INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Objectives`, `Details`, `EndText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `QuestGiverTextWindow`, `QuestGiverTargetName`, `QuestTurnTextWindow`, `QuestTurnTargetName`, `CompletedText`, `VerifiedBuild`) VALUES
(13504, 'frFR', 'Les travailleurs briselances', 'Tuez 10 Travailleurs briselances.', 'Un grand nombre de trolls briselances pillent les ruines au nord et au nord-est. Je les soupçonne de chercher des artéfacts magiques, mais aucun de nos éclaireurs ne signale quoi que ce soit d’intéressant dans ce qu’ils ont fouillé jusqu’ici. Ils cherchent peut-être juste de quoi alimenter leur effort de guerre.$b$BEn tout cas, une chose est sûre, avec moins de travailleurs, leur offensive serait ralentie. Donc, veillez à ce qu’ils aient moins de travailleurs. Entendu ?', '', '', '', '', '', '', '', '', '', 'Retournez voir la sentinelle Tysha Lamelune, aux Ruines de Mathystra.', 0),
(13505, 'frFR', 'Les vestiges des Bien-nés', 'Récupérez 8 Reliques de Bien-né.', 'Des ruines comme celles-ci sont dispersées sur tout Sombrivage. Beaucoup sont hantées par les esprits troublés des Bien-nés. Par courtoisie envers ces âmes maudites, nous n’avons guère fait d’efforts pour nettoyer les ruines de leurs artéfacts, mais face à la nouvelle menace que posent les trolls, ces hésitations s’évaporent.$B$BLorsque vous aiderez les Sentinelles à accomplir leurs objectifs dans les ruines, ramassez tous les artéfacts que vous trouverez et rapportez-les-moi. J’aimerais sauver ce qui peut l’être.', '', '', '', '', '', '', '', '', '', 'Retournez voir Balthule Frappelombre, aux Ruines de Mathystra.', 0),
(13506, 'frFR', 'Des raisons de s\'inquiéter', 'Remettez les Ordres briselances au Lieutenant Morra Brise-Stellaire, aux Ruines de Mathystra.', 'Cela ressemble à des ordres transmis aux surveillants briselances par l’un de leurs supérieurs du camp de guerre des Briselances. Dans l’ensemble, le document n’a pas beaucoup de valeur stratégique, mais quelques lignes attirent votre attention.$B$B« Nous avons capturé une autre espionne elfe de la nuit. Elle a été emmenée au camp pour être torturée. Peut-être nous donnera-t-elle d’autres informations. Ouvrez l’œil au cas où d’autres espions rôderaient. Nous ne pouvons pas nous permettre de voir nos opérations compromises. »$B$BCette information intéressera sûrement le lieutenant.', '', '', '', '', '', '', '', '', '', '', 0),
(13507, 'frFR', 'Privation de personnel', 'Tuez 6 Massacreurs de la Horde et 6 Mystiques briselances.', 'Au nord, les Briselances ont un camp de guerre où ils construisent leurs catapultes. Il est gardé par certains de leurs mystiques, mais je commence à recevoir des rapports selon lesquels on y voit aussi des orcs et des taurens.$B$BJe ne veux pas présumer de ce que cela signifie, mais je veux que vous y alliez et que vous les tuiez avant qu’ils ne puissent organiser d’autres attaques sur nos Sentinelles.', '', '', '', '', '', '', '', '', '', 'Retournez voir la sentinelle Tysha Lamelune, aux Ruines de Mathystra.', 0),
(13508, 'frFR', 'Une réponse rapide', 'Retrouvez les prisonnières elfes de la nuit, au Camp de guerre des Briselances.', 'Nous avons perdu le contact avec l’un de mes éclaireurs il y a environ deux jours. Je la croyais morte, mais il semble qu’elle ait été capturée. Si j’en crois les trolls, ils ont au moins deux prisonnières… L’autre prisonnière serait Alanndarian Chantenuit, une civile qui a quitté le camp contre mon avis, tôt dans la journée d’hier.$B$BLes Briselance ont établi un camp de guerre au nord. Les prisonnières s’y trouvent certainement. Trouvez-les et libérez-les si vous le pouvez.', '', '', '', '', '', '', '', '', '', '', 0),
(13509, 'frFR', 'Fournitures de guerre', 'Détruisez 12 Armes briselances.', 'Les trolls rassemblent leurs troupes et leur matériel dans leur camp de guerre, au nord. Lorsqu’ils se sentiront prêts, ils partiront certainement de là pour attaquer Lor’danel. Nous ne devrions pas avoir trop de mal à disperser cette racaille, mais je n’ai pas envie de prendre de risques inconsidérés.$B$BJe veux que vous pénétriez dans leur camp de guerre et que vous mettiez le feu à leurs piles de fournitures. Cela devrait nous donner un peu de temps avant qu’ils ne puissent lancer une contre-attaque.', '', 'Armes briselances brûlées', '', '', '', '', '', '', '', 'Retournez voir le Lieutenant Morra Brise-Stellaire, aux Ruines de Mathystra.', 0),
(13510, 'frFR', 'Une arrivée providentielle', 'Escortez la sentinelle Aynasha jusqu\'à ce qu\'elle soit en sécurité.', 'C’est bon de vous voir. Des secours sont vraiment les bienvenus, je n’avais aucune envie d’endurer ce qu’ils ont fait subir à Alanndarian,.$B$BAvant d’être capturée, j’ai vu le chef des trolls. Je pensais avoir une occasion parfaite de le tuer, mais il était protégé par une sorte de bouclier magique. Il faut que Morra le sache avant de lancer son attaque, mais d’abord, sortons d’ici.$B$BAidez-moi à aller jusqu’au quai. Je rentrerai à Lor’danel par l’eau, pendant que vous rentrerez voir Morra avec les informations.', 'Escorter la sentinelle Aynasha jusqu\'aux docks', '', '', '', '', '', '', '', '', 'Informez Morra Brise-Stellaire de la situation, aux Ruines de Mathystra.', 0),
(13511, 'frFR', 'Un vœu amer', 'Tuez Rit\'ko, le Tortionnaire Briselance.', 'C’est Morra qui vous envoie ? J’aurais dû l’écouter – j’imagine que c’est juste trop difficile de prendre les trolls au sérieux.$B$B<Alanndarian rit faiblement.>$B$BIl est trop tard pour ça, de toute façon. Nous sommes mortels, désormais… C’est le destin que nous devons subir, d’une manière ou d’une autre. J’ai eu le temps de l’accepter.$B$BJ’ai une requête… tuez le tortionnaire qui m’a fait ça. Ils l’appellent Rit’ko… vous le trouverez par là, avec l’autre prisonnière.$B$B<Alanndarian sourit tant bien que mal, puis fait la grimace et retombe en arrière, terrassée par la douleur.>', '', '', '', '', '', '', '', '', '', 'Informez le Lieutenant Morra Brise-Stellaire de la situation, aux Ruines de Mathystra.', 0),
(13512, 'frFR', 'Frappes stratégiques', 'Tuez Sheya Tissetempête et Lorenth Mandetonnerre.', 'Décapiter la bête ne fonctionne pas si une autre tête lui pousse aussitôt. Avant de tuer leur chef, nous devons nous en prendre aux lieutenants qui pourraient lui succéder. Pour l’instant, ils ne sont pas très bien protégés, vous devriez être capable de les liquider sans trop d’aide.$B$BPrenez cette lance de dryade et traquez-les. Le poison sur sa pointe ralentira leurs incantations. Mes éclaireurs me signalent que l’un d’eux se trouve dans la chambre inondée des ruines, à l’est. L’autre est un peu au-delà des ruines de la tour, au sud-ouest.', '', '', '', '', '', '', '', '', '', 'Retournez voir Morra Brise-Stellaire, aux Ruines de Mathystra.', 0),
(13513, 'frFR', 'Sur le fil', 'Rapportez 6 Amulettes briselances.', 'Je travaillais déjà sur quelque chose pour abattre leurs protections. En nous concentrant sur leurs pouvoirs et avec une touche de magie druidique, nous devrions être capables de pénétrer leurs boucliers.$B$BTrouvez leurs chamans, à l’est et au sud-est, et récupérez leurs amulettes. Je les préparerai et imprégnerai une flèche que vous donnerez à Sandrya Tombelune au moment de l’attaque.', '', '', '', '', '', '', '', '', '', 'Retournez voir Balthule Frappelombre, aux Ruines de Mathystra.', 0),
(13514, 'frFR', 'Le courroux des anciens', 'Utilisez un Protecteur vengeur pour tuer 30 Trolls briselances, et pour détruire 6 Bâtiments briselances.', 'Vous venez vous joindre à l’offensive ? Si vous cherchez Sandrya Tombelune, elle dirige l’attaque contre le chef Briselance, à la caverne au fond de la vallée. Vous pourrez la trouver là-bas.$B$BTant que vous y serez, nous aurons certainement besoin de votre aide pour anéantir le reste de la tribu. Allez-y en compagnie de l’un des protecteurs vengeurs. Veillez à ce que tous les bâtiments soient détruits et à ce qu’aucun troll n’en réchappe. Pas question de les laisser revenir se venger lorsque nous aurons baissé notre garde !', '', 'Trolls de la vallée des Briselances tués', 'Bâtiments briselances détruits', '', '', '', '', '', '', 'Retournez voir Kerlonian Eternombre, dans la vallée des Briselance.', 0),
(13515, 'frFR', 'Mettre un terme à la menace', 'Allez parler à Sandrya Tombelune lorsque vous serez $gprêt:prête; à passer à l’attaque, et aidez-la à tuer Jor\'kil le Faucheur d\'âmes.', 'Leur chef et sa garde sont devant nous. Mes Sentinelles sont prêtes à s’occuper de la garde, nous n’attendions que cette flèche pour sceller le sort du chef.$B$BDites-moi lorsque vous serez $gprêt:prête; à passer à l’attaque. Dès que mes Sentinelles interviendront, je détruirai le bouclier du chef, et nous l’attaquerons ensemble. Frappez vite, frappez fort, et nous chasserons cette menace de nos terres !$B$BJe vous attends. Vos préparatifs terminés, parlez-moi.', '', '', '', '', '', 'Nos relations pacifiques avec les Briselances ont été jetées aux orties, les Briselances doivent donc les y rejoindre.', 'Jor\'kil le Faucheur d\'âmes', '', '', 'Retournez voir la chasseresse Sandrya Tombelune, dans la vallée des Briselances.', 0),
(13518, 'frFR', 'La dernière vague de survivants', 'Retrouvez tout réfugié d\'Auberdine encore vivant.', 'Il est trop tard pour Laird, il ne s’en est pas sorti à temps.$B$BUne dernière vague d’elfes de la nuit a tenté de quitter Auberdine il y a deux heures. Ils étaient restés dans leurs anciennes demeures, espérant les sauver, mais il semble qu’ils aient fini par en être chassés. J’ai peur que beaucoup ne s’en tirent pas mieux que Laird.$B$BVite, allez à l’ouest en longeant la côte, et trouvez tous les survivants que vous pourrez.$B$BOn envoie des Sentinelles et des hippogriffes, mais chaque seconde compte. Nous devons savoir qui a survécu.', '', 'Cerellean Blanchegriffe secouru', 'Gershala Murmenuit secouru', 'Shaldyn secourue', 'Volcor secouru', '', '', '', '', 'Retournez voir la Prêtresse Dentaria, à Lor’danel.', 0),
(13519, 'frFR', 'Le Marteau du crépuscule', 'Tuez le Haut-sectateur Azerynn et 10 Fanatiques du Crépuscule au Campement du crépuscule.', 'Un groupe de sectateurs du Marteau du crépuscule a dressé un camp au sud-ouest. Ils préparent une armée d’élémentaires d’eau pour l’envoyer contre Lor’danel.$B$BLeur chef, le haut-sectateur Azerynn, a passé des pactes avec les Dieux très anciens, des entités ténébreuses qui donnent des pouvoirs sur les éléments à leurs disciples. Allez vous occuper d\'eux, $n, avant qu’il ne soit trop tard.$B$BLe cataclysme a plongé les esprits des éléments dans la confusion… ce n’est qu’une question de temps avant qu’ils n’aient assez d’élémentaires pour percer nos défenses.', '', '', '', '', '', 'Sa mort signifie beaucoup pour nous.', 'Haut-sectateur Azerynn', '', '', 'Retournez voir la sentinelle Lendra à Lor’danel, en Sombrivage.', 0),
(13520, 'frFR', 'Le don des mers', 'Récupérez 16 Muscles de palourdes incrustés.', 'C’est bon de vous revoir. C’est en grande partie grâce à vous que ceux que nous aimons ont pu rejoindre leur foyer, et j’espère bien que vous pourrez nous aider davantage.$B$BIls vont être grièvement blessés, comme Laird l’était. Tous auront marché le long de la côte et subi les attaques des élémentaires. Je fais ce que je peux, mais on dirait que les élémentaires sécrètent une toxine qui empêche les blessés de guérir. Je crois pouvoir préparer un onguent, mais il me faudra les sécrétions des muscles des palourdes de la côte. Pouvez-vous m’en trouver ?', '', '', '', '', '', '', '', '', '', 'Retournez voir la Prêtresse Serendia à Lor\'danel.', 0),
(13521, 'frFR', 'Bigobox 413', 'Récupérez 4 échantillons de Chair de clampant des marées corrompu et amenez-les à la Bigobox 413 pour analyse.', 'Salutations ! J’aide Tharnariun à comprendre ce qui corrompt la faune de la région. J’ai installé des machines sur le terrain. Elles sont capables d’analyser des morceaux d’animaux et d’isoler les sources de corruption possibles. Si vous me trouvez de bons échantillons, nous ne tarderons pas à comprendre ce qui se passe.$B$BLa première machine est la Bigobox 413. Elle est sur la plage, juste à l’est de la ville. J’ai besoin que vous récupériez un peu de chair sur les rampants des marées corrompus que l’on trouve aux alentours. Lorsque ce sera fait, amenez-la à la machine, que je puisse l’analyser.', '', '', '', '', '', '', '', '', '', 'Apportez les échantillons à la Bigobox 413, à la Lisière des brumes.', 0),
(13522, 'frFR', 'Une menace venue des eaux', 'Tuez 8 Projections viles.', 'Certains des survivants de la dernière attaque contre Auberdine tentent de remonter la côte pour se mettre en sécurité. Nous n\'en avons été informés qu\'il y a une heure. J’aurais aimé que nous ayons plus de temps…$B$BÀ l\'ouest, la côte grouille de projections viles, d’infects petits élémentaires d’eau. Si nous voulons que les survivants aient une chance d’atteindre Lor’danel, nous devons leur dégager le passage. Partez tout de suite, et tuez tous les élémentaires que vous verrez.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Forestier Glynda Nal’Shea, à Lor’danel.', 0),
(13523, 'frFR', 'Un pouvoir sur les marées', 'Utilisez l\'Orbe d\'Élune sur la dépouille de 6 Esprits des marées enragés.', 'Ne vous préoccupez pas de moi. Mes blessures sont trop profondes, et la mort viendra bientôt.$B$BTout repose sur vous, désormais… vous devez arrêter le Marteau du crépuscule.$B$BSes membres se sont voués aux Dieux très anciens. Ils leur ont donné pouvoir sur les esprits des eaux agités… mais ce pouvoir ne tient qu’à un fil. À l’aide de cet orbe, canalisez la présence d’Élune lorsque les élémentaires seront au tapis.$B$BUtilisez le pouvoir d’Élune pour bannir définitivement les esprits.', '', 'Esprit des marées apaisé', '', '', '', '', '', '', '', 'Retournez voir la prêtresse de la lune Tharill au Campement du crépuscule.', 0),
(13525, 'frFR', 'Qu\'arrive-t-il aux furbolgs Noirbois ?', 'Parlez à l’Ancien Brolg, au Bastion des Noirbois.', 'Pendant de longues générations, nos ancêtres ont vécu aux côtés des furbolgs Noirbois. Toutefois, depuis peu, nous sommes sans nouvelles de leurs campements dans la forêt profonde. L’un des plus importants, le Bastion des Noirbois, se trouve au sud.$B$BAllez-y et trouvez l’Ancien Brolg. Demandez-lui pourquoi son peuple a rompu le contact, et offrez-lui votre aide, si besoin est.', '', '', '', '', '', '', '', '', '', '', 0),
(13526, 'frFR', 'La patte d\'ours', 'L’Ancien Brolg, du Bastion des Noirbois, a besoin de 8 tiges de Pattes d’ours.', 'Les vils satyres de Gangrebois ont commencé à introduire leurs poisons en Sombrivage, ici même. Leur corruption tue la terre et déforme les créatures qui y vivent. Mon peuple ne fait pas exception.$B$BNotre magie ne suffit pas à faire revenir les malades à la raison, mais il existe une herbe, la patte d’ours, qui fait tomber la fièvre et qui fortifie les faibles. Grâce à elle, nous pourrons peut-être neutraliser l’influence des satyres. Elle pousse dans la nature, autour du village.', '', '', '', '', '', '', '', '', '', '', 0),
(13527, 'frFR', 'Les questions de goût, ça ne se discute pas…', 'Cherchez une carcasse d\'ours à l\'est de la Bigobox 413 et rapportez-en un échantillon.', '<La machine bourdonne pendant un moment avant que la voix de Crackboum ne résonne.>$B$BIntéressant ! La source de la corruption est incontestablement extérieure, ce qui n’est pas une surprise. Il semble qu’ils aient mangé quelque chose de toxique, sans doute un grand mammifère. Un ours, probablement.$B$BExaminez la plage à la recherche d’une carcasse d’ours, voulez-vous ? Peut-être un peu à l’est, un peu à l’intérieur des terres de la plage. Rapportez-moi l’échantillon en ville.', '', '', '', '', '', '', '', '', '', 'Retournez voir Crackboum Tournelevier, à Lor’danel.', 0),
(13528, 'frFR', 'Bigobox 723', 'Rassemblez 6 échantillons de Tripes d’ours des chardons corrompus, et rapportez-les à la Bigobox 723 pour analyse.', 'Nous avons confirmé l’infection sur au moins deux autres espèces animales. En fait, que les crabes aient été contaminés par les ours est une bonne nouvelle, cela veut probablement dire que tout vient d’une seule source. Nous devons nous concentrer sur les ours pour le moment.$B$BLa Bigobox 723 se trouve à l’est, près des chutes d’eau. J’ai un boulot salissant mais nécessaire pour vous : il va falloir que vous déposiez des tripes fraîches d’ours dans la Bigobox pour analyse. Lorsque j’aurai l’information, on verra ce qu’on en fait.', '', '', '', '', '', '', '', '', '', 'Apportez les échantillons à la Bigobox 723, près des chutes.', 0),
(13529, 'frFR', 'La source de la corruption', 'Tuez Zenn Vilsabot et 8 Grells maléfiques au Val de la Bondissante.', 'Je me suis précipité ici dès que j’ai eu les nouvelles de Crackboum. Je sais qui est derrière ce gâchis ! Zenn Vilsabot.$B$BIl est venu ici après que nous l’avons chassé de Teldrassil parce qu’il utilisait la magie de manière perverse. Son genre de corruption n’est pas très apprécié de mon peuple, et on dirait qu’il a été encore plus loin cette fois, peut-être pour se venger.$B$BNous lui avons donné trop de chances de se racheter. Il est temps de mettre un terme à cette menace pour la nature. Tuez Zenn et ses sbires, et revenez me voir à Lor’danel.', '', '', '', '', '', 'La patience et la vertu n’ont qu’un temps. Certaines bornes ne doivent jamais être dépassées, et Zenn en a dépassé plusieurs.', 'Zenn Vilsabot', '', '', 'Retournez voir Tharnariun Soigneflore, à Lor’danel.', 0),
(13537, 'frFR', 'Une envie de mérou', 'Utilisez vos compétences en pêche pour obtenir 4 Mérous de Sombrivage.', 'Entre les balades en bateau et nos efforts de construction, je suis exténué… et affamé. Vous savez ce qui me plairait ? Du poisson. Un délicieux plat de poisson.$B$BSombrivage est connu pour ses mérous. Si vous m’en pêchez quelques-uns, je vous dédommagerai de votre peine.', '', '', '', '', '', '', '', '', '', 'Retournez voir Jonathan Staats, à Lor’danel.', 0),
(13541, 'frFR', '', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(13542, 'frFR', 'Contre le vent', 'Utilisez le Puits de lune des Ruines d\'Auberdine pour détruire 8 jeux de Brassards de cyclone frénétique.', 'Si nous devons reprendre les ruines d’Auberdine aux forces du Marteau du crépuscule, il faut que nous nous débarrassions définitivement des élémentaires invoqués par les sectateurs.$B$BC’est là que vous intervenez.$B$BÉcoutez, je ne m’attends pas à ce que vous repreniez la ville, mais vous pouvez les affaiblir pendant que nous récupérons.$B$BPour venir à bout des cyclones frénétiques, allez à l’ouest, tuez-les, prenez leurs brassards, et placez-les dans le puits de lune. Cela détruira les brassards et empêchera que les élémentaires soient de nouveau invoqués.', '', 'Brassards de cyclone frénétique détruits', '', '', '', '', '', '', '', 'Retournez voir la Sentinelle Selarin au Camp de réfugiés d’Auberdine en Sombrivage.', 0),
(13543, 'frFR', 'Trois marteaux à briser', 'Tuez la Dompteuse de nuages Crin-sauvage, le Maître du vent Tzu-Tzu et le Seigneur du ciel Braax.', 'J’ai survolé les ruines d’Auberdine au cours d’une mission de reconnaissance. Trois sectateurs du Marteau du crépuscule sont responsables des élémentaires qui ont envahi notre ville détruite.$B$BAllez à l’ouest jusqu’aux ruines. Cherchez et abattez la dompteuse de nuages Crin-sauvage, le maître du vent Tzu-Tzu et le seigneur du ciel Braax.$B$BLorsque ce sera fait, la sentinelle Selarin et ses forces auront une chance de reprendre leur foyer.', '', '', '', '', '', '', '', '', '', 'Retournez voir Corvine Aubelune au Camp de réfugiés d’Auberdine en Sombrivage.', 0),
(13544, 'frFR', 'La bénédiction de l\'ours', 'L’Ancien Brolg, du Bastion des Noirbois, veut que vous lui rameniez le Paquet d’herbes bénies.', 'Avant que nous ne puissions utiliser les pattes d’ours pour soigner les malades, le paquet doit être achevé et béni. Vous trouverez un haut-trotteur au nord de ce village. On l’appelle Pied-léger. Je vais avoir besoin de ses plumes de queue pour terminer le paquet d’herbes.$B$BAmenez plumes et herbes jusqu’à l’antique statue d’ours, dans les ruines qui entourent le bosquet des Anciens, un peu au nord de l’endroit où vous verrez Pied-léger.$B$BLorsque vous serez au sanctuaire, combinez les plumes de queue et les pattes d’ours, et recevez la bénédiction de l’esprit-ours.', '', '', '', '', '', '', '', '', '', '', 0),
(13545, 'frFR', 'Purifier les souffrants', 'L’Ancien Brolg veut que vous utilisiez le Paquet d’herbes bénies pour purifier 7 furbolgs du Bastion des Noirbois et que vous tuiez les Esprits de corruption qui leur ont fait perdre la raison.', 'Avec les herbes sacrées et la bénédiction de l’ours, vous pouvez à présent utiliser le paquet d’herbes pour purifier mes frères. La corruption qui sourd de Gangrebois leur a fait perdre la tête. Ils attaquent tous ceux qui s’approchent d’eux. Attendez-vous à ce que les Noirbois malades soient en colère contre vous jusqu’à ce que vous ayez tué les esprits qui les hantent.$B$BRevenez me voir lorsque vous aurez arraché mes frères à leur folie.', '', 'Furbolg noirbois purifié', '', '', '', '', '', '', '', 'Retournez voir l’ancien Brolg au Bastion des Noirbois.', 0),
(13546, 'frFR', 'Le Souilleur', 'L’Ancien Brolg, du Bastion des Noirbois, veut que vous tuiez Sharax le Souilleur.', 'Les satyres Jadefeu de Gangrebois ont trouvé la route de Sombrivage. Ils corrompent nos terres, notre eau, et toutes les créatures qu’ils rencontrent. Vous avez vu ce que cela fait à mon peuple et à son foyer. Si nous ne les chassons pas, nous allons tous connaître ce terrible destin.$B$BSharax le Souilleur vit dans une caverne, à l’est. C’est lui le responsable de toutes les souffrances des Noirbois. Tuez-le, $n, et libérez-nous de son influence. Montrez aux satyres que les Noirbois ne sont pas prêts de se coucher et de se laisser mourir.', '', '', '', '', '', '', '', '', '', '', 0),
(13547, 'frFR', 'Amadouer les esprits', 'Amadouez les esprits de Thundris Tissevent, Elissa Brise-Stellaire, Taldan et Caylais Plumelune.', 'Vos amis du camp de réfugiés n’ont aucune idée du danger imminent que les sectateurs du Marteau du crépuscule ont d’ores et déjà introduit dans ce monde.$B$BPour que vous puissiez l’affronter, il nous faudra l’aide des morts d’Auberdine.$B$BFouillez les ruines de la ville à la recherche des cadavres de Thundris Tissevent, Elissa Brise-Stellaire, Taldan et Caylais Plumelune. Amadouez leurs esprits, faites-les sortir de leurs corps, et revenez me voir en leur compagnie.', '', 'Esprit de Thundris Tissevent amadoué', 'Esprit de la sentinelle Elissa Brise-Stellaire amadoué', 'Esprit de Taldan amadoué', 'Esprit de Caylais Plumelune amadoué', '', '', '', '', 'Retournez voir Yalda aux Ruines d’Auberdine en Sombrivage.', 0),
(13554, 'frFR', 'Un remède dans l\'obscurité', 'Récupérez 6 échantillons d\'Ichor infect sur des créatures du Val de la Bondissante.', '<La machine crache un discours inintelligible avant que vous ne distinguiez à nouveau la voix de Crackboum.>$B$BDes rats de la pénombre ! Ils ont mangé des rats de la pénombre ! Ces sales petites bêtes ne peuvent venir que d\'un seul endroit, une grotte contre la façade de la falaise à l\'est. Trouvez un chemin vers le nord-est, puis cherchez une ouverture sous la cascade.$B$BSoit ces rats de la pénombre ont rencontré quelque chose d\'affreux, soit quelqu\'un répand un agent sur eux - quoi qu\'il en soit, rapportez-moi plusieurs échantillons de ce truc !', '', '', '', '', '', '', '', '', '', 'Retournez voir Crackboum Tournelevier, à Lor’danel.', 0),
(13557, 'frFR', 'Le porte-chance', 'Libérez 8 Ours des chardons non corrompus ou Rats de la pénombre non corrompus des cages du Val de la Bondissante.', 'Cette clé ouvre probablement les cages d’animaux qui sont dispersées dans le val de la Bondissante. Tharnariun apprécierait certainement que vous profitiez de la situation pour libérer une partie des ours des chardons et des rats de la pénombre non corrompus qui y sont toujours prisonniers.', '', 'Animaux non corrompus libérés', '', '', '', '', '', '', '', 'Allez parler à Tharnariun Soigneflore, à Lor’danel.', 0),
(13558, 'frFR', 'L\'appel du tonnerre', 'Utilisez l\'Orbe rituel d\'Aetherion et récupérez l\'Essence d\'Aetherion.', 'Aetherion est presque dans notre monde, mais nous pouvons encore le neutraliser !$B$BAu bout du quai flotte un orbe rituel. Je veux que vous vous en serviez pour compléter le rituel, faisant sortir le seigneur élémentaire de son vortex.$B$BFaites-moi confiance, $n. Les esprits que vous avez libérés et moi-même allons beaucoup l\'affaiblir. Il vous reviendra de l’achever et de sauver les Kaldorei de Sombrivage d’une destruction totale.$B$BRemettez son essence à Corvin Aubelune, au camp de réfugiés, qu’il sache ce que vous avez fait.', '', '', '', '', '', 'Prenez son essence !', 'Aetherion', '', '', 'Retournez voir Corvine Aubelune au Camp de réfugiés d’Auberdine en Sombrivage.', 0),
(13560, 'frFR', 'Un océan pas si profond', 'Gorbold Main-d\'acier à Lor\'danel vous a demandé de parler à Gary pour obtenir de nouvelles instructions.', 'Vous avez l’air $gd’un gars compétent:d’une fille compétente; ! Il y a de nombreuses épaves le long de la côte… anciennes, pour la plupart, mais aussi quelques récentes. Cela fait un moment que j’essaye d’y entrer et d’y récupérer des objets de valeur, mais la région est infestée de murlocs, et ils semblent avoir d’autres projets. J’ai envoyé des tas d’aventuriers, mais aucun n’est jamais revenu.$B$BNon, ne vous inquiétez pas, j’ai retenu la leçon, et ce n’est pas le sort qui vous attend. Nagez plein nord et cherchez Gary. Il vous expliquera le nouveau plan. Vous verrez, c’est tout simple.', '', 'Récupérateur grisebrume', '', '', '', '', '', '', '', 'Retournez voir Gorbold Main-d\'acier à Lor\'danel.', 0),
(13561, 'frFR', 'Du réconfort pour les Bien-nés', 'Tuez 6 Bien-nées maudites et 6 Bien-nés frémissants.', 'Je suis venue à Bashal’Aran pour donner le repos aux esprits troublés des Bien-nés, mais ma main hésite au moment de frapper chaque coup. Je vous serais très reconnaissante si vous acceptiez de m’aider.', '', '', '', '', '', '', '', '', '', 'Retournez voir Arya Clairautomne, sur la route à l’extérieur de Bashal’Aran.', 0),
(13562, 'frFR', 'La dernière flamme de Bashal\'Aran', 'Éteignez la Dernière flamme de Bashal\'Aran.', 'En des temps comme ceux-ci, nous devons nous arrêter et réfléchir à notre mode de vie. Nous sommes mortels, dorénavant, et même si nous voulons croire que c’est injuste, nous méritons notre nouvelle place en ce monde.$B$BBashal’Aran, qui se trouve le long de la route, au sud, était une grande ville du temps de nos ancêtres. C’est aujourd’hui la résidence de leurs fantômes maudits. Nous avons longtemps espéré les sauver, et nous sauver nous-mêmes, mais nous les avons laissés souffrir trop longtemps. Il est temps d’éteindre la dernière flamme de Bashal’Aran.', 'Éteindre la dernière flamme de Bashal\'Aran', '', '', '', '', '', '', '', '', 'Retournez voir le Forestier Glynda Nal’Shea, à Lor’danel.', 0),
(13563, 'frFR', 'Un amour éternel', 'Libérez l\'esprit d\'Anaya Coursaurore et rapportez son pendentif.', 'Je vous témoigne la plus grande gratitude pour nous avoir sauvés. Je pourrais me considérer chanceux, mais ma bien-aimée, Anaya, est morte depuis longtemps. Je suis seul et profondément troublé, et malheureusement, je dois vous demander à nouveau votre aide.$B$BAlors que j\'errais dans les bois de Sombrivage après mon sauvetage, je me suis retrouvé dans les ruines de Bashal\'Aran... où j\'ai vu l\'esprit hanté de ma bien-aimée.$b$bElle doit être libérée, mais je n\'ai pas le cœur à le faire. Son esprit doit être détruit.', '', '', '', '', '', 'Pour certains, accepter la mort est le comble de la difficulté.', 'Anaya Coursaurore', '', '', 'Rapportez le Pendentif d’Anaya à Cerellean Blanchegriffe, à Lor’danel.', 0),
(13564, 'frFR', 'Un compagnon perdu', 'Retrouvez Griffe-sinistre.', 'Aidez-moi, s’il vous plaît… Je peux à peine m’asseoir.$B$BMon ami, un ours nommé Griffe-sinistre, a disparu. Je l’avais envoyé en avant, pour que les Sentinelles sachent que nous arrivions avant que nous ne quittions Auberdine, mais il n’est jamais arrivé. J’ai senti que quelque chose n’allait pas lorsque nous sommes partis, mais avec l’évacuation, je n’ai pas creusé la question.$B$BS’il est blessé, il sera sans doute allé se réfugier au fourré Flétri, au nord d’Auberdine. C’est au sud d’ici, à l’écart de la route. Ramenez-le-moi… C’est ma seule famille.', 'Griffe-sinistre trouvé', '', '', '', '', '', '', '', '', '', 0),
(13565, 'frFR', 'De lointains cousins', 'Utilisez la Racine pétrifiée pour lever 6 Ents flétris et tuer le chef naga, Dame Janira.', 'La violence aveugle n’est pas dans notre nature, et nous ne l’approuvons pas. Toutefois, il arrive qu’éviter une bataille ait des conséquences trop tangibles pour être ignorées. C’est le cas avec les nagas.$B$BLorsque la terre s’est fracassée, des ruines ont émergé à l’est. Jadis, elles abritaient des loyalistes à la reine Azshara. On dirait qu’ils sont revenus à la recherche de quelque chose.$B$BPrenez cette racine pétrifiée. Vous pourrez l’utiliser sur leurs corps pour invoquer des ents qui vous aideront. Occupez-vous des nagas et de leur chef, vite !', '', '', 'Ents flétris appelés', '', '', 'Les nagas cherchent à récupérer un objet de valeur des ruines de Sombrivage, mais ils ont outrepassé la patience des elfes de la nuit depuis longtemps. Leur intrusion leur en cuira.', 'Dame Janira', '', '', 'Retournez voir Séraphine au fourré Flétri.', 0),
(13566, 'frFR', 'Des matériaux pour le rituel', 'Récupérez 3 Moustaches de traquelune, 3 Touffes de poils de biche tachetée et 3 Fourrures d\'ours des chardons.', 'Pendant que nous nous occupons de Griffe-sinistre, je souhaite que vous vous procuriez quelques objets dont j’aurai besoin pour le rituel. Surtout, pas de violence !$B$BIl me faut des moustaches de traquelunes – arrachez-les aux traquelunes endormis et éloignez-vous rapidement.$B$BJ’ai aussi besoin de poils de biche. Je vous conseille d’éviter les cerfs.$B$BEnfin, il me faudra de la fourrure prise sur les ours qui vivent au bord de l’eau, au nord-est. Attendez qu’ils aient pêché un poisson, prélevez l’échantillon rapidement, et fuyez avant qu’ils aient fini leur repas.$B$BJe vous demande encore une fois de ne leur faire aucun mal.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Gardien Karithus, au Fourré Flétri.', 0),
(13567, 'frFR', 'L\'esprit du cerf', 'Le Gardien Karithus vous a demandé de recevoir la bénédiction du Grand esprit cerf.', 'Dans ces bois vivent trois grands esprits, celui du Cerf, celui de l’Ours des chardons et celui du Traquelune. Tous trois sont des alliés puissants, mais vous ne pouvez en choisir qu’un.$B$BSi vous souhaitez vous allier avec l’esprit du Grand cerf, prenez cet encens et allez dans les bois, juste au nord de Bashal’Aran. Méditez devant le grand esprit tout en brûlant l’encens sur le sol, entre lui et vous. Acceptez son épreuve et gagnez sa bénédiction. Si vous réussissez, revenez me voir.', '', '', '', '', '', '', '', '', '', '', 0),
(13568, 'frFR', 'L\'esprit du traquelune', 'Le Gardien Karithus vous a demandé de recevoir la bénédiction du Grand esprit traquelune.', 'Dans ces bois vivent trois grands esprits, celui du Cerf, celui de l’Ours des chardons et celui du Traquelune. Tous trois sont des alliés puissants, mais vous ne pouvez en choisir qu’un.$B$BSi vous souhaitez vous allier avec l’esprit du Grand traquelune, prenez cet encens et allez juste au sud des ruines de Lornesta. Méditez devant le grand esprit tout en brûlant l’encens sur le sol, entre lui et vous. Acceptez son épreuve et gagnez sa bénédiction. Si vous réussissez, revenez me voir.', '', '', '', '', '', '', '', '', '', '', 0),
(13569, 'frFR', 'Le lien rituel', 'Respirez l\'encens devant le gardien Karithus, puis choisissez la bénédiction du Grand esprit cerf, du Grand esprit ours des chardons ou du Grand esprit traquelune.$B$BSongez que vous ne pouvez recevoir la bénédiction que d\'un esprit à la fois, donc choisissez judicieusement.', 'Je vais m’occuper de Griffe-sinistre jusqu’à ce qu’il ait récupéré. Il ne devrait pas tarder à être capable de rentrer. Pendant que j’attends, j’ai une autre tâche pour vous… Hum… En fait, c’est plutôt une faveur que je vous fais, si vous êtes capable de le reconnaître.$B$BLes grands esprits de la faune errent autour de nous. Ils attendent, et espèrent que quelqu’un sera capable de les aider à arrêter la destruction. Ils sont avec nous en ce moment même. Grâce aux matériaux que vous m’avez amenés, je vais vous permettre de les voir. Parlez aux esprits, choisissez-en un, et revenez me voir avec sa bénédiction.', 'Recevoir la bénédiction d\'un grand esprit animal', '', '', '', '', '', '', '', '', 'Retournez voir le Gardien Karithus, au Fourré Flétri.', 0),
(13570, 'frFR', 'Souvenirs d\'Auberdine', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(13572, 'frFR', 'Les braseros jadefeu', 'Gren poil-semé, au Bastion des Noirbois, veut que vous détruisiez 8 Braseros jadefeu.', 'Les satyres de Gangrebois déversent leur haine et leur corruption sur nos terres. Ils ont envoyé Sharax le Souilleur pour s’emparer de la région que nous autres Noirbois considérons comme notre foyer.$B$BIl empoisonne la terre, les animaux et les plantes. De plus, il a installé des braseros jadefeu dans le village. Ils l’aident à contrôler notre peuple. Les détruire ne suffira pas à l’arrêter, mais cela aidera à atténuer son influence, le temps que vous travailliez avec l’ancien Brolg à libérer nos frères.', '', '', '', '', '', '', '', '', '', 'Retournez auprès de Gren Poil-Semé au Bastion des Noirbois.', 0),
(13573, 'frFR', 'Le retour de Malfurion', 'Cherchez Malfurion Hurlorage dans l\'Œil du Vortex, au sud-est du Camp de réfugiés, à Sombrivage.', 'Nous n’avons appris le réveil de Malfurion que très récemment, juste avant que le Cataclysme ne nous frappe.$B$BImmédiatement après avoir repris conscience, il a lancé un avertissement énigmatique expliquant que la terre se briserait en deux si rien n\'était fait, et que toutes les ondes de choc convergeraient vers Sombrivage.$B$BIl aurait ensuite été aperçu se dirigeant non loin d\'ici. J\'ai été envoyé pour le retrouver, mais il a fallu aider les réfugiés…$B$BPeut-être pourriez-vous le chercher ? Il devrait être au sud-est.', '', '', '', '', '', '', '', '', '', '', 0),
(13575, 'frFR', 'Cette terre est dans leurs veines', 'Parlez à l\'Ancien Brunepatte au Camp des Noirbois, au sud-ouest de l\'Œil du Vortex.', 'Si nous devons stabiliser les forces de la nature, nous allons avoir besoin de toute l’aide possible. Les furbolgs de la tribu Noirbois vivent dans la région depuis longtemps, et ils ont des liens profonds avec la terre.$B$BLeur plus vieux chaman, l’ancien Brunepatte, exerce un grand pouvoir sur les éléments. Son soutien nous serait précieux. Voyez si vous pouvez l’obtenir.', '', '', '', '', '', '', '', '', '', '', 0),
(13576, 'frFR', 'Assistance mutuelle', 'Utilisez le Totem apaisant pour absorber les restes de 8 Élémentaires de feu déliés.', 'La plupart des nôtres ont succombé à la folie ou à la corruption. On dirait que nous n’avons pas d’autre choix que de nous rallier à vous, $r. Vous pouvez compter sur notre aide… une fois que vous nous aurez prouvé que nous pouvons compter sur la vôtre.$B$BComme vous pouvez le voir, mon peuple a un petit problème avec des élémentaires de feu. Aidez-nous à les combattre, et utilisez ce totem sur leurs restes incandescents.$B$BNous allons les renvoyer d’où ils viennent… que cela leur plaise ou non.', '', 'Élémentaire de feu délié absorbé', '', '', '', '', '', '', '', 'Retournez voir l’ancien Brunepatte au Camp des Noirbois, en Sombrivage.', 0),
(13577, 'frFR', 'Le dernier Indomptable', 'Parlez à Aroom à la Tanière des Frôlelunes, au nord de l\'Œil du Vortex.', 'Il fut un temps où les indomptables abondaient en Sombrivage. Mais leurs liens avec la terre sont si profonds que le cataclysme qui a ravagé la région les a également décimés.$B$BAroom est le dernier de sa tribu, un ancien puissant, étroitement lié à Élune. Son aide nous sera nécessaire pour guérir cette terre. Vous le trouverez au nord, à la tanière des Frôlelunes.', '', '', '', '', '', '', '', '', '', '', 0),
(13578, 'frFR', 'L\'adieu d\'Aroom', 'Obtenez 8 Plumes d\'indomptables tués.', '<La créature hulule tristement lorsqu’elle vous adresse la parole.>$B$BAroom dernier de la tribu…$B$BAutres sans repos… Besoin bûcher funéraire. Ramenez à Aroom plumes des autres… donnez-leur le repos.$B$BAprès, Aroom aider vous.', '', '', '', '', '', '', '', '', '', 'Retournez voir Aroom à la Tanière des Frôlelunes, en Sombrivage.', 0),
(13579, 'frFR', 'Le protecteur d\'Ameth\'Aran', 'Parlez à Selenn dans les Ruines d\'Ameth\'Aran.', 'Rien ne guérira la terre plus vite que la force de ceux qui l’habitent. Nous autres elfes de la nuit avons de la chance… Certains de nos plus proches alliés sont tout à la fois la terre et ses habitants.$B$BSelenn, l’Ancien de la Guerre, a été chargé de veiller sur les ruines d’Ameth’Aran, au sud. Allez le voir et demandez-lui de vous aider.', '', '', '', '', '', '', '', '', '', '', 0),
(13580, 'frFR', 'Apaiser les éléments', 'Placez le Totem apaisant énergisé au sommet du récif près de la grève Flamboyante et protégez-le jusqu’à ce que le Rituel d’apaisement soit terminé.', 'Leurs esprits incandescents sont désormais enfermés dans le totem. Rendez-vous au sommet du récif déchiqueté, près de la grève Flamboyante, et posez le totem sur le sol.$B$BSes énergies apaisantes se répandront petit à petit sur les élémentaires, jusqu’à ce que leur rage laisse la place à la paix.$B$BVous devrez protéger le totem, car le feu réagit mal aux rituels d’apaisement.', '', 'Rituel d\'apaisement terminé', '', '', '', '', '', '', '', 'Retournez voir l’ancien Brunepatte au Camp des Noirbois, en Sombrivage.', 0),
(13581, 'frFR', 'Le serment des Noirbois', 'Retournez voir Malfurion Hurlorage dans l\'Œil du Vortex.', 'Cela ne va pas se produire immédiatement, mais la colère des élémentaires finira par s’apaiser. Mon peuple vivra pour continuer à se battre.$B$BJe vais venir. Je vous aiderai de toutes mes forces, vous et Malfurion.', '', '', '', '', '', '', '', '', '', '', 0),
(13582, 'frFR', 'Le feu d\'Élune', 'Obtenez la Torche d\'Élune auprès de Horoo le Gardien des flammes.', 'Nous faut flamme spéciale pour rituel. Nous faut feu d’Élune.$B$BEsprit d’Horoo erre à l’est. Horoo porte torche d’Élune. Donne repos aux esprits.$B$BAroom dit merci.', '', '', '', '', '', '', '', '', '', 'Retournez voir Aroom dans la Tanière des Frôlelunes, en Sombrivage.', 0),
(13583, 'frFR', 'Le serment de l\'Indomptable', 'Retournez voir Malfurion Hurlorage dans l\'Œil du Vortex.', 'Indomptables avec Élune. Aroom dette envers vous.$B$BAroom vous aider. Retournez voir Malfurion. Je viens bientôt.', '', '', '', '', '', '', '', '', '', '', 0),
(13584, 'frFR', 'Calmer la terre', 'Tuez 8 Élémentaires de terre enragés.', 'J’ai des responsabilités, et je ne peux pas les négliger en abandonnant mon poste maintenant, avec tant d’élémentaires hors de contrôle dans les ruines.$B$BCommençons par nous occuper d’eux avant de voir si nous pouvons aider Malfurion. Qu’en dites-vous, petit être ?', '', '', '', '', '', '', '', '', '', 'Retournez voir Selenn dans les Ruines d’Ameth’Aran, en Sombrivage.', 0),
(13585, 'frFR', 'Le serment de protéger', 'Parlez à Malfurion Hurlorage dans l\'Œil du Vortex, à Sombrivage.', 'J’ai rempli mon devoir ici de mon mieux. Prévenez Malfurion que je vais le rejoindre très bientôt.$B$BJe vous souhaite bonne chance, $n. Nous allons tous en avoir besoin.', '', '', '', '', '', '', '', '', '', '', 0),
(13586, 'frFR', 'Le Rêve d\'émeraude', 'Franchissez le Portail cauchemardesque à la Caverne de Brise-terre, et parlez à Thessera.', 'Nos efforts pour contenir la destruction ne semblent pas suffisants. J’ai peur qu’il ne nous faille de l’aide hors du monde de l’éveil.$B$BLes sectateurs du Crépuscule qui infestent la caverne de Brise-terre, à l’est, ont ouvert un portail vers une région du Rêve d’émeraude infestée de cauchemars. Ils y détiennent Thessera, un dragon vert.$B$BPassez le portail cauchemardesque et libérez-la. Elle fera une alliée redoutable.', '', '', '', '', '', '', '', '', '', '', 0),
(13587, 'frFR', 'Cauchemar éveillé', 'Obtenez le Parchemin émeraude du Gardien cauchemardesque, à l’intérieur de la Caverne de Brise-terre.', 'Malfurion dit vrai, petit être. La faille qui menace de déchirer Sombrivage en deux menace aussi la séparation entre ce monde et le vôtre.$B$BLaissez-moi vous aider comme je le peux, sans quoi, d’autres failles entre nos mondes amplifieront la destruction qui prend place de part et d’autre.$B$BPour commencer, vous devez défaire mes entraves en récupérant le parchemin émeraude sur le gardien cauchemardesque qui erre dans les salles du dessous.', '', '', '', '', '', '', '', '', '', 'Retournez voir Thessera dans la Caverne de Brise-terre, en Sombrivage.', 0),
(13588, 'frFR', 'L\'œil de toutes les tempêtes', 'Chevauchez Thessera pour vaincre 12 Chevaucheurs du Crépuscule et détruisez le Portail du Crépuscule.', 'Des cavaliers du Crépuscule tournent dans le ciel au-dessus du vortex. Je crains que ce ne soit leur magie qui ait réduit à néant nos efforts pour contenir les forces cataclysmiques.$B$BPrenez l’air avec Thessera. Détruisez les cavaliers et le portail par où ils sont venus.', '', '', '', '', '', '', '', '', '', 'Retournez voir Malfurion Hurlorage à l’Œil du Vortex, en Sombrivage.', 0),
(13589, 'frFR', 'Les envahisseurs briselances', 'Faites votre rapport au lieutenant Morra Brise-Stellaire, aux Ruines de Mathystra.', 'La terre et les éléments se retournent contre nous. Comme si cela ne suffisait pas, on dirait que quelque chose excite les trolls qui vivent au nord-est. Ils sont sur le sentier de la guerre. Je ne sais pas ce qu’ils veulent au juste, mais ils ont déjà attaqué plusieurs de nos éclaireurs. Ils ont aussi assiégé les sectateurs de la tour d’Althalaxx.$B$BNous avons envoyé un groupe de nos meilleures Sentinelles pour les neutraliser. Si vous voulez bien vous rendre aux ruines, au nord-est, et vous joindre à elles, je suis sûre qu\'elles seront ravies d\'avoir une paire de mains supplémentaire.', '', '', '', '', '', '', '', '', '', '', 0),
(13590, 'frFR', 'La ligne de front', 'Faites votre rapport à la chasseresse Sandrya Tombelune, dans la Vallée des Briselances.', 'Leurs forces sont affaiblies, leurs fournitures détruites, et leurs sous-chefs morts. Il est temps de porter le fer chez eux et d’affronter leur chef. Je me demande encore ce qui a provoqué cette soudaine agression, mais nous trouverons peut-être des réponses sur le pas de leur porte.$B$BPrenez cette flèche préparée par Balthule et présentez-vous à Sandrya Tombelune, dans les profondeurs de la vallée des Briselances, pour vous joindre à l’offensive. Je vous conseille de faire le trajet sur le dos de l’un de nos sabres-de-nuit. À pied, c’est trop dangereux.', '', '', '', '', '', '', '', '', '', '', 0),
(13591, 'frFR', 'Des liens inquiétants', 'Apportez la Lettre de Hurlenfer au forestier Glynda Nal\'Shea, à Lor\'danel.', 'La lettre de Garrosh Hurlenfer confirme les soupçons que nous avions conçus au cours de l’offensive contre les Briselances. La présence de Réprouvés aux ruines de la tour, et celle de matériel et de guerriers de la Horde au camp de guerre des Briselances… Tout cela n’était qu’un début. Garrosh en personne a contacté les Briselances pour les pousser à l’offensive contre Lor’danel. Il semble clair qu’il a aussi l’intention d’attaquer depuis le sud.$B$BSi nous voulons que les elfes de la nuit soient prêts, Glynda Nal’Shea doit en être informée.', '', '', '', '', '', '', '', '', '', '', 0),
(13594, 'frFR', 'N\'oubliez pas la Horde', 'Tuez 10 membres de la Horde au Repaire de Bathran.', 'Evenar et les autres apprentis ne sont peut-être pas très utiles au combat, mais vous, vous avez l’air de savoir vous défendre. La racaille de la Horde, par-delà la route à l’est du repaire de Bathran, a besoin d’une bonne leçon.$B$BLe nouveau seigneur de guerre Garrosh Hurlenfer et ses troupes préparent un mauvais coup. Ça vous dirait d’aller leur apprendre la vie ?$B$BJe viendrais bien avec vous, mais j’ai pour mission de rester ici et de protéger les apprentis d’Orendil, et c’est exactement ce que je vais faire !', '', 'Membres de la Horde abattus au Repaire de Bathran', '', '', '', '', '', '', '', 'Retournez voir la Sentinelle Shyela à la Retraite d\'Orendil, en Orneval.', 0),
(13595, 'frFR', 'Tel est pris qui croyait prendre', 'Récupérez une Bouteille braisière et lancez-la sur le Cadavre de Bathran pour le brûler.', 'Ces créatures… les monstres de cette prétendue Horde… m’ont abattu dans la fleur de l’âge et se servent de mes cheveux pour mener à bien leurs plans maléfiques.$b$bM’aiderez-vous à mettre un terme à cette mascarade, $gpetit:petite; $r ?$B$BJ’ai entendu leurs herboristes parler d’une certaine bouteille braisière qui se trouve sur leur table, plus loin. Si vous pouviez vous emparer de cette bouteille au contenu mystérieux et la jeter sur mon cadavre, au nord-est, il prendrait feu et mes cheveux ne pousseraient plus.$B$BJe suis déjà mort et c’est un bien petit prix à payer pour les arrêter.', '', 'Cadavre de Bathran brûlé', '', '', '', '', '', '', '', 'Retournez voir Bathran, au Repaire de Bathran, en Orneval.', 0),
(13596, 'frFR', 'Les plans du Crépuscule', 'Récupérez 6 Plans du Crépuscule au Campement du crépuscule.', 'Nous ne sommes pas totalement au fait des intentions des sectateurs du Marteau du crépuscule qui se sont établis au sud-ouest. Nous redoutons une attaque sur Lor’danel, mais leurs motivations sont peut-être plus complexes que cela.$B$BJ’ai besoin que vous alliez au campement du crépuscule et que vous mettiez la main sur leurs plans. Dépêchez-vous, $n, nous n’avons peut-être pas beaucoup de temps.', '', '', '', '', '', '', '', '', '', 'Retournez voir la sentinelle Lendra à Lor’danel, en Sombrivage.', 0),
(13597, 'frFR', 'L\'esprit de l\'Ours des chardons', 'Le Gardien Karithus vous a demandé de recevoir la Bénédiction du Grand esprit ours des chardons.', 'Dans ces bois vivent trois grands esprits, celui du Cerf, celui de l’Ours des chardons et celui du Traquelune. Tous trois sont des alliés puissants, mais vous ne pouvez en choisir qu’un.$B$BSi vous souhaitez vous allier avec l’esprit du Grand ours des chardons, prenez cet encens et allez à la caverne, juste à l’est du grand tourbillon. Méditez devant le grand esprit tout en brûlant l’encens sur le sol, entre lui et vous. Acceptez son épreuve et gagnez sa bénédiction. Si vous réussissez, revenez me voir.', '', '', '', '', '', '', '', '', '', '', 0),
(13598, 'frFR', 'Des remèdes déplaisants', 'Récupérez 6 Amanites fumantes.', 'Grâce à ma magie de guérison, je ne doute pas que Griffe-sinistre finira par se remettre. Je n’en dirai pas autant des braconniers qui l’ont attaqué. Cependant, j’aurai l’usage d’un onguent pour l’aider à cicatriser et atténuer la douleur.$B$BVous trouverez les ruines de Lornesta à l’est. Parmi les pierres écroulées poussent des amanites fumantes, qui prospèrent dans cet environnement humide. Rapportez-m’en quelques-unes, que je puisse préparer un onguent pour notre ami.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Gardien Karithus, au Fourré Flétri.', 0),
(13599, 'frFR', 'Le retour de Griffe-sinistre', 'Retournez voir Volcor et Griffe-sinistre à Lor\'danel.', 'Maintenant que le lien est complet, la bénédiction agit. Elle rendra certainement vos voyages à travers cette région plus facile.$B$BGriffe-sinistre est complètement guéri. Avant que je puisse faire quoi que ce soit pour l’arrêter, il a filé vers Lor’danel. J’imagine que cela veut dire qu’il est temps que vous partiez.$B$BVous rencontrer a été un grand plaisir. Adieu pour le moment. Transmettez mes meilleurs souvenirs à Volcor et à Griffe-sinistre.', '', '', '', '', '', '', '', '', '', '', 0),
(13601, 'frFR', 'Au secours des réfugiés', 'La Sentinelle Lendra, à Lor\'danel, vous demande d\'aller parler à la Prêtresse Alinya, au Camp de réfugiés.', 'Par Élune ! On dirait qu’un grand nombre de gens que nous pensions morts dans l’attaque contre l’ancienne Auberdine sont encore en vie, réfugiés dans un camp à l’extérieur des ruines de la ville.$B$BLes sectateurs du campement du crépuscule ont essayé de s’en prendre à eux. Heureusement, vous avez attaqué leur position.$B$BAllez voir la prêtresse Alinya au camp de réfugiés, à l’est de l’ancienne Auberdine, loin au sud d’ici.', '', '', '', '', '', '', '', '', '', '', 0),
(13602, 'frFR', 'Gang de nagas', 'Tuez 15 Nagas irequeue, sur la Grève de Zoram.', 'Un mal étrange rôde sur la côte, à l’ouest.$b$bLa grève de Zoram est le tombeau de la ville maudite du même nom, détruite lors de la Fracture, et engloutie par les eaux. Les elfes de la nuit n’ont pu accéder à cette ville isolée pendant des années. Cette ville isolée, et presque oubliée.$b$bAujourd’hui, les nagas sont de retour, et nous ignorons leurs intentions. Mais finalement, peu importe, nous devons tuer ces monstres et les renvoyer dans les profondeurs de la mer !', '', 'Nagas irequeue tués', '', '', '', '', '', '', '', 'Retournez voir Shindrell Prestefeu, au Camp de Brassenoire, en Orneval.', 0),
(13605, 'frFR', 'Le dernier réfugié', 'Escortez l\'Archéologue Hollee jusqu\'à ce qu\'elle soit en sécurité.', 'Il y a eu ce gros tremblement de terre et tout est devenu noir. Lorsque j’ai repris conscience, j’étais prisonnière ici. L’endroit grouille d’élémentaires d’air !$b$BJ’espère que tout le monde va bien. Ces vermines du Marteau du crépuscule n’ont pas intérêt à s’en être pris à mes amis !$B$BVite, $c ! Prenez n’importe quel machin pointu pour crocheter le verrou de mes fers. Ensemble, nous devrions pouvoir rentrer au camp de réfugiés.', 'Archéologue Hollee conduite en lieu sûr', '', '', '', '', '', '', '', '', 'Retournez voir Elisa Main-d’acier au Camp de réfugiés d’Auberdine en Sombrivage.', 0),
(13612, 'frFR', 'La défense de Mor\'shan', 'Kadrak, au Rempart de Mor\'shan, vous demande de tuer 5 Tirailleurs d\'Orneval et 5 Francs-archers d\'Orneval.', 'Lok’tar, $r !$b$bLa campagne est finalement lancée ! Orneval sera bientôt aux mains de la Horde.$b$bComme prévu, notre offensive force l’ennemi à éprouver nos défenses à chaque position.$b$bIci, à Mor’shan, nous avons balayé leur attaque ! Mais l’étau se resserre, et ils n’auront d’autre choix que de continuer à nous repousser ici.$b$bFouillez la région, $c. Partez à la recherche de survivants elfes de la nuit et abattez-les avant qu’ils ne se regroupent pour lancer une nouvelle attaque !', '', 'Tirailleurs d\'Orneval tués', 'Franc-archers d\'Orneval tués', '', '', '', '', '', '', 'Parlez à Kadrak au Rempart de Mor\'shan.', 0),
(13613, 'frFR', 'Sauvez les blessés', 'Utilisez l\'Onguent médicinal sur 5 Défenseurs de Mor\'shan blessés.', 'Notre armée résiste héroïquement aux assauts de l’ennemi, $c.$b$bMais il faut s’occuper des blessés, et nombre d’entre eux se trouvent encore sur le champ de bataille.$b$bJ’ai préparé un onguent qui devrait leur redonner assez d’énergie pour revenir au rempart et recevoir des soins. Je vous en prie, appliquez-le à tous ceux qui pourraient en avoir besoin, avant qu’ils ne meurent.', '', 'Défenseurs de Mor\'shan blessés secourus', '', '', '', '', '', '', '', 'Parlez à Dinah au Rempart de Mor\'shan.', 0),
(13615, 'frFR', 'Des carquois vides', 'Truun, au Rempart de Mor\'shan, vous demande de récupérer 10 Flèches utilisables dans la région du Lac Tombeciel.', 'Salutations, $c, et bienvenue au Rempart.$b$bLa situation peut vous sembler un peu chaotique ici, mais ne vous inquiétez pas. Kadrak a les choses en main. Pas un seul elfe n’a pu franchir nos lignes !$b$bPendant que vous êtes là… J’attends une livraison de ravitaillement d’Orgrimmar d’un jour à l’autre, mais nos sentinelles viennent à manquer de flèches.$b$bSi vous m’en rapportez, je vous dédommagerai.', '', '', '', '', '', '', '', '', '', '', 0),
(13617, 'frFR', 'En route pour la grève', 'Allez parler à Talen, au Camp de Brassenoire en Orneval.', '$n, je pense que vos talents exceptionnels pourraient servir à l\'un de mes amis. Il se nomme Talen, et c’est un archéologue, en quelque sorte. Depuis peu, il est fasciné par les bouleversements de la ville antique de Zoram et par les trésors qu\'elle renferme.$B$BSi vous voulez l\'aider, vous le trouverez au camp de Brassenoire, au bout du chemin vers l’ouest.', '', '', '', '', '', '', '', '', '', '', 0),
(13618, 'frFR', 'Trouvez Gorat !', 'Kadrak, au Rempart de Mor\'shan, vous demande de fouiller la région du Lac Tombeciel pour retrouver Gorat.', 'Gorat est l’un des assassins les plus expérimentés de la Horde.$B$BLa seule mention de son nom remplit d’effroi le cœur des héros les plus vaillants de l’Alliance.$b$bC’est quelqu’un de fiable, de farouchement loyal et, jusqu’à présent, de ponctuel.$b$bQuelque chose ne tourne pas rond, $c.$b$bGorat avait pour mission de trouver et d’éliminer l’elfe responsable de cette attaque sur le rempart.$b$bIl devrait être dans la région du lac Tombeciel.$b$bRetrouvez-le !', '', '', '', '', '', '', '', '', '', '', 0),
(13619, 'frFR', 'Le dernier rapport', 'Gorat vous demande de rapporter la Fiole de sang de Gorat à Kadrak, au Rempart de Mor\'shan.', '<Gorat tousse violemment, éprouvant d’immenses difficultés à parler.>$b$bC’était… une embuscade…$b$bNous… retournions au rempart. Tous… morts…$b$bNous avons… trouvé leur chef…$b$b<Gorat remplit péniblement une fiole du sang qui s’écoule de ses blessures.>$b$bMes hommes… doivent être vengés… Apportez ça… à Kadrak…$b$bIl saura quoi faire…$b$b<Gorat rend son dernier souffle.>', '', '', '', '', '', '', '', '', '', '', 0),
(13620, 'frFR', 'Livraison expresse', 'Kadrak vous a demandé de rapporter la Fiole de sang de Gorat à Dinah au Rempart de Mor\'shan.', 'Gorat est le membre le plus loyal que la Horde ait jamais connu. Aucune mission ne lui a jamais résisté, et il refuse de considérer celle-ci comme son premier échec.$b$bGorat vous a demandé de livrer cette fiole dans un but bien précis. Dinah est la fille d\'un chaman révéré, et est bien plus puissante qu’elle n’y paraît. Apportez-lui la fiole en espérant qu’il ne soit pas trop tard.', '', '', '', '', '', '', '', '', '', '', 0),
(13621, 'frFR', 'La vengeance de Gorat', 'Utilisez le Sang imprégné de Gorat sur le Cadavre de Gorat, puis battez le Capitaine Elendilad.', 'Aujourd’hui, la chance nous sourit, $r.$b$bLe sang de Gorat était assez frais et j’ai donc pu réaliser un rituel très particulier que je connais depuis l’enfance.$b$bAppliquez ce sang imprégné sur le cadavre de Gorat pour invoquer son esprit errant. Écoutez-le, faites ce qu’il vous demandera, puis revenez informer Kadrak de la situation.$b$bPuissent les esprits vous protéger, mon $gami:amie;.', '', 'Capitaine Elendilad tué', '', '', '', '', '', '', '', 'Parlez à Kadrak au Campement de Mor\'shan.', 0),
(13623, 'frFR', 'Une livraison pour Orendil', 'Apportez le Sac de cheveux de Bathran à Orendil Largefeuille au Poste de Maestra, en Orneval.', 'Hâtez-vous, $n. Je vais mettre les cheveux de Bathran dans ce sac, mais vous devez l’apporter à mon maître, Orendil Largefeuille. Vous le trouverez au poste de Maestra, au sud, au bout de la route sur la gauche.$B$BMais prenez garde, les rapports que nous avons reçus indiquent que le poste est assiégé par la Horde !', '', '', '', '', '', '', '', '', '', '', 0),
(13624, 'frFR', 'Votre propre escouade', 'Utilisez une escouade de Sentinelles du Poste de Maestra pour détruire 3 Casseurs d\'Orneval et pour tuer 10 Envahisseurs de la Horde.', 'J’espère vraiment que vous êtes ici pour nous aider, $c. La situation est aussi critique qu’elle y paraît. En bref, nous sommes submergés !$B$BMes sentinelles et moi sommes la dernière ligne de défense contre la Horde. Mais nous n’allons pas nous laisser faire sans passer à l’attaque. Êtes-vous $gprêt:prête; à relever le défi ?$B$BJe peux mettre à votre disposition une petite escouade de sentinelles. Placez-les à bonne distance, et je suis certaine que leurs flèches magiques détruiront ces casseurs et ces envahisseurs.$B$BRevenez me voir s’il vous faut des renforts.', '', 'Casseurs d\'Orneval détruits', 'Envahisseurs de la Horde tués', '', '', '', '', '', '', 'Retournez voir la Sentinelle Onaeya au Poste de Maestra, en Orneval.', 0),
(13626, 'frFR', 'Le respect envers les morts', 'Récupérez le Marteau sacré de Feero et le Livre de prières du Purificateur.', 'Deux humains se trouvaient là : Feero Main-de-fer et Delgren le Purificateur. Ils appartenaient à une organisation sacrée appelée l’Aube d’argent. Tous deux sont tombés au combat en défendant le poste lors de la première attaque de la Horde.$B$BJe vais vous prêter la cape magique que Cénarius m’a offerte. Elle me permet de me déplacer sans être vue.$B$BRetrouvez leurs deux cadavres et rapportez-moi le marteau de Feero et le livre de prières de Delgren. Le cadavre de Feero se trouve dans la cour et celui de Delgren est au sommet de la tour.$B$BPrenez garde, le démoniste qui s’y trouve pourra vous voir.', '', '', '', '', '', '', '', '', '', 'Retournez voir la Sentinelle Onaeya au Poste de Maestra, en Orneval.', 0),
(13628, 'frFR', 'Z\'avez du bois ?', 'Truun vous a demandé de chevaucher Brutusk jusqu\'au camp de travail chanteguerre.$b$bAdressez-vous à Kadrak pour obtenir les rênes de Kadrak et chevaucher Brutusk.', 'Kadrak vient de recevoir de nouveaux ordres pour nos troupes. J’ai cru comprendre que nous devions commencer à lancer des offensives sur Orneval !$b$bJe ne suis pas du tout préparé pour ces assauts, et ma livraison d’Orgrimmar n’est pas encore arrivée. Je dois improviser…$b$bJe vais certainement avoir besoin de vous, $c.$b$bAllez voir Kadrak et demandez-lui de vous prêter les rênes de Brutusk. Le kodo vous transportera au camp de travail chanteguerre. Quand vous y serez, cherchez Gorka et demandez-lui de charger mes bûches sur le kodo.', '', 'Chevaucher Brutusk', '', '', '', '', '', '', '', 'Allez voir Gorka au Camp de travail chanteguerre, en Orneval.', 0),
(13630, 'frFR', 'Raison de plus !', 'Désactivez les Pierres de lune bleue, verte et rouge.', 'Les furbolgs sont descendus des hauteurs pour investir les ruines d’Ordil’Aran, au nord. Je crois qu’ils ont été attirés par les découvertes des sectateurs morts : trois pierres de lune.$B$BLiladris Ondelune vous conseillerait de résoudre le problème des furbolgs d’une manière radicale, et je ne la contredirais pas, mais, en ce qui me concerne, je préférerais que vous alliez dans ces ruines pour désactiver les pierres de lune.', '', 'Pierre de lune bleue désactivée', 'Pierre de lune verte désactivée', 'Pierre de lune rouge désactivée', '', '', '', '', '', 'Retournez voir la prêtresse de la lune Maestra, du Poste de Maestra en Orneval.', 0),
(13632, 'frFR', 'À l\'arrière-garde', 'Tuez 10 Furbolgs aux Ruines d\'Ordil\'Aran.', 'La prêtresse de la lune a un plan pour empêcher les furbolgs de descendre des hauteurs et de nous envahir. Ceux qui se trouvent déjà dans les ruines m’inquiètent davantage ; certains d’entre eux se regroupent juste devant le poste.$B$BAussi déplaisant que cela puisse paraître, je dois vous demander d’aller au nord dans les ruines d’Ordil’Aran et d’abattre les furbolgs. Nous ne pouvons pas combattre sur deux fronts à la fois !$B$BMerci, $c.', '', 'Furbolgs des Ruines d’Ordil’Aran abattus', '', '', '', '', '', '', '', 'Retournez voir Liladris Ondelune au Poste de Maestra, en Orneval.', 0),
(13635, 'frFR', 'Rapport sur la porte sud', 'Remettez le Rapport de situation du pilote Martèlepied au Capitaine Rudagite, dans la Vallée des Rois.', 'Nous devons envoyer un rapport de situation aux montagnards de la vallée des Rois.$b$bJ’imagine que de toute façon, c’est votre prochaine étape, non ? Vous voulez bien leur remettre le rapport de ma part ? Vous n’avez qu’à prendre le tunnel à l’est et vous présenter au poste de garde. Remettez-le en mains propres au capitaine Rudagite.', '', '', '', '', '', '', '', '', '', '', 0),
(13636, 'frFR', 'Les ordres des Foudrepiques', 'Remettez les Ordres des Foudrepiques au Montagnard foudrepique, au Poste d’Algaz.', 'Je dois transmettre des ordres au montagnard foudrepique, qui se trouve au poste d’Algaz. Si ça ne vous dérange pas, il vous suffit de suivre la route vers le nord-ouest et vous finirez par apercevoir le fortin principal.$b$bSi vous acceptez de l’aider à régler ses problèmes, nous vous récompenserons pour cela aussi.', '', '', '', '', '', '', '', '', '', '', 0),
(13639, 'frFR', 'Approvisionnement du site de fouilles', 'Trouvez Huldar, Miran et Saean.', 'Baguefer possède un site de fouilles au sud-est et a dû y envoyer une sacrée quantité d’explosifs de la Ligue pour les excavations. Huldar, Miran et Saean viennent à peine de partir avec le dernier chargement et ont probablement besoin d’aide.$b$bIls ne peuvent pas être bien loin, aussi forts soient-ils. Leur progression est ralentie à cause de tous ces tonneaux.$b$bIls ont emprunté la route habituelle pour atteindre le site, celle qui quitte la ville par le sud et qui longe le bord du loch. Rattrapez-les et filez-leur un coup de main, vous voulez bien ?', 'Trouver Huldar, Miran et Saean', '', '', '', '', '', '', '', '', '', 0),
(13640, 'frFR', 'Gestion des ressources', 'Convainquez des Péons démoralisés de se remettre au travail et de rassembler 5 fagots de Bois fraîchement coupé.', 'Alors comme ça, Truun a besoin de bois ? En temps normal, je pourrais lui en fournir, mais pas aujourd’hui.$b$bLa collecte de bois est devenue dangereuse à cause des attaques incessantes des elfes. Les seuls péons qu’il me reste sont réticents à l’idée d’aller s’aventurer dans les bois.$b$bVous voulez du bois ? Alors allez convaincre les péons de travailler.$b$bEt protégez-les ! Je ne peux plus me permettre d’en perdre un seul !', '', '', '', '', '', '', '', '', '', 'Allez voir Gorka au Camp de travail chanteguerre, en Orneval.', 0),
(13642, 'frFR', 'Bain de lumière', 'Créez une Décoction baignée de lumière.', 'La décoction n’est pas encore tout à fait terminée, elle doit être baignée par la lumière d’Élune avant que nous envisagions de la donner à l’enfant.$B$BIl existe un endroit bien connu, juste à l’ouest du lac Falathim, où la lumière lunaire de la déesse rayonne jusqu’au sol, nuit et jour. Je vous en supplie, $n, pour le bien de Relara, prenez la décoction et imprégnez-la de la radiance d’Élune.$B$BMais prenez garde, la région du lac abrite désormais des choses étranges, et j’ai bien peur que l’endroit ne soit plus sûr.', '', '', '', '', '', '', '', '', '', 'Retournez voir Orendil Largefeuille au Poste de Maestra, en Orneval.', 0),
(13644, 'frFR', 'Tuer le messager', 'Tuez le Messager Aphotic.', 'Quand j’ai senti ces… choses… surgir de la terre, je les ai renvoyées d’où elles venaient. J’ai découvert le cadavre de votre ami et je l’ai traîné aussi loin que mes pauvres articulations me l’ont permis. C’est tout ce que je peux faire pour repousser ces vrilles infâmes.$B$BJe sais qui est à l’œuvre derrière tout cela. Il se fait appeler le messager Aphotic : je suis sûr que vous avez entendu ses hurlements, venant du sud.$B$BMes pouvoirs magiques ne peuvent pas atteindre le messager, mais vous pourriez aller vous en occuper. Si vous l’osez…', '', '', '', '', '', 'Renvoyez cette vile créature dans les profondeurs d\'où elle vient.', 'Messager Aphotic', '', '', 'Retournez voir le Gardien Sagecœur, du lac Falathim en Orneval.', 0),
(13645, 'frFR', 'Raene Mène-loup', 'Apportez la Gemme luminescente à Raene Mène-loup, à Astranaar, en Orneval.', 'J\'aimerais vous demander de remettre la gemme en mains propres à Raene Mène-loup. Aux dernières nouvelles, elle était toujours à Astranaar, au sud-est.$B$BAu moins la route est-elle encore relativement sûre jusque là-bas, il vous suffira de la suivre. Bien sûr, si vous préférez, je crois que la sentinelle Avana serait prête à vous confier l\'un de ses sabres-de-nuit pour que votre voyage soit plus rapide.$B$BQuel que soit votre choix, mes vœux vous accompagnent, $n. Puissent nos chemins se croiser à nouveau.', '', '', '', '', '', '', '', '', '', '', 0),
(13646, 'frFR', 'Destination Astranaar', 'Allez voir la Sentinelle Luara à Astranaar, en Orneval.', 'Vous nous avez été d\'une grande aide, $n. Sans vous, nous aurions déjà été rayés de la carte.$B$BCe serait pour moi un plaisir de mettre à votre disposition l\'un de mes sabres-de-nuit pour chevaucher jusqu\'à Astranaar et vers le sud-est. Je suis sûre que vous avez des affaires très importantes à mener là-bas.$B$BJe considérerais cela comme une grande faveur si à votre arrivée vous vouliez bien parler à ma sœur, la sentinelle Luara, pour lui dire que je vais bien.$B$BParlez-moi à nouveau quand vous serez $gprêt:prête; à partir, et chaque fois que vous aurez besoin d\'une monture, elle sera à vous.', '', '', '', '', '', '', '', '', '', '', 0),
(13647, 'frFR', 'Bienvenue chez les chasseurs', 'Parlez à Marek Cœur-de-fer au Pavillon des Pérégrins.', 'Eh bien, vous touchez vraiment votre bille, pour ce qui est de la bagarre.$b$bVous savez, il y a un genre de pavillon de chasse loin à l’est, au-delà des excavations de Baguefer. Vous devriez bien vous entendre avec les chasseurs qui s’y trouvent. Pourquoi vous ne leur rendriez pas une petite visite ? Peut-être qu’ils auront des besognes intéressantes à vous confier ?', '', '', '', '', '', '', '', '', '', '', 0),
(13648, 'frFR', 'AVIS DE RECHERCHE : l\'espion Sombrefer', 'Tuez Gorick Siffle-breuvage.', 'Un espion sombrefer s’est infiltré dans la ville et a volé des documents aux dirigeants de la Ligue des explorateurs. Maintenant, il se cache quelque part aux alentours. La dernière fois qu’on l’a vu, il se trouvait au sommet de la colline, au sud de la ville.$b$bUne coquette récompense ira à celui qui amènera cet espion devant la justice mort ou vif, et plutôt mort que vif.', '', '', '', '', '', 'Trouvez ce crétin et tuez-le !', 'Gorick Siffle-breuvage', '', '', 'Retournez auprès du Magistrat Courtnez à Thelsamar, au Loch Modan.', 0),
(13650, 'frFR', 'Pas touche à la marchandise !', 'Inspectez les Artéfacts du Géant renversé, de la Femme lourdement vêtue et de la Tablette brisée.', 'Nous avons découvert des antiquités époustouflantes, sur ce site. Je doute qu’elles soient toutes authentiques, mais elles ont quand même un intérêt historique potentiel.$b$bMalheureusement, quand les troggs ont envahi le site, nous avons perdu l’accès à trois de nos trouvailles les plus précieuses. Je crains que les troggs ne les aient volées ou abîmées en notre absence.$b$bSi vous allez au site d’excavations, retrouvez le géant renversé, la femme lourdement vêtue et la tablette brisée, et assurez-vous qu’ils soient intacts.', '', 'Artéfact de la Tablette brisée inspecté', 'Artéfact du géant renversé inspecté', 'Artéfact de la femme lourdement vêtue inspecté', '', '', '', '', '', 'Retournez auprès du Prospecteur Baguefer aux Excavations de Baguefer dans le Loch Modan.', 0),
(13651, 'frFR', 'De l’huile de coude', 'Gorka, du Camp de travail chanteguerre, vous a demandé de récupérer 5 extraits d’Huile naturelle sur les Gelées pourrissantes d’Orneval.', 'Vous avez votre bois, mais ces envahisseurs elfes empêchent votre kodo de revenir au rempart de Mor’shan.$b$bNe vous inquiétez pas, j’ai envoyé un messager à Bois-brisé pour demander de l’aide. Les elfes ne devraient pas tarder à débarrasser le plancher.$b$bEn attendant, vous pourriez peut-être nous rendre un service ? La rouille ne nous permet plus d’utiliser nos déchiqueteurs. Avec un peu d’huile, ils seront comme neufs.$b$bCelle des gelées pourrissantes, juste au nord d’ici, conviendra parfaitement.', '', '', '', '', '', '', '', '', '', 'Allez voir Gorka au Camp de bûcherons Chanteguerre.', 0),
(13653, 'frFR', 'Crise à Bois-Brisé', 'Gorka vous demande de l\'accompagner au Rempart de Mor\'shan et de faire votre rapport à Kadrak.$b$bAllez la voir quand vous serez $gprêt:prête; à partir.', 'Bois-Brisé n’enverra aucun renfort.$b$bLes elfes ont lancé une attaque massive sur notre bastion et ils ont encerclé l’endroit !$b$bNous devons informer Kadrak de la situation ou mourir au combat !$b$bLe bois que vous avez ramassé a été chargé sur votre kodo. Prévenez-moi quand vous serez $gprêt:prête; et nous forcerons les lignes ennemies.', '', 'Gorka accompagnée au Rempart de Mor\'shan', '', '', '', '', '', '', '', 'Présentez-vous à Kadrak au Rempart de Mor\'shan.', 0),
(13655, 'frFR', 'Document de la Ligue des explorateurs (2 sur 6)', 'Rapportez le Document de la Ligue des explorateurs à Torren Gueule-carrée à Thelsamar.', 'Le document porte l’en-tête de la Ligue des explorateurs et ressemble à une liste de tous les sites de fouilles potentiels dans le loch Modan. Des traînées de suie sur le document vous donnent à penser qu’il a dû être dérobé par les espions sombrefer présents dans la région.$b$bVous vous rappelez avoir entendu quelque chose à propos de documents volés dans le bâtiment de la Ligue des explorateurs, à Thelsamar.', '', '', '', '', '', '', '', '', '', '', 0),
(13656, 'frFR', 'Document de la Ligue des explorateurs (1 sur 6)', 'Rapportez le Document de la Ligue des explorateurs à Torren Gueule-carrée à Thelsamar.', 'Le document porte l’en-tête de la Ligue des explorateurs et contient des informations détaillées sur les créatures indigènes du loch Modan. Des traînées de suie sur le document vous donnent à penser qu’il a dû être dérobé par les espions sombrefer présents dans la région.$b$bVous vous rappelez avoir entendu quelque chose à propos de documents volés dans le bâtiment de la Ligue des explorateurs, à Thelsamar.', '', '', '', '', '', '', '', '', '', '', 0),
(13657, 'frFR', 'Document de la Ligue des explorateurs (3 sur 6)', 'Rapportez le Document de la Ligue des explorateurs à Torren Gueule-carrée à Thelsamar.', 'Le document porte l’en-tête de la Ligue des explorateurs et contient une chronique de tous les lieux dignes d’intérêt au loch Modan. Des traînées de suie sur le document vous donnent à penser qu’il a dû être dérobé par les espions sombrefer présents dans la région.$b$bVous vous rappelez avoir entendu quelque chose à propos de documents volés dans le bâtiment de la Ligue des explorateurs, à Thelsamar.', '', '', '', '', '', '', '', '', '', '', 0),
(13658, 'frFR', 'Document de la Ligue des explorateurs (4 sur 6)', 'Rapportez le Document de la Ligue des explorateurs à Torren Gueule-carrée à Thelsamar.', 'Le document porte l’en-tête de la Ligue des explorateurs et ressemble à une carte détaillée des routes commerciales de la ligue arrivant et partant du loch Modan. Des traînées de suie sur le document vous donnent à penser qu’il a dû être dérobé par les espions sombrefer présents dans la région.$b$bVous vous rappelez avoir entendu quelque chose à propos de documents volés dans le bâtiment de la Ligue des explorateurs, à Thelsamar.', '', '', '', '', '', '', '', '', '', '', 0),
(13659, 'frFR', 'Document de la Ligue des explorateurs (6 sur 6)', 'Rapportez le Document de la Ligue des explorateurs à Torren Gueule-carrée à Thelsamar.', 'Le document porte l’en-tête de la Ligue des explorateurs et se révèle être une liste décrivant par le détail les diverses menaces pesant sur le loch Modan. Des traînées de suie sur le document vous donnent à penser qu’il a dû être dérobé par les espions sombrefer présents dans la région.$b$bVous vous rappelez avoir entendu quelque chose à propos de documents volés dans le bâtiment de la Ligue des explorateurs, à Thelsamar.', '', '', '', '', '', '', '', '', '', '', 0),
(13660, 'frFR', 'Document de la Ligue des explorateurs (5 sur 6)', 'Rapportez le Document de la Ligue des explorateurs à Torren Gueule-carrée à Thelsamar.', 'Le document porte l’en-tête de la Ligue des explorateurs et contient une liste de tous les artéfacts exhumés par les travailleurs de Baguefer dans la région sud-est du loch Modan. Des traînées de suie sur le document vous donnent à penser qu’il a dû être dérobé par les espions sombrefer présents dans la région.$b$bVous vous rappelez avoir entendu quelque chose à propos de documents volés dans le bâtiment de la Ligue des explorateurs, à Thelsamar.', '', '', '', '', '', '', '', '', '', '', 0),
(13661, 'frFR', 'Notre appréciation la plus sincère', '', 'Vous avez retrouvé tous nos documents ! Nous ne vous remercierons jamais assez… Nous étions presque résignés à abandonner leur recherche et à accepter que les Sombrefers puissent en tirer parti. C’est rassurant de savoir qu’ils continueront à attaquer à l’aveuglette pour un certain temps encore.$b$bPour vous récompenser de tous vos efforts, j’aimerais vous offrir quelque chose de notre part à tous. Un artéfact, en fait… une antiquité que nous avons découverte lors de nos fouilles. Vous avez l’estime de toute la Ligue des explorateurs.', '', '', '', '', '', '', '', '', '', '', 0),
(13683, 'frFR', 'Arrêter les rituels', 'Dérangez 8 Gemmes de rituel.', 'J’ai appris la mort de la sœur d’Illiyana. Je comprends son désir de vengeance. Et puisque vous êtes là pour l’aider, je me demandais si vous pouviez en profiter pour nous rendre un service ?$B$BVous avez certainement déjà aperçu les satyres de Satyrnaar et de Xavian en plein rituel. Je pense qu’ils réalisent ces rituels pour corrompre tous les elfes de la nuit qu’ils capturent et les transformer en satyres. Nous aussi, les draeneï, résistons mal à la magie corrompue.$B$BAuriez-vous l’amabilité de profiter de l’occasion pour déranger leurs gemmes de rituel quand vous y serez ?', '', 'Gemmes de rituel dérangées', '', '', '', '', '', '', '', 'Retournez voir l\'Anachorète Buurq au Chant des forêts, en Orneval.', 0),
(13698, 'frFR', 'C’est de la bombe !', 'Utilisez un Déchiqueteur chanteguerre pour détruire 8 Tonneaux d’explosifs.', 'Ça m’ennuie de vous renvoyer là-bas, mais d’après ce que vous avez vu, on ne peut pas les laisser utiliser tout leur stock d’explosifs !$B$BC’est trop dangereux d’essayer de les détruire vous-même, mais si vous pouviez voler l’un de leurs déchiqueteurs, je suis certaine qu’il serait assez résistant pour supporter les explosions.$B$BQuand vous aurez détruit leurs explosifs, revenez ici avec le déchiqueteur. Il n’y a aucune raison de le leur laisser.', '', 'Explosifs de la Horde détruits', 'Ramener le Déchiqueteur chanteguerre', '', '', '', '', '', '', 'Retournez voir la Sentinelle Luciel Murmétoile, au Camp de bûcherons Chanteguerre, en Orneval.', 0),
(13712, 'frFR', 'Prêter main-forte', 'Parlez à Kadrak au Rempart de Mor\'shan et accompagnez-le au Poste de Bois-Brisé.', 'Vous êtes $gréquisitionné:réquisitionnée; d’office, $n.$b$bJe ne peux me séparer de personne d’autre, et nous ne pouvons pas nous permettre de laisser Bois-Brisé aux mains de l’ennemi.$b$bPréparez-vous, et revenez me parler quand vous serez $gprêt:prête;.', '', 'Siège du Poste de Bois-Brisé levé', '', '', '', '', '', '', '', 'Parlez à Kadrak au Poste de Bois-Brisé.', 0),
(13730, 'frFR', 'Jouer avec le gangrefeu', 'Draaka, à Bois-Brisé, vous demande de remplir la Boîte renforcée de 7 Gangrefeux de la Colline Gangrefeu.', '<Draaka se penche pour vous parler.>$b$bÉcoutez… Avant que vous ne disiez quoi que ce soit, je SAIS que nous ne devons pas interférer avec les énergies démoniaques…$b$bMais regardez autour de vous ! Nous sommes désespérés, $c.$b$bDe toute manière, nous allons probablement mourir ici. Nous ferions tout aussi bien de partir en beauté dans le feu de la gloire !$b$bAlors… vous acceptez ?$b$bPrenez cette boîte et allez au sud-est jusqu’à la colline Gangrefeu. Utilisez-la près des plaques de gangrefeu et rapportez-la-moi quand vous l’aurez remplie.$b$bOh, et il serait préférable de n’en parler à personne…', '', 'Gangrefeux siphonnés', '', '', '', 'Si je ne tire pas fréquemment, ça commence à brûler. Vous désirez ?', 'Draaka', 'Si je ne tire pas fréquemment, ça commence à brûler. Vous désirez ?', 'Draaka', 'Allez voir Draaka au Poste de Bois-Brisé.', 0),
(13751, 'frFR', 'Ne le dis à personne !', 'Draaka, à Bois-Brisé, vous demande d\'apporter la Note écrite à la hâte à Durak.', 'Parfait !$b$bLa Horde va montrer aux elfes de quoi elle est capable quand on la met au pied du mur.$b$bÉcoutez, $n. Vous ne devez rien dire à personne !$b$bVol’jin appréciera sûrement notre initiative quand il verra le résultat final, mais si nous nous faisons prendre avant nos corps iront se balancer au bout d’une corde !$b$b<Draaka vous tend une note écrite à la hâte.>$b$bApportez ça à Durak. Vous le trouverez dans les mines derrière moi, juste au nord. Il vous donnera de nouvelles instructions.', '', '', '', '', '', 'Quoi que vous fassiez, ne lisez pas cette note.', 'Draaka', '', '', 'Remettez la Note écrite à la hâte à Durak au Poste de Bois-Brisé.', 0),
(13766, 'frFR', 'Il faut qu’une porte soit ouverte ou fermée !', 'Noueux, du Camp de bûcherons Chanteguerre, vous a demandé d’utiliser le Rameau de Noueux pour fermer 10 Portes démoniaques.', 'Je sens l’arrivée d’autres démons sur notre monde, à travers la terre. Ils seront bientôt trop nombreux et nous serons submergés, sans l’espoir de pouvoir les repousser.$b$bPrenez ce morceau de moi, puis retournez au canyon et à la crête de la Malechute, au sud de la colline Gangrefeu. Visez une porte démoniaque avec ce rameau, et concentrez-vous. Je l’ai imprégné de l’essence de vie de la forêt, il refermera la porte.', '', 'Portes démoniaques fermées', '', '', '', '', '', '', '', 'Retournez voir Noueux au Camp de bûcherons Chanteguerre, en Orneval.', 0),
(13792, 'frFR', 'Le Marchombre', 'Parlez à Gaivan Marchombre, il fait les cent pas à l\'extérieur de l\'entrée du Refuge des saisons de Dor\'danil en Orneval.', 'Maintenant que les portes démoniaques ont été détruites, la forêt doit retrouver son pouvoir. Il faut récupérer son cœur !$B$BGaivan Marchombre, un puissant druide de la Griffe, s’en est allé au sud-ouest, en passant par la colline Gangrefeu, jusqu’au refuge des saisons de Dor\'danil. Ici repose le cœur de la forêt. Il est enfoui profondément sous terre, gardé par les druides d’Orneval.$B$BTrouvez Gaivan et dites-lui de quoi il retourne, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(13796, 'frFR', 'Le cœur de la forêt', 'Récupérez le Cœur de la forêt.', 'Vous devez apporter à tout prix le cœur de la forêt à Noueux !$B$BIl se trouve dans les profondeurs du refuge des saisons de Dor’danil, corrompu par la Horde. Seul Noueux peut le purifier.$B$BVous allez avoir besoin du pouvoir de la nature pour pouvoir le déplacer. Récupérez assez d’esprits non corrompus sur les druides et gardiens disjoints pour les transformer en un pouvoir de la nature.$B$BBonne chance, $n !', '', '', '', '', '', '', '', '', '', 'Retournez voir Noueux au Camp de bûcherons Chanteguerre, en Orneval.', 0),
(13797, 'frFR', 'Des tâches ingrates', 'Fouillez les piles de Débris récents pour trouver 10 Morceaux de minerai.', 'Draaka a besoin d’un aimant à sorts : quelque chose qui attirerait ses projectiles démoniaques.$b$b<Durak esquisse un sourire narquois.>$b$bIl se trouve que je connais une méthode qui pourrait servir nos desseins.$b$bFouillez les mines à la recherche de morceaux de minerai gros comme mon poing, pendant que je prépare un enchantement… très particulier.', '', '', '', '', '', '', '', '', '', 'Retournez voir Durak à la Mine de Bois-Brisé, en Orneval.', 0),
(13798, 'frFR', 'La pluie de destruction', 'Utilisez le Minerai maudit afin de marquer des cibles pour Draaka. Vous devez vaincre 30 Elfes de la nuit et 5 Anciens déchaînés de cette manière.$b$bParlez à Durak pour obtenir à nouveau un Déguisement de diablotin.', 'Vous êtes $garrivé:arrivée; juste à temps, $c. Les elfes viennent de lancer une autre attaque !$b$bPrenez ce minerai maudit et utilisez-le depuis les tours de guet pour marquer des cibles à l’intention de Draaka. Ses projectiles frapperont votre cible et exploseront en gangreflammes magiques, détruisant tous les ennemis proches.$b$bCertaines personnes nourrissent de forts préjugés contre l\'utilisation de la magie démoniaque. Ces reproches ne sont pas justifiés, mais ils existent. C\'est pour cela que je vais vous transformer en diablotin pendant la durée de la mission pour qu’on ne puisse pas vous identifier.', '', 'Attaquants elfes abattus', 'Anciens déchaînés abattus', '', '', '', '', '', '', 'Sous forme de diablotin, parlez à Durak à la Mine de Bois-Brisé.', 0),
(13801, 'frFR', 'La nuit des elfes morts-vivants', 'Tuer 15 Elfes de la nuit fantomatiques de n\'importe quelle variété au Refuge des saisons de Dor’danil.', 'V-Vous avez entendu ? Des fantômes ! Je les déteste !$b$bLeurs hurlements terrifiants proviennent du refuge des saisons, au sud. Ahhh ! Faites-les taire !!$b$bJe vous en prie, $gjeune homme:jeune fille;, je paierai cher pour que ces voix sortent de ma tête !', '', 'Elfes de la nuit fantomatiques tués', '', '', '', '', '', '', '', 'Allez voir Pixel au Poste de Bois-Brisé.', 0),
(13803, 'frFR', 'Le sang des faibles', 'Kadrak vous demande d’apporter la Hache imprégnée de sang à Durak, au poste de Bois-Brisé.', 'Nous savions que les elfes n’abandonneraient pas sans se battre, mais personne ne s’attendait à ce qu’ils assiègent Bois-Brisé…$b$bIl est temps qu’ils paient pour ce qu’ils ont fait !$b$bTout près, l’ennemi cache au refuge des saisons de Dor’danil un bien précieux : le cœur de la forêt.$b$bQuelqu’un doit le trouver et le corrompre.$b$bEt cette personne, c’est vous, $n.$b$bMais d’abord, apportez ma hache à Durak, ici dans les mines. Il se servira du sang de nos ennemis.', '', '', '', '', '', '', '', '', '', 'Remettez la Hache imprégnée de sang à Durak au Poste de Bois-Brisé.', 0),
(13805, 'frFR', 'Transpercez leur cœur !', 'Durak vous demande d\'utiliser le Sang corrompu des Kaldorei sur le Cœur de la forêt.', 'Voilà…$b$bLe sang des Kaldorei déchus a été transformé. On peut désormais l’utiliser sur le cœur de la forêt pour le corrompre. Il se trouve au refuge des saisons de Dor’danil.$b$bLa relique sacrée de ces elfes arrogants va se retourner contre eux. Quelle tragédie !$b$b<Durak éclate d’un rire cruel.>$b$bLe refuge des saisons est niché dans les collines, au sud-est. L’un de mes diablotins a laissé une traînée de sang qui part de l’entrée du refuge et qui mène au cœur.$b$bHâtez-vous ! Kadrak n’est probablement pas d’humeur patiente.$b$bAllez, au boulot, $c !', '', 'Cœur de la forêt corrompu', '', '', '', '', '', '', '', 'Présentez-vous à Kadrak au Poste de Bois-Brisé.', 0),
(13806, 'frFR', 'Les faunes et la flore', 'Locke Okarr, de Bois-Brisé, vous a demandé de fermer 12 Portails des satyres, à Satyrnaar et à Xavian.', 'Écoutez, $c, je sais que l’attaque de Bois-Brisé monopolise l’attention de tout le monde. Mais si nous négligeons les portails des satyres, à la fin de cette bataille, nous en verrons naître une autre bien plus importante.$b$b<Locke lit l’incompréhension sur votre visage.>$b$bVous n’avez pas entendu parler de ces portails ?$b$bAu nord-est, dans les régions de Satyrnaar et de Xavian, les satyres tentent d’invoquer des démons pour gonfler leurs rangs.$b$bNous devons absolument fermer ces portails, et peu importent les obstacles que nous rencontrerons !', '', 'Portails démoniaques fermés', '', '', '', '', '', '', '', '', 0),
(13808, 'frFR', 'Mission improbable', 'Kadrak vous demande de répandre la Poudre du signal secret sur le Brasero fumant depuis Satyrnaar.', 'J’ai une mission très particulière à confier à $gun:une; $c bien $géquipé:équipée; et $gexpérimenté:expérimentée;. Je ne peux me séparer de personne d’autre, alors je crois que je vais devoir me rabattre sur vous…$b$bL’ennemi a pris d’assaut le camp de bûcherons Chanteguerre et l’a coupé du reste de nos troupes. Une grande diplomate elfe de sang en route pour Orgrimmar y est retenue prisonnière.$b$bVous devez la libérer.$b$bPrenez la route au nord-est et versez cette poudre sur le brasero fumant pour invoquer notre agent. Faites tout ce qu’il vous demandera.$b$bRompez !', '', '', '', '', '', '', '', '', '', 'Allez voir Krokk au Brasero fumant devant Satyrnaar.', 0),
(13815, 'frFR', 'De quel bois on se chauffe', 'Krokk vous a demandé d’utiliser la Hache de Bois-Brisé pour abattre les Chênes d’Orneval du Camp de bûcherons Chanteguerre.$b$bSi vous perdez votre Poudre du signal secret, adressez-vous à Kadrak, à Bois-Brisé.', 'Comme vous le savez, nous devons escorter une diplomate, et la faire sortir du camp de bûcherons assiégé pour la mettre en sécurité.$b$bÉtant donné la situation actuelle, c’est tout simplement impossible. Les elfes ont posté des archers devant toutes les entrées du camp.$b$bNous devons d’abord faire une diversion et détourner leur attention.$b$bMon idée est simple. Prenez cette hache et allez abattre leurs arbres chéris qu’ils font pousser dans la région.$b$bQuand vous en aurez terminé, utilisez cette poudre pour m’envoyer un signal et me prévenir.', '', 'Chênes d’Orneval abattus', '', '', '', '', '', '', '', 'Présentez-vous à Krokk au Brasero fumant.', 0),
(13831, 'frFR', 'Une troublante prescription', 'Remettez les Notes de l’apothicaire à Tharnariun Soigneflore à Lor’danel.', 'C’est un laboratoire d’apothicaire rudimentaire et visiblement installé à la hâte, couvert de notes gribouillées et de potions puantes. On dirait que les Réprouvés aussi travaillaient sur l’œuvre de Vilsabot. Vous ramassez en vitesse les notes qui vous semblent les plus importantes et vous préparez à détruire le matériel avant d’aller prévenir Soigneflore de votre découverte.', '', '', '', '', '', '', '', '', '', 'Remettez les Notes de l’apothicaire à Tharnariun Soigneflore à Lor’danel, en Sombrivage.', 0),
(13841, 'frFR', 'Toutes mes confuses', 'Draaka vous demande d’apporter sa Lettre d’explication à Vol’jin, à Orgrimmar.', 'C’est probablement la fin… Je n’ai peut-être pas réfléchi à mes actes comme je l’aurais dû…$b$bLa bonne nouvelle, c’est que nous avons repoussé une attaque qui aurait causé la perte de Bois-Brisé. Prions pour que Vol’jin le voie aussi de cette manière.$b$bJe vais certainement être convoquée à Orgrimmar pour répondre de mes actes.$b$bS’il vous plaît, $n, allez-y et remettez-lui cette lettre.$b$bFaites votre possible pour qu’il ne soit pas trop dur envers moi.', '', '', '', '', '', 'En espérant qu\'il fera preuve d\'un peu de pitié.', 'Draaka', '', '', '', 0),
(13842, 'frFR', 'Prenez-lui la tête !', 'Parlez à Durak à la Mine de Bois-Brisé.', 'Je sens que ce Durak, il cache bien son jeu. Le pouvoir démoniaque est dangereux, même le sorcier bien entraîné il peut tomber sous le charme de sa corruption. \n\nJe ne lui fais pas confiance, $n.\n\nVous allez trouver ce Durak et vous lui dites que la Horde, elle voudra rien avoir à faire avec lui.', '', 'Durak persuadé', '', '', '', '', '', '', '', 'Parlez à Vol’jin, à Orgrimmar.', 0),
(13844, 'frFR', 'Le pillage d\'Althalaxx', 'Trouvez le Tome de Narassin parmi les Ruines d\'Althalaxx et tuez le commandant réprouvé Teegan Holloway.', 'Avant que vous ne retourniez vous battre, $c… On vient de me signaler une urgence. D’après mes éclaireurs, les Réprouvés s’intéressent aux ruines de la tour d’Althalaxx, au sud.$b$BAvant l’attaque, cette tour sinistre abritait une branche fanatique du Conseil des ombres, commandée par le bien-né déchu Athrikus Narassin. Celui-ci est mort depuis longtemps, mais si ses travaux ont survécu, nous ne pouvons pas nous permettre de les perdre de vue. Récupérez le résultat de ses recherches, et tuez le commandant des Réprouvés qui pille les ruines.', '', '', '', '', '', 'Les Réprouvés rôdent en périphérie de la tour. Ne leur accordez aucune pitié.', 'Teegan Holloway', '', '', 'Restituez le Tome à Mathas Boissauvage aux Ruines de Mathystra, en Sombrivage.', 0),
(13848, 'frFR', 'Un oiseau de mauvais augure', 'Kadrak vous a demandé d’aller parler au Commandant Croc-sinistre, sur la Grève de Zoram.', 'Depuis le début du siège de Bois-Brisé, aucun rapport n’a pu être transmis. À l’heure qu’il est, le commandant Croc-sinistre doit commencer à s’inquiéter.$b$bJe vous envoie sur la grève de Zoram pour transmettre notre rapport. Il n’est pas très reluisant, mais le commandant saura au moins à quoi s’en tenir.$b$bAllez parler à Vhulgra quand vous serez $gprêt:prête; à faire le trajet.', '', '', '', '', '', '', '', '', '', '', 0),
(13849, 'frFR', 'Astranaar brûle !', 'Éteignez 15 feux.', '$C, Astranaar est en feu !$B$BVite, prenez ce seau d\'eau et éteignez les feux avant qu\'il ne reste plus que des cendres !', '', 'Feux d\'Astranaar éteints', '', '', '', '', '', '', '', 'Retournez voir la Sentinelle Thenysil à Astranaar, en Orneval.', 0),
(13853, 'frFR', 'La riposte', 'Utilisez un Lanceur d\'Astranaar pour abattre 15 Hellions de Hurlenfer et leurs Coursiers du vent de la garde.', 'Les feux sont sous contrôle, mais nous devons faire quelque chose contre ces coursiers du vent !$B$BVite, $n, montez dans l\'un de nos lanceurs de glaive et répondez à leurs tirs !', '', 'Hellions et coursiers du vent abattus', '', '', '', '', '', '', '', 'Retournez voir la Sentinelle Thenysil, à Astranaar en Orneval.', 0),
(13865, 'frFR', 'Un boulot salissant', 'Krokk vous a demandé de tuer Dorinar, Arminon, Endolar et 12 Éclaireurs d’Orneval.$b$bSi vous perdez votre Poudre du signal secret, allez parler à Kadrak, à Bois-Brisé.', 'Écoutez-moi bien, $c.$b$bLes elfes de la région sont commandés par trois chefs qui leur ordonnent de concentrer leurs efforts sur le camp de bûcherons. Les abattre sèmerait sûrement la panique et la confusion, assez longtemps, je l’espère, pour que nous puissions mener à bien notre mission.$b$bPendant que vous y êtes, profitez-en pour tuer leurs éclaireurs, cela ne pourra que nous aider.', '', 'Protecteur Endolar abattu', 'Protectrice Dorinar abattue', 'Protecteur Arminon abattu', 'Éclaireurs d’Orneval vaincus', '', '', '', '', 'Présentez-vous à Krokk au Brasero fumant.', 0),
(13866, 'frFR', 'Au Rempart !', 'Parlez à Kulg Crachetripes à la frontière entre Orneval et Azshara afin d\'être $gtransporté:transportée; vers le Rempart de Mor\'shan. Présentez-vous à Kadrak à votre arrivée.', 'Ces bois sont peut-être silencieux, mais nos ennemis se cachent derrière chaque tronc. J\'ai trouvé plus d\'un orc avec des flèches dans le dos, son arme encore dans son fourreau.$b$bLe terrain est traître par ici, derrière les lignes de front, mais nous aurions besoin de bras solides et d\'esprits affûtés là-bas au Rempart de Mor\'shan. Kadrak y prépare une offensive. Il préfère les actions aux paroles. Vous vous entendrez bien.$b$bVenez me parler quand vous serez $gprêt:prête; et je vous y enverrai.', '', '', '', '', '', '', '', '', '', '', 0),
(13867, 'frFR', 'Réduction de la menace furbolg', 'Tuez 15 Furbolgs au Village des Crins-de-chardon, en Orneval.', 'Les furbolgs crins-de-chardon se trouvent juste au nord d’Astranaar. Mes éclaireurs m’ont signalé que leur nombre avait beaucoup augmenté au cours de ces derniers mois. S’ils devenaient trop nombreux, ils pourraient trouver le courage d’attaquer Astranaar !$B$BAllez au village des Crins-de-chardon et tuez autant de furbolgs que possible.$B$BJe resterai ici à Astranaar en attendant votre rapport. Qu’Élune soit avec vous, $c.', '', 'Furbolgs du village des Crins-de-chardon tués', '', '', '', '', '', '', '', 'Retournez voir Raene Mène-loup à Astranaar, en Orneval.', 0),
(13868, 'frFR', 'Une influence corruptrice ?', 'Apportez le Charme troll à Raene Mène-loup à Astranaar, en Orneval.', 'Un petit charme roule au sol lorsque vous fouillez dans les affaires du furbolg mort devant vous. C’est très certainement de l’artisanat troll.$B$BEn touchant l’objet en bois, un sentiment de malaise vous envahit. Vous sentez la corruption émaner de l\'amulette.$B$BVous l’enveloppez dans un morceau de tissu puis la mettez dans votre besace. Vous décidez de la montrer à Raene Mène-loup la prochaine fois que vous passerez à Astranaar.', '', '', '', '', '', '', '', '', '', '', 0),
(13869, 'frFR', 'Le bois en émoi', 'Récupérez 10 Bois de coupe chanteguerre.', 'Les satyres ont fait subir des atrocités aux arbres, mais ce n’est rien comparé au massacre auquel se livrent les orcs !$B$B<De rage, l’ancien secoue ses feuilles qui tombent tout autour de vous.>$B$B$R, j’aimerais que vous alliez jusqu’au camp de bûcherons et que vous rameniez les restes des arbres, tréants et anciens que la Horde a abattus dans la fleur de l’âge.', '', '', '', '', '', '', '', '', '', 'Retournez voir Noueux au Camp de bûcherons Chanteguerre, en Orneval.', 0),
(13870, 'frFR', 'Le nec plus ultra', 'Krokk vous a demandé d’entrer dans le Camp de bûcherons Chanteguerre, et d’aller parler au Surveillant Gorthak.', 'Eh bien, $c, ça ne pourrait pas mieux se passer.$b$bLes elfes peinent à se remettre de votre dernier passage. C’est le moment de forcer l’entrée du camp de bûcherons !$b$bFrayez-vous un chemin et allez parler au surveillant Gorthak. Il vous donnera des instructions sur la meilleure façon d’escorter la diplomate et de la mettre à l’abri.$b$bBonne chance !', '', '', '', '', '', '', '', '', '', '', 0),
(13871, 'frFR', 'Sécurité !', 'Le Surveillant Gorthak vous demande de lui apporter la Tête de l\'assassin kaldorei.', 'Ce n’est pas comme si je n’avais que ça à faire !$b$bIl faut que cet endroit reste opérationnel, et c’est déjà assez difficile sans que je sois constamment harcelé par les elfes et les draeneï.$b$bEn prime, il y a maintenant une meurtrière qui rôde autour du camp et qui a tué une importante diplomate… pendant que je montais la garde !$b$bQui que ce soit, elle n’a pas pu aller bien loin, $c. Fouillez le camp pour la retrouver puis vengez la diplomate !$b$bJe pourrai au moins apporter la tête de cette criminelle à Hurlenfer quand il me demandera des explications.', '', '', '', '', '', '', '', '', '', '', 0),
(13872, 'frFR', 'Sagesse worgen', 'Apportez le Charme troll à Héphaïstos Pèlerin à Astranaar, en Orneval.', 'L\'homme qui se trouve en face de moi se nomme Héphaïstos Pèlerin. C\'est un worgen.$B$BSa sœur et lui sont venus à Astranaar il n\'y a pas très longtemps, à la recherche d\'un asile. Selon le peu d\'informations que j\'ai pu glaner, il aimerait apporter son aide au Cercle terrestre pour faire face au bouleversement cataclysmique. Sa sœur est encore plus puissante. Elle s’en est allée à l\'est aider les chamans à résoudre le problème du volcan.$B$BPeut-être qu’Héphaïstos peut vous aider. Montrez-lui le charme et voyez ce qu\'il en pense.', '', '', '', '', '', '', '', '', '', '', 0),
(13873, 'frFR', 'La dernière volonté de Sheelah', 'Le Gardien Ménérin vous a demandé de transmettre la Lettre scellée au Gardien Gurtar.', 'Je… Je n’arrive à croire qu’elle soit morte. Tout s’est passé si vite…$b$bJe crois que je dois vous remercier d’avoir vengé ma maîtresse. Pour cela, vous avez ma gratitude et celle de Lune-d’Argent.$b$bDans sa grande sagesse, ma maîtresse avait prédit ce dénouement. Elle avait préparé une missive à transmettre au cas où il lui arriverait malheur.$b$bNous étions censés rejoindre un groupe de gardes d’Orgrimmar, au croisement, juste au nord d’ici. Je vous en prie, $r, allez-y à notre place et veillez à ce que le message soit transmis.', '', '', '', '', '', '', '', '', '', '', 0),
(13874, 'frFR', 'Une vie pas si charmante', 'Rassemblez 8 Charmes trolls.', 'Les furbolgs convoitent ce qui ne leur appartient pas.$B$B<Héphaïstos retourne plusieurs fois le charme dans sa main puis le jette.>$B$BCes inscriptions possèdent un pouvoir qui corrompt lentement tous ceux qui ne sont pas trolls. D’après ce que je sais, les furbolgs ont déjà été victimes de leur convoitise par le passé. Certains ne tirent jamais de leçon de leurs erreurs.$B$BIls doivent entasser la plupart des charmes au repaire des Crins-de-chardon, par-delà leur village, au nord.', '', '', '', '', '', '', '', '', '', 'Retournez voir Héphaïstos Pèlerin à Astranaar, en Orneval.', 0),
(13875, 'frFR', 'La demande de Gurtar', 'Le Gardien Gurtar vous demande d’apporter la Sanguinette tressée à Draaka, à Bois-Brisé.', 'J’ai une requête un peu personnelle à vous adresser, $c.$b$bCela fait des lunes que je n’ai pas vu Draaka, ma bien-aimée. Et il y en aura encore beaucoup d’autres avant que nous ne soyons à nouveau réunis. Je crains que son amour pour moi ne se fane au fil du temps.$b$bCette tresse a une signification particulière pour nous deux, tout comme les sanguinettes épineuses, les fleurs qui poussent dans la région.$b$bJ’aimerais que vous alliez cueillir ces fleurs et que vous les enrouliez autour de la tresse. Apportez ensuite ce cadeau à Draaka de ma part.', '', '', '', '', '', '', '', '', '', '', 0),
(13876, 'frFR', 'Perdus à jamais', 'Procurez-vous l’Assortiment de Griffe-de-sang.', 'Oui, je parle votre langue, $r.$B$BNous, les furbolgs, avons déjà été victimes de ce genre de corruption par le passé. Il n’y a pas si longtemps, notre chef a volé l’idole de Remulos. Cet objet démoniaque a ensorcelé toute notre tribu. Un druide appelé Broll Mantelours nous a finalement offert la rédemption.$B$BMais cette fois-ci, nous n’avons rien volé. Les trolls de Zoram’gar nous ont donné des charmes en gage d’amitié. Une amitié empoisonnée, oui !$B$BLa folie s’est emparée de notre chef, Dal Griffe-de-sang. Pénétrez dans le fort et rapportez-moi ces charmes.', '', '', '', '', '', 'Récupérez l\'Assortiment de Griffe-de-sang.', 'Dal Griffe-de-sang', '', '', 'Retournez voir Vear Museau-sombre, à l’entrée du Repaire des Crins-de-Chardon, en Orneval.', 0),
(13877, 'frFR', 'Autant en emporte la lave', 'Allez parler à Sabina Pèlerin, à l’extrémité sud du torrent de lave de Pic-Tonnerre, en Orneval.', '<Le worgen vous dévisage avant de formuler sa demande.>$B$BLe volcan va engloutir la totalité d’Orneval si nous n’agissons pas rapidement. Je peux vous assurer que la cause de cette éruption n’était pas naturelle.$B$BMa sœur, Sabina, une puissante chamane du Cercle terrestre, s’en est allée à l’est, à l’extrémité du torrent de lave du Pic-Tonnerre. Elle tente d’obtenir l’aide des autres éléments pour affronter le seigneur du Feu à l’origine de cette destruction.$B$B$n, allez la rejoindre et aidez-la du mieux de vos possibilités.', '', '', '', '', '', '', '', '', '', '', 0),
(13878, 'frFR', 'À travers feu et flammes', 'Brisez les chaînes pour libérer les loups des écuries en feu.', 'Aidez-moi, $c ! Les hommes-cochons, ils sont venus mettre le feu aux écuries ! Au feu ! Au feu !$B$B<Dorak pousse des gémissements incohérents jusqu\'à ce que vous parveniez à le calmer.>$B$BLes loups sont encore attachés à l\'intérieur. Quelqu\'un doit sauver les pitits loups !', '', 'Loups libérés', '', '', '', '', '', '', '', 'Allez voir Dorak au sud du Poste de Guet-Lointain, dans les Tarides du Nord.', 0),
(13879, 'frFR', 'Le Pic-Tonnerre', 'Broyk vous demande de trouver Stikwad, au Pic-Tonnerre.', 'Salutations, $c.$b$bJe vous félicite pour le succès de votre attaque sur Astranaar. Les elfes ne sont pas prêts d’oublier l’humiliation que vous leur avez fait subir.$b$bMais vous devez savoir qu’ils ne sont pas les seuls obstacles qui empêchent la Horde de conquérir Orneval…$b$bÀ l’est, un chaman du Cercle terrestre a besoin d’aide pour résoudre un autre problème. Vous le trouverez au pied du volcan, le Pic-Tonnerre.', '', '', '', '', '', '', '', '', '', '', 0),
(13880, 'frFR', 'Chaud devant !', 'Utilisez le Don de la Terre pour combler 8 Crevasses de lave.', '<Le grand élémentaire de terre vous observe de toute sa hauteur.>$B$BNous devons interrompre le torrent de lave pour réussir. Je vais vous conférer une partie de mes pouvoirs. Utilisez-les pour combler les crevasses de lave !', '', 'Crevasses de lave comblées', '', '', '', '', '', '', '', 'Retournez voir Magma au Pic-Tonnerre, en Orneval.', 0),
(13881, 'frFR', 'Consumés', 'Tuez 6 Ours des chardons consumés et examinez le lac auquel ils s’abreuvent.', 'Je m’inquiète d’abord pour les familles d’ours des chardons qui vivent dans ce qui reste de ces bois. Juste au sud, au-delà du sanctuaire de l’ours, une génération entière est tombée malade. Une vilaine maladie.$B$B$n, je ne sais pas de quoi ils souffrent au juste, mais ils se consument de l’intérieur. Cela me brise le cœur qu’une génération entière soit impossible à sauver, mais nous devons les tuer afin que la terre récupère leurs corps.$B$BDe plus, nous devons découvrir d’où vient la maladie. Enquêtez au lac peu profond où ils boivent !', 'Enquête au point d\'eau', '', '', '', '', '', '', '', '', 'Retournez voir Kathrena Fétu-d’hiver au Bosquet des Anciens, en Sombrivage.', 0),
(13882, 'frFR', 'Les graines de la vie', 'Récupérez une Graine de la terre, une Graine du ciel et une Graine de la mer.', 'Quelque chose essaye de dévorer la vie de Sombrivage de l’intérieur ! Je vais tenter d’en apprendre davantage sur la… chose… que vous avez découverte dans le lac. Pendant ce temps, il faut que nous protégions la faune de nouveaux dégâts.$B$BPouvez-vous récupérer quelques matériaux pour moi ? J’ai besoin de vie sous toutes ses formes. Parlez à Onu, ici dans le bosquet, pour récupérer une graine de la terre. Capturez l’un des feux follets de Sombrivage qui flottent entre les arbres et vous aurez une graine du ciel. Enfin, vous trouverez une graine de la mer à l’intérieur des coquillages le long de la côte, à l’ouest.', '', '', '', '', '', '', '', '', '', 'Apportez les graines à Kathrena Fétu-d’hiver au Bosquet des Anciens, en Sombrivage.', 0),
(13883, 'frFR', 'Mené en bateau', 'Retrouvez 10 Morceaux de ferraille immergés.', 'C’est du sale boulot ! Il n’y a pas d’autre explication…$b$bCes navires ont dû être construits à la va-vite. Des pans entiers de blindage se détachent sans avoir subi le moindre choc !$b$bJe vais leur montrer comment on fait. Mais d’abord, il faut que vous écumiez le fond des mers à la recherche de ces morceaux de ferraille.$b$bRapportez-les-moi, et je ferai le reste.', '', '', '', '', '', '', '', '', '', 'Allez voir Dagrun à Zoram\'gar.', 0),
(13884, 'frFR', 'Ils ne feront pas long feu', 'Tuez 10 Enragés de lave. Si vous avez besoin d\'un autre Surgisseur glacial, allez voir Arctanus.', 'Pour reprendre le contrôle de la région et mettre un terme à la destruction massive de la forêt, il faut d’abord se débarrasser des sbires du seigneur Magmathar.$B$BLe torrent de lave, au nord, renforce les enragés de lave qui s’y trouvent. $gSeul:Seule;, je crains que vous ne fassiez pas le poids face à eux.$B$BRevenez me parler quand vous serez $gprêt:prête;, et j’invoquerai un élémentaire pour vous aider.', '', '', '', '', '', '', '', '', '', 'Retournez voir Arctanus au Pic-Tonnerre, en Orneval.', 0),
(13885, 'frFR', 'La défense de Sombrivage', 'Parlez à Orseus à l’extérieur du Bosquet des Anciens et montez sur un hippogriffe. Depuis les airs, protégez 8 Cerfs queue-blanche, 8 Vieux ours des chardons et 8 Matriarches ou Géniteurs traquelunes contre la consomption.', 'Maintenant que nous savons que nos mesures préventives fonctionnent, nous devons couvrir autant de terrain que possible.$B$BJe me suis arrangée pour récupérer un hippogriffe, mais je ne suffirai pas à la tâche. Allez voir mon ami Orseus, près du maître de vol, juste devant le bosquet. Prévenez-le quand vous serez $gprêt:prête;, je vous retrouverai là-bas. Nous sillonnerons Sombrivage depuis les airs, et nous protègerons autant d’animaux que nous le pourrons !', '', 'Vieil ours des chardons protégé', 'Traquelune protégé', 'Cerf blanche-queue protégé', '', '', '', '', '', 'Retournez voir Kathrena Fétu-d’hiver au Bosquet des Anciens, en Sombrivage.', 0),
(13886, 'frFR', 'Le vortex', 'Utilisez les pouvoirs du Vortex tourbillonnant pour vaincre le Seigneur Magmathar.', 'Le temps est venu, $n. Lorsque vous serez $gprêt:prête;, revenez me voir et j’invoquerai un vortex tourbillonnant pour vous envoyer plus rapidement au sommet du Pic-Tonnerre.$B$BCanalisez le pouvoir du Cercle terrestre à travers l’élémentaire pour vaincre le seigneur Magmathar et rétablir l’équilibre.', '', 'Seigneur Magmathar vaincu', '', '', '', 'L’essence même du Pic-Tonnerre. Éteignez-la !', 'Seigneur Magmathar', '', '', 'Retournez voir Sabina Pèlerin au Pic-Tonnerre, en Orneval.', 0),
(13888, 'frFR', 'Le vortex', 'Utilisez les pouvoirs du Vortex tourbillonnant pour vaincre le Seigneur Magmathar.', 'Le temps est venu, $n. Lorsque vous serez $gprêt:prête;, revenez me voir et j’invoquerai un vortex tourbillonnant pour vous envoyer plus rapidement au sommet du Pic-Tonnerre.$B$BCanalisez le pouvoir du Cercle terrestre à travers l’élémentaire pour vaincre le seigneur Magmathar et rétablir l’équilibre.', '', 'Seigneur Magmathar vaincu', '', '', '', 'L’essence même du Pic-Tonnerre. Éteignez-la !', 'Seigneur Magmathar', '', '', 'Retournez voir Stikwad au Pic-Tonnerre, en Orneval.', 0),
(13890, 'frFR', 'Jeter de l’huile sur le feu', 'Le Commandant Croc-sinistre, de Zoram’gar, vous a demandé de verser de l’Huile d’hydre fouettebrume sur le feu du phare.', 'Ce n’est pas une mince affaire, $r !$b$bD’autres navires approchent, et sans la lumière du phare, ils seront perdus, ou pire ! Vous êtes donc $gchargé:chargée; d’entretenir le feu.$b$bRécupérez la graisse des hydres qui nagent dans ces eaux, puis transformez-la en huile grâce à la forge que voici.$b$bVous nous ferez gagner un temps précieux en jetant cette huile sur le feu du phare.', '', 'Feu du phare allumé', '', '', '', '', '', '', '', '', 0),
(13891, 'frFR', 'Le Dévoreur de Sombrivage', 'Utilisez l’Arbrisseau portevie sur la rive du lac peu profond, au sud du Bosquet des Anciens, afin de détruire l’Artéfact dévoreur et son gardien.', 'Maintenant que les créatures de Sombrivage sont en sécurité, il est temps de nous intéresser à l’artéfact que vous avez trouvé dans le lac. Je crois qu’il est l’œuvre d’un séide d’un Dieu très ancien. Nous allons combattre ces monstres en employant les énergies vitales de Sombrivage ! Rendez-vous sur la berge du lac peu profond qui se trouve au sud avec l’arbrisseau portevie. Agitez-le au-dessus des eaux. Cela devrait suffire à neutraliser l’artéfact.$B$BFaites quand même attention, $n. Il y a des chances qu’il soit gardé par Élune sait quoi.', '', 'Artéfact dévoreur détruit', '', '', '', 'Qui sait ce que vous pourriez découvrir…', 'Yoth\'al le Dévoreur', '', '', 'Retournez voir Kathrena Fétu-d’hiver au Bosquet des Anciens, en Sombrivage.', 0),
(13892, 'frFR', 'Ne laissez aucune trace', 'Infiltrez-vous au Glaive du maître à l’aide de la Figurine de panthère, et espionnez le Marteau du crépuscule.', 'Au sud-ouest gît le corps d’une créature apparentée aux Dieux très anciens que vénèrent les sectateurs du Marteau du crépuscule.$B$BIl a été vaincu avant notre temps, peut-être pas par les titans eux-mêmes, mais au moins par l’une de leurs créations.$B$BL’activité du culte a augmenté dans la région. Autrement dit, quelque chose de terrible se prépare.$B$BNous devons découvrir ce qu’ils mijotent là-bas, et quelles sont leurs motivations. Prenez cette figurine, elle vous aidera à passer $ginaperçu:inaperçue; pendant votre collecte d’informations.', '', 'Surveillance du Marteau du crépuscule', '', '', '', '', '', '', '', '', 0),
(13893, 'frFR', 'Soggoth et Kronn', 'Retournez voir Larien au Bosquet des Anciens avec les informations que vous avez obtenues.', 'Le Glaive du Maître a été le théâtre d’une antique bataille, $n. Les titans ont envoyé vingt géants de pierre contre Soggoth.$B$BUn seul a survécu.$B$BLes tablettes disent que Kronn, le plus grand d’entre eux, s’est laissé prendre par les tentacules de Soggoth, juste assez longtemps pour que le monstre l’approche de sa tête… à portée de son épée.$B$BHeureusement que ce truc est mort… nous n’avons pas vingt géants de pierre pour l’arrêter de nouveau.', '', '', '', '', '', '', '', '', '', '', 0),
(13895, 'frFR', 'Les Anciens endormis', 'Trouvez Aros au nord-est du Bosquet des Anciens, en Sombrivage.', 'Nous n’avons peut-être pas vingt géants de pierre à lancer sur l’ennemi, mais nous autres géants de bois sommes aussi forts que n’importe quel rocher.$B$BRegardez autour de vous, $r. Les miens dorment… mais lorsque le besoin s’en fera sentir, ils entendront le cor du gardien.$B$BAllez voir Aros, le gardien du bosquet, au-delà du pont qui se trouve au nord-est.$B$BExpliquez-lui à quel point la situation est dramatique.', '', '', '', '', '', '', '', '', '', '', 0),
(13896, 'frFR', 'Connaissances déterrées', 'Parlez à l’Archéologue Groff aux Excavations de Songerrance.', 'Écoutez, $n. Nous avons besoin d’en savoir plus sur nos ennemis.$B$BAu sud-ouest, au-delà du Glaive du Maître, il y a un groupe de prospecteurs nains qui fouillent des ruines. Peut-être ont-ils découvert des informations susceptibles de nous aider ?', '', '', '', '', '', '', '', '', '', '', 0),
(13897, 'frFR', 'La bataille pour Sombrivage', 'Tuez l’Avatar de Soggoth, au Glaive du Maître.', 'Les anciens du bosquet sont venus nous prêter main-forte, $n. Je peux voir ce qu’ils voient, en ce moment même.$B$BLe Marteau du crépuscule a été forcé de réaliser à la hâte son rituel. Il n’a réussi à ramener à la vie qu’une ombre du terrible Soggoth.$B$BDétruisez-la avant qu’il ne soit trop tard, $n. Mon aide est requise ailleurs.$B$BRetournez voir les druides, au bosquet des Anciens, quand tout sera terminé. Ils vous diront quoi faire.', '', '', '', '', '', 'Renvoyez-le dans les profondeurs auxquelles il appartient.', 'Avatar de Soggoth', '', '', 'Retournez voir Balren de la Griffe au Bosquet des Anciens, en Sombrivage.', 0),
(13898, 'frFR', 'Les marées se retournent contre nous', 'Tuez 8 Myrmidons Sombrécailles.', 'Nous ne pouvons pas laisser les nagas s’en tirer comme ça, $n. Ils nous ont déclaré la guerre en tuant le gardien du bosquet.$B$BLeur antre se trouve dans une grotte, sur l’île de Nazj’vel, plus loin au sud-ouest.$B$BJe veux leur faire passer un message clair.', '', '', '', '', '', '', '', '', '', 'Retournez voir Felros au Bosquet des Anciens, en Sombrivage.', 0),
(13899, 'frFR', 'Le seigneur de guerre des Sombrécailles', 'Tuez le Seigneur de guerre Iréchine, à l’intérieur de Nazj’vel.', 'Je prie pour qu’Élune ait pitié des nagas, car ils ont l’intention de s’allier avec le Marteau du crépuscule.$B$BAventurez-vous dans leur repaire, sur l’île de Nazj’vel, et trouvez leur chef, le seigneur de guerre naga, connu sous le nom d’Iréchine.$B$BLe cor des Anciens a encore une chance d’être sauvé.', '', '', '', '', '', '', '', '', '', '', 0),
(13900, 'frFR', 'L\'offrande à Azshara', 'Empêchez les Prêtresses Sombrécailles d’offrir le Cor des Anciens à Azshara au-dessus de Nazj’vel.', 'Selon les dires du seigneur de guerre, le cor des Anciens a été offert à Azshara, au-dessus de Nazj’vel.$B$BIl n’est peut-être pas trop tard pour empêcher la relique antique d’être détruite.', '', 'Offrande à Azshara empêchée', '', '', '', '', '', '', '', '', 0),
(13901, 'frFR', 'Un désespoir intense', 'Tuez 6 Prêtresses des marées de Brassenoire.', 'La question des nagas est plus compliquée qu’elle n’y paraît, $c. On ne résoudra pas le problème simplement en réduisant leur nombre. Il faut les écraser et leur montrer qui est le plus fort.$b$bAllez à l’extrémité nord de la grève de Zoram et pénétrez dans les profondeurs de Brassenoire. Lorsque vous y serez, faites comprendre aux nagas que leur présence ne sera plus tolérée dans cette région !', '', 'Prêtresses des marées de Brassenoire abattues', '', '', '', '', '', '', '', 'Retournez voir Marukai à Zoram\'gar, en Orneval.', 0),
(13902, 'frFR', 'Monter l\'offensive', 'Allez parler à Balren de la Griffe, au Bosquet des Anciens, en Sombrivage.', 'Notre travail en Sombrivage n\'est pas encore terminé. Nous avons peut-être empêché la région d’être pulvérisée, mais nos ennemis sont toujours très présents dans le secteur.$B$BJe veux que vous rejoigniez un groupe de druides, au bosquet des Anciens, plus loin au sud. Leur chef est un de mes vieux amis, Balren de la Griffe.$B$BDites-leur que l’heure est venue d’entrer en guerre contre nos ennemis. Je leur prêterai main-forte dès que la zone sera sécurisée.', '', '', '', '', '', '', '', '', '', '', 0),
(13907, 'frFR', 'Nettoyer les ruines', 'Tuez un total de 10 Oracles ou Réfugiés grisebrumes qui occupent les Excavations de Songerrance.', 'Dès qu’ils ont su pour le désastre, ces grosses barbes de Forgefer m’ont envoyé ici pour jeter un œil aux fouilles de Songerrance. Regardez-moi ce bazar ! Des reliques inestimables emportées par la mer, des mois de fouilles réduits à néant en un clin d’œil.$B$BQuand le raz-de-marée s’est abattu sur le rivage, tous les camps murlocs ont été détruits. Une chance ? Tu parles, pas avec ma poisse. Les survivants se sont réfugiés dans les ruines, et ils font plus de dégâts que les éléments eux-mêmes n’en feraient ! Ça vous dirait pas de traîner vos savates là-bas et de prendre les choses en main ?', '', 'Squatteurs murlocs tués', '', '', '', '', '', '', '', 'Retournez voir l’archéologue Groff aux Excavations de Songerrance, en Sombrivage.', 0),
(13909, 'frFR', 'Vous avez des débris ?', 'Rassemblez 5 morceaux de Débris grisebrumes récupérables, le long du rivage et dans l\'eau près des Excavations de Songerrance.', 'On va trouver un moyen, $n. Il nous faut juste un peu d’ingéniosité naine. Réfléchis, Groffou, réfléchis !$B$BCes murlocs veulent juste un toit, c’est ça ? Soyons constructifs. Et pas qu’au sens figuré !$B$BToutes sortes de débris ont atterri sur le rivage pendant la catastrophe, et on doit pouvoir se servir des restes des taudis murlocs. Rassemblez tous les matériaux de construction que vous trouverez le long du rivage et qui pourraient convenir à un murloc. C’est-à-dire à peu près tout et n’importe quoi.', '', '', '', '', '', '', '', '', '', 'Apportez les débris à l’archéologue Groff aux Excavations de Songerrance, en Sombrivage.', 0),
(13910, 'frFR', 'Un nouveau foyer', 'Construisez une cabane de murloc sur un site choisi par Groff, près du rivage.', 'Peut-on le construire ? Oui, nous le pouvons ! À l\'ouest du site de fouille, j\'ai planté une bannière sur le rivage. Le sable est ferme et ce site est aussi bien qu\'un autre. Prenez mes outils et les pièces que vous avez récupérées, et construisez à ces pestes hargneuses un endroit différent où vivre.', '', 'Foyer pour les murlocs grisebrumes construit', '', '', '', '', '', '', '', 'Retournez voir l’archéologue Groff aux Excavations de Songerrance, en Sombrivage.', 0),
(13911, 'frFR', 'Les absences du Prospecteur', 'Escortez le Prospecteur Songerrance désorienté pour l’aider à retrouver son journal. Allez parler à l\'Apprenti archéologue Ferd au site de fouilles quand vous aurez terminé.', 'Vous êtes qui, déjà ? $n ? On se connaît ? Si c’est la Ligue des explorateurs qui vous envoie, dites-leur que je ne partirai pas ! Pas sans ma trouvaille. Je l’avais entre les mains. Puis, il y a eu les cris. Et l’eau.$B$BÉcoutez voir, Trucmuche, j’ai tout noté dans mon journal, le jour de la marée. Et je sais exactement où je l’ai laissé ! Mon journal. Pas ma trouvaille. Aidez-moi à trouver l’un pour retrouver l’autre ! Ou l’inverse ! Vous me suivez ? Suivez-moi !', 'Prospecteur Songerrance escorté', '', '', '', '', '', '', '', '', 'Parlez à l’apprenti archéologue Ferd aux Excavations de Songerrance, en Sombrivage.', 0),
(13912, 'frFR', 'Secrets embourbés', 'Trouvez un Disque ancien incrusté de boue dans les ruines voisines.', 'Songerrance est peut-être une tête de linotte, mais c’est un génie, un joyau dans un vieil écrin. Mais je n’ai pas l’intention de l’abandonner. Regardez ce que j’ai trouvé dans ses notes… ce n’est pas là… non, ça, c’est une liste de courses… Voilà ! Le passage où il essaie de dater le disque !$B$BNous pensons que cet artéfact légendaire est une sorte de roue contenant des informations codées. Nous étions en train de le déterrer soigneusement quand la catastrophe est survenue. Mais heureusement, il se trouve encore dans les ruines. Creusez et rapportez-le-moi !', '', '', '', '', '', '', '', '', '', 'Rapportez le Disque à l’apprenti archéologue Ferd aux Excavations de Songerrance, en Sombrivage.', 0),
(13913, 'frFR', 'Ils ont pris nos gnomes', 'Libérez Boug le « gnome qui murmurait à l’oreille des rouages » et Coquine du Chariot d’agonie sans fin du Maître de la douleur Thundrak.', 'L’équipe de démolisseurs gnomes que nous avons demandée est arrivée de Brikabrok la semaine dernière. Juste à temps pour faire face à une attaque de la Horde. Nous avons perdu beaucoup de soldats, ce jour-là. La majeure partie de l’équipe gnome a aussi été capturée. Maintenant, on se retrouve cerné de toutes parts par la Horde, le refuge de Vent-d\'Argent a été perdu, et il nous manque une douzaine de gnomes.$b$bJe vous supplie de nous aider, $n. Allez à l’est, jusqu’au refuge de Vent-d\'Argent, et cherchez les gnomes survivants. Ils ont tous été embarqués dans un chariot par un grand orc impitoyable appelé Thundrak. Trouvez-le et vous trouverez nos gnomes.', 'Boug et Coquine libérés', '', '', '', '', '', '', '', '', 'Retournez auprès de la Chasseresse Jalin à la Flèche de Chimétoile, en Orneval.', 0),
(13918, 'frFR', 'Le terminal des titans', 'Passez la plage près des Excavations de Songerrance au Détecteur d’artéfacts enterrés pour retrouver 5 morceaux du Mécanisme antique. Ensuite, assemblez-les pour former le Mécanisme antique pourvu d’une fente.', 'La découverte du disque nous permet désormais de comprendre l’utilisation de nos premières trouvailles. Peu après mon arrivée, le prospecteur Songerrance a trouvé ce qu’il pensait être un grille-pain préhistorique.$B$BJe pense que cette boîte dotée d\'une fente doit être une sorte de lecteur de données. Malheureusement, elle s’est cassée, et la mer l’a emportée avec le reste de notre camp de base quand la marée a déferlé sur le rivage !$B$BElle ne doit pas être bien loin, $n. Des morceaux doivent être enfouis dans le sable, aux alentours. Tenez, passez la plage au peigne fin avec mon fidèle détecteur d’artéfacts enterrés.', '', '', '', '', '', '', '', '', '', 'Apportez le Mécanisme à l’apprenti archéologue Ferd aux Excavations de Songerrance, en Sombrivage.', 0),
(13919, 'frFR', 'Un voyage au puits de lune', 'Prenez la Larme d’Élune et allez la purifier dans les eaux du Puits de lune de pureté, en Orneval.', 'Ça n’a pas marché.$B$B<Une expression de tristesse et de résignation se dessine sur le visage de Pelturas tandis qu’il retire la larme de la soupe et la nettoie délicatement.>$B$BL’éruption du Pic-Tonnerre a dû avoir un impact sur la pierre. Vous devez l’emporter au puits de lune de pureté au sud-est, à proximité du volcan. Il est toujours intact, protégé par la puissance des déesses.$B$BLorsque vous y serez, vous purifierez la pierre dans les eaux sacrées d’Élune. Je ne connais pas la suite des évènements. Je crains pour la vie de ma fille. Elle est entre vos mains désormais, $n.', 'Larme d\'Élune purifiée', '', '', '', '', '', '', '', '', '', 0),
(13920, 'frFR', 'Avant de partir...', 'Rapportez 5 Steaks de venaison au Commandant Croc-sinistre, à Zoram’gar.', 'Il faut à tout prix envoyer $gun:une:c; $c au guet de Hurlenfer, et quelqu\'un de compétent, $n. Mais avant que vous n’y alliez, il reste encore un problème à régler, ici.$b$bNous avons perdu une bonne partie de nos denrées périssables en mer à cause des attaques répétées de l’Alliance. Nous devons stocker suffisamment de nourriture pour mener à bien notre campagne sur Orneval.$b$bVous trouverez de nombreux animaux sauvages juste à l’est d’ici. Rapportez-moi la meilleure viande que vous trouverez pour sustenter nos troupes !', '', '', '', '', '', '', '', '', '', '', 0),
(13921, 'frFR', 'Celui qui cherchait le pardon', 'Allez voir Avrus Malmurmure à la Tour de Raynebois, en Orneval.', '<Une voix envahit votre esprit. Elle provient du puits de lune et vous apaise.>$B$BVous souhaitez guérir un enfant, mais sachez que toute chose a un prix. La tour de Raynebois se dresse à l’est. Celui qui a succombé à la corruption se tient devant cette tour, près de mon puits de lune.$B$BAvrus Malmurmure cherche le pardon et la rédemption, $n. L’aiderez-vous à obtenir ce qu’il désire pour atteindre votre objectif ?', '', '', '', '', '', '', '', '', '', '', 0),
(13922, 'frFR', 'Satyre à sa fin', 'Récupérez 5 Pierres de lune tombées.', 'Il y a quelque temps de cela, les membres de mon ancien clan, les Gangremusc du défilé de la Nuit, ont pillé le lac Tombeciel, et volé les uniques pierres de lune de la région.$B$BLes propriétés curatives de ces pierres sont réputées et pourraient certainement être utilisées pour guérir l’enfant malade d’Astranaar.$B$BPour vous rendre au défilé de la Nuit, vous devez emprunter la route à l’est, qui mène au nord. Il existe de nombreux chemins dans les collines qui vous permettront de vous y rendre, sur le côté est : c’est là que vous trouverez mes frères irrécupérables. Ils auront ce que vous cherchez.', '', '', '', '', '', '', '', '', '', 'Retournez voir Avrus Malmurmure à la Tour de Raynebois, en Orneval.', 0),
(13923, 'frFR', 'En route pour le Guet de Hurlenfer', 'Allez parler au Capitaine Goggath, au Guet de Hurlenfer.', 'Nous combattrons ensemble jusqu’au bout, $r !$b$bLe Guet de Hurlenfer est l’une des zones les plus sensibles d’Orneval. Vous devriez retirer beaucoup d\'expérience de cette mission… enfin, si vous survivez.$b$bQuand vous serez $gprêt:prête;, allez parler à Andruk. Il vous conduira directement à votre poste.$b$bUne fois sur place, cherchez le capitaine Goggath. Il vous donnera des instructions.$b$bTerrassez nos ennemis ! Pour la Horde !', '', '', '', '', '', '', '', '', '', '', 0),
(13924, 'frFR', 'Tout est bien…', 'Apportez les Pierres de lune sanctifiées à Pelturas Blanchelune à Astranaar, en Orneval.', 'Grâce à vous, j’ai échappé à un destin pire que la mort, $n ! Je vous remercie de m’avoir sauvé, ainsi que l’enfant !$B$BEnfin, celle-ci n’est pas encore tout à fait tirée d’affaire. Il ne vous reste plus qu’à suivre la route à l’ouest et à apporter les pierres de lune à Astranaar. Donnez-les à Pelturas, il saura quoi en faire.$B$BAllez en paix, mon $gami:amie;. Louée soit Élune !', '', '', '', '', '', '', '', '', '', '', 0),
(13925, 'frFR', 'Une once de prévention', 'Testez l’Arbrisseau portevie sur un Vieil ours des chardons sain, un Cerf blanche-queue sain, une Matriarche ou un Géniteur traquelune sain.', 'Avez-vous déjà entendu parler des Très anciens, $n ? Onu et moi pensons que l’artéfact que vous avez trouvé dans le lac ne peut que leur appartenir. Son pouvoir corrompt Sombrivage et des horreurs, disparues depuis longtemps, refont surface. Vous et moi ne faisons pas le poids face à la situation, mais, pour l’instant, ma principale préoccupation est de protéger la faune.$B$BTenez, voici l’arbrisseau qui renferme l’essence vitale que vous m’avez rapportée. Je pense qu’il peut protéger la faune locale. Testez-le sur un ours, un cerf, ou un traquelune non corrompus, et revenez m’informer du résultat !', '', 'Arbrisseau portevie testé', '', '', '', '', '', '', '', 'Retournez voir Kathrena Fétu-d’hiver au Bosquet des Anciens, en Sombrivage.', 0),
(13928, 'frFR', 'Les âmes des sœurs', 'Retrouvez 10 Cadavres de sœurs rieuses.', 'Le gardien Ordanus nous a chargées, mes sentinelles et moi, de rester ici et de protéger la tour. Jusqu’ici, nous avons réussi à repousser les assaillants de la Horde. Mais ils nous contournent à présent, et se dirigent vers la retraite, au nord.$B$BLe gardien a envoyé ses dryades pour protéger l’arbre, mais elles ne semblent pas faire le poids face à l’avant-garde des orcs chanteguerre.$B$BVous devez y aller et récupérer autant de corps de sœurs rieuses que possible. Apportez-les à Halannia, à l’intérieur de l’arbre, à la retraite. Elle saura quoi faire.', '', '', '', '', '', '', '', '', '', 'Parlez à Halannia, au deuxième niveau de l’arbre de la Retraite de Raynebois.', 0),
(13935, 'frFR', 'Défendez l\'arbre !', 'Allez voir Halannia pour invoquer l’Ombre de Shadumbra et utilisez son pouvoir pour détruire un total de 50 ennemis chanteguerres, à la Retraite de Raynebois.', 'Nous utilisons le pouvoir du cœur de la forêt pour empêcher la Horde de détruire l’arbre, mais son pouvoir n’est pas sans limite. Nous devons nous en servir pour attaquer cette racaille !$B$BShadumbra, le grand félin de la forêt, rôde tout près d’ici. C’est en elle que nous devons puiser notre inspiration. Vous deviendrez l’ombre de Shadumbra. Vous serez $gimprégné:imprégnée; de l’essence de la panthère et vous tuerez tous ceux qui osent s’attaquer à la puissante Orneval !', '', 'Ennemis chanteguerres détruits', '', '', '', '', '', '', '', 'Allez voir la Sentinelle Melyria Ombregivre à la Tour de Raynebois, en Orneval.', 0),
(13936, 'frFR', 'Gluon englué', 'Le Capitaine Goggath vous demande de parler à Gluon, au Guet de Hurlenfer.', 'Des retards, encore des retards et toujours des retards ! Je ne m’en sors pas !$b$bOn m’avait dit que ce gobelin avait du talent, qu’il aurait plein de gadgets qui forceraient l’ennemi à se soumettre. Jusqu’à présent, je n’ai entendu que de belles paroles. S’il revient les mains vides, je le jette du haut de la falaise !$b$bAllez lui parler, $c. Dites-lui que ma patience atteint ses limites !', '', '', '', '', '', '', '', '', '', '', 0),
(13939, 'frFR', 'Les petits bonshommes en gangremousse', 'Collectez 6 Gangremousses.', 'J’espérais ne jamais devoir revenir à Teldrassil pour une si triste tâche. J’espérais que la corruption aurait complètement disparu. Mais quelque chose d’innommable subsiste.$B$BLa corruption des gangremousses pernicieuses menace toujours de retourner contre nous de paisibles créatures. Les grells et les grellides ont encore investi les lieux et menacent les résidents de Sombrevallon.$B$BAttaquez les grells et les grellides, $n, et voyez s’ils ont bel et bien été victimes des sortilèges de la gangremousse pernicieuse. Quand nous serons sûrs de ce qu’il en est, nous saurons comment procéder.', '', '', '', '', '', '', '', '', '', 'Retournez voir Tarindrella à Sombrevallon.', 0),
(13940, 'frFR', 'La fin du rêve', 'Allez parler à Malfurion, dans l’Œil du Vortex, en Sombrivage.', 'Tenez bon, $n. Le réveil est toujours un peu difficile pour les esprits et les corps qui n’y sont pas préparés.', '', '', '', '', '', '', '', '', '', '', 0),
(13941, 'frFR', 'La vile ennemie', 'Apportez la Glande à venin congestionnée à Dirania Brillargent au pied d\'Aldrassil.', 'Githyiss la Vile était connue pour posséder un venin plus violent que celui des autres Tissebois. Dirania Brillargent, au pied d’Aldrassil, pourra certainement fabriquer un antidote très puissant à partir de la glande à venin congestionnée de Githyiss. Elle pourrait même vous offrir une récompense…', '', '', '', '', '', '', '', '', '', '', 0),
(13942, 'frFR', 'Je vais l’exploser, façon puzzle !', 'Gluon, du Guet de Hurlenfer, vous a demandé de rassembler 10 échantillons d’Argile caressée par la lune.', 'Je tiens quelque chose, là !$b$bJ’ai pu récupérer assez d’éléments volatils de notre arsenal pour fabriquer les explosifs dont Goggath a besoin. Mais il faut d’abord que je les stabilise et que j’en fasse des bombes.$b$bJ’ai besoin d’argile, mais pas de n’importe laquelle… de l’argile caressée par la lune.$b$bOn en trouve seulement sur les rives nord du lac d’Astranaar, et elle possède les propriétés dont j’ai besoin pour révéler tout le potentiel de ma trouvaille !', '', '', '', '', '', '', '', '', '', '', 0),
(13943, 'frFR', 'Trêve de plaisanterie !', 'Le Capitaine Goggath vous a demandé de tuer 10 Tirailleurs d’Astranaar et 3 Officiers d’Astranaar.', 'Nos troupes ne sont pas encore prêtes à attaquer Astranaar, $c. Les elfes savent que nous allons passer à l’offensive et ne se contentent pas de rester assis à nous attendre. Ils ont établi un camp au pied de cette falaise, duquel ils lancent des attaques assez gênantes à la lumière de la lune.$b$bAvant qu’ils ne soient stimulés par ces embuscades, je veux que vous leur montriez de quel bois se chauffe la Horde ! Revenez au rapport quand vous les aurez calmés.', '', 'Tirailleurs d’Astranaar abattus', 'Officiers d’Astranaar abattus', '', '', '', '', '', '', '', 0),
(13944, 'frFR', 'Petit, mais costaud !', 'Utilisez l\'Explosif improvisé de Gluon sur le Chariot cassé, au Guet de Hurlenfer.', '<Gluon gesticule frénétiquement. Vous remarquez que ses gants sont anormalement grands.>$b$bJ’ai réussi ! Ça devrait même plaire à Goggath !$b$bIl faudrait juste pouvoir le tester sur quelque chose pour prouver son efficacité… ahh : le chariot !$b$bÇa fait des jours que le patron nous a demandé de dégager cette poubelle rouillée. Utilisez mes explosifs pour vous en débarrasser, puis voyez ce que le capitaine dira !', '', 'Chariot cassé détruit', '', '', '', '', '', '', '', 'Allez voir le Capitaine Goggath au Guet de Hurlenfer, en Orneval.', 0),
(13945, 'frFR', 'Danger à domicile', 'Tuez 20 Furbolgs pins-tordus à l’intérieur et aux alentours du Refuge des saisons de Ban’ethil.', 'L’agression des Pins-tordus restreint nos choix. Personne parmi nous n’a envie de se retourner, armes à la main, contre les furbolgs. Ils ont été nos amis, mais je redoute qu’ils ne s’intéressent bientôt à Dolanaar.$B$BLes furbolgs du creux de Ban’ethil et du refuge des saisons de Ban’ethil sont ma principale source d’inquiétude. J’ai besoin que vous partiez vers l’ouest, que vous entriez dans le refuge des saisons, et que vous tuiez tous les Pins-tordus que vous pourrez. Nous n’aurons sans doute pas beaucoup d’autres occasions de limiter leur nombre, alors faites vite.', '', 'Pin-tordu de Ban’ethil tué', '', '', '', '', '', '', '', 'Retournez voir la Sentinelle Kyra Chantétoile à Dolanaar.', 0),
(13946, 'frFR', 'Les représailles de la nature', 'Utilisez des Graines d’iracine pour tuer 12 Grellides à l’intérieur de Gangreroche.', 'Vous êtes $gprêt:prête; à réparer vos erreurs. C’est une bonne chose, et cela me donne une haute idée de votre caractère.$B$BJ’ai une autre tâche pour vous. J’ai récolté quelques graines d’iracine. Elles ressemblent à des gangrenoix, mais en plus puissantes. La nature réagit souvent mal aux démons, et ces iracines représentent une forme de représailles concentrées.$B$BAllez à Gangreroche, au nord. Vous y trouverez des grellides qui n’ont plus aucun espoir de rédemption. Servez-vous des racines pour les chasser, avant qu’ils ne deviennent une menace plus sérieuse.', '', 'Grellides de Gangreroche tués avec des Graines d’iracine', '', '', '', '', '', '', '', 'Retournez voir Syral Feuillelame à Dolanaar.', 0),
(13947, 'frFR', 'Écrastranaar !', 'Le Capitaine Goggath vous a demandé d’utiliser les Explosifs improvisés de Gluon pour tuer 20 Sentinelles d’Astranaar et détruire 10 Lanceurs d’Astranaar.', 'Alors, Gluon est finalement venu à bout de ces explosifs, hein ?$b$bÇa ne pouvait pas mieux tomber. En ce moment même, les elfes d’Astranaar se préparent à lancer une violente attaque sur notre camp.$b$bFaites-leur goûter notre nouvelle arme en la lançant du ciel ! Tous les elfes de la nuit ressentiront la destruction d’Astranaar comme un coup de poignard !$b$bAllez parler à Thraka quand vous serez $gprêt:prête; à lancer l’assaut.$b$bVisez juste, $c.', '', 'Sentinelles d’Astranaar abattues', 'Lanceurs d\'Astranaar détruits', '', '', '', '', '', '', '', 0),
(13948, 'frFR', 'Améliorer la surveillance', 'Infiltrez-vous au Glaive du maître à l\'aide de la Figurine de panthère, et espionnez les chefs du Marteau du crépuscule, sur la plateforme située au-dessus.', 'Les sectateurs semblent exhumer les restes d’une créature connue sous le nom de Soggoth le Rampant.$B$BLeurs supérieurs, sur les poutres au-dessus, ont peut-être davantage d’informations.', '', 'Espionnage au Glaive du Maître', '', '', '', '', '', '', '', 'Retournez voir Balren de la Griffe au Bosquet des Anciens, en Sombrivage.', 0),
(13949, 'frFR', 'Rétablir la caravane pour la Croisée', 'Parlez à Halga Œil-sanglant au Poste de Guet-Lointain pour escorter la prochaine caravane de la Croisée jusqu\'à la Ferme de Grol\'dom.', '<Halga affiche un sourire désarmant tout en tenant une arme à feu surdimensionnée.>$b$bVous avez déjà utilisé un joujou pareil, $n ? C’est du très gros calibre. Le feu de l’enfer avec une gâchette. Trop lourd pour être manié à pied, mais parfait quand on est monté sur le kodo de tête de la caravane. Je l’appelle mon « balayeur de rues ».$b$bNous devons transporter les provisions que vous avez récupérées jusqu’à la Croisée et je m’attends à un voyage mouvementé. J’aimerais que vous protégiez le convoi. Quand vous êtes $gprêt:prête;, dites-le et je vous mettrai en tête de la prochaine caravane.', '', 'Caravane escortée', '', '', '', '', '', '', '', 'Parlez à Kranal Fiss à la Ferme de Grol’dom, dans les Tarides du Nord.', 0),
(13953, 'frFR', 'Des nagas parmi nous', 'Retournez voir Balren de la Griffe au Bosquet des Anciens, en Sombrivage.', 'Cette créature semble s’être fendu le crâne en affrontant Aros. Elle ressemble à la description des nagas qu’on vous a donnée.$B$BOn raconte que malgré leur monstrueuse apparence, les nagas sont des elfes de la nuit déformés par la magie des arcanes de la reine Azshara.$B$BOn dirait bien qu’ils ont décidé de vous empêcher de récupérer le cor des Anciens.', '', '', '', '', '', '', '', '', '', '', 0),
(13958, 'frFR', 'La situation est critique !', 'Goggath vous a demandé d’apporter la Trousse de triage de combat à Thagg, à la Retraite de Raynebois.', 'Nos ennemis sont sur les dents. La victoire est proche !$b$bMais l’heure n’est pas encore à la fête, $c. Il reste beaucoup à faire avant que la Horde ne puisse revendiquer Orneval.$b$bUn conflit a éclaté à la retraite de Raynebois, à l’est. Les rapports indiquent que la Horde compte de nombreux blessés.$b$bPrenez les fournitures médicales que voici et apportez-les à Thagg. Dites-lui que notre attaque sur Astranaar est une réussite. Cela pourrait remonter le moral des troupes.', '', '', '', '', '', '', '', '', '', '', 0),
(13961, 'frFR', 'Tirer les vers du nez', 'Utilisez le Filet de Grol\'dom pour capturer un Pillard tranchecrin et le ramener à Togrik, à la Ferme de Grol\'dom.', 'Notre instinct est de courir sus à nos agresseurs, mais la sagesse nous dicte une autre voie. Nous devrions interroger l\'un de ces envahisseurs hurans afin d\'apprendre tout ce que nous pourrons. Prenez ce filet, $n, et allez m’attraper un de ces pillards hurans qui attaquent notre ferme à l\'ouest. Assommez-moi un de ces bestiaux et livrez-le-moi.', 'Prisonnier tranchecrin livré', '', '', '', '', '', '', '', '', 'Allez voir à Togrik à la Ferme de Grol’dom, dans les Tarides du Nord.', 0),
(13962, 'frFR', 'Status quo', 'Thagg, de la Retraite de Raynebois, vous a demandé de tuer le Gardien Ordanus.', 'Les trousses de triage nous aident à tenir pour les combats, cependant nous sommes dans une impasse.$b$bLes dryades meurent assez facilement, mais leur chef les ramène rapidement à la vie ! Nous devons affronter un flot incessant de cette vermine !$b$bLe gardien Ordanus se cache dans cet arbre biscornu. Nous avons tenté d’y accéder, mais en vain. Peut-être pourriez-vous essayer de vous frayer un chemin pendant que nous nous chargeons de ces dryades… ?$b$bCe devrait être un jeu d’enfant pour quelqu’un qui a conquis Astranaar. N’est-ce pas ?', '', 'Gardien Ordanus abattu', '', '', '', '', '', '', '', '', 0),
(13963, 'frFR', 'Coûte que coûte', 'Interrogez le Prisonnier tranchecrin. S\'il n\'est pas là ou s\'il est inconscient, adressez-vous à Togrik qui le ranimera.', 'Je pense qu\'il reviendra à lui si on lui verse de l\'eau froide sur la tête. Que va-t-il nous dire, à votre avis ?$B$BJe vais l\'enfermer dans notre enclos à bestiaux là-bas derrière moi. Je ne pense pas qu\'il restera conscient longtemps. Tâchez d\'apprendre le maximum de choses sur les raisons qui poussent les hurans à attaquer nos fermes ! Je vous laisse le choix de la méthode d\'interrogation.', '', 'Prisonnier tranchecrin interrogé', '', '', '', '', '', '', '', 'Parlez à Togrik à la Ferme de Grol’dom, dans les Tarides du Nord.', 0),
(13964, 'frFR', 'En route pour la flèche', 'Parlez à la Sentinelle Vélène Heurtétoile à la Flèche de Chimétoile.', 'Nous avons perdu le refuge de Vent-d\'Argent ! Tout ce que je sais, c\'est que la Horde a attaqué par surprise et est parvenue d\'une façon ou d\'une autre à retourner les élémentaires gardiens du lac Mystral contre nous.$B$BLes survivants se sont repliés sur la flèche de Chimétoile. $n, ils ont besoin de votre aide.$B$BPartez vers le sud-sud-est. Vous trouverez la flèche à l\'entrée de la Perce des Serres, qui conduit aux Serres-Rocheuses. Vous y rencontrerez la sentinelle Vélène Heurtétoile, elle prépare une contre-offensive.', '', '', '', '', '', '', '', '', '', '', 0),
(13965, 'frFR', 'L’infortune des Edune', 'Allez parler à Benjari Edune, à la Maison d\'Edune.', '$n, si vous avez un moment, j\'aimerais vous demander votre aide pour une affaire fort simple.$B$BJe n\'ai pas reçu de nouvelles de mes amis, les Edune, depuis quelque temps. Je me demandais si vous ne pourriez pas faire un crochet vers l\'ouest pour aller les voir ?$B$BJe vous remercie. Leur maison se trouve sur un petit terrain, juste à l\'ouest du sanctuaire d\'Aessina.', '', '', '', '', '', '', '', '', '', '', 0),
(13967, 'frFR', 'Prendre du poil de la bête', 'Senani Cœur-de-tonnerre, de la Retraite de Vent-d\'Argent, vous a demandé de rassembler 15 Oreilles de furbolgs sur les Totémiques vile-sylve et les Ursas vile-sylve.', 'Au sud, les furbolgs sont plus nombreux que nous ne le pensions. Ils sont aussi bien plus agressifs.$b$bNous sommes occupés à traquer les elfes et à récolter le bois dont nous avons besoin, il n’y a plus que vous pour m’aider à résoudre le problème des furbolgs.$b$bJe dois faire des recherches, ici. En attendant, j’aimerais que vous ayez une approche plus… directe. Rapportez-moi les oreilles des furbolgs qui sont dans le coin pour prouver à Tarkan que l’on se charge de l’affaire.', '', '', '', '', '', '', '', '', '', '', 0),
(13968, 'frFR', 'L\'assassinat de Raclhure', 'Éliminez Raclhure, le chef des Tranchecrins.', 'Dans le sillage du chaos qui règne au sud, cette brute de « Raclhure » semble avoir rallié tous les réfugiés tranchecrins sous sa bannière. Sous son commandement, ils sont devenus de vulgaires brigands. On ne négocie pas avec ces gens-là. Raclhure doit être éliminé.$b$bÀ en croire notre prisonnier, vous le trouverez au sud-est d’ici, dans un endroit appelé la colline des Épines. Cherchez près des promontoires d’où on a une vue dégagée sur la route. Tuez-le, $n, et la menace immédiate devrait disparaître.', '', '', '', '', '', 'L\'affreux huran de la Colline des Épines.', 'Raclhure', '', '', 'Retournez voir Togrik à la Ferme de Grol’dom, dans les Tarides du Nord.', 0),
(13969, 'frFR', 'Le kodo manquant de Grol\'dom', 'Trouvez un Kodo de Grol\'dom égaré dans la Colline des Épines, dans les Tarides du Nord.', '$gCher ami:Chère amie;, si vous voyagez vers le sud en direction de la colline des Épines, je me demandais si vous ne pourriez pas localiser un des kodos que nous avons perdus ? Toutes les caravanes n\'arrivent pas au-delà du poste de Guet-Lointain. Ces brutes de Tranchecrins ont attaqué un animal de bât hier matin. Il n\'est peut-être plus en vie, mais au cas où il le serait, nous ne pouvons pas nous permettre de perdre davantage de bêtes.', '', '', '', '', '', '', '', '', '', 'Trouvez un Kodo de Grol\'dom égaré dans la Colline des Épines, dans les Tarides du Nord.', 0),
(13970, 'frFR', 'Services aux animaux', 'Ramassez 5 Sacs de grain volé dans les camps des Tranchecrins, sur la Colline des Épines.', 'Les kodos sont des créatures résistantes. Avec de la nourriture, ce gros pépère va peut-être revenir à lui.$B$BLes Tranchecrins ont volé quantité de céréales aux caravanes précédentes. Vous pouvez ramasser du grain dans les différents camps des environs.', '', '', '', '', '', '', '', '', '', 'Apportez le grain au Kodo de Grol’dom dans la Colline des Épines, dans les Tarides du Nord.', 0),
(13971, 'frFR', 'Le retour du kodo', 'Parlez à Kranal Fiss à la Ferme de Grol\'dom pour vous assurer que son kodo perdu est bien arrivé.', 'L\'énorme bête se redresse lentement sur ses pattes en faisant tomber de la terre des Tarides de ses membres revivifiés. Guidée par son instinct, elle se met en route d\'un pas lourd vers la ferme de Grol\'dom.$B$BVous voudrez probablement vérifier auprès de Kranal Fiss que le kodo est bien arrivé chez lui.', '', '', '', '', '', '', '', '', '', 'Parlez à Kranal Fiss à la Ferme de Grol’dom dans les Tarides du Nord, pour vous assurer que son kodo égaré est bien revenu au bercail.', 0),
(13972, 'frFR', 'De nouveau parmi les humains', 'Parlez à Gwen Armstead à Triste-bourg.', 'Enfin ! La potion de Krennan aura au moins fonctionné sur l\'un de vous autres worgens.$B$BVous devriez être capable de garder le dessus la plupart du temps, mais contrôlez vos émotions.$B$BLe maire Arsmtead voudra probablement vous parler. Gilnéas est attaquée et nous avons vraiment besoin que tout combattant apte prenne les armes.', '', '', '', '', '', '', '', '', '', '', 0),
(13973, 'frFR', 'La milice de Grol\'dom', 'Tuez 6 Pillards tranchecrins.', 'Ils sont venus de nulle part, $c ! Des hurans à perte de vue. Tant de piquants, de groins et de dents. Nous nous sommes repliés sur la ferme mais il en venait toujours plus.$B$BNos meilleurs défenseurs sont tombés au combat, et nous n\'avons aucune nouvelle du fermier Ralton. J\'ai besoin que vous partiez à l\'offensive pour moi ! Tenez ces porcs en respect pendant que je défends les blessés en attendant l\'arrivée des secours.', '', '', '', '', '', '', '', '', '', 'Retournez voir Una Griffe-de-loup à la Ferme de Grol\'dom, dans les Tarides du Nord.', 0),
(13974, 'frFR', 'Le petit paquet de Gluon', 'Gluon vous a demandé d’apporter le Petit paquet de Gluon à Flouz, au Refuge de Vent-d\'Argent.', 'Waouh !$b$bMatez-moi un peu ça ! C’est révolutionnaire ! La technologie des explosifs, qui est d’ailleurs la plus intéressante, va faire un bond en avant grâce à cette découverte !$b$bTous les gobelins du sud du Norfendre vont être verts de jalousie !$b$bCroyez-le ou non, j’ai amélioré la formule pour la rendre encore plus efficace !$b$bTenez. Apportez-en un échantillon au refuge de Vent-d\'Argent, au sud-est. Mon cousin, Flouz, saura peut-être comment l’utiliser pour aider la Horde à s’emparer des lieux.', '', '', '', '', '', '', '', '', '', '', 0),
(13975, 'frFR', 'Mener la caravane pour la Croisée', 'Parlez à Rocco Fouette-Jarret à la Ferme de Grol\'dom et escortez sa caravane jusqu\'à la Croisée.', '<Rocco vous tend un fusil qui vous rappelle quelque chose.>$B$BJ\'ai pris la liberté de nettoyer l\'arme de Halga pour vous. Je n\'ai sûrement pas besoin de vous prévenir de faire attention au recul. Parlez-moi quand vous serez $gprêt:prête; à partir pour la Croisée ! Thork vous attend là-bas. Surtout évitez de lui manquer de respect.$B$BNe faites pas d\'arrêts inutiles, $n, et si quelqu\'un s\'approche de trop près, donnez-lui juste un bon coup avec la crosse de votre fusil. Faites-nous honneur !', '', '', 'Caravane du carrefour escortée', '', '', '', '', '', '', 'Parlez à Thork à la Croisée, dans les Tarides du Nord.', 0),
(13976, 'frFR', 'Trois amis de la forêt', 'Allez voir Bolyun au Camp de Bolyun, en Orneval.', 'Ça vous dirait d’aller faire un tour dans le sud ? Je n’ai pas eu de nouvelles de trois de mes amis depuis longtemps. Je n’ose pas abandonner ma famille à cause de ces étranges tentacules qui surgissent du sol, au nord, et à cause de toute cette activité démoniaque.$B$BBolyun a établi son camp au sud-ouest de la forêt, juste au nord-ouest de ce maudit sanctuaire de Scarfeu. Alenndaar et Harlown l’y ont rejoint. Ils devraient être en sécurité, mais on ne sait jamais.$B$BMerci, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(13977, 'frFR', 'Production de masse', 'Flouz vous a demandé d’apporter la Poudre bang-bang de Gluon à Laguigne, à la Bidouillerie.', 'Waouh !! Vous avez VU ça ?!$b$bOn doit en fabriquer à la chaîne tout de suite !$b$bVoilà. Apportez le reste du matos à Laguigne. Vous le trouverez sur le chantier de notre nouvelle installation, juste à l’ouest d’ici.', '', '', '', '', '', '', '', '', '', '', 0),
(13979, 'frFR', 'Le cerveau gobelin', 'Procurez-vous la Tête de Sploseur.', 'Si ces fichus bombardements lancés depuis les machines gobelines cessaient, nous pourrions lancer une contre-offensive pour reprendre le refuge de Vent-d\'Argent !$B$BD’après mon expérience, les gobelins sont soit paresseux et improductifs, soit trop productifs et finissent par se tuer avec leurs propres explosifs. Malheureusement pour nous, ils sont formés par l’explosif boumgénieur en chef Sploseur.$B$BDirigez-vous vers la Bidouillerie, à l’ouest du refuge, et ne revenez que lorsque vous aurez la tête du boumgénieur en chef !', '', '', '', '', '', 'En espérant que sa tête n\'explosera pas !', 'Boumgénieur en chef Sploseur', '', '', 'Retournez voir la Chasseresse Jalin à la Flèche de Chimétoile, en Orneval.', 0),
(13980, 'frFR', 'À l’assaut de l’invisible', 'Laguigne, à la Bidouillerie, vous a demandé de tuer 12 Assassins d’Orneval.', 'Ils ne sont pas loin, $c. Et ils nous encerclent.$b$bMes hommes commencent à mourir les uns après les autres. Ce sont des attaques elfes, il n’y a aucun doute possible.$b$bOn dirait que votre raid sur Astranaar les a bien décidés à mettre un terme à notre avancée. Allez, un dernier effort pour échapper à la défaite !$b$bPrenez ces lunettes. Grâce à elles, vous pourrez voir même le plus sournois des elfes. Surveillez mes arrières le temps que je termine d’armer vos explosifs.', '', '', '', '', '', '', '', '', '', '', 0),
(13981, 'frFR', 'Ça va péter !', 'Informez la Chasseresse Jalin de l’existence de la Bombe, à la Flèche de Chimétoile en Orneval.', 'De toute évidence, c’est le plus gros explosif que vous ayez jamais vu. Mais qu’est-ce que les gobelins comptaient bombarder avec un tel engin ?$B$BÀ vos yeux, la bombe paraît presque terminée. Les gobelins semblent avoir soigné son élaboration : on dirait qu’elle résiste à toutes les attaques. Et elle est trop grosse pour que vous puissiez la déplacer.$B$BVous feriez mieux d’aller informer la chasseresse Jalin de l’existence de cette bombe, à la flèche de Chimétoile, au sud-ouest.', '', '', '', '', '', '', '', '', '', '', 0),
(13982, 'frFR', 'Les liens du cœur', 'Procurez-vous le Cœur de Kaliva pour Bolyun, au Camp de Bolyun.', 'Faites attention, $n. Kaliva est toujours dans les parages et quand elle nous a capturés, elle a clairement mentionné votre nom.$B$BSeul son cœur peut nous libérer de ces chaînes, mais je pense qu’elle vous a tendu un piège !', '', '', '', '', '', 'Immonde dominatrice démoniaque. Coupez-lui la tête !', 'Kaliva', '', '', 'Retournez voir Bolyun, au Camp de Bolyun, en Orneval.', 0),
(13983, 'frFR', 'Creuser sa propre tombe', 'Le Contremaître Laguigne vous a demandé de rassembler 3 Rouages en bronze, 3 Plaques de cuivre, et 5 Écrous d’assemblage.', 'Quand cette bombe sera terminée, on devra l’apporter à Saurboz.$b$bEt par « on », j’entends « vous ».$b$bAvec tous ces ennemis qui rôdent dans les parages, je vais devoir créer quelque chose d’exceptionnel si vous voulez avoir une chance de réussir.$b$bJe peux bricoler l’un de ces déchiqueteurs détraqués, mais il va me falloir quelques pièces détachées. Vous devriez pouvoir en trouver facilement dans les bois, à l’ouest.$b$bRassemblez-en quelques-unes le temps que je termine de travailler sur la bombe.', '', '', '', '', '', '', '', '', '', '', 0),
(13985, 'frFR', 'Nettoyer le sanctuaire', 'Tuez 12 démons au Sanctuaire de Scarfeu.', 'Il faut mettre un terme à l’invasion maléfique de la Légion ardente !$B$BVous avez vaincu l’un de leurs démons les plus puissants, $n, mais ils sont encore nombreux dans les bois, à l\'est du sanctuaire de Scarfeu.$B$BEn tant qu’$gami:amie; de la forêt, accepteriez-vous d’aller abattre ces infâmes créatures ? Vous devrez ensuite aller prévenir Grand-baobab, le grand ancien de guerre du sanctuaire d’Aessina, au nord-est.', '', 'Démons du Sanctuaire de Scarfeu abattus', '', '', '', '', '', '', '', 'Allez voir Grand-baobab au Sanctuaire d\'Aessina, en Orneval.', 0),
(13987, 'frFR', 'La bataille finale', 'Tuez 30 Envahisseurs démoniaques.', '$n, il faut absolument que vous m’aidiez ! Je ne pourrai pas repousser indéfiniment l’assaut démoniaque. Si je cède, Astranaar sera leur prochaine cible !$B$BJe vous en supplie, aidez-moi !', '', '', '', '', '', '', '', '', '', 'Allez voir Grand-baobab au Sanctuaire d\'Aessina, en Orneval.', 0),
(13988, 'frFR', 'Un problème croissant', 'Apportez les Yeux de Tonga au Sommet de Tête-tonnerre, au sud-ouest de Cabestan.', 'Un foisonnement de vie sur des terres incultes… Mon compagnon Jerrik m’a décrit des évènements similaires qui sont arrivés ailleurs dans les Tarides. Je dois m’en rendre compte par moi-même, mais je ne peux pas abandonner mon poste.$b$bTenez, $n, je vous prête mes « yeux ». Mon compagnon aigle me sert depuis que je suis né. Accompagnez-le jusqu’au sommet de Tête-tonnerre, où Jerrik vous attend, et nous examinerons le phénomène.$b$bPour arriver au sommet, suivez la route à l’est de la Croisée et tournez au sud quand vous atteindrez une grosse pierre couverte de peintures.', '', 'Yeux de Tonga emmenés au sommet', '', '', '', '', '', '', '', 'Parlez à Jerrik au Sommet de Tête-tonnerre, dans les Tarides du Nord.', 0),
(13989, 'frFR', 'Le roi des Vile-sylve', 'Placez la Bannière dent-rouge sur le Tertre du totem Vile-sylve. Ne laissez pas les furbolgs détruire la bannière avant que leur chef n\'arrive. Tuez le Chef Murgut.', 'Je n\'éprouve pas beaucoup de sympathie pour votre espèce, $r. Mais je veux sauver les furbolgs.$B$BEmportez cette bannière un peu au nord-est, dans le village des Pattes-vertes, et placez-la sur le tertre de leur totem. Ils considéreront cela comme une agression et essaieront de la détruire. Contenez leurs assauts jusqu\'à ce que leur chef, Murgut, apparaisse pour sauver l\'honneur de sa tribu, puis tuez ce traître !$B$BÉconomisez vos forces, mon $gami:amie;, car le combat promet d’être long.', '', '', '', '', '', 'Tuez le chef des furbolgs.', 'Chef Murgut', '', '', 'Retournez voir Krolg à la Hutte de Krolg, en Orneval.', 0),
(13991, 'frFR', 'La paie dérobée', 'Parlez à Gazrog près de l\'entrée de Cabestan.', 'Eh bien, $n. J\'admets que vous avez votre place dans ma Horde bien-aimée. Vous m\'avez montré votre force, votre habileté, votre sens de l\'initiative... Même Thork a récemment mentionné votre nom, et pourtant ni lui ni moi ne nous laissons facilement impressionner. Beau travail.$B$BIl est temps à présent que vous fassiez votre part du travail. La paie des gardes de la Croisée pour la semaine a disparu. Gazrog à Cabestan mène l\'enquête. Allez lui parler !$B$BIl suffit de suivre la route à l\'est d\'ici vers la côte.', '', '', '', '', '', '', '', '', '', 'Parlez à Gazrog près de l’entrée de Cabestan, dans les Tarides du Nord.', 0),
(13992, 'frFR', 'Une petite diversion', 'Tuez 8 Centaures kolkars.', 'J\'ai été envoyé ici en reconnaissance pour observer l\'activité centaure. J\'ai surveillé leurs moindres mouvements pendant des jours ! Il est temps pour moi de partir discrètement, mais ils ont cerné cette oasis.$B$BVous avez l\'air d\'une personne dangereuse. Pouvez-vous faire beaucoup de bruit pour moi ? Provoquez-les ! Tuez-les au hasard. Pendant qu\'ils seront à votre recherche, je me glisserai hors d\'ici pour rapporter mes informations à Regthar Seuil-de-mort.', '', 'Centaures kolkars tués', '', '', '', '', '', '', '', 'Retournez auprès de Ta\'jari aux Bassins Oubliés, dans les Tarides du Nord.', 0),
(13994, 'frFR', '[PÉRIMÉ]', 'Parlez à l\'Inquisiteur Blackwell à Triste-bourg.', 'Écoutez, $n. Vous devez faire ce que l\'inquisiteur vous a demandé.$B$BIl affirme que la Horde attaque Gilnéas. Si c\'est vrai, alors quelqu\'un doit en informer le clan Cœur-de-loup avant qu\'il ne soit trop tard.$B$BSans compter que Balvus Cœur-de-loup m\'écorcherait vivant s\'il découvrait que je vous ai $glaissé:laissée; moisir sur les réserves de Grisetête.', '', '', '', '', '', '', '', '', '', '', 0),
(13995, 'frFR', 'Le roi de la montagne des centaures', 'Veillez à ce que Gorgal Balafre-furieuse reste en vie alors qu’il se bat contre les centaures et aidez-le à tuer Kurak.', 'Nous avons été envoyés ici pour observer les déplacements des centaures kolkars, mais au bout d\'une semaine à observer ces saletés d\'animaux galoper partout autour de cette oasis, ça me démange vraiment d\'aller leur faire goûter ma hache. Qu\'en dites-vous, $c ? Vous voulez faire quelques ravages avec moi ?$B$BVoyons un peu si nous pouvons attirer l\'attention de leur guerrier le plus puissant, Kurak.', 'Créer de l\'agitation', '', '', '', '', 'Sa présence est un affront pour les sens. Même ses mouches ont des mouches.', 'Kurak', '', '', 'Parlez à Gho’dass à l’Oasis Stagnante, dans les Tarides du Nord.', 0),
(13996, 'frFR', 'Pouvez-vous prendre cette quête pendant que je suis en combat ?', 'ELM Cible d\'hébétement sur l\'Île des Concepteurs vous a demandé de tuer 5 ELM attaquants pour Dan et la Grande justice !', 'Votre mission, si vous arrivez à lire ceci alors que je suis en combat, consiste à tuer cinq de ces maudits kobolds qui me maintiennent tout le temps en combat.$B$BRien que le fait de pouvoir lire ceci est une grande VICTOIRE ! Dan est génial, pas vrai ?!!', '', '', '', '', '', '', '', '', '', '', 0),
(13998, 'frFR', 'Les champignons, une valeur sûre', 'Plantez une Culture fongique près de l\'Oasis Stagnante et observez les résultats.', 'J\'ai mis en culture ces spores étranges que vous avez trouvées avec un mélange raffiné de... composants... que j\'affectionne particulièrement. Je suis impatient de voir comment mes spores améliorées réagiront aux eaux des oasis de la Croisée.$B$BL\'oasis Stagnante au sud-est devrait nous offrir un site exempt de toute contamination pour notre expérience. Il vous suffit de planter cette culture dans le sol humide n\'importe où autour de l\'oasis et de noter les résultats pour moi.$B$BN\'oubliez surtout pas de vous couvrir la bouche, $c.$B$B<Helbrim vous décoche un sourire désarmant.>', 'Culture fongique plantée', '', '', '', '', '', '', '', '', 'Rendez compte de vos découvertes à l\'Apothicaire Helbrim à la Croisée, dans les Tarides du Nord.', 0),
(13999, 'frFR', 'Trafic de champis', 'Apportez les Recherches de Helbrim à Sashya à Cabestan, dans les Tarides du Nord.', 'Imaginez un peu le potentiel, $n ! Des vecteurs fongiques à croissance rapide pour toutes sortes de toxines. Mes camarades de Fossoyeuse voudront en être informés.$B$BVoici mes notes et quelques échantillons supplémentaires. Si nous faisons vite, nous pourrons profiter du prochain bateau pour les royaumes de l\'Est. Prenez la route à l\'est d\'ici et suivez-la jusqu\'à la ville gobeline de Cabestan. Cherchez la Taverne de la quille brisée vers le côté sud de la ville et apportez-les à mon associée Sashya à l\'intérieur.', '', '', '', '', '', '', '', '', '', 'Apportez les Recherches de Helbrim à Sashya à Cabestan, dans les Tarides du Nord.', 0),
(14001, 'frFR', 'Les capsules de sauvetage gobelines', 'Portez secours à 6 Survivants gobelins.', '$n, je suis navré, je croyais que vous étiez $gmort:morte; !$B$BC’est juste incroyable. Notre navire s’est retrouvé au milieu d’une bataille entre l’Alliance et la Horde !$B$BNos frères et sœurs ont besoin d’être secourus.$B$B<Il montre toutes les capsules de sauvetage autour de vous.>$B$BJe crois que je vais encore un peu rester assis pour reprendre mon souffle. Pourriez-vous les rejoindre à la nage et les aider à sortir des capsules ? Prenez mes palmes thermohydratiques, vous irez plus vite.$B$BDites à Chipie que je viendrai bientôt.', '', 'Survivants gobelins secourus', '', '', '', '', '', '', '', 'Faites votre rapport à Chipie Serrelavis sur le Rivage de l’Épave, sur les Îles Perdues.', 0),
(14003, 'frFR', 'La réparation du samophlange', 'Apportez le Samophlange cassé à Brak Rouspétuyère, dans le campement.', 'Zut, ce n’était pas prévu, ça. Je pense que je l’ai cassé.$b$bMais pas de panique. Rendez-moi service : apportez ça à Brakk, dans le camp. Il retapera ce bibelot en deux temps, trois mouvements !', '', '', '', '', '', '', '', '', '', 'Apportez le Samophlange cassé à de Brak Rouspétuyère, dans le campement.', 0),
(14004, 'frFR', 'Retour au samophlangeur', 'Rapportez les Débris du samophlange rafistolé à Krachevalve, à l\'Avant-poste de Potuyère. Parlez à Wenikee pour qu’elle vous y téléporte directement.', 'Eh bien, ça n\'a pas marché. L’intégrité structurelle du samophlange est à son plus-bas historique. Je pourrais ajouter plus de cadrans et peut-être un levier ou deux pour arranger ça, mais… ce serait peut-être pire que mieux.$B$BMais regardez ce que j\'ai découvert en bloquant la soupape de sûreté et en faisant sauter le couvercle du carter de différentiel : le poinçon personnel du « Chef Cuivroncteur ».$b$bRapportez ceci à Krachevalve et dites-lui de trouver ce génie de Cuivroncteur. Quand vous en aurez terminé ici, vous n’aurez qu’à me parler et je vous expédierai grâce au téléporteur de Brak.', '', '', '', '', '', '', '', '', '', 'Rapportez les Débris du samophlange rafistolé à Krachevalve, à l\'Avant-poste de Potuyère, dans les Tarides du Nord. Parlez à Wenikee pour qu’elle vous y téléporte directement.', 0),
(14005, 'frFR', 'La vengeance d\'Élune', 'Utilisez les pouvoirs qui vous ont été accordés par Tarindrella pour vous frayer un chemin jusqu’au Cœur de la corruption et détruisez-le.', 'Teldrassil se nettoie de la corruption qui a perverti sa croissance pendant ces années. Une tumeur maligne s’est formée près de la lisière, au sud. Nous avons l’occasion de l’attaquer et de faire disparaître la source de gangremousse qui a perverti les Pins-tordus, les sylvains et tout le reste.$B$BGrâce à l’eau que vous avez récoltée dans les puits de lune et grâce à la puissance retrouvée de Teldrassil, je vais vous accorder de grands pouvoirs pour un court moment. Mettez un terme à cette corruption, $n.', '', '', '', '', '', 'Lorsque Malfurion a arraché les restes de Xavius de Teldrassil, l’Arbre-monde a été libéré d’un grand poids. Un vestige de Xavius demeure pour tourmenter les elfes, mais le champion d\'Élune qui libérera entièrement l\'arbre approche.', 'Rameau de corruption', '', '', 'Retournez voir Tarindrella aux Bassins d\'Arlithrien.', 0),
(14006, 'frFR', 'Lire le manuel', 'Reconstituez le Manuel du samophlange.', 'À l’époque où j’étais dans l’Union des bricoleurs, le chef Cuivroncteur était le meilleur ingénieur que nous avions. Il est parti pour la KapitalRisk peu avant que je quitte l’union et il a emmené ses meilleures technologies avec lui. Il gardait bien ses secrets et n’en divulguait que de petits fragments à ses collaborateurs les plus fidèles.$b$bSi c’est lui qui a construit le samophlange, il doit probablement en détenir le manuel. La dernière fois que j’en ai entendu parler, il travaillait tout près d’ici, à l’entrée de la mine des Pierriers au nord-est. Qu’il vous donne le manuel, ensuite vous rassemblerez les pages auprès de ses collaborateurs.', '', '', '', '', '', '', '', '', '', 'Apportez le Manuel à Krachevalve à l\'Avant-poste de Potuyère, dans les Tarides du Nord.', 0),
(14007, 'frFR', 'Le tir assuré', 'Atteignez le Niveau 3 pour apprendre le Tir assuré, puis utilisez-le 3 fois sur un Mannequin d’entraînement.', 'Je m’appelle Bamm Mégabombe et je suis votre maître de classe personnel, $gm’sieur:m’dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l’art d’être $gun:une:c; $c.\n\nLe secret, c’est de gagner de l’expérience, et vous apprendrez rapidement à en faire encore plus. Ça vous en bouche un coin, pas vrai ?$B$BAlors accumulez de l’expérience, et quand vous aurez découvert une nouvelle compétence, revenez me la montrer sur un mannequin d’entraînement.', '', 'S’exercer au Tir assuré', '', '', '', '', '', '', '', 'Parlez à Bamm Mégabombe au Quartier général de la SCK, sur Kezan.', 0),
(14008, 'frFR', 'Nova de givre', 'Atteignez le Niveau 3 pour apprendre la Nova de givre, puis lancez-la 2 fois sur un Mannequin d’entraînement.', 'Je m’appelle Bulle Briquet et je suis votre maître de classe personnel, $gm’sieur:m’dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l’art d’être $gun:une:c; $c.\n\nLe secret, c’est de persévérer dans cette voie, et vous apprendrez rapidement à en faire encore plus. Ça vous en bouche un coin, pas vrai ?$B$BAlors gagnez de l’expérience, et quand vous aurez découvert une nouvelle compétence, revenez me la montrer sur un mannequin d’entraînement.', '', 'Nova de givre pratiquée', '', '', '', '', '', '', '', 'Parlez à Bulle Briquet au Quartier général de la SCK, sur Kezan.', 0),
(14009, 'frFR', 'Apprendre le mot', 'Atteignez le Niveau 3 pour apprendre le Mot de l’ombre : Douleur, puis lancez-le 3 fois sur un Mannequin d’entraînement.', 'Je m’appelle sœur Écumelor et je suis votre maître de classe personnel, $gm’sieur:m’dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l’art d’être $gun:une:c; $c.\n\nLe secret, c’est de gagner de l’expérience, et vous apprendrez rapidement à en faire encore plus. Ça vous en bouche un coin, pas vrai ?$B$BAlors accumulez de l’expérience, et quand vous aurez découvert une nouvelle compétence, revenez me la montrer sur un mannequin d’entraînement.', '', 'Mot de l’ombre : Douleur pratiqué', '', '', '', '', '', '', '', 'Parlez à Sœur Écumelor au Quartier général de la SCK, sur Kezan.', 0),
(14010, 'frFR', 'L’éviscération', 'Atteignez le Niveau 3 pour apprendre l’Éviscération, puis utilisez-la 3 fois sur un Mannequin d’entraînement.', 'Je m’appelle Fugace Coutelard et je suis votre maître de classe personnel, $gm’sieur:m’dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l’art d’être $gvoleur:voleuse;.\n\nÉcoutez, y a pas de secret : gagnez de l’expérience, et vous découvrirez toujours plus de techniques. Ça vous en bouche un coin, pas vrai ?$B$BAllez, du vent ! Engrangez de l’expérience, et quand vous aurez appris une nouveauté, venez l’essayer sur l’un de ces mannequins d’entraînement.', '', 'S’exercer à l’Éviscération', '', '', '', '', '', '', '', 'Parlez à Fugace Coutelard au Quartier général de la SCK, sur Kezan.', 0),
(14011, 'frFR', 'La frappe primordiale', 'Atteignez le Niveau 3 pour apprendre la Frappe primordiale, puis utilisez-la 2 fois sur un Mannequin d’entraînement.', 'Je m’appelle Maxx Avalanche et je suis votre maître de classe personnel, $gm’sieur:m’dame;.$B$BOn parle pas mal de vous, par ici, alors je me suis laissé dire que vous auriez besoin de conseils. Et ça, ça me connaît !$B$BEn vous améliorant, vous deviendrez vite capable d’accomplir de plus en plus de choses, nouvelles et surprenantes. Et croyez-moi, ça marche. On me paie pour raconter ça à tout le monde.$B$BQuoi qu’il en soit, devenez $gun meilleur chaman:une meilleure chamane;, puis utilisez vos nouvelles compétences sur un mannequin d’entraînement au sud-est.', '', 'Frappe primordiale pratiquée', '', '', '', '', '', '', '', 'Parlez à Maxx Avalanche au Quartier général de la SCK, sur Kezan.', 0),
(14012, 'frFR', 'Corruption', 'Atteignez le Niveau 3 pour apprendre la Corruption, puis lancez-la 3 fois sur un Mannequin d’entraînement.', 'Je m’appelle Doigt Bolik et je suis votre maître de classe personnel, $gm’sieur:m’dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l’art d’être $gun:une:c; $c.\n\nLe secret, c’est de gagner de l’expérience, et vous apprendrez rapidement à en faire encore plus. Ça vous en bouche un coin, pas vrai ?$B$BAlors accumulez de l’expérience, et quand vous aurez découvert une nouvelle compétence, revenez me la montrer sur un mannequin d’entraînement.', '', 'Corruption pratiquée', '', '', '', '', '', '', '', 'Parlez à Doigt Bolik au Quartier général de la SCK, sur Kezan.', 0),
(14013, 'frFR', 'À la charge !', 'Atteignez le Niveau 3 pour apprendre la Charge, puis utilisez cette technique sur un Mannequin d’entraînement.', '<Le Mécano-guerrier NX-01 s’active.>$B$BIndividu $n détecté. Je suis le Mécano-guerrier NX-01.$B$BAvertissement : expérience insuffisante repérée ! Veuillez gagner plus d’expérience pour apprendre de nouvelles compétences.\n\nFaites une démonstration de ces nouvelles compétences sur les mannequins d’entraînement pour continuer.', '', 'S’exercer à la Charge', '', '', '', '', '', '', '', 'Parlez au Mécano-guerrier NX-01 au Quartier général de la SCK, à Kezan.', 0),
(14014, 'frFR', 'Rapportez-nous nos affaires !', 'Récupérez 8 Caisses d\'outils.', 'Nos bombes et nos outils ! Ces singes sournois, à l\'est, les ont tous volés au beau milieu de la nuit !$B$BPouvez-vous y aller et nous rapporter nos affaires, $n ? Sans ces outils, nous n\'avons aucun moyen de quitter cette île !', '', '', '', '', '', '', '', '', '', 'Retournez voir Chipie Serrelavis sur le Rivage de l’Épave, sur les Îles Perdues.', 0),
(14019, 'frFR', 'Arrêtez leurs singeries', 'Nourrissez 10 Singes lanceurs de bombes en leur lançant des Bananes au nitro-potassium.', 'Nous avons un sérieux problème avec les singes dans la jungle, à l’est. Ils ont volé tous nos explosifs, et maintenant ils s’amusent à les lancer.$B$BIls nous visent même, parfois !$B$BJ’ai demandé à Bulle Briquet de mettre un peu de nitro dans ces bananes. Aucun singe ne peut résister à un régime de bananes !$B$BTout ce que vous avez à faire, c\'est d’aller par là et de les nourrir.', '', 'Singes lanceurs de bombes nourris', '', '', '', '', '', '', '', 'Retournez voir Bamm Mégabombe sur le Rivage de l’épave, dans les Îles Perdues.', 0),
(14021, 'frFR', 'Troubles mineurs', 'Escortez le Mineur effrayé à travers la Caverne de kaja\'mite.', 'Des singes mineurs dotés d\'intelligence !$B$BIl y en a partout à l\'intérieur de la caverne, avec… des pioches ! Il y a là quelque chose de pas naturel, et je suis sûr que c\'est à cause de cette kaja\'mite !$B$BAucun de mes mineurs n\'est sorti. Je n\'en ai presque plus ! Vous voyez dans quelle situation je me trouve, $n.$B$B<Le contremaître baisse la voix.>$B$BCes gars sont loin d’être aussi bons que mon vieux groupe de trolls de la jungle. Ah, c\'était le bon temps.$B$BPeut-être que vous pourriez escorter mon dernier mineur dans la caverne et faire en sorte que les singes ne s’approchent pas de lui ? Il nous faut cette kaja\'mite !', '', 'Le minage du minerai de kaja\'mite est un véritable succès !', '', '', '', '', '', '', '', 'Retournez voir le Contremaître Méchumide à l\'extérieur de la Caverne de kaja\'mite, sur les Îles Perdues.', 0),
(14026, 'frFR', 'Tout a commencé par un gros boum', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14029, 'frFR', 'La fin du siège', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14031, 'frFR', 'Immortaliser l’inconnu', 'À l’aide de votre Clic-clac-flash de la SCK, prenez des photos des trois peintures rupestres et de l’autel pygmée là où vous voyez des appareils photos.', 'Salut, $n, il y a d’étranges peintures rupestres et d’autres reliques dans la grotte.$B$BPensez-vous que vous pourriez utiliser le clic-clac-flash de la SCK intégré à votre ceinture pour prendre des photos des endroits indiqués ? Ah, profitez-en pour prendre également une photo de l’autel qui se trouve au fond de la grotte.$B$BJe parie que ces informations intéresseront Chipie.', '', 'Peinture rupestre 1 prise en photo', 'Peinture rupestre 2 prise en photo', 'Peinture rupestre 3 prise en photo', 'Autel pygmée pris en photo', '', '', '', '', 'Retournez voir Chipie Serrelavis sur le Rivage de l’Épave, sur les Îles Perdues.', 0),
(14034, 'frFR', 'Racketter Foote', 'Prenez les Plans du navire à l\'Ingénieur en chef Foote à la Taverne de la quille brisée, à Cabestan.', 'Toutes ces nouvelles frictions entre l\'Alliance et la Horde allaient mener à des bénéfices exceptionnels, jusqu\'à ce que le contre-amiral Hartley débarque dans MON port et commence à me mettre des bâtons dans les roues. Il recherche et saisit les vaisseaux portant les couleurs de la Horde dans le but de les priver de l\'usage d\'un port neutre.$B$BJe ne vais pas laisser un gros balourd d\'humain tailler dans mes profits ! Allez me chercher les plans de son vaisseau amiral. L\'ingénieur en chef de Hartley est en train de se saouler à la Taverne de la quille brisée juste en haut de la colline...', '', '', '', '', '', 'Il détient les schémas dont nous avons besoin.', 'Ingénieur en chef Foote', '', '', 'Apportez les plans à Gazleu à Cabestan, dans les Tarides du Nord.', 0),
(14038, 'frFR', 'Une mine attachante', 'Plantez une Mine-ventouse à l’endroit le moins épais de la coque du Bellipotent.', '<Gazleu déplie le plan sur la table et pointe un doigt minuscule à l\'arrière du bateau, sous la ligne de flottaison.>$B$BLà ! La coque est la plus mince à cet endroit, là où le vilebrequin actionne le mécanisme des roues à aubes. Et c\'est juste à côté de la sainte-barbe !$B$B$n, on ne pourrait me tenir pour responsable si quelque $c $gplein:pleine:c; d\'initiative devait poser une mine-ventouse à cet endroit de la coque. Pas même si je lui fournissais la mine. Et que je $gle:la:c; payais. Grassement. Le navire est ancré juste au sud-est d\'ici... allez-y !$b$bQuand ce sera fait, contactez-moi grâce à ce gnomotophone volé.', '', 'Bellipotent miné', '', '', '', '', '', 'La voix de Gazleu grésille dans le gnomotophone volé…', 'Gazleu', 'Parlez à Gazleu à Cabestan, dans les Tarides du Nord.', 0),
(14039, 'frFR', 'Le foyer des Kaldorei', 'Remettez le Récipient rempli à Tyrande Murmevent à Darnassus.', 'C’est un grand honneur que de vous avoir $grencontré:rencontrée;. Vous êtes le témoignage vivant de la noblesse de votre race.$B$BAllez, et accomplissez cette dernière tâche. Apportez cette eau à Tyrande Murmevent à Darnassus.', '', '', '', '', '', '', '', '', '', '', 0),
(14042, 'frFR', 'Munitions à gogo', 'Détruisez 5 Réserves de munitions de Theramore le long de la côte.', 'Hartley a dû décharger toutes ses munitions sur la plage. Faisons-lui une surprise, $n !$B$BFilez le long de la côte pour trouver ses dépôts de munitions. Faites-les sauter et comme ça, il se retrouvera échoué, à terre et sans armes pendant les réparations du Bellipotent.$B$BAllez-y et je vous retrouverai ici même, à Cabestan.', '', 'Réserves de munitions détruites', '', '', '', 'La voix de Gazleu grésille dans le gnomotophone volé…', 'Gazleu', '', '', 'Retournez voir Gazleu à Cabestan dans les Tarides du Nord.', 0),
(14045, 'frFR', 'Trouver le baron de Longrivage', 'Parlez au Baron de Longrivage, le célèbre pirate, après l’avoir trouvé dans les Tarides du Nord.', 'Ce sale flibustier de baron de Longrivage était la terreur de ces eaux avant que l’Alliance ne démolisse sa flotte et n’embastille les survivants. Est-ce que je suis content pour autant ? Est-ce que j’ai l’air d’avoir de la joie au cœur, $n ?$b$bNon ! Avant d’être capturé, Longrivage a détourné quelques-uns de mes meilleurs chargements. La rumeur dit qu’il a enterré son butin avant de se faire serrer. Je veux récupérer ces marchandises ! Trouvez Longrivage dans le camp de l’Alliance, juste au sud d’ici et faites-lui cracher l’emplacement de MON trésor.', '', '', '', '', '', '', '', '', '', 'Parlez au Baron de Longrivage, le célèbre pirate, après l’avoir trouvé dans les Tarides du Nord.', 0),
(14046, 'frFR', 'Les exigences du baron', 'Si vous lui faites confiance, parlez au Baron de Longrivage pour le libérer de ses menottes.', 'Ch’suis mûr pour la potence, matelot, ça c’est sûr. Ce trésor, il ne me sert à rien pour le moment…$b$bÀ moins que je l’utilise pour me sauver la mise… Je vais faire un marché avec vous, $r. Libérez-moi de ces fers et je vous dirai où mon magot est enfoui.$b$bOh, vous pouvez me croire sur parole, $gl’ami:chérie;. J’étais un vrai baron, dans le temps, vous savez.', '', 'Marché conclu avec le baron de Longrivage', '', '', '', '', '', '', '', 'Si vous lui faites confiance, parlez au Baron de Longrivage pour le libérer de ses menottes.', 0),
(14049, 'frFR', 'Une drôle de carte', 'Procurez-vous la Tête tatouée exposée à l\'entrée de la base de l\'Alliance.', 'Voilà le marché, marin d’eau douce : Pour protéger ma carte au trésor, je l’ai tatouée sur le crâne de mon second.$b$bBien sûr, il est mort à l’heure qu’il est, ainsi que la plupart de mon équipage. L’Alliance ne connaît même pas sa chance : la tête de mon second est pendue à un arbre à l’entrée de ce camp.$b$bAttrapez cette tête et apportez-la à Gazleu, à Cabestan.', '', '', '', '', '', '', '', '', '', 'Remettez la Tête tatouée à Gazleu à Cabestan, dans les Tarides du Nord.', 0),
(14050, 'frFR', 'La fortune de Gazleu', 'Gazleu veut que vous déterriez son trésor en haut des falaises qui surplombent Cabestan.', 'Sabordelipopette, vous aviez raison ! Il y a une carte tatouée sur ce crâne.$B$BCe maudit Baron. Il a enterré mon trésor juste sous mon nez. Ou plutôt au-dessus de ma tête. La carte indique un endroit sur les hauteurs qui surplombent Cabestan, au sud.$B$BSuivez la route à l\'ouest en sortant de la ville, montez en haut de la colline, dirigez-vous vers le sud, puis reprenez la direction de la côte et cherchez un arbre énorme qui surplombe la baie. Cherchez mon trésor, et je le partagerai avec vous !', '', '', '', '', '', '', '', '', '', 'Retournez voir Gazleu à Cabestan dans les Tarides du Nord.', 0),
(14052, 'frFR', 'Fomenter avec Tony', 'Parlez à Tony Deux-Défenses sur l’Île de la Dispute, dans les Tarides du Nord.', 'Cette histoire de pirates freine vraiment mon commerce. Le cap’taine Garvey attaque tout ce qui bouge, même les navires dont les armateurs m’ont acheté l’assurance « tous risques » bidon. Il faut mettre ces pirates au pas, et vite !$b$bJ’ai l’homme qu’il nous faut pour ça : un des hommes de Garvey avec qui je suis en cheville. Il m’a proposé d’organiser une petite mutinerie dans l’équipage. Une fois que ces gars travailleront pour nous, ce sera du gâteau, vous saisissez ?$b$bParlez à mon contact sur l’île de la Dispute, au sud. Il s’appelle Tony Deux-Défenses.', '', '', '', '', '', '', '', '', '', 'Parlez à Tony Deux-Défenses sur l’Île de la Dispute, dans les Tarides du Nord.', 0),
(14056, 'frFR', 'Glomp trône dessus', 'Tuez Glomp et volez-lui son Butin.', 'Quoi ? C’est Tournoupette tout craché, de vouloir une mutinerie au rabais.$b$bPas grave, mec, on peut le faire. Tout d’abord, il nous faut le blé. Le cap\'taine Garvey, il aime bien accumuler le butin au fur et à mesure des pillages. C’est de l’argent que je peux utiliser pour payer mes mutins triés sur le volet, tu vois ?$b$bLa trésorerie, elle est juste en dehors de cette caserne, et pour accéder au trésor, vous devrez d’abord vous occuper du « trésorier » du cap\'taine Garvey, tu saisis ? Seulement, Glomp, l’est pas du genre à se laisser bousculer. J’ai essayé de le bousculer, une fois. Pas bougé d’un cheveu, le gars.', '', '', '', '', '', 'Prenez garde, son centre de gravité est bas.', 'Glomp', '', '', 'Apportez le Butin à Tony Deux-Défenses sur l’Île de la Dispute, dans les Tarides du Nord.', 0),
(14057, 'frFR', 'Des flingues. Il nous faut des flingues.', 'Rassemblez 6 Carabines lourdes naines.', 'Alors, une bonne mutinerie, elle doit avoir une vraie puissance de feu, vous voyez ? Le cap\'taine Garvey, il s’est gardé les meilleures armes : toute une cargaison de gros fusils à silex nains. Il les planque près de lui, dans le bâtiment de l’autre côté de l’île. Dégottez-moi six de ces fusils et je les distribuerai à mes futurs officiers…', '', '', '', '', '', '', '', '', '', 'Remettez les Carabines à Tony Deux-Défenses sur l’Île de la Dispute, dans les Tarides du Nord.', 0),
(14063, 'frFR', 'La mutinerie, camarade !', 'Soufflez dans le Cor de signal pirate pour donner l’ordre à Tony Deux-Défenses et son équipage d’aborder la Dague de la vierge. Aidez-le à tuer Alicia Cuthbert qui se trouve sur le pont inférieur.', 'On arrive à ma partie préférée de la mutinerie : le massacre ! Chez les pirates, on se fiche de savoir qui commande. La vraie question, c’est qui contrôle les bateaux. La Dague de la vierge, l’ancien navire amiral de Garvey, est à l’ancre à la pointe est de cette île. Il y a laissé son plus fidèle officier pour monter la garde : Alicia Cuthbert. Quand on l’aura neutralisée, le navire sera à nous, et la mer avec, mec.$b$bJe vais faire embarquer mes hommes dans des canots. Je veux que vous montiez à bord de la Dague et que vous sonniez de cette corne sur le pont. Ce sera notre signal pour l’abordage général. Ha-haarh !', '', 'Dague de la vierge prise', '', '', '', '', '', '', '', 'Faites part de votre réussite au Maître des quais Tournoupette à Cabestan, dans les Tarides du Nord.', 0),
(14066, 'frFR', 'Enquête sur les débris', 'Trouvez la caravane accidentée sur la route entre Cabestan et la Croisée et fouillez les environs à la recherche d\'indices.', 'Il y a peu, une cargaison d\'argent a été volée en chemin entre ici et la Croisée. Cet argent était destiné à payer les gardes, et nous voulons le récupérer.$B$BJe vais interroger les gens par ici à la recherche d\'indices, mais je veux que vous alliez enquêter sur la scène du crime. Partez vers l\'ouest à la recherche d\'un chariot de caravane accidenté juste au nord de la route entre ici et la Croisée. Découvrez qui a pris notre argent, et récupérez-le !', 'Site de la caravane fouillé', '', '', '', '', '', '', '', '', 'Trouvez la caravane accidentée sur la route entre Cabestan et la Croisée et fouillez les environs à la recherche d\'indices.', 0),
(14067, 'frFR', 'L\'argent volé', 'Tuez 8 Ravageurs et 4 Faucheurs solécailles et localisez l\'Argent volé.', 'Il apparaît clairement que ces raptors sont les seuls responsables du vol de l\'argent de la Horde.$B$BL\'heure est venue de donner une bonne leçon à ces sales bêtes.', '', '', '', '', '', '', '', '', '', 'Remettez l’Argent volé à Gazrog à l’extérieur de Cabestan, dans les Tarides du Nord.', 0),
(14068, 'frFR', 'La prive au piève', 'Utilisez le Piève à raptor de Kala\'ma pour capturer 5 Raptors rétréfis.', 'Piéver des raptors, fa peut f\'avérer danvereux, mais v\'ai confu de nouveaux pièves pour réduire les rifques.$B$BPovez le piève fur le fol et il pouffera un cri de raptor, fe qui devrait les attirer vufqu\'au piève.$B$BQuand un raptor marfe fur un piève à raptor, fa le rétréfit fur-le-famp pour qu\'il foit moins danvereux. F\'est fuper fafile ! Ve ferais bien tout fa moi-même, mais ve fuis tombé fur le roi Griffe-aférée, réfemment.', '', '', '', '', '', '', '', '', '', 'Apportez les Raptors rétréfis à Kala’ma dans les Tarides du Nord.', 0),
(14069, 'frFR', 'L\'aide n\'est plus ce qu\'elle était', 'Corriger le comportement de 8 Trolls défiants.', 'J\'ai échoué ! J\'ai fait tout mon possible pour remplir les quotas de production de Kaja’Cola, mais vous savez comment sont les esclaves trolls, de nos jours. Difficile de trouver une assistance efficace !$B$BVotre façon toute personnelle de régler les problèmes serait très utile. Une décharge de votre gadgetoceinture gobeline devrait faire l\'affaire. Si nous arrivons à corriger quelques trolls défiants, les autres suivront sans broncher.$B$BNous devons poursuivre la production de Kaja’Cola ou c\'est nous tous qui subirons le courroux du prince marchand !', '', 'Comportement corrigé', '', '', '', '', '', '', '', 'Retournez voir le Contremaître Mèchumide au Quartier général de la SCK, sur Kezan.', 0),
(14070, 'frFR', 'Faites-le vous-même', 'Rossez Bruno Lignifuge, Frankie Glissécrou, Jack le Marteau et Savon Magee.', 'Nous devons envoyer un message à plusieurs mauvais payeurs. Bien sûr, cette racaille se cache dans Trimeville. Je sais que vous détestez devoir aller dans ces taudis, boss, mais que pouvons-nous faire ?$B$B<Chipie feuillette rapidement ses papiers.>$B$BJ\'ai là tous les noms.$B$BPuis-je vous suggérer une petite « visite personnelle » ? Un ou deux coups bien placés enverraient également un message à vos autres débiteurs ET à vos concurrents.$B$BIl ne faut pas prendre $n à la légère !', '', 'Bruno Lignifuge rossé', 'Frankie Glissécrou rossée', 'Jack le Marteau rossé', 'Savon Magee rossé', '', '', '', '', 'Retournez voir Chipie Serrelavis au Quartier général de la SCK, sur Kezan.', 0),
(14071, 'frFR', 'Rouler avec mes potes', 'Faites une virée en Voiture de sport et ramassez vos amis Crack, Gobeur et Izzy.', '$n, j\'ai entendu dire que vous organisez une fête d\'entreprise qui éclipsera toutes les autres ! Mes études indiquent que si vous êtes $gvu:vue; en train de vous amuser à cette fête, votre quotient promotionnel grimpera en flèche et atteindra des sommets !$B$BEn gardant ces données en tête, puis-je vous suggérer d\'aller faire un tour avec la voiture de sport de votre entreprise et de passer prendre vos amis en ville ?$B$BOh et n\'oubliez pas ce que j\'ai fait pour vous quand tout ça aura porté ses fruits et que vous serez $gle nouveau prince marchand:la nouvelle princesse marchande;, d\'accord ?', '', 'Clés de la voiture de sport utilisées', 'Izzy récupérée', 'Crack récupéré', 'Gobeur récupéré', '', '', '', '', 'Retournez voir Megs Déchiqueffroi au Quartier général de la SCK, sur Kezan.', 0),
(14072, 'frFR', 'Verog passe à la trappe', 'Retrouvez 4 pages d’Informations des centaures autour de l’Oasis Stagnante.', 'Regthar Seuil-de-mort m’a envoyée ici pour épier les activités des centaures, mais leur chef est difficile à identifier. J’ai appris qu’il s’appelle « Verog le Derviche », mais j’ignore toujours où il se trouve.$b$bPouvez-vous m’aider à creuser un peu la question ? Je sais que les centaures ont l’intelligence d’une huître, mais leurs camps sont souvent jonchés de renseignements importants sur leurs activités. Fouillez les tentes des centaures tout autour de l’oasis Stagnante et rapportez-moi des informations.', '', '', '', '', '', '', '', '', '', 'Apportez les Informations à Gho’dass à l’Oasis Stagnante, dans les Tarides du Nord.', 0),
(14073, 'frFR', 'Des renforts pour Seuil-de-mort', 'Présentez-vous à Regthar Seuil-de-mort à son avant-poste à l\'ouest de la Croisée, dans les Tarides du Nord.', '$n ! Votre réputation s\'étend au sein de la Horde. J\'ai eu vent de rapports en provenance des bassins Oubliés et de l\'oasis Stagnante disant que vous avez été un vrai fléau pour nos ennemis centaures. Très beau travail.$B$BRegthar Seuil-de-mort est en charge de nos opérations contre les centaures dans toutes les Tarides du Nord. Il pourrait avoir besoin d\'$gun courageux:une courageuse:c; $c comme vous pour renforcer ses troupes. Présentez-vous à lui à son avant-poste au bord de la route à l\'ouest d\'ici et apportez-lui toute l\'aide qu\'il vous demandera.', '', '', '', '', '', '', '', '', '', 'Présentez-vous à Regthar Seuil-de-mort à son avant-poste à l\'ouest de la Croisée, dans les Tarides du Nord.', 0),
(14075, 'frFR', 'Des problèmes dans les mines', 'Exterminez 6 Vers tunneliers.', 'On a encore des problèmes dans la Kaja\'mine, boss. Les vers des tunnels sont de retour et ils sont littéralement en train de grignoter les marges de la Société Commerciale du Kajaro !$B$BNous avons dû suspendre l\'extraction de kaja\'mite, ce qui a un impact négatif sur la production de Kaja’Cola!$B$BJ\'ai tenté de faire appel à la société d\'extermination, mais le patron s\'est enfui après sa dernière paye.$B$BVous pensez que vous pourriez entrer dans les trois mines et vous en charger ? J\'vous aurais bien $gaidé:aidée;, mais je n\'ai pas encore eu l\'occasion d\'assister au séminaire de formation de combattant du cartel.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Contremaître Mèchumide au Quartier général de la SCK, sur Kezan.', 0),
(14078, 'frFR', 'État d\'alerte !', 'Trouvez le Lieutenant Walden à l\'extrémité nord-ouest de la Place des Marchands.', 'Que faites-vous encore là, $gcitoyen:citoyenne; ? Vous n\'avez pas entendu ? La ville est en état d\'alerte.$B$BAllez voir le lieutenant Walden, il vous donnera les consignes d\'évacuation.', '', '', '', '', '', '', '', '', '', '', 0),
(14091, 'frFR', 'Quelque chose ne va pas', 'Retournez voir le Prince Liam Grisetête sur la Place des Marchands.', 'Le lieutenant semble avoir succombé à de graves blessures. Le prince voudra probablement l\'apprendre.$B$BVous entendez des bruits de combat venant du marché.', '', '', '', '', '', '', '', '', '', '', 0),
(14093, 'frFR', 'Une pagaille monstrueuse', 'Le Prince Liam Grisetête vous demande de tuer 6 Worgens déchaînés.', 'Des worgens ! Mon père m\'avait prévenu que les créations de l\'archimage Arugal étaient devenues incontrôlables.$B$BMais d\'où viennent-ils ?$B$BJe suppose que cela n\'a aucune espèce d\'importance. Aidez-nous à nous débarrasser d\'eux. Nous autres Gilnéens leur montrerons de quoi nous sommes capables !', '', '', '', '', '', '', '', '', '', 'Retournez voir le Prince Liam Grisetête sur la Place des Marchands de la ville de Gilnéas.', 0),
(14094, 'frFR', 'Préserver le ravitaillement', 'Récupérez 4 Caisses de fournitures.', 'Écoutez, $n. Nous ne pouvons pas les laisser détruire notre ravitaillement.$B$BGilnéas étant coupé du reste du monde, nous ne passerons pas l\'hiver si nous perdons encore des provisions.$B$BAidez-moi à sauver ce que vous pouvez.', '', '', '', '', '', '', '', '', '', 'Retournez voir Gwen Armstead à la Place des Marchands dans la ville de Gilnéas.', 0),
(14098, 'frFR', 'L\'évacuation de la place des Marchands', 'Évacuez 3 Maisons de civils.', 'Les civils ne sont plus en sécurité. Pas même chez eux.$B$BNous faisons tout notre possible pour empêcher les worgens d\'entrer, mais ils sont trop nombreux.$B$BAidez-nous à évacuer les foyers des civils. L\'armée de mon père est basée dans le quartier de la prison et sera plus à même de protéger les citoyens.', '', 'Maisons du marché évacuées', '', '', '', '', '', '', '', 'Retournez voir le Prince Liam Grisetête sur la Place des Marchands de la ville de Gilnéas.', 0),
(14099, 'frFR', 'Des ordres royaux', 'Parlez à Gwen Armstead dans le Secteur Militaire, au sud-est.', 'Il est temps pour vous de partir, $n. Allez dans le secteur Militaire avec les autres civils.$B$BPrésentez-vous auprès de Gwen Armstead lorsque vous aurez traversé le pont au sud-est... Vérifiez que tout le monde va bien.$B$BJe vais rester ici avec les gardes et couvrir la fuite des civils. C\'est un ordre !', '', '', '', '', '', '', '', '', '', '', 0),
(14109, 'frFR', 'Un nouveau vous', 'Achetez un Bling-bling rutilant à Diastème Dent-d\'argent, une Nouvelle tenue branchée auprès de Szabo et des Lunettes de soleil cool chez Missa Labinocle, dans la Rue de la Fauche.', 'Une nouvelle tenue ? Sans blague ! Votre fête fait couler beaucoup d\'encre. Tous les gobelins un tant soit peu célèbres de l\'île seront présents.$B$BEh bien, bon shopping. La rue de la Fauche est très connue pour les offres qu\'on y trouve !', '', '', '', '', '', '', '', '', '', 'Retournez voir votre copine, Peggy Mauve, au Quartier général de la SCK, sur Kezan.', 0),
(14110, 'frFR', 'Un nouveau vous', 'Achetez un Bling-bling rutilant à Diastème Dent-d\'argent, une Nouvelle tenue branchée auprès de Szabo et des Lunettes de soleil cool chez Missa Labinocle, dans la Rue de la Fauche.', 'Une nouvelle tenue ? Sans blague ! Votre fête fait couler beaucoup d\'encre. Tous les gobelins un tant soit peu célèbres de l\'île seront présents.$B$BEh bien, bon shopping. La rue de la Fauche est très connue pour les offres qu\'on y trouve !', '', '', '', '', '', '', '', '', '', 'Retournez voir votre copain, Benji Golo, au Quartier général de la SCK, sur Kezan.', 0),
(14113, 'frFR', 'Membre d\'honneur', 'Revêtez votre Tenue de fête sensationnelle (Lunettes de soleil cool, Nouvelle tenue branchée et Bling-bling rutilant), puis dirigez-vous vers la fête à la piscine du Quartier général de la SCK et divertissez 10 Bambocheurs de Kezan.', 'Waouh, bébé ! Tout le monde est là ! On se fiche de ce stupide dragon !$B$BLa fête bat son plein autour de la piscine. On dirait qu\'ils s\'amusent tous comme des fous. Et toi, tu vas être tellement $gélégant:élégante; !$B$BPourquoi ne vas-tu pas près de la piscine pour divertir tes invités ? Je te rejoins dans un tout petit instant... Il faut juste que je me glisse dans une robe encore plus magnifique !', '', 'Bambocheur diverti', '', '', '', '', '', '', '', 'Retournez voir Chipie Serrelavis au Quartier général de la SCK, sur Kezan.', 0),
(14114, 'frFR', 'Un nouveau vous (suivi d\'évènement)', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14115, 'frFR', 'Les trouble-fête pirates', 'Tuez 12 Trouble-fête pirates pour sauver votre carrière.', 'Par tous les dieux ! Des pirates !$B$B$n, des pirates des mers du Sud sont en train de gâcher votre fête !$B$BVous devez y aller et faire quelque chose, sinon votre carrière et vos chances de devenir $gle prochain prince marchand:la prochaine princesse marchande; seront réduites à néant !', '', '', '', '', '', '', '', '', '', 'Retournez voir Chipie Serrelavis au Quartier général de la SCK, sur Kezan.', 0),
(14116, 'frFR', 'Un invité indésirable', 'Parlez au Prince marchand Gallywix à l\'étage du bâtiment principal du Quartier général de la SCK, sur Kezan.', 'Pendant que vous vous occupiez des pirates, j\'ai aperçu le prince marchand se faufiler à l\'étage. Il est sur le balcon en haut des marches.$B$B$n, je crois que c\'est lui qui a envoyé les pirates.$B$B<Chipie a un mouvement de recul.>$b$bVous devriez y aller au plus vite ! Je ne le ferais pas attendre, si j’étais vous.', '', '', '', '', '', '', '', '', '', '', 0),
(14117, 'frFR', 'Les yeux d\'Orneval', 'Tuez 8 Éclaireurs de Talrendis.', 'Nos ennemis sont partout, $c, jusque sur le pas de notre porte. Les elfes de la nuit ont renforcé la halte de Talrendis dans l’intention de mettre un terme à notre avancée en Orneval. En ce moment même, leurs éclaireurs patrouillent dans les collines à proximité, relevant toutes les allées et venues qui passent par ces portes.$B$BIl faut supprimer ces yeux d’Orneval.$B$BAllez-y. Vos proies rôdent tout autour de ces portes, surtout à l’est. Massacrez les éclaireurs qui nous espionnent !', '', '', '', '', '', '', '', '', '', 'Retournez voir Ag’tor Poing-de-sang à la Porte d’Azshara, en Azshara.', 0),
(14118, 'frFR', 'Une livraison de venaison', 'Récupérez 15 Tranches de venaison sur des Cerfs sabot-de-mousse affaiblis.', 'Au fur et à mesure que nous épuisons les ressources de cette terre pour nos machines de guerre, nous privons les animaux de la région de leur habitat naturel. S’ils doivent mourir, ce serait dommage de gaspiller leur viande alors qu’Orgrimmar est pleine de ventres affamés.$B$BAllez tuer les cerfs sabot-de-mousse qui subsistent dans la région et récupérez leur viande pour nos péons et nos grunts.', '', '', '', '', '', '', '', '', '', 'Apportez la venaison à Ag’tor Poing-de-sang à Orgrimmar à la Porte d’Azshara, en Azshara.', 0),
(14120, 'frFR', 'Mille milliards de radis ?!', 'Parlez à Chipie Serrelavis au Quartier général de la SCK, sur Kezan.', 'Vous êtes $gun jeune gobelin:une jeune gobeline; très $gambitieux:ambitieuse;, $n. Peut-être même un peu trop pour votre propre bien. J\'ai l\'impression de me revoir à votre âge.$B$BJe vais vous faire une offre. Vous avez peut-être remarqué que le mont Kajaro est en train d\'exploser à cause de votre dragon. Tous les habitants de Kezan vont mourir !$B$BMais si vous me rapportez mille milliards de radis avant que mon voilier ne quitte l\'île, je m\'assurerai que vous soyez $gl\'un des heureux élus:l\'une des heureuses élues; à s\'échapper.$B$BSi vous voulez vivre, vous feriez bien de trouver rapidement une solution pour me rapporter mon flouze !', '', '', '', '', '', '', '', '', '', '', 0),
(14121, 'frFR', 'Robin des bois moderne', 'Utilisez votre Voiture de sport pour renverser 12 Pillards embauchés et récolter 12 Butins volés par la même occasion.', 'Nous allons tous mourir !!!$B$B<Vous giflez Megs pour la calmer.>$B$BDésolée, $gm\'sieur:m\'dame; $n. Ça n\'arrivera plus. D\'accord. Alors, nous devons trouver du flouze rapidement.$B$BIl semblerait que le prince marchand a déjà envoyé dans les rues des pillards qu\'il a embauchés.$B$BVous devriez prendre la voiture de sport, aller les renverser et récupérer le butin qu\'ils ont déjà volé illégalement. Rien de mal à ça, pas vrai ?', '', '', '', '', '', '', '', '', '', 'Retournez voir Megs Déchiqueffroi au Quartier général de la SCK, sur Kezan.', 0),
(14122, 'frFR', 'Le casse du jour', 'Faites sauter le coffre de la Banque Centrale de Kezan pour récupérer vos Biens personnels.', 'Tous vos actifs ont été gelés et la Banque Centrale de Kezan a fermé ses portes !$B$BVous avez besoin d\'un sacré paquet de flouze, boss. Je crois bien que vous allez devoir voler votre propre argent à la banque ! Les différents outils de votre gadgetoceinture gobeline devraient suffire à ouvrir le coffre.$B$BEspérons seulement que vous avez économisé suffisamment pour le cas où vous auriez chaud aux fesses, comme je vous l\'avais conseillé. Vous l\'avez peut-être remarqué mais... le coup de chaleur risque de durer un bon moment !!!', '', 'Coffre de la Banque Centrale de Kezan', '', '', '', '', '', '', '', 'Retournez voir Chipie Serrelavis au Quartier général de la SCK, sur Kezan.', 0),
(14123, 'frFR', 'On entre et on ressort', 'Obtenez l\'Épervier de Maldy, La gobeline Lisa et la Bombe ultime.', 'Il n\'y a qu\'un moyen d\'obtenir mille milliards de radis : les voler aux riches !$B$BCet abject prince marchand a volé de nombreux objets d\'art et antiquités. Il est temps de les lui reprendre et de les distribuer aux nécessiteux... à commencer par nous !$B$BHobart a laissé une coiffe sur laquelle il travaillait. C\'est un déguisement qui vous fera passer pour l\'un des malabars de Gallywix. Tout ce que vous devez faire, c’est rentrer dans sa villa, à l\'ouest, et vous « procurer » ce qui nous intéresse.$B$BUn conseil, faites attention à ses cochons, ils sont capables de renifler les intrus malgré leur déguisement !', '', '', '', '', '', '', '', '', '', 'Retournez voir Fugace Coutelard au Quartier général de la SCK, sur Kezan.', 0),
(14124, 'frFR', 'L\'extraction de la kaja\'mite', 'Collectez 12 Morceaux de kaja\'mite.', '$gM\'sieur:M\'dame;, nous avons besoin d\'un sacré paquet de flouze pour payer le prince marchand et pouvoir enfin quitter Kezan ! Eh bien des tonnes de blé dorment justement sous nos pieds dans la Kaja’mine, attendant d’être ramassées !$B$BJe parle des derniers gisements de kaja\'mite dans tout Azeroth. C\'est cette matière première qui a fait de nous les alchimistes et ingénieurs de génie que nous sommes aujourd\'hui. Si ça, ça ne vaut pas mille milliards de radis, alors rien ne les vaut !$B$BPrenez quelques-unes de mes bombes krak’boum et faites sauter les gisements. Vous n\'aurez plus qu\'à ramasser les morceaux de minerai.$B$BEt faites attention aux trolls rebelles !', '', '', '', '', '', '', '', '', '', 'Retournez voir le Contremaître Mèchumide au Quartier général de la SCK, sur Kezan.', 0),
(14125, 'frFR', '447', 'Surchargez le Générateur défectueux, activez le Poêle qui fuit, laissez tomber un cigare sur le Lit inflammable et utilisez le Gazbot pour mettre le feu au Quartier général de la SCK !', 'Nous y sommes presque, mais nous n’avons pas encore assez de radis. J’ai donc élaboré un plan : nous allons nous servir de la police d’assurance du quartier général !$B$BJe me suis permis de ranger les feux d’artifice qui restaient de votre petite fête dans le bâtiment. Tout ce que vous avez à faire, c’est d’entrer et de saboter quelques installations.$B$BJe pense notamment au générateur défectueux, au poêle qui fuit et au lit inflammable. Ensuite, ressortez et utilisez le panneau de commandes pour envoyer le gazbot.$B$BC’est un plan infaillible !', '', 'Surcharger le générateur défectueux', 'Activer le poêle qui fuit', 'Faire tomber un cigare sur le lit inflammable', 'Quartier général de la SCK incendié à l\'aide du gazbot', '', '', '', '', 'Parlez à l’Expert en sinistres au Quartier général de la SCK, sur Kezan.', 0),
(14126, 'frFR', 'Les économies de toute une vie', 'Cédez vos Économies d\'une vie au Prince marchand Gallywix sur le Voilier du prince marchand, sur Kezan.', 'Nous avons tout le flouze dont nous avons besoin. Il n\'y a plus qu\'une chose à faire, boss. Allez sur le bateau du prince marchand. Il va bientôt lever l\'ancre !$B$BNous avons intérêt à nous dépêcher. Montez, je prends le volant.', '', '', '', '', '', '', '', '', '', '', 0),
(14127, 'frFR', 'Le retour des Bien-nés ?', 'Apportez les Ordres de l’éclaireur à Ag’tor Poing-de-sang, à la Porte d’Azshara.', 'Le cachet de cire qui scellait ces ordres semble avoir été récemment brisé. L’écriture du texte est soignée mais vous ne savez pas lire la langue des elfes de la nuit. Cependant, une petite carte dessinée à la main indique les ruines à proximité. En dessous de la carte, des runes sont inscrites dans une langue complètement différente, avec une encre aux reflets métalliques.$B$BCette importante découverte intéressera certainement Ag’tor.', '', '', '', '', '', '', '', '', '', 'Apportez les Ordres de l’éclaireur à Ag’tor Poing-de-sang à la Porte d’Azshara, en Azshara.', 0),
(14128, 'frFR', 'Le retour des Bien-nés ?', 'Apportez les Ordres de l’éclaireur à Malynéa Saccagecieux, à la Station d’Orgrimmar du fusorail.', 'Nos alliés elfes de sang font des recherches sur le site de fouilles des ruines indiquées sur la carte depuis quelque temps, et peuvent probablement comprendre ce texte mystérieux. Cherchez une elfe de sang nommée Malynéa Saccagecieux. Elle dirige ses recherches depuis la station d’Orgrimmar du fusorail, juste au nord d’ici. Cet endroit fait partie du nouveau système de transport gobelin qui sillonne cette terre. Dépêchez-vous !', '', '', '', '', '', '', '', '', '', 'Apportez les Ordres de l’éclaireur à Malynéa Saccagecieux, à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14129, 'frFR', 'Déchiqueteur emballé !', 'Attaquez l’un des Déchiqueteurs emballés près de la Porte d’Azshara et sautez dedans une fois qu’il aura subi des dégâts importants.', 'J’ai tenté d’impressionner les nouveaux alliés de la Horde avec notre savoir-faire gobelin, mais avec le recul… automatiser les déchiqueteurs n’était pas une bonne idée. Maintenant, ce ne sont que de stupides machines tueuses qui dévastent tout sur leur passage. Ne vous méprenez pas, ces machines ont leur place, ici. Mais pour l’instant, il faut qu’$gun gentil:une gentille:c; $c m’aide à les maîtriser.$B$BC’est facile. Un déchiqueteur automatique, comme toutes les machines, doit d’abord être maté. Ensuite, prenez-en le contrôle et je vous transmettrai les instructions par radio.', '', 'Déchiqueteur emballé capturé', '', '', '', '', '', '', '', 'Attaquez l’un des Déchiqueteurs emballés près de la Porte d’Azshara et sautez dedans une fois qu’il aura subi des dégâts importants.', 0),
(14130, 'frFR', 'Un ami haut en couleur', 'Trouvez Ergll sur la côte des Ruines d’Arkkoran.', 'Mes frères et moi sommes pourchassés.$B$BNotre père vient d’être tué et le Vol draconique noir veut expulser tous ceux de notre espèce encore en vie. Je suis ici pour trouver Azuregos et le conduire en sécurité, si seulement il voulait bien se laisser faire.$B$BAzuregos a peu d’amis, et ceux qu’il a sont un peu… spéciaux. Le seul que je connaisse est un murloc du nom d’Ergll. Vous devriez le trouver sur la côte, au nord-est d’ici.$B$BFaites votre possible pour trouver Azuregos et envoyez-le-moi.$B$BJe vous en prie, hâtez-vous.', '', '', '', '', '', '', '', '', '', '', 0),
(14131, 'frFR', 'Un petit remontant', 'Récupérez 10 Fèves de kaphay sur les kaphayers dans les Ruines d’Arkkoran.', 'Azuregos… Azuregos. Azy ? Le dragon ? Bien sûr, qu’on est amis ! Y m’a appris à parler. Y disait qu’il aimait ma teinte… Il a un truc avec les couleurs, hein ?$B$BMe rappelle pas où il est allé. Mmhh… y me faudrait quelque chose pour me rafraîchir la mémoire !$B$BJe plante du kaphay partout sur la plage. Ça aime le sable, ça. Plutôt bizarre.$B$BVous pourriez aller en récupérer un peu ?', '', '', '', '', '', '', '', '', '', 'Retournez voir Ergll sur la côte des Ruines d’Arkkoran.', 0),
(14132, 'frFR', 'C’est vraiment mal élevé !', 'Tuez 10 Makrinnis dans les Ruines d’Arkkoran.', 'Je partagerais bien avec eux, s’ils me le demandaient. Mais ils vont juste faire clic-clac sur mon kaphay ! Y sont vraiment mal élevés ! Vous devriez leur donner une bonne leçon.$B$BStupides makrinnis.', '', 'Makrinnis des Ruines d’Arkkoran tués', '', '', '', '', '', '', '', 'Retournez voir Ergll sur la côte des Ruines d’Arkkoran.', 0),
(14134, 'frFR', 'Il faut bûcher', 'Utilisez le Déchiqueteur reprogrammé pour récupérer 6 piles de Bois d’Azshara. Si vous perdez votre déchiqueteur, vous pouvez en attaquer un autre et le reprogrammer.', 'Maintenant que vous maîtrisez cette machine, je vous propose d’aller récupérer le bois que j’étais censé amasser. Sinon, ces orcs vont ME transformer en catapulte !$B$BLe bois fraîchement coupé doit être empilé partout autour d’ici. Utilisez le déchiqueteur pour récupérer tout le bois que vous pouvez.', '', '', '', '', '', '', '', '', '', 'Utilisez le Déchiqueteur reprogrammé pour récupérer 6 piles de Bois d’Azshara. Si vous perdez votre déchiqueteur, vous pouvez en attaquer un autre et le reprogrammer.', 0),
(14135, 'frFR', 'Une coupe sombre', 'Utilisez la scie circulaire du déchiqueteur pour abattre des Arbrisseaux d’Azshara, et tuez 9 Snipers de Talrendis dès que vous les apercevez.', 'Attendez une seconde, je vais brancher les commandes de votre scie circulaire.$B$BDes tireurs elfes de la nuit de Talrendis sont embusqués dans les arbres et tirent au hasard sur mes ouvriers. Je veux que vous vous débarrassiez de ces snipers… en abattant d’abord les arbres. Cherchez des arbrisseaux d’Azshara, à l’est des portes principales. Votre déchiqueteur saura quoi faire. Allez bûcher !', '', '', '', '', '', '', '', '', '', 'Utilisez la scie circulaire du déchiqueteur pour abattre des Arbrisseaux d’Azshara, et tuez 9 Snipers de Talrendis dès que vous les apercevez.', 0),
(14137, 'frFR', 'Formation de classe (suivi d\'évènement)', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14138, 'frFR', 'La main à la pâte', 'Apportez l\'Encouragement de Chipie au Contremaître Mèchumide au Quartier général de la SCK, sur Kezan.', 'Le contremaître Mèchumide vous cherche partout à cause des problèmes que nous avons dans la Kaja\'mine. Il a parlé de « trolls défiants ».$B$BLa kaja\'mite que nos trolls minent est primordiale dans la fabrication du Kaja’Cola. Cette boisson gazeuse nous rapporte une fortune, et c\'est grâce à ça que vous serez bientôt $gpromu prince marchand:promue princesse marchande; !$B$BMais tout d\'abord, nous devons faire en sorte que la production reprenne. Vous trouverez le contremaître à l\'est. Tenez, donnez-lui ceci pour le motiver.', '', '', '', '', '', '', '', '', '', '', 0),
(14139, 'frFR', 'Fin de phase 1 (suivi d\'évènement)', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14146, 'frFR', 'Défendez les portes !', 'Le Capitaine d’ouvrage Grailletout veut que vous retourniez sans tarder à la Porte d’Azshara pour massacrer 20 Écumeurs elfes de la nuit.', 'Bon sang, mais que se passe-t-il ?$B$B<Des cris, des hurlements et le chaos du combat envahissent la radio.>$B$B$n ! Revenez ici immédiatement. Retournez près des portes, vite ! Nous sommes attaqués !$B$BAidez-nous à repousser les envahisseurs. Je suis en train d’armer votre lance-grenades !!', '', '', '', '', '', '', '', '', '', 'Le Capitaine d’ouvrage Grailletout veut que vous retourniez sans tarder à la Porte d’Azshara pour massacrer 20 Écumeurs elfes de la nuit.', 0),
(14153, 'frFR', 'Membre d\'honneur', 'Revêtez votre Tenue de fête sensationnelle (Lunettes de soleil cool, Nouvelle tenue branchée et Bling-bling rutilant), puis dirigez-vous vers la fête à la piscine du Quartier général de la SCK et divertissez 10 Bambocheurs de Kezan.', 'Eh ben, bébé ! Tout le gratin est là ! On se fiche de ce stupide dragon !$B$BLa fête bat son plein autour de la piscine. On dirait qu\'ils s\'amusent tous comme des fous. Tu vas être tellement $gélégant:élégante; !$B$BPourquoi ne vas-tu pas près de la piscine pour divertir tes invités ? Je te rejoins dans un instant... Il faut juste que je me mette quelque chose sur le dos !', '', 'Bambocheur diverti', '', '', '', '', '', '', '', 'Retournez voir Chipie Serrelavis au Quartier général de la SCK, sur Kezan.', 0),
(14154, 'frFR', 'Pas passé loin', 'Repoussez les worgens au sommet de la prison de Gilnéas pendant 2 minutes.', 'Un de ces satanés sacs à puces a bien chopé Dempsey. Nous ne pouvons pas le déplacer tant qu\'il perd du sang.$B$BAidez-nous à repousser ces sales bêtes. Nous n\'aurons besoin que de quelques minutes, $gmon frère:ma sœur; !', 'Survivre et repousser les worgens pendant 2 minutes.', '', '', '', '', '', '', '', '', 'Parlez au Seigneur Darius Crowley en haut de la Prison de Gardepierre, dans la ville de Gilnéas.', 0),
(14155, 'frFR', 'Arbricide', 'Utilisez le Déchiqueteur pour détruire l’Ancien de Talrendis. Si vous perdez votre déchiqueteur, des machines de secours sont disponibles à la Porte d’Azshara.', 'Le déchiqueteur tient le coup ? Je pense pouvoir réactiver vos réserves d’énergie d’urgence, ça rechargera vos batteries si vous êtes $gtouché:touchée;.$B$BÉcoutez, ces elfes de la nuit tirent leur puissance d’un ancien de la guerre, enraciné juste à l’ouest des portes. C’est un arbre gigantesque. Vous savez ce qu’il vous reste à faire ! Dégommez-le !$B$BVous êtes $gfait:faite; pour ça !', '', '', '', '', '', 'Utilisez vos scies circulaires quand vous êtes près pour abattre cet arbre !', 'Ancien de Talrendis', '', '', 'Retournez voir le Capitaine d’ouvrage Grailletout à la Porte d’Azshara.', 0),
(14157, 'frFR', 'D\'anciennes rancœurs', 'Parlez au Capitaine Broderick dans la Prison de Gardepierre, à Gilnéas.', 'Le seigneur Darius Crowley a porté bien des noms : rebelle, traître, terroriste.$B$BAvant la guerre civile, je l\'appelais… mon ami.$B$BJe ne lui en ai jamais voulu d\'avoir mené une insurrection contre moi. Ses terres et son peuple étaient séparés de Gilnéas par un mur de dix mètres de haut… mais nous n\'avions pas d\'autre choix.$B$BNéanmoins… Crowley est exactement l\'homme qu\'il nous faut aujourd\'hui.$B$BEntrez dans la prison de Gardepierre et demandez au capitaine Broderick où se cache Crowley. J\'aurais bien envoyé mes hommes, mais les vieilles rancœurs sont tenaces.', '', '', '', '', '', '', '', '', '', '', 0),
(14158, 'frFR', 'Fin de phase 6 (suivi d\'évènement)', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14159, 'frFR', 'L\'arsenal du seigneur séditieux', 'Parlez à Josiah Avery dans le Secteur Militaire, à Gilnéas.', 'L\'arsenal dont parlait Crowley se trouve dans la cave d\'un bâtiment à l\'ouest.$B$BIl est assez pénible de savoir que mes ennemis ont réussi à cacher des armes en ville, mais aujourd\'hui, cet armement sauvera peut-être les habitants de Gilnéas.$B$BTrouvez Josiah Avery et réquisitionnez l\'artillerie rebelle. Nous ferons bon usage de ces armes.', '', '', '', '', '', '', '', '', '', '', 0),
(14161, 'frFR', 'Un parfum de basilic', 'Tuez 10 Basilics grispierre dans la Mine à ciel ouvert du Puy-du-Pied.', 'Nous avons déplacé l’ensemble de cette montagne pour pouvoir exploiter les minerais qui se trouvent en dessous. Mais c’était sans compter les basilics souterrains qui sont maintenant, euh… terrains. Vous avez l’air débrouillard ! Allez donc tuer quelques-uns de ces monstres et je piocherai dans notre cagnotte pour vous récompenser.', '', '', '', '', '', '', '', '', '', 'Allez faire votre rapport à Horzak Zigrignote à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14162, 'frFR', 'Présentez-vous à Horzak', 'Trouvez Horzak Zigrignote à la Station d’Orgrimmar du fusorail, en Azshara.', 'Grâce à vous, la coupe du bois a repris. Mais j’ai entendu dire que notre quota de pierre était insuffisant. Si seulement on pouvait déplacer des montagnes et rassembler quelques rochers…$B$BEh bien, ce n’est pas mon problème, mais ça pourrait peut-être devenir le vôtre. Présentez-vous à Horzak Zigrignote un peu plus loin, à la station d’Orgrimmar du fusorail. Voyez si vous pouvez l’aider à réorganiser ses opérations. Vous n’avez qu’à suivre la route au nord-est. Vous le trouverez dans la tour du fusorail.', '', '', '', '', '', '', '', '', '', 'Trouvez Horzak Zigrignote à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14165, 'frFR', 'Froid comme la pierre', 'Allez chercher un Mineur du Puy-du-Pied pétrifié dans la Mine à ciel ouvert du Puy-du-Pied, et ramenez-le à Horzak Zigrignote, à la Station d’Orgrimmar du fusorail.', 'Mes ouvriers n’arrêtent pas de se plaindre. Quand ce n’est pas le travail qui est éreintant, les heures qui semblent interminables, ou la paie qui est mauvaise, c’est la faute des basilics qui les changent en pierre. Il y a toujours quelque chose !$B$BMais je pourrais peut-être me faire de l’argent avec ces ouvriers pétrifiés. Et si ces gars étaient faits d’une pierre de très bonne qualité ? Mes geignards d’employés me rapporteraient peut-être plus en tant que matériaux de construction de luxe qu’en tant que main d’œuvre ! Allez chercher un mineur pétrifié et ramenez-le-moi.', 'Mineurs pétrifiés délivrés', '', '', '', '', '', '', '', '', 'Allez voir Horzak Zigrignote à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14184, 'frFR', 'Mon heure est venue', 'Furien de Tethris Aran veut que vous utilisiez son Faucon-dragon pour vous rendre au Poste de Furien et prévenir sa sœur, Cérélia, de sa mort.', '<Avec difficulté, Furien vous fait signe d’approcher et vous parle avec peine.>$b$bQuelle négligence… Je suis tombé sous le feu de l’Alliance…$b$bVous devez… prévenir ma sœur.$b$bPrenez ma monture, $r… elle vous y conduira…$b$b<Furien rend son dernier souffle.>', '', '', '', '', '', '', '', '', '', '', 0),
(14188, 'frFR', 'Vengez Furien !', 'Cérélia vous a demandé de parler à Sorrem au Poste de Furien.', 'C’est impossible !$b$bMon frère bien-aimé, abattu par la racaille de l’Alliance !$b$bJe veux qu’ils souffrent, $r ! Trouvez un moyen de les faire payer ! Je ne trouverai pas le repos tant qu’il ne sera pas vengé…$b$bFurien était à la recherche de reliques antiques dans les régions à l’est, avant sa mort. Allez parler à Sorrem. Peut-être pourra-t-il vous guider sur les traces de mon frère.', '', '', '', '', '', '', '', '', '', '', 0),
(14189, 'frFR', 'La traduction', 'Sorrem veut que vous trouviez les Tablettes antiques.$b$bAllez parler à Narimar au Poste de Furien d\'où il vous enverra à l’endroit où Furien faisait ses recherches.', 'Il est vrai que Furien avait consacré ses derniers jours à un projet spécial de recherches. Mais il n’a jamais voulu me dire de quoi il s’agissait.$b$bHeureusement, j’ai pu retrouver son journal, mais c’est écrit dans un code que je ne parviens pas à déchiffrer.$b$bPeut-être trouverez-vous un moyen de le traduire dans les régions à l’est, où il passait son temps.$b$bEmportez le journal avec vous, $c, et allez parler à Narimar lorsque vous serez $gprêt:prête; à enquêter sur cette énigme.', '', '', '', '', '', '', '', '', '', '', 0),
(14190, 'frFR', 'Le prisme parfait', 'Récupérez un Pendentif en cristal sur un Saboteur de Talrendis dans la Mine à ciel ouvert du Puy-du-Pied.', 'Il doit y avoir un moyen d’inverser le sort de pétrification des basilics. Les saboteurs elfes de la nuit qui rôdent autour de ma mine doivent savoir quelque chose à ce sujet. On dirait qu’ils sont insensibles au regard de ces bêtes !$B$BJe veux que vous découvriez leur secret, $n. Dégommez quelques saboteurs de Talrendis planqués au fond de la mine à ciel ouvert et rapportez-moi un exemplaire du charme ou de la breloque qui leur confère cette immunité. Envoyez-moi un message radio du bâtiment principal de la forge quand vous aurez récupéré l’objet.', '', '', '', '', '', '', '', '', '', 'Utilisez la Radio du quartier-général dans le bâtiment principal de la forge de la Mine à ciel ouvert du Puy-du-pied, en Azshara.', 0),
(14191, 'frFR', 'Sur les traces de Furien', 'Les tablettes antiques du sanctuaire d’Élune vous ont $gconduit:conduite; jusqu\'aux trois plus grandes ruines de Sargeron.', 'Vous parvenez à déchiffrer des bribes du texte, mais des recherches plus approfondies seront nécessaires pour comprendre le travail de Furien.$b$bPour l’heure, en regardant vers le nord-est, vous pensez reconnaître les ruines décrites dans le journal.$b$bVous avez le sentiment que ces ruines avaient de l’importance dans les recherches de Furien.', '', 'Ruines de la Cathédrale d\'Élune explorées', 'Ruines du Temple d\'Élune explorées', 'Ruines du Sanctuaire d\'Élune explorées', '', '', '', '', '', '', 0),
(14192, 'frFR', 'Un cristal à tout prisme !', 'Apportez le Pendentif en cristal au Râtelier d’armes du quartier général de la Mine à ciel ouvert du Puy-du-Pied.', 'Si le prisme que vous tenez là est réglé pour réfracter le regard des basilics, nous pouvons utiliser ses propriétés cristallines pour inverser le processus. Tout ce qu’il nous faut, c’est une source de pouvoir.$B$BDans le râtelier d’armes, sur votre droite, vous trouverez notre laser prototype pour le forage des mines. J’adorais cette machine, mais les démembrements quasi-quotidiens ont commencé à devenir gênants. Prenez la foreuse à laser et remplacez la lentille par votre cristal…', '', '', '', '', '', '', '', '', '', 'Apportez le Pendentif en cristal au Râtelier d’armes du quartier général de la Mine à ciel ouvert du Puy-du-Pied.', 0),
(14193, 'frFR', 'Choper le melon', 'Récoltez 8 Melons.', 'Les inscriptions sur les ruines révèlent un point important. La vieille fontaine du sanctuaire d’Élune renferme un secret.$b$bIl semblerait que se passer de son eau sur le visage confère un pouvoir extraordinaire. Il faudrait d’abord qu’il y ait quelque chose dans l’ancienne fontaine à se passer sur le visage.$b$bEn réfléchissant au problème, vous apercevez un melon au pied d’un arbre tout près de vous…', '', 'Rituel de purification terminé', '', '', '', '', '', '', '', 'Pressez le jus des Melons dans la Coupe d’Élune à Sargeron, en Désolace.', 0),
(14194, 'frFR', 'Reviandication', 'Utilisez le Reviandicateur pour dépétrifier 8 Mineurs du Puy-du-Pied, dans la Mine à ciel ouvert du Puy-du-Pied.', '<La radio à proximité vous appelle.>$B$BHé, $n, vous avez l’arme ? Bien ! Ne la pointez pas dans votre direction.$B$BPointez plutôt ce bébé sur mes ouvriers pétrifiés et la lumière réfractée devrait inverser le processus de pétrification. Ou bien faire fondre mes gars. Peu importe. Je veux qu’ils soient à nouveau rentables ! Et si le processus de reviandication les rend fous, on devra les tuer pour toucher l’assurance ! Horzak TERMINÉ !', '', 'Mineurs du Puy-du-Pied dépétrifiés', '', '', '', '', '', '', '', 'Retournez voir Horzak Zigrignote à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14195, 'frFR', 'Tout devient plus clair', 'Le Journal de Furien vous met sur la piste des ruines du Palais d’Élune, au nord de Sargeron.', 'Quelque chose a changé en vous… c’est peut-être dû au rituel de purification d’Élune.$b$bBien qu’elle ne soit pas encore parfaite, votre compréhension de l’antique langue utilisée dans le journal s’est grandement améliorée.$b$bFurien semblait surtout très intéressé par les ruines situées dans les montagnes du nord de Sargeron. Il avait le sentiment de pouvoir y trouver un moyen de déloger l’Alliance de cette région.$b$bVous fermez le journal, $gdéterminé:déterminée; à découvrir ces ruines et les secrets qu’elles renferment.', '', 'Ruines du Palais d’Élune localisées.', '', '', '', '', '', '', '', '', 0),
(14196, 'frFR', 'La guerre du feu', 'Vous devez créer un Vortex déchaîné en tuant 7 Disciples d’Élune en présence de la tempête de feu.$b$bSi vous perdez votre Gemme du vortex, vous pouvez en récupérer une autre sur l’Ancienne pierre runique du vortex.', 'Vous êtes maintenant capable de déchiffrer le code utilisé dans le journal.$b$bDans le passage concernant la pierre runique, il est expliqué que les gemmes du monument avaient le pouvoir d’invoquer une tempête de feu.$b$bCette tempête pouvait devenir une arme redoutable, nourrie par une foi inconditionnelle en Élune, ou chargée de l’énergie spirituelle des défunts.$b$bEn observant les disciples fantomatiques d’Élune, vous vous dites que vous n’avez ni le temps, ni l’envie de vénérer la déesse de votre ennemi…', '', 'Vortex déchaîné créé', '', '', '', '', '', '', '', '', 0),
(14197, 'frFR', 'Un quota à respecter', 'Récupérez 20 lingots de Fer du Puy-du-pied dans la Mine à ciel ouvert du Puy-du-pied, en Azshara.', 'Le fer du Puy-du-pied est un alliage fragile, mais en distribuant quelques pots-de-vin par-ci par-là, il finit par répondre aux normes de sécurité gobeline. Zigrignote, ici présent, rencontre des problèmes au niveau de la production, mais ça ne change pas mes délais. J’ai un quota à respecter, moi !$B$BIntroduisez-vous dans la mine à ciel ouvert du Puy-du-pied et récupérez tous les lingots de fer du Puy-du-pied que vous trouverez. Il devrait y avoir des piles de barres de fer fondues, prêtes à être expédiées.', '', '', '', '', '', '', '', '', '', 'Apportez le fer au Contremaître Fisk à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14198, 'frFR', 'Le cavalier de l\'orage', 'Utilisez la Gemme du vortex déchaîné aux ruines de la combe de Nijel. À l’aide de votre Tempête-de-feu, tuez 40 Défenseurs de la combe de Nijel et brûlez 15 Marchands de la combe de Nijel.$b$bSi vous perdez votre Gemme du vortex déchaîné, vous pouvez en récupérer une autre sur l’Ancienne pierre runique du vortex.', 'Vous ne pouvez vous empêcher de ressentir une pointe de fierté à l’idée d’avoir résolu le mystère des anciens adorateurs d’Élune.$b$bVous avez désormais le pouvoir de semer la destruction parmi vos ennemis.$b$bFurien s’est donné du mal pour rendre cela possible, il est donc normal que cette arme soit déchaînée contre ceux qui lui ont ôté la vie.$b$bLa racaille de l’Alliance, à la combe de Nijel, doit payer pour ses affronts à la Horde !', '', 'Défenseurs de la combe de Nijel abattus', 'Marchands de la combe de Nijel abattus', '', '', '', '', '', '', 'Retournez voir Cérélia au Poste de Furien, en Désolace.', 0),
(14201, 'frFR', 'Un millier d\'histoires dans le sable', 'Rassemblez 5 Artéfacts récupérés dans les ruines qui entourent le Lac Mennar, en Azshara.', 'Les ruines qui entourent le lac Mennar, à l’est, ont une histoire à raconter. Les races inférieures, telles que ces lourdauds de nains, ont cherché à la découvrir à coups de pelles et de pioches. <Malynéa fronce le nez.> Nous allons utiliser des méthodes plus élégantes.$B$BMes compétences en divination sont un peu rouillées, mais avec le bijou approprié je devrais pouvoir traverser les limbes du temps. Les ossements de mes ancêtres ont pourri depuis bien longtemps, mais certains de leurs objets personnels ont survécu. Rapportez-m’en quelques-uns.', '', '', '', '', '', '', '', '', '', 'Apportez les Artéfacts récupérés à Malynéa Saccagecieux à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14202, 'frFR', 'La surveillance des rives du lac', 'Escortez une Géomètre gobeline jusqu’aux trois appareils de l’équipement de géomètre qui entourent le Lac Mennar, et défendez-la le temps qu’elle relève les mesures. Vous pouvez toujours invoquer une autre Géomètre avec votre Balise de géomètre.', 'Il va falloir détruire ces ruines grossières si nous voulons qu’Azshara retrouve tout son potentiel un jour. Regardez sur ma carte ici, vous voyez le lac Mennar, à l’est ? Je vais vous dire ce que je vois : un futur dépôt de carburant pour fusée !$B$BMais il faut d’abord que la configuration du paysage corresponde à nos attentes avant de tout raser, de tout passer au bulldozer, de tout enfouir et de recouvrir ce lac. Cet endroit hanté a fait fuir toutes mes géomètres. Escortez l’une de mes géomètres stagiaires jusqu’au lac, et relevez les mesures des appareils qui ont été installés.', '', 'Repère topographique ouest', 'Repère topographique nord', 'Repère topographique est', '', '', '', '', '', 'Retournez voir Custer Clubnik à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14204, 'frFR', 'Dans les ombres', 'Tuez 6 Rôdeurs croc-de-sang.', 'Il s’est transformé en l\'un d\'eux... c’est ça ? Comment pourrait-on vaincre un ennemi qui peut faire de telles choses ?$B$BJe me dis que l\'arsenal de mon père pourra certainement y contribuer.$B$BLes worgens se cachent dans ces ruelles. Prenez un de mes mastiffs pour les trouver plus facilement.$B$BNous devons dégager le passage pour pouvoir monter ces canons jusqu’ici.', '', '', '', '', '', '', '', '', '', 'Retournez voir Lorna Crowley dans le Secteur Militaire de la ville de Gilnéas.', 0),
(14209, 'frFR', 'Viscosité', 'Inspectez le Buldo de Clubnik et récupérez un échantillon de l’ectoplaf qui encrasse le moteur.', 'J’étais venu avec mon meilleur bulldozer pour raser ces ruines antiques qui survivent aux intempéries depuis dix mille ans. J’ai baptisé ma machine « Margène ».$B$BMais elle m’a lâché, récemment, $n. Quand je l’ai conduite dans ces bois hantés, son moteur a émis un hurlement à vous glacer le sang. Mes ingénieurs m’ont dit que quelque chose était coincé dans ses valves. Allez inspecter le compartiment moteur de Margène, et rapportez-moi un échantillon de ce qui la fait caler.', '', '', '', '', '', '', '', '', '', 'Apportez l’Échantillon d\'ectoplaf à Custer Clubnik, à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14212, 'frFR', 'Sacrifices', 'Montez derrière le Seigneur Darius Crowley et rassemblez 30 Traqueurs croc-de-sang.', 'Vous n\'avez pas à faire ça, $n. Vous en avez déjà fait suffisamment.$B$BMais si vous décidez de rester... je serais fou de vous chasser.$B$BMes hommes ont fortifié leur position dans la cathédrale. Ils sont prêts pour la prochaine étape.$B$BJe vais m\'y rendre en attirant autant de ces sacs à puces que possible. Vous pouvez m\'accompagner, si vous le désirez.', '', 'Traqueurs croc-de-sang rassemblés', '', '', '', '', '', '', '', 'Parlez à Tobias Mantebrume à la Cathédrale de l\'Aube de Lumière dans la ville de Gilnéas.', 0),
(14213, 'frFR', 'Dix livres de chair', 'Vous devez rassembler 10 lambeaux de Chair de satyre sur les satyres de Sargeron, et les déposer sur le Brasero d’Élune.', 'D’après le journal de Furien, ce brasero antique a été placé ici pour accomplir des sacrifices.$b$bLes passages du script que vous parvenez à déchiffrer vous indiquent qu’une bénédiction est accordée à quiconque dépose des lambeaux de chair des ennemis d’Élune sur les braises enflammées du brasero.$b$bEn regardant autour de vous, vous jetez votre dévolu sur les satyres ayant récemment investi la région.', '', 'Offrande sacrificielle acceptée', '', '', '', '', '', '', '', '', 0),
(14214, 'frFR', 'Un message pour Grisetête', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Il est temps, $n. Nous allons continuer sans vous.$B$BAllez dire au roi Grisetête que l\'arsenal de mon père est à sa disposition. Il y a suffisamment de puissance de feu ici pour faire sauter tous les worgens d\'ici à la mer Boréale.', '', '', '', '', '', '', '', '', '', '', 0),
(14215, 'frFR', 'Souvenirs des morts', 'Apportez l’Anneau de Kalytha sur les rives du Lac Mennar. Touchez l’Esprit de Kalytha pour revivre ses souvenirs. Parlez aux autres esprits pour découvrir le secret du Lac Mennar.', 'Les runes de l’anneau que vous avez trouvé sont encore visibles : il avait été donné à une certaine Kalytha au moment de son admission à l’Académie. En utilisant les sorts appropriés, ce bijou personnel devrait nous ouvrir les portes de son âme.$B$BRapportez cet anneau au lac Mennar. Vous devriez désormais être en mesure de voir l’esprit de Kalytha sur la rive du lac. Touchez son fantôme et l’anneau vous permettra de voir le monde à travers ses yeux, alors qu’elle revit sans cesse ses dernières heures. Sondez son esprit, $n ! Parlez aux autres apparitions et découvrez les secrets du lac Mennar…', '', 'Secret de Kalytha découvert', '', '', '', '', '', '', '', 'Apportez l’Anneau de Kalytha sur les rives du Lac Mennar. Touchez l’Esprit de Kalytha pour revivre ses souvenirs. Parlez aux autres esprits pour découvrir le secret du Lac Mennar.', 0),
(14216, 'frFR', 'Le mystère de la pierre de Sarcen', 'Récupérez la Pierre de Sarcen au fond du Lac Mennar.', 'Avant sa mort, Kalytha était censée enterrer quelque chose au fond du lac : un puissant artéfact créé par les archimages du lac Mennar et auquel ils avaient consacré les dernières heures de leur vie. Malynéa Saccagecieux sera certainement intéressée par cet artéfact, en supposant qu’il existe encore. Vous décidez de fouiller les profondeurs du lac Mennar à la recherche de la pierre de Sarcen.', '', '', '', '', '', '', '', '', '', 'Apportez la Pierre de Sarcen à Malynéa Saccagecieux à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14217, 'frFR', 'Offrandes satyriques', 'Vous devez rassembler 10 lambeaux de Chair de satyre sur les satyres de Sargeron, et les déposer sur le Brasero d’Élune.', 'Vous trouvez très amusant que cette relique vous accorde une bénédiction normalement destinée à vos ennemis. $b$bVous décidez de faire le maximum pour mettre à profit ce cadeau fortuit.', '', 'Offrande sacrificielle acceptée', '', '', '', '', '', '', '', '', 0),
(14218, 'frFR', 'Par le sang et les cendres', 'Massacrez 80 Traqueurs croc-de-sang en utilisant les Canons rebelles.', 'Il est temps, $n. Si nous voulons porter un grand coup, c\'est maintenant qu\'il faut agir.$B$BNous sommes bien placés.$B$BNous avons la puissance de feu suffisante.$B$BTout ce qui nous reste à vérifier, c\'est si nous sommes suffisamment courageux... Et je n\'ai certainement pas $gun couard:une froussarde; en face de moi.', '', '', '', '', '', '', '', '', '', 'Retournez voir Tobias Mantebrume à l\'extérieur de la Cathédrale de l\'Aube de Lumière dans la ville de Gilnéas.', 0),
(14219, 'frFR', 'Les sabres mouvants', 'Vous devez récupérer 20 Sabres de satyre dans les râteliers d’armes et sur les satyres de la région, puis les placer sur la statue de la Suivante d’Élune.', 'Vous reconnaissez tout de suite la statue représentée dans le journal de Furien.$b$bBien que le texte associé à l’image ne vous renseigne pas davantage, le croquis est quant à lui explicite. Après chaque bataille, les armes des ennemis devaient être déposées dans le bassin en échange de quelque divine faveur.$b$bPendant que vous méditez sur ce rituel, une lueur métallique provenant d’un râtelier d’armes, non loin de là, attire votre attention…', 'Rituel de guerre d\'Élune terminé', '', '', '', '', '', '', '', '', '', 0),
(14221, 'frFR', 'Ne jamais abandonner, mais se replier si nécessaire', 'Parlez au Seigneur Darius Crowley dans la Cathédrale de l\'Aube de Lumière.', 'Nous avions suffisamment de munitions pour un mois de guerre civile, mais les worgens sont en si grand nombre que nous avons utilisé presque toutes nos réserves.$B$BEt nous ne voulons certainement pas être encore à l\'extérieur quand nous serons à sec. Repliez-vous à l\'intérieur de la cathédrale et faites votre rapport au boss. Je suis persuadé que le vieux Crowley saura quoi faire ensuite.', '', '', '', '', '', '', '', '', '', '', 0),
(14222, 'frFR', 'Dans les derniers retranchements', 'Tuer 8 Traqueurs frénétiques.', 'Nous tenons une position stratégique, $n. N\'hésitez pas à faire une prière, si c\'est dans vos habitudes.$B$BPrenez votre courage à deux mains et allons tuer ces corniauds !', '', '', '', '', '', '', '', '', '', 'Retournez voir le Seigneur Darius Crowley dans la Cathédrale de l\'Aube de Lumière, dans la ville de Gilnéas.', 0),
(14223, 'frFR', 'La paix de l\'âme', 'Sorrem, du Poste de Furien, vous a demandé de tuer Kohor.', 'Nous occupons un poste avancé, chargé de surveiller les ennemis potentiels. Quand la Horde lancera son attaque sur Désolace, notre travail nous permettra de ne pas nous laisser prendre par surprise.$b$bL’un de nos éclaireurs a récemment été capturé et sacrifié par la Lame-Ardente, dans leur bastion, à l’est. Depuis, une vermine de la Lame, du nom de Kohor, ne cesse de nous menacer et de nous provoquer.$b$bMême s’ils ne survivront pas longtemps, je paierais une jolie fortune à quiconque le fera taire !', '', 'Kohor tué', '', '', '', '', '', '', '', '', 0),
(14225, 'frFR', 'Vous le saurez quand vous le verrez', 'Sorrem, du Poste de Furien, veut que vous trouviez l’Ancien rituel d’invocation dans la Forteresse de Hache-Tonnerre.', 'En rendant son dernier souffle, Kohor a fait allusion à l’invocation d’un démon qui pourrait menacer toute la région.$b$bIl mentait peut-être, mais on ne peut pas courir ce risque.$b$bNous ne pouvons pas nous permettre d’attendre que Désolace soit aux mains de la Horde pour agir. Vous devez ratisser la forteresse de Hache-Tonnerre pour trouver des indices et mettre un terme à cette menace potentielle maintenant.', '', '', '', '', '', '', '', '', '', '', 0),
(14226, 'frFR', 'Un bon coup de savate', 'Utilisez votre Assistant arcanique personnel pour transformer 12 Démons legashi en insectes, puis écrabouillez-les.', 'Regardez-vous. Toujours en train de rendre service. Vous êtes quelqu’un de responsable. Vous prenez du galon, du galon, du galon, du galon !$B$BIl y a des démons plus loin ! Des démons tous aussi répugnants les uns que les autres. Des démons qui se régaleraient de vos entrailles ! Des démons legashi qui se dirigent vers le sud-est ! Mais ne vous inquiétez pas. Non, non, aucune raison de s’inquiéter, car vous serez $gaccompagné:accompagnée; d’un assistant !$B$BCibler, insectiser, écrabouiller. Cibler, insectiser, écrabouiller ! Très efficace. Très salissant aussi… mais, je le répète, pas d’inquiétude. Non, non, aucune inquiétude, car nous n’avons pas à faire le ménage après !', '', '', '', '', '', '', '', '', '', 'Retournez voir l’Image de l’archimage Xylem aux Ruines de Nordressa.', 0),
(14227, 'frFR', 'Le casse-tête', 'Rassemblez 100 Crânes blanchis de la Forteresse de Hache-tonnerre, déposez-les dans le Cercle d’invocation de la Larme ardente, puis tuez Nazargen.', 'C’est donc vrai…$b$bLe parchemin que vous avez découvert dans la forteresse de Hache-Tonnerre est la formule d’un puissant rituel d’invocation. Il est beaucoup plus puissant que tous ceux jamais possédés par la Lame-Ardente.$b$bIl faut à tout prix l’empêcher de se produire !$b$bSi le démon pouvait être invoqué avant que le rituel ne soit terminé, cela pourrait permettre d’éviter le pire.', '', 'Nazargen tué', '', '', '', '', '', '', '', 'Parlez à Sorrem au Poste de Furien.', 0),
(14230, 'frFR', 'Du travail manuel', 'Récupérez le Manuel d’abjurateur dans le Campement Legashi.', 'Les démons de la région semblent prendre un malin plaisir à voler tous nos manuels des Arcanes. Je doute fortement que la plupart d’entre eux sache lire, ils doivent donc faire ça par pure méchanceté.$B$BLa majorité des livres qu’ils ont pris sont sans valeur, mais ils ont volé un manuel d’abjurateur dont je vais avoir besoin pour aider les apprentis de Xylem à survivre aux « épreuves » qu’il leur impose. Trouvez ces démons au campement Legashi, au sud-est, et récupérez le manuel d’abjurateur.$B$BC’est tout. Filez !', '', '', '', '', '', '', '', '', '', 'Retournez voir Teresa Flèchefeuille aux Ruines de Nordressa.', 0),
(14232, 'frFR', 'Les oreilles qui chauffent', 'Vous devez rapporter 25 Oreilles de la Lame-Ardente à Sorrem, au Poste de Furien.', 'Sorrem n’a fait aucun mystère de son mépris pour les sympathisants de la Lame-Ardente de la Forteresse de Hache-Tonnerre.$b$bIl apprécierait certainement une preuve de leur mort.', '', '', '', '', '', '', '', '', '', '', 0),
(14233, 'frFR', 'Les orcs savent écrire ?', 'Apportez le Journal de campagne à Chipie Serrelavis sur le Rivage de l’Épave, sur les Îles Perdues.', 'En fouillant les affaires de l\'orc décédé, vous trouvez un journal de bord. Bien qu\'il ait été grandement endommagé par l\'eau, l\'écriture reste lisible, parfois avec peine.$B$BTandis que vous en feuilletez les pages, une histoire intéressante se dessine. Heureusement que vous avez appris à parler l\'orc.$B$BTout comme le voilier du prince marchand, les orcs ont été attaqués par les vaisseaux de guerre de l\'Alliance. Vous vous rappelez un bateau orc que vous avez dépassé juste avant que l\'Alliance ouvre le feu. Peut-être qu\'elle visait les orcs et non votre bateau ?$B$BImbéciles d\'orcs ! C\'est de leur faute si vous avez coulé !', '', '', '', '', '', '', '', '', '', '', 0),
(14234, 'frFR', 'L\'ennemi de mon ennemi', 'Remettez le Journal de campagne à Aggra au Camp de base de la Horde, sur les Îles Perdues.', 'Je déteste avoir à vous demander ça, mais j\'imagine que c\'est pour ça que vous gagnez si bien votre vie. Pouvez-vous remettre le journal de campagne de l\'orc mort à la personne qui se trouve à la tête de leur camp ?$B$BSelon les dires de ce journal, ils devraient être installés au sommet de l\'île, en haut de la pente qui se trouve après la caverne de kaja\'mite, au sud-est.$B$BBonne chance, $n. Je vous ai toujours $gapprécié:appréciée;.', '', '', '', '', '', '', '', '', '', '', 0),
(14235, 'frFR', 'Le val Vicieux', 'Trouvez Kilag Sangrecroc dans le Val Vicieux, sur les Îles Perdues.', 'Notre chasseur, Kilag Sangrecroc, et quelques éclaireurs se sont dirigés vers le val qui se trouve au bout du chemin à l\'ouest. Ils recherchent une... « cargaison précieuse »... que nous protégions lorsque ces chiens de l\'Alliance ont coulé notre bateau.$B$BLe passage est bloqué par des plantes mortelles et nos hommes n\'ont pas pu se frayer un chemin.$B$B$n, prouvez votre valeur en tant que $ggobelin:gobeline; et $c. Rendez-vous dans le val Vicieux et trouvez Kilag.', '', '', '', '', '', '', '', '', '', '', 0),
(14236, 'frFR', 'Un désherbant radical', 'Utilisez le Massacr\'herbes de votre Gadgetoceinture gobeline pour faucher 100 Plantes dans le Val Vicieux.', '<Kilag a à peine le temps de vous saluer entre deux tirs de pétoire, mais son regard appréciateur s’attarde un moment sur votre gadgetoceinture gobeline.>$B$BIl est temps de trouver des solutions inventives. Trouvez un outil qui fera l\'affaire dans votre ceinture et mettez-vous au travail !$B$B<Vous réfléchissez pendant un moment à la situation et une idée germe dans votre esprit, tellement dingue que ça pourrait bien marcher !>', '', 'Plantes mortelles de la jungle fauchées', '', '', '', '', '', '', '', 'Retournez voir Kilag Sangrecroc dans le Val Vicieux, sur les Îles Perdues.', 0),
(14237, 'frFR', 'Déplacement offensif', 'Trouvez Kilag Sangrecroc et ses éclaireurs au Surplomb Sauvage, sur les Îles Perdues.', 'Kilag devrait être en position, maintenant. Il est temps que vous vous rendiez au surplomb Sauvage. Quant à nous, nous allons nous regrouper et partir bientôt.$B$BSuivez le sentier au nord-ouest et traversez le val Vicieux... qui n\'est plus si vicieux, grâce à vous, pas vrai ?$B$BKilag et ses éclaireurs devraient se cacher un peu en retrait du sentier, mais les assassins du SI:7 risquent de les trouver rapidement, alors dépêchez-vous !', '', '', '', '', '', '', '', '', '', '', 0),
(14238, 'frFR', 'Infrarouge = Inframort', 'Tuez 10 Assassins du SI:7.$B$BS\'il arrive quoi que ce soit à votre Éclaireur orc, retournez voir Kilag qui pourra peut-être vous trouver un autre équipier.', 'Parlez moins fort. Le vallon au nord et à l\'ouest est infesté d\'assassins de l\'Alliance.$B$BMalheureusement, nous n\'avons pas réussi à les trouver. Les pleutres ! Ils se cachent et refusent de se battre à la loyale.$B$BMais vous, les gobelins, vous êtes connus pour vos incroyables lunettes. Vous devez bien en avoir une paire qui vous permettra de les voir, non ?$B$BJ\'aimerais que vous fassiez équipe avec l\'un de mes éclaireurs et que vous tuiez tous les assassins du SI:7 que vous découvrirez.', '', '', '', '', '', '', '', '', '', 'Retournez voir Kilag Sangrecroc au Surplomb Sauvage, sur les Îles Perdues.', 0),
(14239, 'frFR', 'N\'allez pas vers la Lumière !', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14240, 'frFR', 'Vers les falaises', 'Parlez à l\'Éclaireur Brax sur le chemin en direction des falaises au nord du Vallon Sauvage, sur les Îles Perdues.', 'J\'ai envoyé l\'éclaireur Brax longer la route en direction des falaises qui surplombent la plage à l\'ouest.$B$BJe vais vous demander de monter sur Bastia. Descendez le chemin et dites à Brax que nous empruntons une route différente.$B$BNous nous retrouverons lors de l\'attaque à la tête de pont de l\'Alliance.', '', '', '', '', '', '', '', '', '', '', 0),
(14241, 'frFR', 'Au gyrocoptère !', 'Récupérez les Clés du gyrocoptère.', 'Les gens de l\'Alliance ont volé quelque chose de très précieux pour la Horde et l\'ont emporté sur leurs bateaux.$B$BÀ l\'autre bout de la plage, il y a un gyrocoptère. Notre lige-d\'armes couvrira votre approche.$B$BRécupérez les clés de cette machine volante sur l\'un de leurs agents.$B$BVous pourrez alors voler jusqu\'à leur vaisseau, le Vogue-Vengeance, et ramener notre précieuse cargaison !', '', '', '', '', '', '', '', '', '', 'Allez au Gyrocoptère à la Tête de pont de l\'Alliance, sur les Îles Perdues.', 0),
(14242, 'frFR', 'Une cargaison précieuse', 'Trouvez la précieuse cargaison sous le pont du vaisseau de l\'Alliance, le Vogue-Vengeance, au large des Îles Perdues.', 'Ils ont dit que leur « précieuse cargaison », peu importe sa nature, était conservée sur le vaisseau de l\'Alliance, le Vogue-Vengeance.$B$BIl n\'y a qu\'une chose à faire... Utilisez ce truc pour voler jusque là-bas et récupérez cette cargaison !', '', 'Précieuse cargaison découverte', '', '', '', '', '', '', '', '', 0),
(14243, 'frFR', 'La vengeance du chef de guerre', 'Utilisez les pouvoirs du Cyclone des éléments pour tuer 50 Marins de l\'Alliance.$B$BUne fois que ce sera fait, vous serez $grenvoyé:renvoyée; sur le Surplomb Sauvage.', 'Frères de la Terre et du Feu, entendez-moi ! Sœurs de l\'Air et de l\'Eau, répondez à mon appel !$B$BAzeroth est au bord du précipice, son existence vouée à disparaître ! Prêtez-moi votre puissance, comme vous l\'avez fait par le passé avec mes ancêtres. Permettez-moi de canaliser votre volonté dans $gcet enfant:cette enfant; de Kezan.$B$BAidez-nous à arrêter ceux qui veulent nous empêcher de soigner ce monde !', '', '', '', '', '', '', '', '', '', 'Parlez au Chef de guerre au Surplomb Sauvage, sur les Îles Perdues.', 0),
(14244, 'frFR', 'Les gobelins s\'envolent vers d\'autres cieux', 'Survivez au tir de la Fronde à fusées au-dessus de la Mauvaise passe.', 'Pendant que vous aidiez le chef de guerre et que vous nous sauviez tous de l\'Alliance, le contremaître Mèchumide a fabriqué cette fronde à fusées pour nous projeter au-dessus de la mer infestée de requins, droit sur la plus grande île.$B$BHeureusement pour nous, Mèchumide a réussi à récupérer une ville-en-boîte dans l\'épave. Une fois que vous l\'aurez montée, nous aurons notre propre ville. J\'ai hâte de dormir à nouveau dans un vrai lit !$B$BLe contremaître vous attend au site d\'atterrissage. Pourquoi ne pas emprunter la fusée suivante ?', '', 'Voyage en fronde à fusées surmonté', '', '', '', '', '', '', '', 'Parlez au Contremaître Mèchumide au Site d\'atterrissage, sur les Îles Perdues.', 0),
(14245, 'frFR', 'C\'est une Ville-en-Boîte', 'Monter au sommet de la montagne d\'explosifs et utiliser la Ville-en-Boîte.', 'Le prince marchand avait une ville-en-boîte entière dans sa cale ! J\'ai réussi à la récupérer pendant que vous étiez en train de nous sauver.$B$BVoulez-vous avoir les honneurs ? Tout ce que vous avez à faire, c\'est grimper au sommet de cette immense pile d\'explosifs et d\'appuyer sur le détonateur et... boum badaboum... une ville en un clin d\'œil !', '', 'Ville-en-Boîte déployée !', '', '', '', '', '', '', '', 'Parlez au Contremaître Mèchumide au Site d\'atterrissage, sur les Îles Perdues.', 0),
(14246, 'frFR', 'Une adoption précoce', 'Placez 3 Œufs de rapace dans des Nids de rapace et protégez-les jusqu’à ce qu’ils soient en lieu sûr.', 'Au fur et à mesure que la région devient luxuriante, les créatures du désert se retrouvent progressivement confinées dans des espaces réduits.$b$bConséquence alarmante : les rapaces locaux sont en voie de disparition. Les prédateurs se repaissent des oiseaux et de leurs œufs au moment de la nidification.$b$bJ’ai récupéré des œufs de rapaces de Tanaris puis je les ai enduits d’une phéromone irrésistible. Placez-en un dans chaque nid que vous trouverez, puis protégez-le jusqu’à ce qu’un rapace vienne le chercher.$b$bVous contribuerez au rétablissement de l’écosystème de ces terres.', '', 'Œuf de rapace protégé', '', '', '', '', '', '', '', 'Retournez voir Thunk dans sa Demeure, en Désolace.', 0),
(14247, 'frFR', 'Terres rebelles', 'Thunk, de la Demeure de Thunk, veut que vous trouviez l’Affleurement anormal.', 'Par ordre du Cercle cénarien, je suis chargé de transformer ces terres arides en prairies verdoyantes.$b$bAu sud, les terres ont bien accueilli cette croissance, mais ici quelque chose lutte et refuse la fertilisation.$b$bVos yeux verront peut-être ce qui a échappé aux miens.$b$bJe vous en prie, $r. Explorez ces terres et découvrez la source de la résistance du désert.', '', '', '', '', '', '', '', '', '', '', 0),
(14248, 'frFR', 'Besoin d\'aide', 'Parlez au Contremaître Méchumide à l\'extérieur de la Caverne de kaja\'mite sur les îles Perdues.', 'Bonne nouvelle ! Le contremaître Méchumide a découvert une caverne bourée de kaja\'mite sur cette île ! Qui l\'eût cru ?$B$BBien sûr, il y a une petite difficulté. Il a emmené quelques survivants avec lui pour l\'aider à exploiter le minerai, mais aucun d\'entre eux n\'a pu sortir de la caverne.$B$BAussi fou que cela puisse sembler, le contremaître dit qu\'il y a des singes dans la caverne… avec des pioches de mineur ! Ils récoltent la kaja\'mite ! Comment est-ce possible ?$B$BPourriez-vous aller vers la caverne, au sud-est ? Le contremaître est juste à l\'extérieur de l\'entrée.', '', '', '', '', '', '', '', '', '', '', 0),
(14249, 'frFR', 'À la mode de chez nous', 'Récupérez 80 Plumes de Tête-tonnerre en parfait état sur les Hippogriffes près des Ruines de Nordressa.', 'Je ferais un tabac en archimagie. Un tabac ! Il ne veut même pas m’adresser la parole parce que je ne porte pas une robe débile et un chapeau. Ppff.$B$BLe mage le plus puissant que cette région ait vu naître ne peut pas porter n’importe quelle robe et n’importe quel chapeau. Je dois lui montrer que je suis spécial, et je sais exactement comment m’y prendre.$B$BAllez tuer quelques hippogriffes. Rapportez-moi une TONNE de leurs plumes.$B$BVous m’avez bien compris ? Tout un tas de plumes ! Allez, allez. Le temps que vous reveniez, il ne manquera plus que les plumes à ma robe.', '', '', '', '', '', '', '', '', '', 'Retournez voir Will Robotronique aux Ruines de Nordressa.', 0),
(14250, 'frFR', 'Ressource renouvelable', 'Utilisez la Charge arcanique pour récupérer 5 morceaux de Basalte animé de Balboa, près des Ruines de Nordressa.', 'Il va nous falloir plus de basalte animé. Et la seule source fiable de la région est le géant des montagnes nommé Balboa. Si nous voulons conserver un stock constant de roche, nous ne pouvons pas tuer ce géant. Nous récupérons donc régulièrement quelques morceaux.$B$BLe chemin qu’il emprunte passe au nord-est et à l’est d’ici. Trouvez-le, placez la charge au bout du chemin, puis cachez-vous jusqu’à ce qu’elle explose. Quand il sera parti, vous pourrez récupérer le basalte et me le rapporter.', '', '', '', '', '', '', '', '', '', 'Retournez voir Tharkul Crâne-de-fer aux Ruines de Nordressa.', 0),
(14251, 'frFR', 'Un nouveau commencement', 'Obtenez 15 Dards de scorpion.', 'Les centaures n’ont jamais lancé d’attaques si loin au nord. On les a poussés à le faire, j’en suis sûr !$b$bRésultat, je n’ai plus rien. J’avais tout investi dans ce machin.$b$bHeureusement, il y a une chose qu’aucun centaure ne pourra jamais me prendre : l’ingéniosité gobeline ! Je vais prendre un nouveau départ et bâtir un empire !$b$b<Bizby repère un scorpion au loin.>$b$bLe marché du poison est toujours intéressant. Pas vrai, l\'$gami:amie; ?', '', '', '', '', '', '', '', '', '', 'Retournez voir Bizby à sa Caravane, en Désolace.', 0),
(14252, 'frFR', 'Le basilic est une espèce sonnante et trébuchante', 'Trouvez 15 Queues de basilic âgé.', 'Il me faut beaucoup de queues, $c ! Mais pas n’importe lesquelles. Les queues que je recherche doivent être vieilles, très vieilles même. Plus elles sont décrépites, mieux c’est.$b$bLes écailles de la queue des basilics sont uniques car elles durcissent avec le temps sans se casser. Ces écailles durcies sont idéales pour la confection de certaines armures.$b$bÇa fait longtemps que je n’en ai pas été réduit à revendre des écailles de lézard, mais peut-être que ça forgera encore plus mon caractère après tout ! Enfin, si c’est possible…', '', '', '', '', '', '', '', '', '', 'Retournez voir Bizby à sa Caravane, en Désolace.', 0),
(14253, 'frFR', 'Si votre empennage se rapporte à votre plumage…', 'Collectez 25 Plumes de rapace redoutable.', 'Dites, $c, pendant que vous en êtes à explorer ces étendues désertiques, vous pourriez peut-être me rendre un service ?$b$bSurveillez les rapaces redoutables. Leurs plumes graisseuses sont parfaites pour l’empennage, et on pourrait en tirer un bon prix.$b$bHeureusement pour vous, je connais tous les meilleurs acheteurs !', '', '', '', '', '', '', '', '', '', 'Retournez voir Bizby à sa Caravane, en Désolace.', 0),
(14254, 'frFR', 'Le 116ème élément', 'Vous devez trouver 7 morceaux d’Élément 116 et les rapporter à Bizby, à la Caravane de Bizby.', 'Vous avez le sentiment que cette pierre est responsable, d’une façon ou d’une autre, de l’infertilité de la région.$b$bEn regardant vers l’ouest, vous remarquez une traînée de débris fumants qui semble être liée à ce mystère.$b$bVous supposez que dégager ces débris rendrait service à Thunk.$b$bEt qui sait à quoi ce matériau pourrait servir ?', '', '', '', '', '', '', '', '', '', '', 0),
(14255, 'frFR', 'Ethel Rethor', 'Cérélia, du Poste de Furien, vous a demandé d’aller parler à Korrah, à Ethel Rethor.', 'Nous avons déjà bien assez d’ennemis dans la région, il ne faut pas nous attirer la colère du Cercle cénarien.$b$bQuand nous avons établi notre poste ici, ils nous ont chargés de veiller sur l’une de ses chercheuses.$b$bKorrah a été vue pour la dernière fois dans la tour à l’ouest. Auriez-vous l’amabilité d’aller la voir ? Nous n’y sommes pas allés depuis un bon moment.', '', '', '', '', '', '', '', '', '', '', 0),
(14256, 'frFR', 'La menace venue de la mer', 'Korrah veut que vous alliez lui parler quand vous serez $gprêt:prête; à découvrir la menace naga.', 'Je suis la dernière du groupe qui a été envoyé ici pour étudier les nombreux changements survenus sur la côte de Désolace.$b$bJ’ai signalé l’augmentation impressionnante du nombre de nagas, mais sans résultat.$b$bMes pairs sont absorbés par d’autres crises, alors je dois vous demander, à vous, $gun étranger:une étrangère;, de m’aider dans mes recherches.$b$bMais avant cela, laissez-moi vous montrer la menace qui pèse sur nous.', '', 'Troupes nagas espionnées', '', '', '', '', '', '', '', 'Parlez à la chercheuse cénarienne Korrah à Ethel Rethor, en Désolace.', 0),
(14257, 'frFR', 'Ondulames laminés', 'Collectez 10 Ossements ondulame sur les Nagas ondulame, 30 Écailles ondulame sur les Sorcières ondulame, et 4 Nageoires ondulame sur les Guerriers ondulame.', 'Les nagas ont prouvé à plusieurs reprises qu’ils étaient les ennemis de l’équilibre de la nature. Je n’ai aucun scrupule à voir verser leur sang.$b$bMais tous vos efforts ne feraient qu’à peine entamer leurs troupes. On dirait que quand l’un meurt, il y en a deux pour prendre sa place.$b$bJ’ai un plan, $c. Votre objectif n’est pas seulement de leur prendre la vie, mais aussi de rassembler les composants nécessaires pour la prochaine étape de votre enquête…', '', '', '', '', '', '', '', '', '', 'Retournez voir la chercheuse cénarienne Korrah à Ethel Rethor, en Désolace.', 0),
(14258, 'frFR', 'À bas les nagas !', 'Récupérez 5 Obus de mortier gobelins dans le Laboratoire secret, en Azshara.', 'Les nagas ont commencé à envahir la péninsule après qu’on a terminé la construction de ce terminus du fusorail. Mais il n’y a rien en ce monde qu’on ne puisse résoudre avec la bonne puissance de feu ! C’est ce que mon père disait. Avant l’accident.$B$BMais, il ne me reste presque plus de réserves. Rendez-moi service en allant récupérer les obus de mortier que j’ai laissés dans le laboratoire secret, juste à l’ouest d’ici. Réapprovisionnez-moi et je vous laisserai lancer les frappes d’artillerie !', '', '', '', '', '', '', '', '', '', 'Apportez les obus au Capitaine bombardier Smooks au Terminus sud du fusorail, en Azshara.', 0),
(14260, 'frFR', 'Gloups ! Je suis un naga !', 'Utilisez le Charme ondulame.', 'J’ai fabriqué un charme qui vous permettra de vous infiltrer parmi les nagas, en vous donnant l’apparence de l’un de leurs congénères.$b$bGrâce à ce déguisement, vous pourrez parler leur langue et la comprendre. Ils n’auront aucun moyen de déceler votre véritable identité.$b$bMais prenez garde ! Les requins et autres créatures aquatiques révèleront votre vraie forme aux yeux de tous. Évitez-les à tout prix.$b$bMaintenant, partez. Allez parler à la prêtresse d’Azshara et faites en sorte de découvrir ses intentions.', '', 'Charme ondulame utilisé', '', '', '', '', '', '', '', 'Parlez à Valishj au Rivage des Ondulames, en Désolace.', 0),
(14261, 'frFR', 'Un froid glacial', 'Utilisez le Cryomatic 16 pour congeler et tuer 8 Drakes sable.', 'J’ai la solution parfaite à notre problème de drakes. Il s’agit de mon très cher Cryomatic 16.$B$BAu départ, je l’avais mis au point pour congeler mes ouvriers durant le transport et entre les changements pour ne pas avoir à les nourrir et à les occuper, mais il y a eu des… complications. Mais ça devrait être parfait pour faire tomber ces drakes du ciel !', '', '', '', '', '', '', '', '', '', 'Retournez voir Feno Explozmuso au Terminus Nord du fusorail.', 0),
(14262, 'frFR', 'Noyer le poisson', 'Tuez 6 Furies des tempêtes fouette-bile et 6 Mande-mers fouette-bile.', 'Je suis fatigué de combattre des créatures qui peuvent disparaître à volonté dans la mer et émerger n’importe où. Mais je n’abandonnerai pas tant qu’Azshara ne sera pas débarrassée de leur espèce.$B$BLes nagas fouette-bile ont rampé le long des parois de la falaise et assiègent ce poste par l’est. Détruisez-les, $n, et videz-les ! Qu’ils subissent la fureur de la Horde !', '', '', '', '', '', '', '', '', '', 'Retournez voir Torg Broie-double au Terminus sud du fusorail, en Azshara.', 0),
(14263, 'frFR', 'Perte de thym', 'Récupérez 8 bouquets de Thym de l\'ire vivante près des Ruines de Nordressa.', 'Du thym de l’ire vivante. Il m’en faut plus ! Faites vite, s’il vous plaît.', '', '', '', '', '', '', '', '', '', 'Retournez voir Quarla Sifflepause aux Ruines de Nordressa.', 0),
(14264, 'frFR', 'L’eau, ça mouille', 'Anéantissez 5 Serviteurs de Neptulon. (Vous devez adopter la forme de naga pour les tuer).$b$bSi vous perdez votre Trident ondulame, adressez-vous à Valishj.$b$bSi vous perdez votre Charme ondulame, adressez-vous à Korrah, à Ethel Rethor.', 'Les sbires de Neptulon viennent d’arriver et mettent tout en œuvre pour contrecarrer nos plans. Ils ont manifestement découvert nos intentions.$b$bCela ne fait que confirmer que ce que nous cherchons se trouve effectivement dans ces ruines !$b$bCes élémentaires d’eau ne font pas le poids face à nos troupes ! Prenez ce trident et utilisez-le pour détruire les minables serviteurs du Chasse-marée.$b$bLorsque nous aurons trouvé ce que nous cherchons, Neptulon lui-même craindra pour sa vie !', '', 'Serviteurs de Neptulon anéantis', '', '', '', '', '', '', '', 'Retournez voir Valishj au Rivage des Ondulames, en Désolace.', 0),
(14265, 'frFR', 'Votre instructeur', 'Parlez au Sergent Cleese dans le Secteur Militaire.', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu’un m’a demandé de vos nouvelles : un type qui disait s’appeler Cleese dont vous seriez l’$gun:une; des $gétudiants:étudiantes;. Il voulait s’assurer que vous alliez bien.', '', '', '', '', '', '', '', '', '', '', 0),
(14266, 'frFR', 'À la charge !', 'Atteignez le Niveau 3 pour apprendre la Charge. Ensuite, exercez-vous à utiliser la Charge contre un Worgen croc-de-sang.', 'Vous êtes toujours en vie, $n ! Ça en dit long sur mon enseignement !$B$BEt encore, nos leçons ont été interrompues. Mais à mesure que vous apprendrez par vous-même, vous découvrirez de nouvelles techniques.$B$BAllez donc gagner plus d’expérience, apprenez une nouvelle compétence, puis essayez-la contre les worgens croc-de-sang qui sont à l’ouest.', '', 'S’exercer à la Charge', '', '', '', '', '', '', '', 'Retournez voir le Sergent Cleese dans le Secteur Militaire.', 0),
(14267, 'frFR', 'Enquête au sanctuaire de la mer', 'Inspectez le Sanctuaire naga pour Torg Broie-double.', 'Les envahisseurs nagas ont bâti une kyrielle de sanctuaires le long des falaises. J’ignore leurs intentions, $n, mais je pense qu’ils renforcent les troupes ennemies. Il faut que vous y alliez et que vous éradiquiez ce mal.$B$BL’un des sanctuaires à proximité est peu défendu. Traversez le premier pont, à l’est d’ici, puis dirigez-vous au nord, vers la baie. Le sanctuaire se trouve sur un petit affleurement. Inspectez-le, puis revenez me voir avec des informations utiles.', '', '', '', '', '', '', '', '', '', 'Inspectez le Sanctuaire naga aux Falaises de la Tempête pour Torg Broie-double.', 0),
(14268, 'frFR', 'L’impact', 'La prêtresse Valishj vous a demandé de trouver les Gravures antiques de Neptulon.', 'La reine Azshara veut entrer dans le plan de l’Eau, mais j’ignore pourquoi.$b$bElle pense que les anciens savaient où il se trouvait.$b$bJe suis personnellement chargée de fouiller les ruines de cette région, et il n’y aura aucun répit jusqu’à ce que nous découvrions les secrets que nous cherchons !$b$bAu nord se trouvent des ruines enfouies. Utilisez ce bâton pour chercher sous les décombres.$b$bNe revenez me voir que lorsque vous aurez trouvé l’objet de notre quête !', '', '', '', '', '', '', '', '', '', '', 0),
(14269, 'frFR', 'Quelqu’un vous cherche', 'Parlez à Loren la Receleuse dans le Secteur Militaire.', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu’un m’a demandé de vos nouvelles : une femme qui disait s’appeler Loren... Elle a eu l’air un peu déçu quand je lui ai dit que vous alliez bien.$B$BJe crois qu’elle a parlé d’argent qu’elle vous devait.', '', '', '', '', '', '', '', '', '', '', 0),
(14270, 'frFR', 'L’éclat de la pierre de voûte', 'Trouvez l’Éclat de la pierre de voûte, à proximité.', 'L’air qui entoure cette pierre étrange crépite d’énergie. La pierre en elle-même est lisse et très froide. Lorsque vous la touchez, elle scintille de temps à autre, tel le roulement des vagues.$B$BSur le dessus de l’artéfact, un emplacement vide semble destiné à recevoir une pièce à bout pointu. Cet « éclat de la pierre de voûte » est probablement la clé qui permettra de percer les secrets de la pierre. L’éclat doit se trouver par terre, près du temple.', '', '', '', '', '', '', '', '', '', 'Placez l’Éclat de la pierre de voûte sur la Pierre de puissance naga aux Falaises de la Tempête, en Azshara.', 0),
(14271, 'frFR', 'Présentez-vous à Broie-double', 'Retournez voir Torg Broie-double au Terminus sud du fusorail, en Azshara, et informez-le de votre découverte.', 'Une barrière magique scintille autour de vous et vous fait frissonner. Ce mur enchanté vous apporte un sentiment de sécurité.$B$BTorg Broie-double voudra certainement savoir ce que vous avez découvert ici !', '', '', '', '', '', '', '', '', '', 'Retournez voir Torg Broie-double au Terminus sud du fusorail, en Azshara, et informez-le de votre découverte.', 0),
(14272, 'frFR', 'L’éviscération', 'Atteignez le Niveau 3 pour apprendre Éviscération, puis exercez-vous à utiliser Éviscération contre un Worgen croc-de-sang.', 'Heureuse de vous voir en vie !$B$BBien sûr que non, je n’ai pas l’or que je vous dois. Vous croyez vraiment que c’est le moment de parler de ça ?$B$BJ’ai une idée ! Je peux vous apprendre un truc ou deux qui pourraient vous sauver la peau au milieu de tout ce carnage.$B$BEn apprenant à combattre, vous découvrirez de nouvelles choses. Allez gagner de l’expérience, et quand vous aurez appris une nouvelle technique, essayez-la contre les worgens croc-de-sang. Je vous observerai.', '', 'S’exercer à l’Éviscération', '', '', '', '', '', '', '', 'Retournez voir Loren la Receleuse dans le Secteur Militaire.', 0),
(14273, 'frFR', 'D’obscurs associés', 'Parlez à Vitus Sombremarcheur dans le Secteur Militaire.', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu’un m’a demandé de vos nouvelles : un type bizarre qui disait s’appeler Vitus... Il m’a donné la chair de poule.$B$BIl n’arrêtait pas de parler de « savoir interdit » qu’il avait découvert.', '', '', '', '', '', '', '', '', '', '', 0),
(14274, 'frFR', 'Corruption', 'Atteignez le Niveau 3 pour apprendre la Corruption, puis utilisez-la contre un Worgen croc-de-sang.', 'Alors c’était vrai ! Vous êtes $gvivant:vivante; !$B$BJe n’ai jamais eu l’occasion de vous mettre au courant de ma plus grande découverte. Une fois mon entraînement commencé, la voix de Balcephoth a résonné au plus profond de mon âme… il m’a enseigné les secrets interdits de…$B$Bla corruption !$B$BPartez, accumulez de l’expérience, et vous aussi, peut-être, découvrirez un nouveau sort. Vous pourrez ensuite l’utiliser contre les worgens croc-de-sang, à l’ouest d’ici.', '', 'S’exercer à la Corruption', '', '', '', '', '', '', '', 'Retournez voir Vitus Sombremarcheur dans le Secteur Militaire.', 0),
(14275, 'frFR', 'Quelqu’un vous suit à la trace', 'Parlez au Veneur Blake dans le Secteur Militaire.', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu’un m’a demandé de vos nouvelles : un type qui disait s’appeler Blake. Il a marmonné quelque chose à propos d’un plan pour s’échapper par les bois.', '', '', '', '', '', '', '', '', '', '', 0),
(14276, 'frFR', 'Le tir assuré', 'Atteignez le Niveau 3 pour apprendre le Tir assuré. Ensuite, exercez-vous au Tir assuré 2 fois contre un Worgen croc-de-sang.', 'J’ai une bonne et une mauvaise nouvelle.$B$BLa mauvaise, c’est que les bois sont encore plus infestés de worgens que la ville… Du coup, on n’a aucun endroit sûr où se planquer.$B$BLa bonne nouvelle, c’est que vous commencez à connaître la musique. Plus vous gagnez en expérience, plus vous apprenez de nouvelles choses.$B$BDès que vous aurez découvert votre première nouvelle compétence, faites-vous la main contre les worgens croc-de-sang à l’ouest.', '', 'S’exercer au Tir assuré', '', '', '', '', '', '', '', 'Retournez voir Veneur Blake dans le Secteur Militaire.', 0),
(14277, 'frFR', 'Enquêtes arcaniques', 'Parlez à Myriam Éveillesort dans le Secteur Militaire.', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu’un m’a demandé de vos nouvelles : une femme, une mage apparemment, qui disait s’appeler Myriam. Elle vous fait dire qu’il faut se tenir prêt, ou quelque chose comme ça.', '', '', '', '', '', '', '', '', '', '', 0),
(14278, 'frFR', 'Cherchez la sœur', 'Parlez à Sœur Almyra dans le Secteur Militaire.', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu’un m’a demandé de vos nouvelles : un membre du clergé, une sœur, qui disait s’appeler Almyra. Elle vous fait dire que vous courez un grave danger et que vous auriez grand besoin de la protection de la Lumière.$B$BVous devriez aller lui parler, elle avait l’air vraiment très inquiet.', '', '', '', '', '', '', '', '', '', '', 0),
(14279, 'frFR', 'Apprendre le mot', 'Atteignez le Niveau 3 pour apprendre le Mot de l’ombre : Douleur, puis utilisez-le à deux reprises contre un Worgen croc-de-sang.', 'Vous avez beaucoup à apprendre, $n. Et j’ai de nombreuses choses à vous enseigner.$B$BCependant, nous vivons des temps troublés, et j’ai bien peur que vous ne deviez découvrir beaucoup de choses par vous-même.$B$BNe craignez rien, $gmon frère:ma sœur;. La Lumière nous guidera à travers cette épreuve.\n\nAllez, engrangez de l’expérience et apprenez une nouvelle compétence, puis utilisez-la contre les worgens croc-de-sang à proximité.', '', 'S’exercer au mot de l’ombre : Douleur', '', '', '', '', '', '', '', 'Retournez voir Sœur Almyra dans le Secteur Militaire.', 0),
(14280, 'frFR', 'Les vents connaissent votre nom... apparemment', 'Parlez à Célestine de la Moisson dans le Secteur Militaire.', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu’un m’a demandé de vos nouvelles : c’était cette sorcière des moissons, vous savez, Célestine. Elle vous fait dire que les vents parlent de vous.$B$BVous feriez mieux de filer la voir, $n. Mais il faudra que vous reveniez très vite nous aider à massacrer du worgen, une fois que vous en aurez terminé avec votre petite conversation avec la nature.', '', '', '', '', '', '', '', '', '', '', 0),
(14281, 'frFR', 'Nova de givre', 'Atteignez le Niveau 3 pour apprendre la Nova de givre, puis utilisez-la contre un Worgen croc-de-sang.', 'Une dure tâche nous attend, $n. Nous devrons lui consacrer toute notre puissance mentale sans restriction.$B$BÀ mesure que vous gagnerez en puissance, de nouveaux chemins menant aux arcanes s’ouvriront à vous. Vous développerez des sorts vous étant jusqu’alors inconnus.\n\nAllez, accumulez de l’expérience, puis utilisez vos nouvelles connaissances contre les worgens croc-de-sang.', '', 'S’exercer à la Nova de givre', '', '', '', '', '', '', '', 'Retournez voir Myriam Eveillesort dans le Secteur Militaire.', 0),
(14282, 'frFR', 'Mystère résolu', 'Vous devez apporter les Gravures antiques de Neptulon à Korrah, la chercheuse du Cercle cénarien.', 'Vos efforts ont fini par payer. Les risques que vous avez pris n’ont pas été vains.$b$bVous avez découvert l’objet convoité par les nagas et la raison de leur invasion sur la côte de Désolace.$b$bEt concernant les gravures que vous avez trouvées, vous savez ce que vous avez à faire…', '', '', '', '', '', '', '', '', '', '', 0),
(14283, 'frFR', 'Éclat lunaire', 'Atteignez le Niveau 3 pour apprendre l’Éclat lunaire, puis utilisez-le contre un Worgen croc-de-sang.', 'Nous avons déjà failli connaître l’extinction, $n. Mais nous autres druides, gardiens des anciennes traditions, avons sauvé notre peuple de la famine.$B$BLorsque nous nous sommes coupés du monde extérieur et que nos récoltes n’ont rien donné, c’est notre ordre qui en a appelé à la bénédiction de la terre pour sauver la moisson.$B$BTout comme nos pouvoirs ont sauvé la moisson, en grandissant, votre puissance développera votre connexion à nos arts anciens.\n\nAllez, travaillez vos pouvoirs, et utilisez vos connaissances ainsi acquises contre les worgens croc-de-sang.', '', 'S’exercer à l’Éclat lunaire', '', '', '', '', '', '', '', 'Retournez voir Célestine de la Moisson dans le Secteur Militaire.', 0),
(14284, 'frFR', 'La vengeance d\'un revenant', 'Hydronis veut que vous le chevauchiez pour aller tuer la Prêtresse Valishj.', 'Je me nomme Hydronis, serviteur de Neptulon le chasse-marée, seigneur des mers et des océans.$b$bAzshara et ses monstrueux nagas se sont ligués contre mon maître, et veulent entrer en guerre contre lui. C’est le premier conflit d’une lutte qui s’annonce longue et difficile.$b$bJ’ai longtemps combattu, $r, et je suis las.$b$bJe crois que mes efforts ici ont attiré l’attention de leur prêtresse.$b$bJe n’ai pas la force de la vaincre, mais peut-être y parviendrons-nous ensemble.', '', 'Valishj tuée', '', '', '', '', '', '', '', '', 0),
(14285, 'frFR', 'Le groupe apporte la sécurité', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Il y a des limites à ce que je peux vous enseigner tant que ces worgens tenteront de nous démembrer.$B$BNous devrions envisager de partir vers le sud avec les autres survivants. On nous a dit que le roi Grisetête était déjà là-bas.$B$BSi nous restons ensemble, nos chances de survie augmenteront... surtout si l\'on choisit de rester avec quelqu\'un qui a l\'air plus... appétissant.', '', '', '', '', '', '', '', '', '', '', 0),
(14286, 'frFR', 'Le groupe apporte la sécurité', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Je vous ai appris tout ce dont vous avez besoin pour l’instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BNous devrions aller là-bas. Nous serons plus en sécurité en étant tous réunis.', '', '', '', '', '', '', '', '', '', '', 0),
(14287, 'frFR', 'Le groupe apporte la sécurité', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Je vous ai appris tout ce dont vous avez besoin pour l\'instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BNous devrions aller là-bas. Nous serons plus en sécurité en étant tous réunis.', '', '', '', '', '', '', '', '', '', '', 0),
(14288, 'frFR', 'Le groupe apporte la sécurité', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Il y a des limites à ce que je peux vous enseigner tant que ces worgens tenteront de nous démembrer.$B$BNous devrions envisager de partir vers le sud avec les autres survivants. On nous a dit que le roi Grisetête était déjà là-bas.$B$BSi nous restons ensemble, nos chances de survie augmenteront... surtout si l\'on choisit de rester avec quelqu\'un qui a l\'air plus... appétissant.', '', '', '', '', '', '', '', '', '', '', 0),
(14289, 'frFR', 'Le groupe apporte la sécurité', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Je vous ai appris tout ce dont vous avez besoin pour l\'instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BLes survivants vont avoir besoin de l\'aide de la Lumière en ces temps troublés.', '', '', '', '', '', '', '', '', '', '', 0),
(14290, 'frFR', 'Le groupe apporte la sécurité', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Je vous ai appris tout ce dont vous avez besoin pour l\'instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BNous devrions aller là-bas. Nous serons plus en sécurité en étant tous réunis.', '', '', '', '', '', '', '', '', '', '', 0),
(14291, 'frFR', 'Le groupe apporte la sécurité', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Je vous ai appris tout ce dont vous avez besoin pour l\'instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BNous devrions aller là-bas. Nous serons plus en sécurité en étant tous réunis.', '', '', '', '', '', '', '', '', '', '', 0),
(14292, 'frFR', 'L\'ennemi de notre ennemi', 'Korrah, la chercheuse cénarienne, vous a demandé de parler au Seigneur Hydronis.', 'Vous nous avez rendu un grand service, $c.$b$bMême si les nagas restent nombreux, vos efforts ont permis de les empêcher de mettre la main sur une relique précieuse.$b$bJe ferai part de vos découvertes à mes pairs. En attendant, le revenant d’eau, sur l’île de Ranazjar, affronte seul les assauts incessants des nagas.$b$bJ’aimerais que vous le rejoigniez et que vous trouviez un moyen de l’aider.', '', '', '', '', '', '', '', '', '', '', 0),
(14293, 'frFR', 'Sauver Krennan Aranas', 'Portez secours à Krennan Aranas.', 'Les années ont passé depuis la guerre, mais Crowley cachait encore suffisamment d\'armes dans cette cave pour raser la moitié du secteur.$B$BEt on risque de devoir en arriver là, malheureusement.$B$BMais nous ne pouvons pas ouvrir le feu tout de suite. Il y a un civil piégé de l\'autre côté de la prison.$B$BEt ce n\'est pas n\'importe qui, en plus. Il s\'agit de Krennan Aranas, l\'un des plus brillants alchimistes que ce monde ait connu.$B$BL\'une de ses potions a sauvé ma fille, Tess, alors qu\'elle venait de naître.$B$BPrenez mon cheval et sauvez Krennan. Il faut qu’il vive.', '', 'Krennan Aranas sauvé', '', '', '', '', '', '', '', 'Parlez au Seigneur Godfrey dans le Secteur Militaire de la ville de Gilnéas.', 0),
(14294, 'frFR', 'Il est temps de se regrouper', 'Parlez au roi Genn Grisetête dans la Cour de Grisetête, dans la ville de Gilnéas.', 'Nous avons fait de notre mieux. Allez dire au roi Grisetête que nous avons réussi à gagner du temps.$B$BJ\'ai comme l\'impression qu\'il ne faudra pas longtemps aux worgens pour revenir en force.$B$BNous devrons nous retrancher dans la cour de Grisetête, à l\'ouest, si c\'est le cas. C\'est le dernier endroit que nous pourrons tenir sans nous faire coincer comme des rats.', '', '', '', '', '', '', '', '', '', '', 0),
(14295, 'frFR', 'Les sœurs de la mer', 'Tuez Dame Silisthra et Dame Vesthra en désactivant leurs pierres de puissance.', 'Deux sorcières nagas sont à l’origine de l’assaut de cet avant-poste. Elles ont repoussé les attaques directes de certains de mes meilleurs grunts, mais vous pouvez finir le boulot là où d’autres ont échoué.$B$BTraquez et abattez dame Silisthra et dame Vesthra à l’extrémité est des falaises, près des ruines de l’antique colosse elfe de la nuit. Vous devrez d’abord détruire les pierres de puissance qui leur confèrent cette force. Ne me décevez pas, $c !', '', '', '', '', '', '', '', '', '', 'Retournez voir Torg Broie-double au Terminus Sud du fusorail, en Azshara.', 0),
(14296, 'frFR', 'Attention à la marche', 'Absorbez 6 Charges énergisées en montant le long des Conduits d’énergie jusqu’à la Cime des Arcanes.', 'C’est simple et compliqué à la fois. Il y a des conduits d’énergie qui montent jusqu’en haut. Un peu comme celui que vous voyez là, si on peut dire ! En fait, je le dis.$B$BMaintenant, votre boulot. Vous devez utiliser mes tremplins pour monter jusqu’à la cime en touchant tous les conduits que vous croiserez en chemin. Quand vous m’aurez rejoint au sommet, vous devriez crépiter d’énergie, vous n’aurez pas vraiment le choix.$B$BEt n’oubliez pas de rester en mouvement ou vous allez faire une sacrée balade !', '', 'Test arcanique terminé', '', '', '', '', '', '', '', 'Allez voir l’Image de l’archimage Xylem au sommet de la Cime des Arcanes.', 0),
(14297, 'frFR', 'Pro-libération', 'Récupérez des Clés en fer forgé sur des Sectateurs et des Draconiens, puis utilisez-les pour libérer 4 Ouvriers gobelins, sur la Crête Fuligineuse.', 'Je savais que ces types nous causeraient des ennuis dès qu’on a commencé à construire cette tour. Ils encaissent les pots-de-vin à notre place. Ils volent nos ouvriers.$B$BLa main d’œuvre n’est pas bon marché ici, en Azshara, avec tous ces chantiers de construction. Je veux récupérer mes hommes !', '', 'Travailleurs de Baille-Fonds secourus', '', '', '', '', '', '', '', 'Retournez voir Jellix Allumèche au Terminus nord du fusorail.', 0),
(14299, 'frFR', 'Le refuge de Xylem', 'Prenez le portail pour accéder à la tour de l’Archimage Xylem et cherchez-y Joanna.', 'Vous avez fait un travail fantastique ! Un véritable régal pour les yeux ! Cela mériterait d’être étudié de plus près.$B$BBon, filez maintenant. Joanna vous attend dans ma tour, elle vous récompensera. Je vais vous ouvrir un portail.', '', '', '', '', '', '', '', '', '', '', 0),
(14300, 'frFR', 'L\'Épreuve du Feu', 'Terminez l’Épreuve du Feu en sautant entre les runes de feu sans vous faire toucher par le feu pendant 10 explosions consécutives.', 'L’Épreuve du Feu… oooh… ça fait peur, hein? Non ? Hmm. Eh bien, je pensais que c’était le cas. Tout d’abord, il faut que vous touchiez le cristal de feu et le portail de l’épreuve s’ouvrira.$B$BPour passer cette épreuve, vous devez sauter entre les runes de feu sans que le feu ne vous atteigne. Si vous réussissez à éviter le feu suffisamment longtemps, vous remportez l’épreuve !$B$BVoici quelques petites astuces : le feu se déclenche de rune en rune, et il s’éteint quand une rune se refroidit. Vous pouvez le constater par vous-même, si vous voulez. Ou y aller à l’aveuglette ! C’est ce que font la plupart des gens.', '', 'Épreuve du Feu terminée', '', '', '', '', '', '', '', 'Allez voir l’Image de l’archimage Xylem à l’Épreuve du Feu.', 0),
(14301, 'frFR', 'Rapport : le retour', 'Vous devez retourner voir Korrah, la chercheuse cénarienne, à Ethel Rethor.', 'Enfin ! Ensemble, nous avons pu venir à bout d’un adversaire coriace.$b$bNeptulon en personne entendra parler de vos exploits, $c. Permettez-moi de vous transmettre ses remerciements…$b$bVous devriez partir, maintenant. Vous ne serez plus longtemps en sécurité ici. Les nagas chercheront bientôt à venger leur prêtresse.', '', '', '', '', '', '', '', '', '', '', 0),
(14302, 'frFR', 'Analyse officielle', 'Korrah, la chercheuse cénarienne, vous a demandé d’apporter le Rapport de Korrah à Karnum, au bosquet de Karnum.', 'Vous avez combattu les nagas avec vaillance, $n. Mais j’ai bien peur que ce ne soit pas suffisant… Voici mon analyse officielle de la menace qu’ils représentent.$b$bJ’ai confiance en mes pairs des terres sauvages, ils feront ce qu’il faut.$b$bApportez ceci à Karnum au bosquet situé au centre des terres sauvages Cénariennes, au sud-est. Il saura quoi faire.$b$bMerci, $n. Et à bientôt.', '', '', '', '', '', '', '', '', '', '', 0),
(14303, 'frFR', 'Retourner voir Aggra', 'Informez Aggra sur les récents évènements au Camp de base de la Horde, sur les Îles Perdues.', 'Retournez au camp de base de la Horde et informez Aggra que nous sommes toujours en vie, $n.$B$BDites-lui que je poursuis ma route vers le surplomb Sauvage et que nous nous retrouverons sur le versant nord-ouest de l\'île. J\'espère vous y voir.$B$BNous traquerons les membres de l\'Alliance et les tuerons jusqu\'au dernier !', '', '', '', '', '', '', '', '', '', '', 0),
(14304, 'frFR', 'La théorie du sang', 'Obtenez 10 Sangsues gorgées de sang.', 'La terre n’est pas le seul élément à avoir subi des bouleversements en Désolace. Ici, la faune et la flore ont réagi à leur nouvel environnement de façon étrange, et parfois fascinante.$b$bLes lézards-tonnerre régénérés qui errent à l’ouest m’intéressent tout particulièrement.$b$bIl me faut un échantillon de leur sang.$b$bVous pourriez m’aider en commençant par utiliser ce bocal de sangsues sur quelques spécimens.$b$bLorsqu’elles se seront remplies du sang de ces bêtes, ramenez-les-moi.', '', '', '', '', '', '', '', '', '', 'Retournez voir Thressa Valambré à la Clairière de Karnum, en Désolace.', 0),
(14305, 'frFR', 'Le temps des récoltes', 'Trouvez 10 Chardons d\'aloès.', 'Le Cercle cénarien sait mieux que quiconque que cette oasis luxuriante pourrait s’assécher aussi rapidement qu’elle est apparue.$b$bIl ne faut pas interférer avec les mécanismes à l’œuvre ici, mais tenter de les encourager et de les préserver.$b$bUne nouvelle espèce de plante, très abondante dans la région, est apparue depuis le grand bouleversement.$b$bTrouvez-en quelques échantillons afin que je puisse les étudier et découvrir ce qu’ils ont à nous révéler.', '', '', '', '', '', '', '', '', '', 'Retournez voir la botaniste Ferrah à la Clairière de Karnum, en Désolace.', 0),
(14306, 'frFR', 'La mauvaise herbe', 'Tuez 7 Flagellants déracinés.', 'Avec un tel bouleversement écologique, il faut s’attendre à ce qu’une partie de la faune et de la flore ne réagisse pas aussi bien que nous le souhaiterions.$b$bLes flagellants déracinés en sont un parfait exemple. Ils déambulent dans les champs à l’est et au sud, et sont nuisibles pour la région. Il faut s’en débarrasser.$b$bTant que vous êtes là, n’hésitez pas à abattre tous ceux que vous croiserez.', '', 'Flagellants déracinés abattus', '', '', '', '', '', '', '', 'Retournez voir la botaniste Ferrah à la Clairière de Karnum, en Désolace.', 0),
(14307, 'frFR', 'Vents contraires', 'Détruisez 5 Tourbillons marchetempête.', 'Les vents du changement soufflent, $r. Cela ne fait aucun doute. $b$bNous devons régler de nombreux problèmes et agir. Le développement de notre oasis est particulièrement préoccupant.$b$bSa croissance a dépassé toutes nos espérances ainsi que notre entendement, mais elle se retrouve désormais confrontée à un obstacle. $b$bÀ l’ouest, à la limite de l’herbe et du sable, des tourbillons l’empêchent d’envahir le désert.$b$bAllez éliminer ces entraves à la vie !', '', 'Tourbillons marchetempête détruits', '', '', '', '', '', '', '', 'Retournez voir Karnum Tisse-marais dans la Clairière de Karnum, en Désolace.', 0),
(14308, 'frFR', 'Quand la science attaque', 'Utilisez l’Éliminafeu X-21 pour éteindre 8 feux et sauver 6 Chercheurs stagiaires des flammes du Laboratoire secret.$B$BSi vous perdez votre Éliminafeu, allez voir l\'Assistante Greely au Terminus Sud du fusorail.', 'Vous avez vu les explosions en arrivant ? Les flammes ont englouti le laboratoire secret ! Encore ! Si nous n’éteignons pas ce feu, nous allons atteindre une températurité critique qui finira en cascades de lave.$B$BTenez, je vous confie un bidon de gel liquide expérimental hyper-froid et pressurisé : c’est l’agent ignifuge le plus instable que la science connaisse ! (N’approchez pas ce bidon des flammes). Éteignez le feu et arrosez mes internes, puis contactez-moi par le haut-parleur du central de commande.', '', 'Feux du laboratoire secret éteints', 'Chercheurs stagiaires secourus', '', '', '', '', '', '', 'Contactez l’Assistante Greely en utilisant les haut-parleurs situés à l’extrémité ouest du Laboratoire secret, en Azshara.', 0),
(14309, 'frFR', 'Quota de kodos', 'Utilisez la Décoction de kodo près de 5 Kodos enragés.', 'Comme vous l’avez sûrement remarqué, la brutalité des changements survenus dans la région peut avoir des effets aussi bien positifs que négatifs sur la faune locale.$b$bAu sud et à l’est d’ici, les kodos enragés sont une menace constante pour tous ceux qui s’en approchent.$b$bIl est temps de mettre ma théorie à l’épreuve. J’ai utilisé le sang de lézard-tonnerre régénéré pour réaliser cette décoction. J’espère qu’elle apaisera les kodos quand ils la boiront.$b$bDéposez-la près d’un kodo enragé en vous tenant bien à distance !', '', 'Kodo enragé calmé', '', '', '', '', '', '', '', 'Retournez voir Thressa Valambré dans la Clairière de Karnum, en Désolace.', 0),
(14310, 'frFR', 'Erreur de segmentation : évacuation du noyau', 'Activez la Console de contrôle du réacteur et protégez le Noyau d’azsharite jusqu’au Terminus sud du fusorail. Utilisez l’Éliminafeu X-21 sur le noyau s’il se met à surchauffer.', 'Une fois le réacteur central purgé, je veux que vous me rapportiez le noyau. C’est un cristal entièrement composé d’azsharite raffinée, un minerai à la fois puissant et dangereux. Et d’un bel aspect. Ô, précieuse azsharite qui façonnera les mondes à venir !$B$BLe grand levier sur votre gauche fera descendre le noyau et me l’enverra directement par le système ferroviaire. Le noyau sera brûlant, vous devrez donc le refroidir de temps à autre à l’aide de l’éliminafeu jusqu’à ce que vous arriviez ici… Il ne faut pas qu’il atteigne une température critique !', '', 'Noyau d’azsharite apporté', '', '', '', '', '', '', '', 'Allez voir l’Assistante Greely au Terminus sud du fusorail, en Azshara.', 0),
(14311, 'frFR', 'Mise à contribution', 'Utilisez les Graines cénariennes à proximité de 5 Monticules fertiles, dans les Terres sauvages Cénariennes.', 'Nous vivons une époque formidable !$b$bLes anciennes zones désertiques de Désolace sont fertiles, débordantes de vie. Imaginez, $c, s’il en était de même pour tous les déserts d’Azeroth ! Peut-être qu’un jour…$b$bNous avons des problèmes importants à gérer ici, mais pourquoi ne pas prendre le temps d’apprécier ce merveilleux miracle ?$b$bEt pourquoi ne pas y participer ? Voici des graines cénariennes. Utilisez-les aux endroits les plus fertiles des terres sauvages.$b$bC’est le meilleur remède contre l’aridité !', '', 'Graines cénariennes plantées', '', '', '', '', '', '', '', 'Retournez voir la botaniste Ferrah à la Clairière de Karnum, en Désolace.', 0),
(14312, 'frFR', 'Des présentations sont de rigueur', 'Garren Vent-noir, de la clairière de Karnum, vous a demandé d’aller parler au khan Leh’prah.', 'J’ai eu vent de vos exploits ici, en Désolace, $n. Nous vous sommes redevables.$b$bMais j’ai bien peur de devoir vous impliquer dans une autre bataille, bien plus importante que le reste.$b$bLes récents bouleversements n’ont pas affecté que le paysage ici. Les vieux conflits ont fait place à des guerres sans merci. Mais je vais laisser notre hôte vous en dire davantage…$b$bLe khan Leh’prah est l’un des derniers survivants de la tribu des Kolkar qui possédait autrefois toute la région est de Désolace. Nous l’avons retrouvé à moitié mort à la frontière de nos terres. Écoutez-le.', '', '', '', '', '', '', '', '', '', '', 0),
(14313, 'frFR', 'De nouveau parmi les humains', 'Parlez à Krennan Aranas à Havre-du-Soir.', 'Alors, comme ça, la potion de Krennan ne vous a pas $gtué:tuée;, hein ? Et bien, ça veut sûrement dire que la part humaine en vous est restée aux commandes.$B$BJe n’ai pas de raison de vous tirer dessus du coup, enfin, pas encore.$B$BAllez raconter tout ça à Krennan Aranas, c’est une bonne nouvelle pour lui. C’est lui qui surveille le bâtiment où on garde les gens de votre… espèce.$B$BMais rappelez-vous bien, $n, je vous ai à l’œil. Ayez seulement l’air de faire un truc pas net et je vous colle une balle entre les deux yeux.', '', '', '', '', '', '', '', '', '', '', 0),
(14314, 'frFR', 'Sauve qui peut !', 'Tuez le Gardien magram, au Village des Magram.', 'Tout a commencé par un rêve récurrent, comme l’avertissement d’un danger à venir. J’ai vu des légions de démons s’abattre sur nous, dévaster nos terres.$b$bPuis le rêve s’est réalisé. La Lame-Ardente et ses maîtres démoniaques ont expulsé les Magram de leurs terres, vers le sud. À leur tour, les Magram ont vaincu mon peuple et pris possession de nos maisons.$b$bCe fut un combat acharné. Seule une poignée de Kolkar est encore en vie. J’aimerais que vous alliez à l’est, sur ce qui était autrefois ma terre, et que vous les libériez de leur prison.', '', 'Prisonniers kolkar libérés', '', '', '', '', '', '', '', 'Retournez voir le khan Leh’prah à la Clairière de Karnum, en Désolace.', 0),
(14316, 'frFR', 'Propriété cénarienne', 'Récupérez 7 Caisses de provisions cénariennes en territoire magram.', 'Depuis que les démons ont envahi leurs terres, les Magram ont rompu tout contact avec les étrangers.$b$bIls sont méfiants, hostiles et préfèrent voler aux autres plutôt que de subvenir à leurs propres besoins.$b$bUne grande partie de nos provisions a récemment disparu et nous soupçonnons les Magram.$b$bJe vous en prie, $n, partez à l’est sur leurs terres et cherchez nos provisions.', '', '', '', '', '', '', '', '', '', 'Retournez voir Garren Vent-noir à la Clairière de Karnum, en Désolace.', 0),
(14318, 'frFR', 'De délicates négociations', 'Le khan Leh’prah vous a demandé d’enfoncer la Lance du khan des Kolkar dans la Pierre du père et de la protéger des Magram jusqu’à ce que le Khan Kammah apparaisse.$b$bAllez parler au khan Leh’prah quand vous serez $gprêt:prête; à vous rendre sur le champ de bataille.', 'Il n’y a qu’une seule façon de gagner la confiance et la loyauté des Magram.$b$bLa violence !$b$bIls ont essuyé de nombreuses pertes suite à leur guerre contre mon clan. Ils occupent désormais une terre qui leur est inconnue, où ils luttent ne serait-ce que pour se nourrir.$b$bC’est le moment d’attaquer.$b$bVenez me parler quand vous serez $gprêt:prête;, puis allez planter ma lance dans la pierre du père. Si nous parvenons à en tuer suffisamment, leur khan se soumettra à notre volonté.', '', 'Briser la volonté des Magram', '', '', '', '', '', '', '', '', 0),
(14320, 'frFR', 'Il nous faut des ingrédients', 'Trouvez la Caisse d\'essence de mandragore.', 'Ah, oui. Pour autant que l\'on sache, il n’est pas possible de complètement guérir des effets de la Malédiction.$B$BNéanmoins, un traitement approprié vous permettra de rester maître de votre esprit et de l’empêcher de se transformer en celui d’un animal sauvage.$B$BC’est une chance que la médication ait eu de l’effet sur vous car, habituellement, cela ne fonctionne que pour les infections récentes.$B$BSi vous voulez avoir une chance de guérir complètement de la Malédiction, il faut continuer le traitement.$B$BJe vais avoir besoin d\'essence de mandragore pour vous concocter une nouvelle dose de mon sérum. Vous en trouverez dans une caisse cachée sous un abri au sud-ouest de la ville.', '', '', '', '', '', '', '', '', '', '', 0),
(14321, 'frFR', 'L\'invasion', 'Parlez à Gwen Armstead à Havre-du-Soir.', '<Un long couteau dont la garde est ornée d\'un crâne dépasse des côtes du milicien. Tandis que vous cherchez des indices aux alentours, vous apercevez deux vaisseaux de guerre à l\'apparence menaçante sur le rivage.>$B$B<Gilnéas est envahie. Allez en aviser le maire de Havre-du-Soir, Gwen Armstead.>', '', '', '', '', '', '', '', '', '', '', 0),
(14322, 'frFR', 'La science, c\'est le MAL !', 'Tuez 8 Hippogriffes chargés d’électricité statique.', 'J’étais en train d’essayer de domestiquer les hippogriffes de la région en utilisant une série de chocs électriques débilitants, jusqu’au moment où, pour une raison inconnue, ils sont devenus fous ! À présent, mes cobayes saccagent l’endroit sans raison apparente ! $C, allez massacrer mes expériences ratées avant qu’elles ne me trouvent.', '', '', '', '', '', '', '', '', '', 'Allez faire votre rapport à Tordux Pinces-joyeuses au Laboratoire secret, en Azshara.', 0),
(14323, 'frFR', 'Absorbant', 'Collectez 20 Gouttes d\'eau frémissante sur des Éclabousseurs maléfiques à l\'est des Ruines d\'Arkkoran.', 'Il me faut autre chose. De l’eau chaude.$B$BPas évident à trouver dans les parages. Aucune source d’eau chaude, personne à qui parler. Mais j’ai tout de même un avantage. Cette éponge… elle est ultra absorbante ! Utilisez-la pour éponger des éclabousseurs maléfiques sur le banc de sable, à l’est.$B$BQuand vous aurez récupéré assez d’eau, allez essorer l’éponge près de la tour pour invoquer l’élémentaire géant. Il a de l’eau chaude, lui.', '', '', '', '', '', '', '', '', '', 'Retournez voir Ergll sur la côte des Ruines d’Arkkoran.', 0),
(14324, 'frFR', 'Le plein d\'eau bouillante', 'Récupérez un Globe d’eau bouillante sur un Seigneur de l’eau brûlante, à la Tour d’Eldara.', 'Ergll vous a dit que vous pourriez utiliser l’éponge marine enchantée d’Azshara pour invoquer un élémentaire « géant » près de la tour d’Eldara, au nord-est.', '', '', '', '', '', 'D\'autres moyens récréatifs d\'ébouillantage d\'élémentaires d\'eau se sont avérés trop dangereux pour être commercialisés.', 'Seigneur de l\'eau brûlante', '', '', 'Retournez voir Ergll sur la côte des Ruines d’Arkkoran.', 0),
(14325, 'frFR', 'Un flanchet de basilic, et ça repart !', 'Collectez 5 Flanchets de basilic.', '<Le khan Kammah vous écoute expliquer la menace démoniaque, et les visions du khan Leh’prah.>$b$bNous n’avons de leçon à recevoir de personne au sujet des démons, $r. Ce sont eux qui ont chassé notre clan des terres de nos ancêtres.$b$bCe sont eux encore qui nous ont forcés à envahir les déserts kolkars, où nous luttons pour survivre.$b$bLa guerre contre les Kolkars a coûté cher à mon peuple. Les quelques survivants sont las et affamés.$b$bApportez de la nourriture à mon peuple et nous parlerons des démons.', '', '', '', '', '', '', '', '', '', 'Retournez voir le khan Kammah au nouveau Village Magram, en Désolace.', 0),
(14326, 'frFR', 'Rencontre au sommet', 'Remontez sur le pont du Vogue-Vengeance au large des Îles Perdues, et parlez à Thrall.', 'Je ne pensais pas me retrouver un jour à nouveau prisonnier de l\'Alliance. Je ne sais comment exprimer ma gratitude... $n, c\'est ça ?$B$BJe vous retrouve en haut et nous nous occuperons de ces scélérats.', '', '', '', '', '', '', '', '', '', '', 0),
(14327, 'frFR', 'Parole d’honneur', 'Le khan Kammah vous a demandé d’aller parler au khan Leh’prah.', 'Je crois que nous n’avons pas le choix.$b$bMême si coopérer avec les Kolkars ne m’enchante guère, le discours de leur khan me semble sage.$b$bVous pouvez aller lui donner ma parole que nous combattrons côte à côte.', '', '', '', '', '', '', '', '', '', '', 0),
(14328, 'frFR', 'Les trois petits princes', 'Tuez Rhoho, Sherik, et Jorreth.', 'Les Gelkis se trouvent au sud-ouest de Désolace. Ils sont aussi têtus que les Magram, mais comme ils n’ont pas subi la guerre et l’exode, ils sont beaucoup plus forts.$b$bLes mater demandera un véritable tour de force.$b$bLe Khan Shodo et ses trois fils règnent sur le clan. Shodo est âgé, et souffre d’anciennes blessures de guerre. Il ne quitte jamais les profondeurs de sa grotte. La puissance de son règne réside en ses fils.$b$bTuez-les, et persuadez le Khan de se rallier à notre cause.', '', 'Rhoho vaincu', 'Sherik vaincu', 'Jorreth vaincu', '', '', '', '', '', 'Parlez au khan Shodo au Trou de Bolgan, en Désolace.', 0),
(14329, 'frFR', 'Pas si vite !', 'Le khan Shodo veut que vous tuiez 10 Marteleurs maraudines dans la Vallée des Lances.$b$bVous devez fouiller leurs cadavres à la recherche d’indices sur le lieu où est retenue Kherrah.', '<Le khan du clan Gelkis vous observe de son regard vide alors que vous décrivez la menace démoniaque et les visions de Leh’prah.>$b$bL’avenir de cette terre m’importe peu à présent. J’ai fait défaut à mon clan et à mes ancêtres…$b$bIl ne reste qu’une chose en ce monde qui pourrait raviver la flamme de ma vieille âme, et elle est probablement morte, elle aussi.$b$bMa chère fille, Kherrah, m’a été enlevée par le clan des Maraudines. Si vous me la ramenez en vie, j’étudierai votre proposition.', '', 'Marteleurs maraudines tués', '', '', '', '', '', '', '', '', 0),
(14330, 'frFR', 'Derrière les portes closes', 'Vous devez retrouver Kherrah quelque part à l’intérieur de Maraudon.', 'Vous avez découvert où se trouve la fille du khan Shodo, Kherrah. Elle est retenue prisonnière à l’intérieur de Maraudon !$b$bTenter de la sauver risque d’être dangereux, mais si vous voulez obtenir l’aide du clan Gelkis, vous devez la libérer.', '', '', '', '', '', '', '', '', '', '', 0),
(14332, 'frFR', 'L\'heure du changement a sonné', 'Kherrah vous a demandé d’aller parler au khan Leh’prah.', '<Kherrah écoute votre récit des derniers événements.>$b$bJe suis d’accord avec le khan des Kolkar. Il est temps d’enterrer la hache de guerre. Il aura fallu une invasion démoniaque pour unir les tribus, et c’est bien dommage.$b$bJe vais retourner voir mon père pour le convaincre de se rallier à votre cause. Je vous promets qu’il acceptera.$b$bRetournez voir le khan Leh’prah et dites-lui que les Gelkis répondront présents à l’appel.', '', '', '', '', '', '', '', '', '', '', 0),
(14333, 'frFR', 'Pendant que vous êtes là', 'Vous devez fouiller la Vallée des lances à la recherche de 6 Reliques profanées.', 'Les Maraudines ont saccagé les camps des Gelkis pendant de nombreuses années, pillant tout ce qui leur tombait sous la main.$b$bIls appréciaient tout particulièrement de dérober les reliques de puissance, si chères aux Gelkis, pour les amener ici et les profaner.$b$bLe clan des Gelkis vous serait certainement reconnaissant si vous trouviez et détruisiez ces artéfacts profanés.', '', 'Reliques profanées détruites', '', '', '', '', '', '', '', '', 0),
(14334, 'frFR', 'Boule-de-gras', 'Mai\'Lahii vous a demandé de tuer Boule-de-gras.', 'Salut, mec !$b$bÇa vous dirait pas d’faire quelque chose pour notre village, là ?$b$bLes baleines, on sait y faire, mais y en a une spéciale là-bas qu’elle est trop grosse pour nos lances.$b$bBoule-de-gras y devient de plus en plus gros, à se goinfrer tout notre poisson !$b$bAllez là-bas et chopez-moi ce monstre, pis faut qu’y paie pour tout c’qu’il a mangé !', '', 'Boule-de-gras abattu', '', '', '', '', '', '', '', '', 0),
(14335, 'frFR', 'Leur fermer le claquet', 'Tuez 5 Rampants claquesec et 5 Pinceurs claquesec.', 'Comme vous l’avez sans doute remarqué, la région a récemment subi des bouleversements qui ont eu de nombreuses répercussions. Certaines sont bénéfiques, alors que d’autres posent de sérieux problèmes.$b$bAu sud du village, les homstroks émergent de la mer et bloquent l’accès au village. $b$bJe vous en prie, $c, éradiquez cette peste.', '', 'Pinceurs claquesec abattus', 'Rampants claquesec abattus', '', '', '', '', '', '', 'Parlez à Taiga Crin-de-sage au village de Proie-de-l\'Ombre.', 0),
(14336, 'frFR', 'Tuer ou être tué', 'Parlez au Prince Liam Grisetête à l\'extérieur de Havre-du-Soir.', 'Les récifs nous ont toujours protégés d\'une attaque maritime. Le tremblement de terre a dû ouvrir un passage qu\'auront emprunté les bateaux réprouvés.$B$BDépêchez-vous, $n. Ralentissez les attaquants pendant que je rassemble la milice.$B$BJe crois bien que j\'entends le prince et quelques-uns de nos hommes engager le combat contre les Réprouvés en ce moment même. Demandez à Liam si vous pouvez lui être d\'une aide quelconque.$B$BOh, et assurez-vous qu\'il ne se fasse pas tuer. J\'ai peur qu\'il soit un peu imprudent, dans son état.', '', '', '', '', '', '', '', '', '', '', 0),
(14337, 'frFR', 'Proie-de-l’Ombre', 'Karnum Tisse-marais vous a demandé d’aller parler à Mai’Lahii.', 'Rebonjour, $c.$b$bOn m’a dit que les habitants de Proie-de-l’Ombre avaient besoin d’aide. Nous sommes très occupés ici, c’est pourquoi je vous demande d’aller les aider.$b$bLe village se trouve sur la côte, au sud-ouest d’ici. Quand vous y serez, cherchez Mai’Lahii.', '', '', '', '', '', '', '', '', '', '', 0),
(14338, 'frFR', 'Le poste de Rôdeur-fantôme', 'Karnum Tisse-marais vous a demandé d’aller parler à Maurin Craquossement.', 'Salutations, $c.$b$bQuelle joie de voir que vous respirez encore. Le temps est venu pour moi de vous demander votre concours.$b$bAu sud-ouest de cette clairière se trouve le poste de Rôdeur-fantôme. Là-bas, vous trouverez un réprouvé du nom de Maurin Craquossement.$b$bIl aura peut-être une solution à l\'un des problèmes auxquels nous sommes confrontés.$b$bAllez lui parler et faites ce que vous pouvez pour l\'aider.', '', '', '', '', '', '', '', '', '', '', 0),
(14339, 'frFR', 'Voie d\'administration', 'Maurin Craquossement vous a demandé de trouver 3 Cornes creuses de kodos sur des Kodos mourants.', 'Il se trouve qu’il y a une certaine mission à accomplir… et que cela rendrait service au Cercle cénarien, en même temps qu’à moi-même.$b$bVous comprenez, $c, on me presse de créer une décoction… spéciale, dirons-nous. Je pense avoir terminé, mais je dois la tester pour en être sûr.$b$bLes cobayes seraient les nagas, qui menacent cette région par l’ouest. Leur disparition rendrait certainement service au Cercle.$b$bMais d’abord, j’ai besoin d’une voie d\'administration. Les cornes creuses de kodos mourants iront parfaitement.', '', '', '', '', '', '', '', '', '', '', 0),
(14340, 'frFR', 'La fripe pour la frime', 'Mettez votre nouveau Chapeau de sorcier, puis allez voir l’Image de l’archimage Xylem, juste au nord-est de la Station nord du fusorail.', 'Je crois que chacun doit tirer les leçons de ses erreurs.$B$BTenez, prenez mon chapeau de sorcier. Il vous prendra sûrement comme $gapprenti:apprentie; si vous avez la tête de l’emploi… Mais, vous devrez peut-être d’abord faire quelques petits tours. Par exemple sauter à travers de minuscules cerceaux enflammés, $gsuspendu:suspendue; au-dessus de pointes, avec des lames en mouvements de l’autre côté.$B$BVous devriez trouver une image de Xylem au sommet de la colline, au nord-est.', 'Allez voir l’Archimage Xylem en portant votre Chapeau de sorcier.', '', '', '', '', '', '', '', '', '', 0),
(14341, 'frFR', 'Les harnais de Smeed', 'Nataka, du Poste de Rôdeur-fantôme, veut que vous ameniez les Harnais de Smeed à Smeed.', 'Excusez-moi, jeune $r.$b$bJ’aurais besoin d’un peu d’aide. Je viens de terminer une commande de harnais qui doivent être livrés sur le champ.$b$bJe suis un peu âgé pour ce trajet, surtout depuis que les choses ont empiré.$b$bAuriez-vous la gentillesse de les livrer pour moi ?$b$bSmeed en est le destinataire, un gobelin qui vit juste au sud-est d’ici.', '', '', '', '', '', '', '', '', '', '', 0),
(14342, 'frFR', 'Intrusion infernale', 'Felgur Doublecoupe veut que vous détruisiez 10 Infernaux inférieurs.', 'Les démons sont en marche, $r !$b$bSi nous ne faisons rien, nous serons submergés en quelques semaines. Je reviens à peine du Convent de Mannoroc où les infernaux tombent du ciel !$b$bIl nous faut gagner du temps. Allez-y et finissez ce que j’ai commencé !', '', 'Infernaux inférieurs détruits', '', '', '', '', '', '', '', '', 0),
(14343, 'frFR', 'La décoction de Maurin', 'Maurin vous a demandé d’apporter la Décoction de Maurin à Karnum, au bosquet de Karnum.', '<Maurin ferme soigneusement les cornes creuses de kodo contenant sa décoction.>$b$bTenez, $c.$b$bApportez-les à Karnum. Il saura comment les utiliser sur les nagas.$b$bJe ne serai pas loin pour voir si ma formule est efficace !', '', '', '', '', '', '', '', '', '', '', 0),
(14344, 'frFR', 'Juguler Jugkar', 'Vous devez utiliser le Noyau de puissance infernal pour prendre le contrôle du seigneur Azrethoc, à l’autel de Jugkar, et utiliser ses pouvoirs pour tuer Jugkar Grim’rod.', 'Vous comprenez qu’il s’agit de l’essence d’un démon invoqué.$b$bDes énergies maléfiques et obscures s’animent à sa surface.$b$bEn l’observant de plus près, une vision emplit votre esprit : un rêve dans lequel vous contrôlez des serviteurs démoniaques. Une vague d’excitation vous envahit à l’idée de posséder un tel pouvoir.$b$bEn scrutant les alentours, vous vous demandez comment ce trésor pourrait être utilisé contre l’ennemi…', '', 'Jugkar Grim\'rod abattu', '', '', '', '', '', '', '', '', 0),
(14345, 'frFR', 'Les apprentis', 'Allez voir Sorata Filefeu à la Station nord du fusorail.', 'Délicieux !$B$BAzy cherche toujours à faire main basse sur des artéfacts magiques. Il a dit qu’il voulait devenir pote avec cet archimage, Xylem !$B$BXylem a BEAUCOUP d’apprentis. Il prend tous ceux qui se présentent, il les fait bosser comme des chiens, puis il les laisse errer un peu partout. Y a beaucoup de rotation.$B$BLe dernier a débarqué la nuit dernière. Il allait en direction de cette grosse tour gobeline en construction, plus à l’ouest. Peut-être qu’il pourra vous aider à rencontrer Xylem ? Peut-être que Xylem sait où se trouve Azy ?$B$BJouez-la finement !', '', '', '', '', '', '', '', '', '', '', 0),
(14346, 'frFR', 'Nettoyer notre crevasse', 'Karnum Tisse-marais veut que vous utilisiez la Décoction de Maurin pour tuer 10 Envahisseurs ondulames, 10 Sirènes ondulames, et 3 Géants des mers.', 'Comme vous devez le savoir, $n, la région est toujours sérieusement menacée par les nagas. Il est temps pour nous de les repousser vers la mer !$b$bLorsque vous serez $gprêt:prête;, Plume-sinistre vous conduira jusqu’à la crevasse où ils préparent un assaut massif. Une fois là-bas, utilisez la décoction de Maurin pour leur donner une leçon qu’ils ne seront pas prêts d’oublier.', '', 'Monter Plume-sinistre', 'Sirènes ondulames vaincues', 'Géants des mers vaincus', 'Envahisseurs ondulames tués', '', '', '', '', '', 0),
(14347, 'frFR', 'Empêchez-les d\'avancer', 'Tuez 10 Envahisseurs réprouvés.', '$n ! Je ne sais toujours pas si vous êtes $gvivant:vivante; ou $gmort:morte;... $ghumain:humaine; ou worgen...$B$BJe ne suis même pas sûr d\'être vraiment réveillé. Mais s\'il y a bien UNE chose dont je suis certain...$B$BC\'est que nous allons nous débarrasser d\'un grand nombre de ces maudits Réprouvés.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Prince Liam Grisetête à l’extérieur de Havre-du-Soir, en Gilnéas.', 0),
(14348, 'frFR', 'Impossible de s\'en charger seul', 'Utilisez les Barils de poudre à canon noire pour faire exploser 4 Abominations affreuses.', 'Regardez par ici, $n. Les gros trucs, qu\'on appelle abominations, ils ne se laissent pas faire, alors évitez de vous en occuper $gseul:seule;.$B$BMais j\'ai une idée tellement loufoque qu’elle pourrait fonctionner… ou vous tuer, si nous ne sommes pas prudents.$B$BIl y a des tonneaux de poudre à canon sous les cabanes et près des moulins. Prenez-les et jetez-les au visage de ces abominations. Je m\'occuperai du reste grâce à ce bon vieux tromblon.', '', 'Poudre à canon lancée sur une abomination', '', '', '', '', '', '', '', 'Retournez voir le prince Liam Grisetête à Havre-du-Soir, en Gilnéas.', 0),
(14354, 'frFR', 'Les cadeaux d\'Élune', 'Examinez les Reliques d’Élune à Sargeron.', 'C’est tout simplement intolérable !$b$bLes satyres, les pires créatures qui soient, profanent nos terres sacrées… $b$bLeurs jours sont comptés, $r. Faites-moi confiance. Dès que nous serons assez nombreux, je lancerai une attaque pour purifier cette terre de ces immondes créatures.$b$bEn attendant, peut-être pourriez-vous apaiser mes craintes ?$b$bAllez à l’est d’ici jusqu’à Sargeron et explorez les ruines. Trouvez les reliques d’Élune et assurez-vous qu’elles sont en bon état.$b$bVous recevrez une belle récompense.', '', 'Suivante d’Élune examinée', 'Brasero d’Élune examiné', 'Coupe d’Élune examinée', '', '', '', '', '', 'Retournez voir Vahlarriel Tueur-de-démons à la Combe de Nijel, en Désolace.', 0),
(14357, 'frFR', 'Les sabres mouvants', 'Récupérez 20 Sabres de satyre dans les râteliers d’armes et sur les satyres de la région.', 'La suivante d’Élune ! Elle est encore plus belle que vous ne l’imaginiez.$b$bVous approchez de la relique, et les légendes qui l’entourent vous viennent à l’esprit :$b$bJadis, après chaque bataille, les armes des ennemis étaient déposées dans le bassin en échange de quelque faveur divine.$b$bPendant que vous méditez sur ce rituel, une lueur métallique provenant d’un râtelier d’armes, non loin de là, attire votre attention…', 'Rituel de guerre d’Élune terminé', '', '', '', '', '', '', '', '', 'Placez les Sabres de satyre sur la statue de la Suivante d’Élune à Sargeron, en Désolace.', 0),
(14358, 'frFR', 'Dix livres de chair', 'Rassembler 10 lambeaux de Chair de satyre sur les satyres de Sargeron.', 'La légende raconte que ce brasero antique avait été placé ici pour accomplir des sacrifices.$b$bD’après le peu dont vous vous souvenez, une bénédiction est accordée à quiconque dépose la chair des ennemis d’Élune sur ses braises ardentes.$b$bEn scrutant les alentours, vous jetez votre dévolu sur les satyres ayant récemment investi la région.', '', 'Offrande sacrificielle acceptée', '', '', '', '', '', '', '', 'Placez la Chair de satyre sur le Brasero d’Élune à Sargeron, en Désolace.', 0),
(14359, 'frFR', 'Bénédiction divine', 'Vous devez rassembler 10 lambeaux de Chair de satyre provenant des satyres de Sargeron, et les déposer sur le Brasero d’Élune.', 'Vous communiez avec la relique, et sa bénédiction vous fait ressentir un lien profond avec le passé.$b$bVous êtes $gdécidé:décidée; à tirer le maximum de ce don du ciel.', '', 'Offrande sacrificielle acceptée', '', '', '', '', '', '', '', '', 0),
(14360, 'frFR', 'Choper le melon', 'Vous devez rassembler 8 Melons et presser leur jus dans la Coupe d’Élune, à Sargeron.', 'Les inscriptions sur les ruines révèlent un point important : la vieille fontaine du sanctuaire d’Élune renferme un secret.$b$bIl semblerait que se passer de son eau sur le visage confère un pouvoir extraordinaire. Mais pour cela, il faudrait d’abord que la fontaine contienne un peu d’eau.$b$bEn réfléchissant au problème, vous apercevez un melon au pied d’un arbre, tout près de vous…', '', 'Rituel de purification terminé', '', '', '', '', '', '', '', '', 0),
(14361, 'frFR', 'La paix de l’âme', 'Tuez Kohor.', 'Nous occupons un poste avancé, chargé de surveiller les ennemis potentiels. Quand l’Alliance lancera son attaque sur Désolace, notre travail nous permettra de ne pas nous laisser prendre par surprise.$b$bL’un de nos éclaireurs a récemment été capturé et sacrifié par la Lame-Ardente, dans leur bastion, à l’ouest. Depuis, une vermine de la Lame, du nom de Kohor, ne cesse de nous menacer et de nous provoquer.$b$bMême si leurs jours sont comptés, je donnerais cher pour le voir réduit au silence dès maintenant !', '', 'Kohor tué', '', '', '', '', '', '', '', 'Retournez voir le capitaine Pentigast à la Combe de Nijal, en Désolace.', 0),
(14362, 'frFR', 'Les oreilles qui chauffent', 'Obtenez 25 Oreilles de la Lame-Ardente.', 'Le capitaine Pentigast n’a fait aucun mystère de son mépris pour les sympathisants de la Lame-Ardente de la Forteresse de Hache-Tonnerre.$b$bIl apprécierait certainement une preuve de leur mort.', '', '', '', '', '', '', '', '', '', 'Retournez voir le capitaine Pentigast à la Combe de Nijal, en Désolace.', 0),
(14363, 'frFR', 'Vous le saurez quand vous le verrez', 'Trouvez l’Ancien rituel d’invocation dans la Forteresse de Hache-Tonnerre.', 'En rendant son dernier souffle, Kohor a fait allusion à l’invocation d’un démon qui pourrait menacer toute la région.$b$bIl mentait peut-être, mais on ne peut pas courir ce risque.$b$bNous ne pouvons pas nous permettre d’attendre que notre conquête de Désolace soit terminée. Vous devez ratisser la forteresse de Hache-Tonnerre pour trouver des indices et mettre un terme à cette menace potentielle.', '', '', '', '', '', '', '', '', '', 'Retournez voir le capitaine Pentigast à la Combe de Nijel, en Désolace.', 0),
(14364, 'frFR', 'Le casse-tête', 'Rassemblez 100 Crânes blanchis de la Forteresse de Hache-Tonnerre, déposez-les dans le Cercle d’invocation de la Larme ardente, puis tuez Nazargen.', 'C’est donc vrai…$b$bLe parchemin que vous avez découvert dans la forteresse de Hache-Tonnerre est la formule d’un puissant rituel d’invocation. Il est beaucoup plus puissant que tous ceux jamais possédés par la Lame-Ardente.$b$bIl faut à tout prix l’empêcher de se produire !$b$bSi le démon pouvait être invoqué avant que le rituel ne soit terminé, cela pourrait permettre d’éviter le pire.', '', 'Nazargen abattu', '', '', '', '', '', '', '', 'Parlez au Capitaine Pentigast à la Combe de Nijel.', 0),
(14365, 'frFR', 'Ethel Rethor', 'Le caporal Melkins vous a demandé d’aller parler à Korrah, à Ethel Rethor.', 'Une chercheuse du Cercle cénarien nous a récemment appelés à l’aide.$b$bJe ne peux me séparer de personne pour le moment, c’est pourquoi je vous demande d’aller la voir pour nous.$b$bKorrah est en poste près de la tour en ruine d’Ethel Rethor, sur la côte, à l’ouest.', '', '', '', '', '', '', '', '', '', '', 0),
(14366, 'frFR', 'Tenir bon', 'Parlez à Gwen Armstead à Havre-du-Soir.', 'Nous allons prendre la relève, $n. Allez voir le maire Armstead.$B$BCe n\'est qu\'une petite partie des troupes réprouvées. Si nous ne bougeons pas rapidement, nous allons bientôt nous retrouver avec un plus gros problème sur les bras.$B$BVoyez ce que vous pouvez faire pour engager le combat contre les Réprouvés sur le lieu de leur débarquement.', '', '', '', '', '', '', '', '', '', '', 0),
(14367, 'frFR', 'L\'abri des Allen', 'Parlez au Seigneur Godfrey dans l\'Abri de la Ferme des Allen, en Gilnéas.', 'Le seigneur Godfrey mène l\'attaque près du site de débarquement des Réprouvés. Voyez ce que vous pouvez faire pour nous aider à repousser l\'envahisseur.$B$BJ\'ai entendu dire que Godfrey a réquisitionné l\'abri de la ferme des Allen, loin à l\'ouest. Allez le voir là-bas.', '', '', '', '', '', '', '', '', '', '', 0),
(14368, 'frFR', 'Sauvez les enfants !', 'Sauvez Cynthia, Ashley et James à la Ferme des Hammond.', 'Les soldats ne veulent pas me laisser sortir de cette cave, mais mes enfants sont toujours à la ferme ! S\'il vous plaît, vous devez aller les chercher.$B$BLes Réprouvés ne font montre d\'aucune compassion pour les vies innocentes… Mes enfants courent un grave danger !$B$BIls s\'appellent Cynthia, Ashley et James. Si vous les trouvez, ramenez-les-moi. Je vous en serai à jamais reconnaissante.', '', 'Cynthia secourue', 'Ashley secourue', 'James secouru', '', '', '', '', '', 'Retournez voir Melinda Hammond dans l’abri de la Ferme des Allen, en Gilnéas.', 0),
(14369, 'frFR', 'Libérer la bête', 'Tuez 8 Fantassins ou Marins réprouvés.', 'Je ne vais pas vous mentir, $n. Je n\'aime pas beaucoup l\'idée d\'avoir des worgens dans nos rangs. Qui sait combien de temps la décoction de Krennan fera effet avant que vous ne tentiez de nous arracher la tête ?$B$BToutefois, en attendant, nous pouvons faire bon usage de votre férocité.$B$BJe veux que vous alliez sur le champ de bataille et que vous tuiez autant de Réprouvés que possible, et n\'hésitez surtout pas à être $gbrutal:brutale;.$B$BLes worgens leur inspireront bientôt la peur, $n.', '', 'Combattant réprouvé tué', '', '', '', '', '', '', '', 'Retournez voir le Seigneur Godfrey dans l’Abri de la ferme des Allen en Gilnéas.', 0),
(14370, 'frFR', 'La mystérieuse azsharite', 'Récupérez 5 Échantillons d’azsharite sur les falaises à proximité.', 'L’azsharite ! Cette mystérieuse substance cristalline a été utilisée pour forger des armes chargées de puissance gangrenée. Mais en faisant des recherches, nous avons découvert qu’elle pouvait concentrer d’énormes quantités d’énergie. C’est probablement la plus grande découverte gobeline depuis la kaja’mite.$B$BMais qu’est-ce que c’est ? D’où vient-elle ? Pourquoi n’en trouve-t-on qu’ici ? La science exige des réponses ! Il me faut plus d’échantillons à étudier. Cherchez des dépôts d’azsharite le long des falaises à proximité.', '', '', '', '', '', '', '', '', '', 'Apportez les échantillons à l’Assistante Greely au Terminus Sud du fusorail, en Azshara.', 0),
(14371, 'frFR', 'Un en-cas de géant', 'Récupérez 8 Carcasses brumailes mutilées sur les Hante-falaises brumailes.', 'Tant que vous êtes là, à parcourir les falaises, peut-être que vous pourriez m’aider à suivre une autre piste. Les géants qui arpentent ces falaises ont l’âge de ces montagnes. Peut-être qu’ils savent d’où vient l’azsharite ? C’est dans notre intérêt de sympathiser avec ces géants pour découvrir ce qu’il en est.$B$BPréparez-moi un repas gigantesque en guise d’offrande de paix ! Tuez les hante-falaises brumailes qui nuisent considérablement à nos études et rapportez-moi leurs carcasses.', '', '', '', '', '', '', '', '', '', 'Apportez les carcasses à l’Assistante Greely au Terminus Sud du fusorail, en Azshara.', 0),
(14372, 'frFR', 'Le camp de Thargad', 'Karnum Tisse-marais veut que vous alliez parler à Thargad.', 'Quel plaisir de vous voir toujours en vie, $c. On m’a dit que l’activité démoniaque s’était intensifiée au sud.$b$bLes habitants du camp situé à la frontière risquent d’être massacrés si les démons se déplacent vers le nord.$b$bVous pourriez peut-être les aider ?$b$bJe sais que le chef de ce camp se nomme Thargad. Il sera d’un sage conseil.$b$bMerci, l\'$gami:amie;. Portez-vous bien.', '', '', '', '', '', '', '', '', '', '', 0),
(14373, 'frFR', 'Intrusion infernale', 'Détruisez 10 Infernaux inférieurs.', 'Écoutez un peu. Venez voir par-là.$b$b<Thargad désigne l’est.>$b$bVous avez vu ces grosses boules vertes qu’elles tombent en feu du ciel là ?$b$bUn gros tas de vilains démons qu’ça doit être ça, qui arrêtent pas de rôdailler dans tout le pays. Enfin… Je leur ai donné de quoi s’occuper, moi, tiens, queq’ chose à quoi penser.$b$bQu’est-ce vous dites d’aller là-bas et de finir mon boulot, hein ?', '', 'Infernaux inférieurs détruits', '', '', '', '', '', '', '', 'Retournez voir Thargad dans son Camp, en Désolace.', 0),
(14374, 'frFR', 'Les portails de la Légion', 'Bannissez 6 Portails du Convent de Mannoroc.', 'Mirez-moi un peu ça, la Main d\'Iruxos !$b$bC’est moi que je l’ai piquée à un chef de la Lame-Ardente.$b$bElle a un pouvoir magique ! Voyez, faut l’utiliser sur les portails démoniaques et hop, y en a plus ! C’est d’la sorcellerie, mais les temps sont durs…$b$bSi les démons continuent de rappliquer comme ça, mon camp sera ratiboisé en moins de deux.$b$bAllez-y. Mettez-vous au boulot, et que ça saute !', '', 'Portails bannis', '', '', '', '', '', '', '', 'Retournez voir Thargad dans son Camp, en Désolace.', 0),
(14375, 'frFR', 'Dernier espoir d\'humanité', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14376, 'frFR', 'Juguler Jugkar', 'Vous devez utiliser le Noyau de puissance infernal pour prendre le contrôle du seigneur Azrethoc, à l’autel de Jugkar, et utiliser ses pouvoirs pour tuer Jugkar Grim’rod.', 'Vous comprenez qu’il s’agit de l’essence d’un démon invoqué.$b$bDes énergies maléfiques et obscures s’animent à sa surface.$b$bEn l’observant de plus près, une vision emplit votre esprit : un rêve dans lequel vous contrôlez des serviteurs démoniaques. Une vague d’excitation vous envahit à l’idée de posséder un tel pouvoir.$b$bEn scrutant les alentours, vous vous demandez comment ce trésor pourrait être utilisé contre l’ennemi…', '', 'Jugkar Grim\'rod abattu', '', '', '', '', '', '', '', '', 0),
(14377, 'frFR', 'C’est géant !', 'Allez voir Gormungan devant le Terminus sud du fusorail, et découvrez le secret de l’azsharite.', 'Une étude sommaire de l’azsharite que vous m’avez apportée révèle que ce minerai n’est pas d’origine biologique, et qu’il ne se forme pas de manière naturelle non plus. En Azshara, il existe d’autres créatures avec les mêmes caractéristiques : les géants qui arpentent lentement ces falaises.$B$BL’un des géants semble disposé à nous aider dans nos recherches. Apportez à Gormungan la viande que vous avez récupérée. C’est le géant qui se trouve juste à l’ouest d’ici. Amadouez-le, puis cuisinez-le… Découvrez s’il connaît le secret de l’azsharite !', '', 'Secret de l’azsharite découvert', '', '', '', '', '', '', '', 'Retournez voir l’Assistante Greely au Terminus sud du fusorail, en Azshara.', 0),
(14378, 'frFR', 'La chasse à Brendol', 'Récupérez la Sacoche de Brendol.', 'J’suis trop occupé à chercher des reliques pour m’occuper de quoi que ce soit d’autre, mais y a une affaire que j’aimerais bien régler.$b$bY a un apothicaire réprouvé qui traînaille dans l’coin depuis un moment. D’habitude, je l’aurais ignoré, mais là ça fait trois fois qu’il se faufile dans mon camp et carotte mes provisions… Y en a marre !$b$bTrouvez-moi ce voleur et rapportez-moi ce qu’il reste de mes affaires !', '', '', '', '', '', '', '', '', '', 'Retournez voir Thargad dans son Camp, en Désolace.', 0),
(14379, 'frFR', 'Homstrok au wok !', 'Obtenez 7 Queues de homstrok tendres.', 'Thargad est presque toujours à la recherche de reliques antiques des titans. Il est tellement occupé que, sans moi, il oublierait sûrement de manger !$b$bEn parlant de manger, j’aimerais lui faire quelque chose de spécial, vous pouvez m’aider ?$b$bY a des homstroks sur la côte à l’ouest. Je ne ferais pas un pli face à eux, mais si vous me ramenez quelques-unes de leurs queues, je pourrai préparer un bon repas !', '', '', '', '', '', '', '', '', '', 'Retournez voir Dumti au Camp de Thargad, en Désolace.', 0),
(14380, 'frFR', 'Une découverte cruciale', 'Apportez la Décoction mystérieuse à Karnum, à la clairière de Karnum.', '<Thargad farfouille dans la sacoche et en ressort un objet étrange.>$b$bEh ben, c’est cornu ça… une corne de kodo creuse avec une espèce de potion dedans.$b$b<Thargad renifle la potion.>$b$bPOUAH ! C’est pas un élixir de jouvence, pour sûr ! Ce machin sert qu’à une chose : estourbir !$b$bÇa vous dit pas d’l’apporter à Karnum pour voir ce qu’il peut en faire ?', '', '', '', '', '', '', '', '', '', '', 0),
(14381, 'frFR', 'Nettoyer notre crevasse', 'Utilisez la Décoction de Maurin pour tuer 10 Envahisseurs ondulames, 10 Sirènes ondulames, et 3 Géants des mers.', 'Cette potion infecte me dit quelque chose. Elle provoque une terrible maladie qui tue presque sur-le-champ, et de manière très violente. Bien que je répugne à utiliser de tels moyens, j’ai bien peur que nous n’ayons pas le choix.$b$bComme vous devez le savoir, la région est toujours sérieusement menacée par les nagas. Il est temps pour nous de les repousser vers la mer !$b$bLorsque vous serez $gprêt:prête;, Plume-sinistre vous conduira jusqu’à la crevasse où ils préparent un assaut massif.$b$bUtilisez la décoction sur les nagas et leurs alliés pour sécuriser Désolace !', '', 'Monter Plume-sinistre', 'Sirènes ondulames vaincues', 'Géants des mers vaincus', 'Envahisseurs ondulames tués', '', '', '', '', 'Retournez voir Karnum Tisse-marais dans la Clairière de Karnum, en Désolace.', 0),
(14382, 'frFR', 'Deux réprouvés sont dans un bateau...', 'Utilisez les Catapultes des Réprouvés pour aborder leurs bateaux et tuer les Capitaines Morris et Anson.', 'Les Réprouvés sont en train de nous botter les fesses avec leurs catapultes, $n. Et même si nous nous chargeons de ces machines, leurs deux bateaux armés de canons se tiennent prêts.$B$BJ\'ai un plan pour faire d\'une pierre deux coups. Et vous, vous jouerez le rôle de la pierre.$B$BDébarrassez-vous des machinistes qui manœuvrent les catapultes. Utilisez ensuite l\'un de ces engins pour aborder les vaisseaux réprouvés.$B$BSi vous ne visez pas trop mal, vous devriez atterrir sans trop de dégâts. Une fois à bord, descendez sous les ponts et occupez-vous des capitaines de chacun des bateaux. Bonne chance, $c.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Seigneur Godfrey dans l’abri de la Ferme des Allen, en Gilnéas.', 0),
(14383, 'frFR', 'Les affreux bricolos des confins Dévastés', 'Tuez Bingham Gadgetaressort aux Confins Dévastés, ainsi que 4 Gnomes lance-filet et 6 Gnomes zappeurs.', 'Crapules ! Infidèles ! Depuis que j’ai commencé mon travail, ici en Azshara, la famille Gadgetaressort n’a cessé de saboter mes études et d’entraver mes recherches. Et maintenant, une bande de pitoyables bricolos est venue lui prêter main-forte ! J’ai des affaires urgentes à régler : veillez à ce que ces gnomes ne soient plus une gêne.$B$BDirigez-vous vers les confins Dévastés sur la côte, au sud de mon laboratoire secret, et commencez à faire tomber quelques-unes de leurs têtes anormalement grosses.', '', '', '', '', '', 'La menace à moustaches.', 'Bingham Gadgetaressort', '', '', 'Retournez voir Hobart Martelutte au Terminus sud du fusorail, en Azshara.', 0),
(14384, 'frFR', 'Dérouté !', 'L’officier Jankie veut que vous utilisiez sa monture jusqu’à la Combe de Nijel et que vous alliez parler au Caporal Melkins.', 'Halte là !$b$bPar ordre de la combe de Nijel, je dois envoyer sur-le-champ tous les alliés valides au caporal Melkins.$b$bJe n’ai pas l’autorisation de divulguer d’autres informations.$b$bMais je peux vous proposer un moyen de transport. Vous pouvez utiliser ma monture. Elle vous conduira directement au bon endroit.$b$bRompez.', '', '', '', '', '', '', '', '', '', '', 0),
(14385, 'frFR', 'Azsharite : expérience n° 1', 'Récupérez un Laxatif format géant dans la tour gnome des Confins Dévastés. Essayez ensuite de le faire avaler au géant Gormungan.', 'Bon, je connais un moyen infaillible pour envoyer les géants aux toilettes, mais ça ne va pas vous plaire. Ce qu’il nous faut c’est un… puissant… laxatif. Oh hé ! Il se trouve que les gnomes en ont, incroyable, non ? Ce n’est certainement pas une coïncidence. Je me demande ce qu’ils essaient de purger, là-bas ?$B$BD’après mes informations, le laxatif a été livré à la tour de Gadgetaressort le long de la côte, au sud du laboratoire secret. Récupérez le laxatif et faites-le avaler à Gormungan !', '', 'Tentative pour nourrir Gormungan', '', '', '', '', '', '', '', 'Allez faire part de vos découvertes à l’Assistante Greely au Terminus Sud du fusorail, en Azshara.', 0),
(14386, 'frFR', 'Le chef de la meute', 'Aidez-vous du Sifflet de mastiff pour tuer le forestier sombre Thyala.', 'Vous avez fait de l\'excellent travail jusqu\'ici, $n. Nos éclaireurs ont identifié le chef de l\'assaut terrestre des Réprouvés.$B$BL\'un des forestiers-sombres désignés par Sylvanas surveille le front depuis la demeure des Walden, près du rivage. Prenez ce sifflet et utilisez-le lorsque vous serez suffisamment proche du forestier-sombre.$B$BJe vais ordonner à mes hommes de lâcher leurs mastiffs d\'attaque sur elle. Soyez $gprudent:prudente;, $n. Vous n\'aimeriez pas vous retrouver $gseul:seule; avec elle.', '', '', '', '', '', 'N’oubliez pas d’utiliser le sifflet !', 'Forestier-sombre Thyala', '', '', 'Retournez voir le Seigneur Godfrey dans le sous-sol de la Ferme des Allen, en Gilnéas.', 0),
(14387, 'frFR', 'Tâter le terrain', 'Le capitaine Pentigast vous a demandé d’aller parler à Vahlarriel, à la combe de Nijel.', 'Oui, oui. Bienvenue en Désolace, $r.$b$bDésolé d’avoir été si insistant, mais c’est un petit avant-poste et il y a beaucoup de problèmes dans cette région, la plupart étant très urgents.$b$bRésultat : il nous faut toute l’aide possible.$b$bPour commencer, notre ami Vahlarriel, que vous voyez là-bas, commence à s’impatienter. Il s’obstine à vouloir envoyer un contingent pour explorer les ruines à l’est.$b$bAllez donc vous présenter à lui…', '', '', '', '', '', '', '', '', '', '', 0),
(14388, 'frFR', 'Azsharite : expérience n° 2', 'Allez voir l’Assistante Greely pour qu’elle vous donne la taille d’un rat. Enfourchez un Rat du fusorail et utilisez-le pour terrifier le géant Gormungan.', 'Bon, nouveau plan. On va leur filer une telle trouille qu’ils vont se faire dessus ! D’après mon expérience, la plupart des grosses créatures sont terrifiées par les petits animaux, comme les rats. Mhh. Cet endroit grouille de rats, mais comment les amener près du géant ?$B$BHé, dites-moi ! Ça ne vous ennuie pas si je détruis votre matrice cellulaire pour la réassembler ensuite ? Ça ne fait mal que sur le moment. Je peux vous donner la taille d’un rat et vous pourrez enfourcher l’une de ces brutes là-bas, comme si c’était un cheval. C’est une idée de génie, il faut que ça marche ! Prévenez-moi quand vous serez $gprêt:prête; pour la miniaturisation…', '', 'Gormungan effrayé', '', '', '', '', '', '', '', 'Allez faire part de vos découvertes à l’Assistante Greely au Terminus Sud du fusorail.', 0),
(14389, 'frFR', 'C\'était évident !', 'Utilisez le portail derrière Joanna à la Tour de Xylem pour trouver Anara la Gardienne des âmes et, avec un peu de chance, Azuregos.', 'Azuregos ! Oui, bien sûr. Un vieux dragon perturbé, mais un cœur grand comme ça. Je ne pense pas que toutes ces années passées à se faire attaquer par des vagabonds lui aient été bénéfiques. Il est un peu bizarre en ce moment.$B$BIl n’y a pas si longtemps, alors que je retournais encore une fois voir Anara, la gardienne des âmes du coin, je n’ai pas pu m’empêcher de remarquer qu’Azuregos et elle semblaient bien s’entendre. Je suppose qu’il doit encore lui tenir compagnie.$B$BLe portail qui se trouve derrière moi est probablement le moyen le plus rapide de la rejoindre. Ça risque de piquer un peu.', 'Trouver Anara et, avec un peu de chance, Azuregos.', '', '', '', '', '', '', '', '', '', 0),
(14390, 'frFR', 'Pourquoi faire simple quand on peut faire compliqué ?', 'Persuadez Azuregos de regagner le monde des vivants et de rencontrer Kalecgos.', 'Après de longues heures de recherches, aux méthodes parfois discutables, vous avez fini par trouver Azuregos.$B$BMaintenant, il suffit simplement de le convaincre d’aller voir Kalecgos, et de mettre un terme à la menace du vol noir en Azshara.', 'Persuader Azuregos de rencontrer Kalecgos.', '', '', '', '', '', '', '', '', '', 0),
(14391, 'frFR', 'Retournement de situation', 'Allez voir Anara pour revenir dans le monde des vivants, puis retrouvez Kalecgos au Terminus nord du fusorail.', 'Azuregos et Kalecgos doivent se rencontrer au terminus nord du fusorail. Vous devriez les y retrouver pour vous assurer que Kalecgos n’a pas à nouveau besoin d’aide.$B$BSi vous souhaitez ne plus être $gmort:morte;, Anara pourra probablement vous aider.', '', '', '', '', '', '', '', '', '', '', 0),
(14392, 'frFR', 'Ce n’est qu’un au revoir', 'Allez voir Sorata Filefeu au Havre Baille-Fonds.', 'Merci, petit être.$B$BIl est parfois facile de se laisser aveugler par l’amour et de perdre de vue les choses importantes, même pour un dragon. Dorénavant, mon unique but sera de m’assurer que Kalec ne parvienne jamais à prendre la place de Malygos. C’est la cause la plus noble à laquelle je puisse penser.$B$BVous devriez retourner au port. Je crois que vous y êtes $gattendu:attendue;.$B$BÉvitez de vous faire écraser ou dévorer en chemin.', '', '', '', '', '', '', '', '', '', '', 0),
(14393, 'frFR', 'Au cœur de la bataille !', 'Le khan Leh’prah vous a demandé de tuer 15 Démonistes de la Lame-Ardente, 3 Envahisseurs de la Garde funeste, et la Prêtresse Than’darissa.$b$bAllez parler au khan Leh’prah pour vous rendre sur le champ de bataille.', 'Pendant d’innombrables générations, les clans des centaures se sont entretués, mais c’est terminé à présent.$b$bGrâce à vous, nous combattons désormais ensemble un ennemi commun. Nous allons reprendre nos terres ancestrales à ces démons, ou bien nous mourrons en frères !$b$bEt vous, $n ?$b$bVous êtes digne de combattre à nos côtés. Un groupe de mes meilleurs centaures est à votre disposition. Conduisez-les au combat.$b$bRelèverez-vous le défi ?', '', 'Démonistes de la Lame-Ardente abattus', 'Envahisseurs de la Garde funeste abattus', 'Prêtresse Than’darissa abattue', '', '', '', '', '', '', 0),
(14394, 'frFR', 'L\'agonie d\'Agogridon', 'Vaincre Agogridon.', 'Objectif en vue, $n !$b$bNous pouvons désorganiser l’armée démoniaque en tuant son chef. Si nous réussissons, Désolace nous reviendra !$b$bQuand vous serez $gprêt:prête;, emmenez un groupe de centaures dans le ravin de Brèche-de-l’Ombre, par le passage au sud. Trouvez le repaire d’Agogridon !$b$bJe vais rassembler les autres khans puis je vous rejoindrai pour l’affrontement.', '', 'Agogridon vaincu', '', '', '', '', '', '', '', 'Parlez au Khan Leh\'Prah.', 0),
(14395, 'frFR', 'Besoin d\'air', 'Portez secours à 4 Veilleurs qui se noient.', '$n ! J\'étais en route lorsque cela s\'est produit.$B$BIl n\'y a pas un instant à perdre. Une bonne moitié des veilleurs de la ville étaient dans les environs lorsque la terre s\'est effondrée. Sauvez autant d\'hommes que possible.$B$BSortez-les de l\'eau et ramenez-les jusqu\'au rivage. Je m\'assurerai qu\'on leur apporte toute l\'aide nécessaire.', '', 'Veilleur qui se noie secouru', '', '', '', '', '', '', '', 'Retournez voir le prince Liam Grisetête à la Ferme des Allen, en Gilnéas.', 0),
(14396, 'frFR', 'Pendant que la terre se fracture', 'Parlez au Prince Liam Grisetête à la Ferme des Allen.', 'Qu\'est-ce que ça pouvait bien être, $n?$B$BNi des canons, ni des catapultes, ça j\'en suis certain.$B$BSortez et voyez ce qu\'il se passe.', '', '', '', '', '', '', '', '', '', '', 0),
(14397, 'frFR', 'L\'évacuation', 'Parlez à Gwen Armstead à Havre-du-Soir.', 'Nous avons survécu par pure chance, $n. Mais notre bonne étoile nous abandonne.$B$BLa côte est submergée alors même que nous discutons. Et d\'après ce que je peux voir, la terre sous nos pieds ne s\'est pas encore stabilisée.$B$BJ\'ai horreur d\'avoir à le dire, mais nous devons partir. Malédiction, $n... Je ne peux tout de même pas perdre ma terre natale une seconde fois en une seule vie. Mais ces séismes sont des ennemis que nous ne pouvons combattre.$B$BDites à Gwen Armstead de commencer l\'évacuation.', '', '', '', '', '', '', '', '', '', '', 0),
(14398, 'frFR', 'Grand-maman Wahl', 'Trouvez Grand-maman Wahl au Cottage des Wahl.', 'Nous allons avoir du mal à convaincre grand-maman Wahl de nous suivre. Faites tout votre possible malgré tout.$B$BVous la trouverez au cottage des Wahl. S’il vous plaît, $n, soyez $gpatient:patiente; avec elle. Elle est vieille et n’a plus toute sa tête.', '', '', '', '', '', '', '', '', '', '', 0),
(14399, 'frFR', 'Grand-maman a complètement perdu l\'esprit', 'Trouvez le Livre enroulé dans un linge.', 'Partir ? Maintenant ?$B$BEh bien s\'il le faut, je partirai. Mais seriez-vous assez $ggentil:gentille; pour chercher quelque chose pour moi ?$B$BJ\'ai perdu mon livre préféré et je ne partirai pas sans lui.$B$B<Après que vous lui ayez expliqué la gravité de la situation, grand-maman secoue la tête avec condescendance.>$B$BMon ange, trouvez mon livre, voulez-vous ?', '', '', '', '', '', '', '', '', '', 'Retournez voir Grand-maman Wahl au Cottage des Wahl, en Gilnéas.', 0),
(14400, 'frFR', 'Je ne peux pas porter ça', 'Récupérez les Vêtements de bonne qualité de grand-maman.', 'Que vouliez-vous, déjà ?$B$BAh, c\'est vrai. L\'ordre d\'évacuer.$B$BEh bien, je ne peux tout de même pas me présenter ainsi vêtue, pas vrai ?$B$BAllez me chercher mes vêtements de bonne qualité. Ils sont en train de sécher sur la corde à l\'extérieur.$B$B<Vous vous efforcez de convaincre grand-maman Wahl que ce qu\'elle porte fait parfaitement l\'affaire.>$B$BVous autres, les jeunes, manquez décidément de tenue. Avez-vous été $gélevé:élevée; par des ogres ? Maintenant, allez me chercher mes vêtements, mon chou.', '', '', '', '', '', '', '', '', '', 'Retournez voir Grand-maman Wahl au Cottage des Wahl, en Gilnéas.', 0),
(14401, 'frFR', 'Le chat de grand-maman', 'Retrouvez Chance le chat.', 'Bien ! Revenons à cette évacuation, mon chou.$B$BJe ne peux pas partir sans mon chat. C\'est un adorable chat tigré roux.$B$BChance a établi son terrain de chasse préféré sur un chariot cassé, près d\'une tonnelle au nord-est.$B$BRapportez-le moi et nous pourrons partir.', '', '', '', '', '', '', '', '', '', 'Retournez voir Grand-maman Wahl au Cottage des Wahl, en Gilnéas.', 0),
(14402, 'frFR', 'Prête à partir', 'Parlez à Gwen Armstead à Havre-du-Soir.', 'Je suppose que partir maintenant vaut bien un autre moment.$B$BJ\'ai ma plus belle tenue, mon livre préféré et mon chat adoré.$B$BJ\'espère que je n\'oublie rien.$B$BDites à votre maire que je me mets en route. Je suppose que je vous verrai en ville avec les autres !', '', '', '', '', '', '', '', '', '', '', 0),
(14403, 'frFR', 'Les frères Hayward', 'Parlez à Sebastian Hayward aux Pêcheries Hayward.', 'Les pêcheries Hayward se trouvent loin au sud. Les frères Hayward sont à leur tête depuis des années.$B$BIls viennent rarement en ville, excepté pour vendre leur poisson. Allez leur annoncer que l\'évacuation est en cours.', '', '', '', '', '', '', '', '', '', '', 0),
(14404, 'frFR', 'Pas très bon état général', 'Trouvez des Planches de bois, du Goudron de charbon et des Outils de charpentier naval.', 'Évacuation, vous dites ? Eh bien, nous avons eu exactement la même idée de notre côté, lorsque les Réprouvés se sont montrés.$B$BNous avons pensé que la mer serait le moyen le plus sûr de nous enfuir.$B$BMalheureusement, nos bateaux ont subi des dégâts pendant le dernier tremblement de terre.$B$BIl me manque certaines fournitures pour finir les réparations : du bois, du goudron et mes outils. Apportez-les moi pour que mes frères et moi puissions sortir d\'ici.', '', '', '', '', '', '', '', '', '', 'Retournez voir Sebastian Hayward aux Pêcheries Hayward, en Gilnéas.', 0),
(14405, 'frFR', 'L\'évasion par la mer', 'Parlez à Gwen Armstead à Havre-du-Soir.', 'Merci pour votre aide, $n. Ce bateau est prêt à prendre le large.$B$BAllez prévenir mademoiselle Armstead que nous ne participerons pas à l\'évacuation terrestre.$B$BNous autres, Hayward, sommes des marins depuis plusieurs générations. Si nous devons quitter notre foyer, ce sera par la mer.', '', '', '', '', '', '', '', '', '', '', 0),
(14406, 'frFR', 'Le verger de Crowley', 'Parlez à Lorna Crowley au Verger de Crowley.', 'Vous vous souvenez de Lorna, la fille du seigneur Darius Crowley, je suppose ?$B$BElle ne s\'est pas vraiment remise de la mort de son père à Gilnéas. Depuis, elle vit en ermite. Le seul visiteur qu\'elle a accepté de recevoir, c\'est Krennan... Et il ne dira rien de tout ça.$B$BAllez lui apprendre que nous évacuons la ville.', '', '', '', '', '', '', '', '', '', '', 0),
(14407, 'frFR', 'Le blues d’Azshara', 'Retrouvez Kalec au Havre Baille-Fonds.', 'Hé ! Je suis bien contente de vous trouver.$B$BJe viens de la part de mon maître, Kalec. Il a besoin de votre aide. Retrouvez-le le plus tôt possible sous le pont, dans les bas-fonds.', '', '', '', '', '', '', '', '', '', '', 0),
(14408, 'frFR', 'Le plan de n° 9', 'Récupérez les Plans secrets de la fusée dans le bâtiment des Archives du laboratoire, à l’extrémité est du Laboratoire secret. Sonnez à la porte et tuez le Directeur du laboratoire à son arrivée.', 'Mes bienfaiteurs se sont servi de leur intelligence limitée pour construire un moyen de transport interplanétaire. En l’état, cette soi-disant « fusée » est un engin mortel. Mais je pense qu’un petit réajustement du catalyseur de carburant pliable rendrait le mélange plus stable, sous réserve d’un sous-produit d’oxygène respirable. Pour procéder à de tels changements, il me faut les plans d’ingénieur d’origine.$B$BLocalisez le bâtiment des archives du laboratoire et tentez d’y pénétrer. Les plans doivent être en la possession du directeur du laboratoire, s\'il est encore en vie.', '', 'Sonner à la porte', '', '', '', '', '', '', '', 'Rapportez les Plans secrets de la fusée au Sujet N°9 au Laboratoire secret, en Azshara.', 0),
(14410, 'frFR', 'Les étendues sauvages de Féralas', 'Allez en Féralas et parlez à Telaron Volevent, au Repos du Rêveur.', 'Vous faites vraiment acte de bravoure en nous aidant à protéger ces terres, $ghéros:héroïne;. Si vous souhaitez servir cette contrée, d’autres personnes peuvent avoir besoin de votre aide.$b$bLes forêts verdoyantes de Féralas étendent leurs frondaisons au sud. C’est là, dans l’ombre des Colosses jumeaux, que vous devrez trouver Telaron Volevent. Au repos du Rêveur, lui et ses confrères, les druides de la serre, ont trouvé les signes d’une inquiétante maladie.$b$bIls apprécieront votre aide, $c. Allez en paix.', '', '', '', '', '', '', '', '', '', '', 0),
(14411, 'frFR', 'Suite Féralas', '', 'Un jour, je serai une vraie suite de quêtes !!!!', '', '', '', '', '', '', '', '', '', '', 0),
(14412, 'frFR', 'Des Réprouvés à la mer', 'Tuez 6 Naufragés réprouvés.', 'Les bateaux de ces Réprouvés ont coulé bien trop près de nos pêcheries. Tous les survivants viennent jusqu\'ici, et comme vous pouvez le voir, nous nous faisons submerger.$B$BAidez-nous à les tenir en respect pendant que je finis de réparer nos bateaux.', '', '', '', '', '', '', '', '', '', 'Retournez voir Sebastian Hayward aux Pêcheries Hayward, en Gilnéas.', 0),
(14413, 'frFR', 'La cime de la connaissance', 'Allez voir l’Image de l’Archimage Xylem au pied de la Cime des Arcanes.', 'C’est tellement exaltant ! Qu’est-ce qu’il y a de si palpitant, me direz-vous ? Mais, ÇA bien sûr !$B$BC’est l’heure des tests… le moment pour VOUS de passer des tests. Tant de défis à relever, tant de connaissances à assimiler. Les tests vous apprennent des choses. Et j’en apprends sur vous.$B$BAlors maintenant, filez. Montez jusqu’à la cime des arcanes. Je vous y attendrai, évidemment, car je suis un peu omniprésent.', '', '', '', '', '', '', '', '', '', '', 0),
(14416, 'frFR', 'L\'ettin affamé', 'Apportez 5 Chevaux des montagnes à Lorna Crowley au Verger de Crowley.', 'Écoutez, $n. Nous n’irons pas loin sans moyen de transport, pas vrai ?$b$bSi nous nous carapatons d’ici, les Réprouvés nous rattraperont en moins de temps qu’il n’en faut pour le dire.$b$bNormalement, se procurer de chevaux aux étables au sud-est serait facile, mais il y a un hic.$b$bCe dernier tremblement de terre doit avoir effrayé Koroth, l’ettin, et il doit être descendu des montagnes. Si nous ne mettons pas bientôt la main sur ces chevaux, je crains que lui le fasse.', '', 'Chevaux des montagnes secourus', '', '', '', '', '', '', '', 'Retournez voir Lorna Crowley au Verger de Crowley.', 0),
(14422, 'frFR', 'Ouvrez, ouvrez la cage aux raptors', 'Libérez 5 Raptors expérimentaux de leurs cages dans le Laboratoire secret, puis amenez-les jusqu’à la fusée, à côté du Sujet n°9.', 'Peu de temps après l’augmentation de mon intelligence, je me suis accouplée avec le sujet n°4 pour créer une race unique de raptors supérieurs au niveau cognitif. Par la suite, le sujet n°4 ne m’a pas rappelée, ni même écrit. J’ai donc décidé de l’étriper la prochaine fois que je le croiserai.$B$BMais il y a suffisamment de jeunes raptors emprisonnés dans ce laboratoire pour constituer une banque génétique capable de repeupler ma race. Libérez-les de leurs cages et transportez-les jusqu’à la fusée.', '', 'Raptors expérimentaux libérés', '', '', '', '', '', '', '', 'Allez voir le Sujet n°9 au Laboratoire secret, en Azshara.', 0),
(14423, 'frFR', 'La gêne de Margène', 'Utilisez le Lance-fusée béni près du Buldo de Clubnik pour demander de l’aide, puis « Exorcisez » le bulldozer.', '… c’est un prêtre qu’il nous faut !$B$BHeureusement, j’ai mis un peu d’argent de côté pour la bénédiction des machines. Prenez ce lance-fusée et dirigez-vous vers Margène, mon pauvre bulldozer adoré qui est en panne. Tirez une fusée de signal, et l’un de nos meilleurs prêtres volants devrait se parachuter pour régler la situation. Revenez me voir quand mon bulldozer sera réparé !', '', 'Buldo de Clubnik exorcisé', '', '', '', '', '', '', '', 'Retournez voir Custer Clubnik à la Station d’Orgrimmar du fusorail, en Azshara.', 0),
(14424, 'frFR', 'Science, on tourne !', 'Trouvez l’Assistante Greely au Terminus sud du fusorail. On peut utiliser le fusorail gobelin pour se déplacer plus vite en Azshara.', '<Clubnik sèche une larme, puis affiche une moue déterminée.>$B$BPlus jamais, $n ! Aucun bulldozer ne mérite de subir le même sort que ma Margène. Il va nous falloir du matériel qui résiste aux fantômes. C’est un boulot pour des savants de haut niveau, et il se trouve que j’ai exactement la scientifique qu’il nous faut ! Allez chercher l’assistante Greely au terminus sud du fusorail. C’est elle qui gère le célèbre laboratoire secret d’Azshara, et elle me doit une faveur.', '', '', '', '', '', '', '', '', '', 'Trouvez l’Assistante Greely au Terminus sud du fusorail. On peut utiliser le fusorail gobelin pour se déplacer plus vite en Azshara.', 0),
(14425, 'frFR', 'La première quête', 'Le Thrall de test veut que vous tuiez un truc.', 'Bonjour $n, ceci est un test. Acceptez-la et tuez des trucs.', '', 'Sales kobolds supprimés', '', '', '', '', '', '', '', '', 0),
(14427, 'frFR', 'Quête d\'objets', 'Récupérez les objets.', 'Quête de collecte d\'objets.', '', '', '', '', '', '', '', '', '', '', 0),
(14428, 'frFR', 'Le journal d’Ambrevent', 'Tuez la Gardienne du savoir Ambrevent au Camp de base Darnassien et récupérez son journal.', 'Si mes sources sont fiables, la gardienne du savoir Ambrevent supervise les recherches de l’Alliance dans les ruines, à l’est. Je ne connais pas encore l’étendue de ses compétences. Je me disais que vous pourriez me faire un rapport complet en la provoquant en duel et en la tuant.$B$BAvec un titre de « gardienne », je suppose qu’elle aura un journal sur elle qui nous expliquera en détail ce que mijotent ces elfes de la nuit. Rapportez-moi ce journal. Inutile de vous presser pour revenir, utilisez leurs propres pierres de vision pour me contacter à distance.', '', '', '', '', '', 'Espérons qu\'elle a les informations que nous cherchons.', 'Gardienne du savoir Ambrevent', '', '', 'Utilisez la Pierre de vision supérieure dans le Camp de base Darnassien pour obtenir d’autres instructions.', 0),
(14429, 'frFR', 'Désassemblage arcanique', 'Tuez des Apprentis enquêteurs et des Apprentis illuminateurs pour récupérer 10 Pierres runiques en phase.', 'Les assemblages arcaniques sont des créatures constituées de pur mana et d’intelligence. Entre de bonnes mains, un assemblage permet à son utilisateur d’assimiler rapidement une énorme quantité de connaissances arcaniques. Mais ils sont dangereux, $n. Si intelligents ! Si puissants ! Si sensibles à l’environnement extérieur…$B$BIl faut donner une bonne leçon à ces amateurs et retourner leur propre magie contre eux. Tuez des apprentis et rapportez-moi leurs pierres runiques. Quand vous aurez terminé, utilisez la pierre de vision inférieure pour me contacter.', '', '', '', '', '', '', '', '', '', 'Utilisez la Pierre de vision inférieure au Camp de base Darnassien pour obtenir d’autres instructions.', 0),
(14430, 'frFR', 'Pirater l\'assemblage', 'Allez voir l\'Assemblage arcanique au Camp de base Darnassien, et prononcez les mots chargés de puissance arcanique.', 'Maintenant, nous allons pirater leur assemblage arcanique et l\'utiliser pour semer le chaos. Avez-vous déjà pratiqué ce genre de magie, $n ? Non ? Ah ! Mon plan n\'en sera que plus savoureux. Pas très loin d\'ici, vous devriez voir un superbe assemblage arcanique qu\'ils ont invoqué. Grâce aux pierres runiques que vous avez collectées, nous pouvons communiquer avec lui. Parlez à l\'assemblage et dites-lui « Al\'teth la c\'tolgar ». Vous avez compris ? Vous pouvez le répéter ? Ça ira. Revenez me voir pour me raconter comment ça s\'est passé.', 'Assemblage arcanique piraté', '', '', '', '', '', '', '', '', 'Allez faire votre rapport à Andorel Ligesol à la Station Nord du fusorail, en Azshara.', 0),
(14431, 'frFR', 'Coup de noiregueule', 'Tuez 8 Biologistes de Talrendis, et récupérez les Informations noiregueules sur l’un des corps.', 'Les furbolgs noiregueules de la région se sont séparés de leurs frères grumegueules quand nous nous sommes installés de façon brutale en Azshara. Ils sont devenus fous, $c, et ils attaquent nos troupes à chaque détour. Pire encore, nous les avons surpris à discuter de façon amicale avec les elfes de la nuit de Talrendis. Il faut empêcher leur alliance à tout prix !$B$BAu sud-ouest d’ici, vous trouverez une balafre qui défigure le sol et où mes éclaireurs m’ont signalé une activité elfe de la nuit. Tuez les elfes qui s’y trouvent et rapportez-moi toute information utile.', '', '', '', '', '', '', '', '', '', 'Apportez les informations à Haggrum Poing-de-sang à la Station nord du fusorail, en Azshara.', 0),
(14432, 'frFR', 'L’heure du thé', 'Récupérez 10 échantillons de Tisane de racine de bruyère au Repaire des Noiregueules.', 'On dirait bien que les pourparlers de nos ennemis de l’Alliance avec les Noiregueules progressent, car ils négocient en utilisant la langue des furbolgs. Si on veut saboter le traité, il va falloir faire la même chose. $B$BCe n’est pas si difficile que ça en a l’air, $n. Les Noiregueules ont l’habitude de préparer une puissante tisane dont les vapeurs vous mettront dans un état de transe qui vous rendra capable de parler plusieurs langues. Celle des Noiregueules, pour être précis. Allez dans leur repaire au sud-ouest, et rapportez-moi quelques échantillons de cette tisane de racine de bruyère !', '', '', '', '', '', '', '', '', '', 'Retournez voir Haggrum Poing-de-sang à la Station nord du fusorail, en Azshara.', 0),
(14433, 'frFR', 'Diplomatie à tout prix !', 'Récupérez le Programme de la rencontre avec les Noiregueules au Repaire des Noiregueules, puis tuez une Ambassadrice de Talrendis pour lui prendre sa Robe d’ambassadrice.', 'Pour pouvoir perturber les négociations noiregueules, nous devons découvrir où elles ont lieu. Le repaire des Noiregueules, au sud-ouest, doit grouiller d’ambassadrices elfes de la nuit en pleins préparatifs.$B$B<Haggrum crache au sol.> $B$BTuez-en à loisir, et fouillez l’endroit à la recherche de documents de valeur. Ah, et récupérez une robe d’ambassadrice, on va en avoir besoin.', '', '', '', '', '', '', '', '', '', 'Apportez la robe et le programme à Haggrum Poing-de-sang à la Station nord du fusorail, en Azshara.', 0),
(14434, 'frFR', 'Rut’theran', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14435, 'frFR', 'La trahison des Noiregueules', 'Portez le Déguisement d’ambassadrice et allez voir Andorel Ligesol pour qu’il vous téléporte au Repaire des Noiregueules. Allez voir Ungarl pour faire échouer les négociations, puis tuez 4 Guerriers noiregueules et 4 Chamans noiregueules sur le chemin du retour.', 'Andorel, ici présent, a préparé un petit tour de magie. Approchez, tenez-vous près de mon feu, et imprégnez-vous des vapeurs du thé. Enfilez la robe et vous prendrez l’apparence d’une ambassadrice elfe de la nuit aux yeux des Noiregueules.$B$BEndossez votre déguisement et allez parler à Andorel, ici, dans le camp. Il vous téléportera au cœur du repaire des Noiregueules, lieu de leurs négociations. Allez voir le chef Ungarl et sabotez le traité. Tuez autant de Noiregueules que possible sur le chemin du retour !', '', 'Négociations sabotées', '', '', '', 'Vous pensez que votre intelligence dépasse celle d’un furbolg ?', 'Ungarl', '', '', 'Retournez voir Haggrum Poing-de-sang à la Station nord du fusorail, en Azshara.', 0),
(14442, 'frFR', 'Mon sujet favori', 'Trouvez le Sujet n°9 près du complexe du Laboratoire secret, en Azshara.', 'J’ignore si vous l’avez remarqué, $n, mais ce laboratoire est un vrai chantier ! Je me fiche d’avoir perdu tous ces hippogriffes, mais mon sujet d’expérience le plus cher a disparu : le sujet n°9 !$B$BC’est un raptor femelle que nous avons importé des Tarides. Je me demande si elle est toujours en vie… Allez jeter un coup d’œil au-dessus du complexe principal, à l’ouest d’ici, près de la fusée géante top secrète. Vous ne pourrez pas la manquer.', '', '', '', '', '', '', '', '', '', 'Trouvez le Sujet n°9 près du complexe du Laboratoire secret, en Azshara.', 0),
(14445, 'frFR', 'Adieu, pour l\'instant', 'Parlez à Chipie Serrelavis au Surplomb Sauvage, sur les Îles Perdues.', 'Nos destinées sont à jamais liées. Des évènements se produisent, qui changent la face du monde et qui finiront par le détruire. Nous devons y mettre un terme avant qu\'il ne soit trop tard.$B$BSachez que vous pourrez toujours compter sur moi, $gmon frère:ma sœur; ! Nous nous retrouverons sur la plus grande île. J\'espère que d\'ici là vous trouverez la paix, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(14447, 'frFR', 'Les ennemis de mes ennemis…', 'Le Saccageur-des-cieux Korm Noire-balafre vous demande de parler à Koltira Tissemort, à bord du Marteau d\'Orgrim.', 'Même s\'il ne faut jamais perdre une occasion de frapper l\'Alliance, nous ne devons pas oublier le Fléau.$b$bIci, nous ne serons pas assez nombreux pour préparer une attaque en règle du glacier avant des semaines. Mais cela ne doit pas nous empêcher d\'apprendre tout ce que nous pouvons sur leurs défenses.$b$bJ\'ai demandé à notre chevalier de la mort attitré de vous conseiller à ce sujet. Après tout, qui connaît mieux l\'ennemi que lui ?$b$bPermettez-moi de vous présenter Koltira Tissemort.', '', '', '', '', '', '', '', '', '', '', 0),
(14448, 'frFR', 'Les ennemis de mes ennemis…', 'Le Saccageur-des-cieux Korm Noire-balafre vous demande de parler à Koltira Tissemort, à bord du Marteau d\'Orgrim.', 'Même s\'il ne faut jamais perdre une occasion de frapper l\'Alliance, nous ne devons pas oublier le Fléau.$b$bIci, nous ne serons pas assez nombreux pour préparer une attaque en règle du glacier avant des semaines. Mais cela ne doit pas nous empêcher d\'apprendre tout ce que nous pouvons sur leurs défenses.$b$bJ\'ai demandé à notre chevalier de la mort attitré de vous conseiller à ce sujet. Après tout, qui connaît mieux l\'ennemi que lui ?$b$bPermettez-moi de vous présenter Koltira Tissemort.', '', '', '', '', '', '', '', '', '', '', 0),
(14449, 'frFR', 'La première étape', 'Suivez le sentier qui part vers l\'est depuis le Camp Narache et trouvez Grull Vent-du-faucon.', 'Mon enfant, ce que vous voyez ici est l’œuvre des hurans. Année après année, ils ont harcelé notre village. Lors du grand cataclysme, ils ont jailli de leurs repaires et se sont répandus sur nos terres comme une nuée de sauterelles. Et voici le résultat : ma mère, morte, victime de leur sauvagerie.$B$BVous êtes $gdevenu:devenue; adulte aujourd’hui. Et aujourd’hui, vous allez prendre une arme et combattre pour la tribu, pour venger la Grande-mère. Suivez le sentier vers l’est jusqu’à ce que vous ayez trouvé mon fils, Grull. Il vous expliquera comment frapper les hurans.', '', '', '', '', '', '', '', '', '', '', 0),
(14450, 'frFR', 'Distribution à taux progessif', 'Récupérez 10 Rouages progressifs.', 'Cette quête teste les distributions d\'objet à pourcentage progressif.', '', '', '', '', '', '', '', '', '', '', 0),
(14451, 'frFR', 'Distribution à taux constant', 'Récupérez 10 Rouages plats.', 'Cette quête teste les distributions d\'objet à pourcentage constant.', '', '', '', '', '', '', '', '', '', '', 0),
(14452, 'frFR', 'Le rite de force', 'Tuez 6 Envahisseurs dos-hirsutes.', 'Regardez, $n. La seule présence des Dos-hirsutes est un fléau. Il ne reste rien sur leur passage, sinon des cadavres et des terres stériles. Si nous ne nous battons pas, dans quelques jours, Camp Narache sera semblable à ce que nous contemplons.$B$BCe sera votre rite de force, la première cérémonie sur la voie qui fera de vous un brave tauren. Rendez-vous au cœur de Grognépine et tuez des Dos-hirsutes, puis revenez me voir.', '', '', '', '', '', '', '', '', '', 'Retournez voir Grull Vent-du-faucon.', 0),
(14455, 'frFR', 'Mort aux mande-épines !', 'Tuez 7 Mande-épines dos-hirsutes.', 'L’un des aspects les plus importants de la chasse est de connaître les mœurs de votre gibier. Dans leurs terres d’origine, les hurans prospèrent sous l’ombre protectrice d’immenses racines épineuses. Lorsqu’ils se déplacent, leurs chamans font pousser de nouvelles racines pour qu’ils puissent y vivre.$B$BLeurs épines balafrent la terre, l’étouffent et la rendent stérile. Allez au sud, et neutralisez les mande-épines avant qu’ils n’aient eu l’occasion de continuer, $n.', '', '', '', '', '', '', '', '', '', 'Retournez voir Adana Corne-tonnerre.', 0),
(14456, 'frFR', 'Le rite de courage', 'Récupérer 7 Fusils volés sur des Voleurs d’armes dos-hirsutes.', 'L’une des premières leçons que vous devez apprendre est de ne jamais sous-estimer votre proie, $n.$B$BUne bande de Dos-hirsutes a profité de ce que l’attaque de notre camp monopolisait notre attention pour se faufiler sans être remarquée, avant de piller une cache de fusils. Vous pouvez les voir au sud, remplissant l’air de plomb.$B$BCe sera votre rite de courage : braver cette grêle de balles, traquer les Dos-hirsutes qui nous ont volés, et nous ramener nos armes.', '', '', '', '', '', '', '', '', '', 'Retournez voir Adana Corne-tonnerre.', 0),
(14458, 'frFR', 'Allez voir Adana', 'Cherchez Adana Corne-tonnerre au sud-ouest.', 'Nous avons frappé un grand coup contre les hurans ici. Je vais rester là et tenir la position, mais vous devez continuer votre route.$B$BAllez voir Adana Corne-tonnerre, elle a conduit quelques braves vers le sud-ouest pour disperser les Dos-hirsutes restants.', '', '', '', '', '', '', '', '', '', '', 0),
(14459, 'frFR', 'Les sangliers de guerre', 'Tuez 10 Sangliers de guerre cuirassés.', 'Il y a d’autres menaces dont il faut s’occuper. Les Dos-hirsutes dressent des sangliers sauvages et s’en servent contre nous.$B$BCes sangliers de guerre en armure ont été tellement brutalisés qu’ils ne pourront plus vivre normalement. Il faut les abattre, pour eux… et dans notre intérêt. Rendez-vous aux enclos, au sud, et tuez-les, $n. Ensuite, revenez me voir.', '', '', '', '', '', '', '', '', '', 'Retournez voir Adana Corne-tonnerre.', 0),
(14460, 'frFR', 'Le rite d\'honneur', 'Tuez le chef Hurleur Mantépine.', 'Le chef Hurleur Mantépine dirige ces hurans. C’est lui qui les a lâchés sur Grande-mère Vent-du-faucon et a pris sa vie, ce qui a conduit à l’attaque sur Camp Narache. Ensuite, il a fui et s\'est caché, mais nous l’avons trouvé. Il se dissimule dans son infect nid d’épines, à l\'ouest. Tous les braves que nous avons envoyés après lui ont échoué.$B$BVous avez fait la preuve de votre vaillance en défendant notre peuple, $n. Tuez Mantépine et ramenez sa crinière au Chef Vent-du-faucon, pour honorer notre Grande-mère !', '', '', '', '', '', '', '', '', '', 'Retournez voir le Chef Vent-du-faucon au Camp Narache.', 0),
(14461, 'frFR', 'Les auges du mal', 'Servez-vous de la Torche d’Adana pour mettre le feu à 3 Auges dans l’Enclos des sangliers de guerre.', 'Nous ne devons pas nous contenter de chasser les sangliers. Il faut nettoyer ce qu’ils ont laissé derrière eux, et ce n’est pas joli à voir.$B$BPour leur donner le goût du sang, les sangliers de guerre étaient gavés de chair fraîche. Prenez cette torche, et servez-vous-en pour brûler les auges pleines de sang et de viande.', '', 'Première auge', 'Deuxième auge', 'Troisième auge', '', '', '', '', '', 'Retournez voir Adana Corne-tonnerre.', 0),
(14462, 'frFR', 'Où est ma tête ?', 'Vous devez aller chercher l’assassin gobelin Fugace Coutelard au pied de la tour du Nord de la Halte de Talrendis.', 'Il est là, $n ! Le capitaine Grunwald est un officier d’un rang élevé de l’Alliance. Il vient du fort de Guet-du-Nord et il ne fait aucun doute qu’il est ici pour organiser une attaque sur Orgrimmar avec ses alliés elfes de la nuit. Nous l’avons vu entrer dans la tour, au sud-ouest d’ici. Je veux sa tête, $c. Je veux la renvoyer à Guet-du-Nord pour semer le chaos parmi nos ennemis !$B$BJ’ai envoyé un assassin gobelin, Fugace Coutelard, à la tour mais elle n’est pas revenue. Allez la chercher. Et rapportez-moi cette tête !', '', '', '', '', '', '', '', '', '', 'Rejoignez l’assassin gobelin Fugace Coutelard au pied de la tour Nord de la Halte de Talrendis, en Azshara.', 0),
(14463, 'frFR', 'Des chevaux pour Havre-du-Soir', 'Parlez à Gwen Armstead à Havre-du-Soir.', 'Sauver les chevaux a peut-être sauvé toute la ville. Havre-du-Soir dispose de nombreuses voitures, mais pas suffisamment de chevaux pour les tirer.$B$BAllez dire au maire Armstead que les chevaux que vous avez sauvés sont à sa disposition.$B$BJe vais tout préparer et je vous rejoindrai dans peu de temps.', '', '', '', '', '', '', '', '', '', '', 0),
(14464, 'frFR', 'Attentat à la foudre', 'Allez voir Fugace Coutelard pour monter au sommet de la tour et assassiner le Capitaine Grunwald. Récupérez la Tête de Grunwald.', 'Les gardes d’élite du capitaine patrouillent au pied de la tour. Alors, voilà ce qu’on va faire : on va aller directement au sommet, découper en rondelles le grand manitou, et nous tirer en utilisant mon parachute portatif de faible altitude. Je vais bidouiller la tour pour qu’elle explose derrière nous. N’oubliez pas de prendre la tête du capitaine Grunwald pour Chawg. Compris ?$B$BN’ACCEPTEZ cette mission que si vous êtes $gprêt:prête; à TOUT FAIRE PÉTER. C’est clair ?', '', '', '', '', '', 'Voici la tête que vous devez récupérer. C\'est parti !', 'Capitaine Grunwald', '', '', 'Apportez la Tête de Grunwald à Chawg à Valormok, en Azshara. Fugace Coutelard connaît un raccourci pour sortir de la tour !', 0),
(14465, 'frFR', 'Direction le manoir de Grisetête', 'Parlez à la Reine Mia Grisetête dans le Manoir de Grisetête.', 'Il est temps pour tout le monde de se mettre en lieu sûr. Vous y compris, $n. Dirigez-vous vers le manoir de Grisetête, les autres y seront bientôt.$B$BNe vous inquiétez pas pour moi, je vais m\'assurer que tout le monde quitte la ville en un seul morceau. Oui, même les quelques bêtes féroces que nous gardons dans les enclos.$B$BUne fois sur place, informez la reine Grisetête de la gravité de la situation.', '', '', '', '', '', '', '', '', '', '', 0),
(14466, 'frFR', 'L\'observatoire du roi', 'Parlez au Roi Genn Grisetête à l\'observatoire dans le Manoir de Grisetête.', 'Vous devriez parler à Genn. Il s\'est enfermé dans son observatoire depuis le début de cette épreuve.$B$BJe suis certaine qu\'il est en train de réfléchir à un plan pour son peuple. C\'est un homme particulièrement entêté.', '', '', '', '', '', '', '', '', '', '', 0),
(14467, 'frFR', 'Hélas, Gilnéas !', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(14468, 'frFR', 'Le bouche-trou', 'Présentez-vous au Commandant Molotov sur la Crête Lugubre.', 'Hé, j’ai une super affaire à vous proposer ! Vous immerger dans des cultures étrangères, vivre des aventures extraordinaires, faire exploser des trucs, et être $gpayé:payée; pour ça ! Trop beau pour être vrai vous pensez ? Hé bien non, c’est vraiment ce que nous proposons !$B$BSi ça vous intéresse, rendez-vous au poste de défense de Gallywix, sur la crète Lugubre au nord, et cherchez le commandant Molotov.', '', '', '', '', '', '', '', '', '', '', 0),
(14469, 'frFR', 'Matériel de récupération', 'Récupérez 12 Packs de ravitaillement militaire dans le champ de mines central.', 'Chaque chose en son temps. Il nous faut des fournitures pour les nouvelles recrues, y compris vous. Il y a des paquetages réglementaires en très bon état sur les corps de la dernière fournée de recrues, dans le champ de mines, au nord.$B$BSi vous ne voulez pas finir comme eux, je vous recommande d’éviter de marcher sur des mines.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Commandant Molotov au Poste de défense de Gallywix sur la Crête Lugubre, en Azshara.', 0),
(14470, 'frFR', 'Percée militaire', 'Tuez le Seigneur de guerre Krellian et récupérez la GSB.', 'Nous avons perdu tout contact avec le sergent Dynamo, posté près de la crête à proximité, au nord du champ de mines central. Sa section a dû être submergée.$B$BIl avait notre dernière GSB. Rendez-vous sur place et rapportez-la-moi. Profitez-en pour tuer tous les nagas qui ont investi les lieux.', '', '', '', '', '', '', '', '', '', 'Retournez voir Glix Grinceverrou au Poste de défense de Gallywix sur la Crête Lugubre, en Azshara.', 0),
(14471, 'frFR', 'Mortier au premier degré', 'Utilisez un Mortier gobelin pour tuer 60 Attaquants fouette-bile.', 'Hé, l\'$gami:amie; ! Vous aimez les explosions ? Je suis sûr que oui. Qui n’aime pas ça ?!$B$BJ’ai placé des mortiers sur la crête, à l’est, pour repousser les nagas. Allez-y, recrue. Mortierisez-les… mortierisez-les tous ! Ahahahah !', '', 'Attaquants fouette-bile réduits en poussière', '', '', '', '', '', '', '', 'Retournez voir Xiz Salvesouffle au Poste de défense de Gallywix sur la Crête Lugubre, en Azshara.', 0),
(14472, 'frFR', 'Dans ta face !', 'Utilisez une GSB pour tuer un Fils d’Arkkoroc asservi au champ de mines du Sud.', 'Les nagas utilisent des géants pour créer des chemins dans nos champs de mines. Il est temps d’utiliser cette GSB !$B$BDirigez-vous vers l’entrée du champ de mines, au sud : je pense que vous avez compris ce qu’il vous reste à faire.', '', '', '', '', '', '', '', '', '', 'Retournez voir Glix Grinceverrou au Poste de défense de Gallywix sur la Crête Lugubre, en Azshara.', 0),
(14473, 'frFR', 'C\'est notre problème, maintenant', 'Tuez 6 Jeunes téraptors.', 'On dirait que ces singes voleraient n\'importe quoi ! Ces sales petits chapardeurs ont rendu la matriarche téraptor folle furieuse en volant ses œufs. Pire encore, les œufs ont commencé à éclore ! Nous sommes maintenant envahis par de jeunes téraptors affamés qui cherchent à faire de nous leur repas !$B$BNous n\'y sommes pour rien, mais c\'est notre problème maintenant. Vous allez devoir tuer ces jeunes téraptors dans la jungle avant qu\'ils ne nous tuent jusqu\'au dernier.', '', '', '', '', '', '', '', '', '', 'Retournez voir Maxx Avalanche sur le Rivage de l’Épave, sur les Îles Perdues.', 0),
(14474, 'frFR', 'Les capsules de sauvetage gobelines', 'Portez secours à 6 Survivants gobelins.', '$n, je suis navré, je croyais que vous étiez $gmort:morte; !$B$BC\'est juste incroyable. Notre navire s\'est retrouvé au milieu d\'une bataille entre l\'Alliance et la Horde !$B$BNos frères et sœurs ont besoin d\'être secourus.$B$B<Il montre toutes les capsules de sauvetage autour de vous.>$B$BJe crois que je vais encore un peu rester assis pour reprendre mon souffle. Pourriez-vous les rejoindre à la nage et les aider à sortir des capsules ? Prenez mes palmes thermohydratiques, vous irez plus vite.$B$BDites à Chipie que je viendrai bientôt.', '', 'Survivants gobelins secourus', '', '', '', '', '', '', '', 'Faites votre rapport à Chipie Serrelavis sur le Rivage de l’Épave, sur les Îles Perdues.', 0),
(14475, 'frFR', 'Coursiers du vent à terre !', 'Trouvez le Capitaine bombardier Smooks près de la tour elfe de la nuit la plus au sud, à la Halte de Talrendis.', 'Vous voyez quelque chose qui cloche avec ces coursiers du vent, $n ? Eh bien, ils ne volent pas ! Toutes les escadrilles que j’envoie se font mitrailler par des snipers elfes de la nuit.$B$BLes tireurs de précision de Talrendis sont planqués dans la tour la plus au sud, adossée aux montagnes. J’ai envoyé un de ces traîne-savates de gobelins s’en occuper, mais je n’ai plus aucune nouvelle de lui. Trouvez le capitaine bombardier Smooks, et donnez-lui une raclée avec le bâton-baston !', '', '', '', '', '', '', '', '', '', 'Trouvez le Capitaine bombardier Smooks près de la tour elfe de la nuit la plus au sud, à la Halte de Talrendis, en Azshara.', 0),
(14476, 'frFR', 'Une idée explosive', 'Amorcez les trois Charges explosives situées autour de la base de la tour la plus au sud, à la Halte de Talrendis.', 'Comme cette tour était hors de portée de canon, j’ai pensé qu’on pourrait la faire sauter à l’ancienne, c’est-à-dire à la main. On a mis en place toutes les charges principales mais les gardes nous ont chassés avant qu’on puisse amorcer les détonateurs.$B$B$n ! Rendez-vous sur place et amorcez les trois détonateurs placés tout autour de la base de la tour. Ces bébés sont reliés à des charges thermiques que j’ai disposées le long de la crête… Ça va être un vrai feu d’artifice !', '', 'Charge du détonateur 1 amorcée', 'Charge du détonateur 2 amorcée', 'Charge du détonateur 3 amorcée', '', '', '', '', '', 'Retournez voir le Capitaine bombardier Smooks à la Halte de Talrendis, en Azshara.', 0),
(14477, 'frFR', 'Appuyez sur le bouton !', 'Faites péter les explosifs !', 'Laissez-moi juste vérifier les connexions... Et on sera prêt. À vous l\'honneur, $n. Allez-y. Appuyez sur le bouton !$B$BAppuyez sur le bouton, $n !$B$BAprès le feu d\'artifice, allez prévenir Kroum à Valormok que son ciel est dégagé.$B$BAppuyez sur le bouton !', 'Faire péter les explosifs', '', '', '', '', '', '', '', '', 'Présentez-vous à Kroum à Valormok, en Azshara.', 0),
(14478, 'frFR', 'Opération Poiscaille', 'Allez vous présenter au Commandant Molotov sous le canon principal, au Havre Baille-Fonds.', 'Le bataillon de Baille-Fonds recrute actuellement pour son OPÉRATION POISCAILLE.$B$BTous les soldats en règle qui auront terminé l’opération recevront une pièce d’or. Toutes les récompenses seront perdues en cas de décès. Une contribution de vingt pièces d’argent sera demandée pour toute résurrection réalisée dans le cadre du service.$B$BToutes les recrues doivent se présenter directement au commandant Molotov, sous le canon principal.', '', '', '', '', '', '', '', '', '', '', 0),
(14479, 'frFR', 'Il y en a beaucoup des comme ça', 'Utilisez une fusée pour atteindre la Grève Fracassée, puis présentez-vous au Lieutenant Drex.', 'Assez de bavardages. Bougez-vous les fesses et grimpez sur une fusée, soldat.$B$BEt souvenez-vous, si vous mourez, vous ne serez pas $gpayé:payée;.', '', '', '', '', '', '', '', '', '', '', 0),
(14480, 'frFR', 'Extermination', 'Tuez 30 Nagas fouette-bile aux Ruines d’Eldarath.', 'On vous envoie là-bas pour nettoyer l’infestation naga. On a reçu l’autorisation d’utiliser la force meurtrière.$B$BLa Brigade gob assurera vos arrières, ça devrait donc être une promenade de santé.', '', 'Nagas fouette-bile tués', '', '', '', '', '', '', '', 'Retournez voir le Sergent Zelks aux Ruines d’Eldarath.', 0),
(14482, 'frFR', 'L\'appel du devoir', 'Allez à la bataille à bord du navire des mercenaires.', 'Citoyen !$b$bComme vous le savez peut-être, les forces de la Horde se trouvent juste au large. Nous les affrontons, mais les combats sont féroces et interminables.$b$bNous avons besoin de tout le monde pour repousser l’ennemi !$b$bPour partir à la bataille, présentez-vous immédiatement au quai nord.$b$bAh, et nos navires de guerre sont… hum, un peu en retard. Ne vous inquiétez pas, nous avons engagé des vaisseaux mercenaires pour les remplacer en attendant.$b$bHâtez-vous, $c. Hurlevent a besoin de vous !', 'Prendre le navire des mercenaires pour Vashj\'ir', 'Allez à Vashj\'ir à bord du navire des mercenaires', '', '', '', '', '', '', '', 'Parlez à Erunak à bord du Fend-les-flots.', 0),
(14484, 'frFR', 'La tête du serpent', 'Tuez le Seigneur Kassarus au Temple de Zin-Malor.', 'Au camp des officiers, on nous a toujours appris à couper la tête des serpents. Ça semblait idiot à l’époque, vu qu’on n’avait jamais combattu de serpents, mais je pense que ça prend tout son sens aujourd’hui.$B$BEmmenez vos hommes et allez tuer le seigneur Kassarus.', '', '', '', '', '', 'Plus ils sont gros, plus la bombe que vous utilisez doit être grosse.', 'Seigneur Kassarus', '', '', 'Retournez voir le Sergent Zelks aux Ruines d’Eldarath.', 0),
(14485, 'frFR', 'Tocant est demandé au rayon explosifs', 'Appelez Tocant dans les ruines à l’aide de la Fusée de l’escouade Gob\' et couvrez ses arrières jusqu’à ce qu’il ait fait exploser 3 Pierres runiques fouette-bile.', 'Notre meilleur démolisseur, Tocant, est en mission avec la Brigade gob. Il a BIEN plus qu’assez d’explosifs pour toutes les pierres runiques des ruines.$B$BVous n’avez qu’à l’appeler une fois à proximité d’une pierre runique, puis il vous suffira de couvrir ses arrières : il se chargera du reste.', '', 'Pierres runiques fouette-bile détruites', '', '', '', '', '', '', '', 'Retournez voir le Sergent Zelks aux Ruines d’Eldarath.', 0),
(14486, 'frFR', 'Bien tabler', 'Récupérez 12 Tablettes de Bien-né dans les Ruines d\'Eldarath.', 'Salut, l’$gami:amie; ! Vous voulez gagner un peu d’argent, vite fait bien fait ?$B$BRapportez-moi des tablettes de Bien-né que vous trouverez dans les ruines.', '', '', '', '', '', '', '', '', '', 'Retournez voir Tora Halotrix aux Ruines d’Eldarath.', 0),
(14487, 'frFR', 'Coup de cœur', 'Récupérez le Cœur d’Arkkoroc au centre des Ruines d’Eldarath.', 'Le commandant Molotov a trouvé un acheteur potentiel au laboratoire secret pour l’artéfact que vous avez découvert un peu plus tôt.$B$BLa relique doit encore reposer au centre des ruines avec la grande prêtresse, à l’endroit où vous l’aviez aperçue la première fois. Rapportez-la-moi intacte, recrue.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Capitaine Tork aux Ruines d’Eldarath.', 0),
(14491, 'frFR', 'La terre s\'agite', 'Servez-vous du Tambour de la terre apaisée pour calmer 6 Esprits de la terre agités.', 'Un groupe de nains s’était introduit sur nos terres à l’ouest. Jusqu’à une date récente, ils creusaient le sol bêtement, à la recherche de trésors. Lorsque la terre s’est ouverte, les esprits qu’ils avaient maltraités se sont soulevés et ont pris leur revanche.$B$BLes esprits de la terre agités hantent encore le site des fouilles, $n. Nous devons les calmer.$B$BPrenez ce tambour, partez vers l’ouest et jouez pour les esprits. Le rythme les calmera et dissipera leur confusion.', '', 'Esprits calmés', '', '', '', '', '', '', '', 'Retournez voir Ahmo Corne-Tonnerre à Sabot-de-Sang.', 0),
(20440, 'frFR', 'L\'eau empoisonnée', 'Récupérez 6 Pattes de loups des prairies et 4 Serres de trotteurs des plaines.', 'Nos puits sacrés ont été corrompus, et je vais avoir besoin de votre aide pour trouver une solution.$B$BPour purifier chaque puits, je vais créer un totem de purification. Vous devez l’amener au puits et accomplir un rituel de purification.$B$BNous allons commencer par créer le totem qui purifiera le puits Sabot-d’hiver. Pour cela, nous allons avoir besoin de l’aide de la terre. Traquez les loups des prairies pour leurs pattes et les trotteurs des plaines adultes pour leurs serres. Vous les trouverez au sud-ouest.$B$BRevenez me voir avec leurs pattes et leurs serres, $n.', '', '', '', '', '', '', '', '', '', 'Retournez voir Mull Corne-Tonnerre à Sabot-de-Sang.', 0),
(20441, 'frFR', 'Le rite de vision', 'Buvez l’Eau de vision devant le feu tribal de Sabot-de-Sang.', 'Assurez-vous d’être $gprêt:prête; à quitter Sabot-de-Sang, $n. La prochaine étape de votre voyage va vous emmener très loin d’ici.$B$BVotre route s’étend à travers les plaines de Mulgore, sous le regard de la Terre-Mère. Lorsque vous serez $gprêt:prête;, consommez les eaux près du feu de la tribu. Lorsque vous aurez bu les eaux sacrées, vos yeux s’ouvriront, et les esprits vous guideront.', '', 'Eau de vision bue', '', '', '', '', '', '', '', '', 0),
(23733, 'frFR', 'Les rites de la Terre-mère', 'Parler à Dyami Plane-vent au sommet de la Mesa de Mireloin.', 'Aujourd’hui, vous avez accompli un rite de passage bien plus difficile que ce que nous exigeons de la plupart de nos jeunes. Vous pouvez être $gfier:fière; de vous. Il est temps à présent de continuer votre route.$B$BÀ l’ouest, au-delà du cimetière, vous trouverez un chemin qui monte en haut de la mesa. Suivez-le jusqu’au sommet, et parlez à Dyami Plane-vent.$B$BMarchez avec la Terre-Mère, $gmon ami:mon amie;. Vous serez toujours $gle bienvenu:la bienvenue; ici.', '', '', '', '', '', '', '', '', '', '', 0),
(24215, 'frFR', 'Le rite des vents', 'Boire l\'Eau de vision.', 'Regardez, $n. Les plaines vallonnées de Mulgore s’étendent devant vous : notre domaine, le berceau de la Terre-Mère, une contrée verdoyante et paisible qui nous donne tout ce dont nous pouvons rêver. C’est pour elle que vous devez vous battre.$B$BVotre voyage vous emmènera bien loin de ses bras protecteurs, dans les régions les plus cruelles de ce monde, et au-delà.$B$BEn dessous de nous se trouve le village de Sabot-de-Sang. Vous allez faire votre premier pas sur votre véritable chemin. Buvez l’eau de vision, et laissez les esprits vous guider.', '', '', '', '', '', '', '', '', '', '', 0),
(24430, 'frFR', 'Les cieux s\'obscurcissent', 'Enfourchez un Coursier du vent immobilisé et survolez la Halte de Talrendis. Détruisez 6 Lanceurs de glaive de Talrendis, puis bombardez le Centre de commandement.', '$n ! Vous voulez bien venir nous donner un coup de main ? Gorsch, que vous voyez là, a eu une mauvaise expérience au resto de fruits de mer à volonté, en ville, et maintenant il nous manque quelqu’un pour chevaucher un coursier du vent.$B$BJ’étais censé éliminer ces lanceurs de glaive elfes avant qu’ils ne découpent nos unités aériennes en rondelles. Grimpez sur ce coursier du vent et envolez-vous ! L’un de mes bombardiers vous accompagnera et bombardera les cibles de votre choix.$B$BEt... ah oui ! Larguez carrément une bombe sur le centre de commandement des elfes de la nuit : c’est le grand bâtiment au sud d’ici, près du pont. Ça va être glorieux !', '', '', 'Centre de commandement bombardé', '', '', '', '', '', '', 'Retournez voir l’Apprenti bombardier Hackel à Valormok, en Azshara.', 0),
(24432, 'frFR', 'Le pied marin', 'Erunak, à bord du Fend-les-flots, veut que vous lui rapportiez 3 Étoiles de mer et une Coquille de conque de la Tombe du marin.', 'Bienvenue à bord du Fend-les-flots, $c.$b$bJe m’appelle Erunak, le dernier passager encore en vie sur ce navire à la fierté disparue.$b$bJ’ai bien peur que votre travail ne fasse que commencer. Les nagas nous attaquent sans relâche, ici.$b$bVous n’êtes pas encore assez bien $géquipé:équipée; pour agir efficacement, mais je peux arranger ça.$b$bUne espèce particulière d’étoile de mer vit juste à l’extérieur de ce bateau. Rapportez-m’en quelques-unes, ainsi qu’une coquille de conque. Grâce à ces composants, je préparerai un enchantement qui devrait augmenter vos chances de survie.', '', '', '', '', '', '', '', '', '', 'Retournez auprès d’Erunak à bord du Fend-les-flots.', 0),
(24433, 'frFR', 'Semer la terreur', 'Frayez-vous un chemin à travers la Halte de Talrendis, tuez 12 Défenseurs de Talrendis et 6 Sentinelles de Talrendis.', 'Nos grunts sont forts, mais ils ne font preuve d’aucune initiative. Ils ne mènent le combat que sur le front. Mais $gun:une:c; $c téméraire comme vous, enfin… quelqu’un comme vous peut se glisser derrière les lignes adverses et semer la terreur au sein de la redoute ennemie.$B$BDétruisez le cœur de Talrendis, $n ! Nos ennemis pensent que leur territoire est sécurisé… profitez-en pour les tuer, et semez la terreur et le désespoir sur votre passage !', '', '', '', '', '', '', '', '', '', 'Retournez voir Chawg à Valormok, en Azshara.', 0),
(24434, 'frFR', 'Opération commando', 'Tuez 5 Gardiens du savoir de Talrendis et trouvez la Pierre d’invocation des Gardiens du savoir quelque part dans la Halte de Talrendis.', 'Vous sentez les tremblements de terre provoqués par les lignes telluriques locales, $n ? Je perçois des vibrations ponctuelles, comme une corde que l’on pince. On dirait la résonance qu’émettrait un sort d’invocation à grande portée. Les gardiens du savoir de Talrendis, avec leur magie primitive ridicule, essaient d’invoquer des renforts de Darnassus.$B$BNous pouvons tourner cela à notre avantage, $n. Si vous réussissez à altérer leur pierre d’invocation, nous pourrons téléporter un groupe de commandos derrière les lignes ennemies.$B$BLocalisez la pierre d’invocation dans Talrendis !', '', '', '', '', '', '', '', '', '', 'Manipulez la Pierre d’invocation des Gardiens du savoir. Ensuite, elle pourra servir de raccourci vers Valormok.', 0),
(24435, 'frFR', 'Le grand lessivage', 'Tuez 12 Nagas fouette-bile sur la Grève Fracassée.', 'Il reste encore beaucoup de nagas sur cette plage. Vous allez devoir vous mouiller, $gfiston:jeune fille;.', '', 'Défenseurs nagas tués', '', '', '', '', '', '', '', 'Retournez voir le Lieutenant Drex sur la Grève Fracassée.', 0),
(24436, 'frFR', 'La mort vous va si bien', 'Appelez des Prêtres volants auprès des corps de 8 Soldats estropiés sur la Grève Fracassée.', 'Partout sur la plage, des soldats nous claquent dans les bras pour essayer d’échapper à leurs corvées. Trouvez-moi ces fainéants et utilisez ce lance-fusées pour qu’un prêtre vienne s’occuper de la situation.$B$BIl ne faut pas que ces hommes pensent qu’ils peuvent s’en tirer si facilement.', '', 'Soldats estropiés secourus', '', '', '', '', '', '', '', 'Retournez voir le Sergent Hort sur la Grève Fracassée.', 0),
(24437, 'frFR', 'Premier arrivé, premier servi', 'Plantez le Drapeau de revendication territoriale de Grabuge près des biens immobiliers de premier choix, le long de la Grève Fracassée.', 'Sur le front de mer, il y a de magnifiques terrains tout le long de la côte. Je peux en tirer dix fois plus que ce que la construction m\'en coûtera.$B$BLes meilleurs endroits sont la pagode naga au sud, la tour juste à côté de l’eau, et les ruines à l’extrémité nord de la plage. Je vous donnerai une piécette si vous les revendiquez pour moi avant que la bataille ne détruise tout.', '', 'Pagode sud revendiquée', 'Vieille tour immense revendiquée', 'Panorama nord revendiqué', '', '', '', '', '', 'Retournez voir Grabuge sur la Grève Fracassée.', 0),
(24438, 'frFR', 'L\'exode', 'Montez à bord d\'une voiture au pied du Manoir de Grisetête.', 'Nous n\'avons pas le choix, $n. Nous devons nous enfoncer plus loin dans les terres.$B$BJe n\'aime pas ça, mais nous sommes vulnérables, ici.$B$BRetournez aux écuries au pied du manoir. Que tout le monde monte en voiture et prenne la direction de l\'est. Prions pour qu\'il ne soit pas trop tard.', '', '', '', '', '', '', '', '', '', '', 0),
(24439, 'frFR', 'La conquête d\'Azshara', 'Tuez le Commandant Jarrodenus à la Halte de Talrendis et récupérez sa tête.', '$n ! C’est vous qui chevauchiez le coursier du vent qui a bombardé le centre de commandement ?$B$BMes éclaireurs m’ont signalé que vous aviez gravement blessé Jarrodenus, le maître de vol des chasse-le-ciel elfes de la nuit, et de fait le commandant de l’opposition.$B$BC’est maintenant qu’il faut frapper, je n’ai pas le temps d’organiser une attaque en bonne et due forme. Alors, prenez d’assaut le bâtiment du centre de commandement et tuez le commandant Jarrodenus avant que ses renforts n’arrivent. Rapportez-moi sa tête… et Azshara nous appartiendra !', '', '', '', '', '', 'Nous ne sommes qu\'à une tête de la victoire. Et c\'est de cette tête dont il s\'agit.', 'Commandant Jarrodenus', '', '', 'Retournez voir Chawg à Valormok, en Azshara.', 0),
(24440, 'frFR', 'Purification de Sabot-d\'hiver', 'Utiliser le Totem de purification de Sabot-d\'hiver au puits Sabot-d\'hiver.', 'J’ai fabriqué le totem qui nous permettra de purifier le puits Sabot-d’hiver. Vous devez l’emmener là-bas et accomplir le rituel. Il se trouve au sud-est, mais prenez garde, celui qui a fait ça s’y trouve peut-être encore, à nous attendre.$B$BCela pourrait être très dangereux, $n. Faites attention… ne laissez pas ceux qui ont souillé nos puits s’échapper.', 'Puits purifié', '', '', '', '', '', '', '', '', 'Retournez voir Mull Corne-Tonnerre à Sabot-de-Sang.', 0),
(24441, 'frFR', 'Le totem de Corne-tonnerre', 'Collectez 6 Griffes de traqueur et 6 Griffes de puma.', 'Nous avons encore du travail. Nous devons créer un nouveau totem pour purifier le puits Corne-tonnerre.$B$BVous devez récupérer les griffes des prédateurs des plaines de Mulgore. Chassez les traqueurs de la prairie et les pumas des basses plaines et prenez leurs griffes, puis revenez me voir.$B$BVous trouverez traqueurs et pumas à l’est et à l’ouest.', '', '', '', '', '', '', '', '', '', 'Retournez voir Mull Corne-Tonnerre à Sabot-de-Sang.', 0),
(24448, 'frFR', 'Promotion sur le terrain', 'Présentez-vous au Capitaine Tork au Poste avancé des Ruines d’Eldarath.', 'Sur ordre du commandant Molotov, vous devez être $genvoyé:envoyée; sur-le-champ à notre poste avancé. Nous sommes en train de préparer l’envoi d’escouades dans les ruines pour dérouter les nagas et récupérer l’artéfact. Le commandant veut que vous preniez la tête d’une de ces escouades.$B$BAllez à l’extrémité nord-ouest de la plage, et suivez le chemin qui mène à notre poste avancé.', '', '', '', '', '', '', '', '', '', '', 0),
(24449, 'frFR', 'Permission à terre', 'Apportez le Cœur d’Arkkoroc à Oncle Binz au Havre Baille-Fonds.', 'On s’en sort plutôt bien jusque-là. Ça a vraiment été un plaisir de travailler avec vous, soldat.$B$BSi vous êtes $gprêt:prête; à rapporter l’artéfact, un gyrocoptère vous attend pour vous ramener au havre Baille-Fonds. Ensuite, vous pourrez remettre l’artéfact en mains propres à Oncle Binz.', '', '', '', '', '', '', '', '', '', '', 0),
(24452, 'frFR', 'Objectif rentabilité', 'Utilisez le Générateur de champ de camouflage pour vous introduire dans les Ruines d’Eldarath et identifier le Cœur d’Arkkoroc.', 'La situation semble se calmer un peu. Gallywix va certainement continuer à casquer pour qu’on reste en poste ici, et j’ai le sentiment que ce marché pourrait nous rapporter un peu plus d’argent.$B$BD’habitude, nagas et géants des mers ne font pas bon ménage, j’en déduis que les nagas doivent les contrôler d’une manière ou d’une autre. Prenez ce générateur de champ de camouflage, allez dans les ruines, et prévenez-moi si vous trouvez quelque chose d’intéressant.', 'Cœur d\'Arkkoroc identifié', '', '', '', '', '', '', '', '', 'Retournez voir le Commandant Molotov au Poste de défense de Gallywix sur la Crête Lugubre, en Azshara.', 0),
(24453, 'frFR', 'Worcester fait monter la sauce', 'Allez voir le Soldat Worcester à la Station d’Orgrimmar du fusorail.', 'Écoutez… j’ai un dernier service à vous demander avant que vous ne partiez.$B$BLe soldat Worcester est resté à la tour, à « recruter ». Allez le voir pour lui dire que nous sommes prêts à plier le camp, maintenant. Nous rentrons en ville.$B$BCe fut un plaisir de travailler avec vous, recrue.', '', '', '', '', '', '', '', '', '', '', 0),
(24455, 'frFR', 'Déploiement rapide', 'Présentez-vous au Capitaine Desoto au Havre Baille-Fonds pour être $gdéployé:déployée;.', 'Vous allez reprendre le service sur-le-champ. Le capitaine Desoto supervise le déploiement. Vous le trouverez au bout de la rampe de la station de lancement de fusées.$B$BRendez-nous riches, soldat. Rompez !', '', '', '', '', '', '', '', '', '', '', 0),
(24456, 'frFR', 'La purification de Corne-tonnerre', 'Servez-vous du Totem de purification de Corne-tonnerre au Puits Corne-tonnerre.', 'La tribu des Totems-Sinistres croit que Kalimdor devrait appartenir aux taurens et à eux seuls. Leur haine et leur colère leur ont donné une soif de pouvoir qui, à son tour, les a corrompus. Magatha, leur chef, a empoisonné notre grand chef Cairne Sabot-de-Sang, avant de tenter de s’emparer des Pitons-du-Tonnerre. Elle a été vaincue, et les Totems-Sinistres ont été exilés.$B$BDésormais, ils cherchent la ruine de Mulgore, dont ils sont en train d’être chassés. Vite, $n, vous devez aller au puits Corne-Tonnerre, au nord, et accomplir le rituel !', 'Puits purifié', '', '', '', '', '', '', '', '', 'Retournez voir Mull Corne-Tonnerre à Sabot-de-Sang.', 0),
(24457, 'frFR', 'Le rite de vision', 'Parlez à Zarlman Deux-Lunes à Sabot-de-Sang.', 'Je ne vous remercierai jamais assez d’avoir purifié le puits de ma tribu, $n, et d’avoir combattu les sauvages Totems-Sinistres. Mais il reste encore beaucoup à faire, et il est temps que votre route vous conduise loin de Sabot-de-Sang.$B$BZarlman Deux-Lunes se tient près du feu, au nord du village. Allez lui parler et il vous expliquera le prochain rituel que vous devrez accomplir.', '', '', '', '', '', '', '', '', '', '', 0),
(24458, 'frFR', 'Noyau atomique', 'Apportez le Noyau d’azsharite armé à Bleenik Foiramorce au Havre Baille-Fonds. Allez voir Friz Tourneterre pour qu’il vous offre le trajet.', '$n, j’ai utilisé l’échantillon purifié d’azsharite que vous avez récupéré au laboratoire pour créer une arme. Si mes calculs sont bons, la puissance de l’explosion devrait suffire à raser une ville entière.$B$BSi je me trompe, c’est la planète entière qui disparaîtra.$B$BLa seule façon de le savoir est de faire un test ! Apportez le noyau d’azsharite près du canon géant de Baille-Fonds et présentez-vous à Bleenik Foiramorce. Friz Tourneterre, mon pilote de maître ici présent, peut vous conduire auprès de lui.$B$BJe vous suivrai… de loin.', 'Noyau d\'azsharite apporté', '', '', '', '', '', '', '', '', 'Apportez le Noyau d’azsharite armé à Bleenik Foiramorce au Havre Baille-Fonds. Allez voir Friz Tourneterre pour qu’il vous offre le trajet.', 0),
(24459, 'frFR', 'Morin Traqueur-de-nuage', 'Trouvez Morin Traqueur-de-Nuage à l’est de Sabot-de-Sang.', 'Peut-être avez-vous entendu parler de la KapitalRisk ? C’est un « cartel » gobelin, une sorte de tribu.$B$BL’un de ces cartels a rejoint la Horde, mais la KapitalRisk ne s’intéresse qu’au profit. Ces gobelins cupides et leurs ouvriers ont déjà tenté d’exploiter les ressources de Mulgore par le passé, sans grand succès.$B$BL’une de nos estafettes, Morin Traqueur-de-nuage, est parti examiner les restes de l’une des caravanes gobelines. Si vous désirez l’aider, prenez la route qui part du village vers l’est.', '', '', '', '', '', '', '', '', '', '', 0),
(24460, 'frFR', 'Hors service', 'Le Donneur de quêtes de test de Paul veut que vous tuiez des zombies.', 'Hé, $n, je veux que vous me répariez le cataclysme. Allez donc chasser quelques zombies. Vous êtes |5$r.', '', '', '', '', '', '', '', '', '', '', 0),
(24463, 'frFR', 'Enquête en Orneval', 'Allez parler à Kulg Crachetripes, en Orneval.', 'Cette racaille de Darnassus se retire d’Azshara, mais mes messagers, postés en Orneval, à l’ouest, m’envoient des rapports mitigés. Les elfes de la nuit pourraient se préparer à attaquer les Tarides.$B$B$C, il faut que vous passiez la frontière pour aller parler à l’un de mes éclaireurs. Cherchez Kulg Crachetripes, juste après le pont, à l’extrême sud-ouest de la halte de Talrendis. Il se trame quelque chose dans ces bois, et vous devez découvrir de quoi il s’agit !', '', '', '', '', '', '', '', '', '', 'Allez parler à Kulg Crachetripes, en Orneval.', 0),
(24467, 'frFR', 'Le déclin du Crépuscule', 'Tuez la Dame du Crépuscule Katrana et Malicion à la Crête Fuligineuse.', 'Nous allons mettre fin à toute cette folie. Pour cela, il faut chasser définitivement les membres du Vol draconique noir en Azshara avant qu’ils ne puissent transmettre des informations à leur maître.$B$BJe ne sais toujours pas ce qu’ils prévoient pour nous capturer, alors j’aimerais vous demander une dernière chose : allez à la crête Fuligineuse et tuez leurs chefs, la dame du Crépuscule Katrana et Malicion.$B$BSi les choses se gâtent, je viendrai vous aider. C’est juste que je ne veux pas risquer de tomber dans un piège tendu pour Azuregos.', '', '', '', '', '', 'Parfois, la chasse aux dragons peut s\'avérer impitoyable.', 'Dame du Crépuscule Katrana', '', '', 'Allez voir Kalecgos au Terminus nord du fusorail.', 0),
(24468, 'frFR', 'Coincés dans les marais', 'Portez secours à 5 Survivants de l\'accident dans le Marais du Bois-grêlé.', 'Les ogres ont eu deux de nos diligences... Celle-ci, et une autre, qui est tombée dans les marécages un peu plus au nord.$B$BJ\'aimerais que vous y alliez et que vous portiez secours aux éventuels survivants pendant que nous élaborons un plan pour nous débarrasser de ces ogres.', '', 'Survivant de l\'accident secouru', '', '', '', '', '', '', '', 'Retournez voir Liam Grisetête à la Diligence accidentée.', 0),
(24469, 'frFR', 'Maintenez le front !', 'Tuer 6 Envahisseurs mâcherocs.', 'Hé, vous, là ! Vous m’avez tout l’air d’$gun:une:c; $c qui sait se défendre. Vous voulez bien nous prêter main-forte ?$b$bOn dirait que le gros tremblement de terre d’aujourd’hui a fait remonter des groupes de troggs des profondeurs de la terre. En plus, ils sont sacrément remontés. Mes hommes font ce qu’ils peuvent pour les repousser, mais ils auraient bien besoin d’un coup de main.$b$bFaites votre boulot : allez aider mes montagnards à maîtriser la situation, au sud. Nous devons maintenir le front à tout prix !', '', '', '', '', '', '', '', '', '', 'Retournez voir Joren Ironstock à la Vallée des Frigères.', 0),
(24470, 'frFR', 'Donnez-leur une raclée', 'Tuez 3 Spadassins mâcherocs.', 'Bon, écoutez, $n. Je connais une ou deux choses à propos des troggs, et ce dont je suis sûr, c’est que ce sont les plus forts et les plus grands troggs qui sont les plus respectés au sein de leur groupe. Ces brutes placent la force physique au-dessus de tout.$b$bVous voyez ces grands troggs qui se tiennent derrière les premières lignes ? C’est ce qu’ils ont de plus ressemblant à ce que nous, nous appellerions un commandant. Allez en éliminer quelques-uns, histoire de leur montrer ce qui arrive quand on s’en prend aux fils de Forgefer !', '', '', '', '', '', '', '', '', '', 'Retournez voir Joren Ironstock à la Vallée des Frigères.', 0),
(24471, 'frFR', 'Aide aux blessés', 'Utilisez la Trousse de premiers soins de Sten pour soigner 4 Montagnards des Frigères blessés.', 'Écoutez, $n ! Contrairement à Joren, je n’ai pas besoin d’un sabreur, mais de quelqu’un qui a la main sûre et le cœur bien accroché.$b$bNos montagnards sont entraînés pour protéger le village des attaques de loups sporadiques… pas pour repousser une invasion de troggs ! À cause de ça, pas mal de mes meilleurs hommes sont blessés ou épuisés, et j’aimerais que vous m’aidiez à les soigner.$b$bTenez, prenez ma trousse de premiers soins et aidez-en autant que vous pourrez.', '', 'Montagnards des Frigères blessés aidés', '', '', '', '', '', '', '', 'Retournez voir Sten Rudebras à la Vallée des Frigères.', 0),
(24472, 'frFR', 'Des présentations dans les règles', 'Tuez 4 Serviteurs ogres et obtenez la Bannière de Koroth dans l\'Antre de Koroth.', 'Les Réprouvés sont à nos trousses et maintenant les ogres tentent de nous atteindre par les flancs, $n.$B$BIls servent l\'ettin Koroth, la force la plus mauvaise et la plus destructrice de tout Gilnéas.$B$BSi nous pouvons leurrer Koroth pour qu\'il attaque les forces avancées des Réprouvés, nous devrions pouvoir couvrir notre fuite et prendre un peu d\'avance.$B$BLe seul moyen d\'y arriver est de rendre Koroth furieux. Tuer ses serviteurs ne sera pas suffisant. Nous devons lui voler son bien le plus cher, une bannière en peau de tigre.', '', '', '', '', '', '', '', '', '', 'Retournez voir Liam Grisetête à la Diligence accidentée.', 0),
(24473, 'frFR', 'Le confinement de Courbenclume', 'Parlez à Jona Troupefer à Courbenclume.', 'Votre aide est très appréciée ici, mais on pourrait avoir encore plus besoin de vous autre part.$b$bÀ cause de l’attaque des troggs, et du tremblement de terre que nous venons de subir, nous avons interdit aux civils de sortir de Courbenclume, la ville située au sommet de la colline au nord-ouest.$b$bJona, ma femme, se trouve dans la ville. Allez lui parler. Je suis certain qu’elle aura besoin d’$gun gaillard tel:une gaillarde telle; que vous.', '', '', '', '', '', '', '', '', '', '', 0),
(24474, 'frFR', 'Priorité à l\'essentiel : on va avoir besoin de bière', 'Trouvez un Fût de brune de Marteau-tempête, un Fût de bière ambrée de Theramore et un Fût de Gnomenbrau.', 'Je ne comprends pas comment quoi que ce soit pourrait avancer dans cette ville si on n’a pas de bière ! Les caves de Courbenclume sont presque à sec.$b$bHeureusement pour nous tous, j’ai prévu des fûts de secours pour les situations telles que celle-ci. Vous trouverez des fûts de brune Marteau-tempête et d’ambrée de Theramore le long de la limite nord de la vallée, à l’ouest de Courbenclume. Et juste à l’est d’où nous sommes, vous trouverez une réserve de ma bière préférée, la Gnomenbrau.', '', '', '', '', '', '', '', '', '', 'Retournez voir Jona Ironstock à Courbenclume.', 0),
(24475, 'frFR', 'Couvertures et nourriture', 'Obtenez 3 Cuissots de sanglier et 4 Peaux de loup rapiécées.', 'Si les autorités maintiennent la fermeture de la ville pour longtemps, on va avoir besoin de nourriture et de couvertures pour tenir chaud aux enfants. Ça vous dérangerait d’aller voir dehors et de rapporter un peu des deux ?$b$bCertains sangliers des alentours ont l’air assez replets, et la fourrure de jeune loup fait de parfaites couvertures.$b$bVous trouverez ces animaux où que vous alliez dans les Frigères.', '', '', '', '', '', '', '', '', '', 'Retournez voir Jona Ironstock à Courbenclume.', 0),
(24477, 'frFR', 'Les artéfacts nains', 'Récupérer 5 Artéfacts nains oubliés.', '$n, mon ange ! Ça vous intéresse, l’archéologie ?$b$bC’est l’occasion rêvée pour vous y mettre. Les secousses du tremblement de terre d’aujourd’hui ont mis à jour tout un tas d’artéfacts autour de notre campement. Allez voir le long de la limite nord de la vallée et vous devriez trouver toutes sortes de trésors. Rapportez-m’en quelques-uns, et peut-être que nous pourrons les examiner ensemble.$b$bVous avez compris ? En route, alors !', '', '', '', '', '', '', '', '', '', 'Retournez voir Grundel Harkin à Courbenclume.', 0),
(24478, 'frFR', 'L\'Épreuve du Givre', 'Terminez l’Épreuve du Givre en rassemblant 20 Essences de glace sans qu’aucune Brûlure du givre ne vous touche.', 'Vous savez, certains de mes apprentis disent que je suis quelqu’un de froid. Mais je réponds toujours que la température de mon corps ne doit pas interférer avec l’apprentissage des connaissances.$B$BPour accéder à l’Épreuve du Givre, il faut que vous ouvriez un portail en touchant le cristal de givre. Une fois là-bas, votre objectif est très simple : rassembler des sortes de petits orbes de glace flottants.$B$BPour corser les choses, des brûlures du givre tourbillonnantes pourront ralentir votre progression, en quelque sorte. Si vous voulez un peu de fantaisie, vous pouvez utiliser les pièges à runes pour les éviter quand elles passent près de vous. La classe, hein ?', '', 'Épreuve du Givre terminée', '', '', '', '', '', '', '', 'Allez voir l’Image de l’archimage Xylem à l’Épreuve du Givre.', 0),
(24479, 'frFR', 'L\'Épreuve de l\'Ombre', 'Terminez l’Épreuve de l’Ombre en attirant 20 Âmes éplorées dans les runes d’ombre sans vous faire toucher.', 'Ne nous limitons pas au répertoire magique du mage. Moi, par exemple, j’ai décidé de ne pas faire comme les autres. La nécromancie, c’est tellement plus amusant !$B$BTouchez le cristal ombreux pour ouvrir un portail et accéder à l’Épreuve de l’Ombre. Une fois là-bas, déplacez l’autel quand vous serez $gprêt:prête; à commencer.$B$BDes âmes éplorées vont se lancer à votre poursuite… votre objectif sera simplement de les attirer dans les pièges. Et faites attention à ne pas les toucher.', '', 'Épreuve de l’Ombre terminée', '', '', '', '', '', '', '', 'Allez voir l’Image de l’archimage Xylem à l’Épreuve de l’Ombre.', 0),
(24483, 'frFR', 'Val-Tempête', 'Parlez à Gwen Armstead à Val-Tempête.', 'Les conducteurs de nos voitures ont reçu l\'ordre de se regrouper à Val-Tempête, un village de pêcheurs. Nos éclaireurs nous ont indiqué que nous y trouverons gîte et couvert.$B$BRetrouvez Gwen Armstead là-bas, elle a pour mission de s\'occuper de nos villageois.', '', '', '', '', '', '', '', '', '', '', 0),
(24484, 'frFR', 'Contrôle des nuisibles', 'Tuer 6 Glisseuses vilepontes à Val-Tempête.', 'Eh bien, qui l\'eût cru, $n ? Après tout ça, Val-Tempête est resté quasiment intact.$B$BLes Réprouvés continuent malheureusement leurs incursions à l\'intérieur des terres, mais nous devrions pouvoir nous reposer une nuit ou deux.$B$BL\'autre moitié du village est envahie par les araignées, donc j\'ai demandé aux habitants d\'en rester éloignés.$B$BPeut-être pourriez-vous nous aider à chasser ces bêtes ? Je suis certaine que nos concitoyens blessés dormiraient plus tranquillement s\'ils savaient que quelqu\'un s\'occupe de ces monstres à huit pattes.', '', '', '', '', '', '', '', '', '', 'Retournez voir Gwen Armstead à Val-Tempête en Gilnéas.', 0),
(24486, 'frFR', 'Battre le fer tant qu\'il est chaud', 'Obtenir 5 Artéfacts mâcherocs inestimables des Charognards mâcherocs.', 'Le village trogg situé au sud-ouest a subi les mêmes dégâts que le nôtre. On peut donc en déduire logiquement que chez eux aussi, les artéfacts jaillissent du sol !$b$bMalheureusement, on dirait que les charognards troggs sont déjà passés par là et en ont ramassé la majeure partie. Vous tenteriez bien quelque chose pour récupérer ces objets, non ? Croyez-le ou pas, la connaissance des troggs pourrait aussi nous en apprendre beaucoup sur les nains !', '', '', '', '', '', '', '', '', '', 'Retournez voir Grundel Harkin à Courbenclume.', 0),
(24487, 'frFR', 'Blanchebarbe a besoin de vous', 'Faites votre rapport à Grelin Blanchebarbe à son campement, dans la Vallée des Frigères.', 'Vous nous avez rendu de fiers services ici, mais je crains de devoir me séparer de vous.$b$bGrelin Blanchebarbe, un bon ami à moi, m’a laissé entendre qu’il aurait bien besoin de renforts près des camps des trolls, au sud-ouest. Suivez la route de l’ouest et vous ne tarderez pas à le voir.$b$bPortez-vous bien, $n. Les troggs sont peut-être dangereux, mais les trolls le sont encore plus.', '', '', '', '', '', '', '', '', '', '', 0),
(24488, 'frFR', 'Remplacements', 'Collectez 6 Pièces de rechange.', 'Mes joueurs sont tous sur le banc des blessés ! Nos déchiqueteurs sont H.S. ! Et l\'arbitre est sur le point de lancer le match !$B$BNous sommes dans la panade. J\'ai besoin de vous, $n !!!$B$BRemettons l\'un de ces déchiqueteurs en état de marche. Vous trouverez des pièces de rechange un peu partout dans le port Baille-Fonds. Tout Kezanien qui se respecte sera heureux que vous les preniez si cela peut donner la moindre chance aux Boucaniers.$B$BOn va montrer à ces vauriens de Requins de Gentepression comment on joue au footbombe.', '', '', '', '', '', '', '', '', '', 'Retournez voir l\'Entraîneur Sainturrébreutel au Parc des Princes marchands, sur Kezan.', 0),
(24489, 'frFR', 'Écouter aux portes des trolls', 'Tenez-vous près d’une Devineresse crins-de-givre dans chacun des camps crins-de-givre et écoutez ce qu’elle a à dire.', 'Je suis très mauvais en physionomie trolle. Impossible de lire l’expression de leurs visages. Cela dit, je n’ai pas l’impression qu’ils soient en colère. Ils semblent plutôt inquiets… et peut-être un peu effrayés.$b$bQuelque chose a dû arriver, mais cela nous échappe pour le moment, $n. Je propose que nous fassions une petite enquête avant de tuer tous les trolls à la ronde.$b$bIl y a trois camps trolls dans la région : l’un au sud-est, l’autre au sud-ouest et le dernier droit vers l’ouest. Dans chacun de ces camps se trouve une devineresse. Voyez si vous pouvez vous en approcher suffisamment pour écouter ce qu’elles ont à dire.', '', 'Devineresse Shi\'kala écoutée', 'Devineresse Rikkari écoutée', 'Devineresse Mirim\'koa écoutée', '', '', '', '', '', 'Retournez auprès de l’Apprenti Soren au Camp de Blanchebarbe.', 0),
(24490, 'frFR', 'Un voyage à Forgefer', 'Rendez-vous auprès de Mano Engrenaressort, dans la Vallée des Frigères.', 'La présence d’un élémentaire de feu dans les Frigères est un grave problème. Le tremblement de terre n’a pas seulement secoué les troggs… il a aussi secoué la terre à un tel point qu’une fissure vers le plan élémentaire s’est créée. Nous devrions en informer Forgefer.$b$bVous n’auriez pas envie de faire un peu de marche, par hasard ? Ne vous inquiétez pas, je suis sûr que vous vous en sortirez. Allez parler à Mano Engrenaressort, près du tunnel à l\'extrémité est de la vallée. Il vous indiquera la marche à suivre.', '', '', '', '', '', '', '', '', '', '', 0),
(24491, 'frFR', 'Suivez ce gyrocoptère !', 'Allez voir Milo Élangrenage, près de Courbenclume.', 'Vous… vous… vous avez vu ça ? Vous avez vu comment la caverne s’est effondrée ? Encore heureux que vous soyez $garrivé:arrivée; maintenant, et pas une minute plus tôt.$b$bBien que cet effondrement me facilite la surveillance de l’entrée du tunnel, j’imagine que ça va rendre votre voyage à Kharanos moins évident.$b$bHé, attendez, j’ai une idée ! Les pilotes de Gnomeregan ont un trajet aérien qui passe tout près d’ici. Je vais leur envoyer un signal pour qu’ils viennent vous aider. Je pense que l’atterrissage se fait à Courbenclume.', '', '', '', '', '', '', '', '', '', '', 0),
(24492, 'frFR', 'Faites vos valises', 'Obtenez une Bouteille de bière des Frigères, une Cape rapiécée en peau de loup et un Reste de viande de sanglier.', 'La masse maximale autorisée de mon gyro n’admet qu’$gun passager:une passagère:r; $r. On dirait que c’est votre jour de chance, $n ! La naine Jona m’a dit que la plupart de vos effets personnels avaient été transférés dans Courbenclume. Rassemblez vos effets, expédiez les affaires courantes et revenez me voir quand vous serez $gprêt:prête; à décoller.', '', '', '', '', '', '', '', '', '', 'Retournez voir Milo Élangrenage dans la Vallée des Frigères.', 0),
(24493, 'frFR', 'Ne nous oubliez pas', 'Rendez-vous auprès de Tharek Noirepierre, à Kharanos.', 'Vous nous quittez ? Pensez à faire le plein de provisions pour le voyage, avant de partir.$b$bMais surtout, n’oubliez pas de parler à Tharek Noirepierre, une fois à Kharanos. Dites-lui ce qui se passe ici, dans les Frigères, et demandez-lui de nous envoyer de l’aide. J’espère qu’il pourra nous sortir de cette situation.', '', '', '', '', '', '', '', '', '', '', 0),
(24494, 'frFR', 'Rune investie', 'Lisez la Rune investie, puis parlez à Teo Martel-tempête, à Courbenclume.', '$n, on m’a donné cette rune pour que je vous la donne à mon tour. Prenez le temps de la lire, à l’occasion. Je pense qu’elle vient de Teo, le maître des chamans. Jetez-y un œil, puis allez lui parler à Courbenclume.', '', '', '', '', '', '', '', '', '', 'Lisez la Rune investie, puis parlez à Teo Martel-tempête, à Courbenclume.', 0),
(24495, 'frFR', 'Les fragments du passé', 'Retrouvez 6 Vieilles pages de journal.', 'J\'ai trouvé le journal d\'un dénommé Bradshaw. Malheureusement, il manque de nombreuses pages, surtout parmi les dernières.$B$BSi vous retrouvez suffisamment de ces pages, je pourrai reconstituer ce qui s\'est passé ici après le déclenchement de la Malédiction.$B$BQui sait... peut-être que les habitants de cette ville ont réussi à s\'en sortir. Peut-être y a-t-il des survivants, quelque part.$B$BPeut-être que mon père est toujours en vie.', '', '', '', '', '', '', '', '', '', 'Retournez voir Lorna Crowley à Val-Tempête, en Gilnéas.', 0),
(24496, 'frFR', 'Rune des Arcanes', 'Lisez la Rune des Arcanes, puis parlez à Teegli Merrowith, dans la Vallée des Frigères.', '$n, on m’a donné cette rune pour que je vous la donne à mon tour. Prenez le temps de la lire, à l’occasion. Je pense qu’elle vient de Teegli, le maître des mages. Jetez-y un œil, puis allez lui parler à Courbenclume.', '', '', '', '', '', '', '', '', '', 'Lisez la Rune des Arcanes, puis parlez à Teegli Merrowith, dans la Vallée des Frigères.', 0),
(24497, 'frFR', 'Prêtres au volant, on gagne du temps', 'Demandez à un Prêtre volant de vous conduire à Valormok en avion. Les Prêtres volants se trouvent dans la partie est du Havre Baille-Fonds.', 'Nous venons de recevoir des nouvelles en provenance de Valormok. Nos coursiers du vent ne peuvent plus s’y rendre par le trajet habituel car les snipers de Talrendis les abattent systématiquement. Mais nous ne pouvons pas renoncer à Valormok si nous voulons conserver une voie sûre jusqu’à Orneval : nous allons donc procéder autrement.$B$BLes prêtres volants nous ont gracieusement proposé de parachuter quelques hommes à l’intérieur de Valormok, hors de portée des snipers. Donc rendez-vous dans la zone militaire et demandez à un prêtre de vous déposer à Valormok en avion. De cette façon, vous y arriverez en un seul morceau, et une fois là-bas, j’espère que vous pourrez sécuriser à nouveau le trajet de nos coursiers du vent.', '', '', '', '', '', '', '', '', '', '', 0),
(24501, 'frFR', 'La reine des enquiquineuses', 'Tuez Rygna dans le Repaire de Rygna.', 'Les araignées continuent d\'affluer en nombre alarmant, $n. Il va falloir vous rendre dans leur repaire et tuer la mère pondeuse.$B$BNous avons repéré cette araignée géante, Rygna, en bordure de la forêt Noire, dans une zone infestée de toiles d\'araignées. C\'est une tâche dangereuse, mais nous comptons sur vous.', '', '', '', '', '', 'Retrouvez-la dans cette grotte et revenez en vie. Nous comptons sur vous.', 'Rygna', '', '', 'Retournez voir Gwen Armstead à Val-Tempête en Gilnéas.', 0),
(24502, 'frFR', 'Une brutalité nécessaire', 'Grimpez dans le Boucanier de Baille-Fonds, puis lancez la bomballe sur 8 Requins de Gentepression.', 'Tout repose sur les épaules de notre dernier déchiqueteur. Pendant que tout le monde avait le dos tourné, je l\'ai chargé avec des bomballes... modifiées, pourrait-on dire.$B$B$gGamin:Gamine;, montez dans ce déchiqueteur et faites-leur vivre un enfer !', '', 'Boucanier de Baille-Fonds', 'Requins de Gentepression touchés par la bomballe', '', '', '', '', '', '', '', 0),
(24503, 'frFR', 'Et c\'est le buuuuuuuuuuut !', 'Marquez le but de la victoire en lançant la bomballe entre les cheminées derrière le but adverse.', 'Tout est entre vos mains, $ggamin:gamine;. Vous avez pulvérisé les Requins de Gentepression, donc tout ce qu\'il reste à faire, c\'est de marquer le but de la victoire.$B$BBon, rien qu\'entre vous et moi, il faut qu\'on fasse ça dans les règles de l\'art. Je ne veux pas que vous marquiez juste un but... je veux que vous lanciez la bomballe si loin qu\'elle vole entre les deux cheminées derrière le but ! J\'ai modifié le ballon pour vous donner la puissance supplémentaire nécessaire pour arriver à nos fins.$B$BFaites-moi rêver !', '', 'Bomballe lancée entre les cheminées', '', '', '', '', '', '', '', 'Retournez voir l’Entraîneur Sainturrébreutel au Parc des Princes marchands, sur Kezan.', 0),
(24504, 'frFR', 'Nettoyez la Haute-route', 'Tuez 3 Éclaireurs de la Haute-route.', 'Par ici, $c ! Je vois que vous avez découvert la haute-route.$b$bL’Alliance croit pouvoir couper nos lignes de communication avec les Serres-Rocheuses, mais ils oublient que nous autres, les taurens, nous chassons sur ces terres depuis des générations. Nous connaissons les moindres replis de ces collines et toutes les pistes de gibier d’ici aux Mille pointes.$b$bMais pour que ces chemins restent ouverts, nous devons empêcher les humains de les cartographier.$b$bPatrouillez sur la piste vers l’est et tuez tous les éclaireurs de la haute-route que vous rencontrerez. Ensuite, parlez à Tunawa Mortebrise, juste en haut de la piste.', '', '', '', '', '', '', '', '', '', 'Parlez à Tunawa Mortebrise sur la Haute-route, dans les Tarides du Sud.', 0),
(24505, 'frFR', 'Un petit village d\'irréductibles taurens', 'Parlez à Onatay à la Colline du Chasseur, dans les Tarides du Sud.', 'Le Séjour de l’honneur est peut-être tombé, mais son esprit vit toujours. Même maintenant, d’irréductibles survivants tiennent toujours tête à l’ennemi dans un endroit appelé la « colline du Chasseur ».$b$bContinuez à suivre la haute-route et vous trouverez ce camp juste un peu plus haut. Parlez à Onatay quand vous y serez et dites-lui que pour le moment, la route est sûre.', '', '', '', '', '', '', '', '', '', 'Parlez à Onatay sur la Colline du Chasseur, dans les Tarides du Sud.', 0),
(24512, 'frFR', 'La rédemption du guerrier', 'Récupérez 5 caisses d\'Armes confisquées au Séjour de l\'Honneur et équipez-en 5 Prisonniers des Serres-Rocheuses. Utilisez les cordes à proximité pour pénétrer et sortir discrètement du camp de l\'Alliance.', 'Ceux qui se sont rendus lors de la chute du Séjour de l’honneur ne sont plus dignes de la Horde, $c, mais je n’ai pas encore perdu tout espoir pour eux. La prison en contrebas n’est que légèrement gardée. Nous allons donner à ces prisonniers une dernière chance de mourir avec honneur.$b$bJ’ai installé des cordes pour nous permettre de descendre et remonter rapidement la montagne. Descendez dans la prison, mettez la main sur les armes confisquées et réarmez les prisonniers incarcérés dans la tour.$b$bEt surtout, restez près de la tour, $n ! Nous ne sommes pas encore prêts pour un assaut en règle de toute la base.', '', 'Prisonnier des Serres-Rocheuses armé', '', '', '', '', '', '', '', 'Retournez voir Holgom à la Haute-route, dans les Tarides du Sud.', 0),
(24513, 'frFR', 'Œil pour œil', 'Tuez le Capitaine Peake et remettez ses yeux à Oltarg.', 'Qui va là ? Le bruit de vos pas ne ressemble pas au piétinement paresseux des gardes.$b$b$gUn:Une:c; $c, vous dites ? Vous êtes toujours en un seul morceau, au moins ? Pour moi, c’est fini, $gmon vieux:ma vieille;. J’ai perdu la vue et je ne suis plus apte au combat.$b$bJ’ai osé émettre une réflexion alors que le capitaine Peake était en train de passer un des prisonniers à tabac. En récompense, il m’a donné des coups de pieds dans la tête, encore et encore, jusqu’à ce que j’en perde la vue, $r.$b$bVous trouverez le capitaine Peake au sommet de sa tour. Si vous avez soif de justice, rapportez-moi ses yeux.$b$bEt s’il ne s\'en sépare pas de son plein gré… tant pis pour lui.', '', '', '', '', '', '', '', '', '', 'Remettez les Globes oculaires du capitaine Peake à Oltarg au Séjour de l\'Honneur, dans les Tarides du Sud.', 0),
(24514, 'frFR', 'Faire la peau aux raptors', 'Écorchez des Coureurs ou des Faucheurs dent-d’effroi et récoltez 8 de leurs peaux.', 'Nous sommes en état de siège, ici, $c, et à cause de ce précipice et du harcèlement incessant de l’Alliance, nos réserves s’amenuisent. Mais nous faisons avec les moyens du bord, comme les taurens l’ont toujours fait.$b$bÀ défaut d’avoir une forge, un tanneur expérimenté peut renforcer et réparer nos armures endommagées avec des peaux de bonne qualité.$b$bLe territoire de chasse des raptors dent-d’effroi se trouve en contrebas. Ce sont des durs à cuire, en partie à cause de l’épaisseur de leur peau. Faites-la-leur, $n, et rapportez-la-moi !', '', '', '', '', '', '', '', '', '', 'Livrez les peaux à Onatay sur la Colline du Chasseur, dans les Tarides du Sud.', 0),
(24515, 'frFR', 'Des signaux dans le ciel', 'Atteignez le Camp Una’fe, dans le Lacis des Tarides du Sud et parlez à Makaba Sabot-plat.', 'Regardez au sud-est. Vous voyez la fumée qui monte du camp Una’fe ?$b$bIl n’y a pas dix minutes, j’ai vu de grosses bouffées de fumée blanche s’élever dans le ciel au-dessus de ce camp. C’est un ancien signal utilisé par mon village pour coordonner la chasse sur de grandes distances, mais cette fois, c’était un signal de détresse.$b$b$n, Makaba, mon frère, s’est enfoncé dans cette jungle corrompue. Je vous en prie, allez voir s’il ne lui est arrivé aucun mal.$b$bIl n’y a que très peu de chemins dans cette jungle. Vous devrez vous repérer aux tentes disséminées dans la nature.', '', '', '', '', '', '', '', '', '', 'Parlez à Makaba Sabot-plat au Camp Una\'fe, dans les Tarides du Sud.', 0),
(24517, 'frFR', 'Insufflez-leur la peur', 'Tuez 8 Fantassins du Séjour de l’honneur et 1 Officier du Séjour de l’honneur.', 'Vous voyez cette piste en contrebas, $n ? C’est MA piste. Alors si ces chiens de l’Alliance veulent l’utiliser, ils auront intérêt à surveiller leurs arrières.$b$bL’heure du péage a sonné ! Tuez les fantassins du Séjour de l’honneur et voyez si vous pouvez les renvoyer en rampant jusque chez eux.$b$bVeillez à tuer au moins un des officiers qui patrouillent sur la route. Ils doivent savoir que personne n’est en sûreté.', '', '', '', '', '', '', '', '', '', 'Retournez voir Kilrok Marteltripe sur la Colline du Chasseur, dans les Tarides du Sud.', 0),
(24518, 'frFR', 'La route basse', 'Remettez le Plan de route à Kilrok Marteltripe à la Colline du Chasseur, dans les Tarides du Sud.', 'Ce rouleau de feuillets a été trouvé dans un porte-documents en cuir, caché sous les vêtements de l’officier.$b$bDes plans de bataille de la région montrent que le Séjour de l’honneur est relié à Theramore par ce qui semble être une large chaussée, encore en pointillés, traversant toutes les Tarides. On dirait que l’Alliance a l’intention de construire une route qui irait de la côte jusqu’au beau milieu de Kalimdor !$b$bKilrok Marteltripe sera certainement intéressé par ces plans.', '', '', '', '', '', '', '', '', '', 'Livrez le Plan de route à Kilrok Marteltripe sur la Colline du Chasseur, dans les Tarides du Sud.', 0),
(24519, 'frFR', 'Mettre des bâtons dans les roues au cartographe', 'Trouvez et tuez le cartographe Henry Zykes.', 'Ces cartes ont toutes été dessinées par la même main experte. J’ai vu un cartographe humain faire des allées et venues sur la route entre le fort et la jungle, à l’est.$b$bNous pouvons réduire leurs plans à néant en zigouillant ce cartographe pour montrer l’exemple, $n.$b$b<Kilrok montre la signature figurant au bas des cartes.>$b$bQu’est-ce qu’il est marqué ? « Zykes ? » Même les noms humains sonnent creux et faible. Tuez-le.', '', '', '', '', '', 'Explorez la route au sud du Séjour de l\'Honneur.', 'Henry Zykes', '', '', 'Retournez voir Kilrok Marteltripe sur la Colline du Chasseur, dans les Tarides du Sud.', 0),
(24520, 'frFR', 'Une bonne nouvelle pour Chipie', 'Parlez à Chipie Serrelavis au Quartier général de la SCK, sur Kezan.', 'J\'aurais bien fêté ça avec vous, $n, mais on dirait bien que le dragon n\'y est pas allé d\'aile morte sur ce bon vieux mont Kajaro. Je... Euh, je crois que je vais rassembler mes affaires et prendre le premier bateau qui quittera l\'île !$B$BPeu importe, vous devriez retourner au quartier général et annoncer à Chipie que vous avez remporté le titre de footbombe pour nous. Je suis sûr que cette histoire de dragon et du mont Kajaro l\'intéressera aussi.$B$BBonne chance !', '', '', '', '', '', '', '', '', '', '', 0),
(24523, 'frFR', 'Le totem des Crin-sauvage', 'Récupérez 4 Dents de loup alpha des prairies sur des Loups alpha des prairies.', 'Il ne reste plus qu’un puits à purifier, celui qui porte le nom du clan Crin-sauvage. Pour qu’il retrouve sa pureté, la terre doit offrir les dents d’un prédateur féroce, le loup alpha des prairies. Trouvez les alphas, au nord, et revenez me voir lorsque votre chasse sera terminée.$B$BLes alphas rôdent souvent autour de la base de notre grande cité des Pitons-du-Tonnerre.', '', '', '', '', '', '', '', '', '', 'Retournez voir Una Crin-sauvage au Camp Frôle-soleil en Mulgore.', 0),
(24524, 'frFR', 'La purification de Crin-sauvage', 'Utiliser le Totem de purification de Crin-sauvage au puits Crin-sauvage.', 'Votre purification des puits Sabot-d\'hiver et Corne-tonnerre est un objet de discussion et de fierté parmi les esprits, jeune $n. Le totem de Crin-sauvage est construit et le devoir vous appelle, encore une fois.$B$BLe puits Crin-sauvage se trouve au nord des Pitons-du-Tonnerre. Pratiquez-y le rituel ! Débarrassez le pays du poison des Totems-Sinistres. Que l\'eau claire coule de nouveau !', 'Purifier le puits Crin-sauvage', '', '', '', '', '', '', '', '', 'Retournez voir Una Crin-sauvage au Camp Frôle-soleil.', 0),
(24525, 'frFR', 'Tenir les chiens à distance', 'Tuez 6 Charognards Jappecroc.', 'Tous ceux qui ont fui Taurajo n’ont pas réussi à atteindre Una’fe, $n. Certains sont morts de leurs blessures en cours de route et d’autres ont été achevés par des hurans opportunistes.$b$bLa douloureuse tâche de trouver et de rassembler les cadavres me revient, mais vous pouvez m’aider.$b$bDes charognards jappecroc rôdent sur les terres au sud en déchiquetant les corps, en déchirant leurs entrailles et en emportant des membres dans leur gueule. Je vous en prie, réduisez leur population pour que je puisse effectuer les rituels funéraires dignement.', '', '', '', '', '', '', '', '', '', 'Retournez voir Makaba Sabot-plat au Camp Una\'fe, dans les Tarides du Sud.', 0),
(24526, 'frFR', 'Remplir le grimoire', 'Atteignez le Niveau 3 pour apprendre la Nova de givre. Réussissez à la lancer 2 fois sur les Mannequins d’entraînement, à l’entrée de Courbenclume.', 'Excellent ! Commençons, voulez-vous ?$b$bÀ mesure que vous gagnerez en puissance, votre lien aux arcanes se renforcera et vous aurez accès à de nouveaux sorts et compétences.\n\nAllez donc accumuler de l’expérience, vous comprendrez mieux. Revenez me voir quand vous aurez découvert quelque chose, et faites-moi la démonstration de votre savoir nouvellement acquis sur ces mannequins d’entraînement.', '', 'S’exercer à la Nova de givre', '', '', '', '', '', '', '', 'Retournez auprès de Teegli Merrowith, à Courbenclume.', 0),
(24527, 'frFR', 'Votre voie commence ici', 'Atteignez le Niveau 3 pour apprendre la Frappe primordiale, puis utilisez-la 2 fois sur un Mannequin d’entraînement à l’entrée de Courbenclume.', 'Excellent ! Commençons, à présent.$b$bEn progressant au cours de votre périple, vous découvrirez les anciens secrets des chamans.\n\nLa première de ces compétences est celle de la frappe primordiale. Lorsque vous invoquerez les esprits primaux, ils fortifieront votre bras pour que vous donniez un coup puissant.$b$bPratique, n’est-ce pas ?', '', 'S’exercer à la Frappe primordiale', '', '', '', '', '', '', '', 'Retournez auprès de Teo Martel-tempête, à Courbenclume.', 0),
(24528, 'frFR', 'Le pouvoir de la Lumière', 'Atteignez le Niveau 3 pour apprendre le Sceau d’autorité, puis utilisez-le sur vous-même et frappez l’un des Mannequins d’entraînement à l’entrée de Courbenclume.', 'Z’êtes $gprêt:prête; à démarrer ? Génial ! On est content de vous avoir avec nous.$b$bEn gagnant en puissance, vous vous rapprochez de la lumière et vous découvrez de nouvelles techniques. Allez, gagnez de l’expérience, et revenez me montrer ce que vous avez appris.', '', 'Utiliser Sceau d’autorité et frapper un Mannequin', '', '', '', '', '', '', '', 'Retournez auprès de Bromos Grummneur, à Courbenclume.', 0),
(24529, 'frFR', 'De mal en pis', 'Libérez 5 Réfugiés de Taurajo incarcérés et tuez n’importe quelle combinaison de 8 Tisseurs d’épines et de Garde-lames dos-hirsutes.', 'Lorsque les réfugiés ont fui au nord de Taurajo, certains furent séparés des autres dans les ténèbres grandissantes. Nombre d\'entre eux ont été faits prisonniers par des hurans dos-hirsutes ayant établi des campements au sud et au sud-ouest d\'ici.$B$BJe ne sais pas exactement ce que ces hurans espéraient en capturant nos réfugiés. Tout ce qu\'ils ont provoqué, c\'est ma colère. Et tout ce qu\'ils récolteront sera ma vengeance.$B$BSauvez mes frères et sœurs piégés et tuez leurs ravisseurs pour envoyer un message aux hurans.', '', 'Réfugiés de Taurajo libérés de leur cage', 'Hurans dos-hirsute tués', '', '', '', '', '', '', 'Retournez voir Makaba Sabot-plat au Camp Una\'fe, dans les Tarides du Sud.', 0),
(24530, 'frFR', 'La vie de chasseur', 'Atteignez le Niveau 3 pour apprendre le Tir assuré, puis utilisez-le 5 fois sur des Mannequins d’entraînement, à l’entrée de Courbenclume.', 'La vie du chasseur est réglée par de très fortes traditions, vous savez. Pister de dangereuses bêtes en terrain hostile. Boire un coup. Voyager au grand air, le fusil en bandoulière. Boire un coup. Survivre grâce à sa jugeote et à son courage… et aussi en buvant des coups !$b$bMais avant de passer aux choses amusantes, vous allez devoir apprendre le b.a.-ba.\n\nGagnez donc de l’expérience, et vous apprendrez à faire de plus en plus de choses. Ensuite, hop ! On lève le coude.', '', 'S’exercer au Tir assuré', '', '', '', '', '', '', '', 'Retournez auprès de Thorgas Grimson, à Courbenclume.', 0),
(24531, 'frFR', 'Être prêt pour la bataille', 'Atteignez le Niveau 3 pour apprendre la Charge, puis utilisez-la sur les Mannequins d’entraînement, à l’entrée de Courbenclume.', 'Leçon numéro un. À part votre épée et votre bouclier, quel est l’outil le plus important que vous ayez dans votre arsenal ?$b$b<Thran attend votre réponse.>$b$bOh, laissez tomber, je vais répondre pour vous. C’est votre expérience. \n\nEn accumulant de l’expérience, vous découvrirez de nouvelles techniques, et vous deviendrez de plus en plus redoutable.\n\nAllez, gagnez de l’expérience et apprenez quelque chose de nouveau, puis revenez me voir et faites-moi une démonstration.', '', 'S’exercer à la Charge', '', '', '', '', '', '', '', 'Retournez voir Thran Khorman à Courbenclume.', 0),
(24532, 'frFR', 'Éviscérer l’ennemi', 'Atteignez le Niveau 3 pour apprendre l’Éviscération, puis utilisez 3 fois cette technique sur les Mannequin d’entraînement à l’entrée de Courbenclume.', 'En gagnant en expérience, on se rend compte que de nouvelles compétences s’ouvrent à nous. \n\nNotamment, vous apprendrez à utiliser des manœuvres de combat pour affaiblir un adversaire, avant de lui asséner une technique dévastatrice.\n\nPartez donc engranger de l’expérience, apprenez à utiliser cette tactique, puis essayez-la sur nos mannequins d’entraînement.', '', 'S’exercer à l’Éviscération', '', '', '', '', '', '', '', 'Retournez voir Solm Hargrin à Courbenclume.', 0),
(24533, 'frFR', 'Des mots de pouvoir', 'Atteignez le Niveau 3 pour apprendre le Mot de l’ombre : Douleur, puis lancez-le 5 fois sur des Mannequins d’entraînement.', 'Alors, si vous voulez VRAIMENT devenir quelqu’un de spécial, c’est à moi qu’il faut venir parler. Un prêtre n’est rien sans ses sorts, et comment est-ce qu’on apprend de nouveaux sorts ?\n\nEn gagnant de l’expérience, pardi. Allez, partez à l’aventure, gagnez en puissance, et revenez me montrer ce que vous avez appris.', '', 'S’exercer au mot de l’ombre : Douleur', '', '', '', '', '', '', '', 'Retournez auprès de Branstock Khalder, à Courbenclume.', 0),
(24534, 'frFR', 'Jouer leur jeu avec nos cartes', 'Sonnez le Cor du défi au Cercle de défi dos-hirsute et battez Hurecroc en combat singulier.', 'Les hurans nous attaquent car ils perçoivent notre faiblesse. La force est la seule chose qu’ils comprennent, donc nous allons leur montrer notre force.$b$b<Makaba extirpe un grand cor de sa besace.>$b$bC’est manifestement de l’artisanat grossier, mais ça fera l’affaire. Les chefs dos-hirsutes utilisent de tels cors pour se défier les uns les autres.$b$b$n, je veux que vous défiiez Hurecroc, le champion dos-hirsute, en combat singulier. Écrasez-le devant ses hommes. Vous devez descendre dans le cercle de défi dos-hirsute, au sud d’ici, et y sonner de ce cor.', '', '', '', '', '', 'Sonnez le Cor du défi pour commencer le combat contre Hurecroc.', 'Hurecroc', '', '', 'Retournez voir Makaba Sabot-plat au Camp Una\'fe, dans les Tarides du Sud.', 0),
(24539, 'frFR', 'L\'attaque des plantes', 'Secourez 5 Réfugiés de Taurajo en tuant les Lacis avides qui les ligotent.', 'Ce camp a été construit à la lisière de la jungle et il est déjà submergé par la végétation. Quelque chose d’anormal est en train de se passer ici !$b$bJ’ai déjà fait l’erreur d’envoyer dans la jungle quelques-uns des réfugiés les plus en forme pour qu’ils ramassent des noix et des baies. Ceux qui sont revenus m’ont parlé de plantes qui les attrapaient aux chevilles ou qui les soulevaient carrément de terre. Je m’inquiète pour ceux qui ne sont pas encore ressortis de la jungle.$b$bJe vous en prie, $C, secourez les réfugiés emprisonnés par la végétation du lacis autour du camp.', '', 'Réfugiés de Taurajo sauvés du Lacis', '', '', '', '', '', '', '', 'Retournez voir Lane Hautes-herbes au Camp Una\'fe, dans les Tarides du Sud.', 0),
(24540, 'frFR', 'La danse de guerre', 'Triomphez d’Orno Totem-Sinistre à la Passe des Serres-Rocheuses.', 'Certains nous voient comme de doux géants, ou comme de nobles sauvages. Ils ne nous ont jamais vus nous battre entre nous… contre les traîtres qui vivent parmi nous.$B$BLes Totems-Sinistres ont été condamnés à l’exil, ce qui était miséricordieux. Ils ont ravagé leurs propres terres pour nous nuire. Ils ne seront plus tolérés en Mulgore.$B$BJ’ai envoyé nos guerriers les chasser vers le nord, à travers la passe des Serres-Rocheuses. Vous vous êtes bien $gbattu:battue; contre les Totems-Sinistres, $n. Je vais vous demander de continuer le combat. Allez, et aidez-nous à porter ce dernier coup.', '', '', '', '', '', 'Vainquez-le !', 'Orno Totem-Sinistre', '', '', 'Retournez voir Baine Sabot-de-Sang aux Pitons-du-Tonnerre.', 0),
(24542, 'frFR', 'Une curieuse floraison', 'Cueillez 10 Boutons de fleur insolites sur les Fleurs en bourgeon, dans le Lacis.', 'Le grand archidruide Naralex est récemment apparu ici, dans les Tarides. Soit il est derrière tout ça, soit il essaie de résoudre le problème. Quoi qu\'il en soit, vous devriez lui parler avant que cette jungle n\'engloutisse le monde entier ! Il est dans un petit campement tauren, au sud-est.$B$BEn chemin, vous devriez ramasser des échantillons de plantes qu\'il pourra étudier. Les boutons de fleur les plus jeunes lui en apprendront beaucoup sur les récents changements dans la jungle.', '', '', '', '', '', '', '', '', '', 'Trouvez Naralex au milieu du Lacis, dans les Tarides du Sud.', 0),
(24543, 'frFR', 'Une famille divisée', 'Trouvez Kirge Corne-sévère à la Halte de la Vendetta, dans les Tarides du Sud.', 'Les enfants que vous voyez ici ont tous été évacués de Taurajo quand les combats ont commencé. J’essaie de retrouver leurs parents.$b$bL’un des réfugiés que vous avez sauvés des hurans a identifié le plus fort des enfants comme étant le fils de Kirge et Mawre Corne-sévère. Il a aussi dit que Kirge était en garnison aux champs du Sang, juste au nord du site du massacre de Taurajo.$b$bJe vous en prie, $n, allez-y et dites à Kirge Corne-sévère que son fils est bien vivant !', '', '', '', '', '', '', '', '', '', 'Trouvez Kirge Corne-sévère à la Halte de la Vendetta, dans les Tarides du Sud.', 0),
(24546, 'frFR', 'Délimiter notre territoire', 'Prenez une colline neutre dans les Champs du Sang et défendez-la contre une contre-attaque de l\'Alliance.', 'L’Alliance sème la mort et la désolation à travers les Tarides. Nous devons les arrêter ici, ou il ne restera plus de terres pour nous.$b$bSur les champs du Sang, il existe plusieurs collines stratégiquement importantes, marquées par une tour en bois et un drapeau neutre gris à leur sommet. Nous devons prendre ces collines et les tenir si nous comptons ralentir l’avance de l’Alliance !$b$bTrouvez les tours au nord, à l’est et au sud de ce qui reste de Taurajo. Revendiquez l’un des drapeaux neutres et repoussez la contre-attaque de la colline !', '', 'Point capturé', 'Point défendu', '', '', '', '', '', '', 'Retournez voir Kirge Corne-sévère à la Halte de la Vendetta, dans les Tarides du Sud.', 0),
(24550, 'frFR', 'Un voyage aux Pitons-du-Tonnerre', 'Parlez à Baine Sabot-de-Sang aux Pitons-du-Tonnerre.', 'Les puits sont purifiés, et les eaux de Mulgore coulent de nouveau, douces et bienfaisantes. Vous nous avez sauvés… mais vous avez également fait des découvertes inquiétantes. Vous devez expliquer les crimes des Totems-Sinistres en haut lieu.$B$BIl est temps pour vous de découvrir les Pitons-du-Tonnerre, notre grande cité au sommet des mesas. Allez voir notre chef, Baine Sabot-de-Sang, fils de Cairne. Il doit être informé de ce qui se passe.', '', '', '', '', '', '', '', '', '', '', 0),
(24551, 'frFR', 'Une pomme pour la nouvelle maîtresse', 'Tuez des Patrouilles de reconnaissance de Guet-du-Nord et récupérez 10 Plaques de mérite de Theramore.', '$n, vous n’êtes pas sans savoir que Gar’dul n’a pas été d’une grande efficacité en tant que commandant des défenses des Tarides. Rien ne va plus. Garrosh nous dépêche le seigneur de guerre Garde-sanglante pour reprendre les choses en main. Il est ici même, dans ce camp. Si vous voulez faire bonne impression, vous feriez bien de prendre des initiatives.$b$bAllez donc à l’est, dans les champs du Sang et interceptez quelques unités de reconnaissance de Guet-du-Nord. Apportez une poignée de leurs plaques de mérite au nouveau seigneur de guerre. Ça vous permettra de vous faire un nom !', '', '', '', '', '', '', '', '', '', 'Donnez les Plaques au Seigneur de guerre Garde-sanglante à la Halte de la Vendetta, dans les Tarides du Sud.', 0),
(24552, 'frFR', 'La fierté du lion', 'Tuez n’importe quelle combinaison de 5 Rôdeurs des plaines ou de Fiercrins des plaines.', 'Si vous voulez vous venger de ces envahisseurs de l’Alliance, vous feriez bien d’observer les prédateurs les plus féroces des Tarides.$b$bLes lions qui rôdent dans les hautes herbes sont rusés, silencieux et puissants. Prenez exemple sur eux et vous comprendrez le genre de guerre que nous devons mener.$b$bChassez les rôdeurs et les fiercrins des plaines ensuite, revenez m’exposer ce que vous aurez appris. On trouve souvent ces animaux à l’ombre des grands arbres.', '', 'Lions des Tarides tués', '', '', '', '', '', '', '', 'Retournez voir Jorn Oeil-des-cieux à la Halte de la Vendetta.', 0),
(24565, 'frFR', 'Intervention biologique', 'Tuez 5 Dents-d\'effroi déviants et 5 Trotteurs des plaines déviants.', 'Les énergies qui se déchaînent dans la région ont bouleversé la faune et la flore, la métamorphosant en formes instables et puissantes. Si nous laissons ces organismes déviants se répandre au-delà de ce bosquet, ils sèmeront le chaos dans l’écosystème actuel en dévorant les espèces locales et en faisant fuir les créatures naturelles les plus faibles.$b$bVous devez aller dans le lacis et y réduire la population animale. Revenez me voir quand ce sera fait.', '', '', '', '', '', '', '', '', '', 'Retournez voir Naralex.', 0),
(24566, 'frFR', 'Le germe de la solution', 'Utilisez des Graines apaisantes sur 6 Dents-d\'effroi déviants ou Trotteurs des plaines déviants et observez le résultat.', 'En me basant sur ce que vous m’avez apporté, je pense que nous pourrions tenir une solution. J’ai imbibé les graines de vignefouet avec des énergies soignantes.$b$bLe simple contact avec ces graines devrait conférer assez d’énergie aux créatures déviantes pour les purger de toute influence corruptive.$b$bEssayez de guérir les dents-d’effroi et les trotteurs des plaines déviants en les saupoudrant de ces graines. Ensuite, venez me communiquer les résultats.', '', 'Résultats observés', '', '', '', '', '', '', '', 'Retournez voir Muyoh au Lacis, dans les Tarides du Sud.', 0),
(24567, 'frFR', 'Match de sélection', 'Parlez à l\'Entraîneur Sainturrébreutel au Parc des Princes marchands, sur Kezan.', '$n, Sainturrébreutel vous cherche. C’est l\'entraîneur de notre vaillante équipe de footbombe, les Boucaniers de Baille-Fonds.$B$BIl m\'a dit que le titre de la division allait bientôt être disputé contre les Requins de Gentepression et que vous êtes $gle seul:la seule; qui puisse nous le rapporter !$B$BAllez en ville, vers l\'ouest. Impossible de passer à côté du parc des Princes marchands sans le voir !$b$bUne star de footbombe ! C’est tout bon pour votre image !', '', '', '', '', '', '', '', '', '', '', 0),
(24569, 'frFR', 'Briseur de siège', 'Détruisez 4 Engins de siège de Guet-du-Nord aux Portes de Mulgore.', '$n, vous avez fait vos preuves sur les champs du Sang, mais l’Alliance menace encore nos amis taurens.$b$BLes engins de siège, au-delà des portes de Mulgore, sont comme une lance pointée vers notre cœur. Je veux que vous alliez aux portes, au sud d’ici, et que vous neutralisiez ces machines de siège.$B$BTenez, prenez ces bombes sales. C’est un cadeau de nos nouveaux alliés gobelins. On dirait qu’ils ont glissé de la poudre explosive dans… heu… des chaussettes couvertes de graisse, non ? Bah, ça fera l’affaire.', '', 'Engins de siège détruits', '', '', '', '', '', '', '', 'Retournez voir le Seigneur de guerre Garde-sanglante à la Halte de la Vendetta, dans les Tarides du Sud.', 0),
(24570, 'frFR', 'Aspics en gelée', 'Trouvez 5 Aspics affaiblis.', 'La corruption qui règne ici doit être analysée si nous espérons trouver un moyen efficace de la combattre.$b$bHeureusement, toutes les créatures n’ont pas été frappées au même degré. Les serpents de petite taille boivent peu d’eau et ne mangent pas de plantes, donc leur exposition aux énergies a été minime. Cependant, ils en ont quand même absorbé suffisamment pour que la pigmentation de leur peau change.$b$bAllez collecter ces serpents dans le lacis et rapportez-les-moi, afin que nous puissions voir précisément ce qui arrive aux créatures de cet endroit.', '', '', '', '', '', '', '', '', '', 'Retournez voir Muyoh au Camp envahi par la végétation.', 0),
(24571, 'frFR', 'Les graines de vignefouet', 'Collectez 4 Graines grouillantes sur des Vignefouets.', 'Il doit y avoir un moyen de guérir ces pauvres créatures sans avoir à leur prendre la vie. J\'ai une idée, mais j\'aurai besoin de votre aide, $c.$B$BLes vignefouets, des plantes qui rôdent par ici, ont des graines remplies de l\'énergie primale de ces lieux. Collectez-en et rapportez-les-moi. Nous verrons si l\'on peut faire quelque chose.', '', '', '', '', '', '', '', '', '', 'Retournez voir Muyoh dans le Lacis.', 0),
(24572, 'frFR', 'Reprendre Taurajo', 'Tuez 8 Pillards de Taurajo dans les ruines de Taurajo.', 'Excellent travail aux portes, $n ! Le gros des troupes de l’Alliance se replie partout, mais cela ne me suffit pas.$B$BIls ont pillé Taurajo, qui n’était guère plus qu’un camp de chasse. Cette « Alliance » a montré son vrai visage, celui d’une bande de bouchers et de renégats.$B$BEn cet instant même, un groupe d’humains est resté en arrière pour achever de dépouiller les ruines fumantes de Taurajo.$B$B<Garde-sanglante plante une hache dans la poussière.>$B$BJe veux qu’ils souffrent.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Seigneur de guerre Garde-sanglante à la Halte de la Vendetta, dans les Tarides du Sud.', 0),
(24573, 'frFR', 'Honneur aux morts', 'Servez-vous du Totem funéraire sur les corps de Krulmoo, Dranh, Yonada et Omusa dans les ruines de Taurajo.', 'Maintenant que la menace immédiate est écartée, pouvez-vous m’aider dans une triste tâche ?$B$BNous autres taurens n’enterrons pas nos morts. Nous les préparons à revenir aux éléments, avant de les placer dans des sites funéraires sacrés. Ceux qui ont été tués dans le massacre de Taurajo n’ont pas eu de funérailles, et je redoute que des soldats de l’Alliance ignorants ne brûlent leurs corps avant que nous ayons pu accomplir les rites.$B$BJe vous en prie, $n, prenez ce totem, allez à Taurajo, et rendez les derniers devoirs à Krulmoo, Dranh, Yonada et Omusa. Ils… ne s’en sont pas sortis.', '', 'Éloge funèbre de Krulmoo', 'Éloge funèbre de Dranh', 'Éloge funèbre de Yonada', 'Éloge funèbre d\'Omusa', '', '', '', '', 'Retournez voir Winnoa Forêt-de-pins à la Halte de la Vendetta, dans les Tarides du Sud.', 0),
(24574, 'frFR', 'Récolter le chaos', 'Tuez 5 Excroissances et trouvez un Cœur remuant.', 'Si j’ai effectivement semé le chaos, l’heure de la récolte a sonné.$b$bLes enchevêtrements chaotiques de vie végétale se sont même répandus dans le ruisseau consacré, $n. Ils sont une manifestation directe des forces instables qui métamorphosent cette région. Tuez-en autant que possible et nous pourrons peut-être ralentir la propagation du lacis.$b$bAh, et tant que vous y êtes… essayez de repérer les organismes particulièrement corrompus et rapportez-m’en quelques spécimens.', '', '', '', '', '', '', '', '', '', 'Retournez voir Naralex dans le Lacis.', 0),
(24575, 'frFR', 'Le jour de la libération', 'Libérez 5 Villageois asservis dans la Mine de Pierrebraise.', 'Nous avons récemment découvert que les villageois de Pierrebraise ont survécu à la plupart des ravages de la Malédiction.$B$BMalheureusement, leur village n\'a pas eu autant de chance face à l\'invasion des Réprouvés.$B$BIls ont fait prisonniers les villageois et les forcent à travailler comme esclaves dans la mine à proximité.', '', 'Gilnéen asservi libéré', '', '', '', '', '', '', '', 'Retournez voir Lorna Crowley à l’Avant-poste de l’écurie.', 0),
(24577, 'frFR', 'Inspection du fort de la désolation', 'Parlez au seigneur de guerre Garde-sanglante, ensuite pénétrez dans le Fort de la Désolation et informez Gar’dul que Garde-sanglante va arriver.', 'Grâce à vous, la menace à court terme a été levée, mais mon travail dans les Tarides ne fait que commencer.$b$bLe Séjour de l’honneur a été capturé et Taurajo a été mis à sac, tout ça alors que le seigneur de guerre Gar’dul avait le commandement de la région. Le chef de guerre m’a envoyé pour réparer ses erreurs.$b$bJ’aimerais que vous vous rendiez avant moi au fort de la Désolation, au sud. Dites à Gar’dul qu’il va devoir rendre des comptes.$b$bVenez me parler quand vous serez $gprêt:prête; et j’assemblerai mon avant-garde pour qu’elle vous accompagne.', '', 'Gar\'dul notifié', '', '', '', '', '', '', '', 'Parlez au seigneur de guerre Garde-sanglante, ensuite pénétrez dans le Fort de la Désolation et informez Gar’dul que Garde-sanglante arrive.', 0),
(24578, 'frFR', 'La forêt Noire', 'Enquêtez au Moulin de Bradshaw à l’extérieur de Val-Tempête.', 'Ça a pris du temps, mais je pense avoir réussi à reconstituer ce qui s’est passé ici. Au moins en partie.$B$BDes gens ont survécu à la Malédiction, dans cette ville. Ils ont rejoint d’autres personnes dans les montagnes, aux confins de la Tourmente.$B$BTout le monde est parti, excepté l’homme qui tenait ce journal, le vieux Bradshaw. Il a remarqué que les attaques de worgens s’étaient arrêtées brutalement et a voulu s’aventurer dans la forêt Noire.$B$BBradshaw vivait dans un moulin maintenant abandonné, au nord-est de la ville. Voyez si vous y trouvez des indices.', '', '', '', '', '', '', '', '', '', '', 0),
(24591, 'frFR', 'La relève de la Gar\'dul', 'Rendez-vous au sommet de la tour nord au Fort de la Désolation et aidez le Seigneur de guerre Garde-sanglante à « relever » Gar\'dul de ses fonctions.', 'Quand Garde-sanglante arrivera, j’aimerais lui parler –hem ! – en privé. Pouvez-vous m’accompagner pour être sûr que les choses ne tournent pas au vinaigre ? Ce Garde-sanglante, il est – hem ! – il est vraiment – hem ! – vraiment imprévisible.$b$b<Gar’dul essaie de se calmer.>$b$bRetrouvez-moi au sommet de la tour nord et nous parlerons à Garde-sanglante tous les deux.', '', 'Aller au sommet de la tour', 'Gar’dul « relevé » de son commandement', '', '', '', '', '', '', 'Parlez au Seigneur de guerre Garde-sanglante au Fort de la Désolation, dans les Tarides du Sud.', 0),
(24592, 'frFR', 'Trahison aux confins de la Tourmente', 'Buvez la Potion de camouflage de Krennan aux Confins de la Tourmente, puis assassinez les Seigneurs Ashbury et Walden.', 'Le roi Grisetête a été fait prisonnier par le seigneur Godfrey aux confins de la Tourmente !$B$BIl a réussi à convaincre deux seigneurs de l\'Est de suivre son plan. Le fou pense arriver à conclure un marché avec les Réprouvés en leur livrant Grisetête.$B$BÉcoutez bien, $n. Nous devons résoudre cette affaire en faisant le moins de victimes possibles.$B$BCette potion vous permettra de vous infiltrer sans vous faire repérer. Vous devez assassiner les seigneurs traîtres avant que la situation ne dégénère !', '', '', '', '', '', '', '', '', '', 'Parlez au Roi Grisetête aux Confins de la Tourmente, en Gilnéas.', 0),
(24593, 'frFR', 'Ni homme ni bête', 'Buvez au Puits de tranquillité, au Puits d\'équilibre et au Puits de fureur.', 'Il est temps, $n. Cette... alchimie qui a permis de neutraliser la bête en vous ne durera pas longtemps.$B$BLes premiers worgens maudits étaient des druides elfes de la nuit, comme nos nouveaux alliés. Cependant, ils renoncèrent à l\'équilibre que le reste de leur race embrassait et permirent à la bête de prendre le contrôle de leur esprit.$B$BCe n\'est que justice que leurs frères soient ceux qui nous délivrent de la Malédiction. Allez, $C. Buvez aux eaux de Tal\'doren et faites la paix avec vous-même.', '', '', '', '', '', '', '', '', '', 'Parlez au Seigneur Darius Crowley à Tal’doren en Gilnéas.', 0),
(24601, 'frFR', 'La balafre du Cauchemar', 'Aidez Naralex à sceller la Balafre du Cauchemar.', 'Ça se confirme. Cette prolifération n’est pas simplement due à un surcroît d’énergie.$B$BVous comprenez ? C’est bien au-delà de ce qui est arrivé aux cavernes des Lamentations. Il a dû s’ouvrir une faille, une balafre, qui donne sur le Cauchemar, au beau milieu de ces terres mêmes où nous nous trouvons ! Et je crois que c’est de ma faute…$B$BJ’en ai assez d’appliquer des emplâtres sur des jambes de bois. Allez à l’ouest, au centre du Lacis. C’est là que nous nous retrouverons. Nous plongerons alors au cœur de toute cette corruption et nous en tarirons la source de force !', '', 'Balafre du Cauchemar scellée', '', '', '', '', '', '', '', 'Retournez voir Naralex au milieu du Lacis, dans les Tarides du Sud.', 0),
(24602, 'frFR', 'Le repos éternel', 'Retrouvez 5 Souvenirs déterrés.', 'Lors de notre fuite précipitée, nous avons commis la faute d’ébranler les tombes de nos ancêtres, $n. Et voilà que ça nous retombe dessus, sans vouloir faire de jeu de mot.$B$BDans les cimetières de Gilnéas, traditionnellement, l’on enterre une sorte de petit souvenir du mort sous une fine couche de terre. Le piétinement des gens qui fuyaient dans ces tunnels a exhumé ces souvenirs et courroucé les esprits.$B$BTrouvez-les et apportez-les-moi. Nous nous assurerons que les morts retournent à leur sommeil éternel et paisible.', '', '', '', '', '', '', '', '', '', 'Retournez voir Krennan Aranas au Repos d’Aderic, en Gilnéas.', 0),
(24603, 'frFR', 'La croisade de Mankrik', 'Tuez 13 Hurans tranchecrins.', 'Pendant un instant, j’ai cru que ma haine était retombée. Ma compagne portée en terre, je lui ai fait une dernière offrande du sang de ses meurtriers pour apaiser son esprit torturé. Je pensais trouver la paix.$b$bJe me suis trompé.$b$bJe n’aurai de repos que quand le dernier de ces sales petits pourceaux grognants et meurtriers sera mort et enterré ! Je trouve que je n’en tue pas encore assez à moi tout seul. Tuez-en pour moi, $r !', '', 'Hurans tranchecrins tués', '', '', '', '', '', '', '', 'Retournez voir Mankrik dans les Tarides du Sud.', 0),
(24604, 'frFR', 'Inquiétude au sujet de Mankrik', 'Apportez le Cadeau de Mahka à Mankrik, au sud de la halte de Pierre-feu.', 'J\'aimerais vous demander une faveur, $c.$B$BUn guerrier du nom de Mankrik, qui voyage seul, est récemment passé par notre camp. Sa femme a été tuée par les hurans, il y a longtemps de cela, et il cherche toujours vengeance. Je n\'arrive pas à oublier ses yeux... ils brûlent en permanence d\'une haine inconsolable.$B$BNous n\'avons que brièvement parlé, mais il m\'est insupportable de penser à lui, tout seul là-bas. S\'il vous plaît, apportez ceci à Mankrik, et dites-lui que c\'est moi qui le lui envoie...', '', '', '', '', '', '', '', '', '', '', 0),
(24606, 'frFR', 'Le sang des Tarides', 'Collectez 6 Bijoux joyau de sang sur des Hurans tranchecrins.', 'Cette pierre rouge vif que vous avez trouvée serrée dans le poing d’un huran, a été soigneusement taillée à l’effigie d’un grand sanglier dont les crins se transforment en lianes épineuses. Sa surface est lisse et délicatement polie.$b$bEst-ce que cette pierre est l’œuvre des hurans ? Si vous en trouviez d’autres, peut-être qu’un des chamans de la halte de Pierre-feu pourrait vous en dire plus à leur sujet.', '', '', '', '', '', '', '', '', '', 'Retournez voir Mahka à la Halte de Pierre-feu.', 0),
(24607, 'frFR', 'L’ascension des Sombrelances', 'Allez voir Nortet sur le Terrain d’entraînement des Sombrelances.', 'Nous autres Sombrelances, on a longtemps été des victimes. Des parias. On a dû fuir notre foyer, encore et encore… mais cette fois-ci, c’est pas pour fuir qu’on est là.$B$BVol’jin, il nous gouverne avec sagesse, et c’est ça qui nous a gardés en vie si longtemps. Et maintenant, avec sa sagesse, il voit que la Horde sous les ordres de Garrosh Hurlenfer, elle a un avenir chaotique.$B$BNon, cette fois, on ne fuit pas. Cette fois, on se bat pour rester chez nous.$B$BIl est temps de commencer votre formation, $n. Parlez à Nortet, à l’est.', '', '', '', '', '', '', '', '', '', '', 0),
(24608, 'frFR', 'Mutiledent', 'Tuez Mutiledent.', 'Je n’ai plus que faire de l’honneur ou de la gloire, $c. Tout ce qui m’importe, c’est de voir mourir les hurans, à tout prix et de n’importe quelle manière.$b$bMutiledent, le chef de ces sales petits Dos-hirsutes se trouve dans son antre au sommet d’une colline, au nord-ouest. Mettez fin à ses jours.$b$bJ’ai l’intention de rester ici et d’entasser les cadavres jusqu’à ce que plus aucune vermine ne sorte du kraal…', '', '', '', '', '', '', '', '', '', 'Retournez voir Mankrik dans les Tarides du Sud.', 0),
(24616, 'frFR', 'Effacez vos traces', 'Utilisez le Talisman de Belrysa pour vaincre l’Éclaireur noir.', 'Vous devez vous poser de nombreuses questions, $n. Vous aurez vos réponses en temps voulu.$B$BJe sais pourquoi vous êtes ici et ce que vous cherchez.$B$BMais je ne peux pas vous y mener tant que l’ennemi vous pourchasse.$B$BL’un des éclaireurs de Sylvanas vous suit à la trace. Vous ne devez pas mener les Réprouvés à l’endroit que vous cherchez. Prenez ce talisman et marchez le long de la route qui se trouve au nord d’ici.$B$BLaissez le forestier vous attirer dans son piège et utilisez le pouvoir du talisman pour vous libérer et contre-attaquer.', '', '', '', '', '', '', '', '', '', 'Retournez voir Belrysa Brise-Stellaire au Moulin des Bradshaw.', 0),
(24617, 'frFR', 'Tal\'doren, le foyer sauvage', 'Parlez à Darius Crowley à Tal\'doren, au cœur de la Forêt Noire.', 'Vous n\'êtes pas $gseul:seule;, $n. D\'autres étaient comme vous, perdus et confus.$B$BVous avez un foyer maintenant.$B$BTal\'doren, le foyer sauvage abritait autrefois un ordre de druides capables de se transformer en loups.$B$BVous y trouverez les réponses que vous cherchez et également quelqu\'un pour vous servir de guide, un vieil ami.', '', '', '', '', '', '', '', '', '', '', 0),
(24618, 'frFR', 'La revendication de la Balafre', 'Rendez-vous à la Balafre. Trouvez le drapeau et tuez 10 Soldats de l’avant-garde de Fort-Triomphe.$b$bLa capture du drapeau donnera un avantage à tous les joueurs de la Horde dans la Balafre.', 'Nous avons réussi à contenir l’avance de l’Alliance dans cette région, même si la terre se déchire sous nos pieds. À l’est, vous trouverez la Balafre, une large bande de terre désolée. Ce n’est guère qu’une ligne dans le sable, mais il faut que ce soit NOTRE ligne.$b$bAu centre de la Balafre, vous trouverez un drapeau aux couleurs de celui qui la contrôle. Allez reconnaître la zone où se trouve le drapeau.$b$bS’il n’est pas encore à nos couleurs, capturez-le pour la Horde. Il nous donnera l’avantage dans la bataille. Explorez la Balafre et tuez tous ceux que vous verrez !', 'Drapeau de la Balafre capturé', '', '', '', '', '', '', '', '', 'Retournez voir le Seigneur de guerre Garde-sanglante au Fort de la Désolation, dans les Tarides du Sud.', 0),
(24619, 'frFR', 'Pièces de récup\'', 'Utilisez la Scie à os de Calder sur les cadavres de la Balafre et récoltez 15 Extrémités coupées.', 'J’ai toujours voulu essayer de créer une abomination. Ça a l’air assez simple, mais vous savez, tout a toujours l’air simple sur le papier. Rien ne vaut l’expérimentation !$b$bPour commencer, je vais avoir besoin de pièces. Beaucoup de pièces. Et c’est vous qui allez me les trouver.$b$bPas la peine de faire la fine bouche : humain, orc,… ça n’a pas d’importance. Les pièces sont les pièces.$b$bSoyez juste $gcertain:certaine; que les cadavres sur lesquels vous les prélevez proviennent de la Balafre, comme ça je suis sûr qu’ils seront frais.$b$b<Calder vous tend une scie de boucher rouillée et couverte de sang séché, tout en affichant un sourire complice.>', '', '', '', '', '', '', '', '', '', 'Apportez les pièces à Calder Gray à l’extérieur du Fort de la Désolation, dans les Tarides du Sud.', 0),
(24620, 'frFR', 'Rodrigue, as-tu du cœur ?', 'Tuez un Mâle vibreterre, au sud de la Balafre et prélevez-lui un Cœur de kodo énorme.', 'Ces pièces… elles sont si belles ! Des muscles, des tendons, des doigts et des orteils… J’attrape vraiment faim, tout à coup.$b$bMais le travail passe avant tout. Une fois que j’aurai cousu tous ces organes ensemble, j’aurai besoin d’un cœur assez puissant pour irriguer ce labyrinthe de veines. J’utiliserais bien mon propre cœur, mais ce n’est qu’une coquille tellement fripée qu’on dirait un navet desséché.$b$bNon, il me faut des chevaux sous le capot. Trouvez-moi un cœur de kodo sur un de ces mâles vibreterre géants, au sud de la Balafre.', '', '', '', '', '', '', '', '', '', 'Retournez voir Calder Gray à l’extérieur du Fort de la Désolation, dans les Tarides du Sud.', 0),
(24621, 'frFR', 'Ceeerveauuux…', 'Tuez un Capitaine de Fort-Triomphe à l’autre bout de la Balafre et prélevez-lui son Cerveau frais.', 'Ma monstruosité prend forme ! Il n’y a plus qu’à lui fourrer quelque chose dans le ciboulot.$b$bJe parle d’un cerveau, $n. Et pas de n’importe quel cerveau. Le processus d’abomination cause des dégâts cérébraux considérables, donc il vaut mieux commencer avec un sujet intelligent.$b$bUn officier de l’Alliance devrait faire l’affaire. Choisissez un des capitaines à l’autre bout de la Balafre et essayez de ne pas abîmer la marchandise en le tuant.', '', '', '', '', '', '', '', '', '', 'Apportez le Cerveau frais à Calder Gray à l\'extérieur du Fort de la Désolation, dans les Tarides du Sud.', 0),
(24622, 'frFR', 'Le meilleur ami du troll', 'Parlez à Kijara sur le Rivage Griffesang.', 'Si vous cherchez un truc à faire, on a b\'soin de mettre les raptors dans les enclos. Si vous allez à l\'île, au sud, vous y trouverez nos éleveurs, ils vous mettront au jus.$B$BS’ront sûrement ravis du coup de main. Allez, soyez sympa, d’acc ?', '', '', '', '', '', '', '', '', '', '', 0),
(24623, 'frFR', 'Sauver les jeunes', 'Servez-vous du Sifflet griffesang pour sauver 12 Jeunes Griffesang égarés.', 'En fait, vous pouvez m’aider pour quelque chose de très important, si vous voulez, $gmon pote:ma grande;.$B$BNos jeunes raptors, y a quelqu’un sur l’île d’à côté qui les vole. Au début, je pensais qu’ils s’enfuyaient ou qu’ils mouraient de causes naturelles, mais maintenant, y nous manque plus d’une douzaine de p\'tits gars.$B$BAllez à la Chute de Zalazane, au nord-ouest, et montrez le chemin du retour à ces pauvres petits chéris, d\'accord ?', '', 'Jeune Griffesang sauvé', '', '', '', '', '', '', '', 'Retournez voir Kijara au Rivage Griffesang sur les Îles de l’Écho.', 0),
(24624, 'frFR', 'De la miséricorde pour les égarés', 'Tuez 8 Raptors Griffesang corrompus.', 'Celui qui vole nos raptors, il les corrompt avec un genre de magie. Maintenant qu’ils ont grandi avec cette corruption en eux, j’crois qu’on peut plus rien faire d’autre pour les sauver que d’leur accorder la paix dans la mort. Allez à la Chute de Zalazane, au nord-ouest, et mettez-vous au boulot.$B$BJ’espère que vous aurez l’estomac pour ça. Moi, même en sachant que c’est nécessaire, j’crois que j’pourrais pas.', '', '', '', '', '', '', '', '', '', 'Retournez voir Tegashi au Rivage Griffesang sur les Îles de l’Écho.', 0),
(24625, 'frFR', 'Le consort de la sorcière des mers', 'Tuez Naj\'tess et récupérez son orbe.', 'J’ai mené ma p\'tite enquête sur les Griffesangs corrompus, et je crois que j’ai trouvé la source du problème, un naga isolé. Il tenait un orbe rouge au-dessus de nos jeunes, et je les ai vus… changer.$B$BJ\'suis sûr qu’y s\'imagine que ses vols et ses sortilèges, ils sont passés inaperçus. Vous devriez pouvoir le choper avant qu’il se doute de quelque chose. Tuez ce naga et ramenez-moi cet orbe ignoble. Vous le trouverez au nord-ouest, sur la Chute de Zalazane.', '', '', '', '', '', 'Naj\'tess croyait pouvoir retourner leurs alliés les plus fidèles contre les Sombrelances. Il ne sous-estimait pas que les trolls.', 'Naj\'tess', '', '', 'Retournez voir Tegashi au Rivage Griffesang sur les Îles de l’Écho.', 0),
(24626, 'frFR', 'Jeune et vicieux', 'Capturez Vivegriffe et amenez-le dans les enclos près du Bastion des Sombrelances.', 'Z’êtes $gbon:bonne; $n.$B$BMoraya, elle a demandé à ce qu’on lui amène de nouveaux raptors à dresser, et faut pas la faire attendre plus ! J’ai demandé à d’autres recrues de lui en amener, mais y en a un spécial que je promets à Moraya depuis longtemps.$B$BVivegriffe est l’un de nos jeunes raptors les plus rapides et les plus braves, mais l’est un peu indiscipliné. J’vais vous donner l’lasso, faudra qu’vous le preniez quelque part sur cette île, et que vous l’ameniez à l’enclos de l’île principale. Y a des chances qu’y s’laisse pas trop faire.', '', 'Capturer Vivegriffe', 'Vivegriffe remis à l\'enclos aux raptors', '', '', '', '', '', '', 'Parlez à Moraya au Bastion des Sombrelances sur les Îles de l’Écho.', 0),
(24627, 'frFR', 'À nos portes', 'Tuez 6 Banshees hurlantes.', 'Les elfes de la nuit nous ont beaucoup appris, $n. Ce sont eux qui nous ont révélé qui nous sommes et d\'où nous venons.$B$BGrâce à eux, grâce à cet endroit... nous ne sommes plus de simples bêtes. Nous avons regagné notre libre arbitre.$B$BLes Réprouvés ne sont pas venus seulement en quête de terres.$B$BIls cherchent quelque chose que nous possédons. C’est un artéfact qui pourrait propager la Malédiction à l’humanité entière. Il ne faut à aucun prix qu’ils le trouvent.$B$BLes banshees de Sylvanas sont beaucoup trop près. Aidez mes pisteurs à en venir à bout.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Seigneur Darius Crowley à Tal’doren, en Gilnéas.', 0),
(24628, 'frFR', 'Préparations', 'Apportez 6 Feuillelunes à Vassandra.', 'Ce que vous connaissez sous le nom de Malédiction a débuté par une hérésie parmi les miens.$B$BAlors qu\'ils essuyaient une défaite face aux forces démoniaques, les druides de la meute tournèrent le dos à l\'équilibre auquel ils avaient prêté serment et laissèrent la bête en eux prendre le dessus.$B$BIls furent bannis dans le Rêve d\'émeraude, où ils se sont à jamais endormis sous un arbre identique à celui-ci. Mais leur malédiction s\'était déjà répandue.$B$BNotre cérémonie permettra enfin de rétablir l\'équilibre de votre peuple. Apportez-moi la feuille qui pousse uniquement dans les environs de Tal\'doren.', '', '', '', '', '', '', '', '', '', 'Retournez voir Vassandra à Tal’doren dans la Forêt Noire.', 0),
(24631, 'frFR', 'Cauchemar ailé', 'Utilisez le Crochet de Tomusa sur les Griffons de guerre de Fort-Triomphe pour faire tomber 5 Mercenaires marteaux-hardis. Tuez-les une fois à terre.', 'L’Alliance a recruté des mercenaires marteaux-hardis pour contrôler le ciel au-dessus de la Balafre. Je pense que ce sont les mêmes chevaucheurs de griffons qui ont largué des bombes incendiaires sur Taurajo durant l’attaque.$b$bJe veux que notre espace aérien soit nettoyé.$b$bLes Marteaux-hardis volent suffisamment bas pour qu’$gun:une:c; $c les fasse démonter. Prenez ceci. Visez les griffons et jetez les chevaucheurs à bas de leur monture. Une fois à terre, ne leur faites pas de quartier.', '', '', '', '', '', '', '', '', '', 'Retournez voir Tomusa au Fort de la Désolation, dans les Tarides du Sud.', 0),
(24632, 'frFR', 'La vengeance d\'un tauren', 'Cherchez Gann Cime-de-pierre à Fer-de-lance, dans les Tarides du Sud.', 'Mon peuple n’est pas de nature belliqueuse, mais parfois, la colère et la soif de justice nous font prendre les armes.$b$bLorsqu’il a appris la nouvelle du bain de sang de Taurajo, mon vieil ami Gann Cime-de-pierre est entré dans une rage tellement aveugle que les anciens de la tribu n’ont pas pu le maîtriser.$b$bAujourd’hui, c’est à peine s’il a encore des contacts avec la Horde. Il est devenu un renégat, $n, et il s’est mis à attaquer l’Alliance avec un petit groupe de partisans.$b$bSi vous aussi, vous avez soif de vengeance, vous trouverez Gann au sud-est, au pied de Bael Modan.', '', '', '', '', '', '', '', '', '', 'Cherchez Gann Cime-de-pierre à Fer-de-lance, dans les Tarides du Sud.', 0),
(24633, 'frFR', 'La requête de Mahka', 'Parler à Mankrik.', 'Je n’arrive pas à l’oublier, $n. Parfois, la nuit, je peux l’entendre hurler de rage et de souffrance, ses lamentations résonnant à travers la plaine. Je l’imagine là-bas, seul et accablé de tant de peine…$b$bJe vous supplie de me rendre un service. Allez voir Mankrik et priez-le de venir me voir.', 'Parler à Mankrik', '', '', '', '', '', '', '', '', 'Retournez voir Mahka à la Halte de Pierre-feu.', 0),
(24634, 'frFR', 'La guerre du renseignement', 'Tuez un Agent des Tarides et récupérez les Briefings du SI:7.', 'Je suis persuadé que l’Alliance utilise des espions pour explorer la région et récolter des renseignements. Ils savaient que les chasseurs étaient hors de Taurajo quand ils l’ont attaqué, et ils ont lu la défense de Gar’dul comme dans un livre ouvert.$b$bHé bien, $n, je ne vais pas me faire avoir, moi. Pas ici. Nous allons gagner la guerre du renseignement.$b$bEn cet instant-même, j’apprends que des agents de l’Alliance rôdent dans l’ombre, surtout ici, juste en dehors de cette enceinte. Tuez ces agents et rapportez-moi des renseignements utiles.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Seigneur de guerre Garde-sanglante au Fort de la Désolation, dans les Tarides du Sud.', 0),
(24637, 'frFR', 'Le boucher de Taurajo', 'Parlez à Karthog, puis attirez le Général Hawthorne à l\'extérieur et assassinez-le.', 'Les ordres de cet agent étaient de sécuriser les routes allant du poste de commandement de l’Alliance à Fort-Triomphe. Le général Hawthorne est en déplacement.$b$b<Garde-sanglante broie les documents dans son poing.>$b$bC’est LUI, $n ! Hawthorne, maudit soit son nom, est celui qui a ordonné l’assaut sur Taurajo ! Maintenant, nous savons quand et où le frapper. Vite, suivez la route au nord de la Balafre et retrouvez Karthog, mon assassin. BROYEZ Hawthorne et éparpillez son cadavre le long de la route !', '', '', '', '', '', 'Trouvez Karthog le long de la route au nord de la Balafre. Ensemble, tendez une embuscade au Boucher de Taurajo et tuez-le.', 'Général Hawthorne', '', '', 'Retournez voir le Seigneur de guerre Garde-sanglante au Fort de la Désolation, dans les Tarides du Sud.', 0),
(24639, 'frFR', 'La base : savoir frapper des trucs', 'Détruire 6 Cibles Tiki.', 'D’accord d’accord, $gmon pote:ma grande;. On va commencer petit. Faut que j’m’assure ‘‘vous savez vous servir de cette arme qu’vous trimballez avec vous.$B$BAllez m’casser des cibles tiki. En douceur. Naturellement. J’vais vous regarder vous escrimer, et on partira d’là.', '', '', '', '', '', '', '', '', '', 'Retournez voir Nortet au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24640, 'frFR', 'Les arts du guerrier', 'Atteignez le Niveau 3 pour apprendre la Charge, puis utilisez-la sur une Cible Tiki.', 'En vous améliorant au combat, vous découvrirez d’nouveaux trucs dont vous vous seriez jamais cru capable.$B$BVous voulez voir ? Entraînez-vous un peu, jusqu’à apprendre quelque chose de nouveau.$B$BRevenez m’voir ensuite pour me montrer ça.', '', 'S’exercer à la Charge', '', '', '', '', '', '', '', 'Retournez voir Nortet au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24641, 'frFR', 'Un début difficile', 'Récupérez 6 Peaux de félins crin-sauvage.', 'Bon, ben $gmon pote:ma grande;, on va s’servir de ces compétences, en commençant par un truc qu’il sera facile.$B$BY a des fauves qui tuent nos sangliers. Not’bouffe, on la partage pas. Si vous voulez grailler ce soir, faut que ces sangliers, ils soient en vie.$B$BY en a sur toute l’île. Amenez-moi des peaux de félins.', '', '', '', '', '', '', '', '', '', 'Retournez voir Nortet au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24642, 'frFR', 'La fosse de l’épreuve', 'Parlez à un Geôlier sombrelance, puis descendez dans la fosse de l’épreuve et tuez un Éclaireur Vexécaille captif.', 'Vous vous en sortez bien, $c. Oh, pas d’doute, j’peux encore vous apprendre un ou deux trucs, mais j’serais vous, j’perdrais plus mon temps sur les cibles tiki.$B$BAlors, j’ai une autre épreuve pour vous, $gmon pote:ma grande;. Vous allez jusqu’à la fosse de l’épreuve, là au milieu, et vous vous battez contre un vrai méchant, un qui va s’défendre et vouloir vous tuer. Quand vous serez $gprêt:prête;, vous le dites juste au geôlier, au bord d’la fosse.', '', 'Parlez à un Geôlier sombrelance', '', '', '', '', '', '', '', 'Retournez voir Nortet au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24643, 'frFR', 'Mieux que prévu', 'Présentez-vous à Vol’jin au Bastion des Sombrelances.', 'Y a plus en vous qu’on n’en attendait, $gmon pote:ma grande;. On doit sûrement avoir des trucs plus importants à vous faire faire. Z’avez plus besoin de traîner ici avec les autres p’tits nouveaux.$B$BAllez au village, au sud-est, et faites-vous connaître. Donnez un coup de main ici ou là, et en un rien de temps, vous aurez eu l’occase de faire quequ’chose de plus prestigieux.', '', '', '', '', '', '', '', '', '', '', 0),
(24644, 'frFR', 'Intro troll terminée', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(24646, 'frFR', 'Reprendre ce qui nous appartient', 'Soufflez dans le Cor de Tal\'doren à la Cabane du Bout-du-bois et récupérez l\'Artéfact mystérieux qui y est caché.', 'Depuis que les Réprouvés ont envahi Gilnéas, nous avons tenté de garder l\'emplacement de la faux d\'Élune secret. Nous la déplacions de nuit de l\'une à l\'autre de nos cachettes. Les forestiers-sombres s\'en sont approchés, mais ne l\'ont jamais trouvée... jusqu\'à aujourd\'hui.$B$BLa dernière fois qu\'ils ont été vus, c\'était près de la cabane du Bout-du-bois, à l\'ouest. Soufflez dans ce cor lorsque vous les aurez trouvés et Tobias et ses pisteurs attaqueront les forestiers-sombres.$B$BVous pourrez alors vous aventurer dans la cabane en toute sécurité et reprendre la faux. Dépêchez-vous, $n. Sylvanas ne doit pas mettre la main dessus.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Seigneur Darius Crowley à Tal’doren en Gilnéas.', 0),
(24653, 'frFR', 'Des échos d\'Agamaggan', 'Récupérez 3 Crânes de sanglier polis.', 'Je pense que les agissements des hurans sont motivés par autre chose qu’un simple instinct bestial. Pouvez-vous m’aider à éclaircir la question ?$b$bÀ l’ouest, j’ai remarqué que des crânes de sangliers étaient éparpillés dans les villages et les campements hurans. On peut les voir briller de loin car ils sont soigneusement polis et se détachent nettement au milieu des tas d’ordures. Je pense que ce sont des objets de culte.$b$bApportez-moi quelques-uns de ces crânes pour que je les examine, $n.', '', '', '', '', '', '', '', '', '', 'Retournez voir Mahka à la Halte de Pierre-feu, dans les Tarides du Sud.', 0),
(24654, 'frFR', 'Vermine silithide', 'Utilisez le Seau de poix ardente sur les Antres des silithides et tuez 10 Grouillants silithides quand ils s’en échappent.', 'Les silithides ! Ce sont des insectes, $n. Et encore. Ils ne sont pas naturels… Et dire qu’on a construit une forteresse sur l’équivalent d’une fourmilière.$b$bPrenez cette poix ardente. Ça fera frire cette vermine et ça rebouchera leurs galeries par la même occasion. Soyez $gprudent:prudente; quand vous verserez cette substance, car les silithides s’échapperont en masse !$b$bTrouvez les antres des silithides à l’extérieur du fort de la Désolation. Ils ressemblent à des tas de sable. Tuez tout ce qui en sort et qui rampe.', '', '', '', '', '', '', '', '', '', 'Retournez voir Crawgol au Fort de la Désolation, dans les Tarides du Sud.', 0),
(24667, 'frFR', 'La halte de Pierre-feu', 'Remettez le Manuel pratique sur les silithides de Crawgol à Tauna Chasse-le-Ciel à la Halte de Pierre-feu, dans les Tarides du Sud.', 'Je maîtrise le problème des silithides depuis bientôt un mois, c’est pourquoi je me considère comme l’expert local en la question. Il y a une semaine à peine, le Cercle terrestre était en visite ici et ils veulent que j’écrive un papier sur les silithides.$b$b<Crawgol vous tend un livre en piteux état.>$b$bJe n’ai pas une très bonne plume car je n’aime ni lire, ni écrire, mais ce livre est probablement le manuel le plus exhaustif sur les silithides.$b$bApportez-le à Tauna Chasse-le-Ciel, à la halte de Pierre-feu. C’est juste au sud d’ici, à l’ouest de la route principale.', '', '', '', '', '', '', '', '', '', 'Remettez le Manuel pratique sur les silithides de Crawgol à Tauna Chasse-le-Ciel à la Halte de Pierre-feu, dans les Tarides du Sud.', 0),
(24671, 'frFR', 'Cot-cot en cocotte', 'Capturez 10 Poules sauvages en les attachant à un Feu d\'artifice télécommandé.', 'Ridicule ! Le plus grand génie gobelin de tous les temps réduit à se préoccuper de nourriture ? J\'ai justement créé le micro-mécapoulet pour ça et ils le laissent filer !$B$B<La peau de Hobart s\'assombrit tandis que sa pression artérielle augmente.>$B$BEst-ce que j\'ai l\'air d\'être du genre à courir après des poules sauvages fugitives ? Ah ça non, mon $gami:amie;, pas moi ! Bamm très certainement, mais il est bien trop paresseux.$B$BMais vous venez de dégringoler sur l\'échelle sociale, alors vous allez le faire !$B$BPrenez ces feux d\'artifice télécommandés et attachez-les aux poules.', '', 'Poules sauvages capturées', '', '', '', '', '', '', '', 'Retournez voir Hobart Martelutte à Ville-en-Boîte, sur les Îles Perdues.', 0),
(24672, 'frFR', 'En constante progression', 'Retrouvez Krennan Aranas sur la route vers les Confins de la Tourmente.', 'Je vais faire ce que Darius a demandé et mener les survivants à travers la forêt Noire.$B$BVous devriez rattraper le roi Grisetête. Lui et Krennan sont partis pour les confins de la Tourmente après que le seigneur Godfrey a confirmé que des survivants y avaient établi un campement.$B$BSuivez la route qui quitte Val-Tempête et mène dans les montagnes. J\'ai demandé à Krennan de vous attendre au niveau du pont avant les confins de la Tourmente.', '', '', '', '', '', '', '', '', '', '', 0),
(24673, 'frFR', 'Retour à Val-Tempête', 'Parlez à Gwen Armstead à Val-Tempête.', 'Il faudra du temps avant que notre nation soit à nouveau unie. Les anciennes tensions politiques ne sont rien comparées à la rupture que nous vivons aujourd\'hui.$B$BMais s\'il y a bien un moment propice pour s\'unir et combattre un ennemi commun, c\'est maintenant. Et c\'est vous, $n, qui avez prouvé qu\'il était possible de franchir le fossé qui sépare nos peuples.$B$BRetournez à Val-Tempête et dites aux habitants qu\'ils pourront traverser la forêt Noire en toute sécurité pour rejoindre les confins de la Tourmente. Nous nous chargerons des Réprouvés qui tenteraient de les suivre.', '', '', '', '', '', '', '', '', '', '', 0),
(24674, 'frFR', 'Esclaves de personne', 'Tuez Brothogg le maître d\'esclaves dans la Mine de Pierrebraise.', 'Je suis l\'un des rares rescapés, $n. Lorsque les Réprouvés ont pris d\'assaut notre ville et notre mine, ils nous ont traités avec la plus extrême cruauté.$B$BLes plus faibles d\'entre nous qui ne pouvaient supporter ce dur labeur se sont tués à la tâche sous les coups d\'une abomination appelée Brothogg.$B$BMa femme fait partie des victimes, $c, et j\'ai juré de venger sa mort. Je suis trop faible pour l\'instant, mais vous pouvez faire justice... pour ma femme... pour Gilnéas !', '', '', '', '', '', 'Débarrassez-vous de cette… cette… ABOMINATION.', 'Brothogg le maître d’esclaves', '', '', 'Retournez voir Marcus à l’Avant-poste de l’écurie.', 0),
(24675, 'frFR', 'Un dernier repas', 'Récupérez 10 Gigues de cerf.', 'Je ne suis pas idiote, $n. Je sais ce qui nous attend.$B$BNotre peuple va passer ces portes pour combattre un ennemi mieux entraîné, supérieur en nombre et mieux armé que nous.$B$BMême si nous en sortons victorieux, le prix à payer sera terrible. Pour la plupart d\'entre nous, le repas d\'aujourd\'hui sera le dernier.$B$BJe ne peux pas me battre, mais je suis une excellente cuisinière. Apportez-moi de la viande des cerfs qui abondent dans cette zone, et je m\'assurerai que le dernier repas de ces gens soit le meilleur qu\'ils aient jamais fait.', '', '', '', '', '', '', '', '', '', 'Retournez voir Magda Whitewall à l’Avant-poste de l’écurie dans la ville de Gilnéas.', 0),
(24676, 'frFR', 'Repoussez les envahisseurs', 'Tuez 4 Soldats d\'infanterie réprouvés, l\'Exécuteur Cornell et Valnov le Fou à Pierrebraise.', 'Les gens sont libres, mais la ville est encore occupée par les Réprouvés. Ils sont coupés du gros de leurs troupes, donc si nous voulons les chasser, c\'est notre meilleure occasion.$B$BLeur chef, l\'exécuteur Cornell, est connu pour sa cruauté sans limites. Parmi eux, se trouve également Valnov le Fou, un soi-disant scientifique qui fait des expériences inhumaines sur les villageois trop âgés pour travailler aux mines.$B$BOccupez-vous d\'eux.', '', '', '', '', '', '', '', '', '', 'Retournez voir Lorna Crowley à l’Avant-poste de l’écurie.', 0),
(24677, 'frFR', 'Contourner les Réprouvés', 'Parlez au Seigneur Hewell pour obtenir un cheval qui vous mènera à l\'Avant-poste de l\'écurie, puis présentez-vous à Lorna Crowley.', 'Je vous remercie, $n. Mais nous ne pouvons pas nous reposer sur nos lauriers.$B$BNous avons découvert une ville minière qui est aujourd\'hui occupée par les Réprouvés. Nous avons envoyé quelques-uns de mes hommes ainsi que la fille de Crowley aux écuries de louage proches pour y lancer les opérations. Liam devrait bientôt les rejoindre.$B$BJe vais rester ici et organiser la campagne finale pour notre chère Gilnéas. Parlez au seigneur Hewell, il vous procurera un cheval qui vous mènera là-bas.', '', '', '', '', '', '', '', '', '', '', 0),
(24678, 'frFR', 'Jusqu\'au cou', 'Utilisez la Torche à moitié consumée pour traverser le tunnel sous Gilnéas.', 'Il est temps de faire vos bagages, $n. La plupart de nos concitoyens se sont enfuis, c\'est à votre tour, maintenant.$B$BPrenez cette torche, vous allez en avoir besoin. Le tunnel est infesté de bestioles dégoûtantes de la pire espèce. Utilisez la torche pour les maintenir à distance.$B$BUne fois de l\'autre côté, parlez à Krennan.', '', '', '', '', '', '', '', '', '', '', 0),
(24679, 'frFR', 'La bénédiction du patriarche', 'Placez les Offrandes bénies sur la Tombe d\'Aderic.', 'Vous avez réussi, $n. Même en ces temps troublés, nous devons honorer nos morts.$B$BPrenez ces offrandes et placez-les sur la tombe d\'Aderic.$B$BEspérons que cela suffira à apaiser les fantômes de nos ancêtres.', '', 'Offrande placée', '', '', '', '', '', '', '', 'Retournez voir Krennan Aranas au Repos d’Aderic en Gilnéas.', 0),
(24680, 'frFR', 'Quilleport', 'Parlez au Seigneur Darius Crowley à Quilleport en Gilnéas.', 'Nous avons peut-être perdu notre cité, mais au moins les morts semblent nous avoir pardonnés.$B$BRetrouvez les autres survivants à Quilleport.$B$BJe suis certain qu\'il y a encore beaucoup à faire avant d\'être hors de danger. Genn n\'est pas encore arrivé, donc je suppose que le seigneur Crowley sera le responsable sur place.', '', '', '', '', '', '', '', '', '', '', 0),
(24681, 'frFR', 'Ils ont des alliés, mais nous aussi !', 'Utilisez les Lanceurs de glaives des elfes de la nuit pour tuer 40 Écumeurs orcs, 8 Voltigeurs gueule-de-loup et 4 Machines de guerre orques.', 'Les elfes de la nuit ont tenu leur promesse. Ils ont fait venir des navires et sont prêts à nous offrir refuge sur leurs terres.$B$BMalheureusement, les Réprouvés ont eux aussi fait venir leurs alliés.$B$BLes orcs marchent vers nous tandis que les canonnières de la Horde empêchent les navires de transport de conduire notre peuple en sécurité.$B$BLes druides contiennent l\'ennemi, mais ils ne tiendront plus très longtemps. Heureusement, les navires des elfes transportaient des armes de siège. Prenez l\'un des lanceurs de glaives et attaquez l\'ennemi de front.', '', '', '', '', '', '', '', '', '', 'Retournez voir le Seigneur Darius Crowley à Quilleport, en Gilnéas.', 0),
(24684, 'frFR', 'Un Weezil dans la bergerie', 'Pénétrez dans le donjon de Bael’dun et tuez 10 Nains de Bael’dun (fusiliers, soldats ou officiers). Ensuite, trouvez Weezil Fluidombre, qui devrait être caché dans le donjon.', '<Gann vous attrape d’une main croûtée de sang.>$b$bMes plaies sont encore vives, mais je n’aurai de repos tant que les nains de Bael Modan n’auront pas payé pour leurs crimes. <Il prend une profonde inspiration sifflante.> Nous avons introduit un homme à nous dans la forteresse, lors de notre dernier raid. Un saboteur gobelin qui s’appelle Weezil Fluidombre.$b$bCréez une diversion à l’entrée. Tuez ceux que vous pouvez. Ensuite, glissez-vous dans la forteresse de Bael’Dun au sud et trouvez Weezil.$b$bCette place forte <TEUH !> ne peut être détruite que de l’intérieur et Weezil n’y arrivera pas tout seul.', '', 'Nains de Bael\'dun tués', '', '', '', '', '', '', '', 'Trouvez Weezil Fluidombre au Donjon de Bael\'dun, dans les Tarides du Sud.', 0),
(24685, 'frFR', 'La forteresse naine', 'Obtenir les Plans de la forteresse de Bael\'dun.', 'Je ne sais pas si vous l’avez remarqué en entrant, mais toute cette forteresse est bâtie autour d’un canon géant. Si nous trouvions l’entrepôt à munitions, nous pourrions rayer cet endroit de la carte en moins de temps qu’il n’en faut pour le dire !$b$bMais pour cela, je vais avoir besoin des plans de cette forteresse et je n’ai pas encore réussi à les voler.$b$bCherchez les plans à l’étage le plus bas. Vous n’avez qu’à descendre ces escaliers, juste là.', '', '', '', '', '', '', '', '', '', 'Retournez voir Weezil Fluidombre au Donjon de Bael\'dun, dans les Tarides du Sud.', 0),
(24686, 'frFR', 'Porté par les vagues', 'Utilisez le Filet de Garl pour obtenir 4 Graines de flagellant d’Un’Goro.', 'Les pétales-de-sang d’Un’Goro ont un cycle de vie fascinant.$b$bCes arbres devant nous portent des graines qui tombent dans la rivière, une fois arrivées à maturité. Le courant les emporte alors vers le nord, où les graines éclosent, presque comme des œufs, et donnent naissance à un nouveau pétale-de-sang.$b$bJ’ai besoin de ces graines pour mes travaux. Prenez ce filet et utilisez-le pour puiser les graines orange vif dans la rivière. Vous devrez plonger pour les trouver.', '', '', '', '', '', 'Ces minuscules spores sont portées par les courants de profondeur.', 'Graine de flagellant', '', '', 'Retournez voir Garl Grifforage au Cratère d\'Un\'Goro.', 0),
(24687, 'frFR', 'Des bouquets de mort', 'Tuez 6 Meutes de Flagellants juvéniles.', 'Vous connaissez déjà la première phase du cycle de reproduction des pétales-de-sang : le flottage des graines. Cependant, la phase suivante, la meute de pousses, est loin d’être aussi paisible.$b$bQuand les pétales-de-sang germent, ils se regroupent rapidement en meutes et se déplacent toujours en groupe, de manière à compenser leur faiblesse individuelle par la force du nombre. Ces meutes de jeunes flagellants sont généralement assez farouches, mais si vous en bousculez un, c’est toute la meute que vous bousculez.$b$bPour notre sécurité à tous, réglez-leur leur compte. Ils poussent tout près, à l’ouest et au nord.', '', '', '', '', '', '', '', '', '', 'Retournez voir Ithis Gardelune dans la Fondrière.', 0),
(24689, 'frFR', 'Et vogue la graine', 'Faites votre rapport à Ithis Gardelune, dans les Jardins mouvants.', 'Ithis Gardelune est le druide elfe de la nuit qui m’a intronisé dans le Cercle cénarien. Il a dressé son camp au nord, près des falaises du bord oriental du cratère. Suivez le chemin des graines de pétale-de-sang et je gage que vous le trouverez à proximité.$b$bMes travaux s’intéressent uniquement aux graines et autres réactifs, mais les siens traitent de problèmes plus complexes. Si la flore d’Un’Goro vous intéresse vraiment, vous devriez aller lui rendre visite maintenant.', '', '', '', '', '', '', '', '', '', 'Faites votre rapport à Ithis Gardelune, dans les Jardins mouvants.', 0),
(24690, 'frFR', 'Coursembrase', 'Tuer Coursembrase.', 'Je ne suis toujours pas rassuré au sujet de ces élémentaires de feu, $n. Rendez-moi un dernier service : montez au sommet de la crête de la Fournaise et tuez l’élémentaire appelé Coursembrase. C’est le plus grand et le plus fort de tous les élémentaires de feu du cratère. Je dormirai mieux si je sais qu’il est six pieds sous terre.', '', '', '', '', '', 'Il brûle d’impatience de vous rencontrer.', 'Coursembrase', '', '', 'Retournez voir Williden Marshal au Camp retranché des Marshal.', 0),
(24691, 'frFR', 'De singuliers mets', 'Obtenez 96 Pattes de silithide.', 'Salut $gmec:ma belle;, ça vous dirait de vous faire un peu de blé ?$b$bJe tiens de source sûre que dans les milieux intéressés, on est prêt à payer CHER pour des pattes de silithide. Oui, vous avez bien entendu : des pattes de silithide ! Apparemment, c’est délicieux quand c’est bien cuit. Les silithides sont des genres de homards souterrains qui vivent juste au sud.$b$bLe problème, c’est qu’il me faudra une grosse quantité de pattes pour graisser celle des intermédiaires. Vous pensez pouvoir m’en obtenir huit douzaines ?', '', '', '', '', '', '', '', '', '', 'Retournez voir Quixxil au Camp retranché des Marshal.', 0),
(24692, 'frFR', 'Le petit colosse', 'Tuez le Petit colosse Gorishi.', 'Si vous êtes ici pour nous aider, vous pourrez peut-être vous occuper d’une menace urgente.$b$bAu sud se trouve la Balafre sinueuse, un avant-poste silithide grouillant de vermine, au beau milieu de la jungle. Vous ne pouvez pas le rater.$b$bL’un de mes éclaireurs m’a révélé que les silithides y élèvent un jeune colosse, dans leur chambre souterraine principale. Ils ont l’intention de le lâcher sur Un’Goro une fois qu’il aura atteint sa taille adulte !$b$bCela ne peut pas se produire, $n. Trouvez ce colosse et tuez-le.', '', '', '', '', '', 'Filez vous mettre à couvert lorsqu\'il commence à lancer Explosion de poison.', 'Petit colosse Gorishi', '', '', 'Retournez voir Hol\'anyee Marshal au Camp retranché des Marshal.', 0),
(24693, 'frFR', 'Le tertre Moussu', 'Présentez-vous à Gremix, au Tertre Moussu.', 'Ici, au camp retranché des Marshal, je ne peux pas exercer mon activité lucrative correctement sans éveiller les soupçons des scientifiques. Cependant, il y a un autre endroit où on pourrait avoir besoin de vos services.$b$bMon associé, Gremix, possède un camp, au nord-ouest, de l’autre côté du volcan. Il a un sens des affaires très aiguisé, et un flair encore meilleur que le mien. Je suis sûr qu’il vous trouvera de l’ouvrage, si vous n’avez pas peur de gagner de l’argent.', '', '', '', '', '', '', '', '', '', 'Présentez-vous à Gremix, au Tertre Moussu.', 0),
(24694, 'frFR', 'La terrasse du Façonneur', 'Parlez à l’Examinateur Un’Goro pour vous téléporter à la Terrasse du Façonneur, puis parlez à Nablya.', '<En regardant dans l’orbe en face de vous, vous entendez une voix.>$b$BLes pylônes de cristal ont été activés. Un nombre suffisant de cristaux a été rassemblé. Les conditions sont remplies. Nous sommes prêts pour la téléportation vers la terrasse du Façonneur.$b$bQuand vous êtes $gprêt:prête;, dites-le-moi, $r. Nous consulterons la Guetteuse.', '', '', '', '', '', '', '', '', '', 'Parlez à l’Examinateur Un’Goro pour vous téléporter à la Terrasse du Façonneur, puis parlez à Nablya.', 0),
(24695, 'frFR', 'Un point de vue olympien', 'Tirez les leviers derrière Nablya et réussissez ses tests.', 'Quand mon maître Khaz’goroth a créé le monde que vous appelez Azeroth, il a conçu le cratère d’Un’Goro comme un laboratoire d’expérimentation. On pourrait l’appeler la boîte de Petri des titans, si vous voulez.$b$bSi vous voulez connaître les méthodes que nous utilisons pour observer le monde, tirez les quatre leviers derrière moi et réussissez mes tests.', '', 'Observation du Pétale-de-sang', 'Observation du Dimeurtrodon', 'Observation du Gorille', 'Observation du Pterreurdactyle', '', '', '', '', 'Retournez voir Nablya au Hall de la quiétude.', 0),
(24697, 'frFR', 'L\'art d\'accommoder les restes', 'Utilisez les Morceaux de viande pourrissante afin d’attirer les dinosaures dans les pièges disposés autour du Camp retranché des Marshal.', 'Je ne pense pas vous avoir déjà $grencontré:rencontrée;… Je m’appelle Nolen Graillon, le nouveau chef-coq des gardes des expéditions Marshal. Je suis aussi leur chef tout court. Vous seriez $gsurpris:surprise; de la ressemblance entre les deux fonctions.$b$bJ’ai un chouette petit boulot pour vous. Vous avez vu les chausse-trapes autour du camp ? Voyez si vous pouvez convaincre quelques dinosaures de s’y jeter. Si vous leur jetez cette viande avariée, ça les rendra soit furieux, soit affamés. Ça ne fait pas une grande différence, du moment qu’ils vous suivent dans le piège !', '', 'Dinosaures appâtés', '', '', '', '', '', '', '', 'Retournez voir Nolen Graillon au Camp retranché des Marshal.', 0),
(24698, 'frFR', 'Des aventures archéologiques', 'Faites votre rapport à Étincelle Minerien, aux Sources de Golakka.', 'Hé, vous voulez goûter mes nouveaux hot-dogs au dimeurtrodon ? Non ? Du risotto de raptor non plus ? Des ptacos au pterreurdactyle, alors ?$b$bD’accord. Oh, ça me revient, maintenant ! J’ai un ami dans le coin, qui pourrait avoir besoin de votre aide. Il s’appelle Étincelle Minerien et c’est le président-archéologue général des Expéditions Marshal.$b$bIl a été envoyé aux sources de Golakka, à l’ouest. Vous le trouverez sûrement sur la rive occidentale des sources.', '', '', '', '', '', '', '', '', '', 'Faites votre rapport à Étincelle Minerien, aux Sources de Golakka.', 0),
(24699, 'frFR', 'Gormashh le glutineux', 'Tuez Gormashh et obtenez le Goudron incroyablement collant.', 'Ça y est, je sais ! On s’est trompés de source de goudron.$b$bUn jour, Gremix m’a dit qu’il avait vu une créature goudronneuse plus grande que la normale. Elle rôde près du puits à goudron loin à l’est, au sud du rocher Fongique. Je parierais que plus ces bêtes sont grandes, plus leur goudron est collant ! Là, on va s’en mettre plein les poches, $n !$b$bN’oubliez pas le racloir !', '', '', '', '', '', 'Essayez de le tuer sans le toucher, si possible.', 'Gormashh', '', '', 'Retournez auprès de Tara, au Tertre Moussu.', 0),
(24700, 'frFR', 'Une récolte ardue', 'Obtenez 4 Fleurs de goudronelle.', 'Les fosses de goudron de Lakkari, au nord, recèlent un trésor caché : des fleurs rares qui ne poussent qu’au fond de ces puits. Ces goudronelles, puisque c’est leur nom, sont recherchées pour leur beauté et leur durabilité. Ma dernière récolte de goudronelles date d’un certain temps, donc de nouvelles fleurs doivent avoir repoussé au fond des puits. Vous voulez bien aller m’en chercher ?$b$bAu fait, bonne chance pour nager dans le goudron. Ça n’a rien à voir avec l’eau.', '', '', '', '', '', '', '', '', '', 'Retournez voir Tara au Tertre Moussu.', 0),
(24701, 'frFR', 'Le rebut des Marshal', 'Obtenez 10 Fournitures abandonnées.', 'Une condition à l’enrichissement personnel est l’absence de scrupules. Vous devez être $gprêt:prête; à profiter du malheur des autres. En fin de compte, ça revient à une simple question : À quel point aimez-vous l’argent ?$b$bQuand Marshal et son équipe ont abandonné leur refuge au nord, ils y ont laissé des tas de fournitures. Ce ne sont pas des denrées rares, ni même particulièrement précieuses, mais elles sont là, à la portée de qui veut bien les prendre. Son camp est en haut des collines, au nord.$b$bOh, et faites attention. S’ils sont partis, c’est qu’il doit y avoir une raison…', '', '', '', '', '', '', '', '', '', 'Retournez voir Doreen au Tertre Moussu.', 0),
(24702, 'frFR', 'Ci-gît Dadanga', 'Obtenez 10 Pousses de pétale-de-sang.', '', '', '', '', '', '', '', '', '', '', 'Retournez à la Tombe de Dadanga, au Refuge des Marshal.', 0),
(24703, 'frFR', 'Une importante leçon', 'Parlez à Maximillian de Comté-du-Nord pour savoir comment devenir son $gécuyer:écuyère;.', 'Hola, $gvoyageur:voyageuse; ! Sachez que vous venez d’empiéter sur le camp de Maximillian de Comté-du-Nord ! Peut-être avez-vous eu vent de mes nombreux exploits ? À voir votre expression, j’en déduis que oui. Cette étincelle d’admiration se voit dans votre regard comme la Dame Blanche se reflète sur le lac du Cairn.$b$bIl me paraît évident que vous cherchez l’aventure, et comme vous me semblez assez $gdégourdi:dégourdie; et de bonne volonté, je vous permets de devenir mon $gécuyer:écuyère;.', 'Entraînement terminé', '', '', '', '', '', '', '', '', 'Retournez voir Maximillian de Comté-du-Nord, aux Sources de Golakka.', 0),
(24704, 'frFR', 'Les vils dragons d\'Un\'Goro', 'Aidez Maximillian de Comté-du-Nord à tuer 15 « Dragons ».', 'Ce cratère regorge de dragons d’une espèce maligne. Les avez-vous vus ? Ils déambulent en affichant ostensiblement leurs échines épineuses et leurs faciès de lézards aux quatre coins du cratère.$b$bNe soyez pas dupe, $gécuyer:écuyère;, car ces dragons ne sont en aucune manière les rejetons de la gracieuse Alexstrasza. Ils sont manifestement vicieux et justes bons à exercer le bras d’un héros.$b$bJ’ai décidé d’en occire pas moins d’une quinzaine. Vous êtes mon $gécuyer:écuyère; vous m’accompagnerez donc. Si nous sommes séparés, vous me retrouverez aux sources.', '', '', '', '', '', '', '', '', '', 'Allez parler à Maximillian à son camp des Sources de Golakka. Si vous courez déjà l’aventure avec lui, vous devez d’abord lui parler puis le renvoyer.', 0),
(24705, 'frFR', 'Recherche damoiselle en détresse', 'Sauver la Damoiselle près de la côte, la Damoiselle sur les falaises et la Damoiselle du nord.', 'J\'ai l\'impression que nous allons trouver bien plus que des dragons dans ce cratère. Mon instinct de paladin me souffle que des jeunes femmes requièrent notre aide dans les environs. Mon cœur ne bat que pour ma dame Doloria, mais une damoiselle en détresse ne peut pas être ignorée.$b$bEn route, $gécuyer:écuyère; $n ! Nous devons venir en aide aux dames d\'Un\'Goro !', '', 'Damoiselle près de la côte sauvée', 'Damoiselle sur les falaises sauvée', 'Damoiselle du nord sauvée', '', '', '', '', '', 'Allez parler à Maximillian à son camp des Sources de Golakka. Si vous courez déjà l’aventure avec lui, vous devez d’abord lui parler puis le renvoyer.', 0),
(24706, 'frFR', 'Les esprits des sources de Golakka', 'Observez Maximillian de Comté-du-Nord parler à 2 Furies de vapeur.', 'Un peu de sérieux, maintenant, $n. Une mission importante s’offre à nous. Les perfides dragons qui tourmentent cette vallée continueront leurs exactions tant que nous n’aurons pas détruit leur répugnante matriarche. Mais avant même de tenter pareille entreprise, nous devons solliciter l’aide de la Lumière.$b$bJe l’ai vue se manifester sous la forme d’esprits, flottant non loin des rives des sources de Golakka. Venez, je dois leur demander leur aide.', '', 'Prières', '', '', '', '', '', '', '', 'Allez parler à Maximillian à son camp des Sources de Golakka. Si vous courez déjà l’aventure avec lui, vous devez d’abord lui parler puis le renvoyer.', 0),
(24707, 'frFR', 'La ballade de Maximillian', 'Aidez Maximillian de Comté-du-Nord à tuer la Reine diablosaure. Si vous êtes $gséparé:séparée; de Maximillian, retrouvez-le aux Sources de Golakka, au Cratère d’Un’Goro.', 'Voici venu le moment que nous attendions, $gécuyer:écuyère; $n. La matriarche d’Un’Goro va périr de mes mains. La gravité de la tâche pèse lourdement sur mes épaules, mais avec le pouvoir de la Lumière de notre côté, nous sommes assurés de triompher.$b$bÊtes-vous $gprêt:prête; à partir ?', '', 'Mère des couvées d\'Un\'Goro tuée', '', '', '', '', '', '', '', 'Retournez voir Maximillian de Comté-du-Nord aux Sources de Golakka, dans le Cratère d\'Un\'Goro.', 0),
(24708, 'frFR', 'Le détec-fossiles 3000', 'Obtenir une Griffe de dinosaure énorme.', 'Une des choses que je déteste le plus dans l’archéologie, c’est que la moitié du temps, on est couvert de boue. C’est pourquoi j’ai passé pas mal de temps à bricoler au lieu de creuser.$b$bEt regardez ce que j’ai inventé : le détec-fossiles 3000. Je viens juste d’y mettre la dernière main. S’il fonctionne comme prévu, il devrait nous permettre de trouver les plus gros fossiles de la région. Je sais, c’est sympa, hein ?$b$bTestez-le et voyez si vous pouvez trouver des os de dinosaure géants.', '', '', '', '', '', '', '', '', '', 'Retournez voir Étincelle Minerien aux Sources de Golakka.', 0),
(24709, 'frFR', 'Un conte de deux pelles', 'Tuez Durrin Mornepelle et récupérez ses Découvertes archéologiques.', 'Hé, attendez un instant, il y a des coups de pioche sur cet os. Ce n’est pas vous qui les avez faits, au moins ? Non, je crois reconnaître les empreintes… Ce doit encore être ce maudit nain ! Pouah !$b$bLaissez-moi vous raconter toute l’histoire. Il y a un autre archéologue, au sud. Il s’appelle Durrin Mornepelle. C’est un adepte de l’archéologie anarchique et irrespectueuse. Il est encore pire que moi !$b$bUn fossile unique, complètement gâché par un coup de pioche de jean-foutre. C’est la goutte d’eau, Durrin !$b$b$n, allez faire cesser Mornepelle et son excavation sans scrupules.', '', '', '', '', '', 'L’archéologie par-dessus la jambe mérite un châtiment exemplaire.', 'Durrin Mornepelle', '', '', 'Retournez voir Étincelle Minerien aux Sources de Golakka.', 0),
(24714, 'frFR', 'À la poursuite d\'A-Mi 01', 'Trouvez A-Mi 01 au Rocher fongique.', 'Il est malheureusement arrivé quelque chose à l\'une de mes plus grandes inventions. Vous avez déjà vu des écureuils mécaniques, pas vrai ? Eh bien, afin de m\'approcher des singes du cratère d’Un\'Goro et de me mêler à eux, j\'ai créé une guenon mécanique. Je l’ai appelée A-Mi 01.$B$BCela fait plusieurs mois qu’elle étudie la faune et la flore locales près du rocher Fongique, mais elle n’est toujours pas revenue alors que sa mission est terminée. Je crains le pire.$b$bPouvez-vous m’aider à la retrouver ?', '', '', '', '', '', 'Un primate préprogrammé', 'A-Mi 01', '', '', 'Allez voir A-Mi 01 au Cratère d\'Un\'Goro.', 0),
(24715, 'frFR', 'Réparer A-Mi 01', 'Vous êtes à peu près $gcertain:certaine; qu’A-Mi 01 vous a demandé de trouver une noix de coco, de l’ouvrir sur un rocher, et de lui donner le lait de coco à haute viscosité.', '<Tout à coup, les yeux du gorille-robot s’allument, tandis qu’il se met à parler.>$b$b« …capacité opérationnelle… inférieure à 5%… fuite accidentelle… au réservoir d’huile… »$b$b« Utilisez lait de coco… rocher… sauvez A-Mi 01… »$b$b<A-Mi referme les yeux.>', '', '', '', '', '', '', '', '', '', 'Retournez voir A-Mi 01 au Rocher fongique.', 0),
(24716, 'frFR', 'Ramener A-Mi 01', 'Escortez A-Mi 01 jusqu’à Karna Songerrance, au Tertre Moussu.', 'Salutations. Moi, unité A-Mi 01. Vous… $r ?$B$BMission A-mi : étudier gorilles locaux. Mission réussie. A-mi a récolté données et maintenant, les apporter à Karna.$b$bMaintenant, temps de retourner près Karna. Vous venir ? Nous partir tout de suite si vous être $gprêt:prête;.', '', 'Protéger A-Mi 01 jusqu\'à avoir rejoint Karna Songerrance', '', '', '', '', '', '', '', 'Retournez auprès de Karna Songerrance au Tertre Moussu.', 0),
(24717, 'frFR', 'Les gorilles d\'Un\'Goro', 'Apportez 2 Peaux de gorille d’Un’Goro, 2 Peaux d’Écrabouilleurs d’Un’Goro et 2 Peaux de Foudroyeur d’Un’Goro à Gremix, au Tertre Moussu.', 'Il y a beaucoup d’argent à se faire, à Un’Goro. Il suffit de savoir où regarder !$b$bLes singes sont très répandus ici, mais ils sont bien plus rares dans le nord. À Long-Guet, une peau de gorille se vend dix fois plus cher qu’ici !$b$bJe ne vais pas vous envoyer au Berceau-de-l’Hiver, ce ne serait pas raisonnable, mais par contre, vous pourriez m’aider à obtenir des peaux.$b$bVous trouverez des gorilles au rocher Fongique, au nord-est, près d’une cascade. N’oubliez pas d’aller voir dans la grotte !', '', '', '', '', '', '', '', '', '', 'Retournez voir Gremix au Tertre Moussu.', 0),
(24718, 'frFR', 'Le puissant U\'cha', 'Apportez la Peau d\'U\'cha à Gremix, au Tertre Moussu.', 'En regardant autour de vous, vous remarquez que le sol de cette partie de la grotte est jonché de touffes de poils roux ressemblant à ceux d’un gorille.$b$bD’après vos conversations avec Gremix, vous savez que si jamais vous trouviez une peau de gorille roux, il serait certainement preneur.', '', '', '', '', '', 'Dans votre imagination, voilà ce qui ressemble le plus à un gorille rouge.', 'Le puissant U’cha', '', '', 'Retournez voir Gremix au Tertre Moussu.', 0),
(24719, 'frFR', 'Des griffes blanches', 'Obtenez 5 Griffes blanches de ravasaure.', 'Attendez, $r. J’aurais besoin de l’aide d’$gun:une:c; $c $gtel:telle:c; que vous.$b$bJuste en dehors de ce camp se trouvent des raptors aux griffes mortelles. J’ai essayé d’utiliser ces griffes dans mes rituels druidiques, mais elles ne semblent pas fonctionner. Cependant, j’ai remarqué que certains raptors ont des griffes blanches, alors que la plupart ont des griffes noires comme la mort.$b$bLes mystères de la terre sont insondables. Peut-être pourriez-vous me trouver quelques griffes blanches pour que je tente un dernier rituel ?', '', '', '', '', '', '', '', '', '', 'Retournez voir Garl Grifforage au Cratère d\'Un\'Goro.', 0),
(24720, 'frFR', 'Cristaux de puissance', 'Récupérer 7 Cristaux de puissance de chaque couleur (rouge, bleu, jaune et vert).', 'Je suis sûre que vous les avez remarqués, $n. Il y en a partout !$b$bDe quoi je parle ?? Mais des cristaux, bien sûr !$b$bLes cristaux… Ils sont partout dans le cratère. La plupart des gens les ignorent, mais j’ai l’étrange impression qu’ils détiennent une sorte de pouvoir.$b$bDites, mes niveaux de cristaux commencent à baisser dangereusement. Vous pensez pouvoir m’en récolter quelques-uns ?$b$bVous trouverez des cristaux jaunes au nord-ouest, des cristaux rouges au… mais je ne doute pas que vous trouverez bien $gtout seul:toute seule; !', '', '', '', '', '', '', '', '', '', 'Retournez voir J. D. Collie au Camp retranché des Marshal.', 0),
(24721, 'frFR', 'Le Pylône est', 'Touchez le Pylône de cristal est dans le Cratère d’Un’Goro.', 'Loin dans les falaises au-dessus de moi, il y a un grand pylône de cristal. Je ne saurais dire qui l’a construit, ni pourquoi l’avoir construit à cet endroit précis.$b$bPeut-être que vous pourrez trouver les réponses à ces questions. Personnellement, je n’en ai rien à faire, donc ne vous sentez pas $gobligé:obligée; de venir me faire votre rapport. Par contre, un des érudits au camp retranché des Marshal sera peut-être intéressé par ce que vous aurez découvert.', 'Trouvez et examinez le Pylône de cristal est', '', '', '', '', '', '', '', '', 'Faites votre rapport à J.D. Collie, au Camp retranché des Marshal.', 0),
(24722, 'frFR', 'Le Pylône nord', 'Localisez le Pylône de cristal nord au Cratère d’Un’goro.', 'Vous nous avez rendu un certain nombre de services, $n… Maintenant, permettez à Gremix de vous rendre la pareille. Les attaques menées sur le refuge des Marshal ont été terribles, sans aucun doute. Les assaillants ont agi par surprise et n’ont pas fait de prisonniers. Les hommes des Marshal ont de la chance qu’il y ait eu si peu de morts.$b$bIl y a quelques semaines, j’ai découvert un pylône de cristal dans les falaises au nord-est d’ici, à l’est du refuge des Marshal. Je pense qu’il peut être lié aux attaques. Vous pourriez mener votre enquête ? Je suis sûr que quelqu’un au camp retranché des Marshal vous récompensera.', 'Trouvez et examinez le Pylône de cristal nord', '', '', '', '', '', '', '', '', 'Faites votre rapport à J.D. Collie, au Camp retranché des Marshal.', 0),
(24723, 'frFR', 'Le Pylône ouest', 'Localisez le Pylône de cristal ouest.', 'Les travaux de Durrin concernaient un sujet qui m’intrigue : un lien possible entre les titans et les dinosaures. Au camp, J. D. Collie nous rabâche sans cesse les oreilles avec ses titans et ses cristaux… sans doute que ça l’intéresserait.$b$bAvant d’aller lui faire votre rapport, vous devriez peut-être aller voir le pylône de cristal, tout près d’ici. Il se trouve juste en haut des falaises, à l’ouest. Il y a des cristaux dessus et il m’a toujours semblé avoir un rapport quelconque avec les titans.', 'Trouvez et examinez le Pylône de cristal ouest', '', '', '', '', '', '', '', '', 'Faites votre rapport à J.D. Collie, au Camp retranché des Marshal.', 0),
(24724, 'frFR', 'Cristal de restauration', '', '', '', '', '', '', '', '', '', '', '', 'Retournez au Pylône de cristal nord, dans le Cratère d\'Un\'Goro.', 0),
(24725, 'frFR', 'Cristal d\'explosion', '', '', '', '', '', '', '', '', '', '', '', 'Retournez au Pylône de cristal nord, dans le Cratère d\'Un\'Goro.', 0),
(24726, 'frFR', 'Cristal de concentration', '', '', '', '', '', '', '', '', '', '', '', 'Retournez au Pylône de cristal est, dans le Cratère d\'Un\'Goro.', 0),
(24727, 'frFR', 'Cristal de rétribution', '', '', '', '', '', '', '', '', '', '', '', 'Retournez au Pylône de cristal est, dans le Cratère d\'Un\'Goro.', 0),
(24728, 'frFR', 'Cristal de protection', '', '', '', '', '', '', '', '', '', '', '', 'Retournez au Pylône de cristal ouest en Silithus.', 0),
(24729, 'frFR', 'Cristal de réduction', '', '', '', '', '', '', '', '', '', '', '', 'Retournez au Pylône de cristal ouest en Silithus.', 0),
(24730, 'frFR', 'Faites rouler les os', 'Obtenez 8 Os de dinosaure.', 'On pourrait penser qu\'être chef terrassier pour les Expéditions Marshal signifie que j\'aime creuser. Il y a des choses bien plus désagréables à faire en ce monde… mais aucune ne me vient à l\'esprit.$B$BNous étions supposés creuser dans les Coteaux de la terreur - quel nom FANTASTIQUE, soit dit en passant - à la recherche de stégodons et de dimeurtrodons morts ! Eh bien, figurez-vous qu\'il en reste aussi beaucoup de vivants ! Wil et Hol insistent encore pour étudier ce piège mortel, alors nous devons ramener ces os de dinosaures. Entre vous et moi, s\'ils proviennent de créatures vivantes, ils feront tout aussi bien l\'affaire.', '', '', '', '', '', '', '', '', '', 'Retournez voir Étincelle Minerien aux Sources de Golakka.', 0),
(24731, 'frFR', 'La nourriture de Lar\'korwi', 'Trouvez la carcasse de la dernière proie tuée par Lar’korwi et volez un Morceau de carcasse d’un battrodon.', 'Il y a très longtemps, un de mes frères a volé de la viande sur une des proies de Lar’korwi. Il ne le savait pas à l’époque, mais Lar’korwi était tapi dans la forêt et l’a vu faire. Il a traqué mon frère pendant des jours et des jours, détruisant tout sur son passage. Mon frère, terrorisé, a fini par quitter le cratère pour semer Lar’korwi.$b$bLa bête l’a tué tout près d’où nous sommes.$b$bSi vous voulez provoquer Lar’korwi, trouvez une proie qu’il vient de tuer et prélevez-y de la viande.$b$bCommencez à chercher à l’ouest.', '', '', '', '', '', '', '', '', '', 'Retournez voir Torwa le Guide dans le Cratère d\'Un\'Goro.', 0),
(24732, 'frFR', 'Un parfum pour Lar\'korwi', 'Obtenez 2 Glandes de phéromone de ravasaure.', 'Cela me surprend qu\'il ne soit pas encore venu s\'occuper de vous, $n. Mais tout va bien, car j\'ai une dernière idée pour attirer le monstre.$B$BEn tant que mâle dominant, il a le droit de s\'accoupler avec n\'importe quelle femelle. Et il en choisit beaucoup. Vous trouverez de nombreux œufs de ravasaure à l\'ouest d\'ici. Approchez-vous-en et vous provoquerez l’attaque de ses compagnes. Les femelles possèdent dans la tête une glande qui secrète une affreuse odeur. Elle sert à avertir les mâles quand la reproduction est possible. Apportez-moi deux de ces glandes.', '', '', '', '', '', '', '', '', '', 'Retournez voir Torwa le Guide dans le Cratère d\'Un\'Goro.', 0),
(24733, 'frFR', 'Un appât pour Lar\'korwi', 'Faites se manifester Lar’korwi grâce au contenu de la Sacoche de Torwa et tuez-le. Ensuite, apportez la Tête de Lar’korwi à Torwa le Guide, près de l’entrée du Cratère d’Un’Goro.', 'Nous en arrivons à la partie la plus épineuse du plan. Continuez à suivre la rivière vers le nord, et arrêtez-vous quand vous arriverez à un méandre. C’est là que j’ai vu Lar’korwi pour la dernière fois. Vous saurez que vous y êtes quand vous verrez tous les ossements des grandes créatures qui peuplaient la région auparavant. Prenez la viande que vous avez récupérée et placez-la près du méandre. Ensuite, frottez la viande avec cette mixture de ma composition.$b$bSi ces deux appâts combinés n’attirent pas Lar’korwi, je ne sais pas ce qui l’attirera.', '', '', '', '', '', 'Il n’y a qu’une seule chose que Lar’korwi aime plus que la viande : les femmes.', 'Lar’korwi', '', '', 'Retournez voir Torwa le Guide dans le Cratère d\'Un\'Goro.', 0),
(24734, 'frFR', 'Perdu !', 'Trouvez la trace de Ringo à la Crête de la fournaise.', 'Vous devez m’aider, $n ! Mon ami Ringo est parti explorer le volcan au nord, et il devrait être revenu depuis longtemps. Je suis vraiment inquiète à son sujet.$B$BPensez-vous que vous pourriez le retrouver ? Tenez, prenez ma gourde. Si vous trouvez Ringo, je suis sûre qu’il en aura besoin !', '', '', '', '', '', '', '', '', '', 'Trouvez des signes de Ringo sur la Crête de la Fournaise.', 0),
(24735, 'frFR', 'Un peu d\'aide de mes amis', 'Amenez Ringo jusqu’à Spraggle Frock, au Camp retranché des Marshal.$B$BSi Ringo faiblit, giflez-le. S’il tourne de l’œil, utilisez la Gourde de Spraggle pour lui faire reprendre connaissance.', 'Wouf… Il fait tellement chaud…$B$BJ\'explorais le secteur lorsque soudain, la chaleur est devenue insupportable. Je dois souffrir d\'insolation.$B$BJe vous en prie, aidez-moi à retourner auprès de mon amie Spraggle au camp retranché des Marshal. Je pense que je vais encore suffisamment bien pour être capable de vous suivre jusque là-bas.$B$BJe ne me sens pas vraiment en grande forme, cependant, alors si je devais m\'évanouir à nouveau, renversez-moi de l\'eau de la gourde de Spraggle dessus. Ça devrait marcher, j\'espère...', 'Escortez Ringo jusqu\'au Camp retranché des Marshal', '', '', '', '', '', '', '', '', 'Retournez voir Spraggle Frock au Camp retranché des Marshal.', 0),
(24736, 'frFR', 'La machine volante de Shizzle', 'Collectez 35 Ecailles étoilées de pterreurdactyle.', 'Je construis une machine volante !$b$bJe suis bloqué ici et mon sens de l’orientation est lamentable. Je prendrais bien un griffon ou un coursier du vent pour retourner à Gadgetzan, mais j’ai une frousse bleue de ces animaux.$b$bVous allez m’aider, n’est-ce pas ? Il ne me reste plus qu’à construire les ailes, et je me disais que des écailles étoilées de pterreurdactyle feraient parfaitement l’affaire. Il n’y a aucune chance que j’aille les chercher moi-même, mais vous, vous avez l’air plutôt apte, non ? Pourquoi vous ne vous en occuperiez pas ? Vous trouverez des pterreurdactyles aux confins Hurlants, à l’ouest.', '', '', '', '', '', '', '', '', '', 'Retournez voir Shizzle au Tertre Moussu.', 0),
(24737, 'frFR', 'Ultra collant', 'Collectez 8 échantillons de Goudron ultra collant.', 'Je suis toujours à l’affût d’une occasion de gagner de l’argent rapidement, $n. Si vous m’aidez dans ma dernière entreprise, je vous intéresserai aux bénéfices. Qu’est-ce que vous en dites ?$B$BIl me semblait bien !$B$BOn va fabriquer de la colle. Allez aux puits à goudron, juste au nord, et collectez-moi du goudron. Mais pas n’importe lequel, je veux que vous le récoltiez sur les créatures qui vivent près des puits. Pour vous faciliter la tâche, utilisez mon racloir à goudron et vous ne vous salirez pas les mains.', '', '', '', '', '', '', '', '', '', 'Retournez auprès de Tara, au Tertre Moussu.', 0),
(24740, 'frFR', 'Activité volcanique', 'Collectez 9 échantillons de Cendres d\'Un\'Goro sur les Élémentaires de feu autour du volcan du Cratère d\'Un\'Goro.', 'Bienvenue. Je m’appelle Williden Marshal et ma sœur et moi, nous dirigeons cette expédition scientifique et d’exploration. Vous avez un instant ?$b$bJe n’aime pas la trogne des élémentaires de ce volcan, $c. Nous avons trop d’équipements, trop de notes, ici… Si l’envie lui en prenait, un seul élémentaire pourrait ravager notre camp et causer des dégâts vraiment terribles.$b$bMontrez-leur qu’ils n’ont pas intérêt à chercher des noises à leurs nouveaux voisins. Et rapportez-moi leurs cendres… Autant en profiter pour faire un peu de recherche, tant qu’on y est.', '', '', '', '', '', '', '', '', '', 'Retournez voir Williden Marshal au Camp retranché des Marshal.', 0),
(24741, 'frFR', 'Un échange en notre faveur', 'Rassemblez 5 Œufs de raptor épineux.', 'Hobart pense vraiment pouvoir nous nourrir avec ces ridicules œufs de poule ? Bon, nous allons avoir besoin de vrais œufs !$B$BJ\'ai déjà posé quelques pièges sur la cime des Raptors au bout du chemin à l\'est. Prenez ces œufs de poule sauvage et placez-les dans les pièges. Les raptors épineux vont se précipiter sur les œufs de poule, que vous pourrez alors échanger contre leurs œufs, bien plus gros.$B$BC\'est génial !', '', '', '', '', '', '', '', '', '', 'Retournez voir Bamm Mégabombe à Ville-en-Boîte, sur les Îles Perdues.', 0),
(24742, 'frFR', 'À la recherche de la source', 'Krakle, au Cratère d’Un’Goro, veut que vous trouviez la zone la plus chaude de la Crête de la Fournaise.$b$bQuand vous trouvez un point chaud, utilisez le thermomètre pour en mesurer la température. Continuez vos relevés jusqu’à trouver le point le plus chaud.', 'J’ai conçu un thermomètre capable de mesurer la température du volcan, dans le but de trouver les courants de lave les plus chauds. Il lit la température en degrés Kraklenheit !$b$bTenez, prenez-le et relevez les températures le long de la crête partout où vous verrez un point chaud !$b$bGénéralement, les points chauds se manifestent sous la forme d’une colonne de roche incandescente jaillissant du sol. Vous en trouverez à la périphérie de la base de la crête de la Fournaise… Un tour de cratère devrait donner suffisamment de relevés.', '', 'Trouver la zone la plus chaude de la Crête de la Fournaise', '', '', '', '', '', '', '', 'Retournez voir Krakle au Camp retranché des Marshal.', 0),
(24744, 'frFR', 'Le plus gros œuf du monde', 'Ramasser le Plus gros œuf du monde.', 'Bamm Mégabombe ? Mais pour qui se prend-il ? Ses œufs de raptor sont ridicules comparés à ce que nous allons bientôt récupérer !$B$BComme vous le savez, chaque Ville-en-Boîte est équipée d’un micro-mécapoulet pour les urgences alimentaires de ce type. Heureusement pour nous, ma grande intelligence m’a permis de déduire l’emplacement où a fui notre prodigieuse volaille pré-programmée.$B$BDirigez-vous vers le goulet Incendié au nord. Mais faites attention, ses circuits ont dû griller et j’ai bien peur que le poulet ne soit plus si micro que ça, maintenant !', '', '', '', '', '', 'Trouvez le plus gros œuf du monde', 'Mécapoulet', '', '', 'Retournez voir Hobart Martelutte à Ville-en-Boîte, sur les Îles Perdues.', 0),
(24747, 'frFR', 'Sabotage !', 'Sabotez un Obus d’artillerie nain et échappez-vous de Bael’Dun avant que tout n’explose.', 'Ces obus d’artillerie nains ont une fusée chronométrique intégrée. C’est l’enfance de l’art ! Il suffit de saboter l’un des projectiles d’artillerie dans le quai de chargement et de l’insérer dans le chargeur. Et Boum ! que ça fait, BOUM !$b$bVous trouverez les obus dans l’un des deux quais de chargement derrière le garage principal, à ce niveau-ci. C’est à deux pas.$b$bUne fois que vous aurez chargé l’obus… Courez ! Courez comme $gun dératé:une dératée;, $n ! Ensuite, retournez au camp faire votre rapport à Gann. Je serai juste derrière vous.', '', 'Obus d\'artillerie saboté', 'Sortez d\'ici ! Tout va sauter !', '', '', '', '', '', '', 'Faites votre rapport à Gann Cime-de-pierre à Fer-de-lance, dans les Tarides du Sud.', 0),
(24750, 'frFR', 'L\'ascension des Sombrelances', 'Allez voir Soratha sur le Terrain d’entraînement des Sombrelances.', 'Nous autres Sombrelances, on a longtemps été des victimes. Des parias. On a dû fuir notre foyer, encore et encore… mais cette fois-ci, c’est pas pour fuir qu’on est là.$B$BVol’jin, il nous gouverne avec sagesse, et c’est ça qui nous a gardés en vie si longtemps. Et maintenant, avec sa sagesse, il voit que la Horde sous les ordres de Garrosh Hurlenfer, elle a un avenir chaotique.$B$BNon, cette fois, on ne fuit pas. Cette fois, on se bat pour rester chez nous.$B$BIl est temps de commencer votre formation, $n. Parlez à Soratha, à l’est.', '', '', '', '', '', '', '', '', '', '', 0),
(24751, 'frFR', 'La base : savoir frapper des trucs', 'Détruire 6 Cibles Tiki.', 'D\'accord d\'accord, $gmon pote:ma grande;. On va commencer petit. Faut que j’m’assure que vous maîtrisez les bases des arts arcaniques.$B$BAllez m’casser des cibles tiki. En douceur. Naturellement. J’vais vous regarder lancer vos sorts, et on partira d’là.', '', '', '', '', '', '', '', '', '', 'Retournez voir Soratha au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24752, 'frFR', 'Les arts du mage', 'Atteignez le Niveau 3 pour apprendre la Nova de givre, puis utilisez-la à 2 reprises contre une Cible Tiki.', 'Quand vous aurez développé vot’ pouvoir, vous vous r’trouverez avec de nouveaux sorts, et de nouvelles façons d’utiliser les arcanes.\n\nAllez, apprenez des trucs, et revenez m’faire une démonstration.', '', 'S’exercer à la Nova de givre', '', '', '', '', '', '', '', 'Retournez voir Soratha au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24753, 'frFR', 'Un début difficile', 'Récupérez 6 Peaux de félins crin-sauvage.', 'Bon, ben $gmon pote:ma grande;, on va s’servir de ces compétences, en commençant par un truc qu’il sera facile.$B$BY a des fauves qui tuent nos sangliers. Not’bouffe, on la partage pas. Si vous voulez grailler ce soir, faut que ces sangliers, ils soient en vie.$B$BY en a sur toute l’île. Amenez-moi des peaux de félins.', '', '', '', '', '', '', '', '', '', 'Retournez voir Soratha au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24754, 'frFR', 'La fosse de l\'épreuve', 'Parlez à un Geôlier sombrelance, puis descendez dans la fosse de l\'épreuve et tuez un Éclaireur Vexécaille captif.', 'Vous vous en sortez bien, $c. Oh, pas d’doute, j’peux encore vous apprendre un ou deux trucs, mais j’serais vous, j’perdrais plus mon temps sur les cibles tiki.$B$BAlors, j’ai une autre épreuve pour vous, $gmon pote:ma grande;. Vous allez jusqu’à la fosse de l’épreuve, là au milieu, et vous vous battez contre un vrai méchant, un qui va s’défendre et vouloir vous tuer. Quand vous serez $gprêt:prête;, vous le dites juste au geôlier, au bord d’la fosse.', '', 'Parlez à un Geôlier sombrelance', '', '', '', '', '', '', '', 'Retournez voir Soratha au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24755, 'frFR', 'Mieux que prévu', 'Présentez-vous à Vol\'jin au Bastion des Sombrelances.', 'Y a plus en vous qu’on n’en attendait, $gmon pote:ma grande;. On doit sûrement avoir des trucs plus importants à vous faire faire. Z’avez plus besoin de traîner ici avec les autres p’tits nouveaux.$B$BAllez au village, au sud-est, et faites-vous connaître. Donnez un coup de main ici ou là, et en un rien de temps, vous aurez eu l’occase de faire quequ’chose de plus prestigieux.', '', '', '', '', '', '', '', '', '', '', 0),
(24758, 'frFR', 'L\'ascension des Sombrelances', 'Allez voir Nekali sur le Terrain d’entraînement des Sombrelances.', 'Nous autres Sombrelances, on a longtemps été des victimes. Des parias. On a dû fuir notre foyer, encore et encore… mais cette fois-ci, c’est pas pour fuir qu’on est là.$B$BVol’jin, il nous gouverne avec sagesse, et c’est ça qui nous a gardés en vie si longtemps. Et maintenant, avec sa sagesse, il voit que la Horde sous les ordres de Garrosh Hurlenfer, elle a un avenir chaotique.$B$BNon, cette fois, on ne fuit pas. Cette fois, on se bat pour rester chez nous.$B$BIl est temps de commencer votre formation, $n. Parlez à Nekali, à l’est.', '', '', '', '', '', '', '', '', '', '', 0),
(24759, 'frFR', 'La base : savoir frapper des trucs', 'Détruire 6 Cibles Tiki.', 'D\'accord d\'accord, $gmon pote:ma grande;. On va commencer petit. Faut que j’m’assure que vous maîtrisez les bases des arts d’la nature.$B$BAllez m’casser des cibles tiki. En douceur. Naturellement. J’vais vous regarder lancer vos sorts, et on partira d’là.', '', '', '', '', '', '', '', '', '', 'Retournez voir Nekali au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24760, 'frFR', 'Les arts du chaman', 'Atteignez le Niveau 3 pour apprendre la Frappe primordiale, puis utilisez-la 3 fois sur une Cible Tiki.', 'En gagnant en puissance, vous vous rendrez vite compte que les voix d’vos ancêtres vous causent pour vous raconter des tas d’secrets.\n\nEt l’premier d’entre eux, c’est d’focaliser l’pouvoir des éléments dans votre arme, pour pouvoir balancer une attaque rapide et qui fait mal. Ça d’vrait être facile pour vous, alors hésitez pas à vous en servir beaucoup.$B$BEssayez. Revenez m’voir quand vous aurez pigé l’truc.', '', 'S’exercer à la Frappe primordiale', '', '', '', '', '', '', '', 'Retournez voir Nekali au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24761, 'frFR', 'Un début difficile', 'Récupérez 6 Peaux de félins crin-sauvage.', 'Bon, ben $gmon pote:ma grande;, on va s’servir de ces compétences, en commençant par un truc qu’il sera facile.$B$BY a des fauves qui tuent nos sangliers. Not’bouffe, on la partage pas. Si vous voulez grailler ce soir, faut que ces sangliers, ils soient en vie.$B$BY en a sur toute l’île. Amenez-moi des peaux de félins.', '', '', '', '', '', '', '', '', '', 'Retournez voir Nekali au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24762, 'frFR', 'La fosse de l\'épreuve', 'Parlez à un Geôlier sombrelance, puis descendez dans la fosse de l\'épreuve et tuez un Éclaireur Vexécaille captif.', 'Vous vous en sortez bien, $c. Oh, pas d’doute, j’peux encore vous apprendre un ou deux trucs, mais j’serais vous, j’perdrais plus mon temps sur les cibles tiki.$B$BAlors, j’ai une autre épreuve pour vous, $gmon pote:ma grande;. Vous allez jusqu’à la fosse de l’épreuve, là au milieu, et vous vous battez contre un vrai méchant, un qui va s’défendre et vouloir vous tuer. Quand vous serez $gprêt:prête;, vous le dites juste au geôlier, au bord d’la fosse.', '', 'Parlez à un Geôlier sombrelance', '', '', '', '', '', '', '', 'Retournez voir Nekali au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24763, 'frFR', 'Mieux que prévu', 'Présentez-vous à Vol\'jin au Bastion des Sombrelances.', 'Y a plus en vous qu’on n’en attendait, $gmon pote:ma grande;. On doit sûrement avoir des trucs plus importants à vous faire faire. Z’avez plus besoin de traîner ici avec les autres p’tits nouveaux.$B$BAllez au village, au sud-est, et faites-vous connaître. Donnez un coup de main ici ou là, et en un rien de temps, vous aurez eu l’occase de faire quequ’chose de plus prestigieux.', '', '', '', '', '', '', '', '', '', '', 0),
(24764, 'frFR', 'L’ascension des Sombrelances', 'Allez voir Zen’tabra sur le Terrain d’entraînement des Sombrelances.', 'Nous autres Sombrelances, on a longtemps été des victimes. Des parias. On a dû fuir notre foyer, encore et encore… mais cette fois-ci, c’est pas pour fuir qu’on est là.$B$BVol’jin, il nous gouverne avec sagesse, et c’est ça qui nous a gardés en vie si longtemps. Et maintenant, avec sa sagesse, il voit que la Horde sous les ordres de Garrosh Hurlenfer, elle a un avenir chaotique.$B$BNon, cette fois, on ne fuit pas. Cette fois, on se bat pour rester chez nous.$B$BIl est temps de commencer votre formation, $n. Parlez à Zen’tabra, à l’est.', '', '', '', '', '', '', '', '', '', '', 0),
(24765, 'frFR', 'La base : savoir frapper des trucs', 'Détruire 6 Cibles Tiki.', 'D’accord d’accord, $gmon pote:ma grande;. On va commencer petit. Faut que j’m’assure que vous maîtrisez les bases des arts druidiques.$B$BAllez m’casser des cibles tiki. En douceur. Naturellement. J’vais vous regarder lancer vos sorts, et on partira d’là.', '', '', '', '', '', '', '', '', '', 'Retournez voir Zen’tabra au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24766, 'frFR', 'Les arts du druide', 'Atteignez le Niveau 3 pour apprendre l’Éclat lunaire, et entraînez-vous à l’utiliser sur une Cible Tiki au Terrain d’entraînement des Sombrelances.', 'En dev’nant plus $gcostaud:puissante;, c’est aussi vot’ capacité à faire appel à la nature qui s’renforce. Vous voulez voir ?\n\nAllez gagner d’l’expérience et rev’nez me montrer c’que vous aurez appris.', '', 'S’exercer à l’Éclat lunaire', '', '', '', '', '', '', '', 'Retournez voir Zen’tabra au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24767, 'frFR', 'Un début difficile', 'Récupérez 6 Peaux de félins crin-sauvage.', 'Bon, ben $gmon pote:ma grande;, on va s’servir de ces compétences, en commençant par un truc qu’il sera facile.$B$BY a des fauves qui tuent nos sangliers. Not’bouffe, on la partage pas. Si vous voulez grailler ce soir, faut que ces sangliers, ils soient en vie.$B$BY en a sur toute l’île. Amenez-moi des peaux de félins.', '', '', '', '', '', '', '', '', '', 'Retournez voir Zen’tabra au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24768, 'frFR', 'La fosse de l’épreuve', 'Parlez à un Geôlier sombrelance, puis descendez dans la fosse de l’épreuve et tuez un Éclaireur Vexécaille captif.', 'Vous vous en sortez bien, $c. Oh, pas d’doute, j’peux encore vous apprendre un ou deux trucs, mais j’serais vous, j’perdrais plus mon temps sur les cibles tiki.$B$BAlors, j’ai une autre épreuve pour vous, $gmon pote:ma grande;. Vous allez jusqu’à la fosse de l’épreuve, là au milieu, et vous vous battez contre un vrai méchant, un qui va s’défendre et vouloir vous tuer. Quand vous serez $gprêt:prête;, vous le dites juste au geôlier, au bord d’la fosse.', '', 'Parlez à un Geôlier sombrelance', '', '', '', '', '', '', '', 'Retournez voir Zen’tabra au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24769, 'frFR', 'Mieux que prévu', 'Présentez-vous à Vol’jin au Bastion des Sombrelances.', 'Y a plus en vous qu’on n’en attendait, $gmon pote:ma grande;. On doit sûrement avoir des trucs plus importants à vous faire faire. Z’avez plus besoin de traîner ici avec les autres p’tits nouveaux.$B$BAllez au village, au sud-est, et faites-vous connaître. Donnez un coup de main ici ou là, et en un rien de temps, vous aurez eu l’occase de faire quequ’chose de plus prestigieux.', '', '', '', '', '', '', '', '', '', '', 0),
(24770, 'frFR', 'L\'ascension des Sombrelances', 'Allez voir Legati sur le Terrain d’entraînement des Sombrelances.', 'Nous autres Sombrelances, on a longtemps été des victimes. Des parias. On a dû fuir notre foyer, encore et encore… mais cette fois-ci, c’est pas pour fuir qu’on est là.$B$BVol’jin, il nous gouverne avec sagesse, et c’est ça qui nous a gardés en vie si longtemps. Et maintenant, avec sa sagesse, il voit que la Horde sous les ordres de Garrosh Hurlenfer, elle a un avenir chaotique.$B$BNon, cette fois, on ne fuit pas. Cette fois, on se bat pour rester chez nous.$B$BIl est temps de commencer votre formation, $n. Parlez à Legati, à l’est.', '', '', '', '', '', '', '', '', '', '', 0),
(24771, 'frFR', 'La base : savoir frapper des trucs', 'Détruire 6 Cibles Tiki.', 'D\'accord d\'accord, $gmon pote:ma grande;. On va commencer petit. Faut que j’m’assure ‘‘vous savez vous servir de ces armes qu’vous trimballez avec vous.$B$BAllez m’casser des cibles tiki. En douceur. Naturellement. J’vais vous regarder vous escrimer, et on partira d’là.', '', '', '', '', '', '', '', '', '', 'Retournez voir Legati au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24772, 'frFR', 'Les arts du voleur', 'Atteignez le Niveau 3 pour apprendre l’Éviscération, puis utilisez-la à 3 reprises contre une Cible Tiki.', 'En cognant sur vos ennemis, vous apprendrez d’nouveaux trucs pour être encore plus redoutable.\n\nVous n’devriez plus tarder à apprendre un d’ces trucs : repérer les points faibles de l’ennemi, et lancer des attaques en combo qui font super mal. Vous portez quelques coups pour affaiblir l’adversaire, et puis vous l’finissez en l’éviscérant.\n\nRevenez m’faire une démonstration quand vous maîtriserez tout ça.', '', 'S’exercer à l’Éviscération', '', '', '', '', '', '', '', 'Retournez voir Legati au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24773, 'frFR', 'Un début difficile', 'Récupérez 6 Peaux de félins crin-sauvage.', 'Bon, ben $gmon pote:ma grande;, on va s’servir de ces compétences, en commençant par un truc qu’il sera facile.$B$BY a des fauves qui tuent nos sangliers. Not’bouffe, on la partage pas. Si vous voulez grailler ce soir, faut que ces sangliers, ils soient en vie.$B$BY en a sur toute l’île. Amenez-moi des peaux de félins.', '', '', '', '', '', '', '', '', '', 'Retournez voir Legati au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
(24774, 'frFR', 'La fosse de l\'épreuve', 'Parlez à un Geôlier sombrelance, puis descendez dans la fosse de l\'épreuve et tuez un Éclaireur Vexécaille captif.', 'Vous vous en sortez bien, $c. Oh, pas d’doute, j’peux encore vous apprendre un ou deux trucs, mais j’serais vous, j’perdrais plus mon temps sur les cibles tiki.$B$BAlors, j’ai une autre épreuve pour vous, $gmon pote:ma grande;. Vous allez jusqu’à la fosse de l’épreuve, là au milieu, et vous vous battez contre un vrai méchant, un qui va s’défendre et vouloir vous tuer. Quand vous serez $gprêt:prête;, vous le dites juste au geôlier, au bord d’la fosse.', '', 'Parlez à un Geôlier sombrelance', '', '', '', '', '', '', '', 'Retournez voir Legati au Terrain d’entraînement des Sombrelances, sur les Îles de l’Écho.', 0),
