(28814, 'ruRU', 'Пастыри и паства', 'Убейте верховную жрицу Азил и 101 верного последователя.', 'В бумагах описывается визит верховной жрицы Азил в глубины Каменных Недр.$B$BИсходя из изложенного, Азил – высокопоставленный член Сумеречного Совета, а ее кортеж более чем из ста верных последователей готовится провести темный ритуал необыкновенно разрушительной силы.$B$BПохоже, вам стоит воспрепятствовать осуществлению их планов.', '', '', '', '', '', '', 'Верховная жрица Азил', '', '', 'Вернитесь к Хранителю земли Изре в Каменные недра.', 0),
(28815, 'ruRU', 'Документы Сумеречного Молота', 'Раздобудьте документы Сумеречного Молота.', 'Мы выследили агента Сумеречного Молота. Зовут его Миллхаус Манашторм.$B$BЕсть основания полагать, что у него при себе важные бумаги.$B$BОднако мы не можем оставить внутренний периметр Храма Земли без защиты.$B$BРазыщи Манашторма и отбери у него документы.', '', '', '', '', '', '', 'Миллхаус Манашторм', '', '', '', 0),
(28816, 'ruRU', 'В пучину', 'Явитесь с рапортом к командиру Тораку в бухте Острорука в Дуротаре.', 'Служители Земли установили, что водянистый регион Вайш\'ир является источником разрушительной энергии.$b$bСложно сказать, что за опасности таит в себе это место, но любые сведения о нем, что ты сможешь добыть, окажутся чрезвычайно полезными.$b$bВ это самое время Орда посылает в данный регион военную армаду. Для того чтобы попасть на корабль, обратись к командиру Тораку в бухте Острорука.$b$bДа хранят тебя духи, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(28817, 'ruRU', 'Тыл зачищен', 'Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.', 'Прекрасно сработано, $n! Отныне тыл можно считать зачищенным. Мы сами займемся дезертирами. Я хочу, чтобы ты $gпошел:пошла; к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и $gдоложил:доложила; ему, что ситуация с гоблинами находится под контролем.$B$BПрощай, |3-6($c).', '', '', '', '', '', '', '', '', '', '', 0),
(28818, 'ruRU', 'Тыл зачищен', 'Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.', 'Прекрасно сработано, $n! Отныне тыл можно считать зачищенным. Мы сами займемся дезертирами. Я хочу, чтобы ты $gпошел:пошла; к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и $gдоложил:доложила; ему, что ситуация с гоблинами находится под контролем.$B$BПрощай, |3-6($c).', '', '', '', '', '', '', '', '', '', '', 0),
