(28934, 'ruRU', 'Конец Королевской компании', 'Убейте 5 техников химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к востоку от гробницы Хартута, рядом со входом со стороны Танариса. После этого вернитесь к инспектору Кромсу Гвоздезубу в Штормград.', 'В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте в Ульдуме, которое находится к востоку от гробницы Хартута, рядом со входом со стороны Танариса. Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', '', 'Повозка с химикатами уничтожена', '', '', '', '', '', '', '', 'Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.', 0),
(28935, 'ruRU', 'Конец Королевской компании', 'Убейте 5 техников химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к востоку от гробницы Хартута, рядом со входом со стороны Танариса. После этого вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.', 'В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте в Ульдуме, которое находится к востоку от гробницы Хартута, рядом со входом со стороны Танариса. Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', '', 'Повозка с химикатами уничтожена', '', '', '', '', '', '', '', 'Вернитесь к детективу Крямсу Гвоздезубу на Аллею Силы Оргриммара.', 0),
