(8022, 'ptBR', 'Trocar o Vale-brinde iCoca', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Bethina, em Teldrassil.', 0),
(8023, 'ptBR', 'Trocar o Vale-brinde iCoca', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tresa MacGregor, no Pantanal.', 0),
(8024, 'ptBR', 'Trocar o Vale-brinde iCoca', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Hovrak Sacatripas, na Floresta de Pinhaprata.', 0),
(8025, 'ptBR', 'Trocar o Vale-brinde iCoca', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nyx Fúria Sanguinária, em Durotar.', 0),
(8026, 'ptBR', 'Trocar o Vale-brinde iCoca', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rygal Rocknell, na Desolação.', 0),
