(8827, 'ptBR', 'Presentes de inverno', 'Fale com o Papai Inverno. Ele está perto dos vendedores da Fazenda Bosque Defumado, em Altaforja.', 'Ouvi dizer que o Papai Inverno, com a ajuda da Fazenda Bosque Defumado, colocou presentes para a galera lá debaixo da árvore, em Altaforja. Eu queria dar um pulo lá, mas tenho que tomar conta do Voltímato de Inverno PX-238.$b$bMas não deixa de passar lá, não. Garanto que o Papai Inverno tem presentes para você também!', '', '', '', '', '', '', '', '', '', '', 0),
(8828, 'ptBR', 'Presentes de inverno', 'Fale com o Papai Inverno. Ele está perto dos vendedores da Fazenda Bosque Defumado, em Orgrimmar.', 'Ouvi dizer que o Papai Inverno, com a ajuda da Fazenda Bosque Defumado, colocou presentes para a galera lá debaixo da árvore, em Orgrimmar. Eu queria dar um pulo lá, mas tenho que tomar conta do Voltímato de Inverno PX-238.$b$bMas não deixa de passar lá, não. Garanto que o Papai Inverno tem presentes para você também!', '', '', '', '', '', '', '', '', '', '', 0),
