(10464, 'ptBR', 'Voto do sábio', 'Leve seu Elo da Eternidade para Soridormi nas Cavernas do Tempo após tornar-se $gHonrado:Honrada; pela Escama das Areias.', 'Jurou perante a nossa irmandade, $c. É chegada a hora de cumprir tal juramento.$B$BSirva a Escama das Areias com afinco e será $grecompensado:recompensada;.$B$BFalhe, e a linha do tempo que conhecemos se romperá!', '', '', '', '', '', '', '', '', '', '', 0),
(10465, 'ptBR', 'Voto do restaurador', 'Leve seu Elo da Eternidade para Soridormi nas Cavernas do Tempo após tornar-se $gHonrado:Honrada; pela Escama das Areias.', 'Jurou perante a nossa irmandade, $c. É chegada a hora de cumprir tal juramento.$B$BSirva a Escama das Areias com afinco e será $grecompensado:recompensada;.$B$BFalhe, e a linha do tempo que conhecemos se romperá!', '', '', '', '', '', '', '', '', '', '', 0),
(10466, 'ptBR', 'Voto do campeão', 'Leve seu Elo da Eternidade para Soridormi nas Cavernas do Tempo após tornar-se $gHonrado:Honrada; pela Escama das Areias.', 'Jurou perante a nossa irmandade, $c. É chegada a hora de cumprir tal juramento.$B$BSirva a Escama das Areias com afinco e será $grecompensado:recompensada;.$B$BFalhe, e a linha do tempo que conhecemos se romperá!', '', '', '', '', '', '', '', '', '', '', 0),
(10467, 'ptBR', 'Voto do defensor', 'Leve seu Elo da Eternidade para Soridormi nas Cavernas do Tempo após tornar-se $gHonrado:Honrada; pela Escama das Areias.', 'Jurou perante a nossa irmandade, $c. É chegada a hora de cumprir tal juramento.$B$BSirva a Escama das Areias com afinco e será $grecompensado:recompensada;.$B$BFalhe, e a linha do tempo que conhecemos se romperá!', '', '', '', '', '', '', '', '', '', '', 0),
(10468, 'ptBR', 'Juramento do sábio', 'Leve o Elo da Eternidade para Soridormi nas Cavernas do Tempo depois de tornar-se $gReverenciado:Reverenciada; pela Escama das Areias.', 'Cumpriu sua promessa conosco, $n, ganhando, assim, o reconhecimento que merece.$B$BEnquanto continuar a desvendar os eventos do passado sobre o monte Hyjal, continuarei a conceder poder ao seu anel. Logo ele alcançará seu estado pleno.', '', '', '', '', '', '', '', '', '', '', 0),
(10469, 'ptBR', 'Juramento do restaurador', 'Leve o Elo da Eternidade para Soridormi nas Cavernas do Tempo depois de tornar-se $gReverenciado:Reverenciada; pela Escama das Areias.', 'Cumpriu sua promessa conosco, $n, ganhando, assim, o reconhecimento que merece.$B$BEnquanto continuar a desvendar os eventos do passado sobre o monte Hyjal, continuarei a conceder poder ao seu anel. Logo ele alcançará seu estado pleno.', '', '', '', '', '', '', '', '', '', '', 0),
(10470, 'ptBR', 'Juramento do campeão', 'Leve o Elo da Eternidade para Soridormi nas Cavernas do Tempo depois de tornar-se $gReverenciado:Reverenciada; pela Escama das Areias.', 'Cumpriu sua promessa conosco, $n, ganhando, assim, o reconhecimento que merece.$B$BEnquanto continuar a desvendar os eventos do passado sobre o monte Hyjal, continuarei a conceder poder ao seu anel. Logo ele alcançará seu estado pleno.', '', '', '', '', '', '', '', '', '', '', 0),
(10471, 'ptBR', 'Juramento do defensor', 'Leve o Elo da Eternidade para Soridormi nas Cavernas do Tempo depois de tornar-se $gReverenciado:Reverenciada; pela Escama das Areias.', 'Cumpriu sua promessa conosco, $n, ganhando, assim, o reconhecimento que merece.$B$BEnquanto continuar a desvendar os eventos do passado sobre o monte Hyjal, continuarei a conceder poder ao seu anel. Logo ele alcançará seu estado pleno.', '', '', '', '', '', '', '', '', '', '', 0),
(10472, 'ptBR', 'Pacto do sábio', 'Leve seu Elo da Eternidade para Soridormi nas Cavernas do Tempo após tornar-se $GExaltado:Exaltada; pela Escama das Areias.', 'Suas conquistas excederam minhas expectativas, $n.$B$BConsegue viajar no tempo tão bem quanto qualquer dragão de bronze que conheço. Seu destino trará grande poder a você e fico feliz em ajudar nesta caminhada.$B$BContinue a servir à Escama das Areias e libertarei todo o poder do presente que recebeu.', '', '', '', '', '', '', '', '', '', '', 0),
(10473, 'ptBR', 'Pacto do restaurador', 'Leve seu Elo da Eternidade para Soridormi nas Cavernas do Tempo após tornar-se $GExaltado:Exaltada; pela Escama das Areias.', 'Suas conquistas excederam minhas expectativas, $n.$B$BConsegue viajar no tempo tão bem quanto qualquer dragão de bronze que conheço. Seu destino trará grande poder a você e fico feliz em ajudar nesta caminhada.$B$BContinue a servir à Escama das Areias e libertarei todo o poder do presente que recebeu.', '', '', '', '', '', '', '', '', '', '', 0),
(10474, 'ptBR', 'Pacto do campeão', 'Leve seu Elo da Eternidade para Soridormi nas Cavernas do Tempo após tornar-se $GExaltado:Exaltada; pela Escama das Areias.', 'Suas conquistas excederam minhas expectativas, $n.$B$BConsegue viajar no tempo tão bem quanto qualquer dragão de bronze que conheço. Seu destino trará grande poder a você e fico feliz em ajudar nesta caminhada.$B$BContinue a servir à Escama das Areias e libertarei todo o poder do presente que recebeu.', '', '', '', '', '', '', '', '', '', '', 0),
(10475, 'ptBR', 'Pacto do defensor', 'Leve seu Elo da Eternidade para Soridormi nas Cavernas do Tempo após tornar-se $GExaltado:Exaltada; pela Escama das Areias.', 'Suas conquistas excederam minhas expectativas, $n.$B$BConsegue viajar no tempo tão bem quanto qualquer dragão de bronze que conheço. Seu destino trará grande poder a você e fico feliz em ajudar nesta caminhada.$B$BContinue a servir à Escama das Areias e libertarei todo o poder do presente que recebeu.', '', '', '', '', '', '', '', '', '', '', 0),
(10476, 'ptBR', 'Inimigos ferozes', 'O Responsável Moi\'bff Jill, de Telaar, quer que você pegue 10 Colares de Guerra Obsidianos de vários ogros de Nagrand.', 'Para provares tua lealdade para conosco, não há melhor caminho do que lutar contra nossos inimigos.$B$BDestes, nenhum supera os ogros em força e fúria. Traze-me os colares de guerra desses bárbaros como prova de que tombaram em campo e falarei aos demais sobre a tua bravura.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Protetor Moi\'bff Jill na vila de Telaar, em Nagrand.', 0),
(10477, 'ptBR', 'Mais colares de guerra', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Protetor Moi\'bff Jill na vila de Telaar, em Nagrand.', 0),
(10478, 'ptBR', 'Mais colares de guerra!', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda Bullrok no Pântano Zíngaro.', 0),
(10479, 'ptBR', 'Prova de força', 'O Guarda Bullrok, de Garadar, quer que você pegue 10 Colares de Guerra Obsidianos de vários ogros de Nagrand.', 'Ainda que almejemos uma existência pacífica, nossos inimigos são muitos. Destes, nenhum se iguala aos ogros em força bruta.$B$BSe você deseja provar seu valor perante nosso povo, traga-me os colares de guerra que esses bárbaros usam no pescoço. Falarei de suas façanhas aos demais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda Bullrok na cidade de Garadar, em Nagrand.', 0),
(10480, 'ptBR', 'Espíritos da água enfurecidos', 'O Reparador da Terra Torlok, no Altar da Danação do Vale da Lua Negra, quer que você use o Totem dos Espíritos para capturar 5 Almas da Água.', 'As nagas Illidari desta região tomaram controle da única fonte de água limpa no Vale da Lua Negra.$B$BBem ao norte daqui você encontrará Serpentálios, o covil das nagas. Ao redor de Serpentálios existem bolsões de água agitada que uivam para a terra em agonia. É nesses bolsões que os espíritos enfurecidos da água agora vagueiam.$B$BVá até Serpentálios e use o Totem dos Espíritos para capturar almas da água. Você encontrará a maior concentração de espíritos próximo à Cisterna Serpentálios.', '', 'Almas da Água capturadas', '', '', '', '', '', '', '', 'Fale com o Reparador da Terra Torlok no Altar da Danação, que fica no Vale da Lua Negra.', 0),
(10481, 'ptBR', 'Espíritos do ar enfurecidos', 'O Reparador da Terra Torlok, no Altar da Danação do Vale da Lua Negra, quer que você use o Totem dos Espíritos para capturar 10 Almas do Ar.', 'Quero que você vá para sudeste, $gherói:heroína;. Quando você encontrar campos de cristais azuis gigantescos se projetando do solo, terá alcançado seu destino. É lá, nos Campos da Asa Etérea, que você encontrará os espíritos do ar enfurecidos. Eles vagam pelos penhascos e sopés montanhosos que cercam os campos.$B$BDestrua-os e capture suas almas com o Totem dos Espíritos. Fale novamente comigo ao completar sua missão.', '', 'Almas do Ar capturadas', '', '', '', '', '', '', '', 'Fale com o Reparador da Terra Torlok no Altar da Danação, que fica no Vale da Lua Negra.', 0),
(10482, 'ptBR', 'Orcs vis catadores', 'Mate 20 Orcs Mascaosso e fale novamente com a Tenente Amadi na Fortaleza da Honra.', 'Os catadores orcs do clã Mascaosso vagueiam pelas ruínas no Caminho da Glória. Achamos que esses orcs vis estão coletando peças de maquinário de guerra para seus mestres, na Cidadela Fogo do Inferno. Eles precisam ser impedidos!$B$BEncontre os orcs Mascaosso ao norte daqui, $n. Encontre-os e mate-os! Mas tome cuidado, pois embora esses orcs sejam os mais baixos dos clãs de orcs vis, a força deles é páreo para qualquer orc de pele verde...', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Tenente Amadi na Fortaleza da Honra, que fica na Península Fogo do Inferno.', 0),
(10483, 'ptBR', 'Presságios agourentos', 'A Tenente Amadi, na Fortaleza da Honra, quer que você leve 1 Talismã Amaldiçoado para o Cabo Cristaferro no Posto da Expedição.', 'Em nossas batalhas com o clã Olhos Sangrentos de orcs vis, temos encontrado alguns itens agourentos... Os orcs vis andam coletando insígnias dos soldados da Fortaleza da Honra para fabricar talismãs amaldiçoados. Acreditamos que a magia perversa dos Olhos Sangrentos tenha transformado nossas insígnias em objetos amaldiçoados, que podem ser usados contra nós.$B$BEncontre um talismã dos orcs Olhos Sangrentos de Zeth\'Gor, a leste daqui, e leve-o para o cabo Cristaferro no Posto da Expedição, a nordeste de Zeth\'Gor.', '', '', '', '', '', '', '', '', '', 'Fale com o Cabo Cristaferro, no Posto da Expedição, que fica na Península Fogo do Inferno.', 0),
(10484, 'ptBR', 'Talismãs amaldiçoados', 'Leve 12 Talismãs Amaldiçoados para o Cabo Cristaferro no Posto da Expedição.', '$n, não podemos permitir que os Olhos Sangrentos continuem usando os talismãs! Você tem que confiscá-los para que possamos destruí-los. Assim, os soldados que os possuíram poderão ser honrados pelos sacrifícios que fizeram.$B$BSiga para Zeth\'Gor, o covil maldito dos Olhos Sangrentos, e execute suas ordens. Apresente-se a mim quando tiver coletado os talismãs.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Cabo Cristaferro, no Posto da Expedição, que fica na Península Fogo do Inferno.', 0),
(10485, 'ptBR', 'O senhor da guerra dos Olhos Sangrentos', 'Leve a Armadura Rachada de Morkh para o Cabo Cristaferro no Posto da Expedição.', 'Você demonstrou ter muita força e sorte, pois retornou de Zeth\'Gor para contar a história! Espero que sua sorte perdure, pois tenho uma tarefa árdua para você...$B$BO Senhor da Guerra Morkh está nos quartéis de Zeth\'Gor, comandando as tropas vis. As táticas dele são astuciosas e cruéis, e admito que os êxitos que ele obteve doeram fundo. Assim, $n, peço a você que deponha Morkh do comando. Me traga a armadura dele para ser exibida aos soldados, para que possamos animá-los.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Cabo Cristaferro, no Posto da Expedição, que fica na Península Fogo do Inferno.', 0),
(10486, 'ptBR', 'A selva agressiva', 'Mate 12 Dessangradores Laminasas.', 'Os Senhor do Trovão eram um clã orc orgulhoso antes que o sangue de Mannoroth os transformasse em orcs vis.$B$BRecentemente recuperamos esta fortaleza órquica dos ogros que infestam o barranco abaixo. Eles invadiram quando o clã Senhor do Trovão a abandonou.$B$BTenho interesse em manter este lugar, mas preciso de sua ajuda.$B$BNa Serra dos Espigões, a sul e a oeste, há dessangradores que se tornaram uma praga para nós. Eles comem e se reproduzem incessantemente.$B$BMate-os e venha falar comigo de novo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gor\'drek na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10487, 'ptBR', 'Pó dos dracos', 'Colete 4 Amostras de Pó de Draco Encantado.', 'A Aliança veio para o oeste há pouco tempo e usou magia élfica para criar uma cidade e um bosque em um piscar de olhos. Não podemos deixar que fortaleçam as defesas e se estabeleçam.$B$BTenho um plano que vai dar conta disso – e de muito mais. Quero que você atravesse a ponte a sudoeste, que cruza o Barranco Malho Sangrento e leva até o Bosque Vicejante. Ataque os dracos encantados no Bosque Vicejante e traga o pó mágico que é encontrado ocasionalmente nas asas deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gor\'drek na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10488, 'ptBR', 'A proteção dos nossos', 'Use a Pomada de Gor\'drek em 5 Lobos Hediondos Senhor do Trovão.', 'Eu fiz uma pomada mágica com o pó mágico que você trouxe. Ela ajudará as nossas defesas.$B$BOs lobos hediondos são uma combinação perfeita de montaria, guarda e amizade, mas os imprestáveis da Aliança os estão caçando na Serra dos Espigões.$B$B$n, quero que leve a pomada e a aplique nos nossos amigos lobos hediondos. A Aliança terá uma grata surpresa na próxima vez que enviar um de seus grupos de caça.$B$BAlguns lobos podem não gostar, então tome cuidado.', '', 'Lobos Hediondos Senhor do Trovão fortalecidos', '', '', '', '', '', '', '', 'Fale novamente com Gor\'drek na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10489, 'ptBR', 'Derrubada da árvore anciente', 'Obtenha o Tronco de Ramaforte Raizfundo.', 'PROCURADO!$B$BRamaforte Raizfundo, anciente de guerra e maior defensor do Bosque Vicejante, ao sul de Sylvanaar.$B$BEncontre-o indo para oeste pela ponte que cruza o Barranco Malho Sangrento.$B$BCorte o tronco dele e o entregue para Tor\'chunk Duasgarras.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tor\'chunk Duasgarras na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10500, 'ptBR', 'A Horda precisa de você!', 'Fale com o Senhor da Guerra Gorchuk no Vale dos Espíritos em Orgrimmar.', 'Olá, que bom que você resolveu me dar ouvidos. A Horda precisa de toda a ajuda que conseguir para os preparativos de guerra em Ahn\'Qiraj. Ou seja, precisamos de você! Enquanto tagarelamos, os coletores oficiais reúnem o material necessário à guerra iminente, mas não seremos capazes de cumprir as metas sem sua ajuda, $n!$B$BFale com o encarregado, o Senhor da Guerra Gorchuk. Então, $c? Podemos contar com sua ajuda em preparativos tão vitais?', '', '', '', '', '', '', '', '', '', '', 0),
(10501, 'ptBR', 'A Aliança precisa de você!', 'Fale com o Marechal-de-campo Nevado na Ala Militar de Altaforja.', 'Olá, que bom que tu resolveste me escutar. A Aliança precisa de toda a ajuda que conseguir para os preparativos de guerra em Ahn\'Qiraj. Ou seja, precisamos de ti! Enquanto mantemos este colóquio, os coletores oficiais reúnem o material necessário à guerra iminente, mas não seremos capazes de cumprir as metas sem tua ajuda, $n!$B$BFala com o encarregado, o Marechal-de-campo Nevado. Como é, $c? Podemos contar com tua ajuda em preparativos tão vitais?', '', '', '', '', '', '', '', '', '', '', 0),
(10502, 'ptBR', 'Os ogros Malho Sangrento', 'Mate 30 Ogros Malho Sangrento quaisquer no Posto Malho Sangrento.', 'Sylvanaar enfrenta uma ameaça muito mais letal que as forças da Horda na Cidadela do Senhor do Trovão.$B$BFalo dos ogros nativos destas montanhas. O clã Malho Sangrento fica logo ao sul e leste, adentrando a ravina. Apesar de não ser o único grupo de ogros que nos ameaça, são os mais próximos.$B$BEu gostaria de que você rumasse para o sul pelo Bosque Vicejante, e descesse pelo caminho para o leste que leva ao posto deles. Mate o máximo possível de ogros Malho Sangrento no posto deles.', '', 'Ogros Malho Sangrento mortos', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Caelumbra em Sylvanaar, nas Montanhas da Lâmina Afiada.', 0),
(10503, 'ptBR', 'A ameaça dos Giralança', 'Mate quaisquer 30 Ogros Giralança e 10 Raptores Giralança no Bastião Giralança e nas Terras dos Giralança.', 'Há uma ameaça para a Cidadela do Senhor do Trovão pior que a Aliança em Sylvanaar.$B$BFalo dos ogros destas montanhas. O clã Giralança vive logo a oeste, adentrando o barranco. Apesar de não serem os únicos ogros, são os que estão mais perto. Foram eles que derrotamos para ficar com este lugar.$B$BSiga para o norte pela Serra dos Espigões e depois desça pela estrada para chegar ao bastião deles. Mate o máximo possível de ogros Giralança e de raptores no Bastião Giralança e nas Terras dos Giralança.', '', 'Ogros Giralança mortos', '', '', '', '', '', '', '', 'Fale novamente com Tor\'chunk Duasgarras na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10504, 'ptBR', 'Os ogros Giralança', 'Mate 30 Ogros Giralança quaisquer no Bastião Giralança e nas Terras dos Giralança.', 'Ao norte do clã Malho Sangrento, há uma ameaça mais grave: o Bastião Giralança.$B$BOs ogros Giralança são o clã mais forte das montanhas e contam com a proteção do gronn conhecido como Gruul, o Matador de Dragões, e seus sete filhos.$B$BAgora que já cuidamos dos Malho Sangrento, chegou o momento de voltarmos a nossa atenção para os rivais deles.$B$BSiga para o norte a partir do Bastião Malho Sangrento até chegar ao Bastião Giralança e às Terras dos Giralança. Mate o máximo possível de ogros Giralança que encontrar no local.', '', 'Ogros Giralança mortos', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Caelumbra em Sylvanaar, nas Montanhas da Lâmina Afiada.', 0),
(10505, 'ptBR', 'Os ogros Malho Sangrento', 'Mate 30 Ogros Malho Sangrento quaisquer no Posto Malho Sangrento.', 'Ainda há outra ameaça ao sul do clã Giralança: o Posto Avançado Malho Sangrento.$B$BApesar de os ogros Malho Sangrento não serem o clã mais forte das montanhas e não contarem com a proteção do gronn conhecido como Gruul, o Matador de Dragões, não devemos subestimá-los.$B$BJá estamos livres dos Giralança, mas chegou o momento de nos concentrarmos nos rivais deles.$B$BSiga para o sul a partir do Bastião Giralança e passe pelo barranco até chegar ao Posto Avançado Malho Sangrento. Mate o máximo possível de ogros Malho Sangrento nas adjacências.', '', 'Ogros Malho Sangrento mortos', '', '', '', '', '', '', '', 'Fale novamente com Tor\'chunk Duasgarras na Cidadela do Senhor do Trovão que fica nas Montanhas da Lâmina Afiada.', 0),
(10506, 'ptBR', 'Uma situação hedionda', 'Use o Pó de Diminuição de Rina em 5 Lobos Hediondos Malho Sangrento, que podem ser encontrados no posto Malho Sangrento e no Barranco Malho Sangrento.', 'A Horda precisa de mais lobos, pois a matilha deles está reduzida. Infelizmente há outra fonte por perto.$B$BOs ogros Malho Sangrento, na ravina abaixo e a leste, mantêm uma alcateia forte como sentinelas. Não gostei de $G tê-lo:tê-la; enviado para matar lobos hediondos Senhor do Trovão, então por que não fazemos algo diferente desta vez?$B$BCriei um pó mágico a partir da poeira que cai naturalmente das asas dos nossos dracos encantados. Borrife isto nos lobos hediondos Malho Sangrento para torná-los indesejáveis para a Horda.', '', 'Lobo Hediondo Malho Sangrento enfraquecido', '', '', '', '', '', '', '', 'Fale novamente com Rina Lunafontana em Sylvanaar, nas Montanhas da Lâmina Afiada.', 0),
(10507, 'ptBR', 'Virada', 'Use a Pedra Teleportadora de Socrethar no Ponto de Invasão: Lorde supremo, ao norte da Base-forja: Oblívio para levar seu grupo ao Porto de Socrethar. Uma vez lá, use a Presença de Voren\'thal para derrotar Socrethar.$B$BCumprir missões para os Áugures fará com que a sua reputação entre os Aldor diminua.', 'Esta é chance que esperamos, $n. Além de termos descoberto as evidências que precisamos para mostrar ao nosso povo para quem Kael\'thas está trabalhando, podemos provar nossa força derrotando seus novos mestres.$B$BMinha saúde frágil impede-me de assisti-$Glo:la; nessa empreitada, mas ofereço-lhe um objeto que projetará meu poder através do continente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Voren\'thal, o Vidente, no Terraço dos Áugures, em Shattrath.', 0),
(10508, 'ptBR', 'O presente de Voren\'thal', 'O Mestre Espião Thalodien, na Área 52, quer que você obtenha a Primeira Metade da Pedra de Socrethar do Mestre Forjador Morug, na Base-forja: Oblívio e a Segunda Metade da Pedra de Socrethar de Silroth, na Base-forja: Geena.$B$BCumprir missões para os Áugures fará com que sua reputação entre os Aldor diminua.', 'Não quero enviar-lhe a Voren\'thal de mãos vazias. Não me é dado criar frustrações.$B$BPara obter acesso ao Trono de Socrethar, ao norte, vamos precisar usar seus próprios teleportadores, que estão selados pela pedra teleportadora de Socrethar. A primeira metade da pedra encontra-se em posse do Mestre Forjador Morug, na Base-forja: Oblívio. A segunda metade encontra-se em posse do demônio Silroth, na Base-forja: Geena.$B$BObtenha-as e Voren\'thal ficará sem palavras.', '', '', '', '', '', '', '', '', '', 'Fale com o Mestre Espião Thalodien, na Área 52, em Eternévoa.', 0),
(10509, 'ptBR', 'Destinado à glória', 'Leve a Pedra teleportadora de Socrethar a Voren\'thal, o Vidente, no Terraço dos Áugures, em Shattrath.$B$BCumprir missões para os Áugures fará com que sua reputação entre os Aldor diminua.', 'Agora posso enviar-lhe a Shattrath de forma apropriada. Você descobriu as evidências do pacto entre Kael\'thas e a Legião Ardente e conseguiu a chave da porta dos fundos do lorde supremo.$B$BCertifique-se de que Voren\'thal não se afobe de empolgação com as notícias. O velho está ficando um pouco fraco, se é que me entende. Ele fica no interior da Biblioteca do Vidente, no Terraço dos Áugures.', '', '', '', '', '', '', '', '', '', '', 0),
(10510, 'ptBR', 'Para a Mina de Draenetista', 'Colete 5 Cristais da Mina de Draenetista.', 'É bom ver alguém disposto a dar uma força!$B$BBorgrim e eu somos da Liga dos Exploradores e estamos aqui para aprender o que der sobre essas montanhas. Ouvimos todos os tipos de contos e mal posso esperar para montar acampamento e começar.$B$BUma coisa em especial chamou a minha atenção. Os elfos noturnos falam de um lugar no barranco a leste cujo nome é Mina de Draenetista. Fica no extremo sul do posto Malho Sangrento. Eu queria alguns cristais que crescem naturalmente por lá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Bronwyn Fortemalho em Sylvanaar, nas Montanhas da Lâmina Afiada.', 0),
(10511, 'ptBR', 'Banebruto é uma enorme cerveja!', 'Colete 11 Cervejas Banebruto dos Malho Sangrento.', 'Se é para começar as férias com o pé direito, então precisarei de mais cerveja. Infelizmente os elfos não sabem nada sobre a fina arte da fermentação.$B$BFelizmente eu ouvi dizer que os ogros Malho Sangrento, lá no barranco, estão bem preparados. Estou a fim de experimentar.$B$BFaz um favor para mim? Siga para o sul pelo Bosque Vicejante, desça a ladeira para o leste para chegar ao Posto Avançado Malho Sangrento, e fature algumas amostras para mim. Ouvi dizer que eles têm grandes barris de cerveja por todos os lados, e que os cervejeiros os levam para todos os outros ogros.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Borgrim Fortemalho em Sylvanaar, nas Montanhas da Lâmina Afiada.', 0),
(10512, 'ptBR', 'Boa noite, Giralança', 'Use o Barril de Cerveja Banebruto dos Malho Sangrento para tentar embebedar 5 Ogros Giralança.', 'Não beberei mais nenhum gole desse lodo fétido! Mas até que isso me deu uma ideia.$B$B<Borgrim fica com um brilho nos olhos.>$B$BO plano é o seguinte: sabemos que os Malho Sangrento praticamente vivem dessa gororoba, mas o que será que os inimigos deles, os ogros Giralança, acham dela?$B$B$n, quero que você leve o resto deste lixo e tente embebedar os ogros Giralança. Você pode encontrá-los seguindo para o norte a partir do Posto Avançado Malho Sangrento pelo barranco.', '', 'Ogros Giralança bêbados', '', '', '', '', '', '', '', 'Fale novamente com Borgrim Fortemalho em Sylvanaar, nas Montanhas da Lâmina Afiada.', 0),
(10513, 'ptBR', 'Oronok Coração-partido', 'Procure Oronok Coração-partido na Plataforma Estilhaçada, ao norte da Cisterna Serpentálios.', 'Não sei como será possível conseguir o feitiço que os espíritos mencionaram, $n. Para ser sincero, não sei nem por onde poderíamos começar a busca.$B$B<Torlok olha para o vazio, perdido em pensamentos.>$B$BHum... É uma chance remota, mas pode ser a única. Já vi um orc por estas bandas antes. Nos falamos brevemente, uma vez. É um ermitão que diz morar pra cima da Cisterna Serpentálios a nordeste. Procure o orc, Oronok Coração-partido.$B$BComo lhe disse, é uma chance remota.', '', '', '', '', '', '', '', '', '', '', 0),
(10514, 'ptBR', 'Eu fui muitas coisas...', 'Oronok Coração-partido na Fazenda de Oronok, que fica no Vale da Lua Negra, quer que você recolha 10 Tubérculos Lua Negra no Platô Despedaçado.$B$BEle também quer o Apito de Javali de Oronok de volta quando você terminar.', 'Eu já fui muitas coisas, $gestranho:estranha;, mas meu passado não importa. O que importa é o que eu sou agora, e agora eu sou um fazendeiro.$B$BEu uso viljavardos treinados para escavar tubérculos na terra endurecida do Platô Despedaçado. Ultimamente, porém, esfola-pedras saídos de um ninho a nordeste daqui começaram a atacar meus animais, interrompendo minha colheita.$B$BVocê poderia ir até a área ao norte daqui colher tubérculos pra mim? Use este apito quando estiver sobre um montículo de tubérculo e um javardo virá escavá-lo pra você!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra.', 0),
(10515, 'ptBR', 'Dê uma lição', 'Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra, quer que você destrua 10 Ovos de Esfola-pedra Vorasga no Platô Despedaçado.', 'Vamos mostrar aos esfola-pedras o que acontece com quem mexe com Oronok!$B$BQuero que você volte ao Platô Despedaçado e destrua todos os ovos de esfola-pedra que encontrar. Eles estão bem no meio do território dos esfola-pedras, então é bom tomar cuidado.', '', 'Ovo de Esfola-pedra Vorasga Destruído', '', '', '', '', '', '', '', 'Fale novamente com Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra.', 0),
(10516, 'ptBR', 'Paramentos de uma vindicante', 'Recupere a Lâmina da Vindicante Vuuleen e o Escudo da Vindicante Vuuleen.', 'Sei que é estranho, mas quero ficar nesta cela. Assim tenho a oportunidade perfeita para cumprir o meu objetivo: reunir informações sobre os Giralança.$B$BPosso ir embora a qualquer momento, mas gostaria de recuperar minha espada e meu escudo.$B$BDois dos líderes deles estão com os paramentos. Droggam está com a espada e Mugdorg, com o escudo.$B$BSe precisares, pega e usa a cerveja do posto Malho Sangrento ao sul para tirar alguns dos monstros de combate e atrair os dois, mas toma cuidado com os guardas sóbrios que não bebem!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Vindicante Vuuleen no Bastião Giralança, que fica nas Montanhas da Lâmina Afiada.', 0),
(10517, 'ptBR', 'A Luz não gosta de Gorr\'dim, não!', 'Mate Gorr\'dim, líder dos ogros do Bastião Giralança.', 'O líder do Bastião Giralança é conhecido como Gorr\'dim. Acredita... o nome é adequado.$B$BEm teu lugar eu não o subestimaria. Ele foi astuto o bastante para fazer seu clã virar o favorito de Gruul, o Matador de Dragões, e agora eles dominam estas montanhas. Gorr\'dim sempre fica com um comparsa e também com os guardas que juraram não beber a cerveja dos Malho Sangrento. $B$BPela segurança de Sylvanaar, peço que voltes lá e cuides dele.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Vindicante Vuuleen no Bastião Giralança, que fica nas Montanhas da Lâmina Afiada.', 0),
(10518, 'ptBR', 'Bandeira da discórdia', 'Finque a bandeira dos Giralança no topo da Torre do Malho do Norte para atrair Gurn Rangalarva. Recolha a bandeira do clã Giralança e o capacete de Gurn Rangalarva.', 'Quero que roubes a bandeira dos Giralança de um dos campeões e a leve ao sul para o posto Malho Sangrento. Finca-a no topo da Torre do Malho do Norte.$B$BIsso deixará os Malho Sangrento enfurecidos e eles te atacarão sem compaixão. Mas também concentrarão o ódio no Bastião Giralança, longe de Sylvanaar.$B$BA missão estará completa quando derrotares Gurn Rangalarva e te apropriares do capacete dele. Leva-o para Sylvanaar.$B$B$n, tua tarefa não será fácil. Leva um ou dois amigos contigo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Caelumbra em Sylvanaar, nas Montanhas da Lâmina Afiada.', 0),
(10519, 'ptBR', 'A Cifra da Danação: verdade e história', 'Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra, quer que você escute a história dele. Fale com Oronok para começar a ouvir a história.', '<Oronok ajusta a postura, ficando mais alto.>$B$BEu tinha que me assegurar, $n. E para me assegurar, tinha que testar você. Por favor, perdoe a minha pequena farsa. Eu sou um fazendeiro tanto quanto você é $g uma mulher:um homem;. Ou seja, nem um pouco.$B$BSe você quiser recuperar a Cifra da Danação, precisa ouvir o que vou lhe contar. Quando estiver $gpronto:pronta;, me avise e lhe contarei a história.', 'A Cifra da Danação: verdade e história', '', '', '', '', 'A Cifra da Danação: verdade e história', '', '', '', 'Fale novamente com Oronok Coração-partido no Vale da Lua Negra.', 0),
(10520, 'ptBR', 'Assisting Arch Druid Staghelm', 'Speak with Arch Druid Fandral Staghelm in Darnassus.', 'Excuse me $c, but I\'d like just a moment of your time if possible.$B$BThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project. While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.$B$BPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.', '', '', '', '', '', '', '', '', '', '', 0),
(10521, 'ptBR', 'Grom\'tor, filho de Oronok', 'Encontre Grom\'tor, filho de Oronok, no Pontal dos Serpentálios, no Vale da Lua Negra.', 'Meu primogênito, Grom\'tor, partiu para vasculhar o Pontal dos Serpentálios, diretamente a sudoeste daqui.$B$BEle é o guerreiro da família, sanguinário e com um gênio terrível... ele puxou à mãe, sabe. Procure por ele nas cercanias do Pontal dos Serpentálios. Se você vir cadáveres de naga, Grom\'tor certamente estará por perto.$B$BAo encontrá-lo, diga-lhe o seguinte: "Nós derramamos sangue por causas justas". Assim ele saberá que você é $gamigo:amiga; dos Coração-partido e você evitará uma morte prematura.', '', '', '', '', '', '', '', '', '', '', 0),
(10522, 'ptBR', 'A Cifra da Danação: a carga de Grom\'tor', 'Grom\'tor, Filho de Oronok, no Pontal dos Serpentálios, no Vale da Lua Negra, quer que você recupere o Primeiro Fragmento da Cifra da Danação.', 'Essa naga nojenta já é a sexta que eu interrogo hoje. Com uma armadura bonita assim, eu imaginei que ela devia saber alguma coisa. As outras não disseram nada que prestasse.$B$B<Grom\'tor aponta para os cadáveres das nagas em volta.>$B$BEu só precisei espancar ela uma vez pra ela abrir a boca.$B$BA primeira parte da cifra está escondida num baú no Pontal dos Serpentálios ou na Cisterna Serpentálios, a leste daqui. Ela disse que as nagas têm as chaves. Mate as nagas, pegue as chaves e use-as pra abrir os baús serpentálios. Volte aqui quando achar a cifra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Grom\'tor, Filho de Oronok, no Pontal dos Serpentálios, no Vale da Lua Negra.', 0),
(10523, 'ptBR', 'A Cifra da Danação: primeiro fragmento recuperado', 'Leve a Caixa-forte de Grom\'tor para Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra.', '<Grom\'tor dobra os documentos e os coloca numa caixa com tranca.>$B$BLeve esta caixa para meu pai. Ele aguarda seu retorno na fazenda, a noroeste daqui.$B$BDiga a ele que voltarei para casa logo. Assim que terminar de me divertir...', '', '', '', '', '', '', '', '', '', '', 0),
(10524, 'ptBR', 'Artefatos do clã Senhor do Trovão', 'Colete o Tambor do Clã Senhor do Trovão, a Flecha do Clã Senhor do Trovão e a Tabuleta do Clã Senhor do Trovão.', 'O artefato tem marcas que indicam que foi criado pelos orcs do clã Senhor do Trovão. Eles viviam na Cidadela do Senhor do Trovão antes de se transformarem em orcs vis.$B$BOs ogros Giralança moraram na cidadela até há pouco, quando foram expulsos pela Horda.$B$BVocê já deve ter ouvido falar de outros artefatos perdidos. Estão procurando um tambor, uma flecha e uma tabuleta.$B$BEncontre-os no Bastião Giralança e entregue-os a Rokgah Punhossangue.', '', '', '', '', '', '', '', '', '', 'Fale com Rokgah Punhossangue na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10525, 'ptBR', 'Guia de visão', 'Use o Fragmento de Alma do Fogo para transformar seu espírito em um guia de visão para revelar a localização do último artefato dos Senhor do Trovão.', '$R imbecil. Quase destruiu o tambor!$B$BTrabalhei muito para chegar onde estou e estava de mãos vazias até agora. Ao menos, você conseguiu ter êxito onde todos os outros falharam. Ou pior.$B$BChegou a hora de evocar uma visão que $go:a; levará à última relíquia que procuro.$B$BPegue este fragmento abrasador da minha alma. Use-o para transformar o seu corpo em chamas e preparar o espírito para um guia de visão que se lançará para revelar a localização da última relíquia dos Senhor do Trovão.', 'Último Artefato encontrado', '', '', '', '', 'Último Artefato encontrado', '', '', '', 'Fale com Rokgah Punhossangue na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10526, 'ptBR', 'A Lança do Trovão', 'Colete a Lança do Trovão.', 'Se a visão que lhe concedi for verdadeira, então você deve ir até o barranco e seguir até o extremo sul do Barranco Malho Sangrento. A Mina de Draenetista fica lá.$B$BVá até o outro lado da mina e recupere a Lança do Trovão. Ignore todo o resto! Não tenho interesses nos cristais da mina e nem nos ogros.$B$BVenha trazer a lança assim que puser as mãos nela!$B$BE, $n, tenha extremo cuidado com ela... Não quero nem pensar no que aconteceria se a quebrasse.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rokgah Punhossangue na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10527, 'ptBR', 'Ar\'tor, filho de Oronok', 'Encontre Ar\'tor, Filho de Oronok, no Pontal Illidari no Vale da Lua Negra.', 'Meu filho mais novo, Ar\'tor, partiu para investigar o Pontal Illidari, que fica longe, a sudoeste daqui, aninhado entre a Cidadela da Legião e a Fortaleza Martelo Feroz.$B$BAr\'tor é um caçador imensamente habilidoso e um mestre rastreador, mas mesmo assim eu temo que ele tenha se metido em algo grande demais. O Pontal Illidari é o campo de teste dos demônios de Illidan. São demônios que abandonaram a Legião Ardente para se juntar ao Traidor!$B$BVá até o Pontal Illidari e encontre Ar\'tor, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(10528, 'ptBR', 'Prisões demoníacas de cristal', 'Procure e mate a Rainha da Dor Gabrissa no Pontal Illidari. Em seguida, volte até o cadáver de Ar\'tor, Filho de Oronok, com a Chave Cristalina.', 'Ao examinar a cena, você percebe que Ar\'tor está sendo mantido no ar pelos raios de energia que emanam dos cristais pairando em volta da runa. Por mais que você tente, Ar\'tor não pode ser removido.$B$BVocê percebe que os cristais têm uma ranhura vazia na base, talvez para uma chave. Também é aparente que súcubos periodicamente executam algum tipo de ritual no local.$B$BVasculhe o Pontal Illidari em busca da líder delas. Talvez ela tenha a chave para a libertação de Ar\'tor.', '', '', '', '', '', '', '', '', '', 'Volte até Ar\'tor, Filho de Oronok, no Pontal Illidari no Vale da Lua Negra.', 0),
(10531, 'ptBR', 'The Battle for Arathi Basin!', 'Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.', '$n, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.$B$BAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy\'s banner and rip it from its flag post!$B$BWhen you have done this to all four points, return to me.', '', 'Mine Assaulted', 'Lumber Mill Assaulted', 'Blacksmith Assaulted', 'Farm Assaulted', '', '', '', '', 'Return to Field Marshal Oslight at Refuge Pointe in Arathi Highlands.', 0),
(10537, 'ptBR', 'Lohn\'goron, arco dos Coração-partido', 'O Espírito de Ar\'tor, no Pontal Illidari do Vale da Lua Negra, quer que você recupere Lohn\'goron, Arco dos Coração-partido, com um dos demônios da área.', 'É um sinal, $n. Mesmo morto eu não posso ser derrotado. Recuperar uma parte da Cifra da Danação é o meu destino. Com a sua ajuda, tal destino será cumprido.$B$BAntes que possamos embarcar nessa jornada, eu preciso do meu arco longo, Lohn\'goron. É uma herança de família que foi passada de Coração-partido a Coração-partido durante gerações.$B$BMeus instintos me dizem que um demônio o roubou do meu cadáver. Mate os demônios por aqui até encontrar meu arco.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Espírito de Ar\'tor, Filho de Oronok, no Pontal Illidari no Vale da Lua Negra.', 0),
(10538, 'ptBR', 'Sangue quente', 'Use o Sangue de Olhos Sangrentos no Caldeirão Amaldiçoado para fazer Sangue Fervido. Leve 12 amostras de Sangue Fervido para o Boticário Alberto no Acampamento Quebra-espinha.', 'Meu último experimento não foi uma perda completa. Eu guardei um pouco do sangue que você me trouxe. Agora que está fervido, o sangue deve estar livre de qualquer maldição que as bruxas dos Olhos Sangrentos tenham evocado.$B$BMas eu preciso de mais sangue para estudar. Vá coletar sangue dos orcs Olhos Sangrentos em Zeth\'Gor. Quando tiver coletado o sangue, leve-o para o caldeirão amaldiçoado e ferva-o. Traga-me o sangue fervido.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Boticário Alberto no Acampamento Quebra-espinha, que fica na Península Fogo do Inferno.', 0),
(10540, 'ptBR', 'A Cifra da Danação: a missão de Ar\'tor', 'O Espírito de Ar\'tor no Pontal Illidari, no Vale da Lua Negra, quer que você recupere o Segundo Fragmento da Cifra da Danação, que está em poder de Veneratus, o Muitos.$B$BCriaturas atacadas ou danificadas pelo Espírito de Caçador não fornecerão saque nem experiência.', 'Finalmente estamos prontos. Vou lhe conceder uma parte do meu espírito, $gherói:heroína;. Vou $gprotegê-lo:protegê-la; e ajudar na batalha contra o mal.$B$BVocê deve então viajar para o sul, em direção à retaguarda do Pontal Illidari. Lá, oculta no éter, está uma criatura vil conhecida como Veneratus, o Muitos. Meu espírito de caçador vai revelá-lo quando ele estiver próximo.$B$BDestrua Veneratus e tire do corpo dele a segunda parte da Cifra da Danação.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Espírito de Ar\'tor, Filho de Oronok, no Pontal Illidari no Vale da Lua Negra.', 0),
(10541, 'ptBR', 'A Cifra da Danação: segundo fragmento recuperado', 'Leve a Arca de Ar\'tor para Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra.', 'Eu lhe agradeço, $gherói:heroína;. Sem você, meu espírito permaneceria para sempre neste lugar amaldiçoado.$B$B<Ar\'tor lhe entrega uma arca espectral.>$B$BLeve-a e entregue ao meu pai na fazenda, longe daqui, a nordeste, nas montanhas acima da Cisterna Serpentálios... Dentro estão Lohn\'goron e a segunda parte da cifra.$B$BEle ficará triste ao saber da minha morte. Prometa que você dirá a ele que morri uma alma livre. Diga-lhe que eu vejo os campos de caça, e eles são gloriosos. E diga que estarei esperando por ele lá...', '', '', '', '', '', '', '', '', '', '', 0),
(10542, 'ptBR', 'Meu narguilé! Minhas cervas!', 'Colete o Narguilé de T\'chali e 10 Cervejas Banebruto dos Malho Sangrento.', 'T\'chali sempre foi um troll maneiro. Veio pra ensiná os Malho Sangrento a fazê cerva. Só que no final os Malho Sangrento enterraram T\'chali e deixaram ele aqui pra abotoar o paletó!$B$BO pior é que roubaram meu narguilé!$B$BE aí? Tá a fim de dar uma mão pro T\'chali? Traz o narguilé de volta. T\'chali acha que os ogros ladrões foram pro sudoeste, perto da mina.$B$BAproveita que cê vai lá e traz umas cervas também!', '', '', '', '', '', '', '', '', '', 'Fale novamente com T\'chali, o Mandingueiro, no Barranco Malho Sangrento, que fica nas Montanhas da Lâmina Afiada.', 0),
(10543, 'ptBR', 'Grimnok e Korgaah, a batata tá assando!', 'Mate Grimnok Guerranato e Korgaah.', 'T\'chali tava esperando a hora da vingança!$B$BFoi o Grimnok Guerranato que tava liderando no dia em que enterraram T\'chali. No dia seguinte, foi Korgaah que veio do sul pra dar uma bicuda na cabeça do T\'chali.$B$BQuero mais é que eles morram!$B$BO Grimnok tá lá na Torre Martelo do Sul, no Posto Avançado Malho Sangrento. O Korgaah tá no topo de uma estrutura no extremo norte do Bastião Giralança. Korgaah tem guardas que não bebem, então usa a cerva pra chamar ele pra longe. Toma cuidado que os guardas não vão beber de jeito nenhum.', '', '', '', '', '', '', '', '', '', 'Fale novamente com T\'chali, o Mandingueiro, no Barranco Malho Sangrento, que fica nas Montanhas da Lâmina Afiada.', 0),
(10544, 'ptBR', 'Uma maldição para os dois clãs!', 'Use o Fetiche Sinistramente Forte para amaldiçoar 5 prédios ou torres no Bastião Giralança e 2 no Posto Avançado Malho Sangrento.', 'T\'chali qué se vingá de todos os ogros!$B$BT\'chali era mandingueiro batuta quando tava vivo. Mete a mão na minha cova que cê vai achá um fetiche forte pra caramba.$B$BÉ só invocar a magia do fetiche na entrada das construções e torres do Bastião Giralança e do Posto Malho Sangrento. O vodu vai evocá um espírito do mal pra cê derrotá. Isso vai amaldiçoá as construções.$B$BMas cuidado que se cê tentá amaldiçoá uma construção já amaldiçoada, cê vai atrair outro espírito sinistro!', '', 'Prédios do Bastião Giralança amaldiçoados', 'Prédios do Posto Avançado Malho Sangrento amaldiçoados', '', '', '', '', '', '', 'Fale novamente com T\'chali, o Mandingueiro, no Barranco Malho Sangrento, que fica nas Montanhas da Lâmina Afiada.', 0),
(10545, 'ptBR', 'Barril dos Giralança', 'Use o Barril de Cerveja Banebruto dos Malho Sangrento para embebedar 5 Ogros Giralança.', 'Bom, como T\'chali tava dizendo, ele ajudou os Malho Sangrento a fazer cerva. Mas T\'chali ainda não disse por quê. Os Malho Sangrento tão passando aperto, saca. Os Giralança tão acabando com eles, e eles precisavam de uma arma pra ajudar na batalha. Foi aí que T\'chali teve uma ideia da hora: criar uma cerveja que deixa a pessoa mais forte, mas enfraquece os inimigos. Só que T\'chali não conseguiu testar a parada! Por favor, leva essa cerva lá no Bastião Giralança pra ver se funciona!', '', 'Ogros Giralança bêbados', '', '', '', '', '', '', '', 'Fale novamente com T\'chali, o Mandingueiro, no Barranco Malho Sangrento, que fica nas Montanhas da Lâmina Afiada.', 0),
(10546, 'ptBR', 'Borak, filho de Oronok', 'Encontre Borak, Filho de Oronok, perto da Ponta do Eclipse, no Vale da Lua Negra.', 'Enquanto Ar\'tor caçava e Grom\'tor lutava, Borak estudava. Um dia, Borak assumiu a vocação de erudito e partiu em busca das terras selvagens de Draenor. Voltou para casa há alguns anos, completamente mudado.$B$BSeu senso elevado de percepção e sua acuidade mental forjaram um assassino silencioso.$B$BAgora um orc confiante e poderoso, Borak decidiu recuperar a parte mais bem guardada da cifra.$B$BEncontre-se com Borak, que está escondido perto da Ponta do Eclipse, bem ao sul. Ele vigia sob as sombras da ponte.', '', '', '', '', '', '', '', '', '', '', 0),
(10547, 'ptBR', 'De cardólatras e ovos...', 'Borak, Filho de Oronok, junto à ponte ao norte da Ponta do Eclipse, quer que você encontre um Ovo Podre de Arakkoa. O ovo deve ser entregue a Tobias, o Come-lixo, em Shattrath, localizada no noroeste da Mata Terokkar.', 'Eu teria desistido se não tivesse percebido... Ele é um cardólatra. Não tinha notado inicialmente, mas os sinais estão todos lá...$B$BAgora, se pudermos colocar nossas mãos em um pouco de cardossangue, estaremos feitos.$B$BNas minhas viagens, conheci um Degradado suspeito em Shattrath chamado Tobias.$B$BO sujeito ganha a vida traficando cardossangue para elfos sangrentos em troca de ovos podres de arakkoa.$B$BDiretamente a oeste daqui ficam as ruínas arakkoas. Vasculhe-as em busca de um ovo e vá para o Bairro Inferior em Shattrath. É lá que você encontrará Tobias.', '', '', '', '', '', '', '', '', '', 'Procure Tobias, o Come-lixo, em Shattrath, na Mata Terokkar.', 0),
(10550, 'ptBR', 'O feixe de cardossangue', 'Leve o Feixe de Cardossangue a Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra.', 'Eu não estava mentindo. O ovo estava bom à beça. Onde você conseguiu?$B$BBem, se você algum dia precisar de mais cardossangue, sabe onde eu estou e o que eu quero.$B$BAqui está o pacote de bagulho. Leve para o seu benfeitor.', '', '', '', '', '', '', '', '', '', '', 0),
(10551, 'ptBR', 'Aliança com os Aldor', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(10552, 'ptBR', 'Aliança com os Áugures', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(10553, 'ptBR', 'Voren\'thal, o Vidente', 'Fale com Voren\'thal, o Vidente, na Biblioteca dos Videntes, no Terraço dos Áugures, que fica em Shattrath.$B$BCumprir missões para os Áugures fará com que sua reputação com os Aldor diminua.', 'Agora que você escolheu seu lado, $n, é hora de conhecer o líder dos Videntes.$B$BVoren\'thal, o Vidente, se encontra na Biblioteca dos Videntes, no Terraço dos Áugures.$B$BVeja se você pode ajudá-lo com alguma coisa. Ele ficará feliz em saber que você decidiu se aliar aos Áugures.', '', '', '', '', '', '', '', '', '', '', 0),
(10554, 'ptBR', 'Ishanah', 'Fale com a Alta-sacerdotisa Ishanah, no Templo da Luz Perene, que fica no Terraço dos Aldor em Shattrath.$B$BCumprir missões para os Aldor fará com que sua reputação com os Áugures diminua.', 'Agora que decidiste se aliar aos Aldor, farias bem em te apresentar à líder deles. A Alta-sacerdotisa Ishanah se encontra no Templo da Luz Perene.', '', '', '', '', '', '', '', '', '', '', 0),
(10555, 'ptBR', 'Mal-estar', 'Colete 18 Plumas de Lashh\'an Arrancadas.', 'A magia dos arakkoas Lashh\'an não é natural. Eles arrancam punhados (ou seriam "garrados"?) de suas próprias plumas para usar como reagentes!$b$bIsso não tem cara de magia boa... Eu vim aqui para aprender mais sobre os feitiços dos arakkoas, mas não acho que seja uma boa ideia chegar perto demais deles.$b$bVocê pode resolver meu problema. Basta lançar um dos feitiços em você $gmesmo:mesma; e voltar aqui pra eu estudar a magia. Você terá que encontrar um dos livros de feitiços deles nas árvores do Véu Lashh.$b$bE é melhor arranjar algumas plumas, ou você não conseguirá lançar feitiço nenhum.', '', '', '', '', '', '', '', '', '', 'Abra as páginas do Tomo dos Lashh\'an no Véu Lashh, que fica nas Montanhas da Lâmina Afiada.', 0),
(10556, 'ptBR', 'Arranhões', 'Use o Punhado de Plumas no Círculo de Feitiço dos Lashh\'an.', 'Os pictogramas indicam que as plumas devem ser usadas para lançar o feitiço em um dos círculos do poder no Véu Lashh.$b$bA iconografia confusa parece mostrar um arakkoa recebendo o espírito de um kaliri.', '', 'Deixe Daranelle analisar a aura Kaliri', '', '', '', '', '', '', '', 'Fale novamente com Daranelle em Sylvanaar, que fica nas Montanhas da Lâmina Afiada.', 0),
(10557, 'ptBR', 'Voo de teste: capacitório de zefírio', 'Fale com Netto Desastraz e use o Capacitório de Zefírio.', 'Eu montei um dispositivo incrível, o Capacitório de Zefírio, e tenho certeza de que vai funcionar tinindo, mas... quer me ajudar a testar?$B$BVai ser uma aventura e tanto!$B$BFale com o meu irmão gêmeo, Netto. Boa sorte, $n. Volte depois que testar. Ou... se não puder por ter se machucado, o seu parente mais próximo pode vir pegar o pagamento.', 'Teste o experimento de Betto', '', '', '', '', 'Teste o experimento de Betto', '', '', '', 'Fale novamente com Betto Desastraz na Estação do Tocha, nas Montanhas da Lâmina Afiada.', 0),
(10562, 'ptBR', 'Cercados!', 'Comandante de Ala Nuainn, do lado de fora da Fortaleza Martelo Feroz, quer que você mate 10 Atacantes Infernais.', 'Não baixe a guarda, $r. Estamos sob ataques constantes da Legião Ardente.$B$BDa Cidadela da Legião a noroeste, os demônios arremessam uma torrente incessante de infernais. Assim que acabamos de matar uma leva, novos meteoros caem e iniciam uma nova onda de ataque.$B$BMeus homens estão estropiados e exaustos. Não sei quanto tempo vão aguentar. Por favor, $n, ajude com as nossas defesas. Assuma um lugar na linha de combate e impeça o avanço dos infernais!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Ala Nuainn na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10563, 'ptBR', 'Contra a Cidadela da Legião', 'Rume para a Cidadela da Legião e encontre o Dispositivo de Comunicação da Legião. Enquanto estiver ao lado do dispositivo comunicador, use o disfarce e descubra os planos da Legião. Fale novamente com Comandante de Ala Nuainn na Fortaleza Martelo Feroz.', 'A fortaleza da Cidadela da Legião é praticamente impenetrável e, sinceramente, eu não tenho tropas disponíveis para um ataque. Depositamos todas as nossas esperanças em você, $n.$B$BAs parcas informações que conseguimos reunir indicam que a Legião estoca e prepara os infernais na cidadela. Usando o disfarce que vou lhe dar, você terá que se esgueirar e invadir a Cidadela da Legião, para poder descobrir os planos deles. Acho que o melhor jeito será interceptar ou espreitar comunicações entre os comandantes. Boa sorte, $n.', '', 'Descubra os Planos da Legião', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Ala Nuainn na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10564, 'ptBR', 'Os infernais que se explodam!', 'Use a Bomba Vil em cima do glifo verde na Cidadela da Legião, e em seguida se apresente ao Comandante de Ala Nuainn na Fortaleza Martelo Feroz.', 'O dispositivo que montamos não vai ganhar nenhum concurso de beleza, mas deve ser capaz de destruir os infernais armazenados na Cidadela da Legião. Julgando pelo efeito que o núcleo de força teve no Lago Fétido, deve ter um poder explosivo respeitável.$B$BSe você armar o dispositivo no meio do glifo verde na cidadela, a explosão provavelmente atingirá todos os infernais.', '', 'Destrua os Infernais da Cidadela da Legião', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Ala Nuainn na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10565, 'ptBR', 'As pedras de Vekh\'nir', 'Colete e use um Cristal Vekh\'nir no Círculo de Feitiço Vekh\'nir para criar um Cristal Vekh\'nir Carregado.', 'Os arakkoas de Vekh\'nir têm sido um espinho em nosso flanco por muitos anos. Uma estranha religião os guia, uma religião que os têm deixado em polvorosa. Agora os arakkoas andam carregando cristais, que são usados para algum propósito sinistro.$B$BEu sei algo a respeito dos rituais dos arakkoas. Eles levam os cristais para os círculos de feitiço para infundi-los. Nós aqui da aldeia gostaríamos de descobrir mais a respeito disso. Ataque alguns arakkoas até achar um cristal, e então traga-o para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dertrok na Vila de Mok\'nathal, que fica nas Montanhas da Lâmina Afiada.', 0),
(10566, 'ptBR', 'Tentativa e erro', 'Teste cada varinha de Dertrok em um ogro escravo dos arakkoas. Cada varinha precisará de um Cristal Vekh\'nir Infuso para ser usada.', 'Fiz quatro varinhas e acredito que elas aumentarão o poder dos cristais dos arakkoas. Leve as quatro para a Mina de Trogma e tente usá-las nos ogros escravos.$b$bMas antes, para cada varinha, você precisará encontrar um cristal infuso dos arakkoas.$b$bVolte aqui quando descobrir qual funciona melhor.', '', 'Teste a primeira varinha', 'Teste a segunda varinha', 'Teste a terceira varinha', 'Teste a quarta varinha', '', '', '', '', 'Fale novamente com Dertrok na Vila de Mok\'nathal, que fica nas Montanhas da Lâmina Afiada.', 0),
(10567, 'ptBR', 'Criação do pingente', 'Colete 6 Garras de Ruuan\'ok e as use no Círculo do Oráculo Ruann\'ok para evocar um Emissário do Corvo. Mate-o para coletar o Pingente do Emissário.', 'Os arakkoas do Bosque Ruuan exaltam os Emissários do Corvo, os arautos do deus que eles veneram. Eles acreditam que os Emissários os protegem dos céus, onde recebem ensinamentos do Corvo, e de onde descem para passá-los adiante.$b$bAlém disso, os Emissários têm poder direto sobre as almas dos arakkoas por meio de pingentes mágicos. É destes pingentes que nós precisamos.$b$bAtraia um dos Emissários matando seu redil, pegando suas garras e as usando num círculo de invocação.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Timeon no Arvoredo Eterno, que fica nas Montanhas da Lâmina Afiada.', 0),
(10568, 'ptBR', 'Tabuletas de Baa\'ri', 'A Anacoreta Ceyla no Altar de Sha\'tar quer que você colete 12 Tabuletas Baa\'ri no chão e com os Trabalhadores Grislíngua nas Ruínas de Baa\'ri.$B$BCompletar missões para os Aldor reduzirá sua reputação junto aos Áugures.', 'Há muitos anos, o temido bruxo conhecido por Gul\'dan elevou um vulcão no meio do Vale da Lua Negra. A aldeia draeneica de Baa\'ri, a sudoeste daqui, foi soterrada sob a lava junto com os habitantes e artefatos de valor religioso.$B$BA tribo traiçoeira de Degradados conhecida como Grislíngua está escavando a área a mando de Illidan. Precisamos aproveitar a oportunidade para recuperar as Tabuletas de Baa\'ri, um texto antigo que, de acordo com rumores, contém os segredos do Templo de Karabor, agora conhecido como Templo Negro.', '', '', '', '', '', '', '', '', '', 'Procure a Anacoreta Ceyla no Altar de Sha\'tar, que fica no Vale da Lua Negra.', 0),
(10569, 'ptBR', 'As Ruínas de Sketh\'lon', 'Consiga as Páginas 1, 2 e 3 do Diário do Comandante de Sketh\'lon com os arakkoas do Conclave Negro nas Ruínas de Sketh\'lon e as entregue ao Cavalga-grifo Kieran.', 'Os batedores fizeram relatos perturbadores sobre os acampamentos arakkoas arruinados que encontraram.$B$BOs fantasmas de poderosos magos arakkoas exibem poderes que nunca imaginamos que eles tivessem. Eles parecem estar se organizando, como se estivessem se preparando para alguma coisa, mas sabemos muito pouco. Não podemos mais permanecer na ignorância!$B$BViaje para o norte até as Ruínas de Sketh\'lon, a noroeste da Forja da Morte, e procure indícios das motivações deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Cavalga-grifo Kieran na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10570, 'ptBR', 'Um cardólatra da pesada', 'Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra, quer que você recupere a Missiva de Tempesfúria.', '<Borak pega o pacote de cardossangue com você e o leva até o nariz.>$B$BPungente...$B$BAgora leve o pacote e o coloque do outro lado da ponte. Quando o emissário fizer a ronda diária, será compelido a pegar o pacote, sem o guarda-costas. Sabe, os elfos sangrentos desprezam os cardólatras. Se qualquer um dos compatriotas dele descobrir...$B$BTudo que você terá de fazer será esperar que ele dispense o guarda-costas. Quando ele estiver sozinho, ataque! Mate-o e pegue a missiva.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Borak, Filho de Oronok, no Vale da Lua Negra.', 0),
(10571, 'ptBR', 'Oronu, o Ancião', 'A Anacoreta Ceyla no Altar de Sha\'tar quer que você obtenha as Ordens de Akama que estão com Oronu, o Ancião, nas Ruínas de Baa\'ri.$B$BCompletar missões para os Aldor reduzirá sua reputação junto aos Áugures.', 'De acordo com as tabuletas, havia um artefato conhecido como Medalhão de Karabor na cidade Baa\'ri. Só os sacerdotes draeneis mais elevados recebiam tal honra, pois os medalhões permitiam acesso ilimitado ao Templo de Karabor.$B$BÉ preciso saber se os Grislíngua já recuperaram o medalhão que era mantido em Baa\'ri. O poder do artefato nos ajudaria muitíssimo na contenda contra Illidan.$B$BO tenente de Akama em Baa\'ri, Oronu, o Ancião, recebe ordens escritas do mestre diariamente. Obtêm-nas e traze-as para mim.', '', '', '', '', '', '', '', '', '', 'Procure a Anacoreta Ceyla no Altar de Sha\'tar, que fica no Vale da Lua Negra.', 0),
(10572, 'ptBR', 'Bomba la bomba', 'Obtenha um Núcleo de Força de Aníquilus e uma Placa de Armadura de Aníquilus, e leve-os ao Comandante de Ala Nuainn, na Fortaleza Martelo Feroz.', 'Não podemos permitir que a Legião destrua a Fortaleza Martelo Feroz ao passar marchando em direção ao Templo Negro.$B$BExiste apenas uma forma de impedi-los, $n. É necessário criar um explosivo grande o bastante para destruir o estoque inteiro de infernais da Legião.$B$BDentro do Lago Fétido, próximo à Cidadela da Legião, você encontrará um velho núcleo de força de aníquilus que poderá ser usado como base do dispositivo. Vasculhe os outros destroços próximos ao aníquilus em busca de placas blindadas para fazermos a carcaça.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Ala Nuainn na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10573, 'ptBR', 'A Forja da Morte', 'Apresente-se a Ewan Asalouca, o Arrojado, na Torre da Forja da Morte.', 'De acordo com o que você descobriu na Cidadela da Legião, sabemos que os aliados da Legião, o Concílio da Sombras, estão produzindo infernais na Forja da Morte. Despachei um pequeno grupo de batedores para vigiar a área, mas eles não poderão realizar tudo que precisamos.$B$BSe a Forja da Morte continuar operando sem problemas, o concílio conseguirá reconstituir o estoque de infernais que você destruiu na Cidadela da Legião.$B$BQuero que você se encontre com Ewan Asalouca, o Arrojado, na Torre da Forja da Morte, a noroeste, se erguendo sobre a própria Forja da Morte.', '', '', '', '', '', '', '', '', '', '', 0),
(10574, 'ptBR', 'Os corruptores Grislíngua', 'Obtenha os quatro fragmentos de medalhão com Haalum, Eykenen, Lakaan e Uylaru e procure a Anacoreta Ceyla no Altar de Sha\'tar, que fica no Vale da Lua Negra.$B$BCompletar missões para os Aldor reduzirá sua reputação com os Áugures.', 'De acordo com a carta de Akama, quatro fragmentos do medalhão foram escavados e dados aos corruptores Grislíngua. Os perversos Degradados um dia foram poderosos xamãs que agora aproveitam-se dos mesmos elementos que um dia reverenciaram.$B$BHaalum, o Corruptor do Ar, encontra-se na Trilha da Asa Etérea. Eykenen e Uylaru, Corruptores da Terra e do Fogo, foram vistos pela última vez nos Poços Fétidos perto da Mão de Gul\'dan. Segundo rumores, Lakaan, o Corruptor da Água, está próximo ao Pontal dos Serpentálios.$B$BEncontra-os e consegue os fragmentos de medalhão.', '', '', '', '', '', '', '', '', '', 'Procure a Anacoreta Ceyla no Altar de Sha\'tar, que fica no Vale da Lua Negra.', 0),
(10575, 'ptBR', 'A Jaula do Carcereiro', 'A Anacoreta Ceyla quer que você entre na Jaula do Carcereiro, ao sul das Ruínas de Baa\'ri e interrogue Sanoru quanto à localização de Akama.$B$BCompletar missões para os Aldor reduzirá sua reputação junto aos Áugures.', 'Os fragmentos que tu trouxeste formam apenas metade do medalhão. Akama, o líder dos Grislíngua, deve estar com a outra metade.$B$BLamento te pedir isso, considerando que Akama é tão maligno quanto ardiloso.$B$BHá rumores de que ele e os Devotos da Morte Grislíngua, os membros mais depravados e brutais da tribo, mantêm uma câmara de torturas sob a Jaula do Carcereiro.$B$BPreciso que tu encontres essa temível prisão e descubras o paradeiro de Akama. O tenente dele no local é um Degradado conhecido como Sanoru. Interroga-o, se precisares.', '', '', '', '', '', '', '', '', '', '', 0),
(10576, 'ptBR', 'O golpe Lua Negra', 'Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra, quer que você recupere 6 peças de Armadura Eclipsion.', '<Borak $go:a; examina de cima abaixo.>$B$BEssa tarefa será complicada, mas acho que eu consigo dar um jeito.$B$BPosso disfarçar você como $gum desses elfos sangrentos:uma dessas elfas sangrentas; Illidari, $n. Mas, para isso, primeiro preciso de várias peças de armadura $g deles:delas;. É essencial que a armadura esteja limpa. Nada de manchas de sangue! Queremos evitar suspeitas.$B$BTraga-me o equipamento e eu cuidarei do resto do disfarce.$B$BUma vez que o disfarce estiver montado, você entregará a mensagem ao Grão-comandante pessoalmente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Borak, Filho de Oronok, no Vale da Lua Negra.', 0),
(10577, 'ptBR', 'O que Illidan quer, Illidan consegue...', 'Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra, quer que você entregue a Mensagem de Illidan ao Grão-comandante Ruusk na Ponta do Eclipse.', 'Tome este disfarce e vá até a Ponta do Eclipse. Uma vez lá dentro, use o disfarce para se misturar. Os elfos sangrentos Eclipsion serão iludidos pelo disfarce e, assim, eles lhe darão passagem segura até o grão-comandante Ruusk.$B$BAo encontrá-lo, diga-lhe o próximo esconderijo da cifra. Você terá de atuar como nunca antes, $n. Aja como se você fosse $Go superior:a superiora; dele, entregando uma mensagem do senhor supremo. Acho que será o bastante!$B$BAh, cuidado com os falcodragos, pois eles não são enganados pelo disfarce.', 'Mensagem de Illidan Entregue', '', '', '', '', 'Mensagem de Illidan Entregue', '', '', '', 'Fale novamente com Borak, Filho de Oronok, no Vale da Lua Negra.', 0),
(10578, 'ptBR', 'A Cifra da Danação: a missão de Borak', 'Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra, quer que você recupere o Terceiro Fragmento da Cifra da Danação com Ruul, o Obscurecente.$B$BNesta missão, será melhor ir em grupo.', 'Aquele fragmento da Cifra jamais chegará a Zuluhed. Você vai emboscar Ruul, o Obscurecente, e o transporte dele antes que tenham chance de fazer a entrega.$B$BA Fortaleza Presa do Dragão fica diretamente ao leste daqui, do outro lado dos Campos da Asa Etérea. Você encontrará Ruul em algum ponto entre a Fortaleza Presa do Dragão e o Sacrário Estelar. Ataque forte e ataque rápido! E $n, pelo que eu ouvi, esse Ruul vai ser dureza. Fique alerta.$B$BTraga-me a Cifra quando tiver sucesso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Borak, Filho de Oronok, no Vale da Lua Negra.', 0),
(10579, 'ptBR', 'A Cifra da Danação: terceiro fragmento recuperado', 'Leve o Cofre de Borak para Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra.', 'Leve o cofre ao meu pai. Ele ainda mora na Fazenda de Oronok, bem longe ao norte, acima da Cisterna Serpentálios. Quando todos os três fragmentos forem reunidos, as palavras antigas serão conhecidas novamente.$B$BBoa sorte, $n. Diga ao meu pai que eu estarei em casa em breve.', '', '', '', '', '', '', '', '', '', '', 0),
(10580, 'ptBR', 'Cadê o gnomo que estava aqui?', 'Investigue a área sul da Serra dos Espigões nas Montanhas da Lâmina Afiada para encontrar algum indício do paradeiro de Tocha e dos outros gnomos.', 'Apesar do bem que fizemos aqui, sinto-me mal por ter afugentado Tocha e seus amigos gnomos.$B$BNão tivemos escolha. Eles estavam atrapalhando a nossa operação no bosque com todas aquelas experiências e tecnologia.$B$BFicaria grato se pudesse averiguar o que aconteceu com eles. A última informação que tenho é que foram para o leste e cruzaram a ponte. Tenho certeza de que devem ter ido para o sul, para longe da Cidadela do Senhor do Trovão.$B$BProcure por algum indício do paradeiro deles no sul da Serra dos Espigões.', '', '', '', '', '', '', '', '', '', '', 0),
(10581, 'ptBR', 'Siga as migalhas de pão', 'Siga a trilha de peças na ladeira para o Espinhaço Cortante. Fale com Tocha na Estação do Tocha, nas Montanhas da Lâmina Afiada.', 'MUITO BEM! JÁ AVISEI QUE NÃO ENCONTRARÁ NADA NA SERRA.$B$BNÃO SIGA A TRILHA DE PEÇAS QUE LEVA PARA A ESTAÇÃO DO TOCHA! VOCÊ NÃO ENCONTRARÁ TOCHA E NENHUM OUTRO GNOMO LÁ.', '', '', '', '', '', '', '', '', '', '', 0),
(10582, 'ptBR', 'Lacaios do Concílio das Sombras', 'Ewan Asalouca, o Arrojado, na Torre da Forja da Morte, quer que você mate 10 Guardiões da Forja da Morte e 5 Evocadores da Forja da Morte.', '<Ewan escuta atento à sua narrativa dos eventos da Cidadela da Legião.>$B$BIsso explica muitas das coisas que observamos. Tivemos relances deles disparando infernais na direção da Cidadela, mas não descobrimos muito mais.$B$BO Concílio das Sombras lacrou a Forja da Morte melhor do que um barril novo de cervaforte. Primeiro, você terá que rachar alguns crânios para poder entrar lá e fuçar. Comece eliminando os lacaios do Concílio das Sombras que guardam a entrada da Forja da Morte!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ewan Asalouca, o Arrojado, na Torre da Forja da Morte, que fica no Vale da Lua Negra.', 0),
(10583, 'ptBR', 'O destino de Flanis', 'Ewan Asalouca, o Arrojado, na Torre da Forja da Morte, quer que você vasculhe a Forja da Morte em busca de Flanis Celerasa e recupere a Mochila de Flanis.', 'O Comandante de Ala Nuainn originalmente mandou três de nós para cá, para vigiarmos a Forja da Morte e reunirmos informações. Flanis Celerasa se ofereceu para tentar se infiltrar na Forja da Morte, mas não temos notícia nenhuma dele há dias.$B$BTemo o pior, $n. Flanis é um batedor habilidoso, mas, se ele se meteu numa encrenca boa, não há como saber. Vasculhe a Forja da Morte em busca dele, e recupere quaisquer informações ou itens que ele tenha coletado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ewan Asalouca, o Arrojado, na Torre da Forja da Morte, no Vale da Lua Negra.', 0),
(10584, 'ptBR', 'Recuperando os conversores', 'Use o Coletor de Magneto Protovoltaico para coletar 5 Eletromentais.', 'Aqueles ogros burros do Acampamento Giralança ao norte estão saqueando os nossos conversores de energia! Você vai recuperá-los para mim... mais ou menos.$B$BÉ óbvio que os ogros estragaram os conversores com aquelas mãos grandes e desajeitadas. Então eu quero que você libere a energia dos conversores e depois use este coletor de magneto protovoltaico no eletromental resultante para aprisioná-lo.$B$BEle provavelmente ficará irritado, então você vai precisar "matá-lo" enquanto ele ainda está preso na esfera de magneto.', '', 'Eletromentais coletados', '', '', '', '', '', '', '', 'Fale novamente com Tocha na Estação do Tocha, que fica nas Montanhas da Lâmina Afiada.', 0),
(10585, 'ptBR', 'A câmara de evocação', 'Obtenha um Deslocador Elemental com um Ferreiro da Forja da Morte ou um Engenhoqueiro da Forja da Morte. Use o dispositivo para interromper o ritual na câmara de evocação. Apresente-se a Ewan Asalouca, o Arrojado, na Torre da Forja da Morte, depois de completar a missão.', 'Para que o Concílio das Sombras consiga construir infernais tão rápido assim, eles precisam ter uma área dedicada a evocar os elementais corrompidos que servem de almas às criaturas. $B$BA câmara de evocação provavelmente fica no subterrâneo, perto de um poço de água impura ou lava. Encontre a câmara de evocação dentro da Forja da Morte e descubra uma forma de encerrar o ritual de evocação. Os mo\'args envolvidos na construção dos infernais provavelmente carregam ferramentas que poderão ser úteis na destruição da magia dos evocadores.', '', 'Encerrar Ritual de Evocação de Infernais', '', '', '', '', '', '', '', 'Fale novamente com Ewan Asalouca, o Arrojado, na Torre da Forja da Morte, no Vale da Lua Negra.', 0),
(10586, 'ptBR', 'Acabe com o Armipotente!', 'Derrote o Armipotente Razuun, recolha as Ordens de Razuun, e apresente-se ao Comandante de Ala Nuainn na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 'Fizemos muitos avanços contra as operações do Concílio das Sombras na Forja da Morte, mas, se quisermos ser realmente triunfantes, precisamos derrotar o feitor da Legião.$B$BEncontrei uma chave em meio às coisas na mochila do Flanis. Tenho certeza de que será útil para encontrar esse Armipotente Razuun que você observou na Cidadela da Legião.$B$BDepois que você tiver caçado e derrotado o Armipotente Razuun, apresente-se diretamente ao Comandante de Ala Nuainn. Ele vai ficar feliz em saber imediatamente!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Ala Nuainn na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10587, 'ptBR', 'Campo de treinamento Karabor', 'A Exarca Onaala, no Altar de Sha\'tar, quer que você obtenha 8 Glaives Solfúria dos Caçadores de Demônios Suplicantes e Caçadores de Demônios Iniciados nas Ruínas de Karabor, a sudeste do Altar de Sha\'tar.$B$BCumprir missões para os Áugures fará com que a sua reputação entre os Aldor diminua.', 'Nossos batedores relatam um trânsito intenso de recrutas dos elfos sangrentos Solfúria rumo às Ruínas de Karabor. Normalmente, isso representaria apenas uma ameaça militar. Entretanto, acreditamos que haja outra coisa de errado.$B$BAs descrições dos trajes e estilos de luta são estranhamente semelhantes aos do próprio Illidan. Contudo, não pretendo me alarmar sem motivos. Por isso, quero que vás até lá e tragas a mim as armas deles. Assim, determinaremos se meus temores têm ou não fundamento.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Exarca Onaala no Altar de Sha\'tar, que fica no Vale da Lua Negra.', 0),
(10588, 'ptBR', 'A Cifra da Danação', 'Use a Cifra da Danação no Altar da Danação para evocar Cyrukh, o Senhor do Fogo.$B$BDestrua Cyrukh, o Senhor do Fogo, e então fale com o Reparador da Terra Torlok no Altar da Danação.', 'Quantas vezes esse feitiço foi usado na história dos nossos mundos? Sem dúvida, o poder de destruição dele é inigualável.$B$BAgora você precisa levar a cifra, finalmente completa, e lê-la no Altar da Danação, onde se encontra a memória de Gul\'dan.$B$BUma vez pronunciadas as palavras, você verá as memórias que ficaram marcadas na terra. Aguente firme e espere a chegada de Cyrukh.$B$BVocê precisa vencer, $n. Este mundo não aguentará mais uma onda de devastação.', '', '', '', '', '', '', '', '', '', 'Fale com o Reparador da Terra Torlok no Altar da Danação, que fica no Vale da Lua Negra.', 0),
(10589, 'ptBR', 'Obtendo acesso', 'Traga um Controle do Teleportador da Legião ao Comandante de Ala Nuainn na Fortaleza Martelo Feroz, no Vale da Lua Negra. Os Armeiros Mo\'args na Cidadela da Legião costumam carregar os dispositivos.', 'De acordo com as ordens de Razuun, a imensa área de reunião de infernais se chama Ponto de Invasão: Cataclismo, e está aninhada nas montanhas do norte. A única maneira de se chegar lá é usando um teleportador localizado na Cidadela da Legião.$B$BAlguns membros da hoste da Legião portam dispositivos que ativam os teleportadores. Você precisa conseguir um dos dispositivos para ter acesso ao teleportador. Massacre todos os demônios, se for necessário, mas não volte de mãos vazias de jeito nenhum.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Ala Nuainn na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10590, 'ptBR', 'Prove Your Hatred', 'Mehlar Dawnblade at the Bulwark wants you to bring him 20 Minion\'s Scourgestones.', 'It is time you remembered history that should not be forgotten... the slaughter of our people by Arthas and his Scourge army.$b$bVengeance on the Scourge is the only way to ease your pain. It is unfortunate they are not susceptible to fear and pain. Only their utter destruction will bring you even a shred of satisfaction.$b$bSpeak with Argent Officer Garush for knowledge of scourgestones and how to obtain them -- I will need to see many of them as proof of your commitment before we speak again.', '', '', '', '', '', '', '', '', '', 'Return to Mehlar Dawnblade in Tirisfal Glades.', 0),
(10592, 'ptBR', 'Wisdom of the Banshee Queen', 'Bring the Scourgestone Fragments to Lady Sylvanas Windrunner in Undercity.', 'The scourgestones are weak when separated from the skeletal grasp that once held them. Simply holding them in my hands has caused them to fracture and break.$b$b<Mehlar crushes the scourgestones into a pile of rubble.>$b$bTake these fragments to the Banshee Queen, Lady Sylvanas Windrunner, at her throne in Undercity. With her lies the knowledge to turn these remains into a weapon against the Scourge.', '', '', '', '', '', '', '', '', '', '', 0),
(10594, 'ptBR', 'Medindo a frequência de ressonância', 'Coloque os Receptores de Frequências Oscilantes de modo que você seja atingido por 5 campos de Oscilação sobrepostos quando estiver no meio deles.', 'Leve estes receptores para o Platô Harmônico. Basta distribuí-los em um padrão no chão para criar campos sobrepostos e fazer a leitura da amplitude dos cristais. Fique no meio deles de modo que esteja em cinco campos de oscilação e conseguirei a informação de que preciso!$B$BOs receptores funcionarão mesmo com aqueles que outras pessoas deixaram cair.$B$BAh, pode ser que uma fenda se forme! Eu não faço ideia do que vai sair dessa fenda, se é que vai sair algo, mas esteja preparad$Go:a; para o pior.', 'Frequência de ressonância do cristal cantante verificada', '', '', '', '', 'Frequência de ressonância do cristal cantante verificada', '', '', '', 'Fale novamente com Nickwanca, o Metrognomo, na Estação do Tocha, que fica nas Montanhas da Lâmina Afiada.', 0),
(10595, 'ptBR', 'Cercados!', 'O Guarda-de-sangue Gulmok, do lado de fora da Aldeia Lua Negra, quer que você mate 10 Atacantes Infernais.', '<Gulmok olha para o céu.>$B$BNossos batedores estão lutando bravamente, mas os infernais continuam avançando!$B$BOs demônios nos bombardeiam impunes a partir da Cidadela da Legião a sudoeste. Nem mesmo a guarda de elite Kor\'kron conseguirá contê-los para sempre.$B$BEstou convocando cada $r para que faça sua parte na defesa da Aldeia Lua Negra. Não é brincadeira, $c. A sobrevivência da aldeia corre sério risco. Cumpra seu dever com a Horda e junte-se à luta!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-sangue Gulmok na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10596, 'ptBR', 'Contra a Cidadela da Legião', 'Vá até a Cidadela da Legião, encontre o Dispositivo de Comunicação da Legião, e descubra os planos da Legião enquanto estiver $gdisfarçado:disfarçada;. Fale novamente com o Guarda-de-Sangue Gulmok na Aldeia Lua Negra quando a missão estiver cumprida.', 'Seu alvo é a Cidadela da Legião. Não haverá reforços, então um ataque frontal está fora de questão.$B$BO pouco de informação que obtivemos indica que a Legião prepara e estoca os infernais na cidadela. Usando o disfarce que vou lhe dar, você terá que se esgueirar e invadir a Cidadela da Legião para descobrir os planos deles.$B$BTalvez seja melhor você interceptar ou escutar as comunicações entre os comandantes.', '', 'Descubra os Planos da Legião', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-Sangue Gulmok na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10597, 'ptBR', 'Bomba la bomba', 'Obtenha um Núcleo de Força de Aníquilus e uma Placa de Armadura de Aníquilus, e leve-os ao Guarda-de-Sangue Gulmok na Aldeia Lua Negra.', 'Não podemos permitir que a Legião nos pisoteie ao marchar contra o Templo Negro.$B$BEncontre uma maneira de destruir os infernais que pretendem usar contra nós. Não é um pedido, $n; é uma ordem.$B$BDentro do Lago Fétido, próximo à Cidadela da Legião, você encontrará um velho núcleo de força de aníquilus que poderá ser usado como base para uma bomba vil. Vasculhe os outros destroços próximos ao aníquilus em busca de placas blindadas. Acho que você conseguirá fazer uma bomba poderosa o suficiente para destruir os infernais e dar uma bela balançada na cidadela!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-Sangue Gulmok na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10598, 'ptBR', 'Os infernais que se explodam!', 'Use a Bomba Vil em cima do glifo verde na Cidadela da Legião para destruir os infernais, e em seguida apresente-se ao Guarda-de-Sangue Gulmok na Aldeia Lua Negra.', 'O dispositivo que montamos não vai ganhar nenhum concurso de beleza, mas deve ser capaz de destruir os infernais armazenados na Cidadela da Legião. Julgando pelo efeito que o núcleo de força teve no Lago Fétido, deve ter um poder explosivo respeitável.$B$BSe você armar o dispositivo no meio do glifo verde na cidadela, a explosão provavelmente atingirá todos os infernais.', '', 'Destrua os Infernais da Cidadela da Legião', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-Sangue Gulmok na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10599, 'ptBR', 'A Forja da Morte', 'Apresente-se ao Batedor Zagran no Mirante da Escória.', 'Eu analisei seus relatórios enquanto você estava dando um jeito nos infernais na Cidadela da Legião. Não temos motivo para duvidar do que a Legião disse sobre a Forja da Morte. Eles realmente estão produzindo infernais lá, por isso despachei um grupo de batedores para ficar de olho na área.$B$BSe não destruirmos a Forja da Morte, eles vão reconstruir o estoque de infernais que você destruiu na Cidadela da Legião.$B$BApresente-se ao batedor Zagran no topo do Mirante da Escória, acima da Forja da Morte, a sudeste daqui.', '', '', '', '', '', '', '', '', '', '', 0),
(10600, 'ptBR', 'Lacaios do Concílio das Sombras', 'O Batedor Zagran no Mirante da Escória quer que você mate 10 Guardiões da Forja da Morte e 5 Evocadores da Forja da Morte.', '<Zagran ouve sua narrativa dos eventos da Cidadela da Legião.>$B$BIsso completa as coisas que vimos. Tivemos relances deles disparando infernais na direção da Cidadela, mas não descobrimos muito mais.$B$BO Concílio das Sombras montou uma segurança impenetrável na forja. Parece que você terá que abrir caminho no braço. Comece eliminando os lacaios do Concílio das Sombras que guardam a entrada da Forja da Morte!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Batedor Zagran no Mirante da Escória, que fica no Vale da Lua Negra.', 0),
(10601, 'ptBR', 'O destino de Hagrosh', 'O Batedor Zagran no Mirante da Escória quer que você vasculhe a Forja da Morte em busca de Hagrosh e recupere a Mochila de Hagrosh.', 'O grupo de batedores originalmente tinha três participantes. Infelizmente, Hagrosh decidiu virar herói.$B$BEle desceu até a Forja da Morte e não tivemos mais notícias dele desde então.$B$BMuito provavelmente, o idiota conseguiu ser morto. Os membros do Concílio das Sombras não são idiotas, e Hagrosh não era lá muito bom nessa coisa de sutileza, se é que você me entende. Procure por ele na Forja da Morte, e recupere quaisquer informações ou itens que ele tenha coletado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Batedor Zagran no Mirante da Escória, que fica no Vale da Lua Negra.', 0),
(10602, 'ptBR', 'A câmara de evocação', 'Obtenha um Deslocador Elemental com um Ferreiro da Forja da Morte ou um Engenhoqueiro da Forja da Morte e use o dispositivo para interromper o ritual na câmara de evocação. Apresente-se ao Batedor Zagran no Mirante da Escória quando tiver cumprindo a missão.', 'Para cuspir infernais tão rápido assim, eles precisam de uma área dedicada à evocação dos elementais que formam o núcleo dos infernais.$B$BA câmara de evocação provavelmente está no subsolo, perto de um poço de lava ou de água corrompida. Encontre a câmara de evocação dentro da Forja da Morte e descubra uma forma de encerrar o ritual de evocação. Os mo\'args envolvidos na construção dos infernais provavelmente carregam ferramentas que poderão ser úteis na destruição da magia dos evocadores.', '', 'Encerrar Ritual de Evocação de Infernais', '', '', '', '', '', '', '', 'Fale novamente com o Batedor Zagran no Mirante da Escória, que fica no Vale da Lua Negra.', 0),
(10603, 'ptBR', 'Acabe com o Armipotente!', 'Derrote o Armipotente Razuun, recolha as Ordens de Razuun, e apresente-se ao Guarda-de-Sangue Gulmok na Aldeia Lua Negra.', 'Fizemos muitos avanços contra as operações do Concílio das Sombras aqui na Forja da Morte, mas chegou a hora de completar o serviço.$B$BAchei uma chave na mochila do Hagrosh. Pelo menos ele prestou para alguma coisa antes de ser pego.$B$BA chave $Go:a; ajudará a encontrar esse Armipotente Razuun que você observou na Cidadela da Legião.$B$BDepois que você tiver caçado e acabado com o Armipotente Razuun, apresente-se diretamente ao Guarda-de-Sangue Gulmok. Não podemos deixar ele esperando.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-Sangue Gulmok na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10604, 'ptBR', 'Obtendo acesso', 'Leve um Controle do Teleportador da Legião para o Guarda-de-sangue Gulmok na Aldeia Lua Negra, que fica no Vale da Lua Negra. Os Armeiros Mo\'args na Cidadela da Legião costumam carregar os dispositivos.', 'De acordo com as ordens de Razuun, a imensa área de reunião de infernais se chama Ponto de Invasão: Cataclismo, e fica nas montanhas detrás da nossa aldeia! A única maneira de chegar lá é usando um teleportador localizado na Cidadela da Legião.$B$BAlguns lacaios da Legião carregam dispositivos que lhes permitem usar os teleportadores. Você precisa capturar um dos dispositivos para ganhar acesso ao teleportador. Massacre todos os demônios, se for necessário, mas não volte de mãos vazias de jeito nenhum. Não perca tempo, o inimigo está perto demais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-sangue Gulmok na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10606, 'ptBR', 'A Arte da Manutenção de Aníquilus', 'Mate o Doutor Gutrick e obtenha a Chave do Doutor. Use a chave para abrir o Cofre do Doutor e pegar A Arte da Manutenção de Aníquilus, e entregue o livro a Pléxis no Ponto de Invasão: Cataclismo.', 'A melhor maneira de destruir o resto dos suprimentos da Legião é usar as próprias armas deles contra eles. Andei trabalhando num aparelho para controlar uma daquelas Sentinelas Aníquilus lá embaixo.$B$BMas tem duas coisinhas que eu preciso resolver primeiro. Para tanto, vou precisar do manual que o Doutor Gutrick guarda trancado num baú no final da rampa. Ele provavelmente não vai entregar a chave sem luta, então você terá que capturá-la. Traga o manual de aníquilus para mim, e eu farei o resto!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pléxis no Ponto de Invasão: Cataclismo no Vale da Lua Negra.', 0),
(10607, 'ptBR', 'Sussurros do deus Corvo', 'Mate os arakkoas Grishna para obter a Compreensão da Fala do Corvo por 2 minutos. Enquanto estiver sob os efeitos do feitiço, você poderá encontrar e receber a profecia dos quatro santuários.', 'Os Oráculos do Corvo deixaram totens em Grishnath para que os arakkoas pudessem ouvir a Palavra do Corvo. Infelizmente, não conseguimos decifrar a língua dos arakkoas.$b$bPoderemos entendê-la usando o pingente do Emissário. Você poderá controlar as almas dos arakkoas para compreender a língua deles. Enquanto estiver com o espírito arakkoa, visite os totens e ouça a mensagem.$b$bDescubra o que puder para nós, $n.', '', 'Primeira Profecia Recebida', 'Segunda Profecia Recebida', 'Terceira Profecia Recebida', 'Quarta Profecia Recebida', '', '', '', '', 'Fale novamente com Timeon no Arvoredo Eterno, que fica nas Montanhas da Lâmina Afiada.', 0),
(10608, 'ptBR', 'Claro como cristal', 'Mate 10 Esfola-pedras de Cristal.', 'Os malditos esfola-pedras estão atrapalhando minha pesquisa no Platô Harmônico! As escavações deles atrapalham as minhas chances de estudar a harmonia dos cristais cantantes.$B$BVocê parece ser capaz de me ajudar. Siga para o sul e elimine os esfola-pedras.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nickwanca, o Metrognomo, na Estação do Tocha, que fica nas Montanhas da Lâmina Afiada.', 0),
(10609, 'ptBR', 'Quem nasceu primeiro? O ovo ou o draco?', 'Colete 3 Essências de Protodraco Etéreo, 3 Essências de Draco Jovem e 3 Essências de Draco Adulto.', 'Estou pesquisando o uso de essências de draco para o meu trabalho como médico. Acho que isso pode ser uma panaceia para um monte de doenças!$B$BPreciso que alguém vá ao sul, no Platô Harmônico, e arranje um pouco para mim.$B$BEstá $g disposto:disposta; a levar o modulador de fase temporal, e usar nos dragonetes etéreos que saem dos ovos de dracos etéreos? Colete as essências da coisa qualquer em que eles se transformarem.$B$BFalo logo que não tenho certeza do que será essa coisa, porque se trata de uma tecnologia arriscada de modificação de tempo e espaço.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fizit "Doc" Tique-taque na Estação do Tocha, nas Montanhas da Lâmina Afiada.', 0),
(10611, 'ptBR', 'A Arte da Manutenção de Aníquilus', 'Mate o Doutor Maleficus e obtenha a Chave do Doutor. Use a chave para abrir o Cofre do Doutor e pegar A Arte da Manutenção de Aníquilus Vis, e entregue o livro a Nakansi no Ponto de Invasão: Cataclismo.', 'A melhor maneira de destruir o resto dos suprimentos da Legião é usar as próprias armas deles contra eles. Andei trabalhando num aparelho para controlar um daqueles Sentinelas Aníquilus lá embaixo.$B$BMas tem duas coisinhas que eu preciso resolver primeiro. Vou precisar do manual que o Doutor Maleficus guardou trancado num baú lá no final da rampa. Ele provavelmente não vai entregar a chave sem lutar, então você vai ter que pegar na marra. Me traz o manual de aníquilus e eu resolvo o lance.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nakansi no Ponto de Invasão: Cataclismo no Vale da Lua Negra.', 0),
(10612, 'ptBR', 'Vil-oses e Furiosos', 'Use o Console de Controle de Aníquilus para controlar um Sentinela Aníquilus. Destrua 60 Infernais Forjados na Morte antes que o seu aníquilus pife. Quando a missão estiver completa, apresente-se a Pléxis no Ponto de Invasão: Cataclismo.', '<Pléxis folheia o manual.>$B$BBem, aqui tem tudo que a gente precisa, mas só tem um probleminha. Os Aníquilus não são construídos para serem controlados remotamente.$B$BPosso modificar um para que você use por um tempinho, mas você terá que trabalhar rápido, ou sabe-se lá o que vai acontecer! Não ficarei surpreso se a sua brincadeirinha com o aníquilus também chamar a atenção dos capangas da Legião. Fique de olhos abertos e, aconteça o que acontecer, não se esqueça de destruir o máximo que puder!', '', 'Infernal Forjado na Morte destruído', '', '', '', '', '', '', '', 'Fale novamente com Pléxis no Ponto de Invasão: Cataclismo no Vale da Lua Negra.', 0),
(10613, 'ptBR', 'Vil-oses e Furiosos', 'Use o Console de Controle de Aníquilus para controlar uma Sentinela Aníquilus. Destrua 60 Infernais Forjados na Morte antes que o seu aníquilus pife. Quando a missão estiver completa, apresente-se a Nakansi no Ponto de Invasão: Cataclismo.', '<Nakansi folheia o manual.>$B$BTá tudo aqui, mas fica $gligado:ligada;. Essas coisas não foram construídas para serem controladas remotamente.$B$BA gente pode fazer uma gambiarra pra tu mandar ver num deles, mas tu vai ter que trabalhar rápido, senão vai dar xabu! Agora: abre teu olho, porque essa malandragem aí vai deixar os manés da Legião tudo ouriçado. Tenta tomar cuidado, mas lembra que a missão e a segurança da Aldeia Lua Negra vêm primeiro!', '', 'Infernal Forjado na Morte destruído', '', '', '', '', '', '', '', 'Fale novamente com Nakansi no Ponto de Invasão: Cataclismo no Vale da Lua Negra.', 0),
(10614, 'ptBR', 'Sussurros ao vento', 'Fale com Leoroxx na Vila de Mok\'nathal, que fica nas Montanhas da Lâmina Afiada.', 'Corri atrás de boatos sobre os Mok\'nathal por toda Terralém, mas não encontrei nada. Finalmente, podemos ter encontrado o lar deles.$B$BNo entanto, agora que o momento chegou, estou bastante apreensivo. Isto me tirou completamente o sono durante a minha busca. Será que me aceitarão?$b$bEu... sei o nome do líder deles: Leoroxx. Encontre-o. Quero que você seja os meus olhos.', '', '', '', '', '', '', '', '', '', '', 0),
(10615, 'ptBR', 'Bosque Ruuan', 'Fale com Timeon no Arvoredo Eterno, que fica no Bosque Ruuan, nas Montanhas da Lâmina Afiada.', 'As informações que você me ajudou a descobrir sobre a natureza dos arakkoas são de grande interesse para um outro grupo.$b$bRecebemos uma visita de um membro da Expedição Cenariana, que também está preocupado com as intenções dos arakkoas nas Montanhas da Lâmina Afiada.$b$bVocê deveria procurá-lo. O nome dele é Timeon. Ele fica no Arvoredo Eterno, no Bosque Ruuan. Siga a estrada para oeste e depois para o norte quando chegar à bifurcação no Espinhaço Cortante. Por fim, prossiga para o oeste até que a estrada se divida na Ravina das Lâminas.', '', '', '', '', '', '', '', '', '', '', 0),
(10617, 'ptBR', 'Casulo de sedasa', 'Colete 8 Casulos de Sedasa de Larvas de Sedasas.$b$bMate a larva rapidamente, ou ela se transformará em sedasa e arruinará o casulo.', 'Nós usamos a seda dos casulos de sedasa para tudo na vila. Nunca conseguimos o bastante e nunca temos o bastante.$b$bÉ difícil colher os casulos da lava depois que começam o processo de metamorfose.$b$bOs guerreiros estão ocupados com o ataque na vila. Ajudaria muito se pudesse recolher alguns.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Taerek na Vila de Mok\'nathal, que fica nas Montanhas da Lâmina Afiada.', 0),
(10618, 'ptBR', 'As asas mais finas', 'Colete 12 Asas Iridescentes.', 'Caçar larvas de sedasa é um desafio difícil para nossos jovens guerreiros. Por sorte, mesmo quando eles não conseguem colher os casulos é possível usar as asas de sedasas adultas.$B$BNa verdade, temos mais usos para as asas que para os casulos, e estamos sempre precisando de mais.$B$BJá que você vai andar caçando por aí, por que não nos traz algumas asas? Isso nos ajudaria muito.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Silmara na Vila de Mok\'nathal, que fica nas Montanhas da Lâmina Afiada.', 0),
(10619, 'ptBR', 'A tribo dos Grislíngua', 'O Vindicante Aluumen quer que você vá até as Ruínas de Baa\'ri e mate 3 Tratadores Grislíngua, 6 Guerreiros Grislíngua e 4 Xamãs Grislíngua.$B$BCompletar missões para os Aldor reduzirá sua reputação junto aos Áugures.', 'A tribo dos Grislíngua é temida por todos os Degradados. É composta pelos indivíduos mais malignos e sanguinários, escolhidos a dedo pelo próprio Akama. São tão ferozes e implacáveis quanto qualquer naga, demônio ou elfo sangrento do exército de Illidan, e foram postados em grandes quantidades nas Ruínas de Baa\'ri, a sudoeste daqui. Vai lá e reduze o número de tropas antes que eles tenham a chance de nos atacar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Vindicante Aluumen no Altar de Sha\'tar, que fica no Vale da Lua Negra.', 0),
(10620, 'ptBR', 'Ameaça Costasserra', 'Mate 10 Espreitadores Costasserra.', 'Fomos contratados para ajudar Tocha com a sua mudança para Terralém e estamos trabalhando nisso desde então.$B$BAcho que finalmente nós nos fixamos. Todos os cientistas malucos estão com projetos em andamento e nós, os Cavalentes, estamos aqui para protegê-los.$B$BAgora precisamos que você vá para o Espinhaço Cortante, ao norte, ou para o Planalto Escamasa, ao leste, e os ajude matando os espreitadores. São aranhas sorrateiras que vivem dentre afloramentos rochosos e pulam nas pessoas distraídas que passam por lá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dina Tonta na Estação do Tocha, nas Montanhas da Lâmina Afiada.', 0),
(10621, 'ptBR', 'Estilhaço da Ruína dos Illidari', 'Leve o Estilhaço Ruína dos Illidari a Ordinn Punhostrondo na Fortaleza Martelo Feroz.', 'O estilhaço parece ser parte de uma arma maior. Runas angulosas gravadas no metal brilham ameaçadoramente.$B$BO propósito original da arma não lhe é evidente, mas é difícil de ignorar. A maioria dos mo\'args da Cidadela da Legião parece estar trabalhando com fragmentos do mesmo metal que você segura. Talvez um dos armeiros da Fortaleza Martelo Feroz possa lhe dizer mais sobre ele.', '', '', '', '', '', '', '', '', '', '', 0),
(10622, 'ptBR', 'Prova de fidelidade', 'Mate Zandras na Jaula do Carcereiro, no Vale da Lua Negra, e fale novamente com Sanoru.', 'Akama acompanhou seu progresso com muita atenção, $n.$B$BOs Grislíngua que você matou nas Ruínas de Baa\'ri estavam dentre os Degradados mais malignos que conhecíamos... cuidadosamente selecionados pelo próprio Akama para manter a farsa e enganar Illidan. Os Devotos da Morte, entretanto, conhecem as reais intenções de Akama.$B$BMas vamos começar do princípio. Precisamos ter certeza de que você não está com Illidan. Um sátiro chamado Zandras vigia a Jaula do alto das muralhas da prisão em nome de Illidan. Mate-o como prova de sua lealdade.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Sanoru, na Jaula do Carcereiro, que fica no Vale da Lua Negra.', 0),
(10623, 'ptBR', 'Estilhaço da Ruína dos Illidari', 'Leve o Estilhaço Ruína dos Illidari a Grokom Olho da Morte na Aldeia Lua Negra.', 'O estilhaço parece ser parte de uma arma maior. Runas angulosas gravadas no metal brilham ameaçadoramente.$B$BO propósito original da arma não lhe é evidente, mas é difícil de ignorar. A maioria dos mo\'args da Cidadela da Legião parece estar trabalhando com fragmentos do mesmo metal que você segura. Talvez um dos ferreiros da Aldeia Lua Negra possa lhe dizer mais sobre o estilhaço.', '', '', '', '', '', '', '', '', '', '', 0),
(10624, 'ptBR', 'Uma história assombrada', 'A Boticária-chefe Hildagard da Aldeia Lua Negra, que fica no Vale da Lua Negra, quer que você traga 15 amostras de Cinzas Sempre Ardentes.', 'Sentiu o calafrio? Talvez você tenha achado que era a mão de alguém no seu ombro. Não foi uma ilusão, $r. Esta terra é assombrada. Há fantasmas por todos os lados, presos aqui para sempre.$B$BVocê gostaria de vê-los? Tem certeza, $n? Essas coisas costumam mudar as pessoas; e nunca para melhor.$B$BMuito bem, preciso que você colete as cinzas sempre ardentes que ficam perto de qualquer um dos poços de lava vil em Lua Negra ocidental. Em qualquer lugar perto da lava verde...', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Boticária-chefe Hildagard na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10625, 'ptBR', 'Espectróculos', 'A Boticária-chefe Hildagard da Aldeia Lua Negra, que fica no Vale da Lua Negra, quer que você mate 12 Zelotes Lua Negra.', 'Eu os batizei de "Espectróculos". Muito bom, não? Assim que você põe os óculos, consegue ver os espíritos do Vale da Lua Negra.$B$BMas antes de entregá-los a você, porém, quero que prometa que vai nos ajudar a eliminar os fantasmas da aldeia.$B$BLeve os óculos e destrua quaisquer espíritos que encontrar vagando pela Aldeia Lua Negra. Vamos torcer para que a destruição desses espíritos force os remanescentes a se mudar para outro lugar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Boticária-chefe Hildagard na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10626, 'ptBR', 'Capture as armas', 'Ordinn Punhostrondo na Fortaleza Martelo Feroz quer que você lhe traga o Glaive de Mazakradon e o Glaive de Morgroron.', 'Com um suprimento maior do material, talvez a gente consiga forjar uma arma para você usar.$B$BOs dois lordes abissais na Cidadela da Legião, Makazradon e Morgroron, já foram equipados com as armas antidemônio. Não temos como saber quantas outras dessas armas a Legião pretende produzir, mas se pudermos capturar os protótipos, deverá ser o suficiente para o nosso projeto.$B$B<Ordinn sorri.>$B$BÉ muito bom usar as próprias "armas secretas" da Legião contra eles mesmos, não acha?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ordinn Punhostrondo na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10627, 'ptBR', 'Capture as armas', 'Grokom Olho da Morte, na Aldeia Lua Negra, quer que você lhe traga a Glaive de Mazakradon e a Glaive de Morgroron.', 'Com um suprimento maior do material, eu poderei forjar uma arma adequada a você.$B$BOs dois lordes abissais na Cidadela da Legião, Makazradon e Morgroron, já estão equipados com as armas antidemônio. Se você capturar as duas armas, teremos matéria-prima suficiente para fazer uma arma e mais uma sobra.$B$BMal posso esperar para destroçar o inimigo usando essas armas. Isso ensinará a Legião a não se meter com magia antidemoníaca.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Grokom Olho da Morte na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10628, 'ptBR', 'Akama', 'Fale com Akama dentro da câmara oculta na Jaula do Carcereiro.', 'Você provou de que lado está. Vou lhe revelar o esconderijo do nosso líder.$B$BSiga os corredores adiante; há uma passagem subterrânea oculta por água estagnada à direita.$B$BAgora, um aviso sério, $n. Não fale com ninguém sobre o que você encontrar lá.', '', '', '', '', '', '', '', '', '', '', 0),
(10629, 'ptBR', 'Trabalho sujo', 'Use o Apito de Canisvil para evocar um Canisvil de Guarda. Leve o Canisvil de Guarda para um passeio e mate alguns Javiltuscos Dementes. Procure as Chaves do Retalhador nos "montinhos" que o Canisvil de Guarda deixar. Devolva as Chaves do Retalhador ao Capataz Razelcraz, na mina a noroeste de Thrallmar.', 'Eu finalmente consertei o retalhador, mas acho que perdi as chaves. Tenho uma matilha de canisvis para proteger o acampamento. Eles não fazem um trabalho muito bom e gostam de me morder. E também gostam de objetos brilhantes. Acho que um dos canisvis comeu minha chave. Eu posso te pagar, se você for passear com ele. Mate alguns javiltusco e deixe ele comer à vontade. Aí ele vai lá e, hum, manda ver... Quando ele terminar, dá pra você procurar as chaves nos "montinhos" que ele deixar?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capataz Razelcraz na Mina de Thrallmar, que fica na Península Fogo do Inferno.', 0),
(10630, 'ptBR', 'Embaixo de Thrallmar', 'Mate Urga\'zz e fale novamente com o Capataz Razelcraz na mina a noroeste de Thrallmar.', 'Estou quase de volta aos negócios. O problema são esses gan\'args na mina. Não dá pra mandar os peões lá pra baixo. E mesmo quando eu consertar o retalhador, não vou querer estragar ele em combate... Os gan\'args têm um líder lá embaixo. Se você matá-lo, talvez os gan\'args vão embora daqui. Daí dava pra eu descolar um trocado e sair daqui chispando.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capataz Razelcraz na Mina de Thrallmar, que fica na Península Fogo do Inferno.', 0),
(10632, 'ptBR', 'Chega de moleza', 'Colete 5 Dentes Extra-afiados de Gorjadaga.', 'É bom saber que você está ajudando o Tocha e os cientistas dele, mas não me dou ao luxo de satisfazer os meus desejos "pessoais".$B$BSe quiser fazer a diferença, faça o que eu lhe pedir, e agora estou pedindo armas.$B$BNossos fuzis e pistolas são eficientes a longo alcance, mas precisamos de armas poderosas de combate corpo-a-corpo para quando os bichos chegam perto.$B$BOs dentes dos batecauda gorjadaga na região norte do Espinhaço Cortante servem para fazer excelentes vibrolâminas. Me arranje alguns.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Razak Ladoférreo na Estação do Tocha, nas Montanhas da Lâmina Afiada.', 0),
(10633, 'ptBR', 'Teron Sanguinávido: fatos e lendas', 'A Boticária-chefe Hildagard da Aldeia Lua Negra, no Vale da Lua Negra, quer que você encontre o Antigo Espírito de Lua Negra.$B$BSe você perder o Espectróculos, Hildagard pode fazer um novo par.', 'Há incontáveis histórias sobre a vida de Teron Sanguinávido, mas a maioria não passa disso – de histórias. Não sabemos o que aconteceu a Sanguinávido depois que retornou a Draenor.$B$BA única coisa que sabemos com certeza é que ele já morreu uma vez.$B$BOuvi os batedores falando de um espírito orc ancião que reside no Altar das Sombras, longe a sudeste, passando pelos Campos da Asa Etérea e atravessando a Trilha da Asa Etérea. Pegue os Espectróculos e rastreie o orc. Ele certamente saberá mais sobre Sanguinávido.', '', '', '', '', '', '', '', '', '', '', 0),
(10634, 'ptBR', 'Vaticínio: a armadura do Sanguinávido', 'O Antigo Espírito de Lua Negra no Altar das Sombras, que fica no sudeste do Vale da Lua Negra, quer que você recupere a Armadura do Sanguinávido.', 'Quando ainda vivia, Sanguinávido era um monstro. Após a morte, ele se tornou um terror incontrolável.$B$BA sudeste daqui você encontrará a Plataforma da Asa Etérea. O que um dia já foi parte das terras de Lua Negra agora é uma ilha flutuante no céu.$B$BEsse lugar já foi o lar de Vhel\'kar, filho de Asa da Morte. Hoje é o seu túmulo. Vhel\'kar sobrevoa a ilha sem descanso, remoendo eternamente a derrota que sofreu nas mãos de Sanguinávido.$B$BDerrote Vhel\'kar se quiser recuperar a armadura de Sanguinávido.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Antigo Espírito de Lua Negra no Altar das Sombras, que fica no sudeste do Vale da Lua Negra.', 0),
(10635, 'ptBR', 'Vaticínio: o manto do Sanguinávido', 'O Antigo Espírito de Lua Negra no Altar das Sombras, que fica no sudeste do Vale da Lua Negra, quer que você recupere o Manto do Sanguinávido.', 'Muitos atos cruéis ele cometeu, mas nenhum tão frio quanto o massacre dos clérigos de Karabor.$B$BDepois que a Horda de Gul\'dan derrotou os draeneis em Karabor, os clérigos sobreviventes foram retirados. Disseram-lhes que seriam levados à Cidadela Fogo do Inferno como prisioneiros de guerra.$B$BSanguinávido, que ainda nem era um cavaleiro da morte, assassinou todos a sangue frio. Eles agora vagueiam diante do Templo Negro com vingança no coração.$B$BO manto de Sanguinávido está com os clérigos de Karabor.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Antigo Espírito de Lua Negra no Altar das Sombras, que fica no sudeste do Vale da Lua Negra.', 0),
(10636, 'ptBR', 'Vaticínio: o bastão do Sanguinávido', 'O Antigo Espírito de Lua Negra no Altar das Sombras, que fica no sudeste do Vale da Lua Negra, quer que você recupere o Bastão do Sanguinávido.', 'Eles se ajoelharam um a um diante do líder, oferecendo as próprias vidas como demonstração de fidelidade. Sanguinávido ergueu a foice e decepou-lhes as cabeças. Logo após o massacre, Sanguinávido tomou a própria vida.$B$BMas não foi um ato de contrição! Não, Sanguinávido buscava a imortalidade! Dos cadáveres dos cavaleiros da morte tombados se ergueram os Cavaleiros Fantasmas de Karabor.$B$BAgora cavalgam pelas estradas que circundam a Mão de Gul\'dan, esperando o dia do retorno do mestre. São eles os portadores do bastão do Sanguinávido. Recupere-o...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Antigo Espírito de Lua Negra no Altar das Sombras, que fica no sudeste do Vale da Lua Negra.', 0),
(10637, 'ptBR', 'Uma distração necessária', 'A Exarca Onaala quer que você volte às Ruínas de Karabor e descubra uma forma de libertar Azaloth, voltando-o contra seus captores.$B$BCompletar missões para os Aldor reduzirá sua reputação junto aos Áugures.', 'Como eu temia, as armas são autênticas. Illidan está treinando caçadores de demônios nas Ruínas de Karabor, e precisamos acabar com isso.$B$BNão te iludas com o nome "caçadores de demônios", $n. O poder deles será empregado contra nós também.$B$BOs bruxos evocam e subjugam demônios que são usados no treinamento dos iniciados. Um lorde abissal chamado Azaloth demostrou ser poderoso demais para ser usado no treinamento, e foi aprisionado em um feitiço de banimento. Descobre uma maneira de libertá-lo de seus captores. Assim ganharemos o tempo de que precisamos.', '', 'Azaloth liberto', '', '', '', '', '', '', '', 'Fale novamente com a Exarca Onaala no Altar de Sha\'tar, que fica no Vale da Lua Negra.', 0),
(10639, 'ptBR', 'Teron Sanguinávido eu sou...', 'O Antigo Espírito de Lua Negra usou você como um fantoche! Agora que você coletou os itens exigidos, ele revelou que é o próprio Teron Sanguinávido. Para se livrar da possessão, você terá de obedecê-lo e assassinar Karsius, o Antigo Vigia.$B$BSe tiver sucesso, fale com a Boticária-chefe Hildagard na Aldeia Lua Negra.', 'Com as posses de Sanguinávido recuperadas, falta apenas uma peça neste quebra-cabeças: um hospedeiro.$B$B<Os lábios do Antigo Espírito de Lua Negra se contorcem num sorriso maldoso.>$B$BCertamente você não acreditou nesse conto de fadas que lhe contei. O Altar das Sombras é a minha prisão. Sem sua ajuda, eu teria ficado preso aqui por toda a eternidade. Agora eu possuirei seu corpo e você destruirá meus captores, quebrando enfim estes grilhões. Se você recusar, ficaremos os dois aqui, presos para sempre.$B$BTeron Sanguinávido se libertará!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Boticária-chefe Hildagard na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10640, 'ptBR', 'Altruis', 'Vá até Nagrand ocidental e encontre Altruis, o Sofredor.$B$BCompletar missões para os Aldor reduzirá sua reputação com os Áugures.', 'Nos dias de hoje, é raro ouvir falar em alguém que siga o caminho do caçador de demônios. Mais raro ainda é descobrir que alguém o faz e não é fiel a Illidan.$B$BHá rumores de tal indivíduo aqui em Terralém, alguém cujo nome é mais temido nos campos da Legião em Nagrand do que qualquer exército de vindicantes Aldor: Altruis.$B$BVai para Nagrand Ocidental e encontra-o. Talvez ele se disponha a nos ajudar a compreender melhor o novo campo de treinamento de caçadores de demônios.', '', '', '', '', '', '', '', '', '', '', 0),
(10641, 'ptBR', 'Contra a Legião', 'Altruis, o Sofredor, quer que você obtenha Sangue Recém-extraído de uma Sacerdotisa da Ira na Base-forja: Geena em Eternévoa. Derrame-o no chão e mate o Avatar de Sathal. Fale novamente com Altruis quando concluir a tarefa.', 'A Legião Ardente já demonstrou inúmeras vezes a própria capacidade de corromper almas mortais. Para que eu possa lhe confiar o conhecimento que você busca, preciso de provas da sua lealdade.$B$BA demonesa conhecida como Sathal já se esquiva de mim há muito, pois ela possui um forma incorpórea.$B$BSathal vigia as sacerdotisas enquanto elas labutam na Base-forja: Geena. Mate uma das lacaias dela e derrame o sangue no solo. A afronta provocará a materialização temporária de Sathal. Mate-a enquanto for possível fazê-lo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Altruis, o Sofredor, em Nagrand.', 0),
(10642, 'ptBR', 'Um fantasma na máquina', 'Zorus, o Judicante, na Fortaleza Martelo Feroz, no Vale da Lua Negra, quer que você lhe traga 15 amostras de Cinzas Sempre Ardentes.', 'Temo que os anões não compreendam a natureza da terra em que ergueram suas construções. Esta região já foi a terra ancestral dos orcs Lua Negra. É de espíritos que estou falando, $r.$B$BHá quase vinte anos eles jazem dormentes sob a Fortaleza Martelo Feroz, mas recentemente alguma coisa os perturbou.$B$BAventura-te além dos portões de Martelo Feroz e busca os poços e rios de lava vil espalhados por estas plagas. Próximo à lava, encontrarás cinzas sempre ardentes. Quero que me tragas as cinzas, para que eu crie algo que nos ajudará.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zorus, o Judicante, na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10643, 'ptBR', 'Precursores de Lua Negra', 'Zorus, o Judicante, na Fortaleza Martelo Feroz, que fica no Vale da Lua Negra, quer que você mate 12 Precursores Lua Negra.', 'Que todos saibam que Zorus tem, sim, um senso de humor.$B$BAgora chega de conversa fiada. Veste os Espectróculos para que possas ver os espíritos de orcs Lua Negra que vagueiam por esta fortaleza. Não te assustes, pois somos nós os verdadeiros invasores aqui. Lamentavelmente, os espíritos precisam ser destruídos, pois o tempo deles já passou há muito.$B$BDestrói os precursores de Lua Negra que infestam a Fortaleza Martelo Feroz e vem falar comigo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zorus, o Judicante, na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10644, 'ptBR', 'Teron Sanguinávido: fatos e lendas', 'Zorus, o Judicante, na Fortaleza Martelo Feroz, no Vale da Lua Negra, quer que você encontre o Antigo Espírito de Lua Negra.$B$BSe você perder os Espectróculos, Zorus pode fazer um novo par.', 'Há incontáveis histórias sobre a vida de Teron Sanguinávido, mas a maioria não passa disso, de histórias. Não sabemos o que aconteceu a Sanguinávido depois que retornou a Draenor.$B$BA única coisa da qual temos certeza é que ele já morreu uma vez.$B$BOuvi os batedores falando de um espírito orc ancião que reside no Altar das Sombras, bem ao leste, passando pelos Campos da Asa Etérea e atravessando a Trilha da Asa Etérea. Pega os Espectróculos e rastreia o orc. Ele certamente saberá mais sobre Sanguinávido.', '', '', '', '', '', '', '', '', '', '', 0),
(10645, 'ptBR', 'Teron Sanguinávido eu sou...', 'O Antigo Espírito de Lua Negra usou você como um fantoche! Agora que você coletou os itens exigidos, ele revelou que é o próprio Teron Sanguinávido. Para se livrar da possessão, você terá de obedecê-lo e assassinar Karsius, o Antigo Vigia.$B$BSe tiver sucesso, fale novamente com Zorus, o Judicante, na Fortaleza Martelo Feroz.', 'Com as posses de Sanguinávido recuperadas, falta uma única peça neste quebra-cabeças: um hospedeiro.$B$B<Os lábios do Antigo Espírito de Lua Negra se contorcem num sorriso maldoso.>$B$BCertamente você não acreditou nesse conto de fadas que lhe contei. O Altar das Sombras é a minha prisão. Sem sua ajuda, eu teria ficado preso aqui por toda eternidade. Agora eu possuirei seu corpo e você destruirá meus captores, quebrando enfim estes grilhões. Se você recusar, ficaremos os dois aqui, presos para sempre.$B$BTeron Sanguinávido se libertará!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zorus, o Judicante, na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10646, 'ptBR', 'Pupilo de Illidan', 'Escute a história de Altruis.', 'Você provou sua lealdade, $n. Perdoe-me pela cautela, mas neste mundo as coisas não são o que aparentam.$B$BAssim que você puder, contarei a você sobre Varedis.', 'Pupilo de Illidan', '', '', '', '', 'Pupilo de Illidan', '', '', '', 'Fale novamente com Altruis, o Sofredor, no Campo-forja: Ódio em Nagrand.', 0),
(10647, 'ptBR', 'Procura-se: Uvuros, flagelo de Lua Negra', 'Mate Uvuros e colete a Juba Flamejante de Uvuros. Entregue-a ao Belarauto Sardon Verocorte na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 'Procura-se - MORTO:$B$BUvuros, flagelo de Lua Negra.$B$BPor ordem do Suserano Or\'barokh, a fera vil Uvuros deve ser morta imediatamente e ter a juba esfolada da carcaça como prova do feito. Traga a juba flamejante da fera para o Belarauto Sardon Verocorte, caso tenha sucesso.$B$BUvuros foi visto pela última vez na Mão de Gul\'dan, que fica no coração do Vale da Lua Negra, a leste da Aldeia Lua Negra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Belarauto Sardon Verocorte na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10648, 'ptBR', 'Procura-se: Uvuros, flagelo de Lua Negra', 'Mate Uvuros e colete a Juba de Fogo de Uvuros. Entregue-a ao Belarauto Napachope na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 'Procura-se - MORTO:$B$BUvuros, flagelo do Vale da Lua Negra.$B$BPor ordem do Thane Yoregar, a fera vil Uvuros deve ser morta imediatamente e ter a juba esfolada da carcaça como prova do feito. Traga a juba flamejante da fera para o Belarauto Napachope, caso você tenha sucesso.$B$BUvuros foi visto pela última vez na Mão de Gul\'dan, que fica no coração do Vale da Lua Negra, a nordeste da Fortaleza Martelo Feroz.', '', '', '', '', '', '', '', '', '', 'Fale com o Belarauto Napachope na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10649, 'ptBR', 'O livro dos nomes abjetos', 'Penetre no Labirinto Soturno em Auchindoun e roube o Livro dos Nomes Abjetos de Nerocordius, o Incitador. Fale novamente com Altruis em Nagrand quando concluir a tarefa.', 'Eu simpatizo com suas intenções de opor-se a Varedis e seus seguidores, mas você não tem chance contra ele. A não ser que você encontre o artefato que lhe concedeu aquele poder.$B$BCorrem boatos de que o Livro dos Nomes Abjetos está em poder de Nerocordius, o Incitador, dentro do Labirinto Soturno em Auchindoun. Obtê-lo é sua única esperança contra Varedis.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Altruis, o Sofredor, no Campo-forja: Ódio em Nagrand.', 0),
(10650, 'ptBR', 'Retorno aos Aldor', 'Fale com a Exarca Onaala no Altar de Sha\'tar, que fica no Vale da Lua Negra.$B$BCompletar missões para os Aldor reduzirá sua reputação com os Áugures.', 'Este livro... Eu poderia usá-lo para aumentar meu poder em dez vezes... Não! Isso acabaria corrompendo a minha alma, tenho certeza. Volte para aqueles que $go:a; mandaram aqui, $n. Agora você tem uma maneira de derrotar Varedis. Espere até que ele manifeste a própria forma demoníaca por metamorfose e, quando isso acontecer, queime o livro diante dele. Essa é a única forma de privá-lo dos poderes.', '', '', '', '', '', '', '', '', '', '', 0),
(10651, 'ptBR', 'Varedis precisa ser detido!', 'A Exarca Onaala quer que você vá até as ruínas de Karabor e mate Alandien, Theras, Netharel e Varedis. Use o Livro dos Nomes Abjetos para enfraquecer Varedis quando ele usar Metamorfose. Fale novamente com a Exarca Onaala após completar a tarefa.$B$BCompletar missões para os Aldor reduzirá sua reputação entre os Áugures.', 'Temos de nos livrar de um artefato tão corrupto, mas não antes de usá-lo para minar os poderes de Varedis.$B$BÉ preciso erradicar permanentemente o campo de treinamento das Ruínas de Karabor, o que significa matar não apenas Varedis, mas também os três mestres elfos noturnos que o auxiliam: Alandien, Theras e Netharel.$B$BReúne um grupo adequado e volta às Ruínas de Karabor. Segue as instruções de Altruis para derrotar Varedis. Para o bem de todos nós, espero que funcione.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Exarca Onaala no Altar de Sha\'tar, que fica no Vale da Lua Negra.', 0),
(10652, 'ptBR', 'Atrás das linhas inimigas', 'Fale com Veronia quando estiver $Gpreparado:preparada; para partir para Manaforja Coruu. Chegando ao destino, fale com Caledis Albafulgis.$B$BCumprir missões para os Áugures fará com que sua reputação entre os Aldor diminua.', 'Foram feitos todos os preparativos para que você chegasse onde nossos espiões estão escondidos. Venha falar comigo quando estiver $Gpronto:pronta; e eu vou $Gencaminhá-lo:encaminhá-la;.', '', '', '', '', '', '', '', '', '', '', 0),
(10653, 'ptBR', 'Marcas de Sargeras', 'Leve 10 Marcas de Sargeras para Adyen, o Guardião da Luz.$B$BCompletar missões para os Aldor reduzirá sua reputação com os Áugures.', 'Já deve estar bem claro para ti porque é que nos opomos à Legião Ardente e àqueles que a servem.$B$BSe desejas provar teu valor para os Aldor, traz-me as insígnias de membros de alta patente da Legião e dos devotos do Concílio das Sombras. Eles podem ser encontrados em Eternévoa e no Vale da Lua Negra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Adyen, o Guardião da Luz, no Terraço dos Aldor em Shattrath.', 0),
(10654, 'ptBR', 'Mais marcas de Sargeras', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Adyen, o Guardião da Luz.', 0),
(10655, 'ptBR', 'Marca única de Sargeras', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Adyen, o Guardião da Luz.', 0),
(10656, 'ptBR', 'Sinetes dos Solfúria', 'A Magistra Fyalenn, em Shattrath, quer que você lhe traga 10 Sinetes dos Solfúria.$B$BCompletar missões para os Áugures reduzirá sua reputação com os Aldor.', 'Como você deve saber, os Áugures e os exércitos de Kael\'thas estão em guerra. Kael nos vê como ameaça a sua influência sobre os outros elfos sangrentos e já tentou nos esmagar várias vezes.$B$BSe você deseja nos ajudar em nossa batalha contra Kael\'thas, existem muitos alvos a escolher. Os soldados de alta patente de Kael\'thas usam sinetes Solfúria para designar suas patentes. Eles se espalham por toda Eternévoa e pelo Vale da Lua Negra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Magistra Fyalenn na Mata Terokkar.', 0),
(10657, 'ptBR', 'Domando o relâmpago', 'Use a Esfera de Magneto Repolarizada para absorver 25 raios das Serpentes Escamasas. Aproveite para coletar 5 Glândulas Relampejantes de Escamasa.', 'Não conseguimos manter a operação do Capacitório de Zefírio dentro do orçamento. Acabei de lembrar que as serpentes do Planalto Escamasa ao leste têm glândulas e uma baforada de relâmpago que podemos aproveitar.$B$BFiz a repolarização do coletor de magneto para absorver raios, e quero que vá lá, ative-o em si $gmesmo:mesma; e consiga um pouco de energia barata daquelas serpentes.', '', 'Raios Absorvidos', '', '', '', '', '', '', '', 'Fale novamente com Tocha na Estação do Tocha, que fica nas Montanhas da Lâmina Afiada.', 0),
(10658, 'ptBR', 'Mais sinetes dos Solfúria', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Magistra Fyalenn na Mata Terokkar.', 0),
(10659, 'ptBR', 'Sinete único dos Solfúria', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Magistra Fyalenn na Mata Terokkar.', 0),
(10660, 'ptBR', 'Que criaturas estranhas...', 'O Pesquisador Tiorus na Aldeia Lua Negra, que fica no Vale da Lua Negra, quer que você traga 8 Timos de Fogovil.', 'Estou interessado em aprender mais sobre os estranhos répteis que vagueiam pelas torrentes de lava do Vale da Lua Negra. Nunca antes vi feras capazes de suportar o calor calcinante de magma derretido!$B$BDo lado de fora da Aldeia Lua Negra, onde o solo se rompeu e a lava flui pelas fendas, você encontrará dimetrodontes fogovil. Mate-os e me traga os timos deles. Com os timos eu poderei iniciar a análise preliminar da resistência ao calor.$B$BComece sua busca pelo sudeste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Pesquisador Tiorus na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10661, 'ptBR', 'Ó-timos!', 'Gnomus na Fortaleza Martelo Feroz, do Vale da Lua Negra, quer que você traga 8 Timos de Fogovil.', 'Você já ouviu falar em uma comida que se cozinha sozinha e fica quente para sempre? Ouse sonhar, eu digo!$B$BMas talvez não seja um sonho, afinal! Fora da fortaleza, perto dos poços e torrentes de lava, há feras que prosperam no calor escaldante. São conhecidos como dimetrodontes fogovil.$B$BOs anões destas bandas me dizem que os tais dimetrodontes têm os timos mais deliciosos do mundo, e que esses timos já vêm praticamente pré-cozidos! Traga-me os timos e eu lhe darei um trocado.$B$BComece sua busca diretamente a leste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gnomus na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10662, 'ptBR', 'O ferreiro eremita', 'Leve a Caixa de Lingotes para David Wayne no Refúgio de Wayne da Mata Terokkar.', '<Ordinn examina o resultado da tentativa de trabalhar o metal balançando a cabeça.>$B$BIsto está além das minhas habilidades, mas não quer dizer que a arma não possa ser recriada para você.$B$BUm ferreiro talentoso chamado David Wayne estava indo com os Filhos de Lothar a Draenor. Era um ferreiro excepcional, mas decidiu abandonar a expedição. Ele está morando num acampamento numa península a leste do Pontal Asardente na Mata Terokkar. Leve os lingotes para ele e veja se pode te ajudar com a arma.', '', '', '', '', '', '', '', '', '', '', 0),
(10663, 'ptBR', 'O ferreiro eremita', 'Leve a Caixa de Lingotes para David Wayne, no Refúgio de Wayne, na Mata Terokkar.', '<O orc balança a cabeça diante do fracasso.>$B$BNão sou bom o suficiente para dar um jeito nisso, mas ainda acredito que a arma pode ser recriada.$B$BÉ muito triste ter que sugerir isso, mas sua única esperança é um ferreiro humano chamado David Wayne. Sim, uma vez ele já fez parte da expedição da Aliança, mas isso foi há muito tempo, e Wayne já abandonou os Filhos de Lothar. Ele está morando num acampamento numa península a leste do Pontal Asardente na Mata Terokkar. Leve os lingotes e veja se ele pode lhe ajudar.', '', '', '', '', '', '', '', '', '', '', 0),
(10664, 'ptBR', 'Material adicional', 'David Wayne, no Refúgio de Wayne, quer que você lhe traga uma Estrutura de Adamantita, 4 pedaços de Couro Nodoso Pesado e um Totem de Repelir Demônios.', 'Os lingotes que você trouxe já contribuem com quase todo o metal de que precisarei para forjar a lâmina da espada, mas necessito de várias outras coisas para criar as outras partes da arma.$B$BDeixe-me ver, vamos precisar de uma estrutura de adamantita, um pouco de couro nodoso pesado e um totem de repelir demônios. Artesãos habilidosos são capazes de produzir os dois primeiros itens, mas o terceiro é vendido apenas pelo mercador de reagentes do Bairro Inferior de Shattrath, Fantei. Você o encontrará com os outros comerciantes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com David Wayne no Refúgio de Wayne, que fica na Mata Terokkar.', 0),
(10665, 'ptBR', 'Fresquinho dos Mecanar', 'David Wayne, no Refúgio de Wayne, quer que você lhe traga uma Manacélula Sobrecarregada.', 'Fundir os lingotes que você trouxe vai exigir muito calor — mais do que uma forja convencional é capaz de suprir.$B$BVou precisar de uma fonte de calor suplementar para a forja, e há poucas coisas em Terralém capazes de fornecer tanta energia.$B$BA área Mecanar da Bastilha da Tormenta produz manacélulas contendo uma quantidade inacreditável de energia. Encontre uma das manacélulas sobrecarregadas nas pilhas ao redor do Mecanolorde Capácitus, e a traga de volta para cá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com David Wayne no Refúgio de Wayne, que fica na Mata Terokkar.', 0),
(10666, 'ptBR', 'O Lexicon Demonica', 'Obtenha o Lexicon Demonica com o Grão-mestre Vorpil e o traga para David Wayne no Refúgio de Wayne.', 'Recriar os encantamentos na lâmina exige que vários feitiços sejam pronunciados em demoníaco.$B$BNão é algo que tenham me ensinado durante meu treinamento como aprendiz, mas não há outro jeito. Existe um livro, chamado Lexicon Demonica, que contém a maior parte das palavras de que preciso, mas está nas mãos de um bruxo poderoso do Concílio das Sombras.$B$BBem fundo nos salões do Labirinto Soturno de Auchindoun, com o Grão-mestre Vorpil. Faça o que for necessário para conseguir o livro, e me traga ele aqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com David Wayne no Refúgio de Wayne, que fica na Mata Terokkar.', 0),
(10667, 'ptBR', 'Greda do submundo', 'Obtenha um Frasco de Greda do Submundo com a Hidromante Thespia e o traga para David Wayne no Refúgio de Wayne.', 'A estrutura que você me trouxe mais cedo não será suficiente para conter o metal derretido sem reforços. Um tipo raro de terra poderá ser usado para resfriar e imbuir a estrutura, dando uma força sobrenatural à adamantita.$B$BA greda do submundo, como a terra é conhecida, é portanto muito valorizada pelas nagas. Pouquíssimos a possuem, e aqui em Terralém, conheço apenas uma naga que a usa: a Hidromante Thespia, que reside na Câmara dos Vapores do Reservatório Presacurva.', '', '', '', '', '', '', '', '', '', 'Fale novamente com David Wayne no Refúgio de Wayne, que fica na Mata Terokkar.', 0),
(10668, 'ptBR', 'Contra os Illidari', 'Altruis, o Sofredor, quer que você assassine Lothros no Pontal Illidari, no Vale da Lua Negra.', 'Eu ainda respeito Illidan. Sem ele eu não teria encontrado meu caminho.$B$BEntretanto, Illidan não é mais quem já foi um dia. A alma de meu antigo aliado foi corrompida pelo poder, e sua mente, degenerada pela derrota. Illidan se transformou naquilo que jurei destruir, e seus servos de estimação, os Illidari, são tão abomináveis quanto qualquer demônio da Legião Ardente.$B$BO domínio que Illidan exerce sobre Terralém está se esvaindo, porém seu alcance ainda é vasto. Prove que não está com ele matando o tenente Lothros no Pontal Illidari, no Vale da Lua Negra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Altruis, o Sofredor, em Nagrand.', 0),
(10669, 'ptBR', 'Contra todas as chances', 'Altruis, o Sofredor, quer que você leve a Lança de Prata Imbuída e a use na Clareira do Portal perto do Lago Pantanoso, que fica no Pântano Zíngaro, para acordar Xeleth. Fale novamente com Altruis depois que você tiver assassinado o demônio.', 'Alguns demônios não juram fidelidade a ninguém além de si mesmos. Entretanto, aqueles que realmente odeiam os demônios buscam e destroem a presa independentemente das alianças dela.$B$BO demônio Xeleth, desertor da Legião, já foi um dia idolatrado como um deus pelas criaturas primitivas do Pântano Zíngaro. Quando Draenor foi quase destruída, Xeleth se recolheu num sono profundo sob o Lago Pantanoso. Encontre o portal no lago e finque esta lança no chão.$B$BXeleth despertará. Esteja $gpreparado:preparada; para matá-lo e provar que é $ginimigo:inimiga; de todos os demônios.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Altruis, o Sofredor, em Nagrand.', 0),
(10670, 'ptBR', 'Lágrima da Mãe-terra', 'Tome a Lágrima da Mãe-terra do Armipotente O\'mrogg e leve-a a David Wayne no Refúgio de Wayne.', 'Os encantamentos da espada devem ser contidos num foco poderoso, como uma gema. Conheço uma gema que podemos usar para esse fim, pois há poucas capazes de conter magia tão poderosa sem estilhaçar.$B$BChama-se lágrima da mãe-terra. É um artefato poderoso nas mãos dos ogros que a criaram, e o Armipotente O\'mrogg, o atual dono da gema, tem muitos aliados poderosos nos Salões Despedaçados da Cidadela Fogo do Inferno. Tome cuidado ao recuperar a lágrima, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com David Wayne no Refúgio de Wayne, que fica na Mata Terokkar.', 0),
(10671, 'ptBR', 'Mais que uma navalha na carne', 'Colete 5 pedaços de Carne Energizada com Éter', '$n, quero que faça outra coisa para mim. Um dos cabeçudos quer estudar as feras de carne demoníacas do campo de Razaan, a norte do Espinhaço Cortante.$B$BMais especificamente, eles querem estudar a carne daquelas feras.$B$B<Dina faz cara de nojo.>$B$BAlém de não querer pôr a mão na massa, ele ainda só quer carne energizada por éter, o que nem todas as feras devem ter.$B$BNa minha opinião, ele já está exigindo demais, mas não posso fazer nada...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dina Tonta na Estação do Tocha, nas Montanhas da Lâmina Afiada.', 0),
(10672, 'ptBR', 'Francamente, não faz sentido...', 'O Pesquisador Tiorus na Aldeia Lua Negra, que fica no Vale da Lua Negra, quer que você vá até a torrente de lava próxima às Ruínas de Baa\'ri e use a Unidade de Controle Arcano para comandar um Arcanescórpide. Vá nadar na lava controlando o Arcanescórpide e marque 8 Dimetrodontes Fogovil Maiores.', 'Precisamos estudar melhor as criaturas.$B$BBem a leste daqui – perto das grandes torrentes de lava sob as ruínas de Baa\'ri – você encontrará unidades de controle arcano. Foram criadas por um gênio chamado Gnomus, com o propósito exclusivo de explorar a lava usando escorpiões mecânicos.$B$BFaz tempo que ele enlouqueceu e agora só se interessa em provar as comidas mais quentes que a gnomidade já conheceu.$B$B<Tiorus lhe dá um olhar esquisito.>$B$BQuero que você use as unidades para marcar os dimetrodontes da torrente de lava para estudos futuros.', '', 'Dimetrodontes Fogovil Maiores marcados', '', '', '', '', '', '', '', 'Fale novamente com o Pesquisador Tiorus na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10673, 'ptBR', 'Espinhavil, o Grande', 'O Pesquisador Tiorus na Aldeia Lua Negra, que fica no Vale da Lua Negra, quer que você mate Espinhavil, o Grande, e lhe traga o Couro de Espinhavil.', 'Gnomus ficou sabendo do dimetrodonte gigante e planeja comê-lo! Ele deve ter visto o que eu vi, usando o arcanescórpide. Olha, não tenho tempo para explicações. Gnomus é louco, e a loucura dele vai nos custar a coisa mais próxima que temos de um macacão a prova de fogo.$B$BVolte à torrente de lava perto de Baa\'ri e localize Espinhavil, o Grande. Quando encontrá-lo, mate-o e traga-me o couro dele.$B$BNão tente argumentar comigo, $n. Já passei desse ponto há muito.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Pesquisador Tiorus na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10674, 'ptBR', 'Aprisione a luz fantástica', 'Use a Armadilha de Luz para coletar 15 Orbes de Luz Razaani.', 'Os etéreos Razaani andam brincando com uma tecnologia interessante no Campo de Razaan, ao norte.$B$BTenho certeza de que não vão se importar se você usar esta armadilha pra pegar umas amostras de orbes flutuantes de luz rosa. Devem servir só de enfeite mesmo.$B$BA armadilha tem uma propriedade especial pra atrair uma das bolas flutuantes quando estiver aberta. É óbvio que também deve alertar os Razaani da sua presença.', '', 'Orbes de Luz Razaani aprisionados', '', '', '', '', '', '', '', 'Fale novamente com Tocha na Estação do Tocha, que fica nas Montanhas da Lâmina Afiada.', 0),
(10675, 'ptBR', 'Tamanho não é documento', 'Recolha a Coleção de Almas.', '<Escorre sangue no rosto de Tocha.>$B$BOs orbes são feitos de energia e almas etéreas. E algumas são almas de gnomos!$B$BComo ousam! Eram eles que estavam matando os gnomos que iam para o norte?!$B$B$n, você precisa dar um basta nisso e a única forma é acabando com o líder deles, o Príncipe do Nexus Razaan.$B$BVocê vai precisar arrancá-lo do esconderijo. Ele deve sair, se você matar um monte de etéreos Razaani.$B$BTenho certeza de que ele tem uma coleção de almas. Pega e traz aqui pra mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tocha na Estação do Tocha, que fica nas Montanhas da Lâmina Afiada.', 0),
(10676, 'ptBR', 'Ruína dos Illidari', 'Espere que David Wayne termine de forjar a espada para você.', '<David pega os equipamentos.>$B$BVocê fez um ótimo trabalho em reunir tudo de que precisamos para reforjar a lâmina antidemônios. Seu trabalho duro e dedicação serão recompensados.$B$BChegou a hora de forjar a espada.', '', '', '', '', '', '', '', '', '', '', 0),
(10677, 'ptBR', 'O segundo prato...', 'Gnomus na Fortaleza Martelo Feroz, no Vale da Lua Negra, quer que você lhe traga 1 Moela Hipertrofiada de Fogovil.', 'Lembro de ter visto dimetrodontes maiores a leste da Mão de Gul\'dan, perto das torrentes de lava ao sul das Ruínas de Baa\'ri. Agora quero que você me consiga uma das moelas hipertrofiadas de fogovil das feras daquela região. Talvez seja necessário matar vários monstros para achar a moela que eu quero. Não desista! Um bicho desses certamente conterá minha próxima refeição.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gnomus na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10678, 'ptBR', 'O prato principal!', 'Gnomus na Fortaleza Martelo Feroz, no Vale da Lua Negra, quer que você lhe traga o Couro de Espinhavil.', 'Resumindo a história, eu costumava trabalhar com um elfo sangrento chamado Tiorus. Minha parceria com Tiorus se desfez quando entrei nessa vida de gourmet. Ele decidiu continuar nossas pesquisas por conta própria, usando as MINHAS invenções. Então, Tiorus mandou alguns capangas da Horda usarem as sondas do meu Arcanescórpide na torrente de lava das Ruínas de Baa\'ri, e descobriu o maior de todos os dimetrodontes!$B$BPreciso que você chegue lá antes dele e mate o monstro, Espinhavil, o Grande. Traga-me o couro do bicho.$B$BRápido!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gnomus na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10679, 'ptBR', 'Temperando a lâmina', 'Vá até os Lagos Escaldantes, localizados perto do topo da A Mão de Gul\'dan, e use a Lâmina da Ruína dos Illidari Forjada para temperá-la nos poços de lava. Uma vez que a lâmina esteja temperada, fale de novo com David Wayne no Refúgio de Wayne.', 'A lâmina está quase pronta!$B$BQuase dá para sentir a magia começando a coalescer dentro do aço. Porém, resta mais um último passo.$B$BLeve a lâmina forjada até os Lagos Escaldantes perto do topo da A Mão de Gul\'dan no Vale da Lua Negra, e mergulhe-a nos poços de lava para temperar a espada. Quando isso estiver feito, volte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com David Wayne no Refúgio de Wayne, que fica na Mata Terokkar.', 0),
(10680, 'ptBR', 'A Mão de Gul\'dan', 'Fale com o Reparador da Terra Torlok no Altar da Danação, que fica no Vale da Lua Negra.', 'Os elementos precisam da sua ajuda, $r! O Vale da Lua Negra foi submetido a malefícios indizíveis. Até hoje os espíritos ainda estão transtornados. Muitos estão enfurecidos e relutam em comungar com a Harmonia Telúrica.$B$BAjude a curar este mundo, $gamigo:amiga;.$B$BDiretamente a nordeste da Fortaleza Martelo Feroz há uma área conhecida como o Altar da Danação. Vá até lá e fale com o Reparador da Terra Torlok.', '', '', '', '', '', '', '', '', '', '', 0),
(10681, 'ptBR', 'A Mão de Gul\'dan', 'Fale com o Reparador da Terra Torlok no Altar da Danação, que fica no Vale da Lua Negra.', 'Os elementos precisam de sua ajuda, $r! O Vale da Lua Negra foi submetido a males indizíveis. Até hoje os espíritos continuam transtornados. Muitos estão enfurecidos e relutam em comungar com a Harmonia Telúrica.$B$BAjude a curar este mundo, $gamigo:amiga;.$B$BA sudeste da Aldeia Lua Negra, no coração do Vale da Lua Negra, você encontrará uma área conhecida como o Altar da Danação. Vá até lá e fale com o Reparador da Terra Torlok.', '', '', '', '', '', '', '', '', '', '', 0),
(10682, 'ptBR', 'Hora de negociar...', 'Negocie com o Supervisor Nuaar.', 'Quando chegamos ao Bosque Ruuan, os sectários das serpes estavam reclusos no Conciliábulo do Asa Negra, depois do túnel a oeste. No entanto, eles estão se aproximando cada vez mais.$B$BPreciso que encontre o supervisor dos sectários das serpes. Dizem que ele patrulha regularmente os vários acampamentos do Bosque Ruuan.$B$BTente negociar com ele. Diga a ele que estamos dispostos a fazer um acordo, mas que não toleraremos matança indiscriminada da vida selvagem e nem derrubada insensata das árvores.', 'Negociações com o Supervisor Nuaar concluídas', '', '', '', '', 'Negociações com o Supervisor Nuaar concluídas', '', '', '', 'Fale novamente com o Guardião Arbóreo Chawn no Arvoredo Eterno, que fica nas Montanhas da Lâmina Afiada.', 0),
(10683, 'ptBR', 'Tabuletas de Baa\'ri', 'O Arcanista Thelis, no Sacrário Estelar, quer que você recolha 12 Tabuletas Baa\'ri no chão e com os Trabalhadores Grislíngua, nas Ruínas de Baa\'ri.$B$BCompletar missões para os Áugures reduzirá sua reputação com os Aldor.', 'Os Degradados Grislíngua estão escavando as Ruínas de Baa\'ri, bem ao norte daqui, a mando de Illidan. Estão procurando por artefatos draeneicos, sem dúvida. Baa\'ri era um lugar de muitas relíquias antes que Gul\'dan enterrasse a cidade sob uma erupção vulcânica. Precisamos aproveitar a oportunidade para recuperar as Tabuletas de Baa\'ri, um texto antigo que, de acordo com rumores, contém os segredos do Templo de Karabor... um lugar que você provavelmente conhece como Templo Negro.', '', '', '', '', '', '', '', '', '', 'Procure o Arcanista Thelis no Sacrário Estelar, que fica no Vale da Lua Negra.', 0),
(10684, 'ptBR', 'Oronu, o Ancião', 'O Arcanista Thelis no Sacrário Estelar quer que você obtenha as Ordens de Akama com Oronu, o Ancião, nas Ruínas de Baa\'ri.$B$BCompletar missões para os Áugures reduzirá sua reputação com os Aldor.', 'De acordo com as tabuletas, havia um artefato conhecido como Medalhão de Karabor na cidade Baa\'ri. Só os sacerdotes draeneis mais elevados recebiam tal honra, pois os medalhões permitiam acesso ilimitado ao Templo de Karabor.$B$BÉ preciso saber se os Grislíngua já recuperaram o medalhão que era mantido em Baa\'ri. O poder do artefato nos ajudaria muitíssimo na contenda contra Illidan.$B$BO tenente de Akama em Baa\'ri, Oronu, o Ancião, recebe ordens escritas do mestre diariamente. Obtenha-as e traga-as para mim.', '', '', '', '', '', '', '', '', '', 'Procure o Arcanista Thelis no Sacrário Estelar, que fica no Vale da Lua Negra.', 0),
(10685, 'ptBR', 'Os corruptores Grislíngua', 'Obtenha os quatro fragmentos de medalhão com Haalum, Eykenen, Lakaan e Uylaru e procure o Arcanista Thelis no Sacrário Estelar, que fica no Vale da Lua Negra.$B$BCompletar missões para os Áugures reduzirá sua reputação entre os Aldor.', 'De acordo com a carta de Akama, quatro fragmentos do medalhão foram escavados e dado aos corruptores Grislíngua. Os perversos Degradados um dia foram poderosos xamãs que agora se aproveitam dos mesmos elementos que um dia reverenciaram.$B$BHaalum, o Corruptor do Ar, encontra-se na Trilha da Asa Etérea. Eykenen e Uylaru, Corruptores da Terra e do Fogo, foram vistos pela última vez nos Poços Fétidos perto da Mão de Gul\'dan. Segundo rumores, Lakaan, o Corruptor da Água, está próximo ao Pontal dos Serpentálios.$B$BEncontre-os e consiga os fragmentos de medalhão.', '', '', '', '', '', '', '', '', '', 'Procure o Arcanista Thelis no Sacrário Estelar, que fica no Vale da Lua Negra.', 0),
(10686, 'ptBR', 'A Jaula do Carcereiro', 'O Arcanista Thelis quer que você entre na Jaula do Carcereiro, ao sul das Ruínas de Baa\'ri e interrogue Sanoru quanto à localização de Akama.$B$BCompletar missões para os Áugures reduzirá sua reputação entre os Aldor.', 'Os fragmentos que você trouxe formam apenas metade do medalhão. Akama, o líder dos Grislíngua, deve estar com a outra metade.$B$BSinto ter de lhe pedir isso, considerando que Akama é tão maligno quanto ardiloso.$B$BAkama está com os Devotos da Morte Grislíngua, que são os membros mais depravados e brutais da tribo. É sabido que eles controlam uma câmara de torturas sob a Jaula do Carcereiro.$B$BQuero que encontre a temível prisão e descubra o paradeiro de Akama. O tenente dele no local é um Degradado conhecido como Sanoru. Interrogue-o, se precisar.', '', '', '', '', '', '', '', '', '', '', 0),
(10687, 'ptBR', 'Campo de treinamento Karabor', 'Larissa Golpessol, no Sacrário Estelar, quer que você obtenha 8 Glaives Solfúria dos Caçadores de Demônios Suplicantes e Caçadores de Demônios Iniciados nas Ruínas de Karabor, a nordeste do Sacrário Estelar.$B$BCompletar missões para os Áugures reduzirá sua reputação com os Aldor.', 'Nossos batedores relatam um trânsito intenso de recrutas elfos sangrentos Solfúria indo na direção das Ruínas de Karabor. Normalmente, isso representaria uma ameaça meramente militar. Entretanto, acreditamos que exista outra coisa de errado.$B$BAs descrições dos trajes e estilos de luta estranhamente são semelhantes às do próprio Illidan. Não pretendo me alarmar sem motivos, por isso quero que vá até lá e me traga as armas deles. Assim, determinaremos se meus temores têm ou não fundamento.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Larissa Golpessol no Sacrário Estelar, que fica no Vale da Lua Negra.', 0),
(10688, 'ptBR', 'Uma distração necessária', 'Larissa Golpessol quer que você volte às Ruínas de Karabor e descubra uma forma de libertar Azaloth, voltando-o contra seus captores.$B$BCompletar missões para os Áugures reduzirá sua reputação com os Aldor.', 'Como eu temia, as armas são autênticas. Illidan está treinando caçadores de demônios nas Ruínas de Karabor, e precisamos acabar com isso.$B$BNão se iluda com o nome "caçadores de demônios", $n. O poder deles será empregado contra nós também.$B$BOs bruxos evocam e subjugam demônios que são usados no treinamento dos iniciados. Um lorde abissal chamado Azaloth demostrou ser poderoso demais para ser usado no treinamento, e foi aprisionado em um feitiço de banimento. Descubra uma maneira de libertá-lo de seus captores. Assim ganharemos o tempo de que precisamos.', '', 'Azaloth liberto', '', '', '', '', '', '', '', 'Fale novamente com Larissa Golpessol no Sacrário Estelar, que fica no Vale da Lua Negra.', 0),
(10689, 'ptBR', 'Altruis', 'Vá até o oeste de Nagrand e encontre Altruis, o Sofredor.$B$BCompletar missões para os Áugures reduzirá sua reputação junto aos Aldor.', 'É difícil achar um caçador de demônios hoje em dia. Eles são vistos com desconfiança pelo próprio povo, e é raro descobrir um que não esteja aliado a Illidan.$B$BPorém, há rumores de um caçador de demônios independente em Nagrand. O nome dele é Altruis. Ele odeia profundamente os demônios e irá nos ajudar se você conseguir convencê-lo de que temos os mesmos objetivos.$B$BVá para Nagrand ocidental e encontre-o. Talvez ele se disponha a nos ajudar a compreender melhor o novo campo de treinamento de caçadores de demônios.', '', '', '', '', '', '', '', '', '', '', 0),
(10690, 'ptBR', 'A matriarca do covil', 'Mate Rema.', 'PROCURADA!$B$BRema, matriarca do covil e guardiã principal da Serra dos Espigões, a sul da Cidadela do Senhor do Trovão.$B$BPara encontrá-la, vá para o leste, partindo da cidade, e cruze a ponte que atravessa o Barranco Malho Sangrento. Ela se mantém isolada num túnel no extremo sul da serra.$B$BLeve notícias da morte dela ao Comandante Caelumbra de Sylvanaar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Caelumbra em Sylvanaar, nas Montanhas da Lâmina Afiada.', 0),
(10691, 'ptBR', 'Retorno aos Áugures', 'Fale com Larissa Golpessol no Sacrário Estelar, que fica no Vale da Lua Negra.$B$BCompletar missões para os Áugures reduzirá sua reputação com os Aldor.', 'Este livro... Eu poderia usá-lo para incrementar meu poder em dez vezes... Não! Acabaria corrompendo a minha alma, tenho certeza. Volte para aqueles que $go:a; mandaram aqui, $n. Agora você tem uma maneira de derrotar Varedis. Espere até que ele manifeste a forma demoníaca por metamorfose, e, quando acontecer, queime o livro diante dele. É a única forma de privá-lo dos poderes.', '', '', '', '', '', '', '', '', '', '', 0),
(10692, 'ptBR', 'Varedis precisa ser detido!', 'Larissa Golpessol quer que você vá até as ruínas de Karabor e mate Alandien, Theras, Netharel e Varedis. Use o Livro dos Nomes Abjetos para enfraquecer Varedis quando ele usar Metamorfose. Fale novamente com Larissa Golpessol após completar a tarefa.$B$BCompletar missões para os Áugures reduzirá sua reputação junto aos Aldor.', 'É claro que vamos destruir o livro, mas não antes de usá-lo para destruir Varedis.$B$BPara fecharmos a academia de imitadores de Illidan que ele dirige, teremos que lidar não só com Varedis, mas também com os três mestres elfos noturnos que o ajudam: Alandien, Theras e Netharel.$B$BReúne um grupo adequado e volte às Ruínas de Karabor. Siga as instruções de Altruis para derrotar Varedis. Espero que o plano dele funcione. Caso contrário... foi um prazer trabalhar com você.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Larissa Golpessol no Sacrário Estelar, que fica no Vale da Lua Negra.', 0),
(10693, 'ptBR', 'Um sinete de comenda', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comendador de Luaprata em Durotar.', 0),
(10694, 'ptBR', 'Dez sinetes de comenda', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comendador de Luaprata em Durotar.', 0),
(10695, 'ptBR', 'Um sinete de comenda', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Comendador da Exodar em Dun Morogh.', 0),
(10696, 'ptBR', 'Dez sinetes de comenda', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Comendador da Exodar em Dun Morogh.', 0),
(10697, 'ptBR', 'Um sinete de comenda', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Oficial da Alvorada na Floresta do Canto Eterno.', 0),
(10698, 'ptBR', 'Dez sinetes de comenda', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Oficial da Alvorada na Floresta do Canto Eterno.', 0),
(10699, 'ptBR', 'Um sinete de comenda', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Oficial Khaluun na Ilha Névoa Lazúli.', 0),
(10700, 'ptBR', 'Dez sinetes de comenda', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Oficial Khaluun na Ilha Névoa Lazúli.', 0),
(10701, 'ptBR', 'Éter mole em Pétrer duro', 'Mate Pétrer e apresente-se ao Mestre-fogueteiro Fuselagem, na Área 52, em Eternévoa.', 'A todos que se interessarem na construção do Foguéter X-52 dentro do prazo:$B$BO rei dos gigantes rochedo das redondezas, Pétrer, está aterrorizando os Ermos Esfacelados. Ele está interferindo em todas as operações na porção sul da ilha!$B$BJunte-se a seus amigos e acabe com ele! Depois, fale comigo aqui na Área 52.$B$BMestre-fogueteiro Fuselagem', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre-fogueteiro Fuselagem, na Área 52, em Eternévoa.', 0),
(10702, 'ptBR', 'Trabalho de bruto', 'O Suserano Or\'barokh da Aldeia Lua Negra quer que você mate 20 animais da fauna do Vale da Lua Negra. Entre eles estão os Viljavardos, as Quimeras Asavil e os Tenazes Chamuscos. Qualquer combinação deles será suficiente.', 'Todas as forças da Horda nesta região foram despachadas para lidar com os ataques da Legião Ardente. Ou seja, precisamos de mais gente para fazer o trabalho de bruto.$B$BNossas caravanas de suprimentos sofrem ataques constantes das feras da região. Não podemos sair cinco metros da estrada sem nos deparar com uma quimera, viljavardo ou escorpião superdesenvolvido.$B$BVá lá fora e limpe o Vale da Lua Negra dessas bestas sádicas! Pode matar tudo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Suserano Or\'barokh na Aldeia Lua Negra, que fica no Vale da Lua Negra.', 0),
(10703, 'ptBR', 'Hora de pôr as joelheiras...', 'O Thane Yoregar da Fortaleza Martelo Feroz quer que você mate 20 animais selvagens do Vale da Lua Negra.$B$BTais criaturas incluem os Viljavardos, as Quimeras Asavil e os Tenazes Chamuscos. Qualquer combinação será suficiente.', 'Está na hora de encarar o serviço pesado. O que é que você esperava? Quem sai na chuva é pra se queimar, não é? Ah, não, espere, não é bem assim...$B$BEnfim, estamos com todo mundo ocupado matando os cramulhões que a Legião Ardente está jogando pra cima da gente. Isto lhe dá a honra de acabar com os animais selvagens enlouquecidos que vagueiam pelo Vale da Lua Negra.$B$BPegue uma espada, cajado, seja lá o que for, e mate o máximo de animais selvagens que conseguir. Assim vamos abrir caminho para as nossas caravanas de suprimentos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Thane Yoregar na Fortaleza Martelo Feroz, no Vale da Lua Negra.', 0),
(10704, 'ptBR', 'Como entrar em Arcatraz', 'A\'dal quer que você recupere os fragmentos Superior e Inferior da Chave de Arcatraz. Leve-os para ele, para que ele possa criar a Chave para Arcatraz para você.', 'Uma mensagem foi embutida no cristal ata\'mal que você recuperou. O Príncipe do Nexus Haramad nos deu informações vitais para nossa campanha contra a Bastilha da Tormenta.$B$BEle nos disse que existem dois pedaços, dois estilhaços de chave que, ao ser combinados, destrancam o satélite Arcatraz da bastilha.$B$BUm pedaço está com um anciente conhecido como Estilhaço Dimensional, no Jardim Botânico. O outro está com Pathaleon, o Calculista, dentro do Mecanar.$B$BTraga os dois pedaços para mim e eu os combinarei para criar a chave de Arcatraz.', '', '', '', '', '', '', '', '', '', 'Fale novamente com A\'dal no Bairro Inferior, que fica em Shattrath.', 0),
(10705, 'ptBR', 'Vidente Udalo', 'Encontre o Vidente Udalo em Arcatraz, na Bastilha da Tormenta.', 'Espero que você não se assuste quando eu revelar que os pedaços do medalhão de Karabor que você obteve dos meus lacaios são simples réplicas.$B$B<Akama mostra um medalhão idêntico na palma da mão.>$B$BOs Devotos da Morte e eu mantivemos o segredo longe dos ouvidos de Illidan tanto quanto foi possível. Contudo, ainda falta a última peça.$B$BUdalo veio a mim em sonhos para anunciar que a havia encontrado. Infelizmente ele é mantido preso por Kael\'thas em Arcatraz, na Bastilha da Tormenta. Encontre-o e descubra o que ele sabe.', '', '', '', '', '', '', '', '', '', '', 0),
(10706, 'ptBR', 'Um portento misterioso', 'Fale novamente com Akama na Jaula do Carcereiro no Vale da Lua Negra.', 'Antes de morrer, Udalo escreveu uma única palavra no chão sob si. As letras estão quase ilegíveis, mas você reconhece a palavra Atam\'al.$B$BQuiçá Akama entenderá o significado da mensagem do compatriota.', '', '', '', '', '', '', '', '', '', '', 0),
(10707, 'ptBR', 'O Terraço de Ata\'mal', 'Vá ao topo do Terraço de Ata\'mal no Vale da Lua Negra e obtenha o Coração da Fúria. Cumprida a tarefa, fale novamente com Akama na Jaula do Carcereiro, no Vale da Lua Negra.', 'Sabemos que os orcs vis, sob o comando de Illidan, vêm guardando um Cristal de Ata\'mal conhecido como Coração da Fúria, no Terraço de Ata\'mal. Eles lhe ocultam a presença com magia negra para mantê-lo longe dos Sha\'tar.$B$BAbra caminho à força até o Terraço de Ata\'mal do lado de fora do Templo Negro e olhe para o céu. O Umbramestre Tanatuivos estará sobrevoando o terraço em círculos, além do seu alcance. Será necessário matar tanto ele quanto os bruxos para obter o cristal.$B$BNão será fácil, $n. Desejo-lhe sorte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Akama na Jaula do Carcereiro, que fica no Vale da Lua Negra.', 0),
(10708, 'ptBR', 'A promessa de Akama', 'Traga o Medalhão de Karabor a A\'dal na cidade de Shattrath.', '<Akama insere o cristal no medalhão.>$B$BNão sou tão forte quanto já fui um dia, $n. Após tanto tempo ao lado da encarnação do mal, não sei mai se é possível confiar um artefato tão poderoso a mim mesmo.$B$BLeve isto como promessa de que estarei ao seu lado quando a hora chegar de você enfrentar Illidan. Leve-o para o único ser em quem poderemos confiar tanto poder. Entregue o medalhão a A\'dal na cidade de Shattrath.', '', '', '', '', '', '', '', '', '', '', 0),
(10709, 'ptBR', 'Reunião', 'Fale com Rexxar na Cidadela do Senhor do Trovão, nas Montanhas da Lâmina Afiada.', 'Então você é do mundo do outro lado do Portal? E conhece Rexxar. Ah, sim, eu o conheço bem.$b$bPara falar a verdade, é meu filho.$b$bEle tomou a decisão que quis muito tempo atrás. Ele não é um dos nossos e não é bem-vindo aqui. Já temos muitos problemas com os ogros Malho Sangrento.$b$bEntenda: nascer mestiço não o transforma em Mok\'nathal.', '', '', '', '', '', '', '', '', '', '', 0),
(10710, 'ptBR', 'Voo de teste: Platô Harmônico', 'Assine o Documento de Isenção de Betto e depois fale com Netto Desastraz para usar o Capacitório de Zefírio.', 'Fiz alguns ajustes no Capacitório de Zefírio e estou pronto para outro teste! Está a fim de ajudar?$B$BEsse próximo voo deve ser curto, mas rápido!$B$BErr... tenho certeza de que não tem perigo, mas... queria que assinasse esse documento de isenção. É só uma formalidade, pode confiar!$B$BBoa sorte! Fale com Netto para se lançar e volte aqui depois que acabar o teste!', 'Se joga na pista!', '', '', '', '', 'Se joga na pista!', '', '', '', 'Fale novamente com Betto Desastraz na Estação do Tocha, nas Montanhas da Lâmina Afiada.', 0),
(10711, 'ptBR', 'Voo de teste: Campo de Razaan', 'Fale com Netto Desastraz para usar o Capacitório de Zefírio.', '$n, melhorei a eficiência do Capacitório de Zefírio em 30%. Vai lançar um voluntário do seu peso e resistência ao ar a novas alturas! Quer testar a minha teoria? Esse teste vai te mandar para perto do Campo de Razaan.$B$BFale com o Netto... Ele vai fazer os preparos para o lançamento.', 'O céu é o limite!', '', '', '', '', 'O céu é o limite!', '', '', '', 'Fale novamente com Betto Desastraz na Estação do Tocha, nas Montanhas da Lâmina Afiada.', 0),
(10712, 'ptBR', 'Voo de teste: Bosque Ruuan', 'Fale com Netto Desastraz para usar o Capacitório de Zefírio. Gire o Cata-vento do Éter enquanto estiver voando para o Bosque Ruuan. Entregue o Cata-vento do Éter Girante para Anacletto Desastraz no Arvoredo Eterno.', 'Ei, $n. Ainda bem que te encontrei! Tenho uma missão muito importante!$B$BIsto é um cata-vento do éter. Preciso que você faça algumas leituras em voo e entregue-as ao meu primo no Bosque Ruuan.$B$BFale com o Netto e use o Capacitório de Zefírio para ir voando até o Bosque Ruuan. Use o cata-vento enquanto estiver voando!$B$BDepois de pousar, leve o cata-vento girante para Anacletto Desastraz.$B$BBoa sorte, $n. E não demore!', 'Lançamento para o Bosque Ruuan.', '', '', '', '', 'Lançamento para o Bosque Ruuan.', '', '', '', 'Fale com Anacletto Desastraz no Arvoredo Eterno, que fica nas Montanhas da Lâmina Afiada.', 0),
(10713, 'ptBR', '... e hora de agir', 'Mate 10 Lenhadores da Seita das Serpes.', 'Não ficaremos de braços cruzados enquanto eles dizimam o Bosque Ruuan à nossa volta. A nossa principal prioridade são as árvores.$B$B$C, quero que volte ao bosque e leve uma mensagem bem diferente da primeira. Quero que mate todos os lenhadores que atravessarem o seu caminho!$B$BEles não deram ouvidos à razão, mas talvez um método mais persuasivo dê certo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guardião Arbóreo Chawn no Arvoredo Eterno, que fica nas Montanhas da Lâmina Afiada.', 0),
(10714, 'ptBR', 'Nas asas de Espírito', 'Encontre um Capataz Malho Sangrento e um Adivinho Malho Sangrento conversando e use o Apito do Rexxar para chamar Espírito para espioná-los.', 'Se os ogros Malho Sangrento estão atormentando os Mok\'nathal, então darei um jeito neles e nos seguidores deles. Os ogros são criaturas inocentes e ganhariam pouco incomodando os Mok\'nathal.$b$bDeve haver algo maior por trás disso. $n, leve Espírito, meu falcão, e observe as conversas dos líderes dos Malho Sangrento. Ele pode ir a lugares que não podemos sem ser percebido.', '', 'Espione os planos dos Malho Sangrento', '', '', '', '', '', '', '', 'Fale novamente com Rexxar na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10715, 'ptBR', 'Para a Ravina Trêmula', 'Colete 7 Glândulas Peçonhentas de Estoura-crosta.', 'Então Rexxar quer que eu faça um veneno para ele? Até posso fazer o que ele quer, mas por um preço. Mesmo para amigos, sempre deve haver um preço. Fazer as coisas de graça acaba com a amizade.$B$BPrimeiro, você precisa caminhar um pouco para sudoeste, para a Ravina Trêmula.$B$BLá, mate algumas das criaturas mais venenosas de toda a Terralém, ou do universo. Estou falando dos estoura-crostas. Preciso das glândulas deles para preparar o veneno.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Zibecrina no Círculo Sangrento, que fica nas Montanhas da Lâmina Afiada.', 0),
(10717, 'ptBR', 'Ladrão que rouba ladrão...', 'Colete 5 Redes da Seita das Serpes.', 'Desculpe-me, mas não pude deixar de ouvir a sua conversa com Chawn e gostaria de $gajudá-lo:ajudá-la;.$B$BEstou analisando o Conciliábulo do Asa Negra e ajudando os druidas a lidar com eles.$B$BEstou bastante interessada em conseguir alguns dragonetes. Saber mais sobre o que eles tanto veneram será bastante útil para termos uma noção exata do que temos pela frente.$B$BNós precisamos de algumas redes para isso, e notei que os caçadores da Seita das Serpes do Bosque Ruuan têm várias.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Samia Longes no Arvoredo Eterno, que fica nas Montanhas da Lâmina Afiada.', 0),
(10718, 'ptBR', 'Os espíritos têm vozes', 'Fale com Rexxar na Cidadela do Senhor do Trovão, nas Montanhas da Lâmina Afiada.', '$n, agora que pode me ver, quero que diga algo a Rexxar. Sei que ele está à procura de seu povo e sei onde estão.$B$BOs Mok\'nathal, como são conhecidos, têm uma aldeia a leste, depois do Espinhaço Cortante.$B$BVá dizer isso a Rexxar. O povo dele está em perigo e sei que ele quer ajudá-los.', '', '', '', '', '', '', '', '', '', '', 0),
(10719, 'ptBR', 'Recebeu o bilhete?', 'Entregue o Bilhete de Reunião ao Guardião Arbóreo Chawn no Arvoredo Eterno, que fica nas Montanhas da Lâmina Afiada.', 'O sectário deixou cair este recado, que parece ser destinado ao supervisor Nuaar. Está assinado por alguém chamado Kolphis Skamanegra.$B$BO guardião arbóreo Chawn ficará interessado em ver isto.', '', '', '', '', '', '', '', '', '', '', 0),
(10720, 'ptBR', 'As menores criaturas', 'Use o Tambor de Couro de Kodo na Toca das Marmotas. Envenene três barris na Base dos Malho Sangrento controlando a Marmota.', 'Os ogros, mesmo sendo tão inocentes, com certeza perceberiam se você espalhasse isso na base deles. Portanto, eu ensinarei a recrutar ajuda de uma das menores criaturas da natureza para fazer o serviço.$b$bVocê pode fazer uma marmota obedecer seus comandos ao soar uma simples batida neste tambor.$b$bHá uma toca de marmotas perto da Base dos Malho Sangrento, na Garganta Gorjadaga, depois do Círculo Sangrento.$B$BQuando conseguir fazer com que a marmota $go:a; ajude, use-a para dispersar o veneno nos barris dos Malho Sangrento.', '', 'Envenene o Barril de Grogue Verde', 'Envenene o Barril de Maria-louca Envelhecida', 'Envenene o Barril de Fermentado de Semente', '', '', '', '', '', 'Fale novamente com Rexxar na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10721, 'ptBR', 'Grulloc e o javali', 'Colete a Sacola de Grulloc.', '$n, tenho um javali de estimação chamado Bufo. Ele quer $Gajudá-lo:ajudá-la; a se divertir um pouco com um dos filhos de Gruul aqui perto. $B$BGrulloc fica em um lugar conhecido como Clareira Maldita. Quando chegar lá, solte o Bufo. O gronn ficará um bom tempo correndo atrás dele. Aproveite para reaver a sacola que ele protege e a entregue ao Barão Zibecrina.$B$BPara chegar à Clareira Maldita, siga pela ladeira ao norte e depois para leste, por Findragões. A clareira fica no extremo leste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Zibecrina no Círculo Sangrento, que fica nas Montanhas da Lâmina Afiada.', 0),
(10722, 'ptBR', 'Reunião no Conciliábulo do Asa Negra', 'Colete Pedaços de Uniforme dos sectários das serpes para criar um Disfarce de Supervisor. Use o disfarce para participar da reunião com Kolphis Escamanegra.', 'Já sei o que temos que fazer, $n! Você deve comparecer à reunião se fazendo passar pelo supervisor Nuaar!$B$BOs sectários das serpes têm um uniforme padrão. Dá pra você pegar um pedaço de cada um e montar um disfarce.$B$BSe disfarce de supervisor Nuaar, descubra as pretensões de Kolphis Escamanegra e depois fale com o guardião arbóreo Chawn.$B$BVá pelo Túnel Caveira de Dragão e siga até o fim do caminho que passa pela Mata do Corvo e por Grishnath.', 'Reunião com Kolphis Escamanegra presenciada', '', '', '', '', 'Reunião com Kolphis Escamanegra presenciada', '', '', '', 'Fale novamente com o Guardião Arbóreo Chawn no Arvoredo Eterno, que fica nas Montanhas da Lâmina Afiada.', 0),
(10723, 'ptBR', 'Gorgrom, o Devorador de Dragão', 'Colete 3 Totens Medonhos dos ogros Rocha\'mok. Depois use a Armadilha de Zibecrina no Altar de Gorgrom para atrair e matar Gorgrom, o Devorador de Dragão.$b$bQuando Gorgrom estiver morto, coloque 3 Totens Medonhos perto do cadáver.', 'O gronn que procuramos é Gorgrom, o Devorador de Dragão. Com a armadilha de Zibecrina você dará um jeito nele. Você vai encontrá-lo aceitando sacrifícios dos ogros de Rocha\'mok.$b$bSiga a estrada para o norte do Círculo Sangrento e depois vire para o oeste no Bosque Ruuan. Vá para noroeste pelo túnel.$b$bPrimeiro, mate os ogros e pegue suas cabeças. Vamos mandar um recado. Monte a armadilha no altar de Gorgrom. Quando ele estiver morto, coloque os totens medonhos perto do seu corpo. Todos entenderão o aviso.$b$bLeve o urso.$b$b<Misha dá um rugido.>', '', 'Use o Totem Medonho', '', '', '', '', '', '', '', 'Fale novamente com Rexxar na Cidadela do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10724, 'ptBR', 'Prisioneiro dos Giralança', 'Mate os ogros Giralança para obter a Chave da Jaula da Mantícora. Quando a tiver, vá para a Jaula da Mantícora e use o Apito do Espírito para chamá-lo, destrancar a jaula e libertar Leokk.', 'Pouco depois da minha chegada às montanhas, fui atacado por um grupo de ogros Giralança.$b$bConsegui me livrar e matar muitos, mas capturaram a minha mantícora, Leokk. Espírito o encontrou preso em uma jaula no centro do acampamento dos Giralança na entrada do Covil de Gruul.$b$bUm dos ogros deve estar com a chave. Encontre-a e Espírito poderá usá-la para destrancar a jaula de Leokk.$B$BO acampamento fica no extremo norte da Garganta Gorjadaga abaixo.', '', 'Resgate Leokk', '', '', '', '', '', '', '', 'Fale novamente com Rexxar na Vila do Senhor do Trovão, que fica nas Montanhas da Lâmina Afiada.', 0),
(10725, 'ptBR', 'Eminência do Olho Violeta', 'Leve seu Sinete Violeta para a Arquimaga Leryda, na Trilha do Vento Morto, após obter a reputação "$gExaltado:Exaltada;" com o Olho Violeta.', 'Seus serviços foram acima e além do que se esperava de você, $n. Falta muito pouco para você conseguir a honra mais alta disponível para não-cidadãos de Dalaran.$B$BContinue a provar sua lealdade para conosco e eu carregarei seu sinete completamente.', '', '', '', '', '', '', '', '', '', '', 0),
(10726, 'ptBR', 'Eminência do Olho Violeta', 'Leve seu Sinete Violeta para a Arquimaga Leryda, na Trilha do Vento Morto, após obter a reputação "$gExaltado:Exaltada;" com o Olho Violeta.', 'Seus serviços foram acima e além do que se esperava de você, $n. Falta muito pouco para você conseguir a honra mais alta disponível para não-cidadãos de Dalaran.$B$BContinue a provar sua lealdade para conosco e eu carregarei seu sinete completamente.', '', '', '', '', '', '', '', '', '', '', 0),
(10727, 'ptBR', 'Eminência do Olho Violeta', 'Leve seu Sinete Violeta para a Arquimaga Leryda, na Trilha do Vento Morto, após obter a reputação "$gExaltado:Exaltada;" com o Olho Violeta.', 'Seus serviços foram acima e além do que se esperava de você, $n. Falta muito pouco para você conseguir a honra mais alta disponível para não-cidadãos de Dalaran.$B$BContinue a provar sua lealdade para conosco e eu carregarei seu sinete completamente.', '', '', '', '', '', '', '', '', '', '', 0),
(10728, 'ptBR', 'Eminência do Olho Violeta', 'Leve seu Sinete Violeta para a Arquimaga Leryda, na Trilha do Vento Morto, após obter a reputação "$gExaltado:Exaltada;" com o Olho Violeta.', 'Seus serviços foram acima e além do que se esperava de você, $n. Falta muito pouco para você conseguir a honra mais alta disponível para não-cidadãos de Dalaran.$B$BContinue a provar sua lealdade para conosco e eu carregarei seu sinete completamente.', '', '', '', '', '', '', '', '', '', '', 0),
