(11864, 'ptBR', 'Instrução de uma missão', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(11865, 'ptBR', 'A morte é pouco', 'Zazá no Acampamento da DruiPA, que fica na Tundra Boreana, quer que você use a Pilha de Peles Falsas para prender 8 Coureadores de Rosarães.', 'Os caribus costumavam vagar livre e pacificamente na área ao sul daqui. Daí Rosarães apareceu e tudo mudou. Agora os caribus estão em um estado de loucura permanente, sempre em pânico. Eles vêm sendo emboscados por caçadores e coureadores do Rosarães, escondidos no campo.$B$BA morte é pouco para esses assassinos. Eles precisam vivenciar a tortura que causam aos caribus!$B$BLeve esta pilha de peles falsas e coloque-as em cima das armadilhas para caribus ao sul. Observe os caçadores serem pegos em suas próprias armadilhas mortais!', '', 'Coureador de Rosarães preso', '', '', '', '', '', '', '', 'Fale novamente com Zazá no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11866, 'ptBR', 'Faça-os ouvir!', 'Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana, disse que recompensará quem trouxer 15 Orelhas de Lacaios de Rosarães.', 'Não importa se são caçadores de tesouro ou de animais. Qualquer um que apoie Rosarães e ouse atacar nossa querida vida selvagem será considerado um inimigo da DruiPA.$B$BCaso mate algum desses imundos simpatizantes de Rosarães, traga-me prova da morte deles e eu $go:a; recompensarei com a bênção dos druidas da DruiPA.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11867, 'ptBR', 'Não vão me ouvir reclamar!', 'Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana, disse que recompensará quem trouxer 15 Orelhas de Lacaio de Rosarães.', 'Não importa se são caçadores de tesouro ou de animais. Qualquer um que apoie Rosarães e ouse atacar nossa querida vida selvagem será considerado um inimigo da DruiPA. Caso mate algum desses imundos simpatizantes de Rosarães, traga-me prova da morte deles e eu $go:a; recompensarei com a bênção dos druidas da DruiPA.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11868, 'ptBR', 'Eis que vem a Abatedora', 'Zazá no Acampamento da DruiPA, que fica na Tundra Boreana, quer que você mate Karen, a Abatedora.', 'Perto da extremidade sul desta elevação é onde se encontra a traiçoeira líder dos coureadores de caribus. Ela é mais cruel do que qualquer outro, desfilando com as carcaças dos animais mortos, bebendo de seu sangue e uivando para as luas!$B$BEncontre Karen, essa assassina cruel, e acabe com a indigna existência dela.$B$BPrepare-se para o combate, $n: Karen, a Abatedora, gosta de esbanjar as generosas riquezas com que Rosarães Guima a presenteia!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zazá no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11869, 'ptBR', 'Feliz feito um marisco', 'A Hierofante Cenius no Acampamento da DruiPA, que fica na Tundra Boreana, quer que você mate 10 Mergulhadores Ávidos por Despojos.', 'A oeste daqui, você encontrará o Lago Kum\'uya. Até onde sei, ele é o único habitat de mariscos gigantes de água doce do mundo.$B$BNão é nenhuma surpresa que os lacaios do Rosarães estejam usando o lugar como uma fazenda de pérolas gigantes. Eles precisam ser detidos! Precisamos ensinar uma lição a todos que ameaçam uma espécie inteira.$B$BVá para o Lago Kum\'uya, encontre os mergulhadores ávidos por despojos e mate todos eles até que a água fique vermelha! Uma vez que você tenha ensinado uma lição a eles, volte a falar comigo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Hierofante Cenius no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11870, 'ptBR', 'Confins Abandonados', 'Encontre a Hierofante Liandra, nos Confins Abandonados.', 'Liandra acaba de nos informar que mercenários contratados por Rosarães Guima estão transportando mercadorias desde a praia até o principal navio de carga Rosarães. Eles sem dúvida planejam fazer fortuna com esse comércio assassino!$B$BEla me pediu para que mandasse assistência para os Confins Abandonados, ao sul daqui, às margens da praia da Tundra Boreana.$B$BVá rápido: Liandra espera você!', '', '', '', '', '', '', '', '', '', '', 0),
(11871, 'ptBR', 'Não na nossa vigília', 'A Hierofante Liandra, nos Confins Abandonados da Tundra Boreana, quer que você recupere 12 Carregamentos de Pedaços de Animais.', 'Espalhadas pela praia, por entre os destroços, estão caixas e sacolas com restos de animais. Parece que Rosarães está em parceria com os Flibusteiros do Mar Norte. Aqueles piratas imundos estão transportando as mercadorias que os lacaios assassinos do Rosarães coletam pelo mar. Com certeza eles vão se juntar a outros figurões ricos e inescrupulosos por toda Azeroth.$B$BIsso não pode acontecer. Não na nossa vigília. Traga-me todos os carregamentos que achar pela praia. Eles não vão pôr as mãos neles!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Hierofante Liandra nos Confins Abandonados da Tundra Boreana.', 0),
(11872, 'ptBR', 'O nefário senhor dos mariscos...', 'Mate o Senhor dos Mariscos K e fale com a Hierofante Cenius no Acampamento da DruiPA.', 'É ultrajante alguém se autoproclamar "Senhor dos Mariscos" como se pudesse ter controle sobre as criaturas do mar. Ninguém deveria dizer uma coisa dessas!$B$BEsse tal "Senhor dos Mariscos" precisa ser encontrado e morto. Ele foi visto pela última vez nos destroços perto da costa dos Confins Abandonados. Encontre-o e mate-o.$B$BUma vez que tiver feito isso, fale com a Hierofante Cenius no Acampamento da DruiPA, ao norte daqui, e conte a ela que a missão foi um sucesso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Hierofante Cenius no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11873, 'ptBR', 'Notícias ao Biela', 'Volte para a Pista de Pouso do Biela e fale com o Biela Velotroll.', 'Você se importaria de voltar até a pista de pouso e contar ao Biela que eu não demorarei para entregar meu relatório final? Ainda preciso cuidar dos destroços da minha aeronave, mas vou para lá em seguida.$B$BFarei com que o Biela saiba que é a você quem ele deve agradecer pela minha sobrevivência e todo o trabalho de resgate.$B$BFico imaginando o que o velho aviador teria feito caso estivesse voando conosco. Tenho saudade daqueles tempos.', '', '', '', '', '', '', '', '', '', '', 0),
(11874, 'ptBR', 'Upper Deck Promocional - Foguete de Montaria', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(11875, 'ptBR', 'Tomando a dianteira', 'Leve 8 Resíduos de Éter ao Emissário Mordin em Shattrath.', 'As tropas da Ofensiva do Sol Partido precisarão de toda vantagem possível para dar o troco nos aliados de Kil\'jaeden. Os meus colegas de Ventobravo criaram óleos para fortalecer as lâminas e as armaduras das tropas.$B$BO ingrediente principal, resíduo de éter, está espalhado por toda a Terralém. Basta saber onde procurar. Qualquer mestre herborista, esfolador ou minerador que souber ler os sinais pode obtê-lo ao fazer as atividades rotineiras. Quaisquer ervas, minérios e feras nativas de Terralém podem conter o resíduo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Emissário Mordin na Mata Terokkar.', 0),
(11876, 'ptBR', 'Ajude quem não pode se ajudar', 'Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana, quer que você use a Esmagadora de Armadilhas da DruiPA para libertar 8 Filhotes de Mamute.', 'Criaturas majestosas, não acha?$B$B<Lathorius aponta para os mamutes na tundra do norte.>$B$BA cada dia, seus números diminuem. Demônios, que se autodenominam caçadores, matam por esporte ou por ganância.$B$B<O rosto de Lathorius se contorce de raiva.>$B$BÉ a lamúria que me ensandece, $n. Dá para ouvi-la, trazida pelo vento – filhotes de mamutes, aprisionados nas perversas armadilhas dos caçadores, chamando por nós.$B$BPegue esta marreta e destrua-as. Liberte os filhotes!', '', 'Filhote de Mamute libertado', '', '', '', '', '', '', '', 'Fale novamente com o Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11877, 'ptBR', 'Plano de Ataque dos Solfúria', 'Lorde Torvos, em Shattrath, quer que você obtenha o Plano de Ataque dos Solfúria.', 'Durante a ofensiva em Quel\'Danas, descobrimos que os lacaios de Kael\'thas estão planejando um contra-ataque. Ele ordenou que os elfos sangrentos Solfúria, situados em Eternévoa, ataquem nossas operações em Terralém de modo a desviar nossas tropas e nossa atenção para longe da Nascente do Sol.$B$BNão podemos permitir isso, $n. Precisamos que todas as lâminas disponíveis unam forças nas linhas de frente.$B$BVá a Eternévoa e obtenha os planos de ataque deles. Qualquer elfo sangrento Solfúria pode estar em posse dos planos. Boa sorte, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Lorde Torvos em Shattrath.', 0),
(11878, 'ptBR', 'Khu\'nok saberá', 'Leve o Filhote Órfão de Mamute para Khu\'nok, o Beemote na Tundra Boreana.', 'Embora tenha agido bravamente libertando os filhotes aprisionados, muitos ainda morrerão. Sem ninguém para vigiá-los, precisarão lutar pela própria sobrevivência na natureza.$B$BMas existe uma solução! A esperança ainda vive!$B$BAo norte daqui, nos campos dos mamutes, fronteira com os Poços Escaldantes, você encontrará Khu\'nok, o Beemote. Um mamute tão sábio quanto velho. Leve este mamute órfão e presenteie Khu\'nok. Ele saberá o que fazer.', 'Filhote Órfão de Mamute devolvido para Khu\'nok', '', '', '', '', 'Filhote Órfão de Mamute devolvido para Khu\'nok', '', '', '', 'Fale com Khu\'nok, o Beemote, na Tundra Boreana.', 0),
(11879, 'ptBR', 'Kaw, o Destruidor de Mamutes', 'Mate Kaw, o Destruidor de Mamutes e recupere a Alabarda de Guerra do Kaw. Entregue a Alabarda de guerra do Kaw para o Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana.', 'Você não derrotará $Gsozinho:sozinha; o responsável pela carnificina da minha espécie. Os mamutes da tundra $Go:a; ajudarão!$B$BAventure-se pelas planícies e encontre um mamute macho. Ele lhe permitirá montar e controlar seus movimentos e ações. Cavalgue-o e encontre Kaw a norte daqui, no Mirante de Kaw. Juntos vocês serão o instrumento que dará fim a Kaw.$B$BDestrua o exército dele e tome sua cobiçada alabarda de guerra. Fale novamente com o Arquidruida Lathorius no Acampamento da DruiPA, caso seja $Gbem-sucedido:bem-sucedida;.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11880, 'ptBR', 'Sondagem multifásica', 'O Precursor Haronem, em Shattrath, quer que você use os Óculos Espectrográficos Multifásicos para obter 6 Leituras Multifásicas.', 'Aquele "inventor gnômico" não passa de um doidivanas. Ele não parava de matraquear sobre distorções sombrias que começaram a aparecer nos Campos dos Espíritos perto de Oshu\'gun, em Nagrand.$B$BDe acordo com ele, os óculos... espectromultifásicos permitirão que o usuário veja as distorções e obtenha as leituras. Ficou dizendo que a gravação dos dados é fundamental para a nossa campanha na Nascente do Sol. Para mim ele é um lunático, mas tenho ordens para investigar qualquer coisa que possa ajudar. Gostarias de realizar algumas leituras, $n?', '', 'Leituras Multifásicas Obtidas', '', '', '', '', '', '', '', 'Fale novamente com o Precursor Haronem no Terraço da Luz, que fica em Shattrath.', 0),
(11881, 'ptBR', 'Carreguem-na!', 'Ajude a Geni a andar do local do acidente até Fazzix Girarroda na Aldeia Taunka\'le sem perder todo o carregamento.', 'Você já viu essas máquinas voadoras zanzando por aqui? Aquilo é inovação gnômica de ponta.$B$BFaz tempo que estou doido pra pôr as mãos nessa tecnologia e esta é a oportunidade perfeita! Uma tropa de naves de reconhecimento se espatifou nos Lagos Escaldantes, na região sudoeste dos Campos de Gêiser.$B$BSopre este apito perto de uma das máquinas destruídas e minha confiável mula, Geni, virá até você. Ela vai te seguir e carregar as peças, mas você precisa cuidar dela, porque ela vai deixar cair a carga se for atacada.', '', 'Traga a Geni de volta em segurança sem perder o carregamento.', '', '', '', '', '', '', '', 'Fale novamente com Fazzix Girarroda na Aldeia Taunka\'le, em Tundra Boreana.', 0),
(11882, 'ptBR', 'Brincando com fogo', 'Fale com um Mestre Engolidor de Fogo em qualquer capital da Aliança.', 'Estaria $Ginteressado:interessada; em desenvolver novas e empolgantes perícias?$b$bNão sei se você vai chegar ao meu nível, mas acho que dá para lhe ensinar um truque ou dois se você se esforçar.', '', '', '', '', '', '', '', '', '', '', 0),
(11883, 'ptBR', 'Dança do Fogo?', 'Fale com uma Mestre Dançarina do Fogo em qualquer capital da Horda.', 'Gostaria de aprender a arte da dança do fogo?$b$bPois bem. Fale com uma Mestre Dançarino do Fogo em qualquer capital da Horda.', '', '', '', '', '', '', '', '', '', '', 0),
(11884, 'ptBR', 'Nedar, o Senhor dos Rinocerontes...', 'Mortígero, o Vigia do Covil, no Acampamento da DruiPA, que fica na Tundra Boreana, quer que você mate Nedar, Senhor dos Rinocerontes, e sua mascote "Lancheira".', 'A oeste daqui, nos altos penhascos sobre o Lago Kum\'uya, vagueia um desprezível ser conhecido como Nedar, que se autoproclamou "Senhor dos Rinocerontes". Ele varre os campos à caça de rinocerontes jovens ou machucados, incapazes de se defender contra seus ataques covardes. Para piorar, Nedar criou um rinoceronte desde pequeno e o transformou em montaria e guarda-costas.$B$BÉ muito raro a DruiPA desejar a morte de um animal, mas esse rinoceronte desvirtuado precisa ser sacrificado... Mate ambos e volte a falar comigo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Mortígero, o Vigia do Covil, no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11885, 'ptBR', 'Sangue adversário', 'Encontre as Pilhas de Crânios no meio dos círculos de evocação em Skettis. Evoque e derrote cada um dos descendentes usando 10 Pergaminhos perdidos no tempo na Pilha de Crânios. Fale novamente com Hazzik no Campo de Pouso Ventonegro.', 'Os descendentes mantidos como prisioneiros pelos sacerdotes da garra de Skettis estão listados nesse livro: Gezzarak, a Caçadora; Karrog, o gigante de cristal; Vakkiz, o Arrojaventos; e o herege conhecido como Guinchonegro Akkarai. Todos eles precisam morrer antes do retorno de Terokk.$B$BVocê precisará dos pergaminhos carregados pelos arakkoas perdidos no tempo para evocá-los nos círculos de evocação em Skettis. Eles são inimigos poderosos, assim, é bom levar seus amigos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Hazzik. Você pode encontrá-lo no Campo de Pouso Ventonegro, que fica na Mata Terokkar.', 0),
(11886, 'ptBR', 'Atividade incomum', 'Vá para o novo Acampamento do Crepúsculo, ao sul da Entrada das Profundezas Negras, na Praia de Zoram – a qual fica no Vale Gris – e pegue a Correspondência do Crepúsculo dos sectários. Depois, convoque o Guia da Harmonia Telúrica usando a Lanterna Totêmica.', 'Enquanto alguns estão celebrando, $c, alguns de nós precisam dar atenção a assuntos mais graves.$b$bQuando o festival começou, recebemos informações da Praia de Zoram sobre um aumento crítico nas atividades do Culto do Crepúsculo. As origens desse feriado estão calcadas nos mesmos poderes que esses loucos reverenciam. Isso não pode ser só coincidência. Vá para o acampamento ao sul da Entrada das Profundezas Negras, nas ruínas, e veja se os sectários te darão alguma informação sobre isso. Use força se for necessário. Use essa lanterna para evocar um guia quando encontrar alguma coisa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guia da Harmonia Telúrica.', 0),
(11887, 'ptBR', 'Equipamentos de emergência', 'Consiga 7 Equipamentos de Emergência Gnômicos dos corpos dos Pilotos de Reconhecimento do Biela e leve-os para Fazzix Girarroda na Aldeia Taunka\'le.', 'Revistando rapidamente o corpo do gnomo morto, você encontra um pequeno embrulho contendo provisões, ferramentas e um pequeno rolo de fita isolante gnômica. O conteúdo desse estojo deve ser útil para Fazzix Girarroda para quando ele for tentar remontar os destroços das máquinas gnômicas voadoras.$B$BEsses estojos serão de grande ajuda para Fazzix.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fazzix Girarroda na Aldeia Taunka\'le, em Tundra Boreana.', 0),
(11888, 'ptBR', 'Viagem à Aldeia Taunka\'le', 'Fale com o Sábio Terra e Céu na Aldeia Taunka\'le.', '$R, o chefe está me fazendo esperar... tempo que os Taunka\'le não têm!$B$BTodos estão falando de sua bravura. Em vez de esperar Garrosh nos enviar ajuda, peço-lhe para que ajude meu povo.$B$BA aldeia Taunka\'le fica longe, a nordeste daqui. Siga a estrada leste que sai do forte e vá para o norte ao chegar à interseção. Logo em seguida, encontrará outra encruzilhada. Siga para leste e até o fim das planícies inundadas.$B$BFale com o Sábio Terra e Céu quando chegar lá.', '', '', '', '', '', '', '', '', '', '', 0),
(11889, 'ptBR', 'A morte vem de cima', 'Sargento Martelmonte quer que você use a Rede Reforçada para aprisionar e matar 6 Cospe-chamas Flagelados, fora da Bastilha Valentia.', 'Estamos fazendo um bom trabalho, segurando a linha de frente contra esses insetos. Infelizmente alguns desses insolentes conseguem voar por cima de nós. Estão acabando com nossas defesas internas!$B$BEncomendei algumas redes de pesca reforçadas, diretamente dos nossos navios pesqueiros. Acha que tem um braço forte a ponto de conseguir derrubar alguns deles com as redes? Então acabe com esses diabos, para que nossa defesa possa cuidar da fortaleza.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Martelmonte na Bastilha Valentia, na Tundra Boreana.', 0),
(11890, 'ptBR', 'O que estão tramando?', 'Investigue a área nos arredores da Estação Bombeadora do Biela. Depois, fale novamente com o Sábio Terra e Céu, na Aldeia Taunka\'le.', 'Os gnomos tiveram algum contratempo nos poços a oeste. Um castigo merecido por violarem a terra com aquilo que chamam de invenções.$B$BQuero que você vá à estação bombeadora deles e observe o que ocorreu. Depois volte aqui.', 'Arredores da Estação Bombeadora do Biela inspecionados.', '', '', '', '', 'Arredores da Estação Bombeadora do Biela inspecionados.', '', '', '', 'Fale novamente com o Sábio Terra e Céu na Aldeia Taunka\'le, que fica na Tundra Boreana.', 0),
(11891, 'ptBR', 'Um disfarce inocente', 'Use o Orbe do Caranguejo para espionar o novo Acampamento do Crepúsculo a oeste da Entrada das Profundezas Negras na Praia de Zoram do Vale Gris. Depois, evoque o Guia da Harmonia Telúrica usando a Lanterna Totêmica.', 'De acordo com essas informações, parece haver um outro acampamento de sectários a noroeste do grande grupo na Praia de Zoram, e eles estão conversando com... convidados?$b$bPodemos descobrir muito ao ouvir essas conversas, $r. Pegue esse orbe. Ele fará com que você se pareça com um dos caranguejos nativos da praia. Escute essa conversa entre os sectários e seus "convidados" no acampamento a noroeste e fale novamente comigo quando tiver conseguido.', 'Ouça o plano dos Sectários do Crepúsculo', '', '', '', '', 'Ouça o plano dos Sectários do Crepúsculo', '', '', '', 'Fale novamente com o Guia da Harmonia Telúrica.', 0),
(11892, 'ptBR', 'O assassinato de Manuelzão', 'Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana, quer que você mate Manuelzão.', 'Você fez muito pelos animais da Tundra Boreana, $n. Os lacaios de Rosarães levaram uma surra e aprenderam uma lição que não vão esquecer tão cedo.$B$BManuelzão, o principal responsável pela chacina em Nagrand, foi identificado como mandante das operações de Rosarães na tundra. Ele se encontra no Lago Kum\'uya, a oeste daqui.$B$B<Lathorius lhe entrega uma trompa de carvalho complexamente entalhada.>$B$BEncontre-o e mate-o. Use essa trompa, caso necessite de ajuda.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Arquidruida Lathorius no Acampamento da DruiPA, que fica na Tundra Boreana.', 0),
(11893, 'ptBR', 'O poder dos elementos', 'Dorain Casco Gélido, na Aldeia Taunka\'le, quer que você use o Totem Almeólico para obter a energia de 10 Coléricos Vaporíferos.', 'Vivo dizendo àquele goblin tolo que suas máquinas não são confiáveis.$B$BJá o poder dos elementos é profundo e duradouro. Quando meu aprendizado chegar ao fim, terei controle de todo esse poder. Talvez eu consiga ajudar nosso amigo Fazzix com o que eu já sei.$B$BLeve este totem almeólico e ponha-o perto de qualquer colérico vaporífero, a oeste da aldeia. O totem coletará a energia dos elementais mortos. Traga o totem completamente energizado para mim, e eu farei o resto.', '', 'Energia coletada', '', '', '', '', '', '', '', 'Fale novamente com Dorain Casco Gélido na Aldeia Taunka\'le, que fica na Tundra Boreana.', 0),
(11894, 'ptBR', 'Remendando', 'Fazzix Girarroda, na Aldeia Taunka\'le, quer que você lhe traga 5 Pelegos Curtidos no Vapor.', 'Lembra de toda aquela fita isolante gnômica que você me trouxe?$B$BBem, descobri o que fazer com ela. A estrutura dessa máquina voadora tá caindo aos pedaços, então vou ter que reforçá-la se quiser que volte a voar um dia.$B$BDorain estava me contando que os taunkas usam couro de caribu curtido pra fazer recipientes à prova d\'água. Caribus do pântano vivem por toda parte da aldeia e nas Planícies Inundadas ao sul. Consiga os melhores couros que achar e use as saídas de vapor nos Campos de Gêiser para curti-los.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fazzix Girarroda na Aldeia Taunka\'le, em Tundra Boreana.', 0),
(11895, 'ptBR', 'Mestre da tormenta', 'Derrote a Tormenta da Tempestade e fale com o Sábio Terra e Céu na Aldeia Taunka\'le.', 'Pelo que você me descreveu, as criaturas de metal devem ser fáceis de lidar. Mas primeiro, você precisa dominar a tormenta.$B$BAtrás de mim, no chalé, existe um totem. Quando estiver $Gpreparado:preparada;, concentre sua força de vontade sobre ele e a tormenta virá. Derrote-a e traga a essência do elemental para dentro de você.$B$BSe estiver $Gacompanhado:acompanhada; de outros, todos vocês poderão trabalhar juntos para derrotá-la. Fale comigo quando tiver terminado.', '', 'Tormenta dominada', '', '', '', '', '', '', '', 'Fale novamente com o Sábio Terra e Céu na Aldeia Taunka\'le, que fica na Tundra Boreana.', 0),
(11896, 'ptBR', 'Suscetível à eletricidade', 'Destrua 15 Unidades Robóticas, exceto gnomecânicos enquanto estiverem enfraquecidos pelo poder da tormenta nos arredores dos grandes poços, na Estação Bombeadora do Biela.$B$BDepois, fale novamente com o Sábio Terra e Céu na Aldeia Taunka\'le.', 'Agora você possui a força da tormenta dentro de você. Vou lhe ensinar a canalizar tal poder para enfraquecer os robôs nos poços.$B$BPegue este para-raios. Use-o contra as criações robóticas dos gnomecânicos que encontrar nos arredores dos grandes poços a oeste. Não se preocupe em usar o bastão contra os gnomecânicos, pois a Grande Mãe Taiga tem outros planos para eles.$B$BAssim que os robôs estiverem enfraquecidos pelo poder da tormenta, desmonte-os por completo!', '', 'Robôs enfraquecidos e destruídos', '', '', '', '', '', '', '', 'Fale novamente com o Sábio Terra e Céu na Aldeia Taunka\'le, que fica na Tundra Boreana.', 0),
(11897, 'ptBR', 'Tampem as fossas', 'Sargento Martelmonte quer que você use os Explosivos Incendiários para fazer ruir as fossas a sudoeste e a noroeste da Bastilha Valentia.', 'Parece que o Flagelo não descansa, $n. Culpa daquelas malditas fossas! Elas se conectam a túneis que vêm desde a Coroa de Gelo até aqui, criados por minhocas zumbis gigantes que escavam o solo abaixo.$B$BSe tem uma coisa que aprendi com anos de mineração é que, sem vigas de sustentação, um túnel inteiro desmorona após uma explosão.$B$BPegue estes explosivos e ponha-os na entrada das fossas, na cordilheira depois da praia a oeste. Volte depois que você os demolir.', '', 'Explosivos posicionados na fossa sul', 'Explosivos posicionados na fossa norte', '', '', '', '', '', '', 'Fale novamente com o Sargento Martelmonte na Bastilha Valentia, na Tundra Boreana.', 0),
(11898, 'ptBR', 'Abrindo caminho', 'Derrote o Príncipe Valanar e seus tenentes Vanthryn, o Impiedoso, e Luthion, o Torpe, e então apresente-se ao Chefe Vento de Inverno na Aldeia Taunka\'le.', 'Na camada mais baixa da Cidade-templo existe um antigo altar banhado em luz. Suba nele para conseguir acesso à terrível necrópole Naxxanar.$B$BTome cuidado, $n. Os leais seguidores do príncipe Valanar certamente o defenderão com a vida, e tentarão impedir que você chegue ao nível mais alto da necrópole.$B$BVocê precisa chegar ao trono do príncipe. Se falhar em derrotá-lo, $n, temo que meu povo nunca chegue a conhecer a segurança que a Bruma Boreal pode oferecer.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Chefe Vento de Inverno na Aldeia Taunka\'le, na Tundra Boreana.', 0),
(11899, 'ptBR', 'O desalmar dos desalmados', 'Use O Apanhador de Almas da Grande Mãe para capturar as almas de 10 gnomecânicos do Biela. Depois, fale novamente com a Grande Mãe Taiga na Aldeia Taunka\'le.', 'Os gnomecânicos nos poços a oeste daqui são um grande mistério para nós. Eles surgiram logo depois dos gnomos desaparecerem da estação bombeadora e arredores.$B$BEles são um perigo desnaturado e devemos acabar com eles.$B$BPegue este apanhador de almas e use-o nos restos do gnomecânicos para capturar suas almas. Quando você voltar, iremos libertá-los para que possamos descobrir o que aconteceu.', '', 'Alma de gnomo capturada', '', '', '', '', '', '', '', 'Fale novamente com a Grande Mãe Taiga na Aldeia Taunka\'le, que fica na Tundra Boreana.', 0),
(11900, 'ptBR', 'Leitura dos medidores', 'Arquimago Berinand, no Escudo de Transitus, pediu que você faça as leituras dos instrumentos dele em Gelarra.', 'Eu esperava que o efeito do impacto do Nexus tivesse se restringido a essa região. Entretanto, relatos recentes de toda Azeroth nos inundam, dizendo que a instabilidade geológica está crescendo exponencialmente!$b$bPreciso monitorar o Nexus regularmente enquanto trabalho para encontrar uma solução.$b$bEu pus sensores ao redor de Gelarra, disfarçados de orbes de vidência do Malygos. Um deles está em uma trincheira próxima ao Nexus, e três outros estão escondidos em estruturas no perímetro do vale. Visite cada um deles e volte com as leituras.', '', 'Leitura Geológica do Nexus', 'Leitura Geológica do sul', 'Leitura Geológica do norte', 'Leitura Geológica do oeste', '', '', '', '', 'Fale novamente com o Arquimago Berinand no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11901, 'ptBR', 'Militar? Que militar?', 'Geraldo Delleprane, em Algures, quer que você vá até a mina ao norte e descubra o que aconteceu com a guarnição militar que foi para lá.', 'Tem Flagelo pra tudo quanto é lado, $c. Organizamos os fazendeiros e mineradores em uma milícia, mas isso não basta.$B$BA guarnição que a Bastilha Valentia nos mandou está defendendo as minas. Não recebemos notícias deles há dias!$B$BSe realmente quer nos ajudar, por que não vai até lá e descobre o que tá acontecendo? Pode ser que eles nos enviem reforços.', '', '', '', '', '', '', '', '', '', '', 0),
(11902, 'ptBR', 'Evidência nociva', 'Fale novamente com Geraldo Delleprane, em Algures.', 'Os sacos de grãos emanam um fedor pútrido que você sabe ser característico da Peste. Isto provavelmente explica o que aconteceu aos soldados que defendiam a mina.$B$BÉ melhor levar esta notícia para Geraldo Delleprane.', '', '', '', '', '', '', '', '', '', '', 0),
(11903, 'ptBR', 'Hora de agir', 'Geraldo Delleprane, em Algures, quer que você mate 14 Catadores Pestilentos.', 'Muito bem, $n. Com a morte dos nossos últimos militares em Algures, nada mais nos resta a não ser lutar contra o Flagelo.$B$BTemos uma milícia situada no que restou de Algures. Sem sua ajuda, eles não terão chance alguma de vencer. Vá até lá e dê uma mãozinha. Eu e meus companheiros vamos guardar este caminho. Não podemos permitir que o Flagelo passe por nós!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Geraldo Delleprane em Algures, que fica na Tundra Boreana.', 0),
(11904, 'ptBR', 'Frutos dos nossos esforços', 'Vá até a mina em Algures, consiga a Chave de Liberação do Vagão do Capitão Jácobo e use-a para soltar o vagonete de minério. Fale com Geraldo Delleprane, em Algures, quando tiver completado esta tarefa.', 'O Flagelo continua avançando... mas não podemos desistir! Dentro daquela mina tem um vagonete com o último minério que a Aliança verá deste lado do continente por um bom tempo.$B$BO problema é que o vagonete está travado. Quando os militares foram lá, o capitão Jácobo confiscou todo o equipamento importante, incluindo a chave que libera o vagão.$B$BA peste que assolou os soldados na mina deve ter afetado Jácobo também. Pegue a chave dele e recupere o minério.', '', 'Vagonete de Minério liberado', '', '', '', '', '', '', '', 'Fale novamente com Geraldo Delleprane em Algures, na Tundra Boreana.', 0),
(11905, 'ptBR', 'Adiando o inevitável', 'A imagem da Maga-de-guerra Kaitlyn, no Nexus, quer que você use o Reconstituidor Interdimensional perto da fissura.', 'As linhas de meridiano de Azeroth estão sendo redirecionadas para o Nexus.$B$BO influxo de energias arcanas está abrindo uma fissura interdimensional.$b$bNão posso evitar isso, mas descobri uma maneira de atrasá-lo.$b$BLeve isto e ative perto da fissura que está se formando.', '', 'Fissura Interdimensional interrompida', '', '', '', '', '', '', '', 'Fale novamente com a Imagem da Maga-de-guerra Kaitlyn no Nexus.', 0),
(11906, 'ptBR', 'Limpando os poços', 'Colete 15 Peças Sobressalentes do Biela e entregue-as para Olhos de Ferro na Aldeia Taunka\'le.', '<Uma única lágrima cai do rosto de Olhos de Ferro.>$B$BOuvi dizer que você está voltando para os poços do oeste. Tem algo que preciso que você faça por mim enquanto estiver lá, $r. Os gnomos, que não se importam com a terra, poluíram tudo com suas máquinas. Quero que você pegue as peças soltas que encontrar por lá.$B$BTraga-as para mim. Assegurarei que tudo seja jogado fora antes de deixarmos este lugar para sempre.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Olhos de Ferro na Aldeia Taunka\'le, que fica na Tundra Boreana.', 0),
(11907, 'ptBR', 'Os subchefes', 'Derrote Clanq, ED-210, Max Blasto e O Triturador. Depois, fale com o Sábio Terra e Céu na Aldeia Taunka\'le.', 'É sabido que o Engrenochefe Mecanozod possui quatro subchefes que controlam os robôs nos poços.$B$BTemos que dar um fim a eles!$B$BNossos pisaléguas e rastreadores da neve dizem que, se girarmos as válvulas nas estações oeste, norte, central e sul, cada subchefe virá rapidamente, tentando impedir que você atrapalhe as operações deles.$B$BAs estações têm luzes rodopiantes, nos poços próximos à estação bombeadora.$B$BRápido, $n!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sábio Terra e Céu na Aldeia Taunka\'le, que fica na Tundra Boreana.', 0),
(11908, 'ptBR', 'Material de referência', 'Jeremias Ranieri quer que você recupere o livro "Campos, Fábricas e Oficinas" da construção em chamas perto da mina em Algures.', 'Era eu quem cuidava dos golens colheiteiros... um trabalho importante até que o Flagelo destruiu a maior parte das nossas fazendas. Tenho uma ideia do que fazer para que os golens voltem a ser úteis.$B$BAcho que consigo religar os colheiteiros para que nos ajudem a lutar contra o Flagelo.$B$BNão sou nenhum perito nisso, então vou precisar do meu manual. O problema é que eu esqueci ele na oficina... que por acaso é a construção em chamas perto da mina. Acha que consegue ir lá pegá-lo?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Jeremias Ranieri em Algures, na Tundra Boreana.', 0),
(11909, 'ptBR', 'Derrote o engrenochefe', 'Investigue o Manual do Engrenochefe e traga a Cabeça do Mecanozod para a Grande Mãe Taiga na Aldeia Taunka\'le.', 'O Engrenochefe Mecanozod é completamente insano. Se sua oferta de cura e imortalidade implica em virarmos escravos robóticos, então precisamos detê-lo!$B$BOs ventos que me guiam sussurram que ele se encontra no topo da estação bombeadora, bem no meio dos poços a oeste daqui.$B$BProvavelmente ele deve estar na cabana de comando acima da estrutura. Vá e vasculhe a cabana.$B$B$n, você precisa confrontar Mecanozod se quisermos sobreviver!', '', 'Manual do Engrenochefe investigado', '', '', '', '', '', '', '', 'Fale novamente com a Grande Mãe Taiga na Aldeia Taunka\'le, que fica na Tundra Boreana.', 0),
(11910, 'ptBR', 'Segredo dos Ancientes', 'O Arquimago Berinand, no Escudo de Transitus, quer que você consiga 3 Estilhaços Glaciais e 3 Estilhaços Embruxados dos Ancientes em Gelarra.', 'Agora está claro que a instabilidade na região casou efeitos nas criaturas nativas.$b$bTenho observado com interesse os ancientes glaciais e suas recentes adaptações. Suspeito que suas transformações em ancientes "embruxados" tenha pistas sobre a situação que enfrentamos aqui.$b$bPara continuar meus estudos, precisarei de amostras de ambos. Por favor, apresse-se...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Arquimago Berinand no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11911, 'ptBR', 'A metamorfose', 'A Imagem da Maga-de-guerra Kaitlyn, no Nexus, quer que você colete 5 Estilhaços Arcanos dos Protetores Cristalinos.', 'Aprendi mais em minha curta estadia aqui do que em décadas de estudos.$b$bEsses ancientes estão sendo expostos a incríveis níveis de energia arcana, o que está transformando-os literalmente em algo... diferente.$b$bEstou certa de que existe um estágio final na metamorfose deles. Encontre alguma prova do estado final deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Imagem da Maga-de-guerra Kaitlyn no Nexus.', 0),
(11912, 'ptBR', 'Loucos por frutinhas', 'A Bibliotecária Serrah, no Escudo de Transitus, quer que você colha 10 Frutagelos dos Arbustos de Frutagelo em Gelarra.', 'Oh! Que alívio ver um rosto novo por aqui. Já estava achando que tínhamos sido abandonados.$B$BNossas linhas de abastecimento foram cortadas dias atrás e as coisas começaram a ficar preocupantes. Para ser sincera, começo a achar que nossa missão aqui é suicida.$B$BTalvez eu não tenha nascido para lidar com tanta violência – sem mencionar o frio cortante! Preferia mil vezes estar em Dalaran estudando textos antigos.$B$BMas, pra ir direto ao ponto – nosso estoque de comida está no fim. Por favor, colha o que puder e traga pra mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Bibliotecária Serrah no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11913, 'ptBR', 'Sem arriscar', 'Vanda Rúbia quer que você use a Tocha da Vanda para queimar 8 sacos de Grão de Algures.', 'Ouvi o que você disse para o Delleprane e não estou gostando nada disso. Se os sectários conseguiram envenenar os grãos nas minas com aquela maldita peste, então podem muito bem ter feito o mesmo com os grãos daqui de fora.$B$BNão temos tempo para separar o joio do trigo. Temos que agir rápido e queimar tudo.$B$BPegue esta tocha e taque fogo em todos os sacos de grãos que encontrar por aqui. Seria uma tragédia se, depois de sobrevivermos a esse ataque, morrêssemos por causa da peste.', '', 'Grão de Algures queimado', '', '', '', '', '', '', '', 'Fale com Vanda Rúbia em Algures, na Tundra Boreana.', 0),
(11914, 'ptBR', 'Mantenha o segredo a salvo', 'A Bibliotecária Serrah, no Escudo de Transitus, precisa que você mate Serpentes Arcanas perto do Nexus e consiga 5 Essências de Mana do Nexus delas.', 'Nossa existência aqui depende inteiramente de nos mantermos escondidos. Se o escudo cair, mesmo que por um segundo, os servos de Malygos nos dominarão.$b$bUma das minhas responsabilidades é reabastecer os níveis de mana dos magos-de-guerra para que não falhem em sua concentração. Como perdemos nossa linha de abastecimento, fui forçada a improvisar.$b$bVocê pode me ajudar, $n.$b$bBem perto do Nexus, Serpentes Arcanas se alimentam da abundante energia mágica. Uma vez derrotadas, elas produzem uma essência de mana que pode ser útil.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Bibliotecária Serrah no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11915, 'ptBR', 'Brincando com fogo', 'Fale com um Mestre Engolidor de Chamas em qualquer capital da Horda.', 'Estaria $Ginteressado:interessada; em desenvolver novas e empolgantes perícias?$b$bNão sei se você vai chegar ao meu nível, mas acho que dá para lhe ensinar um truque ou dois se você se esforçar.', '', '', '', '', '', '', '', '', '', '', 0),
(11916, 'ptBR', 'Campeão do Grito Infernal', 'Encontre o Chefe Vento de Inverno na Aldeia Taunka\'le.', 'Você encarou todos os desafios que lhe propusemos e esmagou cada um deles com os calcanhares. Graças a você, $n, a Horda está firmemente entrincheirada em Nortúndria.$B$BMas nosso trabalho apenas começou. Precisamos marchar até a Coroa de Gelo e derrubar os muros de lá!$B$BSua próxima missão começa a leste, na Aldeia Taunka\'le. Nossos aliados taunkas estão com terríveis dificuldades e precisam de ajuda. Consiga um transporte com o mestre de estábulo Durkot Irmão do Lobo e encontre o Chefe Vento de Inverno em Taunka\'le.', '', '', '', '', '', '', '', '', '', '', 0),
(11917, 'ptBR', 'Contra-ataque', 'Mate o Tenente Frentálgida evocado pela Pedra de Gelo, localizada na Praia de Zoram no Vale Gris. Depois, retorne ao Ancião da Harmonia Telúrica em uma capital.', 'Nós precisamos proteger o equilíbrio! Estamos correndo contra o tempo.$b$bVolte ao acampamento na Praia de Zoram. Lá, você encontrará grandes pedras de gelo que são usadas pelos sectários como um meio de comunicação com os elementais, assim como é feito em Silithus. Por mais que eu odeie essa ideia, espero que os espíritos entendam. Você deve evocar um dos tenentes de Ahune e destruí-lo. Com sorte, isso irá atrasá-los o suficiente...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião da Harmonia Telúrica.', 0),
(11918, 'ptBR', 'Treinamento básico', 'Raelorasz, no Escudo de Transitus, quer que você mate 10 Tecencantos de Gelarra.', 'Estamos em guerra, mortal, e somos apenas a ponta da lança.$b$bSuas pequenas intrigas por terras e dinheiro ofuscam-se diante de tal conflito. Enfrentamos o aspecto Malygos e toda sua revoada dragônica azul. Sabe que, caso ele vença, este mundo não mais existirá.$b$bSomos poucos voando contra muitos. Nossas mortes nada mais são que uma certeza e todo o nosso sucesso depende simplesmente de atrasarmos nosso inimigo.$b$bAgora vá. Mantenha-se ocupad$go:a; enquanto decido o que fazer de você.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Raelorasz no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11919, 'ptBR', 'Caçada dracônica', 'Raelorasz quer que você use a Lança de Raelorasz para dominar um Filhote de Draco do Nexus e trazê-lo até ele, no Escudo de Transitus.', 'Os azuis começaram a cobrir seus próprios dracos com runas misteriosas. Preciso descobrir o significado delas.$b$b<Raelorasz fura sua mão com uma lança e cobre sua ponta com sangue.>$b$bLeve isto e use em um dos dracos. Espere até que estejam subjugados, então traga-os para mim antes que se soltem.$b$bSeus filhotes se alimentam na margem noroeste do vale.', '', 'Draco do Nexus capturado', '', '', '', '', '', '', '', 'Fale novamente com Raelorasz no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11920, 'ptBR', 'Sectários entre nós', 'Fale com Capitão "Canhoto" Velabaixa acima do Rompe-procelas, na Bastilha Valentia.', 'Este altar está repleto de escrituras da Seita dos Malditos. Ao que parece, fanáticos dos outros continentes chegaram a Nortúndria. Seria prudente notificar o capitão da embarcação.$B$BTalvez ele esteja lá em cima.', '', '', '', '', '', '', '', '', '', '', 0),
(11921, 'ptBR', 'Mais arremessos de tochas', 'Vença o jogo de arremessar as tochas e então fale com o Mestre Engolidor de Fogo.', 'Olá, $Glançador:lançadora; de tochas! Está se divertindo botando fogo em tudo? É assim que eu gosto! Agora, você acha que já é profissional no arremesso de tochas? Se sim, tenho um teste para você...$B$BVocê já sabe as regras: arremesse as tochas nos braseiros marcados. Desta vez, você terá um pouco mais de tempo e muito mais braseiros para acertar.$B$B$GPronto:Pronta;?', 'Acerte 20 braseiros.', '', '', '', '', 'Acerte 20 braseiros.', '', '', '', 'Fale novamente com o Mestre Engolidor de Fogo.', 0),
(11922, 'ptBR', 'Arremesso de tochas', 'Vença o jogo de arremessar tochas e então fale com o Mestre Engolidor de Chamas.', 'Então você quer ser piromalabarista? Será que você dá conta do recado? Tem a destreza, os reflexos necessários? E a coragem? Bom, se você acha que sim, é hora de começar a praticar!$B$BPegue estas tochas e vá para perto da fogueira. Você verá alguns braseiros com marcas brilhantes em cima. Basta jogar a tocha no braseiro marcado antes que a marca desapareça! Tem que ser rápido!$B$BAcerte oito braseiros antes que o tempo acabe e então volte aqui... para a próxima aula.', 'Acerte 8 braseiros.', '', '', '', '', 'Acerte 8 braseiros.', '', '', '', 'Fale novamente com o Mestre Engolidor de Chamas.', 0),
(11923, 'ptBR', 'Piromalabarismo', 'Pegue 4 tochas seguidas e então fale com o Mestre Engolidor de Chamas.', 'Agora que você já sabe como lançar uma tocha, será que consegue pegá-la no ar?$B$BLeve estas tochas para perto da fogueira. Então, jogue uma para cima, pegue-a antes que caia no chão e... jogue-a para cima outra vez! Jogue e pegue a mesma tocha quatro vezes e depois volte aqui.$B$BTome cuidado! As tochas podem ser perigosas, se caírem no chão! Então, não as deixe cair! Se não conseguir pegar, você terá que voltar até a fogueira e começar de novo. Boa sorte!', 'Pegue 4 tochas seguidas.', '', '', '', '', 'Pegue 4 tochas seguidas.', '', '', '', 'Fale novamente com o Mestre Engolidor de Chamas.', 0),
(11924, 'ptBR', 'Mais piromalabarismo', 'Pegue 10 tochas seguidas e então fale com o Mestre Engolidor de Fogo.', 'O piromalabarismo exige alta concentração. Quanto tempo será que você consegue manter as tochas no ar?$B$BVamos ver...', 'Pegue 10 tochas seguidas.', '', '', '', '', 'Pegue 10 tochas seguidas.', '', '', '', 'Fale novamente com o Mestre Engolidor de Fogo.', 0),
(11925, 'ptBR', 'Mais piromalabarismo', 'Pegue 10 tochas seguidas e então fale com o Mestre Engolidor de Chamas.', 'O piromalabarismo exige alta concentração. Quanto tempo será que você consegue manter as tochas no ar?$B$BVamos ver...', 'Pegue 10 tochas seguidas.', '', '', '', '', 'Pegue 10 tochas seguidas.', '', '', '', 'Fale novamente com o Mestre Engolidor de Chamas.', 0),
(11926, 'ptBR', 'Mais arremessos de tochas', 'Vença o jogo de arremessar tochas e então fale com o Mestre Engolidor de Chamas.', 'Olá, $Glançador:lançadora; de tochas! Está se divertindo botando fogo em tudo? É assim que eu gosto! Agora, você acha que já é profissional no arremesso de tochas? Se sim, tenho um teste para você...$B$BVocê já sabe as regras: arremesse as tochas nos braseiros marcados. Desta vez, você terá um pouco mais de tempo e muito mais braseiros para acertar.$B$B$GPronto:Pronta;?', 'Acerte 20 braseiros.', '', '', '', '', 'Acerte 20 braseiros.', '', '', '', 'Fale novamente com o Mestre Engolidor de Chamas.', 0),
(11927, 'ptBR', 'Boato das ruas', 'Encontre Leryssa na Bastilha Valentia.', 'Ei, $n. Tem uma garota na estalagem que está perguntando por você. O nome dela é Leryssa.$B$BNão acho que ela te conheça, mas disse que precisa da tua ajuda. Parecia bastante urgente.', '', '', '', '', '', '', '', '', '', '', 0),
(11928, 'ptBR', 'Algures', 'Vá para Algures, na Tundra Boreana, e fale com Geraldo Delleprane.', 'Meus companheiros darão conta a partir daqui, $n. A Bastilha Valentia foi criada pra aguentar uma surra bem pior do que essa. O que me preocupa são nossos campos e a mina de Algures.$B$BMandamos uma guarnição inteira proteger a mineração logo antes da invasão. Acho que conseguirão defender os civis.$B$BGeraldo Delleprane é o responsável pelos aldeões lá. Existe uma saída no muro norte da Bastilha Valentia que leva direto a ele. Veja o que pode fazer para ajudá-los.', '', '', '', '', '', '', '', '', '', '', 0),
(11929, 'ptBR', 'A queda da Aldeia Taunka\'le', 'Fale com Mãe Tauranuk do lado de fora dos portões da Aldeia Taunka\'le.', 'Estamos perdidos, $n. Esta terra, lar de muitas gerações nossas, não está mais segura. Restou apenas morte... Morte e lembrança de como já foi um dia.$B$BEu mesmo ordenei a evacuação dos Taunka\'le. Todos os taunkas remanescentes devem partir imediatamente para nossa capital, Bruma Boreal, localizada no Ermo das Serpes.$B$B<Vento do Inverno aponta para o leste.>$B$BVocê precisa levar meu povo para a nossa segurança, $n. A Mãe Tauranuk $go:a; aguarda nos portões da aldeia. Depressa! O Flagelo nos cerca por todos os lados!', '', '', '', '', '', '', '', '', '', '', 0),
(11930, 'ptBR', 'Além de Transbórea', 'Escolte os Retirantes de Taunka\'le através da Transbórea até Guerratuk Gelonato, na fronteira com o Ermo das Serpes.', 'O caminho através de Transbórea, ao leste, é a única forma de chegar ao Ermo das Serpes. Muitos riscos $go:a; aguardam em sua jornada nesta tundra. Tome cuidado com o Flagelo e sua influência sobre as feras desta terra. Há rumores dizendo que nossos irmãos e irmãs taunka voltaram dos mortos e estão atacando as caravanas que se dirigem ao Ermo das Serpes. Proteja a caravana e leve os retirantes para um lugar seguro!$B$BGuerratuk Gelonato $go:a; espera depois da ponte que leva ao Ermo das Serpes.', 'Proteja a passagem para o Ermo das Serpes', '', '', '', '', 'Proteja a passagem para o Ermo das Serpes', '', '', '', 'Fale com Guerratuk Gelonato no Ermo das Serpes.', 0),
(11931, 'ptBR', 'Quebrando o código', 'Raelorasz, no Escudo de Transitus, quer que você pegue o Códice Lazúli do Inquisidor Caleras e consiga 3 Runas Cintilantes dos Mesmerizadores de Gelarra.', 'Sinto certa peculiaridade nos dracos daqui, mas o significado das runas que cobrem seus corpos ainda me escapam o conhecimento.$b$bSem o códice, demoraremos mais tempo do que temos para interpretá-las.$b$bNão distante daqui, existe um traidor do Kirin Tor, Caleras, o mais propenso a ter uma cópia do tomo de que preciso. Seus subalternos possuem as runas necessárias para minha tradução.$b$bApresse-se, mortal. Malygos se fortalece a cada segundo que perdemos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Raelorasz no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11932, 'ptBR', 'Covardes e tolos', 'Fale com Ataika em Kaskala, a nordeste da Bastilha Valentia.', 'Olha, $n. Não se ofenda, sim? Mas a operação que eles mandaram o Thassarian comandar era suicídio em massa.$B$BMandaram um monte de homens atacar a maior concentração do Flagelo desta região. Podem me chamar de louco, mas invadir um zigurate do Flagelo do lado de fora de uma cidade nerubiana com uns dez soldados não é o que eu chamaria de divertido.$B$BSe ainda quer encontrar o Thassarian, procure um morsano chamado Ataika na cidade de Kaskala, a nordeste daqui. Boa sorte nessa missão insana.', '', '', '', '', '', '', '', '', '', '', 0),
(11933, 'ptBR', 'Roubando a chama da Exodar', 'Entregue a Chama da Exodar para o Contador de Histórias do Festival.', 'Esta chama, roubada do coração da Exodar, enche você de calor e entusiasmo. Este poder em estado bruto lhe é estranho, mas talvez o contador de histórias saiba mais a respeito...', '', '', '', '', '', '', '', '', '', 'Fale novamente com um Contador de Histórias do Festival.', 0),
(11935, 'ptBR', 'Roubando a chama de Luaprata', 'Entregue a Chama de Luaprata para o Historiador do Festival.', 'A chama, roubada do coração de Luaprata, enche você de calor e entusiasmo. Este poder em estado bruto lhe é estranho, mas talvez o historiador saiba mais a respeito...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Historiador do Festival.', 0),
(11936, 'ptBR', 'Chocando um plano', 'Raelorasz, no Escudo de Transitus, quer que você mate Draconoides de Gelarra e use seus machados de gelo para quebrar 5 ovos de dragão azul.', 'Nossos objetivos aqui são simples. Devemos permanecer escondidos de Malygos, observar a ninhada e impedir seus esforços onde quer que estejam. Com esta finalidade, tenho uma tarefa para você.$b$bOs azuis estão pondo ovos na base do Nexus. Uma exposição a tamanha energia arcana sem dúvida os fará nascer mais cedo. Não é possível prevermos os efeitos que isto causará à ninhada.$b$bE realmente não pretendo descobrir. Mate os draconoides locais e use os machados de gelo deles para quebrar os ovos.', '', 'Ovos de Dragão destruídos', '', '', '', '', '', '', '', 'Fale novamente com Raelorasz no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11937, 'ptBR', 'FLAG - all torch return quests are complete', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(11938, 'ptBR', 'Conseguindo mais tempo', 'Thassarian no Zigurate dos Lamentos, na Tundra Boreana, quer que você cause 20 baixas contra os membros do Flagelo, dentro da Cidade-Templo de En\'kilah. Use os Ossos de Lúrido, caso precise de ajuda.', 'Agora que conseguimos o filactério, não terei problemas em conseguir a informação de que preciso. Entretanto, não demorará muito para que os membros do Flagelo da Cidade-templo percebam que algo está acontecendo.$B$BNão conseguirei deter um ataque em massa aqui. Bem, talvez eu até conseguisse, mas prefiro não ter que descobrir.$B$BQuero que você vá lá embaixo e cause algumas baixas. Com sorte, eles vão ficar ocupados por tempo suficiente para que esses dois vomitem o que sabem... figurativamente falando, claro. Leve Lúrido com você. Ele pode ser de alguma ajuda.', '', 'Baixas em En\'kilah', '', '', '', '', '', '', '', 'Fale novamente com Thassarian no Zigurate dos Lamentos, na Tundra Boreana.', 0),
(11940, 'ptBR', 'Caçada dracônica', 'Raelorasz quer que você use a Lança com Ponta de Sangue para dominar um Filhote de Draco do Nexus e trazê-lo até ele, no Escudo de Transitus.', 'Preciso de mais filhotes de draco para dar continuidade à minha pesquisa sobre as runas que cobrem seus corpos.$b$bEles podem ser encontrados na margem noroeste do vale...$b$b<Raelorasz fura a própria mão com uma lança e recobre a ponta com seu sangue.>$b$bPegue isto e use em um deles. Espere até que estejam subjugados, então traga-os para mim antes que se soltem.', '', 'Draco do Nexus capturado', '', '', '', '', '', '', '', 'Fale novamente com Raelorasz no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11941, 'ptBR', 'Enigmas...', 'Leve o Fragmento Esplendoroso para Raelorasz, no Escudo de Transitus.', 'Há algo neste pedaço de metal que chama a sua atenção.$b$bTalvez Raelorasz possa esclarecer a finalidade disso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Raelorasz no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11942, 'ptBR', 'Palavras de poder', 'Thassarian no Zigurate dos Lamentos quer que você vá para a Cidade-Templo de En\'kilah e recupere os Pergaminho do Alto-sacerdote Talet-Kha na Torre da Dor, o Pergaminho do Alto-sacerdote Naferset na Torre da Decomposição e o Pergaminho do Alto-sacerdote Andorath.', 'O lich falou, $n. Os sumos sacerdotes de En\'kilah conhecem o segredo para entrar em Naxxanar.$B$BVá para a Torre Sangrenta, para a Torre da Dor e para a Torre da Decomposição e mate cada um de seus sacerdotes.$B$BRetorne uma vez que conseguir seus pergaminhos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Thassarian no Zigurate dos Lamentos, na Tundra Boreana.', 0),
(11943, 'ptBR', 'A prisão', 'Raelorasz, no Escudo de Transitus, quer que você obtenha o Invólucro da Prisão do General Cerúleo e o Núcleo de Energia do Armipotente Goredrak.', 'Você encontrou o fragmento de uma prisão especial, $n.$b$bOs lacaios de Malygos usam prisões similares para aprisionar os magos capturados e outras entidades arcanas, mas esta prisão foi construída para aprisionar algo... mais forte.$b$bVamos esperar que o inimigo de nosso inimigo seja nosso aliado. Procure os fragmentos restantes da prisão.$b$bÉ provável que estejam com os serviçais mais confiáveis de Malygos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Raelorasz no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11944, 'ptBR', 'Cercados!', 'Cabo Venn, no Campo da Morte, quer que você mate 7 Defensores do Zigurate.', 'Praticamente não temos mais esperanças. Fomos ordenados a tomar o Zigurate dos Lamentos com apenas um punhado de homens.$B$BTeremos sorte se conseguirmos sustentar esse posto contra o Flagelo. Estamos em menor número, feridos e sem rota de fuga.$B$BSe puder aliviar a pressão sobre nós, talvez possamos fortalecer nossa posição. Mate alguns mortos-vivos que rondam a estrutura e nós cuidaremos da investida deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Cabo Venn no Campo da Morte, na Tundra Boreana.', 0),
(11945, 'ptBR', 'Preparação para o pior', 'Utaik quer que você junte 8 Suprimentos de Kaskala, em Kaskala.', 'Que tempos sombrios são estes em que o espírito de Karkut anda por essa terra reunindo os espíritos dos morsanos mortos.$B$BOs filhos das brumas levaram muitos de nossos confrades. Em breve, nossa querida Kaskala será reduzida às cinzas.$B$BAinda há esperança. Não para nós, mas para nossas famílias, que mandamos para Unu\'pe. Lutamos na esperança de garantir um futuro para elas.$B$BNossas famílias precisam de suprimentos ou morrerão de fome. Não temos comida suficiente em Unu\'pe. Por favor, resgate qualquer suprimento antes que seja tarde demais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Utaik em Kaskala, na Tundra Boreana.', 0),
(11946, 'ptBR', 'Keristrasza', 'Keristrasza quer que você fale com ela quando estiver $Gpronto:pronta; para confrontar Malygos.$b$bCaso perca sua Prisão Arcana Aumentada, fale com Raelorasz no Escudo de Transitus.', 'Estou... livre?$b$bDestinada a passar uma eternidade vagando em um abismo vazio e agora estou salva? Jamais compreenderá o quanto lhe sou grata, mortal.$b$bQuando me neguei a me curvar ante as vontades de Malygos, ele me aprisionou e estraçalhou minha jaula. Mesmo que eu viva cem vezes o tempo da sua vida, nunca esquecerei tal ato de bondade.$b$BTalvez, com o tempo, eu ache modos de recompensar-lhe. Por enquanto, devemos nos preocupar com Malygos. Estou fraca e muito ainda precisa ser feito.$b$bNecessito de sua ajuda, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(11947, 'ptBR', 'Contra-ataque', 'Mate o Tenente Granizo evocado pela Pedra de Gelo, localizada em Ethel Rethor, que fica em Desolação. Depois, retorne ao Ancião da Harmonia Telúrica em uma capital.', 'Nós precisamos proteger o equilíbrio! Estamos correndo contra o tempo.$b$bExiste um acampamento na sombra de Ethel Rethor que fica na parte noroeste de Desolação. Lá, você encontrará grandes pedras de gelo que são usadas pelos sectários como um meio de comunicação com os elementais, assim como é feito em Silithus. Por mais que eu odeie essa ideia, espero que os espíritos entendam. Você deve evocar um dos tenentes de Ahune e destruí-lo. Com sorte, isso irá atrasá-los o suficiente...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião da Harmonia Telúrica.', 0),
(11948, 'ptBR', 'Contra-ataque', 'Mate o Tenente de Ventogelante evocado pela Pedra de Gelo, localizada na ilha dos elementais da água, que fica na parte oeste da Selva do Espinhaço. Depois, retorne ao Ancião da Harmonia Telúrica em uma capital.', 'Nós precisamos proteger o equilíbrio! Estamos correndo contra o tempo.$b$bNeptulon possui uma base de operações em uma ilha na parte oeste da Selva do Espinhaço. Lá, você encontrará grandes pedras de gelo que são usadas pelos sectários como um meio de comunicação com o reino do Caçador das Marés, assim como é feito em Silithus. Por mais que eu odeie essa ideia, espero que os espíritos entendam. Você deve evocar um dos tenentes de Ahune e destruí-lo. Com sorte, isso irá atrasá-los o suficiente...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião da Harmonia Telúrica.', 0),
(11949, 'ptBR', 'De graça, não!', 'Ataika quer que você mate 12 Saqueadores Kvaldir, em Kaskala.', 'Kaskala é um lugar sagrado para nós, $r. Nossos antepassados foram guiados até aqui pelo próprio espírito de Tayutka.$B$BAgora, essas imundas criaturas saem das brumas para nos atacar sem motivo algum.$B$BMostraremos a eles que não usamos nossas lanças apenas para caçar baleias. Lute conosco, $Gamigo:amiga;. Talvez meu povo viva para um dia $Grecompensá-lo:recompensá-la;.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ataika em Kaskala, na Tundra Boreana.', 0),
(11950, 'ptBR', 'A sabedoria de Muahit', 'Encontre o Ancião Muahit, em Kaskala.', 'Olha, $n. Guerreiros como eu podem ser substituídos. Se eu cair, meus primos e irmãos pegarão minha lança e continuarão lutando.$B$BMeu povo não sobreviverá sem anciãos sábios. O teimoso Muahit, nosso mais respeitável xamã, se recusa a deixar o altar de Tayutka, na ilha central. Sofreremos uma gigantesca perda, caso ele seja morto por esses monstros.$B$BVocê veio de fora, talvez ele o escute. Faça-o enxergar a verdade... peça para que fuja até a segurança de Unu\'pe antes que seja tarde.', '', '', '', '', '', '', '', '', '', '', 0),
(11951, 'ptBR', 'Isca e anzol', 'Keristrasza pediu-lhe que consiga 10 Estilhaços de Mana Cristalizados em Gelarra.$B$bCaso perca sua Prisão Arcana Aumentada, fale com Raelorasz no Escudo de Transitus.', 'Durante minha escravidão, muito aprendi sobre Malygos. O destino agora nos permite usar essa sabedoria contra ele.$b$bExiste uma grande dragonesa azul, Saragosa, que voa acima do Nexus. Ela é a guardiã do aspecto e, também, sua consorte. Caso alguma ameaça surja, ela o alertará sobre o perigo.$b$bMuito sofri nas garras dela e agora é chegada a hora de sua morte. Antes, contudo, precisamos da isca perfeita...', '', '', '', '', '', '', '', '', '', 'Fale com Keristrasza em Gelarra, que fica na Tundra Boreana. Caso perca sua Prisão Arcana Aumentada, fale com Raelorasz no Escudo de Transitus.', 0),
(11953, 'ptBR', 'Contra-ataque', 'Mate o Tenente Glacial evocado pela Pedra de Gelo, localizada no Passeio do Crepúsculo que fica na parte norte de Silithus. Depois, retorne ao Ancião da Harmonia Telúrica em uma capital.', 'Nós precisamos proteger o equilíbrio! Estamos correndo contra o tempo.$b$bSilithus é a principal base de operações da Seita do Crepúsculo em Azeroth. Na parte norte da região, eles têm usado grandes pedras de gelo como um meio de comunicação com o reino do Caçador das Marés. Por mais que eu odeie essa ideia, espero que os espíritos entendam. Você deve evocar um dos tenentes de Ahune e destruí-lo. Com sorte, isso irá atrasá-los o suficiente...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião da Harmonia Telúrica.', 0),
(11954, 'ptBR', 'Contra-ataque', 'Mate o Templário Glacial evocado pela Pedra de Gelo, localizada perto do Portal Negro, que fica na Península Fogo do Inferno. Depois, retorne ao Ancião da Harmonia Telúrica em uma capital.', 'Nós precisamos proteger o equilíbrio! Estamos correndo contra o tempo.$b$bA Seita do Crepúsculo estabeleceu uma base próxima ao Portal Negro em Draenor. De lá, eles usam pedras de gelo para coordenar a chegada do senhor do gelo. Por mais que eu odeie essa ideia, espero que os espíritos entendam. Você deve evocar um dos tenentes de Ahune e destruí-lo. Com sorte, isso irá atrasá-los o suficiente...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião da Harmonia Telúrica.', 0),
(11955, 'ptBR', 'Ahune, o Senhor do Gelo', 'Viaje para o Pátio dos Escravos no Reservatório Presacurva, que fica no Pântano Zíngaro e fale com Numa Irmã das Nuvens', 'Eu acredito que nós somos fortes o suficiente para cumprir a missão final.$b$bNós não podemos permitir que o plano do Culto do Crepúsculo e das nagas hereges de Neptulon se realize. Pelo bem de Azeroth e de todos que vivem nela, nós temos que agir. Nosso caminho está claro. Você precisa viajar para o Pátio dos Escravos no interior do Reservatório Presacurva e encontrar com nossa xamã. Vá rápido!', '', '', '', '', '', '', '', '', '', '', 0),
(11956, 'ptBR', 'Encontre o filactério', 'Vá para o Campo da Morte e cavalgue a égua Crepúsculo até a localização do Filactério de Tanathal. Pegue-o e leve-o de volta para Thassarian dentro do Zigurate dos Lamentos.', 'Vamos direto ao que interessa, $n. Fui mandado ao que era pra ser uma missão suicida em tomar este zigurate. Completei meu dever como soldado e agora é hora de conseguir algumas respostas.$B$BEste lich tem o conhecimento que procuro, mas não consigo causar nenhum dano em seu corpo físico.$B$BEle guardou sua própria alma em um filactério e não conseguirei extrair informações enquanto este permanecer escondido.$B$BVolte ao acampamento e pegue a minha égua Crepúsculo. Ela o levará até o filactério. Traga-o para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Thassarian no Zigurate dos Lamentos, na Tundra Boreana.', 0),
(11957, 'ptBR', 'O fim de Saragosa', 'Keristrasza quer que você use a Concentração de Poder para atrair Saragosa e, então, derrotá-la.', 'Usando os cristais de mana que você me forneceu, criei esta Concentração de Poder.$b$bSaragosa é insaciável. Ela não será capaz de resistir a esta isca, que contém feitiços que diminuirão grandemente o seu poder. Esperemos que ela não descubra meu ardil...$b$bPrepare-se, $n, e fale comigo novamente quando estiver $Gpronto:pronta; para enfrentar Saragosa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Keristrasza em Gelarra, que fica na Tundra Boreana. Caso perca sua Prisão Arcana Aumentada, fale com Raelorasz no Escudo de Transitus.', 0),
(11958, 'ptBR', 'Não deixe nada se perder', 'Recupere 6 Mercadorias Roubadas de Moa\'ki dos guaxinantes. Devolva as mercadorias para o Ancião Ko\'nani, no Porto Moa\'ki.', 'Os guaxinantes sempre foram nossos inimigos naturais. Mas a incursão do seu povo no grande Ermo das Serpes os forçou a se mudar para uma pequena clareira em um vale mais ao norte.$B$BE então, depois da revolta que houve hoje pela manhã, eles ficaram mais agressivos do que nunca. Eles já saquearam vários suprimentos nossos... coisas de que vamos precisar para sobreviver à jornada.$B$BComo sinal de boa fé e amizade, por favor, recupere nossas mercadorias dos guaxinantes da Clareira Nevada.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião Ko\'nani no Porto Moa\'ki, que fica no Ermo das Serpes.', 0),
(11959, 'ptBR', 'Mate Loguhn', 'Esfregue o Sangue de Loguhn em você e então fale novamente com o Ancião Ko\'nani no Porto Moa\'ki.', 'As coisas já estão piorando. Só há uma coisa a fazer... infelizmente, Loguhn deve morrer!$B$BEle é o macho alfa da tribo da Clareira Nevada, e é um guaxinante cruel. Essa é a única maneira de conseguir alguma trégua dos ataques e saques.$B$BVocê encontrará o "Rasgador de Carne" em frente a uma cabana na elevação norte da clareira. É uma cabana maior que as outras, não dá pra errar. Mate-o e esfregue o sangue dele em você, para mostrar sua vitória e seu respeito.', '', 'Sangue de Loguhn esfregado', '', '', '', '', '', '', '', 'Fale novamente com o Ancião Ko\'nani no Porto Moa\'ki, que fica no Ermo das Serpes.', 0),
(11960, 'ptBR', 'Planos para o futuro', 'Colete 12 filhotes da Clareira Nevada. Leve-os para o Coureador Mau\'i no Porto Moa\'ki.', 'Precisamos tomar a ofensiva contra os guaxinantes se quisermos ter chance de sobreviver. No entanto, eu temo que muitos sejam mortos devido ao nosso fervor.$B$BOs guaxinantes da Clareira Nevada têm tanto direito à vida quanto nós. Você e eu lhes daremos uma chance de sobreviver.$B$BSe o Ancião Ko\'nani ainda não pediu, ele pedirá que você dê um jeito neles. Enquanto estiver na clareira ao norte daqui, eu gostaria que você capturasse os filhotes dos guaxinantes e os trouxesse para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Coureador Mau\'i no Porto Moa\'ki, que fica no Ermo das Serpes.', 0),
(11961, 'ptBR', 'Que os espíritos nos guardem', 'O Ancião Muahit, na Baía do Bafo de Njord, quer que você ache o cadáver de Iruk na água e recupere o Totem de Issliruk.', 'Poderosos espíritos zelam pela minha tribo. Kaskala não cairá.$B$BIssliruk nos dará coragem, Tayutka fará com que nossos sobreviventes sempre tenham comida em seus abrigos e Karkut cuidará para que nossos mortos nunca se percam no caminho.$B$BÉ da orientação de Issliruk o que mais precisamos agora. Pedi para que meu sobrinho, Iruk, me trouxesse o totem de Issliruk, mas as lanças dos kvaldir o acertaram e seu corpo caiu nas águas ao norte. Traga-me o totem, $n. Não deixe que a morte de meu sobrinho seja em vão.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião Muahit na Baía do Bafo de Njord, na Tundra Boreana.', 0),
(11962, 'ptBR', 'Uma última entrega', 'Entregue o Caixote de Minério de Algures para Hilda Forjapétrea, na Bastilha Valentia.', 'Então é isso. Com o último minério que você nos trouxe, temos o suficiente para mandar pra Bastilha Valentia.$B$BJá que Algures sumiu da face de Azeroth, então que sejamos lembrados como os primeiros a defender nossa terra e como os últimos a desistir dela.$B$BLeve este minério para Hilda Forjapétrea. Ela é uma grande amiga minha. Peça para fazer algumas boas armas com ele. Precisaremos de muitas nos próximos dias.', '', '', '', '', '', '', '', '', '', 'Fale com Hilda Forjapétrea na Bastilha Valentia, na Tundra Boreana.', 0),
(11963, 'ptBR', 'Armas para Algures', 'Fale novamente com Geraldo Delleprane, em Algures.', 'Algures foi tomada e ainda assim Geraldo se lembrou de me mandar minério? Nossa, aí está um homem tão corajoso quanto os soldados nas frentes de batalha...$B$BJá que os civis estão dispostos a lutar por suas terras, nós não deixaremos que eles as percam. Não temos tropas para enviar, mas podemos enviar armas.$B$BEstas aqui estavam separadas para os novos recrutas, mas vou poder repô-las com o minério que você trouxe. Diga a Geraldo que as armas estão chegando.', '', '', '', '', '', '', '', '', '', '', 0),
(11964, 'ptBR', 'Incenso para as faíscas de verão', 'O Historiador do Festival quer que você ofereça um Incenso Estival para uma Faísca de Verão do lado de fora de qualquer acampamento da Aliança.', 'Você sabia que o fogo do festival está aceso em todos os acampamentos da Aliança? Os Guardiões das Chamas são os responsáveis por zelar pelo fogo em tendas do lado de fora de cada cidade, cuidando para que as fogueiras não se apaguem e a celebração não pare.$b$bAo lado de cada Guardião das Chamas há uma faísca do festival – um mensageiro dos espíritos elementais do fogo.$B$BVocê gostaria de fazer uma oferenda às faíscas do festival, $n? Basta dar este incenso estival a qualquer uma delas. Se você agradar os pequeninos espíritos do fogo, eles $Go:a; recompensarão.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Faísca de Verão.', 0),
(11965, 'ptBR', 'Chamado às armas!', 'Vá para a prefeitura de Algures e toque o sino.', 'Algures tem uma chance de vencer agora, $n. Isso era tudo que podíamos pedir e foi você quem tornou isso possível.$B$BTudo que precisamos agora é um ponto de encontro. Farei com que meus homens levem as armas para a prefeitura. Vá e toque o sino para que todos os sobreviventes saibam que nos agruparemos lá.$B$BEstá na hora de mostrar ao Flagelo do que somos feitos.', '', 'Sino de Algures tocado', '', '', '', '', '', '', '', 'Fale novamente com Geraldo Delleprane em Algures, na Tundra Boreana.', 0),
(11966, 'ptBR', 'Incenso para as faíscas do festival', 'O Contador de Histórias do Festival quer que você ofereça um Incenso Estival para uma Faísca do Festival do lado de fora de qualquer acampamento da Horda.', 'Você sabia que o fogo do festival está aceso em todos os acampamentos da Horda? Os Protetores das Chamas são os responsáveis por zelar pelo fogo em tendas do lado de fora de cada cidade, cuidando para que as fogueiras não se apaguem e a celebração não pare.$b$bAo lado de cada Protetor das Chamas há uma faísca do festival – um mensageiro dos espíritos elementais do fogo.$B$BVocê gostaria de fazer uma oferenda às faíscas do festival, $n? Basta dar este incenso estival a qualquer uma delas. Se você agradar os pequeninos espíritos do fogo, eles $Go:a; recompensarão.', '', '', '', '', '', '', '', '', '', 'Fale com uma Faísca do Festival.', 0),
(11967, 'ptBR', 'Alistamento vermelho', 'Keristrasza pediu para que a leve até Raelorasz, no Escudo de Transitus.', 'Sem dúvida, Malygos está ciente de que algo está faltando.$b$bEu o conheço. Sua concentração está abalada. Estou confiante que conseguirei atraí-lo para fora da segurança de seu reino, quando ele descobrir o destino de sua amada Saragosa.$b$bLeve-me a Raelorasz imediatamente, $n. Ele tem de convocar cada dragão sob seu comando para enfrentar Malygos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Raelorasz no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11968, 'ptBR', 'O virar das marés', 'O Ancião Muahit quer que você mate Heigarr, o Horrível, na Baía do Bafo de Njord.', 'Os espíritos atenderam ao nosso pedido de ajuda, $n. É um sinal de que Kaskala ainda pode ser salva.$B$BAproveite-se da confusão criada pelo clima e mate o líder dos kvaldir. Seus atos nos trarão vantagem na batalha, estou certo disso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião Muahit na Baía do Bafo de Njord, na Tundra Boreana.', 0),
(11969, 'ptBR', 'Acionando a armadilha', 'Raelorasz quer que você use a Centelha de Raelorasz no Sinal de Fumaça em Gelarra.', 'Devemos muito aos seus esforços por esta oportunidade, $n.$b$bNada mais adequado do que você $Gmesmo:mesma; começar o ataque contra Malygos.$b$bPegue esta centelha e use-a para acender o sinal de fumaça, a noroeste do Nexus. Keristrasza $go:a; guiará de lá.', '', 'Malygos atraído', '', '', '', '', '', '', '', 'Fale novamente com Raelorasz no Escudo de Transitus, que fica na Tundra Boreana.', 0),
(11970, 'ptBR', 'O mestre do folclore de verão', 'Fale com um Catedrático do Festival em qualquer capital da Aliança.', 'É preciso buscar e apreciar o saber.$b$bEm cada capital da Aliança há um Historiador do Festival  que pode guiar seu caminho pelo conhecimento.', '', '', '', '', '', '', '', '', '', '', 0),
(11971, 'ptBR', 'O contador de histórias de verão', 'Fale com um Contador de Histórias do Festival em qualquer capital da Horda.', 'É preciso buscar e apreciar o saber.$b$bEm cada capital da Horda há um Contador de Histórias do Festival que pode guiar seu caminho pelo conhecimento.', '', '', '', '', '', '', '', '', '', '', 0),
(11972, 'ptBR', 'Fragmentos de Ahune', 'Entregue os Estilhaços de Gelo para Luma Mãe dos Céus.', 'Estes fragmentos pulsam com o mau agouro. Será que ainda guardam a essência do Senhor do Gelo?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Luma Mãe dos Céus no Pátio dos Escravos.', 0),
(11973, 'ptBR', 'Prisioneira de guerra', 'A Maga-de-guerra Kaitlyn quer que você liberte Keristrasza.', 'Malygos tomou Keristrasza como consorte!$b$bNão podemos permitir que isso aconteça.$B$BFaça o que for preciso para poupá-la desse destino, $r.', '', 'Keristrasza fenecida', '', '', '', '', '', '', '', 'Fale novamente com a Maga-de-guerra Kaitlyn no Nexus.', 0),
(11975, 'ptBR', 'Quando eu crescer...', 'Leve a sua órfã Salandria para ver a banda Chefe Tauren Elite no Passeio dos Anciãos, que fica em Luaprata. Não se esqueça de chamá-la, caso ela não esteja com você ao chegar lá.', 'Acho que já perguntei isso, mas você sempre quis ser $Gum:uma; $c? Desde pequen$Go:a;?!$B$BEu ainda não sei o que vou ser. Talvez uma maga, ou uma bruxa, ou uma cavaleira sangrenta... Ou quem sabe... uma estrela do rock!! Que nem o Sid Nicious, o elfo sangrento da Chefe Tauren Elite!$B$BOuvi dizer que, quando não estão em turnê, eles ficam em uma varanda no Passeio dos Anciãos de Luaprata esperando pelas pessoas que passam por lá.$B$BPor favor, a gente pode ir lá? Hein! Por favoooooooooor!', 'Leve Salandria para visitar a banda Chefe Tauren Elite em Luaprata.', '', '', '', '', 'Leve Salandria para visitar a banda Chefe Tauren Elite em Luaprata.', '', '', '', 'Fale novamente com a Órfã Elfa Sangrenta.', 0),
(11976, 'ptBR', 'Ice Shards', 'Bring the Ice Shards to Luma Skymother.', 'These shards pulse with foreboding. Do they hold the last essence of the Frost Lord?', '', '', '', '', '', '', '', '', '', 'Return to Luma Skymother at Darrow Hill in Hillsbrad Foothills.', 0),
(11977, 'ptBR', 'Uma tauren entre os taunkas', 'Procure a Emissária Casco Luminoso no Campo de Refugiados de Zefirália.', '<Guerratuk aponta para o nordeste.>$B$BEla é muito bondosa, sabe. Se não fosse pela emissária de vocês, os refugiados sobreviventes já teriam abandonado as esperanças. Ela pode não ser uma taunka de nascença, mas a tribo já a considera como uma anciã da aldeia.$B$BSe você for quem eu acho que é, por favor vá e visite a Emissária Casco Luminoso, no campo de refugiados. Ela espera por você.', '', '', '', '', '', '', '', '', '', '', 0),
(11978, 'ptBR', 'Novas forças para a Horda', 'A Emissária Casco Luminoso no Campo de Refugiados de Zefirália, no Ermo das Serpes, quer que você recupere 10 Armamentos da Horda.', 'Antes que possamos incorporar oficialmente esses taunkas à Horda, precisamos recuperar nossos armamentos dos nerubianos de Anub\'ar que infestam os bosques próximos. Os armamentos foram perdidos quando uma caravana do Martelo de Agmar foi emboscada pelo Flagelo no final da noite de ontem.$B$BSiga para o bosque a leste do Campo de Refugiados de Zefirália e recupere os armamentos, $r.', '', '', '', '', '', '', '', '', '', 'Procure a Emissária Casco Luminoso no Campo de Refugiados de Zefirália, no Ermo das Serpes.', 0),
(11979, 'ptBR', 'Os taunkas e os taurens', 'Procure a Emissária Casco Luminoso no Campo de Refugiados de Zefirália.', 'O Flagelo tomou o controle da capital dos taunkas, a Aldeia Bruma Boreal. Todos os taunkas que escaparam do ataque são mantidos sob proteção no Campo de Refugiados de Zefirália na fronteira oeste do Ermo das Serpes.$B$BO Senhor Grito Infernal crê que os taunkas precisam se unir à Horda, se quiserem sobreviver, e enviou uma emissária taurena para Zefirália, para melhorar nosso relacionamento com os taurens-do-frio. Vá até o Campo de Refugiados de Zefirália e procure a Emissária Casco Luminoso. Você a ajudará.', '', '', '', '', '', '', '', '', '', '', 0),
(11980, 'ptBR', 'Orgulho da Horda', 'O Guarda-de-Sangue Roh\'kill, no Campo de Refugiados de Zefirália, no Ermo das Serpes, quer que você mate 15 Emboscadores Anub\'ar.', 'Eu era um dos guardas escoltando a caravana que trazia o carregamento de armas pra cá. O ataque foi rápido e nos pegou de surpresa. Nós lutamos e matamos dúzias de feras, mas no final fomos sobrepujados. Tor\'zin e eu mal saímos com vida...$B$BSe não estivéssemos feridos, a essa altura já estaríamos nos bosques caçando pessoalmente esses demônios. Você nos ajudaria a reconquistar nosso orgulho? Vasculhe os bosques a leste daqui, ache Nerubianos de Anub\'ar e mate-os! Pela Horda!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-Sangue Roh\'kill no Campo de Refugiados de Zefirália, que fica no Ermo das Serpes.', 0),
(11981, 'ptBR', 'Encontre Karun!', 'Fale com Karun no morro sobre Thor Modan.', 'A pele rochosa do guerreiro terrano está coberta de rachaduras e cinzeladas. Mesmo que ele seja incapaz de sangrar, você sente que ele está próximo da morte.$B$BUma voz grave e rouca escapa dos lábios do combatente caído.$B$B"Encontre... Karun... você precisa encontrar... Karun."$B$BEle olha para você impaciente, quando lhe pergunta quem ou o que é Karun.$B$B"Nosso líder... está no alto... do morro sobre Thor Modan... nos comandando. Por favor... diga-lhe... não conseguimos... conquistar a cidade."', '', '', '', '', '', '', '', '', '', '', 0),
(11982, 'ptBR', 'Chuva de pedras que cai sem parar', 'Karun, que está no morro sobre Thor Modan, quer que você jogue penedos na área exposta de Thor Modan para interromper o trabalho dos anões de ferro.', 'Sob nossos pés encontra-se o antigo bastião dos ferrosos, Thor Modan. Milhares de anos atrás, os gigantes de pedra rasgaram a terra, fazendo com que boa parte da cidade desabasse, e expondo uma grande porção do resto.$B$BMesmo agora, os anões de ferro tentam recuperar a velha capital, mas nós não o permitiremos. Meus gigantes preenchem o fosso com penedos e destroços, na esperança de selá-lo e matar os servos do ferro. Tome os penedos espalhados perto do fosso a nordeste e nos ajude a por um fim nos esforços inimigos.', '', 'Operações dos Anões de Ferro interrompidas', '', '', '', '', '', '', '', 'Fale novamente com Karun nos Montes dos Penedos, que ficam na Serra Gris.', 0),
(11983, 'ptBR', 'Juramento de sangue da Horda', 'Fale com os taunkas no Campo de Refugiados de Zefirália e faça 5 deles jurarem aliança à Horda.$B$BDevolva o Juramento de Sangue da Horda à Emissária Casco Luminoso quando tiver completado a tarefa.', 'Eles estão prontos, $n. Esses taunkas se juntarão de livre vontade à Horda, e farão tudo ao alcance deles para expulsar o Flagelo desse mundo.$B$B<Casco Luminoso entrega a você um pergaminho com a insígnia da Horda.>$B$BEsse pergaminho contém o juramento de sangue da Horda. A tradição manda que nossos novos irmãos e irmãs taunkas pronunciem as palavras sagradas contidas no pergaminho.$B$BLeve o pergaminho e oficie a entrada dos taunkas na Horda, comandante. Me devolva o pergaminho quando tiver completado a tarefa.', '', 'Taunkas acolhidos pela Horda', '', '', '', '', '', '', '', 'Procure a Emissária Casco Luminoso no Campo de Refugiados de Zefirália, no Ermo das Serpes.', 0),
(11984, 'ptBR', 'Enchendo as jaulas', 'Samir, nas Fontes Graníticas, quer que você use a Jaula de Caçador de Recompensas num troll drakkari que tenha sido atordoado por Bino.', 'O velho Bino já teve dias melhores.$b$bEle tem sido um inútil desde a época em que ficamos na Terra Fantasma. Nós tivemos que nos virar sozinhos, e hoje isso significa leiloar trolls.$b$bPor sorte, nós achamos uma utilidade pro Bino. Por algum motivo, a maluquice dele permite que ele circule entre os trolls daqui. Então, nós ensinamos um truquezinho para ele que tem dado um bom lucro.$b$bVeja com seus próprios olhos. Fale com o Bino, leve ele para a parte sudoeste das Ruínas de Drak\'Zin e use a jaula dele assim que ele "pegar" um troll.', '', 'Troll do Gelo capturado vivo', '', '', '', '', '', '', '', 'Fale novamente com Samir nas Fontes Graníticas, que ficam na Serra Gris.', 0),
(11985, 'ptBR', 'Atentado em Thor Modan', 'Karun, que está no morro sobre Thor Modan, quer que você mate Thane de Ferro Argrum.', 'Se não superarmos os defensores dentro de Thor Modan, os anões de ferro resistirão para sempre. Os Terrenos enfrentam corajosamente os constructos criados pelos filhos do ferro, mas não conseguem entrar na cidade.$B$BOs túneis se estreitam rápido demais para que os gigantes sejam úteis, nos limitando a poucas opções. Você estaria $gdisposto:disposta; a se aventurar na cidade e matar o anão que comanda a resistência?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Karun nos Montes dos Penedos, que ficam na Serra Gris.', 0),
(11986, 'ptBR', 'O diário danificado', 'Recupere 8 Páginas Perdidas do Diário, combine-as com o Diário Incompleto e entregue o diário completo a Torthen Cavafundo no Acampamento da Brigada de Cerro Oeste.', 'Este diário gasto e enlameado já viu dias melhores. Folheando o livro, você descobre dúzias de anotações, diagramas e mapas.$B$BA caligrafia do autor lhe parece vagamente familiar, mas você não consegue lembrar direito até encontrar um registro assinado por Brann Barbabronze.$B$BA metade final do livro, contendo as anotações mais recentes, foi arrancada. Há páginas espalhadas por todo o campo de batalha e será impossível saber o que Brann descobriu aqui até que o livro esteja inteiro de novo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Torthen Cavafundo no Acampamento da Brigada de Cerro Oeste, que fica na Serra Gris.', 0),
(11987, 'ptBR', 'zzOLDFortune Card: Silver', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(11988, 'ptBR', 'A pedra decifradora de runas', 'Traga 5 Fragmentos de Pedra Decifradora de Runas para Torthen Cavafundo no Acampamento da Brigada de Cerro Oeste.', 'Brann conta no diário que usou uma pedra decifradora de runas para decodificar as runas importantes na placa que ele descobriu. Sem a pedra decifradora, o texto na placa não passa de um monte de rabiscos.$B$BA última anotação de Brann termina com ele dizendo que os anões de ferro lhe tomaram a pedra decifradora, estilhaçando-a e dividindo-a entre si. Para que possamos decifrar a placa rúnica, é necessário antes coletar os fragmentos. Qualquer anão dentro de Thor Modan ou nos prédios em volta pode estar com os fragmentos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Torthen Cavafundo no Acampamento da Brigada de Cerro Oeste, que fica na Serra Gris.', 0),
(11989, 'ptBR', 'Trégua?', 'Drakuru, nas Fontes Graníticas, quer que você use a Faca Cega, que está perto da jaula, e então fale com ele.', 'Fica espert$go:a;, cara.$b$bDrakuru já encolheu mais cabeças do que eu consigo lembrar e, mesmo se eu conseguisse, eu não ia saber contar um número tão grande. Sorte sua que eu tô nesta jaula, ou eu botava o teu coco na lista também.$b$bMas, considerando o lance da situação, de repente a gente podia botar nossas diferença de lado por um tempo, né não?$b$bDrakuru sabe das coisas, cara. Coisas que vão ajudar você nessa sua luta aqui.$b$b<Drakuru corta a palma da mão com uma das presas e a estende para fora da gaiola.>$b$bEntão, $gmermão:garota;, o que tu me diz... trégua?', '', 'Pacto de Sangue com Drakuru', '', '', '', '', '', '', '', 'Fale novamente com Drakuru nas Fontes Graníticas, na Serra Gris.', 0),
(11990, 'ptBR', 'O vidro das visões', 'Drakuru, nas Fontes Graníticas, quer que você lhe traga 1 Ampola de Cristal, 1 Ramo de Aguapé e 3 Folhas-de-névoa.', 'Vamos começar pelo começo, cara. A gente tem que fazer uns trabalhos de preparação antes.$b$bSei lá quanto tempo os vacilões vão me malocar aqui, então cê vai precisar dum elixir sinistrão pra gente ficar em contato, saca?$b$bSorte sua que eu sei fazer a parada! E dá pra descolar todos os bagulhos da receita aqui perto.$b$bPreciso duma ampola daquela trolesa teteia ali, um bocadinho de aguapé do lago que fica logo ali a norte, e algumas folhas-de-névoa dessa área aqui do acampamento.$b$bRala peito, $gmano:irmãzinha;, antes que os vacilões me levem daqui!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Drakuru nas Fontes Graníticas, na Serra Gris.', 0),
(11991, 'ptBR', 'Sujeito a interpretação', 'Drakuru quer que você pegue 5 Mojos Congelados dos Trolls Drakkari nas Ruínas de Drak\'Zin e, em seguida, use o elixir no Braseiro de Drakuru, nas mesmas ruínas.', 'Um pacote lendário de artefatos, perdido há uma pá de tempo, foi criado pra deixar a Bastilha Drak\'Tharon sinistrona.$b$bO povão aí acha que é lero, mas Drakuru tá de olho no lance, cara!$b$bQuase descobri onde um deles tava, mas aí cês me cataram quando eu tava interpretando os hieroglifos. Cê tem que evocar minha alma lá de novo pra eu terminar de ler!$b$bUsa o meu elixir no braseiro das Ruínas de Drak\'Zin, a sudoeste daqui. Cê tem que misturar o lance no mojo congelado dos meus camaradas lá. Odeio ver meus camaradas morrer, mas é pro bem de geral.', '', '', '', '', '', '', '', '', '', '', 0),
(11993, 'ptBR', 'As profecias rúnicas', 'Torthen Cavafundo, no Acampamento da Brigada de Cerro Oeste, quer que você decifre as três Placas Rúnicas.', 'Não temos tempo a perder! Agora que a pedra decifradora de runas está reconstituída – bem, pelo menos a maior parte dela – podemos decodificar o conteúdo das placas rúnicas em que Brann estava trabalhando quando teve que fugir.$B$BNão há como saber se ele conseguiu ler todas as três placas, mas teremos de presumir que reuniu informação suficiente para determinar o próximo local a ser visitado.$B$BVá a cada placa e use a pedra decifradora para ler o conteúdo. Brann deve estar contando conosco!', '', 'Primeira Profecia Decifrada', 'Segunda Profecia Decifrada', 'Terceira Profecia Decifrada', '', '', '', '', '', 'Fale novamente com Torthen Cavafundo no Acampamento da Brigada de Cerro Oeste, que fica na Serra Gris.', 0),
(11995, 'ptBR', 'Sua presença é requisitada no Recanto das Estrelas', 'Fale com a Imagem da Arquimaga Modera no Recanto das Estrelas.', '$C, sei que os morsanos vão pedir muitos favores a você, mas precisa chegar ao Recanto das Estrelas com toda urgência!$B$BA revolta que ocorreu esta manhã com certeza representará bem mais que um mero incômodo para os nativos de lá.$B$BO Recanto das Estrelas fica na direção oeste, depois da intersecção da estrada que segue para o norte, saindo do cais. Lá você encontrará uma arquimaga chamada Modera. Ela está esperando você.', '', '', '', '', '', '', '', '', '', '', 0),
(11996, 'ptBR', 'Sua presença é requisitada no Martelo de Agmar', 'Fale com a Imagem do Arquimago Aethas Fendessol no Martelo de Agmar.', '$C, eu sei que os morsanos vão pedir muitos favores, mas você precisa chegar ao Martelo de Agmar com toda urgência!$B$BA revolta que ocorreu hoje de manhã significa mais que um simples incômodo para os nativos de lá.$B$BO Martelo fica na direção oeste, depois da intersecção da estrada que segue para o norte, saindo do cais. O Arquimago Aethas Fendessol estará esperando por você.', '', '', '', '', '', '', '', '', '', '', 0),
(11998, 'ptBR', 'Embebedando o peru', 'Leve um barril de Pinga Boa da Disgrama para Brugar Rasgalito no Acampamento da Brigada de Cerro Oeste.', 'A melhor opção que temos para levar nossas forças até o Glaciar Coroa de Gelo é a rede de túneis que fica sob Thor Modan, a antiga cidade dos anões de ferro.$B$BBrugar Rasgalito e seus rapazes da Liga dos Exploradores não ficarão nada felizes com isso, mas ordens são ordens.$B$BA notícia talvez desça um pouco mais macia se você lhe trouxer um barril daquela pinga vendida pelo coureiro Hugo Copas lá no Entreposto Sequoia, que fica a sudeste daqui ao longo da orla da floresta.$B$BO sujeito é meio ruim da cabeça, mas faz a melhor pinga da região.', '', '', '', '', '', '', '', '', '', 'Fale com Brugar Rasgalito no Acampamento da Brigada de Cerro Oeste, que fica na Serra Gris.', 0),
(11999, 'ptBR', 'Vasculhe os cadáveres', 'Encontre os Planos dos Jardins Lua Serena e entregue-os à Imagem do Arquimago Aethas Fendessol, no Martelo de Agmar.', 'Os Jardins Lua Serena, a sudoeste daqui, são o local de descanso final de um nobre grupo de elfos altaneiros. São também um poderoso nexus de linhas do meridiano.$B$BA revoada azul usou uma ferramenta mágica chamada agulha de mana para destruir o nexus, liberando o poder ali contido para ser utilizado a seu bel-prazer.$B$BEu preciso de mais informações a respeito, e é você quem vai consegui-las para mim.$B$BDepois que a terra foi destruída perto das ruínas, os fantasmas dos Altaneiros se ergueram e dizimaram metade dos caça-magos presentes. Procure por pistas nos cadáveres.', '', '', '', '', '', '', '', '', '', 'Volte à Imagem do Arquimago Aethas Fendessol no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12000, 'ptBR', 'Vasculhe os cadáveres', 'Encontre os Planos dos Jardins Lua Serena e entregue-os para a Imagem da Arquimaga Modera, no Recanto das Estrelas.', 'Os Jardins Lua Serena, a sudoeste daqui, são o local de descanso final de um nobre grupo de elfos Altaneiros. São também um poderoso nexus de linhas do meridiano.$B$BA revoada azul usou uma ferramenta mágica chamada agulha de mana para destruir o nexus, liberando o poder ali contido para ser utilizado a seu bel-prazer.$B$BEu preciso de mais informações a respeito, e espero que você as consiga para mim.$B$BDepois da revolta nas ruínas, os fantasmas dos Altaneiros se ergueram e dizimaram metade dos caça-magos presentes. Procure por pistas nos cadáveres.', '', '', '', '', '', '', '', '', '', 'Fale com a Imagem da Arquimaga Modera no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12002, 'ptBR', 'Irmãos na batalha', 'Mate 10 Golens de Batalha Rúnicos e fale novamente com Brugar Rasgalito, no Acampamento da Brigada de Cerro Oeste.', 'Espero que Gryan saiba que eu retirei meus homens de Thor Modan quando a batalha começou. Não há a menor chance de nós escavarmos qualquer coisa até que aquele lugar se acalme.$B$BVocê parece ser do tipo corajoso, porém, e já conquistou a confiança de Gryan.$B$BThor Modan fica logo a nordeste daqui, e a batalha entre nossos irmãos terranos e as criações daqueles malditos anões de ferro ainda arde feroz. Ajude nossos irmãos a virar a maré da guerra. Eu me ocuparei em descobrir como fazer a exploração de Thor Modan.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Brugar Rasgalito no Acampamento da Brigada de Cerro Oeste, que fica na Serra Gris.', 0),
(12003, 'ptBR', 'Descobrindo os túneis', 'Brugar Rasgalito no Acampamento da Brigada de Cerro Oeste quer que você explore o Edifício Norte, o Edifício Leste e o Edifício Sul de Thor Modan.', 'Começaremos a procurar as aberturas do sistema de túneis de Thor Modan pelos prédios próximos.$B$BQuando abandonei o local com meus homens, tive a impressão de que os anões de ferro defensores estavam se refugiando dentro das construções. Tome cuidado ao explorá-las.$B$BAs entradas de túneis, se houver, provavelmente ficam no fundo das edificações. Não sei muito bem o que Mantoforte acha que vai encontrar lá embaixo, mas duvido que os anões de ferro facilitarão a busca.', '', 'Investigue o Edifício Norte', 'Investigue o Edifício Leste', 'Investigue o Edifício Sul', '', '', '', '', '', 'Fale novamente com Brugar Rasgalito no Acampamento da Brigada de Cerro Oeste, que fica na Serra Gris.', 0),
(12004, 'ptBR', 'Impeça o acordo', 'Entregue os Restos do Mercador do Vento Mu\'fah e as Escamas de Goramosh para a Imagem da Arquimaga Modera, no Recanto das Estrelas.', 'Precisamos matar dois coelhos com uma cajadada só, $c. Você será o cajado.$B$BNossos dois coelhos são o Mercador do Vento Mu\'fah e Goramosh. Eles devem estar na parte oeste dos Jardins Lua Serena. Provavelmente, na construção de dois andares acima do fosso.$B$BSolicito uma prova da morte deles, se me fizer a gentileza.', '', '', '', '', '', '', '', '', '', 'Fale com a Imagem da Arquimaga Modera no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12005, 'ptBR', 'Impeça o acordo', 'Entregue os Restos do Mercador do Vento Mu\'fah e as Escamas de Goramosh para a Imagem do Arquimago Aethas Fendessol, no Martelo de Agmar.', 'Precisamos matar dois coelhos com uma cajadada só, $c. Você será o cajado.$B$BNossos dois coelhos são o Mercador do Vento Mu\'fah e Goramosh. Eles devem estar na parte oeste dos Jardins Lua Serena. Provavelmente, na construção de dois andares acima do fosso.$B$BSolicito uma prova da morte deles, se possível.', '', '', '', '', '', '', '', '', '', 'Volte à Imagem do Arquimago Aethas Fendessol no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12006, 'ptBR', 'Vingue essa atrocidade!', 'Mate 15 inimigos, entre Caça-magos do Ermo das Serpes, Espreitadores da Lua Serena, Feiticeiros da Agulha de Mana e Teurgos de Concentração. Quando cumprir a missão, fale com Ethenial Umbraluna, nos Jardins Lua Serena.', 'Esses caça-magos vieram aqui e destruíram nosso local de descanso.$B$BVingue-nos, ou eu farei com que sua base de operações seja sufocada pelos espíritos dos mortos!', '', 'Forças da Revoada Azul nos Jardins Lua Serena derrotadas', '', '', '', '', '', '', '', 'Fale novamente com Ethenial Umbraluna nos Jardins Lua Serena, no Ermo das Serpes.', 0),
(12007, 'ptBR', 'Se é pelo bem de todos...', 'Drakuru quer que você leve o Olho dos Profetas para ele no Braseiro de Drakuru em Zeb\'Halak.$b$bColete o Mojo do Zim\'bo para poder usar o Elixir do Drakuru lá.', 'Saquei, cara!$b$bA norte daqui, no zigurate em Zeb\'Halak, tem uma cabeça de pedra com olhos de rubi. Um desses olhos é o Olho dos Profetas! Leva ele pro braseiro por lá e bebe o meu elixir.$b$bPra variar, cê vai precisar de mojo pro elixir funcionar... Dessa vez, do chefão, Zim\'bo. Ele tá malocado numa das cabanas em Zeb\'Halak.$b$bÉ pena matar o Zim\'bo, cara, mas ele jurou com sangue que ia defender Drak\'Tharon e deu muito mole. Agora pelo menos o mojo dele vai ajudar a gente a recuperar Drak\'Tharon.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Imagem de Drakuru em Zeb\'Halak, na Serra Gris.', 0),
(12008, 'ptBR', 'O Martelo de Agmar', 'Vá para o Martelo de Agmar, que fica no Ermo das Serpes, e fale com o Lorde Supremo Agmar.', 'A leste deste campo de refugiados fica o Martelo de Agmar, um testemunho do poder da Horda no Ermo das Serpes.$B$BNão tenho dúvidas de que nossos irmãos e irmãs da Horda já podem ver os resultados dos seus esforços em trazer os taunkas para o nosso lado. Mas ainda assim, quero que você dê pessoalmente a notícia do seu êxito para o Lorde Supremo Agmar.$B$BVá, $n! Cavalgue os ventos! Para leste, para o Martelo de Agmar!', '', '', '', '', '', '', '', '', '', '', 0),
(12009, 'ptBR', 'Armadilhas para caranguejo de Tua\'kea', 'Colete 8 Armadilhas para Caranguejo de Tua\'kea e devolva-as para ele no Porto Moa\'ki.', 'Além de todos esses problemas, eu perdi meus assistentes. Queria saber se você poderia me ajudar.$B$BEu tenho um monte de armadilhas para caranguejo debaixo d\'água, no porto. Você as recuperaria pra mim? Estou velho demais pra essas aventuras, e as águas podem ser muito perigosas.$B$BPor favor, leve essa bexiga. Com ela você pode respirar embaixo d\'água.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tua\'kea no Porto Moa\'ki, que fica no Ermo das Serpes.', 0),
(12010, 'ptBR', 'O destino de Orlond', 'Encontre o Topógrafo Orlond dentro de Thor Modan.', 'Quando começamos as escavações da cidade, mandei o Topógrafo Orlond para verificar a estabilidade dos túneis de Thor Modan. Eu não o vi escapar quando nos retiramos, depois que a batalha começou. Estou preocupado com a possibilidade dele ainda estar preso dentro da cidade.$B$BSe quisermos passar com um exército por Thor Modan, precisamos das informações que Orlond estava coletando. Mantoforte e os superiores dele arrancariam meu couro se os túneis desabassem sobre as brigadas!', '', '', '', '', '', '', '', '', '', '', 0),
(12011, 'ptBR', 'Sinais de encrenca na água', 'Informe Tua\'kea, no Porto Moa\'ki, sobre a armadilha para caranguejos destruída.', 'Uma das armadilhas parece ter sido destruída por algo muito maior que os tubarões próximos.$B$BTalvez Tua\'kea, o pescador do Porto Moa\'ki, deva ser informado.', '', '', '', '', '', '', '', '', '', '', 0),
(12012, 'ptBR', 'Informe o ancião', 'Vá para a capital e fale com o Ancião da Harmonia Telúrica.', 'Essa informação precisa ser espalhada por toda a Harmonia Telúrica. Eu não sei ao certo como proceder, mas o ancião que te enviou nessa jornada deve saber. Fale novamente com o ancião e descubra o nosso próximo passo. Nós precisamos fazer alguma coisa!', '', '', '', '', '', '', '', '', '', '', 0),
(12013, 'ptBR', 'Acabe com Arcanimus', 'Destrua Arcanimus e, então, fale novamente com Ethenial Umbraluna, que fica nos Jardins Lua Serena.', 'Há mais uma coisa que eu quero que você faça, $r. Quero que você destrua Arcanimus!$B$BOs feiticeiros a oeste daqui usaram aquele dispositivo gigante no céu para escavar um fosso descomunal em nosso local de descanso. Com isso, eles libertaram uma monstruosidade!$B$BEu não me importaria se fosse um problema só dos mortais, mas Arcanimus se alimenta das almas dos mortos.$B$BVocê dará um basta nisso agora mesmo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ethenial Umbraluna nos Jardins Lua Serena, no Ermo das Serpes.', 0),
(12014, 'ptBR', 'Firme como uma rocha?', 'Recupere o Sismógrafo Portátil, use-o para tomar leituras de estabilidade em Thor Modan, e então fale novamente com Brugar Rasgalito no Acampamento da Brigada de Cerro Oeste.', 'As anotações de Orlond dão a entender que ele trouxe um equipamento chamado sismógrafo portátil, mas o aparelho não está por perto.$B$BOs registros topográficos indicam que Orlond completou todas as leituras do túnel de Thor Modan menos uma, rotulada "extremo leste do túnel exposto".$B$BA última anotação afirma que Orlond tentou se refugiar na água e foi atacado por manguais subterrâneos. Os monstros podem ter levado o equipamento. Você terá que recuperá-lo se quiser fazer a última leitura.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Brugar Rasgalito no Acampamento da Brigada de Cerro Oeste, que fica na Serra Gris.', 0),
(12016, 'ptBR', 'A isca', 'Consiga a Carne de "Duas Pinças Enormes" e entregue-a para Tua\'kea, no Porto Moa\'ki.', 'Tenho certeza... nosso antigo inimigo aquático, Tu\'u\'gwar, "O Que Brinca com a Comida", voltou. Precisamos armar uma armadilha pra ele.$B$BTu\'u\'gwar morre pela boca. Existe uma carne que ele acha irresistível.$B$BKili\'lua "Duas Pinças Enormes", a mãe de todos os caranguejos, habita em uma ilha nas águas a sudoeste daqui. Vá visitá-la e depois volte aqui com a carne dela.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tua\'kea no Porto Moa\'ki, que fica no Ermo das Serpes.', 0),
(12017, 'ptBR', 'Carne no anzol', 'Mate Tu\'u\'gwar e então fale novamente com Tua\'kea, no Porto Moa\'ki.', 'A hora chegou, $Gmeu amigo:minha amiga;, precisamos dar jeito em Tu\'u\'gwar!$B$BJá preparei a carne. Assim que você jogar o anzol com a carne na água, ele virá com certeza. É só seguir a linha de pesca até lá embaixo.$B$BO que quer que você faça, não deixe Tu\'u\'gwar te engolir $Ginteiro:inteira;, $n!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tua\'kea no Porto Moa\'ki, que fica no Ermo das Serpes.', 0),
(12019, 'ptBR', 'Últimos ritos', 'Vá para a Cidade-Templo de En\'kilah e encontre a orbe de teleporte abaixo da cidade Flagelo de Naxxnar. Use-a para chegar até o topo e ajude Thassarian lá.', 'Servi a Arthas na morte, pois não tive outra escolha. Ele tinha controle sobre meu corpo e minha vontade. A Seita dos Malditos serve a Arthas em vida... por vontade própria.$B$BAgora que você sabe as palavras de poder para entrar em Naxxanar, podemos dar um fim à influência dos sectários. Vá para En\'kilah e procure o orbe de teleporte abaixo da cidade flutuante.$B$BVá e encontre-me lá em cima. Arme-se com toda coragem que puder. Podemos não sair vivos dessa.', '', 'Últimos ritos', '', '', '', '', '', '', '', 'Procure Thassarian em Naxxanar, na Tundra Boreana.', 0),
(12020, 'ptBR', 'Certa vez, quando eu estava bêbado...', 'Fale com Caxias Girafuso na CervaFest.', 'Os Ferro Negro levaram uma surra! E, durante a fuga desembestada para o Glutão Implacável, uma peça do veículo deles caiu. O mais importante é que você ajudou a manter a CervaFest segura... pelo menos por hoje.$b$bConte para o Caxias sobre a sua incrível vitória sobre os anões Ferro Negro.', '', '', '', '', '', '', '', '', '', '', 0),
(12022, 'ptBR', 'Caneco no boneco!', 'Use a Amostra sem Álcool da CervaFest para acertar o B.I.R.I.T.A. 5 vezes. Depois, fale com Caxias Girafuso.', 'Olá! Pelo jeito você entende de cerveja. Será que também entende de canecos?$b$bOs anões Ferro Negro estão de volta e querem arruinar o festival por vingança. O melhor jeito de acabar com esses encrenqueiros é tacar uns canecos direto na cabeça deles! Mas, antes de qualquer coisa, vamos ver se você consegue jogar um caneco no nosso velho B.I.R.I.T.A.$b$bÉ fácil: basta pegar uma prova de cerveja sem álcool, beber um gole, se virar para o B.I.R.I.T.A. e tacar o caneco nele! Volte aqui depois de acertá-lo cinco vezes.', '', 'B.I.R.I.T.A. atingido', '', '', '', '', '', '', '', 'Fale novamente com Caxias Girafuso em Dun Morogh.', 0),
(12026, 'ptBR', 'O diário danificado', 'Recupere 8 Páginas Perdidas do Diário, combine-as com o Diário Incompleto e entregue o diário completo à Sábia Paluna na Aldeia Oneqwah.', 'Este diário gasto e enlameado já viu dias melhores. Folheando pelas páginas, você descobre dúzias de anotações, diagramas e mapas em linguagem enânica.$B$BA única coisa que você consegue decifrar é o nome de Brann Barbabronze rabiscado em uma das anotações.$B$BA metade final do livro, contendo as anotações mais recentes, foi arrancada. Alguém achou que as anotações eram importantes o suficiente para serem destruídas. Talvez as páginas perdidas no campo de batalha possam revelar alguma pista.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sábia Paluna na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12027, 'ptBR', 'As Perigosas Peripécias do Sr. Pinote', 'Ajude Emília e o Sr. Pinote a voltar ao Acampamento da Brigada de Cerro Oeste, e então fale com o Escudeiro Walter.', 'Com licença, $gmoço:moça;, $go senhor:a senhora; sabe o caminho de volta até o acampamento dos soldados?$B$BO Sr. Pinote e eu saímos para passear na floresta, e aí o meu irmão Walter vinha com a gente, mas aí ele tinha umas coisas de escudeiro pra fazer.$B$BEntão aí o Sr. Pinote e eu saimos sozinhos, mas aí a gente se perdeu, e tinha um montão de lobos com fome, mas aí a gente achou essa torre.$B$BEntão os lobos foram embora, mas a gente ainda tá perdido.$B$BEu perguntei pro Sr. Pinote, e ele não sabe o caminho de volta. $GO senhor:A senhora; pode ajudar a gente? Por favor?', 'Ajude Emília e o Sr. Pinote a voltar ao acampamento.', '', '', '', '', 'Ajude Emília e o Sr. Pinote a voltar ao acampamento.', '', '', '', 'Fale com o Escudeiro Walter no Acampamento da Brigada de Cerro Oeste, que fica na Serra Gris.', 0),
(12028, 'ptBR', 'Iluminação espiritual', 'Fale com Toalu\'u, o Místico, no Porto Moa\'ki, quando obtiver a iluminação espiritual.', '$R, estamos sem notícias de nosso povo na Aldeia Indu\'le desde que o chão tremeu e se partiu!$B$BVocê já fez uma peregrinação espiritual? Você derrotou Loguhn, então acho que é capaz.$B$BEu lhe darei um incenso especial para ser jogado no meu braseiro. Inale os vapores e seu espírito ascenderá e testemunhará o que aconteceu em Indu\'le.$B$BE eu poderei ver através dos seus olhos.', 'Iluminação espiritual a respeito da Aldeia Indu\'le obtida.', '', '', '', '', 'Iluminação espiritual a respeito da Aldeia Indu\'le obtida.', '', '', '', 'Fale novamente com Toalu\'u, o Místico, no Porto Moa\'ki, que fica no Ermo das Serpes.', 0),
(12029, 'ptBR', 'Churrasco de Flagelo', 'Mack, nas Fontes Graníticas, quer que você use o grogue dele para queimar 20 Trolls Esfomeados do Flagelo em Drak\'Tharon.', '<Hic>... Eu tchenho qui queimá essish cadarves antish qui elish começa a andá por aí di novo.$b$bMeu papai shempre me disse: a única coisa pió qui matá um troll é matá um troll duash vezhes.$b$bÓ só, <hic>... Falano em Fragelo, a gente não podemosh entrá naquela fortaleza troll pras bandash do norte enquanto tivé tanto troll por lá.$b$bQue tal vochê pegá um pouco do meu grogue aqui e tacá fogo naquelesh mardito?', '', 'Trolls do Flagelo queimados', '', '', '', '', '', '', '', 'Fale novamente com Mack Fearsen nas Fontes Graníticas, na Serra Gris.', 0),
(12030, 'ptBR', 'Ancião Mana\'loa', 'Fale com a estátua do Ancião Mana\'loa, na Aldeia Indu\'le.', 'Meu povo...$B$B<O ancião parece prestes a ter um colapso.>$B$BEnquanto o seu espírito voava pela aldeia, eu senti que o Ancião Mana\'loa percebeu sua presença. $n, ele deseja falar com você. Os anciãos de pedra são reverenciados por nós como fontes de sabedoria ancestral.$B$BO ancião provavelmente quer nos ajudar. Procure por ele no canto noroeste da aldeia.', '', '', '', '', '', '', '', '', '', '', 0),
(12031, 'ptBR', 'Liberdade para os espíritos', 'Dê o descanso final a 15 aldeões Indu\'le, dentre Pescadores, Místicos e Guerreiros. Então fale com o Ancião Mana\'loa na Aldeia Indu\'le.', 'O solo sagrado dos elfos a leste daqui foi rasgado. Agora, a magia élfica grassa pela terra, causando ruína onde quer que vá.$B$BAs almas dos Kalu\'ak estão ameaçadas, pois a revoada azul está tentando controlar a magia.$B$BO poder irrompeu do lago, matando quase toda a aldeia instantaneamente. Os que sobreviveram ficaram loucos.$B$BLiberte os espíritos, $n, para que eles possam seguir caminho. Deixe os loucos vivos em paz, pois eles ainda podem recobrar a sanidade.', '', 'Espíritos Indu\'le apaziguados', '', '', '', '', '', '', '', 'Fale novamente com o Ancião Mana\'loa na Aldeia Indu\'le, que fica no Ermo das Serpes.', 0),
(12032, 'ptBR', 'Conversando com as profundezas', 'Invoque Oacha\'noa com a Pérola das Profundezas e faça o que a deusa do mar ordenar.$B$BSe você sobreviver à prova, fale novamente com Toalu\'u, o Místico, no Porto Moa\'ki.', 'A deusa aquática, Oacha\'noa, deve ser consultada; somente ela saberá qual será o destino dos Kalu\'ak. Somente a Pérola das Profundezas pode trazê-la do abismo obscuro.$B$BPerto da costa, a sudoeste daqui, se ergue o Morro Salgado. No topo do morro fica o altar em que a pérola se encontra.$B$BInvoque Oacha\'noa no altar, e ela com certeza ouvirá o seu chamado. Faça o que ela mandar, ou você atrairá sua fúria e trará ruína para todos os morsanos.$B$BSe você sobreviver, fale com o místico novamente.', 'Injunção de Oacha\'noa obedecida', '', '', '', '', 'Injunção de Oacha\'noa obedecida', '', '', '', 'Fale novamente com Toalu\'u, o Místico, no Porto Moa\'ki, que fica no Ermo das Serpes.', 0),
(12033, 'ptBR', 'Mensagem do oeste', 'Leia a Carta de Saurfang e, depois, destrua-a.$B$BFale com o Mensageiro Torvus ao completar essa tarefa.', '<Torvus aperta sua mão, ao mesmo tempo em que passa uma carta para você.>$B$B<Torvus sussurra.>$B$BNão faça alarde, $n.$B$BÉ bom ver você aqui, combatente! Lorde Grito Infernal sem dúvida enviou os guerreiros mais fortes para Lorde Agmar!$B$B<Torvus sussurra.>$B$BLeia e queime na pira aqui ao lado.', 'Carta de Saurfang lida e destruída', '', '', '', '', 'Carta de Saurfang lida e destruída', '', '', '', 'Fale com o Mensageiro Torvus, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12034, 'ptBR', 'A vitória se aproxima', 'Fale com o Primeiro-Sargento Juktok, que fica no Martelo de Agmar.', 'Só restam duas ameaças em nosso caminho. Uma é a horrenda cidadela de Naxxramas, a leste daqui, acima da fortaleza da Aliança de Invergarde, e a outra é o Fosso de Narjun, o ponto de escoamento dos exércitos de mortos-vivos de Azjol\'Nerub. Foi partindo do Fosso de Narjun que os nerubianos de Anub\'ar atacaram e destruíram a aldeia taunka da Bruma Boreal.$B$BNós vamos destruir os Anub\'ar e lacrar o Fosso de Narjun.$B$BApresente-se ao Primeiro-Sargento Juktok para receber suas ordens.', '', '', '', '', '', '', '', '', '', '', 0),
(12035, 'ptBR', 'Tecnologia reobjetivada', 'Jeremias Ranieri, em Algures, quer que você destrua 5 Golens Colheiteiros e use as Ferramentas do Jeremias para reprogramá-los.', 'Certo, já entendi! Trocar os fios é um pouco complicado, mas nada que $Gum talentoso:uma talentosa; $c como você não consiga fazer.$B$BPegue minhas ferramentas e desative alguns colheiteiros. Depois, use-as para ligar todos os fios vermelhos nas tomadas azuis. Isso vai fazer com que entrem em modo de autodefesa. Vamos logo, $n. Daqui a pouco não vamos ter mais nada pra salvar!', '', 'Golem Colheiteiro reprogramado', '', '', '', '', '', '', '', 'Fale novamente com Jeremias Ranieri em Algures, na Tundra Boreana.', 0),
(12036, 'ptBR', 'Das profundezas de Azjol-Nerub', 'Explore o Fosso de Narjun e reporte suas descobertas para o Primeiro-Sargento Juktok no Martelo de Agmar.', 'Os mortos-vivos nerubianos que atacaram a Aldeia Bruma Boreal vieram de uma fossa conhecida como Fosso de Narjun. Se não forem interceptados, esses demônios certamente irão flanquear nossas forças no Portão da Ira e porão um fim à nossa marcha para a vitória.$B$BPreciso de um bom par de olhos, $n. Siga para o oeste e investigue o Fosso de Narjun. Precisamos localizar o ponto principal de escoamento deles, e bloqueá-lo. Encontre esse ponto.', 'Fosso de Narjun explorado', '', '', '', '', 'Fosso de Narjun explorado', '', '', '', 'Fale com o Primeiro-Sargento Juktok, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12037, 'ptBR', 'Busca e resgate', 'Mack, nas Fontes Graníticas, quer que você entre em Drak\'Tharon e descubra o que houve com Kurzel.', 'Essas orquisas... Elash nunca eshcutam... <hic>. Sabe cumé qui é, $r.$b$bA Kurzel já tá com a gente fash unsh anos. Era de se penshar que ela já tinha entendido como qui a gente trabalha. A gente atrai osh otário pra fazer o trabalho perigoso, e então colhe ash recompensash quando é sheguro. O qui tem de complicado nisso?$b$bMas ela num intende... a pele-verde impacientchi sai por aí fashendo o trabalho com as própriash mãosh. Ela provavelmente tá morta, mas eu me sentiria péshimo se a gente não foshe atrás dela. Só que eu não estou em condições de ir pessoalmente... <hic>.$b$bEntão, o que cê me diz, camarada?', '', '', '', '', '', '', '', '', '', '', 0),
(12038, 'ptBR', 'Churrasco de Flagelo', 'Mack, nas Fontes Graníticas, quer que você use o grogue dele para queimar 30 Trolls Esfomeados do Flagelo.', 'Tá eshperando o quê, $c? Aquelesh trolls frageladosh não vão shi queimá a shi mezhmosh!$b$bVochê shabe como é. Vai lá pra Drak\'Tharon, no norte... Leva um pouco do meu grogue aqui e taca neles de longe... <hic>. Então é shó shentá e olhá elesh queimano.', '', 'Trolls do Flagelo queimados', '', '', '', '', '', '', '', 'Fale novamente com Mack Fearsen nas Fontes Graníticas, na Serra Gris.', 0),
(12039, 'ptBR', 'O sangue negro de Yogg-Saron', 'Borus Dobraferro, no Martelo de Agmar, no Ermo das Serpes, quer que você recupere 10 Amostras de Sangue Negro de Yogg-Saron.', 'Angrathar, o Portão da Ira... Eu vi o metal do portão pulsando e ondulando como se estivesse vivo! Em 50 anos, nunca vi um metal "respirar".$B$BSó os morsanos sabiam algo a respeito. Eles o chamavam de "Sangue Negro de Yogg-Saron", e disseram que eu devia manter distância.$B$BExiste um buraco chamado Fosso de Narjun fora da Aldeia Bruma Boreal. Ouvi falar que nesse buraco há bastante desse minério estranho. Se você estiver indo praquele lado, pode me trazer algumas amostras?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Borus Dobraferro no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12040, 'ptBR', 'Inimigo comum', 'Kilix, o Desfiador, no Fosso de Narjun, no Ermo das Serpes, quer que você mate 6 Sublordes Anub\'ar.', 'Estamos no meio de uma guerra civil. No coração deste mundo, os últimos representantes da minha espécie se defendem contra a aniquilação total. O Lich Rei busca dominar o reino de Azjol-Nerub a qualquer custo. Os que não abaixam a cabeça se tornam inimigos do Flagelo e são marcados pra morrer.$B$BArthas é nosso inimigo comum...$B$BAjude nossa causa e livre este local da mácula de Anub\'ar! Que o próprio Anub\'arak escute a angústia dos gritos de morte!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kilix, o Desfiador, no Fosso de Narjun, que fica no Ermo das Serpes.', 0),
(12041, 'ptBR', 'O Império perdido', 'Entregue o Plano de Batalha de Kilix ao Lorde Supremo Agmar no Martelo de Agmar, no Ermo das Serpes.', 'Você provou estar $gdisposto:disposta; a ajudar o Império Azjol nesses tempos difíceis. Assim sendo, o Império Azjol ajudará a Horda.$B$BLeve esse pergaminho de volta para seu líder. Nele estão listados os pontos fortes e fracos dos nerubianos atacando a Aldeia Bruma Boreal. Considere um gesto de boa vontade. Um sinal de nossa predisposição em ajudar o seu povo. Use essas informações para esmagar os Anub\'ar, e você nos terá feito a todos um grande favor.$B$BAdeus, $r.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Lorde Supremo Agmar no Martelo de Agmar, no Ermo das Serpes.', 0),
(12042, 'ptBR', 'Coração dos antigos', 'Drakuru quer que você vá à câmara mais alta da Madeireira Céu Azul e encontre o Coração dos Antigos.', 'Segredos das eras, se revela pra mim agora!$b$b<Drakuru espia pelo Olho dos Profetas.>$b$bAaah, meu destino vai ser o bicho, $n. Cê tem sorte de me conhecer...$b$bAchei! Tô vendo, cara. O Coração dos Antigos. Mas que moleza!$b$bO coração tá jogado perto do presunto dum goblin, a leste daqui. Ele tá lá numa câmara, perto de um rio de árvores quebradas.$b$bCorre, cara, antes que algum mané ache a parada.', '', '', '', '', '', '', '', '', '', '', 0),
(12043, 'ptBR', 'Em Defesa do Posto Ferrugem', 'Mate 12 Escavadores dos Ermos e 1 Capataz dos Ermos nas escavações próximas do Repouso de Galakrond. Fale novamente com Narf, no Posto Ferrugem, quando completar a tarefa.', 'Aí, $c! Os mortos-vivos ao sul daqui continuam atrapalhando nosso trabalho. Vai lá falar com eles, vai?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Narf no Posto Ferrugem, que fica no Ermo das Serpes.', 0),
(12044, 'ptBR', 'Farmácia particular', 'Colete 8 montes de Minério Composto dos buracos próximos ao Repouso de Galakrond, e leve-os para Xink, no Posto Ferrugem.', 'Oi, oi! O Flagelo tá na área mais pro sul, cavando uns troços velhos de dragão. Não dou a mínima pro que eles tão fazendo, mas parece que tem muito minério sendo escavado no processo, e isso muito me interessa.$B$BPega lá alguns minérios pra mim. Deve dar pra levantar um belo faz-me-rir com a Horda, que está precisando de metal pra forjar armas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Xink no Posto Ferrugem, que fica no Ermo das Serpes.', 0),
(12045, 'ptBR', 'Estilhaços de gelo', 'Colete 4 Drusas de Estilhaços de Gelo dos Elementais de Gelo ao norte e leve-as para Zivlix, no Posto Ferrugem.', 'Eu nunca vi você antes... você é $gnovo:nova; por aqui? Prazer. Eu sempre preciso de mais gente.$B$BVocê me consegue os materiais, eu completo minha máquina, vendo ela pros figurões lá e todo mundo vai pra casa rico.$B$BEu já tenho todos os componentes primários, então na verdade eu só preciso dos materiais da arma. O Narf me falou que as lascas de gelo pontudas daqueles elementais ao norte daqui dariam estilhaços perfeitos pras minhas bombas. Porque você não vai lá e pega alguns pra mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zivlix, no Posto Ferrugem, que fica no Ermo das Serpes.', 0),
(12046, 'ptBR', 'Invólucro macio', 'Colete 12 Pelegos Animais Finos dos Escavadores Yormungar ou dos Condores Dracósseos perto do Posto Ferrugem. Quando conseguir os pelegos, leve-os para Zivlix.', 'Preciso de um novo invólucro para as bombas de estilhaço. O que eu tenho aqui é muito rígido, e os estilhaços não se espalham quando a bomba explode.$B$BA gente precisa do couro fino de algum bicho. Aqueles yormungares escavadores a oeste daqui podem servir... ou aqueles condores que ficam bicando os ossos dos dragões. Traz pra mim o que você encontrar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zivlix, no Posto Ferrugem, que fica no Ermo das Serpes.', 0),
(12047, 'ptBR', 'Algo que não derreta', 'Procure por 12 Pedaços de Osso Estilhaçado nos ossos de dragão a leste do Posto Ferrugem.', 'Não, não, não! Esses estilhaços não vão funcionar de jeito nenhum! Eles vão derreter antes de causar qualquer estrago. Essa foi a última vez que eu confiei na opinião do Narf a respeito de matérias-primas. Quer dizer que precisamos de uma coisa completamente diferente pra servir de estilhaço.$B$BJá sei! Eu sou brilhante. Lascas de osso.$B$BTem um monte de ossos por aqui que os yormungares vivem mastigando. Vá dar uma vasculhada e veja se me acha alguns ossos partidos que eu possa usar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zivlix, no Posto Ferrugem, que fica no Ermo das Serpes.', 0),
(12048, 'ptBR', 'Armamentos do Flagelo', 'Borus Dobraferro, no Martelo de Agmar, no Ermo das Serpes, quer que você colete 8 Armamentos do Flagelo.', 'Não consigo forjar nada com esse minério! Não dá liga! Tentei tudo, mas esse metal não dobra!$B$BSe tivesse acesso a algumas amostras de armamentos do Flagelo forjados com esse metal, eu poderia fazer engenharia reversa e descobrir o processo que criou esses itens.$B$BA Aldeia Bruma Boreal está cheia de nerubianos do Flagelo usando armaduras. Vá até lá e me consiga alguns armamentos do Flagelo! Com sua ajuda, eu talvez possa criar alguma coisa com esse minério.$B$BA Aldeia Bruma Boreal fica a oeste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Borus Dobraferro no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12049, 'ptBR', 'Duro de engolir', 'Lute com um Yormungar Imponente a leste do Posto Ferrugem até que ele abra a boca, então jogue uma Carga Explosiva Potente na garganta do verme. Quando o verme explodir, colete 6 nacos de Carne de Yormungar Queimada do chão e leve-os de volta para Xink.', 'As tropas com certeza vão precisar de muita comida pra continuar na campanha.$B$BDeixa eu te contar um segredo que gente da sua raça pode achar meio nojento... aqueles vermes yormungares têm gosto de frango.$B$BSiga para o leste e puxe briga com um bichão yormungar. Você não vai conseguir matá-los assim de cara. É melhor você jogar isso aqui na garganta deles, quando abrirem a boca. Me traga todos os nacos de carne que você conseguir carregar pra cá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Xink no Posto Ferrugem, que fica no Ermo das Serpes.', 0),
(12050, 'ptBR', 'Madeeeira!', 'Use o Dispositivo de Controle de Retalhador do Xink para convocar um Retalhador, quando você chegar aos Ninhos das Harpias, ao Norte. Colete 50 montes de Madeira das árvores da área, e então fale novamente com Xink, no Posto Ferrugem.$B$BSe você perder o Dispositivo de Controle de Retalhador, peça outro para Xink, no Posto Ferrugem.', 'Agora a gente precisa trazer madeira pras torres da Aliança. Tem umas árvores finas mais pro sul, mas as árvores onde as harpias fazem ninho, ao norte, são melhores para construção.$B$BPega isso. Quando você chegar na área em que as harpias moram, use o controle e um dos meus Retalhadores irá até você. Junte quanta lenha puder carregar. As harpias não vão achar legal você derrubar as casas delas – você dá um jeito nisso também.$B$BAgora vai!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Xink no Posto Ferrugem, que fica no Ermo das Serpes.', 0),
(12052, 'ptBR', 'Não passarão, passarinhos!', 'Mate a Senhora do Vento Frio e 15 Harpias do Vento Frio nas montanhas a noroeste do Posto Ferrugem. Fale novamente com Narf quando completar a tarefa.$B$BSe precisar do Dispositivo de Controle de Retalhador, peça para Xink no Posto Ferrugem.', '$C, você viu aquilo? É a harpia que lidera os ataques aos nossos carregamentos para o portão! Eu a vi lá pelo Planalto Vento Frio.$B$BChega dessas harpias reduzindo nossos lucros! Mate todas elas.', '', '', 'Harpias do Vento Frio', '', '', '', '', '', '', 'Fale novamente com Narf no Posto Ferrugem, que fica no Ermo das Serpes.', 0),
(12053, 'ptBR', 'A força da Horda', 'O Primeiro-Sargento Juktok, no Martelo de Agmar, no Ermo das Serpes, quer que você finque o Estandarte de Batalha do Brado Guerreiro na Aldeia Bruma Boreal, e o defenda dos agressores.$B$BDevolva o Estandarte de Batalha do Brado Guerreiro quando terminar a missão.', 'Os taunkas agora são nossos irmãos em armas. Devemos mostrar solidariedade e reconquistar a Aldeia Bruma Boreal.$B$BVocê vai encontrar a Aldeia Bruma Boreal a oeste do Martelo de Agmar, no sopé das montanhas. Viaje até lá e desafie os nerubianos de Anub\'ar! Finque nosso amado estandarte na Aldeia Bruma Boreal e destrua todos os que tentarem rasgá-lo!$B$BQue os Anub\'ar sintam toda a força da Horda! Que nosso estandarte seja a última coisa que eles vejam antes de morrer!', 'Estandarte de Batalha do Brado Guerreiro defendido', '', '', '', '', 'Estandarte de Batalha do Brado Guerreiro defendido', '', '', '', 'Fale com o Primeiro-Sargento Juktok, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12054, 'ptBR', 'Decifrando o diário', 'Traga um ramo de Halispírito para Sábia Paluna na Aldeia Oneqwah.', 'Vor\'takh está certo: não podemos deixar esta oportunidade nos escapar.$B$BFelizmente, acho que conheço um jeito de traduzir o diário do tal Brann.$B$BOs xamãs dos pelursos da Presa Vermelha, que se reúnem na Ermida Verossangue, ao sul da aldeia, cultivam uma erva chamada halispírito. Um místico experiente pode usar incenso feito com a erva para buscar a sabedoria dos espíritos antepassados.$B$BProcure o xamã conhecido como Grumbald Caolho. Ele certamente usa a erva nos ritos de devoção a Ursoc.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sábia Paluna na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12055, 'ptBR', 'Um dispositivo estranho', 'Entregue o Dispositivo Estranho de Goramosh para a Imagem da Arquimaga Modera no Recanto das Estrelas.', 'Ao examinar o dispositivo estranho, você percebe que ele é mágico. Infelizmente, não dá para depreender qual seria seu uso.$B$BTalvez a arquimaga no Recanto das Estrelas, a leste dos Jardins Lua Serena, possa descobrir como usar o dispositivo.', '', '', '', '', '', '', '', '', '', 'Fale com a Imagem da Arquimaga Modera no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12056, 'ptBR', 'Marcado para Morrer: Grão-sectário Zangus', 'Mate o Grão-sectário Zangus e leve a Cabeça do Grão-sectário Zangus para o Capitão Gort no Martelo de Agmar, que fica no Ermo das Serpes.', 'Testemunhei sua traição com meus próprios olhos! O traidor liderou um assalto de Anub\'ar a esta bastilha, em que morreram alguns dos meus melhores soldados.$B$B<Gort sacode a cabeça.>$B$BEle estava com o Flagelo o tempo inteiro, e não fazíamos ideia! Quantos mais iguais a Zangus não existirão por aí? Nós vamos procurar por eles, e quando os encontrarmos...$B$B<Gort faz um gesto de cortar na altura do pescoço.>$B$BO primeiro na lista é Zangus. Nossos batedores informam que ele está escondido no Fosso de Narjun, a oeste daqui. Encontre-o, mate-o, me traga a cabeça dele.', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Gort, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12057, 'ptBR', 'O tomo encadernado com carne', 'Leve o Tomo Encadernado com Carne para o Capitão Gort, no Martelo de Agmar.', 'O tomo é encadernado com carne e parece estar sangrando. Ao examiná-lo, você vê páginas e páginas cheias de estranhos símbolos, que parecem escritos a sangue.$B$BQualquer que seja a informação contida nessas páginas, parece importante. Leve o tomo para o Capitão Gort, no Martelo de Agmar, a leste da Aldeia Bruma Boreal.', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Gort, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12058, 'ptBR', 'As profecias rúnicas', 'A Sábia Paluna, na Aldeia Oneqwah, quer que você decifre as três Placas Rúnicas.', 'O diário de Brann também contém um guia dos símbolos dos anões de ferro. Eu os inscrevi nesta pedra decifradora que $go:a; ajudará a entender as palavras inscritas nas placas rúnicas.$B$BDe acordo com as anotações do diário, aparentemente Brann está buscando indícios sobre a origem do povo dele. Fique de olhos abertos em busca de pistas quanto ao destino do explorador.$B$BVolte a Thor Modan, a nordeste daqui, pare diante de cada uma das placas, e use a pedra para determinar o conteúdo de cada uma. Não podemos permitir que a Aliança encontre Brann antes de nós.', '', 'Primeira Profecia Decifrada', 'Segunda Profecia Decifrada', 'Terceira Profecia Decifrada', '', '', '', '', '', 'Fale novamente com a Sábia Paluna na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12059, 'ptBR', 'Um dispositivo estranho', 'Entregue o Dispositivo Estranho de Goramosh para a Imagem do Arquimago Aethas Fendessol no Martelo de Agmar.', 'Ao examinar o dispositivo estranho, você percebe que ele é mágico. Infelizmente não dá para depreender qual seria seu uso.$B$BTalvez o arquimago, no Martelo de Agmar, a leste dos Jardins Lua Serena, possa descobrir como usar o dispositivo.', '', '', '', '', '', '', '', '', '', 'Volte à Imagem do Arquimago Aethas Fendessol no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12060, 'ptBR', 'Projeções e planos', 'Aproxime-se da Agulha de Mana flutuando acima dos Jardins Lua Serena e observe a projeção.$B$BEntão, relate o que descobrir para a Imagem da Arquimaga Modera, no Recanto das Estrelas.', 'Este é um dispositivo de teleporte. Creio que ele leva até a plataforma da agulha de mana flutuando acima dos Jardins Lua Serena, a oeste daqui.$B$BQuero que você investigue o que está havendo lá em cima. O dispositivo leva e traz, então você não vai ter que pular de volta.$B$BImagino que encontrará algum aparelho de observação lá no topo da agulha de mana.$B$BVocê poderá usar o teleportador de qualquer lugar dentro dos jardins.', '', 'Objeto na Agulha de Mana observado', '', '', '', '', '', '', '', 'Fale com a Imagem da Arquimaga Modera no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12061, 'ptBR', 'Projeções e planos', 'Aproxime-se da Agulha de Mana flutuando acima dos Jardins Lua Serena e observe a projeção.$B$BEntão relate o que descobrir para a Imagem do Arquimago Aethas Fendessol, no Martelo de Agmar.', 'Este é um dispositivo de teleporte. Creio que ele leva até a plataforma da agulha de mana flutuando acima dos Jardins Lua Serena, a sudoeste daqui.$B$B$n, eu quero que você use o dispositivo para investigar o que está havendo lá em cima. O dispositivo leva e traz, então você não vai ter que pular de volta.$B$BImagino que você encontrará algum aparelho de observação lá no topo da agulha de mana.$B$BVocê poderá usar o teleportador de qualquer lugar dentro dos jardins.', '', 'Objeto na Agulha de Mana observado', '', '', '', '', '', '', '', 'Volte à Imagem do Arquimago Aethas Fendessol no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12062, 'ptBR', 'Insulte Coren Cervatroz', 'Fale com Coren Cervatroz.', 'Coren Cervatroz está na sala ao lado, reunindo os anões Ferro Negro para outro ataque à CervaFest. Derrote-o!$B$BVá até ele e puxe briga. Diga que a cerveja que ele faz não presta nem pra porcos.$B$BE é melhor se preparar para a luta. A última pessoa que insultou a cerveja dele... virou comida de tusco.', '', '', '', '', '', '', '', '', '', '', 0),
(12063, 'ptBR', 'O poder da Bruma Boreal', 'Encontre Banthok Bruma Boreal, na Aldeia Bruma Boreal.', '<A Grande Mãe Bruma Boreal se inclina para saudar você.>$B$BÉ uma honra $gconhecê-lo:conhecê-la;, $gherói:heroína;. É por sua causa que muitos de nós estamos aqui hoje, vivos e prontos para lutar contra o Flagelo.$B$BVocê tem feito tanto por nós, que me envergonho de pedir sua ajuda novamente. Apesar dos meus protestos, meu único filho, Banthok, nos deixou para ir procurar pelo pai, o Chefe Supremo Bruma Boreal. Da última vez em que ele foi visto, ele se dirigia para a Aldeia Bruma Boreal. Por favor, encontre Banthok. Eu não sei o que faria se perdesse meu filho.', '', '', '', '', '', '', '', '', '', '', 0),
(12064, 'ptBR', 'Correntes dos Anub\'ar', 'Banthok Bruma Boreal, na Aldeia Bruma Boreal, que fica no Ermo das Serpes, quer que você leve para ele a Parte da Chave de Anok\'ra, a Parte da Chave de Tivax e a Parte da Chave de Sinok.', 'Eles prenderam meu pai com correntes mágicas no meio da Aldeia Bruma Boreal. Pelo que eu consegui descobrir, a prisão é controlada por três poderosos magos Anub\'ar. Cada um tem um pedaço da chave.$B$BPreciso que você varra a Aldeia Bruma Boreal e localize esses magos. Mate-os e pegue os pedaços da chave. Com os três pedaços, poderemos salvar meu pai. Quando ele estiver livre...$B$BA retaliação virá depressa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Banthok Bruma Boreal, na Aldeia Bruma Boreal, que fica no Ermo das Serpes.', 0),
(12065, 'ptBR', 'O foco na praia', 'Obtenha o Anel de Controle do Foco da Linha do Meridiano e use-o para conseguir informações do Foco da Linha do Meridiano na Praia Reluzente.$B$BEntão, fale novamente com a Imagem da Arquimaga Modera no Recanto das Estrelas.', 'As tropas de caça-magos estão ativas na Praia Reluzente, ao sul dos Jardins Lua Serena. Acredito que você encontrará um foco fortemente protegido na praia com um capitão no comando.$B$BO capitão deve portar algum dispositivo de controle. Pegue o controle e use-o no foco.$B$BCom sorte, poderemos obter mais informações sobre o que eles estão fazendo lá.', '', 'Informação do foco da linha do meridiano recuperada', '', '', '', '', '', '', '', 'Fale com a Imagem da Arquimaga Modera no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12066, 'ptBR', 'O foco na praia', 'Obtenha o Anel de Controle do Foco da Linha do Meridiano e use-o para conseguir informações do Foco da Linha do Meridiano na Praia Reluzente.$B$BEntão, fale novamente com a Imagem do Arquimago Aethas Fendessol no Martelo de Agmar.', 'As tropas de caça-magos estão ativas na Praia Reluzente, ao sul dos Jardins Lua Serena. Acredito que você encontrará um foco fortemente protegido na praia, e um capitão no comando.$B$BO capitão da força deve estar carregando algum dispositivo de controle. Pegue o controle e use-o no foco.$B$BSe tiver alguma habilidade, poderemos obter mais informações sobre o que eles estão fazendo lá.', '', 'Informação do foco da linha do meridiano recuperada', '', '', '', '', '', '', '', 'Volte à Imagem do Arquimago Aethas Fendessol no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12067, 'ptBR', 'Uma carta para casa', 'Entregue a Carta da Capitão Malin para a Comandante Saia Azulaço, no Recanto das Estrelas.', 'Você encontra uma carta escondida no forro das vestes dela. A carta diz:$B$B"Pai,$B$Bdesculpe por desaparecer assim. Se está lendo esta carta, é porque eu estou morta.$B$BFui forçada a trabalhar para os exércitos de Malygos. Nossa família seria assassinada se eu recusasse. Estou tão envergonhada.$B$BSe houver qualquer coisa que o Sr. possa fazer para combatê-los, não se preocupe comigo. Eu enganei eles, e estou sabotando a operação de dentro.$B$BTe amo, papai!$B$BEm"$B$BA Comandante Saia Azulaço vai querer ver isto!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Comandante Saia Azulaço nos Bosques de Lothalor, que fica no Ermo das Serpes.', 0),
(12068, 'ptBR', 'Pergunte ao pó', 'Drakuru quer que você colete as Tabuletas Drakkari das Ruínas de Drakil\'jin, e 5 Mojos Sagrados dos Oráculos Drakkari e Protetores Drakkari da região. Em seguida, use o Elixir de Drakuru no Braseiro de Drakuru nas ruínas para evocar a imagem dele.', '<Drakuru coloca o Olho dos Profetas na testa e o Coração dos Antigos no peito.>$b$bTamos perto, cara, perto pacas!$b$bSó falta a gente achar as Tabuletas Drakkari. Ninguém tá sabendo a idade delas ou o que elas dizem, mas, com o olho e o coração, Drakuru vai ler tudo. Elas tão lá no fundo da cripta em Drakil\'jin, a leste daqui.$b$bQuanto cê conseguir as tabuletas, pega o mojo sagrado dos oráculos e protetores pra cê poder me chamar. Eles vão ficar orgulhosos de morrer por essa causa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Imagem de Drakuru nas Ruínas de Drakil\'jin, que ficam na Serra Gris.', 0),
(12069, 'ptBR', 'O retorno do Chefe Supremo', 'Liberte o Chefe Supremo Bruma Boreal usando a Chave da Prisão Anub\'ar e ajude-o a derrotar o Baixo-Rei Anub\'et\'kan.$B$BLeve um Fragmento da Casca de Anub\'et\'kan para o Lorde Supremo Agmar, no Martelo de Agmar, que fica no Ermo das Serpes.', '<Banthok entrega as chaves da prisão para você.>$B$BApresse-se, $n. Pegue a chave e use-a para libertar meu pai da prisão Anub\'ar. Quando ele for libertado, ajude-o a destruir o líder Anub\'ar, o Baixo-Rei Anub\'et\'kan. Quando o Baixo-Rei for derrotado, arranque um pedaço da sua carapaça quitinosa como troféu para apresentar à Horda, no Martelo de Agmar. Que Agmar testemunhe o poder do Chefe Supremo!', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Lorde Supremo Agmar no Martelo de Agmar, no Ermo das Serpes.', 0),
(12070, 'ptBR', 'Incentivo às tropas', 'Use o Estilhaço da Terra para incentivar os Gigantes da Serra Gris lutando nos Montes dos Penedos, mate quaisquer anões de ferro que se opuserem, e então apresente-se a Karun no morro acima de Thor Modan.', 'Os filhos do ferro usaram suas runas para escravizar muitos dos meus irmãos, que agora são usados para romper o cerco a Thor Modan. Eu gostaria de não ter de lutar contra eles, mas não temos escolha.$B$BMeus gigantes não vão durar muito contra meus irmãos.$B$BImbuí este estilhaço de terra com uma bênção que ajudará nossos aliados. Leve-o consigo à batalha nos Montes dos Penedos ao norte, e use-o para incentivar e fortificar meus companheiros.$B$BMate todos os anões de ferro que tentarem atrapalhar.', '', 'Gigante da Serra Gris incentivados', 'Vingadores da Runa Férrea mortos', '', '', '', '', '', '', 'Fale novamente com Karun nos Montes dos Penedos, que ficam na Serra Gris.', 0),
(12071, 'ptBR', 'Ataque aéreo!', 'Apresente-se ao Furivento Valnok no Martelo de Agmar.', 'Eles sentiram a força da Horda pela terra, agora será pelo ar! Quero que você se apresente ao Furivento Valnok imediatamente! Ele está aqui no Martelo de Agmar.$B$BValnok já sabe a respeito de sua missão, e está esperando você.', '', '', '', '', '', '', '', '', '', '', 0),
(12072, 'ptBR', 'Pro inferno com as mangraferas!', 'Use a Pistola Sinalizadora de Valnok para chamar uma Mantícora de Batalha Kor\'kron, na Aldeia Bruma Boreal. Monte na Mantícora de Batalha Kor\'kron e use-a para matar 25 Mangraferas Anub\'ar!$B$BFale novamente com Furivento Valnok, no Martelo de Agmar, ao completar a missão.', 'Sem dúvida você viu o exército de mangraferas de Anub\'ar que está sendo montado na Aldeia Bruma Boreal. Os Anub\'ar têm planos de enviar esses monstros contra nossos soldados no Portão da Ira. Isso não pode acontecer!$B$BVá para a Aldeia Bruma Boreal com esta pistola sinalizadora e use-a para convocar uma das minhas mantícoras de batalha. Suba nas costas dela e dê a ordem para que ela destrua as mangraferas que estiverem longe do solo!$B$BQuando você tiver dizimado as forças aéreas, volte aqui para receber sua recompensa!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Furivento Valnok no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12073, 'ptBR', 'Marretando o ferro', 'Mate 10 Anões de Ferro de qualquer tipo que estiverem defendendo Thor Modan e, depois, apresente-se ao Batedor Vor\'takh na Aldeia Oneqwah.', 'A Aliança não é a única força adversária na Serra Gris. Os anões de ferro controlam firmemente a costa leste, ainda que Thor Modan, a nordeste, esteja cercada por gigantes de pedra.$B$BO guerreiro habilidoso emprega as fraquezas do inimigo contra o próprio, e nós seríamos tolos se ignorássemos a vulnerabilidade dos anões de ferro em Thor Modan. Mostre aos anões de ferro o quanto desconhecemos a misericórdia. Massacre tudo e todos que surgirem a sua frente.$B$BOs "filhos do ferro" logo aprenderão a temer a Horda.', '', 'Anões de Ferro Defensores mortos', '', '', '', '', '', '', '', 'Fale novamente com o Batedor Vor\'takh na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12074, 'ptBR', 'Um aliado oportuno', 'Fale com Karun no morro sobre Thor Modan.', 'A velha capital dos anões de ferro, Thor Modan, que fica longe a nordeste, está sob cerco de um grupo misterioso de gigantes de pedra e terrosos.$B$BPor que as criações dos titãs guerreiam entre si é algo que a Horda não quer nem entender, mas é também uma oportunidade de enfraquecer um inimigo mútuo.$B$BVá até Thor Modan e procure o tal do Karun que comanda os gigantes e os terrenos. Junte-se à causa dele e use as forças da terra para esmagar os anões de ferro.', '', '', '', '', '', '', '', '', '', '', 0),
(12075, 'ptBR', 'Amostras de morte', 'Colete uma amostra de carne pétrea do cadáver do Gigante do Gelo na entrada da caverna na Fenda Cristalina, ao norte de onde Zort está. Quando completar essa tarefa, volte a falar com Zort perto do centro do desfiladeiro.', 'Tá frio lá fora, hein, $r?$B$BKo\'char não quis falar comigo. Parece que ele tem coisas mais urgentes pra se preocupar – os yormungares que têm atacado eles, vindos das cavernas lá embaixo. Talvez você possa convencer Ko\'char de que eu sou um dos mocinhos.$B$BEu vi um gigante ser comido por um dos vermes na entrada da caverna ao norte daqui... Ainda estou encucado com esses vermes conseguirem comer os gigantes tão fácil assim... Me traz uma amostra da ferida de um dos gigantes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zort, na Fenda Cristalina, que fica no Ermo das Serpes.', 0),
(12076, 'ptBR', 'Negócio sujo', 'Colete 2 Ampolas de Cuspe Corrosivo dos Yormungares, usando a raspadeira em você $gmesmo:mesma;. Leve as ampolas para Zort, na Fenda Cristalina, quando completar a tarefa.', 'Já deu pra ver de cara naquela amostra que tinha uma espécie de saliva corrosiva ali. Faz sentido supor que a mesma substância que esses vermes usam para perfurar o solo também seja uma arma poderosa na luta contra os Gigantes de Gelo.$B$BPegue esse raspador e vá arranjar briga com um verme. Quando eles cuspirem em você, use o raspador para remover a saliva e traz ela para mim.$B$BMe traz duas amostras – eu vou usá-las como base pra um elixir.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zort, na Fenda Cristalina, que fica no Ermo das Serpes.', 0),
(12077, 'ptBR', 'Aplique duas vezes ao dia', 'Ofereça o elixir que Zort preparou para Ko\'char, o Inquebrável.', 'Esse elixir deve te proteger contra o cuspe dos vermes. Ofereça o elixir para o Ko\'char, por favor? Diz pra ele que tem muito mais de onde esse veio, se ele quiser negociar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ko\'char, o Inquebrável, na Fenda Cristalina, que fica no Ermo das Serpes.', 0),
(12078, 'ptBR', 'O encantador de vermes', 'Entre nas cavernas da Fenda Cristalina e capture 3 Crias de Yormungar usando os caixotes resistentes. Só pegue os caixotes de volta depois que os filhotes estiverem presos lá dentro!$B$BLeve as Crias de Yormungar de volta para Zort na Fenda Cristalina.', 'Assim seja. Se os gigantes não vão nos ajudar, então a gente pode muito bem usar os vermes. Com certeza, você vai encontrar filhotes perto da matriarca na caverna lá embaixo. Leve essa caixa, capture 3 crias de Yormungar e traga-as pra mim.$B$BQuando a diplomacia falha, a escravidão é uma alternativa super válida.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zort, na Fenda Cristalina, que fica no Ermo das Serpes.', 0),
(12079, 'ptBR', 'Reconquistando a caverna', 'Penetre na caverna na parte norte da Fenda Cristalina e mate 8 Yormungares Caçadoras Gelocórdias para Ko\'char, o Inquebrável.', 'Saudações, $gpequenino:pequenina;. Não sei que loucura $go:a; fez vir até a Fenda Cristalina, mas você é $gbem-vindo:bem-vinda; à minha presença. Duvido que você vá achar os meus irmãos amigáveis nessa hora de crise, mas se veio para nos ajudar contra os vermes, então você tem minha atenção.$B$BSe quisermos reconquistar a caverna, precisamos limpar o desfiladeiro dessas caçadoras yormungares. Ajude-nos nessa batalha, $r!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ko\'char, o Inquebrável, na Fenda Cristalina, que fica no Ermo das Serpes.', 0),
(12080, 'ptBR', 'Verme enorme', 'Entre na Caverna Gelocórdia e mate Cascavadora. Se você ainda tiver, use o Elixir Protetor de Zort contra a cusparada corrosiva da Yormungar.$B$BFale novamente com Ko\'char, o Inquebrável, quando completar a tarefa.', 'Tem uma matriarca yormungar nas cavernas mais abaixo. Nós a chamamos de Cascavadora, um nome dado a ela por um aventureiro das Terras Pestilentas. Eu a vi rapidamente durante o combate ao ataque inicial deles. Ela é grande o suficiente para devorar um dos meus filhotes inteiro. Essa caverna não será nossa até que ela seja retirada de lá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ko\'char, o Inquebrável, na Fenda Cristalina, que fica no Ermo das Serpes.', 0),
(12081, 'ptBR', 'Gavrocha', 'Fale com Gavrocha nas Ruínas de Tethys.', 'Sem sua ajuda, não teríamos sido capazes de virar a maré da batalha por Thor Modan. A cidade ancestral há muito é o campo de guerra entre as forças da terra e do ferro. Espero de coração que eles tenham sido silenciados para sempre.$B$BOs anões de ferro ainda podem usar a magia para capturar e escravizar meus irmãos. Gavrocha procura uma forma de libertar os gigantes escravizados pelas runas. Encontre-o num pequeno arquipélago, chamado Ruínas de Tethys, próximo à parte central da Costa da Lestada ao sul.', '', '', '', '', '', '', '', '', '', '', 0),
(12082, 'ptBR', 'Ta-na-na-náá!', 'Escolte Harrison das Ruínas de Drakil\'jin, e em seguida fale com Harkor no Acampamento do Harkor.', 'Escuta, $ggaroto:garota;, isso aqui não é lugar para ficar de brincadeira.$b$bEstou a ponto de fazer uma tentativa de fuga. Vem comigo e eu tiro você daqui.', 'Harrison escoltou você até um lugar seguro.', '', '', '', '', 'Harrison escoltou você até um lugar seguro.', '', '', '', 'Fale novamente com Harkor no Acampamento do Harkor, que fica na Serra Gris.', 0),
(12083, 'ptBR', 'No alto dos bosques', 'Obtenha o Amuleto de Controle do Foco da Linha do Meridiano e use-o para conseguir informações do Foco da Linha do Meridiano nos bosques de Lothalor.$B$BEntão, fale novamente com a Imagem da Arquimaga Modera no Recanto das Estrelas.', 'Tenho certeza de que há mais desses focos por aí, redirecionando as energias das linhas do meridiano. Mas ainda não sabemos o que é que eles querem com tanto poder.$B$BMeu palpite é que você vai encontrar outro foco no topo dos Bosques de Lothalor, a sudeste daqui. Mais uma vez, você precisa achar o responsável e tomar dele o dispositivo de controle. Todo foco tem um, tenho certeza.$B$BTome cuidado, $n, esses bosques são perigosos.', '', 'Informação do foco da linha do meridiano recuperada', '', '', '', '', '', '', '', 'Fale com a Imagem da Arquimaga Modera no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12084, 'ptBR', 'No alto dos bosques', 'Obtenha o Amuleto de Controle do Foco da Linha do Meridiano e use-o para conseguir informações do Foco da Linha do Meridiano nos bosques de Lothalor.$B$BEntão, fale novamente com a Imagem do Arquimago Aethas Fendessol no Martelo de Agmar.', 'Tenho certeza de que há mais desses focos por aí, redirecionando as energias das linhas do meridiano. Mas ainda não sabemos o que é que eles querem com tanto poder.$B$BMeu palpite é que você vai encontrar outro foco no topo dos Bosques de Lothalor, a sudeste daqui. Mais uma vez, você precisa achar o responsável e tomar dele o dispositivo de controle. Todo foco tem um, tenho certeza.$B$BNão demore, $c. Sinto que nosso tempo está se esgotando.', '', 'Informação do foco da linha do meridiano recuperada', '', '', '', '', '', '', '', 'Volte à Imagem do Arquimago Aethas Fendessol no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12085, 'ptBR', 'Uma carta para casa', 'Entregue a Carta do Tenente Ta\'zinni ao Lorde Supremo Agmar no Martelo de Agmar.', 'Você encontra uma carta escondida no forro das vestes. A carta diz:$B$B"Denya,$B$BDesculpa que Ta\'zinni sumiu. Se você tá lendo esta carta, então eu morri.$B$BMe forçaram a trabalhar pro exército do Malygos, senão eles iam matar minha família. Nunca que Ta\'zinni ia deixar isso acontecer!$B$BNão se preocupa comigo, só proteja seus filhos. Eu enganei eles, e tô sabotando a operação toda.$B$BTe amo, maninha!$B$BTa\'zinni"$B$BO Lorde Supremo Agmar vai querer ver isso!', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Lorde Supremo Agmar no Martelo de Agmar, no Ermo das Serpes.', 0),
(12086, 'ptBR', 'O filho de Karkut', 'Vá para o Campo da Morte, depois de Unu\'pe.', 'O homem que você procura foi para longe, a leste, para um lugar perto da costa chamado Campo da Morte, depois de Unu\'pe.$B$BTome cuidado se for procurá-lo, $n. Ele carrega a marca de Karkut... aquele que vigia os mortos.', '', '', '', '', '', '', '', '', '', '', 0),
(12088, 'ptBR', 'Thassarian, o Cavaleiro da Morte', 'Procure por Thassarian dentro do Zigurate dos Lamentos, ao norte do Campo da Morte.', 'Bem, $n, você nos ajudou... então acho que não seria justo deixar de ajudá-$glo:la; também.$B$BVocê procura Thassarian? Ele desapareceu esta manhã. Achamos que ele foi para o Zigurate dos Lamentos ao norte. Se não tivéssemos lutado lado a lado com ele, pensaríamos que era um traidor.$B$BSabe, ele é um Cavaleiro da Morte... e eu sei que eles estão do nosso lado e tudo mais... mas, há pouco tempo atrás, eram servos de Arthas.$B$BNão o Thassarian – ele é um bom sujeito. Vá para o Zigurate dos Lamentos, veja se está tudo bem com ele.', '', '', '', '', '', '', '', '', '', '', 0),
(12089, 'ptBR', 'Procura-se: Magíster Keldonus', 'Mate o Magíster Keldonus e fale com o Capitão Gort, no Martelo de Agmar, que fica no Ermo das Serpes.', 'Por decreto do lorde supremo Agmar:$B$BCriminoso: Magíster Keldonus$B$BCrime: Traição$B$BCondição: Vivo$B$BO magíster Keldonus, ex-mago comandante do Martelo de Agmar, deve ser morto em nome da Horda.$B$BKeldonus foi visto pela última vez viajando para sudoeste, em direção aos Jardins Lua Serena, para se unir à revoada azul em sua campanha contra a magia.$B$BKeldonus deve ser abordado com cuidado, pois é um mago poderoso.$B$BTodas as recompensas serão pagas pelo capitão Gort no Martelo de Agmar.', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Gort, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12090, 'ptBR', 'Procura-se: Gigantauro', 'Mate Gigantauro e fale novamente com o Capitão Gort no Martelo de Agmar, que fica no Ermo das Serpes.', 'Por decreto do lorde supremo Agmar:$B$BCriminoso: Gigantauro$B$BCrime: Ataques à Horda; "Ser feio".$B$BCondição: Vivo$B$BO senhor dos magnatauros, Gigantauro, é procurado por inúmeros ataques contra soldados e instalações da Horda no Ermo das Serpes.$B$BGigantauro foi visto pela última vez vagando pelos bosques e estradas a su-sudeste do Martelo de Agmar.$B$BGigantauro deve ser considerado armado e extremamente perigoso.$B$BTodas as recompensas serão pagas pelo capitão Gort no Martelo de Agmar.', '', '', '', '', '', '', 'Gigantauro', '', '', 'Fale com o Capitão Gort, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12091, 'ptBR', 'Procura-se: Garra Horrenda', 'Mate Garra Horrenda e fale com o Capitão Gort, no Martelo de Agmar, que fica no Ermo das Serpes.', 'Por decreto do lorde supremo Agmar:$B$BCriminoso: Garra Horrenda$B$BCrime: Ataques à Horda$B$BCondição: Vivo$B$BGarra Horrenda é procurado por inúmeros ataques às caravanas da Horda viajando de e para Perfídia.$B$BGarra Horrenda mora em um penhasco sobranceiro ao Santuário Dragônico Rubi, a leste do Martelo de Agmar. Exercer extrema cautela na abordagem.$B$BTodas as recompensas serão pagas pelo capitão Gort no Martelo de Agmar.', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Gort, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12092, 'ptBR', 'Fortaleça os ancientes', 'Use a Casca dos Andarilhos para fortalecer 3 Ancientes de Lothalor e então fale novamente com Sarendryana no Recanto das Estrelas.', 'Não foi só a raça $r que sofreu o impacto das ações da revoada azul. Os ancientes dos Bosques de Lothalor, a sudeste daqui, também foram afetados.$B$BAlguns foram corrompidos. Esses você deve evitar, mas a maioria ainda pode ser salva. No entanto, os arvorosos dos bosques parecem imunes à magia que grassa pela terra, e às serpes arcanas que essa magia trouxe.$B$BPeça a casca dos arvorosos andarilhos para dar de comer aos ancientes. Espero que baste para salvá-los.', '', 'Anciente de Lothalor fortalecido', '', '', '', '', '', '', '', 'Fale novamente com Sarendryana no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12093, 'ptBR', 'Runas de compulsão', 'Gavrocha, nas Ruínas de Tethys, quer que você neutralize as quatro Runas de Compulsão derrotando o Feitor Durval, o Feitor Korgan, o Feitor Lochli e o Feitor Brunon.', 'Mesmo enquanto Karun ataca Thor Modan, os anões de ferro empregam magia contra nossos irmãos. Eles evocam nossos companheiros da terra e, em seguida, os atam com runas. Assim, os filhos do ferro os forçam a lutar contra os filhos da pedra.$B$BAo longo da Costa da Lestada, os ferrosos usam runas de compulsão para mandar os gigantes escravizados aos campos de batalha setentrionais.$B$BEncontre as quatro runas da compulsão e force a aparição dos feitores, derrotando os tecedores de runas que ocupam cada sub-runa. Sem os feitores, os círculos rúnicos são inúteis.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gavrocha nas Ruínas de Tethys, que ficam na Serra Gris.', 0),
(12094, 'ptBR', 'Poder latente', 'Energize o Estilhaço de Gavrocha no Primeiro Marco Ancestral, no Segundo Marco Ancestral e no Terceiro Marco Ancestral, e em seguida fale novamente com Gavrocha nas Ruínas de Tethys.', 'Enquanto as runas de compulsão estiverem dormentes, temos uma chance para libertar os gigantes escravizados.$B$BEu lhe darei um pedaço de pedra que faz parte de mim desde a minha criação. Corretamente imbuído, o pedaço libertará os gigantes atados.$B$BDois marcos de pedra ancestrais se erguem em lugares energéticos entre o Caminho de Ferro e a orla da floresta, locais que o seu povo chamaria de interseção de meridianos místicos. O outro está numa ilha ao sul destas ruínas. Energize o estilhaço em cada um dos marcos e volte.', '', 'Energia Absorvida do Primeiro Marco Ancestral', 'Energia Absorvida do Segundo Marco Ancestral', 'Energia Absorvida do Terceiro Marco Ancestral', '', '', '', '', '', 'Fale novamente com Gavrocha nas Ruínas de Tethys, que ficam na Serra Gris.', 0),
(12095, 'ptBR', 'Para a Aldeia do Dragão Arruinado', 'Fale com Rokhan, na Aldeia do Dragão Arruinado, que fica no Ermo das Serpes.', 'A leste daqui, no coração do Ermo das Serpes, fica um campo repleto de ossos de dragões e neve. O Flagelo estabeleceu vários acampamentos na tundra. Eles estão reanimando serpes gélidas para atacar nossas forças no Portão da Ira. A maior parte dessas serpes é derrotada facilmente por Rokhan e os caçadores de dragão que ele comanda, mas há uma serpe que é um tanto problemática.$B$BSiga para nordeste e procure Rokhan na Aldeia do Dragão Arruinado. Ajude-o a derrubar Sarathstra e será muito bem $grecompensado:recompensada;!', '', '', '', '', '', '', '', '', '', '', 0),
(12096, 'ptBR', 'Fortaleça os ancientes', 'Use a Casca dos Andarilhos para fortalecer 3 Ancientes de Lothalor e então fale novamente com o Guarda da Terra Grife no Martelo de Agmar.', 'Os ancientes dos Bosques de Lothalor ao sul estão sendo corrompidos por serpes arcanas... serpes que eles ressuscitaram do solo!$B$BOs que já estão corrompidos são letais, e já não nos servem, mas a maioria ainda pode ser salva. Por sorte, parece que os arvorosos dos bosques continuam imunes ao que está acontecendo.$B$BPeça a casca dos arvorosos andarilhos para dar de comer aos ancientes. Deve fortalecê-los.$B$BAgora, deixe-me, pois estou ocupado! Preciso ficar de olho nesses boticários.', '', 'Anciente de Lothalor fortalecido', '', '', '', '', '', '', '', 'Fale novamente com o Guarda da Terra no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12097, 'ptBR', 'Sarathstra, Flagelo do norte', 'Peça para Rokhan chamar a serpe gélida Sarathstra.$B$BMate Sarathstra e entregue o Coração Gelado de Sarathstra para o Capitão Gort no Martelo de Agmar.', 'Meus caçadores tão tudo morto ou congelado, $n. Ainda tá a fim de fazer essa parada? É só tu pedir que eu chamo o dragão de novo.$B$BSe tu matar o bicho, leva o coração dele de volta pro Martelo de Agmar e entrega pro Gort. Ele vai te recompensar bem, cara.', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Gort, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12098, 'ptBR', 'Vasculhe a Aldeia Indu\'le', 'Procure o comandante das tropas de caça-magos na Aldeia Indu\'le e no Lago Indu\'le.', 'Tenho certeza de que você vai encontrar o próximo foco de linha de meridiano nas ruínas da Aldeia Indu\'le, a sudeste daqui. O problema é que não recebemos nenhum relatório de confirmação.$B$BQuero que você investigue a aldeia e tente encontrar algum sinal do foco, ou dos caça-magos e seu comandante na área.$B$BNão esqueça de procurar no lago também.', '', '', '', '', '', '', '', '', '', '', 0),
(12099, 'ptBR', 'Liberdade, liberdade', 'Use o Quebra-runas de Gavrocha para libertar 4 Gigantes Rúnicos, e então fale novamente com Gavrocha nas Ruínas de Tethys.', 'O estilhaço de pedra imbuído parece ser poderoso o bastante para romper a magia rúnica que ata meus irmãos.$B$BLeve-o com você e encontre os gigantes escravizados que caminham para o norte ao longo da Costa da Lestada. Libere o poder contido na pedra e observe o resultado.$B$BSe funcionar, os gigantes escravizados voltarão ao normal e não mais obedecerão aos anões de ferro. Se a pedra falhar, o gigante poderá atacar, num estado enfraquecido. Mas que escolha nós temos? Se não tentarmos nada, eles permanecerão escravizados e sem esperança.', '', 'Gigantes Rúnicos libertos', '', '', '', '', '', '', '', 'Fale novamente com Gavrocha nas Ruínas de Tethys, que ficam na Serra Gris.', 0),
(12100, 'ptBR', 'Contendo a putrefação', 'Pairante Fúria da Águia, no Martelo de Agmar, no Ermo das Serpes, quer que você mate 15 Animais Selvagens Infectados e ache um Órgão Resistente à Putrefação.', 'A morte e a doença acompanham o Flagelo. Por vezes, nos esquecemos que a vida selvagem em uma área infestada pelo Flagelo acaba destruída pelo contágio e pela putrefação.$B$BJá é tarde demais para a maioria das feras nativas do Ermo das Serpes. A doença purulenta que o Flagelo traz consigo já infectou as feras; elas estão raivosas e apodrecendo.$B$BVocê precisa ir para oeste, na direção do Fosso de Narjun, e abater a vida selvagem infectada de lá. Vasculhe os cadáveres e tente achar um órgão preservado, pois precisamos de um para produzir uma vacina.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pairante Fúria da Águia, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12101, 'ptBR', 'O bom doutor...', 'Entregue o Órgão Resistente à Putrefação ao Dr. Síntar C. Málius, no Martelo de Agmar.', 'Nossos aliados Renegados enviaram os boticários para cá para nos ajudar a destruir o Flagelo no Portão da Ira. Um deles, o Doutor Síntar C. Málius, sabe muito a respeito da putrefação do Flagelo e métodos de conter o contágio. Eu fechei um acordo com ele sobre desenvolver uma vacina para os animais selvagens. Desde então, ele aguarda o órgão.$B$BEntregue o órgão resistente à putrefação para o Dr. Málius. Diga a ele que eu mandei a amostra. Ele lhe dará sua próxima tarefa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Dr. Síntar C. Málius, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12102, 'ptBR', 'Em busca da lilás-rubi', 'O Doutor Síntar C. Málius, no Martelo de Agmar, no Ermo das Serpes, quer que você colete 1 Lilás-rubi.', 'Quão fortuito que o Santuário Dragônico Rubi fique tão perto, a leste daqui. É lá que você encontrará uma flor chamada lilás-rubi. Essa planta revitalizante é tudo que preciso para preparar uma vacina para as feras ainda não contaminadas da região.$B$BViaje para leste e procure o Santuário Dragônico Rubi. Lá você encontrará a lilás-rubi.$B$BSó uma coisa: o santuário, como todos nessa terra erma miserável, se encontra cercado pelo Flagelo. Tome cuidado. Ninguém aqui quer que você seja $Gcomido:comida; por uma serpe das cinzas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Dr. Síntar C. Málius, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12104, 'ptBR', 'Falar com Pairante', 'Entregue a Vacina de Síntar a Pairante Fúria da Águia no Martelo de Agmar.', '<O Dr. Málius entrega a você uma ampola cheia de um líquido turvo.>$B$BAqui está, $r. Entregue isso para aquela vaca. E avise que as dívidas estão pagas. Estamos oficialmente quites.$B$BAgora vá, antes que eu solte o Jennings aqui em cima de você.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pairante Fúria da Águia, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12105, 'ptBR', 'Descida às trevas', 'Entregue o Diário de Mikhail ao Tenente Dumont no Chalé do Pinho Âmbar.', 'O diário foi escrito por um morador de Arroio Prateado chamado Mikhail. Narra a chegada de um grupo de adoradores das trevas chamados de "Culto dos Lobos".$B$BOs aldeões inicialmente hesitaram em se juntar ao culto, mas os simpatizantes surgiram aos poucos dentre os residentes da vila.$B$BPerturbado pelos acontecimentos, Mikhail mandou a filha Sasha para longe de Arroio Prateado enquanto tentava argumentar com os outros aldeões.$B$BA última anotação de Mikhail menciona uma reunião de líderes da vila para debater eventos não especificados na Mina da Pedra Oca.', '', '', '', '', '', '', '', '', '', 'Fale com o Tenente Dumont no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12106, 'ptBR', 'Vasculhe a Aldeia Indu\'le', 'Procure o comandante das tropas de caça-magos na Aldeia Indu\'le e no Lago Indu\'le.', 'Tenho certeza de que você vai encontrar o próximo foco de linha de meridiano nas ruínas da Aldeia Indu\'le, a sudeste daqui. O problema é que não recebemos nenhum relatório de confirmação.$B$BQuero que você investigue a aldeia e tente encontrar algum sinal do foco, ou dos caça-magos e seu comandante na área.$B$BNão esqueça de procurar no lago também!', '', '', '', '', '', '', '', '', '', '', 0),
(12107, 'ptBR', 'O fim da linha', 'Use o Talismã de Controle do Foco da Linha do Meridiano para conseguir informações do Foco da Linha do Meridiano sob o Lago Indu\'le. Então, siga na direção leste para o Santuário Dragônico Lazúli, perto da parte centro-sul do Ermo das Serpes, e, do parapeito ocidental, observe o que está acontecendo lá.$B$BDepois, fale novamente com a Imagem da Arquimaga Modera, no Recanto das Estrelas.', 'Nas vestes dele, você encontra duas coisas interessantes:$B$BUma é um talismã, que é obviamente um dispositivo de controle do foco. A outra é uma lista de ordens vindas de um certo Sidragos, dirigidas ao líder aquartelado nos Jardins Lua Serena.$B$BO pergaminho encharcado informa Goramosh que ele deverá deslocar todas as tropas de caça-magos para o leste, para o Santuário Dragônico Lazúli.$B$BTalvez fosse bom você extrair a informação do foco e depois seguir para o leste para observar o santuário do parapeito ocidental.', '', 'Informação do foco da linha do meridiano recuperada', 'Santuário Dragônico Lazúli observado', '', '', '', '', '', '', 'Fale com a Imagem da Arquimaga Modera no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12109, 'ptBR', 'Apresente-se a Miguel Mantoforte... de novo', 'Fale com o Capitão Miguel Mantoforte no Acampamento da Brigada de Cerro Oeste.', 'Os rapazes de Cerro Oeste foram mandados pro leste, para procurar um caminho até os territórios do norte. Como o objetivo secundário deles é dominar pontos de recursos estratégicos, tenho certeza de que não se importariam em investigar uma mina.$B$BProcure o Acampamento da Brigada de Cerro Oeste bem a nordeste, e procure por Miguel Mantoforte. Talvez você se lembre dele, se já passou algum tempo em Cerro Oeste. Não esqueça de dizer que fui eu quem $go:a; mandou.$B$BEle ficará mais do que feliz em deixar você se apossar de uma mina para o rei.', '', '', '', '', '', '', '', '', '', '', 0),
(12110, 'ptBR', 'O fim da linha', 'Use o Talismã de Controle do Foco da Linha do Meridiano para conseguir informações do Foco da Linha do Meridiano sob o Lago Indu\'le. Então, siga na direção leste para o Santuário Dragônico Lazúli, perto da parte centro-sul do Ermo das Serpes, e observe o que está acontecendo lá, do parapeito ocidental.$B$BDepois, fale novamente com a Imagem do Arquimago Aethas Fendessol, no Martelo de Agmar.', 'Nas vestes dele, você encontra duas coisas interessantes:$B$BUma é um talismã, que é obviamente um dispositivo de controle do foco. A outra é uma lista de ordens vindas de um certo Sidragos, endereçadas ao líder aquartelado nos Jardins Lua Serena.$B$BO pergaminho encharcado informa Goramosh que ele deve deslocar todas as tropas de caça-magos para o leste, para o Santuário Dragônico Lazúli.$B$BTalvez fosse bom você extrair a informação do foco e depois seguir para o leste para observar o santuário do parapeito ocidental.', '', 'Informação do foco da linha do meridiano recuperada', 'Santuário Dragônico Lazúli observado', '', '', '', '', '', '', 'Volte à Imagem do Arquimago Aethas Fendessol no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12111, 'ptBR', 'Onde moram os bichos selvagens', 'Pairante Fúria da Águia, no Martelo de Agmar, no Ermo das Serpes, quer que você use o Pacote de Vacinas para vacinar 5 Cervos Nevados e 5 Ursos Árticos.', 'Este pacote guarda várias ampolas da vacina que Síntar criou. Eu quero que você vasculhe os bosques aqui perto e procure por cervos nevados e ursos árticos. Quando os encontrar, atire uma ampola na direção deles de uma distância segura. A ampola se estilhaçará e liberará um fino gás que agirá como agente inoculante. As feras só precisam entrar na nuvem de gás para serem vacinadas e salvas.$B$BInocule o maior número de feras que conseguir e depois fale comigo.', '', 'Cervo Nevado inoculado', 'Urso Ártico inoculado', '', '', '', '', '', '', 'Fale novamente com Pairante Fúria da Águia, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12112, 'ptBR', 'Negociações rígidas', 'Encontre Zort no centro da Fenda Cristalina, a nordeste do Posto Ferrugem.', 'Olha só, parece que você serviu pra alguma coisa... É raro conhecer $Gum:uma; $r que serve pra alguma coisa.$B$BMas já não tenho mais serviço pra você aqui. Vai lá na Fenda Cristalina e veja se meu irmão Zort precisa de alguma coisa. Ele foi lá ver se conseguia fazer os gigantes arriscarem a vida pra gente não precisar fazer isso. Mas ele não é conhecido por ser o esperto da família.', '', '', '', '', '', '', '', '', '', '', 0),
(12113, 'ptBR', 'A marvada carne', 'Harkor, no Acampamento do Harkor, quer que você colete 10 peças de Carne Fibrosa de Worg dos Predadores Uivo da Noite, e 10 Bifes de Hastepás dos Ruminantes Cascolongo.', 'Bons dias, $c! Te senta aqui junto à fogueira.$b$bGostaria de te oferecer um belo churrasco, pena que eu não tenho nada. Como estou preso aqui esperando um companheiro, não posso resolver o problema pessoalmente.$b$bVeja bem, você parece estar com bastante tempo livre, e tem muita carne por estes pampas. Que me diz de me dar uma mãozinha e arrebanhar umas carnes?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Harkor no Acampamento do Harkor, que fica na Serra Gris.', 0),
(12114, 'ptBR', 'Terapia', 'Harkor, no Acampamento do Harkor, quer que você mate 10 Protetores Drakkari e 10 Oráculos Drakkari do lado de fora das Ruínas de Drakil\'jin.', 'Trolls... como eu odeio eles!<Harkor cospe.>$b$bUma vez eu fui capturado por um grupo daquelas bestas... Faltou ISSO pra minha cabeça ser encolhida!$b$bMeus amigos me dizem para tocar o barco e deixar isso tudo para trás, mas isso não é suficiente.$b$bSabe o que ia me deixar muito mais feliz, $r? Ver uma pilha de cadáveres dos trolls alta o bastante para cobrir o sol! Tenho muita grana pra gastar se tu fizer isso acontecer.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Harkor no Acampamento do Harkor, que fica na Serra Gris.', 0),
(12115, 'ptBR', 'Koltirus e a linguagem da morte', 'Leve o Tomo Encadernado com Carne para Koltirus Tecemorte.', 'Uma pessoa que aderiu recentemente à nossa causa pode conseguir decifrar o tomo. Um cavaleiro da morte livre chamado Koltirus Tecemorte está morando temporariamente aqui no Martelo de Agmar. Como já foi um cavaleiro da morte de Arthas e membro do Flagelo, ele pode ser capaz de traduzir a linguagem dos mortos.$B$BLeve o tomo encadernado com carne para Koltirus, e peça que ele traduza as páginas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Koltirus Tecemorte no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12116, 'ptBR', 'Das tripas coração', 'Kraz, no Acampamento do Harkor, quer que você entre nas Ruínas de Drakil\'jin e colete 5 Vasos Canópicos Drakkari.', 'Saudações, $c. É muita gentileza sua parar para ouvir a história de Kraz.$b$bHá muitos anos que Kraz se esforça para ouvir os espíritos e seguir as ordens deles.$b$bRecentemente, muitas vozes dessas ruínas vêm chorando para Kraz. Elas buscam uma paz que não podem encontrar sozinhas.$b$bSe você estiver dispost$go:a; a ajudar os espíritos dos antecessores, entre na cripta e recolha algo que um dia pertenceu às almas atormentadas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kraz no Acampamento do Harkor, que fica na Serra Gris.', 0),
(12117, 'ptBR', 'Viagem para Porto Moa\'ki', 'Vá até Porto Moa\'ki no Ermo das Serpes e fale com o Ancião Ko\'nani.', '$R, acabam de chegar notícias do Porto Moa\'ki... Algo muito ruim aconteceu por lá esta manhã!$B$BVocê nos ajudou muito por aqui. Não gostaria de viajar até o grande Ermo das Serpes usando o barco de Unu\'pe?$B$BAo que tudo indica, o Ancião Ko\'nani precisa do seu auxílio.', '', '', '', '', '', '', '', '', '', '', 0),
(12118, 'ptBR', 'Viagem para Porto Moa\'ki', 'Vá até Porto Moa\'ki no Ermo das Serpes e fale com o Ancião Ko\'nani.', '$R, acabam de chegar notícias de Porto Moa\'ki. Algo muito ruim aconteceu por lá essa manhã!$B$BVocê nos ajudou muito por aqui. Poderia ir até o grande Ermo das Serpes usando o barco de Unu\'pe?$B$BAo que tudo indica, o ancião Ko\'nani certamente precisa do seu auxílio.', '', '', '', '', '', '', '', '', '', '', 0),
(12119, 'ptBR', 'Requerimento de audiência', 'Entregue sua Carta de Apresentação ao Templo do Repouso das Serpes para Tariolstrasz, no Templo do Repouso das Serpes.', '$n, viaje o mais rápido que puder para o Templo do Repouso das Serpes e entregue esta carta ao administrador Tariolstrasz.$B$BO templo fica no centro do Ermo das Serpes. Siga para leste até o final da estrada, então atravesse os Ermos Dragônicos.$B$BTenho certeza de que, quando o administrador ler essa apresentação, ele conseguirá uma audiência com a rainha Alexstrasza. Espero que não seja tarde demais.$B$BObrigada por tudo o que tem feito por nós. Boa viagem!', '', '', '', '', '', '', '', '', '', 'Fale com Tariolstrasz nos Ermos Dragônicos, no Ermo das Serpes.', 0),
(12120, 'ptBR', 'A marreta de Drag\'akaal', 'Kraz, no Acampamento do Harkor, quer que você mate Drag\'akaal do lado de fora das Ruínas de Drakil\'jin e volte com a Marreta Drakil\'jin.', 'Corrupção...$b$bMesmo antes que você entregasse as jarras, Kraz já podia senti-la. A corrupção deixa os antigos espíritos Drakkari muito angustiados, e os impede de alcançar o repouso que buscam.$b$bKraz não vai mentir, $c. Purificar o lugar exigirá grande sacrifício, mas vamos falar disso em outro momento.$b$bHá alguém dentre os vivos que detém a chave para a purificação. Procure Drag\'akaal e volte com a marreta que ele carrega.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kraz no Acampamento do Harkor, que fica na Serra Gris.', 0),
(12121, 'ptBR', 'A gente se vê no aquém do além', 'Kraz, no Acampamento do Harkor, quer que você use a Marreta Drakil\'jin nos gongos do lado de fora das Ruínas de Drakil\'jin. Uma vez $gassassinado:assassinada;, entre nas ruínas e fale com o espírito de Gan\'jo enquanto estiver $gmorto:morta;.', 'Os Drakkari não lhe ofereceram nada além de hostilidade selvagem. Você nada lhes deve. De fato, poucos executariam a tarefa que Kraz lhe concederá hoje.$b$bPara purificar este lugar e mandar os espíritos ao descanso eterno, você terá de se juntar a eles na morte.$b$bUm desses espíritos $Go:a; aguarda dentro da cripta... no além. Ele possui o conhecimento que buscamos, $n.$b$bUse a marreta nos gongos. O espírito daquele que corrompe este lugar certamente $go:a; levará ao mundo espiritual.$b$bKraz aguardará seu retorno.', '', 'Morte pelas mãos do Senhor da Guerra Jin\'arrak', '', '', '', '', '', '', '', 'Fale com Gan\'jo nas Ruínas de Drakil\'jin, que ficam na Serra Gris.', 0),
(12122, 'ptBR', 'Requerimento de audiência', 'Entregue sua Carta de Apresentação ao Templo do Repouso das Serpes para Tariolstrasz, no Templo do Repouso das Serpes.', '$n, viaje o mais rápido que puder para o Templo do Repouso das Serpes e entregue esta carta ao administrador Tariolstrasz.$B$BO templo fica no centro do Ermo das Serpes. Siga para leste até o final da estrada, e atravesse os Ermos Dragônicos.$B$BTenho certeza de que, quando o administrador ler essa apresentação, ele conseguirá uma audiência com a rainha Alexstrasza. Espero que não seja tarde demais.$B$BObrigado por tudo o que tem feito por nós. Boa viagem!', '', '', '', '', '', '', '', '', '', 'Fale com Tariolstrasz no Templo do Repouso das Serpes, que fica no Ermo das Serpes.', 0),
(12123, 'ptBR', 'Informando a rainha', 'Entregue sua Carta de Apresentação ao Templo do Repouso das Serpes a Alexstrasza, a Mãe da Vida, no Templo do Repouso das Serpes.', '<O dragão administrador tira a carta de apresentação da manga.>$B$BSim... sim, creio que você está $gpronto:pronta; para ver a rainha.$B$BQuando quiser, pode falar comigo e eu arranjarei para que um dos dracos leve você sem riscos até o topo do templo. Você terá de apresentar sua carta pessoalmente à rainha Alexstrasza.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Alexstrasza, a Mãe da Vida no Templo do Repouso das Serpes, que fica no Ermo das Serpes.', 0),
(12124, 'ptBR', 'Informando a rainha', 'Entregue sua Carta de Apresentação ao Templo do Repouso das Serpes a Alexstrasza, a Mãe da Vida, no Templo do Repouso das Serpes.', '<O dragão administrador tira a carta de apresentação da manga.>$B$BSim... sim, creio que você está $gpronto:pronta; para ver a rainha.$B$BQuando quiser, pode falar comigo e eu arranjarei para que um dos dracos leve você sem riscos até o topo do templo. Você terá de apresentar sua carta pessoalmente à rainha Alexstrasza.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Alexstrasza, a Mãe da Vida no Templo do Repouso das Serpes, que fica no Ermo das Serpes.', 0),
(12125, 'ptBR', 'A serviço do sangue', 'Koltirus Tecemorte, no Martelo de Agmar, no Ermo das Serpes, quer que você use a Gema Sangrenta em um Aldeão Indu\'le Demente. Se apresente novamente a ele com uma Gema Sangrenta Preenchida.', 'Já houve época em que o sangue de inocentes era usado para saciar a sede desta lâmina. Mas já não posso me utilizar de tal recurso, infelizmente.$B$B<Koltirus para e reflete.>$B$BVamos ter que improvisar. A sul daqui, nos penhascos, fica a vila morsana de Indu\'le. Os morsanos de lá foram subjugados pela magia caótica da Revoada Azul, e enlouqueceram.$B$BTome esta gema sangrenta e use-a em um aldeão enlouquecido. Se não posso ter o sangue dos inocentes, usarei o sangue dos mansos!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Koltirus Tecemorte no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12126, 'ptBR', 'A serviço do profano', 'Koltirus Tecemorte, no Martelo de Agmar, no Ermo das Serpes, quer que você use a Gema Profana no Duque Vallenhal e se apresente novamente a Koltirus Tecemorte com uma Gema Profana Preenchida.', 'O poder profano é cobiçado pelos de minha estirpe. Trata-se da própria fibra de nossa existência, levando a morte àqueles que ousarem ficar em nosso caminho. Por sorte, existe uma fonte de onde posso retirar poder em épocas de necessidade.$B$BTome esta gema profana e siga para o Santuário Dragônico Rubi, a leste daqui. É lá que você encontrará o Duque Vallenhal, cavaleiro da morte de Arthas. Quebre o espírito de batalha do Duque, e libere o poder da gema sobre ele. A gema o matará, e lhe roubará a energia profana!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Koltirus Tecemorte no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12127, 'ptBR', 'A serviço do gelo', 'Koltirus Tecemorte, no Martelo de Agmar, no Ermo das Serpes, quer que você use a Gema Gélida nos Elementais Vingativos Gélidos e se apresente novamente a ele com uma Gema Gélida Preenchida.', 'O frio agudo protege o cavaleiro da morte, ao mesmo tempo em que repele os inimigos. Quem comandar o poder do gelo pode criar o caos e a destruição!$B$BTome esta gema gélida e vá pela tundra do Ermo das Serpes até encontrar o Espelho da Aurora, a leste do Templo do Repouso das Serpes. Lá, você dará combate às legiões de elementais vingativos gélidos que habitam a superfície do lago e roubará deles a essência gélida. Use o poder da gema quando eles enfraquecerem, $n!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Koltirus Tecemorte no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12128, 'ptBR', 'Conferindo a situação de Raegar', 'Fale com Raegar Quebracelha no Mirante do Minerador.', 'Com toda essa confusão do exército tentando passar por Thor Modan, quase me esqueci da equipe do Raegar lá no Mirante do Minerador.$B$BMandei ele e seus assistentes até lá com um amigo montanhista para estabelecer um pequeno entreposto perto de Dun Argol, no extremo sul da Costa da Lestada.$B$BEles foram investigar a presença dos anões de ferro nas colinas do sul, mas não recebi nenhum relatório até agora. Você poderia dar uma olhada neles, se for para aqueles lados?', '', '', '', '', '', '', '', '', '', '', 0),
(12129, 'ptBR', 'O plano perfeito', 'Traga o Diagrama do Golem de Guerra completo para Raegar Quebracelha no Mirante do Minerador.', 'Os anões de ferro não fazem o menor esforço para esconder o fato de estarem se preparando para a guerra. Com os gigantes, golens e elementais do raio, eles têm a vantagem tecnológica contra a Brigada de Cerro Oeste. Se nossos rapazes não encontrarem logo a passagem para o norte, os "ferros" poderão pegá-los de surpresa.$B$BTemos de prendê-los aqui, e eu sei exatamente como vamos fazê-lo. Dun Argol está cheio de forjadores de runas produzindo golens de guerra. Cada um carrega as instruções de peças específicas, então você terá que encontrar e montar todas as partes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Raegar Quebracelha no Mirante do Minerador.', 0),
(12130, 'ptBR', 'Para que fabricar se você pode confiscar?', 'Traga 8 Peças de Golem de Guerra para Raegar Quebracelha no Mirante do Minerador.', 'Temos os diagramas, mas eles não servem para nada sem as peças! Não temos acesso a uma fundição, e muito menos às matérias-primas, mas há sempre um montão de peças em Dun Argol.$B$BSeu trabalho?$B$BOferecer um novo lar a elas.$B$BAs peças provavelmente estão espalhadas pelos prédios onde os forjadores de runas trabalham, e eu não os culparei se ficarem mal-humorados quando você tentar surrupiar os frutos do trabalho deles. Quanto mais peças você trouxer, melhor ficará o golem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Raegar Quebracelha no Mirante do Minerador.', 0),
(12131, 'ptBR', 'Nós temos a força', 'Traga a Pilha de Durar e a Pilha de Kathorn para Raegar Quebracelha no Mirante do Minerador.', 'Estamos chegando lá, mas o golem de guerra não vai funcionar sem as pilhas. Pelas informações que consegui coletar em Dun Argol, antes que fôssemos descobertos, o Forjador de Runas Durar e o Forjador de Runas Kathorn criam pilhas separadamente.$B$BPrecisamos de uma pilha de cada um deles para fazermos nosso golem funcionar.$B$BOs dois forjadores de runas devem estar nas respectivas oficinas no nível central de Dun Argol.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Raegar Quebracelha no Mirante do Minerador.', 0),
(12132, 'ptBR', 'O poder de destruir', 'Koltirus Tecemorte, no Martelo de Agmar, que fica no Ermo das Serpes, quer que você entre no mundo das sombras e derrote 6 Atormentadores Sombrios.$B$BFale com Koltirus Tecemorte se precisar entrar novamente no reino das sombras.', 'Você fez muito por mim, mas ainda resta uma tarefa.$B$BContíguo ao mundo que você conhece, existe um outro. É desse mundo, o mundo das sombras, que meus atormentadores me atacam. Eu mesmo não tenho poder para encarar meus demônios, mas você poderia dar um fim neles. Você tem o poder, isso eu vi com meus próprios olhos.$B$BEntre no mundo das sombras e enfrente os demônios que me atormentam!$B$BCumpra esta tarefa, e traduzirei o tomo como prometi.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Koltirus Tecemorte no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12133, 'ptBR', 'Esmague a abóbora', 'Dê o Símbolo Sagrado Chamuscado para a Matriarca Fantasiada.', 'Esta lanterna de abóbora está esquecida no meio da aldeia. Ela parece observar todos os que a olham, com um ar ameaçadoramente sombrio.$B$BAo esmagá-la, você encontra um antigo símbolo sagrado chamuscado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Matriarca Fantasiada.', 0),
(12134, 'ptBR', 'A caçada de Sasha', 'Sasha quer que você mate 12 Caçadores do Solstício na Aldeia Solstício.', 'A doença... a maldição... que está afetando Arroio Prateado e a Aldeia Solstício... transforma as pessoas em monstros.$B$BMeu pai tentou avisá-los, mas todos ouviram a seita dos lobos.$B$BAgora é tarde demais para eles, e chegou a hora de sacrificá-los... pelo próprio bem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Sasha no Entreposto Pinheiro Branco, que fica na Serra Gris.', 0),
(12135, 'ptBR', '"Que venha o fogo!"', 'A Matriarca Fantasiada quer que você ajude a apagar os focos de incêndio na vila assim que o Cavaleiro Sem Cabeça atear fogo. Quando acabar, fale novamente com a Matriarca Fantasiada.', 'Você precisa nos ajudar! O Cavaleiro Sem Cabeça vai atacar a vila a qualquer momento! O fogo vai destruir tudo, e as nossas crianças correm perigo!$B$BPor favor, $n, ajude a brigada de incêndio. Pegue um balde e apague as chamas... Ou então, passe-o para alguém que esteja perto delas. Apague os focos de incêndio, ainda há esperança!', 'Apague os focos de incêndio!', '', '', '', '', 'Apague os focos de incêndio!', '', '', '', 'Fale novamente com a Matriarca Fantasiada.', 0),
(12136, 'ptBR', 'O tomo traduzido', 'Leve o Tomo Encadernado com Carne Traduzido para o Capitão Gort, no Martelo de Agmar.', 'Tome, $n. Traduzi tudo que está impresso nas páginas do tomo. Você encontrará uma lista dos nomes dos membros da Seita dos Malditos. Eles se espalham pelo continente inteiro.$B$BE a rede de espiões e agentes deles é impressionante.$B$BAdeus, $gamigo:amiga;. Que o livro lhe sirva bem, e aos seus.', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Gort, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12137, 'ptBR', 'Fica frio, camarada', 'Gan\'jo quer que você colete a Neve do Sono Eterno no baú nas Ruínas de Drakil\'jin.$b$bVocê então deverá usar a Neve nos Antigos Espíritos Drakkari de lá e levar as Partículas Espirituais Drakkari de volta a Kraz no Acampamento do Harkor.', 'É como as profecias disseram, cara. $gUm:Uma; $c $r vem aí pra botar nossos espíritos pra dormir. A gente já tá esperando há um tempão!$b$bOs Drakkari viraram um povo perdido, feroz e selvagem.$b$bMas aqui a gente sofre sem ser culpa nossa, cara. Esse lugar tem que ser purificado, e só os vivos podem fazer isso.$b$bFale comigo quando estiver pront$go:a; para se reunir ao seu corpo. Então cê pega a neve no baú aqui perto e bota meus camaradas pra dormir.$b$bLeva os resto deles pro teu guia espiritual. Ele tá sabendo o que tem que fazer depois.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kraz no Acampamento do Harkor, que fica na Serra Gris.', 0),
(12138, 'ptBR', '... Ou talvez a gente não tenha', 'Carregue seu Golem de Guerra com a energia de 10 Sentinelas Relâmpago e fale novamente com Raegar Quebracelha no Mirante do Minerador.', 'Era de se imaginar que os caras que fizeram as pilhas teriam pensado em carregá-las, mas não, eles precisam dificultar a nossa vida.$B$BMuito bem, vamos carregar as pilhas do jeito mais difícil. Há energia suficiente nelas para fazer o golem funcionar por um curto tempo, mas não espere que ele seja bom de briga nesse estado.$B$BEstá vendo as sentinelas relâmpago que os ferrosos postaram ao redor do perímetro de Dun Argol? Leve o golem com você, até bem perto das sentinelas, e use-o para absorver a energia quando elas morrerem.', '', 'Nível de Recarga', '', '', '', '', '', '', '', 'Fale novamente com Raegar Quebracelha no Mirante do Minerador.', 0),
(12139, 'ptBR', '"Que venha o fogo!"', 'A Matriarca Mascarada quer que você ajude a apagar os incêndios da vila. Quando acabar, fale novamente com a Matriarca Mascarada na cidade.', 'O Cavaleiro Sem Cabeça vai atacar a aldeia a qualquer momento! O fogo vai destruir tudo!$B$BPor favor, $n, ajude a brigada de incêndio. Pegue um balde e apague as chamas... ou passe-o para alguém que esteja perto delas. Apague os focos de incêndio, ainda há esperança!', 'Apague os focos de incêndio!', '', '', '', '', 'Apague os focos de incêndio!', '', '', '', 'Fale novamente com a Matriarca Mascarada.', 0),
(12140, 'ptBR', 'Salve Roanauk!', 'Procure por Roanauk Bruma Boreal no Martelo de Agmar, e oficie sua iniciação como membro e líder das tropas da Horda.$B$BFale novamente com o Lorde Supremo Agmar com o Juramento de Sangue da Horda quando você completar a missão.', 'Assim como os taurens, os mortos-vivos, os trolls e os elfos sangrentos, os taunkas também precisam de um líder do seu próprio sangue. O taunka que você salvou, Roanauk, será tal líder.$B$B<O Lorde Supremo Agmar entrega um pergaminho para você.>$B$BVocê já deve conhecer o que estou lhe entregando. É o juramento de sangue da Horda.$B$BLeve o juramento para Roanauk Bruma Boreal e oficie seu ingresso na Horda como líder dos taunkas.$B$BNão vamos deixá-lo esperando.$B$B<Agmar acena com a cabeça.>', '', 'Roanauk Bruma Boreal iniciado na Horda', '', '', '', '', '', '', '', 'Apresente-se ao Lorde Supremo Agmar no Martelo de Agmar, no Ermo das Serpes.', 0),
(12141, 'ptBR', 'Uma missão diplomática', 'Fale com Karuk, no Areal Quebramar, sudoeste da Bastilha Valentia.', 'Vejo que está $Gansioso:ansiosa; para ajudar, $n. Você não veio até Nortúndria para ficar $Gentocado:entocada; em uma cidade! Tenho o trabalho ideal para você... algo que vai levá-$Glo:la; para bem longe daqui.$B$BHá muito lutamos para cair nas graças dos morsanos de Nortúndria. Faz algum tempo que um jovem morsano veio nos pedir ajuda, algo que não pudemos oferecer na época.$B$BAgora que você está aqui, talvez possamos remediar isso. Procure Karuk perto do Areal Quebramar, a sudoeste daqui, e veja o que você pode fazer para ajudar.', '', '', '', '', '', '', '', '', '', '', 0),
(12142, 'ptBR', 'Controle de Pragas', 'Dúnio, do Front da 7ª Legião, quer que você mate 10 Nevolds da Planície Nevada e 3 Magnatauros do Ermo das Serpes, nos acampamentos de magnatauros ao redor do Templo do Repouso das Serpes.', 'Eca! Um daqueles nevolds tampinhas vandalizou nosso acampamento enquanto estávamos ocupados com aquele último dragão. Eles estão nos infernizando cada vez que viramos as costas... Já basta!$B$BVocê vai encontrar os nevolds ao sul, se escondendo debaixo da saia dos magnatauros daqui. Vá lá e mate-os.$B$BSe os magnatauros interferirem, mate-os também.', '', 'Nevolds da Planície Nevada', 'Magnatauros do Ermo das Serpes', '', '', '', '', '', '', 'Fale novamente com Dúnio, no Front da 7ª Legião, que fica no Ermo das Serpes.', 0),
(12143, 'ptBR', 'Perseguição no desfiladeiro', 'Dúnio quer que você persiga os nevolds pelo desfiladeiro a nordeste do Front da 7ª Legião, e que você dê um jeito no líder deles.', 'Não posso acreditar nisso! Outro bando dessas pestes acabou de tentar se escafeder com os nossos suprimentos. Eles estão correndo na direção daquele desfiladeiro ao norte. Vá atrás deles e dê um jeito no líder deles!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dúnio, no Front da 7ª Legião, que fica no Ermo das Serpes.', 0),
(12144, 'ptBR', 'Controle de pragas', 'Kontokanis, na Aldeia do Dragão Arruinado, quer que você mate 10 Nevolds da Planície Nevada e 3 Magnatauros do Ermo das Serpes, nos acampamentos de magnatauros ao redor do Templo do Repouso das Serpes.', 'Fala, mano! Aqueles nevolds tampinhas barbarizaram o acampamento durante o ataque do dragão. Eles tão de butuca o tempo todo, não tamos podendo nem virar as costas...$B$BJá deu, mano, já deu. Indo pra leste, cê vai dar de cara com os nevolds se escondendo debaixo da saia dos magnatauros. É pra matar geral, mano. Se algum magnatauro se meter, mata ele também.', '', 'Nevolds da Planície Nevada', 'Magnatauros do Ermo das Serpes', '', '', '', '', '', '', 'Fale novamente com Kontokanis, na Aldeia do Dragão Arruinado, que fica no Ermo das Serpes.', 0),
(12145, 'ptBR', 'Perseguição no desfiladeiro', 'Kontokanis quer que você persiga os nevolds pelo desfiladeiro a sul da Aldeia do Dragão Arruinado, e que você dê um jeito no líder deles.', 'Não tô acreditando, mano! As pestes nevold de novo! Tentaram surrupiar os suprimentos! Eles tão indo pelo desfiladeiro agora, vai atrás e acaba com o líder deles também!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kontokanis, na Aldeia do Dragão Arruinado, que fica no Ermo das Serpes.', 0),
(12146, 'ptBR', 'Implicações perturbadoras', 'Leve a Corneta de Batalha Brasonada para o Templo do Repouso das Serpes e procure alguém interessado em avaliar a ameaça potencial.', 'O lado de baixo da corneta leva um selo brasonado com um martelo e um relâmpago. Alguma coisa na corneta parece muito suspeita, vinda de um magnatauro.$B$BLeve a corneta para o sul, pelo Caminho dos Titãs até o Templo do Repouso das Serpes, e encontre alguém que possa se interessar por suas suspeitas.', '', '', '', '', '', '', '', '', '', 'Fale com Aurastrasza nos Ermos Dragônicos, no Ermo das Serpes.', 0),
(12147, 'ptBR', 'Implicações perturbadoras', 'Leve a Corneta de Batalha Brasonada para o Templo do Repouso das Serpes e procure alguém interessado em avaliar a ameaça potencial.', 'O lado de baixo da corneta leva um selo brasonado com um martelo e um relâmpago. Alguma coisa na corneta parece muito suspeita, vindo de um Magnatauro.$B$BLeve a corneta para o sul, pelo Caminho dos Titãs até o Templo do Repouso das Serpes, e encontre alguém que se interesse por suas suspeitas.', '', '', '', '', '', '', '', '', '', 'Fale com Aurastrasza nos Ermos Dragônicos, no Ermo das Serpes.', 0),
(12148, 'ptBR', 'Um tipo único', 'Encontre e mate Assolaosso no ou perto do desfiladeiro a noroeste do Santuário Dragônico Lazúli. Leve quaisquer provas que encontrar de volta a Aurastrasza no Templo do Repouso das Serpes.', 'Um selo deveras peculiar de se ver entre os magnatauros, o que sugere um grau de organização pouco comum entre eles.$B$BOs magnatauros raramente deixam de lado sua índole agressiva para cooperar uns com os outros. Desconfio que estejam planejando atacar um acampamento grande.$B$BDuvido muito que essa corneta seja a única. Gostaria que você provasse que estou enganada. No desfiladeiro a noroeste do Santuário Dragônico Lazúli, você encontrará Assolaosso. Vá desafiá-lo e traga-me quaisquer provas que possam confirmar minhas suspeitas.', '', '', '', '', '', '', '', '', '', 'Fale com Aurastrasza no Templo do Repouso das Serpes, que fica no Ermo das Serpes.', 0),
(12149, 'ptBR', 'O poderoso magnatauro', 'Cace e mate Sangrentauro, Quebra-Gelo e Gangredraco a leste do Templo do Repouso das Serpes.$B$BSangrentauro habita o canto sudeste dos Ermos Dragônicos, a norte do Santuário Dragônico Esmeralda. Quebra-Gelo patrulha o limite norte do Espelho da Aurora. Gangredraco vagueia no fundo dos penhascos a oeste do Santuário Dragônico Bronze.$B$BFale novamente com Aurastrasza no Templo do Repouso das Serpes quando os magnatauros forem mortos.', 'Os magnatauros são criaturas tremendamente violentas... esse é o principal motivo de não os vermos juntos em grande número. Um líder poderoso parece ter surgido dentre eles e precisamos caçá-lo se quisermos deter essa ameaça.$B$BVou perguntar por aí. Enquanto isso, preciso que os distraia o máximo que puder.$B$BA leste daqui, você encontrará três tochas. Perto delas, encontrará três poderosos magnatauros. Abata-os para nos dar tempo de caçar o líder.', '', '', '', '', '', '', '', '', '', 'Fale com Aurastrasza no Templo do Repouso das Serpes, que fica no Ermo das Serpes.', 0),
(12150, 'ptBR', 'O recluso mestre de runas', 'Encontre Dregmar Marcarruna perto da caverna dele, que fica no caminho para os penhascos acima do Espelho da Aurora. Desafie-o e descubra o nome do líder dos magnatauros custe o que custar. Fale novamente com Aurastrasza, no Templo do Repouso das Serpes, quando tiver a informação.', 'Dregmar Marcarruna é um mestre de runas magnatauro... um espécime raro. Ele faz o tipo solitário, mas já há algum tempo se associou a magnatauros mais poderosos e influentes no Ermo das Serpes. Ele deve saber quem é esse novo líder.$B$BDuvido que consigamos ajuda, tendo em vista os crescentes problemas com o Flagelo e a revoada azul. Então quero que você obtenha essa informação de Dregmar pelos meios que se fizerem necessários.$B$BEle pode ser encontrado entre os penhascos acima do Espelho da Aurora.', 'Nome do Chefe Guerreiro Magnatauro', '', '', '', '', 'Nome do Chefe Guerreiro Magnatauro', '', '', '', 'Fale com Aurastrasza no Templo do Repouso das Serpes, que fica no Ermo das Serpes.', 0),
(12151, 'ptBR', 'Senhor sinistro', 'Vá até o círculo de tochas a sul do Santuário Dragônico Lazúli e toque a Corneta de Batalha Brasonada. Derrote Grom\'thar, o Arauto do Trovão, e leve a cabeça dele para Aurastrasza no Templo do Repouso das Serpes.', 'Não há motivos para duvidar das palavras de Dregmar. Quer Grom\'thar derrote ou seja derrotado por você, as mãos dele estão limpas.$B$BSiga as instruções que ele deu e leve a corneta que me trouxe anteriormente, vá até o círculo de tochas ao sul do Santuário Dragônico Lazúli e toque a corneta para desafiar Grom\'thar.$B$BQuando Grom\'thar, o Arauto do Trovão, chegar, mate-o, e traga-me a cabeça dele.', '', '', '', '', '', '', '', '', '', 'Fale com Aurastrasza no Templo do Repouso das Serpes, que fica no Ermo das Serpes.', 0),
(12152, 'ptBR', 'O fim de Jin\'arrak', 'Kraz, no Acampamento do Harkor, quer que você colete a Oferenda Sagrada Drakkari nas Ruínas de Drakil\'jin e use o Pó Espiritual Drakkari nela. Use a Oferenda Drakkari Infundida nos gongos do lado de fora das Ruínas de Drakil\'jin.', 'É bom vê-$glo:la; novamente entre os vivos. Muitos dos que viajam pela trilha dos mortos não voltam para falar dela.$b$bEnquanto você esteve fora, uma visão apareceu diante do Kraz, revelando o que resta ser feito.$b$bUma oferenda sagrada está em algum lugar da cripta. Leve este pó espiritual criado com os restos que você coletou e a use na oferenda.$b$bA oferenda infundida porá um fim no senhor da guerra corrompido, e libertará as muitas almas atormentadas.$b$bQue os espíritos guiem seus atos, $n.', '', 'Senhor da Guerra Jin\'arrak destruído', '', '', '', '', '', '', '', 'Fale novamente com Kraz no Acampamento do Harkor, que fica na Serra Gris.', 0),
(12153, 'ptBR', 'O thane de ferro e sua bigorna', 'Use as habilidades do Golem de Guerra para derrotar o Thane de Ferro Furiamalho e em seguida fale novamente com Raegar Quebracelha no Mirante do Minerador.', 'Agora que o golem de guerra está recarregado, vamos aproveitar essa energia toda. Acione o golem dentro de Dun Argol para assumir o controle.$B$BO líder de Dun Argol é o thane de Ferro Furiamalho. Nossas informações indicam que Furiamalho tem um guarda-costas que o protege de qualquer dano.$B$BEsse guarda-costas é o constructo chamado "A Bigorna". Desative o constructo e a proteção desaparecerá.$B$BO thane geralmente fica na construção situada no topo de Dun Argol. É de lá de cima que ele supervisiona a produção do nível inferior.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Raegar Quebracelha no Mirante do Minerador.', 0),
(12154, 'ptBR', 'Apagão', 'Use os Explosivos do Raegar para destruir o Núcleo Rúnico de Força em Dun Argol, e em seguida apresente-se a Raegar Quebracelha no Mirante do Minerador.', 'O salão principal no topo de Dun Argol contém a fonte de energia da área inteira. Se você conseguir destruir o núcleo de força, Dun Argol ficará inutilizada por algum tempo.$B$BNada de energia significa nada de golems, de sentinelas e nada mais de armamentos-relâmpago.$B$BQuando fomos mandados para cá, nos disseram que os explosivos eram para escavações mas, graças ao Thane de Ferro Furiamalho, a pesquisa foi descartada. Podemos aproveitá-los para outros fins, porém. São a única coisa por aqui capaz de destruir o núcleo de força.', '', 'Núcleo de Força de Dun Argol destruído', '', '', '', '', '', '', '', 'Fale novamente com Raegar Quebracelha no Mirante do Minerador.', 0),
(12155, 'ptBR', 'Esmague a abóbora', 'Dê o Símbolo Sagrado Chamuscado para a Matriarca Mascarada.', 'Esta lanterna de abóbora está esquecida no meio da aldeia. Ela parece observar todos os que a olham, com um ar ameaçadoramente sombrio.$B$BAo esmagá-la, você encontra um antigo símbolo sagrado chamuscado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Matriarca Mascarada.', 0),
(12157, 'ptBR', 'O mensageiro perdido', 'Fale com o Mensageiro Lanson no Recanto das Estrelas, que fica no Ermo das Serpes.', 'Tivemos sorte de chegar até aqui, $n. Fomos emboscados pelo Flagelo assim que desembarcamos.$B$BDescobrimos que um dos nossos era um espião da Seita dos Malditos. Parece que Thassarian tem mais provas de infiltração dos sectários... acho que a coisa vai até o alto comando.$B$BMandei um dos meus melhores mensageiros para nosso posto avançado no Ermo das Serpes, mas ele ainda não voltou. Temo que ele tenha sido abatido pelo Flagelo. Você pode ir ao Ermo das Serpes procurá-lo? Ele atende por "Mensageiro Lanson".', '', '', '', '', '', '', '', '', '', '', 0),
(12158, 'ptBR', 'Mina da Pedra Oca', 'Procure por pistas dentro da Mina da Pedra Oca a noroeste do Acampamento da Brigada de Cerro Oeste.', 'Eu já queria mandar alguns dos nossos rapazes dar uma olhada na Mina da Pedra Oca. Ainda não tive uma oportunidade, porém... estamos ocupados demais lidando com a Horda a oeste e os anões de ferro a leste.$B$BMas, se Dumont te mandou aqui, o mínimo que posso fazer é te indicar a direção correta.$B$BA entrada da mina fica a noroeste, não muito longe daqui. Veja se dá para a gente aproveitar as operações por lá. Certamente seria bom ter mais recursos disponíveis pelo menos até que nossa mina em Algures esteja operacional de novo.', '', '', '', '', '', '', '', '', '', '', 0),
(12159, 'ptBR', 'Almas inquietas', 'Petrov, na Mina da Pedra Oca, quer que você use o Lampião do Minerador para queimar os corpos de 8 Mineradores da Pedra Oca.', '<Petrov parece estar profundamente perturbado, com a respiração ofegante e o olhar dardejando para todos os lados.>$B$BMeus camaradas... precisamos dar descanso às suas almas. Eu mato e continuo matando... mas eles simplesmente voltam!$B$BTive uma ideia a respeito disso há algum tempo, mas não tenho coragem para executá-la eu mesmo.$B$BTalvez você possa fazer isso por mim? Pegue este lampião e use o óleo para queimar os seus restos mortais, de modo que eles nunca mais se levantem.$B$BResponderei às suas perguntas mais tarde, ajude meus amigos primeiro!', '', 'Mineradores Apaziguados', '', '', '', '', '', '', '', 'Fale novamente com Petrov na Mina da Pedra Oca, que fica na Serra Gris.', 0),
(12160, 'ptBR', 'Um nome do passado', 'Fale novamente com o Capitão Miguel Mantoforte no Acampamento da Brigada de Cerro Oeste.', 'Funcionou! Funcionou! Meus camaradas finalmente podem gozar do merecido descanso...$B$BVou ficar aqui e terminar o serviço. Nós, mineradores da Pedra Oca, sempre terminamos o serviço – somos mineradores e não desistimos nunca!$B$BPor isso que Arugal tentou nos usar como exemplo. A gente não cedia, entendeu? Jamais nos juntaríamos a essa seita dos lobos!', '', '', '', '', '', '', '', '', '', '', 0),
(12161, 'ptBR', 'Ruuna, a Cega', 'Fale com Ruuna, a Cega, no Acampamento da Ruuna, perto do Desfiladeiro de Vordrassil.', 'E aí. Escutei a sua conversa com o capitão, e você precisa saber... as coisas não são tão simples em Nortúndria.$B$BSó porque alguém está morto, não quer dizer que é carta fora do baralho.$B$BA sudoeste daqui, perto do Passo de Vordrassil, mora uma mulher que atende pelo nome de Ruuna, a Cega. Dizem que ela fala com os mortos e tem visões do passado e futuro.$B$BNão escutei a sua história toda, mas parece que ela poderia lhe ajudar muito.', '', '', '', '', '', '', '', '', '', '', 0),
(12164, 'ptBR', 'Arugal II: A Missão', 'Sasha, no Entreposto Pinheiro Branco, quer que você vá à Ilha Sangreluna e mate Selas, Varlam, Gorjavil e o Vulto de Arugal.', 'Chegou a hora então, $n. Arugal tem que ser derrotado.$B$BChame alguns amigos de confiança e vá para a Ilha Sangreluna. Ela fica perto da costa, a leste daqui.$B$BVamos atacá-los rapidamente. Elimine os tenentes de Arugal; eu te alcanço quando chegar a hora de enfrentar o próprio monstro.', '', '', '', '', 'Vulto de Arugal derrotado', '', '', '', '', 'Fale novamente com Sasha no Entreposto Pinheiro Branco, que fica na Serra Gris.', 0),
(12165, 'ptBR', 'Um plano intrigante', 'Traga o Diagrama do Golem de Pedra completo para Rokar na Aldeia Oneqwah.', 'O Prospector Rokar decidiu nos ajudar. Ele tramou um plano para usar a força dos anões de ferro contra eles mesmos.$B$BTenho de admitir, nosso novo "amigo" é mais intuitivo do que poderia acreditar. Ele tem razão em afirmar que somos muito poucos para um ataque frontal.$B$BVá até Dun Argol, nas regiões nevadas do sudeste, e confisque todas as partes dos diagramas de Golem de Guerra com os forjadores de runas. Traga o diagrama completo para Rokar, e então veremos se o plano dele vale alguma coisa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Prospector Rokar na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12166, 'ptBR', 'O fogo líquido de Eluna', 'A Guardiã Jodi Lunacanto, no Recanto das Estrelas, quer que você use o Fogo Líquido de Eluna para limpar os cadáveres de 6 Cervos Empesteados e 6 Ursos Árticos Raivosos.', '$R, você pode me ajudar?$B$BO Flagelo se deslocou para a Bruma Boreal, mais ao norte. Eles espalham sua mácula por onde quer que vão, e as criaturas da terra sofrem.$B$BPegue este frasco cheio do fogo líquido de Eluna, retirado do poço lunar. Por favor, use o líquido para limpar os cadáveres dos animais selvagens que você encontrar.', '', 'Cadáver de Cervo Empesteado limpo', 'Cadáver de Urso Ártico Raivoso limpo', '', '', '', '', '', '', 'Fale novamente com Jodi Lunacanto no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12167, 'ptBR', 'Mate os sectários', 'Colete 5 Roupas Funcionais de Sectários para a Guardiã Jodi Lunacanto, no Recanto das Estrelas.', 'Os sectários de Anub\'ar são indiretamente responsáveis pela contaminação das feras e precisamos dar um basta!$B$BA fumaça que vaza das roupas deles contamina tudo o que toca, envenenando e corrompendo o ambiente.$B$BVá para o norte, para a Aldeia Bruma Boreal, e mate-os. Traga as roupas deles que você conseguir juntar, e eu farei com que sejam eliminadas da maneira certa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Jodi Lunacanto no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12168, 'ptBR', 'O presente de Zangus', 'Entregue o Presente de Zangus para a Guardiã Jodi Lunacanto, no Recanto das Estrelas.', 'Uma inscrição nas costas do objeto diz:$B$B"Para meu pupilo favorito.$B$BSe continuar progredindo assim, ensinarei a você coisas além da imaginação.$B$BCaso contrário, eu o destruirei!$B$BDo seu,$B$BGrão-sectário Zangus"$B$BSem dúvida os guardiães no Recanto das Estrelas vão querer ver isso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Jodi Lunacanto no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12169, 'ptBR', 'O Grão-sectário', 'A Guardiã Jodi Lunacanto, no Recanto das Estrelas, quer que você mate o Grão-sectário Zangus.', 'Eu já sonhara com Zangus, mas sem o contexto fornecido por você, eu não sabia como interpretar a informação. Você iluminou a visão que a deusa me concedeu, e, agora, sei que ele pode ser encontrado no Fosso de Narjun, ao norte.$B$BJá tem o seu alvo, $n. Se quisermos que o sofrimento dessa terra acabe, o grão-sectário deve morrer!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Jodi Lunacanto no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12170, 'ptBR', 'Olhos roxos no Rio Negro', 'O Capitão dos Saqueadores Kronn quer que você mate 10 unidades ou jogadores da Horda na Madeireira Rio Negro.', 'A Empreendimentos S.A. abandonou as operações aqui logo depois de aparecermos. Obviamente, eles ficaram com medo de descobrir o que nós iríamos fazer com os couros mesquinhos deles.$B$BAgora que os ratos partiram, os campos de desmatamento estão disponíveis. Nossa máquina de guerra é uma fera faminta... Se não renovarmos nossos suprimentos, não chegaremos à Coroa de Gelo.$B$BInfelizmente, a Aliança teve a mesma ideia, e precisamos botá-los para fora daqui. Vá para o campo de desmatamento e nos ajude a enfrentar os vermes da Aliança.', '', 'Unidades da Aliança mortas no Rio Negro', '', '', '', '', '', '', '', 'Fale novamente com o Capitão de Saqueadores Kronn na Serra Gris.', 0),
(12171, 'ptBR', 'Sobre traição e traidores', 'Mostre a Missiva da Aliança para Palena Nefelargenta no Recanto das Estrelas.', 'Esta lista deve ser entregue ao alto-comandante Haraldo Serpecida. Ele comanda a 7ª Legião, aquartelada na Bastilha Invergarde, na fronteira oriental do Ermo das Serpes.$B$BSe algum dos traidores mencionados nessa lista estiver em Invergarde, pode haver uma catástrofe!$B$BDepressa, $n. Mostre este documento a Palena Nefelargenta aqui no Recanto das Estrelas e explique sua missão a ela. Ela colocará você no grifo mais rápido para Invergarde!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Palena Nefelargenta no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12172, 'ptBR', 'Em sintonia com Dalaran', 'A Imagem da Arquimaga Modera, no Recanto das Estrelas, quer que você entre em sintonia com as Linhas de Meridiano de Nortúndria.', '$gBem-vindo, mago:Bem-vinda, maga;.$B$BVocê deve estar se perguntando onde fica Dalaran, e como chegar lá. Eu vou ajudar.$B$BMas antes de dizer como pode se teleportar para nossa bela cidade, você precisa entrar em sintonia com as linhas de meridiano de Nortúndria. Senão, você será $gdestruído:destruída;.$B$BPegue este cristal de sintonia e use-o no fosso abaixo da agulha de mana nos Jardins Lua Serena, a oeste daqui. Aí você estará $gpronto:pronta; para aprender o feitiço.', '', 'Em sintonia com as Linhas de Meridiano de Nortúndria', '', '', '', '', '', '', '', 'Fale com a Imagem da Arquimaga Modera no Recanto das Estrelas, que fica no Ermo das Serpes.', 0),
(12173, 'ptBR', 'Em sintonia com Dalaran', 'A Imagem do Arquimago Aethas Fendessol, no Martelo de Agmar, quer que você entre em Sintonia com as Linhas de Meridiano de Nortúndria.', 'Olá, $gmago:maga;.$B$BVocê deve estar se perguntando onde fica Dalaran, e como chegar lá. Eu vou ajudar se você conseguir sobreviver a um teste simples.$B$BAntes de dizer como pode se teleportar para nossa bela cidade, você precisa entrar em sintonia com as linhas de meridiano de Nortúndria. Senão, você será $gdestruído:destruída;.$B$BPegue este cristal de sintonia e use-o no fosso abaixo da agulha de mana nos Jardins Lua Serena, a sudoeste daqui. Então você estará $gpronto:pronta; para aprender o que tenho a ensinar.', '', 'Em sintonia com as Linhas de Meridiano de Nortúndria', '', '', '', '', '', '', '', 'Volte à Imagem do Arquimago Aethas Fendessol no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12174, 'ptBR', 'Alto-comandante Haraldo Serpecida', 'Entregue a Missiva da Aliança para o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, a leste do Ermo das Serpes.', '<Palena lhe devolve a missiva.>$B$BNeveforte levará você a Invergarde, $n. Garanto que será o voo mais rápido da sua vida. Agora vá!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12175, 'ptBR', 'Pelegos de worg cinzento', 'O Comerciante de Peles Jun\'ik, no Forte da Conquista, quer que você lhe traga 3 Pelegos de Worg Cinzento dos Caçadores Brumagris das florestas ao norte.', 'Vou te contar uma parada, cara. Quando eles manda tu equipar o exército da Horda, tu precisa de pelego paca!$B$BA Conquistadora Krenna, a machona que manda nesse bagulho aqui, me deu uma mixaria de prazo. Se eu não equipar o regimento inteiro até o fim de semana, ela vai me botar pra lutar com ursos no fosso.$B$BMe ajuda aí que eu te pago bem pacas. Tô precisando de pelego de Caçador Brumagris.$B$BTem um montão deles pro norte, caçando cervos. Esquece não, cara. Pago bem pacas!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comerciante de Peles Jun\'ik no Forte da Conquista, que fica na Serra Gris.', 0),
(12176, 'ptBR', 'Uma pequena substituição', 'O Comerciante de Peles Jun\'ik quer que você lhe traga 6 Pelegos de Urso-cinzento.', 'A Krenna, ela quer uns pelegos de worg pra todos os soldados. Só que não vai rolar pelego de worg pro exército inteiro. Nem agora, nem nunca.$B$BEsses worgs... eles são magrinhos, cara! O negócio é o seguinte... desde que tu guarde segredo, claro.$B$BA leste de Runavold tem uns urso-cinzento gordo que nem ogro. Esses pelegos são grandões, aí a gente pode usar!$B$BAnda logo, $gmano:mina;. A Krenna é pavio curto.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comerciante de Peles Jun\'ik no Forte da Conquista, que fica na Serra Gris.', 0),
(12177, 'ptBR', 'A malandragem do Jun\'ik', 'Leve 1 pedaço de Carvão e 5 unidades de Farinha Simples para o Comerciante de Peles Jun\'ik no Forte da Conquista, que fica na Serra Gris.', 'Ah, temos um probleminha. Os pelegos de urso-cinzento... são marrons, cara!$B$BPensa... pensa!$B$BJá sei, cara! É tipo assim: cinzento é preto e branco tudo misturadão. Se tu me arranjar carvão e farinha, eu vô moer a parada toda e salpicar nos pelegos. Ninguém vai ver a diferença!$B$BOs ferreiros vendem carvão pra derreter as coisa, e dá pra comprar farinha com algum fornecedor.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comerciante de Peles Jun\'ik no Forte da Conquista, que fica na Serra Gris.', 0),
(12178, 'ptBR', 'Entrega para a Sra. Krenna', 'Entregue o Pacote de Peles a Krenna no Forte da Conquista', 'É isso aí, cara. Vamos levar esses pelegos pra Krenna e ver se ela cai no truque.$B$BÉ bom a gente torcer, pelo nosso bem, que a Krenna não saque nada.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Conquistadora Krenna, no Forte da Conquista, na Serra Gris.', 0),
(12180, 'ptBR', 'Os prospectores cativos', 'Liberte o Prospector Gann, o Prospector Torgan e a Prospectora Varana, e em seguida fale novamente com o Montanhista Kilian no Mirante do Minerador.', 'Raegar mandou uma equipe de prospectores a Dun Argol em busca de artefatos e informações sobre a história do povoado. Ninguém na equipe esperava que Dun Argol fosse tão populoso.$B$BEstão todos presos enquanto os anões de ferro se preparam para a guerra. Não temos gente suficiente para atacá-los, e Raegar está ocupado demais criando fantasias da derrota dos ferrosos para nos ajudar.$B$BPortanto, dependemos de você, $n. As chaves das jaulas dos nossos companheiros devem estar com os ferrosos, ou com os servos deles.', '', 'Prospector Gann Resgatado', 'Prospector Torgan Resgatado', 'Prospectora Varana Resgatada', '', '', '', '', '', 'Fale novamente com o Montanhista Kilian no Mirante do Minerador, que fica na Serra Gris.', 0),
(12181, 'ptBR', 'Dê nome à criança', 'Mostre o Espécime de Praga para Tobias Sarkhoff em Nova Agamand.', 'Céus, quanto tempo! Há quanto tempo estamos trabalhando nesta maldita praga? Finalmente, após falhas sem fim, fomos abençoados com a perfeição. Isso... Ainda nem lhe demos um nome! Essa praga... É isso! PRAGA! Essa praga vai esgarçar o tecido da vida!$B$B<Espargosa entrega um frasco para você.>$B$BVá agora, encontre Tobias, o tratador de morcegos, e mostre-lhe o espécime. Ele $Go:a; encaminhará para Perfídia.', '', '', '', '', '', '', '', '', '', 'Fale com Tobias Sarkhoff na cidade de Nova Agamand, que fica no Fiorde Uivante.', 0),
(12182, 'ptBR', 'Para Perfídia!', 'Entregue o Espécime de Praga para o Pestífero-chefe Militão em Perfídia, na parte leste do Ermo das Serpes.', 'Tenho um morcego especial separado para você, $Gamigo:amiga;. A montaria mais rápida e mais suave daqui. Ele vai levar você direto para Perfídia – em grande estilo.$B$BApenas entregue o frasco para o pestífero-chefe Militão assim que você aterrissar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Pestífero-chefe Militão no Ermo das Serpes.', 0),
(12183, 'ptBR', 'Vestindo a beca', 'Traga o Uniforme do Supervisor para o Montanhista Kilian no Mirante do Minerador.', 'Se o que a prospectora Varana falou for verdade, e apenas alguns ferrosos têm permissão para se comunicar com o tal do Loken, então deve ser um privilégio dos feitores.$B$BTemos que infiltrar você para saber do que se trata, mas não será fácil. O primeiro passo é conseguir um uniforme que lhe seja apropriado.$B$BDepois a gente se preocupa com a maquiagem.$B$BAche um dos supervisores em Dun Argol, mate-o e traga-me o uniforme. Se o uniforme ficar sujo de sangue, a culpa será toda sua.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Kilian no Mirante do Minerador, que fica na Serra Gris.', 0),
(12184, 'ptBR', 'Cultivando uma imagem', 'Use a Câmera do Kilian para gravar imagens de 8 Anões de Ferro em Dun Argol, e em seguida fale novamente com o Montanhista Kilian no Mirante do Minerador.', 'Agora que já temos um uniforme, precisamos de mais informações para completar a camuflagem.$B$BRaegar trouxe uma câmera para documentar as descobertas da equipe, mas estou pensando numa utilidade diferente para ela. Quero que você a leve consigo a Dun Argol e capture imagens dos anões de ferro.$B$BÉ claro que os seus modelos não serão do tipo mais cooperativo, então você provavelmente terá que... hum, subjugá-los primeiro. Traga a câmera e as imagens quando terminar.', '', 'Imagens de Anão de Ferro registradas', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Kilian no Mirante do Minerador, que fica na Serra Gris.', 0),
(12185, 'ptBR', 'Fazendo carão para Loken', 'Use o disfarce de Feitor da Runa Férrea, intercepte a mensagem de Loken e por fim se apresente ao Montanhista Kilian no Mirante do Minerador.', 'Usando as imagens que você registrou, preparei tudo que você precisa para o kit de disfarce de supervisor. Você será um belo anão de ferro, se me permite dizer.$B$BLeve o kit até Dun Argol e se disfarce, e depois vá ao edifício no extremo leste do largo setor intermediário da cidade.$B$BLá você verá um pedestal onde o Thane e os feitores recebem as ordens do tal Loken. Ative o pedestal enquanto estiver $gdisfarçado:disfarçada; e ouça o comunicado com atenção.', '', 'Mensagem de Loken recebida', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Kilian no Mirante do Minerador, que fica na Serra Gris.', 0),
(12186, 'ptBR', 'ESTANDARTE: vencedor', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(12187, 'ptBR', 'ESTANDARTE: participante', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(12188, 'ptBR', 'A praga dos renegados e você: como não morrer', 'O Pestífero-chefe Militão, em Perfídia, que fica no Ermo das Serpes, quer que você leve 10 Resíduos Ectoplásmicos para ele.', 'Os detalhes sobre a funcionalidade da praga não importam. Tudo o que você precisa saber é que a praga faz aquilo para que foi projetada. Eu consegui sintetizar uma cepa inerte da praga.$B$B<Militão destapa um frasco e aspira.>$B$BVê? Meu corpo ainda está quase todo intacto. Se você misturasse isso com um agente reativo, iríamos todos virar montes amorfos de gosma.$B$BNa praia ao sul daqui, você encontrará patéticos fantasmas de soldados da Aliança. Derrote-os e me traga seus resíduos ectoplásmicos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Pestífero-chefe Militão em Perfídia, no Ermo das Serpes.', 0),
(12189, 'ptBR', 'Imbecis aos montes!', 'Vá para Perfídia, no Ermo das Serpes e fale com o Pestífero-chefe Militão.', 'O carregamento de Nova Agamand deveria ter chegado a Perfídia na semana passada. Era pra ter sido entregue a mim após alguns testes simples em campo. Essa é uma prioridade da Horda, a última peça do "quebra-cabeças da vitória."$B$B<Síntar suspira.>$B$BÉ muito desanimador estar cercado de imbecis e pamonhas incompetentes!$B$BQuero que você vá para Perfídia, perto da fronteira oriental do Ermo das Serpes. Encontre aquele palhaço, o Militão, e diga a ele que estou esperando a encomenda.', '', '', '', '', '', '', '', '', '', '', 0),
(12190, 'ptBR', 'O Prigmon mandou um beijo', 'Prigmon quer que você entregue os Ingredientes do Harkor ao Harkor no Acampamento do Harkor.', 'O Harkor vai parir um mico-leão-dourado quando vir esses ingredientes de primeira. Só falta tu levar a parada pra ele.$b$bEle tá acampado na costa leste, perto lá daquelas ruínas assombradas... Drakil\'jin, é o nome.$b$bTu provavelmente vai chegar lá antes de eu terminar com esses cadáveres... A não ser que... tu tá a fim de aprender a embalsamar?', '', '', '', '', '', '', '', '', '', 'Procure Harkor no Acampamento do Harkor, que fica na Serra Gris.', 0),
(12191, 'ptBR', 'Caneco no boneco!', 'Use a Amostra sem Álcool da CervaFest para acertar o B.I.R.I.T.A. 5 vezes. Depois, fale com Bizu Sobelogo.', 'Aquelas pestes dos Ferro Negro estão de volta! Temos que saber se você sabe se defender, caso necessário. E mais importante ainda: temos que saber se você é capaz de defender a nossa propriedade!$b$bMeu amigo B.I.R.I.T.A. aqui está em ponto de bala, e você? Beba uma amostra sem álcool da CervaFest e jogue a caneca direto no B.I.R.I.T.A.! Acerte ele cinco vezes e depois volte aqui.', '', 'B.I.R.I.T.A. atingido', '', '', '', '', '', '', '', 'Fale novamente com Bizu Sobelogo em Durotar.', 0),
(12192, 'ptBR', 'Certa vez, quando eu estava bêbado...', 'Fale com Bizu Sobelogo no acampamento da CervaFest.', 'Os Ferro Negro levaram uma surra! E, durante a fuga desembestada para o Glutão Implacável, uma peça do veículo deles caiu. O mais importante é que você ajudou a manter a CervaFest segura... pelo menos por hoje.$b$bConte para o Bizu sobre a sua incrível vitória sobre os anões Ferro Negro.', '', '', '', '', '', '', '', '', '', '', 0),
(12195, 'ptBR', 'O "convidado" inesperado', 'Traga 5 Chifres de Cervo Adulto para Tormak, o Marcado, na Aldeia Oneqwah.', 'Uma expedição de caça recente trouxe de volta algo além da carne.$B$BEncontraram um anão ferido fugindo da fortaleza ferro-enânica de Dun Argol. Talvez ele saiba de coisas que possam nos ajudar na ofensiva contra nosso inimigo ancestral. Porém, para que o anão possa nos ajudar, precisamos baixar a febre dele.$B$BOs chifres dos cervos mantoprata, que vagueiam pela floresta vizinha, há muito são usados no preparo de cataplasmas curativos. Se você me trouxer chifres suficientes, talvez o cataplasma tenha efeito curativo no nosso "convidado".', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tormak, o Marcado, na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12196, 'ptBR', 'Do começo ao fim', 'Traga 8 Peças de Golem de Guerra para Rokar na Aldeia Oneqwah.', 'Não há tempo para que eu forje as peças pessoalmente, mas as fundições em Dun Argol, a sudeste, trabalham dia e noite produzindo peças de golem.$B$BAcho que você deveria voltar lá e pegar peças suficientes para que eu possa fazer um golem com estes diagramas.$B$BProvavelmente estão espalhadas pelos prédios onde os forjadores de runas trabalham.$B$BPor favor, se apresse, $n. Aquele Tormak parece estar só esperando por uma desculpa para executar as ameaças.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Prospector Rokar na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12197, 'ptBR', 'Nós temos a força', 'Traga a Pilha do Durar e a Pilha de Kathorn para o Prospector Rokar da Aldeia Oneqwah.', 'Bem, temos aqui um golem sem vida, mas não é o suficiente para Tormak. Ele não entende que essas coisas não começam a funcionar só porque estão montadas! Precisamos de pilhas para animá-lo.$B$BQuando eu estava em Dun Argol, percebi que eram o Forjador de Runas Durar e o Forjador de Runas Kathorn que fabricavam pilhas. Precisaremos de uma pilha de cada um deles para energizar nosso golem.$B$BEles devem estar nas respectivas oficinas, no nível central de Dun Argol.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Prospector Rokar na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12198, 'ptBR', '... Ou talvez a gente não tenha', 'Carregue seu Golem de Guerra com a energia de 10 Sentinelas Relâmpago e fale novamente com o Prospector Rokar na Aldeia Oneqwah.', 'As pilhas do golem têm energia suficiente para que ele funcione nos níveis mais baixos, mas não podemos acionar nenhum dos sistemas de combate.$B$BA boa notícia é que o perímetro de Dun Argol é patrulhado por sentinelas relâmpago. Acho que dá para aproveitar a energia delas para recarregar os sistemas bélicos do golem.$B$BLeve o golem com você, até bem perto das sentinelas, e use-o para absorver a energia quando elas morrerem.', '', 'Nível de Recarga', '', '', '', '', '', '', '', 'Fale novamente com o Prospector Rokar na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12199, 'ptBR', 'Derrubando o Thane de Ferro', 'Use as habilidades do Golem de Guerra para derrotar o Thane de Ferro Furiamalho, e em seguida fale novamente com Tormak, o Marcado, na Aldeia Oneqwah.', 'Agora que o golem está totalmente carregado, ele pode ser usado contra o líder de Dun Argol.$B$BO thane de ferro Furiamalho tem sempre ao lado um golem pessoal que o protege de qualquer ataque.$B$BO nome do constructo é Bigorna, e ele pode ser desativado, desligando, assim, o escudo protetor. Use a habilidade de PEM do seu golem para fazer isso. Será possível ativar e controlar o golem dentro de Dun Argol.$B$BO thane está na fábrica principal, no alto, e supervisiona a produção no piso térreo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tormak, o Marcado, na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12200, 'ptBR', 'Lágrimas de dragão esmeralda', 'O Pestífero-chefe Militão, em Perfídia, que fica no Ermo das Serpes, quer que você leve 8 Lágrimas de Dragão Esmeralda para ele.', 'Com um espécime inerte da praga terminado, e com o agente ativador em mãos, só precisamos de uma cápsula adequada para abrigar os componentes.$B$BA sudoeste daqui, nas praias mais ao centro do Ermo das Serpes, você encontrará o Santuário Dragônico Esmeralda. Dentro do Santuário, você encontrará os restos endurecidos de uma lágrima de dragão verde. Eu não sei os detalhes direito, mas parece que eles choram bastante antes de morrer. Enfim...$B$BVá ao Santuário Dragônico Esmeralda e recolha lágrimas para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Pestífero-chefe Militão em Perfídia, no Ermo das Serpes.', 0),
(12201, 'ptBR', 'A sombra do feitor', 'Traga o Uniforme do Supervisor para o Batedor Vor\'takh na Aldeia Oneqwah, que fica na Serra Gris.', 'Parece que Loken é o mestre por trás dos súbitos preparativos de guerra dos anões de ferro.$B$BSó os oficiais mais elevados têm permissão para falar com ele, então você terá de se tornar um feitor para descobrir o que está acontecendo por lá.$B$BEu tenho um plano para tanto, mas vamos precisar de alguns apetrechos.$B$BEncontre um dos supervisores da runa férrea em Dun Argol, a sudeste, mate-o, e me traga o uniforme.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Batedor Vor\'takh na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12202, 'ptBR', 'Cultivando uma imagem', 'Use a Câmera de Rokar para registrar as imagens de 8 Anões de Ferro em Dun Argol, e em seguida fale novamente com o Batedor Vor\'takh na Aldeia Oneqwah.', 'Agora temos que terminar o serviço de te tornar tão repugnante quanto aqueles anões de ferro.$B$BA melhor maneira de chegar lá é basear seu disfarce nas próprias carrancas dos anões de ferro de verdade.$B$BQuando o grupo de caça de Tormak encontrou aquele prospector perdido, eles tomaram a câmera do sujeito. Acho que chegou a hora de a gente usar isso.$B$BVá a Dun Argol com a câmera, mate alguns anões de ferro e registre a fuça deles no aparelho. Volte aqui quando tiver exemplos o suficiente.', '', 'Imagens de Anão de Ferro registradas', '', '', '', '', '', '', '', 'Fale novamente com o Batedor Vor\'takh na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12203, 'ptBR', 'Ordens de Loken', 'Use o disfarce de Feitor da Runa Férrea, intercepte a mensagem de Loken e por fim se apresente ao Batedor Vor\'takh na Aldeia Oneqwah.', 'Preparei tudo que você precisa para o disfarce de feitor. Tente não vomitar ao vesti-lo. Eu me esforcei ao máximo para que ficasse o mais realista possível.$B$BLeve o kit até Dun Argol e se disfarce, e depois vá ao edifício mais a leste do largo setor intermediário da cidade.$B$BLá você verá um pedestal onde o Thane e os feitores recebem as ordens do tal Loken. Ative o pedestal enquanto estiver $gdisfarçado:disfarçada; e ouça o comunicado com atenção.', '', 'Mensagem de Loken recebida', '', '', '', '', '', '', '', 'Fale novamente com o Batedor Vor\'takh na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12204, 'ptBR', 'Tá todo mundo Loken', 'Fale com Hugo Copas e Gavrocha sobre Loken, e em seguida apresente suas descobertas ao Batedor Vor\'takh na Aldeia Oneqwah.', 'Os anões de ferro são nossos inimigos mais ferozes e organizados em Nortúndria. Por onde passamos, lá estavam eles, nos atacando com o nome de Loken nos lábios.$B$BPrecisamos descobrir quem é esse Loken e o que ele quer. Os habitantes desta região talvez possam nos ajudar.$B$BA nordeste daqui, no Entreposto Sequoia, um humano chamado Hugo Copas vende bugigangas. Mais ao leste, nas Ruínas de Tethys, você encontrará um gigante de pedra chamado Gavrocha. Pergunte a eles o que sabem desse Loken. Certamente sabem algo de útil.', '', 'Hugo Copas interrogado', 'Gavrocha interrogado', '', '', '', '', '', '', 'Fale novamente com o Batedor Vor\'takh na Aldeia Oneqwah, que fica na Serra Gris.', 0),
(12205, 'ptBR', 'Procura-se: A Ofensiva Escarlate', 'Mate 20 membros da Ofensiva Escarlate e, então, apresente-se ao Alto-executor Iracundo, em Perfídia.', 'Por ordem do Alto-executor Iracundo, todos os membros da organização ilegal conhecida como Ofensiva Escarlate deverão ser executados imediatamente.$B$BNenhum refúgio poderá ser oferecido a eles, e saibam os que forem cumprir este decreto que serão deixados para morrer, ou pior, em caso de serem capturados pelos humanos!$B$BNas palavras do Alto-executor, "Quero a neve pintada de vermelho com o sangue deles!"', '', 'Membros da Ofensiva Escarlate mortos', '', '', '', '', '', '', '', 'Fale novamente com o Alto-executor Iracundo em Perfídia, que fica no Ermo das Serpes.', 0),
(12206, 'ptBR', 'Os ritos finais da praga', 'A Boticária Rivadávia Levine, em Perfídia, quer que você teste a Ampola de Praga no Prisioneiro da Ofensiva Escarlate.', 'Você leu aquele cartaz de "procura-se"? O que o alto-executor está pensando?!$B$B<Rivadávia olha ao redor e continua sussurrando.>$B$BNinguém quer esses idiotas da Ofensiva Escarlate sendo ressuscitados – ou pior, entrando para as fileiras do Flagelo, não é verdade?$B$BNão, eu concordo totalmente com você, precisamos tomar uma providência quanto a esses cadáveres.$B$BEu tenho a coisa certa pra isso. Pegue essa amostra da praga que acabamos de criar e teste no prisioneiro ali daquela jaula.$B$BTrabalho limpo, silencioso, e ninguém em volta pra criar problemas...', '', 'Ampola de Praga testada', '', '', '', '', '', '', '', 'Fale novamente com a Boticária Rivadávia Levine, em Perfídia, que fica no Ermo das Serpes.', 0),
(12207, 'ptBR', 'A queda de Vordrassil', 'A Vidente Chifre Cinzento, no Forte da Conquista, quer que você vá até a Rama de Vordrassil, Coração de Vordrassil ou Lágrimas de Vordrassil e obtenha 6 Amostras de Visgo das Gosmas Entrópicas.', 'Há muito tempo, druidas poderosos plantaram uma árvore a nordeste daqui.$B$BChamaram-na de Vordrassil, era para ela ser uma árvore do mundo. Não se sabe a razão, mas depois que a árvore estava completamente crescida, os druidas decidiram que precisava ser destruída.$B$BDesde que chegamos aqui, a terra fala comigo, $n. Os gritos de dor desta região vêm dos lugares onde os restos de Vordrassil tombaram.$B$BGosmas corruptoras vagueiam por lá. Traga-me amostras da substância para que possamos iniciar a cura desta terra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Vidente Chifre Cinzento no Forte da Conquista, que fica na Serra Gris.', 0),
(12208, 'ptBR', 'Gênio introllável', 'O Sargento Thurkin mandou você falar com Samir nas Fontes Graníticas.', 'Vermes imprestáveis!$b$bEles poderiam ter ficado na moleza. Estendemos a mão em nome da amizade. Se eles nos tivessem deixado passar por Drak\'Tharon, nós os teríamos deixado em paz.$b$bMas não: os trollzinhos do gelo orgulhosos decidiram complicar as coisas. Agora, vamos destruí-los e passaremos pela preciosa fortaleza deles a caminho de Zul\'Drak do mesmo jeito!$b$bContratamos uma gangue para nos entregar trolls capturados. Fale com Samir se quiser ganhar um trocado também. Ele está a noroeste daqui, ao sul de Zeb\'Halek.', '', '', '', '', '', '', '', '', '', '', 0),
(12209, 'ptBR', 'Roubo de equipamento', 'O Intendente Bartolotto, em Perfídia, quer que você roube 8 Armaduras da Ofensiva Escarlate e 8 Armas da Ofensiva Escarlate.', 'Ótimo, carne fresca. Quer mostrar serviço, carne fresca?$B$BA Ofensiva Escarlate, formada pelos membros mais fervorosos e racistas da Cruzada Escarlate, estão no nosso quintal, ao sul daqui. Se vamos combatê-los, precisaremos de mais armaduras e armas do que sou capaz de fabricar em tão pouco tempo.$B$BPor que não tomamos as deles?$B$BMelhor dizendo, por que VOCÊ não vai lá e toma deles?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Intendente Bartolotto em Perfídia, que fica no Ermo das Serpes.', 0),
(12210, 'ptBR', 'Temporada de caça aos trolls', 'O Tenente Dumont, no Chalé do Pinho Âmbar, quer que você fale com Samir nas Fontes Graníticas.', 'Ei, você aí, $r! Soldado que fica no quartel está procurando trabalho!$B$BA Bastilha Drak\'Tharon é o caminho mais direto para Zul\'Drak. TEMOS que capturá-la para assegurar a passagem segura da Aliança. Porém, até que tenhamos gente suficiente para montar um ataque, vamos nos contentar em matar os trolls do gelo e colher informações.$B$BPor isso, recrutamos uma gangue de valentões para capturar e nos entregar trolls vivos para interrogatório. Viaje para o noroeste e fale com Samir nas Fontes Graníticas. Ele lhe dirá o que fazer.', '', '', '', '', '', '', '', '', '', '', 0),
(12211, 'ptBR', 'Que eles não se levantem!', 'A Boticária Rivadávia Levine, em Perfídia, quer que você use a Caixa de Ratos para "limpar" os cadáveres de 15 membros da Ofensiva Escarlate, em Nova Amparo.', 'Eu não entendo. A praga deveria ter funcionado!$B$BNão adianta se preocupar com isso agora.$B$B<A boticária parece aliviada por alguma razão.>$B$BMesmo que a praga não funcione na Ofensiva, ainda assim precisamos impedir que os sacerdotes deles os ressuscitem.$B$BEu tive uma ideia para dar um jeito nos cadáveres.$B$B$n, leve os meus ratos num recipiente e solte-os em cima dos cadáveres dos membros da Ofensiva que você encontrar em Nova Amparo. Eu os deixo passando fome. Então, eles vão devorar o que aparecer pela frente!', '', 'Cadáveres da Ofensiva Escarlate "limpos"', '', '', '', '', '', '', '', 'Fale novamente com a Boticária Rivadávia Levine, em Perfídia, que fica no Ermo das Serpes.', 0),
(12212, 'ptBR', 'Reabastecimento', 'O Mestre Mateiro Anderhol, no Chalé do Pinho Âmbar, quer que você mate Cervos Altastes e recolha 8 pedaços de Carne Suculenta.', 'Bons dias, $c.$b$bO meu amigo tenente aqui me disse que a Horda saqueou nosso armazém, o que deixou nosso suprimento de comida perigosamente baixo.$b$bSem dúvida nós vamos nos vingar daqueles cretinos, mas primeiro temos que nos concentrar em nos reabastecer. Meus homens estão fazendo tudo que podem, mas vamos precisar de toda ajuda possível para evitar uma crise.$b$bVocê não terá dificuldades em coletar a carne dos cervos da região. Boa caçada!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mateiro Anderhol no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12213, 'ptBR', 'As trevas subterrâneas', 'A Vidente Chifre Cinzento, no Forte da Conquista, quer que você vá à Rama de Vordrassil, ao Coração de Vordrassil e às Lágrimas de Vordrassil e use o Orbe do Geomante nas profundezas.', 'Algo... maligno... ocorreu à árvore Vordrassil. Depois que os druidas decidiram destruí-la, os restos ocos da árvore lançaram raízes profundas na terra.$b$bQuero que você vá para o norte, aos três locais onde o tronco se rompeu, e desça o mais fundo que puder. Use este orbe quando chegar lá, para criar uma impressão da energia da área à sua volta. Assim teremos indícios do que aconteceu a Vordrassil, e porque fracassou em se tornar uma árvore do mundo.', '', 'Orbe usado sob o Coração de Vordrassil.', 'Orbe usado sob a Rama de Vordrassil.', 'Orbe usado sob as Lágrimas de Vordrassil.', '', '', '', '', '', 'Fale novamente com a Vidente Chifre Cinzento no Forte da Conquista, que fica na Serra Gris.', 0),
(12214, 'ptBR', 'Novas montarias', 'Alcebíades da Gama, em Perfídia, quer que você roube 3 Corcéis da Ofensiva Escarlate e os entregue, passando as rédeas para ele.', 'Olá. Me chamo Alcebíades. Prazer em $gconhecê-lo:conhecê-la;, $gsenhor:senhora;.$B$BO alto-executor me disse: "Alcebíades, consiga novas montarias para nós."$B$BEle acha que nós encontramos cavalos onde? Brotando do chão?$B$B<sussurrando>Bom, é assim mesmo, se você estiver num cemitério de cavalos.$B$BMas aqui não tem nenhum. Então, quero que você vá para o sul, para Nova Amparo, mate os cavaleiros, pegue o chicote deles e roube os corcéis.$B$BTraga os cavalos para mim e me passe as rédeas deles, por favor.', '', 'Rédeas dos Corcéis da Ofensiva Escarlate entregues', '', '', '', '', '', '', '', 'Fale novamente com Alcebíades da Gama, em Perfídia, que fica no Ermo das Serpes.', 0),
(12215, 'ptBR', 'Situação worg-rível', 'Anderhol, no Chalé do Pinho Âmbar, quer que você encontre e mate 6 Caçadores Brumagris na Serra Gris.', 'Como se já não tivéssemos problemas suficientes...$b$bEssa crise de suprimentos nos faz competir com os worgs nativos pela caça. A situação piorou ultimamente e, se não dermos um jeito nisso agora, não vai sobrar nada para caçar.$b$bVasculhe a floresta, $r. Mate todos os brumagris que encontrar. Relatórios recentes indicam que há uma grande concentração deles do outro lado do rio, a oeste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mateiro Anderhol no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12216, 'ptBR', 'Lambada no lombo!', 'Anderhol, no Chalé do Pinho Âmbar, quer que você lhe traga 8 Lombos de Urso Pardo dos Ursos Pardos da Serra Gris.', 'Todos nós trabalhamos duro e estamos começando a ver os resultados, mas ainda estamos longe de resolver o problema. Precisamos de muito mais carne do que temos no momento e a população de cervos não será suficiente.$b$bInfelizmente você terá que caçar uma presa muito mais perigosa: os ursos pardos que comandam esta região. Há muitos deles por aqui e estão todos bem cevados com os peixes abundantes que nadam pelos rios.$b$bMas tome cuidado, $c.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mateiro Anderhol no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12217, 'ptBR', 'Olhos de águia', 'Anderhol, no Chalé do Pinho Âmbar, quer que você mate 5 Águias Imperiais e, em seguida, fale com ele novamente.', 'Bem, $n, finalmente descobrimos como a Horda conseguiu localizar nossos suprimentos escondidos.$b$bEles estavam atando a própria visão às águias inocentes que planam sobre as árvores daqui. A visão de águia permitiu que eles espionassem com facilidade todas as nossas atividades.$b$bPor ordem do tenente, temos que exterminar as majestosas aves de modo a atrapalhar nossos inimigos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mateiro Anderhol no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12218, 'ptBR', 'Espalhe as boas novas', 'O Pestífero-chefe Militão, em Perfídia, no Ermo das Serpes, quer que você use a Bomba Empesteada do Vetor da Praga Renegado para destruir 30 Mortos Vorazes nos arredores dos Campos de Carniça.', 'Antes que eu possa $Gmandá-lo:mandá-la; dar as boas notícias ao Dr. Síntar C. Málius, você terá que executar um simples teste de campo da praga com as modificações que eu implementei.$B$BOs mortos famintos continuam saindo das ruínas da Velha Invergarde. Pilote um veículo saindo do portão leste e leve-o na direção nordeste através do Desfiladeiro da Vingança, até chegar às torres gêmeas na fronteira sudeste de Invergarde. Jogue a bomba de praga nos mortos-vivos da área. Apresente-se a mim com os resultados!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Pestífero-chefe Militão em Perfídia, no Ermo das Serpes.', 0),
(12219, 'ptBR', 'A Árvore do Mundo fracassada', 'A Hierofante Theyreen, no Chalé do Pinho Âmbar, quer que você vá até a Rama de Vordrassil, Coração de Vordrassil ou Lágrimas de Vordrassil e obtenha 6 Amostras de Visgo das Gosmas Entrópicas.', 'Meus ancestrais um dia plantaram uma árvore no meio da Serra Gris.$b$bChamava-se Vordrassil e deveria ter se tornado uma árvore do mundo.$b$bPor motivos há muito esquecidos, depois que a árvore cresceu completamente, eles decidiram que ela tinha de ser destruída. O tronco gigantesco foi partido em três locais da área ao norte.$b$bOnde a árvore tocou o chão, uma gosma vil começou a cobrir a terra. Traga-me amostras de gosma para que eu possa iniciar meu trabalho e curar a terra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Hierofante Theyreen no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12220, 'ptBR', 'Influência perversa', 'A Hierofante Theyreen, no Chalé do Pinho Âmbar, quer que você vá à Rama de Vordrassil, ao Coração de Vordrassil e às Lágrimas de Vordrassil e use o Orbe do Geomante nas profundezas.', 'Quando tombaram a árvore Vordrassil, os restos ocos lançaram raízes profundas na terra.$b$bQuero que você vá para o norte, aos três locais onde o tronco se rompeu e desça o mais fundo que puder. Os três locais ficam a oeste da Bocaina Velha.$b$bUse este orbe quando chegar lá para criar uma impressão da energia da área à sua volta. Para que a terra seja restaurada, é necessário descobrir qual foi a causa do fracasso de Vordrassil como árvore do mundo a tantos anos atrás.', '', 'Orbe usado sob o Coração de Vordrassil', 'Orbe usado sob a Rama de Vordrassil', 'Orbe usado sob as Lágrimas de Vordrassil', '', '', '', '', '', 'Fale novamente com a Hierofante Theyreen no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12221, 'ptBR', 'Praga dos Renegados', 'Entregue a Praga dos Renegados ao Dr. Síntar C. Málius, no Martelo de Agmar.', 'Eu preparei uma encomenda que deve ser entregue ao Dr. Síntar C. Málius, no Martelo de Agmar. A encomenda contém o espécime final da praga, mais as instruções de preparo e amostras do agente reativo.$B$BO Martelo de Agmar fica na parte ocidental do Ermo das Serpes. É só ficar $Gatento:atenta; às construções orcs de metal denteado. Quando as vir, é porque você chegou ao Martelo de Agmar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Dr. Síntar C. Málius, no Martelo de Agmar, que fica no Ermo das Serpes.', 0),
(12222, 'ptBR', 'Segredos dos flamestres', 'Traga 3 Talismãs Imbuídos de Chamas para o Mateiro Draco no Chalé do Pinho Âmbar.', 'Enquanto enfrentamos a Horda, a tribo dos Esfola-dragão se reúne na aldeia de Runavold, perto da costa ao sul.$B$BOs guerreiros mais poderosos da aldeia recebem talismãs imbuídos de chamas que lhes dão a habilidade de controlar protodracos poderosos e selvagens. Se pudermos controlar um desses dracos, talvez seja possível usá-lo para neutralizar a ameaça representada por Runavold.$B$BOs flamestres Esfola-dragão criam os talismãs e os imbuem com poder. Mate-os e pegue os talismãs.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mateiro Draco no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12223, 'ptBR', 'Reduzir as hostes', 'Mate 12 Vassalos Esfola-dragão e fale novamente com o Mateiro Draco no Chalé do Pinho Âmbar.', 'Há muita agitação na aldeia Runavold ao sul. O thane Torvald Eriksson e seus vassalos se preparam para a guerra. Enquanto a maioria dos nossos soldados estiver lidando com a traição da Horda, Pinho Âmbar ficará vulnerável.$B$BVá até Runavold, que fica perto da costa meridional, e mostre aos Esfola-dragão que não somos um alvo fácil.$B$BMassacre o máximo de vassalos que puder. Faça que eles pensem duas vezes antes de se aproveitar do nosso conflito com a Horda.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mateiro Draco no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12224, 'ptBR', 'A Vanguarda Kor\'kron!', 'Fale com Saurfang, o Jovem, na Vanguarda Kor\'kron.', 'Agiu bem, $girmão:irmã;. Em tudo o que você enfrentou, você agiu como $gum campeão:uma campeã; da Horda. Os Anub\'ar Flagelados de Azjol-Nerub, esmagados sob seu calcanhar! Os taunkas, agora valentes e poderosos membros da Horda, por sua causa! Nossa super-arma contra o Flagelo, testada e aperfeiçoada por você!$B$BA hora chegou, o momento é agora. Nossos soldados de elite no Portão da Ira esperam por você. O filho de Saurfang espera sua chegada na Vanguarda Kor\'kron. Vá agora, siga a direção nordeste até o Portão da Ira.', '', '', '', '', '', '', '', '', '', '', 0),
(12225, 'ptBR', 'Hmmmmm... Semente Âmbar!', 'Fale com o Mestre Mateiro Anderhol no Chalé do Pinho Âmbar.', 'Seu estômago ronca quando o perfume poderoso de castanhas saborosas chamam-lhe a atenção ao balde de sementes.$b$bAlguma alma generosa obviamente deixou os petiscos gratuitos aqui para receber visitantes cansados. $GAgradecido:Agradecida;, você pega as últimas sementes e as devora.$b$bElas não $go:a; desapontam em nada. Percebendo que deseja muitas mais, você decide descobrir-lhes a origem.', '', '', '', '', '', '', '', '', '', '', 0),
(12226, 'ptBR', 'Evacuação de emergência', 'Anderhol, no Chalé do Pinho Âmbar, quer que você lhe traga 5 Talos de Raiz Negra.', 'Precisamos agir rápido, $r! Não podemos correr o risco de deixar que as preciosas sementes sejam completamente digeridas. Elas precisam ser postas para fora AGORA.$b$bVá cavar algumas raízes negras nas margens do rio logo a oeste daqui e eu lhe farei um purgante que botará suas tripas para funcionar.$b$bVá logo! E lembre-se, é tudo culpa sua.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mateiro Anderhol no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12227, 'ptBR', 'O cumprimento do feder', 'Anderhol, no Chalé do Pinho Âmbar, quer que você tome a Sidra Redonda de Anderhol e use a casinha para recuperar as Sementes Âmbar Parcialmente Processadas.', 'Muito bem, $r. Aqui está o laxante.$b$bO efeito é imediato, então não use antes estar sentad$go:a; em segurança, dentro da casinha.$b$bAgora, vá lá descarregar as sementes!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mateiro Anderhol no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12229, 'ptBR', 'Uma possível conexão', 'A Vidente Chifre Cinzento, no Forte da Conquista, quer que você obtenha 8 amostras de Sangue de Pelurso Louco dos Pelursos da Ermida Verossangue e da Ermida Presa Raivosa.', 'Recentemente, mandamos uma expedição ao leste, onde foram atacados por pelursos enlouquecidos. Um dos sobreviventes contou que, após matar um dos pelursos, o cadáver começou a expelir uma substância gosmenta escura.$B$BDurante milhares de anos, os pelursos da Serra Gris foram pacíficos. Talvez exista uma conexão entre o comportamento dos pelursos e a energia das trevas que detectamos antes.$B$BTraga-me amostras do sangue dos pelursos. Você os encontrará a leste, na Ermida Presa Raivosa e na Ermida Verossangue.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Vidente Chifre Cinzento no Forte da Conquista, que fica na Serra Gris.', 0),
(12230, 'ptBR', 'Roubando dos mestres de cerco', 'O Necroguarda Molder, em Perfídia, quer que você recupere 6 Bombas de Mestre de Cerco.', 'Estou encarregado de destruir as balistas da Ofensiva Escarlate. Infelizmente, estou tendo problemas de disputa de recursos com os boticários, e fiquei sem nada com que destruí-las!$B$BA nordeste daqui ficam os Campos de Carniça. Os mestres de cerco do Flagelo, com suas forjas e carroças carniceiras, são especialistas em demolição.$B$BPra nossa sorte, eles têm por hábito deixar bombas jogadas por toda parte.$B$BQuero que você vá buscar algumas pra mim. Pegue-as do chão ou dos mestres, o que preferir.', '', '', '', '', '', '', '', '', '', 'Fale com o Necroguarda Molder, em Perfídia, que fica no Ermo das Serpes.', 0),
(12231, 'ptBR', 'As crias do deus-urso', 'A Vidente Chifre Cinzento, no Forte da Conquista, quer que você converse com Orsonn na Ermida Presa Raivosa e Kodian na Ermida Verossangue.', 'É possível que os pelursos de Serra Gris sejam portadores da mesma mácula que assolou Vordrassil. Agora estão envolvidos numa guerra tribal violenta após anos de coexistência pacífica.$B$BAs ermidas que eles protegem, a leste, são o lar dos filhos de Ursoc.$B$BSe a corrupção afetou os pelursos, é possível que Kodian e Orsonn tenham permanecido ilesos.$B$BCaso isso tenha acontecido, encontre-os e escute o que eles têm a dizer.', '', 'História de Orsonn', 'História de Kodian', '', '', '', '', '', '', 'Fale novamente com a Vidente Chifre Cinzento no Forte da Conquista, que fica na Serra Gris.', 0),
(12232, 'ptBR', 'Bombardeie as balistas', 'O Necroguarda Molder, em Perfídia, quer que você use as Bombas de Mestre de Cerco para bombardear 5 Balistas de Nova Amparo.', 'Finalmente, chegou nossa hora de atacar as máquinas de cerco deles! Não vá errar!$B$BEstou brincando.$B$BUm pouquinho.$B$B$C, bombardeie as balistas de Nova Amparo com essas bombas.$B$BVamos mostrar à Real Sociedade de Boticários como é que se resolve um problema em grande estilo. E nem precisa de poções!', '', 'Balista de Nova Amparo bombardeada', '', '', '', '', '', '', '', 'Fale com o Necroguarda Molder, em Perfídia, que fica no Ermo das Serpes.', 0),
(12234, 'ptBR', 'Em busca de respostas', 'A Espiã-chefe Repine, em Perfídia, quer que você roube as Ordens do Dia da Ofensiva Escarlate: Abadia, Ordens do Dia da Ofensiva Escarlate: Quartel e Ordens do Dia da Ofensiva Escarlate: Praia.', 'Eu preciso saber o que eles estão inventando lá em Nova Amparo.$B$BEu quero que você vá lá e roube as ordens do dia para mim.$B$BVá para o sul e procure os planos no quartel, na praia e na abadia.$B$BPra você não se confundir: o quartel é a construção grande, logo ao lado da ferraria.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Espiã-chefe Repine, em Perfídia, que fica no Ermo das Serpes.', 0),
(12235, 'ptBR', 'Naxxramas e a queda de Invergarde', 'Apresente-se ao Comandante de Grifos Eurico, na estação de grifos da Bastilha Invergarde.', 'O Lorde Fordragon liderou um ataque esmagador contra Arthas, no Portão da Ira. Em retaliação, Arthas enviou Naxxramas pra cima de nós. Kel\'Thuzad está escondido na cidadela flutuante, e seu comandante de solo, Thel\'zan, mantém o cerco à Bastilha Invergarde. O vilarejo mais abaixo daqui já está perdido, e as chances de conseguirmos resgatar sobreviventes de lá diminuem a cada minuto.$B$BPrecisamos agir logo! Apresente-se imediatamente ao comandante de Grifos Eurico, na estação de grifos! Ele $Go:a; encaminhará com rapidez.$B$BPode ir!', '', '', '', '', '', '', '', '', '', '', 0),
(12236, 'ptBR', 'Ursoc, o deus-urso', 'A Vidente Chifre Cinzento, no Forte da Conquista, quer que você encontre Tur Patafúria, próximo ao Covil de Ursoc, e derrote Ursoc com a ajuda dele. Então use as Cinzas Purificadas de Vordrassil no Cadáver de Ursoc.', 'Chegou a hora, $n. Agora vamos descobrir se nossos esforços terão sucesso, ou se fracassarão.$B$BLeve as cinzas e procure o pelurso que Kodian mencionou, Tur Patafúria, perto do Covil de Ursoc. O covil fica a norte da Bocaina Velha.$B$BConvença Tur para que $go:a; ajude, pois você precisará do máximo de apoio possível.$B$BApós derrotar o deus-urso, espalhe as cinzas sobre o corpo.$B$BMesmo que a forma mundana dele seja destruída, o espírito precisa ser salvo.', '', 'Ursoc purificado', '', '', '', '', '', '', '', 'Fale novamente com a Vidente Chifre Cinzento no Forte da Conquista, que fica na Serra Gris.', 0),
(12237, 'ptBR', 'O voo do defensor de Invergarde', 'Resgate 5 Aldeões de Invergarde Indefesos e fale novamente com o Comandante de Grifos Eurico, na Bastilha Invergarde.', 'Com este apito é possível chamar um grifo de Invergarde. Monte na criatura e vá para as ruínas da Vila de Invergarde, que agora se chamam Campos de Carniça, a sudeste daqui. Quando chegar ao vilarejo, fique $Gatento:atenta; aos aldeões de Invergarde que precisam de ajuda. Quando você encontrar um aldeão, voe baixo e use o grifo para apanhá-lo. Traga o aldeão pra cá, pra estação de grifos.$B$BO Flagelo está por toda parte, então é bom ficar $gesperto, herói:esperta, heroína;. Boa sorte!', '', 'Aldeão Indefeso resgatado', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Grifos Eurico, na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12238, 'ptBR', 'A limpeza de Drak\'Tharon', 'Drakuru quer que você use o Elixir de Drakuru no braseiro dentro de Drak\'Tharon. Para usar o Elixir do Drakuru, você precisará de 5 Mojos Implacáveis.', 'Drak\'Tharon rapidinho vai estar liberada daqueles mortos-vivos nojentos e vai voltar a ter um destino maneiro. Para agradecer a tua ajuda, os tesouros mais irados da bastilha vão ser teus, cara!$b$bQuando tu chegar lá no alto, tu tem que me evocar pra eu mandar ver no ritual.$b$bInfelizmente, cara, tu vai ter que pagar um preço para me evocar. Vai ter que catar o mojo dos que viverem.', '', '', '', '', '', '', '', '', '', '', 0),
(12239, 'ptBR', 'A espiã em Nova Amparo', 'Entregue as Ordens do Dia da Ofensiva Escarlate para a Agente Skully, em Nova Amparo.', 'Eu tenho uma espiã nas fileiras da Ofensiva Escarlate. Preciso que você entregue as ordens do dia para ela poder planejar a próxima fase do nosso ataque.$B$BO nome dela é Agente Skully. Ela está usando um disfarce mágico: você a verá como zeladora do cemitério da Ofensiva.$B$BEntregue as ordens e faça o que ela disser. O cemitério fica do lado da abadia.', '', '', '', '', '', '', '', '', '', 'Fale com a Agente Skully nos Ermos Dragônicos, no Ermo das Serpes.', 0),
(12240, 'ptBR', 'Meios para um fim', 'A Boticária Rivadávia Levine, em Perfídia, quer que você use os Cupins da Família Levine para atrair o Encarregado Kaleiki e matá-lo.', 'No último carregamento que chegou aqui, eu recebi alguns barris de cupins que minha irmã me mandou lá do Baluarte. Acho que vão ser úteis para uma coisa que quero que você faça.$B$BAs operações madeireiras em Nova Amparo são problemáticas para nós, mas até agora não conseguimos colocar ninguém lá pra dar um jeito no encarregado dos trabalhos.$B$BSe você soltasse esses cupins na madeireira, acho que o encarregado sairia correndo pra ver. Seria sua chance.$B$B$gPronto:Pronta; pra dar um sumiço nele, $c?', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Boticária Rivadávia Levine, em Perfídia, que fica no Ermo das Serpes.', 0),
(12241, 'ptBR', 'Destrua a muda', 'A Vidente Chifre Cinzento, no Forte da Conquista, quer que você use a Tocha Verdejante para queimar a Muda de Vordrassil. Traga as Cinzas de Vordrassil para Vidente Chifre Cinzento.', 'O trabalho dos pelursos deve ser desfeito, $n. Nem as melhores intenções contam quando o resultado é tão conspurcado.$B$BA muda precisa ser destruída, pois é a fonte da influência maligna. Tome esta tocha e use-a para incendiar a muda corrompida. Depois traga-me as cinzas.$B$BApós a purificação pelas chamas, usarei todo o meu poder para remover a mácula. As cinzas serão necessárias para purgar Ursoc do poder maligno que o controla.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Vidente Chifre Cinzento no Forte da Conquista, que fica na Serra Gris.', 0),
(12242, 'ptBR', 'As sementes de Vordrassil', 'A Vidente Chifre Cinzento, no Forte da Conquista, quer que você vá até a Bocaina Velha e obtenha 8 das Sementes de Vordrassil.', 'Temos que nos assegurar de que Vordrassil jamais seja replantada. Os pelursos devem ter colhido as sementes.$B$BVá até Bocaina Velha, no centro da Serra Gris, e recolha todas as sementes que encontrar. Darei um fim adequado a elas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Vidente Chifre Cinzento no Forte da Conquista, que fica na Serra Gris.', 0),
(12243, 'ptBR', 'Fogo sobre as águas', 'A Boticária Rivadávia Levine, em Perfídia, quer que você use a Água Escaldante da Boticária para incendiar as velas do Extravagância do Pecador.$B$BEnquanto os taifeiros estiverem ocupados tentando apagar o fogo, vá para o alojamento do capitão e pegue as Cartas Náuticas do Capitão Selmo.', 'Tenho outra missão pra você.$B$BEu consegui implementar algumas mutações na praga para produzir minha mundialmente famosa água escaldante. Eu quero que você a use para atear fogo nas velas do Extravagância do Pecador!$B$BUse-a do píer. Quando as velas pegarem fogo, os taifeiros vão ficar ocupados. Você vai poder descer até o camarote do capitão e "pegar emprestada" a carta de navegação.$B$BO navio está no Ancoradouro dos Cruzados, abaixo e ao sul de Nova Amparo. O alojamento do capitão fica no primeiro convés inferior, atrás das escadas.', '', 'Velas do Extravagância do Pecador em chamas', '', '', '', '', '', '', '', 'Fale novamente com a Boticária Rivadávia Levine, em Perfídia, que fica no Ermo das Serpes.', 0),
(12244, 'ptBR', 'Conserte o retalhador', 'Synipus, na Madeireira Céu Azul, quer que você lhe traga 3 Retalhadores Quebrados.', 'Escuta, cara. Por que você não enrola as mangas e cata uma chave de boca? Temos trabalho a fazer! Precisamos reformar e mandar esses retalhadores para a Baía dos Empreendimentos, e é para ontem... $b$bO quê? Você não tem uma chave de boca? Então pra que você presta? É melhor você descer com os outros cabeções e ir brincar com a Horda!$b$bEnquanto estiver por lá, veja se consegue pilotar alguns dos retalhadores quebrados até aqui, para que a gente possa consertar. Mas toma cuidado! Eles estão bem arrebentados.', '', 'Retalhador entregue', '', '', '', '', '', '', '', 'Fale novamente com Synipus na Madeireira Céu Azul, que fica na Serra Gris.', 0),
(12245, 'ptBR', 'Sem piedade para com os prisioneiros', 'A Espiã-chefe Repine quer que você mate a Necroguarda Xavier, o Escrivão-mestre Barriga, o Engenheiro Braga e o Chanceler Amai.$B$BDepois que cumprir a tarefa, informe o Alto-executor Iracundo, em Perfídia.', 'Temos mais idiotas pra você matar.$B$BMeus agentes me informam que vários dos nossos bons concidadãos acharam por bem cair nas garras da Ofensiva Escarlate.$B$BNão tem cabimento.$B$BVolte para Nova Amparo e elimine a necroguarda Xavier, o escrivão-mestre Barriga, o engenheiro Braga e o chanceler Amai.$B$BEles estão espalhados pelo local. Sem dúvida estão enjaulados, aguardando tortura.$B$BFale com eles e, depois, mate-os!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Alto-executor Iracundo em Perfídia, que fica no Ermo das Serpes.', 0),
(12246, 'ptBR', 'Uma possível conexão', 'A Hierofante Theyreen, no Chalé do Pinho Âmbar, quer que você obtenha 8 amostras de Sangue de Pelurso Louco dos Pelursos da Ermida Verossangue e da Ermida Presa Raivosa.', 'Os pelursos que vivem a leste daqui são mais agressivos e selvagens do que aqueles a que estamos acostumados. Nossas forças os enfrentaram mais de uma vez, e os sobreviventes sempre mencionam uma substância sombria e gosmenta pingando dos cadáveres dos pelursos.$B$BO comportamento incomum deles pode estar conectado aos contaminantes que descobrimos nos restos de Vordrassil$B$BTraga-me amostras do sangue dos pelursos. Você os encontrará na Ermida Presa Raivosa e na Ermida Verossangue bem longe ao leste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Hierofante Theyreen no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12247, 'ptBR', 'Filhos de Ursoc', 'A Hierofante Theyreen, no Chalé do Pinho Âmbar, quer que você converse com Orsonn na Ermida Presa Raivosa e Kodian na Ermida Verossangue.', 'Os pelursos da Serra Gris são portadores de algum tipo de corrupção, com certeza. A guerra tribal irrompeu após anos de coexistência pacífica.$B$BResta descobrir se os ursos que eles reverenciam como deuses também foram conspurcados.$B$BOs dois filhos de Ursoc, Orsonn e Kodian, vivem na Ermida Verossangue e na Ermida Presa Raivosa, ao sul e ao sudeste da Bocaina Velha.$B$BVeja se eles conversam com você sobre o que aconteceu aqui.', '', 'História de Orsonn', 'História de Kodian', '', '', '', '', '', '', 'Fale novamente com a Hierofante Theyreen no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12248, 'ptBR', 'A muda de Vordrassil', 'A Hierofante Theyreen, no Chalé do Pinho Âmbar, quer que você use a Tocha Verdejante para queimar a Muda de Vordrassil. Traga as Cinzas de Vordrassil para Hierofante Theyreen.', 'Os druidas ancestrais aparentemente tiveram bons motivos para destruir Vordrassil. Não podemos permitir que os pelursos tentem replantá-la.$B$BPor outro lado, a salvação do espírito de Ursoc depende da magia contida na muda. Ela está no meio da Bocaina Velha, dentro do antigo tronco de Vordrassil.$B$BTraga-me as cinzas de Vordrassil. Espero que, uma vez purificadas pelo fogo, a magia que elas possuem possa ser usada para purgar o espírito de Ursoc da mácula negra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Hierofante Theyreen no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12249, 'ptBR', 'Ursoc, o deus-urso', 'A Hierofante Theyreen, no Chalé do Pinho Âmbar, quer que você encontre Tur Patafúria, próximo ao Covil de Ursoc, e derrote Ursoc com a ajuda dele. Então use as Cinzas Purificadas de Vordrassil no Cadáver de Ursoc.', 'Chegou a hora. Leve estas cinzas e procure o pelurso mencionado por Kodian. Se ele partiu em busca de Ursoc, estará perto do covil, ao norte da Bocaina Velha.$B$BVocê precisará da ajuda desse pelurso. Você não conseguirá derrotar Ursoc $gsozinho:sozinha;.$B$BDepois de vencer Ursoc, use as cinzas para purificar-lhe o espírito. Só então saberemos se nossos esforços foram em vão.', '', 'Ursoc purificado', '', '', '', '', '', '', '', 'Fale novamente com a Hierofante Theyreen no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12250, 'ptBR', 'As sementes de Vordrassil', 'A Hierofante Theyreen, no Chalé do Pinho Âmbar, quer que você vá até a Bocaina Velha e obtenha 8 das Sementes de Vordrassil.', 'Não podemos permitir que Vordrassil cresça novamente. Se os pelursos a replantaram uma vez, podem fazê-lo de novo.$B$BVá até a Bocaina Velha, no centro da Serra Gris, e obtenha as sementes de Vordrassil. Darei um fim adequado a elas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Hierofante Theyreen no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12251, 'ptBR', 'Apresentação ao Alto-comandante', 'Fale com o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, que fica no Ermo das Serpes.', 'Fale novamente com o Alto-comandante Haraldo Serpecida imediatamente, $n. Diga a ele que sua missão foi bem-sucedida e que os aldeões que restaram foram resgatados e já estão trabalhando.', '', '', '', '', '', '', '', '', '', '', 0),
(12252, 'ptBR', 'Torture o torturador', 'O Alto-executor Iracundo, em Perfídia, quer que você use o ferro de marcar 5 vezes no Torturador Bel\'Arte, para extrair as informações dele. Depois, mate-o.', 'Basta! Meu povo não será mais torturado, e você vai cuidar disso!$B$BO torturador da Ofensiva, Bel\'Arte, tem extraído informações (junto com sangue, unhas e dentes) de quem quer que lhe caia nas mãos! Eu preciso saber o que eles sabem.$B$BMinhas fontes me dizem que ele está instalado no porão do quartel, que fica ao lado da ferraria.$B$BEu vou emprestar a você meu ferro de marcar, pra ter certeza de que vai ser um trabalho bem feito.$B$BEncontre-o, e consiga as informações.', '', 'Torturador Bel\'Arte minuciosamente interrogado', '', '', '', '', '', '', '', 'Fale novamente com o Alto-executor Iracundo em Perfídia, que fica no Ermo das Serpes.', 0),
(12253, 'ptBR', 'Resgate na praça', 'O Alto-comandante Haraldo Serpecida na Bastilha Invergarde, no Ermo das Serpes, quer quer você resgate 6 Aldeões de Invergarde Presos.', 'Descendo por esse caminho, fica a praça de Invergarde. O lugar, que já foi um centro de atividades para os cidadãos de Invergarde, é agora uma praça de guerra repleta de geists assassinos querendo se vingar dos vivos.$B$BExistem alguns aldeões presos nas construções ao redor da praça. Eles precisam ser libertados! Eu sei que exijo muito, $n, mas você é $go único:a única; soldado livre que tenho. Liberte nosso povo. Siga por esse caminho até a praça da cidade e entre nas casas. Mate tudo que se meter no seu caminho! Apresente-se a mim depois, se sobreviver.', '', 'Aldeão de Invergarde libertado', '', '', '', '', '', '', '', 'Fale novamente com o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12254, 'ptBR', 'Oração do Moribundo', 'A Agente Skully, em Nova Amparo, quer que você obtenha o Livro de Orações do Bispo Alameda.', 'Esses planos indicam que algo está sendo tramado para breve.$B$BMas antes de continuar investigando, precisamos cuidar dessa estranha proteção que beneficia as forças da Ofensiva. Se Perfídia quiser triunfar sobre a Ofensiva de uma vez por todas, temos que encontrar e eliminar quem está por trás dessa proteção.$B$BEu notei que o bispo da capela que fica em Nova Amparo, do lado mais afastado, vem aumentando as bênçãos das tropas. Mate-o e roube o livro de orações dele.$B$BTalvez encontremos uma pista.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Agente Skully, em Nova Amparo, que fica no Ermo das Serpes.', 0),
(12255, 'ptBR', 'O thane dos Runavold', 'Use Flamarauto para derrotar o Thane Torvald Eriksson e se apresente ao Mateiro Draco no Chalé do Pinho Âmbar.', 'Agora que você capturou os talismãs imbuídos de chamas e enfraqueceu as defesas de Runavold, podemos atacar o líder, thane Torvald Erkisson.$B$BA montaria favorita dele é um protodraco chamado Flamarauto. Ele é mantido acorrentado na parte ocidental de Runavold, mas, com os talismãs, você poderá controlá-lo por tempo suficiente para usá-lo contra o thane.$B$BQuando estiver com Flamarauto dominado, vasculhe o topo das torres de Runavold em busca do thane, e acabe com ele.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mateiro Draco no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12256, 'ptBR', 'O segredo dos flamestres', 'Traga 3 Talismãs Impregnados de Chamas para o Sargento Nazgrim no Forte da Conquista.', 'Mesmo enquanto os covardes da Aliança assaltam nossas defesas, Runavold, o posto avançado dos Vraikalen Esfola-dragão, a sudeste, se prepara para a guerra. Os vraikalen estão longe de ser nossos inimigos mais fortes, mas precisamos eliminá-los antes que possam nos ameaçar de verdade.$B$BOs guerreiros vraikalen mais poderosos têm permissão de cavalgar protodracos semitreinados durante as batalhas. Para controlar as feras, os flamestres criam talismãs poderosos. Quero que você os mate e tome os talismãs para que nosso plano possa funcionar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Nazgrim no Forte da Conquista, que fica na Serra Gris.', 0),
(12257, 'ptBR', 'Demonstração de força', 'Mate 12 Vassalos Esfola-dragão e fale novamente com o Sargento Nazgrim no Forte da Conquista, que fica na Serra Gris.', 'A aldeia vraikal de Runavold se prepara para a guerra. O thane de Runavold não tem como enviar um grande exército, mas, com nossas próprias forças tão espalhadas, estamos muito vulneráveis.$B$BNão podemos oferecer a oportunidade de ataque ao thane e seus homens, portanto temos que levar a batalha até eles. Se você é realmente $gum:uma; $c da Horda, se regozijará com a chance de demonstrar nossa força.$B$BMassacre os vassalos e prove ao clã dos Esfola-dragão que a Horda não está de brincadeira!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Nazgrim no Forte da Conquista, que fica na Serra Gris.', 0),
(12258, 'ptBR', 'Praça de guerra', 'A Comandante Lynore Golpevento, na Bastilha Invergarde, no Ermo das Serpes, quer que você mate 15 Geists Vingativos.', 'A praça da cidade, descendo por esse caminho, foi tomada pelos cidadãos mortos-vivos de Invergarde! Nossa própria cripta fornece um número sem-fim de soldados para o Flagelo. Não tenha piedade deles, $n. Quando eram mortais, eles tinham compaixão e intelecto. Agora não passam de mortos-vivos descontrolados que só têm um objetivo: nossa destruição.$B$BSiga para a praça da cidade e faça com que os geists vingativos encontrem o criador. Leve a paz da Aliança a eles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Comandante Lynore Golpevento, na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12259, 'ptBR', 'O thane dos Runavold', 'Use Flamarauto para derrotar o Thane Torvald Eriksson e se apresente ao Sargento Nazgrim no Forte da Conquista.', 'Com os talismãs impregnados de chamas, finalmente poderemos desafiar o thane.$B$BA montaria favorita dele é um protodraco feroz chamado Flamarauto. O bicho fica acorrentado na parte ocidental de Runavold, mas, com os talismãs, você poderá controlá-lo por tempo suficiente para atacar o thane.$B$BQuando Flamarauto estiver dominado, vasculhe o topo das torres de Runavold em busca do thane e acabe com ele.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Nazgrim no Forte da Conquista, que fica na Serra Gris.', 0),
(12260, 'ptBR', 'Dessemelhança perfeita', 'A Agente Skully, em Nova Amparo, quer que você roube a imagem de um Sacerdote Corvo da Ofensiva. Devolva o Espelho Mágico da Banshee à Agente quando terminar.', 'Você deve estar se perguntando como eu consigo manter esse disfarce: eu uso um espelho mágico que me foi dado pela espiã-chefe.$B$BEle não tem tanto poder assim, mas acho que é o suficiente para nós $Gdois:duas;. Pode pegar. Use-o para se fazer passar por um dos sacerdotes corvos da Ofensiva.$B$BSeja $grápido:rápida;... Não tenho ideia de quanto tempo meu disfarce vai durar enquanto o espelho estiver com você.$B$BSaiba que o disfarce não ficará perfeito de imediato. Então, tenha cuidado até que eu tenha uma chance de ajudar você.', '', 'Imagem do Sacerdote Corvo da Ofensiva roubada', '', '', '', '', '', '', '', 'Fale novamente com a Agente Skully, em Nova Amparo, que fica no Ermo das Serpes.', 0),
(12261, 'ptBR', 'Sem lugar pra correr', 'Posicione um Marco Destrutivo no final do caminho saindo do Santuário Dragônico Obsidiano, no ponto em que a estrada começa a desaparecer sob a neve. Proteja o marco até que ele esteja totalmente energizado, então fale novamente com Serinar.', 'Eles extraem poder dos ossos de meus irmãos mortos...$B$BMesmo em se tratando dessa seita, estou perplexo com tamanha audácia! Não haverá piedade para eles... não que, porventura, houvesse.$B$BQuero que você garanta que eles não terão pra onde correr quando o massacre começar. Vá e posicione um selo destrutivo no final do caminho saindo do santuário... no ponto em que a estrada começa a desaparecer sob a neve. Proteja o marco até que ele esteja totalmente energizado.', '', 'Marco Destrutivo completamente energizado', '', '', '', '', '', '', '', 'Fale novamente com Serinar, na Bocarra de Neltharion, que fica no Ermo das Serpes.', 0),
(12262, 'ptBR', 'Sem misericórdia', 'Mate 6 Necrólitos das Profundezas Flamejantes e 10 Esqueletos Fumegantes na parte externa do Santuário Dragônico Obsidiano. Fale novamente com Serinar quando completar a tarefa.', 'Não pouparemos ninguém.$B$BLá fora, reles necrólitos e seus servos descarnados conspurcam minha terra com sua presença. Massacre todos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Serinar na Bocarra de Neltharion, que fica no Ermo das Serpes.', 0),
(12263, 'ptBR', 'As melhores intenções', 'Espere até que Serinar aplique em você o disfarce de Necrólito das Profundezas Flamejantes. Então, siga até os fundos da Bocarra de Neltharion, e descubra o que a Seita dos Malditos está fazendo lá. Fale novamente com Serinar e lhe repasse os detalhes do que descobrir.', 'A Seita dos Malditos não veio até aqui só para extrair poder dos dragões mortos. Creio já saber o que eles pretendem, mas preciso que você confirme minha teoria.$B$BEu farei com que você se assemelhe a um necrólito. Vá até os fundos da caverna e confirme as intenções que os trouxeram a este lugar sagrado. Eu observarei pelos seus olhos.$B$BCuidado, $n. Se sofrer algum dano, a ilusão poderá ser desfeita.', 'Descubra a Câmara de Ressurreição da Magma-serpe', '', '', '', '', 'Descubra a Câmara de Ressurreição da Magma-serpe', '', '', '', 'Fale novamente com Serinar, na Bocarra de Neltharion, que fica no Ermo das Serpes.', 0),
(12264, 'ptBR', 'Abater os Malditos', 'Mate 3 Necromantes das Profundezas Flamejantes, 6 Constructos Ardentes e 6 Geists Ardentes na Bocarra de Neltharion, e então fale novamente com Serinar.', 'A caverna mais além enxameava com as atrocidades da Seita. Só há uma maneira de lidar com tais criaturas. Sabe o que fazer.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Serinar, na Bocarra de Neltharion, que fica no Ermo das Serpes.', 0),
(12265, 'ptBR', 'Profanar profanadores', 'Encontre e destrua 8 Runas Necromânticas desenhadas no chão dentro da Bocarra de Neltharion. Fale novamente com Serinar quando completar a tarefa.', 'Eu senti um grande acúmulo de magia nas runas que vimos enquanto você explorava a caverna. Não permitirei que tente extrair a magia dali... Frequentemente a solução mais direta é a mais eficiente.$B$BApenas destrua as runas e oblitere-as para garantirmos que a Seita não terá acesso a qualquer que seja o poder acumulado ali.', '', 'Runa Necromântica destruída', '', '', '', '', '', '', '', 'Fale novamente com Serinar, na Bocarra de Neltharion, que fica no Ermo das Serpes.', 0),
(12266, 'ptBR', 'Histórias de destruição', 'Volte para o Templo do Repouso das Serpes e informe Nalice que as tarefas de Serinar foram cumpridas.', 'Pode partir agora, $r.$B$BVá e diga a Nalice que ela perdeu um bom massacre.', '', '', '', '', '', '', '', '', '', '', 0),
(12267, 'ptBR', 'A chama de Neltharion', 'Use a Chama de Neltharion para purificar a área de ressurreição nos fundos da Bocarra de Neltharion. Quando você atrair a atenção de Podran, mate-o. Então, fale novamente com Serinar, na frente da caverna.', 'Com as fileiras da Seita diminuídas e com o poder deles exaurido, é hora de atacar a fonte da corrupção.$B$BPodran, o Decomposto, está ressuscitando dragões negros como magma-serpes nas profundezas da caverna. Siga até a câmara de ressurreição e purifique os ossos do único jeito que garantirá que eles não serão usados novamente: com fogo.$B$BQueimar os ossos atrairá a atenção de Podran. Você precisa destruí-lo também.$B$BA magia contida nesta ampola deve ser suficiente.', '', 'Área de Ressurreição purificada', '', '', '', '', '', '', '', 'Fale novamente com Serinar, na Bocarra de Neltharion, que fica no Ermo das Serpes.', 0),
(12268, 'ptBR', 'Partes apartadas', 'Pepe Kabong, na Madeireira Céu Azul, quer que você recolha 4 Engrenagens Sulcadas, 3 Rodas Ranhuradas e 2 Molas de Alta Tensão.', 'Putz! Olha essa bagunça!$b$bA engenharia goblínica deixa muito a desejar, pode acreditar. Olha só pra isso! Não sei nem como essa joça funcionou algum dia.$b$bMe dê uma ajuda aqui, pode ser? Para botar esse troço dentro das especificações operacionais, terei que trocar algumas engrenagens, rodas dentadas e molas. Você não vai ter problemas em achar isso tudo pela área da serraria.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pepe Kabong na Madeireira Céu Azul, que fica na Serra Gris.', 0),
(12269, 'ptBR', 'Na nossa mina, não!', 'O Grão-lorde Leoric von Zeldig, na Bastilha Invergarde, no Ermo das Serpes, quer que você recupere 10 Cartões dos Mineradores de Invergarde.', 'Aquela necrópole maldita nos pegou de surpresa! Com toda a destruição que ela causou, perdemos a Mina Invergarde. E pior, os acólitos de Kel\'Thuzad reanimaram os mineradores mortos e estão usando eles para fornecer materiais da nossa mina para os mestres de cerco deles!$B$BEsse suprimento precisa ser interrompido, e nossos irmãos perdidos precisam voltar a descansar.$B$BVá até a Mina Invergarde, a nordeste daqui, nos Campos de Carniça, e destrua os mineradores reanimados. Me traga os cartões deles para que eu possa dar baixa em seus nomes aqui no registro.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Grão-lorde Leoric von Zeldig na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12270, 'ptBR', 'Retalhando a Aliança', 'Grekk, na Madeireira Céu Azul, quer que você lhe traga 3 retalhadores.', 'Leia meus lábios, $c: preciso daqueles retalhadores! Além disso: preciso mantê-los longe das mãos da Aliança!$b$bEles andam reparando os retalhadores e os usando contra nossos irmãos na Baía dos Empreendimentos. Agora vamos ter que lhes dar um gostinho do próprio remédio!$b$bSe você encontrar um retalhador lá fora, pegue-o! E se você vir algum verme da Aliança num deles, mate-o e, então, pegue o retalhador. Assim que tiver um deles, pilote-o de volta até aqui e vamos trabalhar nele.$b$b$gDispensado:Dispensada;!', '', 'Retalhador entregue', '', '', '', '', '', '', '', 'Fale novamente com Grekk na Madeireira Céu Azul, que fica na Serra Gris.', 0),
(12271, 'ptBR', 'O Bastão da Compulsão', 'Entregue o Bastão do Torturador para o Alto-executor Iracundo, em Perfídia.', 'Um bastão cai da mão morta de Bel\'Arte. Você vê runas mágicas pulsando nele.$B$BSerá que ele usava este artefato para extrair as confissões?$B$BÉ melhor deixar o alto-executor dar uma olhada.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Alto-executor Iracundo em Perfídia, que fica no Ermo das Serpes.', 0),
(12272, 'ptBR', 'O minério que sangra', 'O Engenheiro de Cerco Quarteirão, na Bastilha Invergarde, no Ermo das Serpes, quer que você recupere 10 amostras de Minério Estranho da Mina Invergarde.', 'Algumas horas antes da invasão de Naxxramas, um dos mineradores encontrou um minério escuro, de onde vazava um fluido viscoso. No caos que irrompeu durante a evacuação da mina, nós perdemos as amostras que tiramos do veio alienígena. Agora, o Flagelo está explorando o minério para usá-lo em suas máquinas de destruição.$B$BRetorne à Mina Invergarde, a nordeste daqui, nos Campos de Carniça, e recupere o minério estranho. É crucial para nosso sucesso aqui!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Engenheiro de Cerco Quarteirão, na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12273, 'ptBR', 'A denúncia', 'O Alto-executor Iracundo, em Perfídia, quer que você use o Bastão da Compulsão no Comandante Jardel, no Mestre Canhoneiro Zenão, no Ferreiro Bonhomme e no Mestre de Estábulo Mércio.$B$BDepois de aplicar o bastão neles, mate-os para que suas últimas palavras sejam uma denúncia da Ofensiva.', 'É hora de nós desmoralizarmos completamente as forças da Ofensiva!$B$BQuero que você pegue o bastão e use-o em quatro líderes deles: O Comandante Jardel, no andar de cima do quartel, o Mestre Canhoneiro Zenão na rampa sudeste que dá para a praia, o Ferreiro Bonhomme na ferraria e o Mestre de Estábulo Mércio nos estábulos.$B$BUse o bastão para mantê-los sob controle, concentre-se em fazê-los denunciar os atos da Ofensiva, e então mate-os!', '', 'Denúncia & morte do Comandante Jardel', 'Denúncia & morte do Mestre Canhoneiro Zenão', 'Denúncia & morte do Ferreiro Bonhomme', 'Denúncia & morte do Mestre de Estábulo Mércio', '', '', '', '', 'Fale novamente com o Alto-executor Iracundo em Perfídia, que fica no Ermo das Serpes.', 0),
(12274, 'ptBR', 'Caindo em desgraça', 'A Agente Skully, em Nova Amparo, quer que você toque o sino da abadia e, depois, fale com Abade-mor para extrair informações dele.', 'Precisamos de mais informações sobre o Abade-mor, e agora que temos a imagem de um dos sacerdotes corvo, deve ser mais fácil chegar perto para falar com ele.$B$BMas precisamos afastá-lo dos guarda-costas, ou você não vai conseguir nada.$B$B<A agente se apoia na pá e pensa por alguns instantes.>$B$BAcho que já sei! Use o disfarce, vá ao topo da abadia e toque o sino. Isso vai atrair os guarda-costas do abade e você vai poder descer e falar com ele.', '', 'Sino da abadia tocado', 'Abade-mor interpelado', '', '', '', '', '', '', 'Fale novamente com a Agente Skully, em Nova Amparo, que fica no Ermo das Serpes.', 0),
(12275, 'ptBR', 'O explo-gnomo', 'Fale com o Engenheiro de Cerco Quarteirão, na Bastilha Invergarde, que fica no Ermo das Serpes.', 'Quarteirão recentemente requisitou um especialista para mandar numa missão de reconhecimento na Mina Invergarde. Eu mandei Slinkinho, meu especialista em demolições. Eu fui um tolo de achar que ele poderia fechar aquele fosso de danação depois de cumprir a missão para Quarteirão, nos dando outra vitória contra o Flagelo...$B$BJá se passou um dia e ele não voltou ainda. Eu quero respostas! Fale com o Engenheiro de Cerco Quarteirão e ache o meu agente sumido!', '', '', '', '', '', '', '', '', '', '', 0),
(12276, 'ptBR', 'À procura de Slinkinho', 'Encontre Slinkinho, o Explo-gnomo, na Mina Invergarde. Use o Robô Teleguiado de Quarteirão se precisar de ajuda para encontrar a mina.', 'Muito embora eu não saiba do paradeiro de Slinkinho, talvez eu possa ajudar a encontrá-lo.$B$B<Quarteirão exibe um pequeno brinquedo mecânico.>$B$BIsto não é um brinquedo, $Gmeu compatriota:minha compatriota;. Na verdade, é minha última criação mecânica. Esta máquina foi criada com a única função de encontrar o que se perdeu. Estas são circunstâncias infelizes, mas essa máquina é nossa melhor chance de encontrar Slinkinho.$B$BQuando você estiver $Gpronto:pronta; para começar a busca, posicione o robô no chão perto de mim.', '', '', '', '', '', '', '', '', '', '', 0),
(12277, 'ptBR', 'Não dê sopa pro azar', 'Pegue uma Bomba da Mina Invergarde e use-a para explodir o Túnel Superior da Mina Invergarde e o Túnel Inferior da Mina Invergarde. Fale novamente com o Engenheiro de Cerco Quarteirão, na Bastilha Invergarde, que fica no Ermo das Serpes, quando completar a tarefa.', 'Se o seu coração é bom e sua consciência está em paz, continue lendo.$B$BNessa mina, perto do andaime do capataz, existe uma grande carga de dinamite. Vá até lá, pegue bastante explosivos e siga para a entrada da mina. Quando chegar lá, acenda a dinamite e exploda a entrada. Lembre-se: exploda a entrada superior e a inferior da Mina Invergarde.$B$BNão dê sopa pro azar. O mal que habita aqui não deve ver a luz do dia. Que a Luz te guie.', '', 'Túnel Superior da Mina Invergarde destruído', 'Túnel Inferior da Mina Invergarde destruído', '', '', '', '', '', '', 'Fale novamente com o Engenheiro de Cerco Quarteirão, na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12278, 'ptBR', 'Clube da Cerveja do Mês', 'Entregue a ficha de inscrição do clube "Cerveja do Mês" para Larkin Cervaforte na Taberna Pedra de Fogo, em Altaforja.', 'A filiação traz alguns privilégios. Como parte do clube "Cerveja do Mês", você saberá onde encontrar as melhores cervejas.$b$bEntregue a ficha de inscrição do clube "Cerveja do Mês" para Larkin Cervaforte na Taberna Pedra de Fogo, em Altaforja.', '', '', '', '', '', '', '', '', '', 'Fale com Larkin Cervaforte em Dun Morogh.', 0),
(12279, 'ptBR', 'Um apetite de urso', 'Traga 6 Salmões do Norte para Hugo Copas no Entreposto Sequoia.', 'Que bom que ocê voltou, Manco! Tava preocupado achando que Griselda e eu íamos ficar sozinhos. $B$BTô cozinhando um grude aqui pra gente, mas a Griselda não gosta, não.$B$BEla prefere os peixes que vivem na Costa da Lestada, a leste daqui. Eu não suporto aqueles bichos, mas ela sempre foi muito exigente. Seis peixões devem ser suficientes para deixar ela feliz por um bom tempo.$B$BCorre, hmm, digo, manca lá, Zé. Ocê não quer deixar a garota esperando, né?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Hugo Copas no Entreposto Sequoia, que fica na Serra Gris.', 0),
(12280, 'ptBR', 'Consertando', 'Lurz, na Madeireira Céu Azul, quer que você recolha 4 Engrenagens Sulcadas, 3 Rodas Ranhuradas e 2 Molas de Alta Tensão.', 'Vinte retalhadores prontos amanhã ao meio-dia?!$b$bAfinal, quem é que estabeleceu esses prazos? Quem quer que tenha sido, nunca consertou uma lata de lixo dessas...$b$bPara cumprir minha meta, vou precisar de ajuda. Me dê uma mãozinha e eu dividirei minha comissão com você... justo?$b$bPreciso de engrenagens, rodas dentadas e molas. Essas coisas estão espalhadas em volta dos retalhadores.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lurz na Madeireira Céu Azul, que fica na Serra Gris.', 0),
(12281, 'ptBR', 'Para entender a máquina de guerra do Flagelo', 'Entregue o Pacote de Quarteirão para o Alto-comandante Haraldo Serpecida, na Bastilha Invergarde.', 'Devemos nos consolar com o fato de que a morte de Slinkinho, embora trágica, serviu para um bem maior. A descoberta que ele fez, mais o seu heroísmo na mina e as amostras que você trouxe, tudo nos aproxima um pouco mais de entender a máquina de guerra do Flagelo.$B$BEntregue este pacote para o alto-comandante Haraldo Serpecida. É uma amostra do minério estranho junto com minha análise.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12282, 'ptBR', 'Marcas do passado', 'Zelig, o Visionário, na Bastilha Invergarde, que fica no Ermo das Serpes, quer que você recupere o Orbe de Vidência.', 'As lembranças do passado assombram esta terra, $n. Eu ouço os gritos dos guerreiros tombados por toda Nortúndria chamando por mim.$B$BArthas deixou marcas terríveis em tudo que tocou. Em seu rastro, só ficaram morte e destruição. Assim, é importante que estudemos o passado, para melhor conhecer o inimigo. Talvez verdades secretas venham à tona para ajudar nossa campanha.$B$BAntes de mais nada, você precisa recuperar meu orbe de vidência que está na prefeitura, $n. Saia daqui da torre, vire à esquerda e então desça até chegar à praça da cidade.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zelig, o Visionário, na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12283, 'ptBR', 'A verdade aparecerá', 'A Agente Skully quer que você adquira o Diário da General Abbendis e o entregue para o Alto-executor Iracundo, em Perfídia.', 'Precisamos entender o que está acontecendo aqui. Precisamos do diário da general!$B$BTenho certeza de que você vai encontrá-lo no criado-mudo no andar de cima da casa dela. É a casa perto da igreja, depois dos estábulos e da madeireira.$B$BQuando conseguir o diário, leve-o para o alto-executor em Perfídia.$B$BVocê terá que fazer isso à moda antiga, pois o poder do espelho está enfraquecido e só há o suficiente para uma pessoa.$B$B<A agente sorri.>', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Alto-executor Iracundo em Perfídia, que fica no Ermo das Serpes.', 0),
(12284, 'ptBR', 'Tem que puxar as orelhas', 'O Comandante Bargok quer que você derrote 15 unidades ou jogadores da Aliança na Madeireira Céu Azul.', 'Sofremos baixas pesadas aqui, $r.$b$bA única boa notícia é que nós ferimos tanto quanto fomos feridos. Requisitei mais tropas, mas a maior parte das nossas forças está atolada na Baía dos Empreendimentos. Parece que estamos por conta própria por enquanto.$b$bNão importa o quanto a situação ficar feia, nós VAMOS resistir. Os preciosos recursos desta região são essenciais para o sucesso em longo prazo da Horda em Nortúndria.$b$bTemos que deixar a Aliança em estado de alerta até que os reforços cheguem. Vá para o campo de batalha e dê a eles algo a temer.', '', 'Unidades da Aliança eliminadas', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Bargok na Madeireira Céu Azul, que fica na Serra Gris.', 0),
(12285, 'ptBR', 'Fazei aos outros', 'O Alto-executor Iracundo, em Perfídia, quer que você entregue a Cabeça da General-de-exército Abbendis para ele.', 'O ataque é iminente, $c. Preciso que você entre lá e arranque a cabeça da Ofensiva Escarlate... literalmente!$B$BMas não vai ser fácil... Abbendis com certeza estará cercada de muitos guardas.$B$BTraga-me a cabeça dela e eu farei com que você seja devidamente $Grecompensado:recompensada; por salvar Perfídia.$B$BSe falhar, nem precisa voltar aqui!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Alto-executor Iracundo em Perfídia, que fica no Ermo das Serpes.', 0),
(12286, 'ptBR', 'Balde de balas', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(12287, 'ptBR', 'Orik Fidélio e a Costa Abandonada', 'Procure a ajuda de Orik Fidélio nos Confins da Aurora, no Ermo das Serpes.', 'Eu perscrutei o orbe e vi a trilha que você tem de seguir, $n.$B$BHá muitos anos, uma atrocidade foi cometida nas praias do Ermo das Serpes. O ato em si permanece envolto em trevas, mas estou certo de que o seu destino se encontra ao sul, entre as ruínas da Costa Abandonada.$B$BTome o caminho a sudeste, passando pela praça destruída. Siga a trilha até chegar aos Confins da Aurora. Lá você encontrará um velho amigo meu chamado Orik Fidélio. Ele espera por você.', '', '', '', '', '', '', '', '', '', '', 0),
(12288, 'ptBR', 'Sobrecarregada!', 'Aumana, na Madeireira Céu Azul, quer que você use o Torniquete Recuperador em 10 Escaramuçadores Feridos.', 'Você aí, $c! Me ajude!$b$bEstamos perdendo vidas inestimáveis! Há feridos demais para eu socorrer sozinha. Se não curarmos nossos soldados, poderemos ser expulsos da Serra Gris!$b$bPegue este torniquete e use-o nos feridos no campo de batalha$b$bRápido, $n! Eles tão morreeeendo!', '', 'Escaramuçador Ferido curado', '', '', '', '', '', '', '', 'Fale novamente com Aumana na Madeireira Céu Azul, que fica na Serra Gris.', 0),
(12289, 'ptBR', 'Chutando cachorro morto', 'O Sargento Hartsman quer que você derrote 15 unidades ou jogadores da Horda na Madeireira Céu Azul.', 'É um dia negro para a Aliança. Muitos soldados valorosos jazem mortos ou moribundos. Nosso único conforto é que eles lutaram corajosamente e massacraram muitos inimigos também.$b$bCom a maioria de nossas forças comprometidas com a batalha da Baía dos Empreendimentos, enfrentaremos sozinhos a tempestade. Os recursos nesta região são vitais à Aliança e podem fazer uma grande diferença na batalha contra a Horda. Não podemos fracassar!$b$bVá, $n. Ataque enquanto eles lambem as feridas. Vingue os irmãos caídos e mantenha nossas esperanças vivas!', '', 'Unidades da Horda eliminadas', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Hartsman na Madeireira Céu Azul, que fica na Serra Gris.', 0),
(12290, 'ptBR', 'O elixir de herassombra', 'Orik Fidélio, nos Confins da Aurora, no Ermo das Serpes, quer que você colete 5 Herassombras no Cerro Lúgubre.', 'Os espíritos dos condenados assombram a costa. Em vida, eles foram bravos e nobres soldados da Aliança, mas agora estão condenados a vagar pelo mundo até o fim dos tempos. Precisamos descobrir a fonte da angústia dessas almas se quisermos libertá-las.$B$BA sudeste daqui, no Cerro Lúgubre, existe uma planta rara chamada herassombra. Eu preciso de herassombra para preparar um elixir que permitirá o seu ingresso temporário no mundo dos esquecidos. Vá e me traga essa erva.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Orik Fidélio nos Confins da Aurora, no Ermo das Serpes.', 0),
(12291, 'ptBR', 'A história esquecida', 'Orik Fidélio, nos Confins da Aurora, no Ermo das Serpes. quer que você escute as histórias de um Camponês Esquecido, de um Carabineiro Esquecido, de um Cavaleiro Esquecido e de um Soldado Raso Esquecido.', 'As toxinas do elixir de herassombra deixarão você inconsciente. A herassombra é tão poderosa que até seu espírito será enganado, e você poderá adentrar temporariamente o mundo dos mortos.$B$BAo virar espírito, você deverá falar com os cidadãos fantasmagóricos da Costa Abandonada. Descubra a causa da angústia deles e depois fale novamente comigo.$B$BLembre-se, $n, que esses espíritos já foram soldados da Aliança. Trate-os com respeito, honra e dignidade.$B$BAgora, de posse do elixir, siga em direção sul, para a Costa Abandonada.', '', 'Camponês Esquecido Interrogado', 'Carabineiro Esquecido Interrogado', 'Cavaleiro Esquecido Interrogado', 'Soldado Raso Esquecido Interrogado', '', '', '', '', 'Fale novamente com Orik Fidélio nos Confins da Aurora, no Ermo das Serpes.', 0),
(12292, 'ptBR', 'Apoio local', 'O Tenente Dumont, no Chalé do Pinho Âmbar, quer que você vá até Entreposto Perene e obtenha o Baú de Cedro.', 'Estamos travados numa luta equilibrada com a Horda na Serra Gris. Nossas forças estão bem equiparadas às deles, e todos os sinais apontam para um empate sangrento.$B$BIsto é, até hoje de manhã. Os coureadores locais pediram nossa ajuda. Aparentemente a Horda tomou algo que lhes pertence... Algum tipo de relíquia.$B$BSe nós a recuperarmos para eles, eles nos darão a vantagem de que precisamos. Vá ao Entreposto Perene, a oeste do Forte da Conquista, e procure um baú de cedro.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Dumont no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12293, 'ptBR', 'Acordo fechado', 'Leve o Baú de Cedro a Ivan no Posto Álamo.', 'Temos o que os coureadores querem. Agora é hora de recrutá-los para o nosso lado.$B$BLeve o baú para um coureador chamado Ivan no Posto Álamo, logo ao norte daqui.$B$BSe tudo correr bem, logo os mateiros locais estarão trabalhando como batedores no exército do rei.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ivan no Posto Álamo, que fica na Serra Gris.', 0),
(12294, 'ptBR', 'Um pacto experimental', 'Fale novamente com o Tenente Dumont no Chalé do Pinho Âmbar.', 'Muito bem, $n. Seu lado respeitou os termos combinados.$B$BDiga a Dumont que vamos honrar o acordo.', '', '', '', '', '', '', '', '', '', '', 0),
(12295, 'ptBR', 'Exercícios diplomáticos', 'Fale com o Enviado Ducal no Arroio Prateado.', 'Passamos semanas tentando negociar com aqueles coureadores, mas não estávamos chegando a lugar algum até que você achou aquele maldito baú deles.$B$BNosso enviado em Arroio Prateado vai gostar muito das novidades. Mandamos Ducal para lá há uma semana, e a última carta dele indica que teve pouquíssimo progresso.$B$BVá para o Arroio Prateado e ajude-o nos esforços diplomáticos. Siga pela estrada rumo ao noroeste e você chegará lá depois de cruzar algumas pontes.', '', '', '', '', '', '', '', '', '', '', 0),
(12296, 'ptBR', 'Vida ou morte', 'Rheanna, na Madeireira Céu Azul, quer que você use a Bandagem Recuperadora em 10 Soldados de Infantaria Feridos de Cerro Oeste.', 'Ah, a carnificina...$b$bJá passei por muitas batalhas, $c, e esta foi a mais brutal que já vi. Nossa guerra contra a Horda se intensificou ainda mais. Nortúndria é pequena demais para as duas facções... É matar ou morrer.$b$bSe quisermos sobreviver mais um dia, precisamos tratar dos feridos. Há homens demais para eu resgatar sozinha.$b$bPreparei umas bandagens especiais e, com elas, você poderá me ajudar. Leve uma e cuide daqueles que ainda não sucumbiram aos ferimentos.', '', 'Soldado de Infantaria de Cerro Oeste curado', '', '', '', '', '', '', '', 'Fale novamente com Rheanna na Madeireira Céu Azul, que fica na Serra Gris.', 0),
(12297, 'ptBR', 'Sobre traidores e traição', 'O Capitão Carneiro quer que você mostre a Missiva da Aliança para Grier Metalomalho na Bastilha da Guarda Oeste.', 'Esta lista deve ser entregue ao alto-comandante Haraldo Serpecida. Ele comanda a Sétima Legião, que está aquartelada na Bastilha Invergarde, na fronteira oriental do Ermo das Serpes.$B$BSe algum dos traidores listados estiver aquartelado em Invergarde, pode haver uma catástrofe!$B$BDepressa, $n. Mostre este documento a Grier Metalomalho aqui, na Bastilha da Guarda Oeste, e explique a ele a natureza da sua missão. Ele lhe dará o grifo mais veloz para levar você a Invergarde!', '', '', '', '', '', '', '', '', '', 'Fale com Grier Metalomalho no Fiorde Uivante.', 0),
(12298, 'ptBR', 'Alto-comandante Haraldo Serpecida', 'Entregue a Missiva da Aliança para o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, a leste do Ermo das Serpes.', '<Grier devolve a missiva a você.>$B$BCelicanto vai levar você até Invergarde, $n. Garanto que será o voo mais rápido da sua vida. Agora vá!', '', '', '', '', '', '', '', '', '', 'Fale com o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12299, 'ptBR', 'Hospitalidade nortista', 'Sergei, em Arroio Prateado, quer que você mate 8 Espoliadores do Forte da Conquista.', 'É um prazer conhecer você. Vamos celebrar nosso pacto participando de uma boa e velha sessão de massacre da Horda.$B$BVocê encontrará os espoliadores do Forte da Conquista logo ao lado da vila, a oeste daqui. Por que você não vai até lá e os caça como os animais imundos que são?$B$BVamos ver se nossos novos aliados fazem tanto quanto falam...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Sergei em Arroio Prateado, que fica na Serra Gris.', 0),
(12300, 'ptBR', 'Teste de macheza', 'Encontre o Sargento Quebraossos a noroeste de Arroio Prateado e passe no Teste de Macheza.', 'Muito bem, camarada. Você nos fez um favor ou dois, mas ainda não passou pelo real teste de coragem.$B$BPor estas bandas aqui, você não é $Gum caçador:uma caçadora; de verdade até vestir a pele da presa.$B$B<Sergei tira a faca de esfolar da bainha e lhe entrega.>$B$BO líder desses orcs sem mãe que atacam nossa vila chama-se Quebraossos; ele está num acampamento a noroeste daqui.$B$BÉ isso mesmo. Você vai esfolar esse monstro.', '', 'Teste de macheza', '', '', '', '', '', '', '', 'Fale novamente com o Coureador Capturado em Arroio Prateado, que fica na Serra Gris.', 0),
(12301, 'ptBR', 'A verdade nos libertará', 'Orik Fidélio, nos Confins da Aurora, no Ermo das Serpes, quer que você use o Orbe Cristalino de Orik nas ruínas da Costa Abandonada para redimir os Esquecidos.', 'Zelig me deu essa bola de cristal há muitos anos, com instruções específicas sobre como usá-la. Durante cinco anos, sempre que eu sentia raiva, ansiedade ou mágoa por causa do que aconteceu aqui, eu concentrava meus pensamentos nesse orbe.$B$BAgora eu entendo porque Zelig me deu esse cristal.$B$BLeve-o para a Costa Abandonada. Encontre as ruínas da minha velha base, na parte mais alta da praia, e coloque o orbe no centro da cidade. Que os esquecidos vejam o mundo através do meu coração e da minha alma.', 'Esquecidos redimidos', '', '', '', '', 'Esquecidos redimidos', '', '', '', 'Fale novamente com Orik Fidélio nos Confins da Aurora, no Ermo das Serpes.', 0),
(12302, 'ptBR', 'Palavras de advertência', 'Vá para o noroeste de Arroio Prateado.', 'Obrigada por me ajudar, $n. Me chamo Sasha. Escute, tenho que dar o fora daqui.$B$BAs pessoas que te mandaram aqui... a minha gente... eles mudaram. Não são mais boas pessoas... e querem transformar você em... um deles.$B$BEsse... "teste" que lhe deram é só o começo.$B$BVá ao extremo noroeste de Arroio Prateado. Lá encontrará algo muito interessante.$B$BBoa sorte... e não confie em ninguém.', '', '', '', '', '', '', '', '', '', '', 0),
(12303, 'ptBR', 'Verbas para o esforço de guerra', 'O Intendente Bartolotto, em Perfídia, quer que você recupere 6 Tesouros Esquecidos.', '<O intendente abaixa a voz e sussurra.>$B$B$C, eu preciso de sua ajuda. Nossos cofres estão vazios. A Vanguarda Kor\'kron no Portão da Ira levou todas as nossas verbas para financiar a luta lá.$B$BMas eu ouvi boatos de que há tesouros entre os destroços da Costa Abandonada, a sudeste daqui.$B$BPrecisamos fazer alguma coisa e rápido, ou não conseguiremos continuar a luta contra a Ofensiva Escarlate. Como você sabe, guerra custa caro!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Intendente Bartolotto em Perfídia, que fica no Ermo das Serpes.', 0),
(12304, 'ptBR', 'A casa de praia', 'O Topógrafo Reis, ao norte da Costa Abandonada, quer que você mate 20 fantasmas Esquecidos.', 'É hora de expandir Perfídia!$B$BLogo daremos um jeito na Ofensiva, mas agora preciso que você adiante nossos trabalhos na Costa Abandonada. O valor imobiliário daquela área tem um grande potencial e, $gmeu amigo:minha cara;, que vista!$B$BInfelizmente, o lugar está infestado de fantasmas, marujos que naufragaram e não sabem que morreram, aquilo de sempre.$B$BLimpe a praia e as águas da costa, e talvez possamos conversar sobre a construção de um mausoléu novinho e confortável lá muito em breve.', '', 'Fantasmas esquecidos mortos', '', '', '', '', '', '', '', 'Fale novamente com o Topógrafo Reis na Costa Abandonada, que fica no Ermo das Serpes.', 0),
(12305, 'ptBR', 'Pensamentos finais', 'Fale novamente com Zelig, o Visionário, na Bastilha Invergarde, que fica no Ermo das Serpes.', 'Você me fez honra, e à memória de centenas de veteranos da Aliança, $n. Zelig foi sábio de enviar você para cá. Por favor, retorne a ele com meus agradecimentos. Ele ficará feliz ao saber o que aconteceu hoje na Costa Abandonada.$B$BMuito embora eu não tenha o dom da clarividência como Zelig, tenho certeza de que grandes feitos aguardam você, $Gamigo:amiga;.$B$BAdeus.', '', '', '', '', '', '', '', '', '', '', 0),
(12306, 'ptBR', 'Clube da Cerveja do Mês', 'Entregue a Ficha de Inscrição do Clube "Cerveja do Mês" para Ray\'ma em Orgrimmar.', '$n, saiba que cervejeiros unidos jamais serão vencidos! Como membro do Clube da Cerveja do Mês, você e seus companheiros de copo sempre terão acesso às melhores cervejas.$b$bEntregue a ficha de inscrição do Clube da Cerveja do Mês para Ray\'ma, em Orgrimmar.', '', '', '', '', '', '', '', '', '', 'Fale com Ray\'ma em Orgrimmar.', 0),
(12307, 'ptBR', 'Raiz de acônito', 'Katia, em Arroio Prateado, quer que você arranque 8 Raízes de Acônito.', 'Já ouviu falar na planta acônito? É uma erva horrível... destrói nossas plantações.$B$BPassamos a semana passada inteira exterminando essa droga, mas as raízes estão brotando de novo.$B$BPode não parecer urgente, mas o ressurgimento da planta pode vir a ser um verdadeiro... desastre. Você poderia nos ajudar desenraizando as ervas quando encontrá-las perto da vila?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Katja em Arroio Prateado, que fica na Serra Gris.', 0),
(12308, 'ptBR', 'Fuga do Arroio Prateado', 'Abra a Jaula de Madeira e ajude o Batedor Libertado da Aliança a escapar de Arroio Prateado. Apresente-se ao Tenente Dumont quando chegar ao Chalé do Pinho Âmbar.', 'Você... você não é um deles? Rápido! Deixe-me sair!$B$BPrecisamos chegar ao Chalé do Pinho Âmbar imediatamente! Quando o tenente Dumont descobrir quem essa gente realmente é, esta vila será reduzida a escombros.', '', 'Fuga do Arroio Prateado', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Dumont no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12309, 'ptBR', 'Encontre Durkon!', 'Procure o Paladino Durkon, na Cripta de Invergarde, no Ermo das Serpes.', 'Depois que o Flagelo invadiu a muralha sul, eu ordenei ao Paladino Durkon que investigasse a cripta da cidade. Há alguns instantes, recebi este relatório dele.$B$BOs mortos-vivos que estão nos infernizando vêm de dois lugares: das ruínas de Invergarde, que agora é uma incubadora para o Flagelo, e da nossa própria cripta! Em meio ao caos e à confusão, o Flagelo conseguiu infiltrar um necrolorde na cripta.$B$BNo relatório, Durkon me pede ajuda. Encontre-o e ajude-o, $n. A cripta fica do lado oeste da praça da cidade.', '', '', '', '', '', '', '', '', '', '', 0),
(12310, 'ptBR', 'Uma reação rápida', 'O Tenente Dumont quer que você vá ao Posto Boca da Mata e mate Vladek e 7 Caçadores de Arroio Prateado.', 'Nossa reação tem que ser imediata. Decisiva. Precisamos ensinar os selvagens a não nos provocar.$B$BNossos batedores localizaram o que sobrou dos coureadores de Arroio Prateado... Você sabe, aqueles que você não conseguiu incendiar. Parece que eles estão bloqueando a estrada para o sudeste... talvez tentem nos prender.$B$BVá até o posto da Boca da Mata e dê um jeito neles. Ouvimos que o líder deles é um homem chamado Vladek... Quero que você suma com ele.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Dumont no Chalé do Pinho Âmbar, que fica na Serra Gris.', 0),
(12311, 'ptBR', 'A cripta do nobre', 'O Paladino Durkon, na Bastilha Invergarde, quer que você mate o Necrolorde Amarion.', 'Dentro das frias paredes de pedra dessa cripta ficam os restos dos nobres e dignitários que morreram em Nortúndria. E bem no centro da cripta agora existe um necrolorde que reanima os cadáveres para servir ao Flagelo.$B$BVá até o fundo da Cripta de Invergarde e mate o Necrolorde Amarion. Só então os ataques internos vão parar!$B$BE $n, fique $gatento:atenta; a qualquer informação que possa estar dando sopa na sala em que Amarion fica.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Paladino Durkon, na Cripta de Invergarde, que fica no Ermo das Serpes.', 0),
(12312, 'ptBR', 'Segredos do Flagelo', 'Entregue o Tomo Encadernado com Carne ao Paladino Durkon, na Bastilha Invergarde, no Ermo das Serpes.', 'Você vê estranhos símbolos e formas garatujados no livro encadernado com carne; os símbolos parecem ter sido gravados com uma lâmina. Você não faz ideia do que está escrito, mas dá para notar que, o que quer que seja, deve ser importante.$B$BEntregue o tomo ao Paladino Durkon, de guarda no alto da Cripta de Invergarde.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Paladino Durkon, na Cripta de Invergarde, que fica no Ermo das Serpes.', 0),
(12314, 'ptBR', 'Abaixo a capitão Zorna!', 'Mate a Capitão Zorna e apresente-se ao barão Franco na Baía dos Empreendimentos.', 'As forças da Horda estão a ponto de romper nossas linhas, e conquistarão a Baía dos Empreendimentos se nós não agirmos. O comandante da Horda no porto é a capitão Zorna, que se encontra perto do navio do lado oposto da baía.$B$BSe você derrotá-la, a ofensiva da Horda fraquejará e nós vamos aproveitar a chance para capturar o porto. Cuidado, $n, pois Zorna é uma combatente feroz. Talvez seja necessário levar várias pessoas para derrotá-la, ou, se você tiver acesso a um retalhador reparado, poderá aproveitá-lo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Franco na Baía dos Empreendimentos na Serra Gris.', 0),
(12315, 'ptBR', 'Esmague o Capitão Aguaclara!', 'Mate o Capitão Aguaclara e apresente-se ao General Khizgur na Baía dos Empreendimentos.', 'A cada ofensiva, nossos homens enfrentam reforços descansados da Aliança. É quase como se o comandante dele antecipasse todas as minhas manobras!$B$BChegou a hora do Capitão Aguaclara encontrar seu fim. Ele comanda as tropas a bordo de um destróier da Aliança no extremo oposto da baía.$B$BA luta não será nada fácil, $n. Leve alguns amigos de confiança, ou, se você tiver a chave de um daqueles retalhadores reparados, use-o para estripar Aguaclara. De qualquer maneira, ele tem que morrer!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o General Khizgur na Baía dos Empreendimentos, que fica na Serra Gris.', 0),
(12316, 'ptBR', 'Você já foi à baía?', 'Derrote 10 unidades ou jogadores da Horda na Baía dos Empreendimentos e fale novamente com o Tenente Stuart.', 'Não podemos permitir que a Horda controle a Baía dos Empreendimentos. O porto é essencial para nossas operações na Serra Gris e além.$B$BO capitão Mantoforte levou o resto da Brigada de Cerro Oeste para o leste em busca de uma passagem pelas montanhas, então não teremos reforços.$B$BVá para o campo de batalha, $n, e mate os beserkeres do Forte da Conquista que a Horda mandou contra nós. Massacre-os até que não reste mais nenhum. A Aliança precisa do porto!', '', 'Integrantes da Horda mortos', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Stuart na Baía dos Empreendimentos, que fica na Serra Gris.', 0),
(12317, 'ptBR', 'Você já foi à baía?', 'Derrote 10 unidades ou jogadores da Aliança na Baía dos Empreendimentos e fale novamente com o Centurião Kiggram.', 'A maldita Brigada de Cerro Oeste se revelou um oponente mais valoroso do que tínhamos imaginado. Apesar dos parcos números, eles lutam bem e com bravura, mas não podemos nos dar ao luxo de tentar vencer pelo cansaço.$B$BAs ordens da Conquistadora Krenna são bem claras: temos que capturar o porto rapidamente. Você precisa resolver este impasse a nosso favor, $n. Encontre os marinheiros do inimigo e os massacre até que a resistência termine. Só assim será possível tomar posse do porto.$B$BVá logo. Não queremos deixar a Conquistadora Krenna esperando.', '', 'Integrantes da Aliança mortos na Baía dos Empreendimentos', '', '', '', '', '', '', '', 'Fale novamente com o Centurião Kiggram na Baía dos Empreendimentos, que fica na Serra Gris.', 0),
(12318, 'ptBR', 'Salve a CervaFest!', 'Fale com o Espião da CervaFest no Glutão Implacável, que fica no Abismo Rocha Negra.', '$n, nossos espiões descobriram um plano terrível! Os anões Ferro Negro querem destruir a nossa amada CervaFest!$B$BO Coren Cervatroz, líder de uma família de cervejeiros renegados, recrutou os anões do Abismo Rocha Negra, que costumam nos atacar com máquinas-toupeira.$B$BNosso espião está infiltrado no Glutão Implacável, uma taberna entranhada no Abismo Rocha Negra. Ele sabe mais a respeito do plano do Cervatroz.$B$BEncontre o espião e salve a CervaFest!', '', '', '', '', '', '', '', '', '', '', 0),
(12319, 'ptBR', 'O mistério do tomo', 'Leve o Tomo Encadernado com Carne para o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, que fica no Ermo das Serpes.', 'O que pode ser isso, $n? Com certeza não foi uma maldição comum essa que o lich desgramado jogou em ti!$B$B<Durkon passa as páginas horrendas do tomo.>$B$BNem sequer sei se estou olhando do jeito certo. Precisamos descobrir que informação esse tomo guarda!$B$B<Durkon devolve o livro para você.>$B$BO Alto-comandante saberá o que fazer. Leve o tomo pra ele e conte exatamente o que aconteceu aqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12320, 'ptBR', 'A linguagem da morte', 'Leve o Tomo Encadernado com Carne para o Inquisidor Galhardo na prisão da Bastilha Invergarde.', 'Pegue o livro e siga a trilha que leva até o quartel. Quando chegar ao quartel, desça pela escadaria até a prisão. Na prisão você encontrará o Inquisidor Galhardo e o Prefeito Godofredo. Creio que Godofredo é a peça que falta no quebra-cabeça, e Galhardo é quem vai juntar todas as peças.$B$BAgora vá!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Inquisidor Galhardo, na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12321, 'ptBR', 'Um sermão virtuoso', 'Espere o Inquisidor Galhardo terminar o Sermão Virtuoso e informe o que você descobrir ao Alto-comandante Haraldo Serpecida na Bastilha Invergarde, no Ermo das Serpes.', 'Godofredo Gotardo, que já foi um homem íntegro e prefeito de Invergarde, é agora um agente do Flagelo. Sua transformação de homem em carniçal que não morre aconteceu lentamente. Agora ele escuta o chamado do Lich Rei e vive apenas para servi-lo.$B$BComo todo membro do Flagelo, Godofredo conhece a linguagem da morte e, com o incentivo certo, vai nos dizer o que precisamos saber sobre o tomo.$B$BQuando ele disser o que você quer saber, fale novamente com o alto-comandante nas linhas de frente. Eu vou ficar aqui limpando a sujeira.', 'Sermão Virtuoso ouvido', '', '', '', '', 'Sermão Virtuoso ouvido', '', '', '', 'Fale novamente com o Alto-comandante Haraldo Serpecida na Bastilha Invergarde, que fica no Ermo das Serpes.', 0),
(12323, 'ptBR', 'Ô fumacê, fumacê', 'Use a Bomba de Fumaça para expulsar 20 Trabalhadores Retardatários dos prédios e então se apresente ao Sargento Downey.', 'Ainda há grupos de funcionários covardes da Empreendimentos S.A. escondidos em alguns dos prédios no centro da Baía dos Empreendimentos. Preciso colocar todos os soldados disponíveis para lutar contra a Horda, mas também não podemos permitir que esses retardatários da Empreendimentos S.A. ocupem os prédios.$B$BTalvez seja possível "convencê-los" a voltar para o navio deles. Use esta bomba de fumaça para defumar os retardatários dos esconderijos no alojamento, serraria ou no estábulo. Não chegue muito perto: eles provavelmente mordem.', '', 'Trabalhadores Retardatários defumados', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Downey na Baía dos Empreendimentos, que fica na Serra Gris.', 0),
(12324, 'ptBR', 'Ô fumacê, fumacê', 'Use a Bomba de Fumaça para expulsar 20 Trabalhadores Retardatários dos prédios e então se apresente ao Guarda Pétreo Totem da Fúria.', 'Como se a infestação dos ratos rastejantes da Aliança já não fosse suficiente, ainda temos funcionários da Empreendimentos S.A. refugiados em alguns dos prédios. Não vale a pena perder tempo matando aqueles vermes, e, de qualquer jeito, não posso desperdiçar guerreiros com isso.$B$BTalvez possamos "convencê-los" a fugir para o navio. Use esta bomba de fumaça para afugentar os retardatários dos esconderijos no alojamento, na serraria ou no estábulo. Mas não chegue muito perto: sabe-se lá que doenças esses vermes transmitem.', '', 'Trabalhadores Retardatários defumados', '', '', '', '', '', '', '', 'Fale novamente com o Guarda Pétreo Totem da Fúria na Baía dos Empreendimentos, que fica na Serra Gris.', 0),
(12325, 'ptBR', 'Em território inimigo', 'Fale com o Comandante de Grifos Eurico e pegue um voo para o Posto de Thorson. Apresente-se ao Duque Augusto Martel quando você chegar ao Posto de Thorson no Ermo das Serpes.', 'Você fez muito para ajudar nossos esforços contra o Flagelo, $n. De fato, o moral dos que falaram com você melhorou! Tamanho é o grau da sua influência sobre os soldados e cidadãos de Invergarde, $gcaro aliado:cara aliada;.$B$BE por sua causa, estamos preparados para começar a ofensiva! Apresente-se ao Duque Augusto Martel, depois dos Campos de Carniça, no Posto de Thorson, a leste daqui. O Comandante de Grifos Eurico, na estação de grifos, preparou um voo especial que levará você para trás das linhas inimigas. Agora vá!', '', '', '', '', '', '', '', '', '', '', 0),
(12326, 'ptBR', 'Surpresa a vapor', 'Use um Tanque a Vapor da Aliança para destruir 6 Carroças Pestilentas e descarregar os Soldados de Elite da 7ª Legião no Mausoléu Invergarde. Fale com Amgo Cash dentro do Mausoléu Invergarde, que fica no Ermo das Serpes.', 'Essa é uma missão de busca e destruição. Você vai guiar um tanque pelos Campos de Carniça para desmantelar as carroças pestilentas do Flagelo. Em cada tanque há três soldados da 7ª Legião. Todos devem sobreviver para que a missão seja bem-sucedida!$B$BVocê precisa chegar perto de uma carroça pestilenta para poder enviar o engenheiro que desabilitará o vagão. Deixe-o fazendo o serviço e siga para a próxima carroça. Quando a área estiver livre de carroças pestilentas, vá para o mausoléu em frente ao bastião em ruínas e descarregue o resto da tripulação. Encontre Amgo Cash do lado de dentro.', '', 'Carroça Pestilenta sabotada', 'Elite da 7ª Legião descarregado a salvo', '', '', '', '', '', '', 'Fale com Amgo Cash no Mausoléu Invergarde, que fica no Ermo das Serpes.', 0),
(12327, 'ptBR', 'Experiência Extracorpórea', 'Beba a Poção de Teia Diáfana perto da Bola de Cristal de Ruuna e testemunhe uma Visão do Passado.', 'Ah, você busca uma visão do passado. É $gum:uma; $r $gsábio:sábia;.$B$BTodas as vezes que alguém aparece para uma leitura, sempre perguntam sobre o futuro. Mas quando você chega à minha idade, aprende que vaticinar o passado geralmente é muito mais útil.$B$BBeba esta poção e espie minha bola de cristal. Vamos ver o que descobrimos.', 'Visão do Passado', '', '', '', '', 'Visão do Passado', '', '', '', 'Fale com Ruuna, a Cega, no Acampamento da Ruuna, que fica na Serra Gris.', 0),
(12328, 'ptBR', 'O pedido de Ruuna', 'Ruuna, a Cega, quer que você obtenha 4 punhados de Poeira Diáfana.', 'Não vou cobrar ouro pelos meus serviços, pois prevejo que suas ações são necessárias, e muita coisa dependerá daquilo que você descobrir hoje.$B$BPorém, peço que você recolha alguns reagentes para mim. Obtenha a poeira diáfana das mariposas pteridópsidas a nordeste daqui. Se você fizer o favor, eu prepararei uma poção que $go:a; levará ao momento e local em que ocorreram os eventos que você precisa presenciar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ruuna, a Cega, no Acampamento da Ruuna, que fica na Serra Gris.', 0),
(12329, 'ptBR', 'Destino e coincidência', 'Fale com Sasha no Entreposto Pinheiro Branco.', 'Há dois tipos de pessoas no mundo, $n. Aqueles que acreditam em coincidências e os que não acreditam.$B$BNo dia em que perdi minha visão, recebi o dom da clarividência. Imagino que você consiga deduzir em qual tipo me enquadro.$B$BHoje mais cedo, uma jovem chamada Sasha recebeu a mesma visão que você. Você precisa falar com ela.$B$BSasha está diretamente a leste daqui, no Entreposto Pinheiro Branco, a caminho da Aldeia Solstício.', '', '', '', '', '', '', '', '', '', '', 0),
(12330, 'ptBR', 'Anatólio falará', 'Sasha, no Entreposto Pinheiro Branco, quer que você use o Dardo Tranquilizante em Tatiana na Aldeia Solstício. Traga Tatiana de volta ao Entreposto Pinheiro Branco.', 'Minha irmã está por aqui em algum lugar, só que não consigo fazer este monstro falar.$B$BEle parece não se importar com o próprio bem-estar, mas eu tive uma ideia. Eu conhecia a mulher de Anatólio, Tatiana, antes da chegada da seita dos lobos. Ela era uma tratadora de cavalos.$B$BLeve este dardo tranquilizante. Traga-a de volta viva, vamos precisar de Tatiana para arrancar alguma coisa de Anatólio.$B$BEu $go:a; ajudarei a encontrar aquele que está por trás disso tudo – depois que salvarmos minha irmã.', 'Tatiana entregue', '', '', '', '', 'Tatiana entregue', '', '', '', 'Fale novamente com Sasha no Entreposto Pinheiro Branco, que fica na Serra Gris.', 0),
