(13736, 'ptBR', 'Surge um campeão', 'Fale com a Justicar Mariel Veras nos Campos do Torneio Argênteo.', '$C, agora seus colegas e eu $go:a; respeitamos. Você derrotou todos os que $go:a; desafiaram e dominou a arte de combate do torneio. Não tenho dúvidas de que você está $gpronto:pronta; para enfrentar os campeões de outras cidades pela glória de Orgrimmar!$B$B$n, a Justicar Mariel Veras quer falar com você e inscrevê-$glo:la; formalmente na grande escaramuça dos campeões.', '', '', '', '', '', '', '', '', '', '', 0),
(13737, 'ptBR', 'Surge um campeão', 'Fale com a Justicar Mariel Veras nos Campos do Torneio Argênteo.', '$C, agora seus colegas e eu $go:a; respeitamos. Você derrotou todos os que $go:a; desafiaram e dominou a arte de combate do torneio. Não tenho dúvidas de que você esteja $gpronto:pronta; para enfrentar os campeões de outras cidades pela glória dos Lançanegra!$B$B$n, a Justicar Mariel Veras quer falar com você e $ginscrevê-lo:inscrevê-la; formalmente na grande escaramuça dos campeões.', '', '', '', '', '', '', '', '', '', '', 0),
