(25787, 'ptBR', 'A verdade está aí dentro', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(25788, 'ptBR', 'A verdade está aí dentro', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(25789, 'ptBR', 'A verdade está aí dentro', 'Leve o Dispositivo Misterioso para Orgrimmar, Cidade Baixa, Luaprata ou para o Penhasco do Trovão, e mostre-o para um Representante da Harmonia Telúrica.', 'Você encontra um estranho dispositivo no mesmo lugar onde a fenda elemental estava. O que será isso?$B$BAlgum estudioso de uma das capitais deve saber algo a respeito.', '', '', '', '', '', '', '', '', '', '', 0),
(25790, 'ptBR', 'De volta para o Crazzle', 'Fale com Crazzle Molavivaz na Serra do Casco Fendido, que fica em Mil Agulhas.', 'Eu NÃO SOU IDIOTA!$B$BVolte para o seu senhor e diga que não haverá acordo! Claro, se você conseguir sair daqui $Gvivo:viva;.', '', '', '', '', '', '', '', '', '', '', 0),
(25791, 'ptBR', 'De volta para o Riznek', 'Fale novamente com Riznek na Serra do Casco Fendido, que fica em Mil Agulhas.', 'Eu NÃO SOU IDIOTA!$B$BVolte para o seu senhor e diga que não haverá acordo! Claro, se você conseguir sair daqui $Gvivo:viva;.', '', '', '', '', '', '', '', '', '', '', 0),
(25792, 'ptBR', 'Sempre em frente!', 'Use a Runa de Fogo para destruir 4 Totens de Constrição no Front Jubafria.', 'A maior parte dos montanhistas e dos tanques a vapor de Dun Morogh está em campo contra o Front Jubafria, que vem se aproximando de nós a partir do sul. Mal estamos conseguindo conter os trolls, quanto mais avançar sobre a vila e sequestrar o líder deles.$B$BEles bloquearam o caminho das nossas tropas com totens misteriosos que sufocam os montanhistas, deixando-os indefesos. Esta pedra contém uma runa de fogo. Deve ser suficiente para destruir os totens e libertar os montanhistas.', '', 'Totens de Constrição queimados', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Tharran em Kharanos.', 0),
(25793, 'ptBR', 'As Entranhas da Terra', 'Fale com McGee Pé-de-Aço nas Entranhas da Terra, que ficam na Cordilheira das Torres de Pedra.', 'O propósito desta base era estabelecer uma posição nas Torres de Pedra para Theramore e abrir uma linha de suprimentos para os elfos noturnos. A Horda, infelizmente, lutou encarniçadamente contra nossos objetivos. Os exércitos de Grito Infernal são fortes e impiedosos. Não vejo a Horda tão feroz desde a segunda guerra.$B$BAgora parece que a mina cavada pela Liga dos Exploradores está servindo à Horda como via expressa para a nossa retaguarda. Precisamos fechar essa passagem!', '', '', '', '', '', '', '', '', '', '', 0),
(25794, 'ptBR', 'Santuário submarino', 'Use o Orbe de Vidência de Erunak para ver a localização da Gruta Densanévoa.', 'Acredito que eu tenha localizado o autor do seu bilhete, amig$go:a;.$b$bParece que ele precisa desesperadamente de atenção para sobreviver.$b$bHarmonizarei um dos meus orbes de vidência para que você possa ver com os próprios olhos.', '', 'Orbe de Vidência de Erunak usado', '', '', '', '', '', '', '', 'Fale com Erunak em Beira Fundo.', 0),
(25795, 'ptBR', 'De volta ao santuário', 'Fale novamente com Choluna no Santuário de Aviana, no Monte Hyjal.', 'O Ovo de Aviana deveria ter chegado ao Santuário em segurança. Seria bom se você fosse lá checar a situação! Choluna saberá como lidar com o problema.$B$BEu vou acabar de resolver algumas coisas aqui e encontro com você depois.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Choluna no Santuário de Aviana, no Monte Hyjal.', 0),
(25796, 'ptBR', 'Desapropriação', 'Mate 15 centauros da Serra do Casco Fendido.', 'Aquele petróleo nos pertence! É uma pena que os centauros tenham recuado para cá quando o mar invadiu Mil Agulhas.$B$BUma pena para eles, isso sim!$B$BEles cuspiram na nossa boa vontade, $n. Fizemos uma excelente oferta e eles erraram em não aceitar. Agora nós... ahn... você vai mostrar a eles o erro que cometeram.$B$BAcabe com os centauros da Serra do Casco Fendido. O petróleo é nosso!', '', 'Centauros da Serra do Casco Fendido mortos', '', '', '', '', '', '', '', 'Fale novamente com Crazzle Molavivaz na Serra do Casco Fendido, que fica em Mil Agulhas.', 0),
(25797, 'ptBR', 'Desapropriação', 'Mate 15 centauros da Serra do Casco Fendido.', 'A gente vai pegar aquele petróleo! É uma pena os centauros terem recuado pra cá quando o mar invadiu.$B$BUma pena para eles, isso sim!$B$BEles deram um tapa na nossa cara, $n. A gente faz uma excelente oferta e eles fazem a besteira de não aceitar. Agora a gente... ahn... você vai mostrar pra eles o vacilo que eles deram.$B$BVai lá e passa o rodo nos centauros da Serra do Casco Fendido. O petróleo é nosso!', '', 'Centauros da Serra do Casco Fendido mortos', '', '', '', '', '', '', '', 'Fale novamente com Riznek na Serra do Casco Fendido, que fica em Mil Agulhas.', 0),
(25798, 'ptBR', 'Proteja a perfuratriz', 'Proteja a Perfuradeira de Petróleo.', 'Não vamos sair daqui de mãos abanando! Concorda?$B$BVocê deve estar se perguntando o que tem naquela caixinha gigante. Bem, chega de suspense! Quero que você leve uma de nossas perfuratrizes até os poços de petróleo e pegue um pouquinho de ouro negro.$B$BFique $gatento:atenta; quanto aos centauros. Apenas proteja o equipamento até ter enchido um ou dois barris.', 'Perfuradeira de Petróleo protegida', '', '', '', '', 'Perfuradeira de Petróleo protegida', '', '', '', 'Fale novamente com Crazzle Molavivaz na Serra do Casco Fendido, que fica em Mil Agulhas.', 0),
(25799, 'ptBR', 'Proteja a perfuratriz', 'Proteja a Perfuradeira de Petróleo.', 'A gente não vai sair daqui de mãos abanando! Concorda?$B$BVocê deve estar se perguntando o que tem naquela caixona gigante. Bem, chega de suspense! Eu quero que você leve uma das nossas perfuratrizes até os poços de petróleo e pegue um pouquinho de ouro negro.$B$BMas fica esperto com os centauros. É só proteger o equipamento até ele ter enchido um ou dois barris.', 'Perfuradeira de Petróleo protegida', '', '', '', '', 'Perfuradeira de Petróleo protegida', '', '', '', 'Fale novamente com Riznek na Serra do Casco Fendido, que fica em Mil Agulhas.', 0),
(25800, 'ptBR', 'Caranguejos da vida', 'Colete 5 Garras Carnudas de Rastejante dos Baitiscos.', '$C, temos muito trabalho a fazer aqui, mas não podemos ignorar os presentes do destino. A inundação cobriu as nossas casas e trouxe vários seres marinhos. Agora, a Baía de Menethil está repleta de caranguejos, grandes e prontos para a panela.$B$BQuando a vida lhe der caranguejos, prepare o molho e aproveite. Traga os maiores e mais carnudos que encontrar e você será bem $Gpago:paga;.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Carlos Borba no Porto de Menethil, que fica no Pantanal.', 0),
(25801, 'ptBR', 'Garras das profundezas', 'Colete a Cabeça de Comilão e mate 12 Murlocs Guelrazul de qualquer tipo.', 'Os murlocs estão saindo das águas profundas e construindo aldeias na costa. Eles estão atormentando os pescadores e comerciantes. Temos que dar um fim nisso.$B$BUm deles, o Comilão, costuma se juntar a outros murlocs guelrazul para saquear os comerciantes na estrada. Depois, eles sempre fogem para as cabanas por perto. Os nossos comerciantes estão em perigo, e estamos dispostos a pagar a quem puder garantir a segurança deles.$B$BO Comilão ronda a baía do rio a norte daqui. Encontre-o, mate todo o bando e traga-me a cabeça dele.', '', 'Murlocs Guelrazul mortos', '', '', '', '', 'Comilão', '', '', 'Fale novamente com Carlos Borba no Porto de Menethil, que fica no Pantanal.', 0),
(25802, 'ptBR', 'O que é nosso de direito', 'Vasculhe os caixotes e barris nos acampamentos dos murlocs na costa.', 'Pouco tempo atrás, um navio mercante, o Princesa Cega, foi atacado por murlocs. O navio não sofreu avarias, mas a maior parte da carga, que continha até uma estatueta muito valiosa de Terenas Menethil, foi roubada pelas criaturas. Queremos a estatueta de volta.$B$BProcure caixotes, barris e outros indícios da carga roubada nas cabanas dos murlocs na costa. Encontre a estatueta de Menethil e traga-a de volta.', '', '', '', '', '', '', '', '', '', '', 0),
(25803, 'ptBR', 'A busca continua', 'Procure a Estatueta de Menethil.', 'Você vasculha o conjunto inteiro de cabanas dos murlocs e não encontra nem sinal da Estatueta de Menethil.$B$BTalvez uma das duas cabanas ao norte e ao nordeste tenha alguma pista.', '', '', '', '', '', '', '', '', '', '', 0),
(25804, 'ptBR', 'Vasculhe mais cabanas', 'Continue vasculhando as cabanas dos Murlocs em busca da Estatueta de Menethil.', 'Mesmo depois de uma busca completa, a aldeia murloc não oferece pista alguma.$B$BVocê tem certeza de que a próxima pista que encontrar será proveitosa.$B$BA estatueta de Menethil deve estar em uma das cabanas ao norte!', '', '', '', '', '', '', '', '', '', '', 0),
(25805, 'ptBR', 'Devolva a estatueta', 'Leve a Estatueta de Menethil a Carlos Borba no Porto de Menethil, que fica no Pantanal.', 'Depois de tirar o barril do lamaceiro e abri-lo, você encontra um artigo de prata no meio da palha. É uma imagem de um jovem paladino de cabelos longos com um martelo erguido.$B$BDeve ser a estatueta de Menethil! Leve-a a Carlos Borba no Porto de Menethil.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Carlos Borba no Porto de Menethil, que fica no Pantanal.', 0),
(25806, 'ptBR', 'Antes quatro-olhos do que morto', 'Mate 12 Assassinos de Krom\'gar.', 'Ah, a Liga dos Exploradores... mas que grande grupo de idiotas... Como se não bastassem os fantasmas taurens no nosso encalço, a Liga dos Exploradores abriu uma passagem para a principal base da Horda nas Torres de Pedra, a Fortaleza Krom\'gar.$B$BAgora, temos assassinos de Krom\'gar matando silenciosamente todos na mina.$B$BEu preciso que você entre lá e mate-os.$B$BAh, quase esqueci de dar esses óculos a você. Coloque-os imediatamente. Eles tornarão os assassinos furtivos na mina claramente visíveis.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Tenente Paulson nas Entranhas da Terra, que ficam na Cordilheira das Torres de Pedra.', 0),
(25807, 'ptBR', 'O despertar da anciã', 'Use o Incenso do Arauto diante do Ovo de Aviana no Santuário de Aviana.', 'Estou convencida de que você é o arauto de Aviana, $n. Foi você quem primeiro a viu e resgatou a essência dela das garras do dragão.$b$bSim, acredito que Aviana renascerá em nosso mundo. E você terá a honra de conduzi-la por esse limiar.$b$bPegue este incenso e queime-o diante do ovo de Aviana na sala logo acima de mim.$b$bA anciã aguarda, $n. Nossa libertação chegou!', '', 'Incenso do Arauto queimado', '', '', '', '', '', '', '', 'Fale com Aviana dentro do Santuário dela no Monte Hyjal.', 0),
(25808, 'ptBR', 'Esse negócio está ligado?', 'Mate a Mestre Assassina Kel\'istra.', '<O Gnomofone estala com energia. Você consegue ouvir o Tenente Paulson do outro lado.>$B$BPorcaria gnômica idiota... Tem ALGUÉM aí? $n, você está aí?$B$BTalvez $Gele:ela; tenha morrido.$B$BEscute, se você ainda conseguir me ouvir, acabamos de saber que uma mestre assassina da Horda está nas minas, comandando os demais assassinos. Encontre-a, mate-a e apresente-se novamente a mim.$B$BPaulson desliga.', '', '', '', '', '', '', 'Tenente Paulson', '', '', 'Fale novamente com o Tenente Paulson nas Entranhas da Terra, que ficam na Cordilheira das Torres de Pedra.', 0),
(25809, 'ptBR', 'Não deixe ninguém para trás!', 'Resgate 8 Mineradores Assustados.', 'Monstros da Horda!$B$B<O cabo Wocard cospe.>$B$BOlhe para este lugar! Eles exterminaram inocentes! Civis!$B$BOuça, $n, você tem que nos ajudar. Vá às Entranhas da Terra e procure por mineradores sobreviventes. Se eles ainda estiverem vivos, devem estar apavorados! Verifique os cantos e as fendas da mina. Talvez nos carrinhos da mina! É certo que alguns estejam vivos e escondidos.', '', 'Mineradores Assustados resgatados', '', '', '', '', '', '', '', 'Fale novamente com o Cabo Wocard nas Entranhas da Terra, que ficam na Cordilheira das Torres de Pedra.', 0),
(25810, 'ptBR', 'Fogo na incubadora!', 'Atravesse o portal de chamas no meio da Ardilanta, no Monte Hyjal. Em seguida, fale com Farden Garrafiada.', '$n! Choluna estava certa: a deusa voltou! Um milagre entre nós.$B$BVocê matou a dragonesa do crepúsculo, a Sethria, mas mesmo assim nós não conseguimos encontrar todos os ovos que as harpias entregaram para ela. Eu e Tessália descobrimos que os ovos estão em uma grande incubadora nas Terras do Fogo. Aviana não poderá acompanhar você porque a incubadora está em outro mundo.$B$BVoe para sul e atravesse o portal de chamas no meio do vale. O Farden Garrafiada já foi enviado para lá e aguarda você do outro lado.', '', '', '', '', '', '', '', '', '', 'Atravesse o portal de chamas no meio da Ardilanta, no Monte Hyjal. Em seguida, fale com Farden Garrafiada.', 0),
(25811, 'ptBR', 'Acabando com ela', 'Plante o Feixe de Dinamite na Primeira Viga, na Segunda Viga, na Terceira Viga e na Quarta Viga.', 'Para desativar esta mina, você precisará explodir as vigas de sustentação. Posso fornecer os explosivos necessários, mas você terá que passar pelos assassinos de Krom\'gar para alcançar todos os suportes.$B$BA boa notícia, se é que há alguma, é que sempre marcamos nossas vigas de sustentação com um grande ‘‘X\'. Procure as marcas e plante esta dinamite perto delas. Quando você tiver plantado todas as dinamites, volte aqui para que eu ative os explosivos.$B$BCabum!', '', 'Plantar Explosivos na Primeira Viga', 'Plantar Explosivos na Segunda Viga', 'Plantar Explosivos na Terceira Viga', 'Plantar Explosivos na Quarta Viga', '', '', '', '', 'Fale novamente com McGee Pé-de-Aço nas Entranhas da Terra, que ficam na Cordilheira das Torres de Pedra.', 0),
(25812, 'ptBR', 'Espeleologia', 'Fale com o Recruta Pollard na Gruta Densanévoa.', 'Depressa, $n!$b$bVá logo para aquela caverna.$b$bIremos atrás de você para garantir que você não está sendo seguid$go:a;.', '', '', '', '', '', '', '', '', '', '', 0),
(25813, 'ptBR', 'Chamado dos ventos', 'Mate Whrrrl.', 'O Clamacéus Vrakthris, aquele centauro velhinho e ranzinza, havia falado de um grande espírito do ar que os centauros veneram. O último passo para dominarmos a Serra é acabar com ele.$B$BUma vez eu os vi soprando um grande berrante no topo daquela colina. Então, apareceu um elemental do ar que deu instruções a eles e depois sumiu.$B$BSopre aquele berrante, $n.', '', 'Sopre o berrante', '', '', '', '', 'Whrrrl', '', '', 'Fale novamente com Crazzle Molavivaz na Serra do Casco Fendido, que fica em Mil Agulhas.', 0),
(25814, 'ptBR', 'Chamado dos ventos', 'Mate Whrrrl.', 'O Clamacéus Vrakthris, aquele centauro velho e ranzinza, tinha falado de um grande espírito do ar que os centauros veneram. O que falta pra gente dominar a Serra é acabar com ele.$B$BUma vez eu vi os caras soprarem um berrante grande no topo daquela colina. Aí apareceu um elemental do ar que deu instruções a eles e depois sumiu.$B$BAgora você vai lá e sopra aquele berrante, $n.', '', 'Sopre o berrante', '', '', '', '', 'Whrrrl', '', '', 'Fale novamente com Riznek na Serra do Casco Fendido, que fica em Mil Agulhas.', 0),
(25815, 'ptBR', 'A terceira frota', 'Obtenha o Hidromel de Simonez na adega da estalagem do Porto de Menethil.', 'Eu era Primeiro Oficial do Senhora das Ondas, o navio de linha da Terceira Frota de Kul Tiraz, a Frota Condenada. Condenada porque, na última viagem, foi atacada pelos Dragões Vermelhos... Dragões controlados por orcs!$B$BNão tivemos a mínima chance contra o fogo deles... A nossa frota inteira foi queimada e afundou perto da costa. Sou o único sobrevivente desses pobres navios...$B$BTraga o meu hidromel, $c. Está na adega da estalagem. Tentei afastá-lo de mim, mas não aguento mais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Primeiro Oficial Simonez no Porto de Menethil, que fica no Pantanal.', 0),
(25816, 'ptBR', 'Condenado a vagar', 'Converse com o fantasma do Primeiro Oficial Expedito.', '<Animado, Simonez continua o conto...>$B$BSou o único sobrevivente da Terceira Frota de Kul Tiraz, que teve um fim trágico e naufragou perto da costa ao norte. Em um dos navios, havia um grande e terrível tesouro escondido. O poder misterioso dele mantém as almas dos meus irmãos aprisionadas dentro dos cascos apodrecidos dos navios.$B$BSou assombrado por eles dia e noite, noite e dia. O Primeiro Oficial Expedito fica chamando o meu nome! Era para ele estar morto! Eu imploro, $n! Encontre-o perto dos navios naufragados e... peça para ele me deixar em paz!', '', '', '', '', '', '', '', '', '', '', 0),
(25817, 'ptBR', 'A tripulação amaldiçoada', 'Mate 5 Marinheiros Amaldiçoados e 5 Fuzileiros Amaldiçoados na Frota Perdida.', 'Os marinheiros da Terceira Frota estão amaldiçoados e fadados a vagar para sempre em grande agonia pelo litoral. A angústia de Simonez está ligada à nossa. Enquanto sofrermos, ele também sofrerá.$B$BAcabe com o sofrimento dos espíritos dos meus amigos. Elimine os fantasmas deste plano e depois fale comigo novamente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Primeiro Oficial Expedito na Frota Perdida, que fica no Pantanal.', 0),
(25818, 'ptBR', 'O fim da maldição', 'Obtenha a Chave do Cofre do Intrépido do Capitão Halyndor.', 'Só um ajuste de contas quebrará a maldição. O capitão Halyndor instigou em todos nós a cobiça por um artefato proibido, o Olho de Paleth. O espírito dele ainda é assolado pela cobiça e mantém guarda no cofre do navio que outrora comandava, o Intrépido.$B$BExtermine a alma daquele que nos amaldiçoou, $c. Derrote o Capitão, obtenha a chave dele e leve o Olho de Paleth para longe daqui.', '', '', '', '', '', '', '', '', '', 'Procure o Cofre Trancado do Intrépido no Pantanal.', 0),
(25819, 'ptBR', 'Olho de Paleth', 'Leve o Olho Maldito de Paleth a Glorin Testaço no Porto de Menethil, que fica no Pantanal.', 'Ao abrir o baú, você se depara com um orbe enegrecido que palpita com uma luz macabra. Deve ser o Olho de Paleth, que amaldiçoou as almas dos marinheiros.$B$BÉ preciso purificar tanta corrupção. Talvez um sacerdote no Porto de Menethil possa ajudar.', '', '', '', '', '', '', '', '', '', '', 0),
(25820, 'ptBR', 'O meu filho é uma joia de moço', 'Mate 10 Rasgatanas da Baía.', 'O meu filho Gimlok é a luz da minha vida. O meu coração se alegra quando ele brinca com outras crianças.$B$BMas não consigo deixar de me preocupar com os tubarões que ficam a poucos metros da baía. Se um deles nadar até aqui...$B$BNão quero nem imaginar! Por favor, $r! Você já deve ter passado por situações muito piores. Você não quer matar alguns desses tubarões cretinos pra gente? Nem que sejam só alguns...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Derina Patego no Porto de Menethil, que fica no Pantanal.', 0),
(25821, 'ptBR', 'Um trabalho especial', 'Apresente-se ao Comandante de Força Valen na Base da Expedição Guardanorte, que fica na Cordilheira das Torres de Pedra.', 'Você fez um trabalho admirável aqui, $n. O comandante de Força Valen percebeu isso e requisitou sua presença imediatamente. Ele tem uma missão especial para você, uma que esperamos que vá pôr um grande ponto final na incursão da Horda nas Torres de Pedra.', '', '', '', '', '', '', '', '', '', '', 0),
(25822, 'ptBR', 'Armamentos para a guerra', 'Colete 10 Caixotes de Armas da Aliança.', 'Preciso que você se arrisque mais uma vez, $n. A leste, você encontrará uma escavação, rica em minérios, que foi recentemente tomada pela Horda. No local, há caixotes com armamento nosso espalhados por todo canto. Como a Horda invadiu o local há pouco tempo, é improvável que tenham encontrado todos os nossos suprimentos.$B$BVá lá e arranje umas armas para os nossos amigos do Temível Totem!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Força Valen na Base da Expedição Guardanorte, que fica na Cordilheira das Torres de Pedra.', 0),
(25823, 'ptBR', 'A impiedosa Horda', 'Mate 12 inimigos integrantes da Horda nas Terras Escavadas.', 'Apesar de ser da maior importância que você obtenha os caixotes de armas imediatamente, precisamos que as Terras Escavadas, a leste, estejam livres da Horda. Se vamos abrir uma linha de abastecimento para nossos aliados do Temível Totem, precisaremos de acesso irrestrito à escavação.$B$BMate qualquer guerreiro da Horda que cruzar seu caminho nas Terras Escavadas, $n. Pela glória da Aliança!', '', 'Inimigos integrantes da Horda mortos nas Terras Escavadas', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Força Valen na Base da Expedição Guardanorte, que fica na Cordilheira das Torres de Pedra.', 0),
(25824, 'ptBR', 'Relato de missão', 'Fale com o Recruta Pollard sobre a missão dele.', 'Este soldado estava à beira da morte, mas temo que não tenhamos tempo para esperarmos ele se recuperar totalmente. Ele tem informações que precisamos ter, desesperadamente.$b$bSeja paciente com ele, mas faça-o falar até que saibamos tudo o que pudermos.$b$bCom sorte, pode ser que descubramos o que estamos combatendo...', '', 'Recruta Pollard interrogado', '', '', '', '', '', '', '', '', 0),
(25825, 'ptBR', 'Entregando a mercadoria', 'Entregue o Barril de Petróleo a Xabu Latafuso no Barcódromo do Xabu e do Relé, que fica em Mil Agulhas.', 'Ok, $n. Preciso que você leve este barril de petróleo para o Xabu lá no Barcódromo. E conte a ele as boas novas!', '', '', '', '', '', '', '', '', '', '', 0),
(25826, 'ptBR', 'Entregando a mercadoria', 'Entregue o Barril de Petróleo a Relé no Barcódromo do Xabu e do Relé, que fica em Mil Agulhas.', 'Beleza, $n. Preciso que você leve esse barril de petróleo pro Relé lá no Barcódromo. E aproveita e conta pra ele as novidades!', '', '', '', '', '', '', '', '', '', '', 0),
(25829, 'ptBR', 'Missão de rastreamento – Centro de Goldrinn completo', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(25830, 'ptBR', 'O último erudito', 'Encontre Nordu, um Anciente da Tradição, na Ardilanta, que fica no Monte Hyjal.', 'Você despertou os anciãos, $n, mas o espírito das florestas, Aessina, ainda não se manifestou. Com a ajuda dela, é possível virar a maré a nosso favor e desfazer o mal que o Martelo do Crepúsculo causou.$B$BTalvez haja alguém para nos ajudar. A mais velha das árvores, Nordu, há milhares de anos está no meio do que agora conhecemos como Ardilanta. A sabedoria de Nordu é tão antiga quanto esta montanha. Se a velha árvore ainda estiver viva, talvez consiga despertar Aessina... Encontre Nordu.', '', '', '', '', '', '', '', '', '', 'Encontre Nordu, um Anciente da Tradição, na Ardilanta, que fica no Monte Hyjal.', 0),
(25832, 'ptBR', 'Novo encontro com Aviana', 'Fale novamente com Aviana no Santuário de Aviana, no Monte Hyjal.', '$n, você fez tudo o que podia aqui. Essa caverna está quase desmoronando!$B$BVou reunir os últimos corcéis alados e cuidar para que o portal de chamas seja lacrado.$B$BVá na frente e avise à Aviana que essa incubadora abominável acabou!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Aviana no Santuário de Aviana, no Monte Hyjal.', 0),
(25834, 'ptBR', 'A batata deles está assando...', 'Fale com o "Cuca" MacMolhofraco na Base da Expedição Guardanorte, que fica na Cordilheira das Torres de Pedra.', 'Você consegue escutá-los lutando lá embaixo, $n? Parece que os taurens do clã Temível Totem não são mais vistos com bons olhos pela Horda. Não sei o que aconteceu, mas podemos usar isso a nosso favor.$B$BProvidenciarei uma reunião com o embaixador dos Temível Totem. Preciso que você prepare uma oferta de paz.$B$B<O comandante de força Valen aponta para o "Cuca".>$B$BFale com o "Cuca", $n. Ele já tem as instruções do que precisamos fazer.', '', '', '', '', '', '', '', '', '', '', 0),
(25835, 'ptBR', 'Liberdade para a Aldeia Vento Livre!', 'Fale com Quentin na Aldeia Vento Livre, que fica em Mil Agulhas.', 'Infelizmente, é hora de dizer adeus. Como dizem: vem fácil, vai rápido. Ou algo assim.$B$BTanto faz! Você fez um ótimo trabalho por aqui, $Gmeu amigo:minha amiga;, mas Quentin e os elfos noturnos na Aldeia Vento Livre, a noroeste, vêm nos pedindo ajuda urgente na luta contra os Temível Totem.$B$BSe você quiser saber, acho que é uma causa perdida, mas... Talvez, com a sua ajuda, eles venham a conseguir.', '', '', '', '', '', '', '', '', '', '', 0),
(25836, 'ptBR', 'Liberdade para a Aldeia Vento Livre!', 'Fale com Thalia Couro Âmbar na Aldeia Vento Livre, que fica em Mil Agulhas.', 'Bem, chegou a hora de a gente se separar, pelo menos por enquanto.$B$BOs taurens da Aldeia Vento Livre precisam da sua ajuda na luta contra o clã Temível Totem!$B$BVocê fez tanto pela gente que aposto que vai se tornar $Gum:uma; grande $Gherói:heroína; em muito pouco tempo!', '', '', '', '', '', '', '', '', '', '', 0),
(25837, 'ptBR', 'Uma oferta de paz adequada', 'Colete 6 Ovos de Águia de Kalimdor, 8 Ancas de Carneiro e 10 pedaços de Queijo da Ravina da Avalanche.', 'Pra preparar uma oferta de paz que se preze, eu vou precisar do seguinte:$B$BOvos de águia de Kalimdor, pegos do ninho. Eles estão espalhados pela floresta no oeste.$B$BAncas de carneiro! Tu vai achar boas ancas nos carneiro das Torres de Pedra.$B$BO último ingrediente vai ser um pouco mais difícil de encontrar, mas tu precisa dele para preparar o carneirete. Tu segue pro sudoeste, vai na Garganta da Avalanche e encontra as cavernas dos kobolds. Então tu mata os kobold e pega o queijo especial deles.$B$BTraz tudo para cá e eu te preparo uma obra prima!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o "Cuca" MacMolhofraco na Base da Expedição Guardanorte, que fica na Cordilheira das Torres de Pedra.', 0),
(25838, 'ptBR', 'Ajuda da Garagem do Gradaço', 'Fale com Delber Manigiro na Garagem do Gradaço.', 'Com sua ajuda, conseguimos avançar sobre o Refúgio Jubafria. Nossas tropas em breve conseguirão enfraquecer as reservas dos Jubafria, deixando a vila troll exposta ao ataque.$B$BÉ aí que entra em campo a equipe de operações secretas de Gnomeregan, cujos estrategistas desenvolveram uma técnica para posicionar tropas atrás das linhas inimigas sem chamar a atenção dos Jubafria. Vá até a Garagem do Gradaço, a nordeste da cidade, e fale com Delber Manigiro. Ele tem mais informações sobre a operação.', '', '', '', '', '', '', '', '', '', 'Fale com Delber Manigiro na Garagem do Gradaço.', 0),
(25839, 'ptBR', 'O lançador pessoal super seguro', 'Use o Lançador Pessoal Super Seguro para entrar em posição no Refúgio Jubafria.', 'Como o cataclismo deixou os inimigos bem mais perto da nossa porta, o chefe de operações secretas de Gnomeregan pediu que eu construísse um dispositivo para despachar equipes rápida e discretamente para qualquer parte de Dun Morogh.$B$BPois veja o incrível Lançador Pessoal Super Seguro!$B$BCom partida elétrica e um sistema de paraquedas AUT de série – "acionamento ultra tardio", para os leigos – essa belezinha vai te deixar no front em dois tempos. É só pular para dentro e bom voo! Blate Gaxetabamba espera por você na zona de lançamento.', 'Use o Lançador Pessoal Super Seguro para entrar em posição no Refúgio Jubafria.', '', '', '', '', 'Use o Lançador Pessoal Super Seguro para entrar em posição no Refúgio Jubafria.', '', '', '', 'Fale com Blate Gaxetabamba no Refúgio Jubafria.', 0),
(25840, 'ptBR', 'Como minar a resistência', 'Mate Battok, o Berserker, e 5 Guerreiros Jubafria no Refúgio Jubafria.', 'O chefe Jubafria foi morto no primeiro massacre trogg, e desde então a liderança daquele clã foi assumida por um guerreiro muito respeitado. Battok, o Berserker, organizou a retirada dos Jubafria, a construção da nova vila e os ataques contra Kharanos e os montanhistas.$B$BSe conseguirmos neutralizar Battok, toda a organização dos Jubafria desmoronará, deixando o caminho livre para os montanhistas resgatarem os sobreviventes. Battok está na aldeia, que fica a leste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Blate Gaxetabamba no Refúgio Jubafria.', 0),
(25841, 'ptBR', 'O perigo vem de cima', 'Use o Sinal de Fumaça para chamar ataques aéreos contra os limites norte e sul do Refúgio Jubafria.', 'Os técnicos de Delber estão trabalhando dia e noite nos preparativos para o ataque. Além de construir e programar o lançador pessoal, a equipe preparou a esquadrilha aérea de operações secretas para um ataque contra o Refúgio Jubafria. Eles estão esperando pelo sinal para começar os ataques.$B$BLeve este sinalizador e dispare-o perto dos prédios nos limites norte e sul da vila. As máquinas voadoras farão um ataque rápido e certeiro nos locais marcados.', '', 'Ataque ao lado norte do Refúgio Jubafria', 'Ataque ao lado sul do Refúgio Jubafria', '', '', '', '', '', '', 'Fale novamente com Blate Gaxetabamba no Refúgio Jubafria.', 0),
(25842, 'ptBR', 'Bombeiro', 'Mate 5 Atormentadores de Fogo para mantê-los afastados de Nordu.', 'É muito... tarde para mim. Queimado até o cerne. Eu vivi por eras... Ainda sim, meu fim parece repentino.$B$BUm nova vida pode brotar da antiga. Eu ainda tenho sabedoria para transmitir. Por favor... Não deixe que eu seja levado antes de terminar meu trabalho.$B$BMantenha os atormentadores afastados... só um pouco mais, $c.$B$BDê-me alguns minutos e eu lhe concederei mil vidas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nordu na Ardilanta, que fica no Monte Hyjal.', 0),
(25843, 'ptBR', 'A vingança de Tortolla', 'Fale com Tortolla na Terra Queimada, que fica no Monte Hyjal.', 'A montanha floresceu novamente! Se agirmos com rapidez, poderemos aproveitar bem a vantagem.$B$BNosso velho amigo Tortolla, a tartaruga anciã, já está indo para lá. No ritmo dele, é claro...$B$BEncontre-se com o Tortolla a leste daqui, no início do caminho que leva às terras queimadas. Nossas fortalezas daquela região foram tomadas pelo inimigo no início da campanha, mas talvez agora seja possível reconquistá-las.', '', '', '', '', '', '', '', '', '', 'Fale com Tortolla na Terra Queimada, que fica no Monte Hyjal.', 0),
(25844, 'ptBR', 'Saciando a fera selvagem', 'Entregue a Oferenda Carnuda a Ton Arco de Vento na Aldeia do Temível Totem, que fica na Cordilheira das Torres de Pedra.', 'Tu ouviu o comandante, $n. Entrega a minha oferenda perfeita ao embaixador do Temível Totem! Ele e a equipe dele estão esperando no final do caminho de sudeste.$B$BCom isso, com certeza vamos ganhar a confiança do chefe deles!', '', '', '', '', '', '', '', '', '', '', 0),
(25845, 'ptBR', 'Termos de serviço', 'Entregue os Termos de Serviço Temível Totem ao Comandante de Força Valen na Base da Expedição Guardanorte, que fica na Cordilheira das Torres de Pedra.', 'Os Temível Totem precisam de armas! A Horda, fortalecida pelo chefe guerreiro e auxiliada pelos novos aliados goblins, acumulou um arsenal poderoso. Nossos armamentos simplesmente não são páreo para o poder de fogo deles. Forneça armas fortes aos Temível Totem e trabalharemos juntos para destruir a Horda!$B$BEstas são as nossas exigências! Abasteça o Temível Totem e lutaremos pela Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(25846, 'ptBR', 'Grundig Nuvem Negra, chefe dos Temível Totem', 'Entregue os Caixotes de Armas da Aliança a Grundig Nuvem Negra na Aldeia do Temível Totem, que fica na Cordilheira das Torres de Pedra.', 'O chefe dos Temível Totem aguarda sua chegada, $n. Leve os caixotes de armas com você e siga rumo à Aldeia do Temível Totem, ao sul daqui.$B$BBoa sorte, $n. Caso algo aconteça com você, notificarei pessoalmente seus parentes e farei com que o rei Wrynn saiba o que você fez pela Aliança.', '', '', '', '', '', '', '', '', '', '', 0),
(25847, 'ptBR', 'Supremacia do Temível Totem', 'Use o Caixote de Armas da Aliança para armar 12 dos Temível Totem.', 'Por todo o Vale Matagrande, você encontrará guerreiros do Temível Totem sendo atacados pela Horda. Os exércitos de Grito Infernal não mostram piedade ou compaixão, matando tudo que veem pela frente.$B$BMas chega disso! Leve os armamentos que você nos trouxe e encontre os Temível Totem que estão lutando contra a Horda. Dê-lhes as armas da Aliança e assista enquanto eles destroem seus oponentes! Vá. Há muito trabalho a ser feito, aliad$Go:a;.', '', 'Temível Totem armados', '', '', '', '', '', '', '', 'Fale novamente com Grundig Nuvem Negra na Aldeia do Temível Totem, que fica na Cordilheira das Torres de Pedra.', 0),
(25848, 'ptBR', 'Queda', 'Mate os generais da Horda na Aldeia Apareje e recupere a Insígnia do General da Horda.', 'Já era tarde demais quando fomos informados de que Grito Infernal havia enviado outro orc mag\'har para supervisionar as tropas da Horda na parte sul das Torres de Pedra. Da Aldeia Apareje só restam as cinzas, e todos os Temível Totem que lá estavam morreram incinerados.$B$BAgora, a Horda está com quatro de seus generais mais temíveis comandando a batalha pelo Vale Matagrande, incluindo o mag\'har, general Glubgok.$B$BVocê deve ir para o sul, até as ruínas da Aldeia Apareje, e matar os generais. ESSA é a hora de determos a Horda! Volte a mim com a marca deles!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Grundig Nuvem Negra na Aldeia do Temível Totem, que fica na Cordilheira das Torres de Pedra.', 0),
(25849, 'ptBR', 'A revolução dos fósseis', 'Colete 20 Ossos Fossilizados dos Fósseis Vivos.', 'Presta atenção, $gguri:guria;. Qualquer arqueólogo que se preze sabe dos riscos da profissão. Se um arqueólogo não desenterrar um mal antigo e nem for amaldiçoado por espíritos maléficos ao menos uma vez na carreira, então não está fazendo o serviço direito!$B$B$n, os arqueólogos de verdade sabem que uma coisa tão simples como ossos fossilizados se transformarem em criaturas esqueléticas não é motivo para parar o trabalho.$B$BContinuo precisando dos ossos dos fósseis. Pegue os dos monstros fósseis que estão perambulando pela escavação e traga-os aqui. Você será bem $grecompensado:recompensada;.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Prospector Whelgar no Refúgio de Whelgar, que fica no Pantanal.', 0),
(25850, 'ptBR', 'A terra contra-ataca!', 'Mate 7 Elementais Paleolíticos.', 'Caso não tenha percebido, o Pantanal está completamente enlouquecido. Inundações, terremotos... Para piorar ainda mais, até a terra resolveu ficar rebelde.$B$BNunca imaginei que a própria escavação fosse nos atacar. Blocos e mais blocos gigantes de terra caem tentando esmagar os anões distraídos.$B$BVocê é $gum:uma; $r jovem e forte... Pode fazer a terra botar a cabeça no lugar?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ormer Trançaferro no Refúgio de Whelgar, que fica no Pantanal.', 0),
(25851, 'ptBR', 'Dança com os Temível Totem', 'Apresente-se ao Comandante de Força Valen na Base da Expedição Guardanorte, que fica na Cordilheira das Torres de Pedra.', 'Volte agora a seu líder e conte a ele tudo que você fez pelos Temível Totem. Diga a ele que a Aliança pode cruzar livremente nossas fronteiras.', '', '', '', '', '', '', '', '', '', '', 0),
(25852, 'ptBR', 'Tudo limpo', 'Apresente-se ao Comandante Tomas Walpole no Desfiladeiro das Torres de Pedra, que fica nos Sertões Meridionais.', 'Arrume seu equipamento, $n. É chegado o momento de juntar-se ao resto das forças de Guardanorte nos Sertões Meridionais. Sua primeira missão nos Sertões Meridionais deve ser bem simples e direta.$B$BHá dois dias, recebemos um pedido de socorro do comandante Walpole. Ele e seu batalhão estão encurralados no Desfiladeiro das Torres de Pedra, logo ao lado do Posto da Honra. A Horda os cercou por todos os lados! Vá até lá e ajude-os! Transmitirei as notícias sobre nossa aliança com os Temível Totem ao comando de Guardanorte.', '', '', '', '', '', '', '', '', '', '', 0),
(25853, 'ptBR', 'Minhas queridas ferramentas', 'Colete 6 Ferramentas do Arqueólogo.', 'Eu sou a responsável pelo fornecimento de materiais para a escavação. Até que não é tão ruim assim, mas ficar indo de um lugar para o outro não é bem o que eu queria!$B$BOs arqueólogos precisam de ferramentas. Não dá para desenterrar relíquias antigas de valor inestimável na força do braço. Você vai entrar na escavação de novo, não vai? Pode trazer as ferramentas que ficaram lá?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Marina Tecepedra no Refúgio de Whelgar, que fica no Pantanal.', 0),
(25854, 'ptBR', 'O nome dele vai ser Costelinha', 'Colete 6 Ovos Vibrantes de Raptor.', 'Você já ouviu falar de uns raptores que são tão inteligentes que podem ser domesticados? É verdade! Eu já vi alguns sendo domados por caçadores.$B$BSabe de uma coisa? Confesso que a companhia da Wenna não basta pra aliviar a solidão... Ter um ajudante me deixaria mais feliz. Um bebê raptor seria ideal!$B$BVocê está matando os adultos, não é? Pode trazer alguns ovos chocados? Dá para saber se já estão para abrir pela vibração deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fradd Entrós na Estação Entrós.', 0),
(25855, 'ptBR', 'Trecos e tralhas', 'Encontre 7 Engenhocas Entrós.', 'As minhas peças para projetos de engenharia estavam acabando muito rápido, mas só entendi o motivo outro dia: os gnolls Pelemusgo estão roubando tudo!$B$BNão faço a mínima ideia do que eles querem fazer com elas, mas preciso dos meus trecos de volta. A essa altura elas devem estar todas espalhadas pelo pântano, mas se você vir alguma por aí, pode trazer pra mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fradd Entrós na Estação Entrós, que fica no Pantanal.', 0),
(25856, 'ptBR', 'Couro de crocolisco', 'Colete 10 Couros de Crocolisco do Pântano dos Crocoliscos do Pantanal.', 'Esfolei crocoliscos por anos no pantanal, $c, mas agora as coisas mudaram.$B$BNão quero ficar alugando ninguém, mas a inundação do Cataclismo no Porto de Menethil destruiu a minha casa. A patroa e as crianças estão sem lugar para ficar. Preciso arrumar dinheiro para conseguir um teto para nós.$B$BEsfolei crocoliscos até não aguentar nem me mexer, mas ainda preciso de mais peles para vender. Traga algumas para mim e farei questão de pagar por elas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Iago Halberque na Estação Entrós, que fica no Pantanal.', 0),
(25857, 'ptBR', 'Atrás do Garganto', 'Mate Garganto e colete o Pelego do Garganto.', 'Confesso que fiquei tentado a ir atrás do maior crocolisco de todos, o Garganto. Só a pele dele seria suficiente para tirar minha família da miséria.$B$BMas logo criei juízo. Um erro e posso perder a perna ou até a vida. O que seria da patroa e das crianças? Continuariam sem casa e, pior, sem pai.$B$BNão posso ser orgulhoso agora, pois a segurança da minha família vem sempre em primeiro lugar. Por favor, $c, cace o Garganto para mim. Ele fica em um charco sombrio ao norte à espera da próxima presa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Iago Halberque na Estação Entrós.', 0),
(25858, 'ptBR', 'Por ordens de Lady Sira\'kess', 'Fale com o Senhor das Profundezas Zin\'jatar, com a Lady Sira\'kess e com o Feitor Idra\'kess.$B$BEssa missão faz parte da visão da Dama Guerreira Naz\'jar. Caso necessário, use a Lâmina da Dama Guerreira Naz\'jar em um foco temporal para voltar à visão.', 'A Lady Sira\'kess deu início aos preparativos para o ritual de evocação, mas o Cadinho de Nazsharin foi roubado. Com certeza os kvaldir o levaram quando fugiram para águas mais rasas.$B$BFale com os líderes das castas para montar um grupo de batalha e lidere-o para retomar o artefato na Crista Biel\'aran a leste.$B$BConfio em você, Dama Guerreira, pois você nunca falhou em nenhuma das missões que lhe dei. Assim como sou devotada à Rainha, você deve ser devotada a mim. Vá com as minhas bênçãos.', '', 'Falar com o Senhor das Profundezas Zin\'jatar', 'Falar com a Lady Sira\'kess', 'Falar com o Feitor Idra\'kess', '', '', '', '', '', 'Encontre o Espreitador das Profundezas Azjentus na Crista Biel\'aran a leste das Ruínas de Vashj\'ir, do outro lado do Promontório Partido.', 0),
(25859, 'ptBR', 'Passou, morreu', 'Mate 20 Kvaldir na Crista Vraikal.$B$BEssa missão faz parte da visão da Dama Guerreira Naz\'jar. Caso necessário, use a Lâmina da Dama Guerreira Naz\'jar em um foco temporal para voltar à visão.', 'Sei que você, assim como nossa venerada dama, às vezes sofre de lamentáveis surtos de piedade. Porém, tenho um conselho a respeito dessa bondade. Os kvaldir são orgulhosos e revidarão nossos ataques se não os destruirmos completamente. Assim, mate todos que encontrar sem piedade nenhuma!$B$BInfelizmente, minha missão é garantir que nenhum deles retorne à cidade, então quem vai ficar com toda a diversão é você. E é claro que vou ficar na torcida.', '', 'Kvaldir da Crista Vraikal mortos', '', '', '', '', '', '', '', 'Fale novamente com o Espreitador das Profundezas Azjentus na Crista Biel\'aran.', 0),
(25860, 'ptBR', 'A qualquer custo', 'Mate 20 Kvaldir que estão atacando o Templo de Quel\'Durmar para impedir o ritual.$B$BEssa missão faz parte da visão da Dama Guerreira Naz\'jar. Caso necessário, use a Lâmina da Dama Guerreira Naz\'jar em um foco temporal para voltar à visão.', 'Começaremos o ritual imediatamente, e é sua responsabilidade garantir que ninguém nos interrompa.$B$BAcabe com qualquer kvaldir que entrar no templo e certifique-se de que minhas sacerdotisas fiquem vivas para concluir o ritual a qualquer custo!', '', 'Kvaldir atacantes mortos', '', '', '', '', '', '', '', 'Fale novamente com a Lady Sira\'kess no nível superior do Templo de Quel\'Durmar.', 0),
(25861, 'ptBR', 'Dando o exemplo', 'Traga um Sumo Xamã Kvaldir à presença do Carrasco Varathress.$B$BEssa missão faz parte da visão da Dama Guerreira Naz\'jar. Caso necessário, use a Lâmina da Dama Guerreira Naz\'jar em um foco temporal para voltar à visão.', 'Os sumos xamãs estão nos prédios próximos, cantando e nos provocando, mas sem ousar se aproximar de mim. Parece que os kvaldir são corajosos e fortes somente quando estão escondidos, e não passam de um pequeno incômodo em meio às ondas.$B$BVim aqui trazendo uma mensagem. Se vossa senhoria dispuser de tempo, traga um sumo xamã à minha presença para entregar esta mensagem para ele e seu povo.', '', 'Sumo Xamã Kvaldir levado à presença do carrasco', '', '', '', '', '', '', '', 'Fale com o Carrasco Varathress na Crista Biel\'aran.', 0),
(25862, 'ptBR', 'Propriedade roubada', 'Recupere o Cadinho de Nazsharin.$B$BEssa missão faz parte da visão da Dama Guerreira Naz\'jar. Caso necessário, use a Lâmina da Dama Guerreira Naz\'jar em um foco temporal para voltar à visão.', 'Nossa venerada dama me enviou para ajudá-la em sua missão. Ela deseja que você recupere o Cadinho de Nazsharin, que foi roubado, e traga-o de volta o quanto antes.$B$BEla está ficando cada vez mais impaciente para iniciar o ritual de evocação para que possamos então começar nossas preparações para a guerra.', '', '', '', '', '', '', '', '', '', 'Recupere o Cadinho de Nazsharin.', 0),
(25863, 'ptBR', 'Fardo escolhido', 'Retorne à extremidade oeste da Crista Biel\'aran com as notícias do Cadinho de Nazsharin.$B$BEssa missão faz parte da visão da Dama Guerreira Naz\'jar. Caso necessário, use a Lâmina da Dama Guerreira Naz\'jar em um foco temporal para voltar à visão.', 'Com o Cadinho de Nazsharin, tudo que resta a fazer é informar a Lady Naz\'jar.', '', '', '', '', '', '', '', '', '', 'Retorne à extremidade oeste da Crista Biel\'aran com as notícias do Cadinho de Nazsharin.', 0),
(25864, 'ptBR', 'Crise dos dinossauros', 'Mate 8 Raptores do Planalto de qualquer tipo.', 'Temos recebido mais e mais relatórios de ataques de raptores na região. Pretendo deixar o local seguro para que mais pessoas possam se estabelecer aqui, então ofereci recompensa para quem der um jeito nesses malas.$B$BJá matamos muitos, mas os raptores do planalto ao norte estão se multiplicando cada vez mais. Não vai continuar, vai?$B$BMate vários raptores do Planalto e receberá uma boa recompensa.', '', 'Raptores do Planalto mortos', '', '', '', '', '', '', '', 'Fale novamente com Shilah Cinzelaje na Estação Entrós, que fica no Pantanal.', 0),
(25865, 'ptBR', 'Um basta nos Pelemusgo', 'Recupere 8 Lingotes de Altaforja dos Gnolls Pelemusgo.', 'Acho que posso confiar em você para me ajudar com o meu verdadeiro problema, $n. Vim de Altaforja recuperar um carregamento de lingotes de ouro.$B$BOs lingotes são parte do Tesouro Real de Altaforja e têm o carimbo do brasão real... Eles são tão fáceis de rastrear que só um idiota os roubaria. Por incrível que pareça, esta região está cheia de idiotas: os gnolls Pelemusgo.$B$BNão sei se você já lutou contra gnolls antes, mas eles são feras brutais, imundas e perigosas. Quero que os mate e recupere os lingotes desaparecidos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Shilah Cinzelaje na Estação Entrós, que fica no Pantanal.', 0),
(25866, 'ptBR', 'Coureadores Ferro Negro', 'Mate 10 Coureadores Ferro Negro.', 'Você deve ter visto alguns coureadores por aí, mas também avistamos alguns membros do clã Ferro Negro. Eles nunca foram de respeitar política de boa vizinhança e parece que estão sequestrando os gnolls Pelemusgo por algum motivo.$B$BNão sei o que pretendem, mas precisamos dar um fim nisso antes que tudo piore mais ainda. Destrua os planos deles.$B$BSe estiver $gpreocupado:preocupada; com a justiça, tente negociar primeiro para ver o que acontece.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Shilah Cinzelaje na Estação Entrós, que fica no Pantanal.', 0),
(25867, 'ptBR', 'Fuga dos Gnolls', 'Obtenha as Chaves do Coureador dos Coureadores Ferro Negro e use-as para libertar 6 Gnolls das Jaulas de Gnoll.', 'Eu sei que estávamos atacando os gnolls, mas não posso deixar que os Ferro Negro os escravizem. Em primeiro lugar, encontramos os ladrões e recuperamos o que havia desaparecido. A justiça já foi feita. Em segundo lugar, não quero que o trabalho que eles estão fazendo obrigados pelos Ferro Negro prossiga.$B$BDe um jeito ou de outro, precisamos libertar os gnolls. Os coureadores ficam com as chaves e precisamos delas para abrir as jaulas.', '', 'Gnolls Libertados', '', '', '', '', '', '', '', 'Fale novamente com Shilah Cinzelaje na Estação Entrós, que fica no Pantanal.', 0),
(25868, 'ptBR', 'Yorla Laçadeira', 'Mate Yorla Laçadeira.', 'Eu descobri quem está por trás dessa operação. A Yorla Laçadeira está orientando os anões Ferro Negro a partir de uma base a leste daqui. Deve ter sido ela quem mandou os gnolls roubarem o ouro de Altaforja.$B$BAlém do mais, ela é uma criminosa procurada... Magni ainda estava vivo quando ela começou a organizar rebeliões e ataques contra Altaforja.$B$BEla está bem debaixo do nosso nariz e não podemos permitir que fuja. Atrás dela, $n!', '', '', '', '', '', '', 'Yorla Laçadeira', '', '', 'Fale novamente com Shilah Cinzelaje na Estação Entrós, que fica no Pantanal.', 0),
(25869, 'ptBR', 'Temível Totem na Aldeia', 'Mate 10 Invasores Temível Totem.', 'Sua jornada deve começar com a batalha contra os invasores do Temível Totem na Aldeia Vento Livre. Se você não os detiver aqui, não conseguiremos avançar até o território deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Quentin na Aldeia Vento Livre, que fica em Mil Agulhas.', 0),
(25870, 'ptBR', 'Temível Totem na Aldeia', 'Mate 10 Invasores Temível Totem.', 'Você precisa acabar com os Temível Totem que estão na Aldeia Vento Livre. Eles pediram por isso, os covardes.$B$BNão poderemos avançar rumo ao território inimigo com eles à nossa retaguarda. Por favor, ajude-nos a retomar nosso lar, $c.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Thalia Couro Âmbar na Aldeia Vento Livre, que fica em Mil Agulhas.', 0),
(25871, 'ptBR', 'Por favor, salvem a sentinela', 'Resgate a Sentinela de Feralas.', '<Brienna balança um bilhete com inscrições em taurahe.>$B$BAqueles monstros capturaram uma de nossas sentinelas! Estão ameaçando matá-la caso não cessemos o ataque!$B$BNão negociamos com criaturas covardes! Por favor, ajude-nos! Salve-a antes que seja tarde demais, $c.', '', 'Sentinela de Feralas libertada', '', '', '', '', 'Sentinela de Feralas capturada', '', '', 'Fale novamente com Brienna Cintiluna na Aldeia Vento Livre, que fica em Mil Agulhas.', 0),
(25872, 'ptBR', 'Os Bravos e Destemidos', 'Salve o Valente de Vento Livre.', '<Rau balança um bilhete com inscrições em taurahe.>$B$BAqueles monstros capturaram um de nossos valentes! Estão ameaçando matá-lo caso não cessemos o ataque!$B$BNão permitiremos que aqueles covardes continuem na Aldeia Vento Livre! Por favor, salve-o antes que seja tarde demais, $c.', '', 'Valente de Vento Livre libertado', '', '', '', '', 'Valente de Vento Livre capturado', '', '', 'Fale novamente com Rau Corta Montes na Aldeia Vento Livre, que fica em Mil Agulhas.', 0),
(25873, 'ptBR', 'Chifre do traidor', 'Consiga o Chifre do Chifre Longo', 'Aqui jaz o corpo sem vida de Montarr, o erudito da Aldeia Vento Livre, em uma poça de seu próprio sangue.$B$BUm rastro vermelho se estende até a estalagem...', '', '', '', '', '', '', 'Vigia do Rochedo Chifre Longo', '', '', 'Fale com Quentin na Aldeia Vento Livre, que fica em Mil Agulhas.', 0),
(25874, 'ptBR', 'Chifre do traidor', 'Consiga o Chifre do Chifre Longo', 'Aqui jaz o corpo sem vida de Montarr, o erudito da Aldeia Vento Livre, em uma poça de seu próprio sangue.$B$BUm rastro vermelho se estende até a estalagem...', '', '', '', '', '', '', 'Vigia do Rochedo Chifre Longo', '', '', 'Fale novamente com Thalia Couro Âmbar na Aldeia Vento Livre, que fica em Mil Agulhas.', 0),
(25875, 'ptBR', 'Gnomida infiltrada', 'Procure Dada, que está disfarçada como uma Controladora de Bomba "Goblina", no Barreiro, que fica na Cordilheira das Torres de Pedra.', 'O Lago Mirkfallon está infestado pela Horda. Os goblins se instalaram e não vão a lugar algum antes de esgotar todo o petróleo das Torres de Pedra.$B$BFelizmente, tenho uma gnomida infiltrada que vem coletando informações para nós. Se alguém sabe algo sobre aquela bomba, esse alguém é a minha agente.$B$BVá ao Barreiro, ao norte, e fale com a Dada. Ela estará disfarçada como uma controladora "goblina".', '', '', '', '', '', '', '', '', '', '', 0),
(25876, 'ptBR', 'Lá em cima!', 'Roube o Livro de Registros de Krom\'gar.', 'Escute, tenho estado no encalço dessa bomba desde que você me resgatou no Vale Gris. Seja o que for que farão com ela, vai acontecer logo, logo.$B$BNo topo daquela plataforma petrolífera grande há uma sala de controle. Dentro da sala, você encontrará um livrinho de registros de Krom\'gar. Esse livrinho é a chave para descobrirmos para onde irá a bomba. Vá lá e pegue o livro de registros! Traga-o aqui e eu o decifrarei para você.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a "Goblina" Controladora de Bomba no Barreiro, que fica na Cordilheira das Torres de Pedra.', 0),
(25877, 'ptBR', 'Sem tempo para despedidas!', 'Fale novamente com o Comandante dos Batedores Barus no Posto Mirkfallon, que fica na Cordilheira das Torres de Pedra.', 'CORRA! Saia daqui, $n. Volte a Barus e informe tudinho a respeito do que você descobriu. Ele arranjará uma viagem segura pelo Vale Chaga de Guerra até o Mirante de Thal\'darah para você.$B$BAinda temos tempo de salvar aqueles jovens druidas!', '', '', '', '', '', '', '', '', '', '', 0),
(25878, 'ptBR', 'Tramando aquela sabotagem...', 'Use o Controlador de Bomba Goblínico para destruir 4 Bombas Petrolíferas Goblínicas.', 'Goblins... O que seria deste mundo sem goblins? Eu lhe digo: LIMPO!$B$BAqueles trastes imundos imprestáveis espalharam bombas petrolíferas por todo o lago na esperança de extrair o petróleo das Torres de Pedra até a última gota. Junto a cada bomba, eles posicionaram um controlador cuja única função é vigiá-la e garantir que nada dê errado.$B$BAlgo está prestes a dar errado.$B$BElimine os controladores e pegue os controles das bombas. Use os controles para sobrecarregá-las!', '', 'Bombas Petrolíferas destruídas', '', '', '', '', '', '', '', 'Fale novamente com a Batedora-chefe Yvonia no Posto Mirkfallon, que fica na Cordilheira das Torres de Pedra.', 0),
(25879, 'ptBR', 'O problema dos parvos desorientados', 'Mate 10 Parvos Desorientados', 'Você já viu um hobgoblin? Eles são mais uma das criações torpes dos goblins. Pegue um goblin e deixe-o mais feio, mais gordo, maior e mais idiota e você terá um hobgoblin. Acrescente a tudo isso uma veia cruel e temos um senhor problema.$B$BEsses parvos desorientados perambulam pelo Barreiro e pelo Lago Mirkfallon fazendo o trabalho pesado pelos goblins.$B$BVá lá e desfalque o contingente deles. Permanentemente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Batedora-chefe Yvonia no Posto Mirkfallon, que fica na Cordilheira das Torres de Pedra.', 0),
(25880, 'ptBR', 'Avise o mestre Thal\'darah', 'Apresente-se ao Mestre Thal\'darah no Mirante de Thal\'darah, que fica na Cordilheira das Torres de Pedra.', 'Há dúzias de estudantes no Bosque de Thal\'darah. A maioria deles não tem como se defender. Estão prontos para o abate!$B$BVocê precisa alertar o mestre Thal\'darah sobre os planos da Horda. Ele instruirá você quanto ao que deve ser feito em seguida.$B$BFiora Alçaluna lhe concedeu o direito de voar em nosso mais veloz hipogrifo. Voe já com ele até o Mirante de Thal\'darah! Não olhe para trás, $n! A Horda deve ser detida!', '', '', '', '', '', '', '', '', '', '', 0),
(25881, 'ptBR', 'Protetor perdido', 'Encontre e resgate 8 Protetores Perdidos.', 'Nós aguentamos ao máximo, $c. Mas as chamas... O calor... A cidade inteira foi destruída.$B$BO capitão Ferrárbol se recusou a recuar quando o fogo nos engolfou. Nossas tropas se dispersaram. Será que alguns sobreviveram? Nós podemos organizar um contra-ataque!$B$BVá até a Terra Queimada e resgate os protetores que se perderam do grupo. Depois, procure o capitão Ferrárbol. Ele deve ter tomado algum ponto fortificado em meio à batalha.', '', 'Protetores Perdidos resgatados', '', '', '', '', '', '', '', 'Encontre o Capitão Ferrárbol na Terra Queimada, que fica no Monte Hyjal.', 0),
(25882, 'ptBR', 'Uma mãozinha para o rancho', 'Fale com o Sargento Pedertelo no Rancho Ambarmanso.', 'O capitão Tharran pediu que eu lhe desse os parabéns e agradecesse pela sua ajuda na missão. Ele e seus soldados estão dando cabo dos últimos trolls e começando a assistência aos feridos.$B$BO Capitão também pediu que você checasse relatos de ataques de trolls no Rancho Ambarmanso, ao norte. Procure pelo sargento Pedertelo quando chegar.', '', '', '', '', '', '', '', '', '', '', 0),
(25883, 'ptBR', 'Naga má fica sem brinquedo', 'Destrua 6 conjuntos de Tridentes Naga.', 'Armas das nagas...$b$bÉ só olhar na direção dos Currais das nagas que você verá dúzias de pilhas de tridentes semelhantes, estrategicamente posicionadas.$b$bDestruir as armas delas só pode dificultar quaisquer que sejam os planos maléficos que elas levam a cabo nesta região...', '', 'Armas Naga destruídas', '', '', '', '', '', '', '', '', 0),
(25884, 'ptBR', 'Haja o que houver', 'Mate 12 Nagas Zin\'jatar na Amarra, que fica na Floresta Kelp\'thar.', 'Ah, pelo amor de...$b$bSei que o nosso amigo sobrevivente aqui parece estar bem, mas o guri está seriamente traumatizado.$b$bSó existe uma maneira de lidar com aquelas feras malditas: um bom machado enânico, enterrado até o cabo, bem na cabeça delas.$b$bSe você fizer uma pilha bem grande com os corpos delas, vai fazer elas pensarem duas vezes antes de tentar nos transformar em comida de peixe.$b$bOuça o que digo, $gguri:guria;: aquelas coisas odeiam ver o próprio sangue, tanto quanto nós.$b$bAgora, vai lá e dá uma lição nelas!', '', 'Nagas Zin\'jatar mortas', '', '', '', '', '', '', '', 'Fale com o Rendel na Gruta Densanévoa, que fica na Floresta Kelp\'thar.', 0),
(25885, 'ptBR', 'O quê? Quê? Nas minhas entranhas...?', 'Colete 7 Brotos de Alga-crespa dos Ceifadores Luzespinha, que ficam na Amarra.', 'O qu... que é isso!?$b$bTem uma dor forte crescendo... no fundo das minhas entranhas.$b$bAcho... ugh... que eles devem ter me envenenado!$b$bEles nos deram algas marinhas estranhamente brilhantes que cultivam em torno da fortaleza deles...$b$bAcho que essa câimbra vai piorar se eu não conseguir mais logo...$b$bPor favor, $r. Tente me arranjar um pouco!', '', '', '', '', '', '', '', '', '', 'Fale com o Recruta Pollard na Gruta Densanévoa.', 0),
(25886, 'ptBR', 'Aproveitando a vantagem', 'Mate 4 Capitães Avançados do Crepúsculo.', 'Parece que boa parte do Martelo do Crepúsculo retrocedeu para organizar outro ataque. Os mais abnegados ficaram para trás, defendendo o front. Essa é a nossa chance de acabar com as lideranças deles.$B$BAvance pela Terra Queimada e esmague os capitães avançados do Crepúsculo. Vamos apagá-los dessa equação!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Ferrárbol na Terra Queimada, que fica no Monte Hyjal.', 0),
(25887, 'ptBR', 'Rastro de destruição', 'Use o Orbe da Sugestão para dominar um Grande Tubarão Faminto e, a seguir, use-o para destruir 25 Zin\'jatar na Amarra.', 'O nosso tempo aqui está acabando. De alguma forma, preciso seguir a trilha desses prisioneiros para descobrir os propósitos das nagas nesta região.$b$bMas, antes de prosseguir, quero ver o fim dessa operação!$b$bNão importa o número delas, tenho um plano que pode equilibrar as chances.$b$bFora desta caverna, grandes tubarões famintos que foram expulsos dos seus territórios pelas nagas procuram comida.$b$bEnfraquecidos como estão, eles ficam influenciáveis. Use este orbe para dominá-los e, então, mande-os de encontro ao inimigo.', '', 'Guardiões Zin\'jatar devorados vivos', '', '', '', '', '', '', '', 'Fale com Erunak na Gruta Densanévoa.', 0),
(25888, 'ptBR', 'Descompressão', 'Use a Pedra da Respiração de Moana em 10 Soldados Aprisionados na Amarra.', 'Simplesmente não suporto a ideia de tantos outros, como esse soldado, aprisionados ou cercados por nagas.$b$bAlgo deve ser feito para regatá-los!$b$bTente isto, $n. Use-a nas celas da prisão para fazer com que boiem.$b$bSe conseguirmos fazer com que cheguem à superfície, ao menos eles terão uma chance de resgate.', '', 'Soldados Aprisionados libertados', '', '', '', '', '', '', '', 'Fale com Moana na Gruta Densanévoa.', 0),
(25889, 'ptBR', 'Salve as crianças!', 'Use o Hipogrifo do Mestre Thal\'darah para resgatar 5 Jovens Druidas Indefesos do Bosque de Thal\'darah.', 'Meus pobres e indefesos jovens alunos estão isolados no Bosque de Thal\'darah. Com a batalha assolando todo o Vale Chaga de Guerra, elas não têm como escapar. Devemos salvar as crianças antes que a Horda jogue a bomba!$B$BPegue meu hipogrifo e use-o para resgatar os jovens druidas do Bosque de Thal\'darah. Deixe-os no posto de hipogrifos aqui na cidade.$B$BSalve-as todas, $n. Você é realmente nossa única esperança.', '', 'Jovens Druidas Indefesos resgatados', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Thal\'darah no Mirante de Thal\'darah, que fica na Cordilheira das Torres de Pedra.', 0),
(25890, 'ptBR', 'Nespirah', 'Passe pela entrada noroeste de Nespirah e, em seguida, descubra um jeito de se comunicar com ela.', 'A esta altura, já entendi o que tem que ser feito, $n.$b$bAs nagas só podem estar obtendo essas pérolas de um lugar: Nespirah, a concha ancestral que vive em frente a esta caverna. O motivo pelo qual Nespirah se submeteria às nagas, contudo, está além do meu entendimento.$b$bPodemos entrar na cavidade corporal de Nespirah através de um pequeno tubo próximo da saída desta caverna. Primeiro, preciso buscar o meu mestre e, então, poderemos encontrar você lá dentro. Iremos nos reunir na entrada noroeste de Nespirah.', 'Descubra uma forma de se comunicar com Nespirah.', '', '', '', '', 'Descubra uma forma de se comunicar com Nespirah.', '', '', '', 'Fale com o Reparador da Terra Duarn dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25891, 'ptBR', 'Um último esforço', 'Auxilie o Mestre Thal\'darah na busca por qualquer druida deixado para trás no Bosque de Thal\'darah.', 'A Horda sinaliza uma retirada. Olhe agora. Eles recuam do campo de batalha... presságios do desastre.$B$BPrecisamos descer uma última vez ao Bosque de Thal\'darah. Eu não poderia viver com a culpa de deixar nossos jovens druidas para trás.$B$BAjude-me, $Gherói:heroína;. Tomarei as rédeas. Procure por qualquer druida que possa ter sido deixado para trás.$B$BIremos quando você estiver $gpronto:pronta;.', 'Último esforço feito', '', '', '', '', 'Último esforço feito', '', '', '', 'Fale com o Mestre Thal\'darah no Mirante de Thal\'darah na Cordilheira das Torres de Pedra.', 0),
(25892, 'ptBR', 'Perdendo terreno', 'Use o cavalo-marinho da Falaondas Valoren para voltar até o Almirante Dvorek sob o terraço sul nas Ruínas de Vashj\'ir.', 'Terás de me contar as novidades mais tarde. Agora, precisamos sair daqui antes que as nagas nos ataquem. Volta ao posto avançado no nível abaixo de nós.$B$BUsa meu cavalo-marinho. Encontramo-nos lá em breve.', '', 'Retorno ao posto avançado', '', '', '', '', '', '', '', 'Retirada para a Praia Tranquila', 0),
(25893, 'ptBR', 'Plano de emergência', 'Encontre-se com o Engenheiro Hexasfrega na Crista Biel\'aran.', 'Jorlan e Hexasfrega partiram para conseguir ajuda. As rotas comerciais não ficam tão longe, então talvez tenhamos uma chance de sucesso. Mas estou tomando cuidado para que ninguém fique muito esperançoso.$B$BNa verdade, essa é nossa última opção. Não sobreviveremos por muito mais tempo. Hora ou outra, as nagas nos encontrarão e... bem... você viu muito bem quantas nagas havia lá embaixo.$B$BVá encontrar Jordan e Hexasfrega na Crista Biel\'aran, a sudeste. Manterei todos aqui em segurança o máximo de tempo que puder.', '', '', '', '', '', '', '', '', '', '', 0),
(25894, 'ptBR', 'Águas hostis', 'Mate 10 Bicões Pelancalamas.', 'Hexasfrega veio aqui com um tipo de balão que ele trouxe de uma das nossas embarcações. Ele tentou fazer com que a coisa flutuasse até a superfície, mas aqueles bicões pelancalamas apareceram do nada para atrapalhar.$B$BHexasfrega resolveu usar outro balão, mas temos que garantir que não vamos ter mais problemas com os bicões. Preciso que você acabe com esses goblins-de-guelra. Seja como for, mate goblins o suficiente para que eles pensem duas vezes antes de nos atrapalhar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Engenheiro Hexasfrega na Crista Biel\'aran.', 0),
(25895, 'ptBR', 'É melhor se preparar', 'Recupere o Kit de Sobrevivência da Aliança.', 'Preparação é essencial. Temos que preparar engrenagens, instruções, e... engrenagens e instruções!$B$BTodas as embarcações das frotas da Aliança carregam kits de sobrevivência, e muitos dos nossos instrumentos vêm desses kits, incluindo meu balão! Mas agora ele se foi, e eu preciso de outro kit de sobrevivência!$B$BHá um navio para sudeste. Espero que os sobreviventes deste tenham sido tolos o suficiente para não usarem o kit de sobrevivência, assim podemos usá-lo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Engenheiro Hexasfrega na Crista Biel\'aran.', 0),
(25896, 'ptBR', 'Assembleia dos devotos', 'Procure o Invocador das Profundezas Azrajar no meio das escadas ao norte e 6 Sacerdotisas da Maré na região superior das ruínas, e ordene que eles retornem ao templo.$B$BEssa missão faz parte da visão da Dama Guerreira Naz\'jar. Caso necessário, use a Lâmina da Dama Guerreira Naz\'jar em um foco temporal para voltar à visão.', 'Ah, Dama Guerreira. Você carrega consigo as palavras e a vontade da maior das nossas damas. Gostaria de lhe pedir um favor...$B$BPreciso que o Invocador das Profundezas Azrajar e minhas Sacerdotisas da Maré retornem para que possamos começar o ritual. Você poderia avisá-los? As sacerdotisas se encontram sobre o terraço do templo. Azrajar provavelmente estará nas escadas ao norte.', '', 'Sacerdotisas da Maré Sira\'kess informadas', 'Invocador das Profundezas Azrajar informado', '', '', '', '', '', '', 'Fale novamente com a Lady Sira\'kess no Templo de Quel\'Durmar.', 0),
(25897, 'ptBR', 'Corda cabeluda', 'Colete 8 Rolos de Corda Kvaldir.', 'Como lhe falei, os kits de sobrevivência nunca trazem cordas. Isso não faz sentido nenhum!$B$BTenho certeza que aqueles kvaldir têm cordas. Eles estão sempre andando por aí em barcos, fazendo nós, preparando redes... Veja se consegue uma corda com eles! Precisamos de uma para nosso plano funcionar, não há dúvidas quanto a isso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Engenheiro Hexasfrega na Crista Biel\'aran.', 0),
(25898, 'ptBR', 'Fazendo as honras', 'Nade até a superfície, pegue o sinalizador e use-o na direção das embarcações da Aliança.', 'Tudo pronto. Estou confiante de que vai funcionar. E nenhum bicão por perto para atrapalhar! Perfeito.$B$BJorlan já está na superfície esperando, nade você também até lá. Ele me disse que as honras serão suas. Ele é um cara muito legal.$B$BVá para a superfície com o balão, leve junto o sinalizador e procure por embarcações da Aliança no horizonte. Se você vir alguma, atire com o sinalizador na direção dela e pronto, simples assim!$B$BNadar, flutuar, sinalizar e resgatar – aliás, ser resgatado! A última parte é minha favorita.', '', 'Nadar até o balão de resgate na superfície', 'Disparar o sinalizador na direção das embarcações da Aliança', '', '', '', '', '', '', 'Falar com Jorlan Gumecerto na superfície, acima da Crista Biel\'aran.', 0),
(25899, 'ptBR', 'Através das linhas inimigas', 'Mate 10 Senhores Calcinantes do Crepúsculo.', 'O exército de chamas que causou toda essa devastação no alto do morro recuou em direção ao leste. Apenas os senhores calcinantes continuam no front. Se conseguirmos furar a linha de frente deles e nos reagruparmos com as tropas do capitão Ferrárbol, toda a ofensiva inimiga entrará em colapso.$B$B$C, não estou em condições de lutar, mas acho que você é capaz de fazer um belo estrago. Mate os senhores calcinantes e junte-se às tropas do capitão Ferrárbol!', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Ferrárbol na Terra Queimada, que fica no Monte Hyjal.', 0),
(25900, 'ptBR', 'Fazendo contato', 'Observe enquanto o Reparador da Terra Duarn tenta se comunicar com Nespirah.', 'Não acredito que Nespirah permitiria, condescendentemente, que essas nagas estabelecessem residência dentro da sua concha. A meu ver, ou uma coisa, ou outra: ou elas a convenceram a se juntar à causa, ou elas a enfraqueceram a ponto de ela não conseguir reagir. Qualquer uma das duas é ruim.$b$bAqui, nesta câmara, devo conseguir me comunicar diretamente com Nespirah. Vamos descobrir por nós mesmos. Fale comigo quando estiver preparad$go:a;, $c.', 'Fale com o Reparador da Terra Duarn', '', '', '', '', 'Fale com o Reparador da Terra Duarn', '', '', '', 'Fale novamente com o Reparador da Terra Duarn dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25901, 'ptBR', 'Programa de reciclagem de Hyjal', 'Recolha 15 Flechas do Protetor.', 'Reforços! Achei que lutaríamos aqui até o amargo fim.$B$BRestaram poucos guardiões de Hyjal e estamos ficando sem suprimentos. Mas deve haver muitas flechas aproveitáveis no campo de batalha em torno daqui.$B$BEu sei que esta não é uma tarefa à altura dos seus talentos, mas você poderia recolher um pouco da munição usada? É a única forma de reabastecer nossos estoques!', '', '', '', '', '', '', '', '', '', 'Entregue as flechas para Logram na Terra Queimada, que fica no Monte Hyjal.', 0),
(25904, 'ptBR', 'O Martelo e a chave', 'Mate um Capitão Avançado do Crepúsculo e recupere o Glifo de Abertura.', 'Meu Nêmesis. Ainda vive.$BOs servos do fogo virão.$BTemos que perseguir. Até o covil deles.$B$BOs ogros sabem o caminho.$BMate os capitães avançados.$BPegue o Glifo de Abertura.$B$BEste é o jeito.', '', '', '', '', '', '', '', '', '', 'Entregue o glifo para Tortolla na Terra Queimada, que fica no Monte Hyjal.', 0),
(25905, 'ptBR', 'A fuga dos carneiros', 'Recupere 6 Carneiros Roubados nos Montes Túndricos usando /assobiar.', 'Os carneiros criados e treinados no Rancho Ambarmanso há tempos são as montarias preferidas dos montanhistas de Dun Morogh. Sim, há alguns montanhistas ali, mas não em número suficiente para cuidar da segurança da minha família e dos animais.$B$BAlguns saqueadores Jubafria mais abusados vêm furtando nossos carneiros na calada da noite e levando-os para os Montes Túndricos. Você poderia ajudar a trazer nossos animais de volta? Para atraí-los, basta chegar bem perto deles e assoviar bem alto para chamar a atenção. Então, é só esperar, pois o adestramento vai falar mais alto e eles saberão o que fazer.', '', 'Carneiros Roubados recuperados', '', '', '', '', '', '', '', 'Fale novamente com Veron Ambarmanso no Rancho Ambarmanso.', 0),
(25906, 'ptBR', 'O terceiro Portal de Chamas', 'Atravesse o portal de chamas na Terra Queimada e encontre Garunda Picomonte do outro lado.', 'Memorize o glifo.$BLeve-o dentro de você.$B$BRisque-o no chão perante o portal de chamas.$BLeste daqui.$BEntre nas Terras de Fogo.$B$BNão posso ir com você.$BMas meus filhos esperam. Lá dentro.$B$BEncontre Garunda Picomonte no reino do fogo.', '', '', '', '', '', '', '', '', '', 'Atravesse o portal de chamas na Terra Queimada e encontre Garunda Picomonte do outro lado.', 0),
(25907, 'ptBR', 'Trabalho escravo', 'Use a Corda de Duarn para salvar 8 Mineradores de Pérolas Escravizados.', 'Vamos precisar de algum tempo para rompermos essa barreira e nos comunicarmos com Nespirah. No meio-tempo, você pode salvar alguns daqueles homens que as nagas mantêm escravizados nos poços aqui embaixo.$b$b<Duarn fabrica um pedaço de corda com as próprias vestes.>$b$bIsso vai acabar sendo útil.', '', 'Mineradores de Pérolas resgatados', '', '', '', '', '', '', '', 'Fale novamente com o Reparador da Terra Duarn dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25908, 'ptBR', 'Limpando o organismo', 'Mate 7 Sentinelas Idra\'kess e 7 Encantadoras Idra\'kess.', 'Não consegui me comunicar diretamente com a fera Nespirah, mas ainda posso, indiretamente, sentir algumas coisas. Por exemplo, posso perceber claramente que Nespirah não está gostando da presença das nagas aqui.$b$bQuando entramos no corpo de Nespirah, vi dúzias de sentinelas e encantadoras patrulhando o andar da câmara central. Talvez a dor da anciã seja um pouco aliviada se você removê-las.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Reparador da Terra Duarn dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25909, 'ptBR', 'Capture o caranguejo', 'Use a Rede de Duarn para capturar um Caranguejo Buscafundo dentro de Nespirah.', 'Tudo no meu corpo me diz que Nespirah está tentando falar comigo, mas não consigo escutá-la. Talvez as nagas tenham feito algo com a voz dela.$b$b<Duarn pensa com seus botões por um momento.>$b$bA voz de Nespirah pode estar suprimida... isso quer dizer que... precisamos encontrar uma voz para ela!$b$bJá sei! Os Idra\'kess são conhecidos por treinarem caranguejos buscafundo como companheiros de batalha. Use esta rede para capturar um caranguejo e traga-o a mim. Você deve encontrá-los vagando ao redor da câmara.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Reparador da Terra Duarn dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25910, 'ptBR', 'Acabou a moleza', 'Mate 10 Atormentadores Derretidos e 4 Senhores da Chama Sombria.', 'Esta caverna é um aberração, $n. E está repleta de horrores das profundezas.$B$BEu não quero qualquer dessas – coisas – atravessando o portal e saindo para o mundo lá fora. Mate tudo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Garunda Picomonte no Caldeirão.', 0),
(25911, 'ptBR', 'Boas notícias', 'Fale novamente com o Capitão Taylor na Praia Tranquila.', 'Eles provavelmente enviarão um esquife, o que pode demorar um pouco. Ficarei aqui para falar com eles.$B$BVocê precisa voltar à caverna imediatamente e informá-los de que o resgate está a caminho. Espero que as nagas ainda não tenham chegado lá.$B$BVá, nada o mais rápido que puder, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(25912, 'ptBR', 'Bons velhos tempos...', 'Encontre o Caderno de Esboços da Anciã Sareth\'na.', 'O mundo está se desintegrando à nossa volta, $n. De um lado, velhos inimigos tentam nos destruir. Do outro, hostis forças antigas se aproximam.$B$B<A anciã Sareth\'na suspira.>$B$BJá vi dias melhores, mais felizes, e tenho saudade deles...$B$BDo outro lado do Morro das Torres de Pedra, jazem as ruínas de nosso velho acampamento, agora tomado pelas trevas. Se você, por acaso, seguir naquela direção, será que poderia procurar meu caderno de esboços? Ele guarda muitas boas lembranças. Eu $Go:a; recompensaria bem por devolvê-lo a mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Anciã Sareth\'na no Mirante de Thal\'darah, que fica na Cordilheira das Torres de Pedra.', 0),
(25913, 'ptBR', 'Botando-as para descansar', 'Recupere 8 Glaives das Sentinelas.', 'À medida que a Horda marchava sobre as Torres de Pedra, notei que algumas sentinelas adoeceram. Não muito depois, elas começaram a agir estranhamente. Quando o primeiro tentáculo irrompeu do solo, as sentinelas doentes começaram a nos atacar. Perdemos o acampamento pouco depois...$B$BAs sentinelas no pico, agora, nada mais são do que cascas, carapaças para algo muito mais sinistro. Quero que você dê o descanso final às sentinelas e recupere seus glaives. Cada glaive devolvido pode identificar uma irmã abatida.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sentinela-chefe Geleneth no Mirante de Thal\'darah, que fica na Cordilheira das Torres de Pedra.', 0),
(25914, 'ptBR', 'De volta às profundezas!', 'Mate o Emissário Aph\'lass e 10 Tentáculos Invasores.', 'Gavinhas estão brotando da terra e aterrorizando o Morro das Torres de Pedra. Minhas sentinelas mal conseguem desfalcar os números delas.$B$BSuspeito que haja uma força, no coração do Morro das Torres de Pedra, controlando as gavinhas. Talvez, se conseguirmos deter essa força, as gavinhas voltem às profundezas de onde vieram!', '', '', 'Tentáculos Invasores mortos', '', '', '', '', '', '', 'Fale novamente com a Sentinela-chefe Geleneth no Mirante de Thal\'darah, que fica na Cordilheira das Torres de Pedra.', 0),
(25915, 'ptBR', 'A força de Tortolla', 'Acompanhe um Filho de Tortolla até um Cristal de Nêmesis. Volte a falar com Garunda Picomonte se você se desencontrar do Filho de Tortolla.', 'Nêmesis, o usurpador sombrio, fugiu para cá quando os incêndios em Hyjal recuaram. Ainda não somos fortes o suficiente para derrotá-lo, $n, mas talvez possamos usar a força dele contra ele mesmo.$B$BVou mandar um filho de Tortolla acompanhar você, um dos libertados da corrupção do Martelo do Crepúsculo.$B$BProcure no fundo desta caverna um Cristal de Nêmesis e permita que a jovem tartaruga examine o mineral.$B$BProcure-me novamente se você se desencontrar da tartaruguinha!', '', 'Cristal de Nêmesis examinado', '', '', '', '', '', '', '', 'Fale novamente com Garunda Picomonte no Caldeirão.', 0),
(25916, 'ptBR', 'Abrindo caminho', 'Observe enquanto o Reparador da Terra Duarn tenta falar com Nespirah.', 'Um xamã treinado tem a habilidade de se comunicar com os quatro elementos – terra, fogo, ar e água. Isso é sabido.$b$bO que poucos sabem, contudo, é que há um quinto elemento. Esse elemento não é tão claramente descrito quanto os outros quatro, mas tem a ver com os... atributos comuns a todas as criaturas vivas.$b$bA minha teoria é que o caranguejo, criatura marinha que é, é próximo o bastante de Nespirah para que, com a influência dos elementos, consigamos convencê-lo a agir como porta-voz dela.', 'Fale com o Reparador da Terra Duarn', '', '', '', '', 'Fale com o Reparador da Terra Duarn', '', '', '', 'Fale novamente com o Reparador da Terra Duarn dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25917, 'ptBR', 'Não estamos sozinhos', 'Encontre os sobreviventes da Aliança dentro de Nespirah, que fica em Vash\'jir.', '<Duarn fecha os olhos, para por um momento e balança a cabeça.>$b$bNespirah acabou de me informar que não somos os únicos lutando dentro desta concha. Um pequeno grupo de escravos da Aliança escapou e está combatendo as nagas do outro lado da concha, em cima da borda que dá vista para o coração de Nespirah.$b$bVá ao encontro deles, $n, e veja se eles podem nos ajudar. Com o auxílio deles, talvez sejamos capazes de despertar Nespirah desse torpor.$b$bContinuarei aqui, caso você precise de alguma coisa.', '', '', '', '', '', '', '', '', '', '', 0),
(25918, 'ptBR', 'Totalmente desequipado', 'Obtenha 4 Armas de Haste Furtadas dos cavaletes de armas dentro de Nespirah.', 'Eu honestamente não sei como sobrevivemos até agora. As nagas levaram a minha armadura e as minhas armas, deixaram-me com farrapos e uma picareta de mineração... e ATÉ ELA quebrou há meia hora.$b$bPara termos alguma chance de virar o jogo, vou precisar de alguma coisa para lutar... Assim como os meus companheiros, mesmo que eles sejam orgulhosos demais para admitir.$b$bVi cavaletes de armas no depósito das nagas, aqui perto. Não estou acostumado a lutar com um tridente, mas é fato que me sairei melhor do que se eu lutasse apenas com os punhos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Almirante Dvorek dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25919, 'ptBR', 'Golpes corporais', 'Ataque 7 Abscessos de Nespirah ao longo das paredes da câmara respiratória de Nespirah.', '<O capitão Taylor ouve atentamente o seu relato da conversa de Duarn e Nespirah.>$b$bEntendo. Então a criatura quer a nossa ajuda para acordar, não é isso?$b$bCom centenas de escravos picaretando as pérolas dela, a fera parece ter um sono bem pesado. Quem sabe você não tem mais sorte?$b$bMinha sugestão? Procure sinais de fraqueza pela carne da criatura. Talvez essa sua arma encontre um ponto sensível que faça a fera voltar a si.', '', 'Abscessos de Nespirah atacados', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Taylor dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25920, 'ptBR', 'Não deixam de ser valiosas', 'Obtenha 5 Pérolas Misteriosas de Senhores da Guerra e Profetas Idra\'kess dentro de Nespirah.', 'Por mais que eu não tenha passado muito tempo nos poços de pérolas, fiquei curiosa quanto aos objetivos das nagas. Sim, agora sei que as nagas querem usar Nespirah como um motor de guerra, mas, se esse é o caso, então por que elas estão escravizando homens para minerar as pérolas?$b$bPresumindo que vamos conseguir fugir do casco dessa criatura, eu gostaria muito de poder estudar um desses objetos. As pérolas que encontramos nos poços eram grandes demais para carregar, mas já vi senhores da guerra e profetas carregando umas menores algumas vezes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Levia Despertassonhos dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25921, 'ptBR', 'Feitor Idra\'kess', 'Vá para o topo de Nespirah e mate o Feitor Idra\'kess.', 'Meus homens estão com problemas, $n. Receio que não vamos durar muito mais tempo com essas nagas. Com as armas de Idra\'kess e as pérolas de Nespirah, acho que estamos prontos para nos mandarmos daqui.$b$bSiga a parede ao sudeste e procure uma rampa que leva à câmara superior. Presumo que o líder delas esteja lá, ou talvez a chave para acordarmos Nespirah. Com sorte, as duas coisas.$b$bSe você estiver forte o suficiente, vá para o topo da concha e busque algumas respostas.', '', '', '', '', '', '', 'Feitor Idra\'kess', '', '', 'Apresente-se ao Reparador da Terra Duarn perto do cérebro de Nespirah, que fica em Vashj\'ir.', 0),
(25922, 'ptBR', 'Despertando a fera', 'Fale com o Reparador da Terra Duarn dentro de Nespirah, para ativar as defesas biológicas dela. Em seguida, escape do corpo de Nespirah.', 'Graças a você e ao capitão, Nespirah tem controle total do próprio corpo. Mas a maioria das nagas ainda não sabe disso. Depois de fugirmos, ela ativará as defesas biológicas e destruirá as nagas de dentro para fora.$b$bPrepare-se. Vou avisar Nespirah para começar a contagem regressiva.', '', 'Escute enquanto Duarn conversa com Nespirah', 'Escape montando no Cavalo-marinho de Erunak', '', '', '', '', '', '', 'Apresente-se ao Capitão Taylor na Praia Tranquila, que fica em Vashj\'ir.', 0),
(25923, 'ptBR', 'O fim de Nêmesis', 'Use o Totem de Tortolla e a ajuda de um Filho de Tortolla para derrotar Nêmesis. Volte a falar com Garunda Picomonte se você se desencontrar do Filho de Tortolla.', 'A tartaruguinha pode usar o poder recém-descoberto para deixar você e ela própria invulneráveis por um curto período. Você pode usar esse poder para evitar a fúria e os ataques mais fortes de Nêmesis. Para tanto, basta evocar este totem.$B$BIsso é tudo que eu posso fazer por você. Juntos, você e o Filho de Tortolla devem derrotar Nêmesis de uma vez por todas.$B$BVolte aqui se você se perder do seu amiguinho.', '', '', '', '', '', '', 'Nêmesis, o Usurpador', '', '', 'Fale novamente com Garunda Picomonte no Caldeirão.', 0),
(25924, 'ptBR', 'O chamado do dever', 'Embarque na nau mercenária para ir ao local da batalha.', 'Ouça bem, $r!$b$bUma nova massa de terra emergiu na costa dos Reinos do Leste e estamos travando uma importante batalha pelo controle da ilha!$b$bSe vencermos lá, Ventobravo ficará completamente sem defesas!$b$bÉ chegada a hora de atacarmos!$b$bApresente-se nas docas, de imediato, para ser transportad$go:a; para a batalha.$b$bTodos os nossos navios de guerra estão em combate, por isso, você irá em uma nau mercenária comissionada pelo próprio chefe guerreiro.', 'Suba na nau mercenária para ir a Vashj\'ir.', 'Vá até Vashj\'ir na nau mercenária', '', '', '', 'Suba na nau mercenária para ir a Vashj\'ir.', '', '', '', 'Fale com Erunak na Espiral Imortal.', 0),
(25925, 'ptBR', 'A vingança de Thal\'darah', 'Mate 20 soldados da Horda e destrua 3 Demolidores de Krom\'gar no Vale Chaga de Guerra.', 'Devemos tentar estabelecer comunicação com o Vale do Atalaia, ao sul. Nossas atiradoras de glaives darnassianas estão à disposição, $n. Use-os para ceifar as forças invasoras da Horda e abrir o caminho até o Vale do Atalaia.$B$BSó espero que não seja tarde demais para salvarmos o vale. Caso o Vale do Atalaia esteja intacto, encontre o hierofante Malyk e informe-o sobre nossa situação.', '', 'Demolidores de Krom\'gar destruídos', 'Soldados da Horda mortos', '', '', '', '', '', '', 'Apresente-se ao Hierofante Malyk no Vale da Atalaia, que fica na Cordilheira das Torres de Pedra.', 0),
(25926, 'ptBR', 'Repleto de ódio', 'Mate 10 Monstros do Pântano Putrescentes.', 'Os monstros do pântano a oeste não são meus irmãos. Eles são sintomas do distúrbio da terra, uma impureza putrefata.$B$BVocê não entenderia... Eles assumem a forma do meu povo, infestados com sementes em decomposição, e acabam com a vida do pântano. Eles tiram tudo e só deixam a podridão. Nada resta, nada resta!$B$BDê-me um pouco de conforto, $r. Mate os monstros do pântano, purifique a terra e, talvez, a minha mente se acalme.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rethiel, o Verdião, no Bosque do Verdião, que fica no Pantanal.', 0),
(25927, 'ptBR', 'A ameaça das chamas', 'Mate 8 Elementais do Fogo Exaltados.', 'As chamas me ameaçam há muito tempo... muito tempo... mas agora não são mais os pequenos, os insignificantes...$B$BCampos inteiros queimam! Os montes e as montanhas não param de gritar, $r! Não param de gritar! Os elementais que vieram para cá consomem todas as formas de vida.$B$BEles não podem triunfar, não podem triunfar. Acabe com eles. ACABE COM ELES! Destrua os causadores das chamas...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rethiel, o Verdião, no Bosque do Verdião, que fica no Pantanal.', 0),
(25928, 'ptBR', 'O triunfo de Tortolla', 'Atravesse o portal de chamas e fale novamente com Tortolla na Terra Queimada, em Hyjal.', 'Vou conduzir os filhos de Tortolla para fora daqui e lacrar este portal amaldiçoado.$B$BE você vai avisar ao Tortolla sobre a nossa vitória. Atravesse o portal de chamas. O ancião vai ficar muito satisfeito!', '', '', '', '', '', '', '', '', '', 'Atravesse o portal de chamas e fale novamente com Tortolla na Terra Queimada, em Hyjal.', 0),
(25929, 'ptBR', 'Calças do mar', 'Colete 3 Estrelas-do-mar de Água Salgada e uma Concha do fundo do mar no Destino da Legião.', 'Saudações, $c. Sou Erunak, mais um sobrevivente desta selvageria.$b$bReceio que o seu trabalho pesado esteja apenas começando. As nagas têm vasculhado estas águas, atacando qualquer um que ainda viva.$b$bVocê ainda não está equipad$go:a; para sobreviver aqui, mas posso remediar isso.$b$bBem na frente deste navio vive um tipo especial de estrela-do-mar. Traga-me algumas e uma concha. Vou preparar um encantamento que deve ajudar você a se acostumar com esse meio-ambiente.', '', '', '', '', '', '', '', '', '', 'Fale com Erunak na Espiral Imortal.', 0),
(25930, 'ptBR', 'Subindo o vale', 'Use a Mochila-foguete de Salsbury para subir o vulcão do Vale Carbonizado.', 'Ouvi dizer que, antes do grande levante, o Vale Carbonizado era mesmo um vale, sem acesso ao mar. Basta olhar ao sul para ver que o Vale Carbonizado não é mais um vale e que, na verdade, virou uma área de grande atividade vulcânica.$B$BNosso Salsbury aqui montou um dispositivo que vai nos permitir subir o vulcão. Use-o para chegar ao topo e investigar o que está acontecendo.$B$BManterei contato por meio deste Gnomofone, tão gentilmente cedido por Salsbury.', 'Suba o Vulcão do Vale Carbonizado.', '', '', '', '', 'Suba o Vulcão do Vale Carbonizado.', '', '', '', '', 0),
(25931, 'ptBR', 'Prole de Seldarria', 'Destrua 5 dos Ovos de Seldarria', '<O Gnomofone zumbe.>$B$BTenha muito cuidado, $n. Você não quer atiçar aquele dragão negro.$B$BAgora olhe à sua volta. Se isto é um ninho, então deve haver ovos de dragão negro por perto. Vasculhe a área em busca de ovos e destrua os que encontrar.$B$BVolte a mim se você encontrar e destruir os ovos de Seldarria.$B$BQue Goldrinn olhe por você.', '', 'Ovos de Seldarria destruídos', '', '', '', '', 'Hierofante Malyk', '', '', 'Fale novamente com o Hierofante Malyk no Vale do Atalaia, que fica na Cordilheira das Torres de Pedra.', 0),
(25932, 'ptBR', 'Não há nada que os impeça quando a noite cai', 'Ajude o Sargento Pedertelo e seus montanhistas a defender o Rancho Ambarmanso dos Saqueadores Jubafria.', 'Os relatórios que tenho mandado para o capitão Tharran não refletem a gravidade do problema que os trolls da Jubafria nos causaram. O seu ataque à vila ajudou a aliviar um pouco a pressão. As incursões ainda são frequentes, mas há menos trolls do que antes.$B$BMesmo assim, meus soldados estão cansados e com o moral nas últimas. Poderia nos ajudar a defender a fortaleza contra os saqueadores Jubafria? Eles podem aparecer a qualquer momento.', '', 'Defender o Rancho Ambarmanso', '', '', '', '', '', '', '', '', 0),
(25933, 'ptBR', 'Ajuda na pedreira', 'Fale com o Encarregado Pedracenho na Pedreira Gol\'Bolar.', 'Obrigado mais uma vez pela ajuda, $n.$B$BTenho um primo que trabalhava nas minas abaixo da Pedreira Gol\'Bolar, mas ele não pôde mais trabalhar desde que os troggs invadiram o local e assumiram o controle. A pedreira e o acampamento ficam a sudeste do rancho. Por favor, poderia conversar com o encarregado de lá e ver se há algo que possa ser feito?', '', '', '', '', '', '', '', '', '', '', 0),
(25934, 'ptBR', 'O primeiro gnomogen do mundo', 'Consiga 1 Coração de Fogo Fulgurante', 'Bom dia, $Gcidadão:cidadã;. Permita que eu me apresente. Sou Salsbury, e logo serei o primeiro gnomogen do mundo. Malyk assegurou-me de que, assim que meu trabalho aqui estiver completo, ele me cederá o dom dos worgens.$B$BAgora que já nos apresentamos, tenho um pedido!$B$BNo Vale Carbonizado, ao sul daqui, perambulam elementais do fogo recém-criados. Preciso desesperadamente do coração de fogo fulgurante de um dos demônios, algo muito raro. Consiga-o para mim e estarei mais próximo de me tornar um gnomogen!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Salsbury, o "Empregado", no Vale do Atalaia, que fica na Cordilheira das Torres de Pedra.', 0),
(25935, 'ptBR', 'Filhotes famintos', 'Consiga 6 Filés de Filhote de Dragonete Negro.', 'Ah, $Gum recém-chegado:uma recém-chegada;! Que bom que você está aqui, $grapaz:moça;! Os filhotes estão com fome e estamos completamente sem comida.$B$BPor sorte, eles adoram carne de dragão, que fortuitamente pode ser encontrada em abundância ao sul, no Vale Carbonizado.$B$BSeja $Gum bom menino:uma boa menina; e me traga bastante filé de dragonete negro.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre de Matilha Jonathan no Vale do Atalaia, que fica na Cordilheira das Torres de Pedra.', 0),
(25936, 'ptBR', 'Corrente do bem', 'Use a Concha Encantada para resgatar 6 Guerreiros em Afogamento.', 'Você agora pode se mover por este reino com mais liberdade e sem medo de se afogar.$b$bÉ aqui que o nosso trabalho começa.$b$bPrimeiro, você tem muitos aliados se afogando por perto neste momento. Assim como salvei você, você deve salvá-los.$b$bEncantei a concha que você me trouxe. Use-a para resgatar os seus amigos.$b$bVá logo!', '', 'Guerreiros em Afogamento resgatados', '', '', '', '', '', '', '', 'Fale com Erunak na Espiral Imortal.', 0),
(25937, 'ptBR', 'Tesouros inestimáveis', 'Recupere 8 Artefatos Congelados do fundo da Pedreira Gol\'Bolar.', 'Sabia que a mineração não era nossa única atividade na pedreira? Eu liderava uma equipe de escavadores da Liga dos Exploradores que procurava artefatos antigos de valor incalculável.$B$BEu consegui escapar do primeiro ataque dos troggs, mas meus colegas estavam no fundo da mina e não sobreviveram.$B$BMeus companheiros se orgulhavam muito desse trabalho e arriscaram as vidas para que nós pudéssemos conhecer melhor nossa história. Já que você vai até as minas, leve esta picareta e tente encontrar algum objeto nos sítios que os prospectores começaram a escavar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Prospector Drugan na Pedreira Gol\'Bolar.', 0),
(25938, 'ptBR', 'Ajuda para Desolação', 'Apresente-se à Oficial Matilde em Tethris Aran, que fica em Desolação.', 'Recebi uma mensagem perturbadora de Posto do Nijel, em Desolação. Parece que o grande levante criou alguns novos problemas para eles, que estão mal-equipados para a situação. Não recebi mais informação alguma.$B$BApresente-se à oficial Matilde em Desolação. Ela encaminhará você ao Posto do Nijel.$B$BBoa sorte, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(25939, 'ptBR', 'Pelo bem das turfas', 'Use o Inundalírio Abençoado para extinguir 7 Focos de Incêndio no Pântano.', 'Os elementais que assolam o Monte Umbraforja estão queimando tudo por onde passam. Em um pântano como este, o fogo continua queimando nos musgos e nas turfas mais profundas.$B$BVocê precisa apagar os focos de incêndio antes que se alastrem mais. Leve esta flor. Ela é abençoada pela chuva da natureza e permitirá que apague os incêndios.$B$BAlém disso, ela também poderá ser útil contra os próprios elementais.', '', 'Focos de Incêndio no Pântano Apagados', '', '', '', '', '', '', '', 'Fale novamente com Feralon Verdefólio no Bosque do Verdião, que fica no Pantanal.', 0),
(25940, 'ptBR', 'Resistência no Bosque Silvante', 'Apresente-se ao Guardião Taldros no Bosque Silvante, que fica no Monte Hyjal.', 'Graças ao seu trabalho no Inferno, talvez ainda tenhamos uma chance de conter as chamas.$B$BMesmo assim, a vida selvagem ainda está ameaçada. O guardião Taldros correu para o Bosque Silvante, a norte, atravessando o incêndio.$B$BVeja se você pode ajudá-lo em alguma coisa!', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Guardião Taldros no Bosque Silvante, que fica no Monte Hyjal.', 0),
(25941, 'ptBR', 'Descanso para os exaustos', 'Fale com o Legionário Nazgrim.', 'Você agiu bem, $r, mas há muito mais a fazer e estou cada vez mais exausto.$b$bGastei muita energia para mandar o pedido de ajuda para os líderes da Harmonia Telúrica, implorando pelo socorro deles.$b$bPreciso descansar para continuar sendo de utilidade por aqui.$b$bFale com o líder dos homens que você salvou e faça o que puder para prepará-los para a batalha.$b$bAs nagas estão vasculhando as águas em busca de nós... É apenas uma questão de tempo até que elas voltem – e é certo que virão com mais força ainda.', '', '', '', '', '', '', '', '', '', '', 0),
(25942, 'ptBR', 'Ganhando algum tempo', 'Mate 8 Saqueadores Zin\'jatar no Destino da Legião.', 'Perdemos muitos bons guerreiros hoje.$b$bSe o que o xamã diz é verdade, precisamos agir rápido se não quisermos ter o mesmo destino de nossos derrotados.$b$bAs nagas estão vasculhando estas águas em busca de sobreviventes.$b$bAinda não estamos prontos para lutar. Você precisa ganhar tempo para que nos preparemos, $r.$b$bEncontre as nagas que nos caçam e atrase os esforços delas.', '', 'Saqueadores Zin\'jatari mortos', '', '', '', '', '', '', '', 'Fale com o Legionário Nazgrim na Espiral Imortal.', 0),
(25943, 'ptBR', 'Saco vazio não fica em pé', 'Colete 8 pedaços de Carne Suculenta de Caranguejo de Pateantes Garrabífidas.', 'Vou precisar da sua ajuda para preparar esses orcs para a batalha.$b$bQualquer líder decente sabe que os homens precisam de comida para marchar e lutar. Sem comida, sem vitória.$b$bEstes guerreiros estão fracos desde a última luta. Eles precisam de comida para suportarem um ataque naga.$b$bFalando nisso, eu vi vários caranguejos lá no fundo do mar...', '', '', '', '', '', '', '', '', '', 'Fale com o Legionário Nazgrim na Espiral Imortal.', 0),
(25944, 'ptBR', 'Preparando o nosso lombo', 'Colete 5 Machados de Orgrimmar, 5 Peitorais de Orgrimmar e 5 Elmos de Orgrimmar do fundo do mar e de Ladravazes Guelblin no Destino da Legião.', 'Enquanto lutávamos para não nos afogar, meus orcs e eu nos vimos forçados a largar nossas armas e boa parte da nossa armadura.$b$bO Erunak diz que é para esperarmos um grande ataque das nagas em breve, e acredito nele.$b$bPara sairmos vitoriosos, precisaremos da sua ajuda para recuperar o nosso equipamento perdido. Ele deve estar espalhado pelo fundo do mar, perto dos restos dos nossos navios, aqui e ao norte.$b$bApresse-se, $r. O inimigo pode chegar a qualquer momento.', '', '', '', '', '', '', '', '', '', 'Fale com o Legionário Nazgrim na Espiral Imortal.', 0),
(25945, 'ptBR', 'Estamos aqui para fazer uma coisa, talvez duas...', 'Embarque na Carroça de Krom\'gar rumo ao Nicho, que fica na Cordilheira das Torres de Pedra.', 'Você está no exército de Grito Infernal agora, $n, e, no exército de Grito Infernal, a gente desce o cacete. Foram-se os dias em que o nosso povo morria de fome pelas ruas de Orgrimmar enquanto assinávamos tratados com os elfos. Agora, pegamos o que precisamos. Kalimdor pertence à Horda!$B$BA Aliança tenta barrar nossa expansão sempre que pode. Não satisfeitos com a posse da maior parte dos Reinos do Leste, aqueles filhos de um kodo querem tudo!$B$BO suserano Krom\'gar convocou mais tropas às Torres de Pedra. Suba no carroção a oeste daqui e vá!', 'Chegada ao Nicho na Carroça de Krom\'gar', '', '', '', '', 'Chegada ao Nicho na Carroça de Krom\'gar', '', '', '', 'Apresente-se a Saurboz no Nicho, que fica na Cordilheira das Torres de Pedra, e junte-se ao exército de Krom\'gar.', 0),
(25946, 'ptBR', 'Os segredos do elmo', 'Leve o Equipamento F.O.C.A. da Aliança para o Legionário Nazgrim na Espiral Imortal.', 'Este elmo e seus componentes associados estão marcados com o selo de Ventobravo. Certamente, isso foi lançado de uma embarcação da Aliança que sofreu um destino similar ao seu.$b$bOlhando de perto, isto parece complexo e resistente demais para ser um equipamento normal de mergulho. Talvez Nazgrim possa dar alguma luz sobre isso...', '', '', '', '', '', '', '', '', '', 'Fale com o Legionário Nazgrim na Espiral Imortal.', 0),
(25947, 'ptBR', 'Achado não é roubado', 'Colete 5 peças do Equipamento F.O.C.A. de Ventobravo.', 'Reconheço este elmo, $r. Você foi sábi$go:a; de trazê-lo a mim.$b$bA Aliança tem uma unidade especial treinada e equipada para combates submarinos.$b$bParece que eles não estão nesta região só para defender o nosso ataque.$b$bDeve haver mais destes aqui embaixo, e, se você conseguir encontrá-los, isso pode virar o jogo para a Vanguarda.', '', '', '', '', '', '', '', '', '', 'Fale com o Legionário Nazgrim na Espiral Imortal.', 0),
(25948, 'ptBR', 'Podem vir com tudo!', 'Fale com o Legionário Nazgrim a bordo da Espiral Imortal.', 'Chegou a hora, $c.$b$bNão vamos ficar mais prontos que isso!$b$bVou falar com a Vanguarda e, então, nadaremos mar adentro rumo ao nosso destino.', '', '', '', '', '', '', '', '', '', 'Fale com o Legionário Nazgrim na Espiral Imortal.', 0),
(25949, 'ptBR', 'Sangue e trovão!', 'Auxilie o Legionário Nazgrim na defesa da Espiral Imortal.', 'Chegou o momento de nos impormos, $r.$b$bVamos defender este navio até a morte e fazer essas nagas pensarem duas vezes antes de se aproximarem novamente!$b$bPela Horda!', '', 'Defesa da Espiral Imortal completa', '', '', '', '', '', '', '', 'A Espiral Imortal foi perdida. Fale com Erunak em Beira Fundo.', 0),
(25950, 'ptBR', 'Extermínio das Sira\'kess', 'Mate 10 Nagas Sira\'kess.', 'Então você é $go:a; $n de quem todo mundo anda falando, que vive por aí, lutando e batalhando? É um prazer conhecê-$glo:la;, $gparceiro:parceira;!$B$BMas chega de conversa fiada, vamos ao que interessa. Preciso que você nade para noroeste, no Front Sira\'kess, onde estão aquelas cobras cafajestes. Vá lá acabe com elas!$B$BE pode cair matando: elas estão procurando treta, e é isso que vão ter!', '', 'Nagas Sira\'kess mortas', '', '', '', '', '', '', '', 'Fale novamente com a Tenente Topper, a "Gostosa", no Covil do Abismo Sombrio em Vashj\'ir.', 0),
(25951, 'ptBR', 'Julgamento final', 'Proteja a ponte do Terraço de Quel\'Durmar até que os aliados da Lady Sira\'kess apareçam.$B$BEssa missão faz parte da visão da Dama Guerreira Naz\'jar. Caso necessário, use a Lâmina da Dama Guerreira Naz\'jar em um foco temporal para voltar à visão.', 'Vá para a ponte a leste, rápido! Lady Naz\'jar e o Senhor das Profundezas devem estar lá com o resto das tropas.$B$BComo sempre, siga as instruções da Dama e proteja a ponte até que possamos completar o ritual.$B$BQuando nossos aliados chegarem, os kvaldir estarão arruinados.', '', 'Proteja a extremidade leste do Terraço de Quel\'Durmar.', 'Force os kvaldir a recuar na ponte', '', '', '', '', '', '', 'Fale com a Lady Naz\'jar no Terraço de Quel\'Durmar.', 0),
(25952, 'ptBR', 'Pego de surpresa', 'Mate 10 Patrulheiros Azsh\'ir.', 'Com certeza notaram que fugimos da concha, mas parece que as nagas das ruínas não foram informadas ou não nos consideram uma ameaça. Porém, é melhor não aceitarmos isso como verdade – a hora de atacar é agora.$B$BPreciso que você entre no nível inferior das ruínas, a oeste daqui, e acabe com o máximo de patrulhas nagas que puder. Não podemos arriscar que qualquer uma dessas patrulhas nos encontre nesta caverna. Assim, não deixe nenhuma delas escapar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Vilespinho no Repouso da Legião.', 0),
(25953, 'ptBR', 'Ataque preventivo', 'Destrua 8 Monitores Azsh\'ir.', 'Tomei a liberdade de fazer uma inspeção preliminar do local. As nagas podem não saber da nossa posição, mas não estão totalmente despreparadas.$B$BAlém das patrulhas, elas usam dispositivos mágicos de vigia, que as avisarão caso detectem qualquer visitante indesejado. Felizmente, parece que elas sacrificaram qualidade por quantidade, e há uma brecha nos dispositivos, que permite destruí-los antes dos alarmes serem respondidos.$B$BAcredito que você pode tomar conta disso antes que os outros soldados cheguem ao local.', '', 'Monitor Azsh\'ir destruído', '', '', '', '', '', '', '', 'Fale com o Legionário Nazgrim no Repouso da Legião.', 0),
(25954, 'ptBR', 'Investigação aquática', 'Investigue 4 estátuas intactas nos Jardins de Vashj\'ir.', 'Veja bem... $n – é esse o seu nome mesmo? – preciso da sua ajuda! Sei que a maioria acha que só devemos nos preocupar com nossas vidas no momento, mas não posso me esquecer dos meus ancestrais tão facilmente.$B$BEssa era uma das cidades reais dos elfos nos dias em que Azshara era rainha. Aqui se encontram histórias perdidas no tempo e artefatos de valor histórico inimaginável. Enquanto estiver lá fora, fique atento para qualquer objeto importante. Observe principalmente as estátuas.', '', 'Estátua de Lestharia Vashj', 'Estátua da Rainha Azshara', 'Estátua do Patrulheiro Valarian', 'Estátua da Alta-sacerdotisa Siralen', '', '', '', '', 'Fale novamente com Elendri Testadouro no Repouso da Legião.', 0),
(25955, 'ptBR', 'Estabelecendo uma posição favorável', 'No nível mais baixo das ruínas, vasculhe: a extremidade norte dos Jardins de Quel\'Durmar, a passagem que leva para baixo das ruínas a oeste dos jardins, e as estruturas no canto sudeste das ruínas sob as pontes.', 'Esta caverna é nossa única proteção, e não há nenhum tipo de ajuda a caminho. Aconteça o que acontecer, esta caverna tem que permanecer segura ou todos nós morreremos aqui dentro.$B$BPrecisamos de um posto mais avançado para podermos lançar nossos ataques, mas que também possa ser defendido.$B$BNa parte leste das ruínas, no nível inferior, vasculhe: a extremidade norte dos jardins, a passagem sob a estrutura principal a oeste dos jardins, e o conjunto de prédios no canto sudeste das ruínas sob as pontes.$B$BTraga-me qualquer informação que encontrar.', '', 'Jardins de Quel\'Durmar ao norte vasculhados', 'Túnel a oeste dos Jardins de Quel\'Durmar vasculhado', 'Estruturas ao sul dos Jardins de Quel\'Durmar vasculhadas', '', '', '', '', '', 'Fale novamente com o Capitão Vilespinho no Repouso da Legião.', 0),
(25956, 'ptBR', 'Na cena de batalha', 'Leve o estilhaço partido de volta para o Repouso da Legião.', 'Ao seu redor encontram-se os resquícios de uma batalha cruel. Os esqueletos das nagas não são surpresa nenhuma, mas as armas e os restos dos aparentes oponentes são, de certa forma, inesperados.$B$BNo meio dos ossos, você encontra uma estranha e talvez importante peça de metal cravada em um dos crânios. É difícil dizer de que tipo de arma a peça fazia parte, mas ela se destaca o suficiente para ser levada como evidência.$B$BCom certeza alguém na caverna terá interesse nessa descoberta.', '', '', '', '', '', '', '', '', '', '', 0),
(25957, 'ptBR', 'Visões do passado: a invasão de Vashj\'ir', 'Use a Lâmina da Dama Guerreira Naz\'jar no campo de batalha na extremidade sudeste das ruínas.', 'O estilhaço que você recuperou parece ser de origem naga. Eu esperava um objeto como esse para usar em um feitiço que venho preparando há certo tempo, que nos permitirá enxergar o passado.$B$BEncantei a lâmina, mas será preciso levá-la ao local onde estava seu dono. Viaje de volta ao local onde a encontrou e use-a.$B$BTalvez, assim, descubramos mais a respeito do que as nagas estão fazendo aqui, ou, melhor ainda, um ponto fraco – o que aumentará nossas chances.', '', 'Harmonia com o Dono da Lâmina Quebrada', '', '', '', '', '', '', '', 'Fale com a Falaondas Tulra nas Ruínas de Vashj\'ir.', 0),
(25958, 'ptBR', 'Prevenindo o pior', 'Encontre e fale com o Capitão Vilespinho ao norte das Ruínas de Vashj\'ir.$B$BUse o cavalo-marinho da Falaondas Tulra para chegar até o posto avançado rapidamente.', 'O Capitão usou as informações que você trouxe para montar um posto avançado sob o terraço a oeste. Ele está preparando um ataque contra as nagas.$B$BVá até ele imediatamente e informe-o sobre a dimensão das forças das nagas. Temos poucos homens, e temo por eles caso nos lancemos em um ataque descuidado.$B$BTome meu cavalo-marinho, ele sabe o caminho.', '', '', '', '', '', '', '', '', '', '', 0),
(25959, 'ptBR', 'Objetivos claros', 'Mate 10 tropas nagas que se reúnem sob o terraço a sudoeste, no térreo do local.', 'Entendo. As notícias que você traz não são boas, mas eu não estava completamente despreparado para essa possibilidade. Sem examinar as forças das nagas de perto, sabia que nosso plano era arriscado, mas é exatamente por isso que estabelecemos este posto avançado.$B$BDeixe-me explicar de forma mais clara, $c. Se não mantivermos as nagas ocupadas, elas é que nos atacarão. Não temos nem a estrutura nem os homens para nos defender, assim, isso está fora de questão.$B$BVocê poderia acabar com algumas nagas ao sul para ganharmos tempo?', '', 'Tropas das nagas ao sul mortas', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Vilespinho ao norte das Ruínas de Vashj\'ir.', 0),
(25960, 'ptBR', 'Não completamente despreparado', 'Leve 8 Pacotes de Setas de Besta para os Vigias da Horda posicionados em volta da extremidade norte dos Jardins de Quel\'Durmar.', 'Por acaso ouvi sua conversa com o Capitão. Sei que parece que estamos malucos, mas realmente não temos muitas opções. A vida de muitas pessoas na caverna depende de nós.$B$BColoquei vigias em várias saliências da área logo em frente, e eles não estão hesitando em abater as patrulhas nagas no local. Você poderia levar mais munição para eles, pois assim ganharemos mais tempo.', '', 'Vigia da Horda reabastecido', '', '', '', '', '', '', '', 'Fale novamente com o Legionário Nazgrim ao norte dos Jardins de Quel\'Durmar.', 0),
(25961, 'ptBR', 'Curious Distraction', 'Transcribe the 4 Highborne Tablets.', 'Hah! Did you see the Captain giving me dirty looks and decide you\'d throw some sympathy my way? I\'ve pretty much lost hope of making him understand that these ruins offers us some opportunity to salvage some usefulness out of this whole mess.$B$BI\'d actually hoped that you might turn up again - you seem like the only one I can rely on. I\'ve seen a few tablets like this one spread about the nearby ruins and I put together a rubbing kit for transcribing them. Up to the task?', '', 'Messy Rubbing', 'Torn Rubbing', 'Smudged Rubbing', 'Smeared Rubbing', '', '', '', '', 'Return to Elendri Goldenbrow north of the Quel\'Dormir Gardens.', 0),
(25962, 'ptBR', 'Hora de improvisar', 'Colete 8 Bulbos Inchados de Alga que ficam pendurados sob o terraço a sudoeste.', 'Sabe como é. Estive em todos os lugares, explodi todos os tipos de coisas. Pensei que talvez a coisa fosse mais difícil aqui embaixo, com toda essa água, mas no final é tudo uma questão de... improvisação!$B$BEncontrei um material volátil o suficiente para fazer as bombas! Há várias algas penduradas no terraço a sudoeste daqui. As algas normais costumam armazenar um gás que as faz flutuar, porém, as daqui produzem um gás um pouco diferente e mais denso, capaz de fazer as coisas explodirem.$B$BQue acha de coletar algumas para mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fiasco Girafuso ao norte dos Jardins de Quel\'Durmar.', 0),
(25963, 'ptBR', 'Ação rápida', 'Fale com Fiasco Girafuso do lado de fora do prédio para tomar parte no ataque, e então use os explosivos improvisados para matar 100 Soldados Azsh\'ir, 20 Gritaondas Azsh\'ir e 12 Arkaens Azsh\'ir.', 'Já temos tudo o que precisamos para começar o ataque.$B$BSe o que você diz é verdade, é melhor segurar firme em sua montaria quando atacarmos. Quem for pego em mar aberto não vai nadar mais rápido que uma naga.$B$BMate quantos inimigos conseguir enquanto atacamos. Vamos nos encontrar na saliência quebrada do terraço sul, mais acima, logo após usarmos nossos explosivos. Com sorte haverá bem menos nagas e então poderemos acabar com elas à moda antiga.', '', 'Falar com Fiasco Girafuso', '', '', '', '', '', '', '', 'Fale com o Capitão Vilespinho no Terraço de Nar\'shola.', 0),
(25964, 'ptBR', 'Caídos, mas não esquecidos', 'Resgate 6 Voluntários do Ataque Feridos', 'Foi um desastre! A maioria dos nossos homens foi abatida pelas lanças das nagas antes mesmo de chegarem ao ponto de encontro.$B$BLogo que as nagas nos atacarem, perderemos nossa posição. Precisamos sair daqui, seguir para sudoeste e salvar a maior quantidade de homens que pudermos encontrar! Faça tudo o que puder!$B$BEles não ficarão vivos por muito tempo!', '', 'Voluntários do Ataque Feridos resgatados', '', '', '', '', '', '', '', 'Fale novamente com o Legionário Nazgrim no Terraço de Nar\'shola.', 0),
(25965, 'ptBR', 'Avaliando o sucesso', 'Examine a área noroeste do terraço circular e o túnel sob as escadas principais ao norte. Ambos os locais se encontram no Terraço de Nar\'shola, o nível intermediário das ruínas.', 'Malditas nagas... aquelas lanças deixaram nossos homens seriamente feridos.$B$B<O Capitão faz uma cara de dor enquanto aperta um ferimento.>$B$BVamos ficar aqui e proteger o local até todos os homens retornarem. Enquanto isso, preciso de alguém para verificar a quantidade atual de nagas e saber se nosso ataque foi efetivo.$B$BUm dos maiores grupos de nagas estava na esquina da área a noroeste do terraço, enquanto outro se encontrava um pouco mais longe, ao norte, em um pequeno túnel, também no nível intermediário das ruínas.$B$BVocê não gostaria de fazer o serviço?', '', 'Examinar o túnel ao norte', 'Examinar o terraço a noroeste', '', '', '', '', '', '', 'Fale novamente com o Capitão Vilespinho no Terraço de Nar\'shola.', 0),
(25966, 'ptBR', 'Visões do passado: o massacre da Crista Biel\'aran', 'Assista à história da Dama Guerreira usando a lâmina quebrada no local da morte do general kvaldir.', 'Sei que posso parecer abusiva num momento tão difícil, mas preciso que você esqueça tudo isso por um breve momento.$B$BEnquanto cuido dos soldados, encontre o local onde aconteceu a batalha com o general kvaldir, a oeste, como você me falou. De lá será possível descobrir mais sobre a Dama Guerreira. Tenho um forte pressentimento de que o segredo para derrotar as nagas tem relação com ela.$B$BVá depressa, farei tudo o que puder para ganhar tempo.', '', 'Observe a história da Dama Guerreira', '', '', '', '', '', '', '', 'Fale com a Falaondas Tulra no Terraço de Nar\'shola.', 0),
(25967, 'ptBR', 'Perdendo terreno', 'Use o cavalo-marinho da Falaondas Tulra para retornar ao Capitão Vilespinho ao norte das Ruínas de Vashj\'ir.', 'Terás de me contar as novidades mais tarde. Agora, precisamos sair daqui antes que as nagas nos ataquem. Volta ao posto avançado no nível abaixo de nós.$B$BUsa meu cavalo-marinho. Encontramo-nos lá em breve.', '', 'Retorno ao posto avançado', '', '', '', '', '', '', '', 'Escape para o Repouso da Legião.', 0),
(25968, 'ptBR', 'Plano de emergência', 'Encontre-se com Fiasco Girafuso na Crista Biel\'aran.', 'Toldrek e Fiasco partiram para conseguir ajuda. As rotas comerciais não ficam muito longe daqui, então talvez tenhamos uma chance de sucesso, mas estou tomando cuidado para que ninguém fique muito esperançoso.$B$BNa verdade, essa é nossa última opção. Não sobreviveremos por muito mais tempo aqui. Hora ou outra, as nagas nos encontrarão e... bem... você viu muito bem quantas nagas havia lá embaixo.$B$BVá encontrar Jordan e Hexasfrega na Crista Biel\'aran a sudeste. Manterei todos aqui em segurança o máximo de tempo que puder.', '', '', '', '', '', '', '', '', '', '', 0),
(25969, 'ptBR', 'Águas hostis', 'Mate 10 Bicões Pelancalamas.', 'O Fiasco veio aqui com um tipo de balão, que trouxe de uma das nossas embarcações. Ele tentou fazer com que a coisa flutuasse até a superfície, mas aqueles Bicões Pelancalamas apareceram do nada para atrapalhar.$B$BEle resolveu usar outro balão, mas para isso temos que garantir que não teremos mais problemas com os guelblins. Preciso que você acabe com eles, assim eles pensam duas vezes antes de nos atrapalhar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fiasco Girafuso na Crista Biel\'aran.', 0),
(25970, 'ptBR', 'É melhor se preparar', 'Recupere um Kit de Sobrevivência da Horda.', 'Não demora muito para nadar até a superfície. Rapidinho você chega lá. O problema é que é difícil levar qualquer suprimento até lá, pois eles são muito pesados.$B$BTodas as embarcações das frotas da Horda carregam kits de sobrevivência. Tenho um balão do kit antigo, mas tive alguns problemas com ele e agora preciso de outro kit de sobrevivência.$B$BHá um navio para sudeste. Espero que os sobreviventes deste tenham sido tolos o bastante para não usarem o kit de sobrevivência, assim podemos usá-lo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fiasco Girafuso na Crista Biel\'aran.', 0),
(25971, 'ptBR', 'Corda cabeluda', 'Colete 8 Rolos de Corda Kvaldir.', 'Como lhe falei, os kits de sobrevivência nunca trazem cordas. Isso não faz sentido nenhum! Cordas e bombas, é tudo isso que eles têm que trazer. O resto é apenas tralha desnecessária!$B$BÉ, tem esse balão, que está se mostrando muito útil no momento.$B$BTenho certeza que aqueles kvaldir têm cordas. Eles estão sempre andando por aí em barcos, fazendo nós, preparando redes... Veja se consegue umas cordas com eles! Precisamos de algumas para o nosso plano funcionar, não há dúvidas quanto a isso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fiasco Girafuso na Crista Biel\'aran.', 0),
(25972, 'ptBR', 'Fazendo as honras', 'Nade até a superfície, pegue o sinalizador e use-o na direção das embarcações da Horda.', 'Tudo pronto! Estou confiante de que vai funcionar. E nenhum bicão por perto para atrapalhar! Perfeito.$B$BToldrek já está na superfície esperando, todo preocupado com as correntes e tudo mais. Ele me disse que as honras serão suas. Cara legal, não sei como ainda existe gente que nem ele!$B$BVá para a superfície com o balão, pegue o sinalizador na caixa e procure por embarcações da Horda no horizonte. Se você vir alguma, atire com o sinalizador na direção dela e pronto, simples assim!$B$BNadar, flutuar, sinalizar e resgatar – aliás, ser resgatado, que é a parte que eu prefiro.', '', 'Nade até o balão de resgate na superfície', 'Dispare o sinalizador na direção das embarcações da Horda', '', '', '', '', '', '', 'Fale com o Guarda-de-Sangue Toldrek na superfície, acima da Crista Biel\'aran.', 0),
(25973, 'ptBR', 'Notícias de boas-vindas', 'Fale novamente com o Legionário Nazgrim no Repouso da Legião.', 'Eles provavelmente enviarão um esquife, o que pode demorar um pouco. Ficarei aqui para falar com eles.$B$BVocê precisa voltar à caverna imediatamente e informá-los de que o resgate está a caminho. Espero que as nagas ainda não tenham chegado lá.$B$BVá, nada o mais rápido que puder, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(25974, 'ptBR', 'Extermínio das Sira\'kess', 'Mate 10 Nagas Sira\'kess.', 'Então você é $go:a; $n de quem todo mundo anda falando? É um prazer conhecê-$glo:la;.$B$BBom, chega de conversa, certo? Vamos ao que interessa. Preciso que você nade para noroeste, para o Front Sira\'kess, e acabe rapidamente com aquelas nagas.$B$BSem frescuras! Elas querem briga, então é isso que terão!', '', 'Nagas Sira\'kess mortas', '', '', '', '', '', '', '', 'Fale novamente com a Sargento Gertrudes na Caverna Tenebrosa em Vashj\'ir.', 0),
(25975, 'ptBR', 'Reivindicação do tesouro', 'Colete 6 Tesouros das Barbatanas', 'Nossos reforços já chegaram, mas ainda temos que achar uma maneira de lhes pagar. E, como você deve saber, esse tipo de serviço não sai barato.$B$BNa Crista das Barbatanas, a noroeste, aqueles guelblins nojentos roubaram uma quantidade enorme de tesouros. Acho que chegou a hora de recuperarmos essas riquezas e pagarmos as contas!', '', '', '', '', '', '', '', '', '', 'Apresente-se a Jorlan Gumecerto no Covil do Abismo Sombrio, que fica em Vashj\'ir.', 0),
(25976, 'ptBR', 'Reivindicação do tesouro', 'Colete 6 Tesouros das Barbatanas.', 'Sangue e trovão! Nossos reforços já estão aqui, mas ainda temos de lhes pagar, o que não é barato.$B$BNa Crista das Barbatanas, a noroeste, aqueles guelblins nojentos roubaram uma quantidade enorme de tesouros. Acho que chegou a hora de os recuperarmos em nome da Horda!$B$BOs olhos de Grito Infernal estão sobre você, $n!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-Sangue Toldrek na Caverna Tenebrosa em Vashj\'ir.', 0),
(25977, 'ptBR', 'Mais um dia na vida de Azrajar', 'Crave o Estandarte da Aliança no cadáver do Invocador das Profundezas Azrajar.', '$n, as nagas estão perseguindo nossas tropas loucamente. Preciso que você volte à Crista das Barbatanas, a noroeste, e meta o pau na chefia do inimigo.$B$BElas vão vazar para longe daqui com o rabo entre as... ops, creio que elas não têm pernas, têm?', '', 'Estandarte cravado no cadáver de Azrajar', '', '', '', '', 'Invocador das Profundezas Azrajar', '', '', 'Fale novamente com a Tenente Topper, a "Gostosa", no Covil do Abismo Sombrio em Vashj\'ir.', 0),
(25978, 'ptBR', 'Caindo numa fria', 'Rompa 6 Tumbas Geladas para libertar os Montanhistas Congelados que estão presos no Lago Helm.', 'O Khorgorn me disse que o cataclismo perturbou o equilíbrio dos elementos por todo o mundo. O Lago Helm, a sul daqui, costumava ser um belo remanso, mas agora está repleto de elementais da água em convulsão. Quando eles começaram a se levantar do fundo do lago, eu logo enviei tropas para tentar contê-los, mas a maioria dos montanhistas foi transformada em blocos de gelo.$B$BSe conseguirmos libertá-los, talvez ainda tenhamos uma chance. Não posso deslocar mais tropas para uma segunda expedição ao lago. Você poderia tentar?', '', 'Montanhistas Congelados libertados', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Bahrum no Posto de Bahrum.', 0),
(25979, 'ptBR', 'Surto elemental', 'Mate 6 Rebentadores do Lago Helm no Lago Helm.', 'Os elementos estão instáveis, $c. O cataclismo perturbou os espíritos da água há muito adormecidos no Lago Helm, a sul daqui. Eles estão confusos, enfurecidos e nem um pouco dispostos a escutar meus apelos.$B$BEu tentei de tudo para acalmá-los, para persuadi-los a parar com os ataques aos montanhistas do Sargento, mas nada adiantou.$B$BÉ difícil admitir isso, mas não me resta outra opção a não ser matar os elementais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Khorgorn Chamuscapena no Posto de Bahrum.', 0),
(25980, 'ptBR', 'Mais um dia na vida de Azrajar', 'Crave o Estandarte da Horda no cadáver do Invocador das Profundezas Azrajar.', '$n, as nagas estão perseguindo nossas tropas. Preciso que você volte à Crista das Barbatanas, a noroeste, e crave nosso estandarte no general inimigo, o Invocador das Profundezas Azrajar.$B$BElas vão nadar para longe daqui com o rabo entre as... ops, creio que elas não têm pernas, têm?', '', 'Estandarte cravado no cadáver de Azrajar', '', '', '', '', 'Invocador das Profundezas Azrajar', '', '', 'Fale novamente com a Sargento Gertrudes na Caverna Tenebrosa em Vashj\'ir.', 0),
(25981, 'ptBR', 'Tudo menos máscaras', 'Colete 6 Cabeças Impiedosas.', '$n, estamos tendo problemas com uns demônios lulas que estão comendo as cabeças dos pobres guelblins e tomando controle dos coitados! Isso sim que é escravidão!$B$BO que acha de nadar até a Crista das Barbatanas, a noroeste, ou até o Front Sira\'kess, e me trazer alguns desses perversos?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Engenheiro Hexasfrega no Covil do Abismo Sombrio em Vashj\'ir.', 0),
(25982, 'ptBR', 'Tudo menos máscaras', 'Colete 6 Cabeças Impiedosas.', '$n, estamos tendo problemas com uns demônios lulas que estão comendo as cabeças dos pobres guelblins e tomando o controle dos coitados. Espero que eles não venham aqui!$B$BO que acha de nadar até a Crista das Barbatanas, a noroeste, ou até o Front Sira\'kess, e me trazer alguns desses demônios? De preferência mortos, claro.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fiasco Girafuso na Caverna Tenebrosa em Vashj\'ir.', 0),
(25983, 'ptBR', 'Promontório', 'Fale com o Capitão Taylor no Promontório em Vashj\'ir.', 'Precisamos levar essas informações para o Capitão Taylor a noroeste, no Promontório. Ele está lá junto com Erunak Falapedra e a Harmonia Telúrica.', '', '', '', '', '', '', '', '', '', '', 0),
(25984, 'ptBR', 'Promontório', 'Fale com o Legionário Nazgrim no Promontório em Vashj\'ir.', '$n, preciso que você leve essas informações para o Legionário Nazgrim a noroeste, no Promontório. Ele está lá com Erunak Falapedra e os outros da Harmonia Telúrica.', '', '', '', '', '', '', '', '', '', '', 0),
(25985, 'ptBR', 'Asas de Hyjal', 'Encontre Choluna no Santuário de Aviana, no Monte Hyjal.', '$n, é verdade que você vai tentar entrar em comunhão com os anciãos?$B$BO Santuário de Aviana, a matriarca de todas as criaturas aladas, fica a sudoeste daqui. É o lar da minha instrutora favorita, que se chama Choluna. Eu nunca conheci alguém mais conectado com os espíritos deste mundo. Ela tem muito a ensinar!$B$BOs últimos ataques isolaram o santuário, mas é fácil chegar lá voando. Procure a segunda maior árvore de Hyjal. Boa sorte!', '', '', '', '', '', '', '', '', '', 'Encontre Choluna no Santuário de Aviana, no Monte Hyjal.', 0),
(25986, 'ptBR', 'Problemas no lago', 'Fale com o Sargento Bahrum no Posto de Bahrum.', 'Você foi de grande ajuda na proteção das minas e no resgate dos mineradores aprisionados.$B$BO Senado ficará animado em saber que você e os montanhistas do capitão Tharran fizeram avanços na proteção de Dun Morogh.$B$BO que me preocupa é que ainda não recebi notícias do sargento Bahrum e de sua guarnição. Eles rumaram para leste, pela estrada que leva para o Lago Helm, com ordens de estabelecer um pequeno posto avançado. Você poderia ir até o Posto de Bahrum e conferir se o Sargento está bem?', '', '', '', '', '', '', '', '', '', '', 0),
(25987, 'ptBR', 'Cai de cabeça', 'Observe o que acontece ao "vestir" o Impiedoso na cabeça.', 'Ei, $n, tenho uma ideia para um disfarce! Pegue um desses bichos danados e coloque na cabeça.$B$BO que poderia dar errado?$B$BEstá $gpronto:pronta;?', 'Impiedoso vestido', '', '', '', '', 'Impiedoso vestido', '', '', '', 'Fale com o Engenheiro Hexasfrega no Covil do Abismo Sombrio em Vashj\'ir.', 0),
(25988, 'ptBR', 'Cai de cabeça', 'Observe o que acontece ao "vestir" o Impiedoso na cabeça.', 'Tenho uma ideia para um ótimo disfarce, mas precisarei da sua ajuda, $n! Pegue desses bichos danados e coloque na cabeça.$B$BEu sei, eu sei! Mas a coisa está morta, o que poderia dar errado além de você ficar fedendo por alguns dias?$B$BEstá $gpronto:pronta;?', 'Impiedoso vestido', '', '', '', '', 'Impiedoso vestido', '', '', '', 'Fale com Fiasco Girafuso na Caverna Tenebrosa em Vashj\'ir.', 0),
(25989, 'ptBR', 'Capture o caranguejo', 'Use a Rede de Duarn para capturar um Caranguejo Buscafundo dentro de Nespirah.', 'Tudo no meu corpo me diz que Nespirah está tentando falar comigo, mas não consigo escutá-la. Talvez as nagas tenham feito algo com a voz dela.$b$b<Duarn pensa com seus botões por um momento.>$b$bA voz de Nespirah pode estar suprimida... isso quer dizer que... precisamos encontrar uma voz para ela!$b$bJá sei! Os Idra\'kess são conhecidos por treinarem caranguejos buscafundo como companheiros de batalha. Use esta rede para capturar um caranguejo e traga-o a mim. Você deve encontrá-los vagando ao redor da câmara.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Reparador da Terra Duarn dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25990, 'ptBR', 'Abrindo caminho', 'Observe enquanto o Reparador da Terra Duarn tenta falar com Nespirah.', 'Um xamã treinado tem a habilidade de se comunicar com os quatro elementos – terra, fogo, ar e água. Isso é sabido.$b$bO que poucos sabem, contudo, é que há um quinto elemento. Esse elemento não é tão claramente descrito quanto os outros quatro, mas tem a ver com os... atributos comuns a todas as criaturas vivas.$b$bA minha teoria é que o caranguejo, criatura marinha que é, é próximo o bastante de Nespirah para que, com a influência dos elementos, consigamos convencê-lo a agir como porta-voz dela.', 'Fale com o Reparador da Terra Duarn', '', '', '', '', 'Fale com o Reparador da Terra Duarn', '', '', '', 'Fale novamente com o Reparador da Terra Duarn dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25991, 'ptBR', 'Não estamos sozinhos', 'Encontre os sobreviventes da Horda dentro de Nespirah, que fica em Vash\'jir.', '<Duarn fecha os olhos, para por um momento e balança a cabeça.>$b$bNespirah acabou de me informar que não somos os únicos lutando dentro desta concha. Um pequeno grupo de escravos da Horda escapou e está combatendo as nagas do outro lado da concha, em cima da borda que dá vista para o coração de Nespirah.$b$bVá ao encontro deles, $n, e veja se eles podem nos ajudar. Com o auxílio deles, talvez sejamos capazes de despertar Nespirah desse torpor.$b$bContinuarei aqui, caso você precise de alguma coisa.', '', '', '', '', '', '', '', '', '', '', 0),
(25992, 'ptBR', 'Totalmente desequipado', 'Obtenha 4 Armas de Haste Furtadas dos cavaletes de armas dentro de Nespirah.', 'Eu honestamente não sei como sobrevivemos até agora. As nagas levaram a minha armadura e as minhas armas, deixaram-me com farrapos e uma picareta de mineração... e ATÉ ELA quebrou há meia hora.$b$bPara termos alguma chance de virar o jogo, vou precisar de alguma coisa para lutar... Assim como os meus companheiros, mesmo que eles sejam orgulhosos demais para admitir.$b$bVi cavaletes de armas no depósito das nagas, aqui perto. Não estou acostumado a lutar com um tridente, mas é fato que me sairei melhor do que se eu lutasse apenas com os punhos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Vilespinho dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25993, 'ptBR', 'Golpes corporais', 'Ataque 7 Abscessos de Nespirah ao longo das paredes da câmara respiratória de Nespirah.', '<O legionário Nazgrim ouve atentamente o seu relato da conversa de Duarn e Nespirah.>$b$bEntendo. Então a criatura quer a nossa ajuda para acordar, não é isso?$b$bCom centenas de escravos picaretando as pérolas dela, a fera parece ter um sono bem pesado. Quem sabe você não tem mais sorte?$b$bMinha sugestão? Procure sinais de fraqueza pela carne da criatura. Talvez essa sua arma encontre um ponto sensível que faça a fera voltar a si.', '', 'Abscessos de Nespirah atacados', '', '', '', '', '', '', '', 'Fale novamente com o Legionário Nazgrim dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25994, 'ptBR', 'Não deixam de ser valiosas', 'Obtenha 5 Pérolas Misteriosas de Senhores da Guerra e Profetas Idra\'kess dentro de Nespirah.', 'Por mais que eu não tenha passado muito tempo nos poços de pérolas, fiquei curiosa quanto aos objetivos das nagas. Sim, agora sei que as nagas querem usar Nespirah como um motor de guerra, mas, se esse é o caso, então por que elas estão escravizando homens para minerar as pérolas?$b$bPresumindo que vamos conseguir fugir do casco dessa criatura, eu gostaria muito de poder estudar um desses objetos. As pérolas que encontramos nos poços eram grandes demais para carregar, mas já vi senhores da guerra e profetas carregando umas menores algumas vezes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Falaondas Tulra dentro de Nespirah, que fica em Vashj\'ir.', 0),
(25995, 'ptBR', 'Feitor Idra\'kess', 'Vá para o topo de Nespirah e mate o Feitor Idra\'kess.', 'Os meus homens estão em maus lençóis, $n. Receio que não vamos durar muito mais tempo contra essas nagas. Com as armas de Idra\'kess e as pérolas de Nespirah, acho que estamos prontos para nos mandarmos daqui.$b$bSiga a parede ao nordeste e procure uma rampa que leva para a câmara superior. Acredito que o líder delas esteja lá, ou talvez a chave para acordarmos Nespirah. Com sorte, as duas coisas.$b$bSe você estiver forte o suficiente, vá para o topo da concha e busque algumas respostas. Os olhos de Grito Infernal estarão voltados para você!', '', '', '', '', '', '', 'Feitor Idra\'kess', '', '', 'Apresente-se ao Reparador da Terra Duarn perto do cérebro de Nespirah, que fica em Vashj\'ir.', 0),
(25996, 'ptBR', 'Despertando a fera', 'Fale com o Reparador da Terra Duarn dentro de Nespirah, para ativar as defesas biológicas dela. Em seguida, escape do corpo de Nespirah.', 'Graças a você e ao legionário, Nespirah tem controle total do próprio corpo. Mas a maioria das nagas ainda não sabe disso. Depois de fugirmos, ela ativará as defesas biológicas e destruirá as nagas de dentro para fora.$b$bPrepare-se. Vou avisar Nespirah para começar a contagem regressiva.', '', 'Escute enquanto Duarn conversa com Nespirah', 'Escape montando no Cavalo-marinho de Erunak', '', '', '', '', '', '', 'Apresente-se ao Legionário Nazgrim no Repouso da Legião, que fica em Vashj\'ir.', 0),
(25997, 'ptBR', 'Armações dos Ferro Negro', 'Mate 5 Espiões Ferro Negro e tome os Planos de Ataque dos Ferro Negro do Capitão Beld no Complexo de Bandaferro.', 'Um grupo de espiões dos Ferro Negro tomou o Complexo de Bandaferro, que fica a sul daqui, além do Lago Helm. Antes do cataclismo, os montanhistas conseguiam mantê-los longe de Dun Morogh, mas tudo está fora da ordem agora.$B$BSeria uma estupidez se os anões de Dun Morogh não se aproveitassem desse momento de caos. Precisamos descobrir o que os espiões estão tramando e detê-los antes que possam nos prejudicar.$B$BVocê poderia tentar descobrir o que eles estão armando no Complexo de Bandaferro?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Bahrum no Posto de Bahrum.', 0),
(25998, 'ptBR', 'Vá voando para a base aérea!', 'Embarque na Máquina Voadora do Marcos na Pedreira Gol\'Bolar.', 'De acordo com os planos que você pegou, os Ferro Negro estão planejando um ataque de grande escala à Base Aérea de Altaforja! O concílio deslocou grande parte das nossas tropas para Dun Morogh a fim de lidar com a instabilidade gerada pelo cataclismo. Isso enfraqueceu as defesas da base aérea.$B$BPrecisamos dar um jeito de levar você à base aérea imediatamente. Pegue a estrada que leva a oeste, em direção à Pedreira Gol\'Bolar, e encontre Marcos Chaverrujem. Ele deve ter alguma máquina voadora para levar você até a base. Vai!', '', '', '', '', '', '', '', '', '', 'Fale com o Comandante Quebrapedra na Base Aérea de Altaforja.', 0),
(25999, 'ptBR', 'Entrada barrada', 'Arme 8 "Mata-elfos" de Krom\'gar', 'Os elfos noturnos, sujos e imprestáveis, conseguiram desarmar todo o nosso campo minado na Trilha Garracava. Alguém terá que voltar lá e armar as minas todas de novo! Uma tarefa perfeita para $Gum bruto:uma bruta; como você, $n. Espero que você não se exploda no processo.$B$BVocê encontrará nossos "mata-elfos" espalhados pela Trilha Garracava, diretamente a norte daqui. Leve esta chave de boca e trate de trabalhar, verme.', '', '"Mata-elfos" de Krom\'gar armados', '', '', '', '', '', '', '', 'Apresente-se a Saurboz no Nicho, que fica na Cordilheira das Torres de Pedra.', 0),
(26000, 'ptBR', 'Espeleologia', 'Fale com Gurrok na Gruta Densanévoa.', 'Depressa, $n!$b$bVá logo para aquela caverna.$b$bIremos atrás de você para garantir que você não está sendo seguid$go:a;.', '', '', '', '', '', '', '', '', '', '', 0),
(26001, 'ptBR', 'O cabumgenheiro desaparecido', 'Encontre o Cabumgenheiro Sussujo.', 'Talvez você não seja tão inútil assim, afinal de contas. Pode ser que você consiga lidar com algo um pouco mais importante.$B$BHá cerca de dois dias, enviei o cabumgenheiro Sussujo à Mina Cortavento. Ele deveria chegar lá, certificar-se de que as coisas estavam correndo conforme o esperado com a bomba e voltar com um relatório. Dois dias e nada...$B$BVá à floresta ao sul daqui e encontre-o. Para o próprio bem dele, é bom que ele esteja morto.', '', '', '', '', '', '', '', '', '', '', 0),
(26002, 'ptBR', 'Plano de ataque da Aliança', 'Consiga o Plano de Ataque da Aliança, em posse da Caçadora Davinia.', '<Você arranca o bilhete da mão do Sussujo.>$B$BEles estão na nossa cola! Eles sabem de tudo sobre a bomba. Estão planejando um ataque à Fortaleza Krom\'gar! Acho que eles mandaram um grupo de busca atrás de mim. Eu não vou morrer feito um trouxa. Eles vão ter uma briga.$B$BAcho que estou ouvindo eles chegando! A líder deles é uma caçadora elfa chamada Davinia. Ela falou de um plano de ataque. Me vingarei matando ela e pegando aquele plano! A tenda dela fica por perto, mais pro leste.$B$BOs olhos de Grito Infernal lhe observam...', '', '', '', '', '', '', '', '', '', 'Entregue o Plano de Ataque da Aliança a Saurboz no Nicho, que fica na Cordilheira das Torres de Pedra.', 0),
(26003, 'ptBR', 'Lições das Ilhas Perdidas', 'Mate 12 Batedores Darnassianos.', 'Há grandes perigos na floresta ao sul daqui. Elas estão infestadas por batedores darnassianos, assassinos enviados de Darnassus para nos matar. Mas talvez possamos virar o jogo, certo?$B$BQuando eu estava isolado nas Ilhas Perdidas, um goblin me deu essas lentes infravermelhas de calor. Elas permitem ao usuário ver a assinatura térmica de certas criaturas. Pegue as lentes e use-as quando estiver na floresta ao sul. Elas permitirão que você aviste os batedores rapidamente. Mate o maior número deles que você puder! Pela Horda!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kilag Dilaceros no Nicho, que fica na Cordilheira das Torres de Pedra.', 0),
(26004, 'ptBR', 'A Fortaleza Krom\'gar', 'Entregue o Plano de Ataque da Aliança ao Suserano Krom\'gar na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 'A Fortaleza Krom\'gar é nossa principal base de operações na Cordilheira das Torres de Pedra. É de lá que o suserano Krom\'gar observa toda a atividade militar da Horda na região. Krom\'gar reporta tudo que acontece diretamente ao chefe guerreiro.$B$BOs planos de ataque que você trouxe detalham uma investida contra a Fortaleza Krom\'gar programada para breve. Pegue os planos e siga rumo à fortaleza, a sudoeste daqui. Entregue-os ao suserano.$B$BAté logo, $n. E tenha certeza: os olhos de Grito Infernal lhe observam.', '', '', '', '', '', '', '', '', '', '', 0),
(26005, 'ptBR', 'Finalmente ar puro', 'Encontre o Capitão Taylor no Castelo de Voldrin, na superfície acima das Ruínas de Vashj\'ir.', 'O Capitão Taylor e muitos outros sobreviventes já chegaram à superfície. Tenho certeza de que alguns só pensam em sair de vez deste lugar, porém ainda temos trabalho a fazer para impedir que as nagas invadam o plano da água.$B$BPrimeiro, precisamos nos concentrar no demônio com tentáculos que destruiu nossos navios quando chegamos. Não queremos que esse pesadelo se repita.$B$BHexasfrega deixou essas botas para você. Com elas, sua viagem deverá ser um pouco mais rápida.', '', '', '', '', '', '', '', '', '', '', 0),
(26006, 'ptBR', 'Finalmente ar puro', 'Encontre o Legionário Nazgrim a bordo da Recompensa Estígia na superfície acima das Ruínas de Vashj\'ir.', 'O Legionário Nazgrim e muitos outros sobreviventes já chegaram à superfície. Tenho certeza de que alguns só pensam em sair de vez deste lugar, porém ainda temos trabalho a fazer para impedir que as nagas invadam o plano das águas.$B$BPrimeiro, precisamos nos concentrar no demônio com tentáculos que destruiu nossos navios quando chegamos. Não queremos que esse pesadelo aconteça novamente.$B$BFiasco deixou isso para você. Com eles, sua viagem deverá ser um pouco mais rápida.', '', '', '', '', '', '', '', '', '', '', 0),
(26007, 'ptBR', 'Relato de missão', 'Fale com Gurrok sobre a missão dele.', 'Este guerreiro estava à beira da morte, mas receio não termos tempo para esperar ele se recuperar totalmente. Ele tem informações que precisamos conhecer desesperadamente.$b$bSeja paciente com ele, mas faça-o falar até que saibamos de tudo que pudermos.$b$bCom sorte, pode ser que descubramos o que estamos combatendo...', '', 'Gurrok interrogado', '', '', '', '', '', '', '', '', 0),
(26008, 'ptBR', 'Descompressão', 'Use a Pedra da Respiração de Moana em 10 Guerreiros Aprisionados na Amarra.', 'Simplesmente não suporto a ideia de tantos outros, como esse guerreiro, aprisionados ou cercados por nagas.$b$bAlgo deve ser feito para regatá-los!$b$bTente isto, $n. Use-a nas celas da prisão para fazer com que boiem.$b$bSe conseguirmos fazer com que cheguem à superfície, ao menos eles terão uma chance de resgate.', '', 'Guerreiros Aprisionados libertados', '', '', '', '', '', '', '', 'Fale com Moana na Gruta Densanévoa.', 0),
(26009, 'ptBR', 'Busque e destrua', 'Mate quaisquer 20 soldados da Aliança na Cordilheira das Torres de Pedra.', 'A Aliança avança em nossos territórios nas Torres de Pedra. As forças da Expedição Guardanorte romperam nossa barreira ao sul e ocupam o Vale Cortavento, a oeste de nós. Da frente norte, vem um violento ataque de soldados noctiélficos. Todos devem ser detidos!$B$BSiga pelas Torres de Pedra destruindo todos os soldados da Aliança que cruzarem seu caminho. Que as mortes deles sirvam de recado.$B$BAs Torres de Pedra pertencem à Horda!', '', 'Soldados da Aliança mortos', '', '', '', '', '', '', '', 'Fale novamente com o Suserano Krom\'gar na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 0),
(26010, 'ptBR', 'Do pó ao pó', 'Use o Lança-chamas de Krom\'gar para destruir 8 Tendas da Guardanorte.', 'A Aliança ganhou coragem. Logo a oeste daqui, no Vale Cortavento, tropas de Guardanorte montaram um acampamento. Sem dúvida estão se preparando para o ataque do qual você nos avisou, $n. Eles nunca terão essa chance!$B$BPegue este lança-chamas. É o mesmo lança-chamas que meus incineradores usam para expulsar nossos inimigos ocultos na floresta. Use-o para destruir as tendas da Expedição Guardanorte. Não deixe nada para trás senão cinzas!', '', 'Tendas de Guardanorte incineradas', '', '', '', '', '', '', '', 'Fale novamente com o Suserano Krom\'gar na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 0),
(26011, 'ptBR', 'Inimigo da Horda: marechal Paltrow', 'Mate o Marechal Paltrow.', 'Meus batedores determinaram que a causa deste último fiasco é um único homem: o marechal Paltrow. Ele comanda o acampamento avançado que foi estabelecido no Vale Cortavento, a oeste daqui. Elimine-o e você terá eliminado um poderoso comandante de campo da Aliança da equação.$B$BPaltrow tem que morrer, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Senhora dos Espiões Anara na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 0),
(26012, 'ptBR', 'Bafafá no repouso', 'Fale com Krasus no Templo do Repouso das Serpes, que fica no Ermo das Serpes.', 'Krasus, um grande amigo meu, me enviou um bilhete relatando acontecimentos terríveis no Repouso das Serpes, no Ermo das Serpes. Parece que o Santuário Ruby, abaixo do Templo, sofreu algum tipo de ataque.$B$BAssuntos muito urgentes em Dalaran estão me impedindo de verificar o problema pessoalmente. Eu soube, no entanto, das suas façanhas na Cidadela do Lich Rei e, sem dúvida, você está à altura desta tarefa. Poderia ajudar Krasus em meu nome?', '', '', '', '', '', '', '', '', '', 'Fale com Krasus no Templo do Repouso das Serpes, que fica no Ermo das Serpes.', 0),
(26013, 'ptBR', 'Ataque ao santuário', 'Investigue o Santuário Rubi, embaixo do Templo do Repouso das Serpes.', '$R, algo terrível aconteceu no Santuário Rubi, embaixo do Templo.$B$BA entrada para o santuário está em ruínas, e os guardiões foram mortos violentamente. Nós enviamos batedores para investigar, mas eles não voltaram ainda. Só posso esperar o pior.$B$BVai ao Santuário Rubi e descobre o que aconteceu ao lar da minha revoada. Quando tivermos mais informações, poderemos planejar os próximos passos de acordo.', '', '', '', '', '', '', '', '', '', 'Investigue o Santuário Rubi, embaixo do Templo do Repouso das Serpes.', 0),
(26014, 'ptBR', 'Os irmãos Cavaclave', 'Apresente-se a Humberto Cavaclave na Garganta Telúmina, que fica em Vashj\'ir.', 'Soldado $n, sentido! Estamos tendo uma pequena prroblema!$b$bEnviamos Humberrto e Oskarr Cavaclave parra o Garrganta Reclusa, ao norrdeste, mas elas não voltarram. Elas deverriam investigarr o árrea, mas perrdemos toda contato com elas.$b$bO seu missão, soldado $n, é localizar nossas camarradas e, se elas estiverrem vivas, trazê-las a mim!', '', '', '', '', '', '', '', '', '', '', 0),
(26015, 'ptBR', 'Caça fosforescente', 'Obtenha 6 amostras de Fósforo Telúmino de Caranguejos Fogaça e Garoupas Luxescala na Garganta Telúmina.', 'O último pedido do Oskar, antes de ser sugado para a goela daquela grandenguia, era trazer comida para o capitão, então é isso que vamos fazer.$b$bO meu irmão tinha um plano genial. Ele viu aqueles murlocs lá na vegetação atraindo peixes com uma antena fosforescente e bolou um jeito de fazer uma para si. Tu só precisa de alguma coisa que brilhe.$b$bMate os caranguejos que perambulam pelo chão da caverna. Eles mesmo não são comestíveis, mas a fosforescência deles é muito mais valiosa do que a carne.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Humberto Cavaclave no fundo da Garganta Telúmina, que fica em Vashj\'ir.', 0),
(26017, 'ptBR', 'Uma isca', 'Coloque a Fedora Fosforescente e, em seguida, nade pelas algas na Garganta Telúmina para atrair 30 Mordiscadores Telúminos.', 'Prenda este dispositivo na cabeça e nade em meio às algas e ao coral ao longo da beira da garganta. Aposto que muitos daqueles peixes vão achar a sua antena irresistível.$b$bQuando voltarmos ao Covil do Abismo Sombrio, teremos montes de peixes para todo mundo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Humberto Cavaclave no fundo da Garganta Telúmina, que fica em Vashj\'ir.', 0),
(26018, 'ptBR', 'Apagando a luz fria', 'Mate 4 Caçadores de Luz Fria e 4 Oráculos de Luz Fria.', 'Ah, sim! Eu tinha que preparar um relatório! Quase esqueci!$b$bParece que o que existe por aqui é vida selvagem inofensiva... Não falando daquelas malditas enguias... e alguns murlocs. O capitão vai se interessar mais por esses murlocs, eu acho.$b$bVá lutar contra alguns deles e veja quais truques eles têm na manga. Pelo o que vi, os grandões caçam peixes em meio às algas enquanto os pequenos praticam algum tipo de mágica... mas isso é tudo o que eu sei.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Humberto Cavaclave no fundo da Garganta Telúmina, que fica em Vashj\'ir.', 0),
(26019, 'ptBR', 'Ovo gigante de enguia', 'Entregue o Ovo Gigante de Enguia para Humberto Cavaclave no fundo da Garganta Telúmina, que fica em Vashj\'ir.', '<Isto parece ser um ovo de uma das grandenguias tortuosas que flutuam acima da garganta. Você se pergunta se Humberto se interessaria por algo assim.>', '', '', '', '', '', '', '', '', '', '', 0),
(26020, 'ptBR', 'Apresente-se a Bombatripa', 'Apresente-se à Cabumgenheira-chefe Bombatripa na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 'Devemos nos preparar para o ataque iminente. Mandarei nossos soldados prepararem a bomba para o transporte. Quero que você se apresente à Cabumgenheira-chefe Bombatripa. Ela vem trabalhando para consertar nossos canhões antiaéreos, mas não conseguiu até agora. Certifique-se de que ela está devidamente motivada para reparar nossas armas, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(26021, 'ptBR', 'Os irmãos Cavaclave 2: omelete de ovo de enguia', 'Use o Dispositivo Enguiexplosivo perto de uma Grandenguia Tortuosa na Garganta Telúmina. Em seguida, derrote a Grandenguia Enfraquecida.', 'Aquelas enguias devoraram o meu irmão. O meu irmão, $n! Já é hora de alguém mostrar para esses bichos quem é que manda.$b$b<Humberto remove vários bastões de dinamite da roupa e os enfia pela membrana exterior do ovo.>$b$bNão dá para lutar mano a mano com elas, mas, com este ovo, a coisa vai ser diferente. Coloque-o próximo a uma daquelas criaturas e, então, cabum!$b$bSe a bomba não matar a enguia de imediato, ao menos a deixará perto o bastante da morte para que você termine o serviço.', '', 'Use o Dispositivo Enguiexplosivo na Grandenguia Tortuosa.', 'Vingue Oskar Cavaclave', '', '', '', 'Oskar Cavaclave', '', '', 'Fale novamente com Humberto Cavaclave no fundo da Garganta Telúmina, que fica em Vashj\'ir.', 0),
(26022, 'ptBR', 'Primeira gota', 'Consiga 10 Amuletos de Pedra-sangrenta de membros da Camarilha.', 'Prepare-se, $n. Você será $Go primeiro:a primeira; a derramar sangue por nós nesta terra.$B$BA Camarilha, como são chamados, são humanos covardes que traem até mesmo os próprios familiares. O isolamento os torna alvos fáceis.$B$BVá para o norte, mate os membros da Camarilha que encontrar, e retome a Casa Grande do Norte em nome dos Renegados! E, como prova da conquista, traga-me os amuletos de pedra-sangrenta que eles usam.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Patrulheira Sombria Alina na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26023, 'ptBR', 'O Matatroll Renegado', 'Fale com Galen Matatroll.', 'Vou lhe contar uma história.$B$BExistia um tolo troll chamado Zengu que recebeu a missão de encontrar Trol\'kalar, a lendária espada da linhagem humana Matatroll. Ele a encontrou e, orgulhoso do seu feito, decidiu partir de Arathi sozinho. Pouco tempo depois, os humanos o abateram e tomaram a espada de volta.$B$BNão seremos tão imprudentes. Nossos boticários acharam o guia perfeito para conseguirmos Trol\'kalar: o príncipe que a possuía.$B$BEle está pronto para guiá-$Glo:la;, $n. Fale com ele.', '', '', '', '', '', '', '', '', '', '', 0),
(26024, 'ptBR', 'Procura-se: Marez Capucho', 'Entregue a Cabeça de Marez para a Capitã Nélia na Ponta do Refúgio.', 'Oferece-se recompensa pela cabeça de Marez Capucho, uma alta conselheira e detetive da Camarilha. Ela foi vista pela última vez em Stromgarde, território controlado pela Camarilha.$B$BProcure a capitão Nélia para receber a recompensa.$B$BAviso: Marez é uma exímia bruxa conhecida pelo envolvimento com demônios. Recomenda-se extremo cuidado ao caçá-la.', '', '', '', '', '', '', 'Marez Capucho', '', '', 'Fale com a Capitão Nélia na Ponta do Refúgio, que fica no Planalto Arathi.', 0),
(26025, 'ptBR', 'A orquisa traidora', 'Pegue o Orbe de Pedra-sangrenta Conspurcado de Marez Capucho.', 'Não temos dúvida de que existe uma bruxa muito poderosa em Stromgarde. De vez em quando, ela usa uma relíquia arcana mágica para evocar um grande número de terríveis demônios. Temos que acabar com essa fonte de poder.$b$bEncontre a bruxa e mate-a. Traga-me todos os objetos mágicos que encontrar com ela. Tomarei providências para destruí-los e garantir que o poder do artefato não seja mais usado para macular esta terra.', '', '', '', '', '', '', 'Marez Capucho', '', '', 'Fale novamente com a Patrulheira Sombria Alina na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26026, 'ptBR', 'Sonhe com um futuro melhor', 'Recupere o Aparato de Guerra BD-816, o Fogo Mecanizado, o Gelo Mecanizado e o Ar Mecanizado.', 'O Sr. P está doente, $gsenhor:senhora;. Você não vai ajudá-lo? Você só tem que encontrar o chapéu e as baterias dele para ele ficar bonzinho. Eu mesma faria isso, mas não posso deixar o Sr. P sozinho!$B$BO chapéu dele foi roubado, pelos malvados da Empreendimentos S.A., perto da roda d\'água, e eles esconderam as baterias dele espalhadas pelo Rochedo Cortavento. Você vai ter que procurar muito bem por elas!$B$BPor favor, você traria as coisas do Sr. P de volta para que a gente possa dar uma lição nos malvados da Aliança?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Clarissa na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 0),
(26027, 'ptBR', 'Chamado às armas', 'Mate 7 Xamãs Punho de Pedra e 3 Senhores dos Punho de Pedra em Stromgarde.', 'Nosso próximo ataque contra os ogros $Go:a; levará ainda mais a leste, até Stromgarde. Os vivos acham que vale a pena se apegar a essas ruínas depredadas. Esse sentimentalismo todo me enoja!$B$BPara nós, Stromgarde não passa de um antro de ogros esperando para serem abatidos. Mate os xamãs e os senhores e certifique-se de exterminar todo tipo de liderança existente entre eles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Patrulheira Sombria Alina na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26028, 'ptBR', 'O passeio radical do Sr. P', 'Mate 20 Engenheiros Gnomos e 5 Bate-estacas Gnômicos', 'Agora, o Sr. P só precisa de um anjo que ajude ele a navegar. Você vai ser esse anjo, $gsenhor:senhora;? Com a sua ajuda, a gente vai poder andar pelo rochedo e matar um montão de malvados da Aliança! E aí? Vamos, $gsenhor:senhora;! Por favor! Por favor! Por favor!$B$BSe a gente matar um monte deles, o Sr. Krom\'gar vai comprar sorvete pra todo mundo!', '', '', '', '', '', '', '', '', '', 'Fale com o Suserano Krom\'gar na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 0),
(26029, 'ptBR', 'A ameaça real', 'Mate Or\'Kalar e arranque a cabeça dele.', 'Or\'Kalar é o líder dos ogros daqui. Ele já escapou da morte inúmeras vezes, e a simples existência desse bruto é uma afronta à Dama Sombria. Mug\'thol, um traidor dos Renegados, o comanda de longe!$B$BNão toleramos ogros ou traidores em terras dos Renegados. Traga-me a cabeça dessa criatura que eu mesmo a queimarei.', '', '', '', '', '', '', 'Or\'Kalar', '', '', 'Fale novamente com a Sicária Marília na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26030, 'ptBR', 'Signo de Strom', 'Consiga o Signo de Strom dos membros da Camarilha na Bastilha de Stromgarde.', 'Em tempos muito distantes, o Lorde Ígnaeus de Strom, conhecido como Matatroll, liderou a primeira civilização de Arathor na guerra contra os trolls. Sua espada era Trol\'kalar, assassina de trolls na língua antiga deles.$B$BSou um dos últimos desta linhagem, guardião jurado de Trol\'kalar... porém, falhei nesta função. Mas, agora, vamos reavê-la para o meu novo mestre.$B$BA espada está vinculada a três signos. O primeiro deles está guardado pelos traidores da Camarilha que vivem nas ruínas de Stromgarde. Mate-os e traga-me esse signo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Galen Matatroll na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26031, 'ptBR', 'Signo de Thoradin', 'Consiga 5 Fragmentos de Signo dos defensores de Stromgarde, na Bastilha de Stromgarde.', 'Durante minha vida, dividi o signo de Thoradin em cinco partes, e as entreguei para os meus soldados mais leais protegerem. Isto também não deu certo, mas meu sucessor fez o mesmo que eu.$B$BOs defensores de Stromgarde guardam novamente os pedaços do signo. Mate-os e traga-me os fragmentos. Eu os remontarei.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Galen Matatroll na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26032, 'ptBR', 'Signo de Arathor', 'Consiga o Signo de Arathor do Tenente Clamabravo.', 'Confiei o signo de Arathor ao Tenente Clamabravo, líder da minha cavalaria. Ele escapou por muito pouco, quando o atacaram.$B$BÉ muito improvável que isso aconteça de novo. Clamabravo patrulha a estrada entre a Bastilha de Stromgarde e a Ponta do Refúgio. Encontre-o e tome o signo dele mais uma vez.', '', '', '', '', '', '', 'Tenente Clamabravo', '', '', 'Fale novamente com Galen Matatroll na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26033, 'ptBR', 'Trol\'kalar', 'Recupere Trol\'kalar de dentro da tumba de Matatroll, na Bastilha de Stromgarde.', 'O último signo é meu. Os quatro formam o Signo de Matatroll, a chave para a tumba. Estamos prontos.$B$BTrol\'kalar encontra-se guardada com os restos de seu mestre, dentro da tumba de Matatroll nas catacumbas de Stromgarde. Ela estará muito bem guardada... mas eu sou a prova morta-viva de que é possível superar os defensores.$B$BEntre na tumba, recupere Trol\'kalar e traga-a para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Galen Matatroll na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26034, 'ptBR', 'O destruidor do crepúsculo', 'Derrote Halion e rechace a invasão do Santuário Rubi.', 'Este não foi um ataque a esmo. Foi um golpe calculado contra o coração da Revoada Vermelha.$B$BZarithrian, no penhasco lá adiante, está supervisionando o ataque, mas o verdadeiro líder das tropas é um dragão Crepuscular poderoso e impudente chamado Halion. Não víamos uma cria adulta dos experimentos perversos de Sinestra desde a época de Dargonax.$B$BMate-o, $n, e quando a invasão for completamente rechaçada, apresente-se a Krasus e informe a ele tudo o que viu aqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Krasus no topo do Templo do Repouso das Serpes.', 0),
(26035, 'ptBR', 'Isto vale ouro', 'Consiga 10 Presas de Cascasseca e 4 Bolsas Medicinais de Cascasseca dos Trolls Cascasseca.', 'O Arquimago Malin pediu para que eu coletasse reagentes para ele. Confesso que eu não fazia ideia de como consegui-los, mas agora que você chegou, tudo vai ficar mais fácil.$B$BPreciso de presas e bolsas medicinais de Cascasseca.$B$BPoderia me trazer algumas? Os Cascasseca vivem no sudeste de Arathi.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rodapeh na Ponta do Refúgio, que fica no Planalto Arathi.', 0),
(26036, 'ptBR', 'Entre a varinha e a espada', 'Encontre a Varinha de Evocação de Trelane e devolva-a para Rodapeh, na Ponta do Refúgio.', 'Ei! $n! Desculpa por ter sido curto e grosso com você mais cedo... E não, isso não é um trocadilho.$B$BEu descobri onde é que foi parar o primeiro item do Trelane: no Forte Punho de Pedra, com o Kor\'gresh. E pelo jeito que ele anda lascando raios de gelo nos lacaios, deve estar aprendendo a usar todo o poder da varinha.$B$BO Forte Punho de Pedra fica a sul daqui, e a leste da Ponte Thandol.$B$BEnquanto isso, vou pensar no que fazer com Stromgarde.', '', '', '', '', '', '', 'Kor\'gresh Furiafria', '', '', 'Fale novamente com Rodapeh na Ponta do Refúgio, que fica no Planalto Arathi.', 0),
(26037, 'ptBR', 'Defesas de Trelane', 'Consiga uma Ágata Lazúli e entregue-a para o Aprendiz Kraiten, na Bastilha de Stromgarde', 'Descansou um pouco?$B$BO plano é o seguinte: existem ogros ao redor da Torre de Arathor em Stromgarde. Temos que arrumar um jeito de você se proteger contra as defesas da torre. Para isso, vamos precisar de uma das gemas que os xamãs Punho de Pedra tanto gostam. Eles as obtiveram na torre, mas garanto que não irão ficar muito tempo em posse deles.$B$BConsiga uma e entregue-a para Kraiten, ele vai saber como encantá-la.', '', '', '', '', '', '', '', '', '', 'Fale com o Aprendiz Kraiten na Bastilha de Stromgarde, que fica no Planalto Arathi.', 0),
(26038, 'ptBR', 'Ataque à torre', 'Encontre o Filactério de Trelane, o Orbe de Trelane e a Ágata-de-fogo de Trelane e entregue-os para Rodapeh na Ponta do Refúgio.', 'Muito bem, seus alvos são: o Filactério de Trelane, o Orbe de Trelane e a Ágata-de-fogo de Trelane.$B$BEles estão em baús espalhados pela torre. O grande problema não é abrir as fechaduras, mas sim os ogros que andam por lá.$B$BFique com sua arma em punho! Se eles perceberem que tem alguém tentando roubá-los, vão fazer picadinho dessa pessoa!$B$BTome cuidado e boa sorte!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rodapeh na Ponta do Refúgio, que fica no Planalto Arathi.', 0),
(26039, 'ptBR', 'A princesa aprisionada', 'Consiga 12 Partículas de Myzrael dos Kobolds Bigodesseco.', 'Meu nome é Myzrael. Sou uma princesa da terra, mas os gigantes me prenderam nas profundezas do solo do Planalto Arathi. Estes cristais são a única forma que tenho de me comunicar com a superfície.$B$BPor favor, ajude-me. Os aliados dos gigantes, os kolbods Bigodesseco, possuem um cristal como este na Garganta Seca, a leste daqui. Para energizá-lo, use as partículas de Myzrael que os kobolds carregam.$B$BEu lhe imploro, $n, ajude-me!', '', '', '', '', '', '', '', '', '', 'Encontre os Fragmentos Iridescentes na Garganta Seca, que fica no Planalto Arathi.', 0),
(26040, 'ptBR', 'O quê? Quê? Nas minhas entranhas...?', 'Colete 7 Brotos de Alga-crespa dos Ceifadores Luzespinha, que ficam na Amarra.', 'O qu... que é isso!?$b$bTem uma dor forte crescendo... no fundo das minhas entranhas.$b$bAcho... ugh... que eles devem ter me envenenado!$b$bEles nos deram algas marinhas estranhamente brilhantes que cultivam em torno da fortaleza deles...$b$bAcho que essa câimbra vai piorar se eu não conseguir mais logo...$b$bPor favor, $r. Tente me arranjar um pouco!', '', '', '', '', '', '', '', '', '', 'Fale com Gurrok na Gruta Densanévoa.', 0),
(26041, 'ptBR', 'Pedras de vínculo', 'Consiga a Chave Ardente, a Chave Troante e a Chave Trovejante nas Pedras da União Ocidental, da União Oriental e de União Exterior.', 'Quatro pedras de vínculo estão espalhadas por Arathi e são elas que me prendem abaixo da terra.$B$BPara destrancá-las, você precisa desativar a mais forte: a Pedra da União Interna. Para isso, é necessário que você obtenha as chaves que estão nas outras três.$B$BEssas pedras são vigiadas por guardiões, mas se você for $ghabilidoso:habilidosa; e tiver um pouco de sorte, conseguirá bani-los.', '', '', '', '', '', '', '', '', '', 'Vá até a Pedra da União Interna no Círculo de União Interno, que fica no Planalto Arathi.', 0),
(26042, 'ptBR', 'Quebrando a pedra-chave', 'Tome o Bastão de Ordem das mãos de Fozruk.', 'A abertura das pedras de vínculo minimizou o meu confinamento, mas ainda há algo que me mantém aprisionada: a pedra-chave que você vê no meio deste círculo de pedras. Para abri-la, precisamos de um artefato que é guardado por Fozruk, um dos vigias de pedra que me capturaram.$B$BPreciso que você pegue esse artefato, chamado pelos vigias de pedra de Bastão de Ordem.$B$B$n, você já fez tanto por mim... Só mais um pouco e minha gratidão fará a própria estrutura da terra tremer!', '', '', '', '', '', '', 'Fozruk', '', '', 'Volte até a Pedra-chave no Círculo de União Interno, que fica no Planalto Arathi.', 0),
(26043, 'ptBR', 'CUIDADO COM QUEIXADA!', 'Mate Queixada e pegue o Dente Enorme do Queixada.', 'Por ordem do suserano Krom\'gar, o Lago do Rochedo está INTERDITADO!$B$BA agressiva fera conhecida como QUEIXADA fez do lago uma armadilha mortal. Se você matar Queixada, pegue o dente enorme dele como troféu e entregue-o à senhora dos espiões Anara para receber uma recompensa.', '', '', '', '', '', '', '', '', '', 'Entregue o Dente Enorme do Queixada à Senhora dos Espiões Anara na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 0),
(26044, 'ptBR', 'Onde estão as peças?', 'Fale com o Sargento Dontrag nas Entranhas da Terra, que ficam na Cordilheira das Torres de Pedra.', 'Eu estou esperando as peças pra essas armas faz dias! Eu mandei um dos meus melhores cabumgenheiros e duas dúzias de mineradores pras Entranhas da Terra pra pegar peças faz uns cinco dias. Depois de três dias sem ninguém dar notícia, eu comecei a ficar um pouco preocupada. O suserano mandou dois dos melhores orcs dele para ver o que estava acontecendo. E desde então nada...$B$BEntra lá nas Entranhas da Terra, aqui embaixo da fortaleza, e descobre o que está acontecendo! Eu preciso das peças!', '', '', '', '', '', '', '', '', '', '', 0),
(26045, 'ptBR', 'Tô com as suas peças bem aqui...', 'Colete 10 Peças Sobressalentes.', 'O dilema é que, das duas, uma: ou eu morro aqui embaixo igual a todo o resto, ou morro na Fortaleza quando Krom\'gar perceber que perdemos a mina. Bem, escolhi a terceira opção: não fazer nada. Até agora, está funcionando.$B$BQuem precisa de peças? Tem muito lixo espalhado pela mina. Você só precisa ir lá pegar.$B$BBoa sorte! Talvez, se você catar essas peças, possamos dar as caras na Fortaleza Krom\'gar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Dontrag nas Entranhas da Terra, na Cordilheira das Torres de Pedra.', 0),
(26046, 'ptBR', 'Entre a cruz e a espada', 'Mate 12 Elementais da Terra Enfurecidos.', 'Dontrag pode explicar melhor do que eu. Basicamente, estamos presos entre a cruz e a espada. Não há o que fazer aqui embaixo com todas essas coisas que podem nos matar e não podemos voltar à base por causa de todas essas coisas que podem nos matar, entende?$B$BTalvez, trabalhando juntos, possamos resolver essa bagunça. Que tal você começar eliminando alguns desses elementais que, aparentemente, andaram matando tudo na mina? Pode ser?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Batedor Utvoch nas Entranhas da Terra, que ficam na Cordilheira das Torres de Pedra.', 0),
(26047, 'ptBR', 'E é por isso que eles são chamados de peões...', 'Resgate 10 Peões Assustados.', 'Estes dois são uns INÚTEIS! Assim que eles chegaram, eu achei que a gente estava salvo. Até parece! Em vez disso, Dontrag e Utvoch deram uma olhada na mina e fizeram algum plano idiota em que a gente esperava aqui até que... até estar todo mundo morto, eu acho.$B$BBem, você não parece tão inútil quanto eles nem de longe. Que tal você me quebrar um galho, amig$Go:a;? Eu estou com dúzias de peões escondidos nas Entranhas da Terra, mais assustados do que caixa novato em liquidação. Encontra eles e tira eles de lá!', '', 'Peões Assustados resgatados', '', '', '', '', '', '', '', 'Fale novamente com o Cabumgenheiro Igore nas Entranhas da Terra na Cordilheira das Torres de Pedra.', 0),
(26048, 'ptBR', 'Nadando em peças sobressalentes!', 'Entregue o Caixote de Peças Sobressalentes à Cabumgenheira-chefe Bombatripa na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 'Ufa, essa foi difícil. Não achei que conseguiríamos, $n. É melhor levarmos essas peças sobressalentes para a cabumgenheira-chefe Bombatripa. Tenho a impressão de estar ouvindo máquinas voadoras gnômicas lá fora. Não temos um minuto sequer para desperdiçar!', '', '', '', '', '', '', '', '', '', '', 0),
(26049, 'ptBR', 'A princesa libertada', 'Evoque e derrote Myzrael nos Estilhaços de Myzrael.', 'Myzrael não é uma princesa inocente. Ela é uma terrível manifestação que os gigantes fizeram muito bem em aprisionar. Lamento dizer que você foi $Genganado:enganada;.$B$BDe acordo com Gerrig, você terá que evocá-la nos Estilhaços de Myzrael, onde a ouviu pela primeira vez. Derrote-a, recupere os Grilhões Sobrenaturais e ate-os aos Estilhaços.$B$BEste é o pergaminho de que você necessitará. Tome cuidado com ele, pois quase perdi uns dentes para consegui-lo. Boa sorte, $n.', '', '', '', '', '', '', 'Myzrael', '', '', 'Volte aos Estilhaços de Myzrael no Planalto Arathi.', 0),
(26050, 'ptBR', 'Óculos à prova d\'água', 'Escolte o Professor Bruzundanga até a caverna e retorne com ele.', 'Agora que somos Saqueadores de Aguanegra de verdade, cabe a nós ajudar Juanka Nabrava a encontrar o tesouro perdido dos elfos.$b$bÉ praticamente impossível encontrar gemas no fundo do mar sem o auxílio dos óculos que o doutor construiu. Precisamos energizá-los com a energia da pedra encantada na caverna logo acima da colina.$b$bO problema é que a caverna é amaldiçoada! Sempre que nos aproximamos, somos emboscados. Me proteja enquanto eu extraio energia da pedra para os óculos.', 'Defenda o Professor Bruzundanga', '', '', '', '', 'Defenda o Professor Bruzundanga', '', '', '', 'Fale com o Doutor Medeixo na Enseada de Faldir, que fica no Planalto Arathi.', 0),
(26051, 'ptBR', 'Tesouro afundado', 'O Doutor Medeixo na Enseada de Faldir quer que você consiga 10 Gemas Élficas e devolva os Óculos para Caçar Gemas quando tiver terminado.', 'O tesouro ficou tanto tempo no fundo do mar que uma grossa camada de pedra encobriu as gemas, mas a energia contida nesses óculos vai fazer com que você encontre-as facilmente.$b$bNada que um toquezinho de gnomicidade não resolva!$b$bUse os óculos para caçar gemas, $n, e recupere parte do tesouro para o capitão Juanka Nabrava.$b$bEu mesmo nadaria até lá, mas... ahm... você sabe, tenho negócios a tratar aqui em terra firme... e seca... é, isso.', '', '', '', '', '', '', '', '', '', 'Fale com o Doutor Medeixo na Enseada de Faldir, que fica no Planalto Arathi.', 0),
(26052, 'ptBR', 'Tremenda encomenda', 'Leve as Gemas Élficas para o Capitão Juanka Nabrava na Enseada de Faldir, que fica no Planalto Arathi.', 'Não podemos deixar o Capitão Juanka Nabrava esperando. Ele quer ver essas gemas imediatamente. Afinal de contas, é para isso que estamos aqui!$b$bAlgumas poucas semanas de convivência com esses piratas são suficientes para descobrir que esconder o tesouro deles não faz bem para sua saúde.$b$bTome, $n, leve-as para Juanka Nabrava.', '', '', '', '', '', '', '', '', '', '', 0),
(26053, 'ptBR', 'Limpando o Planalto', 'Mate 8 Ogros Punho de Pedra e 10 Impositores Punho de Pedra.', 'Nenhuma ameaça passará despercebida. Se vamos tomar estas terras em nome da Dama Sombria, exterminaremos toda a vida, até que não sobre nada.$B$BExiste um abrigo de ogros a nordeste daqui, tão perto quanto a distância de uma pedra arremessada. Os Punho de Pedra que lá vivem devem ser erradicados, $c.$B$BEles estão no nosso caminho. Não hesite, nem tenha piedade.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sicária Marília na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26054, 'ptBR', 'Bruxas, trolls e monstros marinhos', 'Mate Kai\'ju Gahz\'rilla e, depois, fale com o General Marcus Jonas em Ventobravo.', 'Trolls Zangareia de complô com o Martelo do Crepúsculo?!$B$BTanto faz. Aquela bruxa velha não vai mandar o bichinho dela para a MINHA cidade.$B$BVamos, bravos guerreiros! Vamos encharcar as areias com o sangue deles e voltar triunfantes de lá! Conte ao general Marcus Jonas o que ocorreu quando voltamos. Preciso cuidar da realocação dos cidadãos, dos consertos e de tudo mais.', '', '', '', '', '', '', '', '', '', 'Vá para Ventobravo e conte ao General Marcus Jonas sobre a morte de Kai\'ju Gahz\'rilla.', 0),
(26055, 'ptBR', 'Afogando as mágoas', 'O Capitão Tripaço, na Enseada de Faldir, quer que você mate 10 Saqueadores Espinhadaga e 3 Feiticeiras Espinhadaga.', 'Argh, odeio esta vida. Eu devia ter virado comida de peixe, em vez de estar aqui respirando ar fresco.$b$BA tripulação fez o que pôde para salvar o meu lindo Extravagância da Donzela. Abençoados os corações daqueles rapazes.$b$bJuanka Nabrava conseguiu chegar à praia, mas nós não tivemos a mesma sorte. O mar nos engoliu, eu juro.$b$bDe uma hora para outra, água por toda parte... e aqueles monstros! Mataram todos os sobreviventes. Maldita escória naga. Daí tudo ficou preto e quando acordei estava aqui.$b$bQuero que todas aquelas feras morram.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Tripaço na Enseada de Faldir, que fica no Planalto Arathi.', 0),
(26056, 'ptBR', 'A Falaondas', 'Encontre a Falaondas Valoren no Abismo dos Pesadelos em Vashj\'ir.', 'Um dos membros da Harmonia Telúrica, a Falaondas Valoren, nadou para o Abismo dos Pesadelos, a nordeste. Já faz tempo que não temos notícias dela.$B$BNade até lá e veja se consegue encontrá-la.', '', '', '', '', '', '', '', '', '', '', 0),
(26057, 'ptBR', 'A Falaondas', 'Encontre a Falaondas Valoren no Abismo dos Pesadelos em Vashj\'ir.', 'Um dos membros da Harmonia Telúrica, a Falaondas Valoren, nadou para o Abismo dos Pesadelos, a nordeste. Já faz tempo que não temos notícias dela.$B$BNade até lá e veja se consegue encontrá-la.', '', '', '', '', '', '', '', '', '', '', 0),
(26058, 'ptBR', 'Em defesa da Fortaleza Krom\'gar', 'Destrua 15 Máquinas Voadoras Gnômicas ou Bombardeiros e 25 Comandantes de Ala Gnomos.', 'A gente não tem mais tempo. Aí vêm eles! Pega um canhão aí e manda os gnomos pelos ares! Se essa bomba tomar muito teco, ela vai explodir e matar todo mundo!$B$BDefende a base, $n! Você é a nossa única esperança!$B$BSe a gente conseguir, de alguma forma, sair daqui $ginteiro:inteira;, se apresenta depois ao suserano Krom\'gar.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Suserano Krom\'gar na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 0),
(26059, 'ptBR', 'Olhos e ouvidos: Malaka\'jin', 'Apresente-se ao Mandingueiro Jin\'zil em Malaka\'jin, que fica na Cordilheira das Torres de Pedra.', 'Perdemos o Posto da Honra. O poder da Horda sobre os Sertões despedaçou-se junto com a própria terra. Agora recebo relatórios que dizem estarmos correndo risco de perder Malaka\'jin para um ataque combinado da Aliança e do Temível Totem. Se Malaka\'jin ruir, metade das Torres de Pedra ruirá junto.$B$BVocê provou ser $gum:uma; soldado da Horda capaz. Você será meus olhos e ouvidos em Malaka\'jin? O mandingueiro Jin\'zil aguarda sua chegada.$B$BMalaka\'jin está localizada bem ao sul.', '', '', '', '', '', '', '', '', '', '', 0),
(26060, 'ptBR', 'Vodu: coração de eletrocutor', 'Obtenha um Coração de Eletrocutor do Penhasco', 'Com o vodu, nossas tropas podem ter uma chance de contra-atacar o Temível Totem. Dito isso, preciso de vários ingredientes se vou mesmo fazer magia negra.$B$BO primeiro ingrediente na minha lista é o coração de um eletrocutor do penhasco. As feras foram caçadas quase até a extinção, mas ainda há algumas por essas bandas. Encontre uma e extraia seu coração pulsante!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mandingueiro Jin\'Zil em Malaka\'jin, que fica na Cordilheira das Torres de Pedra.', 0),
(26061, 'ptBR', 'Vodu: chifres de carneiro', 'Obtenha 6 Chifres de Carneiro das Torres de Pedra.', 'Para fazer o vodu, preciso de vários reagentes especiais. Traga-me os chifres dos carneiros das Torres de Pedra da região, $n! Sem os chifres, estaremos perdidos!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mandingueiro Jin\'Zil em Malaka\'jin, que fica na Cordilheira das Torres de Pedra.', 0),
(26062, 'ptBR', 'Vodu: cristal de ressonita', 'Obtenha 8 Cristais de Ressonita.', 'O último ingrediente para o ritual vodu é um tipo especial de cristal chamado ressonita. Ele só pode ser achado na Caverna da Avalanche, a oeste daqui. Cuidado com os kobolds! Eles guardam a ressonita com a própria vida!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mandingueiro Jin\'Zil em Malaka\'jin, que fica na Cordilheira das Torres de Pedra.', 0),
(26063, 'ptBR', 'A rainha e sua corte', 'Mate a Rainha Silith e quaisquer 10 aranhas no Antro Enrediço.', '<Darn geme.>$B$BHmmpf.$B$BTudo dando errado. Darn não feliz. Agora, parceira de Darn morta por aranhas no Antro Enrediço. Darn exige vingança!$B$BAjuda Darn? Mata rainha Silith e filhotes dela? Por Darn? Por parceira de Darn!$B$BAntro Enrediço fica nordeste, pelo caminho. Vai!', '', '', 'Aranhas do Antro Enrediço mortas', '', '', '', '', '', '', 'Fale novamente com Darn Garradanha na barreira da Horda, que fica na Cordilheira das Torres de Pedra.', 0),
(26064, 'ptBR', 'Guerra estomacal', 'Colete 8 Ovos de Águia de Kalimdor.', 'As tropas estão famintas, $n. Com nossas linhas de abastecimento interrompidas, estamos ficando sem comida. Posso cozinhar um banquete para os soldados se você me trouxer alguns ingredientes.$B$BVá à floresta a oeste daqui e procure por ninhos de águias de Kalimdor. Roube os ovos dos ninhos e traga-os para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Denni\'ka em Malaka\'jin, que fica na Cordilheira das Torres de Pedra.', 0),
(26065, 'ptBR', 'Libertando Wil\'hai', 'Mate todos os Tentáculos Horrendos para libertar Wil\'hai.', 'Aqueles tentáculos horrendos saíram das profundezas e prenderem o pobre "bichinho". $n, tu poderias destruir os tentáculos e libertar Wil\'hai?$B$BAqui, usa meu totem perto dos tentáculos. Ele emana um frio que diminuirá o tamanho do monstro e, assim, tu poderás acabar com ele.', '', 'Libertando Wil\'hai', '', '', '', '', 'Wil\'hai', '', '', 'Fale novamente com a Falaondas Valoren no Abismo dos Pesadelos em Vashj\'ir.', 0),
(26066, 'ptBR', 'Reforços...', 'Use o Chicote do Subjugador Divo para subjugar 6 Kobolds da Caverna da Avalanche.', 'Parece que estamos ficando sem orcs grandes e estúpidos para enviar contra o inimigo. Isso é um problema. Felizmente, posso ter uma solução.$B$BPegue este chicote e siga para o oeste, até a Caverna da Avalanche. Dentro da caverna, você encontrará um ninho sujo de kobolds. Use meu chicote para subjugar as feras. Uma vez dominadas, elas farão o que lhes for pedido.$B$BVolte a mim quando você tiver reunido um exército de kobolds razoavelmente grande.', '', 'Kobolds da Caverna da Avalanche subjugados', '', '', '', '', '', '', '', 'Fale novamente com o Subjugador Divo em Malaka\'jin, que fica na Cordilheira das Torres de Pedra.', 0),
(26067, 'ptBR', 'A bênção de Jin\'Zil', 'Use o Bastão Vodu de Jin\'Zil para infundir 12 Espoliadores de Krom\'gar com Vodu.', 'Ah, está feito! Agora, resta vermos se funciona.$B$BVá ao principal ponto de conflito no Vale Matagrande e use meu bastão vodu nos espoliadores de Krom\'gar em combate contra os Temível Totem. Minha magia vodu deve restaurar o vigor deles e permitir-lhes esmagar nossos inimigos!$B$BAgora vá, $n!', '', 'Espoliadores de Krom\'gar fortalecidos', '', '', '', '', '', '', '', 'Fale novamente com o Mandingueiro Jin\'Zil em Malaka\'jin, que fica na Cordilheira das Torres de Pedra.', 0),
(26068, 'ptBR', 'A fúria dos kobolds!', 'Use a Trompa de Guerra Kobold perto do Estandarte da Horda nas Terras Escavadas para convocar o Exército de Kobolds!', 'Agora nós comandamos os exércitos de kobolds nas Torres de Pedra! Soa quase impressionante! Quase.$B$B<Divo suspira.>$B$BO acampamento-base da Aliança, ao norte, é fortemente guardado. Ele é quase inexpugnável, exceto pela entrada próxima às Terras Escavadas, a nordeste daqui. Pegue esta trompa de guerra e vá rumo às Terras Escavadas. Entre pelo leste, $n! Uma vez lá, siga para o oeste até chegar ao local que marquei em seu mapa e use a trompa para despejar a fúria dos kobolds sobre a Aliança!', 'O Exército Kobold ataca!', '', '', '', '', 'O Exército Kobold ataca!', '', '', '', 'Fale novamente com o Subjugador Divo em Malaka\'jin, que fica na Cordilheira das Torres de Pedra.', 0),
(26069, 'ptBR', 'Nura Caminheira', 'Apresente-se a Nura Caminheira na Estrada Alta, que fica nos Sertões Meridionais.', 'Os Sertões Meridionais estão sob ataque da Aliança. Os taurens enviaram um pedido de ajuda que, simplesmente, não podemos ignorar. Todos os membros da Horda em bom estado físico devem ajudar.$B$BSe você deseja ajudar, siga o caminho até a Estrada Alta, que começa na vila. Procure por Nura Caminheira.', '', '', '', '', '', '', '', '', '', '', 0),
(26070, 'ptBR', 'Limpando a sujeira', 'Mate 8 Enguias Esmagadoras, Rêmoras do Abismo ou Espreitadores do Abismo.', 'Nossos amigos da Harmonia Telúrica querem saber se vamos ajudá-los ou não. Há certas criaturas no Abismo Escaldante que estão profanando toda a vida selvagem do local.$B$BVocê poderia tomar contra delas para mim?', '', 'Vida selvagem profanada do Abismo Escaldante', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Taylor no Promontório em Vashj\'ir.', 0),
(26071, 'ptBR', 'Limpando a sujeira', 'Mate 8 Enguias Esmagadoras, Rêmoras do Abismo ou Espreitadores do Abismo.', 'Nossos amigos da Harmonia Telúrica querem que façamos o serviço sujo para eles. Há certas criaturas no Abismo Escaldante que estão profanando toda a vida selvagem do local.$B$BVocê poderia cuidar disso para mim?', '', 'Vida selvagem profanada do Abismo Escaldante', '', '', '', '', '', '', '', 'Fale novamente com o Legionário Nazgrim no Promontório em Vashj\'ir.', 0),
(26072, 'ptBR', 'Totem adentro', 'Mate 5 Profanadores Sem-rosto enquanto eles estiverem perto do Totem de Confinamento.', 'Você terá que levar meu totem para o Abismo Escaldante. Use-o para capturar as energias dos sem-rosto quando eles morrerem. O totem impedirá que eles retornem do local de onde vieram.$B$BQuando o totem estiver cheio, traga-o para mim: nós o usaremos para atrair o líder deles das profundezas do abismo.', '', 'Energias dos Profanadores Sem-rosto confinadas', '', '', '', '', '', '', '', 'Fale novamente com Erunak Falapedra no Promontório em Vashj\'ir.', 0),
(26073, 'ptBR', 'Nada de novo no front sul', 'Apresente-se ao suserano Krom\'gar na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 'Volte já ao suserano Krom\'gar, $n. Informe-o sobre o nosso estado e sobre o que você fez para garantir que Malaka\'jin não caia.$B$BAgradecemos por tudo que você fez. Talvez, algum dia em breve, você tenha a sua própria região para comandar.', '', '', '', '', '', '', '', '', '', '', 0),
(26074, 'ptBR', 'Começo do fim', 'Leve o Balão de Ar Quente de Krom\'gar ao Barreiro, que fica na Cordilheira das Torres de Pedra.', '$GCampeão:Campeã;, temos um novo alvo. Nossos batedores no Vale Chaga de Guerra informaram que os elfos noturnos estão produzindo sua própria arma de destruição em massa, e a estão escondendo dentro de uma antiga árvore. Eles nunca terão a chance de usar essa arma contra nós.$B$BEscolte a bomba até o Barreiro para reabastecer e, em seguida, até o Posto Andarilho da Montanha, de onde a detonaremos e mataremos todos os nossos inimigos.$B$BVá agora, $n. Apresente-se a Jibbly Rakit quando você chegar ao Barreiro.', '', 'Balão de Ar Quente de Krom\'gar escoltado a salvo até o Barreiro', '', '', '', '', '', '', '', 'Apresente-se a Jibbly Rakit no Barreiro, que fica na Cordilheira das Torres de Pedra.', 0),
(26075, 'ptBR', 'As mantícoras, quando avoam...', 'Mate quaisquer 6 Mantícoras Asaltivas.', 'A gente tá com um pequeno problema...$B$B<Jibbly aponta para os cocôs cobrindo a base.>$B$BO Barreiro foi construído próximo a um hábitat de mantícoras. O projeto inicial do Barreiro foi feito pra não perturbar o hábitat das mantícoras, já que parece que elas são sagradas pros taurens e pros orcs. Mas sabe o que é sagrado pra mim? Não levar cocô na cabeça!$B$BCá entre nós, as mantícoras têm que morrer!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Jibbly Rakit no Barreiro, que fica na Cordilheira das Torres de Pedra.', 0),
(26076, 'ptBR', 'Infestação de espiões', 'Mate 8 Espiões da Aliança. Use a Bomba de Gás do Jibbly para revelar os espiões!', 'A gente tem um outro problema, $n. Tem espião da Aliança pra todo lado! Você não viu nenhum deles? Isso é porque eles estão invisíveis! Camuflados! Eu tenho uma solução, mas preciso da sua força pra ir lá fora e fazer o meu plano funcionar.$B$BUsa essa bomba de gás nos espiões que estiverem camuflados e ela vai fazer eles aparecerem. E, quando eles aparecerem... manda pra terra dos pés juntos.$B$BVocê vai reconhecer os espiões camuflados pelo efeito que eles deixam no ar. Fica de olho!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Jibbly Rakit no Barreiro, que fica na Cordilheira das Torres de Pedra.', 0),
(26077, 'ptBR', 'Entrega final', 'Leve o Balão de Ar Quente de Krom\'gar ao Posto  Andarilho da Montanha, na Cordilheira das Torres de Pedra.', 'O suserano Krom\'gar manda notícias da base. Você deve voltar ao balão de ar quente de Krom\'gar e levá-lo ao Posto  Andarilho da Montanha. De lá, o plano é despejar a carga em cima da Aliança no Vale Chaga de Guerra.$B$BÉ melhor você ir logo, $n. Não seria sábio deixar Krom\'gar esperando.$B$BFale com o general Grebo quando você chegar ao seu destino. Ele será capaz de instruir você quanto à próxima ação.', '', 'Balão de Ar Quente de Krom\'gar levado ao Posto Pedrâmbula', '', '', '', '', '', '', '', 'Apresente-se ao General Grebo no Posto Andarilho da Montanha, que fica na Cordilheira das Torres de Pedra.', 0),
(26078, 'ptBR', 'Fogo!', 'Usando o Equipamento de Combate a Incêndio, apague 6 focos de incêndios na Base Aérea de Altaforja.', 'O ataque dos Ferro Negro nos pegou de surpresa. Os sabotadores conseguiram danificar nossas aeronaves, nossos tanques a vapor e suprimentos. Apenas alguns bombardeiros estavam em condição de voar.$B$BTodos os técnicos, recrutas e guardas que posso manter aqui estão correndo para consertar as outras aeronaves. Só resta à nossa infantaria resistir até lá. Pegue este equipamento e ajude a extinguir os incêndios nos bombardeiros.', '', 'Incêndios extinguidos', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Quebrapedra na Base Aérea de Altaforja.', 0),
(26079, 'ptBR', 'Procura-se: Otto e Falcocrista', 'Entregue a Cabeça de Otto e a Cabeça de Falcocrista para a Capitão Nélia na Ponta do Refúgio.', 'A Milícia de Stromgarde oferece recompensa pelas cabeças do Lorde Falcocrista e de Otto, o guarda-costas. Falcocrista lidera as ações da Camarilha no Planalto Arathi, e a morte dele afetaria grandemente os planos desta organização.$B$BSeu guarda-costas, embora não seja um alvo estratégico, é um perigoso inimigo que já matou dúzias de defensores de Stromgarde.$B$BA recompensa deverá ser reclamada junto à capitão Nélia.', '', '', '', '', '', '', 'Lorde Falcocrista', '', '', 'Fale com a Capitão Nélia na Ponta do Refúgio, que fica no Planalto Arathi.', 0),
(26080, 'ptBR', 'Um último favor', 'Entregue o Filé com Dicas do Cavaclave para o Capitão Glovaal no Covil do Abismo Sombrio.', '$n, preciso que você leve isto de volta para o capitão Glovaal. No estado em que estou, vou demorar uma semana para chegar no Covil do Abismo Sombrio, e não temos tempo a perder.', '', '', '', '', '', '', '', '', '', '', 0),
(26081, 'ptBR', 'A recompensa de Alina', 'Fale com a Patrulheira Sombria Alina.', 'Então... aqui termina a lenda de Trol\'kalar. Ela será a arma que trará morte para os vivos, em nome da Dama Sombria.$B$BDeixe-me só, $n. Mais uma vez, tenho o dever de guardar esta espada. Conte a Alina sobre sua vitória, tenho certeza de que ela $go:a; recompensará.', '', '', '', '', '', '', '', '', '', '', 0),
(26082, 'ptBR', 'Rumo à Chaga de Guerra!', 'Use o Demolidor de Krom\'gar para destruir 5 Lançadoras de Glaives Darnassianas e quaisquer 20 Soldados da Aliança no Vale Chaga de Guerra.', 'Permitirei que este velho tolo apresente o caso dele. Ele me garantiu que traria prova de que os elfos noturnos não estão desenvolvendo uma arma de destruição em massa. Veremos.$B$BEnquanto esperamos por essa prova, você auxiliará nosso exército no vale. Preparamos um grande número de tanques de cerco para esse propósito. Nossos demolidores estão prontos para atacar.$B$BDesça de elevador até a base do posto e assuma o controle de um demolidor de Krom\'gar. Use-o para arrasar nossos inimigos no Vale Chaga de Guerra.', '', 'Lançadoras de Glaives Darnassianas destruídas', 'Soldados da Aliança no Vale Chaga de Guerra mortos', '', '', '', '', '', '', 'Apresente-se ao General Grebo no Posto  Andarilho da Montanha, que fica na Cordilheira das Torres de Pedra.', 0),
(26083, 'ptBR', 'Olá, Lolo', 'Encontre Lolo, o Olheiro, na Enseada de Faldir.', 'Mandaram Bucho-da-gota fazer escolta. Procurar monte de coisas. Aventura grande!$B$BBucho-da-gota achar barco pirata. Piratas tudo assustados, eles correr pra longe. Mas ogro Lolo não correr. Ogro Lolo fazer amigo com Bucho-da-gota!$B$BBucho-da-gota ir pra longe, mas saudade de Lolo. Você ir e dizer olá pro Lolo!', '', '', '', '', '', '', '', '', '', '', 0),
(26084, 'ptBR', 'Ruína do Martelo', 'Apresente-se a Gor\'mul na Ruína do Martelo, que fica no Planalto Arathi.', 'Você nos foi de muita ajuda, $n. Agora que reafirmamos nossa presença, a próxima fase do nosso plano de conquista vai levar meses, e não mais poucos minutos.$B$BAinda há muito a se fazer, mas vou poupar você do tédio de esperar as fortificações ficarem prontas. Vá para o leste, até a Ruína do Martelo. Tenho certeza de que os orcs de lá terão trabalho para você.', '', '', '', '', '', '', '', '', '', '', 0),
(26085, 'ptBR', 'É bom para o moral', 'Finque 8 Estandartes de Altaforja nos montes de Neve Fofa ao longo da Base Aérea de Altaforja.', 'Enquanto nossos engenheiros trabalham duro para consertar os bombardeiros, nossos guardas e montanhistas continuam a lutar contra os invasores.$B$BEles estão em campo desde o início da incursão e ainda não conseguiram descansar ou comer. Os defensores de Altaforja estão entre os melhores de Azeroth, mas até mesmo eles têm limites.$B$BPegue estes estandartes e finque-os em montinhos de neve. Faça-os lembrar pelo que estão lutando. Ajude-me a levantar o moral deles!', '', 'Estandartes de Altaforja fincados', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Quebrapedra na Base Aérea de Altaforja.', 0),
(26086, 'ptBR', 'Orako', 'Apresente-se a Orako na Garganta Telúmina, que fica em Vashj\'ir.', '<O capitão Verne olha para o relógio.>$b$bOnde está aquele caçador? Enviei Orako à Garganta Telúmina em uma missão de reconhecimento há uma semana! Claro, ele é hábil, e não me importei em tirar ele da minha cola, mas preciso desse relatório.$b$bQual é o seu nome? $n? Você está dispost$go:a; a rastreá-lo? Parece estranho mandar $gum:uma; $c para encontrar um caçador, mas estou ficando sem opções.', '', '', '', '', '', '', '', '', '', '', 0),
(26087, 'ptBR', '"Suco fluorescente"', 'Obtenha 6 amostras de Suco Fluorescente de Caranguejos-aranha Fogaça e Garoupas Luxescala na Garganta Telúmina.', 'Atirar em peixes em um barril é fácil. Atirar em peixes em um oceano é um pouco mais difícil.$b$bVocê viu os murlocs na garganta, $c? Eles sequer atiram! Eles têm bolinhas cheias de suco fluorescente na cabeça que servem para ATRAIR os peixes. Ei, a gente deveria tentar isso!$b$bVá para o sul e mate os caranguejos e as garoupas na garganta. Eles têm muito suco fluorescente na pele. Eu já vi!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Orako na Garganta Telúmina, que fica em Vashj\'ir.', 0),
(26088, 'ptBR', 'Aqui, peixinho', 'Coloque o Chapéu de Peixe. Em seguida, nade pelas algas na Garganta Telúmina para atrair 30 Mordiscadores Telúminos.', '<Orako enrola o suco fluorescente e o prende a um dispositivo o qual é evidente que ele anda trabalhando há algum tempo.>$b$bAqui, tenho um chapéu para você. Ele tem uma luz nele, e isso fará com que os peixes sigam você. Igualzinho aos murlocs!$b$bOs murlocs gostam de caçar em meio às algas e aos corais ao longo dos lados da garganta. Se você colocar este chapéu e nadar por aquelas algas, pode ser que você pegue peixes como eles fazem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Orako na Garganta Telúmina, que fica em Vashj\'ir.', 0),
(26089, 'ptBR', 'Morra, homem-peixe! Morra!', 'Mate 4 Caçadores de Luz Fria e 4 Oráculos de Luz Fria.', 'Um peixe devorou o meu lobo, e murlocs parecem peixes. Farei esses murlocs pagarem!$b$bVolte à garganta e mate esses homens-peixe! O meu lobo será vingado!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Orako na Garganta Telúmina, que fica em Vashj\'ir.', 0),
(26090, 'ptBR', 'Eu trouxe este ovo para você', 'Entregue o Ovo Gigante de Enguia a Orako na Garganta Telúmina, que fica em Vashj\'ir.', '<Isto parece ser um ovo de uma das grandenguias tortuosas que flutuam acima da garganta. Você se pergunta se Orako se interessaria por algo assim.>', '', '', '', '', '', '', '', '', '', '', 0),
(26091, 'ptBR', 'Aqui, peixinho 2: omelete de ovo de enguia', 'Use o Dispositivo Enguiexplosivo perto de uma Grandenguia Tortuosa na Garganta Telúmina. Então, derrote a Grandenguia Enfraquecida.', '<Orako tira uma armadilha explosiva da bolsa e a empurra pela membrana externa do ovo.>$b$bIsso é para fazer o ovo explodir. Coloque o ovo próximo de uma daquelas enguias gigantes e espere ela se aproximar. Quando o ovo explodir, o grande peixe estará quase morto e você poderá finalizá-lo.$b$bSalve o meu lobo! Com o ovo, você pode conseguir.', '', 'Use o Dispositivo Enguiexplosivo na Grandenguia Tortuosa.', 'Vingue o Lobo', '', '', '', 'Lobo', '', '', 'Fale novamente com Orako na Garganta Telúmina, que fica em Vashj\'ir.', 0),
(26092, 'ptBR', 'Relatório do Orako', 'Entregue o Relatório do Orako ao Capitão "Julho" Verne na Caverna Tenebrosa.', '<Você lembra ao Orako que ele deveria enviar um relatório para o capitão Verne.>$b$bAh, é... Um relatório. Não vi nada aqui além de peixes. Montes e montes de peixes.$b$b<Orako olha para o saco de peixe que você trouxe para ele.>$b$bLeve isso para o capitão. Aí está o meu relatório.', '', '', '', '', '', '', '', '', '', '', 0),
(26093, 'ptBR', 'Casa Grande do Norte', 'Mate 10 membros da Camarilha na Casa Grande do Norte.', 'Estamos perdendo a batalha de Stromgarde. Ogros, Camarilha e até mesmo nós somos responsáveis pela situação da nossa antiga cidade, e cada facção luta para exterminar as demais.$B$BPerdemos a Costa Sul... não podemos permitir que nossos inimigos nos tomem mais territórios!$B$BVá até a base da Camarilha na Casa Grande do Norte e mate-os. Temos que retomar nossas terras antes que a Horda se espalhe.', '', '', '', '', '', '', '', '', '', 'Fale com a Capitão Nélia na Ponta do Refúgio, que fica no Planalto Arathi.', 0),
(26094, 'ptBR', 'O revide', 'Embarque no Bombardeiro Consertado e use a Bomba Martelo de Ferro para matar 30 atacantes Ferro Negro. Você pode matar quaisquer anões Ferro Negro ou seus aliados na Base Aérea de Altaforja.', 'Meu engenheiro-chefe disse que conseguiu deixar uma das aeronaves prontas para voar de novo. Pegue estas bombas e vá até o bombardeiro consertado, no começo da pista.$B$BQuando estiver voando, dispare as bombas para causar o maior dano possível nos Ferro Negro. Ouvi rumores de que eles estão se preparando para ativar um novo tipo de golem de guerra. Mantenha seus olhos bem abertos para isso e faça desses golens seus alvos prioritários.', '', 'Atacantes Ferro Negro mortos', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Quebrapedra na Base Aérea de Altaforja.', 0),
(26095, 'ptBR', 'Insígnias de Stromgarde', 'Consiga 7 Insígnias de Stromgarde dos integrantes da Camarilha na Bastilha de Stromgarde.', 'A Camarilha está em constante guerra contra nossa milícia em Stromgarde. No intuito de encorajar a ralé deles a encarar nossas tropas mais treinadas, os líderes da Camarilha estão oferecendo recompensa para cada Insígnia de Stromgarde que seus soldados pegarem dos corpos dos nossos homens.$B$BQueremos essas insígnias de volta. Não podemos permitir que estes assassinos acabem com a honra dos nossos mortos!$B$BEntre em Stromgarde, mate-os e recupere nossas insígnias.', '', '', '', '', '', '', '', '', '', 'Fale com a Capitão Nélia na Ponta do Refúgio, que fica no Planalto Arathi.', 0),
(26096, 'ptBR', 'Cogumelos escaldantes', 'Colete 5 Cogumelos Escaldantes.', 'Creio que temos uma utilidade para os impiedosos que o seu amigo da caverna nos enviou. No entanto, preciso de uma forma de defesa para isso.$B$BNas profundezas do Abismo Escaldante existem cogumelos com as propriedades que preciso. Traga-me alguns e verei o que posso fazer.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Falaondas Tulra no Promontório em Vashj\'ir.', 0),
(26097, 'ptBR', 'Prova de mentiras', 'Encontre Orthus no Bosque de Thal\'darah, que fica na Cordilheira das Torres de Pedra.', 'No coração do Vale Chaga de Guerra, fica uma antiga árvore – uma árvore que resistiu à força de eras e serviu como local de paz e aprendizado por gerações. Meus semelhantes estudam o druidismo no bosque, junto aos elfos noturnos, por tanto tempo quanto consigo lembrar. Agora, querem que eu acredite que a árvore guarda, dentro de si, uma arma de destruição em massa da Aliança?$B$BKrom\'gar está errado e vou provar isso!$B$BEnviei meu filho, Orthus, ao Bosque de Thal\'darah em busca dessa arma. Vá lá agora e encontre-o.', '', '', '', '', '', '', '', '', '', '', 0),
(26098, 'ptBR', 'Traição no bosque', 'Leve a Insígnia do General de Krom\'gar de volta ao Grande Chefe Andarilho da Montanha no Posto Andarilho da Montanha, que fica na Cordilheira das Torres de Pedra.', 'Cadáveres de druidas se amontoam no aposento. Algo parece errado, dado que não se vê sinal de luta. Marcas sangrentas indicam que alguma coisa foi arrastada desde a entrada.$B$BCom dificuldade, você abre a mão de Orthus e encontra algo perturbador: uma insígnia de um general de Krom\'gar.$B$BLeve a insígnia do general de Krom\'gar de volta ao grande chefe Andarilho da Montanha.', '', '', '', '', '', '', '', '', '', '', 0),
(26099, 'ptBR', 'Isso é justiça?', 'Defenda-se.', 'Ele era um bom menino, $n. Jovem, amoroso. Ele nunca mataria um jovem druida sequer. Eles eram amigos dele! Não... Não meu Orthus.$B$BO general deve pagar por esse crime. Terei justiça!', 'Defenda-se.', '', '', '', '', 'Defenda-se.', '', '', '', 'Fale com Masha Andarilha da Montanha no Posto Andarilho da Montanha, que fica na Cordilheira das Torres de Pedra.', 0),
(26100, 'ptBR', 'O general está morto', 'Fale com o Suserano Krom\'gar na Fortaleza Krom\'gar, que fica na Cordilheira das Torres de Pedra.', 'Talvez você pudesse falar com o suserano Krom\'gar, $n. Pode ser que ele escute o que você tem a dizer. Você é $Gum campeão:uma campeã; do exército dele, afinal de contas. Você viu tudo. Por favor, ajude-nos, $n. Só queremos que nos deixem em paz e a sós.$B$BFale com o suserano Krom\'gar e tente fazê-lo ver que não queríamos que nada disso acontecesse.', '', '', '', '', '', '', '', '', '', '', 0),
(26101, 'ptBR', 'Contra a força não há argumento', 'Encontre o Suserano Krom\'gar no Posto Andarilho da Montanha, que fica na Cordilheira das Torres de Pedra.', 'Você fez bem em denunciar esse crime. Os perpetradores desse ato abominável serão punidos. Haverá derramamento de sangue.$B$BPrecisarei de um novo general agora que Grebo está morto. Você tomará o lugar dele.$B$BEncontre-me no Posto Andarilho da Montanha, general. Juntos, acabaremos com essa loucura.', '', '', '', '', '', '', '', '', '', '', 0),
(26102, 'ptBR', 'O fim de Sinistracha', 'Mate o General Sinistracha na Base Aérea de Altaforja.', 'Com você abrindo caminho, finalmente conseguimos esfriar o pique inicial dos Ferro Negro. O general Sinistracha, líder dos Ferro Negro, está tentando reagrupar suas tropas no lago congelado ao sul.$B$BEle fica gritando ordens para os soldados do alto de um golem de guerra. Se eles se reagruparem, muito provavelmente vão nos sobrepujar. Você não pode permitir isso, $n. Acabe com o golem e, então, mate o general Sinistracha. Ele é a chave para nossa vitória.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Quebrapedra na Base Aérea de Altaforja.', 0),
(26103, 'ptBR', 'Biocombustível', 'Use a Bomba de Extração de Óleo nos cadáveres de Tartarugas Onda do Mar, Rêmoras das Profundezas e Cabeças de Martelo Espinhescama na Ruína de Kothrun para obter 4 amostras de Óleo de Tartaruga, 4 amostras de Óleo de Rêmora e 4 amostras de Óleo de Tubarão Martelo.', 'Combustível de submarino é caro!$b$bOs poderosos de Gnomeregan foram generosos o bastante para ceder vários barris de combustível, mas estamos queimando mais do que imaginávamos. Isso que dizer que vamos precisar improvisar.$b$bÉ sabido que as criaturas marinhas são cheias de todo tipo de químicas interessantes... como óleo, por exemplo. Leve este dispositivo até a Ruína de Kothrun e enfie ele nos cadáveres de tartarugas, rêmoras e tubarões martelo. Se não arranjarmos mais combustível de submarino, o óleo desses bichos pode ser a nossa única esperança.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Engenheiro Hexasfrega no Covil do Abismo Sombrio, que fica em Vashj\'ir.', 0),
(26105, 'ptBR', 'Reivindicando a Ruína de Korthun', 'Mate 7 Lobos-do-mar Grito Infernal na Ruína de Kothrun.', 'A Horda tem espiões nesta área? O Covil do Abismo Sombrio fica perto daqui, e lá dentro está o Tenaz X2. Não podemos deixar que a Horda se aproxime!$b$bAlguém no Covil do Abismo Sombrio vai gostar de saber disso... depois que você terminar de matar mais alguns desses espiões imundos da Horda.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Jorlan Gumecerto no Covil do Abismo Sombrio, que fica em Vashj\'ir.', 0),
(26106, 'ptBR', 'Combustologia 1', 'Use a Estação de Amostragem de Combustível no Covil do Abismo Sombrio para criar o biocombustível perfeito.', 'Quanto será que sabemos a respeito de combustíveis, $n? Elaborar o combustível perfeito é um trabalho traiçoeiro, e existem muitos fatores que precisam ser equilibrados: parâmetros de cronoperoxidação, variáveis tempero-incendiárias, critérios de silicificação conflagradora... só para citar alguns.$b$bEspero que as amostras que você me trouxe possam ser combinadas nas proporções corretas para criar... o biocombustível perfeito. Use aquele mesa ali e tente combinar algumas amostras! Traga-me o resultado quando você terminar.', 'Crie o biocombustível perfeito', '', '', '', '', 'Crie o biocombustível perfeito', '', '', '', 'Fale novamente com o Engenheiro Hexasfrega no Covil do Abismo Sombrio, que fica em Vashj\'ir.', 0),
(26107, 'ptBR', 'Espíritos elevados', 'Consiga 10 Olhos de Raptores do Planalto matando os Andarilhos do Planalto ou os Espancadores do Planalto.', 'Acordei de anos de letargia graças ao dom do xamanismo inerente à nossa raça. Hoje, sou eu quem providencia, para todos aqui, as mesmas bênçãos que renovaram minhas forças.$B$BOs raptores do Planalto são feras selvagens e astutas. Os espíritos deles podem conferir grande força para nossos guerreiros. Traga-me os olhos dos raptores para que eu possa criar os amuletos que Tor\'gan me ensinou a fazer.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gor\'mul na Ruína do Martelo, que fica no Planalto Arathi.', 0),
(26108, 'ptBR', 'A astúcia dos raptores', 'Consiga 12 Corações de Raptores dos Espreitacarnes do Planalto.', 'Ao sul, ficam os espreitacarnes do planalto, raptores ainda mais ferozes que os demais. Não são apenas fortes, mas extremamente astutos.$B$BNa minha depressão, nem mesmo os amuletos de força conseguiram me libertar de meu estado deplorável. Mas Tor\'gan usou os corações dos espreitacarnes para evocar espíritos que eliminaram minhas dúvidas, permitindo que minha alma se libertasse.$B$BNossos soldados também merecem receber a astúcia do raptor. Traga-me os corações dos espreitacarnes, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gor\'mul na Ruína do Martelo, que fica no Planalto Arathi.', 0),
(26110, 'ptBR', 'Como nos velhos tempos', 'Pegue a Pasta Lacrada da Mensageira Renegada.', 'Engraçado. Eu e a Kin passamos por tantas coisas juntas e aqui estamos nós, novamente em Arathi, como nos velhos tempos.$B$BFoi aqui que nós acabamos com os planos de criação de uma nova peste, mas parece que a Horda não aprendeu a lição, pois estão invadindo nossas fazendas mais uma vez.$B$BA mensageira morta-viva deles está perambulando por aí como se nada tivesse acontecido. Se você deseja ajudar, encontre a mensageira e traga-me o que quer que ela esteja transportando.', '', '', '', '', '', '', 'Mensageira Renegada', '', '', 'Fale novamente com Quae na Fazenda Go\'Shek, que fica no Planalto Arathi.', 0),
(26111, 'ptBR', 'Ele virá', 'Obtenha o Cérebro do Inconcebível.', 'Agora você está $Gimbuído:imbuída; nas energias dos corruptos sem-rosto.$B$BNade até meu totem-isca na trincheira a nordeste e use-o para liberar as energias. Acabe com o líder dos sem-rosto e traga-me o cérebro dele.$B$BChame por Ick\'thys, o Inconcebível... ele virá!', '', '', '', '', '', '', 'Ick\'thys, o Inconcebível', '', '', 'Fale novamente com Erunak Falapedra no Promontório em Vashj\'ir.', 0),
(26112, 'ptBR', 'Pedido de resposta', 'Leve o Relatório de Quebrapedra para Moira Thaurissan na Sala do Trono de Altaforja.', 'Então, como é que todos esses guerreiros Ferro Negro vieram parar aqui, na porta da Altaforja, praticamente já invadindo nossa cidade?$B$BA "Imperatriz" Moira, integrante do nosso estimado Conselho dos Três Martelos, não comanda os Ferro Negro? Isto não poderia ter acontecido sem o conhecimento e o consentimento dela. Não era um bando desgrenhado de anões rebeldes, mas sim uma força de invasão muito bem organizada e equipada!$B$BPreparei um relatório sobre a batalha pela base aérea. Leve-o até Altaforja, para a Sala do Trono, e confronte Moira!', '', '', '', '', '', '', '', '', '', 'Leve o Relatório de Quebrapedra para Moira Thaurissan na Sala do Trono de Altaforja.', 0),
(26113, 'ptBR', 'Quae e Kinelory', 'Encontre Quae no morro acima da Fazenda Go\'Shek.', 'A Horda controla a Fazenda Go\'shek, a leste daqui, há muito tempo. Nunca demos muita importância a este fato devido aos nossos outros problemas, mas agora recebi relatos sobre mortos-vivos na área.$B$BQualquer coisa mais séria do que peões embusteiros requer uma investigação. Esta não é a primeira vez que mortos-vivos planejam algo podre nas fazendas, por isso enviei meus melhores batedores para checar o ocorrido. Apresente-se a Quae e Kinelory. Elas vão deixá-$Glo:la; a par da situação.', '', '', '', '', '', '', '', '', '', '', 0),
(26114, 'ptBR', 'Quae confia em você', 'Fale com Kinelory perto da Fazenda Go\'Shek no Planalto Arathi.', '<Quae começa a vasculhar a pasta.>$B$BExpansão... controle territorial... esses mortos-vivos não estão tramando nada mirabolante, só o de praxe: dominar todo o Planalto. Precisamos impedir isso.$B$BVou ficar de vigia daqui de cima. Vá com a Kin e consiga os planos de invasão. Esses cadáveres ambulantes não vão nem saber o que os atingiu.$B$BE tome conta dela, entendeu?', '', '', '', '', '', '', '', '', '', '', 0),
(26115, 'ptBR', 'O que significa ser da Horda...', 'Aprenda o que significa ser da Horda.', 'Fique próxim$Go:a; de mim, $n, e observe como nossa poderosa arma destrói nossos inimigos.$B$BAprenda o que significa ser da Horda!', '', 'Aprenda o que significa ser da Horda.', '', '', '', '', '', '', '', 'Fale com o Grande Chefe Andarilho da Montanha no Posto  Andarilho da Montanha.', 0),
(26116, 'ptBR', 'O ataque de Kinelory', 'Proteja Kinelory até que ela volte para Quae.', 'Muito bem, $n. Estou pronta à sua espera.$B$BPodemos ir?', 'Proteja Kinelory', '', '', '', '', 'Proteja Kinelory', '', '', '', 'Fale novamente com Quae no Planalto Arathi.', 0),
(26117, 'ptBR', 'Pela Costa Sul', 'Fale com a Comandante Amaren na Ponta do Refúgio.', 'Já vi Kinelory ficar pior depois de uma noite de bebedeira na taberna do que ela está agora. Não há duvida de que você fez um bom trabalho em protegê-la.$B$BA Ponta do Refúgio vai querer receber notícias sobre esta missão. Vá na frente. Ficarei com Kin até ela se recuperar.', '', '', '', '', '', '', '', '', '', '', 0),
(26118, 'ptBR', 'Peguem o Embaixador!', 'Vá até a Embaixada dos Ferro Negro e use as Algemas Inflexíveis para prender o Embaixador Skoriamalho.', 'A traição do Embaixador me assombrará por muito tempo. Você deve prendê-lo antes que ele nos prejudique ainda mais. Ou pior, antes que ele fuja e comece a planejar um próximo ataque. Altaforja não estará segura enquanto o embaixador Skoriamalho estiver circulando livre pela cidade.$B$BPegue essas algemas e vá até a embaixada dos Ferro Negro. Ela fica ao norte da Sala do Trono, perto da Grande Forja. Prenda o embaixador Skoriamalho traga-o aqui.', 'Prenda o Embaixador Skoriamalho e leve-o para a Sala do Trono.', '', '', '', '', 'Prenda o Embaixador Skoriamalho e leve-o para a Sala do Trono.', '', '', '', 'Fale novamente com Moira Barbabronze na sala do trono, em Altaforja.', 0),
(26119, 'ptBR', 'FLAG - Claim Our Stake Launched', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(26120, 'ptBR', 'Os Presa do Dragão perderam a cabeça', 'Mate 12 Sequestradores de Dragonetes Presa do Dragão.', 'Os orcs Presa do Dragão daqui de perto estão se tornando um estorvo ainda maior. Os ataques suicidas deles no bosque são irritantes, mas servem de treino para as minhas sentinelas.$B$BNo entanto, meus batedores viram que eles estão usando redes para capturar os dragonetes negros. A última coisa de que estas terras precisam é a volta do adestramento de dragões. Siga para o leste, $c, e mate os sequestradores de dragonetes. Certifique-se de que aqueles imbecis não nos incomodarão mais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Caçadora Iczélia no Bosque do Verdião, que fica no Pantanal.', 0),
(26121, 'ptBR', 'Reivindicando a Ruína de Korthun', 'Mate 7 Lobos-do-mar Grito Infernal na Ruína de Kothrun.', 'Você está vendo espiões lá em cima? Isso não é nada bom... nada bom mesmo, camarada.$b$bVolte à Ruína de Kothrun e destrua-os, $gmeu amigo:minha amiga;.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Jorlan Gumecerto no Covil do Abismo Sombrio, que fica em Vashj\'ir.', 0),
(26122, 'ptBR', 'Consciência ambiental', 'Use a Bomba de Extração de Óleo nos cadáveres de Tartarugas Onda do Mar, Rêmoras das Profundezas e Cabeças de Martelo Espinhescama na Onda do Mar para obter 4 amostras de Óleo de Tartaruga, 4 amostras de Óleo de Rêmora e 4 amostras de Óleo de Tubarão Martelo.', 'Você já sentiu o cheiro de combustível de submarino, $n? O negócio é terrível. Infelizmente, temos que queimar quantidades enormes desse troço para que o Verne se mova, e isso é tanto fedido quanto mortal para a vida selvagem local. Precisamos ser mais ambientalmente conscientes.$b$bAs criaturas do mar daqui têm uma carne particularmente oleosa. Leve este dispositivo à Onda do Mar, logo acima desta caverna, e use-o nos cadáveres de tartarugas, rêmoras e tubarões martelo. O óleo delas pode salvar as vidas de centenas de outras criaturas marinhas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fiasco Girafuso na Caverna Tenebrosa, em Vashj\'ir.', 0),
(26124, 'ptBR', 'Defenda a Onda do Mar', 'Mate 7 Batedores dos Mares da Aliança na Onda do Mar.', 'A Aliança tem espiões nesta área? A Caverna Tenebrosa fica perto daqui, e dentro dela repousa o novo submarino da Horda! Não podemos deixar que a Aliança se aproxime!$b$bAlguém na caverna vai gostar de saber disso... depois que você terminar de matar mais alguns desses espiões maquinadores da Aliança.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Guarda-de-Sangue Toldrek na Caverna Tenebrosa, em Vashj\'ir.', 0),
(26125, 'ptBR', 'Defenda a Onda do Mar', 'Mate 7 Batedores dos Mares da Aliança na Onda do Mar.', 'Você viu espiões lá em cima? Isso não é bom... Não vou aceitar isso.$b$bVolte à Onda do Mar e livre-se deles antes que comecem a se meter no nosso esconderijo.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Guarda-de-Sangue Toldrek na Caverna Tenebrosa, em Vashj\'ir.', 0),
(26126, 'ptBR', 'O combustível perfeito', 'Use a Estação de Amostragem de Combustível na Caverna Tenebrosa para criar o biocombustível perfeito.', 'Quanto será que sabemos a respeito de combustíveis, $n? Elaborar o combustível perfeito é um trabalho traiçoeiro, e existem muitos fatores que precisam ser equilibrados: parâmetros de cronoperoxidação, variáveis tempero-incendiárias, critérios de silicificação conflagradora... só para citar alguns.$b$bEspero que as amostras que você me trouxe possam ser combinadas nas proporções corretas para criar... o biocombustível perfeito. Use aquele mesa ali e tente combinar algumas amostras! Traga-me o resultado quando você terminar.', 'Crie o biocombustível perfeito', '', '', '', '', 'Crie o biocombustível perfeito', '', '', '', 'Fale novamente com Fiasco Girafuso na Caverna Tenebrosa, em Vashj\'ir.', 0),
(26127, 'ptBR', 'O segredo do Martelo do Crepúsculo', 'Mate 12 membros do Martelo do Crepúsculo em Dun Modr.', 'Todo mundo desconfiava que os imbecis do Martelo do Crepúsculo estavam tramando alguma coisa, mas ninguém esperava que eles fossem sectários!$B$BO Martelo do Crepúsculo quer nada mais nada menos que a destruição do mundo inteiro. Eles já uniram forças com Asa da Morte e Ragnaros e, além de tudo, têm um histórico com os Ferro Negro.$B$BNão dou a mínima para o que eles querem, mas não posso deixar que continuem em Dun Modr! Daqui eles não passam. Acabe com eles, $n!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Thargas Sidermar em Dun Modr, que fica no Pantanal.', 0),
(26128, 'ptBR', 'A batalha da Ponte Thandol', 'Derrote Calamoth Barbacinza na Ponte Thandol.', 'Já defendi a Ponte Thandol até contra os Ferro Negro. O meu pai e o pai do meu pai também...$B$BO único membro dos Ferro Negro que conseguiu fugir de mim foi direto para a ponte. Há algo de podre por aqui e aposto que vamos cair direto em alguma armadilha repugnante.$B$B$n, pelo bem de Altaforja, preciso de sua ajuda! Posso contar com você?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Thargas Sidermar em Dun Modr, que fica no Pantanal.', 0),
(26129, 'ptBR', 'Irmãos de armas', 'Fale com o Rei Genn Greymane no Distrito Militar da cidade de Guilnéas.', 'Preste atenção, $n. É a primeira vez, desde a guerra civil, que eu concordo com o Greymane. Não é hora de se prender a velhas rixas.$B$BRealmente não acho que esses bichos deem importância ao fato de você ser um rebelde ou um nobre.$B$BAvise ao Greymane: meus homens se juntarão aos dele.$B$BHá uma casamata perto daqui, no porão do Josiah. Meus camaradas guardaram artilharia pesada lá.$B$BDiga ao seu rei que meu arsenal está à disposição.', '', '', '', '', '', '', '', '', '', '', 0),
(26130, 'ptBR', 'Cortando a conexão com L\'ghorek', 'Mate Ur\'Goz, Sku\'Bu e Neph\'Lahim.', 'L\'ghorek é o ancião que descansa no recife à frente. Ele está sendo controlado e sua energia vital está sendo lentamente consumida por um enorme ser subterrâneo$B$BHá uma caverna conhecida como Concha Subterrânea debaixo de L\'ghorek. Nela há três poderosos ogros magos que mantêm um ritual que liga o monstro subterrâneo com o ancião. Você terá de matar os três ogros para que o monstro se desconecte de L\'ghorek.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Erunak Falapedra no Promontório em Vashj\'ir.', 0),
(26131, 'ptBR', 'Reforços para Loch Modan', 'Peça ao Grif Trovino, na Grande Forja, um voo para Loch Modan. Fale com o Piloto Pisafundo quando chegar.', 'Estou esperando que o concílio considere meu pedido há horas, mas eles parecem não se importar. O maior desejo de Moira parece ser paralisar o concílio.$B$BEnquanto isso, Loch Modan sofre. Nossos inimigos são muitos e nossos recursos, poucos. Por favor, $n. Já que o concílio não me dá ouvidos, quem sabe você possa me escutar. Fale com Grif Trovino, o mestre de grifos de Altaforja. Ele fica na parte leste da Grande Forja e lhe arranjará um voo grátis até o Desfiladeiro do Portão Sul. Apresente-se ao piloto Pisafundo quando chegar.', '', '', '', '', '', '', '', '', '', 'Fale com o Piloto Pisafundo no Posto de Guarda do Portão Sul.', 0),
(26132, 'ptBR', 'Malévolos do mundo etéreo', 'Mate 8 Malévolos Etéreos.', 'Os ogros magos da Concha Subterrânea evocaram malévolos do mundo etéreo para defendê-los.$B$BNão podemos arriscar que essas aberrações sejam mais tarde usadas contra nossas forças. Enquanto estiver por lá, quero que você destrua o máximo de malévolos que puder.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Taylor no Promontório em Vashj\'ir.', 0),
(26133, 'ptBR', 'Malévolos do mundo etéreo', 'Mate 8 Malévolos Etéreos.', 'Os ogros magos da Concha Subterrânea evocaram malévolos do mundo etéreo para defendê-los.$B$BNão quero ver essas aberrações usadas contra nossas forças. Quando estiver por lá, quero que você destrua todas elas!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Legionário Nazgrim no Promontório em Vashj\'ir.', 0),
(26134, 'ptBR', 'Nada resta para você aqui', 'Fale com Furien em Tethris Aran, que fica em Desolação.', 'Não há mais nada para você aqui, $n. Quanto a mim, devo colocar o corpo de Masha para descansar. Feito isso, irei ao local do bombardeio e darei início ao processo de recrescimento. Talvez, um dia, um novo bosque floresça, um bosque permeado pelo espírito de meu filho e dos jovens elfos noturnos que se foram.$B$BSe você quiser seguir para Desolação, ouvi dizer que um elfo sangrento chamado Furien procura parceiros de aventuras. Talvez seja o caso de você procurá-lo.$B$BAdeus, amig$Go:a;. Jamais $go:a; esquecerei.', '', '', '', '', '', '', '', '', '', '', 0),
(26135, 'ptBR', 'Visões do passado: ascensão das profundezas', 'Observe a história da Dama Guerreira usando a lâmina quebrada no Templo de Quel\'Durmar.', 'O que você me contou a respeito das nagas não saiu da minha cabeça. Quem serão esses aliados que elas estão evocando? Elas realmente acham que podem derrotar o Caçador das Marés?$B$BEscapar desta caverna traz um pouco de alívio, mas nosso propósito aqui perdura. Espero que queiras ir em busca de mais respostas da Dama Guerreira uma última vez.$B$BSó posso imaginar um lugar para onde elas teriam levado o artefato: o templo na parte de cima das ruínas. O local certamente está muito bem protegido. Logo, tome cuidado.', '', 'Infiltrar-se no Templo de Quel\'Durmar', 'Observe a história da Dama Guerreira', '', '', '', '', '', '', 'Fale novamente com a Falaondas Tulra no Repouso da Legião.', 0),
(26136, 'ptBR', 'FLAG – Rigor Mortis removido', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(26137, 'ptBR', 'Cuidando dos rapazes', 'Vá até o Pantanal e fale com o Montanhista Rharen nos arredores de Dun Algaz.', 'Você já deve ter visto o tamanho do estrago no Loch Modan. E o problema não se resume a isso: toda aquela água foi para algum lugar, e esse lugar é o Pantanal.$B$BMuitos anões de qualidade estão lá, tentando ajudar, e eles precisam de suprimentos. Por isso, mandei dois montanhistas levarem um barril de cerveja para eles.$B$BMas eu não tive mais notícias deles desde que passaram pela estrada para Dun Algaz. Você poderia ver se está tudo bem?', '', '', '', '', '', '', '', '', '', '', 0),
(26139, 'ptBR', 'Caminho para Arathi', 'Vá para o Planalto Arathi e fale com a Capitão Nélia na Ponta do Refúgio.', 'Você devia ir na frente e alertar o povo do outro lado de Than\'dol sobre isto, $n.$B$BAtravessando a ponte ao norte você chegará à Ponta do Refúgio, a fortaleza da Aliança em Arathi. Diga à Capitão Nélia para ficar atenta quanto a esses malditos do Martelo do Crepúsculo.', '', '', '', '', '', '', '', '', '', '', 0),
(26140, 'ptBR', 'Comunicando-se com os Ancestrais', 'Entregue o Cérebro do Inconcebível para L\'ghorek, no Cerebrilho, localizado dentro de L\'ghorek, em Vashj\'ir.', 'Coloque na cabeça um dos impiedosos mortos para que você se pareça com um dos escravos.$B$BEntre então em L\'ghorek e tente comunicar-se com o ancião.', '', '', '', '', '', '', '', '', '', '', 0),
(26141, 'ptBR', 'Pedras rúnicas da vinculação', 'Colete 7 Pedras Rúnicas da Vinculação.', 'NO OUTRO... LADO... DA CÂMARA... HÁ CANDIDATOS... À ASCENSÃO.$B$BPRECISAREMOS... DAS... PEDRAS RÚNICAS DA... VINCULAÇÃO... PARA CRIAR UMA... MANEIRA DE CONTROLAR... UM... SERVO ELEMENTAL.', '', '', '', '', '', '', '', '', '', 'Fale novamente com L\'ghorek, no Cerebrilho, localizado dentro de L\'ghorek, em Vashj\'ir.', 0),
(26142, 'ptBR', 'Ascender nunca mais!', 'Destrua 5 Dutos Antigos.', 'PARA IMPEDIR... OS... RITUAIS DE ASCENSÃO... VOCÊ PRECISA... DESTRUIR... OS DUTOS ANTIGOS.$B$BELES USAM OS... DUTOS... PARA... DRENAR MINHAS... ENERGIAS... E CRIAR... ASCENDENTES.$B$BA LUTA CONTRA... NEPTULON...É IMINENTE. O MARTELO DO CREPÚSCULO... DEVE SER... DETIDO.', '', 'Dutos Antigos destruídos', '', '', '', '', '', '', '', 'Fale novamente com L\'ghorek, no Cerebrilho, localizado dentro de L\'ghorek, em Vashj\'ir.', 0),
(26143, 'ptBR', 'Nada mais elevado', 'Mate Hallazeal, o Elevado.', '<A voz do ancião pressiona sua mente.>$B$BAGORA QUE... VOCÊ ROUBOU... AS ENERGIAS DOS... FIÉIS... ENTRE NO... TEMPLO... E DESTRUA... HALLAZEAL, O ELEVADO.', '', '', '', '', '', '', 'Hallazeal, o Elevado', '', '', 'Fale novamente com L\'ghorek, no Cerebrilho, localizado dentro de L\'ghorek, em Vashj\'ir.', 0),
(26144, 'ptBR', 'Aprisionados', 'Resgate 5 Prisioneiros da Aliança.', 'Os sectários do Crepúsculo deixaram cair esta chave. Use-a para libertar os prisioneiros da Aliança nas jaulas dentro de L\'ghorek.$B$BApresse-se antes que os prisioneiros sejam sacrificados!', '', 'Prisioneiros da Aliança resgatados', '', '', '', '', '', '', '', '', 0),
(26145, 'ptBR', 'A ameaça trogg', 'Pegue 8 Dentes de Pedra de Trogg.', '$C, não sei se você já soube da ameaça trogg, que paira sobre as terras enânicas. Os Reservistas de Altaforja foram enviados ao front da Aliança. Com isso, nos restou apenas uma fração das tropas necessárias para manter a segurança destas terras. Meu regimento foi designado para vigiar esta cidade e não podemos deixar nossos postos, por causa do perigo de invasão.$b$bMas temos que oferecer alguma resistência a estes malditos troggs que espreitam as montanhas. Ataque-os, se for capaz. E traga oito dentes de pedra desses selvagens como prova da façanha.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Sapatorro no Vale dos Reis, em Loch Modan.', 0),
(26146, 'ptBR', 'Em defesa das terras do Rei', 'Mate 12 Troggs Lascapedra ou Batedores Lascapedra.', 'Temos que proteger o Loch, $n! Com tantas tropas lutando bravamente em frentes longínquas, nós ficamos sobrecarregados com a defesa de casa. Tem troggs surgindo de cada fenda na rocha! Essa infestação é a maior ameaça a Altaforja hoje.$b$bPrecisamos da sua ajuda, $Gbravo aventureiro:brava aventureira;, para dar fim a esse perigo. Mate doze troggs Lascapedra e volte aqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Balbúrdia no Vale dos Reis, em Loch Modan.', 0),
(26147, 'ptBR', 'Agora é que o bicho pega', 'Mate 8 Xamãs Lascapedra e 8 Quebraossos Lascapedra.', 'Os montanhistas me contaram que você é muito competente e $Gcorajoso:corajosa;. $GUm:Uma; $r como você seria muito útil por aqui. Os reservistas foram convocados para o front e ficamos desguarnecidos. Mas agora que temos $Gum:uma; $c $Gveterano:veterana; conosco, vamos ver o que podemos fazer.$b$bSaia em campo e mate oito xamãs Lascapedra e oito quebraossos Lascapedra. Eles devem estar nas montanhas ao sul, dentro e no entorno das cavernas.$b$bVamos ver se você vai fazer jus à sua reputação, $Gmatador:matadora; de troggs.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Batemuro no Vale dos Reis, em Loch Modan.', 0),
(26148, 'ptBR', 'Um ataque decisivo', 'Mate Gromug.', 'Parece que essas criaturas de Loch Modan estão sendo lideradas por um chefe conhecido como Gromug. Ele é o maior dos troggs daqui e se esconde nas partes mais profundas das cavernas ao sul.$b$bCaso você se sinta $Gmerecedor:merecedora; de tal encargo, $n, quero que você lidere a missão para assassinar Gromug.', '', '', '', '', '', '', 'Gromug', '', '', 'Fale novamente com o Capitão Balbúrdia no Vale dos Reis, em Loch Modan.', 0),
(26149, 'ptBR', 'Aprisionados', 'Resgate 5 Prisioneiros da Horda.', 'Os sectários do Crepúsculo deixaram cair esta chave. Use-a para libertar os prisioneiros da Horda nas jaulas dentro de L\'ghorek.$B$BApresse-se antes que os prisioneiros sejam sacrificados!', '', 'Prisioneiros da Horda resgatados.', '', '', '', '', '', '', '', '', 0),
(26150, 'ptBR', 'Visitando Mabel', 'Fale com Mabel Madruga nos Vinhedos dos Madruga, que fica na Floresta de Elwynn.', 'Você parece gostar de ajudar, $n. O que acha de fazer um favor a um velho?$B$BDa última vez que estive nos Vinhedos dos Madruga, ouvi Mabel chorando. Você poderia, por gentileza, ir ao chalé onde ela mora e ver como ela está? Estou um pouco preocupado.', '', '', '', '', '', '', '', '', '', '', 0),
(26152, 'ptBR', 'Procura-se: Tiago Ciríaco', 'Mate Tiago Ciríaco e arranque a cabeça dele.', 'Por decreto do Exército de Ventobravo, uma recompensa é por meio deste oferecida pela cabeça de Tiago Ciríaco.$B$BCiríaco é procurado por roubo, furto, incêndio criminoso e assassinato. Ele também é suspeito do sequestro e desaparecimento de "Princesa", a porca premiada de Braga.$B$BTiago Ciríaco foi visto pela última vez indo em direção à Madeireira Vale do Leste.$B$BTraga Tiago Ciríaco perante a justiça e se apresente ao Delegado Macredo na Madeireira Vale do Leste.', '', '', '', '', '', '', '', '', '', 'Leve a Cabeça de Tiago Ciríaco para o Delegado Macredo na Madeireira Vale do Leste, que fica na Floresta de Elwynn.', 0),
(26153, 'ptBR', 'Panquecas de abóbora da Magali', 'Obtenha 8 Abóboras de Ventobravo. Entregue-as para Chico Magarefe em Ventobravo.', 'Minha filha, a Magali, adora panquecas de abóbora. Mas as geadas do último inverno acabaram com as plantações de abóbora de Elwynn. Eu soube que há um roçado de abóboras lá para o norte de Ventobravo que está no ponto para ser colhido. Vá até lá, colha algumas abóboras maduras para mim e veremos o que podemos fazer.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Chico Magarefe em Ventobravo.', 0),
(26154, 'ptBR', 'Extermínio do crepúsculo', 'Tome controle de uma Torrente Vinculada e use-a para matar 50 Devotos do Crepúsculo e 10 Feitores Sem-rosto.', 'AGORA... USE A... PEDRA RÚNICA HARMONIZADA... PARA... CONTROLAR... UMA DAS... TORRENTES CONFINADAS... NO TEMPLO CENTRAL. ELES VÃO IGNORÁ-$GLO:LA;. VOCÊ NÃO SERÁ... NOTAD$GO:A;.$B$BUSE... OS PODERES... DO ELEMENTAL... PARA... DESTRUIR... OS DEVOTOS DO CREPÚSCULO... E OS... FEITORES SEM-ROSTO.', '', 'Torrente Vinculada possuída', '', '', '', '', '', '', '', '', 0),
(26157, 'ptBR', 'Kasim Sharim', 'Apresente-se a Kasim Sharim na parte de trás das Cavernas Serpeantes, que ficam na Barreira do Inferno.', 'Preciso de você para passar adiante uma mensagem.$b$bKasim Sharim é um velho mago sangrento que sabe muito a respeito dos demônios da Barreira do Inferno. Apesar de não aparentar, ele é muito velho e muito poderoso... e talvez um pouco excêntrico. Ultimamente ele tem passado os dias nas profundezas das Cavernas Serpeantes, não longe de onde você matou aqueles sectários.$b$bPor favor, entregue esta mensagem a ele. Ele saberá o que significa.', '', '', '', '', '', '', 'Kasim Sharim', '', '', '', 0),
(26158, 'ptBR', 'Em harmonia com a pedra-sangrenta', 'Harmonize-se com as Pedras-sangrentas Teleportadoras nas Cavernas Serpeantes.', 'Você se divertiu lutando para chegar nesta parte da caverna? Admito que não escolhi o lugar mais... conveniente para realizar os meus estudos, especialmente para aventureiros passantes que desejam entrar e sair à vontade.$b$bContudo, posso permitir que você se harmonize com minhas pedras-sangrentas teleportadoras. Basta colocar as suas mãos na pedra do canto de trás e você será teleportad$go:a; para fora da caverna. Para voltar, é só usar a pedra e você será teleportad$go:a; novamente.', '', 'Use a Pedra-sangrenta Teleportadora interna', 'Use a Pedra-sangrenta Teleportadora externa', '', '', '', '', '', '', 'Fale novamente com Kasim Sharim nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26159, 'ptBR', 'A primeira etapa', 'Obtenha 9 frascos de Sangue de Hiena Rasgarrindo e 9 frascos de Sangue de Basilisco Itarrubra.', 'Como todo mago sangrento que se preza, realizo a minha magia com sangue. Todo sangue é diferente, e a Barreira do Inferno tem muitos sabores úteis, se você souber onde procurar.$b$bPara os nossos propósitos? Basiliscos e hienas, em quantidades iguais. Vamos precisar de bastante. Vá para o oeste, até o centro da Barreira do Inferno. E não se esqueça... você pode usar aquele teleportador!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kasim Sharim nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26160, 'ptBR', 'Ritual de sangue', 'Fale com Kasim Sharim para começar o ritual de sangue.', 'Suponho que você queira saber o que estamos fazendo. Aqui vai a versão resumida, e que conheço como a palma da minha mão:$b$bOs sectários Devotos da Sombra querem evocar o demônio Razelikh de volta à Barreira do Inferno. Não podemos deixar isso acontecer. Assim sendo, nós que vamos evocar ele para, então, matá-lo. Uma tarefa menos simples do que parece...$b$bAvise-me quando você estiver pront$go:a; para começar o ritual de sangue e, então, afaste-se.', 'Fale com Kasim Sharim para começar o ritual de sangue.', '', '', '', '', 'Fale com Kasim Sharim para começar o ritual de sangue.', '', '', '', 'Fale novamente com Kasim Sharim nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26161, 'ptBR', 'Não apenas um corpo', 'Encontre a Cabeça de Loramus, o Torso de Loramus e as Pernas de Loramus.', 'Precisamos de Loramus Talípedes, o caçador de demônios. Ele conhece o verdadeiro nome de Razelikh, e você sabe: se você conhece o nome do demônio, você tem poder sobre ele. O problema é que Loramus foi morto e despedaçado.$b$bSe você me trouxer os pedaços, ainda teremos um recurso. Todos os três pedaços estão a oeste... Os ogros Malhorrendo os escondem nas cavernas deles. Vá depressa, pois, assim como o Grímeo, o Loramus também está em dívida comigo...', '', '', '', '', '', '', 'Loramus Talípedes', '', '', 'Fale novamente com Kasim Sharim nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26162, 'ptBR', 'O altar das tempestades', 'Leve o Cadáver de Loramus ao Altar das Tempestades e proteja-o enquanto o ritual é realizado.', 'No topo dos penhascos a oeste encontra-se um altar poderoso. Um altar DEMONÍACO, protegido por sectários, mas, ainda assim, poderoso. Se você conseguir chegar até ele, você poderá usá-lo para trazer Loramus de volta.$b$bÉ provável que o altar resista aos seus esforços, então você terá que proteger o corpo de Loramus até que o ritual seja concluído. Depois, traga o caçador de demônios a mim.', '', 'Loramus ressuscitado', '', '', '', '', '', '', '', 'Fale com Loramus Talípedes nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26163, 'ptBR', 'O tempo é curto', 'Entregue a Runa Dissonante ao Vigia Grímeo no Portal Negro, que fica na Barreira do Inferno.', 'O Razelikh está planejando voltar para a Barreira do Inferno e dominar Azeroth. Neste exato momento, ele está se preparando para evocar legiões de demônios e nos riscar do mapa. Com os três amuletos, nós podemos evocar Razelikh – mas como destruí-lo?$b$b<Com um gesto rápido, o gnomo desenha uma runa no ar e a entrega para você.>$b$bEntregue isto para Grímeo, no Portal Negro, a sudeste daqui. Ele vai orientar você. Rápido! O tempo é curto! E eu também!', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Vigia Grímeo no Portal Negro, que fica na Barreira do Inferno.', 0),
(26164, 'ptBR', 'O granito carbonizado do Portal Negro', 'Obtenha 24 Lascas de Granito Carbonizado.', 'Kasim quer que tu recolhas para ele algumas lascas de granito desses pedaços de pedra em torno do Portal Negro. Não sei para quê ele necessita de tais fragmentos, mas tenho lá as minhas suspeições – e nenhuma delas é agradável.$b$bUsa esta picareta e procura pelas pequenas saliências de pedra ao longo do perímetro do raio de explosão do portal.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Vigia Grímeo no Portal Negro, que fica na Barreira do Inferno.', 0),
(26165, 'ptBR', 'O sangue vil dos demônios', 'Obtenha 7 garrafas de Sangue Demoníaco Torpe.', 'Sharim quer sangue de demônio. No que me diz respeito, essa coisa nem se parece com sangue – está muito mais próximo de ser putrefação em forma líquida – mas minhas crenças não têm importância nesta questão.$b$bPara a tua sorte, a área em torno do Portal Negro está coalhada de demônios. Infernais, canisvis, guardas vis... todos eles têm o que tu precisas, em grandes e pustulentas quantidades.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Vigia Grímeo no Portal Negro, que fica na Barreira do Inferno.', 0),
(26166, 'ptBR', 'Potencializando a pedra', 'Leve o Pacote do Grímeo para Kasim Sharam nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', '<Grímeo termina de empacotar os materiais em um embrulho caprichoso.>$b$bIsto é tudo que o gnomo nos solicitou. Quando tu o encontrares, avisa-o que esta tarefa salda a dívida que tenho com ele. Não mais me submeterei aos caprichos dele.', '', '', '', '', '', '', '', '', '', '', 0),
(26167, 'ptBR', 'O amuleto de Allistarj', 'Obtenha o Amuleto de Allistarj das Cavernas Serpeantes, que ficam na Barreira do Inferno.', 'Para evocar o nosso demônio, precisamos de três amuletos, e o primeiro é o Amuleto de Allistarj.$b$bAllistarj está morto, mas ele trancou o amuleto em um baú que está aqui, nesta caverna. Junto com os outros amuletos, esta relíquia nos dará acesso ao covil de Razelikh.$b$b<Kasim se concentra por um momento.>$b$bO amuleto está perto da entrada. Recomendo que você use o teleportador.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kasim Sharim nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26168, 'ptBR', 'O amuleto de Sevine', 'Obtenha o Amuleto de Sevine de Fiasco-sal perto da Costa Partida, que fica na Barreira do Inferno.', 'O segundo amuleto, o amuleto de Sevine, está nas mãos de um murloc, bem ao sul, em um recife de frente para a Costa Partida. Como ele foi parar na mão daquele murloc eu não sei dizer, mas posso garantir que você o encontrará lá.$b$bTraga o amuleto dela para mim, junto com os demais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kasim Sharim nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26169, 'ptBR', 'O amuleto de Grol', 'Obtenha o Amuleto de Grol na Costa Partida, que fica na Barreira do Inferno.', 'Grol... o ogro.$b$b<Kasim gargalha.>$b$bParece que o corpo de Grol não se encontra mais com os ogros. Ele e o seu amuleto de poder estão em um navio acidentado na Costa Partida, a leste. Este amuleto é o último que precisamos... uma vez combinados, os três nos darão acesso a Razelikh, e então teremos a nossa chance de acabarmos com loucura dele.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kasim Sharim nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26170, 'ptBR', 'O ritual final', 'Fale com Kasim Sharim e participe do ritual dele.', 'A faca está pronta. Loramus está presente, e ele sabe o que deve ser feito. Agora, preciso pegar os três amuletos e usar o encantamento deles para conceder a você acesso a Razelikh, o criador dos amuletos.$b$bEstou preparado para realizar o ritual em você e em Loramus. Fale comigo quando estiverem prontos.', 'Participe do ritual de Kasim Sharim.', '', '', '', '', 'Participe do ritual de Kasim Sharim.', '', '', '', 'Fale com Loramus Talípedes nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26171, 'ptBR', 'Você é Rakh\'likh, demônio', 'Fale com o Psicopompus ao norte do Cerro do Profanador. Uma vez no topo do Cerro, destrua o corpo de Razelikh e então use a Faca Pétrea do Aprisionamento para encarcerar a alma do demônio.', '$gHerói:Heroína;, ouça bem.$b$bPrimeiro, precisamos viajar até Psicopompus, que nos aguarda ao pé do Cerro do Profanador, ao nosso noroeste. Psicopompus nos levará ao topo do cerro. Uma vez lá, você me ajudará a derrotar Razelikh, pois temo que, sozinho, eu não seja forte o bastante para vencê-lo.$b$bMais importante que isso, preciso que você segure a faca de pedra e não a use até eu mandar. A faca aprisionará a alma de Razelikh dentro de um novo e eterno cárcere.$b$bSe formos bem-sucedidos, fale com Grímeo, o draenei.', '', 'Cadáver de Razelikh destruído', 'Alma de Razelikh aprisionada', '', '', '', 'Rakh\'likh', '', '', 'Reporte o destino de Loramus ao Vigia Grímeo no Portal Negro, que fica na Barreira do Inferno.', 0),
(26172, 'ptBR', 'Um mago sangrento também precisa comer', 'Obtenha 5 Bifes de Jubacinza de Javalis Jubacinza na Barreira do Inferno.', 'Apesar da crença popular, os magos sangrentos antigos e poderosos NÃO bebem sangue. Nós ingerimos comida normal como todo mundo – algo que pode ser difícil de obter em meio às privações de uma fortaleza sectária.$b$bOs javalis jubacinza no vale central da Barreira do Inferno servem, ao menos, para comer – já que a carne deles não exige qualquer cozimento. Você caçaria esses javalis para me ajudar a repor o meu estoque cada vez mais escasso?', '', '', '', '', '', '', '', '', '', 'Volte a falar com Kasim Sharim nas Cavernas Serpeantes, que ficam na Barreira do Inferno.', 0),
(26173, 'ptBR', 'Protegendo a retaguarda', 'Mate Jarroc Asa-dilacerada, Shahandana e Gomegaz.', 'Você só está me vendo lado a lado com soldados da Horda porque o nosso dever supera a rivalidade... ainda que por pouco. Fomos encarregados de proteger o Portal Negro de viajantes não autorizados. Após o recente cataclismo, ficamos particularmente suscetíveis a ataques. Já ouvimos relatos sobre dragões negros na área...$b$bMeus homens estão ocupados com a vigilância, por isso precisamos que alguém mantenha os demônios da área sob controle. Você encontrará três subchefes demoníacos nos arredores do portal. Mate-os.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante da Guarda Relthorn Declinéter no Portal Negro, que fica na Barreira do Inferno.', 0),
(26174, 'ptBR', 'O seguro morreu de velho', 'Examine os Planos da Horda no Portal Negro sem ser peg$go:a;.', '<O comandante da guarda Relthorn Declinéter sussurra de modo furtivo.>$b$bTenho ordens de... de superiores... para as quais você seria adequad$go:a;. Eu notei agentes da Horda se referindo a uma pilha de papéis naquele barril logo ali. Eu gostaria de dar uma olhada nesses papéis para descobrir o que eles estão tramando. Minha missão e meu posto me impedem de realizar uma tarefa suspeita dessas, mas $Gum:uma; recém-chegad$Go:a; como você pode ser capaz de passar despercebid$Go:a;...', '', 'Planos da Horda examinados', '', '', '', '', '', '', '', 'Fale novamente com o Comandante da Guarda Relthorn Declinéter no Portal Negro, que fica na Barreira do Inferno.', 0),
(26175, 'ptBR', 'Mecassur', 'Apresente-se ao Prefeito Charlton Connisport em Mecassur, que fica na Barreira do Inferno.', 'A não ser pelo o que você viu, o Portal tem estado surpreendentemente quieto. Receio que eu não tenha muito mais trabalho para te oferecer.$b$bSe você está procurando confusão, a colônia de pescadores guilneana, a sudoeste, pode resolver. Mecassur, se me lembro bem.$b$bEu sei que deveríamos ser aliados dos guilneanos, mas francamente... worgens? Já tive problemas suficientes para me acostumar com os draeneis.', '', '', '', '', '', '', '', '', '', '', 0),
(26176, 'ptBR', 'Para Thelsamar!', 'Entregue o Relatório Situacional de Balbúrdia para o Montanhista Kadrell em Thelsamar.', 'Você nos ajudou muito aqui. Caso esteja de partida, poderia entregar este relatório da situação em Thelsamar?$B$BBasta seguir a estrada em direção ao norte, não dá para errar. O montanhista Kadrell está esperando o relatório.', '', '', '', '', '', '', '', '', '', '', 0),
(26177, 'ptBR', 'Da lama ao caos', 'Pegue 6 Caranguejos do Canal e entregue-os para Chico Magarefe em Ventobravo.', 'O Rei adora patinhas de caranguejo frescas. É uma das iguarias favoritas dele. Nas últimas semanas, tivemos muita sorte pegando caranguejos nos canais. Você poderia me dar uma mãozinha e pegar alguns para mim? Lembre-se de pegá-los vivos: caranguejos mortos não servem porque o Rei gosta de comê-los bem fresquinhos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Chico Magarefe em Ventobravo.', 0),
(26178, 'ptBR', 'Planning for the Future', 'Collect 12 Snowfall Glade Pups. Deliver them to Trapper Mau\'i at Moa\'ki Harbor.', 'We must move decisively against the wolvar if we\'re to have a chance of survival. However, I worry that in our zeal, too many of them will be slain.$B$BThe Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance.$B$BIf Elder Ko\'nani hasn\'t asked you already, he will ask you to deal with them.  While you\'re upon the glade to the north, I\'d like you to bag up their pups and bring them back to me.', '', '', '', '', '', '', '', '', '', 'Return to Trapper Mau\'i at Moa\'ki Harbor in Dragonblight.', 0),
(26179, 'ptBR', 'Empreendimentos S.A.', 'Mate 7 Trabalhadores da Empreendimentos S.A. para Morin Espreita Nuvem na Aldeia Casco Sangrento.', 'Isso explica o aumento do número de empregados e equipamentos da Empreendimentos S.A. que vimos em Mulgore. Esses goblins... a empresa deles se expande rápido demais para o bem deles. É como se diz, mostre algo a um goblin e você logo ouve as balanças ao fundo.$b$bCriaturinhas gananciosas essas. Infelizmente para o empreendimento comercial deles, nós taurens não podemos permitir que eles conduzam suas operações em nossas terras. Vá à mina deles a nordeste da caravana devastada e transmita-lhes uma mensagem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Morin Espreita Nuvem em Mulgore.', 0),
(26180, 'ptBR', 'Supervisor Geringonça', 'Mate o Supervisor Geringonça e pegue a Prancheta do Geringonça.', 'De acordo com os documentos que você recuperou na caravana, a Empreendimentos S.A. maquinou muitos planos na tentativa de nos expulsar de nossas terras, para que pudessem saqueá-las à vontade.$b$bO nível a que são capazes de descer para atingir seus objetivos me enoja e aterroriza. Quero o mandante por trás dos planos morto. O nome dele é supervisor Geringonça. Encontre-o na mina da Empreendimentos S.A., a leste da caravana devastada.Traga-me a prancheta dele, e veremos se é possível descobrir algo de útil.', '', '', '', '', '', '', 'Supervisor Geringonça', '', '', 'Fale novamente com Morin Espreita Nuvem em Mulgore.', 0),
(26181, 'ptBR', 'De volta ao Covil do Abismo Sombrio', 'Fale com Erunak Falapedra no Covil do Abismo Sombrio em Vashj\'ir.', 'VOCÊ PRECISA RETORNAR... PARA O COVIL DO ABISMO SOMBRIO. ERUNAK FALAPEDRA $GO:A; AGUARDA... LÁ DENTRO.$B$BHORA... DE... MORRER...', '', '', '', '', '', '', '', '', '', '', 0),
(26182, 'ptBR', 'De volta à Caverna Tenebrosa', 'Fale com Erunak Falapedra na Caverna Tenebrosa em Vashj\'ir.', 'VOCÊ PRECISA RETORNAR... PARA A CAVERNA SOMBRIA. ERUNAK FALAPEDRA $GO:A; AGUARDA... LÁ DENTRO.$B$BHORA... DE... MORRER...', '', '', '', '', '', '', '', '', '', '', 0),
(26183, 'ptBR', 'Sidra para o rei', 'Pegue 12 Maçãs Suculentas e entregue-as para Chico Magarefe em Ventobravo.', 'Tenho uma dívida de gratidão eterna com o Rei por tudo o que ele fez por nós. E um dos favores que posso fazer para agradá-lo é preparar a bebida favorita dele! Felizmente para nós, dá para achar todos os ingredientes do drinque aqui mesmo em Ventobravo. Há macieiras em todos os distritos da cidade. Não dá para colher as frutas do pé, pois as árvores são muito altas, mas felizmente muitas maçãs já caíram no chão.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Chico Magarefe em Ventobravo.', 0),
(26184, 'ptBR', 'O sonho de Wormthorn', 'Mate 5 Destruidores Demonarcas, 5 Senhores do Medo Profanadores, 5 Arvorosos Lenhanegra Corrompidos e 3 Senhores do Brejo Esporovil na Floresta Maculada.', 'Como é notável, a maioria dos cidadãos de Mecassur não veio para a Barreira do Inferno pela atmosfera agradável. Eles vieram em busca do sonho de um druida idealista: Marl Wormthorn. Wormthorn acreditava que o Rasgo Infecto poderia ser curado, e tentou recuperá-lo.$b$bMas, parece que ele estava errado. Ele fez crescer a floresta, mas a terra continua infestada por demônios e a grande árvore está retorcida e deformada.$b$bAinda tenho esperança. Talvez, se entrarmos na Floresta Maculada e limparmos um pouco dessa corrupção...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Prefeito Charlton Connisport em Mecassur, que fica na Barreira do Inferno.', 0),
(26185, 'ptBR', 'Conselho do Círculo Cenariano', 'Apresente-se à Observadora Cenariana Shayana em Mecassur, que fica na Barreira do Inferno.', 'Acredito que a mácula da Barreira do Inferno finalmente influenciou meu amigo Wormthorn. O experimento dele falhou e, agora, a grande árvore serve apenas como ponto de encontro para os demônios se agruparem ao redor.$b$bA árvore deve ser derrubada, e Wormthorn também. Fale com a Observadora Cenariana no outro lado da cidade; ela deve ter alguma ideia sobre como proceder.$b$b$n: o ato que estamos prestes a cometer não deve chegar aos ouvidos dos habitantes de Mecassur. O moral já está suficientemente baixo.', '', '', '', '', '', '', '', '', '', '', 0),
(26186, 'ptBR', 'Recipiente demoníaco', 'Mate os Ursos Pretos Maculados, Espreitadoras Noturnas Maculadas e Uivadores Maculados na Floresta Maculada e tente reunir os pedaços deles em um Recipiente Demoníaco.', 'Precisamos atrair a atenção de Wormthorn de alguma forma. Algo que o desperte do transe. Algo de que tenhamos a garantia de que vá funcionar.$b$bOs poucos tipos de vida selvagem que conseguiram se estabelecer na Floresta Maculada estão, sem dúvida alguma, afetadas pelas energias latentes da região. A sua tarefa é coletar as partes dos corpos delas e encontrar um jeito de combiná-las em um recipiente. Se o transe de Wormthorn for druídico ou demoníaco, um grande recipiente de carne animal maculada deve ser o bastante para acordá-lo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Prefeito Charlton Connisport em Mecassur, que fica na Barreira do Inferno.', 0),
(26187, 'ptBR', 'A ruína de Marl Wormthorn', 'Mate Marl Wormthorn em Maldraz, que fica na Barreira do Inferno. Você pode usar o Recipiente Demoníaco para despertá-lo do transe.', 'Quando descobrirem o que fizemos... Não há como prever como os cidadãos de Mecassur vão reagir. Eles são tão apegados ao sonho do Wormthorn...$b$b...Ainda assim, temos que fazer isso. Leve o recipiente demoníaco e use-o para despertar Marl Wormthorn do transe. Volte aqui quando ele estiver morto.', '', '', '', '', '', '', 'Marl Wormthorn', '', '', 'Fale novamente com o Prefeito Charlton Connisport em Mecassur, que fica na Barreira do Inferno.', 0),
(26188, 'ptBR', 'Mazzranache', 'Leve um Fêmur de Puma das Estepes para Maur Clamachuva na Aldeia Casco Sangrento.', 'Meu avô me contou histórias sobre as batalhas dele com um moa chamado Mazzranache. Ele me falou dos olhos vermelhos demoníacos, das garras afiadas como navalhas e da mordida venenosa.$B$BUma vez, viajando pelas planícies, me deparei com Mazzranache. Ele é tão terrível quanto meu avô descreveu, e me deu uma bela mordida no ombro. Já reuni todos os ingredientes do remédio que preciso para me curar... exceto um fêmur de puma das estepes.$B$BEstou cada vez mais fraco... Ajude-me, por favor.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Maur Clamachuva na Aldeia Casco Sangrento, que fica em Mulgore.', 0),
(26189, 'ptBR', 'A ameaça Presirada', 'Mate Gorfax Presirada e mais 16 Orcs Presa do Dragão no Acampamento Presirada.', 'Viemos para cá para fugir dos raptores, mas caímos bem perto de um bando de orcs Presa do Dragão!$B$BJá ouvi histórias em Menethil de que os Presa do Dragão são mais bárbaros e cruéis que os outros orcs, e que eles conseguem estrangular dragões negros só com as mãos... Não sei o que é verdade e o que não é, mas não podemos deixar para lá.$B$BVocê tem cara de que dá conta do recado, $n. Siga para o leste, para o Acampamento Presirada, dê um jeito nos orcs e não deixe de pegar o líder deles!', '', '', 'Orcs Presa do Dragão mortos', '', '', '', 'Gorfax Presirada', '', '', 'Fale novamente com o Prospector Whelgar no Refúgio de Whelgar, que fica no Pantanal.', 0),
(26190, 'ptBR', 'Um banquete de pescador', 'Pegue 5 Bagres Gigantescos. Entregue os peixes para Chico Magarefe em Ventobravo.', 'Se tem um prato que o Rei adora é um bagre bem fresquinho. Esse peixe é fácil de cozinhar, mas muito difícil de pegar. É aí que você entra! Há grandes cardumes de bagres gigantes em Ventobravo, mas a disputa para pescá-los também é muito grande. Preciso que você descubra uma forma de "pegar" alguns desses belos bagres para Sua Majestade. Há pescadores nos píeres dos canais em torno da cidade. Quanto ao resto do plano, acho que você vai conseguir descobrir por conta própria.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Chico Magarefe em Ventobravo.', 0),
(26191, 'ptBR', 'O auge dos nossos esforços', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(26192, 'ptBR', 'Órfãos também gostam de biscoitos!', 'Obtenha 4 sacos de Açúcar de Confeiteiro. Entregue-os para Chico Magarefe em Ventobravo.', 'Os órfãos de Ventobravo costumam ser negligenciados, mas não hoje, $Gmeu amigo:minha amiga;. O rei ordenou que uma fornada especial de biscoitos fosse feita e entregue ao orfanato imediatamente. Eu estava quase terminando a última leva quando acabou o meu açúcar de confeiteiro. Você poderia dar um pulinho lá fora e pegar mais açúcar para mim? Você deve achar em qualquer um dos armazéns ou estalagens de Ventobravo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Chico Magarefe em Ventobravo.', 0),
(26193, 'ptBR', 'Defendendo a Fissura', 'Mate 15 nagas na Brecha Abissal.', 'Os murmúrios dos elementos estão tomando os meus pensamentos, $n...$b$bO Trono das Marés está sob cerco!$b$bNão podemos ficar passivos enquanto as nagas ameaçam o reino de Neptulon. Precisamos encontrar um modo de nos unirmos a ele.$b$bCapitão Taylor me escoltará até as profundezas, onde poderei me comunicar diretamente com Neptulon.$b$bPreciso pedir que você siga um caminho mais violento. Mantenha as forças inimigas distraídas até eu chegar em segurança à entrada do Trono das Marés.$b$bQue os espíritos nos ajudem, $n.', '', 'Mate 15 nagas na Brecha Abissal', '', '', '', '', '', '', '', 'Fale com o Capitão Taylor no perímetro da Brecha Abissal.', 0),
(26194, 'ptBR', 'Defendendo a Fissura', 'Mate quaisquer 15 nagas na Brecha Abissal.', 'Os murmúrios dos elementos estão tomando os meus pensamentos, $n...$b$bO Trono das Marés está sob cerco!$b$bNão podemos ficar passivos enquanto as nagas ameaçam o reino de Neptulon. Precisamos encontrar um modo de nos unirmos a ele.$b$bNazgrim me escoltará até as profundezas, onde poderei me comunicar diretamente com Neptulon.$b$bPreciso pedir que você siga um caminho mais violento. Mantenha as forças inimigas distraídas até eu chegar em segurança à entrada do Trono das Marés.$b$bQue os espíritos nos ajudem, $n.', '', 'Mate 15 nagas na Brecha Abissal', '', '', '', '', '', '', '', 'Fale com o Legionário Nazgrim no perímetro da Brecha Abissal.', 0),
(26195, 'ptBR', 'O verde do Verdião', 'Fale com Feralon Verdefólio no Bosque do Verdião, que fica no Pantanal.', 'O Verdião era uma lenda local. Muitos pensavam que ele era um mito: o homem-planta, o protetor do pantanal. Os elfos noturnos vieram de muito longe só para encontrá-lo, e acabaram se estabelecendo a leste depois de falar com ele.$B$BEles fizeram um bosque imenso para proteger o Verdião, mas ouvi dizer que ele está muito agitado por causa da inundação e dos danos causados à terra.$B$BOs elfos são boas pessoas. Eles precisam da ajuda de alguém como você. Se puder, conte o que fez por aqui ao druida chefe.', '', '', '', '', '', '', '', '', '', '', 0),
(26196, 'ptBR', 'Trançalonga, o Austero', 'Leve o Pacote de Suprimentos de Feralon a Trançalonga, o Austero, em Dun Modr.', 'Os anões de Dun Modr lutam dia e noite contra os Ferro Negro que invadiram o antigo lar deles. Ainda não podemos correr o risco de enviar nossas sentinelas para a batalha, mas sempre mandamos os suprimentos de que tanto precisam para continuar com a vigília.$B$BSe tiver interesse em ajudar, leve este pacote a Trançalonga, o Austero, ao norte daqui. Tenho certeza de que os homens dele estão precisando.', '', '', '', '', '', '', '', '', '', '', 0),
(26197, 'ptBR', 'O futuro de Gnomeregan', 'Encontre-se com Bipsi Tacagelo na Vila da Gambiarra.', 'Para nós, cada sobrevivente que tiramos dos salões contaminados de Gnomeregan é uma vitória. $GUm:Uma; $c como você terá papel importante no futuro de Gnomeregan. Com isso em mente, nosso líder, o grão-faz-tudo Mekkatorque, reuniu uma equipe de instrutores para ajudar você a aprender a arte da sua classe.$B$BA Bipsi Tacagelo vai ajudar a supervisionar o treinamento e o processo de ajuste à vida na superfície.', '', '', '', '', '', '', '', '', '', '', 0),
(26198, 'ptBR', 'A arte do mago', 'Chegue ao nível 3 para aprender Nova Congelante. Após aprender o feitiço, lance-a duas vezes contra um Boneco de Treinamento na Vila da Gambiarra.', 'Conforme você participar de aventuras selvagens e seu poder crescer, você começará a desenvolver novas conexões com o arcano, que lhe concederão novos feitiços.\n\nVocê vai ver. Vá! Me mostre o que você aprendeu! Estarei bem aqui.', '', 'Praticar Nova Congelante', '', '', '', '', '', '', '', 'Fale novamente com Bipsi Tacagelo na Vila da Gambiarra.', 0),
(26199, 'ptBR', 'O futuro de Gnomeregan', 'Encontre-se com a "Doutora" Girarroda na Vila da Gambiarra.', 'Para nós, cada sobrevivente que tiramos dos salões contaminados de Gnomeregan é uma vitória. $GUm:Uma; $c como você terá papel importante no futuro de Gnomeregan. Com isso em mente, nosso líder, o grão-faz-tudo Mekkatorque, reuniu uma equipe de instrutores para ajudar você a aprender a arte da sua classe.$B$BA "Doutora" Girarroda vai ajudar a supervisionar o treinamento e o processo de ajuste à vida na superfície.', '', '', '', '', '', '', '', '', '', '', 0),
(26200, 'ptBR', 'A arte do sacerdote', 'Alcance o nível 3 para aprender Palavra Sombria: Dor. Use-a 5 vezes contra um dos bonecos de treinamento na Vila da Gambiarra.', 'Sabe, conforme você se aventurar por esse mundo louco e se tornar mais poderos$go:a;, também vai começar a descobrir novos poderes.$B$BPor que você não sai por aí, ganha mais um pouquinho de experiência e depois volta para me mostrar o que aprendeu?', '', 'Praticar Palavra Sombria: Dor', '', '', '', '', '', '', '', 'Fale novamente com a "Doutora" Girarroda na Vila da Gambiarra.', 0),
(26201, 'ptBR', 'O poder do bruxo', 'Alcance o nível 3 para aprender Corrupção. Em seguida, lance o feitiço 5 vezes contra um Boneco de Treinamento na Vila da Gambiarra.', 'Para mim, não surpreende nem um pouquinho que $gum bruxo:uma bruxa; como você tenha conseguido sair de Gnomeregan. Poucos são aqueles que entendem verdadeiramente a natureza do nosso poder, mesmo entre os gnomos.\n\nConforme se tornar mais poderos$go:a;, você começará a ouvir vozes vis lhe revelando segredos, ensinando novos feitiços.\n\nQuero que você vá adquirir alguma experiência. Quando aprender algo novo, me mostre.', '', 'Praticar lançar Corrupção', '', '', '', '', '', '', '', 'Fale novamente com Alamar Carranca na Vila da Gambiarra.', 0),
(26202, 'ptBR', 'O futuro de Gnomeregan', 'Encontre-se com Alamar Carranca na Vila da Gambiarra.', 'Para nós, cada sobrevivente que tiramos dos salões contaminados de Gnomeregan é uma vitória. Vamos precisar de toda a ajuda possível para retomar nosso lar e nos livrar dos troggs e dos gnomos irradiados. Com isso em mente, nosso líder, o grão-faz-tudo Mekkatorque, reuniu uma equipe de instrutores para ajudar você na aprendizagem da sua, hum, "arte".$B$BO Alamar Carranca se estabeleceu num prédio a oeste daqui. Ele tem poderes parecidos com os seus e pode ajudar você a se ajustar.', '', '', '', '', '', '', '', '', '', '', 0),
(26203, 'ptBR', 'O futuro de Gnomeregan', 'Encontre-se com o Sargento-instrutor Virabrequim na Vila da Gambiarra.', 'Para nós, cada sobrevivente que tiramos dos salões contaminados de Gnomeregan é uma vitória. $GUm:Uma; $c como você terá papel importante no futuro de Gnomeregan. Com isso em mente, nosso líder, o grão-faz-tudo Mekkatorque, reuniu uma equipe de instrutores para ajudar você a aprender a arte da sua classe.$B$BO sargento-instrutor Virabrequim vai ajudar a supervisionar o treinamento e o processo de ajuste à vida na superfície.', '', '', '', '', '', '', '', '', '', '', 0),
(26204, 'ptBR', 'A arte do guerreiro', 'Chegue ao nível 3 para aprender Investida. Em seguida, encontre um Boneco de Treinamento na Vila da Gambiarra e use Investida contra ele.', 'Aprender é a melhor forma de melhorar. Conforme for aprendendo mais, você começará a descobrir que consegue fazer coisas das quais nunca se achou capaz.$B$BVá, adquira um pouco mais de experiência e aprenda uma nova técnica. Depois volte e a demonstre em um boneco de treinamento.', '', 'Praticar Investida', '', '', '', '', '', '', '', 'Encontre-se com o Sargento-instrutor Virabrequim na Vila da Gambiarra.', 0),
(26205, 'ptBR', 'Esse é um trabalho para o multibô', 'Use o Multibô GS-9x para limpar 5 Gêiseres Tóxicos no Aeroporto Tóxico. Quando você se aproximar de um gêiser, o Multibô GS-9x vai começar a trabalhar imediatamente.', 'Se tudo funcionar direitinho, o multibô vai nos ajudar a cumprir qualquer tarefa desagradável ou perigosa para gnomos!$B$BDepois que o Termaplugue detonou o irradiador ao fim da Operação: Gnomeregan, lama e nuvens tóxicas começaram a aflorar no velho aeroporto a sul da cidade.$B$BSe não controlarmos isso, a contaminação pode se espalhar para o restante das terras. Pegue o multibô e leve-o para perto dos gêiseres das poças verdes do Aeroporto Tóxico. Seu robô vai cair dentro!', '', 'Limpar Gêiseres Tóxicos', '', '', '', '', '', '', '', 'Fale novamente com o Engenheiro Fagulhamola na Vila da Gambiarra.', 0),
(26206, 'ptBR', 'O futuro de Gnomeregan', 'Encontre-se com Kelsey Fagulhaço na Vila da Gambiarra.', 'Para nós, cada sobrevivente que tiramos dos salões contaminados de Gnomeregan é uma vitória. $GUm:Uma; $c como você terá papel importante no futuro de Gnomeregan. Com isso em mente, nosso líder, o grão-faz-tudo Mekkatorque, reuniu uma equipe de instrutores para ajudar você a aprender a arte da sua classe.$B$BA Kelsey Fagulhaço, que é membro importante das Operações Secretas de Gnomeregan, vai ajudar a supervisionar o treinamento e o processo de ajuste à vida na superfície.', '', '', '', '', '', '', '', '', '', '', 0),
(26207, 'ptBR', 'A arte do ladino', 'Chegue ao nível 3 para aprender Eviscerar. Depois, encontre um Boneco de Treinamento na Vila da Gambiarra e pratique Eviscerar 3 vezes.', 'Conforme você for aprendendo mais e se tornando $gum ladino:uma ladina; melhor, começará a aprender novas habilidades.$B$BUma das mais potentes é encadear golpes em uma combinação, explorando a fraqueza de seu inimigo e abrindo a oportunidade de usar manobras mais fortes.\n\nVá, adquira alguma experiência e descubra como se faz. Quando descobrir, volte aqui e faça alguns testes.', '', 'Praticar Eviscerar', '', '', '', '', '', '', '', 'Fale novamente com Kelsey Fagulhaço na Vila da Gambiarra.', 0),
(26208, 'ptBR', 'A luta continua', 'Assista à apresentação da holomesa em frente ao Grão-faz-tudo Mekkatorque para saber mais sobre a Operação: Gnomeregan.', 'Os anões de Altaforja foram muito gentis ao nos acolher quando a invasão dos troggs e a radiação nos obrigaram a deixar Gnomeregan pela primeira vez. Mas mesmo, a bondade dos amigos não consegue abrandar a saudade de casa.$B$BEmiti um chamado para que bravos gnomos e outros membros da Aliança nos ajudem a retomar Gnomeregan e derrotar Termaplugue, aquele usurpador, de uma vez por todas.$B$BNós não conseguimos atingir todos os objetivos da Operação: Gnomeregan, mas Termaplugue fugiu e estamos mais perto de casa do que antes.', '', 'Saiba mais sobre a Operação: Gnomeregan', '', '', '', '', '', '', '', 'Fale com o Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 0),
(26209, 'ptBR', 'Olho vivo e faro fino', 'Fale com os desabrigados que ocuparam o Sítio dos Jansen para reunir pistas sobre o assassinato dos Taturanas.', 'O negócio é o seguinte, $Ggaroto:garota;: nós temos um crime hediondo em nossas mãos. Um duplo homicídio e um equino... cídio.$B$BPara piorar ainda mais, nós estamos em Cerro Oeste. Se eu jogar uma pedra para trás, vou acertar em pelo menos uma dúzia de mendigos com motivos de sobra para matar esses dois (e esse cavalo).$B$BNão tenho a menor ideia de quem fez isso e realmente odeio ter vindo até esse pardieiro para investigar o assassinato de dois invasores (e um cavalo), mas quero ser mico de circo se eu não encontrar o meliante que cometeu o crime. Quer ajudar? Veja se descobre alguma coisa com os vagabundos ali atrás. Esses mendigos são muito... vivos.', '', 'Pista nº 1 recolhida', 'Pista nº 2 recolhida', 'Pista nº 3 recolhida', 'Pista nº 4 recolhida', '', '', '', '', 'Fale novamente com o Tenente Horatio Laine no Sítio dos Jansen, em Cerro Oeste.', 0),
(26210, 'ptBR', 'Gammerita, cara!', 'Katum, o Pesqueiro, na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate Gammerita e apanhe a Melhor Isca de Katum da carcaça.$B$BKatum mencionou que Gammerita circula pela costa com as outras tartarugas.', 'Falaí! Tem uma tartaruga lá fora que dá de dez nas outras. É a Gammerita, chefona das mordeliscas de água salgada – uma baita duma sangue-frio gatuna e canalha à vera.$B$BCara, ela roubou as minhas iscas mais maneiras. Arrancou diretinho da linha! E desde que rolou isso os peixes não estão nem beliscando.$B$BEncontra essa cascuda pra mim e arranca a minha isca da barrigada dela!', '', '', '', '', '', '', 'Gammerita', '', '', 'Fale novamente com Katum, o Pesqueiro, na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26211, 'ptBR', 'Mordeliscas, cara!', 'Katum, o Pesqueiro, na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 10 tartarugas Mordeliscas de Água Salgada. Fale novamente com ele quando concluir a tarefa.', 'Não deixa os olhões delas te enganarem, cara! Essas mordeliscas de água salgada são um perigo. Não dá pra pescar nem cinco minutos sem aqueles sacos de peixe tamanho família arrebentarem a linha pra pegar a isca.$B$BFaz um favor pra mim e pro povo da Aldeia Revatusco. Mata elas, cara.$B$BMata todas elas!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Katum, o Pesqueiro, na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26212, 'ptBR', 'Banha perdeu o almoço', 'Banha na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre o Almoço do Banha. Fale novamente com ele quando a tarefa for concluída.$B$BBanha mencionou tê-lo esquecido na ilha ao norte. Cuidado com os trolls Ramatorpe.', 'Banha estava fazendo um piquenique no esconderijo secreto dele quando Ramatorpe feio e malvado bateu em Banha com tronco. Banha corre de volta pra Revatusco, mas esquece almoço. Banha com fome. Quem sabe você voltar esconderijo especial e pegar almoço Banha? Banha com medo. Vai norte! Ilha lá no norte ser esconderijo especial.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Banha na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26213, 'ptBR', 'De olho no lance: o clã Pata Molhada', 'Recolha a Pista de Gnoll Pata Molhada.', 'Já que não temos nenhuma pista, acho que não faz mal seguir as que você descobriu.$B$BTem uns dois acampamentos dos Pata Molhada na área. Vá atrás deles e procure mais pistas. Traga tudo que descobrir para mim. Restrinja sua busca aos batedores e gnolls Pata Molhada.', '', '', '', '', '', '', '', '', '', 'Entregue a Pista de Gnoll Pata Molhada para o Tenente Horatio Laine no Sítio dos Jansen, em Cerro Oeste.', 0),
(26214, 'ptBR', 'De olho no lance: murlocs', 'Recolha a Pista do Murloc.', 'Eu sei que não vai dar em nada, mas temos que ir atrás de todas as pistas.$B$BPreciso que você vá até a Praia Grande, a oeste daqui, e dê uma prensa em uns murlocs. Tente descobrir qualquer coisa que nos dê alguma luz sobre o assassinato.$B$BFale novamente comigo se tiver sorte, $gnovato:novata;.', '', '', '', '', '', '', '', '', '', 'Entregue a Pista do Murloc para o Tenente Horatio Laine no Sítio dos Jansen, em Cerro Oeste.', 0),
(26215, 'ptBR', 'Conheça o Lu "Dois Sapatos"', 'Fale com o Lu "Dois Sapatos" na Plantação de Abóboras do Taturana, em Cerro Oeste.', 'Hum, isso está parecendo um verdadeira história de mistério, $Gnovato:novata;. Mas infelizmente o pessoal da área não está a fim de falar e as pistas que você recolheu com os gnolls e os murlocs não valeram de nada. Vamos ter que botar em prática o plano B... "B" de buscar o Lu "Dois Sapatos".$B$BO Lu "Dois Sapatos" é um antigo informante meu que, olha que ironia do destino, mora na velha fazenda de plantação de abóboras do Taturana. Vá até lá, a oeste, e veja se o Lu sabe de alguma coisa.$B$BSe ele encher seu saco, diga que foi o Horatio que enviou você.', '', '', '', '', '', '', '', '', '', '', 0),
(26219, 'ptBR', 'Vai e volta', 'Embarque no Tenaz X2, no Castelo de Voldrin, e ajude na conquista do Covil do Abismo Sombrio.', 'Nós encontramos a fera que destruiu nossas embarcações. Ela fica no Covil do Abismo Sombrio, uma gigantesca caverna debaixo d\'água na borda do abismo.$B$BDessa vez, estamos preparados para enfrentar o monstro. Os gnomos prepararam uma belezoca para nós em Ventobravo, com tanto poder de fogo que o monstro vai molhar a calças.$B$BQuando o Tenaz X2 chegar às docas ao lado do navio, suba a bordo e ajude como puder. Estaremos logo atrás de você.', '', 'Embarque no Tenaz X2 quando ele chegar.', 'Conquiste o Covil do Abismo Sombrio', '', '', '', '', '', '', 'Fale com o Capitão Glovaal no Covil do Abismo Sombrio.', 0),
(26220, 'ptBR', 'Tudo fica melhor com bacon', 'Mate Suínos Cevados ao sul de Orgrimmar e me traga 6 Toucinhos. Vou ficar esperando aqui no Bazar.', 'Alimentar um exército orc faminto nunca é uma tarefa fácil. Pra nossa sorte, temos um bom suprimento de carne suína cevada vinda das fazendas de porcos e áreas próximas, ao sul de Orgrimmar. Me faça um favor... mate alguns porcos e me traga aquela carne de bucho deliciosa. Vou cortar tudo bonitinho e fazer tiras de bacon pro desjejum da tropa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Marogg em Orgrimmar.', 0),
(26221, 'ptBR', 'Vai e volta', 'Suba a bordo do Verne na Recompensa Estígia e ajude no ataque à Caverna Tenebrosa.', 'Você encontrou a fera que destruiu nossas embarcações. Ele fica dentro da Caverna Tenebrosa, um gigantesco covil debaixo d\'água na borda da Brecha Abissal.$B$BDessa vez, os goblins mostraram ao que vieram e construíram uma máquina fantástica no Ancoradouro Borraquilha. Ela tem tanto poder de fogo que o monstro vai molhar as calças.$B$BQuando o Verne chegar à doca, ao lado do navio, suba a bordo e ajude como puder. Estaremos logo atrás de você.', '', 'Embarque no Verne quando ele chegar.', 'Ajude no ataque à Caverna Tenebrosa', '', '', '', '', '', '', 'Fale com o Capitão "Julho" Verne na Caverna Tenebrosa.', 0),
(26222, 'ptBR', 'Catando sucata', 'Leve 7 Peças Sobressalentes para o Engenheiro Fagulhamola na Vila da Gambiarra.', 'Tem muita coisa para fazer aqui e poucos gnomos em condição de ajudar! O Grão-faz-tudo me pediu para converter alguns robôs velhos e peças usadas na Operação: Gnomeregan. Espero começar a testar uma nova linha de multibôs logo, logo!$B$BPor acaso você teria algum tempinho para me ajudar? Tem um monte de peças espalhadas por aí. Cate tudo que encontrar e traga para mim. Nunca se sabe o que pode acabar sendo útil!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Engenheiro Fagulhamola na Vila da Gambiarra.', 0),
(26223, 'ptBR', 'Espreitando os espreitadores', 'Mate 8 Espreitadores Jubaprata.', 'Muitos trolls valentes foram perdidos para os ermos inóspitos das Terras Agrestes, $r. Os jubapratas são uma das maiores ameaças aos nossos caçadores. Eles ficam à espreita, escondidos nos arbustos e na paisagem. Quando surge a oportunidade, atacam!  Esse tipo de ferocidade não pode ser ignorada!$B$BVocê precisa pensar como um jubaprata. Espreite os espreitadores! Mate todos eles!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-caça Markhor na Aldeia Revatusco nas Terras Agrestes.', 0),
(26224, 'ptBR', 'Caça às bestas', 'Mate 10 Ferujas Selvagens.', 'Bons guerreiros Revatusco foram perdidos nas garras e bicos destas bestas.$B$BMate todas as ferujas selvagens que aparecerem na tua frente, $r.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-caça Markhor na Aldeia Revatusco nas Terras Agrestes.', 0),
(26225, 'ptBR', 'Xerez de Pupellyverbos', 'Recolha 12 garrafas de Xerez de Pupellyverbos.', 'Você aí! Sabia que tem dezenas, se não centenas, de garrafas de um vinho do bom espalhadas por toda a praia ao norte daqui?$B$BBem, agora você sabe!$B$BEu estaria lá recolhendo elas aos borbotões se aquelas tartarugas não estivessem atrás de mim. Elas querem meu sangue, tô te falando!$B$BPor isso, vou te pagar pra quebrar esse galho. Me traz 12 garrafas de Xerez de Pupellyverbos que eu "compro" de você, $c.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Resmungão na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26226, 'ptBR', 'Bobó de lagostim', 'Pegue 10 Lagostins Lamacentos em Orgrimmar. Entregue os crustáceos para Marogg quando completar a missão.', 'Existem algumas lagoas em Orgrimmar que se enchem de lagostins a cada ano. Quero que você visite algumas e colete alguns crustáceos deliciosos pra mim. Se você for $gbem-sucedido:bem-sucedida;, o exército da Horda irá se banquetear hoje à noite.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Marogg em Orgrimmar.', 0),
(26227, 'ptBR', 'Cuidado que a fruta morde', 'Colha 8 Peras Espinhosas. Entregue-as para Marogg em Orgrimmar.', 'As tropas querem algo doce pra comer. Nem sempre eu dou a elas o que elas querem, mas vou abrir uma exceção dessa vez. Tenho certeza de que você já viu o cacto que cresce aqui em Orgrimmar. Eles produzem uma fruta gostosa chamada "pera espinhosa". Como deve ter dado pra perceber, o problema é que essa pera é toda coberta de espinhos. Então tome cuidado com as mãos quando for lá buscar elas pra mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Marogg em Orgrimmar.', 0),
(26228, 'ptBR', 'Cada um no seu caixote', 'Use a Velha Casa do Lu "Dois Sapatos" na parte de trás da Mina Veiojango, em Cerro Oeste.', 'Escute só: eu não podia mesmo falar coisa alguma com você, mas estou devendo uns favorezinhos pro Horatio. Eu não sei mesmo o que aconteceu com os Taturanas, mas talvez eu consiga dar uma luz para você.$B$B<Lu entrega a você um grande caixote.>$B$BEu morava nesse caixote antes de me dar bem. Mas agora eu vivo a vida dos sonhos de qualquer vagabundo!$B$BOK, agora você pega o caixote e vai para a Mina Veiojango, a sudoeste daqui. Vá para a parte de trás da mina e se esconda dentro do caixote.', 'Cada um no seu caixote!', '', '', '', '', 'Cada um no seu caixote!', '', '', '', 'Fale com o Lu "Dois Sapatos" na Plantação de Abóboras do Taturana, em Cerro Oeste.', 0),
(26229, 'ptBR', '"Pego vela SIM!"', 'Mate 12 Kobolds Escavadores.', 'Antes desses malditos kobolds me aleijarem, eu era o fornecedor de vela número um do Durval Pilão. Oras, eu até inventei o bordão "PEGO VELA SIM!". Isso mesmo, a frase é minha, sim $gsenhor:senhora;. Os kobolds diziam "Cê não pega vela!", eu só respondia "PEGO VELA SIM!" e então esmagava os miolos deles!$B$B<Jimbo se perde em pensamentos por um instante.>$B$BBons tempos aqueles... Muito bons mesmo.$B$BAgora? Agora eu não consigo nem ir ao banheiro sozinho. Quer me ajudar? Mate alguns kobolds. Tem um bando deles na mina aqui perto.', '', '', '', '', '', '', '', '', '', 'Fale com Jimbo Joanez, o Vela, na Plantação de Abóboras do Taturana, em Cerro Oeste.', 0),
(26230, 'ptBR', 'Banquete de rei', 'Pegue 6 Rabos de Coiote e 5 punhados de Terra de Formigueiro.', 'A vida em Cerro Oeste está difícil, $gfilho:filha;! Cada dia é uma luta. Às vezes passamos semanas sem uma refeição decente. Por isso é tão importante que todos se ajudem. Quem sabe você não me dá uma mãozinha, hein? Vou fazer um bolo formigueiro e preciso de alguns ingredientes.$B$BPegue alguns punhados de terra de formigueiro e uns rabos de coiote. A terra de formigueiro você pega no canteiro de abóboras aqui de frente, e há coiotes vagando pelo mato em toda Cerro Oeste.$B$BAnda logo! Temos muitas bocas para alimentar.', '', '', '', '', '', '', '', '', '', 'Fale com Mama Celeste na Plantação de Abóboras do Taturana, em Cerro Oeste.', 0),
(26232, 'ptBR', 'As últimas palavras do Lu', 'Espreite os Bandidos atrás da sede da Plantação de Abóboras do Taturana, em Cerro Oeste.', 'Dois bandidos apareceram aqui na fazenda faz pouco tempo, armando todo tipo de confusão. Eu não sei de onde eles vieram ou para quem eles trabalham, mas eu SEI que tem caroço nesse angu. Talvez eu tenha escutado umas conversas deles sobre uns assuntos muito interessantes...$B$BSe você quiser saber mais, os bandidos estão atrás da sede da fazenda. Se te pegarem ou matarem eu não te conheço. Nunca te vi, hein?$B$BBoa sorte, $ggaroto:garota;.', '', 'Espreite os Bandidos.', '', '', '', '', '', '', '', 'Volte à cabana do Lu "Dois Sapatos" na Plantação de Abóboras do Taturana, em Cerro Oeste.', 0),
(26233, 'ptBR', 'Roubando de nós mesmos', 'Recupere 6 Barris de Arroz Lançanegra. Entregue o arroz para Marogg em Orgrimmar.', 'Como você bem sabe, $n, Garrosh relegou os trolls de Orgrimmar aos arredores a oeste da cidade. O que é uma sorte, pois isso nos dá fácil acesso aos suprimentos deles. Estou preparando uma panelada de jambalaia para a infantaria e vou precisar de muito, muito arroz. Os trolls guardam o arroz em barris, perto das construções. Traga-me os barris de arroz Lançanegra para que eu consiga fazer a comida a tempo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Marogg em Orgrimmar.', 0),
(26234, 'ptBR', 'Roubando de nós mesmos', 'Recupere 6 Barris de Arroz Kezan. Entregue o arroz para Marogg em Orgrimmar.', 'Como você bem sabe, $n, Garrosh relegou os goblins de Orgrimmar aos arredores a oeste da cidade. O que é uma sorte, pois isso nos dá fácil acesso aos suprimentos deles. Estou preparando um bom lote de jambalaya pra infantaria e vou precisar de todo o arroz que puder conseguir. Os goblins mantêm o arroz estocado em barris perto das construções. Traga-me os barris de arroz Kezan e eu vou conseguir terminar a comida a tempo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Marogg em Orgrimmar.', 0),
(26235, 'ptBR', 'Até ladrões têm fome', 'Recupere 3 Rações de Infantaria da Horda. Entregue-as para Marogg em Orgrimmar.', 'Estamos com problemas... as rações da infantaria aqui em Orgrimmar já vêm sendo roubadas há duas semanas. Recentemente recebi informações de onde os crimes estão acontecendo. Onde houver caixotes de suprimentos também haverá ladrões por perto. Quero que você encontre os ladrões e recupere as rações roubadas. Fale comigo novamente quando você completar a missão.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Marogg em Orgrimmar.', 0),
(26236, 'ptBR', 'Aperto nos Saldanha', 'Fale com o Fazendeiro Saldanha na Fazenda dos Saldanha, em Cerro Oeste.', 'Então, o que descobrimos até agora? Temos que seguir as pistas.$B$BNo Sítio dos Jansen, você achou uma carta ensopada e uns retalhos vermelhos. Aqui, na fazenda, você escutou uma conversa entre um vulto sombrio e um ogro-mago. Você também conseguiu uma confissão de assassinato de um bando de criminosos, que você acabou matando depois.$B$BAlgo não se encaixa, $Gnovato:novata;.$B$BTem um casal de velhinhos que mora numa fazenda a sudeste daqui. Vá até lá e converse com o fazendeiro Saldanha para descobrir se ele sabe de alguma coisa.', '', '', '', '', '', '', '', '', '', '', 0),
(26237, 'ptBR', 'Tempos difíceis', 'Mate 10 Guarda-colheitas.', 'Estamos passando por tempos difíceis, $gmeu rapaz:dona;. Com a migração de massas de oprimidos de Ventobravo para Cerro Oeste, nossas reservas estão mais baixas do que nunca. O povo está inquieto e precisando de ajuda.$B$BAté a sede da nossa fazenda vem sendo usada como casa de passagem há anos. A Salma faz o que pode para proteger os hóspedes, mas às vezes alguns caem nas mãos dos guarda-colheitas, que são perversas abominações que perambulam pelas nossas terras – uma lembrancinha deixada pelos Défias antes de serem expulsos daqui. Ajude-nos!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Fazendeiro Saldanha na Fazenda dos Saldanha, em Cerro Oeste.', 0),
(26238, 'ptBR', 'Anões ferozes', 'Mate 10 Guerreiros Martelo Feroz ou Xamãs de Martelo Feroz.', 'A Horda fez muito por nós, os Revatusco, e não somos do tipo bicão. Com as outras tribos de trolls da floresta rechaçadas, estamos reivindicando mais terras em nome da Horda.$B$BMas, agora, os anões Martelo Feroz resolveram entrar no nosso caminho. É guerra que eles querem, é guerra que vão ter... E eu não pretendo perder a guerra pra criaturas com metade do meu tamanho.$B$BVai lá e mata uns anões pra mim.', '', 'Martelo Feroz mortos', '', '', '', '', '', '', '', 'Fale novamente com o Ancião Presa-arrancada na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26240, 'ptBR', 'Segue o meu compasso', 'Use os Tambores de Guerra Revatusco em 6 Guerreiros Revatusco.', 'Nossos guerreiros tão lá fora lutando duro pra matá aqueles anões Martelo Feroz nojentos, pra gente poder ficar numa boa aqui na vila. O mínimo que a gente pode fazer é dá uma força pra eles.$B$BUm ritmo legal é tudo que um troll precisa pra arrebentar em uma luta. O ritmo retumbante dos tambores faz a gente bater mais forte, chamando os espíritos pra proteger a gente. Leva os meus tambores pro campo de batalha. Toca eles pros guerreiros e deixa eles mostrarem pros Martelo Feroz quem manda nestas terras!', '', 'Guerreiros Revatusco encorajados', '', '', '', '', '', '', '', 'Fale novamente com a Mística Yayo\'jin na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26241, 'ptBR', 'Ensopado de Cerro Oeste', 'Pegue 6 Quiabos, 6 quilos de Acém de Ripa-carne e 6 quilos de Chã-de-fora de Goretusco.', 'Olá, $Gquerido:querida;. $GBem-vindo:Bem-vinda; à nossa casa. Hum, você não parece ser $Gum desabrigado:uma desabrigada;. Veio para nos ajudar? Se veio, não poderia ter chegado em melhor hora! Estou planejando o jantar da meninada e preciso de alguns ingredientes.$B$BVocê poderia me trazer alguns quiabos, seis quilos de chã-de-fora de goretusco e seis quilos de acém de ripa-carne para eu fazer o meu famoso ensopadinho de Cerro Oeste? Tem todos os ingredientes por aqui mesmo, perto da fazenda. Só cuidado com os guarda-colheitas. Eles matam sem misericórdia.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Salma Saldanha na Fazenda dos Saldanha, em Cerro Oeste.', 0),
(26244, 'ptBR', 'A terra reclama tudo para si', 'Destrua 5 Elementais de Pedrafunda.', 'Estamos no plano telúrico, $n. No fim, tudo é absorvido pela terra.$B$BEm breve, o Fúria da Tempestade virará pó e não conseguiremos descobrir mais nada a partir dos destroços.$B$BDestrua os elementais que estão desmantelando a aeronau. Estamos apenas protelando o inevitável, mas temos que ganhar mais tempo se quisermos rastrear todos os pedaços do Pilar do Mundo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Vidente Kormo no Templo da Terra, que fica no Geodomo.', 0),
(26245, 'ptBR', 'Belonave em perigo', 'Procure pistas nos Destroços do Fúria da Tempestade, no Geodomo.', 'A Pedra Angular estava sendo transportada em uma belonave voadora da Horda chamada Fúria da Tempestade.$B$BA belonave caiu a sul daqui, mas nós descobrimos, por meio de clarividência, que a Pedra Angular não está mais lá.$B$BProcure, por entre os destroços, pistas do que possa ter acontecido.', '', 'Primeira pista', 'Segunda pista', 'Terceira pista', '', '', '', '', '', 'Fale novamente com Maruut Atapedras no Templo da Terra, que fica no Geodomo.', 0),
(26246, 'ptBR', 'Diário de bordo', 'Entregue o Diário de Bordo para Maruut Atapedras no Templo da Terra, que fica no Geodomo.', '<Você vai direto à última, e incompleta, anotação.>$B$B...se aproximando do Templo da Terra a 300 nós e iniciando manobra de aterrissagem conforme nova rota. Percebemos um sistema de baixa pressão a norte e recolhemos o...$B$BSANGUE E TROVÃO! IMBECIS DA ALIANÇA SE APROXIMANDO!', '', '', '', '', '', '', '', '', '', '', 0),
(26247, 'ptBR', 'Diplomacia em primeiro lugar', 'Encontre a Tempestária Mylra a bordo da Belonave da Aliança.', 'A Harmonia Telúrica é uma organização neutra, $n. Não podemos escolher um lado na guerra entre a Horda e a Aliança.$B$BBasta ver à sua volta: nossos membros têm as mais diversas origens. Nossa missão ficaria comprometida se puséssemos as tensões raciais acima de nosso objetivo. Vamos tentar manter isso em sigilo até que tenhamos mais informações.$B$BMas não vamos nos precipitar. Quero que você procure a belonave da Aliança. Um dos nossos novos membros vai acompanhá-$Glo:la;.$B$BTente descobrir o máximo de informações sem nos envolver.', '', '', '', '', '', '', '', '', '', '', 0),
(26248, 'ptBR', 'Nossos amigos estão mortos', 'Use o Totem de Espírito nos corpos de 6 Tripulantes Assassinados.', 'Tem alguma coisa errada aqui, $n.$B$BToda a tripulação foi assassinada, mas eu não vi marcas de sangue nem danos à estrutura da belonave.$B$BIsso não é obra da Horda.$B$BOs espíritos dos mortos vão dar todas as respostas que queremos. Eles ainda não deixaram este mundo.$B$BBote este totem perto dos corpos da tripulação. Você vai conseguir ouvir, por alguns segundos, aos últimos pensamentos deles.$B$BMas cuidado! Não temos como prever como os espíritos dos mortos vão reagir a esse novo estímulo.', '', 'Informação de Tripulante Assassinado', '', '', '', '', '', '', '', 'Fale novamente com a Tempestária Mylra na Belonave da Aliança, que fica no Geodomo.', 0),
(26249, 'ptBR', 'A cabine do almirante', 'Procure pistas na cabine do almirante da Belonave da Aliança.', 'É possível que haja mais pistas na cabine do almirante. Ela está exatamente abaixo de nós.$B$BVeja se lá dentro há sobreviventes ou mais informações que possam nos levar ao fragmento do Pilar do Mundo. Mas cuidado, $n. Quem quer que tenha matado a tripulação ainda pode estar por lá.', '', '', '', '', '', '', '', '', '', '', 0),
(26250, 'ptBR', 'Pensando bem, faça um prisioneiro', 'Domine Mor\'norokk, o Odioso, na Belonave da Aliança, que está no Geodomo.', 'Não é tarde demais, $n. Os sectários provavelmente ainda estão aqui.$B$BVá pra parte de baixo do navio, descubra quem é o chefe e domine ele.$B$BVamos conseguir respostas de uma forma ou de outra.', '', 'Mor\'norokk, o Odioso, subjugado', '', '', '', '', 'Mor\'norokk, o Odioso', '', '', '', 0),
(26251, 'ptBR', 'Não prenda ninguém', 'Mate 6 Sabotadores do Crepúsculo.', 'Parece que o pessoal do Martelo do Crepúsculo ainda está no navio. Desce lá e acabe com todos eles.$B$BCuidado, $n. Eles não vieram aqui para um retiro espiritual, se é que você me entende.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Tempestária Mylra na Belonave da Aliança, que fica no Geodomo.', 0),
(26252, 'ptBR', 'O guarda tem coração', 'Devolva o Coração de Guarda-colheitas para o Fazendeiro Saldanha na Fazenda dos Saldanha, em Cerro Oeste.', 'Isso que você achou parece ser o coração de um guarda-colheitas.$B$BDá para ver que ainda funciona pelos sons que está emitindo. Acho melhor você devolver isso para o fazendeiro Saldanha.', '', '', '', '', '', '', '', '', '', '', 0),
(26254, 'ptBR', 'Aperto no ogro', 'Monte no Bicovento e assista ao interrogatório de Mor\'norokk.', 'Chega aí, $n. Vamos ver o que o Sr. Cara de Ogro tem a dizer.$B$BPode ficar à vontade, o Bicovento só derrubou passageiros umas duas vezes até hoje.', '', 'Mor\'norokk interrogado', '', '', '', '', '', '', '', 'Fale com a Tempestária Mylra na Belonave da Aliança, que fica no Geodomo.', 0),
(26255, 'ptBR', 'Retorno ao Templo da Terra', 'Fale com Maruut Atapedras no Templo da Terra, que fica no Geodomo.', 'Você precisa avisar a todos no templo. É muito provável que o fragmento já esteja sendo levado para um lugar mais protegido.$B$BConte a Maruut tudo o que você sabe. Enquanto isso, vou investigar mais um pouco esse tal de Conselho do Crepúsculo.', '', '', '', '', '', '', '', '', '', '', 0),
(26256, 'ptBR', 'Sangrar o Moldassangue', 'Obtenha as Ordens do Crepúsculo com um dos Moldassangue do Crepúsculo na Queda do Asa da Morte.', 'O Martelo do Crepúsculo está manipulando magias malignas aqui, $n. Eles estão vivificando e energizando os restos do sangue do Asa da Morte. Assim, em vez de secar e desaparecer, o sangue viceja e prolifera.$B$BMate um dos moldassangue e veja se encontra pistas sobre a localização desse "mestre forjador".', '', '', '', '', '', '', 'Moldassangue do Crepúsculo', 'Eles têm escravos aqui?', 'Maruut Atapedras', '', 0),
(26257, 'ptBR', 'Está vivo!', 'Use o Coração de Guarda-colheitas em um Golem Colheiteiro em Curto-circuito. Em seguida, use o mesmo Golem para matar 25 Colheitadeiras Energizadas.', 'Pelo que eu sei, basta encontrar um golem de colheita e jogar o coração dentro. Então, a criatura fica sob controle.$B$BEu acho que há um campo cheio de golens em curto-circuito na fazenda dos Peçanha. Procure os arcos elétricos.$B$BCaso você consiga botar um dos golens para funcionar, use-o para destruir as colheitadeiras energizadas na antiga fazenda dos Peçanha. Esses monstros são muito mais destrutivos do que os da fazenda.', '', 'Golem Colheiteiro em Curto-circuito ativado', '', '', '', '', '', '', '', 'Fale novamente com o Fazendeiro Saldanha na Fazenda dos Saldanha, em Cerro Oeste.', 0),
(26258, 'ptBR', 'Queda do Asa da Morte', 'Vá para a Queda do Asa da Morte, no Geodomo.', 'Faz muito sentido que o Martelo do Crepúsculo esteja envolvido no sumiço do fragmento do Pilar do Mundo. Só nos resta esperar que consigamos recuperar o fragmento rapidamente.$B$B<Maruut bota a mão no seu ombro.>$B$BEu estabeleci um laço espiritual com você. Enquanto você estiver no Geodomo, vamos conseguir nos comunicar.$B$BVá até a Queda do Asa da Morte, a sudoeste daqui, e investigue as operações do Martelo do Crepúsculo.', 'Chegada à Queda do Asa da Morte', '', '', '', '', 'Chegada à Queda do Asa da Morte', 'Maruut Atapedras', 'Eles devem ter trazido o fragmento para cá!', 'Maruut Atapedras', '', 0),
(26259, 'ptBR', 'Sangue do Guardião da Terra', 'Colete 5 amostras de Sangue de Neltharion dos Sangues Vivos na Queda do Asa da Morte.', 'Quando o Asa da Morte escapou para o Geodomo, ele sofreu uma extrema degradação, mas não absoluta.$B$BOs sectários estão recolhendo e moldando o sangue corrompido que escorreu do dragão na Queda do Asa da Morte e transformando o material em organismos vivos, dos quais sugam o poder.$B$BE se um traço do Guardião da Terra tiver resistido? Afinal, Neltharion era o aspecto da terra, antes de se tornar o aspecto da morte.$B$BRecolha amostras do Sangue Vivo criado pelos sectários para verificarmos se restou algum vestígio do Guardião da Terra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Vidente Kormo no Templo da Terra.', 0),
(26260, 'ptBR', 'O diário do Mestre Forjador', 'Encontre o Diário do Mestre Forjador na Queda do Asa da Morte, que fica no Geodomo.', 'Vá até a torre que o escravo mencionou. Ela provavelmente está no limite nordeste do campo.$B$BSe agirmos rápido, talvez seja possível até espiar a reunião do mestre forjador.', '', '', '', '', '', '', '', '', '', '', 0),
(26261, 'ptBR', 'Pergunte aos escravos', 'Pegue a Chave do Escravizador do Crepúsculo e liberte 6 Mineradores Escravizados.', 'De acordo com as ordens que você encontrou, dentro de uma tenda no limite sudeste da Queda do Asa da Morte há uma chave.$B$BPegue a chave e liberte os escravos na pedreira a sul daqui.', '', 'Mineradores Escravizados libertados', '', '', '', '', '', '', '', '', 0),
(26263, 'ptBR', 'Espinar Trovechoque', 'Mate Espinar Trovechoque.', 'A gente está tentando dar cabo do comandante dos Martelo Feroz que está invadindo nossas terras, mas ainda não tivemos sorte.$B$BEspinar Trovechoque fica lá no posto de comando, bem protegido, e a voz dele ecoa no campo de batalha, incitando os anões. Mas a gente está achando que já passou da hora de ele se calar.$B$BMate o Espinar que a gente acaba com o resto dessa peleja sem problema.', '', '', '', '', '', '', 'Espinar Trovechoque', '', '', 'Fale novamente com o Ancião Presa-arrancada na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26264, 'ptBR', 'O que deixamos para trás', 'Pegue 6 Pertences Recuperados das poças de Lodo Tóxico no Aeroporto Tóxico.', 'Todos nós vimos gnomos doentes e enlouquecidos sofrendo com a exposição aos venenos e à radiação de Gnomeregan. Com o tempo, eles vão involuir ainda mais, até se tornarem poças de lodo tóxico descerebradas, ainda que inofensivas.$B$BOs resultados das minhas pesquisas sugerem que talvez seja possível tirá-los desse estado. Vá até o Aeroporto Tóxico, a sul, domine as poças de lodo tóxico que mencionei e traga para mim os objetos dos gnomos que eles já foram um dia.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tock Molavivaz na Vila da Gambiarra.', 0),
(26265, 'ptBR', 'Está na chuva radioativa é para se molhar', 'Destrua 6 Contaminações Viventes no Aeroporto Tóxico.', 'O Tock Molavivaz tem uma teoria maluca sobre as poças de lodo tóxico, que seriam restos mortais de gnomos. Por isso, a ordem é não combatê-las por enquanto.$B$BNo entanto, o Aeroporto Tóxico, a sul daqui, está cheio de contaminações viventes, que são elementais formados por água poluída e outras matérias tóxicas. Se as deixarmos soltas, elas vão tomar conta da cidade. Você poderia nos ajudar a limpar o terreno?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Cabo Silvapito na Vila da Gambiarra.', 0),
(26266, 'ptBR', 'Esperança para o povo', 'Leve o Ensopado de Cerro Oeste para Esperança Saldanha no Morro da Sentinela.', 'Há cerca de quatro anos, na calada da noite, uma menininha entrou correndo na sede da fazenda e desmaiou no meio da sala. Ninguém conhecia a menina, e ela não se lembrava de quem era ou de onde vinha. Era uma verdadeira alma perdida.$B$BPouco tempo depois, nós a adotamos e batizamos como Esperança, que é o que ela representou para nós.$B$BAgora ela já está uma mocinha e cuida dos desvalidos e desabrigados de Cerro Oeste. Por favor, entregue à minha filha o ensopado que fiz. Ela está lá no Morro da Sentinela, a sul daqui.', '', '', '', '', '', '', '', '', '', '', 0),
(26267, 'ptBR', 'Limpeza na Rocha Oculta', 'Mate 10 Gosmas Jade.', 'Há alguns anos, havia uma base da Horda nas profundezas da Rocha Oculta. Ela está abandonada desde então, mas ainda é um território de primeira, que vale a pena ser reclamado!$B$BO problema é que ela está cheia de gosmas agora. Criaturas horrendas... estúpidas, irritantes, que comem tudo que encontram.$B$BPreciso de alguém com coragem para ir à Rocha Oculta e se livrar desses visgos. Você tem coragem pra isso, $n?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião Presa-arrancada na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26268, 'ptBR', 'Os suprimentos da Rocha Oculta', 'Recolha 5 Caixas de Suprimentos Cobertas de Gosma.', 'Eu estive na Rocha Oculta durante a segunda guerra. Eu era jovem, anos antes de conhecer minha companheira e ainda me lembro do caos quando a Aliança nos atacou. Nós fugimos com os orcs, sem tempo de recolher nossas coisas.$B$BDeixamos tudo pra trás. Rocha Oculta ainda está cheia dos nossos suprimentos. Nós precisamos deles aqui na aldeia... e mais que isso, os Martelo Feroz não podem botar as mãos imundas neles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Ancião Presa-arrancada na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26269, 'ptBR', 'Grande Espinhaço: Veredas', 'Encontre a Página 14 do Grande Espinhaço: Veredas.', 'Uma página! Eu só preciso de mais uma página!$b$bO romance do mestre Rosarães sofreu um pequeno... acidente... <Eucunha lança um olhar de acusação sobre o Mimorde>... e nós perdemos algumas páginas.$b$bEu pedi aos outros aventureiros para procurar as páginas perdidas e eles têm sido bem atenciosos, mas uma página continua perdida.$b$bEu sei que você deve estar terrivelmente ocupad$go:a; com outros assuntos, mas, enquanto você estiver rodando a selva, poderia ajudar a procurar a página perdida?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Eucunha de Clides na Expedição do Rosarães, que fica na Selva do Espinhaço Setentrional.', 0),
(26270, 'ptBR', 'Agradecemos a gentileza', 'Fale com Salma Saldanha na Fazenda dos Saldanha, em Cerro Oeste.', 'Faz muito tempo que ninguém nos ajuda, $n. Se você não tivesse aparecido aqui, é possível que a gente não sobrevivesse ao inverno. Você já provou que é altruísta, que é alguém em quem se pode acreditar. Ah, como eu queria ter algo de valor para lhe dar!$B$BEu não sei de nada que possa ajudar você nessa cruzada para pegar os assassinos dos Taturanas, mas talvez a minha mulher possa ajudar. Vá lá dentro falar com a Salma e talvez ela lhe diga o que você quer ouvir.', '', '', '', '', '', '', '', '', '', '', 0),
(26271, 'ptBR', 'Saco vazio não fica em pé', 'Use o Ensopado de Cerro Oeste para alimentar 20 Desabrigados no entorno do Morro da Sentinela, em Cerro Oeste.', 'Sim, eu ouvi falar do assassinato dos Taturanas. Foi muito triste, mas tragédias assim são rotina em Cerro Oeste. Muita gente aqui não tem como, ou não tem mais ânimo, para comer. Perderam todas as esperanças. Dá para entender o que significa estar tão desamparado a ponto de desistir de viver? Temos que trabalhar juntos para mostrar a essa gente que ainda há esperança. Que, com o alvorecer de um novo dia, virá uma vida melhor.$B$BPegue o ensopado que minha mãe fez e ajude a alimentar os desamparados do Morro da Sentinela.', '', 'Desabrigado de Cerro Oeste alimentado', '', '', '', '', '', '', '', 'Fale novamente com Esperança Saldanha no Morro da Sentinela, em Cerro Oeste.', 0),
(26272, 'ptBR', 'O levante dos Lançanegra', 'Fale com Voldreka no Campo de Treinamento Lançanegra.', 'A gente, os Lançanegra, sempre foi vítima. Exilado. Sempre fugindo, sempre largando nossas casas pra trás... Mas desta vez não vai ser assim. A gente não chegou aqui fugido.$B$BO Vol\'jin mostrou pra rapaziada como é que se manda com sabedoria, e isso salvou nossa pele até hoje. E, agora, essa sabedoria aí tá mostrando um futuro meio sinistro pra Horda, com esse Garrosh Grito Infernal.$B$BNão... A gente não vai fugir de novo. A gente vai é lutar pra manter esse cafofo aqui por muito tempo.$B$BTá na hora de começar o seu treinamento, $n. Fala com o Voldreka, que tá pra leste.', '', '', '', '', '', '', '', '', '', '', 0),
(26273, 'ptBR', 'O básico: como bater nas coisas', 'Destrua 6 Alvos Carrancas.', 'Beleza, vamos por partes. Antes de mais nada, preciso ter certeza de que tu tá por dentro do básico das artes sombrias.$B$BTá vendo aqueles alvos carrancas? Acaba com eles. Mas calma! Tem que ser devagar... de um jeito natural... sacou? Vai pra lá enquanto eu fico aqui de olho em como tu lança essas magias.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Voldreka no Campo de Treinamento Lançanegra, que fica nas Ilhas do Eco.', 0),
(26274, 'ptBR', 'A arte do bruxo', 'Alcance o nível 3 para aprender Corrupção. Então, pratique-a 5 vezes contra um Alvo Carranca.', 'Eu acho que é bom eu te contar uma parada.$B$BQuando tu ficar mais poderos$go:a;, tu vai começar a ouvir as vozes te dando uns toques, ensinando uns feitiços.$B$BVai lá, ganha mais experiência e volta aqui pra me mostrar o que aprender. Sacou?', '', 'Praticar Corrupção', '', '', '', '', '', '', '', 'Fale novamente com Voldreka no Campo de Treinamento Lançanegra, que fica nas Ilhas do Eco.', 0),
(26275, 'ptBR', 'O começo sempre é difícil', 'Consiga 6 Pelagens de Gato Juba Agreste.', 'Hora de pôr a teoria na prática! Vamos começar com algo bem fácil, beleza?$B$BOs gatos daqui tão matando nossos javalis. Não vai rolar de ficar dividindo comida com eles. Se a gente quer um jantar hoje à noite, temos que dar um jeito nisso.$B$BCata umas pelagens de gato pra mim. Eles tão por toda a ilha.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Voldreka no Campo de Treinamento Lançanegra, que fica nas Ilhas do Eco.', 0),
(26276, 'ptBR', 'Fosso da prova', 'Fale com o Carcereiro Lançanegra, depois entre no fosso da prova e mate um Batedor Escamas Odiosas Cativo.', 'Tu tá se saindo bem, $c. Eu ainda posso te ensinar uns truques aqui, uns macetes ali... mas chega de perder tempo em carrancas.$B$BQuero ver como cê vai se sair agora, cara. Vai lá no fosso da prova, no centro desta ilha, enfrentar um inimigo de verdade. Um que vai lutar até um de vocês dois morrer. É só falar com o carcereiro quando tu tiver $Gpronto:pronta;.', '', 'Falar com o Carcereiro Lançanegra.', '', '', '', '', '', '', '', 'Fale novamente com Voldreka no Campo de Treinamento Lançanegra, que fica nas Ilhas do Eco.', 0),
(26277, 'ptBR', 'Melhor do que o esperado', 'Apresente-se a Vol\'jin na Cidadela dos Lançanegra.', 'Tu me surpreendeu, cara. Tenho certeza de que tem coisa mais importante pra tu fazer do que ficar por aqui, $Gcercado:cercada; de calouros.$B$BDesce pro sudeste até a aldeia e se apresenta lá. É só ajudar numa coisinha aqui, noutra ali, que rapidinho tu vai tá mexendo com coisas mais... mais... menos... xumbregas.', '', '', '', '', '', '', '', '', '', '', 0),
(26278, 'ptBR', 'A defesa de Grom\'gol: o risco dos raptores', 'Destrua 12 Ovos de Batecauda.', 'Throm\'ka, $c!$b$bVocê chegou em Grom\'gol na hora certa. Nossa missão de manter uma cadeia de suprimentos segura para o Pedregal está sendo atrapalhada por alguns habitantes locais.$b$bEu estou encarregando você de acabar pessoalmente com a população de raptores do lado de fora de Grom\'gol, ao norte. Não se preocupe em matar os raptores em si, aqueles caçadores idiotas do Rosarães vão dar conta deles.$b$bEu quero que você destrua os ovos deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Aggro\'gosh no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26279, 'ptBR', 'A defesa de Grom\'gol: opressão dos ogros', 'Mate 4 Brutamontes Mosh\'Ogg e 4 Mandingueiros Mosh\'Ogg.', 'Quando nós chegamos à floresta, não tínhamos a intenção de entrar em guerra com as tribos locais. Nossa missão de suprir o Pedregal é a nossa maior prioridade, mas aconteceram complicações. Um bando de ogros locais ocuparam as Ruínas de Nizjah ao sul de Grom\'gol. Apesar dos avisos, eles continuam emboscando nossas caravanas de suprimentos.$b$bEstou te encarregando de dar um jeito nesses ogros não cooperativos.$b$bVá para as ruínas e tente expulsá-los da área. Na pior das hipóteses, mande uma mensagem bem dura.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Aggro\'gosh no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26280, 'ptBR', 'A defesa de Grom\'gol: a ameaça dos murlocs', 'Mate 15 murlocs Umbrânquia.', 'Os murlocs Umbrânquia foram expulsos do oceano pelos murlocs Escama Salgada e procuraram abrigo nas Ruínas de Kal\'ai, a nordeste daqui. No passado, isto era aceitável... Mas não mais.$b$bLonge do mar, os Umbrânquia ficaram inquietos e estão mandando os colhedores deles atacarem as minhas caravanas. Mande uma mensagem bem clara para eles: a Horda do Grito Infernal NÃO tolera este tipo de comportamento.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Aggro\'gosh no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26281, 'ptBR', 'A defesa de Grom\'gol: a ladroagem trólica', 'Recupere as Rações de Grom\'gol das Ruínas de Bal\'lal.', 'Os trolls costumam nos deixar em paz aqui em Grom\'gol. A maioria deles sabe que a Horda pode esmagá-los facilmente se for irritada, e os trolls daqui da Selva do Espinhaço não são exceção.$b$bNo entanto, os Sanguescalpo têm estado mais ativos ultimamente. Na semana passada, eles mandaram um grupo para Grom\'gol, que roubou várias caixas de ração.$b$bO roubo de comida é o tipo de roubo mais perdoável, mas, ainda assim, não posso deixar este tipo de coisa acontecer sob o meu comando. Vá para o norte, para dentro das Ruínas de Bal\'lal, e traga de volta a nossa propriedade.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Aggro\'gosh no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26283, 'ptBR', 'Visgo de primeira', 'Recolha uma Amostra da Gosma Horrenda.', 'Estou muito interessado no fato dos visgos habitarem a Rocha Oculta. Não importa quantas vezes eles sejam exterminados, eles sempre voltam, embora não me pareça que eles sejam capazes de se reproduzir a partir de um único visgo.$B$BTem alguma coisa estranha lá dentro.$B$BTodos os visgos têm uma só origem, e eu quero estudá-la. Encontre a fonte e traga uma amostra dela para mim.', '', '', '', '', '', '', 'A Gosma Horrenda', '', '', 'Fale novamente com Malcom Fendelson na Aldeia Revatusco, que fica nas Terras Agrestes.', 0),
(26284, 'ptBR', 'Desaparecidos em ação', 'Liberte 6 Demolidores Capturados das jaulas ao redor da Fortaleza Jubafria.', 'Pra dar conta de uma lida como essa, meu costume é chamar toda a tropa de demolidores. O serviço fica ajeitado mui rápido quando tem uns chirus pra dispor bem a pólvora, as cargas e tudo mais.$B$BMas aqueles troggs filhos de chocadeira engaiolaram toda a peãozada na Fortaleza Jubafria. Pois fiquei eu aqui, mais largado que sapato de troll perneta, sem um peão pra me ajudar a terminar a lida.$B$BMas tu me parece ser $Gum:uma; $c mui valente. O que tu acha de catar os meus demolidores e soltar todos eles?', '', 'Demolidores Capturados resgatados', '', '', '', '', '', '', '', 'Fale novamente com Jessé Macredo na Fortaleza Jubafria.', 0),
(26285, 'ptBR', 'Devolva minha pólvora agora!', 'Recupere 7 Barris de Pólvora Roubados dos Limpa-ossos Pedraqueixo ou Espoliadores Pedraqueixo na Fortaleza Jubafria.', 'Para explodir as cavernas, vamos precisar de muita pólvora. Até parece que os malditos troggs sabiam disso, pois os danados roubaram meu material e sequestraram meus demolidores! Mas dá na mesma.$B$BNão vou dar conta de detonar nada enquanto não devolverem minha pólvora.$B$BVá para a Fortaleza Jubafria, a sul, e mate todos os malditos troggs que cruzarem o seu caminho. Qualquer um deles pode estar carregando um dos meus barris de pólvora.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Jessé Macredo na Fortaleza Jubafria.', 0),
(26286, 'ptBR', 'Em defesa de Cerro Oeste', 'Tome as Ordens de Ataque Gnoll.', 'Quando o meu tempo de serviço em Serra Gris acabou, eu voltei para Cerro Oeste e encontrei as terras em situação pior do que quando parti.$B$BOs onerosos custos da nossa guerra resultaram em milhares de cidadãos desabrigados, que agora migram para cá, estabelecendo assentamentos em fazendas e vilas desocupadas.$B$BPara piorar tudo, estamos sendo atacados por gnolls. A Brigada de Cerro Oeste precisa de você, $n. Mate os gnolls que estão nos atacando e tome as ordens deles. Alguém os está liderando e temos que descobrir quem!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Marechal Miguel Mantoforte no Morro da Sentinela, em Cerro Oeste.', 0),
(26287, 'ptBR', 'A Brigada de Cerro Oeste', 'Mate 12 Gnolls Pata Molhada que estejam atacando o Morro da Sentinela.', 'Nós já fomos conhecidos como a Milícia do Povo. Hoje em dia, no entanto, lutamos sob a bandeira de Ventobravo, com total apoio do Rei Varian Wrynn. Temos muitas obrigações aqui em Cerro Oeste, como dar um jeito na bagunça que os Défias deixaram, expandir as fronteiras da Aliança e manter a ordem. Até agora, falhamos em todos os casos.$B$BEstamos passando por um período pior do que quando os Défias corriam por aqui com fúria homicida. E agora, como os gnolls pegaram em armas, ficamos encurralados. Ajude-nos, $n!', '', 'Gnoll Pata Molhada hostil', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Danuvin no Morro da Sentinela, em Cerro Oeste.', 0),
(26288, 'ptBR', 'Jango Pintalgas', 'Mate Jango Pintalgas, 5 Místicos Pata Molhada e 5 Capatazes Pata Molhada.', 'A sul daqui há uma área de Cerro Oeste conhecida como Planícies do Pó. Pelo que sabemos, os gnolls transformaram aquela região em capital não oficial. Como em qualquer cidade central, há um líder por trás de tudo. Se quisermos dar um fim a esses ataques, temos que encontrar o gnoll que comanda a capital e dar cabo dele.$B$BVá até as Planícies do Pó, encontre o líder dos gnolls, que é conhecido como Jango Pintalgas, e mate-o. Acabe com qualquer outro gnoll que se meter no seu caminho.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Danuvin no Morro da Sentinela, em Cerro Oeste.', 0),
(26289, 'ptBR', 'Encontre a agente Marta Hari', 'Encontre a Agente Marta Hari.', 'A AVIN está de olho no Helix Quebracâmbio desde que ele entrou no território da Aliança, há duas semanas. O Mathias Shaw me enviou uma carta avisando que destacou uma tal agente Marta Hari para seguir de perto o sujeito. Encontre a agente e você encontrará Helix Quebracâmbio.$B$BA Marta veio à cidade há dois dias, para pegar mais provisões. Ela mencionou que estaria perto da Torre do Pinel, a sudeste daqui, nas Planícies do Pó.$B$BCirculando, $n, circulando.', '', '', '', '', '', '', '', '', '', '', 0),
(26290, 'ptBR', 'Os segredos da torre', 'Entre na Torre do Pinel e encontre o Helix Quebracâmbio.', 'O Helix está entocado lá na velha torre do Filipe Pinel. Eu não vou mentir para você, $n: a torre é fortemente vigiada. Só do lado de fora são seis mercenários armados. Você não vai conseguir entrar lá $Gsozinho:sozinha; de jeito nenhum. Mas hoje é seu dia de sorte, pois eu e a Lili estamos aqui.$B$B<Marta Hari dá dois tapinhas na sua carabina.>$B$BPode deixar que eu cuido da cobertura.$B$BPegue esta poção de esconderijo, você vai precisar. Tome-a assim que entrar na torre e suba as escadas. Descubra o que o Helix está tramando lá dentro!', 'Segredo de Helix revelado', '', '', '', '', 'Segredo de Helix revelado', '', '', '', 'Fale novamente com a Agente Marta Hari nas Planícies do Pó, em Cerro Oeste.', 0),
(26291, 'ptBR', 'Problemas no Arroio da Lua', 'Relate suas descobertas para o Marechal Miguel Mantoforte no Morro da Sentinela, em Cerro Oeste.', 'Vou terminar meu relatório e partir para Ventobravo imediatamente. A AVIN precisa ser informada sobre os acontecimentos de Cerro Oeste. Sugiro que você faça o mesmo com Mantoforte. Apresente-se a ele e conte o que descobriu aqui.', '', '', '', '', '', '', '', '', '', '', 0),
(26292, 'ptBR', 'Siga para o Arroio da Lua!', 'Apresente-se ao Capitão Alberto no Arroio da Lua, em Cerro Oeste.', 'Já faz algum tempo que montamos uma base perto do Arroio da Lua, $n. Um dos meus melhores cadetes controla a área junto a uma companhia de soldados do Morro da Sentinela. Apresente-se ao capitão Alberto e descubra se ele sabe alguma coisa sobre os acontecimentos do Arroio da Lua.$B$BEu tenho outro aliado na base do Arroio da Lua. O nome dele é Thorálius, e o conheci quando servi em Valgarde. Acho que as habilidades dele nos serão úteis para resolver o mistério.', '', '', '', '', '', '', '', '', '', '', 0),
(26293, 'ptBR', 'Máquinas de guerra', 'Fale com o Encarregado Glibbs no Portão Traseiro de Orgrimmar, em Orgrimmar.', 'Indo pro leste, longe daqui, os "Quebramundo" se escondem no Planalto do Crepúsculo. Temos que dar um fim neles e vamos fazer isto com o exército mais poderoso do mundo!\nOs goblins, nossos novos aliados, estão construindo máquinas de guerra, mas ouvi dizer que têm problemas de qualidade. Não podemos guerrear com máquinas quebradas. Fale com o Encarregado Glibbs e garanta que elas estejam prontas.', '', '', '', '', '', '', '', '', '', 'Fale com o Encarregado Glibbs no Portão Traseiro de Orgrimmar, em Orgrimmar.', 0),
(26294, 'ptBR', 'Armas de disfunção em massa', 'Inspecione os Demolidores do Grito Infernal até encontrar um defeituoso, então, ensine uma lição ao Engenheiro-chefe.', '<Glibbs limpa o suor do rosto com um lenço sujo de graxa.>$B$BVol\'jin não tá satisfeito com nosso trabalho? Isso é muito ruim. Meus garotos precisam dar um gás.$B$BQuem sabe você não dá um bom exemplo? Um lote de Demolidores do Grito Infernal acabou de sair do forno e tá pronto pra inspeção. Examine bem os trecos e, se achar algum galho, dê uns sopapos no Engenheiro-chefe pra colocar ele na linha. Eles têm que lembrar que o Chefe Guerreiro está contando com eles!', '', 'Demolidor defeituoso encontrado', 'Engenheiro-chefe disciplinado', '', '', '', '', '', '', 'Fale novamente com Vol\'jin no Castelo Grommash, que fica em Orgrimmar.', 0),
(26295, 'ptBR', 'Propaganda', 'Pegue um Panfleto Informativo, um Jornal Clandestino, uma Edição da Gazeta do Arroio da Lua e uma Propaganda Misteriosa.', 'Nós notamos um aumento da violência entre os desabrigados daqui. Algo, ou alguém, está agitando eles. Agora, quem quer que esteja por trás de tudo está ficando mais organizado. Há pouco tempo, um grupo de bandidos veio até aqui para entregar panfletos.$B$BVá até o Arroio da Lua e procure por provas. Panfletos, cartazes, o que for. Traga tudo que encontrar para mim. Quem sabe a gente não descobre o líder por meio desse material?', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Capitão Alberto no Arroio da Lua, em Cerro Oeste.', 0),
(26296, 'ptBR', 'Coleta de provas', 'Pegue 6 Bandanas Vermelhas.', 'O tecido desta bandana é idêntico ao encontrado na cena do crime do assassinato dos Taturanas. Pegue mais bandanas vermelhas como prova e relate suas descobertas ao capitão Alberto.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Capitão Alberto no Arroio da Lua, em Cerro Oeste.', 0),
(26297, 'ptBR', 'O alvorecer de um novo dia', 'Traga informações da Reunião do Arroio da Lua.', 'Parece que a reunião mencionada pelo vulto sombrio vai acontecer em breve. Preciso que você participe desse encontro para levantar mais informações, $n.$B$BVá até o centro do Arroio da Lua e participe da reunião. Relate a mim tudo que descobrir.', '', 'Informações da Reunião do Arroio da Lua reunidas', '', '', '', '', '', '', '', 'Apresente-se novamente ao Capitão Alberto no Arroio da Lua, em Cerro Oeste.', 0),
(26298, 'ptBR', 'A caçada ao Yennikan', 'Junte 6 Presas de Sanguescalpo dos trolls Sanguescalpo nas Ruínas de Bal\'lal.', 'A ruína, isso sim. A ruína do filho mais novo do meu chefe, Yennikan. Como é de costume para a nossa tribo, ele foi entregue para os trolls Gurubashi de Zul\'Gurub, mas depois que a minha tribo, os Lançanegra, partiram com o orc Thrall, o pobre Yennikan se perdeu para nós. Eu fui enviado lá de Orgrimmar de volta para a Selva do Espinhaço, para procurar o filho do meu chefe.$B$BE acredito que os Sanguescalpo estão com ele. Se quiser me ajudar, vá atrás dos Sanguescalpo. Você pode encontrá-los ao norte. Junte as presas deles e me entregue.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nimboya no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26299, 'ptBR', 'Caçando cabeças', 'Colete 25 Cabeças Encolhidas dos trolls Sanguescalpo nas Ruínas Zuuldaia.', 'Nós precisamos descobrir se Yennikan está morto.$B$BMate os Sanguescalpo de Zuuldaia e pegue as cabeças encolhidas deles. Você deve juntar muitas, mas muitas cabeças mesmo! E eu vou olhá-las pra ter certeza de que a cabeça do Yennikan não é uma delas.$B$BE se o Yennikan foi morto pelos Sanguescalpo, que uma maldição de 600 anos caia sobre o espírito do chefe deles, Gan\'zulah!$B$BVá, $n. Você vai encontrar as cabeças nas Ruínas Zuuldaia, na costa ao norte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nimboya no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26300, 'ptBR', 'Nezzliok saberá', 'Pegue a Cabeça de Nezzliok, o Ríspido, em Zul\'Kanda.', 'Yennikan não estava entre as cabeças encolhidas, graças à Grande Serpente. Mas nós não estamos mais perto de encontrá-lo.$B$BNós precisamos descobrir a verdade e eu temo que só o mandingueiro dos Sanguescalpo saiba. Ele é um inimigo da tribo Lançanegra e não vai falar por vontade própria. Precisaremos arrancar a verdade dos lábios mortos dele!$b$bTraga-me a cabeça de Nezzliok, o Ríspido, e coloque-a no caldeirão.$B$BEle está nas profundezas de Zul\'Kanda. Traga a cabeça pra mim... eu farei ela falar.', '', '', '', '', '', '', 'Nezzliok, o Ríspido', '', '', 'Fale novamente com o Caldeirão Borbulhante no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26301, 'ptBR', 'Falando com Nezzliok', 'Consiga o Troféu de Balia\'mah e o Troféu de Ziata\'jai das ruínas dos Rachacrânio, que ficam na Selva do Espinhaço Setentrional.', '<A cabeça de Nezzliok fala.>$B$BÉ verdade. Eu sei para onde o filho dos Lançanegra foi levado. Você me derrotou e prendeu meu espírito, mas eu não direi nada até ser apaziguado!$B$BOs Sanguescalpo estão em guerra com os Rachacrânio. Para conseguir a minha ajuda, roube os dois crânios mais preciosos nas ruínas dos Rachacrânio na margem leste do rio. Coloque-os aqui comigo para que o meu espírito tenha escravos no Éter. Um dos crânios deve estar em Balia\'mah. O outro, em Ziata\'jai.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Caldeirão Borbulhante no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26302, 'ptBR', 'Procurando o destino de Yennikan', 'Fale com Kin\'weelay em Bambala.', '<Nezzliok fala.>$B$BVocê apaziguou a mim e ao meu chefe. Por isso, vou dizer o que você quer descobrir...$B$BO jovem Yennikan está perdido para o clã dele.$B$BEle foi levado pelo mandingueiro Zanzil, o Pária. Agora, Zanzil controla o corpo e a alma dele. Só a magia mais poderosa pode libertá-lo.$B$BMagia esta que você não possui, $c.$B$BTalvez seus aliados Lançanegra de Bambala, a leste, possam ajudá-lo a salvar Yennikan. Mas eu duvido.', '', '', '', '', '', '', '', '', '', 'Fale com Kin\'weelay em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26303, 'ptBR', 'O Olho da Mente', 'Pegue o Olho da Mente de Mai\'Zoth.', 'O Olho da Mente está nas mãos de um ogro-mago, na Gruta de Mosh\'Ogg que fica a nordeste daqui. O nome dele é Mai\'Zoth. Eu conheço ele desde a época em que os Lançanegra moravam na Selva do Espinhaço. Ele é violento e a magia dele é poderosa.$b$bAlém disso, se ele possui o Olho da Mente, então a magia dele está ainda mais forte.$b$bVocê deve enfrentar Mai\'Zoth e pegar o Olho da Mente dele. É uma tarefa perigosa, mas é a única esperança que temos de salvar Yennikan.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kin\'weelay em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26304, 'ptBR', 'A noite na selva', 'Apague 8 Braseiros de Zul\'Mamwe em Zul\'Mamwe, que fica na Selva do Espinhaço Setentrional.', 'Há um ano, a minha mãe - quer dizer, a trolesa que cuidou de mim - foi levada pelos Rachacrânio de Zul\'Mamwe. Eu era jovem e cabeça-dura e fui correndo atrás dela... Só tive tempo de vê-la sendo empurrada para um braseiro em chamas por uma dúzia de guerreiros. Eu me escondi atrás de uma árvore e assisti enquanto ele pegaram ela e... e...$b$b<Kil\'karil olha para o nada.>$b$bÀ noite, as luzes dos braseiros deles refletidas nas copas das árvores me mantém acordado. Por favor, $n... Vá para o sul, para Zul\'Mamwe, e apague esses braseiros.', '', 'Braseiros de Zul\'Mamwe apagados', '', '', '', '', '', '', '', 'Fale novamente com Kil\'karil em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26305, 'ptBR', 'Salvando Yennikan', 'Leve a Joia de Alma Plena para Nimboya.', 'Eu transformei o Olho da Mente em uma Gema Anímica. Ela tem dois propósitos. Quando você usá-la, Yennikan ficará atordoado. Quando isso acontecer, coloque a pedra na cabeça dele para que ela atraia e prenda a alma dele.$b$bAs suspeitas das quais eu falei antes estavam corretas. Os espíritos me disseram que Yennikan não está ao lado de Zanzil, o Pária, mas nas Ruínas de Zul\'Mamwe, para sudoeste. Quando você tiver libertado o espírito de Yennikan, fale com Nimboya em Grom\'gol.', '', '', '', '', '', '', 'Yennikan', '', '', 'Fale novamente com Nimboya no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26306, 'ptBR', 'Início da retomada', 'Mate 5 Mandingueiros Ramatorpe e 5 Caçadores de Cabeças Ramatorpe em Jintha\'Alor.', 'Hoje, infligiremos o primeiro golpe no coração da tribo selvagem dos Ramatorpe. Sem piedade, $n. Isso não é apenas mais uma disputa entre trolls. Cada vitória dos Revatuscos é uma vitória da Horda!$B$BOs caçadores de cabeças e os mandingueiros Ramatorpe são os primeiros da lista. Invista contra os terraços mais baixos e apresente-se a mim com sangue em suas armas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Primeva Presa-arrancada em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26307, 'ptBR', 'Morte aos Ramatorpe', 'Mate 5 Berserkers Ramatorpe e 1 Lança-sombras Ramatorpe em Jintha\'Alor.', 'Não vamos dar a eles a chance de reagir. Entre novamente em Jintha\'Alor e abra caminho até os pavimentos mais elevados.$B$BOs berserkers e os lança-sombras Ramatorpe são inimigos perigosos, $n. Quando os outros virem os corpos deles voando por cima dos muros, saberão que não estamos brincando.$B$BNão deixe nenhum coração Ramatorpe batendo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Primeva Presa-arrancada em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26308, 'ptBR', 'É nossa agora', 'Mate 5 Bebe-sangue Ramatorpe e 5 Devoradores de Almas Ramatorpe em Jintha\'Alor.', 'Agora só restam os Ramatorpe mais fortes e mais hediondos. Os devoradores de almas e os bebe-sangue, adoradores imorais do deus maligno Hakkar.$B$BTOLOS! Se agarram a crenças decadentes. Não vou mais tolerar os crimes deles contra os Revatusco.$B$BDê o golpe de misericórdia, $n. Reclame Jintha\'Alor para os Revatusco... e para a Horda!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Primeva Presa-arrancada em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26309, 'ptBR', 'Caldeirões negros', 'Recolha 5 Recipientes com Sangue Maculado em Jintha\'alor.', 'Os trolls Ramatorpe daqui bebiam o sangue conspurcado do próprio deus Hakkar em busca de poder. Eles o ferviam em caçarolas rudimentares antes de bebê-lo, caldeirões negros repletos de uma força profana.$B$BHakkar foi morto há muito tempo, claro. Mas o interessante é que... Eu ainda vejo caldeirões borbulhantes aqui. Traga-me alguns e veremos o que eles estão aprontando.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Elisa Sorrisonegro em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26310, 'ptBR', 'Tudo que rasteja', 'Recolha 8 Aranitos Espocantes em Jintha\'Alor.', 'Um momentinho, $c. Já que você vai até lá em cima... $b$bTenho alguns clientes bastante interessados em toxinas mais potentes. Não pude deixar de perceber a movimentação das aranhas por aqui... não das gigantes, das pequenas e espocantes.$B$BEssas rastejantes são de uma nuança que eu nuca havia visto nesta área. Você pode recolher algumas e trazê-las para mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Elisa Sorrisonegro em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26311, 'ptBR', 'Águas estranhas', 'Localize Herezegor Presardente na Pousada Cauda da Manticora no Vale da Honra, que fica em Orgrimmar, e obtenha o Mapa Costeiro do Planalto do Crepúsculo.', 'O Chefe Guerreiro tem planos de lançar um ataque fulminante ao Planalto do Crepúsculo. Uma vez lá, esperamos ter os orcs Presa do Dragão como aliados.$B$BMinhas fontes confirmaram que um orc Presa do Dragão vive aqui em Orgrimmar. Ele é conhecido como Herezegor Presardente e já comandou legiões de guerreiros.$B$BSeu conhecimento do assunto o torna precioso para nós. Encontre Presardente e consiga um mapa das vias náuticas do Planalto do Crepúsculo.$B$BDa última vez que soube, Presardente estava num bar no Vale da Honra...', '', '', '', '', '', '', '', '', '', 'Entregue o mapa para Sauranok, o Místico, no Castelo Grommash, que fica em Orgrimmar.', 0),
(26312, 'ptBR', 'Alívio imediato', 'Alivie a situação de Tawn Pedra Nevada, da Tempestária Mylra e de Hargoth Flamaturva, ajudando-os a derrotar os inimigos.', 'Quando o ataque começou, a gente correu pra tomar o campo o mais rápido que desse. Mas as forças deles não tinham mais fim... A gente subestimou eles. E agora, três dos xamãs mais fortes da Harmonia Telúrica tão encurralados lá, exaustos e longe do nosso apoio.$B$BDá uma chegada lá pra aliviar um pouco a barra dos nossos camaradas. Qualquer folguinha já vai ser o maior alívio pros caras.$B$BMas vê se corre, $c.', '', 'Alívio para Tawn Pedra Nevada', 'Alívio para a Tempestária Mylra', 'Alívio para Hargoth Flamaturva', '', '', '', '', '', 'Fale novamente com o Arauto da Terra Torunscar, que está a oeste do Templo da Terra.', 0),
(26313, 'ptBR', 'A raiz dos problemas', 'Consiga 6 Núcleos de Furionita.', 'Os elementais são caóticos por natureza, mesmo. Virem pra cima da gente assim, em um ataque organizado, é muito estranho. Ainda mais aqui em baixo, onde a morte deles é meio que permanente. Tô achando que isso é coisa da Therazane, a Petramáter, mas eu preciso ter certeza.$B$BDá um jeito nos estrondores de furionita e me traz os núcleos deles. Vamos ver agora mesmo se isso tudo tá vindo do ódio da Petramáter.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Reparadora da Terra Norsala, que está a oeste do Templo da Terra.', 0),
(26314, 'ptBR', 'Maior a altura, maior a queda', 'Use a Laçada de Elemêntio para derrubar 3 Serviçais de Therazane.', 'A gente tem dado mó sorte porque esses gigantes não tão acertando uma. Mas a maré vai acabar virando pra eles uma hora dessas.$B$BA gente tem que tirar eles da batalha, mas eu não acho que bater de frente seja lá muito esperto.$B$BPega esse gancho aqui, lança diretinho nas pernas dos gigantes e puxa firme. Quando eles tiverem estirados no chão, vai ser moleza acabar com eles.', '', 'Serviçais de Therazane derrubados', '', '', '', '', '', '', '', 'Fale novamente com o Arauto da Terra Torunscar, que está a oeste do Templo da Terra.', 0),
(26315, 'ptBR', 'Cachimbo da paz...', 'Leia a Proclamação da Harmonia Telúrica para Boden, o Imponente.', 'Tu já reparou num vulto de gigante que aparece lá longe no horizonte, lá pro nordeste? Pois é. É o Boden, o Imponente, um dos Senhores da Pedra da Petramáter.$B$BA gente não sabe muita coisa sobre os senhores da pedra, mas com certeza o Boden não é um cara lá muito equilibrado. É uma pena, mas parece que é ele que tá comandando o ataque, então é nele que a gente vai mirar.$B$BPega essa proclamação e lê ela em voz alta na frente dele em nome da Harmonia Telúrica. Eu sei que eu tô forçando a barra achando que umas palavrinhas vão dar um jeito nisso, mas a gente tem que tentar. Fica $Gesperto:esperta;.', '', 'Buscar a paz com Boden, o Imponente', '', '', '', '', 'Boden, o Imponente', '', '', 'Fale novamente com a Reparadora da Terra Norsala, que está a oeste do Templo da Terra.', 0),
(26316, 'ptBR', 'Cadê Jessé?', 'Encontre Jessé Macredo no acampamento da Fortaleza Jubafria.', 'O cataclismo abriu profundas cavernas sob a Fortaleza Jubafria e vários troggs foram expulsos de suas terras pelas águas. Eles conseguiram enxotar os trolls que viviam lá e vão fazer o mesmo conosco se não agirmos agora.$B$BO grão-faz-tudo Mekkatorque contratou um renomado demolidor chamado Jessé Macredo para fechar as cavernas e estancar o avanço dos troggs. Não sabemos se ele conseguiu detê-los. Você poderia procurá-lo no acampamento que ele montou perto da Fortaleza Jubafria, ao sul, depois do Aeroporto Tóxico?', '', '', '', '', '', '', '', '', '', '', 0),
(26317, 'ptBR', 'Um raptinho batecauda', 'Leve o Raptinho Batecauda para o Clarividente Mok\'thardin no Acampamento Grom\'gol.', 'Ao quebrar o último ovo, você vê um raptor recém-nascido olhando para você. Você percebe que ele está estudando você, as suas expressões e imitando seus movimentos.$b$bO raptinho batecauda acabou de formar um laço com você.$b$bA sua missão original era diminuir a população de raptores, mas você já cumpriu a sua meta de ovos quebrados e este é só um filhote inocente. Talvez alguém no Acampamento Grom\'gol saiba o que fazer com um filhote de raptor.', '', '', '', '', '', '', '', '', '', 'Fale com o Clarividente Mok\'thardin no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26318, 'ptBR', 'Ponto final', 'Vá até o fundo da caverna da Fortaleza Jubafria, mate o Chefe Brigor e ative o Detonador para explodir os túneis dos troggs.', 'Minha equipe já acabou de arrumar os barris de pólvora e o detonador no fundo da maldita caverna na parte oeste da Fortaleza Jubafria. Você só tem que descer lá no fundo e ativar o detonador para detonar a pólvora e os túneis, por assim dizer.$B$BIsso vai interromper aquela avalanche de troggs saindo do fundo da terra. Vai ser mais fácil para Mekkatorque acabar com o resto dos troggs se você conseguir dar cabo do líder dessa corja, conhecido como chefe Brigor. Boa sorte, $n.', '', 'Detonar túnel trogg', '', '', '', '', '', '', '', 'Fale novamente com Jessé Macredo no acampamento dele, que fica na Fortaleza Jubafria.', 0),
(26319, 'ptBR', 'Segredos revelados', 'Fale com Thorálius, o Sábio, no Arroio da Lua, em Cerro Oeste.', 'Há um xamã aqui, o Thorálius, que talvez possa nos ajudar. Ele é amigo do Mantoforte e recentemente veio a Cerro Oeste para estudar a devastação elemental que se abateu sobre nós.$B$BFale com o Thorálius e veja se ele pode nos ajudar a descobrir a identidade desse vulto sombrio.', '', '', '', '', '', '', '', '', '', '', 0),
(26320, 'ptBR', 'Visão do Passado', 'Entre no Esconderijo dos Défias e siga a trilha de desabrigados até a masmorra das Minas Mortas. Chegando lá, use o Incensório para ver o passado.', 'Este incenso colocará teu corpo e tua mente em um profundo estado meditativo. Assim que o transe se iniciar, tu serás $Gtransportado:transportada; para o mundo espiritual.  Não resiste ao transe, $n, permite que os espíritos revelem a ti o que sabem.$B$BAgora deves partir, $c. Vai até as Minas Mortas, um lugar que me foi dito ser de grande significância para a história de Cerro Oeste. Quando estiveres lá dentro, usa o incenso.$B$BPodes adentrar as Minas Mortas pela velha casa de fazenda a sul daqui. Em dúvida, segue os desabrigados. $B$BDepois, relata o que descobrires ao Mantoforte.', 'Visão do Passado revelada', '', '', '', '', 'Visão do Passado revelada', '', '', '', 'Fale novamente com o Marechal Miguel Mantoforte no Morro da Sentinela, em Cerro Oeste.', 0),
(26321, 'ptBR', 'Eu acho que ela está com fome', 'Mate murlocs Umbrânquia na Selva do Espinhaço Setentrional e deixe o seu Raptor Batecauda dar 40 mordidas na carne de murloc.', 'A sua raptorazinha parece faminta. Se você quiser mantê-la, procure alguma coisa para ela comer. Os batecauda costumam atacar os murlocs Umbrânquia, encontrados ao norte.$b$bEla ainda não tem força para abater um murloc sozinha, mas eu tenho certeza de que comeria carne fresca de murloc.', '', 'Mordidas na carne de murloc', '', '', '', '', '', '', '', 'Fale novamente com o Clarividente Mok\'thardin no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26322, 'ptBR', 'A ascensão da Irmandade', 'Testemunhe a ascensão da Irmandade.', 'Eu nunca poderia imaginar que o VanCleef tivesse uma filha, $n. Se havia algo em que aquele homem era excepcionalmente bom, era em guardar segredos.$B$BMas que tragédia... A coitadinha testemunhou um ato horrível. Ah, se eu soubesse disso!$B$BEspere, o que foi isso? Você ouviu alguma coisa? Parece que os gnolls estão recuando... onde estão meus guardas?$B$BEM GUARDA, $n!', 'Ascensão da Irmandade testemunhada', '', '', '', '', 'Ascensão da Irmandade testemunhada', '', '', '', 'Apresente-se ao Rei Varian Wrynn na Bastilha Ventobravo, em Ventobravo.', 0),
(26323, 'ptBR', 'O crânio favorito', 'Fale novamente com Nimboya no Acampamento Grom\'gol e mostre o novo crânio do seu Raptinho Batecauda.', 'Seu raptor de estimação encontrou um novo brinquedo: um crânio em uma pilha de crânios de trolls.$b$bVocê não consegue entender o que torna esse crânio diferente dos outros, mas, por alguma razão, ela não larga o osso.$b$bNimboya, no Acampamento Grom\'gol, é um especialista em crânios, a julgar pelas pilhas de crânios que ele guarda. Talvez ele consiga saber o que há de tão especial nesse crânio.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nimboya no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26324, 'ptBR', 'Alguém viu minha tropa?', 'Fale com o Senhor da Guerra Krogg no Porto Borraquilha, que fica em Azshara.', 'O Planalto é a terra dos orcs Presa do Dragão. Se mostrarmos nossa força, eles vão se aliar à gente contra o Martelo do Crepúsculo.\n\nA frota está se juntando no Porto Borraquilha, em Azshara, mas está atrasada.\nTu botou os goblins pra trabalhar. Vou precisar das tuas habilidades de novo.\nEncontre o Senhor da Guerra Krogg, em Azshara, e descubra por que estão demorando.', '', '', '', '', '', '', '', '', '', 'Fale com o Senhor da Guerra Krogg no Porto Borraquilha, que fica em Azshara.', 0),
(26325, 'ptBR', 'Faro para esse tipo de coisa', 'Use o seu Raptinho Batecauda para farejar 8 Fetiches de Zuuldaia.', '<A caveira fala com você.>$b$bEu estou vivo? Não, eu não estou... mas eu posso.$b$bO seu raptor foi esperto por achar o meu crânio entre tantos outros. Em vida, eu fui forte e poderoso, um senhor dos trolls. Com a sua ajuda, posso voltar a ser um senhor novamente.$b$bOs Sanguescalpo de Zuuldaia carregam fetiches mágicos que podem me ajudar a retornar. Eles escondem esses artefatos na areia. Use o seu filhote para encontrar os fetiches, $n... Depois, traga-os para cá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Caldeirão Borbulhante no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26326, 'ptBR', 'A terra onde pisamos', 'Encontre o Arauto da Terra Torunscar, que está logo a noroeste do Templo da Terra, no Deserto Dentado.', 'Só restou uma parte do Pilar do Mundo, e ela está nas mãos da Petramáter. E pior: o templo foi sitiado por elementais e gigantes. É plausível imaginar que essas criaturas estejam agindo sob o comando dela.$B$BConfronte os elementais a noroeste daqui. Tente, junto com Torunscar e Norsala, descobrir uma forma de entrar em contato com os líderes elementais e encontrar o Pilar do Mundo. É desejável que isso seja feito de forma pacífica, mas vamos fazer o que for preciso para vedar a fenda.', '', '', '', '', '', '', '', '', '', '', 0),
(26327, 'ptBR', 'Sidermar, o Herói', 'Fale com Thargas Sidermar.', 'Você não vai querer perder tempo falando comigo, $gguri:guria;. Thargas Sidermar em pessoa está do outro lado dos vagões.$B$BÉ claro que você já ouviu falar dele, não é? Ele lutou ao lado do Rei de Ventobravo para defender a Ponte Thandol dos Ferro Negro e é um dos maiores heróis de Altaforja!$B$BMas todo mundo tem o seu momento de dificuldade. Fale com ele e diga que está $Gpronto:pronta; para ajudar. Ele sempre maneja a arma como se estivesse em combate, então é melhor não chegar muito perto.', '', '', '', '', '', '', '', '', '', '', 0),
(26328, 'ptBR', 'Conversa de pedras', 'Encontre Diamant, o Paciente, na fronteira nordeste do Deserto Dentado.', '<Norsala aproxima-se do chão em uma tentativa de descobrir onde está Diamant, mas levanta-se sobressaltada após o primeiro contato.>$B$BNossa! Por essa eu não esperava. O Diamant nem tá longe. Eu procurei ele, e ele mesmo falou comigo e me disse onde é que a gente tem que procurar. Vai lá pra ponta nordeste do Deserto Dentado. O Diamant tá lá te esperando.$B$B$n, fica $Gesperto:esperta;. Não é lá muito provável que um ser da terra arme alguma cilada, mas até aí também era muito improvável que eles atacassem o templo, então...', '', '', '', '', '', '', '', '', '', '', 0),
(26329, 'ptBR', 'Só mais uma coisinha...', 'Entregue o Relatório de Jessé para o Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 'Bem, já é hora de arrumar tudo e partir para o próximo serviço. Tem sempre alguma coisa por aí esperando para ir pelos ares. Em algum recanto deste mundo, uma montanha precisa ser deslocada ou uma garganta precisa ser escavada – e eu estarei lá para botar para quebrar.$B$BSerá que você ainda aguenta me fazer um último favor? Você poderia entregar este relatório para o grão-faz-tudo Mekkatorque na Vila da Gambiarra? Ele precisa saber que os troggs não vão incomodar os gnomos tão cedo.', '', '', '', '', '', '', '', '', '', 'Entregue o Relatório de Jessé para o Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 0),
(26330, 'ptBR', 'Quem é o troll grande?', 'Pegue o Corpo do Gan\'zulah em Zul\'Kanda.', '<O crânio fala novamente.>$b$bA minha alma está pronta, mas meu corpo não. Os Sanguescalpo destruíram meu antigo corpo há muito tempo atrás. Os horrores que eles fizeram comigo... Meu espírito observou enquanto eles partiam o meu corpo em pedaços e, e... eu não consigo continuar a falar.$b$bO chefe deles, Gan\'zulah, ordenou cada um dos atos brutais. Na verdade, se a minha memória não me falha, ele era um troll forte e poderoso... Mais ou menos do mesmo tamanho que eu era. Que bela coincidência.$b$bVocê sabe o que fazer, $r. E seja $Grápido:rápida;.', '', '', '', '', '', '', 'Gan\'zulah', '', '', 'Fale novamente com o Caldeirão Borbulhante no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26331, 'ptBR', 'Os lacaios do Esmagrenagem', 'Mate 8 Lacaios do Esmagrenagem no Arsenal do Esmagrenagem. Você pode matar Técnicos Irradiados ou Trajes de Batalha do Esmagrenagem.', 'O Termaplugue, nosso antigo inimigo, está fazendo tudo que pode para atrapalhar a reconstrução e a retomada de Gnomeregan. Ele enviou um dos mais fiéis comparsas, o Razlo Esmagrenagem, e uma tropa de gnomos irradiados para acabar com a gente.$B$BOs comparsas do Esmagrenagem tomaram um velho arsenal na estrada a norte, e os técnicos estão recuperando todo o armamento que encontraram. Temos que detê-los antes que eles consigam botar aqueles mecanotanques para rodar. Vá até o Arsenal do Esmagrenagem e elimine todos os técnicos que puder.', '', 'Lacaios do Esmagrenagem mortos', '', '', '', '', '', '', '', 'Fale novamente com o Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 0),
(26332, 'ptBR', 'Mojo Rachacrânio', 'Pegue 6 Mojos de Lança Partida de trolls Lança Partida nas Ruínas Ziata\'jai e nas Ruínas de Balia\'mah.', '<O crânio fala novamente.>$b$bRecuperei meu corpo graças a você, ao seu raptor e a Gan\'zulah. Agora, se não me falha a memória, você e seu amiguinho mandingueiro vão precisar de um tanto de mojo para fazer o ritual.$b$bOs Sanguescalpo têm mojo em Zul\'Kanda, mas do tipo mais fraco. O seu mojo dos Lançanegra também não vai funcionar. Nada disso... Você tem que pegar o mojo dos trolls Lança Partida, lá do outro lado do rio, a leste daqui.$b$bCorra, $r, e eu fico de olho aqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Caldeirão Borbulhante no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26333, 'ptBR', 'Sem tanques, por favor', 'Use a Tecno-granada para destruir 5 Mecanotanques Consertados no Arsenal do Esmagrenagem.', 'Perdemos alguns batedores na tentativa de descobrir quais são os planos do Razlo Esmagrenagem para todos aqueles mecanotanques que os técnicos irradiados estão consertando.$B$BNão podemos mais nos dar ao luxo de pegar leve. Temos que tomar uma atitude antes que o Esmagrenagem mande seus asseclas e suas armas para cima de nós.$B$BEsta tecno-granada tem poder explosivo o suficiente para destruir os mecanotanques. Assim, o Esmagrenagem não poderá usá-los contra nós. Pegue a granada, siga pela estrada até o Arsenal do Esmagrenagem e acabe com aqueles tanques!', '', 'Mecanotanques Consertados destruídos', '', '', '', '', '', '', '', 'Fale novamente com Rique Splodelonj na Nova Vila da Gambiarra.', 0),
(26334, 'ptBR', 'Sangrelorde Mandokir', 'Entregue o Fragmento de Ovo de Raptor Batecauda para o Sangrelorde Mandokir no Acampamento Grom\'gol.', '$R. $R, $r, $r... Você não achou que eu seria seu amigo, achou $r? Ah, hahahahaha!$b$bVocê serviu ao seu propósito. Eu voltei para o mundo dos vivos graças a você. Por isso, em vez de matá-$glo:la;, eu proponho um acordo.$b$bMe dê o raptor.$b$bVocê já deve ter percebido que ela não é um raptor qualquer. Eu preciso de um substituto para Ohgan. Faça isso ou você e o mandingueiro sofrerão a minha ira.', '', '', '', '', '', '', '', '', '', '', 0),
(26335, 'ptBR', 'Preparando a marinha', 'Investigue o Casco do Devastador.', 'Grito Infernal espera uma frota de navios para a invasão, mas as docas estão com semanas de atraso. Os custos estão exorbitantes e a qualidade caiu. A corrupção é o problema, $n! Preciso que você investigue isso.$B$BO Devastador, um navio de guerra ancorado no píer noroeste, deveria ter sido equipado há dias. Algo não me cheira bem... Vá lá e inspecione a construção.$B$BDescubra quem está atrapalhando nossos preparativos e dê um jeito nisso!', '', '', '', '', '', '', '', '', '', 'Investigue o Casco do Devastador.', 0),
(26336, 'ptBR', 'Juanka Nabrava', 'Encontre Juanka Nabrava na Enseada de Faldir, que fica no Planalto Arathi.', 'Eu gostei de você, $n. Não é todo dia que encontro $Gum herói:uma heroína; que sabe o que está fazendo ao chegar a terras tão distantes do próprio lar. Em verdade, eu gostei tanto de você que vou te arrumar um serviço de qualidade.$B$BTenho um amigo chamado Juanka Nabrava, capitão de um grupo de piratas conhecidos por Saqueadores de Aguanegra. Pessoal bacana, mesmo sendo piratas. Eles usam a Enseada de Faldir, escondida na costa sul, como ancoradouro.$B$BTenho certeza de que Nabrava terá muito trabalho para você, se estiver interessado.', '', '', '', '', '', '', '', '', '', '', 0),
(26337, 'ptBR', 'Fique de olho', 'Rastreie um Encarregado de Borraquilha no Ancoradouro Borraquilha e dê uma prensa nele.', '<Não é impossível saber o motivo do atraso por trás do Devastador. Dia sim, dia não vem um capataz e muda o projeto.>$B$B<As mais graves são as alterações recentes. Os trabalhadores tiveram ordens de retirar rebites para cortar custos!>$B$B<É melhor você rastrear um encarregado Borraquilha responsável por isso e usá-lo como exemplo antes que vidas da Horda se percam em um navio defeituoso.>', '', 'Encarregado de Borraquilha intimidado', '', '', '', '', '', '', '', 'Fale novamente com o Senhor da Guerra Krogg no Ancoradouro Borraquilha, que fica em Azshara.', 0),
(26338, 'ptBR', 'Con-troll-e de população', 'Mate 7 Místicos Sanguescalpo, 7 Caçadores Sanguescalpo, 7 Batedores Sanguescalpo e 1 Senhor das Feras Sanguescalpo.', 'Eu sei que você deve estar indo para Zul\'Kanda em breve. Eu tenho uma pequena tarefa para você, aproveitando a sua viagem.$b$bOs trolls estão ficando mais numerosos do que a Selva do Espinhaço consegue suportar. Os Sanguescalpo a oeste, os Rachacrânio a leste... Eles saem das ruínas para a selva, perturbando o equilíbrio da região. Já é hora de nós restabelecermos esse equilíbrio.$b$bZul\'Kanda é a capital dos Sanguescalpo. Lá dentro, você encontrará os Sanguescalpo de patente mais alta. Acabe com alguns deles e depois fale novamente comigo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Clarividente Mok\'thardin no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26339, 'ptBR', 'Preparativos na Aldeia da Cevada', 'Fale com Jarvi Pisassombra na Aldeia da Cevada.', 'Enquanto eu, o grão-faz-tudo Mekkatorque e seus conselheiros militares finalizamos os planos de ataque contra Razlo Esmagrenagem, enviei um assistente à Aldeia da Cevada para começar a adiantar os preparativos.$B$BPara chegar à Aldeia da Cevada, siga pela estrada que sai da cidade, à sudeste. Ao chegar lá, procure Jarvi Pisassombra e ofereça ajuda a ele. Nossos primos anões despacharam uma unidade de montanhistas para Altaforja para reforçar nossas tropas na luta contra Esmagrenagem.', '', '', '', '', '', '', '', '', '', 'Fale com Jarvi Pisassombra na Aldeia da Cevada.', 0),
(26340, 'ptBR', 'A caçada', 'Fale com Eucunha de Clides na Expedição do Rosarães, que fica na Selva do Espinhaço Setentrional.', 'De todos os lugares de Azeroth, eu acabei preso logo aqui em Grom\'gol. Com essa vida selvagem cheia de perigos, ataques à caravana e a ameaça constante de ataques de trolls, eu até me surpreendo de ter vivido por tanto tempo.$b$bEu acho que poderia ter sido pior. Pelo menos, aqui em Grom\'gol nós temos muros e guardas. Tem um grupo de caçadores ao norte que montou acampamento no meio da selva!$b$bEu vejo pessoas indo pra lá o tempo todo. Se você estiver procurando confusão, lá é o lugar. Eu prefiro ficar aqui em Grom\'gol, com muros.', '', '', '', '', '', '', '', '', '', '', 0),
(26341, 'ptBR', 'Os estilhaços de pedra', 'Investigue os Estilhaços de Myzrael.', 'Conheço este planalto como as cicatrizes da minha perna, $n, e só existe uma coisa que eu não compreendo.$B$BA nordeste daqui, existe um círculo de pedras como os outros que você vê por Arathi... só que maior e mais majestoso, construído na própria encosta da montanha.$B$BAqui entre nós, ouvi vozes da última vez que estive lá. Sussurros vindos da terra. Se você for $Gcurioso:curiosa;, tenho certeza de que irá até lá dar uma olhada...', '', '', '', '', '', '', '', '', '', '', 0),
(26342, 'ptBR', 'Teto preto', 'Use o Lança-tinta para cegar 5 Alarmobôs do Esmagrenagem.', 'Recebemos informações confiáveis de que Razlo assumiu posição defensiva na ilha no meio das águas congeladas do Lago Nevado. Para piorar, ele se cercou de uma rede de alarmobôs que detectam qualquer tentativa de ataque.$B$BSe quisermos dar cabo do Esmagrenagem, teremos que dar pau nesses robôs. Este dispositivo lança uma tinta escura e pegajosa que vai cobrir os sensores óticos dos alarmobôs do Esmagrenagem. Isso vai paralisar o sistema de alarme avançado deles.', '', 'Alarmobôs do Esmagrenagem cegos', '', '', '', '', '', '', '', 'Fale novamente com Jarvi Pisassombra na Aldeia da Cevada.', 0),
(26343, 'ptBR', 'Oferta e demanda', 'Leve 2 Peles de Crocolisco Grande do Rio para o Drizzlik na Expedição do Rosarães.', '"O melhor coureiro dos Mares do Sul, do mundo novo e do mundo antigo". É assim que eu sou conhecido. Eu! Drizzlik! O melhor cou...Haham. Enfim.$b$bMeus produtos de couro são conhecidos em todos os cantos como os melhores, a escolha dos especialistas!$b$bEu acabei de receber uma encomenda do Diretor Riddlevox do Sindicato dos Faz-tudo para fazer uma dúzia de botas da linha Excelsior, as favoritas dele. Na verdade, são as minhas campeãs de vendas.$b$bPra começar a forma básica, eu preciso de couro de crocolisco, daqueles que ficam na margem do rio na Selva do Espinhaço Setentrional.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Drizzlik na Expedição do Rosarães, que fica na Selva do Espinhaço Setentrional.', 0),
(26344, 'ptBR', 'Algumas partes faltando', 'Leve 5 Peles de Crocolisco Arapuca para o Drizzlik na Expedição do Rosarães.', 'Bom, eu já fiz a forma básica das botas e elas estão ficando ótimas, mas as peles que você trouxe não foram suficientes para fazer toda a camada interna.$b$b"O que faremos agora, Drizzlik?" Certamente essa é a pergunta que você está se fazendo agora e, ora, não é uma sorte você estar falando com o Drizzlik? Ele te dirá exatamente o que fazer!$b$bAs camadas internas nunca são vistas e, portanto, podemos usar umas peles mais grossas e mais baratas dos crocodilos que ficam ao redor do Lago Nazferiti para complementar o forro.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Drizzlik na Expedição do Rosarães, que fica na Selva do Espinhaço Setentrional.', 0),
(26345, 'ptBR', 'Excelsior', 'Leve uma Pele de Crocolisco Ancião para o Drizzlik na Expedição do Rosarães.', 'Depois que terminamos a parte de dentro, só falta fazermos a parte de fora. Para isso, eu uso o couro dos melhores crocoliscos anciãos. Ele é mais durável e serve como uma tela melhor para podermos colocar os desenhos e formas que caracterizam a linha Excelsior do Drizzlik.$b$bÉ difícil encontrar o couro perfeito, no entanto. O único que serve para o meu projeto é o do crocolisco Arapuca ancião. Encontre-os no sul, perto da fronteira com o cabo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Drizzlik na Expedição do Rosarães, que fica na Selva do Espinhaço Setentrional.', 0),
(26346, 'ptBR', 'O conto de Myzrael', 'Fale novamente com Rodapeh na Ponta do Refúgio, que fica no Planalto Arathi.', 'A voz se cala e uma sensação de inquietude invade seu coração. Algo não está certo.$B$BTalvez você devesse contar ao Rodapeh o acontecido.', '', '', '', '', '', '', '', '', '', '', 0),
(26347, 'ptBR', 'A chama não pode apagar', 'Entregue 5 Gosmas do Abismo para o Capitão Calvino no Farol de Cerro Oeste.', 'A noite em que a família do faroleiro morreu foi terrível. Eu assisti, impotente, ao Velho Olho-turvo liderar o ataque. Mas o que está feito não se pode mudar. Agora, minha preocupação é com a vida dos marinheiros cujos navios se aproximam dos perigosos rochedos da costa. Como não há vivalma para manter a chama do farol acesa, a responsabilidade recaiu sobre mim.$b$bAjude-me a manter a chama acesa trazendo para mim um bocado de gosma do Abismo Atroz, a nordeste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Calvino no Farol de Cerro Oeste.', 0),
(26348, 'ptBR', 'Limpando a área', 'Mate 7 Murlocs Caçamarés e 7 Oráculos Murloc.', 'Você provavelmente já reparou que há vários navios naufragados ao longo da costa. O Grande Oceano é deveras traiçoeiro. Precisamos manter a costa de Cerro Oeste livre, para que os marinheiros que chegarem à praia fiquem em segurança. Os murlocs dão problema demais.$b$bMate alguns caçamarés e oráculos murlocs e eu farei com que você seja devidamente $Grecompensado:recompensada;.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Calvino no Farol de Cerro Oeste.', 0),
(26349, 'ptBR', 'O mar não está para peixe', 'Leve uma escama do Velho Olho-turvo para o Capitão Calvino no Farol de Cerro Oeste.', 'Quando eu perdi a vida nesses rochedos, não fazia ideia do que a vida após a morte reservava para mim. Naquela noite, o farol encontrava-se apagado pois o Velho Olho-turvo afugentou a família do faroleiro, porém eles retornaram posteriormente e reacenderam o facho de luz. O Velho Olho-turvo então coagiu os murlocs de mente mais fraca a invadir novamente o farol com ele. Desta feita, a família não teve tanta sorte e pereceram todos diante dos meus olhos.$b$bMate o Velho Olho-turvo caso você o veja pela praia e traga-me uma de suas escamas. Garanto-lhe que minha recompensa será generosa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Calvino no Farol de Cerro Oeste.', 0),
(26350, 'ptBR', 'Sacerdotisa Hu\'rala', 'Fale com a Sacerdotisa Hu\'rala em Bambala, que fica na Selva do Espinhaço Setentrional.', 'Obrigado, $n. Eu sei que você não precisava salvar a minha vida, e... Bem, lhe sou grato.$b$bO retorno do Sangrelorde Mandokir é uma notícia horrível. Ele foi morto em Zul\'Gurub há muitos anos atrás e nós achamos que seria o último da espécie dele. Os trolls de Zul\'Gurub estavam tentando fazer um ritual terrível e profano. Se Mandokir está vivo, é provável que ele não seja o único.$b$bOs trolls de Bambala, ao leste, devem saber mais sobre isso. Fale com a sacerdotisa deles.', '', '', '', '', '', '', '', '', '', '', 0),
(26351, 'ptBR', 'Visão da mente', 'Obtenha 5 Penas de Espreitador da Selva dos Espreitadores da Selva na Selva do Espinhaço Setentrional.', 'Para conhecer Mandokir, você precisa ver Mandokir.$b$bPara ver Mandokir, você precisa usar olhos de raptor.$b$bVocê criou um laço com um raptor: Ohgan\'aka, filha de Ohgan.$b$bPara fortalecer o laço, nós precisamos de penas.$b$bVá a oeste, e encontra penas para mim, sim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sacerdotisa Hu\'rala em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26352, 'ptBR', 'Plano do Cosella', 'Pegue a Chave do Cosella do Encarregado Cosella. Depois, pegue os Esquemas do Regulador de Combustível.', 'Eu posso ter nascido um Lançanegra, mas passei toda a minha infância aqui na Selva do Espinhaço. Já vi de tudo nesta selva, mas a coisa mais ofensiva é a devastação causada pela Empreendimentos S.A. ao leito do rio.$b$bE, pra piorar as coisas, o Encarregado Cosella e a equipe dele têm estado mais ativos do que nunca. Eu acho que eles estão planejando alguma coisa nova. Tente fazer o que eu não consegui, $n. Mate o Cosella, pegue a chave dele e roube o projeto que deve estar guardado no apartamento dele.', '', '', '', '', '', '', 'Encarregado Cosella', '', '', 'Fale novamente com Kil\'karil em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26353, 'ptBR', 'O tesouro escondido do Capitão Albernaz', 'Encontre o baú do Capitão Albernaz e procure a próxima pista dentro dele.', 'Se o campanha tá lendo isso, é porque o bom e velho Albernaz virou comida de peixe. Então o meu tesouro é seu, é só seguir os bizus. $b$bPrimeiro o campanha tem que achar o meu baú. Ele deve estar de agarra perto do naufrágio, na costa ocidental de Cerro Oeste, e já deve estar meio enterrado na areia. Tem um monte de navio a pique na costa, mas só uma âncora enferrujada. Encontre esse ferro e tá safo que vai achar o baú! O próximo bizu tá lá dentro.', '', '', '', '', '', '', '', '', '', '', 0),
(26354, 'ptBR', 'O tesouro escondido do Capitão Albernaz', 'Encontre o velho barril perto da chaminé em ruínas e procure a próxima pista dentro dele.', 'A pista do tesouro diz: "Bom trabalho, campanha! Agora levante ferro e pegue pra leste, pra riba dos penhascos, pela estrada. Fica de olho nas ruínas da chaminé do lado da estrada. O outro bizu tá ali, dentro de um barril".', '', '', '', '', '', '', '', '', '', '', 0),
(26355, 'ptBR', 'O tesouro escondido do Capitão Albernaz', 'Procure a próxima pista dentro do garrafão vazio perto do moinho de vento.', 'Ao olhar dentro do barril, você encontra outro fragmento de pergaminho. Neste, lê-se: "A partir do barril, olhe pra norte. Vai batendo perna em linha reta como o voo do corvo até encontrar um garrafão vazio perto do moinho de vento abandonado na falésia. Se o campanha fuçar dentro do garrafão, vai achar o que procura".', '', '', '', '', '', '', '', '', '', '', 0),
(26356, 'ptBR', 'O tesouro escondido do Capitão Albernaz', 'Encontre o baú do Capitão Albernaz e abra-o para receber sua recompensa.', 'Como previsto, no fundo do velho garrafão havia uma pista para o tesouro do Albernaz. O papel está cheirando a uísque e a tinta está meio borrada, mas ainda é possível entender parte da mensagem: "Agora que o campanha encontrou meu velho garrafão de uísque, o tesouro tá perto! É só olhar pra oeste, a partir do garrafão, e andar para a praia. Chegando na água, deixa de frescura, arregace as calças e vá em frente! Nade em direção ao oeste até topar com a ilha do tesouro!"', '', '', '', '', '', '', '', '', '', '', 0),
(26357, 'ptBR', 'As faces do mal', 'Use a Tocha Tiki para botar fogo em 8 Carrancas em Jintha\'Alor.', 'Os Ramatorpe penduram as carrancas deles em todas as paredes de Jintha\'Alor. Os espíritos num vão tomar conta deles por muito mais tempo.$B$BLeva esta tocha com você quando abrir caminho entre os Ramatorpe, $c. Põe fogo nas carrancas deles. Vô ficá olhando daqui pra ver os protetores e bagateiros deles desaparecendo, e o vodu negro herege deles virá fumaça.', '', 'Carrancas queimadas', '', '', '', '', '', '', '', 'Fale novamente com Kotonga em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26358, 'ptBR', 'Força aérea quase número um', 'Procure Flica em seu ferro-velho no Ancoradouro Borraquilha, que fica em Azshara.', 'Garanti para Grito Infernal que ia entregar a frota aérea dele pronta esta semana, mas nosso carro-chefe – a Lança de Durotar – ainda não tá com os motores principais instalados.$B$BFlica me prometeu um motor novinho em folha na semana passada. Vai falar com ela no ferro-velho atrás do banco e descubra qual é a do atraso.$B$BA frota aérea tá esperando, $n!', '', '', '', '', '', '', '', '', '', 'Procure Flica em seu ferro-velho no Ancoradouro Borraquilha, que fica em Azshara.', 0),
(26359, 'ptBR', 'Ver raptor', 'Fale com a Sacerdotisa Hu\'rala em Bambala, que fica na Selva do Espinhaço Setentrional.', 'Nós temos penas, sim.$b$bNós temos $go:a; $c, sim.$b$bFale com a Sacerdotisa quando tiver pront$go:a;.', '', 'Visão da Mente completada', '', '', '', '', '', '', '', 'Fale novamente com a Sacerdotisa Hu\'rala em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26360, 'ptBR', 'Controle mental', 'Pegue o Grande Cérebro de Braddok do Braddok em Zul\'Mamwe.', 'Visão da Mente não basta, não.$b$bControle Mental é feitiço muito mais forte, sim.$b$bFeitiço poderoso precisa de reagentes poderosos, e cérebro de troll é reagente poderoso.$b$bBraddok, em Zul\'Mamwe, é muito inteligente, sim.$b$bVai para o sul e dá uma olhada no grande cérebro do Braddok.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sacerdotisa Hu\'rala em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26361, 'ptBR', 'A embriaguez do sucesso', 'Encontre Makaxêra em algum lugar do Ancoradouro Borraquilha, intercepte-o e consiga a Rebimboca de Indução.', 'Foi o Capitão que insistiu que os motores novos dele tivessem uma rebimboca de indução.$B$BSó que esse troço nem foi inventado ainda!$B$BMandei Makaxêra fazer uma baseado em esquemas roubados da Empreendimentos S.A., e ele finalmente fez um bagulho que funciona!$B$BAgora que fez a rebimboca, tá se achando o rei do pedaço. Fica perambulando pela cidade como um goblin possuído com o troço na mão.$B$BDá uns sopapos nele e traz minha rebimboca, $n.', '', '', '', '', '', '', '', '', '', 'Leve a Rebimboca de Indução de volta para Flica no Ancoradouro Borraquilha, que fica em Azshara.', 0),
(26362, 'ptBR', 'Ser raptor', 'Fale com a Sacerdotisa Hu\'rala. Depois, ajude o Filhote Capturado de Batecauda a escapar de Zul\'Gurub.', 'Controle Mental muito poderoso, sim.$b$bCom sorte, ajuda Ohgan\'aka a escapar de Zul\'Gurub.$b$bDepois, Ohgan\'aka vira $n\'aka de novo!$b$bFala com a Sacerdotisa, sim, e ajuda $n\'aka fugir.', '', 'Falar com Tan\'shang', 'Ajude Tenjiyu', 'Falar com Chiyu', 'Fuja de Zul\'Gurub', '', 'Ohgan\'aka', 'De volta dos mortos?', 'Jin\'do, o Bagateiro', 'Fale novamente com a Sacerdotisa Hu\'rala em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26363, 'ptBR', 'O cúmulo do destino', 'Recolha 8 Ídolos da Aranha dos Ramatorpe no cume de Jintha\'Alor.', 'Você se saiu bem abrindo caminho entre os guerreiros, $n. Investigue o cume de Jintha\'Alor.$B$BEstávamos prontos para a batalha mais atroz. Para atacar violentamente o altar sombrio deles, mas está silencioso demais. Silêncio total. Pode ser uma armadilha terrível. Alguém com poder tem de verificar primeiro em vez de entrarmos todos de uma vez.$b$BE, se não for uma armadilha... Tenho muito interesse em descobrir o que aconteceu ali. Traga-me todas as pistas que encontrar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Primeva Presa-arrancada em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26364, 'ptBR', 'Abaixo o Esmagrenagem!', 'Derrote Razlo Esmagrenagem. Fale com o Grão-faz-tudo Mekkatorque no Lago Nevado quando você estiver $Gpronto:pronta; para a batalha.', 'Nossos primos, os anões de Altaforja, concordaram em nos ajudar na batalha contra Razlo Esmagrenagem. O montanhista Ralapedra é um veterano que conhece Dun Morogh como a palma da mão. Ele e o grão-faz-tudo Mekkatorque estão a postos em uma pequena ilha coberta de neve no Lago Nevado, a norte. Procure-os lá e fale com o Grão-faz-tudo quando você estiver $Gpronto:pronta; para encarar aquele Esmagrenagem traidor.$B$BPegue esse dispositivo de mira orbital e use-o em combate. Isso vai ajudar a guiar as armas especiais do Grão-faz-tudo.', '', 'Razlo Esmagrenagem derrotado', 'Falar com o Grão-faz-tudo Mekkatorque', '', '', '', '', '', '', 'Fale novamente com Jarvi Pisassombra na Aldeia da Cevada.', 0),
(26365, 'ptBR', 'O chamado ao heroísmo: Montanhas Cristarrubra!', 'Apresente-se ao Capitão da Guarda Florestan na Torre Vigilante, que fica nas Montanhas Cristarrubra.', 'A situação aqui é séria, mas há outras partes desta região literalmente sendo sacudidas pelo cataclismo.$B$BEu tenho aqui um relatório do capitão da guarda Florestan, das Montanhas Cristarrubra, um dos nossos territórios a leste da Floresta de Elwynn. Ele solicita o envio de algum herói para ajudá-los.$B$BMas nós já estamos sobrecarregados aqui e não temos como mandar mais tropa alguma pra lá. Você poderia se apresentar ao Florestan e ajudá-lo no que precisar? Ele fica no topo da torre em Três Caminhos.', '', '', '', '', '', '', '', '', '', '', 0),
(26366, 'ptBR', 'Fique alerta', 'Derrote Umboda Três-cabeças e recolha a cabeça dele.', 'Umboda dos Ramatorpe é um dos guerreiros mais poderosos deles, além de ser um carniceiro doentio.$B$BEle usa a cabeça de tudo que mata como bugiganga, recompensa... e até como arma! Chegou a vez dele.$B$BEncontre Umboda Três-cabeças, mate-o e traga-me a cabeça DELE! Vejamos como os Ramatorpe lutarão quando a jogarmos por cima dos muros!', '', '', '', '', '', '', 'Umboda Três-cabeças', '', '', 'Fale novamente com a Primeva Presa-arrancada em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26367, 'ptBR', 'A vingança de Ongo\'longo', 'Lute com Ongo\'longo até que ele se liberte.', 'Ongo\'longo era um dos nossos. Os forasteiros o chamavam de Troll Hediondo, mas ele era um Revatusco e um guerreiro orgulhoso como todos nós!$B$BAté que os Ramatorpe o capturaram. Eles o mantêm acorrentado em um fosso no alto de Jintha\'Alor e o botam para dançar, algo como um divertimento doentio.$B$BMas nenhuma corrente é capaz de segurar Ongo\'longo. Tudo que você tem que fazer é incitá-lo, $n. Ataque-o até que ele fique furioso o suficiente para se lembrar de sua verdadeira essência e se libertar. E, então, saia da frente!', '', 'Ongo\'longo enfurecido', '', '', '', '', 'Ongo\'longo', '', '', 'Fale novamente com a Primeva Presa-arrancada em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26368, 'ptBR', 'Segredos peçonhentos', 'Recolha 6 Amostras de Peçonha de Crias de Shadra em Jintha\'Alor.', 'Podemos conseguir mais desta peçonha curiosa se Shadra for evocada.$B$BNão fique tão $gsurpreso:surpresa;, os Renegados estudaram estas terras antes e nós encontramos a rainha peçonhenta pelo menos uma vez. As toxinas dela se mostraram úteis no passado.$B$BE mais uma vez elas provarão sua utilidade à Horda. Seja $gprestativo:prestativa; e busque todo o veneno que conseguir da cria de Shadra que espreita a caverna no cume. Bem, você ficará $Gensopado:ensopada; dele, de qualquer maneira...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Elisa Sorrisonegro em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26369, 'ptBR', 'Caça à guardiã', 'Mate Morta\'gya, a Guardiã, e pegue a Tabuleta de Shadra.', 'O Kotonga me falou de Shadra. Ela é a rainha peçonhenta, a loa das aranhas, venerada pelas trevas. Se os Ramatorpe estiverem mesmo fazendo rituais, eu não vou deixá-los prosseguir.$B$BVá até a caverna atrás do altar, no alto de Jintha\'Alor. É bem possível que uma das guardiãs de Shadra esteja lá, bem no fundo, à espreita. Mate-a e traga para cá tudo o que ela estiver carregando. Vamos ver se conseguimos descobrir o que está acontecendo.', '', '', '', '', '', '', 'Morta\'gya, a Guardiã', '', '', 'Fale novamente com a Primeva Presa-arrancada em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26370, 'ptBR', 'De volta ao Morro da Sentinela', 'Apresente-se ao Marechal Miguel Mantoforte no Morro da Sentinela, em Cerro Oeste.', 'A força da Irmandade Défias não pode ser menosprezada, $n. Você testemunhou o nascimento de uma organização criminosa implacável que fará de tudo para reduzir Ventobravo a cinzas.$B$BQuero que você volte ao Morro da Sentinela e avise ao Mantoforte que vou enviar reforços. Espero que não seja tarde demais.', '', '', '', '', '', '', '', '', '', '', 0),
(26371, 'ptBR', 'A lenda do capitão Calvino', 'Encontre o Capitão Calvino no Farol de Cerro Oeste.', 'Você já ouviu falar no capitão Calvino? Dizem que ele é apenas fruto da imaginação de um bando de marinheiros bêbados, mas qualquer um daqui de Cerro Oeste sabe que não é nada disso! Ele é o fantasma que assombra o Farol de Cerro Oeste, que fica a oeste, na Praia Grande.$B$BVocê teria coragem de investigar isso?', '', '', '', '', '', '', '', '', '', '', 0),
(26372, 'ptBR', 'A super máquina', 'Fale com o Capitão Krazz no Ancoradouro Borraquilha, que fica em Azshara.', 'Este novo motor é bem rápido. E perigoso. Eu usaria a palavra "volátil."$B$BTá do jeito que o Capitão gosta.$B$BCorre lá de volta pra colina e fale pra ele que vou instalar esta geringonça agora e que ele tem que me encontrar no local da montagem.', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Krazz no Ancoradouro Borraquilha, que fica em Azshara.', 0),
(26373, 'ptBR', 'Para Kharanos e avante!', 'Fale com o Capitão Tharran em Kharanos.', 'Alguns dos montanhistas sob o comando do Ralapedra estavam me contando sobre a situação em Kharanos. Quando os troggs tomaram a Fortaleza Jubafria, parece que os trolls sobreviventes fugiram em direção ao leste, para o coração das terras enânicas.$B$BAgora os trolls estão ameaçando Kharanos. Acho que a cidade vai precisar de toda a ajuda possível. Vá até lá e apresente-se ao Capitão Tharran. Para chegar, basta seguir pela estrada que sai da Aldeia da Cevada, em direção a leste.', '', '', '', '', '', '', '', '', '', '', 0),
(26374, 'ptBR', 'Preparando as tropas terrestres', 'Vasculhe o Ancoradouro Borraquilha e convença 12 Brutos Desertores a se apresentarem para o serviço.', 'Foi má ideia reunir as tropas nesta cidade goblin purulenta. Cada vício que o dinheiro pode comprar está ao alcance de qualquer um. Nossos poderosos veteranos estão descontando as derrotas de Nortúndria fazendo fiascos por todas a cidade.$B$BVocê pode vasculhar a cidade e reunir qualquer bruto desertor que encontrar?$B$BMeus guerreiros mordachas são inigualáveis numa batalha, mas não vou deixá-los desonrarem seus uniformes.', '', 'Bruto Desertor disciplinado', '', '', '', '', '', '', '', 'Fale com o Senhor da Guerra Krogg no Ancoradouro Borraquilha, que fica em Azshara.', 0),
(26375, 'ptBR', 'Pedras soltas', 'Use o Destruidor Delicado de Correntes para libertar 6 Pedriscos de Quartzo.', 'Os sectários do Crepúsculo estão raptando os meus pedriscos. Os malévolos drenam as energias dos pedriscos e os submetem a torturas. Extraem deles a essência que os anima.$B$BPor favor, $r, liberte meus pedriscos. Nem eu, nem Diamant temos a delicadeza necessária para quebrar as correntes que os aprisionam sem machucá-los. Mas temos uma ferramenta que pode ser útil a você.$B$BUse isto. Quebre as correntes e liberte-os.', '', 'Pedriscos de Quartzo libertados', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-quartzo próximo ao Portão de Lorthuna, no Geodomo.', 0),
(26376, 'ptBR', 'Ódio profundo', 'Mate Dragul, o Mata-gigantes, e 12 Sectários do Crepúsculo no Portão de Lorthuna.', 'Peço desculpas por Boden, mas a pedra é uma coisa teimosa...$B$BEla só muda a forma de agir com o passar do tempo.$B$BOs Senhores da Pedra, Boden e eu entre eles, estão encarregados de recuperar o Pilar do Mundo.$B$BE, quanto a isso, estamos em lados contrários.$B$BPosso exercitar minha paciência com você, $r.$B$BProve que você não é $Galiado:aliada; da Seita do Crepúsculo, nem do Asa da Morte...$B$BDespeje nosso ódio sobre eles.$B$BAtaque com ligeireza, pois nós não o podemos.$B$BTenha sucesso, e eu $Go:a; escutarei.', '', '', 'Sectários do Portão de Lorthuna mortos', '', '', '', 'Dragul, o Mata-gigantes', '', '', 'Fale novamente com Diamant, o Paciente, que está próximo ao Portão de Lorthuna, no Geodomo.', 0),
(26377, 'ptBR', 'Terreno instável', 'Recolha 6 Drusas de Cristal de Jade, junte-as e esmague-as no acampamento do Portão de Lorthuna.', 'A Seita do Crepúsculo está prospectando jade em uma mina perto do acampamento deles.$B$BTolos...$B$BNegligentes...$B$BRecolha os cristais extraídos, leve-os para o centro do acampamento e quebre-os contra o chão.$B$BA reverberação e os cristais energizados atrairão os escavadores para aquele ponto.$B$BEles vão aprender a ter mais respeito pela terra...$B$BGrão a grão...$B$BPedra a pedra...$B$B...com o tempo.', '', 'Escavador Agitado atraído', '', '', '', '', '', '', '', 'Fale novamente com Diamant, o Paciente, que está próximo ao Portão de Lorthuna, no Geodomo.', 0),
(26378, 'ptBR', 'O chamado ao heroísmo: Cerro Oeste!', 'Apresente-se ao Tenente Horatio Laine no Sítio dos Jansen, em Cerro Oeste.', 'Cerro Oeste vem passando por maus bocados, $Gmeu amigo:minha amiga;. Com o fim da ameaça dos Défias, a região se tornou um refúgio para desabrigados e oprimidos em geral. A incidência de crimes na região subiu vertiginosamente com essas pessoas lutando por abrigo e comida. E agora, estão falando em assassinato!$B$BCaso você esteja $Ginteressado:interessada; em ajudar o povo da Aliança, Cerro Oeste é um ótimo lugar para começar. Apresente-se ao tenente Horatio Laine no Sítio dos Jansen. Cerro Oeste fica exatamente a oeste da Floresta de Elwynn.', '', '', '', '', '', '', '', '', '', '', 0),
(26380, 'ptBR', 'Um pulinho em Kharanos', 'Leve as Barricas de Amostra para o Estalajadeiro Belm na Destilaria Cervaforte, que fica em Kharanos.', 'Me pediram para levar esses barris até a estalagem de Kharanos. Eles estão cheios de uma misteriosa cerveja produzida por uma cervejaria nova que fica na Aldeia da Cevada. Quando eu estava saindo da cidade, fui atacada por um grupo de trolls Jubafria. Vou levar dias para consertar a carroça!$B$BVocê por acaso não estaria $Gdisposto:disposta; a me fazer um favor, estaria? Não vou conseguir tirar esses grandes tonéis daqui de jeito nenhum, mas tenho algumas barricas menores. Você poderia levá-las até Kharanos? É só seguir a estrada que vai para sudeste.', '', '', '', '', '', '', '', '', '', '', 0),
(26381, 'ptBR', 'O olho de Shadra', 'Recupere o Olho de Shadra em Agol\'watha.', 'É preciso evocar Shadra, de fato. Seria tolice permitir que uma oportunidade destas escapasse. Apesar dos boticários serem capazes de tirar um bom proveito do veneno da deusa, eles são relativamente inexperientes com rituais mágicos.$B$BPor sorte, estou acostumado a preparar evocações malignas. Traga as partes espalhadas de Shadra para mim e eu te ajudo a trazê-la a este plano para ser eliminada.$B$BA primeira parte é o olho de Shadra, mantido em Agol\'watha, ao norte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Trevoclérigo Marnal no Acampamento de Pesquisa Hiri\'watha, que fica nas Terras Agrestes.', 0),
(26382, 'ptBR', 'Não se faz uma omelete sem...', 'Recolha 5 Ovos da Prole de Shadra em Agol\'watha.', 'Marnal tem me importunado com essa história da Shadra há dias. Estou quase aborrecida por ele ter encontrado a tabuleta de fato. Eu achava que ele fosse parar de falar sobre isso.$B$BApesar de toda aquela conversa sobre ritual mágico, ele ainda vai precisar tanto da minha ajuda quanto eu da dele. Eu preciso preparar um meio base com elementos...$B$BQuer saber? Não vou perder tempo divagando sobre detalhes. Me traz logo os ovos da prole de Shadra de Agol\'watha. Deve ter um bocado deles, vigiados pelos trolls Ramatorpe.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Boticária Gangrena no Acampamento de Pesquisa Hiri\'watha, que fica nas Terras Agrestes.', 0),
(26383, 'ptBR', 'Os ventos da mudança', 'Use a árvore teleportadora na banda oeste de Darnassus para chegar à Vila de Rut\'theran. Em seguida, fale com Vesprystus e ele $Go:a; enviará a Lor\'danel.', 'Ei, você! Você parece capaz e, quem sabe, esteja $Gdisposto:disposta; a ajudar?$B$BAuberdine caiu, por fim. Embora muitos moradores tenham partido há muito, logo que a cidade sofreu as primeiras consequências do Cataclismo, os mais teimosos recusaram-se a deixar a cidade. Agora tudo indica que a cidade foi tomada por elementais de água.$B$BMinhas irmãs precisam de ajuda para resgatar os sobreviventes. Por favor, $c, use a árvore oeste para chegar a Rut\'theran, ao chegar, fale com Vesprystus e pegue um voo para Lor\'danel. Vá depressa!', '', '', '', '', '', '', '', '', '', '', 0),
(26384, 'ptBR', 'Trevoclérigo Marnal', 'Leve a Tabuleta de Shadra para o Trevoclérigo Marnal.', 'Ainda não podemos deixar essa tabuleta de lado, $n. Podemos usá-la...$B$BVeja, eu estou um tanto impressionada com o veneno das aranhas daqui. Está claro que ele é mágico e deve ter relação com aquele deus aranha com que os trolls estão envolvidos. Se aquela tabuleta permite que alguém a evoque...$B$BBem, dá para perceber onde isso vai parar. A Horda não pode perder essa oportunidade. Leve a tabuleta aos meus companheiros Renegados. Eles estão a oeste, na estação de pesquisa das ruínas de Hiri\'watha.', '', '', '', '', '', '', '', '', '', '', 0),
(26385, 'ptBR', 'Os ventos da mudança', 'Fale com Vesprystus, na Vila de Rut\'theran, e voe para Lor\'danel.', 'Ora, já temos uma primeira empreitada para você. Viaje de volta à Vila de Rut\'theran, que foi onde primeiro pisamos nesta terra, fale com Vesprystus e pegue um voo para Lor\'danel.$B$BAo chegar, ajude os elfos noturnos em tudo que puder. Confio em você para tratá-los com a reverência de que são dignos em vista de tudo que nos fizeram.$B$BEntrementes, viajarei à distante cidade de Ventobravo para conferenciar com o Rei Varian. Espero ver seu rosto dentro em breve, $n. Até lá e que a sorte $Go:a; acompanhe.', '', '', '', '', '', '', '', '', '', '', 0),
(26386, 'ptBR', 'Surkhan', 'Fale com Surkhan em Bambala, que fica na Selva do Espinhaço Setentrional.', 'Sacerdotisa não sabe falar Órquico muito bem, não.$b$bVocê pode falar com Surkhan, lá em cima.$b$bFala pra ele o que você viu em Zul\'Gurub, sim.', '', '', '', '', '', '', '', '', '', 'Fale com Surkhan em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26387, 'ptBR', 'Dieta de fome', 'Destrua 6 Vítimas Encasuladas nas Ruínas Assustadoras.', 'As aranhas que infestam a Ruína Assustadora ao leste são inúteis. Agora, chamamos elas de prole de Shadra, e é óbvio que elas são descendentes do deus aranha, mas isso não muda o fato de que elas não valem o esforço. Eu queria mesmo era eliminar as pestinhas.$B$BQuando for à ruína assustadora, destrua todos os casulos que encontrar. Elas se alimentam dos corpos aprisionados por dias, por isso, privá-las da refeição é mais eficaz do que tentar esmagar todas elas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Boticária Gangrena no Acampamento de Pesquisa Hiri\'watha, que fica nas Terras Agrestes.', 0),
(26388, 'ptBR', 'Céu crepuscular', 'Acompanhe a frota aérea da Horda até o Planalto do Crepúsculo. Embarque no zepelim na torre que fica no Terminal Sul da Foguetovia em Azshara.', 'Beleza, todo mundo nos conformes. Espere o capitão Krazz trazer o zepelim, embarque e acompanhe a frota aérea. O almirante Punhopétreo vai estar esperando você do lado de fora do Porto Presa do Dragão!', '', 'Acompanhe a frota aérea', '', '', '', '', '', '', '', 'Fale com o Almirante Punhopétreo do lado de fora do Porto Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(26389, 'ptBR', 'Invasão dos Rocha Negra', 'Pegue 8 Armas dos Orcs Rocha Negra.', 'Os orcs estão botando fogo na floresta, $n! Eles tomaram o vinhedo a leste e estão preparando o golpe final contra nós! Temos que detê-los!$B$BVá para leste, para o outro lado do rio, e mate os orcs Rocha Negra furiosos. Tome as armas dos orcs que você matar como prova de que foram eliminados e, então, volte a mim.$B$BVocê é nossa única esperança, $n!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Major Belmonte na Abadia de Vila Norte, que fica na Floresta de Elwynn.', 0),
(26390, 'ptBR', 'Vamos acabar com a invasão!', 'Elimine Kurtok, o Matador.', 'O líder dessa horda de orcs furiosos é uma criatura selvagem conhecida como Kurtok, o Matador! Foi ele o responsável por esta invasão, e se quisermos restaurar a paz ao nosso vale, temos que matá-lo.$B$BVá novamente em direção ao leste, atravesse o rio e o vinhedo, e procure a passagem que leva para dentro das montanhas. Kurtok com certeza estará lá, preparando outro ataque. Mate-o e apresente-se novamente a mim.', '', '', '', '', '', '', 'Kurtok, o Matador', '', '', 'Fale novamente com o Major Belmonte na Abadia de Vila Norte, que fica na Floresta de Elwynn.', 0),
(26391, 'ptBR', 'A esperança é a última que queima', 'Use o Extintor de Incêndio da Madel para apagar 8 Incêndios no Vinhedo.', 'Estamos passando por tempos tão difíceis que quase sinto saudade de quando nosso único problema eram os Défias. O cataclismo abriu uma passagem para as Estepes Ardentes e agora há orcs Rocha Negra pululando por todo o Vale de Vila Norte! Eles tomaram o meu vinhedo e estão botando fogo em tudo! TUDO MESMO!$B$BPor favor, $n, aquele vinhedo é tudo o que eu tenho. Pegue meu extintor e apague o incêndio no vinhedo, por favor. Talvez ainda haja esperança para minhas terras!', '', 'Incêndio no Vinhedo extinto', '', '', '', '', '', '', '', 'Fale novamente com Madel Quintana na Abadia de Vila Norte, que fica na Floresta de Elwynn.', 0),
(26393, 'ptBR', 'Um recado rápido', 'Leve o Bilhete de Argus para Bartolotto, o Bravo, mestre de grifos.', 'Nós não obtemos muito suporte diretamente de Ventobravo, mas tenho um contato lá que nos ajuda com os suprimentos de armaduras. O nome dele é Osric Strang. A loja dele, "Imunidade Limitada", fica na Cidade Velha, em Ventobravo.$B$BNosso estoque de armaduras está no fim, e preciso contatar Osric e encomendar mais. Você pode levar esse bilhete pra ele?$B$BO jeito mais rápido de chegar em Ventobravo é falando com nosso mestre de grifos, Bartolotto, o Bravo. Ele fica em frente à forja; leve meu bilhete para ele e pegue um grifo para Ventobravo.', '', '', '', '', '', '', '', '', '', '', 0),
(26394, 'ptBR', 'Siga para Ventobravo', 'Compre uma passagem de grifo do mestre de grifos Bartolotto, o Bravo, e leve o Bilhete de Argus para Osric Strang na loja Imunidade Limitada, que fica na Cidade Velha, em Ventobravo.', 'Por uma taxa módica, você pode ir de grifo para Ventobravo e entregar o bilhete de Argus para Osric. É a maneira mais rápida de chegar lá.$B$BSe você quiser fazer negócio, fale novamente comigo quando estiver $gpronto:pronta; pra partir. Vai custar um pouco, mas acredite, vai valer a pena!', '', '', '', '', '', '', '', '', '', '', 0),
(26395, 'ptBR', 'Dungar Tragolongo', 'Leve o Caixote de Osric para Dungar Tragolongo, o mestre de grifos.', '$n, eu pus aqui nesse caixote tudo o que Argus pediu. Você pode entregar para ele?$B$BSe você já conversou com Bartolotto em Vila d\'Ouro, então você pode pegar um grifo e voltar pra lá. Dungar Tragolongo é o mestre de grifos lá no distrito comercial.$B$BFale com Dungar e leve esse caixote para Argus o mais rápido possível. Não queremos que nossos homens e mulheres lutando em Vila d\'Ouro fiquem sem equipamento.', '', '', '', '', '', '', '', '', '', '', 0),
(26396, 'ptBR', 'Fale novamente com Argus', 'Compre uma passagem para Vila d\'Ouro do mestre de grifos Dungar Tragolongo. Em seguida, leve o Caixote de Osric ao Ferreiro Argus,em Vila d\'Ouro.', 'O mestre de grifos de Vila d\'Ouro é Bartolotto. Se você já o conhece, pode ir de grifo até ele.$B$BNão se esqueça disso: os grifos são treinados para chegar à capital, mas eles só $Go:a; levarão para lugares mais remotos se você já tiver estado lá antes e falado com o tratador local.$B$BVocê já conhece Bartolotto, então é só falar comigo de novo quando quiser pegar um grifo para Vila d\'Ouro. Chegando lá, entregue o Caixote de Osric ao Ferreiro Argus.', '', '', '', '', '', '', '', '', '', '', 0),
(26397, 'ptBR', 'Tenha a Mãe Terra ao seu lado', 'Leve a Marca do Casco Sangrento para o Chefe Guerreiro, no Castelo Grommash, em Orgrimmar.$B$BFale com Tal, o Mestre de Mantícoras, para voar até lá, ou aguarde o zepelim.', 'Muita coisa mudou fora dos limites de Mulgore, $n. O mundo está destroçado e nossos aliados da Horda tomaram caminhos obscuros. Precisamos orientá-los. Mesmo nos momentos mais difíceis, vamos manter a cabeça erguida bravamente e honrar a Mãe Terra em tudo o que fizermos.$B$BVá, $n, e sirva de exemplo. Vá a Orgrimmar. Conte ao chefe guerreiro como os Temível Totem foram expulsos. Que ele saiba do nosso orgulho e disciplina, da nossa força e pesar.$B$BTal, na Torre Celeste, vai colocar você no caminho. Vá em paz e nunca esqueça o seu povo.', '', '', '', '', '', '', '', '', '', '', 0),
(26399, 'ptBR', 'O Tesouro Mosh\'Ogg', 'Pegue o Tesouro Mosh\'Ogg nas ruínas atrás da Gruta de Mosh\'Ogg.', 'Então, você já ouviu falar dos ogros? Eu recebi uma dica quente de um amigo chamado Mok\'thardin de que $gum:uma; $r idiota $gvestido:vestida; com umas roupas ridículas de $c encontrou uma mão de ogro e...$b$b<O Esquésito se perde no que estava dizendo quando repara em você>$b$bO que eu estava mesmo dizendo? Ah, sim... $gum:uma; $gHERÓI DESTEMIDO:HEROÍNA EXUBERANTE; encontrou uma mão de ogro e o Mok\'thardin tá achando que isso significa que eles têm alguma coisa de valor. Eu vi esses ogros guardando um baú numas ruínas que ficam nos fundos da caverna deles. Você consegue pegar esse baú pra mim?', '', '', '', '', '', '', '', '', '', 'Fale com Esquésito Relatrisca em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26400, 'ptBR', 'A chave mestra', 'Abra o Tesouro Mosh\'Ogg lutando com um Retalhador da Empreendimentos S.A. ou usando a Laminosserra da serraria da Empreendimentos S.A.', 'Nós vamos precisar de alguma coisa mais forte do que essas suas mãos grandes de $r para abrir essa coisa. E os palhaços da Empreendimentos S.A. que ficam a noroeste talvez tenham a ferramenta perfeita.$b$bDa última vez que eu passei por lá, vi retalhadores andando com umas lâminas rotatórias nas mãos. Assim é que se abre uma caixa!$b$bSe você não encontrar nenhum retalhador, pode tentar a laminosserra gigante que fica na serraria deles, ao lado do lago.', '', '', '', '', '', '', '', '', '', 'Fale com Esquésito Relatrisca em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26401, 'ptBR', 'Fale com Véstia', 'Leve o Amuleto Névoa Negra para Véstia Lançaluna na Torre de Estulan.', 'O brilho suave do pedestal se ilumina e você vê uma simples corrente deixada para trás. Era isso que o aprendiz procurava?', '', '', '', '', '', '', '', '', '', '', 0),
(26402, 'ptBR', 'General Shandris Plumaluna', 'Fale com Shandris Plumaluna no Domínio de Plumaluna, que fica em Feralas.', 'Nós, os druidas, não mantemos muito contato com o exército sentinela, mas sempre estamos dispostos a unir forças para defender nossa terra. Agora que você me ajudou, eu seria omisso se não pedisse que os ajudasse também.$B$BShandris Plumaluna, general das sentinelas, comanda toda a força de guerra de Kalimdor direto do recém-construído Domínio de Plumaluna, ao sul. Diga a ela que eu enviei você. Tenho certeza de que ela precisará de suas habilidades.', '', '', '', '', '', '', '', '', '', '', 0),
(26403, 'ptBR', 'Mineração da Empreendimentos S.A.', 'Leve 5 Cristais Rolados para o Esquésito Relatrisca em Bambala, que fica na Selva do Espinhaço Setentrional.', 'Cara, eu odeio a Empreendimentos S.A. Eles têm uma cadeia de operações na Selva do Espinhaço que impede goblins trabalhadores como eu de ganhar um dinheiro honesto!$B$BSabe como eu chamo isso? Roubo. Os geólogos da Empreendimentos S.A., próximos ao Lago Nazferiti, a noroeste daqui, estão extremamente interessados naqueles cristais azuis estranhos que eles andam encontrando nas minas. Pegue algumas amostras do cristal com os geólogos. Eu não me importo com o que você vai ter que fazer pra conseguir.', '', '', '', '', '', '', '', '', '', 'Fale com Esquésito Relatrisca em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26404, 'ptBR', 'Acima do meu salário', 'Fale com a Espoleta Chaveforte no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 'Ei, você já foi ao Esconderijo da Chaveforte? Nossa, você PRECISA ver aquele lugar. É o sonho de qualquer goblin.$b$bÉ o seguinte... Você parece $gum:uma; $c decente. Raskha, a de colete e saia aqui ao lado, pode te dar uma carona pra lá, se você não conhecer o caminho.$b$bO voo é por minha conta.', '', '', '', '', '', '', '', '', '', '', 0),
(26405, 'ptBR', 'Mambo Zul\'Mamwe', 'Mate 16 Trolls Rachacrânio em Zul\'Mamwe.', 'Os Rachacrânio são uma vergonha pro império dos trolls. A briguinha deles com os Sanguescalpo dividiu a Selva do Espinhaço Setentrional ao meio. Enquanto as tribos Lançanegra e Zandalari tão prosperando, os Rachacrânio ficam aí lutando por causa de umas ruínas.$b$bEu tenho autorização pra dar uma recompensa pros mercenários que tiverem a fim de dar uma lição nos Rachacrânio. Então, se você tiver dispost$go:a;, vai pro sul com todo mundo que você conhecer e dá uma boa sova nesses caras.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Surkhan em Bambala, que fica na Selva do Espinhaço Setentrional.', 0),
(26406, 'ptBR', 'A presa de Shadra', 'Pegue a Presa de Shadra na Ruína Assustadora.', 'Agora, precisamos da presa de Shadra.$B$BEla está na Ruína Assustadora, a leste, e é guardada pela própria prole de Shadra. O veneno delas é poderoso, $n... não se descuide.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Trevoclérigo Marnal na Estação de Pesquisa Hiri\'watha.', 0),
(26407, 'ptBR', 'Manufatura de Mosh\'Ogg', 'Leve a Mão Desfigurada de Mosh´´Ogg para o Clarividente Mok\'thardin no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 'Este ogro estava usando um item incomum: a mão cortada de outro ogro, amarrada por um pedaço de barbante e pendurada no pescoço. A mão é marcada por várias cicatrizes que emitem uma luz roxa suave.$b$bCicatrizes que brilham depois da morte são bem incomuns, e achar um item destes com um ogro é mais incomum ainda. Talvez alguém em Grom\'gol saiba o que fazer com esta bizarrice.', '', '', '', '', '', '', '', '', '', 'Leve a Mão Desfigurada de Mosh´´Ogg para o Clarividente Mok\'thardin no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26408, 'ptBR', 'As cinzas do Vale Gris', 'Fale com a Sentinela Shyela no Retiro de Orendil, que fica no Vale Gris.', 'A Costa Negra pode ter sido desolada e devastada, mas, graças a você, conseguimos nos manter minimamente seguros aqui - e com um pouco de paz. Ainda há muito a ser reconstruído.$B$BProssiga em sua jornada, $Gmeu amigo:minha amiga;. O Vale Gris verga-se ante o ataque maciço da Horda sob o comando de Garrosh. Seus machados derrubarão a nós todos e às árvores da floresta se não reagirmos.$B$BSe não quisermos perder as florestas por completo, $n, vamos precisar de sua ajuda. Siga a estrada para o sul e encontre a sentinela Shyela.', '', '', '', '', '', '', '', '', '', '', 0),
(26409, 'ptBR', 'Cadê o Almada?', 'Encontre o Iniciado Almada na Bacia de Quartzito, no Geodomo.', 'O meu pupilo não dá notícias há algum tempo. Ele é um goblin chamado Almada.$B$BEu o enviei para observar os esfola-pedras a sudoeste daqui, na Bacia de Quartzito. Tu poderias procurá-lo? Quando o encontrar, por favor, peça-lhe que volte para o templo.', '', '', '', '', '', '', '', '', '', '', 0),
(26410, 'ptBR', 'Super cola explosiva', 'Colete 5 Resinas de Quartzito.', 'Esse cara aqui é o filho do líder dos Terrenos. Faltou pouco pra ele escapar de um bando de esfola-pedras que pegou ele de jeito numa emboscada...$B$BA rapaziada toda sabe que o Petrarca Terreno malocou o fragmento do meio do Pilar do Mundo. Quem sabe se a gente curar o filho dele, ele não entrega o bendito pedaço?$B$BAs minhas curas não vão funcionar com o Sílex. Mas se a gente arrancar um pouco da resina de quartzito desses monstros, acho que eu dou um jeito de fazer uma mistura explosiva que vai colar e cauterizar os ferimentos dele.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Iniciado Almada na Bacia de Quartzito, que fica no Geodomo.', 0),
(26411, 'ptBR', 'Maravilha cura-ativa', 'Use o Emplastro Colante Explosivo em Sílex Rochamanto.', 'Beleza, pega isso e passa nos machucados dele. Se o efeito cauterizador da explosão secativa não arrebentar ele em dois, isso vai curar tudo direitinho.$B$BEu acho.', '', 'Emplastro Colante Explosivo aplicado', '', '', '', '', '', '', '', 'Fale com o Iniciado Almada na Bacia de Quartzito, que fica no Geodomo.', 0),
(26413, 'ptBR', 'Tem coisas que só o Arauto da Terra faz por você', 'Apresente Sílex Rochamanto para o Arauto da Terra Yevaa no Templo da Terra.', 'Ele ainda tá meio esquisito. Acho que a cabeça dele ainda tá rodando.$B$BÉ melhor levar o cara pra dentro do templo e ver o que o Arauto da Terra quer fazer com ele.$B$BEu acho que vou ficar aqui fora mais um pouquinho "observando" esses esfola-pedras.', '', 'Sílex Rochamanto apresentado para o Arauto da Terra Yevaa', '', '', '', '', '', '', '', 'Apresente Sílex Rochamanto para o Arauto da Terra Yevaa no Templo da Terra, que fica no Geodomo.', 0),
(26414, 'ptBR', 'Pega-te olhete', 'Catarina Gurjão, de Ventobravo, quer que você lhe traga 8 Olhetes do Lago.', 'Algumas vezes, eu pesco por diversão. Outras, para relaxar. Mas tem vezes que estou a fim de um desafio. E aí entra em cena o olhete. Esse peixe é uma presa muito valorizada não pelo sabor da carne, mas pelo desafio da pesca. O Lago de Ventobravo, a norte da cidade, está cheio deles. Você acha que está à altura do desafio?', '', '', '', '', '', '', '', '', '', 'Leve os peixes para Catarina Gurjão em Ventobravo.', 0),
(26415, 'ptBR', 'Indicador da missão Diário de Bordo', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(26416, 'ptBR', 'Conheça a lei da selva', 'Apresente-se a Bort em Orgrimmar.', 'Meu comandante me enviou para procurar recrutas em potencial para defender o Acampamento Grom\'gol na Selva do Espinhaço Setentrional. Você conhece a Selva do Espinhaço? É muito longe daqui, do outro lado do Grande Oceano, no sul dos Reinos do Leste. Você parece se encaixar no perfil que meu comandante me mandou procurar... Estaria interessad$go:a; em sair de Kalimdor por uns tempos?$b$bSe for o caso, fale com o meu colega Bort, em Orgrimmar. Ele vai te ajudar a entrar no zepelim.$b$bE diga pra ele que eu mandei o seguinte recado: "Woozle woozle". Ele vai entender.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Bort em Orgrimmar.', 0),
(26417, 'ptBR', 'Selva do Espinhaço Setentrional: o Império Caído', 'Apresente-se ao Comandante Aggro\'gosh no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 'O comandante Aggro\'gosh está procurando membros dedicados da Horda para que o ajudem na missão em Grom\'gol. Se você estiver interessad$go:a;, basta ir ao topo da torre do zepelim e subir a bordo do zepelim para Grom\'gol. É fácil assim!$b$bFalando sério, o Espinhaço é o lugar para se estar neste momento... bastante ação e muito menos dano cataclísmico do que há, por exemplo, na Cordilheira das Torres de Pedra. Eu gostaria de poder ir com você.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Comandante Aggro\'gosh no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 0),
(26418, 'ptBR', 'A carapaça de Shadra', 'Mate Qiaga, a Tutora, e pegue a Carapaça de Shadra.', 'Só falta conseguir uma última peça para termos tudo o que precisamos.$B$BA carapaça está com a última alta-sacerdotisa viva do deus aranha, Qiaga, a Tutora. Ela fica no topo do Altar de Zul, guardada pelos outros zelotes fanáticos.$B$BBem fácil, não é? Suba os degraus do altar e mande a cabeça dela rolando pela escadaria. Me traga a carapaça e finalmente pegaremos Shadra.', '', '', '', '', '', '', 'Qiaga, a Tutora', '', '', 'Fale novamente com o Trevoclérigo Marnal na Estação de Pesquisa Hiri\'watha, que fica nas Terras Agrestes.', 0),
(26419, 'ptBR', 'Shadra, a Rainha Peçonhenta', 'Mate Shadra, a Rainha Peçonhenta.', '<O chão treme quando o ídolo é posto no altar e o lago abaixo turva! Shadra está emergindo!>', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Trevoclérigo Marnal na Acampamento de Pesquisa Hiri\'watha, que fica nas Terras Agrestes.', 0),
(26420, 'ptBR', 'Minhocas por cristais', 'Encontre uma Minhoca Hipertrofiada nas margens do Lago de Olívia e use-a como isca para pescar uma Perca-cristal no mesmo lago, a norte de Ventobravo.', 'Olá, olá, $Gpescador:pescadora;! O Arnoldo me contou que você estava procurando um pesqueiro novo e acho que conheço o lugar perfeito. A norte de Ventobravo, existe um lugarzinho muito interessante chamado Lago de Olívia.$b$bO lago fica cheio de percas-cristal a cada temporada, mas são peixes muito difíceis de pegar. Eles só mordem um tipo muito específico de isca... Só minhocas hipertrofiadas. Se você cavucar as margens do lago, tenho certeza de que vai encontrar as minhocas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Catarina Gurjão em Ventobravo.', 0),
(26421, 'ptBR', 'Conheça o Grão-faz-tudo', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 'Não sei se você se lembra do Mekkatorque. Nevin me contou que perda de memória é muito comum entre os sobreviventes de Gnomeregan.$B$BMekkatorque, ou melhor, o grão-faz-tudo Mekkatorque é o líder dos gnomos. Ele criou o hábito de encontrar cada sobrevivente em pessoa. Você deveria se apresentar a ele. Ele está reunido com o conselho de guerra sob a tenda no centro da cidade.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 0),
(26422, 'ptBR', 'Conheça o Grão-faz-tudo', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 'Não sei se você se lembra do Mekkatorque. Nevin me contou que perda de memória é muito comum entre os sobreviventes de Gnomeregan.$B$BMekkatorque, ou melhor, o grão-faz-tudo Mekkatorque é o líder dos gnomos. Ele criou o hábito de encontrar cada sobrevivente em pessoa. Você deveria se apresentar a ele. Ele está reunido com o conselho de guerra sob a tenda no centro da cidade.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 0),
(26423, 'ptBR', 'Conheça o Grão-faz-tudo', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 'Não sei se você se lembra do Mekkatorque. Nevin me contou que perda de memória é muito comum entre os sobreviventes de Gnomeregan.$B$BMekkatorque, ou melhor, o grão-faz-tudo Mekkatorque é o líder dos gnomos. Ele criou o hábito de encontrar cada sobrevivente em pessoa. Você deveria se apresentar a ele. Ele está reunido com o conselho de guerra sob a tenda no centro da cidade.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 0),
(26424, 'ptBR', 'Conheça o Grão-faz-tudo', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 'Não sei se você se lembra do Mekkatorque. Nevin me contou que perda de memória é muito comum entre os sobreviventes de Gnomeregan.$B$BMekkatorque, ou melhor, o grão-faz-tudo Mekkatorque é o líder dos gnomos. Ele criou o hábito de encontrar cada sobrevivente em pessoa. Você deveria se apresentar a ele. Ele está reunido com o conselho de guerra sob a tenda no centro da cidade.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 0),
(26425, 'ptBR', 'Conheça o Grão-faz-tudo', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 'Não sei se você se lembra do Mekkatorque. Nevin me contou que perda de memória é muito comum entre os sobreviventes de Gnomeregan.$B$BMekkatorque, ou melhor, o grão-faz-tudo Mekkatorque é o líder dos gnomos. Ele criou o hábito de encontrar cada sobrevivente em pessoa. Você deveria se apresentar a ele. Ele está reunido com o conselho de guerra sob a tenda no centro da cidade.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Grão-faz-tudo Mekkatorque na Vila da Gambiarra.', 0),
(26426, 'ptBR', 'Tempestade violenta', 'Encontre Felsen, o Perene, e siga as instruções dele para chegar à entrada dos Abismos Esfacelados.', 'Tenho uma tarefa para você.$B$BUma tarefa perigosa. Se você conseguir cumpri-la, até o mais reticente dos Senhores da Pedra ficará bem impressionado.$B$BA oeste daqui fica a Borda Limpa. Aquela região é açoitada por fortes ventos que desviam a atenção do verdadeiro perigo do lugar, no subterrâneo.$B$BOs litovermes vivem no interior da Borda Limpa. Eles devoram as pedras e se movem por elas como se nadassem. E fazem o mesmo em nossas peles rochosas.$B$BEncontre Felsen, o Perene. Peça que ele $Go:a; encaminhe para os Abismos Esfacelados. Assim que você chegar lá, nos falaremos novamente.', '', 'Encontre Felsen, o Perene', 'Encontre a entrada dos Abismos Esfacelados', '', '', '', '', '', '', 'Encontre a entrada dos Abismos Esfacelados.', 0),
(26427, 'ptBR', 'Sem capitão nem tripulação', 'Entregue uma Garrafa de Uísque e um Carretel de Corda para o Primeiro Oficial Taciturno.', 'Hum, não sei para quem você trabalha, mas você não me parece ser um... deles.$B$BNão entendi muito bem o que aconteceu. Eu fui dormir antes da ceia e acordei com um navio cheio de gente morta e assassinos.$B$BNão sei se você quer me matar, mas vou lhe poupar o trabalho.$B$B<Taciturno aponta para um ferimento no estômago. As tripas não estão onde deveriam estar.>$B$BEu consigo continuar pilotando o navio por mais algum tempo. Não se morre de um ferimento na barriga imediatamente. Basta me trazer um carretel de corda e um pouco de rum... Não, uísque.', '', '', '', '', '', '', '', '', '', '', 0),
(26428, 'ptBR', 'Cortem as cabeças!', 'Pegue as cabeças de Kenata Dabyrie, Fardel Dabyrie e Marcel Dabyrie.', 'Aquela meretriz! Aquela vaca! Kenata está viva e a família dela prosperando enquanto eu sofro aqui. Renegada de fato!$B$BPerdi minha família para a peste. Meu terreno foi pilhado e queimado durante a guerra. E ainda assim, ela e os filhos tiveram a audácia de roubar meus últimos bens restantes.$B$BNão me importo mais com o que me foi tirado. Quero as cabeças deles!$B$BMate-os por mim! Vá até a Fazenda dos Dabyrie em Arathi, a nordeste de Ponta do Refúgio.', '', '', '', '', '', '', 'Kenata Dabyrie', '', '', 'Fale novamente com Geneva Celara na Ruína de Galen, que fica no Planalto Arathi.', 0),
(26429, 'ptBR', 'Acabe com os Cascasseca', 'Mate 10 Arremessadores Cascasseca, 10 Caçadores de Cabeças Cascasseca e 8 Mandingueiros Cascasseca.', 'Os trolls Cascasseca e os ogros Punho de Pedra de Arathi se uniram, na tentativa de nos aniquilar. Mas não irão conseguir, nem eles, nem ninguém. Vamos trucidá-los e mostrar a todos que nós também fazemos daqui nosso lar.$B$BOs trolls nos ignoraram, e os ogros iriam se fartar de nossa carne e se vestir com nossa pele se deixássemos. E acredite, não iremos deixar nada disso acontecer. $B$BNosso primeiro ataque será contra a tribo Cascasseca ao sul daqui. Mate dezenas deles, e só volte quando o acampamento deles feder a sangue.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Drum Fel na Ruína do Martelo, que fica no Planalto Arathi.', 0),
(26430, 'ptBR', 'Aldeia Revatusco', 'Viaje até a Aldeia Revatusco nas Terras Agrestes e fale com o Ancião Presa-arrancada.', 'Nem todos os trolls da floresta são problemas como os Cascasseca. Nas Terras Agrestes ao norte daqui fica a Aldeia Revatusco, lar da única tribo de trolls da floresta aliada à Horda.$B$BMas nem mesmo eles escapam da crueldade dos seus irmãos. A tribo Ramatorpe os ataca, distraindo-os da nossa guerra contra a Aliança.$B$BVocê já fez muito por aqui, $n. Fale com Urda se quiser voar para Revatusco. A aldeia precisa da sua força.', '', '', '', '', '', '', '', '', '', '', 0),
(26432, 'ptBR', 'A queda de Jintha\'Alor', 'Encontre a Primeva Presa-arrancada em Jintha\'Alor, que fica nas Terras Agrestes.', 'A gente não tem só anões no nosso sapato, cara. Enquanto eu vigio a vila, minha companheira, Primeva Presa-arrancada, foi liderar os guerreiros contra a tribo perversa dos Ramatorpe.$B$BEles mataram nossos irmãos e até me fizeram prisioneiro uma vez. Chega! Desta vez, a cidade de Jintha\'Alor vai cair.$B$BVai até Jintha\'Alor e fala com a minha companheira. Ela capturou um acampamento perto da entrada da cidade.', '', '', '', '', '', '', '', '', '', '', 0),
(26433, 'ptBR', 'A água benta da limpidez', 'Consiga a Água Benta da Limpidez do Olho-d\'água Nek\'mani no Cabo do Espinhaço.', 'Ok, vamos começar a trabalhar para identificar essa... essa coisa que você tem aqui.$b$bPra começar, eu vou precisar de um pouco de água benta da limpidez. As nagas a sudeste daqui guardam uma fonte que tem uma água tão limpa, tão fresca e tão pura que aqueles que beberem um gole da coisa têm sua mente limpa e a melhor decisão revelada.$b$bParece interessante, né?$b$bConsiga um pouco dela no Olho-d\'água Nek\'mani, que fica no topo do acampamento naga. Boa sorte!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Flem Gizzix no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26434, 'ptBR', 'Reagentes primevos do poder', 'Obtenha 4 Peles Flexíveis de Tigresa e 4 Peles de Pantera Aveludadas.', 'Agora eu entendo claramente... A chave para identificar esse talismã misterioso está em obter alguns itens raros e preciosos. Esses reagentes primevos do poder, quando combinados da maneira certa, poderão nos revelar a origem desse tesouro.$b$bViaje para o norte, para o lado oeste da Arena de Gurubashi, e cace os felinos que rondam a selva. As peles aveludadas deles nos levarão até a verdade!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Flem Gizzix no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26435, 'ptBR', 'Eu sou um grande mentiroso e uma fraude', 'Leve o Tesouro Mosh\'Ogg Aberto para Garley Montaluz na Angra do Butim, que fica no Cabo do Espinhaço.', 'Eu não faço ideia do que seja esse artefato. Eu não sei nem por onde COMEÇAR a pesquisar o que ele é.$b$bNa verdade, eu não sei nem o motivo de alguém achar que EU poderia identificá-lo, pra começar.$b$bEu pedi a água porque estava com sede. Eu pedi as joias e as peles para... Bem, são presentes para a minha namorada.$b$bAo menos eu posso te colocar no caminho certo. Garley Montaluz, na Angra do Butim, é membro do Relicário e talvez te ajude mais do que eu.$b$bDesculpe.', '', '', '', '', '', '', '', '', '', '', 0),
(26436, 'ptBR', 'O entrincheirado', 'Procure Kor, o Inamovível, em meio às Agulhas Tremulantes, no Geodomo.', 'Suas intenções me parecem verdadeiras.$B$BDeixarei claro para os Senhores da Pedra que estou começando a confiar em você.$B$BE, mais importante: eles ouvirão.$B$BLeva-se tempo para cair nas graças deles. Mais ainda para ganhar a confiança da Petramáter. O tempo é uma dádiva poderosa, então seja $Ggeneroso:generosa; com ele.$B$BEntre as longínquas Agulhas Tremulantes, a noroeste, está Kor, o Inamovível. Ele é bastante equilibrado. Além disso, a situação dele torna mais provável que aceite ajuda externa.$B$BProcure-o.', '', '', '', '', '', '', '', '', '', '', 0),
(26437, 'ptBR', 'Deixando tudo claro como cristal', 'Recolha 8 Formações de Cristal Calcário.', 'Por entre as Agulhas Tremulantes há cristais. Gemas calcárias, brancas. Nós absorvemos esses cristais pela pele. Para nos limpar. Para nos purificar.$B$BEu não mais vago pelas rochas. Estou unido à terra. Isso me traz inúmeras bênçãos, mas não me deixa recolher os cristais por mim mesmo.$B$BTraga-me os cristais para que eu me fortaleça. Leve-os para longe dos esfoladores. Para longe de meus filhos. Esta honra é minha.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kor, o Inamovível, em meio às Agulhas Tremulantes, no Geodomo.', 0),
(26438, 'ptBR', 'Intervenção', 'Mate 12 Esfola-pedras Pontajaspe.', 'Os esfoladores ficaram enlouquecidos de fome. As escavações deles já foram um dia moderadas. Agora nada sacia o apetite deles. Eles se tornaram mortalmente violentos.$B$BOs esfoladores se voltaram contra meus filhos. Eles os dominam. Eles os matam. Isso tem que acabar!$B$BMate os esfoladores. Eles não têm função nesta terra. O fim deles não será lamentado. Salve meus filhos. Mate todos os esfoladores que encontrar.', '', 'Esfola-pedras mortos', '', '', '', '', '', '', '', 'Fale novamente com Kor, o Inamovível, nas Agulhas Tremulantes, que ficam no Geodomo.', 0),
(26439, 'ptBR', 'Juntando os pedaços', 'Ajude a reabilitar 6 Elementais Rochosos Inativos.', '$R, se você está servindo aos Senhores da Pedra, então poderá receber alguma ajuda.$B$BProcure os rochosos inativos que estão espalhados pelas Agulhas Tremulantes. Não será difícil reabilitá-los para lutar contra os esfoladores.', '', 'Elementais Rochosos reabilitados', '', '', '', '', '', '', '', 'Fale novamente com Berracit que está entre as Agulhas Tremulantes, no Geodomo.', 0),
(26440, 'ptBR', 'Tu te tornas eternamente responsável...', 'Leve o Cascalho até a grande formação de cristais nas Agulhas Tremulantes.', '<Um minúsculo elemental parece ter se afeiçoado a você.>$B$BCastri... cris... cristal? <Cascalho olha para você com olhar ansioso.>$B$B<Você notou uma grande formação de cristal no meio das Agulhas Tremulantes. Será que você deveria levar o elemental até lá?>', '', 'Cascalho levado à formação de cristal', '', '', '', '', '', '', '', 'Fale com o Cascalho. A última vez que você o viu foi nas Agulhas Tremulantes.', 0),
(26441, 'ptBR', 'Tão bonitinho...', 'Fale com Kor para descobrir de que tipo de comida o Cascalho gosta.', '<Cascalho olha em volta, animado com alguma coisa. Após alguns segundos de confusão, ele para e se vira para você com os olhos de joia, grandes e brilhantes.>$B$BOme... Fome...$B$B<Por mais que você tente, não há como resistir àquele olhar. Será que o Kor sabe o que os minimentais gostam de comer?>', '', '', '', '', '', '', '', '', '', '', 0),
(26442, 'ptBR', 'Lagosta das Rochas', 'Colete 6 Lagostas das Rochas das armadilhas embaixo do píer do Porto de Ventobravo. Cuidado com os tubarões!', 'Se me fosse dado escolher minha última refeição, com certeza eu pediria lagostas frescas. Tem alguma coisa nesse crustáceo maravilhoso que é simplesmente irresistível! Faz pouco tempo que começamos a pegar lagostas aqui em Ventobravo. Você poderia verificar as armadilhas para mim?$b$bMais uma coisa: cuidado com os tubarões. Eles podem ser muito traiçoeiros lá embaixo.', '', '', '', '', '', '', '', '', '', 'Entregue as lagostas para Catarina Gurjão em Ventobravo.', 0),
(26443, 'ptBR', 'Planos diabólicos', 'Entregue os Planos Diabólicos para o Vindicante Vedaar no Acampamento de Lenhadores Brado Guerreiro, que fica no Vale Gris.', 'Um demônio deixou este pergaminho cair, e o texto, surpreendentemente, está escrito na Língua Comum! Diathorus e Gorgannon, os dois nomes mencionados no pergaminho, são os infames senhores do medo que controlam a área dos demônios.$B$BOs planos detalham os preparativos para um ataque demoníaco a Cantilenda, ao norte, onde um novo assentamento draeneico vem sendo erguido.$B$BSerá que o vindicante Vedaar, no Acampamento de Lenhadores Brado Guerreiro, se interessaria por estes planos?', '', '', '', '', '', '', '', '', '', '', 0),
(26444, 'ptBR', 'Destrua a Legião', 'Mate 15 demônios de qualquer tipo no Monte Fogovil, no Cânion do Demônio Caído e na Serra do Demônio Caído.', 'Não tolerarei a presença deles neste mundo! A Legião Ardente quase destruiu nossa raça, nos obrigando a fugir e fundar um novo lar, em um novo mundo. Depois, os demônios voltaram e nós recuamos novamente, vez após vez.$B$BChega!$B$BHá remanescentes da Legião a sul e oeste daqui, no Monte Fogovil, no Cânion do Demônio Caído e na Serra do Demônio Caído. Eles são o que restou de uma tropa que invadiu este mundo há muito tempo.$B$BVai até lá e mata quantos puder antes que seja tarde demais!', '', 'Demônios mortos', '', '', '', '', '', '', '', 'Fale novamente com o Vindicante Vedaar no Acampamento de Lenhadores Brado Guerreiro, que fica no Vale Gris.', 0),
(26445, 'ptBR', 'Basta!', 'Consiga a Espada Flamejante de Gorgannon e a Lança Maligna do Inquisidor.', '$n, cabe a ti cuidar para que o ataque da Legião Ardente não se concretize. Mata os líderes dos demônios. Sem liderança, eles ficarão desorientados.$B$BGorgannon está no Cânion do Demônio Caído, a sul do Monte Fogovil, perto do local onde paira a lança partida de Mannoroth.$B$BDiathorus, o Inquisidor, está em algum lugar do covil no alto da Serra do Demônio Caído. Para chegar lá, procura uma rampa a partir do Cânion do Demônio Caído, próxima ao monumento da Horda a Grom Grito Infernal.$B$BTraze-me as armas deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Vindicante Vedaar no Acampamento de Lenhadores Brado Guerreiro, que fica no Vale Gris.', 0),
(26446, 'ptBR', 'A retomada do Monte Fogovil', 'Plante 8 Mudas de Árvore em Monturos de Terra Fértil.', '$GPequenino:Pequenina;, uma parte da Floresta Noturcanto, a sudoeste daqui, recentemente começou a ser chamada de Monte Fogovil. É muito triste ver os demônios se esgueirando por lá, espalhando a vilania.$B$BVocê poderia nos ajudar a retomar aquelas terras?$B$BTenho aqui algumas sementes que guardei para um momento como este. Leve-as até o Monte Fogovil e plante-as em terra fértil.', '', 'Mudas de Árvore plantadas', '', '', '', '', '', '', '', 'Fale novamente com Nodoso no Acampamento de Lenhadores Brado Guerreiro, que fica no Vale Gris.', 0),
(26447, 'ptBR', 'Planos diabólicos', 'Entregue os Planos Diabólicos a Valusha no Posto Machadada, que fica no Vale Gris.', 'Um demônio deixou este pergaminho cair, e surpreendentemente o texto está escrito em órquico! Diathorus e Gorgannon, que são mencionados no pergaminho, são os infames senhores do medo que controlam os demônios da região.$B$BOs planos detalham os preparativos para um ataque demoníaco ao Posto Machadada, a noroeste daqui.$B$BCertamente Valusha, no Posto Machadada, se interessará em ver os planos.', '', '', '', '', '', '', '', '', '', '', 0),
(26448, 'ptBR', 'Destrua a Legião', 'Mate 15 demônios de qualquer tipo no Monte Fogovil, no Cânion do Demônio Caído ou na Serra do Demônio Caído.', 'Os remanescentes da demoníaca Legião Ardente têm sido uma pedra em nosso sapato por muito tempo!$B$BOs demônios estão vindo das áreas conhecidas como Monte Fogovil, Cânion do Demônio Caído e Serra do Demônio Caído, a leste daqui.$b$bVá até lá e destrua todos os demônios que conseguir. Conquiste essa glória, por você $gmesmo:mesma; e pela Horda!', '', 'Demônios destruídos', '', '', '', '', '', '', '', 'Fale com Valusha no Posto Machadada.', 0),
(26449, 'ptBR', 'Nunca mais!', 'Consiga a Espada Flamejante de Gorgannon e a Lança Maligna do Inquisidor.', '$n, é sua responsabilidade impedir que esse ataque da Legião Ardente aconteça! Vá até lá e mate os senhores do medo! Sem eles, o resto dos demônios é basicamente um bando de idiotas desorganizados.$b$bVocê encontrará Gorgannon no Cânion do Demônio Caído, ao sul, além do Monte Fogovil, próximo à lança partida de Mannoroth.$b$bDiathorus, o Inquisidor, está em algum lugar do covil no alto da Serra do Demônio Caído.$b$bTraga as armas deles para mim como prova dos seus feitos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Valusha no Posto Machadada, que fica no Vale Gris.', 0),
(26450, 'ptBR', 'Se elas estão largadas por aí...', 'Obtenha 6 Ícones de Naga da Costa Selvagem Sul, que fica no Cabo do Espinhaço.', 'Eu tava pensando em uma coisa, $n. Aquelas nagas têm mais do que junco lá embaixo. Elas costumam deixar umas estatuetas perto dos santuários, na areia, sob as árvores. Elas não parecem estar usando as estátuas agora.$b$bMas eu bem que poderia usar essas estátuas! Eu podia colocá-las no gramado, para parecer mais aconchegante. Qualquer coisa é melhor do que uma maldita ossada de dinossauro. Eu poderia vender como souvenires.$b$bEu poderia vendê-las de volta para as nagas!$b$bPor que você não pega uma ou duas enquanto eu penso no que fazer com elas?', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Espoleta Chaveforte no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26451, 'ptBR', 'Desafio de Gurubashi: combate de arena cada um por si', 'Coloque a Bandeira de Desafio de Gurubashi no chão, dentro do Ringue de Batalha. Depois, derrote o Desafiante da Arena Gurubashi.', 'A arena é um campo de batalha diferente de todos os outros. Lá dentro, você não tem aliados. As alianças que se formam são frágeis, pois seus aliados podem se voltar contra você a qualquer momento. Horda conta Aliança, Aliança contra Aliança, Horda contra Horda... Qualquer coisa vale.$b$bPegue esse estandarte de batalha, $r, e coloque-o no pátio da arena. Derrote os combatentes evocados e volte para falar comigo.$b$bTome cuidado, $r. Como eu disse, qualquer coisa vale na Arena de Gurubashi.', '', 'Derrote seu Desafiante da Arena Gurubashi', '', '', '', '', '', '', '', 'Fale novamente com Guarda Pétreo Couro Grosso na Grande Arena, que fica no Cabo do Espinhaço.', 0),
(26452, 'ptBR', 'Desafio de Gurubashi', 'Coloque a Bandeira de Desafio de Gurubashi no chão, dentro do Ringue de Batalha. Depois, derrote o Desafiante da Arena Gurubashi.', 'Você voltou, $r. Isso quer dizer que você sentiu o chamado da arena mais uma vez. Pois bem.$b$bPegue esse estandarte de batalha, $r, e coloque-o no pátio da arena. Derrote os combatentes evocados e volte para falar comigo.$b$bTome cuidado, $r. Como eu sempre digo, vale qualquer coisa na Arena de Gurubashi.', '', 'Derrote seu Desafiante da Arena Gurubashi', '', '', '', '', '', '', '', 'Fale novamente com Guarda Pétreo Couro Grosso na Grande Arena, que fica no Cabo do Espinhaço.', 0),
(26453, 'ptBR', 'Ajuda nunca é demais', 'Fale com o Arquiteto Nemos em Cantilenda, que fica no Vale Gris.$B$BA Vindicante Palannaar pode lhe dar um meio de transporte para que você chegue lá mais rapidamente.', 'Sob a supervisão do arquiteto Nemos e do vindicante Vedaar, meu povo vem revitalizando um antigo entreposto noctiélfico no lado leste do Vale Gris.$B$BTal reconstrução não será fácil, $n, pois os desafios e os inimigos são muitos. Por certo o arquiteto Nemos e seus companheiros em Cantilenda estimarão todo auxílio que receberem. Ele me pediu que encaminhasse para lá todos os interessados em ajudar.$B$BQuando estiveres $Gpronto:pronta; para partir, fala comigo novamente e tomarei providências para que tu sejas rapidamente $Gtransportado:transportada; para Cantilenda.', '', '', '', '', '', '', '', '', '', '', 0),
(26454, 'ptBR', 'Desperdício vergonhoso', 'Recolha 5 feixes de Madeira Vil de Satyrnaar.', '$GBem-vindo:Bem-vinda; a Cantilenda, $c. Onde se vê tendas, em breve haverá edifícios, mas tal ambição requer um contínuo fluxo de material. Não sou capaz de ordenar que nossos operários derrubem as venerandas árvores deste bosque, mas nossos vizinhos a oeste não têm o mesmo respeito pela floresta.$B$BTemos que reaver com os sátiros de Satyrnaar, a oeste, a madeira maculada. Leva a madeira para Nodoso, no Acampamento de Lenhadores Brado Guerreiro. Ele é um anciente, e purificará o material para que possamos usá-lo.', '', '', '', '', '', '', '', '', '', 'Fale com Nodoso no Acampamento de Lenhadores Brado Guerreiro, que fica no Vale Gris.', 0),
(26455, 'ptBR', 'O cálice perdido', 'Consiga o Cálice de Eluna.', 'A área a oeste daqui, que agora é conhecida como Satyrnaar, já foi um importante santuário construído pelo meu povo. Lá guardava-se uma relíquia inestimável, o Cálice de Eluna, confiado aos guardiões do santuário pelos sacerdotes de Eluna. O lugar um dia recebeu peregrinos em busca dos supostos poderes curativos do cálice.$B$BTais relatos podem não passar de histórias da carochinha mas, se houver alguma verdade nisso, a relíquia pode ser a chave para recuperar a floresta ferida. Preciso descobrir, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kainet Brisacalma em Cantilenda, que fica no Vale Gris.', 0),
(26456, 'ptBR', 'Notícias do front setentrional', 'Entregue o relatório da Sentinela Melyria para a Sentinela Cantálgures no Bosque Asa de Prata, que fica no Vale Gris.', 'O combate à Horda não está sendo travado apenas a partir da Torre do Bosque Real, $n. Há um efetivo mais numeroso de sentinelas da Asa de Prata a sudeste daqui, perto da fronteira com os Sertões. Do Bosque Asa de Prata, a sentinela Cantálgures orienta os esforços contra os que intentam destruir nossas terras.$B$BJá passou da hora de eu enviar um relatório para ela, mas não quero deixar a torre desguarnecida.$B$BPreciso muito que você entregue este relatório a ela o mais rápido possível!', '', '', '', '', '', '', '', '', '', '', 0),
(26457, 'ptBR', 'Agentes da destruição', 'Mate o Feitor Gorthak e mais 12 membros da Horda no Acampamento de Lenhadores Brado Guerreiro.', 'O Acampamento de Lenhadores Brado Guerreiro é uma chaga nestas cercanias conflagradas. Quanto mais prejudicamos as operações deles, mais o feitor Gorthak ordena aos lenhadores que redobrem os esforços!$B$BAgora, os orcs estão cortando mais madeira do que jamais usarão, deixando-a apodrecer enquanto o fio dos machados se deita sobre mais árvores! Isso é uma afronta a tudo por que lutamos, $n.$B$BVamos mostrar a eles que não deixaremos a destruição das nossas terras continuar!$B$BVá, e não descanse até matar o feitor Gorthak e os lacaios dele!', '', '', 'Membros da Horda mortos no Acampamento', '', '', '', '', '', '', 'Fale novamente com a Sentinela Luciel Sussurrastra no Acampamento de Lenhadores Brado Guerreiro, que fica no Vale Gris.', 0),
(26459, 'ptBR', 'Researching the Corruption', 'Relwyn Shadestar at the Blackfathom Camp wants 8 Corrupt Brain stems.', 'Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?$b$bI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.$b$bI wish to study the brain stems of the satyr and naga so that I might deduce what fate the sin\'dorei are headed toward. In Blackfathom Deeps, just to the west, you will find both satyr and naga.', '', '', '', '', '', '', '', '', '', '', 0),
(26462, 'ptBR', 'O Revatusco perverso', 'Mate 10 Espreitadores Revatusco ou Bagateiros Revatusco.', 'Esses trolls Revatusco acham que são especiais só porque são da Horda. Tenho que rir!$B$BVeja, o engraçado é que não importa se eles fazem parte da Horda, ou de algum tipo de império troll, ou da maldita Legião Ardente. Nós já enfrentamos trolls nestas terras há alguns séculos.$B$BNa verdade, vou ser boazinha e te deixar ajudar, $ggaroto:garota;! Pegue uma arma, parta para o campo de batalha e ajude os rapazes a leste.', '', 'Revatusco morto', '', '', '', '', '', '', '', 'Fale novamente com Kerr Aço-de-mira no Posto Avançado Penafúria, que fica nas Terras Agrestes.', 0),
(26463, 'ptBR', 'Procurando Teronis', 'Procure Teronis no Lago Falathim, que fica no Vale Gris.', 'Raene Correlobos, uma amiga de Astranaar, me pediu que eu destacasse um batedor para o Lago Falathim, a oeste daqui. Enviei Teronis, que partiu já faz dias, logo antes de a Horda atacar.$B$BTeronis saiu para procurar um item que, segundo ele, teria o poder de dificultar os ataques dos pelursos contra nosso povo, um bastão criado por um teurgo cruel, já falecido.$B$BAntes de partir, Teronis mencionou algo sobre encontrar uma gema para o bastão. Mas, infelizmente, sabemos que o Lago Falathim foi invadido por alguma força malévola.$B$BPor favor, $n, encontre meu amigo!', '', '', '', '', '', '', '', '', '', '', 0),
(26464, 'ptBR', 'A gema perdida', 'Encontre a Gema Faiscante.', 'Você revista os pertences de Teronis e encontra um diário danificado pela água.$B$BAo folhear as últimas páginas legíveis, você descobre que Teronis conseguiu encontrar a gema, mas a perdeu logo em seguida, perto do lago.$B$BSó resta a você encontrá-la. Será que as gavinhas a pegaram?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Orendil Folharga no Entreposto de Maestra, que fica no Vale Gris.', 0),
(26465, 'ptBR', 'As estatuetas ancestrais', 'Recolha 10 Estatuetas Ancestrais.', 'Vou dar uma tarefa para você, $c.$B$BEu estava no meu barco, deslizando nas águas sobre as ruínas de Zoram, quando algumas nagas me atacaram. Elas surgiram da água e partiram para cima de mim com aquelas garras imensas! Eu consegui fugir e o resto, como dizem por aí, é história.$B$BSou arqueólogo amador e estou procurando artefatos da cidade perdida.$B$BVocê poderia ir até a Praia de Zoram, a sudoeste daqui, e recolher todas as estatuetas antigas que encontrar? Foi por causa delas que eu resolvi desbravar os perigos da Praia de Zoram.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Talen no Acampamento das Profundezas Negras, que fica no Vale Gris.', 0),
(26466, 'ptBR', 'Ruuzel', 'Obtenha o Anel de Zoram.', 'Receio que os segredos das estatuetas ancestrais continuem escondidos para sempre a não ser que você encontre a chave para abrir as fechaduras.$B$BA chave na verdade é um anel, o Anel de Zoram. Ele pertencia aos líderes da cidade antes das ondas da Cisão tomarem conta de tudo.$B$BO anel ficou perdido por muitos anos, mas há pouco tempo as nagas o encontraram.$B$BA líder delas, Ruuzel, habita a ilha na ponta norte da Praia de Zoram. Por favor, $n, consiga esse anel para mim!', '', '', '', '', '', '', 'Ruuzel', '', '', 'Fale novamente com Talen no Acampamento das Profundezas Negras, que fica no Vale Gris.', 0),
(26467, 'ptBR', 'Malditos sátiros! Dríades em perigo!', 'Encontre Anilia em Xavian, que fica no Vale Gris.', 'Escute aqui, eu não sei quem é você, mas preciso da sua ajuda. Minhas irmãs foram pegar o Ramo de Cenarius de volta dos sátiros. Elas disseram que voltariam rápido, mas já se passaram dois dias inteiros!$B$B$n, você tem que encontrá-las! Elas estavam procurando as ruínas de um tempo noctiélfico em Xavian, a noroeste daqui. Eu não sei mais o que pensar. Procure Anilia; ela era a responsável pela expedição.', '', '', '', '', '', '', '', '', '', '', 0),
(26468, 'ptBR', 'O ramo de Cenarius', 'Consiga o Ramo de Cenarius.', 'Anilia põe a mão sobre os seus ombros e puxa você para perto. Ofegante, ela aponta para o arco a norte, antes de fechar os olhos e exalar o último suspiro. "Ele pegou o ramo... Geltharis..." Você sente em sua alma que o último pedido de Anilia é devolver o Ramo de Cenarius às dríades.', '', '', '', '', '', '', 'Geltharis', '', '', 'Fale novamente com Iliana em Cantilenda, que fica no Vale Gris.', 0),
(26469, 'ptBR', 'Temporada de caça aos sátiros', 'Consiga 16 Chifres de Sátiro.', 'Mal consigo acreditar que Anilia se foi... Nós sempre brincávamos nas florestas. Eu me sinto quase... triste.$B$BMas eu sei de uma coisa que vai me fazer sentir melhor. Por favor, mate os sátiros que tiraram Anilia de mim! Traga os chifres desses facínoras como prova de seu feito e lhe serei eternamente grata.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Iliana em Cantilenda, que fica no Vale Gris.', 0),
(26470, 'ptBR', 'A retomada do Lago Mistral', 'Mate Mareante e 12 Elementais da Água Contaminados.', 'Nós teríamos facilmente impedido a tomada do Refúgio Brisaprata pela Horda se eles não tivessem assumido o controle sobre os elementais da água no Lago Mistral.$B$BUm dos xamãs da Horda evocou Mareante, um velho e raivoso espírito da água que desvirtuou nossos elementais e os jogou contra nós. Com o ataque da Horda e do lago contra nós, nossa única opção foi recuar até esta torre.$B$BVá para leste e retome o lago para que, um dia, possamos retomar o refúgio.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sentinela Velene Golpestela na Torre Poeira Estelar, que fica no Vale Gris.', 0),
(26472, 'ptBR', 'Druidas insanos', 'Mate os druidas insanos: Taneel Lenhanegra, Uthil Chamaluna e Mavoris Rasganimbus.', 'Os druidas foram mortos pelos próprios líderes, que enlouqueceram com a corrupção que a Horda causou no Coração da Floresta! Eu consigo sentir a corrupção daqui, e não ousarei ir além.$B$BSe, por um lado, eu estou muito integrado com o Vale Gris e o Coração da Floresta, você... Você poderia descer à gruta e fazer o que tem que ser feito. Eu deixei pistas para você lá.$B$BPor mais que isso me doa, vou ter que pedir a você que dê um fim aos antigos grandes líderes druidas: Taneel Lenhanegra, Uthil Chamaluna e Mavoris Rasganimbus.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gaivan Andassombras, que está andando pelo lado de fora da entrada do Retiro de Dor\'Danil, no Vale Gris.', 0),
(26473, 'ptBR', 'Cabelo-de-bathran', 'Colha 8 ramos de Cabelo-de-bathran.', 'Nas ruínas do Refúgio de Bathran, do outro lado da estrada, a leste, cresce uma planta chamada cabelo-de-bathran. Ela é conhecida por curar os males do espírito.$B$BAgora, a Horda está colhendo a planta para usar em seus propósitos vis.$B$BUma criança está doente em Astranaar, e achamos que seu mal não é apenas físico. Prometi a meu mestre que ajudaria a encontrar uma cura para ela, mas não sou nenhum guerreiro.$B$BVocê poderia ir até o Refúgio de Bathran e colher alguns ramos da erva?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Evenar Placimúrmur no Retiro de Orendil, que fica no Vale Gris.', 0),
(26474, 'ptBR', 'A cura de Orendil', 'Entregue a Cura de Orendil a Pelturas Lunalva em Astranaar, que fica no Vale Gris.', '$n, acho que a concocção, agora que foi banhada na luz abençoada de Eluna, vai ajudar a criança doente. Por favor, leve o preparado para Astranaar e entregue-o ao pai da menina, Pelturas Lunalva.$B$BPara chegar lá, siga pela estrada em direção ao sul e, em seguida, ao leste. Mas, se você quiser chegar lá mais rapidamente, fale com a sentinela Avana.', '', '', '', '', '', '', '', '', '', '', 0),
(26475, 'ptBR', 'A lágrima de Eluna', 'Consiga uma Lágrima de Eluna.', 'Eu tinha esperanças de que a cura de Orendil fosse salvar Relira, mas isso apenas reduziu o avanço do mal. Temos que encontrar um remédio mais poderoso! Mas, graças a Eluna, Orendil mencionou outros remédios, caso o primeiro não funcionasse.$B$BA lágrima de Eluna é um cristal que só existe em um lugar: nos resquícios do Lago Íris, que foi destruído pela erupção do Pico do Trovão, a nordeste de Astranaar. Orendil disse que essa pedra purifica qualquer tipo de corrupção.$B$BPor favor, $n, traga-me a lágrima de Eluna e reze para que ela dê um fim ao mal de minha filha!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pelturas Lunalva em Astranaar, que fica no Vale Gris.', 0),
(26476, 'ptBR', 'Trabalho de dríade', 'Entregue a Gema Faiscante a Shael\'dryn na Torre do Bosque Real, que fica no Vale Gris.', 'Ah, aí está você, $n. Eu estudei as anotações de Teronis e parece que o próximo passo é encontrar as outras partes do Bastão de Dartol.$B$BEu começaria pegando a estrada para a Torre do Bosque Real, ao leste.$B$BChegando lá, uma dríade chamada Shael\'dryn poderá orientá-$Glo:la; melhor. Procure por ela.$B$BGuarde a gema. Shael\'dryn vai precisar dela para ajudar você a reconstruir o bastão.', '', '', '', '', '', '', '', '', '', '', 0),
(26477, 'ptBR', 'Madeira sem lei', 'Encontre a Chave de Madeira e use-a para pegar a Haste de Ferro do Bastão de Dartol.', 'Eu gostaria que as notícias que você me trouxe fossem melhores.$B$BRaene está certa. Eu sei da criação de Dartol e conheço os arvorosos daqui... ou, pelo menos, conheci um dia. Todos foram corrompidos, suas naturezas desvirtuadas.$B$BPara encontrar a outra parte do bastão, você precisa pegar a chave para abrir o baú onde a peça está guardada.$B$BA chave de madeira está com um dos arvorosos, a noroeste daqui, perto da fronteira com a Selva Maleva, no Vale Uivante. Após pegar a chave, procure uma pequena clareira depois de um túnel. O baú deve estar escondido ali.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Shael\'dryn na Torre do Bosque Real, no Vale Gris.', 0),
(26478, 'ptBR', 'Fingindo de morto', 'Pegue a última peça do Bastão de Dartol, o Castão de Ferro.', 'A última parte do bastão está em poder dos druidas da Garra. Eu pedi educadamente ao líder deles, Oso Espinheira, que a entregasse para mim, mas ele e sua guarda quase me mataram! Eles claramente também foram afetados pela corrupção causada pela Horda no Coração da Floresta.$B$BMas eu sei como você vai conseguir entrar na caverna de Oso e pegar o castão.$B$BDesde filhote, sou ótima em me fingir de morta. Funciona muito bem contra ursos! E vou ensinar você a fazer isso! Vá até a Gruta Escura, a norte daqui, e, se alguém tentar expulsar você de lá, use a minha técnica.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Shael\'dryn na Torre do Bosque Real, no Vale Gris.', 0),
(26479, 'ptBR', 'Retorno a Raene', 'Entregue o Bastão de Dartol para Raene Correlobos em Astranaar, no Vale Gris.', 'Eu sugiro que você encontre Raene e diga a ela que o bastão está pronto. Ela saberá dizer qual é o próximo passo a dar.$B$BMas tenha cuidado... Estou sentindo um grande poder no bastão, tanto para o bem quanto para o mal. Espero que você e Raene saibam o que estão fazendo.$B$BBoa sorte, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(26480, 'ptBR', 'Bastão de Dartol', 'Use o Bastão de Dartol para se comunicar com Krolg na Cabana do Krolg, que fica no Vale Gris.', 'Não sei muito bem o que Teronis planejou mas, se o que ele disse sobre o poder do bastão for verdade, você poderá assumir uma outra forma, provavelmente de pelurso.$B$BTalvez o objetivo dele fosse se aproximar dos pelursos, mas mesmo os ainda não corrompidos poderiam matá-lo, caso não fosse cuidadoso. Transformado pelo poder do bastão, Dartol teria que falar com algum pelurso ainda imaculado.$B$BEu começaria com um conhecido como Krolg. Procure-o na cabana a sudeste do Lago Mistral.', '', '', '', '', '', '', '', '', '', '', 0),
(26481, 'ptBR', 'Enfeite novo', 'Consiga o Crânio de Ran Dente Sangrento e o Bastão de Dartol.', 'Não tenho dúvidas de que a intenção de Dartol, um teurgo que já morreu há bastante tempo, era usar o bastão para nos subjugar e destruir, exatamente como os elfos noturnos e os orcs. No entanto, acho que agora daremos um novo uso àquela coisa.$B$BRan Dente Sangrento é o rei dos pelursos do Vale Gris. A tribo dele, a Dente Sangrento, é a mais poderosa de todas, e fica isolada em uma colina a leste daqui.$B$BMate-os todos e traga-me a cabeça de Ran Dente Sangrento. Vamos dar um novo uso a ela também.', '', '', '', '', '', '', 'Ran Dente Sangrento', '', '', 'Fale novamente com Krolg na Cabana do Krolg, que fica no Vale Gris.', 0),
(26482, 'ptBR', 'O verdadeiro poder do bastão', 'Use o Bastão de Dartol e fale com Ota Wen. Convença-o a se insurgir contra os opressores da Horda. Em seguida, entregue o Bastão de Dartol para Raene Correlobos.', 'Agora, use o poder do bastão para conseguir falar com meu irmão, Ota Wen.$B$BOta é um dos pelursos presos pelos orcs em uma jaula gigante no lado norte do Refúgio Brisaprata. Com o bastão, você vai conseguir convencer os outros pelursos a se insurgir e atacar a Horda.$B$BEntão, você poderá tomar o caminho que bem entender. Saiba que, graças ao seus feitos, você conquistou um novo amigo.', 'Revolta dos pelursos deflagrada.', '', '', '', '', 'Revolta dos pelursos deflagrada.', '', '', '', 'Entregue o Bastão de Dartol para Raene Correlobos em Astranaar, no Vale Gris.', 0),
(26483, 'ptBR', 'Gan\'dranda', 'Mate Gan\'dranda.', 'Por mais divertido que seja ficar batendo cabeça aqui com esses trolls, a gente tem mais o que fazer. Ia ser bom demais acabar logo com essa peleja, não ia?$B$BO comandante deles, que se chama Gan\'dranda, costuma ficar atrás daqueles muros arrebentados a sudeste do campo de batalha. Nossos rapazes estão ocupados pra caramba, então quero que você entre lá e dê cabo do sujeito. Quando eles virem $gum:uma; $r ao lado do corpo do grande herói deles, ah, eles vão ficar murchinhos!', '', '', '', '', '', '', 'Gan\'dranda', '', '', 'Fale novamente com Kerr Aço-de-mira no Posto Avançado Penafúria, que fica nas Terras Agrestes.', 0),
(26484, 'ptBR', 'Ajuda ao Larpétreo', 'Fale com Petros Esmagapedra no Larpétreo, que fica no Geodomo.', 'Há quinze mil anos, os terranos e os troggs de pedra encontraram, não se sabe como, uma forma de entrar no Geodomo a partir de Uldum. Desde então, só há hostilidade entre eles.$B$BSe quisermos recuperar o fragmento central do Pilar do Mundo, temos que resgatar o Petrarca.$B$BPor favor, vá até o Larpétreo e faça tudo que puder para ajudar os terranos na luta contra os troggs de pedra.$B$BVocê é nossa única esperança, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(26485, 'ptBR', 'Mordeliscas, jovem!', 'Colete 8 Moelas de Mordelisca de Mordeliscas de Água Salgada.', 'Quero produzir algo especial para aqueles trolls irritantes. Sim, eu disse para eles... uma bebida que nunca vão esquecer! Uma bebida que vai fazê-los catar as presas nas encostas!$B$BJá tenho alguns ingredientes de molho, mas preciso de ajuda para conseguir outros. No sopé dos Penhascos Panorâmicos a leste, perto da costa, tem um montão de mordeliscas. Eu preciso de moelas frescas inteiras delas para meu engasga gato.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dron Explodecerva no Posto Penafúria, que fica nas Terras Agrestes.', 0),
(26486, 'ptBR', '100 garrafas de bebida na praia', 'Recolha 12 garrafas de Xerez de Pupellyverbos.', 'Bah, eu sei que estamos no meio de uma briguinha encarniçada, mas tem umas garrafas ótimas espalhadas lá pelos penhascos panorâmicos! Não quero ver boa bebida caindo nas mãos da Horda!$B$BSe você for para aquele lado, recolha as garrafas e traga-as pra mim. Eu pago um bom preço por elas, como se você $gmesmo:mesma; as tivesse engarrafado!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dron Explodecerva nas Terras Agrestes.', 0),
(26487, 'ptBR', 'Akiris aos montes', 'Obtenha 6 Juncos de Akiris das Exploradoras Nagas.', 'É difícil administrar um resort 5 estrelas exótico que também é uma estação coletora de recursos silvestres! Ou melhor, seria difícil se eu não fosse tão organizada quanto uma assistente pessoal de príncipe mercador!$b$bO segredo é ser multitarefa. Por exemplo, as exploradoras nagas ao sul carregam um tipo de junco do mar muito valioso, que nós chamamos de junco de Akiris. Nós podemos vender esse junco para os nossos clientes do outro continente ou podemos usá-lo como enchimento nos colchões do resort! Pensando bem, nós podemos usar o junco para muito mais coisas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Espoleta Chaveforte no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26488, 'ptBR', 'Olho grande', 'Fisgue um Tamboril-real no fosso do distrito do Vale dos Heróis, em Ventobravo. Em seguida, abra o peixe e veja se ele engoliu o medalhão.', 'Arnoldo e eu costumávamos relaxar no fosso do Vale dos Heróis. Um dia, eu deixei um medalhão cair na água e nunca mais o encontrei. Dizem por aí que aquele fosso está infestado de tamboris-reais enormes que comem tudo o que veem pela frente! Eu sei que é um tiro no escuro, mas você poderia pegar alguns tamboris para ver se acha o meu medalhão?$b$bPor favor, me avise assim que você o encontrar. Esse medalhão é muito precioso para mim.', '', '', '', '', '', '', '', '', '', 'Entregue o Medalhão Precioso para Catarina Gurjão em Ventobravo.', 0),
(26489, 'ptBR', 'É você!!', 'Obtenha 6 Juncos de Akiris das Exploradoras Nagas.', 'Pois não, posso ajud...$b$b<Espoleta fica de queixo caído.>$b$b$n! É você mesm$Go:a;? Olha só como você está grande e forte! Deixe-me ver esses bíceps!$b$bEu? Eu tenho tentado ganhar a vida aqui na floresta. Nós atuamos principalmente no ramo de aquisições de bens, mas também com turismo.$b$bEu sei, é genial né?$b$bEi, escuta só... Eu estava pensando: as exploradoras nagas ao sul carregam junco de akiris, e nós poderíamos vender isso ou usar como enchimento nos colchões dos hóspedes. Você tá interessad$go:a; em matar umas nagas? Vai ser como nos velhos tempos!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Espoleta Chaveforte no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26490, 'ptBR', 'Visgo de primeira', 'Recolha uma Amostra de Gosma Horrenda.', 'Quase nenhum anão sabe disso, mas, para dar uma PRESSÃO de verdade na minha cerveja, eu boto um tiquinho dessas gosmas na mistura. Isso mesmo, as gosmas verdes gigantes que comem anões, aquelas mesmo.$B$BMas eu quero que essa cerveja tenha uma BAITA pressão, por isso a gente precisa de um visgo gigante! Tem um de butuca na Rocha Oculta que é a mãe de todos eles, a coisa é simplesmente enorme... A gente chama ela de Gosma Horrenda.$B$BSe você for $Gmacho:braba; de verdade;, vá até lá e arranque um pedaço da Gosma Horrenda para mim!', '', '', '', '', '', '', 'A Gosma Horrenda', '', '', 'Fale novamente com Dron Explodecerva no Posto Penafúria, que fica nas Terras Agrestes.', 0),
(26491, 'ptBR', 'Limpeza na Rocha Oculta', 'Mate 10 Gosmas Jade.', 'Há alguns anos, havia uma base da Horda nas profundezas da Rocha Oculta. Ela está abandonada desde então, mas ainda é um território de primeira, que vale a pena ser tomado para nossos aliados!$B$BO problema é que ela está cheia de visgos e gosmas comedores de anões. Aquelas coisas são ligeiramente menos repulsivas do que trolls, mas ainda assim vão nos dar trabalho.$B$BCom nossos rapazes empenhados na luta contra os Revatusco, preciso que você vá à Rocha Oculta e limpe o lugar para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kerr Aço-de-mira no Posto Avançado Penafúria, que fica nas Terras Agrestes.', 0),
(26492, 'ptBR', 'Os suprimentos da Rocha Oculta', 'Recolha 5 Caixas de Suprimentos Cobertas de Gosma.', 'Um primo meu participou da segunda guerra! Ele sempre me falava de um raide que eles fizeram na Rocha Oculta. Entraram varrendo os trolls para fora como ratos do ninho. Eles os perseguiram até Alterac!$B$BOs visgos se mudaram para lá logo em seguida, e ainda há caixas com antigos bens da Horda repousando lá dentro. Que tal se não deixarmos os trolls recuperá-las!$B$BTraga-me alguns caixotes da Rocha Oculta, a noroeste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kerr Aço-de-mira no Posto Avançado Penafúria, que fica nas Terras Agrestes.', 0),
(26493, 'ptBR', 'Alguém lá fora quer isso', 'Obtenha 7 porções do Ingrediente Secreto da Espoleta dos basiliscos Ferroqueixo e Batecauda que ficam na Mina Veio de Cristal.', 'Bom, já que você já tá $gtodo sujo:toda suja; por cumprir essas tarefas, eu quero te pedir mais uma coisa. Você não se importa né?$b$bA edição mais recente da revista sobre Ciências e Explosões acabou de chegar do Ancoradouro Borraquilha, e ela traz um artigo sobre um novo reagente quentíssimo. Os preços desse novo reagente estão aumentando loucamente e nós estamos numa posição ótima para fazer capital!$b$b<A Espoleta fala os detalhes no seu ouvido.>$b$bEntendeu? Que bom. Você vai encontrar os basiliscos em uma caverna, bem para o leste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Espoleta Chaveforte no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26494, 'ptBR', 'M.C. Jasper', 'Leve as Amostras da Espoleta para o M.C. Jasper no Esconderijo da Chaveforte.', 'Você poderia entregar algumas dessas coisas para o Jasper, lá nas suítes superiores? Tenho certeza de que ele vai encontrar uma utilidade perfeita para isso.$b$bObrigada, $n!', '', '', '', '', '', '', '', '', '', '', 0),
(26495, 'ptBR', 'Chabal', 'Leve o Presente Generoso da Espoleta para o Chabal no Esconderijo da Chaveforte.', 'Chabal, aquele troll ali no jardim botânico/laboratório de armas biológicas é nosso hóspede especial. Ele é um representante dos trolls Zandalari e veio de bem longe para ficar aqui conosco.$b$b<Espoleta coloca alguns dos itens que você coletou em um pequeno pacote e lhe entrega.>$b$bToma, entrega isso pra ele. Diga a ele que os Zandalari serão sempre bem-vindos no Esconderijo da Chaveforte. E lembre-o que a indicação é a alma do negócio!', '', '', '', '', '', '', '', '', '', '', 0),
(26496, 'ptBR', 'Abaixo os Ramatorpe', 'Encontre Doran Asadaço em Jintha\'Alor, que fica nas Terras Agrestes.', 'Os Revatusco não são a única tribo de trolls infames que estamos aqui para liquidar! Os Ramatorpe conspurcam esta terra há anos da fortaleza de Jintha\'Alor.$B$BNão deu para perceber que estamos cansados de ficar no Ninho da Águia assistindo a tudo isso sem fazer nada? Doran Asadaço lidera o ataque contra os Ramatorpe de um acampamento que os rapazes tomaram a sul daqui. Fale com ele e entre na luta!', '', '', '', '', '', '', '', '', '', '', 0),
(26497, 'ptBR', 'Escória Ramatorpe', 'Mate 5 Mandingueiros Ramatorpe e 5 Caçadores de Cabeças Ramatorpe em Jintha\'Alor.', 'Os Ramatorpe são uma tribo diferente dos Revatusco, mas a diferença é teórica. Para nós, troll bom é troll morto!$B$BMas não se engane: os Ramatorpe são tão sórdidos quanto os Revatusco, mesmo sem a corrente da Horda em volta do pescoço. Eles vão envenenar toda esta terra a menos que tomemos essa fortaleza e nos livremos deles.$B$BComece com os mandingueiros e os caçadores de cabeças na esfera mais baixa. Me avise quando tiver matado um bocado deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Doran Asadaço em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26498, 'ptBR', 'Morte aos Ramatorpe', 'Mate 5 Berserkers Ramatorpe e 5 Lança-sombras Ramatorpe em Jintha\'Alor.', 'Estamos indo bem. Continue assim e não hesite!$B$BOs berserkers Ramatorpe lutam como animais ferozes, tomados por um frenesi sanguinário. Os Lança-sombras deles evocam espíritos malignos de outro mundo! É por isso que estamos nos livrando dessas criaturas degeneradas, $n, nunca se esqueça disso.$B$BVá ao terraço intermediário e mate os berserkers e os lança-sombras!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Doran Asadaço em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26499, 'ptBR', 'Bênção do Petrarca', 'Conceda a Bênção do Petrarca a 12 Defensores do Larpétreo.', 'Com a captura do Petrarca, as tropas estão desmoralizadas. Em uma situação normal, um dos meus homens seria capaz de derrubar cinco troggs de pedra. Mas agora...$B$BQuero que você vá para o campo que cerca a cidade. Finque o estandarte do Petrarca Rochamanto ao lado de nossos defensores. Que eles recebam a bênção do Petrarca e se lembrem por quem estão lutando.', '', 'Bênção do Petrarca concedida', '', '', '', '', '', '', '', 'Fale novamente com Petros Esmagapedra no Larpétreo, que fica no Geodomo.', 0),
(26500, 'ptBR', 'Do que é feito um trogg', 'Mate 12 Troggs de Pedra Emboscadores.', 'Estamos em guerra há mais tempo do que o próprio tempo do seu povo. Vamos ver se você consegue fazer a diferença, $r.$B$BOs troggs de pedra são um erro dos titãs. No seu mundo, eles sucumbiram à Maldição da Carne. Aqui, no Geodomo, eles estão em sua genuína forma.$B$BEstamos cercados. Você poderia ir até lá e arrebentar alguns troggs por nós? Vamos ver do que eles realmente são feitos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Rompe-terra Dolomita no Larpétreo, que fica no Geodomo.', 0),
(26501, 'ptBR', 'Passando o trinco', 'Ajude os Geomantes Terranos a sair de combate e entregue-lhes os Reagentes de Avalanche para que eles possam lacrar o Arsenal, a Estalagem, a Guarnição Militar e o Templo.', 'Os troggs de pedra estão abrindo túneis por baixo das nossas casas!$B$BEu mandei os geomantes lacrarem todos os prédios. Mas, para fazerem os rituais de deslizamento de terra, eles precisam de reagentes e de um tempo fora de combate.$B$BQuando terminar, apresente-se a Seixo Lajegrande, a norte do Front Partido.', '', 'Arsenal lacrado', 'Estalagem lacrada', 'Guarnição Militar lacrada', 'Templo lacrado', '', '', '', '', 'Fale com Seixo Lajegrande no Front Partido, que fica no Geodomo.', 0),
(26502, 'ptBR', 'Pedras do trovão', 'Colete 12 Pedras do Trovão.', 'Os combates mais intensos estão sendo travados no Front Partido, a norte daqui.$B$BEntre no Larpétreo e pegue todas as pedras do trovão que conseguir. Nossos engenheiros estão precisando dessas pedras para as catapultas.$B$BQuando você tiver coletado pedras suficientes, entregue-as para o Árgilos Venalama. Não repare no que ele disser. O Venalama está velho, rabugento e deveria ter voltado para dentro da terra há milhares de anos.', '', '', '', '', '', '', '', '', '', 'Entregue as Pedras do Trovão para Árgilo Venalama no Front Partido, que fica no Geodomo.', 0),
(26503, 'ptBR', 'Ainda avaliando a ameaça', 'Roube o Plano de Batalha Gnoll, as Ordens Gnoll e o Guia Estratégico Gnoll.', 'Aqueles cachorros sujos gnolls estão armando alguma coisa. Posso sentir nos ossos. A atividade gnoll na área triplicou nas últimas duas semanas. Temo que estejam se concentrando para um ataque em Vila Plácida.$B$BPreciso que você vá a cada acampamento gnoll aqui da área e me traga todas as informações que conseguir de lá. Verifique os acampamentos diretamente ao norte, leste e sudeste daqui. Me traga o que encontrar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão da Guarda Florestan na Torre Vigilante, que fica em Cristarrubra.', 0),
(26504, 'ptBR', 'Procuram-se: Gnolls de Cristarrubra', 'Mate 15 Gnolls de Cristarruba na região de Três Caminhos, que fica nas Montanhas Cristarrubra.', 'Por ordem da Guarda Real de Ventobravo, todos os gnolls da região de Três Caminhos, na parte sudoeste das Montanhas Cristarrubra, devem morrer.$B$BSe você eliminar os gnolls da região, relate sua vitória para o capitão da guarda Florestan na Torre Vigilante.', '', 'Gnolls de Cristarrubra mortos', '', '', '', '', '', '', '', 'Fale novamente com o Capitão da Guarda Florestan na Torre Vigilante, que fica em Cristarrubra.', 0),
(26505, 'ptBR', 'O relatório de Florestan', 'Entregue o Relatório de Florestan ao Magistrado Salomão em Vila Plácida, que fica em Cristarrubra.', '<O capitão da guarda Florestan entrega um relatório para você.>$B$BAqui está, $n. Leve meu relatório para Vila Plácida, ao norte daqui, e entregue-o para o magistrado Salomão. Diga a ele que precisamos de uma solução mais abrangente para lidar com os gnolls. Sugira que ele mande explosivos. Muitos explosivos.$B$BSe você sabe o que é bom pra saúde, fique na estrada.$B$BAh, e o que é bom pra saúde é ficar vivo. Caso você não saiba... o que é bom pra saúde. Agora você sabe o que é... Ahm. Enfim. Deixa pra lá.', '', '', '', '', '', '', '', '', '', '', 0),
(26506, 'ptBR', 'Salsichão com nozes', 'Colete 4 Olhos de Tarântula, 4 Miúdos de Condor e 4 Rins de Goretusco.', 'Preciso de sua ajuda, $r! Acabaram nossas rações e os guardas estão famintos! Eles estão implorando pelo meu prato mundialmente famoso de salsichão com nozes, mas não tenho ingredientes aqui. Você pode me fazer um favor?$B$BPreciso de alguns rins de goretusco, miúdos de condor e olhos de tarântula. Você vai encontrar goretuscos, condores e tarântulas perto daqui. É só procurar!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Darcy Florestan na Torre Vigilante, que fica em Cristarrubra.', 0),
(26507, 'ptBR', 'Aceita um quebra-queixo?', 'Pegue 12 Morcegos de Pedra Petrificados para o Cascalho.', 'Morcegos petrificados.$B$BOs elementais desse tamanho são exigentes. Você não vai achar nada melhor.$B$BHá basiliscos a leste daqui. Eles transformam em pedra os morcegos que se aproximam demais, e depois se banqueteiam deles quando estão com fome. Há morcegos espalhados por todo o território dos basiliscos.$B$BMas saiba de uma coisa... Se você der muita atenção àquele elementalzinho, não vai conseguir mais se livrar dele. Ele pode ficar muito... carente.', '', '', '', '', '', '', '', '', '', 'Fale com o Cascalho. A última vez que você o viu foi nas Agulhas Tremulantes.', 0),
(26508, 'ptBR', 'Colar da Nida', 'Encontre o Colar da Nida.', 'Minha amiga Nida perdeu o colar, e não conseguimos encontrá-lo. Nós temos pescado aqui o dia todo, e já procuramos por toda a área. O único lugar que falta olhar... é dentro do lago. Nossos pais não querem que a gente entre no lago... A mamãe diz que tem bicho feio na água, mas você não parece ter medo de bicho feio...$B$BVocê pode achar o colar da Nida? Por favor?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nida no Lago Plácido, que fica nas Montanhas Cristarrubra.', 0),
(26509, 'ptBR', 'O penetra', 'Mate Ronquifuça e pegue a Presa de Ronquifuça.', 'Mais uma vez meu jardim foi pisoteado e saqueado. E eu sei quem é o brutamontes que está fazendo isso. É aquele maldito javali que o oficial Marris começou a chamar de Ronquifuça.$B$BVou ter que esperar a próxima estação pra poder plantar meus narcisos de novo... Tudo arruinado! Tudo arruinado por aquele javali maldito. Dê cabo dessa praga! Traga a presa dele pra mim e ficarei feliz em recompensar você. Ele passa o tempo fuçando nos campos a sudoeste de Vila Plácida, mas de vez em quando vem pra cá e faz esse estrago no meu jardim...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Martie Jainrose nas Montanhas Cristarrubra.', 0),
(26510, 'ptBR', 'Devemos nos preparar!', 'Recupere o Gnomofone.', 'A cada dia, mais cidadãos daqui desaparecem. Nós achamos que os gnolls são os responsáveis, mas não temos ideia de pra onde estão levando nossos cidadãos! Se você vai nos ajudar a derrotar os gnolls e encontrar essas pessoas, você tem que estar $gequipado:equipada; de acordo. Infelizmente, não temos mais gnomofones. Sem um gnomofone, não temos como nos comunicar com você em campo.$B$BNosso último gnomofone que prestava foi roubado por murlocs saqueadores semana passada. Você precisa ir até o Lago Plácido, a leste daqui, e recuperá-lo!', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Magistrado Salomão em Vila Plácida, que fica em Cristarrubra.', 0),
(26511, 'ptBR', 'Limpando o Lago Plácido', 'Mate 10 murlocs no Lago Plácido.', 'Você está indo para o Lago Plácido? Então você vai gostar de saber que pusemos a cabeça dos murlocs de lá a prêmio. Mate o máximo de murlocs que puder e você será $grecompensado:recompensada;! Qualquer murloc serve. Tudo o que você precisa fazer é matar indiscriminadamente.$B$BO Lago Plácido fica a leste de Vila Plácida. É um lago. Aquele negócio com água dentro. Parece familiar?', '', 'Murloc do Lago Plácido morto', '', '', '', '', '', '', '', 'Fale novamente com o Meirinho Conacher em Vila Plácida, que fica em Cristarrubra.', 0),
(26512, 'ptBR', 'Sintonizando o gnomofone', 'Vá até o cemitério de Vila Plácida para sintonizar o Gnomofone.', 'O gnomofone parece estar em bom estado. Já está tudo plugado, só falta sintonizar o gnomofone para receber.$B$BSiga para o norte, saindo de Vila Plácida, e tome a estrada que leva ao cemitério. Quando você chegar ao cemitério, vou tentar transmitir.', 'Teste o Gnomofone no Cemitério de Vila Plácida.', '', '', '', '', 'Teste o Gnomofone no Cemitério de Vila Plácida.', '', 'Estou recebendo alto e claro!', 'Magistrado Salomão', '', 0),
(26513, 'ptBR', 'Feito pum no vento', 'Recupere 8 Caixotes de Suprimentos de Cristarrubra.', 'Nós fomos saqueados noite passada. Mas talvez tenha sido na noite retrasada. Não tenho certeza porque já tem três dias que não prego o olho. Já estou alucinando a essa altura.$B$BMas o que importa é que gnolls saquearam nossos estoques e levaram tudo! Sumiram feito pum no vento... Meus soldados os viram correndo de volta pros desfiladeiros a nordeste daqui. Recupere nossos suprimentos, $c!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Oficial Marris em Vila Plácida, que fica nas Montanhas Cristarrubra.', 0),
(26514, 'ptBR', 'Matador na garganta', 'Colete 10 Coleiras de Gnoll de Cristarrubra.', '<O gnomofone zumbe.>$B$BSua primeira tarefa vai ser uma brincadeirinha na Garganta Cristarrubra, diretamente ao norte de Vila Plácida. Mate todos os gnomos que encontrar. Espera, eu disse "gnomo"? Quis dizer "gnoll". Mate todos os GNOLLS que encontrar e pegue as coleiras deles como prova do ato.$B$BE fique de sobreaviso, $n; quando estiver em campo, cuidado com os gorjalas. Meus batedores me informaram da presença de gorjalas enormes e sedentos de sangue vagando pelos cânions ultimamente. Fique longe deles se gosta de viver.$B$BCâmbio e desligo. Vou manter contato.', '', '', '', '', '', '', 'Magistrado Salomão', 'Os gnolls estão alerta!', 'Magistrado Salomão', '', 0),
(26515, 'ptBR', 'A vingança de Ongo\'longo', 'Lute com Ongo\'longo até que ele se liberte.', 'Bolei um plano que vai jogar troll contra troll.$B$BOs Ramatorpe têm um troll hediondo grandalhão trancado em um fosso com umas correntinhas de nada. Eu já vi esses bichos lutando e tenho certeza que aqueles cadarcinhos não vão aguentar de jeito nenhum se o monstrengo ficar furioso!$B$BQuero que você encontre o tal do troll hediondo e meta bronca, $n. Mas não mata ele não... Só dê umas bordoadas até ele ficar vermelho de raiva. Então, deixe ele quebrar as correntes e saia da frente! Ele vai dar um trabalhão para os Ramatorpe.', '', 'Ongo\'longo enfurecido', '', '', '', '', 'Ongo\'longo', '', '', 'Fale novamente com Doran Asadaço em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26516, 'ptBR', 'É nossa agora', 'Mate 5 Bebe-sangue Ramatorpe e 5 Devoradores de Almas Ramatorpe em Jintha\'Alor.', 'Agora só restam os Ramatorpe mais fortes e pérfidos. Os devoradores de almas e os bebe-sangue, adoradores hediondos do deus maligno Hakkar.$B$BNão se esqueça de que você não está enfrentando apenas trolls, $n. São forças das trevas e malignas que transformarão esta terra em cinzas se as deixarmos vivas!$B$BSeja $Gimpiedoso:impiedosa;!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Doran Asadaço em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26517, 'ptBR', 'O cúmulo do destino', 'Recolha 8 Ídolos da Aranha dos Ramatorpe no cume de Jintha\'Alor.', 'Você precisa ir ao cume agora, $n. Nossos guerreiros não querem passar pelos últimos portões. Eles dizem que parece um túmulo: nenhum som, nada respira, nem sinal de movimento.$B$BEles acham que é uma armadilha, mas de acordo com o que você me trouxe, temo que seja algo ainda pior. Vá ao altar, descubra o que aconteceu... e me traga QUALQUER tipo de objeto místico ou ídolo das trevas que encontrar! Ouviu bem?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Explodar Mantrovejante em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26518, 'ptBR', 'Fique alerta', 'Derrote Umboda Três-cabeças e recolha a cabeça dele.', 'Umboda Três-cabeças é um dos maiores trolls das redondezas. Ele é um carniceiro brutal e adora cortar cabeças, tanto de anões como de trolls, para sua coleção! Está na hora de ele ter o que merece.$B$BEncontre o brutamontes nos terraços mais baixos e traga a cabeça dele pra cá!', '', '', '', '', '', '', 'Umboda Três-cabeças', '', '', 'Fale novamente com Doran Asadaço em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26519, 'ptBR', 'Quem controla os gorjalas', 'Mate Ardo Patassuja.', 'Você encontra um documento gnoll. O gnoll que escreveu essa peça de propaganda é semi-analfabeto:$B$BIRMAUMS DE BERRANTE, ESCUTEM PATASSUJA! PATASSUJA GANHO ORBE DUS ORQUE! PATASSUJA CONTROLA US GORJALA! PATASSUJA EZMAGA UMANOS! VENHAUM PEGA PATÓGRAFO DO PATASSUJA NAS CARVENA RETIBANA. CARVENA FICA NO OESTE, ESCONDIDA NO DIZFILADERO!$B$B<A assinatura é uma impressão da pata do gnoll.>$B$B<O pergaminho também parece ter tido um pedaço arrancado a mordida.>$B$BÉ melhor você investigar.', '', '', '', '', '', '', '', '', '', 'Use o Orbe de Controle de Gorjala.', 0),
(26520, 'ptBR', 'Salvando o encarregado Oslow', 'Use o Orbe de Controle de Gorjala para controlar um Gorjala. Então, use o Orbe de Controle de Gorjala no seu Gorjala Subjugado do Desfiladeiro para levantar o Rochedo do Encarregado Oslow em Vila Plácida.', '<Ao tocar no orbe, você escuta um clique suave.>$B$B<Você remove o orbe do pedestal.>$B$BVocê controla o orbe agora e, portanto, controla os gorjalas. Talvez você possa usar um gorjala para remover o grande rochedo que está esmagando o encarregado Oslow em Vila Plácida. Encontre um gorjala e use o orbe nele. Então siga para Vila Plácida.', '', 'Encarregado Oslow salvo', '', '', '', '', 'Gorjala do Desfiladeiro', '', '', 'Apresente-se ao Magistrado Salomão na Vila Plácida, que fica nas Montanhas Cristarrubra.', 0),
(26521, 'ptBR', 'As faces do mal', 'Use a Tocha Tiki para botar fogo em 8 Carrancas em Jintha\'Alor.', 'Os Ramatorpe penduram as carrancas deles em todas as paredes de Jintha\'Alor. Não vamos tolerar os bagateiros hediondos e a magia negra deles.$B$BEstá na hora de enviar uma mensagem e destroçar as defesas de uma vez! Pegue esta tocha, $c. Ponha fogo nas carrancas e veja-as queimar. Eles vão saber que os Martelo Feroz os querem fora daqui quando virem seus ídolos das trevas consumidos!', '', 'Carrancas queimadas', '', '', '', '', '', '', '', 'Fale novamente com Explodar Mantrovejante em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26522, 'ptBR', 'Faces of Evil', 'Use the Tiki Torch to set fire to 8 Tiki Masks at Jintha\'Alor.', 'The Vilebranch have hung their tiki masks all across the walls of Jintha\'Alor. The spirits not gonna be watchin\' over them much longer.$B$BTake this torch with ya as ya fight through the Vilebranch, $c. Set fire to their tiki masks. I\'ll be watchin\' from here as their wards and hexes fade away, an\' their heretical dark voodoo goes up in smoke.', '', 'Tiki Masks Burned', '', '', '', '', '', '', '', 'Return to Kotonga at Jintha\'Alor in The Hinterlands.', 0),
(26523, 'ptBR', 'Tudo que rasteja', 'Recolha 8 Aranitos Espocantes em Jintha\'Alor.', 'Notei uma coisa lá em cima... Jintha\'Alor está cheia de aranhas. Aranhas pequenas do tamanho da mão. Não que isso seja incomum nas Terras Agrestes, mas algo está errado.$B$BPara ser honesto, não confio nos trolls com mascotes. Eles estão aprontando alguma. Preciso que você me traga algumas daquelas aranhas. Tente mantê-las vivas e veremos o que os espíritos me dizem...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Explodar Mantrovejante em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26524, 'ptBR', 'Caldeirões negros', 'Recolha 5 Recipientes com Sangue Maculado em Jintha\'alor.', 'Os trolls Ramatorpe daqui sempre adoraram ao deus hediondo Hakkar, o loa de sangue. Uma entidade doentia e destorcida que quase abriu caminho para o nosso mundo, mas foi derrotada há anos.$B$BOs Ramatorpe ainda remexem os caldeirões malignos, que eles encheram de sangue há anos. Agarrando-se a um espírito morto há tempos ou tramando algo novo tão sinistro quanto.$B$BMe consiga aqueles caldeirões, $n. Precisamos examiná-los juntamente com as aranhas para descobrir exatamente o que está acontecendo aqui!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Explodar Mantrovejante em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26525, 'ptBR', 'Segredos peçonhentos', 'Mate 8 Crias de Shadra.', 'Se o sacrifício já tiver acontecido, a presença de Shadra começará a rastejar para este plano. Aquela caverna já deve estar cheia de filhotes dela.$B$BNão deixe que escapem, $n. Mate todas as aranhas repugnantes que encontrar!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Explodar Mantrovejante em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26526, 'ptBR', 'Caça à guardiã', 'Mate Morta\'gya, a Guardiã, e pegue a Tabuleta de Shadra.', 'Shadra, a aranha loa... A rainha peçonhenta, um espírito das trevas e da morte! Se houve mesmo um sacrifício, eles vão tentar trazer essa criatura vil como uma última tentativa.$B$BE se os Ramatorpe estiverem fazendo rituais, eu não vou deixar eles terminarem de jeito nenhum.$B$BDê uma olhada na caverna atrás do altar, no alto de Jintha\'Alor. É bem capaz que uma das guardiãs de Shadra esteja lá de butuca. Mate a criatura e traga aqui tudo o que ela estiver carregando. Vamos ver se a gente descobre o que está acontecendo.', '', '', '', '', '', '', 'Morta\'gya, a Guardiã', '', '', 'Fale novamente com Explodar Mantrovejante em Jintha\'Alor, que fica nas Terras Agrestes.', 0),
(26528, 'ptBR', 'O olho de Shadra', 'Recupere o Olho de Shadra em Agol\'watha.', 'O mestre-grifos Garra-de-acha me enviou aqui para dar cabo de Shadra, a Rainha Peçonhenta. A conquista de Jintha\'Alor não basta... os trolls podem se reagrupar e evocar essa criatura mais tarde, quando não estivermos esperando.$B$BPrimeiro, vamos recolher os artefatos, trazer Shadra para este mundo da nossa maneira e largar nossos martelos naquela criatura hedionda. Preciso que você ajude a encontrar os artefatos e aproveite para abrir uma ferida no resto dos trolls.$B$BPegue primeiro o Olho de Shadra, guardado em Agol\'watha, ao norte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gilda Chamanuvens no Pavilhão Quel\'Danil, que fica nas Terras Agrestes.', 0),
(26529, 'ptBR', 'A Presa de Shadra', 'Pegue a Presa de Shadra nas Ruínas Assustadoras.', 'Agora, precisamos da Presa de Shadra.$B$BEla está nas Ruínas Assustadoras, a leste, e é guardada pela própria prole de Shadra. Aranhas horrendas do tamanho de um anão e duas vezes mais fortes. O veneno delas é poderoso, $n... não se descuide.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gilda Chamanuvens no Pavilhão Quel\'Danil.', 0),
(26530, 'ptBR', 'A Carapaça de Shadra', 'Mate Qiaga, a Tutora, e pegue a Carapaça de Shadra.', 'Só falta a última peça para extinguir Shadra de uma vez por todas.$B$BA Carapaça de Shadra está com a última alta-sacerdotisa viva do deus aranha, Qiaga, a Tutora. Ela fica no topo do Altar de Zul, guardada pelos outros zelotes fanáticos.$B$BSuba até o topo do altar e elimine-a! A Carapaça está com ela. Traga-a para mim.', '', '', '', '', '', '', 'Qiaga, a Tutora', '', '', 'Fale novamente com Gilda Chamanuvens no Pavilhão Quel\'Danil, que fica nas Terras Agrestes.', 0),
(26531, 'ptBR', 'Evocando Shadra', 'Use o Ídolo de Shadra nos Templos Noroeste, Sudoeste e Leste em Shadra\'Alor.', 'Nossos guerreiros mais fortes estão prontos, o ídolo já foi montado... Chegou a hora, $n.$B$BEscute bem o que vamos fazer: você vai na frente para Shadra\'Alor, levando o ídolo. Quando chegar lá, use ele em todos os três templos. Você vai ter que abrir caminho na marra pelos trolls que protegem o lugar.$B$BCom isso, a Shadra vai aparecer no nosso mundo, e a gente vai estar esperando por ela com todo o ódio dos nossos corações. Fale com os meus rapazes que estão lá assim que você terminar o ritual!', '', 'Templo Noroeste', 'Templo Leste', 'Templo Sudoeste', '', '', '', '', '', 'Fale novamente com o Atalaia Martelo Feroz em Shadra\'Alor, que fica nas Terras Agrestes.', 0),
(26532, 'ptBR', 'Shadra, a Rainha Peçonhenta', 'Mate Shadra, a Rainha Peçonhenta.', 'Não há tempo a perder, $n! Ela está saindo da água neste instante!$B$BO mestre de grifos Garra-de-acha está chegando agora mesmo com os rapazes, vamos fazer esses insetos pagarem!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre de Grifos Garra-de-acha no Ninho da Águia, que fica nas Terras Agrestes.', 0),
(26533, 'ptBR', 'O segredo de Zanzil', 'Obtenha 5 ampolas do Preparado de Zanzil.', 'Há muitos anos atrás, os Gurubashi exilaram um dos seus trolls de Zul\'Gurub. Um troll chamado Zanzil. As razões para isso não são muito claras, mas parece ter a ver com a tendência dele de injetar drogas poderosas para alterar o comportamento de qualquer troll que cruzasse seu caminho. De qualquer modo, os sacerdotes Gurubashi e o deus de sangue que eles seguiam foram mortos há muito tempo, mas Zanzil, o Pária, permanece...$b$b...assim como as drogas poderosas dele.$b$bEu gostaria de ter um pouco delas, $r. Procure nos zumbis ao norte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o M.C. Jasper no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26534, 'ptBR', 'Vamos ver qual é a sua, Zanzil', 'Ofereça o Refresco Selvagem do Jasper para o Gmurgl, para o Orgus e para o Capitão Bartolomeu Barbalisa.', 'Os visitantes do Esconderijo da Chaveforte assinam vários termos de responsabilidade quando chegam, inclusive um que nos permite fazer testes básicos neles. Eu acho que tá na hora de usar esse direito.$b$bPensando melhor, vamos evitar de envenenar nossos clientes por enquanto. Pode ser ruim pros negócios.$b$b<Jasper enche uma jarra com o Preparado de Zanzil e um pouco de gelo picado.>$b$bA torre sudeste do Esconderijo serve como uma prisão temporária. Nós chamamos de "Carandirijo". Enfim, dá um pouco desse refresco pros prisioneiros beberem e me diz o que acontece.', '', 'Gmurgl testado', 'Orgus testado', 'Capitão Bartolomeu Barbalisa testado', '', '', '', '', '', 'Fale novamente com o M.C. Jasper no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26535, 'ptBR', 'Receita de desastre', 'Obtenha a Formulação de Zanzil de um dos seguidores de Zanzil nas Ruínas de Aboraz.', 'Eu preciso da receita do Zanzil, mais do que nunca. Aqueles idiotas seguidores do Zanzil, que ficam nas Ruínas de Aboraz, devem ter a receita. Vá para o leste, para o outro lado do Cabo, e arrume a receita pra mim!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o M.C. Jasper no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26536, 'ptBR', 'Cachoeira do Trovão', 'Pesque 4 Percas-violeta na Cachoeira do Trovão, ao sul de Ventobravo. Em seguida, entregue os peixes para Catarina Gurjão.', 'Já faz muitos anos que Arnoldo e eu pescamos pelas águas de Ventobravo. Esse é mais ou menos o tempo que se leva para encontrar um bom pesqueiro. Um dos meus favoritos se chama Cachoeira do Trovão.$b$bFica a sul de Ventobravo, na Floresta de Elwynn. O melhor da Cachoeira do Trovão é a perca-violeta. Eu nunca vi esses peixes em nenhum outro lugar, apenas naquela queda d\'água. Mas, hoje em dia, caminhar até lá ficou um pouco pesado para mim e o Arnoldo. Você poderia ir até a cachoeira e pescar algumas percas-violeta para nós?', '', '', '', '', '', '', '', '', '', 'Entregue a Perca-Violeta para Catarina Gurjão em Ventobravo.', 0),
(26537, 'ptBR', 'Moedor de pedra', 'Mate 12 troggs de pedra de qualquer tipo no Front Partido.', 'Quero que você vá até lá e acabe com todo mundo.$B$BBerserkers, Rasgaterras, Cavalga-mortes... Não quero nem saber. Só quero que você triture todos os troggs de pedra!', '', 'Troggs de pedra no Front Partido mortos', '', '', '', '', '', '', '', 'Fale novamente com Seixo Lajegrande no Front Partido, que fica no Geodomo.', 0),
(26538, 'ptBR', 'S.O.S. emergência', 'Procure um Curandeiro no Porto Presa do Dragão, próximo à orla.', 'Muitos de nossos guerreiros não sobreviveram ao ataque do Crepúsculo à nossa força aérea. Aqueles que conseguiram estão nadando em direção aos vestígios da frota, sangrando e com queimaduras. Preciso de apoio da orla para manter meus homens vivos!$B$BDeve haver algum tipo de médico ou curandeiro no Porto Presa do Dragão disposto a ajudar seus companheiros orcs necessitados. Vá até lá e veja se consegue suprimentos médicos para a frota!', '', 'Curandeiro persuadido', '', '', '', '', '', '', '', 'Fale novamente com Gregor no Porto Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(26539, 'ptBR', 'Negociações estagnadas', 'Fale com Ornak no Porto Presa do Dragão. Horzog providenciará transporte rápido para o litoral.', 'O paradeiro do Chefe Guerreiro é desconhecido! Mas devemos manter o plano dele em ação. Você parece ser do tipo que dá um jeito nas coisas, $n.$B$BNossas negociações com os Presa do Dragão estagnaram. O Chefe Guerreiro deles... não é o que esperávamos. Vá e faça com que as negociações retornem ao seu rumo.$B$BEncontre Ornak na costa, ele vai lhe explicar os detalhes.$B$BFale com Horzog aqui no convés para conseguir transporte rápido para a costa.', '', '', '', '', '', '', '', '', '', 'Fale com Ornak no Porto Presa do Dragão. Horzog providenciará transporte rápido para o litoral.', 0),
(26540, 'ptBR', 'Compaixão perigosa', 'Leve o Caixote de Bandagens dos Presa do Dragão de volta para o Senhor da Guerra Krogg no Porto Presa do Dragão.', 'A revoada dragônica vermelha representa o aspecto da vida. Como tal, seu sangue tem propriedades de cura.$B$BEste caixote de curativos foi encharcado com sangue de dragão vermelho. É meu último suprimento. Que ele traga rápida recuperação a seus guerreiros.$B$BSeja qual for o resultado das suas negociações por aqui, não se esqueça de que você tem amigos entre os Presa do Dragão.', '', '', '', '', '', '', '', '', '', 'Leve o Caixote de Bandagens dos Presa do Dragão de volta para o Senhor da Guerra Krogg no Porto Presa do Dragão.', 0),
(26542, 'ptBR', 'O chamado ao heroísmo: Terras Agrestes!', 'Vá ao Ninho da Águia nas Terras Agrestes e fale com o Mestre de Grifos Garra-de-acha.', 'Por ordem de sua majestade o rei Varian Wrynn, todos os cidadãos da Aliança em bom estado físico devem apresentar-se ao mestre de grifos Garra-de-acha no aviário, que fica no Ninho da Águia.$B$BNossos novos irmãos da Aliança precisam de ajuda para rechaçar a ofensiva da Horda na tão amada terra natal deles. Siga para o norte partindo do Planalto Arathi, através do desfiladeiro dos anões, e siga a estrada a noroeste até o Ninho da Águia.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(26543, 'ptBR', 'Mão melada', 'Colete 10 nacos de Carne de Marisco Monstruoso dos mariscos perto da costa leste, ao sul de Orgrimmar. Fale novamente com Razgar quando terminar.', 'Nada é tão gostoso quanto carne de marisco monstruoso, $n. Tenho estado ocupado trabalhando nas últimas semanas e não pude ir catar mariscos. Você poderia ir lá onde eles nascem e catar alguns pra mim?$b$bVocê vai encontrar os mariscos perto da costa leste de Durotar. Deve ter bastante perto das docas de Orgrimmar.', '', '', '', '', '', '', '', '', '', 'Entregue a Carne de Marisco Monstruoso para Razgar em Orgrimmar.', 0),
(26544, 'ptBR', 'Caiu a ficha', 'Recupere a Missiva Orc de Rocha Negra.', '<O gnomofone estala e chia.>$B$BParece que finalmente a ficha caiu para os orcs Rocha Negra. Recebi relatórios de que eles estariam unindo forças com os gnolls e já planejando um ataque. Preciso de detalhes, $n!$B$BPreciso que você investigue as Cavernas Retibanas, localizadas na região oeste da Garganta Cristarrubra. Procure os orcs de pele escura. Mate todos que encontrar e reviste os corpos à procura de informações.$B$BCâmbio e desligo.', '', '', '', '', '', '', 'Magistrado Salomão', 'Salomão: Fluente em órquico.', 'Magistrado Salomão', 'Apresente-se ao Magistrado Salomão na Vila Plácida, que fica nas Montanhas Cristarrubra.', 0),
(26545, 'ptBR', 'Berrante tem que morrer!', 'Mate Berrante e recupere o Plano de Invasão dos Rocha Negra.', '<O gnomofone zumbe.>$B$BVocê precisa encontrar o Berrante, $n. Ele deve estar perto da região mais ao norte, na Garganta Cristarrubra. Mate o vira-lata e vasculhe o cadáver. Encontre os planos de invasão dos Rocha Negra. Se tiver sucesso, traga os planos para mim. Estarei na prefeitura de Vila Plácida.$B$BCâmbio e desligo.', '', '', '', '', '', '', 'Berrante', '', '', 'Apresente-se ao Magistrado Salomão na Vila Plácida, que fica nas Montanhas Cristarrubra.', 0),
(26546, 'ptBR', 'Amigos dos bicavalha', 'Use a Comida de Grifo para alimentar 7 grifos Bicavalha Adestrados.', 'Nosso clã reverencia o grifo como um animal sagrado. São criaturas majestosas dos céus e mais do que meros animais, elas são inteligentes e astutas.$B$BAlguns dizem que nós as possuímos, mas está mais para amizade. Se quiser fazer amizade com os Martelo Feroz aqui, faça amizade com nossos grifos primeiro! Pegue este saco de comida, está fresca e apetitosa. Nossos grifos bicavalha adestrados vagam pelas florestas ao sul do aviário. Vá em frente e alimente alguns para mim, sim?', '', 'Bicavalha Adestrado alimentado', '', '', '', '', '', '', '', 'Fale novamente com o Mestre de Grifos Garra-de-acha no Ninho da Águia, que fica nas Terras Agrestes.', 0),
(26547, 'ptBR', 'Uma ameaça sarnenta', 'Mate 8 Jubapratas Sarnentos.', 'Nós fazemos de tudo para proteger nossa raça e nossos grifos. Isso inclui espantar os predadores, sejam eles da floresta ou da Horda.$B$BPor enquanto, não vou pedir para você nos salvar de monstros de duas pernas. Jubapratas sarnentos rondam a mata ao sul, onde nossos grifos pastam, e sabemos que eles os abocanham quando voam baixo demais. Cace alguns dos jubapratas e deixe claro para eles que nossos grifos não são comida.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre de Grifos Garra-de-acha no Ninho da Águia, que fica nas Terras Agrestes.', 0),
(26548, 'ptBR', 'Rumo ao fronte', 'Fale com Kerr Aço-de-mira no Posto Avançado Penafúria.', 'Precisamos de sua ajuda com algo mais premente, $n.$B$BA Horda está ganhando moral por aqui. Eles penetraram o nosso território e começam a nos atacar abertamente. Os trolls Revatusco da floresta estão atacando o Posto Avançado Penafúria em plena luz do dia!$B$BPreciso de sua ajuda. Fale com Guthrum Punhostrondo lá fora. Ele $go:a; colocará em um grifo para o Posto Avançado Penafúria. Kerr Aço-de-mira vai deixá-$Glo:la; a par da situação quando você chegar lá.', '', '', '', '', '', '', '', '', '', '', 0),
(26549, 'ptBR', 'Loucura, loucura, loucuuuura!', 'Escolte o Negociador da Horda até o salão principal do Porto Presa do Dragão para encontrar o Chefe Guerreiro Mor\'ghor dos Presa do Dragão. Fale com Ornak na costa se você se perder do Negociador.', 'Nossos dois últimos negociadores não voltaram da conversa com o Chefe Guerreiro Presa do Dragão. Acho que teremos que exercitar um pouco os músculos.$B$BDesta vez quero que VOCÊ acompanhe o negociador. O Chefe Guerreiro deles pode pensar duas vezes quando perceber que a Horda está cheia de $Gheróis bons:heroínas boas; de briga como você.$B$BBasta escoltar nosso negociador ao forte principal no meio do Porto Presa do Dragão e parecer $gameaçador:ameaçadora;.', '', 'Negociações concluídas', '', '', '', '', '', '', '', 'Fale com Zaela no Porto Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(26550, 'ptBR', 'Negócios obscuros', 'Coloque o Incenso de Gurubashi em frente ao Totem de Hir\'eek. Em seguida, escute o plano de Zanzil.', 'Zanzil, o Pária, um exilado da tribo Gurubashi, é o meu alvo. Tenho ouvido boatos recentes dos meus irmãos do norte sobre os planos de Zanzil de reintegrar-se à sociedade, começando pelo emissário que ele enviou para os Rachacrânio. Essas não são boas notícias.$b$bEu quero que você descubra os planos atuais de Zanzil. Pegue esse incenso e coloque-o em frente ao totem do morcego nas Ruínas de Jubuwal, ao leste daqui. Hir\'eek irá guiá-$Glo:la; de lá.', '', 'Coloque o Incenso em frente ao Totem de Hir\'eek', 'Espione Zanzil', '', '', '', '', '', '', 'Fale novamente com Chabal no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26551, 'ptBR', 'Eliminando o pária', 'Vá para as Ruínas de Aboraz no Cabo do Espinhaço e mate Zanzil, o Pária.', 'Você deve matar Zanzil. Você voou nas asas de Hir\'eek e viu através dos olhos de Hir\'eek; você sabe onde Zanzil se esconde, dentro das Ruínas de Aboraz. Vá até lá e mate-o.$b$bMais uma coisa, $r: se nos separarmos, use esse fetiche. Ele só funciona no Espinhaço, mas trará você de volta para cá em caso de emergência.$b$bBoa sorte, $r. Zanzil não é um adversário qualquer.', '', '', '', '', '', '', 'Zanzil, o Pária', 'Para onde ele foi?', 'Zanzil, o Pária', '', 0),
(26552, 'ptBR', 'Pelo buraco do troll', 'Use o Portal de Zanzil para entrar em Zul\'Gurub.$b$bSe você se perder ou precisar voltar para Zul\'Gurub, fale com Chabal no Esconderijo da Chaveforte.', 'Parece que o portal de Zanzil para Zul\'Gurub ainda está aberto. Zul\'Gurub é um local perigoso, mas Chabal confiou essa tarefa a você.$b$bO portal está na sua frente.', '', 'Atravesse o Portal de Zanzil', '', '', '', '', '', '', '', '', 0),
(26553, 'ptBR', 'Alta-sacerdotisa Jeklik', 'Destrua o corpo da Alta-sacerdotisa Jeklik antes que Zanzil consiga ressuscitá-la.$b$bSe você se perder ou precisar voltar para Zul\'Gurub, fale com Chabal no Esconderijo da Chaveforte.', 'À sua frente está a rampa para um dos muitos terraços da cidade. Os totens em forma de morcego indicam que esse é o domínio da alta-sacerdotisa Jeklik, uma seguidora de Hir\'eek.$b$bJeklik foi uma das sacerdotisas adoradoras de Hakkar que Zanzil planejava ressuscitar. Talvez, se você se apressar, ainda possa impedir a ressurreição!', '', 'Destrua o corpo da Alta-sacerdotisa Jeklik', '', '', '', '', 'Alta-sacerdotisa Jeklik', '', '', '', 0),
(26554, 'ptBR', 'Cada vez mais fundo em Zul\'Gurub', 'Atravesse o Portal de Zanzil.$b$bSe você se perder ou precisar voltar para Zul\'Gurub, fale com Chabal no Esconderijo da Chaveforte.', 'Zanzil, o Pária, escapou mais uma vez por um de seus portais. Siga-o!', '', 'Atravesse o Portal de Zanzil', '', '', '', '', '', '', '', '', 0),
(26555, 'ptBR', 'Sumo Sacerdote Venoxis', 'Mate Zanzil, o Pária, e o Sumo Sacerdote Venoxis.$b$bSe você se perder ou precisar voltar para Zul\'Gurub, fale com Chabal no Esconderijo da Chaveforte.', 'Venoxis era o segundo dos dois sacerdotes que Zanzil planejava ressuscitar. Você já conseguiu destruir o corpo da alta-sacerdotisa Jeklik... Venoxis deve ser o próximo.', '', 'Mate o Sumo Sacerdote Venoxis.', '', '', '', '', 'Sumo Sacerdote Venoxis', '', '', 'Fale novamente com Chabal no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26556, 'ptBR', 'Jogue o lixo no lixo', 'Pesque 6 Brejeiros Tóxicos e entregue-os para Razgar no Vale da Honra ao completar a missão.', 'Desde que os goblins se refugiaram em Orgrimmar, eles vêm jogando lixo em nosso reservatório de água.$b$bNão faço ideia do efeito que isso está causando em nossos cardumes, mas não pode ser bom. Ouvi falar que uma espécie mutante de peixe surgiu perto da lagoa tóxica próxima ao acampamento goblin. Alguns espécimes me ajudariam a entender o que está acontecendo.$b$bPode me ajudar?', '', '', '', '', '', '', '', '', '', 'Entregue os Brejeiros Tóxicos para Razgar em Orgrimmar.', 0),
(26557, 'ptBR', 'Um esforço laborioso', 'Mate um Cervo ao norte de Orgrimmar e use o olho como isca para pescar uma Carpa Arenosa no Vale da Sabedoria. Fale novamente com Razgar no Vale da Honra ao completar a missão.', 'Já pesco carpas arenosas nas águas de Orgrimmar há anos. Recentemente, notei que minhas iscas já não funcionam tão bem quanto antes. Suspeito que isso tenha alguma coisa a ver com os taurens que vieram pro Vale da Sabedoria.$b$bEu falei com um dos pescadores tauren e ele me disse que o apetite dos peixes mudou. Agora eles querem olhos de cervo. Dá pra encontrar muitos cervos ao norte de Orgrimmar, do lado de fora do portão norte.', '', '', '', '', '', '', '', '', '', 'Entregue a Carpa Arenosa para Razgar em Orgrimmar.', 0),
(26558, 'ptBR', 'Evocando Shadra', 'Use o Ídolo de Shadra nos Templos Noroeste, Sudoeste e Leste em Shadra\'Alor.', 'O ídolo está pronto, $n. Espero que você também esteja.$B$BVocê deverá seguir para Shadra\'Alor, que fica a sudoeste daqui, antes de nós, levando o ídolo. Chegando lá, use-o em todos os três templos.$B$BFeito isso, Shadra se materializará neste mundo. Os sicários e eu chegaremos logo em seguida para dominar e ceifar o cadáver de Shadra. Fale com o atalaia que eu já enviei para lá assim que terminar, e aguarde a minha chegada.', '', 'Templo Noroeste', 'Templo Leste', 'Templo Sudoeste', '', '', '', '', '', 'Fale novamente com o Atalaia Sicário em Shadra\'Alor, que fica nas Terras Agrestes.', 0),
(26560, 'ptBR', 'Jorgensen', 'Recupere a Chave da Jaula de Jorgensen.', 'Não sei onde Krakauer e Danforth estão, mas Jorgensen estava no Acampamento dos Laceradores, a nordeste daqui. Eu estava na mesma jaula imunda com ele antes de me levarem para a Serraria Alther.$B$BVamos precisar da chave para tirá-lo de lá. Uma bruxa sinistra do inferno chamada Utroka, a Senhora das Chaves, não se separa um segundo dessa chave. Vamos ter que matá-la para conseguir a chave da jaula de Jorgensen. Ela fica a norte daqui, no vale que leva às Estepes Ardentes.$B$BVamos lá, $ggaroto:moça;.', '', '', '', '', '', '', '', '', '', 'Encontre Jorgensen no Acampamento dos Laceradores, que fica em Cristarrubra.', 0),
(26561, 'ptBR', 'Krakauer', 'Mate o Ritualista Tarak.', 'Krakauer está com a cabeça por um fio nesse exato instante! Os orcs trouxeram um mandingueiro Gurubashi para realizar um ritual de magia negra com ele. Teremos que matar o troll para libertar Krakauer!$B$BVamos! Ele está dentro dessa caverna. Dobre à direita no primeiro entroncamento.', '', '', '', '', '', '', '', '', '', 'Fale com Krakauer na Rocha dos Laceradores, que fica em Cristarrubra.', 0),
(26562, 'ptBR', 'E, por último, mas não menos importante... Danforth', 'Mate o Suserano Barbarius e recupere a Chave da Alavanca de Rocha Negra. Use a Chave da Alavanca de Rocha Negra para libertar Danforth.', 'Danforth está sendo torturado no outro lado da caverna. Não temos como saber em que estado ele se encontra! Precisamos ir até lá e salvá-lo!$B$BO suserano Barbarius tem a chave da manivela que mantém Danforth suspenso. Se trabalharmos em equipe, poderemos matar Barbarius, aquele pulha. Quando Barbarius morrer, nós usamos a chave para descer Danforth, e daí damos o fora daqui!$B$B$gPronto:Pronta;?', '', '', '', '', '', '', '', '', '', '', 0),
(26563, 'ptBR', 'A volta da Companhia Bravo', 'Fale novamente com o Coronel Troteman em Vila Plácida, que fica em Cristarrubra.', 'Não sei quem é você, $gmoço:moça;, mas você acaba de conquistar o respeito e a admiração da Companhia Bravo. Você conseguiu salvar nosso couro e ainda matou uma penca de orcs! Agora é nossa vez de retribuir.$B$BVolte para Vila Plácida e apresente-se ao Coronel Troteman. Vamos encontrar nosso Johnny e dar a boa notícia pessoalmente. Com a Companhia Bravo de volta à ativa, esses orcs não têm nenhuma chance.', '', '', '', '', '', '', '', '', '', '', 0),
(26564, 'ptBR', 'Peças sobressalentes', 'Recolha 6 Peças de Catapulta.', '<O riso irônico de Árgilos soa como um esfregar de pedra contra pedra.>$B$BEles destruíram todas as nossas catapultas. Estou tentando consertar esta aqui, mas até agora não consegui.$B$BVocê está querendo ajudar? Vá até o front e recolha todas as peças sobressalentes que encontrar.$B$BVocê acha que dá conta do recado, saco de carne?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Árgilos Venalama no Front Partido, que fica no Geodomo.', 0),
(26565, 'ptBR', 'A Furious Catch (REMOVED)', 'Catch a Furious Pike in the Southfury River. The Southfury River can be found just outside Orgrimmar\'s western gate. Return to Razgar in the Valley of Honor once you are done.', 'Are you up for a challenge, $n? Good, I was hoping you would be. The southfury river flows just west of Orgrimmar and your challenge can be found within it\'s mighty flow.$b$bWe are looking for a furious pike. This mighty fish used to be prevalent in these areas but ever since the floods hit, they have been much harder to find. Head out to the river and let\'s see just how good of an angler you really are.', '', '', '', '', '', '', '', '', '', 'Deliver the Furious Pike to Razgar in Orgrimmar.', 0),
(26566, 'ptBR', 'O triunfo da inventividade gnômica', 'Fale com o Engenheiro Fagulhamola na Vila da Gambiarra.', 'Vamos precisar de todas as armas, todas as invenções e todos os soldados que pudermos reunir para derrotar Razlo Esmagrenagem e seus asseclas.$B$BO engenheiro Fagulhamola é um dos expoentes da nova geração de mentes gnômicas brilhantes. Por quê? Ora, porque ele não provocou nenhuma explosão em três protótipos!$B$BMas chega de falatório. O engenheiro Fagulhamola está trabalhando em um robô que supostamente vai ajudar a limpar a base aérea de qualquer contaminação. Você deveria se apresentar a ele, que está a nordeste daqui, e oferecer ajuda para testar o autômato.', '', '', '', '', '', '', '', '', '', 'Fale com o Engenheiro Fagulhamola na Vila da Gambiarra.', 0),
(26567, 'ptBR', 'John J. Keeshan', 'Consiga a ajuda de John J. Keeshan na Taberna de Vila Plácida, que fica em Vila Plácida.', 'Já ouviu falar de John Keeshan, $n? Eu fui oficial comandante dele nas três grandes guerras. Ninguém conseguiu matar mais orcs do que ele. Se alguém pode impedir a invasão dos Rocha Negra, é John Keeshan. Precisamos convencê-lo a nos ajudar, ou Vila Plácida vai virar um monte de entulho e cinzas quando o exército Rocha Negra passar a caminho de Elwynn.$B$BOuvi dizer que ele estava lutando no clube da luta no porão na taberna de Vila Plácida. Encontre-o e informe a ele tudo o que você descobriu.', '', '', '', '', '', '', '', '', '', '', 0),
(26568, 'ptBR', 'Essa guerra não é minha', 'Fale novamente com o Coronel Troteman.', 'Eles me pediram para lutar naquelas guerras. Não fui eu quem pediu! Eu fiz o que tinha de fazer pra vencer. E então fui capturado por aqueles orcs imundos, aqueles vermes beberrões, e, por cinco anos, eles me usaram de latrina. Quando eu finalmente consegui escapar e voltei pra minha cidade, adivinha só o que me esperava? Pessoas cuspindo em mim, protestando, me chamando de matador de bebê orc, todo tipo de calúnia nojenta!$B$BNão, acho que não vou ajudar você. Volte lá e fale pro Troteman que essa guerra não é minha.', '', '', '', '', '', '', '', '', '', '', 0),
(26569, 'ptBR', 'Aparelhagem de levantamento', 'Recupere 5 Telescópios de Rocha Negra.', 'Ah, $gmeu salvador:minha salvadora;! Ouvi dizer que você está numa missão para salvar Vila Plácida... e minha ponte. Pois é, trabalhei tempo demais nela pra deixar que seja destruída por um exército de orcs saqueadores!$B$BEscute, se você estiver indo para o norte, na direção do Acampamento dos Laceradores, poderia me ajudar e arranjar alguns telescópios dos mateiros Rocha Negra de lá? Eu poderia fazer bom uso delas em minha nova aparelhagem de levantamento.', '', '', '', '', '', '', '', '', '', 'Fale novamente com encarregado Oslow nas Montanhas Cristarrubra.', 0),
(26570, 'ptBR', 'O exército dos laceradores', 'Mate 25 orcs Rocha Negra na Serraria Alther ou no Acampamento dos Laceradores.', 'Vocês estão indo para o norte? Que tal você fazer uma guerrinha contra os monstros Rocha Negra? Que tal, $n?$B$BMate todo orc Rocha Negra que você vir na Serraria Alther ou no Acampamento dos Laceradores. Mate até que sua pele fique vermelha com o sangue deles. Então volte a falar comigo e eu $go:a; recompensarei generosamente.$B$BIsso não vai deter a invasão Rocha Negra, mas vai atrasar um pouco os planos deles.', '', 'Orcs da Serraria Alther ou do Acampamento dos Laceradores mortos', '', '', '', '', '', '', '', 'Fale novamente com o Oficial Marris em Vila Plácida, que fica nas Montanhas Cristarrubra.', 0),
(26571, 'ptBR', 'Armas de guerra', 'Recupere a Faca de Sobrevivência de Keeshan e o Arco de Keeshan.', 'O que estou prestes a pedir não vai ser fácil de fazer, $n. Keeshan deixou tudo lá na prisão orc, e não estou falando da alma ou da vontade de viver.$B$BSe quisermos que nosso Johnny fique pronto pra guerra, vamos precisar recuperar os pertences dele. Os orcs estão de posse do arco e da faca de sobrevivência de Keeshan.$B$BVá para a Serraria Alther, a leste daqui, e encontre os dois tenentes orc, Murdunk e Homurk. Foram eles que pegaram o equipamento de Keeshan. Traga tudo de volta.$B$BVou manter contato pelo gnomofone.', '', '', '', '', '', '', '', 'Se vai mandar todo esse pessoal, é melhor não se esquecer de uma coisa. Um bom suprimento de sacos pra cadáveres.', 'Coronel Troteman', 'Fale novamente com o Coronel Troteman em Vila Plácida, que fica nas Montanhas Cristarrubra.', 0),
(26572, 'ptBR', 'Oportunidade de ouro', 'Use a Faca Filetadora de Razgar para cortar um Rabo de Lagarto Trovejante Afogado no Desfiladeiro do Trovão, ao sul de Orgrimmar. Use a cauda para matar um Peixe-pedra Dourado. Fale novamente com Razgar no Vale da Honra ao completar a missão.', 'Já ouviu falar do peixe-pedra dourado, $n? Não dá pra pegar esse peixe pelos meios normais. As mandíbulas deles são tão fortes que arrebentam qualquer anzol ou armadilha que a gente tentar usar neles.$b$bDá pra achar muitos no Desfiladeiro do Trovão, ao sul de Orgrimmar. O desfiladeiro costumava estar repleto de lagartos trovejantes, mas todos se afogaram na enchente.$b$bLeve minha faca, nade até lá embaixo e arranque a cauda deles. Use a cauda para sapecar os peixes-pedra que você encontrar.', '', '', '', '', '', '', '', '', '', 'Entregue o Peixe-pedra Dourado para Razgar em Orgrimmar.', 0),
(26573, 'ptBR', 'Motivos para lutar', 'Recupere a Bandana Vermelha de Keeshan e o Amuleto de Jade de Keeshan.', '<O gnomofone dá um clique.>$B$BSó o equipamento não basta, $n. Ele precisa lembrar que tem motivos para lutar. Pra isso, vamos precisar de alguns itens de valor sentimental. Os orcs Rocha Negra do Acampamento dos Laceradores, ao norte, estão de posse de dois itens que pertencem ao Keeshan.$B$BSiga para lá e vasculhe os cofres deles. Quero que você encontre a bandana vermelha de Keeshan e um amuleto de jade que a esposa deixou pra ele. Ela foi brutalmente assassinada durante uma invasão dos Rocha Negra.$B$BTraga esses itens para mim.', '', '', '', '', '', '', 'Coronel Troteman', '', '', 'Fale novamente com o Coronel Troteman em Vila Plácida, que fica nas Montanhas Cristarrubra.', 0),
(26574, 'ptBR', 'O acampamento secreto de Adella', 'Fale com Adella no Ramo Sombrio, que fica em Feralas.', 'Lady Shandris já lhe pediu para nos ajudar mais um pouco.$B$BAdella dirigiu-se para o leste, entre os gnolls Patábua, e montou um acampamento ao sul da Aldeia Mojache. Você deve apresentar-se a ela se deseja ajudar lady Shandris e a Aliança.$B$BNão chegue muito perto da Aldeia Mojache... A Horda não hesitará em atacá-$Glo:la;. Siga para o sul e fique $gatento:atenta; aos nossos estandartes.', '', '', '', '', '', '', '', '', '', '', 0),
(26575, 'ptBR', 'Basilisco abusado', 'Mate o Gorgonita.', 'Tenho mais um favor a lhe pedir, criatura de carne.$B$BUm dos basiliscos é muito maior e mais velho do que os outros. Normalmente não temos medo daquelas criaturas, mas este em questão se tornou tão poderoso a ponto de petrificar alguns de meus filhos. Não podemos permitir isso.$B$BProcure o Gorgonita a leste daqui e mate-o. Ele já viveu muito mais do que o necessário.', '', '', '', '', '', '', 'Gorgonita', '', '', 'Fale novamente com Kor, o Inamovível, nas Agulhas Tremulantes, que ficam no Geodomo.', 0),
(26576, 'ptBR', 'Mãos firmes', 'Fale com Terrath, o Estável, no Alcândor Pálido.', 'Perto daqui, a norte, encontra-se Terrath, o Estável. Ele tomou para si a tarefa de mandar os dragões de pedra de volta para onde vieram. De século em século, nós passamos pela mesma provação... Os dragões de pedra são imprevisíveis, e só se curvam perante força bruta.$B$BTerrath é equilibrado e justo, mas os objetivos que ele busca não são fáceis. Procure-o. Apele para o lado mais equilibrado da Petramáter.', '', '', '', '', '', '', '', '', '', '', 0),
(26577, 'ptBR', 'Rocha dura de roer', 'Fale com Gorsik, o Turbulento, no alto da Vastidão Carmesim.', 'A leste daqui, na Vastidão Carmesim, você encontrará o Gorsik. Ele é a materialização do que há de mais instável e violento na nossa espécie. Ele não é amistoso, tampouco ingênuo, mas a palavra dele tem peso.$B$BProvar seu valor para Gorsik $Go:a; ajudará em muito a conquistar a confiança da Petramáter.', '', '', '', '', '', '', '', '', '', '', 0),
(26578, 'ptBR', 'Cogumalos', 'Destrua 10 Cogumalos.', 'A fenda para o seu mundo deixou a nossa terra natal envenenada. Corrompida. Poluída.$B$BÉ uma pústula que não para de crescer. Está difícil até mesmo de ver a pureza das rochas por trás de tanta imundície.$B$BSe você veio aqui para nos prestar ajuda, acabe com esse crescimento descontrolado. Procure os cogumelos cintilantes que crescem mais do que os outros. Eles são os piores.', '', 'Cogumalos destruídos', '', '', '', '', '', '', '', 'Fale novamente com Gorsik, o Turbulento, na Vastidão Carmesim.', 0),
(26579, 'ptBR', 'Eles não são mais os mesmos', 'Mate 8 Beemotes Fúngicos.', 'Os beemotes fúngicos das redondezas sucumbiram a uma fraqueza muito parecida com a que aflige a sua espécie. A pele deles amoleceu. Eles não são mais seres da rocha.$B$BMate-os. Queremos evitar que a infecção se propague.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gorsik, o Turbulento, na Vastidão Carmesim.', 0),
(26580, 'ptBR', 'Inimigos íntimos', 'Fale com as "criaturas de carne" intrusas na Vastidão Carmesim.', 'Criatura de carne. Alguns dos seus deslizam por entre as rochas. Covardes demais para se aproximarem, rápidos demais para serem esmagados.$B$BSe você quiser ganhar minha confiança, acabe com eles. Esses jogos me cansam.', '', '', '', '', '', '', '', '', '', '', 0),
(26581, 'ptBR', 'Cabeça de vento', 'Monte no demonéolo de Lorvarius e colete uma amostra de bruma vermelha perto da água, na Vastidão Carmesim. Em seguida, fale novamente com Lorvarius.', 'Não sou nenhum druida, mas acho que esses cogumelos não nasceram naturalmente. Sei que o nosso amigo Senhor da Pedra ali anseia por culpar a exposição a Azeroth, mas eu suspeito que a causa seja doméstica.$B$BPercebi a formação de algumas nuvens de bruma vermelha a noroeste daqui, à beira d\'água. Elas pareciam estimular o crescimento conforme se deslocavam. Monta em um dos meus demonéolos e pega uma amostra dessas nuvens para mim. Talvez tu precises ficar perto do chão para enxergares a bruma.', '', 'Colete uma amostra da bruma vermelha', '', '', '', '', '', '', '', 'Entregue a amostra para o Voz dos Ventos Lorvarius na Vastidão Carmesim.', 0),
(26582, 'ptBR', 'Causas não naturais', 'Fale com Gorsik, o Turbulento, na Vastidão Carmesim.', 'Tenho certeza que isso tem origem mágica. E não é druídica. Estou suspeitando de um dos troggs de pedra que vivem a norte daqui.$B$BFale com Gorsik sobre esse trogg. Espero que isso te seja útil para conquistares a confiança dele.', '', '', '', '', '', '', '', '', '', '', 0),
(26583, 'ptBR', 'A ira do fungimante', 'Fale com a Reparadora da Terra Norsala. Em seguida, mate o Fungimante Glop.', 'O líder deles se esconde em uma toca mais à frente. Ele é o responsável por trazer a peste à Vastidão Carmesim.$B$BEle tem que morrer.$B$BUma de nossas companheiras da Harmonia Telúrica já está na caverna. Você deveria falar com ela.', '', 'Falar com a Reparadora da Terra Norsala', '', '', '', '', 'Fungimante Glop', '', '', 'Fale novamente com Ruberick na parte inferior do Posto Verlok.', 0),
(26584, 'ptBR', 'Batido e mexido', 'Mate 8 Verloks Demolidores do Pilar na parte inferior do Posto Verlok.', 'Eu mandei meus irmãos atacarem a Aldeia Verlok por baixo. Com isso, os Verlok subirão todos para as plataformas do penhasco, como costumam fazer para escapar da nossa ira. Então, faremos com que a terra trema até que caiam aos nossos pés.$B$BNeste momento você provará seu valor. Certifique-se de que não se levantem mais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gorsik, o Turbulento, na Vastidão Carmesim.', 0),
(26585, 'ptBR', 'A semente do mal', 'Pegue 8 sacos de Crescimento Miraculoso dos Verlok.', 'Se este crescimento repulsivo tiver realmente sido espalhado pelos Verlok, então o material usado para tal ainda deve estar na aldeia deles, que fica a norte daqui. Traga-me as provisões dos Verlok para que eu possa comprovar a sua alegação.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gorsik, o Turbulento, na Vastidão Carmesim.', 0),
(26586, 'ptBR', 'À procura da Companhia Bravo', 'Procure pelos membros da Companhia Bravo na Serraria Alther.', 'Vamos precisar encontrar o antigo batalhão de Keeshan se quisermos que ele ajude você a defender Vila Plácida. A última notícia que obtive deles é que todos haviam sido capturados pelos orcs: Messner, Jorgensen, Krakauer e Danforth. Não sei onde eles estão, nem sequer se estão vivos, mas quero ser mico de circo se não vou mandar você procurar por eles.$B$BVasculhe a Serraria Alther, a leste daqui. Talvez haja pistas lá.', '', '', '', '', '', '', '', '', '', '', 0),
(26587, 'ptBR', 'Escapar não é fácil', 'Recupere a Chave da Jaula de Messner.', 'A chave dessa jaula fica numa bolsa lá no covil dos worgs, a norte daqui. O problema é que a bolsa está protegida e segura em cima de um toco de árvore cercado por worgs homicidas sedentos de sangue.$B$BVocê só tem uma chance de pegar a chave sem acordar os worgs. Vá lá e ache um caminho até o meio do covil dos worgs. Pise com cuidado e fique de olho no capitão dos worgs da Rocha Negra. Pegue a chave e volte aqui.$B$BSe você tem alguma mascote, recomendo que mande ela ficar pra trás!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Messner na Serraria Alther, que fica em Cristarrubra.', 0),
(26588, 'ptBR', 'Pesca furiosa', 'Pesque um Lúcio Gigante Furioso no Rio Furiaustral. O Rio Furiaustral fica perto do portão ocidental de Orgrimmar. Fale novamente com Razgar no Vale da Honra quando completar a missão.', 'Está $gpronto:pronta; para um desafio, $n? Muito bom. O rio Furiaustral corre a oeste de Orgrimmar e o seu desafio está lá, esperando por você.$b$bEstamos procurando por um lúcio gigante furioso. Esse belo peixe costumava ser abundante nessa área, mas, desde as enchentes, tem se tornado muito mais difícil de se achar. Siga para o rio e vamos ver se você é $gum bom pescador:uma boa pescadora; mesmo.', '', '', '', '', '', '', '', '', '', 'Entregue o Lúcio Gigante Furioso para Razgar em Orgrimmar.', 0),
(26589, 'ptBR', 'As selvas de Feralas', 'Vá até Feralas e fale com Konu Runa Totem na Aldeia Ataya.', 'Você é muito $Gcorajoso:corajosa; por nos ajudar a proteger estas terras, $Gcaro herói:cara heroína;. Caso deseje fazer algo mais pela natureza, há outros por aqui precisando de ajuda.$B$BA sul daqui, verdejam luxuriantes as florestas de Feralas. Lá, à sombra dos Colossos Gêmeos, procure Konu Runa Totem, que encontrou indícios de um distúrbio preocupante.$B$BSiga pela estrada a oeste, contornando os Colossos Gêmeos, até a Aldeia Ataya. Vá em paz, $n, e que a Mãe Terra $Go:a; acompanhe.', '', '', '', '', '', '', '', '', '', '', 0),
(26590, 'ptBR', 'A água benta da limpidez', 'Consiga a Água Benta da Limpidez do Olho-d\'água Nek\'mani no Cabo do Espinhaço.', 'Ei, escuta aqui... Você não parece $gum:uma; turista aposentad$go:a; qualquer e eu estou em apuros aqui. Meu primo lá do norte me mandou esse artefato estranho aqui e eu preciso da sua ajuda pra identificar o que é.$b$bPra começar, eu vou precisar de um pouco de água benta da limpidez. Dizem que quem beber dessa água recebe uma visão clara e esclarecedora.$b$bParece bem interessante, não?$b$bConsiga um pouco dela no Olho-d\'água Nek\'mani, que fica no topo do acampamento naga. Boa sorte!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Flem Gizzix no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26591, 'ptBR', 'Triagem no front', 'Faça curativos em 10 Terranos Feridos.', 'Você parece ser bem $Gesperto:esperta;, $r. Preciso que alguém entre no meio do caos da frente de batalha e socorra os feridos.$B$BTome o meu kit. É bem simples de usar.$B$BCuide deles antes que os troggs de pedra acabem com todos de vez.', '', 'Terrenos Feridos socorridos', '', '', '', '', '', '', '', 'Fale novamente com o Reparador da Terra Veiofundo no Front Partido, que fica no Geodomo.', 0),
(26592, 'ptBR', 'Cromoscópio difratório', 'Consiga um Rubi dos Vela Sangrenta e uma Safira dos Vela Sangrenta.', 'Para conseguir identificar corretamente esse artefato, Eu vou precisar das ferramentas certas. Eu acho que um cromoscópio difratório deve ser o suficiente.$b$bEu já tenho a carcaça de mithril que, por incrível que pareça, é a parte mais difícil de conseguir. Nós só precisamos de mais duas peças: um rubi e uma safira.$b$bHá piratas por aqui, alguns para o sul e um pouco mais a leste. E piratas adoram guardar tesouros... Que tal tentar conseguir essas pedras pra mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Flem Gizzix no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 0),
(26593, 'ptBR', 'Fazendo o Sacode tremer', 'Obtenha 5 Miúdos de Gorila do Vale da Névoa dos Gorilas Anciãos do Vale da Névoa.', 'Se tem uma coisa que eu não suporto é gente que não paga as dívidas de jogo! E tem muita gente que me deve. Você acha que consegue me ajudar a receber esse dinheiro?$b$bO primeiro é o Phillipe "Sacode", que fica lá nas docas. Ele me deve um monte de dinheiro depois do jogo da última semana, e eu quero tudo! Mas pra conseguir isso, você vai ter que dar um susto nele.$b$bVá para fora da cidade e cace alguns gorilas anciãos do Vale da Névoa. Pegue um bocado de miúdos de gorila e leve-os pro Sacode. Não fale pra ele que são partes de animais. Deixe ele imaginar o pior.', '', '', '', '', '', '', '', '', '', 'Leve os miúdos para o Phillipe "Sacode" na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26594, 'ptBR', 'Fale novamente com MacKinley', 'Leve o Pagamento do Sacode para o MacKinley "Lobo do Mar".', 'Toma, leva essa bolsa de dinheiro pro Lobo do Mar e diz a ele que eu ia pagar! Eu juro!$b$bSó enchi a cara e fiquei perdido e... Sabe como são essas coisas! Ele vai entender, você não precisa ficar nervos$Go:a;!', '', '', '', '', '', '', '', '', '', 'Fale com o MacKinley "Lobo do Mar" na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26595, 'ptBR', 'Cobrança forçada', 'Pegue o Pé-de-clava do Maury, a Chave de Torque Ajustável do Fitzpingo e o Espelho Ornamentado de Ephram.', 'Existem três fases no processo de cobrança: pedir educadamente, pedir à força e algo que eu costumo chamar de "fase três".$b$bInfelizmente eu já estou velho demais para a fase três da cobrança. Por isso, eu contrato tantos capangas, comparsas, cúmplices, jagunços e nobres aventureiros como você!$b$bJunts Fitzpingo, Ephram Lunapoente e Maury Wilkins estão escondidos na costa leste. Você deve conseguir visitar todos os três em uma só viagem... E trazer o que encontrar de valioso com eles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o MacKinley "Lobo do Mar" na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26596, 'ptBR', 'O chamado de Kalimdor', 'Entre no barco que vai da Angra do Butim à Vila Catraca. Chegando lá, fale com o Gasganete.', 'Eu fui enviada pelo povo de Theramore para recrutar membros leais da Aliança que estejam dispostos a ajudar a Grã-senhora Jaina a resolver alguns problemas em Vadeoso.$b$bVocê não veio aqui realmente para trabalhar para os goblins, veio?$b$bO caminho que você deve tomar para Vadeoso é pela Vila Catraca. Espere neste píer pelo próximo barco. Ao chegar à vila, procure pelo Gasganete. Ele lhe mostrará a direção correta.$b$bUrgh, eu acho que pisei em um peixe! E ele pulou!', '', '', '', '', '', '', '', '', '', 'Fale com Gasganete na Vila Catraca, que fica nos Sertões Setentrionais.', 0),
(26597, 'ptBR', 'Febre da Selva do Espinhaço', 'Procure o Mandingueiro Unbagwa e faça-o evocar Mokk, o Selvagem. Leve o Coração de Mokk para Fino Algazarro.', 'Doente... muito... d-d-doente... Contraí febre da Selva do Espinhaço...$b$b...tecnicamente... Febre do CABO do Espinhaço...$b$b...vírus mortaaaal...$b$b...a única cura é... é... comer o coração do m-m-m-Mokk, o Selvagem... fera branca furtiva...$b$b...Mandingueiro Unbagwa... único que sabe evoc-c-c-caaar...$b$b...procure Unbagwa na caverna escondida ao sul do cabo...$b$b...Rápido... estou... morrendo...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Fino Algazarro na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26598, 'ptBR', 'O Coração de Mokk', 'temp text 02 - log', 'temp text 02 - description', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mandingueiro Unbagwa no Cabo do Espinhaço.', 0),
(26599, 'ptBR', 'O baú do capitão', 'Recupere o Baú do Smotts com Gorlash no Cabo do Espinhaço.', 'Eu costumava navegar um barco daqui até a Vila Catraca, em Kalimdor. Eu era uma capitão bem-sucedido, com uma reputação impecável.$b$bAté que...$b$bAqueles malditos gigantes do mar me arruinaram! Eles destruíram o meu navio, mataram a minha tripulação e me abandonaram num bote salva-vidas a caminho da Angra do Butim. Eu não vou descansar até que os corpos deles encham o fundo do oceano!$b$bUm dos gigantes, Gorlash, roubou o meu baú. Eu ouvi falar que ele vaga pela costa, a leste daqui. Encontre-o e recupere meu baú! Faça isso e você terá conquistado a gratidão de um capitão.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Hecklebury Smotts na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26600, 'ptBR', 'Um banquete de gigantes', 'Compre uma Caixa de Carne de Quinta Categoria de Kelsey Yance e um Caixote de Xerez de Pupellyverbos de Aldo Isque.', 'O próximo gigante na minha lista se chama Negolash. Eu lembro nitidamente como ele saltou da espuma do mar e arrancou o Paul Borra-botas do topo da vela. Ele engoliu o pobre Paul de uma vez só e, ao descer, ainda quebrou meu mastro principal em dois.$b$bNenhum homem da minha tripulação merece uma morte como essa. Por isso, nós usaremos o apetite de Negolash contra ele. Kelsey Yance pode te vender um pouco de carne e o Aldo Isque tem bebida suficiente pra derrubar até um... bom, até um gigante do mar. Você pode encontrá-los na cidade.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Hecklebury Smotts na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26601, 'ptBR', 'Mok\'rash, o Cutelo', 'Mate Mok\'rash, o Cutelo, no Pontal de Janeiro.', 'Mok\'rash, o Cutelo, é o último dos gigantes. E o maior deles, se não me engano. Mais alto do que uma onda em uma tempestade, com uma barba que parece uma floresta de algas e um martelo que parece um carvalho.$b$bAté hoje ele zomba de mim lá do Pontal de Janeiro, a ilha que fica bem no final deste píer. É por causa dele que eu ainda estou aqui, preso, vivendo essa vida terrestre lamentável.$b$bSe você souber nadar, vá até o Pontal de Janeiro e mate Mok\'rash.$b$bTome cuidado, $n, pois ele não será abatido tão facilmente quanto os outros dois gigantes.', '', '', '', '', '', '', 'Mok\'rash, o Cutelo', '', '', 'Fale novamente com o Capitão Hecklebury Smotts na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26602, 'ptBR', 'Um prato que se come muito', 'Leve a Caixa Gigante de Comida de Gigante para o bote salva-vidas do Capitão Smotts. Depois, use-a para evocar e matar Negolash.', 'Pegue essa comida e coloque no meu antigo bote salva-vidas, a sudeste daqui na costa. Quando Negolash sentir o cheiro de toda essa comida, virá correndo!$b$bE, quando ele vier, encontrará $gum:uma; $c resolut$go:a;, pront$go:a; pra jogar o corpo dele de volta no fundo do mar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Hecklebury Smotts na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26603, 'ptBR', 'Mensagem na garrafa', 'Encontre a autora da mensagem na Ilha Jaguara, que fica no Cabo do Espinhaço.', 'Dentro da garrafa você encontra um bilhete muito bem escrito:$b$b<Para qualquer um que possa me ajudar.>$b$b<Por favor, eu preciso muito de ajuda. Uma grande besta me mantém prisioneira em uma ilha nos Mares do Sul.>$b$b<As estrelas à noite são estranhas para mim e são obscurecidas pelas árvores da selva. Porém, na luz do dia, eu consigo enxergar a praia a noroeste e uma frota de grandes navios a sudoeste.>$b$b<Eu imploro, a quem quer que seja minha salvação: por favor, me ajude.>', '', '', '', '', '', '', '', '', '', 'Encontre a autora da mensagem na Ilha Jaguara, que fica no Cabo do Espinhaço.', 0),
(26604, 'ptBR', 'Protegendo vossa alteza real Manda-chuva', 'Mate 5 Espreitadores Jaguara.', 'Esses gatos selvagens ferozes estão me rondando já há algum tempo. Eu os vigio o máximo que posso, mas eles parecem simplesmente desaparecer na grama.$b$bO jeito como eles rosnam e rugem!$b$bNão me entenda mal... Eu ainda quero que você me resgate, mas antes, mate alguns desses gatos. Não vale a pena ser resgatada para terminar como jantar de alguém.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Princesa Manda-chuva na Ilha Jaguara, que fica no Cabo do Espinhaço.', 0),
(26605, 'ptBR', 'Aquelas patas imundas', 'Recupere a Tiara da Manda-chuva, o Cetro da Manda-chuva, as Sapatilhas da Manda-chuva e o Diário da Manda-chuva que estão com os primatas da Ilha Jaguara.', 'Eu compreendo que você esteja ansios$go:a; para me resgatar, mas ainda não é a hora certa. Primeiro eu preciso de algumas das minhas coisas.$b$bOs macacos e gorilas no outro lado da ilha roubaram a maioria dos meus pertences. Eu vou precisar da minha tiara, do meu cetro, da minha sapatilha e do meu diário antes de partirmos.$b$bO que foi? Pare de me olhar como se eu fosse uma pessoa louca. Você não faz ideia de como é ser uma princesa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Princesa Manda-chuva na Ilha Jaguara, que fica no Cabo do Espinhaço.', 0),
(26606, 'ptBR', 'A morte de Mukla', 'Mate o Rei Mukla e pegue a Chave dos Grilhões.', '$n, agora eu acredito que você possa me libertar. O grande Rei dos Grenhacéu, Mukla, é o meu captor. Ele comanda todas as feras dessa ilha, e elas me mantêm aqui contra a minha vontade, com a ajuda dessa corrente. Você precisa matá-lo e encontrar a chave que abre esse grilhão, e eu serei eternamente grata a você.$B$BFrequentemente, eu ouço os rugidos dele vindo do lado sudeste da ilha. Por favor, tenha cuidado. Ele não deve ser subestimado.', '', '', '', '', '', '', 'Rei Mukla', '', '', 'Fale novamente com a Princesa Manda-chuva na Ilha Jaguara, que fica no Cabo do Espinhaço.', 0),
(26607, 'ptBR', 'Programado para matar', 'Entregue os Pertences de Keeshan para John J. Keeshan na Taberna de Vila Plácida, que fica em Cristarrubra.', 'Pegue este pacote com os pertences de Keeshan e volte para o porão da taberna de Vila Plácida. A Companhia Bravo já está lá, falando com Keeshan. Faça-o lembrar de que ele foi programado para matar, $n. Vila Plácida precisa de Keeshan. A Aliança precisa de Keeshan.$B$B$gDispensado:Dispensada;, soldado!', '', '', '', '', '', '', '', '', '', '', 0),
(26608, 'ptBR', 'Negociações terminadas', 'Fale com o Almirante Punhopétreo no Bastião Presa do Dragão, que fica no Planalto do Crepúsculo.', 'Vá agora, volte para sua frota. Conte a eles sobre o monstro que reivindica a autoridade sobre os Presa do Dragão.$B$BNosso "Chefe Guerreiro" é um traidor à raça dele. Desde que voltou de Terralém, ele fede a demônio e tem levado o que restou do nosso clã à ruína.$B$BLiberte os Presa do Dragão das garras de Mor\'ghor, e aqueles que têm sangue puro serão seus eternos aliados. Promessa é dívida.', '', '', '', '', '', '', '', '', '', 'Fale com o Almirante Punhopétreo no Bastião Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(26609, 'ptBR', 'Os bucaneiros da Vela Sangrenta', 'O Imediato Crazz quer que você cheque a enseada ao norte da Angra do Butim.', 'Tá mesmo dispost$Go:a; a trabalhar, né, companheir$Go:a;!? Não sei bem por que $gum:uma; $r $c de terra firme como você tá oferecendo ajuda aos Saqueadores Aguanegra, mas não vou recusar.$b$bA gente fez da Angra do Butim nosso "doce lar" quando estamos em terra, mas andam dizendo à boca miúda que os Vela Sangrenta tão armando alguma pra estragar tudo. Todos os meus marujos tão ocupados enchendo a cara e procurando mulheres. Preciso de $gum:uma; $gbatedor:batedora;!$B$BDê uma vasculhada na área que fica ao norte da Angra do Butim, na Costa Selvagem, e veja o que consegue descobrir.', '', '', '', '', '', '', '', '', '', '', 0),
(26610, 'ptBR', 'Traição da Vela Sangrenta', 'Relate suas descobertas para o Imediato Crazz na Angra do Butim.', 'O mapa mostra a Angra do Butim com um "X" vermelho desenhado exatamente no lugar onde você está.$b$bO texto escrito diz:$b$B"Monte seu posto de comando aqui e espere. O Mestre de Frota irá avisar quando chegar a hora de fazer a sua parte."$b$b"Estou colocando o tenente Bruce como encarregado aqui. Dessa vez tudo será diferente. Dessa vez nós tomaremos a Angra do Butim de uma vez por todas."$b$bO mapa está preso no lugar por uma adaga, cravada exatamente na localização da Angra do Butim.', '', '', '', '', '', '', '', '', '', 'Fale com o Imediato Crazz na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26611, 'ptBR', 'O barão precisa ser avisado', 'Conte sobre o plano de ataque da Vela Sangrenta para o Barão Rezingada.', 'Macacos me mordam! Então os Bucaneiros da Vela Sangrenta estão planejando um ataque contra a Angra do Butim? Quanta petulância desses bastardos inglórios. A Angra do Butim será sempre dos Saqueadores Aguanegra!$b$bIsso é muito mais grave do que eu imaginei... Conte o que você descobriu para o Barão Rezingada imediatamente. Ele está aqui na Angra do Butim.', '', '', '', '', '', '', '', '', '', 'Fale com o Barão Rezingada na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26612, 'ptBR', 'Detalhes do ataque', 'Mate 8 Lobos-do-mar da Vela Sangrenta e 8 Magos Anciãos da Vela Sangrenta. Pegue as Cartas de Navegação da Vela Sangrenta e as Ordens da Vela Sangrenta.', 'Eu preciso saber dos detalhes, $n. A nossa supremacia sobre os Vela Sangrenta é principalmente por causa da nossa fortaleza aqui na Angra do Butim, mas a inteligência também tem um papel fundamental.$b$bOs Vela Sangrenta mantêm alguns acampamentos esparsos ao sul, que eles chamam de "Comando do Sul". Bom, invada o tal "comando", a sul daqui, encontre os planos e mate os homens que estiverem lá. Traga de volta qualquer informação que você encontrar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Rezingada na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26613, 'ptBR', 'Levaram o rapé', 'O Dígui, na Angra do Butim, quer que você leve para ele 15 trouxinhas de Rapé.', 'Ah, a vida no mar. Eu não posso dizer que é uma vida fácil, mas é a minha vida.$b$bQuando eu aporto, eu gosto de arrumar uma boa garrafa de bebida e um rapé de boa qualidade. Péssimos hábitos, eu sei... Mas não existe pirata sem vícios, né?$b$bEntão tu deve imaginar como eu fiquei de coração partido quando descobri que o herborista daqui da cidade ficou sem estoque do negócio. Ele disse que o carregamento dele foi roubado por aqueles malditos Saqueadores da Vela Sangrenta.$b$bEu aposto como $gum:uma; $c destemid$go:a; como você consegue convencê-los a dividir um pouco da mercadoria, hein...', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Dígui na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26614, 'ptBR', 'Fique de olho', 'Recupere o Olho do Dizzy dos Bucaneiros da Vela Sangrenta.', 'Alto! Quem vem lá?$b$bArre, sou inútil sem meu olho encantado. Pra começo de conversa, já foi uma desgraça perder as vistas em batalha! Mas, num golpe de sorte, aportamos em Menethil e um mago viajante encantou um olho de vidro que me devolveu a visão. $b$bNa noite passada, fui atacado por uns bucaneiros da Vela Sangrenta... e afanaram meu olho! Parece que esses tipos deram um jeito de entrar na Angra do Butim.$b$bVocê ajuda este velho lobo-do-mar a conseguir o olho de volta!?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Dizzy Caolho na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26616, 'ptBR', 'Não acaba nunca', 'Leve a Barcaça do Keeshan para o Acampamento Lago Plácido, em Cristarrubra.', 'Esses orcs Rocha Negra vão precisar de um exército pra aguentar a Companhia Bravo e você, $n. Quando estiver $gpronto:pronta; pra partir, nos encontre nas docas em frente ao Lago Plácido. Vamos seguir viagem em minha barcaça para o acampamento do outro lado do Lago Plácido.$B$BVejo você lá, $n.', 'Jornada na Barcaça do Keeshan completa', '', '', '', '', 'Jornada na Barcaça do Keeshan completa', '', '', '', 'Fale com John J. Keeshan no Acampamento Lago Plácido, que fica em Cristarrubra.', 0),
(26617, 'ptBR', 'Um velho lobo do mar', 'Leve a Moeda Gasta pelo Tempo para o Mestre de Frota Chifre do Mar na Angra do Butim.', 'Essa moeda velha e desgastada foi encontrada no corpo do pirata Bruce "Bom Garoto". A parte da frente tem uma imagem de um grande barco pirata. Na parte de trás, tem o nome "Tripulação Mareforte".$b$bTalvez algum pirata bem experiente possa saber de onde veio essa moeda ou o que ela significa.', '', '', '', '', '', '', '', 'Bruce, antes de ficar gravemente doente.', 'Bruce Callows', 'Fale com o Mestre de Frota Chifre do Mar na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26618, 'ptBR', 'Lobos nos nossos calcanhares', 'Mate 12 Lobos Hediondos', 'Os lobos hediondos são a ameaça mais comum aos aldeãos. Eles estão à espreita na mata em torno de nós, embora a maioria esteja na margem norte do rio.$B$BE eles não são como os cachorrinhos raquíticos de Elwynn, ou seja lá de onde você for. São grandes como homens e duas vezes mais cruéis.$B$BSe sua intenção é ajudar o povo da Vila Sombria, saia à caça dos lobos hediondos para que nossas ruas fiquem mais seguras.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Comandante Aldora Ebanez na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26619, 'ptBR', 'Caminhando e lutando e seguindo a intuição', 'Passe pelas linhas de frente no Porto Presa do Dragão e fale com Zaela.', 'Se o que você diz for verdade, $n, então temos amigos no clã Presa do Dragão. Há soldados armados, preparados ou não. Quase todos perdidos de armas na mão. Nos quartéis lhes ensinam uma antiga lição de morrer pela Horda e viver sem razão. Nós podemos encarar um levante e evitar um derramamento de sangue, e esperar não é saber.$B$BFale com Zaela atrás das linhas de combate enquanto meus guerreiros Mordacha atacam a costa.$B$BVamos equipar os Presa do Dragão e derrubar seus vis mentores!', '', '', '', '', '', '', '', '', '', 'Passe pelas linhas de frente no Porto Presa do Dragão e fale com Zaela.', 0),
(26620, 'ptBR', 'Kebab Temperado de Lobo', 'Pegue 5 Picanhas de Lobo dos Lobos Hediondos.', 'Os kebabs de lobo bem temperadinhos são especialidade da casa! É claro que posso fazer alguns para você. Mas antes eu preciso dos ingredientes.$B$BTraga-me cinco picanhas de lobo. Os lobos hediondos que vagam nas proximidades do rio a norte da cidade são uma boa presa mas, se eu fosse você, não entraria muito na floresta.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Chef Goroba na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26621, 'ptBR', 'A revolta', 'Dê armas para 3 Trabalhadores ou Mercadores Presa do Dragão, mate 10 Impositores Presa do Dragão e 4 Bruxos Presa do Dragão.', 'As armas que a Horda nos forneceram vão ser mais do que suficientes. Nós quatro devemos nos separar e recrutar o máximo de trabalhadores e mercadores Presa do Dragão que conseguirmos.$B$BNão nos subestime, $n. Você verá que até nossos vendedores são duros na queda.$B$BVamos causar o máximo de dano que pudermos. Equipe um pelotão Presa do Dragão e destrua os impositores e os bruxos vis que têm intimidado meu povo há tempos. Me encontre aqui quando voltar para darmos início ao nosso golpe final!', '', 'Civil Presa do Dragão armado', '', '', '', '', '', '', '', 'Fale novamente com Zaela no Porto Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(26622, 'ptBR', 'Morte a Mor\'ghor', 'Mate o Chefe Guerreiro Mor\'ghor no Porto Presa do Dragão. Você ainda pode recrutar Mercadores e Trabalhadores Presa do Dragão para ajudarem você.', 'Chegou o momento. Mor\'ghor morrerá hoje.$B$BEsteja $gavisado:avisada;, $c. Sangue demoníaco corre nas veias dele e ele canaliza poder inatural. Ele será destruído sim, mas não será uma luta fácil.$B$BVocê se lembra de onde Mor\'ghor reside? No cume do acampamento. Encontro você lá. Dê um fim nele!$B$BRecrute 3 seguidores Presa do Dragão se necessário – você vai precisar de nossa ajuda.', '', '', '', '', '', '', 'Chefe Guerreiro Mor\'ghor', '', '', 'Fale com Garrosh Grito Infernal no Porto Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(26623, 'ptBR', 'Bolinhos de Caranguejo Crepuscular', 'Pegue 6 Caroços Crepusculares de Venaracna.', 'Vou lhe contar um segredinho – os bolinhos de caranguejo crepuscular são, na verdade, feitos com carne de aranha! Eu sei que é um pouco nojento, mas os bolinhos ficam com um delicioso sabor pungente, ótimos para tira-gosto!$B$BMas, se você ficou com vontade de provar, lamento dizer que acabou a carne. Preciso de carne para fazer mais bolinhos.$B$BAs venaracnas dão muita carne. Os ninhos delas ficam a norte, no vale entre as montanhas e o rio.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Chef Goroba na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26624, 'ptBR', 'Entrando para os Vela Sangrenta', 'Apresente-se ao Yancey Gradelha na cachoeira, ao norte da Angra do Butim.', 'Esses planos são... interessantes. Firalião, você é mais esperto do que isso!$b$bOlha pra isso, ele vai colocar os três navios atirando com os canhões e só alguns poucos homens vindo pelo túnel. Ele nunca vai conseguir tomar a Angra do Butim com três navios e uma dúzia de soldados. E ele sabe disso.$b$bNão, ele deve ter mais alguma coisa planejada... e você vai descobrir o que é. Fale com Yancey Gradelha, o Recrutador Vela Sangrenta, ao norte da cidade.$b$bIsso mesmo, $n. Torça pra eles não reconhecerem a sua cara.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Yancey Gradelha na cachoeira, ao norte da Angra do Butim.', 0),
(26625, 'ptBR', 'Troggzor, o Aterrador', 'Pegue a Clava do Aterrador.', 'Você tem que acabar com isso agora mesmo!$B$BVolte para o noroeste, para a frente de batalha, e mate Troggzor, o Aterrador, que está liderando os ataques. Traga-me a clava dele como prova.', '', '', '', '', '', '', 'Troggzor, o Aterrador', '', '', 'Fale novamente com Seixo Lajegrande no Front Partido, que fica no Geodomo.', 0),
(26627, 'ptBR', 'O eremita', 'Descubra quem está ocupando a torre no Refúgio dos Mendigos.', 'Eu soube que tem havido registros de atividade no Refúgio dos Mendigos. Algumas pessoas relataram ter visto luzes na torre a leste da cidade.$B$BPoucos são corajosos o suficiente para se aproximar da Trilha do Vento Morto. Você foi $go primeiro:a primeira; a se apresentar desde que recebemos as informações. Vá até lá e veja se o que está lá é humano.', '', '', '', '', '', '', '', '', '', '', 0),
(26628, 'ptBR', 'A morte vem das profundezas', 'Proteja o Juanka Nabrava durante o ataque.', 'Nada bom. Parece que os Espinhadaga estão se reunindo para um ataque.$b$bNagas são conhecidas pela crueldade em batalha. Elas não vão parar até que eu esteja morto.$b$bNão prezo a minha vida mais do que a da minha tripulação, mas você precisa me ajudar. Meus homens não conseguirão voltar para a Angra do Butim sem minha prática marítima.$b$bAs nagas sairão das águas. Preciso que você fique aqui comigo para nos defendermos do ataque. Pegue um canhão e expulse-as.$b$bEstá $Gpronto:pronta;, $n?', 'Defenda o Juanka Nabrava', '', '', '', '', 'Defenda o Juanka Nabrava', '', '', '', 'Fale novamente com o Juanka Nabrava na Enseada de Faldir, que fica no Planalto Arathi.', 0),
(26629, 'ptBR', 'Teste de lealdade', 'Pegue a Cabeça do Mestre de Frota Chifre do Mar na Angra do Butim.', 'Só tem uma coisa...$b$bO velho Yancey ouve coisas. Alguns dos meus camaradas tavam bem bêbados quando me falaram sobre $gum:uma; tal $r $c que entrou no Comando do Sul atropelando todo mundo, procurando pelas cartas marítimas e pelas ordens. El$ge:a; inclusive matou alguns bons piratas.$b$bComo eu disse, meus camaradas estavam cheios de cachaça na cabeça, mas ainda assim... Um bucaneiro tem que confiar no que ouve. Portanto, eu tenho só uma tarefa pra você, enviada diretamente do Firalião...$b$bTraga-me a cabeça do Mestre de Frota Chifre do Mar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Yancey Gradelha no Cabo do Espinhaço.', 0),
(26630, 'ptBR', 'Me parece um tauren pirata', 'Consiga uma Cabeça de Vaca e um Chapéu de Pirata Enorme. Depois, leve-os de volta para o Mestre de Frota Chifre do Mar.', 'Firalião quer a MINHA cabeça? Ah, isso é interessante. Mas não é nada que nós não possamos resolver.$b$bEsse tal de Yancey nem deve conhecer a minha cara direito. A maioria dos não-taurens acha que nós somos todos iguais. Na verdade... a maioria dos não-taurens nos acham indistinguíveis de um... Um certo animal de fazenda de quatro patas.$b$bRiknik, o coureiro, mantém uma dessas criaturas aqui na Angra do Butim, e Narkk é meu fornecedor oficial de chapéus de pirata. Arrume uma cabeça e um chapéu para substituir a minha e depois volte aqui.', '', 'Entregue os dois itens para o Mestre de Frota Chifre do Mar', '', '', '', '', '', 'Boa noite, doce rainha. Seu sacrifício não será esquecido.', 'Malhada', 'Fale novamente com o Mestre de Frota Chifre do Mar na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26631, 'ptBR', 'O primeiro dia do pirata', 'Leve os Seus Papéis para o Capitão Querena.', 'Você pode ser $gum matador:uma matadora; de mestres de frota, mas regras são regras e ordens são ordens. E as MINHAS ordens são para que todos os piratas comecem como grumetes. É a regra.$b$bVocê vai trabalhar para o Capitão Querena, o comandante do Rasgamar. É o barco mais a oeste da nossa frota, que está ancorada ao sul da ponta do cabo.$b$bEncontre ele na cabine do capitão e leve os seus papéis.', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Querena no Rasgamar, que está no Cabo do Espinhaço.', 0),
(26632, 'ptBR', 'Acompanhando de perto', 'Escolte a Catapulta Terrana até a Vila Pedragulha.', 'Muito bem, acho que consegui consertar. Agora, você vai levar a catapulta para a cidade dos troggs de pedra, chamada Vila Pedragulha, que fica a norte do front.$B$BO condutor da catapulta vai com você, e eu vou voltar para dar notícias ao Seixo.$B$BTenho certeza que os troggs de pedra vão tentar deter vocês. Basta mantê-los longe da catapulta. Ela tem muito poder de fogo.$B$BAvise-me quando você estiver $Gpronto:pronta;, $n.', '', 'Catapulta Terrena escoltada', '', '', '', '', '', '', '', 'Fale com Pírio Magneto na Vila Pedragulha, que fica no Geodomo.', 0),
(26633, 'ptBR', 'Entrei de gaiato no navio', 'Pegue o Esfregão do Grumete no convés do Rasgamar e mantenha o convés limpo por 2 minutos.', 'Eu quero o Rasgamar todo brilhando como um rubi-estrela, grumete $n. O meu barco está sempre impecável graças a grumetes como você!$b$bTá esperando o quê, $gseu:sua; cabeça de bagre? Vai pro convés e começa a esfregar!', '', 'Esfregue o convés', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Querena no Rasgamar, que está no Cabo do Espinhaço.', 0),
(26634, 'ptBR', 'O fim de muitos piratas', 'Obtenha 5 Punhados de Limas.', 'Doenças na gengiva. Isso sim é um problema, $r.$b$bEu sei que você é nov$Go:a; por aqui e provavelmente nunca precisou cortar a sua gengiva, mas os piratas mais experientes daqui têm que lidar com um probleminha chamado ESCORBUTO. É justamente por isso que a gente tem tantas limas a bordo.$b$bBom... a gente tinha limas aqui. Fugiram com o nosso último carregamento. Quem quer que tenha sido não pode ter ido muito longe... Deve estar nas ilhas vizinhas. Traga as nossas limas de volta, e eu vejo o que posso fazer pra promover você.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Garr Casco Salgado no Rasgamar, que está no Cabo do Espinhaço.', 0),
(26635, 'ptBR', 'Afunda como bala de canhão', 'Colete 6 Balas de Canhão da Vela Sangrenta dentro da água, na área abaixo do Rasgamar.', 'Pode ajudar um companheiro de trabalho?$b$bO Querena me pediu pra pegar umas balas de canhão no fundo do oceano, mas isso não dá pra mim. Vou te explicar porquê.$b$b- Primeiro: eu tenho braços curtos. Olha só eles! Você acha mesmo que eu conseguiria levantar uma bala de canhão, mesmo debaixo d\'água?$b$b- Segundo: eu tenho um sistema respiratório frágil. Eu começo a perder os sentidos se parar de respirar por mais de dez segundos.$b$b- Terceiro: tá cheio de tubarões nessa água.$b$bVocê precisa me ajudar, $n! Eu já fui rebaixado para a pior posição do navio... Eu não quero descobrir o que acontece depois!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Duncan "Bonitão" no Rasgamar, que está no Cabo do Espinhaço.', 0),
(26636, 'ptBR', 'Kit de campanha da Companhia Bravo: Camuflagem', 'Colete 5 Montes de Folhas e 5 pedaços de Fezes de Raposa.', 'Vamos precisar de suprimentos antes de eliminarmos o exército Rocha Negra e salvarmos Cristarrubra. É aí que você entra, $gnovato:novata;.$B$BKeeshan me encarregou de arranjar camuflagem para o kit de campanha da Companhia Bravo. Preciso que você vá para o sul e pratique um pouco de "jardinagem". Essa tarefinha tem basicamente dois elementos: (1) Folhas e (2) Fezes de raposa. É do que precisamos.$B$BVocê achou que camuflagem fosse feita de quê?$B$BVá para o sul e colete o que eu pedi, $grapaz:moça;.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Krakauer no Acampamento Lago Plácido, que fica em Cristarrubra.', 0),
(26637, 'ptBR', 'Kit de campanha da Companhia Bravo: Clorofórmio', 'Colete 8 Glândulas de Moralodo.', 'A primeira parte da missão é uma operação secreta, $n. Assim, vamos precisar incapacitar o inimigo sem fazer barulho. Vamos precisar de clorofórmio.$B$BOs moralodos no fundo do Lago Plácido têm clorofórmio nas glândulas. Preciso que você mergulhe no Lago Plácido e colete glândulas de moralodo. Acha que dá conta?$B$BFale comigo novamente quando coletar bastante glândulas.$B$BVocê quer saber onde fica o lago? Abre o olho, pateta. Fica diretamente a oeste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Messner no Acampamento Lago Plácido, que fica em Cristarrubra.', 0),
(26638, 'ptBR', 'Caçando os caçadores', 'Mate 8 Caçadores Rocha Negra.', 'A sul daqui, na Estrada Beira-lago, tem um grupo de orcs Rocha Negra. Eles ficam de tocaia na floresta, protegidos pela escuridão, e armam emboscadas pros incautos. Eles são a primeira linha de defesa do exército Rocha Negra. Eles são batedores, e tudo o que eles veem é imediatamente repassado pra central de comando Rocha Negra.Eles precisam ser eliminados IMEDIATAMENTE, ou nossa missão aqui vai ficar seriamente comprometida.$B$BSiga para o sul e mate todos os Rocha Negra que encontrar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Danforth no Acampamento Lago Plácido, que fica em Cristarrubra.', 0),
(26639, 'ptBR', 'Ponto de Contato: Brubaker', 'Encontre Brubaker.', 'Antes de começarmos a agir, precisamos montar um kit de campanha. Você vai me ajudar com isso, $n. Também tem o problema do reconhecimento da área. Por sorte, Ventobravo nos mandou alguma ajuda nesse sentido. Meu velho companheiro de batalhas, Brubaker, foi mandado pela AVIN para fazer reconhecimentos aqui na área. Você deve encontrá-lo em campo, ao sul daqui.$B$BVá falar com Brubaker e descubra o que ele sabe.', '', '', '', '', '', '', '', '', '', '', 0),
(26640, 'ptBR', 'Atrocidades indizíveis', 'Entregue o Relatório de Brubaker para John J. Keeshan no Acampamento Lago Plácido, que fica em Cristarrubra.', '<Você desdobra o bilhete e começa a ler.>$B$B"Keeshan, se você estiver lendo isto, significa que estou morto. Posição provavelmente comprometida.$B$BOrcs estão cometendo atrocidades indizíveis com os prisioneiros. Sim, prisioneiros, Keeshan. Jaulas cheias de prisioneiros de guerra. Se você vai explodir esse vale, vai precisar libertar os prisioneiros antes.$B$BDiga a minha esposa que eu a amo e acabe com essa escória maldita.$B$B– Brubaker$B$BP.S.: Eles têm dragões negros."$B$BLeve o relatório para Keeshan.', '', '', '', '', '', '', '', '', '', '', 0),
(26641, 'ptBR', 'Não se faz uma omelete sem...', 'Recolha 5 Ovos da Prole de Shadra em Agol\'watha.', 'Os guarda-proles Ramatorpe, a nordeste daqui, tomam conta dos ovos da prole de Shadra. Mesmo se matarmos os Ramatorpe, os ovos continuarão ali, esperando para chocar e lançar essas criaturas horríveis na floresta.$B$BPrecisamos cuidar disso da maneira correta. Arranque os ovos das bolsas de ovos e traga-os para mim. Não tente destruí-los por conta própria, pois as criaturinhas podem escapar.$B$BQuando você voltar, cuidarei para que os ovos sejam eliminados adequadamente!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gilda Chamanuvens no Pavilhão Quel\'Danil, que fica nas Terras Agrestes.', 0),
(26642, 'ptBR', 'A defesa dos Sertões', 'Apresente-se a Kargal Chaga de Guerra no Posto Remoto, que fica nos Sertões Setentrionais.', 'Durante anos os Sertões foram o coração da Horda em Kalimdor. Uma ligação vital entre os orcs de Durotar e os assentamentos dos taurens, em Mulgore.$B$BCom o caos causado pelo cataclismo: enchentes, terremotos e até uma invasão de javatuscos ameaçam nos separar destas terras verdejantes.$B$BVocê parece $Gpronto:pronta; para um desafio. Apresente-se a Kargal Chaga de Guerra no Posto Remoto, e cuide para que o caminho até os Sertões permaneça seguro! Para encontrá-lo, siga para o oeste, beirando o Monte Navalha, e cruze o Rio Furiaustral.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Kargal Chaga de Guerra no Posto Remoto, que fica nos Sertões Setentrionais.', 0),
(26643, 'ptBR', 'Dieta de fome', 'Destrua 6 Vítimas Encasuladas nas Ruínas Assustadoras.', 'A Ruína Assustadora, a leste, está infestada de aranhas adultas da prole de Shadra. Elas são grandes o bastante para arrastar um anão inteiro noite à dentro e você terá provas suficientes disso quando chegar lá... há casulos de corpos por toda a ruína.$B$BElas não os mantêm vivos por muito tempo, $n, mas se alimentam dos corpos por dias. É tarde demais para salvar as vítimas, mas não podemos permitir que as aranhas engordem e se desenvolvam. Livre-se daqueles casulos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gilda Chamanuvens no Pavilhão Quel\'Danil, que fica nas Terras Agrestes.', 0),
(26644, 'ptBR', 'Chamando atenção', 'Fale com o Mestre de Frota Firalião no Véu Carmesim, que está no Cabo do Espinhaço.', 'Grumete $n! Esse é um dia triste pro seu velho Capitão Querena. Hoje eu estou perdendo $go meu:a minha; melhor grumete.$b$bChegou uma carta do Mestre de Frota Firalião. Aparentemente ele ouviu falar do seu ótimo trabalho de grumete e quer te levar para bordo do Véu Carmesim, como espadachim e terceiro marujo. O barco está ancorado ao lado do Rasgamar.$b$bEm termos de plano de carreira como pirata, esse é um grande passo pra você, grumete $n. Sugiro que tu aceite essa oferta.$b$bDispensad$go:a;!', '', '', '', '', '', '', '', '', '', '', 0),
(26645, 'ptBR', 'A Vigília Noturna', 'Abata 8 Horrores Putrefatos nos arredores do Antro da Maria Cega, a sudeste da Vila Sombria.', 'Lamento informar que só contamos com você para nos ajudar, $n. As tropas de Ventobravo estão tão sobrecarregadas combatendo males maiores que não podem deslocar nem um batedor para proteger a Vila Sombria. Cabe a mim e à Vigília Noturna zelar pela segurança de nossos lares.$B$BInfelizmente, nossos problemas aqui não se resumem a meros lobos. Horrores putrefatos vagam perto do Antro da Maria Cega, na fronteira sudeste da vila. Se não os mantivermos sob controle, em breve estarão visitando nossas casas durante a noite.$B$BDê cabo dos mortos-vivos e se apresente a mim para pegar sua recompensa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Comandante Aldora Ebanez na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26646, 'ptBR', 'Prisioneiros de guerra', 'Liberte os Prisioneiros de Guerra trancados na prisão no Vale dos Laceradores.', 'O kit de campanha da Companhia Bravo está pronto, $n. Aqui está. Você deverá entrar no Vale dos Laceradores, a sudeste daqui, e libertar os prisioneiros. Estou mandando o Jorgensen com você para ficar de olho na sua retaguarda.$B$BOs prisioneiros estão no lado nordeste do vale, numa grande jaula, mas a chave da jaula está numa caverna no lado sul do vale. Você vai precisar roubar a chave, criar uma distração e libertar os cidadãos.$B$BBoa sorte, $n! Vou manter contato pelo kit de campanha.', '', 'Prisioneiros de Guerra libertados', '', '', '', '', '', 'A guerra está no meu sangue.', 'John J. Keeshan', 'Fale com John J. Keeshan no Acampamento Lago Plácido, que fica em Cristarrubra.', 0),
(26647, 'ptBR', 'Velho Detona', 'Pratique tiro com o canhão. Acerte 5 tiros no Tico Graveto usando o Velho Detona.', 'Temos trabalho a fazer. Quanta experiência você tem com canhões? Humm... É mesmo? E quanto a canhões piratas, velhos, caindo aos pedaços?$b$bNós temos uns canhões lá no convés que ainda funcionam da maneira antiga: você carrega uma bala de cada vez, mira, trava o canhão e atira. Funciona muito bem se você tiver tentando acertar a lateral de um navio de três velas... Mas não funciona tão bem se estiver tentando acertar um barquinho a remo ou coisas do tipo.$b$bPor que você não sobe lá e tenta dar uns tiros no Tico Graveto?', '', 'Acerte o Tico Graveto com um tiro de canhão', '', '', '', '', 'Tico Graveto', '', '', 'Fale com o Olho de Ferro no Véu Carmesim, que está no Cabo do Espinhaço.', 0),
(26648, 'ptBR', 'Nossos inimigos mortais', 'Mate 15 Ninjas na Ilha Jaguara.', 'Ei, novat$go:a;, dá uma olhada nisso aqui.$b$b<O anão levanta o tapa-olho e mostra um olho perfeito por baixo.>$b$bEu não uso esse tapa-olho por ter perdido um olho. Eu uso porque meu OUTRO olho é tão poderoso que esse só serve pra atrapalhar.$b$bEsse olho serve pra ver todo tipo de coisa, como, por exemplo, aqueles brutamontes mascarados que ficam nos seguindo. O Mestre de Frota disse que eles foram vistos na Ilha Jaguara. Quando tu chegar lá, dispare esse sinalizador e eu vou te ajudar a achar eles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Drederico McGumm, o Caolho, no Véu Carmesim, que está no Cabo do Espinhaço.', 0),
(26649, 'ptBR', 'Pirataria de passagem', 'Fale com o Remador da Vela Sangrenta do lado de fora do Véu Carmesim. Depois, use o canhão para matar 75 Petroleiros da Empreendimentos S.A.', 'Agora que você já sabe como usar os nossos canhões, chegou a hora de acertar alguns alvos de verdade!$b$bA Empreendimentos S.A. encontrou ouro ao norte daqui... Um tipo de ouro raro, chamado "ouro negro". Parece mais uma "mancha preta" na minha opinião.$b$bNós vamos roubar esse ouro, mas antes precisamos nos livrar daqueles capangas da Empreendimentos. Eu ordenei que um dos meus remadores te leve até lá. Saia do navio pela rampa e fale com ele na parte norte da ilha.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Olho de Ferro no Véu Carmesim, que está no Cabo do Espinhaço.', 0),
(26650, 'ptBR', 'O Sorte da Donzela', 'Vá para a sua cabine do capitão no Sorte da Donzela, que está no Cabo do Espinhaço.', 'Eu sei que tu mal chegou aqui no Véu Carmesim, mas preciso te despachar em outro servicinho. O Sorte da Donzela é o terceiro barco da minha frota, ancorado a leste daqui. O encarregado dele, capitão Tranquiláguas, já não está mais entre nós.$b$bAmaldiçoados sejam aqueles assassinos mascarados!$b$bEnfim, o Olho de Ferro me falou das tuas façanhas heroicas no mar e hoje em dia tá difícil arrumar bucaneiros de categoria. E eu acho que tu já tá dando mais que no couro de assumir essa nova função.$b$bParabéns, $gmarujo:maruja;. Tu é $go novo:a nova; capitão do Sorte da Donzela.', '', '', '', '', '', '', '', '', '', '', 0),
(26651, 'ptBR', 'Para vencer a guerra, torne-se a guerra', 'Use o Kit de Campanha da Companhia Bravo para plantar uma Carga de Cequatrum na Torre Rocha Negra e na Cabana de Munições Rocha Negra.', '<O rádio da Companhia Bravo emite um bipe.>$B$BVocê já compreendeu, $n? Você entende o que precisamos fazer para vencer a guerra contra esses monstros? VOCÊ DEVE SER A GUERRA! SEM PIEDADE!$B$BCom os prisioneiros libertados, você já pode posicionar o cequatrum. Siga até aquelas estruturas lá fora e posicione uma carga em cada uma.$B$BUma carga na cabana de munições Rocha Negra e outra na torre Rocha Negra. Quando terminar, apresente-se a mim e à Companhia Bravo na Garganta do Barro Seco, a leste do Vale dos Laceradores.', '', 'Cequatrum posicionado na Cabana de Munições', 'Cequatrum posicionado na Torre Rocha Negra', '', '', '', 'John J. Keeshan', '', '', 'Fale com John J. Keeshan na Garganta do Barro Seco, que fica em Cristarrubra.', 0),
(26652, 'ptBR', 'Linha de Cabelo de Fantasma', 'Leve o Pente Espectral para a Maria Cega.', 'Há uma casa de fazenda abandonada, nas montanhas a sul da Vila Sombria, que é assombrada por um velho e melancólico fantasma chamado Maria Cega.$B$BPegue este pente espectral e peça à Maria Cega que penteie os cabelos. Em seguida, traga o pente para mim e catarei o cabelo de fantasma para fazer a linha que você quer.$B$BE cuidado, pois ultimamente criaturas sombrias têm espreitado a casa...', '', '', '', '', '', '', '', '', '', '', 0),
(26653, 'ptBR', 'Fio de cabelo', 'Fale com Madame Eva na Vila Sombria.', 'Ah, o que um pobre velho pode fazer? Preciso de suprimentos, mas a Vila Sombria fica tão longe e eu estou tão velho e fraco... Eu nunca sobreviveria à viagem.$B$BVocê poderia ir até lá e trazer para mim uma linha feita com cabelo de fantasma? Madame Eva costuma ter dessas linhas em casa, na praça da Vila Sombria.', '', '', '', '', '', '', '', '', '', '', 0),
(26654, 'ptBR', 'Devolva o pente', 'Leve o Pente de Fantasma para Madame Eva na Vila Sombria.', 'NÃO!!!!!$B$BLeve o pente para bem longe de mim!$B$BEu sou um monstro, e nunca mais alguém vai me achar bonita de novo!', '', '', '', '', '', '', '', '', '', '', 0),
(26655, 'ptBR', 'Entregue a linha', 'Leve a Linha de Cabelo de Fantasma para Abercrombie, na torre dele no Refúgio dos Mendigos.', 'Aqui está a linha, $n. Ela tem mil e uma utilidades, desde prender espíritos do mal até dar vida a objetos inanimados costurados com ela.', '', '', '', '', '', '', '', '', '', '', 0),
(26656, 'ptBR', 'Sempre em frente', 'Corra com pelo menos 5 Guardiões Opalescentes para fora do Alcândor Pálido, em direção ao leste, até o círculo de pedra próximo ao Trono de Therazane.', 'Quando o Asa da Morte veio para cá, os Dragões de Pedra juntaram-se a ele. E agora, com a ausência do destruidor, os dragões estão novamente sem líder. Eles voam em bando e se alimentam de nossos companheiros.$B$BEu criei dúzias de guardiões opalescentes, mas não posso tirá-los da segurança do abrigo. Preciso de alguém mais ágil, e suspeito que você seja assim.$B$BConduza os guardiões pelo chão até o Trono de Therazane, a leste daqui. Certamente perderemos alguns pelo caminho, mas a maioria conseguirá se juntar às tropas.', '', 'Falar com Terrath, o Estável', 'Guardiões Opalescentes escoltados em segurança', '', '', '', '', '', '', 'Fale novamente com Terrath, o Estável, no Alcândor Pálido.', 0),
(26657, 'ptBR', 'Caindo no duro', 'Mate 6 Dracos de Pedra.', 'Os Dragões de Pedra só cedem perante força bruta. Se apanharem bastante, eles se curvarão a nós.$B$BEnviei os nossos mais fortes gigantes para os campos a oeste. Eles derrubarão os dragões, e você garantirá que não voem de novo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Terrath, o Estável, no Alcândor Pálido.', 0),
(26658, 'ptBR', 'Valores frágeis', 'Pegue uma Marreta Esculpida em Pedra.', 'Chegou a hora de atrair a atenção da Prolemadre. Para tanto, vamos precisar da marreta que os troggs usam para fazer oferendas a ela.$B$BProcure os troggs de pedra que estão tentando domar basiliscos na parte sul do Alcândor Pálido. Você certamente achará uma marreta em um dos cadáveres.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Terrath, o Estável, no Alcândor Pálido.', 0),
(26659, 'ptBR', 'Golpe ressoante', 'Derrote Aeosera.', 'Na fronteira oeste do Alcândor Pálido, há um cristal ressoante. Acerte-o com a marreta. Isso atrairá a prolemadre.$B$BEsteja $Gpronto:pronta; para a batalha. Estarei lá para ajudá-$glo:la;, mas a prolemadre não será derrotada facilmente.', '', 'Cristal Ressoante Pálido atingido', 'Aeosera derrotada', '', '', '', 'Aeosera', '', '', 'Fale novamente com Terrath, o Estável, no Alcândor Pálido.', 0),
(26660, 'ptBR', 'Suco de zumbi', 'Fale com o Taberneiro Oseias', 'Preciso de uma garrafa de uma certa bebida – suco de zumbi. O taberneiro Oseias, na taberna O Corvo Escarlate, deve ter em estoque.$B$BE, por favor, corra, $n. As noites estão frias, e eu preciso dessa bebida para botar fogo nas minhas veias de novo!', '', '', '', '', '', '', '', '', '', '', 0),
(26661, 'ptBR', 'Flores do mal', 'Colha 5 Flores do Mal no Cemitério Jardins da Paz.', 'Se você me trouxer algumas flores do mal, eu posso fazer suco de zumbi para você.$B$BAs flores do mal crescem em lugares estranhos. Elas costumam florescer sobre coisas mortas, e há muito disso aqui na Floresta do Crepúsculo!$B$BEu vi que algumas flores do mal nasceram no Cemitério Jardins da Paz. Procure perto dos túmulos... Mas cuidado com os mortos que zanzam por lá.', '', '', '', '', '', '', '', '', '', 'Fale com o Taberneiro Oseias na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26662, 'ptBR', 'A tripulação do Mareforte', 'Fale com Long John Copper no Sorte da Donzela, com Shawn Stooker, o Gigante no Véu Carmesim e com Mary Smitts, a Uivadora no Rasgamar.', 'As cartas náuticas mencionam um grupo chamado de Tripulação do Mareforte. Esse nome é novo para você, apesar de ter ouvido que novos bucaneiros teriam se juntado ao grupo recentemente.$b$bTalvez seja a hora de visitá-los e descobrir o que eles sabem.', '', 'Falar com Long John Copper', 'Falar com Shawn Stooker, o Gigante.', 'Falar com Mary Smitts, a Uivadora', '', '', '', '', '', 'Volte para a sua cabine no Sorte da Donzela, que está no Cabo do Espinhaço.', 0),
(26663, 'ptBR', 'Traíra de água salgada', 'Sabote o Barril de Grogue, o Barril de Pólvora e a Caixa de Balas de Canhão.', 'O ataque contra a Angra do Butim é muito maior do que imaginavam. Você precisa retornar ao Barão de imediato para avisá-lo.$b$bMas antes disso, é uma boa ideia sabotar os suprimentos dos piratas enquanto eles ainda confiam em você. Eles mantêm a maioria dos suprimentos no convés inferior dos diversos barcos da flotilha.', '', 'Sabote o Grogue', 'Sabote a Pólvora', 'Sabote as Balas de Canhão', '', '', '', '', '', 'Volte para a sua cabine no Sorte da Donzela, que está no Cabo do Espinhaço.', 0),
(26664, 'ptBR', 'Causando um motim', 'Acuse 9 Corsários da Vela Sangrenta de motim. Depois, mate-os.', 'Antes de voltar para a Angra do Butim, você deve fazer tudo que puder para enfraquecer os Bucaneiros da Vela Sangrenta. Infelizmente, mesmo sendo capitão do barco, você está proibid$go:a; de matar seus companheiros a sangue frio. Só o Mestre da Frota pode fazer isso.$b$bNo entanto, você pode executar marinheiros amotinados... e é muito difícil conseguir provas negando um possível motim.$b$bFalando nisso, aqueles corsários da Vela Sangrenta que ficam no convés inferior do navio parecem muito suspeitos.', '', 'Corsário dos Vela Sangrenta acusado e morto', '', '', '', '', '', '', '', 'Volte para a sua cabine no Sorte da Donzela, que está no Cabo do Espinhaço.', 0),
(26665, 'ptBR', 'O chamado do Butim', 'Fale com o Barão Rezingada na Angra do Butim, que fica no Cabo do Espinhaço.', 'Você acha que já causou bastante dano e agora já sabe os planos dos Vela Sangrenta. Você fez tudo que o Barão Rezingada pediu.$b$bChegou a hora de pendurar o chapéu de pirata e voltar para a Angra do Butim. A batalha está próxima.', '', '', '', '', '', '', '', '', '', '', 0),
(26666, 'ptBR', 'A lenda de Galvão', 'Procure o Tabelião Azambuja na Prefeitura de Vila Sombria.', 'Eu vim até aqui porque recebi uma carta do Galvão, meu irmão. Não nos víamos há muito tempo. E, quando cheguei, me falaram que ele havia morrido...$B$BA cidade inteira se recusa a me dar mais explicações. A mera menção do nome dele suscita terror e desconfiança. Como se eu já não estivesse aterrorizado e desconfiado o bastante!$B$BTenho medo do que pode acontecer se eu ficar com ainda mais raiva e frustração. Eu lhe rogo: me ajude a chegar ao fundo disso tudo. Implore ao tabelião Azambuja que ele lhe dê qualquer informação sobre o meu irmão.', '', '', '', '', '', '', '', '', '', '', 0),
(26667, 'ptBR', 'As cartas roubadas', 'Recupere o Maço de Cartas Destruídas no Bosque Brilhante.', 'Então você quer notícias do Galvão...$B$BVocê não é $Go primeiro:a primeira;, sabia? Com frequência aparecem uns forasteiros perguntando sobre ele. E é sempre gente de fora. Quem é daqui não comete o mesmo erro.$B$BMas você deu azar. Perdi metade dos arquivos. Worgens selvagens invadiram a prefeitura algumas noites atrás e destruíram tudo.$B$BOs documentos que você quer devem estar espalhados pelo Bosque Brilhante, no meio das matas a oeste. Se você quer saber, o esforço não vale a pena.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tabelião Azambuja na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26668, 'ptBR', 'Detonação', 'Exploda o Vale dos Laceradores.', 'Os explosivos que você posicionou eram bem potentes, $n. Quando eu apertar esse botão aqui no kit de campanha da Companhia Bravo, o vale inteiro vai ser engolfado por uma mortífera bola de fogo gigante.$B$BSabe, acho que você pode fazer as honras. Foi você quem fez todo o trabalho pesado, afinal.$B$B$gPronto:Pronta;?', 'Exploda o Vale dos Laceradores.', '', '', '', '', 'Exploda o Vale dos Laceradores.', '', '', '', 'Fale com John J. Keeshan no Acampamento Lago Plácido, que fica em Cristarrubra.', 0),
(26669, 'ptBR', 'Em uma esquina sombria', 'Procure a Página de Diário Rasgada no Horto Pútrido.', 'Se você realmente está levando isso a sério, $n, vou ajudá-$Glo:la;. Eu sei onde os outros documentos devem estar. Mas estou simplesmente aterrorizado demais para fazer algo a respeito.$B$BOs terríveis Nocturnos se reúnem em alguns poucos lugares, quando não estão rondando a floresta. Um deles é o Horto Pútrido, a sul daqui. Eles usam as estruturas construídas lá como abrigo. Então, se não tiverem comido tudo, talvez você ainda encontre algum documento lá... Mas aposto que você vai ter que vasculhar o covil todo para achar alguma coisa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tabelião Azambuja na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26670, 'ptBR', 'O Descanso de Rolando', 'Procure as outras páginas do Diário do Galvão no Descanso de Rolando.', 'E isso não é tudo...$B$BÉ melhor deixar pra lá, $n. Só falta procurar no Descanso de Rolando, aquela mina a sul da cidade que é o maior covil de worgens da Floresta do Crepúsculo. E nenhum morador da Vila Sombria jamais voltou com vida de lá. Na verdade, alguns registros que tenho aqui indicam que todos esses monstros vieram de lá... Quem sabe que tipo de mal espreita aquele covil?$B$BPor favor, $n, é melhor desistir. Vamos esquecer tudo e nunca mais falar disso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tabelião Azambuja na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26671, 'ptBR', 'O destino de Galvão Brumanto', 'Entregue a Lenda de Galvão para Tobias Brumanto.', 'Você achou tudo. Tudo menos a última página....$B$B...Que está aqui. Ah, não me olhe assim. Você vai entender quando ler o que está escrito. Alguns até dizem que está amaldiçoada, sabia? Para ser sincero, eu fiquei aliviado quando os worgens invadiram e deram um fim nisso!$B$BTome. Na verdade, pode levar tudo. Eu agradeço a você por recuperar meus arquivos, mas não quero saber disso nunca mais. Por favor, me deixe em paz.', '', '', '', '', '', '', '', '', '', '', 0),
(26672, 'ptBR', 'Agarrando-se à verdade', 'Entregue o Anel da Família Brumanto para a Madame Eva.', 'Não pode ser. Meu irmão era genioso, mas tamanha vileza... Uma maldade sanguinária tão doentia e violenta...$B$B<Tobias levas as mãos ao rosto, desviando o olhar.>$B$BEu preciso de respostas. Preciso saber como aquela carta chegou a mim. Preciso saber se o Galvão fez isso de verdade.$B$BEu preciso saber por quê...$B$BPegue o meu anel, $n. Entregue-o para a Madame Eva. Essa mulher é declaradamente adepta das artes ancestrais... Pode me chamar de louco, mas não tenho nada a perder.', '', '', '', '', '', '', '', '', '', '', 0),
(26673, 'ptBR', 'REUSE - BREADCRUMB', 'Bring the Mistmantle Family Ring to Madame Eva.', 'This can\'t be. My brother was strong-willed, but such vileness... such sickness and violent, bloody evil...$B$B<Tobias brings a hand to his face, averting his gaze.>I must have answers. I need to know how I got that letter. I need to know if Stalvan really did this.$B$BI need to know why...$B$BTake my ring, $n. Bring it to Madame Eva. That woman is a follower of old arts and makes no secret of it... call it madness, but I\'ll try anything at this point.', '', '', '', '', '', '', '', '', '', '', 0),
(26674, 'ptBR', 'A vingança de Brumanto', 'Use o Anel da Família Brumanto no Casarão dos Brumanto, a leste da vila.', 'Lamento dizer que não tenho as respostas que Tobias procura. Mas eu posso ajudar você a encontrar a única pessoa que sabe de tudo...$B$BGalvão Brumanto.$B$BLeve o anel até o Casarão dos Brumanto, na mata a leste daqui, onde o corpo de Galvão foi enterrado. Entre lá e segure o anel diante de si. Deixe que a lua minguante derrame sua luz sobre a joia, e os espíritos responderão ao seu chamado.$B$BTenha cuidado, $n. As dúvidas dos vivos dão mais consolo do que as respostas dos mortos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tobias Brumanto na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26676, 'ptBR', 'Alguém pediu um suco?', 'Leve o Suco de Zumbi para o Abercrombie no Refúgio dos Mendigos.', 'Está aqui o suco de zumbi...$B$B...E tenha cuidado com isso. É forte o suficiente para levantar os mortos!', '', '', '', '', '', '', '', '', '', '', 0),
(26677, 'ptBR', 'Boneco de carniçal', 'Pegue 7 Costelas de Carniçal dos Cadáveres Fétidos que vagam perto do Casarão dos Brumanto.', 'Nestes campos afastados dos arredores da cidade, é incrível que eu ainda não tenha virado comida de morto-vivo! Na verdade, ontem mesmo eu vi um bando de carniçais andando pelas paredes da minha torre!$B$BEu quero fazer um boneco para funcionar como uma espécie de espantalho de carniçais. Para isso, eu preciso de algumas costelas de carniçal. Dá para tirar muitas costelas dos cadáveres fétidos que vagam pelas terras nas cercanias do Casarão dos Brumanto, a norte da Vila Sombria...$B$BPegue as costelas para mim e lhe darei algumas moedas pelo favor.', '', '', '', '', '', '', '', '', '', 'Fale com o Abercrombie no Refúgio dos Mendigos, na Floresta do Crepúsculo.', 0),
(26678, 'ptBR', 'Rumdumal', 'Encontre o Barril de Rumdumal do Barão Rezingada na Angra do Butim.', '<O Barão Rezingada suspira.> Mesmo com todas as minhas suspeitas sobre os planos do Firalião, nós não estamos preparados para encarar um ataque completo em duas frentes contra os Vela Sangrenta e os Mareforte. Vamos precisar de um pequeno milagre para segurar a Angra do Butim hoje.$b$bEu tenho guardado um barril de Rumdumal no meu quarto. Desça três lances de escada e entre na primeira porta à direita. Pode ignorar os avisos no barril... São as menores das preocupações que nós temos agora.', '', '', '', '', '', '', '', '', '', '', 0),
(26679, 'ptBR', 'Fale novamente com Rezingada', 'Leve o Rumdumal para o Barão Rezingada na Angra do Butim.', 'Tem alguma coisa acontecendo lá fora. Será que os Vela Sangrenta já estão aqui?$b$bÉ melhor levar o rumdumal do Rezingada. E bem rápido.', '', '', '', '', '', '', '', '', '', '', 0),
(26680, 'ptBR', 'Ogro ladrão', 'Devolva o Caixote do Abercrombie para o Abercrombie.', 'Há algumas semanas, fui colher plantas longe de casa e um bando de ogros me atacou! Eu fugi, mas tive que deixar para trás uma caixa com as minhas preciosas ferramentas e todas as plantas que colhi.$B$BDepois da perseguição, eles voltaram todos pimpões para o morro dos ogros no sul da Floresta do Crepúsculo. Tenho certeza que o caixote com as minhas ferramentas está lá.$B$BPor favor, $n, traga o caixote de volta para mim. Ele me faz muita falta.', '', '', '', '', '', '', '', '', '', 'Fale com o Abercrombie no Refúgio dos Mendigos, na Floresta do Crepúsculo.', 0),
(26681, 'ptBR', 'Carta ao alcaide', 'Entregue a Carta para Malaquias Ebanez, Prefeito de Vila Sombria, a pedido de Abercrombie.', 'Entregue este bilhete para Malaquias Ebanez, o alcaide da Vila Sombria.$B$BEu e ele somos velhos amigos... E quando ele souber o que você fez por mim... Ele vai ficar tão feliz quanto eu! Rá rá rá rá rá!', '', '', '', '', '', '', '', '', '', '', 0),
(26682, 'ptBR', 'A ameaça rastejante', 'Mate 7 Rastejantes Murchavinhas ou Coléricos Murchavinhas no pântano ao norte da Aldeia Muralha Verde.', 'Vadeoso é território da Horda, $n. Os humanos podem ter aquela ilhota e a barra que julgam tão preciosa, mas o pântano pertence a nós.$B$BNo dado tempo, o impasse com os humanos será resolvido. Por ora, devemos manter o domínio do nosso próprio território. Os murchavinhas brejeiros ao norte emergem do pântano para atacar qualquer coisa que chegue perto. E, como o pântano é nosso, não permitiremos que nossa própria terra lute contra nós!$B$BSe você está $Gdisposto:disposta; a servir à Horda, mate as feras brejeiras. Você será $Grecompensado:recompensada;.', '', 'Murchavinha morto', '', '', '', '', '', '', '', 'Fale novamente com Krog na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(26683, 'ptBR', 'Ora (direis) ouvir estrelas!', 'Encontre a Maria e convença-a a dar um espelho para o projeto do Vitório.', 'O Roda, um gnomo amigo meu, prometeu me ajudar a construir um aparelho para observar as estrelas. Segundo o esquema que ele desenhou, preciso arranjar antes de tudo um jeito de refletir a luz.$B$BEu me lembro de uma tal de Maria que ficou conhecida por circular por aí sempre carregando um espelho. Você poderia encontrá-la e ver se ela nos empresta esse espelho? Acho que ela morava na Floresta do Crepúsculo...', '', '', '', '', '', '', '', '', '', '', 0),
(26684, 'ptBR', 'O carniçal insano', 'Tome o Espelho de Maria do Carniçal Insano.', 'Aquele espelho era um dos meus mais preciosos tesouros até... o incidente. Depois do acontecido, eu o joguei fora atrás do celeiro. Um carniçal maluco costumava perambular por lá. Talvez ele tenha pegado o espelho. Dizem por aí que aquela criatura do demônio mora no Cemitério Jardins da Paz.', '', '', '', '', '', '', 'Carniçal Insano', '', '', 'Fale novamente com Vitório Prismado na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26685, 'ptBR', 'Lente de classe', 'Mate Zzarc\'Vul no morro ôgrico a sul da Floresta do Crepúsculo, e pegue o Monóculo do Ogro.', 'Agora só precisamos de mais um item para terminar o aparelho. O projeto do Roda pede um determinado tipo de lente. A única lente que eu conheço que é grande o suficiente é muito difícil de conseguir.$b$bTem um ogro chamado Zzarc\'Vul que mora no morro a sul da Floresta do Crepúsculo. Se puder, pegue o monóculo dele para usarmos como lente!', '', '', '', '', '', '', 'Zzarc\'Vul', '', '', 'Fale novamente com Vitório Prismado na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26686, 'ptBR', 'Ossos ambulantes', 'A Comandante Aldora Ebanez, da Vila Sombria, quer que você mate 5 Guerreiros Descarnados e 5 Magos Descarnados.', 'Há mortos-vivos ainda mais sórdidos com os quais temos que lidar, $n.$B$BO Cemitério Jardins da Paz, a sul da cidade, não é um lugar muito amistoso à noite. As ossadas que se levantam do chão são espertas o bastante para lembrar como manejar um machado ou lançar um feitiço.$B$BNem preciso explicar o quão perigosas isso as torna. Prossiga com cautela e lembre-se do quanto o povo da Vila Sombria vai sofrer se você falhar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Comandante Aldora Ebanez na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26687, 'ptBR', 'Reforços de Theramore', 'Siga para a Ilha Theramore no Pântano Vadeoso e fale com o Capitão Garrido Valente no quartel principal.', 'Hawthorne morto... meu filho assassinado... a situação nos Sertões está fora de controle, $n.$B$BVou assumir o comando do Forte Triunfo e tentar ajeitar as coisas. Pra isso, precisarei de reforços. Reforços que já deviam ter chegado de Theramore há semanas!$B$BSiga para Theramore, no Pântano Vadeoso, e passe um sabão no capitão Garrido Valente. Pra que diabos serve aquela maldita estrada cortando o pântano se não recebemos tropas nem equipamentos?', '', '', '', '', '', '', '', '', '', 'Siga para a Ilha Theramore no Pântano Vadeoso e fale com o Capitão Garrido Valente no quartel principal.', 0),
(26688, 'ptBR', 'Worgen na floresta', 'Mate 7 Worgens Nocturnos no Bosque Brilhante.', 'A escuridão parece ter se abatido inexoravelmente sobre a Floresta do Crepúsculo. E a missão do mestre Carevino é expulsar o mal e a heresia. Por meio de nossos esforços, o povo da Vila Sombria se mantém em segurança.$b$bVocê se acha $Gdigno:digna; o bastante para se juntar a nós?$b$bEu costumava pensar como você. Desiludido com a complacência da Vigília, me juntei ao mestre Carevino. Se você quer provar seu valor, não será apenas por meio de meras palavras.$b$bMostre suas habilidades contra os worgens Nocturnos no Bosque Brilhante. Vamos ver se você tem estofo o suficiente para caçar aqueles monstros.', '', '', '', '', '', '', '', '', '', 'Fale com Petrônio na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26689, 'ptBR', 'O Horto Pútrido', 'Mate 10 Tece-sombras Nocturnos no Horto Pútrido.', 'A infestação dos worgens se espalhou para além do Bosque Brilhante. Na região sul, nos limites da Vila Sombria, o Horto Pútrido se tornou refúgio de ainda mais criaturas selvagens.$B$BOs worgens de lá são mais astutos, $n, mas tão selvagens e maldosos quanto os outros. Eles invocam vultos sórdidos para despedaçar os inimigos à distância. Vá até o Horto Pútrido e mate os tece-sombras para garantir a segurança da cidade!', '', '', '', '', '', '', '', '', '', 'Fale com Petrônio na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26690, 'ptBR', 'Torpes e maculados', 'Mate 8 Presas Torpes Nocturnos e 8 Maculados Nocturnos no Descanso de Rolando.', 'Suas façanhas anteriores me convenceram de que você está $Gpronto:pronta; para lidar com os mais fortes worgens a infestar o bosque.$b$bDos worgens que se estabeleceram aqui, os presa torpe e os maculados são os mais perigosos. Eles ocuparam a mina e algumas cavernas ao sul.$b$bDá para ver de longe as luzes das fogueiras deles...', '', '', '', '', '', '', '', '', '', 'Fale com Petrônio na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26691, 'ptBR', 'Worgen na floresta', 'Entregue o bilhete do Petrônio para João Carevino.', 'Aqui está, $n. Leve esta carta para o Mestre Carevino.$b$b<Ele rapidamente pega um pedaço de pergaminho desbotado e lhe entrega.>$b$bMais algumas pessoas como você, e em breve superaremos a Vigília Noturna em número! Quem sabe então não conseguiríamos alcançar o objetivo que os poucos que somos hoje tanto almejam?', '', '', '', '', '', '', '', '', '', '', 0),
(26692, 'ptBR', 'Extinção dos Umbrapele', 'Mate um total de 20 Gnolls Umbrapele.', 'Agora que os orcs Rocha Negra ao sul do Lago Plácido não passam de cinzas e carne queimada, podemos nos concentrar no exército de gnolls Umbrapele no Vale Galardell, ao norte daqui.$B$BQuero que você siga para lá e mate todos, $n! Iniciar a Operação Extinção, soldado. Pela Companhia Bravo e pela Aliança!', '', 'Gnoll Umbrapele morto', '', '', '', '', '', 'Mate todos eles.', 'Danforth', 'Fale novamente com Danforth na Garganta do Barro Seco, que fica em Cristarrubra.', 0),
(26693, 'ptBR', 'A Torre Negra', 'Recupere a Chave de Ilgalar.', 'Nós demos sorte e obtivemos informações cruciais com os habitantes do vale. Aqueles dois atrás de nós, os Ranthals, me disseram que os gnolls do Vale Galardell estão sendo controlados por um mago poderoso na torre de Ilgalar. O problema é que a torre está protegida por um campo de força mágico.$B$BAntes de mais nada, precisamos conseguir a chave que você vai precisar pra entrar lá. Uma vez lá dentro, encontre Mordente, o general gnoll. Mate o general Mordente e pegue a chave.$B$BEu vou manter contato.', '', '', '', '', '', '', '', 'Mordente era um trouxa.', 'John J. Keeshan', 'Fale com John J. Keeshan na Garganta do Barro Seco, que fica em Cristarrubra.', 0),
(26694, 'ptBR', 'O grão-mago Doane', 'Mate o Grão-mago Doane.', '<O kit de campanha da Companhia Bravo começa a vibrar.>$B$BBom trabalho, $ggaroto:mocinha;. Tenho informações vitais pra você. O mago na torre é um humano chamado Doane. O traidor safado está trabalhando para os orcs Rocha Negra. Eu quero ele morto.$B$BUse a chave de Ilgalar e se infiltre na torre. Siga para o topo e mostre a Doane o que a Companhia Bravo faz com traidores.$B$BApresente-se na Garganta do Barro Seco quando tiver cumprido a missão.$B$BCâmbio e desligo.', '', 'Grão-mago Doane confrontado', '', '', '', '', 'John J. Keeshan', '', '', 'Fale com John J. Keeshan na Garganta do Barro Seco, que fica em Cristarrubra.', 0),
(26695, 'ptBR', 'Preparar para decolar', 'Pegue as Bombas de Mão de Narkk na Capitania do Velho Porto, na Angra do Butim.', 'Eu tenho uma ideia, mas você vai precisar andar um pouco. Por serem um cartel goblin, os Saqueadores Aguanegra certamente têm um monte de explosivos à mão. Na verdade, eu sei que, de fato, nosso amigo Narkk guarda uma caixa cheia de explosivos nos fundos da loja dele, na Capitania do Velho Porto.$b$bPega lá os explosivos e traz pra mim. E torça pra não explodirem no caminho.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Rezingada na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26696, 'ptBR', 'O chamado de Kalimdor', 'Entre no barco que vai da Angra do Butim à Vila Catraca. Chegando lá, fale com o Gasganete.', 'Olá, você não teria visto um peixe mais ou menos desse tamanho? Com nadadeiras curtas? Reponde pelo nome de Steve? Ele é azul?$b$bDeixa pra lá, eu vou continuar procurando.$b$bNa verdade, eu estou aqui por outro motivo. O Chefe Krog, que fica em Vadeoso, está procurando por sangue novo. Alguém que ajude os Pedramalho a não serem dominados. Você parece forte o suficiente...$b$bEspere pelo próximo barco na beira do píer. Depois, vá nele até a Vila Catraca. Gasganete poderá ajudá-$glo:la; a partir de lá.$b$bSteve? Steve!', '', '', '', '', '', '', '', '', '', 'Fale com Gasganete na Vila Catraca, que fica nos Sertões Setentrionais.', 0),
(26697, 'ptBR', 'A jornada final dos Mareforte', 'Fale com Kebok na Angra do Butim para montar em uma Mantícora Audaz. Depois, use as bombas de mão para matar 85 Tripulantes Mareforte e destruir 6 Barcos de Assalto da Mareforte.', 'Nós não vamos conseguir sobreviver a esse ataque com todos esses piratas worgens invadindo o porto pelo norte. Por sorte, parece que eles não têm canhões. Se nós conseguirmos tirar você do porto, você poderá atacá-los do céu.$b$bKebok, assistente do mestre de voo da horda, está logo ali. Fale com ele e diga que você vai precisar da mantícora mais corajosa que ele tiver.$b$bE leve umas bombas de mão com você. Você vai precisar do máximo que puder pra parar os barcos de guerra!', '', '', 'Barco de Assalto da Mareforte Destruído', '', '', '', '', '', '', 'Fale novamente com o Barão Rezingada na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26698, 'ptBR', 'Procurando o Chifre do Mar', 'Fale com o Mestre de Frota Chifre do Mar na Angra do Butim.', 'Quando os Mareforte chegaram aqui, o Chifre do Mar pegou a primeira arma que viu e pulou daqui de cima. Você vai encontrá-lo lá embaixo, provavelmente fazendo novos orifícios na cabeça daqueles worgens.$b$bDesce lá e dá uma mãozinha. Eu vou ficar motivando nossas tropas daqui de cima.', '', '', '', '', '', '', '', '', '', '', 0),
(26699, 'ptBR', 'A virada da Mareforte', 'Mate 10 Saqueadores Mareforte na Angra do Butim.', 'Os Mareforte estão por toda parte! Temo que os bordoeiros da Angra do Butim comandados pelo Barão não consigam dar conta de todos eles.$b$bJá que você tá aqui na luta, por que não me ajuda a dar cabo de alguns?$b$bQuando tiver terminado, nem se preocupe em vir falar comigo. Eu provavelmente estarei bem ocupado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Rezingada na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26700, 'ptBR', 'A (má) Sorte da Donzela', 'Mate 8 Corsários da Vela Sangrenta na Angra do Butim.', 'Ouvi falar que esse barco aqui é o Sorte da Donzela. Você não foi o capitão dessa coisa? Então você deve saber andar aqui dentro.$b$bOs Mareforte são nossa principal preocupação, mas nós também não precisamos tomar tiros desnecessários daqueles canhões. Use essa corda aqui atrás e dê um jeito em alguns desses corsários enfurecidos. Fale com o Barão quando tiver terminado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Rezingada na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26701, 'ptBR', 'Voo para a Muralha Verde', 'Fale com o Bragok na Vila Catraca para voar até a Aldeia Muralha Verde. Depois, fale com Krog.', 'É o seguinte, eu não morro de amores pela Horda, mas também não tenho nenhum ódio especial por vocês.$b$bO seu dinheiro vale como qualquer outro.$b$bAquele ogro de duas cabeças e o peixe de estimação dele deixaram dinheiro comigo pra cobrir as suas despesas de viagem. Parece que você precisa procurar um tal de Krog lá em Vadeoso. O melhor caminho pra lá é pelo céu. Fala com o mestre de voo, o Bragok, que ele te manda pra lá. A viagem vai sair de graça, já que o seu amigo já pagou por você.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Krog na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(26702, 'ptBR', 'Voo para Theramore', 'Fale com o Bragok na Vila Catraca para voar até Theramore. Depois, fale com Calia Hastings.', 'É o seguinte, eu não morro de amores pela Aliança, mas também não tenho nenhum ódio especial por vocês.$b$bO seu dinheiro vale como o de qualquer outro. Dependendo, vale até mais.$b$bA Jeyne deixou algum dinheiro comigo pra cobrir as suas despesas de viagem. Parece que você precisa procurar uma tal de Calia Hastings lá em Vadeoso. O melhor caminho pra lá é pelo céu. Fala com o mestre de voo, o Bragok, que ele te manda pra lá. A viagem vai sair de graça, já que a sua amiga já pagou por você.', '', '', '', '', '', '', '', '', '', 'Fale com Calia Hastings em Theramore, que fica no Pântano Vadeoso.', 0),
(26703, 'ptBR', 'A derrota da Vela Sangrenta', 'Fale com Kebok na Angra do Butim para pegar uma Mantícora. Depois, mate o Mestre de Frota Firalião.', 'Nós quase ganhamos o dia hoje, principalmente graças a você. Falta, porém, uma tarefa a ser cumprida... Matar o Mestre de Frota Firalião.$b$bParece que a maior parte da tripulação do Firalião já está morta, mas eu conheço aquele velho lobo do mar bem o suficiente pra saber que ele não vai se entregar. Não, ele está escondido na cabine, pronto pra afundar com o navio.$b$bFale novamente com Kebok para pegar uma mantícora. Eu vou tentar cessar os tiros de canhão enquanto você estiver lá dentro.', '', 'Mate o Mestre de Frota Firalião', '', '', '', '', 'Mestre de Frota Firalião', '', '', 'Fale novamente com o Barão Rezingada na Angra do Butim, que fica no Cabo do Espinhaço.', 0),
(26705, 'ptBR', 'A Cidade Portátil Tracking Event', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(26706, 'ptBR', 'Fim de jogo', 'Quando o Tobias der o sinal, monte em um hipogrifo e destrua a Belonave da Horda.', 'Temos que nos livrar daquela canhoneira voadora, senão não teremos a menor chance de escapar.$B$BO plano é o seguinte: nos velhos tempos, Porto Quilha já teve lá seus rebeldes. Então, consegui pegar muitos explosivos incendiários em um de nossos armazéns.$B$BVamos atacar com uma esquadrilha que seja pequena o bastante para passar despercebida, como os hipogrifos dos elfos noturnos.$B$BTobias dará o sinal quando chegar a hora de partir.', '', 'Belonave destruída', '', '', '', '', '', '', '', 'Fale novamente com Lorna Crowley no Porto Quilha, que fica em Guilnéas.', 0),
(26707, 'ptBR', 'Uma trepadeira mortal', 'Colete 5 pedaços de Cadavéreas.', 'Eu preciso juntar muita cadavérea para o mestre Espargosa fazer suas concocções. Essa planta é difícil de achar, mas não podemos deixar nossos estoques desabastecidos.$B$BA cadavérea é dura de roer... Se não tomar cuidado, ela pega você antes que você a pegue! Mas, se você quiser ajudar, eu lhe pagarei com prazer pelas que você me trouxer.$B$BTem muita cadavérea nas terras dos Figueira, a sudeste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Aprendiz Zembucha na Floresta do Crepúsculo.', 0),
(26708, 'ptBR', 'AHHHHHHHHHHHH! AHHHHHHHHH!!!', 'Use o Tanque de Cerco da Companhia Bravo para matar 200 soldados Rocha Negra.', 'Estou aqui pra ajudar você e a Companhia Bravo a dar um fim nessa bagunça. Você deve usar um tanque de cerco da Companhia Bravo e limpar o caminho até o Posto do Keeshan do outro lado do vale, ao norte daqui.$B$BEssa é uma situação de alerta máximo, soldado. Os orcs Rocha Negra já conhecem a sua localização e estão enviando uma tropa numerosa para se encontrar com você de frente. Acabe com eles e não se preocupe com a sujeira.$B$BVejo você do outro lado. Que a Luz tenha piedade de sua alma.', '', '', '', '', '', '', '', '', '', 'Fale com o Coronel Troteman no Posto do Keeshan, que fica em Cristarrubra.', 0),
(26709, 'ptBR', 'O trono de pedra', 'Procure Therazane no Trono de Therazane.', 'Vou voltar para o meu trono. Não quero ver mais qualquer membro da Harmonia Telúrica, mas você ainda é $Gbem-vindo:bem-vinda; aqui, $r. Caso você queira nos ajudar a reconstruir nosso reino, podemos devolver o favor.$B$BTudo em seu tempo.', '', '', '', '', '', '', '', '', '', '', 0),
(26710, 'ptBR', 'Perdido no abismo', 'Encontre o Cascalho dentro dos Abismos Esfacelados e conduza-o para fora em segurança.', 'O Cascalho se perdeu de novo, desta vez no fundo dos Abismos Esfacelados.$B$BA sorte dele é que os litovermes não vão gastar energia para atacar uma criatura tão pequena, mas é uma questão de tempo até que ele se aproxime demais de um e acabe devorado. O que quer que o tenha atraído para lá certamente não vale a pena.$B$BAcho que ele gosta de você. Por favor, desça ao abismo e tire-o daqueles túneis. Traga-o para brincar em terrenos mais seguros.', '', 'Cascalho conduzido em segurança', '', '', '', '', '', '', '', 'Fale novamente com o Guarda-pirita no Trono de Therazane.', 0),
(26711, 'ptBR', 'Indo pro banco', 'Fale com o Caixa do BCK no Banco Central de Kezan, em Kezan.', 'Falaí, neném. Suave na nave? Tá prontinha pra festa? Não?! Olha, cê sabe que eu te amo, né? Então nem sei como dizer isso, mas... Acho melhor você dar um pulo na cidade e comprar uma beca nova pra festa.$B$BNão me olha assim... você quer ficar gaaaata, não quer? Não quer ficar super arrumaaaada pra mim? Eu sou seu queridão ou não sou?$B$BPor que você não dá um pulo no banco e saca umas paçoquinhas? Melhor, um montão de paçoquinhas! Você não quer comprar aquelas porcarias xing-ling, né?', '', '', '', '', '', '', '', '', '', '', 0),
(26712, 'ptBR', 'Indo pro banco', 'Fale com o Caixa do BCK no Banco Central de Kezan, em Kezan.', 'Oi, gatinho. Tá pronto pra festa?$B$BNão?! Cê sabe que eu te amo, né? Acho melhor você dar um pulinho na cidade e comprar uma roupinha nova bacana pra festa.$B$BNão me olhe assim... você não quer causar boa impressão? Não quer ficar bonitão pra mim? Afinal, eu sou sua gatinha!$B$BPorque você não dá um pulo no banco e saca umas paçoquinhas? Melhor, um montão de paçoquinhas! Não compre nenhuma porcaria de camelô!', '', '', '', '', '', '', '', '', '', '', 0),
(26713, 'ptBR', 'Confronto final no Mirante de Pedra', 'Mate Tharil\'zun e Gath\'Ilzogg.', 'Só resta o alto comando Rocha Negra, $n. Estão todos escondidos na Bastilha Mirante de Pedra, justo ao sul de nossa posição aqui no Posto do Keeshan. Quero que você e o restante da Companhia Bravo invadam o Mirante de Pedra e deem fim à invasão de orcs Rocha Negra.$B$BNão quero sobreviventes, $n.', '', '', '', '', '', '', '', 'É uma armadilha! Saia já daí!', 'Coronel Troteman', 'Fale com o Coronel Troteman no Posto do Keeshan, que fica em Cristarrubra.', 0),
(26714, 'ptBR', 'Fulgor Negro, prole do Quebra-mundos', 'Use o Chifre de Evocação para chamar Fulgor Negro. Derrote Fulgor Negro.', 'Depois que a voz de Troteman se cala, o mundo ao seu redor fica estranhamente silencioso. Você vê um dragão negro à distância!', '', 'Fulgor Negro derrotado', '', '', '', '', 'Coronel Troteman', '', '', 'Apresente-se ao Coronel Troteman no Posto do Keeshan, que fica em Cristarrubra.', 0),
(26717, 'ptBR', 'Noel, o worgen', 'Examine o Monte de Terra na Fazenda dos Figueira.', 'Meus camaradas no Monte Corvo estão muito preocupados em curar os worgens selvagens destas florestas. O quadro propriamente dito não pode ser revertido, mas a lucidez pode ser restaurada naqueles que não tenham sido muito afetados.$B$BMuitos aqui já não podem mais ser ajudados, mas estamos sempre atentos aos que ainda guardam vestígios da mente... Ligações com suas vidas anteriores.$B$BEu vi um worgen solitário perambulando pela Fazenda dos Figueira, cavando em um monte de terra entre as casas... Você poderia verificar se ele deixou cair alguma coisa naquele monte de terra?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Aprendiz Zembucha na Floresta do Crepúsculo.', 0),
(26719, 'ptBR', 'Entrega para o Mestre Espargosa', 'Entregue o Pacote de Cadavérea para Olívio Espargosa no Monte Corvo.', 'O Mestre Espargosa precisa ser informado disso imediatamente.$B$BLeve este pacote de cadavérea até o acampamento do Monte Corvo, seguindo pela estrada, e conte ao Mestre o que presenciamos na Fazenda dos Figueira.', '', '', '', '', '', '', '', '', '', '', 0),
(26720, 'ptBR', 'Praga que pega', 'Procure o Worgen Espreitador na Quinta dos Aguiar e use a Ampola de Espargosa para entorpecê-lo.', 'O que fazemos aqui não é uma cura. A transformação não pode ser revertida, mas a mente...$B$BA mente pode ser restaurada por meio de alquimia, se ainda restar um mínimo de lucidez. Acho que esse worgen que você viu ainda está lutando para manter a consciência, $n. Temos que encontrá-lo.$B$BCaso ele tenha fugido da Fazenda dos Figueira, procure-o na Quinta dos Aguiar, ao sul. Ele pode estar escondido em uma das casas.$B$BChegue bem perto e injete esta ampola nele para tranquilizá-lo.', '', 'Worgen Espreitador capturado', '', '', '', '', 'Worgen Espreitador', '', '', 'Fale novamente com Olívio Espargosa no Monte Corvo, que fica na Floresta do Crepúsculo.', 0),
(26721, 'ptBR', 'Aracnofobia', 'Retire 8 Glândulas de Peçonha da Viúva Negra das Viúvas Negras.', 'O-o Me-Mestre Espargosa precisa de muitos reagentes para fazer soro. Ele pediu que eu recolhesse todo o material.$B$BA maior parte não é tão difícil... Quero dizer, a cadavérea é bem chatinha de pegar, mas não tanto quanto a peçonha da viúva negra. Você viu essas aranhas por aqui? Cada filhote é do tamanho de um homem. Mesmo armado, eu não dou conta de caçá-las!$B$BÉ simplesmente terrível demais para mim. Se você cuidar disso em meu lugar, eu pagarei pelo serviço com prazer! As viúvas negras perambulam pelas florestas a leste, logo acima da estrada.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Medrisco no Monte Corvo, que fica na Floresta do Crepúsculo.', 0),
(26722, 'ptBR', 'Enterrado fundo', 'Procure a Cimeira Forjada a Luz dentro do túnel sob as Catacumbas do Bosque da Aurora.', '<Você encaixa o arco no bastão, e o artefato está quase completo. Uma grande lacuna ainda permanece no centro da extremidade do símbolo sagrado.>$B$B<Mais uma vez você sente que o artefato arrasta o seu braço, puxando você até um vão na parede que dá acesso a um túnel sinuoso. A última parte deve estar lá dentro.>', '', '', '', '', '', '', '', '', '', '', 0),
(26723, 'ptBR', 'O destino de Morbídio Vil', 'Procure por vestígios do Morbídio Vil no Morro dos Esquecidos.', 'A última coisa de que me lembro antes de me perder na floresta é do Morbídio Vil, um sórdido necromante. Por causa dele esta terra está infestada com tantos mortos-vivos odiosos.$B$BEu cheguei a pedir ajuda a um aventureiro para dar cabo do Morbídio. E achei que ele tinha conseguido! Mas a Irmã Elsington me disse que a terra ainda está repleta de carniçais e espectros arrancados dos túmulos.$B$BO Morbídio Vil deveria ter exalado seu último suspiro na casa do Morro dos Esquecidos, a norte do Cemitério do Monte Corvo. Vá até lá e descubra o que aconteceu com ele...', '', 'Restos mortais de Morbídio Vil', '', '', '', '', '', '', '', 'Fale novamente com Noel Figueira no Monte Corvo, que fica na Floresta do Crepúsculo.', 0),
(26724, 'ptBR', 'O lich espreitador', 'Fale com a Irmã Elsington.', 'Todos aqui têm a mesma suspeita: o Morbídio segue vivendo na morte em vida... E pode estar ainda mais poderoso do que antes. Um necromante foi abatido, mas um lich pode ter ascendido em seu lugar. E continua a devastar esta terra.$B$BEu me lembro de como era a Floresta do Crepúsculo antes disso tudo, $n. Eu me lembro de céus azuis e bosques tranquilos. Não podemos deixar isso continuar! Precisamos deter o Morbídio Vil de uma vez por todas.$B$BFale com a Irmã Elsington. A intuição dela pode guiar você até o Morbídio, e lhe mostrar como derrotá-lo.', '', '', '', '', '', '', '', '', '', '', 0),
(26725, 'ptBR', 'Guiado pela Luz', 'Encontre o Bastão Forjado a Luz no Cemitério de Monte Corvo.', 'O Noel está certo. Consigo sentir a presença de um poderoso mal entranhado no Cemitério de Monte Corvo. O mal está à espreita naquelas catacumbas, e Morbídio Vil é a fonte de tudo.$B$BVocê vai precisar do poder da Luz para derrotá-lo, $n. O Noel mencionou que os heróis que mataram Morbídio pela primeira vez usaram um artefato de ferro forjado a luz, impregnado com poder sagrado. E esse artefato ainda está aqui!$B$BEu posso senti-lo, como uma centelha de luz entre as trevas. Procure-o no Monte Corvo, e deixe a Luz guiá-$Glo:la; nas buscas.', '', '', '', '', '', '', '', '', '', '', 0),
(26726, 'ptBR', 'Retorno triunfante', 'Apresente-se ao Magistrado Salomão na Vila Plácida, que fica nas Montanhas Cristarrubra.', 'Volte para a Vila Plácida e informe Salomão de que a invasão Rocha Negra foi impedida. Faça-o compreender o preço que pagamos pela nossa liberdade. Diga a ele que perdemos cinco de nossos maiores heróis para salvar Cristarrubra e também Ventobravo.$B$BVocê é $go último:a última; sobrevivente da Companhia Bravo, $n. É responsabilidade sua manter o legado da Companhia vivo.$B$B$gDispensado:Dispensada;.', '', '', '', '', '', '', '', '', '', '', 0),
(26727, 'ptBR', 'A vingança do embalsamador', 'Mate o Suturino na Vila Sombria.', 'Você não foi $Go primeiro:a primeira; idiota a cair na lábia do Abercrombie! Aquele velho gagá é conhecido entre nós como O Embalsamador. Ele é um vil necromante e representa uma praga para a cidade.$B$BE agora, costurada e vivificada pelo material que você fez o favor de levar para ele, certamente uma das terríveis criações de Abercrombie está se aproximando de nós!$B$BA criatura malévola deve chegar aqui em pouco tempo! Se você ainda tiver coração, $n, ajude a Vigília Noturna a deter a abominação e salvar a cidade!', '', '', '', '', '', '', 'Suturino', '', '', 'Fale novamente com o Lorde Malaquias Ebanez na Prefeitura de Vila Sombria, na Floresta do Crepúsculo.', 0),
(26728, 'ptBR', 'O chamado ao heroísmo: Floresta do Crepúsculo!', 'Apresente-se à Comandante Aldora Ebanez na Vila Sombria, que fica na Floresta do Crepúsculo.', '$n, os cidadãos da Floresta do Crepúsculo estão precisando desesperadamente da sua ajuda! Recebi uma carta com um pedido de ajuda da comandante Aldora Ebanez, líder da Vigília Noturna.$B$BPara chegar à Vila Sombria você deve cruzar a ponte a sudoeste das Montanhas Cristarrubra. A Floresta do Crepúsculo fica logo após a ponte. Então, basta seguir a estrada até a Vila Sombria. Cuidado com as criaturas selvagens à espreita pelos campos!', '', '', '', '', '', '', '', '', '', '', 0),
(26729, 'ptBR', 'Elementais da água', 'Pegue 6 Braçadeiras dos Elementais da Água.', 'Eu cheguei à Selva para estudar um lugar chamado Altar de Naias. Mas fiz a péssima escolha de ir contra as ideias do Coronel Kurzen, o que me rendeu vários anos naquela jaula. Agora que saí de lá, acho que eu posso continuar com meus estudos iniciais.$b$bO altar fica na ilha a oeste daqui, ao sul de Zul\'Kanda. Pegue algumas braçadeiras dos elementais da água da ilha.$b$bAh, e você pode usar esse dispositivo quando tiver terminado. Não precisa andar o caminho todo de volta.', '', '', '', '', '', '', '', '', '', 'Use a Bola de Cristal de Emerine para evocar Emerine Junis na Selva do Espinhaço Setentrional.', 0),
(26730, 'ptBR', 'Você pode tirar o murloc do oceano...', 'Obtenha 6 vidros de Sal Marinho dos murlocs Umbrânquia na Selva do Espinhaço Setentrional.', 'Preciso de alguma coisa para acessar o poder elemental bruto desses braceletes... Alguma coisa forte e abrasiva, mas que seja do mar.$b$bOs murlocs Umbrânquia saíram do mar e foram morar em terra firme, mas ainda carregam sempre uns vidros de sal marinho com eles. O que eles fazem com isso eu não sei, mas vai servir para os nossos estudos. Você encontrará os Umbrânquia na clareira ao sul do Acampamento dos Rebeldes e a leste das Ruínas de Bal\'lal.', '', '', '', '', '', '', '', '', '', 'Use a Bola de Cristal de Emerine para evocar Emerine Junis na Selva do Espinhaço Setentrional.', 0),
(26731, 'ptBR', 'O altar de Naias', 'Use a Dádiva de Naias para evocar Naias. Depois, pegue o Coração de Naias.', 'O sal que você trouxe foi suficiente para ativar os encantamentos inatos do bracelete. Eu peguei esses encantamentos e combinei-os em um símbolo de evocação... Uma oferenda, se você preferir chamar assim.$b$bVolte à Ilha de Naias e coloque a oferenda no altar. Me chame novamente quando você tiver o coração de Naias.', '', '', '', '', '', '', '', '', '', 'Use a Bola de Cristal de Emerine para evocar Emerine Junis na Selva do Espinhaço Setentrional.', 0),
(26732, 'ptBR', 'Remédio do mal', 'Obtenha 7 Remédios da Mata no Complexo do Kurzen.', 'Eu acho que os Curandeiros do Kurzen estão distribuindo mais do que remédios por aí. Kurzen precisava de um jeito de acabar com a insubordinação, e um elixir disfarçado de remédio é o jeito perfeito de fazer isso.$B$BNós precisamos desses tais remédios para pesquisar. Procure no Complexo do Kurzen, a sudeste. Os curandeiros e os guerrilheiros da selva dele devem estar levando algumas doses com eles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Irmão Nimetz no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26733, 'ptBR', 'Amostra de controle', 'Consiga 7 amostras de Sangue de Basilisco da Serra dos Cristais.', '<O Irmão Nimetz analisa as amostras que você deu pra ele.>$b$bIsso... isso é só sangue de basilisco!$b$bNa verdade, a maior parte é sangue de basilisco. Eles misturaram alguma coisa aqui. Eu vou precisar de uma amostra de controle para fazer uma comparação correta.$b$bEles provavelmente conseguiram sangue dos basiliscos da Serra dos Cristais, que ficam a leste do complexo. Traga umas amostras do sangue puro e vou descobrir de que é feito este elixir.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Irmão Nimetz no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26734, 'ptBR', 'A fonte da loucura', 'Obtenha uma Pedra Azul Sussurrante com as tropas que ficam no Arsenal.', 'Depois de vaporizar o sangue do elixir, descobri um sedimento incomum. Parece um tipo de cristal azul...$b$b<O Irmão Nimetz consulta as anotações dele.>$b$bIsso não é cristal azul canoro... Não é um estilhaço azul pulsante...$b$b<Ele pula algumas páginas.>$b$b... Não é um pedaço de Olho da Mente. Nada, isso não é nada que já tenha sido visto aqui na Selva do Espinhaço. Se alguém tiver mais dessa substância, eu vou querer. Procure mais um pouco disso com as tropas de patente mais altas do Kurzen, no fundo da caverna deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Irmão Nimetz no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26735, 'ptBR', 'O destino de Kurzen', 'Pegue os Registros de Prisão do Complexo de Kurzen e o Dossiê dos Oficiais do Complexo de Kurzen.', 'Olá, $c.$b$bNós somos soldados de Ventobravo e rebeldes do Complexo do Kurzen, um grande posto avançado que fica a sudeste daqui. Estávamos sob o comando do Coronel Kurzen até ele e os soldados próximos a ele começarem a ficar loucos...$b$bNós nos rebelamos, acampamos aqui e nos opusemos ao Kurzen. Agora, as minhas fontes estão dizendo que o Kurzen desapareceu. Eu confio nas minhas fontes, mas eu prefiro ouvir isso de mais alguém. Vá até o complexo e encontre algum documento falando sobre o destino dele.', '', '', '', '', '', '', 'Coronel Kurzen', '', '', 'Fale novamente com o Tenente Doren no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26736, 'ptBR', 'Poupados da loucura', 'Resgate Berrin Penaquente, Emerine Junis e Osborn Obnótico de dentro do Complexo do Kurzen.', 'A morte de Kurzen é um alívio, mas o mais importante e talvez mais urgente é a possibilidade de alguns aliados em potencial estarem presos dentro do complexo.$b$bEu não me importo com o que esteja escrito no registro, eu sei EXATAMENTE o motivo de aqueles 3 terem sido trancafiados: a recusa em seguir ordens. Eles devem ter sido poupados da loucura, assim como eu e meus companheiros aqui, e foram encarcerados por confrontar as ordens.$b$bVocê precisa achá-los, $n. Encontre-os e envie-os para cá.', '', 'Resgate de Berrin Penaquente', 'Resgate de Emerine Junis', 'Resgate de Osborn Obnótico', '', '', '', '', '', 'Fale novamente com o Tenente Doren no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26737, 'ptBR', 'Acabando com o legado de Kurzen', 'Mate o Chefe Anders, o Chefe Gaulus, a Chefe Miranda e o Chefe Esquivel dentro do Arsenal.', 'Agora que já removemos nossos aliados, chegou a hora de fazer a incursão final no Complexo do Kurzen. Eles nunca ficarão tão fracos quanto estão agora e, com a sua ajuda, nós podemos enfraquecê-los definitivamente.$b$bQuatro nomes estavam listados no dossiê dos oficiais: Anders, Gaulus, Miranda e Esquivel. Eles são os oficiais de patente mais alta no complexo. Matar os quatro será um golpe devastador para as forças de Kurzen.$b$bVá com honra, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Doren no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26738, 'ptBR', 'Recém-chocado', 'Leve o Raptinho Batecauda para o Cabo Malta no Acampamento dos Rebeldes, na Selva do Espinhaço Setentrional.', 'Ao revirar as coisas desse soldado, você vê um raptor recém-nascido olhando para você. Será que ele estava seguindo esse soldado do Kurzen o tempo todo?$b$bVocê percebe que ele está estudando você, as suas expressões e imitando seus movimentos.$b$bO raptinho batecauda acabou de formar um laço com você.$b$bTalvez alguém no Acampamento dos Rebeldes saiba o que fazer com um filhote de raptor.', '', '', '', '', '', '', '', '', '', 'Leve o Raptinho Batecauda para o Cabo Malta no Acampamento dos Rebeldes, na Selva do Espinhaço Setentrional.', 0),
(26739, 'ptBR', 'Eu acho que ela está com fome', 'Mate Basiliscos da Serra dos Cristais na Selva do Espinhaço Setentrional e deixe o Raptor Batecauda dar 40 mordidas na carne de basilisco.', 'A sua raptorazinha parece faminta. Se você quiser mantê-la, procure alguma coisa para ela comer. Os batecauda costumam atacar os basiliscos da Selva do Espinhaço, que costumam ficar a leste, além do Complexo do Kurzen.$b$bEla ainda não tem força para abater um basilisco sozinha, mas eu tenho certeza de que ela comeria carne fresca de basilisco.', '', 'Mordidas na carne de basilisco', '', '', '', '', '', '', '', 'Fale novamente com o Irmão Nimetz no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26740, 'ptBR', 'A cozinha de Krazek', 'Leve a Caçarola Meia-boca do Krazek para o Krazek.', 'Eu faço quase toda a comida do acampamento. Isso costumava me dar muito trabalho, até que eu comprei uma panela mecânica de um mercador goblin. A panela é maravilhosa! Ela me poupou horas e horas... até que ela quebrou!$B$BVocê poderia levá-la de volta para o goblin e pedir que ele a conserte? O nome dele é Krazek. A última coisa que eu soube dele é que estava no acampamento de caça do Rosarães ao sul.', '', '', '', '', '', '', '', '', '', 'Fale com Krazek na Expedição do Rosarães, que fica na Selva do Espinhaço Setentrional.', 0),
(26742, 'ptBR', 'Conhecimento dos Sanguescalpo', 'Adquira um Totem Sanguescalpo de um Xamã Sanguescalpo.', 'Eu não consegui te agradecer apropriadamente por me salvar.$b$bObrigado, $n.$b$bEu ainda estou um pouco cansado por ter ficado preso, mas gostaria de pedir para tu me ajudar com os meus estudos. Como xamã do clã Martelo Feroz, estou muito interessado nas práticas xamanísticas da tribo Sanguescalpo.$b$bA magia deles parece ter divergido para uma direção muito interessante. Se eu conseguisse um dos totens que os xamãs deles usam, poderia começar meus estudos. Tu os encontrará nas Ruínas de Bal\'lal, na costa sudoeste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Berrin Penaquente no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26743, 'ptBR', 'Sagrado para os Sanguescalpo', 'Consiga um Ícone de Tsul\'Kalu, um Ícone de Mahamba e um Ícone de Pogeyan dos trolls Sanguescalpo nas Ruínas de Tkashi.', 'Ahh... esses devem ser os nomes das criaturas totêmicas deles - os animais aos quais eles atribuem os espíritos. Vamos ver... Mahamba como água, Tsul\'Kalu como terra, Pogeyan como... ar? Fogo? Eu não consigo decifrar esta parte. $b$bPreciso de mais informações sobre os espíritos deles. Os Sanguescalpo têm um acampamento aqui perto, nas Ruínas de Tkashi. Talvez tu consiga encontrar mais alguma informação por lá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Berrin Penaquente no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26744, 'ptBR', 'Raízes profundas', 'Consiga a Tabuleta de História dos Sanguescalpo nas Ruínas de Bal\'lal, que ficam na Selva do Espinhaço Setentrional.', 'Em um assunto separado, estou juntando uma coletânea de histórias e lendas trólicas para um... projeto pessoal. Eu estava pensando que talvez você possa me ajudar a encontrar algumas.$b$bOs Sanguescalpo nas Ruínas de Bal\'lal, que ficam na costa sudoeste, guardam uma grande tabuleta documentando algumas das histórias deles. Obviamente, eu pagarei por qualquer uma que você conseguir trazer.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Cabo Malta no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26745, 'ptBR', 'O crânio favorito', 'Fale com Osborn Obnótico no Acampamento dos Rebeldes e mostre o novo crânio do seu Raptinho Batecauda.', 'Seu raptor de estimação encontrou um novo brinquedo: um crânio em uma pilha de crânios de trolls.$b$bVocê não consegue entender o que torna esse crânio diferente dos outros, mas, por alguma razão, ela não larga o osso.$b$bOsborn Obnótico, o gnomo que você salvou no Complexo do Kurzen, é um especialista em história e fisiologia trólica. Talvez ele consiga saber o que há de tão especial nesse crânio.', '', '', '', '', '', '', '', '', '', 'Fale com o Osborn Obnótico no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26746, 'ptBR', 'Faro para esse tipo de coisa', 'Use o seu Raptinho Batecauda para farejar 8 Fetiches Tkashi.', '<Osborn olha o crânio novamente.>$b$bEm vida, ele foi forte e poderoso, um senhor entre os trolls. Com a nossa ajuda, ele pode ser um senhor novamente. Os catadores Sanguescalpo que andam pelas ruínas a sudoeste daqui guardam fetiches mágicos que podem nos ajudar. Eles escondem esses artefatos debaixo da terra. Use o seu filhote para encontrar os fetiches, $n... Depois, traga-os para cá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Osborn Obnótico no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26747, 'ptBR', 'Um espécime físico', 'Pegue o Corpo do Gan\'zulah em Zul\'Kanda.', 'A alma está pronta, mas o corpo não. Para um crânio tão bem formado e maravilhoso como esse, nós precisaremos de um corpo adequado.$b$bO chefe dos Sanguescalpo, Gan\'zulah, conquistou o trono dele com força bruta. Se ele ainda estiver vivo, você o encontrará em Zul\'Kanda, a oeste daqui.$b$bPegar o corpo dele não será nada fácil, mas não é nada que $gum:uma; $c poderos$go:a; como você não consiga dar conta. Traga-o para mim quando conseguir.', '', '', '', '', '', '', 'Gan\'zulah', '', '', 'Fale novamente com Osborn Obnótico no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26748, 'ptBR', 'Sangrelorde Mandokir', 'Entregue o Fragmento de Ovo de Raptor Batecauda para o Sangrelorde Mandokir no Acampamento dos Rebeldes.', '$R. Você acabou de ressuscitar o seu pior pesadelo. Você não achou que eu seria seu amigo, achou, $r? Ah, hahahahaah!$b$bVocê serviu ao seu propósito. Eu voltei para o mundo dos vivos graças a você. Por isso, em vez de matá-$glo:la;, eu farei um acordo com você.$b$bDê a raptor para mim.$b$bVocê já deve ter percebido que ela não é um raptor qualquer. Eu preciso de um substituto para Ohgan. Faça isso ou você e o gnomo sofrerão a minha ira.', '', '', '', '', '', '', '', '', '', '', 0),
(26749, 'ptBR', 'Sacerdotisa Thaalia', 'Fale com a Sacerdotisa Thaalia no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 'Obrigado, $n. Eu sei que você não precisava salvar a minha vida.$b$bO retorno do Sangrelorde Mandokir é uma notícia horrível. Ele foi morto em Zul\'Gurub há muitos anos atrás e nós achamos que seria o último da espécie dele. Os trolls de Zul\'Gurub estavam tentando fazer um ritual terrível e profano. Se Mandokir está vivo, é provável que ele não seja o único.$b$bOs exploradores do Forte Pedraviva, ao sul, devem saber mais sobre isso. Fale com a sacerdotisa deles.', '', '', '', '', '', '', '', '', '', 'Fale com a Sacerdotisa Thaalia no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26750, 'ptBR', 'O chamado da Petramáter', 'Fale com Therazane, a Petramáter.', 'Chegou a hora. A Petramáter aceitou falar com você. O trono dela fica no norte do Geodomo, acima da Borda Limpa.', '', '', '', '', '', '', '', '', '', '', 0),
(26751, 'ptBR', 'Con-troll-e de população', 'Mate 7 Místicos Sanguescalpo, 7 Caçadores Sanguescalpo, 7 Batedores Sanguescalpo e 1 Senhor das Feras Sanguescalpo.', 'Eu sei que você deve estar indo para Zul\'Kanda em breve. Eu tenho uma pequena tarefa para você, aproveitando a sua viagem.$b$bOs trolls estão ficando mais numerosos do que a Selva do Espinhaço consegue suportar. Os Sanguescalpo a oeste, os Rachacrânio a leste... Eles saem das ruínas para a selva, perturbando o equilíbrio da região. Já é hora de nós restabelecermos esse equilíbrio.$b$bZul\'Kanda é a capital dos Sanguescalpo. Lá dentro, você encontrará os Sanguescalpo de patente mais alta. Acabe com alguns deles e depois fale novamente comigo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sargento Yohwa no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26752, 'ptBR', 'Audiência com a Petramáter', 'Compareça à audiência com a Petramáter.', 'Fique onde está, $Gcampeão:campeã;. Ainda não decidi o que fazer com você e com a sua Harmonia Telúrica.', '', 'Compareça à audiência com a Petramáter', '', '', '', '', '', '', '', 'Fale com o Arauto da Terra Torunscar no Trono de Therazane.', 0),
(26753, 'ptBR', 'Os salões dos mortos', 'Encontre o Arco Forjado a Luz nas Catacumbas do Bosque da Aurora.', '<Diante de você, o declive de terra leva até a sombria entrada das criptas.>$B$B<Você sente que o artefato forjado a luz é puxado para dentro. Será que a outra parte está lá embaixo?>', '', '', '', '', '', '', '', '', '', '', 0),
(26754, 'ptBR', 'A desgraça de Morbídio', 'Use a Desgraça de Morbídio para enfraquecer Morbídio Vil e derrotá-lo.', '<As partes se encaixam, o artefato sagrado foi finalmente restaurado e brilha, fulgurante. O objeto permitirá que você derrote a magia negra de Morbídio Vil.>$B$B<Do fundo do túnel, um ruído horripilante faz tremer as paredes. Trata-se da estrondosa gargalhada de um lich. Morbídio está logo adiante!>', '', '', '', '', '', '', '', '', '', 'Fale novamente com Noel Figueira no Monte Corvo, que fica na Floresta do Crepúsculo.', 0),
(26755, 'ptBR', 'Para longe do front', 'Bombardeie 30 Horrores Fúngicos e/ou Reforços dos Troggs de Pedra.', 'Ah, que bom, você trouxe outra catapulta! O Árgilo pode ser mais velho do que a própria terra, mas sabe como fazer umas máquinas de guerra excelentes.$B$BBem, você não trouxe essa máquina até aqui a troco de nada, saco de carne. Pule já em uma dessas catapultas e mande chumbo nos horrores fúngicos e nos reforços que não param de chegar na Vila Pedragulha.$B$BTemos que mantê-los longe do front!', '', 'Reforços bombardeados', '', '', '', '', '', '', '', 'Fale novamente com Pírio Magneto na Vila Pedragulha, que fica no Geodomo.', 0),
(26760, 'ptBR', 'Uivando para a lua', 'Observe Olívio Espargosa e Medrisco tentarem curar o Worgen Espreitador.', 'Eu estou esperançoso, mas vamos manter o profissionalismo. É o negócio de sempre: este aqui vai para a guilhotina... e se a alquimia não funcionar, de lá ele não volta.$B$BEu e o Medrisco tomamos conta disso. Por favor, afaste-se e observe de uma distância segura.', '', 'Worgen curado', '', '', '', '', '', '', '', 'Fale novamente com Olívio Espargosa no Monte Corvo, que fica na Floresta do Crepúsculo.', 0),
(26761, 'ptBR', 'Ameaça ao reino', 'Apresente-se ao Magistrado Salomão na Vila Plácida, que fica nas Montanhas Cristarrubra.', 'Não resta dúvida de que os Défias representam uma grande ameaça ao reino, mas não podemos simplesmente entrar no esconderijo deles e esperar que tudo acabe bem. Nada disso: uma investida contra os Défias exigirá planejamento e tempo. Deixe a logística comigo. Não temos que lidar com quaisquer outras ameaças imediatas mesmo!$B$BVá para as Montanhas Cristarrubra, a leste, atravessando Elwynn, e apresente-se ao magistrado Salomão na Vila Plácida.', '', '', '', '', '', '', '', '', '', '', 0),
(26762, 'ptBR', 'Reativar constructos', 'Reative 5 Constructos de Guerra Desativados.', 'Nós enviamos vários constructos de guerra para a Vila Pedragulha, a norte daqui, mas nenhum deles voltou. Temos certeza que os troggs de pedra místicos fizeram alguma coisa com eles.$B$BEstamos preocupados que os místicos consigam controlar os constructos e os usem contra nós, como fizeram com os gigantes fúngicos.$B$B$n, vá até a vila trogg e reative os constructos.', '', 'Constructos de Guerra Desativados reativados', '', '', '', '', '', '', '', 'Fale novamente com Pírio Magneto na Vila Pedragulha, que fica no Geodomo.', 0),
(26763, 'ptBR', 'Mineração da Empreendimentos S.A.', 'Obtenha 5 Cristais Rolados das forças da Empreendimentos S.A. próximas ao Lago Nazferiti.', 'Se vou ter que consertar esta panela, vou precisar de reagentes. E pra pegar os reagentes, você vai ter que fazer uma matançazinha. Eu espero que não se importe.$b$bAqueles geólogos covardes da Empreendimentos S.A. tão coletando uns cristais rolados que vão servir pro que eu preciso. Você vai achar eles ao redor do Campo-base, do outro lado do Lago Nazferiti, a leste.$b$bEu não me importo com o que você vai precisar fazer pra conseguir os cristais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Krazek na Expedição do Rosarães, que fica na Selva do Espinhaço Setentrional.', 0),
(26765, 'ptBR', 'Fale novamente com o Cabo Kaleb', 'Leve a Caçarola Melhorada do Krazek para o Cabo Kaleb no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 'Bem, a panela está consertada. Eu até coloquei uma válvula de vapor extra e, olha só! Tem uma nova lâmina no fundo que corta até osso de costela!$B$BSim, sim, todos os cozinheiros vão adorar a Caçarola Meia-boca do Krazek! Tenho certeza que o dono dela vai ficar satisfeito.', '', '', '', '', '', '', '', '', '', 'Leve a Caçarola Melhorada do Krazek para o Cabo Kaleb no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26766, 'ptBR', 'Para grandes presas, grandes iscas', 'Use a Faca de Mylra para retirar 5 Lombos de Basilisco de Basiliscos Cristajade mortos.', 'Só vamos ter uma chance de pegar o Abyssion, $n. E não vamos desperdiçá-la.$B$BVamos testar a armadilha com o maior dos dragões de pedra do Planalto do Alabastro.$B$BPara atrair a matriarca de pedra, vamos precisar de muitas iscas.$B$BPegue esta faca e corte 5 lombos de basilisco. Isso deve bastar, até mesmo para um apetite como o dela.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Tempestária Mylra no Mirante do Crepúsculo, que fica no Geodomo.', 0),
(26768, 'ptBR', 'Como domar um dragão', 'Obtenha uma Armadilha do Crepúsculo dos Espreita-dragão do Crepúsculo.', 'O inimigo foi muito perspicaz ao botar um dragão para guardar o fragmento. Assim, eles podem mudá-lo de lugar sempre que nos aproximamos.$B$BVai ser muito difícil pegar o Abyssion, mas eu tenho um plano.$B$BO Martelo do Crepúsculo usa armadilhas mágicas para prender dragões no chão e absorver a energia deles.$B$BSe conseguirmos botar as mãos em uma dessas armadilhas, talvez possamos prender o Dragão Crepuscular ao chão por tempo suficiente.$B$BSiga em direção a leste, para o Planalto de Alabastro, e pegue uma dessas armadilhas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Tempestária Mylra no Mirante do Crepúsculo, que fica no Geodomo.', 0),
(26769, 'ptBR', 'Rio em fúria', 'Embarque na Barcaça de Tito Tocatrompa, a nordeste da Vila Catraca, e vá ao Acampamento do Macambúzio.', 'Tó a sua parte, $n!$B$BDetesto ter que dividir, mas negócios são negócios. E aquele caloteiro do Macambúzio tem 10% do tesouro garantido. Tu pode ir lá entregar isso pra ele no posto ao norte?$B$BEle conduz um laboratoriozinho rio acima. Se tu for pro nordeste da cidade, Tito Tocatrompa pode te dar uma viagem grátis em um de seus barcos. Fala pra ele que tu me conhece!', '', 'Embarque na Barcaça para encontrar o Macambúzio', '', '', '', '', '', '', '', 'Fale com o Macambúzio no Acampamento do Macambúzio, que fica nos Sertões Setentrionais.', 0),
(26770, 'ptBR', 'Mestres místicos', 'Mate 5 Místicos Pedragulha.', 'Os místicos Pedragulha estão controlando os gigantes fúngicos que brotaram na fenda deles. E agora, eles estão tentando tomar os nossos constructos de guerra.$B$BVá até a Vila Pedragulha, a norte daqui, e tome alguma providência! Não é para isso que você está aqui?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Sílex Rochamanto na Vila Pedragulha, que fica no Geodomo.', 0),
(26771, 'ptBR', 'O teste da armadilha', 'Monte a armadilha de carne na fronteira oeste do Planalto de Alabastro.', 'Agora você deverá montar a armadilha para a matriarca.$B$BVá até a ponta oeste do Planalto de Alabastro e coloque a armadilha de carne de basilisco no meio do campo onde ela come.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Tempestária Mylra no Mirante do Crepúsculo.', 0),
(26772, 'ptBR', 'Visão da mente', 'Obtenha 5 Penas de Espreitador da Selva dos Espreitadores da Selva na Selva do Espinhaço Setentrional.', 'Para conhecer Mandokir, você precisa ver Mandokir.$b$bPara ver Mandokir, você precisa usar olhos de raptor.$b$bVocê criou um laço com um raptor, Ohgan\'aka, filha de Ohgan.$b$bPara fortalecer o laço, nós precisamos de penas.$b$bVocê vai para nordeste, encontrar penas para mim, sim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sacerdotisa Thaalia no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26773, 'ptBR', 'Ver raptor', 'Fale com a Sacerdotisa Thaalia no Forte Pedraviva para participar do ritual da Visão da Mente.', 'Nós temos penas, sim.$b$bNós temos $go:a; $c, sim.$b$bFale com a Sacerdotisa quando tiver pront$go:a;.', '', 'Visão da Mente completada', '', '', '', '', '', '', '', 'Fale novamente com a Sacerdotisa Thaalia no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26774, 'ptBR', 'Controle mental', 'Pegue o Grande Cérebro de Braddok do Braddok em Zul\'Mamwe.', 'Visão da Mente não basta, não.$b$bControle Mental é feitiço muito mais forte, sim.$b$bFeitiço poderoso precisa de reagentes poderosos, e cérebro de troll é reagente poderoso.$b$bBraddok, em Zul\'Mamwe, é muito inteligente, sim.$b$bVai para o sul e dá uma olhada no grande cérebro do Braddok.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sacerdotisa Thaalia no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26775, 'ptBR', 'Ser raptor', 'Fale com a Sacerdotisa Thaalia. Depois, ajude o Filhote Capturado de Batecauda a escapar de Zul\'Gurub.', 'Controle Mental muito poderoso, sim.$b$bCom sorte, ajuda Ohgan\'aka a escapar de Zul\'Gurub.$b$bDepois, Ohgan\'aka vira $n\'aka de novo!$b$bFala com a Sacerdotisa, sim, e ajuda $n\'aka fugir.', '', 'Falar com Tan\'shang', 'Ajude Tenjiyu', 'Falar com Chiyu', 'Fuja de Zul\'Gurub', '', 'Ohgan\'aka', 'De volta dos mortos?', 'Jin\'do, o Bagateiro', 'Fale novamente com a Sacerdotisa Thaalia no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26776, 'ptBR', 'Ghaliri', 'Fale com Ghaliri no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 'Sacerdotisa não sabe falar Língua Comum muito bem, não.$b$bVocê pode falar com Ghaliri, na frente daquela barraca.$b$bFala para ele o que você viu em Zul\'Gurub, sim.', '', '', '', '', '', '', '', '', '', 'Fale com Ghaliri no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26777, 'ptBR', 'Acalmar os espíritos', 'Use o Incensório Sagrado para acalmar 5 Espíritos Desamparados no Sítio dos Aguiar.', 'Esta é uma terra marcada pela tragédia, e cuja história exibe as cicatrizes da violência e do desespero. Alguns mortos espreitam a carne vivente, enquanto outros são apenas almas penadas, vagando perdidas na própria confusão.$B$BElas merecem descansar.$B$BMuitas dessas almas se reúnem no Sítio dos Aguiar, a sul daqui, e costumam aparecer diante de viajantes. Pegue este incensório sagrado e espalhe sua fumaça benfazeja diante dos espíritos desamparados. Que a oferenda de perfumes suaves lhes dê paz.', '', 'Espírito Desamparado acalmado', '', '', '', '', '', '', '', 'Fale novamente com a Irmã Elsington no Monte Corvo, que fica na Floresta do Crepúsculo.', 0),
(26778, 'ptBR', 'O lamento dos mortos', 'Mate 20 carniçais de qualquer espécie no Cemitério de Monte Corvo.', 'Você consegue ouvi-los, $n? São tantos... Perambulam por entre os túmulos, arrastando os membros apodrecidos pelo chão frio.$B$BO lamento dos mortos ecoa pelo ar imóvel. Eles sofrem nas peles inanimadas uma vigília sem fim! Todas as noites eu me arrisco a ir ao cemitério para dar a mais espíritos o descanso merecido, mas meus esforços não são o bastante.$B$BAjude-me, $n. Livre os carniçais apinhados no Cemitério de Monte Corvo dessa desgraça. Mate tantos quanto puder.', '', 'Carniçais mortos', '', '', '', '', '', '', '', 'Fale novamente com a Irmã Elsington no Monte Corvo, que fica na Floresta do Crepúsculo.', 0),
(26779, 'ptBR', 'Mambo Zul\'Mamwe', 'Mate 16 Trolls Rachacrânio em Zul\'Mamwe.', 'Os Rachacrânio são uma vergonha pro império dos trolls. A briguinha deles com os Sanguescalpo dividiu a Selva do Espinhaço Setentrional ao meio. Enquanto as tribos Lançanegra e Zandalari tão prosperando, os Rachacrânio ficam aí lutando por causa de umas ruínas.$b$bEu tenho autorização pra dar uma recompensa pros mercenários que tiverem a fim de dar uma lição nos Rachacrânio. Então, se você tiver dispost$go:a;, vai pro leste com todo mundo que você conhecer e dá uma boa sova nesses caras.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ghaliri no Acampamento Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26780, 'ptBR', 'A noite na selva', 'Apague 8 Braseiros de Zul\'Mamwe em Zul\'Mamwe, que fica na Selva do Espinhaço Setentrional.', 'A noite na Selva do Espinhaço é linda. O céu se enche de estrelas e os raios da lua passam exatamente entre aquelas duas folhas ali. Eu poderia ficar olhando para esse céu a noite toda.$b$bInfelizmente, os trolls que vivem nas ruínas de Zul\'Mamwe estão atrapalhando a minha astronomia. Eles ficam acendendo braseiros dia e noite, e isso acaba com a escuridão de que eu preciso pra observar direito.$b$bPor favor, $n... Vá para leste, em Zul\'Mamwe, e apague os malditos braseiros.', '', 'Braseiros de Zul\'Mamwe apagados', '', '', '', '', '', '', '', 'Fale novamente com Kinnel no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26781, 'ptBR', 'O Olho da Mente', 'Pegue o Olho da Mente de Mai\'Zoth.', 'Um dos muitos tesouros da Selva está próximo daqui, no NOSSO lado do redemoinho gigante. O Olho da Mente está nas mãos de um ogro-mago, na Gruta de Mosh\'Ogg, que fica a sul daqui. O nome dele é Mai\'Zoth. Tudo o que eu sei é que ele é violento e a magia dele é poderosa.$b$bAlém disso, se ele possui o Olho da Mente, então a magia dele deve estar ainda mais forte.$b$bAté hoje eu não consegui chegar perto o suficiente para pegar o artefato dele. Você poderia tentar?', '', '', '', '', '', '', 'Mai\'Zoth', '', '', 'Fale novamente com Livio Marcus no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26782, 'ptBR', 'O tesouro Mosh\'Ogg', 'Pegue o Tesouro Mosh\'Ogg nas ruínas atrás da Gruta de Mosh\'Ogg.', 'O Acampamento dos Rebeldes, ao norte, tem estado estranhamente ativo. Acabei de ouvir de um soldado chamado Nimetz que $gum:uma; $r $c encontrou algo que está os deixando loucos. Não foi você, foi?$b$bEnfim, ele mandou uma amostra para mim e parece com as pedras que eu encontrei lá na Gruta de Mosh\'Ogg, a nordeste daqui.$b$bOuvi dizer que os ogros estão guardando um baú em umas ruínas atrás da gruta deles. Acho que essas coisas podem estar relacionadas. Você pode pegá-lo para mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Wulfred Harrys no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26783, 'ptBR', 'O tesouro Mosh\'Ogg', 'Pegue o Tesouro Mosh\'Ogg nas ruínas atrás da Gruta de Mosh\'Ogg.', 'O Acampamento dos Rebeldes, ao norte, tem estado estranhamente ativo. Acabei de ouvir de um soldado chamado Nimetz que $gum:uma; $r $c encontrou algo que está deixando-os loucos. Não foi você, foi?$b$bEnfim, ele mandou uma amostra para mim e parece com as pedras que eu encontrei lá na Gruta de Mosh\'Ogg, a nordeste daqui.$b$bOuvi dizer que os ogros estão guardando um baú em umas ruínas atrás da gruta deles. Acho que essas coisas podem estar relacionadas. Você pode pegá-lo para mim?', '', '', '', '', '', '', '', '', '', 'Fale com Wulfred Harrys no Forte Pedraviva, que fica na Selva do Espinhaço Setentrional.', 0),
(26784, 'ptBR', 'Águas lamacentas', 'Mate Elementais de Água Turva para coletar 5 Núcleos do Redemoinho.', 'Os poderes elementais têm força aqui no Planalto, $n. Por isso o Martelo do Crepúsculo decidiu construir o forte aqui.$B$BNas mãos certas, esse poder pode ser canalizado para algo produtivo... como um portal direto para Orgrimmar.$B$BA noroeste daqui, no delta do Rio Verrall, os elementais de água têm sido provocados por nossos rivais rio acima. Destrua-os e colete 5 núcleos dos redemoinhos. Você vai não só tranquilizar o rio como também fortalecer nosso portal.', '', '', '', '', '', '', '', '', '', 'Entregue os Núcleos para Artesh no Porto Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(26785, 'ptBR', 'Membro da matilha', 'Fale com o Aprendiz Zembucha na encruzilhada a oeste da Vila Sombria, que fica na Floresta do Crepúsculo.', 'Tenho tentando esconder minha verdadeira identidade do povo de Vila Sombria... Acho que eles não reagem muito bem quando veem um worgen. E há mais de nós aqui, para além da cidade.$B$BOs companheiros com quem eu viajei por aqui pela primeira vez vêm fazendo buscas pelos bosques para encontrar worgens selvagens. Eles acham que alguns deles, os que têm marcas características, ainda podem ser curados. Por favor, avise o aprendiz Zembucha, que está na encruzilhada a oeste da cidade, que eu vou ficar na Vila Sombria um pouco mais.', '', '', '', '', '', '', '', '', '', '', 0),
(26786, 'ptBR', 'A vigília da cabeça da praia', 'Fale com Artesh no Porto Presa do Dragão, que fica no Planalto do Crepúsculo.', 'Algo me incomoda, $n. Os dragões crepusculares sabiam quando e onde atacar nossa frota aérea, como se conhecessem nossos planos.$B$BEspiões do Crepúsculo se acovardam entre nós!$B$BVou levar um de nossos navios restantes de volta a Orgrimmar para arrancar algumas cabeças. Dê cobertura! Os xamãs Presa do Dragão são poderosos. Pedi a eles que abrissem um portal para Orgrimmar e preciso de sua ajuda.$B$BEntão, vamos lá!', '', '', '', '', '', '', '', '', '', 'Fale com Artesh no Porto Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(26787, 'ptBR', 'Lembrete', 'Pegue 8 Cérebros de Urso Preto.', 'Lamento muito ter que... Bem, eu sou todo lamentos, mas também sinto muito ter que lhe pedir outro favor.$B$BO Mestre Espargosa precisa de miolos. Cérebros de urso. Parece que são um ingrediente do soro, ou pelo menos funcionam como substituto.$B$BHá muitos ursos pretos nas florestas a oeste e ao longo do rio, mas... Eu não consigo! Tenho muito medo de ir até lá e encarar aquelas criaturas enormes, mesmo armado com um rifle! Por favor, eu pago para você me trazer alguns cérebros!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Medrisco no Monte Corvo, que fica na Floresta do Crepúsculo.', 0),
(26788, 'ptBR', 'O tijolinho que faltava para nossa vitória', 'Colete 10 porções de Lama do Rio Verrall.', 'Nossa aliança com os Presa do Dragão está assegurada, mas este porto está longe de estar preparado para o combate. Estas muralhas de madeira frágil são uma vergonha para nosso Chefe Guerreiro.$B$BQuando os elementais de água cavam seu caminho através das pedras, como fazem no Rio Verrall, eles soltam uma espécie de lama peculiar. Ela é perfeita para construções em grande escala.$B$BVá ao delta do rio, a noroeste daqui, e colete um tanto da lama do Rio Verrall. Nesse caso, um pouco já é muito.', '', '', '', '', '', '', '', '', '', 'Leve a lama para Ornak no Porto Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(26789, 'ptBR', 'You no take axe!', 'Kill 5 Test Kobolds.', '<Name>, we have a problem! I\'ve tracked down the demon-hound Magmadar to this clearing, but when we resting a band of kobolds took our battle axes! I need you to retrieve them, lest Magmadar catch us off guard! Hurry, he could awaken at any moment!', '', '', '', '', '', '', '', '', '', 'Return to Thrall in Stonetalon Mountains.', 0),
(26791, 'ptBR', 'Brotos nunca mais', 'Interaja com um Guardião de Guerra e conquiste-o. Em seguida, destrua 5 Cogumelos Gigantes.', 'Os troggs de pedra místicos estão criando essas monstruosidades fúngicas a partir dos cogumelos gigantes que nascem ao norte.$B$BQuero que você pegue um guardião de guerra e ajude a cuidar dos gigantes e troggs de pedra. Vá até os cogumelos gigantes e ataque-os. Eu e meus geomantes os enterraremos antes que os místicos consigam terminar o ritual.', '', 'Pegue um Guardião de Guerra', 'Cogumelos Gigantes destruídos', '', '', '', '', '', '', 'Fale novamente com Ardósio Movediço na Fenda Pedragulha, que fica no Geodomo.', 0),
(26792, 'ptBR', 'Monstros fúngicos', 'Mate 5 Monstros Fúngicos.', 'Pegue um Guardião de Guerra e destrua os monstros fúngicos.', '', 'Pegue um Guardião de Guerra', '', '', '', '', '', '', '', 'Fale novamente com Ardósio Movediço na Fenda Pedragulha, que fica no Geodomo.', 0),
(26793, 'ptBR', 'A velha lápide', 'Fale com Sirra Von\'Indi na Vila Sombria.', 'Na lápide antiga lê-se apenas:$b$bMORGAN LADIMORE$b$b<Ao olhar mais de perto, você repara que a terra sobre o túmulo foi remexida há pouco tempo. Na verdade, parece que uma boa porção de terra foi deslocada...>', '', '', '', '', '', '', '', '', '', '', 0),
(26794, 'ptBR', 'Morgan Ladimore', 'Fale com a Comandante Aldora Ebanez na Vila Sombria.', '<Ele olha as prateleiras e encontra um livro com capa de couro.>$b$bCaso você queira saber mais, é melhor perguntar à Aldora. É ela que tem lidado com o ... problema... ultimamente.', '', '', '', '', '', '', '', '', '', '', 0),
(26795, 'ptBR', 'Mor\'Ladim', 'Mate Mor\'Ladim e entregue a caveira dele para a Comandante Aldora Ebanez na Vila Sombria.', 'Pelo que os batedores me disseram, Mor\'Ladim vaga pela Floresta do Crepúsculo, seguindo um estranho e sinuoso caminho pelo cemitério. Nós o enterramos logo acima da casa do outeiro, você sabe onde fica?$b$bNão posso te ajudar muito além disso, mas lhe desejo boa sorte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Comandante Aldora Ebanez na Vila Sombria, que fica na Floresta do Crepúsculo.', 0),
(26796, 'ptBR', 'A filha sobrevivente', 'Fale com a Vigia Sarah Ladimore na Vila Sombria.', 'Eu devia ter mencionado isso antes...$b$bComo é que vou explicar...$b$bEmbora Morgan acreditasse que toda a família dele estava morta, na verdade, a filha Sarah Ladimore agora é uma Vigia. Ela sempre foi muito perturbada pelas... circunstâncias... da morte do pai. Talvez você possa dar a notícia a ela.', '', '', '', '', '', '', '', '', '', '', 0),
(26797, 'ptBR', 'Amor de filha', 'Leve o anel de Sarah Ladimore até o túmulo de Morgan Ladimore.', 'Pegue isto e bote no túmulo de meu pai. Quem sabe... de alguma forma, assim ele saberá que eu estou bem e que ninguém o responsabiliza pelo que aconteceu.$b$b<Lágrimas escorrem do rosto de Sarah enquanto ela retira um anel da mão direita e o entrega a você.>$b$bE... Obrigada, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(26798, 'ptBR', 'A satisfação do Chefe Guerreiro', 'Use o portal no Porto Presa do Dragão para ir para Orgrimmar e apresente-se ao Chefe Guerreiro.', 'O portal está pronto!$B$BEle não é poderoso o suficiente para transportar um exército, mas nós podemos manter a conexão por tempo suficiente para permitir que indivíduos importantes o usem.$B$BO Chefe Guerreiro vai querer saber como está o progresso aqui. Passe pelo portal para Orgrimmar e dê notícias para o Chefe Guerreiro.', '', '', '', '', '', '', '', '', '', 'Use o portal no Porto Presa do Dragão para ir para Orgrimmar e apresente-se ao Chefe Guerreiro.', 0),
(26799, 'ptBR', 'Aqueles que não puderam ser salvos', 'Mate 6 Zumbis Desmiolados.', 'As val\'kyren ressuscitam centenas de cadáveres todos os dias. Ágata acabou de ressuscitar você... Mas nem todos têm a mesma sorte que você.$b$bAlguns mantêm o livre arbítrio, mas vivem constantemente confusos e com medo. Costumam correr para as florestas, assustando-se com o próprio reflexo.$b$bOutros perdem a cabeça completamente, vagando sem direção. Ficam violentos e devem ser destruídos.$b$bEsta é a sua tarefa, $n. Destrua nossos antigos irmãos e irmãs, não importa quem sejam.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Coveiro Mordo nas Tumbas de Plangemortis, que fica nas Clareiras de Tirisfal.', 0),
(26800, 'ptBR', 'Recrutamento', 'Procure em Plangemortis e redondezas por 6 Cadáveres Escarlates e, em seguida, aponte para eles para que Darnell possa pegá-los.', 'Temos carregado cadáveres de Pinhaprata, Eira dos Montes... que diabos, de onde quer que eles venham. Não podemos ignorar os corpos que simplesmente aparecem no nosso caminho.$b$bOs últimos vestígios da Cruzada Escarlate jazem aqui nas Clareiras de Tirisfal. Enquanto tentávamos movê-los de Plangemortis, vários corpos fugiam para as construções ao norte e ao leste.$b$bEncontre estes corpos... e leve o camarada Darnell com você. Ele parece ser forte o bastante para carregar alguns cadáveres.', '', 'Cadáveres Escarlate recolhidos', '', '', '', '', '', '', '', 'Fale novamente com o Necroguarda Saulo em Plangemortis, nas Clareiras de Tirisfal.', 0),
(26801, 'ptBR', 'Flagelo nas proximidades', 'Mate 8 mortos-vivos fora de Plangemortis. Você pode matar tanto Carniçais Ignóbeis quanto Esqueletos Range-ossos.', 'Se você vai se tornar um bem valioso para os Renegados, você precisa aprender a lutar. E não há melhores oponentes que os lacaios do Flagelo, que sempre incomodam a todos.$B$BOs carniçais ignóbeis e os esqueletos range-ossos que zanzam a norte e a leste são antigas tropas derrotadas do Flagelo. Devem ser um desafio melhor para $gum:uma; $c aprendiz como você.$b$bNão demore. Quando acabar com todos, venha a mim novamente.', '', 'Flagelos de Plangemortis mortos', '', '', '', '', '', '', '', 'Fale com o Sacerdote Sombrio Sarvis em Plangemortis, que fica nas Clareiras de Tirisfal.', 0),
(26802, 'ptBR', 'Os malditos', 'Obtenha 4 Patas de Carniceiro e 4 Asas de Quiropúsculo.', 'Antes de tudo, olhe para a sua armadura. Que coisa horrorosa, $c.$b$bSe não quiser ficar em pedaços, o que eu acho que seja o seu objetivo, talvez eu possa ajudar. Se você conseguir juntar algumas patas de lobos e asas de morcegos, eu talvez encontre uma armadura para você. As criaturas estão ao norte e a oeste daqui.', '', '', '', '', '', '', '', '', '', 'Fale com o Executor Arren em Plangemortis, que fica nas Clareiras de Tirisfal.', 0),
(26803, 'ptBR', 'Relatórios perdidos', 'Fale com Doraso, o tratador de mantícoras de Orgrimmar.', 'Vol\'jin é sábio e tem boas intenções. Com o tempo, ele aprenderá a ver seu povo como um aliado valioso.$B$BEstou esperando relatórios sobre atividade recente da Aliança em Durotar, mas eles ainda não chegaram. Você está $gdisposto:disposta; a ir ao Monte Navalha e pedir os relatórios a ele? O jeito mais fácil de chegar lá é voando de mantícora. Doraso, o tratador de Orgrimmar, aluga mantícoras por um preço módico. Ele fica na elevação norte do Vale da Força.', '', '', '', '', '', '', '', '', '', '', 0),
(26804, 'ptBR', 'Voo até o Monte Navalha', 'Fale com Doraso para conseguir uma passagem de mantícora até o Monte Navalha. Ao chegar lá, fale com Gar\'Thok.', 'Quando estiver $gpronto:pronta; para ir de mantícora até o Monte Navalha, basta falar comigo de novo. Ao chegar lá, vá direto falar com Gar\'Thok. É ele o responsável pelos relatórios sobre a atividade recente da Aliança em Durotar.', '', '', '', '', '', '', '', '', '', '', 0),
(26805, 'ptBR', 'Para o Cabo!', 'Fale com Robert Rhodes para conseguir um voo para a Escavação da Liga dos Exploradores, no Cabo do Espinhaço.', 'A Liga dos Exploradores está crescendo, $n. Eles não apenas estão aceitando worgens como eu, mas também estão expandindo a área de pesquisa em busca de mais artefatos. Um dos nossos melhores exploradores, Bronwyn Talho, montou acampamento no sul, onde ele acredita haver um artefato titânico perdido.$b$bO Bronwyn me encarregou de algumas tarefas aqui no norte. Uma delas é identificar recrutas em potencial, e eu acho que você tem o que precisamos. Fale com Robert Rhodes, o mestre de voo, e ele lhe arranjará transporte. Por conta do Bronwyn.', '', '', '', '', '', '', '', '', '', 'Fale com Robert Rhodes para conseguir um voo para a Escavação da Liga dos Exploradores, no Cabo do Espinhaço.', 0),
(26806, 'ptBR', 'Relatórios para Orgrimmar', 'Leve os Relatórios de Gar\'Thok para Burok, no Monte Navalha.', 'Eitrigg terá que se contentar com o relatório até onde pude completá-lo. Diga que em breve enviarei o restante.$B$B<Gar\'Thok lhe entrega uma pilha de papéis dobrados grosseiramente.>$B$BIsto deve dar conta dos detalhes mais importantes sobre o fortalecimento das tropas da Aliança vindas da Guardanorte. Peça desculpas a Eitrigg em meu nome; diga-lhe que estivemos bastante ocupados aqui, mantendo o Monte Navalha seguro e provido. Quando estiver $gpronto:pronta; para voltar a Orgrimmar, basta falar com Burok e alugar uma mantícora.', '', '', '', '', '', '', '', '', '', '', 0),
(26807, 'ptBR', 'De volta a Eitrigg', 'Fale com Burok e compre uma passagem de volta para Orgrimmar. Em Orgrimmar, leve os Relatórios de Gar\'Thok para Eitrigg no Vale da Força.', 'Uma vez que você já falou com Doraso, poderá alugar uma mantícora de volta para Orgrimmar. Sempre que você chegar numa cidade nova, fale com o tratador de mantícoras de lá. Assim você poderá usar os serviços do mestre de voos para viajar rapidamente.$B$BFale comigo novamente quando estiver $gpronto:pronta; para comprar uma passagem de volta para Orgrimmar. Leve os relatórios para Eitrigg no Vale da Força quando chegar lá.', '', '', '', '', '', '', '', '', '', '', 0),
(26808, 'ptBR', 'Maywiki', 'Leve o Presente de Linzi para Maywiki de Zuldazar na Escavação da Liga dos Exploradores.', '<Linzi parece perturbada.>$b$bTem uma trolesa escondida atrás daquela pilha de caixas. Ela deve estar muito triste, porque não quer sair para falar com ninguém.$b$b<Linzi coloca um pouco de Junco de Akiris em um lençol e amarra.>$b$bToma, entrega isso pra ela. São bem macios... talvez ela se sinta mais confortável lá atrás.', '', '', '', '', '', '', '', '', '', '', 0),
(26809, 'ptBR', 'Negócios obscuros', 'Coloque o Incenso de Gurubashi em frente ao Totem de Hir\'eek. Em seguida, escute o plano de Zanzil.', 'Zanzil, o Pária, um exilado da tribo Gurubashi, é o meu alvo. Tenho ouvido boatos recentes dos meus irmãos do norte sobre os planos de Zanzil de reintegrar-se à sociedade, começando pelo emissário que ele enviou para os Rachacrânio. Essas não são boas notícias.$b$bEu quero que você descubra os planos atuais de Zanzil. Pegue esse incenso e coloque-o em frente ao totem do morcego nas Ruínas de Jubuwal, ao norte daqui. Hir\'eek irá guiá-l$go:a; de lá.', '', 'Coloque o Incenso em frente ao Totem de Hir\'eek', 'Espione Zanzil', '', '', '', '', '', '', 'Fale novamente com Maywiki na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26810, 'ptBR', 'Eliminando o pária', 'Vá para as Ruínas de Aboraz no Cabo do Espinhaço e mate Zanzil, o Pária.', 'Você deve matar Zanzil. Você voou nas asas de Hir\'eek e viu através dos olhos de Hir\'eek; você sabe onde Zanzil se esconde, dentro das Ruínas de Aboraz. Vá até lá e mate-o.$b$bMais uma coisa, $r: se nos separarmos, use esse fetiche. Ele só funciona no Espinhaço, mas trará você de volta para cá em caso de emergência.$b$bBoa sorte, $r. Zanzil não é um adversário qualquer.', '', 'Mate Zanzil, o Pária', '', '', '', '', 'Zanzil, o Pária', 'Para onde ele foi?', 'Zanzil, o Pária', '', 0),
(26811, 'ptBR', 'Pelo buraco do troll', 'Use o Portal de Zanzil para entrar em Zul\'Gurub.$b$bSe você se perder ou precisar voltar para Zul\'Gurub, fale com Maywiki na Escavação da Liga dos Exploradores.', 'Parece que o portal de Zanzil para Zul\'Gurub ainda está aberto. Zul\'Gurub é um local perigoso, mas Maywiki confiou essa tarefa a você.$b$bO portal está na sua frente.', '', 'Atravesse o Portal de Zanzil', '', '', '', '', '', '', '', '', 0),
(26812, 'ptBR', 'Alta-sacerdotisa Jeklik', 'Destrua o corpo da Alta-sacerdotisa Jeklik antes que Zanzil consiga ressuscitá-la.$b$bSe você se perder ou precisar voltar para Zul\'Gurub, fale com Maywiki na Escavação da Liga dos Exploradores.', 'À sua frente está a rampa para um dos muitos terraços da cidade. Os totens em forma de morcego indicam que esse é o domínio da alta-sacerdotisa Jeklik, uma seguidora de Hir\'eek.$b$bJeklik foi uma das sacerdotisas adoradoras de Hakkar que Zanzil planejava ressuscitar. Talvez, se você se apressar, ainda possa impedir a ressurreição!', '', 'Destrua o corpo da Alta-sacerdotisa Jeklik', '', '', '', '', 'Alta-sacerdotisa Jeklik', '', '', '', 0),
(26813, 'ptBR', 'Cada vez mais fundo em Zul\'Gurub', 'Atravesse o Portal de Zanzil.$b$bSe você se perder ou precisar voltar para Zul\'Gurub, fale com Maywiki na Escavação da Liga dos Exploradores.', 'Zanzil, o Pária, escapou mais uma vez por um de seus portais. Siga-o!', '', 'Atravesse o Portal de Zanzil', '', '', '', '', '', '', '', '', 0),
(26814, 'ptBR', 'Sumo sacerdote Venoxis', 'Mate Zanzil, o Pária, e o Sumo Sacerdote Venoxis.$b$bSe você se perder ou precisar voltar para Zul\'Gurub, fale com Maywiki na Escavação da Liga dos Exploradores.', 'Venoxis era o segundo dos dois sacerdotes que Zanzil planejava ressuscitar. Você já conseguiu destruir o corpo da alta-sacerdotisa Jeklik... Venoxis deve ser o próximo.', '', 'Mate o Sumo Sacerdote Venoxis.', '', '', '', '', 'Sumo Sacerdote Venoxis', '', '', 'Fale novamente com Maywiki na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26815, 'ptBR', 'O segredo de Zanzil', 'Obtenha 5 ampolas do Preparado de Zanzil.', 'Há muitos anos atrás, os Gurubashi exilaram um dos seus trolls de Zul\'Gurub. Um troll chamado Zanzil. As razões para isso não são muito claras, mas parece ter a ver com a tendência dele de injetar drogas poderosas para alterar o comportamento de qualquer troll que cruzasse seu caminho. De qualquer modo, os sacerdotes Gurubashi e o deus de sangue que eles seguiam foram mortos há muito tempo, mas Zanzil, o Pária, permanece...$b$b...assim como as drogas poderosas dele.$b$bEu preciso de uma amostra desse preparado para o meu próximo teste. Procure nos zumbis ao norte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dask Chiabisca, o "Frasco", na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26816, 'ptBR', 'Receita de desastre', 'Obtenha a Formulação de Zanzil de um dos seguidores de Zanzil nas Ruínas de Aboraz.', 'Você viu a explosão que eu causei? Eu devo ter voado uns 30 centímetros do chão!$b$bEu preciso conseguir a receita do Zanzil para descobrir o que aconteceu. Um daqueles capangas derrotados do Zanzil nas Ruínas de Aboraz deve ter a receita. Vá para leste, para a costa do Cabo, e pegue a receita para mim!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dask Chiabisca, o "Frasco", na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26817, 'ptBR', 'Perfeitamente puro', 'Consiga a Água Pura do Olho-d\'água Nek\'mani no Cabo do Espinhaço.', 'Esse humor não vai servir sozinho. É denso demais.$b$bAs nagas a oeste daqui mantêm a única fonte de água pura desse lado da Floresta do Crepúsculo. Na maioria das poções eu uso água de rio, mas o Bronwyn exige precisão!$b$bConsiga a água do Olho-d\'água Nek\'mani no topo do acampamento naga. Boa sorte!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dask Chiabisca, o "Frasco", na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26818, 'ptBR', 'Pelos macios', 'Obtenha 4 Peles Flexíveis de Tigresa e 4 Peles de Pantera Aveludadas.', 'Olá, eu sou a comerciante da cidade! E o Bronwyn é meu pai!$b$bDesculpe, eu não devia ficar tão empolgada. O pai diz que não é profissional.$b$bEnfim, as pessoas sempre vêm me perguntar sobre couro pesado ou pelegos duros, mas eu acho que meus clientes também devem se interessar por materiais mais macios... como pele de tigre! Será que tu poderia conseguir algumas pra mim?$b$bTu vai encontrar algumas panteras aqui por perto, mas pra achar os grandes tigres, vai ter que viajar para noroeste daqui... Ao norte daquela grande arena dos trolls.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Linzi Talho na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26819, 'ptBR', 'Akiris aos montes', 'Obtenha 6 Juncos de Akiris das Exploradoras Nagas.', 'As exploradoras nagas a leste daqui carregam uma espécie de junco do mar muito valiosa chamada de junco de akiris. Profissionais usam para fazer remédios e cataplasmas, e artesãos usam para alinhavar armaduras e até enrolar charutos!$b$bToda tarde, quando a escavação termina, o pai vem aqui me ensinar a usá-lo... mas infelizmente o nosso estoque acabou. Tu poderia conseguir mais um pouco?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Linzi Talho no Acampamento da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26820, 'ptBR', 'Se elas estão largadas por aí...', 'Obtenha 6 Ícones de Naga da Costa Selvagem Sul, que fica no Cabo do Espinhaço.', 'Meu pai sempre disse que um mercador responsável deve sempre estar de olhos abertos para novas oportunidades de negócios. Eu tenho procurado por bons negócios em toda parte e acho que finalmente encontrei uma oportunidade!$b$bAs nagas a oeste daqui deixam dezenas de estátuas no chão do local onde vivem. Elas provavelmente não precisam de todas elas... então eu estava pensando que nós poderíamos pegar algumas!$b$bEstátuas grátis! Esse é um bom negócio, não é?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Linzi Talho na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26821, 'ptBR', 'Airwyn Bantamflax', 'Leve o Tesouro Mosh\'Ogg Aberto à Airwyn Bantamflax na Angra do Butim, que fica no Cabo do Espinhaço.', 'Bom, eu não tenho ideia do que esse artefato é. Ele é mais velho do que andar pra frente... mas não é dos titãs. Eu estou completamente estupefato.$b$bAirwyn Bantamflax, na Angra do Butim, é minha superiora direta. Nosso próximo passo deve ser informá-la sobre essa descoberta. Tu pode levar isso pra ela?', '', '', '', '', '', '', '', '', '', '', 0),
(26822, 'ptBR', 'Cães-rastejantes inúteis', 'Mate 12 basiliscos Ferroqueixo ou Batecauda.', 'Ham, ham...$b$b<O anão limpa a garganta por vários segundos.>$b$bTu está procurando alguma coisa pra fazer? E veio perguntar pra MIM? O pobre Goris?!$b$bBom, isso é novidade. Ah, já sei!$b$bO vale ao norte daqui tá cheio daqueles basiliscos gordos e inúteis. Eles não fazem nada de bom pra ninguém e eu ouvi dizer dia desses eles transformaram um sujeito em pedra. $b$bSe tu der cabo deles, posso te dar umas coisas minhas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Goris na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26823, 'ptBR', 'Ele acha que é "o cara"', 'Consiga um frasco de Humor Aquoso de Ferroqueixo de um Beemote Ferroqueixo na Mina Veio de Cristal.', 'Para qualquer coisa que você queira fazer, eu tenho uma receita de poção. Quer uma poção explosiva? BUM!! Quer uma poção elétrica? ZAP!! Quer uma poção de encolhimento? Shuim.$b$bEntão o Bronwyn precisa de uma poção de datação carbônica? Fácil. Posso fazer isso com as duas mãos e um pé amarrados. Mas é o seguinte: se você quer precisão, vai ter de me trazer ingredientes de qualidade.$b$bPara começar, precisamos de um pouco de humor aquoso de um dos basiliscos ao norte. Você vai precisar de um basilisco dos grandes...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dask Chiabisca, o "Frasco", na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26824, 'ptBR', 'Resultado: inconclusivo', 'Leve o Tesouro Mosh\'Ogg Aberto de volta para Bronwyn no Acampamento da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 'Eu fiz tudo o que pude, $n. Eu usei as poções certas... Eu usei as receitas certas... Mas, ainda assim, a origem desse artefato me escapa. Ele tem dezenas de milhares de anos, mas nós já concluímos que não é de origem titânica. E não é saronita, isso eu posso afirmar só de olhar pra ele. Então qual, em nome de Brann, é a origem dessa coisa?$b$bDiga ao Bronwyn que eu tentei de tudo. Sinto muito.', '', '', '', '', '', '', '', '', '', 'Leve o Tesouro Mosh\'Ogg Aberto de volta para Bronwyn no Acampamento da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26825, 'ptBR', 'Dask Chiabisca, o "Frasco"', 'Leve o Tesouro Mosh\'Ogg Aberto para o Dask Chiabisca, o "Frasco", na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 'Ei... Tu deve ser $gaquele guri:aquela guria; de quem o Wulfred estava falando! Isso, $gaquele:aquela; que encontrou o artefato para o ogro e o ajudou a testar aquelas pedras estranhas ao norte. Bem-vind$go:a; à nossa escavação, $n!$b$bNa verdade, nós estávamos pesquisando as amostras nesse exato momento! Tu pode levar essas amostras para o Dask? Eu preciso que ele me diga a idade disso.', '', '', '', '', '', '', '', '', '', 'Leve o Tesouro Mosh\'Ogg Aberto para o Dask Chiabisca, o "Frasco", na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26826, 'ptBR', 'Dask Chiabisca, o "Frasco"', 'Leve o Tesouro Mosh\'Ogg Aberto para o Dask Chiabisca, o "Frasco", na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 'Ei... Tu deve ser $gaquele guri:aquela guria; de quem o Wulfred estava falando! Bem-vind$go:a; à nossa escavação, $n!$b$bNós estamos começando um projeto nesse exato momento! Tu pode levar essas amostras para o Dask? Eu preciso que ele me diga a idade disso.', '', '', '', '', '', '', '', '', '', 'Leve o Tesouro Mosh\'Ogg Aberto para o Dask Chiabisca, o "Frasco", na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 0),
(26827, 'ptBR', 'Incentivando a Harmonia Telúrica', 'Convoque 5 xamãs na parte de trás do Templo da Terra. Em seguida, fale com Maruut Atapedras.', 'A gente tem que levantar a bola da Harmonia Telúrica antes de entrar nessa luta. O que falta pra gente em quantidade, a gente compensa em força.$B$BVai lá no templo e junta os xamãs que sobraram nas salas de trás. Eu, a Norsala e o Lorvarius vamos encontrar com eles no Portão de Lorthuna.', '', 'Membros da Harmonia Telúrica convocados', '', '', '', '', '', '', '', 'Fale com Maruut Atapedras.', 0),
(26828, 'ptBR', 'Trato é trato', 'Fale com Therazane no Egresso Halcion.', 'Infelizmente, eu tenho que ficar para conter a fenda. Você vai ter que lutar $Gsozinho:sozinha;. Junte-se às tropas de Therazane, como prometido. Ela está no Egresso Halcion, a norte do Portão de Lorthuna, e a leste da Borda Limpa.$B$BQuando a nossa parte no trato for cumprida, traga a última parte do Pilar do Mundo o mais rápido possível.', '', '', '', '', '', '', '', '', '', '', 0),
(26829, 'ptBR', 'A marcha da pedra', 'Mate 15 Sectários do Abismo do Crepúsculo.', 'Minhas tropas já deram início ao ataque. Junte-se a elas. Derrame o sangue dos sectários sobre o chão, e assim saberei o quanto estão sofrendo.', '', 'Sectários do Abismo do Crepúsculo mortos', '', '', '', '', '', '', '', 'Fale novamente com Therazane no Egresso Halcion.', 0),
(26830, 'ptBR', 'A isca do traidor', 'Interrogue os Peões da Ponte Aérea de Orgrimmar em volta das Torres de Zepelim. Procure por qualquer Peão Suspeito. Tente expulsar Sauranok, o Místico, e mate-o.', 'Os agentes do Martelo do Crepúsculo continuam zanzando por Orgrimmar. Preciso de alguém de confiança para arrumar evidências da trairagem.\n\n<Vol >\n\nSuspeito que Sauranok, o Místico, esteja metido nisto. Quero que descubra a verdade, $n. O Martelo do Crepúsculo enfiou agentes no meio dos trabalhadores das docas das aeronaus para espalhar mentiras pelas nossas terras. Converse com eles e, se achar evidências de que Sauranok é culpado, mostre pra ele o que acontece com traíras na Horda.', '', 'Revelada a culpa de Sauranok', '', '', '', '', 'Sauranok, o Místico', '', '', 'Fale com o Chefe Guerreiro em Orgrimmar.', 0),
(26831, 'ptBR', 'A revoada do Crepúsculo', 'Derrote Zoltrik, o Mata-dragão.', 'Você deve ir até o fundo do precipício para lutar contra Zoltrik, o Mata-dragão. Quem pede isso é Terrath, que também está indo para lá. Ele acha que Zoltrik provavelmente vai se aproximar pelos céus.$B$BVocê causou muito boa impressão, $Gpequenino:pequenina;. Já parou para pensar que nada disso teria acontecido se eu tivesse simplesmente pisado em você da primeira vez? O destino é uma coisa curiosa.', '', 'Zoltrik, o Mata-dragão, derrotado', '', '', '', '', 'Zoltrik, o Mata-dragão', '', '', 'Fale com Terrath, o Estável, no alto do Abismo do Crepúsculo.', 0),
(26832, 'ptBR', 'A misericórdia de Therazane', 'Derrote Boldrich Racha-pedras e a Alta-sacerdotisa Lorthuna.', 'Temos que eliminar dois líderes do Crepúsculo.$B$BUm deles é um humano chamado Boldrich. Pequeno e ainda assim perigoso, como você.$B$BO outro é uma sacerdotisa chamada Lorthuna. Ela é muito astuta e difícil de encurralar. Ataque rapidamente e não a deixe escapar, ou você se arrependerá.', '', 'Boldrich Racha-pedras derrotado', 'Alta-sacerdotisa Lorthuna derrotada', '', '', '', '', '', '', 'Fale novamente com Therazane no Egresso Halcion.', 0),
(26833, 'ptBR', 'Promessa lavrada em pedra', 'Fale com Maruut Atapedras no Templo da Terra.', 'Você cumpriu o que lhe pedi, $r. Honrarei minha palavra. Gorsik encontrará você no Templo levando a nossa parte do Pilar do Mundo.$B$BTermine o seu ritual e feche a fenda. Em seguida, diga à Harmonia Telúrica para sair daqui.$B$BVocê, no entanto... Você pode ficar pelo tempo que quiser. Você merece pelo menos isso.', '', '', '', '', '', '', '', '', '', '', 0),
(26834, 'ptBR', 'No fundo do abismo', 'Fale com Ardósio Movediço na Fenda Pedragulha, que fica no Geodomo.', 'Os místicos estão semeando essas monstruosidades fúngicas no fundo da Fenda Pedragulha, que fica a nordeste daqui. Eu enviei o arquigeomante Ardósio Movediço e um pequeno pelotão para cuidar disso, mas eles toparam com um problema.$B$BVocê se lembra dele? Poderia voar até lá para ajudá-lo?', '', '', '', '', '', '', '', '', '', '', 0),
(26835, 'ptBR', 'Um pequeno percalço...', 'Fale novamente com Pírio Magneto na Vila Pedragulha, que fica no Geodomo.', 'Enquanto você estava em campo, o Pírio Magneto entrou em contato comigo. Ele disse que surgiu uma questão muito urgente e que precisam da sua ajuda imediatamente. O Pírio está na entrada da Vila Pedragulha, a sudoeste daqui.$B$BDesejo-lhe sorte no resgate do Petrarca e na recuperação do fragmento central.', '', '', '', '', '', '', '', '', '', '', 0),
(26836, 'ptBR', 'Resgate o Petrarca... e o Sílex', 'Liberte o Petrarca Rochamanto.', 'Nós descobrimos onde o Petrarca está preso, e o jovem Sílex correu até lá sozinho para tentar resgatar o pai!$B$BNem preciso falar que isso é péssimo. O Sílex vai acabar capturado ou coisa pior!$B$BO líder dos troggs de pedra, conhecido como Pança de Pedra, está no limite das plataformas acima da Fenda Pedragulha, a norte daqui.$B$BPor favor, $n, vá atrás do Sílex e liberte o Petrarca antes que percamos os dois!', '', 'Petrarca Rochamanto resgatado', '', '', '', '', 'Pança de Pedra', '', '', 'Fale novamente com Pírio Magneto na Vila Pedragulha, que fica no Geodomo.', 0),
(26838, 'ptBR', 'Rebeldes sem causa', 'Fale com o Tenente Doren no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 'Há muitos anos atrás, o Capitão Kurzen, de Ventobravo, trouxe uma brigada para dentro da Selva do Espinhaço. Os detalhes da missão deles ainda são obscuros. Kurzen enlouqueceu repentinamente, assim como os homens dele... exceto por alguns rebeldes que decidiram dedicar suas vidas a desfazer o mal que Kurzen causou.$b$bComo eu disse, isso foi há anos atrás. Eu já ouvi dizer que Kurzen está morto, mas os rebeldes persistem com a insubordinação. Se quiser investigar a situação, você encontrará o acampamento deles na fronteira norte.', '', '', '', '', '', '', '', '', '', 'Fale com o Tenente Doren no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 0),
(26840, 'ptBR', 'O retorno ao Planalto', 'Use o Portal do Planalto do Crepúsculo em Orgrimmar para retornar para o Porto Presa do Dragão no Planalto do Crepúsculo e fale com Zaela.', 'Com Orgrimmar em segurança e nossos aliados Presa do Dragão nos dando cobertura, podemos voltar nossa atenção à conquista do Planalto do Crepúsculo e à total destruição das forças do Asa da Morte.$B$BPreciso dos melhores membros da Horda na linha de frente. Isso significa você. E todos os seus amigos.$B$BO Planalto SERÁ nosso!$B$BUse o novo portal que você criou para voltar ao Porto Presa do Dragão. Apresente-se à Zaela e veja onde você será útil.', '', '', '', '', '', '', '', '', '', 'Use o Portal do Planalto do Crepúsculo em Orgrimmar para retornar para o Porto Presa do Dragão no Planalto do Crepúsculo e fale com Zaela.', 0),
(26841, 'ptBR', 'O selo proibido', 'Fale com Rhyanda no interior de Aldrassil, que fica em Umbravale.', 'Este selo foi-me entregue por um mensageiro enviado por nossa instrutora de magos, Rhyanda. Parece que ela deseja conversar com você quando tiver algum tempo livre. Leia o recado e, depois, leve-o a ela.', '', '', '', '', '', '', '', '', '', '', 0),
(26842, 'ptBR', 'Está chovendo gnoll', 'Pegue 12 Orelhas de Gnoll de Batedores Pelemusgo ou Esmagadores Pelemusgo.', 'Saudações, $c. Estamos com problemas, por isso peço a sua ajuda.$B$BSão os gnolls. Eles surgiram aos montes a oeste da cidade, vagando pelas colinas. Normalmente, isso não seria motivo para alarme, mas nunca vimos gnolls antes em Loch Modan.$B$BEstou curioso para saber de onde vêm essas criaturas sarnentas, mas não a ponto de perguntar diretamente a elas. Por isso eu digo: acabe com todas. Traga-me provas da matança e lhe pagarei uma vultosa recompensa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Kadrell na cidade de Thelsamar, em Loch Modan.', 0),
(26843, 'ptBR', 'Um comandante espertinho', 'Mate o Comandante Nazrim.', 'Lidamos com os kobolds nesta terra há anos. Nunca passaram de transtornos sem maior importância. Mas eles estão se tornando ladrõezinhos mais habilidosos.$B$BAcho que um deles ficou mais esperto que os outros. Mas isso não vai durar muito!$B$BQuero que você vá até a aldeia ao sul daqui e se assegure que não tenha mais nenhum kobold "manda-chuva" atiçando os outros. Não deixe de procurar dentro da caverna.$B$BE não hesite em acabar com os kobolds que encontrar pelo caminho.', '', '', '', '', '', '', '"Comandante" Nazrim', '', '', 'Fale novamente com o Montanhista Lançatroz na Estação Algaz, em Loch Modan.', 0),
(26844, 'ptBR', 'Aqui não, violão!', 'Mate 5 Ratatúneis Topógrafos e 5 Ratatúneis Colhedores.', 'Agora que demos um jeito naquelas coisinhas pestilentas, temos outros problemas a resolver.$B$BA Mina da Prata está infestada de ratatúneis, que andam construindo ninhos e fuçando tudo que veem pela frente. Acho que esses fominhas estão procurando coisas para pilhar.$B$BTudo bem topografar e coletar, mas não em terras enânicas! Dê cabo dos ratatúneis e volte aqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Lançatroz na Estação Algaz, em Loch Modan.', 0),
(26845, 'ptBR', 'O mandante', 'Pegue a cabeça do Encarregado Zombeteiro.', 'A Dorli me contou tudo sobre esta insana operação mata-trogg dos Kobolds e, se você ainda não conversou com ela, sugiro que o faça.$B$BEu gostaria de chegar ao fundo disso tudo. Literalmente! Quem quer que seja o diretor desse show deve estar no fundo da mina, só mexendo os pauzinhos, e quero ele morto.$B$BDescubra quem é o velhaco que está orientando os geomantes e escavadores e me traga a cabeça dele!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Lançatroz na Estação Algaz, em Loch Modan.', 0),
(26846, 'ptBR', 'Abuso de troggs', 'Mate 5 Geomantes Ratatúnel.', 'Descobri o que esses ratos estão tramando. Os espertinhos estão vindo para fora porque os troggs estão escavando a mina por eles!$B$BOs ratatúneis geomantes devem ter feito algum truquezinho de salão para controlar os troggs, porque são criaturas da terra ou coisa assim.$B$BFascinante, mas nem por isso vamos deixar que continuem. Acabe com os geomantes imediatamente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a batedora Dorli na Estação Algaz, em Loch Modan.', 0),
(26854, 'ptBR', 'O piloto perdido', 'Encontre o Piloto Hildeve no Lago Helm.', 'Meu amigo Mori Hildelve, que também é piloto de máquina de cerco, desapareceu nas montanhas. Nós estávamos em campo procurando um minério raro para fazer pólvora de alta qualidade. Mas, durante as buscas, ele subiu um barranco com a máquina e o motor acabou explodindo!$B$BMori tinha certeza de que havia minério naquela serra, então me pediu para ficar vigiando as máquinas de cerco e seguiu a pé.$B$BMas isso já faz dias, e eu ouvi uns grunhidos alarmantes a norte do Lago Helm, a oeste do túnel. O Mori é duro na queda, mas estou preocupado.$B$BPor favor, $n, encontre meu amigo.', '', '', '', '', '', '', '', '', '', '', 0),
(26855, 'ptBR', 'A vingança do piloto', 'Mate o Ronhagarra.$B$BEntregue a Pata Sarnenta do urso e o Diário de Hildelve para o Piloto Pisafundo no Posto de Guarda do Portão Sul.', 'Hildeve escreveu no diário que foi atacado pelo Ronhagarra, um "imenso urso garra de gelo". Apesar de ferido gravemente pela fera, conseguiu espantá-la.$B$BA julgar pelo estado do corpo de Hildeve, Ronhagarra provavelmente voltou em seguida para matá-lo.$B$BAinda assim, Hildeve ainda teve forças para anotar no diário o derradeiro pedido:$B$BVingança contra Ronhagarra.', '', '', '', '', '', '', 'Ronhagarra', '', '', 'Fale novamente com o Piloto Pisafundo no Posto de Guarda do Portão Sul.', 0),
(26856, 'ptBR', 'Rechace a invasão', 'Mate Pederneiro, Bazzalan e Jergosh, o Invocador.', 'Esta caverna já foi um lugar de grande honra. Jovens guerreiros eram trazidos aqui para matar um verme Furaterra – a primeira presa deles. Isso é algo que nós orcs levamos conosco por toda a vida.$B$BOs agentes da Lâmina Calcinante escravizaram os habitantes da caverna e planejam lançar um ataque em larga escala a Orgrimmar junto com seus aliados, os Trogg.$B$BSe você atacar os Tenentes da Lâmina, talvez seja possível pegá-los de surpresa e deter a invasão antes que ela comece.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Guarda Pétreo Kurjack nas Cavernas Ígneas.', 0),
(26857, 'ptBR', 'Lacaios de Abyssion', 'Derrote 8 unidades Draconianas ou do Crepúsculo no Covil de Abyssion.', 'Se o dragão tiver pegado o fragmento, vamos ter que atrair a atenção dele de volta para o covil.$B$BVá até o Covil de Abyssion, a leste daqui, e derrote os servos dele. Isso vai fazer com que, mais cedo ou mais tarde, ele apareça com o fragmento do Pilar do Mundo.', '', 'Servos de Abyssion derrotados', '', '', '', '', '', '', '', 'Fale novamente com a Tempestária Mylra no Mirante do Crepúsculo, que fica no Geodomo.', 0),
(26858, 'ptBR', 'Taragaman, o Famélico', 'Pegue o coração de Taragaman, o Famélico.', 'A Lâmina Calcinante conseguiu evocar um demônio impuro chamado Taragaman, o Famélico, para liderar o primeiro ataque a Orgrimmar!$B$BApresse-se e mate Taragaman em nome do Chefe Guerreiro! Lok\'tar ogar!', '', '', '', '', '', '', 'Taragaman, o Famélico', '', '', 'Fale novamente com Guarda Pétreo Kurjack nas Cavernas Ígneas.', 0),
(26859, 'ptBR', 'Searching for the Lost Satchel', 'Search Ragefire Chasm for Maur Grimtotem\'s corpse and search it for any items of interest.', 'The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She\'d like Maur\'s body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.$B$BReturn to Magatha any items of interest, and I\'m sure she would be very generous in her reward.$B$BAgain, seek the Chasm in the darkest areas of Orgrimmar.', '', '', '', '', '', '', '', '', '', '', 0),
(26860, 'ptBR', 'Chouriço de Thelsamar', 'Pegue 8 Alcatras de Urso dos Ursos Pretos em Loch Modan.', 'Sempre tem uma barriga roncando aqui em Thelsamar: crianças que correm o dia inteiro, operários dos sítios arqueológicos que voltam de um dia de trabalho... Nossos chouriços são muito famosos, já provou?$b$bNão? Bem, por estas bandas, ninguém ganha um prato de comida de graça, e não pense que você vai ser exceção só por ser $Gum:uma; $c $Gtodo:toda; chique.$b$bTraga umas alcatras de urso e deixe a cozinha comigo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Vidra Fornalenha na cidade de Thelsamar, em Loch Modan.', 0),
(26861, 'ptBR', 'Bloqueie os portões', 'Use a Pedra da Tempestade no Portão do Crepúsculo e no Portão Elemental do Covil de Abyssion.', 'Só teremos chance contra o Abyssion se conseguirmos impedir que ele receba reforços.$B$BO covil dele, a leste daqui, tem dois portões de entrada. Use esta pedra da tempestade para danificar o mecanismo dos portões.$B$BSe tudo der certo, vamos poder atacar Abyssion sem que ele receba ajuda.', '', 'Portão do Crepúsculo danificado', 'Portão Elemental danificado', '', '', '', '', '', '', 'Fale novamente com o Vidente Galekk no Mirante do Crepúsculo, que fica no Geodomo.', 0),
(26862, 'ptBR', 'Interferindo com os elementais', 'Obtenha 6 Braceletes Causticantes.', 'Os bruxos da Lâmina Calcinante escravizaram os espíritos elementais das Cavernas Ígneas, $n. Enquanto meus feitiços puderem mantê-los à distância, eles não representam perigo para a cidade, mas não posso aguentar muito mais tempo.$B$BTraga-me seis Braceletes Causticantes, que são usados para controlá-los, e eu liberarei seus espíritos nas Cavernas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Bovaal Chifre Branco nas Cavernas Ígneas.', 0),
(26863, 'ptBR', 'Patas nojentas', 'Pegue seis lotes de Equipamento de Mineração na Mina da Prata.', 'A Mina da Prata, a leste daqui, está esgotada há muito tempo. A Liga dos Mineradores a transformou em armazém, mas agora os kobolds estão ocupando as galerias e botando aquelas patas nojentas em ferramentas enânicas de qualidade!$B$BNós vamos expulsar esses vermezinhos em breve, mas a Liga quer retirar os equipamentos antes que nós, guerreiros, invadamos o lugar e quebremos alguma coisa. Vai ser uma operação difícil, então sugiro que você leve alguns companheiros para ajudá-$Glo:la;.$B$BO equipamento está armazenado em caixotes da Liga dos Mineradores ao longo de toda a mina. Boa sorte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Lançatroz na Estação Algaz, em Loch Modan.', 0),
(26864, 'ptBR', 'Notícias dos gnolls', 'Entregue a Cabeça do Encarregado Zombeteiro para o Montanhista Kadrell.', 'Preciso que você mostre isso para o Montanhista Kadrell. Diga a ele que as criaturas sórdidas destas bandas podem estar se juntando.', '', '', '', '', '', '', '', '', '', '', 0),
(26865, 'ptBR', 'Inimigos subterrâneos', 'Fale com o Guarda Pétreo Kurjack.', 'Existem inimigos da Horda debaixo de nossa cidade, $c.$B$BA Lâmina Calcinante planeja tomar Orgrimmar, e já conquistou as Cavernas Ígneas! Precisamos atacá-los e retomar o que é nosso!$B$BVá falar com o guarda pétreo Kurjack dentro das Cavernas Ígneas. Ele terá ordens adicionais para você.', '', '', '', '', '', '', '', '', '', '', 0),
(26866, 'ptBR', 'Inimigos subterrâneos', 'Fale com o Guarda Pétreo Kurjack.', 'As Cavernas Ígneas de Orgrimmar foram tomadas pela Lâmina Calcinante. $n, não podemos permitir que permaneçam impunes e pousem os olhos sobre o Penhasco do Trovão.$B$BFale com o guarda pétreo Kurjack logo na entrada das cavernas. Ajude-o como puder, pois os nossos destinos estão entrelaçados.', '', '', '', '', '', '', '', '', '', '', 0),
(26867, 'ptBR', 'Inimigos subterrâneos', 'Fale com o Guarda Pétreo Kurjack.', 'Com a graça e gentileza que lhe são características, o Chefe Guerreiro Garrosh requisitou a sua presença nas Cavernas Ígneas para ajudar a retomá-la da Lâmina Calcinante. Parece que sua robusta cidade não é tão impenetrável quanto ele imaginava.$B$BFale com o guarda pétreo Kurjack, ele fica bem na entrada das cavernas. Ele ficará feliz de conseguir ajuda competente.', '', '', '', '', '', '', '', '', '', '', 0),
(26868, 'ptBR', 'Eixo do terror', 'Vista o Kit de Disfarce Inteligente de Planta para se esgueirar até o Representante Pelemusgo e lance os Feromônios Potentes de Murloc nele.', 'OK, agora cala a boca e me escuta, porque vou te contar o plano.$B$BOs gnolls e murlocs devem estar se reunindo em algum lugar. Então você pega esse meu disfarce inteligente de planta e bota ele para ficar com cara de planta. Aí você entra lá de fininho e joga o feromônio nos pelemusgos que estão com os murlocs.$B$BAí os murlocs vão subir pelas paredes, e os pelemusgos vão pensar duas vezes antes de trabalhar de novo com esses pestinhas malucos!', '', 'Pelemusgo marcado', '', '', '', '', '', '', '', 'Fale novamente com Canária Cascatira na cidade de Thelsamar, em Loch Modan.', 0),
(26869, 'ptBR', 'No fundo do abismo', 'Encontre Dolorita nos Abismos Esfacelados.', '<O chão treme levemente, e a voz grave e familiar de Diamant parece falar com você como que a partir das rochas.>$B$BMuito bem, $r.$B$BNo seio dos túneis abaixo está a pedra que você procura, a dolorita.$B$BSão muitos os perigos adiante...$B$BPerigos temidos até mesmo pelos Senhores da Pedra.$B$BMantenha-se firme.$B$BMantenha-se forte.$B$BA força das rochas está sob seus pés.', '', '', '', '', '', '', '', '', '', '', 0),
(26870, 'ptBR', 'Limpando a caverna', 'Ebru, na Caverna Ululante, quer que você mate os Lordes da Presa: Cobrahn, Sucurina, Pítias e Serpentis.', 'Naralex tinha um objetivo nobre.$B$BNosso grande líder almejava entrar no Sonho Esmeralda e ajudar estas terras áridas a voltar a ser novamente a floresta pujante que outrora havia aqui.$B$BEntretanto, aconteceu algo muito errado.$B$BOs Druidas da Presa, aliados de confiança de Naralex, voltaram-se contra ele! Eles não querem recuperar os Sertões, e sim dominá-los.$B$B$n, antes que possamos despertar Naralex e restaurar o equilíbrio deste lugar, você precisa erradicar os Lordes da Presa. A influência está muito enraizada.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ebru.', 0),
(26871, 'ptBR', 'Uma rocha entre muitas', 'Fale novamente com Diamant no Portão de Lorthuna, levando o Pedaço de Dolorita.', '<O chão treme levemente, e a voz grave e familiar de Diamant parece falar com você como que a partir das rochas.>$B$BVocê fez o que pedi.$B$BAgora volte, e $Ginteiro:inteira;.$B$BE não esqueça a pedra.', '', '', '', '', '', '', '', '', '', '', 0),
(26872, 'ptBR', 'Pelego anormal', 'Nalpak quer 10 Pelegos Anormais.', 'Enquanto Naralex descia mais e mais fundo no pesadelo, uma raça estranha de feras surgiu nos Sertões e fez da Caverna Ululante o seu lar.$B$BEssas criaturas anormais têm características estranhas, que parecem de outro mundo. Sua mera existência causa grande dor à terra. Creio que a morte delas seria uma grande ajuda para nosso trabalho de recuperação da caverna.$B$BSe você se sente à altura do desafio, mate quantas feras puder e me traga os pelegos delas como prova da morte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nalpak.', 0),
(26873, 'ptBR', 'Métodos preventivos', 'Nalpak quer que você colete 5 Ofídeas.', 'Nessa caverna existe uma erva com poderes incalculáveis, $n. Você pode coletar algumas amostras para mim?$B$BÉ uma flor rara chamada "ofídea". Creio que, em grandes quantidades, ela tem o poder de impedir que pesadelos como o de Naralex ocorram.$B$BInfelizmente, ofídeas só podem ser encontradas nos recessos mais sombrios da caverna.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nalpak.', 0),
(26875, 'ptBR', 'Crepúsculo infinito', 'Mate 12 Invasores do Crepúsculo e 1 Furitérreo Profanado.', 'Os Sectários do Crepúsculo estão aqui! Eles estão tentando interromper o ritual! Vá até as salas de trás e nos ajude!', '', 'Invasores do Crepúsculo mortos', '', '', '', '', '', '', '', '', 0),
(26876, 'ptBR', 'O fragmento do Pilar do Mundo', 'Coloque o Estandarte da Harmonia Telúrica no meio do Covil de Abyssion. Em seguida, mate-o e pegue o Fragmento Superior do Pilar do Mundo.', 'Chegou a hora, $n. Nós vimos o Abyssion voltando para o covil.$B$BO Martelo do Crepúsculo deve ter pensado que o fragmento ficaria muito bem guardado com um dragão. Mas eu já vi muitos dragões nessa vida e sei qual é a fraqueza deles: o orgulho.$B$BAbyssion não vai fugir de uma luta contra nós, pobres mortais.$B$BFinque o estandarte da Harmonia Telúrica no meio do covil de Abyssion. E depois que nós o derrotarmos, entregue o fragmento para Maruut. Temos que recompor o Pilar do Mundo o mais rápido possível.', '', '', '', '', '', '', '', '', '', 'Entregue o Fragmento Superior do Pilar do Mundo para Maruut Atapedras no Templo da Terra.', 0),
(26878, 'ptBR', 'Discípulos de Naralex', 'Fale com Nalpak na Caverna Ululante.', '$C, os Sertões já foram um dos lugares mais bonitos de Kalimdor. Um lugar promissor e cheio de vida.$B$BMas agora, como você vê, esses tempos se foram... E eles se tornaram palco de contendas e de grande tormento.$B$BOs Discípulos de Naralex buscam limpar a Caverna Ululante para lhe devolver a beleza de outrora. Fale com Nalpak, logo na entrada da Caverna Ululante, se quiser nos ajudar.', '', '', '', '', '', '', '', '', '', '', 0),
(26879, 'ptBR', 'Disciples of Naralex', 'Speak with Nalpak in the Wailing Caverns.', '$C, this place is, shall I say, not optimal for my business endeavors. If it were more lively, I have an idea that would make me the richest goblin that\'s ever lived!$B$BA $c of your stature must see the potential in that, or at least care about the environment or something.$B$BGo talk to Nalpak just inside the Wailing Caverns, he\'s a Disciple of Naralex and, just between you and me, I think they\'re going to fix this blasted place for good! It\'s my big break!', '', '', '', '', '', '', '', '', '', '', 0),
(26880, 'ptBR', 'Gilneas City Unphase Cheat', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(26881, 'ptBR', 'Em busca de Aluwyn', 'Procure a Sentinela Aluwyn nas Profundezas Negras.', 'Algo sinistro está acontecendo aqui, $n. Tememos que os rumores de que o Martelo do Crepúsculo está nas Profundezas Negras sejam verdadeiros.$B$BEu enviei a Sentinela Aluwyn, uma das nossas melhores batedoras, para investigar o caso, mas ela ainda não regressou.$B$BEncontre-a. Se ela ainda estiver viva, recolha todas as informações que ela tiver.', '', '', '', '', '', '', '', '', '', '', 0),
(26882, 'ptBR', 'Vilão das Profundezas', 'Obtenha a cabeça do Senhor do Crepúsculo Kelris.', 'Perdi as forças e preciso de ajuda!$b$bHá muito tempo, aqui era um grande templo de Eluna. Mas infortúnios o levaram às ruínas quando a corrupção de um Deus Antigo se ergueu das profundezas e conspurcou o poço lunar.$b$bAku\'Mai, um servo do Deus Antigo, ergueu-se das águas.$b$bOs sectários do Martelo do Crepúsculo se uniram às nagas para tomar estas terras e, liderados por Kelris, sacrificam inocentes para Aku\'Mai em troca de poder.$b$bMate Kelris e entregue a cabeça dele para Ashelan.', '', '', '', '', '', '', 'Senhor do Crepúsculo Kelris', '', '', 'Fale novamente com Ashelan.', 0),
(26883, 'ptBR', 'Cachoeira do Crepúsculo', 'Consiga 3 Pingentes do Crepúsculo.', 'Fortalecidos pelos ritos milenares dos Deuses Antigos, os integrantes do Martelo do Crepúsculo estão dispostos a fazer de tudo para sair da escuridão e levar morte e terror ao mundo inteiro.$b$bAcreditamos que o Martelo do Crepúsculo tenha se aliado às nagas e esteja reunindo forças aqui.$b$bPrecisamos impedir a concretização dos planos urdidos nas trevas ancestrais.$b$bDeclare guerra ao Martelo e traga as provas do seu feito. Você receberá uma recompensa bem generosa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Aluwyn.', 0),
(26884, 'ptBR', 'Pesquisando a corrupção', 'Reúna 8 Troncos Encefálicos Corrompidos.', 'Os tolos elfos sangrentos estão mexendo com magia demoníaca. Eles agem como se não soubessem o que aconteceu com as nagas e com os sátiros de Kalimdor.$b$bTemo que os elfos sangrentos sofram deformação semelhante. O nascimento de mais uma vil raça de monstros será muito penoso para o futuro de Azeroth.$b$bPretendo estudar o tronco encefálico dos sátiros e das nagas para deduzir onde findará o caminho escolhido pelos Sin\'dorei. Procure não causar danos aos troncos quando matar as criaturas, pois apenas amostras em perfeito estado terão utilidade para os meus estudos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Relwyn.', 0),
(26885, 'ptBR', 'Conhecimento nas Profundezas', 'Encontre o Manuscrito de Lorgalis.', 'É meu dever de aprendiz coletar artefatos perdidos para meus superiores. Artefatos antigos. Artefatos poderosos. Artefatos que abrem novas possibilidades e artefatos que podem despertar mais d\'Aqueles que Dormem, se não forem tratados com a devida cautela.$B$BHá rumores de que um artefato antigo, o Manuscrito de Lorgalis, está no fundo do Poço de Ask\'ar, em um Baú Coberto de Ferro. Lá era o antigo lar dos nossos ancestrais há muito idos. Eles detinham muitos conhecimentos antes de a cidade ser entregue às ruínas.$B$BPor favor, $n! Encontre o manuscrito. Não tenho habilidade suficiente para seguir adiante!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Aprendiz de Sentinela Issara.', 0),
(26886, 'ptBR', 'Nada mais de capataz', 'Mate o Capataz dos Mares do Sul.', 'Aquele maldito navio no lado leste da enseada não para de atirar em nós. Eu me divirto vendo os goblins sendo acertados por bolas de canhão, mas agora eles estão acertando alguns dos meus amigos gnomos também!$B$BSeria muito, mas muito legal mesmo se você conseguisse subir naquele navio. Tem um capataz malvadão que grita ordens para a tripulação. Tenho certeza de que todo esse inferno acabaria se ele sumisse... ou morresse.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kelsey Fagulhaço na Enseada do Armador Perdido, que fica em Tanaris.', 0),
(26887, 'ptBR', 'Enchendo os bolsos', 'Consiga 20 Obturações de Ouro dos Mosqueteiros dos Mares do Sul ou dos Capangas dos Mares do Sul.', 'Sei que devemos fazer amizade com os goblins Bondebico, mas aqueles goblins Borraquilha são tão grossos!$B$BVocê acredita que eu vi eles roubando obturações de ouro dos dentes dos mosqueteiros e capangas dos Mares do Sul? Quem eles acham que são?$B$BÉ claro que a melhor coisa a se fazer é matar aqueles piratas e roubarmos as obturações nós mesmos. Aí sim dar uma parte para os Bondebico como prova da nossa amizade! Desça até lá e mostre a esses goblins como se faz!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kelsey Fagulhaço na Enseada do Armador Perdido, que fica em Tanaris.', 0),
(26888, 'ptBR', 'Pesadelo das Profundezas', 'Mate Aku\'mai.', 'Nos covis mais recônditos das Profundezas Negras, se oculta um monstro gerado pelos Deuses Antigos. Nós o conhecemos apenas como Aku\'mai.$B$BOs Deuses Antigos e seus servos são uma grande ameaça para o mundo. Azeroth esteve sob o domínio deles no passado, e receio que eles tentem voltar, ou destruam o mundo na tentativa.$B$B$n, Aku\'mai é uma criatura capaz de causar terror inimaginável. Não podemos permitir que ele continue vivo. Destrua-o.', '', '', '', '', '', '', 'Aku\'mai', '', '', 'Fale novamente com Je\'neu Sancrea.', 0),
(26889, 'ptBR', 'Chefe... tô cansada pra chuchu', 'Fale com Zeke Borrabotas no Vilarejo dos Falsários.', 'Puxa vida, que limpeza que fizemos!$B$B<Kelsey pigarreia.>$B$BEscute, $n. Estou prestes a abandonar este pardieiro. Vou para longe desses goblins... Chega de bancar a amiguinha. Se você quiser continuar a defender os interesses de Gnomeregan e da Aliança por aqui, vá para o sul até o Vilarejo dos Falsários.$B$BFale com Zeke Borrabotas. Lembre-se de que qualquer trabalho para o Bondebico vai nos ajudar a expulsar o Borraquilha de Tanaris de uma vez por todas.', '', '', '', '', '', '', '', '', '', '', 0),
(26890, 'ptBR', 'A essência de Aku\'mai', 'Recolha 20 Safiras de Aku\'Mai.', 'Há muitas drusas de safira nos primeiros túneis das Profundezas Negras. Nós reparamos que, logo após as nagas começarem a extrair o cristal, o armamento delas melhorou muito.$B$BOs cristais parecem conter um grande poder elemental e, se forem usados de forma adequada, podem funcionar como um poderoso material para forjar armamentos.$B$BVocê pode me ajudar, $n? As Profundezas Negras ficam próximas à Praia de Zoram, ao norte de nosso assentamento.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dagrun Martelo da Ira.', 0),
(26891, 'ptBR', 'Nas ruínas', 'Extraia o Núcleo das Profundezas.', 'O Martelo do Crepúsculo ocupou as Ruínas do Sacrário Lunar. A intenção deles com isso só pode ser coagir os elementos a se voltarem contra nós.$B$B$n, encontre os agentes do Crepúsculo e, em seguida, a pedra das profundezas, que deve estar submersa em algum lugar bem debaixo do nariz deles. Dentro da pedra está o núcleo das profundezas, que, quando lido da forma correta, relata um histórico de todas as atividades elementais na área. Com o núcleo, espero que eu e a Harmonia Telúrica consigamos fazer alguma coisa para detê-los!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Je\'neu Sancrea.', 0),
(26892, 'ptBR', 'No fundo das Profundezas', 'Mate Ghamoo-Ra, Gelihast e a Lady Sarevess.', 'As nagas e o Martelo do Crepúsculo estão trabalhando juntos para reverter o nosso progresso aqui. Além disso, o Je\'neu me disse que está sentindo a presença de um Deus Antigo sob nossos pés.$B$BSe eles querem ver o circo pegar fogo, é isso que lhes daremos.$B$B$n, mate os guerreiros mais fortes deles e vamos ver qual será a reação.$B$BAs Profundezas Negras estão repletas de passagens submersas e caminhos laterais que podem esconder os alvos. Faça a busca com cuidado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zeya.', 0),
(26894, 'ptBR', 'Profundezas Negras', 'Fale com Je\'neu Sancrea.', 'O Martelo do Crepúsculo nos provoca com seu desrespeito. Vamos expulsar todos eles e seus aliados daqui para sempre.$B$BVá para o norte, para as Profundezas Negras, e fale com Je\'neu Sancrea. Ele já está do lado de dentro.$B$BAh, tome cuidado com Zeya. Às vezes, ela é um pouco... temperamental.', '', '', '', '', '', '', '', '', '', '', 0),
(26895, 'ptBR', 'A Cúpula do Trovão!', 'Fale com o Doutor Asnamanga em Geringontzan.', 'Olá $Gamigo:amiga;! Você gosta de aventura? Adrenalina? Dinheiro? Violência?$B$BEspero que pelo menos de violência você goste, pois a Cúpula do Trovão de Geringontzan acaba de ser reaberta! Como fiquei triste em vê-la fechada por tanto tempo por causa de processos por dano físico, multas por extorsão e violação de direitos autorais... mas agora ela voltou e está esperando por combatentes fortes e selvagens como você!$B$BVá para Geringontzan e fale com o Dr. Asnamanga para participar. Chame seus amigos!', '', '', '', '', '', '', '', '', '', '', 0),
(26896, 'ptBR', 'A Cúpula do Trovão!', 'Fale com o Doutor Asnamanga em Geringontzan.', 'Olá $Gamigo:amiga;! Você gosta de aventura? Adrenalina? Dinheiro? Violência?$B$BEspero que pelo menos de violência você goste, pois a Cúpula do Trovão de Geringontzan acaba de ser reaberta! Como fiquei triste em vê-la fechada por tanto tempo por causa de processos por dano físico, multas por extorsão e violação de direitos autorais... mas agora ela voltou e está esperando por combatentes fortes e selvagens como você!$B$BVá para Geringontzan e fale com o Dr. Asnamanga para participar. Chame seus amigos!', '', '', '', '', '', '', '', '', '', '', 0),
(26897, 'ptBR', 'Profundezas Negras', 'Fale com a Sentinela Aluwyn.', 'Por mais que a nossa posição esteja exposta, ainda estamos mais seguros do que nossos amigos nas Profundezas Negras! Eles estão a poucos metros das forças do Martelo do Crepúsculo. Fale com a sentinela Aluwyn e ajude-os como puder!', '', '', '', '', '', '', '', '', '', '', 0),
(26898, 'ptBR', 'Profundezas Negras', 'Fale com a Sentinela Aluwyn.', 'Estas florestas são a minha vida, $c. As coisas parecem ir muito mal, mas prefiro enfrentar a Horda sozinho a ficar de braços cruzados enquanto destroem as árvores.$B$BVá para as Profundezas Negras, a oeste. Quando chegar lá, encontre a Sentinela Aluwyn. Ela é uma amiga de confiança que precisa de ajuda.$B$BOs orcs do Assentamento Zoram\'gar ameaçam a posição dela. Se tomarem as Profundezas Negras, certamente cortarão todas as árvores para alimentar as chamas da loucura.', '', '', '', '', '', '', '', '', '', '', 0),
(26899, 'ptBR', 'O inimigo do meu inimigo', 'Obtenha a cabeça do Senhor do Crepúsculo Kelris.', 'Sectários... Sacrifício... Poder...$B$BInimigo... despertou...$B$BDeus Antigo... me... aprisionou...$B$BSenhor... Kelris...$B$BTraga cabeça dele... Vingança...$B$BEXTERMÍNIO!!!', '', '', '', '', '', '', 'Senhor do Crepúsculo Kelris', '', '', 'Fale novamente com o Extirpador Flamejante.', 0),
(26901, 'ptBR', 'Matéria orguânica', 'Consiga 1 porção de Guano de Morcego.', 'Os morcegos nativos do Urzal dos Tuscos produzem uma substância um tanto peculiar. O fedor do guano deles parece pôr os javatuscos em um estado de fúria descontrolada, e este lugar está tomado por ele!$b$bEncontre a caverna onde tais morcegos vivem e me traga uma amostra de lá. Se conseguirmos reverter o efeito e produzir um antídoto, talvez possamos salvar os javatuscos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Auld Agulha de Pedra.', 0),
(26902, 'ptBR', 'De volta à cidade Accepted Tracking Event', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(26903, 'ptBR', 'Importador Willix', 'Escolte o Importador Willix até a saída do Urzal dos Tuscos.', 'Finalmente, alguém para ajudar!$b$bVocê não faz ideia do tempo que estou preso aqui. Não lembro quando foi a última vez que vi o mundo lá fora.$b$bEntenda, sou um empresário sempre em busca de lucros. Correu um boato de que focinhos de porcos estavam em alta no mercado, então pensei: me dei bem! Como você pode ver, eu estava um pouquinho enganado...$b$bEnfim, se você me ajudar a escapar daqui, sua generosidade não será esquecida!', 'Ajude o Importador Willix a escapar do Urzal dos Tuscos.', '', '', '', '', 'Ajude o Importador Willix a escapar do Urzal dos Tuscos.', '', '', '', 'Fale com o Importador Willix.', 0),
(26904, 'ptBR', 'Corrupção', 'Alcance o nível 3 para aprender Corrupção. Em seguida, lance o feitiço 5 vezes contra um Boneco de Treinamento perto da entrada de Sidermar.', 'Poucas pessoas, especialmente entre nossos aliados, compreendem verdadeiramente a natureza do poder que possuímos. Eles nos desprezam por causa de nossa busca por um conhecimento que eles são fracos demais para saber usar.$B$BÀ medida que você se fortalecer, começará a descobrir novos feitiços, aumentando seu poder ainda mais.\n\nAgora vá, ganhe mais experiência, depois volte quando tiver aprendido um feitiço novo. Vamos ver se você realmente tem talento para dominar as artes sombrias.', '', 'Praticar lançar Corrupção', '', '', '', '', '', '', '', 'Fale novamente com Sarala Maltagris em Sidermar.', 0),
(26905, 'ptBR', 'Investida de Agamaggan', 'Arranque o coração de Charlga Talhaflanco.', 'Ouça com atenção, mortal.$B$BOs Javatuscos são meus filhos e meu sangue pulsa forte por estas terras.$B$BCharlga Talhaflanco levou minhas crianças para a escuridão, enlouquecidas pelo Flagelo.$B$BMate-a, $n. Mate-a e abra os olhos de meus filhos.$B$BDê aos Javatuscos a chance de retornar às suas nobres origens e merecer minha bênção outra vez.$B$BTraga-me o coração dela!!!$B$B', '', '', '', '', '', '', 'Charlga Talhaflanco', '', '', 'Fale novamente com o Espírito de Agamaggan.', 0),
(26906, 'ptBR', 'Agamaggan', 'Fale com o Espírito de Agamaggan.', 'Sinto a presença de um ser poderoso dentro destes espinhos retorcidos, $n. Toda esta área tomou vida devido à presença dele.$B$BDeve ser o Espírito de Agamaggan! Ele foi um dos primeiros e mais poderosos seres a existir, e os javatuscos o veneram fervorosamente.$B$BTodas as vinhas que você vê espalhadas nesta terra são resultado do sangue dele, derramado para salvar Azeroth durante a Guerra dos Antigos.$B$BEle é o único ser capaz de conduzir os Javatuscos de volta à sua nobre origem.$B$BVocê precisa encontrá-lo.', '', '', '', '', '', '', 'Espírito de Agamaggan', '', '', 'Teste', 0),
(26907, 'ptBR', 'Acabe com eles!', 'Mate o Caçador Tuscosso, Rugug e o Senhor da Guerra Presatak.', 'Para manter um mínimo de segurança nos Sertões Meridionais, temos que dar fim à atual liderança da tribo dos Tuscos. Embora Charlga Talhaflanco comande seu povo por meio de seu poderoso misticismo, seu verdadeiro poder reside na força dos anciões a sua volta.$B$BMate-os. Cace Tuscosso, o líder da vara. Dê fim a Rugug, o líder dos Geomantes. Esmague Presatak, o Senhor da Guerra dos javatuscos.$B$BVolte quando tiver cumprido sua missão.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Auld Agulha de Pedra.', 0),
(26908, 'ptBR', 'Caçando agulha no Urzal', 'Fale com Auld Agulha de Pedra.', 'A raiva de Mankrik pela morte de sua esposa nos traz novos problemas, $c.$B$BOs javatuscos do Urzal dos Tuscos são muito mais cruéis e impiedosos do que Mankrik podia imaginar.$B$BVocê devia ir para o sul e conversar com meu antigo amigo, Auld Agulha de Pedra. Ele luta para acabar com tal situação antes que esta frágil e castigada terra sofra ainda mais.', '', '', '', '', '', '', '', '', '', '', 0),
(26909, 'ptBR', 'Os estilhaços de pedra', 'Investigue os Estilhaços de Myzrael.', 'Antigas pedras estão espalhadas por esta terra. Os elementos acorrem a elas, cercando-as de forma protetora.$B$BOs locais onde isso acontece guardam imenso poder, e o maior deles fica a oeste da Ruína do Martelo. Não existe alma viva por lá, mas se você estiver $Gsozinho:sozinha;, é possível ouvir os sussurros da própria terra.$B$BHá muito não visito aquele local, mas nossos batedores dizem que os sussurros voltaram. Você investigaria por mim? Checaria se as pedras ainda falam?', '', '', '', '', '', '', '', '', '', '', 0),
(26910, 'ptBR', 'Carta cinzelada', 'Leia a Carta Cinzelada e fale com Adalgisa Ferrão no Vale de Vila Norte.', 'Pediram que eu lhe mostrasse isso tão logo você voltasse da missão contra os espiões Rocha Negra, $n. Parece ser uma carta lacrada com o selo de Adalgisa Ferrão, a instrutora de caçadores daqui. Sugiro que você leia essa carta antes de tratar de qualquer outro assunto aqui na abadia.', '', '', '', '', '', '', 'Adalgisa Ferrão', '', '', '', 0),
(26911, 'ptBR', 'O conto de Myzrael', 'Fale novamente com Zaruk na Ruína do Martelo, que fica no Planalto Arathi.', 'A voz se cala e uma sensação de inquietude invade seu coração. Algo não está certo.$B$BTalvez você devesse contar ao Zaruk o acontecido.', '', '', '', '', '', '', '', '', '', '', 0),
(26912, 'ptBR', 'A princesa libertada', 'Evoque e derrote Myzrael nos Estilhaços de Myzrael.', 'Myzrael é uma impostora. Ela é uma antiga força confinada há muito tempo, e assim deve permanecer.$B$BVocê tem de enfrentá-la nos Estilhaços de Myzrael, onde a ouviu pela primeira vez. Evoque-a com este pergaminho e então derrote-a. Recupere os Grilhões Sobrenaturais e prenda-os aos Estilhaços para que ela seja aprisionada mais uma vez.$B$BBoa sorte, $n... E que meu passado nunca mais $Go:a; atormente.', '', '', '', '', '', '', 'Myzrael', '', '', 'Volte aos Estilhaços de Myzrael no Planalto Arathi.', 0),
(26913, 'ptBR', 'Com toda a carga', 'Alcance o nível 3 para aprender Investida. Depois, pratique-a em um Boneco de Treinamento ao sul da entrada da Abadia de Vila Norte.', 'Agora que você já pôde testar suas habilidades em batalha, é hora de explicar mais um motivo de o treinamento ser tão importante.$B$BÀ medida que você obtém mais experiência, você poderá dominar técnicas com as quais jamais sonhou.\n\nVá, obtenha mais experiência, aprenda uma nova habilidade e demonstre-a em um dos bonecos de treinamento.', '', 'Praticar Investida', '', '', '', '', '', '', '', 'Fale novamente com Hipólito Valentim dentro do Salão das Armas, na Abadia de Vila Norte.', 0),
(26914, 'ptBR', 'Corrupção', 'Alcance o nível 3 para aprender a habilidade Corrupção. Então, pratique-a 5 vezes em um Boneco de Treinamento ao sul da entrada da Abadia de Vila Norte.', 'Precisamos tomar cuidado com o modo como falamos perto da abadia e nos arredores, mas não deixe que isso atrapalhe sua busca de poder.$B$BÀ medida que você se torna mais poderoso, você começará a ouvir as vozes vis, dando a você os poderes das artes sombrias.\n\nVá, obtenha mais experiência e aprenda um novo feitiço. Depois, pratique o que aprendeu em um dos bonecos de treinamento.', '', 'Praticar Corrupção', '', '', '', '', '', '', '', 'Fale novamente com Drusilla La Salle perto da Abadia de Vila Norte.', 0),
(26915, 'ptBR', 'Corte profundo', 'Alcance o nível 3 para aprender Eviscerar, depois encontre um Boneco de Treinamento ao sul da entrada da Abadia de Vila Norte e pratique o Eviscerar 3 vezes.', 'Até agora, você só aprendeu noções básicas do modo de combate dos ladinos, mas já é hora de lhe ensinar uma nova habilidade. Os ladinos são reconhecidos pela habilidade de encadear técnicas de combate em ordem progressiva de poder de destruição.$B$BÀ medida que você obtém mais experiência, você aprenderá novas coisas, e essa é uma das primeiras. Quero que você pratique essa técnica em um dos bonecos de treinamento ao sul da entrada da abadia.', '', 'Praticar Eviscerar', '', '', '', '', '', '', '', 'Fale novamente com Rufino Raposo perto da Abadia de Vila Norte.', 0),
(26916, 'ptBR', 'O domínio do poder arcano', 'Alcance o nível 3 para aprender Nova Congelante. Então, pratique-a 2 vezes contra um Boneco de Treinamento ao sul da entrada da Abadia de Vila Norte.', 'Mag$go:a;, você aprenderá vários feitiços à medida que sua compreensão aumentar. Tudo o que você precisa é obtere mais experiência e os segredos do poder arcano se revelarão a você.\n\nVocê verá. Vá treinar seus poderes e me mostre o que aprendeu.', '', 'Praticar lançar Nova Congelante', '', '', '', '', '', '', '', 'Fale novamente com Gaspar Melchior na Ala da Biblioteca da Abadia de Vila Norte.', 0),
(26917, 'ptBR', 'O caminho do caçador', 'Alcance o nível 3 para aprender Tiro Firme, depois encontre um Boneco de Treinamento ao sul da entrada da Abadia de Vila Norte e pratique o Tiro Firme 5 vezes.', 'Ouvi dizer que você ajudou a eliminar alguns dos orcs. E também já provou que sabe se virar em combate.$B$BÀ medida que você obtém mais experiência em combate, você aprenderá a fazer novas coisas. Eu quero que você vá, adquira mais experiência e então teste as novas habilidades que você aprendeu em um dos bonecos de treinamento ao sul da entrada da abadia.', '', 'Pratique o Tiro Firme', '', '', '', '', '', '', '', 'Fale novamente com Adalgisa Ferrão perto da Abadia de Vila Norte.', 0),
(26918, 'ptBR', 'O poder da Luz', 'Alcance o nível 3 para aprender Selo de Comando. Use o Selo em si mesm$go:a; e ataque um dos Bonecos de Treinamento ao sul da entrada da Abadia de Vila Norte.', 'À medida que você avança em sua jornada de Paladino, você se aproximará cada vez mais da Luz, aprendendo novas habilidades.\n\nVá, obtenha mais experiência e aprenda uma nova habilidade. Demonstre-a para mim e nós continuaremos o seu treinamento.', '', 'Usar Selo de Comando e acertar um Boneco de Treinamento', '', '', '', '', '', '', '', 'Fale novamente com o Irmão Samuel na Abadia de Vila Norte, dentro do Salão das Armas.', 0),
(26919, 'ptBR', 'Aprenda a Palavra', 'Alcance o nível 3 para aprender Palavra Sombria: Dor, depois lance o feitiço 5 vezes em um dos bonecos de treinamento perto da Abadia de Vila Norte.', 'Uma de suas responsabilidades como $gsacerdote:sacerdotisa; é cuidar dos feridos. Outra responsabilidade é sair pelo mundo e ser mais... pró-ativ$go:a; na defesa deles.$B$BÀ medida que você fizer isso, você ganhará mais poder e aprenderá coisas novas.\n\nPor que você não sai por aí, obtém mais experiência e depois volta aqui para me mostrar o que aprendeu?', '', 'Praticar Palavra Sombria: Dor', '', '', '', '', '', '', '', 'Fale novamente com a Sacerdotisa Anita dentro da Abadia de Vila Norte.', 0),
(26920, 'ptBR', 'A batalha por Andorhal', 'Apresente-se a Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 'Corra, $n... não temos tempo a perder.$b$bA cidade de Andorhal está no meio de uma guerra tríplice entre os Renegados, a Aliança e o Flagelo. A Grande Dama Sylvana enviou um dos melhores cavaleiros da morte para liderar o ataque em prol de sua causa, mas tenho certeza de que toda ajuda será bem-vinda. Com a morte de Arthas, é chegada a hora dos Renegados tomarem Andorhal.$b$bFale com o tratador de morcegos Timóteo Canorus quando estiver pront$go:a;. Ele colocará você no primeiro morcego a caminho de Andorhal.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(26921, 'ptBR', 'Primeiro o Flagelo... depois a Aliança', 'Mate 15 Flagelos Ressequidos dentro de Andorhal.', 'O Umbromestre Gandling, da Seita dos Malditos, lidera a ofensiva do Flagelo aqui em Andorhal. Meu antigo companheiro, Thassarian, irá liderar as forças da Aliança. Para conquistar Andorhal nós teremos que derrotar ambos, mas certamente falharemos se enfrentarmos os dois de uma vez.$b$bEu conheço Thassarian bem o suficiente para saber que ele irá focar o ataque contra o Flagelo primeiro. Nós faremos o mesmo.$b$bAcabaremos com os Flagelos mais fracos e ressequidos para diminuir suas forças. A Aliança terá que esperar um pouco mais para provar a nossa ira.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(26922, 'ptBR', 'O fluxo interminável', 'Use as Granadas de Mão do Arlindo para matar 5 Berserkers Espetosso e destruir um Animus dos Ossos do Flagelo.', 'Araj, o Evocador, está aumentando as defesas do Flagelo com esqueletos simples... um exército de criaturas fracas que são mais capazes de te soterrar do que de vencer propriamente. Ele estocou animi nas torres norte de Andorhal e elas ficam produzindo esqueletos em um ritmo incessante. Mas eu tenho uma solução!$b$b<O Arlindo entrega um punhado de granadas para você.>$b$bO objetivo é simples. Jogar essas granadas em um animus de ossos... ou, se a oportunidade aparecer, no meio de uma multidão de esqueletos... irá transformá-los em farelos.', '', 'Animus dos Ossos do Flagelo destruído', '', '', '', '', '', '', '', 'Fale novamente com Arlindo Inácio em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(26923, 'ptBR', 'Máquinas de guerra', 'Destrua 6 Beemotes Tripaberta em Andorhal.', 'Esses tolos nunca vão derrotar o Flagelo com essas abominações soltas por aí. Koltirus tagarela sobre reduzir o número deles mas as melhores armas do Flagelo, aqui em Andorhal, são esses brutamontes que conseguem jogar meus necroguardas como se fossem bonecas de pano.$b$bPra mim basta! $n, entre no campo de batalha e destrua esses monstros.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lívida Corvossol em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(26924, 'ptBR', 'Scolomantiano', 'Mate o Umbromestre Gandling em Andorhal.', 'Scolomântia é uma das poucas fortalezas a oeste de Thondroril que ainda permanecem sob controle do Flagelo. O chefe da Scolomântia, um sectário conhecido como umbromestre Gandling, apareceu no campo de batalha.$b$bEsse foi o último erro que ele cometeu.$b$bVocê encontrará Gandling em uma praça perto da parte sul da cidade. Eu quero que você lute contra ele e o enfraqueça. Eu vou juntar-me a você para acabar com ele.', '', 'Umbromestre Gandling morto', '', '', '', '', 'Umbromestre Gandling', '', '', 'Fale novamente com Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(26925, 'ptBR', 'Araj, o Evocador', 'Mate Araj, o Evocador. Você pode usar as Granadas de Mão do Arlindo para destruir os Berserkers Espetosso.', 'Depois de destruir o animus, nosso próximo passo lógico é acabar com o próprio Araj e pegar um pedaço do filactério dele. Você provavelmente já o viu, espreitando, próximo à fonte no meio da cidade.$b$bLeve essas granadas pra você. Elas não vão adiantar nada contra o Araj, mas se ele resolver evocar aqueles esqueletos, você pode usá-las para explodir eles em pedacinhos. Outra vez.', '', '', '', '', '', '', 'Araj, o Evocador', '', '', 'Fale novamente com Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(26926, 'ptBR', 'Vitória, por enquanto', 'Apresente-se ao Alto-executor Arcabuz no Baluarte, que fica nas Clareiras de Tirisfal.', 'Os Renegados são vitoriosos, e nossas tropas continuam fortalecidas. A estratégia militar clássica reza que devemos atacar a Aliança agora, enquanto eles estão se recuperando, desarmados. Mas tenho planos diferentes... $b$bVamos esperar. Atacaremos Thassarian e suas tropas no devido tempo. Enquanto isso, fale com Flovélia Espanta e pegue um voo para o Baluarte, na fronteira ocidental das Terras Pestilentas. O alto-executor Arcabuz lhe dará sua próxima missão.$b$bMandarei avisar quando eu precisar novamente de você em Andorhal.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Alto-executor Arcabuz no Baluarte, que fica nas Clareiras de Tirisfal.', 0),
(26927, 'ptBR', 'E, de repente... Murlocs!', 'Fale com Canária Cascatira.', 'Então os troggs estão trabalhando para os kobolds, e os kobolds estão trabalhando para os gnolls. E estes devem ter vindo do Pantanal para cá.$B$BComo eu sei disso? Bem, porque os gnolls trouxeram amiguinhos: o que sobrou do Loch está infestado de murlocs Guelrazul, e antes não havia nenhum.$B$BPraga é praga, mas esta ação conjunta é preocupante. Preciso que você fale com a Canária Cascatira. Ela é uma das melhores caçadoras destas bandas e vai saber como lidar com os murlocs – se você conseguir tirar a caneca da mão dela.', '', '', '', '', '', '', '', '', '', '', 0),
(26928, 'ptBR', 'Sinto cheiro de um plano no ar', 'Pegue 7 Glândulas Odoríferas de Murloc de qualquer Murloc Guelrazul no Loch.', 'Murlocs e gnolls trabalhando juntos? Que piada! Mas tem uma coisa: tentar matar esses pestinhas não vai levar você a lugar algum. Eles são muitos.$B$BMas calma que eu tenho um plano! Tutano, $Gmeu:minha; camarada, tutano! Os murlocs têm um cheiro, e eles espalham esse cheiro nas coisas, e quando outros murlocs cheiram isso, fica todo mundo maluco! É uma ótima isca.$B$BBem, esse cheiro dos murlocs sai de uma glândula. Vai lá e me traz uma porção disso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Canária Cascatira na cidade de Thelsamar, em Loch Modan.', 0),
(26929, 'ptBR', 'Crocodilagem da boa', 'Pegue 6 Mandíbulas Intactas de Crocolisco.', 'Vem cá, enquanto você corre de um lado pro outro fazendo seja lá o que você faz, que tal me dar uma forcinha?$B$BVeja bem, eu costumava caçar crocoliscos mas, dadas as circunstâncias, agora prefiro ficar por aqui mesmo. Sem pena de mim, certo? Obrigada.$B$BEntão, já que você é $Gum cavalheiro:uma dama;, traz aqui pra mamãe umas mandíbulas de crocolisco que eu lhe dou um dinheiro razoavelmente limpo em troca.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Canária Cascatira na cidade de Thelsamar, em Loch Modan.', 0),
(26930, 'ptBR', 'Depois da cruzada', 'Observe o acampamento da Cruzada Escarlate a leste do Campo Pedravil, que fica nas Terras Pestilentas Ocidentais.', 'Nossas vitórias estão se acumulando, $n. A Cruzada Escarlate, que por tanto tempo perseguiu os Renegados, está no fim dos dias. Apesar deles ainda ocuparem um monastério em Tirisfal, já deixaram de ocupar Amparo e a Manopla de Tyr ao leste.$b$bNa semana passada fomos informados sobre atividades da Cruzada Escarlate em um pequeno acampamento a leste do Campo Pedravil, mas eu tenho razões para acreditar que eles também tenham sido eliminados. Viaje até lá e verifique essa informação para mim.', 'Acampamento da Cruzada Escarlate observado', '', '', '', '', 'Acampamento da Cruzada Escarlate observado', '', '', '', 'Fale novamente com o Alto-executor Arcabuz no Baluarte, que fica nas Clareiras de Tirisfal.', 0),
(26931, 'ptBR', 'Raposas e cães', 'Mate 4 Caçadores de Raposas da Aliança, 4 Bull-mastins e 4 Raposas-de-cauda-branca nas Terras Pestilentas Ocidentais.', 'Essas forças da Aliança andam pelas Terras Pestilentas como se fossem donas do lugar. E não são! Esta terra pertence, por direito, à Dama Sombria!$b$bCom a conclusão da batalha por Andorhal, as forças da Aliança se espalharam. Muitas estão a leste daqui, caçando raposas. Mostre que este território pertence aos Renegados.$b$bMate os caçadores. Mate os cães de caça deles. E mate as raposas que eles estavam caçando também, só pra deixar bem claro quem manda por aqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sacerdotisa Sombria Vandis no Baluarte, que fica nas Clareiras de Tirisfal.', 0),
(26932, 'ptBR', 'Maldita urubuzada', 'Mate 8 Urubus Lacustres.', 'Quando o Dique Lapidado rompeu, o Loch perdeu quase toda a água. Um desastre ecológico terrível.$B$BE não pense que isso não afetou os anões! A pesca foi pelo ralo, e há centenas de carcaças de manguadontes apodrecendo ao sol. Os urubus já estão atrás de carniça, espalhando todo tipo de sujeira e doenças nos arredores da cidade.$B$BNão posso lhe pedir que dê uma faxina geral, mas você poderia ajudar com os urubus? Se você matar uns poucos já será de grande ajuda.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Montanhista Kadrell na cidade de Thelsamar, em Loch Modan.', 0),
(26933, 'ptBR', 'Espadas e não enxadas', 'Mate 9 Operários da Aliança no Campo Pedravil.', 'Os homens que cultivam o Campo Pedravil não são mais fazendeiros. Eles são soldados.$b$bAs tropas de Thassarian precisavam de comida. Por isso, ele enviou parte das tropas da Aliança para o norte de Andorhal, para cultivar o Campo Pedravil. A batalha por Andorhal pode ter terminado, mas outra batalha se aproxima. Renegados contra humanos. Se matarmos os soldados que estão trabalhando no Campo Pedravil, daremos uma vantagem decisiva às tropas da Dama Sombria.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Sacerdotisa Sombria Vandis no Baluarte, que fica nas Clareiras de Tirisfal.', 0),
(26934, 'ptBR', 'Doença latente', 'Mate Ursos Pretos Doentes nas Terras Pestilentas Ocidentais e colete 20 Emaranhados de Peste que crescem junto aos corpos.', 'Eu preciso de grama pestilenta para um... um tipo de experimento. Aqueles membros da Cruzada Argêntea e aqueles druidas infernais do Círculo Cenariano fizeram um trabalho muito bom em curar as terras pestilentas. No entanto, agora, não consigo encontrar os reagentes de que preciso aqui por perto.$b$bMas parte da vida selvagem ainda se mantém empesteada. Mate um urso preto doente. Depois, pegue a grama que crescer onde o corpo pútrido do animal cair. Não é o ideal mas vai servir.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Boticário Trépido no Baluarte, que fica nas Clareiras de Tirisfal.', 0),
(26935, 'ptBR', 'Serraria de Beiranorte', 'Fale com Nataniel Dumah na Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.', 'Nós não somos os únicos membros da Cruzada Argêntea aqui nas Terras Pestilentas. Nosso quartel general, Amparo, fica mais ao norte. Também nesta direção, porém mais próxima, há uma serraria que está sob nosso controle.$b$bNataniel Dumah é o nosso principal contato nesta serraria. Eu te aconselho a procurá-lo se por acaso te encontres por esta parte da floresta.', '', '', '', '', '', '', '', '', '', 'Fale com Nataniel Dumah na Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.', 0),
(26936, 'ptBR', 'Apertarei o gatilho', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(26937, 'ptBR', 'Quando a morte não basta', 'Mate 8 Operários da Aliança no Campo Pedravil para que a sua Val\'kyr Enfeitiçada possa transformá-los em Renegados.', 'Arcabuz e os homens dele não sabem, mas fui eu que ordenei o empesteamento do Campo Pedravil. Nós precisamos daquela área para treinamento. Se quisermos vencer a guerra por Andorhal, temos que usar a nossa mais nova e versátil arma:$b$bVal\'kyren.$b$bLeve a minha val\'kyr enfeitiçada com você, $n, e mate os imprestáveis da Aliança que permanecem em Pedravil. Quando eles estiverem mortos, ela os trará de volta para esse mundo... como um de nós.$b$bOs Renegados não acabarão!', '', 'Operários da Aliança mortos e convertidos', '', '', '', '', '', '', '', 'Fale novamente com Lívida Corvossol no Posto Calcinado, que fica nas Terras Pestilentas Ocidentais.', 0),
(26938, 'ptBR', 'Treino de combate', 'Use a habilidade Chamado às Armas da sua Val\'kyr Enfeitiçada para mobilizar 5 Soldados Renegados no Campo Pedravil. Depois, mate a abominação Tripaberta dentro do estábulo Pedravil.', 'Como o único propósito de uma val\'kyr é servir, essa servirá a você. Eu estou dando a você total controle sobre ela, $n.$b$bRondando a fazenda você encontrará vários dos Renegados que você acabou de criar. Eu quero que você use a sua val\'kyr para juntar pelo menos cinco deles. Feito isso, leve seus novos soldados para dentro do estábulo de Pedravil e mate a fera que lá está. Hoje, eles aprenderão a lutar pela Dama Sombria.', '', 'Soldado Renegado mobilizado', '', '', '', '', '', '', '', 'Fale novamente com Lívida Corvossol no Posto Calcinado, que fica nas Terras Pestilentas Ocidentais.', 0),
(26939, 'ptBR', 'Esquadrão Classe G', 'Mate a Precipitação Radioativa Viscosa.', 'Como você chegou até aqui?$B$BAh, não tem importância! O que importa é que somos o top do top, os melhores do mercado, e estamos aqui para retomar Gnomeregan!$B$BQuando a situação ficou crítica e ninguém mais sabia o que fazer, fomos contratados pelo Grão-faz-tudo.$B$BMas, infelizmente, nem nós poderemos fazer isso sozinhos. A partir de agora, você é soldado honorário do Esquadrão Classe G, $n.$B$BUse este paraquedas para saltar direto no Salão das Engrenagens e mate a Precipitação Radioativa Viscosa. Depois, apresente-se ao Comando B.E Barechus. Vocês vão se dar muito bem.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Comando B.E Barechus.', 0),
(26940, 'ptBR', 'Nova Congelante', 'Alcance o nível 3 para aprender Nova Congelante. Encontre um Boneco de Treinamento por perto e pratique-a duas vezes.', 'Somos herdeiros de um legado de magia arcana, e seu caminho não será fácil. Muitos ainda nos responsabilizam pelas ações de nossos predecessores, mas nossos talentos são necessários.$B$BEmbora seja preciso ter cuidado, é importante que você desenvolva seus poderes, já que isso vai aprofundar sua ligação com o arcano e lhe conceder novos feitiços.\n\nVá ganhar mais experiência com seus feitiços e demonstre para mim o que aprendeu.', '', 'Praticar usar Nova Congelante', '', '', '', '', '', '', '', 'Fale novamente com Rhyanda em Aldrassil.', 0),
(26941, 'ptBR', 'Esquadrão Classe G', 'Mate o Eletrocutor 6000.', 'Aquele Murd Doc é doido, $c. Nunca, mas nunca mesmo, entre numa aeronave com aquele gnomo maluco.$B$BNão sou muito fã de me esconder, e creio que você também não é. Siga por este corredor até chegar na Área de Lançamento e, chegando lá, acabe com o Eletrocutor 6000.$B$BÉ ele que cuida da aeronave...$B$B...e eu odeio aeronaves. Não vou subir em aeronave nenhuma!$B$BUse este paraquedas para pular fora depois que terminar o serviço e fale com o Comando Rosto para receber a próxima missão.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Comando Rosto.', 0),
(26942, 'ptBR', 'Esquadrão Classe G', 'Mate o Mecangenheiro Termaplugue.', 'Se eu fosse você, ficava longe do B.E Barechus e do Murd Doc, nenhum deles é bom da cachola.$B$BMas você é, $Gmeu caro:minha cara;! Assim, que tal trabalharmos. Siga por este túnel até a Corte dos Faz-tudo. Com sorte, você saberá o que fazer quando der de cara com o Mecangenheiro Termaplugue.$B$BNosso chefe, o Comando Hann Ibal, $Go:a; aguarda em algum lugar lá dentro. Provavelmente, ele vai recompensá-$Glo:la; muito bem por todo o trabalho.$B$BProvavelmente.', '', '', '', '', '', '', 'Mecangenheiro Termaplugue', '', '', 'Apresente-se ao Comando Hann Ibal.', 0),
(26943, 'ptBR', 'Lar doce lar', 'Fale com Murd Doc.', 'Lá em Altaforja eu tinha uma casa incrível! Quer dizer, até que tive que sair para dar lugar para os gnomos.$B$BMesmo com aquela parafernália toda, duzentas e doze máquinas e tranqueiras, os nanicos não conseguiram dar conta de um bando de troggs! E agora EU tenho que pagar pela incompetência alheia?!$B$BMas nem! Chegou a hora de acabar isso.$B$BVá para Gnomeregan e fale com o Comando Murd Doc. Sim, ele é um gnomo, mas o grupo dele, um tal de V.E.R.A., está se preparando para retomar Gnomeregan.$B$BVá! Eu quero minha casa de volta!', '', '', '', '', '', '', '', '', '', '', 0),
(26944, 'ptBR', 'Explorando Gnomeregan', 'Fale com Murd Doc.', 'Já faz tempo que os gnomos perderam o controle da capital, Gnomeregan. Sei muito bem como é perder a própria casa.$B$BEntre em Gnomeregan e fale com o Comando Murd Doc, um dos membros da V.E.R.A. Se há algo que você pode fazer para ajudar, faça! Existem muitos segredos obscuros dentro daquele lugar.', '', '', '', '', '', '', '', '', '', '', 0),
(26945, 'ptBR', 'O aprendizado de novas técnicas', 'Chegue ao nível 3 para aprender Eviscerar. Encontre um Boneco de Treinamento e pratique Investida.', 'À medida que você supera os desafios, você aprenderá novas técnicas.$B$BVá, obtenha mais experiência e aprenda uma nova habilidade. Então demonstre-a para mim em um dos bonecos de treinamento.', '', 'Praticar Investida', '', '', '', '', '', '', '', 'Fale novamente com Alyissia, em Teldrassil.', 0),
(26946, 'ptBR', 'As vantagens de um ladino', 'Alcance o nível 3 e aprenda a técnica de Eviscerar. Procure um Boneco de Treinamento ao sudeste de Aldrassil e execute a técnica de Eviscerar 3 vezes.', 'Estou certo de que, a esta altura, você já aplica o Golpe Sinistro em seus inimigos com perícia. Mas à medida que você aprende mais e progride como ladino, você começará a aprender novas técnicas. Uma que você logo aprenderá se chama Eviscerar e pode ser um meio eficiente de finalizar uma combinação de ataques.$B$BQuero que você obtenha mais experiência, aprenda-a e vá treiná-la em um boneco de treinamento perto da extremidade sudeste de Aldrassil.', '', 'Praticar Eviscerar', '', '', '', '', '', '', '', 'Fale novamente com Frahun Umbrurmúrio em Teldrassil.', 0),
(26947, 'ptBR', 'Treinamento de mateiro', 'Alcance o nível 3 para aprender Tiro Firme. Procure um Boneco de Treinamento a sudeste de Aldrassil e execute Tiro Firme 5 vezes.', 'A maioria das pessoas lembra de druidas e sentinelas quando pensam nos kaldorei, mas a arte da caça é igualmente antiga e respeitável entre nós.$B$BVenho observando você e notei sua experiência no manejo do arco. Ao adquirir mais experiência, você começará a aprender novas técnicas.$B$BEu quero que você saia, obtenha mais experiência e descubra uma nova habilidade. Depois, use a habilidade em um boneco de treinamento perto da fronteira sudeste de Aldrassil.', '', 'Praticar Tiro Firme', '', '', '', '', '', '', '', 'Fale novamente com Ayanna Perenanda em Aldrassil.', 0),
(26948, 'ptBR', 'Fogo Lunar', 'Alcance o nível 3 para aprender Fogo Lunar. Use esse feitiço em um boneco de treinamento em Aldrassil.', 'Os druidas têm um papel importante em nossa sociedade, mas muitas vezes parece que são sonhadores apáticos em um mundo que se modifica.$B$BMas a verdade é que precisamos treinar muito e sair para o mundo a fim de desenvolver nossa ligação com a natureza.\n\nEntão vá ganhar mais experiência. Você vai começar a sentir sua ligação se aprofundar e vai aprender novas habilidades. Demonstre para mim a primeira que você aprendeu.', '', 'Praticar Fogo Lunar', '', '', '', '', '', '', '', 'Fale novamente com Mardant Carvalhaço em Aldrassil.', 0),
(26949, 'ptBR', 'Aprenda a Palavra', 'Alcance o nível 3 para aprender Palavra Sombria: Dor, depois treine lançando-a 5 vezes contra um dos bonecos de treinamento.', 'À medida que se aventura no mundo e desenvolve suas habilidades, você começará a aprender habilidades que você não sabia existirem dentro de si.\n\nQuero que você saia por aí, ganhe experiência e depois me mostre a primeira habilidade que aprender.', '', 'Praticar Palavra Sombria: Dor', '', '', '', '', '', '', '', 'Fale novamente com Shanda em Aldrassil.', 0),
(26950, 'ptBR', 'O lado negro da força', 'Mate o Interrogador Vishas e o Mago Sangrento Thalnos.', 'A Cruzada Escarlate encanta guerreiros jovens e ingênuos com a promessa de erradicar os mortos-vivos. O que esses jovens guerreiros não enxergam é o lado negro dessa operação.$B$BO Interrogador Vishas é o mais cruel de todos os homens que já encontrei. Foi ele que "extraiu" informações de minha mãe durante o primeiro surto da peste. Já o impiedoso Mago Sangrento Thalnos supervisiona o cemitério.$B$BA raiva e o zelo sagrados dos cruzados os impede de enxergar a própria escuridão. Faça com que eles se arrependam da própria hipocrisia.', '', '', '', '', '', '', 'Interrogador Vishas', '', '', 'Fale novamente com a Patrulheira Sombria Velonara.', 0),
(26951, 'ptBR', 'Limpeza nas Ilhas do Eco', 'Recolha 8 Carrancas Desencantadas.', 'A batalha pela retomada das Ilhas do Eco custou caro para nós, mas valeu a pena, $c. O grande espírito Bwonsamdi ajudou nossos guerreiros a derrotar o impuro Zalazane e os protegeu com espíritos da ilha, mas alguns desses espíritos caíram em batalha. Precisamos de sua ajuda para fazer com que esses espíritos descansem. Vá às Ilhas do Eco e recolha as carrancas que encontrar espalhadas por lá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Gadrin na Aldeia Sen\'jin.', 0),
(26952, 'ptBR', 'O Acampamento dos Restauradores', 'Apresente-se ao Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 'Eu não estou gostando disso que os Renegados estão fazendo aqui no Baluarte. Bombas, caldeirões, derramamento de sangue desnecessário... Nenhuma dessas coisas incorpora o espírito da Cruzada Argêntea. Além disso, eu não gosto do fato deles contratarem mercenários como você.$b$bNão é nada pessoal, $c. É que, na verdade, você poderia estar fazendo muito mais sozinh$go:a;. Se estiver interessad$go:a; em ajudar a curar as terras pestilentas ao invés de re-empesteá-las, fale com o Agente de Campo Kaartish no Acampamento dos Restauradores, a leste daqui.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(26953, 'ptBR', 'Zen\'Kiki, o druida', 'Mate 20 animais infectados com Zen\'Kiki ao seu lado. Você pode matar Ursovis Canhestros, Lobos Doentes, Rasterruças Tocaieiras ou Tocaieiras Pestilentas.$b$bRetorne para o Acampamento dos Restauradores caso você se separe de Zen\'Kiki.', 'Eu sou Adrina Couro Claro, uma druida do Círculo Cenariano. Nós somos os responsáveis por curar essa terra onde antes só havia morte.$b$bNós aceitamos todos aqueles que seguem o caminho dos druidas, independente da raça, facção ou talento. Isso quer dizer que, às vezes, recrutamos alguns druidas que precisam de mais ajuda do que outros.$b$bEu gostaria que você conhecesse o Zen\'Kiki. Ele é novo por aqui e ainda está aprendendo a arte. Você poderia levá-lo para dar uma volta? Vocês podem treinar combate com os animais pestilentos que rondam essa área.', '', 'Animais selvagens mortos com Zen\'Kiki', '', '', '', '', '', '', '', 'Fale novamente com Adrina Couro Claro no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(26954, 'ptBR', 'Uma metodologia diferente', 'Leve Zen\'Kiki para o topo da colina a leste do Acampamento dos Restauradores. Depois, use-o para evocar e matar 7 Falcões Doentes.', 'Entre outras coisas, Zen\'Kiki tem que praticar a precisão dos feitiços. Eu vi os feitiços dele saindo descontrolados daqui! Na verdade, eu até os usei para ver o caminho de vocês na floresta.$b$bTalvez nós possamos usar o Zen\'Kiki de uma outra forma. Leve-o para o alto da colina a leste daqui. Os falcões doentes que circulam por lá precisam ser destruídos. Peça ao Zen\'Kiki para atirar neles. Mesmo que ele não consiga acertá-los, ele irá distraí-los para que você acabe com eles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Adrina Couro Claro no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(26955, 'ptBR', 'Zen\'Kiki e os Sectários', 'Leve o Zen\'Kiki para o Posto de Malícia nas Terras Pestilentas Ocidentais. Depois, solte 4 Ursovis Cativos e permita que Zen\'Kiki os cure.', 'Enquanto você esteve fora, eu estive pensando em outras maneiras de direcionar o nosso amigo Zen\'Kiki. Eu acho que ele pode ter futuro como curador. Eu digo isso porque os feitiços de cura dele nunca erram o alvo.$b$bEu ouvi o agente de campo Kaartish dizer que o acampamento de sectários a leste é o lugar de onde os animais infectados estão vindo. Eu espero que você não se importe de escoltar o Zen\'Kiki até lá... Talvez ele possa ajudar a curar alguns dos animais infectados no acampamento.', '', 'Ursovil Cativo libertado e curado', '', '', '', '', '', '', '', 'Fale novamente com Adrina Couro Claro no Acampamento dos Restauradores nas Terras Pestilentas Ocidentais.', 0),
(26956, 'ptBR', 'Colheita infeliz', 'Remova 6 Milhos Estragados, 4 Maçãs Podres e 3 Abóboras com Aparência Insalubre da Fazenda dos Dalson, que fica nas Terras Pestilentas Ocidentais.', '$R! Fico feliz em ver que alguém veio me ajudar.$b$bNós, druidas cenarianos, conseguimos recultivar a Fazenda dos Dalson, que fica bem aqui atrás de mim. A terra floresceu e nossas plantações têm sido um sucesso... em sua maioria.$b$bAlgumas plantas parecem continuar infectadas pela praga que varreu essas terras. Talvez as raízes estivessem enterradas muito fundo, talvez as sementes fossem mais frágeis... eu não saberia dizer. Mas com certeza $gum:uma; $c habilidos$go:a; como você pode me ajudar a arrancar as plantas infectadas de perto das boas.', '', 'Milho Estragado removido', 'Maçã Podre removida', 'Abóbora com Aparência Insalubre removida', '', '', '', '', '', 'Fale novamente com Selyria Groenveld no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(26957, 'ptBR', 'A longa jornada para casa', 'Reencontre-se com Del Garrão no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 'Eu estive em muitos lugares na minha vida, $Gmeu bom:minha boa; $c. Eu lutei na batalha por Ahn\'Qiraj, atravessei o Portal Negro para Terralém e me juntei à Cruzada Argêntea para derrotar o Flagelo no frio de Nortúndria.$b$bMas antes disso tudo, eu fui um fazendeiro aqui em Lordaeron. Agora aqui estou eu, em Amparo, a umas poucas milhas da minha casa. Já é hora de prestar meus respeitos.$b$bEu estou indo para o Acampamento dos Restauradores antes de voltar pra casa. Eu não ficaria chateado se encontrasse você por lá quando eu chegar.', '', '', '', '', '', '', '', '', '', 'Reencontre-se com Del Garrão no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(26958, 'ptBR', 'A primeira lição', 'Chegue ao nível 3 para aprender Investida. Encontre um Boneco de Treinamento na área noroeste do Ponto de Impacto e execute a técnica Investida.', 'Comecemos teu treino imediatamente. Conforme ganhes mais experiência em combate, começarás a desenvolver novas técnicas.$B$BVai, fica mais experiente, aprende algo novo e o demonstra nos bonecos de treinamento ao noroeste.', '', 'Praticar Investida', '', '', '', '', '', '', '', 'Fale novamente com Kore no Ponto de Impacto.', 0),
(26959, 'ptBR', 'Arruinando as defesas escarlates', 'Mate o Mestre de Matilha Lobato e o Arcanista Doan.', 'Precisamos eliminar as defesas do Monastério Escarlate antes que possamos começar a verdadeira invasão. Vá para a biblioteca do Monastério e elimine o Mestre de Matilha Lobato e o Arcanista Doan. São eles que mantêm as fortes defesas do Monastério de pé e protegem seus companheiros.$B$BMinha magia garantirá que suas ações não sejam detectadas pelo resto do monastério. Quando eles forem eliminados, posso evocar mais reforços para ajudar nosso ataque.$B$BSucesso é a nossa única opção, $n, pois a Dama Sombria não tolerará falhas.', '', '', '', '', '', '', 'Arcanista Doan', '', '', 'Fale novamente com a Patrulheira Sombria Velonara.', 0),
(26960, 'ptBR', 'Meu filho, o Príncipe', 'Apresente-se ao Príncipe Anduin na Bastilha Ventobravo. Em seguida, fale com o Rei Wrynn.', 'Meu filho, ainda tão jovem, já carrega um grande fardo. E temo que suas responsabilidades cresçam ainda mais.$B$BEle nunca aprenderá a ser um líder se ficar confinado à bastilha, mas eu fico um pouco relutante em deixá-lo sair sem escolta.$B$B$n, seus feitos na resposta ao cataclismo já são lendários. Você seria $gum excelente mentor:uma excelente mentora; para o jovem príncipe Anduin.$B$BPor favor, apresente-se a ele. Há alguns assuntos urgentes na cidade, e vocês dois podem cuidar disso por mim.', '', 'Apresentação a Anduin', '', '', '', '', '', '', '', 'Fale com o Rei Wrynn na Bastilha Ventobravo.', 0),
(26961, 'ptBR', 'Ídolos', 'Leve 8 Ídolos Esculpidos em Pedra para Magmar Machadeiro no Sítio de Escavação de Bandaferro.', 'Há pouco tempo, antes dos troggs aparecerem no sítio, nós desenterramos estranhos ídolos esculpidos. Mas não tivemos nem chance de estudá-los, porque logo depois da descoberta os troggs nos expulsaram das ruínas! E esses artefatos provocam estranhos efeitos nos troggs. Eles ficam enlouquecidos!$B$BTraga oito ídolos para mim. Quero estudá-los e mantê-los longe dos troggs! Os ídolos estão com os troggs que infestam o sítio.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Magmar Machadeiro no Sítio de Escavação de Bandaferro.', 0),
(26962, 'ptBR', 'Arruinando a ofensiva escarlate', 'Mate Herodes.', 'Como você pode ver, $n, nosso primeiro ataque contra a Armaria não saiu como planejado. Tomamos o pátio do local até que Herodes, o Campeão Escarlate, apareceu.$B$BDevemos continuar o ataque! Não podemos permitir que a Cruzada Escarlate treine nenhum outro soldado aqui, e muito menos lance um ataque contra a Cidade Baixa.$B$BA sua missão é simples: eliminar o Campeão Escarlate.', '', '', '', '', '', '', 'Herodes', '', '', 'Fale novamente com a Patrulheira Sombria Velonara.', 0),
(26963, 'ptBR', 'Firmeza no disparo', 'Chegue ao nível 3 para aprender Tiro Firme. Encontre um Boneco de Treinamento a noroeste do Ponto de Impacto e execute 5 vezes o Tiro Firme.', 'Vamos dar início ao teu treino. Teremos de lutar para sobreviver neste ambiente e tu tens um papel importante na segurança e estabilidade do nosso povo.$B$BConforme te tornares mais experiente, começarás a descobrir novas habilidades. Vai, aprende algo novo e experimenta. Volta quando julgares ter dominado a técnica.', '', 'Praticar Tiro Firme', '', '', '', '', '', '', '', 'Fale novamente com Keilnei no Ponto de Impacto.', 0),
(26964, 'ptBR', 'Ordens do Chefe Guerreiro: Floresta de Pinhaprata!', 'Apresente-se ao Grão-executor Mortuus no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 'Todos os membros da Horda em bom estado físico são por esta intimados a se apresentar ao Grão-executor Mortuus no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.$B$BAgora, mais do que nunca, sua ajuda é necessária para debelar a infestação dos inimigos na região e para conquistar o porto de Guilnéas!$B$BPara chegar ao Alto Comando dos Renegados, você deverá seguir para o sul pelas Clareiras de Tirisfal e, então, entrar na Floresta de Pinhaprata. De lá, tome a estrada para o sul até chegar ao Alto Comando dos Renegados.$B$BAvante, irmãos e irmãs! O destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(26965, 'ptBR', 'Chega o Chefe Guerreiro', 'Compareça à chegada do Chefe Guerreiro Garrosh Grito Infernal.', 'Chegou na hora certa, $nnub. É $nnub, né?$B$B<O grão-executor Mortuus examina uma folha de papel.>$B$BSim, é o que diz aqui: "$nnub."$B$B<O grão-executor Mortuus aponta o seu nome na folha.>$B$BOnde é que eu estava? Ah, sim, chegou na hora certa, $nnub! O Chefe Guerreiro deve estar chegando a qualquer momento para se reunir com nossa líder e salvadora, a Dama Sombria. Apenas fique de prontidão e mantenha a compostura. Acho que quando essa demonstração terminar, todos nós vamos receber comendas!', '', 'Compareça à chegada do Chefe Guerreiro Garrosh Grito Infernal.', '', '', '', '', '', '', '', 'Fale com o Grão-executor Mortuus no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(26966, 'ptBR', 'O poder da Luz', 'Chegue ao nível 3 para aprender Selo de Comando. Aplique o Selo de Comando, encontre um Boneco de Treinamento a noroeste do Ponto de Impacto e acerte-o com um ataque.', 'Como paladin$go:a;, a Luz que nos toca a todos não te é estranha. Mas tu tens o poder único de invocar a Luz pata ajudar-te em batalha.$B$BConforme ganhares mais experiência, te aproximarás ainda mais da Luz e serás capaz de invocar novos poderes em batalha.\n\nVai, cresce em experiência até teres aprendido um novo poder. Então, demonstra-o para mim.', '', 'Usar Selo de Comando e acertar o Boneco de Treinamento', '', '', '', '', '', '', '', 'Fale novamente com Aurelon no Ponto de Impacto.', 0),
(26967, 'ptBR', 'Batalha pelo Monastério Escarlate', 'Mate o Comandante Escarlate Mograine e a Alta-inquisidora Cristalba.', 'Contemple o poder dos Renegados! A vontade implacável da Dama Sombria corre em nossas veias! $B$BA grande maioria das tropas restantes dos cruzados fugiu. Alguns, entretanto, ainda nos desafiam.$B$BVocê vem sendo muito útil para o sucesso dessa operação, e Sylvana lhe deu a honra de eliminar nossos últimos inimigos, $n.$B$BNão tenha piedade!', '', '', '', '', '', '', 'Alta-inquisidora Cristalba', '', '', 'Fale novamente com a Patrulheira Sombria Velonara.', 0),
(26968, 'ptBR', 'Nova Congelante', 'Chegue ao nível 3 para aprender Nova Congelante. Encontre um Boneco de Treinamento na área noroeste do Ponto de Impacto e pratique nele 2 vezes.', 'Em teu futuro como $gmago:maga;, tu certamente necessitarás de um bom número de feitiços. Para tanto, tu precisas tornar-te mais poderos$go:a;. Assim, tua conexão com o arcano ficará mais profunda.\n\nVai, obtém mais experiência e demonstra a mim o que tu aprendeste.', '', 'Praticar Nova Congelante', '', '', '', '', '', '', '', 'Fale novamente com Valaatu no Ponto de Impacto.', 0),
(26969, 'ptBR', 'Golpe primevo', 'Aprenda o Golpe Primevo chegando ao nível 3. Depois, encontre um Boneco de Treinamento na área noroeste do Ponto de Impacto e pratique utilizando 3 vezes o Golpe Primevo.', 'Andar lado a lado com os poderes elementais te levará a muitos lugares. Conforme cresceres em poder, começarás a aprender novas habilidades.\n\nComecemos tua jornada com uma lição simples, porém bastante útil.\n\nAprende o segredo do Golpe Primevo e pratica-o nos bonecos de treinamento a noroeste do Ponto de Impacto. Volta quando tiveres concluído a tarefa.', '', 'Praticar Golpe Primevo', '', '', '', '', '', '', '', 'Fale novamente com Firmanvaar no Ponto de Impacto.', 0),
(26970, 'ptBR', 'Aprenda a Palavra', 'Alcance o nível 3 para aprender Palavra Sombria: Dor, depois lance o feitiço 5 vezes nos bonecos de treinamento perto do ponto de impacto.', 'Como sacerdote, um dos teus deveres mais importantes é usar o poder da Luz para ajudar os feridos.\n\nOutro dever é usar teu poder ofensivamente, para protegê-los.\n\nAo obteres mais experiência, tu começarás a descobrir novas habilidades para usar em teus protegidos. Vai, obtém mais experiência e demonstra para mim as habilidades que aprendeste.', '', 'Praticar Palavra Sombria: Dor', '', '', '', '', '', '', '', 'Fale novamente com Zalduun no Ponto de Impacto.', 0),
(26971, 'ptBR', 'O fechamento', 'Mate a Alta-sacerdotisa Lorthuna.', 'Um barulho na câmara principal do templo chama a sua atenção. Você escuta uma risada familiar: Lorthuna. Ela voltou para interromper o ritual. Você precisa detê-la!', '', '', '', '', '', '', 'Alta-sacerdotisa Lorthuna', '', '', 'Fale com o Arauto da Terra Torunscar no Templo da Terra.', 0),
(26972, 'ptBR', 'O lado negro da força', 'Mate o Interrogador Vishas e o Mago Sangrento Thalnos.', 'Entrei para a Cruzada Escarlate como um jovem paladino, sedento para eliminar o mal existente no mundo. Mas pouco sabia eu a respeito da obscura verdade sobre esses fanáticos.$B$BO Interrogador Vishas e o Mago Sangrento Thalnos supervisionam o cemitério. Os dois adoram torturar os novos recrutas para garantir que eles permaneçam "puros". Isso é uma afronta contra a Luz, $c!$B$BNão desejo mais fazer parte dessa organização corrupta! Você terá que matá-los para que, assim, ninguém mais tenha que passar pelo que eu passei.', '', '', '', '', '', '', '', '', '', 'Fale novamente com José, o Enlouquecido.', 0),
(26973, 'ptBR', 'O único caminho da verdade', 'Mate o Mestre de Matilha Lobato e o Arcanista Doan.', 'Creio que a raiz de toda a corrupção da cruzada pode ser encontrada aqui. O Arcanista Doan supervisiona a biblioteca e treina muitos recrutas nas artes da magia arcana.$B$BA Luz é o único caminho! Você deve matá-lo, $c, e redimir essa gloriosa organização!$B$B<José, o Desperto, treme nervosamente.>$B$BQuero também que você acabe com o Lobato. Ele e seus cães parecem não concordar com nossas nobres intenções.', '', '', '', '', '', '', 'Arcanista Doan', '', '', 'Fale novamente com José, o Enlouquecido.', 0),
(26974, 'ptBR', 'O falso campeão', 'Mate Herodes.', 'Nós... nós... nós tivemos que matá-los! Foi legítima defesa!$B$BVocê acredita em mim, não acredita, $n?$B$BHerodes não é o verdadeiro campeão da Cruzada Escarlate, eu sou! Ele tomou o que por direito era meu!$B$BVocê deve matá-lo! Ele é... uma grande ameaça. Ele treina e instrui os soldados a matarem não somente mortos-vivos, mas qualquer ser que os enfrentem!$B$BAjude-me, e lhe darei uma boa recompensa...', '', '', '', '', '', '', 'Herodes', '', '', 'Fale novamente com José, o Enlouquecido.', 0),
(26975, 'ptBR', 'Arregimentando a frota', 'Escolte o Príncipe Anduin para as Docas de Ventobravo e fale com o Sargento de Suprimentos Covas. Se você se separar do príncipe, poderá encontrá-lo na sala do trono de Ventobravo.', 'Estou recrutando uma frota de guerra para atacar o Planalto do Crepúsculo e dar fim aos lacaios de Asa da Morte. Meus soldados estão prontos, mas os preparativos da frota estão atrasados.$B$BMeus homens que estão nas docas precisam de inspiração e motivação. Uma visita do Príncipe deve estimulá-los e fazê-los lembrar que lutam por um futuro repleto de glórias.$B$BLeve o príncipe Anduin para as docas e fale com o sargento de suprimentos Covas. Quero que Anduin veja como um líder nato cuida da situação.', 'Príncipe Anduin escoltado até Covas.', '', '', '', '', 'Príncipe Anduin escoltado até Covas.', '', '', '', 'Fale com o Sargento de Suprimentos Covas no Porto de Ventobravo.', 0),
(26976, 'ptBR', 'Batalha pelo Monastério Escarlate', 'Mate o Comandante Escarlate Mograine e a Alta-inquisidora Cristalba.', 'Ah, é muito bom te ver de novo, $n! Creio que precisarei da sua ajuda mais uma vez.$B$BVeja bem, Mograine, o comandante aqui, junto à alta-inquisidora Cristalba, tentaram me convencer de que eu não era o novo Campeão Escarlate! Claro que eu e os garotos não ficamos nem um pouco satisfeitos com isso.$B$BComo retaliação, vamos tomar o Monastério por conta própria e restabelecer a ordem da maneira correta: comigo no poder! Assim, cuidarei dos Renegados e do Flagelo de uma vez por todas.$B$BEntão, você vai ajudar o seu velho amigo aqui?', '', '', '', '', '', '', 'Alta-inquisidora Cristalba', '', '', 'Fale novamente com José, o Insano.', 0),
(26977, 'ptBR', 'Investigação do Crepúsculo', 'Fale com o Major Samuelson na Bastilha Ventobravo.', 'A cidade ainda está se recuperando dos atos de revolta do Martelo do Crepúsculo nos últimos meses. Eles atacam os camponeses e corrompem nossos cidadãos mais importantes. Temos que descobrir até onde essa conspiração vai.$B$BEncarreguei o major Samuelson, da Guarda de Ventobravo, pela investigação. Ele está na sala do trono. Veja se você pode auxiliá-lo na tarefa.', '', '', '', '', '', '', '', '', '', 'Fale com o Major Samuelson na Bastilha Ventobravo.', 0),
(26978, 'ptBR', 'Quem precisa de caldeirões?', 'Coloque os Barris de Peste do Trépido perto do Moinho, dos Celeiros de Grãos, do Rancho e do Estábulo no Campo Pedravil.', 'Você viu como está o Campo Pedravil? As forças da Aliança em Andorhal dominaram a área e eles estão usando para.. para... para PLANTAR ALIMENTOS!$b$bEu quase gostava mais quando o Flagelo dominava aquela área. Pelo menos eles tiveram o bom gosto de colocar um caldeirão pestilento bem lá no meio do campo.$b$bNós vamos tomar a fazenda de volta daqueles humanos, $n. Pegue esses barris e coloque-os em posições estratégicas ao redor do campo. Eu vou ficar esperando aqui no Baluarte.', '', 'Deixe um Barril perto do Moinho', 'Deixe um Barril perto do Celeiro de Grãos', 'Deixe um Barril perto do Rancho', 'Deixe um Barril perto do Estábulo', '', '', '', '', 'Fale novamente com o Boticário Trépido no Baluarte, que fica nas Clareiras de Tirisfal.', 0),
(26979, 'ptBR', 'Novos rostos estranhos', 'Fale com Lívida Corvossol no Posto Calcinado, que fica nas Terras Pestilentas Ocidentais.', 'Agora que Pedravil é nosso, podemos usar a área - e todos os corpos que encontrarmos - para os nossos próprios propósitos. Recebi ordens dos altos escalões dizendo que você vai nos ajudar neste processo.$b$bVocê conheceu Lívida Corvossol no campo de batalha, em Andorhal. Eu nunca a encontrei pessoalmente, mas parece que ela fez algumas amizades importantes, porque ela está tomando a frente das operações aqui em Pedravil. Você pode encontrá-la no acampamento Escarlate calcinado... aquele que você observou mais cedo.', '', '', '', '', '', '', '', '', '', 'Fale com Lívida Corvossol no Posto Calcinado, que fica nas Terras Pestilentas Ocidentais.', 0),
(26980, 'ptBR', 'Estação Entrós', 'Fale com Shilah Cinzelaje na Estação Entrós, que fica ao norte do Porto de Menethil.', 'Você fez um bom trabalho aqui, $n. Pedir para você ficar carregando saco de areia seria um desperdício. Prefiro que vá para um lugar onde realmente precisem das suas habilidades.$B$BTemos um pequeno posto ao norte do pântano, construído por um gnomo chamado Entrós. Quero que você fale com Shilah Cinzelaje e a ajude com os problemas relacionados a Altaforja.$B$BEla é uma gracinha, mas eu não tentaria me engraçar pra cima dela! Aquele martelo que ela carrega não é só enfeite...', '', '', '', '', '', '', '', '', '', '', 0),
(26981, 'ptBR', 'Refúgio de Whelgar', 'Fale com o Prospector Whelgar no Refúgio de Whelgar, que fica a sudeste da Estação Entrós.', 'O prospector Whelgar está liderando uma escavação nas montanhas a sudeste daqui já faz algum tempo. Ele teve alguns problemas com raptores, mas a situação melhorou.$B$BUm dia desses, soubemos que ele teve que esvaziar a escavação de novo. Não sei direito o que está acontecendo, mas tenho quase certeza de que o Cataclismo não colaborou para a segurança da mina.$B$BOs anões que trabalham lá são boas pessoas, $n. Será que você poderia dar uma olhada no que está acontecendo e ajudar no que puder?', '', '', '', '', '', '', '', '', '', '', 0),
(26982, 'ptBR', 'O Monastério Escarlate', 'Fale com José, o Desperto.', 'O Monastério, nas Clareiras de Tirisfal, agora ocupado pelos Cruzados Escarlates, costumava ser um campo de treinamento para nossos paladinos. Agora, os Renegados vigiam o local a partir da Cidade Baixa, enquanto a Cruzada impede que utilizemos o local para treinar os soldados necessários para lidar com os mortos-vivos!$B$BVeja bem, embora eu não acredite em José, o Desperto, ele $Go:a; aguarda no cemitério. Vá até lá, pois embora ele seja um cruzado, diz agora que se rebelou contra a cruzada, o que nos dá a oportunidade de retomar o que é nosso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com José, o Desperto.', 0),
(26984, 'ptBR', 'Um velho e louco amigo', 'Fale com José, o Enlouquecido.', 'José, o Enlouquecido, foi um dos meus melhores amigos até ir para o Monastério Escarlate, nas Clareiras de Tirisfal, e se juntar à Cruzada Escarlate. Ouvi falar que ele agora se encontra na Armaria, numa tentativa ridícula de tomar a posição de Herodes como o Campeão Escarlate.$B$BDesafiar Herodes desse modo é procurar a própria morte! Vá até lá e tente convencer José a deixar essa ideia enlouquecida de lado!', '', '', '', '', '', '', '', '', '', 'Fale com José, o Enlouquecido.', 0),
(26985, 'ptBR', 'De louco todo mundo tem um pouco', 'Fale com José, o Insano.', 'Com nossas tropas renovadas, podemos lidar com a situação por aqui sem sua ajuda. No entanto, recebi relatórios de que José, o Insano, um antigo oficial da Cruzada Escarlate, encontra-se na Catedral no Monastério Escarlate e pretende liderar um bando de renegados em um ataque contra o Comandante Escarlate Mograine.$B$BEssa é uma excelente oportunidade. Vá até lá e ajude José nessa loucura, e quem sabe não podemos usar o Monastério como nossa nova fortaleza, bem na porta da fortaleza de Sylvana?', '', '', '', '', '', '', '', '', '', 'Fale novamente com José, o Enlouquecido.', 0),
(26986, 'ptBR', 'Adentrando no Monastério Escarlate', 'Apresente-se à Patrulheira Sombria Velonara.', 'Às vezes, a melhor maneira de garantir a segurança dos nossos homens é atacar o inimigo dentro da própria casa, cortando o mal pela raiz e impedindo mais batalhas!$B$BVá para o cemitério do Monastério Escarlate e fale com a Patrulheira Sombria Velonara. Ela está liderando um ataque dos Renegados e pode aproveitar a ajuda de $Gum:uma; $c experiente como você.', '', '', '', '', '', '', '', '', '', 'Fale novamente com José, o Enlouquecido.', 0),
(26987, 'ptBR', 'O caminho correto', 'Fale com a Patrulheira Sombria Velonara.', 'Meu povo não é muito fã das artes arcanas que tantas outras raças abusam. Felizmente, os teurgos na biblioteca do Monastério Escarlate estão bem longe daqui, mas me preocupa não só a habilidade que eles têm de transcender os reinos físicos, como principalmente o impacto que isso teria na sobrevivência do meu povo.$B$BViaje para oeste, até a biblioteca do monastério, e fale com a patrulheira sombria Velonara. Suas tropas já estão prontas para atacar o próprio arcanista Doan, o mago líder dos cruzados.', '', '', '', '', '', '', '', '', '', 'Fale novamente com José, o Desperto.', 0),
(26988, 'ptBR', 'Adiantando as coisas', 'Fale com a Patrulheira Sombria Velonara.', 'Tô esperando uns reagentes que encomendei da Cidade Baixa tem um tempinho. Ouvi falar que o carregamento tá atrasado porque os cruzados do Monastério Escarlate tão bloqueando o caminho. Quem tá cortando o meu barato só pode ser Herodes, o Campeão Escarlate.$B$BProcure a patrulheira sombria Velonara na armaria do Monastério Escarlate, ela vai "dar um jeitinho" no Herodes e, assim, meu carregamento vai chegar todo certinho!', '', '', '', '', '', '', '', '', '', 'Fale novamente com José, o Desperto.', 0),
(26989, 'ptBR', 'A Frente de Libertação de Guilnéas', 'Mate 10 Renegados Worgens.', 'A batalha por essa região continua, $nnub. Nós subjugamos as defesas guilneanas e tomamos Guilnéas para a Horda, mas um grupo pequeno de rebeldes conseguiu escapar. A "Frente de Libertação de Guilnéas", como eles se chamam, está realizando ataques oportunistas contra nossas forças em campo. Os rebeldes tiveram alguns pequenos sucessos e estão atacando com ousadia cada vez maior! Chegou a hora de atacar, $nnub.$B$BSiga para o sul, para Pinhaprata, e mate qualquer rebelde que encontrar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Grão-executor Mortuus no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(26990, 'ptBR', 'Bruxas, trolls e monstros marinhos', 'Mate Kai\'ju Gahz\'rilla e depois fale com Hamuul Runa Totem no Penhasco do Trovão.', 'Parece que os trolls Zangareia estão juntos com o Martelo do Crepúsculo.$B$BTanto faz. Aquela bruxa velha não vai mandar o bichinho dela para a MINHA cidade.$B$BVamos, bravos guerreiros! Vamos encharcar as areias com o sangue deles e voltar triunfantes de lá! Conte ao Hamuul Runa Totem o que ocorreu quando voltamos. Preciso cuidar da realocação dos cidadãos, dos consertos e de tudo mais.', '', '', '', '', '', '', '', '', '', 'Informe Hamuul Runa Totem, no Penhasco do Trovão, da morte de Kai\'ju Gahz\'rilla.', 0),
(26991, 'ptBR', 'Inimigos no exterior', 'Fale com a Patrulheira Sombria Velonara.', 'Às vezes, é preciso proteger nossos aliados para que eles possam nos proteger. Essa é uma dessas ocasiões, $r.$B$BVá para o Monastério Escarlate, nas Clareiras de Tirisfal, perto da Cidade Baixa. Chegando lá, dirija-se para a Catedral e fale com a Patrulheira Sombria Velonara. Ela está liderando o ataque final contra os cruzados, e será uma grande ajuda se os nossos aliados mortos-vivos tomarem o monastério antes que os cruzados tenham chance de atacar a Cidade Baixa', '', '', '', '', '', '', '', '', '', 'Fale novamente com José, o Enlouquecido.', 0),
(26992, 'ptBR', 'Fartura de miséria', 'Colete 8 Ruinervas Ferozes.', 'Sem dúvida você já está sabendo do que aconteceu no Portão da Ira em Nortúndria, não é? Por causa desses eventos infelizes, agora estamos proibidos de usar a cepa de praga destruidora de vida que havíamos finalmente aperfeiçoado. Agora, obedecemos a regras e regulamentos e outras inanidades!$B$BEles nos deram uma versão neutra da praga aperfeiçoada e querem que nós a transformemos em uma arma.$B$BMas vou precisar de uma sacola cheia de ruinerva feroz pra fazer isso funcionar. Você vai encontrar ruinerva feroz por toda Pinhaprata.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Boticário Murchaflores no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(26993, 'ptBR', 'Compêndio dos Caídos', 'Recupere o Compêndio dos Caídos.', 'Não se preocupe, não sirvo a mestre nenhum, $r. Dentro destes salões, encontra-se um livro chamado de Compêndio dos Caídos. O livro traz uma vasta variedade de pesquisas que a Cruzada Escarlate fez sobre minha raça ao longo dos anos.$B$BIndo direto ao ponto, gostaria que você fosse em busca do livro e o trouxesse para mim. Sem mais perguntas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dominique.', 0),
(26994, 'ptBR', 'Sem rimar nem pensar', 'Mate 3 Mirmidões Escarlates, 3 Protetores Escarlates, 3 Guardas Escarlates e 3 Evocadores Escarlates.', 'Ouvi falar que querem que você mate Herodes. Enquanto cumpre essa missão, o que acha de também eliminar os soldados de elite do Campeão Escarlate? Pagarei muito bem pelo trabalho.$B$BE não se preocupe sobre o porquê disso, mas sim no "como fazer isso".', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dominique.', 0),
(26995, 'ptBR', 'Entranhas e sangue', 'Colete 6 Tripas "Limpas" de Fera.', 'Vamos precisar de entranhas frescas de animal para finalizar esta nova praga. O problema é que tripas frescas são um item de luxo aqui na Floresta de Pinhaprata. A maior parte das feras daqui sucumbiram à doença e seus órgãos não prestam mais pra nada.$B$BFaça uma busca na mata a leste daqui e encontre worgs e ursos cinzentos. Mate apenas os animais sãos que encontrar e, em seguida, arranque suas tripas. Me traga todas as tripas limpas que couberem na sua mochila!', '', '', '', '', '', '', '', '', '', 'Fale com a Grã-boticária Shana T\'veen no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(26996, 'ptBR', 'Bem debaixo do nariz deles', 'Mate o Alto Inquisidor Fairbanks.', 'Dentro da maldita catedral, na sala contígua à direita, há uma tocha na parede. Se você mexer essa tocha, uma porta secreta se abrirá. Lá dentro, encontra-se o Alto Inquisidor Fairbanks, que agora é um morto-vivo!$B$BPreciso que ele seja eliminado, e dentro da sua própria sala se possível, pois é bom os cruzados não o verem. Você já conhece o negócio: mate-o e venha buscar sua recompensa. E nada mais de conversas entre nós, você já sabe o que tem que saber.', '', '', '', '', '', '', 'Alto Inquisidor Fairbanks', '', '', 'Fale novamente com Dominique.', 0),
(26997, 'ptBR', 'Os suspeitos', 'Interrogue 6 Trabalhadores das Docas de Ventobravo no Porto de Ventobravo.', '<Samuelson coça o queixo distraidamente.>$B$BMinhas investigações revelam que os trabalhadores das docas de Ventobravo estão metidos numa confusão iminente. Não confie neles.$B$BVocê deve ir até lá e fazer aquele lugar tremer. Comece interrogando os estivadores. Isso deve $gocupá-lo:ocupá-la;.$B$BAniquile os infiéis do Crepúsculo!', '', 'Trabalhadores das Docas interrogados', '', '', '', '', '', '', '', 'Fale com Anduin Wrynn sobre suas descobertas. Se ele não estiver com você, poderá encontrá-lo novamente na Bastilha Ventobravo.', 0),
(26998, 'ptBR', 'Se eu pudesse, matava mil', 'Mate 50 Murlocs Pinavil.', 'O preparado finalmente está no ponto, mas, antes que eu possa aprovar esse trabalho, vamos precisar testá-lo.$B$BFale com o Tratador de Morcegos Vermebafo, aqui no Alto Comando, e solicite um morcego. O morcego levará você até as Ilhas da Aurora, a leste daqui, depois do Espelho de Lordaeron, bem no centro da depravação: os covis dos murloc Pinavil!$B$BUse o preparado nos murlocs e volte com um relatório.$B$BQuero que venha escrito no relatório: "Não sobrou um!"', '', 'Morcego solicitado ao Tratador de Morcegos Vermebafo', 'Murloc Pinavil morto', '', '', '', '', '', '', 'Fale com a Grã-boticária Jana T\'veen no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(26999, 'ptBR', 'Uma nova era para as Terras Pestilentas', 'Consiga 4 Amostras de Tocaieira Pestilenta, 4 Amostras de Tocaieira Rasterruça, 4 Amostras de Ursovil Canhestro e 4 Amostras de Lobo Doente.', 'O Flagelo não mais domina esta área. Nós, os viventes, estamos retomando Lordaeron.$b$bNossos passos nesta direção são largos e céleres, como podes atestar. A terra está florescendo, as árvores estão vicejando e a vida silvestre começa a retornar. Entretanto, parcas reminescências de morte-viva ainda sobrevivem.$b$bAo passo que as árvores e a grama prosperam, os animais ainda enfrentam dificuldades. Algo está impedindo-os de se curarem propriamente, e preciso descobrir o que é. Traz-me algumas amostras de animais contaminados para que eu possa estudá-las mais de perto.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 19865);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Objectives`, `Details`, `EndText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `QuestGiverTextWindow`, `QuestGiverTargetName`, `QuestTurnTextWindow`, `QuestTurnTargetName`, `CompletedText`, `VerifiedBuild`) VALUES
(27000, 'ptBR', 'Tapa na aranha', 'Monte em um Mustangue de Amparo na Serraria de Beiranorte. Depois, use a habilidade Relinchar dele para espantar 25 Aranhas Beiranorte.', 'Ah, como é bom estar de volta aqui em Beiranorte! Eu tenho a minha serraria, minha linda esposa, um garotinho feliz... Eu até pendurei meu chapéu com a Cruzada Argêntea. Nós vamos suprir as forças do Tirion com nossa madeira.$b$bMeus lenhadores estavam sendo excepcionalmente produtivos também... até que as aranhas chegaram. Agora eles se recusam a entrar na floresta.$b$bTalvez você possa me ajudar. Monte em um dos meus cavalos e use-o para espantar as aranhas. Talvez nós possamos evitar o derramamento de sangue e espantá-las.', '', 'Aranhas Beiranorte assustadas', '', '', '', '', '', '', '', 'Fale novamente com Nataniel Dumah na Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.', 0),
(27001, 'ptBR', 'Tá na hora do PAU (Porrada nas Aranhas Urgente!)', 'Monte em um Mustangue de Amparo na Serraria de Beiranorte. Depois, use a habilidade Relinchar dele para direcionar 10 Aranhas Beiranorte para os Recrutas de Amparo que estão na Serraria Beiranorte. Você pode arrebanhar várias aranhas de cada vez.', 'O grão-lorde foi generoso e mandou alguns dos recrutas para nos proteger aqui na serraria. Com a sua habilidade de montaria e o poder marcial deles, nós resolveremos o problema das aranhas rapidamente.$b$bMonte novamente no mustangue e assuste as aranhas. Mas dessa vez, assuste-as na direção da serraria. Esses recrutas de Amparo vão cuidar delas daí em diante.', '', 'Aranha Beiranorte atraída para a Serraria', '', '', '', '', '', '', '', 'Fale novamente com Nataniel Dumah na Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.', 0),
(27002, 'ptBR', 'Uma audiência com o grão-lorde', 'Apresente-se ao Grão-lorde Tirion Fordring em Amparo, que fica nas Terras Pestilentas Ocidentais.', 'Ah, antes de você partir, $n... eu tenho uma mensagem para você. Tem alguém em Amparo que quer te conhecer. Ele disse que ouviu seu nome aparecer várias vezes nos últimos dias.$b$bConsidere-se $Gum:uma; $r de sorte, $n. Nem todo mundo consegue uma audiência particular com o grão-senhor Tirion Fordring.$b$bAh, e sinta-se à vontade para usar um dos meus mustangues para chegar até lá. Eles são os mais velozes que o dinheiro pode comprar.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Grão-lorde Tirion Fordring em Amparo, que fica nas Terras Pestilentas Ocidentais.', 0),
(27003, 'ptBR', 'Dinheiro fácil', 'Acompanhe a caravana de Adarrah para Uldum.', 'Ora, ora – olá!$b$bSeja qual for o motivo que traz você aqui, estou feliz por você ter vindo! Meus amigos jamais admitirão, mas bem que gostaríamos de uma ajuda.$b$bA antiga região de Uldum foi exposta. Tesouros que superam os seus sonhos mais loucos estão esperando serem levados, e de graça!$b$bPrecisamos apenas de uma pequena escolta, por causa daqueles bandidos e tudo mais...$b$bVocê nos acompanhará, não é?$b$bSinta-se à vontade para levar tudo o que você conseguir arrastar!', '', 'Caravana escoltada', '', '', '', '', '', '', '', 'Fale com Adarrah na Cidade Perdida dos Tol\'vir.', 0),
(27004, 'ptBR', 'Conspiração crepuscular', 'Pegue os Planos do Portão do Mestre.', 'Viemos aqui para investigar rumores da existência de um artefato titânico no Portão do Mestre, a sudoeste.$B$BOs planos do Martelo do Crepúsculo devem estar com um dos sectários. Você tem que trazer esses planos para nós, $n.$B$BProcure em todos os sectários até encontrar esses planos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Exploradora Mowi no Templo da Terra, que fica no Geodomo.', 0),
(27005, 'ptBR', 'Conspiração crepuscular', 'Pegue os Planos do Portão do Mestre.', 'Viemos aqui para investigar rumores da existência de um artefato titânico no Portão do Mestre, a sudoeste daqui.$B$BOs planos do Martelo do Crepúsculo devem estar com um dos sectários. Você tem que trazer esses planos para nós, $n.$B$BMate os sectários que estão no Portão do Mestre até encontrar esses planos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Avaliador Ruibarbo no Templo da Terra, que fica no Geodomo.', 0),
(27006, 'ptBR', 'Sobrevoo', 'Investigue a área central da parte de trás do Portão do Mestre.', 'Pues, eu tentei voar por cima da plataforma pra dar uma espiada, mas aquele bando de bagual não parou de mandar chumbo. Não cheguei nem perto, tchê.$B$BMas tu parece ser $Gíndio velho:índia velha; que dá conta dos cabrestos. Pues alça a perna na tua montaria e vai lá ver pra quê tanto bochincho!', '', 'Portão do Mestre investigado', '', '', '', '', '', '', '', 'Fale novamente com a Prospectora Cervejeira no Templo da Terra, que fica no Geodomo.', 0),
(27007, 'ptBR', 'Encontro no Pântano de Prata', 'Vá até o Alto Pântano de Prata, no Geodomo.', 'Bom trabalho, $n. Sabemos exatamente onde será a reunião.$B$BO Alto Pântano de Prata é um charco de mercúrio a leste daqui. Normalmente, apenas elementais e alguns troggs de pedra circulam por lá, mas nossos batedores relataram ter visto alguns membros do Crepúsculo.$B$BVá para lá. Vamos encontrar uma forma de espiar a reunião do Mestre Forjador.', 'Alto Pântano de Prata alcançado', '', '', '', '', 'Alto Pântano de Prata alcançado', 'Maruut Atapedras', 'Chegamos.', 'Maruut Atapedras', '', 0),
(27008, 'ptBR', 'Sobrevoo', 'Investigue a área central da parte de trás do Portão do Mestre.', 'Sou bastante habilidosa com meu tapete voador. Mas, infelizmente, os sectários quase me atingiram quando eu tentei investigar o que eles desenterraram no Portão do Mestre.$B$BVocê parece ser $Gum piloto habilidoso:uma piloto habilidosa;. Se importaria de voar até lá, em direção ao sudoeste, para ver o que eles descobriram?', '', 'Portão do Mestre investigado', '', '', '', '', '', '', '', 'Fale novamente com a Relicária Jessia Nigrossol no Templo da Terra, que fica no Geodomo.', 0),
(27009, 'ptBR', 'O Frigífero', 'Mate Amnennar, o Frigífero.', 'Amnennar, o Frigífero, domina o Urzal dos Mortos por meio de magia negra do Flagelo. Eu consegui abrir caminho por entre os espinhos até ficar bem em cima do trono dele, mas os feitiços me impedem de atacá-lo.$B$BSe você for até lá e distraí-lo, tenho certeza de que conseguirei enfraquecê-lo, impedindo que ele use suas magias mais poderosas. Depois disso, aniquile-o sem piedade.', '', '', '', '', '', '', 'Amnennar, o Frigífero', '', '', 'Fale novamente com Koristrasza', 0),
(27010, 'ptBR', 'Banho de mercúrio', 'Pegue um Caixote de Trogg e use-o para mergulhar no pântano e espiar a base do Martelo do Crepúsculo a leste.', 'Os troggs do Geodomo revelaram-se tão hostis quanto os de Azeroth. Mas talvez a presença deles possa nos ser útil.$B$BOs caixotes que eles usam na pesca de arrasto são um ótimo disfarce. Mergulhe no pântano e cubra-se com um deles.$B$BAproxime-se da base do Martelo do Crepúsculo, no limite leste do Alto Pântano de Prata, sem ser $Gpercebido:percebida;.', '', 'Pista do fragmento do Pilar do Mundo descoberta', '', '', '', '', '', '', '', '', 0),
(27011, 'ptBR', 'Ladroagem dos Pinhorrubro', 'Recupere 10 pilhas de Lenha de Beiranorte do acampamento Pinhorrubro, que fica nas Terras Pestilentas Ocidentais.', 'Mais para o sul, você vai encontrar os gnolls Pinhorrubro... que são novos aqui na área. Você provavelmente passou por alguns deles no caminho pra cá. O Nataniel finge que isso não é um problema, mas eu não sou boba.$b$bEu já os vi saindo correndo da serraria à noite. Eu não sei o que eles fazem com a madeira, eles não me parecem muito habilidosos... mas isso não os impede de roubar! Vá até o acampamento deles e pegue a nossa madeira de volta.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kelly Dumah na Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.', 0),
(27012, 'ptBR', 'A determinação dos gnolls', 'Colete 6 Báculos de Pinhorrubro e 6 Malhos de Pinhorrubro dos gnolls Pinhorrubro.', 'Eu suspeito das intenções desses gnolls. Eles ainda não nos atacaram, mas estão ficando mais numerosos e agora carregam armas para todos os lados. Eu não sou nenhuma especialista militar, mas isso me parece um pouco agressivo.$b$bSe nós conseguíssemos tomar suas armas, talvez eles ameaçassem menos a nossa serraria. Eu me sentiria muito melhor se você fosse até lá e me trouxesse algumas das armas deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kelly Dumah na Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.', 0),
(27013, 'ptBR', 'Perto demais para me sentir confortável', 'Mate 12 Raposas Raivosas perto da Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.', 'Eu estou feliz pelo Nataniel: ele passou muito tempo tentando voltar para Beiranorte e, agora que a Cruzada Escarlate acabou, ele pode finalmente voltar para casa. O problema é que... mesmo um lugar que parece tão idílico pode não ser o melhor lugar pra criar uma família.$b$bPor exemplo, na fronteira do vale existem muitas raposas raivosas procurando presas inocentes. De vez em quando eu percebo uma delas olhando diretamente para mim.$b$bPor favor, $c, cace algumas dessas raposas. Eu não consigo me sentir segura com elas por perto.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kelly Dumah na Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.', 0),
(27014, 'ptBR', 'Bilhete santificado', 'Fale com a Vidente Pena do Corvo na Aldeia Narache.', 'Não faz muito tempo, passou uma mensageira à sua procura, $n. Acredito que ela foi enviada pela instrutora de sacerdotes, a vidente Pena do Corvo. Se o bilhete foi mesmo enviado pela vidente, eu iria ter com ela imediatamente, se fosse você.', '', '', '', '', '', '', '', '', '', '', 0),
(27015, 'ptBR', 'Bilhete consagrado', 'Fale com o Andarilho do Sol Helakar, na Aldeia Narache.', 'Não faz muito tempo, passou uma mensageira à sua procura, $n. Creio que foi enviada pelo instrutor de paladinos, o andarilho do sol Helakar. Se o bilhete foi mesmo enviado pelo andarilho do sol, recomendo que vá vê-lo imediatamente.', '', '', '', '', '', '', '', '', '', '', 0),
(27016, 'ptBR', 'Nada como caçar javalis!', 'Mate 10 Javalis Lodacentos.', 'Contenha a animação, $n, pois você está diante do maior caçador de javalis de Azeroth!$B$BSão criaturas de intelecto aguçado, extremamente velozes e fortes, e de couro resistente. Só os mais habilidosos caçadores conseguem caçá-los. Amadores não entram nesse clube.$B$BPor quê? Porque aposto que você nunca caçou uma criatura tão exótica quanto essa. Aposto dinheiro que você não consegue bater meu recorde de dez javalis abatidos. Tente começar pelos que pastam pela margem leste do Loch... Mas não vá se machucar, viu, $Gfrangote:frangota;?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dário, o Novato, no Pavilhão dos Andarilhos em Loch Modan.', 0),
(27017, 'ptBR', 'Memórias de um passado perdido', 'Viaje para a casa da fazenda na Aridez de Garrão e colete todas as lembranças que puder encontrar.', 'É engraçado como nos lembramos do passado. Eu trabalhava 16 horas por dia nos campos e a cada sete dias eu ia para a maravilhosa cidade de Andorhal para vender o que eu colhia. Era uma vida dura, mas eu me saía bem.$b$bQuase não me lembro de nada disso. Quando eu penso no meu passado, me lembro do sorriso da Gloria ou da Andrea acenando da janela enquanto eu estava arando.$b$bA fazenda é só um pouco para o leste, mas eu não tenho certeza se estou pronto para voltar lá, $n. Eu só quero ter certeza de que não vou esquecer essas coisas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Del Garrão no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(27019, 'ptBR', 'Flagelo do Urzal', 'Caso aceite ajudar Belnistrasz, fale com ele de novo e devolva a Pedra do Juramento.', 'Excelente! Meu nome é Belnistrasz. Muito obrigado por me salvar. Eu já havia aceitado minha morte e até mesmo o fato de virar comida para essa ralé do Flagelo.$B$BEscute... em vez de apenas fugir, desejo fazer algo quanto ao ocorrido. Gostaria de me ajudar? É provável que seja perigoso, mas alguém precisa fazê-lo e, sinceramente, duvido que outros aventureiros venham a passar por este lugar devastado.', '', '', '', '', '', '', '', '', '', '', 0),
(27020, 'ptBR', 'A primeira lição', 'Alcance o nível 3 para aprender Investida. Encontre um Boneco de Treinamento na Aldeia Narache e pratique Investida.', 'Você se saiu muito bem. Seguindo seu caminho, você crescerá, aprendendo novas técnicas que você nunca imaginou antes.\n\nSua primeira lição é o poder da experiência. Vá aprender uma nova habilidade e demonstre-a para mim.', '', 'Praticar Investida', '', '', '', '', '', '', '', 'Fale novamente com Harutt Chifre Troante na Aldeia Narache.', 0),
(27021, 'ptBR', 'O caminho do caçador', 'Chegue ao nível 3 para aprender Tiro Firme. Encontre um Boneco de Treinamento na Aldeia Narache e pratique o Tiro Firme 5 vezes.', 'É chegada a hora de começar seu aprendizado, $N. Há uma longa trilha a percorrer para que se domine os segredos do caçador, mas ao prosseguir em sua jornada você estará dando passos nessa direção.$B$BVá, obtenha mais experiência e aprenda uma nova habilidade. Então, use-a em um dos bonecos de treinamento daqui.', '', 'Praticar Tiro Firme', '', '', '', '', '', '', '', 'Fale novamente com Lanka Tiro Distante na Aldeia Narache.', 0),
(27022, 'ptBR', 'O ídolo nefando', 'Proteja Belnistrasz.', 'Há um ídolo perto da entrada que serve como um forno macabro para os Javatuscos. Eles literalmente consomem as vítimas capturadas nos Sertões. Com sua ajuda, tenho certeza de que consigo destruí-lo. Preciso que você me escolte até o ídolo e me proteja enquanto realizo o ritual para destruí-lo. Mal serei capaz de me comunicar com você, que dirá me defender$B$BPosso contar com você, $r? Vai me ajudar a acabar com tais atrocidades?', 'Proteja Belnistrasz enquanto ele realiza o ritual para desativar o ídolo.', '', '', '', '', 'Proteja Belnistrasz enquanto ele realiza o ritual para desativar o ídolo.', '', '', '', 'Volte ao Braseiro de Belnistrasz.', 0),
(27023, 'ptBR', 'Os caminhos dos andarilhos do sol', 'Alcance o nível 3 para aprender Selo de Comando. Encontre um Boneco de Treinamento na Aldeia Narache, use o Selo em si mesm$go:a; e ataque um dos Bonecos de Treinamento.', 'É sempre um prazer encontrar $Gum irmão:uma irmã; dos Andarilhos do Sol. Não somos tão numerosos quanto as ordens mais antigas, mas nossos segredos não são menos poderosos e os nossos correligionários não são menos respeitados.$B$BÀ medida que você continua em sua jornada, você se aproximará da Luz e ganhará habilidades com as quais nunca sonhou.\n\nVá, obtenha mais experiência e volte quando tiver aprendido uma nova habilidade. Quero que você demonstre-a para mim.', '', 'Usar Selo de Comando e acertar o Boneco de Treinamento', '', '', '', '', '', '', '', 'Fale novamente com o Andarilho do Sol Helakar na Aldeia Narache.', 0),
(27024, 'ptBR', 'Suspeitos de um crime perfeito', 'Mate Glutão, Mordresh Olho-de-Fogo e Tutan\'kash.', 'Embora Amnennar seja a ameaça principal aqui, ele não é a única. Você precisa matar os tenentes, se realmente deseja acabar com a fortaleza deles no Urzal.$B$BGlutão guarda a entrada da Espiral de Espinhos.$B$BMordresh encontra-se no topo da Pilha de Ossos, incitando o frenesi destrutivo no Flagelo.$B$BTutan\'kash vive no subsolo. Para que ele saia de seu esconderijo, será necessário tocar o gongo na Câmara do Arauto três vezes.$B$BBoa sorte, $Gbravo herói:brava heroína;.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Koristrasza', 0),
(27025, 'ptBR', 'Perigo na mata', 'Pegue 6 Sementes de Espetocardo.', 'Chegou a época do espetocardo! As sementes de espetocardo são responsáveis por 89% das lesões sementais entre caçadores.$B$BTem muita semente de espetocardo principalmente na mata de baixada, a norte do pavilhão. Elas costumam ficar aos pés das árvores e atacar quem passa.$B$BEm uma situação normal, eu aconselharia você a passar longe delas, mas estou precisando de alguém para ajudar a recolhê-las por motivo de segurança! Traga-me algumas sementes de espetocardo para que outros não se machuquem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Oficial de Segurança Pipsy no Pavilhão dos Andarilhos, em Loch Modan.', 0),
(27026, 'ptBR', 'Alerta vermelho: lince', 'Mate 8 Linces.', 'Parem tudo! Acabei de ser informada de que linces foram vistos rondando o pavilhão. Linces!$B$BVeja bem, eu nunca vi um lince, mas tenho certeza de que são perigosos. Eles são tipo uma jaguatirica, ou coisa parecida. Não quero que ninguém saia até que a área esteja em segurança!$B$BDigo, ninguém menos você. Vou lhe pagar para limpar a área, $c. Mas cuidado para não sair $Gtodo arranhado:toda arranhada;.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Oficial de Segurança Pipsy no Pavilhão dos Andarilhos, em Loch Modan.', 0),
(27027, 'ptBR', 'Golpe primevo', 'Alcance o nível 3 para aprender Golpe Primevo, em seguida encontre um Boneco de Treinamento na Aldeia Narache e execute o Golpe Primevo 3 vezes.', 'Soube que você anda $Gocupado:ocupada; ajudando os valentes a proteger a Aldeia Narache dos Costagulha. Vamos precisar de muita sorte, $N, e também de muitos martelos.\n\nÀ medida que suas habilidades aumentam, também aumenta o seu vínculo com os elementos, o que por vez lhe dá acesso a novas habilidades.\n\nA primeira que você deve aprender se chama Golpe Primevo. Ela fará com que você derrube seus inimigos mais rápido. Aprenda-a, e depois experimente.', '', 'Praticar Golpe Primevo', '', '', '', '', '', '', '', 'Fale novamente com Meela Anda com a Aurora na Aldeia Narache.', 0),
(27028, 'ptBR', 'Caça às vespas', 'Pegue 6 Asas Vítreas de Vespa.', 'Estamos sempre procurando novas caças por aqui. O Dário pode ficar com os javalis dele... o que a gente gosta mesmo é de caças mais exóticas.$B$BLonge de mim dizer que o esvaziamento do lago tenha sido uma coisa boa, mas também não foi de todo ruim. O fundo pantanoso exposto atraiu uma nova caça: vespas!$B$BVespas gigantes, na verdade. Poucos caçadores já encararam vespas gigantes, isso ainda é uma novidade.$B$BCaso queira tentar, eu faço um trato com você. Traga-me algumas daquelas belas asas iridescentes e lhe pagarei bem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Marek Ferrocordis no Pavilhão dos Andarilhos, em Loch Modan.', 0),
(27029, 'ptBR', 'Cura para o Flagelo', 'Consiga 20 Presas Definhadas.', 'Melhor do que matar centenas de lacaios do Flagelo, é achar um meio de impedir que mais criaturas se transformem neles. Acho que consigo criar um pó fino que, quando inalado, interrompa todo o processo.$B$BPreciso de presas definhadas dos javatuscos mortos-vivos para isso. Traga-me uma grande quantidade e talvez consigamos impedir o crescimento do Flagelo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Koristrasza', 0),
(27030, 'ptBR', 'Rabos de raposa aos montes!', 'Pegue 7 Rabos de Raposa Fofos.', 'Ultimamente, temos visto mais raposas pelas montanhas. Criaturinhas espertas. Um bom teste para o caçador e um bom lucro para o bolso!$B$BEu me refiro aos rabos das raposas, $gmeu caro:minha cara;. Macios e fofinhos, servem tanto para pendurar no cinto e espantar moscas quanto para forrar as luvas da nobreza.$B$BOra vejam só, eu de conversa mole que nem um goblin. Sou um anão: vim aqui para caçar, não para conversar! Mas, se você me trouxer alguns rabos de raposa, eu lhe pagarei com prazer. Tem muita raposa a norte do pavilhão, na mata de baixada.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Marek Ferrocordis no Pavilhão dos Andarilhos, em Loch Modan.', 0),
(27031, 'ptBR', 'O aerolouco', 'Pegue 3 Penas Voadoras Impolutas de Águias Douradas.', 'Tô de saco cheio de girocópteros. Sim, OK, eles funcionam, mas desde quando funcionar é o bastante para um gnomo de verdade? Eu quero voar pra valer, com ASAS!$B$BJá faz anos que eu estudo as aves, tentando descobrir qual é o segredo para fazer uma máquina voar como um passarinho. Planar e mergulhar com elegância. O farfalhar das asas com o vento, ah...$B$BVocê! Você vai me ajudar. Quero que me traga as melhores penas de voo que encontrar. As águias douradas que circulam perto do pavilhão devem servir direitinho...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gomez Plosivo no Pavilhão dos Andarilhos, em Loch Modan.', 0),
(27032, 'ptBR', 'Ave, aves!', 'Encontre o Navestruz Enferrujado na Caverna Asaférrea.', 'Eu estou realmente perto da perfeição com a minha máquina dos sonhos: o navestruz! O primeiro mecanostruz voador! Bem, só tem um porém...$B$BQuando eu estava dando os toques finais no navestruz, dentro da minha caverna-laboratório secreta, minhas outras criações ficaram um pouco, digamos, enciumadas. Talvez não tenha sido uma boa ideia dar personalidade a aves mecânicas, para começo de conversa, mas isso é passado.$B$BPara reconstruir o navestruz, preciso do Mecanismo Robótico Supermecânico do protótipo original! Por favor, vá até a caverna e resgate essa peça para mim!', '', '', '', '', '', '', '', '', '', '', 0),
(27033, 'ptBR', 'Coração de navestruz', 'Devolva o Mecanismo Robótico Supermecânico para Gomez Plosivo no Pavilhão dos Andarilhos.', 'Ao abrir a portinhola, você vê um aparelho chamativo ligado a vários fios, engrenagens e sabe-se lá o que mais.$B$BO mecanismo é desplugado facilmente. É hora de devolvê-lo para Gomez.', '', '', '', '', '', '', '', '', '', '', 0),
(27034, 'ptBR', 'Aborrescência', 'Fale com Teles Plosivo na margem leste do Loch.', 'Não desenvolvi a navestruz para mim, $n. Nem para a gnomidade. Quero que meu filho pilote a minha criação.$B$BJá estou velho e meus reflexos não são mais os mesmos. Mas o meu garoto, o meu Teles, tem potencial para ser o melhor piloto jamais visto em Azeroth – se ele deixar de ser um adolescente enjoado.$B$BMeu filho fica o dia inteiro sentado na beira do lago, olhando para o céu. Ele está com algum problema mas se recusa a conversar com o próprio pai sobre isso. Não sei mais o que fazer!$B$BPor favor, $n, você poderia falar com o meu filho? Diga que preciso dele para pilotar a navestruz!', '', '', '', '', '', '', '', '', '', '', 0),
(27035, 'ptBR', 'O revoltado', 'Destrua o Moldaterra Crepuscular no meio do acampamento do Martelo do Crepúsculo.', 'Olha só para eles. O Martelo do Crepúsculo devastou tudo!$B$BEsse culto gerou o Cataclismo, destruiu o Dique Lapidado e provocou a seca do Loch. E agora ficam aí vagando pelas ruínas como se fossem a casa deles!$B$BAh, se ainda houvesse justiça neste mundo, alguém invadiria aquele acampamento e partiria aquele artefato deles em dois. Mas eu ainda não tenho força suficiente.$B$BE ninguém tem coragem de tentar! Nem mesmo você! Tá vendo? Ninguém merece...', '', 'Moldaterra Crepuscular destruído', '', '', '', '', '', '', '', 'Fale novamente com Teles Plosivo em Loch Modan.', 0),
(27036, 'ptBR', 'A vingança de Vyrin', 'Mate o Velho Fumaça e traga a cabeça dele.', 'Você estaria $Ginteressado:interessada; em dar o troco em Sua Excelência o Caçador? O Dário até tem talento. Me dói dizer isso, mas é verdade.$b$bHá um ano, todo o Pavilhão dos Andarilhos saiu atrás de um urso enorme, mas nenhum caçador teve sorte. Então, o Dário resolveu tentar também. E tudo que trouxe de volta foi aquela cicatriz horrorosa debaixo do olho.$b$bSe você matasse aquele urso, tenho certeza que até o Dário ficaria sem palavras.$B$BO Velho Fumaça, nome que demos ao urso, costuma vagar por perto da toca, numa caverna a norte daqui.', '', '', '', '', '', '', 'Velho Fumaça', '', '', 'Entregue a Cabeça do Velho Fumaça para Dário, o Novato, no Pavilhão dos Andarilhos em Loch Modan.', 0),
(27037, 'ptBR', 'A vingança de Vyrin', 'Entregue a Cabeça do Velho Fumaça para Vyrin Velozvento no Pavilhão dos Andarilhos.', 'Pela luz! Não me traga mais essas coisas para o Pavilhão! É insalubre, é incômodo, é in... in... insalubre!$b$bLeve isso lá para fora, OK? Ninguém quer ver esse seu trofeuzinho ensanguentado! Mesmo!', '', '', '', '', '', '', '', '', '', '', 0),
(27038, 'ptBR', 'Peças perdidas', 'Recolha 5 Peças Perdidas nas redondezas do Porto de Ventobravo.', '<O Sargento volta a atenção para você.>$B$BPreste atenção, se você quer acelerar as coisas por aqui, procure Flintlocke. Um carregamento inteiro de peças de máquinas de cerco foi extraviado e está espalhado por todos os lados nas docas.$B$BRecolha as peças perdidas e entregue-as para Flintlocke para que ele possa terminar a montagem. Ele está esperando no outro lado da estrada.', '', '', '', '', '', '', '', '', '', 'Entregue as peças para Fargo Flintlocke, no Porto de Ventobravo.', 0),
(27039, 'ptBR', 'Intenções perigosas', 'Encontre a Sicária Rane Yorick na Plantação do Ivar, que fica na Floresta de Pinhaprata.', 'Você sabe porque Mortuus bota "nub" no final do seu nome, $n? Porque ele é um cabeça dura, miolo-mole, apedeuta e analfabeto. Ele viu sua designação, "NUB", e achou que isso fosse parte do seu nome. Você agora faz parte da NOVA UNIDADE DE BATALHA da Cidade Baixa.$B$BMas chega de gracinha! Faz três dias, enviei a sicária Yorick em uma operação secreta. O objetivo dela era retornar com informações sobre a Frente de Libertação de Guilnéas. Três dias e ela ainda não deu notícias.$B$BSiga para sudoeste, para a Plantação do Ivar, e encontre Yorick, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(27040, 'ptBR', 'Decodificação para idiotas', 'Decodifique 6 planos.', 'Não temos as ferramentas para decodificar estes planos, mas o Martelo do Crepúsculo tem.$B$BVocê poderia ser $Gum bom menino:uma boa menina; e levar os planos até lá para rodar em um daqueles antigos dispositivos de decodificação?', '', 'Planos decodificados', '', '', '', '', '', '', '', '', 0),
(27041, 'ptBR', 'Decodificação para idiotas', 'Decifre 6 planos.', 'Não temos as ferramentas para decifrar os planos, mas o Martelo do Crepúsculo tem.$B$BVocê poderia levar os planos até lá para rodar em uma daquelas máquinas decifradoras?', '', 'Planos decifrados', '', '', '', '', '', '', '', '', 0),
(27042, 'ptBR', 'Combata fogo, água e ar com...', 'Obtenha as Proteções do Fogo, da Água e do Ar. Em seguida, mate Haethen Kaul.', 'Ouviste o bagual charlando lá em cima sem parar? Aquele é o Haethen Kaul, o galego que é o chefe daqui.$B$BO maleva tá mais metido que bosta em chinelo de dedo. Ele tá puxando força daqueles três elementais que tão presos e tá ficando de um jeito que não dá pra derrubar, barbaridade!$B$BBueno, pra usted pelear com ele cabeça a cabeça, carece de primeiro passar a faca nos bicharocos e pegar a guarda deles. Isso vai te proteger dos feitiços do Haethen.$B$BBueno, de quase todos.', '', 'Proteção do Fogo adquirida', 'Proteção da Água adquirida', 'Proteção do Ar adquirida', '', '', 'Haethen Kaul', '', '', 'Fale novamente com a Prospectora Cervejeira no Templo da Terra, que fica no Geodomo.', 0),
(27043, 'ptBR', 'Combata fogo, água e ar com...', 'Obtenha as Proteções do Fogo, da Água e do Ar. Em seguida, mate Haethen Kaul.', 'Você reparou em um homem que não parava de gritar lá em cima? Aquele é o Haethen Kaul, o líder deles.$B$BTodos sabem que o poder que ele retira dos elementais lhe subiu à cabeça. E, infelizmente, isso o tornou quase invencível.$B$BPara derrotá-lo, primeiro você terá que matar cada um dos elementais para ganhar a proteção deles. Isso $Go:a; guardará contra os feitiços do Haethen.$B$BBem, contra quase todos.', '', 'Proteção do Fogo adquirida', 'Proteção da Água adquirida', 'Proteção do Ar adquirida', '', '', 'Haethen Kaul', '', '', 'Fale novamente com a Relicária Jessia Nigrossol no Templo da Terra, que fica no Geodomo.', 0),
(27044, 'ptBR', 'A questão dos camponeses', 'Escolte o Príncipe Anduin até o Fazendeiro Wollerton no Sítio dos Wollerton, que fica em Ventobravo. Se ele não estiver mais com você, poderá encontrá-lo na Bastilha Ventobravo.', 'Não estou preparado para retornar ao forte ainda. Você me ajudaria a resolver um problema? Recentemente, alguns fazendeiros da região reclamaram com o Rei sobre o sumiço do gado. Meu pai prometeu que alguém investigaria, mas a guarda da cidade está tão atarefada que vai levar semanas para começar a investigação.$B$BPensei que eu pudesse ser útil. Os fazendeiros poderão se animar vendo alguém tomar uma atitude, especialmente se esse alguém for da família real. Além do mais, são só umas vaquinhas perdidas... Nada perigoso.$B$BLeve-me até o fazendeiro Wollerton aqui na cidade!', 'Anduin escoltado até o Fazendeiro Wollerton', '', '', '', '', 'Anduin escoltado até o Fazendeiro Wollerton', '', '', '', 'Fale com o Fazendeiro Wollerton no Sítio dos Wollerton, que fica em Ventobravo.', 0),
(27045, 'ptBR', 'Sangria desatada', 'Entre no Chalé dos Ivar e encontre um esconderijo adequado no segundo andar. Escute a conversa do lorde Darius Crowley.', 'O líder da Frente de Libertação de Guilnéas, Darius Crowley, tem se reunido com outros worgens dentro do chalé nos últimos três dias. Não tenho certeza do que está acontecendo, mas precisamos entrar no chalé e encontrar um bom esconderijo de onde possamos escutar as conversas.$B$BÉ agora ou nunca, $r. Podemos não ter outra chance.$B$BMe prometa que, se eu não conseguir, você retornará ao Alto Comando dos Renegados e informará Belmonte do que nós descobrirmos.', '', 'Descubra os Planos de Lorde Darius Crowley', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Sicário Belmonte no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27046, 'ptBR', 'Medo de broca', 'Mate 10 Litovermes.', 'Os litovermes infestam a rocha, comendo todas as pedras que virem pela frente até que nosso mundo desmorone. Para cada um que matamos, dois aparecem, mas temos que insistir no combate a essa praga. Precisamos acabar com eles.$B$BVá até os Abismos Esfacelados e mate todos os litovermes que encontrar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Felsen, o Perene, no Trono de Therazane.', 0),
(27047, 'ptBR', 'Grânulos', 'Colete 10 Grânulos de Dolorita.', 'Os cristais mais raros costumam se formar nos lugares mais perigosos. Nos Abismos Esfacelados, há formações de dolorita – muito mais valiosa do que o ouro que as raças carnentas adoram tanto.$B$BComo você é um ser de carne e de baixa estatura, certamente conseguirá entrar nos Abismos Esfacelados para pegar alguns grânulos de dolorita. Você se exporia a tal perigo por mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Felsen, o Perene, no Trono de Therazane.', 0),
(27048, 'ptBR', 'Economia subterrânea', 'Use as Bombas da Ricket para coletar 3 Alabastros das Profundezas, 3 Celestitas das Profundezas, 3 Ametistas das Profundezas e 3 Granadas das Profundezas.', 'Ei, você! Tô precisando de ajuda para pegar uns cristais. Os elementais pagam os tubos por esses troços. Se você me ajudar a pegar todos os tipos de cristal, eu te dou uma parte dos lucros.$B$BUsa essas bombas aqui para explodir as formações maiores.$B$BEu tenho o péssimo hábito de carregar a mão nos explosivos que monto. Cuidado com o coice.', '', '', '', '', '', '', '', '', '', 'Fale com Ricket nos Abismos Esfacelados, no Geodomo.', 0),
(27049, 'ptBR', 'Rocha mole', 'Mate 8 Beemotes Fúngicos.', 'A deterioração na Vastidão Carmesim ainda não cedeu. Destrua os Beemotes Fúngicos que estão despejando essa imundície sobre o nosso reino. Se eles continuarem a renascer, nós continuaremos a destruí-los.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gorsik, o Turbulento, no Trono de Therazane.', 0),
(27050, 'ptBR', 'Fungos em fúria', 'Destrua 10 brotos de cogumelo na Vastidão Carmesim.', 'Alguma coisa sobre a Vastidão Carmesim não para de semear esporos que proliferam repulsivamente. Novos fungos estão nascendo e temos que esmagá-los antes que proliferem.', '', 'Brotos de cogumelo destruídos', '', '', '', '', '', '', '', 'Fale novamente com Gorsik, o Turbulento, no Trono de Therazane.', 0),
(27051, 'ptBR', 'Não vamos desistir!', 'Tome um Saco de Crescimento Miraculoso dos Verlok das mãos dos Verlok da Vastidão Carmesim.', 'Os troggs não se dispersaram depois que você matou Glop. Os lacaios dele pegaram o restante do agente de crescimento e continuam a espalhar as sementes da corrupção por toda a Vastidão Carmesim.$B$BVá atrás deles e recolha todo o Crescimento Miraculoso dos Verlok que você encontrar. Temos que nos livrar disso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ruberick no Trono de Therazane.', 0),
(27053, 'ptBR', 'Caldeirão da Aridez de Garrão', 'Vá para a Aridez de Garrão nas Terras Pestilentas Ocidentais para encontrar e derrotar o Mestre da Caldeira no local. Depois, use a chave dele para acessar o caldeirão.', 'Minha análise das amostras está completa! A praga que aflige os animais daqui não é de forma alguma uma doença residual. Não, isto é algo novo... e creio ter o conhecimento do que possa ser.$b$bA Seita dos Malditos mantém um caldeirão pestilento em uma fazenda chamada Aridez de Garrão, que fica bem ao sudeste de nossa posição, perto de onde as Terras Pestilentas Orientais se iniciam.$B$BEu preciso de uma amostra do conteúdo deste caldeirão, de modo a confirmar minhas suspeições.$b$bMata o mestre da caldeira presente no local e toma-lhe a chave que carrega consigo, pois desse modo terás acesso ao caldeirão para que coletes a amostra de que necessito.', '', '', '', '', '', '', 'Mestre da Caldeira Almafúria', '', '', 'Examine o Caldeirão do Flagelo na Aridez de Garrão, que fica nas Terras Pestilentas Ocidentais.', 0),
(27054, 'ptBR', 'Ações desesperadas', 'Mate a Instrutora Malícia e pegue as Ordens da Seita dela.', 'A Seita dos Malditos mantém um pequeno acampamento a leste, o Posto de Malícia, que é usado para treinamento de campo dos alunos de Scolomântia. Talvez nós tenhamos permitido que eles mantivessem esses treinamentos por tempo demais.$b$bSe os sectários estão realmente usando a peste para inocular a vida selvagem da área, então este ato deve se proceder no Posto de Malícia.$b$bA Instrutora Malícia é a líder deste Posto. Encontra esta elfa maldita, dá cabo da vida dela e descobre de quem ela recebe ordens.', '', '', '', '', '', '', 'Instrutora Malícia', '', '', 'Fale novamente com o Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(27055, 'ptBR', 'Alunos de Krastinov', 'Mate 2 Discípulos Krastinovianos, 2 Brutos de Carne Retalhada, 2 Estripadores de Carne Retalhada e 4 Corpúsculos Profanos dentro da Caverna das Lágrimas, que fica nas Terras Pestilentas Ocidentais.', 'As Ordens da Seita dizem que a peste do caldeirão encontrado na Aridez de Garrão está, na verdade, sendo usada para DUAS finalidades. A primeira é espalhar a doença pelos animais da região, o que nós já sabíamos.$b$bO resto da peste está sendo levada para a Caverna das Lágrimas, uma caverna que fica ao norte do Posto de Malícia, para ser usada em experimentos obscuros. Os alunos de Scolomântia estão usando a praga para reanimar os mortos!$b$bEles precisam ser impedidos imediatamente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(27056, 'ptBR', 'O relatório de Belmonte', 'Entregue o Relatório de Belmonte para a Grande Dama Sylvana Correventos no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', '<Belmonte entrega um envelope selado para você.>$B$BEntregue este relatório para a Grande Dama Sylvana Correventos. É minha avaliação da situação em Pinhaprata baseada no trabalho de campo de vocês.$B$BSe não esmagarmos os rebeldes worgens, eles nos dominarão. Precisamos agir agora!', '', '', '', '', '', '', '', '', '', '', 0),
(27057, 'ptBR', 'Volte para o Acampamento', 'Leve a Garrafa Cheia da Aridez de Garrão para o Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 'Você fecha cuidadosamente a torneira que fica na tampa de acesso, enquanto os líquidos pútridos se assentam dentro da garrafa.$b$bCom o veneno em mãos, é hora de retornar para o Acampamento dos Restauradores para encontrar com o Agente de Campo Kaartish.', '', '', '', '', '', '', '', '', '', 'Leve a Garrafa da Aridez de Garrão Cheia para o Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(27058, 'ptBR', 'Sequência errada', 'Use o Controle do Pórtico para inserir a sequência de ativação errada e destruir o Pórtico.', 'Temos que impedir o Martelo do Crepúsculo de usar o Pórtico. E só há uma coisa a fazer.$B$BInsira uma sequência de ativação errada e destrua o Pórtico.$B$BHum, vejamos... Sim, aqui tem uma sequência que abre as profundezas incendiárias das Terras do Fogo, o plano elemental do fogo. Essa vai dar conta do trabalho muito bem.', '', 'Pórtico destruído', '', '', '', '', '', '', '', 'Fale novamente com a Exploradora Mowi no Templo da Terra, que fica no Geodomo.', 0),
(27059, 'ptBR', 'Sequência errada', 'Use o Controle do Pórtico para inserir a sequência de ativação errada e destruir o Pórtico.', 'Temos que impedir o Martelo do Crepúsculo de usar o Pórtico. E só há uma coisa a fazer.$B$BInsira uma sequência de ativação errada e destrua o Pórtico.$B$BHum, vejamos... Sim, aqui tem uma sequência que abre as profundezas incendiárias das Terras do Fogo, o plano elemental do fogo. Essa vai dar conta do trabalho muito bem.', '', 'Pórtico destruído', '', '', '', '', '', '', '', 'Fale novamente com o Avaliador Ruibarbo no Templo da Terra, que fica no Geodomo.', 0),
(27060, 'ptBR', 'Vaca profana', 'Enquanto escolta Anduin Wrynn, siga o rastro de sangue que vai da Propriedade do Fazendeiro Wollerton até o local do crime. Proteja Anduin. Caso o perca de vista, ele estará esperando por você na Bastilha Ventobravo.', '<O fazendeiro Wollerton tenta se recompor.>$B$BVacas? Você está perguntando sobre o gado sumido?$B$BNormalmente deixo as vacas pastando ao norte daqui de casa. De vez em quando some uma deixando um rastro de sangue. Quem faria isso?$B$BTenho medo de seguir esse rastro... Alguma coisa doentia está acontecendo em Ventobravo!', '', 'Cena do crime descoberta', 'Príncipe Anduin protegido', '', '', '', '', '', '', 'Fale com o Príncipe Anduin Wrynn. Se ele não estiver com você, encontre-o na Bastilha Ventobravo.', 0),
(27061, 'ptBR', 'O Mirante do Crepúsculo', 'Fale com a Tempestária Mylra no Mirante do Crepúsculo, que fica no Geodomo.', 'O dragão que eles mencionaram é o Abyssion, $n. Não vai ser fácil tirar o fragmento dele.$B$BProcure a Mylra novamente, perto do Mirante do Crepúsculo.$B$BEla lhe dirá qual será o nosso próximo passo.', '', '', '', '', '', '', 'Tempestária Mylra', '', '', '', 0),
(27062, 'ptBR', 'Ameaça crescente', 'Encontre ajuda no Urzal dos Mortos.', 'Parece que os Javatuscos do Urzal dos Mortos se aliaram ao Flagelo. Péssimas notícias, $c. Não conseguiremos resistir a um ataque deles, pois já temos problemas suficientes com os membros do Temível Totem. Vá até o Urzal dos Mortos, a leste daqui, e veja se consegue ajuda para impedir este ataque.', '', '', '', '', '', '', '', '', '', '', 0),
(27063, 'ptBR', 'Ameaça crescente', 'Encontre ajuda no Urzal dos Mortos.', 'O Flagelo é uma afronta à natureza. Ele corrompeu os Javatuscos do Urzal dos Mortos e agora ameaça se espalhar por toda Mil Agulhas. E, depois, temo eu, por Feralas a oeste. É mister que você vá até lá e faça tudo para impedir que isso ocorra. Talvez alguém possa lhe ajudar. Os ventos me contam sobre uma poderosa presença na região.', '', '', '', '', '', '', '', '', '', '', 0),
(27064, 'ptBR', 'Algo de podre no reino', 'Escolte Anduin Wrynn até o terceiro andar do quartel-general da AVIN, no distrito Cidade Velha, em Ventobravo. Se você perder ele de vista, encontre-o na Bastilha Ventobravo.', '$n, parece até que o Samuelson está tentando nos fazer perder tempo de propósito. Os estivadores não sabem de nada. E mais: sumiram alguns explosivos do Porto de Ventobravo!$B$BSabe o que eu acho? Aposto que o Samuelson está escondendo alguma coisa. Ele provavelmente descobriu alguma pista sobre o Martelo do Crepúsculo e quer todo o mérito e glória para si.$B$BAcho melhor a gente dar uma espiada nos relatórios dele, no quartel-general da AVIN. Quero que você me leve até lá para que eu possa ver os arquivos e descobrir o que ele sabe.', '', 'Documentos de Samuelson examinados por Anduin', '', '', '', '', '', '', '', 'Fale com Anduin Wrynn. Se você perder ele de vista, encontre-o na Bastilha Ventobravo.', 0),
(27065, 'ptBR', 'A esquadra do Chefe Guerreiro', 'Apresente-se à Almirante Machadinha na Retaguarda dos Renegados, que fica na Floresta de Pinhaprata.', 'Os reforços de Kalimdor chegaram ontem à noite. Três belonaves órquicas cheias de suprimentos, armas e soldados. Três belonaves órquicas perdidas para os malditos worgens de Dentessangue.$B$BComo é possível uma esquadra órquica inteira ser derrotada por um pequeno bando de combatentes sem maquinário de bloqueio? Isso é o que você vai descobrir pra mim.$B$BJunte suas coisas e apresente-se à almirante Machadinha na Retaguarda dos Renegados, a sudoeste daqui.$B$BQuero aqueles orcs trabalhando, $n. Aguardo seu relatório completo.', '', '', '', '', '', '', '', '', '', '', 0),
(27066, 'ptBR', 'Aprenda a Palavra', 'Alcance o nível 3 para aprender Palavra Sombria: Dor. Treine lançando-a 5 vezes contra um dos bonecos de treinamento na Aldeia Narache.', 'À medida que suas habilidades crescem e se expandem, você poderá ganhar muitos novos poderes.\n\nVá ganhar mais experiência por aí e volte a mim quando tiver aprendido algo novo. Você pode fazer uma demonstração nos bonecos de treinamento aqui perto.', '', 'Praticar Palavra Sombria: Dor', '', '', '', '', '', '', '', 'Fale novamente com a Vidente Pena do Corvo na Aldeia Narache.', 0),
(27067, 'ptBR', 'Fogo Lunar', 'Alcance o nível 3 para aprender Fogo Lunar. Depois, pratique em um Boneco de Treinamento na Aldeia Narache.', 'À medida que desenvolve suas habilidades, druid$Ga:esa;, você começará a sentir sua conexão com a Mãe Terra se aprofundar, a entender outros segredos da natureza e a aprender a lançar novos feitiços.\n\nAgora vá, ganhe experiência e volte a mim quando tiver aprendido um novo feitiço. Demonstre o que aprendeu.', '', 'Praticar Fogo Lunar', '', '', '', '', '', '', '', 'Fale novamente com Gart Corre com a Névoa na Aldeia Narache.', 0),
(27068, 'ptBR', 'Chefe Ukorz Escalpareia', 'Mate o Chefe Ukorz Escalpareia.', 'Saca só isso, $Gmano:gata;. É assim que a banda toca, tá ligad$Go:a;? Trairage por cima de trairage. Eu te traí por causa da espada, aí o chefe Ukorz faz uma sacanagem maior ainda comigo pelo mesmo motivo.$B$BA vida é essa, $Gmeu peixe:neném;. Ou era...$B$BSei que tu não é lá muito fã do Mazoga aqui. Mas sei que tu vai entrar lá de qualquer jeito. Mata ele pra mim. Derrama sangue na areia e dá ao chefe Ukorz Escalpareia o fim que todo Zangareia merece... um fim sangrento.$B$BQuem sabe eu tiro o encosto das minhas parada e deixo tudo pra tu antes de cantá pra subir, hein?', '', '', '', '', '', '', 'Chefe Ukorz Escalpareia', '', '', 'Fale novamente com o Espírito de Mazoga em Zul\'Farrak.', 0),
(27069, 'ptBR', 'Trovão de aço', 'Recupere 5 Caixotes dos Lobos do Mar.$B$BPeça um outro lobinho do mar à Almirante Machadinha se você perder o seu.', 'Acho que não vamos viver o suficiente para suportar a vergonha dessa derrota, $n. O Chefe Guerreiro vai mandar nos executar com certeza.$B$BMas quero ser mico de circo se não vender caro minha pele. Todo o atracadouro está infestado de worgens Dentessangue, mas ainda há esperança. Quero que você escolte um dos nossos lobinhos do mar até o atracadouro, diretamente a oeste daqui, e recupere nossos suprimentos. Quando o lobinho não puder carregar mais nada, volte e fale comigo.', '', 'Caixote dos Lobos do Mar recuperado', '', '', '', '', '', '', '', 'Fale novamente com a Almirante Machadinha na Retaguarda dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27070, 'ptBR', 'Bonita, linda e joiada', 'Obtenha a Tiara das Profundezas e a Escama Eletrificada de Gahz\'rilla.', 'Ouvi dizer que uma trolesa daqui – acho que o nome é "Hidromante Velratha" – está de posse de uma bela joia, linda, rara e poderosa, chamada Tiara das Profundezas. Velratha usa a joia para controlar o poderoso semideus Gahz\'rilla, cujas escamas estalam de pura energia. Sabe o que isso tudo quer dizer, $r?$B$BEu quero! Mate Velratha, pegue a Tiara das Profundezas, mate Gahz\'rilla e pegue uma das escamas dele. Traga tudo de volta pra mim com urgência! Eu vou te recompensar generosamente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Engenheiro-chefe Silvadágua.', 0),
(27071, 'ptBR', 'A fúria dos Zangareia', 'Mate o Mandingueiro Zum\'rah, Antu\'sul, Ruuzlu e Theka, o Mártir.', 'Os Zangareia... taí uma tribo obstinada. Sobreviveram a muita tempestade de areia e séculos de conflito com outras coisa que hoje tão coberta pelas duna. É besteira pensar que as únicas força aqui são trolls. Nós temos domado os escaravelho, criado silitídeo e ressuscitado os morto para pagar de zumbi por toda a eternidade.$B$BRuuzlu, o braço direito do chefe Ukorz Escalpareia, tá planejando usar tudo isso pra retomar Tanaris pro império Zangareia. É melhor matar os troll responsável por isso se cê quiser viver, $gmano:calega;.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Espírito de Mazoga.', 0),
(27072, 'ptBR', 'A antiga guarnição', 'Vá para a Antiga Guarnição e mate 6 Sectários Enlouquecidos. Depois, localize Jack Bauden.', 'Eu reconheço o símbolo nesses distintivos, de antes do ataque do Asa da Morte a Ventobravo. Eles pertenciam aos soldados da antiga guarnição, que fica na parte oeste da cidade, protegendo o porto.$b$bVocê não poderia ter chegado numa hora melhor. Um dos meus melhores agentes, Jack Bauden, está tentando se infiltrar no culto do Martelo do Crepúsculo. Na noite passada, ele sumiu. Se você e Anduin estiverem certos, os cultistas estão escondidos na antiga guarnição. Temos pouco tempo! Ataque a antiga guarnição, mate os cultistas e resgate Jack Bauden.', '', '', '', '', '', '', '', '', '', 'Fale com Jack Bauden na Antiga Guarnição, que fica em Ventobravo.', 0),
(27073, 'ptBR', 'Mande-os para o Inferno!', 'Mate 10 Catadores Dentessangue.', 'É culpa dos goblins, $r!$B$B<hic!>$B$BNós saímos do Ancoradouro Borraquilha, lá em Azshara, pra Pinhaprata. Foi um grande erro! Nunca existiu tamanho covil de pecado e iniquidade em nosso grande império. Aqueles goblins malditos incentivaram nossos vícios e nos embarcaram junto com barris cheios de cerveja.$B$B<hic!>A vergonha deixa marcas mais fundas que cicatrizes. Nossa honra tem que ser recuperada! Mate os worgens Dentessangue que nos emboscaram. Eles estão rapinando os destroços a sudoeste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Senhor da Guerra Torok na Retaguarda dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27074, 'ptBR', 'Ataque ao Martelo', 'Fale com Ashlan Risadura ao lado da Fortaleza Mo\'grosh, em Loch Modan.', 'Você conseguiu o impossível! Cansei de ficar aqui paradão. É hora de virar um gnomo com G maiúsculo!$B$BPreciso falar com o meu pai. E você, não se preocupe mais comigo. Você tem que continuar o combate aos sectários.$B$BProcure o Ashlan Risadura, a leste daqui. Ele está lutando sozinho contra o Martelo do Crepúsculo. Sem ajuda de ninguém. Você é a única esperança dele!$B$BNão desista, $n. Eu não vou desistir.', '', '', '', '', '', '', '', '', '', '', 0),
(27075, 'ptBR', 'Servos de Cho\'gall', 'Mate 7 ogros Mo\'grosh na Fortaleza Mo\'grosh.', 'O Martelo do Crepúsculo começou como um clã dentro da selvagem Horda. Mas Cho\'gall, o líder deles, aos poucos transformou aquele bando de ogros em um culto mórbido, atraindo de braços abertos todo tipo de louco que deseje o fim da existência. Como você pode ver, ainda há muitos ogros fiéis ao culto, tão insanos, fanáticos e fortes quanto antes.$B$BEsses monstros cruéis tiveram a audácia de vir até aqui para espalhar sua sujeira por nossas terras. Quantos mais você matar, melhor será para Loch Modan, $n.', '', 'Ogros Mo\'grosh mortos', '', '', '', '', '', '', '', 'Fale novamente com Ashlan Risadura ao lado da Fortaleza Mo\'grosh, em Loch Modan.', 0),
(27076, 'ptBR', 'Arrombamento e invasão', 'Liberte Weegli Pavio Quente e mate Nekrum Cometripas e o Sacerdote Sombrio Diz\'ieh.', 'Um grande amigo meu, Weegli Pavio Quente, juntou-se ao sargento Bly e ao seu grupo de foras-da-lei para invadir Zul\'farrak e levar a lendária Sul\'thraze de prêmio. Claro, eles subestimaram a tribo Zangareia e agora estão todos presos, aguardando execução para aplacar o semideus Put\'zgrillah!$B$BSe você conseguir libertá-lo, ele ajudará você a limpar o caminho até a câmara particular de Ukorz, onde ele guarda pelo menos um pedaço da lâmina.$B$BMate os captores dele, Nekrum Cometripas e o sacerdote sombrio Diz\'ieh, como vingança. Vou recompensar você por isso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tran\'rek.', 0),
(27077, 'ptBR', 'Presos ao caos', 'Arranque do chão 10 Aguilhões Nascentes de Elemêntio na Fortaleza Mo\'grosh.', 'Os devotos do Martelo do Crepúsculo usam seus poderes para puxar elemêntio até a superfície em forma de aguilhões retorcidos. Esses aguilhões são usados como estrutura para a construção de prédios, que ficam encrustados na terra arrasada.$B$BParece que os ogros estão no meio da moldagem, e temos que atacá-los durante esse processo.$B$BQuebre os aguilhões enquanto estão flexíveis e traga-os para mim! Não vamos deixar esses patifes usar nem um centímetro da nossa terra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ashlan Risadura ao lado da Fortaleza Mo\'grosh, em Loch Modan.', 0),
(27078, 'ptBR', 'Gor\'kresh', 'Derrote Gor\'kresh.', 'O ogro que ficou encarregado de cuidar desses grosseirões idiotas atende pelo nome de Gor\'kresh. Ele é grande o suficiente para mandar e desmandar nesses brutamontes, e ainda por cima é bastante esperto. Nunca parta do princípio de que um ogro é burro. É aí que eles nos pegam.$B$BSe você der cabo dele, mostraremos ao Martelo do Crepúsculo que Loch Modan não é trampolim para ninguém. Pegue firme contra o Gor\'kresh e mande esses idiotas de volta para as terras altas!', '', '', '', '', '', '', 'Gor\'kresh', '', '', 'Fale novamente com Ashlan Risadura ao lado da Fortaleza Mo\'grosh, em Loch Modan.', 0),
(27079, 'ptBR', 'Rastreamento do Portão do Crepúsculo', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27080, 'ptBR', 'Rastreamento do Portão do Crepúsculo', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27082, 'ptBR', 'Jogando sujo', 'Colete 8 Órgãos Adoecidos de Ursos Raivosos Gigantes e de Worgs Raivosos.', 'Você viu os gorjalas enormes vagueando pela floresta? Essas coisas malditas vieram de Guilnéas. Agora, eles vagueiam pela área em busca de comida. Nós conseguimos subjugar e usar alguns para puxar nossas carroças, mas os outros... bom, eles têm que morrer!$B$BInfelizmente, não temos soldados disponíveis para esse trabalho. É aí que você entra, $c!$B$BEu tenho um plano, mas vou precisar de alguns ingredientes. Vá para os bosques ao redor de nossa base e colete órgãos adoecidos das feras.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Boticário Vermimundo na Retaguarda dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27083, 'ptBR', 'A batalha continua', 'Apresente-se a Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 'Chegaram notícias de Andorhal, $n. A batalha foi retomada.$b$bJá é de conhecimento das forças Renegadas que você foi $Go herói:a heroína; da primeira batalha de Andorhal. Koltirus requisita sua presença imediatamente.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27084, 'ptBR', 'A milícia dos fazendeiros', 'Use a Coleira da Gárgula de Ébano em 6 Milicianos Provincianos em Andorhal.', 'A batalha começou quando eles nos atacaram por trás. Eu baixei minha guarda e um grupo de fazendeiros e milicianos fracamente armados atacou nossos flancos, saindo do Antro Repelente.$b$bEles podem ser fracos, mas ainda assim ameaçam nos sobrepujar com seu grande número.$b$bAs abominações de Lívida cuidarão do combate corpo a corpo. Mantenha-se $Gafastado:afastada; e use essa coleira para lançar minha gárgula de ébano sobre os fazendeiros.', '', 'Gárgula de Ébano liberada', '', '', '', '', '', '', '', 'Fale novamente com Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27085, 'ptBR', 'Ajuda às tropas', 'Mate 15 Defensores de Andorhal.', 'Apesar desses fazendeiros ameaçarem nos sobrepujar, nós não podemos esquecer as forças principais da Aliança.$b$bViaje para a parte oeste de Andorhal e mate os soldados humanos que estão combatendo nossos necroguardas. Nós precisamos de toda ajuda possível.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Arlindo Inácio em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27086, 'ptBR', 'Do pó ao pó', 'Mate 3 Chefes Militares de Andorhal.', 'A oeste daqui, nas profundezas da parte de Andorhal controlada pela Aliança, você vai encontrar os comandantes deles. Eles nunca entram em combate direto, ficam apenas dando ordens do alto de seus cavalos.$b$bProcure e mate esses comandantes, $n. Os humanos não terão chance.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27087, 'ptBR', 'Lívida Corvossol, revelada', 'Fale com Lívida Corvossol em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 'Eu fui informado de que aquela mulher inútil, a Lívida Corvossol, estaria aqui para me ajudar nessa batalha. Mas, até agora, tudo o que ela fez foi se esconder no porão da prefeitura que fica atrás de mim. Acho que foi melhor assim. Ela acabaria me distraindo.$b$bAinda assim, eu não posso e não vou permitir este tipo de insubordinação nas minhas tropas. Encontre-a e traga-a até mim.', '', '', '', '', '', '', '', '', '', 'Fale com Lívida Corvossol em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27088, 'ptBR', 'Só é venenoso se você ingerir', 'Use o Frango do Mato Mutante para matar o Gorjala da Floresta.', 'Pegue essa gaiola, $c. Eu pus dentro dela um de meus frangos do mato mutantes, com algumas pequenas modificações. Tem uma banana de dinamite enfiada no traseiro desse frango, misturada com gosma dos órgãos adoecidos que você me trouxe.$B$BLeve a gaiola para a floresta e encontre o gorjala errante da floresta. Solte o frango e ache um lugar confortável para apreciar minha obra-prima em ação. A explosão deve ser suficiente para matar o gorjala ou pelo menos enfraquecê-lo o suficiente para você dar cabo dele.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Boticário Vermimundo na Retaguarda dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27089, 'ptBR', 'Um ás na manga', 'Com a Val\'kyr Enfeitiçada ao seu lado, mate 5 Milicianos Provincianos Assustados para que sejam transformados em Soldados Renegados. Depois, encontre Thassarian na parte oeste de Andorhal.', 'Você não sabe como foi difícil ficar disfarçada e assistir o Koltirus deixar essa guerra escapar por entre nossos dedos. Mesmo agora aqueles fazendeiros infernais ameaçam sobrepujar nossas forças. Tudo porque ele se recusou a matar um amigo.$b$bLeve a minha val\'kyr novamente, $n. Com ela ao seu lado, mate os fazendeiros, converta-os em Renegados e mobilize-os. Depois, vá com eles até a parte oeste de Andorhal, dominada pela Aliança, e cace o cavaleiro da morte Thassarian.$b$bNós vamos ganhar esta guerra.', '', 'Miliciano Provinciano Assustado morto e convertido', 'Soldado Renegado mobilizado', 'Cace Thassarian', '', '', '', '', '', 'Investigue o corpo de Lúrido em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27090, 'ptBR', 'Andorhal, de uma vez por todas', 'Fale com a Grande Dama Sylvana Correventos em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 'Sylvana vai querer ser informada sobre a fuga de Thassarian de Andorhal. Você decide retornar para a parte da cidade dominada pelos Renegados.', '', '', '', '', '', '', '', '', '', 'Fale com a Grande Dama Sylvana Correventos em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27091, 'ptBR', 'Atacar!', 'Chegue ao nível 3 para aprender Eviscerar. Encontre um Boneco de Treinamento fora da Torre do Sol e pratique Investida.', 'Bom. Você começou muito bem. Esta estrada será longa, e à medida que melhorar sua formação, você começará a descobrir que pode fazer coisas que nunca sequer imaginou antes.$B$BVá ganhar mais experiência e aprender uma nova técnica. Quando tiver feito isso, faça uma demonstração nos bonecos de treinamento.', '', 'Praticar Investida', '', '', '', '', '', '', '', 'Fale novamente com Delios na Torre do Sol, que fica na Ilha Andassol.', 0),
(27092, 'ptBR', 'Cataclismo nas catacumbas', 'Entre na Catedral da Luz e siga para as catacumbas subterrâneas. Mate o Bispo Negro e desarme a Pilha de Explosivos que está próxima.', 'Não se preocupe comigo, $c. Descobri a trama do Martelo do Crepúsculo. Eles têm roubado e estocado explosivos que chegam ao Porto de Ventobravo. De alguma forma, eles têm acesso às catacumbas abaixo da Catedral da Luz. Ouvi rumores de alguém conhecido como "o Bispo Negro."$B$BNão há tempo para avisar a guarda, $n! Você tem apenas alguns minutos para entrar nas catacumbas e desarmar a bomba. Vá já ou CENTENAS DE PESSOAS vão MORRER!', '', '', '', '', '', '', 'O Bispo Negro', '', '', 'Vá até os explosivos nas catacumbas abaixo da Catedral da Luz!', 0),
(27093, 'ptBR', 'Perdido na escuridão', 'Resgate 6 Lobos do Mar Orcs da Penumbra Furtiva.', 'Há quem diga que temos sorte de estarmos vivos. Só um idiota diria isso. Pelo menos, se estivéssemos mortos, não teríamos que enfrentar a ira do Chefe Guerreiro. Bem, o que está feito, está feito! Agora, precisamos recuperar nossa honra perdida.$B$BNosso terceiro navio acaba de afundar na costa de Penumbra Furtiva, a nordeste daqui. Os que conseguiram chegar à praia foram cercados por aranhas gigantes e presos em casulos de teia.$B$BSe houver sobreviventes, precisamos libertá-los! Vá, $n. Para a Penumbra Furtiva!', '', 'Lobo do Mar Orc resgatado', '', '', '', '', '', '', '', 'Fale novamente com a Almirante Machadinha na Retaguarda dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27094, 'ptBR', 'Mais fundo nas trevas', 'Mate a Matriarca Tremeteia.', 'A matriarca tremeteia está por perto! Você pode acabar com a ameaça tremeteia se matar a matriarca!$B$BA mãe da ninhada fica no final da caverna na Penumbra Furtiva. Destrua-a!', '', '', '', '', '', '', 'Matriarca Tremeteia', '', '', 'Fale novamente com o Senhor da Guerra Torok na Retaguarda dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27095, 'ptBR', 'A ameaça das tremeteias', 'Mate 12 Aranhas Tremeteia.', 'A vingança tudo consome, $n! Nosso terceiro navio acaba de afundar na costa de Penumbra Furtiva, a nordeste daqui. Os homens que conseguiram escapar do navio foram capturados ou mortos pelas aranhas tremeteia da região. Por causa disso, essas aranhas vão morrer! TODAS ELAS!$B$BVá para a Penumbra Furtiva e esmague os insetos!$B$BE fique de olho na matriarca delas. Talvez se nós a liquidarmos, possamos acabar com essa ameaça para sempre!', '', 'Aranha Tremeteia morta', '', '', '', '', '', '', '', 'Fale novamente com o Senhor da Guerra Torok na Retaguarda dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27096, 'ptBR', 'Orcs a postos', 'Entregue a Carta de Comenda da Almirante para a Grande Dama Sylvana Correventos no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', '<A almirante Machadinha entrega a você um envelope selado com a marca da Horda.>$B$BEssa é sua carta de comenda. É o mínimo que posso fazer, dadas as circunstâncias.$B$BLeve a carta para a Grande Dama Sylvana Correventos e diga a ela qual a nossa situação. Quero que ela saiba que estamos prontos para marchar assim que ela der a ordem.$B$BAdeus, $n. Você é $gum:uma; excelente soldado.$B$BSiga para nordeste, $grapaz:moça;. Para o Alto Comando dos Renegados!', '', '', '', '', '', '', '', '', '', '', 0),
(27097, 'ptBR', 'Erga-se, Renegado', 'Ressuscite 15 Renegados matando humanos na Ilha de Fenris.', 'A Ilha de Fenris se posta desafiadora no coração do Lago Lordamere... Uma lembrança cruel de um tempo que ficou para trás.$B$BApesar de já não estar infestada de vermes gnoll, uma nova ameaça surgiu. Refugiados humanos, expulsos de suas casas em Eira dos Montes, fugiram para a Ilha de Fenris na esperança de escapar da derrota por nossas mãos. Esse foi um grande erro.$B$BQuero que você leve Ágata para a Ilha de Fenris. Massacrem todos os humanos. Ela ressuscitará os humanos como Renegados, aumentando nossas forças.$B$BNão falhe, $n.', '', 'Renegados ressuscitados', '', '', '', '', '', 'Os humanos terão uma... sobrevida melhor como Renegados.', 'Grande Dama Sylvana Correventos', 'Fale com a Grande Dama Sylvana Correventos no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27098, 'ptBR', 'Lordaeron', 'Acompanhe a Grande Dama Sylvana Correventos até o Sepulcro, que fica na Floresta de Pinhaprata.', 'Cavalgue comigo até o Sepulcro, $n. Tenho muito o que discutir com você. É essencial que você compreenda a história de Lordaeron e o infortúnio dos Renegados.', '', 'Grande Dama Sylvana Correventos acompanhada até o Sepulcro.', '', '', '', '', '', '', '', '', 0),
(27099, 'ptBR', 'Sem saída', 'Encontre a Liderança dos Refugiados dentro do Castelo Fenris.', 'Você deve atacar os líderes, $n. Você os encontrará escondidos no velho castelo. Invada o lugar e encontre-os! Transforme-os para sua rainha!$B$BNinguém escapará ao jugo dos Renegados!', '', 'Líderes Humanos encontrados', '', '', '', '', 'Grande Dama Sylvana Correventos', '', '', 'Apresente-se à Grande Dama Sylvana Correventos no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27100, 'ptBR', 'Pesquisa do Crepúsculo', 'Obtenha 4 Anotações de Pesquisa do Crepúsculo de Gosmas Mercuriais no Alto Pântano de Prata.', 'O livro que você encontrou parece detalhar algum tipo de pesquisa feita por um membro do Martelo do Crepúsculo.$B$BParece que trata de gosmas, mas há muitas páginas faltando.$B$BTalvez seja possível entender a pesquisa se mais páginas forem encontradas.', '', '', '', '', '', '', '', '', '', '', 0),
(27101, 'ptBR', 'A revelação de Maziel', 'Encontre o Diário de Maziel no Baixo Pântano de Prata, que fica no Geodomo.', 'As anotações são a continuação da desconexa pesquisa de Maziel sobre as propriedades do mercúrio e das gosmas mercuriais.$B$BParece que ele fez uma grande descoberta. Maziel menciona ter escondido o diário da pesquisa no Baixo Pântano de Prata, a sudoeste daqui.', '', '', '', '', '', '', '', '', '', '', 0),
(27102, 'ptBR', 'A ascensão de Maziel', 'Mate Maziel dentro da Caverna da Luz Prateada, no Geodomo.', 'O diário de Maziel narra um ritual de ascensão capaz de transfigurar o corpo dele em mercúrio puro.$B$BO ritual seria realizado em uma caverna perto do Baixo Pântano de Prata, onde Maziel se alimentaria de gosmas mercuriais até atingir força total.$B$BTalvez ainda seja possível acabar com essa loucura.', '', '', '', '', '', '', 'Maziel', '', '', '', 0),
(27103, 'ptBR', 'Pedaços de Vinhavil', 'Use o Relicário da Pureza para recolher uma Lasca de Vinhavil.', 'O sátiro Azzin, que atende pela alcunha de o Selvamorfo, estendeu seu rastro de corrupção sobre esta área de Eldre\'Thalas. E o Fruto da Fertilidade, agora corrompido e transformado em Vinhavil, deve estar perto de Azzin. O Fruto pode ser o instrumento para purificar este lugar ancestral.$B$BQuando o grande sátiro cair, recolha toda a essência de Vinhavil que puder e deposite o material no Relicário da Pureza. Sele o recipiente e traga-o para mim.$B$BBoa sorte, e aja com a presteza de Cenarius.', '', '', '', '', '', '', '', '', '', 'Fale com Fungus Lenhatorta.', 0),
(27104, 'ptBR', 'Azzin, o Selvamorfo', 'Mate Zevrim Cascardo e Azzin, o Selvamorfo.', 'O monstro que causou a ruína que você está testemunhando chama-se Azzin, o Selvamorfo. Para chegar até ele, no entanto, você precisará matar Zevrim Cascardo, um sátiro que mantém prisioneiro um nobre anciente chamado Velho Cascaferro.$B$BSe você libertar Cascaferro, ele o ajudará a avançar sobre os domínios de Azzin. Entre lá e mate Cascardo sem misericódia.', '', '', '', '', '', '', 'Azzin, o Selvamorfo', '', '', 'Fale com Fungus Lenhatorta.', 0),
(27105, 'ptBR', 'O penetra', 'Colete a Essência de Rebentágua.', 'Você vai ver que o Gládio Cruel está repleto de elementais arcanos e naturais. Não sei como, mas um elemental da água conseguiu entrar aqui. Por favor, colete a essência do elemental e traga-a para mim. Estou curioso para saber como um ser desses conseguiu entrar aqui, e se por trás disso há algum objetivo escuso contra os elementos naturais de Eldre\'Thalas.', '', '', '', '', '', '', '', '', '', 'Fale com Fungus Lenhatorta.', 0),
(27106, 'ptBR', 'Um vilão desmascarado', 'Desmascare e mate o Major Samuelson na Sala do Trono da Bastilha Ventobravo.', '<Você descobre uma lista completa de todos os sectários do Martelo do Crepúsculo em Ventobravo.>$B$B<Mais importante ainda: você descobre uma carta do major Samuelson aos seus compatriotas explicando todo o esquema. O Príncipe tinha razão: Samuelson é o verdadeiro vilão, usando suas ligações como comandante da guarda da cidade para ocultar essas atividades.>$B$B<Está na hora de voltar para a Bastilha Ventobravo e fazer justiça com Samuelson!>', '', 'Samuelson desmascarado', '', '', '', '', 'Major Samuelson', '', '', 'Fale com o Rei Varian Wrynn na Bastilha Ventobravo, que fica em Ventobravo.', 0),
(27107, 'ptBR', 'Pusillin, o ladrão', 'Convença Pusillin a devolver o Livro de Encantamentos.', 'É só eu tirar soneca mais cedo e diabrete imbecil espertinho pega livro! Dagg\'thol precisa de livro pra obedecer ordens e Amo precisa de livro para fazer conquistas! Gah!$B$BVocê, $Gseu:sua; $r, ajuda a pegar livro de volta de diabrete e eu te dou coisinha brilhante. Vai logo, o diabrete foi para a esquerda! MATA!!!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o "Embaixador" Dagg\'thol.', 0),
(27108, 'ptBR', 'A teia de Letendris', 'Pegue a teia de Letendris.', 'Uma tal elfa sangrenta chamada Letendris tem teia para pegar mágica aqui. É só ela que usa, mas o Amo quer usar também para bem do mundo! Você pega teia de elfa burra e Dagg\'thol te paga bem! E você ainda vai ver que Amo usa teia muito melhor!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o "Embaixador" Dagg\'thol.', 0),
(27109, 'ptBR', 'O defensor tortuoso', 'Mate Gavíneo Lenhatorta.', 'Os Cascaferro e os Lenhatorta já foram os mais poderosos protetores de Eldre\'Thalas. Veja como estão decadentes agora! Em última instância, o destino deles está nas minhas mãos e nas dos outros Altaneiros. Não cuidamos bem do poder que tínhamos, $r. $B$BMas você pode consertar os erros cometidos aqui! Vá até lá e dê um fim a Gavíneo Lenhatorta. Ele foi o último e mais poderoso defensor daquela área e o espírito dele merece descansar. Cuidado: é preciso matar os Protetores Cascaferro antes de enfrentar Gavíneo, pois ele os chamará para ajudá-lo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Vigia Shen\'dralar.', 0),
(27110, 'ptBR', 'A loucura intrínseca', 'Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol\'thar. Quando os pilares se desligarem, o campo de força que cerca Immol\'thar se dissipará.$B$BDestrua o terrível demônio que fica no coração da Prisão de Immol\'thar. Por fim, enfrente o Príncipe Tortheldrin, no Ateneu.$B$BFale novamente com a Anciã Shen\'dralar, no pátio, após completar a missão.', 'Esta loucura precisa acabar. A era dos imortais terminou há tempos. Destrua os guardiões que cercam os cinco pilares para enfraquecer o campo de força. Em seguida, acabe com Immol\'thar. O poder do Príncipe diminuirá muito com o fim do demônio. Aproveite o ensejo e mate-o também. Conceda o descanso eterno aos espíritos desta cidade, $Gaventureiro:aventureira;, e faça com que o Príncipe pague pelos malfeitos.', '', '', '', '', '', '', 'Immol\'thar', '', '', 'Fale novamente com a anciã Shen\'dralar.', 0),
(27111, 'ptBR', 'O tesouro de Shen\'dralar', 'Volte ao Ateneu e encontre o Tesouro de Shen\'dralar. Reclame sua recompensa!', 'Na biblioteca conhecida como Ateneu, há um baú antigo escondido embaixo da escadaria. Retire do baú o que desejar.', '', '', '', '', '', '', '', '', '', '', 0),
(27112, 'ptBR', 'Maldito restolho', 'Mate o Magíster Kalendris e Illyanna Corvalho.', 'Ainda restam duas criaturas aqui que representam uma ameaça direta às nossas intenções de retomar esta cidade sagrada. Tanto o Magíster Kalendris quanto a Illyanna Corvalho são muito perigosos e precisam ser eliminados o mais rápido possível.$B$BTenha muita cautela, pois, como agora os que se alimentam das energias de Immol\'thar são poucos, Kalendris e Illyanna provavelmente estarão mais poderosos do que nunca.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Estulan.', 0),
(27113, 'ptBR', 'A anciã Shen\'dralar', 'Fale com a anciã Shen\'dralar.', 'Algumas criaturas conseguiram miraculosamente se manter a salvo das trevas que vêm se alastrando com rapidez. No segundo andar da Corte dos Altaneiros descansa o espírito de uma anciã Shen\'dralar. Encontre-o. É provável que seja muito sábia e, quiçá, conheça até mesmo o segredo para libertar Eldre\'Thalas.', '', '', '', '', '', '', '', '', '', '', 0),
(27115, 'ptBR', 'O chamado de Teles', 'Fale com Teles Plosivo.', 'Excelente trabalho aqui, $n! Enquanto você estava fora, aquele rapaz, o Teles, passou aqui procurando por você. Ele falou alguma coisa sobre um pássaro de metal.$B$BTalvez seja bom você voltar às margens do Loch para ver o que ele quer.', '', '', '', '', '', '', '', '', '', '', 0),
(27116, 'ptBR', 'Os ventos de Loch Modan', 'Vá até a Estação Algaz a bordo do Navestruz e fale com o Montanhista Lançatroz.', 'Meu pai terminou o navestruz. É um barato! Assim que a gente resolver uns últimos probleminhas, vou usar minha nave para lutar pelos desamparados, assim como você.$B$BEu sei que você tem que ir embora, ajudar outras pessoas, já que é $Gum herói:uma heroína; e tudo mais, mas que tal dar uma voltinha? O navestruz vai voar pela primeira vez, e eu ficaria muito honrado se você me acompanhasse. Eu deixo você na Estação Algaz.$B$BE então? Topa?', '', '', '', '', '', '', '', '', '', '', 0),
(27117, 'ptBR', 'Força bruta', 'Mate o Corvino em Andorhal.', 'Gandling trouxe consigo um de seus tenentes, o Corvino. Esse brutamontes enorme é muito mais perigoso do que qualquer outro Flagelo no seu caminho... mesmo as abominações.$b$bVocê encontrará o Corvino dentro da torre, na parte sul da cidade. Eu recomendo que você tenha cuidado ao enfrentá-lo, $n. Ele não é um adversário qualquer.', '', '', '', '', '', '', 'O Corvino', '', '', 'Fale novamente com Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27118, 'ptBR', 'Armadilha quebrada', '', '', '', '', '', '', '', '', '', '', '', 'Volte até a Armadilha Quedrada nas Montanhas de Alterac.', 0),
(27119, 'ptBR', 'Roupa de Gordok', 'Leve um Tanino Ôgrico para Fiapo Agulhacerta.', 'Para derrotar o rei dos Gordok, você vai ter que passar pelo capitão Kebrapaw. Uma das formas de passar por ele é matá-lo. Mas talvez seja bom deixá-lo vivo.$B$BComo? Acho que eu sei de um jeito! Uma fantasia de ogro!$B$BPosso fazer uma se você me trouxer um Tanino Ôgrico lá de cima. Não dá mesmo para eu ir a lugar nenhum desse jeito...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fiapo Agulhacerta.', 0),
(27120, 'ptBR', 'Roupa de Gordok', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fiapo Agulhacerta.', 0),
(27122, 'ptBR', 'Vai quente porque tá fervendo', 'Mate o Grande Embaixador Fogaçoite e, depois, fale com o Comandante Punhaço em Altaforja.', 'Deixe que os anões Ferro Negro lidem com os filhinhos e mascotes do Ragnaros. Não tenha dúvida de que aqueles insanos do Martelo do Crepúsculo estão por trás disso tudo!$B$BHora de cessar esses ataques contra Altaforja de uma vez por todas. Ah é! Conte ao comandante Punhaço tudo o que aconteceu quando chegamos. Preciso cuidar para que tudo volte a ser como era antes dos ataques.', '', '', '', '', '', '', '', '', '', 'Avise ao Comandante Punhaço em Altaforja sobre a morte do Grande Embaixador Fogaçoite.', 0),
(27123, 'ptBR', 'Geodomo, o reino da terra', 'Monte na Mantícora de Aggra e atravesse a brecha na Voragem. Ao chegar ao outro lado, fale com Maruut Atapedras.', 'Eu sabia que você atenderia ao nosso chamado, $n. Quando, há muito tempo, o Asa da Morte foi derrotado pelos outros Aspectos Dragônicos, ele se recolheu ao Geodomo, o reino da terra.$B$BCom a volta do Asa da Morte, uma brecha foi aberta entre Azeroth e o Geodomo.$B$BE se não fecharmos a abertura, este mundo entrará em colapso.$B$BEstamos fazendo todo o possível para conter os danos deste lado da brecha. E você vai ajudar a consertar o estrago do outro lado. Aggra $Go:a; levará até lá.$B$BPegue a mantícora de Aggra quando estiver $Gpronto:pronta;.', '', '', '', '', '', '', '', '', '', '', 0),
(27124, 'ptBR', 'Negócios pendentes', 'Fale com o Guarda Mol\'dar no Gládio Cruel.', 'Agora você é o rei, então talvez pegue de volta do Guarda Mol\'dar um artefato muito valioso! O outro rei nunca deu valor a ele, e os reis antes dele também não, e isso vai indo até o primeiro rei Gordok!$B$BO artefato é chamado de Manoplas do Poder de Gordok. A lenda conta que só o verdadeiro rei de Gordok vai dar conta de pegar de volta. Então você vai lá, pega elas e fica com manoplas poderosas para sempre! Arr, eu te mostro!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Kebrapaw no Trono dos Gordok, no Gládio Cruel.', 0),
(27125, 'ptBR', 'Rei dos Gordok', 'Mate o Rei Gordok.', 'Na sociedade Gordok, o rei é o guerreiro mais forte e nada mais. Se alguém, ogro ou não, mata o rei, é automaticamente aclamado como novo regente.$B$BO novo rei tem autoridade sobre todos os guardas, o Pisoteador Kreeg e o capitão Kebrapaw. Mate o Rei Gordok e o máximo de líderes que puder, e você não apenas vai receber uma vultosa recompensa como vai poder usar o poder de rei para deter a invasão dos Gordok sem maiores conflitos!', '', '', '', '', '', '', 'Rei Gordok', '', '', 'Fale novamente com o Druida do Gadanho.', 0),
(27126, 'ptBR', 'Entrega urgente', 'Entregue as Peças de Catapulta para Cimo Petráspera no Front Partido, que fica no Geodomo.', 'A catapulta do Cimo Petráspera quebrou em algum lugar da região oeste.$B$BSerá que você poderia fazer alguma coisa, pra variar, e entregar algumas peças para eles, $r?', '', '', '', '', '', '', '', '', '', '', 0),
(27127, 'ptBR', 'Vai quente porque tá fervendo', 'Mate o Grande Embaixador Fogaçoite e, depois, fale com o Guarda-de-sangue Kang em Orgrimmar.', 'Os Ferro Negro? Cho\'gall?! Vamos mostrar a eles o que acontece com quem se vira contra Orgrimmar.$B$BVamos atacar! Lançaremos os corpos desmembrados deles no magma que tanto adoram.$B$BConte ao Guarda-de-sangue Kang o que aconteceu aqui, ok? Não terei tempo para isso, pois preciso organizar a reconstrução da cidade...', '', '', '', '', '', '', '', '', '', 'Informe o Guarda-de-sangue Kang, em Orgrimmar, da morte do Grande Embaixador Fogaçoite.', 0),
(27128, 'ptBR', 'Rei dos Gordok', 'Mate o Rei Gordok.', 'Você mata chefe Gordok, você $Gnovo rei:nova rainha;. Se você $Grei:rainha;, então outros chefes como Kebrapaw e Kreeg te respeitam e você manda parar invasão de Gordok. Se você faz isso, eu fico muito feliz e a gente toma as Gládio Cruel PELA HORDA!!!$B$BVá, $Gpequeno:pequena; $r! Mata o rei ogro bobo e feio e então aqui vai ser novo Acampamento dos Pedramalho! Arr!', '', '', '', '', '', '', 'Rei Gordok', '', '', 'Fale novamente com o Ogro Pedramalho.', 0),
(27129, 'ptBR', 'Fungus Lenhatorta', 'Fale com Fungus Lenhatorta.', 'Dentro da área leste do Gládio Cruel, um dos ancientes lenhatorta, Fungus Lenhatorta, ainda resiste à corrupção. Vá até lá e ajude-o a expulsar as terríveis criaturas que tomaram o lugar para si. O controle do Gládio Cruel é um grande passo em direção à retomada de Feralas.$B$BAs Gládio Cruel ficam a sudeste daqui.', '', '', '', '', '', '', '', '', '', '', 0),
(27130, 'ptBR', 'Fungus Lenhatorta', 'Fale com Fungus Lenhatorta.', 'Dentro da área leste do Gládio Cruel, um dos ancientes lenhatorta, Fungus Lenhatorta, ainda resiste à corrupção. Vá até lá e ajude-o a expulsar as terríveis criaturas que tomaram o lugar antes que voltem as atenções para a Aldeia Mojache. Quem sabe também consigamos convencer Fungus a nos ajudar a manter nossa posição em Feralas, já que inimigos pululam de todos os lados.', '', '', '', '', '', '', '', '', '', '', 0),
(27131, 'ptBR', 'O Altaneiro', 'Fale com Estulan.', 'Estulan, um Altaneiro íntegro e de grande poder, conseguiu entrar na ala oeste do Gládio Cruel e pediu ajuda para expurgá-la do mal. A despeito de suas opiniões pessoais sobre os Altaneiros, tenho que apoiar este pedido pelo bem de Feralas. Que o vento conduza seu espírito até lá com celeridade.$B$BAs Gládio Cruel ficam a sudeste.', '', '', '', '', '', '', '', '', '', '', 0),
(27132, 'ptBR', 'O Altaneiro', 'Fale com Estulan.', 'Estulan, um Altaneiro íntegro e de grande poder, conseguiu entrar na ala oeste do Gládio Cruel e pediu ajuda para expurgá-la. A despeito de suas opiniões pessoais sobre os Altaneiros, devo apoiar este pedido pelo nosso bem. Por favor, apresse-se. Precisamos do máximo de soldados possível em Feralas.$B$BAs Gládio Cruel fica a sudeste.', '', '', '', '', '', '', '', '', '', '', 0),
(27133, 'ptBR', 'De olho no céu', 'Fale com o Druida do Gadanho.', 'A mais terrível e mais organizada ameaça a nós em Feralas são os ogros de Gordok, na área norte do Gládio Cruel. Eu pedi que um druida do Gadanho fosse até lá para fazer as primeiras averiguações. Caso esse batedor ainda esteja vivo, fale com ele, que então liderará você em uma ofensiva para deter Gordok antes que sejamos atacados.$B$BÉ uma ordem, $c.', '', '', '', '', '', '', '', '', '', '', 0),
(27134, 'ptBR', 'Tem ogro na área', 'Fale com o Ogro Pedramalho.', 'A mais terrível e mais organizada ameaça contra nós em Feralas são os ogros Gordok do Gládio Cruel Norte. Se acabarmos com eles e reclamarmos as Gládio Cruel para a Horda, teremos uma base fortemente armada na região e muitos artefatos para facilitar as negociações. Eu já enviei um pequeno destacamento de ogros Pedramalho para lá. Caso algum tenha sobrevivido, fale com ele e termine o serviço.$B$BÉ uma ordem, $c.', '', '', '', '', '', '', '', '', '', '', 0),
(27135, 'ptBR', 'Cadê o combustível?', 'Pegue o Coração Ardente.', 'Beleza, agora a gente precisa de alguma coisa que faça a mistura fazer "BUM"!$B$BA pólvora acabou, mas acho que eu sei de uma coisa pra gente usar no lugar: o coração do meu elemental do fogo!$B$BLeva o meu totem do fogo para a Trilha de Sangue, a leste daqui. Aí é só ligar o interruptor perto de qualquer poço de lava e o Mordamagma vai aparecer rapidinho. Traz o coração dele pra mim pra gente mandar brasa!', '', '', '', '', '', '', 'Mordamagma', '', '', 'Fale novamente com o Iniciado Almada na Bacia de Quartzito, que fica no Geodomo.', 0),
(27136, 'ptBR', 'Energia elemental', 'Destrua 8 Geodos Energizados ou Elementais de Magnetita ao lado do Totem Exaurido.', 'Sem o Pilar, estamos gastando todas as nossas energias para manter o mundo estável.$B$BComo xamãs, podemos beber das energias dos elementais do Geodomo e usá-las para reparar os danos causados pela fenda.$B$BPegue este totem e finque-o no solo, do lado de fora. A energia dos geodos energizados e elementais de magnetita mortos nas proximidades preencherá o artefato com a energia de que precisamos.', '', 'Totem energizado', '', '', '', '', '', '', '', 'Fale novamente com o Vidente Kormo no Templo da Terra, que fica no Geodomo.', 0),
(27137, 'ptBR', 'Nem toda garota terrena é facinha', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27138, 'ptBR', 'Nem toda garota terrena é facinha', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27139, 'ptBR', 'Roberto precisa de você', 'Fale com Roberto Agarramalho na Cidade Portátil, que fica nas Ilhas Perdidas.', 'Opa, $Gchefinho:chefinha;, o Roberto Agarramalho quer falar com você. Ele disse que é urgente.', '', '', '', '', '', '', '', '', '', '', 0),
(27140, 'ptBR', 'Artimanha de Alexei', 'Coloque a Artimanha de Alexei na Sala de Exibição e mate Vectus e Marduk.', 'Preciso de sua ajuda, $c. Quero que você encontre o mago morto-vivo Vectus e o guerreiro Marduque Lagonero nas profundezas deste lugar. Eles são os responsáveis pela criação dos dragões pestilentos para o Flagelo e, por isso, devem morrer.$B$BColoque esta caixa na sala de exibição, e, com sorte, ela reagirá às energias deles e destruirá todos os estudantes na sala.$B$BBem, derrotar Vectus e Marduque depois disso deve ser fácil. Certo?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Alexei Barov.', 0),
(27141, 'ptBR', 'Explosição prematura', 'Ajude Harrison Jones na Tumba de Khartut.', 'Mas que descoberta!$b$bBem aqui... Exatamente onde as minhas notas diziam que estaria.$b$bCom um pouco de sorte, haverá pistas da localização do lendário Baú da Promessa dentro desta câmara.$b$bÉ isso mesmo, $n. Não é só um mito. Acredito que ele exista mesmo.$b$bExplicarei melhor depois. Por enquanto, dê-me uma mão com estes explosivos.', '', 'Harrison, na Tumba de Khartut, ajudado', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Obelisco das Estrelas.', 0),
(27142, 'ptBR', 'O lich, Ras Friomúrmuro', 'Aniquile Ras Friomúrmuro.', 'Um dos alunos de maior confiança de Kel\'Thuzad é o responsável pela supervisão das operações em Scolomântia. Você precisa ir até lá e matar Ras Friomúrmuro em sua câmara ao lado sala de observação.$B$BAniquile-o, $n, e não deixe traços da existência deste monstro que espalhou horror pelo nosso mundo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Alexei Barov.', 0),
(27143, 'ptBR', 'A fortuna da família Barov', 'Recupere a Escritura de Castro das Flechas, a Escritura de Montalvo, a escritura da Serraria Tarren e a escritura de Costa Sul.', 'Dentro de Scolomântia encontra-se a fortuna da família Barov, e Alexei e eu somos os dois últimos Barov vivos. Quer dizer, EU sou o último Barov realmente vivo, o que significa que todo o vasto império da nossa família pertence a mim!$B$BEncontre as escrituras de Castro das Flechas, Montalvo, Serraria Tarren e Costa Sul, que lhe darei uma generosa recompensa ao entregá-las a mim. O império dos Barov finalmente renascerá!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Weldon Barov.', 0),
(27144, 'ptBR', 'O ajuste de contas', 'Fique ao lado da Grande Dama Sylvana Correventos enquanto ela fala com Koltirus Tecemorte.', 'Você agiu de forma admirável, soldado. Você deixou os Renegados orgulhosos, o que é mais do que eu posso dizer sobre nosso general, Koltirus Tecemorte.$b$bEu pretendo ter uma conversa com aquele cavaleiro da morte. Ele envergonhou a si mesmo e à nossa causa.', '', 'Testemunhar Ajuste de Contas', '', '', '', '', '', '', '', 'Fale novamente com a Grande Dama Sylvana Correventos em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27145, 'ptBR', 'Filhotes pestilentos... por pouco tempo', 'Mate 10 Filhotes Pestilentos e Ossorrange.', 'Um dos "projetos" em andamento aqui é o da revoada dragônica pestilenta. Embora ainda sejam filhotes, logo se tornarão as mais poderosas armas do flagelo e uma terrível ameaça para Azeroth!$B$BPrincipalmente para minha família e eu. Mate dez dragonetes e acabe com Ossorrange. Ele se encontra em uma pequena sala abaixo, onde prepara complementos catalisadores para a evolução dos filhotes. Apresse-se... antes que cresçam!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Weldon Barov.', 0),
(27146, 'ptBR', 'Doutor Theolen Krastinov, o Carniceiro', 'Aniquile o Doutor Theolen Krastinov e depois queime os Restos Mortais de Eva Sarkhoff e os Restos Mortais de Lucien Sarkhoff.', 'O Doutor Theolen Krastinov é responsável por milhares de mortes. Seu apelido, o Carniceiro, reflete bem as atrocidades que cometeu. Ele precisa ser punido. É preciso fazer justiça!$B$BEncontre-o e faça-o pagar pela agonia causada a todos os inocentes, inclusive meu marido e eu. Após destruí-lo, queime nossos restos mortais, $n. Traga paz para nossas almas angustiadas.', '', '', 'Restos Mortais de Eva Sarkhoff queimados', 'Restos Mortais de Lucien Sarkhoff queimados', '', '', '', '', '', 'Fale novamente com Eva Sarkhoff.', 0),
(27147, 'ptBR', 'Kirtonos, o Arauto', 'Aniquile Kirtonos.', 'Com sangue, Kirtonos pode ser evocado. E é com sangue, então, que Kirtonos deve ser destruído.$B$BNa Câmara de Evocação, você irá encontrar um braseiro, no qual deverá colocar um gota de seu próprio sangue. Kirtonos não resistirá. Quando ele aparecer, vingue a morte de milhares de inocentes.$B$BCaso seja bem-$Gsucedido:sucedida;, não receberá apenas gratidão como recompensa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Eva Sarkhoff.', 0),
(27148, 'ptBR', 'Férias prolongadas', 'Mate o Umbromestre Gandling.', 'O Umbromestre Gandling é o diretor de Scolomântia responsável por todas as mortes que seus alunos causaram e, por isso, deve ser punido.$B$BEle não se mostrará facilmente. Mate os seis professores das salas conectadas ao Gabinete do Diretor. Quando o último morrer, ele virá, mas, tome cuidado, pois Gandling estará furioso e usará todo o arsenal mágico que possui em seu ataque. Não permita que ele saia vivo.', '', '', '', '', '', '', 'Umbromestre Gandling', '', '', 'Fale novamente com Lucien Sarkhoff.', 0),
(27151, 'ptBR', 'O legado de Taelan Fordring', 'Mate 10 Gatunos Pinhorrubro.', 'Saudações. Como vai você, viajante? Meu nome é Daria.$b$bEu sou uma das sacerdotisas encarregadas de manter a paz aqui em Amparo. Um dos meus deveres envolve a manutenção da torre que fica no final da trilha a sudeste de Amparo. Essa torre tem uma importância especial para o grão-lorde. É o lugar onde o filho dele foi morto.$b$bMas, com as recentes incursões de gnolls, a manutenção da torre se tornou extremamente difícil. Você poderia me ajudar a limpar a trilha desses vândalos para que eu possa fazer o meu trabalho?', '', '', '', '', '', '', '', 'Desculpe, espero que não se importe se eu usar o feitiço Visão da Mente em você.', 'Daria Lorena', 'Fale novamente com Daria Lorena em Amparo, que fica nas Terras Pestilentas Ocidentais.', 0),
(27152, 'ptBR', 'Comportamento incomum... mesmo para gnolls', 'Investigue o esconderijo de gnolls ao lado da trilha para Amparo, nas Terras Pestilentas Ocidentais.', 'Deixe que eu me concentre por um instante. $b$b<Você sente a Visão da Mente de Daria viajar para outro lugar. Depois, ela retorna para você.>$b$bMais para baixo na trilha, ao sul da Torre de Taelan, os gnolls abriram uma pequena clareira, a leste da estrada principal. Alguma coisa está acontecendo por lá... Eu não sei exatamente o quê. Nós devemos investigar. Eu vou procurar alguma coisa fora do normal. Você só precisa se proteger.', 'Acampamento gnoll investigado', '', '', '', '', 'Acampamento gnoll investigado', 'Daria Lorena', 'Você está vendo aquilo? Aquela garrafa, aqueles suprimentos, no chão!', 'Daria Lorena', 'Fale novamente com Daria Lorena em Amparo, que fica nas Terras Pestilentas Ocidentais.', 0),
(27153, 'ptBR', 'O bom povo de Amparo', 'Fale com Morris Vant, Provedor Mendelev, Bia Raçaférrea e Alto-clérigo Álphus dentro de Amparo.', 'Você está vendo aqueles reagentes ali? E esses suprimentos aqui perto? Eles pertencem à Cruzada Argêntea.$b$bGnolls são conhecidos como ladrões, mas que eu saiba, Amparo não sofreu nenhuma incursão desde que os Pinhorrubro chegaram. Isso é muito suspeito.$b$bEu conheço algumas pessoas dentro de Amparo: o Morris Vant, o Provedor Mendelev, a Bia Raçaférrea e o Alto-clérigo Álphus. Todos são confiáveis e são muito bem conectados. Interrogue-os e descubra se eles sabem de alguma coisa sobre esses suprimentos perdidos.', '', 'Falar com Morris Vant', 'Falar com Provedor Mendelev', 'Falar com Bia Raçaférrea', 'Falar com Alto-clérigo Álphus', '', 'Daria Lorena', 'Bisp é o nosso homem.', 'Daria Lorena', 'Fale novamente com Daria Lorena em Amparo, que fica nas Terras Pestilentas Ocidentais.', 0),
(27154, 'ptBR', 'Encurralando Bisp', 'Fale com Magus Bisp no alto da torre dos magos, em Amparo.', 'O Magus Bisp é um dos arcanistas mais importantes de Amparo. E pensar que ele está interagindo com gnolls, flertando com a necromancia... Inimaginável.$b$bMagus Bisp está no alto da torre próxima ao portão principal de Amparo. Talvez ele tenha uma explicação para tudo isso. Se não... bem, neste caso, eu só subiria naquela torre muito bem preparada, $n.', '', 'Magus Bisp "questionado"', '', '', '', '', 'Daria Lorena', 'Bisp, gnolls e necromancia... caramba.', 'Daria Lorena', 'Fale novamente com Daria Lorena em Amparo, que fica nas Terras Pestilentas Ocidentais.', 0),
(27155, 'ptBR', 'Se entregando', 'Apresente-se ao Grão-lorde Tirion Fordring em Amparo, que fica nas Terras Pestilentas Ocidentais.', 'Então... você matou um membro da Cruzada Argêntea dentro de Amparo. Normalmente isso não é muito bem visto, mesmo em defesa própria.$b$bEu recomendo que você vá para a Bastilha Mardenforte e se entregue ao grão-lorde Fordring. Com sorte, ele ouvirá a sua história e entenderá a sua situação. Eu espero não ter causado nenhum problema para você.', '', '', '', '', '', '', 'Daria Lorena', '', '', 'Apresente-se ao Grão-lorde Tirion Fordring em Amparo, que fica nas Terras Pestilentas Ocidentais.', 0),
(27156, 'ptBR', 'Já era hora!', 'Desafie e derrote 7 Aprendizes de Amparo.', 'Finalmente! Você chegou! Vá trabalhar!$b$bMeus homens estão lutando com esses bonecos de madeira há tempo demais. É claro que você pode aprender a atacar com uma espada batendo em um boneco, mas combate de verdade precisa de combatentes de verdade.$b$bHummm... Eu pedi a eles que mandassem alguém imponente, mas parece que vamos ter que nos virar com $gum:uma; $r $c de braços finos.$b$bAgora entre lá e mostre aos meus homens como se luta!', '', 'Aprendizes de Amparo desafiados e derrotados', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Minairo em Amparo, que fica nas Terras Pestilentas Ocidentais.', 0),
(27157, 'ptBR', 'Peões... <suspiro>', 'Mate Shadril dentro da mina de Amparo.', 'Ei, você... eu não lembro seu nome. $n? Prazer em conhecê-l$go:a;, $n.$b$bEu tenho um problema pra resolver e você tem aquela cara de quem está louc$go:a; pra resolver problemas dos outros.$b$bTem uma mina ao norte de Amparo de onde extraímos a maior parte do minério de que a cidade precisa. Os meus peões, que trabalham na mina, normalmente fazem um trabalho razoável.$b$bO problema é que recentemente uma aranha enorme resolveu morar na caverna. Você acha que pode resolver isso pra mim?', '', '', '', '', '', '', 'Shadril', '', '', 'Fale novamente com o Tenente Minairo em Amparo, que fica nas Terras Pestilentas Ocidentais.', 0),
(27158, 'ptBR', 'A batalha por Andorhal', 'Apresente-se a Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 'Corra, $n... não temos tempo a perder.$b$bA cidade de Andorhal está no meio de uma guerra tríplice entre os Renegados, a Aliança e o Flagelo. O rei Wrynn pagou para ver ao enviar um cavaleiro da morte para liderar o ataque em prol da causa dele, mas tenho certeza de que toda ajuda será bem-vinda. Com a morte de Arthas, é chegada a hora da Aliança retomar Lordaeron.$b$bFale com o mestre de voo, Bibilfaz Penapita, quando estiver pront$go:a;. Ele colocará você no primeiro grifo a caminho de Andorhal.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27159, 'ptBR', 'O Flagelo primeiro... Depois a Horda', 'Mate 15 Flagelos Ressequidos dentro de Andorhal.', 'O umbromestre Gandling, da Seita dos Malditos, lidera a ofensiva do Flagelo aqui em Andorhal. Meu antigo companheiro, Koltirus, irá liderar as forças dos Renegados. Para conquistar Andorhal, nós teremos que derrotar ambos, mas certamente falharemos se tentarmos enfrentar os dois ao mesmo tempo.$b$bEu conheço Koltirus bem o suficiente para saber que ele irá focar o ataque contra o Flagelo primeiro. Nós faremos o mesmo.$b$bAcabaremos com os Flagelos mais fracos e ressequidos para diminuir suas forças. Os Renegados terão que esperar um pouco mais para provar da nossa ira.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27160, 'ptBR', 'Máquinas de guerra', 'Destrua 6 Beemotes Tripaberta em Andorhal.', 'Flagelos ressecados... fracos. Abominações... fortes.$b$bNós derrotamos abominações, nós vencemos guerra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lúrido em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27161, 'ptBR', 'O fluxo interminável', 'Use as Granadas de Mão do Lango para matar 5 Berserkers Espetosso e destruir um Animus dos Ossos do Flagelo.', 'Araj, o Evocador, está aumentando as defesas do Flagelo com esqueletos simples... um exército de criaturas fracas que são mais capazes de te soterrar do que de vencer propriamente. Ele estocou animi nas torres norte de Andorhal e elas ficam produzindo esqueletos em um ritmo incessante. Mas eu tenho uma solução!$b$b<O Lango entrega um punhado de granadas para você.>$b$bO objetivo é simples. Jogar essas granadas em um animus de ossos... ou, se a oportunidade aparecer, no meio de uma multidão de esqueletos... isso irá reduzi-los a farelos.', '', 'Animus dos Ossos do Flagelo destruído', '', '', '', '', '', '', '', 'Fale novamente com Lango Manfurada em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27162, 'ptBR', 'Scolomantiano', 'Mate o Umbromestre Gandling em Andorhal.', 'Scolomântia é uma das poucas fortalezas a oeste do Thondroril que ainda permanecem sob controle do Flagelo. O chefe da Scolomântia, um sectário conhecido como Umbromestre Gandling, apareceu no campo de batalha.$b$bEsse foi o último erro que ele cometeu.$b$bVocê encontrará Gandling em uma praça perto da parte sul da cidade. Eu quero que você lute contra ele e o enfraqueça. Eu irei me juntar a você para acabar com ele.', '', 'Umbromestre Gandling morto', '', '', '', '', 'Umbromestre Gandling', '', '', 'Fale novamente com Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27163, 'ptBR', 'Força bruta', 'Mate o Ossorrange em Andorhal.', 'Gandling trouxe consigo um de seus tenentes, o Ossorrange. Esta criatura deformada é muito mais perigosa do que qualquer outro Flagelo no seu caminho... mesmo as abominações.$b$bVocê encontrará o Ossorrange dentro do antigo prédio da prefeitura, perto do centro da cidade. Recomendo que você tenha cuidado ao enfrentá-lo, $n. Ele não é um adversário qualquer.', '', '', '', '', '', '', 'Ossorrange', '', '', 'Fale novamente com Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27164, 'ptBR', 'Araj, o Evocador', 'Mate Araj, o Evocador. Você pode usar as Granadas de Mão do Lango para destruir os Berserkers Espetosso.', 'Depois de destruir o animus, nosso próximo passo lógico é acabar com o próprio Araj e pegar um pedaço do filactério dele. Você provavelmente já o viu espreitando próximo à fonte no meio da cidade.$b$bLeve essas granadas pra você. Elas não vão adiantar nada contra o Araj, mas se ele resolver evocar aqueles esqueletos, você pode usá-las para explodir eles em pedacinhos. Outra vez.', '', '', '', '', '', '', 'Araj, o Evocador', '', '', 'Fale novamente com Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27165, 'ptBR', 'Vitória, por enquanto.', 'Apresente-se ao Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.', 'A Aliança saiu vitoriosa, e nossas tropas continuam fortalecidas. A estratégia militar clássica reza que devemos atacar os Renegados agora, enquanto eles estão se recuperando, desarmados. Mas eu fiz um acordo... $b$bVamos esperar. Atacaremos Koltirus e suas tropas no devido tempo. Enquanto isso, fale com Gina Boaventura e pegue um voo para o Acampamento Ventogelante, ao sul. O Comandante Ashlam Punhobom lhe dará sua próxima missão.$b$bMandarei avisar quando eu precisar novamente de você em Andorhal.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.', 0),
(27166, 'ptBR', 'Vá flechar!', 'Obtenha 9 Cálamos de Penaparda', 'Nós temos que estar prontos para o combate, $n. Não importa se é contra os Renegados em Andorhal, contra o Flagelo a leste daqui ou contra qualquer inimigo ainda não declarado. Nossa única certeza é que temos que ficar sempre a postos.$b$bEstamos com poucas flechas. Eu consigo arranjar as hastes e as pontas, mas preciso de penas. A muda dos pássaros desta região costuma ser por esta época. Você poderia procurar algumas penas para o nosso acampamento?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.', 0),
(27167, 'ptBR', 'Uma fome violenta', 'Obtenha 5 Picanhas de Urso de Ursos Pretos Desgrenhados nas Terras Pestilentas Ocidentais.', 'Eu venho do Cerro Oeste, do sul longínquo, assim como esses homens que me seguem... Nós somos simples fazendeiros.$b$bFoi-nos dito que Lordaeron havia sido curada e que estaria pronta para ser arada. No entanto, esse tal "comandante" acaba de nos dizer que é muito perigoso seguir em frente. Ele disse que há uma guerra acontecendo e que as terras pestilentas ainda não foram curadas.$b$bAntes de mais nada, eu preciso de um pouco de comida para encher a barriga dos meus homens. Qualquer coisa vai servir. Os ursos são bem abundantes nessa região.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Anton DeGrandis no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.', 0),
(27168, 'ptBR', 'Aqueles que não puderam partir', 'Use o Turíbulo Sagrado em 12 Almas Recolhidas na Colina do Pesar. Mate-as se elas reagirem de forma negativa.', 'A Colina do Pesar, subindo a estrada a nordeste, foi um dos primeiros locais que a Cruzada Argêntea e o Círculo Cenariano conseguiram curar. A área agora está livre do Flagelo.$b$bNo entanto, ainda há muitos espectros do passado que, por algum motivo, não conseguiram partir para o outro mundo. Talvez estejam de luto, talvez tenham assuntos inacabados... talvez estejam terrivelmente perdidos.$b$bLeve meu turíbulo e use-o para defumá-los com incenso sagrado. De um jeito ou de outro, nós os ajudaremos a partir para o outro plano.', '', 'Alma Recolhida libertada', '', '', '', '', '', '', '', 'Fale novamente com a Alta-sacerdotisa Donélia no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.', 0),
(27169, 'ptBR', 'A bênção de Uther', 'Entre na Tumba de Uther e use a Homenagem de Ventogelante em frente à estátua dele.', 'Os fazendeiros do sul querem retomar essas fazendas, mas eu não posso deixar que eles entrem nas terras pestilentas despreparados. Mesmo com o Flagelo expulso, os Renegados ainda representam uma ameaça. Não, nós precisamos estar prontos para lutar... inclusive com nossos novos visitantes.$b$bMas, antes de qualquer coisa, sugiro que você viaje até a Tumba de Uther a leste daqui, ofereça uma homenagem a ele e peça uma bênção. Fale com um dos sacerdotes que cuidam da tumba quando você tiver terminado.', '', 'A bênção de Uther', '', '', '', '', 'Uther, o Arauto da Luz', '', '', 'Fale com o Sumo Sacerdote Thel\'danis na Tumba de Uther, que fica nas Terras Pestilentas Ocidentais.', 0),
(27170, 'ptBR', 'A cripta abandonada', 'Encontre o Caixote de Armas no último andar da Cripta da Colina do Pesar, que fica nas Terras Pestilentas Ocidentais.', 'Se vocês realmente desejam seguir em frente com essa batalha por Andorhal... Bem, acho que posso ajudar.$b$bA leste daqui, fica uma grande cripta. O andar mais baixo da cripta foi usado no passado para estocar armas e armaduras... até a chegada do Flagelo. Agora que os mortos-vivos se foram, as armas podem ser recuperadas.$b$bA maioria provavelmente está enferrujada e podre, mas, ainda assim, servirão melhor do que túnicas e ancinhos.', '', '', '', '', '', '', '', '', '', 'Encontre o Caixote de Armas no último andar da Cripta nas Terras Pestilentas Ocidentais.', 0),
(27171, 'ptBR', 'Emboscado!', 'Pegue 4 Peitorais Gastos pelo Tempo e 4 Espadas Enferrujadas.', 'Ao virar, você se depara com a silhueta de esqueletos descendo as escadas.$b$bOs mortos-vivos não se foram dessa cripta. Eles estavam escondidos, esperando! Além disso, eles parecem estar armados com os equipamentos que você estava procurando.$b$bVocê terá que fugir da cripta. No caminho, tente pegar o máximo de equipamento que puder.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.', 0),
(27172, 'ptBR', 'O Antro Repelente', 'Leve as Armas e Armaduras Desgastadas para Anton DeGrandis no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.', 'Os fazendeiros viajaram para o Antro Repelente, uma antiga fazenda a nordeste daqui, do outro lado do rio. Alguém precisa ficar de olho neles.$b$bLeve para eles essas armas e armaduras enferrujadas que você encontrou. Nós não podemos deixá-los lutar com ancinhos.', '', '', '', '', '', '', '', '', '', 'Fale com Anton DeGrandis no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.', 0),
(27173, 'ptBR', 'Este é o nosso exército', 'Mate 10 Pioneiros Renegados.', 'Eu disse ao Comandante Punhobom que nós poderíamos nos virar sozinhos e é isso que vamos fazer. Conversei com o general cavaleiro da morte Thassarian no caminho para cá. Nós, fazendeiros, pretendemos ajudar do nosso próprio jeito.$b$bNós tomaremos o controle dessa fazenda, começaremos a cultivar a terra... e quando a batalha por Andorhal começar, nós atacaremos os Renegados por trás. Eles não estarão preparados para isso.$b$bMas, primeiro, precisamos nos livrar desses Pioneiros Renegados. Mate alguns deles e volte pra cá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Anton DeGrandis no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.', 0),
(27174, 'ptBR', 'Treino de combate', 'Fale com o Gangrena no Antro Repelente e o desafie para um combate.', 'Na verdade, talvez você ainda possa ajudar a treinar meus homens. Você deve ter visto a abominação lá fora. Nós tentamos atacá-la assim que chegamos, mas ela não reagiu. Ela parece estar querendo ajudar na fazenda.$b$bPegue um grupo de quatro homens e desafie a abominação para o combate. Ela parece bem forte, mas com cinco de vocês contra ela sozinha, eu acho que vocês têm chance de vencer.', '', 'Gangrena derrotado', '', '', '', '', '', '', '', 'Fale novamente com Anton DeGrandis no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.', 0),
(27175, 'ptBR', 'Acampamento dos Restauradores', 'Apresente-se ao Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 'Esses homens e mulheres no Acampamento Ventogelante têm objetivos nobres, mas o caminho deles é a guerra. Eu gostaria de oferecer-lhe a oportunidade de buscar objetivos mais pacíficos.$b$bNo Acampamento dos Restauradores, que fica além da parte de Andorhal destruída pela guerra ao norte, a Cruzada Argêntea se uniu ao Círculo Cenariano. Juntos, eles desejam curar esta terra da praga que costumava dominar essa região.$b$bVocê está interessad$go:a; em se juntar à nossa causa, $c?', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(27176, 'ptBR', 'Só a pontinha', 'Obtenha o Cajado do Sultão e, então, use o Disco Sofisticado para criar o Cajado das Estrelas.', 'As gravuras em torno da superfície deste objeto indicam que ele é de origem ancestral, mas sinal algum de desgaste pode ser detectado.$b$bUm buraco na beirada, cheio de farpas, indica que foi feito para ser encaixado em algum tipo de lança de madeira.$b$bAntes de mostrar esta descoberta ao doutor Jones, você parte em busca da parte desaparecida do equipamento.', '', '', '', '', '', '', 'Sultão Oogah', '', '', 'Leve o Cajado das Estrelas para Harrison Jones no Obelisco das Estrelas.', 0),
(27177, 'ptBR', 'Operação de resgate', 'Colete 8 Suprimentos Recuperados dos Caixotes Encharcados nas Quebradas Obsidianas.', 'Entre a Horda e as nagas, nossa frota foi derrubada. Não podemos fazer nada para trazer de volta os homens que perderam as vidas no mar, mas me afogue se eu permitir que nossos suprimentos se percam para sempre.$B$BVá nadando para as Quebradas Obsidianas, a sudoeste de Beiralta, e recupere nossos suprimentos nos destroços que estão no leito do oceano.', '', '', '', '', '', '', '', '', '', 'Leve os Suprimentos para Simão Candelária em Beiralta, que fica no Planalto do Crepúsculo.', 0),
(27178, 'ptBR', 'Reforços naga', 'Mate 10 Mirmidões Escamanegra ou Arautos do Mar Escamanegra.', 'As nagas vieram serpenteando pelas profundezas do oceano, $n. A intenção delas, creio, seja reforçar o Bastião do Crepúsculo, provavelmente invadindo as terras através do rio Verrall. Não podemos permitir isso!$B$BDeixe bem claro que a orla nos pertence e escorrace as nagas de volta para o breu das profundezas.$B$BMate as nagas Escamanegra que vêm rastejando pelas Quebradas Obsidianas!', '', 'Naga Escamanegra morta', '', '', '', '', '', '', '', 'Fale novamente com Simão Candelária em Beiralta, que fica no Planalto do Crepúsculo.', 0),
(27179, 'ptBR', 'Trabalho de campo', 'Colete 10 Fragmentos de Tabuleta Ancestral.', 'Este pigmeu desafortunado estava no lugar errado na hora errada.$b$bEnquanto você reflete sobre a falta de sorte dele, os símbolos que cobrem o escudo que ele usava chamam a atenção – são elaborados demais para os rabiscos dos pigmeus.$b$bCert$go:a; de que o doutor Jones se interessará por tais objetos, você parte em busca de mais fragmentos como este.', '', '', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Obelisco das Estrelas.', 0),
(27180, 'ptBR', 'Em honra aos mortos', 'Colete 6 Insígnias dos Renegados dos cadáveres dos Soldados Renegados Veteranos.', 'Um comboio de veteranos e catapultas dos Renegados foi emboscado hoje mais cedo ao tentar atravessar a Miséria de Olsen, diretamente a sul daqui. Nada se salvou: todos os soldados foram mortos e as catapultas foram destruídas.$B$BA matilha de Dentessangue foi a responsável pela emboscada. Muito provavelmente eles já fugiram de volta para as colinas para se preparar para o próximo ataque covarde. O dia deles vai chegar, mas por ora eu quero que você vá até a Miséria de Olsen e honre nossos soldados tombados.$B$BRecupere as insígnias dos Renegados de nossas tropas.', '', '', '', '', '', '', '', '', '', 'Fale com a Grande Dama Sylvana Correventos no Sepulcro, que fica na Floresta de Pinhaprata.', 0),
(27181, 'ptBR', 'Limpando a mácula', 'Mate 10 Espreitadores Dentessangue.', 'Parece que um grupo dos emboscadores acabou ficando pra trás. Mate todos os espreitadores Dentessangue na Miséria de Olsen. Por Sylvana! Pela Horda!!!', '', '', '', '', '', '', '', 'Aqueles cães em breve pagarão caro pela arrogância!', 'Grande Dama Sylvana Correventos', 'Fale com a Grande Dama Sylvana Correventos no Sepulcro, que fica na Floresta de Pinhaprata.', 0),
(27182, 'ptBR', 'O ermitão do Morro das Bruxas', 'Fale com Zé "Olho de Lama", no Casarão do Pantanal Iluminado.', 'O pântano parece ter um efeito estranho sobre humanos. Alguns ficam loucos só de viver aqui.$B$BTodos que já se estabeleceram no Casarão do Pantanal Iluminado enlouqueceram de maneira notável. O atual proprietário, Zé "Olho de Lama", já está mostrando os sinais.$B$BNão sei o que se passa por lá e, se você descobrir, vou lhe agradecer muito.$B$BO casarão fica na extremidade leste do pântano. Siga a borda leste através da Charneca Azul, e depois da Torre Norte. O casarão fica em uma área assombrada conhecida como o Morro das Bruxas.', '', '', '', '', '', '', '', '', '', '', 0),
(27183, 'ptBR', 'Pernas de sapo do pântano', 'Colete 10 Pernas de Sapo do Pântano dos Sapos Gigantes do Pântano.', 'Eu gosto de cozinhar. A boa e velha cozinha do pantanal. Perna de sapo verde frita, esse tipo de coisa.$B$BMinhas pernas de sapo acabaram. Mas o casarão tá infestado deles. Sapos gigantes do pântano. Acha que consegue me arrumar umas perninhas? É mole. É só cacetar eles na cabeça e me trazer as pernas.$B$BVou fazer um ensopado, cozinhar e secar um pouco, daí te dou um cadinho também.$B$BVocê gosta de ensopado?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zé "Olho de Lama" no Casarão do Pantanal Iluminado, que fica no Pântano Vadeoso.', 0),
(27184, 'ptBR', 'Zé "olho em falta"', 'Colete 20 Olhos Névoa Negra Inteiros das aranhas Névoa Negra.', 'Suco de olho é ótimo pra beber. É uma pena que a maioria dos bichos só tenha um par de olhos.$B$BMas as aranhas têm um bocado. Um bom bocado. E o suco de Névoa Negra é gostosíssimo. Suave e salgadinho! As bolinhas dos olhos redondinhas... Dá pra imaginar que o nome das aranhas é esse por causa da caverna... ou é o contrário?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zé "Olho de Lama" no Casarão do Pantanal Iluminado, que fica no Pântano Vadeoso.', 0),
(27185, 'ptBR', 'Eliminando a concorrência', 'Mate o Marteleiro Reanimado.', 'Olha, não vou ficar de brincadeiras com você. O marteleiro Carmesim, da Cruzada Escarlate, não costumava ser grande coisa, mas agora que virou um Reanimado, aprendeu a forjar os mais diversos tipos de armas demoníacas com o senhor do medo Balnazzar.$B$BO negócio é o seguinte: encontre as instruções de ferraria do Marteleiro Reanimado. Ele virá tomar de volta, e então mate ele. Assim vamos garantir que seus exércitos não coloquem as mãos nesses armamentos demoníacos. Eles já são poderosos demais sem eles!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Artesão Wilhelm.', 0),
(27186, 'ptBR', 'Zé precisa de uma lâmina', 'Obtenha a Espada de Cortaspinha.', 'Preciso cortar umas coisas... Não posso dizer o que é, mas... Tô precisado de uma lâmina. É uma lâmina que é...$B$BBom, eles dão o nome de espada. Eu chamo de aparador de grama.$B$BVocê vai me ajudar? Esses homens-peixe, sabe, murlocs ou alguma coisa assim... Tem um chamado Cortaspinha que tem uma espadona. Ele vive ao norte, perto da praia. É dessa espada que eu preciso!$B$BMas não vai demorar, hein?! Tenho que cortar essa coisa e não tô por sua conta...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zé "Olho de Lama" no Casarão do Pantanal Iluminado, que fica no Pântano Vadeoso.', 0),
(27187, 'ptBR', 'Faça um favor ao mundo', 'Mate 12 Hienas Sarnentas.', 'Hienas são, no melhor dos casos, um estorvo.$b$bEsses espécimes abomináveis têm uma disposição particularmente sórdida, carregam toda sorte de doenças e, simplesmente, são uma vergonha para os demais canídeos.$b$bFaça um favor ao mundo e livre os desertos de Uldum desta ameaça sarnenta.', '', 'Hienas Sarnentas erradicadas', '', '', '', '', 'Hiena Sarnenta', '', '', '', 0),
(27188, 'ptBR', 'Que é que assombra o Morro das Bruxas?', 'Consiga informações derrotando 10 Carcaças Moventes ou Espíritos Revividos.', 'Vim de longe para visitar o Zé e conhecer sua nova casa, mas a viagem tem sido um show de horrores interminável! Tem alguma coisa muito errada aqui e não é possível que só eu esteja vendo...$B$BVocê viu os fantasmas e cadáveres se arrastando pelo Morro das Bruxas? Tenho um pressentimento de que eles devem saber o que está acontecendo por aqui. Procure as carcaças moventes e os espíritos revividos nas proximidades e os leve o descanso eterno pelo caminho da espada ou da magia e veja o que consegue aprender com eles, antes que o mal consuma o Zé!', '', 'Informações obtidas', '', '', '', '', '', '', '', 'Fale novamente com o Mordente Tenúbrio no Casarão do Pantanal Iluminado, que fica no Pântano Vadeoso.', 0),
(27189, 'ptBR', 'A ruína da bruxa', 'Colete 9 talos de Espanta-bruxa nas proximidades do Morro das Bruxas.', 'Em todos esses anos como herborista, várias vezes vi a natureza prover curas sublimes aos mais abissais dos problemas. Li que magos autodidatas e mandingueiros costumam usar a fumaça de uma erva chamada espanta-bruxa para revelar e expurgar o mal.$B$BSe isso for verdade, significa, então, que há espanta-bruxas crescendo perto das águas rasas do Morro das Bruxas. É possível identificá-las pelas folhas largas e pelo talo avermelhado. Traga-me o tanto que encontrar da erva, $n. Ele pode ser nossa única esperança.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mordente Tenúbrio no Casarão do Pantanal Iluminado, que fica no Pântano Vadeoso.', 0),
(27190, 'ptBR', 'A expurgação do Morro das Bruxas', 'Coloque a Tocha de Espanta-bruxa no fim da doca e derrote o mal que assombra o Morro das Bruxas.', 'A tocha está pronta. Coloque-a no fim da doca e prepare-se para enfrentar o que aparecer.$B$BNão faço ideia do que a fumaça revelará – caso alguma coisa realmente emerja das águas. Admito que não confio muito nessas simpatias, mas não temos tempo para preparar outra coisa. Pelo seu bem e pelo bem de Zé, desejo-lhe sorte.', '', 'Morro das Bruxas expurgado', '', '', '', '', '', '', '', 'Fale novamente com o Mordente Tenúbrio no Casarão do Pantanal Iluminado, que fica no Pântano Vadeoso.', 0),
(27191, 'ptBR', 'Uma fome de ogro!', 'Colete 8 Cabeças de Lamapina dos Murlocs Lamapina.', 'A gente faz amizade fácil aqui e conhece muita gente bacana. Conheci um ogro uma vez. Os ogros ficam famintos que nem eu.$B$BNunca vou esquecer o que ele falou. Foi assim: "Barrão é ogrão. Mim com fome. Ocê pescá pêxe. Trazê pêxe pra Barrão. Ocê dá cumida pra Barrão ou Barrão cômi ocê."$B$BDaí eu levei os peixes pra ele e ele mandou goela abaixo. E foi aí que eu comecei também. A cabeça é a melhor parte, bem molhadinha.$B$BNão vai amassar as cabeças, hein?! Deixa elas com uma cara triste. E não é bom comer cara triste. Me traz umas caras felizes, daí eu vou comer e ficar feliz também.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zé "Olho de Lama" no Casarão do Pantanal Iluminado, que fica no Pântano Vadeoso.', 0),
(27192, 'ptBR', 'A tentação de Fras Siabi', 'Recupere uma caixa do Tabaco da Lata do Fras Siabi.', 'O tabaco da lata do Fras Siabi é famoso até em Kul Tiraz. A iguaria era apreciada por todas as pessoas importantes que visitavam Stratholme: o rei Terenas; Uther, o Arauto da Luz; o grão-lorde Fordring... Sim, todas essas personalidades saboreavam o fumo de Siabi.$B$BInfelizmente, Siabi se recusou a deixar sua loja quando Stratholme foi invadida, jurando de pés juntos que o Flagelo nunca chegaria perto do seu tabaco. Vá para Stratholme e veja se você consegue encontrar algum resquício desse tabaco... ele vale ouro, posso garantir!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Caravaneiro Esmagapedra.', 0),
(27193, 'ptBR', 'Busque e destrua', 'Vasculhe as fazendas na Miséria de Olsen.', '<A voz da Rainha Banshee invade seus pensamentos mais uma vez.>$B$BVasculhe as fazendas próximas e encontre retardatários da Aliança. Fique $gatento:atenta; a qualquer informação que possa nos levar a Crowley e Dentessangue. Procure e destrua todos os que ficarem em seu caminho, $n!', '', '', '', '', '', '', 'Grande Dama Sylvana Correventos', 'Eles serão encurralados e esmagados!', 'Grande Dama Sylvana Correventos', 'Fale com a Grande Dama Sylvana Correventos no Sepulcro, que fica na Floresta de Pinhaprata.', 0),
(27194, 'ptBR', 'Encurralados e esmagados!', 'Apresente-se ao Mestre Forteski na Mina Elenfunda, que fica na Floresta de Pinhaprata.', '<A Rainha Banshee fala em sua mente.>$B$BPrecisamos agir rápido, $n. Eles não podem ter chance de fugir. Estou enviando nossas tropas mais poderosas à Mina Elenfunda, e com eles o Cavaleiro, para garantir que nada dê errado. Quero que você os encontre e se apresente ao mestre Forteski na Mina Elenfunda, a leste da Miséria de Olsen, e ESMAGUE aqueles ratos.', '', '', '', '', '', '', 'Grande Dama Sylvana Correventos', '', '', '', 0),
(27195, 'ptBR', 'Sem ter pra onde correr', 'Escolte o Mestre Forteski dentro da Mina Elenfunda.', 'A senhora me pôs como encarregado dessa tropa. Nossa missão primária é entrar lá, encurralar os ratos e matar todos eles, incluindo Dentessangue.$B$BVocê nos prestou um excelente serviço quando conseguiu essas informações, $n. Compartilhe de nossa glória e nos ajude a empalar os crânios daqueles miseráveis!$B$BMe avise quando estiver $gpronto:pronta;, e eu darei a ordem de ataque.', 'Escolte o Mestre Forteski dentro da Mina Elenfunda.', '', '', '', '', 'Escolte o Mestre Forteski dentro da Mina Elenfunda.', '', '', '', 'Fale com a Grande Dama Sylvana Correventos no Sepulcro, que fica na Floresta de Pinhaprata.', 0),
(27196, 'ptBR', 'Aprontando alguma coisa', 'Acompanhe Harrison Jones à Câmara das Estrelas.', 'É notável o trabalho que você fez. Especialmente para alguém que não faz os meus cursos!$b$bEstas tabuletas fornecem informações novas a respeito de vários assuntos.$b$bElas indicam que estes obeliscos são parte de um enorme mecanismo ancestral que, algum dia, já manteve esta região inteira escondida do resto do mundo.$b$bElas também descrevem como recarregar o mecanismo, e é aí que entra esse Cajado das Estrelas...$b$bPrepare-se, $n. Estamos prestes a fazer história!', '', 'Harrison Jones acompanhado até a Câmara das Estrelas', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Câmara das Estrelas.', 0),
(27197, 'ptBR', 'A batalha continua', 'Apresente-se ao Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 'Chegaram notícias de Andorhal, $n. A batalha foi retomada.$b$bJá é de conhecimento geral entre as forças da Aliança que você foi $go herói:a heroína; da primeira batalha de Andorhal. O Thassarian pediu a sua presença imediatamente.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27198, 'ptBR', 'Ajuda às tropas', 'Mate 15 Necroguardas de Andorhal.', 'Eu não sou nenhum especialista em estratégias militares, mas parece que esta batalha está a nosso favor. Nossos defensores se igualam em número com os necroguardas deles, mas a milícia dos fazendeiros pegou eles de surpresa por trás. Pela Aliança!$b$bAinda assim, nós precisamos fazer o possível para garantir a vitória. Viaje para leste de Andorhal e mate os Necroguardas Renegados que estão enfrentando nossos homens. Quanto mais cedo eles morrerem, mais rápido nós poderemos retomar Andorhal!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lango Manfurada em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27199, 'ptBR', 'Do pó ao pó', 'Mate 3 Necroguardas Capitães-de-guerra', 'A leste daqui, nas profundezas da parte de Andorhal controlada pelos Renegados, você vai encontrar os comandantes deles. Eles nunca entram em combate direto, ficam apenas dando ordens do alto de seus cavalos.$b$bProcure e mate esses comandantes, $n. Os renegados não terão chance.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27200, 'ptBR', 'Canção da sereia', 'Mate Ophelia, a Sereia do Planalto.', 'Ela ainda está por aí... Ophelia, a Sereia do Planalto! Sua tenebrosa canção pode te atrair para as profundezas. Prometi ficar na retaguarda e me vingar dos camaradas que se foram, $c. Se quiser me acompanhar, é só falar.$B$BNos amarraremos no mastro, fecharemos os olhos, taparemos os ouvidos com cera e, quando a ilusão dela passar... vamos atacar!$B$BTopa?', 'Mate Ophelia e proteja Efraim', '', '', '', '', 'Mate Ophelia e proteja Efraim', '', '', '', 'Fale com Efraim Durolito nas Quebradas Obsidianas, que ficam no Planalto do Crepúsculo.', 0),
(27201, 'ptBR', 'Incursão val\'kyr', 'Mate 9 Val\'kyren Menores em Andorhal.', 'As val\'kyren eram as principais armas do Flagelo. Não só eram extremamente habilidosas em combate como também podiam transformar cadáveres em lacaios do Flagelo. E pensar que a Sylvana chegou a esse ponto para garantir a supremacia dos Renegados...$b$bNós precisamos parar as val\'kyren antes que elas matem nossos exércitos e os usem contra nós. Mate todas as que você conseguir encontrar. E leve alguns desses milicianos com você. Se eles sobreviveram até agora, devem ter alguma capacidade de batalha.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27202, 'ptBR', 'Irmão contra irmão', 'Mate 20 Soldados Renegados em Andorhal.', 'Nossa milícia já foi quase dizimada. Só eu e um punhado de fazendeiros permanecemos vivos.$b$bAquelas criaturas aladas... Elas pegaram os corpos dos nossos homens e... e transformaram em mortos-vivos! A cada homem nosso que cai, aumenta o número dos soldados deles.$b$bEu odeio dizer isso, mas você terá que lutar contra eles também, junto com os necroguardas e as val\'kyren. Assim como fizeram em vida, eles caçam em grupo. Portanto, leve alguns milicianos com você.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Anton DeGrandis em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27203, 'ptBR', 'Voragem', 'Atravesse o Portal para Voragem e fale com Thrall.', 'Graças aos espíritos você está aqui, $n!$B$BNão sabemos por quanto tempo ainda conseguiremos segurar a abertura na Voragem.$B$BNossos companheiros mais poderosos, liderados por Thrall, estão com dificuldades para evitar o colapso completo.$B$BPelo que eu soube, nossa única esperança é tentar estabilizar a fenda pelo outro lado.$B$BVou conjurar um portal. Atravesse-o e apresente-se a Thrall o mais rápido possível.', '', '', '', '', '', '', '', '', '', '', 0),
(27204, 'ptBR', 'Aradne', 'Mate Aradne no topo da torre que fica na parte ocidental de Andorhal.', 'Nossa última esperança para vencer essa batalha é derrotar as val\'kyren. Você lutou muito bem até agora... Mas você é $gum:uma; $r só, e há literalmente dúzias delas causando caos e destruição no campo de batalha.$b$bUma val\'kyr enorme observa o progresso do combate do topo da torre ao sul... você pode vê-la daqui. Se a eliminarmos, é possível que as outras val\'kyren debandem.$b$bEssa é a nossa única esperança, $n. Leve consigo alguns dos homens do DeGrandis, você precisará da proteção deles nessa batalha.', '', '', '', '', '', '', 'Aradne', '', '', 'Fale novamente com Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(27205, 'ptBR', 'A depravação dos Renegados', 'Descubra o que Thassarian está vendo.', 'Nós já estamos quase vencendo essa batalha, $n. Eu posso sentir o gosto da vitória. Os Renegados nunca tiveram chan...$b$bO que diabos é isso?', '', '', '', '', '', '', '', '', '', 'Fale com Thassarian sobre o que você acabou de ver.', 0),
(27206, 'ptBR', 'Adeus, Andorhal', 'Relate os eventos da batalha de Andorhal para o Comandante Ashlam Punhobom.', 'Vá para o sul, para o Acampamento Ventogelante. Fale ao comandante Ashlam Punhobom sobre tudo que aconteceu aqui.$b$bEu? Eu estou indo para o oeste, para dentro de Tirisfal.$b$bA minha batalha ainda não terminou. Eu tenho um encontro com aquela bruxa que se autodenomina rainha Banshee... e vou descobrir o que ela fez com Koltirus.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.', 0),
(27208, 'ptBR', 'O senhor do medo Balnazzar', 'Mate Balnazzar.', 'Com a queda da Cruzada Escarlate, Balnazzar, o demônio que se passava por líder dos cruzados, libertou o corpo do grande cruzado Dathrohan e simplesmente enlouqueceu, matando todos os cruzados que restavam no local. Depois disso, ele usou seus poderes necromânticos para reviver todos os cruzados assassinados como escravos mortos-vivos.$B$BBalnazzar batizou seu novo exército de "Os Reanimados". Não podemos permitir que ele aumente o tamanho desse exército, pois eles são muito poderosos e, diferente do Flagelo de Arthas, Balnazzar não conterá suas forças. Mate-o enquanto ainda temos uma chance, $c.', '', '', '', '', '', '', 'Balnazzar', '', '', 'Fale novamente com o Comandante Eligor Alvorada.', 0),
(27209, 'ptBR', 'Vento ventania', 'Mate o Príncipe Sarsarun e depois fale com Hamuul Runa Totem no Penhasco do Trovão.', 'Bem, então é esse o mal que está por trás dos ataques ao Penhasco do Trovão.$B$BVamos avançar. Está na hora de pormos um fim a essa abominação.$B$BDiga ao Hamuul Runa Totem o que aconteceu quando voltamos. Preciso coordenar o regresso do meu povo, os consertos e tudo mais.', '', '', '', '', '', '', '', '', '', 'Informe Hamuul Runa Totem, no Penhasco do Trovão, da morte do Príncipe Sasarun.', 0),
(27210, 'ptBR', 'Há traidores entre nós', 'Confronte 5 Desertores Subversivos em Theramore.', 'É um prazer, $c. Vim a Theramore para eliminar o problema causado pelos desertores. Muito homens, depois de terem abandonado seus postos, voltaram e se espalharam pela cidade.$B$BOs agentes dos desertores estão propagando falácias sobre nossos líderes com o intuito de aumentar seus números.$B$BEles estão em praticamente todos os postos de guarda da cidade até as docas. Encontre-os, acabe com sua credibilidade expondo-os aos outros. Pelo andar da carruagem, uma atitude mais severa os deixariam mais bem-vistos pelos outros homens.', '', 'Desertor Subversivo exposto', '', '', '', '', '', '', '', 'Fale novamente com Calia Hastings na Ilha Theramore, que fica no Pântano Vadeoso.', 0),
(27211, 'ptBR', 'Propaganda de guerra', 'Obtenha a Propaganda do Desertor em uma embarcação, no fim das docas de Theramore.', 'Os agentes desertores estavam fazendo muito mais que apenas influenciar os guardas. Encontramos um monte de propagandas que os desertores conseguiram introduzir num navio, nas docas.$B$BO navio que seria usado para levar os panfletos está em Theramore ainda, na última doca. Se você conseguir se infiltrar no navio e roubar o resto das propagandas, os agentes perderão sua mais poderosa ferramenta. Tome cuidado! O navio é conduzido por corsários veteranos e a carga deve estar no alojamento do capitão.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Calia Hastings na Ilha Theramore, que fica no Pântano Vadeoso.', 0),
(27212, 'ptBR', 'Difamando os desertores', 'Distribua os Panfletos Alterados entre 6 Guardas de Theramore.', 'Alterei os panfletos que você roubou dos mercenários contratados pelos desertores nas docas. E agora, quando as pessoas lerem, terão uma ideia completamente diferente dos desertores e de seus objetivos.$B$BSe os distribuirmos entre os guardas, a desonra dos desertores será tamanha que jamais conseguirão se restabelecer no interior de nossos muros.$B$B<Calia lhe entrega um bolo de panfletos alterados.>$B$BFaça isso enquanto planejo o próximo passo.', '', 'Panfletos distribuídos', '', '', '', '', '', '', '', 'Fale novamente com Calia Hastings na Ilha Theramore, que fica no Pântano Vadeoso.', 0),
(27213, 'ptBR', 'O fim dos desertores', 'Derrote Gavis Escudogris, a bordo do navio ao sudeste de Theramore.', 'Agora que eliminamos os desertores de Theramore, é hora de finalizar a operação. Os relatórios dos meus contatos locais apontam que a base das operações dos desertores fica em um navio ancorado em uma ilhota a sudeste das docas.$B$BSe prendermos o líder Gavis Escudogris, os ânimos devem se acalmar. Encontre-o no navio e convença-o a se render. Não me espantaria se ele tentasse resistir e só se rendesse ao perceber que não conseguirá vencer.', '', 'Gavis Escudogris capturado', '', '', '', '', 'Gavis Escudogris', '', '', 'Fale novamente com Calia Hastings na Ilha Theramore, que fica no Pântano Vadeoso.', 0),
(27214, 'ptBR', 'Um desenvolvimento perturbador dos fatos', 'Apresente-se ao Capitão Walmor no Pontal de Vigília.', 'Recebemos relatórios muito desagradáveis de nossas patrulhas de escolta. Dizem que há homens usando bandanas vermelhas do Défias andando pela Costa Tenebrosa ao norte dos muros de Theramore.$B$BOs destroços na área indicam que eles podem ser sobreviventes de um naufrágio, mas nossas informações se limitam a isso. O capitão Walmor, no Pontal de Vigília, um sentinela de torre ao norte da cidade, está procurando ajuda para enriquecer nossas informações.', '', '', '', '', '', '', '', '', '', '', 0),
(27215, 'ptBR', 'O ermitão do Casarão do Pantanal Iluminado', 'Fale com Zé "Olho de Lama", no Casarão do Pantanal Iluminado.', 'Tem um sujeito que o pessoal chama de Zé "Olho de Lama" que mora sozinho no pântano. Já há algum tempo ele "ocupou" o Casarão do Pantanal Iluminado, após o desaparecimento misterioso dos antigos proprietários.$B$BGosto de mandar alguém para ver se está tudo bem com ele, de vez em quando. Ele meio que me lembra o meu avô, sabe? Tem gente que diz que ele é meio tantã.$B$BSe estiver indo para a saída noroeste de Theramore, vai passar pelo Casarão do Pantanal Iluminado na região do Morro das Bruxas, antes da estrada se virar para o oeste.', '', '', '', '', '', '', '', '', '', '', 0),
(27216, 'ptBR', 'O farol velho', 'Fale com Dani Torqueimado no farol da ilha ao leste de Theramore.', 'O farol velho ao leste não funciona mais há algum tempo, mas Dani Torqueimado colocou na cabeça que vai consertá-lo.$B$BNão faço ideia de como ela planeja fazer isso sozinha, mas, de acordo com ela, isso vai facilitar a entrada e saída de navios e mercadorias nas docas, então não tenho do que reclamar. Organizar as docas não se compara a estar na frente de batalha, né?', '', '', '', '', '', '', '', '', '', '', 0),
(27217, 'ptBR', 'Óleo de mangual', 'Colete 4 caixas de Óleo de Mangual dos Mangualamas abaixo das docas de Theramore.', 'Os registros antigos do farol indicam que a lanterna era abastecida com óleo dos manguais que vivem ao longo da costa.$B$B<Dani torce o nariz ao mencionar tecnologia tão ultrapassada.>$B$BCreio que seja a solução mais prática, apesar de deselegante. O registro diz que o óleo retirado dos mangualamas mais jovens funcionam melhor, e os mais jovens vivem logo abaixo das docas de Theramore.$B$BVocê está $Gdisposto:disposta; a ajudar no reabastecimento do farol?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dani Torqueimado na Ilha Theramore, que fica no Pântano Vadeoso.', 0),
(27218, 'ptBR', 'Pavorosos Pusilânimes das Profundezas', 'Leve o livro Pavorosos Pusilânimes das Profundezas a Michael Crowe, o Sujo, nas docas de Theramore.', 'Você nem imagina o tipo de coisa que dá pra encontrar nesse farol. É incrível. Depois que acendi a lanterna, reparei neste livro em cima de um baú aqui em cima.$B$B<Dani segura o livro e lê o título com uma voz dramática.>$B$B"Pavorosos Pusilânimes das Profundezas!"$B$BEita, acho que eu ia desmaiar só de ver um bicho desses! É óbvio que dá para dar umas boas risadas com esse livro, mas estou sem tempo para ler agora.$B$BNa verdade, tem uma pessoa que vai gostar e você conhece... o peixeiro que fica nas docas, Michael Crowe, o Sujo. Ele coleciona livros antigos.', '', '', '', '', '', '', '', '', '', 'Fale com Michael Crowe, o Sujo na Ilha Theramore, que fica no Pântano Vadeoso.', 0),
(27219, 'ptBR', 'É de verdade?', 'Fale com Nat Pagle no Píer do Nat, que fica no Pântano Vadeoso.', 'Hehe, sei que você e a Dani devem ter rido bastante das descrições e desenhos finisterrianos desse livro, mas vocês pararam pra pensar que pode ser verdade?$B$BSe prestar atenção por aí, aposto que vai ouvir os marinheiros falando de Tethyr, a criatura marítima que o livro diz que mora bem aqui! Claro, sempre que alguém quer saber algo assim, é só perguntar ao velho Nat Pagle.$B$BEle tem um campo de pesca em uma ilhazinha, na Enseada da Fúria das Marés, cruzando a Baía de Vadeoso.', '', '', '', '', '', '', '', '', '', '', 0),
(27220, 'ptBR', 'A barganha de Nat', 'Espalhe o Patê de Peixe do Pagle, Extraforte no seu corpo e adentre a Enseada da Fúria das Marés nadando.', 'Então você encontrou uma cópia de Pavorosos Pusilânimes das Profundezas, não foi mesmo? Bom, posso dizer da minha experiência pessoal que é tudo verdade. Já até vi alguns desses monstros com meus próprios olhos.$B$BMas você quer saber mesmo é sobre o Tethyr, né? Disse que ia fazer um negócio, então quero que faça o seguinte: Estou trabalhando em uma nova linha de iscas, mas ainda não testei essa aqui.$B$BÉ só pegar esse patê aí – esse que fede pra caramba – passar no corpo e nadar nas profundezas da Enseada da Fúria das Marés a sudoeste. Daí você me fala se funciona!', '', 'Patê de Peixe testado', '', '', '', '', '', '', '', 'Fale novamente com Nat Pagle no Píer do Nat, que fica no Pântano Vadeoso.', 0),
(27221, 'ptBR', 'Caramba, é de verdade!', 'Fale com o major Moendas nas docas de Theramore.', 'Sim, Tethyr é tão real quanto eu ou você e ele vive nas águas além de Theramore.$B$BEle tem uma atração por coisas brilhantes. Foi por causa dele que desativaram o farol, entendeu?...$B$BSe acenderem o farol, ele volta na hora, mas ninguém que bata bem da cabeça vai fazer isso.$B$BÉ o que você está planejando?! Foi bacana beber com você, e não vá culpar o velho Nat se Tethyr te COMER como se fosse isca de peixe – de verdade, dessa vez. Se for mesmo fazer isso, consulte o major Moendas, nas docas de Theramore.', '', '', '', '', '', '', '', '', '', '', 0),
(27222, 'ptBR', 'Acabe com Tethyr!', 'Use os morteiros para derrotar Tethyr.', 'Com ou sem monstro marítimo, não vamos arriscar a segurança dos nossos carregamentos. Ordenei aos nossos melhores atiradores que se preparassem para um confronto com esse Tethyr. A artilharia já acresceu as defesas da doca de três morteiros.$B$BVou ordenar que acendam a lanterna do farol. Se Tethyr atacar, seu trabalho será operar os morteiros e derrubar a fera antes que mate os nossos atiradores. Eu não aconselharia ficar no mesmo lugar por muito tempo. Os morteiros provavelmente vão chamar a atenção do monstro.', 'Defenda as Docas de Theramore de Tethyr', '', '', '', '', 'Defenda as Docas de Theramore de Tethyr', '', '', '', 'Fale novamente com o major Moendas na Ilha Theramore, que fica no Pântano Vadeoso.', 0),
(27223, 'ptBR', 'Retaliação', 'Mate o Imperdoável e Tico, o Cruel.', 'No cruzamento da Travessa do Comércio com a Alameda do Festival, você encontrará o Imperdoável. E, acabando com todos os inimigos na Praça dos Cruzados, você fará com que Tico, o Cruel, $Go:a; ataque. No passado, esses antigos campeões cometerem atos hediondos contra pessoas inocentes para adquirir ainda mais poderes profanos.$B$BVocê tem que destruí-los e livrar Stratholme dessa presença maligna. Tome cuidado, pois eles foram poderosos lutadores durante a vida, e agora, com seus novos poderes sombrios, são ainda mais mortais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Eligor Alvorada.', 0),
(27224, 'ptBR', 'Bandeira de fase de Andorhal', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27225, 'ptBR', 'Convocação de Abner Germano', 'Fale com Abner Germano no Centro de Comando de Ventobravo.', 'Abner Germano me enviou uma mensagem dizendo que deseja homenagear-te pela tua exímia habilidade em armas e tua dedicação à Aliança. Vá a Ventobravo e passa pela saída sul da Cidade Velha. Lá, fala com Ander no Centro de Comando. Não sei quais planos ele tem, mas parece ter demonstrado interesse em teu rápido progresso.', '', '', '', '', '', '', '', '', '', '', 0),
(27226, 'ptBR', 'Nós trupica mas não cai', 'Atice 8 Lobos do Mar Orcs.', 'Graças ao Chefe Guerreiro você chegou, $n. Cometi um erro grave com os lobos do mar... vou precisar da sua ajuda para consertar a situação.$B$BO que acontece é que eu os mandei enfrentar os worgens da Ilha de Fenris sóbrios... Muitos morreram, uns pouco sobreviveram... mas eles estão nas últimas.$B$BLeve este barril de cerveja para os Campos Apodrecidos, a leste daqui, e despeje-a pela goela dos lobos do mar.', '', 'Lobo do Mar Orc atiçado', '', '', '', '', '', '', '', 'Fale novamente com o Senhor da Guerra Torok no Sepulcro, que fica na Floresta de Pinhaprata.', 0),
(27227, 'ptBR', 'Lorde Aurius Rivendare', 'Mate o Lorde Aurius Rivendare.', 'Nossa capela é a luz no fim do túnel, a última esperança em meio à escuridão. Ras Friomúrmuro levou a própria esposa para o matadouro, com um sorriso macabro frente ao Lich Rei, que o reviveu como o Lich que hoje assombra Scolomântia.$B$BO solo onde tal atrocidade ocorreu é agora a terra sagrada do Flagelo, profanada pelo Lich Rei com sua magia negra. O Lorde Aurius Rivendare, novo governador de Stratholme, protege o local enquanto dá continuidade aos seus planos malignos. Mate-o imediatamente!', '', '', '', '', '', '', 'Lorde Aurius Rivendare', '', '', 'Fale novamente com o Comandante Cruzado Eligor Alvorada.', 0),
(27228, 'ptBR', 'Abaixo a Abominação', 'Assassine Ramstein, o Engolidor.', 'Nos confins de Stratholme você encontrará Ramstein, o Devorador. Mal consigo comentar as atrocidades que esse monstro cometeu. Mas saiba de uma coisa: ele merece sentir a fúria das incontáveis almas que destruiu, e é você quem levará essa fúria até ele.$B$BNão tenha piedade, e que sua fúria seja inabalável.', '', '', '', '', '', '', 'Ramstein, o Engolidor', '', '', 'Fale novamente com o Comandante Cruzado Korfax.', 0),
(27229, 'ptBR', 'DESTRUA A RAINHA DA NINHADA', 'Obtenha o Pedipalpo da Rainha da Ninhada.', '<Você lê uma inscrição em letras garrafais.>$B$BARANHAS RUINS NA CAVERNA NORTE. ARANHAS ENVENENAR OGROS. OGROS FICA MAL. RUIM!$B$BARANHÃO NA CAVERNA FAZER MAIS ARANHA. MAIS ARANHA RUIM!$B$BMATAR ARANHÃO, CHEGA DE ARANHA. MATAR ARANHÃO, GANHAR GRANDE RECOMPENSA! BOM!$B$B<Um desenho rudimentar acompanha a mensagem.>', '', '', '', '', '', '', 'Rainha de Ninhada Névoa Negra', 'ARANHA RUIM!', '', 'Apresente-se a Krog na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(27230, 'ptBR', 'Armas de guerra', 'Mate o Cuteleiro da Guarda Negra.', 'O Flagelo costuma forjar armas poderosas para seus soldados, o que torna ainda mais difícil matá-los! Perto do zigurate da Baronesa Anastari há instruções de ferraria que o chefe ferreiro planeja usar para forjar uma arma poderosíssima para o Lorde Aurius.$B$BVamos impedir que essa arma seja forjada e acabar de uma vez por todas com a produção de armamento! Vá em busca das instruções e mate o Cuteleiro da Guarda Negra logo que ele aparecer para defendê-las. Isso tornará nossa missão muito mais fácil.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Artesão Wilhelm.', 0),
(27231, 'ptBR', 'Reforços de Fenris', 'Mate 10 Worgens de Eira dos Montes.', 'Os que sobreviveram ao seu ataque a Fenris conseguiram beber o sangue do lobo. Eles se transformaram em worgens ferozes, loucos por vingança. Agora, eles infestam o Lago Lordamere e atacam meus cães do mar. Muitos já foram mortos. Esses worgens monstruosos têm que parar!$B$BVá até os Campos Apodrecidos, a leste daqui, e mate os worgens de Eira dos Montes que infestam a área. Quando tiver matado todos, siga para o painel de comunicação da Horda, que fica nas docas. Vou manter contato.', '', 'Worgens de Eira dos Montes mortos', '', '', '', '', '', 'Essa foi só a primeira leva!', 'Almirante Machadinha', 'Encontre o Painel de Comunicação da Horda nos Campos Apodrecidos, que fica na Floresta de Pinhaprata.', 0),
(27232, 'ptBR', 'Água rubra', 'Mate 50 Worgens de Eira dos Montes com o Canhão da Horda.', '<O console de comunicação emite um zumbido.>$B$BOs worgens que você matou eram do grupo de batedores. Tem centenas mais se aproximando! Parece que Crowley e Dentessangue fizeram a oferta de sangue para cada humano de Lordaeron.$B$BSuba num dos canhões da Horda e mande-os encontrar o criador. Que as águas do Lago Lordamere fiquem rubras com o sangue deles!', '', '', '', '', '', '', 'Almirante Machadinha', '', '', 'Fale novamente com a Almirante Machadinha no Sepulcro, que fica na Floresta de Pinhaprata.', 0),
(27233, 'ptBR', 'Acampamento dos Restauradores', 'Apresente-se ao Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 'Eu posso dar conta do treinamento por aqui. Se você está procurando outra coisa pra fazer, eu recomendo que você pegue a estrada na direção noroeste. Os druidas Cenarianos e a Cruzada Argêntea têm um pequeno acampamento armado lá, na antiga fazenda dos Dalson. Talvez eles tenham alguma coisa pra você fazer até nós precisarmos de você outra vez.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Agente de Campo Kaartish no Acampamento dos Restauradores, que fica nas Terras Pestilentas Ocidentais.', 0),
(27234, 'ptBR', 'Os Défias, aqui no pântano?', 'Obtenha as Ordens dos Défias de Galvão Matreiro.', 'Minhas escoltas relataram um naufrágio pouco além da praia, a nordeste. Os naufrágios são comuns aqui, mas os relatórios indicavam que os sobreviventes vestiam bandanas vermelhas... o símbolo dos Défias!$B$BOs relatórios indicam que o líder reside em uma ilha grande, um pouco além da costa, a nordeste da torre. Mate-o e pegue todos os documentos que ele possuir.', '', '', '', '', '', '', 'Galvão Matreiro', '', '', 'Fale novamente com o Capitão Walmor no Pontal de Vigília, que fica no Pântano Vadeoso.', 0),
(27235, 'ptBR', 'Renato Deguelra', 'Leve as Ordens de Défias para Renato Deguelra nas águas da Costa Tenebrosa.', 'De acordo com as ordens que você obteve, parece que a prioridade máxima dos Défias é localizar e assegurar a carga que possuíam, a qual desconhecemos.$B$BA AVIN tem um mergulhador de resgate, Renato Deguelra, que está trabalhando fora de Theramore há algum tempo. Quando soube do naufrágio, Renato foi mergulhar perto das ilhas ocupadas pelos Défias, ao norte.$B$BSe quisermos tomar essa carga dos Défias, precisaremos da ajuda dele. Procure-o nas águas a nordeste de uma ilhazinha que fica a norte da ilha que você visitou da última vez.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Renato Deguelra na Costa Tenebrosa, que fica no Pântano Vadeoso.', 0),
(27236, 'ptBR', 'Equipamento de mergulho de segunda mão', 'Leve o Kit de Ferramentas e o Equipamento de Mergulho Danificado para Renato Deguelra no Pântano Vadeoso.', 'Há um monte de destroços espalhados no fundo do mar daqui até Alcaz e os Défias já enviaram mergulhadores para vasculhar a área. Com ajuda do equipamento deles, podemos $Gprepará-lo:prepará-la; para se juntar à caçada, mas você vai ter de consegui-los "emprestados" de forma criativa.$B$BProcure uma caixa de equipamentos de mergulho na ilha e também material de manutenção. Quando conseguir tudo, traga para mim e eu vou arrumar tudo em um segundo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Renato Deguelra na Costa Tenebrosa, que fica no Pântano Vadeoso.', 0),
(27237, 'ptBR', 'Recolha a carga!', 'Colete 1 Cofre Resgatado.', 'Bom, com o conserto, o equipamento de mergulho vai aguentar por mais algum tempo. Mas não dá para confiar em mergulhos mais longos.$B$BOs destroços do navio estão espalhados pelo fundo do mar, ao longo do costa leste da ilha, em direção à Ilha Alcaz. Enquanto o escafandro aguentar, procure os restos do navio entre esta ilha e Alcaz. Use este kit de resgate para procurar a carga em meio aos destroços. Mas evite se aproximar muito da Ilha Alcaz. Aquelas hidras de lá são danadas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Renato Deguelra na Costa Tenebrosa, que fica no Pântano Vadeoso.', 0),
(27238, 'ptBR', 'Jaina precisa saber', 'Fale com a Grã-senhora Jaina Proudmore em Theramore.', 'Você deve levar as notícias de nossas descobertas à grã-senhora Jaina sem demora! Se os Défias estiverem transportando um prisioneiro, é impossível saber de quem se trata ou se ainda está vivo!$B$BUma coisa é certa, $n: eles não estariam tendo esse trabalho todo em função de um desentendimentozinho. O prisioneiro deve ser alguém de grande importância. A grã-senhora Jaina saberá melhor do que ninguém o significado disso tudo. Ela se encontra no topo da Torre dos Magos, no centro de Theramore.', '', '', '', '', '', '', '', '', '', '', 0),
(27239, 'ptBR', 'Inspeção na Ilha Alcaz', 'Fale com Cassa Carminasa e use um de seus grifos para inspecionar a Ilha Alcaz.', 'Parece que a intuição de Renato sobre a Ilha Alcaz estava certa, então. Temos que inspecionar a ilha, mas é preciso uma brigada inteira para abrir caminho até lá.$B$BAs defesas de Theramore não sobreviveriam a semelhante golpe, de forma que combinei com Cassa Carminasa, a aprendiz do mestre de grifos, para que ela lhe permitisse usar uma das feras para inspecionar Alcaz do alto.$B$BA Ilha Alcaz é a chave para desvendar o mistério do envolvimento dos Défias no rapto.', 'Inspeção da Ilha de Alcaz', '', '', '', '', 'Inspeção da Ilha de Alcaz', '', '', '', 'Fale novamente com a Grã-senhora Jaina Proudmore na Ilha Theramore, que fica no Pântano Vadeoso.', 0),
(27240, 'ptBR', 'Prova da traição', 'Fale com Jaina para ir a Ventobravo e conferenciar com o Rei Varian Wrynn.', 'Já desmascaramos Onyxia e a expulsamos da Corte. Mas ainda falta punir os Défias que colaboraram com o plano da dragonesa. Vá até o Castelo de Ventobravo e avise ao Rei Varian Wrynn que os Défias foram os responsáveis pelo rapto dele. Não tenho dúvidas de que o Rei aplicará veloz e terrivelmente sua justiça aos envolvidos.$B$BPosso usar de magia para acelerar sua viagem a Ventobravo. Fale comigo quando estiver $Gpronto:pronta; para partir, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(27241, 'ptBR', 'Fale novamente com Jaina', 'Apresente-se à Grã-senhora Jaina Proudmore em Theramore.', 'Preciso planejar a destruição do restante dos Défias. Por obséquio, transmita os meus agradecimentos à grã-senhora Jaina quando estiver de volta em Theramore. Ela sempre se mostrou uma amiga leal e aliada hábil.$B$BVá ao Distrito dos Magos, na extremidade oeste da cidade, e fale com o arquimago Malin ao pé de uma torre. Ele acelerará seu retorno à Theramore.', '', '', '', '', '', '', '', '', '', '', 0),
(27242, 'ptBR', 'Quem rapta capta', 'Use a Corda Robusta para capturar 6 Raptores ou Gritadores Dinossangue.', 'O pedaço mais ao nordeste do pântano é o lar de uma espécie de raptores muito agressiva. Inclusive, já nos tiraram alguns soldados distraídos, mas acho que podemos usá-los contra os nossos vizinhos no Temível Totem.$B$BLeve esta corda para capturar os raptores e gritadores dinossangue depois de subjugá-los. Eu não aconselharia tentar antes de ter enfraquecido bem a criatura. Vai ser uma luta e tanto.', '', 'Raptores capturados', '', '', '', '', '', '', '', 'Apresente-se ao Sargento Lukas na Torre Norte, que fica no Pântano Vadeoso.', 0),
(27243, 'ptBR', 'Solte os raptores', 'Coloque a Isca de Raptor perto do moinho da Aldeia Casco Negro.', 'Agora que conseguimos os raptores, o próximo passo é "encorajá-los" a atacar o Temível Totem na Aldeia Casco Negro, a noroeste.$B$BTenho umas sobras de pernil de... bom, não importa de que é o pernil. Vai servir de isca. Coloque-os no chão perto do moinho da Aldeia Casco Negro. Ele fica no centro do aldeia. Os raptores tomarão conta do resto, eles estão bem adestrados.', '', 'Raptores soltos', '', '', '', '', '', '', '', 'Apresente-se ao Sargento Lukas na Torre Norte, que fica no Pântano Vadeoso.', 0),
(27244, 'ptBR', 'O relatório perdido', 'Leve o Relatório do Espião para Nazir Piquessangue na Aldeia Muralha Verde.', 'Remexendo a terra, você encontra a mão decepada de um orc. A mão segura um tubo feito de osso. No tubo há um pergaminho sujo de terra.$B$BO pergaminho é um relatório feito por um orc que passou algumas semanas espionando a cidade de Theramore.$B$BApós uma passada de olhos, fica claro que isso deve ser encaminhado ao mestre espião orc da Aldeia Muralha Verde.', '', '', '', '', '', '', '', '', '', '', 0),
(27245, 'ptBR', 'Os prisioneiros dos Temível Totem', 'Pegue as Chaves dos Temível Totem dos taurens Temível Totem, na Aldeia Casco Negro, e use-as para libertar 5 Prisioneiros de Theramore.', 'Estamos fazendo o possível para manter os saqueadores dos Temível Totem afastados, mas eles continuam atacando a torre. E ainda pior: descobriram e capturaram as patrulhas que o capitão envia para conseguir informações e proteger a estrada.$B$BSuspeito que os cativos estejam na Aldeia Casco Negro, a noroeste. Conhecendo os Temível Totem, os defensores da vila devem estar com as chaves das jaulas. Não me importo por que meios, $c, traga meus homens de volta – e vivos.', '', 'Prisioneiros de Theramore libertados', '', '', '', '', '', '', '', 'Apresente-se ao Sargento Lukas na Torre Norte, que fica no Pântano Vadeoso.', 0),
(27246, 'ptBR', 'O relatório orc', 'Leve o Relatório do Espião ao Tenente Adão, em Theramore.', 'Remexendo a terra, você encontra a mão decepada de um orc. A mão segura um tubo feito de osso. Dentro do tubo há um pergaminho sujo de terra.$B$BO pergaminho está escrito em órquico... e parece importante.', '', '', '', '', '', '', '', '', '', '', 0),
(27247, 'ptBR', 'O Capitão Valente', 'Leve o Relatório do Espião ao Capitão Garrido Valente.', 'O capitão Valente tem de ver este relatório dos orcs que você encontrou, $n. Ele é um dos maiores conhecedores da língua órquica. Ele precisa saber que há espiões da Horda nas proximidades de Theramore!$B$BO capitão está no quartel, no lado nordeste da Ilha Theramore.', '', '', '', '', '', '', '', '', '', '', 0),
(27248, 'ptBR', 'A missão Coroa de Barro', 'Fale com Drazzit Pingajunta em Coroa de Barro.', 'O Cartel Bondebico estabeleceu um novo posto na porção sul do Pântano Vadeoso. Chama-se Coroa de Barro e, se me lembro bem, fica na estrada principal, ao sul da Fazenda de Tabetha e das Ruínas Pedramalho.$B$BÉ uma oportunidade excelente para estabelecermos novas trocas comerciais e a grã-senhora Jaina quer que eu envie um representante para estabelecer contato. Você está $Gdisposto:disposta; a ir?', '', '', '', '', '', '', '', '', '', '', 0),
(27249, 'ptBR', 'A inspeção das ruínas', 'Fale com o Inspetor Tarem, na Estalagem Pouso do Umbral.', 'O coitado do James nunca se recuperou da destruição da Pouso do Umbral e do assassinato de sua família. Os rapazes e eu estamos fazendo tudo o que podemos para encontrar os monstros responsáveis.$B$BMandei nosso melhor investigador, o Inspetor Tarem, para as ruínas, mas esse trabalho é difícil demais para um homem só. Se você puder dar uma mãozinha, nós ficaremos gratos. Só a Luz sabe o quanto nós gostaríamos de ajudar.$B$BA estrada principal $Go:a; levará até a estalagem; cuide-se. Sua jornada $Go:a; levará mais longe do que a proteção dos meus soldados alcança.', '', '', '', '', '', '', '', '', '', '', 0),
(27250, 'ptBR', 'REUSE - BAD COPY', 'Speak with Vincent Hyal in Menethil Harbor.', 'Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I\'d ever met. His name was James Hyal. Everything I have and everywhere I\'ve gotten in life is thanks to him.$b$bI wonder how he\'s doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven\'t heard from him recently.$b$bIf you ever happen to be headed in that direction, maybe you could say hello to him for me?', '', '', '', '', '', '', '', '', '', '', 0),
(27251, 'ptBR', 'Chamam-no Jim Sorridente', 'Fale com o Capitão Garrido Valente, no último andar da Cidadela do Esteio.', 'Não consigo deixar de sentir pena do velho Jim. Ele já foi diferente. Teve uma estalagem no pântano por algum tempo, um lugar maravilhoso.$B$BOlha, eu não estou muito a fim de falar disso. Se quiser saber a história, vá falar com o capitão Valente. A posição dele é no último andar da Cidadela do Esteio, fica naqueles quartéis enormes a leste da torre da Grã-senhora.', '', '', '', '', '', '', '', '', '', '', 0),
(27252, 'ptBR', 'Vento ventania', 'Mate o Príncipe Sarsarun. Depois, informe esse feito ao General Marcus Jonas em Ventobravo.', 'É ISSO que está por trás das tempestades que assolam minha cidade?$B$BVamos avançar. Aquele gigante indigente pode soprar e espernear o quanto quiser, mas este será o fim dele. Conte ao general Marcus Jonas o que ocorreu quando voltamos. Preciso cuidar da realocação dos cidadãos, dos consertos e de tudo mais.', '', '', '', '', '', '', '', '', '', '', 0),
(27253, 'ptBR', 'A inspeção das ruínas', 'Investigue a Estalagem Pouso do Umbral na extremidade dos Sertões, que fica no Pântano Vadeoso.', 'Seguindo a saída sul da vila e virando em direção aos sertões, a oeste, encontram-se as ruínas da Estalagem Pouso do Umbral.$B$BTheramore enviou um investigador para descobrir como a estalagem encontrou sua sina. Eu tinha um espião na estalagem e não confio na competência desses humanos para descobrir o que aconteceu.$B$BNão deixe nenhuma pista de nada que descobrir para o investigador. Vamos cuidar disso por conta própria.', '', '', '', '', '', '', '', '', '', '', 0),
(27254, 'ptBR', 'O escudo negro', 'Leve o Escudo de Ferro Enegrecido a Krog, na Aldeia Muralha Verde.', 'Um escudo de ferro, pretejado pelo fogo que devastou a estalagem, está afixado aos destroços da chaminé – uma das poucas partes restantes da estrutura que um dia fora a Estalagem Pouso do Umbral.$B$BÉ possível remover o escudo dos tijolos da chaminé.', '', '', '', '', '', '', '', '', '', '', 0),
(27255, 'ptBR', 'O escudo negro', 'Mostre o Escudo de Ferro Enegrecido para Do\'gol na Aldeia Muralha Verde.', 'Hmm... Não vejo nada de extraordinário neste escudo. Precisamos levá-lo a Do\'gol, o ferreiro, para que ele o examine. Talvez ele possa nos dizer mais, mas eu não alimentaria muitas esperanças...', '', '', '', '', '', '', '', '', '', '', 0),
(27256, 'ptBR', 'O escudo negro', 'Pegue 5 Vesículas de Peçonha Ácida das Aranhas Névoa Negra.', 'Huuum, lateral do escudo tem coisa escrita, mas difícil ler queimado.$B$BDo\'gol precisar de ácido pra limpar. Peçonha de aranha névoa negra ser bom. Aranhas viver em mina velha, a Caverna Névoa Negra, noroeste da aldeia. Se $r me traz vesícula, eu pode limpar escudo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Do\'gol na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(27257, 'ptBR', 'O escudo negro', 'Fale com Krog na Aldeia Muralha Verde.', 'Opa, acho que eu derramar ácido demais no escudo. Deixa Do\'gol esfregar um pouco...$B$BHum, difícil ler, mas parece ser o nome de Mosarn. Nunca ouvir falar de Mosarn. Quem sabe Krog conhecer? Krog conhecer muita gente.', '', '', '', '', '', '', '', '', '', '', 0),
(27258, 'ptBR', 'O escudo negro', 'Mostre o Escudo de Ferro Enegrecido para Mosarn no Penhasco do Trovão.', 'Ah, me lembrei! Mosarn é um ferreiro respeitado no Penhasco do Trovão. Sabia que já havia escutado esse nome antes.$B$BEm agradecimento, a Harmonia Telúrica me recompensou com um conjunto de armadura forjado por Mosarn. Muito bem feita, aliás.$B$BTalvez ele possa dar mais detalhes sobre o escudo que forjou.$B$BNão é uma pista muito boa, mas já que não conseguimos nada melhor de Reethe, isso é tudo o que temos.', '', '', '', '', '', '', '', '', '', '', 0),
(27259, 'ptBR', 'Pegadas em forma de casco', 'Informe Krog, na Aldeia Muralha Verde, sobre as pegadas suspeitas na Estalagem Pouso do Umbral.', 'Você nota um rastro de pegadas em forma de casco saindo do esqueleto ainda fumegante da Estalagem Pouso do Umbral. Há algumas outras marcas e outros rastros quase imperceptíveis na terra macia do pântano.', '', '', '', '', '', '', '', '', '', '', 0),
(27260, 'ptBR', 'Tenente Paval Reethe', 'Leve o Distintivo de Reethe para Krog na Aldeia Muralha Verde.', 'Uma luz fugidia no chão sob os escombros chama sua atenção. Ao retirar os destroços e as cinzas, é revelada uma insígnia de ouro em formato de âncora com uma inscrição branca: o símbolo de Theramore.$B$BAbaixo da âncora, lê-se: "Tenente Paval Reethe".', '', '', '', '', '', '', '', '', '', '', 0),
(27261, 'ptBR', 'O interrogatório de Reethe', 'Vá com Ogron para falar com Reethe.', 'Demorou, mas Ogron encontrar Reethe. Ele se esconder bem para um humano.$B$BOgron preocupado com ele ter ficado louco no pântano. Você vir com Ogron fazer perguntas a Reethe.', 'Interrogue Reethe na companhia de Ogron', '', '', '', '', 'Interrogue Reethe na companhia de Ogron', '', '', '', 'Fale novamente com Krog na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(27262, 'ptBR', 'Pegadas em forma de casco', 'Informe o Capitão Garrido Valente, em Theramore, sobre as pegadas suspeitas na Estalagem Pouso do Umbral.', 'Você nota um rastro de pegadas em forma de casco saindo do esqueleto ainda fumegante da Estalagem Pouso do Umbral. Há algumas outras marcas e outros rastros quase imperceptíveis na terra macia do pântano.', '', '', '', '', '', '', '', '', '', '', 0),
(27263, 'ptBR', 'Tenente Paval Reethe', 'Leve o Distintivo de Reethe ao Capitão Garrido Valente em Theramore.', 'Uma luz fugidia no chão sob os escombros chama sua atenção. Ao retirar os destroços e as cinzas, é revelada uma insígnia de ouro em formato de âncora com uma inscrição branca: o símbolo de Theramore.$B$BAbaixo da âncora lê-se: "Tenente Paval Reethe".', '', '', '', '', '', '', '', '', '', '', 0),
(27264, 'ptBR', 'Tenente Paval Reethe', 'Descubra mais sobre Reethe consultando o Auxiliar Tesoran em Theramore.', 'Não reconheço esse nome. É melhor você conferir com o auxiliar Tesoran. Ele toma conta de todos os registros da guarda de Theramore, tanto de pessoal quanto de equipamento.$B$BCom uma pesquisa rápida ele deve descobrir quem é Reethe.', '', '', '', '', '', '', '', '', '', '', 0),
(27265, 'ptBR', 'Lorde Grayson Quebrassombra', 'Fale com o Lorde Grayson Quebrassombra na Catedral da Luz, em Ventobravo.', 'O Lorde Grayson Quebrassombra, um dos mais notáveis paladinos deste reino, deseja conversar pessoalmente com você. Não sei quais são os planos dele, mas ele me pareceu impressionado com a sua rápida ascensão.$B$BVá imediatamente para Ventobravo e encontre-o na Catedral da Luz.', '', '', '', '', '', '', '', '', '', '', 0),
(27266, 'ptBR', 'O chamado de Wulf', 'Fale com Wulf Hansreim em Ventobravo.', 'Wulf Hansreim é responsável pelo treinamento e pela organização dos caçadores a serviço de Ventobravo. Ele pediu para que eu falasse pessoalmente contigo. Assim que estiveres pront$Go:a;, vá a Ventobravo e deixe o distrito da Cidade Velha pelo portão sul para chegar ao quartel general.$B$BNão consigo imaginar quais os planos dele, mas acredito que tenha ficado impressionado com tua rápida ascensão.', '', '', '', '', '', '', '', '', '', '', 0),
(27267, 'ptBR', 'Encontro com a AVIN', 'Fale com Osborne, o Homem da Madrugada, na Cidade Velha, em Ventobravo.', 'Parece que os líderes da AVIN ficaram sabendo dos teus feitos e conquistas em nome da Aliança, $n. Osborne, o Homem da Madrugada, membro de alta patente da AVIN, pediu que tu fosse falar com ele. Procure por ele na área sul da Cidade Velha de Ventobravo.$B$BNão sei ao certo o que ele pretende contigo, mas parece ser importante.', '', '', '', '', '', '', '', '', '', '', 0),
(27268, 'ptBR', 'Depressa, para a Catedral', 'Fale com a Alta-sacerdotisa Laurena na Catedral da Luz, em Ventobravo.', 'Tenho uma importante mensagem vinda de Ventobravo para ti, $n. Parece que a alta-sacerdotisa Laurena deseja conversar contigo na Catedral da Luz de Ventobravo. A mensagem não diz qual o motivo dessa convocação, mas creio que seria boa ideia apressar-te, pois parece urgente.', '', '', '', '', '', '', '', '', '', '', 0),
(27269, 'ptBR', 'O Templo da Lua', 'Fale com Tyrande Murmuréolo no Templo da Lua, que fica em Darnassus.', 'Ei, $Gguri:guria;! Tu recebeu uma mensagem urgente, vinda de Darnassus. É de ninguém menos que a própria Tyrande Murmuréolo, Alta-sacerdotisa de Eluna! O mensageiro não disse o que ela deseja tratar com você, mas recomendo que vá o mais rápido possível para o Templo da Lua em Darnassus.', '', '', '', '', '', '', '', '', '', '', 0),
(27270, 'ptBR', 'Audiência com o clarividente', 'Fale com a Clarividente Umbrua no Barril Dourado, que fica no Distrito dos Anões em Ventobravo.', 'Tenho uma mensagem urgente de Ventobravo para ti, $n. Parece-me que a clarividente Umbrua deseja falar contigo da próxima vez que passares pela cidade.$B$BO mensageiro não me explicou o motivo do convite, mas aconselho que viajes o quanto antes para Ventobravo. A clarividente Umbrua se encontra no Barril Dourado, localizado no Distrito dos Anões.', '', '', '', '', '', '', '', '', '', '', 0),
(27271, 'ptBR', 'Viagem para o Sacrário dos Teurgos', 'Fale com Maginor Dumas no Sacrário dos Teurgos, que fica no Distrito dos Magos em Ventobravo.', 'Acabo de receber uma mensagem de Ventobravo, $n. Maginor Dumas, um dos mais renomados magos de lá, pediu para que você o encontre no Distrito dos Magos, em Ventobravo. Ele fica no topo de uma grande torre, bem no coração do Distrito.$B$BNão sei quais são os planos dele, mas acho que ele ficou impressionado com o seu rápido aprendizado.', '', '', '', '', '', '', '', '', '', '', 0),
(27272, 'ptBR', 'Convocação de Joyce', 'Fale com Joyce Lopes no Cordeiro Imolado, que fica no Distrito dos Magos em Ventobravo.', 'Parece que nossos anciãos ficaram sabendo do teu progresso e da tua dedicação, $n. Joyce Lopes, uma das mais sábias e respeitadas integrantes de nosso círculo, nos mandou uma mensagem dizendo que deseja conversar com você. Não faça pouco caso disso. A maioria das pessoas só fala com ela durante o período de aprendizagem, mas se ela deseja vê-$Glo:la; pessoalmente, com certeza é algo de extrema importância.$B$BVá depressa para Ventobravo e encontre-a no porão do Cordeiro Imolado, no Distrito dos Magos.', '', '', '', '', '', '', '', '', '', '', 0),
(27273, 'ptBR', 'Convite da Clareira da Lua', 'Fale com Loganaar no Refúgio Noturno, que fica na Clareira da Lua.', 'Por pouco você não encontrou o mensageiro que veio da Clareira da Lua, $n. Ele não explicou direito, apenas disse que estava levando uma mensagem urgente de Loganaar, um dos honrados instrutores do Círculo Cenariano. Vá à Clareira da Lua o mais rápido que puder, $n. O assunto parece sério.$B$BProcure por Loganaar na aldeia Refúgio Noturno.', '', '', '', '', '', '', '', '', '', '', 0),
(27274, 'ptBR', 'A cirurgiã-chefe', 'Fale com a Cirurgiã-chefe Soldatalho no Distrito dos Anões, em Ventobravo.', 'Ei, $Gguri:guria;! Chegou uma mensagem urgente para você, vinda de Ventobravo. A cirurgiã-chefe Soldatalho pediu para que a encontre imediatamente. A mensagem não diz o que a Cirurgiã-chefe deseja tratar com você, mas recomendo que vá o mais rápido possível. Procure por ela no Distrito dos Anões de Ventobravo.', '', '', '', '', '', '', '', '', '', '', 0),
(27275, 'ptBR', 'Reencontro', 'Fale com a Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 'Cuidamos dos ferimentos da sentinela e providenciamos novos armamentos para ela. Já a mandei de volta para a batalha.$B$BEla $go:a; encontrará no Pináculo da Nuvem Negra.', '', '', '', '', '', '', '', '', '', '', 0),
(27276, 'ptBR', 'Reencontro', 'Fale com o Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 'Cuidamos dos ferimentos do valente e providenciamos novos armamentos para ele. Já o mandei de volta para a batalha.$B$BEle $go:a; encontrará no Pináculo da Nuvem Negra.', '', '', '', '', '', '', '', '', '', '', 0),
(27277, 'ptBR', 'Audiência com Ureda', 'Fale com Ureda no Antro das Sombras, em Orgrimmar.', 'Acabo de receber uma mensagem urgente de Orgrimmar para você, $n. Ureda, uma renomada maga, quer que você a encontre lá. Não sei do que se trata, mas se eu fosse você, iria para a capital o mais rápido possível. Ela disse que estaria esperando por você no Antro das Sombras.', '', '', '', '', '', '', '', '', '', '', 0),
(27278, 'ptBR', 'O chamado de Tiroatroz', 'Fale com Ormak Tiroatroz no Vale da Honra.', 'Um mensageiro acabou de me entregar uma mensagem dizendo que Ormak Tiroatroz, o mestre dos caçadores de Orgrimmar, quer falar com você.$B$BVá depressa para Orgrimmar e apresente-se a ele no Vale da Honra.', '', '', '', '', '', '', '', '', '', '', 0),
(27279, 'ptBR', 'A Mão Despedaçada', 'Fale com Gordul no Antro das Sombras, em Orgrimmar.', 'Um mensageiro recém-chegado de Orgrimmar estava procurando você, $n. Gordul, o experiente instrutor de ladinos, deseja vê-$Glo:la; imediatamente no Antro das Sombras, em Orgrimmar.$B$BSempre que Gordul chama, a coisa mais prudente a fazer é obedecê-lo. Não o faça esperar!', '', '', '', '', '', '', '', '', '', '', 0),
(27280, 'ptBR', 'O chamado do Rompe-terra', 'Fale com Terga Rompe-terra no Vale da Sabedoria, em Orgrimmar.', 'As notícias voam, jovem xamã. Seus feitos não passaram despercebidos! Parece que Terga Rompe-terra quer discutir algo com você. Vá imediatamente para Orgrimmar e encontre-a no Vale da Sabedoria. Ela estará junto dos outros instrutores.', '', '', '', '', '', '', '', '', '', '', 0),
(27281, 'ptBR', 'Grezz Iracarpos', 'Fale com Grezz Iracarpos no Vale da Honra, em Orgrimmar.', 'Acabo de receber notícias de que sua presença se faz necessária em Orgrimmar, $n. Grezz Iracarpos, honrado instrutor de guerreiros da cidade, $Go:a; chama, e não seria prudente ignorá-lo.$B$BVá imediatamente para Ogrimmar. Grezz $Go:a; aguarda no Vale da Honra.', '', '', '', '', '', '', '', '', '', '', 0),
(27282, 'ptBR', 'A mando de Kranosh', 'Fale com Kranosh no Antro das Sombras.', '$n, recebi notícias de que sua presença se faz necessária em Orgrimmar. Kranosh, um dos mais antigos instrutores de bruxos do Antro das Sombras, disse ter algo muito importante para tratar com você. Me parece o tipo de assunto que não pode ser adiado.$B$BVá à Orgrimmar e fale com ele assim que puder.', '', '', '', '', '', '', '', '', '', '', 0),
(27283, 'ptBR', 'Viagem à Clareira da Lua', 'Fale com Loganaar no Refúgio Noturno.', 'Como você já deve ter ouvido, a Clareira da Lua serve de lar para o Círculo Cenariano, uma irmandade de druidas. Todos que passam por lá, o fazem com a paz de Cenarius. E, sob essas condições, o instrutor Loganaar lhe estende um convite para que o visite na Clareira da Lua.$B$BVocê poderá encontrá-lo na aldeia Refúgio Noturno.', '', '', '', '', '', '', '', '', '', '', 0),
(27284, 'ptBR', 'O escudo negro', 'Mostre o Escudo de Ferro Enegrecido para Caz Doismancal em Theramore.', 'Sinto muito por não poder ajudar, $n, mas posso indicar alguém que $Go:a; ajudará. Caz Doismancal, um de nossos melhores ferreiros, trabalha na forja da ferraria.$B$BLeve o escudo para ele e escute o que tem a dizer.', '', '', '', '', '', '', '', '', '', '', 0),
(27285, 'ptBR', 'O escudo negro', 'Fale com o Capitão Garrido Valente em Theramore.', 'Ah, isso quase me passou despercebido... A faixa de couro na parte traseira deve ter queimado, mas parece que foi feita para uma pessoa bem grandona. Aliás, eu até diria que para um tauren.$B$BÉ tudo que posso dizer. Peça desculpas ao capitão Valente por eu não ter podido ajudar mais.', '', '', '', '', '', '', '', '', '', '', 0),
(27286, 'ptBR', 'Os homens de Daelin', 'Leve as informações sobre Reethe ao Capitão Garrido Valente em Theramore.', 'Redão... Redolfo... Achei! Tenente Paval Reethe.$B$BAlistado na guarda de Theramore junto com a maior parte dos recrutas que atravessaram o mar com a grã-senhora Proudmore. Alistado na marinha de Kul Tiraz com dezesseis anos. Serviços primorosos, promoções...$B$BSituação atual: desaparecido.', '', '', '', '', '', '', '', '', '', '', 0),
(27287, 'ptBR', 'Os desertores', 'Obtenha informações sobre Reethe de Balos Xavier e dos desertores no Pântano Vadeoso.', 'Tem sido difícil permanecer no pântano, mas, com muito esforço, conseguimos manter várias torres defensivas de observação espalhadas pela região.$b$bAs últimas informações e relatórios de batedores indicam que um grupo de desertores invadiu uma de nossas torres abandonadas no Posto Perdido, sudeste da estalagem.$b$bParece que o tenente local é Balos Xavier. Tente obter alguma informação dele.$b$bTenha cuidado, $n. Pode ser difícil arrancar alguma coisa do homem.', '', '', '', '', '', '', 'Balos Xavier', '', '', '', 0),
(27288, 'ptBR', 'Os desertores', 'Fale sobre Reethe com o Capitão Garrido Valente em Theramore.', 'Reethe? Aquele covarde?$B$BExpulsamos ele do acampamento, porque ele insistiu em continuar saqueando os suprimentos dos ogros da Aldeia Muralha Verde. Nossos números não são grandes o suficiente para enfrentarmos aqueles brutamontes.$B$BEle passou dos limites várias vezes, daí nós o deixamos por conta dele.$B$BAgora que ajudei você... Bem que poderia nos ajudar e fingir que nunca nos encontrou, não é mesmo?', '', '', '', '', '', '', '', '', '', '', 0),
(27290, 'ptBR', 'Para o Comando Avançado dos Renegados', 'Apresente-se ao Comandante Sicário Belmonte no Comando Avançado dos Renegados, que fica em Guilnéas.', 'É chegada a hora de destruir Crowley, Dentessangue e os cães que eles comandam. Para isso, precisaremos de astúcia e planejamento em níveis com os quais eles nem sequer sonham!$B$BVocê tem minha confiança, $n. Preciso que vá até o Comando Avançado dos Renegados, em Guilnéas, e apresente-se ao comandante sicário Belmonte. Ele já está lá com os planos, aguardando sua chegada.$B$BArtura escoltará você até o Comando Avançado. Me avise quando estiver $gpronto:pronta; e eu darei a ordem de partida.', '', '', '', '', '', '', '', '', '', '', 0),
(27291, 'ptBR', 'Paz, enfim', 'O Capitão Garrido Valente, na Cidadela do Esteio, quer que você coloque a Guirlanda sobre o Monumento da Família Hyal.', 'Gostaria de encontrar um meio de contar à esposa e ao filho de James que as mãos da justiça se abateram sobre os seus assassinos.$B$B<O capitão Valente mostra uma guirlanda de flores.>$B$BDizem que os espíritos sempre sabem, mesmo quando não conseguimos falar com eles. Não é muita coisa, mas gostaria que esta coroa repousasse sobre o monumento da família Hyal. É uma das pedras do cemitério ao norte, perto dos portões de Theramore.', '', 'Guirlanda Colocada no Monumento Hyal', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Garrido Valente na Cidadela do Esteio, que fica no Pântano Vadeoso.', 0),
(27292, 'ptBR', 'O retorno a Krog', 'Fale com Krog, na Aldeia Muralha Verde.', 'Espero ter ajudado e sinto muito por não ter mais informações. Meus aprendizes e eu fabricamos tantas armas e armaduras diferentes que é quase impossível lembrar dos detalhes de uma peça específica.$B$BNós não só equipamos os corajosos defensores das terras taurenas, como os Temível Totem apreciam muito meu trabalho. Um guerreiro experiente sabe reconhecer um bom trabalho quando o vê.', '', '', '', '', '', '', '', '', '', '', 0),
(27293, 'ptBR', 'Os planos dos Temível Totem', 'Pegue 4 Bilhetes dos Temível Totem dos Anciãos Temível Totem e una-os para formar os Planos de Batalha dos Temível Totem.', 'Agora que se lançou luz sobre as atividades dos Temível Totem de Mil Agulhas, muitos taurens olham seus irmãos com desconfiança. Já vimos membros dos Temível Totem cometerem assassinatos e raptos para servir os seus interesses e temo que tenhamos nos tornado o próximo alvo.$B$BA Aldeia Casco Negro a nordeste, perto da Charneca Azul, é um novo e grandioso assentamento dos Temível Totem. Seus líderes, os anciãos, recebem ordens direto do Penhasco do Trovão. Veja se consegue capturar as ordens para montar o quebra-cabeça e entender os planos dos Temível Totem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Krog no Pântano Vadeoso.', 0),
(27294, 'ptBR', 'Além de mera coincidência', 'Colete 7 Armamentos dos Casco Negro na Aldeia Casco Negro.', 'Conseguimos tudo o que pudemos das ruínas da estalagem. Estou preocupado com o lugar em que chegaremos a partir disso, mas precisamos saber a verdade.$B$BAs pegadas em forma de casco junto ao escudo com a marca de Mosarn, me levam a crer que os Temível Totem podem estar envolvidos. Recentemente, eles estabeleceram um assentamento no pântano: a Aldeia Casco Negro, a nordeste. Viaje até a Aldeia Casco Negro e procure mais armas feitas por Mosarn.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Krog na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(27295, 'ptBR', 'Encontre Tabetha', 'Fale com Tabetha em sua fazenda no Atoleiro.', 'As armas que você capturou na Aldeia Casco Negro só conheceram um tipo de combate: o treino, o que indica que os Temível Totem que destruíram o Pouso do Umbral continuam impunes.$B$BAo sul, no cerne do Atoleiro, vive a bruxa Tabetha. Embora seja humana, ela se mostrou honrosa em suas relações conosco e até treinou alguns de nossos magos.$B$BPeça-lhe ajuda para rastrear o bando dos Temível Totem responsável pelo incêndio da estalagem. Não podemos deixar que a Aliança nos considere cúmplice do ataque.', '', '', '', '', '', '', '', '', '', '', 0),
(27296, 'ptBR', 'Ateie fogo ao Posto Chifrebravo!', 'Use a Tocha de Tabetha para incendiar a Tenda Norte, a Tenda Leste e a Tenda Nordeste no Posto Chifrebravo.', 'Não é necessário ser clarividente para ver os problemas que os meus "vizinhos" novos estão causando. E se, de acordo com o que você diz, esse bando foi responsável pelo incêndio da Estalagem Pouso do Umbral, não há mais motivo para os tolerarmos.$B$BVá lá com esta tocha e volte quando só houver as cinzas no chão. Chifrebravo fica a norte da minha fazenda, perto da estrada. Sério, não dá para se perder: os Temível Totem fizeram um trabalho esplêndido em anunciar sua presença com aqueles totens que eles reverenciam.', '', 'Tenda Norte queimada', 'Tenda Nordeste queimada', 'Tenda Leste queimada', '', '', '', '', '', 'Fale novamente com Tabetha na Fazenda de Tabetha, que fica no Pântano Vadeoso.', 0),
(27297, 'ptBR', 'Justiça executada', 'Fale com Krog na Aldeia Muralha Verde.', 'Duvido muito que os Temível Totem desistam de sua campanha de expulsão dos humanos do pântano, mas tenho a impressão de que você não se importa muito com isso. Ao menos lidamos com os perpetradores dos crimes da Estalagem Pouso do Umbral.$B$BVá dizer ao seu líder que ele já pode se saciar com a vingança.', '', '', '', '', '', '', '', '', '', '', 0),
(27298, 'ptBR', 'Procure o mestre Pyreanor', 'Fale com o Mestre Pyreanor no Vale da Força, em Orgrimmar.', 'O mestre Pyreanor, um antigo Cavaleiro Sangrento e conselheiro do chefe guerreiro, solicita sua presença em Orgrimmar. Ele demonstrou interesse pelo seu treinamento, $n, e você deve falar com ele imediatamente.$B$BA mensagem que recebi não mencionava a razão pela qual ele deseja vê-$Glo:la;, mas você deve partir para Orgrimmar agora mesmo. O mestre Pyreanor $Go:a; espera na fortaleza ao centro do Vale da Força.', '', '', '', '', '', '', '', '', '', '', 0),
(27299, 'ptBR', 'Terra partida', 'Mate 3 Tentáculos de Iso\'rath.', 'Não vai precisar muita coisa pra convencer a gente a ficar contra os membros do Crepúsculo – já é, mermão! Já até entramos na batalha. A gente pode precisar de uma mão sua antes de partir pra fortaleza deles.$B$BO Crepúsculo já trouxe Iso\'rath das terras do sul, sei que cê já sabe disso. Os tentáculos dele tão irrompendo da terra por tudo que é lado. Se você quiser ajudar a gente, podemos acabar com eles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Arauto da Terra Torunscar no Círculo dos Elementos, que fica no Planalto do Crepúsculo.', 0),
(27300, 'ptBR', 'De frente com o Martelo', 'Mate 12 membros do Martelo do Crepúsculo nas Ruínas de Dragkor.', 'Os membros do Martelo do Crepúsculo destruíram uma cidade Presa do Dragão no sul e tão fazendo rituais de conjuração por aqueles lados. Não dê moleza pra eles e não deixe que continuem os encantamentos. Mostre o que é luta!', '', 'Sectários Drakgor assassinados', '', '', '', '', '', '', '', 'Fale novamente com o Arauto da Terra Torunscar no Círculo dos Elementos, que fica no Planalto do Crepúsculo.', 0),
(27301, 'ptBR', 'Corpo fechado', 'Encontre a Arauto da Terra Yevaa nas Ruínas de Drakgor.', 'Estamos preparando um ritual para destruir Iso\'rath, a abominação que o Martelo do Crepúsculo trouxe das profundezas. Mas estamos atrasados, pois uma das nossas companheiras mais fortes foi capturada durante um ataque ao acampamento deles.$B$BA arauto da terra Yevaa está nas ruínas ao sul. Ela não morreu, tenho certeza disso. Por favor, vá resgatá-la. Se há algum de nós que merece sua ajuda, esse alguém é ela.', '', '', '', '', '', '', '', '', '', '', 0),
(27302, 'ptBR', 'Soluções simples', 'Recolha 10 barris de Óleo de Pira.', 'Sou novo nessa parada. Um calouro. Mas sabe de uma coisa? Isso me dá perspectivas!$B$BOs meus chapas xamãs vieram com boas intenções, mas têm a cabeça muito quadradona! Eles confiam nos elementos, mas se esquecem de usar as coisas comuns que tem por aí.$B$BVi aqueles otários crepusculares carregando barris de óleo inflamável nas ruínas do sul! Vi eles usarem aquilo quando arrasaram a cidade. Vamos usar aquilo pra arrasar com eles!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Iniciado Almada no Círculo dos Elementos, que fica no Planalto do Crepúsculo.', 0),
(27303, 'ptBR', 'Corações derretidos', 'Recolha 5 Corações de Tostacarnes.', 'Não é nenhuma novidade que não desejo ficar aqui, mas há matérias-primas que precisamos para o ritual... Demorei para pegá-las e por isso fui capturada.$B$BRetornarei ao círculo e ficaria em dívida contigo se tu pudesses terminar o que eu não pude. Precisamos dos corações dos elementais de fogo que o Martelo do Crepúsculo escravizou no lado oeste do acampamento.$B$BOs elementais estão sem esperanças, mas com esse sacrifício eles terão sua vingança.$B$BEncontra-me no acampamento.', '', '', '', '', '', '', '', '', '', 'Fale com a Arauto da Terra Yevaa no Círculo dos Elementos, que fica no Planalto do Crepúsculo.', 0),
(27304, 'ptBR', 'Siga o Sol', 'Fale com o Andarilho do Sol Atohmo no Vale da Sabedoria, em Orgrimmar.', 'O Andarilho do Sol Atohmo nos manda notícias de Orgrimmar. Ele deseja encontrá-$Glo:la; na próxima vez que estiver na cidade. Não preciso lembrá-$glo:la; de que Atohmo é um honrado membro de nossa ordem e que os pedidos dele não devem ser ignorados.$B$BQuando você estiver em Orgrimmar, vá ao Vale da Sabedoria e fale com ele.', '', '', '', '', '', '', '', '', '', '', 0),
(27305, 'ptBR', 'Do Amor e da Família', 'Encontre a pintura "Do Amor e da Família".', 'Dentro do Bastião Escarlate há um bem de grande valor pessoal para o Grão-lorde Tirion Fordring. Procure uma pintura com duas luas gêmeas e descasque as camadas de tinta dela até revelar a obra prima conhecida como "Do Amor e da Família".$B$BQue a luz $Go:a; guie, e tome muito cuidado ao manusear a pintura.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Eligor Alvorada.', 0),
(27306, 'ptBR', 'Fale com Ogron', 'Encontre Ogron ao sudeste da Aldeia Muralha Verde.', 'Conheço este humano, Paval Reethe. É um ser patético, mesmo dentre os humanos. Desertou seus colegas e está se escondendo na floresta.$B$BEnviei Ogron para encontrá-lo. Ele é suspeito de roubar nossos suprimentos. Acho que Ogron foi em direção sudeste.', '', '', '', '', '', '', '', '', '', '', 0),
(27307, 'ptBR', 'Lamento dos elementos', 'Fale com Erunak Falapedra em Ventobravo.', 'Está sentindo, $c? Os elementos estão inquietos. Nós, membros da Harmonia Telúrica, estamos lutando para encontrar a causa desse distúrbio. Até então, não tivemos sucesso, e agora pedimos ajuda a outros. Fale com Erunak Falapedra em Ventobravo e veja se tem algo que você possa fazer para nos ajudar.', '', '', '', '', '', '', '', '', '', 'Fale com Erunak Falapedra em Ventobravo.', 0),
(27308, 'ptBR', 'Lamento dos elementos', 'Fale com a Reparadora da Terra Norsala em Orgrimmar.', 'Está sentindo, $c? Os elementos estão inquietos. Nós, membros da Harmonia Telúrica, estamos lutando para encontrar a causa desse distúrbio. Até então, não tivemos sucesso, e agora pedimos ajuda a outros. Fale com a Reparadora da Terra Norsala, em Orgrimmar, e veja se tem algo que você possa fazer para nos ajudar.', '', '', '', '', '', '', '', '', '', 'Fale com a Reparadora da Terra Norsala em Orgrimmar.', 0),
(27309, 'ptBR', 'The Grimtotem Plot', 'Collect 4 Grimtotem Notes from Grimtotem Elders and combine them to form the full Grimtotem Battle Plan.', 'With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We\'ve seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.$B$BBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems\' plans.', '', '', '', '', '', '', '', '', '', 'Return to Krog in Dustwallow Marsh.', 0),
(27310, 'ptBR', 'Nada de armas para vocês!', 'Queime 8 Cavaletes de Armas do Temível Totem.', 'Quer dizer que esses covardes querem lutar? Vamos ver como se saem sem nenhuma arma!$B$BBem, você deve ter alguma tocha ou coisa parecida. Queime o arsenal deles.$B$BQueime tudo!', '', 'Cavalete de Armas queimado', '', '', '', '', '', '', '', 'Fale com a Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27311, 'ptBR', 'Nada de armas para vocês!', 'Queime 8 Cavaletes de Armas do Temível Totem.', 'Os Temível Totem querem brigar? Vamos ver como esses covardes se saem sem armas!$B$BAposto que você tem alguma coisa que sirva para atear fogo no arsenal deles, $Gmeu caro:minha cara; $c.$B$BPonha fogo e deixe que a natureza cuide do resto.', '', 'Cavalete de Armas queimado', '', '', '', '', '', '', '', 'Fale com o Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27312, 'ptBR', 'Temível Totem da Nuvem Negra', 'Mate 20 taurens do Temível Totem no Pináculo da Nuvem Negra.', 'Não existe outra solução. Para vencer uma batalha é necessário derramar sangue. Neste caso... muito sangue.$B$BVocê já sabe o que precisamos fazer.', '', 'Temível Totem morto no Pináculo da Nuvem Negra', '', '', '', '', '', '', '', 'Fale com a Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27313, 'ptBR', 'Temível Totem da Nuvem Negra', 'Mate 20 taurens do Temível Totem no Pináculo da Nuvem Negra.', 'Não há alternativa. Para vencer uma batalha é necessário derramar sangue inimigo. Infelizmente, neste caso... muito sangue.$B$BVocê sabe o que precisamos fazer.', '', 'Temível Totem morto no Pináculo da Nuvem Negra', '', '', '', '', '', '', '', 'Fale com o Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27314, 'ptBR', 'Chefes dos Temível Totem: Isha Gume Sombrio', 'Mate Isha Gume Sombrio.', 'A primeira cartilha das sentinelas diz: mate os líderes e seus inimigos se enfraquecerão. É exatamente o que faremos, $c.$B$BIsha Gume Sombrio é a chefe do Temível Totem mais perto de nós. Vamos ver se ela é páreo para nós.', '', '', '', '', '', '', 'Isha Gume Sombrio', '', '', 'Fale com a Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27315, 'ptBR', 'Chefes dos Temível Totem: Isha Gume Sombrio', 'Mate Isha Gume Sombrio.', 'A filosofia de um valente diz que, se você matar os líderes inimigos, o caos se instaurará rapidamente nas forças deles. É exatamente o que vamos fazer, $c.$B$BIsha Gume Sombrio é a chefe dos Temível Totem mais perto de nós. Poremos o machado dela à prova, e ela não estará à altura.', '', '', '', '', '', '', 'Isha Gume Sombrio', '', '', 'Fale com o Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27316, 'ptBR', 'Chocalho de Ossos', 'Entregue o Chocalho de Ossos à Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 'Eis um chocalho tauren largado no chão, emanando poderes sobrenaturais. Seu antigo dono está morto, e o artefato foi abandonado.$B$BTalvez a sentinela tenha alguma pista quanto à importância de tal artefato.', '', '', '', '', '', '', '', '', '', '', 0),
(27317, 'ptBR', 'Chocalho de Ossos', 'Entregue o Chocalho de Ossos para o Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 'Eis um chocalho tauren largado no chão, emanando poderes sobrenaturais. Seu antigo dono está morto, e o artefato foi abandonado.$B$BTalvez o valente tenha alguma pista quanto à importância de tal artefato.', '', '', '', '', '', '', '', '', '', '', 0),
(27318, 'ptBR', 'Chefes dos Temível Totem: Ancião Casco Feroz', 'Mate o Ancião Casco Feroz.', 'O Ancião Casco Feroz é um xamã de imenso poder. Dizem que ele foi discípulo de Magatha Temível Totem, a Bruxa Anciã, líder do clã Temível Totem.$B$BSabemos que ele está aqui, treinando geomantes. Temos que matá-lo, $c.', '', '', '', '', '', '', 'Ancião Casco Feroz', '', '', 'Fale com a Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27319, 'ptBR', 'Chefes dos Temível Totem: Ancião Casco Feroz', 'Mate o Ancião Casco Feroz.', 'O Ancião Casco Feroz é um chefe xamã de imenso poder. Ele foi treinado pela própria Magatha Temível Totem, a Bruxa Anciã, líder do clã Temível Totem.$B$BSabemos que ele está aqui, treinando geomantes. Temos que matá-lo, $c.', '', '', '', '', '', '', 'Ancião Casco Feroz', '', '', 'Fale com o Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27320, 'ptBR', 'Pergaminho da História', 'Consiga o Pergaminho da História.', 'Os mitos dos shu\'halo contam da existência de três poderosos artefatos taurens: o Chocalho de Ossos, o Pergaminho da História e os Tambores da Guerra.$B$BPrecisamos ficar de olhos bem abertos se quisermos encontrá-los. Se as histórias forem verdadeiras, o pergaminho deve parecer um objeto comum, um mero pergaminho ilustrado.', '', '', '', '', '', '', '', '', '', 'Entregue o Pergaminho da História para a Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27321, 'ptBR', 'Pergaminho da História', 'Consiga o Pergaminho da História.', 'O Chocalho de Ossos faz parte dos antigos mitos dos shu\'halo. Ele sempre esteve ligado ao Pergaminho da História e aos Tambores da Guerra. Diz-se que a Mãe Terra presentou os taurens com esses três poderosos artefatos. Entretanto, não consigo imaginar nossa Mãe associada aos tambores.$B$BPrecisamos ficar de olhos bem abertos se quisermos encontrar os artefatos que faltam. Se bem me lembro da lenda, o pergaminho se parece com um simples rolo ilustrado.', '', '', '', '', '', '', '', '', '', 'Entregue o Pergaminho da História ao Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27322, 'ptBR', 'Korok, o Colosso', 'Leve a Segunda Cabeça de Korok para o Comandante Avançado da Ofensiva no Comando Avançado dos Renegados, que fica nas Ruínas de Guilnéas.', 'A monstruosidade caiu, garantindo um breve sossego para os soldados Renegados nas linhas de frente.$B$BLeve a segunda cabeça de Korok para o Comandante Avançado da Ofensiva no Comando Avançado dos Renegados.', '', '', '', '', '', '', '', '', '', '', 0),
(27323, 'ptBR', 'Chefes dos Temível Totem: Grundig Nuvem Negra', 'Mate Grundig Nuvem Negra', 'Um dos mais terríveis líderes dos Temível Totem da Cordilheira das Torres de Pedra voltou para cá.$B$BDevemos aproveitar esta chance e assegurar que ele não vá mais a lugar algum.', '', '', '', '', '', '', 'Grundig Nuvem Negra', '', '', 'Fale com a Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27324, 'ptBR', 'Chefes dos Temível Totem: Grundig Nuvem Negra', 'Mate Grundig Nuvem Negra', 'Um dos líderes mais importantes dos Temível Totem da Cordilheira das Torres de Pedra voltou para cá.$B$BDevemos aproveitar esta chance e acabar com a campanha de terror dele... de uma vez por todas!', '', '', '', '', '', '', 'Grundig Nuvem Negra', '', '', 'Fale com o Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27325, 'ptBR', 'Tambores da Guerra', 'Consiga os Tambores da Guerra.', 'Não sabemos o que o Temível Totem está tramando, mas não podemos permitir que fiquem com os Tambores da Guerra.$B$BNão se preocupe, $n. Tudo acabará bem. Porém, primeiro precisamos de todas as partes deste quebra-cabeça.', '', '', '', '', '', '', '', '', '', 'Entregue os Tambores da Guerra para a Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27326, 'ptBR', 'Tambores da Guerra', 'Consiga os Tambores da Guerra.', 'Não importa o que o Temível Totem esteja tramando, não podemos permitir que fiquem com os Tambores da Guerra.$B$BNão se preocupe, $n. Logo descobriremos o que está acontecendo aqui. No entanto, primeiro precisamos juntar todos os artefatos.', '', '', '', '', '', '', '', '', '', 'Entregue os Tambores da Guerra para o Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27327, 'ptBR', 'Chefes dos Temível Totem: O chefe dos chefes', 'Mate Arnak Temível Totem.', 'É chegada a hora de enfrentarmos Arnak, líder dos Temível Totem do Pináculo da Nuvem Negra.$B$BDizem que ele é o sobrinho desonrado de Magatha, a Bruxa Anciã e matriarca do clã Temível Totem. Supostamente, ela desaprovou a imprudência dos atos dele.$B$BMas nada disso importa. Vá e mate-o. Acabe com o problema.', '', '', '', '', '', '', 'Arnak Temível Totem', '', '', 'Fale com a Sentinela de Feralas no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27328, 'ptBR', 'Chefes dos Temível Totem: O chefe dos chefes', 'Mate Arnak Temível Totem.', 'É chegada a hora de enfrentarmos Arnak, líder dos Temível Totem do Pináculo da Nuvem Negra.$B$BEle é o sobrinho desonrado de Magatha, a Bruxa Anciã e matriarca do clã Temível Totem. Ela desaprova a imprudência dos atos dele.$B$BMas nada disso importa. Vá e mate-o. Acabe com isso de vez.', '', '', '', '', '', '', 'Arnak Temível Totem', '', '', 'Fale com o Valente de Vento Livre no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27329, 'ptBR', 'Evocando a serpente', 'Derrote Arikara.', 'Sim, conheço estes artefatos. Creio que tenham sido trazidos pela própria Magatha. No entanto, ela não está entre os Temível Totem do Pináculo da Nuvem Negra. Tão rápido quanto apareceu, ela se foi, e ninguém sabe para onde.$B$BTalvez possamos descobrir.$B$BLeve o chocalho, o pergaminho e os tambores para a Agulha de Arikara. Se minhas suspeitas estiverem corretas, a serpente alada aparecerá mais uma vez. Derrote-a para descobrir onde Magatha se esconde.', '', 'Arikara derrotada', '', '', '', '', 'Arikara', '', '', 'Fale novamente com Lakota Cantéolo no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27330, 'ptBR', 'Evocando a serpente', 'Derrote Arikara.', 'Sim, conheço estes artefatos. Creio que tenham sido trazidos pela própria Magatha. No entanto, ela não está entre os Temível Totem do Pináculo da Nuvem Negra. Tão rápido quanto apareceu, ela se foi, e ninguém sabe para onde.$B$BTalvez possamos descobrir.$B$BLeve o chocalho, o pergaminho e os tambores para a Agulha de Arikara. Se minhas suspeitas estiverem corretas, a serpente alada aparecerá mais uma vez. Derrote-a para descobrir onde Magatha se esconde.', '', 'Arikara derrotada', '', '', '', '', 'Arikara', '', '', 'Fale novamente com Lakota Cantéolo no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 0),
(27331, 'ptBR', 'O chamado do vidente', 'Fale com a Vidente Liwatha no Vale da Sabedoria, em Orgrimmar.', 'Fui informado que sua presença é necessária em Orgrimmar, $n. A vidente Liwatha pediu você volte à cidade o mais rápido que puder. Embora ela não tenha entrado em detalhes, pareceu ser algo de extrema urgência.$B$BProcure pela vidente Liwatha no Vale da Sabedoria, em Orgrimmar.', '', '', '', '', '', '', '', '', '', '', 0),
(27332, 'ptBR', 'Em busca do andarilho das sombras', 'Fale com o Andarilho das Sombras Zuru no Vale dos Espíritos, em Orgrimmar.', 'O andarilho das sombras Zuru solicita sua presença em Orgrimmar imediatamente, $n. Não demore, uma vez que isto parece ser importante.$B$BVocê pode encontrá-lo no Vale dos Espíritos, em Orgrimmar.', '', '', '', '', '', '', '', '', '', '', 0),
(27333, 'ptBR', 'Perdendo terreno', 'Mate 12 Rebeldes Worgens.', 'Não sei por quanto tempo vamos aguentar, $n. Crowley e os worgens Dentessangue conhecem cada esconderijo e local seguro em Guilnéas. Num minuto eles estão bem na sua frente, no outro, eles desaparecem! Vamos perder essa guerra por causa de ataques oportunistas, mesmo tendo um contingente maior.$B$BMas minha mãe não criou nenhum molenga! Sou Renegado até o fim, $gmeu:minha; camarada.$B$BVá para oeste, até o promontório, e ajude nossos soldados na linha de frente. Mate os worgens rebeldes!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Avançado Chacina no Comando Avançado dos Renegados, que fica nas Ruínas de Guilnéas.', 0),
(27334, 'ptBR', 'Clériga das trevas Cecille', 'Fale com a Clériga das Trevas Cecille no Castelo Grommash, que fica no Vale da Força, em Orgrimmar.', 'Acabo de receber uma mensagem da clériga das trevas Cecille, de Orgrimmar, solicitando a sua presença junto à delegação da Cidade Baixa, no salão de reuniões do Castelo Grommash. A clériga não me disse o motivo deste encontro, mas não há duvidas de que é de extrema importância. Apresse-se, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(27335, 'ptBR', 'Jornada para Orgrimmar', 'Fale com Tyelis no Castelo Grommash, que fica no Vale da Força em Orgrimmar.', 'Ainda há pouco, um mensageiro pediu para que eu lhe entregasse este convite. É de Tyelis, um instrutor de sacerdotes e emissário de Luaprata.$B$BEle pediu para que o encontre no Castelo Grommash, em Orgrimmar. Vá imediatamente, $n, pois parece ser importante.', '', '', '', '', '', '', '', '', '', '', 0),
(27336, 'ptBR', 'A arma dos Temível Totem', 'Use o Totem Capturado para fincá-lo no chão e mate 10 Crocoliscos Secâmoros Mosqueados ou Secâmoros Gorjadaga perto do totem para testar seus efeitos.', 'Eu fui ferido durante o último ataque dos Temível Totem, mas isso não me impediu de roubar um dos peculiares totens que nossos inimigos estavam usando contra nós.$B$BEle parecia lançar raios de energia pura durante a batalha, mas mesmo depois de vários experimentos, não consegui descobrir como ele funciona. Se concordar em testá-lo, eu lhe emprestarei o totem.$B$BAs áreas aguacentas em volta da fazenda são o lar de muitos crocoliscos secâmoro e secâmoros gorjadaga irritantes. Tente lutar com os crocoliscos perto do totem.', '', 'Testes do Totem conduzidos', '', '', '', '', '', '', '', 'Fale novamente com o Aprendiz Garion na Fazenda de Tabetha, que fica no Pântano Vadeoso.', 0),
(27337, 'ptBR', 'Uma arma apropriada', 'Vá à Bastilha da Presa Negra e recupere a Espada da Família Silverlaine do Barão Silverlaine, 5 caixas de Lingotes de Lunaço e 5 Tendões Imortais.', 'Desde quando você ainda era jovem, $n, os instrutores me falavam sobre seu talento natural. Seu aprendizado e dedicação $go:a; tornaram um exemplo para todos.$B$BComo prova de reconhecimento, o rei Wrynn ordenou que o armeiro real forje uma arma especial para você.$B$BDiz a lenda que a amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata, é onde se encontram as matérias-primas para tal fabricação. Vá e encontre a espada da família Silverlaine, há muito perdida. Traga também um carregamento de lingotes de lunaço e tendões dos carniçais e geists que infestam aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Therum Baixaforja no Distrito dos Anões, em Ventobravo.', 0),
(27338, 'ptBR', 'Guris ao mar', 'Apresente-se ao Tenente Henri na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 'A situação aqui no Planalto muda a cada minuto. Nosso objetivo é atacar o Bastião do Crepúsculo, mas nem consigo defender uma pista de pouso na costa sem que a maldita Horda crie um salseiro.$B$BEnquanto eu junto os destroços da frota, preciso de homens protegendo a orla.$B$BApresente-se ao tenente Henri, que está na orla, e ajude seus homens na defesa contra a Horda!', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Tenente Henri na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27339, 'ptBR', 'O ladrão de reagentes', 'Colete 6 ampolas de Peçonha do Pântano das Rastejantes Presanegra ou das Retalhadoras Nóxias.', 'O aprendiz Morlann fica pra cima e pra baixo choramingando sobre reagentes o tempo todo.$B$BNormalmente eu ignoro, mas nunca funciona. Desta vez, quero tentar algo diferente.$B$BAcho que ele vai me deixar em paz se eu repuser os reagentes que estão faltando antes que ele perceba. O reagente que nós dois mais usamos é a peçonha do pântano, encontrado nas rastejantes presanegra e das retalhadoras nóxias que vivem no pântano ao norte da fazenda. Se você me trouxer a peçonha, farei a reposição antes que Morlann perceba que eu usei.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Aprendiz Garion na Fazenda de Tabetha, que fica no Pântano Vadeoso.', 0),
(27340, 'ptBR', 'Os saqueadores de Chifrebravo', 'Mate 12 Temível Totem no Posto Chifrebravo.', 'Os Temível Totem do Posto Chifrebravo estão ficando cada vez mais audaciosos. Todas as noites os ouvimos cantar seus feitos de batalha contra os povos que tentaram se estabelecer aqui.$B$BEles estão determinados a nos expulsar da fazenda de Tabetha, sem se importar se gerações inteiras de aprendizes foram treinadas aqui. Demos o melhor de nós para defender a fazenda, mas o aprendiz Garion estava ferido durante o último ataque.$B$BVá ao Posto Chifrebravo e mate todos os Temível Totem que encontrar! Temos que deter esses ataques!', '', 'Membros do Temível Totem de Chifrebravo Mortos', '', '', '', '', '', '', '', 'Fale novamente com o Aprendiz Morlann, na Fazenda de Tabetha, que fica no Pântano Vadeoso.', 0),
(27341, 'ptBR', 'A patrulha da orla', 'Patrulhe o Ponto de Controle da Cabeça de Praia na Costa do Crepúsculo. Você não precisa tomá-lo, mas, se assim o fizer, seu lado terá vantagem de combate e você será $gsinalizado:sinalizada; para JxJ.', 'Somos nós ou eles, $c. Somente um de nós pode comandar esta praia.$B$BA norte daqui você encontrará uma colina com vista que permite vigiar a orla. Quem controlar essa colina terá a costa em suas mãos.$B$BTenho que saber como está a situação atual. Patrulhe o ponto de controle da cabeça da praia sinalizado com uma bandeira enorme e volte aqui.$B$BVocê não precisa tentar tomá-lo, a não ser que esteja $gdoido:doida; por uma briga...', 'Ponto de Controle da Cabeça de Praia patrulhado', '', '', '', '', 'Ponto de Controle da Cabeça de Praia patrulhado', '', '', '', 'Fale novamente com o Tenente Henri na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27342, 'ptBR', 'Com o tempo, tudo será revelado.', 'Colete 6 Acônitos.', 'A Dama Sombria enviou Artura e você aqui para um propósito bem específico. Antes que eu possa dizer mais, precisamos fazer preparativos.$B$BSiga para leste, para a floresta de Guilnéas, e procure perto das árvores e pedras da região por uma planta especial chamada acônito, ou "mata-lobos". Colete o máximo que puder carregar e volte aqui.$B$BA nossa missão aqui vai além do campo de batalha, $n. Com o tempo, tudo será revelado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Sicário Belmonte no Comando Avançado dos Renegados, que fica nas Ruínas de Guilnéas.', 0),
(27343, 'ptBR', 'A mão da Luz', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante do Comandante Floraval, 5 caixas de Lingotes de Lunaço e 5 Tendões Imortais.', 'Venho observando seus passos, $n, e conclui que a Luz brilha forte em seu coração. Você se tornou $gum:uma; $c exemplar.$B$BComo forma de honrar a sua dedicação, o Rei Wrynn ordenou que o ferreiro real lhe forje uma arma especial.$B$BOs materiais necessários são raros e só podem ser encontrados na amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata. Vá até lá e traga o símbolo sagrado do comandante Floraval, algumas caixas de lingotes de lunaço e tendões dos carniçais e geists que infestam o lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Therum Baixaforja no Distrito dos Anões, em Ventobravo.', 0),
(27344, 'ptBR', 'Uma recompensa merecida', 'Vá à Bastilha da Presa Negra e consiga a Mira de Cristal de Godfrey do Lorde Godfrey, 5 feixes de Lunalenha e 5 Tendões Imortais.', 'Não sou o único que está impressionado com o progresso apresentado por você, $n. Sua habilidade com arco, assim como a força de seu ajudante e sua dedicação à Aliança, chegou aos ouvidos do Rei Wrynn.$B$BComo reconhecimento por tudo o que tem feito, o próprio rei ordenou que o arqueiro real construa uma arma especial.$B$BEntretanto, os materiais necessários encontram-se dentro da amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata. Vá até lá e traga a mira da arma do Lorde Godfrey, alguns feixes de lunalenha e tendões dos carniçais e geists que infestam aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Frederico Fornalha no Distrito Comercial de Ventobravo.', 0),
(27345, 'ptBR', 'O D.C.R.', 'Recupere o Dispositivo de Comunicação dos Renegados.', 'Perdemos comunicação com todos os postos avançados da linha de frente, $n. Neste momento, não tenho a menor ideia do que está se passando com nossas tropas em Guilnéas. Precisamos restabelecer comunicação.$B$BPreciso que você siga para leste, na direção do promontório, e se apresente em nosso posto avançado na costa. A esta altura os soldados devem estar todos mortos, mas o D.C.R. deles deve estar operacional. Traga o dispositivo para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Avançado Chacina no Comando Avançado dos Renegados, que fica nas Ruínas de Guilnéas.', 0),
(27346, 'ptBR', 'O zepelim caído', 'Fale com Moxie Gradacelha nos Destroços de Beezil.', 'Pouco tempo atrás, um zepelim goblin caiu ao leste daqui. E, há alguns dias, uma representante do Cartel Bondebico passou por aqui.$B$BEla estava buscando informações sobre a carga e o piloto Beezil Esmerilhadeiro, mas nenhum de nós viu a queda direito. Duvido muito que ela consiga revirar os destroços por conta própria, quanto mais recuperar a carga que o veículo transportava.$B$BSe estiver com tempo, ela se encontra nos Destroços de Beezil, ao leste daqui, perto das montanhas.', '', '', '', '', '', '', '', '', '', '', 0),
(27347, 'ptBR', 'Prevenção contra corrosão', 'Moxie Gradacelha quer que você dissolva 10 gosmas e que fale novamente com ela nos Destroços de Beezil.', 'Olha só esse lugar! Tá infestado de gosmas. Se eu não descobrir como mantê-las sob controle, elas vão corroer os destroços e a carga do zepelim!$B$BNão posso voltar de mãos abanando, $c! Ajude-me a dissolver as gosmas antes que elas engulam tudo!$B$BEste aparelho, quando carregado, concentra uma quantidade de energia nas gosmas que faz com que elas explodam. Os fragmentos do núcleo de força do zepelim devem bastar para carregar o aparelho. O que está perto do destroço maior funciona o tempo todo, mas os outros ficam oscilando.', '', 'Gosmas dissolvidas', '', '', '', '', '', '', '', 'Fale novamente com Moxie Gradacelha nos Destroços de Beezil, que fica no Pântano Vadeoso.', 0),
(27348, 'ptBR', 'O asseguramento da carga!', 'Moxie Gradacelha, nos Destroços de Beezil, quer que você resgate 8 peças da Carga do Zepelim.', 'Este zepelim estava levando seis meses de suprimentos para Coroa de Barro! Tá certo que eles conseguiram negociar algumas necessidades básicas, mas não vão aguentar por muito tempo.$B$BFui enviada para recuperar o que fosse possível da carga, mas os destroços estão espalhados por todo o pântano desta área. Sei que muitas coisas não sobreviveram à queda, mas tu tá $Gdisposto:disposta; a me ajudar com o que der?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Moxie Gradacelha nos Destroços de Beezil, que fica no Pântano Vadeoso.', 0),
(27349, 'ptBR', 'Interrupção de comunicações: Posto Mirante do Medo', 'Investigue o Posto Mirante do Medo.', 'Não vou mentir para você, $n. É praticamente suicídio o que vou pedir que você faça. A chance de fracasso é perto de 95%.$B$BTodas as comunicações vindas do Posto Mirante do Medo cessaram. Com os worgens nos atacando sem trégua, não temos como ir ao Mirante do Medo ver a situação dos soldados. Preciso que você vá para o posto avançado, ao sul daqui, e veja o que está acontecendo com os soldados. Daqui por diante, vou manter contato pelo dispositivo de comunicação dos Renegados, o D.C.R.$B$BAFASTE-SE DA ESTRADA PRINCIPAL.', 'Investigue o Posto Mirante do Medo.', '', '', '', '', 'Investigue o Posto Mirante do Medo.', '', 'O Mirante do Medo era nosso posto avançado mais bem protegido.', 'Comandante Avançado Chacina', 'Fale com o Comandante Avançado Chacina no Comando Avançado dos Renegados, que fica nas Ruínas de Guilnéas.', 0),
(27350, 'ptBR', 'Interrupção de comunicações: Guarda de Rutsak', 'Encontre o Capitão Rutsak na Guarda de Rutsak, que fica nas Ruínas de Guilnéas.', '<O D.C.R. emite um zumbido.>$B$BO próximo posto avançado é a Guarda de Rutsak, a leste do Mirante do Medo. Você deve ir para lá evitando os agressores worgens, $n. Você não vai querer encarar esses bichos $gsozinho:sozinha;.$B$BSe você chegar lá $ginteiro:inteira;, encontre o capitão Rutsak.$B$BEsteja $gpreparado:preparada; para o pior.', '', '', '', '', '', '', 'Comandante Avançado Chacina', '', '', '', 0),
(27351, 'ptBR', 'Uma real recompensa real', 'Vá à Bastilha da Presa Negra e consiga a Pedra de Amolar do Comandante Floraval, 5 caixas de Lingotes de Lunaço e 5 Tendões Imortais.', 'A AVIN tem observado seus passos com interesse. Os serviços que você tem prestado à Aliança, assim como as histórias de suas conquistas, chegaram aos ouvidos do rei.$B$BComo reconhecimento à essa dedicação, o Rei Wrynn ordenou que o ferreiro real forje uma arma especial.$B$BOs materiais necessários, porém, são raros e só podem ser encontrados na amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata. Vá até lá e traga a pedra de amolar do comandante Floraval, algumas caixas de lingotes de lunaço e tendões dos carniçais e geists que infestam o lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Therum Baixaforja no Distrito dos Anões, em Ventobravo.', 0),
(27352, 'ptBR', 'Ouro líquido', 'Encontre uma ampola de Água Benta de Stratholme.', 'Enquanto o Flagelo varria Stratholme como uma peste indomável, os Cavaleiros do Punho de Prata preparavam litros e litros de água benta para usar contra os mortos-vivos. Eles armazenavam a água em pequenos caixotes, junto com outros suprimentos muito importantes, e os distribuíam por toda a cidade. Infelizmente, os habitantes da cidade foram contaminados pela peste e tornaram-se membros do Flagelo muito antes da água benta ser usada!$B$BEssas caixas de suprimentos serão muito úteis em nossa operação. Traga-me uma ampola de água benta de Stratholme, pois precisaremos replicá-la em grande quantidade.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Caravaneiro Esmagapedra.', 0),
(27353, 'ptBR', 'Bênção dos elementos', 'Vá à Bastilha da Presa Negra e consiga o Talismã de Walden, o Livro das Almas Perdidas e 5 Essências Fantasmagóricas.', 'Teu talento chamou muita atenção entre os círculos xamanísticos, $n. Histórias sobre teu domínio dos elementos, assim como tua dedicação à Aliança, chegaram até mesmo ao trono.$B$BComo prova de reconhecimento, o Rei Wrynn ordenou que o encantador real crie uma arma especial.$B$BEntretanto, os materiais necessários só podem ser encontrados na amaldiçoada Bastilha da Presa Negra, que fica na Floresta Pinhaprata. Vá até lá e traz o talismã de Walden, o Livro das Almas Perdidas e as essências dos fantasmas que assombram o lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Therum Baixaforja no Distrito dos Anões, em Ventobravo.', 0),
(27354, 'ptBR', 'O domínio do poder arcano', 'Vá à Bastilha da Presa Negra e consiga o Cristal Encantado de Silverlaine do Barão Silverlaine, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', 'Você tem se mostrado $gum brilhante aluno:uma brilhante aluna; e $gum dedicado defensor:uma dedicada defensora; da Aliança.$b$bEm reconhecimento aos seus serviços, o Rei Wrynn ordenou que o encantador real crie uma arma especial.$B$BEntretanto, o material necessário só pode ser encontrado na amaldiçoada Bastilha da Presa Negra, que fica na Floresta Pinhaprata. Vá até lá e traga a herança perdida da família Silverlaine, um feixe de lunalenha e as essências dos fantasmas que assombram o lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Lucas Cordell no Distrito dos Magos, em Ventobravo.', 0),
(27355, 'ptBR', 'Bênção para os fortes', 'Vá à Bastilha da Presa Negra e consiga o Orbe Tenebroso do Lorde Godfrey, o Livro das Almas Perdidas e 5 Essências Fantasmagóricas.', 'O reino está começando a reconhecer nosso poder e importância para a Aliança, graças aos seus feitos. Talvez este seja o primeiro passo para ganharmos a confiança deles.$B$BO Rei Wrynn ordenou que o encantador real crie uma poderosa arma para você como forma de reconhecimento pelas conquistas alcançadas até então.$B$BTodos os materiais necessários podem ser encontrados na Bastilha da Presa Negra, na Floresta Pinhaprata. Vá e traga o orbe tenebroso que Lorde Godfrey usa, o Livro das Almas Perdidas e as essências dos fantasmas que assombram o local.', '', '', '', '', '', '', '', '', '', 'Fale com Lucas Cordel no Distrito dos Magos, em Ventobravo.', 0),
(27356, 'ptBR', 'O futuro do Círculo', 'Vá à Bastilha da Presa Negra e consiga os Elixires de Walden do Lorde Walden, 5 feixes de Lunalenha e 5 Tendões Imortais.', 'O Círculo Cenariano está feliz com as suas conquistas, $n. Você é um exemplo a ser seguido por todos os druidas da nossa comunidade.$B$BO Círculo decidiu honrá-$Glo:la; com a criação de um cajado único.$B$BOs raros e poderosos materiais necessários para forjá-lo encontram-se dentro da Bastilha da Presa Negra, na Floresta de Pinhaprata. Vá e me traga a coleção de elixires do Lorde Walden, alguns feixes de lunalenha e tendões dos carniçais e geists que habitam a bastilha.', '', '', '', '', '', '', '', '', '', 'Fale com Narianna no Refúgio Noturno, que fica na Clareira da Lua.', 0),
(27357, 'ptBR', 'A noiva cativa', 'Fale com Lakota Cantéolo no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 'Mas é claro! Lakota Cantéolo! Como não pensei nisso antes?$B$BEla foi sequestrada por Arnak anos atrás. Ela conseguiu escapar, mas foi capturada novamente em meio a toda a confusão causada pelos recentes ataques à Aldeia Vento Livre.$B$BVamos procurá-la. Ela se aprofundou nos estudos místicos nos últimos anos. Acho que ela deve saber o que fazer com estes artefatos.', '', '', '', '', '', '', '', '', '', '', 0),
(27358, 'ptBR', 'A noiva cativa', 'Fale com Lakota Cantéolo no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 'Lakota Cantéolo! Como não me lembrei dela?$B$BEla foi sequestrada por Arnak anos atrás, quando ele quis obrigá-la a se tornar noiva dele. Ela conseguiu escapar, mas, em meio a toda a confusão causada pelos recentes ataques à Aldeia Vento Livre, ele a capturou novamente.$B$BVamos procurá-la. Ela se tornou uma xamã e tanto nos últimos anos, e vai compreender o que significa o aparecimento do chocalho, do pergaminho e dos tambores.', '', '', '', '', '', '', '', '', '', '', 0),
(27359, 'ptBR', 'Reforços argênteos', 'Colete 4 Essências de Banshee.', 'O Flagelo conta com um tipo de proteção mágica no local que me impede de abrir um portal e enviar nossos reforços para ajudar na tomada da cidade! Essa proteção é como uma gritaria sem fim dentro da minha cabeça! Agh!$B$BEstou fazendo tudo que posso para manter minha sanidade em meio a todos esses gritos horrendos. Provavelmente são as banshees que estão mantendo a defesa. Se você puder me trazer a essência de alguma dessas banshees, creio que posso usá-la para contra-atacar a barreira e então colocar nossos garotos lá dentro!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Arquimaga Ângela Santoro.', 0),
(27360, 'ptBR', 'Vingue nossos soldados', 'Mate 10 Tripulantes de Submarino da 7ª Legião.', '7ª Legião... Eles nos surpreenderam na calada da noite. O capitão deles rugia ordens enquanto os tripulantes do submarino massacravam meus homens. Então ele chegou perto de mim, aproximou o rosto do meu e disse algo que jamais esquecerei:$B$B"Meu nome é primeiro-sargento Pietro Zaren, oficial da 7ª Legião. Quando você vir seus soldados sendo massacrados em seus pesadelos – se você ainda for capaz de sonhar – lembre-se do meu nome e trema de pavor."$B$BVingue meus soldados! Mate os membros da 7ª Legião ocupando o Distrito da Catedral em Guilnéas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Rutsak na Guarda de Rutsak, que fica nas Ruínas de Guilnéas.', 0),
(27361, 'ptBR', 'Protegido pela Luz', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante do Comandante Floraval, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', 'A Luz é forte e verdadeira tanto em você quanto em suas ações a favor da Aliança, $n. Você é um exemplo para todos os nossos sacerdotes e companheiros de combate.$B$BComo reconhecimento por esses feitos, o Rei Wrynn ordenou que o encantador real crie um cajado especial para você.$B$BEntretanto, os materias necessários encontram-se na amaldiçoada Bastilha da Presa Negra, que fica na Floresta de Pinhaprata. Vá até lá e encontre o símbolo sagrado do comandante Floraval. Traga também um feixe de lunalenha e as essências dos espíritos que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Lucas Cordel no Distrito dos Magos, em Ventobravo.', 0),
(27362, 'ptBR', 'Protegido de Eluna', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante Floraval, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', 'Você é $Gum verdadeiro filho:uma verdadeira filha; de Eluna, $n. Um exemplo para nosso povo e $Gum ferrenho defensor:uma destemida defensora; da Aliança. O Templo da Lua e a corte de Ventobravo desejam honrá-$Glo:la; por suas conquistas.$B$BNós ordenamos que o encantador real crie um cajado especial para você.$B$BEntretanto, as matérias-primas necessárias encontram-se na amaldiçoada Bastilha da Presa Negra, que fica na Floresta de Pinhaprata. Vá até lá e encontre o símbolo sagrado do comandante Floraval. Traga também um feixe de lunalenha e essências dos espíritos que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Lucas Cordel no Distrito dos Magos, em Ventobravo.', 0),
(27363, 'ptBR', 'Um jovem e promissor cirurgião', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante do Comandante Floraval, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', 'Você se mostrou $Gum:uma; incrível $Gsacerdote:sacerdotisa; e um exemplo a ser seguido pelo povo de Gnomeregan, $n. O Grão-faz-tudo e o rei de Ventobravo desejam agradecer a sua contribuição à Aliança.$B$BEles ordenaram que o encantador real crie um cajado especial para você.$B$BEntretanto, os materias necessários encontram-se na amaldiçoada Bastilha da Presa Negra, que fica na Floresta de Pinhaprata. Vá até lá e encontre o símbolo sagrado do comandante Floraval. Traga também um feixe de lunalenha e as essências dos espíritos que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Lucas Cordel no Distrito dos Magos, em Ventobravo.', 0),
(27364, 'ptBR', 'A mando de quem?', 'Encontre as Ordens do Alto Comando.', '<O D.C.R. emite um zumbido.>$B$BA 7ª Legião é um regimento de operações especiais de elite. Eles têm agido por debaixo dos panos em quase toda ofensiva militar de monta da Aliança. Isso não é bom. Como eles passaram por nossos navios de guerra? E a mando de quem?$B$BPrecisamos botar as mãos nas ordens deles. Esse tal de Pietro com certeza tem informações importantes. Ele está no Distrito da Catedral, em Guilnéas. Elimine-o. Reviste o cadáver e encontre pistas.', '', '', '', '', '', '', 'Primeiro-sargento Pietro Zaren', 'Estamos perdendo o Comando Avançado dos Renegados.', 'Comandante Avançado Chacina', 'Fale com o Comandante Avançado Chacina no Comando Avançado dos Renegados, que fica nas Ruínas de Guilnéas.', 0),
(27365, 'ptBR', 'Uma arma apropriada', 'Vá à Bastilha da Presa Negra e recupere a Espada da Família Silverlaine do Barão Silverlaine, 5 caixas de Lingotes de Lunaço e 5 Tendões Imortais.', 'Desde o começo, os instrutores já sabiam que o seu caminho na Horda seria grandioso. Você tem lutado bravamente e dado boas razões para os inimigos sentirem medo.$B$BComo forma de homenageá-$Glo:la; pela sua dedicação, o chefe guerreiro ordenou que o ferreiro particular dele forje uma arma especial para você.$B$BA amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata, é o único lugar onde você encontrará os materiais necessários. Vá até lá e recupere a espada perdida da família Silverlaine, um carregamento de lingotes de lunaço e tendões dos carniçais e geists que infestam aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Saru Furiácero no Vale da Honra, em Orgrimmar.', 0),
(27366, 'ptBR', 'Apego à terra', 'Mate 12 Fuzileiros Mordacha na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 'Os Fuzileiros Mordacha da Horda estão se espalhando pela minha querida praia.$B$B<O Tenente aponta para o norte, ao longo da costa.>$B$BMate-os.', '', '', '', '', '', '', '', '', '', 'Relate seu sucesso para o Tenente Henri na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27367, 'ptBR', 'Gidwin Fitáurea', 'Encontre Gidwin Fitáurea nas Terras Pestilentas Orientais.', 'Eu amo os meus rapazes, não pense que não. Mas EU AVISEI que eu precisava de CINCO MINUTOS para dar água e escovar os cavalos, e o que eles fizeram? Uma aposta idiota entre si e fugiram! Eu já deveria saber... isso sempre acontece.$b$bGidwin é o baixinho. Ele seguiu para o norte, ao longo do rio. Se você estiver indo nessa direção, será que você mandaria ele voltar? Precisamos chegar à Capela Esperança da Luz e não tenho nada contra ir embora sem ele.', '', '', '', '', '', '', 'Gidwin Fitáurea', '', '', '', 0),
(27368, 'ptBR', 'Recém-preso', 'Obtenha 8 frascos de Bile de Cripta de nerubianos no Túnel Terrorteia.', 'Você devia ter me visto lutando! Eu já tinha matado umas seis daquelas feras, quando...$b$bPera aí, você pode contar os corpos, não pode? Tudo bem então. Eu tinha matado quatro delas quando a quinta me atingiu com esta teia. Para piorar as coisas ainda mais... quando ela me atingiu com a teia líquida, eu estava de boca aberta!$b$bNão consigo arrebentar estas teias e duvido que você consiga. Não, você tem que pegar um pouco do suco estomacal daquelas aranhas mortas-vivas. Isso deve resolver.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gidwin Fitáurea no Rio Thondroril, que fica nas Terras Pestilentas Orientais.', 0),
(27369, 'ptBR', 'Azeitando a roda', 'Colete 10 Sinos da Banshee da margem do Rio Thondroril.', 'Desculpe-me por aquilo. Eu tinha certeza de que você era uma daquelas feras aracnídeas fazendo uma péssima imitação de $r.$b$bMuito prazer, Gidwin Fitáurea, ao seu dispor. Estou com um pouco de pressa para voltar à minha caravana, mas será que você faria um último favor? Minha amiga Fiona tem uma lojinha e provavelmente faria bom uso de um pouco dessas plantas que crescem ao longo da margem do rio.$b$bEu estava pensando que, se dermos umas plantas dessas para ela de presente, ela ficará MUITO MENOS inclinada a me matar. Bem, ao menos é esse o plano.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Fiona no Rio Thondroril, que fica nas Terras Pestilentas Orientais.', 0),
(27370, 'ptBR', 'Tarenar Golpessol', 'Encontre Tarenar Golpessol no Degrau da Morte, que fica nas Terras Pestilentas Orientais.', 'Assim que paramos, eles apostaram "quem consegue matar mais mortos-vivos em cinco minutos".$b$bJá faz uma hora e continuo esperando eles voltarem.$b$bEu vi o Tarenar fugir para o sudeste. Infelizmente, não posso deixar a caravana sem ninguém. Se você estiver viajando nessa direção, será que você poderia encontrá-lo e mandá-lo de volta a mim?', '', '', '', '', '', '', 'Tarenar Golpessol', '', '', '', 0),
(27371, 'ptBR', 'O que faço de melhor', 'Mate 5 Aberrações do Degrau da Morte no Degrau da Morte, que fica nas Terras Pestilentas Orientais.', 'Quando era pequeno, eu costumava entrar escondido na Terra Fantasma para bater em zumbis por horas a fio. Nem precisavam me PAGAR pra isso, eu simplesmente ia lá e fazia.$b$bAgora, olhe só à sua frente. Esses são umas belezas de zumbis, e eu estava prestes a ir bater neles. Você gostaria de se juntar a mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tarenar Golpessol no Degrau da Morte, que fica nas Terras Pestilentas Orientais.', 0),
(27372, 'ptBR', 'Um presente para Fiona', 'Obtenha 10 amostras de Sangue de Cão Pestilento.', 'Minha companheira de viagem, Fiona, tem uma lojinha que mantém com a caravana dela. Ela e eu, assim como nosso amigo Gidwin, estamos a caminho da Capela Esperança da Luz. Tenho certeza de que você pode se juntar a nós, se quiser... apesar da Fiona estar um pouco furiosa comigo.$b$bA Fiona sempre esquece o motivo pelo qual está furiosa quando ganha um presente. Mate alguns dos cães pestilentos ao norte daqui e dê o sangue deles para a Fiona, na caravana, mais adiante ao longo do rio. Ela vai adorar. Voltaremos a conversar lá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Fiona no Rio Thondroril, que fica nas Terras Pestilentas Orientais.', 0),
(27373, 'ptBR', 'Adiante, rumo à Capela Esperança da Luz', 'Suba à bordo da Caravana da Fiona no Rio Thondroril, que fica nas Terras Pestilentas Orientais.', 'Agora que os rapazes estão de volta, podemos prosseguir. Você está indo para o leste?$b$bPor favor, junte-se a nós! Eu insisto! Ontem, estávamos no Acampamento dos Restauradores quando eu falei para o Tarenar: "Temos dois paladinos e uma vendedora, mas sabe do que mais precisamos? De $gum:uma; $c!"$b$bNão me olhe desse jeito! Estou falando sério! Vamos, suba logo no carro.', '', 'Continue com a Caravana da Fiona', '', '', '', '', '', '', '', 'Fale com a Fiona na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 0),
(27374, 'ptBR', 'Ventre da Loucura', 'Fale com o Arauto da Terra Torunscar no Círculo dos Elementos.', 'Não creio nisso, $n. Meu próprio filho – carne da minha carne, sangue do meu sangue – unido àqueles demônios do Martelo do Crepúsculo. Viu no que ele se transformou quando tentou acabar com o casamento? Ai... por quê? Por quê?$B$BÉ aquela fera, $n. Aquela bocarra surgindo da terra a oeste daqui... o "Ventre da Loucura"! Meu filho disse que aquilo falou com ele, mas pensei que fosse só um pesadelo.$B$BA Harmonia Telúrica está tentando destruí-lo. Fale com o arauto da terra Torunscar, a oeste daqui, e veja o que pode ser feito!', '', '', '', '', '', '', '', '', '', '', 0),
(27375, 'ptBR', 'A ferida aberta', 'Fale com o Arauto da Terra Torunscar no Círculo dos Elementos.', 'Uma fera, $n! Vi uma fera. Estômago grande, voracidade maior ainda. Eles não têm ideia do que desencadearam.$B$BEla está aqui. O corpo disforme está irrompendo brutalmente das terras do Planalto.$B$BEu vi você em minhas visões, $n. Você deve pelejar ao lado da Harmonia Telúrica para conter a fera. Você enfrentará as trevas.$B$BVá agora, antes que a fera se fortaleça. Fale com o Arauto da Terra Torunscar no Círculo dos Elementos, a noroeste daqui, acima da cordilheira além das Ruínas do Acampamento Dragkor. Depressa!', '', '', '', '', '', '', '', '', '', '', 0),
(27376, 'ptBR', 'Nas entranhas de Iso\'rath', 'Monte num grifo para se juntar ao ataque a Iso\'rath.', 'Tamos prontos pra atacar a fera. Primeiro, a gente precisa destruir os tentáculos, depois Yevaa vai fazer um ritual para invocar um elemental de fogo fortão que a gente vai jogar no papo dela.$B$BQuero que você decole com nosso primeiro grupo de ataque. Aguarde até ter uma boa oportunidade pra se juntar ao resto dos xamãs e fazer picadinho de tentáculos.$B$BLeve qualquer grifo quando você estiver $gpreparado:preparada; pra atacar.', '', 'Junte-se ao ataque a Iso\'rath', '', '', '', '', '', '', '', 'Fale com a Arauto da Terra Yevaa dentro do estômago de Iso\'rath, no Planalto do Crepúsculo.', 0),
(27377, 'ptBR', 'Devorados', 'Proteja a Arauto da Terra Yevaa e a si $gmesmo:mesma; das defesas corporais de Iso\'rath.', 'Sabíamos desta possibilidade, mas não tínhamos ideia de como a fera iria se defender. O corpo de Iso\'rath está reagindo rápido à nossa ameaça.$B$BPosso terminar a evocação daqui, mas só se tu conseguires rechaçar as defesas de Iso\'rath. Mantenha-as ocupadas! Nós sobreviveremos a isso!', '', 'Sobreviva às defesas de Iso\'rath', '', '', '', '', '', 'No fogo.', 'Thrall', 'Fale com Thrall em Voragem.', 0),
(27378, 'ptBR', 'O Quebramundo', 'Derrote Asa da Morte, o Aspecto da Morte.', 'Não há tempo! Asa da Morte nos atacou antes que pudéssemos nos formar contra ele. Se você não impedi-lo, a Harmonia Telúrica acabará hoje!', '', 'Ajude Thrall na luta contra Asa da Morte', '', '', '', '', 'Asa da Morte', 'Pesadelos ameaçam infestar e dominar a todos que estão dentro de Iso\'rath.', 'Yevaa', 'Fale com a Arauto da Terra Yevaa dentro do estômago de Iso\'rath, no Planalto do Crepúsculo.', 0),
(27379, 'ptBR', 'Os horrores de Iso\'rath', 'Resgate Hargoth Flamaturva, o Reparador da Terra Duarn, a Tempestária Jalara e a Tempestária Mylra.$B$BRetorne para a segurança de um xamã se as defesas de Iso\'rath estiverem consumindo você.', 'Precisamos de ti! Tu estavas $Gpreso:presa; em algum tipo de pesadelo, tal qual os outros xamãs.$B$BIsso não importa... o nosso plano está ruindo. Alguns dos nossos xamãs estão canalizando auras protetoras que podem combater os sucos digestivos e manter-te $Gvivo:viva;, mas temos que resgatar os outros xamãs dos tentáculos. Não vamos conseguir derrotar Iso\'rath sem eles!$B$BNão fiques no estômago sem um xamã por muito tempo ou serás $gdigerido vivo:digerida viva;!', '', 'Salve Hargoth Flamaturva', 'Salve a Tempestária Jalara', 'Salve o Reparador da Terra Duarn', 'Salve a Tempestária Mylra', '', '', '', '', 'Fale com a Arauto da Terra Yevaa dentro do estômago de Iso\'rath, no Planalto do Crepúsculo.', 0),
(27380, 'ptBR', 'Pesadelo', 'Destrua o Cérebro de Iso\'rath.', 'O cérebro de Iso\'rath está à mostra! O xamã que você salvou deve $gmantê-lo:mantê-la; a salvo.$B$BAcerte o cérebro e destrua Iso\'rath!', '', 'Mate Iso\'rath', '', '', '', '', 'Iso\'rath', '', '', 'Fale com o Arauto da Terra Torunscar no Círculo dos Elementos, que fica no Planalto do Crepúsculo.', 0),
(27381, 'ptBR', 'Companheiros de viagem', 'Encontre alguém na Torre da Coroa que queira se juntar à sua caravana.', 'Enquanto esperamos aqui nesta torre, por que não vemos se mais alguém está indo para a Capela Esperança da Luz? Quanto mais, melhor!$b$bPergunte por aí para ver se alguém quer se juntar a nós em nossa viagem. Tenho certeza de que você encontrará alguém a caminho da Esperança da Luz.', '', 'Encontre um companheiro de viagem', '', '', '', '', '', '', '', 'Fale novamente com Tarenar na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 0),
(27382, 'ptBR', 'Estradas tortuosas', 'Mate 13 Quirópragos ao longo do caminho para a Torre Escudo da Luz.', 'A Cruzada Argêntea construiu estas torres para que fossem pontos de luz em meio à escuridão das Terras Pestilentas. Minha função é viajar a cada uma elas, cuidando para que estejam seguras e bem mantidas.$b$bAs estradas têm estado perigosas ultimamente, pois a fauna pestilenta corre desenfreada e morcegos mergulham sobre viajantes incautos. A próxima parte da minha jornada será muito mais fácil se você puder tirar um pouco dessa vida selvagem do meu caminho.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Argus Sinalto na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 0),
(27383, 'ptBR', 'Pequena Pâmela', 'Encontre Pâmela Trilharrubra na Vila das Flechas.', 'A batalha pela Vila das Flechas ainda me assombra, $r. Acordo suando frio, convencido de que ainda estou lá, que aquilo está acontecendo de novo e de novo.$b$bSuportei a perda dos meus companheiros, mas perder os meus familiares ainda me dói profundamente. A minha jovem sobrinha, Pâmela, foi uma da minha linhagem que se foi durante o ataque.$b$bSe você tiver coragem de entrar na Vila das Flechas, pode procurar por algum sinal da Pâmela? As ruínas da Vila das Flechas ficam ao sul daqui.', '', '', '', '', '', '', '', '', '', '', 0),
(27384, 'ptBR', 'A boneca de Pâmela', 'Encontre a boneca de Pâmela.', 'A minha tia Marlene me disse para ficar aqui na nossa casa porque o meu pai teve que sair para lutar. O meu pai é o homem mais corajoso do mundo todo!$B$BMas já estou aqui há muito tempo e ele não voltou. Às vezes, pessoas más vêm aqui e sussurram coisas para mim e meu pai não está aqui para fazer elas irem embora!$B$BE, às vezes, quando fica escuro, eu quero brincar com a minha boneca mas não posso porque deixei ela na cidade.$B$BVocê poderia encontrar a minha boneca para mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pâmela Trilharrubra na Vila das Flechas, que fica nas Terras Pestilentas Orientais.', 0),
(27385, 'ptBR', 'Tio Carlin', 'Fale novamente com Carlin Trilharrubra na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 'Eu vou brincar com a bonequinha, mas acho que não quero mais brincar com a espada do papai. É melhor você ficar com ela.$b$bPensando bem, será que você pode dar ela para o meu tio Carlin? Não sei bem onde ele está, mas ouço ele chorando de vez em quando. O som parece vir de perto, ao norte.$B$BEspero que ele não esteja chorando por minha causa! $n, você pode procurar o meu tio e avisar a ele que estou bem?$B$BSe você conseguir, avise que estou esperando por ele, e quero ouvir a estória que ele costumava contar... aquela sobre os coelhinhos e a geleia de amoras! Aquela estória é tão engraçada!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Carlin Trilharrubra na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 0),
(27386, 'ptBR', 'Uma historiadora estranha', 'Leve a Lâmina de Caça do Josefo para a Crona.', 'Essa espada pertencia a Josefo Trilharrubra, o pai da Pâmela – mas você provavelmente já sabia disso. Eu gostaria que o Josefo pudesse voltar para a filha, mas isso não é possível. A alma dele foi retorcida pelo Flagelo e ele se tornou um monstro.$B$BO destino da Pâmela está selado, mas talvez possamos mudar a sorte do Josefo.$B$BUma estranha gnomida chegou nesta torre há pouco. Ela se chama Crona. Leve essa espada a ela. Pressinto que ela será capaz de nos ajudar.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Crona na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 0),
(27387, 'ptBR', 'Vilões da Vila das Flechas', 'Leve o Crânio de Horgus e a Espada Estilhaçada de Marduk para a Crona, na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 'O livro Os Anais da Vila das Flechas fala dos vilões daquela batalha. Conta como o lorde carniçal Horgus, o Assolador, foi destruído pelas forças da Aliança durante a batalha. Ele foi morto em meio às colinas ao norte daqui, e lá permanece o crânio dele.$B$BApesar de Marduk, o Tenebroso, nunca ter sido vencido, a lendária espada dele agora enferruja, abandonada. Ela pode ser encontrada próxima à estrada a sudeste.$B$BRecupere esses itens, $n. Não sei o porquê, mas estou certa de que o destino deles é com você.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Crona na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 0),
(27388, 'ptBR', 'Heróis da Vila das Flechas', 'Obtenha os Anais Estendidos da Vila das Flechas com o Carlin Trilharrubra, e obtenha o Incunábulo de Davil e o Escudo de Trilharrubra no Sítio dos Marris.', 'Os heróis da Vila das Flechas tinham suas próprias relíquias, e dentro dessas relíquias, residem mais lembranças preciosas.$B$BPrimeiro, fale com Carlin e obtenha os Anais Estendidos da Vila das Flechas. No tomo está a narrativa que levará a nossa excursão através do tempo.$b$bFeito isso, você terá que ir para o oeste até o Sítio dos Marris. O antigo dono da casa de fazenda dos Marris colecionava relíquias da batalha da Vila das Flechas – por que motivo, não sei dizer.$B$BColete essas relíquias e torne a falar comigo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Crona na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 0),
(27389, 'ptBR', 'Espoliadores da Vila das Flechas', 'Leve 5 Crânios Ressonantes para a Crona na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 'Eu preciso de um reagente para o poderoso feitiço que pretendo lançar: crânios dos flagelados que participaram da batalha da Vila das Flechas.$B$BPegue este cristal, cace campeões do Flagelo e tome-lhes os crânios. O cristal é encantado; se um campeão participou da batalha, o cristal ressonará ao ser passado sobre o crânio. Traga-me esses crânios ressonantes.$B$BVá, $n. Você encontrará campeões do Flagelo no Vale Fungi ao norte. Vá.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Crona na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 0),
(27390, 'ptBR', 'A batalha pela Vila das Flechas', 'Coloque o Saco de Relíquias na praça da Vila das Sombras.$B$BImpeça que Davil Luminoso morra antes de Horgus.$B$BImpeça que o Capitão Trilharrubra morra antes que Trilharrubra, o Corrompido, surja.$B$BDerrote Trilharrubra, o Corrompido.$B$BFale com o espírito de Josefo Trilharrubra quando ele aparecer na praça.', 'Agora, $n, você participará da batalha pela Vila das Flechas e salvará Josefo Trilharrubra.$B$BColoque este saco de relíquias na praça da Vila das Flechas para que os espíritos da Vila das Flechas se levantem. Lute ao lado deles e se certifique que essas duas coisas aconteçam: o Davil tem que sobreviver à morte de Horgus e o Trilharrubra precisa sobreviver para ser corrompido e, então, vencido.$B$BDepois que você vencer o Trilharrubra corrompido, o espírito dele poderá voltar à filha Pâmela.', '', 'Aceite o perdão do Trilharrubra', '', '', '', '', '', '', '', 'Fale novamente com Pâmela Trilharrubra na Vila das Flechas, que fica nas Terras Pestilentas Orientais.', 0),
(27391, 'ptBR', 'Tesouros escondidos', 'Leve a Chave de Josefo ao Baú do Josefo.', 'O papai me disse para te dar esta chave. Ele disse que ela abre um baú que fica atrás da casa.$B$BEle também pediu que eu te agradecesse. Você fez algum favor para ele? Você contou para ele que você encontrou a minha boneca?$B$BBem, aqui está a chave. E obrigada, $n. Obrigada! Você é $gum homem muito bom:uma mulher muito boa;!', '', '', '', '', '', '', '', '', '', '', 0),
(27392, 'ptBR', 'Eu não deveria te contar isso', 'Obtenha a Lâmina de Caça do Josefo do Caçador Solitário nas Terras Pestilentas Orientais.', 'O papai sempre teve duas espadas: uma para lutar com homens e outra para lutar com animais. Não era para eu mexer nas espadas dele, mas eu sabia onde ele escondia elas.$b$bUm dia, ele disse para a mamãe que ele ia lutar contra um "caçador solitário" nas colinas a leste, mas ele levou a espada de animais! Quando ele voltou, não estava mais com a espada.$b$bQuando o papai voltar, ele vai ficar tão feliz quando eu der para ele a espada de animais! Será que você poderia encontrar ela?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pâmela Trilharrubra na Vila das Flechas, que fica nas Terras Pestilentas Orientais.', 0),
(27393, 'ptBR', 'O chamado da espada', 'Investigue o campo de batalha na extremidade sul das Ruínas de Vashj\'ir.', 'Sinto uma tremenda força me chamando nas ruínas. Você poderia verificar novamente o campo de batalha ao sul? Tenho certeza de que há algo por lá.', '', '', '', '', '', '', '', '', '', '', 0),
(27394, 'ptBR', 'O chamado da espada', 'Investigue o campo de batalha na extremidade sul das Ruínas de Vashj\'ir.', 'Sinto uma tremenda força me chamando nas ruínas. Você poderia verificar novamente o campo de batalha ao sul? Tenho certeza de que há algo por lá.', '', '', '', '', '', '', '', '', '', '', 0),
(27395, 'ptBR', 'A verdadeira arma de um atirador', 'Vá à Bastilha da Presa Negra e consiga a Mira de Cristal de Godfrey, 5 feixes de Lunalenha e 5 Tendões Imortais.', 'Você tem trilhado rápido o caminho do caçador, $n. Suas habilidades $Go:a; tornaram um trunfo para a Horda e um exemplo para os mais jovens.$B$BComo recompensa pelo trabalho exemplar, o chefe guerreiro ordenou que o arqueiro particular dele crie uma arma sem igual!$B$BA amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata, é o único lugar onde você encontrará os materiais necessários. Vá até lá e consiga a mira da arma do Lorde Godfrey, alguns feixes de lunalenha e tendões dos carniçais e geists que infestam aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Saru Furiácero no Vale da Honra, em Orgrimmar.', 0),
(27396, 'ptBR', 'Lâmina da Mão Despedaçada', 'Vá à Bastilha da Presa Negra e consiga a Pedra de Amolar de Floraval do Comandante Floraval, 5 caixas de Lingotes de Lunaço e 5 Tendões Imortais.', 'Muitos membros da Mão Despedaçada não sobrevivem ao treinamento, $n. Você não apenas sobreviveu, como sua lâmina logo será temida por todos!$B$BComo recompensa pelo desempenho apresentado, o chefe guerreiro ordenou que o ferreiro particular dele forje uma arma para você.$B$BA amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata, é o único lugar onde você encontrará os materiais necessários. Vá até lá e recupere a pedra de amolar do comandante Floraval, um carregamento de lingotes de lunaço e tendões dos carniçais e geists que infestam aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Saru Furiácero no Vale da Honra, em Orgrimmar.', 0),
(27397, 'ptBR', 'A tarefa de Terga', 'Vá à Bastilha da Presa Negra e consiga o Talismã de Walden do Lorde Walden, o Livro das Almas Perdidas e 5 Essências Fantasmagóricas.', 'As vozes dos espíritos e dos elementos soam claras para você, $n. Você se tornou $Gum poderoso:uma poderosa; xamã e um exemplo a ser seguido por todos da Horda.$B$BNotícias sobre seus feitos chegaram aos ouvidos do chefe guerreiro, que ordenou que o ferreiro particular dele forje uma arma especial para você.$B$BA amaldiçoada Bastilha da Presa Negra, dentro da Floresta de Pinhaprata, é o único lugar onde é possível encontrar os materiais necessários. Vá e traga o talismã de Walden, o Livro das Almas Perdidas e a essências dos fantasmas que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Saru Furiácero no Vale da Honra, em Orgrimmar.', 0),
(27398, 'ptBR', 'Ganhamos a batalha, mas não a guerra', 'Fale com Naraat, a Voz da Terra, no Santuário Oriental da Terra, em Ventobravo.', 'Derrotamos as forças inimigas daqui, $n. No entanto, Hyjal não é o único local onde nossos inimigos avançam.$B$BFui informado de que nossos aliados na Harmonia Telúrica pediram ajuda em um caso de extrema urgência.$B$BFale com Naraat, a Voz da Terra, no Santuário Oriental da Terra, que fica na cidade de Ventobravo, para maiores instruções.', '', '', '', '', '', '', '', '', '', '', 0),
(27399, 'ptBR', 'Ganhamos a batalha, mas a guerra continua', 'Fale com o Clarividente Krogar, no Santuário Ocidental da Terra, que fica em Orgrimmar.', 'Derrotamos as forças inimigas daqui, $n. No entanto, Hyjal não é o único local onde nossos inimigos avançam.$B$BFui informado de que nossos aliados na Harmonia Telúrica pediram ajuda em um caso de extrema urgência.$B$BFale com o clarividente Krogar no Santuário Ocidental da Terra, que fica em Orgrimmar, para maiores instruções.', '', '', '', '', '', '', '', '', '', '', 0),
(27400, 'ptBR', 'O domínio do poder arcano', 'Vá à Bastilha da Presa Negra e consiga o Cristal Encantado de Silverlaine do Barão Silverlaine, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', '$n, todos os instrutores concordam que você possui um talento incrível para alguém tão jovem. Até mesmo o chefe guerreiro ficou impressionado com sua rápida jornada.$B$BComo recompensa por se dedicar tanto, o chefe guerreiro ordenou que o mestre encantador crie um cajado para você.$B$BA amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata, é o único lugar onde você encontrará os materiais necessários. Vá até lá e consiga a herança mágica da família Silverlaine, alguns feixes de lunalenha e as essências dos fantasmas que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Godan no Bazar, em Orgrimmar.', 0),
(27401, 'ptBR', 'O que nos traz o dia de amanhã', 'Use o Telescópio da 7ª Legião para Vasculhar o Cais.', '<O D.C.R. zumbe.>$B$BProcure no Distrito da Catedral. Deve haver um telescópio por perto que a 7ª Legião usa para espionar. Encontre-o e use-o para investigar o cais. Precisamos descobrir como a 7ª Legião passou pela nossa esquadra.$B$BApresse-se, $n. Não vamos conseguir segurar esses bichos por muito mais tempo.$B$BO que nos traz o dia de amanhã?', '', 'Use o Telescópio da 7ª Legião para Vasculhar o Cais.', '', '', '', '', 'Comandante Avançado Chacina', 'Nós fomos torpedeados!', 'Comandante Avançado Chacina', 'Fale com o Comandante Avançado Chacina no Comando Avançado dos Renegados, que fica nas Ruínas de Guilnéas.', 0),
(27402, 'ptBR', 'Prova de poder', 'Vá à Bastilha da Presa Negra e consiga o Orbe Tenebroso do Lorde Godfrey, o Livro das Almas Perdidas e 5 Essências Fantasmagóricas.', 'Seu domínio sobre as nossas artes continua a crescer rapidamente, $n, e eu não sou o único impressionado com esse progresso. Até mesmo o chefe guerreiro está sabendo dos seus feitos.$B$BComo recompensa por essa dedicação, o chefe guerreiro ordenou que o encantador particular dele crie um cajado.$B$BA amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata, é o único lugar onde você encontrará os materiais necessários. Vá até lá e consiga o tenebroso orbe guardado pelo Lorde Godfrey, o Livro das Almas Perdidas e as essências dos fantasmas que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Godan no Bazar, em Orgrimmar.', 0),
(27403, 'ptBR', 'Um verdadeiro Andarilho do Sol', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante do Comandante Floraval, 5 caixas de Lingotes de Lunaço e 5 Tendões Imortais.', 'Tenho acompanhado seu treinamento, $n. Você trilha o caminho de $Gum:uma; exemplar Andarilh$Go:a; do Sol. De $Gum bravo defensor:uma destemida defensora; da Horda e $Gseguidor:seguidora; dos nossos costumes.$B$BComo forma de homenageá-$Glo:la; pelas suas conquistas, o chefe guerreiro ordenou que o ferreiro particular dele forje uma arma para você.$B$BA amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata, é o único lugar onde você encontrará os materiais necessários. Vá até lá e recupere o símbolo sagrado do comandante Floraval, um carregamento de lingotes de lunaço e tendões dos carniçais e geists que infestam aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Saru Furiácero no Vale da Honra, em Orgrimmar.', 0),
(27404, 'ptBR', 'O futuro do Círculo', 'Vá à Bastilha da Presa Negra e consiga os Elixires de Walden de Lorde Walden, 5 feixes de Lunalenha e 5 Tendões Imortais.', 'O Círculo Cenariano está feliz com as suas conquistas, $n. Você é um exemplo a ser seguido por todos os druidas, e em você nós vemos o futuro de nossa irmandade.$B$BO Círculo decidiu honrá-$Glo:la; com a criação de um cajado único.$B$BAs raras e poderosas matérias-primas necessárias para forjá-lo encontram-se na Bastilha da Presa Negra, na Floresta de Pinhaprata. Vá e me traga a coleção de elixires de Lorde Walden, alguns carregamentos de Lunalenha e tendões dos carniçais e geists que habitam a bastilha.', '', '', '', '', '', '', '', '', '', 'Fale com Narianna no Refúgio Noturno, que fica na Clareira da Lua.', 0),
(27405, 'ptBR', 'Recuar!', 'Encontre o Comandante Sicário Belmonte na Vila da Pedra Incandescente, que fica nas Ruínas de Guilnéas.', '<O D.C.R. zumbe.>$B$B<Uivos podem ser ouvidos ao fundo.>$B$B$n, pode me ouvir? Responda, $n. Essa é minha última transmissão. Os worgens invadiram o Comando Avançado dos Renegados. É só questão de tempo até que a base caia. Belmonte e Artura, a val\'kyr, já partiram. Belmonte mencionou que eles vão se encontrar com você na Vila da Pedra Incandescente, a nordeste de sua posição. Encontre Belmonte, $n. Nossa missão – nossa própria existência – depende disso.$B$BVocê é nossa última esperança.', '', '', '', '', '', '', 'Comandante Avançado Chacina', '', '', '', 0),
(27406, 'ptBR', 'Um homem chamado Godfrey', 'Encontre o cadáver de Lorde Vincent Godfrey.', 'Lorde Vincent Godfrey passou a vida defendendo o reino de Guilnéas. Quando a maldição worgen assolou esta terra, Godfrey foi um dos primeiros guilneanos a pegar em armas contra as feras. Dizem que Godfrey tirou a própria vida quando descobriu que seu próprio rei estava amaldiçoado. Ele preferiu morrer a servir as criaturas que ele havia combatido em defesa da pátria.$B$BVamos dar uma segunda chance a ele, $n. Juntos, vamos lutar e seguir até Tempestária, a sudeste daqui, e recuperaremos o cadáver dele.', '', 'Cadáver de Lorde Vincent Godfrey encontrado', '', '', '', '', '', '', '', 'Fale com o Comandante Sicário Belmonte nas Ruínas de Guilnéas.', 0),
(27407, 'ptBR', 'Penas de Dinossangue', 'Colete 5 Penas de Dinossangue dos Raptores Dinossangue.', 'A presença de Brogg te incomoda, $gpequeno:pequena; $r? Os goblin da Coroa de Barro é amigo de Brogg; você também pode ser.$B$BBrogg deixou a Aldeia Muralha Verde quando novo lorde supremo não se vinga dos dragão negro que destrói casa e amigos do Brogg. Brogg aqui pra vingar espíritos dos amigo e colocar eles pra descansar, mas Brogg precisa ajuda. Brogg precisa pena de magia forte pra ritual, penas de raptor, dos raptor do Antro do Dinossangue lá pra oeste da cidade.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Brogg em Coroa de Barro, que fica no Pântano Vadeoso.', 0),
(27408, 'ptBR', 'O estandarte de Pedramalho', 'Recupere o Estandarte de Pedramalho do Antro das Chamas.', 'Quando dragões vieram destruir casa antiga de Brogg, ogros de Pedramalho fugir e deixar tudo pra trás, também estandarte do clã.$B$BBrogg sabe que o estandarte ficava no morro dos ogros de Pedramalho, mas hoje morro chamar Antro das Chamas. Brogg precisa ter estandarte do clã para se vingar de dragão que matou amigo.$B$BO morro antigo do clã de Brogg, o Antro das Chamas, ser noroeste da Coroa de Barro e tá infestado de draconiano. Estandarte estar bem no fundo da caverna. Tenha cuidado, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Brogg em Coroa de Barro, que fica no Pântano Vadeoso.', 0),
(27409, 'ptBR', 'A essência da inimizade', 'Leve 10 Essências de Draconiano Negro para Brogg em Coroa de Barro.', 'Para fazer totem, Brogg vai precisar fazer ritual e, pra fazer ritual, Brogg precisa de essência de criaturas que matar amigos de Brogg. A mágica da vingança de Brogg ser enchida da raiva e do ódio dos inimigos de Brogg.$B$BVocê matar flamigrenhas cauda cinza, batedores flamigrenha e escamortes flamigrenha e usar totem de Brogg em carcaça. Só quando o draconiano morrer ele liberar sua essência.$B$BAs criaturas que você buscar infestar o Antro das Chamas noroeste daqui e as Ruínas Pedramalho no norte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Brogg em Coroa de Barro, que fica no Pântano Vadeoso.', 0),
(27410, 'ptBR', 'Os espíritos do Acampamento dos Pedramalho', 'Dê o descanso a 10 Espíritos de Pedramalho nas Ruínas Pedramalho.', 'Brogg ter montado totem que vai fazer espíritos dos amigos de Brogg descansar. Quando draconiano vier, eles matar todos os Pedramalho que não fugir. Brogg fugir com o lorde supremo Mok\'Morokk, esperando liderar contra-ataque com os outros sobreviventes Pedramalho.$B$BContra-ataque nunca acontecer e os Pedramalho mortos ainda assombrar Brogg e os outros. Leve esse totem pro norte, nas Ruínas Pedramalho, e use ele perto dos esqueletos de ogro para chamar os espíritos.', '', 'Espíritos dos Pedramalho descansando', '', '', '', '', '', '', '', 'Fale novamente com Brogg em Coroa de Barro, que fica no Pântano Vadeoso.', 0),
(27411, 'ptBR', 'O desafio à Revoada Negra', 'Posicione o Estandarte de Pedramalho perto da entrada do Covil da Onyxia e enfrente todos que responderem ao desafio.', 'Brogg feliz só de pensar em vingança contra draconianos negros do pântano. $n, você ter sido de grande ajuda para Brogg. Você ajudar de novo?$B$BLevar estandarte do clã de Brogg e viajar leste até ver caverna que parece boca de dragão. Na entrada da caverna, colocar estandarte Pedramalho e dizer que Brogg desafia Onyxia.$B$BBrogg e os Pedramalho vai ter suas terras de volta!', '', 'Clã Pedramalho vingado', '', '', '', '', '', '', '', 'Fale novamente com Brogg em Coroa de Barro, que fica no Pântano Vadeoso.', 0),
(27412, 'ptBR', 'PROCURA-SE: Garra Sanguinária, o Voraz', 'Mate Garra Sanguinária, o Voraz, e apresente-se a Drazzit Pingajunta em Coroa de Barro.', 'Viajantes e funcionários do Bondebico trabalhando no campo devem evitar o Antro do Dinossangue, a oeste da cidade.$B$BA área está infestada de raptores liderados pelo cruel Garra Sanguinária, o Voraz, que já matou dois engenheiros do Bondebico.$B$BDrazzit Pingajunta está oferecendo uma generosa recompensa para o indivíduo que livrar a Coroa de Barro dessa ameaça.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Drazzit Pingajunta em Coroa de Barro, que fica no Pântano Vadeoso.', 0),
(27413, 'ptBR', 'Erva da serpe', 'Colete 8 Rabos-de-serpe na Draconumbra ou no Pântano da Serpe.', 'Com o atraso na entrega dos suprimentos por causa da queda do zepelim, a gente acabou ficando sem medicamentos e bandagens.$B$BA gente tá se virando com o que tem, claro... Mas eu tô ficando maluco com tantos insetos, tantos ferimentos e tantos inimigos! Encontrei uma erva que parece ser cicatrizante e analgésica, mas até isso está acabando.$B$BO nome da planta é rabo-de-serpe, e ela cresce na Draconumbra e no Pântano da Serpe, ao leste da cidade. Tem uns talos em espiral e parece pulsar quando alguém olha para elas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gizzix Gargaressujo, em Coroa de Barro, que fica no Pântano Vadeoso.', 0),
(27414, 'ptBR', 'Identificando a ninhada', 'Draz\'Zilb, na Aldeia Muralha Verde, quer que você traga 7 Línguas Calcinantes e 7 Corações Calcinantes.', 'Enquanto aquele covarde do Mok\'Morokk refestela-se com seu poder e Tharg trava um embate com os demônios do sofrimento e da vingança, almejando a liderança do clã, eu pareço ser o único preocupado em identificar a origem da agressão ao nosso antigo lar.$B$BPor que a cara de espanto, $n? Esperava que eu falasse como um rufião inculto pelo mero fato de que sou um ogro?$B$BDe volta aos negócios: traga-me os corações e as línguas dos dragonetes e dos filhotes. Desvelarei a origem desse mal...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Draz\'Zilb na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(27415, 'ptBR', 'A linhagem de Onyxia', 'Destrua 5 Ovos de Onyxia.', 'A linhagem de Onyxia está espalhada por Draconumbra. É mister impedir que doravante qualquer dragonete nasça.$B$BCorra como o vento para o Pântano da Serpe, ao sul do Pântano Vadeoso. Ela fez de lá seu covil. Encontre os ovos dos dragões malignos e destrua-os.$B$BNunca reaveremos a Vila Pedramalho se as áreas circundantes permanecerem servindo de campos de reprodução.$B$BQuanto a Mok\'Morokk... Tenho outros planos para o imbecil.', '', 'Ovo de Onyxia destruído', '', '', '', '', '', '', '', 'Fale novamente com Draz\'Zilb na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(27416, 'ptBR', 'A linhagem de Onyxia', 'Fale com o Lorde Supremo Mok\'Morokk na Aldeia Muralha Verde.', 'A Vila Pedramalho foi invadida pela linhagem de Onyxia. Mas por que a filha do lorde-dragão negro, o Asa da Morte, escolheria as nossas terras?$B$BIsso é o mais intrigante. Decerto Onyxia se dirigiu para cá com um propósito maior que espalhar o terror num pequeno bando de ogros.$B$BFale com Mok\'Morokk imediatamente! Alguma ação tem de ser tomada.', '', '', '', '', '', '', '', '', '', '', 0),
(27417, 'ptBR', 'A linhagem de Onyxia', 'Fale com Draz\'Zilb na Aldeia Muralha Verde.', 'Deixa Mok\'Morokk em paz. Diz pra Draz\'Zilb que nós fica.', '', '', '', '', '', '', '', '', '', '', 0),
(27418, 'ptBR', 'Desafie o lorde supremo Mok\'Morokk', 'Derrote Mok\'Morokk e leve a notícia para Draz\'Zilb na Aldeia Muralha Verde.', 'Ousa desafiar o lorde supremo Mok\'Morokk?$B$BHar!$B$BEu esmaga $r $Gpequeno:pequena;! $r insignificante!$B$BFala com eu quando querer apanhar.', 'Expulse o Lorde Supremo Mok\'Morokk da Aldeia Muralha Verde', '', '', '', '', 'Expulse o Lorde Supremo Mok\'Morokk da Aldeia Muralha Verde', '', '', '', 'Fale novamente com Draz\'Zilb na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(27419, 'ptBR', 'O exército dos dragões negros', 'Tharg, na Aldeia Muralha Verde, quer que você mate 10 Batedores Flamigrenha, 10 Caudas Cinza Flamigrenha e 5 Escamortes Flamigrenha.', 'Rexxar nomeou Mok\'Morokk como Lorde Supremo. Ele deseja poder mais que nosso bem.$B$BDragão negro matar muitos ogros. Matar mulher de Tharg. Mok\'Morokk mandar ogros fugir. Trazer ogros aqui.$B$BOgros têm que lutar. Ogro não corre. Mok\'Morokk só olha barriga de Mok\'Morokk.$B$BTharg chamar as Ruínas Pedramalho de casa. Tharg gostar do sul. Aqui não ser casa.$B$BAjuda ogro lutar contra dragão negro. Tharg quer vingança. Tharg quer ir para casa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tharg na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(27420, 'ptBR', 'Adiando o inevitável', 'Obtenha as Runas de Controle de Sectários Sombrios e Umbramantes e então, use a Partícula Sobrecarregada neles para destruir 3 Disseminadores da Peste.', 'Você tem bons olhos para ter conseguido me ver aqui, escondida em meio ao mato.$b$bÀ nossa frente está o Vale Fungi, uma área ainda fortemente controlada pelo Flagelo. Eles usam constructos flutuantes para empestear seguidamente a região, mantendo-a vil e poluída.$b$bOs dispositivos são controlados por runas, as quais ficam nas mãos de adeptos das trevas e umbramantes. Pegue as runas de controle que esses sectários possuem, mire-as nos disseminadores da peste e então, sobrecarregue-os com esta partícula. Os resultados deverão ser divertidos.', '', 'Disseminadores da Peste destruídos', '', '', '', '', '', '', '', 'Fale com Rayne perto da entrada do Vale Fungi, que fica nas Terras Pestilentas Orientais.', 0),
(27421, 'ptBR', 'Em meio à morte, vida', 'Plante as sementes de Rayne no centro de cada uma das três necrópoles do Vale Fungi.', 'As forças do Flagelo fizeram questão de não deixar nada vivo no Vale Fungi – tudo que você encontrará são cascas de cogumelos apodrecidos e vegetação carbonizada. Os três cantos do vale abrigam três grandes necrópoles, as quais eles usam para reanimar os próprios mortos e evocar novos soldados para o campo de batalha.$b$bContudo, mesmo neste lugar mau e mórbido, a vida encontra formas de florescer. Leve as minhas sementes e plante-as nos centros dessas necrópoles. Prove a eles que a vida há de prevalecer.', '', 'Semente plantada na necrópole ao sudeste', 'Semente plantada na necrópole a oeste', 'Semente plantada na necrópole ao nordeste', '', '', '', '', '', 'Fale com Rayne perto da entrada do Vale Fungi, que fica nas Terras Pestilentas Orientais.', 0),
(27422, 'ptBR', 'Uma cidade sob cerco', 'Fale com o Caravaneiro Esmagapedra.', 'Nunca controlaremos as Terras Pestilentas Orientais se não controlarmos Stratholme. O local não somente é de alta importância estratégica, mas também é onde se encontram os líderes do inimigo: Balnazzar e Aurius Rivendare. Seus exércitos de Reanimados e do Flagelo ameaçam arruinar todo o progresso que fizemos até o momento.$B$BCreio que a Cruzada Argêntea é mais que adequada para resolver esse problema. Segue para oeste, atravessando o portão principal de Stratholme e fala com o caravaneiro Esmagapedra. Ele te dará mais instruções.', '', '', '', '', '', '', '', '', '', '', 0),
(27423, 'ptBR', 'Resistir é inútil', 'Mate 20 Combatentes Worgens.', '<O D.C.R. zumbe.>$B$BAqui é a Comandante Lorna Crowley, da Frente de Libertação de Guilnéas. Se você está ouvindo essa mensagem, então sabe que a Aliança mais uma vez controla Guilnéas. Deponha as armas e se renda. Recusa de sua parte implicará na sua morte.$B$BNossas tropas isolaram sua posição e já se encontram a caminho. A resistência é inútil.', '', 'Combatente Worgen morto', '', '', '', '', 'Comandante Lorna Crowley', '', '', 'Fale com o Comandante Sicário Belmonte nas Ruínas de Guilnéas.', 0),
(27424, 'ptBR', 'As preocupações do lorde supremo', 'Pegue a Beberagem, o Rapé e o Cofre de Mok\'Morokk no Pântano Vadeoso.', 'Você se curvar pra lorde supremo Mok\'Morokk!$b$bRexxar fez eu líder poderoso do clã Pedramalho!$b$bEu bom líder. Eu proteger clã.$b$bDragão grande veio incendiar lar antigo. Eu ogro esperto. Achar casa nova pro clã aqui.$b$bEu sair da casa antiga correndo, esquecer coisas. $GPequeno:Pequena; $r, ir pegar minhas coisas. Vai pro sul, encontra bebida gostosa, rapé e cofre de Mok\'Morokk. Eu gostar você depois que fazer o que Mok\'Morokk mandar. Procurar no Antro das Chamas e nas Ruínas Pedramalho... eles estar lá, eu ter certeza!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Lorde Supremo Mok\'Morokk, na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 0),
(27425, 'ptBR', 'Uma conexão temível', 'Apresente-se ao Capitão Dario, no Ponto Norte.', 'Falei com o inspetor Tarem a respeito das evidências que você descobriu nas ruínas da Estalagem Pouso do Umbral. Ele está certo de que as pegadas de cascos e o escudo encontrado apontam para o clã taurino Temível Totem.$B$BHá relatórios indicando um aumento das atividades do Temível Totem no pântano. Isso não pode ser mera coincidência. A pessoa a quem você se apresentará em seguida, o capitão Dario, é especialista no Temível Totem. Siga a saída norte da cidade até a Torre Norte. É o segundo posto da estrada.', '', '', '', '', '', '', '', '', '', '', 0),
(27426, 'ptBR', 'A confirmação das suspeitas', 'Colete 4 Bilhetes dos Temível Totem dos Anciãos Temível Totem e junte-os para formar os Planos de Batalha dos Temível Totem.', 'O Temível Totem pode ser o clã tauren mais beligerante de todos, mas não é de forma alguma desorganizado. Se as tochas que atearam fogo à Estalagem Pouso do Umbral eram do Temível Totem, certamente receberam ordens dos anciãos do clã.$B$BHá um assentamento considerável do Temível Totem chamado Aldeia Casco Negro ao noroeste. Eles o estão usando como base para atacar a torre e eu aposto que você vai encontrar as ordens que procura por lá. Sonde os anciãos da vila procurando pistas a respeito das ordens.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Dario na Torre Norte, que fica no Pântano Vadeoso.', 0),
(27427, 'ptBR', 'As armas dos Temível Totem', 'O Capitão Dario, na Torre Norte, quer você lhe leve 7 Armamentos dos Casco Negro.', 'Se o equipamento que encontrou nas ruínas da estalagem pertenciam ao grupo de ataque do Temível Totem, provavelmente haverá equipamentos iguais no acampamento deles, ao noroeste.$B$BNão conseguimos muitas informações sobre a Aldeia Casco Negro, mas julgando pelo tamanho dos raides, há uma força considerável lá.$B$BUse dos meios que forem necessários para capturar alguns equipamentos para que possamos compará-los àqueles que achou na estalagem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Dario na Torre Norte, que fica no Pântano Vadeoso.', 0),
(27428, 'ptBR', 'A ajuda de Tabetha', 'Fale com Tabetha em sua fazenda.', 'Não posso abrir mão de nenhum homem para ajudar na busca por mais um posto avançado dos Temível Totem, mas acho que conheço alguém que pode ajudar.$B$BBem no fundo do Atoleiro, ao sul daqui, há uma fazendinha. A proprietária, Tabetha, pode parecer uma simples ermitã, mas na verdade ela é uma maga vidente e goza de certo reconhecimento. Siga a estrada na direção sul até a fazenda, peça-lhe ajuda para encontrar os responsáveis pelo massacre da Estalagem Pouso do Umbral.', '', '', '', '', '', '', '', '', '', '', 0),
(27429, 'ptBR', 'Ateie fogo ao Posto Chifrebravo!', 'Use a Tocha de Tabetha para incendiar a Tenda Norte, a Tenda Leste e a Tenda Nordeste no Posto Chifrebravo.', 'Não é necessário ser clarividente para ver os problemas que os meus "vizinhos" novos estão causando. E se, de acordo com o que você diz, esse bando foi responsável pelo incêndio da Estalagem Pouso do Umbral, não há mais motivo para os tolerarmos.$B$BVá lá com esta tocha e volte quando só houver as cinzas no chão. Chifrebravo fica a norte da minha fazenda, perto da estrada. Sério, não dá para se perder: os Temível Totem fizeram um trabalho esplêndido em anunciar sua presença com aqueles totens que eles reverenciam.', '', 'Tenda Norte queimada', 'Tenda Nordeste queimada', 'Tenda Leste queimada', '', '', '', '', '', 'Fale novamente com Tabetha na Fazenda de Tabetha, que fica no Pântano Vadeoso.', 0),
(27430, 'ptBR', 'Seja feita justiça pelos Hyal', 'Fale com o Capitão Garrido Valente na Cidadela do Esteio, que fica em Theramore.', 'Para mim, os Temível Totem não passavam de um incômodo, mas para o capitão Valente era diferente: ele certamente quererá saber dos seus feitos. Dê a ele as boas novas. Diga-lhe que você encontrou e deu um jeito nos responsáveis pelo incêndio da estalagem Pouso do Umbral.$B$BÉ tarde demais para salvar a família de James Hyal, mas talvez os Temível Totem pensem duas vezes antes de atacar qualquer pessoa ligada a Theramore da próxima vez.', '', '', '', '', '', '', '', '', '', '', 0),
(27431, 'ptBR', 'Ajustando o equilíbrio', 'Fale com Harrison Jones na Câmara das Estrelas.', '<Harrison sorri.>$b$bÉ isso, $n. As peças de que precisamos estão escondidas nessas estátuas!$b$bDo jeito que estão, elas parecem um pouco desequilibradas. Talvez só um empurrãozinho...$b$bDevo dizer que o seu trabalho de campo está indo bem. Se você se dedicasse, você daria $gum:uma; ótim$go:a; arqueólog$go:a; um dia.', '', 'Ficar fora do caminho de Harrison', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Câmara das Estrelas.', 0),
(27432, 'ptBR', 'Zaeldarr, o Proscrito', 'Obtenha a Cabeça de Zaeldarr, o Proscrito.', 'Dá para acreditar que, mesmo depois de todo o trabalho que tivemos nas Terras Pestilentas... ainda temos que nos preocupar com ladrões? E eles nem são ladrões comuns, são ladrões trolls.$B$BAliás, também não são ladrões trolls comuns, são ladrões trolls mortos!$B$BEles são liderados por esse troll grande e morto chamado Zaeldarr, o Proscrito, e vêm aqui à noite para roubar corpos dos nossos cemitérios e levá-los de volta para o esconderijo maligno, troll e morto deles – a Chácara Secreta, a sudoeste daqui.$B$BVá lá e acabe com Zaeldarr, $n. Estou farto das maldades dele!', '', '', '', '', '', '', 'Zaeldarr, o Proscrito', '', '', 'Fale novamente com Urk Gagbaz na Torre da Coroa, que fica nas Terras Pestilentas Orientais.', 0),
(27433, 'ptBR', 'Desmantelamento', 'Destrua Retalhadores com Lâminas de Diamante para coletar 5 Peças de Retalhadores Danificados.', 'Nossos tanques têm que recuar, e isso significa reparos no campo.$B$BDestrua alguns dos retalhadores com lâminas de diamante que aqueles monstrinhos verdes usam para derrubar árvores pela costa e traga um pouco da sucata que sobrar deles. Vamos juntos botar pra quebrar e deixar nossos tanques seguirem adiante.', '', '', '', '', '', '', '', '', '', 'Leve as peças para Fargo Flintlocke na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27434, 'ptBR', 'O caminho do adepto', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante do Comandante Floraval, 5 caixas de Lingotes de Lunaço e 5 Tendões Imortais.', 'Seu tempo como aprendiz chegou ao fim, $n. Você está $Gpronto:pronta; para se tornar $gum adepto:uma adepta;, $Gum verdadeiro cavaleiro sangrento:uma verdadeira cavaleira sangrenta; a serviço de Luaprata.$B$BComo forma de homenageá-$Glo:la; pelas suas conquistas, o chefe guerreiro ordenou que o ferreiro particular dele forje uma arma para você.$B$BA amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata, é o único lugar onde você encontrará os materiais necessários. Vá até lá e recupere o símbolo sagrado do comandante Floraval, um carregamento de lingotes de lunaço e tendões dos carniçais e geists que infestam aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Saru Furiácero no Vale da Honra, em Orgrimmar.', 0),
(27435, 'ptBR', 'O cajado do vidente', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante do Comandante Floraval, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', 'Aos olhos da Mãe Terra, você está pront$Go:a; para se tornar um vidente. Você completou o treinamento inicial com habilidade e dedicação.$B$BPara celebrar este momento, o chefe guerreiro ordenou que o mestre encantador crie um cajado para você.$B$BA amaldiçoada Bastilha da Presa Negra, na Floresta de Pinhaprata, é o único lugar onde você encontrará os materiais necessários. Vá até lá e consiga o símbolo sagrado do comandante Floraval, alguns feixes de lunalenha e as essências dos fantasmas que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Godan no Bazar, em Orgrimmar.', 0),
(27436, 'ptBR', 'A tarefa do andarilho das sombras', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante do Comandante Floraval, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', 'Essa é uma grande ocasião, $n. Cê aprendeu muita coisa e cresceu nos caminhos do poder. Teu futuro vai ser importante pros Lançanegra e pra Horda.$B$BEu pedi pro mestre encantador do chefe guerreio fazer um cajado pra você... É um jeitinho de dizer obrigado por tudo que tu fez até hoje.$B$BMas os materiais necessários tão tudo lá na Bastilha da Presa Negra, no meio da Floresta de Pinhaprata. Cê vai precisar do símbolo sagrado do comandante Floraval, de uns feixes de lunalenha e de umas essências dos espíritos que tão assombrando aquilo lá. Depois, é só levar tudo pro Godan.', '', '', '', '', '', '', '', '', '', 'Fale com Godan no Bazar, em Orgrimmar.', 0),
(27437, 'ptBR', 'A ordem da clériga das trevas', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante do Comandante Floraval, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', 'Você é assídu$Go:a; nos estudos e dedicad$Go:a; em nossa causa. Enquanto focar seus talentos para satisfazer a vontade da Grande Dama Sylvana, a sombra $Go:a; protegerá.$B$BA nossa rainha providenciou para que o mestre encantador de Orgrimmar crie um poderoso cajado como reconhecimento pelos serviços prestados.$B$BOs materiais necessários só podem ser encontrados na Bastilha da Presa Negra, que fica no coração da Floresta de Pinhaprata. Encontre e traga o símbolo sagrado do comandante Floraval, alguns feixes de lunalenha e as essências dos fantasmas que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Godan no Bazar, em Orgrimmar.', 0),
(27438, 'ptBR', 'A grande fuga', 'Fuja das Ruínas de Guilnéas com Artura e o cadáver de Lorde Godfrey.', 'Agora que cumprimos o objetivo de nossa missão, chegou a hora de fugirmos daqui. Apesar de termos perdido Guilnéas, conseguiremos retomá-la em pouco tempo com Godfrey e seus tenentes nos ajudando. Volte com Artura para a Linha de Frente dos Renegados na parte sul da Floresta de Pinhaprata. A Rainha Banshee espera sua chegada.', 'Escape das Ruínas de Guilnéas.', '', '', '', '', 'Escape das Ruínas de Guilnéas.', '', '', '', 'Fale com a Grande Dama Sylvana Correventos na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27439, 'ptBR', 'Cajado da Luz', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante Floraval, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', 'Você vem rapidamente se tornando $Gum dedicado servo:uma dedicada serva; da Luz e de Luaprata, $n. Sua lealdade ao nosso povo e à Horda é exemplar.$B$BBComo reconhecimento à sua dedicação, o chefe guerreiro ordenou que o mestre encantador crie um cajado para você.$B$BBA amaldiçoada Bastilha da Presa Negra na Floresta de Pinhaprata é o único lugar onde você encontrará as matérias-primas necessários. Vá até lá e consiga o símbolo sagrado do comandante Floraval, alguns feixes de lunalenha e as essências dos fantasmas que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Godan no Bazar, em Orgrimmar.', 0),
(27440, 'ptBR', 'Trolls, ogros, orcs... ai, ai...', 'Mate o Senhor da Guerra Voone, o Grão-lorde Omokk e o Lorde Supremo Wyrmthalak.', 'O draconiano negro conhecido como Lorde Supremo Wyrmthalak supervisiona as forças do Pico Inferior, que estão quase prontas para um lançar um ataque fulminante contra os anões Ferro Negro. Não podemos permitir que a revoada negra tome o controle da montanha!$B$BVocê tem que matar o Senhor da Guerra Voone, o Grão-lorde Omokk e o Lorde Supremo Wyrmthalak. A morte deles impedirá o avanço das tropas, nos dando tempo para agir.', '', '', '', '', '', '', 'Lorde Supremo Wyrmthalak', '', '', 'Fale novamente com Acrídeo.', 0),
(27441, 'ptBR', 'O cajado do vidente', 'Vá à Bastilha da Presa Negra e consiga o Símbolo Sagrado do Comandante do Comandante Floraval, 5 feixes de Lunalenha e 5 Essências Fantasmagóricas.', 'Ouvi dizer que as notícias sobre seus trabalhos pra Horda estão tão falados que chegaram até os ouvidos do chefe guerreiro. Acho que logo ele vai perceber que a primeira impressão que ele teve quanto aos goblins estava errada.$B$BEle até concordou em pedir pro mestre encantador criar um cajado pra você!$B$BA Bastilha da Presa Negra, aquela da Floresta de Pinhaprata, é o único lugar que tem os materiais que você vai precisar. Vai lá e traz o símbolo sagrado do comandante Floraval, uns feixes de lunalenha e umas essências dos fantasmas que assombram aquele lugar.', '', '', '', '', '', '', '', '', '', 'Fale com Godan no Bazar, em Orgrimmar.', 0),
(27442, 'ptBR', 'As muitas frentes de batalha', 'Fale com o Clarividente Krogar, no Santuário Ocidental da Terra, que fica em Orgrimmar.', 'Estamos em uma posição muito melhor aqui em Vashj\'ir do que antes de você chegar. Não me entenda mal, sua ajuda aqui ainda é necessária, porém outras frentes de batalha estão em situações ainda mais urgentes.$B$BFui informado de que nossos aliados na Harmonia Telúrica fizeram um pedido de ajuda em um caso que dizem ser de extrema urgência.$B$BFale com o Clarividente Krogar no Santuário Ocidental da Terra, em Orgrimmar, para obter instruções adicionais.', '', '', '', '', '', '', '', '', '', '', 0),
(27443, 'ptBR', 'As muitas frentes de batalha', 'Fale com Oraterra Naraat no Santuário Oriental da Terra, que fica em Ventobravo.', 'Estamos em uma posição muito melhor aqui em Vashj\'ir do que antes de você chegar. Não me entenda mal, sua ajuda aqui ainda é necessária, porém outras frentes de batalha estão em situações ainda mais urgentes.$B$BFui informado de que nossos aliados na Harmonia Telúrica fizeram um pedido de ajuda em um caso que dizem ser de extrema urgência.$B$BFale com o Oraterra Naraat no Santuário Oriental da Terra, em Ventobravo, para obter instruções adicionais.', '', '', '', '', '', '', '', '', '', '', 0),
(27444, 'ptBR', 'O falso Chefe Guerreiro', 'Mate o Chefe Guerreiro Laceral Mão Negra.', 'Laceral Mão Negra é filho de um antigo Chefe Guerreiro orc. O pai dele foi morto por Orgrim Martelo da Perdição, que se tornou o novo Chefe, ignorando o jovem orc. Hoje, Laceral se impõe como líder de uma falsa Horda de orcs Rocha Negra que tem o apoio de Nefarian e seu exército de dragões.$B$BO tolo afirma que a Horda é dele por direito de sangue e agora ameaça tomá-la usando a força! Não podemos permitir. Encontre-o no Pináculo Superior e ponha um fim neste falso Chefe Guerreiro, $c.', '', '', '', '', '', '', 'Chefe Guerreiro Laceral Mão Negra', '', '', 'Fale novamente com Acrídeo.', 0),
(27445, 'ptBR', 'General Drakkisath, o braço direito de Nefarian', 'Mate o General Drakkisath.', 'Nefarian vive na parte mais alta da montanha no Covil Asa Negra. Existem duas entradas: uma através da passagem no Pináculo Superior; outra usando um orbe de teleportação aqui perto. Entretanto, não podemos usá-lo sem chegar antes a um outro orbe.$B$BDrakkisath, o general dos exércitos de Nefarian, guarda tal artefato. Elimine-o e obtenha o orbe para que possamos usá-lo. Você o encontrará no Trono da Espícula, dentro do Pináculo Superior.', '', '', '', '', '', '', 'General Drakkisath', '', '', 'Fale novamente com Acrídeo.', 0),
(27446, 'ptBR', 'O chamado de Tanaris', 'Fale com Kelsey Fagulhaço em Geringontzan, que fica em Tanaris.', 'Opa, $n! A Kelsey Fagulhaço, lá de Tanaris, deixou um recado para você. Ela disse que os gnomos de Geringontzan ficaram sabendo de tudo o que você tem feito por aqui.$B$BBem, o Cataclismo também atingiu eles em cheio. Aqui foi pior, mas tenho certeza de que você vai poder ajudar o pessoal de lá também.', '', '', '', '', '', '', '', '', '', '', 0),
(27447, 'ptBR', 'O chamado de Tanaris', 'Fale com Carlota Tomanota em Geringontzan, que fica em Tanaris.', 'Opa, $n. A Carlota Tomanota de Tanaris deixou uma mensagem para você. Ela disse que os goblins de lá ficaram sabendo de tudo o que você tem feito por aqui.$B$BDe todo jeito, o Cataclismo acertou eles em cheio. Não tanto quanto nos acertou, mas tenho certeza de que você vai poder ajudá-los.', '', '', '', '', '', '', '', '', '', '', 0),
(27448, 'ptBR', 'A jornada continua', 'Embarque na Caravana da Fiona quando você estiver pront$go:a; para seguir para a próxima torre.', 'Acho que os cavalos estão prontos. Argus Sinalto, o cavalheiro que trabalha com a Cruzada Argêntea, falou comigo mais cedo. Parece que ele prosseguirá conosco... ótimo! Abrirei espaço para ele.$b$bSei que você está ocupad$go:a;, então não há pressa. Assim que você estiver pront$go:a;, embarque na caravana e prosseguiremos para a próxima torre.', '', 'Siga com a Caravana da Fiona', '', '', '', '', '', '', '', 'Fale com a Fiona na Torre Escudo da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27449, 'ptBR', 'Honra e força', 'Passe no teste de força de Vex\'tul.', 'Meu nome é Vex\'tul e venho observando você lutar, $r. Você é forte.$b$bVocê matou o meu mestre, Zaeldarr, mas isso não me incomoda. Dou mais valor à força do que à lealdade que eu tinha por ele. Dou mais valor à força do que à qualquer outra coisa.$b$bProve-me mais uma vez a sua força, $r. Faça isto, e emprestarei a MINHA força a você, para qualquer propósito que você desejar.', '', '', '', '', '', '', '', '', '', 'Fale com Vex\'tul na Torre Escudo da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27450, 'ptBR', 'O apreço de Frederick por peixes', 'Obtenha 8 Baiacus Empesteados, 8 Caramujões de Infectis e 8 Caranguejos-aranha de Infectis da Fenda Infectis.', 'Eu amo o mar. Sim, fui eu, Frederick Calston, que introduzi a vida marinha naquele lago a sudoeste. Eu esperava fornecer à Cruzada uma fonte de comida fresca dentro das fronteiras das Terras Pestilentas.$b$bEntretanto, acabou que alguns dos peixes que coloquei lá são predadores e agora, aterrorizam os outros animais. Se não tivermos cuidado, ele vão matar todos os outros!$b$bNade até o fundo da fenda e salve alguns caramujos, caranguejos e baiacus antes que seja tarde demais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Frederick Calston na Torre Escudo da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27451, 'ptBR', 'Matar com propósito', 'Viaje para o Cruzamento de Corin, ao sul, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada.', 'Saudações, estranh$go:a;! Você adentrou o coração das Terras Pestilentas. Espero que você tenha trazido o seu equipamento de matar mortos-vivos.$b$bA peste tem se espalhado mais devagar atualmente, então a Seita dos Malditos aumentou a produção para manter a terra marrom e morta, do jeito que eles gostam. Mas eu tenho um plano para impedi-los. Leve o meu almofariz e pilão e use-os na putrefação viva das criaturas mortas-vivas no Cruzamento de Corin, ao sudeste. Vamos preparar um presentinho para os sectários!', '', '', '', '', '', '', '', 'Tome cuidado com aquela putrefação!', 'Betina Bigozinco', 'Fale novamente com Betina Bigozinco na Torre Escudo da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27452, 'ptBR', 'Traje Sombrio', 'Obtenha um Capuz de Sectário da Morte e Vestes de Sectário da Morte de sectários no Cruzamento de Corin.', 'Alguns dos meus colegas me disseram que a região quer se curar, mas vários mortos-vivos de alto escalão, junto com a Seita dos Malditos, não estão deixando. Isso significa que precisamos pará-los! Eu tenho um plano, mas antes precisamos de um disfarce de sectário.$b$bVá para o Cruzamento de Corin, a sudeste, e pegue a roupa dos sectários humanos que perambulam pela cidade. Entrarei em contato quando você tiver completado esta etapa.', '', '', '', '', '', '', '', 'Isso vai ser ótimo!', 'Betina Bigozinco', 'Fale novamente com Betina Bigozinco na Torre Escudo da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27453, 'ptBR', 'Catalisação', 'Use o Frasco de Betina nos elementais vivos dentro do Lago Mereldar para obter 8 Agentes Pestilentos Líquidos Ativos.', 'Putrefação coagulada já é potente por si só, mas precisamos de algo para ativar os poderes escondidos nela... um catalisador. Você encontrará um catalisador perfeito ao sul, no Lago Mereldar.$b$bSe você olhar para baixo, notará que coloquei um conjunto de frascos na sua bolsa enquanto você não olhava. Esses frascos podem ser usados nos elementais de água do lago. A água viva e corrupta que flui pelos corpos deles será o catalisador perfeito!', '', '', '', '', '', '', '', 'Ih... parece que a solução ficou forte demais.', 'Betina Bigozinco', 'Fale novamente com Betina Bigozinco na Torre Escudo da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27454, 'ptBR', 'Só uma gota no balde', 'Use o seu Disfarce de Sectário da Morte para entrar no Campo-base dos Sectários da Morte e então, coloque a mistura da Betina no Caldeirão de Praga de Mereldar.', 'Agora, é só misturar uma gotinha de putrefação com a água, e misturar tudo muito bem. Pronto, aí está. Esta solução continua muito poderosa, e só precisamos de um pouquinho dela.$b$bNa margem sudeste do lago, você encontrará um caldeirão de peste com vários sectários por perto. Vista o seu disfarce de sectário, aproxime-se do caldeirão e pingue APENAS UMA GOTA da solução que você preparou. Uma quantidade maior colocará a sua vida em risco!', 'Sabote o Caldeirão de Praga de Mereldar', '', '', '', '', 'Sabote o Caldeirão de Praga de Mereldar', '', '', '', 'Fale novamente com Betina Bigozinco na Torre Escudo da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27455, 'ptBR', 'Garotos são só garotos', 'Encontre Gidwin Fitáurea na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 'Assim que chegamos aqui, na Torre Escudo da Luz, aqueles dois paladinos idiotas fugiram para a Capela Esperança da Luz. Ainda estamos um pouco longe, mas, se formos seguir Argus de torre em torre, não vamos chegar mais perto do que isso.$b$bDê uma olhada neles e veja se estão bem? Sei que eles podem se cuidar, mas, ainda assim, eu me sentiria melhor sabendo que você está vigiando eles enquanto fico presa aqui com a caravana.', '', '', '', '', '', '', '', '', '', '', 0),
(27456, 'ptBR', 'Carniçaria dos carniceiros', 'Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e colete 15 Nacos de Carne de Verme Carniceiro.', 'Estamos com problemas para manter os nossos estoques de comida aqui no extremo oriente.$B$BPor aqui, o único tipo de fera não afetado pela devastação da peste é o verme carniceiro. Apesar de insípida, a carne dos vermes pode ser facilmente preservada por meses. Precisaremos de mais várias centenas de quilos para enchermos nossos estoques.$b$bVocê pode encontrar vermes carniceiros por toda a região das Terras Pestilentas, mas eles podem ser encontrados em quantidade particularmente alta ao sul da capela. E lembre-se: vermes maiores têm mais carne.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rimblat Quebraterra na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27457, 'ptBR', 'Uma aliança oportuna', 'Fale com a Fiona na Torre da Muralha Leste, que fica nas Terras Pestilentas Orientais.', 'Com as suas contribuições para os nossos estoques de comida, a minha missão atual está completa.$b$bSeguirei para o norte, até o Bosque Pestilento, em seguida. Sei que você pode estar indo na mesma direção.$b$bVocê se importaria se eu me juntasse a você na estrada?$b$bSeguirei para o noroeste, para a Torre da Muralha Leste. Se você estiver interessad$go:a; em unir forças, você pode me encontrar lá.', '', '', '', '', '', '', '', '', '', '', 0),
(27458, 'ptBR', 'Leandro e o curativo', 'Obtenha as Vestes do Carranca de Estêvão Carranca no Engenho Assombrado.', 'Olá! Interessad$go:a; em ganhar um trocado?$b$bPreciso de um curativo. Bem, na verdade, tenho um amigo que precisa de um curativo. Bem, na verdade... digamos que é complicado. Mas, se você for buscar essa bandagem, você vai ganhar dinheiro. E eu também vou. E o meu amigo. E, provavelmente, mais gente vai ganhar dinheiro.$b$bEstêvão Carranca era o dono do moinho ao norte e, agora, está morto. Um zumbi. Aquele primeiro cara quer ter as vestes do corpo do Carranca.$b$bQual é o problema, você não gosta de dinheiro?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Leandro Leonardo na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27459, 'ptBR', 'A Irmandade da Luz', 'Apresente-se à Arquimaga Ângela Santoro na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 'A Irmandade da Luz tem uma história de decisões impetuosas e impensadas. Eles preencheram um vão entre a Cruzada Escarlate e a Aurora Argêntea. Eles estavam entre os primeiros a se lançar contra Nortúndria, enquanto muitos de nós ficaram para trás.$b$bContudo, eles também têm uma história de resultados obtidos, e eu respeito isso. Agora, eles lutam em duas frentes: uma batalha em Stratholme e outra, mais imediata, ao sul da Manopla de Tyr.$b$bSugiro que você fale com Ângela Santoro na Manopla de Tyr. Você pode ser útil.', '', '', '', '', '', '', '', '', '', '', 0),
(27460, 'ptBR', 'Aterrissagem suave', 'Mate quaisquer 10 criaturas da Cruzada Escarlate dentro da Manopla de Tyr.', 'Só nos foram cedidos cem homens para completar esta missão, e já estamos com um a menos. Nosso batedor foi enviado à fortaleza inimiga para eliminar alguns dos guardas que patrulham a área e disparar um sinalizador para que possamos entrar com um ataque coordenado. Nossos noventa e nove homens restantes estão de prontidão, esperando pelo sinal. Preciso que $gum:uma; $c talentos$go:a; como você entre na Manopla de Tyr, elimine quantos guardas puder e dispare aquele sinalizador.$b$bVocê está dispost$go:a;?', '', 'Cruzado Escarlate da Manopla de Tyr morto', '', '', '', '', '', '', '', 'Acenda o Sinalizador dos Cruzados atrás da capela na Manopla de Tyr.', 0),
(27461, 'ptBR', 'Para tomar a abadia', 'Apresente-se ao Comandante Eligor Alvorada do lado de fora da abadia da Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 'A Cruzada Escarlate mantém uma abadia bastante fortificada no setor oeste inferior da Manopla de Tyr. Ela precisará ser tomada antes que se possa prosseguir dentro da fortaleza.', '', '', '', '', '', '', '', '', '', '', 0),
(27462, 'ptBR', 'Para tomar o quartel', 'Apresente-se ao Comandante Cruzado Korfax na frente do Quartel na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 'Uma das fortificações chave dentro da Manopla de Tyr é o quartel, que fica logo ao lado deste sinalizador. A Irmandade da Luz e seus centuriões precisarão de toda ajuda possível nesta empreitada.', '', '', '', '', '', '', '', '', '', '', 0),
(27463, 'ptBR', 'Um sonho de menino', 'Fale com o Lorde Maximiliano Tyrosus dentro da Capela Esperança da Luz.', 'Eu sempre quis fazer parte da Cruzada. Foi por isso que me tornei um paladino. Anos de prática, afiando a minha arte... Finalmente, estou pronto.$b$bO Tarenar também acha que está pronto, mas não tenho certeza disso. Ele é meio exibicionista e nunca leva a sério as lições. Ainda assim, prometemos que faríamos isso juntos, e aqui estamos.$b$bPodemos entrar na capela agora?', '', '', '', '', '', '', '', '', '', '', 0),
(27464, 'ptBR', 'Chamado argênteo: o teste da cripta', 'Entre na Cripta atrás da Capela Esperança da Luz, leia o Pergaminho Argênteo e complete o teste.', 'Atrás da nossa capela, você encontrará uma pequena cripta. Sepultos no interior dela estão os nossos heróis abatidos; aqueles que deram a vida na guerra contra o Flagelo.$b$bOs espíritos deles estão em paz, mas eles retornam intermitentemente para testar os novos membros da ordem.$b$bVocês três podem fazer o teste juntos. Entrem na cripta e leiam este pergaminho. O Lorde Raimundo George – meu predecessor – presidirá o seu teste.', '', 'Teste da cripta completo', '', '', '', '', '', '', '', 'Fale novamente com o Lorde Maximiliano Tyrosus na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27465, 'ptBR', 'Chamado argênteo: a Clareira Nociva', 'Mate 16 Membros do Flagelo e 8 Sectários dentro do Engenho Assombrado e da Clareira Nociva. Volte à Capela Esperança da Luz se o Tarenar ou o Gidwin for morto.', 'O Engenho Assombrado, ao norte, está infestado por mortos-vivos. A Clareira Nociva, mais ao norte, está ainda pior. Apesar da proximidade da nossa capela, nós não fomos capazes de acabar completamente com eles.$b$bVigilância é imprescindível. Adentrem a Clareira Nociva e matem todos os mortos-vivos que vocês conseguirem encontrar... e também os sectários que vaguem por lá.$b$bE evitem Garginox, o gigante de carne que anda pelo vale, enquanto estiverem por lá. Suspeito que vocês ainda não sejam fortes o bastante para vencê-lo.', '', 'Membros do Flagelo mortos', 'Sectários mortos', '', '', '', '', '', '', 'Fale novamente com o Lorde Maximiliano Tyrosus na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27466, 'ptBR', 'Chamado argênteo: o Vilarejo do Norte', 'Fale com a Fiona na Torre da Muralha Leste, que fica nas Terras Pestilentas Orientais.', 'O Tyrosus nos deu nossa última tarefa: matar mais mortos-vivos no Vilarejo do Norte. O Gidwin está animado para seguir em frente, mas acho que deveríamos ter um pouco mais de cuidado.$b$bVamos nos encontrar com a Fiona. Ela deve estar na próxima torre, a esta altura... Acho que se chama Torre da Muralha Leste. Fica perto, ao noroeste da Esperança da Luz. Poderemos descansar lá e planejar o nosso ataque contra o Vilarejo do Norte.', '', '', '', '', '', '', '', '', '', '', 0),
(27467, 'ptBR', 'Lâminas enterradas', 'Enterre as Lâminas Tocadas pela Luz nos corpos de 10 Soldados do Flagelo Mortos.', 'A Clareira Nociva é um atoleiro, tanto literalmente quanto metaforicamente. Há membros do Flagelo em número suficiente para termos dor de cabeça pelo resto de nossas vidas.$b$bEles podem reanimar os mais fracos quando eles morrem, $n. Eles vão continuar vindo se não fizermos alguma coisa.$b$bLeve estas lâminas e encrave-as nos cadáveres de soldados do Flagelo que você encontrar. A lâmina é simples, mas o encantamento impedirá que os ossos mortos sejam reanimados. Para sempre.', '', 'Lâminas enterradas', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Artesão Omarion na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27468, 'ptBR', 'Cercando o Tanque de Cerco', 'Fale com um Comandante de Tanque de Cerco que esteja em cima de um Tanque de Cerco de Beiralta. Defenda o tanque enquanto os engenheiros fazem reparos.', 'Vamos ter que tirar, um a um, os tanques de cerco para fora do lamaçal. Leve estas peças que você coletou para um comandante de tanque de cerco que está em cima de uma das máquinas destrambelhadas.$B$BDepois, defenda o tanque enquanto os engenheiros o consertam.$B$BVá e me dê motivos para sentir orgulho de você, $c!', '', 'Conversa com Comandante de Tanque de Cerco', 'Tanque de cerco defendido', '', '', '', '', '', '', 'Fale com Fargo Flintlocke na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27469, 'ptBR', 'Amigos do outro lado', 'Encontre Acrídeo.', 'Trago notícias do Pico da Rocha Negra. Chegou um novo visitante. O nome dele é Acrídeo.$B$BEle procura pessoas de grande força, inteligência e destreza. Você tem de ir ao Pico da Rocha Negra para falar com ele.', '', '', '', '', '', '', '', '', '', '', 0),
(27470, 'ptBR', 'Aliado em potencial', 'Encontre Acrídeo.', 'Todos sabem que não somos fãs dos orcs da Montanha Rocha Negra, por isso mesmo observamos constantemente cada passo deles. Nada acontece na Montanha que eu não saiba, $c.$B$BHá pouco tempo, um estranho orc chegou ao Pico da Rocha Negra e se estabeleceu por lá. Dizem que ele planeja destruir Nefarian junto com todo o exército órquico. Não costumo confiar em orcs, mas este possui os mesmos interesses que nós... Encontre-o. Ele se chama Acrídeo.', '', '', '', '', '', '', '', '', '', '', 0),
(27471, 'ptBR', 'Anomalia Rocha Negra', 'Encontre Acrídeo.', 'Existe um orc dentro do Pico da Rocha Negra bem diferente dos demais. Suas palavras são sábias para a idade que aparenta e não luta contra nossos soldados, como outros o fazem.$B$BVá para noroeste do Pico da Rocha Negra e encontre este tal orc, conhecido por nós como Acrídeo. Talvez ele seja a chave para determos o exército órquico e, quem sabe, acabarmos com Nefarian antes que seja tarde demais...', '', '', '', '', '', '', '', '', '', '', 0),
(27472, 'ptBR', 'Erga-se, Godfrey', 'Fique junto da Grande Dama Sylvana Correventos enquanto ela oficia a iniciação de Lorde Godfrey e seus homens.', 'Você é inflexível em sua lealdade aos Renegados, $n. Saiba que o que você fez por nós e pela Horda não deixará de ser notado. Com Lorde Godfrey e seus homens recuperados teremos uma grande vantagem sobre a Frente de Libertação de Guilnéas e o resto dos cães da Aliança.$B$BAgora fique ao meu lado e veja Lorde Godfrey ressurgir como um dos nossos. Juntos acolheremos o lorde e seus homens em nossas fileiras.', '', 'Lorde Godfrey Renascido', '', '', '', '', '', '', '', 'Fale com a Grande Dama Sylvana Correventos na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27473, 'ptBR', 'Altos problemas em Altaforja', 'Fale com a Tempestária Mylra em Altaforja.', 'Os problemas de Altaforja estão cada vez maiores, $n. Por favor, fale com a tempestária Mylra e veja se tem algo em que você possa ajudar.', '', '', '', '', '', '', '', '', '', 'Fale com a Tempestária Mylra em Altaforja.', 0),
(27474, 'ptBR', 'Rompendo a barreira', 'Encontre o Códice de Lenhâmbar', 'Enquanto Godfrey e eu cuidamos dos preparativos para nosso ataque a Guilnéas, quero que você lidere nosso ataque a Lenhâmbar, diretamente a leste daqui.$B$BOs magos de Lenhâmbar, que eram de Dalaran, ergueram uma barreira mágica que os esconde de nossas vistas. Eles estão escondidos em um nicho dimensional, esperando as ordens da Aliança para iniciar o ataque. Devemos impedi-los executando um ataque preventivo. Siga para Lenhâmbar e encontre informações que nos permitam chegar aos magos.', '', '', '', '', '', '', '', '', '', 'Fale com a Grande Dama Sylvana Correventos na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27475, 'ptBR', 'Servos obstinados', 'Colete 6 Núcleos dos Servos.', 'Os magos de Lenhâmbar usaram magia suja para nos manter afastados. Eles criaram servos elementais para vigiar o território, e esses servos estão protegidos por feitiços de imunização que não conseguimos anular.$B$BSiga para Lenhâmbar, a leste daqui, mate os servos elementais obstinados que protegem a cidade e traga seus núcleos para mim. Dessa forma, vou poder elaborar um método para destruirmos todos eles!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dália na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27476, 'ptBR', 'Dalar Tessalba', 'Leve o Códice de Lenhâmbar para Dalar Tessalba no Sepulcro, que fica na Floresta de Pinhaprata.', 'Pegue o códice e vá para o norte até o Sepulcro. Quando chegar lá, encontre Dalar Tessalba. Dalar é um antigo arquimago do Kirin Tor. Com certeza ele conseguirá derrubar as proteções mágicas do códice e descobrir os segredos nele contidos.$B$BApresse-se, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(27477, 'ptBR', 'O corpulento', 'Encontre o Brocassangre nos ermos do norte das Terras Pestilentas e destrua-o.', 'Ao norte daqui e a oeste do Vilarejo do Norte, você encontrará o corpulento verme feral, Brocassangre.$B$BPerdi regimentos inteiros para aquele monstro. O tamanho dele não conhece limites! Quanto mais ele come, maior ele fica...$B$BSe, por um lado, eu não ficarei emocionalmente afetada se a fera devorar você, por outro, torço para que você saia $gvitorioso:vitoriosa;. O Brocassangre é notório devorador daqueles que tentam caçá-lo.', '', '', '', '', '', '', 'Brocassangre', '', '', 'Fale novamente com Cari Okashia na Torre da Muralha Leste, que fica nas Terras Pestilentas Orientais.', 0),
(27478, 'ptBR', 'Relios, o Guardião de Relíquias', 'Encontre um Anel-sinete de Arquimago de Dalaran.', 'A Dama Sombria estava certa em me enviar o códice. Mas, infelizmente, preciso de um anel-sinete de um arquimago de Dalaran para conseguir abrir o livro. Meu anel me foi tomado quando morri, anos atrás. Mas ainda há um jeito.$B$BDalaran flutuou para longe, mas os arredores da cidade ainda estão no lugar. Longe daqui, para leste, ficam as ruínas de Dalaran. É lá que você encontrará um arquimago chamado Relios. "Peça emprestado" o anel dele e traga-o para mim.$B$BVocê pode usar o portal atrás de mim para chegar na cratera.', '', '', '', '', '', '', 'Relios, o Guardião de Relíquias', '', '', 'Use o portal na Cratera de Dalaran para voltar até Dalar Tessalba no Sepulcro, que fica na Floresta de Pinhaprata.', 0),
(27479, 'ptBR', 'Indignação íntegra', 'Obtenha 30 Olhos de Esfolamusgo de trolls Esfolamusgo em Zul\'Mashar.', 'Os Esfolamusgo de Zul\'Mashar cospem na face da Luz! Eles canibalizam, criminalizam, priorizam as forças do mal sobre o bem! Sugiro que os olhos deles tu removas, para que rastejem em suas alcovas ou apodreçam nas enxovas agonizando pelas bocas!$b$bTu viajarás para o norte e farás chover sobre eles a justiça e a indignação dos íntegros, $n. A fúria que eles despertaram aos olhos da Luz será canalizada por ti.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Diácono Andaal na Torre da Muralha Leste, que fica nas Terras Pestilentas Orientais.', 0),
(27480, 'ptBR', 'As energias do meridiano', 'Colete 8 Remanescentes Arcanos.', 'O remanente arcano pulsa com uma estranha energia. Talvez você devesse encontrar mais remanentes. Com certeza Dalar se interessará por essa descoberta.', '', '', '', '', '', '', '', '', '', 'Use o portal na Cratera de Dalaran para voltar até Dalar Tessalba no Sepulcro, que fica na Floresta de Pinhaprata.', 0),
(27481, 'ptBR', 'Fora do zigurate', 'Obtenha o Corpo do Senhor da Guerra Thresh\'jin.', 'Agora eu preciso te pedir um favor, $n.$b$bBem mais ao norte da Torre da Muralha Leste encontra-se, escondida em meio à serra, a capital Esfolamusgo de Zul\'Mashar. Foi lá onde eu nasci, e onde eu morri.$b$bO traidor, Thresh\'jin, está sentado no trono que fica no topo do zigurate de Zul\'Mashar. Eu tinha todo o direito de estar lá, mas ele me roubou a posição usando de traição e mentiras. Ele não é forte. Ele é fraco.$b$bEu me encontrarei com você em Zul\'Mashar, e nós iremos matá-lo. A sua força e a minha. Juntas.', '', '', '', '', '', '', 'Senhor da Guerra Thresh\'jin', '', '', 'Fale novamente com Vex\'tul na Torre da Muralha Leste, que fica nas Terras Pestilentas do Leste.', 0),
(27482, 'ptBR', 'Chamas adentro', 'Quando você estiver pront$go:a; para se despedir de Vex\'tul, jogue o corpo do Senhor da Guerra Thresh\'jin na fogueira no topo do zigurate de Zul\'Mashar.', 'É aqui que nos despedimos, $n. Eu estou deixando a caravana.$b$bSe você quiser continuar lutando ao meu lado, fique com corpo do Thresh\'jin. Eu posso esperar um pouco mais. Mas quando você estiver pront$go:a; para dizer adeus, jogue o cadáver na fogueira em cima do zigurate de Zul\'Mashar.$b$bEu sou grato pela sua companhia, $n. Você foi forte.', '', 'Corpo do Senhor da Guerra Thresh\'jin queimado', '', '', '', '', '', '', '', 'Fale novamente com a Fiona na Torre da Muralha Leste, que fica nas Terras Pestilentas Orientais.', 0),
(27483, 'ptBR', 'Vingança prática', 'Mate 12 humanos de Dalaran.', 'Em circunstâncias normais, não sou um homem vingativo. De fato, gosto de me considerar um homem pragmático. Você entende... praticidade raramente é um fator de peso quando se elabora uma vingança. A maioria dos complôs de vingança são muito laboriosos.$B$BMAS... só nesse caso... e já que você está indo para as ruínas de Dalaran mesmo... quero que você mate qualquer humano afiliado a Dalaran que encontrar por lá. Os motivos que me fazem desejar a morte deles são variados: ódio, raiva, traição... Mas garanto que são queixas legítimas. Faça isso pra mim, e eu $go:a; recompensarei generosamente.', '', 'Humano de Dalaran morto', '', '', '', '', '', '', '', 'Use o portal na Cratera de Dalaran para voltar até Dalar Tessalba no Sepulcro, que fica na Floresta de Pinhaprata.', 0),
(27484, 'ptBR', 'Apenas um pode entrar', 'Leve o Anel-sinete de Arquimago de Dalaran para a Grande Dama Sylvana Correventos na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', '<Dalar analisa o códice.>$B$BHAHAHA!$B$BOh... Isso é mau.$B$B<Dalar fecha o códice e olha para você.>$B$BApenas UMA pessoa, usando esse anel, pode entrar no nicho dimensional em Lenhâmbar. Essa pessoa vai ter que enfrentar um exército de magos e matar o arquimago que está gerando o campo de força pelo lado de dentro. Só então a dimensão irá se fechar, expulsando todos os magos.$B$BO portal de entrada está escondido no final da caverna na Cilada de Beren.$B$BIsso é tudo que sei. Leve o anel de volta para Sylvana.', '', '', '', '', '', '', '', '', '', '', 0),
(27485, 'ptBR', 'Recepção calorosa', 'Encontre com Lirastrasza no Rubro Reduto.', 'Estou feliz por sua volta depois de salvar o mundo ou coisa parecida!$B$BMinha incumbência é estabelecer relações com os dragões vermelhos da área, mas estou achando o bando daqui um pouco menos acolhedor do que os do Repouso das Serpes. Ouvi dizer, no entanto, que você é do tipo que resolve problemas.$B$BA solução de todos os problemas.$B$BVocê quer tentar ganhar um pouco da confiança de Lirastrasza no Rubro Reduto ao norte? Qualquer coisa que possa apaziguar os ânimos dela seria de bom grado.', '', 'Encontre-se com Lirastrasza', '', '', '', '', '', '', '', 'Fale com Calen no Rubro Reduto.', 0),
(27486, 'ptBR', 'Recepção calorosa', 'Encontre com Lirastrasza no Rubro Reduto.', 'Bom. Você voltou. Salvando o mundo mais uma vez, presumo.$B$BFui enviado para estabelecer relações com os dragões vermelhos da área, mas estou achando esse bando menos receptivo do que os do Repouso das Serpes. No entanto, fiquei sabendo que você é do tipo que soluciona problemas.$B$B$GUm mediador:Uma mediadora;, como diriam.$B$BVocê tem que ganhar a confiança de Lirastrasza no Rubro Reduto, ao norte. Nosso acordo com os Presa do Dragão complicou as coisas, mas tenho esperanças de que a situação será amenizada.', '', 'Encontre-se com Lirastrasza', '', '', '', '', '', '', '', 'Fale com Calen no Rubro Reduto.', 0),
(27487, 'ptBR', 'Ix\'lar, o Infralorde', 'Mate Ix\'lar, o Infralorde, e 10 lacaios dele.', 'Eu sei que deveríamos seguir para o Vilarejo do Norte, mas isso pode esperar, não pode? Além do mais, esta adorável goblina estava me contando que alguns membros do Flagelo estão ainda mais perto.$b$bEntão, parece que há um infralorde nerubiano, chamado Ix\'lar, que vem tentando se fazer conhecido desde que o Lich Rei foi morto. Ele está em um acampamento de mortos-vivos a norte de onde nós estamos.$b$bClaro, o Tyrosus quer que matemos banshees no Vilarejo do Norte. Nós faremos isso. Mas vamos matar esse nerubiano antes, enquanto ainda estamos perto!', '', '', 'Lacaios de Ix\'lar mortos', '', '', '', '', '', '', 'Fale novamente com a Fiona na Torre da Muralha Leste, que fica nas Terras Pestilentas Orientais.', 0),
(27488, 'ptBR', 'Impaciência', 'Procure por Gidwin Fitáurea no Vilarejo do Norte.', 'Maldito anão! Ele vive fazendo eu me encrencar com a Fiona. Olhe para ela! Ela nem sequer FALA comigo!$b$bVou ficar aqui e tentar fazer as pazes com a nossa amiga peluda. Será que você poderia ver se o Gidwin está bem? Tenho certeza de que ele está ótimo, ele sabe se cuidar. Ele seguiu para o norte, e não pode ter ido muito longe.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tarenar Golpessol na Torre da Muralha Leste, que fica nas Terras Pestilentas Orientais.', 0),
(27489, 'ptBR', 'A culpa é minha e de mais ninguém', 'Embarque na Caravana da Fiona e siga para a Torre do Passo Norte.', 'Isto é culpa minha. Eu... eu ignorei os alertas dele, as reclamações, tudo. Eu não conseguia evitar – eu via aqueles vermes do Flagelo logo além da torre e eu... eu PRECISAVA matar eles.$b$bO Argus diz que o Gidwin foi levado para o noroeste e, como essa é a nossa única pista, é para lá que vamos.$b$bMalditos sejam o Vilarejo do Norte e a Cruzada Argêntea! Vamos tirar o Gidwin das mãos desse Flagelo nojento.', '', 'Continue com a Caravana da Fiona para a Torre do Passo Norte', '', '', '', '', '', '', '', 'Fale com Tarenar Golpessol na Torre do Passo Norte, que fica nas Terras Pestilentas Orientais.', 0),
(27490, 'ptBR', 'Aviso aos viajantes', 'Consiga um esquadrão de Desordeiros Martelo Feroz com Angus Montecalmo e escolte-os até o local de desembarque no Portão do Crepúsculo.', 'Mathias Shaw e a AVIN estão aqui para nos dar assistência nas operações na Cidadela do Crepúsculo. Você precisa escoltá-los.$B$BOs Martelo Feroz estão sendo muito gentis em nos levar até lá. Os agentes precisam fazer algumas coisas nos arredores do Portão do Crepúsculo antes.$B$BFale com Angus Montecalmo e junte-se a um esquadrão para voar até lá. Um grande X azul indica o lugar.', '', 'Consiga uma esquadra Martelo Feroz', 'Agentes da AVIN desembarcados', '', '', '', '', '', '', 'Fale novamente com Cassius, o Branco, no Pontal do Vencedor, que fica no Planalto do Crepúsculo.', 0),
(27491, 'ptBR', 'Quem quer Kor\'kron?', 'Consiga um esquadrilha de Mantícoras Cachamorras com Zep\'apuddo e escolte-a até o local de desembarque no Portão do Crepúsculo.', 'Garona e um destacamento dos Kor\'kron estão aqui para nos dar assistência nas operações na Cidadela do Crepúsculo. Você tem que escoltá-los até lá.$B$BPedi a uma tribo local de trolls para nos levarem em suas mantícoras. Os assassinos precisam fazer algumas coisas no Portão do Crepúsculo antes.$B$BFale com o chefe dos trolls, Zep\'apuddo, e consiga um destacamento Kor\'kron para voar até lá. Um grande X vermelho indica o lugar.', '', 'Consiga uma esquadrilha de mantícoras', 'Kor\'kron desembarcado', '', '', '', '', '', '', 'Fale novamente com a Dama Cozwynn no Planalto do Crepúsculo.', 0),
(27492, 'ptBR', 'Sobre ogros e gorjalas', 'Mate 10 Ogros ou Gorjalas no Portão do Crepúsculo.', 'Como com qualquer ofensiva, você primeiro precisa acalmar ela. Temos tido muito trabalho para chegar lá. Mas alguém como você... Bem, digamos que não tenho dúvida alguma de que você pode seguir pelo Portão do Crepúsculo para sudoeste e ensinar aos ogros do clã Olho de Sangue e aos gorjalas algumas lições!', '', 'Ogros do clã Olho de Sangue e Gorjalas mortos', '', '', '', '', '', '', '', 'Fale novamente com Kurdran Martelo Feroz no Pontal do Vencedor, que fica no Planalto do Crepúsculo.', 0),
(27493, 'ptBR', 'Sobre ogros e gorjalas', 'Mate 10 Ogros do clã Olho de Sangue ou Gorjalas no Portão do Crepúsculo.', 'Quero que você passe pelos rochedos a noroeste até o Portão do Crepúsculo. Mate todos os ogros e gorjalas do clã Olho de Sangue que você encontrar. Você acha que dá conta disso, $n?', '', 'Ogros do clã Olho de Sangue e Gorjalas mortos', '', '', '', '', '', '', '', 'Fale novamente com a Senhora da Guerra Zaela em Cachamorra, que fica no Planalto do Crepúsculo.', 0),
(27494, 'ptBR', 'A fé move o Montanha', 'Detone os Explosivos Escondidos para atrair Britacrânios, o Montanha, para longe do Portão do Crepúsculo.', 'Se o Portão do Crepúsculo está prestes a cair, precisamos tirar Britacrânios, o Montanha, de lá!$B$BAntes de partirem, me certifiquei de que seus agentes da AVIN levassem alguns explosivos escondidos num caixote do Martelo do Crepúsculo. Agora eles já devem ter colocado eles na escadaria que leva à parte superior da cidadela.$B$BQuero que você arme os explosivos e nos avise quando aquele monstro estiver fora do caminho.$B$BSerá o momento em que atacaremos e daremos um fim ao bando de ogros!', '', 'Explosivos escondidos detonados', '', '', '', '', '', '', '', '', 0),
(27495, 'ptBR', 'A fé move o Montanha', 'Detone os Explosivos Escondidos para atrair Britacrânios, o Montanha, para longe do Portão do Crepúsculo.', 'Se o Portão do Crepúsculo está prestes a cair, temos que tirar Britacrânios, o Montanha, de lá!$B$BAntes de partirem, me certifiquei de que seus assassinos kor\'kron levassem alguns explosivos escondidos num caixote do Martelo do Crepúsculo. Agora eles já devem ter colocado eles na escadaria que leva à parte superior da cidadela.$B$BQuero que você arme os explosivos e nos avise quando aquele monstro estiver fora do caminho.$B$BSerá o momento em que atacaremos e daremos um fim ao bando de ogros!', '', 'Explosivos escondidos detonados', '', '', '', '', '', '', '', '', 0),
(27496, 'ptBR', 'Sinal de alerta', 'Use o Sinalizador de Artilharia para mirar os edifícios ao norte, nordeste, sudoeste e sul do Portão do Crepúsculo.', 'Prefiro uma batalha justa. Esses monstros merecem nada menos do que a destruição pelas armas que carregamos. No entanto, esta situação específica requer medidas extremas.$B$BLeve este sinalizador e dispare-o em cada um dos quatro edifícios dentro do Portão do Crepúsculo a sudoeste daqui. Nossos canhões cuidarão do resto.', '', 'Edifício ao norte sob a mira', 'Edifício ao nordeste sob a mira', 'Edifício ao sudoeste sob a mira', 'Edifício ao sul sob a mira', '', '', '', '', 'Fale novamente com Cassius, o Branco, no Pontal do Vencedor, que fica no Planalto do Crepúsculo.', 0),
(27497, 'ptBR', 'Sinal de alerta', 'Use o Sinalizador de Artilharia para mirar os edifícios ao norte, nordeste, sudoeste e sul do Portão do Crepúsculo.', 'Mas é mesmo uma pena não podermos lançar a praga sobre nossos inimigos. Poderia ser o remédio para essa situação. Ah sim, pelo menos temos máquinas de guerra para derrubar os preciosos portões deles.$B$BLeve este sinalizador e dispare-o em cada um dos quatro edifícios dentro do Portão do Crepúsculo a noroeste. As máquinas de guerra cuidarão do resto.', '', 'Edifício ao norte sob a mira', 'Edifício ao nordeste sob a mira', 'Edifício ao sudoeste sob a mira', 'Edifício ao sul sob a mira', '', '', '', '', 'Fale novamente com a Dama Cozwynn no Planalto do Crepúsculo.', 0),
(27498, 'ptBR', 'O sinal para o ataque', 'Use o Sinalizador de Ataque no topo de uma das torres no Portão do Crepúsculo.', 'Agora que você atraiu Britacrânios, o Montanha, pra longe do Portão do Crepúsculo, está na hora de sinalizar pra nossas forças no Pontal do Vencedor iniciarem o ataque!', '', 'Ataque sinalizado', '', '', '', '', '', '', '', '', 0),
(27499, 'ptBR', 'O sinal para o ataque', 'Use o Sinalizador de Ataque no topo de uma das torres no Portão do Crepúsculo.', 'Agora que você atraiu Britacrânios, o Montanha, para longe do Portão do Crepúsculo, está na hora de sinalizar para nossas forças em Cachamorra iniciarem o ataque!', '', 'Ataque sinalizado', '', '', '', '', '', '', '', '', 0),
(27500, 'ptBR', 'Quatro cabeças e um funeral', 'Colete as quatro cabeças de Za\'brox  e Beeble\'phod.', 'Agora que o ataque ao Portão do Crepúsculo foi iniciado, falta apenas uma questão para ser tratada: Za\'brox e Beeble\'phod, os discípulos de Cho\'gall.$B$BA inteligência os colocou no Covil dos Discípulos, uma pequena caverna dos ogros a sudoeste do Portão do Crepúsculo. Pode ter certeza de que Cassius e Kurdran vão querer provas da morte deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Cassius, o Branco, no Pontal do Vencedor, que fica no Planalto do Crepúsculo.', 0),
(27501, 'ptBR', 'Quatro cabeças e um funeral', 'Colete as quatro cabeças de Za\'brox  e Beeble\'phod.', 'Agora que o ataque ao Portão do Crepúsculo foi iniciado, falta apenas uma questão para ser tratada: Za\'brox e Beeble\'phod, os discípulos de Cho\'gall.$B$BA inteligência os colocou no Covil dos Discípulos, uma pequena caverna dos ogros a sudoeste do Portão do Crepúsculo. Pode ter certeza de que a Lady Cozwynn e Zaela vão querer provas da morte deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Lady Cozwynn no Planalto do Crepúsculo.', 0),
(27502, 'ptBR', 'A caminho da Cidadela', 'Fale com o Comandante do Esquadrão AVIN e escolte a tropa.', 'Agora que o ataque está em andamento, está na hora de cuidar da Cidadela do Crepúsculo. Se você não se importar, queria que escoltasse as forças da AVIN para o mestre Mathias Shaw.$B$BEle está escondido em algum lugar no topo. O comandante da tropa AVIN pode lhe dizer onde.$B$BEu lhe agradeço, $n. Estamos ansiosos para nos unir a você no ataque à Cidadela!', '', 'Falar com o Comandante do Esquadrão', 'AVIN escoltada', '', '', '', '', '', '', '', 0),
(27503, 'ptBR', 'A caminho da Cidadela', 'Fale com o Comandante do Esquadrão Kor\'kron e escolte o esquadrão.', 'Agora que o ataque está em andamento, está na hora de cuidar da Cidadela do Crepúsculo. Se você não se importar, queria que escoltasse as forças de Kor\'kron até Garona.$B$BEla está escondida em algum lugar no topo. O comandante da tropa Kor\'kron pode dizer onde.$B$BEu lhe agradeço, $n. Estamos ansiosos para nos unir a você no ataque à Cidadela!', '', 'Falar com o Comandante do Esquadrão', 'Kor\'kron escoltado', '', '', '', '', '', '', '', 0),
(27504, 'ptBR', 'Os dragões também sangram', 'Fale com Velastrasza no Rubro Reduto.', 'Eu não seria grosseiro a ponto de recusar a ajuda que você está oferecendo.$B$BEstamos lutando constantemente contra dracos e dragões crepusculares no sul. Nossos ataques não foram totalmente fracassados, mas os dragões vindos de Grim Batol têm soprado algum tipo de corrupção sobre nós que leva tempo para limpar.$B$BVelastrasza e Ruinaflama estão atendendo nossos irmãos feridos. Veja como você pode ajudá-los.', '', '', '', '', '', '', '', '', '', '', 0),
(27505, 'ptBR', 'Reparos dragônicos', 'Salvaguarde 5 Reparadores Rubros enquanto cuidam dos dragões feridos.', 'Nossos dragões estão voltando da batalha cobertos de chamas corrompidas e perseguidos pelos dracos do Crepúsculo.$B$BMeus reparadores podem tratar das feridas dos dragões, mas devem ser defendidos. Afaste os dracos dos reparadores e, se você puder, também ajude a curar os dragões.$B$BObrigada por sua ajuda. Nossas batalhas por Grim Batol são infinitas. Temos que levar nossos dragões mais fortes de volta à batalha o mais rápido possível.', '', 'Reparadores Rubros defendidos', '', '', '', '', '', '', '', 'Fale novamente com Velastrasza no Rubro Reduto.', 0),
(27506, 'ptBR', 'Vida após a morte', 'Plante Sementes Rubi nos corpos de 6 draconianos no Rubro Reduto.', '$R, tenho uma tarefa para você.$B$BPegue estas sementes rubi e plante-as nos corpos de qualquer draconiano que encontrar. Do Crepúsculo ou Rubro, dragonete ou dragão, não importa o que seja. Precisamos garantir que seus corpos retornem à terra permitindo que a vida continue a florescer.$B$BNa morte há sempre espaço para uma nova vida. Esse deve ser nosso consolo em tempos de guerra e grandes tragédias.', '', 'Corpo de draconiano reivindicado', '', '', '', '', '', '', '', 'Fale novamente com Ruinaflama no Rubro Reduto.', 0),
(27507, 'ptBR', 'Transgressores do Crepúsculo', 'Mate 12 Invasores do Crepúsculo no Rubro Reduto.', 'Invasores do crepúsculo fracos infestam o Reduto. Eles chegam de algum lugar do norte.$B$BNão devemos mostrar misericórdia neste lugar sagrado. Seja qual for a violência que toma conta do seu coração mortal, despeje-a sobre eles!', '', 'Invasores do Crepúsculo mortos', '', '', '', '', '', '', '', 'Fale novamente com Calen no Rubro Reduto.', 0),
(27508, 'ptBR', 'Longe do ninho', 'Recupere 6 Ovos Vermelhos.', 'Entenda... sei que você não tem motivos para simpatizar comigo, assim como eu não tenho para simpatizar com você, mas preciso de toda ajuda que puder conseguir.$B$BNossos ovos estão sendo roubados pelos invasores crepusculares. Não tenho dúvidas de que eles querem levar os ovos de volta para Grim Batol para fazerem experiências. NÃO PERMITIREI que isso ocorra!$B$BSe você quer nos ajudar de verdade, detenha-os! Recupere os ovos e traga-os de volta para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lirastrasza no Rubro Reduto.', 0),
(27509, 'ptBR', 'Falha de defesa', 'Encontre a origem do Martelo do Crepúsculo no Rubro Reduto e destrua-a.', 'Cada centímetro do céu e cada montanha que rodeia o Reduto estão sob constante vigília dos dracos de Lira. Eles devem ter descoberto um caminho para o santuário a partir do subsolo.$B$BPegue esta partícula incandescente. Ela será o suficiente para fechar qualquer buraco, túnel ou portal que eles possam ter usado para chegar até nossas defesas.$B$BEncontre a falha em nossas defesas e feche-a.', '', 'Portal do Crepúsculo destruído', '', '', '', '', '', '', '', 'Fale novamente com Calen no Rubro Reduto.', 0),
(27510, 'ptBR', 'Lobo em pele de urso', 'Mate 10 Ursos Inconspícuos.', 'Esses worgens acham que somos idiotas! Só um idiota confundiria um druida worgen em forma de urso com um urso verdadeiro! Infelizmente, está cheio de idiotas aqui na Linha de Frente dos Renegados. Já perdemos alguns batalhões para ataques organizados de ursos worgens. Isso tudo é muito estúpido...$B$BDiretamente a leste daqui, na direção de Eira dos Montes, você encontrará druidas worgens vagando pelos bosques se fazendo passar por ursos. Mate-os. Torne nossa linha de suprimentos ao sul segura mais uma vez.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sumo Senhor da Guerra Cromush na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27511, 'ptBR', 'A emoção da descoberta', 'Explore a Câmara das Estrelas.', 'Que descoberta! E, de alguma forma, tudo permaneceu intocado por saqueadores...$b$bEscute, $n. Preciso documentar este local antes que perturbemos qualquer coisa. Enquanto faço isso, por que você não vai dar uma volta? Você sabe, explorar um pouco. Você merece.$b$bFique de olhos abertos para qualquer coisa fora do comum.$b$bAh! E, por favor... não quebre nada, está bem?', '', 'Mecanismo Ancestral examinado', 'Hieróglifos do Norte examinados', 'Hieróglifos do Sul examinados', '', '', '', '', '', 'Fale com Harrison Jones na Câmara das Estrelas.', 0),
(27512, 'ptBR', 'Guerrilha transdimensional: Capítulo I', 'Encontre o Portal Dimensional de Lenhâmbar.', '<Sylvana entrega o anel-sinete a você.>$B$BPegue este anel e siga para a Cilada de Beren, a sudeste daqui. O lugar fica numa caverna nas colinas. Quando chegar lá, vasculhe a caverna e encontre o portal para o nicho dimensional que esconde os magos de Lenhâmbar.$B$BEu me comunicarei com você mentalmente, $n. Quando você chegar ao portal, eu lhe darei suas ordens.', '', '', '', '', '', '', '', 'O portal está bem à sua frente.', 'Grande Dama Sylvana Correventos', 'Fale com a Grande Dama Sylvana Correventos na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27513, 'ptBR', 'Guerrilha transdimensional: Capítulo II', 'Mate 20 magos de Lenhâmbar.', '<As palavras da Rainha Banshee flutuam em sua mente.>$B$BAgora você está $gpronto:pronta; para usar o portal. Esteja $gavisado:avisada;, $n: assim que atravessá-lo, você estará em outra dimensão, em Lenhâmbar. Haverá cem, talvez mil magos à espera para matar você.$B$BResista e mate todos em seu caminho.', '', 'Mago de Lenhâmbar morto', '', '', '', '', 'Grande Dama Sylvana Correventos', 'Os cadáveres deles vão alimentar a máquina de guerra dos Renegados!', 'Grande Dama Sylvana Correventos', 'Fale com a Grande Dama Sylvana Correventos na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27514, 'ptBR', 'Cai cai, anão!', 'Localize Thordun Golpemalho, um cavalga-grifo dos Martelo Feroz caído na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 'Enquanto você estava lutando ao longo da costa, vi um grifo despencando das nuvens a oeste daqui.$B$BNão era um dos nossos.$B$BProvavelmente pertencia a um Martelo Feroz. Sei que Kurdran queria estabelecer contato com os clãs Martelo Feroz perdidos depois de tomar a praia.$B$BNão posso mais enviar meus homens para investigar isso, mas posso enviar você. Encontre aquele Martelo Feroz caído!', '', '', '', '', '', '', '', '', '', 'Localize Thordun Golpemalho, um cavalga-grifo dos Martelo Feroz caído na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27515, 'ptBR', 'Raízes profundas', 'Pegue 8 Raízes Espinhacas na Costa do Crepúsculo.', 'Olhe isso, $gguri:guria;. Ela está nas últimas... Se meu pássaro morrer, vou ficar em frangalhos.$B$BTu me pode ser útil. Aqui na península tu pode cavar raízes espinhacas. Ah, o fedor delas é um chute nos fundilhos, mas, quando misturadas com água, elas fazem um poderoso elixir de cura.$B$BPegue algumas enquanto cuido do meu pássaro. Rápido, $gguri:guria;! Vocês embromadores da Aliança não têm reputação para uma intervenção oportuna, né?', '', '', '', '', '', '', '', '', '', 'Leve as raízes para Thordun Golpemalho na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27516, 'ptBR', 'Voar, voar... subir, subir...', 'Fale com Thordun Golpemalho e voe de volta para Beiralta.', 'Bá, veja só! Acho que ela já está se recuperando.$B$BCerto, $gseu:sua; $c $gsabichão:sabichona; da Aliança. É tua base que vejo na costa? "Beiralta", você diz. Posso ficar lá com meu pássaro até que ela melhore?$B$BVoaremos juntos de volta para Beiralta!', '', 'Thordun Golpemalho voou para Beiralta', '', '', '', '', '', '', '', 'Fale com Kurdran Martelo Feroz em Beiralta, que fica no Planalto do Crepúsculo.', 0),
(27517, 'ptBR', 'Prepare-se', 'Colete 6 Pedaços de Corda.', 'Todo aventureiro de respeito sabe que nunca se deve colocar o pé em uma caverna, masmorra, cripta ou tumba sem um vasto estoque de corda... não é?$b$bCorda nunca é demais!$b$bVocê decide coletar cada pedacinho de corda que encontrar nos esqueletos daqui.', '', '', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Câmara das Estrelas.', 0),
(27518, 'ptBR', 'Guerrilha transdimensional: Capítulo III', 'Sobrecarregue o Arquimago Ataeric com poder arcano para derrubar o Escudo Transdimensional.', '<Você escuta a voz de Sylvana ecoando em sua mente.>$B$BVocê deve encontrar o responsável pelo nicho dimensional. Aposto como é Ataeric, aquele tolo... Vasculhe o local e encontre-o. Se encontrá-lo, faça o que precisar para impedi-lo de canalizar a magia. Ele deve estar protegido por um escudo de energia arcana, e vai enviar lacaios feitos de energia arcana para destruir você. Derrote os lacaios enquanto estiverem perto dele, para que liberem as energias. Nenhum mago pode conter tamanho poder!', '', 'Escudo Transdimensional destruído', '', '', '', '', 'Grande Dama Sylvana Correventos', '', '', 'Fale com a Grande Dama Sylvana Correventos na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27519, 'ptBR', 'Sob as areias sufocantes', 'Resgate 8 Sobreviventes de Orsis.', 'Não... não pode ser.$B$BOrsis está completamente soterrada sob as areias do deserto.$B$BO inimigo pagará por isso!$B$BMas antes devemos socorrer meu povo. Rápido, $n. Não temos muito tempo antes do último de meus irmãos ser enterrado vivo!', '', 'Sobrevivente de Orsis resgatado', '', '', '', '', '', '', '', 'Fale com Ammantep em Orsis em Uldum.', 0),
(27520, 'ptBR', 'Lacaios de Al\'Akir', 'Mate 6 Rebentos de Al\'Akir.', 'Al\'Akir enviou seus lacaios para servirem ao Asa da Morte.$B$BA mensagem é clara. Ou nos unimos a eles... ou eles nos destroem.$B$BNão sei muito sobre você, $r. Mas sei disso. Se provar que é $gum inimigo:uma inimiga; de Al\'Akir, sua ajuda não passará em branco.$B$BO que me diz, $c?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Príncipe Nadun em Orsis em Uldum.', 0),
(27521, 'ptBR', 'Colmeia ignóbil de escória e vilania', 'Mate 9 Ignóbeis no Abrigo Quel\'Lithien, que fica nas Terras Pestilentas Orientais.', '$R... por favor, preciso da sua ajuda.$b$bAlgo aconteceu com o meu povo. Nosso comandante, o Lorde Patrulheiro Falcolança, encontrou um item de energia mágica, e os meus amigos, a minha família... ele sucumbiram frente ao poder de sedução daquilo.$b$bEles foram corrompidos, $r. Todos eles.$b$bA minha Ellaria não iria querer viver assim, e tampouco os meus irmãos. Por favor, acabe com o sofrimento deles. O Abrigo Quel\'Lithien não fica longe; é logo em cima do morro, ao noroeste.', '', 'Ignóbil de Quel\'Lithien morto', '', '', '', '', '', '', '', 'Fale novamente com Kirkian Broquelalba na Torre do Passo Norte, que fica nas Terras Pestilentas Orientais.', 0),
(27522, 'ptBR', 'Faça eles falarem', 'Espanque ao menos 6 Engenheiros de Cerco do Flagelo para descobrir detalhes a respeito da localização do Gidwin e do captor dele.', 'Nós, paladinos, somos ensinados a exercitar julgamento e controle ao lidarmos com inimigos, mas isto é uma emergência e, sinceramente, nunca prestei atenção direito ao que meus instrutores diziam, de qualquer modo.$b$bSeguirei para o Bosque Pestilento e verei o que consigo descobrir sobre o Giddy. Você cuida do Flagelo logo ao nosso nordeste, do outro lado desta torre. Os mortos-vivos não temem a morte mas, se você bater neles o suficiente, talvez eles soltem as linguas e nos deem algumas pistas sobre o paradeiro do Gidwin.', '', 'Engenheiro de Cerco do Flagelo espancado', 'Descubra a localização do Gidwin', 'Descubra o captor do Gidwin', '', '', '', '', '', 'Fale novamente com a Fiona na Torre do Passo Norte, que fica nas Terras Pestilentas do Leste.', 0),
(27523, 'ptBR', 'Ah, Quiroscuro, como vos odeio...', 'Obtenha um Tufo de Pele de Quiroscuro.', 'Eu vi muitas coisas na minha época, $r. Os picos do Monte Hyjal... as estranhezas da Terralém... uma muralha de soldados do Flagelo rumo à guerra. Mas nunca vi um morcego tão grande ou tão surpreendentemente branco como o Quiroscuro.$B$BComo ele me atormenta daquele poleiro!$b$bEsse demônio albino circula a sudoeste daqui, ao norte do Lago Bosquenero. Encontre-o e destrua-o. Se ele voar alto demais para que você o alcance, use o meu sinalizador para chamar a atenção dele.', '', '', '', '', '', '', 'Quiroscuro', '', '', 'Fale novamente com Queimacorpos Tim na Torre do Passo Norte, que fica nas Terras Pestilentas Orientais.', 0),
(27524, 'ptBR', 'Fúria cega', 'Encontre Tarenar Golpessol dentro do Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 'Tarenar não estava brincando quando disse não se importava com julgamento e cautela. Quando ele saiu correndo para o Bosque Pestilento atrás do Gidwin, quase arrancou a cabeça daquele elfo superior ao passar por ele. Seria bom se você também fosse para lá.$b$bO Bosque Pestilento é um lugar grande, $n. Boa sorte. Espero ver vocês três saindo do bosque inteiros.', '', '', '', '', '', '', '', '', '', '', 0),
(27525, 'ptBR', 'Guardiões de Stratholme', 'Mate Omasum Casco Podre e Karthis Umbruniel.', 'A Baronesa Anastari está mantendo ele preso? Aqui, no Bosque Pestilento?$b$bO Bosque Pestilento é bem grande... mas vamos achar ele. Nós VAMOS encontrar o Gidwin.$b$bA leste e oeste de onde estamos, há um par de necrópoles que ladeiam Stratholme. Dentro delas, você encontrará dois cavaleiros da morte – tenentes de Rivendare. Duvido que qualquer um dos dois tenha alguma utilidade para um refém paladino, mas talvez eles saibam algo sobre onde ele está.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tarenar Golpessol dentro do Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 0),
(27526, 'ptBR', 'Revelação do destino do Gidwin', 'Procure Gidwin Fitáurea dentro do matadouro no centro do Bosque Pestilento.', 'Depressa, encontre uma entrada para o matadouro ao sul. Encontrarei você lá dentro.$b$bEsteja pront$go:a; para lutar!', '', 'Encontre Gidwin Fitáurea', '', '', '', '', '', '', '', 'Fale com Gidwin Fitáurea dentro do Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 0),
(27527, 'ptBR', 'O fim da jornada', 'Fale com a Fiona na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 'Estou farto do estilo deste lugar. Como se já não bastasse o fedor dos mortos-vivos, ainda por cima esses cogumelos!? Eu odeio cogumelos!$b$bVoltarei à Capela Esperança da Luz, $n... e levarei Tarenar e Fiona comigo. Acho que nós todos fizemos por merecer um descanso justo.$b$bDeixe-me te dar isso. É a minha pedra de regresso – você pode usá-la para viajar instantaneamente de volta para a Esperança da Luz. Eu não vou precisar dela – vou estar na caravana, afinal de contas.$b$bNO BANCO DA FRENTE.', '', '', '', '', '', '', '', '', '', '', 0),
(27528, 'ptBR', 'Massa Flagelada', 'Mate 8 Golens Socados e então, use a Tocha do Cruzado nos corpos deles.', 'Você não pode simplesmente matar o Flagelo. Eles ficam voltando. Você tem que destruir a matéria vil que constitui os próprios seres... e mesmo assim, eles podem voltar como espectros.$b$bPoucos mortos-vivos usam tanta massa quanto as abominações claudicantes. Mate-as e, então, queime os corpos deles. Você os encontrará por todo o Bosque Pestilento.$b$bNunca deixe a sua raiva se dissipar, $r. Lembre-se: essas abominações são costuradas a partir dos corpos de boas pessoas. O crime deles é existir.', '', 'Corpos de Golens Socados queimados', '', '', '', '', '', '', '', 'Fale novamente com o Cruzado Kevin Gelo no Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 0),
(27529, 'ptBR', 'Defensores da Vila das Flechas', 'Liberte 8 Espíritos da Vila das Flechas dos corpos de Carniçais Canibais e, então, fale com eles.', 'A batalha da Vila das Flechas foi repleta de tragédias que nós, humanos, sofremos nas mãos do Flagelo. Mesmo hoje, ainda sentimos os efeitos.$b$bMuitos dos corajosos defensores da cidade agora vagueiam como assombrações à serviço do Flagelo. Daremos um basta ao sofrimento deles.$B$BCace carniçais canibais por aqui, dentro do Bosque Pestilento. Muitos desses vilões já foram o bom povo da Vila das Flechas, e a destruição das formas que atualmente têm libertará as almas deles.', '', 'Espíritos da Vila das Flechas Libertados', '', '', '', '', '', '', '', 'Fale novamente com o Cruzado Kevin Gelo dentro do Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 0),
(27530, 'ptBR', 'As bestas de carne', 'Destrua os cascos de três Bestas de Carne colocando três ou mais Fontes de Luz Argênteas perto delas. Você não pode criar Fontes de Luz Argênteas em combate e você não pode colocá-las a menos de dez metros uma da outra.', 'Ao sul, sectários covardes se concentram em uma tarefa sinistra: reanimar enormes pedaços de carne para criar gigantes conhecidos como bestas de carne. Para a nossa sorte, esses gigantes ainda estão sem vida e fracos.$b$bPegue este encantamento – usá-lo criará uma fonte de energia sagrada no chão. Se você conseguir colocar três dessas perto das bestas de carne que os sectários estão reanimando, a energia sagrada deverá sobrecarregá-las, destruindo os seus corpos para sempre.', '', 'Besta de Carne destruída', '', '', '', '', '', '', '', 'Fale novamente com o Cruzado Kevin Gelo dentro do Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 0),
(27531, 'ptBR', 'Pesquisa contra a peste', 'Obtenha 20 Frutapodres, 5 Braços Decepados e 1 pilha de Raspas do Pé do Gigante de Carne.', 'Eu já trabalhei para a chamada "Rainha-banshee", Sylvana, como boticário. Eu costumava admirá-la, mas algo mudou dentro dela. Desde então, ela está fora de si.$b$bQuebrei os juramentos que fiz aos Renegados e me juntei à Cruzada. Agora, uso o meu conhecimento de alquimia para procurar um agente contra a peste. E o Bosque Pestilento é o lugar perfeito para isso.$b$bPreciso me reabastecer de alguns reagentes, que podem ser encontrados no Bosque Pestilento. Pagarei você se me trouxer qualquer um desses itens.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Boticário Argênteo Judkins na Torre do Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 0),
(27532, 'ptBR', 'Torre do Bosque Pestilento', 'Leve o Pacote do Sinalto ao Boticário Argênteo Judkins na Torre do Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 'Com os recentes e infelizes desdobramentos envolvendo o Gidwin, pode não ser sábio para um homem da minha idade embarcar em uma viagem perigosa pelo Bosque Pestilento. Tudo certo – posso visitar a Torre do Bosque Pestilento na próxima vez que viajar dando a volta.$b$bAinda assim, tenho uma entrega que precisa chegar ao Judkins. Você é mais jovem do que eu, além de mais forte em combate. Você levaria esta entrega para ele?', '', '', '', '', '', '', '', '', '', 'Fale com o Boticário Argênteo Judkins na Torre do Bosque Pestilento, que fica nas Terras Pestilentas.', 0),
(27533, 'ptBR', 'Uma sina pior do que o matadouro', 'Mate 9 Suínos Pestilentos.', 'O povo da Várzea do Medo, primeiro, ficou doente e, então, tornou-se mau. Maus tempos, sem dúvida.$b$bOs porcos, por outro lado... também estão doentes! O que os porcos fizeram para merecer isso? Ha, ha, ha! Nada!$b$bEu não ligo muito para pessoas, mas os porcos maus ainda me deixam triste. Se você matar eles, por outro lado... pode ser que eu fique feliz.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Augustus, o Pirado, na Várzea do Medo, que fica nas Terras Pestilentas Orientais.', 0),
(27534, 'ptBR', 'Livro-caixa do Augustus', 'Pegue o Livro-caixa do Augustus da estalagem na Várzea do Medo.', 'Estou pronto para os negócios! O que você deseja?$B$BEi, espere... Não posso abrir a loja sem o meu livro-caixa. Como vou saber o que estou fazendo sem o meu livro-caixa?$B$BDevo ter deixado ele na cidade, em algum lugar. Eu tinha um quarto na estalagem... o livro deve estar lá.$B$BTraga-me o meu livro. Por favor, traga ele para mim! Traga-me o meu livro e você vai ver! Vou abrir a loja e você verá que os meu preços são LOUCOS!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Augustus, o Pirado, na Várzea do Medo, que fica nas Terras Pestilentas Orientais.', 0),
(27535, 'ptBR', 'Só uns parafusos a menos', 'Fale com Augustus, o Pirado, na Várzea do Medo.', 'Eu gosto de ver como está o Augustus, na Várzea do Medo, de vez em quando, só para ter certeza de que ele está bem. Alguns de nós, mortos-vivos, são menos afetados pela peste que outros, eu acho.$b$bA Várzea do Medo fica a oeste daqui. Você se importaria em conferir como ele está para mim?', '', '', '', '', '', '', '', '', '', 'Fale com Augustus, o Pirado, na Várzea do Medo, que fica nas Terras Pestilentas Orientais.', 0),
(27536, 'ptBR', 'Praticamente inofensiva', 'Colete 8 Minas Terrestres Desarmadas na Penumbra das Mágoas, a leste do Brejo do Goblin.', 'Tem outro favor que quero de você, camarada.$B$BPedimos um carregamento inteiro de minas terrestres de Angra do Butim outro dia. Mas alguém roubou todas elas à noite!$B$BQuem quer que tenha sido, foi descuidado a ponto de derrubar todas pelo pântano a leste. Não conheço um goblin que seria tão descuidado.$B$BPreciso que você colete essas minas terrestres pra mim. Tenho certeza de que elas estão perfeitamente seguras e desarmadas. Todas elas. Sem dúvida.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Mercador Romprata no Pântano das Mágoas.', 0),
(27537, 'ptBR', 'Fecha-se um portal, abrem-se outros', 'Mate Elementais de Água Turva para coletar 5 Núcleos do Redemoinho.', 'Nossos amigos da Harmonia Telúrica têm tentado, em vão, abrir portais de volta para Ventobravo. Mas Thordun me disse que ele deve ter a chave.$B$BOs elementais da água descontrolados nas redondezas do delta do Rio Verrall entraram em transe. Thordun diz que podemos canalizar a energia deles num portal.$B$BNão entendo nada dessa ladainha dos elementais, mas de uma coisa sei: matar elementais e tirar seus núcleos. Entregue-os para Talaa no pátio.', '', '', '', '', '', '', '', '', '', 'Entregue os Núcleos do Redemoinho para Talaa em Beiralta, que fica no Planalto do Crepúsculo.', 0),
(27538, 'ptBR', 'O cataplasma perfeito', 'Colete 10 porções de Lama do Rio Verrall.', 'Você está a caminho do delta do rio Verrall? Tenho uma dica que vai ajudar seus homens... e meu pássaro!$B$BQuando os elementais da água cavam seu caminho pelas pedras, deixam um rastro peculiar de lama que seca e fica rígida como uma rocha e com os poderes rejuvenescedores da água. Dá pra fazer um molde rígido como aço unindo essa lama e ossos quebrados.$B$BLeve um pouco da lama para Talaa, a xamã que está lá embaixo. Ela sabe o que deve ser feito!', '', '', '', '', '', '', '', '', '', 'Leve a lama para Talaa em Beiralta, que fica no Planalto do Crepúsculo.', 0),
(27539, 'ptBR', 'Adicione-os à pilha', 'Obtenha 16 Caveiras Fedorentas de Magos Amaldiçoados e Soldados do Flagelo no Bosque Pestilento.', 'Venho colecionando os crânios dos esqueletos que venço. Já tenho uma pequena pilha deles.$b$bSe você encontrar qualquer crânio, sinta-se à vontade para adicioná-lo à minha pilha. A enorme pilha de crânios parece manter os mortos-vivos afastados e... bem... eu fico feliz em olhar para ela.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Cruzado Kevin Gelo dentro do Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 0),
(27540, 'ptBR', 'O Martelo Feroz', 'Fale com Gavan Penagris na Bastilha Ventobravo.', 'Tenho certeza de que você sentiu os terremotos. Talvez até tenha visto os elementais atacando as cidades. A Harmonia Telúrica se esforça para entender o que está havendo. Tivemos sorte por receber ajuda dos xamãs Martelo Feroz.$b$bGavan Penagris está na Bastilha Ventobravo coordenando nossa investida junto com muitos líderes das facções. Fale com ele e tente descobrir algo sobre os recentes eventos, $n.', '', '', '', '', '', '', '', '', '', 'Fale com Gavan Penagris na Bastilha Ventobravo.', 0),
(27541, 'ptBR', 'Lições do passado', 'Obtenha os Óculos Quebrados.', 'Este explorador desafortunado certamente sofreu de má sorte no passado recente.$b$bA prudência dita que você deve realizar a indesejável tarefa de revistar os cadáveres em busca de pistas que possam lançar alguma luz à sua volta...', '', '', '', '', '', '', '', '', '', 'Leve os Óculos Quebrados para Harrison Jones na Câmara das Estrelas.', 0),
(27542, 'ptBR', 'Conquistando a frente de batalha', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27544, 'ptBR', 'Tenacidade cenariana', 'Fale com Rayne próxima da entrada do Vale Fungi.', 'Aqueles druidas nunca desistem, vou te contar. Eu já teria desistido das Terras Pestilentas há anos, mas o pessoal do Círculo Cenariano vive me dizendo que a região ainda tem esperança.$b$bA mais recente visitante foi uma elfa noturna a caminho do Vale Fungi, ao norte. Ela me disse que estas terras serão totalmente recuperadas, se nos esforçarmos o bastante. Não sei se acredito nela.$b$bVocê compra esse papo? Talvez vocês devessem conversar. Ela ainda deve estar por aí.', '', '', '', '', '', '', '', '', '', 'Fale com Rayne perto da entrada do Vale Fungi, que fica nas Terras Pestilentas Orientais.', 0),
(27545, 'ptBR', 'O caminho está livre', 'Fale com Kurdran Martelo Feroz em Beiralta, que fica no Planalto do Crepúsculo.', 'Meu companheiro xamã e eu ficaremos aqui para mantermos o portal aberto.$B$BTu deves ir lá em cima e notificar Kurdran que o trabalho foi feito. Ele ficará satisfeito em ter boas notícias ao menos uma vez.', '', '', '', '', '', '', '', '', '', 'Fale com Kurdran Martelo Feroz em Beiralta, que fica no Planalto do Crepúsculo.', 0),
(27546, 'ptBR', 'Fale com o Capitão Nascimento', 'Fale com o Capitão Nascimento na Bastilha Ventobravo.', 'Tenho certeza de que você sentiu os terremotos. Talvez até tenha visto os elementais atacando as cidades. Enviamos as nossas mais brilhantes mentes a Nagrand para entrarem em comunhão com os elementos.$b$bMas ainda temos muito que fazer por aqui. Os guardas de Ventobravo estão sendo esmagados por cidadãos loucos, querendo notícias de seus familiares desaparecidos.$b$bPor favor, $c, fale com o capitão Nascimento na Bastilha Ventobravo e veja se tem algo em que você possa ajudar.', '', '', '', '', '', '', '', '', '', 'Fale com o Capitão Nascimento na Bastilha Ventobravo.', 0),
(27547, 'ptBR', 'Uma missão sem importância', 'Resgate 8 Soldados Covardes.', 'Nossas tropas em Lenhardente foram sobrepujadas recentemente por um ataque surpresa. A 7ª Legião conseguiu infiltrar batedores na cidade, e acabaram dizimando nossas tropas.$B$BA Dama Sombria nos designou para uma missão de resgate. Se ainda houver soldados vivos, eles com certeza são inúteis, mas nós fazemos o que a Dama Sombria manda.$B$BVamos acabar com essa bobagem, $n. Lenhardente fica diretamente a sudoeste da Linha de Frente dos Renegados.', '', 'Soldado Covarde resgatado', '', '', '', '', '', '', '', 'Fale com o Barão Ashbury na Floresta de Pinhaprata.', 0),
(27548, 'ptBR', 'Lições de medo', 'Mate 12 Batedores da 7ª Legião', 'Nossos inimigos estão ficando mais inteligentes. Estão se adaptando às nossas táticas. Recentemente, eles atacaram o Vilarejo Lenhardente, a sudoeste daqui. Nossas forças na cidade foram dizimadas, claro... mas o que nos chamou a atenção nesse ataque foi a... composição racial da tropa atacante. Nenhum humano fez parte dela.$B$B<Walden ri.>$B$BEles temem ser reanimados como Renegados, e com razão.$B$BVamos ensinar aos humanos uma lição sobre o medo. Juntos vamos mostrar a eles o que acontece com os cadáveres que não conseguimos usar.', '', '', '', '', '', '', '', '', '', 'Fale com Lorde Walden na Floresta de Pinhaprata.', 0),
(27549, 'ptBR', 'Pela luz das estrelas', 'Colete 7 Luzes Estelares Suspensas.', 'Veja isto, $n.$b$b<Harrison ergue os óculos do batedor morto.>$b$bApertei a junção no meio e dobrei as pontas das hastes. Eles podem não ser muito confortáveis, mas devem ficar inteiros.$b$bSe traduzi as suas tabuletas corretamente, há algo escondido aqui... Uma última peça para o nosso quebra-cabeça.$b$bEspero que os seus óculos contenham a chave.$b$bConte-me o que você descobrir!', '', '', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Câmara das Estrelas.', 0),
(27550, 'ptBR', 'A queda de Lenhardente', 'Use o Feixe de Tochas para queimar a Prefeitura de Lenhardente, a Taberna de Lenhardente e a Capela de Lenhardente.', 'Os ataques à nossa linha de frente são apenas para nos distrair. Com nossa atenção voltada para o massacre worgen, a Aliança conseguiu arrancar o Vilarejo Lenhardente das mãos de nossas tropas.$B$B<Godfrey dá a você um feixe de tochas.>$B$BO lugar deve ser purificado.$B$BCom essas tochas, incendiaremos o Vilarejo Lenhardente até o chão, e nossos inimigos terão que se esconder debaixo das cinzas.$B$BMas chega de perder tempo. Lenhardente fica diretamente a sudoeste da Linha de Frente dos Renegados. Leve-nos até lá, $n.', '', 'Taberna de Lenhardente incendiada', 'Capela de Lenhardente incendiada', 'Prefeitura de Lenhardente incendiada', '', '', '', '', '', 'Fale com Lorde Godfrey na Floresta de Pinhaprata.', 0),
(27551, 'ptBR', 'A missiva da baronesa', 'Leve a Missiva da Baronesa para o Tarenar.', 'O bilhete é da Baronesa Anastari e descreve um ritual que está prestes a acontecer no matadouro central do Bosque Pestilento – logo ao sul de onde está o Tarenar. Talvez seja lá que prenderam o Gidwin!$b$bO Tarenar vai querer saber disso... e depressa, antes que seja tarde demais!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Tarenar Golpessol dentro do Bosque Pestilento, que fica nas Terras Pestilentas Orientais.', 0),
(27552, 'ptBR', '[FLAG] EPL Zone Buff - Flag 1', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27553, 'ptBR', '[FLAG] EPL Zone Buff - Flag 2', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27554, 'ptBR', '[FLAG] EPL Zone Buff - Flag 3', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27555, 'ptBR', 'Patuá da sorte da Fiona', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27556, 'ptBR', 'Óleo para armas do Gidwin', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27557, 'ptBR', 'O talismã do Tarenar', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27558, 'ptBR', 'A boneca de Pâmela', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27559, 'ptBR', 'Os embraces de Vex\'tul', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27560, 'ptBR', 'O diário do Argus', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27561, 'ptBR', 'A pedra do Rimblat', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27562, 'ptBR', 'A engrenagem do Beezil', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27563, 'ptBR', '[FLAG] Beezil\'s Flag', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27564, 'ptBR', 'Em defesa do Reduto', 'Fale com Calen no Rubro Reduto.', 'Calen mandou notícias: o Crespúsculo está no Reduto!$B$BSe houver um momento para ganhar a graça de Calen, o momento é este!', '', '', '', '', '', '', '', '', '', '', 0),
(27565, 'ptBR', 'Para a prisão', 'Encontre César Dâmaso', 'Conseguimos nos infiltrar na prisão dos Ferro Negro!$B$BBem... acho que conseguimos.$B$BCésar Dâmaso teve a... honra... de ver o que estava acontecendo lá, mas não recebemos notícias dele desde então. Você parece uma pessoa que não gosta de morrer... não gostaria de ir lá ver se está tudo bem?$B$BEle deve estar no salão no extremo sul da caverna em frente... embora eu acredite que ele não tenha chegado tão longe.', '', '', '', '', '', '', '', '', '', '', 0),
(27566, 'ptBR', 'A comitiva de Terralém', 'Fale com Gavan Penagris no Trono dos Elementos, que fica em Nagrand.', 'Saudações, $c. Os elementos estão cada vez mais inquietos e ainda estamos muito longe de encontrar a solução para esse problema. Alguns dos nossos mais sábios xamãs se reuniram em Nagrand, no Trono dos Elementos, para discutir sobre tudo o que aflige nossa terra.$b$bVá ao Trono dos Elementos e fale com Gavan Penagris. Tenho certeza de que você poderá ajudá-lo.', '', '', '', '', '', '', '', '', '', 'Fale com Gavan Penagris no Trono dos Elementos, que fica em Nagrand.', 0),
(27567, 'ptBR', 'Crepúsculo?! Ah, não!', '"Interrogue" a Suprema Interrogadora Gerstahn.', 'Sei que é difícil de acreditar, mas há membros do Martelo do Crepúsculo aqui no Abismo Rocha Negra! Não sei quantos, mas ouvi dizer que a chefe interrogadora deles, Gerstahn, está neste corredor.$B$BNão sei o que eles pretendem com as torturas, mas talvez você consiga descobrir se pedir com jeitinho para a Gerstahn...', '', '', '', '', '', '', 'Suprema Interrogadora Gerstahn', '', '', 'Fale novamente com César Dâmaso.', 0),
(27568, 'ptBR', 'Infiltrados na Cidade de Umbraforja', 'Fale com o Prospector Seymour.', 'Se eu te contar uma coisa, tu guarda segredo? Te prepara que é dos bons!?$B$BAqui tem mais DOIDO que Luaprata em dia de festa!!!$B$BTem goblins pras bandas de lá, Ferro Negro pras bandas de cá, e ainda um negócio de fogo pra mais de légua de tamanho atrás daquele portão! E isso tudo nessa caverninha!$B$BMas... o que tu tá fazendo aqui?!$B$BBah, entendi.. Piscadela te mandou, né? Ele falou pra tu caçar o prospector Seymour, né? O sujeito tá pra lá dessas grades, seguindo pela direita. Tudo bem, pode ir... Oralius não liga mesmo!$B$B...TU ME PAGA, PISCADELA!!!$B$B<Oralius começa a choramingar.>', '', '', '', '', '', '', '', '', '', '', 0),
(27569, 'ptBR', 'Táticos dos Ferro Negro', 'Mate o General Forjaversa e o Lorde Golem Argelmach.', 'O General Forjaversa e o Lorde Golem Argelmach lideram os exércitos dos Ferro Negro e seus golens contra nós. Se quisermos avançar, precisamos matar os dois.$B$BPasse por esta porta e abra a Trava da Umbraforja que separa as Guarnições Leste e Oeste. Depois, suba as escadas e mantenha-se à esquerda até chegar à Guarnição Oeste. É lá que você vai encontrar o General e o Lorde Golem.$B$BFique $Gesperto:esperta;, eles são bons de briga. Encontre Mayara Asaluz caso seja bem-$Gsucedido:sucedida;.', '', '', '', '', '', '', '', '', '', 'Fale com Mayara Asaluz.', 0),
(27570, 'ptBR', 'A situação até então', 'Fale com Goturo Quatro Ventos no Castelo Grommash, que fica em Orgrimmar.', 'Tenho certeza de que você sentiu os terremotos. Talvez até tenha visto os elementais atacando as cidades. A Harmonia Telúrica se esforça para entender o que está havendo. Tivemos sorte de ter um dos maiores xamãs como nosso Chefe Guerreiro.$b$bThrall está conversando com os conselheiros e não pretendo atrapalhar a reunião. Mas talvez nosso irmão Goturo Quatro Ventos saiba algo dos planos dele.', '', '', '', '', '', '', '', '', '', 'Fale com Goturo Quatro Ventos no Castelo Grommash, que fica em Orgrimmar.', 0),
(27571, 'ptBR', 'O Glutão Implacável', 'Brigue com Hurley Bafonegro, Birra Guardachave e Ribas Parafuseta.', 'Alguns dizem que o Glutão Implacável é o segredo dos Ferro Negro na guerra. Eles recarregam as baterias lá e saem de novo, doidos pra pegar mais inocentes. Acho que se causarmos um pouco de caos, conseguiremos atrasá-los seriamente.$B$BPreciso que você puxe briga com três famigerados clientes do bar. Destrua os barris e Hurley Bafonegro virá correndo. Roube qualquer coisa das mesas perto do Birra Guardachave e ele vai encarar. E quanto ao Ribas Parafuseta... bom, basta puxar conversa com ele. Apresente-se a Orfus quando tiver terminado.', '', '', '', '', '', '', '', '', '', 'Fale com o Montanhista Orfus.', 0),
(27572, 'ptBR', 'A comitiva de Terralém', 'Fale com Thrall no Trono dos Elementos, que fica em Nagrand.', 'Saudações, $c. Os elementos estão cada vez mais inquietos e ainda estamos muito longe de encontrar a solução para esse problema. Alguns dos nossos mais sábios xamãs se reuniram em Nagrand, no Trono dos Elementos, para discutir sobre tudo o que aflige nossa terra.$b$bVá ao Trono dos Elementos e fale com o nosso Chefe Guerreiro. Tenho certeza de que você poderá ajudá-lo.', '', '', '', '', '', '', '', '', '', 'Fale com Thrall no Trono dos Elementos, que fica em Nagrand.', 0),
(27573, 'ptBR', 'O pacto Ferro Negro', 'Mate o Embaixador Fogaçoite e Ruine\'rel.', 'À frente, temos a criatura conhecida como Embaixador Fogaçoite. Ele é o embaixador da Nação Ferro Negro eleito por Ragnaros, o Senhor do Fogo. Além daquela câmara, encontra-se a Tumba dos Evocadores, lar dos espíritos dos sete patriarcas dos Ferro Negro que evocaram Ragnaros para nosso mundo.$B$BVocê pode não ter ouvido falar do Grande Fogo, mas será a ruína de Azeroth se não o impedirmos. Os indivíduos que estão diretamente ligados a ele comandam os Ferro Negro. Mate todos eles para que a nação possa se redimir no futuro.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Oficial Maxwell.', 0),
(27574, 'ptBR', 'Nunca esqueço um rosto', 'Entregue a Cabeça Parcialmente Digerida para Lorde Godfrey na Floresta de Pinhaprata.', 'Você descobriu uma cabeça parcialmente digerida. Lorde Godfrey se agita quando vê a cabeça. Talvez você deva entregá-la para ele.', '', '', '', '', '', '', '', '', '', '', 0),
(27575, 'ptBR', 'Do ventre das feras', 'Recupere o Torso de Dempsey, os Membros de Dempsey e as Entranhas de Dempsey.', 'Creio que podemos recuperá-lo. Quem sabe se o "montarmos" de novo, ele não nos dá informações sobre Crowley?$B$BMataremos todos os crocoliscos desse charco até encontrarmos o resto do corpo de Dempsey! Ele renascerá do ventre das feras!', '', '', '', '', '', '', '', '', '', 'Fale com Lorde Godfrey na Floresta de Pinhaprata.', 0),
(27576, 'ptBR', 'Comando goblínico de elite', 'Fale com Mathiaz no Desfiladeiro da Presa do Dragão.', 'Acontecimentos recentes deixam claro que ficar por aqui e realizar ataques esporádicos não é suficiente para manter nossa espécie a salvo, muito menos para retomar Grim Batol. Precisamos ser mais agressivos: temos que atacar direto no coração do inimigo.$B$BConcordei em mandar dragões para auxiliar seus comandantes. Eles já estavam planejando um ataque a Grim Batol, assim você deveria concentrar sua atenção primeiramente nisso.$B$BVocê deve encontrar Mathiaz no Desfiladeiro da Presa do Dragão, no cânion mais abaixo, ao sul daqui.', '', '', '', '', '', '', '', '', '', '', 0),
(27577, 'ptBR', 'Planos de Batalha da 7ª Legião', 'Recupere os Planos de Batalha da 7ª Legião.', 'Muito embora tenhamos obtido uma vantagem sobre a Aliança com a destruição de Lenhardente, o nosso objetivo real aqui é incapacitá-la.$B$BA sudoeste daqui, próximo à Muralha Greymane, fica o Acampamento da 7ª Legião. Precisamos vasculhar o acampamento e encontrar os planos de batalha. Com os planos de batalha da 7ª Legião, poderemos identificar todos os deslocamentos das tropas da Aliança na Floresta de Pinhaprata.', '', '', '', '', '', '', '', '', '', 'Fale com Lorde Walden na Floresta de Pinhaprata.', 0),
(27578, 'ptBR', 'Comemoração de Morgan', 'Mate o Imperador Dagran Thaurissan.', 'Do alto de seu trono, o Imperador Dagran Thaurissan tem total controle sobre a cidade. Se quisermos dar um fim aos exércitos dele, teremos que acabar com o reinado do imperador.$B$BVocê terá que passar pela guarda pessoal de Thaurissan – inclusive o gigante Magmus – para chegar até ele. Seja $Grápido:rápida;, pois, se descobrirem nossos planos, toda a cidade virá defendê-lo.$B$BAs portas do outro lado do Liceu só se abrirão depois que você acender os braseiros usando as tochas dos guardachamas. Boa sorte.', '', '', '', '', '', '', 'Imperador Dagran Thaurissan', '', '', 'Fale novamente com o Oficial Maxwell.', 0),
(27579, 'ptBR', 'Para a prisão', 'Encontre Lexlort.', 'O Martelo do Crepúsculo tá aqui por alguma razão, mas não sei qual. O Thal\'trak aqui vai te contá um segredinho: o ladino Lexlort tá lá do lado de fora do salão da Suprema Interrogadora Gerstahn, só esperando ela saí pra acabá com ela.$B$BMas ela ainda não caiu nessa. Então, rola de você dá uma mãozinha? É só falá com o Lexlort, que ele te conta tudo direitinho.', '', '', '', '', '', '', '', '', '', '', 0),
(27580, 'ptBR', 'Semeando a discórdia', 'Execute o General Marpetra.', 'Os reforços da Aliança montaram uma base de operações na região sudoeste de Pinhaprata. É o Acampamento da 7ª Legião. Nosso objetivo primário é semear a discórdia entre as tropas do acampamento. Essa será uma missão de execução relâmpago. O alvo é o comandante de campo deles, o general Marpetra. A morte dele não vai deter o avanço da Aliança, mas certamente vai acalmar o moral das tropas.', '', '', '', '', '', '', 'General Marpetra', '', '', 'Fale com Lorde Godfrey na Floresta de Pinhaprata.', 0),
(27581, 'ptBR', 'Crepúsculo?! Ah, não!', 'Mate a Suprema Interrogadora Gerstahn.', 'Tem muita gente protegendo Gerstahn e ela não é burra de sair de lá, então eu não vou matá-la.$B$BVocê vai.$B$BMas não se preocupe: a recompensa vai valer a pena. É uma coisinha que peguei de um dos guardas.', '', '', '', '', '', '', 'Suprema Interrogadora Gerstahn', '', '', 'Fale novamente com Lexlort.', 0),
(27582, 'ptBR', 'Infiltrados na Cidade de Umbraforja', 'Fale com Razal\'gume', 'Estamos em uma batalha que não vai nada bem. Desde a aliança entre os Ferro Negro e os elementais, ficou impossível lutar contra os novos guerreiros que eles trazem.$B$BPreciso que você nos ajude a entrar nos domínios deles para matar o maior número possível de líderes. Com sorte, isso vai enfraquecê-los e virar a maré a nosso favor. Fale com Razal\'gume para mais informações. Ele se encontra depois deste portão, virando à direita.', '', '', '', '', '', '', '', '', '', '', 0),
(27583, 'ptBR', 'O flanco norte', 'Apresente-se a Gralok na Angra do Resvalo, que fica no Planalto do Crepúsculo.', 'Ordenei que montassem uma área de defesa na costa norte, em Angra do Resvalo. Nossos batedores relataram que as nagas estão tentando tomar aquelas terras.$B$BGralok está comandando a operação – apresente-se a ele e vigie aquela praia!', '', '', '', '', '', '', '', '', '', 'Apresente-se a Gralok na Angra do Resvalo, que fica no Planalto do Crepúsculo.', 0),
(27584, 'ptBR', 'Ondas de sangue', 'Mate 15 Saqueadores Escamanegra ou Damas Escamanegra.', 'A ralé naga pensa em se locomover rio acima para reforçar o Bastião do Crepúsculo. Vamos CORTAR as cabeças e ARRANCAR as espinhas delas!$B$B<Gralok risca a terra com sua espada.>$B$BDestrua os Escamanegra!', '', 'Naga Escamanegra morta', '', '', '', '', '', '', '', 'Fale com Gralok na Angra do Resvalo, que fica no Planalto do Crepúsculo.', 0),
(27585, 'ptBR', 'A 109ª Divisão', 'Mate o General Forjaversa e o Lorde Golem Argelmach.', 'O General Forjaversa e o Lorde Golem Argelmach são os responsáveis pela terrível chacina da 109ª Divisão da Força Expedicionária de Karrath. Tínhamos excelentes trolls e orcs lá, muitos deles amigos meus.$B$BMuito bem, jovem $c, chegou a hora de vingarmos nossos irmãos caídos.$B$BAbra a Trava da Umbraforja e suba as escadas, mantendo-se à esquerda até chegar à Guarnição Oeste. Mate Forjaversa e Argelmach. E não se atreva a ter piedade deles.', '', '', '', '', '', '', '', '', '', 'Fale com a Hierofante Theodora Malvadania.', 0),
(27586, 'ptBR', 'Em busca dos projéteis perdidos', 'Junte 8 Projéteis de Morteiro Intactos ao longo da praia em Angra do Resvalo.', 'Consegui recuperar estes morteiros dos destroços de nossa aeronau quando ela foi derrubada no Porto Presa do Dragão. Mas temos pouca munição!$B$BEnquanto estiver pela praia, me faça o favor de pegar todos os projéteis intactos que encontrar.$B$BOs que não explodiram são os melhores – você nunca sabe QUANDO eles vão explodir. Perfeitos para surpreender o inimigo!', '', '', '', '', '', '', '', '', '', 'Entregue os projéteis para Fergus Fanfa na Angra do Resvalo, que fica no Planalto do Crepúsculo.', 0),
(27587, 'ptBR', 'Maliciosamente deliciosa', 'Colete 6 Caudas Intactas de Makrura de Makruras do Pântano.', 'Sabe, eu estou com um problema e você pode me ajudar.$B$BVeja bem, além de lutar para expandir o mercado de venda de armas, eu venho tentando dar um gás na área de entretenimento aqui no Brejo do Goblin. E parece que essas tais makruras das águas ao norte não apreciam as festas selvagens que estamos promovendo na praia.$B$BProblema delas. Eu que não vou ser pressionado por um bando de lagostas superdesenvolvidas. Elas vão ser minha próxima fonte de renda! Traga uns rabos de makrura para mim, e eu vou transformar um problema em lucro.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Mercador Romprata no Brejo do Goblin, que fica no Pântano das Mágoas.', 0),
(27589, 'ptBR', 'O Glutão Implacável', 'Brigue com Hurley Bafonegro, Birra Guardachave e Ribas Parafuseta.', 'Todo mundo dentro do Glutão Implacável está completamente trêbado e louco para arrumar briga. Acho que se causarmos um pouco de caos, conseguiremos atrasar seriamente os planos dos Ferro Negro.$B$BPreciso que você arrume confusão com três famigerados clientes do bar. Destrua os barris e Hurley Bafonegro virá correndo. Roube qualquer coisa das mesas perto do Birra Guardachave e ele vai encarar. E quanto ao Ribas Parafuseta... bom, é só puxar conversa com ele. Apresente-se a Orfus quando tiver terminado.', '', '', '', '', '', '', '', '', '', 'Fale com Coração Trovejante.', 0),
(27590, 'ptBR', 'O sinal para o ataque', 'Use o Sinalizador de Ataque no topo de uma das torres no Portão do Crepúsculo.', 'Agora que você atraiu Britacrânios, o Montanha, para longe do Portão do Crepúsculo, preciso que você dê o sinal para nossas forças iniciarem o ataque!', '', 'Ataque sinalizado', '', '', '', '', '', '', '', '', 0),
(27591, 'ptBR', 'O pacto Ferro Negro', 'Mate o Embaixador Fogaçoite e Ruine\'rel.', 'Dentro desta câmara está o Embaixador Fogaçoite. Ele é o embaixador da Nação Ferro Negro eleito por Ragnaros, o Senhor do Fogo. Depois, fica a Tumba dos Evocadores, lar dos espíritos dos sete patriarcas dos Ferro Negro que evocaram Ragnaros para nosso mundo.$B$BVocê pode não ter ouvido falar do Grande Fogo, mas ele será a ruína de Azeroth se não o impedirmos. Os indivíduos que estão diretamente ligados a ele comandam os Ferro Negro. Mate todos eles e que essa aliança profana se desfaça.', '', '', '', '', '', '', '', '', '', 'Fale com o Senhor da Guerra Trincador.', 0),
(27592, 'ptBR', 'Drinques e pedras', 'Recupere 10 Garrafas Roubadas de Romprata Ice dos Guajás do Lodo.', 'Falaí, $gbrou:gata;, belê? A gente tava, tipo assim, no meio do nosso luau totalmente espontâneo quando do nada aconteceu uma parada horrível, chapa!$B$BEu tava com um engradado lotadaço de Romprata Ice, a bebida predileta do barão, mas aí vieram uns guajás do lodo e roubaram ele! Eu nunca vi guajás enchendo a cara, mas eles levaram todo o nosso goró pra dentro do mar e até a outra praia! Tamos precisando de $gum herói desenrolado:uma heroína desenrolada; que, tipo assim, nos ajude a recuperar nossa birita especial favorita!$B$B<Brono encara você por um momento.>$B$BIsso mesmo, eu tou é falando de tu, $gmermão:maninha;!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Brono Sonbom que fica no Pântano das Mágoas.', 0),
(27593, 'ptBR', 'Renascer da F.E.K.', 'Mate o Imperador Dagran Thaurissan.', 'O Imperador Dagran Thaurissan controla toda a cidade sentado no trono à frente. Se quisermos dar fim nos exércitos dele, teremos que acabar com o reinado do imperador.$B$BVocê terá que passar pela guarda pessoal, incluindo o gigante Magmus, para chegar até ele. Seja $Grápido:rápida;, pois se descobrirem nossos planos, toda a cidade virá defendê-lo.$B$BAs portas do outro lado do Liceu só se abrirão depois que você acender os braseiros usando as tochas dos guardachamas. Boa sorte.', '', '', '', '', '', '', 'Imperador Dagran Thaurissan', '', '', 'Fale novamente com o Senhor da Guerra Trincador.', 0),
(27594, 'ptBR', 'A serviço secreto de sua majestade', 'Capture a Comandante Lorna Crowley e leve-a para a Grande Dama Sylvana Correventos na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 'Lorna Crowley, filha de lorde Darius Crowley, encontra-se no acampamento da Frente de Libertação de Guilnéas, perto da Muralha Greymane, a sudoeste daqui.$B$BNossa missão consiste em nos infiltrarmos no acampamento e capturá-la viva. A Dama Sombria crê poder usar Lorna como moeda de troca com Crowley. Por mim, nós a mataríamos e a transformaríamos numa Renegada, mas devemos fazer o que a Dama Sombria comanda.$B$BPrecisamos nos apressar antes que o resto das forças da Aliança chegue aqui.', '', 'Comandante Lorna Crowley capturada', '', '', '', '', 'Comandante Lorna Crowley', '', '', 'Leve a Comandante Lorna Crowley para a Grande Dama Sylvana Correventos na Linha de Frente dos Renegados, que fica na Floresta de Pinhaprata.', 0),
(27595, 'ptBR', 'O profeta Hadassi', 'Encontre o Profeta Hadassi em Orsis.', 'O profeta Hadassi é o membro mais sábio e mais velho da tribo dos Orsis.$B$BEle não foi encontrado e seu bem-estar é de vital importância.$B$BEntre em Orsis e encontre-o. O dia do acerto de contas com os parasitas de Al\'Akir chegará se Hadassi for ferido.', '', '', '', '', '', '', '', '', '', '', 0),
(27596, 'ptBR', 'O Coração da Montanha', 'Consiga o Coração da Montanha.', 'Por anos, venho procurando uma certa gema conhecida como o Coração da Montanha, que dizem ser do tamanho do seu punho! Os anões Ferro Negro a guardam em um cofre e, embora eu insista, não querem vendê-la para mim.$B$BEntão, só me resta a violência.$B$BVá ao Cofre Negro perto do Salão da Criação, abra a fechadura e pegue o Coração. Para isto, você precisa derrotar o Vigia Gadanho, mas ele não aparecerá até que você tenha aberto todos os outros cofres de lá!$B$BBoa sorte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Maxwort Uberraio.', 0),
(27597, 'ptBR', 'Zé Pinel', 'Encontre o Zé Pinel a sudeste do Brejo do Goblin.', 'Você está pegando o jeito, $n. Uma mão lava a outra. Bem, na verdade eu lavo as mãos do seu exército inteiro, e só um pouco melhor do que as mãos do outro lado! Muito complicado?$B$BO que estou dizendo é que, enfim, são muitas mãos. Então, tenho que pedir que você lave as minhas algumas vezes mais. Quem quer que tenha roubado essas minas terrestres pode ter atingido nossos rapazes na costa a leste.$B$BVá a nosso acampamento a sudeste e converse com o Zé Pinel. Ele vai botar você por dentro.', '', '', '', '', '', '', '', '', '', '', 0),
(27598, 'ptBR', 'Guelblin bom é guelblin morto', 'Mate 7 Espreitadores Guelblins.', 'Guelblins!$B$B<Zé silenciosamente encara você por alguns instantes.>$B$BVocê nunca viu um guelblin? Eles são loucos! Mais loucos que eu! Só explodo coisas profissionalmente, esses caras são DOIDOS!$B$BNão sei de onde eles vieram, mas parecem peixes goblins horríveis! Com guelras e tudo! Eles liquidaram todos os homens na praia e levaram nosso navio cargueiro!$B$BVocê tem que ajudar! Eles estão logo a leste – vá e livre-se desses guelblins!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zé Pinel na Penumbra das Mágoas, que fica no Pântano das Mágoas.', 0),
(27599, 'ptBR', 'Eles não precisam de bolsas', 'Colete 6 Bolsas de Equipamento dos Corsários Bondebico Mortos.', 'Toda tripulação cargueira que você não vê por aqui, no acampamento, está MORTA! Eram bons goblins, mas o pior é que continuam espalhados por aí! É uma TRAGÉDIA!$B$BQuer dizer, é trágico que ainda estejam com todas suas posses! É assustador pensar em todo aquele material em perfeitas condições e nas moedas, dando sopa ali na água.$B$BEi! Você pode me fazer um favor! Se você for matar guelblins lá fora, pegue as bolsas de equipamento dos meus velhos tripulantes!$B$BQual é? Eles não vão precisar mais delas! Sejamos realistas!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zé Pinel na Penumbra das Mágoas, que fica no Pântano das Mágoas.', 0),
(27600, 'ptBR', 'Entrada explosiva', 'Fale com Zezinho Pinel para embarcar e, então, recupere todas as três mercadorias importantes do Zé Pinel.', 'Nossa fragata mercante continua na água, tomada por guelblins! AAH!$B$BDesculpa. Mas é sério! Precisamos botar você lá, de alguma forma, para pegar nossas coisas de volta. Ainda há mercadorias de qualidade naquele navio! E QUALIDADE É MEU SOBRENOME!$B$BPra sua sorte, eu tive uma ideia... Saia do acampamento e verifique ao longo da parede ao norte.  Meu filho Zezinho vai jogar você lá usando nosso canhão! Vai dar tudo certo! Quer dizer, desde que ele ande praticando...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Zé Pinel no Pântano das Mágoas.', 0),
(27601, 'ptBR', 'Poeira e ruínas', 'Acompanhe a Grande Dama Sylvana Correventos ao Campo de Batalha e derrote a Aliança!', 'Nossos exércitos se digladiam por todo o campo de batalha. Crowley e suas forças estão perdendo terreno, e eles ainda não sabem o que houve com Lorna Crowley. Nós nos encontraremos com Crowley e seus compatriotas no meio do campo de batalha, e eu os informarei dos termos da rendição. Se eles não aceitarem, transformaremos as cidades deles em poeira e ruínas.$B$BComo $gmeu:minha; soldado mais confiável, você ficará ao meu lado na hora da negociação. Me diga quando estiver $gpreparado:preparada; para partir.', '', 'Vitória: Final e absoluta', '', '', '', '', '', '', '', 'Fale com a Grande Dama Sylvana Correventos na Floresta de Pinhaprata.', 0),
(27602, 'ptBR', 'As últimas palavras do profeta', 'Encontre o Receptáculo Sagrado.', 'Nós... estamos... unidos pelo juramento... para proteger o cetro de Orsis.$B$BOuça, $c, não tenho muito tempo... de vida.$B$BEncontre o receptáculo sagrado... no extremo sul da cidade.$B$BNão... o deixe... cair nas... mãos deles...', '', '', '', '', '', '', '', '', '', '', 0),
(27603, 'ptBR', 'O portão lacrado', 'Mate Bael\'Gar.', 'Existem dois portões gigantescos, um em cada ponta da Estrada Ferro Negro. O primeiro guarda a Cidade de Umbraforja, mas não sabemos o que fica atrás do segundo!$B$BTudo que sabemos é que patrulhas dos Furiadastra o guardam, junto com o gigante Bael\'gar. Você só precisa acabar com eles e arrombar aquele portão!$B$BImagine só o que pode ter do outro lado... uma outra cidade tão grande quanto esta... ou simplesmente nada! Ninguém sabe!$B$BBem, deve ter alguma coisa por lá.', '', '', '', '', '', '', 'Bael\'Gar', '', '', 'Fale novamente com Vera Brequim.', 0),
(27604, 'ptBR', 'Jammal\'an, o Profeta', 'Obtenha a Cabeça de Jammal\'an, o Profeta.', 'Jammal\'an, o Profeta, líder dos trolls Atal\'ai e Hakkari, obteve uma pequena quantidade do sangue de Hakkar, o Esfolador de Almas. Os trolls estão injetando o sangue nos dragões verdes para forçar os corpos dos dragões a produzir quantidades enormes do sangue necessário para trazer Hakkar ao nosso mundo.$B$BNão podemos permitir que isso aconteça. Quero que mate Jammal\'an e seus sacerdotes antes que eles façam maiores progressos!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lorde Itharius.', 0),
(27605, 'ptBR', 'Erânicos', 'Mate Erânicos.', 'O sangue de Hakkar que os Atal\'ai vêm injetando nos dragões verdes está tendo efeitos devastadores nas pobres criaturas. Parece que esses dragões, antigos carcereiros dos Atal\'ai, foram corrompidos pelo sangue correndo nas próprias veias e se tornaram seres do Pesadelo.$B$BErânicos, o primeiro-consorte de Ysera e líder dos guardiões do templo, recebeu maciças quantidades do sangue e foi pervertido muito além do que podemos imaginar. Quando Jammal\'an tiver morrido, quero que encontre Erânicos e dê um fim a ele.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lorde Itharius.', 0),
(27606, 'ptBR', 'Bala nele!', 'Sopre a Concha de Heth\'Jatari perto do Estandarte Heth\'Jatari e mate o Senhor das Profundezas Heth\'Jatar. Atraí-lo para o alcance do fogo dos morteiros ajudará a completar a missão.', 'Vamos pescar, $n! Agora que os morteiros estão prontos, a gente pode cuidar do líder da invasão.$B$BO senhor das profundezas Heth\'Jatar comanda os guerreiros Escamanegra. Vá até o Estandarte Heth\'Jatari a nordeste daqui e dê uma soprada nesta concha. Parece um apito de cães, só que para peixes.$B$BQuando Heth\'Jatar aparecer, vou mandar os morteiros concentrarem fogo. Você verá os alvos dos projéteis.$B$BAtraia Heth\'Jatar para o alcance do fogo dos morteiros e mostre a ele quem manda no pedaço!', '', '', '', '', '', '', 'Senhor das Profundezas Heth\'Jatar', '', '', 'Fale novamente com Fergus Fanfa na Angra do Resvalo, que fica no Planalto do Crepúsculo.', 0),
(27607, 'ptBR', 'O flanco sul', 'Fale com Rok\'tar na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 'Nosso novo acordo com a Horda vai pôr meu povo em conflito direto com a Aliança.$B$BQue venha!$B$BEnquanto ficamos de papo, a Aliança se move para a península para ameaçar o Porto Presa do Dragão.$B$BEncontre Rok\'tar no sul – acho que ele montou um posto de comando num dos navios naufragados – e certifique-se de que a Costa do Crepúsculo continue sob nosso controle.', '', '', '', '', '', '', '', '', '', 'Fale com Rok\'tar na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27608, 'ptBR', 'Quatro cabeças e um funeral', 'Colete as quatro cabeças de Za\'brox e Beeble\'phod.', 'Estamos prestes a iniciar o ataque ao Portão do Crepúsculo, mas ainda há uma questão a ser tratada: Za\'brox e Beeble\'phod, os discípulos de Cho\'gall.$B$BA inteligência os colocou no Covil dos Discípulos, uma pequena caverna dos ogros a sudoeste do Portão do Crepúsculo.$B$BVocê voltaria lá para matar eles?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Cassius, o Branco, no Pontal do Vencedor, que fica no Planalto do Crepúsculo.', 0),
(27609, 'ptBR', 'Quatro cabeças e um funeral', 'Colete as quatro cabeças de Za\'brox e Beeble\'phod.', 'Estamos prestes a iniciar o ataque ao Portão do Crepúsculo, mas ainda há uma questão a ser tratada: Za\'brox e Beeble\'phod, os discípulos de Cho\'gall.$B$BA inteligência os colocou no Covil dos Discípulos, uma pequena caverna dos ogros a sudoeste do Portão do Crepúsculo.$B$BPor favor, volte lá e mate-os.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Lady Cozwynn no Planalto do Crepúsculo.', 0),
(27610, 'ptBR', 'A patrulha da orla', 'Patrulhe o Ponto de Controle da Cabeça de Praia na Costa do Crepúsculo. Você não precisa tomá-lo, mas, se assim o fizer, seu lado terá vantagem de combate e você será $gsinalizado:sinalizada; para JxJ.', 'Se a Aliança tomar a península, vai ser uma grande ameaça ao Porto Presa do Dragão. Isso não vai acontecer.$B$BAo sul daqui você verá uma pequena colina com um mirante de vigia da orla. Quem tiver controle sobre a colina terá toda a orla em suas mãos!$B$BVá lá e patrulhe o ponto de controle da cabeça de praia sinalizado com uma enorme bandeira. Depois, volte e fale comigo.$B$BVocê não precisa tomá-lo, a não ser que esteja querendo comprar briga com a Aliança.', 'Ponto de Controle da Cabeça de Praia patrulhado', '', '', '', '', 'Ponto de Controle da Cabeça de Praia patrulhado', '', '', '', 'Fale novamente com Rok\'tar na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27611, 'ptBR', 'Sangue e areia', 'Mate 12 Fuzileiros de Beiralta na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 'Nosso objetivo no Planalto do Crepúsculo é detonar o Bastião do Crepúsculo, mas a Aliança decidiu pela guerra.$B$BEntão, vamos dar o que eles querem: guerra!$B$BMate os fuzileiros de Beiralta até que aprendam a lição.', '', '', '', '', '', '', '', '', '', 'Fale com Rok\'tar na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27612, 'ptBR', 'Vitória que vem de dentro', 'Abra os Portais Argênteos na Ala da Biblioteca e no Salão de Armas dentro da abadia que fica na Manopla de Tyr.', 'Alguns dos nossos homens não conseguiram atravessar os portais que deveriam abrir dentro desta abadia. Você já provou ser $gesquivo e duro:esquiva e dura; em combate... agora preciso que você faça isso de novo.$b$bA abadia tem duas alas: uma biblioteca e um salão de armas. Em cada ala, você deve encontrar um portal.$b$bUse esta pedra-chave nesses portais. Isso deverá abri-los, permitindo que o resto de nossas forças tome esta abadia.', '', 'Portal aberto dentro do Salão de Armas', 'Portal aberto dentro da Ala da Biblioteca', '', '', '', '', '', '', 'Volte ao Comandante Cruzado Eligor Alvorada na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 0),
(27613, 'ptBR', 'O assassino', 'Mate Rohan, o Assassino, dentro da torre do sino da abadia na Manopla de Tyr.', 'O destino da Cruzada Escarlate é trágico, além de um tanto irônico. Antes, eles lideraram o ataque humano contra os mortos-vivos. Agora, eles próprios parecem aqueles cadáveres que outrora caçaram. Como se rebaixaram à morte-viva, não se sabe – mas é fato que são perigosos.$b$bUm dos mais mortais era um assassino chamado Rohan. Temos informações que o localizam no topo da torre do sino desta abadia. Encontre-o e mate-o, $n. E tente não morrer no caminho.', '', '', '', '', '', '', 'Rohan, o Assassino', '', '', 'Volte ao Comandante Cruzado Eligor Alvorada na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 0),
(27614, 'ptBR', 'Pilhagem escarlate', 'Obtenha o Javali Carmesim, o Cordão de Liana, a Mortalha de Uther e o Signo de Gavinrad.', 'Esta batalha já estava vencida antes mesmo de começar. Agora, estamos só praticando pontaria por esporte mesmo.$b$bDentro deste quartel, os chorosos Cruzados Escarlate se agarram aos seus preciosíssimos artefatos, mesmo alguns deles sendo sagrados demais para serem tocados por aquelas mãos mortas-vivas. Assim, eles os guardam em baús, escondidos do mundo.$b$bVocê vai encontrar esses artefatos e trazê-los de volta para mim. O lugar deles é na Cruzada Argêntea. O lugar deles é nas mãos dos íntegros.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante Cruzado Korfax na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 0),
(27615, 'ptBR', 'O arauto da ira', 'Mate Mataus, o Arauto da Ira.', 'Um dos membros mais vis da Cruzada Escarlate – Mataus, o Arauto da Ira – espreita dentro do calabouço do quartel. A morte-viva lhe veio a calhar, dado o jeito sombrio dele.$b$bSe eu fosse mais jovem, e se eu estivesse nas linhas de frente, eu próprio o aniquilaria. Do jeito que estão as coisas, não me resta escolha senão liderar as nossas forças da retaguarda. Assim, deixo que você tenha este prazer.', '', '', '', '', '', '', 'Mataus, o Arauto da Ira', '', '', 'Fale novamente com o Comandante Cruzado Korfax na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 0),
(27616, 'ptBR', 'O guarda-caça', 'Mate o Guarda-caça Leopold.', 'Já perdemos meia dúzia de homens para uma saraivada de projéteis e flechas vindos de cima desta fortaleza. O inimigo que está atirando não mostrou o rosto, mas tudo bem. Eu conheço o homem que está lá em cima.$b$bLeopold.$b$bÉ isso mesmo, um único homem lá em cima, eliminando os meus guerreiros um a um. E, pelo que posso ver, só temos $gum:uma; de você.$b$bParece uma luta justa para mim.', '', '', '', '', '', '', 'Guarda-caça Leopold', '', '', 'Fale novamente com o Comandante Cruzado Korfax na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 0),
(27617, 'ptBR', 'Chega de sujeira', 'Apresente-se à Arquimaga Ângela Santoro na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 'Você está sentindo? A mácula já está se dissipando deste lugar.$b$bUma edificação sagrada quer ser sagrada, e vilões como o Rohan e o resto da escória Escarlate só faziam atrasar isso.$b$bCom a abadia segura, demos mais um passo rumo à tomada da Manopla de Tyr. Reporte os resultados do nosso ataque à Ângela. Ela deve estar liderando a investida contra a catedral de algum ponto no centro da cidade.', '', '', '', '', '', '', '', '', '', '', 0),
(27618, 'ptBR', 'Levante Argênteo', 'Apresente-se à Arquimaga Ângela Santoro na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 'Vou dizer que já causamos dano suficiente a este quartel para chamar isso de uma vitória. Uma comandante, um guarda-caça e um bruxo, todos mortos... Sem contar as relíquias que resgatamos – ou melhor, VOCÊ resgatou.$b$bAinda resta a catedral, mas não por muito tempo. Fale com a arquimaga Ângela Santoro, no pátio central. O destino da catedral da Manopla de Tyr repousa nas hábeis mãos dela.', '', '', '', '', '', '', '', '', '', '', 0),
(27619, 'ptBR', 'A comandante', 'Mate a Comandante Escarlate Marjhan.', 'A comandante escarlate Marjhan é astuta, calculista e disposta a tudo para vencer uma batalha. Mas, antes de tudo isso, ela é leal.$b$bTenho certeza que ela está na câmara central do quartel, lutando sob a bandeira carmesim, até a vitória ou a morte.$b$bCertifique-se de que seja até a morte.', '', '', '', '', '', '', 'Comandante Escarlate Marjhan', '', '', 'Fale novamente com o Comandante Cruzado Korfax na Manopla de Tyr, que fica nas Terras Pestilentas Orientais.', 0),
(27620, 'ptBR', 'Como ratos', 'Mate o Lorde Cruzado Valdelmar.', 'Bem, fico feliz de saber que o Eligor e o Korfax deixaram um pouco da diversão para mim. Já foi uma batalha impedir que eles se metessem no meio da catedral.$b$bEsse é o SEU trabalho, afinal de contas.$b$bA catedral está na nossa frente, o último bastião do poder Escarlate. Lá dentro, o Lorde Cruzado Valdelmar repousa sobre o moribundo púlpito de mentiras da Manopla de Tyr. O último e débil vestígio da Cruzada Escarlate acaba aqui. Mate-o.', '', '', '', '', '', '', 'Lorde Cruzado Valdelmar', '', '', 'Fale novamente com Leonid Bartolomeu, o Venerado, na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 0),
(27621, 'ptBR', 'A patrulha do Barbarruiva', 'Procure Quincas Barbarruiva na Patrulha do Barbarruiva, que fica no Planalto do Crepúsculo.', 'Eu seguia meu caminho para me juntar à patrulha do Barbarruiva quando meu pássaro foi abatido.$B$BO Martelo do Crepúsculo começou a atacar de surpresa o Planalto. A las tantas, suas construções brotaram do chão e se aboletaram no meio de nossas vilas. Um baita pesadelo!$B$BNesse entrevero, Barbarruiva foi um dos poucos a manter a cabeça no lugar. Ele está tentando montar uma nova esquadra de grifos com os sobreviventes.$B$BSe tu quer trazer os Martelo Feroz para a Aliança, comece socorrendo Barbarruiva a oeste daqui.', '', '', '', '', '', '', '', '', '', 'Procure Quincas Barbarruiva na Patrulha do Barbarruiva, que fica no Planalto do Crepúsculo.', 0),
(27622, 'ptBR', 'Mais e melhores retalhadores', 'Localize um Retalhador Recuperável na Costa do Crepúsculo, use-o para invocar um Chefe Recuperador Borraquilha. Defenda o retalhador até que ele esteja funcionando novamente.', '$n, tô com um projeto prum retalhador melhor. Mas meus engenheiros não podem entrar numa zona de combate sozinhos.$B$BVá procurar um retalhador recuperável na Costa do Crepúsculo e use ele pra chamar um chefe recuperador. Você tem que proteger o retalhador enquanto damos uma "melhoradinha" nele.$B$BA Aliança nem vai saber o que acertou ela! Pelo menos até verem a campanha de marketing que tô preparando...', '', 'Retalhador Recuperável localizado', 'Retalhador Recuperável defendido', '', '', '', '', '', '', 'Fale com Sumo Gnugat na Costa do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27623, 'ptBR', 'Guardiões Colossais', 'Obtenha a Pedra da Lua e a Pedra do Sol dos Guardiões Colossais.', 'O baú que contém o cetro parece estar selado com feitiçaria e não abre.$B$BA placa sobre ele mostra duas estátuas gigantescas segurando pedras com cavidades em forma de estrela e lua em seus centros.$B$BAs duas estátuas são retratadas protegendo pirâmides parecidas com as lá de fora.$B$BTalvez valha a pena investigar isto.', '', '', '', '', '', '', '', '', '', 'Volte aos Hieróglifos Cobertos de Areia em Orsis, que fica em Uldum.', 0),
(27624, 'ptBR', 'Depois da queda', 'Colete o Orbe da Estrela da Manhã, o Orbe da Estrela da Noite, o Orbe da Estrela do Norte e o Orbe da Estrela Cadente.', '<Harrison boceja.> Isso não foi nada, na verdade.$b$bAquelas estátuas já estavam balançando... Só precisavam de um empurrãozinho mesmo.$b$bQue tal você dar uma vasculhada nesta bagunça?$b$bSinto que estamos perto de desvendarmos essa coisa toda.', '', '', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Câmara das Estrelas.', 0),
(27625, 'ptBR', 'Em defesa de Quel\'Danil', 'Mate 16 Sicários Invasores no Pavilhão Quel\'Danil.', 'Os mortos-vivos estão aqui! Os Renegados! Eles se aproximam cada vez mais, prestes a lançar um ataque com força total contra nós... aquelas abominações horrendas!$B$BOs jovens draeneis sob meu comando treinaram com os elfos do Altovale em combate. Eles não são indefesos, mas precisam de ajuda!$B$BPor favor, $n, ajuda-os! Rechaça os Renegados!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Anacoreta Traskano no Pavilhão Quel\'Danil, que fica nas Terras Agrestes.', 0),
(27626, 'ptBR', 'Os documentos do Altovale', 'Recolha os Relatórios do Altovale, os Arquivos do Altovale e as Cartas do Altovale.', 'O Altovale mantém registros detalhados aqui há anos. Mortes, nascimentos, estações... mas também informações vitais dos batedores e métodos de contato com o resto da Aliança.$B$BOs documentos foram espalhados aos quatro ventos. Se caírem nas mãos dos Renegados, mais vidas podem correr perigo! Tu precisas recuperar os documentos antes que sejam tomados pela Horda...', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Anacoreta Traska no Pavilhão Quel\'Danil, que fica nas Terras Agrestes.', 0),
(27627, 'ptBR', 'Apenas uma barata metida a besta', 'Mate 5 Escaravelhos de Ametista, 5 Escaravelhos de Safira, 5 Escaravelhos de Turquesa e 5 Escaravelhos de Esmeralda.', 'Evidentemente, as estátuas ancestrais foram o lar de várias espécies de escaravelhos.$b$bDeterminad$go:a; a deixar este lugar na melhor condição possível, você decide livrar a câmara dessas pestes.', '', 'Escaravelhos de Ametista mortos', 'Escaravelhos de Esmeralda mortos', 'Escaravelhos de Safira mortos', 'Escaravelhos de Turquesa mortos', '', '', '', '', '', 0),
(27628, 'ptBR', 'Dê notícias a Phaoris', 'Fale com o Rei Phaoris em Ramkahen, que fica em Uldum.', 'Depressa, $n! Devemos falar com meu irmão, o rei.$B$BEle está empenhado em evitar a guerra com Al\'Akir e os neferset. Ele tem esperanças tolas de que haja uma solução diplomática para este conflito.$B$BTalvez, ao ouvir o que aconteceu aqui, ele tenha bom senso.', '', '', '', '', '', '', '', '', '', '', 0),
(27629, 'ptBR', 'O voto do vizir', 'Fale com o Vizir Tenotep nos Campos Akhenet em Uldum.', 'Fazer com que o vizir Tanotep se oponha aos desejos de meu irmão será extremamente difícil. Sua posição é basicamente reforçar as decisões de Phaoris.$B$BTodavia, você deve falar com ele. Talvez ele dê ouvidos ao ponto de vista de $gum forasteiro:uma forasteira;.$B$BVocê encontrará o Vizir em serviço nos Campos Akhenet.', '', '', '', '', '', '', '', '', '', '', 0),
(27630, 'ptBR', 'O voto do Sumo Sacerdote', 'Fale novamente com o Sumo Sacerdote Amet no Dique Vir\'naal, em Uldum.', 'O voto do sumo sacerdote Amet é o único sobre o qual não temos controle.$B$BEle votará de acordo com o que suas profecias lhe disserem e nada que fizermos irá dissuadi-lo.$B$BAcredito que isso nos dá chances iguais para qualquer lado.$B$BO único problema que temos é que sua clarividência lhe abandonou desde que as barreiras em torno de Uldum caíram.$B$BEle não votará a menos que recupere o poder sobre suas profecias.$B$BSuba as escadas de qualquer lado do Dique Vir\'naal para falar com ele e veja se você pode ajudar de alguma forma.', '', '', '', '', '', '', '', '', '', '', 0),
(27631, 'ptBR', 'O voto do Alto-comandante', 'Fale com o Alto-comandante Kamsés no Posto Avançado da Legião Ramkahen em Uldum.', 'Se estamos para aprovar uma resolução de guerra, o voto do alto conselho tem que ser unânime.$B$BEstou certo que o alto-comandante Kamsés anunciará seu voto assim que ouvir o que ocorreu em Orsis.$B$BFale com ele em Ramkahen e certifique-se de que assim será. Devo preparar-me caso nossos planos falhem.', '', '', '', '', '', '', '', '', '', '', 0),
(27632, 'ptBR', 'O filho de Tanotep', 'Pegue o Mapa do Delta do Rio Vir\'naal de um Guarda Neferset.', 'Dediquei minha vida a serviço do Rei. Minha lealdade está acima de qualquer coisa... com uma exceção: meu filho.$B$BTahet foi capturado por sentinelas de Neferset.$B$BEles alegam que meu filho invadiu seu território. Phaoris está tentando negociar sua libertação... mas temo pelo pior.$B$BSe você for procurar Tahet, prometo-lhe meu voto. Não sei para onde levam seus prisioneiros, mas já vi os guardas consultarem mapas para guiá-los pela vegetação densa.', '', '', '', '', '', '', 'Guarda Neferset', '', '', '', 0),
(27633, 'ptBR', 'Hakkar, o Deus do Sangue', 'Mate o Avatar de Hakkar.', 'Hakkar... A mera menção do nome do Esfolador de Almas é o bastante para afugentar muitos. Os Atal\'ai recuperaram grande parte do esqueleto de Hakkar e estão tentando ressuscitá-lo no Sacrário do Deus Caído. Os filhos dele já começaram a aparecer por aqui.$B$BColoque este ovo no santuário. O ovo fará a evocação acontecer prematuramente. $n, não hesite. Ataque assim que o avatar aparecer!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lorde Itharius.', 0),
(27634, 'ptBR', 'The God Hakkar', 'Bring the Filled Egg of Hakkar to Yeh\'kinya in Tanaris.', 'Now it is time to capture the essence of the avatar of Hakkar.$B$BTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth. Invoke the egg\'s power to stir the dead god.$B$BHe will send his minions against you. Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar\'s spirit. When all the flames go out, the avatar of Hakkar will enter our world.$B$BDefeat him, and place his essence within the egg of Hakkar.', '', '', '', '', '', '', '', '', '', 'Return to Yeh\'kinya at Steamwheedle Port in Tanaris.', 0),
(27635, 'ptBR', 'Descontaminação', 'Entre no Limpatron 500 para iniciar o processo de descontaminação.', 'Já faz algum tempo que você está aqui em Gnomeregan, $n, e é um espanto que tenha sobrevivido e mantido a sanidade por tanto tempo! Temos que tirar você daqui.$B$BAntes que a gente possa mandar você lá para cima, para junto dos outros gnomos, você tem que passar pelo processo de descontaminação. Basta ir até a próxima sala e entrar no Limpatron 500. O aparelhinho cuida do resto! Não deve nem doer... muito.$B$BQuando você estiver $Gpronto:pronta;, apresente-se ao técnico Fanfarrão e e ele vai arranjar o equipamento adequado para você.', 'Processo de Descontaminação completo', 'Processo de Descontaminação iniciado', '', '', '', 'Processo de Descontaminação completo', '', '', '', 'Fale com o Técnico Fanfarrão.', 0),
(27636, 'ptBR', 'Apenas você e Mathias', 'Encontre o Mestre Mathias Shaw na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 'Os agentes da AVIN estão todos mortos. É hora de encontrar o mestre Mathias Shaw.$B$BAinda bem que o comandante do esquadrão disse onde ele estaria.', '', '', '', '', '', '', '', '', '', '', 0),
(27638, 'ptBR', 'Apenas você e Garona', 'Encontre Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 'Os Kor\'kron estão todos mortos. É hora de encontrar Garona Meiorken.$B$BAinda bem que o comandante do esquadrão disse onde ela estaria.', '', '', '', '', '', '', '', '', '', '', 0),
(27639, 'ptBR', 'Apenas você e Garona', 'Encontre Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 'Aquilo foi um golpe para nossos esforços. Maldito seja o Cho\'gall!$B$BFoi bom o comandante do esquadrão ter dito a você onde encontrar Garona.', '', '', '', '', '', '', '', '', '', '', 0),
(27640, 'ptBR', 'Os Dunwald não morrem jamais!', 'Procure pelos sobreviventes da família Dunwald nas Ruínas Dunwald.', 'A meu ver, a tua função é tentar unir os clãs dos Martelo Feroz com a Aliança para a guerra. Não tenho certeza se tu tem noção de onde tu está se metendo.$B$BEnfim... se é para a batalha que tu tá se preparando, tem uma família que é indispensável ter como aliada. Vá para sudoeste, para o lado oposto ao Caldeirão da Carnificina, e lá tu vai achar as ruínas do clã Dunwald. Eles levaram umas boas bordoadas, mas nem isso detém os Dunwald. É só uma questão de encontrá-los...', '', '', '', '', '', '', '', '', '', '', 0),
(27641, 'ptBR', 'Casos de família', 'Mate 20 membros do Martelo do Crepúsculo no território Dunwald.', 'Olá, $gguri:guria;! Sei que Keely te preocupou a respeito dos meus irmãos, mas eles sabem se cuidar. Eles vão achar o caminho de volta de uma forma ou de outra.$B$BTalvez tu possa me fazer um favor enquanto reúne minha família... O território Dunwald ainda está infestado pelo Martelo do Crepúsculo e seus servos. Seria muito bom se tu lembrasse a eles que não são bem-vindos.', '', 'Convidados do Crepúsculo recepcionados em Dunwald', '', '', '', '', '', '', '', 'Fale com Flynn Dunwald no Abrigo dos Dunwald, que fica no Planalto do Crepúsculo.', 0),
(27642, 'ptBR', 'Pente fino nos destroços', 'Procure os corpos de 12 Dunwalds Assassinados.', 'Os membros do Martelo do Crepúsculo foram muito cruéis quando saquearam nossa cidade. Acho que eu e meus irmãos fomos os únicos a deter eles. Preciso ter certeza.$B$BEnquanto tu circula pelas ruínas, preste atenção nos corpos dos meus parentes. Preciso saber se há sobreviventes... ou se alguns conseguiram fugir.', '', 'Dunwalds Assassinados encontrados', '', '', '', '', '', '', '', 'Fale com Flynn Dunwald no Abrigo dos Dunwald, que fica no Planalto do Crepúsculo.', 0),
(27643, 'ptBR', 'Donnelly Dunwald', 'Encontre Donnelly Dunwald.', 'Então tu tá tentando nos encontrar e eu tô tentando encontrar meus irmãos. Me parece que temos algo em comum.$B$BDonnelly é o mais velho de todos nós, mas não tem nada na cabeça. Geralmente ele fica nas ruínas ao norte, numa cabana. Tu acha que pode procurar ele pra mim? Vou ficar mais tranquila sabendo que ele está bem.', '', '', '', '', '', '', '', '', '', '', 0),
(27644, 'ptBR', 'Eoin Dunwald', 'Encontre Eoin Dunwald.', 'Eoin é um dos gêmeos. Ele tem uma quedinha por bebidas. Você pode encontrá-lo perto do velho poço – os estoques de cerveja estavam numa construção por lá.$B$BTe importa de fazer ele vir visitar a irmã preocupada? Não vai ser difícil convencer ele se tu conseguir a cerveja antes.', '', '', '', '', '', '', '', '', '', '', 0),
(27645, 'ptBR', 'Cayden Dunwald', 'Encontre Cayden Dunwald.', 'Cayden é o outro gêmeo. Ele também é sedento, mas não por cerveja. Tenho certeza de que ele tem se divertido desde que o Crepúsculo bateu à nossa porta. Talvez ele esteja aliviando a tensão...$B$BAcredito que o melhor lugar para procurar ele é na travessa do comércio, perto da velha ferraria. Ele costumava ficar por ali de qualquer jeito, mas desde que aquele lugar foi invadido pelo Crepúsculo, é provável que ele tenha mais motivos para chamar aquilo de lar.$B$BTraga ele de volta. Inteiro, de preferência.', '', '', '', '', '', '', '', '', '', '', 0),
(27646, 'ptBR', 'Procurando Bico', 'Ajude Donnelly a encontrar Bico na Cabana de Dunwald.', 'Perdi meu grifo... Bico! Bico, onde tu tá??!$B$BTu quer me ajudar a achar ele? Sei que ele tá na cabana. Tem que estar...$B$BBico?! Onde tu tá?$B$BEspero que ele esteja bem.', '', 'Vasculhe o celeiro na ala sul da Cabana de Dunwald', 'Vasculhe o celeiro na ala noroeste da Cabana de Dunwald', 'Vasculhe as construções na ala leste da Cabana de Dunwald', '', '', '', '', '', 'Fale novamente com Donnelly Dunwald na Cabana de Dunwald, que fica no Planalto do Crepúsculo.', 0),
(27647, 'ptBR', 'Bebendo espero', 'Procure um barril no porão que Eoin Dunwald mencionou.', 'Veja bem, camarada. Ou tu está aqui pra me ajudar a encontrar bebida, ou tu está atrapalhando.$B$BPor que tu não vai até o velho armazém e procura no porão? Suspeito que o contador ficava lá dando uns goles entre uma página e outra. Aposto que ele tem um barril no porão!$B$BSe tu achar algo, venha direto aqui! Sem brincadeira... Isso é urgente!', '', '', '', '', '', '', '', '', '', 'Fale com Eoin Dunwald nas Ruínas Dunwald, que ficam no Planalto do Crepúsculo.', 0),
(27648, 'ptBR', 'No fogo de novo', 'Acompanhe Cayden Dunwald através da mais do que óbvia emboscada.', 'Tá bem, tá bem... Tu quer um pouco de ação? Pode vir junto!$B$BMe diga quanto estiver $gpreparado:preparada;.', '', 'Acompanhe Cayden na Travessa do Comércio de Dunwald', '', '', '', '', '', '', '', 'Fale novamente com Cayden Dunwald nas Ruínas de Dunwald, que ficam no Planalto do Crepúsculo.', 0),
(27649, 'ptBR', 'Ouro líquido', 'Colete 6 Barris de Cerveja Martelo Feroz.', 'Olá, chapa! Vendo como tu é amigável, $gcorajoso:corajosa; e tudo mais, tu pode fazer um favor pra um anão?$B$BEstas são as Ruínas Dunwald... com certeza tem mais provisões nestas construções. Se tu achar mais cerveja, traga para mim, certo? Um bom anão nunca tem o bastante!$B$BEstou pensando em ir de volta até a Keely, assim pode ser que tu tenha que ir atrás de mim, mas vou tentar fazer valer a pena pra ti.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Eoin Dunwald nas Ruínas Dunwald, que fica no Planalto do Crepúsculo.', 0),
(27650, 'ptBR', 'Lar, doce lar', 'Fale com Keely Dunwald no Abrigo dos Dunwald.', 'Tu tem que encontrar a Keely. Ela vai estar ansiosa por notícias.', '', '', '', '', '', '', '', '', '', '', 0),
(27651, 'ptBR', 'Agindo como um Dunwald', 'Fale com Flynn Dunwald e ajude os irmãos Dunwald a matar Darunga.', 'Eles já saíram pra caçar o gorjala que liderou o ataque a Dunwald. Pedi para eles pelo menos te darem uma chance de alcançá-los, mas eles não sabem o que é esperar.$B$BEles partiram em direção à praça da cidade, no meio das ruínas. Vá antes que tu perca o melhor da festa.', '', '', '', '', '', '', 'Darunga', '', '', 'Fale com Flynn Dunwald ou Keely Dunwald nas Ruínas Dunwald, que ficam no Planalto do Crepúsculo.', 0),
(27652, 'ptBR', 'Assassinos sombrios', 'Colete 5 Berloques dos Assassinos Sombrios.', 'Até eu sou caçado, e acredito que seja por me esconder entre as ovelhas.$B$B<Mathias estuda você por algum tempo.>$B$BO Martelo do Crepúsculo enviou seus assassinos sombrios atrás de mim. Um belo bando... todos mortos agora. Eles são feitos com as almas dos matadores mais habilidosos.$B$BQuer me fazer um favor? Acabe com eles e me traga os berloques das almas deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mathias Shaw na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27653, 'ptBR', 'Assassinos sombrios', 'Colete 5 Berloques dos Assassinos Sombrios.', 'Até eu sou caçada, $c. Isso faz parte da graça de me esconder entre as ovelhas.$B$B<Garona estuda você por algum tempo.>$B$BO Martelo do Crepúsculo enviou seus assassinos sombrios atrás de mim. Interessante em se tratando de um grupo de caras mortos. Eles são feitos com as almas dos matadores mais habilidosos.$B$BVocê me faz um favor? Acabe com eles.$B$BEles carregam suas almas em pingentes presos em cordões. Traga-os para mim. As almas são opcionais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27654, 'ptBR', 'Abaixo o Martelo!', 'Mate 10 Veteranos da Cidadela, Elementalistas Corrompidos e/ou Vindicantes do Crepúsculo.', 'Nenhum saque nos campos seria completo sem o bom e velho "pegue os malvados e livre-se deles".$B$BEntre eles, os veteranos da cidadela, os elementalistas corrompidos e os vindicantes do Crepúsculo. Tenho certeza de que não faltarão alvos.$B$BDepende de você a forma como vai matá-los.', '', 'Sectários da Cidadela do Crepúsculo mortos', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mathias Shaw na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27655, 'ptBR', 'Abaixo o Martelo!', 'Mate 10 Veteranos da Cidadela, Elementalistas Corrompidos e/ou Vindicantes do Crepúsculo.', 'Não há nada pior do que um sectário do Martelo do Crepúsculo que se odeia. NADA! Aqueles idiotas desejam, na verdade, o fim do mundo.$B$BEles merecem ser extintos a meu ver.$B$BVocê tem uma variedade grande de alvos, entre eles veteranos da cidadela, elementalistas corrompidos e vindicantes do Crepúsculo.$B$BPouco me importa a forma como você vai matá-los.', '', 'Sectários da Cidadela do Crepúsculo mortos', '', '', '', '', '', '', '', 'Fale novamente com Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27656, 'ptBR', 'Crocolisco Dundee', 'Mate 8 Crocoliscos Dentesserra.', 'O Pantanal dos Cervos, a leste da cidade, está infestado por crocoliscos. Infestado, está ouvindo? Tenho vendido cada parte de crocolisco que você possa imaginar.$B$BCouro, dentes, caudas, línguas, olhos e tudo mais. A questão é que não estão vendendo mais. Há crocoliscos demais! Estamos com excesso de suprimentos e falta de demanda.$B$BAssim sendo, já que eles não têm utilidade pra mim, além de comerem um de meus hóspedes de tempos em tempos, preciso que você mate os sacanas. Quebre esse galho, tá? Estarei aqui negociando coisas com o teu povo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Barão Mercador Romprata no Pântano das Mágoas.', 0),
(27657, 'ptBR', 'Presença de Yevaa', 'Fale com a Arauto da Terra Yevaa nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 'Minha investigação sobre o artefato de Cho\'gall chegou num beco sem saída. O Martelo do Crepúsculo escravizou um grupo de ferreiros Martelo Feroz e os afogou no lago quando não precisava mais dos serviços deles.$B$B<Mathias dá uma cusparada.>$B$BPrecisamos de ajuda. Tem uma mulher na Harmonia Telúrica, a arauto da terra Yevaa, a sudoeste da mina de elemêntio.$B$BEla e seu aprendiz goblin precisam de ajuda com o desligamento dos portais elementais das redondezas. Acho que, em troca, ela pode nos ajudar a solucionar nosso problema.', '', '', '', '', '', '', '', '', '', '', 0),
(27658, 'ptBR', 'Presença de Yevaa', 'Fale com a Arauto da Terra Yevaa nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 'Minha investigação sobre o artefato de Cho\'gall chegou num beco sem saída. O Martelo do Crepúsculo escravizou um grupo de ferreiros Martelo Feroz e os afogou no lago quando não precisava mais dos serviços deles.$B$B<Garona dá uma cusparada.>$B$BOdeio dizer isso, mas precisamos de ajuda. Tem uma mulher na Harmonia Telúrica, uma draenaia chamada Yevaa. Ela e seu goblin estão a sudoeste da mina de elemêntio.$B$BEles precisam de ajuda com o desligamento dos portais elementais das redondezas. Em troca, ela pode nos ajudar a solucionar nosso problema.', '', '', '', '', '', '', '', '', '', '', 0),
(27659, 'ptBR', 'Sobrecarga nos portais', 'Mate Apexar, Aetheron e Edemantus depois que estiverem debilitados.', 'Eu era a guardiã dos portais da Harmonia Telúrica daqui. Mas enquanto estávamos fora ajudando a salvar Geodomo, os membros do Martelo do Crepúsculo vieram e corromperam a área.$B$BEles estão usando poderosos ascendentes para vigiarem nossos portais. Foi aí que cometeram um erro crítico.$B$BQuero que tu vás até os portais e uses os controles para sobrecarregá-los. Isso vai fazer com que toda a energia do portal seja dispersada e deixará os ascendentes debilitados. Mata-os!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Arauto da Terra Yevaa nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 0),
(27660, 'ptBR', 'O espírito do Lago', 'Fale com a Condessa Verrall no Loch Verrall, que fica no Planalto do Crepúsculo.', 'Não estou sabendo de nenhum artefato que Cho\'gall esteja fazendo, mas acho que conheço alguém que pode ajudar.$B$BA condessa Verrall é o venerável espírito do Loch Verrall, que fica ao norte. Ela não tem afeto algum pelo Martelo do Crepúsculo que poluiu suas águas.$B$BEncontra-te com ela para obter a sabedoria que tanto buscas.', '', '', '', '', '', '', '', '', '', '', 0),
(27661, 'ptBR', 'Acenda o estopim!', 'Mate Lorde Kanhaum.', 'Meu arqui-inimigo, Lorde Kanhaum, decidiu tolamente ser leal ao Martelo do Crepúsculo.$B$BNo passado, vivíamos numa trégua vacilante, mas essa mudança de postura dele não me dá outra escolha a não ser acabar com ele. Ou, devo dizer, se você quiser obter informações sobre o anão morto, deverá matar lorde Kanhaum para mim.$B$BProcure-o em Labaredas do Canhão, a sudeste daqui.', '', '', '', '', '', '', 'Lorde Kanhaum', '', '', 'Fale novamente com a Condessa Verrall no Loch Verrall, que fica no Planalto do Crepúsculo.', 0),
(27662, 'ptBR', 'Liberdade é elemental', 'Liberte 10 Elementais Escravizados matando-os na Cidadela do Crepúsculo.', 'Veja bem, se tem uma coisa de que eu entendo é de elementais. Já consigo até saber o que eles sentem. E vou lhe dizer: eles não gostam nem um pouco de serem escravizados!$B$BEntão, o que tô dizendo é que, se você libertar os elementais escravizados, tenho certeza de que eles ficarão não só agradecidos, como também vão se voltar contra os mestres deles.$B$BPra mim, parece ser um esquema vantajoso, $n.', '', 'Elementais escravizados libertados', '', '', '', '', '', '', '', 'Fale novamente com o Iniciado Almada nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 0),
(27663, 'ptBR', 'Tem gosto de moa', 'Extraia 9 Coxinhas Grandes das Moas do Pântano.', 'Você aí! É, você $Gmesmo:mesma;! Quer que eu fale bem de você para o barão mercador? Então me dá uma mão!$B$BOuvi falar que foi você quem conseguiu todas aquelas caudas de makrura. Elas são ótimas, mas não são suficientes para fazer uma comida pantaneira realmente nutitri.. nutritri... ADEQUADA! Preciso de mais carne pro meu bobó!$B$BHá muitas moas do pântano, perto da cidade, na Penumbra das Mágoas. Quero as maiores coxinhas que você conseguir encontrar!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pierre Descamapeixe no Pântano das Mágoas.', 0),
(27664, 'ptBR', 'Baralho Vulcânico de Negraluna', 'Devolva o Baralho Vulcânico à Feira de Negraluna quando ela voltar à cidade.', 'Agora que você juntou todas as cartas de Brasas em um baralho, uma nona carta surge misteriosamente com o mesmo verso das oito primeiras. Nela, está escrito "Devolva estas cartas à Feira de Negraluna para receber uma recompensa". Você ouviu dizer que a entrada da feira aparece perto de Mulgore e da Vila d\'Ouro todos os meses.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Professor Tadeu Jones.', 0),
(27665, 'ptBR', 'Baralho de Furacões de Negraluna', 'Devolva o Baralho de Furacões à Feira de Negraluna quando ela voltar à cidade.', 'Agora que você juntou todas as cartas de Ventos em um baralho, uma nona carta surge misteriosamente com o mesmo verso das oito primeiras. Nela, está escrito "Devolva estas cartas à Feira de Negraluna para receber uma recompensa". Você ouviu dizer que a entrada da feira aparece perto de Mulgore e da Vila d\'Ouro todos os meses.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Professor Tadeu Jones.', 0),
(27666, 'ptBR', 'Baralho de Maremotos de Negraluna', 'Devolva o Baralho de Maremotos à Feira de Negraluna quando ela voltar à cidade.', 'Agora que você juntou todas as cartas de Ondas em um baralho, uma nona carta surge misteriosamente com o mesmo verso das oito primeiras. Nela, está escrito "Devolva estas cartas à Feira de Negraluna para receber uma recompensa". Você ouviu dizer que a entrada da feira aparece perto de Mulgore e da Vila d\'Ouro todos os meses.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Professor Tadeu Jones.', 0),
(27667, 'ptBR', 'Baralho de Terremotos de Negraluna', 'Devolva o Baralho de Terremotos à Feira de Negraluna quando ela voltar à cidade.', 'Agora que você juntou todas as cartas de Pedras em um baralho, uma nona carta surge misteriosamente com o mesmo verso das oito primeiras. Nela, está escrito "Devolva estas cartas à Feira de Negraluna para receber uma recompensa". Você ouviu dizer que a entrada da feira aparece perto de Mulgore e da Vila d\'Ouro todos os meses.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Professor Tadeu Jones.', 0),
(27669, 'ptBR', 'Faça as honras', 'Use os Orbes das Estrelas perto do mecanismo na Câmara das Estrelas.', 'Parece que tudo o que resta fazer é colocar os orbes nos pedestais em cada canto do mecanismo.$b$bParece que esbarramos no que pode ser a descoberta mais importante da história moderna.$b$b<Harrison olha para você por um instante e, então, entrega os orbes.>$b$bVá em frente, $n.$b$bNunca teríamos feito esta descoberta sem você.', '', 'Obelisco das Estrelas reativado', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Obelisco das Estrelas.', 0),
(27670, 'ptBR', 'Ninguém segura a V.E.R.A.!', 'Mate 6 Gnomos Leprosos Enlouquecidos.', 'Meu nome é Nevin Girachave e sou comandante da V.E.R.A. – Valente Expedição de Resgate e Assistência.$B$BNão sei como você conseguiu sobreviver à radiação daqui debaixo, $n, pois a maioria se deu muito mal. Minha equipe está tentando reunir os sobreviventes, mas os gnomos leprosos criados pela radiação são muito numerosos e não conseguiremos mantê-los afastados por muito mais tempo. Eles perderam o juízo!$B$BSe você ainda tiver forças para empunhar uma arma ou lançar um feitiço, poderia nos ajudar a exterminar uma parte desses gnomos bexiguentos?', '', '', '', '', '', '', '', '', '', 'Fale com Nevin Girachave em Gnomeregan.', 0),
(27671, 'ptBR', 'Pense nos sobreviventes', 'Use o Sinalizador de Teleporte para teleportar 6 Sobreviventes para um lugar seguro.', 'Se não fizermos alguma coisa rápido, nem o Nevin, nem os sobreviventes vão conseguir sair dessa vivos. Vou dar para você o sinalizador de teleporte emergencial do meu esquadrão. Ainda nos resta força e munição o suficiente para garantir nossa saída daqui, mas os sobreviventes não estão em condições de dar no pé.$B$BUse o sinalizador nos sobreviventes para que sejam teleportados para a zona segura que minha equipe liberou. Depois disso, apresente-se a mim outra vez para a gente providenciar a sua saída daqui.', '', 'Sobreviventes resgatados', '', '', '', '', '', '', '', 'Apresente-se a Carvo Estourapino em Gnomeregan.', 0),
(27672, 'ptBR', 'A câmara de Khaz\'mul', 'Derrote Ferronaya.', 'Na Câmara do Mapa há uma porta trancada, que creio que leva até a lendária Câmara de Khaz\'mul. Vai saber que segredos estão escondidos lá dentro!$B$BO que sabemos é que o local é protegido por Ferronaya, uma Vigia Titânica gigante e muito poderosa! Para entrar na câmara e desvendar os segredos de Uldaman, você precisará derrotar Ferronaya!', '', '', '', '', '', '', '', 'É isso aí!', 'Fale novamente com o Prospector-chefe Durdin.', 'Fale novamente com o Prospector-chefe Durdin.', 0),
(27673, 'ptBR', 'O que vale é o interior', 'Obtenha o Núcleo de Força Obsidiano e o Núcleo de Força Titânico.', 'Os Criadores construíram dois Antigos Protetores de Pedra para ajudar a defender Uldaman de invasores e para supervisionar as operações diárias enquanto Ferronaya e Arkhaedas dormiam. Um deles ainda está funcionando perfeitamente no Salão do Templo, mas o outro, na Caverna Ecomok, foi corrompido por algo desconhecido.$B$BReceio que um dos Deuses Antigos é o responsável por isso, e você vai me ajudar a confirmar se esse é o caso! Destrua ambos os guardiães e traga-me seus núcleos de força. Eles nos dirão tudo o que precisamos saber.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kand Buscareia.', 0),
(27674, 'ptBR', 'Rumo à superfície', 'Fale com Toninho Despachante para ser $Gteleportado:teleportada; para a superfície e, então, apresente-se a Nevin Girachave.', 'Nevin acabou de avisar que ele e a equipe estão se preparando para subir. Ele vai esperar por você no edifício que a V.E.R.A. está usando como quartel-general.$B$BEstá vendo o Toninho Despachante ali? Fale com ele quando você estiver $Gpronto:pronta; para subir à superfície e ele tomará providências para levar você lá para cima. Foi um prazer $Gconhecê-lo:conhecê-la;, $n, e me sinto honrado em ter ajudado você, ainda que pouco, a escapar de Gnomeregan e começar a vida na superfície.', '', 'Falar com Toninho Despachante', '', '', '', '', '', '', '', 'Fale com Toninho Despachante para ser $Gteleportado:teleportada; para a superfície e, então, apresente-se a Nevin Girachave.', 0),
(27675, 'ptBR', 'Documentos forjados', 'Encontre um morador de Ventobravo que aceite receber os Documentos Forjados.', 'Encontre um morador de Ventobravo que aceite receber os documentos forjados.', '', '', '', '', '', '', '', '', '', '', 0),
(27676, 'ptBR', 'A porta dos desesperados', 'Mate Galnann Martelígneo.', 'Galgann Martelígneo e seu grupo de anões Ferro Negro estão no Sítio Três protegendo um porta misteriosa, e não temos a mínima ideia o que ela guarda! A Liga dos Exploradores é a única organização autorizada e lidar com os artefatos encontrados em Uldaman!$B$BVá até o sítio e acabe com Galnann para continuarmos nosso trabalho sem mais problemas. Estou desesperada para saber o que há detrás daquela porta!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Olga Filha das Runas.', 0),
(27677, 'ptBR', 'Arkhaedas, o Antigo Vigia de Pedra', 'Derrote Arkhaedas.', 'Nosso principal objetivo em Uldaman é conseguir os Discos de Norgannon. Os incontáveis segredos inscritos nesses discos podem mudar completamente a visão que temos do mundo. Por isso, o valor deles está além de qualquer riqueza material imaginável.$B$BO problema é que Arkhaedas, uma antiga e muito poderosa criação dos Criadores, protege os discos com um exército respeitável ao seu dispor. Preciso que você derrote Arkhaedas e garanta que a Liga dos Exploradores obtenha os discos!', '', '', '', '', '', '', 'Arkhaedas', 'Você conseguiu!', 'Fale novamente com o Prospector-chefe Durdin.', 'Fale novamente com o Prospector-chefe Durdin.', 0),
(27679, 'ptBR', 'A câmara de Khaz\'mul', 'Derrote Ferronaya.', 'Na Câmara do Mapa há uma porta trancada, que, creio, leva à lendária Câmara de Khaz\'mul. Ainda não sabemos quais artefatos estão escondidos lá dentro.$B$BO que sabemos é que o local é protegido por Ferronaya, uma Vigia Titânica gigante e muito poderosa. Você terá que derrotá-la, se quiser entrar lá.', '', '', '', '', '', '', '', 'Muito bem.', 'Avaliador-mor Tae\'thelan Vigiassangre', 'Avaliador-mor Tae\'thelan Vigiassangre.', 0),
(27680, 'ptBR', 'Arkhaedas, o Antigo Vigia de Pedra', 'Derrote Arkhaedas.', 'Nosso principal objetivo aqui em Uldaman é obter os Discos de Norgannon. Esses discos de platina podem nos dar um poder inacreditável. Incontáveis segredos dos Criadores estão inscritos neles, e seu valor está além de qualquer riqueza material imaginável.$B$BO problema é que Arkhaedas, uma invenção antiga e muito poderosa dos Criadores, protege os discos com um exército respeitável ao seu dispor. Preciso que você derrote Arkhaedas e garanta que o Relicário fique com os discos.', '', '', '', '', '', '', 'Arkhaedas', 'Excelente.', 'Avaliador-mor Tae\'thelan Vigiassangre', 'Fale novamente com o Prospector-chefe Durdin.', 0),
(27681, 'ptBR', 'A porta dos desesperados', 'Mate Galnann Martelígneo.', 'Galnann Martelígneo e seu grupo de anões Ferro Negro estão no Sítio Três protegendo um porta misteriosa, e não temos a mínima ideia do que há detrás dela! Já estou farta dos Ferro Negro interferindo no nosso trabalho por aqui! O Relicário é a única organização autorizada a lidar com os artefatos encontrados em Uldaman!$B$BVá até o sítio e acabe com Galnann para que assim possamos continuar nosso trabalho sem mais problemas. Preciso saber o que aquela porta esconde!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lídia Rubrossol.', 0),
(27682, 'ptBR', 'Precisamos de mais minérios', 'Obtenha o Núcleo de Força Obsidiano e o Núcleo de Força Titânico.', 'Os titãs construíram dois antigos Protetores de Pedra para ajudar a defender Uldaman de invasores e para supervisionar as operações diárias enquanto Ferronaya e Arkhaedas dormiam. Um deles ainda está funcionando perfeitamente no Salão do Templo, mas o outro, na Caverna Ecomok, foi corrompido por algo desconhecido.$B$BSuspeito que um dos Deuses Antigos é responsável por isso, e você vai me ajudar a confirmar se esse é o caso! Destrua ambos os guardiães e traga-me seus núcleos de força. Eles nos dirão tudo o que precisamos saber.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Aoren Rubrossol.', 0),
(27683, 'ptBR', 'Floresta adentro', 'Encontre uma worgenin no Rio Thondroril, que fica nas Terras Pestilentas Orientais.', 'Outro dia, eu vi uma comoção estranhíssima a caminho da cidade. Uma carruagem movida a cavalo, carregada com caixotes e baús, uma worgenin com as rédeas, um elfo sangrento ao lado dela e um paladino enânico correndo atrás, gritando obscenidades das mais criativas.$b$bEles pareciam estar seguindo rumo às Terras Pestilentas Orientais, mas duvido que já estejam muito além do Rio Thondroril. O que será que eles estão aprontando?', '', '', '', '', '', '', '', '', '', '', 0),
(27684, 'ptBR', 'Visitantes', 'Encontre uma worgenin no Rio Thondroril, que fica nas Terras Pestilentas Orientais.', 'Minhas fontes no Acampamento dos Restauradores me informaram que teremos alguns visitantes em breve. Um grupo de paladinos – liderados por uma mercadora worgenin, por incrível que pareça – chegará aqui em breve. Estou ansioso para conhecê-los. Especialmente um deles.$b$bVocê se importaria em dar uma checada neles? Não tenho como saber ao certo, mas eles devem estar atravessando o Rio Thondroril, bem a oeste.', '', '', '', '', '', '', '', '', '', '', 0),
(27685, 'ptBR', 'Boa ação deixada por fazer', 'Rendel Flamilíngua quer que você fale com Adarrah na Floresta Kelp\'thar.', 'Bom dia, $grapazinho:mocinha;.$b$bO nome é Rendel.$b$bParece que a velha Moana e eu chegamos na última hora, né?$b$bErunak não tava brincando quando disse que era vida ou morte!$b$bBah... na relancina de sair logo daqui, deixamos questões por resolver a leste.$b$bUma mocinha tava prestes a morrer. Não tínhamos outra escolha senão sair por um pequeno duto de ventilação quando fomos tentar resgatá-la.$b$bQue tal tu dar um pulo lá e socorrer ela enquanto ainda há tempo?', '', '', '', '', '', '', 'Adarrah', '', '', '', 0),
(27686, 'ptBR', 'Documentos forjados', 'Encontre um morador de Orgrimmar que aceite receber os documentos forjados.', 'Encontre um morador de Orgrimmar que aceite receber os documentos forjados.', '', '', '', '', '', '', '', '', '', '', 0),
(27687, 'ptBR', 'Uma lata de Gnash aberta e berrando', 'Leve a Cabeça de Gnash para o Samir no Covil do Contrabandista.', 'Mas que feito, matar um poderoso gigante do mar!$b$bOs novos habitantes do Covil do Contrabandista se sentirão consideravelmente mais seguros sabendo que esse monstro não mais perambula pelas vizinhanças.', '', '', '', '', '', '', '', '', '', '', 0),
(27688, 'ptBR', 'Dou-lhe um, dou-lhe dois, dou-lhe três!', 'Mate a Mme. Alys Finnsson, o Mestre Klem e Mia, a Rosa.', 'Há três candidatos à Ascendência que precisamos eliminar: a mme. Alys Finnsson, o mestre Klem e Mia, a Rosa.$B$BQuero que você os distraia para mim. Quando chegar o momento certo, vou me posicionar e matarei eles pelas costas.$B$BO que quer que você faça, $n, não os subestime. Eles estão onde estão por serem inescrupulosos e bons no que fazem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mathias Shaw na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27689, 'ptBR', 'Dou-lhe um, dou-lhe dois, dou-lhe três!', 'Mate Mme. Alys Finnsson, Mestre Klem e Mia, a Rosa.', 'Há três candidatos à Ascendência que precisam ser mortos: a Mme. Alys Finnsson, o Mestre Klem e Mia, a Rosa.$B$BQuero que você os distraia. Quando chegar o momento certo, vou me posicionar e matá-los pelas costas.$B$BO que quer que você faça, $n, não os subestime. Esses lunáticos estão onde estão por serem inescrupulosos e muito bons no que fazem.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27690, 'ptBR', 'Narkrall, o Domadracos', 'Apresente-se a Narkrall Garrasgo na Ravina de Sangue, que fica no Planalto do Crepúsculo.', '$n, a fortaleza na Ravina de Sangue é o cerne do império Presa do Dragão no Planalto. Ela fica rio acima. Narkrall Garrasgo está usando um poder considerável para formar uma esquadrilha de cavalga-dracos na fortaleza.$B$BO sucesso dos Presa do Dragão depende do sucesso da Ravina de Sangue. Vá até Narkrall e certifique-se de que isso aconteça.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Narkrall Garrasgo na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(27691, 'ptBR', 'Loucura do pântano', 'Mate 12 Murlocs do Pântano.', 'Temo que o resto dos Bondebico que estavam aqui estão mortos. Todos os jovens do acampamento a leste foram massacrados quando os murlocs apareceram.$B$BClaro, sempre houve murlocs por estas orlas... mas nunca tantos assim. À noite, eles vieram do mar em grupos enormes, urrando e espumando pela boca, invadindo a terra firme para atacar!$B$BNão podemos deixar eles soltos por aí, podemos? Será que você tranquilizaria uma velha goblina e espancaria alguns deles de volta pra água?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Baba Globlêbada no Pantanal dos Cervos, que fica no Pântano das Mágoas.', 0),
(27692, 'ptBR', 'Princesa Theradras', 'Mate a princesa Theradras.', 'Não se alarme, jovem $r. Sou Zaetar, filho de Cenarius, e venho até você para pedir sua ajuda.$B$BHá muito tempo, cometi o erro de me acasalar com a princesa Theradras, uma poderosa elemental da terra alinhada com os Deuses Antigos. Nossa prole, os Kahns dos centauros, viraram-se contra mim ao nascer e me assassinaram sem misericórdia. Agora, a mácula de Theradras corre fundo e ameaça mais do que apenas Maraudon.$B$BVenha matá-la e liberte meu espírito para que possamos restaurar Desolação às suas antigas feições, verdejante com vida e potencial, como Cenarius quereria.', '', '', '', '', '', '', 'Princesa Theradras', '', '', '', 0),
(27693, 'ptBR', 'O jogo do guardião', 'Complete o Jogo do Guardião teleportando os Peões do Guardião para posições voltadas para dentro.', 'Você vê a estátua se dividir em duas, quatro, e então oito estátuas idênticas em formação quadrada.$b$bVocê escuta uma voz, não pelos seus ouvidos, mas no fundo da sua mente:$b$b   "Um guardião de verdade não olha PARA FORA em busca de sinais de perigo.$b   Um guardião de verdade mantém os olhos voltados PARA DENTRO, sempre concentrado em proteger as suas presas."$b$bSerá que isso é algum tipo de charada?', '', 'Jogo do Guardião completo', '', '', '', '', '', '', '', '', 0),
(27694, 'ptBR', 'Poço de Lágrimas', 'Colete 5 Artefatos Atal\'ai do Poço de Lágrimas ao redor do templo de Atal\'Hakkar.', 'Os trolls que espreitam dentro deste templo causaram grande mal à minha espécie, $n. Fomos enviados aqui para guardarmos este lugar, mas utilizaram-nos para libertar os terríveis poderes antes ali contidos.$B$BPeço encarecidamente a você que preste-nos o auxílio que apenas um mortal pode. Seja minha mão dentro do templo; caso eu adentrasse por conta própria, correria o risco de também ser colocado contra meus irmãos.$B$BFaçamos um pacto. Se você deseja ajudar, primeiro colete artefatos Atal\'ai das águas ao redor do templo e entregue-os a mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Lorde Itharius no topo do Templo de Atal\'Hakkar no Pântano das Mágoas.', 0),
(27695, 'ptBR', 'O machado de elemêntio', 'Obtenha o Machado de Elemêntio.', 'Os covardes do Crepúsculo capturaram e mataram muitos dragões vermelhos, mas um ainda vive. Você se lembra de Lirastrasza? Ela está aprisionada aqui perto e vamos libertá-la.$B$BMas antes, precisamos de algo bastante afiado para arrebentar as correntes dela.$B$BHá um velho gorjala chamado Olhocego, o Guardião. Ele fica de vigília no Altar da Ascensão, ao sul.$B$BEle tem um machado forjado em puro elemêntio. Será essa a arma "definitiva" de Cho\'gall?', '', '', '', '', '', '', 'Olhocego, o Guardião', '', '', 'Fale novamente com o Mestre Mathias Shaw na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27696, 'ptBR', 'O machado de elemêntio', 'Obtenha o Machado de Elemêntio.', 'Os covardes do Crepúsculo capturaram e mataram muitos dragões vermelhos, mas um ainda vive. Você se lembra de Lirastrasza? Ela está acorrentada aqui perto e vamos libertá-la.$B$BMas antes, precisamos de algo bastante afiado para arrebentar as correntes.$B$BHá um velho gorjala chamado Olhocego, o Guardião. Ele fica de vigília no Altar da Ascensão, ao sul.$B$BEle tem um machado forjado em puro elemêntio. Será essa a arma "definitiva" de Cho\'gall?', '', '', '', '', '', '', 'Olhocego, o Guardião', '', '', 'Fale novamente com Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27697, 'ptBR', 'Corrupção em Maraudon', 'Mate o Lorde Torpelíngua.', '$n, preciso de sua ajuda imediatamente! Sou Zaetar, filho de Cenarius, e me quedei prisioneiro aqui após uma sequência infeliz de eventos! Antes que você possa me salvar, temos que limpar a corrupção que grassa por Maraudon.$B$BO lorde Torpelíngua é o governante dos sátiros das cavernas de cristal púrpura. Ele é um insidioso agente da Legião Ardente e a presença dele certamente levará ao caos e à morte. Ele não pode continuar vivo!', '', '', '', '', '', '', 'Lorde Torpelíngua', 'Seu trabalho aqui está longe de terminar.', 'Zaetar', '', 0),
(27698, 'ptBR', 'Servos de Theradras', 'Mate Tóxxico e Azorrague.', 'A princesa Theradras, minha antiga consorte, usou seu enorme poder para corromper a própria natureza de Maraudon. Neste exato instante, as criações dela estão à solta por aqui, e temo que a qualquer momento elas possam escapar para o mundo lá fora e semear morte e destruição.$B$B$n, vá e mate Tóxxico e Azorrague. Eles são dois dos mais poderosos lacaios de Theradras, e suas mortes causariam bastante pesar e sofrimento àquela princesa empedernida. E então, talvez, você possa ajudar a libertar meu espírito do domínio dela.', '', '', '', '', '', '', 'Azorrague', 'Agradeço o seu esforço.', 'Zaetar', '', 0),
(27699, 'ptBR', 'Tubarãozinho difícil', 'Colete 5 dos dentes do Mordisco no Arrecife Amaldiçoado.', 'Esse é um tubarão durão!$b$bVocê decide que é de comum interesse tentar distrair o Bino e torcer que ele nunca mais volte a atenção para o Mordisco e este Arrecife Amaldiçoado.$b$bTalvez os dentes da fera sirvam para este propósito...', '', '', '', '', '', '', '', '', '', 'Leve os dentes do Mordisco para o Bino, no Sítio de Escavação do Bino, que fica na Floresta Kelp\'thar.', 0),
(27700, 'ptBR', 'Liberdade para a dragonesa', 'Use o Machado de Elemêntio para romper as correntes que aprisionam Lirastrasza.', 'Lirastrasza é a última e maior de todos os dragões vermelhos que os membros do Martelo do Crepúsculo capturaram. Eles estão prestes a matá-la.$B$BQuero que você pegue o Machado de Elemêntio e livre-a das algemas.', '', 'Lirastrasza libertada', '', '', '', '', 'Lirastrasza', '', '', 'Fale novamente com o Mestre Mathias Shaw na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27701, 'ptBR', 'Liberdade para a dragonesa', 'Use o Machado de Elemêntio para romper as correntes que aprisionam Lirastrasza.', 'Lirastrasza é a última e maior de todos os dragões vermelhos que os membros do Martelo do Crepúsculo capturaram. Eles estão prestes a matá-la.$B$BVocê tem que pegar o Machado de Elemêntio e livrá-la das algemas antes que eles o façam.', '', 'Lirastrasza libertada', '', '', '', '', 'Lirastrasza', '', '', 'Fale novamente com Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27702, 'ptBR', 'Golpe de misericórdia', 'Dê um golpe de misericórdia em 5 Celesterrores do Crepúsculo.', 'Olhe só para aquilo. Lirastrasza está acabando com eles!$B$BAlguns dracos derrubados por ela precisam ser eliminados, $n. Não seria bom se os curandeiros do Crepúsculo os pusessem de volta no céu.$B$BEstá na hora do golpe de misericórdia.', '', 'Golpe de misericórdia desferido', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mathias Shaw na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27703, 'ptBR', 'Golpe de Misericórdia', 'Aplique um Golpe de Misericórdia em 5 Celesterrores do Crepúsculo.', 'Olhe para aquilo. Lirastrasza está destruindo eles!$B$BTem dracos que ela está derrubando que precisam ser eliminados, $n. Não queremos que os curandeiros imundos do Crepúsculo os mandem de volta ao céu.$B$BEstá na hora de um golpe de misericórdia.', '', 'Golpe de Misericórdia aplicado', '', '', '', '', '', '', '', 'Fale novamente com Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27704, 'ptBR', 'Lendas do templo submerso', 'Percorra as antecâmaras do templo até chegar ao Salão das Máscaras.', 'Preciso que você entre no templo primeiro, $n. Posso juntar-me a você uma vez que o caminho estiver seguro, mas não me atrevo a entrar cegamente. Voltado contra minha espécie, eu seria um inimigo terrível.$B$BVocê pode começar descendo as escadas atrás de mim. Feito isso, nade pelas profundezas alagadas do Salão Partido. Quando estiver lá, siga o corredor à direita para encontrar o Salão das Máscaras.$B$BCuidado com os guardas do templo. Uma vez que você tenha encontrado o Salão das Máscaras, contactarei você por meio da Pedra do Juramento.', 'Chegada ao Salão das Máscaras', '', '', '', '', 'Chegada ao Salão das Máscaras', '', 'Você o encontrou!', 'Lorde Itharius', '', 0),
(27705, 'ptBR', 'Primeiro passo: a sacerdotisa', 'Mate a Sacerdotisa Udum\'bra na Câmara de Sangue.', 'Meus irmãos estão sendo aniquilados aqui. É como pensei.$B$BDevo recorrer a seu auxílio novamente antes que eu possa adentrar, $n. Na passagem no exterior desta sala, o corredor segue tanto para a esquerda quanto para a direita. Seguindo-o à direita, chega-se à Câmara de Sangue. Aqui, os Atal\'ai realizam seus rituais macabros.$B$BEles aguardaram e prepararam-se para minha raça ao longo de anos, mas não previram você. Entre na Câmara de Sangue e mate a sacerdotisa Udum\'bra. Ela é uma das três presenças malévolas que aqui estão e precisam ser subjugadas antes que eu possa entrar.', '', '', '', '', '', '', 'Sacerdotisa Udum\'bra', 'A Pedra do Juramento nos liga.', 'Lorde Itharius', '', 0),
(27706, 'ptBR', 'O cetro de Orsis', 'Pegue o Cetro de Orsis do Receptáculo Sagrado.', 'O baú se destranca com um estalo assim que você coloca as duas pedras na placa.$B$BPegue o cetro e traga-o de volta ao General Ammantep.', '', '', '', '', '', '', '', '', '', 'Entregue o Cetro de Orsis ao General Ammantep do lado de fora de Orsis.', 0),
(27707, 'ptBR', 'Campo de concentração', 'Vá ao Campo de Prisioneiros Neferset e descubra o paradeiro de Tahet.', 'Hieróglifos descrevendo um Tol\'vir acorrentado assinalam o canto sudeste do mapa.$B$BTalvez Tahet tenha sido levado para lá e aprisionado.', '', 'O paradeiro de Tahet', '', '', '', '', '', '', '', '', 0),
(27708, 'ptBR', 'A vez do guardião', 'Erunak Falapedra quer que você mate o Guardião Azjakir na Amarra.', '<A imagem de Erunak invade a sua mente.>$b$bVocê agiu bem, $n. Contudo, ainda resta mais a fazer.$b$bAntes de deixarmos este lugar, vamos nos certificar de que o deixaremos em desordem.$b$bEncontre o líder dessas nagas e faça-o pagar pelos erros dele.', '', 'Guardião Azjakir morto', '', '', '', '', 'Erunak Falapedra', '', '', 'Fale com Erunak Falapedra na Gruta Densanévoa, que fica na Floresta Kelp\'thar.', 0),
(27709, 'ptBR', 'O jogo da sentinela', 'Complete o Jogo da Sentinela conectando as duas estátuas vermelhas.', 'Você coloca a estátua no devido lugar, e várias outras aparecem na sala. Também surge mais uma estátua cor de rubi, em um pequeno cercado no lado oposto do recinto. Você ouve uma voz:$b$b   "A Sentinela observa.$b   A Sentinela protege.$b   A visão da Sentinela nunca falha."$b$bA estátua vermelha no outro lado da sala parece importante. Talvez você devesse tentar conectar as duas estátuas cor de rubi.', '', 'Jogo da sentinela completo', '', '', '', '', '', '', '', '', 0),
(27711, 'ptBR', 'De volta às Profundezas de Elemêntio', 'Fale com o Iniciado Almada nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 'O pupilo da Arauto da Terra, iniciado Almada, precisa de você.$B$BAcho que eles estão esperando que você os ajude com o que quer que haja naquela mina.', '', '', '', '', '', '', '', '', '', '', 0),
(27712, 'ptBR', 'De volta às Profundezas de Elemêntio', 'Fale com o Iniciado Almada nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 'A Arauto da Terra tem um pupilo goblin? Almada é o nome dele? Ele precisa de você.$B$BAcho que eles estão esperando que você faça o trabalho sujo deles com o que quer que esteja acontecendo naquela mina.', '', '', '', '', '', '', '', '', '', '', 0),
(27713, 'ptBR', 'O dia em que o Asa da Morte veio', 'Ouça o conto do Theldurin.', 'O Asa da Morte fez um grande estrago quando passou por essas bandas. Se não fosse por mim, ele provavelmente ainda estaria aqui, assolando todo o bom povo dos Ermos.$b$bOra, você não acredita em mim? Tudo bem, deixe eu contar a história inteira para você.', '', '', 'Dê um soco na cara do Asa da Morte', '', '', '', '', '', '', 'Fale novamente com Theldurin, o Perdido, no Martelo de Aggramar, que fica nos Ermos.', 0),
(27714, 'ptBR', 'O dia em que o Asa da Morte veio: a verdadeira história', 'Ouça a versão de Lucien Tacachave.', 'A história do Theldurin não só está errada, como também é muito chata, sem criatividade e lenta.$b$bEu vou contar a você como as coisas aconteceram de verdade naquele dia.', '', 'Cresça o bastante para alcançar as nuvens', 'Nuvens vasculhadas', 'Encontre o Asa da Morte', '', '', '', '', '', 'Fale com Lucien Tacachave na Cicatriz do Quebramundo, que fica nos Ermos.', 0),
(27715, 'ptBR', 'O dia em que o Asa da Morte veio: o que realmente aconteceu', 'Ouça a versão de Martek, o Exilado.', 'Esses dois não sabem contar uma história. A do Theldurin foi muito curta, e a do Lucien foi meio comprida demais, se é que você me entende.$b$bAlém disso, nenhuma das histórias teve boazudas.$b$bSenta aí de novo, $n. Eu vou te contar o que aconteceu naquele dia de verdade.', '', 'Escolha um admirador para salvar', 'Vá ao fim do cânion', 'Encontre o Asa da Morte', 'Vença o Asa da Morte em uma luta de facas', '', '', '', '', 'Fale com Martek, o Exilado, na Cicatriz do Quebramundo, que fica nos Ermos.', 0),
(27716, 'ptBR', 'Partes do passado', 'Traga os Antigos Entalhes Élficos para Levia Andassonho. Você pode encontrá-la junto com os Sobreviventes de Nespirah da Aliança.', '<Uma antiga laje de pedra um pouco rachada, com inúmeras inscrições por todos os lados. Você não consegue decifrar o idioma, mas a enorme quantidade de textos e a natureza algo ornada da pedra dão a entender que ela é muito valiosa.>$B$B<Levia Andassonho, junto dos sobreviventes de Nespirah, estava procurando algo muito parecido com isso.>', '', '', '', '', '', '', '', '', '', '', 0),
(27717, 'ptBR', 'Partes do passado', 'Traga os Antigos Entalhes Élficos para Elendri Testadouro. Você pode encontrá-la junto dos Sobreviventes de Nespirah da Horda.', '<Uma antiga laje de pedra um pouco rachada, com inúmeras inscrições por todos os lados. Você não consegue decifrar o idioma, mas a enorme quantidade de textos e a natureza algo ornada da pedra dão a entender que ela é muito valiosa.>$B$B<Elendri Testadouro, junto dos sobreviventes de Nespirah, estava procurando algo muito parecido com isso.>', '', '', '', '', '', '', '', '', '', '', 0),
(27718, 'ptBR', 'Ordens do Chefe Guerreiro: Vashj\'ir!', 'Apresente-se ao Comandante Thorak. Você pode encontrá-lo na Baía Carpunhal, em Durotar.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, convocados para se apresentarem ao Comandante Thorak, na Baía Carpunhal, em Durotar.$B$BAgora, mais do que nunca, a Horda precisa de ajuda na batalha contra o mais odiado dos inimigos: a Aliança!$B$BPara chegar à Baía Carpunhal, viaje para o sul, atravessando os portões principais de Orgrimmar até chegar a Durotar. A seguir, siga na direção leste até a costa. Thorak estará aguardando em seu posto, perto das docas.$B$BAvante, irmãos e irmãs! O destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(27719, 'ptBR', 'Água da Vida', 'Use a Água da Vida para obter informações com o Cadáver do Mestre Forjador Finlay.', 'Leve minha Água da Vida e use-a no corpo do anão afogado.$B$BEle trabalhava com metais enquanto vivia e, embora o corpo dele agora sirva de alimento para o meu lago, a Água da Vida vai permitir que ele lhe diga o que você quer saber.$B$BEntão, vá conseguir sua informação e saia dos meus domínios.', '', 'Informação sobre o artefato obtida', '', '', '', '', '', '', '', 'Fale com o Mestre Mathias Shaw na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27720, 'ptBR', 'Um rolé com Almada', 'Viaje no carrinho da mina com o Iniciado Almada até o fim da linha.', 'Beleza, $n, a gente tem que chegar no Portal da Terra no fundo da caverna.$B$BEu consegui um rolé pra gente. Pra que andar se a gente pode dar um rolé de responsa? Tomara que ‘‘cê não se grile com carrinhos de mina.$B$BMe avisa quando você estiver $gpreparado:preparada;.', '', 'Falar com Almada para subir no carrinho.', 'Fim da linha', '', '', '', '', '', '', 'Fale com o Iniciado Almada nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 0),
(27721, 'ptBR', 'Ordens do Chefe Guerreiro: Monte Hyjal!', 'Fale com o Emissário Cenariano Casco Negro para conseguir um meio de transporte para a Clareira da Lua.', 'Todos os membros da Horda em boas condições físicas estão por meio deste convocados a se apresentar à Emissária Cantéolo, no Refúgio Noturno, que fica na Clareira da Lua.$B$BNossos irmãos do Círculo Cenariano relataram que os lacaios do Asa da Morte lançaram uma ofensiva destrutiva à Árvore do Mundo e estão ameaçando incendiá-la por completo!$B$BPara entrar na Clareira da Lua, fale com o emissário cenariano Casco Negro, no distrito tauren, no Vale da Sabedoria, em Orgrimmar.$B$BAvante, irmãos e irmãs! O destino chama!', 'Transporte para a Clareira da Lua garantido', '', '', '', '', 'Transporte para a Clareira da Lua garantido', '', '', '', 'Fale com a Emissária Cantéolo no Refúgio Noturno, que fica na Clareira da Lua.', 0),
(27722, 'ptBR', 'Ordens do Chefe Guerreiro: Geodomo!', 'Fale com o Clarividente Krogar, no Santuário Ocidental da Terra, em Orgrimmar.', 'Todos os membros da Horda em boas condições estão, por meio deste, convocados a se apresentar ao clarividente Krogar, no Santuário Ocidental da Terra, em Orgrimmar.$B$BA Harmonia Telúrica, liderada por Thrall, nosso antigo chefe guerreiro, precisa de nossa ajuda! O plano elemental de Geodomo está ameaçando dominar o nosso mundo!$B$BO Santuário Ocidental da Terra fica ao norte do Vale da Sabedoria.$B$BAvante, irmãos e irmãs! O destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(27724, 'ptBR', 'O chamado ao heroísmo: Vashj\'ir!', 'Fale com o Recrutador Britter. Você pode encontrá-lo no Porto de Ventobravo.', 'Por ordens de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem apresentar-se ao Recrutador Britter, no Porto de Ventobravo.$B$BOs recentes ataques da Horda às nossas embarcações comerciais têm de ser repelidos imediatamente e com força!$B$BO Porto de Ventobravo encontra-se na região noroeste da cidade.$B$BContinue lutando, soldado, pela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(27725, 'ptBR', 'Pavilhão Quel\'Danil', 'Fale com a Anacoreta Traska no Pavilhão Quel\'Danil.', 'Eu posso dar a impressão de estar longe de casa, $c, mas muitos do meu povo foram conduzidos até aqui pelo embaixador Rualeth. Nós nos assentamos com os elfos superiores do Pavilhão Quel\'Danil, a noroeste, para praticar o caminho da Luz e aproveitar a beleza serena desta terra.$B$BTal paz pode ter vida curta. A Horda foi vista avançando a oeste daqui. Tu podes ir a Quel\'Danil e avisar à Anacoreta Traska? A cabana dela fica a norte do pavilhão principal.', '', '', '', '', '', '', '', '', '', '', 0),
(27726, 'ptBR', 'O chamado ao heroísmo: Monte Hyjal!', 'Fale com a Emissária Cenariana Lunajade para conseguir um meio de transporte para a Clareira da Lua.', 'Por ordens de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar à emissária Cantéolo no Refúgio Noturno, que fica na Clareira da Lua.$B$BNossos irmãos do Círculo Cenariano relataram que os lacaios do Asa da Morte lançaram uma ofensiva destrutiva à Árvore do Mundo e estão ameaçando incendiá-la!$B$BFale com a emissária cenariana Lunajade na Bastilha Ventobravo para entrar na Clareira da Lua.$B$BContinue lutando, $girmão:irmã;, pela honra e glória da Aliança!', 'Transporte para a Clareira da Lua garantido', '', '', '', '', 'Transporte para a Clareira da Lua garantido', '', '', '', 'Fale com a Emissária Cantéolo no Refúgio Noturno, que fica na Clareira da Lua.', 0),
(27727, 'ptBR', 'O chamado ao heroísmo: Geodomo!', 'Fale com Naraat, a Voz da Terra, no Santuário Oriental da Terra, em Ventobravo.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar a Naraat, a Voz da Terra, no Santuário Oriental da Terra, em Ventobravo.$B$BA Harmonia Telúrica precisa da sua ajuda! O plano elemental do Geodomo está ameaçando tomar de assalto nosso mundo e destruir todas as formas de vida de Azeroth!$B$BO Santuário Oriental da Terra fica a noroeste da Bastilha Ventobravo.$B$BContinue lutando, $girmão:irmã;! Pela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(27729, 'ptBR', 'Ninguém gosta de enguias', 'Mate 8 Enguias de qualquer tipo na Floresta Kelp\'thar.', 'As enguias estão entre as criaturas mais arrepiantes de Azeroth.$b$bClaro, tem gente que finge não se importar com elas... E outros que chegam a defendê-las.$b$bSão uns mentirosos.$b$bA verdade seja dita, ninguém gosta de enguias. Nem enguias gostam de enguias.$b$bAzeroth seria um lugar melhor se ninguém jamais tivesse que ver uma enguia serpenteando das profundezas lamacentas, pronta para morder.$b$bNa cara.', '', 'Enguias nojentas mortas com razão', '', '', '', '', '', '', '', '', 0),
(27733, 'ptBR', 'O velho troca-troca', 'Mate Rodolfo Moloque.', 'Eu, por mim, ordenaria a explodir esses rebeldes agora mesmo, mas não posso. O Cárcere se encontra sob jurisdição do carcereiro Thelágua e, pelo menos por enquanto, ele deseja apenas mantê-los presos.$B$BEm vez de desobedecer as ordens do chefe, vamos arranjar uma solução alternativa! Nós conseguimos nos aproximar de Monteiro Moloque, que calha de ser o irmão gêmeo do cruel líder rebelde Rodolfo Maloque. Mate Rodolfo e nós poremos Monteiro no lugar dele e, assim, a rebelião cessará pacificamente!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Carabineiros Cauã.', 0),
(27737, 'ptBR', 'Salvos pelo fogo!', 'Obtenha o Núcleo de Fogo do Lorde Superakess.', 'Tenho bastante conhecimentos sobre primeiros socorros e outras formas de cura e, com a ajuda de minha Fonte de Luz, pude tratar de muitos dos nossos até que recuperassem a saúde completamente. O problema é que está tão frio e úmido aqui, que estou perdendo muitos pacientes, mesmo tendo curado suas feridas!$B$BOs terremotos enfureceram os elementos que moram na prisão... quando eles irromperam da terra, chacinaram metade dos prisioneiros. Se você matar o líder deles, lorde Superakess, e me trouxer o núcleo dele, eu posso usá-lo para aquecer nossos homens!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Enfermeira Lillian.', 0),
(27738, 'ptBR', 'O Fosso das Escamas', 'Resgate Tahet no Fosso das Escamas em Uldum.', 'Um ponto na parte inferior do mapa foi assinalado com hieróglifos de crocodilos lutando uns com os outros.$B$BDeve ter sido para onde Caimas levou Tahet.$B$BVá ao Fosso das Escamas e encontre uma maneira de resgatar o filho do Vizir.', '', 'Tahet libertado', '', '', '', '', '', '', '', '', 0),
(27739, 'ptBR', 'O rei gnoll', 'Derrote o Hogger.', '$n, infelizmente terei que lhe pedir o impossível.$B$BEu ganhei esse tapa-olho por causa dele. Milhares pereceram por causa da ira dele. Foi por puro milagre que conseguimos aprisioná-lo aqui.$B$BE isso foi um grande erro. Aguentamos o quanto pudemos, mas então eles chegaram. Das sombras e das trevas, centenas de gnolls servos de Hogger despedaçaram meus melhores homens.$B$BVocê precisa derrotar o Rei gnoll, ou ele vai organizar outro ataque e massacrar todos nós com sua fúria sedenta de sangue.', '', '', '', '', '', '', 'Hogger', '', '', 'Fale novamente com o Carcereiro-chefe Thelágua', 0),
(27740, 'ptBR', 'Baba Globêbada', 'Fale com Margaridoida Pinel para fazer um passeio de canhão até a Baba Globêbada.', 'Ei, enquanto você estava fora, o barão passou por aqui! Ele me chutou até cair dinheiro!$B$BSe bem que ele sempre faz isso. Mas, desta vez, ele pediu que eu te contasse uma coisa! Ele quer que você vá pro sul e ajude nossa herborista, Baba Globêbada.$B$BEla está do outro lado da água! Mas basta que fale com minha filha Margaridoida lá fora e ela levará você até lá à moda do Zé Pinel!', '', '', '', '', '', '', '', '', '', '', 0),
(27742, 'ptBR', 'Divisão justa', 'Colete 6 Estilhaços de Elemêntio.', 'Saca só, a gente tem obrigação moral de proteger este elemêntio todo das aranhas bizarras. Aquelas coisas repugnantes comem toda a parada!$B$BUm desperdício e tanto!$B$BEntão, o que me diz? Ó, vou ficar com uma parte, tá? Tipo 90% da parada...', '', '', '', '', '', '', '', '', '', 'Fale com o Iniciado Almada nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 0),
(27743, 'ptBR', 'Passatempo da hora', 'Mate 12 sectários do Martelo do Crepúsculo, sejam eles Feitores das Profundezas ou Mineradores do Crepúsculo, nas Profundezas de Elemêntio.', '‘‘Cê sabe que, enquanto a gente estiver na área, vamos ter que dar um jeito nos invasores do Martelo do Crepúsculo, né? Este lugar era nosso, pombas!$B$BEu podia dar uma força, mas com as armas e os totens ferrados, me sinto um inútil.', '', 'Sectários das Profundezas de Elemêntio assassinados', '', '', '', '', '', '', '', 'Fale com o Iniciado Almada nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 0),
(27744, 'ptBR', 'Arruinando as runas', 'Destrua a Runa da Terra, a Runa da Água, a Runa do Ar e a Runa do Fogo do Crepúsculo.', 'Ao examinar a Runa da Terra do Crepúsculo, você quase sente o poder dela se estendendo pelas Profundezas de Elemêntio.$B$BEla está provavelmente conectada a outras runas. O iniciado Almada acha que você deveria destruir todas elas.', '', 'Runa da Terra destruída', 'Runa da Água destruída', 'Runa do Ar destruída', 'Runa do Fogo destruída', '', '', '', '', 'Fale com o Iniciado Almada nas Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 0),
(27745, 'ptBR', 'Encontro quente', 'Obtenha o Controle do Portal de Fogo e use-o no Portal de Fogo.', 'Aquele é Mordamagma, meu elemental do fogo descontrolado, $n. Ou ‘‘cê mata ele ou ele me mata!$B$BFoi tudo um grande engano. Como eu podia saber que ele ia ficar danado da vida por eu ter pego "emprestado" o coração dele em Geodomo? Ele não morre... não de vez!$B$BEle tem o controle do portal com ele, sem dúvida. ‘‘Cê tem que pegar esse controle e usar ele no Portal de Fogo pra levar a gente de volta pra entrada.', '', 'Use o Controle do Portal de Fogo', '', '', '', '', 'Mordamagma', '', '', 'Entregue o controle para o Iniciado Almada na entrada das Profundezas de Elemêntio, que ficam no Planalto do Crepúsculo.', 0),
(27746, 'ptBR', 'Império da sujeira', 'Fale com a Alta Executora Darthalia no Bloqueio da Ponta Sul no Contraforte de Eira dos Montes.', 'Esta batalha arrasou nossa população. Muitas foram as nossas perdas para assegurar nosso lugar como legítimos regentes de Lordaeron. E, embora tenhamos vencido esta etapa, a batalha continua a se alastrar por outras partes dos Reinos do Leste.$B$BDevo retornar à Cidade Baixa para me recompor. Quero que você vá ao Contraforte de Eira dos Montes em meu lugar, $n. Como $Gmeu soldado:minha guerreira; de confiança, você comandará nossas forças para dominar nossos inimigos em Eira dos Montes.$B$BFale com a Alta Executora Darthalia no Bloqueio da Ponta Sul, a leste.', '', '', '', '', '', '', '', '', '', '', 0),
(27747, 'ptBR', 'Guerra absoluta', 'Destrua 10 Barris de Cerveja de Trondamar nas Ruínas Trondamar.', 'Muitos dos Martelo Feroz já fugiram de suas casas. Está na hora de varrê-los do mapa!$B$BNa cordilheira ao norte, você encontrará casas abandonadas nas Ruínas Trondamar. Barris de uma poderosa cerveja de Trondamar foram deixados para trás.$B$BEssa cerveja tem um altíssimo teor, não sei como isso é possível!$B$BArrebente os barris e taque fogo neles. Incendeie todos! Não deixe nada para os anões!', '', 'Barris dos Martelo Feroz destruídos', '', '', '', '', '', '', '', 'Fale novamente com Harkkan na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(27748, 'ptBR', 'Fortuna e glória', 'Mate o Colosso Obsidiano.', 'Precisamos continuar, $n. É apenas uma questão de tempo antes que aqueles soldados se recuperem.$b$bO baú deve estar logo depois destas ruínas.$b$bFique atent$go:a;. Algo me diz que isto ainda não terminou...', '', 'Colosso Obsidiano derrotado', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Encosta do Criador.', 0),
(27750, 'ptBR', 'Migalhas e sobras', 'Junte 15 Estoques de Comida dos Martelo Feroz das Ruínas Trondamar.', '<O estômago de Griff ronca.>$B$BQuando nós, os Presa do Dragão, estamos em guerra, todos param de caçar.$B$BA comida mais gostosa é aquela tirada da boca do inimigo. Na colina ao norte do rio há um vilarejo com casas abandonadas pelos Martelo Feroz. Aposto que estão lotadas de comida.$B$BTraga alguma coisa para encher minha boca.', '', '', '', '', '', '', '', '', '', 'Leve a comida para Griff na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(27751, 'ptBR', 'Malhando os Martelo Feroz', 'Mate Notáveis de Guerra Martelo Feroz para coletar 8 Insígnias Martelo Feroz. Personagens com nomes próprios que andam pelas Ruínas Trondamar também carregam insígnias.', 'Desde que meu povo tomou posse pela primeira vez do Planalto, os anões Martelo Feroz têm sido nossos tenazes rivais. Lutamos contra eles em Grim Batol, no Pantanal e ainda hoje na guerra que se espalha pelo norte, do outro lado do rio, entre as Ruínas Trondamar.$B$BMe dê provas de seu valor. Procure e acabe com os Notáveis de Guerra Martelo Feroz. Os melhores dentre eles carregam insígnias – meus guerreiros coletam elas aos montes.$B$BVocê consegue?', '', '', '', '', '', '', '', '', '', 'Leve as Insígnias Martelo Feroz para Narkrall Garrasgo na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(27752, 'ptBR', 'Lute como um Martelo Feroz', 'Recolha 10 Barris de Cerveja de Trondamar das Ruínas Trondamar. Cuidado – essa pega de jeito!', 'A gente não tá se gabando quando diz que faz a melhor cerveja dos Reinos do Leste. É provado e comprovado, eu te garanto!$B$BAo fugir do sul para o centro da cidade, uns companheiros tiveram que deixar a cerveja deles para trás.$B$B<Blundy faz uma pausa dramática, enfatizando a gravidade da situação.>$B$BTRAGA A CERVEJA DE VOLTA! Essa cerva transforma o mais fraquinho dos guerreiros num pária destruidor com a boca espumando. Traga os barris! É nossa única esperança.', '', '', '', '', '', '', '', '', '', 'Leve a cerveja de volta para o Aprendiz de Xamã Blundy em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(27753, 'ptBR', 'Nunca deixe um jantar para trás', 'Junte 15 Estoques de Comida dos Martelo Feroz das Ruínas Trondamar.', 'Os suprimentos estão escassos, $n. Temos refugiados chegando em Trondamar de todos os cantos da cordilheira – um monte de bocas para alimentar.$B$BMuitos estoques de comida foram abandonados quando as famílias procuravam por segurança. Precisamos dessa comida!$B$BSiga para o sul, leste e sudoeste das Ruínas Trondamar em busca de comida.$B$BTenha cuidado, $c! A luta nos arredores das ruínas ainda é intensa.', '', '', '', '', '', '', '', '', '', 'Leve a comida para Fanny Trondamar em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(27754, 'ptBR', 'A queda dos Presa do Dragão', 'Mate Espoliadores Presa do Dragão e colete 8 Insígnias Presa do Dragão. Personagens com nomes próprios que andam pelas Ruínas Trondamar também carregam insígnias.', 'Os Presa do Dragão!$B$B<Colin dá uma cusparada.>$B$BMonstros, todos eles! Lutamos contra eles por todo este Planalto desde a última guerra. E agora eles estão unindo forças com a Horda?$B$BSe tu quiser convencer os Martelo Feroz a se unir à bandeira da Aliança, é melhor provar que tu está contra os Presa do Dragão. Siga para a batalha que assola as Ruínas Trondamar ao sul e sudoeste. Mate espoliadores Presa do Dragão e recolha as insígnias que seus maiores guerreiros usam. Aí vamos conversar.', '', '', '', '', '', '', '', '', '', 'Entregue as insígnias para Colin Trondamar em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(27755, 'ptBR', 'A maldição das tumbas', 'Mate 6 Escavadores Enlouquecidos e o Mecangenheiro Mistureba.', 'Os Neferset não são a única ameaça a nossas tumbas sagradas.$B$BUma expedição gnômica se enfurnou em nossas terras há algumas semanas.$B$BEles não deram ouvidos aos nossos avisos e cavaram fundo demais num túmulo amaldiçoado.$B$BTodos eles estão sofrendo uma terrível maldição que lhes tirou a sanidade e controlou suas mentes.$B$BAgora eles buscam acesso às mais profundas criptas de Uldum e representam grande ameaça. $B$BVá ao Terraço da Pedra Solar e livre suas almas da penúria.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Profeta do Sol Tumet em Nahom, que fica em Uldum.', 0),
(27756, 'ptBR', 'O capataz', 'Mate Falagrum.', 'Se quisermos descobrir o que está acontecendo aqui, vamos ter que abrir caminho na marra pelas Minas Mortas! O primeiro adversário forte que você vai encontrar é Falagrum, o Capataz, um mago ôgrico poderoso. Cuidado: ele tem a força bruta natural dos ogros e o apoio dos feitiços maléficos!$B$BLeve este comunicador para mantermos contato durante a investigação. Tenha bastante cuidado.', '', '', '', '', '', '', 'Falagrum', 'Estamos mais próximos de desvendar o mistério.', 'Tenente Horatio Laine', 'Fale com o Tenente Horatio Laine dentro das Minas Mortas.', 0),
(27757, 'ptBR', 'As profundezas mais sombrias', 'Mate Hr\'nglth, o Perdido.', 'Tenho observado seres marinhos agindo estranhamente por todo o pântano. Os murlocs, sim, mas, antes deles, os guelblins e os makruras... Até vi algumas nagas perambulando em terra firme outro dia.$B$BAlgo está chamando essas criaturas para cá e, pra completar, botando-as em um estado de frenesi. Muitas foram atraídas à Caverna Pantanal dos Cervos, a oeste. Tem alguma coisa ali, e, se ficar mais forte, seremos os próximos a perambular por lá...$B$BVocê deve pôr um fim nisso antes que o pior aconteça.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Baba Globlêbada no Pantanal dos Cervos, que fica no Pântano das Mágoas.', 0),
(27758, 'ptBR', 'O carpinteiro', 'Derrote Helix Quebracâmbio.', '<Bzzzzzzzzzzzzt.>$B$BAlô, alô, tá me ouvindo? Ótimo!$B$BParece que o Helix é o responsável pela construção de um mastro gigantesco. Você não acha que eles estão planejando terminar a Fortaleza Flutuante Défias, acha?$B$BÉ melhor você investigar isso, $n, e não hesite se precisar sujar as mãos! Você tem licença para matar e, convenhamos, precisará usar e abusar dela.', '', '', '', '', '', '', 'Helix Quebracâmbio', 'Agora tudo está começando a fazer sentido.', 'Tenente Horatio Laine', 'Fale com o Tenente Horatio Laine dentro das Minas Mortas.', 0),
(27760, 'ptBR', 'Inteligência artificial', 'Utilize o terminal A.Í.D.A. no Entreposto de Inspeção, que fica em Uldum.', '<Uma voz feminina o direciona ao terminal portátil.>$B$BCódigo de emergência: 55-729.$B$BAs funções cerebrais do córtex superior dos membros da expedição foram comprometidas.$B$BDirija-se ao terminal mais próximo, a sudeste do Terraço da Pedra Solar, para obter análises adicionais.', '', '', '', '', '', '', '', '', '', '', 0),
(27761, 'ptBR', 'Distração fatal', 'Desarme a Primeira, a Segunda e a Terceira Bateria Explosiva e desative 4 Bombômatos Instáveis na Tumba do Rei Sol.', 'A maldição tomou conta das funções cerebrais principais dos membros da expedição, mas meus cálculos revelam que seus subconscientes adolescentes reprimidos ainda podem ser estimulados por imagens realistas.$B$BUtilize esse projetor holográfico para distraí-los.$B$BEles agora estão plantando explosivos na tumba a leste para tentar acessar passagens secretas em Uldum.$B$BEles estão à procura de uma perigosa tecnologia de recriação abaixo de Uldum e devem ser impedidos.', '', 'Primeira Bateria Explosiva desarmada', 'Segunda Bateria Explosiva desarmada', 'Terceira Bateria Explosiva desarmada', 'Bombômato Instável desativado', '', '', '', '', 'Retorne ao terminal A.Í.D.A.', 0),
(27762, 'ptBR', 'Fazfagulha, cara!', 'Pilote o Inderrubável e vá para os Ermos. Depois, apresente-se a Edu Flossobio.', 'Ei, $r, escute aqui. Tenho uma oportunidade de trabalho que você não vai querer perder.$b$bSomos enviados de Fazfagulha, uma nova cidade goblínica que fica nos Ermos. Muito dinheiro para ser feito lá, sim $gsenhor:senhora;. E, nem de longe, tantos zumbis... ou tipinhos metidos como os paladinos argênteos.$b$bNão, aquilo lá é natureza imaculada, e estamos procurando alguém como você para nos ajudar a domá-la. Assim que você estiver pront$go:a;... estaremos esperando.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Edu Flossobio na Fazfagulha Litorânea, que fica nos Ermos.', 0),
(27763, 'ptBR', 'Rumo a Fazfagulha', 'Use o Teleportador na parte de trás de Fazfagulha Litorânea para se teleportar para o alto da montanha. Em seguida, apresente-se a Dolfo Fazbum em Fazfagulha, nos Ermos.', 'Isto, $r, é o paraíso. Eu sempre quis viver em uma cidadezinha quieta à beira mar para poder me concentrar nas minhas explosões sem nenhuma distração.$b$bMas nem todo mundo gosta de sossego... especialmente os aventureiros, como você.$b$bNós instalamos um teleportador, na parte de trás da cidade, que levará você até o topo dos penhascos. Dali, você pode chegar rapidamente a Fazfagulha, a oeste dos Ermos.$b$bDeve ter mais coisas para você fazer lá em cima. Diga que foi o Edu que enviou você.', '', '', '', '', '', '', '', '', '', '', 0),
(27764, 'ptBR', 'Um pedido estranho', 'Entregue o Pacote do Dolfo para Rhea na Ravina Lethlor, que fica nos Ermos.', 'Vamos tratar de outras questões. Eu tenho uma encomenda para entregar.$b$bUma mocinha veio à cidade, há pouco tempo, procurando pólvora comprimida, uma carcaça de mithril temperado e uns óculos de segurança. Naturalmente, a gente tinha bastante pólvora e carcaças de bomba para vender, mas os óculos de segurança foram um pouco mais difíceis de encontrar.$b$bResumindo, eu arranjei os óculos, mas ela já voltou pra pesquisa lá na Ravina Lethlor. Você poderia entregar a encomenda para ela?', '', '', '', '', '', '', '', '', '', 'Apresente-se a Rhea na Ravina Lethlor, que fica nos Ermos.', 0),
(27765, 'ptBR', 'Primeira amostra: ovos selvagens', 'Colete 6 Ovos de Dragões Negros Selvagens.', 'Estou estudando dragões negros. Especificamente, estou interessada em como eles procriam.$b$bMinha pesquisa atual requer muitos ovos de dragões negros, e é por isso que eu vim para a Ravina Lethlor. Eu própria poderia coletar os ovos, mas acho que você vai se beneficiar, se me ajudar.$b$bOs ovos estão ao longo da beirada da ravina. Cuidado com os guardiões lá em cima – eles não gostam de ovos roubados.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rhea na Ravina Lethlor, que fica nos Ermos.', 0),
(27766, 'ptBR', 'Segunda amostra: dragonetes', 'Obtenha 10 Corpos de Dragonetes Escaldantes.', 'Vou pedir outro favor. Preciso que você colete alguns corpos de dragonetes negros. Mate-os e traga os corpos para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rhea na Ravina Lethlor, que fica nos Ermos.', 0),
(27768, 'ptBR', 'Segundo passo: O dessangrador', 'Mate Gomora, o Dessangrador, no Matadouro.', 'Aqui, os trolls perpetuam a queda dos meus irmãos ao pesadelo. Infectam e corrompem dragões verdes com o sangue de seu deus malévolo para, então, colherem o mal que neles cultivaram. Meus irmãos estão sendo explorados como faz-se a gado...$B$BEsta selvageria lamentável não pode prosseguir. Volte à saída que você usou para deixar o Salão das Máscaras e percorra o corredor em direção ao Matadouro. Gomora, o Dessangrador, colhe cadáveres para esses malévolos e cruéis rituais. Tome a vida desse que a desmerece!', '', '', '', '', '', '', 'Gomora, o Dessangrador', 'A Pedra do Juramento nos liga.', 'Lorde Itharius', '', 0),
(27769, 'ptBR', 'Revelação de Rhea', 'Conheça a verdadeira identidade de Rhea.', 'Como eu já disse, eu não sou uma goblina qualquer. É possível que você já tenha adivinhado a minha verdadeira identidade.$b$bPermita-me mostrar a você a minha forma real. E, como você provou ser confiável, também compartilharei detalhes do meu plano.', '', 'Descubra a verdadeira identidade de Rhea', '', '', '', '', '', '', '', 'Fale com Rheastrasza na Ravina Lethlor, que fica nos Ermos.', 0),
(27770, 'ptBR', 'Levantando o véu', 'Testemunhe a última parte da pesquisa de Rhea.', 'A Revoada Negra já foi nobre. Eles eram os guardiões do solo. Que ironia eles terem se tornado a pior ameça que esta terra já viu!$b$bMas acredito que ainda reste um fiapo de esperança, assim como crê a minha mestre. A Revoada Negra sobreviverá à traição do Asa da Morte e tornará a voar como a nobre protetora da terra.$b$bQuero lhe mostrar uma coisa. Feche os olhos e revelarei a você a última parte da minha pesquisa.', '', 'Testemunhe a última parte da pesquisa de Rhea', '', '', '', '', '', '', '', 'Fale com Rhea na Ravina Lethlor, que fica nos Ermos.', 0),
(27771, 'ptBR', 'Terceira amostra: ovos implantados', 'Obtenha 3 Ovos de Nyxondra.', 'Nyxondra está aqui contra a vontade. Ela está escondida da prole, bem no meio do território em que procriam. Bota ovos que serão tomados dela antes mesmo de chocarem.$b$bCruel? Talvez... Mas nem de longe tão cruel quanto o tratamento que a revoada dela prestou à minha mestre.$b$bProve que posso confiar em você, $n. Pegue os ovos de Nyxondra e traga-os para mim. Você terá que dominá-la para poder pegá-los.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rhea na Ravina Lethlor, que fica nos Ermos.', 0),
(27772, 'ptBR', 'O venerável Doutor Blam', 'Entregue as Amostras de Dragão Negro para o Dr. Hieronymus Blam na Ruína de Agmundo, que fica nos Ermos.', 'Tomei uma decisão calculada ao revelar minha identidade a você, $n. Eu precisava ganhar a sua confiança, pois não posso mais ficar aqui na Ravina Lethlor – meu disfarce já foi revelado, sem dúvida.$b$bMas você tem chance de conseguir passar $Gdespercebido:despercebida;. Pegue os resultados da nossa pesquisa e leve-os para o oeste. Na Ruína de Agmundo, você encontrará um gnomo que sabe o que fazer com estes espécimes.$b$bDepressa, $n! Não perca mais tempo aqui do que o necessário!', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Dr. Hieronymus Blam na Ruína de Agmundo, que fica nos Ermos.', 0),
(27773, 'ptBR', 'Terceiro passo: profeta', 'Derrote Jammal\'an, o Profeta.', 'Tudo que permanece entre eu e o templo é o próprio profeta Jammal\'an. Ele é o líder dos trolls Atal\'ai que aqui estão, um sórdido manipulador.$B$BSaiba que você não enfrentará um mero troll enlouquecido, $n, mas um instrumento de forças além de sua concepção mais sombria. Mas esta luta não há de ser apenas sua; minha força e a vontade da revoada verde estarão com você.$B$BProceda ao Covil do Arauto, à esquerda pelo Salão do Ritual, para, então, descer ao Salão dos Ossos. Ao fundo, você encontrará Jammal\'an.', '', 'Jammal\'an, o Profeta, vencido', '', '', '', '', 'Jammal\'an, o Profeta', 'A Pedra do Juramento nos liga.', 'Lorde Itharius', '', 0),
(27774, 'ptBR', 'Facilmente controlável', 'Mate 9 ogros Arrota-pó no Acampamento Kosh.', 'A ameaça mais imediata a Fazfagulha é, sem dúvida, a colônia de ogros a noroeste.$b$bA maioria dos nossos vizinhos era de guerreiros, mas parece que mais e mais deles estão praticando magia. E eu não quero um exército de ogros-magos no meu quintal.$b$bMate alguns ogros Arrota-pó. Vamos torcer para que eles entendam o recado e não desafiem o poder de Fazfagulha.', '', 'Ogros Arrota-pó mortos', '', '', '', '', '', '', '', 'Fale novamente com Dolfo Fazbum em Fazfagulha, que fica nos Ermos.', 0),
(27775, 'ptBR', 'Quando as coisas complicam, trapaceie', 'Obtenha um Bastão do Instrutor de um Instrutor Ogro-mago no Acampamento Kosh.', 'Não consigo fazer a minha invenção funcionar! Porcaria!$b$bChega, já decidi. Vou trapacear e usar magia.$b$bO que a minha invenção precisa é de um pistão sólido e fino, para passar por um tubo estreito de cobre, mas forte o bastante para suportar impactos repetitivos sem quebrar. Os bastões mágicos daqueles magos ogros ao norte devem funcionar perfeitamente.$b$bA julgar pelo que vi, apenas os instrutores têm cajados fortes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gabriana Flizotuque em Fazfagulha, que fica nos Ermos.', 0),
(27776, 'ptBR', 'É hora do bode, meu bem', 'Use o Soca-bode da Gabriana em 12 Bodes de Fazfagulha.', 'Estamos tendo um probleminha com os bodes daqui, caso você não tenha notado. Eles comem de tudo e parecem ter tomado gosto pelas pilhas de porcas e engrenagens que deixamos por aí.$b$bIsso está ficando irritante!$b$bA maioria dos bodes perambula à beira da cidade, perto do penhasco. Use este dispositivo para dar um "empurrãozinho" neles.', '', 'Bodes empurrados', '', '', '', '', '', '', '', 'Fale novamente com Gabriana Flizotuque em Fazfagulha, que fica nos Ermos.', 0),
(27777, 'ptBR', 'Códigos de acesso ao núcleo', 'Obtenha os Códigos de Acesso ao Núcleo com Toinfluxo, o Insano.', 'O contingente da expedição é extremamente numeroso, usuári$go:a; $n.$B$BLidar com eles através dos meios convencionais levará aproximadamente 2.700.136,5 horas.$B$BAlternativamente, podemos utilizar uma fonte de energia poderosa que está guardada no veículo da expedição.$B$BPrecisaremos dos códigos de acesso do núcleo de fusão para utilizá-la.$B$BO mecangenheiro Toinfluxo possui os códigos. Ele fica na Torre de Vigia Estelar, a sudoeste.$B$BEu carreguei frequências de interferência em um misturador de frequências. Use-o para desabilitar temporariamente as defesas de Toinfluxo.', '', '', '', '', '', '', '', '', '', 'Volte ao Terminal A.I.D.A.', 0),
(27778, 'ptBR', 'Hackeando o Wibson', 'Invada o Computador Wibson no topo do Submarino M.A.C.', 'É verdade. Novos tripulantes da expedição chegaram por mar.$B$BMeus analisadores detectaram que eles já foram afetados pelo fenômeno da maldição.$B$BVocê deve se apressar e embarcar no submarino M.A.C. Os códigos de acesso nos permitirão controlar as funções de fusão do núcleo, mas ainda há uma barreira de segurança que devemos transpor.$B$B$gUsuário:Usuária; $n, tenho que lhe pedir que invada um computador muito sofisticado conhecido como "Wibson".$B$BNão se preocupe, eu lhe darei instruções adicionais.', '', 'Computador Wibson invadido', '', '', '', '', '', '', '', 'Vá ao Núcleo de Fusão no topo do Submarino M.A.C. em Uldum.', 0),
(27779, 'ptBR', 'Gnomobliteração', 'Elimine 1000 Gnomos Enlouquecidos.', 'Transferi meu programa ao núcleo de fusão e já tenho controle total sobre ele.$B$BCriei uma pequena bolsa de ar em seu interior para impedir a vaporização $gdo usuário:da usuária; $n.$B$BPermitirei o controle de todas as funções de movimento para que possa dedicar meus ciclos a manterem o núcleo estável.$B$BMinhas análises revelam que você pode sentir... "culpa" como resultado de números altamente fatais.$B$B$gUsuário:Usuária; $n, você deve saber que não há esperança para os membros da expedição.', '', 'Gnomo Enlouquecido eliminado', '', '', '', '', '', '', '', '', 0),
(27781, 'ptBR', 'A maquinação', 'Destrua o Ceifador de Inimigos 5000.', '<Bzzzzzzzzzzzzt.>$B$B<Bzzzzzzzzzzzzt.>$B$BA-alô? Tá aí, $n? Tá $gvivo, rapaz:viva, garota;? Alô?$B$BMinha nossa, até que enfim você respondeu! Pelos verdes bosques de Lordaeron! Que monstruosidade mecânica é essa que eles estão fazendo? Você não pode permitir que eles concluam essa... essa... essa coisa!$B$BDeixe as regras de lado e faça tudo o que for preciso para acabar com os planos deles!', '', '', '', '', '', '', 'Ceifador de Inimigos 5000', 'Mostre toda sua maestria em furtividade!', 'Tenente Horatio Laine', 'Fale com o Tenente Horatio Laine dentro das Minas Mortas.', 0),
(27782, 'ptBR', 'Mathias precisa de você', 'Fale com o Mestre Mathias Shaw na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 'A gente já passou por poucas e boas. Que pena que ‘‘cê vai partir. Mas Mathias disse que precisa de você.$B$BEle falou que é urgente!$B$BEntão, ‘‘cê quer uma bebidinha ou qualquer outra coisa, $grapaz:moça;?', '', '', '', '', '', '', '', '', '', '', 0),
(27783, 'ptBR', 'Garona precisa de você', 'Fale com Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 'A gente já passou por poucas e boas. Que pena que ‘‘cê vai partir. Mas Garona disse que precisa de você.$B$BEla falou que é urgente!$B$BEntão, ‘‘cê quer uma bebidinha ou qualquer outra coisa, $grapaz:moça;?', '', '', '', '', '', '', '', '', '', '', 0),
(27784, 'ptBR', 'O Martelo do Crepúsculo', 'Vá até o Martelo do Crepúsculo.', 'Enquanto você estava na mina, consegui descobrir onde o Martelo do Crepúsculo está sendo mantido. Eles o criaram no Altar do Crepúsculo, ao sul daqui.$B$BMais importante do que isso, os sectários cometeram um erro crítico: Cho\'gall está supervisionando pessoalmente a etapa final da construção dele.$B$BMuitos agentes da AVIN morreram para nos fornecer essa informação.', '', '', '', '', '', '', '', '', '', '', 0),
(27785, 'ptBR', 'O almirante', 'Mate o Almirante Rosnarrasga.', '<Bzzzzzzzzzzzzt.>$B$BNão dá para acreditar... Eles já estão quase acabando de reconstruir aquela monstruosidade! Apresse-se, $n. Não temos muito tempo.$B$BO almirante Rosnarrasga, que é o braço direito da Vanessa, deve estar a bordo da Fortaleza Flutuante. Nunca vamos conseguir colocar as mãos em um fio de cabelo dela se ele ainda estiver vivo. Então, escale a Fortaleza Flutuante, encontre o Rosnarrasga e mate ele. Assim, vamos ter livre acesso aos alojamentos particulares da Vanessa no convés superior.$B$BTenha cuidado! O Almirante foi assolado pela maldição dos worgen e fará de tudo para cravar as garras em você!', '', '', '', '', '', '', 'Almirante Rosnarrasga', 'Agora sim.', 'Tenente Horatio Laine', 'Fale com o Tenente Horatio Laine dentro das Minas Mortas.', 0),
(27786, 'ptBR', 'O Martelo do Crepúsculo', 'Vá até o Martelo do Crepúsculo.', 'Enquanto você estava na mina, consegui descobrir onde o Martelo do Crepúsculo está sendo mantido. Eles o criaram no Altar do Crepúsculo, ao sul daqui.$B$BMais importante do que isso, os sectários cometeram um erro crítico: Cho\'gall está supervisionando pessoalmente a etapa final da construção dele.$B$BMuitos Kor\'kron morreram para nos fornecer essa informação.', '', '', '', '', '', '', '', '', '', '', 0),
(27787, 'ptBR', 'Britacrânios, o Montanha', 'Sobreviva a Britacrânios, o Montanha, para então matá-lo.', 'Era uma armadilha! Cho\'gall atraiu você com o Martelo do Crepúsculo para que o monstrengo dele acabasse com você.$B$BResista e mate Britacrânios, o Montanha!', '', 'Sobreviva ao tabefe de Britacrânios', '', '', '', '', 'Britacrânios, o Montanha', '', '', 'Fale com Kurdran Martelo Feroz no Pontal do Vencedor, que fica no Planalto do Crepúsculo.', 0),
(27788, 'ptBR', 'Britacrânios, o Montanha', 'Sobreviva a Britacrânios, o Montanha, para então matá-lo.', 'Era uma armadilha! Cho\'gall atraiu você com o Martelo do Crepúsculo para que o monstrengo dele acabasse com você.$B$BResista e mate Britacrânios, o Montanha!', '', 'Sobreviva ao tabefe de Britacrânios', '', '', '', '', 'Britacrânios, o Montanha', '', '', 'Fale com a Senhora da Guerra Zaela em Cachamorra, que fica no Planalto do Crepúsculo.', 0),
(27789, 'ptBR', 'Problemas de Trogg', 'Entre em uma Torreta do Blam e sobreviva a quatro ondas de ataque trogg.', 'Vou precisar de um pouco de tempo para analisar estas amostras, e também de uma folga da função de matador de troggs. Assuma o controle de uma das torretas e elimine quantos troggs você puder. Eu vou ficar aqui, estudando.$b$bAs torretas têm duas ferramentas: o tiro comum e uma descarga elétrica para quando muitos inimigos chegam perto! He, he! Boa sorte.$b$bAh, e cuidado com os troggs grandes e lerdos. Você não vai achar legal se eles chegarem muito perto.', '', 'Sobreviva à primeira onda', 'Sobreviva à segunda onda', 'Sobreviva à terceira onda', 'Sobreviva à última onda', '', '', '', '', 'Fale novamente com o Dr. Hieronymus Blam na Ruína de Agmundo, que fica nos Ermos.', 0),
(27790, 'ptBR', 'O chefão Défias', 'Mate o Chefão Défias.', 'Olá, $n. Ouvi falar muito de você. Escute bem o que tenho a dizer. Você terá somente uma chance para fazer o que pedirei.$B$BA nova chefe Défias deve estar dentro da cabana maquinando toda a operação. Quero que você vá lá e mate aquela bandida pelo bem das centenas de inocentes que aquela organização, fundada pelo pai dela, matou e aterrorizou.$B$BEstou impressionado por ela ter deixado você se aproximar dos domínios dos Défias e não ter fugido, provavelmente esperando por condições mais favoráveis. Acho que demos sorte.', '', '', '', '', '', '', 'Mestre Mathias Shaw', '', '', 'Fale com o Tenente Horatio Laine dentro das Minas Mortas.', 0),
(27791, 'ptBR', 'Escavação de Sopravento', 'Fale com o Prospector-chefe Durdin na Escavação de Sopravento, que fica nos Ermos.', 'Eu tive uma ideia que pode não dar certo. Acontece que, felizmente, fazer dar certo é uma das minhas especialidades.$b$bAo norte daqui, a Liga dos Exploradores desenterrou um novo conjunto de ruínas. Se tem alguma coisa mais velha e sábia do que dragões, são os titãs. Diabos, eu ouvi rumores de que os titãs CRIARAM os dragões.$b$bFale com o prospector-chefe Durdin no acampamento ao norte. Ele terá mais informações do que eu sobre esses titãs.$b$bLembra o que eu disse? Pode não dar certo.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Prospector-chefe Durdin na Escavação de Sopravento, que fica nos Ermos.', 0),
(27792, 'ptBR', 'Vale tudo no amor, na guerra e na arqueologia', 'Obtenha um Cálice Quebrado, um Vaso Empoeirado, um Hieroglifo Terrano e uma Ferramenta Trogg.', 'Carece de tratar primeiro do mais importante. Não posso simplesmente sentar e te falar de tudo que descobrimos nas ruínas. Temos problemas a resolver.$b$bO mais urgente é aquele bando de xucros do Relicário, que estão do outro lado da tumba. Eles estão se mandando com todo o nosso saque! Eles não sabem que aquela escavação é trabalho de anão?$b$bBueno, vai atrás de alguns dos escavadores deles – um bando de malevos, na minha opinião – e traz de volta alguns desses preciosos artefatos aqui pra mim.$b$bAÍ ENTÃO a gente conversa sobre os titãs.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Prospector-chefe Durdin na Escavação de Sopravento, que fica nos Ermos.', 0),
(27793, 'ptBR', 'Protetores ancestrais', 'Investigue o Guardião e a Sentinela.', 'Você ouviu bastante barulho vindo da câmara central da tumba. Aquelas duas estátuas grandes lhe pareceram terrivelmente suspeitas.', '', 'Guardião investigado a fundo', 'Sentinela investigada a fundo', '', '', '', '', '', '', 'Inspecione o Tesouro dos Titãs dentro da Tumba dos Observadores, que fica nos Ermos.', 0),
(27794, 'ptBR', 'Fale novamente com Blam', 'Leve o Olho dos Vigilantes para o Dr. Hieronymus Blam na Ruína de Agmundo, que fica nos Ermos.', 'Dentro da arca, você encontra um pequeno dispositivo circular repousando sobre uma almofada.$b$bSe há algum artefato titânico a ser encontrado nesta tumba, é este. Você decide levá-lo de volta para o Dr. Blam.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Dr. Hieronymus Blam na Ruína de Agmundo, que fica nos Ermos.', 0),
(27795, 'ptBR', 'Marés Sombrias', 'Mate 6 Ogros do Pedregal.', 'A batalha está correndo exatamente como eu esperava. Os guerreiros deles estão quase exaustos, então eu acabei de despachar nossa cavalaria para lá.$B$BSó que eu não contava que eles tivessem ogros nas suas tropas. Nossos cavaleiros dariam conta dos brutos inimigos com facilidade, mas agora eles vão precisar de ajuda.$B$BPreciso que você volte ao campo de batalha imediatamente, $n. Poucos soldados desmontados são capazes de abater um ogro, mas acredito que posso contar com você para este fim. Não me desaponte.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Joana Tristalma no Posto Maré do Pântano, que fica no Pântano das Mágoas.', 0),
(27796, 'ptBR', 'O peão do guardião', 'Encontre um uso para o Peão do Guardião dentro da Tumba dos Observadores, que fica nos Ermos.', 'Quando esses trambiqueiros do Relicário chegaram aqui, nós entramos em pânico e começamos a saquear tudo indiscriminadamente.$b$bMuita arqueologia ruim aconteceu naquele dia.$b$bFelizmente, a Olga esbarrou nesta pequena estátua de jade. Achamos que era algum tipo de chave, mas não conseguimos descobrir o que ela abre. Talvez você tenha mais sorte.', '', '', '', '', '', '', '', '', '', '', 0),
(27797, 'ptBR', 'O peão da sentinela', 'Encontre um uso para o Peão da Sentinela dentro da Tumba dos Observadores, que fica nos Ermos.', 'Quase que um dos baguais do Relicário do Vigiassangre roubou esta estátua da gente. Conseguimos pegar ele com a boca na botija e recuperamos a estátua, mas não valeu tanto a pena.$b$BIsso parece ser algum tipo de chave, mas eu não achei a fechadura em lugar algum dessas ruínas. Que tal você tentar?', '', '', '', '', '', '', '', '', '', '', 0),
(27798, 'ptBR', 'Água da Vida', 'Use a Água da Vida para obter informações com o Cadáver do Mestre Forjador Finlay.', 'Leve minha Água da Vida e use-a no corpo do anão afogado.$B$BEle trabalhava com metais enquanto vivia e, embora o corpo dele agora sirva de alimento para o meu lago, a Água da Vida vai permitir que ele lhe diga o que você quer saber.$B$BEntão, vá conseguir sua informação e saia dos meus domínios.', '', 'Informação sobre o artefato obtida', '', '', '', '', '', '', '', 'Fale com Garona Meiorken na Cidadela do Crepúsculo, que fica no Planalto do Crepúsculo.', 0),
(27799, 'ptBR', 'Palavras, apenas palavras', 'Interrompa os rituais dos sectários no Bazar, no Vale da Honra e perto do portão oeste de Orgrimmar, lendo as palavras erradas do Livro de Encantamentos.', 'Agora que você está $Gfamiliarizado:familiarizada; com o ritual, é hora de realizá-lo na cidade. Muitos dos nossos confrades já aguardam nos locais onde os rituais acontecerão.$B$BQuero que você visite esses locais no segundo andar do Bazar, no Vale da Honra, perto do Salão dos Valentes, e perto do portão oeste de Orgrimmar. Tudo o que você tem que fazer é ler a última parte do encantamento do livro, pois os grupos já devem ter feito todo o resto.$B$BEm breve, Orgrimmar arderá em chamas!', '', 'Interromper Ritual no Bazar', 'Interromper Ritual no Vale da Honra', 'Interromper Ritual no Portão Oeste', '', '', '', '', '', 'Fale novamente com o Guarda-de-sangue Torek no Vale da Força de Orgrimmar.', 0),
(27800, 'ptBR', 'Se eles podem, eu também posso', 'Use a Veste do Recruta, vá à Fazenda do Beberrão e consiga o Livro de Encantamentos do Feitor Jintak. Leia o Livro de Encantamentos perto do Altar dos Sectários e pratique o ritual.', 'Prendemos mais e mais sectários e, mesmo assim, eles parecem confiantes da vitória. Precisamos descobrir mais sobre o ritual que eles mencionaram.$B$BEsses rituais parecem ser o alicerce dos planos para atacar Orgrimmar.$B$BPegue uma das vestes de um dos sectários detidos... eles não vão mais precisar delas. Vista-a e volte ao acampamento deles na Fazenda do Beberrão, em Durotar. Tente conseguir alguma informação sobre esses rituais e quais os planos deles.', '', 'Pratique o Ritual dos Sectários', '', '', '', '', '', '', '', 'Fale novamente com o Feitor Jintak na Fazenda do Beberrão, que fica em Durotar.', 0),
(27801, 'ptBR', 'Documento, por favor', 'Vá aos portões de Orgrimmar, leia a Proclamação do Chefe Guerreiro e reviste 5 Cidadãos de Orgrimmar. Confisque qualquer coisa suspeita que encontrar.', 'O fluxo de pessoas em Orgrimmar está proibido, pois descobrimos um grupo de sectários que tentava entrar em nossa cidade. O Chefe Guerreiro decretou que todos os visitantes devem ser revistados antes de entrar. Leve esta cópia da proclamação e leia para as pessoas reunidas em frente ao portão principal. Depois, ajude os guardas a revistar todos aqueles que desejam entrar.', '', 'Cidadãos de Orgrimmar revistados', 'Leia a Proclamação do Chefe Guerreiro', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-sangue Torek no Vale da Força.', 0),
(27802, 'ptBR', 'Prenda os infiltrados', 'Use as Algemas Pesadas para prender 5 Sectários Infiltradores e entregue-os para o Responsável Gartok Iracarpos no Ringue dos Valorosos, que fica no Vale da Honra de Orgrimmar. Depois que tiver entregue os prisioneiros, interrogue um dos Sectários Detidos.', 'O bilhete que você encontrou significa apenas uma coisa: o decreto do Chefe Guerreiro chegou tarde demais. Muitos sectários já se infiltraram em nossa cidade.$B$BAqui diz onde e quando eles vão se encontrar, mas não menciona nada sobre os planos deles. Nossos inimigos estão cada vez mais espertos. Não vai ser fácil encontrar esses infiltrados, mas precisamos deter o maior número possível. Use estas algemas e prenda qualquer agente que encontrar. Leve-os para o responsável Gartok Iracarpos no Ringue dos Valorosos, que fica no Vale da Honra.', '', 'Sectários detidos e levados ao Ringue dos Valorosos', 'Interrogue um Sectário Detido', '', '', '', '', '', '', 'Fale novamente com o Guarda-de-sangue Torek no Vale da Força de Orgrimmar.', 0),
(27803, 'ptBR', 'Alívio em boa hora', 'Mate 8 Tacafogos Subjugados.', 'Tenho homens formando as linhas de defesa por todos os lados da cidade, mantendo afastados os elementais que emergem da terra. Eles são bons camaradas e estão aguentando firme, mas mesmo o anão mais vigoroso se cansa uma hora.$B$BEles estão se dividindo em turnos: uma hora de descanso para cada hora de serviço. É o melhor que posso fazer...$B$BSe tu quiser ajudar, cumpra um turno numa das linhas. Volte depois de matar vários elementais.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Quincas Barbarruiva na Patrulha do Barbarruiva, que fica no Planalto do Crepúsculo.', 0),
(27804, 'ptBR', 'Um lugar para chamar de lar', 'Apague 50 focos de incêndio na Patrulha do Barbarruiva.', 'Nós já sofremos muitas derrotas, mas eu não vou desistir e entregar nossas casas pra esses vira-latas. Eles podem incendiar, roubar e cuspir nas ruínas, mas mesmo assim vamos continuar lutando para tomar de volta o que é nosso.$B$BMas é muito melhor retomar as ruínas com nada queimado. Meus rapazes estão enchendo baldes com água do poço para diminuir o fogo. Se tu for ajudar, eles podem atirar os baldes para tu não precisar ficar correndo para lá e para cá.', '', 'Incêndios do vilarejo apagados', '', '', '', '', '', '', '', 'Fale novamente com Quincas Barbarruiva na Patrulha do Barbarruiva, que fica no Planalto do Crepúsculo.', 0),
(27805, 'ptBR', 'Pequenos caprichos', 'Encontre e devolva a Boneca da Aprika, as Rosas Ressecadas de Meara e o Martelo de Marfim de Parlan.', 'Então tu é $go guri:a guria; que está ajudando o Quincas? Prazer em te conhecer! Talvez tu possa fazer um favor – ou dois – aos Martelo Feroz perturbados que se refugiaram aqui.$B$BFomos obrigados a recuar para este prédio com pressa, e alguns deixaram pertences de grande valor para trás, em nossas casas destruídas nas redondezas. Tu se importaria de pegar algumas coisas quando for lá fora? Tu faria algumas almas perturbadas muito felizes.', '', '', '', '', '', '', '', '', '', 'Fale com Cailin Boagente na Patrulha do Barbarruiva, que fica no Planalto do Crepúsculo.', 0),
(27806, 'ptBR', 'Recrutamento honroso', 'Fale com Iain Barbarruiva no Cemitério de Barbarruiva.', 'Iain, o segundo homem no comando, levou o corpo de um de nossos heróis caídos para a catedral a oeste. Ele é o homem que encarreguei de reestruturar a equipe de cavalga-grifos com os remanescentes de outras frotas. Quero que você o ajude.$B$BQuero que tu perceba a urgência desta tarefa. Nós não vamos conseguir resistir por muito tempo aqui – o Martelo do Crepúsculo ou os orcs Presa do Dragão podem nos atacar a qualquer momento. Recrutar uma nova força aérea pode ser nossa única esperança de sobrevivência nos conflitos.', '', '', '', '', '', '', '', '', '', '', 0),
(27807, 'ptBR', 'Clã Mullan', 'Fale com Duglas Mullan no Caldeirão da Carnificina.', 'Se for para reestruturar uma frota aérea completa de grifos, vamos precisar nos mexer rápido para juntar os sobreviventes antes que partam ou sejam capturados. Estou de olho em alguns grupos de cavalgadores que ficaram juntos. Estou partindo para encontrar os cavalgadores Moore e os Trondamar o mais rápido possível.$B$BOs Mullan seguiram para o Caldeirão da Carnificina, que fica a oeste, da última vez que os vi. Veja se tu consegue convencer Duglas Mullan a se unir a Quincas – afinal, ele está devendo alguns favores...', '', '', '', '', '', '', '', '', '', '', 0),
(27808, 'ptBR', 'Teimoso como um Doyle', 'Fale com Keeland Doyle na Floresta do Planalto.', 'Os cavalgadores Doyle foram vistos pela última vez convergindo para a mata ao sul, na fronteira com a Floresta Obsidiana. Eles são um bando de teimosos e podem ser difíceis de convencer a se unirem a nós.$B$BTua melhor chance com Keeland Doyle é falar pra ele que Cailin Boagente está conosco na cidade. Keeland tem uma quedinha por ela e isso deve ser o suficiente para convencê-lo a levar guris dele para nos ajudar.', '', '', '', '', '', '', '', '', '', '', 0),
(27809, 'ptBR', 'Barbarruiva à vista!', 'Fale com Mackay Barbarruiva no Acampamento de Guerra Gorshak.', 'Preciso que tu vá até o outro lado da Brecha Devoradora, no Acampamento de Guerra Gorshak, para procurar Mackay e os homens dele.$B$BOs Presa do Dragão não sobreviveram ao massacre inicial e Mackay tá querendo saquear tudo o que puder para nos equipar para a guerra. Não vai ser necessário convencer ninguém, mas eles vão querer uma ajudinha para terminar a tarefa antes de se unirem a Quincas.$B$BEnfie o pé no traseiro deles em nome do velho Iain se for necessário.', '', '', '', '', '', '', '', '', '', '', 0),
(27810, 'ptBR', 'Espírito de luta', 'Desafie e derrote um dos Cavalga-grifos Mullan.', 'Quincas quer que os Mullan levantem voo com ele? Se tem um anão com quem eu voaria, esse anão é ele. Ainda assim, não sei por que ele mandou $gum forasteiro:uma forasteira; para me recrutar – não foi muito educado da parte dele, pelo menos para os meus padrões.$B$BAcho que tu não dura 20 segundos com meus guris, seja num bar ou numa guerra. Prove que estou enganado. Derrote um dos guris em uma briga e depois penso se voo ou não com o velho Quincas.', '', 'Cavalga-grifos Mullan derrotado', '', '', '', '', '', '', '', 'Fale com Duglas Mullan no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27811, 'ptBR', 'O doce perfume da guerra', 'Encontre 8 Grifos dos Mullan e devolva-os para seus Cavalga-grifos.', 'Não se engane com Duglas, os Mullan estão loucos para voarem de novo, e se tem alguém por quem faríamos isso, esse alguém é Barbarruiva.$B$BDeixamos nossos grifos na Floresta do Planalto ao sul para caçarem e se afastarem um pouco dos ruídos da batalha. Eles mereciam um descanso.$B$BSe tu nos quer de volta aos ares logo, seria bom nos ajudar a trazer os grifos de volta.$B$BPegue este pedaço de vidoeiro chamuscado. Usamos isso no treinamento – eles vão voltar direto para nós assim que sentirem o cheiro do vidoeiro!', '', 'Grifos dos Mullan encontrados e devolvidos', '', '', '', '', '', '', '', 'Fale com Edana Mullan no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27812, 'ptBR', 'A lealdade do clã Mullan', 'Informe as notícias sobre o Clã Mullan para Iain Barbarruiva no Cemitério de Barbarruiva.', 'Você convenceu a gente. Quincas pode contar com nossa ajuda. Vamos encontrar ele na cidade assim que meus guris estiverem prontos.$B$BVocê é bem $gdurão:durona; para alguém que não é um Martelo Feroz. A criação também deve ser boa no lugar de onde tu vem.$B$BMas ainda não te vi bebendo. Isso sim seria um bom teste.', '', '', '', '', '', '', '', '', '', '', 0),
(27813, 'ptBR', 'Morte à altura dos Presa do Dragão', 'Derrote 6 Desertores Presa do Dragão.', 'O Crepúsculo saqueou esta cidade e matou a maioria dos Presa do Dragão que viviam aqui. Alguns sobreviveram, mas não são muito simpáticos à ideia de mexermos nos suprimentos deles.$B$BNão que isso importe muito.$B$BBem, eu também não sou muito simpático à ideia de eles atacarem meus guris. Persiga eles, mate todos... não me importo, só quero me livrar deles.', '', 'Desertor Presa do Dragão derrotado', '', '', '', '', '', '', '', 'Fale novamente com MacKay Barbarruiva no Acampamento de Guerra Gorshak, que fica no Planalto do Crepúsculo.', 0),
(27814, 'ptBR', 'Tudo o que conseguirmos', 'Leve 8 Armas dos Presa do Dragão para Brom Forjatelo no Acampamento de Guerra Gorshak.', 'Ficar pra trás e forjar mais armas? Bá, capaz! Um Forjatelo jamais tem medo de uma guerra! Quem precisa da segurança do lar para fazer armas? Além do mais, tem matéria-prima de sobra por aí. Aquelas armas Presa do Dragão não valem nada, mas podem ser derretidas para se fazer armas de verdade. Me traga 8 armas dos Presa do Dragão para que eu e minha filha possamos forjar armas de verdade a partir delas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Brom Forjatelo.', 0),
(27815, 'ptBR', 'Uma coisinha para os meninos', 'Leve as Armas de Forjatelo para Iain Barbarruiva no Cemitério de Barbarruiva.', 'Tu fez uma limpa no acampamento e deu os recados para os Forjatelo? Nada mau para $gum:uma; $c $gpequerruxo:pequerruxa;. Leve estas coisas para Iain, no Cemitério de Barbarruiva, e ele vai te recompensar se o trabalho for bem feito.', '', '', '', '', '', '', '', '', '', '', 0),
(27816, 'ptBR', 'Pedido pessoal', 'Fale com Quincas Barbarruiva na Patrulha do Barbarruiva.', 'Que pena para os Doyle... É quase um milagre que muitos de nós tenhamos conseguido, então nem dá para considerar uma surpresa.$B$BAqueles otários de Trondamar são uns covardes. Mesmo falando com eles que era um pedido de Quincas, eles não arredam pé da cidade. Mas pelo menos consegui um acordo com os Moore, ou seja, são três clãs unidos.$B$BQuincas queria te ver quando você chegasse. Procure ele na cidade.', '', '', '', '', '', '', '', '', '', '', 0),
(27817, 'ptBR', 'Derrubando o martelo', 'Mate 12 Dobraventos do Crepúsculo e Servias Ventorror usando um dos grifos na Patrulha do Barbarruiva.', 'Graças a você e a Iain, temos cavalgadores suficientes para continuarmos a guerra ao Crepúsculo.$B$BA gente é treinado para lutar enquanto cavalgamos, mas um segundo cavalgador para manusear o Martelo da Tempestade seria mais eficiente. Pensei que tu fosse ficar $ghonrado:honrada; fazendo isso. É melhor se apressar – estamos planejando eliminar o Crepúsculo daquelas pedras flutuantes o quanto antes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Quincas Barbarruiva na Patrulha do Barbarruiva, que fica no Planalto do Crepúsculo.', 0),
(27818, 'ptBR', 'Sinais rastejantes', 'Colete 5 Corações Intactos das Serpentes do Pantanal dos Cervos.', 'Estabeleci-me aqui, muito antes da fundação do Brejo do Goblin, para preparar poções e ter um pouco de paz e quietude. Conheço este pântano como a palma de minha velha e retorcida mão.$B$BA vida selvagem mudou recentemente. Aquelas cobras com asas que você talvez tenha visto no Pantanal dos Cervos são serpentes aladas, e não apareciam por aqui havia eras.$B$BTambém dão ótimos ingredientes se forem da espécie da qual acredito que sejam. Seja $Gbonzinho:boazinha; e extraia alguns de seus corações, está bem?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Baba Globlêbada no Pantanal dos Cervos, que fica no Pântano das Mágoas.', 0),
(27819, 'ptBR', 'TEST - RVM', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27821, 'ptBR', 'Orcs e humanos', 'Mate 8 Guerreiros do Pedregal.', 'Dada a guerra que assola todo o mundo, a última coisa de que precisamos é um acampamento da Horda bem em nosso quintal. Cristarrubra, Floresta do Crepúsculo e até mesmo Elwynn estão a um dia de marcha daqui.$B$BO primeiro ataque foi nosso, e não planejo dar à Horda tempo para se recuperar. Então, considere-se $Gconvocado:convocada;. Pegue uma arma, junte-se ao restante das tropas no Lamaçal Maldito e comece a matar orcs.$B$BVolte aqui quando já tiver feito algum estrago. Quero você de volta $Gvivo:viva;, e isso é uma ordem. $GDispensado:Dispensada;!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Joana Tristalma no Posto Maré do Pântano, que fica no Pântano das Mágoas.', 0),
(27822, 'ptBR', 'Parvos desorientados', 'Mate 5 Peões do Pedregal.', 'Quero que a vitória seja absolutamente segura. Ter mais recursos não basta; precisamos nos certificar de que o inimigo não tenha nada.$B$BAs forças do Pedregal dependem da madeira coletada na floresta circundante. Os peões orcs que cortam as árvores podem não ser guerreiros, mas só o que têm por humanos é o mais puro ódio.$B$BNão tenha piedade, $n. Eu quero esses peões mortos e o fornecimento de madeira totalmente interrompido.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Joana Tristalma no Posto Maré do Pântano, que fica no Pântano das Mágoas.', 0),
(27823, 'ptBR', 'Um anão tem lá suas necessidades', 'Obtenha 15 canecas de Sombrabier.', 'Eu gosto de uma boa escavação como qualquer outro anão de qualidade, tchê, não me leve a mal. É só que... bem, a gente cava demais e bebe de menos, e às vezes eu penso se já não é hora de pendurar a minha pá e voltar pra Altaforja!$b$bMas hoje não. Eu ainda dou conta de uma escavação ou outra.$b$bAqueles anões Ferro Negro, lá no Sítio de Escavação do Pé-de-malho, a norte daqui, fabricam uma cerveja de deixar cachorro louco, bem aqui neste fim de mundo. Será que tu poderia buscar umas pra mim?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Sigrun Derrubaferro na Escavação de Sopravento, que fica nos Ermos.', 0),
(27824, 'ptBR', 'O melhor da festa', 'Procure o tesouro no andar inferior da Fortaleza Angor.', 'Tenho uma proposta pra ti, se tu te interessar.$b$bOs Ferro Negro vieram aqui antes do Durdin chegar com a equipe dele. Isso quer dizer que aqueles xucros entraram nas ruínas titânicas de primeira, antes de todo mundo, e se mandaram com o melhor da festa. Aposto que eles ainda têm uma pilha de tesouros bem guardadinha na Fortaleza Angor, a noroeste daqui.$b$bTu já mostrou que dá conta deixar um anão bem borracho. Agora vai pra fortaleza e trata de pegar o tesouro dos titãs.$b$bEu até iria junto, mas tô mais bêbado que peru de Véu de Inverno.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Sigrun Derrubaferro na Escavação de Sopravento, que fica nos Ermos.', 0),
(27825, 'ptBR', 'Política da boa vizinhança', 'Obtenha 6 pedaços de Carne dos Arrota-pó e 10 cortes de Seda dos Arrota-pó.', 'Estamos mal de suprimentos, $gestranho:estranha;. Com os dragões negros assolando nossas áreas de caça, não temos como conseguir comida.$b$bOs ogros acampados a sudoeste daqui, no entanto, têm exatamente aquilo de que precisamos. Dentro da gruta em que eles moram deve dar para achar bastante carne e aviamentos.$b$bEles podem dar algum trabalho. Fique de olhos abertos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Victoria Dolen na Boca do Dragão, que fica nos Ermos.', 0),
(27826, 'ptBR', 'Boca do Dragão adentro', 'Leve o Ovo de Dragão Negro Purificado para Rhea na Boca do Dragão, que fica nos Ermos.', '<Em completo assombro, Dr. Blam observa o ovo fixamente, pisca algumas vezes, e então olha para você.>$b$bVo... você viu isso? Incrível! O lance do titã deu certo! Com a sua ajuda, claro.$b$bÉ melhor levarmos isso de volta para a Rhea. Ela não está mais na Ravina Lethlor. Parece que o disfarce dela foi pra cucuia quando ela voltou à forma original na frente de todos aqueles dragonetes. Ela está agora no oeste, em um acampamento da Aliança chamado Boca do Dragão.$b$bEla está esperando por você. E pelo ovo.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Rhea na Boca do Dragão, que fica nos Ermos.', 0),
(27827, 'ptBR', 'O veloz, o feroz e o grandalhão', 'Fale com Eric, o Veloz, na Boca do Dragão, que fica nos Ermos.', 'Na minha pressa para escapar da Ravina Lethlor, eu deixei um ponto sem nó: Nyxondra. Ela está à solta e já alarmou a Revoada Negra. Metade da Revoada já está aqui, vasculhando o oeste dos Ermos em busca do ovo.$b$bEu cuido de esconder o ovo. E você cuida dos dragões mais problemáticos – mas não $Gsozinho:sozinha;.$b$bFale com o Eric, do outro lado do acampamento. Ele e os irmãos se juntarão a você.', '', '', '', '', '', '', '', '', '', '', 0),
(27828, 'ptBR', 'Eric, o anão de utilidades', 'Use a Investida do Eric e a Poção de Bolso do Eric.', 'Antes de a gente louquear que nem goblina em liquidação com toda essa matança de dragões, deixa eu te contar como eu luto.$b$bMe chamam de "o veloz" e não é à toa: eu vou em disparada pra cima dos inimigos – capacete na frente, fique sabendo – e deixo eles abobados por alguns segundos. Também levo algumas poções comigo pros momentos difíceis, que não sou besta.$b$bAcho bom a gente praticar a peleja. Vai pro campo de batalha e teste as minhas habilidades.', '', 'Use a Investida do Eric', 'Use a Poção de Bolso do Eric', '', '', '', '', '', '', 'Fale com Eric, o Veloz, nos Ermos.', 0),
(27829, 'ptBR', 'A ira de uma Revoada', 'Mate Kalaran, o Aniquilador, e 4 Soldados Velonero.', 'Olá, $n. Parece que vocês quatro tiveram tempo para se conhecer bem.$b$bEu tenho uma primeira tarefa para você. Kalaran, um antigo dragão negro de poder considerável, juntou-se à caçada pelo ovo que estamos protegendo. Precisamos deter o dragão antes que ele se aproxime muito.$b$bEle e os lacaios estão na Terrasseca, a nordeste da Boca do Dragão. Vá atrás dele e o mate. É bem provável que você precise de uma ajuda dos seus novos aliados enânicos.', '', '', '', '', '', '', 'Rheastrasza', 'Ainda há trabalho por fazer.', 'Rheastrasza', '', 0),
(27830, 'ptBR', 'A caçada continua', 'Vença o General Jirakka, Moldarr e 6 Dragomorfos da Revoada Negra.', 'A Revoada Negra não está de brincadeira. Parece que eles tomaram boa parte da Nova Karrath, o grande assentamento da Horda a noroeste da Boca do Dragão. As tropas de lá estão sob o comando do general Jirakka e do campeão dele, Moldarr. Temos que detê-los.$b$bNós, dragões, não tomamos parte nas rixas entre a Horda e a Aliança, mas eu entendo o risco que vocês estão assumindo ao avançar sobre Nova Karrath. Por favor, heróis... tenham cuidado.', '', '', '', 'Dragomorfos Velonero mortos', '', '', 'Rheastrasza', 'Nosso maior desafio ainda está por vir...', 'Rheastrasza', '', 0),
(27831, 'ptBR', 'A tristeza e a fúria', 'Mate Nyxondra e 12 Filhotes de Nyxondra.', 'Meu maior arrependimento é o tratamento que nós – ou melhor, eu – dei a Nyxondra. Eu a forcei a botar ovos para, depois, fazer experiências com eles. Fiz isso muitas, muitas vezes mesmo.$b$bEu própria sou mãe, então posso imaginar o sofrimento dela.$b$bNão... Não posso ser fraca. Nosso trabalho é, afinal de contas, em prol das futuras gerações de dragões negros. O sacrifício dela foi necessário.$b$bEla está rondando as Ruínas de Karrath, a noroeste de Nova Karrath, louca de ódio. Por favor, heróis... acabem com o sofrimento dela.', '', '', '', '', '', '', 'Rheastrasza', 'Estamos quase no fim.', 'Rheastrasza', '', 0),
(27832, 'ptBR', 'O ninho escondido', 'Fale com Rhea no Ninho Escondido, que fica nos Ermos.', 'Com os principais dragões negros fora dos Ermos, já é seguro realocarmos o ovo. Estarei em um pequeno platô ao norte de Nova Karrath.$b$bVenha me encontrar.', '', '', '', '', '', '', 'Rheastrasza', '', '', '', 0),
(27833, 'ptBR', 'Problemas de meia tonelada', 'Mate 12 Combatentes Arrota-pó. Você pode matar Espancadores Arrota-pó ou Xamãs Arrota-pó.', 'Eu diria que estamos com um problema de dragões, mas eles parecem estar mais interessados na Nova Karrath do que em nosso pequeno acampamento. Ainda assim, meus melhores homens estão concentrados em manter os dragões afastados.$b$bUm problema que permanece, contudo, é o acampamento ôgrico a sudoeste daqui. Parece que um pequeno pelotão de combatentes bateu à porta deles.$b$bNão podemos assistir de braços cruzados enquanto eles nos flanqueiam, soldado. Enfraqueça-os antes que eles o façam conosco.', '', 'Combatentes Arrota-pó mortos', '', '', '', '', '', '', '', 'Fale novamente com Terêncio Tempestade na Boca do Dragão, que fica nos Ermos.', 0),
(27834, 'ptBR', 'Baelog, o canhão de vidro', 'Use o Tiro de Valhalla do Baelog e o Grito de Guerra do Baelog.', 'Antes que eu comece a encher aqueles dragões de flechas, é melhor me apresentar.$b$bEu sou Baelog, o músculo deste grupo. A minha espada morde que nem um crocolisco e as minhas setas cantam que nem uma banshee. O problema é que eu canso em pouco tempo e não aguento tanto quanto meus irmãos.$b$bVocê dá a ordem, e eu mando um tiro certo bem no coração do alvo. Eu também posso animar os meus irmãos, botando todo mundo em um frenesi de combate.$b$bQue tal a gente praticar a peleja?', '', 'Use o Tiro de Valhalla do Baelog', 'Use o Grito de Guerra do Baelog', '', '', '', '', '', '', 'Fale com Baelog nos Ermos.', 0),
(27835, 'ptBR', 'Olaf, o grandalhão', 'Use a Muralha de Proteção do Olaf e o Brado Potente do Olaf.', 'Você pode não ter notado, mas eu sou bem grande pra um anão.$b$bEu cuido pra que meus irmãos não se metam em muita encrenca. Eles são pequenos e não têm um escudo grande que nem o meu. Eu sou grande e aguento uns monstros batendo em mim! Além do mais, com bastante cuidado, eu costumo conseguir fazer eles baterem no meu escudo e não em mim!$b$bEu posso proteger você também. Vamos, é melhor a gente praticar. Vou garantir que os inimigos me ataquem em vez de você.', '', 'Use a Muralha de Proteção do Olaf', 'Use o Brado Potente do Olaf', '', '', '', '', '', '', 'Fale com Olaf nos Ermos.', 0),
(27836, 'ptBR', 'Combatendo a proliferação', 'Destrua 6 Ovos de Rastejantes.', 'Matar as criaturas que infestam o rio não é o bastante, $n.$B$BUma nova geração dessas monstruosidades já ameaça desovar em nossas águas sagradas.$B$BProcure por seus ovos podres e destrua-os.', '', 'Ovo de Rastejante destruído', '', '', '', '', '', '', '', 'Fale novamente com o Sumo Sacerdote Amet na Represa Vir\'naal em Uldum.', 0),
(27837, 'ptBR', 'Invasores na água!', 'Mate 8 Rastejantes das Águas Paradas.', 'Logo depois que as barreiras protetoras de Uldum caíram, o rio Vir\'naal foi afligido por uma terrível corrupção.$B$BNão importa muito se isso ocorreu de forma maliciosa ou acidental. O resultado é o mesmo.$B$BAssim como o rio se tornou nebuloso, o mesmo ocorreu com nossa capacidade de perscrutar o que o futuro nos reserva.$B$BOlhe lá fora, $c. Estas criaturas asquerosas nunca deveriam habitar as águas límpidas do nosso rio.$B$BMate-as para que o rio nos conceda visões novamente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sumo Sacerdote Amet no Dique Vir\'naal, em Uldum.', 0),
(27838, 'ptBR', 'A raiz da corrupção', 'Vá para a nascente do Rio Vir\'naal, no nordeste, e mate a Madrescama Hevna.', 'Você pode ter lidado com os sintomas de nosso problema, $n. Mas tenho pesquisado estas feras asquerosas e seus ovos não são postos aqui por elas.$B$BO fluxo da corrente carrega os ovos até a represa, mas a criatura que os põe fica rio acima.$B$BSiga para nordeste, para a nascente principal do rio, e dê um jeito na raiz da corrupção.', '', '', '', '', '', '', 'Madrescama Hevna', '', '', 'Fale novamente com o Sumo Sacerdote Amet dentro da Represa do Nilos.', 0),
(27839, 'ptBR', 'Armas antigas', 'Recupere os Armamentos Antigos de Tol\'vir.', 'Embora ainda não estejamos formalmente em guerra, os Neferset não hesitam em aprisionar ou matar qualquer um que invada seu território.$B$BO Rei Phaoris se recusa a retaliar, mesmo quando os Neferset usam nossas terras para contrabandear relíquias roubadas das tumbas de nossos ancestrais.$B$BMeus batedores informam que os Neferset estão prestes a transportar uma grande carga de armas saqueadas ao sul daqui.$B$BInstruí os trabalhadores que você recrutou para que o ajudassem. Chame-os com esta corneta quando achar os contrabandistas e recupere as armas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Alto-comandante Kamsés no Posto Avançado da Legião Ramkahen em Uldum.', 0),
(27840, 'ptBR', 'Cristais de draenetista', 'Pegue 5 Cristais de Draenetista no Retiro Alqueivado.', 'Os perdidos que vivem no Retiro Alqueivado se parecem conosco, mas são monstros... Eles enlouqueceram pelos rigores de nossa jornada a Azeroth. Eram nossos irmãos, mas agora residem a oeste, aprisionando ou matando todos que se aventuram por lá.$B$BE eles roubaram algo sagrado para nós – cristais de draenetista.$B$BNão temos poder suficiente para invadirmos o Retiro Alqueivado e tomar de volta a draenetista roubada das suas cabanas e fogueiras, mas, sem esses cristais... nós também poderemos nos perder de nosso caminho.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Holaaru no Posto Maré do Pântano, que fica no Pântano das Mágoas.', 0),
(27841, 'ptBR', 'Mortos de fome', 'Arranje um Pão dos Mortos e entregue-o para o Espírito Goblínico Alegre no cemitério de Orgrimmar.$B$BUse um Cravo-de-defunto Laranja para enxergar o espírito.', 'É bom passar um tempo com os amigos e a família, mas acho que eu exagerei um pouco... Já comi tudo que eles fizeram para mim!$B$BVocê poderia me trazer mais alguns desses deliciosos pães dos mortos? Eu lhe agradeceria muito...$B$BAcho que o Chapa vende a receita.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Espírito Goblínico Alegre em Durotar.', 0),
(27842, 'ptBR', 'A chapa está esquentando', 'Mate Falagrum.', 'Sinto falta dos dias em que legiões e legiões de ogros poderosos marchavam pela Horda. A Aliança, patética como sempre, morria de medo da nossa selvageria. Tomara que esses dias voltem antes que eu bata as botas.$B$BVamos deixar isso de lado por enquanto. Um mago ôgrico, Falagrum, uniu forças com aqueles imbecis da Irmandade Défias e está encarregado das minerações deles. Idiota estúpido! Acabe com ele por mim, pelo espírito e pela glória da Horda!', '', '', '', '', '', '', 'Falagrum', 'Ainda há muito o que fazer, jovem.', 'Ragtha', 'Fale com Ragtha dentro das Minas Mortas.', 0),
(27843, 'ptBR', 'Reforços negados', 'Mate 3 Bruxos do Pedregal.', 'Apenas matar ogros não será suficiente. Eles mesmos estão surgindo no campo de batalha rápido demais.$B$BPreciso que você se infiltre atrás das linhas inimigas e encontre os evocadores deles. Os orcs estão se valendo de bruxos para trazer reforços.$B$BElimine esses bruxos e os portais deverão fechar. Eles não são muitos; um rápido ataque cirúrgico deverá aleijar severamente as tropas inimigas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Joana Tristalma no Posto Maré do Pântano, que fica no Pântano das Mágoas.', 0),
(27844, 'ptBR', 'Traidores!!!', 'Derrote Helix Quebracâmbio.', 'Os goblins que estão trabalhando com os Défias são, oficialmente, traidores do Cartel Borraquilha, da Mão Despedaçada e da própria Horda!$B$BAinda não fui admitida na Mão Despedaçada, por isso preciso ser muito leal ao meu povo. Só que o Helix Quebracâmbio não quis nem saber das associações e está trabalhando na construção de um mastro para a Fortaleza Flutuante Défias. Será que você poderia fazer a gentileza de "se livrar" de Helix por mim e pela Senhorita Transtorno?', '', '', '', '', '', '', 'Helix Quebracâmbio', '', '', 'Fale novamente com Kika Furafundo nas Minas Mortas.', 0),
(27845, 'ptBR', 'Em honra aos mortos', 'Use o Estandarte dos Abatidos para marcar 7 Soldados Rasos Mortos do Posto da Maré.', 'Tomamos mais do que perdemos, mas, ainda assim, perdemos demais. Muitos heróis valentes deram suas vidas pela Aliança. Quero me certificar de que eles receberão as devidas honras, não importa o quão feroz se torne a batalha.$B$BLeve estas bandeiras e deposite uma sobre cada soldado abatido que encontrar. A barreira mágica delas não é muito poderosa, mas é melhor do que nada. Além disso, terei meios para melhor estimar, à distância, quantos dos nossos caíram.', '', 'Soldados rasos marcados', '', '', '', '', '', '', '', 'Fale novamente com Joana Tristalma no Posto Maré do Pântano, que fica no Pântano das Mágoas.', 0),
(27847, 'ptBR', 'Ainda não estão no ponto', 'Destrua o Ceifador de Inimigos 5000.', 'Esses protótipos vão dar uma nova cara ao poder de fogo da Horda – assim que eu terminar de fazer uns ajustes neles! O problema é que as fontes de energia não suportam manobras de combate e carcaças muito grandes – características muito desejáveis quando se trata de lutar com a Aliança.$B$BOs Défias receberam ajuda de goblins traidores, como o Helix, e estão quase terminando o Ceifador de Inimigos 5000, um golem gigante que realmente funciona!$B$BNão podemos deixar que isso vaze para o público de jeito nenhum! Vou perder clientes!', '', '', '', '', '', '', 'Ceifador de Inimigos 5000', '', '', 'Fale novamente com a Senhorita Transtorno nas Minas Mortas.', 0),
(27848, 'ptBR', 'O que vale é a intenção', 'Mate o Almirante Rosnarrasga.', 'Os Défias estão planejando concluir a Fortaleza Flutuante e usá-la para devastar Ventobravo. Não me entenda mal. É uma causa nobre que conquista qualquer coração orc sem nem pensar!$B$BO problema da Vanessa é a execução do plano. O navio não foi bem construído e faltou treinamento para a tripulação. Ah, ainda por cima, há um worgen no meio deles!$B$BO nome do worgen é almirante Rosnarrasga. Precisamos acabar com ele sem misericórdia em nome do Chefe Guerreiro. Lok\'tar ogar!', '', '', '', '', '', '', 'Almirante Rosnarrasga', 'Ele foi um adversário à altura.', 'Ragtha', 'Fale com Ragtha dentro das Minas Mortas.', 0),
(27849, 'ptBR', 'Ataque ao Pedregal', 'Mate 6 Defensores do Pedregal.', 'É agora, $n. Conseguimos um último avanço Pedregal adentro.$B$BNão deveria ser preciso refrescar a memória de ninguém, mas eu o farei mesmo assim: Não somos orcs e não nos transformaremos neles por vingança ou rancor. O Pedregal não queimará para que dancemos sobre as cinzas.$B$BNão, quero que isso seja feito direito. Quero que seja cirúrgico. Mantenha a cabeça erguida e abata qualquer orc armado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Joana Tristalma no Posto Maré do Pântano.', 0),
(27850, 'ptBR', 'O chefão Défias', 'Mate o Chefão Défias.', 'A Mão Despedaçada já está quieta há muitos anos.$B$BAgora chega!$B$BVocê será o pivô do nosso renascimento, $n. Mate a chefe Défias e tome o navio dela em nome da Horda! Vamos dar um trato nele para virar um navio de guerra órquico e usá-lo para exterminar Ventobravo!$B$BOs sobreviventes vão espalhar aos quatro ventos de Azeroth as notícias do nosso poderio e não haverá um ser no mundo que não nos temerá!$B$BVá, $n. A morte de VanCleef superará todos os feitos que você já realizou até hoje.', '', '', '', '', '', '', 'Ragtha', '', '', 'Fale com Ragtha dentro das Minas Mortas.', 0),
(27851, 'ptBR', 'Cortando o abastecimento', 'Colete 5 caixotes de Suprimentos do Pedregal.', 'Nós não estamos devastando Pedregal até que não sobre mais nada, mas eu não quero ter que entrar lá uma segunda vez.$B$BQuero que você colete qualquer suprimento que encontrar na cidade enquanto estiver lá. Sem provisões, nenhum dos guerreiros dele irá durar mais que um dia.$B$BDeve haver caixotes espalhados por toda a cidade.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Joana Tristalma no Posto Maré do Pântano, que fica no Pântano das Mágoas.', 0),
(27852, 'ptBR', 'Orcs e humanos', 'Mate 10 Soldados Rasos da Maré do Pântano.', 'A guerra assola o pântano, $n. Humanos cruéis se estabeleceram ao norte da cidade e deixaram um exército bem no nosso quintal.$B$BNão há nada neste pântano que interesse a eles. O único motivo para estarem aqui é nos atacar, e sem serem provocados. Mas não deixaremos que eles provem do gosto da vitória!$B$BNosso contingente é menor que o deles, e eu preciso que todo orc fisicamente apto vá para o campo de batalha. Vá, e mate quantos humanos puder.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Expedição Ruag no Pedregal, que fica no Pântano das Mágoas.', 0),
(27853, 'ptBR', 'Parvos desorientados', 'Mate 5 Camponeses do Posto Maré do Pântano.', 'Nossos números foram ultrapassados pela Aliança. Tomados pelo medo, eles enviaram um exército para esmagar um único acampamento. Mas não desistiremos!$B$BSem recursos, os soldados deles estarão em desvantagem. Camponeses humanos ocupam-se na floresta do lado externo do Posto Maré do Pântano coletando madeira para a reconstrução de suas muralhas desmoronadiças.$B$BNegue-lhes a madeira e suas vidas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Expedição Ruag no Pedregal, que fica no Pântano das Mágoas.', 0),
(27854, 'ptBR', 'Marés Sombrias', 'Mate 6 Cavaleiros do Posto Maré do Pântano.', 'Sofremos muitas baixas, $n. O Domínio de Malhorrendo enviou ogros da Barreira do Inferno como reforço, mas eles só podem mandar até certo número; a Aliança também os ataca, mesmo enquanto conversamos.$B$BA Aliança contra-atacou nossos ogros com cavaleiros montados, uma estratégia que lhes foi de muita valia durante a Segunda Guerra. Precisaremos de nossos guerreiros mais fortes para mudarmos o rumo da batalha!$B$BVolte ao Lamaçal Maldito, $n, e acabe com esses cavaleiros!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Expedição Ruag no Pedregal, que fica no Pântano das Mágoas.', 0),
(27855, 'ptBR', 'Reforços negados', 'Mate 3 Magos do Posto Maré do Pântano.', 'A Aliança trouxe seus magos para que evoquem mais reforços diretamente de sua fortaleza ao campo de batalha. Eles devem ser impedidos!$B$BSeus números os botam em desvantagem, mas um único portal pode mudar o curso da batalha. Ataque seus magos e desative esses portais!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Expedição Ruag no Pedregal, que fica no Pântano das Mágoas.', 0),
(27856, 'ptBR', 'Em honra aos mortos', 'Use o Estandarte dos Abatidos para marcar 7 Guerreiros Mortos do Pedregal.', 'Muitos guerreiros encontraram a morte para trazer-nos a vitória, $n.$B$BPois esse é o destino de um verdadeiro orc. Eu vi como a Aliança saqueia os cadáveres de nossos guerreiros, agarrando nossas posses como ratos larápios. Eles não violarão nossos heróis caídos neste campo de batalha.$B$BLeve essas proteções com você ao Lamaçal Maldito. Coloque-as sobre o corpos de nossos guerreiros caídos. Estarei observando para saber quantos morreram e para honrar seus sacrifícios. Espero que os espíritos nos ajudem por prestarmos nosso respeito.', '', 'Guerreiros Mortos do Pedregal marcados', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Expedição Ruag no Pedregal, que fica no Pântano das Mágoas.', 0),
(27857, 'ptBR', 'Estamos sendo atacados!', 'Mate 12 Invasores do Posto Maré do Pântano.', 'A Aliança alcançou nossas muralhas!$B$BSuas ações os atrasaram e diminuíram suas forças, $n, mas, no final das contas, estamos em menor número. Esta é nossa última chance. Vitória ou morte...$B$BLute com honra, $n. Já estão dentro de nossas muralhas agora mesmo, enquanto falamos. Afugente esses cachorros humanos do Pedregal, pela Horda!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Comandante de Expedição Ruag no Pedregal, que fica no Pântano das Mágoas.', 0),
(27858, 'ptBR', 'O presente de Rheastrasza', 'Espere enquanto Rhea recupera o ovo do Ninho Escondido.', 'Espere aqui. Vou recuperar o ovo.', '', 'Espere Rhea recuperar o ovo', '', '', '', '', '', '', '', 'Leia o Bilhete de Rhea dentro do Ninho Escondido, nos Ermos.', 0),
(27859, 'ptBR', 'O ovo sobrevive', 'Espere enquanto Rhea recupera o ovo do Ninho Escondido.', '', '', '', '', '', '', '', '', '', '', '', 0),
(27860, 'ptBR', 'Os Perdidos', 'Mate 12 Perdidos no Retiro Alqueivado.', 'Quando o Portal Negro fechou anos atrás, muitos de nós que acabamos nestas terras foram tomados por arrependimento e medo. Em desespero, amaldiçoaram a Luz e voltaram-se para a violência e o ódio.$B$BEssas pobres almas são conhecidas agora como os Perdidos, e são pouco mais que monstros descerebrados que atacam todos à volta. Eles se corrompem mais e mais a cada dia e, como começaram a se extignuir, passaram a sequestrar moradores do Refúgio...$B$BNão temos mais condições de ajudá-los, $n. Por favor, teria a piedade de acabar com o sofrimento deles?', '', 'Perdidos abatidos', '', '', '', '', '', '', '', 'Fale novamente com Holaaru no Posto Maré do Pântano, que fica no Pântano das Mágoas.', 0),
(27861, 'ptBR', 'O Caldeirão da Carnificina: o briguento Olho de Sangue!', 'Vá até a arena do Caldeirão da Carnificina e enfrente Hurp\'derp!', 'Eu estava imaginando quando ‘‘cê daria as caras, $n! Ter $gum campeão:uma campeã; do Ringue de Sangue aqui vai ser um grande chamariz! Vamos ficar ricos, $gparceiro:parceira;! RICOS!$B$BEnfim, isso aqui é um velho poço Presa do Dragão. Não precisamos fazer muita coisa pra deixar o lugar apropriado pra gente usar. Fiz uns testes e consegui batedores de toda Azeroth para se juntarem à carnificina. Tá na hora de fazer ouro!$B$BVocê conhece a manobra, $n. Quando estiver $gpronto:pronta; me avise pra que o show possa começar!', 'Hurp\'derp derrotado', '', '', '', '', 'Hurp\'derp derrotado', '', '', '', 'Fale novamente com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27862, 'ptBR', 'O Caldeirão da Carnificina: o briguento Olho de Sangue!', 'Vá até a arena do Caldeirão da Carnificina e enfrente Hurp\'derp!', 'Bem, bem... se não é $go antigo campeão:a antiga campeã; da angústia, $n! Prevejo rios de dinheiro agora que ‘‘cê tá por aqui! Vamos deitar e rolar, chapa! RIQUÍSSIMOS!$B$BEnfim, isso aqui é um velho poço Presa do Dragão. Não precisamos fazer muita coisa pra deixar o lugar apropriado pra nosso uso. Fiz uns testes e consegui batedores de toda Azeroth pra se juntarem à carnificina. Tá na hora de fazer ouro!$B$B\'Cê conhece a manobra, $n. Quando estiver $gpronto:pronta; me avise pra que o show possa começar!', 'Hurp\'derp derrotado', '', '', '', '', 'Hurp\'derp derrotado', '', '', '', 'Fale novamente com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27863, 'ptBR', 'O Caldeirão da Carnificina: o briguento Olho de Sangue!', 'Vá até a arena do Caldeirão da Carnificina e enfrente Hurp\'derp!', 'Vou te contar, isso aqui é bem diferente dos Morros Ondulantes de Nagrand ou da arena sangrenta em Zul\'Drak... mas sabe como é, eu tô onde tá o ouro! Então seja $gbem-vindo:bem-vinda; ao Planalto, amizadinha.$B$BVocê é $gnovo:nova; no pedaço, por isso vou te falar como é que a banda toca aqui. Eu sou o promotor de lutas e este troll rabugento aqui é Wodin, meu guarda-costas. E a atração é tu $gmermo:merma;. Quando cê quiser lutar, me avisa que eu preparo tudo.$B$BSe cê já estiver $gpronto:pronta; e com um grupo de amigos, a gente já pode mandar ver! E aí?', 'Hurp\'derp derrotado', '', '', '', '', 'Hurp\'derp derrotado', 'Hurp\'derp', 'Ajudante de Gurg.', 'Wodin', 'Fale novamente com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27864, 'ptBR', 'O Caldeirão da Carnificina: os mortais Presa do Dragão!', 'Vá até a arena do Caldeirão da Carnificina e derrote Torg Esfoladraco!', 'Você vai se amarrar nessa! Os Presa do Dragão ouviram que você entrou na arena e não querem de jeito nenhum que você saia de lá.$B$BTá na hora de dar uma bela lição $r nos orcs! Me avisa quando você estiver $gpreparado:preparada;!', 'Torg Esfoladraco derrotado', '', '', '', '', 'Torg Esfoladraco derrotado', 'Torg Esfoladraco', 'Não há amor como o amor de um troll.', 'Wodin', 'Fale novamente com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27865, 'ptBR', 'O Caldeirão da Carnificina: o Martelo Feroz teimoso!', 'Vá até a arena do Caldeirão da Carnificina e enfrente Súlio Rompedor!', 'Você vai se amarrar nessa! Os Martelo Feroz ouviram que você entrou na arena e não querem de jeito nenhum que você saia de lá.$B$BTá na hora de dar uma bela lição $r nos anões! Me avisa quando você estiver $gpreparado:preparada;!', 'Súlio Rompedor derrotado', '', '', '', '', 'Súlio Rompedor derrotado', 'Súlio Rompedor', 'Não há amor como o amor de um troll.', 'Wodin', 'Fale novamente com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27866, 'ptBR', 'O Caldeirão da Carnificina: a criação de Calder!', 'Vá até a arena do Caldeirão da Carnificina e enfrente o Remendão!', 'Carne e sangue, a próxima luta vai deixar a multidão gemendo de qualquer jeito. Calder Gris juntou partes dos corpos de desafiadores vencidos e construiu com elas um lutador perfeito.$B$BEsta coisa é a última palavra na arte de costurar corpos de combatentes. Uma magnífica mistura de destroços e restos de monstruosidades. Já tá $Gpronto:pronta; pra luta? Porque eu já! É só me avisar e a gente parte pro agito!', 'Remendão derrotado', '', '', '', '', 'Remendão derrotado', 'Remendão', 'Wodin sabe bem como você gosta.', 'Wodin', 'Fale novamente com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27867, 'ptBR', 'O Caldeirão da Carnificina: o senhor da Estripação!', 'Vá até a arena do Caldeirão da Carnificina e enfrente o Lorde Geoffery Tulvan!', 'Essa vai te dar trabalho, camarada. Temos um guerreiro experiente aqui! Ele veio de Guilnéas e está aqui para provar que é o melhor guerreiro destes cantos de Azeroth.$B$BÉ melhor você se aprumar porque as coisas vão esquentar por aqui. Me avisa quando você estiver $gpronto:pronta; para martelar.', 'Lorde Geoffery Tulvan derrotado', '', '', '', '', 'Lorde Geoffery Tulvan derrotado', 'Lorde Geoffery Tulvan', 'Há anos na estrada e sem trocar uma peça de roupa.', 'Wodin', 'Fale novamente com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27868, 'ptBR', 'O Caldeirão da Carnificina: o terror do Crepúsculo!', 'Vá até a arena do Caldeirão da Carnificina e enfrente Escoriabrasa, o Devorador!', 'Agora teremos alguém que ‘‘cê vai amar odiar. No começo, fiquei na dúvida se eu deveria deixar ele entrar na arena, mas briga é briga! E quem sou eu pra dispensar grana certa?!?$B$BEsse cara veio da Cidadela do Crepúsculo e é dono de um soco estrondoso. É melhor ‘‘cê se mexer rápido e ficar $gesperto:esperta;! Me avise quando estiver $gpronto:pronta; para a ação.', 'Escoriabrasa, o Devorador, derrotado', '', '', '', '', 'Escoriabrasa, o Devorador, derrotado', 'Escoriabrasa, o Devorador', 'Balada do troll.', 'Wodin', 'Fale novamente com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(27869, 'ptBR', 'O dragão e o templo', 'Fale com Lorde Itharius no topo dos degraus externos do templo de Atal\'Hakkar.', 'Essas serpentes devem ter vindo do templo de Atal\'Hakkar. Eu já suspeitava...$B$BNão muitos dias atrás, um visitante parou por aqui e me pediu que ficasse de olho aberto para coisas assim. Um elfo chamado Itharius. Tenho certeza de que ele não pensou que eu pudesse enxergar através de sua forma... ele era um dragão verde disfarçado e imbuído do intuito de ajudar seus irmãos caídos, sem dúvida.$B$BEle pode, muito bem, estar aprontando alguma coisa. Itharius partiu rumo ao próprio templo. Talvez seja melhor você procurar ele por lá. Coisas sombrias estão por vir.', '', '', '', '', '', '', '', '', '', '', 0),
(27870, 'ptBR', 'Rumo ao Posto Maré do Pântano', 'Fale com Joana Tristalma no Posto Maré do Pântano.', 'Independentemente de você me ajudar ou não dentro do templo, seu povo deve ser informado sobre o que se passa aqui.$B$BAo norte do templo, humanos da sua Aliança mortal construíram o que chamam de Posto Maré do Pântano. Eles guerreiam com a Horda ao longo do pântano, um conflito avassalador que prevejo só piorar.$B$BNão é meu papel interferir em incidentes mortais, $n. Apenas peço-lhe que alerte seu povo sobre o que espreita no interior do templo.', '', '', '', '', '', '', '', '', '', '', 0),
(27871, 'ptBR', 'Rumo ao Pedregal', 'Fale com o Comandante de Expedição Ruag no Pedregal, que fica no Pântano das Mágoas.', 'Independentemente de me ajudar ou não dentro do templo, seu povo deve ser informado sobre o que se passa aqui.$B$BA sudeste do templo, está a cidade do Pedregal, da Horda. Os orcs de lá guerreiam contra os humanos recém-chegados ao pântano, um conflito devastador que só vejo piorar.$B$BNão é meu papel interferir em incidentes mortais, $n. Apenas peço que alerte seu povo sobre o que espreita no interior do templo.', '', '', '', '', '', '', '', '', '', '', 0),
(27872, 'ptBR', 'Centro de Tortolla completo', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27873, 'ptBR', 'Centro de Aviana completo', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27874, 'ptBR', 'O legado de Aviana', 'Encontre Choluna no Santuário de Aviana, no Monte Hyjal.', 'Precisamos da sua experiência em outro lugar, $n.$B$BO Santuário de Aviana, lar dos Druidas do Gadanho, fica a sudoeste da Árvore do Mundo. Aviana é a matriarca de todas as criaturas aladas e deu a própria vida por este mundo há dez mil anos.$B$BEstou sentindo que o santuário dela corre perigo, bem como os druidas que o guardam. Procure Choluna, uma das mais sábias druidas aladas, no coração do santuário.', '', '', '', '', '', '', '', '', '', 'Encontre Choluna no Santuário de Aviana, no Monte Hyjal.', 0),
(27875, 'ptBR', 'Florrogo', 'Colete 10 brotos de Florrogo do Lodaçal Mutante.', 'Passei anos trabalhando em busca de uma cura para a calamidade dos degradados. As energias vis que os corromperam não se restringiram a desfigurá-los, mas roubaram-lhes o conforto da Luz. Eles não conseguem sentir seu calor.$B$BNão posso permitir que Magtoor se vá nas trevas, $n. Antes dele piorar, eu estava estudando o florrogo, uma flor que cresce no Lodaçal Mutante. Ela germina forte mesmo na mais escura sombra. Peço enfaticamente a ti que coletes essas flores para mim, pelo bem de Magtoor.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o anacoreta Avuun no Refúgio, que fica no Pântano das Mágoas.', 0),
(27876, 'ptBR', 'Segredos do lodo', 'Colete 10 amostras de Lama Envigorada de Bolhas do Lodaçal Mutante.', 'O Lodaçal Mutante é assim chamado por conta de um fenômeno único. Por ação de alguma força, os sedimentos extremamente finos revolvem-se por si, movendo-se como se dotados de vida própria.$B$BInicialmente, tive receio de que seria uma força degradante, mas meus estudos apontam para o contrário; qualquer que seja a energia que fortifica este solo, ela é de natureza positiva. É possível que uma vida tão vibrante possa ser concedida aos degradados de maneira a despertar aquilo que, um dia, eles foram.$B$BA lama pode não ver sua coleta com generosidade, $n. Contudo, por favor, ajuda-nos a coletá-la.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Anacoreta Avuun no Refúgio, que fica no Pântano das Mágoas.', 0),
(27877, 'ptBR', 'A liga dos idiotas', 'Obtenha 15 Cabeças de Ferro Negro.', 'Preciso da sua ajuda em um projetinho meu, $n. Ele se enquadra em um campo que gosto de chamar de "arqueologia defensiva".$b$bEu gosto de enterrar objetos não mágicos em lugares bem fáceis para aqueles idiotas da Aliança pensarem que encontraram artefatos de valor.$b$bHum... Alguns anões Ferro Negro perambulam pelo Sítio de Escavação do Pé-de-malho e pela Fortaleza Angor, a norte. Traga as cabeças deles para mim. Sim, é isso mesmo, as cabeças.$b$bUma vez tirada a carne, podemos usar os crânios para interferir no trabalho dos anões.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lídia Rubrossol no Posto Vigília de Sangue, que fica nos Ermos.', 0),
(27878, 'ptBR', 'Aquisição forçada', 'Procure o tesouro no andar inferior da Fortaleza Angor.', 'Tenho uma proposta para você, se lhe interessar.$b$bOs anões Ferro Negro vieram aqui muito antes de nós. Isso quer dizer que eles entraram nas ruínas titânicas assim que foram encontradas, antes de todo mundo, e saquearam os objetos mais valiosos. Aposto que o butim ainda está guardado na Fortaleza Angor, a noroeste daqui.$b$bQuero que você encontre o tesouro... e o roube.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Aoren Rubrossol no Posto Vigília de Sangue, que fica nos Ermos.', 0),
(27879, 'ptBR', 'Política da boa vizinhança', 'Obtenha 6 pedaços de Carne dos Arrota-pó e 10 cortes de Seda dos Arrota-pó.', 'Estamos mal de suprimentos, $gestranho:estranha;. Com os dragões negros assolando nossas áreas de caça, não temos como conseguir comida.$b$bOs ogros acampados a sul daqui, no entanto, têm exatamente aquilo de que precisamos. Dentro da gruta em que eles moram deve dar para achar bastante carne e aviamentos.$b$bEles podem dar algum trabalho. Fique de olhos abertos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Aidan Ventoestival em Nova Karrath, que fica nos Ermos.', 0),
(27880, 'ptBR', 'Problemas de meia tonelada', 'Mate 12 Combatentes Arrota-pó. Você pode matar Espancadores Arrota-pó ou Xamãs Arrota-pó.', 'Os meus brutos já controlaram o problema com os dragões. Além do mais, não posso deixar que $gum:uma; $c afoit$go:a; se intrometa e arruíne os nossos planos de batalha.$b$bVocê quer trabalho? Tudo bem, vou dar trabalho para você. Investigue o acampamento ôgrico a sudoeste daqui. Pelo que ouvi, um pequeno pelotão de combatentes apareceu do lado de fora do muquifo deles.$b$bNão podemos esperar sentados enquanto eles nos flanqueiam, soldado... especialmente enquanto ainda estivermos enrolados com os dragões negros. Enfraqueça-os antes que eles o façam conosco.', '', 'Combatentes Arrota-pó mortos', '', '', '', '', '', '', '', 'Fale novamente com Gorn em Nova Karrath, que fica nos Ermos.', 0),
(27881, 'ptBR', 'Posto Vigília de Sangue', 'Fale com o Avaliador-mor Tae\'thelan Vigiassangre no Posto Vigília de Sangue, que fica nos Ermos.', 'Eu tive uma ideia que pode não dar certo. Acontece que, felizmente, fazer dar certo é uma das minhas especialidades.$b$bA norte daqui, o Relicário desenterrou um novo conjunto de ruínas. Se tem alguma coisa mais velha e sábia do que dragões, são os titãs. Diabos, eu ouvi rumores de que os titãs CRIARAM os dragões.$b$bFale com o avaliador-mor Tae\'thelan Vigiassangre no acampamento a nordeste daqui. Ele terá mais informações do que eu sobre esses titãs.$b$bLembra o que eu disse? Pode não dar certo.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Avaliador-mor Tae\'thelan Vigiassangre no Posto Vigília de Sangue, que fica nos Ermos.', 0),
(27882, 'ptBR', 'A questão aqui não é a história, é o poder', 'Obtenha um Cálice Quebrado, um Vaso Empoeirado, um Hieroglifo Terreno e uma Ferramenta Trogg.', 'A Liga dos Exploradores pode até saber escavar. O que eles não sabem é USAR os artefatos desenterrados. Eles guardam os tesouros em museus empoeirados em vez de usar os objetos poderosos para aquilo que servem.$b$bOs anões são tolos mas, felizmente, morrem com facilidade.$b$bEles estão escavando as paredes do cânion a norte daqui. Tome o que você puder daqueles dedinhos de salsicha e volte aqui.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Avaliador-mor Tae\'thelan Vigiassangre no Posto Vigília de Sangue, que fica nos Ermos.', 0),
(27883, 'ptBR', 'O peão do guardião', 'Encontre um uso para o Peão do Guardião dentro da Tumba dos Observadores, que fica nos Ermos.', 'Um dos poucos itens de valor que conseguimos roubar das ruínas é esta pequena estátua de jade.$b$bAcreditamos que a estátua seja algum tipo de chave, mas não conseguimos descobrir o que ela abre. Assim, ela não tem utilidade para mim.$b$bTalvez você tenha mais sorte com ela.', '', '', '', '', '', '', '', '', '', '', 0),
(27884, 'ptBR', 'O peão da sentinela', 'Encontre um uso para o Peão da Sentinela dentro da Tumba dos Observadores, que fica nos Ermos.', 'Encontramos esta pequena estátua vermelha junto ao cadáver de um dos arqueólogos da Liga dos Exploradores. Infelizmente, não fomos nós que o matamos. Esse mérito cabe à vida selvagem local.$b$bA estátua é bem trabalhada, mas aparentemente desprovida de poder mágico. Você pode usá-la para qualquer fim que julgar necessário.', '', '', '', '', '', '', '', '', '', '', 0),
(27885, 'ptBR', 'O jogo do guardião', 'Complete o Jogo do Guardião teleportando os Peões do Guardião para posições voltadas para dentro.', 'Você vê a estátua se dividir em duas, quatro, e então oito estátuas idênticas em formação quadrada.$b$bVocê escuta uma voz, não pelos seus ouvidos, mas no fundo da sua mente:$b$b   "Um guardião de verdade não olha PARA FORA em busca de sinais de perigo.$b   Um guardião de verdade mantém os olhos voltados PARA DENTRO, sempre concentrado em proteger as suas presas."$b$bSerá que isso é algum tipo de charada?', '', 'Jogo do guardião completo', '', '', '', '', '', '', '', '', 0),
(27886, 'ptBR', 'O jogo da sentinela', 'Complete o Jogo da Sentinela conectando as duas estátuas vermelhas.', 'Você coloca a estátua no devido lugar, e várias outras aparecem na sala. Também surge mais uma estátua cor de rubi, em um pequeno cercado no lado oposto do recinto. Você ouve uma voz:$b$b   "A Sentinela observa.$b   A Sentinela protege.$b   A visão da Sentinela nunca falha."$b$bA estátua vermelha no outro lado da sala parece importante. Talvez você devesse tentar conectar as duas estátuas cor de rubi.', '', 'Jogo da sentinela completo', '', '', '', '', '', '', '', '', 0),
(27887, 'ptBR', 'Protetores ancestrais', 'Investigue o Guardião e a Sentinela.', 'Você ouviu bastante barulho vindo da câmara central da tumba. Aquelas duas estátuas grandes lhe pareceram terrivelmente suspeitas.', '', 'Guardião investigado a fundo', 'Sentinela investigada a fundo', '', '', '', '', '', '', 'Inspecione o Tesouro dos Titãs dentro da Tumba dos Observadores, que fica nos Ermos.', 0),
(27888, 'ptBR', 'Fale novamente com Blam', 'Leve o Olho dos Observadores para o Dr. Hieronymus Blam na Ruína de Agmundo, que fica nos Ermos.', 'Dentro da arca, você encontra um pequeno dispositivo circular repousando sobre uma almofada.$b$bSe há algum artefato titânico a ser encontrado nesta tumba, é este. Você decide levá-lo de volta para o Dr. Blam.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Dr. Hieronymus Blam na Ruína de Agmundo, que fica nos Ermos.', 0),
(27889, 'ptBR', 'Nova Karrath', 'Leve o Ovo de Dragão Negro Purificado para Rhea, em Nova Karrath, que fica nos Ermos.', ' <Em completo assombro, Dr. Blam observa o ovo fixamente, pisca algumas vezes, e então olha para você.>$b$bVo... você viu isso? Incrível! O lance do titã deu certo! Com a sua ajuda, claro.$b$bÉ melhor levarmos isso de volta para a Rhea. Ela não está mais na Ravina Lethlor. Parece que o disfarce dela foi pra cucuia quando ela voltou à forma original na frente de todos aqueles dragonetes. Ela está agora no oeste, em um grande assentamento da Horda chamado Nova Karrath.$b$bEla está esperando por você. E pelo ovo.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Rhea em Nova Karrath, que fica nos Ermos.', 0),
(27890, 'ptBR', 'Os cachorros maus', 'Fale com Amakkar em Nova Karrath, que fica nos Ermos.', 'Na minha pressa para escapar da Ravina Lethlor, eu deixei um ponto sem nó: Nyxondra. Ela está à solta e já alarmou a Revoada Negra. Metade da Revoada já está aqui, vasculhando o oeste dos Ermos em busca do ovo.$b$bEu cuido de esconder o ovo. E você cuida dos dragões mais problemáticos – mas não $Gsozinho:sozinha;.$b$bEu contratei uns mercenários para ajudar você. Eles estão dentro desta estalagem.', '', '', '', '', '', '', '', '', '', '', 0),
(27891, 'ptBR', 'Amakkar, o coringa', 'Use o Golpe no Rim de Amakkar e a Poção de Bolso de Amakkar.', 'Antes que a gente se empolgue demais com a matança de dragões, vamos conversar um pouco sobre como eu luto.$b$bEu não sou forte e atlético como esses outros dois, mas tenho alguns truques na manga. Ao seu comando, eu sei atordoar inimigos para que fiquem parados. Também carrego algumas poções para os momentos difíceis.$b$bAcho bom treinarmos antes. Vá para o campo de batalha e você verá como é lutar com um verdadeiro orc.', '', 'Use o Golpe no Rim de Amakkar', 'Use a Poção de Bolso de Amakkar', '', '', '', '', '', '', 'Fale com Amakkar nos Ermos.', 0),
(27892, 'ptBR', 'Jurrix, o Atacante', 'Use o Impacto Abrasador de Jurrix e a Distorção Temporal de Jurrix.', 'Ah, você quer conversar? Está bem.$b$bEu sou Jurrix, o único mercenário por aqui com algum miolo. O único daqui que ataca com maldade, também. Eu só mantenho esses escudos de carne por perto para que evitem que eu seja morto.$b$bEscute, você é $go:a; chefe desta operação. Você manda, e eu lanço uma bola de fogo bem no coração do seu alvo. Se as coisas começarem a esquentar demais, posso até distorcer um pouco o tempo para que você ataque mais algumas vezes.$b$bAcho melhor a gente praticar um pouco.', '', 'Use o Impacto Abrasador de Jurrix', 'Use a Distorção Temporal de Jurrix', '', '', '', '', '', '', 'Fale com Jurrix Cristalba nos Ermos.', 0),
(27893, 'ptBR', 'Gargal, o beemote', 'Use a Muralha de Escudos do Gargal e Brado Potente do Gargal.', 'Você pode não ter notado, mas eu sou bem grande para um orc.$b$bEu cuido pra que meus irmãos não se metam em muita encrenca. Eles são pequenos e não têm um escudo grande que nem o meu. Eu sou grande e aguento uns monstros batendo em mim! Além do mais, com bastante cuidado, eu costumo conseguir fazer eles baterem no meu escudo e não em mim!$b$bEu posso proteger você também. Vamos, é melhor a gente praticar. Vou garantir que os inimigos me ataquem em vez de você.', '', 'Use a Muralha de Escudos do Gargal', 'Use o Brado Potente do Gargal', '', '', '', '', '', '', 'Fale com Gargal nos Ermos.', 0),
(27894, 'ptBR', 'A ira de uma Revoada', 'Mate Kalaran, o Aniquilador, e 4 Soldados Velonero.', 'Olá, $n. Parece que vocês quatro tiveram tempo para se conhecer bem.$b$bEu tenho uma primeira tarefa para você. Kalaran, um antigo dragão negro de poder considerável, juntou-se à caçada pelo ovo que estamos protegendo. Precisamos deter o dragão antes que ele se aproxime muito.$b$bEle e os lacaios estão na Terrasseca, ao leste de Nova Karrath. Vá atrás dele e o mate. É bem provável que você precise de uma ajuda dos seus novos aliados mercenários.', '', '', '', '', '', '', 'Rheastrasza', 'Ainda há trabalho por fazer.', 'Rheastrasza', '', 0),
(27895, 'ptBR', 'A caçada continua', 'Vença o General Jirakka, Moldarr e 6 Dragomorfos da Revoada Negra.', 'A Revoada Negra não está de brincadeira. Como você já deve ter percebido, eles tomaram uma grande parte de Nova Karrath. As tropas estão sob o comando do general Jirakka e do campeão dele, Moldarr. Temos que detê-los.', '', '', '', 'Dragomorfos Velonero mortos', '', '', 'Rheastrasza', 'Nosso maior desafio ainda está por vir...', 'Rheastrasza', '', 0),
(27896, 'ptBR', 'A tristeza e a fúria', 'Mate Nyxondra e 12 Filhotes de Nyxondra.', 'Meu maior arrependimento é o tratamento que nós – ou melhor, eu – dei a Nyxondra. Eu a forcei a botar ovos para, depois, fazer experiências com eles. Fiz isso muitas, muitas vezes mesmo.$b$bEu própria sou mãe, então posso imaginar o sofrimento dela.$b$bNão... Não posso ser fraca. Nosso trabalho é, afinal de contas, em prol das futuras gerações de dragões negros. O sacrifício dela foi necessário.$b$bEla está rondando as Ruínas de Karrath, a noroeste de Nova Karrath, louca de ódio. Por favor, heróis... acabem com o sofrimento dela.', '', '', '', '', '', '', 'Rheastrasza', 'Estamos quase no fim.', 'Rheastrasza', '', 0),
(27897, 'ptBR', 'O Ninho Escondido', 'Fale com Rhea no Ninho Escondido, que fica nos Ermos.', 'Com os principais dragões negros fora dos Ermos, já é seguro realocarmos o ovo. Estarei em um pequeno platô ao norte de Nova Karrath.$b$bVenha me encontrar.', '', '', '', '', '', '', 'Rheastrasza', '', '', '', 0),
(27898, 'ptBR', 'O presente de Rheastrasza', 'Espere enquanto Rhea recupera o ovo do Ninho Escondido.', 'Espere aqui. Vou recuperar o ovo.', '', 'Espere Rhea recuperar o ovo', '', '', '', '', '', '', '', 'Leia o Bilhete de Rhea dentro do Ninho Escondido, nos Ermos.', 0),
(27899, 'ptBR', 'Aquele brilho nos olhos', 'Fale com Harrison Jones no Obelisco do Sol.', 'Se você está procurando o Harrison, ele acabou de sair.$b$bEle estava falando sem parar sobre a última descoberta e como tudo estava começando a fazer sentido.$b$bSei lá... Para mim, ele não estava fazendo sentido algum.$b$bTentei convencê-lo a ficar aqui e simplesmente desfrutar de alguns pores-do-sol comigo, mas não há como convencê-lo quando ele está com aquele brilho nos olhos.$b$bSerá que você estaria dispost$go:a; a ver como ele está?$b$bEle seguiu em direção àquele grande monólito, ao sul daqui.', '', '', '', '', '', '', '', '', '', '', 0),
(27900, 'ptBR', 'Deixe esse cara comigo', 'Mate 10 Soldados Aéreos de Schnottz.', 'Bem na hora, $n.$b$bParece que não sou o único interessado nestes obeliscos, e esses sujeitos não estão aqui para comparar anotações...$b$bAcho que você pode deixar esse cara comigo.$b$bTalvez você possa cuidar de alguns dos amigos dele antes que eles cheguem até aqui.', '', 'Soldados Aéreos de Schnottz mortos', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Obelisco do Sol.', 0),
(27901, 'ptBR', 'Eles não sabem o que têm aqui', 'Crie o Dispositivo de Ativação Titânico.', 'Escute, $n. Não tenho muito tempo para conversa agora.$b$bEsses caras estão escavando relíquias deste local e pegando pedaços da tecnologia ancestral de que precisamos!$b$bPreciso que você verifique os caixotes deles em busca de um dispositivo de ativação ancestral. Os oficiais devem ter os códigos para abri-los.$b$bDepressa!$b$bNão podemos permitir que eles carreguem os aviões com essas coisas!', '', '', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Obelisco do Sol.', 0),
(27902, 'ptBR', 'A Fonte Clara', 'Colete 6 Grânulos de Fonte Clara dos Elementais da Fonte Clara.', 'Magtoor falou-me do xamanismo praticado pelos degradados. O grande Nobambo disse, uma vez, que a trilha dos elementos pode, de certa forma, ser outro caminho rumo à Luz.$B$BApenas espero que haja alguma verdade nisso. Os elementais que se reúnem próximo à Fonte Clara, ao sul, são uma fonte de água realmente imaculada. Eles podem ser caóticos e violentos, mas a água pura deles extraída será o canal perfeito para a bênção da Luz.$B$BPor favor, traz-me essa água, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o anacoreta Avuun no Refúgio, que fica no Pântano das Mágoas.', 0),
(27903, 'ptBR', 'Ignição', 'Recupere a Lente do Sol.', 'Este cara simplesmente não cai!$b$bVocê está indo muito bem, garot$go:a;. Resta apenas uma coisa a fazer.$b$bDe acordo com a minha pesquisa, deve haver uma estátua titânica lá embaixo. Use o dispositivo para ativá-la e, então, quebrá-la.$b$bSe a minha teoria estiver correta, a estátua guarda a chave para a reativação deste obelisco.', '', '', '', '', '', '', '', '', '', 'Coloque a Lente do Sol na Plataforma Elevada, que fica na Câmara do Sol.', 0),
(27904, 'ptBR', 'Sopro enevoado', 'Colete 5 Cristais Fumegantes de Diabretes Fumegantes.', 'Os capetas são espíritos florestais que vagueiam, a leste, pelo Vale Nebuloso. Apesar de assemelharem-se a diabretes, não encontrei qualquer vestígio demoníaco naqueles que estudei. Eles são, até onde sei, incorruptos.$B$BAqueles que habitam o vale movem-se como um com o vento, evocando rajadas de brisa a seu bel-prazer. Esse ar puro pode ser incorporado ao meu remédio para o pobre Magtoor.$B$BPor favor, $n, coleta os cristais fumegantes de dentro dos corpos dos diabretes para mim. Devo exaurir qualquer possibilidade de cura.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Anacoreta Avuun no Refúgio, que fica no Pântano das Mágoas.', 0),
(27905, 'ptBR', 'Artilheiro de cauda!', 'Use a torreta de cauda para defender o Bombardeiro de Schnottz.', 'Tudo bem, já amaciei esse sujeito. Que tal você me ajudar a acabar com ele?$b$bTenho um plano para a nossa fuga, mas vamos precisar de muita coragem e um pouco de sorte.$b$bVocê está dispost$go:a;, $n?$b$bEntão me siga...', '', 'Fuga do Obelisco do Sol com sucesso', '', '', '', '', '', '', '', 'Defenda o Bombardeiro de Schnottz até que o Harrison possa aterrissar.', 0),
(27906, 'ptBR', 'Nika Cicatriz-de-sangue', 'Fale com Nika Cicatriz-de-sangue no Entroncamento da Lança Lascada.', 'Há muito trabalho a ser feito para nos recuperarmos do ataque e nos prepararmos para o próximo. Precisarei da coordenação de todos nossos batedores.$B$BNika Cicatriz-de-sangue é nossa melhor batedora, treinada nos inóspitos Ermos. Ela foi enviada ao Entroncamento da Lança Lascada, a oeste, para vigiar a atividade da Aliança.$B$BVá até Nika, $n. Conte a ela o que ocorreu no Pedregal. Ajude-a de qualquer forma que ela precisar.', '', '', '', '', '', '', '', '', '', '', 0),
(27907, 'ptBR', 'Florrogo', 'Colete 10 brotos de Florrogo do Lodaçal Mutante.', 'Fui arruinada, $c. Depositei minha força em Helgrum e, agora, ela se esvai por suas feridas abertas. Ferimentos demasiadamente profundos para serem curados, carne que recusa-se a fechar.$B$BEle murmura temeroso, consumido pela febre e pela dor. Não posso deixá-lo só. Não agora. Por favor, é com vergonha que peço a você que colete ervas para mim.$B$BOs florrogos que crescem no pântano são um velho remédio para alívio. Com uma quantidade suficiente, o sofrimento dele pode ser amenizado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nika Cicatriz-de-sangue no Entroncamento da Lança Lascada, que fica no Pântano das Mágoas.', 0),
(27908, 'ptBR', 'Segredos do lodo', 'Colete 10 amostras de Lodo Revigorado de Globântanos Cambiantes.', 'As feridas de Helgrum inflamam-se neste ar pantanoso. Elas incham e gotejam, enchendo seus momentos finais de sofrimento. Devo ter algo para cobri-las.$B$BOs espíritos movem-se por este lodo. Habitam a própria lama, empurrando-a em bolos de solo fino que ganham vida própria.$B$BOs espíritos da lama fresca e pura oferecerão algum conforto a ele. Por favor, colete-a para mim, pois não posso abandoná-lo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nika Cicatriz-de-sangue no Entroncamento da Lança Lascada, que fica no Pântano das Mágoas.', 0),
(27909, 'ptBR', 'A Fonte Clara', 'Colete 8 Partículas de Fonte Clara dos Elementais da Fonte Clara.', 'A respiração de Helgrum desacelera-se. Aproxima-se a hora dele.$B$BPreciso de água. Elementais vagam pelos açudes da Caverna Fonte Clara. A água que deles flui é a mais pura deste pântano.$B$BMesmo que eu pudesse arriscar sair do lado de Helgrum, meu machado tremeria em minha mão. Mais uma vez, devo pedir a você que tenha piedade de mim, pelo conforto dele. Traga-me as partículas dos elementais para que a última água por ele sorvida seja pura e refrescante.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nika Cicatriz-de-sangue no Entroncamento da Lança Lascada, que fica no Pântano das Mágoas.', 0),
(27910, 'ptBR', 'Arrependimentos derradeiros', 'Extraia a pele do Dente-de-sombra.', 'Se estou reduzida a rebaixar-me, posso muito bem pedir tudo que for possível. Há um último favor que peço de você, mais uma tarefa pela qual implora uma orquisa envergonhada.$B$BHelgrum tinha uma presa predileta. Dente-de-sombra, devorador de ogros, a grande pantera do Vale Nebuloso. Ele jamais tinha a auto-indulgência de permitir-se seguir seu rastro. Mesmo querendo muito caçar, nossos afazeres enquanto batedores eram importantes demais.$B$BSe ele não pode caçar o Dente-de-sombra neste mundo, ele pode caçar a fera no outro. Leve a presa a ele; traga-me a pele do Dente-de-sombra.', '', '', '', '', '', '', 'Dente-de-sombra', '', '', 'Fale novamente com Nika Cicatriz-de-sangue no Entroncamento da Lança Lascada, que fica no Pântano das Mágoas.', 0),
(27911, 'ptBR', 'O último suspiro', 'Testemunhe os últimos momentos de Helgrum.', 'Ele está agitado...$B$BFique, $n. Por favor, honre Helgrum comigo. Você fez tanto por ele.', '', '', '', '', '', '', '', '', '', 'Fale com Nika Cicatriz-de-sangue.', 0),
(27912, 'ptBR', 'O tesouro dos titãs', 'Investigue o Tesouro dos Observadores.', 'O segundo defensor tomba, e uma arca surge no fundo da câmara. Seria isso o que eles protegiam?', '', '', '', '', '', '', '', '', '', 'Inspecione o Tesouro dos Observadores dentro da Tumba dos Observadores, que fica nos Ermos.', 0),
(27913, 'ptBR', 'O tesouro dos titãs', 'Investigue o Tesouro dos Observadores.', 'O segundo defensor tomba, e uma arca surge no fundo da câmara. Seria isso o que eles protegiam?', '', '', '', '', '', '', '', '', '', 'Inspecione o Tesouro dos Observadores dentro da Tumba dos Observadores, que fica nos Ermos.', 0),
(27914, 'ptBR', 'Bênção da revoada verde', 'Fale com Lorde Itharius no topo do templo de Atal\'Hakkar.', 'Você agiu bem, $n. Jammal\'an pode ter escapado, mas sua retirada pavimenta o caminho para que eu entre no templo como bem aprazer-me.$B$BFique onde está e não se mova. Hei de acelerar seu retorno puxando seu espírito a mim usando o Sonho Esmeralda.$B$BPode ser que isso cause certo torpor.', '', '', '', '', '', '', 'Lorde Itharius', '', '', '', 0),
(27915, 'ptBR', 'O coração do templo', 'Fale novamente com Lorde Itharius dentro do templo de Atal\'Hakkar.', 'Devo confessar que este incidente interessa-me por motivações mais pessoais. Um dos primeiros dragões verdes aqui corrompidos era meu irmão, Erânicos.$B$BPensei que Erânicos houvesse sucumbido, eternamente perdido para as mais sombrias fendas deste pesadelo, mas ouvi dizer que seu vulto emergiu do templo. Não sei se, realmente, trata-se dele ou de um triste eco vazio.$B$BSe você deseja ajudar-me mais, retorne ao Salão das Máscaras, atravesse o arco e adentre o verdadeiro santuário do templo. Encontrarei você lá.', '', '', '', '', '', '', '', '', '', '', 0),
(27916, 'ptBR', 'O relatório de Ruag', 'Entregue o Relatório da Lança Lascada ao Comandante de Expedição Ruag no Pedregal.', 'Aqui está o relatório de Ruag, $n. Avise-o que o batedor dele ainda está aqui.$B$BNão mencione Helgrum. Não distrairei os demais com notícias trágicas.$B$BPreciso ser forte. Todos precisamos.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Comandante de Expedição Ruag no Pedregal, que fica no Pântano das Mágoas.', 0),
(27917, 'ptBR', 'O cheiro do inimigo', 'Mate o Barão Ashbury.', 'Posso sentir o cheiro de Godfrey e seus aliados a um quilômetro de distância. Eles tentaram esconder os rastros, mas não se saíram muito bem. Vamos usar essa vantagem para acabar de vez com eles.$B$BUm deles está bem perto daqui e, embora o cheiro dele tenha mudado, parecendo agora meio "morto", tenho quase certeza que é o Barão Ashbury. Entre na bastilha e acabe com ele, enquanto nós garantimos que os Renegados não interfiram no nosso trabalho.', '', '', '', '', '', '', 'Barão Ashbury', '', '', 'Fale novamente com o Líder da Matilha Ivar Dentessangue.', 0),
(27918, 'ptBR', 'O Refúgio', 'Entregue os Cristais de Draenetista ao Anacoreta Avuun.', 'O anacoreta Avuun é um de nossos irmãos que não foram corrompidos, a quem outras raças conhecem como draeneis, e veio ao Refúgio para cuidar de nós e tentar encontrar uma cura para nosso estado. Foi ele quem me enviou aqui para coletar estes cristais.$B$BEle está agora cuidando de um amigo muito doente... e, apesar de ter requisitado ajuda à Exodar, ninguém respondeu ao seu pedido até agora. Você poderia levar esses cristais para ele, $n? Talvez você seja $Go único:a única; capaz de ajudá-lo.', '', '', '', '', '', '', '', '', '', '', 0),
(27919, 'ptBR', 'Rumo à Barreira do Inferno', 'Viaje à Barreira do Inferno e fale com Elomara Cervaforte na Bastilha de Etergarde.', 'Somos gratos por teu auxílio aqui neste pântano, $n. Gostaria de informar-te que recebi correspondência da Bastilha de Etergarde.$b$bElomara Cervaforte requisitou ajuda para investigar os restos naufragados do Recôndito Vermelho, mas nenhum dos nossos quis enfrentar tal viagem, e do mesmo modo não tive condições de deixar o Refúgio.$B$BA Bastilha de Etergarde encontra-se na Barreira do Inferno, ao sul do Pântano das Mágoas. Toma cuidado para não te aproximares demais de Pedregal no teu caminho para aqueles lados.', '', '', '', '', '', '', '', '', '', '', 0),
(27920, 'ptBR', 'Armado até os dentes', 'Mate o Barão Silverlaine e o Comandante Floraval.', 'Topamos com um obstáculo inesperado durante nosso ataque à bastilha, $n. Parece que os soldados que serviram ao Barão Silverlaine e ao Comandante Floraval em vida, agora os servem também em morte, e, para piorar as coisas, Godfrey os colocou bem no nosso caminho!$B$BMas não se preocupe, eles não serão nada além de um pequeno empecilho. Elimine Silverlaine e Floraval, pois assim seus homens não terão mais quem os comande e estaremos mais próximos do nosso objetivo final.', '', '', '', '', '', '', 'Comandante Floraval', '', '', 'Fale novamente com o Líder da Matilha Ivar Dentessangue.', 0),
(27921, 'ptBR', 'Lutando com unhas e dentes', 'Mate o Lorde Walden.', 'Parece que o Lorde Walden finalmente notou nossa presença e reforçou as defesas. Infelizmente, para ele, isso não será suficiente... nada deterá a força da matilha!$B$BO caminho até Walden está cheio de lacaios do Flagelo, mas acredito que você seja capaz de abrir caminho para a nossa passagem. A derrota de Walden será como um tiro certeiro no líder covarde deles.', '', '', '', '', '', '', 'Lorde Walden', '', '', 'Fale novamente com o Líder da Matilha Ivar Dentessangue.', 0),
(27922, 'ptBR', 'Traidores!', 'Esconda-se atrás da Planta de Neferset e descubra o Segredo dos Nefersets.', 'Por favor, $Gestranho:estranha;. Você tem que me ajudar.$B$BVim aqui para investigar a chegada de um poderoso aliado dos Neferset, até ser traído por meus companheiros e entregue ao inimigo.$B$BVá ao terraço a leste daqui e descubra informações que não consegui encontrar. Você terá que se esconder dos Neferset. Talvez você possa se esconder atrás de uma das grandes plantas na plataforma para ocultar sua presença.$B$BFaça isto para mim e ajudarei seus amigos a encontrar o caminho para a segurança.', '', 'Segredo dos Neferset descoberto', '', '', '', '', '', '', '', 'Fale novamente com o Príncipe Nadun na Cidade Perdida dos Tol\'vir em Uldum.', 0),
(27923, 'ptBR', 'Fumaça nos olhos dos outros é refresco', 'Queime Fardos de Feno dentro da Cidade Perdida dos Tol\'vir em Uldum.', 'Não sei que plano doido seu amigo está tramando, mas teremos que distraí-los se quisermos uma chance de fuga.$B$BPegue a tocha daquele braseiro e comece alguns incêndios.$B$BTalvez, se distrairmos a escória Neferset por alguns minutos, tenhamos a oportunidade de que precisamos.', '', 'Fardo de Feno queimado', '', '', '', '', '', '', '', 'Fale novamente com o Príncipe Nadun na Cidade Perdida dos Tol\'vir em Uldum.', 0),
(27924, 'ptBR', 'O plano de Bino', 'Recolha 6 partes de Armaduras de Nerfeset.', 'Eu tive uma ideia! Pode acreditar, dessa vez a ideia é boa!$B$BPegue algumas partes dessas armaduras brilhantes que o povo felino usa.$B$BEste plano não vai falhar. Confie em mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Bino na Cidade Perdida dos Tol\'vir, em Uldum.', 0),
(27926, 'ptBR', 'Hospitalidade do leste', 'Belloc Gumélion quer que você se misture com os convidados no Porto de Schnottz.', 'Receio que o comandante esteja bastante ocupado agora.$b$bAs exigências de uma operação como esta têm requerido muito da atenção dele ultimamente.$b$bEnquanto você espera para falar com ele, por que você não se mistura um pouco com os nossos convidados?$b$bConvidamos uma variedade de ilustres figuras de Azeroth para quando revelarmos os segredos desta região.$b$bEstou certo de que você os achará cativantes.', '', 'Social feita com o Embaixador Laurent', 'Social feita com o Cavalheiro Refinado', 'Social feita com o Artista em Ascensão', 'Social feita com a Atriz Aspirante a Estrela', '', '', '', '', 'Fale com Belloc Gumélion no Porto de Schnottz.', 0),
(27927, 'ptBR', 'Até a cicatriz', 'Encontre Theldurin, o Perdido, na Cicatriz do Quebramundo, que fica nos Ermos.', 'Os Ermos são o lar de pessoas estranhas, e muitas já estão aqui há muito tempo.$b$bPor exemplo, três cavaleiros estavam hospedados aqui na cidade. Eu esqueci os nomes deles... Acho que o anão se chamava Theldurin. De qualquer forma, eles foram para o sul levando um monte de cerveja e não voltaram desde então. Acho que eles estavam indo para aquela grande escarpa.$b$bVocê se importaria em ver como eles estão? Eu gostaria de me certificar de que eles estão bem.', '', '', '', '', '', '', '', '', '', '', 0),
(27928, 'ptBR', 'Um favor para o peleiro', 'Colete 5 Pelegos de Coiote do Deserto.', 'O comandante sabe ser generoso àqueles que demonstram lealdade, e sei de algo que você pode fazer para cair nas graças dele.$b$bAntes de construir esta... bem... esta força de trabalho, ele trabalhava com peles de animais.$b$bEle é muito habilidoso na arte da couraria. O peleiro sabe fazer maravilhas com as peles mais esfarrapadas.$b$bDizem que o oásis seco a leste é o lar de uma espécie rara de coiote.$b$bAs peles deles seriam um presente muito atencioso.', '', '', '', '', '', '', '', '', '', 'Fale com Belloc Gumélion no Porto de Schnottz.', 0),
(27929, 'ptBR', 'Arraste-os para o inferno', 'Use o Gancho Farpado para derrubar e matar 4 Cavalga-grifos de Trondamar.', 'Um único draco Presa do Dragão vale mais que uma dúzia de cavalga-grifos Martelo Feroz. Tire eles de cima dos pássaros piolhentos e eles não são nada!$B$BAté você consegue matar eles com facilidade, $c da Horda.$B$BCace cavalga-grifos sobrevoando o rio ao norte da Ravina de Sangue. Leve este gancho para atirar neles quando passarem perto. Isso vai fazer eles caírem das montarias bem aos seus pés. Dê um fim neles! Mate alguns cavalga-grifos de Trondamar e acreditarei que a Horda é tão poderosa quanto você diz.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Narkrall Garrasgo na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(27930, 'ptBR', 'Devastação', 'Procure Rheastrasza.', 'A costa está limpa. Se Rheastrasza ou o ovo conseguiram, por algum milagre, escapar das chamas do Asa da Morte, eles devem estar precisando da sua ajuda o quanto antes.', '', '', '', '', '', '', '', '', '', 'Procure por qualquer vestígio de Rheastrasza dentro do Ninho Escondido, nos Ermos.', 0),
(27931, 'ptBR', 'Os campos sísmicos', 'Fale com o Ardósio Movediço nos Campos Sísmicos, que fica no Geodomo.', 'Antes que você possa nos ajudar aqui, você vai ter que lidar com as tropas da Therazane, a Petramáter, a sul. Os elementais e os gigantes estão se reunindo nos Campos Sísmicos.$B$BEles também estão em busca do fragmento central do Pilar do Mundo. Provavelmente nos atacarão em meio à guerra contra os troggs de pedra e não conseguiremos repelir a ofensiva.$B$BEu já enviei o arquigeomante para lá. Fale com Ardósio Movediço e faça o que ele mandar.', '', '', '', '', '', '', '', '', '', '', 0),
(27932, 'ptBR', 'O machado da mutilação terrena', 'Mate 5 Colossos Esmeralda Mutilados.', 'Os colossos de esmeralda são as maiores criaturas da Petramáter. Eles têm que ser os primeiros a serem retirados do campo.$B$BEu trouxe o machado do Petrarca Rochamanto exatamente para essa tarefa. Use-o para partir os gigantes ao meio.$B$BIsso vai deixá-los com um tamanho mais adequado para que você dê cabo deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ardósio Movediço nos Campos Sísmicos, que ficam no Geodomo.', 0),
(27933, 'ptBR', 'Minério elemental', 'Colete 6 pepitas de Minério Elemental.', 'Você vai ter que matar o líder das forças de Therazane. Mas, para levar você até ele de forma rápida e segura, eu vou ter que fazer um ritual.$B$BVá até o campo e colete minério elemental dos furiantes. Com isso, eu conseguirei unir você à terra e levá-$Glo:la; aonde quiser.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ardósio Movediço nos Campos Sísmicos, que ficam no Geodomo.', 0),
(27934, 'ptBR', 'Uno com a terra', 'Complete o ritual Uno com a Terra.', 'O líder das tropas da Petramáter é o grande senhor elemental da terra Avalanchion. Para nossa sorte, os sectários do Martelo do Crepúsculo decidiram invadir o covil dele. Eles estão tentando controlar os elementais do senhor da terra.$B$BVamos tirar vantagem desse caos. O ritual telúrico que eu invocarei unirá você à terra. Assim, você será $Glevado:levada; para perto de Avalanchion sem despertar a atenção dele.$B$BCabe a você acabar com ele.', '', 'Ritual Uno com a Terra terminado', '', '', '', '', '', 'O Avalanchion está logo em frente. Você sabe o que fazer.', 'Ardósio Movediço', '', 0),
(27935, 'ptBR', 'Detendo a avalanche', 'Mate Avalanchion.', 'O Avalanchion está diante de você. Mate-o para evitar que as tropas de Therazane ataquem o Larpétreo.', '', '', '', '', '', '', 'Avalanchion', '', '', 'Fale com Petros Esmagapedra no Larpétreo, que fica no Geodomo.', 0),
(27936, 'ptBR', 'Detendo a avalanche', 'Mate Avalanchion.', 'Você precisa voltar e matar o Avalanchion antes que as tropas de Therazane ataquem o Larpétreo.', '', '', '', '', '', '', 'Avalanchion', '', '', 'Fale com Petros Esmagapedra no Larpétreo, que fica no Geodomo.', 0),
(27937, 'ptBR', 'Retorno heroico', 'Apresente-se perante o Petrarca Rochamanto no Larpétreo, que fica no Geodomo.', 'O Petrarca está esperando por você no Larpétreo, ao sul.$B$BE trate de aparecer apresentável. Você vai ser $Grecebido:recebida; como $Gherói:heroína;!', '', '', '', '', '', '', '', '', '', '', 0),
(27938, 'ptBR', 'O fragmento central', 'Recupere o Fragmento Central do Pilar do Mundo.', 'Eu $Go:a; presenteio com a chave do Larpétreo. Com isso, você poderá destrancar o meu lar e recuperar o fragmento central do Pilar do Mundo.$B$BGuarde bem o fragmento, $n, e trate de levá-lo até o Templo da Terra, no coração do Geodomo, o mais rápido possível!$B$BSaiba que você será sempre $Gbem-vindo:bem-vinda aqui;.', '', '', '', '', '', '', '', '', '', 'Entregue o Fragmento Central do Pilar da Terra para o Arauto da Terra Yevaa no Templo da Terra, que fica no Geodomo.', 0),
(27939, 'ptBR', 'A raposa do deserto', 'Schnottz quer que você leve a Raposa do Deserto para ele.', 'Há muito a serr feito neste região, $r.$b$bNós dois terr um paixão arrdente pelos tecnologias antigos daqui, não?$b$bTalvez exista forrma de trabalharrmos juntas?$b$bVamos deixarr as mal-entendidos parra trás, tudo bem?$b$bAgorra, tem uma animal elusiva que estou caçando no região ao leste. Busque esse criaturra parra mim como demonstração do seu sinceridade, está bem?$b$bAí, talvez eu deixarr você entrarr no meu operração...', '', '', '', '', '', '', '', '', '', 'Fale com Schnottz no Porto de Schnottz.', 0),
(27940, 'ptBR', 'Pássaros imundos', 'Você deve matar 8 Abutres Doentes.', 'O céu sobre o Oásis Murcho está infestado por aqueles abutres horríveis.$b$bComo roedores infecciosos alados, eles não servem para nada e causam um mal sem tamanho.$b$bLivre os céus desse estorvo e deixe a região melhor do que estava quando você chegou.', '', 'Abutres Doentes mortos', '', '', '', '', 'Abutre doente', '', '', '', 0),
(27941, 'ptBR', 'Moda utilitária', 'Belloc Gumélion quer que você colete 10 Uniformes de Soldados.', 'Temos uma norma rigorosa entre os nossos soldados, e que levamos muito a sério.$b$bNossas tropas devem sempre se vestir com o uniforme oficial. Isto ajuda na organização, na redução de incidentes de fogo amigo e as tropas ficam com ótima aparência!$b$bChamamos isso de moda utilitária.$b$bUltimamente, estamos ficando sem uniformes. Preciso pedir a você que recolha os uniformes dos soldados que morreram cumprindo o dever.$b$bVocê deve encontrar bastante desses pobres sujeitos a leste daqui, nas Ruínas de Ammon.', '', '', '', '', '', '', '', '', '', 'Fale com Belloc Gumélion no Porto de Schnottz.', 0),
(27942, 'ptBR', 'Idolatria', 'O Comandante Schnottz quer que você colete 8 Ídolos Bem Preservados.', 'Ecziste um coisa que preciso pedirr a você, $r.$b$bA minha conselheirro de mais confiança foi vítima de um antigo maldição. O bagata trransforrmou a homem em uma perru, orra bolas!$b$bEu estudarr porr dias parra descobrirr uma remédio parra o condição dela, e, finalmente, eu estarr pronto parra realizarr o ritual.$b$bPrecisarrei de várrias ídolos dos ruínas próximos. Você precisarr trazerr elas parra mim de imediato!$b$bDispensad$ga:o;!', '', '', '', '', '', '', '', '', '', 'Fale com o Comandante Schnottz no Porto de Schnottz.', 0),
(27943, 'ptBR', 'Espíritos enfurecidos', 'O Comandante Schnottz quer que você use o C.A.P.L. para coletar 5 Essências Espectrais Furiosas.', 'A Doutorr Venkman erra um das minhas maiorres pesquisadorres, até que precisamos colocarr uma basta na sofrrimento dela.$b$bContudo, ela deixarr comigo uma dos seus maiorres conquistas. Contrra a adversárrio superrnaturral adequadamente afinada, este arrma irrá sifonarr o essência da alvo.$b$bÉ de suma importância parra a ritual que tentarrei realizar.$b$bOnde você entrrar? Simples. Você terr a privilégio de coletarr a materrial.$b$bO arrma estarr calibrrado parra funcionarr com as Espectros Enfurrecidas na templo ao leste.', '', '', '', '', '', '', '', '', '', 'Fale com o Comandante Schnottz no Porto de Schnottz.', 0),
(27944, 'ptBR', 'Terrível contra as aranhas', 'Mate 12 Espreitadoras Lenhanegra em Lenhanegra. A floresta Lenhanegra fica a oeste daqui, do outro lado da ponte, na ilha central.', 'Estamos tentando estabelecer uma base na Lenhanegra há semanas, mas o lugar está infestado de aranhas. Faça-me um favor e mate algumas, para que a gente possa montar um ataque.$b$bTome cuidado. No começo da semana, ouvi dizer que as tropas da Horda estavam rondando por lá.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante-de-campo Abreu na Base de Operações de Baradin após cumprir a missão.', 0),
(27945, 'ptBR', 'Diamante preto', 'Adquira um Coração de Diamante Preto.', 'A terra sangra, $c. Eles a afligem como alguém que estraçalha um pedaço de carne.$B$BEstes sectários deleitam-se com seus poderes, mas os elementais que eles usam para seus malefícios podem traí-los. Procure os Rochescravos Obsidianos a nordeste daqui, pelas terras arrasadas que chamamos de Lacuna Negra.$B$BEstilhace seus corpos e encontre para mim um perfeito coração de diamante preto. Olharei para o coração e revelarei sua alma.', '', '', '', '', '', '', '', '', '', 'Leve o coração para Mallia na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(27947, 'ptBR', 'Visão do Crepúsculo', 'Localize um Olho do Crepúsculo na Lacuna Negra.', 'Cho\'gall controla seus lacaios através de orbes mágicos e poderosos: "Os Olhos do Crepúsculo."$B$BNo Monte Hyjal, os guardiões de Hyjal conseguiram achar e controlar um para seus próprios fins. Devemos fazer o mesmo. Quero um daqueles orbes para perscrutar o centro do covil de Cho\'gall.$B$BProcure na Lacuna Negra, do outro lado do rio a nordeste, e encontre um Olho do Crepúsculo. Faça o que for necessário para trazer um orbe até mim!', '', '', '', '', '', '', '', '', '', 'Localize um Olho do Crepúsculo na Lacuna Negra.', 0),
(27948, 'ptBR', 'Uma tarefa pegajosa', 'Colete 4 Glândulas de Seda Pegajosa das Prolemadres Lenhanegra. A floresta Lenhanegra fica a oeste daqui, do outro lado da ponte, na ilha central.', 'Encontrar suprimentos aqui na ilha anda cada vez mais difícil.$b$bFelizmente, demos a sorte de encontrar uma boa quantidade de seda na Lenhanegra, a oeste daqui. O problema é que a seda vem das glândulas das aranhas prolemadres. Traga-me 4 glândulas.$b$bIsso deve ser suficiente para terminarmos mais um lote de camisas.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante-de-campo Abreu na Base de Operações de Baradin após cumprir a missão.', 0),
(27949, 'ptBR', 'Os esquecidos', 'Liberte os espíritos de 6 Almas Torturadas na Colina Esquecida. As almas são canalizadas ao se tocar as lápides com as mãos. A Colina Esquecida fica a oeste daqui, depois de Lenhanegra e do Front Incansável.', 'Vários soldados pereceram nesta ilha, $n. É mais do que justo demonstrarmos nosso respeito a eles da melhor forma possível.$b$bQuero que você vá à Colina Esquecida, a oeste daqui, e livre as almas atormentadas dos nossos irmãos deste lugar penoso. Tome bastante cuidado. Recebemos relatos de mortos-vivos na região.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Paranhos na Base de Operações de Baradin, após cumprir a missão.', 0),
(27950, 'ptBR', 'Gluglu!', 'Schnottz quer que você fale com ele quando você estiver preparad$go:a; para testemunhar o ritual.', 'Finalmente! Chegou o horra parra libertar a Gluglu daquele maldito maldição.$b$bPrreste atenção agorra, $r, e fique alerrta. Não podem haver interrupções enquanto realiza a ritual.$b$bMe avisa quando a perrímetro estiverr segurra.$b$bAgorra, vá logo!', '', 'Ritual de Transformação do Gluglu testemunhado', '', '', '', '', '', '', '', '', 0),
(27951, 'ptBR', 'Todos devemos nos sacrificar', 'Mate 10 Xamãs das Trevas.', '<O Olho fala com você, a ‘‘voz\' reverbera como se viesse de todos os lugares ao mesmo tempo.>$B$BVocê busca minhas visões, $r? Meus poderes têm um preço. Os discípulos crepusculares têm me honrado com o sangue dos anões Martelo Feroz das ruínas próximas, mas ainda tenho sede. Talvez você possa fazer melhor.$B$BMate meus velhos mestres e minha visão será sua. Honre-me matando os xamãs das trevas. Sangue é sangue afinal de contas.', '', '', '', '', '', '', '', '', '', 'Retorne ao Olho do Crepúsculo na Lacuna Negra, que fica no Planalto do Crepúsculo.', 0),
(27952, 'ptBR', 'Os Exploradores', 'Fale com a Exploradora Mowi no Templo da Terra, que fica no Geodomo.', 'Um grupo da Liga dos Exploradores está na câmara a noroeste, dentro do templo.$B$BEles vêm nos alertando sobre alguma armação do Martelo do Crepúsculo.$B$B$n, você poderia ser $Gum bom menino:uma boa menina; e ver se eles estão precisando de alguma coisa?', '', '', '', '', '', '', '', '', '', '', 0),
(27953, 'ptBR', 'O Relicário', 'Fale com o Avaliador Ruibarbo no Templo da Terra, que fica no Geodomo.', 'Um grupo do Relicário está na câmara a nordeste, dentro do templo.$B$BEles vêm nos alertando sobre alguma trama do Martelo do Crepúsculo.$B$B$n, tu poderias ser $Gum bom menino:uma boa menina; e ver se eles estão precisando de alguma coisa?', '', '', '', '', '', '', '', '', '', '', 0),
(27954, 'ptBR', 'O que os olhos veem', 'Leve o Olho do Crepúsculo para Garona Meiorken na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 'Muito bem, $r. Você adquiriu meus serviços com sangue. Leve-me de volta a Garona Meiorken.$B$BAh sim, já sei para onde você me levará. A incessante busca por vingança de Garona não é nenhum segredo. Será um prazer vê-la acontecer.', '', '', '', '', '', '', '', '', '', 'Leve o Olho do Crepúsculo para Garona Meiorken na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(27955, 'ptBR', 'O olho que tudo vê', 'Perscrute o Olho do Crepúsculo para Garona.', 'Esta monstruosidade me arrepia os cabelos. Cho\'gall usa isso para controlar seus lacaios – agora é hora de usar este olho contra ele.$B$BDeixe-me ver... hum, está bem nebuloso. Só vejo mesmo você. Por que estou vendo você?$B$B<Garona fica de frente para o Olho.>$B$BOlhe para dentro do Olho e me diga o que você vê. Perscrute o covil de Cho\'gall! O que ele está fazendo? Ele está rodeado de guardas? Diga-me!', '', 'Olho do Crepúsculo perscrutado', '', '', '', '', '', '', '', 'Fale com Garona Meiorken na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(27956, 'ptBR', 'A tarefa do Lanque', 'Colete 15 Volantes de Motor Temperados dos Golens de Guerra Temperados.', 'O Lanque veio dos Ermos. Outros ogros tentam fazer o Lanque lutar.$b$bO Lanque detesta lutar. O Lanque quer aprender.$b$bO Lanque vê máquinas ao sul. Máquinas feitas de engrenagens.$b$bTalvez, se você pedir com jeito, as máquinas darão algumas engrenagens. Então, talvez o Lanque possa ficar com uma engrenagem e aprender sobre as máquinas também.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Lanque no Avanço de Tório, que fica na Garganta Abrasadora.', 0),
(27957, 'ptBR', 'Lanque não mata', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27958, 'ptBR', 'Um antídoto adequado', 'Obtenha 14 amostras de Peçonha de Teia-de-vidro.', 'É uma pena o Lanque ter partido. Eu estava começando a gostar da companhia dele.$b$bBem, de volta ao trabalho!$b$bSou a coisa mais próxima de um médico que esta expedição tem, e já estou quase sem antídoto. E tendemos a precisar de muito.$b$bA chave para um bom antídoto é SEMPRE começar com o próprio veneno. As aranhas teia-de-vidro daqui parecem um ponto de partida ideal. Se você matá-las, provavelmente vai conseguir extrair um pouco de veneno das bolsas que ficam dentro das mandíbulas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lisa Pulveriza no Avanço de Tório, que fica na Garganta Abrasadora.', 0),
(27959, 'ptBR', 'A aventura do Lanque: o montador de aranhas', 'Enfraqueça 7 Aranhas Teia-de-vidro para que o Lanque possa montar nelas.', 'O Lanque vê que você gosta de matar coisas. Deixa o Lanque mostrar outro jeito.$b$bO Lanque sempre quis andar nas costas das aranhas. Parece divertido. Mas as aranhas são rápidas. Fogem sempre.$b$bNós trabalhamos juntos. Você luta com a aranha e deixa ela cansada. Aí, o Lanque pula nas costas da aranha e anda por aí.$b$bTalvez o Lanque até pegue veneno para você! Não precisa matar!', '', 'Aranhas montadas', '', '', '', '', '', '', '', '', 0),
(27960, 'ptBR', 'Quanto menos, melhor', 'Mate 10 Geólogos ou Vigias dos Ferro Negro.', 'Não sou um grande lutador... Estou mais para um anão minerador. O mesmo vale para o Jack e a Lisa. E quanto ao Lanque... Bem, seria de se esperar que ele fosse um grande lutador, mas ele é o mais maricas de nós todos.$b$bO que estou dizendo é que é bom você ter chegado.$b$bParece provável que nós, da Irmandade do Tório, tenhamos que combater os anões Ferro Negro em breve. Acho que você deveria pegar alguns dos melhores deles antes que a guerra esquente. Comece pelos geólogos e vigias ao sul.', '', 'Geólogos ou Vigias Ferro Negro mortos', '', '', '', '', '', '', '', 'Fale novamente com Escavão Carvoparte no Avanço de Tório, que fica na Garganta Abrasadora.', 0),
(27961, 'ptBR', 'No lugar errado', 'Salve 8 Frangos das Cinzas.', 'A garganta é um lugar duro. Não se vê muita vida por aqui.$b$bTentamos trazer alguns animais, mas eles não se saíram nada bem. Simplesmente não há comida para eles. As aranhas, por outro lado, que já eram perigosas, estão ficando grandes e gordas às custas dos nossos frangos.$b$bNunca vamos nos livrar de todas as aranhas, mas podemos salvar os poucos frangos que restam. Não apenas você estará alimentando a Irmandade, mas também salvando os frangos de uma morte cruel e dolorosa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Escavão Carvoparte no Avanço de Tório, que fica na Garganta Abrasadora.', 0),
(27962, 'ptBR', 'Uma relíquia desajeitada', 'Obtenha o Chifre Gigante de Margol.', 'Margol, a Enfurecida, é uma velha réptil, vista com frequência por estas partes. Segundo conta a lenda, ela vive nesta garganta desde antes dela sequer ser uma garganta. A lenda também diz que ela devorou o meu irmão, Barnabé.$b$bNão me interessa a idade dela ou que tipo de magia ela dispara pelo nariz. Eu quero ela morta e pronto. Pelo Barnabé.$b$bVocê a encontrará perambulando pelos penhascos ao sul.', '', '', '', '', '', '', 'Margol, a Enfurecida', '', '', 'Fale novamente com Escavão Carvoparte no Avanço de Tório, que fica na Garganta Abrasadora.', 0),
(27963, 'ptBR', 'Um novo mestre... mas quem?', 'Obtenha o Memorando dos Ferro Negro com Gravius Lameiro, no Local de Trabalho do Lameiro.', 'Você chegou bem na hora.$b$bAqui vai o resumo: os anões Ferro Negro da garganta vêm agindo de modo estranho ultimamente, e a Irmandade do Tório pretende descobrir o motivo. O feitor Mão-de-graxa não gosta de surpresas.$b$bSuspeitamos que eles estejam seguindo ordens de algum novo líder. Tenho motivos para acreditar que Gravius Lameiro, logo ao sul daqui, saiba quem é.$b$bMesmo aqui, na Garganta Abrasadora, começamos a ouvir histórias sobre os seus feitos, $n. Você não deve ter problemas com o Lameiro.', '', '', '', '', '', '', 'Gravius Lameiro', '', '', 'Fale novamente com Jack Pernadura no Avanço de Tório, que fica na Garganta Abrasadora.', 0),
(27964, 'ptBR', 'Chefe-escavador Barbatrova', 'Mate Escavadores Ferro Negro e Soldados Rasos Ferro Negro no Caldeirão até que o Chefe-escavador Barbatrova apareça. Então, mate o Chefe-escavador Barbatrova e obtenha a Brasa Negra dele.', 'O Lameiro, no fim das contas, não ocupava um cargo tão alto na hierarquia quanto pensei. Teremos que pegar o superior dele e descobrir o que ele sabe.$b$bEle se chama chefe-escavador Barbatrova, e coordena as operações de escavação no Caldeirão, a noroeste daqui. Os escavadores e soldados rasos dele patrulham o leste do Caldeirão, escavando cada vez mais fundo, dia e noite.$b$bEle é conhecido por não dar as caras no campo de batalha com frequência, mas se você matar uma quantidade suficiente dos homens, ele será forçado a aparecer e dar de cara com você.', '', '', '', '', '', '', 'Chefe-escavador Barbatrova', '', '', 'Fale novamente com Jack Pernadura no Avanço de Tório, que fica na Garganta Abrasadora.', 0),
(27965, 'ptBR', 'Posto de Tório: a sede da Irmandade', 'Fale com o Feitor Mão-de-graxa no Posto de Tório, que fica na Garganta Abrasadora.', 'Você... você viu aquilo? Esta é a peça desaparecida que estávamos procurando! Precisamos levar esta informação de volta para alguém no Posto de Tório.$b$bOs Ferro Negro são conhecidos por terem se associado ao senhor do fogo no passado, mas nunca foram tão longe na Garganta Abrasadora.$b$bO Posto de Tório fica a oeste e norte daqui. Você o encontrará abrigado em meio aos penhascos em frente às Planícies Pyrox. Leve esta informação diretamente para o feitor Mão-de-graxa.', '', '', '', '', '', '', '', '', '', '', 0),
(27966, 'ptBR', 'Enterro dos ossos', 'Recupere 9 Fêmures Amaldiçoados dos carniçais que vagam na Colina Esquecida, que fica no oeste da ilha, pouco depois do Front Abandonado.', 'Há vários zumbis e carniçais vagando pela Colina Esquecida desde que conquistamos esta ilha sórdida. Tentamos nos livrar deles várias vezes, mas eles sempre voltam.$b$bUm dos tenentes sugeriu pegar os ossos dos carniçais, depois de matá-los, para que não consigam reencarnar à noite. Podemos contar com a sua ajuda?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Paranhos na Base de Operações de Baradin, após cumprir a missão.', 0),
(27967, 'ptBR', 'Primeiro-tenente Cunha', 'Encontre e mate o Primeiro-tenente Cunha na Colina Esquecida. A Colina Esquecida fica no extremo oeste da ilha.', 'Eu era um mero recruta no cárcere de Ventobravo quando ouvi falar do tenente Cunha pela primeira vez. Ninguém acreditava que ele tinha vindo para Tol Barad. Infelizmente ele ainda vaga por estas ilhas sórdidas e isso derruba o moral das tropas.$b$bPreciso que você dê um fim ao sofrimento dele... e ao nosso.', '', '', '', '', '', '', 'Primeiro-tenente Cunha', '', '', 'Fale novamente com o Tenente Paranhos na Base de Operações de Baradin após lidar com Cunha.', 0),
(27968, 'ptBR', 'A fúria da matilha', 'Mate o Lorde Godfrey.', 'Ah, o doce cheiro da vitória! Meus homens devem estar dilacerando Godfrey neste exato momento. Vá até os domínios do lorde e colete os despojos, você merece!$B$BEra de se pensar que seria mais difícil derrotá-lo?', '', '', '', '', '', '', 'Lorde Godfrey', '', '', 'Fale novamente com o Líder da Matilha Ivar Dentessangue.', 0),
(27969, 'ptBR', 'Faça alguma coisa útil', 'O Comandante Schnottz quer que você convença 6 Operários Ociosos a trabalhar.', 'A Gluglu farrá muito falta, mas o missão não pode sofrerr.$b$bTalvez exista algum coisa que possa fazerr parra se redimirr.$b$bPegue uma das uniforrmes que você recuperrou. Quando vestem ela, minhas trabalhadorres não se comporrtam tão... agressivamente.$b$bUltimamente, o morral delas anda meio baixa. Algumas das trabalhadorres estão se recusando a realizarr os seus tarrefas.$b$bAi, o audácia!$b$bProcurre essas imbecis prreguiçosas e convença elas a trabalharrem... Porque senão, estarrão fritas!', '', 'Ociosos motivados', '', '', '', '', '', '', '', 'Fale com o Comandante Schnottz no Porto de Schnottz.', 0),
(27970, 'ptBR', 'Capitão P. Espargosa', 'Você recebeu ordens para matar o Capitão P. Espargosa no Cabo da Má Esperança, que fica a noroeste daqui, seguindo pela costa. Procure os navios naufragados.', 'Já faz semanas que o Cabo da Má Esperança tem sido um estorvo aqui em Tol Barad. Metade dos navios de suprimentos naufraga por causa daquelas rochas.$b$bComo se isso não bastasse, o cabo é dominado por uma gangue de marujos mortos-vivos. Fizemos de tudo para enfraquecê-los, mas eles continuam voltando e voltando. O nosso último recurso é liquidar o capitão deles. Ele deve estar em um dos navios próximos à costa.$b$bAh, espero que você não tenha medo de tubarões...', '', '', '', '', '', '', 'Capitão P. Espargosa', '', '', 'Apresente-se novamente ao Comandante-de-campo Abreu na Base de Operações de Baradin após cumprir a missão.', 0),
(27971, 'ptBR', 'O navio dos mortos-vivos', 'O Comandante-de-campo Abreu pediu para você matar 8 Marinheiros Náufragos no Cabo da Má Esperança. O cabo fica a noroeste daqui, na praia.', 'Já faz um tempo que temos problemas com os mortos-vivos do Cabo da Má Esperança. Cada vez que um navio naufraga, eles recrutam mais zumbis.$b$bSerá que você poderia nos fazer o favor de matar alguns deles? Sei muito bem que não vai dar para acabar com todos, mas qualquer ajuda é muito bem-vinda.$b$bAh, mais uma coisa, $n. Segundo informações, a Horda tem feito emboscadas na praia. Tome bastante cuidado.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante-de-campo Abreu na Base de Operações de Baradin após cumprir a missão.', 0),
(27972, 'ptBR', 'Levantando o moral', 'Você recebeu ordens para recuperar 6 Barris de Rum dos Mares do Sul nos navios naufragados no Cabo da Má Esperança. O cabo fica a norte daqui, seguindo pela costa.', 'O moral anda baixo, $n. Estamos fazendo de tudo para animar as tropas, mas o estoque do nosso principal levantador de moral está quase no fim... Estamos quase sem rum!$b$bOs relatórios da infantaria afirmam que há muito rum dentro dos navios naufragados no Cabo da Má Esperança. Será que você poderia ir lá investigar?$b$bTraga todos os barris de rum que encontrar!', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante-de-campo Abreu na Base de Operações de Baradin após cumprir a missão.', 0),
(27973, 'ptBR', 'Não ande descalço!', 'O Sargento Dias pediu para você recolher 15 feixes de Lenha do Estaleiro no Estaleiro Bonfilho. A lenha pode ser recolhida do chão ou com os fantasmas. O estaleiro fica a noroeste daqui, na costa.', '$n, você já foi ao Estaleiro Bonfilho? Acho que é melhor você nem chegar perto, a menos que tenha um bom motivo. Só que... É justamente para lá que quero que você vá.$b$bEstamos com poucos suprimentos desde que retomamos a ilha. O estaleiro está cheio de fantasmas, mas também há bastante lenha nele. Já enviamos vários grupos para tentar pegar um pouco, mas nenhum deles voltou.$b$bPodemos contar com a sua ajuda?', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Sargento Dias na Base de Operações de Baradin após cumprir a missão.', 0),
(27974, 'ptBR', 'Terra nostra', 'Mate o Barão Ashbury.', 'Você achou que um bando de worgens imundos poderia me deter? Rá!$B$BA Bastilha da Presa Negra era parte do reino de Lordaeron em vida; logo, deve pertencer aos Renegados em morte! Godfrey e seus cúmplices não são nada além de pequenas pedras no nosso caminho, e é claro que estamos muito felizes em acabar com eles e nos vingar pelo que fizeram contra a Dama Sombria.$B$BAshbury se posicionou perto da entrada da bastilha, então é um alvo fácil. Faça-me o favor de começar nossa investida com o pé direito, certo?', '', '', '', '', '', '', 'Barão Ashbury', '', '', 'Fale novamente com o Comandante Sicário Belmonte.', 0),
(27975, 'ptBR', 'PROCURA-SE: encarregado Bonfilho', 'Mate o Encarregado Bonfilho no Estaleiro Bonfilho. O estaleiro fica a noroeste daqui, na costa oeste.', 'O Encarregado Bonfilho tem sido um estorvo para nós desde que chegamos aqui. Os suprimentos de seu estaleiro nos seriam muito úteis... Se conseguíssemos pôr as mãos neles.$B$BEle mantém seus capangas sob rédea curta, e atravanca nosso acesso ao estaleiro. Eu preciso que você dê cabo dele por nós. Mas tome cuidado, $n, temos recebido reportes de presença da maldita Horda por toda aquela região.', '', '', '', '', '', '', 'Encarregado Bonfilho', '', '', 'Apresente-se novamente ao Sargento Dias na Base de Operações de Baradin após cumprir a missão.', 0),
(27976, 'ptBR', 'Malditos dedos gordos', 'Mate 12 Golens de Guerra Pesados.', 'Infelizmente, não consigo mais lutar como antes por causa deste problema de dedos gordos. Veja bem, o clima daqui, combinado com a falta de pressão atmosférica, faz os meus dedos incharem. Eles estão como chouriços de Thelsamar gigantes, estão sim...$B$BTu vai ter que fazer as minhas tarefas.$B$BA primeira da minha lista: pegar esses golens de guerra pesados feito bicheira em bezerro desmamado. Vai nessa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Hansel Mão-pesada no Posto de Tório, que fica na Garganta Abrasadora.', 0),
(27977, 'ptBR', 'Reconhecimento básico', 'Encontre e devolva o Alcaraviz de Ferraria e a Luneta do Espia.', 'Costumávamos ter mais coisas por aqui. Acho que havia uma luneta em algum lugar próximo, junto com um alcaraviz de ferraria.$b$bEstou quase certo de que esses itens foram roubados por anões Ferro Negro. Sim, eu sei que eu sou um anão Ferro Negro! Mas estou falando dos malvados que vivem naquela garganta.$B$BÉ melhor você checar os vaporistas que trabalham logo ao sul daqui. Eles são os usuários mais prováveis de ferramentas como essas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capataz Scrange no Posto de Tório, que fica na Garganta Abrasadora.', 0),
(27978, 'ptBR', 'Caça-fantasmas', 'Mate 14 fantasmas de qualquer tipo no Mirante do Largo, que fica a nordeste da base.', 'Está vendo aquela colina depois da base? Ali é Mirante do Largo. Acampar lá perto é praticamente suicídio. Estamos tendo problemas com espíritos e espectros desde que montamos o acampamento.$b$bVocê poderia ir até lá para mostrar a eles que viemos para ficar? Eu acho que, se você matar alguns, eles vão andar na linha direitinho.$b$bObrigado pela ajuda, $n.', '', 'Fantasmas mortos no Mirante do Largo', '', '', '', '', '', '', '', 'Apresente-se novamente ao Sargento Dias na Base de Operações de Baradin após cumprir a missão.', 0),
(27979, 'ptBR', 'Ministério negro', 'Obtenha a Esférula de Kiyuubi, a Esférula de Letherio e a Esférula de Finister. Feito isso, combine as três em uma Tripetricina do Crepúsculo.', 'Tenho mais uma missão para você. Essa vem diretamente do próprio Feitor. Parece que ele ficou bem chocado quando soube daquele "arquiduque" que tu descobriu.$b$bEle pediu que saíssemos em busca de três ministros do Crepúsculo que trabalham no Cerro da Sentinela de Fogo, a oeste. Eles se chamam Kiyuubi, Letherio e Finister. Cada um deles carrega algum tipo de pedra especial. Combine todas as três e traga elas de volta para cá.$b$bOuça bem, quando o Feitor dá ordens, tu não faz perguntas. Tu só obedece.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Hansel Mão-pesada no Posto de Tório, que fica na Garganta Abrasadora.', 0),
(27980, 'ptBR', 'As aranhas têm que morrer', 'Mate 9 Aranhas de Lava na Garganta Abrasadora.', 'Aranhas de tamanho normal, por mim, tudo bem.$b$bAranhas teia-de-vidro me deixam desconfortável, mas estão longe o bastante para que eu não me preocupe muito.$b$bAgora, aranhas de lava? <Lolo estremece.> Aranhas de lava são ASSUSTADORAS. Elas são aranhas enormes. Que vivem NA LAVA.$b$bAcabei de ser pago pela minha última semana de trabalho, e pagarei bem a você para matar essas coisas. Você pode encontrá-las por toda a Garganta Abrasadora.', '', 'Aranhas de Lava mortas', '', '', '', '', '', '', '', 'Fale novamente com o Capitão-vigia Lolo Longalcance no Posto de Tório, que fica na Garganta Abrasadora.', 0),
(27981, 'ptBR', 'Um calor que não passa', 'Obtenha 10 Frascos da Fornalha Cheios. Você deve usar os Frascos da Fornalha em elementais vivos, dentro da Garganta Abrasadora.', 'Nós assamos, nós cozinhamos, nós fritamos qualquer carne de aranha em que pudermos colocar as mãos. A questão é que isso tudo precisa de muito fogo.$b$bPor sorte, estamos bem no meio da cidade de fogo.$b$bÉ claro que o melhor fogo vem dos elementais. Você os encontrará por toda a Garganta Abrasadora, mas sempre perto da lava. Aqui, leve estes frascos e use-os nos elementais.$b$bAh, eu mencionei que os elementais têm que estar vivos enquanto você coleta a amostra?', '', '', '', '', '', '', '', '', '', 'Fale novamente com Hansel Mão-pesada no Posto de Tório, que fica na Garganta Abrasadora.', 0),
(27982, 'ptBR', 'Colares do Crepúsculo', 'Obtenha 20 Colares do Crepúsculo.', 'Você viu os colares ridículos que aqueles sectários do Martelo do Crepúsculo usam? As gemas daqueles troços são maiores que o punho do Hansel!$b$bBastam algumas daquelas joias do tamanho de hambúrgueres para que o Queimatar leve o negócio de ferraria para o próximo nível. Apanhe aqueles colares e ele compensará você bem.', '', '', '', '', '', '', '', '', '', 'Fale com o Mestre Ferreiro Queimatar no Posto de Tório, que fica na Garganta Abrasadora.', 0),
(27983, 'ptBR', 'A aventura do Lanque: anõezinhos mal-humorados', 'Enfraqueça 7 Vaporistas Ferro Negro para que o Lanque possa ajudá-los a adormecer.', 'O que você está fazendo? Por que você mata?$b$bVocê precisa das coisas dos anões? Ah, o Lanque entende. O Lanque tem um jeito melhor.$b$bEscuta: você vai lutar com anão, mas não mata! Só luta até o anão ficar cansado. Aí, o Lanque ajuda o anão dormir. Os anões devem ficar mal-humorados porque não dormem.$b$bVamos lá! Confia no Lanque.', '', 'Vaporistas Ferro Negro adormecidos', '', '', '', '', '', '', '', '', 0),
(27984, 'ptBR', 'O conto do Luncardo', 'Ouça o conto do Zamael.', 'Você irá me ajudar, mortal? Ouça o meu conto.', 'A história do Zamael', '', '', '', '', 'A história do Zamael', '', '', '', 'Fale novamente com Zamael Luncardo no Cerro da Sentinela de Fogo, que fica na Garganta Abrasadora.', 0),
(27985, 'ptBR', 'Oração a Eluna', 'Encontre e leia a Oração a Eluna.', 'Você irá me ajudar, mortal? Você encontrará a oração a Eluna?$B$BComo eu disse, a oração foi gravada em uma tábua dourada. Creio que eles a guardam em um daqueles baús torpes, perto da entrada da caverna deles, ao fundo da garganta.$B$BSe você recuperar a minha oração, não a traga de volta para mim. Ao invés disso, dedique algum tempo a lê-la.$b$bA absolvição pode ser pedir demais, dados os pecados que cometi. Mas isso não vai me impedir de ter esperança.', '', '', '', '', '', '', '', '', '', '', 0),
(27986, 'ptBR', 'No salão do Senhor da Montanha', 'Fale com o Senhor da Montanha Rendan, no Auge Férreo, que fica na Garganta Abrasadora.', 'A Irmandade do Tório não mantém uma milícia, apenas alguns guardas e eu. Para atacarmos os Ferro Negro da garganta com sucesso, precisaremos de ajuda.$b$bO senhor da montanha Rendan fica no topo da torre do outro lado da garganta, ao nosso sul. Ele não se associa ao pessoal do Crepúsculo ou aos elementais de fogo, mas tampouco se uniu à Irmandade. Talvez seja o momento de visitá-lo. Com a ajuda dele, podemos ter uma chance.', '', '', '', '', '', '', '', '', '', '', 0),
(27987, 'ptBR', 'Bala de canhão!', 'Você precisa recolher 4 Pilhas de Balas de Canhão no Mirante do Largo, que fica a nordeste da base. Depois, entregue-as para o Sargento Dias.', 'Largo e os lacaios dele estão roubando nossos suprimentos desde que montamos o acampamento. Você não imagina a frustração.$b$bOuvimos dizer que ele está estocando balas de canhão nas torres com vista para as águas do mirante. Será que você poderia ir lá e recuperar algumas?$b$b$n, não se esqueça de manter o olho aberto com a Horda também.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Sargento Dias na Base de Operações de Baradin após cumprir a missão.', 0),
(27988, 'ptBR', 'Peste... Peste em todo lugar!', 'Mate o Barão Silverlaine e o Comandante Floraval.', 'A melhor coisa sobre a peste é que, mesmo quando ela aparentemente desaparece, os resíduos remanescentes ainda são muito poderosos! Entretanto, ainda temos muito trabalho pela frente, com tantas defesas de Godfrey no nosso caminho.$B$BParece que os espíritos que serviam ao Barão Silverlaine e ao Comandante Floraval em vida, agora os servem em morte, e Godfrey os usa contra nós. Mostre a eles a determinação implacável dos Renegados!', '', '', '', '', '', '', 'Comandante Floraval', '', '', 'Fale novamente com o Comandante Sicário Belmonte.', 0),
(27989, 'ptBR', 'Ruumbo quer mel', 'Colete 12 Glóbulos de Mel de Lenha Morta das colmeias na Vila da Lenha Morta usando o Graveto para Mel de Ruumbo.', 'Ruumbo tem fome!$B$BOs idiotas da Lenha Morta roubaram todo o mel da tribo Presamatos! Nós vimos... er, Ruumbo viu eles fazendo isso! Agora, Ruumbo quer o mel de volta!$B$BPegue este... este graveto! Isso, este graveto. Leve este graveto e use ele para roubar o mel das colmeias na Vila Lenha Morta.$B$BRuumbo quer todo o mel. Isso é vital.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Totem de Ruumbo na Vila da Lenha Morta, que fica na Selva Maleva.', 0),
(27990, 'ptBR', 'Zona de combate', 'O Comandante Schnottz quer que você maneje a torreta de um dos tanques de cerco e use-a para derrotar 7 Vigias Decrépitos. Feito isso, apresente-se novamente a ele.', 'Parrece que surgiu outro oporrtunidade parra você se redimir, $r.$b$bEste pequeno emergência me deixou sem algumas atirradorres de tanque.$b$bVocê acha que terr fibra parra entrar na lugarr de uma deles?$b$bAs minhas tanques estão ao oeste da campo. Saia já daqui e coloque uma basta nesse bobeirra!', '', 'Vigias Decrépitos obliterados', 'Voltou ao Schnottz', '', '', '', '', '', '', 'Fale com o Comandante Schnottz no Porto de Schnottz.', 0),
(27991, 'ptBR', 'O mirante é nosso, aha, uhu!', 'O Sargento Dias pediu para você matar o Comandante Largo, no Mirante do Largo. O mirante fica a nordeste da base.', 'Só há uma forma de recuperar o Mirante do Largo.$b$bLargo anda bem paranoico hoje em dia, e deve estar no topo da torre, esperando a chegada da frota imaginária dele. Você já sabe o que precisa ser feito, $n.', '', '', '', '', '', '', 'Comandante Largo', '', '', 'Apresente-se novamente ao Sargento Dias na Base de Operações de Baradin após cumprir a missão.', 0),
(27992, 'ptBR', 'Como funcionam os ímãs?', 'Você foi $Gencarregado:encarregada; de recuperar 7 peças de Sucata da Máquina de Cerco. Use o Coletor de Sucata Magnetizado para encontrar as peças no Front Incansável, que fica a oeste, pouco depois da segunda ponte.', 'Arranjar peças de máquinas anda cada vez mais difícil aqui na ilha, $n. Estamos tentando consertar as máquinas de cerco defeituosas aqui no acampamento, mas as peças boas estão acabando.$b$bO segundo regimento informou que há algumas máquinas de cerco abandonadas em um antigo campo de batalha a oeste. Acho que deve ter algumas peças boas por lá.$B$BVai ser difícil achar qualquer coisa em meio a um antigo campo de batalha, então leve este coletor de sucata magnetizado e veja se ele ainda serve para alguma coisa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Paranhos na Base de Operações de Baradin após concluir a missão.', 0),
(27993, 'ptBR', 'Leve isso pra eles!', 'O Mack quer que você investigue a Tumba de Khartut.', 'Tivemos sorte de escapar, $c. Não sei se ficarei bem se não cuidarmos daqueles emboscadores.$b$bQue tal você voltar à tumba de Khartut e dar uma surra neles?$b$bFica ao nordeste, logo na entrada para Uldum, se me lembro corretamente.$b$bO que você tá olhando? Eu certamente não estou em condições de fazer isso!', '', 'Tumba de Khartut investigada', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Tumba de Khartut.', 0),
(27994, 'ptBR', 'Ruumbo quer justiça', 'Mate 15 Pelursos Lenha Morta de qualquer tipo.', 'Você! Viajante! Curve-se diante do poder de Ruumbo, o grande deus da tribo Presamatos!$B$BEscute a minha vontade! A maligna tribo Lenha Morta vive na aldeia atrás de mim! Eles são uns grandes idiotas!$B$BQuer dizer, eles... eles maculam meu nome com seus crimes perversos! Perseguem e ferem meus estimados Presamatos!$B$BEu exijo que você inflija minha justiça! Derrote os Lenha Morta e darei a você minha... minha bênção! Isso! A bênção de RUUMBO!', '', 'Pelursos Lenha Morta mortos', '', '', '', '', '', '', '', 'Fale novamente com o Totem de Ruumbo na Vila da Lenha Morta, que fica na Selva Maleva.', 0),
(27995, 'ptBR', 'Dance para Ruumbo!', 'Faça uma dancinha boba para Ruumbo.', 'Você agiu bem, $r! Ruumbo está satisfeito com a sua bravura e com o mel delicioso que você trouxe para Ruumbo.$B$BAgora, você vai... dançar! Isso!$B$BDance para Ruumbo! Dance!', '', 'Segredo de Ruumbo descoberto', '', '', '', '', '', '', '', 'Fale novamente com Grazle no Santuário Esmeralda e conte a ele o que aconteceu.', 0),
(27996, 'ptBR', 'Ordens são para os vivos', 'Mate o Lorde Walden.', 'É claro que não vamos dar ouvidos à conversa de Cromush sobre a peste. Porém, a força bruta dele será útil para empurrar meus homens contra os inimigos que bloqueiam o caminho até Godfrey, dentre os quais o mais poderoso é o lorde Walden, braço direito de Godfrey.$B$BMe encontrarei com você na sala de Walden depois que você acabar com ele. Então, finalmente, poderemos tomar toda a Bastilha da Presa Negra em nome dos Renegados!', '', '', '', '', '', '', 'Lorde Walden', '', '', 'Fale novamente com o Comandante Sicário Belmonte.', 0),
(27997, 'ptBR', 'A corrupção dos Flamejade', 'Mate 12 Sátiros Flamejade ou Devotos Vis Flamejade na Grota Flamejade.', 'A limpeza desta floresta tem sido um processo exaustivo. Para cada sucesso que obtemos, um novo desafio surge.$B$BOs sátiros Flamejade têm sido um aborrecimento constante. Eles almejam corromper toda a floresta, assim como nós buscamos expurgá-la. Agora, tomamos medidas para iniciar a erradicação deles de toda a Selva Maleva.$B$BVá à Grota Flamejade, a oeste, e livre a floresta da presença deles. A entrada está a norte das muralhas da Vila da Lenha Morta. Procure pelos torpes estandartes deles.', '', 'Sátiros da Grota Flamejade mortos', '', '', '', '', '', '', '', 'Fale novamente com Tenell Velifrondes no Santuário Esmeralda, que fica na Selva Maleva.', 0),
(27998, 'ptBR', 'Doce e impiedosa vingança', 'Mate o Lorde Godfrey.', 'Se tudo correr bem, você será capaz de entrar diretamente nos domínios de Godfrey e pegar uma recompensa digna $gdo:da; $c jovem e $gambicioso:ambiciosa; que você é.$B$BMas, Godfrey é um adversário ardiloso. Portanto, seria prudente ir até lá, para o caso de precisarem de você. O desgraçado pagará pelo que fez contra a Dama Sombria!', '', '', '', '', '', '', 'Lorde Godfrey', '', '', 'Fale novamente com o Comandante Sicário Belmonte.', 0),
(27999, 'ptBR', 'O destino dos Doyle', 'Dê as notícias do clã Doyle para Iain Barbarruiva no Cemitério de Barbarruiva.', 'Parece que os Doyle se engajaram na derradeira batalha. Iain vai querer saber qual o desfecho.', '', '', '', '', '', '', '', '', '', '', 0),
(28000, 'ptBR', 'Diabretim foi pro saco', 'Enfraqueça o Diabretim e use o Saco de Diabrete Encantado para capturá-lo.', 'Os sátiros escondem o corrompido poço lunar atrás de uma barreira impenetrável de fogo demoníaco. Mas as tropas deles conseguem atravessá-la de alguma forma.$B$BInterrogar os sátiros seria inútil, mas os diabretes com os quais se associam são facilmente influenciáveis. Estou pensando em um especificamente...$B$BNo sopé das colinas a leste, um diabrete solitário tem sido visto perambulando, isolado dos demais. Ele deve ser uma presa fácil. Enfraqueça-o em combate para, então, capturá-lo com este saco encantado. E, então, deixe a conversa comigo...', '', 'Diabretim capturado', '', '', '', '', '', '', '', 'Fale novamente com a Arcanista Delaris nas Ruínas de Constellas, que ficam na Selva Maleva.', 0),
(28001, 'ptBR', 'O dever de um covarde', 'Fale com Colin Trondamar em Trondamar.', 'Podemos estar a salvo aqui, mas tem muitos Martelo Feroz que ainda precisam de ajuda. Nossa força aérea pode oferecer isso, mas temos que continuar a encorajar nossas forças se quisermos eliminar o Crepúsculo completamente.$B$BVou conversar com Colin Trondamar. Só um covarde não dá ouvidos ao clamor de seu povo, ainda mais em tempos como estes.$B$BVá para Trondamar, encontre Colin e peça explicações a ele. Não admitirei a covardia de um líder Martelo Feroz.', '', '', '', '', '', '', '', '', '', '', 0),
(28002, 'ptBR', 'Administração de crises', 'Belloc Gumélion quer que você tranquilize os convidados no Porto de Schnottz.', 'Há uma situação delicada que pede a... discrição objetiva de $gum forasteiro:uma forasteira;.$b$bVeja bem, um incidente desafortunado aborreceu alguns dos nossos convidados. Mas não se preocupe, pois os nossos melhores homens estão cuidando dos detalhes.$b$bNo meio-tempo, seria ótimo se você pudesse acalmar os visitantes mais nervosinhos.$b$bLide bem com a situação e, certamente, o seu feito chegará aos ouvidos do peleiro!', '', 'Escritor Prolífico questionado', 'Socialite Privilegiada tranquilizada', 'Homem de Negócios disciplinado', 'Artista em Ascensão aconselhado', '', '', '', '', 'Fale com Belloc Gumélion no Porto de Schnottz.', 0),
(28028, 'ptBR', 'Cerco!', 'Mate 9 Atiradores Peritos Ferro Negro.', 'O feitor Mão-de-graxa não poderia ter escolhido uma hora pior para pedir que eu compre uma briga. O meu cume já está sob cerco!$b$bNão é nada que meus guardas não possam resolver, mas, ainda assim, não vai ser fácil para mim simplesmente escolher alguns anões e mandá-los para aquela garganta infernal.$b$bTenho uma ideia: tu abate os atiradores peritos que estão mantendo o cerco em torno da nossa fortaleza e considerarei a sua oferta. Tu vai encontrar eles pelas planícies ao leste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Senhor da Montanha Rendan no Auge Férreo, que fica na Garganta Abrasadora.', 0),
(28029, 'ptBR', 'Taca fogo neles!', 'Use a Tocha da Retribuição nas quatro torres ao redor do Caldeirão.', 'Não sei se tu percebeu, mas a minha torre é muito mais alta do que qualquer uma das outras torres da Garganta. Alguns anões se orgulham do quão fundo conseguem cavar, mas não eu. De vez em quando, penso que eu deveria ter nascido um Martelo Feroz.$b$bMas, mesmo assim, não gosto nem de olhar essas outras torres. Aqui, pega esta tocha e usa ela nos braseiros que ficam no topo das outras torres. Primeiro, eles vão se arrepender do dia em que as construíram.', '', 'Torre oeste em chamas', 'Torre sudoeste em chamas', 'Torre sudeste em chamas', 'Torre leste em chamas', '', '', '', '', 'Fale novamente com o Senhor da Montanha Rendan no Auge Férreo, que fica na Garganta Abrasadora.', 0),
(28030, 'ptBR', 'A bala deles é melhor', 'Obtenha 200 Balas de Ferro Negro.', 'Aqueles anões cavadores de garganta sabem fazer ao menos uma coisa: projéteis de alta qualidade. Não consegui reproduzir os seus resultados, então, parti para roubar todos os projéteis deles que eu pude.$b$bVocê quer a minha ajuda? Arranje-me algumas centenas de balas com aqueles atiradores peritos lá embaixo.$b$bEstou certo de que eles não se oporão a entregar um projétil por vez, mas talvez você ache mais rápido procurar os caixotes repletos deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Senhor da Montanha Rendan no Auge Férreo, que fica na Garganta Abrasadora.', 0),
(28031, 'ptBR', 'Entrega especial para Pena Tabwa', 'Entregue o Canhão Criogênico de Pico-léguas para Pena Tabwa no Sítio Arqueológico Submerso, que fica em Mil Agulhas.', 'Arrumei um novo sócio! Meu melhor amigo, Pena Tabwa. Neste exato momento, ele está construindo a infraestrutura do nosso novo império de picolés!$B$BEle levou nossos empregados, o estoque de mercadorias e a máquina de resfriamento para o sítio arqueológico submerso, a sudoeste. Infelizmente, no momento não tenho como entregar algo para ele... algo extremamente importante: nosso supersecreto canhão criogênico de Pico-léguas!$B$BVocê se importaria de levá-lo para o Pena, $n?', '', '', '', '', '', '', '', '', '', '', 0),
(28032, 'ptBR', 'Os mistérios da moela de fogo', 'Obtenha 6 Moelas de Fogo.', 'Ainda falta sabermos muito sobre os incendossauros. De onde eles vieram? Como eles sobrevivem por aqui? E por que o gosto deles é tão ruim?$b$bA chave para o entendimento dessas feras pré-históricas, creio eu, começa com a moela de fogo. Todo incendossauro tem uma. Eu gostaria de estudar algumas delas.$b$bVocê encontrará incendossauros circulando a base do Auge Férreo, principalmente a oeste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Agnes Xalevelho no Auge Férreo, que fica na Garganta Abrasadora.', 0),
(28033, 'ptBR', 'Trapaça', 'Encontre uma forma de convencer o Senhor da Montanha Rendan a se juntar à Irmandade do Tório.', 'O quê? O que você ainda está fazendo aqui? Ah, eu prometi que eu ajudaria você e a Irmandade do Tório na batalha?$b$bEu menti.$b$bEu simplesmente não posso abrir mão dos homens agora. Sei que eu disse que ia ajudar, mas você não vai me convencer a deixar o Auge Férreo agora. De jeito nenhum.', '', '', '', '', '', '', '', '', '', 'Fale com o Lanque no Auge Férreo, que fica na Garganta Abrasadora.', 0),
(28034, 'ptBR', 'A aventura do Lanque: o ponto fraco do Rendan', 'Fale com três Guardas do Auge Férreo e pergunte se eles querem participar da sua dança.', 'O Lanque não é esperto, mas o Lanque percebe as coisas. Hoje, o Lanque percebe que o anão da montanha gosta de ver gente dançar.$b$bO Lanque gosta de dançar! $gO:A; $n gosta de dançar! Deve gostar!$b$bQuem sabe a gente não encontra mais anões que gostam de dançar? Depois, a gente vai falar com o anão da montanha, e ele vai escutar $go:a; $n.', '', 'Faça uma fila de conga com três anões', '', '', '', '', '', '', '', 'Apresente-se ao Senhor da Montanha Rendan no Auge Férreo, que fica na Garganta Abrasadora.', 0),
(28035, 'ptBR', 'O apoio do Senhor da Montanha', 'Reporte o seu sucesso ao Feitor Mão-de-graxa no Posto de Tório, que fica na Garganta Abrasadora.', 'Tudo bem, tudo bem! Se eu soubesse que tu dançava assim, eu não tinha pedido para tu fazer todas aquelas coisas.$b$bAvise ao feitor Mão-de-graxa que vou me juntar a vocês. Te encontro no fosso de lava, $grapaz:moça;! Com as forças combinadas do Posto de Tório e do Auge Férreo, aqueles anões da garganta não vão nem saber o que os acertou!', '', '', '', '', '', '', '', '', '', 'Fale com o Feitor Mão-de-graxa no Posto de Tório, que fica na Garganta Abrasadora.', 0),
(28038, 'ptBR', 'Sangue sobre o Planalto', 'Fale com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 'A guerra corre em suas veias, $c. Você deve se dar bem no Caldeirão.$B$BQuê? Você não sabe do Caldeirão da Carnificina? Aquele goblin bajulador Gurgthock e seu comparsa troll têm nos entupido de panfletos desde que o negócio foi aberto aqui no Planalto. Campeões de toda Azeroth lutam até a morte lá. É bom juntar uns amigos e ver como vocês se saem.$B$BO Caldeirão fica a sudoeste daqui. Procure Wodin, o Serviçal Troll, em algum lugar no meio de um círculo de ossos.', '', '', '', '', '', '', '', '', '', 'Fale com Wodin, o Serviçal Troll, no Caldeirão da Carnificina, que fica no Planalto do Crepúsculo.', 0),
(28041, 'ptBR', 'A isca perfeita', 'Pegue uma Carcaça Fresca de Grifo.', 'Você pode se sair bem em solo firme, $n, admito.$B$BMas nós, os Presa do Dragão, dominamos os céus tanto quanto as terras. Até que você prove que pode domar um draco tão bem quanto um Presa do Dragão, a Horda não tem valor nenhum para mim.$B$BVamos ver se você consegue arrebanhar um de volta para Ravina de Sangue.$B$BPrimeiro você precisa de isca. Vá e mate um dos grifos que vagam pela mata a oeste ou nordeste daqui. Mas tem que ser um selvagem! Dracos odeiam o fedor de anão em sua comida.$B$BPegue a carcaça do grifo e você saberá o que fazer.', '', '', '', '', '', '', '', '', '', 'Pegue uma Carcaça Fresca de Grifo.', 0),
(28042, 'ptBR', 'Entrega especial para Pena Tabwa', 'Entregue o Canhão Criogênico de Pico-léguas para Pena Tabwa no Sítio Arqueológico Submerso, que fica em Mil Agulhas.', 'Faz pouco tempo que me deram algo pra ser entregue a um gnomo chamado Pena Tabwa. Ele tá mais pra Pena Jaca, isso sim!$B$BEu quero que você leve isso pra ele no sudoeste, lá no sítio arqueológico submerso. Ele está tramando alguma coisa e tem grana no meio... Dá para sentir!$B$BVê se fica de olho no que ele está fazendo e tenta ficar com uma parte dos lucros, $n, uma parte bem grande!', '', '', '', '', '', '', '', '', '', '', 0),
(28043, 'ptBR', 'Como mutilar seu dragão', 'Atraia um Draco Preto com uma isca, ataque-o até que fique fraco e cavalgue-o para voltar à Ravina de Sangue.', '<Você apoia o corpo retalhado do grifo em seu ombro com as asas arrastando pelo chão.>$B$B<Dracos Pretos do Planalto pousam ao longo de uma cordilheira de picos baixos de montanhas a sudeste do Caldeirão da Carnificina.>$B$B<Se você jogar o corpo do grifo lá, um draco vai avançar para comer. A guarda dele estará baixa, então você será capaz de atacá-lo até fique suficientemente fraco para que você possa montar nele e sair voando.>', '', 'Draco Preto capturado', '', '', '', '', '', '', '', 'Fale com Zaela na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(28044, 'ptBR', 'Toque o intocável', 'Use a Poção Sanguefase no Signo de Taecondrius para se deslocar para o éter e procure a Garra de Taecondrius.', 'Eu adicionei uma gota da minha própria essência ao visgo. Procure um signo brilhante a oeste, na beira da Serra da Cordilheira Sombria. Fique de pé sobre ele, concentre-se, e despeje esse troço em você $Gtodo:toda;. Isso deve ser o suficiente para um deslocamento éter adentro e para fazer você ver o que está lá de verdade.$B$BVocê não vai estar só... O tesouro dos sátiros é guardado pelo maior espreitador do vazio que eles conseguiram evocar. Derrote ele e o tesouro é seu.$B$BE volte $Ginteiro:inteira; ou essa mina doida vai me fritar!', '', '', '', '', '', '', 'Vorlus', 'Agora, não se mexa.', 'Arcanista Delaris', 'Fale novamente com a Arcanista Delaris nas Ruínas de Constellas, que ficam na Selva Maleva.', 0),
(28045, 'ptBR', 'O melhor sabor do mundo!', 'Consiga 8 Colheradas de Meleca de Silitídeo.', 'Encontrei o lugar perfeito para nossa câmara de refrigeração: uma caverninha abaixo de nós, enorme! Ela é tão grande que cabe todo o nosso estoque e ainda sobra espaço!$B$BO problema é que, quando estávamos quase terminando de montar todos os canos, saíram insetos do nada e mataram todos os meus empregados!$B$BComo é que eu ia saber?$B$BEis que, então, tive uma epifania: sorvete sabor silitídeo. Vai ser um estouro!$B$BSó falta conseguir os ingredientes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pena Tabwa no Sítio Arqueológico Submerso, que fica em Mil Agulhas.', 0),
(28046, 'ptBR', 'Feche o caixão', 'Mate 5 Soldados Incansáveis de Infantaria no Front Incansável. A frente fica no oeste da ilha, pouco antes da Colina Esquecida.', 'Passamos a semana toda tentando coletar mais sucata aproveitável no front, mas sempre que completamos uma remessa, somos atacados pelos incansáveis soldados de infantaria. Seria muito útil se você pudesse ir lá e acabar com todos eles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Paranhos na Base de Operações de Baradin, após cumprir a missão.', 0),
(28047, 'ptBR', 'Congelando os canos', 'Use o Canhão Criogênico de Pico-léguas para congelar quatro canos dentro da caverna.', 'É hora de estrearmos o Canhão Criogênico de Pico-léguas!$B$BUsamos a tecnologia dos canhões de gelo das barcaças. Se tem uma coisa em que os gnomos são bons é a miniaturização através do agigantamento de tudo ao redor do objeto!$B$BPreciso que você leve o canhão até as cavernas e congele os canos que instalamos nas paredes. Isso vai fazer com que eles peguem no tranco!', '', 'Primeiro cano congelado', 'Segundo cano congelado', 'Terceiro cano congelado', 'Quarto cano congelado', '', '', '', '', 'Fale novamente com Pena Tabwa no Sítio Arqueológico Submerso, que fica em Mil Agulhas.', 0),
(28048, 'ptBR', 'Não sabe brincar, não desce pra caverna', 'Mate o Controlador da Colmeia.', 'Existe algum insetinho espertalhão no fundo da caverna que está controlando todos os silitídeos.$B$BMinha mercadoria está derretendo! Como é que eu vou erguer meu império do sorvete se aquela coisa está lá embaixo, destruindo meu estoque?', '', '', '', '', '', '', 'Controlador da Colmeia', '', '', 'Fale novamente com Pena Tabwa no Sítio Arqueológico Submerso, que fica em Mil Agulhas.', 0),
(28049, 'ptBR', 'Veja o invisível', 'Colete 8 porções de Gosma Amaldiçoada das Ruínas de Constellas.', 'É, tá bem, aquela sua amiga feiticeira convencida acertou na mosca. Os diabretes da Serra da Cordilheira Sombria esconderam a chave da barreira dos sátiros no éter. Ela está bem ali, mas não pode ser vista ou tocada a não ser que você esteja em outro plano.$B$BMas acho que você deu azar, já que só diabretes conseguem transitar entre planos! Então, só lhe resta fechar os olhos, virar de costas e me soltar...$B$BFoi só uma piada! Não me machuque! Vou precisar do visgo das gosmas amaldiçoadas que se arrastam por estas ruínas. Traga o bastante para cobrir você dos pés à cabeça!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Diabretim nas Ruínas de Constellas, que fica na Selva Maleva.', 0),
(28050, 'ptBR', 'Tubarão Adamastor', 'Você recebeu ordens para matar Adamastor, um tubarão enorme que aterroriza as águas do Cabo da Má Esperança. O cabo fica ao norte, seguindo pela costa.', 'Odeio tubarões. Todos os meus soldados odeiam tubarões também. É aí que você entra, $n.$b$bVá ao Cabo da Má Esperança e mate um tubarão imenso chamado Adamastor. Ele não está para brincadeira, então acho melhor você levar alguns amigos.', '', '', '', '', '', '', 'Adamastor', '', '', 'Apresente-se novamente ao Comandante-de-campo Abreu na Base de Operações de Baradin após cumprir a missão.', 0),
(28051, 'ptBR', 'Todos estão loucos... e mortos... por sorvete!', 'Prenda o gancho do reboque em 10 Empregados Mortos.', 'Não me entenda mal... posso parecer alegre, mas meu coração está partido em pedacinhos. Todos os meus amigos e empregados estão mortos.$B$BVocê poderia me fazer um favor? Poderia nadar até lá embaixo e prender o gancho do reboque nos meus antigos companheiros? Vou puxá-los para cá.', '', 'Empregados Mortos enganchados', '', '', '', '', '', '', '', 'Fale novamente com Pena Tabwa no Sítio Arqueológico Submerso, que fica em Mil Agulhas.', 0),
(28052, 'ptBR', 'Operação: mexer o caldeirão', 'Fale com o mestre de voo do Posto de Tório e, então, use as armas da Máquina Voadora da Irmandade para matar Defensores do Caldeirão até que a área esteja segura para entrar.', 'Vou colocar você em uma máquina voadora, $n.$b$bVocê ficará responsável por facilitar a nossa aterrissagem no fosso de lava. Fale com o mestre de voo aqui no Posto de Tório e, então, voe para a garganta.$b$bPerto do local de pouso certamente haverá hordas de anões Ferro Negro à sua espera. Use as armas da máquina voadora para matar quantos deles você puder, e então aterrisse na entrada da caverna. O Rendan já deverá estar à sua espera quando você chegar.', '', 'Garanta a entrada no Fosso de Lava', '', '', '', '', '', '', '', 'Fale com o Senhor da Montanha Rendan na entrada do Fosso de Lava, que fica na Garganta Abrasadora.', 0),
(28053, 'ptBR', 'O Lanque gosta do seu estilo', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28054, 'ptBR', 'Escravidão é uma coisa feia', 'Mate 10 Capatazes Ferro Negro ou Feitores Ferro Negro.', 'Assim como o feitor Maltorius, sou um anão rico. Contudo, conquistei a minha riqueza com trabalho duro e decisões sábias, não com escravidão.$b$bTá bom, só um pouquinho de escravidão. Quase nenhuma.$b$bDe qualquer forma, as primeiras coisas que vejo dentro destas cavernas são feitores de escravos e capatazes. Não vou deixar isso assim! À medida que você progredir pela caverna, mate quantos você puder. Reporte os resultados a Evonice Fumarenta, mais ao fundo do Fosso de Lava.', '', 'Capatazes ou Feitores Ferro Negro mortos', '', '', '', '', '', '', '', 'Fale com Evonice Fumarenta dentro do Fosso de Lava, que fica na Garganta Abrasadora.', 0),
(28055, 'ptBR', 'Doce e horrível liberdade', 'Liberte 12 Trabalhadores Escravos. Se eles resistirem, mate-os.', 'É claro que vamos querer libertar quantos escravos pudermos enquanto estivermos aqui. É provável que a maioria se alie a nós, ansiosa por lutar contra seus captores.$b$bContudo, você verá que, às vezes, os escravos resistem à liberdade. É um fenômeno estranho, muitas vezes chamado de "Síndrome do Forte do Desterro".$b$bDe qualquer forma, é melhor que você tente libertá-los. Se eles resistirem, trate-os como inimigos. Reporte os resultados a Evonice Fumarenta, mais ao fundo do Fosso de Lava.', '', 'Trabalhadores Escravos libertados ou mortos', '', '', '', '', '', '', '', 'Fale com Evonice Fumarenta dentro do Fosso de Lava, que fica na Garganta Abrasadora.', 0),
(28056, 'ptBR', 'Erga-se, Obsidião', 'Use o Altar de Suntara e, então, mate Latórico, o Negro, e Obsidião.', 'O feitor Maltorius está no comando por aqui, mas ele não é o único anão poderoso dentro do Fosso de Lava. Latórico, o Negro, e o terrível golem que o segue, Obsidião, espreitam logo adiante, neste corredor.$b$bInterferir com o altar do Latórico deve evocar os dois. Encontre esse altar, evoque Latórico e mate-o. Fale com Evonice Fumarenta quando terminar.', '', '', '', '', '', '', '', '', '', 'Fale com Evonice Fumarenta dentro do Fosso de Lava, que fica na Garganta Abrasadora.', 0),
(28057, 'ptBR', 'Mate-os de sono', 'Obtenha 16 Travesseiros de Ferro Negro.', 'Poucos sabem que os anões, especialmente do tipo Ferro Negro, precisam de descanso! Muito descanso!$B$BAssim sendo, pergunto: como eles podem dormir sem travesseiros? Pois é, $n, eles não podem. É por isso que você precisa roubar os travesseiros deles.$b$bQuando você terminar a coleta, vá falar com o capataz Scrange. Ele está um pouco mais ao fundo da caverna, trabalhando em um projeto secreto com o Hansel.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Capataz Scrange dentro do Fosso de Lava, que fica na Garganta Abrasadora.', 0),
(28058, 'ptBR', 'Olha o tamanho disso!', 'Leve o Travesseiro da Camareira Alma Fada para Evonice Fumarenta, na Garganta Abrasadora.', 'Ora, ora, ora... Mas que surpresa. A camareira tinha um enorme travesseiro ornado, e ele agora é seu. É certo que Evonice Fumarenta vai querer botar as mãozinhas imundas neste item. Leve-o para ela e veja se você consegue algo de útil pelo seu esforço.', '', '', '', '', '', '', '', '', '', '', 0),
(28059, 'ptBR', 'A retomada do Forte', 'Você recebeu ordens para matar o Castelão Farson no Forte Farson, que fica no norte da ilha.', 'Você viu o forte no norte da ilha, $n? É de lá que o castelão Farson organiza a operação.$b$bFarson tem um pequeno grupo de seguidores dedicados que são um grande problema para nós desde que chegamos aqui. Enviamos alguns homens para investigar, e eles nos informaram a posição exata de Farson dentro do forte.$b$bSerá que você consegue dar um fim nele?', '', '', '', '', '', '', 'Castelão Farson', '', '', 'Apresente-se novamente ao Comandante Marco Gama na Base de Operações de Baradin após cumprir a missão.', 0),
(28060, 'ptBR', 'Laços retorcidos do crepúsculo', 'Fale com o Hansel Mão-pesada e ajude-o a atacar o Feitor Maltorius e o Lorde do Crepúsculo Arkkus.', 'O Hansel e eu viemos para cá com uma missão secreta: matar o feitor Maltorius. Apesar do nosso objetivo principal continuar o mesmo – derrotar o arquiduque Calcinder – não há mal algum em eliminarmos o infame feitor do Fosso de Lava enquanto estamos aqui.$b$bO problema é que o Hansel estava preparado para lutar contra apenas um anão, e parece que o Maltorius está com visita... Um emissário do Martelo do Crepúsculo!$b$bFale com o Hansel e ajude-o. Feito isso, siga adiante neste corredor e ao longo da sacada do lado de fora para encontrar o feitor Mão-de-graxa.', '', '', '', '', '', '', '', '', '', 'Fale com o Feitor Mão-de-graxa no Fosso de Lava, que fica na Garganta Abrasadora.', 0),
(28061, 'ptBR', 'Lacaios de Calcinder', 'Mate 6 Flamespectros Abrasadores.', 'É preciso cuidado para não cavar fundo demais, $n. Se, por um lado, os minerais mais ricos estão muito abaixo da superfície, também é lá que estão as criaturas mais malignas.$b$bEsse é o caso dos elementais de fogo.$b$bOs lacaios de Calcinder perambulam pela caverna à frente. Todos eles guardam um pouco do mal de Calcinder. Mate quantos você puder, e não tenha piedade.', '', '', '', '', '', '', '', '', '', '', 0),
(28062, 'ptBR', 'De onde ele veio', 'Enfraqueça o Arquiduque Calcinder e, então, use a Tripetricina Consagrada para bani-lo.', 'O arquiduque Calcinder se contorce no fundo desta exata caverna. Estamos perto de matá-lo... Mas não é o que faremos agora.$b$bMatarmos o Calcinder, aqui, de nada vale. Os acólitos dele podem ressuscitá-lo facilmente. Ao invés disso, vamos bani-lo.$b$bMais cedo, pedi a você que coletasse uma pedra preciosa do Martelo do Crepúsculo. Agora, você a usará contra o Calcinder. Aborde o Arquiduque, enfraqueça-o e, então, use este dispositivo. Ele será banido deste plano.$b$bBoa sorte, brav$go:a; $n.', '', 'Arquiduque Calcinder banido', '', '', '', '', 'Arquiduque Calcinder', '', '', '', 0),
(28063, 'ptBR', 'Armas recauchutadas', 'Obtenha 12 Rifles Enferrujados no Forte Farson, que fica no norte da Península de Tol Barad.', 'Não encontramos muitos suprimentos de batalha nesta rocha esquecida. Parece que estamos enfrentando a Horda com paus e pedras.$B$BDe acordo com os relatórios, o castelão Farson tem um estoque enorme de rifles que poderia vir a calhar. Você pode ir lá e dar uma olhada?$b$bTome cuidado, $n. Os seguidores do Farson farão de tudo para protegê-lo.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Marco Gama na Base de Operações de Baradin após cumprir a missão.', 0),
(28064, 'ptBR', 'Boas-vindas à Irmandade', 'Fale com o Feitor Mão-de-graxa no Posto de Tório, que fica na Garganta Abrasadora.', 'Você deve voltar para o Posto de Tório. O feitor Mão-de-graxa e o resto da Irmandade do Tório devem estar curiosos para saber como foi a sua luta contra Calcinder.', '', '', '', '', '', '', '', '', '', '', 0),
(28065, 'ptBR', 'Trabalho no cangote dos outros é refresco', 'Escolte um Prisioneiro do Forte Farson até um local seguro. O forte fica no extremo noroeste da ilha.', 'Enviamos pelo menos três grupos de reconhecimento para investigar o Forte Farson nas últimas semanas. Infelizmente nenhum deles voltou ainda, e não temos informações do que está acontecendo.$B$BA essa altura, já até estou torcendo para que eles tenham sido feitos prisioneiros e estejam bem. Você precisa se infiltrar na bastilha e ajudar a resgatar os soldados. Não será fácil, $n, mas você é a nossa última chance.', 'Prisioneiro de Farson escoltado', '', '', '', '', 'Prisioneiro de Farson escoltado', 'Prisioneiro de Farson', '', '', 'Apresente-se novamente ao Comandante Marco Gama na Base de Operações de Baradin após cumprir a missão.', 0),
(28068, 'ptBR', 'Procura-se aventureiros: Abismo Rocha Negra', 'Fale com Morgan.', 'Sua Majestade o Rei Varian Wrynn convoca todos os aventureiros fisicamente aptos a se dirigirem imediatamente ao Abismo Rocha Negra, a noroeste da Vigia de Morgan!$B$BOs anões Ferro Negro ameaçam todos os cidadãos de Cristarrubra! Se assim o desejar, vá ao Abismo Rocha Negra e fale com Morgan, que voltou de um longo recesso e anseia por vingança contra o povo Ferro Negro.', '', '', '', '', '', '', '', '', '', '', 0),
(28069, 'ptBR', 'Procura-se aventureiros: Abismo Rocha Negra', 'Fale com o Alto-carrasco Nuzrak.', 'O Chefe Guerreiro convoca todos os aventureiros fisicamente aptos a se dirigirem imediatamente ao Abismo Rocha Negra, a oeste do Monte Candente!$B$BOs anões Ferro Negro já atacaram Cristarrubra, uma área dominada pela Aliança. Se não controlarmos a situação, eles poderão avançar sobre as poucas bases da Horda no sul de Azeroth.$b$bSe assim o desejar, vá ao Abismo Rocha Negra e fale com o alto-carrasco Nuzrak, que está reorganizando a Força Expedicionária de Karrath para acabar com os Ferro Negro de uma vez por todas.', '', '', '', '', '', '', '', '', '', '', 0),
(28084, 'ptBR', 'O poder de Krom\'gar', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28085, 'ptBR', 'Problemas em Alcândora', 'Fale com Pae\'ka Monte Veloz em Alcândora, que fica em Mil Agulhas.', 'Obrigada pela ajuda, $n. Converse com Pae\'ka Monte Veloz em Alcândora, a sudoeste daqui.$B$BTalvez ele saiba o paradeiro da Bruxa Anciã.', '', '', '', '', '', '', '', '', '', '', 0),
(28086, 'ptBR', 'Liberte os filhotes de mantícora', 'Liberte 12 Filhotes de Mantícora de Alcândora.', 'Coureadores estão aprisionando os filhotes de mantícora, $n. Por favor, ajude-me a libertá-los!', '', 'Filhotes de Mantícora libertados', '', '', '', '', '', '', '', 'Fale novamente com Pae\'ka Monte Veloz em Alcândora, que fica em Mil Agulhas.', 0),
(28087, 'ptBR', 'Morte aos coureadores!', 'Consiga 8 Redes de Coureadores.', 'Só existe uma solução para aqueles malditos coureadores do Martelo do Crepúsculo: a morte!$B$BE traga-me as redes deles, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Pae\'ka Monte Veloz em Alcândora, que fica em Mil Agulhas.', 0),
(28088, 'ptBR', 'Liberte Lamicárdio', 'Liberte Lamicárdio das cordas que o prendem.', 'O Martelo do Crepúsculo aprisionou o macho alfa de Alcândora. Suba a rampa a leste e liberte-o antes que as mantícoras percam o patriarca!', '', 'Lamicárdio libertado', '', '', '', '', '', '', '', 'Fale novamente com Pae\'ka Monte Veloz em Alcândora, que fica em Mil Agulhas.', 0),
(28089, 'ptBR', 'Ordens do Chefe Guerreiro: Contraforte de Eira dos Montes!', 'Fale com a Alta Executora Darthalia no Portão do Sul do Contraforte de Eira dos Montes.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, convocados a se apresentarem à Alta Executora Darthalia no Portão do Sul do Contraforte de Eira dos Montes. A máquina de guerra renegada avança, assegurando Lordaeron para a Horda!$B$BPara chegar ao Portão Sul, siga a estrada para o sul através da Floresta de Pinhaprata e depois ao leste na bifurcação para Contraforte de Eira dos Montes.$B$BAvante, irmãos e irmãs! O destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28090, 'ptBR', 'Bens preciosos', 'Recupere uma Pedra-portal da Caravana do Crepúsculo. As chaves dos baús com a pedra-portal devem estar com os Lanceadores.', 'Os portões abaixo do cânion estão fechados. Nossas patrulhas descobriram um tipo de pedra, que eles carregam em baús nas caravanas, usada para abrir os portões.$B$BVá lá e procure uma chave de baú junto aos corpos dos guardas. Quando achar ela, use num dos baús nas carroças da caravana e traga a pedra-portal pra mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Mathiaz no Desfiladeiro da Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(28091, 'ptBR', 'Presas fáceis', 'Mate 8 Lanceadores do Crepúsculo.', 'A emboscada aconteceu sem grandes dificuldades. A maioria dos guardas está morta, mas alguns ainda estão pelas carroças.$B$BVocê pode ver eles a oeste daqui, cânion abaixo. Vá até lá e mande eles dessa pra melhor pra gente poder continuar o ataque.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Mathiaz no Desfiladeiro da Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(28092, 'ptBR', 'Se a chave servir...', 'Lidere o G.O.P.E. até o Portão Presa do Dragão fechado.$B$BCaso se perca do G.O.P.E., fale novamente com o Senhor da Guerra Krogg para recomeçar.', 'As serpes já estão lutando nos céus sobre Grim Batol. O transporte de nossos homens por terra e a proteção dos portões dependem de nós.$B$BQuero que você saiba o que está em jogo aqui, $c. Grim Batol é a fonte dos reforços do Martelo do Crepúsculo no Planalto. Se não expulsarmos eles daqui, não vamos vencer as próximas batalhas.$B$BEstou enviando o G.O.P.E. para ajudar você. Vá até o portão a sudeste daqui e abra-o. Mathiaz dará mais instruções para você lá.', '', 'Portão Presa do Dragão aberto', '', '', '', '', '', '', '', 'Fale com Mathiaz na Curva das Serpes, que fica no Planalto do Crepúsculo.$B$BFale com o Senhor da Guerra Krogg na Curva das Serpes, que fica no Planalto do Crepúsculo, se você não estiver mais com Mathiaz.', 0),
(28093, 'ptBR', 'Adiante com a pressão', 'Leve o G.O.P.E. do Portão Presa à entrada de Grim Batol.$B$BCaso se perca do G.O.P.E., volte até o Senhor da Guerra Krogg para reapresentar-se.', 'Até agora, bom trabalho. A entrada de Grim Batol deve ser logo depois do próximo portão.$B$BMinhas ordens são vigiar a entrada e impedir a passagem de reforços enquanto o resto de nossos homens abrem caminho pelo cânion. Acho que, se a gente chegar logo lá, talvez eu deixe Tique se divertir um pouquinho mais.$B$BVamos seguir para sudoeste do cânion, assim vamos achar o próximo portão bem rápido.', '', 'Entrada de Grim Batol assegurada', '', '', '', '', '', '', '', 'Fale com Calen próximo à entrada de Grim Batol, que fica no Planalto do Crepúsculo.', 0),
(28094, 'ptBR', 'Abrindo caminho', 'Mate 30 sectários do Martelo do Crepúsculo ao longo da Curva das Serpes enquanto você se dirige para a entrada de Grim Batol.', 'Tenho ordens para acompanhar você ao norte pelos Portões Presa do Dragão em direção à entrada de Grim Batol. Devemos abrir caminho para que o resto dos homens sigam a gente e protejam a entrada.$B$BTraduzindo: mate tudo que se move e não tenha vergonha se você se divertir fazendo isso.$B$BOs rapazes estão ficando impacientes. Vamos!', '', 'Sectários da Curva das Serpes assassinados', '', '', '', '', '', '', '', 'Fale com Mathiaz na Curva das Serpes, que fica no Planalto do Crepúsculo.$B$BFale com o Senhor da Guerra Krogg na Curva das Serpes, que fica no Planalto do Crepúsculo, se você não estiver mais com Mathiaz.', 0),
(28096, 'ptBR', 'Ouro de tolo', 'Distribua 3 Missões.', 'Eu devia estar contente porque tenho um emprego, sou a dita morta-viva respeitável e ganho quatro mil ouros semana não, semana sim. Eu devia agradecer à Dama Sylvana por ter este cargo elevado, deveria estar feliz por ter comprado um corcel tão morto assim. Mas confesso, estupefata, que estou decepcionada com esses malucos que aparecem para me pedir missões. Agora eu me pergunto, e daí? E portanto você vai entregar estas ordens aos integrantes da hora, grandessíssimos idiotas, ridículos, limitados, que só usam dez por cento das cabeças animais. Eu é que não me sento no alto do corcel descarnado - vai ser você, quando estiver pronto, com a boca escancarada, cheia de dentes, esperando a morte passar. E olha, você vai esperar um tempão...', '', 'Primeira Missão Repassada', 'Segunda Missão Repassada', 'Terceira Missão Repassada', '', '', '', '', '', 'Fale com a Alta-executora Darthalia no Portão do Sul do Contraforte de Eira dos Montes.', 0),
(28097, 'ptBR', 'Os portões de Grim Batol', 'Fale com o Senhor da Guerra Krogg no Desfiladeiro da Presa do Dragão.', 'O Krogg deu início ao ataque que vai varrer o cânion. Ele acabou de passar pelo portão a sudeste daqui.$B$BVou reunir o esquadrão para a gente se juntar ao ataque. Te encontro lá embaixo.', '', '', '', '', '', '', '', '', '', '', 0),
(28098, 'ptBR', 'Mestre Crepuscular dos Ares', 'Consiga uma carona com Lamicárdio até o Refúgio do Crepúsculo e acabe com o Mestre Crepuscular dos Ares Korpuskein.', 'O Mestre Crepuscular dos Ares está lá em cima, a sudeste daqui, no Refúgio do Crepúsculo. De nada adiantarão nossos esforços para salvar Alcândora aqui embaixo se não acabarmos com ele.$B$BLamicárdio ainda está muito fraco para lutar, mas ele $Go:a; levará até lá. O resto é com você, $n.$B$BBoa sorte.', '', 'Consiga um voo com Lamicárdio', 'Mestre Crepuscular dos Ares Korpuskein morto', '', '', '', 'Mestre Crepuscular dos Ares Korpuskein', '', '', 'Fale novamente com Pae\'ka Monte Veloz em Alcândora, que fica em Mil Agulhas.', 0),
(28099, 'ptBR', 'Rasha\'krak', 'Obtenha as Braçadeiras da Vinculação de Rasha\'krak.', 'Com base nas informações que você entregou, acredito que um dos lacaios desse "arquiduque" possa já ter voltado os olhos para o Posto de Tório.$b$bO nome dele é Rasha\'krak, e ele patrulha as poças de lava logo ao sul. Ele parece com os elementais de fogo latente que devastam a região, exceto por uma pequena diferença: as braçadeiras da vinculação que envolvem os punhos dele.$b$bEncontre-o e traga essas braçadeiras para mim, $n. Preciso de uma prova de que não estamos mais em perigo antes que nos envolvamos em guerras elementais.', '', '', '', '', '', '', 'Rasha\'krak', '', '', 'Fale novamente com o Feitor Mão-de-graxa no Posto de Tório, que fica na Garganta Abrasadora.', 0),
(28100, 'ptBR', 'Um totem falante', 'Fale com o Totem de Ruumbo, próximo à Vila da Lenha Morta.', 'A vila dos pelursos ao sul é o lar da tribo Lenha Morta, inimigos declarados dos Presamatos. Eles são tão sórdidos e torpes como tantos outros ensandecidos pela mácula desta floresta.$B$BAlgo incomum aconteceu próximo à aldeia, contudo. Uns viajantes que vinham para cá disseram que o totem próximo à estrada falou com eles.$B$BJamais ouvi coisa alguma ao aproximar-me dele. Será que ele falará com você, $n? Talvez você consiga descobrir o que está acontecendo.', '', '', '', '', '', '', '', '', '', '', 0),
(28101, 'ptBR', 'O comando de Mathias', 'Fale com o Mestre Mathias Shaw no Desfiladeiro da Presa do Dragão.', 'Acontecimentos recentes tornam mais evidente que se esconder por aqui e realizar ataques esporádicos a Grim Batol não é o suficiente para manter nossa espécie a salvo, muito menos para retomar Grim Batol. Precisamos ser mais agressivos e atacá-los direto no coração.$B$BEu concordei em mandar dragões para ajudar seus comandantes. Eles já estavam planejando um ataque a Grim Batol e você deveria concentrar sua atenção nesse lugar.$B$BEncontre Mathias Shaw no Desfiladeiro da Presa do Dragão, no cânion a sul daqui.', '', '', '', '', '', '', '', '', '', '', 0),
(28102, 'ptBR', 'Faça a coisa certa', 'Mate 8 Desgarrados Flamejade ou Assombrantes Flamejade nas Ruínas de Constellas.', 'É chegada a hora do derradeiro golpe contra os Flamejade!$B$BJá que você está $Gpreparado:preparada; para atravessar a barreira infame e enfrentar o líder deles, eu também lhe pedirei ajuda contra os sátiros inferiores. Nossos druidas lutam com violência, mas a sua força pode ajudar a mudar o curso da batalha.$B$BMostre aos Flamejade que eles não mais dominarão estas terras!', '', 'Desgarrados ou Assombrantes Flamejade mortos', '', '', '', '', '', '', '', 'Fale novamente com Eridan Brisazul nas Ruínas de Constellas, que fica na Selva Maleva.', 0),
(28103, 'ptBR', 'Presas fáceis', 'Mate 8 Lanceadores do Crepúsculo.', 'A emboscada aconteceu sem grandes dificuldades. A maioria dos guardas está morta, mas alguns ainda estão nas carroças.$B$BVá até lá e elimine-os para que possamos avançar pelos cânions.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mathias Shaw no Desfiladeiro da Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(28104, 'ptBR', 'Bens preciosos', 'Recupere uma Pedra-portal da Caravana do Crepúsculo. As chaves dos baús com a pedra-portal devem estar com os Lanceadores.', 'Os portões abaixo do cânion estão fechados. Nossas patrulhas descobriram uma pedra que eles carregavam nas caravanas, que é usada para abrir os portões.$B$BDesça lá e procure uma chave de baú junto aos corpos dos guardas. Quando achá-la, use num dos baús das carroças da caravana e traga a pedra-portal para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Mathias Shaw no Desfiladeiro da Presa do Dragão, que fica no Planalto do Crepúsculo.', 0),
(28105, 'ptBR', 'Kavem, o Caloso', 'Roube a Chave de Neferset de Kavem, o Caloso.', 'Kavem já era cruel o bastante antes dos Neferset entrarem em acordo com Asa da Morte. Seu prazer em deflagrar a dor agora beira a loucura.$B$BÉ ele quem guarda as chaves de nossos grilhões.$B$BEle habita o edifício próximo a nós, à direita.$B$BEncontre-o e pegue as chaves. Não hesite nem tenha piedade. Ele cortará sua garganta sem pestanejar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Príncipe Nadun na Cidade Perdida dos Tol\'vir em Uldum.', 0),
(28106, 'ptBR', 'Os portões de Grim Batol', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28107, 'ptBR', 'Abrindo caminho', 'Mate 30 sectários do Martelo do Crepúsculo ao longo da Curva das Serpes enquanto você se dirige para a entrada de Grim Batol.', 'Tenho ordens para acompanhar você ao norte pelos Portões Presa do Dragão em direção à entrada de Grim Batol. Devemos abrir caminho para que o resto dos homens sigam a gente e protejam a entrada.$B$BTraduzindo: mate tudo que se move e não tenha vergonha se você se divertir fazendo isso.$B$BOs rapazes estão ficando impacientes. Vamos!', '', 'Sectários da Curva das Serpes assassinados', '', '', '', '', '', '', '', 'Fale com o Tenente de Beiralta na Curva das Serpes, que fica no Planalto do Crepúsculo.$B$BSe você não estiver mais com seu esquadrão, fale com o Mestre Mathias Shaw na Curva das Serpes, que fica no Planalto do Crepúsculo.', 0),
(28108, 'ptBR', 'Se a chave servir...', 'Lidere o esquadrão de Beiralta ao Portão Presa do Dragão fechado.$B$BCaso perca o esquadrão, volte ao Mestre Mathias Shaw para reapresentar-se.', 'As serpes já estão lutando nos céus sobre Grim Batol. O transporte de nossos homens por terra e a proteção dos portões dependem de nós.$B$BQuero que você saiba o que está em jogo aqui, $c. Grim Batol é a fonte dos reforços do Martelo do Crepúsculo no Planalto. Se não expulsarmos eles daqui, não vamos vencer as próximas batalhas.$B$BEstou enviando uma tropa de Beiralta para ajudar você. Vá até o portão a sudeste daqui e abra-o. Seu tenente lhe dará mais instruções lá.', '', 'Portão Presa do Dragão aberto', '', '', '', '', '', '', '', 'Fale com seu Tenente de Beiralta na Curva das Serpes, que fica no Planalto do Crepúsculo.$B$BFale com o Mestre Mathias Shaw na Curva das Serpes, que fica no Planalto do Crepúsculo, se você não estiver mais com seu esquadrão.', 0),
(28111, 'ptBR', 'Confusão em Veioazul', 'Fale com o Capitão Caetano na Mina Veioazul, no Contraforte de Eira dos Montes.', 'A produtividade de nossa fazenda de aranhas na Mina Veioazul está estagnada. O capitão Caetano solicitou que enviássemos ajuda imediatamente. Ele alega que as aranhas da mina são insubordinadas e estão fora de controle. Além disso, um grupo de murlocs costeiros está saqueando nossos suprimentos. Quero que você vá lá e verifique a situação. Ajude Caetano e o tratador de aranhas, $n.$B$BA Mina Veioazul fica a sudeste, próximo à costa.', '', '', '', '', '', '', '', '', '', '', 0),
(28112, 'ptBR', 'Fuga da Cidade Perdida', 'Liberte o Príncipe Nadun e fale com o Rei Phaoris em Ramkahen, que fica em Uldun.', 'Está tudo pronto! Livre-me dessas correntes e liberte seus amigos.$B$BDevemos sair rápido, antes que a escória neferset desconfie de algo!$B$BSe conseguirmos, procure meu irmão, o Rei Phaoris, para ser recompensado.', '', '', '', '', '', '', '', '', '', '', 0),
(28113, 'ptBR', 'Quebre o inquebrável', 'Mate Xavathras.', 'Com a garra, estamos prontos para romper as defesas dos Flamejade.$B$BVá para as ruínas a noroeste daqui. Além da linha de frente dos sátiros, há uma passagem estreita que levará você ao corrompido portal lunar deles. Uma enorme muralha de fogo demoníaco bloqueia o caminho, mas a Garra de Taecondrius deve ser capaz de dissipá-la.$B$BAlém da barreira, você encontrará o líder destas forças, Xavathras, guardando o poço lunar corrompido. Mate-o!', '', '', '', '', '', '', 'Xavathras', '', '', 'Fale novamente com a Arcanista Delaris nas Ruínas de Constellas, que ficam na Selva Maleva.', 0),
(28114, 'ptBR', 'Colheita bendita', 'Recupere 60 Ovos de Rastejante.', 'Diretamente a sudeste do Portão Sul, você achará nossas operações de domesticação de aranhas. Através dos anos, desenvolvemos laços com as aranhas de Eira dos Montes e conseguimos domesticar e criar essas adoráveis criaturinhas. Agora elas nos servem tanto como animais domésticos quanto como feras de guerra! Como são multifacetadas!$B$BVá até os campos a sudeste e colete cuidadosamente os ovos que incubamos nos ursos. Entregue a coleta a Sarus na mina.', '', '', '', '', '', '', '', '', '', 'Entregue os ovos de rastejante à Tratadora de Aranhas Sarus na Mina Veioazul, no Contraforte de Eira dos Montes.', 0),
(28115, 'ptBR', 'O destino dos ursos', 'Mate 8 Ursos Infestados.', 'Os ursos são feras desalmadas, criadas apenas para nos atormentar. Só mesmo a engenhosidade dos Renegados seria capaz de descobrir alguma utilidade para eles! Nós usamos os ursos como hospedeiros em nossas fazendas de aranhas. As aranhas depositam ovos na carne dos ursos, e as crias crescem nutridas pela carne e pelo sangue das feras.$B$BDepois de servirem a esse propósito, os ursos precisam ser abatidos. Vá para o sudeste e mate os ursos infestados que já cumpriram seus destinos.', '', '', '', '', '', '', '', '', '', 'Fale com a Tratadora de Aranhas Sarus na Mina Veioazul, no Contraforte de Eira dos Montes.', 0),
(28116, 'ptBR', 'Violeta chorosa', 'Colha 8 Violetas Chorosas.', 'Temos que nos preparar cuidadosamente antes de atacarmos Jaedenar. A magia dos bruxos e demônios de lá é forte, e temos que nos proteger antes de entrar.$B$BJá preparei muitas ervas e preciso de apenas mais um ingrediente: a violeta chorosa que cresce nas montanhas ao sul. Essa flor adaptou-se até mesmo a estas terras contaminadas, um testemunho da força e pureza dela.$B$BColha a violeta chorosa para mim, mas tenha cautela com as criaturas corrompidas da floresta.', '', '', '', '', '', '', '', '', '', 'Entregue as Violetas Chorosas a Andalar Valumbra em Jaedenar, que fica na Selva Maleva.', 0),
(28117, 'ptBR', 'Tirando o mofo', 'Você recebeu ordens para matar 9 fantasmas de qualquer tipo nas Profundezas Amaldiçoadas, logo a leste da Guarnição Baradin.', 'Você é um colírio para os meus olhos, $n. Conseguimos tomar Tol Barad, mas a batalha está apenas começando.$B$BDescobrimos uma prisão a leste daqui e precisamos que você faça uma limpeza nela. Acontece que o lugar está lotado de fantasmas, trancados lá desde o tempo da Jaka\'Cola com rolha.$b$bMate o máximo que conseguir e depois fale comigo novamente.', '', 'Fantasmas Exterminados', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Stevens na Guarnição Baradin após cumprir a missão.', 0),
(28118, 'ptBR', 'O arquimago trancafiado', 'Mate o Arquimago Galus nas Profundezas Amaldiçoadas e traga o Cajado dele. As Profundezas Amaldiçoadas ficam a leste da Guarnição Baradin.', 'Estamos tentando tirar os fantasmas da prisão das Profundezas Amaldiçoadas desde que atracamos em Tol Barad. Mas, sempre que chegamos perto, aquele maldito arquimago aparece e nos expulsa.$B$BAgora a ilha está sob nosso controle, então vamos tentar de novo para ver se muda alguma coisa. Vá lá e traga o cajado dele como prova de que você realizou o que não conseguimos.', '', '', '', '', '', '', 'Arquimago Galus', '', '', 'Apresente-se novamente ao Comandante Stevens na Guarnição Baradin após cumprir a missão.', 0),
(28119, 'ptBR', 'Da corrupção, a pureza', 'Encha o Cantil Vazio com a água do poço lunar corrompido, no centro de Jaedenar.', 'As flores que você me trouxe foram o ingrediente essencial.$B$BBarreiras protetoras cercam a fortaleza, projetadas a partir de braseiros demoníacos. Se quisermos expulsar o Concílio das Sombras da Selva Maleva, temos que apagar os braseiros.$B$BEste frasco foi energizado com violeta-chorosa e com a magia das selvas. Encha-o no poço lunar corrompido, que fica no centro de Jaedenar, e volte aqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Andalar Valumbra em Jaedenar, que fica na Selva Maleva.', 0),
(28120, 'ptBR', 'O passado também ensina', 'Você recebeu ordens de recuperar 4 Diários de Prisão Empoeirados das Profundezas Amaldiçoadas, bem a leste da Guarnição Baradin.', 'Finalmente conseguimos dominar esta ilha maldita, e agora podemos começar a investigar como ela ficou assim. Algumas das nossas tropas encontraram diários perto da entrada da prisão das Profundezas Amaldiçoadas, a leste daqui.$B$BAcho que os anciãos escribas do campo-base terão um interesse especial na nossa descoberta. Quero que você me traga quatro diários o quanto antes.$B$B$n, tome bastante cuidado. A região está infestada de mortos-vivos.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Stevens na Guarnição Baradin após cumprir a missão.', 0),
(28121, 'ptBR', 'Forças de Jaedenar', 'Mate 12 membros das forças de Jaedenar.', 'O Concílio das Sombras perpetua a corrupção desta terra. Em Jaedenar, a noroeste daqui, o Concílio louva os demônios da Legião Ardente e trabalha para abrir caminho para que seus mestres retornem a este mundo.$B$BA área de Jaedenar é patrulhada por cães, guardiões, adeptos e sectários, assassinos que atuam como sentinelas das forças inferiores mais vis. Esses serão os primeiros a morrer para que esta floresta não sofra mais.', '', 'Membros das forças de Jaedenar mortos', '', '', '', '', '', '', '', 'Procure Andalar Valumbra em Jaedenar, que fica na Selva Maleva.', 0),
(28122, 'ptBR', 'Um enorme Pobrema', 'Você recebeu ordens para acabar com o Pobrema, um gorjala gigante que vaga pelas estradas de Tol Barad.', 'Finalmente capturamos essa rocha maldita, mas só agora percebemos que há um baita dum gorjala à solta, acabando com as nossas patrulhas!$B$B$n, reúna alguns amigos e mate-o. Não podemos permitir que uma fera dessas fique por aí causando problemas.$B$BFique alerta: pelo que dizem, ele carrega uma árvore gigantesca como arma e não tem medo de usá-la.', '', '', '', '', '', '', 'Pobrema', '', '', 'Apresente-se ao Sargento Paulo na Guarnição Baradin após cumprir a missão.', 0),
(28123, 'ptBR', 'A corrente demoníaca', 'Conquiste a Corrente Demoníaca.', 'Narkrall revelou a mim o segredo da sua influência sobre os dracos nesta área. Pensei que a Corrente Demoníaca fosse um mito, mas ele a possui.$B$BE agora o tolo pode pôr tudo a perder!$B$BA vida dele é insignificante para mim, mas os Presa do Dragão não podem se dar ao luxo de perder esse artefato. Siga Narkrall ao norte até Trondamar. A cidade vai estar um caos, então pode ser que você consiga pousar sem ser $gdetectado:detectada;. Volte a mim com a Corrente Demoníaca, mesmo se for pra tirá-la do cadáver de Narkrall. Encontre o artefato, $n!', '', '', '', '', '', '', '', '', '', 'Leve a Corrente Demoníaca para Zaela na Ravina de Sangue, que fica no Planalto do Crepúsculo.', 0),
(28124, 'ptBR', 'Caminho para o Baluarte', 'Fale com Lakota Cantéolo no Baluarte do Crepúsculo, que fica em Mil Agulhas.', '$n, Lakota Cantéolo passou por aqui enquanto você e os filhotes cuidavam do mestre dos ares. Ela pediu que você a encontre no Baluarte do Crepúsculo, a leste daqui.$B$BDeve ser lá que estão mantendo Magatha Temível Totem.', '', '', '', '', '', '', '', '', '', '', 0),
(28125, 'ptBR', 'Algo para vestir', 'Consiga 10 peças de Armadura do Martelo do Crepúsculo.', 'Tive uma ideia. Já sei como você pode se aproximar dos líderes deles sem ser $gmorto:morta;, mas para isso precisamos de algo para você vestir.$B$BSugiro que você suba até lá e consiga algumas armaduras deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lakota Cantéolo no Baluarte do Crepúsculo, que fica em Mil Agulhas.', 0),
(28126, 'ptBR', 'Extinguindo as chamas da proteção', 'Use a Água Purificada do Poço Lunar para extinguir os quatro Braseiros de Proteção no interior da Fortaleza do Concílio das Sombras.', 'Os braseiros estão espalhados pela Fortaleza do Concílio das Sombras.$B$BProcure a entrada na parte norte de Jaedenar e prossiga até os corredores subterrâneos. Extinga cada uma das chamas dos braseiros para que as proteções preparadas pelo Concílio caiam por ao menos algum tempo.', '', 'Extinga o Braseiro da Dor', 'Extinga o Braseiro da Malícia', 'Extinga o Braseiro do Sofrimento', 'Extinga o Braseiro do Ódio', '', '', '', '', 'Fale novamente com Greta Musgo no Casco no Santuário Esmeralda, que fica na Selva Maleva.', 0),
(28127, 'ptBR', 'Liberte-os!', 'Liberte 5 Prisioneiros do Baluarte, vigiados pelos Carcereiros do Crepúsculo.', 'Magatha não foi a única pessoa a ser sequestrada pelo Martelo do Crepúsculo.$B$BEnquanto estiver lá em cima, liberte o maior número de prisioneiros que puder.', '', 'Prisioneiros do Baluarte libertados', '', '', '', '', '', '', '', 'Fale novamente com Lakota Cantéolo no Baluarte do Crepúsculo, que fica em Mil Agulhas.', 0),
(28128, 'ptBR', 'O círculo interno', 'Mate 12 Defensores da Fortaleza do Concílio das Sombras de Jaedenar.', 'Com as sentinelas fora do caminho, os membros mais importantes do Concílio das Sombras são os próximos.$B$BEles espreitam o interior da Fortaleza do Concílio das Sombras, cuja entrada fica na parte noroeste de Jaedenar. No interior das grutas corrompidas há bruxos poderosos e demônios aterrorizantes.$B$BEles têm de ser derrotados para que essas terras possam ser salvas!', '', 'Defensores da Fortaleza do Concílio das Sombras mortos', '', '', '', '', '', '', '', 'Fale novamente com Jessir Lunarco no Pontal do Coração Selvagem, que fica na Selva Maleva.', 0),
(28129, 'ptBR', 'O príncipe demônio', 'Mate o Príncipe Xavalis.', 'Os sátiros Flamejade, que dominaram quase toda a Selva Maleva, trabalham com o Concílio das Sombras.$B$BEsses sátiros respondem diretamente a um poderoso ancião, o príncipe Xavalis. Alguns dizem que ele é o filho de Xavius, o primeiro sátiro, abençoado pelo próprio Sargeras.$B$BQualquer que seja a natureza do príncipe, temos que matá-lo se quisermos dispersar os Flamejade e reclamar nossas catacumbas. Vá às profundezas da Fortaleza do Concílio das Sombras, em Jaedenar, a noroeste daqui, e mate-o. Não tenha piedade: ele não terá nenhuma de você.', '', '', '', '', '', '', 'Príncipe Xavalis', 'A Legião será expulsa das profundezas!', 'Andalar Valumbra', '', 0),
(28130, 'ptBR', 'Vizinhança nada amistosa', 'O Comandante Marco Gama pediu para você matar 14 aldeões na Vila Montanha da Ferrugem, que fica a norte da base, pelo lado direito.', 'Você foi à Vila Montanha da Ferrugem, $n? Então siga o meu conselho: não deixe de levar uma espada bem afiada se for passar lá perto.$b$bO povo da vila parece ser calmo, mas há algo que não cheira bem. Os relatórios que recebemos dizem que eles estão atacando os nossos soldados. Não aguentamos mais isso, e precisamos que você faça uma limpa por lá.$B$BMate o máximo que puder e volte aqui depois que terminar.', '', 'Moradores da Vila Montanha da Ferrugem', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Marco Gama na Base de Operações de Baradin após cumprir a missão.', 0),
(28131, 'ptBR', 'Dupla tentação', 'Mate Moora e Salia.', 'Moora e Salia são as servas pessoais do senhor das sombras Fel\'dan. Não se deixe enganar por elas!$B$BEssas súcubos perversas usam de malícia e magias sujas para atrair mortais às profundezas da Fortaleza do Concílio das Sombras. Aqueles em seu poder ou passam por lavagem cerebral, ou são sacrificados por Fel\'dan em nome de mestres demoníacos.$B$BAs duas lutam como uma só e nunca são vistas separadas, o que faz delas uma ameaça considerável. Avance pela Fortaleza do Concílio das Sombras e mate-as.', '', '', '', '', '', '', 'Moora e Salia', 'Fel\'dan cairá!', 'Andalar Valumbra', '', 0),
(28132, 'ptBR', 'Escavações eficientes', 'Leve o "Escavações Eficientes" para Belloc Gumélion no Porto de Schnottz.', 'Este manual descreve teorias bizarras sobre como administrar eficientemente grandes grupos de trabalhadores em grandes projetos de escavação.$b$bDepois de uma breve leitura do material, fica claro que o autor do livro é a figura no comando dos saqueadores excessivamente agressivos daqui.$b$bUm mapa na parte de trás indica que o autor tem uma casamata na região sudoeste de Uldum.$b$bTalvez seja o caso de você se apresentar.', '', '', '', '', '', '', 'Schnottz', '', '', '', 0),
(28133, 'ptBR', 'Vingança adormecida', 'Viaje para a Gorja, fale com Zaela e mate Torth.', 'Torth, o draco de Narkrall, sobreviveu ao ataque fracassado a Trondamar e agora está livre de seu antigo mestre.$B$BTorth quer se vingar contra os Presa do Dragão e já atacou Ravina de Sangue uma vez. Ele vai ficar voltando até darmos uma lição nele. É chegada a hora de colocar a corrente demoníaca para funcionar.$B$BO ninho de Torth é uma pequena caverna nas colinas a oeste daqui, onde montamos um acampamento chamado "A Gorja."$B$BEncontre-me lá e daremos um fim a Torth.', '', '', '', '', '', '', 'Torth, o Voraz', '', '', 'Fale com Zaela na Gorja, que fica no Planalto do Crepúsculo.', 0),
(28134, 'ptBR', 'Retaliação iminente', 'Fale com Nomarch Teneth nas Terras de Tahret, com o Sacerdote do Sol Asaris no Selo do Rei Sol e com Asaq em Mar\'at.', 'Agora que você foi devidamente $Grecompensado:recompensada;, espero poder lhe falar francamente.$B$BVocê prestou um grande favor a meu reino, mas desestabilizou o já frágil processo de pacificação.$B$BEu estava tentando a libertação de meu irmão estritamente por meios diplomáticos a fim de evitar derramamento de sangue.$B$BAgora o inimigo certamente irá retaliar.$B$BFale com Nomarch Teneth nas Terras de Tahret, a leste; com o sacerdote do sol Asaris no Selo do Rei Sol, a norte; e com Asaq em Mar\'at, a oeste. Descubra onde o inimigo atacará.', '', 'Falar com Nomarch Teneth', 'Falar com o Sacerdote do Sol Asaris', 'Falar com Asaq', '', '', '', '', '', 'Fale novamente com o Rei Phaoris em Ramkahen, que fica em Uldum.', 0),
(28135, 'ptBR', 'A vingança de Al\'Akir', 'Fale com o Príncipe Nadun no Entreposto Arsad do lado de fora de Mar\'at em Uldum.', 'Ouça, $n. O que atingiu Orsis não foi uma tempestade de areia natural. Foram os lacaios de Al\'Akir.$B$BO senhor elemental do ar uniu forças com o Asa da Morte e era somente uma questão de tempo antes que afligisse meu povo.$B$BO ataque a Orsis foi um alerta para nós. Devemos nos mover rapidamente para oferecer socorro a nossos irmãos.$B$BEncontre Nadun no Entreposto Arsad do lado de fora de Mar\'at. Vou começar os preparativos para cuidar dos desabrigados e feridos.', '', '', '', '', '', '', '', '', '', '', 0),
(28136, 'ptBR', 'Atrás de você!', 'Assassine o Mestre dos Códigos Deethuk, o Comandante Fusobreve e o Elementalista Starion.', 'Os três líderes do Baluarte são poderosos e não devem ser subestimados, $n. Para nossa sorte, você agora pode se disfarçar como $gum sectário:uma sectária; do Crepúsculo.$B$BVista-se e fale com o Mestre dos Códigos Deethuk, o Comandante Fusobreve e o Elementalista Starion, um de cada vez. Faça-os virar as costas para você e acerte-os com um golpe rápido e letal!', '', 'Mestre dos Códigos Deethuk assassinado', 'Comandante Fusobreve assassinado', 'Elementalista Starion assassinado', '', '', '', '', '', 'Fale novamente com Lakota Cantéolo no Baluarte do Crepúsculo, que fica em Mil Agulhas.', 0),
(28137, 'ptBR', 'Ensine um homem a pescar... ou roubar', 'Roube 22 Percas da Vila Montanha da Ferrugem. Os peixes estão nos varais das docas, na parte de trás da vila. A Vila Montanha da Ferrugem fica a norte do campo-base, pelo lado direito.', '$n, a Vila Montanha da Ferrugem é uma bênção e uma maldição para nós. Não faço ideia de como aqueles bandidos aprenderam a pescar tão bem, mas isso não importa.$B$BVá à vila e roube o máximo que puder dos estoques de peixe. Estamos vivendo de migalhas desde que retomamos a ilha, e essa é a nossa melhor chance de conseguir um bom estoque de comida.$B$BTome cuidado com os espreitadores. Segundo informações, há muitos deles dentro da vila.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Marco Gama na Base de Operações de Baradin após cumprir a missão.', 0),
(28138, 'ptBR', 'Infestação humana', 'Capture 8 Humanos de Eira dos Montes.', 'Esta mina já foi o coração das operações mineradoras da Aliança em Eira dos Montes. Agora ela serve como incubadora das nossas fiéis aranhas, embora os humanos ainda a ocupem de certa forma.$B$B<Caetano dá risadas.>$B$BMas vamos ao que interessa... o Carcereiro Calmágua solicitou mais trabalhadores para os Campos Lodosos. Quero que você entre na mina com estes grilhões e capture humanos de Eira dos Montes para trabalharem nos campos.$B$BTire-os de sua imobilidade nas teias e subjugue-os antes de usar os grilhões.', '', 'Humanos de Eira dos Montes capturados', '', '', '', '', '', '', '', 'Fale com o capitão Caetano na Mina Veioazul, no Contraforte de Eira dos Montes.', 0),
(28139, 'ptBR', 'O código do Mestre dos Códigos', 'Consiga o Código do Mestre dos Códigos.', '$n, as correntes que prendem Magatha foram especialmente codificadas. Precisamos da senha para libertá-la.$B$BHá um dispositivo perto do Mestre dos Códigos Deethuk no Baluarte, a sudeste daqui. Os códigos estão lá.$B$BPor favor, consiga-os.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lakota Cantéolo no Baluarte do Crepúsculo, que fica em Mil Agulhas.', 0),
(28140, 'ptBR', 'A Bruxa Anciã', 'Desative o Controlador da Prisão de Magatha.', 'Agora que você sabe o código, só precisa ir ao Baluarte e libertar a Bruxa Anciã.$B$BBoa sorte, $n. Obrigada por tudo.', '', 'Controlador desativado', '', '', '', '', '', '', '', '', 0),
(28141, 'ptBR', 'Relíquias do Rei Sol', 'Recupere 4 Relíquias do Rei Sol.', 'O Selo do Deus Sol funciona como mecanismo de defesa para Ramkahen.$B$BQuando a barreira em torno de Uldum caiu, vimos pioneiros errantes de Tanaris infiltrarem nossas fronteiras.$B$BEles atacaram este solo sagrado a caminho do oeste e roubaram as relíquias que davam poder ao lugar.$B$BRecupere as relíquias para nós. Sem elas, ficamos enfraquecidos para nos defendermos contra ataques dos inimigos do deserto.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Acólito do Sol Asaris em Uldum.', 0),
(28142, 'ptBR', 'O Definhar do Crepúsculo', 'Fale com Magatha Temível Totem no Definhar do Crepúsculo, que fica em Mil Agulhas.', 'Magatha disse que irá encontrá-$Glo:la; do lado de fora do Definhar do Crepúsculo, a leste daqui.', '', '', '', '', '', '', '', '', '', '', 0),
(28144, 'ptBR', 'Monstrinhos larápios!', 'Recupere 6 "Suprimentos" do Acampamento dos Renegados.', 'O longo trecho da costa diretamente ao sul de nossa posição, que se estende de oeste a leste, é conhecido como Praia Ocidental. Ao longo dela você encontrará duas coisas: murlocs e nossos "suprimentos" roubados.$B$B<Caetano levanta as mãos e faz gestos de aspas com os dedos.>$B$BEstes murlocs larápios aproveitaram que estávamos de costas e roubaram nossos "suprimentos",$B$BSarus e eu não podemos abandonar este posto. Precisamos que você vá à Praia Ocidental e recupere nossos "suprimentos!"', '', '', '', '', '', '', '', '', '', 'Fale com o capitão Caetano na Mina Veioazul, no Contraforte de Eira dos Montes.', 0),
(28145, 'ptBR', 'Antídoto noxissangue', 'Encha a Ampola de Antídoto com o veneno de 8 cadáveres de Escorpídeos Noxissangue.', 'Iset tentou defender este solo sagrado quando os Errantes o saquearam.$B$BParece que eles usaram a potente toxina presente nos escorpídeos noxissangue.$B$BPegue esta ampola e colete a peçonha de seus corpos para que eu possa desenvolver um antídoto. Temo que Iset não tenha muito tempo.', '', 'Escorpídeo Noxissangue drenado', '', '', '', '', '', '', '', 'Fale novamente com o Sacerdote do Sol Asaris no Selo do Rei Sol, em Uldum.', 0),
(28146, 'ptBR', 'Iguarias costeiras!', 'Alimente a Rastejante Faminta da Mina com 12 Murlocs da Praia Ocidental.', 'Minhas aranhas estão famintas e agitadas! Há dias não comem e estão começando a devorar nossos prisioneiros humanos. Não podemos aceitar isso. Precisamos desses humanos para usá-los nos Campos Lodosos.$B$BQuero que você leve uma de minhas aranhas famintas e a alimente com murlocs da Praia Ocidental, ao sul daqui. O que você matar, ela comerá! Quanto mais, melhor!', '', 'Murlocs oferecidos à Aranha Faminta da Mina', '', '', '', '', '', '', '', 'Fale com a Tratadora de Aranhas Sarus na Mina Veioazul no Contraforte de Eira dos Montes.', 0),
(28147, 'ptBR', 'O roxo lhe cai bem', 'Junte 8 Fragmentos de Vestimentas do Crepúsculo.', 'Até onde sei, os Ogros Tripasseca do lado de fora da caverna ainda não se aliaram ao Martelo do Crepúsculo. Se formos espertos, poderemos colocar os dois grupos um contra o outro.$B$BVamos tentar com um pequeno truque que aprendi em Silithus. Primeiro temos que conseguir uma vestimenta de sectário para você.$B$BVá para o sul e mate alguns Dobraventos do Crepúsculo na Lacuna Crepuscular. Além de interromper o que eles estiverem tramando, isso vai dar a você a chance de juntar fragmentos de vestimentas.', '', '', '', '', '', '', '', '', '', 'Leve os fragmentos para Estragrum na Gorja, que fica no Planalto do Crepúsculo.', 0),
(28148, 'ptBR', 'Exterminando os corruptos', 'Colete 10 Pelagens Corrompidas de Ursos Garraivosos ou de Lobos Patavil.', 'A repulsiva corrupção demoníaca permeia esta floresta inteira. O solo, as árvores, os animais... todos estão impregnados de magia vil.$B$BNós, do Círculo Esmeraldino, juramos expurgar esta floresta e, para tanto, faz-se necessária uma batalha constante. Ainda é possível curar algumas formas de vida daqui, mas os ursos e lobos estão corrompidos demais.$B$BTemos que acabar com o sofrimento deles e garantir que seus cadáveres não espalhem a contaminação ainda mais. Cace os ursos e lobos e traga as peles deles para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Taronn Pena Vermelha no Santuário Esmeralda, que fica na Selva Maleva.', 0),
(28149, 'ptBR', 'Sussurros ao vento', 'Colete um amuleto Voz do Vento e 5 Sopros do Vórtice.', '‘‘Cê ouviu eles, $c? As vozes da caverna. Elas querem falar, mas elas não conseguem.$B$BVamos achar um jeito pra escutar. O Martelo do Crepúsculo, eles conversam com o vento. Vai pra Lacuna Crepuscular que fica no sul e pegue um amuleto voz do vento no acampamento. Isso vai estar no alto dum pilar de pedra.$B$BNós vamos precisar do sopro dos elementais também! Mate os vórtices revoltos e pegue o que precisar.', '', '', '', '', '', '', '', '', '', 'Fale com Buuna na Gorja, que fica no Planalto do Crepúsculo.', 0),
(28150, 'ptBR', 'Um aliado arcano', 'Fale com a Arcanista Delaris nas Ruínas de Constellas.', 'O Círculo Esmeraldino jurou aceitar a ajuda de todos os que desejarem combater os demônios da Selva Maleva. Apesar de meu povo evitar contato com magias arcanas há muito tempo, não podemos abrir mão de tamanha vantagem.$B$BA arcanista Delaris, uma feiticeira remanescente dos Altaneiros, está ajudando a combater os sátiros Flamejade. Siga a estrada para o norte e procure-a em nosso acampamento, próximo às Ruínas de Constellas.$B$BSe você quiser ajudar a limpar a Selva Maleva, acate os pedidos dela como você fez com os meus.', '', '', '', '', '', '', '', '', '', '', 0),
(28151, 'ptBR', 'Vestindo-se para matar', 'Mate 10 Ogros Tripasseca. Seu disfarce do Martelo do Crepúsculo será ativado automaticamente enquanto você estiver dentro da Ravina do Tripasseca.', 'Seu disfarce está pronto, $n. Agora você pode ir ao norte para a Ravina do Tripasseca que a vestimenta vai enganar os ogros.$B$BO resto do plano é simples: você mata alguns ogros Tripasseca e eles culpam a seita. Você está $gpronto:pronta; para fazer um massacre no acampamento ogro? Foi o que pensei.', '', 'Ogros Tripasseca mortos', '', '', '', '', '', '', '', 'Fale com Estragrum na Gorja, que fica no Planalto do Crepúsculo.', 0),
(28152, 'ptBR', 'Jaedenar aguarda', 'Entregue as Plantas do Arcanista para Greta Musgo no Casco no Pontal do Coração Selvagem.', 'Os sectários que você viu protegendo a garra eram membros do Concílio das Sombras, bruxos perversos por trás de quase todas as tentativas de infiltrar demônios em Azeroth.$B$BO enclave de Jaedenar fica a norte daqui, e é assim chamado em homenagem ao próprio Kil\'jaeden. Sob o enclave estende-se a Fortaleza do Concílio das Sombras, que outrora foi uma catacumba.$B$BLeve estas ervas para o Pontal do Coração Selvagem, que fica a norte daqui e a leste da estrada. A Greta Musgo no Casco precisará delas para purificar a Fortaleza do Concílio das Sombras de uma vez por todas.', '', '', '', '', '', '', '', '', '', '', 0),
(28153, 'ptBR', 'Senhor das sombras Fel\'dan', 'Mate o Senhor das Sombras Fel\'dan.', 'O senhor das sombras Fel\'dan aguarda no seio das profundezas, $n.$B$BA fúria dele será sem igual, agora que você matou suas queridas companheiras. Mesmo sem Moora e Salia, ele é uma força terrível como adversário.$B$BTenha cuidado com os poderes sombrios de Fel\'dan. A esta altura, ele é praticamente mais demônio que orc.', '', '', '', '', '', '', 'Senhor das Sombras Fel\'dan', 'Nossa tarefa está quase completa. A Fortaleza do Concílio das Sombras será reclamada.', 'Andalar Valumbra', '', 0),
(28154, 'ptBR', 'A nadadeira ou "o que quer que seja" de Mucosinho...', 'Entregue a Nadadeira de Mucosinho ao Capitão Caetano na Mina Veioazul, no Contraforte de Eira dos Montes.', 'Isto se parece com uma nadadeira ou o que quer que seja de Mucosinho. Talvez haja alguém que se importe que você tenha matado este murloc no acampamento da Mina Veioazul. Provavelmente não, mas vale a pena tentar.$B$BLeve a nadadeira, ou o que quer que isso seja, de Mucosinho ao capitão Caetano na Mina Veioazul a sudoeste de Eira dos Montes.', '', '', '', '', '', '', '', '', '', '', 0),
(28155, 'ptBR', 'Lorde Nihilus', 'Mate o Lorde Nihilus.', 'Uma última força ainda espreita as profundezas da Fortaleza do Concílio das Sombras: lorde Nihilus.$B$BO Concílio das Sombras serve aos caprichos de Nihilus, e mesmo Fel\'dan era um mero instrumento dele na preparação destas terras para mais uma invasão da Legião Ardente.$B$BProceda com cautela, $n. Um senhor do medo é um adversário aterrorizante. Aguente firme e vença-o!', '', '', '', '', '', '', 'Lorde Nihilus', '', '', 'Fale novamente com Falrus Coração Selvagem no Pontal do Coração Selvagem, que fica na Selva Maleva.', 0),
(28156, 'ptBR', 'Resgate nas profundezas da mina', 'Escolte Abbes Thado até um lugar seguro!', '<Você ouve Abbes falando através da teia.>$B$BOI! ARANHAS POR TODOS OS LADOS! O CAPITÃO ME ENVIOU PARA SALVAR O MUNDO E CAPTURAR HUMANOS! QUE LUGAR É ESSE AFINAL? FAZ TANTO CALOR! EU...$B$B<Abbes continua falando da situação...>$B$BTalvez você possa libertá-lo e trazê-lo de volta a salvo, ou apenas deixá-lo aqui, mesmo que você seja $go culpado:a culpada; por ele estar preso na mina.', 'Escolte Abbes Thado até um lugar seguro!', '', '', '', '', 'Escolte Abbes Thado até um lugar seguro!', '', '', '', 'Fale com o Capitão Caetano na Mina Veioazul, no Contraforte de Eira dos Montes.', 0),
(28157, 'ptBR', 'Os quatro elementos do crepúsculo', 'Consiga os quatro Elementos do Crepúsculo: Ar, Terra, Fogo e Água.', 'O Martelo do Crepúsculo evocou uma monstruosidade, uma combinação dos quatro elementos, energizada com o poder do elemêntio.$B$BSe você ainda deseja salvar Mil Agulhas, terá de destruí-la. Mas, antes disso, você precisa de algumas coisas para ultrapassar o escudo protetor dela.$B$BVá para o leste, para dentro do Definhar, e traga os quatro elementos do Crepúsculo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Magatha Temível Totem no Definhar do Crepúsculo, que fica em Mil Agulhas.', 0),
(28158, 'ptBR', 'Libertos', 'Liberte os elementais Fúria e Vórtice.', 'O Martelo do Crepúsculo aprisionou dois poderosos elementais, Fúria e Vórtice, e está transferindo todo o poder deles para Animus, um terceiro elemental que serve ao Martelo.$B$BSe Animus continuar a absorver tanto poder, ele explodirá! Mil Agulhas será apagada do mapa, assim como tudo ao redor!', '', 'Elemental Fúria libertado', 'Elemental Vórtice libertado', '', '', '', '', '', '', 'Fale novamente com Magatha Temível Totem no Definhar do Crepúsculo, que fica em Mil Agulhas.', 0),
(28159, 'ptBR', 'A pedra da ruína', 'Consiga a Pedra da Ruína.', 'Existe um artefato dentro de Animus conhecido como Pedra da Ruína, que é capaz de absorver uma quantidade incrível de energia.$B$BOs sectários estão tentando sobrecarregá-la e amplificar o poder do elemental para causar a explosão.$B$BTraga-me a Pedra da Ruína. Para fins de preservação... Para o que mais poderia ser?', '', '', '', '', '', '', 'Animus', '', '', 'Fale novamente com Magatha Temível Totem no Definhar do Crepúsculo, que fica em Mil Agulhas.', 0),
(28160, 'ptBR', 'Espalhe a notícia', 'Fale com Xabu Latafuso no Barcódromo do Xabu e do Relé, que fica em Mil Agulhas.', 'Como forma de agradecimento por tudo que você fez, pouparei sua vida. Conte aos seus amiguinhos o que aconteceu aqui. Agora suma da minha frente antes que eu mude de ideia.$B$BE $n... Se nossos caminhos se cruzarem novamente, você morrerá.', '', '', '', '', '', '', '', '', '', '', 0),
(28161, 'ptBR', 'Espalhe a notícia', 'Fale com Relé no Barcódromo do Xabu e do Relé, que fica em Mil Agulhas.', 'Como forma de agradecimento por tudo que você fez, pouparei sua vida. Conte aos seus amigos o que aconteceu aqui. Agora suma da minha frente antes que eu mude de ideia.$B$BE $n... Se nossos caminhos se cruzarem novamente, você morrerá.', '', '', '', '', '', '', '', '', '', '', 0),
(28162, 'ptBR', 'Isca do pântano', 'Você recebeu ordens para coletar 8 Peles de Crocolisco dos Crocoliscos de Baradin, em Tol Barad. Os crocoliscos estão no pântano a oeste da Guarnição Baradin.', 'Encontrar suprimentos em um lugar como este nunca é fácil, $c. Estamos fazendo buscas desde que tomamos a ilha, mas os resultados não têm sido positivos.$B$BFelizmente, acabamos de receber informações de que há um pântano repleto de crocoliscos a oeste daqui. A pele deles será muito útil para os coureiros. Traga o máximo que puder.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Sargento Paulo na Guarnição Baradin após cumprir a missão.', 0),
(28163, 'ptBR', 'Mais sobras', 'Você recebeu instruções para matar 12 Soldados de Infantaria da Horda em Tol Barad. Os refugiados estão nos Escoriodutos, na Vigia do Guardião e na Guarnição Encouraçada.', 'Lutamos brutalmente para tomar esta ilha, $r. Conseguimos nos livrar da maior parte daqueles vermes da Horda da região, mas ainda sinto o fedor deles no ar.$b$bQuero que você investigue os Escoriodutos, a Vigia do Guardião e a Guarnição Encouraçada. Mate todos os imbecis da Horda que encontrar.$B$BComo é mesmo que dizem? É da Horda? Passa o rodo!', '', 'Soldado de Infantaria da Horda', '', '', '', '', '', '', '', 'Apresente-se ao Sargento Paulo na Guarnição Baradin após cumprir a missão.', 0),
(28164, 'ptBR', 'Procure o irmão Pratassacra', 'Fale com o Irmão Pratassacra no Beco do Goblin, que fica em Orgrimmar.', 'Acabo de ser informado que sua presença se faz necessária em Orgrimmar, $n. O irmão Pratassacra deseja que você volte à cidade o mais rápido que puder. Embora ele não tenha entrado em detalhes, parece ser algo de extrema urgência.$B$BProcure pelo irmão Pratassacra no Beco do Goblin, em Orgrimmar.', '', '', '', '', '', '', '', '', '', '', 0),
(28165, 'ptBR', 'Bloco D', 'Você recebeu instruções para matar 10 demônios de qualquer tipo no Bloco D, que fica a noroeste da Guarnição Baradin.', 'Já ouviu falar do Bloco D, $n? É um dos antigos blocos de prisão da ilha. O lugar está totalmente infestado por demônios. Estávamos planejando usá-lo para isolar o que sobrou da Horda na ilha, mas, do jeito que está, não há condições.$B$BVá lá e acabe com os demônios. Fale comigo novamente quando terminar.', '', 'Demônios destruídos', '', '', '', '', '', '', '', 'Fale novamente com o Segundo-tenente Osório, na Guarnição Baradin, após cumprir a missão.', 0),
(28166, 'ptBR', 'O voo noturno de Thog', 'Pegue a Luz das Almas na Ravina do Tripasseca.', 'Pra ver os espíritos, a gente precisa de uma luz especial. Uma luz que ilumina o interior da gente. A luz das almas.$B$BO Martelo do Crepúsculo usa isso pra expulsar os traidores depois do que a gente fez com eles em Hyjal. Eles deram uma de presente pros ogros Tripasseca.$B$BDentro da Ravina do Tripasseca, no norte, você pode achar o grande Thog. Ele tem uma luz das almas. Tem só até você tirar ela dele.', '', '', '', '', '', '', '', '', '', 'Leve a Luz das Almas para Buuna na Gorja, que fica no Planalto do Crepúsculo.', 0),
(28167, 'ptBR', 'Apresente-se a Carvo Estourapino', 'Apresente-se a Carvo Estourapino em Gnomeregan.', 'Vou dar início aos preparativos para sair daqui. Não conseguiremos resistir por muito mais tempo. Quero que você avance para uma posição mais à dianteira, no meio da grande sala em frente.$B$BLá, você vai encontrar o Carvo Estourapino. Ele lhe dará instruções mais específicas. Boa sorte, $n. Nos vemos na superfície.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Carvo Estourapino em Gnomeregan.', 0),
(28168, 'ptBR', 'Apuros nos Campos Lodosos', 'Apresente-se ao Carcereiro Calmágua nos Campos Lodosos, no Contraforte de Eira dos Montes.', 'O carcereiro Calmágua, nos Campos Lodosos, a norte daqui, enviou um sinal de emergência. A missiva não estava clara, mas pelo que pude entender há uma revolta ocorrendo lá e a maioria dos guardas foi morta. O carcereiro avisou que os aspirantes a herói devem se aproximar pela entrada traseira, a oeste dos Campos Lodosos.$B$BEle também pediu discrição... não quer que notícias dessa pequena... *a-hem*, insurreição venham à tona.', '', '', '', '', '', '', '', '', '', '', 0),
(28169, 'ptBR', 'Retirada para o Galpão de Carregamento!', 'Siga os agentes da V.E.R.A. até encontrar Electra Molacurva no Galpão de Carregamento.', 'Você fez um excelente trabalho ao reunir os outros sobreviventes! Eles – e você – são a motivação para as equipes da V.E.R.A. continuarem descendo aqui. O Nevin não vai sossegar enquanto a gente não resgatar todos os sobreviventes.$B$BVou mandar os rapazes ao Galpão de Carregamento para se prepararem para a descontaminação. Por favor, vá atrás deles e se apresente à Electra Molacurva. Ela vai providenciar a sua descontaminação e enviar você para a superfície.', '', '', '', '', '', '', '', '', '', 'Siga os agentes da V.E.R.A. até encontrar Electra Molacurva no Galpão de Carregamento.', 0),
(28170, 'ptBR', 'Medo do escuro', 'Fale com Uchek na Gorja. No reino dos espíritos, use sua Luz das Almas para se proteger enquanto visita os três santuários dentro da caverna.', 'Meu amigo Uchek já tá na caverna. A gente construiu três santuários lá dentro. Cê só tem que limpar a energia ruim de cada um deles.$B$BEntra na caverna e fala com o Uchek. Ele vai te botar em transe e te transportar pro reino dos espíritos. Mas vai com cuidado! Se encontrar uma aberração fantasma, num precisa ficar com medo. Aponta a Luz das Almas na direção do bicho um bocadinho e a luz vai mandar ela pra bem longe. A luz vai te proteger. Agora vai purificar os três santuários!', '', 'Primeiro santuário purificado', 'Segundo santuário purificado', 'Terceiro santuário purificado', '', '', '', '', '', 'Fale com Buuna na Gorja, que fica no Planalto do Crepúsculo.', 0),
(28171, 'ptBR', 'E o céu se fez rubro', 'Fale com Calen para juntar-se ao ataque à Revoada Dragônica Negra.', 'Com Asa da Morte de certa forma ocupado, temos uma tarefa desagradável e assustadora à nossa frente, sob ordens expressas da rainha. A revoada dragônica negra está para ser exterminada.$B$BEu agradeceria sua ajuda nisso se você a oferecesse. Apenas fale comigo e mandarei você no próximo voo que partir para juntar-se à luta.', '', 'Adesão à força de ataque da Revoada Dragônica Vermelha', '', '', '', '', '', '', '', 'Fale com Lirastrasza a noroeste da Floresta Obsidiana, que fica no Planalto do Crepúsculo.', 0),
(28172, 'ptBR', 'Inocentes', 'Obtenha um Dragonetinho Vermelho Libertado, um Dragonetinho Verde Libertado, um Dragonetinho Azul Libertado e um Dragonetinho Bronze Libertado.', 'Os orcs Rocha Negra das estepes servem a um mestre maligno – um mestre que conduz experimentos em seres vivos e cria sua própria coleção de abominações. Muitas das cobaias são tão corrompidas quanto seu mestre, mas outras são completamente inocentes.$B$BNa Colina dos Dragonetes, a sul, eles acorrentam filhotinhos de dragão ao chão para prepará-los para tais experimentos. Não vou aceitar isso. Destrua os grilhões e traga os filhotes de volta para mim... Para um lugar seguro.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Mouton Flamestrela no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28173, 'ptBR', 'Apagão', 'Mate 8 Labarasas Obsidianos depois de utilizar os Ganchos Caça-serpes para alcançá-los.', 'Os caça-dracos do Crepúsculo usaram acessórios malignos para derrubar nossos dracos que sobrevoavam pelos céus. Ganchos que penetravam suas escamas e deixavam os crepusculares seguros enquanto eles nos mandavam para o chão.$B$BJá não há mais paz. Perdemos as esperanças de uma redenção. O único perdão que daremos à revoada negra é o esquecimento que eles tanto procuram.$B$BUse os ganchos para matar os labarasas obsidianos ao sul. Eles permitirão que você faça muitas manobras no ar se forem usados corretamente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lirastrasza a noroeste da Floresta Obsidiana, que fica no Planalto do Crepúsculo.', 0),
(28174, 'ptBR', 'Vingança ardente', 'Mate 5 Crias Rocha Negra e 5 Ninhadas Flamescama.', 'Os orcs Rocha Negra não param. Eles subiram para os campos de batalha ao leste e podem atacar a qualquer momento.$B$BEles atacaram minha terra natal uma vez. E é por isso que estou aqui, para que isso não aconteça novamente.$B$BSe você tem algum amor pela humanidade, fará o mesmo. Prove seu valor. Vá para o sul, para a Colina dos Dragonetes, e mate as crias e os filhotes de dragão negro. Prove para mim que você está preparad$go:a; para esta guerra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com John J. Keeshan no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28175, 'ptBR', 'A floresta petrificada', 'Utilize a Lágrima de Alexstrasza na cavidade embaixo da Árvore Obsidiana.', 'A grande árvore petrificada que repousa ao sul daqui já foi um dia uma fonte de muita vida. Nossa fonte. Perdemos esta floresta para a revoada negra e, desde então, ela foi corrompida e petrificada. Quase destruída.$B$BMas sempre resta uma esperança. Eu trouxe uma poderosa ferramenta para começar o processo de cura. A árvore ainda pode ser salva, com tempo, sorte e, talvez, algum esforço seu.$B$BLeve a lágrima de Alexstrasza e use-a na cavidade do coração da árvore.', '', 'Lágrima de Alexstrasza colocada', '', '', '', '', '', '', '', 'Fale novamente com Velastrasza a noroeste da Floresta Obsidiana, que fica no Planalto do Crepúsculo.', 0),
(28176, 'ptBR', 'Voando para casa', 'Use a Chama da Mãe nos Ovos Obsidianos para liberar os filhotes e siga-os até o covil da mãe deles.', 'Você encontrará alguns ninhos com ovos negros na parte sudoeste da Floresta Obsidiana. Muitos ovos podem ser chocados a qualquer momento com um pouco de paciência e a chama certa. Assim que os filhotes chocarem, vão sair chorando pela mãe deles.$B$BNão se preocupe, só quero que você liberte os filhotes e siga-os enquanto eles vão atrás da mãe. É ela quem devemos confrontar.', '', 'Filhotes obsidianos chocados', 'Covil Obsidiano infiltrado', '', '', '', '', '', '', 'Fale com Ruinaflama no Covil Obsidiano, que fica no Planalto do Crepúsculo.', 0),
(28177, 'ptBR', 'Fazendo estoque', 'Obtenha 5 Farpas Afiadas de Escorpídeo.', 'Se vamos entrar em guerra contra o Clã Rocha Negra, precisamos de um plano. Meu coronel já montou um, e está na hora de executá-lo.$B$BPreciso de aguilhões de escorpídeo. Os mais afiados que você conseguir encontrar. Os escorpídeos estão por toda a estepe, mas você encontrará a maioria na ravina a oeste.$B$BNão se preocupe com a utilidade deles. Você descobrirá em breve.', '', '', '', '', '', '', '', '', '', 'Fale novamente com John J. Keeshan no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28178, 'ptBR', 'Um projeto futuro', 'Obtenha 11 Pelegos de Worg Incandescente.', 'Vamos precisar de pelegos de worg, e muitos. Não importa se estiverem rasgados, queimados ou ensanguentados: precisamos deles em grandes quantidades.$b$bNa verdade, talvez até seja melhor que os pelegos estejam um pouco deteriorados.$b$bVocê encontrará worgs a oeste e a leste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com John J. Keeshan no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28179, 'ptBR', 'Caçador de lama', 'Obtenha 9 montes de Lama Salpicada de Obsidiana.', 'Espero que você não tenha medo de se sujar. A julgar pela sua aparência, isso não será um problema.$B$BAo norte, às margens do rio de lava, você encontrará montes de lama escura. Preciso delas.$B$BSeria melhor se você não fizesse perguntas e se concentrasse em seguir ordens, $n.', '', '', '', '', '', '', '', '', '', 'Fale novamente com John J. Keeshan no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28180, 'ptBR', 'A areia, a sidra e o orbe', 'Fale com Gorzeeki Olholouco perto do Altar das Tempestades.', 'O Coronel Troteman está nos esperando ao leste. Antes de sairmos, porém, precisamos de mais algumas coisas. Desta vez, você as pegará com um bruxo que atende pelo nome de Gorzeeki Olholouco.$B$BVocê provavelmente vai encontrá-lo a noroeste, perto do Altar das Tempestades. Diga-lhe que ele vai ter que nos ajudar. Precisamos da areia, da sidra e do orbe.$B$BEle vai saber o que isso significa.', '', '', '', '', '', '', '', '', '', 'Fale com Gorzeeki Olholouco no Altar das Tempestades, que fica nas Estepes Ardentes.', 0),
(28181, 'ptBR', 'Os bruxos têm as coisas mais legais', 'Obtenha um punhado de Areia do Sono, um jarro de Sidra Redonda Vil, e um Orbe Límpido de Vidro.', 'O Keeshan disse que precisa de suprimentos? A gente tem suprimento a dar com pau! O problema é que esses bruxos me expulsaram de casa e não vão me deixar voltar.$B$B<Olholouco mede o seu tamanho.>$B$BMas pode ser que você consiga entrar lá. Vai pro norte e busca minha areia do sono, minha sidra redonda vil e um orbe límpido de vidro. Tenho certeza de que é isso que ele quer.$B$BAh, se você matar uns orcs sem querer enquanto estiver lá em cima, eu não vou ficar chateado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gorzeeki Olholouco no Altar das Tempestades, que fica nas Estepes Ardentes.', 0),
(28182, 'ptBR', 'Encaixotando o Sombrio', 'Mate Ner\'gosh, o Sombrio.', 'O Ner\'gosh, o Sombrio, é o líder daqueles bruxos ao norte. Ele é o vacilão que me expulsou de casa quando aqueles orcs Rocha Negra começaram a aparecer. Bom, eles são todos uns vacilões, mas ele é o mais vacilão de todos.$B$BPra eu voltar a morar perto do altar, o Ner\'gosh tem que sumir dali.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gorzeeki Olholouco no Altar das Tempestades, que fica nas Estepes Ardentes.', 0),
(28183, 'ptBR', 'Voltando a Keeshan', 'Leve os Suprimentos de Bruxaria para John J. Keeshan no Posto Flamestrela, que fica nas Estepes Ardentes.', 'Bom, acho que não precisarei mais de você. Vou enxotar daqui aqueles outros bruxos quando tiver criado coragem.$B$BAqui, não se esqueça dos suprimentos!', '', '', '', '', '', '', '', '', '', 'Fale com John J. Keeshan no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28184, 'ptBR', 'Laceragarra, o coração das estepes', 'Elimine 15 soldados Rocha Negra de qualquer tipo em sua viagem para Laceragarra.', 'Estamos indo para Laceragarra, bem no centro destas estepes. Vamos nos encontrar com a Irmandade do Tório lá, assim como com Troteman.$B$BVocê conhece a Irmandade? Aqueles anões Ferro Negro já me ajudaram mais de uma vez. Talvez precisemos da ajuda deles novamente.$B$BVamos passar pelo Casebre Dente Preto no caminho até lá. O que você acha de matarmos alguns orcs durante a viagem? Estou ficando meio inquieto neste acampamento.', '', 'Tropas Rocha Negra eliminadas', '', '', '', '', '', '', '', 'Fale com Estêvão Ferrogusa em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28185, 'ptBR', 'Svarnos', 'Mate Svarnos no Bloco D e volte com a Coleira Maldita. Svarnos está no Bloco D, a noroeste da Guarnição Baradin.', '$C, você fez um excelente trabalho na captura da ilha. Agora, que temos o controle total, precisamos preparar os blocos da prisão para nossos prisioneiros. O Bloco D é o que está dando mais trabalho, por causa dos vários tipos de demônios.$B$BConseguimos reduzir a quantidade de demônios, mas um dos cães-magma conseguiu sair da cela e está fazendo um estrago sério. Preciso que você o mate e me traga a coleira dele.', '', '', '', '', '', '', 'Svarnos', '', '', 'Fale novamente com o Segundo-tenente Osório, na Guarnição Baradin, após cumprir a missão.', 0),
(28186, 'ptBR', 'Grilhões Amaldiçoados', 'Você recebeu ordens para recolher 8 Grilhões Amaldiçoados no Bloco D, que fica a noroeste da Guarnição Baradin.', 'Já foi ao Bloco D, $n? Cansamos de tirar os demônios de lá, mas eles voltam toda hora. Descobrimos que eles conseguem se regenerar por causa dos grilhões amaldiçoados que estão espalhados na região. É aí que você entra, $n.$B$BPreciso que você recolha o máximo de grilhões que puder e os traga para mim. Nós os destruiremos imediatamente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Segundo-tenente Osório, na Guarnição Baradin, após cumprir a missão.', 0),
(28187, 'ptBR', 'Não me pegarr porr pouco!', 'Fale com o Comandante Schnottz quando você estiver pront$go:a; para acompanhá-lo para fora da construção em chamas.', 'Tudo bem, $r! O coisa acabou de ficarr sérrio!$b$bAlguém acharr que pode se livrarr de mim fácil assim, não é?$b$bVamos verr! Nada poderr parrar esta trabalho! Nada!$b$b<Schnottz se volta para as chamas ao redor, que se aproximam.>$b$bÉ melhorr sairrmos logo daqui.$b$bDepressa! A tempo é pouca!', '', 'Schnottz acompanhado a um lugar seguro', '', '', '', '', '', '', '', 'Fale com o Comandante Schnottz no Porto de Schnottz.', 0),
(28188, 'ptBR', 'Revolta na Prisão', 'Você recebeu instruções para matar 10 prisioneiros de qualquer tipo no Presídio da Grande Ilha, que fica a sudoeste da Guarnição Baradin.', 'Já dominamos a ilha. Agora temos que usar os recursos dela. Encontramos um bloco de prisão abandonado a sudoeste daqui, e quero que você vá verificar o estado dele.$B$BSegundo os relatórios, esse bloco é controlado por prisioneiros que estão lá há anos. Faça o que for preciso para liberar o local. Fale comigo novamente depois que estiver tudo pronto.', '', 'Prisioneiros mortos', '', '', '', '', '', '', '', 'Apresente-se novamente ao Marechal Malone, na Guarnição Baradin, após cumprir a missão.', 0),
(28189, 'ptBR', 'Faça a coisa certa', '"Salve" 15 Sementinos Humanos.', 'Você se depara com uma cena terrível. Alguém ou algo enterrou todos os humanos até o pescoço como se tivessem sido plantados. Os carniçais, que aparentemente tomam conta desse "plantio", de vez em quando pulam sobre o humano mais próximo e devoram sua cabeça!$B$BVocê pode acabar com isso de uma vez por todas. Pegue esta pá e "salve" os humanos.$B$BFaça a coisa certa.', '', 'Sementinos Humanos "salvos"', '', '', '', '', '', '', '', '', 0),
(28190, 'ptBR', 'A gosma maculada', 'Mate 8 Gosmas Maculadas.', 'Tudo isso começou com Winna Perícon. Ela era uma boticária Renegada que ficava no Posto Peçonha pesquisando formas de utilizar a gosma demoníaca contra a Aliança.$B$BAvisamos a ela que aquilo já estava indo longe demais, mas não fomos ouvidos e não reagimos com a rapidez necessária. Agora, ela e todos os demais do Posto Peçonha foram reduzidos a meras criaturas gosmentas e descerebradas...$B$BAs gosmas nojentas que ela usou na época ainda se arrastam nas imediações dos poços a leste e ao sul. Eu imploro, $c, extermine-as para que outros não cometam o mesmo mal.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Altsoba Totem da Fúria no Posto Peçonha, que fica na Selva Maleva.', 0),
(28191, 'ptBR', 'Um fim apropriado', 'Mate 10 Draconoides Obsidianos.', 'Os draconoides obsidianos se alastram pelas terras ao sul. Eles não estão em condições de nos atacar, mas ninguém pode prever as novas ameaças que podem surgir em uma batalha.$B$BQuero que você assuma a briga com os draconoides. Elimine-os para que prossigamos com a limpeza destas terras da contaminação da revoada negra.', '', 'Draconoide Obsidiano morto', '', '', '', '', '', '', '', 'Fale novamente com Lirastrasza a noroeste da Floresta Obsidiana, que fica no Planalto do Crepúsculo.', 0),
(28192, 'ptBR', 'Ninguém sai vivo', 'Avalie a situação nos Campos Lodosos.', 'Esta fazenda está interditada! Ninguém entra, ninguém sai! Ainda estamos averiguando a situação para tentar entender o que aconteceu, mas imagino que os trabalhadores tenham comido cogumelos e, de alguma forma, se transformaram em terríveis monstros mortos-vivos. Como isso foi acontecer? É apenas uma fazenda! Plantamos cogumelos nela! E lodo! Sim, lodo!$B$BDê uma olhada por aí, $c, porque, uma vez aqui, só poderá sair quando essa questão for resolvida.$B$BVeja por si $gpróprio:própria;!', 'Avalie a situação nos Campos Lodosos.', '', '', '', '', 'Avalie a situação nos Campos Lodosos.', '', '', '', 'Fale com o Carcereiro Calmágua nos Campos Lodosos, no Contraforte de Eira dos Montes.', 0),
(28193, 'ptBR', 'Ninguém sai!', 'O Comandante Schnottz quer que você observe os convidados no Porto de Schnottz.', 'Aquele construção não explodirr sozinho!$b$bAlguém estava tentando me pegarr, e não vou descansarr enquanto não descobrirr a culpado!$b$bComece com as convidados. Visite as convidados, obserrve a comportamento delas e, então, reporte-as parra mim.$b$bSe elas souberrem de qualquerr coisa, eu interrogo elas!$b$bDispensad$ga:o;!', '', 'Convidados de Schnottz visitados', '', '', '', '', '', '', '', 'Fale com o Comandante Schnottz no Porto de Schnottz.', 0),
(28194, 'ptBR', 'A grande fuga', 'O Escritor Prolífico, no Porto de Schnottz, quer que você colete 6 Uniformes Frescos dos Marinheiros de Schnottz.', 'Por favor, $c! Precisamos da sua ajuda!$b$bEstamos presos neste prédio contra a nossa vontade. E com o comandante falando desse jeito, não tem como sabermos o que ele fará conosco!$b$bTalvez, se você nos arranjar alguns uniformes, consigamos fugir.$b$bNunca deveríamos ter vindo aqui. Agora vejo isso.$b$bSe você nos ajudar a fugir, escreverei a VERDADE sobre o que aconteceu aqui.$b$bOs homens naquelas embarcações estão todos vestidos com os trajes de que precisamos.', '', '', '', '', '', '', '', '', '', 'Fale com o Escritor Prolífico no Porto de Schnottz.', 0),
(28195, 'ptBR', 'Enviando uma mensagem', 'O Comandante Schnottz quer que você mate o Capitão Margun, o Capitão Cork e o Capitão Kronkh.', 'Eu terr olhos e ouvidos em todas as cantos deste região, $r.$b$bOuvi as murrmurrinhos que ecoam dentre meus trropas. Eu terr sido muito tolerante com essa comporrtamento patética – até agora!$b$bEnviarrei o mensagem parra todos em meus fileirras, todos saberrão que divergências não serrão tolerrados!$b$bVocê deve exterminarr as capitães a borrdo das minhas navios no doca. Eles estão entrre as mais descontentes.$b$bQuando isso acabarr, monitorrarrei os comunicações e determinarrei o que fazerr a seguirr.$b$bDispensad$ga:o;!', '', 'Capitão Margun morto', 'Capitão Cork morto', 'Capitão Kronkh morto', '', '', '', '', '', 'Apresente-se ao Comandante Schnottz no Porto de Schnottz.', 0),
(28196, 'ptBR', 'A Batalha por Eira dos Montes', 'Entregue o diário ao Carcereiro Calmágua nos Campos Lodosos, no Contraforte de Eira dos Montes.', 'O diário registra os últimos 62 dias de vida do Tabelião Horácio Brancorcel. Nele estão escritas acusações condenáveis ao Carcereiro Calmágua e suas atividades nos campos lodosos.$B$BVocê deve mostrar isso ao carcereiro. Sem dúvida, ele terá uma explicação para o que está escrito no diário.', '', '', '', '', '', '', '', '', '', '', 0),
(28197, 'ptBR', 'Discrição é tudo', 'Mate o Cidadão Urbano e o Tabelião Horácio Brancorcel.', 'Devemos destruir todas as evidências, $n! Falei evidência? Quis dizer esses mortos-vivos enlouquecidos! De qualquer jeito, discrição é tudo. Não podemos deixar os mortos-vivos descontrolados fugirem dos Campos Lodosos e ninguém de fora deve saber o que aconteceu aqui!$B$BA sudeste daqui, no que costumava ser a velha fazenda de cogumelos, você encontrará um demônio ressuscitado chamado Cidadão Urbano e seu cúmplice, o tabelião Horácio Brancorcel. Eles estão causando grandes problemas a meus guardas. Ache-os e mate-os!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Carcereiro Calmágua nos Campos Lodosos, no Contraforte de Eira dos Montes.', 0),
(28198, 'ptBR', 'O elo mais fraco', 'Fale com Sal-het no Posto Avançado da Legião Ramkahen em Uldum.', 'Dizem que uma corrente é tão forte quanto seu elo mais fraco.$B$BSou adepto desta teoria e vou além.$B$BEm vez de retirar o elo frágil, deve-se... fortalecê-lo.$B$BOs demais elos intensificarão seu desempenho com medo de se tornarem frágeis também.$B$BNo caso do meu exército, o elo frágil tem um nome: Sal-het.$B$BVocê o encontrará treinando próximo ao pé desta escadaria.$B$BComece com algo fácil... as hienas das colinas a oeste, talvez.', '', '', '', '', '', '', '', '', '', '', 0),
(28199, 'ptBR', 'Pela ciência!', 'Colete 6 Amostras de Carne.', 'Amostras... sim... tenho que ter amostras! Estes, hum, experimentos... quero dizer, estes infelizes trabalhadores devem ser estudados.$B$BSiga para a primeira fazenda a sudeste e mate carniçais revividos. De seus decrépitos corpos, colete amostras de carne. Traga-as a mim!$B$B<Arnaldo esfrega as mãos e ri malignamente sem motivo aparente.>$B$BPreciso testar!', '', '', '', '', '', '', '', '', '', 'Entregue as Amostras de Carne ao Molda-carne Arnaldo nos Campos Lodosos, no Contraforte de Eira dos Montes.', 0),
(28200, 'ptBR', 'A essência dos suprimentos', 'Colete 20 Peles Endurecidas de Crocolisco.', 'Você notará que estamos despreparados para lutar.$B$BAs tribos tol\'vir não se envolvem em grandes conflitos há milhares de anos.$B$BMas todos os protocolos de combate programados pelos titãs em nossos ancestrais permanecem. Alguns são parte de nossos instintos, outros transmitidos como tradição.$B$BMas nada disso compensa a falta de suprimentos. Precisamos de armas. Precisamos de armaduras.$B$BA melhor armadura é confeccionada com a pele dos crocoliscos do leito do rio próximo. Ajude-nos a coletar peles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Sargento Mehat no Posto Avançado da Legião Ramkahen, que fica em Uldum.', 0),
(28201, 'ptBR', 'Do arado às armas', 'Recrute 8 Trabalhadores de Ramkahen.', 'Temos um exército considerável, mas temo que o confronto futuro com os bandos Neferset demandará a união de forças de todos os tol\'vir aptos de Ramkahen e Orsis.$B$BQuero que seja responsável pelo recrutamento de reforços.$B$BAtravesse o rio até os Campos Akhenet e recrute trabalhadores para nos servirem.', '', 'Trabalhador de Ramkahen recrutado', '', '', '', '', '', '', '', 'Fale novamente com o Alto-comandante Kamsés no Posto Avançado da Legião Ramkahen.', 0),
(28202, 'ptBR', 'Uma fantasia perfeita', 'Traga a quantidade apropriada de materiais da mesa de alfaiataria para Thelaron Agulhetes, em Laceragarra.', 'Com seu peso, estrutura e tamanho, é melhor $Gvesti-lo:vesti-la; como $Gum orc:uma orquisa;. A maior parte do exército deles é feita de orcs, então você vai se encaixar direitinho no grupo.$B$BVocê sabe algo sobre alfaiataria? Se não, considere isto a primeira lição. Tem todos os materiais necessários ali na minha mesa de alfaiataria.$B$BVá lá, pegue o que achar necessário e traga aqui. O Agulhetes vai dar um jeito em você rapidinho.', '', 'Fantasia Perfeita criada', '', '', '', '', '', '', '', 'Fale com John J. Keeshan em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28203, 'ptBR', 'Uma fantasia perfeita', 'Traga a quantidade apropriada de materiais da mesa de alfaiataria para Thelaron Agulhetes, em Laceragarra.', 'Com seu peso, estrutura e tamanho, é melhor $Gvesti-lo:vesti-la; como $Gum ogro:uma ogra;. Os ogros Pirobucho sempre trabalharam para os Rocha Negra, então, você vai se encaixar direitinho no grupo.$B$BVocê sabe algo sobre alfaiataria? Se não, considere isto a primeira lição. Tem todos os materiais necessários ali na minha mesa de alfaiataria.$B$BVá lá, pegue o que achar necessário e traga aqui. O Agulhetes vai dar um jeito em você rapidinho.', '', 'Fantasia Perfeita criada', '', '', '', '', '', '', '', 'Fale com John J. Keeshan em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28204, 'ptBR', 'Uma fantasia perfeita', 'Traga a quantidade apropriada de materiais da mesa de alfaiataria para Thelaron Agulhetes, em Laceragarra.', 'Com seu peso, estrutura e tamanho, é melhor $Gvesti-lo:vesti-la; como $Gum goblin:uma goblina;. Os Rocha Negra são conhecidos por contratarem goblins mercenários para seus exércitos, então, você vai se encaixar direitinho no grupo.$B$BVocê sabe algo sobre alfaiataria? Se não, considere isto a primeira lição. Tem todos os materiais necessários ali na minha mesa de alfaiataria.$B$BVá lá, pegue o que achar necessário e traga aqui. O Agulhetes vai dar um jeito em você rapidinho.', '', 'Fantasia Perfeita criada', '', '', '', '', '', '', '', 'Fale com John J. Keeshan em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28205, 'ptBR', 'Uma fantasia perfeita', 'Traga a quantidade apropriada de materiais da mesa de alfaiataria para Thelaron Agulhetes, em Laceragarra.', 'Com seu peso, estrutura e tamanho, é melhor $Gvesti-lo:vesti-la; como $Gum troll:uma trolesa;. Os trolls Fumocardo sempre trabalharam com os orcs Rocha Negra, então, você vai se encaixar direitinho no grupo.$B$BVocê sabe algo sobre alfaiataria? Se não, considere isto a primeira lição. Tem todos os materiais necessários ali na minha mesa de alfaiataria.$B$BVá lá, pegue o que achar necessário e traga aqui. O Agulhetes vai dar um jeito em você rapidinho.', '', 'Fantasia Perfeita criada', '', '', '', '', '', '', '', 'Fale com John J. Keeshan em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28206, 'ptBR', 'Garotinha perdida', 'Encontre Jãozinho "Joaninha" Manda-muito nos Campos Lodosos, no Contraforte de Eira dos Montes.', 'Ainda ontem eu a enviei para investigar a fazenda a leste daqui, mas parece que já se passou uma eternidade!$B$BEu soube que era amor verdadeiro desde o primeiro momento que a vi. Os cachinhos dourados a emoldurar seu lindo rosto sanguinélfico... Ela derreteu meu coração seco. Não queria deixá-la ir, mas ela insistiu tanto! Tive que deixá-la fazer o que pediu. Quem diria não a tal visão?$B$BInfelizmente, a pobre Joaninha Manda-muito não retornou! Temo pelo pior, $n. Encontre-a!', '', '', '', '', '', '', '', '', '', '', 0),
(28207, 'ptBR', 'Uma situação gosmenta', 'Colete 7 Brilhacampas Esmeralda.', 'Este pobre sujeito quase não escapou vivo do Posto Peçonha! Se quisermos evitar que ele se torne uma criatura visguenta como os outros, temos que tratar a infecção.$B$BCogumelos gostam de água clara e esverdeada, como a do lago a leste daqui, onde cai uma cachoeira. Mas a maioria não presta... Preciso que você colete os verdes e brilhantes!$B$BCom eles em mãos, poderei preparar algo saboroso para ajudar este pobre tauren. Não demore muito!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kelnir Cantafolha no Posto Peçonha, que fica na Selva Maleva.', 0),
(28208, 'ptBR', 'Acho que eu vi um gatinho...', 'Pegue a Identificação do Bichano do Gatinho da Winna.', 'O Sr. Tauren me contou o que aconteceu no Posto Peçonha. Ele disse que a Winna Perícon ainda está lá!$B$BEla já era, mas o que restou dela está fazendo um monte de novas gosmas. Temos que acabar com isso!$B$BFelizmente, eu tenho um plano. O Sr. Tauren disse que a Winna tinha um gatinho. Ela deu água corrompida por gosma para ele beber, e então o bichano fugiu floresta adentro. Eu vi alguma coisa à espreita a sudeste daqui, logo após a Torre Peçonha, mas era bem maior do que um gatinho! Vá lá ver se o bichano está usando alguma identificação...', '', '', '', '', '', '', 'Acho que eu vi um gatinho...', '', '', 'Fale novamente com Kelnir Cantafolha no Posto Peçonha, que fica na Selva Maleva.', 0),
(28209, 'ptBR', 'Liberdade para Lindolfo', 'Recupere a Chave da Cela de Lindolfo.', 'Este lugar não é uma fazenda! Calmágua tem feito experimentos com humanos de Eira dos Montes. Todas as monstruosidades aqui são criações dele.$B$BIsso não é o pior, $c. As aberrações que detêm a chave da minha prisão eram dos Renegados. Como efeito colateral, os experimentos de Calmágua transformaram esses renegados em zumbis desmiolados. Por que acha que ele tem tanto medo de que escapem? Ele sabe que tal crime é punido com a morte.$B$BTire-me daqui! Os guardas infectados dos Campos Lodosos estão com a chave!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Mestre-boticário Lindolfo nos Campos Lodosos, no Contraforte de Eira dos Montes.', 0),
(28210, 'ptBR', 'Perdendo a graça', 'Ajude Sal-het a matar 8 Hienas Rosnassangue.', 'O alto-comandante Kamsés tem uma missão especial para mim?$B$BEspere... não diga. São hienas de novo, certo?$B$BMuito bem, farei o melhor possível.$B$BEncontre-me no Cume de Solarguarda.$B$BNão desapontarei você.', '', 'Ajude Sal-het a derrotar as Hienas Rosnassangue.', '', '', '', '', '', '', '', 'Fale com Sal-het no Cume de Solarguarda em Uldum.', 0),
(28211, 'ptBR', 'Temperado em chama elemental', 'Colete 8 Lanças Temperadas.', 'Começando pelo começo: vamos precisar de munição. Munição poderosa o suficiente para perfurar o pelego blindado de um draco preto.$B$BA oeste de Trondamar tem uma cidade Martelo Feroz que foi invadida por elementais de fogo. Qualquer arma abandonada na conflagração terá sido temperada em chama elemental e deve ser mais resistente do que qualquer coisa que eu poderia fazer por aqui!$B$BEncontre lanças na Conflagração de Humboldt para mim, $n. Quanto mais pontudas, melhor.', '', '', '', '', '', '', '', '', '', 'Leve as lanças para Nilo Trancanal em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(28212, 'ptBR', 'Parada quente', 'Colete 5 pelotas de Fúria Derretida.', 'Tenho um plano pra quadruplicar a torção recomendada para uma arma de lanças deste tamanho, mas, de acordo com meus cálculos, o ato de disparar a arma pode estraçalhar o invólucro... e possivelmente partir o planeta em dois.$B$BEu poderia soldar um chassi cem vezes mais forte se tivesse uma boa fonte de pura chama elemental para a fusão.$B$BA oeste daqui, diabrasas desgarrados ficam perturbando a Conflagração de Humboldt. Quando morrem, eles ficam reduzidos a pelotas de fúria derretida. Traga algumas pra mim!', '', '', '', '', '', '', '', '', '', 'Fale com Nilo Trancanal em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(28213, 'ptBR', 'Profissão Perícon', 'Use a Identificação do Bichano para chamar a atenção da Winna Perícon e, então, mate-a.', 'A Winna está presa à fonte da gosma, que fica atrás do Posto Peçonha, a oeste daqui. A Renegada mantém a fonte fluindo, e a fonte a protege! Mas, se conseguíssemos atrair a atenção de Winna...$B$BLeve a identificação e mostre-a para a Winna. Se ainda restar algo do antigo eu da Renegada, por menor que seja, pode ser que ela se sensibilize. Talvez a tristeza pelo gatinho perdido aflore, ela se arrependa uma última vez e acabe por sair da gosma!$B$BE então você mata a Winna e acaba com a gosma. Oba!', '', '', '', '', '', '', 'Winna Perícon', '', '', 'Fale novamente com Kelnir Cantafolha no Posto Peçonha, que fica na Selva Maleva.', 0),
(28214, 'ptBR', 'Chamando o Raul', 'Mate 6 Gosmasservos Peçonhentos.', 'Blergh...$B$BVocê poderia... ugh... poderia, por favor... URGH!$B$BPerdoe-me, ainda estou um pouco... ai, meu estômago. Se você está indo para o Posto Peçonha, a oeste, por favor HUUURGH...$B$BApenas... apenas acabe com o sofrimento do que restou de meus amigos. Vá AGORA MESMO. Para o seu próprio bem. Uuuuurghh...', '', '', '', '', '', '', '', '', '', 'Fale novamente com Altsoba Totem da Fúria no Posto Peçonha, que fica na Selva Maleva.', 0),
(28215, 'ptBR', 'Energia potencial', 'Colete 10 Bobinas de Elemêntio Retorcido.', 'Como você bem sabe, a quantidade de energia acumulada numa mola convencional é igual a metade da elasticidade da mola multiplicada pelo deslocamento ao quadrado. A não ser que se esteja usando uma mola de elemêntio, daí os números se tornam obscenos! Matematicamente grotesco.$B$BPreciso de alguns circuitos de elemêntio para minha arma secreta, mas acontece que os sectários do Martelo do Crepúsculo usam bobinas parecidas para prender elementais da terra.$B$BEncontre as bobinas nos Rochescravos Obsidianos a leste daqui, na horrível região conhecida como a Lacuna Negra.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nilo Trancanal em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(28216, 'ptBR', 'Lordemagma Falthazar', 'Pegue a Cabeça de Lordemagma Falthazar.', 'Ouvi notícias pavorosas vindas do oeste – perdemos o Sítio de Humboldt. Varrido da face do planeta por uma coluna de fogo!$B$BA culpa é do Martelo do Crepúsculo, e os sobreviventes dizem que foi obra de um tal Lordemagma Falthazar. Ele é um ascendente – é assim que chamam os sectários superiores do Martelo do Crepúsculo que se tornam unos com os elementos. Ele é uma criatura de puro fogo.$B$BE em breve será uma criatura de pura morte! Mate Falthazar em Conflagração de Humboldt e traga a cabeça dele!', '', '', '', '', '', '', 'Lordemagma Falthazar', '', '', 'Fale novamente com Colin Trondamar em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(28217, 'ptBR', 'Procura-se: o caçador de demônios', 'Mate Feronas Vicíssitus.', 'Desde que retomou a Aldeia Flamejade dos sátiros, o Círculo Esmeraldino enviou muitos druidas para dar início à longa tarefa de limpar as ruínas. Na noite passada, vários deles foram assassinados... por um elfo noturno.$B$BAs testemunhas disseram que foi um caçador de demônios, um discípulo ensandecido de Illidan. Uma rara aparição. Não há dúvidas de que o poder o enlouqueceu, como aconteceu ao mestre.$B$BPagarei a recompensa máxima pela prova de que esse assassino está morto. Ele foi visto nas cercanias da estrada para o norte, em um vale abaixo da Vila Flamejade.', '', '', '', '', '', '', 'Feronas Vicíssitus', '', '', 'Fale com Feronas Vicíssitus.', 0),
(28218, 'ptBR', 'Um destino de chamas e pesar', 'Reviva a batalha de Illidan contra Arthas.', 'Sempre fomos odiados por conta do que fazemos... Proscritos, desprezados, acusados de corrupção sem possibilidade de redenção.$B$BAinda assim, se não fosse por um caçador de demônios, esta floresta seria a maior fortaleza da Legião Ardente em Azeroth. Refiro-me a meu mestre, Illidan Tempesfúria, o "Traidor".$B$BVeja por si $Gpróprio:própria;. Veja o que ocorreu aqui quando Illidan foi libertado pela primeira vez, e as forças demoníacas do senhor do medo, Taecondrius, mandavam nesta floresta sem oposição alguma...', 'Arthas vencido', '', '', '', '', 'Arthas vencido', 'Arthas', '', '', 'Fale novamente com Feronas Vicíssitus na Selva Maleva.', 0),
(28219, 'ptBR', 'Zum-zum para a neném', 'Mate 10 Aguilhantes de Pau-ferro para dá-los de comer à Protetora Germinante.', '<A pequena planta abre bem as folhas, tal como um filhote de passarinho escancara o bico à espera de comida. Ela fala com voz fraca.>$B$BFome... quero... insetos...$B$B<Você ouve um zumbido de vespas ao sul. Seriam elas a refeição que a pequenina deseja?>', '', '', '', '', '', '', '', '', '', '', 0),
(28220, 'ptBR', 'Movimento da sem-terra', 'Leve a Protetora Germinante a 7 torrões de Terra Fértil.', '<A plantinha sacode-se, gesticulando de maneira a indicar o sul. Você mal consegue ouvir a voz tênue.>$B$BTerra...$B$B<Ela parece querer terra nova. Talvez você devesse guiá-la a um dos torrões que parecem mais férteis.>', '', 'Terra fértil', '', '', '', '', '', '', '', '', 0),
(28221, 'ptBR', 'Estas raízes foram feitas para pisar', 'Mate 10 Pisoteadores de Ferrárbol.', 'Há tantos outros espíritos aprisionados em corpos apodrecidos...$B$BVocê consegue ver os pisoteadores de Ferrárbol, ao norte? Eles foram atacados por doenças demoníacas e estão cobertos de mofo. Os pobres espíritos dentro deles não conseguem sair.$B$BMas você pode ajudar! Bote abaixo os pisoteadores para que seus espíritos possam sair. Eu os colocarei dentro de mim para que, juntos, sejamos todos felizes quando eu crescer. Você me ajuda? Por favor?', '', '', '', '', '', '', '', '', '', '', 0),
(28222, 'ptBR', 'Cantando sem chuva', 'Guie o Broto Protetor a 5 feixes de luz solar na Floresta Ferrárbol.', 'Estamos crescendo tanto... É hora de brilhar! Hora de abrirmos nossas folhas sob o sol!$B$BLeve-me para o sol! O sol está longe, mas a luz solar chega a nós. Essa luz nos deixa grandes e fortes de novo. Ilumina desde grandes ramos até pequenos galhos como os nossos.$B$BAli! O sol vem do norte! Leve-me com você, leve-me para dançar!', '', 'Exposição aos raios solares', '', '', '', '', '', '', '', '', 0),
(28223, 'ptBR', 'Matança no Cárcere', 'Mate o Carcereiro Silva no Presídio da Grande Ilha e pegue as chaves dele. O Presídio da Grande Ilha fica a sudoeste da Guarnição Baradin.', 'Estamos quase terminando de nos livrar dos prisioneiros do Presídio da Grande Ilha, mas ainda temos um problema: o carcereiro.$b$bO carcereiro Silva é o mestre dos prisioneiros, que farão de tudo para protegê-lo. Se derrotarmos o Silva, os derrotamos todos. Mate-o e traga-me as chaves dele. Poderemos usá-las para explorar as partes mais baixas da prisão e, com sorte, teremos acesso à fonte de água da ilha.', '', '', '', '', '', '', 'Carcereiro Silva', '', '', 'Apresente-se novamente ao Marechal Malone, na Guarnição Baradin, após cumprir a missão.', 0),
(28224, 'ptBR', 'O último protetor', 'Vença o Protetor Dessecado.', 'Ahhh... obrigado, pequen$Go:a; $r. Eu e os demais tentamos, tantas vezes, crescer nesta floresta... Mas sempre sem sucesso.$B$BO Protetor Dessecado que espreita ao norte é o único anciente que conseguiu atingir a maturidade desde que a floresta foi arruinada, mas o corpo dele está doente e, a mente, insana. Assim como recolhemos os espíritos dos arvorosos, prefiro salvar os que nele habitam em vez de deixá-los para trás.$B$BDerrote-o e deixe que os espíritos se juntem a mim antes que eu fixe minhas raízes.', '', '', '', '', '', '', 'O Protetor Dessecado', '', '', '', 0),
(28225, 'ptBR', 'Prova de lealdade', 'Mate 10 Anões Ferro Negro nas Ruínas de Thaurissan.', 'Tu é $Gbem-vindo:bem-vinda; para ficar em Laceragarra por um tempo, mas preciso ter certeza de que tu é $Gum aliado:uma aliada;. Então, vou te dar uma tarefa.$B$BNós, da Irmandade do Tório, não somos os únicos Ferro Negro das estepes, nem de longe. Os Ferro Negro da Montanha Rocha Negra são muito mais numerosos. Nós estamos suficientemente seguros aqui em Laceragarra, mas ainda assim eles nos incomodam, de lugares tão próximos quanto as Ruínas de Thaurissan, ao norte.$B$BMe prova a tua lealdade, $r. Mate eles pra mim.', '', 'Anões de Thaurissan mortos', '', '', '', '', '', '', '', 'Fale com Estêvão Ferrogusa em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28226, 'ptBR', 'Golens aos pedaços', 'Mate Aniquiladores de Guerra nas Ruínas de Thaurissan e saqueie 3 Pistões Obsidianos, 3 Filtros de Fluxo de Exaustão, 3 Engrenagens de Tório e uma Célula de Força de Pedra das Peças de Aniquilador de Guerra que eles deixam cair.', 'Nós temos golens aqui como guardas. Os anões ao norte também têm golens, mas não tenho certeza pra quê.$B$BDeve ser pra ajudar com a matança, decerto.$B$BMas seria bom ter mais peças sobressalentes pros nossos golens, então, olha só o que tu vai fazer pra mim: mate os golens deles pra ver se eles deixam cair alguma peça e cata o que tu conseguir achar. Provavelmente tu não vai conseguir pegar tudo, então escolha com cuidado.', '', '', '', '', '', '', '', '', '', 'Fale com Estêvão Ferrogusa em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28227, 'ptBR', 'Treinamento de golens', 'Ajude 4 Golens Cinzelados com o treinamento.', 'Tu provou que pode nos ajudar muito por aqui, $r. Eu estava pensando se não poderia me ajudar em mais uma coisa.$B$BNossos guardas são fortes, mas tu é bem mais. Será que se importaria de ajudar alguns deles com o treinamento? Vai lá em cima, fala com um deles e trave algumas pelejas. Espero que eles aprendam com teus golpes e melhorem.', '', 'Golens Cinzelados treinados', '', '', '', '', '', '', '', 'Fale com Estêvão Ferrogusa em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28228, 'ptBR', 'Reflorestamento', 'Leve o Protetor Florescente de volta ao morro no meio da Floresta Ferrárbol.', 'Chegou o momento de nos despedirmos. Você me criou desde que eu era apenas uma plantinha, mas, por mais breve que tenha sido, agora devo juntar-me à floresta.$B$BLeve-me de volta ao morro onde você me encontrou. Lá, fincarei minhas raízes e crescerei sob a sombra dos ancientes que vieram antes de mim.', 'Protetor levado ao morro', '', '', '', '', 'Protetor levado ao morro', '', '', '', '', 0),
(28229, 'ptBR', 'Natureza e nutrição', 'Encha o frasco no poço lunar do Bosque Murmuréolo e despeje a água no chão entre os ancientes mortos na Floresta Ferrárbol.', 'Os ancientes que protegiam a Floresta Ferrárbol, ao norte, morreram há anos. Seus cadáveres são um terrível símbolo do mal causado a estas terras.$B$BA cada estação, nós coletamos a água do poço lunar e a despejamos no solo perante os ancientes, esperançosos de que isso estimulará nova vida. Se você quiser, pode levar a água.$B$BÉ uma excelente oportunidade para refletir. Pegue este frasco e encha-o no poço lunar para, então, despejar a água bem no topo do pequeno morro entre os três ancientes.', '', 'Morro de Ferrárbol regado', '', '', '', '', '', '', '', '', 0),
(28230, 'ptBR', 'Protocolo', 'Mate a Monstruosidade Raí-Pegaz-Kalaba.', 'Antes de o carcereiro receber sua reprimenda, devemos cuidar da revolta. Não podemos arriscar que esse contágio se espalhe pelo mundo.$B$BNos alojamentos dos trabalhadores, a norte daqui, há uma criatura que Calmágua fez usando três fazendeiros. Esta besta deve ser destruída se quisermos garantir a segurança dos Campos Lodosos! É o que exige o protocolo!', '', '', '', '', '', '', '', '', '', 'Fale com o Mestre-boticário Lindolfo nos Campos Lodosos, no Contraforte de Eira dos Montes.', 0),
(28231, 'ptBR', 'A vingança vem a cavalo', 'Mate o Ferreiro Verrintão.', 'O Carcereiro Calmágua me enviou ao campo para investigar a revolta. Quando cheguei, Brilhoso e eu fomos atacados pela truculenta monstruosidade conhecida como Verrintão. Fui derrubado e corri imediatamente para me salvar. Brilhoso, no entanto, ficou para trás e encarou a fera. Infelizmente ele foi derrotado e sumariamente plantado no solo, como se fosse uma muda de pônei estrelado.$B$BEle deu a vida me defendendo. Quero vingança! É o mínimo que posso fazer por Brilhoso!', '', '', '', '', '', '', '', '', '', 'Fale com Jãozinho Manda-muito nos Campos Lodosos, no Contraforte de Eira dos Montes.', 0),
(28232, 'ptBR', 'O que vem de baixo me alimenta', 'Você recebeu ordens para recuperar 12 Rações da Prisão no Presídio da Grande Ilha, que fica a sudoeste da Guarnição Baradin.', 'A nossa comida está acabando, $n. Recentemente descobrimos que a prisão a sudoeste daqui ainda tem um bom estoque de rações, mesmo após anos de uso. Quero que você recolha o máximo que puder e traga tudo para o campo-base.$B$BAh, mais uma coisa. A prisão está lotada de prisioneiros, então tome cuidado.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Marechal Malone, na Guarnição Baradin, após cumprir a missão.', 0),
(28233, 'ptBR', 'Cara, cadê meu irmão?', 'Encontre Bahrum Forjatelo.', 'Meu irmão Bahrum sumiu, desapareceu, escafedeu-se!$B$BEle foi um dos primeiros batedores da área. Todos voltaram em segurança, mas não há sinal dele. Dizem que ele tá vadiando por aí, mas ele é meu único irmão e prometi pra mamãe que eu iria proteger ele. Você pode encontrar meu irmão, por favor?', '', '', '', '', '', '', '', '', '', 'Encontre Bahrum Forjatelo.', 0),
(28234, 'ptBR', 'Me pegaram de calças arriadas!', 'Encontre os Guarda-pernas de Bahrum.', 'Por que eu tô dentro do caixote de grãos? Resumindo... tinha uns vespões e uns Presa do Dragão apareceram em má hora. Consegui me salvar, mas os desgraçados pegaram meus guarda-pernas!$B$BFoi minha irmã que fez pra mim, tinha até o meu nome gravado... Vou ficar morrendo de vergonha se ela souber que perdi eles.$B$BPor favor, acha os guarda-pernas pra mim – vi o larápio indo em direção à fortaleza. Vou ficar aqui... hum... escondido.$B$BE não pergunte o que um Martelo Feroz usa por baixo do kilt!', '', '', '', '', '', '', '', '', '', 'Leve os guarda-pernas para Bahrum no Acampamento de Guerra Gorshak, que fica no Planalto do Crepúsculo.', 0),
(28235, 'ptBR', 'Ardelado deve cair', 'Mate o Magistrado Ardelado.', 'O Magistrado Ardelado já foi o prefeito desta região. Em vida, ele foi um adversário formidável na batalha por Eira dos Montes. Certamente irá nos testar na morte-viva.$B$BArdelado canaliza grande magia arcana na parte noroeste dos campos lodosos. Leve-nos lá e, juntos, poremos um fim a seu jugo de uma vez por todas.', '', '', '', '', '', '', '', '', '', 'Fale com o Mestre-boticário Lindolfo nos Campos Lodosos, no Contraforte de Eira dos Montes.', 0),
(28236, 'ptBR', 'The Lost Brother', 'Find Bahrum Forgehammer.', 'Me brother Bahrum has gone missing!$b$bHe was one of the first scouts in the area. All the others have returned safely, but there be no sign of him. Da says he\'s just dawdling somewhere, but he\'s me only brother, and I promised me mum that I would keep him safe. Will you please find him?', '', '', '', '', '', '', '', '', '', '<completion text>', 0),
(28237, 'ptBR', 'Uma praga sobre a terra', 'Traga a Cabeça do Carcereiro Calmágua.', 'Com a revolta dos mortos-vivos controlada, chegou a hora de Calmágua e seus seguidores pagarem por seus crimes. Apesar de termos evitado uma tragédia sem precedentes desde a invasão do Flagelo, devemos assegurar que coisa parecida jamais ocorra. Eles encararão a morte certa!$B$BVenha, $n! Eu terei a cabeça de Calmágua!', '', '', '', '', '', '', '', '', '', 'Entregue a Cabeça do Carcereiro Calmágua ao Mestre-boticário Lindolfo nos Campos Lodosos, no Contraforte de Eira dos Montes.', 0),
(28238, 'ptBR', 'Costa do Crepúsculo', 'Fale com Fargo Flintlocke no Porto de Ventobravo.', 'É chegada a hora, $c. Com Ventobravo em segurança, vamos levar esta briga ao inimigo. Ao Planalto!$B$BA maior parte da nossa esquadra já partiu, graças ao seu trabalho anterior. Mas Fargo Flintlocke preparou um hidroplano que pode fazer a viagem na metade do tempo.$B$BFale com Flintlocke no porto e diga-lhe que você o acompanhará até o Planalto. Ele estará na beira da água. Tenha uma boa jornada, $n.', '', '', '', '', '', '', '', '', '', 'Fale com Kurdran Martelo Feroz em Beiralta, que fica no Planalto do Crepúsculo.', 0),
(28239, 'ptBR', 'No Casebre Dente Preto', 'Fale com o Intendente Kaoshin no Casebre Dente Preto, que fica nas Estepes Ardentes.', 'Esse não é o disfarce mais... convincente que eu já vi, mas serve. Afinal de contas, a atuação é o mais importante quando se trabalha sob disfarce. Aja como se devesse estar ali e vai dar tudo certo.$B$BSeu contato no Casebre Dente Preto será um orc chamado Intendente Kaoshin. Ele NÃO SABE que você é $Gum espião:uma espiã;, portanto, mantenha a tranquilidade.$B$BFaça o que o Kaoshin pedir. O Coronel Troteman manterá contato via gnomofone para dar a você qualquer instrução especial.$B$BBoa sorte, soldado.', '', '', '', '', '', '', '', '', '', '', 0),
(28241, 'ptBR', 'Visão do Crepúsculo', 'Localize um Olho do Crepúsculo na Lacuna Negra.', 'Cho\'gall rastreia seus lacaios através destas estranhas esferas mágicas: "Os Olhos do Crepúsculo."$B$BSe eu pusesse as mãos numa delas, aposto que poderíamos usá-la para ficar de olho em Cho\'gall e ver o que ele está tramando. Consiga uma das esferas para mim!$B$BProcure na Lacuna Negra, a leste daqui e ao norte do rio. Encontre um Olho do Crepúsculo e faça o que for necessário para me trazê-lo.', '', '', '', '', '', '', '', '', '', 'Localize um Olho do Crepúsculo na Lacuna Negra.', 0),
(28242, 'ptBR', 'Todos devemos nos sacrificar', 'Mate 10 Xamãs das Trevas.', '<O Olho fala com você, a ‘‘voz\' reverbera como se viesse de todos os lugares ao mesmo tempo.>$B$BVocê busca minhas visões, $r? Meus poderes têm um preço. Os discípulos crepusculares têm me honrado com o sangue dos anões Martelo Feroz das ruínas próximas, mas ainda tenho sede. Talvez você possa fazer melhor.$B$BMate meus velhos mestres e minha visão será sua. Honre-me matando os xamãs das trevas. Sangue é sangue afinal de contas.', '', '', '', '', '', '', '', '', '', 'Retorne ao Olho do Crepúsculo na Lacuna Negra, que fica no Planalto do Crepúsculo.', 0),
(28243, 'ptBR', 'O que os olhos veem', 'Leve o Olho do Crepúsculo para o Aprendiz de Xamã Blundy em Trondamar, que fica no Planalto do Crepúsculo.', 'Muito bem, $r. Você adquiriu meus serviços com sangue. Leve-me de volta ao "Aprendiz de Xamã" de Trondamar.$B$BAh sim, já sei para onde você me levará. As escassas habilidades de Blundy são triviais. Mas você... você me fascina, $r. Com minha visão e suas habilidades, imagine a devastação que poderíamos causar neste mundo...', '', '', '', '', '', '', '', '', '', 'Leve o Olho do Crepúsculo para o Aprendiz de Xamã Blundy em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(28244, 'ptBR', 'O olho que tudo vê', 'Perscrute o Olho do Crepúsculo para o Aprendiz de Xamã Blundy.', 'Vou ser honesto, $n. Essa coisa me arrepia os cabelos das ventas! Mas sabendo tudo o que você passou para trazer isso pra cá, acho que devemos achar um uso pra ele.$B$BVocê primeiro.$B$BEncare o olho e peça para te mostrar o interior do Bastião do Crepúsculo de Cho\'gall. Vamos descobrir o que aquele boçal de duas cabeças pretende e vamos usar o olho contra ele.', '', 'Olho do Crepúsculo perscrutado', '', '', '', '', '', '', '', 'Fale com o Aprendiz de Xamã Blundy em Trondamar, no Planalto do Crepúsculo.', 0),
(28245, 'ptBR', 'Trabalho de bruto', 'Dê uma engraxada das boas em 7 pares de Botas de Rocha Negra.', 'Bah! Sua sorte é que estou com falta de pessoal hoje. Se não fosse por isso, você seria $Go escolhido:a escolhida; para levar as chicotadas da semana.$B$BOs oficiais e soldados de alto escalão precisam das botas polidas. Eles as deixaram na frente das barracas.$B$BQuero ver minha cara refletida nessas botas, $Gbruto:bruta;! Ao trabalho!', '', 'Pares de Botas de Rocha Negra engraxadas', '', '', '', '', '', '', '', 'Fale novamente com o Intendente Kaoshin no Casebre Dente Preto, que fica nas Estepes Ardentes.', 0),
(28246, 'ptBR', 'Atalhos estratégicos', 'Use as Farpas Afiadas de Escorpídeo no Voduzeiro Timan, no topo do Pilar de Cinzas, na Worgmestra Othana, nas jaulas de worg, e em Gorlop, quando ele estiver perto das poças de lava.', '<Estática> $n! $n, está me ouvindo? É o Troteman.$B$BOuça, acabamos de receber as informações que faltavam para nossa próxima missão. Existem três alvos que gostaríamos que você acertasse. O primeiro é o Voduzeiro Timan, a quem você irá encontrar no topo do Pilar de Cinzas. A Worgmestra Othana, que está nas jaulas de worg centrais. Pra terminar, o Gorlop, que está perto das poças de lava ao sul.$B$BVocê vai encontrar as farpas escorpídeas que pegou junto com seus pertences. Use as farpas nos alvos no momento certo.', '', '', '', '', '', '', 'Coronel Troteman', 'Você leva jeito com um aguilhante, hein!', 'Coronel Troteman', '', 0),
(28247, 'ptBR', 'A última das dragonesas', 'Mate Obsídia.', 'Obsídia é uma das últimas dragonesas que podem dar continuidade à linhagem da revoada negra. Ela deve ser morta.$B$BSe conseguir matá-la, você deve informar imediatamente a sua vitória à Lirastrasza. Ela tem lutado há muito tempo por esse resultado.$B$BObrigada por ter mostrado garra nessas batalhas. Você provou ser $gum grande aliado:uma grande aliada;.', 'Obsídia derrotada', '', '', '', '', 'Obsídia derrotada', 'Obsídia', '', '', 'Fale com Lirastrasza a noroeste da Floresta Obsidiana, que fica no Planalto do Crepúsculo.', 0),
(28248, 'ptBR', 'Pontal do Vencedor', 'Fale com Kurdran Martelo Feroz no Pontal do Vencedor.', 'Você já provou suas habilidades e boas intenções. O Martelo do Crepúsculo ficou emboscado na Cidadela depois da queda de Grim Batol e da expulsão dos dragões negros.$B$BVá até seus líderes. Você deve encontrá-los a noroeste, no Pontal do Vencedor. Avise-os que quando o ataque à Cidadela do Crepúsculo iniciar, a revoada vermelha vai preencher os céus. Pode ser que você não seja capaz de compensar por todas as ofensas de seus aliados, mas, nesta batalha, estaremos ao seu lado.$B$BO Martelo do Crepúsculo sucumbirá!', '', '', '', '', '', '', '', '', '', '', 0),
(28249, 'ptBR', 'Cachamorra', 'Fale com a Senhora da Guerra Zaela em Cachamorra.', 'Você já provou suas habilidades e boas intenções. O Martelo do Crepúsculo ficou emboscado na Cidadela depois da queda de Grim Batol e da expulsão dos dragões negros.$B$BVá até seus líderes. Você deve encontrá-los a oeste, em Cachamorra. Avise-os que quando o ataque à Cidadela do Crepúsculo iniciar, a revoada vermelha vai preencher os céus. Pode ser que você não seja capaz de compensar por todas as ofensas de seus aliados, mas, nesta batalha, estaremos ao seu lado.$B$BO Martelo do Crepúsculo sucumbirá!', '', '', '', '', '', '', '', '', '', '', 0),
(28250, 'ptBR', 'Ladrõezinhos canalhas', 'Esmague 30 Pigmeus das Areias com a Marreta da Dinastia Tehret.', 'Não tenho o emprego mais glamouroso do mundo.$B$BNão me preocupo com questões de guerra, com os grandes mistérios das muralhas de Uldum, nem nada disso.$B$BSou o mero encarregado destas terras... e nelas crescem tâmaras.$B$BTem uns surrupiadores de tâmaras caras-de-pau que sobem nos ombros uns dos outros para roubar minhas frutinhas.$B$BNão tolerarei isto.$B$BTome esta marreta forjada pelos titãs, abençoada pelos reis-sóis e quem-sabe-o-quê-mais e esmague esses nanicos!', '', 'Ladrãozinho esmagado', '', '', '', '', '', '', '', 'Fale novamente com Nomarch Teneth nas Terras de Tahret.', 0),
(28251, 'ptBR', 'Confusão na Costa Sul', 'Fale com Serguei Hinoto nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 'Antes de minha captura e prisão eu estava na Costa Sul. Minha função principal nas ruínas era colher amostras de gosma e me certificar de que a praga que liberamos estava se dissipando. Simples e fácil, não fosse pelos worgens que insistem em nos intimidar.$B$BPreciso que você vá à Costa Sul e encontre meu aprendiz, Serguei Hinoto. Descubra se ele está bem e avise-o que retornarei assim que meu trabalho for concluído.$B$BAs ruínas da Costa Sul ficam a sudeste, perto da costa.', '', '', '', '', '', '', '', '', '', '', 0),
(28252, 'ptBR', 'A trompa para chamar kodos', 'Use a Trompa do Chamado para chamar 7 Kodos de Guerra Rocha Negra de volta para o acampamento. Se um kodo se tornar hostil, lute até que ele se submeta.', 'Certo, temos um serviço realmente importante pra você. Precisamos chamar os kodos das pastagens ao sul. O general Thorg\'izog disse que vamos para Cristarrubra em breve, e não vou ser apanhado com meus kodos na mão.$B$BUse esta trompa perto de um kodo. Ele vai retornar ao acampamento quando ouvir o chamado.$B$BÉ melhor você tomar cuidado. Às vezes os kodos são meio briguentos. Quando for assim, é preciso bater neles para que obedeçam.', '', 'Kodos de Guerra Rocha Negra de volta ao acampamento', '', '', '', '', '', '', '', '', 0),
(28253, 'ptBR', 'Tomando a trompa para nós', 'Leve a Trompa do Chamado para o Coronel Troteman em Laceragarra, que fica nas Estepes Ardentes.', '$n, é o Troteman. Eu quero que você guarde aquela trompa. Podemos improvisar e encontrar um jeito de incorporá-la ao plano.$B$BEstou muito preocupado com o que Kaoshin disse sobre atacar Cristarrubra. Sabíamos que havia outro ataque iminente, mas o nosso calendário estava atrasado em vários dias.$B$BFale comigo novamente com a trompa em mãos. Conversaremos de novo aqui em Laceragarra. E tente não estragar aquele disfarce. Seu trabalho de espionagem ainda não terminou.', '', '', '', '', '', '', 'Coronel Troteman', '', '', 'Fale com o Coronel Troteman em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28254, 'ptBR', 'Uma agulha num palheiro infernal', 'Fale com Thelaron Agulhetes em Laceragarra, que fica nas Estepes Ardentes.', 'Nós não podemos enfrentar um exército, $n. Eles vão nos destruir. É por isso que temos que nos ater ao planos de Troteman.$B$BA próxima parte do plano requer uma certa sutileza, algo para o qual eu não tenho muito talento. É aí que você entra.$B$BFale com Thelaron Agulhetes, o alfaiate da cidade. Já entreguei a ele os pelegos e a lama que coletamos. Ele vai precisar tirar as suas medidas.$B$BÉ isso mesmo, $n: você vai $Gdisfarçado:disfarçada;.', '', '', '', '', '', '', '', '', '', '', 0),
(28256, 'ptBR', 'O Crânio de Gul\'dan', 'Reviva a batalha de Illidan pelo Crânio de Gul\'dan.', 'Illidan partiu em busca do Crânio de Gul\'dan, atravessando, espada em punho, exércitos de demônios e matando-os com o poder que fez dele um odiado proscrito.$B$BTestemunhe a batalha, $c. Observe aquele que lutou com o máximo de ferocidade contra os corruptores da Selva Maleva e atingiu-os na fonte.', 'Crânio de Gul\'dan obtido', '', '', '', '', 'Crânio de Gul\'dan obtido', '', '', '', 'Fale novamente com Feronas Vicíssitus na Selva Maleva.', 0),
(28257, 'ptBR', 'A queda de Taecondrius', 'Reviva a batalha de Illidan contra Taecondrius.', 'Sim, Illidan tomou o poder do Crânio de Gul\'dan para si.$B$BMas ele fugiu escondido com o Crânio? Usou-o para sua própria glória? Não... A primeira ação de Illidan foi usar o novo poder para atacar o senhor do medo Taecondrius!$B$BTestemunhe o triunfo de Illidan, $c. Testemunhe como ele reclamou a Selva Maleva dos demônios... e o agradecimento que recebeu.', 'Taecondrius vencido', '', '', '', '', 'Taecondrius vencido', 'Taecondrius', '', '', 'Fale novamente com Feronas Vicíssitus na Selva Maleva.', 0),
(28258, 'ptBR', 'Encontro com Abner Germano', 'Fale com Abner Germano no Centro de Comando ao sul da Cidade Velha, em Ventobravo.', 'Abner Germano me enviou uma mensagem endereçada a ti, $n, dizendo que deseja encontrar-te no Centro de Comando da Cidade Velha, em Ventobravo, o mais rápido possível. Parece ser algo importante, $n.', '', '', '', '', '', '', '', '', '', 'Fale com Abner Germano no Centro de Comando ao sul da Cidade Velha, em Ventobravo.', 0),
(28259, 'ptBR', 'Encontro com Joyce Lopes', 'Fale com Joyce Lopes no porão do Cordeiro Imolado, que fica no Distrito dos Magos em Ventobravo.', 'Acabo de receber um pergaminho de Joyce Lopes. Ela pediu para que você a encontre no Cordeiro Imolado, que fica em Ventobravo. Ela não foi muito clara, mas me parece que se trata de algo importante.', '', '', '', '', '', '', '', '', '', 'Fale com Joyce Lopes no porão do Cordeiro Imolado, que fica no Distrito dos Magos em Ventobravo.', 0),
(28260, 'ptBR', 'Vá se encontrar com Wulf Hansreim', 'Fale com Wulf Hansreim no Centro de Comando ao sul do distrito da Cidade Velha, em Ventobravo.', 'Recebi notícias de Ventobravo dizendo que Wulf Hansreim deseja vê-$Glo:la; imediatamente. Ele está no Centro de Comando, logo ao sul do distrito da Cidade Velha, em Ventobravo.', '', '', '', '', '', '', '', '', '', 'Fale com Wulf Hansreim no Centro de Comando ao sul do distrito da Cidade Velha, em Ventobravo.', 0),
(28261, 'ptBR', 'Traidores entre nós', 'Mate 12 Deslocadores Flamejade na Aldeia Flamejade.', 'Agora que você aprendeu uma lição quanto a manter a mente aberta, talvez queira saber POR QUE eu matei aqueles druidas.$B$BA resposta é simples: eles, simplesmente, não eram druidas.$B$BDemônios ainda perambulam pelas ruínas a olhos vistos, agora disfarçados como amigáveis cuidadores. Veja por si $Gpróprio:própria;... Esta venda foi embebida em sangue demoníaco. Vá para a Aldeia Flamejade, a norte, montanha acima, e coloque a venda sobre os olhos. Ela revelará, até mesmo ao mais cego tolo, a verdadeira natureza de qualquer demônio.', '', '', '', '', '', '', '', 'Não mergulhe muito fundo na primeira vez.', 'Feronas Vicíssitus', 'Fale novamente com Feronas Vicíssitus na Selva Maleva.', 0),
(28262, 'ptBR', 'Encontro com Lorde Tony Romano', 'Fale com Abner Germano no Centro de Comando ao sul da Cidade Velha, em Ventobravo.', 'O Lorde Tony Romano, um dos mais antigos instrutores de ladinos da AVIN, enviou uma mensagem dizendo que deseja falar contigo. Vá para Ventobravo o mais rápido possível e procure por ele no prédio da AVIN, ao sul da Cidade Velha.', '', '', '', '', '', '', '', '', '', 'Fale com o Lorde Tony Romano no quartel general da AVIN, ao sul da Cidade Velha, em Ventobravo.', 0),
(28263, 'ptBR', 'Encontro com Maginor Dumas', 'Fale com Maginor Dumas no Sacrário dos Teurgos, que fica no Distrito dos Magos em Ventobravo.', 'Acabo de receber uma mensagem do Maginor Dumas, um sábio instrutor de magos de Ventobravo. Ele pediu para que você o encontre no Sacrário dos Teurgos, em Ventobravo, o mais rápido possível.', '', '', '', '', '', '', '', '', '', 'Fale com Maginor Dumas no Sacrário dos Teurgos, que fica no Distrito dos Magos em Ventobravo.', 0),
(28264, 'ptBR', 'Gambito de Navarax', 'Mate o demônio que está personificando o Arquidruida Navarax.', 'Eu já estou à caça desses impostores demoníacos há algum tempo e, finalmente, descobri a identidade do líder deles. Trata-se de ninguém menos do que o arquidruida Navarax, líder do Círculo Esmeraldino.$B$BO demônio usa inocentes como escudos. Se eu adentrasse o Bosque Murmuréolo para caçá-lo, seria interceptado por guardas ignorantes... Mas você! Você pode pegá-lo desprevenido.$B$BVolte ao Bosque Murmuréolo. Suba a torre druídica e você encontrará Navarax no topo, em sua câmara em meio aos ramos.', '', '', '', '', '', '', 'Arquidruida Navarax', '', '', 'Fale novamente com a Caçadora Selura no Bosque Murmuréolo, que fica na Selva Maleva.', 0),
(28265, 'ptBR', 'General Thorg\'izog', 'Fale com o General Thorg\'izog.', 'O Kaoshin acabou sendo mais útil do que eu esperava, mas não temos mais o que tratar com ele. Está na hora de você falar com o General. Acho que você está $Gpronto:pronta;.$B$BO general Thorg\'izog é um dos "três poderosos" que comandam as tropas de infantaria aqui nas Estepes Ardentes, da Fortaleza Rocha Negra para noroeste. Vista seu disfarce e vá falar com ele. Veja se consegue ganhar a confiança dele. O Troteman manterá contato, caso precisemos de algo mais.', '', '', '', '', '', '', '', '', '', 'Fale com o General Thorg\'izog na Fortaleza Rocha Negra, que fica nas Estepes Ardentes.', 0),
(28266, 'ptBR', 'Prova de magma', 'Fale com Wyrtle Spreelthonket e peça para que ele liberte o Lorde Magma Kolob. Então, vença o Lorde Magma Kolob em batalha.', 'Suponho que tirarei o máximo de proveito desta situação. Esses goblins mercenários trouxeram este elemental do fogo enorme para minha fortaleza como um agradecimento por tê-los contratado. O que eu vou fazer com um elemental aqui nas estepes? É como levar areia pra praia!$B$BSe está procurando serviço, prove seu valor. Fale com este goblin aqui e desafie o seu elemental para uma briga. O vencedor ganhará o meu respeito e o meu tempo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o General Thorg\'izog na Fortaleza Rocha Negra, que fica nas Estepes Ardentes.', 0),
(28267, 'ptBR', 'Esquadrão de fuzilamento', 'Fale com o Comandante Schnottz.', 'Vem comigo, $r.$b$bEcziste algo que querro mostrarr parra você.', '', 'Seguiu Schnottz', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Porto de Schnottz.', 0),
(28268, 'ptBR', 'Encontro com Lorde Grayson Quebrassombra', 'Fale com o Lorde Grayson Quebrassombra na Catedral da Luz, em Ventobravo.', 'O Lorde Grayson Quebrassombra da Catedral da Luz de Ventobravo pediu para avisá-$Glo:la; que deseja conversar com você da próxima vez que estiver na cidade. Você poderá encontrá-lo no Distrito da Catedral.', '', '', '', '', '', '', '', '', '', 'Fale com o Lorde Grayson Quebrassombra na Catedral da Luz, em Ventobravo.', 0),
(28269, 'ptBR', 'Encontre-me em Vir\'sar', 'Fale com Harrison Jones no Oásis de Vir\'sar.', 'Escute, $n.$B$BEu sabia que esses obeliscos estavam conectados ao Baú da Promessa, mas o buraco é mais embaixo.$b$bParece haver alguma coisa importante a respeito desse baú – algo relativo a um lugar que os criadores chamavam de Salões Primordiais.$b$bAgora que sabemos que esse tal de Schnottz e sua tripulação estão de conluio com Asa da Morte, precisamos chegar lá antes deles.$b$bEsperarei a norte daqui, no Oásis de Vir\'sar.$b$BRápido! Eles estão à nossa frente!', '', '', '', '', '', '', '', '', '', '', 0),
(28271, 'ptBR', 'Produtividade reduzida', 'Mate 15 Escavadores de Schnottz ou Feitores de Schnottz.', 'Tudo bem, $n, aqui vai o que aprendi.$b$bHá um dispositivo titânico encrustado em um lugar chamado Salões Primordiais. É feito para funcionar como uma reinicialização emergencial de toda a vida em Azeroth. Se for ativado, destruirá tudo que vive neste mundo!$b$bEle foi feito para ser usado em determinadas condições extremas, mas, se o Asa da Morte conseguir corromper os vigias titânicos, ele poderá usar o conteúdo do baú para ativar o dispositivo.$b$bVá ao Obelisco da Lua, $n. Atrase o serviço deles!', '', 'Empregados de Schnottz mortos no Obelisco da Lua', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Oásis de Vir\'sar.', 0),
(28272, 'ptBR', 'Peças faltantes', 'Colete 7 Pergaminhos de Cobre Antigos.', 'Somente algumas informações específicas que me faltam.$b$bUma vez que essas lacunas estiverem preenchidas, estaremos prontos para reativar o último obelisco. Depois, será uma corrida para descobrirmos o Baú da Promessa antes do Schnottz e seus camaradas.$b$bAqueles tolos estão escavando o mais rápido que podem. Eles estão arruinando mais do que saqueando!$b$bVá ao obelisco e inspecione o butim deles, $n.$b$bVeja se você consegue encontrar as peças que faltam.', '', '', '', '', '', '', '', '', '', 'Fale com Harrison no Oásis de Vir\'sar.', 0),
(28273, 'ptBR', 'Amigo de um amigo', 'Harrison quer você fale com Sullah no Oásis de Vir\'sar.', 'Preciso desempacotar as minhas coisas e investigar um pouco a área. Nesse meio-tempo, eu gostaria que você conhecesse um velho amigo meu.$b$bO Sullah e eu nos conhecemos há muito tempo. Ele é um homem em que se pode confiar, e isso é bastante raro hoje em dia.$b$bPor que você não vai lá e se apresenta?', '', '', '', '', '', '', '', '', '', '', 0),
(28274, 'ptBR', 'Duas tendas', 'Acompanhe o Sullah até o Espetáculo de Sullah.', 'Olhe para você, amig$go:a;. Esta sua grande aventura está deixando você dur$go:a;!$b$bVocê precisa relaxar e se soltar. Você está tens$go:a; demais, dá para notar só de olhar.$b$bConfie em mim, eu entendo de relaxamento!$b$bFalando em tendas, vejo que o Jones me trouxe as que pedi.$b$bVamos, amig$go:a;. Venha comigo!', '', 'Sullah acompanhado', '', '', '', '', '', '', '', 'Fale com o Sullah no Espetáculo de Sullah.', 0),
(28275, 'ptBR', 'Lançar bombas!', 'Destrua 10 Barcos de Suprimentos Medonhos.', 'O Estaleiro Bonfilho sempre recebe carregamentos pelo mar, e precisamos acabar com isso. Há vários canhões defensivos nas docas e, se você conseguir chegar até eles, poderá usá-los para destruir os barcos de suprimentos.$B$BVá lá e veja o que pode fazer. Depois me informe como está o andamento da missão.', '', 'Barcos de Suprimentos Medonhos destruídos', '', '', '', '', '', '', '', 'Apresente-se novamente ao Sargento Dias na Base de Operações de Baradin após cumprir a missão.', 0),
(28276, 'ptBR', 'O segredo de Sal-het', 'Encontre Sal-het no Extremo Sul do Cume de Solarguarda em Uldum.', 'Olha, $n. Antes que desista de mim, há algo que quero lhe mostrar.$B$BVeja bem, não sou muito de luta. Não tenho muita coordenação.$B$BTenho uma mente mais tática.$B$BEncontre-me no extremo sul do cume e lhe mostrarei.', '', '', '', '', '', '', '', '', '', '', 0),
(28277, 'ptBR', 'Sal-het, o Tático', 'Fale com Sal-het e mate 30 Catadores Rosnassangue.', 'Desde que eu era pequenininho, sempre quis ser um general.$B$BAnsiava por entrar no exército. Mas, como pode ver, minhas habilidades para combate não são as melhores.$B$BNão é a primeira vez que sou enviado para matar hienas. De fato, já me mandaram tantas vezes que fiz amizade com estes leões e os treinei para executarem minha tarefa.$B$BEles são meus soldados e, sob meu comando, matarão muitas hienas. Observe!', '', 'Catador Rosnassangue morto', '', '', '', '', '', '', '', 'Fale novamente com Sal-het no Cume de Solarguarda em Uldum.', 0),
(28278, 'ptBR', 'Eu sou a lei e o açoite', 'Use a Borduna da Disciplina de Rocha Negra em 20 soldados nos Campos de Honra. Se um deles descobrir o seu disfarce, bata nele com a borduna até a morte, antes que ele possa desmascarar você.', 'Eu estava procurando $gum:uma; soldado $gbom:boa; e forte como você. Preciso de alguém que mantenha minhas tropas na linha.$B$BFora da fortaleza, você encontrará orcs, ogros e trolls se preparando para o ataque a Cristarrubra. Meus sargentos os mantém na linha, mas eu gostaria que você os ajudasse.$B$BLeve esta clava e discipline alguns dos meus soldados. Estejam eles se comportando mal ou perfeitamente alinhados, quero que apanhem. Quero que fiquem concentrados, prontos para a batalha e obedientes.$B$BAgora, vá.', '', 'Lacaios Rocha Negra disciplinados', '', '', '', '', '', '', '', 'Fale novamente com o General Thorg\'izog na Fortaleza Rocha Negra, que fica nas Estepes Ardentes.', 0),
(28279, 'ptBR', 'Abuso de poder', 'Mate 5 Sargentos Rocha Negra usando a Borduna da Disciplina de Rocha Negra. Derrote-os rapidamente antes que eles tenham uma chance de desmascarar você.', '$n? Aqui é o Troteman.$B$BParece que você conquistou a confiança de Thorg\'izog, e ele confiou a você a disciplina das tropas. Isso foi muita sorte.$B$BPrecisamos que você acabe com os sargentos dele. Você os encontrará montados em lobos, do lado de fora da Fortaleza Rocha Negra, nos Campos de Honra. Use a borduna neles várias vezes, até que morram. Você terá que agir rapidamente. Se eles perceberem que você não é um deles, eles podem $Gdesmascará-lo:desmascará-la;. Ataque com rapidez e violência, $n.$B$BTroteman, câmbio e desligo.', '', 'Sargentos Rocha Negra eliminados', '', '', '', '', 'Coronel Troteman', 'Hahaha! Bom trabalho!', 'Coronel Troteman', '', 0),
(28280, 'ptBR', 'Chuva de dracos que caem sem parar!', 'Use o Atira-lança Cai-cai-dragão para matar 8 Dracos Sombrios Presa do Dragão.', 'Eca! Eles estão aqui, $n. Eles estão aqui!$B$BEu queria equipar um exército inteirinho com meus Atira-lanças Cai-cai-dragão, mas tudo o que tenho é um protótipo caríssimo e ainda não testado. Aqui, tome ele!$B$BAtire nos dracos sombrios Presa do Dragão que sobrevoam Trondamar e derrube eles do céu!', '', '', '', '', '', '', '', '', '', 'Fale com Nilo Trancanal em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(28281, 'ptBR', 'Resistência em Trondamar', 'Mate 8 Garracéus Presa do Dragão que estejam a pé.', 'Vou dar um crédito pra ti e teus amigos da Aliança. Vocês deram mesmo um jeito nos Presa do Dragão!$B$BMuitos dos cavaleiros estão sem montaria, mas continuam vindo para nos atacar e nossos soldados vão precisar de ajuda.$B$BMate os Garracéus Presa do Dragão que estão a pé e Trondamar será eternamente grata a ti.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Colin Trondamar em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(28282, 'ptBR', 'Narkrall, o domadracos', 'Mate Narkrall Garrasgo. Fale com Colin Trondamar quando estiver $gpronto:pronta;.', 'Tem um Presa do Dragão neste lugar, aquele que eles chamam "Narkrall, o domadracos." Não sei como ele exerce poder sobre essas criaturas, mas o terror sombrio que ele cavalga é tão sórdido e bruto como nunca se viu no céu sobre o Planalto.$B$B$n, Narkrall é o fanático que tirou a vida do meu pai e deixou Trondamar em minhas mãos.$B$BNão consigo lidar com ele sozinho, mas sei do que você é capaz, $c. Talvez juntos possamos dar um fim a isso.$B$BQuando estiver $Gpronto:pronta;, vamos juntos combater Narkrall!', '', '', '', '', '', '', 'Narkrall Garrasgo', '', '', 'Fale com Colin Trondamar em Trondamar, que fica no Planalto do Crepúsculo.', 0),
(28283, 'ptBR', 'Que chocalho é este?', 'Leve o Chocalho de Ossos para ser examinado no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 'Você viu aquele chocalho brilhante largado no chão, perto da cabana de Isha?', '', '', '', '', '', '', '', '', '', '', 0),
(28284, 'ptBR', 'Que chocalho é este?', 'Leve o Chocalho de Ossos para ser examinado no Pináculo da Nuvem Negra, que fica em Mil Agulhas.', 'Você viu aquele chocalho brilhante largado no chão, perto da cabana de Isha?', '', '', '', '', '', '', '', '', '', '', 0),
(28285, 'ptBR', 'Encontro com a Alta-sacerdotisa Laurena', 'Fale com a Alta-sacerdotisa Laurena na Catedral da Luz, em Ventobravo.', 'Acabo de receber um pergaminho da Catedral da Luz, $n, informando que a alta-sacerdotisa Laurena deseja conversar contigo. Apressa-te, pois ela $Go:a; aguarda.', '', '', '', '', '', '', '', '', '', 'Fale com a Alta-sacerdotisa Laurena na Catedral da Luz, em Ventobravo.', 0),
(28286, 'ptBR', 'Dano suficiente por um dia', 'Fale novamente com o Coronel Troteman em Laceragarra.', 'Não temos mais necessidade de criar estratégias contra Thorg\'izog ou contra as tropas de infantaria Rocha Negra. Precisamos continuar com a fase seguinte do plano.$B$BQuando tiver terminado na fortaleza, volte a falar conosco aqui em Laceragarra.', '', '', '', '', '', '', 'Coronel Troteman', '', '', 'Fale com o Coronel Troteman em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28287, 'ptBR', 'Encontro com a Clarividente Umbrua', 'Fale com a Clarividente Umbrua no Barril Dourado, que fica no Distrito dos Anões em Ventobravo.', 'Um mensageiro enviado pela clarividente Umbrua acabou de partir, $n. Na mensagem, ela diz ter importantes assuntos a serem tratados contigo e que deves encontrá-la no Barril Dourado, que fica no Distrito dos Anões de Ventobravo, o mais rápido que puderes.', '', '', '', '', '', '', '', '', '', 'Fale com a Clarividente Umbrua no Barril Dourado, que fica no Distrito dos Anões em Ventobravo.', 0),
(28288, 'ptBR', 'Abra os olhos deles', 'Use o Prisma de Delaris para aterrorizar 20 Diabretes Flamejade.', 'Antes que você vá...$B$BAproveitei o tempo que passei "a sós" com o Diabretim para aprender algumas coisas interessantes sobre diabretes. Ele acabou me contando qual é a coisa que mais lhes causa medo. Algo que os deixa absolutamente apavorados.$B$BIsso me soou tanto útil quanto interessante, então eu fiz uma conjuração básica. Este prisma projetará uma imagem de... bem, daquilo que o Diabretim descreveu.$B$BA Cordilheira Sombria continua infestada por diabretes. Por que você não vai lá testar a reação deles para mim?', '', 'Diabretes aterrorizados', '', '', '', '', '', '', '', 'Fale novamente com a Arcanista Delaris nas Ruínas de Constellas, que ficam na Selva Maleva.', 0),
(28289, 'ptBR', 'O chamado da Clareira da Lua', 'Viaje até a Clareira da Lua e fale com Loganaar no Refúgio Noturno.', 'Recebi notícias de que nossos irmãos da Clareira da Lua querem falar com você, $n. Você devia ir ao Refúgio Noturno falar com Loganaar. Ele vai te explicar tudo o que você precisa saber.', '', '', '', '', '', '', '', '', '', 'Viaje até a Clareira da Lua e fale com Loganaar no Refúgio Noturno.', 0),
(28290, 'ptBR', 'Encontro com Grezz Iracarpos', 'Fale com Grezz Iracarpos no Vale da Honra, em Orgrimmar.', 'Acabo de receber uma mensagem urgente de Grezz Iracarpos, $n. Ele deseja encontrá-$Glo:la; imediatamente no Vale da Honra, em Orgrimmar. Acredito que ele tenha uma importante missão para você.', '', '', '', '', '', '', '', '', '', 'Fale com Grezz Iracarpos no Vale da Honra, em Orgrimmar.', 0),
(28291, 'ptBR', 'Retorne ao acampamento', 'Fale novamente com o Alto-comandante Kamsés no Posto Avançado da Legião Ramkahen.', 'O que acha, $n? Talvez o alto-comandante me dê o comando de alguns homens.$B$BTalvez possamos comandar um regimento juntos. O que acha?', '', '', '', '', '', '', '', '', '', '', 0),
(28292, 'ptBR', 'Aquilo não é nenhuma pirâmide!', 'Fale com Harrison Jones na Bastilha Ventobravo, em Ventobravo.', 'A pirâmide do Terraço do Criador, em Uldum, é diferente de todas as outras. É uma máquina gigantesca que pode ser configurada para inúmeros usos.$B$BO Martelo do Crepúsculo ia transformar aquilo em uma arma de destruição em massa para o Asa da Morte!$B$B$n, pegue o portal e conte isso para o Harrison Jones, que está em Ventobravo. Ele vai saber o que fazer.', '', '', '', '', '', '', '', '', '', '', 0),
(28293, 'ptBR', 'Aquilo não é nenhuma pirâmide!', 'Fale com Belloc Gumélion no Castelo Grommash, em Orgrimmar.', 'A pirâmide do Terraço do Criador, em Uldum, é diferente de todas as outras. É uma máquina gigantesca que pode ser configurada para inúmeros usos.$B$BO Martelo do Crepúsculo ia transformar aquilo em uma arma de destruição em massa para o Asa da Morte!$B$B$n, pegue o portal e conte isso para o Belloc Gumélion, que está no Castelo Grommash, em Orgrimmar. Ele vai saber o que fazer.', '', '', '', '', '', '', '', '', '', '', 0),
(28294, 'ptBR', 'A conferência de Kirthaven', 'Fale com Lachlan MacGraff em Kirthaven, que fica no Planalto do Crepúsculo.', 'Depois da lição que demos neles, os ataques dos Presa do Dragão a Trondamar devem parar. Talvez os Martelo Feroz tenham mesmo um lugar na sua Aliança – nós temos uma dívida contigo.$B$BEm Kirthaven, nosso grande xamã Lachlan MacGraff tem tentado marcar uma reunião com os líderes das famílias dos sobreviventes Martelo Feroz. É uma tarefa difícil para fazermos juntos, mas estou disposto a dar o pontapé inicial.$B$BVoe até Kirthaven, ao norte, e fale com Lachlan MacGraff. Te encontro lá!', '', '', '', '', '', '', '', '', '', 'Fale com Lachlan MacGraff em Kirthaven, que fica no Planalto do Crepúsculo.', 0),
(28295, 'ptBR', 'Encontro com a caravana', 'Fale com Adarrah no Vale Moitagulhas, que fica em Tanaris.', 'A pirâmide do Terraço do Criador, em Uldum, pode ser usada como um tipo de super arma que é capaz de destruir todas as formas de vida de Azeroth.$B$B<Harrison para para pensar por um momento.>$B$BVocê tem que continuar a pesquisa que começou. Siga para o deserto de Tanaris, que fica na fronteira sul de Kalimdor. Tem uma caravana lá que vai partir em breve para Uldum.$B$BQuem sabe você não se junta a eles?', '', '', '', '', '', '', '', '', '', '', 0),
(28296, 'ptBR', 'Encontro com a caravana', 'Fale com Adarrah no Vale Moitagulhas, que fica em Tanaris.', 'A pirâmide do Terraço do Criador, em Uldum, pode ser usada como um tipo de super arma que é capaz de acabar com todas as formas de vida de Azeroth.$B$B<Belloc para para pensar por um momento.>$B$BVocê tem que continuar a boa pesquisa que tem feito. Siga para o deserto de Tanaris, a sul. Tem uma caravana lá que vai partir em breve para Uldum.$B$BQuem sabe você não se junta a eles?', '', '', '', '', '', '', '', '', '', '', 0),
(28297, 'ptBR', 'Encontro com Ormak Tiroatroz', 'Fale com Ormak Tiroatroz no Vale da Honra, em Orgrimmar.', 'Recebi um pergaminho de Ormak Tiroatroz, de Orgrimmar. Ele pediu para que você vá ao Vale da Honra encontrá-lo o mais rápido possível. Parecia ser urgente, $n.', '', '', '', '', '', '', '', '', '', 'Fale com Ormak Tiroatroz no Vale da Honra, em Orgrimmar.', 0),
(28298, 'ptBR', 'Encontro com Gordul', 'Fale com Gordul no Antro das Sombras de Orgrimmar.', 'Gordul, líder dos ladinos da Mão Despedaçada de Orgrimmar, deseja vê-$Glo:la;. Vá para Orgrimmar o mais rápido possível, $n, e fale com ele no Antro das Sombras. Acredito que ele tenha uma importante missão para você.', '', '', '', '', '', '', '', '', '', 'Fale com Gordul no Antro das Sombras, em Orgrimmar.', 0),
(28299, 'ptBR', 'Encontre-se com Kranosh', 'Fale com Kranosh no Antro das Sombras, em Orgrimmar.', 'Acabo de receber uma mensagem de Kranosh, o instrutor de bruxos mais notável de Orgrimmar. Ele pede que você vá imediatamente para Orgrimmar e encontre-o no Antro das Sombras. Pelo o que entendi, ele parece ter uma importante missão para você.', '', '', '', '', '', '', '', '', '', 'Fale com Kranosh no Antro das Sombras, em Orgrimmar.', 0),
(28300, 'ptBR', 'Encontro com Ureda', 'Fale com Ureda no Antro das Sombras, em Orgrimmar.', 'Acabo de receber um pergaminho endereçado a você, $n. É de Ureda, uma das instrutoras de magos de Orgrimmar. Ela diz para encontrá-la no Antro das Sombras na próxima vez que passar por Orgrimmar.', '', '', '', '', '', '', '', '', '', 'Fale com Ureda no Antro das Sombras, em Orgrimmar.', 0),
(28301, 'ptBR', 'Fale com Terga Rompe-terra', 'Fale com Terga Rompe-terra no Vale da Sabedoria, em Orgrimmar.', 'Acaba de chegar uma mensagem urgente para você, $n. É da Terga Rompe-terra, uma das instrutoras de xamã de Orgrimmar. Ela deseja vê-$Glo:la; o mais rápido possível.', '', '', '', '', '', '', '', '', '', 'Fale com Terga Rompe-terra no Vale da Sabedoria, em Orgrimmar.', 0),
(28302, 'ptBR', 'Encontro com o Andarilho do Sol Atohmo', 'Fale com o Andarilho do Sol Atohmo no Vale da Sabedoria, em Orgrimmar.', 'Encaminhe-se para Orgrimmar o mais rápido que puder, $n. O Andarilho do Sol Atohmo mandou uma mensagem dizendo que deseja tratar um assunto de extrema importância para a Horda com você. Encontre-o no Vale da Sabedoria.', '', '', '', '', '', '', '', '', '', 'Fale com o Andarilho do Sol Atohmo no Vale da Sabedoria, em Orgrimmar.', 0),
(28303, 'ptBR', 'Encontro com o Mestre Pyreanor', 'Fale com o Mestre Pyreanor no Castelo Grommash, em Orgrimmar.', 'O mestre Pyreanor enviou uma mensagem urgente, $n. Ele pede que você o encontre no Castelo Grommash, que fica no Vale da Força, em Orgrimmar, na próxima vez que você passar por lá. Me pareceu que ele tem uma tarefa importante para tratar com você.', '', '', '', '', '', '', '', '', '', 'Fale com o Mestre Pyreanor no Castelo Grommash, em Orgrimmar.', 0),
(28304, 'ptBR', 'Encontro com a clériga das trevas Cecille', 'Fale com a Clériga das Trevas Cecille no Castelo Grommash, que fica no Vale da Força em Orgrimmar.', 'A clériga das trevas Cecille, integrante da delegação da Rainha Banshee em Orgrimmar, pediu que você a encontre na próxima vez que estiver na cidade. Ela se encontra no Castelo Grommash, que fica no Vale da Força em Orgrimmar. Deve se tratar de algo importante, $n, caso contrário ela não teria sido tão direta.', '', '', '', '', '', '', '', '', '', 'Fale com a Clériga das Trevas Cecille no Castelo Grommash, que fica no Vale da Força em Orgrimmar.', 0),
(28305, 'ptBR', 'O destino do Posto Peçonha', 'Fale com Kelnir Cantafolha no Posto Peçonha.', 'Enquanto lidávamos com Jaedenar, enviei uma amiga para o Posto Peçonha, ao norte. Costumávamos receber visitas esporádicas de taurens, mas, recentemente, eles pararam de vir.$B$BMinha amiga, Kelnir Cantafolha, nunca mais voltou. Você viajaria para o norte para ver como estão ela e a situação em Peçonha?$B$BCaso você a encontre, tenha cautela... Dríades como Kelnir tendem a ver outras raças com certa desconfiança.', '', '', '', '', '', '', '', '', '', '', 0),
(28306, 'ptBR', 'Bosque Murmuréolo', 'Fale com Macia Bosquepuro no Bosque Murmuréolo.', 'Você nos ajudou tanto!$B$BVou ficar um pouco mais por aqui para cuidar do pobre Sr. Tauren até que ele pare de vomitar tanto. Por que você não segue em direção ao norte, para o Bosque Murmuréolo? Lá é muito bonito, e os druidas são tão amigáveis!$B$BDiga à Senhora Bosquepuro que estou bem. Ela vai ficar preocupada se eu ficar longe por muito tempo. Pode ser que ela peça sua ajuda com as flores dela, também! É tão divertido!', '', '', '', '', '', '', '', '', '', '', 0),
(28307, 'ptBR', 'Encontro com Tyelis', 'Fale com Tyelis no Castelo Grommash, que fica no Vale da Força em Orgrimmar.', 'Tyelis, membro da delegação de Luaprata em Orgrimmar, pediu que você o encontre na próxima vez estiver na cidade. Ele está no Castelo Grommash, que fica no Vale da Força em Orgrimmar. Deve se tratar de algo importante, caso contrário ele não teria sido tão direto, $N.', '', '', '', '', '', '', '', '', '', 'Fale com Tyelis no Castelo Grommash, que fica no Vale da Força em Orgrimmar.', 0),
(28308, 'ptBR', 'Encontro com a vidente Liwatha', 'Fale com a Vidente Liwatha no Vale da Sabedoria, em Orgrimmar.', 'A Vidente Liwatha lhe manda saudações do Vale da Sabedoria em Orgrimmar, $n. Ela pediu para que você a visite na próxima vez que estiver passando por lá. Parecia ser importante o que quer que ela queira conversar com você.', '', '', '', '', '', '', '', '', '', 'Fale com a Vidente Liwatha no Vale da Sabedoria, em Orgrimmar.', 0),
(28309, 'ptBR', 'Encontro com o andarilho das sombras Zuru', 'Fale com o Andarilho das Sombras Zuru no Vale dos Espíritos, em Orgrimmar.', 'O andarilho das sombras Zuru, um reverenciado instrutor de sacerdotes, solicitou que você vá a Orgrimmar para encontrá-lo. Você poderá achá-lo no Vale dos Espíritos, junto com os outros instrutores Lançanegra. Deve se tratar de algo importante, $n, caso contrário ele não teria sido tão direto.', '', '', '', '', '', '', '', '', '', 'Fale com o Andarilho das Sombras Zuru no Vale dos Espíritos, em Orgrimmar.', 0),
(28310, 'ptBR', 'A Vigia de Morgan', 'Fale com Oralius na Vigia de Morgan, que fica nas Estepes Ardentes.', 'Nosso trabalho aqui em Laceragarra está terminado, em grande parte graças a você. Agora, vamos para o leste, para a Vigia de Morgan.$B$BNossas informações dizem que a Vigia de Morgan está vazia, pois a maioria dos seus habitantes foi para a Montanha Rocha Negra lutar contra os Rocha Negra. Ela deve servir como uma base de operações adequada para os últimos estágios do nosso plano.$B$BÉ claro que o Keeshan vai encontrar com você no caminho. E eu também.', '', '', '', '', '', '', '', '', '', '', 0),
(28311, 'ptBR', 'Cinzas negras', 'Obtenha 9 montes de Cinzas Obsidianas.', 'Preciso que você junte mais umas coisas antes que possamos acabar com o que restou do exército Rocha Negra. Se vamos fazer isso, vamos fazer direito, e isso significa estarmos preparados.$B$BPreciso de cinzas, $n. E não é qualquer cinza: são as cinzas dos elementais maiores de obsidiana, que vagam pelas planícies a noroeste. Ela é muito, muito negra, e é disso que precisamos para nosso próximo disfarce.$B$BNão se preocupe, você já tem um disfarce. Este será para alguém... Bem, para ALGO diferente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Coronel Troteman na Vigia de Morgan, que fica nas Estepes Ardentes.', 0),
(28312, 'ptBR', 'Demônios Latentes', 'Obtenha 18 Lumenoides Caídos.', 'A lava próxima daqui, a oeste, é como um hospedeiro para os lumenoides, um tipo de demônio do fogo que há muito vaga pelas estepes. A situação no exército Rocha Negra é tal que, se formos cuidadosos, talvez consigamos pôr alguns desses lumenoides atrás das linhas inimigas para causar confusão.$B$BTraga-me os corpos de vários lumenoides. Como demônios, eles são ressuscitados com facilidade, e podemos usá-los para nossos próprios fins.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Coronel Troteman na Vigia de Morgan, que fica nas Estepes Ardentes.', 0),
(28313, 'ptBR', 'Um montão de worgs deliciosos', 'Use a Worgserra nos corpos dos Worgs Incandescentes Gigantes mortos para obter 40 Costeletas de Worg.', 'Vamos precisar de carne fresca, e isso significa que você vai ter que caçar uns worgs deste lado da estepe.$b$b<Troteman traz uma grande serra e a entrega a você.>$b$bCace os worgs incandescentes gigantes. Após abatê-los, use esta serra para tirar os melhores cortes de carne. Os worgs estão espalhados por toda a estepe, mas a matilha mais próxima domina as terras a nordeste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Coronel Troteman na Vigia de Morgan, que fica nas Estepes Ardentes.', 0),
(28314, 'ptBR', 'Passeio sangrento', 'Mate 25 Dragomorfos Negros ou Draconoides Negros.', 'Minhas pernas estão meio inquietas de novo. Está interessad$go:a; em dar um passeio, $n?$B$BVamos dar uma volta até o Rochedo Malhorrendo. Eu gostaria de investigar o exército Rocha Negra antes de darmos o próximo passo, e acho que podemos também matar alguns deles no caminho.', '', '', '', '', '', '', '', '', '', '', 0),
(28315, 'ptBR', 'Vanguarda dracônica', 'Mate a Domadora de Dragonetes Akumi, Minyoth, Tugnar Gorjavil e Terromath, o Marcado.', 'Os orcs Rocha Negra não vêm sozinhos. Você já viu que os ogros Pirobucho e os trolls Fumocardo estão ao lado deles. Infelizmente, eles também se juntaram com a revoada negra.$B$BOs orcs e os dragões já mandaram alguns de seus campeões para ficar de guarda em pontos de reagrupamento, que são marcados por um crânio de dragão em uma estaca. Você e eu vamos encontrar esses pontos de reagrupamento e acabar com essa vanguarda antes que a batalha comece.$B$B$GPreparado:Preparada;?', '', '', '', '', '', '', '', '', '', 'Fale com John J. Keeshan.', 0),
(28316, 'ptBR', 'Acordo com um dragão', 'Entregue os Dragonetinhos Resgatados a Acrídeo na Rocha Coleante, que fica nas Estepes Ardentes.', 'Enquanto estamos circulando pelo Rochedo Malhorrendo, tem mais uma parada que precisamos fazer.$B$BLembra dos filhotes que você libertou na Colina dos Dragonetes? O Troteman ficou com eles, e vamos entregá-los a alguém que vai cuidar deles melhor do que nós. Ele está na Rocha Coleante, a nordeste do Rochedo Malhorrendo.$B$BO nome dele é Acrídeo, e talvez ele seja a chave para a vitória na batalha que se aproxima.', '', '', '', '', '', '', '', '', '', 'Fale com Acrídeo na Rocha Coleante, que fica nas Estepes Ardentes.', 0),
(28317, 'ptBR', 'Uma entrega para Thorg\'izog', 'Usando seu Disfarce de Rocha Negra, leve as Costeletas Marinadas na Sidra Vil para o General Thorg\'izog na Fornalha Pirobucho, que fica nas Estepes Ardentes. Fale com o Coronel Troteman se você precisar de um Disfarce de Rocha Negra.', 'O general Thorg\'izog está entre os ogros da Fornalha Pirobucho, uma caverna na fronteira oeste do Rochedo Malhorrendo. Entregue isto para ele e para os ogros.$B$BDentro deste pacote, você encontrará as Costeletas de Worg que você trouxe, marinadas na sidra redonda vil que pegamos do Altar das Tempestades.$B$BEu evitaria comê-las se fosse você.$B$BLeve-as para o general Thorg\'izog. Ele vai alimentar as suas tropas e, se tivermos sorte, ele mesmo vai comer.', '', '', '', '', '', '', '', '', '', 'Fale com o General Thorg\'izog na Fornalha Pirobucho, que fica nas Estepes Ardentes.', 0),
(28318, 'ptBR', 'Uma entrega para Niralak', 'Usando seu Disfarce de Rocha Negra, vá ao Abrigo da Caveira e convença Niralak, o Senhor dos Dragões, a aceitar o Caixote de Lumenoides Adormecidos. Fale com o Coronel Troteman se você precisar de um Disfarce de Rocha Negra.', 'Os bruxos do clã Rocha Negra costumam praticar sua magia no Abrigo da Caveira, uma caverna na área leste do Rochedo Malhorrendo. Seu líder, Xi\'lun, está ocupado em outro lugar, então, outro dos "três poderosos" está cuidando da caverna: Niralak, o Senhor dos Dragões. Niralak é especializado em dragões, não em necromancia.$B$BEu usei a areia do sono naqueles lumenoides que você capturou. Tente convencer Niralak de que eles são diabretes de bruxos, não lumenoides. Quando eles acordarem, eles não vão estar felizes.', '', '', '', '', '', '', '', '', '', 'Fale com Niralak, o Senhor dos Dragões, no Abrigo da Caveira, que fica nas Estepes Ardentes.', 0),
(28319, 'ptBR', 'Uma entrega para Xi\'lun', 'Usando o Disfarce de Rocha Negra, entregue o Orbe Límpido de Vidro ao Alto Bruxo Xi\'lun no topo do Rochedo Malhorrendo, que fica nas Estepes Ardentes.', 'Nossos dados nos dizem que o alto bruxo Xi\'lun, o último dos "três poderosos", está na caverna que fica no topo do Pico Malhorrendo, preparando-se para o grande momento.$B$BEle está esperando uma entrega: um orbe de dominância, com o qual ele pode fazer um poderoso ritual de evocação. Quero que você dê isto a ele.$B$B<Troteman dá a você um orbe de vidro.>$B$BEste é o orbe límpido de vidro que você tirou do Altar das Tempestades. Ele está sem poder algum. Dê a Xi\'lun e torça para que ele não perceba.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Alto Bruxo Xi\'lun no Rochedo Malhorrendo, que fica nas Estepes Ardentes.', 0),
(28320, 'ptBR', 'Ataque ao Rochedo Malhorrendo', 'Mate 200 Invasores Rocha Negra. Se você perder o veículo, use a Trompa do Chamado para evocá-lo novamente.', 'É isso, $n. Agora é a hora da verdade. Agora, as peças vão se encaixar.$B$BPrepare-se e venha comigo. Vamos falar com Acrídeo e cobrar o favor que ele nos deve. Então, impediremos a invasão a Cristarrubra antes mesmo que ela comece.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Coronel Troteman na Vigia de Morgan, que fica nas Estepes Ardentes.', 0),
(28321, 'ptBR', 'Glória em meio ao caos', 'Mate o General Thorg\'izog, Niralak, o Senhor dos Dragões, e o Alto Bruxo Xi\'lun.', 'Você e o Keeshan vão voltar àquela montanha. Três orcs sobreviveram ao ataque, e não vamos descansar até que eles morram.$B$BIsso mesmo, estou falando dos "três poderosos".$B$BO general Thorg\'izog rastejou de volta para a Fornalha Pirobucho. Niralak, o Senhor dos Dragões, está escondido na caverna que fica no topo da montanha. Xi\'lun está nos fundos do Abrigo da Caveira, conspirando com seus amigos bruxos.$B$BDeixe sua marca, $n. Cace aqueles Rocha Negra chorões e mostre para eles o poder de Cristarrubra!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Coronel Troteman na Vigia de Morgan, que fica nas Estepes Ardentes.', 0),
(28322, 'ptBR', 'Os espólios da guerra', 'Inspecione o Caixote de Suprimentos Restantes na Vigia de Morgan, que fica nas Estepes Ardentes.', 'Nós derrubamos um gigante hoje, $n. Enquanto os orcs Rocha Negra estiverem reunidos no pináculo, duvido que os planos os levem para perto de Cristarrubra. Você e o Keeshan cuidaram disso.$B$BEu diria que nos viramos bem aqui nas Estepes Ardentes: aqueles suprimentos de bruxaria que pegamos certamente foram úteis, assim como as cinzas obsidianas que usamos para ocultar o nosso dragão.$B$BMas sobraram algumas coisas. Por favor, pegue o que desejar antes de continuar para além das estepes.', '', '', '', '', '', '', '', '', '', '', 0),
(28323, 'ptBR', 'Encontro com o irmão Pratassacra', 'Fale com o Irmão Pratassacra no Beco do Goblin, que fica em Orgrimmar.', 'O irmão Pratassacra deseja falar contigo. Ele pediu para que você o encontre no Beco do Goblin da próxima vez que você passar por Orgrimmar. Me pareceu que ele tem algo muito importante para lhe falar.', '', '', '', '', '', '', '', '', '', 'Fale com o Irmão Pratassacra no Beco do Goblin, que fica em Orgrimmar.', 0),
(28324, 'ptBR', 'Pesquisas de letalidade', 'Colete 250 Amostras da Praga.', 'Usamos uma potentíssima praga contra os humanos da Costa Sul. Como você ver, funcionou. O problema do uso de pragas, porém, é que elas insistem em permanecer mesmo depois de servirem ao seu propósito.$B$BPreciso que você leve este kit de análise e vá a campo para fazer uma contagem da letalidade dos visgos que lançamos na área. Use o analisador de letalidade nos pragalodos que estão nas poças de lodo. Volte quando tiver dados concretos.', '', 'Amostras de Pragalodo coletadas', '', '', '', '', '', '', '', 'Fale com Serguei Hinoto nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28325, 'ptBR', 'Uma verdade conveniente', 'Recolha 8 Tubos Empesteados Usados.', 'Reciclagem! É a coqueluche do momento. A Rainha Banshee decretou que devemos preservar se desejamos prosperar como povo. Todos devem fazer sua parte, certo? Dito isso, você fará nossa parte por nós.$B$BHá milhares de fragmentos de tubos empesteados pela Costa Sul. Podemos reutilizar esses fragmentos para incrementar o bombardeio de peste. Dirija-se às ruínas e pegue tudo o que encontrar.', '', '', '', '', '', '', '', '', '', 'Fale com Serguei Hinoto nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28326, 'ptBR', 'Arrumando os peões', 'Fale novamente com o Coronel Troteman na Vigia de Morgan, que fica nas Estepes Ardentes.', '$n. Parece que você e o Keeshan terminaram suas tarefas. Também terminei a minha.$B$BVolte para a Vigia de Morgan. Preparei alguns pacotes para entregar aos "três poderosos": Thorg\'izog, Niralak e Xi\'lun. Você já conheceu o general Thorg\'izog. Esta é a sua chance de conhecer os outros dois.$B$BAntes de os matarmos, claro.', '', '', '', '', '', '', 'Coronel Troteman', '', '', '', 0),
(28327, 'ptBR', 'Carregado e engatilhado', 'Fale com o Coronel Troteman na Vigia de Morgan, que fica nas Estepes Ardentes.', '$n, responda. Está me ouvindo?$B$BA batalha já vai começar. Espero que você tenha entregado todos aqueles pacotes.$B$BPreciso de você aqui na Vigia de Morgan. AGORA.', '', '', '', '', '', '', 'Coronel Troteman', '', '', '', 0),
(28328, 'ptBR', 'Intriga crepuscular', 'Use a Tocha Brilhante para destruir 8 cópias do "A Doutrina do Crepúsculo", no Domicílio do Abismo Rocha Negra.', 'A força do Martelo do Crepúsculo se estende até os locais mais distantes. Eles procuram incessantemente aliados que queiram se juntar à batalha contra os nossos exércitos. Os últimos a serem recrutados foram os anões Ferro Negro do Abismo Rocha Negra.$B$BMoira não consegue manter controlar os Ferro Negro, e um número cada vez maior deles se rebela contra a causa dela. Precisamos acabar com esse recrutamento.$B$BQuero que você vá até o Domicílio do Abismo Rocha Negra e use esta tocha para queimar os livros que o Martelo do Crepúsculo está distribuindo por lá.', '', 'Cópias de "A Doutrina do Crepúsculo" queimadas', '', '', '', '', '', '', '', 'Fale novamente com a Alta-sacerdotisa Laurena na Catedral da Luz, em Ventobravo.', 0),
(28329, 'ptBR', 'Borbulhas de rancor', 'Mate 5 Pragalodos Zangados.', 'Esses pragalodos parecem estar mesmo com raiva. Eles têm até o que parece ser um rosto humano enfurecido em seus ectoplasmas. Hinoto não vai gostar de saber que tem pragalodos descontentes trabalhando nas poças de muco.$B$BMate todos os pragalodos que vir e tente selar um poço de reprodução.', '', '', '', '', '', '', 'Pragalodo Zangado', '', '', 'Fale com Serguei Hinoto nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28330, 'ptBR', 'Rastro de sujeira', 'Mate Odo, o Cria-Lodo.', 'O rastro de sujeira e ódio leva à prefeitura arruinada. Na certa há um poço de reprodução dentro da estrutura. Embrenhe-se e enfrente os criadores de lodos raivosos que encontrar!$B$BSe for $gbem-sucedido:bem-sucedida;, Serguei Hinoto tomará conhecimento disso nas Ruínas da Costa Sul.', '', '', '', '', '', '', 'Odo', '', '', 'Fale com Serguei Hinoto nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28331, 'ptBR', 'O bastão dá...', 'Use o Bastão do Helcolar para revigorar 8 Patrulheiras Sombrias.', 'E pensar que eu, um mestre da necromancia, treinado pelo próprio Kel\'Thuzad, fui reduzido a nada mais do que um cadáver no túmulo. Ainda bem que meu astuto aprendiz, Trevando, se empenhou em formar um grupo de heróis para reaver isto aqui:$B$B<Helcolar saca seu bastão.>$B$BFoi através do poder do bastão que renasci. O bastão dá e o bastão tira!$B$BTome-o agora e use-o para aumentar os poderes dos patrulheiros sombrios que enfrentam os worgens ao norte. Revigore as energias deles com o bastão.', '', 'Patrulheiros Sombrios revigorados', '', '', '', '', '', '', '', 'Fale novamente com Helcolar nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28332, 'ptBR', 'Comando de Helcolar', 'Mate 15 Caçadores Dentessangue de Renegados.', 'Nossos patrulheiros sombrios procuram terroristas worgens nos campos. Esses worgens foram enviados por seus mestres perversos para nos caçar e matar. E, embora um patrulheiro seja um combatente formidável, os worgens geralmente atacam em bando e acabam vencendo.$B$BVasculhe os arredores das Ruínas da Costa Sul em busca de caçadores Dentessangue. Mate quantos você vir! Pelos Renegados e por Lordaeron!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Helcolar nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28333, 'ptBR', 'Hora de passar um óleo', 'Use o Gancho de Darla para coletar Latas de Óleo de Ferrárbol e use-as para lubrificar 7 Retalhadores Ferrárbol.', 'Três coisas saem da Clareira Ferrárbol: lenha, petróleo e trabalhadores exaustos. As duas primeiras são, basicamente, as causas da terceira, mas eu gosto de ser eficiente quando posso.$B$BEu botei os retalhadores para trabalhar o triplo sem pagar hora extra, e não tem espaço no cronograma para fazer manutenção.$B$BUse este gancho de escalada para apanhar algumas das latas de óleo extras que estão flutuando pelo acampamento e use-as para azeitar os retalhadores, tá bom?', '', 'Retalhador lubrificado', '', '', '', '', '', '', '', 'Fale novamente com Darla Amabroca na Clareira Ferrárbol, que fica na Selva Maleva.', 0),
(28334, 'ptBR', 'Passeando pelo bosque...', 'Use a Caixa de Super-sinalizadores de Darla para revelar 8 Predadores Galhaça e matá-los.', 'A operação foi bem discreta até agora, mas os worgens lá da Clareira da Galhaça cismaram com a gente. Eles andam tentando de tudo para nos deter.$B$BAlguns dos trabalhadores disseram ter visto worgens espreitando pela clareira. Pegue estes super-sinalizadores gigantes. Eles iluminam o bastante para mostrar qualquer coisa que chegue perto.$B$BUse os sinalizadores para procurar worgens escondidos e não deixe nenhum sair vivo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Darla Amabroca na Clareira Ferrárbol, que fica na Selva Maleva.', 0),
(28335, 'ptBR', 'Desliga isso! Desliga isso!', 'Desligue o Controle de Bombeamento Automático no fundo da Caverna Ferrárbol.', 'Foram aqueles worgens malditos! Eles passaram direto por mim e entraram na caverna.$B$BEles devem ter aprontado alguma com o controle de bombeamento automático! Se aquele troço ficar ligado por muito tempo, todos os canos vão explodir. Você acha que os vazamentos já estão ruins? Espera só pra ver como é que vai ficar!$B$BEscuta: se você conseguir chegar no controle de bombeamento automático, lá no fundo da caverna, dá pra desligar tudo e salvar todo mundo!', '', '', '', '', '', '', '', '', '', '', 0),
(28336, 'ptBR', 'Quem não tapa, leva tapa', 'Estapeie 7 Trabalhadores em Pânico para fazê-los tapar os poços de petróleo.', 'Ah não... de novo, não! O delegado está gritando lá fora, então isso quer dizer que temos um vazamento dos grandes! Foram aqueles worgens sujos de novo!$B$BEscuta, vai ser um caos completo lá fora. Goblins há noites sem dormir, correndo por todo o lado, gritando sem saber o que fazer. Preciso que você traga esses trabalhadores de volta à razão.$B$BUm belo tapa, bem na cara, deve resolver! E, assim que eles voltarem a si, quero todo mundo tapando aqueles poços!', '', 'Trabalhador em Pânico estapeado', '', '', '', '', '', '', '', 'Fale novamente com Darla Amabroca na Clareira Ferrárbol, que fica na Selva Maleva.', 0),
(28337, 'ptBR', 'Os retalhadores de Ferrárbol', 'Mate 9 Retalhadores de Ferrárbol.', 'Repulsivo, não é? Olhe para eles. Coisinhas patéticas, incapazes de trabalhar com seus próprios corpos.$B$BAndam por aí em seus imensos retalhadores metálicos, reduzindo a floresta a farpas. Aposto que eles pensam estar a salvo dentro dessas máquinas, todos quentinhos e aconchegados.$B$BMostre-lhes que estão errados. Corra em direção ao norte, cruzando o acampamento, e destrua tantos retalhadores quanto puder. Assim que você terminar o derramamento de sangue, vamos demolir este lugar de vez.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Alton Ordeiro na Caverna Ferrárbol, que fica na Selva Maleva.', 0),
(28338, 'ptBR', 'Lenha Morta do norte', 'Mate 15 Pelursos Lenha Morta de qualquer tipo na Aldeia Patavil.', 'Há uma aldeia de pelursos Lenha Morta a sudoeste daqui. A corrupção permeia aquele lugar, e quero acabar com isso antes que eles se tornem um problema.$B$BA tribo Lenha Morta é maligna, mas são os efeitos da mácula vil que poluem as suas mentes. Embora essa hostilidade não seja uma qualidade inata, eles não podem ser ajudados. Entristece-me termos que lutar contra nossos irmãos.$B$BPor favor, $n, peço que você execute o que precisa ser feito. Apenas poupe-me dos detalhes. Tais imagens problemáticas perturbam-me demasiadamente.', '', 'Pelursos Lenha Morta mortos', '', '', '', '', '', '', '', 'Fale novamente com Nafien, que está perto do Domínio dos Presamatos, na Selva Maleva.', 0),
(28339, 'ptBR', 'O petróleo é nosso!', 'Extraia 10 Bolas de Piche Cru das Lamas Oleosas.', 'Na última vez que tivemos um vazamento tão grave, até o petróleo tentou fugir da confusão!$B$BEu não sei por que isso acontece. Talvez seja por causa de toda essa meleca demoníaca daqui. Mas, quando temos um vazamento dos grandes, metade do petróleo se aglomera e tenta fugir!$B$BIsso é o nosso lucro indo pelo ralo! Vá atrás dessas bolhas e traga de volta o nosso doce e precioso petróleo!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Darla Amabroca na Clareira Ferrárbol, que fica na Selva Maleva.', 0),
(28340, 'ptBR', 'Um acordo bombástico', 'Recolha 8 Explosivos Ferrárbol da Caverna Ferrárbol.', 'Todos os meus trabalhadores foram expulsos da caverna por aquelas coisas com cara de esgoto! A Darla me enviou aqui para limpar a bagunça, mas você já deu uma olhada lá dentro? Eu é que não entro lá!$B$BTem uma tonelada de explosivos deixados pra trás e que não podem ficar espalhados por aí.$B$BEu proponho um acordo: você vai lá e recolhe os explosivos, e eu fico aqui e não sou assassinado pelos bichos do esgoto. E se você não morrer, eu te pago! Topa?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capataz Levitraz na Caverna Ferrárbol, que fica na Selva Maleva.', 0),
(28341, 'ptBR', 'Coletando corrupção', 'Extraia 8 Essências Entrópicas de Horrores Entrópicos no Vale das Escaras Pungentes.', 'Apesar de nós, druidas, virmos evitando os poderes demoníacos que infestam estas terras, teremos que confrontá-los em algum momento.$B$BO Vale das Escaras Pungentes, ao sul, ferve em corrupção. As energias de lá são caóticas a ponto de manifestarem-se como entidades violentas, pura magia vil feita matéria para aniquilar tudo que vive.$B$BVenho observando de perto essas feras caóticas e estudando a força que têm. Preciso me certificar de que continuam enfraquecendo-se com o passar do tempo. Traga-me as essências dessas forças, para que eu possa ter certeza de que estão diminuindo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Elessa Brisastral no Bosque Murmuréolo, que fica na Selva Maleva.', 0),
(28342, 'ptBR', 'Restos poluentes', 'Colete 9 pedaços de Destroços Infernais no Vale das Escaras Pungentes.', 'Os infernais que espreitam o Vale das Escaras Pungentes são formidáveis, mas não invencíveis. Logramos grandes êxitos na redução do contingente deles.$B$BDestruí-los é apenas parte da solução, contudo. Descobri que a pedra da qual os infernais são feitos ainda contém grandes quantidades de magia vil, mesmo após a morte deles.$B$BOs restos dos infernais eliminados agora infestam o Vale das Escaras Pungentes, contaminando novamente o solo com a corrupção que exalam. Se você puder coletá-los e trazê-los para mim, ficarei grata.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Elessa Brisastral no Bosque Murmuréolo, que fica na Selva Maleva.', 0),
(28343, 'ptBR', 'O Hálito de Cenarius', 'Recupere o Hálito de Cenarius do Piromante Sábia Semente no Abismo Rocha Negra e use-o para fechar 3 Portões Elementais.', '$n, recebemos informações de que um artefato Cenariano que havia sido perdido, o Hálito de Cenarius, caiu nas garras de um seguidor do Martelo do Crepúsculo, o piromante Sábia Semente. Ele levou este artefato para o Abismo Rocha Negra e está usando-o para abrir os portões elementais.$B$BPrecisamos impedir que ele evoque mais elementais para fortalecer o exército Ferro Negro. Recupere este artefato e use-o para fechar os portões que o Sábio Semente abriu.', '', 'Portões Elementais fechados', '', '', '', '', '', '', '', 'Fale novamente com Loganaar no Refúgio Noturno, que fica na Clareira da Lua.', 0),
(28344, 'ptBR', 'O que diabos é "sair na munheca"?', 'Encontre o Regicida Orkus nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 'Pouco antes de você vir, um orc chegou aqui encarapitado numa serpe gélida e exigiu que eu lhe dissesse onde "os novatos tavam de bobeira". Não compreendi bem aquele palavreado peculiar, de forma que disse a ele que cumprisse seu dever como membro da Horda e fosse ajudar a combater a ameaça dos worgens aqui na região. Ele resmungou algo sobre "sair na munheca" e seguiu para o sul na direção das docas.$B$BNão costumo me importar com orcs perdidos, mas meu interesse em dialetos rústicos me deixou genuinamente curioso em saber o que viria a ser "sair na munheca". Vá lá e descubra.', '', '', '', '', '', '', '', '', '', '', 0),
(28345, 'ptBR', '*Gurga* SOCORRO! *Gurga*', 'Ajude o Regicida Orkus a sair da água.', '*GURGA*$B$BSOCORRO!*OFEGO*$B$BORKUS ESTÁ SE AFOGANDO! SOCORRO, RECRUTADOR $n!$B$B*GLUB*$B$BO anão jogou Orkus na água! Não posso morrer!$B$B*GURGA*$B$BA vergonha seria grande demais.', 'Orkus retirado da água a salvo', '', '', '', '', 'Orkus retirado da água a salvo', '', '', '', 'Fale com o Regicida Orkus nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28346, 'ptBR', 'O solteiro', 'Discuta as perspectivas de casamento com Quincas Barbarruiva em Kirthaven, que fica no Planalto do Crepúsculo.', 'Precisamos fazer isto funcionar, $n. A resposta está no sangue! Laços de família mantiveram os clãs Martelo Feroz afastados uns dos outros. Precisaremos reatar esses laços. Vai ser duro de pelar, mas, com jeitinho, vamos conseguir.$B$BVou procurar Colin Trondamar e conversar com ele. Como você é $gtranquilo:tranquila;, deve falar com Quincas Barbarruiva. Ele é esperto o suficiente para entender um casamento político. Vá descobrir se ele tem alguém em mente!', '', '', '', '', '', '', '', '', '', '', 0),
(28347, 'ptBR', 'Duas Tendas MISSÃO DE RASTREIO', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28348, 'ptBR', 'Reunião dos Lançatroz', 'Descubra como foi a Reunião dos Lançatroz com Orkus.', 'Vim atrás desse necromante decrépito, Helcolar, pra encontrar uma pista sobre a movimentação da Aliança em Eira dos Montes.$B$BHelcolar me mandou achar e matar worgens. Isso não seria problema para Orkus, mas eu tinha acabado de comer várias Costeletas Sinistronas de Quiméroco do Funesto, aí me deu um revestrés no baixo ventre. Foi quando a confusão começou, e foi assim que acabei na água.$B$BEscute o que Orkus diz, $n.', 'Descubra como foi a reunião dos Lançatroz.', '', '', '', '', 'Descubra como foi a reunião dos Lançatroz.', '', '', '', 'Fale com o Regicida Orkus nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28349, 'ptBR', 'A Carlota do Marketing', 'Fale com Carlota Tomanota, na Sede da CCJ, em Kezan.', '$gChefosinho:Chefosinha;, enquanto você estava lá embaixo nas minas, a Carlota Tomanota, do Marketing, esteve procurando por você. Alguma coisa sobre seu carango novo?$B$BEla está do lado de fora do prédio à esquerda.', '', '', '', '', '', '', '', '', '', '', 0),
(28350, 'ptBR', 'Mestre armadilheiro', 'Sullah quer que você colete 5 Retalhos de Carne da fauna de Uldum.', 'Tem uma coisa a meu respeito que você talvez não saiba, $n...$b$bEu venho de uma longa linhagem de armadilheiros. O meu pai me ensinou, assim como o meu avô ensinou a ele, a dominar a arte de prender criaturas em armadilhas da forma mais misericordiosa possível.$b$bQualquer mestre armadilheiro dirá que o ingrediente mais importante de uma armadilha eficaz é a isca.$b$bEntão, vamos começar por aí.$b$bEncha este balde com pedaços de carne de criaturas selvagens de Uldum.', '', '', '', '', '', '', '', '', '', 'Fale com o Sullah no Espetáculo de Sullah.', 0),
(28351, 'ptBR', 'Potencial ilimitado', 'Use a Jaula Reforçada para capturar 5 Pigmeus Saltitantes.', 'Os pigmeus da areia são considerados por alguns como uma praga, ou pior ainda, como meros demônios vis.$b$bMas eu digo que eles são apenas mal compreendidos!$b$bCom a orientação e o cuidado necessários, essas criaturinhas podem se tornar uma dádiva da natureza.$b$bEu quero que você capture alguns pigmeus para serem trabalhados por mim. Use estas gaiolas aqui.$b$bVocê vai ter que dar umas boas bordoadas neles antes de prendê-los, mas é pro bem deles.$b$bVocê vai ver!$B$BOs pigmeus estão a sul daqui.', '', 'Pigmeus das Areias capturados', '', '', '', '', '', '', '', 'Fale com Sullah no Espetáculo de Sullah, em Uldum.', 0),
(28352, 'ptBR', 'Camelos de reboque', 'Use o Arnês de Sullah para domar 3 Camelos.', 'Saudações, amig$go:a;!$b$bVocê é sempre muito bem-vind$go:a; na minha humilde tenda.$b$bEm busca de algo para fazer? O Sullah tem a solução!$b$bÉ sempre bem ter camelos à mão, mas, para uma performance com a do meu espetáculo, eles são absolutamente necessários!$b$bLeve este arnês e o use para dominar um camelo passante.$b$bAntes, você terá que, bem, amaciar ele um pouco... se você entende o que estou dizendo.$B$BVocê encontrará um deserto cheio deles ao sul.', '', 'Camelos Selvagens capturados', '', '', '', '', '', '', '', 'Fale com o Sullah no Espetáculo de Sullah.', 0),
(28353, 'ptBR', 'O Jones chamou você', 'Fale com Harrison Jones no Oásis de Vir\'sar.', 'Veja bem, $n, acho melhor você ir falar com o Jones assim que tiver um tempinho.$b$bÉ bem provável que ele tenha coisas mais importantes a tratar com você do que eu.', '', '', '', '', '', '', '', '', '', '', 0),
(28354, 'ptBR', 'Kasha voará novamente', 'Colha 8 Cogumelos Fuçalama.', 'Kasha voará novamente, $n. Sem isso, não teremos nossa vingança! Infelizmente Orkus deve permanecer aqui com ela. Você precisa nos ajudar. Eu imploro!$B$BEscute com atenção, $grecrutador:recrutadora;. Quando cheguei aqui, passei muito tempo sobrevoando a região para reconhecer o terreno. Há uma fazenda a leste daqui, há muito abandonada, que foi dominada por gnolls. Nesta fazenda cresce um tipo especial de cogumelo conhecido como fuçalama. Vá até lá e colha fuçalamas para Kasha. Volte quando sua bolsa estiver cheia deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Regicida Orkus nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28355, 'ptBR', 'Criaturinhas terríveis', 'Mate 10 Gnolls no Sítio de Nethander.', 'Gnolls! Estas criaturinhas terríveis são uma peste para qualquer terra - e isso não é pouca coisa se considerarmos que Eira dos Montes é território dos Renegados. Mate quantos gnolls puder no Sítio de Nethander. Pelo bem do mundo!', '', 'Gnolls ou Xamãs Fuçalama mortos', '', '', '', '', '', '', '', '', 0),
(28356, 'ptBR', 'A melhor defesa é o ataque', 'Mate 15 Nagas na Praia Oriental.', 'Estes documentos apresentam o que supostamente parecem ser planos de um ataque iminente à Costa Sul. As nagas da Praia Oriental planejam tomar a cidade agora que a Aliança foi expulsa.$B$BA não ser que você nos ajude!$B$BMate todas as nagas da Praia Oriental e apresente-se a Helcolar, nas Ruínas da Costa Sul, com o plano de ataque de Espinhadaga.', '', 'Nagas Espinhadaga mortas', '', '', '', '', '', '', '', 'Fale com Helcolar nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28357, 'ptBR', 'Leve isso à árvore', 'Mate 8 Defensores de Galhaça.', 'Esses vira-latas sarnentos acham que podem invadir meu território e sair numa boa? Vou dar uma lição neles...$B$BE, com isso, eu quis dizer, é claro, que VOCÊ vai dar uma lição neles. Você e o pequeno exército de mercenários goblins armados com machados que eu enviei pra Clareira da Galhaça.$B$BA essa altura, aquilo lá já deve estar infestado de worgens. Exatamente onde a gente quer que eles estejam. Vá para o sudeste, junte-se ao resto de nossas tropas e vamos fazer uns cachorros quentes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Darla Amabroca na Clareira Ferrárbol, que fica na Selva Maleva.', 0),
(28358, 'ptBR', 'Caçando os condenados', 'Mate 6 Sentinelas Infernais.', 'Os primeiros demônios que pisaram nesta floresta foram os infernais. Há muito, esses poderosos seres de pedra e fogo demoníaco caíram do céu com o intuito de tomar esta terra para a Legião Ardente.$B$BAs crateras chamuscadas do Vale das Escaras Pungentes, a sul, foram os pontos de aterrissagem desses demônios, e muitos ainda perambulam por lá. Eles são adversários ferozes, e matá-los é tanto um desafio válido quanto uma causa nobre.$B$BOfereço uma recompensa àqueles que se juntarem à causa. Volte aqui depois.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rurak Presagreste no Bosque Murmuréolo, que fica na Selva Maleva.', 0),
(28359, 'ptBR', 'O âmago de Kroshius', 'Obtenha o Âmago Infernal de Kroshius.', 'O mais temível demônio do Vale das Escaras Pungentes é conhecido como Kroshius. Apesar de muitos o terem caçado ao longo dos anos, os ataques apenas o fortaleceram.$B$BUm após o outro, bruxos vieram a esta floresta e reanimaram Kroshius. E hoje ele espreita a sudeste, cercado por fogo demoníaco, aguardando qualquer um que tente reclamar o poder dele.$B$BNão permitirei que este ciclo infernal continue! Mate Kroshius e traga-me seu âmago infernal.', '', '', '', '', '', '', 'Kroshius', '', '', 'Fale novamente com Rurak Presagreste no Bosque Murmuréolo, que fica na Selva Maleva.', 0),
(28360, 'ptBR', 'Dessa para a melhor', 'Mate 8 Ginetes Podrevis.', 'Eu gostaria muito de salvar todas as criaturas da floresta, mas, como você deve ter notado, algumas já estão completamente perdidas.$B$BInicialmente, quando fundamos o Bosque Murmuréolo, a floresta ao sul era repleta de lindos ginetes, criaturas majestosas e gentis. A corrupção daqui, apesar de não tê-los tornado violentos, os consumiu até quase nada restar.$B$BMesmo que fossem purificados, eles sentiriam apenas dor e sofrimento. Por favor, $c, ajude-me a abatê-los.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Macia Bosquepuro no Bosque Murmuréolo, que fica na Selva Maleva.', 0),
(28361, 'ptBR', 'Banho no esquilo', 'Esfregue 6 Esquilos Maculados.', 'Em geral, os animais maiores já estão corrompidos demais para serem salvos. Mas você se surpreenderia ao ver como os pequenos são resistentes.$B$BVeja os esquilos, por exemplo. Depois de mergulharem em águas contaminadas, eles podem espalhar a doença por grandes distâncias. Mas a afecção é lenta demais para afetá-los. Na verdade, um simples banho resultará em um esquilo limpo e uma floresta mais segura!$B$BPegue esta garrafa de preparado para limpeza. Agarre e esfregue todos os esquilos que você encontrar na floresta ao sul... Eles vão agradecer!', '', 'Esquilos Maculados esfregados', '', '', '', '', '', '', '', 'Fale novamente com Macia Bosquepuro no Bosque Murmuréolo, que fica na Selva Maleva.', 0),
(28362, 'ptBR', 'Xuvisko burro!', 'Encontre o Xuvisko na Aldeia Patavil.', 'O Xuvisko é muito burro! Eu falei pra ele não ir!$B$BO Xuvisko queria roubar mais mel da Aldeia Patavil... Sabe, lá pra onde o sol se põe? Dá para ver lá do penhasco...$B$BEnfim... Eu disse pra ele que era uma ideia idiota e ele foi mesmo assim e os Lenha Morta pegaram ele e... e...$B$BSniff...$B$BNão sei o que eles vão fazer com ele! Por favor, acha o meu amigo, $gseu:dona; $r! Mesmo que ele seja um bobo! Eu não quero que o Xuvisko vire comida de Patavil!', '', '', '', '', '', '', '', '', '', '', 0),
(28363, 'ptBR', 'Sacudiu a colmeia', 'Fale com o Sullah no Espetáculo de Sullah.', 'Uau!$b$bParece que você conseguiu mesmo chamar a atenção deles, $n. Nunca vamos entrar lá com eles alertas desse jeito.$b$bDeve haver um jeito...$b$bÉ só uma questão de tempo antes que os homens do Schnottz ativem o obelisco, e tenho que estudar os pergaminhos que você encontrou. Preciso que você resolva essa sem mim.$b$bO Sullah tem contatos por estas partes. Talvez ele tenha uma solução para nos colocar lá dentro.', '', '', '', '', '', '', '', '', '', '', 0),
(28364, 'ptBR', 'A chave do chefe', 'Recupere a Chave do Xuvisko do Chefe Gorjassangue.', 'Sniff... Desculpa! Não era pra eles me pegarem! Eles me agarraram e me prenderam com corrente e me largaram aqui! Eu não consigo me mexer e a minha perna tá dormente e eu tô com fome!$B$BA chave tá com o chefe... Falaram que o nome dele é Gorjassangue. Ele tá lá na ponta norte da aldeia.$B$BMas corre! Por favor! Não me deixa aqui sozinho!', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Xuvisko na Aldeia Patavil, que fica na Selva Maleva.', 0),
(28366, 'ptBR', 'Desarmando ursos', 'Colete 7 Armas de Lenha Morta da Aldeia Patavil.', 'Quero fazer tudo o que puder para proteger o nosso povo sem precisar matar até o último Lenha Morta. Nós já fizemos alguns avanços nesse sentido e eu lhe peço que faça o mesmo, se você quiser provar seu valor à tribo Presamatos.$B$BProcure as pilhas de armas guardadas na Aldeia Patavil, a sudoeste daqui. Pegue todas que encontrar. Se desarmarmos a tribo Lenha Morta, talvez seja possível impedir um derramamento de sangue depois.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nafien no Domínio dos Presamatos, que fica na Selva Maleva.', 0),
(28367, 'ptBR', 'Capa dos criadores', 'Sabote 7 Barris de Pólvora do Schnottz.', 'É muito bom ter amigos, $c! Apesar de a gentileza ser a própria recompensa, também existem benefícios tangíveis!$b$bRecentemente, alguns amigos meus interceptaram uma remessa do saque de Schnottz e encontraram algo que deve nos atender bem.$b$bÉ um artefato de tecnologia titânica que torna o usuário quase invisível. Se você o usar no campo inimigo, talvez você seja capaz de reconectar os explosivos deles e bagunçar a operação.$b$bCada carga tem uma duração limitada, então não se afaste muito da segurança!', '', 'Barris de Pólvora sabotados', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Oásis de Vir\'sar.', 0),
(28368, 'ptBR', 'Essa vai ser fogo!', 'Mate Grolvitar, o Sempre-em-chamas.', 'Poxa vida, $Gparceiro:parceira;! Você desligou aquelas válvulas pra valer.$B$BMas rolou uma explosão crítica no nosso maldito regulador de queima central! A Dona Darla enviou todos os trabalhadores que tinha para desligar o troço, mas aquelas chamas têm vontade própria!$B$BLiteralmente! Elas tão vindo pra cima e pegando todo mundo que chega perto! Então, a Darla disse que, se você tiver forças pra sair dessa caverna e bater naquele elemental, ela tem um prêmio maneiro te esperando!', '', '', '', '', '', '', 'Grolvitar, o Sempre-em-chamas', '', '', 'Fale novamente com Darla Amabroca na Clareira Ferrárbol, que fica na Selva Maleva.', 0),
(28369, 'ptBR', 'Minha irmã Fanny', 'Fale com Fanny Trondamar em Trondamar, que fica no Planalto do Crepúsculo.', 'Antes que você vá, dê uma passada na estalagem aqui atrás. Minha irmã Fanny está lá.$B$BOs refugiados estão se espalhando por Trondamar vindos de todos os assentamentos Martelo Feroz incendiados ao nosso redor, e encarreguei Fanny de cuidar deles. Ela é durona, mas pode precisar de sua ajuda.', '', '', '', '', '', '', '', '', '', '', 0),
(28370, 'ptBR', 'Afano fátuo', 'Use o Ímã de Fogo-fátuo da Darla para coletar 5 Fogos-fátuos de Galhaça.', 'Dá pra acreditar que esses worgens têm fogos-fátuos? Eles aprenderam toda aquela baboseira druídica com os elfos noturnos e, agora, arranjaram uns fogos-fátuos também – que dão a eles todo o material de construção de que precisam sem que tenham que ferir uma de suas preciosas árvores sequer.$B$BSe a gente tivesse essas coisas, daria para extrair madeira extra de todas as árvores do nosso território. Recursos gratuitos, lucros gratuitos! É por isso que eu venho trabalhando neste dispositivo de contenção.$B$BVá pra Clareira da Galhaça e use isto para roubar alguns fogos-fátuos. É só apontar e apertar o botão.', '', 'Fogo-fátuo de Galhaça capturado', '', '', '', '', '', '', '', 'Fale novamente com Darla Amabroca na Clareira Ferrárbol, que fica na Selva Maleva.', 0),
(28371, 'ptBR', '[DND] ORKUS QUEST FLAG [DO NOT LOCALIZE]', 'Colha 8 Floradas Fuçalama.', 'Kasha voará novamente, $n. Sem isso não teremos nossa vingança! Infelizmente, Orkus deve permanecer aqui com ela. Você precisa nos ajudar. Eu imploro!$B$BEscute com atenção, recrutador. Quando cheguei aqui, passei dias sobrevoando para reconhecer o terreno. Há uma fazenda a leste daqui, há muito abandonada, que foi dominada por gnolls. Nesta fazenda cresce um tipo especial de cogumelo conhecido como fuçalama. Vá até lá e colha fuçalamas para Kasha. Volte quando sua bolsa estiver cheia deles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Regicida Orkus nas Ruínas da Costa Sul, no Contraforte de Eira dos Montes.', 0),
(28372, 'ptBR', 'De volta ao batente', 'Pegue um voo para a Clareira Ferrárbol e fale com Darla Amabroca.', 'Essa coisa de amigos felizes e contentes é uma beleza, né não? Um monte de gente trabalhando junta para salvar a floresta... Mas o que vai acontecer com a mata quando ela estiver curada? Vai simplesmente ficar aí, largada?$B$BA gente precisa dessa lenha. A Horda precisa. Recebi ordens para enviar todos os soldados leais da Horda – e eu sei que você é leal – para a Clareira Ferrárbol, a norte daqui.$B$BEu já providenciei, com o mestre de hipogrifos, uma viagem grátis para você chegar lá voando. Fale com a Darla Amabroca ao aterrissar na cidade.', '', '', '', '', '', '', '', '', '', '', 0),
(28373, 'ptBR', 'Domínio dos Presamatos', 'Fale com Nafien no Domínio dos Presamatos, que fica na Selva Maleva. O Domínio dos Presamatos fica a leste, depois da Aldeia Patavil.', 'Tá bom, eu sei que isso é arriscado, mas perguntar não ofende.$B$BEnquanto eu lido com as consequências de toda aquela loucura ridícula que aconteceu aqui, preciso que você fale com alguns ursos. Os pelursos Presamatos controlam a floresta a nordeste e não gostam muito de nós.$B$BSó quero que alguém convença eles de que a Horda não é tão ruim assim. Vá para o nordeste pela estrada que leva ao Domínio dos Presamatos – não entre na Aldeia Patavil – e pergunte ao pelurso do lado de fora se eles precisam de algum favor.', '', '', '', '', '', '', '', '', '', '', 0),
(28374, 'ptBR', 'Arrancando as ervas daninhas', 'Puxe 7 Açoitadeiras do Bosque Murmuréolo para verificar se estão contaminadas.', 'Em um lugar como este, mesmo algo simples como cultivar flores ou arrancar ervas daninhas pode requerer um esforço heroico.$B$BAs orquídeas açoitadeiras que crescem por todo lado no bosque são um sinal de cura. Mas elas não são perfeitas: algumas sucumbem à corrupção demoníaca de vez em quando.$B$BEu descobri que a melhor forma de verificar a natureza delas é simplesmente puxá-las do chão. Se forem normais, perambularão um pouco pelo entorno e fixarão novamente as raízes. Se não forem... Bem, é melhor que você esteja pront$Go:a; para lutar!', '', 'Açoitadeiras do Bosque Murmuréolo verificadas', '', '', '', '', '', '', '', 'Fale novamente com Macia Bosquepuro no Bosque Murmuréolo, que fica na Selva Maleva.', 0),
(28375, 'ptBR', 'Estrada para Purgação', 'Acompanhe o Regicida Orkus até a Ilha da Purgação.', 'É chegada a hora da vingança, $n. Kasha pode voar novamente, graças a você. Ela nos levará à Ilha da Purgação para nosso confronto com o general anão Vanndar Lançatroz e sua capitão Balinda Larpétreo. AMBOS pagarão pelo que fizeram.$B$BEstá $gpreparado:preparada;? Orkus não pode fazê-lo sozinho.', 'Estrada para Purgação tomada', '', '', '', '', 'Estrada para Purgação tomada', '', '', '', 'Fale com o Regicida Orkus na Ilha da Purgação, no Contraforte de Eira dos Montes.', 0),
(28376, 'ptBR', 'A cabeça de Myzerian', 'Leve a Cabeça de Myzerian para o Sullah no Espetáculo de Sullah.', 'A cabeça de um dos mais formidáveis dragões negros do Asa da Morte está agora em sua posse.$b$bMuitos em Azeroth pagariam caro por tal artefato, mas algo diz a você que o lugar dela é em um museu, para que todos a vejam e se lembrem.$b$bHarrison Jones deve ter os contatos adequados.$b$bO Sullah, certamente, ficará feliz em entregá-la a ele.', '', '', '', '', '', '', '', '', '', '', 0),
(28377, 'ptBR', 'Resgate na Ravina do Tripasseca', 'Encontre Colin Trondamar na Ravina do Tripasseca, que fica no Planalto do Crepúsculo.', 'E por falar em gente sumida... A Fanny partiu e foi capturada por ogros!$B$BNão confio que os Trondamar sejam capazes de montar uma equipe de resgate. Vou convocar meus cavalga-grifos para fazerem a busca aérea.$B$BTenho certeza de que eles farão bom proveito de uma ajudinha extra de $gum:uma; $c. Pegue seu equipamento e procure Colin Trondamar no acampamento Tripasseca a sudoeste daqui, abaixo do despenhadeiro. Vá depressa!', '', '', '', '', '', '', '', '', '', '', 0),
(28378, 'ptBR', 'O resgate de Fanny', 'Encontre e resgate Fanny Trondamar.', 'Começamos olhando este acampamento de cabo a rabo, $n, mas não há nenhum sinal da Fanny. Quem sabe tu não encontra a guria?$B$BNão verificamos a caverna atrás de mim, a noroeste... tu pode procurar ela lá?', '', 'Fanny Trondamar resgatada', '', '', '', '', '', '', '', 'Fale com Colin Trondamar na Ravina do Tripasseca, que fica no Planalto do Crepúsculo.', 0),
(28379, 'ptBR', 'Ogrocídio', 'Mate 10 ogros Tripasseca (tanto Espancadores Tripasseca quanto Arremessadores Tripasseca).', 'Ogros Tripasseca! Eu diria que eles são tão burros quanto um saco cheio de martelos e, mesmo assim, respeito mais meus martelos do que eles.$B$BCombatemos os ataques deles por anos, mas se tiverem colhões para roubar um de nós, vamos ter que dar uma lição pra eles.$B$BAjude a gente a espancar uns ogros por aí! Mate alguns dos espancadores ou arremessadores deles, tanto aqui fora ou – melhor ainda – dentro da caverna. Assim eles vão saber com quem estão se metendo!', '', 'Ogro Tripasseca morto', '', '', '', '', '', '', '', 'Fale novamente com Colin Trondamar na Ravina do Tripasseca, que fica no Planalto do Crepúsculo.', 0),
(28380, 'ptBR', 'Levitraz em perigo', 'Fale com o Capataz Levitraz na Caverna Ferrárbol.', 'O que diabos tá acontecendo aqui? O capataz Levitraz já deveria ter desligado as válvulas a essa altura.$B$BPodemos passar o dia inteiro tapando esses vazamentos e a válvula central pode estar desligada, mas estamos apenas adiando uma explosão enorme.$B$BEscute, se você valoriza seu dinheiro, sua vida, ou qualquer combinação dos dois, é melhor ir para a Caverna Ferrárbol, a sul daqui, e ver se consegue encontrar o capataz Levitraz.', '', '', '', '', '', '', '', '', '', '', 0),
(28381, 'ptBR', 'A grande mãe', 'Voe até a Clareira da Galhaça e fale com a Grande Mãe Ulrica.', 'Ao norte, não mais distante do que pode voar um corvo, goblins estão devastando a floresta, derrubando-a para abastecer a máquina de guerra da Horda e rechear seus próprios bolsos. Este goblin profere palavras agradáveis e mentiras engenhosas aos druidas, que acabam por fazer vista grossa, por receio de perturbar a tênue neutralidade daqui.$B$BOs worgens da Clareira da Galhaça estão fartos disso. Junte-se a nós! O mestre de hipogrifos levará você direto para o nosso lar. A Grande Mãe Ulrica receberá qualquer $r $Gdisposto:disposta; a lutar.', '', '', '', '', '', '', '', '', '', '', 0),
(28382, 'ptBR', 'Inimigos caras de pau', 'Mate 8 Retalhadores de Ferrárbol.', 'Os goblins já estão chegando aqui!$B$BTentamos tudo que pudemos para afastar os goblins da Clareira Ferrárbol sem recorrer à violência. Ficamos perplexos com a forma como se fizeram de surdos e, agora, eles preferem morrer por ganância a poupar a floresta.$B$BLogo conhecerão toda a nossa fúria! A batalha arde logo além do portão norte. Junte-se, gloriosamente, à nossa alcateia e mate qualquer goblin que se atrever a cruzar nosso caminho!', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Grande Mãe Ulrica na Clareira da Galhaça, que fica na Selva Maleva.', 0),
(28383, 'ptBR', 'Fogos-fátuos da floresta', 'Use o Graveto de Velozvento para atrair 5 Fogos-fátuos de Galhaça.', 'Há muito que aqui labuto com a Grande Mãe para espalharmos os ensinamentos de Cenarius e os caminhos da natureza. Eu conquistei a confiança dela e, em troca, foi-me permitido apresentar os espíritos da floresta aos seus alunos. A companhia de fogos-fátuos é uma grande honra e uma bênção útil.$B$BContudo, agora, os goblins estão nos atacando com o intuito de roubar os fogos-fátuos para usos nefastos. Por favor, impeça essa blasfêmia!$B$BChame os fogos-fátuos da floresta a oeste de volta para cá com este graveto abençoado e mantenha-os seguros!', '', 'Fogos-fátuos da Clareira da Galhaça capturados', '', '', '', '', '', '', '', 'Fale novamente com Lyros Velozvento na Clareira Ferrárbol, que fica na Selva Maleva.', 0),
(28384, 'ptBR', 'Clareira adentro', 'Fale com Alton Ordeiro perto da Caverna Ferrárbol.', 'A Clareira Ferrárbol deverá ser arrasada. Não podemos ter misericórdia se quisermos impedir que os goblins espalhem destruição por toda a floresta.$B$BAlton Ordeiro, meu mais confiável protetor, já levou boa parte da alcateia para a linha inimiga a fim de atacar quando eles estiverem distraídos. Procure-o a oeste daqui, perto da Caverna Ferrárbol.', '', '', '', '', '', '', '', '', '', '', 0),
(28385, 'ptBR', 'Petróleo e ironia', 'Sabote a Bomba de Controle Mestre no fundo da Caverna Ferrárbol.', 'Planejo usar a cobiça e a poluição dos goblins contra eles. Para isso teremos que castigar ainda mais as terras que eles já devastaram, mas valerá a pena. Isso os impedirá de se expandir ainda mais.$B$BNas profundezas da Caverna Ferrárbol, logo abaixo de nós, há vários tubos para bombear petróleo. Os canos são conectados a uma bomba de controle mestre que fica no fundo da caverna.$B$BEntre lá e sabote a bomba. A confusão que isso vai gerar nos dará a chance de realizarmos nosso derradeiro ataque.', '', '', '', '', '', '', '', '', '', '', 0),
(28386, 'ptBR', 'Bombas emprestadas', 'Recolha 8 Explosivos Ferrárbol da Caverna Ferrárbol.', 'Os trabalhadores na Caverna Ferrárbol já foram expulsos. Alguma coisa tomou a caverna.$B$BSorte nossa. Eu vi que alguns deles deixaram cair explosivos durante a fuga... Explosivos dos quais precisaremos para a parte seguinte de nosso plano.$B$BEntre na caverna e colete todos os explosivos abandonados que encontrar. Termine esta tarefa e acabe com a bomba para darmos início ao ataque final.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Alton Ordeiro na Caverna Ferrárbol, que fica na Selva Maleva.', 0),
(28387, 'ptBR', 'Combustão', 'Use os Explosivos Ferrárbol Roubados para atear fogo a 7 Gêiseres Petrolíferos na Clareira Ferrárbol.', 'A sabotagem da bomba fez com que canos quebrassem por todo o acampamento. Os goblins já estão apavorados com os gêiseres, e a situação vai ficar pior ainda.$B$BPegue os explosivos coletados e use-os para atear fogo aos gêiseres. Temos que causar o maior estrago possível ao acampamento e impedir que usem o petróleo para abastecer os retalhadores... ou pior, as belonaves da Horda.', '', 'Fonte de Óleo em chamas', '', '', '', '', '', '', '', 'Fale novamente com Alton Ordeiro na Caverna Ferrárbol, que fica na Selva Maleva.', 0),
(28388, 'ptBR', 'Pagamento fatal', 'Mate 7 Trabalhadores em Pânico.', 'Covardes desprezíveis... Olhe só para eles fugindo em pânico!$B$BNão se deixe enganar, $n. Assim que se recuperarem, esses goblins não vão descansar enquanto não derrubarem a floresta toda e enviarem cada pedaço para o esforço de guerra da Horda.$B$BNão permita isso. Mate impiedosamente os trabalhadores por toda a Clareira Ferrárbol... Ensine a eles que a ganância tem um preço!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Alton Ordeiro na Caverna Ferrárbol, que fica na Selva Maleva.', 0),
(28389, 'ptBR', 'Apresente-se à Grande Mãe', 'Fale com a Grande Mãe Ulrica na Clareira da Galhaça.', 'Com os goblins dispersados e seus equipamentos destruídos, eles ou entenderão a mensagem e irão embora, ou serão presas fáceis caso decidam ficar. É nossa a vitória.$B$BVocê lutou tão ferozmente quanto qualquer membro da alcateia, $n. Volte à Grande Mãe e conte-lhe do nosso sucesso. Eu continuarei em guarda.', '', '', '', '', '', '', '', '', '', '', 0),
(28390, 'ptBR', 'Glop, filho de Glop', 'Fale com a Reparadora da Terra Norsala. Em seguida, mate o Fungimante Glop.', 'Glop teve um filho. Em sua arrogância, deu ao rebento o nome de Glop. E assim prosseguiu a linhagem de fungimantes.$B$BPreciso que você mate o novo fungimante. A sua aliada xamã já voltou e espera por você na caverna dele, que fica a sudoeste do Posto Verlok.', '', '', '', '', '', '', 'Fungimante Glop', '', '', 'Fale novamente com Ruberick no Trono de Therazane, no Geodomo.', 0),
(28391, 'ptBR', 'Lugar de dragonesa é na...', 'Derrote Aeosera.', 'Aeosera é impaciente e teimosa. Ela zomba da nossa liderança. Temos que lembrá-la de qual é o lugar dela.$B$BAinda tenho a marreta que você trouxe para mim. Volte até a fronteira oeste do Alcândor Pálido e golpeie o cristal ressoante.$B$BEu encontrarei você lá para ajudar no que for preciso. Bote Aeosera no devido lugar, $c.', '', 'Cristal Ressoante Pálido atingido', 'Aeosera derrotada', '', '', '', 'Aeosera', '', '', 'Fale novamente com Terrath, o Estável, no Trono de Therazane, que fica no Geodomo.', 0),
(28392, 'ptBR', 'A tribo dos Presamatos', 'Fale com Nafien na entrada do Domínio dos Presamatos.', 'Os pelursos Presamatos são a última tribo de pelursos íntegros conhecida. Eles estão aninhados à margem destas terras, defendendo ferozmente o lar, o Domínio dos Presamatos.$B$BApesar de serem criaturas orgulhosas, eles estão precisando de auxílio. Caso você queira ajudar, siga a estrada para norte daqui e procure-os na entrada do Domínio dos Presamatos.', '', '', '', '', '', '', '', '', '', '', 0),
(28393, 'ptBR', 'Uma aliança perigosa', 'Mate 6 Flamiguardas Destruidores e pegue o Plano de Ataque do General do General Forjaversa na Guarnição Oeste, no Abismo Rocha Negra.', 'O último relatório da AVIN sobre as atividades do Martelo do Crepúsculo e do Ferro Negro me preocupa, $n. Há evidências de que eles estão se preparando para um ataque em conjunto, partindo da Montanha Rocha Negra. Seremos forçados a recuar caso isso aconteça, mas se formos rápidos o bastante, talvez possamos enfraquecê-los.$B$BVocê precisa entrar no Abismo Rocha Negra e conseguir os planos de ataque do Martelo do Crepúsculo, que está com o General Forjaversa, na Guarnição Oeste. Não pense duas vezes em acabar com os elementais que se juntaram às forças do Crepúsculo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Abner Germano no Centro de Comando ao sul da Cidade Velha, em Ventobravo.', 0),
(28394, 'ptBR', 'As criações do Lorde Golem', 'Consiga 5 Módulos Elementais dos golens da Fábrica, no Abismo Rocha Negra, e roube o Diagrama do Golem Elemental.', 'As últimas informações que a AVIN obteve sobre o Abismo Rocha Negra são preocupantes, $n. Parece que o Martelo do Crepúsculo se juntou ao engenheiro Ferro Negro Argelmach para criar golens movidos à energia de elementais. Não podemos deixar que usem essa nova arma contra nossas forças.$B$BVocê precisa impedi-los, $n. Encontre a Fábrica no Abismo Rocha Negra, roube o diagrama que eles estão usando para criar os golens e consiga os módulos elementais usados para energizá-los.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Wulf Hansreim no Centro de Comando ao sul do distrito da Cidade Velha, em Ventobravo.', 0),
(28395, 'ptBR', 'Penas para Nafien', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Nafien na Selva Maleva.', 0),
(28396, 'ptBR', 'Penas para Grazle', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Grazle na Selva Maleva.', 0),
(28397, 'ptBR', 'Eles não perdem por esperar...', 'Mate 8 Anões Lançatroz e 8 Sentinelas Dentessangue na Ilha da Purgação.', 'Eles cometeram um erro não me matando quando tiveram a chance. Talvez achassem que Orkus se afogaria. HAHA! Agora eles pagarão pelo descuido.$B$BVocê e eu devastaremos essa ilha, $n. Eles não perdem por esperar! Quando os soldados estiverem todos mortos, enfrentaremos os líderes. Procure os planos de ataque. Se colocarmos as mãos nos planos deles, poderemos interromper a invasão!$B$BVamos lá, $n!', '', 'Anões Lançatroz mortos', '', '', '', '', '', '', '', 'Fale com o Regicida Orkus na Ilha da Purgação, no Contraforte de Eira dos Montes.', 0),
(28398, 'ptBR', 'O grimório do piromante', 'Mate 6 Emissários do Crepúsculo e roube o Grimório de Sábia Semente do Piromante Sábia Semente no Santuário de Thaurissan, no Abismo Rocha Negra.', 'O poder dos Ferro Negro e os aliados deles, os membros do Martelo do Crepúsculo, está crescendo na Montanha Rocha Negra. O famoso piromante Sábia Semente é de grande importância para a organização das forças do Martelo do Crepúsculo que lá atuam. Se conseguirmos colocar as mãos no grimório dele, talvez eu possa criar contrafeitiços e outros meios de enfraquecer a mágica dos elementais.$B$BVocê precisa descer até o Abismo Rocha Negra para encontrar o Santuário de Thaurissan e roubar o grimório. Não tenha piedade do Sábia Semente, muito menos dos lacaios do Crepúsculo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Maginor Dumas no Sacrário dos Teurgos, que fica no Distrito dos Magos em Ventobravo.', 0),
(28399, 'ptBR', 'Pedras vinculadoras', 'Consiga 6 Pedras Vinculadoras Elementais do Abismo Rocha Negra. Você pode encontrá-las na Cidade de Umbraforja, no Domicílio, no Santuário de Thaurissan, na Guarnição Leste e na Guarnição Oeste.', 'Me foi confirmado que a AVIN está preocupada com o trabalho em conjunto do Martelo do Crepúsculo com os anões Ferro Negro no Abismo Rocha Negra. Podemos nos aproveitar dessa informação e provar nosso valor para a Aliança.$B$BO relatório diz que os seguidores do Martelo do Crepúsculo espalharam pedras vinculadoras elementais na Cidade de Umbraforja, no Domicílio, no Santuário de Thaurissan e nas Guarnições Leste e Oeste. Encontre-as e traga-as para mim!', '', '', '', '', '', '', '', '', '', 'Fale com Joyce Lopes no porão do Cordeiro Imolado, que fica no Distrito dos Magos em Ventobravo.', 0),
(28400, 'ptBR', 'Heróis da Horda!', 'Roube os Planos de Batalha da Aliança e torne-se herói da Horda.', 'Agora é encontrar os planos de batalha e cuidar de seus líderes! Se formos bem-sucedidos, há um orc que é sumo senhor da guerra e concederá a nós dois grandes honrarias por isto! Ele lutou em Pinhaprata e agora está lotado na Serraria Tarren, localizada no coração de Eira dos Montes. Seremos heróis da Horda, $n!$B$BAdiante! Juntos derrotaremos os vermes da Aliança!', 'Tornem-se heróis da Horda', '', '', '', '', 'Tornem-se heróis da Horda', '', '', '', 'Entregue os planos de batalha da Aliança ao Sumo Senhor da Guerra Cromush na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28401, 'ptBR', 'Escravos do Senhor do Fogo', 'Use o Totem da Liberdade para libertar as essências de 6 Flamiguardas, Flamiguardas Destruidores ou Flamiguardas Fulgurantes no Abismo Rocha Negra.', 'Por de trás dos muros do Abismo Rocha Negra, a seita do Martelo do Crepúsculo e os anões Ferro Negro juntam forças, reforçados por hordas de elementais sob domínio do senhor do fogo, Ragnaros.$B$BSe conseguirmos libertar esses elementais, não apenas enfraqueceremos nossos inimigos, mas também honraremos os elementos. Leva este totem e usa-o nos flamiguardas subjugados. Isto libertará os espíritos deles e os trará de volta ao estado natural.', '', 'Flamiguardas libertados', '', '', '', '', '', '', '', 'Fale novamente com a Clarividente Umbrua no Distrito dos Anões, em Ventobravo.', 0),
(28402, 'ptBR', 'Um Schnottz ou outro', 'Mate 10 Soldados de Elite do Schnottz na Câmara da Lua.', 'Estou quase pronto, $n.$b$bOs pergaminhos continham informações suficientes para que eu entendesse o método de encriptação deles. Agora, tudo que resta é traduzir os códigos.$b$bPreciso que você investigue a câmara sob o Obelisco da Lua. É provável que haja alguns soldados do Schnottz por lá, sobreviventes da sua explosão.$b$bCuide deles e encontrarei você lá quando eu terminar.', '', 'Soldados de Elite de Schnottz mortos', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Câmara da Lua.', 0),
(28403, 'ptBR', 'É melhor não errarmos', 'Acompanhe Harrison Jones na Câmara da Lua.', 'Deveria existir dois dispositivos de comunicação nesta câmara.$b$bSe as minhas traduções estão corretas, um deles é uma armadilha mortal, enquanto o outro aceitará os códigos e ativará o obelisco.$b$bVamos torcer para que eu acerte essa.$b$bAvise-me quando você estiver pront$go:a;.', '', 'Dados titânicos transferidos', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Câmara da Lua.', 0),
(28404, 'ptBR', 'Vou fazer isso na mão', 'Derrote o Guardião Titânico.', 'Sim, isso tudo parece familiar.$b$bGraças a todas as informações que você coletou para mim, tenho certeza de que conseguirei ativar o mecanismo. Só preciso de algum tempo sem distrações.$b$bSempre que eu começo a trabalhar, aquele constructo titânico tenta me parar.$b$bÉ aí que você entra.$b$bNão preciso lembrar você da importância disto. Derrube aquele guardião!', '', 'Guardião Titânico derrotado', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Câmara da Lua.', 0),
(28405, 'ptBR', 'Armas das trevas', 'Consiga 5 Armas Imbuídas em Poder Elemental dos anões Furiadastra no Abismo Rocha Negra. Depois, quebre-as na Bigorna Negra da Cidade de Umbraforja.', 'O Abismo Rocha Negra há muito é o lar dos nossos inimigos, mas recentemente a AVIN nos informou que a colaboração entre os Ferro Negro e o Martelo do Crepúsculo tem aumentado. Com ajuda dos conhecimentos do culto, os anões Ferro Negro estão imbuindo suas armas em poder elemental e equipando a legião Furiadastra com essas armas terríveis.$B$BQuero que você invada o Abismo Rocha Negra, capture as armas dos anões Furiadastra e quebre-as na Bigorna Negra, que fica no coração da Cidade de Umbraforja.', '', 'Armas Imbuídas em Poder Elemental quebradas', '', '', '', '', '', '', '', 'Fale novamente com o Lorde Grayson Quebrassombra na Catedral da Luz, em Ventobravo.', 0),
(28406, 'ptBR', 'O exército Ferro Negro', 'Use o Veneno de Efeito Rápido para contaminar 6 Rações em Grão na Guarnição Oeste ou Leste do Abismo Rocha Negra.', 'As coisas estão esquentando na Montanha Rocha Negra, $n. Nossas fontes relatam que os anões Ferro Negro se uniram ao Martelo do Crepúsculo e agora se preparam para uma grande ofensiva.$B$BJá notifiquei os principais líderes de Ventobravo sobre este caso, mas preciso de ajuda para lidar com esta ameaça iminente.$B$BOs suprimentos de grande parte do exército Ferro Negro está estocado nas Guarnições Leste e Oeste do Abismo Rocha Negra. Leve este veneno e acabe com as reservas de grãos deles.', '', 'Rações em Grão envenenadas', '', '', '', '', '', '', '', 'Fale novamente com o Lorde Tony Romano na AVIN, ao sul da Cidade Velha, em Ventobravo.', 0),
(28407, 'ptBR', 'A solteira', 'Fale com Fanny em Kirthaven, que fica no Planalto do Crepúsculo.', 'Barbarruiva? Casar com minha irmã? Mas é mesmo o fim dos tempos! Ainda assim, talvez Kurdran esteja certo... Um casamentinho acalmaria os ânimos de todos... e refrescaria a cuca do Barbarruiva. Foi ótimo agirmos juntos contra os ogros.$B$BEntão é isso! Agora depende da Fanny. Mas algo me diz que ela não está a fim de comprometimento.$B$BVoe de volta para Kirthaven e veja se ela topa. Vou terminar meu servicinho sujo com os ogros aqui.', '', '', '', '', '', '', '', '', '', '', 0),
(28408, 'ptBR', 'Não tenha pena', 'Recolha 12 Penas Imaculadas de Coruja.', 'Por tradição, as noivas Martelo Feroz se vestem de branco para mostrar que são puras. E também uma coroa de penas negras para mostrar o BOR\'O\'GODOH delas.$B$BPenas de coruja fazem coisas macanudas e Fanny merece o melhor. Corujas castanhas são nativas do Planalto. Procure elas pelas árvores que nascem nas colinas e pegue suas penas.$B$BProvavelmente você vai ter que matar elas antes.', '', '', '', '', '', '', '', '', '', 'Leve as penas para Lachlan MacGraff em Kirthaven, que fica no Planalto do Crepúsculo.', 0),
(28409, 'ptBR', 'Caravana da beberagem', 'Fale com Fortemão na estrada a leste de Kirthaven e escolte uma caravana de suprimentos para a cidade.', 'Seria um insulto celebrar um casamento Martelo Feroz sem bebida. Kurdran se encarregou de pedir alguns barris de Cervaforte para serem enviados de Beiralta, mas o carregamento não está passando pelo desfiladeiro.$B$BSiga a estrada a leste daqui, ao redor do flanco sul da Montanha Golpeforte, e encontre-se com a caravana. Procure um paisano chamado Fortemão e ajude no transporte da birita pelo desfiladeiro!', '', 'Caravana de Suprimentos escoltada', '', '', '', '', '', '', '', 'Fale com Lachlan MacGraff em Kirthaven, que fica no Planalto do Crepúsculo.', 0),
(28410, 'ptBR', 'Quem não tem seda... costura com qualquer coisa', 'Colete um pedaço de Tecido Negro Especial.', 'Todos vão querer vestir o que têm de melhor para a ocasião, mas elegância é uma coisa rara no Planalto.$B$BSei que os malditos goblins da costa usam a mais fina seda para consertarem as coberturas de seus zepelins. Um desperdício!$B$BEncontre um zepelim que voe entre o Porto Presa do Dragão e os Krazzodutos e consiga um tanto de seda no bagageiro do convés inferior.', '', '', '', '', '', '', '', '', '', 'Leve o tecido para Lachlan MacGraff em Kirthaven, que fica no Planalto do Crepúsculo.', 0),
(28411, 'ptBR', 'Vem quente que já está assando', 'Colete 8 cortes de Carne Fresca e 5 Costelas de Worg.', 'Por fim, precisamos arranjar um banquete. E nada de "petisquinhos"! A multidão quer carne, muita carne!$B$BPegue um tanto de carne de cervo do Planalto. Um bom worg do Planalto também é bem gostoso – traga umas costelas. Prepararemos um banquete como você nunca viu em todos os Reinos do Leste, $gamigo:amiga;!', '', '', '', '', '', '', '', '', '', 'Entregue a comida para Lachlan MacGraff em Kirthaven, que fica no Planalto do Crepúsculo.', 0),
(28413, 'ptBR', 'Letra e música de...', 'Fale com Tom de Moraes e ajude-o a compor uma música.', 'Já compus muitas canções épicas em minha vida, $n, mas esse casamento merece uma balada especial. E rápido!$B$BSerá que componho uma canção de amor? Uma cantiga singela? Uma vulgar anedota?$B$BPreciso de uma ajuda com a letra se você se dispuser a isso.$B$BFale comigo e vamos compor uma canção juntos!', '', 'Crie uma música', '', '', '', '', '', '', '', 'Fale com Tom de Moraes em Kirthaven, que fica no Planalto do Crepúsculo.', 0),
(28414, 'ptBR', 'Chute a gol', 'Entre no Retalhador de Borraquilha e dê o chute da vitória, chutando a Futebomba por entre as chaminés atrás do gol do adversário.', 'Agora é com você, $ggaroto:garota;. Você demoliu o Flamingo. Só falta você chutar a gol pra ganharmos o jogo.$B$B<O treinador se aproxima de você e sussurra em seu ouvido.>$B$BAgora, aqui entre você e eu, acho que devíamos mandar um pouco melhor dessa vez. Não quero só que você chute a gol... Eu quero que você dê um chute tão forte que a bola passe entre as duas chaminés atrás do gol!$B$BEu modifiquei a futebomba para te dar a potência extra que você precisa!$B$BAgora vai lá e me dê orgulho!', '', 'Futebomba Chutada Entre as Chaminés', '', '', '', '', '', '', '', 'Fale com o Técnico Fagallo no Campo Jakaro, em Kezan.', 0),
(28415, 'ptBR', 'SETE! OBA!', 'Capture 7 Moscas-lume.', 'Precisamos tomar uma atitude. O Piscadela e o Gor\'tesh estavam brigando, então planejei esta cerimônia da amizade para ajudar os dois a fazerem as pazes. Estava tudo indo bem, até que...$B$BBem, o resto você sabe.$B$BEu comprei até bebida!$B$BO Piscadela adora moscas-lume. Ele as caça quase toda noite. Acho que talvez ele tenha ido fazer isso.$B$BVocê encontrará moscas-lume a oeste e ao norte, onde quer que haja lava. Traga-me sete delas, e rápido!$B$BO Gor\'tesh pode ser o próximo a ir embora!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Oralius na Vigia de Morgan, que fica nas Estepes Ardentes.', 0),
(28416, 'ptBR', 'Vingança ardente', 'Mate 5 Crias Rocha Negra e 5 Ninhadas Flamescama.', '$n, é você? Pensei que você estivesse $Gmorto:morta;, como os outros!$B$BNão, você sempre foi forte, mesmo naquela época, até mesmo em Cristarrubra.$B$BNossa luta não acabou, $n. Eles já atacaram a nossa terra natal. Estou aqui para garantir que isso não aconteça novamente.$B$BSe você ainda pode lutar como lutou naquela época, junte-se a mim. Você pode começar indo para o sul, para a Colina dos Dragonetes, e matando as crias e os filhotes de dragão negro.$B$BSerá como nos velhos tempos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com John J. Keeshan no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28417, 'ptBR', 'Inocentes', 'Obtenha um Dragonetinho Vermelho Libertado, um Dragonetinho Verde Libertado, um Dragonetinho Azul Libertado e um Dragonetinho Bronze Libertado.', 'Os orcs Rocha Negra das estepes servem a um mestre maligno – um mestre que conduz experimentos em seres vivos e cria sua própria coleção de abominações. Muitas das cobaias são tão corrompidas quanto seu mestre, mas outras são completamente inocentes.$B$BNa Colina dos Dragonetes, a sul, eles acorrentam filhotinhos de dragão ao chão para prepará-los para tais experimentos. Não vou aceitar isso. Destrua os grilhões e traga os filhotes de volta para mim... Para um lugar seguro.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Mouton Flamestrela no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28418, 'ptBR', 'Vingança ardente', 'Mate 5 Crias Rocha Negra e 5 Ninhadas Flamescama.', 'Sou um orc Rocha Negra de nascimento. Passei grande parte da minha juventude dentro daquela montanha.$B$B<Ariok volta-se na direção da Montanha Rocha Negra, ao norte.>$B$BMas, embora meu sangue seja como o deles, meu ponto de vista não é. Estou procurando $Gum aliado:uma aliada; para me ajudar a impedir o ataque iminente deles.$B$BEntão, prove o seu valor. Vá para o sul, para a Colina dos Dragonetes, e mate as crias e os filhotes de dragão negro. Prove para mim que você está preparad$go:a; para esta guerra.', '', '', '', '', '', '', '', '', '', 'Fale com Ariok no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28419, 'ptBR', 'Repondo o estoque', 'Obtenha 5 Farpas Afiadas de Escorpídeo.', 'Se vamos entrar em guerra contra o clã Rocha Negra, precisamos de um plano. Meu pai já montou um, e está na hora de executá-lo.$B$BPreciso de aguilhões de escorpídeo. Os mais afiados que você conseguir encontrar. Os escorpídeos estão por toda a estepe, mas você encontrará a maioria na ravina a oeste.$B$BNão se preocupe com a utilidade deles. Você descobrirá em breve.', '', '', '', '', '', '', '', '', '', 'Fale com Ariok no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28420, 'ptBR', 'Um projeto futuro', 'Obtenha 11 Pelegos de Worg Incandescente.', 'Segundo o meu pai, vamos precisar de pelegos de worg, e muitos. Não importa se estiverem rasgados, queimados ou ensanguentados: precisamos deles em grandes quantidades.$b$bNa verdade, talvez até seja melhor que os pelegos estejam um pouco deteriorados.$b$bVocê encontrará worgs a oeste e a leste daqui.', '', '', '', '', '', '', '', '', '', 'Fale com Ariok no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28421, 'ptBR', 'Caçador de lama', 'Obtenha 9 montes de Lama Salpicada de Obsidiana.', 'Espero que você não tenha medo de se sujar. A julgar pela sua aparência, isso não será um problema.$B$BAo norte, às margens do rio de lava, você encontrará montes de lama escura. Preciso delas.$B$BSeria melhor se você não fizesse perguntas e se concentrasse em seguir ordens, $n.', '', '', '', '', '', '', '', '', '', 'Fale com Ariok no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28422, 'ptBR', 'A areia, a sidra e o orbe', 'Fale com Gorzeeki Olholouco perto do Altar das Tempestades.', 'Meu pai está nos esperando ao leste. Antes de sairmos, porém, precisamos de mais algumas coisas. Desta vez, você as pegará de um bruxo que atende pelo nome de Gorzeeki Olholouco.$B$BVocê deve encontrá-lo a noroeste, perto do Altar das Tempestades. Diga-lhe que ele nos ajudará. Precisamos da areia, da sidra e do orbe.$B$BEle vai saber o que isso significa.', '', '', '', '', '', '', '', '', '', 'Fale com Gorzeeki Olholouco no Altar das Tempestades, que fica nas Estepes Ardentes.', 0),
(28423, 'ptBR', 'Os bruxos têm as coisas mais legais', 'Obtenha um punhado de Areia do Sono, um jarro de Sidra Redonda Vil, e um Orbe Límpido de Vidro.', 'O Ariok disse que precisa de suprimentos? A gente tem suprimento a dar com pau! O problema é que esses bruxos me expulsaram de casa e não vão me deixar voltar.$B$B<Olholouco mede o seu tamanho.>$B$BMas pode ser que você consiga entrar lá. Vai pro norte e busca minha areia do sono, minha sidra redonda vil e um orbe límpido de vidro. Tenho certeza de que é isso que ele quer.$B$BAh, se você matar uns orcs sem querer enquanto estiver lá em cima, eu não vou ficar chateado.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gorzeeki Olholouco no Altar das Tempestades, que fica nas Estepes Ardentes.', 0),
(28424, 'ptBR', 'Encaixotando o Sombrio', 'Mate Ner\'gosh, o Sombrio.', 'O Ner\'gosh, o Sombrio, é o líder daqueles bruxos ao norte. Ele é o vacilão que me expulsou de casa quando aqueles orcs Rocha Negra começaram a aparecer. Bom, eles são todos uns vacilões, mas ele é o mais vacilão de todos.$B$BPra eu voltar a morar perto do altar, o Ner\'gosh tem que sumir dali.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Gorzeeki Olholouco no Altar das Tempestades, que fica nas Estepes Ardentes.', 0),
(28425, 'ptBR', 'De volta a Ariok', 'Leve os Suprimentos de Bruxaria para Ariok no Posto Flamestrela, que fica nas Estepes Ardentes.', 'Bom, acho que não precisarei mais de você. Vou enxotar daqui aqueles outros bruxos quando tiver criado coragem.$B$BAqui, não se esqueça dos suprimentos!', '', '', '', '', '', '', '', '', '', 'Apresente-se a Ariok no Posto Flamestrela, que fica nas Estepes Ardentes.', 0),
(28426, 'ptBR', 'Laceragarra, o coração das estepes', 'Elimine 15 soldados Rocha Negra de qualquer tipo em sua viagem para Laceragarra.', 'Estamos indo para Laceragarra, bem no centro destas estepes. Vamos nos encontrar com a Irmandade do Tório lá, assim como com meu pai.$B$BVocê conhece a irmandade? Aqueles anões Ferro Negro já me ajudaram mais de uma vez. Talvez precisemos da ajuda deles novamente.$B$BVamos passar pelo Casebre Dente Preto no caminho até lá. O que você acha de matarmos alguns Ferro Negro durante a viagem? Estou ficando meio inquieto neste acampamento.', '', 'Tropas Rocha Negra eliminadas', '', '', '', '', '', '', '', 'Fale com Estêvão Ferrogusa em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28427, 'ptBR', 'Uma agulha num palheiro infernal', 'Fale com Thelaron Agulhetes em Laceragarra, que fica nas Estepes Ardentes.', 'Lok\'tar, $c. Meu nome é Eitrigg, da Cruzada Argêntea. Antes, eu era o Chefe Guerreiro da Guarda de Honra. Antes disso, dos orcs Rocha Negra. Creio que meu filho já lhe contou o nosso plano. Não? Talvez seja melhor assim.$B$BA próxima parte do plano requer uma certa sutileza.$B$BFale com Thelaron Agulhetes, o alfaiate da cidade. Já entreguei a ele os pelegos e a lama que você coletou. Ele vai precisar tirar as suas medidas.$B$BÉ isso mesmo, $r: você vai $Gdisfarçado:disfarçada;.', '', '', '', '', '', '', '', '', '', 'Fale com Thelaron Agulhetes em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28428, 'ptBR', 'Uma fantasia perfeita', 'Traga a quantidade apropriada de materiais da mesa de alfaiataria para Thelaron Agulhetes, em Laceragarra.', 'Com seu peso, estrutura e tamanho, é melhor $Gvesti-lo:vesti-la; como $Gum orc:uma orquisa;. A maior parte do exército deles é feita de orcs, então você vai se encaixar direitinho no grupo.$B$BVocê sabe algo sobre alfaiataria? Se não, considere isto a primeira lição. Tem todos os materiais necessários ali na minha mesa de alfaiataria.$B$BVá lá, pegue o que achar necessário e traga aqui. O Agulhetes vai dar um jeito em você rapidinho.', '', 'Fantasia Perfeita criada', '', '', '', '', '', '', '', 'Fale com Eitrigg em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28429, 'ptBR', 'Uma fantasia perfeita', 'Traga a quantidade apropriada de materiais da mesa de alfaiataria para Thelaron Agulhetes, em Laceragarra.', 'Com seu peso, estrutura e tamanho, é melhor $Gvesti-lo:vesti-la; como $Gum ogro:uma ogra;. Os ogros Pirobucho sempre trabalharam para os Rocha Negra, então, você vai se encaixar direitinho no grupo.$B$BVocê sabe algo sobre alfaiataria? Se não, considere isto a primeira lição. Tem todos os materiais necessários ali na minha mesa de alfaiataria.$B$BVá lá, pegue o que achar necessário e traga aqui. O Agulhetes vai dar um jeito em você rapidinho.', '', 'Fantasia Perfeita criada', '', '', '', '', '', '', '', 'Fale com Eitrigg em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28431, 'ptBR', 'Uma fantasia perfeita', 'Traga a quantidade apropriada de materiais da mesa de alfaiataria para Thelaron Agulhetes, em Laceragarra.', 'Com seu peso, estrutura e tamanho, é melhor $Gvesti-lo:vesti-la; como $Gum troll:uma trolesa;. Os trolls Fumocardo sempre trabalharam com os orcs Rocha Negra, então, você vai se encaixar direitinho no grupo.$B$BVocê sabe algo sobre alfaiataria? Se não, considere isto a primeira lição. Tem todos os materiais necessários ali na minha mesa de alfaiataria.$B$BVá lá, pegue o que achar necessário e traga aqui. O Agulhetes vai dar um jeito em você rapidinho.', '', 'Fantasia Perfeita criada', '', '', '', '', '', '', '', 'Fale com Eitrigg em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28432, 'ptBR', 'No Casebre Dente Preto', 'Fale com o Intendente Kaoshin no Casebre Dente Preto, que fica nas Estepes Ardentes.', 'A atuação é o mais importante quando se trabalha sob disfarce. Aja como se devesse estar ali, e vai dar tudo certo.$B$BSeu contato no Casebre Dente Preto será um orc chamado Intendente Kaoshin. Ele NÃO SABE que você é $Gum espião:uma espiã;, portanto, mantenha a tranquilidade.$B$BFaça o que Kaoshin pedir.$B$B<Eitrigg põe um pequeno objeto mecânico na palma da sua mão.>$B$BPonha este aparelho no seu ouvido. Eu manterei contato para dar a você qualquer instrução especial.$B$BBoa sorte, soldado.', '', '', '', '', '', '', '', '', '', 'Fale com o Intendente Kaoshin no Casebre Dente Preto, que fica nas Estepes Ardentes.', 0),
(28433, 'ptBR', 'Trabalho de bruto', 'Dê uma engraxada das boas em 7 pares de Botas de Rocha Negra.', 'Bah! Sua sorte é que estou com falta de pessoal hoje. Se não fosse por isso, você seria $Go escolhido:a escolhida; para levar as chicotadas da semana.$B$BOs oficiais e soldados de alto escalão precisam das botas polidas. Eles as deixaram na frente das barracas.$B$BQuero ver minha cara refletida nessas botas, $Gbruto:bruta;! Ao trabalho!', '', 'Pares de Botas de Rocha Negra engraxadas', '', '', '', '', '', '', '', 'Fale novamente com o Intendente Kaoshin no Casebre Dente Preto, que fica nas Estepes Ardentes.', 0),
(28434, 'ptBR', 'Atalhos estratégicos', 'Use as Farpas Afiadas de Escorpídeo no Voduzeiro Timan, no topo do Pilar de Cinzas, na Worgmestra Othana, nas jaulas de worg, e em Gorlop, quando ele estiver perto das poças de lava.', '<Você ouve um zumbido.>$B$B$n? É o Eitrigg.$B$BAcabamos de receber as informações que faltavam para nossa próxima missão. Existem três alvos que gostaríamos que você acertasse. O primeiro é o Voduzeiro Timan, a quem você irá encontrar no topo do Pilar de Cinzas. A Worgmestra Othana, que está nas jaulas de worg centrais. Pra terminar, o Gorlop, que está perto das poças de lava ao sul.$B$BVocê vai encontrar as farpas escorpídeas que pegou junto com seus pertences. Use as farpas nos alvos no momento certo.', '', '', '', '', '', '', 'Eitrigg', 'Bom trabalho.', 'Eitrigg', '', 0),
(28435, 'ptBR', 'A trompa para chamar kodos', 'Use a Trompa do Chamado para chamar 7 Kodos de Guerra Rocha Negra Guerreiros de volta para o acampamento. Se um kodo for hostil, lute até que ele se submeta.', 'Certo, temos um serviço realmente importante pra você. Precisamos chamar os kodos das pastagens ao sul. O general Thorg\'izog disse que vamos para Cristarrubra em breve, e não vou ser apanhado com meus kodos na mão.$B$BUse esta trompa perto de um kodo. Ele vai retornar ao acampamento quando ouvir o chamado.$B$BÉ melhor você tomar cuidado. Às vezes os kodos são meio briguentos. Quando for assim, é preciso bater neles para que obedeçam.', '', 'Kodos de Guerra Rocha Negra de volta ao acampamento', '', '', '', '', '', '', '', '', 0),
(28436, 'ptBR', 'Tomando a trompa para nós', 'Leve a Trompa do Chamado para Eitrigg em Laceragarra, que fica nas Estepes Ardentes.', '$n, é o Eitrigg. Guarde aquela trompa. Podemos improvisar e encontrar um jeito de incorporá-la ao plano.$B$BEstou muito preocupado com o que Kaoshin disse sobre atacar Cristarrubra. Sabíamos que havia um ataque iminente, mas não tão rápido assim!$B$BFale comigo novamente, e com a trompa em mãos. Conversaremos de novo aqui em Laceragarra. E tente não estragar aquele disfarce. Seu trabalho de espionagem ainda não terminou.', '', '', '', '', '', '', 'Eitrigg', '', '', 'Fale com Eitrigg em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28437, 'ptBR', 'General Thorg\'izog', 'Fale com o General Thorg\'izog.', 'O Kaoshin acabou sendo mais útil do que eu esperava, mas não temos mais o que tratar com ele. Está na hora de você falar com o General. Acho que você está $Gpronto:pronta;.$B$BO general Thorg\'izog é um dos "três poderosos" que comandam as tropas de infantaria aqui nas Estepes Ardentes, a noroeste. Vista seu disfarce e vá falar com ele. Veja se consegue ganhar a confiança dele. Eu manterei contato, caso precise de algo mais.', '', '', '', '', '', '', '', '', '', 'Fale com o General Thorg\'izog na Fortaleza Rocha Negra, que fica nas Estepes Ardentes.', 0),
(28438, 'ptBR', 'Prova de magma', 'Fale com Wyrtle Spreelthonket e peça para que ele liberte o Lorde Magma Kolob. Então, vença o Lorde Magma Kolob em batalha.', 'Suponho que tirarei o máximo de proveito desta situação. Esses goblins mercenários trouxeram este elemental do fogo enorme para minha fortaleza como um agradecimento por tê-los contratado. O que eu vou fazer com um elemental aqui nas estepes? É como levar areia pra praia!$B$BSe está procurando serviço, prove seu valor. Fale com este goblin aqui e desafie o seu elemental para uma briga. O vencedor ganhará o meu respeito e o meu tempo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o General Thorg\'izog na Fortaleza Rocha Negra, que fica nas Estepes Ardentes.', 0),
(28439, 'ptBR', 'Eu sou a lei e o açoite', 'Use a Borduna da Disciplina de Rocha Negra em 20 soldados nos Campos de Honra. Se um deles descobrir o seu disfarce, bata nele com a borduna até a morte, antes que ele possa desmascarar você.', 'Eu estava procurando $gum:uma; soldado $gbom:boa; e forte como você. Preciso de alguém que mantenha minhas tropas na linha.$B$BFora da fortaleza, você encontrará orcs, ogros e trolls se preparando para o ataque a Cristarrubra. Meus sargentos os mantém na linha, mas eu gostaria que você os ajudasse.$B$BLeve esta clava e discipline alguns dos meus soldados. Estejam eles se comportando mal ou perfeitamente alinhados, quero que apanhem. Quero que fiquem concentrados, prontos para a batalha e obedientes.$B$BAgora, vá.', '', 'Lacaios Rocha Negra disciplinados', '', '', '', '', '', '', '', 'Fale novamente com o General Thorg\'izog na Fortaleza Rocha Negra, que fica nas Estepes Ardentes.', 0),
(28440, 'ptBR', 'Abuso de poder', 'Mate 5 Sargentos Rocha Negra usando a Borduna da Disciplina de Rocha Negra. Derrote-os rapidamente antes que eles tenham uma chance de desmascarar você.', '$n? Aqui é o Eitrigg.$B$BParece que você conquistou a confiança de Thorg\'izog, e ele confiou a você a disciplina das tropas. Isso foi muita sorte.$B$BPrecisamos que você acabe com os sargentos dele. Você os encontrará montados em lobos, do lado de fora da Fortaleza Rocha Negra, nos Campos de Honra. Use a borduna neles várias vezes, até que morram. Você terá que agir rapidamente. Se eles perceberem que você não é um deles, eles podem $Gdesmascará-lo:desmascará-la;. Ataque com rapidez e violência, $n.', '', 'Sargentos Rocha Negra eliminados', '', '', '', '', 'Eitrigg', 'Pronto. Boa formação, aliás.', 'Eitrigg', '', 0),
(28441, 'ptBR', 'Dano suficiente por um dia', 'Fale novamente com Eitrigg em Laceragarra.', 'Não temos mais necessidade de criar estratégias contra Thorg\'izog, nem contra as tropas de infantaria Rocha Negra. Precisamos continuar com a fase seguinte do plano.$B$BQuando tiver terminado na fortaleza, volte a falar comigo e com meu filho aqui em Laceragarra.', '', '', '', '', '', '', 'Eitrigg', '', '', 'Fale com Eitrigg em Laceragarra, que fica nas Estepes Ardentes.', 0),
(28442, 'ptBR', 'Monte Candente', 'Fale com Kibler no Monte Candente, que fica nas Estepes Ardentes.', 'Nosso trabalho aqui em Laceragarra está terminado, em grande parte graças a você. Agora, vamos para o Monte Candente, ao nordeste.$B$BO monte fica nos penhascos, depois das Ruínas de Thaurissan. Deve servir como uma base de operações adequada para os últimos estágios do nosso plano.$B$BClaro que meu filho, Ariok, vai encontrar com você no caminho. E eu também.', '', '', '', '', '', '', '', '', '', '', 0),
(28443, 'ptBR', 'Cinzas negras', 'Obtenha 9 montes de Cinzas Obsidianas.', 'Preciso que você junte mais umas coisas antes que possamos acabar com o que restou do exército Rocha Negra. Se vamos fazer isso, vamos fazer direito, e isso significa estarmos preparados.$B$BPreciso de cinzas, $n. E não é qualquer cinza: são as cinzas dos elementais maiores de obsidiana, que vagam pelas planícies a sudeste. Ela é muito, muito negra, e é disso que precisamos para nosso próximo disfarce.$B$BNão se preocupe, você já tem um disfarce. Este será para alguém... Bem, para ALGO diferente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Eitrigg no Monte Candente, que fica nas Estepes Ardentes.', 0),
(28444, 'ptBR', 'Demônios latentes', 'Obtenha 18 Lumenoides Caídos.', 'A lava próxima daqui, ao sul, é como um hospedeiro para os lumenoides, um tipo de demônio do fogo que há muito vaga pelas estepes. A situação no exército Rocha Negra é tal que, se formos cuidadosos, talvez consigamos pôr alguns desses lumenoides atrás das linhas inimigas para causar confusão.$B$BTraga-me os corpos de vários lumenoides. Como demônios, eles são ressuscitados com facilidade, e podemos usá-los para nossos próprios fins.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Eitrigg no Monte Candente, que fica nas Estepes Ardentes.', 0),
(28445, 'ptBR', 'Um montão de worgs deliciosos', 'Use a Worgserra nos corpos dos Worgs Incandescentes Gigantes mortos para obter 40 Costeletas de Worg.', 'Vamos precisar de carne fresca, e isso significa que você vai ter que caçar uns worgs deste lado da estepe.$b$b<Eitrigg traz uma grande serra e a entrega a você.>$b$bSeu alvo será os worgs incandescentes gigantes. Após abatê-los, use esta serra para tirar os melhores cortes de carne. Os worgs estão espalhados por toda a estepe, mas a alcateia mais próxima domina as terras a sudeste daqui.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Eitrigg no Monte Candente, que fica nas Estepes Ardentes.', 0),
(28446, 'ptBR', 'Passeio sangrento', 'Mate 25 Dragomorfos Pretos ou Draconoides Pretos.', 'Minhas pernas estão meio inquietas de novo. Está interessad$go:a; em dar um passeio, $n?$B$BNós vamos dar uma volta até o Rochedo Malhorrendo. Eu gostaria de investigar o exército Rocha Negra antes de darmos o próximo passo, e acho que podemos também matar alguns deles no caminho.', '', '', '', '', '', '', '', '', '', 'Fale com Ariok.', 0),
(28447, 'ptBR', 'Vanguarda dracônica', 'Mate Minyoth, o Domador de Dragonetes Akumi, Terromath, o Marcado, e Tugnar Gorjavil.', 'Os orcs Rocha Negra não vêm sozinhos. Você já viu que os ogros Pirobucho e os trolls Fumocardo estão ao lado deles. Infelizmente, eles também se juntaram com a revoada negra.$B$BOs orcs e os dragões já mandaram alguns de seus campeões para ficar de guarda em pontos de reagrupamento, que são marcados por um crânio de dragão em uma estaca. Você e eu vamos encontrar esses pontos de reagrupamento e acabar com essa vanguarda antes que a batalha comece.$B$B$GPreparado:Preparada;?', '', '', '', '', '', '', '', '', '', 'Fale com Ariok.', 0),
(28448, 'ptBR', 'Acordo com um dragão', 'Entregue os Dragonetinhos Resgatados a Acrídeo na Rocha Coleante, que fica nas Estepes Ardentes.', 'Enquanto estamos circulando pelo Rochedo Malhorrendo, tem mais uma parada que precisamos fazer.$B$BLembra dos filhotes que você libertou na Colina dos Dragonetes? Eu tenho cuidado deles, e agora vamos entregá-los a alguém que vai cuidar deles melhor do que nós. Ele está na Rocha Coleante, a nordeste do Rochedo Malhorrendo.$B$BO nome dele é Acrídeo, e talvez ele seja a chave para a vitória na batalha que se aproxima.', '', '', '', '', '', '', '', '', '', 'Fale com Acrídeo na Rocha Coleante, que fica nas Estepes Ardentes.', 0),
(28449, 'ptBR', 'Arrumando os peões', 'Fale novamente com Eitrigg no Monte Candente, que fica nas Estepes Ardentes.', '<Você ouve um zumbido.>$B$B$n. Parece que você e Ariok terminaram suas tarefas. Também terminei a minha.$B$BVolte para o Monte Candente. Preparei algumas encomendas para entregar aos "três poderosos": Thorg\'izog, Niralak e Xi\'lun. Você já conheceu o general Thorg\'izog. Esta é a sua chance de conhecer os outros dois.$B$BAntes de matá-los, claro.', '', '', '', '', '', '', 'Eitrigg', '', '', '', 0),
(28450, 'ptBR', 'Uma entrega para Thorg\'izog', 'Usando seu Disfarce de Rocha Negra, leve as Costeletas Marinadas na Sidra Vil para o General Thorg\'izog na Fornalha Pirobucho, que fica nas Estepes Ardentes. Fale com Eitrigg se você precisar de um Disfarce de Rocha Negra.', 'O general Thorg\'izog está entre os ogros da Fornalha Pirobucho, uma caverna na fronteira oeste do Rochedo Malhorrendo. Entregue isto para ele e para os ogros.$B$BDentro deste pacote, você encontrará as Costeletas de Worg que você trouxe, marinadas na sidra redonda vil que pegamos do Altar das Tempestades.$B$BEu evitaria comê-las se fosse você.$B$BLeve-as para o general Thorg\'izog. Ele vai alimentar as suas tropas e, se tivermos sorte, ele mesmo vai comer.', '', '', '', '', '', '', '', '', '', 'Fale com o General Thorg\'izog na Fornalha Pirobucho, que fica nas Estepes Ardentes.', 0),
(28451, 'ptBR', 'Uma entrega para Niralak', 'Usando seu Disfarce de Rocha Negra, vá ao Abrigo da Caveira e convença Niralak, o Senhor dos Dragões, a aceitar o Caixote de Lumenoides Adormecidos. Fale com Eitrigg se você precisar de um Disfarce de Rocha Negra.', 'Os bruxos do clã Rocha Negra costumam praticar sua magia no Abrigo da Caveira, uma caverna na área leste do Rochedo Malhorrendo. Seu líder, Xi\'lun, está ocupado em outro lugar, então, outro dos "três poderosos" está cuidando da caverna: Niralak, o Senhor dos Dragões. Niralak é especializado em dragões, não em necromancia.$B$BEu usei a areia do sono naqueles lumenoides que você capturou. Tente convencer Niralak de que eles são diabretes de bruxos, não lumenoides. Quando eles acordarem, eles não vão estar felizes.', '', '', '', '', '', '', '', '', '', 'Fale com Niralak, o Senhor dos Dragões, no Abrigo da Caveira, que fica nas Estepes Ardentes.', 0),
(28452, 'ptBR', 'Uma entrega para Xi\'lun', 'Usando o Disfarce de Rocha Negra, entregue o Orbe Límpido de Vidro ao Alto Bruxo Xi\'lun no topo do Rochedo Malhorrendo, que fica nas Estepes Ardentes. Fale com Eitrigg se precisar de um Disfarce de Rocha Negra.', 'Nossos dados nos dizem que o alto bruxo Xi\'lun, o último dos "Três Poderosos", está na caverna que fica no topo do Pico Malhorrendo, preparando-se para o grande momento.$B$BEle está esperando uma entrega, um Orbe de Dominância, com o qual poderá fazer um poderoso ritual de evocação. Quero que você dê isto a ele.$B$B<Eitrigg dá a você um orbe de vidro.>$B$BEste é o orbe límpido de vidro que você tirou do Altar das Tempestades. Ele está sem poder algum. Entregue isso a Xi\'lun e torça para que ele não perceba a diferença.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Alto Bruxo Xi\'lun no Rochedo Malhorrendo, que fica nas Estepes Ardentes.', 0),
(28453, 'ptBR', 'Carregado e engatilhado', 'Fale com Eitrigg no Monte Candente, que fica nas Estepes Ardentes.', '$n, responda. Está me ouvindo?$B$BA batalha já vai começar. Espero que você tenha entregado todos aqueles pacotes.$B$BPreciso de você aqui no Monte Candente. AGORA.', '', '', '', '', '', '', 'Eitrigg', '', '', '', 0),
(28454, 'ptBR', 'Ataque ao Rochedo Malhorrendo', 'Mate 200 Invasores Rocha Negra. Se você perder o veículo, use a Trompa do Chamado para evocá-lo novamente.', 'É isso, $n. É um dia triste. Mas é também um dia no qual os orcs Rocha Negra vão aprender uma lição importante. Hoje, nosso plano vai se realizar.$B$BVenha comigo. Vamos falar com Acrídeo e cobrar o favor que ele nos deve. Então, impediremos a invasão a Cristarrubra antes mesmo que ela comece.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Eitrigg no Monte Candente, que fica nas Estepes Ardentes.', 0),
(28455, 'ptBR', 'Glória em meio ao caos', 'Mate o General Thorg\'izog, Niralak, o Senhor dos Dragões, e o Alto Bruxo Xi\'lun.', 'Você e meu filho vão voltar àquela montanha. Três orcs sobreviveram ao ataque, e não vamos descansar até que eles morram.$B$BIsso mesmo, estou falando dos "três poderosos".$B$BO general Thorg\'izog rastejou de volta para a Fornalha Pirobucho. Niralak, o Senhor dos Dragões, está escondido na caverna que fica no topo da montanha. Xi\'lun está nos fundos do Abrigo da Caveira, conspirando com seus amigos bruxos.$B$BDeixe sua marca, $n. Acabe com aqueles orcs Rocha Negra corruptos de uma vez por todas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Eitrigg no Monte Candente, que fica nas Estepes Ardentes.', 0),
(28456, 'ptBR', 'Os espólios da guerra', 'Inspecione o Caixote de Suprimentos Restantes no Monte Candente, que fica nas Estepes Ardentes.', 'Enquanto os orcs Rocha Negra estiverem reunidos no pináculo, duvido que seus planos os levem para perto do povo inocente de Cristarrubra. Você e Ariok cuidaram disso.$B$BEu diria que nos viramos bem aqui nas Estepes Ardentes: aqueles suprimentos de bruxaria que pegamos certamente foram úteis, assim como as cinzas obsidianas que usamos para ocultar o nosso dragão.$B$BMas sobraram algumas coisas. Por favor, pegue o que desejar antes de continuar para além das estepes.', '', '', '', '', '', '', '', '', '', '', 0),
(28457, 'ptBR', 'Uma aliança perigosa', 'Mate 6 Flamiguardas Destruidores e pegue o Plano de Ataque do General do General Forjaversa na Guarnição Oeste, no Abismo Rocha Negra.', 'A Mão Despedaçada acredita que os anões Ferro Negro estejam trabalhando em parceria com o Martelo do Crepúsculo. Existem evidências de que eles estão na Montanha Rocha Negra preparando um ataque em conjunto. Não podemos permitir que isso aconteça.$B$BVocê precisa entrar no Abismo Rocha Negra e conseguir os planos de ataque do Martelo do Crepúsculo que está com o General Forjaversa, na Guarnição Oeste. Não se esqueça de destruir os elementais que se juntaram a eles.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Grezz Iracarpos no Vale da Honra, em Orgrimmar.', 0),
(28458, 'ptBR', 'O grimório do piromante', 'Mate 6 Emissários do Crepúsculo e roube o Grimório de Sábia Semente do Piromante Sábia Semente no Santuário de Thaurissan, no Abismo Rocha Negra.', 'O poder dos Ferro Negro e dos aliados deles, os membros do Martelo do Crepúsculo, está crescendo na Montanha Rocha Negra. O famoso piromante Sábia Semente é de grande importância para a organização das forças do Martelo do Crepúsculo. Se conseguirmos pôr as mãos no grimório dele, talvez eu possa desenvolver contrafeitiços para as magias e maldições do Martelo do Crepúsculo.$B$BVocê precisa descer até o Abismo Rocha Negra, localizar o Santuário de Thaurissan e roubar o grimório. Não tenha piedade do Sábia Semente, muito menos dos lacaios do Crepúsculo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ureda no Antro das Sombras, em Orgrimmar.', 0),
(28459, 'ptBR', 'Pedras de vinculação', 'Consiga 6 Pedras Vinculadoras Elementais do Abismo Rocha Negra. Você pode encontrá-las na Cidade de Umbraforja, no Domicílio, no Santuário de Thaurissan, na Guarnição Leste e na Guarnição Oeste.', 'A Mão Despedaçada descobriu que o Martelo do Crepúsculo está trabalhando em conjunto com os anões Ferro Negro no Abismo Rocha Negra. Temos a oportunidade ideal de atacar nossos inimigos e ao mesmo tempo nos fortalecer, $n.$B$BOs seguidores do Martelo do Crepúsculo espalharam diversas pedras vinculadoras elementais na Cidade de Umbraforja, no Domicílio, no Santuário de Thaurissan e nas Guarnições Leste e Oeste. Encontre-as e traga-as para mim!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kranosh no Antro das Sombras, em Orgrimmar.', 0),
(28460, 'ptBR', 'A ameaça dos Invernosos', 'Mate 15 Pelursos Invernosos de qualquer tipo perto das Fontes Termais de Fogofrio.', 'Eu vim a Hibérnia investigar as Fontes Termais de Fogofrio. Percebi que as águas das fontes têm... propriedades estranhas. Ainda não consegui descobrir o motivo e, pra dizer a verdade, tenho tido dificuldades por causa dos pelursos invernosos.$B$BEles parecem estar tão interessados nas fontes quanto eu. Agora eles estão protegendo as águas com unhas e dentes, e não me deixam chegar perto das duas fontes maiores, ao norte.$B$BSerá que você poderia me dar uma ajuda, para que eu possa continuar a minha pesquisa?', '', 'Pelursos Invernosos mortos', '', '', '', '', '', '', '', 'Fale novamente com Bruna Covaneve nas Fontes Termais de Fogofrio, em Hibérnia.', 0),
(28461, 'ptBR', 'As criações do Lorde Golem', 'Consiga 5 Módulos Elementais dos golens da Fábrica, no Abismo Rocha Negra, e roube o Diagrama do Golem Elemental.', 'A Mão Despedaçada nos repassou informações preocupantes sobre o Abismo Rocha Negra. Parece que o Martelo do Crepúsculo se juntou ao engenheiro Ferro Negro Argelmach para criar golens movidos à energia de elementais. Não podemos permitir que eles tenham tamanha vantagem sobre nós.$B$BÉ seu dever impedir que isto aconteça, $n. Encontre a Fábrica no Abismo Rocha Negra, roube o diagrama que eles estão usando para criar os golens e consiga os módulos elementais usados para energizá-los.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ormak Tiroatroz no Vale da Honra, em Orgrimmar.', 0),
(28463, 'ptBR', 'O exército Ferro Negro', 'Use o Veneno de Efeito Rápido para contaminar 6 Rações em Grão na Guarnição Oeste ou Leste do Abismo Rocha Negra.', 'Como membro da Mão Despedaçada, você sabe que é nosso dever vigiar os inimigos da Horda. Descobrimos recentemente que os anões Ferro Negro se juntaram ao Martelo do Crepúsculo e estão preparando um ataque.$B$B$n, irei enviá-$Glo:la; para que cuide dessa ameaça antes que eles comecem a marchar. Leve este veneno e use-o nas rações dos soldados no Abismo Rocha Negra.$B$BA maior parte dessas rações é mantida nas Guarnições Leste e Oeste do Abismo Rocha Negra.', '', 'Rações em Grão envenenadas', '', '', '', '', '', '', '', 'Fale novamente com Gordul no Antro das Sombras, em Orgrimmar.', 0),
(28464, 'ptBR', 'Cedendo à corrupção', 'Encontre o Caldeirão Invernoso na parte norte do acampamento dos Invernosos.', 'Deve haver algum motivo para a agressividade dos pelursos Invernosos. Quero descobrir o que realmente está acontecendo!$B$BEu vi os pelursos nos campos ao norte, preparando alguma coisa em um caldeirão. Eles o protegem cuidadosamente... Se essa coisa aí que eles estão fazendo for a causa de tudo, preciso dar uma olhada pessoalmente.$B$BEncontre o caldeirão, se ele ainda estiver lá, e me traga o que estiver dentro dele!', '', '', '', '', '', '', '', '', '', '', 0),
(28465, 'ptBR', 'Escravos do Senhor do Fogo', 'Use o Totem da Liberdade para libertar as essências de 6 Flamiguardas, Flamiguardas Destruidores ou Flamiguardas Fulgurantes no Abismo Rocha Negra.', 'Dentro dos salões do Abismo Rocha Negra, a seita do Martelo do Crepúsculo e os anões Ferro Negro juntam forças, reforçados por hordas de elementais sob domínio do senhor do fogo, Ragnaros.$B$BSe conseguirmos libertar esses elementais, não apenas enfraqueceremos nossos inimigos, mas também honraremos os elementos. Leva este totem e usa-o nos flamiguardas subjugados. Isso libertará os espíritos deles e os trará de volta ao estado natural.', '', 'Flamiguardas libertados', '', '', '', '', '', '', '', 'Fale novamente com Terga Rompe-terra no Vale da Sabedoria, em Orgrimmar.', 0),
(28466, 'ptBR', 'Armas das trevas', 'Consiga 5 Armas Imbuídas em Poder Elemental dos anões Furiadastra no Abismo Rocha Negra. Depois, quebre-as na Bigorna Negra da Cidade de Umbraforja.', 'O Abismo Rocha Negra foi lar dos nossos inimigos há muito tempo. Porém, a Mão Despedaçada nos informou que os Ferro Negro e o Martelo do Crepúsculo estão fortalecendo cada vez mais. Com a ajuda dos conhecimentos do culto, os anões Ferro Negro estão imbuindo as próprias armas em poder elemental, transformando-as em verdadeiros pesadelos. Além disso, estão equipando também a legião do Furiadastra.$B$BPreciso que você vá ao Abismo Rocha Negra e colete as armas dos anões do Furiadastra. Quebre-as na Bigorna Negra, no coração da Cidade de Umbraforja.', '', 'Armas Imbuídas em Poder Elemental quebradas', '', '', '', '', '', '', '', 'Fale novamente com o Andarilho do Sol Atohmo no Vale da Sabedoria, em Orgrimmar.', 0),
(28467, 'ptBR', 'Meleca misteriosa', 'Informe Bruna Covaneve sobre as suas descobertas.', 'A substância esverdeada dentro do caldeirão é pútrida e viscosa. Seja lá o que for, não parece ser coisa boa.$B$BÉ melhor voltar à Bruna para lhe informar as descobertas e levar uma amostra do líquido do caldeirão.', '', '', '', '', '', '', '', '', '', '', 0),
(28468, 'ptBR', '[DEPRECATED]Toxic Horrors', 'Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring.', 'I\'ve studied the sample you returned with, and while I can\'t say for sure, I believe it contains traces of toxic elements. However, the only way to know for sure is to gather some as a comparison.$B$BI believe that the Deadwood furbolg may be gathering these elements from other corrupted creatures in Felwood; in particular, the elementals living in the Irontree Woods, called toxic horrors.$B$BCollect a few samples for me to compare, but be careful -- it\'s very dangerous there!', '', '', '', '', '', '', '', '', '', 'Return to Donova Snowden in Winterspring.', 0),
(28469, 'ptBR', 'Mensageiros Invernosos', 'Encontre e derrote o Mensageiro Invernoso e depois pegue o Caixote dos Invernosos.', 'Muito interessante, $n...$B$BA substância perde a toxicidade quando é misturada com a água das fontes termais, apenas conservando a capacidade de afetar temporariamente os que a ingerirem. Deve ser por causa disso que os Invernosos protegem as fontes termais com tanta impetuosidade. Eles precisam delas para purificar a aguardente.$B$BPrecisamos pôr um fim nisso, cortando o contato entre os Invernosos e os pelursos da tribo Lenha Morta. Um grupo de mensageiros percorre a estrada entre a aldeia dos Invernosos e Selva Maleva. Encontre-os, acabe com eles, e roube o seu carregamento.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Bruna Covaneve em Hibérnia.', 0),
(28470, 'ptBR', 'Chefe Supremo Invernoso', 'Mate o Chefe Supremo Invernoso.', 'Os pelursos Invernosos geralmente não são agressivos, e acho que a mudança de comportamento deve ter a ver com as ordens do chefe deles. Provavelmente não vamos conseguir desfazer o estrago que já foi causado, mas, se o líder deles for morto, pode ser que não piorem ainda mais.$B$BVá para o leste de novo, além de onde você encontrou o caldeirão. O Chefe Supremo Invernoso está lá no extremo leste do Posto Presamatos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Bruna Covaneve em Hibérnia.', 0),
(28471, 'ptBR', 'A peça final', 'Leve o Registro Escrito Grosseiramente à Bruna Covaneve em Hibérnia.', 'O registro que você encontrou com o grande chefe parece ser detalhado, porém, após folhear algumas páginas, você percebe que não consegue ler o texto. As marcações são tão grosseiras e garranchadas que não dá para saber se há alguém capaz de lê-las.$B$BTalvez a Bruna consiga decifrar o que está escrito...', '', '', '', '', '', '', '', '', '', '', 0),
(28472, 'ptBR', 'Palavras do Chefe Supremo', 'Leve o Registro Escrito Grosseiramente para Kelek Guardacéus no Lago Kel\'Theril.', 'Os invernosos não são mais uma ameaça, mas acho que você deveria falar com Kelek Guardacéus se ainda quiser descobrir por que os pelursos estavam fazendo e consumindo aquela aguardente estranha.$B$BEle é um druida que já trabalhou com o Círculo Esmeraldino para ajudar a purificar a Selva Maleva, e veio aqui estudar as ruínas próximas.$B$BEle está ao leste, no Lago Kel\'theril, onde tem passado o tempo.', '', '', '', '', '', '', '', '', '', '', 0),
(28473, 'ptBR', 'Armas das trevas', 'Consiga 5 Armas Imbuídas em Poder Elemental dos anões Furiadastra no Abismo Rocha Negra. Depois, quebre-as na Bigorna Negra da Cidade de Umbraforja.', 'Embora o Abismo Rocha Negra tenha servido de lar para nossos inimigos há muito tempo, a Mão Despedaçada nos informou que os Ferro Negro e o Martelo do Crepúsculo vêm se fortalecendo cada vez mais. Com a ajuda dos conhecimentos do culto, os anões Ferro Negro estão imbuindo as próprias armas em poder elemental, transformando-as em verdadeiros pesadelos. E, pior que isso, estão equipando também a legião do Furiadastra.$B$BPreciso que você vá ao Abismo Rocha Negra e colete as armas dos anões do Furiadastra. Quebre-as na Bigorna Negra, no coração da Cidade de Umbraforja.', '', 'Armas Imbuídas em Poder Elemental quebradas', '', '', '', '', '', '', '', 'Fale novamente com o Mestre Pyreanor no Castelo Grommash, em Orgrimmar.', 0),
(28474, 'ptBR', 'Intriga crepuscular', 'Use a Tocha Brilhante para destruir 8 cópias do "A Doutrina do Crepúsculo", no Domicílio do Abismo Rocha Negra.', 'A influência do Martelo do Crepúsculo cresce cada vez mais no Abismo Rocha Negra. Eles se juntaram aos anões Ferro Negro e estão convencendo-os a saírem da montanha para um ataque em conjunto.$B$BPrecisamos acabar com essa algazarra criada pelo Martelo do Crepúsculo.$B$BQuero que você vá até o Domicílio do Abismo Rocha Negra e use esta tocha para queimar os livros que o Martelo do Crepúsculo está distribuindo por lá.', '', 'Cópias de "A Doutrina do Crepúsculo" queimadas', '', '', '', '', '', '', '', 'Fale com a Clériga das Trevas Cecille no Castelo Grommash, que fica no Vale da Força de Orgrimmar.', 0),
(28475, 'ptBR', 'Intriga crepuscular', 'Use a Tocha Brilhante para destruir 8 cópias do "A Doutrina do Crepúsculo", no Domicílio do Abismo Rocha Negra.', 'No Abismo Rocha Negra, o Martelo do Crepúsculo está persuadindo os anões Ferro Negro a se unirem aos exércitos deles, com o intuito de saírem em campanha fora das montanhas.$B$BNão podemos permitir que eles criem algo como o Martelo do Ferro Negro Crepuscular! Precisamos destruir as ferramentas com o qual o culto está utilizando para manipular aqueles anões.$B$BQuero que você vá até o Domicílio do Abismo Rocha Negra e use esta tocha para queimar os livros que o Martelo do Crepúsculo está distribuindo por lá.', '', 'Cópias de "A Doutrina do Crepúsculo" queimadas', '', '', '', '', '', '', '', 'Fale novamente com Tyelis no Castelo Grommash, que fica em Orgrimmar.', 0),
(28476, 'ptBR', 'Intriga crepuscular', 'Use a Tocha Brilhante para destruir 8 cópias do "A Doutrina do Crepúsculo", no Domicílio do Abismo Rocha Negra.', 'O Martelo do Crepúsculo está persuadindo os anões Ferro Negro do Abismo Rocha Negra a se juntarem aos exércitos deles para saírem em uma campanha de dominação.$B$BPrecisamos agir antes que os sectários despertem a sede por sangue dos Ferro Negro e de seus líderes. Talvez a melhor maneira seja destruir os materiais que os sectários estão distribuindo para os anões.$B$BQuero que você vá até o setor do Domicílio do Abismo Rocha Negra e use esta tocha para queimar os livros que o Martelo do Crepúsculo está entregando por lá.', '', 'Cópias de "A Doutrina do Crepúsculo" queimadas', '', '', '', '', '', '', '', 'Fale novamente com a Vidente Liwatha no Vale da Sabedoria, em Orgrimmar.', 0),
(28477, 'ptBR', 'Intriga crepuscular', 'Use a Tocha Brilhante para destruir 8 cópias do "A Doutrina do Crepúsculo", no Domicílio do Abismo Rocha Negra.', 'Nossos inimigos tão de conchavo lá no Abismo Rocha Negra. O pessoal do Martelo do Crepúsculo tá distribuindo uns livros pra galera do Ferro Negro, dizendo que tá na hora da guerra. Se o Martelo tiver um exército Ferro Negro como aliado, vai dar problema pro nosso lado! Temos que dar um jeito nesses badernistas!$B$BSeguinte: tu vai até o Domicílio do Abismo Rocha Negra e usa essa tocha aqui pra tacar fogo nos livros do Martelo do Crepúsculo, tá certo?', '', 'Cópias de "A Doutrina do Crepúsculo" queimadas', '', '', '', '', '', '', '', 'Fale novamente com o Andarilho das Sombras Zuru no Vale dos Espíritos, em Orgrimmar.', 0),
(28478, 'ptBR', 'Intriga crepuscular', 'Use a Tocha Brilhante para destruir 8 cópias do "A Doutrina do Crepúsculo", no Domicílio do Abismo Rocha Negra.', 'Pra quê só despedaçar o mundo se dá pra fazer muito pior, né?! O Martelo do Crepúsculo tá fazendo de tudo pra juntar tudo quanto é inimigo nosso contra a gente, principalmente lá no Abismo Rocha Negra. Tem uma cambada de emissários espalhando propaganda militar, propondo uma campanha em conjunto.$B$BBem... sempre ouvi dizer que o meio é a mensagem. Então tá na hora de acabar com essa mensagem!$B$BPreciso que você vá ao Domicílio do Abismo Rocha Negra e use esta tocha pra tacar fogo nos livros do Martelo do Crepúsculo.', '', 'Cópias de "A Doutrina do Crepúsculo" queimadas', '', '', '', '', '', '', '', 'Fale novamente com o Irmão Pratassacra no Beco do Goblin, que fica em Orgrimmar.', 0),
(28479, 'ptBR', 'Ruínas de Kel\'Theril', 'Fale com o Espírito Kaldorei no Lago Kel\'theril, em Hibérnia.', 'O Cristal de Zin-Malor foi roubado deste lago pelos Altaneiros. O cristal era um artefato poderoso que controlava a magia arcana de maneira violenta e imprevisível... mas só podia ser usado por seres valorosos, e acabou trazendo grande destruição para todos.$B$BOs espíritos que vagam por aqui são de várias gerações, cada um deles agrilhoados a esta terra por Zin-Malor. Alguns deles até falam, e nos contam sobre o destino que tiveram.$B$BSe quiser saber mais sobre o destino de Zin-Malor, procure o espírito no centro do lago...', '', '', '', '', '', '', '', '', '', '', 0),
(28480, 'ptBR', 'Tenentes das trevas', 'Mate o Lorde-escorpião Namkhare e o Sumo Sacerdote Sekhemet.', 'Os exércitos de Ramkahen estão sendo dizimados pelos guardiões imortais de Neferset.$B$BA única forma de derrotá-los é matando o Faraó das Trevas de Neferset.$B$BMas, antes de partir, precisamos cuidar de seus tenentes.$B$BVá por trás das linhas de batalha e mate o lorde-escorpião Namkhare e o sumo sacerdote Sekhemet. Somente então estaremos preparados para combater o Faraó das Trevas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Rei Phaoris nos Arredores da Cidade dos Neferset em Uldum.', 0),
(28482, 'ptBR', 'O presente de Sullah', 'Fale com Harrison Jones no Precipício do Peregrino.', 'O Jones me disse que vocês dois precisam subir aquela montanha.$b$bBem, vocês não vão longe com aqueles soldados rastejando por todo canto feito formigas em uma carcaça.$b$bAlguns dos meus aliados conseguiram confiscar um pouco do equipamento do inimigo.$b$bSubam até o alto das montanhas ao norte e vocês encontrarão eles esperando por vocês.$b$bBoa sorte, $grapazes:pessoal;!', '', '', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Precipício do Peregrino.', 0),
(28483, 'ptBR', 'Dando um banho de sangue no inimigo', 'Pegue 10 Insígnias de Neferset.', 'Não mentirei a você, $n. Temos um enorme desafio à nossa frente.$B$BQuando você for para trás das linhas inimigas na Cidade dos Neferset, quero que traga as insígnias da escória que derrotar.$B$BSerá uma bênção para nossos exércitos saber que você esmagou o inimigo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Rei Phaoris nos Arredores da Cidade dos Neferset em Uldum.', 0),
(28484, 'ptBR', 'O cerne da questão', 'Colete 12 Corações Pulsantes de Yetis.', 'O mago ficou ocioso por tempo demais, e um mago ocioso muitas vezes não consegue planejar direito. Agora estou encarregado de coletar vários órgãos de feras para aumentar o poder de uma espécie de bastão controlador. Sou muito frágil para caçar feras - especialmente yetis!$B$BQuem sabe, se lhe recompensarmos, você possa fazê-lo? Tudo que preciso é que você siga para as cavernas dos yetis a oeste e os mate. Arranque os corações pulsantes dos peitos deles e traga-os a mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Guardião Bel\'varão na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28485, 'ptBR', 'Yetimus, o Senhor dos Yetis', 'Pegue o Chifre Retorcido de Yetimus.', 'Durante anos foi permitido um reinado livre aos yetis das montanhas. Nossa complacência ao lidar com a ameaça yeti resultou em uma aberração. Yetimus, o senhor dos yetis, atingiu tamanho e força com os quais nossa guarda não consegue lidar. Tememos que seu apetite voraz o leve à Serraria Tarren para nos devorar.$B$BReúna uma equipe de aventureiros e dê cabo da fera. Ela vaga pelos campos a oeste.$B$BTraga-me um de seus chifres retorcidos e lhe daremos uma bela recompensa.', '', '', '', '', '', '', 'Yetimus', '', '', 'Volte com o Chifre Retorcido de Yetimus ao Necroguarda Sandoval na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28486, 'ptBR', 'Gambito de Sal-het', 'Escolte o Capitão-patrulheiro de Ramkahen durante a subida da montanha.', 'A Cidade dos Neferset está muito bem defendida. A montanha próxima a ela, no entanto, não está.$B$BFalei com o Capitão-patrulheiro e ele está disposto a colocar alguns de seus homens para conquistar o ponto estratégico.$B$BNão há erro, $n. Ele concordou, desde que você os lidere no ataque.$B$BDeverá ser um pequeno grupo. Do contrário, chamaríamos a atenção dos inimigos muito cedo. Mas confie em mim... os patrulheiros de Ramkahen são durões. Tendo você ao lado, eles sairão vencedores.', '', 'Topo da montanha assegurado', '', '', '', '', '', '', '', 'Fale novamente com Sal-het nos Arredores da Cidade dos Neferset, em Uldum.', 0),
(28487, 'ptBR', 'Os problemas pessoais de Humberto', 'Recupere a Espada, o Elmo e as Calças de Humberto.', 'Isso é bastante constrangedor. Por onde começar?$B$BBem, veja só, Melissara ordenou que eu investigasse a ameaça yeti próximo às cavernas, a oeste daqui. Estava ficando tarde e minha armadura pesava muito. Retirei-a e resolvi dar uma voltinha. Quando voltei, descobri que meus pertences haviam sido roubados! Foram os yetis, tenho certeza. Eles levaram minhas calças, espada e elmo, e fugiram para a caverna deles. Recupere-os para mim e lhe darei uma recompensa.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Necroguarda Humberto na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28488, 'ptBR', 'Abaixo da superfície', 'Colete uma Drusa Gigante de Rubi.', 'Entre as pedras preciosas que estão escondidas fora de alcance nos Abismos Esfacelados, há enormes drusas de rubi. Elas contêm energias terríveis.$B$BNão será fácil coletar tal gema, pois são bem vigiadas. Mas você é $Gcorajoso:corajosa; e $Gteimoso:teimosa;. Acho que consegue.$B$BDe dentro dos Abismos Esfacelados, procure o local onde os túneis terminam abruptamente em rocha. As drusas afloram nessas passagens, quando afloram. Se você encontrar uma, traga-a para mim.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Felsen, o Perene, no Trono de Therazane, que fica no Geodomo.', 0),
(28489, 'ptBR', 'Sanduíche-iche', 'Traga 8 peças de Carne de Cervo.', 'Já provou um sanduíche-iche? Nem eu. Parece que são deliciosos. Não sou muito de comer, mas sou um empresário. Se meus clientes querem sanduíche-iches, quem sou eu para questionar?$B$BVocê deve estar se perguntando: "Sim, mas o que isso tem a ver comigo?". É o seguinte: preciso dessa carne! Traga-me carne de cervo de Eira dos Montes e lhe pagarei. Parece um bom negócio, não?$B$BVá então! Há cervos de montão a oeste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Derak Vindanoite na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28490, 'ptBR', 'O chamado ao heroísmo! Costa Negra!', 'Apresente-se à Sacerdotisa Dantaria em Lor\'danel, na Costa Negra.', 'Por ordem de Sua Majestade, o Rei Varian Wrynn, todos os cidadãos em bom estado físico da Aliança devem se apresentar à Sacerdotisa Dantaria, em Lor\'danel, na Costa Negra.$B$BO povo de Lor\'danel precisa de ajuda para cuidar dos sobreviventes da destruição de Auberdine e defender a cidade do Martelo do Crepúsculo. Fale como Vesprystus, o mestre de hipogrifos da Vila de Rut\'theran, na saída de Darnassus, e ele proverá um voo para a Costa Negra.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28491, 'ptBR', 'Vaga-lumes não, moscas-lume!', 'Capture 7 Moscas-lume.', 'A maioria dos meus colegas que moravam aqui no Monte Candente caíram fora em algum momento. Acho que as Estepes Ardentes não eram INTERESSANTES o suficiente pra eles.$B$BMas comigo é diferente. Eu sempre encontro um novo motivo pra não vazar daqui. O último são as moscas-lume que têm aparecido.$B$BElas aparecem perto da lava durante o dia. À noite, você vê as bichinhas em quase tudo que é lugar.$B$BSe você apanhar algumas, pode ser que eu faça seu trabalho valer a pena.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Kibler no Monte Candente, que fica nas Estepes Ardentes.', 0),
(28492, 'ptBR', 'O chamado ao heroísmo: Vale Gris!', 'Apresente-se à Sentinela Shyela no Retiro de Orendil, que fica na região noroeste do Vale Gris.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em bom estado físico devem se apresentar à sentinela Shyela no Retiro de Orendil, na região noroeste do Vale Gris.$B$BA ofensiva da Horda no Vale Gris não pode continuar! Precisamos da sua ajuda para expulsar os invasores e retomar a floresta sagrada. Para chegar lá, siga em direção ao sul, atravessando o Vale do Crepúsculo, na Costa Negra.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28493, 'ptBR', 'Ordens do Chefe Guerreiro: Vale Gris!', 'Apresente-se a Kadrak na Paliçada Mor\'shan, que fica entre os Sertões Setentrionais e o Vale Gris.', 'Todos os membros da Horda em boas condições físicas estão por meio deste convocados a se apresentar a Kadrak na Paliçada Mor\'shan, que fica na fronteira entre os Sertões Setentrionais e o Vale Gris. Ajude-nos a expulsar os elfos noturnos da floresta para que possamos reivindicar os recursos de lá em nome do nosso povo!$B$BPara chegar à Paliçada Mor\'shan, pegue a Estrada do Ouro em direção ao norte, a partir da Encruzilhada, nos Sertões Setentrionais.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28494, 'ptBR', 'Ordens do Chefe Guerreiro: Sertões Setentrionais!', 'Apresente-se a Kargal Chaga de Guerra no Posto Remoto, que fica nos Sertões Setentrionais.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, intimados a se apresentar a Kargal Chaga de Guerra no Posto Remoto, nos Sertões Setentrionais.$B$BPrecisamos do seu auxílio para defender os Sertões Setentrionais dos centauros e javatuscos invasores.$B$BPara chegar ao Posto Remoto, siga em direção a oeste, atravessando a Bacia Furiaustral, em Durotar, e cruze a ponte que leva aos Sertões Setentrionais.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28495, 'ptBR', 'Uma chance de luta', 'Salve 10 Corços Monteses.', 'Abençoada seja a Luz! Preciso de sua ajuda!$B$BNo caminho para Eira dos Montes, percebi muitas famílias de adoráveis corços. Assim que fui pegar um dos corcinhos para ser meu bichinho de estimação, surgiu do nada um voraz gato montanhês que o matou. Fugi para a Serraria Tarren e jurei resolver a questão dos corços montanheses. Depois de muitos dias matutando, achei a salvação!$B$BTome minha varinha e vá aos campos a oeste, use-a para fortalecer os corços. Uma vez fortalecidos, eles serão capazes de se defender!', '', 'Corços da Colina "salvos"', '', '', '', '', '', '', '', 'Fale com a Conselheira Crepax na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28496, 'ptBR', 'Ordens do Chefe Guerreiro: Azshara!', 'Apresente-se ao Capataz Agárrio no Portão Traseiro de Orgrimmar.', 'Todos os membros da horda em boas condições físicas estão, por meio deste, obrigados a se apresentar a Ag\'tor Punho de Sangue, no Portão Traseiro de Orgrimmar, em Azshara.$B$BAjude a rechaçar as forças da Aliança e também a reivindicar Azshara para glória da Horda!$B$BSaia de Orgrimmar pelo portão norte e se dirija até o Portão Traseiro de Orgrimmar em Azshara.$B$BO Destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28497, 'ptBR', 'Fogo do céu', 'Mate 100 Soldados de Schnottz enquanto estiver montad$go:a; na Artilharia Confiscada.', 'O Sullah não estava brincando. Aquela montanha está infestada por soldados!$b$bSuba a bordo e marque os alvos para mim.$b$bNão perca nenhum tiro, $n! Precisamos chegar lá em cima.', '', 'Soldados de Infantaria de Schnottz mortos', '', '', '', '', '', '', '', 'Fale com Harrison Jones no Precipício do Peregrino.', 0),
(28498, 'ptBR', 'O segredo de Nahom', 'Pegue 8 Fragmentos de Registro de Atul-het.', 'Há uma velha história sobre Nahom. Ela conta como um poderoso profeta chamado Atul-het combateu bandos de inimigos canalizando o poder do sol através deste templo.$B$BMuitos acreditam que isto seja apenas uma lenda, mas o poder... certamente seria útil para nós.$B$BOs vis nefersets saquearam a tumba de Atul-het. Eles pegaram todos os artefatos de poder e quebraram as tábuas que codificam suas memórias.$B$BVá a Tumba dos Antecessores a leste e recupere todos os fragmentos que encontrar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Sal-het em Nahom, que fica em Uldum.', 0),
(28499, 'ptBR', 'Castigo aos invasores', 'Mate 10 Invasores Neferset nas Tumbas dos Antecessores.', 'Nós, sacerdotes de Nahom, somos os guardiões das Tumbas dos Antecessores.$B$BDesde que os neferset começaram a servir a seus novos mestres, cometeram grandes heresias.$B$BEles roubam as tumbas sagradas de nossos antepassados em busca de poderosos artefatos e destroem relíquias inestimáveis.$B$BVá até as tumbas, a leste daqui, e castigue os saqueadores por sua transgressão, para que não se unam a seus irmãos quando o ataque neferset em Nahom começar.', '', 'Intruso Neferset morto', '', '', '', '', '', '', '', 'Fale novamente com o Profeta do Sol Tumet em Nahom, que fica em Uldum.', 0),
(28500, 'ptBR', 'O código de Keset', 'Obtenha o Código de Keset.', '<Sal-het passa algum tempo analisando as tabuletas com os sacerdotes a seu redor.>$B$BEstá tudo bem aqui, $n. Atul-het desenvolveu uma poderosa arma aqui neste templo e a única forma de chegar a ela é usando o código correto.$B$BEsta tal arma está escondida no Desfiladeiro Keset. Vamos esperar que os saqueadores Neferset não tenham chegado até ela ainda. É lá que o Senhor dos saqueadores Havat, o mais cruel de todos eles, está atuando.$B$BMas, sem reforços, esta é nossa única esperança de defender Nahom.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Sal-het em Nahom, que fica em Uldum.', 0),
(28501, 'ptBR', 'Em defesa de Nahom', 'Fale com um Sargento de Ramkahen e defenda Nahom.', 'O inimigo está chegando... e em grande número.$B$BNão teremos mais reforços. Tenhamos fé de que conseguiremos impedir o avanço dos Neferset.$B$BSe Nahom cair, Ramkahen cairá.$B$BVá lá fora e fale com um de meus sargentos quando estiver $Gpreparado:preparada;. Farei o melhor que puder para ajudar você a comandar nossas forças.', 'Em defesa de Nahom', '', '', '', '', 'Em defesa de Nahom', '', '', '', 'Fale novamente com Sal-het em Nahom, que fica em Uldum.', 0),
(28502, 'ptBR', 'O senhor da guerra fora-da-lei', 'Mate o Senhor da Guerra Ihsenn.', 'Nossas leis exigem que os responsáveis pelo ataque tenham a punição devida.$B$BO líder dos bandidos é um homem conhecido como senhor da guerra Ihsenn.$B$BVocê o encontrará a oeste do deserto. Faça com que ele seja punido por sua transgressão.', '', '', '', '', '', '', 'Senhor da Guerra Ihsenn', '', '', 'Fale novamente com o Sacerdote do Sol Asaris no Selo do Rei Sol, em Uldum.', 0),
(28503, 'ptBR', 'O chamado ao heroísmo: Mil Agulhas!', 'Apresente-se a Caryssia Caçaluna em Nova Thalanaar, na fronteira entre Feralas e Mil Agulhas.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem apresentar-se a Caryssia Caçaluna em Nova Thalanaar, na fronteira entre Feralas e Mil Agulhas.$B$BAs sentinelas precisam de sua ajuda para expulsar os saqueadores dos Temível Totem que dominaram a região. Para chegar a Nova Thalanaar, vá para o leste de Feralas, perto da fronteira com Mil Agulhas.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28504, 'ptBR', 'Ordens do Chefe Guerreiro: Mil Agulhas!', 'Apresente-se a Nyse em Coroa de Barro, que fica na parte sul do Pântano Vadeoso.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, obrigados a apresentar-se a Nyse na Coroa de Barro. Junte-se às forças da Horda e enfrente os renegados do Temível Totem que dominaram a área.$B$BNyse lhe providenciará o transporte até a frente de batalha. Ela espera na estalagem de Coroa de Barro, na região sul do Pântano Vadeoso.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28505, 'ptBR', 'A batalha por Andorhal', 'Fale com Guthrum Punhostrondo para voar rumo a Andorhal, que fica nas Terras Pestilentas Ocidentais. Feito isso, apresente-se a Thassarian em Andorhal.', 'Acabei de receber as notícias, $gguri:guria;. Não parecem boas.$b$bA cidade de Andorhal está no meio de uma guerra tríplice entre os Renegados, a Aliança e o Flagelo. O Rei Wrynn deu o primeiro passo ao enviar um cavaleiro da morte para liderar o ataque em prol da causa dele, mas tenho certeza de que toda ajuda será bem-vinda.$b$bDetesto ver você partir, mas ele convocou você pelo nome, $n. Fale com Guthrum Punhostrondo lá fora. Ele colocará você no primeiro grifo a caminho de Andorhal.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(28506, 'ptBR', 'A marcha dos Lançatroz', 'Assista à Marcha dos Lançatroz.', 'Estes planos que você recuperou contam uma história interessante, $n. Os Lançatroz transferiram seus exércitos do Vale Alterac para os "quatro dedos" de Eira dos Montes há mais de um mês. De algum jeito, eles conseguiram montar suas instalações sem que soubéssemos. Se não tivéssemos estes planos em mãos, eles teriam marchado até nós em uma semana, aniquilando tudo em seu caminho.$B$BCom os planos, no entanto, podemos virar a mesa.$B$BFaremos o seguinte...', 'Assista à Marcha dos Lançatroz.', '', '', '', '', 'Assista à Marcha dos Lançatroz.', '', '', '', 'Fale com o Sumo Senhor da Guerra Cromush na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28507, 'ptBR', 'O chamado ao heroísmo: Tanaris!', 'Apresente-se a Kelsey Fagulhaço em Geringontzan, que fica em Tanaris.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem apresentar-se a Kelsey Fagulhaço em Geringontzan.$B$BA Aliança necessita de sua ajuda para ganhar concessões do barão local e acesso aos inestimáveis recursos da área. Você pode chegar a Geringontzan seguindo a estrada sul do Abismo Cintilante, em Mil Agulhas.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28508, 'ptBR', 'A batalha por Andorhal', 'Fale com Alcebíades Patágio para voar rumo a Andorhal, que fica nas Terras Pestilentas Ocidentais. Feito isso, apresente-se a Koltirus Tecemorte em Andorhal.', 'Acabei de receber uma missiva curiosa. Mas curiosa mesmo...$b$bA cidade de Andorhal está no meio de uma guerra tríplice entre os Renegados, a Aliança e o Flagelo. Parece que Sylvana começou a agir e, para deixar as coisas mais interessantes, ela colocou Koltirus Tecemorte, o cavaleiro da morte, no comando.$b$bEles chamaram você pelo nome, $n. Fale com Alcebíades Patágio, o tratador de morcegos. Ele colocará você no primeiro morcego a caminho de Andorhal.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(28509, 'ptBR', 'Ordens do Chefe Guerreiro: Tanaris!', 'Apresente-se a Carlota Tomanota em Geringontzan, que fica em Tanaris.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, convocados a se apresentar a Carlota Tomanota no posto de Geringontzan, em Tanaris. Ajude a Horda e o Cartel Borraquilha a estabelecer a presença em Tanaris antes que a Aliança o faça!$B$BPartindo do Barcódromo do Xabu e do Relé, no sudeste de Mil Agulhas, siga para o sul, em direção à costa, para chegar à Geringontzan.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28510, 'ptBR', 'Ordens do Chefe Guerreiro: Feralas!', 'Fale com Konu Runa Totem na Aldeia Ataya, que fica em Feralas.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, obrigados a apresentar-se a Konu Runa Totem na Aldeia Ataya, em Feralas. Ajude a Horda a proteger a grande floresta contra a Aliança e os Temível Totem.$B$BVocê chega à Aldeia Ataya viajando ao sul, a partir de Desolação, para Feralas.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28511, 'ptBR', 'O chamado ao heroísmo: Feralas!', 'Fale com Telaron Volaventos no Repouso do Sonhador, que fica em Feralas.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem apresentar-se a Telaron Volaventos no Repouso do Sonhador, em Feralas.$B$BA Aliança precisa de sua ajuda para deter o avanço de nossos inimigos: a Horda e os Temível Totem. Você chega no Repouso do Sonhador viajando para o sul, a partir de Desolação, para Feralas.$B$BPela glória e honra da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28512, 'ptBR', 'Em auxílio à Irmandade do Tório', 'Fale com Jack Pernadura no Avanço de Tório, que fica na Garganta Abrasadora.', 'Anões Ferro Negro podem ser maquinadores e maliciosos... mas nem todos são inimigos. Eu conversei várias vezes com os anões da Irmandade do Tório e eles sempre foram muito prestativos.$b$bUm conhecido meu, Jack Pernadura, chegou à cidade há pouco, perguntando se eu gostaria de me juntar a ele em uma expedição. Parecia importante.$b$bEu ando meio ocupado, talvez você possa ir no meu lugar? Basta viajar para o oeste, pela estrada que leva à Garganta Abrasadora. Você o verá logo depois que sair dos Ermos.', '', '', '', '', '', '', '', '', '', '', 0),
(28513, 'ptBR', 'Orgulho dos Altaneiros', 'Mate 8 Altaneiros Sofredores ou Angustiados.', 'Há dez mil anos...$B$BOs Altaneiros viviam aqui em prosperidade. Nós nos considerávamos superiores aos elfos noturnos comuns. A magia e a riqueza satisfaziam todas as nossas necessidades. Levávamos uma vida de gozo e diversão. E ganância...$B$BOs espíritos que você vê aqui estão dominados pelo remorso e arrependimento. É a angústia que os aprisiona aqui. Se quiser aprender mais sobre Kel\'theril e Zin-Malor, liberte-os da agonia.', '', 'Espíritos Altaneiros libertados', '', '', '', '', '', '', '', 'Fale novamente com o Espírito Kaldorei no Lago Kel\'Theril, em Hibérnia.', 0),
(28514, 'ptBR', 'Mouton Flamestrela', 'Apresente-se a Mouton Flamestrela no Posto Flamestrela, que fica nas Estepes Ardentes.', 'Ultimamente, tenho passado pouco tempo longe da Garganta Abrasadora. Já faz meses que quero visitar um amigo nas Estepes Ardentes, mas não tive chance.$b$bO nome dele é Mouton Flamestrela. Se por um lado ele não é membro da Irmandade, ele é um amigo absolutamente confiável.$b$bSerá que você mandaria lembranças minhas para ele? Você terá que viajar para o sul, pela base da Montanha Rocha Negra. Basta continuar seguindo para o sul... E você o encontrará.$b$bObrigado.', '', '', '', '', '', '', '', '', '', '', 0),
(28515, 'ptBR', 'Mouton Flamestrela', 'Apresente-se a Mouton Flamestrela no Posto Flamestrela, que fica nas Estepes Ardentes.', 'Ultimamente, tenho passado pouco tempo longe da Garganta Abrasadora. Já faz meses que quero visitar um amigo nas Estepes Ardentes, mas não tive chance.$b$bO nome dele é Mouton Flamestrela. Se por um lado ele não é membro da Irmandade, ele é um amigo absolutamente confiável.$b$bSerá que você mandaria lembranças minhas para ele? Você terá que viajar para o sul, pela base da Montanha Rocha Negra. Basta continuar seguindo para o sul... E você o encontrará.$b$bObrigado.', '', '', '', '', '', '', '', '', '', '', 0),
(28517, 'ptBR', 'O Carvalho Uivante', 'Fale com Genn Greymane no Carvalho Uivante, que fica em Darnassus.', 'Então é aqui... nosso novo lar. Não sei, talvez eu nunca consiga me sentir em casa novamente.$B$BMas não podemos demonstrar ingratidão pelo que nos ofereceram os elfos noturnos. Não é uma raça que dê boas-vindas a qualquer um. Nossa acolhida é uma verdadeira prova de confiança e generosidade.$B$BGwen e Greymane estão nos limites da cidade, no Carvalho Uivante. Passe por lá e entre no portal ao pé da árvore, a norte daqui. Em seguida procure o Carvalho Uivante na parte norte da cidade.', '', '', '', '', '', '', '', '', '', '', 0),
(28518, 'ptBR', 'Legado dos Elfos Superiores', 'Tome a Memória de Zin-Malor do espírito do Arquimago Maenius.', 'Cem anos atrás...$B$BEu e um pequeno grupo de elfos superiores  saímos de nosso lar, Quel\'thalas, e viemos até aqui. Saímos em busca dos mistérios de Kel\'thoril... queríamos descobrir por que ele fora destruído.$B$BEncontramos fragmentos no gelo, estilhaços do cristal. O arquimago que nos acompanhava logo foi dominado. A nossa ingenuidade fez com que demorássemos a perceber o que acontecia.$B$BO espírito dele vaga a sudeste, junto com aqueles cuja razão ele tomou, ainda agarrado à memória do precioso fragmento...', '', '', '', '', '', '', 'Arquimago Maenius', '', '', 'Fale novamente com o Espírito Quel\'dorei no centro do Lago Kel\'theril, em Hibérnia.', 0),
(28519, 'ptBR', 'Dor dos Elfos Sangrentos', 'Mate 7 Espíritos Miseráveis ou Espectros Miseráveis no Lago Kel\'Theril.', 'Um ano atrás...$B$BA lenda do Cristal de Zin-Malor tornou-se conhecida em Luaprata, e eu liderei um grupo dos melhores guerreiros e eruditos disponíveis até estas terras. Trouxemos vários cristais de mana para que nenhum de nós caísse na tentação de experimentar o cristal maligno.$B$BMas ele sequer precisou do nosso desejo para nos arruinar. Quando estava sob nossa posse, transformou todos os meus companheiros em feras desprezíveis.$B$BAs almas miseráveis ainda vagam em busca de mais vidas para acorrentar a este lago. Você terá piedade de suas almas... ou fugirá, na esperança de algum dia morrer em um local não tão nefasto quanto este?', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Espírito Sin\'dorei no centro do Lago Kel\'theril, em Hibérnia.', 0),
(28520, 'ptBR', 'A queda de Neferset', 'Mate o Faraó das Trevas Tekahn na Cidade dos Neferset em Uldum.', 'Estamos preparados para o ataque agora, $n.$B$BSe derrotarmos o faraó das trevas Tekahn, os colossos imortais sucumbirão e nossos exércitos poderão marchar pela cidade dos Neferset.$B$BProcure-o e elimine-o sem medo. Providenciarei para que não esteja sozinh$go:a; na hora de derrotá-lo.', '', '', '', '', '', '', 'Faraó das Trevas Tekahn', '', '', 'Fale com o Rei Phaoris em Ramkahen, que fica em Uldum.', 0),
(28521, 'ptBR', 'Fale com Salfa', 'Viaje pelo Domínio dos Presamatos até chegar a Hibérnia. Fale com Salfa, que está de guarda em frente à entrada do Domínio dos Presamatos.', 'A ameaça da corrupção não vem apenas dos pelursos Lenha Morta ao sul, mas também do leste e dos pelursos da Hibérnia. Se você deseja continuar nos ajudando, converse com Salfa, que está do outro lado do Domínio, próximo à entrada de Hibérnia. Para chegar lá, siga pelo caminho à esquerda.', '', '', '', '', '', '', '', '', '', '', 0),
(28522, 'ptBR', 'Atividade Invernosa', 'Colete 10 Contas Espirituais dos pelursos Invernosos.', 'Os Presamatos costumam não se misturar muito, $n. Concedemos passagem segura àqueles em quem confiamos, mas procuramos evitar outras tribos de pelursos sempre que possível.$B$BA tribo Invernosa vem se tornando cada vez mais hostil conosco. Parece que estão tomados por uma raiva irracional, completamente mergulhados no próprio medo e ódio de qualquer coisa que não compreendem.$B$BOs Invernosos carregam consigo contas espirituais, que certamente não foram capazes de protegê-los da corrupção. Traga-me 10 dessas contas para provar que você lhes reduziu as tropas.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Salfa em Hibérnia.', 0),
(28523, 'ptBR', 'Mais contas para Salfa', '', '', '', '', '', '', '', '', '', '', '', 'Fale novamente com Salfa na Selva Maleva.', 0),
(28524, 'ptBR', 'Uma entrega para Bruna', 'Entregue a Cesta de Salfa para Bruna Covaneve em Hibérnia.', 'Bruna Covaneve é uma anã que frequenta as fontes termais daqui de perto. Ela afirmou que está estudando as propriedades mágicas das fontes.$B$BÉ uma pessoa gentil e tem um bom relacionamento com nossa tribo. Bruna passou a pesquisar as causas da corrupção dos Invernosos depois que eles começaram a ficar mais e mais agressivos.$B$BNão posso sair do meu posto, mas fiz uma cesta de bebidas para ela. Leve-a para ela e diga que esperamos ansiosos pela próxima visita.', '', '', '', '', '', '', '', '', '', '', 0),
(28525, 'ptBR', 'O chamado ao heroísmo: Cratera Un\'Goro!', 'Fale com Williden Marshal. Você pode encontrá-lo no Posto Avançado do Marshal, que fica na Cratera Un\'Goro.', 'Por ordens de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança fisicamente capazes devem se apresentar a Williden Marshal, no Posto Avançado do Marshal.$B$BA Aliança precisa que você ajude as Expedições Marshal a explorar os segredos da Cratera Un\'Goro, como as feras ancestrais, a flora singular e os poderosos cristais do local. É possível chegar à cratera indo para Tanaris e seguindo a estrada oeste até o Posto Avançado do Marshal.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28526, 'ptBR', 'Ordens do Chefe Guerreiro: Cratera Un\'Goro!', 'Fale com Williden Marshal. Você pode encontrá-lo no Posto Avançado do Marshal, que fica na Cratera Un\'Goro.', 'Pelo presente, ordena-se que todo membro da Horda fisicamente capaz apresente-se a Williden Marshal no Posto Avançado do Marshal. As Expedições Marshal precisam de ajuda para descobrir os segredos da Cratera Un\'Goro. É possível que a Horda se beneficie dos cristais e das feras únicas que habitam o local.$B$BÉ possível chegar até a cratera e ao Posto Avançado do Marshal seguindo a estrada a oeste de Tanaris.$B$BSeu destino o aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28527, 'ptBR', 'Ordens do Chefe Guerreiro: Silithus!', 'Apresente-se à Arauto do Vento Chifre Altivo no Forte Cenariano, em Silithus.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, obrigados a apresentar-se à Arauto do Vento Chifre Altivo no Forte Cenariano. Todos deverão ajudar nossos aliados cenarianos em sua batalha para expulsar o Martelo do Crepúsculo. Não podemos permitir que os lacaios de Cho\'Gall dominem Silithus!$B$BVocê pode chegar a Silithus seguindo a estrada noroeste que sai da Cratera Un\'Goro.$B$BO destino os chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28528, 'ptBR', 'O chamado ao heroísmo: Silithus!', 'Apresente-se à Arauto do Vento Chifre Altivo no Forte Cenariano, em Silithus.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em bom estado físico devem apresentar-se à Arauto do Vento Chifre Altivo no Forte Cenariano.$B$BNossos aliados do Círculo Cenariano precisam de sua ajuda para combater o massacre causado pelo Martelo do Crepúsculo. Você pode chegar a Silithus seguindo a estrada noroeste que sai da Cratera Un\'Goro.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28529, 'ptBR', 'As escrituras do Caos', 'Leve as Escrituras do Arauto Negro à Patrulheira Glynda Nal\'Shea em Lor\'danel.', 'Os pergaminhos são vagos e parecem fazer parte de um enigma muito maior, a menos que você esteja $Genganado:enganada;, eles revelam os primeiros passos para se tornar um caçador de demônios.$B$BOs rituais e juramentos sombrios para se tornar um caçador de demônios são reprovados pela maioria dos elfos noturnos, então é bem provável que desejem manter isso em segredo.$B$BA patrulheira Glynda Nal\'Shea saberá o que fazer com os pergaminhos.', '', '', '', '', '', '', '', '', '', '', 0),
(28530, 'ptBR', 'Sinais escaldantes', 'Colete 7 porções de Lodo Verde Suspeito de Surtermais Escaldantes ou Bolhescaldantes Termais.', 'Parece que havia material concentrado dentro do caldeirão. Se os invernosos estão diluindo essa coisa diretamente nas fontes, a contaminação vai se acumular com o tempo... e depois a diluição perderia a eficácia cada vez mais.$B$BA fonte a nordeste está infestada de elementais. Pensei que fosse por causa do cataclismo, mas a aparição deles pode ser uma reação a isto aqui.$B$BSerá que você poderia ir lá dar uma olhada para ver se há corrupção? Cace alguns deles e me traga quaisquer pedaços de material estranho verde que deixarem para trás.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Bruna Covaneve nas Fontes Termais de Fogofrio, em Hibérnia.', 0),
(28531, 'ptBR', 'O chamado ao heroísmo: Desolação!', 'Apresente-se à Oficial Matilde em Tethris Aran, que fica em Desolação.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar à oficial Matilde em Tethris Aran.$B$BOs bravos soldados do Posto do Nijel foram cercados por demônios e tropas da Horda e precisam da sua ajuda. Para chegar a Desolação, siga em direção ao sul, pela estrada que sai do Vale Carbonizado, na Cordilheira das Torres de Pedra.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28532, 'ptBR', 'Ordens do Chefe Guerreiro: Cordilheira das Torres de Pedra!', 'Apresente-se ao Guarda-de-Sangue Aldo Chovepedra no Refúgio Brisaprata, que fica no Vale Gris.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, obrigados a apresentar-se ao Guarda-de-Sangue Aldo Chovepedra no Refúgio Brisaprata, que fica no Vale Gris. As forças da Horda nas Torres de Pedra precisam de sua ajuda para rechaçar a invasão da Aliança e proteger nosso povo. O Guarda-de-Sangue vai direcionar você à fronteira das Torres de Pedra.$B$BPara chegar ao Refúgio Brisaprata, viaje até o coração do Vale Gris e junte-se às nossas forças perto do lago.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28533, 'ptBR', 'A decisão do Alto Conselho', 'Fale com o Rei Phaoris em Ramkahen, que fica em Uldum.', 'O Alto Conselho está pronto para deliberar sobre a guerra com a tribo neferset.', '', '', '', '', '', '', '', '', '', '', 0),
(28534, 'ptBR', 'Descendentes dos Altaneiros', 'Fale com o Espírito Quel\'dorei.', 'Não muito depois de minha morte, a ganância do meu povo fez com que fossem forçados ao exílio. No outro continente, eles se tornaram Quel\'dorei, os Elfos Superiores. Em Quel\'thalas, eles se banharam no poder da Nascente do Sol e se esqueceram do legado de desejo e ganância.$B$BEsses descendentes distantes voltaram aqui, atraídos pelo destino, condenados a repetir o passado. Ouça a história deles, assim como eu já fiz...', '', '', '', '', '', '', '', '', '', '', 0),
(28535, 'ptBR', 'Descendentes dos Elfos Superiores', 'Fale com o Espírito Sin\'dorei.', 'Pouco depois da minha morte, meu povo cometeu um erro ainda mais grave. Os Elfos Superiores dependiam da Nascente do Sol e da sua glória. Eram incapazes de imaginar um mundo em que não mais houvesse a Nascente, e portanto não se prepararam para eventualidade.$B$BMais tarde, quando a Nascente do Sol caiu ante as hostes de mortos-vivos, meus descentes restantes ficaram perdidos e desamparados... E o caminho que decidiram trilhar os mudou para sempre.$B$BOs Sin\'dorei, ainda em busca da redenção, também voltaram aqui...', '', '', '', '', '', '', '', '', '', '', 0),
(28536, 'ptBR', 'A maldição de Zin-Malor', 'Fale novamente com Kelek Guardacéus no Lago Kel\'theril, em Hibérnia.', 'Você já viu o bastante. Saiba que o Cristal de Zin-Malor traz somente a ruína para todos aqueles que dele se aproximam.$B$BVá embora daqui se não desejar se juntar a nós.', '', '', '', '', '', '', '', '', '', '', 0),
(28537, 'ptBR', 'Em busca dos vultos', 'Siga e mate o Vulto do Médium e obtenha quaisquer evidências do mestre dele.', 'Está dizendo que ele falou de um mestre? De alguém que possui Zin-Malor?$B$BIsso é muito grave. Você precisa agir, $c! Eu vi o vulto voar em direção ao sul. Siga o caminho que leva às ruínas superiores, e pode ser que você consiga escalar a cachoeira congelada que fica logo atrás!$B$BE não baixe a guarda... O vulto pode estar à sua espera.', '', '', '', '', '', '', 'Vulto do Médium', '', '', 'Fale novamente com Kelek Guardacéus no Lago Kel\'theril, em Hibérnia.', 0),
(28538, 'ptBR', 'O lamento da Banshee', 'Use o Espelho da Banshee para capturar 10 Agentes da AVIN.', 'Então você será noss$Go:a; salvado$Gr:ra;? Muito bem então, me unirei a você. Com esta união, poderei ver através de seus olhos e me comunicar consigo no campo.$B$BDe acordo com os planos que você trouxe, os Lançatroz conseguiram ajuda da AVIN no Promontório de Sofera, ao norte. A AVIN é composta exclusivamente de humanos – humanos que podemos usar em nosso benefício.$B$BTome meu espelho e siga para o norte. Entre na luta contra a AVIN e deixe seus agentes à beira da morte. Uma vez feridos, use o espelho.', '', 'Agentes da AVIN capturados', '', '', '', '', '', 'Há muito mais trabalho a ser feito. Não seja complacente.', 'Melissara', 'Fale com Melissara na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28539, 'ptBR', 'O chamado ao heroísmo: Cordilheira das Torres de Pedra!', 'Apresente-se à Caçadora Jalin na Torre Poeira Estelar, que fica na fronteira entre o Vale Gris e a Cordilheira das Torres de Pedra.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em bom estado físico devem apresentar-se à Caçadora Jalin na Torre Poeira Estelar, que fica no Vale Gris.$B$BAs forças da Horda estão a postos para invadir as Torres de Pedra e precisam ser combatidas! Você consegue chegar à Torre Poeira Estelar viajando até o sudeste da Floresta do Vale Gris, perto da fronteira com as Torres de Pedra.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28540, 'ptBR', 'Pediu pra ser mágico no vale do E\'ko', 'Obtenha o Coração de Pele Gélida.', 'A Mau\'ari fabrica amuletos dos espíritos das terras selvagens já faz um montão de anos. Ela simplesmente ARRANCA o E\'ko dos animais e faz amuletos pras crianças e pros aventureiros.$b$bLá pro leste tem um monte altão cercado pelos ursos dentilhaços. O Pele Gélida é o urso mais véio da floresta, e tá lá em cima do morro.$B$BA Mau\'ari precisa dele pra fazer magia. Vai lá e me traz lá o coraçãozão véio daquele urso.', '', '', '', '', '', '', '', '', '', 'Fale novamente com a Mandingueira Mau\'ari no oeste de Hibérnia.', 0),
(28542, 'ptBR', 'Ordens do Chefe Guerreiro: Selva Maleva!', 'Apresente-se a Tenell Velifrondes no Santuário Esmeralda, que fica na Selva Maleva.', 'Todos os membros da Horda em bom estado físico devem apresentar-se a Tenell Velifrondes no Santuário Esmeralda, na Selva Maleva. O Círculo Cenariano requer seu auxílio para libertar a Selva Maleva do controle de demônios e outras criaturas corrompidas!$B$BPara chegar ao Santuário Esmeralda, viaje para o norte do Vale Gris e siga a estrada.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28543, 'ptBR', 'O chamado ao heroísmo: Selva Maleva!', 'Apresente-se a Tenell Velifrondes no Santuário Esmeralda, que fica na Selva Maleva.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em bom estado físico devem apresentar-se a Tenell Velifrondes no Santuário Esmeralda.$B$BEle solicita o seu auxílio para libertar a Selva Maleva das influências demoníacas. Para chegar ao Santuário Esmeralda, vá para o norte do Vale Gris e siga pela estrada para Selva Maleva.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28544, 'ptBR', 'O chamado ao heroísmo: Hibérnia!', 'Apresente-se a Bruna Covaneve nas Fontes Termais de Fogofrio, em Hibérnia.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em bom estado físico devem apresentar-se a Bruna Covaneve nas Fontes Termais de Fogofrio.$B$BEla precisa de ajuda para superar a ameaça dos pelursos Invernosos. Para chegar a Hibérnia, cruze a Selva Maleva na direção leste e atravesse o Domínio dos Presamatos.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28545, 'ptBR', 'Ordens do Chefe Guerreiro: Hibérnia!', 'Apresente-se a Bruna Covaneve nas Fontes Termais de Fogofrio, que ficam na Hibérnia.', 'Todos os membros da horda em boas condições físicas estão, por meio deste, obrigados a se apresentar a Bruna Covaneve nas Fontes Termais de Fogofrio. As coisas que ela descobriu sobre os pelursos invernosos podem ser a chave para resolver o problema de uma vez por todas.$B$BPara chegar às Fontes Termais de Fogofrio, em Hibérnia, cruze a Selva Maleva na direção leste e atravesse o Domínio dos Presamatos.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Objectives`, `Details`, `EndText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `QuestGiverTextWindow`, `QuestGiverTargetName`, `QuestTurnTextWindow`, `QuestTurnTargetName`, `CompletedText`, `VerifiedBuild`) VALUES
(28548, 'ptBR', 'Ordens do Chefe Guerreiro: Desolação!', 'Apresente-se a Furien em Tethris Aran, que fica em Desolação.', 'Todos os membros da Horda em boas condições físicas estão por meio deste convocados a se apresentar a Furien, em Tethris Aran, que fica em Desolação, onde os bravos soldados da Horda precisam da sua ajuda para deter exércitos da Aliança e demônios ancestrais.$B$BPara chegar a Tethris Aran, siga para o sul, partindo do Vale Carbonizado, que fica na Cordilheira das Torres de Pedra.$B$BAtenda ao chamado do destino!', '', '', '', '', '', '', '', '', '', '', 0),
(28549, 'ptBR', 'Ordens do Chefe Guerreiro: Sertões Meridionais!', 'Apresente-se a Nura Caminheira na Estrada Alta, que fica nos Sertões Meridionais.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, intimados a se apresentar a Nura Caminheira na Estrada Alta, que fica nos Sertões Meridionais. Com as recentes vitórias da Aliança nos Sertões, nossos inimigos ameaçam cortar nossas rotas de suprimento, deixando nossos guerreiros isolados. Precisamos agir!$B$BPara chegar à Estrada Alta, siga para o leste, saindo da Cordilheira das Torres de Pedra.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28550, 'ptBR', 'O chamado ao heroísmo: Sertões Meridionais!', 'Apresente-se ao Comandante Walpole no Desfiladeiro das Torres de Pedra, que fica na parte noroeste dos Sertões Meridionais.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar ao Comandante Walpole no Desfiladeiro das Torres de Pedra.$B$BNossos bravos soldados fizeram um tremendo progresso nos Sertões, mas pagaram um alto preço por isso! Seus esforços são necessários para consolidar nossa vitória. Para chegar aos Sertões Meridionais a partir da Cordilheira das Torres de Pedra, siga em direção ao sudeste, atravessando o Vale Matagrande.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28551, 'ptBR', 'O chamado ao heroísmo: Sertões Meridionais!', 'Apresente-se ao Mestre de Doca Lewis nas docas perto da Fortaleza da Guardanorte, que fica nos Sertões Meridionais.', 'Por ordem de Sua Majestade o rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar ao Mestre de Doca Lewis perto da Fortaleza da Guardanorte.$B$BNossos bravos soldados fizeram um tremendo progresso nos Sertões, mas pagaram um alto preço por isso. Seus esforços são necessários para consolidar nossa vitória! Para chegar às docas da Fortaleza da Guardanorte, pegue um barco na Angra do Butim até a Vila Catraca e depois siga em direção ao sul, pela costa.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28552, 'ptBR', 'O chamado ao heroísmo: Pântano Vadeoso!', 'Apresente-se a Calia Hastings na Ilha Theramore, que fica no Pântano Vadeoso.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem apresentar-se a Calia Hastings na Ilha Theramore.$B$BOs heróis ajudarão a AVIN a farejar as ameaças externas, assim como as que se escondem entre os muros de Theramore. Pode-se chegar à Ilha Theramore tomando o barco a partir de Menethil ou atravessando o pântano a leste dos Sertões Meridionais.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28553, 'ptBR', 'Okrilla e a Barreira do Inferno', 'Apresente-se a Okrilla no Domínio de Malhorrendo, que fica na Barreira do Inferno.', 'Tenho uma última missão para você, $n. As ordens vêm do Domínio de Malhorrendo, ao sul, na Barreira do Inferno.$b$bA matriarca-de-guerra Okrilla está travando uma batalha contra as forças da Aliança da Bastilha de Etergarde, e ela precisa da assistência de $gum:uma; $c vigoros$go:a;. Você me veio à mente de imediato.$b$bViaje para o sul, Barreira do Inferno adentro, e depois, siga para oeste. Boa sorte, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(28554, 'ptBR', 'Ordens do Chefe Guerreiro: Pântano Vadeoso!', 'Apresente-se a Krog na Aldeia Muralha Verde, que fica no Pântano Vadeoso.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, obrigados a apresentar-se a Krog na Aldeia Muralha Verde. O pântano está coberto de toda espécie de inimigos e as forças da Aliança alcançaram níveis perigosos de poder.$B$BPode-se chegar ao Pântano Vadeoso seguindo o caminho na porção leste dos Sertões Meridionais, em direção à Aldeia Muralha Verde.$B$BO destino os chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28556, 'ptBR', 'Quebrando a mão', 'Coloque uma Bomba Goblin no Promontório de Sofera, na Adaga de Corrahn, em Terralta e no Promontório de Gavin.', 'Devemos quebrar os dedos dos Lançatroz se quisermos detê-los.$B$B<Cromush lhe entrega um pequeno pacote.>$B$BDentro do pacote há quatro explosivos de alta-devastação dos goblins. Você se infiltrará em cada um dos dedos - Promontório de Sofera, Adaga de Corrahn, Terralta e Promontório de Gavin - e colocará uma bomba em cada.$B$BUma vez feito isso - e atendidos todos os pedidos de Melissara - volte até mim.', '', 'Ogiva armada no Promontório de Sofera', 'Ogiva armada na Adaga de Corrahn', 'Ogiva armada no Promontório', 'Ogiva armada no Promontório de Gavin', '', '', '', '', 'Fale novamente com o Sumo Senhor da Guerra Cromush na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28557, 'ptBR', 'Ordens do Chefe Guerreiro: Uldum!', 'Fale com Adarrah no Vale Moitagulhas, que fica na região oeste de Tanaris.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, intimados a se apresentar a Adarrah no Vale Moitagulhas em Tanaris.$B$BTextos antigos nos contam que Uldum é o lar de riquezas e tesouros incomparáveis. Vá e reivindique essas riquezas em nome da Horda!$B$BVocê pode chegar à caravana de Adarrah seguindo para a parte sudoeste de Tanaris. Adarrah está no Vale Moitagulhas.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28558, 'ptBR', 'O chamado ao heroísmo: Uldum!', 'Fale com Adarrah no Vale Moitagulhas, em Tanaris.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar a Adarrah no Vale Moitagulhas em Tanaris.$B$BSeja um dos primeiros a adentrar na gloriosa Uldum e a reivindicar seus tesouros em honra da Aliança!$B$BVocê pode chegar à caravana de Adarrah seguindo para os confins ocidentais de Tanaris.$B$BPela glória e honra da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28559, 'ptBR', 'O chamado ao heroísmo: Ilha Névoa Rubra!', 'Apresente-se a Vorkhan, o Pastor de Elekks, na Travessia de Kessel, que fica na Ilha Névoa Rubra.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar a Vorkhan, o Pastor de Elekks, na Travessia de Kessel.$B$BO povo da Névoa Rubra precisa da sua ajuda para lidar com traiçoeiros elfos sangrentos e outras criaturas perigosas à solta pela ilha. Chega-se à Travessia de Kessel, na Ilha Névoa Rubra, pela ponte a norte da Ilha Névoa Lazúli.$B$BPela glória e honra da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28560, 'ptBR', 'Ordens do Chefe Guerreiro: A Terra Fantasma!', 'Apresente-se ao Arcanista Vandril em Tranquillien, que fica na Terra Fantasma.', 'Todos os membros da Horda em boas condições físicas são por este obrigados a apresentar-se ao Arcanista Vandril em Tranquillien, na Terra Fantasma.$B$BSua ajuda é necessária para rechaçar os inúmeros invasores do Flagelo e garantir a ajuda dos Renegados para combater nosso inimigo comum.$B$BPara chegar a Tranquillien, siga a estrada ao sul da Praça Brisamena até chegar à Terra Fantasma.$B$BO Destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28561, 'ptBR', 'Nahom deve resistir', 'Apresente-se à guarnição em Nahom, que fica em Uldum.', 'Assim que formos a oeste para atacar a cidade dos neferset, o inimigo nos atacará pelo leste, onde estaremos em desvantagem.$B$BNahom será a primeira a cair e, se isso acontecer, Ramkahen terá destino igual.$B$BUma pequena guarnição já está lá.$B$BObtenha informações dela. Quero que se assegure de que eles defendam Nahom até eu enviar mais tropas.', '', '', '', '', '', '', '', '', '', '', 0),
(28562, 'ptBR', 'O chamado ao heroísmo: Cerro Oeste!', 'Apresente-se ao Tenente Horatio Laine no Sítio dos Jansen, em Cerro Oeste.', 'Por ordem de Sua Alteza Real o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar ao tenente Horatio Laine no Sítio dos Jansen.$B$BCerro Oeste foi tomada por pedintes e transeuntes, o que gerou aumento da criminalidade. Precisamos da sua ajuda para restaurar a ordem entre a plebe.$B$BVocê chega ao Sítio dos Jansen viajando para oeste, pela Floresta de Elwynn.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28563, 'ptBR', 'O chamado ao heroísmo: Montanhas Cristarrubra!', 'Apresente-se ao Capitão da Guarda Florestan na Torre Vigilante, que fica nas Montanhas Cristarrubra.', 'Por ordem de sua majestade o rei Varian Wrynn, todos os cidadãos da Aliança em bom estado físico devem se apresentar ao capitão da guarda Florestan na Torre Vigilante, que fica nas Montanhas Cristarrubra.$B$BAs tropas do capitão Florestan têm sido atacadas por gnolls e orcs saqueadores. As pessoas de Vila Plácida estão em perigo e sua ajuda é necessária para protegê-las. Vá para o leste a partir da fronteira da Floresta de Elwynn. Siga por Três Caminhos, em Cristarrubra, e você chegará à Torre Vigilante.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28564, 'ptBR', 'O chamado ao heroísmo: Floresta do Crepúsculo!', 'Apresente-se à Comandante Aldora Ebanez na Vila Sombria, que fica na Floresta do Crepúsculo.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem apresentar-se à comandante Aldora Ebanez, na Vila Sombria.$B$BAs tropas estão sobrecarregadas com o combate a pilhagens de lobos e bandos de worgens selvagens. A comandante não vai resistir por muito mais tempo sem a sua ajuda. Para chegar à Vila Sombria na Floresta do Crepúsculo, siga a estrada para o sul, na fronteira entre a Floresta de Elwynn e as Montanhas Cristarrubra.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28565, 'ptBR', 'O chamado ao heroísmo: Pantanal!', 'Fale com o Montanhista Rharen em Dun Algaz.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança fisicamente aptos devem se apresentar ao Montanhista Rharen em Dun Algaz.$B$BComo consequência da destruição causada pelo cataclismo, o Pantanal ficou repleto de feras, saqueadores órquicos e gnolls selvagens! Para chegar ao Pantanal, siga para o norte a partir de Loch Modan e passe pelo domínio enânico de Dun Algaz.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28566, 'ptBR', 'Dizimação', 'Mate o Capitão Gélido e 12 Soldados Lançatroz.', '<A imagem de Melissara surge diante de você.>$B$BO acampamento avançado dos Lançatroz fica no topo da Adaga de Corrahn, a oeste do Promontório de Sofera. Entre no acampamento e mate todos os anões que vir. Eles precisam aprender o que significa temer e não há lição melhor do que a total aniquilação.$B$BSem sobreviventes, $n. Até mesmo o capitão deles - especialmente o capitão - deve morrer.$B$BManterei contato.', '', '', '', '', '', '', 'Melissara', 'A dizimação leva à hesitação.', 'Melissara', 'Fale com Melissara na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28567, 'ptBR', 'O chamado ao heroísmo: Loch Modan!', 'Fale com o Piloto Pisafundo, no Posto de Guarda do Portão Sul, em Loch Modan.', 'Por ordem de Sua Alteza Real o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem apresentar-se ao piloto Pisafundo no Posto de Guarda do Portão Sul.$B$BCom a destruição do Dique Lapidado e a volta da ameaça dos kobolds e troggs, os montanhistas ficaram sobrecarregados. Precisamos desesperadamente de reforços! Para chegar ao Posto de Guarda do Portão Sul, vá em direção ao nascente, atravessando o Desfiladeiro do Portão Sul, pela parte leste de Dun Morogh.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28568, 'ptBR', 'Ordens do Chefe Guerreiro: Floresta de Pinhaprata!', 'Apresente-se ao Grão-executor Mortuus no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.', 'Todos os membros da Horda em bom estado físico são por esta intimados a se apresentar ao Grão-executor Mortuus no Alto Comando dos Renegados, que fica na Floresta de Pinhaprata.$B$BAgora, mais do que nunca, sua ajuda é necessária para debelar a infestação dos inimigos na região e para conquistar o porto de Guilnéas!$B$BPara chegar ao Alto Comando dos Renegados, você deverá seguir para o sul pelas Clareiras de Tirisfal e, então, entrar na Floresta de Pinhaprata. De lá, tome a estrada para o sul até chegar ao Alto Comando dos Renegados.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28569, 'ptBR', 'O Balaço do Brejo', 'Fale com Sharon Pegabala no canto sudeste das Estepes Ardentes para ir de Balaço do Brejo para o Pântano das Mágoas. Então, fale com o Barão Mercador Romprata no Brejo do Goblin.', 'Já ouvi histórias sobre a estrada para o Pântano das Mágoas. Lendas misteriosas sobre um atalho sinuoso por entre as montanhas, pelo qual você não precisa passar por Cristarrubra: ele manda você diretamente para o Brejo do Goblin!$B$BSe você não tiver mais nada para fazer, suponho que terá que ir embora. E todos nós ficaremos tristes. Quando você for realmente embora, fale com a Sharon Pegabala, no canto sudeste das estepes. Ela lhe dará uma carona.$B$B<Oralius mexe a cabeça como se estivesse ouvindo algo.>$B$BPiscadela? PISCADELA! NÃO!', '', '', '', '', '', '', '', '', '', 'Fale com o Barão Mercador Romprata no Brejo do Goblin, que fica no Pântano das Mágoas.', 0),
(28570, 'ptBR', 'O Balaço do Brejo', 'Fale com Sharon Pegabala no canto sudeste das Estepes Ardentes para ir de Balaço do Brejo para o Pântano das Mágoas. Então, fale com o Barão Mercador Romprata no Brejo do Goblin.', 'Você é mesmo $Gum:uma; $r sensacional, não é? Olha só pra você... $GTodo adulto:Toda adulta;... E a gente acabou de se conhecer!$B$BJá até sei como vai ser. Logo, logo você não vai ter mais nada pra fazer aqui no Monte Candente. Você vai prometer que vai voltar. Mas não vai. Nunca.$B$BO Kibler já viu esse filme.$B$BQuando você for embora, fala com a Sharon Pegabala no canto sudeste das estepes. Ela vai te dar uma carona no Balaço.$B$BO que foi? Ah, é só um foguete. É totalmente seguro.', '', '', '', '', '', '', '', '', '', 'Fale com o Barão Mercador Romprata no Brejo do Goblin, que fica no Pântano das Mágoas.', 0),
(28571, 'ptBR', 'Ordens do Chefe Guerreiro: Contraforte de Eira dos Montes!', 'Fale com a Alta Executora Darthalia no Portão do Sul do Contraforte de Eira dos Montes.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, convocados a se apresentarem à Alta Executora Darthalia no Portão do Sul do Contraforte de Eira dos Montes. A máquina de guerra renegada avança, assegurando Lordaeron para a Horda!$B$BPara chegar ao Portão Sul, siga a estrada para o sul através da Floresta de Pinhaprata e depois ao leste na bifurcação para Contraforte de Eira dos Montes.$B$BAvante, irmãos e irmãs! O destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28572, 'ptBR', 'Ordens do Chefe Guerreiro: Planalto Arathi!', 'Apresente-se à Patrulheira Sombria Alina na Ruína de Galen, que fica no Planalto Arathi.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, convocados a se apresentar à Patrulheira Sombria Alina na Ruína de Galen.$B$BAs forças da Dama Sombria necessitam da sua ajuda para expandir os domínios da Horda e expulsar os intrometidos da Aliança.$B$BPara chegar ao Planalto Arathi, siga para leste do Contraforte de Eira dos Montes e siga a estrada depois da Muralha de Thoradin.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28573, 'ptBR', 'O chamado ao heroísmo: Planalto Arathi!', 'Apresente-se à Capitão Nélia na Ponta do Refúgio, que fica no Planalto Arathi.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar à Capitão Nélia na Ponta do Refúgio.$B$BA antiga honra de Stromgarde deve ser recuperada! Não podemos mais aceitar ogros e criminosos nas estradas. Vá para o norte do Pantanal e atravesse a Ponte Thandol até chegar a Arathi. Siga a estrada para a Ponta do Refúgio e apresente-se para a capitão.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28574, 'ptBR', 'Ordens do Chefe Guerreiro: Terras Agrestes!', 'Apresente-se ao Ancião Presa-arrancada na Aldeia Revatusco, que fica nas Terras Agrestes.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, obrigados a apresentar-se ao ancião Presa-arrancada na Aldeia Revatusco.$B$BAgora que os anões Martelo Feroz se juntaram oficialmente à Aliança, eles se tornaram nossos inimigos. Eles precisam ser derrotados!$B$BPara chegar à Aldeia Revatusco, cruze as Terras Agrestes através do desfiladeiro da montanha na banda oriental do Contraforte de Eira dos Montes e avance até a costa leste.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28575, 'ptBR', 'Ordens do Chefe Guerreiro: Terras Pestilentas Ocidentais!', 'Apresente-se a Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, intimados a se apresentar a Koltirus Tecemorte em Andorhal.$B$BAs tropas da Aliança estão avançando em direção às ruínas de Andorhal para tentar retomá-la. Temos que contra-atacar antes que elas estabeleçam uma base lá!$B$BAtravesse o Baluarte, na fronteira oriental das Clareiras de Tirisfal, e siga pelas estradas a sudeste até Andorhal, onde você encontrará nossas tropas.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28576, 'ptBR', 'O chamado ao heroísmo: Terras Pestilentas Ocidentais!', 'Apresente-se a Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar a Thassarian, em Andorhal.$B$BApesar de derrotados nos primeiros ataques à Andorhal, os Renegados decidiram contra-atacar. A Aliança precisa de você para rechaçar o Flagelo e a Horda e retomar a cidade.$B$BPara chegar a Andorhal, dirija-se a norte, pelo Contraforte de Eira dos Montes, e siga pela estrada além do Acampamento Ventogelante.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28577, 'ptBR', 'Ordens do Chefe Guerreiro: Terras Pestilentas Orientais!', 'Apresente-se à Fiona na margem leste do Rio Thondroril, nas Terras Pestilentas Orientais.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, obrigados a se apresentar à Fiona na margem leste do Rio Thondroril.$B$BA Cruzada Argêntea está reforçando a presença nas Terras Pestilentas e precisa da sua ajuda para garantir a vitória.$B$BAtravesse o Rio Thondroril, na fronteira leste das Terras Pestilentas Ocidentais, e procure por Fiona na margem mais afastada.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28578, 'ptBR', 'O chamado ao heroísmo: Terras Pestilentas Orientais!', 'Apresente-se a Fiona na margem leste do Rio Thondroril, nas Terras Pestilentas Orientais.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar a Fiona, na margem leste do Rio Thondroril.$B$BA Cruzada Argêntea precisa da sua ajuda para retomar as Terras Pestilentas Orientais das garras do Flagelo.$B$BPara chegar às Terras Pestilentas Orientais, atravesse o Rio Thondroril, partindo das Terras Pestilentas Ocidentais. Procure por Fiona na margem leste.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28579, 'ptBR', 'O chamado ao heroísmo: Ermos!', 'Apresente-se a Gek Rojão na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar a Gek Rojão na Capela Esperança da Luz, localizada nas Terras Pestilentas Orientais.$B$BPrecisamos de ajuda para investigar os danos causados pelo Asa da Morte e a distribuição das forças da Horda nos Ermos.$B$BGek concordou em oferecer transporte aos Ermos via foguete em troca de ajuda. Procure-o na Capela Esperança da Luz, localizada nas Terras Pestilentas Orientais.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28580, 'ptBR', 'Ordens do Chefe Guerreiro: Ermos!', 'Apresente-se a Gek Rojão na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, obrigados a se apresentar a Gek Rojão na Capela Esperança da Luz, localizada nas Terras Pestilentas Orientais.$B$BA Aliança está desesperada para se estabelecer nos Ermos. Sua tarefa será mantê-los afastados e levantar informações sobre a destruição causada pelo Asa da Morte.$B$BGek concordou em oferecer o transporte de foguete até os Ermos. Encontre-o na Capela Esperança da Luz.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28581, 'ptBR', 'Ordens do Chefe Guerreiro: Garganta Abrasadora!', 'Apresente-se ao Jack Pernadura no Avanço de Tório, na Garganta Abrasadora.', 'Todos os membros da Horda em boas condições físicas estão por meio deste convocados a se apresentar a Jack Pernadura no Avanço de Tório.$B$BA Mão Despedaçada relata que os anões Ferro Negro da Garganta Abrasadora estão tramando algo. Seu trabalho será aprender tudo sobre esta conspiração e pôr fim a ela.$B$BVocê chega à Garganta Abrasadora seguindo a estrada a oeste dos Ermos.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28582, 'ptBR', 'O chamado ao heroísmo : Garganta Abrasadora!', 'Apresente-se ao Jack Pernadura no Avanço de Tório, na Garganta Abrasadora.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em bom estado físico devem se apresentar a Jack Pernadura, no Avanço de Tório.$B$BA AVIN relata planos de ataque dos anões Ferro Negro da Garganta Abrasadora. Seu trabalho será aprender tudo sobre esta conspiração e pôr fim a ela.$B$BVocê chega à Garganta Abrasadora seguindo a estrada a oeste dos Ermos.$B$BPela glória e honra da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28583, 'ptBR', 'Krazzodutos', 'Entregue o Registro de Patente para o Capitão Krazz nos Krazzodutos, que ficam no Planalto do Crepúsculo.', 'Este novo modelo de retalhador é da hora, $n. Demais! Agora tenho que proteger minha propriedade intelectual. Tem patentes pra registrar, comerciantes pra cadastrar, cortes pra fazer... além dos subornos!$B$BTome este registro de patente e entregue pro capitão Krazz nos Krazzodutos. Ele sobreviveu à destruição do zepelim dele e deve estar sedento por novas oportunidades de negócios.$B$BOs Krazzodutos ficam a norte daqui, no pico de uma montanha totalmente segura. Vá em frente, chapa!', '', '', '', '', '', '', '', '', '', 'Entregue o Registro de Patente para o Capitão Krazz nos Krazzodutos, que ficam no Planalto do Crepúsculo.', 0),
(28584, 'ptBR', 'Construção de qualidade', 'Use a Fita Arrasadora para lacrar 10 Válvulas Defeituosas.', 'Veja bem, chapa, se não fosse por esse idiota desajeitado aí no outro lado, os Krazzodutos estariam aguentando firme.$B$BInfelizmente, pra todo mundo envolvido, o sabichão do Rothman resolveu montar os dutos no topo de uma montanha! Quem faz uma coisa dessas?!?$B$BTem vazamentos por todo lugar por conta de válvulas com defeito. ‘‘Cê acha que consegue lacrar as válvulas com esta fita pra mim?', '', 'Válvulas Defeituosas lacradas', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Krazz nos Krazzodutos, que ficam no Planalto do Crepúsculo.', 0),
(28586, 'ptBR', 'Meu poneizinho pocotó', 'Use os Pôneis Aquáticos para resgatar 10 Trabalhadores dos Krazzodutos que caíram na água.', 'Esse panaca aí no outro lado tá mandando nosso povo dessa pra melhor!$B$BBarbosa, o Inútil, montou os Krazzodutos no lugar errado e agora tá tudo muito instável. As explosões provocadas com a instabilidade estão varando nossos trabalhadores das plataformas pro mar.$B$B\'Cê se importa em voar até lá e resgatar alguns deles com os pôneis aquáticos, $n?', '', 'Trabalhadores dos Krazzodutos resgatados', '', '', '', '', '', '', '', 'Fale novamente com Pirilampo Rothman nos Krazzodutos, que ficam no Planalto do Crepúsculo.', 0),
(28587, 'ptBR', 'Ajuda do clã Lobo do Gelo', 'Fale com Voggah Garramort nas Montanhas de Alterac, no Contraforte de Eira dos Montes.', 'Estudarei os planos de batalha dos Lançatroz e planejarei um ataque. Vá até o Vale Alterac e peça ajuda ao clã Lobo do Gelo, do nosso antigo chefe Thrall. Eles nos auxiliarão na luta contra os anões Lançatroz! Juntos, esmagaremos os invasores e os varreremos de Lordaeron!$B$BVá agora, $n. O Vale Alterac fica a nordeste da Serraria Tarren. Encontre Voggah Garramort e diga-lhe que a Horda solicita a ajuda dos Lobo do Gelo!$B$BLOK\'TAR!', '', '', '', '', '', '', '', '', '', '', 0),
(28588, 'ptBR', 'Infestação Martelo Feroz', 'Mate 10 Saqueadores Martelo Feroz.', 'Enquanto esses dois manés discutem quem realmente aprontou aqui, estão invadindo de sola os Krazzodutos!$B$BAqueles Martelo Feroz malvados estão por todo lugar. Vai até lá e livre os Krazzodutos daquelas pragas com futum de cerveja choca.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Krazz nos Krazzodutos, que ficam no Planalto do Crepúsculo.', 0),
(28589, 'ptBR', 'Tudo e mais um pouco', 'Mate 15 Temperáguias Martelo Feroz.', '‘‘Cê tem que fazer alguma coisa com os Temperáguias Martelo Feroz. Eles estão acabando com a gente!$B$BO que tá pegando é que a gente ficou sem munição e teve que improvisar. A gente carregou os canhões com um monte de troços: pôneis aquáticos, latas de Jaka\'Cola, embalagens de comida, cápsulas combustíveis, pneus... pra ‘‘cê ter noção.$B$BBasicamente tudo, menos a pia da cozinha.$B$B\'Cê acha que tá em forma pra treinar tiro ao alvo?', '', 'Arme-se com um Canhão de Krazz', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Krazz nos Krazzodutos, que ficam no Planalto do Crepúsculo.', 0),
(28590, 'ptBR', 'Represália', 'Fale com Mathiaz a bordo do Retalha-céu, que sobrevoa Beiralta.', 'Fiquei sabendo que tem uns patifes da Aliança que vão levar a pior. E eles estão com uma coisa que é da gente. Eu autorizei um ataque com força total a Beiralta.$B$BEmbarque no Retalha-céu e participe do ataque. Mathiaz vai lhe passar os detalhes quando você chegar lá.', '', '', '', '', '', '', '', '', '', '', 0),
(28591, 'ptBR', 'Caindo do muro', 'Destrua 80 Atiradores Peritos de Beiralta, 12 Canhoneiros de Beiralta e 4 Canhões de Beiralta com uma Torreta Retalha-céu.', 'Você parece se amarrar num agito, hein? Entre numa destas torretas e arrase com as defesas deles na muralha.$B$BMas rapidinho, valeu? De preferência, antes que eles mandem a gente pelos ares...', '', '', '', '', '', '', '', '', '', 'Fale com Mathiaz a bordo do Retalha-céu, que sobrevoa Beiralta, no Planalto do Crepúsculo.', 0),
(28592, 'ptBR', 'Embrulhos surpresa', 'Coloque bombas no barco, na entrada do forte e em uma das torres do norte.', 'Tenho certeza de que Mathiaz tem algum grande plano em mente, mas isso não seria um ataque se a gente não deixasse umas bombas por lá.$B$BDesça e coloque explosivos no barco, na entrada do forte e em uma das torres do norte. Isso deve bastar pra deixar eles baqueados.$B$BA gente vai pro solo também. Encontre a gente na torre do leste quando acabar tudo.', '', 'Bomba colocada no barco de Beiralta', 'Bomba colocada no Forte Beiralta', 'Bomba colocada na torre de Beiralta', '', '', '', '', '', 'Encontre Tique próximo à torre oriental de Beiralta, que fica no Planalto do Crepúsculo.', 0),
(28593, 'ptBR', 'Importante, muito importante... importantíssimo', 'Recupere a Rebimboca de Indução.', 'Quando o zepelim de Garrosh foi derrubado, a rebimboca de indução que você recuperou pra gente em Azshara também se perdeu. A Aliança tá guardando ela em algum lugar daquela fortaleza e Krazz quer ela de volta.$B$BEu arriscaria no porão da fortaleza, é bom começar por lá. Quando você colocar as mãos nela, me entregue na torre do leste.', '', '', '', '', '', '', '', '', '', 'Encontre Mathiaz próximo à torre oriental de Beiralta, que fica no Planalto do Crepúsculo.', 0),
(28594, 'ptBR', 'Beiralta em baixa', 'Mate 10 Defensores de Beiralta.', 'Desça até lá e dê uns safanões naquela gentalha da Aliança. Serve qualquer um. Só quero eles dispersos enquanto você tá atrás do verdadeiro alvo.$B$BEncontre a gente na torre do leste quando você tiver terminado.', '', 'Defensores de Beiralta mortos', '', '', '', '', '', '', '', 'Encontre Mathiaz próximo à torre oriental de Beiralta, que fica no Planalto do Crepúsculo.', 0),
(28595, 'ptBR', 'Eurekrazz!', 'Fale com Samalandra para garantir uma viagem de volta para os Krazzodutos e entregue a Rebimboca de Indução para o Capitão Krazz.', 'É isso. Já estamos prontos. Vamos zarpar!$B$BSamalandra posicionou uns girocópteros no topo da torre. Vá encontrar ela pra uma viagem rápida até os Krazzodutos. Vamos terminar o serviço por aqui.', '', '', '', '', '', '', '', '', '', '', 0),
(28596, 'ptBR', 'Bem-vindo a Beiralta!', 'Mate 10 Agressores da Horda em Beiralta.', '$gBem-vindo:Bem-vinda; ao Planalto, $gguerreiro:guerreira;! Chegou bem a tempo.$B$BTropas da Horda acabaram de iniciar um ataque aéreo. Prepare-se e faça algo a respeito disso. Dê um jeito neles!', '', 'Agressor da Horda assassinado', '', '', '', '', '', '', '', 'Fale novamente com o Tenente Fawkes em Beiralta, que fica no Planalto do Crepúsculo.', 0),
(28597, 'ptBR', 'Queimando as duas pontas', 'Recolha 10 bolsas cheias de Pólvora de Canhão.', 'Bá! A gente tem que cair direto de sola, $n. Parece que Beiralta tem o que chamam de "problema zepelínico": aquela aeronau tá bombardeando as muralhas como um aríete!$B$BOuça, tenho uma ideia tão idiota que chega a ser genial. Só preciso de pólvora de canhão.$B$BPegue o máximo que achar nos arredores de Beiralta e me encontre na região comercial!', '', '', '', '', '', '', '', '', '', 'Encontre Fargo Flintlocke ao norte de Beiralta, que fica no Planalto do Crepúsculo.', 0),
(28598, 'ptBR', 'Mirando alto', 'Espere Fargo Flintlocke colocar você no zepelim para, então, colocar os explosivos na câmara inferior dele.', 'Olhe isso, $n. Encontrei a maior arma de Beiralta! Vamos experimentar uma técnica que meu tataravô ensinou ao meu bisavô que ensinou ao meu avô que ensinou ao meu pai longo antes de explodir.$B$BEla se chama "lança-$c."$B$BVocê tem que pegar $gum:uma; $r $c e colocar dentro de um canhão para... calma, calma, geralmente funciona.$B$BPegue os explosivos e aguarde aqui perto de mim. Assim que o dirigível se aproximar, te lanço pra bordo dele. Coloque os explosivos na saliência e... sei lá. Dê um jeito.', '', 'Aguarde seu lançamento do Canhão do Flintlocke.', 'Destrua o Retalha-céu.', '', '', '', '', '', '', 'Fale novamente com Fargo Flintlocke em Beiralta, que fica no Planalto do Crepúsculo.', 0),
(28599, 'ptBR', 'Kurdran está esperando', 'Fale com Kurdran Martelo Feroz no Forte Beiralta, que fica no Planalto do Crepúsculo.', 'Parece que cessaram o ataque, $n. Isso é uma pena, já que não usamos o lança-$c.$B$BDe todo jeito, Kurdran Martelo Feroz tá lá no topo do forte esperando te receber como $gum herói:uma heroína;. Você merece! Vá falar com ele.$B$BVou continuar e patrulhar a praia.', '', '', '', '', '', '', '', '', '', '', 0),
(28600, 'ptBR', 'Questões de lealdade', 'Fale com Drek\'Thar.', 'Não tenho autoridade sobre tais questões. Você deve falar com nosso líder, Drek\'Thar. Já mandei notícias de sua chegada à Bastilha Lobo do Gelo. Drek\'Thar falará com você pessoalmente.', 'Aprenda as Questões de Lealdade.', '', '', '', '', 'Aprenda as Questões de Lealdade.', '', '', '', 'Fale novamente com o Sumo Senhor da Guerra Cromush na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28602, 'ptBR', 'Prepare-se', 'Colete 6 Pedaços de Corda.', 'Todo aventureiro de respeito sabe que nunca deve colocar o pé em uma caverna, masmorra, cripta ou tumba sem um vasto estoque de corda... não é?$b$bBem, a minha corda estava naquele carro cheio de explosivos que você detonou.$b$bQue tal procurar por aqui e ver se você não encontra um pouco?', '', '', '', '', '', '', '', '', '', 'Fale com Harrison Jones na Câmara das Estrelas.', 0),
(28603, 'ptBR', 'Infiltração', 'Mate o Instrutor Rufus, o Sargento-instrutor Magno e o Capitão Barbagode.', 'Para sua próxima missão, quero que você siga para Terralta a oeste e se infiltre no campo de treinamento Lançatroz. Mesmo havendo centenas de recrutas lançatroz por lá, minhas banshees irão disfarçá-lo para que se pareça com um dos humanos capturados a fim de que você possa andar por entre o inimigo sem riscos.$B$BVá a Terralta e encontre os instrutores Lançatroz. Quando encontrá-los, faça-os $gatacá-lo:atacá-la;! Quando atacarem, mate-os. Com seus instrutores mortos, eles serão incapazes de treinar mais soldados!', '', '', '', '', '', '', 'Melissara', 'A confusão leva ao caos.', 'Melissara', 'Fale com Melissara na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28604, 'ptBR', 'Ilusão e trapaça', 'Use o Barril de Água para envenenar 30 Aprendizes Lançatroz.', 'O inimigo pensará que você é um deles se eu permanecer ao seu lado. Sua recém-adquirida humanidade, no entanto, não permite que você se dê ao luxo de ser descuidado. Se você chamar atenção, os anões suspeitarão e poderão atacar!$B$BAssim sendo, tenho um plano. Leve este barril com água envenenada e use-a para saciar a sede dos aprendizes Lançatroz cansados. Tendo bebido dela, eles ficarão doentes e acabarão por sucumbir ao veneno.', '', 'Aprendiz Lançatroz envenenado', '', '', '', '', '', '', '', 'Fale com Lilith no Contraforte de Eira dos Montes.', 0),
(28605, 'ptBR', 'Dominação', 'Mate 10 Engenheiros Lançatroz.', '<Os pensamentos de Melissara se misturam aos seus.>$B$BSua última tarefa será atacar os técnicos de cerco do Promontório de Gavin, localizado a oeste de Terralta. Siga para o último dedo e acabe com os engenheiros anões e gnomos que construíram e fortificaram as máquinas de guerra Lançatroz. Certifique-se de plantar a última ogiva de bolso de Cromush.', '', '', '', '', '', '', 'Melissara', '', '', 'Fale novamente com Melissara na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28608, 'ptBR', 'O Sepulcro Sombrio', 'Obtenha o Fluido Embalsamador Denso e a Gavinha de Costurar Cadáver do Sepulcro Sombrio, em Plangemortis.', 'Estou satisfeito em ver que está de pé e andando novamente, $n. Nem parece que esteve $gmorto:morta; por tanto tempo!$b$bOutros não tiveram tanta sorte. Se não se importar, poderia pegar o meu fluido embalsamador e algumas gavinhas de costurar cadáveres? Você encontrará ambos no Sepulcro Sombrio, a construção logo atrás de mim.$b$bDarnell mostrará o caminho.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Coveiro Mordo nas Tumbas de Plangemortis, em Plangemortis.', 0),
(28609, 'ptBR', 'Hora do Martelo', 'Fale com Rocas Calho.', 'Nós três estamos discutindo há semanas para saber quem tem as melhores armas.$B$BNão vou deixar ninguém dizer que as minhas maças estão em segundo lugar. Os machados de Kilram e as espadas de Seril nunca foram páreo para a força pura da minha arte.$B$BEstou cansada de discutir. Chegou a hora de provar a esses dois que estou certa com uma demonstração. Se puder, $gmeu caro:minha cara;, vá ali fora e diga ao Rocas Calho que preciso do maior penedo que ele puder encontrar!', '', '', '', '', '', '', '', '', '', '', 0),
(28610, 'ptBR', 'Faturando um cascalho', 'Colete 6 Pedaços de Cascalho de Primeira dos Estrondosos Chispagelo.', 'Se você quiser levar um pedregulhão lá pra dentro, recomendo que use o meu Penedo Encaixotado patenteado! Normalmente eu lhe venderia um agorinha mesmo, mas acabei de ficar sem matéria-prima.$B$BUns elementais da terra andaram aparecendo no pico diretamente ao sul da cidade. Eles são uma boa fonte de cascalho. Se você me trouxer bastante, eu lhe pagarei pela força que você me deu no reabastecimento, e ainda darei um Penedo Encaixotado por conta da casa!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rocas Calho em Visteterna, que fica em Hibérnia.', 0),
(28611, 'ptBR', 'O ritual dos profanadores', 'Detenha o Ritual dos Neferset na Caverna Lodofundo.', 'Ah, já posso ver bem mais claramente, $n.$B$BEstamos certos em ser cautelosos com os malvados neferset. Já posso sentir que eles estão por trás das forças que corromperam o rio.$B$BMergulhe de novo e procure a Caverna Lodofundo. Você encontrará os neferset realizando um ritual perverso.$B$BDetenha-os para que o rio fique puro novamente.', '', 'Ritual dos Neferset interrompido', '', '', '', '', '', '', '', 'Fale novamente com o Sumo Sacerdote Amet na Represa Vir\'naal em Uldum.', 0),
(28612, 'ptBR', 'Harrison Jones e o Templo de Uldum', 'Recupere o Baú da Promessa.', 'Depois de tudo que passamos, parece que tudo está dando certo!$b$bEstamos a alguns passos do baú... Pesquisei os códigos para revelá-lo... Schnottz pensa que estamos mortos...$b$bSabe, pode ser que isso dê certo no final das contas!', '', 'Baú da Promessa descoberto', '', '', '', '', '', '', '', 'Fale com Brann Barbabronze no Templo de Uldum.', 0),
(28613, 'ptBR', 'Vejo você no outro lado!', 'Fale com Harrison Jones no topo da Encosta do Criador, que fica em Uldum.', 'Tudo bem, $n. Conseguimos parar um pouco para respirar, mas não temos tempo a perder.$b$bSiga-me!', '', '', '', '', '', '', '', '', '', '', 0),
(28614, 'ptBR', 'Furiurso', 'Mate Grolnar, o Berserk.', 'A ausência do Grande Chefe Invernoso não adiantou muito para acalmar a ira dos invernosos. Por conta disso, o guerreiro mais forte deles ascendeu a uma posição de poder terrível.$B$BGrolnar, o Berserk, está na caverna, na parte superior da Aldeia dos Invernosos, e bebe tanta aguardente corrupta que daria para matar dez invernosos inferiores.$B$BEle virou uma fera inchada e horrorosa! Os nossos guerreiros não foram capazes de enfrentá-lo... Você é forte o bastante para derrotá-lo, $c?', '', '', '', '', '', '', 'Grolnar', '', '', 'Fale novamente com Rochama perto da Aldeia dos Invernosos, em Hibérnia.', 0),
(28615, 'ptBR', 'Quem com terra fere...', 'Use o Totem Sobrecarregado de Tanrir para sobrecarregar 4 Totens da Terra dos Invernosos.', 'Apesar da corrupção e da loucura, os Invernosos se agarram como podem aos seus poderes xamânicos. É perturbador ver o poder dos elementais sendo usado contra minha tribo e outros inocentes.$B$BVamos virar os totens deles contra eles mesmos! Leve o meu totem para a Aldeia dos Invernosos. Use os poderes dele contra os totens dos Invernosos (mas de longe) e a fúria da terra será lançada sobre todos aqueles que estiverem perto!$B$BE é melhor eu repetir: fique longe!', '', 'Totem da Terra dos Invernosos sobrecarregado', '', '', '', '', '', '', '', 'Fale novamente com Tanrir perto da Aldeia dos Invernosos, em Hibérnia.', 0),
(28616, 'ptBR', 'O crepúsculo dos Lançatroz', 'Testemunhe o Crepúsculo dos Lançatroz.', 'Antes de continuarmos, dediquemos um momento de silêncio ao nosso finado irmão Orkus, sem o qual teríamos sido dizimados pela ofensiva Lançatroz. A você, irmão!$B$B<Cromush se ajoelha.>$B$BAgora, $n, não pense que esqueci sua parte em tudo isso! Por isso você terá a honra de detonar as bombas dos goblins.$B$B$gPreparado:Preparada;? PELA HORDA!', 'Testemunhe o Crepúsculo dos Lançatroz.', '', '', '', '', 'Testemunhe o Crepúsculo dos Lançatroz.', '', '', '', 'Fale com o Sumo Senhor da Guerra Cromush na Serraria Tarren, no Contraforte de Eira dos Montes.', 0),
(28617, 'ptBR', 'O poder das flores', 'Sobreviva a uma Onda Imensa de Zumbis.', 'Você sabe como usar as cúspides, mas sabia que, se usar girassóis, você pode acelerar o crescimento das coisas? Vamos cultivar alguns girassóis e depois plantaremos cúspides para rechaçar as monstruosidades enfurecidas do carcereiro Calmágua.$B$BVamos!', '', 'Onda Imensa sobrevivida', '', '', '', '', '', '', '', 'Fale com o Botânico Zeca Rioka na Fazenda do Zeca, no Contraforte de Eira dos Montes.', 0),
(28618, 'ptBR', 'Penedo em domicílio', 'Entregue o Penedo Encaixotado à Lilith, a Ligeira, em Visteterna.', 'Aqui está, como prometido! Um Penedo Encaixotado.$B$BEra isso que a Lilith queria, não era? Ela é a minha única cliente!', '', '', '', '', '', '', '', '', '', '', 0),
(28619, 'ptBR', 'Ordens do Chefe Guerreiro: Planalto Arathi!', 'Apresente-se à Patrulheira Sombria Alina na Ruína de Galen, que fica no Planalto Arathi.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, convocados a se apresentar à Patrulheira Sombria Alina na Ruína de Galen.$B$BAs forças da Dama Sombria necessitam da sua ajuda para expandir os domínios da Horda e expulsar os intrometidos da Aliança.$B$BPara chegar ao Planalto Arathi, siga para leste do Contraforte de Eira dos Montes e siga a estrada depois da Muralha de Thoradin.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28620, 'ptBR', 'Torre Leste', 'Fale com Nilson Putrefacto na Torre Leste do Contraforte de Eira dos Montes.', 'Nosso posto a sudeste está em apuros. Eu não tenho maiores detalhes a não ser... bem, deixe-me ler a última carta:$B$B"Os orcs ficaram insuportáveis. Envie ajuda ou terei que lhes dar uma surra de bambu".$B$BÉ isso. Ela foi enviada pelo nosso chefe filosófolo, Nilson Putrefacto. Sim, também não tenho ideia alguma do que isso significa. Você pode, por favor, se dirigir à Torre Leste e descobrir o que ele precisa? Não posso mais receber estas cartas enigmáticas!$B$BVá para o sul e siga a estrada para o leste.', '', '', '', '', '', '', '', '', '', '', 0),
(28621, 'ptBR', 'Coloque aquele bebê no berço!', 'Fale com Harrison Jones no Templo de Uldum.', 'Ora, ora!$b$bVocê e o Júnior demoraram bastante para chegar aqui, não foi!?$b$b$gBebendo cerveja:Dando as mãos; e apreciando a vista, aposto...$b$bNão comece a dar tapinhas nas costas e comemorar, pois o trabalho de verdade está só começando!$b$bHá mais por trás deste artefato ancestral do que você sabe, mas, para revelarmos esses segredos, precisamos levá-lo ao Berço dos Anciãos!$b$bAgora, como você acha que vamos fazer isso?$b$bTalvez o Júnior tenha alguma ideia brilhante, né?', '', '', '', '', '', '', '', '', '', '', 0),
(28622, 'ptBR', 'Se pelo ar, três...', 'Use os Sinais de Fumaça no Templo de Uldum.', 'Eu tinha pensado em levar o baú para o meu laboratório para estudá-lo melhor, mas parece que o Brann tem outra coisa em mente.$b$bEle acha que sabe como acabar com os planos do Asa da Morte aqui mesmo em Uldum.$b$bUm camarada meu, o Jock, está a postos com o transporte, esperando apenas pelo nosso sinal.$b$bEspalhe estes sinalizadores ao longo do perímetro para o Jock saber que já estamos prontos.', '', 'Sinal de Fumaça do Norte posicionado', 'Sinal de Fumaça do Oeste posicionado', 'Sinal de Fumaça do Sul posicionado', '', '', '', '', '', 'Fale com Brann Barbabronze no Berço dos Anciãos.', 0),
(28623, 'ptBR', 'Dando um empurrãozinho', 'Apresente-se ao Rei Phaoris nos Arredores da Cidade dos Neferset em Uldum.', 'Nosso trabalho está feito aqui, $n. Contrariando as perspectivas, impedimos o avanço dos neferset em Nahom.$B$BVamos nos juntar às forças seguindo para oeste, para que não reclamem a glória para si.$B$BEles já devem ter atingido os arredores da Cidade dos Neferset.', '', '', '', '', '', '', '', '', '', '', 0),
(28624, 'ptBR', 'O caô do Kilram', 'Fale com Rocas Calho.', 'Que nada! Isso é só força bruta e grosseria!$B$BSó que força não é tudo. Os meus machados são tão fortes quanto as maças de Lilith, mas são tão afiados que dá para cortar uma árvore com um só golpe!$B$BOuviu o que disse? Com um só golpe! Eu vou provar isso aqui, na frente de todo o mundo. Peça ao Rocas para me trazer uma árvore aqui.', '', '', '', '', '', '', '', '', '', '', 0),
(28625, 'ptBR', 'Serrando na serra', 'Colete 10 Lenhas Gélidas Recém-cortadas dos Arvorosos da Folha Gélida.', 'Eu trabalho bastante com troncos pequenos, mas árvores inteiras? Isso é item de colecionador. Mais ou menos como aqueles penedos.$B$BVocê poderia me fazer outro favor? A oeste da cidade, há um bosque cujas árvores rodeiam o Lago Kel\'Theril. Não sei se é por causa dos fantasmas ou se é culpa daquelas tranqueiras élficas mágicas espalhadas por lá, mas ultimamente os arvorosos e as açoitadeiras apareceram na área.$B$BEles estão dando muito trabalho para quem corta lenha lá, então por que você não corta alguns deles? Me traz a lenha dos arvorosos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rocas Calho em Visteterna, que fica em Hibérnia.', 0),
(28626, 'ptBR', 'Árvores em domicílio', 'Entregue a Instantárvore Super-crescida a Kilram na estalagem em Visteterna.', 'Aqui está. Uma Instantárvore Super-crescida feita com 80% de ingredientes naturais!$B$BSem raízes, sem confusão, sem agitação. Entregue isso ao Kilram e não deixe de falar para ele ficar bem longe quando for usar.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Kilram em Visteterna, que fica em Hibérnia.', 0),
(28627, 'ptBR', 'O caô de Seril', 'Fale com Rocas Calho.', 'Brutos e amadores.$B$BNão importa o quanto uma arma é afiada ou pesada se ela só serve para bater como um ogro. Posso ficar aqui o dia inteiro falando sobre sutileza, velocidade, equilíbrio e controle... mas é mais fácil mostrar logo a esses imbecis.$B$BAvise ao Rocas que temos mais uma encomenda para ele. Preciso de um bloco de gelo.', '', '', '', '', '', '', '', '', '', '', 0),
(28628, 'ptBR', 'Gelo em domicílio', 'Entregue o Bloco de Gelo Instantâneo a Seril Flagelicida em Visteterna.', 'Certo, um bloco de gelo instantâneo de primeira saindo!$B$BTentei vender alguns desses por um tempo para servir de proteção. Para fazer igual aquele truque que os magos fazem, sabe? Só não consegui descobrir como resolver o lance da "respiração".', '', '', '', '', '', '', '', '', '', '', 0),
(28629, 'ptBR', 'Eu yeti falar uma coisa...', 'Colete 10 Pelames Grossos de Yeti dos Yetis Cardo de Gelo.', 'Os meus amigos sempre têm um monte de ideias boas. Eu achava que nunca ia ter uma ideia como as deles... até hoje! Acabei de completar os planos para algo genial! Se você me prometer que não vai contar nada pra ninguém, eu te falo um segredo...$B$BVou fazer um yeti mecânico! Meus amigos vão levar um baita susto quando virem, e depois, quando melhorarem do susto, vão ficar impressionados!$B$BTô precisando de um pelame grosso de yeti cardo de gelo. Tem um monte deles na Serra Cardo de Gelo a sudeste.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Umi Zombarruga em Visteterna, que fica em Hibérnia.', 0),
(28630, 'ptBR', 'Eco Tê', 'Encontre Eco Tê.', 'Vários goblins desapareceram na Serra Cardo de Gelo. Quase aconteceu comigo também!$B$BEu tive a ideia de instalar um sensor para avisar quando os yetis estivessem chegando a Visteterna. Claro, também não está funcionando. Tem um monte deles na serra toda, e ainda não ouvi nenhum bipe.$B$BVocê pode ir lá dar uma olhada pra mim? Pode ser que ainda dê para consertar. O Eco Tê está instalado no extremo sudeste da Serra Cardo de Gelo. E nem queira saber o que aconteceu com o Eco Uni e o Duni.', '', '', '', '', '', '', '', '', '', '', 0),
(28631, 'ptBR', 'Os chifres perfeitos', 'Obtenha os Chifres Impolutos de Estrondo Gelado.', 'Não dá pra fazer um yeti sem chifres!$B$BJá estou procurando há tempos por um par perfeito de chifres... Só que nenhum dos que encontro presta! Um dia desses, vi o maior yeti de todos aqui de Hibérnia.$B$BEu chamei ele de Estrondo Gelado. Eu quero aqueles chifres! Ele fica malocado lá no fundo da caverna, perto da cordilheira leste da Serra Cardo de Gelo.$B$BPega lá os chifres... mas fica de olho no Eco Tê quando voltar!', '', '', '', '', '', '', 'Estrondo Gelado', '', '', 'Fale novamente com Umi Zombarruga em Visteterna, que fica em Hibérnia.', 0),
(28632, 'ptBR', 'Fresquinho direto da serra', 'Colete 7 Blocos de Gelo Puro da Geleira na caverna na Serra Cardo de Gelo.', 'Agora é gelo? Opa, pode deixar. Tenho uma boa e uma má notícia para você.$B$BA boa notícia é que há bastante gelo sólido na caverna da Serra Cardo de Gelo, bem ao leste de Visteterna. A má notícia é que também há muitos yetis violentos por lá.$B$BSe conseguir dar conta deles, vai ser moleza! Ande até os pedaços maiores e os solte com sua arma. Traga todos aqui que eu dou meu jeito.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rocas Calho em Visteterna, que fica em Hibérnia.', 0),
(28633, 'ptBR', 'O Baú da Promessa', 'Entregue a Brann Barbabronze o conteúdo do Baú da Promessa.', 'Não sei bem o que esperar daqui, então fica atent$go:a;, está bem?$b$bEstes códigos devem revelar o verdadeiro propósito do baú e nos presentear com as ferramentas que frustrarão de vez os esforços do Asa da Morte em Uldum!$b$bAfaste-se!', '', '', '', '', '', '', '', '', '', 'Fale com Brann Barbabronze no Berço dos Anciãos.', 0),
(28634, 'ptBR', 'Extinção', 'Mate 12 Ferujas Selvagens.', 'Ferujas... Criaturas desalmadas cobertas de penas, enviadas das mais escuras profundezas da Espiral Etérea para se alimentar dos fracos.$B$B<Nilson aponta para a mata que circunda a Torre Leste.>$B$BElas nos cercam por todos os lados e planejam um ataque - posso pressentir isso. Você deve impedi-las antes que se organizem para tal.$B$BQuero que você siga pela floresta e mate todas as ferujas que encontrar. NENHUMA DELAS DEVE SOBREVIVER!', '', '', '', '', '', '', '', '', '', 'Fale com Nilson Putrefacto na Torre Leste do Contraforte de Eira dos Montes.', 0),
(28635, 'ptBR', 'Uma assombração em Eira dos Montes', 'Vasculhe Dun Garok em busca de evidências de assombração.', 'A batalha por Dun Garok foi a mais sangrenta de todas as batalhas de Eira dos Montes. Os anões, em desvantagem de dez para um, lutaram até seu amargo fim. Um a um, foram sucumbindo em defesa daquele pedaço de terra.$B$BAgora ouço boatos de que o lugar está assombrado. Ninguém se aproxima de lá! Infelizmente, tenho ordens de preparar Dun Garok para habitação.$B$BVocê pode me fazer o favor de ir a Dun Garok e procurar evidências de assombração? Ela fica a sudeste.', 'Vasculhe Dun Garok em busca de evidências de assombração.', '', '', '', '', 'Vasculhe Dun Garok em busca de evidências de assombração.', '', '', '', 'Fale com o Fantasma do Capitão Monteferro em Dun Garok no Contraforte de Eira dos Montes.', 0),
(28636, 'ptBR', 'O silêncio dos anões', 'Mate 10 Espíritos de Dun Garok', 'Os espíritos de meus soldados assombram este forte agora, $gguri:guria;. Suas almas estão presas a este lugar. Mesmo mortos, eles continuam a lutar por ele. Que tristeza...$B$BLivre-os desta penúria e você poderá ficar com a pilhagem da vitória de seu povo.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Capitão Jekyll na Torre Leste do Contraforte de Eira dos Montes.', 0),
(28637, 'ptBR', 'Gostinho de urso', 'Mate 15 ursos Dentilhaços.', 'Você já se deu ao luxo de experimentar carne de urso? Nunca tive a chance de experimentar em Guilnéas, mas os ursos daqui são simplesmente fantásticos.$B$BOs ursos dentilhaços que perambulam ao sul têm a carne entremeada de gordura por causa do frio daqui. Eu costumava caçá-los, e acredite, é uma pândega, mas eu prefiro muito mais apenas saboreá-los!$B$BPor que você não vai lá ver como se sai na caça? Mate apenas os ursos dentilhaços de pele branca e o Capitão irá buscar todos que você derrubar.', '', '', '', '', '', '', '', 'Mmm... urso...', 'Francis Morcott', 'Fale novamente com Francis Morcott na Fogueira do Ralador, em Hibérnia.', 0),
(28638, 'ptBR', 'Corujas em alta', 'Mate 15 Corujas de Hibérnia.', 'Eu comi coruja minha vida toda. Comer coruja faz bem, e meu amigo Jez concorda. Fui eu quem falou pra ele vender coruja!$B$BO senhor worgen almofadinha aí diz que urso é mais gostoso, mas não liga pra ele não. Por que você não vai caçar umas corujas? Tem um monte voando ao sul daqui. Cace somente as cinzentas por enquanto e, quando você tiver um monte, me dá um toque com essa traquitana de falar que o Jez te deu.', '', '', '', '', '', '', '', 'Essa geringonça de falar tá me dando nó nas ideias.', 'Jeca Babu', '', 0),
(28639, 'ptBR', 'Úrsius', 'Mate Úrsius.', 'Ouvi dizer que somos o que comemos. Eu não sei se acredito nisso, mas, se for verdade... Prefiro comer as criaturas mais fortes que encontrar.$b$bO Úrsius é o maior urso de Hibérnia. Ele é o primeiro a comer quando a alcateia de dentilhaços dele lhe traz uma quimera ou uma corursa. Ele é o dono da caverna mais confortável nas terras dos dentilhaços. E ele tem... uma influência considerável nas fêmeas dentilhaços.$b$bGosto de ursos assim.$b$bQuero comer a carne dele.$b$bA caverna dele fica perto dos espancadores. Boa sorte!', '', '', '', '', '', '', 'Francis Morcott', '', '', 'Fale novamente com Francis Morcott na Fogueira do Ralador, em Hibérnia.', 0),
(28640, 'ptBR', 'Sabres-de-gelo geladinhos', 'Mate 15 Sabres-de-gelo ou Espreitadores Sabres-de-gelo.', 'Que cheiro bom, não é? As minhas carnes defumadas são as melhores, e ninguém mais oferece os mesmos sabores exóticos que eu encontrei aqui na serra. E a coisa toda é eficiente. Você caça os bichos em troca de uma pequena gratificação, e os meus amigos trazem as feras pra cá pra esfola e defumação!$B$BEu monopolizei o mercado de carne de Sabre-de-gelo. É absolutamente deliciosa, e dá umas salsichas excelentes. Vá lá caçar os felinos a oeste daqui, pra começo de conversa.', '', '', '', '', '', '', '', 'Caça que eu defumo!', 'Jez Ralador', '', 0),
(28641, 'ptBR', 'Orgulho da mesa de jantar', 'Mate 15 Caçadoras Sabre-de-gelo ou Vigias Sabre-de-gelo.', 'Então, jovem, hora de voltar para a lida!$B$BEssa caçada foi muito boa, mas há felinos ainda maiores a oeste. Os guardas e as caçadoras da alcateia são bem mais musculosos e dão um hambúrguer MARAVILHOSO. Eles vendem que nem água!$B$BMe dá um toque depois de fazer a limpa que vamos atrás do prato principal.', '', '', '', '', '', '', 'Jez Ralador', 'Ainda falta mais um!', 'Jez Ralador', '', 0),
(28643, 'ptBR', 'O desafio do Forte do Desterro: Zéfiro', 'Mate Zéfiro.', 'O Forte do Desterro sempre foi um local de discórdia. Por anos, os humanos o utilizaram como internato ou prisão para orcs. Depois disso, ele foi tomado pela Camarilha. Agora? A Dama Sombria capturou e alocou poderosos elementais entre suas muralhas. Ela me encarregou de administrar "O desafio do Forte do Desterro". Quem derrotar todos os elementais ganhará um grande prêmio! Tome estas instruções e encare seu primeiro desafio: Zéfiro!$B$BO Forte do Desterro fica a nordeste daqui.', '', '', '', '', '', '', 'Zéfiro', '', '', 'Fale com o Capitão Jekyll na Torre Leste do Contraforte de Eira dos Montes.', 0),
(28644, 'ptBR', 'O desafio do Forte do Desterro: Terácula', 'Mate Terácula.', 'De acordo com o manual, Terácula é seu próximo desafio. Ele perambula pelas redondezas do covil de Zéfiro.', '', '', '', '', '', '', 'Terácula', '', '', 'Fale com o Capitão Jekyll na Torre Leste do Contraforte de Eira dos Montes.', 0),
(28645, 'ptBR', 'O desafio do Forte do Desterro: Peçonhento', 'Mate Peçonhento.', 'De acordo com o manual, Peçonhento é seu próximo desafio. O temível elemental pode ser encontrado no nível inferior do Forte do Desterro, próximo às prisões ocidentais.', '', '', '', '', '', '', 'Peçonhento', '', '', 'Fale com o Capitão Jekyll na Torre Leste do Contraforte de Eira dos Montes.', 0),
(28646, 'ptBR', 'O desafio do Forte do Desterro: Infernus', 'Mate Infernus.', 'De acordo com as instruções, Infernus será seu próximo desafio. Este ser, feito de lava e fogo incontrolável, encontra-se no nível inferior do Forte do Desterro, próximo às prisões orientais.', '', '', '', '', '', '', 'Infernus', '', '', 'Fale com o Capitão Jekyll na Torre Leste do Contraforte de Eira dos Montes.', 0),
(28647, 'ptBR', 'O desafio do Forte do Desterro: D-1000', 'Mate D-1000.', 'Aprisionado na velha arena do Forte do Desterro, encontra-se um ser composto de puro mercúrio. Os Renegados o batizaram de D-1000. Mate-o e reivindique seu prêmio!', '', '', '', '', '', '', 'D-1000', '', '', 'Fale com o Capitão Jekyll na Torre Leste do Contraforte de Eira dos Montes.', 0),
(28649, 'ptBR', 'Uma surpresa especial', 'O Cavaleiro Comandante Pestecarpo, na Capela da Chama Carmesim, quer que você execute o Lorde Harford, um prisioneiro da Aurora Argêntea, dentro da prisão das redondezas.', 'Nós chegamos, destruímos o lugar e rumamos em direção à prisão. O que encontramos lá nos surpreendeu. Parece que a Cruzada anda bem ocupada. O lugar está cheio de prisioneiros da Aurora Argêntea. A maioria já estava morta quando chegamos, mas alguns ainda respiravam.$B$BEu estava indo lá para executar o resto, mas talvez você deva fazer as honras. Particularmente, um dos prisioneiros é um worgen problemático que, suponho, você terá bastante prazer em executar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Cavaleiro Comandante Pestecarpo na Capela da Chama Carmesim, que fica nas Terras Pestilentas: Enclave Escarlate.', 0),
(28650, 'ptBR', 'Uma surpresa especial', 'O Cavaleiro Comandante Pestecarpo, na Capela da Chama Carmesim, quer que você execute Guto Nadarguto, um prisioneiro da Aurora Argêntea, dentro da prisão das redondezas.', 'Nós chegamos, destruímos o lugar e rumamos em direção à prisão. O que encontramos lá nos surpreendeu. Parece que a Cruzada anda bem ocupada. O lugar está cheio de prisioneiros da Aurora Argêntea. A maioria já estava morta quando chegamos, mas alguns ainda respiravam.$B$BEu estava indo lá para executar o resto, mas talvez você deva fazer as honras. Particularmente, um dos prisioneiros é um goblin problemático que, suponho, você terá bastante prazer em executar.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Cavaleiro Comandante Pestecarpo na Capela da Chama Carmesim, que fica nas Terras Pestilentas: Enclave Escarlate.', 0),
(28651, 'ptBR', 'Noviça Elvira', 'Fale com a Noviça Elvira em Plangemortis, que fica nas Clareiras de Tirisfal.', 'Agora que o treinamento terminou, fale com Elvira. Ela serve ao Sacerdote Sombrio Sarvis e, provavelmente, terá algumas tarefas que podem trazer novas habilidades.', '', '', '', '', '', '', '', '', '', 'Fale com a Noviça Elvira em Plangemortis, que fica nas Clareiras de Tirisfal.', 0),
(28652, 'ptBR', 'Zelador Caice', 'Fale com o Zelador Caice nas Tumbas de Plangemortis, nas Clareiras de Tirisfal.', 'Não tenho mais assuntos a tratar com você. Existem, no entanto, outros que necessitam de seus serviços.$b$bZelador Caice, de pé sobre o tronco apodrecido logo atrás de mim, terá mais missões para você. Vá agora e fale com ele.', '', '', '', '', '', '', '', '', '', '', 0),
(28653, 'ptBR', 'Sacerdote sombrio Sarvis', 'Fale com Sacerdote Sombrio Sarvis em Plangemortis, que fica nas Clareiras de Tirisfal.', 'Ainda está aqui, $n? Sabe, eu sou só um Necroguarda. Não tenho muitas tarefas a realizar.$b$bRecomendo que fale com o Sacerdote Sombrio Sarvis. Lembro que ele me ajudou a entender as coisas quando saí da tumba. Estou certo que fará o mesmo com você.$b$bEle se encontra dentro da capela, do lado oeste da cidade.', '', '', '', '', '', '', '', '', '', '', 0),
(28654, 'ptBR', 'O xis da questão', 'Brann Barbabronze quer que você o encontre nos Salões Primordiais.', 'Bem, $gguri:guria;, parte de mim gostaria de poder ficar por aqui um pouco e apreciar a vista contigo.$b$bJá vi umas coisas bem impressionantes na minha época, mas essa aqui leva o prêmio.$b$bInfelizmente, preciso estudar um pouco estes discos antes de voltar aos Salões Primordiais.$b$bTu parece ter fibra... Que tal vir comigo e ver como um arqueólogo DE VERDADE trabalha, hein?', '', '', '', '', '', '', '', '', '', '', 0),
(28655, 'ptBR', 'O casamento do meu melhor Martelo Feroz', 'Fale com Genésio MacGraff para iniciar a cerimônia de casamento. Mate qualquer membro do Martelo do Crepúsculo que tentar interromper!', 'Estamos prontos, $n!$B$BMas tenho a impressão de que o Martelo do Crepúsculo pode tentar interromper a cerimônia e também desmoralizar e destruir os Martelo Feroz. As coisas podem ficar perigosas!$B$BPor isso, eu mesmo vou conduzir a cerimônia, para que possa ficar de olho nos noivos. Parece um plano pra ti? Ótimo!$B$BJá que o pai dela está morto e o irmão é padrinho, Fanny perguntou se tu pode entrar com ela na igreja. Quanta honra! Fale comigo quando estiver $gpronto:pronta;.', '', 'Núpcias Realizadas', '', '', '', '', '', '', '', 'Fale com Kurdran Martelo Feroz em Kirthaven, que fica no Planalto do Crepúsculo.', 0),
(28656, 'ptBR', 'Forças estranhas da vida', 'Fale com a Mandingueira Mau\'ari no Chalé Covaneve, em Hibérnia.', 'O corpo desta criatura liberou algum tipo de energia quando morreu. A energia entrou em você que, de algum modo, agora se sente mais forte.$b$bDe acordo com os habitantes de Hibérnia, a Mandingueira Mau\'ari, no Chalé Covaneve, é especialista na vida selvagem da região. Pode ser que ela saiba algo sobre essa energia misteriosa.', '', '', '', '', '', '', '', '', '', '', 0),
(28657, 'ptBR', 'Um enorme Pobrema', 'Você recebeu ordens para acabar com o Pobrema, um gorjala gigante que vaga pelas estradas de Tol Barad.', 'Finalmente capturamos essa rocha maldita, mas só agora percebemos que há um baita dum gorjala à solta, acabando com as nossas patrulhas!$B$B$n, reúna alguns amigos e mate-o. Não podemos permitir que uma fera dessas fique por aí causando problemas.$B$BFique alerta: pelo que dizem, ele carrega uma árvore gigantesca como arma e não tem medo de usá-la.', '', '', '', '', '', '', 'Pobrema', '', '', 'Apresente-se novamente ao Comandante Zanoth na Guarnição Baradin após cumprir a missão.', 0),
(28658, 'ptBR', 'Isca do pântano', 'Você recebeu ordens para coletar 8 Peles de Crocolisco dos Crocoliscos de Baradin, em Tol Barad. Os crocoliscos estão no pântano a oeste da Guarnição Baradin.', 'Encontrar suprimentos em um lugar como este nunca é fácil, $c. Estamos fazendo buscas desde que tomamos a ilha, mas os resultados não têm sido positivos.$B$BFelizmente, acabamos de receber informações de que há um pântano repleto de crocoliscos a oeste daqui. A pele deles será muito útil para os coureiros. Traga o máximo que puder.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Zanoth na Guarnição Baradin após cumprir a missão.', 0),
(28659, 'ptBR', 'Mais sobras', 'Você recebeu instruções para matar 12 Soldados de Infantaria da Aliança em Tol Barad. Os refugiados estão nos Escoriodutos, na Vigia do Guardião e na Guarnição Encouraçada.', 'Lutamos brutalmente para tomar esta ilha, $r. Conseguimos nos livrar da maior parte dos vermes da Aliança, mas ainda sinto o fedor deles no ar.$b$bQuero que você investigue os Escoriodutos, a Vigia do Guardião e a Guarnição Encouraçada. Mate todos os imbecis da Aliança que encontrar.$B$BComo é mesmo que dizem? Aliança boa é Aliança morta!', '', 'Soldado de Infantaria da Aliança', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Zanoth na Guarnição Baradin após cumprir a missão.', 0),
(28660, 'ptBR', 'Tirando o mofo', 'Você recebeu ordens para matar 9 fantasmas de qualquer tipo nas Profundezas Amaldiçoadas, logo a leste da Guarnição Baradin.', 'Você é um colírio para os meus olhos, $n. Conseguimos tomar Tol Barad, mas a batalha está apenas começando.$B$BDescobrimos uma prisão a leste daqui e precisamos que você faça uma limpeza nela. Acontece que o lugar está lotado de fantasmas, trancados lá desde o tempo da Jaka\'Cola com rolha.$b$bMate o máximo que conseguir e depois fale comigo novamente.', '', 'Fantasmas Exterminados', '', '', '', '', '', '', '', 'Fale novamente com o Recruta Garnoth, na Guarnição Baradin, após cumprir a missão.', 0),
(28661, 'ptBR', 'O arquimago trancafiado', 'Mate o Arquimago Galus nas Profundezas Amaldiçoadas e traga o Cajado dele. As Profundezas Amaldiçoadas ficam a leste da Guarnição Baradin.', 'Estamos tentando tirar os fantasmas da prisão das Profundezas Amaldiçoadas desde que atracamos em Tol Barad. Mas, sempre que chegamos perto, aquele maldito arquimago aparece e nos expulsa.$B$BAgora a ilha está sob nosso controle, então vamos tentar de novo para ver se muda alguma coisa. Vá lá e traga o cajado dele como prova de que você realizou o que não conseguimos.', '', '', '', '', '', '', 'Arquimago Galus', '', '', 'Fale novamente com o Recruta Garnoth, na Guarnição Baradin, após cumprir a missão.', 0),
(28662, 'ptBR', 'O passado também ensina', 'Você recebeu ordens de recuperar 4 Diários de Prisão Empoeirados das Profundezas Amaldiçoadas, bem a leste da Guarnição Baradin.', 'Finalmente conseguimos dominar esta ilha maldita, e agora podemos começar a investigar como ela ficou assim. Algumas das nossas tropas encontraram diários perto da entrada da prisão das Profundezas Amaldiçoadas, a leste daqui.$B$BAcho que os anciãos escribas do campo-base terão um interesse especial pela nossa descoberta. Quero que você me traga quatro diários o quanto antes.$B$B$n, tome bastante cuidado. A região está infestada de mortos-vivos.', '', '', '', '', '', '', '', '', '', 'Fale novamente com o Recruta Garnoth, na Guarnição Baradin, após cumprir a missão.', 0),
(28663, 'ptBR', 'Bloco D', 'Você recebeu instruções para matar 10 demônios de qualquer tipo no Bloco D, que fica a noroeste da Guarnição Baradin.', 'Já ouviu falar do Bloco D, $n? É um dos antigos blocos de prisão da ilha. O lugar está totalmente infestado por demônios. Estávamos planejando usá-lo para isolar o que sobrou da Aliança na ilha, mas, do jeito que está, não há condições.$B$BVá lá e acabe com os demônios. Fale comigo novamente quando terminar.', '', 'Demônios destruídos', '', '', '', '', '', '', '', 'Apresente-se ao Comandante-chefe Razgoth na Guarnição Baradin após cumprir a missão.', 0),
(28664, 'ptBR', 'Svarnos', 'Mate Svarnos no Bloco D e volte com a Coleira Maldita. Svarnos está no Bloco D, a noroeste da Guarnição Baradin.', '$c, você fez um excelente trabalho na captura da ilha. Agora, que temos o controle total, precisamos preparar os blocos da prisão para nossos prisioneiros. O Bloco D é o que está dando mais trabalho, por causa dos vários tipos de demônios.$B$BConseguimos reduzir a quantidade de demônios, mas um dos cães-magma conseguiu sair da cela e está fazendo um estrago sério. Preciso que você o mate e me traga a coleira dele.', '', '', '', '', '', '', 'Svarnos', '', '', 'Apresente-se ao Comandante-chefe Razgoth na Guarnição Baradin após cumprir a missão.', 0),
(28665, 'ptBR', 'Grilhões Amaldiçoados', 'Você recebeu ordens para recolher 8 Grilhões Amaldiçoados no Bloco D, que fica a noroeste da Guarnição Baradin.', 'Já foi ao Bloco D, $n? Cansamos de tirar os demônios de lá, mas eles voltam toda hora. Descobrimos que eles conseguem se regenerar por causa dos grilhões amaldiçoados que estão espalhados na região. É aí que você entra, $n.$B$BPreciso que você recolha o máximo de grilhões que puder e os traga para mim. Nós os destruiremos imediatamente.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Comandante-chefe Razgoth na Guarnição Baradin após cumprir a missão.', 0),
(28666, 'ptBR', 'O chamado do heroísmo: Estepes Ardentes!', 'Apresente-se a John J. Keeshan no Acampamento Flamestrela, que fica nas Estepes Ardentes.', 'Por ordem de sua Majestade Real, o rei Varian Wrynn, todos os cidadãos capazes da Aliança devem se apresentar a John J. Keeshan no Posto Flamestrela.$B$BSua ajuda está sendo requisitada para dar um fim à ameaça dos orcs Rocha Negra!$B$BPara chegar às Estepes Ardentes, siga pelo sul, passando pela Garganta Abrasadora, até chegar à Montanha Rocha Negra. O Posto Flamestrela fica do lado mais distante da montanha.$B$BHonra e glória à Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28667, 'ptBR', 'Comando do Chefe Guerreiro: Estepes Ardentes!', 'Apresente-se a Ariok no Acampamento Flamestrela, que fica nas Estepes Ardentes.', 'Todos os membros aptos da Horda são por esta intimados a se apresentarem a Ariok no Posto Flamestrela.$B$BO honrado filho de Eitrigg, Ariok, precisa de sua ajuda para impedir a agressão gratuita dos orcs Rocha Negra antes que eles invadam as terras vizinhas.$B$BPara chegar às Estepes Ardentes, siga pelo sul, passando pela Garganta Abrasadora, até chegar à Montanha Rocha Negra. O Posto Flamestrela fica na parte sul da montanha.$B$BO Destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28668, 'ptBR', 'Revolta na Prisão', 'Você recebeu instruções para matar 10 prisioneiros de qualquer tipo no Presídio da Grande Ilha, que fica a sudoeste da Guarnição Baradin.', 'Já dominamos a ilha. Agora temos que usar os recursos dela. Encontramos um bloco de prisão abandonado a sudoeste daqui, e quero que você vá verificar o estado dele.$B$BSegundo os relatórios, esse bloco é controlado por prisioneiros que estão lá há anos. Faça o que for preciso para liberar o local. Fale comigo novamente depois que estiver tudo pronto.', '', 'Prisioneiros mortos', '', '', '', '', '', '', '', 'Apresente-se ao Terceiro-sargento Lázaro na Guarnição Baradin após cumprir a missão.', 0),
(28669, 'ptBR', 'Matança no Cárcere', 'Mate o Carcereiro Silva no Presídio da Grande Ilha e pegue as chaves dele. O Presídio da Grande Ilha fica a sudoeste da Guarnição Baradin.', 'Estamos quase terminando de nos livrar dos prisioneiros do Presídio da Grande Ilha, mas ainda temos um problema: o carcereiro.$b$bO carcereiro Silva é o mestre dos prisioneiros, que farão de tudo para protegê-lo. Se derrotarmos o Silva, os derrotamos todos. Mate-o e traga-me as chaves dele. Poderemos usá-las para explorar as partes mais baixas da prisão e, com sorte, teremos acesso à fonte de água da ilha.', '', '', '', '', '', '', 'Carcereiro Silva', '', '', 'Apresente-se ao Terceiro-sargento Lázaro na Guarnição Baradin após cumprir a missão.', 0),
(28670, 'ptBR', 'O que vem de baixo me alimenta', 'Você recebeu ordens para recuperar 12 Rações da Prisão no Presídio da Grande Ilha, que fica a sudoeste da Guarnição Baradin.', 'A nossa comida está acabando, $n. Recentemente descobrimos que a prisão a sudoeste daqui ainda tem um bom estoque de rações, mesmo após anos de uso. Quero que você recolha o máximo que puder e traga tudo para o campo-base.$B$BAh, mais uma coisa. A prisão está lotada de prisioneiros, então tome cuidado.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Terceiro-sargento Lázaro na Guarnição Baradin após cumprir a missão.', 0),
(28671, 'ptBR', 'Ordens do Chefe Guerreiro: Barreira do Inferno!', 'Apresente-se à Okrilla no Domínio de Malhorrendo, que fica na Barreira do Inferno.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, obrigados a se apresentar a Okrilla, comandante das tropas da Horda no Domínio de Malhorrendo. Ela requisita sua ajuda para proteger o posto avançado contra os ogros insurretos e as forças da Aliança.$B$BPara chegar ao Domínio de Malhorrendo, basta tomar a estrada ao sul do Pântano das Mágoas.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28672, 'ptBR', 'O executor em campo', 'Apresente-se ao Executor Arren.', 'Posso $gmantê-lo ocupado:mantê-la ocupada; durante toda a semana aqui na cidade... Mas você parece ser mais do tipo guerreir$go:a;.$b$b<Elvira olha para você e balança a cabeça.>$b$bSim, você se sairá bem. Quero que fale com o Executor Arren. Siga o caminho ao norte, fora de Plangemortis. Você o encontrará logo após as barricadas.', '', '', '', '', '', '', '', '', '', 'Apresente-se ao Executor Arren em Plangemortis, que fica nas Clareiras de Tirisfal.', 0),
(28673, 'ptBR', 'O chamado ao heroísmo: Barreira do Inferno!', 'Apresente-se ao Intendente Lungertz na Bastilha de Etergarde.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar ao intendente Lungertz na Bastilha de Etergarde.$B$BA guarnição de Etergarde precisa urgentemente de sua ajuda para deter o avanço da Horda na Barreira do Inferno! Siga para o sul, partindo do Pântano das Mágoas, e siga a estrada em direção ao leste para chegar na Bastilha de Etergarde.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28674, 'ptBR', 'Aldeia Chuva Estelar', 'Fale com Eol Correnoite na Aldeia Chuva Estelar.', 'Você andou muito $gocupado:ocupada; por aqui. Se você ainda estiver a fim de fazer boas ações, ou de faturar um dinheirinho, pode ser que se interesse na minha proposta.$B$BA Aldeia Chuva Estelar fica bem ao noroeste de Visteterna. Os elfos noturnos recentemente sofreram uma infestação de insetos bem horrível, e estão precisando de toda a ajuda possível.$B$BAlguns goblins daqui já foram para lá e começaram a investigar, mas aquilo que abunda nunca atrapalha. Fale com Eol Correnoite. Ele contará os detalhes.', '', '', '', '', '', '', '', '', '', '', 0),
(28675, 'ptBR', 'O chamado ao heroísmo: Pântano das Mágoas!', 'Apresente-se ao Barão Mercador Romprata no Brejo do Goblin, que fica no Pântano das Mágoas.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em bom estado físico devem apresentar-se ao Barão Mercador Romprata no Brejo do Goblin.$B$BAs forças da Aliança necessitam urgentemente das munições fornecidas pelo barão! Deve ser feito o que preciso for para convencer o barão a vender-nos suprimentos a preços razoáveis.$B$BPara chegar ao pântano, siga a estrada do sudeste das Estepes Ardentes pelas Montanhas Cristarrubra.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28676, 'ptBR', 'Cuidado: dedetização em curso', 'Fale com Rinno Flamifervente dentro da Gruta de Ban\'Thallow.', 'A infestação nas nossas grutas aconteceu praticamente da noite para o dia. Criaturas violentas que nunca tínhamos visto infestaram os túneis, saltando de ovos não vistos.$B$BComo éramos poucos, o máximo que deu para fazer foi impedi-las de sair da gruta. Fomos obrigados a contratar goblins de Visteterna, que se diziam especialistas em dedetização, mas ainda não tiveram sucesso.$B$BSe você quiser ajudá-los, entre na gruta a oeste deste alojamento e fale com Rinno Flamifervente.', '', '', '', '', '', '', '', '', '', '', 0),
(28677, 'ptBR', 'Ordens do Chefe Guerreiro: Pântano das Mágoas!', 'Apresente-se ao Barão Mercador Romprata no Brejo do Goblin, que fica no Pântano das Mágoas.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, convocados para apresentar-se ao Barão Mercador Romprata no Brejo do Goblin.$B$BPersuadam o barão mercador a manter o fornecimento das armas e munições requeridas por nossos guerreiros, não importa a que preço!$B$BViaje ao Pântano das Mágoas seguindo a estrada a sudeste das Estepes Ardentes por dentre as Montanhas Cristarrubra e encontre o barão mercador em seu recanto litorâneo.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28678, 'ptBR', 'Capitão P. Espargosa', 'Você recebeu ordens para matar o Capitão P. Espargosa no Cabo da Má Esperança, que fica a noroeste daqui, seguindo pela costa. Procure os navios naufragados.', 'Já faz semanas que o Cabo da Má Esperança tem sido um estorvo aqui em Tol Barad. Metade dos navios de suprimentos naufraga por causa daquelas rochas.$b$bComo se isso não bastasse, o cabo é dominado por uma gangue de marujos mortos-vivos. Fizemos de tudo para enfraquecê-los, mas eles continuam voltando e voltando. O nosso último recurso é liquidar o capitão deles. Ele deve estar em um dos navios próximos à costa.$b$bAh, espero que você não tenha medo de tubarões...', '', '', '', '', '', '', 'Capitão P. Espargosa', '', '', 'Apresente-se novamente ao Terceiro Oficial Kronkar no Domínio do Grito Infernal após cumprir a missão.', 0),
(28679, 'ptBR', 'O navio dos mortos-vivos', 'O Terceiro Oficial Kronkar pediu para você matar 8 Marinheiros Náufragos no Cabo da Má Esperança. O cabo fica a noroeste daqui, na praia.', 'Já faz um tempo que temos problemas com os mortos-vivos do Cabo da Má Esperança. Cada vez que um navio naufraga, eles recrutam mais zumbis.$b$bSerá que você poderia nos fazer o favor de matar alguns deles? Sei muito bem que não vai dar para acabar com todos, mas qualquer ajuda é muito bem-vinda.$b$bAh, mais uma coisa, $n. Segundo informações, a Aliança tem feito emboscadas na praia. Tome bastante cuidado.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Terceiro Oficial Kronkar no Domínio do Grito Infernal após cumprir a missão.', 0),
(28680, 'ptBR', 'Levantando o moral', 'Você recebeu ordens para recuperar 6 Barris de Rum dos Mares do Sul nos navios naufragados no Cabo da Má Esperança. O cabo fica a norte daqui, seguindo pela costa.', 'O moral anda baixo, $n. Estamos fazendo de tudo para animar as tropas, mas o estoque do nosso principal levantador de moral está quase no fim... Estamos quase sem rum!$b$bOs relatórios da infantaria afirmam que há muito rum dentro dos navios naufragados no Cabo da Má Esperança. Será que você poderia ir lá investigar?$b$bTraga todos os barris de rum que encontrar!', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Terceiro Oficial Kronkar no Domínio do Grito Infernal após cumprir a missão.', 0),
(28681, 'ptBR', 'Tubarão Adamastor', 'Você recebeu ordens para matar Adamastor, um tubarão enorme que aterroriza as águas do Cabo da Má Esperança. O cabo fica ao norte, seguindo pela costa.', 'Odeio tubarões. Todos os meus soldados odeiam tubarões também. É aí que você entra, $n.$b$bVá ao Cabo da Má Esperança e mate um tubarão imenso chamado Adamastor. Ele não está para brincadeira, então acho melhor você levar alguns amigos.', '', '', '', '', '', '', 'Adamastor', '', '', 'Apresente-se novamente ao Terceiro Oficial Kronkar no Domínio do Grito Infernal após cumprir a missão.', 0),
(28682, 'ptBR', 'A retomada do Forte', 'Você recebeu ordens para matar o Castelão Farson no Forte Farson, que fica no norte da ilha.', 'Você viu o forte no norte da ilha, $n? É de lá que o castelão Farson organiza a operação.$b$bFarson tem um pequeno grupo de seguidores dedicados que são um grande problema para nós desde que chegamos aqui. Enviamos alguns homens para investigar, e eles nos informaram a posição exata de Farson dentro do forte.$b$bSerá que você consegue dar um fim nele?', '', '', '', '', '', '', 'Castelão Farson', '', '', 'Apresente-se novamente ao Comandante Larmash no Domínio do Grito Infernal após cumprir a missão.', 0),
(28683, 'ptBR', 'Terrível contra as aranhas', 'Mate 12 Espreitadoras Lenhanegra em Lenhanegra. A floresta Lenhanegra fica a norte daqui, do outro lado da ponte, na ilha central.', 'Estamos tentando estabelecer uma base na Lenhanegra há semanas, mas o lugar está infestado de aranhas. Faça-me um favor e mate algumas, para que a gente possa montar um ataque.$b$bTome cuidado. No começo da semana, ouvi dizer que as tropas da Aliança estavam rondando por lá.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Terceiro Oficial Kronkar no Domínio do Grito Infernal após cumprir a missão.', 0),
(28684, 'ptBR', 'Uma tarefa pegajosa', 'Colete 4 Glândulas de Seda Pegajosa das Prolemadres Lenhanegra. A floresta Lenhanegra fica a oeste daqui, do outro lado da ponte, na ilha central.', 'Encontrar suprimentos aqui na ilha anda cada vez mais difícil.$b$bFelizmente, demos a sorte de encontrar uma boa quantidade de seda na Lenhanegra, a norte daqui. O problema é que a seda vem das glândulas das aranhas prolemadres. Traga-me 4 glândulas.$b$bIsso deve ser suficiente para terminarmos mais um lote de camisas.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Terceiro Oficial Kronkar no Domínio do Grito Infernal após cumprir a missão.', 0),
(28685, 'ptBR', 'Armas recauchutadas', 'Obtenha 12 Rifles Enferrujados no Forte Farson, que fica no norte da Península de Tol Barad.', 'Não encontramos muitos suprimentos de batalha nesta rocha esquecida. Parece que estamos enfrentando a Aliança com paus e pedras.$B$BDe acordo com os relatórios, o castelão Farson tem um estoque enorme de rifles que poderia vir a calhar. Você pode ir lá e dar uma olhada?$b$bTome cuidado, $n. Os seguidores do Farson farão de tudo para protegê-lo.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Larmash no Domínio do Grito Infernal após cumprir a missão.', 0),
(28686, 'ptBR', 'Vizinhança nada amistosa', 'O Comandante Larmash pediu para você matar 14 aldeões na Vila Montanha da Ferrugem, que fica a norte do campo-base, pelo lado direito.', 'Você foi à Vila Montanha da Ferrugem, $n? Então siga o meu conselho: não deixe de levar uma espada bem afiada se for passar lá perto.$b$bO povo da vila parece ser calmo, mas há algo que não cheira bem. Os relatórios que recebemos dizem que eles estão atacando os nossos soldados. Não aguentamos mais isso, e precisamos que você faça uma limpa por lá.$B$BMate o máximo que puder e volte aqui depois que terminar.', '', 'Moradores da Vila Montanha da Ferrugem', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Larmash no Domínio do Grito Infernal após cumprir a missão.', 0),
(28687, 'ptBR', 'Ensine um homem a pescar... ou roubar', 'Roube 22 Percas da Vila Montanha da Ferrugem. Os peixes estão nos varais das docas, na parte de trás da vila. A Vila Montanha da Ferrugem fica a norte do campo-base, pelo lado direito.', '$n, a Vila Montanha da Ferrugem é uma bênção e uma maldição para nós. Não faço ideia de como aqueles bandidos aprenderam a pescar tão bem, mas isso não importa.$B$BVá à vila e roube o máximo que puder dos estoques de peixe. Estamos vivendo de migalhas desde que retomamos a ilha, e essa é a nossa melhor chance de conseguir um bom estoque de comida.$B$BTome cuidado com os espreitadores. Segundo informações, há muitos deles dentro da vila.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Comandante Larmash no Domínio do Grito Infernal após cumprir a missão.', 0),
(28688, 'ptBR', 'Ordens do Chefe Guerreiro: Selva do Espinhaço Setentrional!', 'Apresente-se ao Comandante Aggro\'gosh, no Acampamento Grom\'gol, que fica na Selva do Espinhaço Setentrional.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, intimados a se apresentar ao comandante Aggro\'gosh, no Acampamento Grom\'gol. O Comandante requisita o seu auxílio para manter as rotas de suprimentos livres da interferência de habitantes locais e insolentes da Aliança.$B$BPara chegar a Grom\'gol, embarque em um zepelim a partir da torre de zepelins a leste de Orgrimmar ou da torre da Cidade Baixa.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28689, 'ptBR', 'Os esquecidos', 'Liberte os espíritos de 6 almas atormentadas na Colina Esquecida. As almas são canalizadas ao se tocar as lápides com as mãos. A Colina Esquecida fica a oeste daqui, depois da Lenhanegra e do Front Incansável.', 'Vários soldados pereceram nesta ilha, $n. É mais do que justo demonstrarmos nosso respeito a eles da melhor forma possível.$b$bQuero que você vá à Colina Esquecida, a oeste daqui, e livre as almas atormentadas dos nossos irmãos deste lugar penoso. Tome bastante cuidado. Recebemos relatos de mortos-vivos na região.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Capitão Prug no Domínio do Grito Infernal após cumprir a missão.', 0),
(28690, 'ptBR', 'Enterro dos ossos', 'Recupere 9 Fêmures Amaldiçoados dos carniçais que vagam na Colina Esquecida, que fica no oeste da ilha, pouco depois do Front Abandonado.', 'Há vários zumbis e carniçais vagando pela Colina Esquecida desde que conquistamos esta ilha sórdida. Tentamos nos livrar deles várias vezes, mas eles sempre voltam.$b$bUm dos tenentes sugeriu pegar os ossos dos carniçais, depois de matá-los, para que não consigam reencarnar à noite. Podemos contar com a sua ajuda?', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Capitão Prug no Domínio do Grito Infernal após cumprir a missão.', 0),
(28691, 'ptBR', 'Primeiro-tenente Cunha', 'Encontre e mate o Primeiro-tenente Cunha na Colina Esquecida. A Colina Esquecida fica no extremo oeste da ilha.', 'Eu era um mero recruta nas Cavernas Ígneas quando ouvi falar do tenente Cunha pela primeira vez. Ninguém acreditava que ele tivesse vindo para Tol Barad. Infelizmente ele ainda vaga por estas ilhas sórdidas e isso derruba o moral das tropas.$b$bPreciso você que dê um fim ao sofrimento dele... e ao nosso.', '', '', '', '', '', '', 'Primeiro-tenente Cunha', '', '', 'Apresente-se novamente ao Capitão Prug no Domínio do Grito Infernal após cumprir a missão.', 0),
(28692, 'ptBR', 'Como funcionam os ímãs?', 'Você foi $Gencarregado:encarregada; de recuperar 7 peças de Sucata da Máquina de Cerco. Use o Coletor de Sucata Magnetizado para encontrar as peças no Front Incansável, que fica a oeste, pouco depois da segunda ponte.', 'Arranjar peças de máquinas anda cada vez mais difícil aqui na ilha, $n. Estamos tentando consertar as máquinas de cerco defeituosas aqui no acampamento, mas as peças boas estão acabando.$b$bO segundo regimento informou que há algumas máquinas de cerco abandonadas em um antigo campo de batalha a oeste. Acho que deve ter algumas peças boas por lá.$B$BVai ser difícil achar qualquer coisa em meio a um antigo campo de batalha, então leve este coletor de sucata magnetizado e veja se ele ainda serve para alguma coisa.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Capitão Prug no Domínio do Grito Infernal após cumprir a missão.', 0),
(28693, 'ptBR', 'Feche o caixão', 'Mate 5 Soldados Inquietos no Front Incansável, que fica no oeste da ilha, pouco antes da Colina Esquecida.', 'Passamos a semana toda tentando coletar mais sucata aproveitável no front, mas sempre que completamos uma remessa, somos atacados pelos soldados inquietos daquela área. Seria muito útil se você pudesse ir até lá acabar com todos eles.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Capitão Prug no Domínio do Grito Infernal após cumprir a missão.', 0),
(28694, 'ptBR', 'Não ande descalço!', 'O Recruta Sarlosk pediu para você recolher 15 feixes de Lenha do Estaleiro no Estaleiro Bonfilho. A lenha pode ser recolhida do chão ou com os fantasmas. O estaleiro fica a noroeste daqui, na costa.', '$n, você já foi ao Estaleiro Bonfilho? Acho que é melhor você nem chegar perto, a menos que tenha um bom motivo. Só que... É justamente para lá que quero que você vá.$b$bEstamos com poucos suprimentos desde que retomamos a ilha. O estaleiro está cheio de fantasmas, mas também há bastante lenha nele. Já enviamos vários grupos para tentar pegar um pouco, mas nenhum deles voltou.$b$bPodemos contar com a sua ajuda?', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Recruta Sarlosk no Domínio do Grito Infernal após cumprir a missão.', 0),
(28695, 'ptBR', 'PROCURA-SE: encarregado Bonfilho', 'Mate o Encarregado Bonfilho no Estaleiro Bonfilho. O estaleiro fica a norte daqui, na costa oeste.', 'O encarregado Bonfilho tem sido um estorvo desde que chegamos aqui. Os suprimentos do estaleiro dele nos seriam muito úteis... Só falta ir lá pegar.$b$bEle fica de olho nos funcionários o tempo todo, e isso atrapalha bastante os nossos planos. Você tem que dar um fim nele. Tome cuidado, $n. Recebemos informações de que a Aliança está por toda a parte.', '', '', '', '', '', '', 'Encarregado Bonfilho', '', '', 'Apresente-se novamente ao Recruta Sarlosk no Domínio do Grito Infernal após cumprir a missão.', 0),
(28696, 'ptBR', 'Lançar bombas!', 'Destrua 10 Barcos de Suprimentos Medonhos.', 'O Estaleiro Bonfilho sempre recebe suprimentos pelo mar... Precisamos acabar com isso. Há vários canhões defensivos nas docas e, se você conseguir chegar até eles, poderá usá-los para destruir os barcos de suprimentos.$B$BVá lá e veja o que você pode fazer. Depois me informe como está o andamento da missão.', '', 'Barcos de Suprimentos Medonhos destruídos', '', '', '', '', '', '', '', 'Apresente-se novamente ao Recruta Sarlosk no Domínio do Grito Infernal após cumprir a missão.', 0),
(28697, 'ptBR', 'Caça-fantasmas', 'Mate 14 fantasmas de qualquer tipo no Mirante do Largo, que fica a nordeste da base da Horda.', 'Está vendo as torres naquela colina a nordeste? Ali é o Mirante do Largo. Acampar lá perto é praticamente suicídio. Estamos tendo problemas com espíritos e espectros desde que montamos o acampamento.$b$bVocê poderia ir até lá para mostrar a eles que viemos para ficar? Eu acho que, se você matar alguns, eles vão andar na linha direitinho.$b$bObrigado pela ajuda, $n.', '', 'Fantasmas mortos no Mirante do Largo', '', '', '', '', '', '', '', 'Apresente-se novamente ao Recruta Sarlosk no Domínio do Grito Infernal após cumprir a missão.', 0),
(28698, 'ptBR', 'Bala de canhão!', 'Você precisa recuperar 4 Pilhas de Balas de Canhão para o Recruta Sarlosk no Mirante do Largo, que fica a nordeste do campo-base.', 'Largo e os lacaios dele estão roubando nossos suprimentos desde que montamos o acampamento. Você não imagina a frustração.$b$bOuvimos dizer que ele está estocando balas de canhão nas torres com vista para as águas do mirante. Será que você poderia ir lá e recuperar algumas?$b$b$n, não se esqueça de manter o olho aberto com a Aliança também.', '', '', '', '', '', '', '', '', '', 'Apresente-se novamente ao Recruta Sarlosk no Domínio do Grito Infernal após cumprir a missão.', 0),
(28699, 'ptBR', 'O chamado ao heroísmo: Selva do Espinhaço Setentrional!', 'Apresente-se ao Tenente Doren, no Acampamento dos Rebeldes, que fica na Selva do Espinhaço Setentrional.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar ao tenente Doren, no Acampamento dos Rebeldes.$B$BAnos após a traição do coronel Kurzen contra Ventobravo, a verdade por trás dos fatos permanece um mistério. Ajude os sobreviventes a descobrir o que aconteceu ao Coronel. Para chegar ao Acampamento dos Rebeldes, vá em direção ao sul, partindo da Floresta do Crepúsculo, e, ao entrar na floresta, siga a estrada a oeste.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28700, 'ptBR', 'O mirante é nosso, aha, uhu!', 'O Recruta Sarlosk pediu para você matar o Comandante Largo, no Mirante do Largo. O mirante fica a nordeste do campo-base.', 'Só há uma forma de recuperar o Mirante do Largo.$b$bLargo anda bem paranoico hoje em dia, e deve estar no topo da torre, esperando a chegada da frota imaginária dele. Você já sabe o que precisa ser feito, $n.', '', '', '', '', '', '', 'Comandante Largo', '', '', 'Apresente-se novamente ao Recruta Sarlosk no Domínio do Grito Infernal após cumprir a missão.', 0),
(28701, 'ptBR', 'Evitando o perigo', 'Recupere 5 Relíquias da Aldeia Chuva Estelar na Gruta de Ban\'Thallow.', 'Felizmente, no momento da infestação não havia druidas hibernando na parte oeste da gruta. Lá ainda é um local sagrado para o nosso povo, e há relíquias abençoadas e intocadas há séculos.$B$BPor mais que eu confie até certo ponto nos exterminadores goblínicos, eu também já ouvi falar... nos costumes da raça deles. Recupere quaisquer relíquias que encontrar na gruta e as traga a mim para que não sejam danificadas. Estão dentro de urnas protegidas, abrigadas nas pequenas alcovas da gruta.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Eol Correnoite na Aldeia Chuva Estelar, em Hibérnia.', 0),
(28702, 'ptBR', 'O chamado do heroísmo: Cabo do Espinhaço!', 'Apresente-se a Bronwyn Talho na Escavação da Liga dos Exploradores, que fica no Cabo do Espinhaço.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos fisicamente capazes da Aliança devem se apresentar a Bronwyn Talho na Escavação da Liga dos Exploradores.$B$BA expedição da Liga dos Exploradores precisa de sua ajuda para proteger a área da escavação e os artefatos dos ogres saqueadores. Siga para o sul, partindo da Selva do Espinhaço Setentrional, e siga a estrada até a Escavação da Liga dos Exploradores.$B$BHonra e glória à Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28703, 'ptBR', 'Venha para a minha gruta', 'Mate 10 Rastejantes Gelespreita e 5 Entocadores Gelespreita.', 'Ainda não faço a menor ideia de onde esses insetos podem ter vindo. O meu palpite é que o cataclismo perturbou alguns ninhos subterrâneos que nós desconhecíamos.$B$BMas não perca seu tempo pensando nisso na hora de matá-los!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Rino Flamifervente na Gruta de Ban\'Thallow, em Hibérnia.', 0),
(28704, 'ptBR', 'Ordens do Chefe Guerreiro: Cabo do Espinhaço!', 'Apresente-se a Espoleta Chaveforte no Esconderijo da Chaveforte, que fica no Cabo do Espinhaço.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, convocados a se apresentar a Espoleta Chaveforte no Esconderijo da Chaveforte. Ela necessita de toda ajuda para lidar com os piratas e nagas que infestaram a floresta.$B$BPara chegar ao Esconderijo da Chaveforte, siga para o sul da Selva do Espinhaço Setentrional e procure pela cidade a sudoeste da Arena de Gurubashi.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28705, 'ptBR', 'Ordens do Chefe Guerreiro: Terralém!', 'Apresente-se ao Tenente-general Órion nos Degraus do Destino, que fica na Península Fogo do Inferno.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, intimados a se apresentar para o tenente-general Órion, nos Degraus do Destino.$B$BSuas aptidões são necessárias para repelir a presença da Legião Ardente nos resquícios despedaçados de Terralém.$B$BVá até o Antro das Sombras em Orgrimmar e use o portal próximo aos instrutores de magos para chegar à Barreira do Inferno.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28706, 'ptBR', 'Passa o spray', 'Leve a Caixa de Fumigadores de Extermínio de Insetos para Remma Flamifervente dentro da Gruta de Ban\'Thallow.', 'As minhas irmãs entraram mais fundo na gruta para cuidar dos insetos, e já estão começando a perder terreno. Tá na hora de tacar gás na coisa toda.$B$BLeve estes fumigadores. Não os ative por conta própria, só um profissional com o ritmo certo consegue usar direito. Encontre as minhas irmãs e lhes entregue os fumigadores.$B$BA Remma deve ser quem está mais perto da entrada. Siga pelo corredor e continue pela direita depois de descer a rampa.', '', '', '', '', '', '', '', '', '', '', 0),
(28707, 'ptBR', 'Passa o spray... de novo', 'Leve a Caixa de Fumigadores de Extermínio de Insetos para Marcy Flamifervente dentro da Gruta de Ban\'Thallow.', 'Vou começar a preparar o negócio.$B$BLeve o próximo para a Marcy, avançando pela gruta. Siga pelo corredor e procure por ela na próxima câmara principal.', '', '', '', '', '', '', '', '', '', '', 0),
(28708, 'ptBR', 'O chamado ao heroísmo: Terralém!', 'Apresente-se ao Comandante Durão nos Degraus do Destino, que fica na Península Fogo do Inferno.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar ao comandante Durão, na Península Fogo do Inferno.$B$BAs forças expedicionárias estão solicitando a sua ajuda para vencer os exércitos demoníacos da Legião Ardente! Use o portal no pavimento central da torre no Distrito dos Magos para chegar aos Degraus do Destino, em Terralém.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28709, 'ptBR', 'O chamado ao heroísmo: Nortúndria!', 'Fale com o Oficial de Recrutamento Blythe na Bastilha Valentia, que fica na Tundra Boreana.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem se apresentar ao oficial de recrutamento Blythe na Bastilha Valentia, que fica na Tundra Boreana.$B$BA Expedição Valentia precisa de você para ajudar a controlar as forças do Flagelo e resguardar as terras ocupadas! Para chegar à Bastilha Valentia, embarque no navio que segue para norte, nas Docas de Ventobravo.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28710, 'ptBR', 'Passa o spray... de novo novamente', 'Leve a Caixa de Fumigadores de Extermínio de Insetos para Sana Flamifervente na Gruta de Ban\'Thallow.', 'Bem que o Rinno podia ter mandado mais que $gum único:uma única; $r para dar uma força! Aquele abeiro...$B$BVou montar este aqui. Siga pro norte, passe pelo corredor e fale com a Sana. Ela deve ter se perdido na última câmara, então dê uma olhada nas passagens laterais quando chegar lá.', '', '', '', '', '', '', '', '', '', '', 0),
(28711, 'ptBR', 'Ordens do Chefe Guerreiro: Nortúndria!', 'Apresente-se ao Oficial de Recrutamento do Brado Guerreiro na Fortaleza Brado Guerreiro, que fica na Tundra Boreana.', 'Todos os membros da Horda em boas condições físicas estão, por meio deste, obrigados a se apresentar ao oficial de recrutamento Brado Guerreiro na Fortaleza Brado Guerreiro.$B$BA Ofensiva Brado Guerreiro precisa de você para triunfar sobre a incessante ameaça dos mortos-vivos do Flagelo.$B$BPegue o zepelim para a Fortaleza Brado Guerreiro na torre oeste de zepelins em Orgrimmar e apresente-se ao oficial de recrutamento.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28712, 'ptBR', 'Operação rainha dragonesa', 'Procure Lirastrasza no Círculo da Vida, que fica no Planalto do Crepúsculo.', 'Olá, $r. Gostaria de $gtê-lo:tê-la; conhecido em melhores circunstâncias. O mundo está por um fio e tudo o que os titãs forjaram corre sério risco.$B$BMuito me entristece, mas minha palavra é decisiva. Asa da Morte – a horrível criatura que já foi o Guardador da Terra e também meu amigo – deve ser destruído.$B$BPreparei um local no topo do Planalto, a oeste do Rubro Reduto, onde posso acabar com isso. Procure o Círculo da Vida e fale com Lirastrasza. Encontrarei você lá.', '', '', '', '', '', '', '', '', '', '', 0),
(28713, 'ptBR', 'O equilíbrio da natureza', 'Mate 6 Sabres-da-noite Jovens.', 'Saudações, $n. Meu nome é Ilthalaine. Meu propósito em Umbravale é treinar jovens elfos noturnos como você para garantir que o equilíbrio da natureza seja mantido.$B$BEste ano, as chuvas de primavera foram inclementes e, enquanto algumas feras se deleitavam, outras sofriam. Infelizmente, a população de sabres-da-noite cresceu de tal maneira que, se não a reduzirmos, eles devastarão as outras criaturas.$B$BVá, jovem $c, diminua a população de sabres para que a harmonia da natureza seja mantida.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ithalaine em Umbravale.', 0),
(28714, 'ptBR', 'A corrupção do limo vil', 'Colete 6 unidades de Limo Vil dos Capetas a oeste de Ithalaine.', 'Você parece saber o que faz. Talvez eu possa $Gincumbi-lo:incumbi-la; de uma tarefa mais importante.$B$BComo você deve saber, a corrupção de Teldrassil foi supostamente eliminada, mas traços dela ainda perduram. As criaturas ainda não se acalmaram e continuamos sendo atormentados por toda sorte de problemas.$B$BPreciso que você cuide de um ajuntamento de capetas a oeste daqui e, enquanto estiver por lá, veja se no corpo deles há algo que chamamos de limo vil. Isso me ajudará a descobrir de onde vem essa corrupção persistente.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Ithalaine em Umbravale.', 0),
(28715, 'ptBR', 'Ladrões demoníacos', 'Recupere as Bolsas Roubadas de Melithar na região habitada pelos Capetas a oeste.', 'Malditos capetas! Eles andaram roubando nossas despensas de novo.$B$BEles com certeza levaram minhas bolsas para o acampamento deles a oeste. Se puder me dar uma mãozinha, traga-me tudo de volta e eu $Go:a; recompensarei.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Melithar Guenelmo em Aldrassil.', 0),
(28716, 'ptBR', 'O chamado ao heroísmo: Planalto do Crepúsculo', 'Fale com o Rei Varian Wrynn na Bastilha Ventobravo, que fica em Ventobravo.', 'Por ordem de Sua Majestade o Rei Varian Wrynn, todos os cidadãos da Aliança em boas condições físicas devem apresentar-se na sala do trono na Bastilha Ventobravo.$B$BO Rei Wrynn precisa de um herói de confiança para uma missão de suma importância.$B$BA Bastilha Ventobravo fica na região leste da cidade.$B$BPela honra e glória da Aliança!', '', '', '', '', '', '', '', '', '', '', 0),
(28717, 'ptBR', 'Ordens do Chefe Guerreiro: Planalto do Crepúsculo!', 'Apresente-se a Vol\'jin no Castelo Grommash, que fica em Orgrimmar.', 'Todos os membros da Horda em bom estado físico estão, por meio deste, obrigados a apresentar-se a Vol\'jin no Castelo Grommash.$B$BO Chefe Guerreiro solicita ajuda de todos para o glorioso ataque ao Planalto do Crepúsculo e aos nossos inimigos: a Aliança e o Martelo do Crepúsculo.$B$BEncontre o Chefe Guerreiro no Castelo Grommash, que fica no centro do Vale da Força em Orgrimmar.$B$BO destino chama!', '', '', '', '', '', '', '', '', '', '', 0),
(28718, 'ptBR', 'Onde há fumaça, há carne deliciosa', 'Encontre Jez Ralador no Fumeiro do Ralador, em Hibérnia.', 'E então, $c? Você gosta de carne? Melhor ainda: você gosta de dinheiro?$b$bTenho um primo de segundo grau que está faturando uma grana preta com carne congelada. Ele está montando um fumeiro ao norte, e está procurando gente para caçar as feras perigosas que costumam ter um gosto tão bom.$b$bTem bastante dinheiro nisso, $gamigo:amiga;. Eu já investi demais nisto aqui... Onde é que eu estava com a cabeça? Acho melhor passar a dica para $gum:uma; $r $gempreendedor:empreendedora; assim como você.$b$bO nome do meu primo é Jez. Siga para nordeste e procure pela fumaça!', '', '', '', '', '', '', '', '', '', '', 0),
(28719, 'ptBR', 'Um pouco forte', 'Mate 15 Espancadores Dentilhaços.', 'Muitos acham que a carne dos ursos dentilhaços é um pouco forte. Já eu discordo, porém gosto não se discute.$b$bPor outro lado, os espancadores dentilhaços, os primos de pele marrom deles, têm uma carne bem mais macia, especialmente nas patas. E eu ouvi dizer que o focinho também é considerado uma iguaria.$b$bContinue a caçada, $n. Vamos ver se você arruma alguns espancadores para o velho Francis.', '', '', '', '', '', '', 'Francis Morcott', 'Esse urso aí é carne de primeira.', 'Francis Morcott', 'Fale novamente com Francis Morcott na Fogueira do Ralador, em Hibérnia.', 0),
(28721, 'ptBR', 'Trabalho no cangote dos outros é refresco', 'Escolte um Prisioneiro do Forte Farson para um local seguro. O forte fica no extremo norte da ilha.', 'Enviamos pelo menos três grupos de reconhecimento para investigar o Forte Farson nas últimas semanas. Infelizmente nenhum deles voltou ainda, e não temos informações do que está acontecendo.$B$BA essa altura, já até estou torcendo para que eles tenham sido feitos prisioneiros e estejam bem. Você precisa se infiltrar na bastilha e ajudar a resgatar os soldados. Não será fácil, $n, mas você é a nossa última chance.', 'Prisioneiro de Farson escoltado', '', '', '', '', 'Prisioneiro de Farson escoltado', 'Prisioneiro de Farson', '', '', 'Apresente-se novamente ao Comandante Larmash no Domínio do Grito Infernal após cumprir a missão.', 0),
(28722, 'ptBR', 'Yetifobia', 'Assuste Legacki com o Yeti Mecânico da Umi.', 'Está tudo preparado, $n!$B$BJá falei pra minha amiga Legacki que tenho uma surpresa pra ela. É aí que você entra!$B$BVou deixar o meu yeti mecânico com você, e você terá a honra de usar ele para surpreender a Legacki. Ela está no outro lado de Visteterna, perto da estalagem.$B$BVá até lá e ligue o yeti... Vou ficar olhando daqui!', '', 'Assuste Legacki', '', '', '', '', '', '', '', 'Fale novamente com Umi Zombarruga em Visteterna, que fica em Hibérnia.', 0),
(28723, 'ptBR', 'A sacerdotisa da Lua', 'Fale com Dantaria Clarargêntea no meio dos dois lagos, no centro de Umbravale.', 'Agora que já dominou algumas técnicas, talvez esteja $Gdisposto:disposta; a nos ajudar a eliminar a corrupção que empesteia Umbravale.$B$BDantaria Clarargêntea, uma sacerdotisa da Lua, nos ofereceu auxílio. Ela se encontra entre os dois lagos ao norte da grande árvore. Dê a volta na árvore para encontrá-la e ofereça seus serviços a ela, jovem $c.', '', '', '', '', '', '', '', '', '', '', 0),
(28724, 'ptBR', 'O antídoto de Iverron', 'Colete 7 Lírios Lunapétala.', 'Nosso amigo Iverron foi envenenado pelas aranhas lenhateia das redondezas. Estou tratando dele para impedir o avanço do veneno, mas preciso que alguém me traga um ingrediente para que eu possa preparar um antídoto.$B$BEm volta dos lagos há uma flor chamada lírio lunapétala. Essa flor contém propriedades medicinais incríveis. Se eu as misturar com os outros ingredientes que tenho, posso restaurar a saúde de Iverron.$B$BVocê pode trazê-las para mim? Deve haver muitas à vista por aqui, perto da margem do lago.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dantaria Clarargêntea no meio dos lagos de Umbravale.', 0),
(28725, 'ptBR', 'O protetor dos bosques', 'Encontre a dríade conhecida por Tarindrella no interior da Caverna Fionumbra, na extremidade norte de Umbravale.', 'Eu $Go:a; incumbirei de uma tarefa mais perigosa. Os espíritos sussurrantes da floresta me trouxeram notícias estranhas. A misteriosa protetora dos bosques, Tarindrella, regressou a Umbravale.$B$BDesde a bênção de Teldrassil, a presença da dríade não é sentida na floresta. Sua volta indica que há algo de errado.$B$BEncontre-a na caverna Fionumbra, ao norte. Será perigoso, mas preparei este antídoto para $Gprotegê-lo:protegê-la;.', '', '', '', '', '', '', '', '', '', '', 0),
(28726, 'ptBR', 'A corrupção das Lenhateia', 'Mate 12 Aranhas Lenhateia.', 'Esperava não ser trazida a Teldrassil para tratar de algo tão lamentável. Tinha esperanças de que houvessem eliminado a corrupção por completo, mas algo de decadente ainda jaz sobre esta terra.$B$BAs aranhas têm sofrido muito mais do que as outras criaturas das redondezas. Elas se tornaram perigosas para o seu povo e para a floresta. Precisamos diminuir seu número e, mais importante, precisamos descobrir a fonte da corrupção que as amaldiçoa.$B$BEu lhe ajudarei.', '', '', '', '', '', '', '', '', '', 'Fale com Tarindrella no interior da Caverna Fionumbra, que fica em Umbravale.', 0),
(28727, 'ptBR', 'Toque de torpeza', 'Mate Githyiss, a Torpe, na extremidade norte da Caverna Fionumbra.', 'Se as aranhas já nascem com a corrupção correndo em suas veias, então a prolemadre deve ser a raiz de todo o mal.$B$BVamos abrir caminho até o fundo da caverna até encontrarmos Githyiss, a Torpe. Ela tem as respostas que buscamos.', '', '', '', '', '', '', 'Githyiss, a Torpe', '', '', 'Fale com Tarindrella no interior da Caverna Fionumbra, que fica em Umbravale.', 0),
(28728, 'ptBR', 'O presságio do que está por vir', 'Fale com Dantaria Clarargêntea entre os lagos que ficam ao norte de Umbravale.', 'Vou seguir os rastros dos Masca-pinho e rastrear a origem da corrupção. Se um dia o seu caminho cruzar com o de Athridas Mantursino em Dolanaar, saiba que ele conhece bem os problemas que assolam a floresta e pode lhe dar orientações sobre como ajudar mais.$B$BEstou certa de que nos encontraremos de novo. Talvez você possa me ajudar a cuidar da origem da corrupção, uma vez que eu a encontre. Por ora, vamos voltar a Dantaria para que possa finalizar seu treinamento. Obrigada por tudo que fez, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(28729, 'ptBR', 'Teldrassil: a coroa de Azeroth', 'Encha o Frasco de Cristal no poço lunar a nordeste de Umbravale.', 'Para completar seu treinamento, é preciso passar por um ritual e parte dele é aprender nossa história recente.$B$BHá uma tarefa que precisa ser realizada. Vá ao poço lunar a noroeste e encha um frasco com água. Enquanto o faz, vislumbrará nossa magia e aprenderá sobre o nosso passado.$B$BQuando tiver terminado, volte com a água e eu lhe darei as próximas instruções.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Dantaria Clarargêntea no meio dos lagos, ao norte de Umbravale.', 0),
(28730, 'ptBR', 'Águas preciosas', 'Leve o Frasco de Cristal Cheio a Tenaron Fortagarras, no topo de Aldrassil, que fica em Umbravale.', 'Tenaron Fortagarras vê tudo o que se passa na clareira. Ele reside no topo de Aldrassil.$B$BSe olhar ao sul, verá o início da rampa que leva a ele. Suba, $n, e terá acabado seu treinamento.$B$BFoi maravilhoso $Gtê-lo:tê-la; conhecido, $n. Enche-me de orgulho saber que há jovens elfos noturnos altruístas e vigorosos como você. Ainda fará muito por nosso povo. Fará muito pelo mundo.$B$BAté o dia em que nos encontrarmos de novo.', '', '', '', '', '', '', '', '', '', '', 0),
(28731, 'ptBR', 'Teldrassil em estado de alerta', 'Leve o Recipiente Parcialmente Cheio a Corithras Lunafúria em Dolanaar.', 'Ainda tenho muito a dizer sobre os poços lunares e sobre Teldrassil, mas você precisa ir. Corithras Lunafúria $Go:a; aguarda. Passei a água que me trouxe para este outro vidro, que você deve levar a ele.$B$BCorithras se encontra no poço lunar de Dolanaar. Siga a estrada ao sul de Aldrassil até sair de Umbravale, continue seguindo os paralelepípedos e vire ao oeste.$B$BAconselho que não saia da estrada, $n. Ultimamente, feras perigosas andam rondando a floresta.', '', '', '', '', '', '', '', '', '', '', 0),
(28732, 'ptBR', 'Só pode significar uma coisa...', 'Use a Máquina Toupeira do Finco para chegar à Montanha Rocha Negra.', 'Eu e Raz nos inscrevemos nos Guardiões de Hyjal para investigar o reaparecimento de Ragnaros neste mundo. Nós vamos na frente para confirmar se ele voltou e o quão furioso está! Também temos evidências de que os sectários do Martelo do Crepúsculo estão levando os elementais daqui para a Caverna Rocha Negra, lá nos Reinos do Leste.$B$BNós estamos de saída e só tem lugar para mais um na máquina toupeira. Se quiser nos acompanhar, encontre-nos lá dentro para começarmos nossa jornada.', 'Vá à Caverna Rocha Negra.', '', '', '', '', 'Vá à Caverna Rocha Negra.', '', '', '', 'Encontre Jonas Tiragosto dentro da Caverna Rocha Negra, na Montanha Rocha Negra.', 0),
(28733, 'ptBR', 'Instinto botânico', 'Sobreviva a uma Onda Imensa de Zumbis.', 'SOCORRO! SOCORRO! Mortos-vivos descontrolados estão atacando minha fazenda! Aquele carcereiro psicopata dos campos lodosos deve ser o responsável por esta bagunça. Ajude-me a derrotar estes zumbis!', '', 'Onda Imensa sobrevivida', '', '', '', '', '', '', '', 'Fale com o Botânico Zeca Rioka na Fazenda do Zeca, no Contraforte de Eira dos Montes.', 0),
(28734, 'ptBR', 'Um favor para Melithar', 'Fale com Melithar Guenelmo em Umbravale.', 'Procure Melithar. Se não me engano, ele também está tendo problemas com os capetas.$B$BSe o ajudar, creio que ele $Go:a; recompensará com uma bolsa e você terá mais espaço para guardar suas coisas.', '', '', '', '', '', '', '', '', '', '', 0),
(28735, 'ptBR', 'Para a Câmara de Incineração!', 'Mate Rom\'ogg Esmaga-ossos.', 'Foi uma cilada, $n! Assim que chegamos, um ogro balofo chamado Rom\'ogg Esmaga-ossos nos atacou! Raz me defendeu bravamente enquanto eu corria para me esconder. Eu vi quando eles o acertaram em cheio e o levaram para um lugar que o gordão chamou de "Câmara da Incineração". Acho que fica no final desse corredor, depois da ponte.$B$BNão tenho coragem de ir até lá. Tome, leve meu capacete de mergulho multitarefa e encontre Raz. Vou falando com você pelo capacete.$B$BAh, se achar aquele ogro, mate-o!', '', '', '', '', '', '', 'Rom\'ogg Esmaga-ossos', 'Siga o Raz!', 'Jonas Tiragosto', 'Fale com Jonas Tiragosto dentro da Caverna Rocha Negra, na Montanha Rocha Negra.', 0),
(28736, 'ptBR', 'Fogo do céu', 'Suba a bordo da Artilharia Confiscada e use-a para matar 100 Soldados de Infantaria de Schnottz.', 'Os restos da organização de Schnottz persistem aqui, na Encosta do Criador, fazendo dessa região uma área mortal para todos que se aproximam.$b$bTemos bastante munição, mas sem um bom avistador estou atirando às cegas.$b$bEntra aqui e me dá uma mão. Aqueles soldados não vão nem saber o que os acertou!', '', 'Soldados de Infantaria mortos', '', '', '', '', '', '', '', 'Fale com o Nômade Experiente no Precipício do Peregrino.', 0),
(28737, 'ptBR', 'Que lugar é esse?', 'Mate Corla, o Arauto do Crepúsculo.', '<O capacete do Finco lhe dá um choque fraco.>$B$BQue lugar é esse? Parece que estão fazendo algo terrível com aquele dragão etéreo. Estão transferindo a energia dele para aquela moça! Precisamos interromper o ritual!$B$BMate Corla para passar desse salão.', '', '', '', '', '', '', 'Corla, o Arauto do Crepúsculo', 'Não temos tempo a perder! Raz precisa da nossa ajuda!', 'Jonas Tiragosto', 'Fale com Jonas Tiragosto dentro da Caverna Rocha Negra, na Montanha Rocha Negra.', 0),
(28738, 'ptBR', 'Forja do Crepúsculo', 'Mate Karsh Dobraferro.', '<O capacete do Finco zumbe como estivesse sendo energizado.>$B$BMas que droga! Raz não cansa! Parece que ele está possuído e só pensa em vingança contra tudo que é do Crepúsculo! Bom, se a gente quer passar por essa sala, vamos ter que acabar com o armoreiro crepuscular, Karsh Dobraferro. Vamos logo, $n! Mate ele!', '', '', '', '', '', '', 'Karsh Dobraferro, Armoreiro Crepuscular', 'Raz está por perto. Posso ouvi-lo!', 'Jonas Tiragosto', 'Fale com Jonas Tiragosto dentro da Caverna Rocha Negra, na Montanha Rocha Negra.', 0),
(28739, 'ptBR', 'Night Elf Class Skill Tracker Quest', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28740, 'ptBR', 'Não acredito no que estou vendo!', 'Mate Bela.', '<O capacete do Finco emite um grito de mulher.>$B$BNÃO ACREDITO! Eu... eu fiquei preso dentro de uma daquelas feras por quase um mês. Isso mesmo, dentro do estômago! Se não fosse minha roupa e meu capacete multitarefa, estaria frito literalmente! E... olha só aquilo! Tem uma ninhada inteira de filhotes!$B$BVoc... você precisa dar um jeito nisso, $n! Não podemos deixar que os filhotes saiam daqui vivos!', '', '', '', '', '', '', 'Bela', 'Vai me poupar anos de terapia.', 'Jonas Tiragosto', 'Fale com Jonas Tiragosto dentro da Caverna Rocha Negra, na Montanha Rocha Negra.', 0),
(28741, 'ptBR', 'Lorde Ascendente Obsidius', 'Mate o Lorde Ascendente Obsidius.', '<O capacete do Finco zumbe.>$B$BCrocoliscos me mordam! Olha só esse lugar! Aqu... aquilo ali no teto são marcas das garras do Asa da Morte?! E o que é aquela criatura no meio da câmara?$B$BNão vejo Raz por aqui. Vamos acabar com esse monstro e continuar nossa procura!', '', '', '', '', '', '', 'Lorde Ascendente Obsidius', '', '', 'Fale com Jonas Tiragosto dentro da Caverna Rocha Negra, na Montanha Rocha Negra.', 0),
(28742, 'ptBR', 'Shy-Rotam', 'Mate Shy-Rotam.', 'Hora da caçada grande, $gxará:mocinha;! Shy-Rotam, a maior de todos os sabre-de-gelo, espreita ao norte.$B$BVocê deveria se sentir $ghonrado:honrada;. Não há presa que teste mais as habilidades de um caçador... E se você visse quanta grana os gourmands daqui estão oferecendo por um pedaço dela, seus olhos iam saltar das órbitas!$B$BDepois que você abater a fera, volte ao acampamento. Não queremos extinguir toda a população de sabres-de-gelo num só dia, não é?', '', '', '', '', '', '', 'Shy-Rotam', '', '', 'Fale novamente com Jez Ralador na Fogueira do Ralador, em Hibérnia.', 0),
(28744, 'ptBR', 'Cadê a sementinha que estava aqui?', 'Sobreviva a 2 Ondas Imensas de Zumbis.', 'Você é craque nisso, $n! $GUm:Uma; aprendiz de botânico nat$Go:a;! Ouça, tenho uma nova semente para testar chamada rochídea. Use-a para deter os mortos-vivos. Apenas jogue-as e elas irão detê-los pelo caminho. Os mortos-vivos são uns tolos!$B$BVamos testar!', '', 'Onda Imensa sobrevivida', '', '', '', '', '', '', '', 'Fale com o Botânico Zeca Rioka na Fazenda do Zeca, no Contraforte de Eira dos Montes.', 0),
(28745, 'ptBR', 'A fim das guinchadoras', 'Mate 15 Guinchadoras de Hibérnia.', 'As corujinhas são boas, mas o Ralador diz que tem umas maiores mais pro sul. O pessoal chama elas de guinchadoras... Elas fazem uma barulheira danada quando você mexe com elas!$B$BMas ele diz que são as melhores corujas que já provou e vendeu, e eu acredito nele. Por que você não vai lá pegar algumas enquanto fico aqui discutindo com o Francis?', '', '', '', '', '', '', 'Jeca Babu', 'Essa geringonça de falar tá me dando nó nas ideias.', 'Jeca Babu', '', 0),
(28746, 'ptBR', 'Incursão às defesas inimigas', 'Consiga acesso à Sala de Controle Titânica.', 'Lá vamos nós, $n!$b$bDo outro lado daquela porta fica a sala de controle.$b$bVou entrar correndo, desativar o mecanismo de recriação e, então, vamos para casa. Fácil e simples.$b$bTu verá, $grapaz:moça;, é este nível de preparo que separa o arqueólogo de verdade do caçador de tesouros comum.$b$bNão faz sentido provocar as feras se não precisamos. Isso só complica as coisas...', '', 'Sala de Controle Titânica invadida', '', '', '', '', '', '', '', 'Fale com Brann Barbabronze na Cripta das Luzes, que fica nos Salões Primordiais.', 0),
(28747, 'ptBR', 'Alguém armou a bombóbora', 'Sobreviva a 2 Ondas Imensas de Zumbis.', 'Já viu uma dessas antes?$B$B<Zeca mostra uma abóbora.>$B$BIsto não é uma abóbora comum, $gamigo:amiga;. Veja, quando você a planta, ela fica à espera de um zumbi e então CABUM! Tripas de zumbi por todos os cantos. Vamos!', '', 'Onda Imensa sobrevivida', '', '', '', '', '', '', '', 'Fale com o Botânico Zeca Rioka na Fazenda do Zeca, no Contraforte de Eira dos Montes.', 0),
(28748, 'ptBR', 'O jardim dos esquecidos', 'Derrote o Carcereiro Calmágua.', 'CALMÁGUA! ELE ESTÁ QUASE AQUI! Vamos precisar de tudo o que temos para abatê-lo! Vamos detê-lo!', '', 'Carcereiro Calmágua derrotado', '', '', '', '', '', '', '', 'Fale com o Botânico Zeca Rioka na Fazenda do Zeca, no Contraforte de Eira dos Montes.', 0),
(28749, 'ptBR', 'A batalha por Andorhal', 'Fale com o Mago de Guerra Erallier para ser teleportad$go:a; para Andorhal, que fica nas Terras Pestilentas Ocidentais. Ao chegar lá, apresente-se a Thassarian, em Andorhal.', 'Nós acabamos de receber um grifo com notícias das Terras Pestilentas, e elas não são nada boas. A cidade de Andorhal está no meio de uma guerra envolvendo três forças: os Renegados, a Aliança e o Flagelo. O Rei Wrynn jogou com a sorte e enviou um cavaleiro da morte para liderar o ataque em prol da causa dele, mas tenho certeza de que toda ajuda será bem-vinda.$b$bEles solicitaram especificamente $gum:uma; $c da Aliança para participar de uma missão especial. Se você resolver aceitar essa incumbência, fale comigo novamente e eu prepararei um portal para você.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Thassarian em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(28750, 'ptBR', 'A batalha por Andorhal', 'Fale com o Arcanista Arman para ser teleportad$go:a; para Andorhal, que fica nas Terras Pestilentas Ocidentais. Ao chegar lá, apresente-se a Koltirus Tecemorte em Andorhal.', 'Nós acabamos de receber uma mantícora com notícias das Terras Pestilentas, e elas não são nada boas. A cidade de Andorhal está no meio de uma guerra tríplice entre os Renegados, a Aliança e o Flagelo. Parece que Sylvana fez seu primeiro movimento, e pra deixar as coisas mais interessantes, ela colocou Koltirus Tecemorte, o cavaleiro da morte, para liderar o ataque.$b$bEles solicitaram especificamente $gum:uma; $c da Horda para participar de uma missão especial. Se você resolver aceitar essa incumbência, fale comigo novamente e eu prepararei um portal para você.', '', '', '', '', '', '', '', '', '', 'Apresente-se a Koltirus Tecemorte em Andorhal, que fica nas Terras Pestilentas Ocidentais.', 0),
(28751, 'ptBR', 'Cuidando do jardim', 'Sobreviva a 2 Ondas Imensas de Zumbis.', 'Mesmo derrotando o Carcereiro Calmágua, seus zumbis continuam vagando pelos campos. Olhe, outro bando se aproxima! Ajude-me a lutar contra eles, $Gparceiro:parceira;! Vamos lá!', '', 'Onda Imensa derrotada', '', '', '', '', '', '', '', 'Fale com o Botânico Zeca Rioka na Fazenda do Zeca, no Contraforte de Eira dos Montes.', 0),
(28753, 'ptBR', 'Fazendo do jeito mais difícil', 'Brann Barbabronze quer que você mate Isiset, Ammunae, Setesh e Rajh.', 'Que tudo se exploda!$b$bAlguém foi e corrompeu o sistema inteiro! Não tenho como acessar o repositório principal a partir desse console.$b$bVamos ter que fazer isso do jeito mais difícil, $gguri:guria;. Espero que tu e teus amigos estejam dispostos a lutar.$b$bExistem quatro guardiões no andar mais alto deste lugar. Não terei como utilizar estes discos até que eles estejam... Bem, off-line, por assim dizer.', '', 'Isiset morto', 'Ammunae morto', 'Rajh morto', 'Setesh morto', '', '', '', '', 'Fale com Brann Barbabronze na câmara mais alta dos Salões Primordiais.', 0),
(28755, 'ptBR', 'Anais do Punho de Prata', 'Vá para Stratholme e recupere um dos volumes perdidos dos Anais do Punho de Prata.', 'Você sabe quem foram os Cavaleiros do Punho de Prata? Eles foram os primeiros paladinos da Luz, e de suas fileiras vieram os cavaleiros que mais tarde se juntaram à Aurora Argêntea ou à Cruzada Escarlate. Embora muitos tenham seguido o caminho do mal, eles ainda possuem valiosas relíquias do Punho de Prata.$B$BNos confins de Stratholme, sob os olhos vigilantes do instrutor Galford, muitos volumes dos Anais do Punho de Prata sobreviveram. Qualquer volume que você recuperar será de grande ajuda para a Capela Esperança da Luz!', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lorde Raimundo George na Capela Esperança da Luz.', 0),
(28756, 'ptBR', 'Aberrações ósseas', 'Mate Ossorrange no Ossuário de Scolomântia.', 'De todas as forças do Flagelo que eu e meus irmãos enfrentamos em nossas vidas nenhuma foi mais ultrajante do que os necromantes. Eles não se contentaram em reanimar nossos mortos e usá-los contra nós. Não... também criaram seres ósseos degenerados com foices no lugar das mãos.$B$BPerdi muitos companheiros na luta contra tais criaturas e, por isso, peço a você, $n, que termine aquilo que começamos. Vá até o Ossuário de Scolomântia e mate a maior e mais perigosa criatura dos necromantes.', '', '', '', '', '', '', '', '', '', 'Fale novamente com Lorde Raimundo George na Capela Esperança da Luz.', 0),
(28757, 'ptBR', 'É hora de reagir', 'Mate 6 Worgs Rocha Negra.', 'Então você é $Go novo:a nova; recruta $Genviado:enviada; por Ventobravo, hein? Sou o major Belmonte, comandante desta guarnição. É um prazer $Gtê-lo:tê-la; a bordo...$B$B<Belmonte mexe na papelada.>$B$B$n. É $n, certo?$B$BVocê chegou na horta certa. Os orcs Rocha Negra conseguiram entrar em Vila Norte através de uma fenda na montanha. Meus soldados estão fazendo todo o possível para detê-los, mas receio que seremos sobrepujados em breve.$B$BVá até a floresta a noroeste e mate os worgs da Rocha Negra! Ajude os soldados!', '', '', '', '', '', '', 'Worg de Batalha da Rocha Negra', '', '', 'Fale novamente com o Major Belmonte na Abadia de Vila Norte, que fica na Floresta de Elwynn.', 0),
(28758, 'ptBR', 'À sombra do destino', 'Monte em um Vandragão Rubro e mate 8 Dracovultos do Crepúsculo.', 'Alexstrasza e Asa da Morte rumaram aos céus sobre Grim Batol! O plano dela está se elucidando – a Rainha Dragonesa está fora do Círculo da Vida que preparou mais cedo. Temos que ajudá-la com tudo o que temos.$B$BDepressa! Monte em um dos vandragões rubros daqui de trás.$B$BSe encontrarmos dracos do crepúsculo ajudando Asa da Morte, teremos que dar um fim a eles. Suba, rápido!', '', '', '', '', '', '', '', '', '', 'Apresente-se para Calen no Rubro Reduto, que fica no Planalto do Crepúsculo.', 0),
(28759, 'ptBR', 'Leões e cordeiros', 'Mate 8 Espiões Rocha Negra.', 'Os orcs que invadiram nossas terras não são nada estúpidos. Eles estão nos avaliando para escolherem a melhor hora de atacar.$B$BHá vários espiões Rocha Negra espalhados pela parte noroeste da floresta. Eles estão nos observando com lunetas, atentos a cada movimento, e esperando. Quero que você acabe com isso!$B$BMate os espiões Rocha Negra! Nós temos que mostrar a eles que sabemos que estamos sendo observados e que estamos preparados para a luta!', '', '', '', '', '', '', 'Espião Rocha Negra', '', '', 'Fale novamente com o Major Belmonte na Abadia de Vila Norte, que fica na Floresta de Elwynn.', 0),
(28760, 'ptBR', 'Vingança para Orsis', 'Mate Asaad.', 'A grande cidade de Orsis foi atacada pelos exércitos do ar.$B$BNós fomos feitos prisioneiros... tivemos sorte.$B$BA maior parte morreu, presa sob as sufocantes areias do deserto.$B$BAsaad, o califa de Al\'Akir, ordenou o ataque... e ele deve pagar com a vida.', '', '', '', '', '', '', 'Asaad, Califa dos Zéfiros', '', '', 'Fale novamente com Itesh no Pináculo do Vórtice.', 0),
(28761, 'ptBR', 'Honor the Flame', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28762, 'ptBR', 'É hora de reagir', 'Mate 6 Worgs Rocha Negra.', 'Então você é $Go novo:a nova; recruta $Genviado:enviada; por Ventobravo, hein? Sou o major Belmonte, comandante desta guarnição. É um prazer $Gtê-lo:tê-la; a bordo...$B$B<Belmonte mexe na papelada.>$B$B$n. É $n, certo?$B$BVocê chegou na hora certa. Os orcs Rocha Negra conseguiram entrar em Vila Norte através de uma fenda na montanha. Meus soldados estão fazendo todo o possível para detê-los, mas receio que seremos sobrepujados em breve.$B$BVá até a floresta a noroeste e mate os worgs da Rocha Negra! Ajude os soldados!', '', '', '', '', '', '', 'Worg de Batalha da Rocha Negra', '', '', 'Fale novamente com o Major Belmonte na Abadia de Vila Norte, que fica na Floresta de Elwynn.', 0),
