(28775, 'ptBR', 'Estatueta de serpente quebrada', 'Conserte a estatueta quebrada usando sua perícia e os materiais necessários.', 'Alguém jogou fora esta estatueta completamente quebrada. Entretanto, com os materiais certos e seus conhecimentos em joalheria, você pode restaurá-la.', '', '', '', '', '', '', '', '', '', 'Texto de conclusão.', 0),
(28776, 'ptBR', 'Estatueta terrena quebrada', 'Conserte a estatueta quebrada usando sua perícia e os materiais necessários.', 'Alguém jogou fora esta estatueta completamente quebrada. Entretanto, com os materiais certos e seus conhecimentos em joalheria, você pode restaurá-la.', '', '', '', '', '', '', '', '', '', 'Texto de conclusão.', 0),
