(25785, 'esMX', 'Rómpete el coco', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(25786, 'esMX', 'Rómpete el coco', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(25787, 'esMX', 'Rómpete el coco', '', '', '', '', '', '', '', '', '', '', '', '', 0),
