(27556, 'esMX', 'El aceite para armas de Gidwin', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27557, 'esMX', 'Dije de Tarenar', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27558, 'esMX', 'La muñeca de Pamela', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27559, 'esMX', 'Bandas de Vex\'tul', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27560, 'esMX', 'El diario de Argus', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27561, 'esMX', 'La piedra de Rimblat', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27562, 'esMX', 'El engranaje de Beezil', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27563, 'esMX', '[FLAG] Beezil\'s Flag', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27564, 'esMX', 'En defensa del Reducto', 'Habla con Calen en el Reducto Bermellón.', 'Calen ha enviado un mensaje: ¡los Crepusculares están en el Reducto!$B$BSi hay una ocasión en la que puedas ganarte su favor, ¡es esta!', '', '', '', '', '', '', '', '', '', '', 0),
(27565, 'esMX', 'En la prisión', 'Encuentra a Kevin Dawson.', '¡Hemos logrado infiltrarnos en la prisión Hierro Negro!$b$bBueno... es posible.$b$bKevin Dawson ha tenido el... honor... de descubrir lo que estaba pasando allí dentro, y no hemos vuelto a saber de él. Tú tienes pinta de que no te gusta morir, ¡así que deberías ir a ver si está bien!$b$bSe supone que está en la sala del extremo sur de la caverna que hay más adelante... Aunque algo me dice que podría no haber llegado tan lejos.', '', '', '', '', '', '', '', '', '', '', 0),
(27566, 'esMX', 'Una reunión en Terrallende', 'Habla con Gavan Plumagrís en el Trono de los Elementos en Nagrand.', 'Saludos, $c. Los elementos están cada vez más inquietos y nosotros no parece que avancemos en la solución del problema. Algunos de nuestros chamanes más sabios se han reunido en Nagrand, en el Trono de los Elementos, para debatir sobre lo que enferma nuestras tierras.$b$bDirígete al Trono de los Elementos y habla con Gavan Plumagrís; seguro que tiene alguna misión para ti.', '', '', '', '', '', '', '', '', '', 'Habla con: Gavan Plumagrís. Zona: Trono de los Elementos, Nagrand.', 0),
(27567, 'esMX', '¡¿Crepúsculo?! ¡No!', '"Interroga" a la alta interrogadora Gerstahn.', 'Cuesta un poco creerlo, ¡pero aquí en las Profundidades de Roca Negra hay miembros del Martillo Crepuscular! No sé cuántos hay arrastrándose por este lugar, pero he oído que su interrogadora principal, Gerstahn, está en este pasillo.$b$bNo sé para qué están torturando aquí, ¿pero a lo mejor te puedes enterar si te enfrentas a Gerstahn?', '', '', '', '', '', '', 'Alta interrogadora Gerstahn', '', '', 'Vuelve con: Kevin Dawson.', 0),
(27568, 'esMX', 'Infiltrarse en Ciudad Forjatiniebla', 'Habla con el prospector Seymour.', '¿Sabes guardar un secreto? Si sabes, tengo un secreto que quiero compartir contigo.$b$b¡¡Aquí todo el mundo está LOCO!!$b$b¡Hay goblins por allí, Hierro Negro justo ahí, y un fuego viviente gigante justo al otro lado de esta puerta! ¡Y eso es solo lo que veo en esta pequeña cueva!$b$b¿Y tú? ¿Tú qué estás haciendo aquí?$b$bAh, ya veo. Te ha enviado Winky, ¿verdad? Te ha enviado para hablar con el prospector Seymour, entrando por esta puerta y a la derecha, ¿verdad? ¡Pues vete! ¡A Oralius le da igual!$b$b¡¡...ME LAS PAGARÁS POR ESTO, WINKY!!$b$b<Oralius se echa a llorar.>', '', '', '', '', '', '', '', '', '', '', 0),
(27569, 'esMX', 'Tácticos Hierro Negro', 'Mata al general Forjainquina y al Señor Gólem Argelmach.', 'El general Forjainquina y el Señor Gólem Argelmach lideran a los ejércitos Hierro Negro y a sus gólems contra nosotros. Si queremos prevalecer, debemos matarlos a los dos.$b$bAtraviesa esta puerta y abre el candado de Forjatiniebla, que separa los Cuarteles Este y Oeste. Luego sigue las escaleras y dirígete a la izquierda hasta que llegues al Cuartel del Oeste. Allí encontrarás al general y al señor gólem.$b$bNo te despistes, ambos son combatientes experimentados. Si tienes éxito, busca a Mayara Alasol.', '', '', '', '', '', '', '', '', '', 'Informa a: Mayara Alasol.', 0),
(27570, 'esMX', 'La situación hasta ahora', 'Habla con Gotura Cuatro Vientos en el Fuerte Grommash en Orgrimmar.', 'Evidentemente habrás notado los terremotos. Incluso puede que hayas visto elementales atacando las tierras y las ciudades. El Anillo de la Tierra se esfuerza por comprender lo que está pasando. Tenemos la suerte de que nuestro Jefe de Guerra es uno de los mejores chamanes que existen.$b$bThrall ha estado consultando a sus consejeros y no queremos interrumpir su consejo. Pero tal vez nuestro hermano, Gotura Cuatro Vientos, conozca los planes de Thrall.', '', '', '', '', '', '', '', '', '', 'Habla con: Gotura Cuatro Vientos. Zona: Fuerte Grommash, Orgrimmar.', 0),
(27571, 'esMX', 'El Tragapenas', 'Peléate con Hurley Negrálito, Plugger Aropatoso y Ribbly Llavenrosca.', 'Hay quien dice que el Tragapenas es el secreto del progreso de la guerra de los Hierro Negro. Sus guerreros se reponen allí y salen sedientos de más almas inocentes. Creo que podríamos ponerles una buena zancadilla a los Hierro Negro si provocamos un poco de caos por aquí.$b$bQuiero que busques pelea con tres de los parroquianos más infames del bar. Daña los barriles y Hurley Negrálito vendrá corriendo. Roba objetos de las mesas cerca de Plugger Aropatoso y se peleará. En cuanto a Ribbly Llavenrosca... Tú habla con ese exaltado. Preséntate ante Orfus cuando hayas terminado.', '', '', '', '', '', '', '', '', '', 'Informa a: Montaraz Orfus.', 0),
(27572, 'esMX', 'Una reunión en Terrallende', 'Habla con Thrall en el Trono de los Elementos en Nagrand.', 'Saludos, $c. Los elementos están cada vez más inquietos y nosotros no parece que avancemos en la solución del problema. Algunos de nuestros chamanes más sabios se han reunido en Nagrand, en el Trono de los Elementos, para debatir sobre lo que enferma nuestras tierras.$b$bDirígete al Trono de los Elementos y habla con nuestro Jefe de Guerra; seguro que él tiene alguna misión para ti.', '', '', '', '', '', '', '', '', '', 'Habla con: Thrall. Zona: Trono de los Elementos, Nagrand.', 0),
(27573, 'esMX', 'El pacto de los Hierro Negro', 'Mata al embajador Latifuego y a Condena\'rel.', 'Más adelante está la criatura que conocemos solo como el embajador Latifuego. Es el embajador en la nación Hierro Negro de Ragnaros, el Señor del Fuego. Más allá de la cámara se encuentra la Tumba del Invocador, donde residen los espíritus de los siete patriarcas Hierro Negro que invocaron a Ragnaros a nuestro mundo.$b$bEs posible que no hayas oído hablar del Gran Fuego, pero será el fin de Azeroth si nadie lo detiene, y estos individuos están directamente relacionados con su dominio de los Hierro Negro. Mátalos para que esta nación pueda redimirse algún día.', '', '', '', '', '', '', '', '', '', 'Informa a: Mariscal Maxwell.', 0),
(27574, 'esMX', 'Nunca olvido una cara', 'Entrega la cabeza parcialmente digerida a Lord Godfrey en el Bosque de Argénteos.', 'Has descubierto una cabeza parcialmente digerida. Lord Godfrey se sobresalta cuando la ve. Tal vez deberías entregársela.', '', '', '', '', '', '', '', '', '', '', 0),
(27575, 'esMX', 'De la barriga de la bestia', 'Recupera el torso de Dempsey, las extremidades de Dempsey y los menudillos de Dempsey.', 'Creo que podemos reconstruirlo. A lo mejor, si conseguimos recomponerlo, puede darnos información sobre Crowley.$B$B¡Tendremos que matar a todos los crocoliscos de esta ciénaga hasta que encontremos el resto del cuerpo de Sean Dempsey! ¡Este hombre renacerá de la barriga de bestia!', '', '', '', '', '', '', '', '', '', 'Habla con: Lord Godfrey. Zona: Bosque de Argénteos.', 0),
(27576, 'esMX', 'La orden de Parche', 'Habla con Parche en el Paso Faucedraco.', 'Los acontecimientos recientes han dejado aún más claro que esconderse aquí y lanzar ataques esporádicos no basta para mantener a salvo a los nuestros, y mucho menos para recuperar Grim Batol. Tenemos que ser más agresivos, tenemos que apuntar al corazón.$B$BHe aceptado enviar dragones para ayudar a tus comandantes. Ya estaban elaborando un plan para atacar Grim Batol, así que deberías empezar por ahí.$B$BParche debería estar en el Paso Faucedraco, en el cañón que hay debajo de nosotros, hacia el sur.', '', '', '', '', '', '', '', '', '', '', 0),
(27577, 'esMX', 'Los planes de ataque de la Séptima Legión', 'Recupera los planes de ataque de la Séptima Legión.', 'Aunque destruir Piroleña seguramente nos dará ventaja sobre la Alianza en el campo de batalla, nuestro auténtico objetivo es dejarlos lisiados.$B$BAl oeste de aquí, cerca de La Muralla de Cringris, hay un campamento base de la Séptima Legión. Debemos registrarlo en busca de sus planes de ataque. Con los planes de ataque de la Séptima Legión, podremos conocer con exactitud el avance de todas las tropas de la Alianza en el Bosque de Argénteos.', '', '', '', '', '', '', '', '', '', 'Habla con: Lord Walden. Zona: Bosque de Argénteos.', 0),
(27578, 'esMX', 'El plan de Morgan', 'Mata al emperador Dagran Thaurissan.', 'El emperador Dagran Thaurissan tiene el control total de la ciudad desde su trono, que está más adelante. Si queremos detener a sus ejércitos, vamos a tener que acabar con el reino de su emperador.$b$bTendrás que atravesar su guardia personal, entre la que se cuenta el gigante Magmus, para llegar a él. Muévete lo más rápido posible: si se corre la voz antes de que termines, la ciudad entera se congregará alrededor de su trono.$b$bTen en cuenta que las puertas del Lyceum solo se abrirán cuando hayas encendido los blandones con antorchas de los guardianes de la llama. Buena suerte.', '', '', '', '', '', '', 'Dagran Thaurissan', '', '', 'Vuelve con: Mariscal Maxwell.', 0),
(27579, 'esMX', 'En la prisión', 'Encuentra a Lexlort.', 'El Mah\'tillo Crepuh\'cular eh\'tá aquí por algo. No sabemos por qué, pero Thal\'trak te va a contar un secretillo: el pícaro Lexlort eh\'pera fuera de la sala de la alta interrogadora Gerstahn p\'a matah\'la si se presenta la ocasión.$b$bPero ella eh demasia\'o lih\'ta, así que lo vas a hacer tú, ¿a que sí? Ve a ver a Lexlort y cuéntaselo. Seguro que le parecerá bien.', '', '', '', '', '', '', '', '', '', '', 0),
(27580, 'esMX', 'Sembrando discordia', 'Asesina al general Machacarroca.', 'Los refuerzos de la Alianza han establecido un asentamiento en la región de Bosque de Argénteos del suroeste llamado el campamento base de la Séptima Legión. Nuestro objetivo principal en el campamento base es sembrar la discordia entre las tropas. Esta es una misión destinada a asesinar a su comandante de operaciones, el general Machacarroca, en menos que canta un gallo. Su muerte no detendrá el avance de la Alianza, pero seguro que afecta a sus tropas.', '', '', '', '', '', '', 'General Machacarroca', '', '', 'Habla con: Lord Godfrey. Zona: Bosque de Argénteos.', 0),
(27581, 'esMX', '¡¿Crepúsculo?! ¡No!', 'Mata a la alta interrogadora Gerstahn.', 'Gerstahn está demasiado bien protegida y es demasiado lista como para abandonar su puesto, así que no voy a matarla.$b$bTú vas a matarla.$b$bTe daré algo que le he quitado a un guardia para recompensarte.', '', '', '', '', '', '', 'Alta interrogadora Gerstahn', '', '', 'Vuelve con: Lexlort.', 0),
(27582, 'esMX', 'Infiltrarse en Ciudad Forjatiniebla', 'Habla con Razal\'filo.', 'Me temo que estamos librando una batalla que no podemos ganar. Los Hierro Negro ya son difíciles de derrotar de por sí, pero sus aliados elementales les han aportado unos nuevos guerreros impresionantes con los que no podemos competir.$b$bQuiero que nos ayudes a infiltrarnos en su terreno y matar a tantos de sus líderes cruciales como sea posible. Con un poco de suerte sus tropas se desesperarán y la balanza se inclinará en nuestro favor. Preséntate ante Razal\'filo para más instrucciones. Está destacado al otro lado de esta puerta, a la derecha.', '', '', '', '', '', '', '', '', '', '', 0),
(27583, 'esMX', 'El flanco norte', 'Preséntate ante Gralok en la Cala Serpenteante, en las Tierras Altas Crepusculares.', 'He ordenado levantar un perímetro de defensa en nuestra costa norte, en la Cala Serpenteante. Nuestros exploradores informan de que los nagas estaban intentando asentarse allí.$B$BGralok está al mando de la operación, ¡preséntate ante él y asegura esa playa!', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Gralok. Zona: Cala Serpenteante, Tierras Altas Crepusculares.', 0),
(27584, 'esMX', 'Sangre en las olas', 'Mata a cualquier combinación de 15 asaltantes o maestras Escama Negra.', 'La escoria naga cree que puede enviar refuerzos río arriba, hasta El Bastión del Crepúsculo. CORTAREMOS sus cabezas de pescado y les ARRANCAREMOS las ESPINAS.$B$B<Gralok clava su espada ancha en el fango.>$b$b¡Destruye a los Escama Negra!', '', 'Nagas Escama Negra asesinados', '', '', '', '', '', '', '', 'Vuelve con: Gralok. Zona: Cala Serpenteante, Tierras Altas Crepusculares.', 0),
(27585, 'esMX', 'La 109ª División', 'Mata al general Forjainquina y al Señor Gólem Argelmach.', 'El general Forjainquina y el Señor Gólem Argelmach son los responsables directos de la horrible matanza de la 109ª División de la Fuerza Expedicionaria de Kargath. Había muchos trols y orcos buenos en esa división, y muchos de ellos eran buenos amigos míos.$b$bBueno, joven $r, es hora de que nuestros hermanos caídos por fin obtengan su venganza.$b$bAbre el candado de Forjatiniebla, sube las escaleras y dirígete a la izquierda hasta que llegues al Cuartel del Oeste. Mata a Forjainquina y a Argelmach, y no te atrevas a mostrarles piedad.', '', '', '', '', '', '', '', '', '', 'Informa a: Theodora Mulvadania.', 0),
(27586, 'esMX', 'Morteros a la orilla del mar', 'Reúne 8 morteros sin explotar en la playa, en la Cala Serpenteante.', 'Rescaté estos morteros de los restos de nuestra nave cuando explotó sobre el puerto Faucedraco. ¡Pero tenemos poca munición!$B$BMientras vas por la playa, hazme un favor y recoge cualquier mortero sin explotar que encuentres.$B$BLos morteros sin explotar son los mejores, nunca sabes CUÁNDO van a detonar. ¡Perfectos para sorprender al enemigo! ', '', '', '', '', '', '', '', '', '', 'Llévale los morteros a: Fergus Piñocompinche. Zona: Cala Serpenteante, Tierras Altas Crepusculares.', 0),
(27587, 'esMX', 'Maliciosamente delicioso', 'Reúne 6 colas de orilla de pantano intactas de makrura de orilla de pantano.', '¿Sabes? Tengo un problema con el que podrías ayudarme.$b$bVerás, además del noble arte del tráfico de armas, estoy intentando animar un poco el ambiente en Chapaleos. Al parecer hay unos cuantos makruras en las aguas del norte a los que no les gustan las fiestas playeras de escándalo que hemos estado organizando.$b$bPeor para ellos, no voy a dejar que me mangoneen unas langostas gigantes. ¡Son mi siguiente fuente de ingresos! Tráeme algunas de sus colas y convertiremos un problema en beneficios.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Barón mercante Brochargento. Zona: Chapaleos, Pantano de las Penas.', 0),
(27589, 'esMX', 'El Tragapenas', 'Peléate con Hurley Negrálito, Plugger Aropatoso y Ribbly Llavenrosca.', 'Todo el mundo en el Tragapenas está como una auténtica cuba, y por lo tanto se enfadan con facilidad. Creo que podríamos ponerles una buena zancadilla a los Hierro Negro si provocamos un poco de caos por aquí.$b$bQuiero que busques pelea con tres de los parroquianos más infames del bar. Daña los barriles y Hurley Negrálito vendrá corriendo. Roba objetos de las mesas cerca de Plugger Aropatoso y se peleará. En cuanto a Ribbly Llavenrosca... Tú habla con ese exaltado. Preséntate ante Corazón Atronador cuando hayas terminado.', '', '', '', '', '', '', '', '', '', 'Informa a: Corazón Atronador.', 0),
(27590, 'esMX', 'Haz la señal para atacar', 'Usa la señal de ataque desde lo alto de una de las torres en la Puerta Crepuscular.', 'Ahora que has atraído a Trituracráneos la Montaña lejos de la Puerta Crepuscular, ¡necesito que les hagas la señal a nuestras fuerzas para que ataquen!', '', 'Señal de ataque hecha', '', '', '', '', '', '', '', '', 0),
(27591, 'esMX', 'El pacto de los Hierro Negro', 'Mata al embajador Latifuego y a Condena\'rel.', 'En el interior de esta cámara se encuentra el embajador Latifuego. Es el embajador en la nación Hierro Negro de Ragnaros, el Señor del Fuego. Más allá de la cámara se encuentra la Tumba del Invocador, donde residen los espíritus de los siete patriarcas Hierro Negro que invocaron a Ragnaros a nuestro mundo.$b$bEs posible que no hayas oído hablar del Gran Fuego, pero será el fin de Azeroth si nadie lo detiene, y estos individuos están directamente relacionados con su dominio de los Hierro Negro. Mátalos a todos para que cese esta unión sacrílega.', '', '', '', '', '', '', '', '', '', 'Informa a: Señor de la guerra Dientegore.', 0),
(27592, 'esMX', 'Bebida salada', 'Recoge 10 botellas de Hielo de Brochargento robado de los reptadores de cieno.', '¿Qué hay, "colega"? ¡Estábamos en plena fiesta en la playa totalmente espontánea cuando sucedió algo terrible, $g"tío":"tía";!$b$bTenía toda una caja de Hielo de Brochargento, la bebida favorita del barón, ¡cuando unos reptadores de cieno fueron y la robaron! Nunca he visto beber a los reptadores, pero la cogieron y se la llevaron al agua. ¡Necesitamos algún tipo de $ghéroe:heroína; que nos ayude a recuperar nuestra bebida de marca favorita!$b$b<Brono te observa un instante.>$b$b¡Me refiero a ti, $g"hermano":"hermana";!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Brono Buenamuesca. Zona: Pantano de las Penas.', 0),
(27593, 'esMX', 'El renacimiento de la F.E.K.', 'Mata al emperador Dagran Thaurissan.', 'El emperador Dagran Thaurissan tiene el control total de la ciudad desde su trono, que está más adelante. Si queremos detener a sus ejércitos, vamos a tener que acabar con el reino de su emperador.$b$bTendrás que atravesar su guardia personal, entre la que se cuenta el gigante Magmus, para llegar a él. Muévete lo más rápido posible: si se corre la voz antes de que termines, la ciudad entera se congregará alrededor de su trono.$b$bTen en cuenta que las puertas del Lyceum solo se abrirán cuando hayas encendido los blandones con antorchas de los guardianes de la llama. Buena suerte.', '', '', '', '', '', '', 'Dagran Thaurissan', '', '', 'Vuelve con: Señor de la guerra Dientegore.', 0),
(27594, 'esMX', 'Al servicio secreto de su majestad', 'Captura a la comandante Lorna Crowley y llévala ante Lady Sylvanas Brisaveloz en el Frente Renegado en el Bosque de Argénteos.', 'Lorna Crowley, hija de Lord Darius Crowley, está actualmente en el campamento del Frente de Liberación de Gilneas, situado cerca de la Muralla de Cringris, al sudeste.$B$BNuesta misión principal es infiltrarnos en el campamento y capturarla viva. La Dama Oscura cree que podrá utilizar a Lorna como moneda de cambio contra Crowley. Yo digo que la matemos y la resucitemos como una Renegada, pero debemos hacer lo que ordena la Dama Oscura.$B$BDebemos darnos prisa antes de que llegue el resto de las fuerzas de la Alianza.', '', 'Comandante Lorna Crowley capturada', '', '', '', '', 'Lorna Crowley', '', '', 'Entrega a: La comandante Lorna Crowley. A: Lady Sylvanas Brisaveloz. Zona: Frente Renegado, Bosque de Argénteos.', 0),
(27595, 'esMX', 'El Profeta Hadassi', 'Encuentra al Profeta Hadassi en Orsis.', 'El Profeta Hadassi es el miembro más sabio y anciano de la tribu de Orsis.$B$BNo sabemos qué ha sido de él y su bienestar es de vital importancia.$B$BVe a Orsis y encuéntralo. Llegará el día del gran juicio para los lacayos de Al\'Akir si resulta herido.', '', '', '', '', '', '', '', '', '', '', 0),
(27596, 'esMX', 'El corazón de la montaña', 'Consigue el corazón de la montaña.', 'Durante años he buscado cierta gema. Se llama corazón de la montaña ¡y es tan grande como uno de tus puños! Los enanos Hierro Negro la tienen bajo llave en su cámara acorazada y, aunque lo he intentado, no me dejan comprarla.$B$BAsí que tengo recurrir a la fuerza.$B$BÁbrete paso hasta la cámara inferior de las Profundidades de Roca Negra, descubre la caja fuerte secreta y hazte con el corazón. Para ello, tendrás que derrotar al velador Presaletal ¡y solo se manifestará cuando hayas abierto todas las arcas con reliquias de la cámara!$B$BSuerte.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Maxwort Suprandor.', 0),
(27597, 'esMX', 'Larry el Demente', 'Encuentra a Larry el Demente al sureste de Chapaleos.', 'Ya lo pillas, $n. Tú me rascas la espalda, yo te la rasco a ti. Bueno, en rigor, le rasco la espalda a todo tu ejército un poquito más fuerte que al otro ejército. ¿Es demasiado complicado?$b$bA lo que voy es que hay muchas espaldas. Así que te voy a pedir que me rasques la mía un poco más. Es posible que quienquiera que robara esas minas haya atacado a los chicos de la costa este.$b$bVe a nuestro campamento, al sureste, y busca a Larry el Demente; él te informará cuando llegues.', '', '', '', '', '', '', '', '', '', '', 0),
(27598, 'esMX', 'Matar gilblins', 'Mata a 7 acechadores gilblin.', '¡Gilblins!$b$b<Larry te observa en silencio durante un rato.>$b$b¿Nunca has visto un gilblin? ¡Están locos! ¡Más locos que yo! Yo solo me gano la vida haciendo saltar cosas por los aires, ¡estos tíos están PIRADOS!$b$b¡No sé de dónde han venido, pero son como horribles peces goblin! ¡Con agallas y todo! ¡Mataron a todos mis hombres en la playa y se llevaron nuestro carguero!$b$b¡Tienes que ayudarme! ¡Están justo al este, ve allí y deshazte de los gilblins!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Larry el Demente. Zona: Tinieblas de las Penas, Pantano de las Penas.', 0),
(27599, 'esMX', 'No les hace falta', 'Recupera 6 bolsitas de corsarios de Chapaleos difuntos.', '¡Todo mi personal que no veas en este campamento está MUERTO! Eran unos goblins estupendos, ¡pero lo peor es que siguen ahí fuera! ¡Es una TRAGEDIA!$b$b¡Quiero decir que es una tragedia que todavía tengan todas sus cosas! Es un horror pensar en todos esos materiales y monedas en perfecto estado ahí en el agua.$b$b¡Oye! ¡Podrías hacerme un favor! Si sales a matar gilblins por ahí, coge las bolsitas de mis antiguos tripulantes.$b$b¡Venga, ya no les hace falta! ¡No seas así!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Larry el Demente. Zona: Tinieblas de las Penas, Pantano de las Penas.', 0),
(27600, 'esMX', 'Una entrada sonada', 'Habla con el pequeño Jerry el Loco para abordar el barco, y luego reúne los tres bienes importantes de Larry el Demente.', '¡Nuestra fragata mercante sigue ahí fuera, en el agua, llena de gilblins! ¡AAH!$b$bPerdona. ¡Pero en serio! Tenemos que llevarte hasta allí para que recuperes nuestras cosas. ¡En ese barco aún quedan bienes de calidad! ¡CALIDAD! ¡ES MI SEGUNDO NOMBRE!$b$bAfortunadamente para ti, ¡tengo una idea! Sal del campamento y dirígete al muro del norte... ¡Mi hijo Jerry te trasladará con nuestro cañón! ¡Si ha estado practicando, vamos!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Larry el Demente. Zona: Pantano de las Penas.', 0),
(27601, 'esMX', 'Ciudades reducidas a polvo', '¡Acompaña a Lady Sylvanas Brisaveloz al campo de batalla y derrota a la Alianza!', 'Nuestros ejércitos chocan en el campo de batalla. Crowley y sus fuerzas están perdiendo terreno. Nos reuniremos con Crowley y sus compatriotas a mitad del campo y les ofreceré los términos de su rendición. O aceptan, o reducimos sus ciudades a polvo.$B$BComo el soldado en quien más confío, debes mantenerte a mi lado durante las negociaciones. Avísame cuando estés $glisto:lista; para marchar.', '', 'Victoria: final y absoluta', '', '', '', '', '', '', '', 'Habla con: Lady Sylvanas Brisaveloz. Zona: Bosque de Argénteos.', 0),
(27602, 'esMX', 'Las últimas palabras del profeta', 'Encuentra el receptáculo sagrado.', 'Nos... hemos... comprometido por un juramento... a proteger el cetro de Orsis.$B$BEscucha, $c, no me queda demasiado... tiempo.$B$BEncuentra el receptáculo sagrado... en el extremo sur de la ciudad.$B$BNo... dejes que... caiga en sus... manos...', '', '', '', '', '', '', '', '', '', '', 0),
(27603, 'esMX', 'La puerta sellada', 'Mata a Bael\'gar.', 'En un extremo de la Ruta Hierro Negro se alza una gigantesca puerta muy parecida a la que protege Ciudad Forjatiniebla al otro lado. ¡Pero no tenemos ni idea de qué hay al otro lado!$b$bTodo lo que sabemos es que está fuertemente custodiada por patrullas Yunque Colérico y el gigante fundido Bael\'gar. ¡Debes acabar con ellos y ver si puedes abrir esa puerta!$b$bImagina lo que podría haber al otro lado... ¡podría haber toda una segunda mitad de la ciudad y no nos habríamos enterado! ¡O nada! ¿Quién sabe?$b$bAunque lo más probable es que haya algo...', '', '', '', '', '', '', 'Bael\'Gar', '', '', 'Vuelve con: Tinkee Vaporio.', 0),
(27604, 'esMX', 'Jammal\'an el Profeta', 'Hazte con la cabeza de Jammal\'an el Profeta.', 'Jammal\'an el Profeta, líder de los trols Atal\'ai y Hakkari, ha obtenido una pequeña cantidad de sangre de Hakkar el Cazador de Almas. Se la inyectan a dragones Verdes y utilizan sus cuerpos para producir las enormes cantidades de sangre que hacen falta para invocar a Hakkar a nuestro mundo.$b$bNo podemos permitir que eso pase. ¡Mata a Jammal\'an y a sus sacerdotes antes de que sus planes avancen aún más!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lord Itharius.', 0),
(27605, 'esMX', 'Eranikus', 'Mata a Eranikus.', 'La sangre de Hakkar que los Atal\'ai han estado inyectando en los dragones Verdes ha tenido un efecto devastador en los propios dragones, antiguos carceleros de los Atal\'ai. Parece que la presencia de la sangre en sus cuerpos los ha corrompido y se han convertido en criaturas de pesadilla.$b$bEranikus, el principal consorte de Ysera y el guardián jefe del templo, es quien ha recibido mayores cantidades de sangre y se ha vuelto retorcido más allá de lo imaginable. Cuando Jammal\'an esté muerto, busca a Eranikus y acaba con él.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lord Itharius.', 0),
(27606, 'esMX', '¡Vuélalo!', 'Sopla la caracola de Heth\'Jatari junto al estandarte de Heth\'Jatari. Mata al señor de las profundidades Heth\'Jatar. Te será más fácil si lo atraes hacia el fuego de mortero.', '¡Vayamos a pescar, $n! Ahora que los morteros están listos, podemos ir por el líder de esta invasión.$B$BEl señor de las profundidades Heth\'Jatar gobierna la casta guerrera Escama Negra. Ve a los estandartes de Heth\'Jatari, al noreste de aquí, y sopla esta caracola. Es como un silbato para perros, pero para peces.$B$BCuando aparezca Heth\'Jatar, ordenaré a los morteros que abran fuego. Verás a los objetivos de los proyectiles.$B$BAtrae a Heth\'Jatar a nuestro fuego de mortero ¡y usa la fuerza para someterlo!  ', '', '', '', '', '', '', 'Heth\'Jatar', '', '', 'Vuelve con: Fergus Piñocompinche. Zona: Cala Serpenteante, Tierras Altas Crepusculares.', 0),
(27607, 'esMX', 'El flanco sur', 'Habla con Rok\'tar en las Orillas Crepusculares, en las Tierras Altas Crepusculares.', 'Nuestro nuevo acuerdo con la Horda hará que mi gente entre directamente en conflicto con la Alianza.$B$BPues que vengan.$B$BMientras hablamos, la Alianza avanza por la península para amenazar el Puerto Faucedraco.$B$BEncuentra a Rok\'tar en el sur, creo que ha montado un puesto de mando en uno de los barcos naufragados, y asegúrate de que las Orillas Crepusculares siguen estando bajo nuestro control.', '', '', '', '', '', '', '', '', '', 'Habla con: Rok\'tar. Zona: Orillas Crepusculares, Tierras Altas Crepusculares.', 0),
(27608, 'esMX', 'Cuatro cabezas es mejor que ninguna', 'Consigue las cuatro cabezas de Za\'brox y Beeble\'phod.', 'Estamos a punto de lanzar el ataque contra la Puerta Crepuscular, pero queda un último cabo suelto por atar: Za\'brox y Beeble\'phod, los discípulos de Cho\'gall.$B$BSegún los informes de inteligencia, están en el Cubil de los Discípulos, una pequeña cueva de ogros en el rincón sudoeste de la Puerta Crepuscular.$B$B¿Querrías volver allí y matarlos?', '', '', '', '', '', '', '', '', '', 'Vuelve con: Cassius el Blanco. Zona: Paso del Invicto, Tierras Altas Crepusculares.', 0),
(27609, 'esMX', 'Cuatro cabezas es mejor que ninguna', 'Consigue las cuatro cabezas de Za\'brox y Beeble\'phod.', 'Ahora que estamos a punto de lanzar el ataque contra la Puerta Crepuscular, queda un último cabo suelto por atar: Za\'brox y Beeble\'phod, los discípulos de Cho\'gall.$B$BSegún los informes de inteligencia, están en el Cubil de los Discípulos, una pequeña cueva de ogros en el rincón sudoeste de la Puerta Crepuscular.$B$BVe allí y mátalos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lady Cozwynn. Zona: Machacolpe, Tierras Altas Crepusculares.', 0),
(27610, 'esMX', 'Explorando la costa', 'Explora el punto de control de punta de playa en la Orilla Crepuscular. No tienes que capturarlo, pero el hacerlo le dará a tu bando ventaja en combate y te pondrá la marca JcJ.', 'Si la Alianza se hace con el control de esta península, el Puerto Faucedraco estará amenazado. Eso no ocurrirá.$B$BAl sur de aquí, verás una pequeña colina con una vista que domina la línea de la costa. ¡Quienquiera que domine esa colina, dominará toda la costa!$B$BCorre hacia allí y explora el punto de control de punta de playa. Está marcado con esa enorme bandera. Luego vuelve aquí.$B$BNo tienes que capturarlo, a menos que te estés muriendo por pelear contra la Alianza.', 'Punto de control de la punta de playa explorado', '', '', '', '', 'Punto de control de la punta de playa explorado', '', '', '', 'Vuelve con: Rok\'tar. Zona: Orillas Crepusculares, Tierras Altas Crepusculares.', 0),
(27611, 'esMX', 'Sangre en la arena', 'Mata a 12 soldados de Bancalto en las Orillas Crepusculares, en las Tierras Altas Crepusculares.', 'Nuestro objetivo en las Tierras Altas Crepusculares es asaltar El Bastión del Crepúsculo, pero la Alianza ha decidido declarar la guerra.$B$B¡Pues les daremos guerra!$B$BMata a sus soldados hasta que aprendan la lección.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Rok\'tar. Zona: Orillas Crepusculares, Tierras Altas Crepusculares.', 0),
(27612, 'esMX', 'Victoria desde el interior', 'Abre los portales Argenta en el Ala de la Biblioteca y de la Sala de Armas en el interior de la abadía en la Mano de Tyr.', 'Unos cuantos de nuestros hombres no consiguieron atravesar los portales que se suponía que llevaban a esta misma abadía. Ya has demostrado lo $gesquivo:esquiva; que puedes llegar a ser, además de tu resistencia en la batalla... y necesito que vuelvas a demostrarlo.$b$bLa abadía tiene dos alas: una Biblioteca y una Sala de Armas. En cada una de las alas encontrarás un portal.$b$bUsa esta piedra angular en los portales. Si lo haces, se supone que forzarás su apertura; lo que permitirá la entrada del resto de nuestros soldados de asalto para hacernos con la abadía.', '', 'Abre el portal en el interior de la Sala de Armas', 'Abre el portal en el interior del ala de la Biblioteca', '', '', '', '', '', '', 'Vuelve con: Comandante de Cruzada Eligor Albar. Zona: Mano de Tyr, Tierras de la Peste del Este.', 0),
(27613, 'esMX', 'El asesino', 'Mata a Rohan el Asesino en el interior de la torre del campanario de la abadía en la Mano de Tyr.', 'El destino de la Cruzada Escarlata es trágico y en cierto modo irónico. En un tiempo lideraron la carga de la humanidad contra los no-muertos. Y ahora se parecen a esos cadáveres que antes perseguían. Todavía no están claros los motivos que causaron su descenso al mundo de los no-muertos, pero eso no los hace menos peligrosos.$b$bUno de sus miembros más mortíferos era un asesino llamado Rohan. Nuestra inteligencia nos informa de que se encuentra en la torre del campanario de esta abadía. Encuéntralo y mátalo, $n. Y trata de no morir en el intento.', '', '', '', '', '', '', 'Rohan el Asesino', '', '', 'Vuelve con: Comandante de Cruzada Eligor Albar. Zona: Mano de Tyr, Tierras de la Peste del Este.', 0),
(27614, 'esMX', 'Recuperación de objetos Escarlata', 'Consigue el jabalí carmesí, el ceñidor de Lihanna, el embozo de Uther y el sello de Gavinrad.', 'Esta batalla estaba ganada antes de comenzar. Ahora mismo solo disparamos para obtener puntos de estilo.$b$bEsos cobardes cruzados Escarlata guardan sus valiosos artefactos en el interior de su cuartel, a pesar de que muchos son demasiado sagrados como para que sus manos de no-muertos puedan tocarlos. Así que los guardan en un cofre oculto.$b$bTienes que encontrar esos artefactos y traérmelos. Le pertenecen a la Cruzada Argenta. Deben estar en las manos adecuadas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Comandante de Cruzada Korfax. Zona: Mano de Tyr, Tierras de la Peste del Este.', 0),
(27615, 'esMX', 'El Colérico', 'Asesina a Mataus el Colérico.', 'Uno de los miembros más viles de la Cruzada Escarlata, Mataus el Colérico, merodea por la mazmorra del cuartel. Los no-muertos encajan con su oscurantismo.$b$bSi fuese más joven y aún estuviese en primera línea, acabaría con él yo mismo. Pero tal y como están las cosas, me dejan relegado a liderar nuestras fuerzas desde la retaguardia. Así que te cederé el placer a ti.', '', '', '', '', '', '', 'Mataus el Colérico', '', '', 'Vuelve con: Comandante de Cruzada Korfax. Zona: Mano de Tyr, Tierras de la Peste del Este.', 0),
(27616, 'esMX', 'El Montero', 'Mata al Montero Leopold.', 'Ya han caído una docena de hombres víctima de una lluvia de balas y flechas provenientes de lo alto de esa fortaleza. No he visto la cara del enemigo que está disparando, pero no me hace falta. Sé cómo se llama el hombre que está ahí arriba.$B$BLeopold.$B$BEn efecto, ahí arriba solo hay un hombre, cargándose a mis hombres uno a uno. Y, por lo que veo, tú estás $gsolo:sola;.$B$BA mí me parece una pelea justa.', '', '', '', '', '', '', 'Montero Leopold', '', '', 'Vuelve con: Comandante de Cruzada Korfax. Zona: Mano de Tyr, Tierras de la Peste del Este.', 0),
(27617, 'esMX', 'El fin de la corrupción', 'Preséntate ante la archimaga Angela Dosantos en la Mano de Tyr en las Tierras de la Peste del Este.', '¿Lo notas? La corrupción ya ha comenzado a desaparecer del edificio.$b$bUn edificio sagrado debe permanecer sagrado; y villanos como Rohan y el resto de la basura Escarlata lo impiden.$b$bAhora que hemos asegurado la abadía, estamos a un paso de hacernos con el control de la Mano de Tyr. Informa del resultado de nuestro ataque a Angela. Ella se encargará de liderar la carga contra la catedral desde algún punto del centro de la ciudad.', '', '', '', '', '', '', '', '', '', '', 0),
(27618, 'esMX', 'Agitación Argenta', 'Preséntate ante la archimaga Angela Dosantos en la Mano de Tyr en las Tierras de la Peste del Este.', 'Creo que ya hemos causado suficientes daños a este cuartel como para considerarlo una victoria. Un comandante, un cazador y un brujo, todos asesinados... Y eso sin mencionar las reliquias que hemos robado. O tal vez debería decir que... TÚ has robado.$b$bTodavía falta esa catedral, pero no será por mucho tiempo. Habla con la archimaga Angela Dosantos en el patio central. El destino de la catedral de la Mano de Tyr está en sus manos.', '', '', '', '', '', '', '', '', '', '', 0),
(27619, 'esMX', 'La comandante', 'Asesina a la Comandante Escarlata Marjahn.', 'La comandante Escarlata Marjahn es astuta, retorcida y está dispuesta a hacer lo que sea con tal de ganar una batalla. Pero, sin embargo, ante todo, es leal.$b$bNo me cabe duda de que la encontrarás en la cámara central del cuartel luchando bajo un estandarte carmesí hasta conseguir la victoria o hasta la muerte.$b$bAsegúrate de que sea lo segundo.', '', '', '', '', '', '', 'Marjhan', '', '', 'Vuelve con: Comandante de Cruzada Korfax. Zona: Mano de Tyr, Tierras de la Peste del Este.', 0),
(27620, 'esMX', 'Como ratas', 'Mata al señor cruzado Valdelmar.', 'Bueno, me alegra ver que Eligor y Korfax dejaron algo de diversión para mí. Fue una batalla en sí impedir que se metieran sin pensar en medio de esta catedral.$B$BEse es TU trabajo, después de todo.$B$BLa catedral está delante de nosotros, el último auténtico bastión que queda del poder Escarlata. En su interior, el señor cruzado Valdelmar se sienta en lo alto del decrépito púlpito de mentiras de la Mano de Tyr.$B$BNo habrá escapatoria; no habrá piedad. Los últimos frágiles vestigios de la Cruzada Escarlata terminan aquí. Mátalo.', '', '', '', '', '', '', 'Señor Cruzado Valdemar', '', '', 'Vuelve con: Leonid Barthalomew el Venerado. Zona: Capilla de la Esperanza de la Luz, Tierras de la Peste del Este.', 0),
(27621, 'esMX', 'La Patrulla de Barbafuego', 'Busca a Keegan Barbafuego en la Patrulla de Barbafuego, en las Tierras Altas Crepusculares.', 'Me dirigía a unirme a la Patrulla de Barbafuego cuando derribaron a mi pájaro.$B$BEl Martillo Crepuscular ha lanzado ataques sorpresa por todas las Tierras Altas. A veces sus edificios surgían de la tierra en medio de nuestros poblados. ¡Fue una pesadilla!$B$BEn el caos, Barbafuego fue uno de los pocos que mantuvo la cabeza fría. Está intentando recomponer nuestras filas con los supervivientes.$B$BSi quieres que los Martillo Salvaje se unan a la Alianza, empieza por ayudar a Barbafuego, al oeste.', '', '', '', '', '', '', '', '', '', 'Busca a: Keegan Barbafuego. Zona: Patrulla de Barbafuego, Tierras Altas Crepusculares.', 0),
(27622, 'esMX', 'Mi trituradora mejorada', 'Localiza una trituradora salvable en las Orillas Crepusculares y úsala para invocar a un experto de salvamento de Pantoque. Defiende la trituradora hasta que vuelva a funcionar.', '$n, tengo planes para una trituradora mejorada. Pero mis ingenieros no pueden entrar solos en la zona de combate.$B$BVe, localiza una trituradora salvable en las Orillas Crepusculares y úsala para elegir a uno de mis expertos de salvamento para que se una a ti. Defiende la trituradora mientras le hacemos algunas "mejoras".$B$B¡La Alianza no sabrá de dónde le vinieron los golpes! Al menos, ¡no hasta que comience mi campaña de marketing!', '', 'Trituradora salvable localizada', 'Trituradora salvable defendida', '', '', '', '', '', '', 'Vuelve con: Juice Gnugat. Zona: Orillas Crepusculares, Tierras Altas Crepusculares.', 0),
(27623, 'esMX', 'Guardianes colosales', 'Consigue la Piedra de la Luna y la Piedra del Sol de los guardianes colosales.', 'El cofre que contenía el cetro parece estar sellado mágicamente y no se abre.$B$BLa placa de la parte superior muestra dos estatuas gigantes que sostienen en el centro unas rocas con forma de estrella y de luna.$B$BLas dos estatuas aparecen custodiando unas pirámides parecidas a las que hay en el exterior.$B$BTal vez merezca la pena investigar esto.', '', '', '', '', '', '', '', '', '', 'Vuelve a los jeroglíficos cubiertos de arena. Zona: Orsis, Uldum.', 0),
(27624, 'esMX', 'Tras la caída', 'Reúne el orbe de la estrella de la mañana, el orbe de la estrella de la tarde, el orbe de la estrella del Norte y el orbe de la estrella fugaz.', 'Bah, no ha sido nada, de verdad.$b$bEsas estatuas estaban ya tambaleándose, solo necesitaban un empujoncito.$b$b¿Te apetece rebuscar un poco en los escombros?$b$bTengo la sensación de que estamos cerca de resolver todo esto.', '', '', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Cámara de las Estrellas.', 0),
(27625, 'esMX', 'En defensa de Quel\'Danil', 'Asesina a 16 invasores Mortacechadores en la Avanzada Quel\'Danil.', '¡Los no-muertos están aquí! ¡Los Renegados! Se estaban acercando cada vez más, pero que nos lancen un ataque total... ¡Esas horribles abominaciones!$B$BEl joven draenei que tenía al cargo se ha entrenado en el combate con los elfos Vallealto. ¡No están completamente indefensos, pero necesitan ayuda!$B$B¡Por favor, $n, ayúdalos! ¡Haz retroceder a los Renegados!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Anacoreta Traska. Zona: Avanzada Quel\'Danil, Tierras del Interior.', 0),
(27626, 'esMX', 'Los documentos de Vallealto', 'Recoge el informe de Vallealto, los registros de Vallealto y las notas de Vallealto.', 'Los Vallealto han guardado registros detallados en este lugar durante años. Muertes, nacimientos, estaciones... pero también información vital para la exploración y métodos de contacto con el resto de la Alianza.$B$BLos documentos estarán desperdigados entre el caos. Si caen en manos de los Renegados, ¡habrá más vidas en peligro! Por favor, tienes que recuperar los documentos antes de que la Horda se haga con ellos...', '', '', '', '', '', '', '', '', '', 'Vuelve con: Anacoreta Traska. Zona: Avanzada Quel\'Danil, Tierras del Interior.', 0),
(27627, 'esMX', 'Tan solo una cucaracha elegante', 'Mata a 5 escarabajos de amatista, 5 escarabajos de zafiro, 5 escarabajos de turquesa y 5 escarabajos de esmeralda.', 'Evidentemente, las antiguas estatuas albergaban diferentes especies de escarabajos.$b$bPretendes dejar este lugar en las mejores condiciones posibles, de modo que decides eliminar esta plaga de la cámara.', '', 'Escarabajo de amatista asesinado', 'Escarabajos de esmeralda asesinados', 'Escarabajo de zafiro asesinado', 'Escarabajo de turquesa asesinado', '', '', '', '', '', 0),
(27628, 'esMX', 'Informa a Phaoris', 'Habla con el rey Phaoris en Ramkahen, en Uldum.', 'Date prisa, $n. Tenemos que hablar con mi hermano, el Rey.$B$BPretende evitar la guerra con Al\'Akir y con los Neferset. Tiene la absurda esperanza de que podría haber una solución diplomática para este conflicto.$B$BTal vez cuando sepa lo que ha ocurrido aquí, entre en razón.', '', '', '', '', '', '', '', '', '', '', 0),
(27629, 'esMX', 'El voto del Visir', 'Habla con el visir Tanotep en los Campos de Akhenet, en Uldum.', 'Conseguir que el visir Tanotep se ponga en contra de los deseos de mi hermano va a ser extremadamente difícil. Su puesto consiste precisamente en hacer cumplir la voluntad de Phaoris.$B$BNo he conseguido gran cosa tratando de ponerle a favor de la guerra abierta contra Neferset.$B$BDe todos modos, tienes que hablar con él. Tal vez escuche a alguien de fuera.$B$BEncontrarás al visir en los Campos de Akhenet en misión oficial.', '', '', '', '', '', '', '', '', '', '', 0),
(27630, 'esMX', 'El voto del sumo sacerdote', 'Habla con el sumo sacerdote Amet en la Presa Vir\'naal, en Uldum.', 'El voto del sumo sacerdote Amet es el único que está completamente fuera de nuestro control.$B$BVotará en función de sus adivinaciones y no habrá manera de disuadirlo.$B$BSupongo que eso nos dará opciones de una forma o de otra.$B$BEl único problema es que su clarividencia ha fallado desde que cayó la barrera que rodeaba Uldum.$B$BNo votará a no ser que recupere el poder sobre sus adivinaciones.$B$BVe por las escaleras a los lados de la Presa Vir\'naal y habla con él para averiguar qué puedes hacer para ayudarle.', '', '', '', '', '', '', '', '', '', '', 0),
(27631, 'esMX', 'El voto del Alto comandante', 'Habla con el alto comandante Kamses en la Avanzada de la Legión Ramkahen, en Uldum.', 'Si queremos que se acepte una resolución de guerra, necesitamos que la votación del Alto Consejo sea unánime.$B$BEstoy seguro de que el alto comandante Kamses nos otorgará su voto en cuanto sepa lo ocurrido en Orsis.$B$BHabla con él en Ramkahen y asegúrate de que sea así. Yo tengo que hacer preparativos por si nuestro plan fallase.', '', '', '', '', '', '', '', '', '', '', 0),
(27632, 'esMX', 'El hijo de Tanotep', 'Consigue el mapa del delta de Vir\'Naal de un guardia de Neferset.', 'He dedicado mi vida a servir al Rey. Ese servicio es más importante que ninguna otra cosa... con una sola excepción: mi hijo.$B$BTahet fue capturado por avizores de Neferset.$B$BAfirman que mi hijo había traspasado su territorio. Phaoris está tratando de negociar su liberación... pero yo temo lo peor.$B$BSi fueses en busca de Tahet, te prometería mi voto.$B$BNo sé dónde llevan a los prisioneros, pero he visto a los guardias consultar mapas que les guían por la densa vegetación.', '', '', '', '', '', '', 'Guardia de Neferset', '', '', '', 0),
(27633, 'esMX', 'Hakkar, el Dios de la Sangre', 'Derrota al avatar de Hakkar.', 'Hakkar... Solo con mencionar el nombre del Cazador de Almas más de uno sale corriendo. En el Sagrario del Dios Caído los Atal\'ai han recuperado una parte considerable de su esqueleto y pretenden devolverle la vida. Sus hijos ya han empezado a reunirse en la zona.$b$bColoca este huevo en el sagrario; precipitará su invocación prematura. $n, no dudes. ¡Ataca en cuanto aparezca su avatar!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lord Itharius.', 0),
(27634, 'esMX', 'El dios Hakkar', 'Llévale el huevo de Hakkar relleno a Yeh\'kinya, que está en Tanaris.', 'Ha llegado la hora de atrapar la esencia del avatar de Hakkar.$B$BLleva el huevo de Hakkar a El Sagrario del Dios Caído que se encuentra en el Templo Sumergido de Azeroth. Convoca el poder del huevo para agitar al dios muerto.$B$BÉl enviará a sus esbirros a atacarte. Derrota a sus chupasangres y extráeles su sangre Hakkari. A continuación, utiliza la sangre para apagar las llamas eternas que protegen el espíritu de Hakkar. Cuando el fuego haya sido sofocado, el avatar de Hakkar entrará en nuestro mundo.$B$BDerrótalo y coloca su esencia en el interior del huevo de Hakkar.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Yeh\'kinya. Zona: Puerto Bonvapor, Tanaris.', 0),
(27635, 'esMX', 'Descontaminación', 'Sube en el Sanitron 500 y comienza el proceso de descontaminación.', 'Llevas mucho tiempo aquí abajo, en Gnomeregan, $n, ¡y es increíble que hayas sobrevivido tanto tiempo sin perder la cordura! Tenemos que sacarte de aquí.$b$bAntes de que podamos enviarte a la superficie con el resto de los gnomos, tienes que completar el proceso de descontaminación. Entra en la siguiente sala y súbete al Sanitron 500. ¡Él hará el resto! Ni siquiera te dolerá... mucho.$b$bCuando hayas terminado, habla con el técnico Braggle y te proporcionará equipo adecuado.', 'Completa el proceso de descontaminación', 'Proceso de descontaminación iniciado', '', '', '', 'Completa el proceso de descontaminación', '', '', '', 'Habla con: Técnico Braggle.', 0),
(27636, 'esMX', 'Solo tú y Mathias', 'Encuentra al maestro Mathias Shaw en la Ciudadela Crepuscular, en las Tierras Altas Crepusculares.', 'Los del IV:7 están todos muertos. Hay que encontrar al maestro Mathias Shaw.$B$BMenos mal que el comandante de escuadrón te dijo dónde estaría.', '', '', '', '', '', '', '', '', '', '', 0),
(27638, 'esMX', 'Solo tú y Garona', 'Encuentra a Garona Semiorco en la Ciudadela Crepuscular, en las Tierras Altas Crepusculares.', 'Los Kor\'kron están todos muertos. Hay que encontrar a Garona Semiorco.$B$BMenos mal que el comandante de escuadrón te dijo dónde estaría.', '', '', '', '', '', '', '', '', '', '', 0),
(27639, 'esMX', 'Solo tú y Garona', 'Encuentra a Garona Semiorco en la Ciudadela Crepuscular, en las Tierras Altas Crepusculares.', 'Eso afectará gravemente a nuestros progresos. ¡Maldito Cho\'gall!$B$BMenos mal que el comandante de escuadrón te dijo dónde encontrar a Garona.', '', '', '', '', '', '', '', '', '', '', 0),
(27640, 'esMX', 'Los Montocre no mueren', 'Busca supervivientes de la familia Montocre en las ruinas Montocre.', 'Tal como yo lo veo, estás intentando reunir a los clanes Martillo Salvaje con la Alianza para que vayan juntos a la guerra. No estoy seguro de que sepas dónde te estás metiendo.$B$BEn fin, si te estás preparando para la batalla, hay una familia que querrás tener de tu parte. Dirígete al suroeste, al lado opuesto del Crisol de Matanza, y allí encontrarás las ruinas del clan Montocre. Están completamente destrozadas, pero eso no será un inconveniente para los Montocre. Solo tienes que encontrarlos.', '', '', '', '', '', '', '', '', '', '', 0),
(27641, 'esMX', 'Mientras te reúnes con la familia', 'Mata a 20 miembros del Martillo Crepuscular en el territorio Montocre.', 'Oye tú, $gchico:chica;. Seguro que Keely te ha pedido que te ocupes de nuestros hermanos, pero pueden cuidarse solos. Encontrarán el camino de vuelta de una forma u otra. $B$BTal vez puedas hacerme un favor mientras vas a reunirte con la familia... El territorio Montocre sigue infestado de miembros del Martillo Crepuscular y sus sirvientes. Me gustaría que les recordaras que no son bienvenidos.', '', 'Invitados Crepusculares recibidos en Montocre', '', '', '', '', '', '', '', 'Vuelve con: Flynn Montocre. Zona: Resistencia Montocre, Tierras Altas Crepusculares.', 0),
(27642, 'esMX', 'Escudriñando los restos', 'Busca los cuerpos de 12 víctimas de Montocre.', 'Los Martillo Crepuscular fueron muy concienzudos cuando saquearon nuestra ciudad. Mis hermanos y yo bien podríamos ser los únicos que resistimos. Pero tengo que asegurarme.$B$BMientras registras las ruinas, mantente alerta por si ves los cuerpos de mi gente. Quiero saber si ha habido supervivientes... o si hay algo que indique que algunos lograron escapar.', '', 'Víctimas de Montocre encontradas', '', '', '', '', '', '', '', 'Vuelve con: Flynn Montocre. Zona: Resistencia Montocre, Tierras Altas Crepusculares.', 0),
(27643, 'esMX', 'Donnelly Montocre', 'Encuentra a Donnelly Montocre.', 'Así que tú nos buscas a nosotros, y yo busco a mis hermanos. Parece que tenemos algunos puntos en común.$B$BDonnelly es el mayor: lo delata su tamaño aunque no su cerebro. Suele estar en las ruinas del norte, en el cobertizo. ¿Te importaría ir a buscarlo? Me sería de gran consuelo saber que está bien.', '', '', '', '', '', '', '', '', '', '', 0),
(27644, 'esMX', 'Eoin Montocre', 'Encuentra a Eoin Montocre.', 'Eoin es uno de los gemelos. Es aficionado a la bebida. Lo más seguro es que lo encuentres cerca del viejo pozo: las reservas de cerveza están en un edificio que hay allí.$B$B¿Te importaría convencerle de que visitara a su hermana, que está preocupada? No debería costarte demasiado si consigues antes la cerveza.', '', '', '', '', '', '', '', '', '', '', 0),
(27645, 'esMX', 'Cayden Montocre', 'Encuentra a Cayden Montocre.', 'Cayden es el otro gemelo. Él también tiene sed, pero no de cerveza. Seguro que se lo ha estado pasando en grande desde que los Crepusculares llegaron a nuestras puertas. Puede que esté sacándose un poco de agresividad del cuerpo.$B$BSe me ocurre que el mejor lugar para buscarlo es en la Fila del Mercado, junto a la vieja herrería. Siempre solía andar por ahí, pero como ahora es donde más Crepusculares hay, tiene más razones para considerarlo un hogar.$B$BTráemelo de vuelta. Estaría bien que fuera de una sola pieza.', '', '', '', '', '', '', '', '', '', '', 0),
(27646, 'esMX', 'Encontrar a Pico', 'Ayuda a Donnelly a encontrar a Pico en el Cobertizo Montocre.', 'He perdido a mi grifo. ¡Pico! ¡¿Dónde estás, Pico?!$B$B¿Quieres ayudarme a encontrarlo? Sé que está en el cobertizo. Tiene que estar ahí.$B$B¡¿Pico?! ¡¿Dónde estás?!$B$BEspero que esté bien.', '', 'Registra el sótano en la parte sur del Cobertizo Montocre', 'Registra el sótano en la parte noroeste del Cobertizo Montocre', 'Registra los edificios en la parte este del Cobertizo Montocre', '', '', '', '', '', 'Vuelve con: Donnelly Montocre. Zona: Cobertizo Montocre, Tierras Altas Crepusculares.', 0),
(27647, 'esMX', 'Cualquier cosa menos agua', 'Registra el sótano que mencionó Eoin Montocre en busca de un barril.', 'Oye, colega. Si no has venido a ayudarme a conseguir bebida, estás estorbando.$B$B¿Por qué no vas al viejo almacén y miras en la planta de abajo? Ya sospechaba que el viejo contable se echaba unos tragos entre página y página. Apuesto a que tiene un barril en su sótano.$B$BSi encuentras algo, ¡ven a verme directamente! ¡No te entretengas... esto es urgente!', '', '', '', '', '', '', '', '', '', 'Habla con: Eoin Montocre. Zona: Ruinas Montocre, Tierras Altas Crepusculares.', 0),
(27648, 'esMX', 'Una vez más entre las llamas', 'Acompaña a Cayden Montocre durante la emboscada ligeramente obvia.', 'Bien, bien. ¿Quieres probar algo de acción? Puedes unirte a mí.$B$BAvísame cuando estés $glisto:lista; para partir.', '', 'Acompaña a Cayden por la Fila del Mercado Montocre', '', '', '', '', '', '', '', 'Vuelve con: Cayden Montocre. Zona: Ruinas Montocre, Tierras Altas Crepusculares.', 0),
(27649, 'esMX', 'Unos suministros estables', 'Consigue 6 barriles de cerveza Martillo Salvaje.', 'Oye colega. Ya que pareces ser tan $gsimpático:simpática; y $gestupendo:estupenda; y todo eso, ¿podrías hacerle un favor a un enano?$B$BEsto son ruinas Montocre... SEGURO que hay más cosas almacenadas en alguno de estos edificios. Si encuentras más cerveza, tráemela, ¿quieres? ¡Un buen enano nunca tiene suficiente!$B$BEstoy pensando en volver con Keely, así que puede que tengas que ir a buscarme, pero procuraré que merezca la pena.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Eoin Montocre. Zona: Ruinas Montocre, Tierras Altas Crepusculares.', 0),
(27650, 'esMX', 'De nuevo en casa', 'Habla con Keely Montocre en la Resistencia Montocre.', 'Deberías ir a ver a Keely. Estará deseando tener noticias.', '', '', '', '', '', '', '', '', '', '', 0),
(27651, 'esMX', 'Hacerlo como un Montocre', 'Habla con Flynn Montocre y ayuda a los hermanos Montocre a matar a Darunga.', 'Ya se han ido para cazar a los ettins que lideraron el ataque contra Montocre. Les pedí que te dieran una oportunidad para alcanzarlos, pero no creo que lleven en la sangre eso de esperar.$B$BSe dirigieron a la Plaza Principal, en el centro de las ruinas. Deberías unirte a ellos antes de que te pierdas toda la diversión.', '', '', '', '', '', '', 'Darunga', '', '', 'Habla con: Flynn Montocre o Keely Montocre. Zona: Ruinas Montocre, Tierras Altas Crepusculares.', 0),
(27652, 'esMX', 'Asesinos oscuros', 'Consigue 5 colgantes de asesino oscuro.', 'Incluso a mí me persiguen. Eso me pasa por esconderme entre las ovejas.$B$B<Mathias te estudia durante un momento.>$B$BEl Martillo Crepuscular también se ha apuntado y ha enviado asesinos oscuros a por mí. Unos tipos encantadores. Muertos. Están hechos de las almas de los asesinos más hábiles.$B$B¿Quieres hacerme un favor? Cázalos. Tráeme sus colgantes de almas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Maestro Mathias Shaw. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27653, 'esMX', 'Asesinos oscuros', 'Consigue 5 colgantes de asesino oscuro.', 'Incluso a mí me persiguen, $c. Pero forma parte de la diversión de esconderse entre las ovejas.$B$B<Garona te estudia durante un momento.>$B$BEl Martillo Crepuscular también se ha apuntado y ha enviado asesinos oscuros a por mí. Son buenos para ser un grupo de tíos muertos. Están hechos de las almas de los asesinos más hábiles.$B$B¿Me haces un favor? Cázalos.$B$BLlevan sus almas en colgantes alrededor del cuello. Tráemelos. Lo del alma es opcional.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Garona Semiorco. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27654, 'esMX', 'Corta por lo sano', 'Mata a 10 veteranos de la ciudadela, elementalistas corruptos y/o vindicadores Crepusculares.', 'Ninguna incursión en el campo de batalla estaría completa sin una buena misión consistente en cargarse a los tipos malos a la vieja usanza.$B$BEntre los veteranos de la ciudadela, los elementalistas corruptos, y los vindicadores Crepusculares, seguro que te sobran objetivos.$B$BCómo decidas matarlos es cosa tuya.', '', 'Cultores de la Ciudadela Crepuscular asesinados', '', '', '', '', '', '', '', 'Vuelve con: Maestro Mathias Shaw. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27655, 'esMX', 'Corta por lo sano', 'Mata a 10 veteranos de la ciudadela, elementalistas corruptos y/o vindicadores Crepusculares.', 'No hay nada peor que un adepto del Martillo Crepuscular que se odia a sí mismo. ¡Nada! Esos idiotas de verdad quieren causar el fin del mundo.$B$BEso, para mí, los hace merecer la extinción.$B$BEntre los veteranos de la ciudadela, los elementalistas corruptos y los vindicadores Crepusculares, seguro que no te faltan objetivos.$B$BCómo decidas matarlos, me importa más bien poco.', '', 'Cultores de la Ciudadela Crepuscular asesinados', '', '', '', '', '', '', '', 'Vuelve con: Garona Semiorco. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27656, 'esMX', 'Crocolisco', 'Mata 8 crocoliscos Denteserra.', 'Stagalbog, al este del pueblo, está lleno de crocoliscos. Lleno, ¿me oyes? He vendido todas las partes de crocolisco que te puedas imaginar.$b$bPieles, dientes, colas, lenguas, ojos, todo. A lo que voy: ya no se vende. ¡Hay demasiados crocoliscos! Tenemos demasiada oferta y nada de demanda.$b$bAsí que, ya que a mí no me sirven y a veces se comen a mis invitados, quiero que mates esos bichos y ya está. Hazme el favor, ¿quieres? Yo estaré aquí, negociando con tu gente.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Barón mercante Brochargento. Zona: Chapaleos, Pantano de las Penas.', 0),
(27657, 'esMX', 'Ayuda de la clamatierras', 'Habla con la clamatierras Yevaa en las Profundidades de Elementium, en las Tierras Altas Crepusculares.', 'Mi estudio del artefacto de Cho\'gall ha llegado a un punto muerto. El Martillo Crepuscular esclavizó a un grupo de herreros Martillo Salvaje y luego los ahogó en el lago cuando ya no necesitaron sus servicios.$B$B<Mathias escupe.>$B$BNecesitamos ayuda. Hay una mujer del Anillo de la Tierra, la clamatierras Yevaa, al sudoeste, en la mina de elementium.$B$BElla y su iniciado goblin necesitan ayuda para cerrar los portales elementales que hay cerca de aquí. Se me ocurre que, a cambio de eso, puede ayudarnos con nuestro problema.', '', '', '', '', '', '', '', '', '', '', 0),
(27658, 'esMX', 'Ayuda de la clamatierras', 'Habla con la clamatierras Yevaa en las Profundidades de Elementium, en las Tierras Altas Crepusculares.', 'Mi estudio del artefacto de Cho\'gall ha llegado a un punto muerto. El Martillo Crepuscular esclavizó a un grupo de herreros Martillo Salvaje y luego los ahogó en el lago cuando ya no necesitaron sus servicios.$B$B<Garona escupe.>$B$BOdio tener que decirlo, pero necesitamos ayuda. Hay una mujer del Anillo de la Tierra, una draenei llamada clamatierras Yevaa. Ella y su goblin mascota están al sudoeste de la mina de elementium.$B$BNecesitan ayuda para cerrar los portales elementales que hay cerca de aquí. A cambio, puede ayudarnos con nuestro problema.', '', '', '', '', '', '', '', '', '', '', 0),
(27659, 'esMX', 'Sobrecargar el portal', 'Mata a Apiciario debilitado, a Aetharon debilitado y a Edemantus debilitado.', 'Aquí solía custodiar los portales del Anillo de la Tierra. Pero, mientras estábamos fuera ayudando a salvar Infralar, el Martillo Crepuscular vino y corrompió la zona.$B$BUsan poderosos ascendientes para guardar nuestros portales. Ahí es donde han cometido un error crítico.$B$BQuiero que vayas a los portales y uses los controladores para sobrecargarlos. Eso liberará toda la energía del portal, debilitando al ascendiente. Mátalo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Clamatierras Yevaa. Zona: Profundidades de Elementium, Tierras Altas Crepusculares.', 0),
(27660, 'esMX', 'El espíritu del lago', 'Habla con la condesa Verrall en Loch Verrall, en las Tierras Altas Crepusculares.', 'No sé nada de ningún artefacto que esté creando Cho\'gall, pero creo que sé de uno que nos puede ser útil.$B$BLa condesa Verrall es el espíritu ancestral de Loch Verrall, al norte. No siente ningún aprecio por el Martillo Crepuscular que ha contaminado sus aguas.$B$BVe a verla para obtener la sabiduría que andas buscando.', '', '', '', '', '', '', '', '', '', '', 0),
(27661, 'esMX', 'Dispara el cañón', 'Mata a Lord Cannon.', 'Mi archi-némesis, Lord Cannon, ha tomado la estúpida decisión de jurarle lealtad al Martillo Crepuscular.$B$BEn el pasado, hemos convivido con una frágil tregua, pero este cambio de parecer no me deja más remedio que acabar con él. Lo que quiero decir es que si quieres conseguir la información que buscas del enano muerto, vas a hacerme el favor de matar a Lord Cannon.$B$BBúscalo en el Infierno de Cannon, al sudeste.', '', '', '', '', '', '', 'Lord Cannon', '', '', 'Vuelve con: Condesa Verrall. Zona: Loch Verrall, Tierras Altas Crepusculares.', 0),
(27662, 'esMX', 'Liberar', 'Libera a 10 elementales esclavizados matándolos en la Ciudadela Crepuscular.', 'Mira, si hay algo de lo que sé, es de elementales. He conseguido llegar a entender cómo se sienten. Y te diré una cosa: ¡no les gusta ni un pelo estar esclavizados!$B$BBien, lo que digo es que si liberases a los elementales esclavizados, estoy seguro de que no solo se mostrarían agradecidos, sino de que se volverían contra sus amos.$B$BA mí me parece que es una apuesta ganadora, $n.', '', 'Elementales esclavizados liberados', '', '', '', '', '', '', '', 'Vuelve con: Iniciado Minaoro. Zona: Profundidades de Elementium, Tierras Altas Crepusculares.', 0),
(27663, 'esMX', 'Sabe a zancudo', 'Hazte con 9 muslos de zancapantano gigantes de los zancapantanos.', '¡Tú! ¡Sí, tú! ¿Quieres que le hable bien de ti al barón mercante? ¡Échame una mano!$b$bHe oído que eres $gel:la; que le ha dado todas esas colas de makrura. Son maravillosas, pero no lo bastante para una comida de verdad. ¡Necesito muslos para mi potaje!$b$bHay un montón de zancapantanos fuera del pueblo, en las Tinieblas de las Penas. ¡Quiero los muslos más grandes que haya!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Pierre Desollapez. Zona: Chapaleos, Pantano de las Penas.', 0),
(27664, 'esMX', 'La baraja de Volcanes de la Luna Negra', 'Lleva la baraja de Volcanes a la Feria de la Luna Negra cuando pase por la ciudad.', 'Ahora que has reunido todos los naipes de Ascuas en una baraja, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: "Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Profesor Thaddeus Paleo.', 0),
(27665, 'esMX', 'La baraja de Huracanes de la Luna Negra', 'Lleva la baraja de Huracanes a la Feria de la Luna Negra cuando pase por la ciudad.', 'Ahora que has reunido todos los naipes de Vientos en una baraja, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: "Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Profesor Thaddeus Paleo.', 0),
(27666, 'esMX', 'La baraja de Tsunamis de la Luna Negra', 'Lleva la baraja de Tsunamis a la Feria de la Luna Negra cuando pase por la ciudad.', 'Ahora que has reunido todos los naipes de Olas en una baraja, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: "Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Profesor Thaddeus Paleo.', 0),
(27667, 'esMX', 'La baraja de Terremotos de la Luna Negra', 'Lleva la baraja de Terremotos a la Feria de la Luna Negra cuando pase por la ciudad.', 'Ahora que has reunido todos los naipes de Piedras en una baraja, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: "Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Profesor Thaddeus Paleo.', 0),
(27668, 'esMX', '¡Presta atención!', 'Nazgrim quiere que vayas a ver qué hay en la caja rota de la Alianza, al norte de La Espiral Inmortal.', 'Escucha, $r. No es que no aprecie el rescate y todo lo demás, pero esta es una situación desesperada.$b$b¡Tienes que prestar más atención ahí fuera!$b$bEstaba observando y vi como pasabas de largo junto a una caja rota de la Alianza.$b$bTiene que haber algo dentro de ella que pueda ayudarnos a mí y a mis chicos.$b$b¿Qué tal si sales ahí fuera y echas un vistazo, eh?', '', '', '', '', '', '', '', '', '', '', 0),
(27669, 'esMX', 'Haz los honores', 'Usa los orbes de las estrellas cerca del mecanismo en la Cámara de las Estrellas.', 'Parece que ya solo queda colocar los orbes en los pedestales de cada esquina del mecanismo.$b$bQuizás nos hayamos topado con lo que podría ser el descubrimiento más importante de la historia moderna.$b$b<Harrison te mira durante un instante y después te entrega los orbes.>$b$bBien, adelante, $n.$b$bNunca lo habríamos descubierto de no ser por ti.', '', 'Obelisco de las Estrellas reactivado', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Obelisco de las Estrellas.', 0),
(27670, 'esMX', 'Bloqueados', 'Mata a 6 gnomos parias enloquecidos.', 'Me llamo Nevin Tuercellave y soy el comandante de los Supervivientes Extraviados de Gnomeregan del Último Rescate Operativo, o S.E.G.U.R.O.$b$bNo sé cómo has conseguido sobrevivir a la radiación, $n, pero la mayoría de los demás no han salido tan bien parados. Mi equipo está reuniendo a los supervivientes, pero los gnomos parias irradiados son demasiados como para que podamos resistir mucho tiempo. ¡Han perdido la cabeza!$b$bSi aún tienes fuerzas como para levantar un arma o lanzar un hechizo, ¿nos ayudarás a acabar con algunos de esos gnomos parias?', '', '', '', '', '', '', '', '', '', 'Habla con: Nevin Tuercellave. Zona: Gnomeregan.', 0),
(27671, 'esMX', 'Atender a los supervivientes', 'Utiliza la baliza de teletransporte para teletransportar a 6 supervivientes a un lugar seguro.', 'Si no hacemos algo rápido, ni Nevin ni los supervivientes saldrán de aquí con vida. Te voy a dar la baliza de teletransporte de emergencia de mi escuadrón. Aún nos queda fuerza y munición para salir de aquí luchando, pero estos supervivientes no están en condiciones de echar a correr.$b$bUtiliza la baliza con los supervivientes para que los teletransporten desde aquí hasta el lugar seguro que han preparado mis hombres. Cuando lo hayas hecho, vuelve conmigo y haremos las preparaciones para sacarte de aquí.', '', 'Sobrevivientes rescatados', '', '', '', '', '', '', '', 'Habla con: Carvo Cargarrayo. Zona: Gnomeregan.', 0),
(27672, 'esMX', 'La cámara de Khaz\'mul', 'Derrota a Hierraya.', 'En la Cámara del Mapa hay una puerta que conduce a la legendaria cámara de Khaz\'mul. ¡Quién sabe qué secretos puede haber ocultos en su interior!$b$bLo que sí sabemos es que la custodia Hierraya, una vigía titánica de poder y tamaño inmensos. ¡Tendrás que derrotarla si pretendes desvelar los secretos de Uldaman!', '', '', '', '', '', '', '', '¡Sí!', 'Prospector jefe Durdin', 'Vuelve con: Prospector jefe Durdin.', 0),
(27673, 'esMX', 'Lo que cuenta es el interior', 'Obtén el núcleo de poder obsidiano y el núcleo de poder titánico.', 'Los Hacedores construyeron dos vigilantes de piedra ancianos para proteger Uldaman de posibles invasores y para supervisar las operaciones diarias mientras Hierraya y Archaedas reposan. Uno de ellos está completamente operativo en la Sala del Templo, pero algo corrompió al de la Cueva Echomok.$B$BTemo que uno de los dioses antiguos sea el responsable, ¡y tú me vas a ayudar a descubrir si es cierto! Derriba a los dos vigilantes y tráeme sus núcleos de poder. Nos dirán todo lo que queremos saber. ', '', '', '', '', '', '', '', '', '', 'Vuelve con: Kand Buscadunas.', 0),
(27674, 'esMX', 'A la superficie', 'Habla con Torben Pumzas para que te teletransporten hasta la superficie y preséntate ante Nevin Tuercellave.', 'Nevin nos acaba de comunicar que sus hombres y él se dirigen a la superficie. Te estará esperando en el edificio que S.E.G.U.R.O. ha establecido como su base de operaciones.$b$b¿Ves a Torben Pumzas ahí al lado? Habla con él cuando estés $glisto:lista; para salir a la superficie y hará que te teletransporten. Ha sido un placer conocerte, $n, y es un honor para mí haber desempeñado un pequeño papel al ayudarte a escapar de Gnomeregan para empezar tu vida en la superficie.', '', 'Habla con Torben Pumzas', '', '', '', '', '', '', '', 'Habla con Torben Pumzas para que te teletransporten hasta la superficie y preséntate ante Nevin Tuercellave.', 0),
(27675, 'esMX', 'Documentos falsificados', 'Encuentra a un residente de la Ciudad de Ventormenta que acepte tus documentos falsificados.', 'Encuentra a un residente en la Ciudad de Ventormenta que acepte tus documentos falsificados.', '', '', '', '', '', '', '', '', '', '', 0),
(27676, 'esMX', 'A puerta cerrada', 'Mata a Galgann Flamartillo.', '¡Galgann Flamartillo y su banda de Hierro Negro están en la Excavación 3 para proteger una puerta sobre la que no sabemos nada! ¡Estoy harta de que sus hombres interfieran con nuestro trabajo! ¡La Liga de Expedicionarios es el único grupo autorizado para manejar artefactos en Uldaman!$b$bVe a la excavación y deshazte de él para que nuestro trabajo pueda continuar. ¡Quiero saber qué hay detrás de esa puerta!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Olga Jurarruna.', 0),
(27677, 'esMX', 'Archaedas, el vigía de piedra antiguo', 'Derrota a Archaedas.', 'Nuestro verdadero objetivo en Uldaman es obtener los Discos de Norgannon. Los secretos que contienen podrían cambiar toda nuestra visión del mundo. En ellos están escritos infinitos secretos de los creadores... Su valor va más allá de toda la riqueza material que puedas imaginar.$b$bEl problema es que Archaedas, una antigua y poderosa creación de los creadores, protege los discos y cuenta con un ejército respetable a su disposición. ¡Quiero que lo derrotes y consigas los discos para la Liga de Expedicionarios!', '', '', '', '', '', '', 'Archaedas', '¡Lo has conseguido!', 'Prospector jefe Durdin', 'Vuelve con: Prospector jefe Durdin.', 0),
(27679, 'esMX', 'La cámara de Khaz\'mul', 'Derrota a Hierraya.', 'En la Cámara del Mapa hay una puerta cerrada que creo que conduce a la legendaria cámara de Khaz\'mul. Aún no sabemos qué artefactos nos esperan en su interior.$b$bLo que sí sabemos es que la custodia Hierraya, una vigía titánica de poder y tamaño inmensos. Tendrás que derrotarla para seguir avanzando en este sitio.', '', '', '', '', '', '', '', 'Bien hecho.', 'Alto examinador Tae\'thelan Mirasangre', 'Vuelve con: Alto examinador Tae\'thelan Mirasangre.', 0),
(27680, 'esMX', 'Archaedas, el vigía de piedra antiguo', 'Derrota a Archaedas.', 'Nuestro verdadero objetivo en Uldaman es obtener los Discos de Norgannon. Esos discos de platino podrían otorgar un poder inigualable a nuestra orden. En ellos están escritos infinitos secretos de los creadores... Su valor va más allá de toda la riqueza material que puedas imaginar.$b$bEl problema es que Archaedas, una antigua y poderosa creación de los creadores, protege los discos y cuenta con un ejército respetable a su disposición. Quiero que lo derrotes y consigas los discos para El Relicario.', '', '', '', '', '', '', 'Archaedas', 'Excelente.', 'Alto examinador Tae\'thelan Mirasangre', 'Vuelve con: Prospector jefe Durdin.', 0),
(27681, 'esMX', 'A puerta cerrada', 'Mata a Galgann Flamartillo.', '¡Galgann Flamartillo y su banda de Hierro Negro están en la Excavación tres para proteger una puerta sobre la que no sabemos nada! ¡Estoy harta de que sus hombres interfieran con nuestro trabajo! ¡El Relicario es el único grupo autorizado para manejar explosivos en Uldaman!$b$bVe a la excavación y deshazte de él para que nuestro trabajo pueda continuar. ¡Quiero saber qué hay detrás de esa puerta!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lidia Brillo del Sol.', 0),
(27682, 'esMX', 'Necesitamos más minerales', 'Obtén el núcleo de poder obsidiano y el núcleo de poder titánico.', 'Los Titanes construyeron dos vigilantes de piedra ancianos para proteger Uldaman de posibles invasores y para supervisar las operaciones diarias mientras Hierraya y Archaedas reposan. Uno de ellos está completamente operativo en la Sala del Templo, pero algo corrompió al de la Cueva Echomok.$B$BSospecho que uno de los dioses antiguos es el responsable y tú me vas a ayudar a descubrir si es cierto. Derriba a los dos vigilantes y tráeme sus núcleos de poder. Nos dirán todo lo que queremos saber. ', '', '', '', '', '', '', '', '', '', 'Vuelve con: Aoren Brillo del Sol.', 0),
(27683, 'esMX', 'Al interior del bosque', 'Encuentra a una mujer huargen en el Río Thondroril en las Tierras de la Peste del Este.', 'El otro día vi una conmoción de lo más extraña en la ciudad. Un carro tirado por caballos y cargado de cajones y cofres. Lo conducía una mujer huargen, a su lado viajaba un elfo de sangre y a pie les seguía un enano paladín que no hacía más que gritar obscenidades, de las más creativas que he oído últimamente, eso he de reconocerlo.$b$bParece que se dirigían a las Tierras de la Peste del Este aunque supongo que no deben de haber llegado mucho más allá del Río Thondroril. Me pregunto qué tramarán.', '', '', '', '', '', '', '', '', '', '', 0),
(27684, 'esMX', 'Visitantes', 'Encuentra a una mujer huargen en el Río Thondroril en las Tierras de la Peste del Este.', 'Mis fuentes en La Finca de los Ensalmadores me han informado de que pronto tendremos visita. En breve llegará un grupo de paladines dirigidos por una comerciante huargen, ¡lo que hay que oír! Estoy deseando conocerlos. Especialmente a uno de ellos.$b$b¿Te importaría echarles un vistazo? No puedo asegurártelo, pero para cuando tú llegues allí, lo más probable es que ellos estén cruzando el Río Thondroril, hacia el oeste.', '', '', '', '', '', '', '', '', '', '', 0),
(27685, 'esMX', 'Una buena obra por hacer', 'Habla con Adarrah en el Bosque Kelp\'thar.', 'Buenas, $gchico:chica;.$b$bMe llamo Rendel.$b$bParece que la vieja Moanah y yo llegamos justo a tiempo, ¿eh?$b$b¡Erunak no estaba de broma cuando dijo que era cosa de vida o muerte!$b$bPor ello... en nuestra prisa por llegar hasta aquí dejamos algunos asuntos por resolver a cierta distancia hacia el este.$b$bUna señorita estaba al borde de la muerte. No tuvimos más opción que dejarla junto a una pequeña fisura de aire para venir aquí a rescatarte.$b$b¿Qué tal si te pasas por allí para ayudarla mientras aún hay tiempo?', '', '', '', '', '', '', 'Adarrah', '', '', '', 0),
(27686, 'esMX', 'Documentos falsificados', 'Encuentra a un residente de Orgrimmar que acepte tus documentos falsificados.', 'Encuentra a un residente en Orgrimmar que acepte tus documentos falsificados.', '', '', '', '', '', '', '', '', '', '', 0),
(27687, 'esMX', 'Gnash se la había ganado', 'Lleva la cabeza de Gnash a Samir en el Agujero del Contrabandista.', '¡Menuda hazaña! ¡Te has cargado a un gigante de mar!$b$bLos nuevos habitantes del Agujero del Contrabandista se sentirán considerablemente más seguros al saber que este monstruo ya no merodea en las inmediaciones de su refugio.', '', '', '', '', '', '', '', '', '', '', 0),
(27688, 'esMX', 'Distráelos', 'Mata a la dama Alys Finnson, al maestro Klem y a Mia la Rosa.', 'Hay tres candidatos para ascender a los que hay que matar: la dama Alys Finnson, el maestro Klem y Mia la Rosa.$B$BQuerría que me sirvieses de distracción. Cuando llegue el momento adecuado, iré y acabaré con ellos por la espalda.$B$BHagas lo que hagas, $n, no los subestimes. Todos llegaron hasta donde están siendo implacables y muy buenos en lo que hacen.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Maestro Mathias Shaw. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27689, 'esMX', 'Distráelos', 'Mata a la dama Alys Finnson, al maestro Klem y a Mia la Rosa.', 'Hay tres candidatos para ascender a los que hay que matar: la dama Alys Finnson, el maestro Klem y Mia la Rosa.$B$BQuiero que sirvas de distracción. Cuando llegue el momento adecuado, iré y acabaré con ellos por la espalda.$B$BAsegúrate de no subestimarlos, hagas lo que hagas, $n. Cada uno de esos lunáticos llegó hasta donde está siendo implacable y muy bueno en lo que hace.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Garona Semiorco. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27690, 'esMX', 'Narkrall, el domador de dracos', 'Preséntate ante Narkrall Rasgarra en Garganta de Sangre, en las Tierras Altas Crepusculares.', '$n, la fortaleza de Garganta de Sangre es el corazón del imperio Faucedraco en las Tierras Altas. Está justo río arriba. Narkrall Rasgarra está usando su considerable poder para reunir un batallón de jinetes de dracos allí.$B$BPara que triunfen los Faucedraco, Garganta de Sangre debe triunfar. Ve con Narkrall y asegúrate de que así sea.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Narkrall Rasgarra. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(27691, 'esMX', 'Locura Aleta de la Marisma', 'Mata a 12 múrlocs Aleta de la Marisma.', 'Me temo que ya no queda más Bonvapor por aquí. Todos los jóvenes del campamento que hay al este cayeron cuando llegaron los múrlocs.$b$bSí, siempre ha habido múrlocs en estas costas, pero nunca en semejante número. Salieron del mar a montones por la noche, aullando y echando espuma por la boca, ¡y subieron a tierra para atacar!$b$bNo podemos permitir que sigan correteando por ahí, ¿no crees? ¿Quieres consolar a una goblin anciana y echar a unos cuantos múrlocs de vuelta al agua?', '', '', '', '', '', '', '', '', '', 'Vuelve con: Baba Cebafango. Zona: Stagalbog, Pantano de las Penas.', 0),
(27692, 'esMX', 'La princesa Theradras', 'Mata a la princesa Theradras.', 'No te alarmes, joven $r. Soy Zaetar, hijo de Cenarius, y he recurrido a ti para solicitar tu ayuda.$b$bHace mucho tiempo cometí el error de relacionarme con la princesa Theradras, un poderoso elemental de tierra fiel a los dioses antiguos. Nuestros hijos, los centauros Kahns, se rebelaron contra mí nada más nacer y me asesinaron sin piedad. Ahora la mácula de Theradras se extiende y no amenaza solo a Maraudon.$b$bVe a matarla y libera mi espíritu para que podamos convertir Desolace en un prometedor lugar de vida floreciente, como desearía Cenarius.', '', '', '', '', '', '', 'Princesa Theradras', '', '', '', 0),
(27693, 'esMX', 'El juego del celador', 'Completa el juego del celador teletransportando a los peones del celador a posiciones en las que miren hacia dentro.', 'Contemplas cómo la estatua se divide en dos, luego en cuatro y, por último, en ocho estatuas idénticas en una formación cuadrada.$b$bOyes una voz, pero no proviene del exterior, sino de tu propia mente:$b$b   "Un auténtico celador no mira HACIA FUERA, en busca de señales de peligro.$b  Un auténtico celador mantiene la mirada HACIA DENTRO, siempre centrado en la protección de aquello que custodia."$b$b¿Será algún tipo de acertijo?', '', 'Juego del celador completado', '', '', '', '', '', '', '', '', 0),
(27694, 'esMX', 'La Charca de Lágrimas', 'Reúne 5 artefactos Atal\'ai de la Charca de Lágrimas que rodea al Templo de Atal\'Hakkar.', 'Los trols que se pasean por este templo han cometido graves ofensas contra mi gente, $n. Nos enviaron para proteger este lugar, pero nos utilizaron para desatar los terribles poderes que alberga.$b$bDebo suplicarte la ayuda que solo me puede brindar un mortal. Puedes ser mi mano dentro del templo. Si entro solo, me arriesgo a enfrentarme también a mis hermanos.$b$bHaremos un pacto. Si deseas ayudarme, reúne artefactos Atal\'ai de las aguas que rodean al templo y tráemelas.', '', '', '', '', '', '', '', '', '', 'Vuelve con Lord Itharius en lo alto del Templo de Atal\'Hakkar, en el Pantano de las Penas.', 0),
(27695, 'esMX', 'El hacha de elementium', 'Consigue el hacha de elementium.', 'Esos cobardes Crepusculares han capturado y asesinado a demasiados dragones Rojos, pero uno sigue vivo. ¿Recuerdas a Lirastrasza? Está encadenada cerca de aquí y vamos a liberarla.$B$BPero primero, necesitamos algo lo suficientemente afilado como para cortar sus cadenas.$B$BHay un viejo ettin llamado Ciego el Guardián. Monta guardia en el Altar de la Ascensión, en el sur.$B$BTiene un hacha hecha de elementium puro. Me pregunto si ese es el arma "definitiva" de Cho\'gall.', '', '', '', '', '', '', 'Ciego el Guardián', '', '', 'Vuelve con: Maestro Mathias Shaw. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27696, 'esMX', 'El hacha de elementium', 'Consigue el hacha de elementium.', 'Esos cobardes Crepusculares han capturado y asesinado a muchos dragones Rojos, pero uno aún respira. ¿Recuerdas a Lirastrasza? Está encadenada cerca de aquí y vamos a liberarla.$B$BPero primero, necesitamos algo lo suficientemente afilado como para soltarla.$B$BHay un viejo ettin llamado Ciego el Guardián. Monta guardia en el Altar de la Ascensión, en el sur.$B$BTiene un hacha hecha de elementium puro. Me pregunto si ese es el arma "definitiva" de Cho\'gall.', '', '', '', '', '', '', 'Ciego el Guardián', '', '', 'Vuelve con: Garona Semiorco. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27697, 'esMX', 'Corrupción en Maraudon', 'Mata a Lord Lenguavil.', '¡$n, necesito tu ayuda de inmediato! Soy Zaetar, hijo de Cenarius, ¡y estoy atrapado aquí después de una desdichada serie de acontecimientos! Antes de que puedas salvarme, debes ayudarme a purificar la corrupción que campa a sus anchas por Maraudon.$b$bLord Lenguavil es el sátiro que domina las Cavernas de Cristales Púrpura. Es un pérfido agente de la Legión Ardiente y su presencia solo conduce al caos y a la muerte. ¡No puede seguir viviendo!', '', '', '', '', '', '', 'Lord Lenguavil', 'Tu trabajo no ha hecho más que empezar.', 'Zaetar', '', 0),
(27698, 'esMX', 'Los sirvientes de Theradras', 'Mata a Noxxion y a Latisable.', 'La princesa Theradras, mi antigua consorte, ha utilizado su enorme poder para corromper la naturaleza misma de Maraudon. Sus criaturas aún andan sueltas por aquí, y temo que pronto escapen al resto del mundo para plantar las semillas de la muerte y de la destrucción.$b$b$n, ve y mata a Noxxion y a Latisable. Son dos de sus esbirros más poderosos y sus muertes le causarían a la cruel princesa un sufrimiento y pesar bien merecidos. Quizás entonces puedas liberar mi espíritu de su control.', '', '', '', '', '', '', 'Latisable', 'Te agradezco tus esfuerzos.', 'Zaetar', '', 0),
(27699, 'esMX', 'Debilidad por los tiburones', 'Reúne 5 dientes de Bocados en el Arrecife de Huesos.', '¡Vaya un tiburón más duro!$b$bDecides que lo mejor para el bien de todos es tratar de distraer a Budd y esperar que su atención nunca derive de nuevo hacia Bocados y el Arrecife de Huesos.$b$bPuede que los dientes de la bestia sean lo suficientemente cautivadores...', '', '', '', '', '', '', '', '', '', 'Lleva los dientes de Bocados a Budd en la Excavación de Budd, en el Bosque Kelp\'thar.', 0),
(27700, 'esMX', 'Dragona, desencadenada', 'Usa el hacha de elementium para romper las cadenas que atan a Lirastrasza.', 'Lirastrasza es la última y la más grande de los dragones Rojos que capturó el Martillo Crepuscular. Están a punto de matarla.$B$BNecesito que cojas el hacha de elementium y la liberes de sus cadenas.', '', 'Lirastrasza liberada', '', '', '', '', 'Lirastrasza', '', '', 'Vuelve con: Maestro Mathias Shaw. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27701, 'esMX', 'Dragona, desencadenada', 'Usa el hacha de elementium para romper las cadenas que atan a Lirastrasza.', 'Lirastrasza es la última y la más grande de los dragones Rojos que capturó el Martillo Crepuscular. Están a punto de matarla, $c.$B$BTienes que coger el hacha de elementium y liberarla de sus cadenas antes de que lo hagan ellos.', '', 'Lirastrasza liberada', '', '', '', '', 'Lirastrasza', '', '', 'Vuelve con: Garona Semiorco. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27702, 'esMX', 'Golpe de gracia', 'Lanza un golpe de gracia contra 5 aterracielos Crepusculares.', 'Mira eso. ¡Lirastrasza los está destruyendo!$B$BHay que acabar con los dracos a los que está derribando, $n. No queremos que los sanadores Crepusculares logren hacerlos volar de nuevo.$B$BEs la hora de un pequeño golpe de gracia.', '', 'Golpe de gracia asestado', '', '', '', '', '', '', '', 'Vuelve con: Maestro Mathias Shaw. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27703, 'esMX', 'Golpe de gracia', 'Lanza un Golpe de gracia contra 5 aterracielos Crepusculares.', 'Mira eso. ¡Lirastrasza los está destruyendo!$B$BTodavía hay que acabar con los dracos a los que está derribando, $n. No queremos que los apestosos sanadores Crepusculares logren hacerlos volar de nuevo.$B$BEs la hora de un pequeño Golpe de gracia.', '', 'Golpe de gracia asestado', '', '', '', '', '', '', '', 'Vuelve con: Garona Semiorco. Zona: La Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27704, 'esMX', 'Las leyendas del Templo Sumergido', 'Viaja por las antecámaras del templo hasta la Sala de las Máscaras.', 'Primero necesito que entres en el templo, $n. Una vez hayas despejado el camino puedo reunirme contigo, pero no me atrevo a entrar a ciegas. Me convertiría en un enemigo feroz si tuviera que enfrentarme a mi propia especie.$b$bPara empezar, baja las escaleras que tengo a mi espalda. Luego nada por las profundidades anegadas de la Cámara Partida. Una vez allí, sigue el pasillo de la derecha hasta la Sala de las Máscaras.$b$bCuidado con los guardias del templo. Cuando hayas encontrado la Sala de las Máscaras, me pondré en contacto contigo a través de la piedra de juramento.', 'Sala de las Máscaras encontrada', '', '', '', '', 'Sala de las Máscaras encontrada', '', '¡Lo has encontrado!', 'Lord Itharius', '', 0),
(27705, 'esMX', 'Paso uno: la sacerdotisa', 'Mata a la sacerdotisa Udum\'bra en la Cámara de la Sangre.', 'Están masacrando a mis hermanos. Es lo que imaginaba.$b$bDebo pedirte tu ayuda de nuevo antes de entrar, $n. En el pasaje que hay fuera de esta habitación, el pasillo sigue a la izquierda y a la derecha. Por la derecha baja hasta la Cámara Sangrienta, donde los Atal\'ai llevan a cabo sus oscuros rituales.$b$bLlevan años esperando y preparándose para alguien como yo, pero no para ti. Entra en la Cámara de la Sangre y mata a la sacerdotisa Udum\'bra. Es una de las tres presencias malvadas que debemos vencer antes de que pueda entrar.', '', '', '', '', '', '', 'Sacerdotisa Udum\'bra', 'La piedra de juramento nos vincula.', 'Lord Itharius', '', 0),
(27706, 'esMX', 'El cetro de Orsis', 'Consigue el cetro de Orsis del receptáculo sagrado.', 'El cofre de debajo se abre con un fuerte clic cuando introduces las dos piedras en la placa.$B$BConsigue el cetro y llévaselo al general Ammantep.', '', '', '', '', '', '', '', '', '', 'Lleva el cetro de Orsis al general Ammantep en el exterior de Orsis.', 0),
(27707, 'esMX', 'La prisión de Neferset', 'Dirígete al campo de prisioneros de Neferset y descubre el paradero de Tahet.', 'Los jeroglíficos que representan a un Tol\'vir encadenado señalan al extremo suroriental del mapa.$B$BTal vez llevaron a Tahet allí cuando lo tomaron prisionero.', '', 'El paradero de Tahet ', '', '', '', '', '', '', '', '', 0),
(27708, 'esMX', 'La hora del celador', 'Erunak Hablapiedra quiere que mates al celador Azjakir en El Encierro.', '<La imagen de Erunak penetra en tu mente.>$b$bLo has hecho bien, $n, pero aún hay más por hacer.$b$bAntes de abandonar este lugar, asegurémonos de dejarlo sumido en el caos.$b$bEncuentra a aquel que lidera a estos nagas y haz que pague por sus fechorías.', '', 'Celador Zin\'jatar asesinado', '', '', '', '', 'Erunak Hablapiedra', '', '', 'Habla con: Erunak Hablapiedra. Zona: Gruta Brumadensa, Bosque Kelp\'thar.', 0),
(27709, 'esMX', 'El juego del centinela', 'Completa el juego del centinela conectando las dos estatuas rojas.', 'Al colocar la estatua en su lugar, aparecen varias estatuas de piedra adicionales en la sala. En un pequeño recinto en el extremo más lejano de la misma, también aparece otra estatua color rubí. Oyes una voz:$b$b  "El centinela vigila.$b  El centinela protege.$b   La visión del centinela no flaquea."$b$bEsa estatua roja del otro lado de la habitación parece importante. ¿Tal vez deberías conectar las dos estatuas rojas?', '', 'Juego del centinela completado', '', '', '', '', '', '', '', '', 0),
(27711, 'esMX', 'De vuelta a las Profundidades de Elementium', 'Habla con el iniciado Minaoro en las Profundidades de Elementium, en las Tierras Altas Crepusculares.', 'El iniciado de la clamatierras, Minaoro, te necesita.$B$BCreo que están listos para que los ayudes con lo que sea que haya en esa mina.', '', '', '', '', '', '', '', '', '', '', 0),
(27712, 'esMX', 'De vuelta a las Profundidades de Elementium', 'Habla con el iniciado Minaoro en las Profundidades de Elementium, en las Tierras Altas Crepusculares.', '¿La clamatierras tiene un iniciado goblin? ¿Se llama Minaoro? Te necesita.$B$BCreo que están listos para que te encargues del trabajo sucio con lo que sea que haya en esa mina.', '', '', '', '', '', '', '', '', '', '', 0),
(27713, 'esMX', 'El día que vino Alamuerte', 'Escucha la historia de Theldurin.', 'Alamuerte armó un buen lío a su paso por estos lugares. Si no hubiese sido por mí, probablemente seguiría aún por aquí, arrasando a la buena gente que vive en las Tierras Inhóspitas.$b$b¿Cómo? ¿No me crees? Bien, deja que te cuente toda la historia.', '', '', 'Golpea a Alamuerte en la cara', '', '', '', '', '', '', 'Vuelve con: Theldurin el Perdido. Zona: Martillo de Agmar, Tierras Inhóspitas.', 0),
(27714, 'esMX', 'El día que vino Alamuerte: la historia real', 'Escucha la versión de la historia de Lucien Borlallave.', 'No solo es que la historia de Theldurin fuese falsa, es que era aburrida, carente de imaginación y lenta.$b$bYo te contaré cómo ocurrieron realmente las cosas ese día.', '', 'Crece lo suficiente como para llegar a las nubes', 'Nubes registradas', 'Encuentra a Alamuerte', '', '', '', '', '', 'Habla con: Lucien Borlallave. Zona: Cicatriz del Rompemundos en las Tierras Inhóspitas.', 0),
(27715, 'esMX', 'El día que vino Alamuerte: lo que ocurrió de verdad', 'Escucha la versión de la historia de Martek el Exiliado.', 'Esos dos no tienen ni idea de cómo contar una historia. La de Theldurin era demasiado corta y el cuento de Lucien se iba un poco por las nubes, ya me entiendes.$b$bAdemás, en ninguna de sus historias había chicas.$b$bPonte $gcómodo:cómoda;, $n. Te contaré lo que realmente ocurrió aquel día.', '', 'Escoge a un admirador al que salvar', 'Cabalga hasta el final del cañón', 'Encuentra a Alamuerte', 'Vence a Alamuerte en un combate a cuchillo', '', '', '', '', 'Habla con: Martek el Exiliado. Zona: Cicatriz del Rompemundos en las Tierras Inhóspitas.', 0),
(27716, 'esMX', 'Fragmento del pasado', 'Lleva las inscripciones élficas antiguas a Levia Despiertasueños. Tendrías que encontrarla junto a los supervivientes de Nespirah de la Alianza.', '<Una antigua losa de piedra ligeramente resquebrajada, con una enorme cantidad de inscripciones en todos sus lados. No eres capaz de descifrar la lengua, pero la gran cantidad de texto y el estilo parcialmente ornamentado de la piedra te indica que su contenido podría tener un valor significativo.>$B$B<Levia Despiertasueños, allá con los supervivientes de Nespirah, estaba buscando exactamente algo como esto.>', '', '', '', '', '', '', '', '', '', '', 0),
(27717, 'esMX', 'Fragmento del pasado', 'Lleva las inscripciones élficas antiguas a Elendri Frente Dorada. Tendrías que encontrarla junto a los supervivientes de Nespirah de la Horda.', '<Una antigua losa de piedra ligeramente resquebrajada, con una enorme cantidad de inscripciones en todos sus lados. No eres capaz de descifrar la lengua, pero la gran cantidad de texto y el estilo parcialmente ornamentado de la piedra te indica que su contenido podría tener un valor significativo.>$B$B<Elendri Frente Dorada, allá con los supervivientes de Nespirah, estaba buscando exactamente algo como esto.>', '', '', '', '', '', '', '', '', '', '', 0),
(27718, 'esMX', '¡La orden del Jefe de Guerra: Vashj\'ir!', 'Preséntate al comandante Thorak en la Bahía de Garrafilada, en Durotar.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el Comandante Thorak en la Bahía de Garrafilada, en Durotar.$B$B¡Ahora, más que nunca, se necesita tu ayuda para expulsar a nuestro enemigo más odiado, la Alianza!$B$BPara llegar a la Bahía de Garrafilada deberás viajar hacia el sur a través de las puertas principales de Orgrimmar y adentrarte en Durotar. Thorak estará esperando en su puesto cerca de los muelles.$B$B¡Adelante, $ghermano:hermana;! ¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(27719, 'esMX', 'Agua de vida', 'Usa el agua de vida para extraer información del cadáver del maestro de forja Finlay.', 'Toma mi agua de vida y hazla beber al cadáver del enano ahogado.$B$BEn vida fue un trabajador de los metales, y, aunque ahora su cuerpo nutra mi lago, el agua le permitirá decirte lo que quieres saber.$B$BConsigue la información que necesitas y desaparece de mis dominios.', '', 'Información sobre el artefacto conseguida', '', '', '', '', '', '', '', 'Habla con: Maestro Mathias Shaw. Zona: Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27720, 'esMX', 'El alucinante viaje del Señor Minaoro', 'Ve hasta el final de la vía en el vagón de mina con el iniciado Minaoro.', 'Muy bien, $n, tenemos que llegar al portal de la tierra que está en el fondo de la caverna.$B$BNos he "conseguido" un medio de transporte. ¿Por qué caminar si podemos viajar con clase? Espero que no tengas nada en contra de los vagones de mina.$B$BAvísame cuando estés $Glisto:lista;.', '', 'Habla con Minaoro para subir al vagón', 'Final de la vía', '', '', '', '', '', '', 'Habla con: Iniciado Minaoro. Zona: Interior de las Profundidades de Elementium, Tierras Altas Crepusculares.', 0),
(27721, 'esMX', '¡La orden del Jefe de Guerra: Monte Hyjal!', 'Habla con el emisario Cenarion Pezuñanegra para viajar a Claro de la Luna.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante la emisaria Son del Viento en Amparo de la Noche, en Claro de la Luna.$b$b¡Nuestros hermanos del Círculo Cenarion nos informan de que los esbirros de Alamuerte han iniciado una ofensiva de destrucción contra el Árbol del Mundo y amenazan con reducirlo a cenizas!$b$bHabla con el emisario Cenarion Pezuñanegra para entrar en Claro de la Luna. Pezuñanegra se encuentra en el distrito tauren del Valle de la Sabiduría, en Orgrimmar.$b$b¡Adelante, $ghermano:hermana;! ¡El destino te aguarda!', 'Viaje a Claro de la Luna conseguido', '', '', '', '', 'Viaje a Claro de la Luna conseguido', '', '', '', 'Habla con: Emisaria Son del Viento. Zona: Amparo de la Noche, Claro de la Luna.', 0),
(27722, 'esMX', 'Orden del Jefe de Guerra: ¡Infralar!', 'Habla con el clarividente Krogar en El Santuario de la Tierra del Oeste en Orgrimmar.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el Clarividente Krogar en El Santuario de la Tierra del Oeste en Orgrimmar.$B$B¡El Anillo de la Tierra, liderado por el antiguo Jefe de Guerra Thrall, necesita tu ayuda! ¡Nos han informado de que el plano elemental de Infralar amenaza con alcanzar nuestro mundo!$B$BEl Santuario de la Tierra del Oeste se encuentra justo al norte de El Valle de la Sabiduría.$B$B¡Adelante, $ghermano:hermana;! ¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(27724, 'esMX', 'Se busca héroe: ¡Vashj\'ir!', 'Habla con el reclutador Burns en el Puerto de Ventormenta, en la ciudad de Ventormenta.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse al reclutador Burns en el Puerto de Ventormenta.$B$B¡Hay que responder de manera rápida y contundente a los recientes ataques de la Horda a nuestros barcos mercantes!$B$BEl Puerto de Ventormenta está situado en la zona noroeste de la ciudad de Ventormenta.$B$B¡Por la gloria y el honor de la Alianza! ¡Prosigue la lucha, camarada!', '', '', '', '', '', '', '', '', '', '', 0),
(27725, 'esMX', 'Avanzada Quel\'Danil', 'Habla con la anacoreta Traska en la Avanzada Quel\'Danil.', 'Puede que te parezca que estoy lejos de casa, $c, pero unos cuantos de nosotros vinimos hasta aquí guiados por el embajador Rualeth. Nos hemos establecido con los altos elfos de la Avanzada Quel\'Danil, al noroeste, para entrenarnos en los caminos de la Luz y para disfrutar de la tranquila belleza de estas tierras.$B$BAunque esa tranquilidad tal vez dure poco. Hemos visto que la Horda avanza más al oeste de aquí. ¿Podrías viajar hasta Quel\'Danil y avisar a la anacoreta Traska? Su cabaña está justo al norte de la avanzada principal.', '', '', '', '', '', '', '', '', '', '', 0),
(27726, 'esMX', 'Se busca héroe: ¡Monte Hyjal!', 'Habla con la emisaria Cenarion Lunajade para conseguir un viaje a Claro de la Luna.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse a la emisaria Son del Viento en Amparo de la Noche, en Claro de la Luna.$b$b¡Nuestros hermanos del Círculo Cenarion nos informan de que los esbirros de Alamuerte han iniciado una ofensiva de destrucción contra el Árbol del Mundo y amenazan con reducirlo a cenizas!$b$bHabla con la emisaria Cenarion Lunajade en el Castillo de Ventormenta para entrar en Claro de la Luna.$B$B¡Por la gloria y el honor de la Alianza! ¡Prosigue la lucha, camarada!', 'Viaje a Claro de la Luna conseguido', '', '', '', '', 'Viaje a Claro de la Luna conseguido', '', '', '', 'Habla con: Emisaria Son del Viento. Zona: Amparo de la Noche, Claro de la Luna.', 0),
(27727, 'esMX', 'Se busca héroe: ¡Infralar!', 'Habla con Naraat el Hablatierra en El Santuario de la Tierra del Este en la Ciudad de Ventormenta.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Naraat el Hablatierra en El Santuario de la Tierra del Este en la Ciudad de Ventormenta.$B$B¡El Anillo de la Tierra necesita tu ayuda! ¡Nos informan de que el plano elemental de Infralar amenaza con alcanzar nuestro mundo y con destruir toda la vida de Azeroth!$B$BEl Santuario de la Tierra del Este se encuentra justo al noroeste del Castillo de Ventormenta.$B$B¡Por la gloria y el honor de la Alianza! ¡Sigue luchando, $ghermano:hermana;!', '', '', '', '', '', '', '', '', '', '', 0),
(27729, 'esMX', 'Otra vez las anguilas', 'Mata a 8 anguilas de cualquier tipo en el Bosque de Algas.', 'Las anguilas se cuentan entre las criaturas más siniestras de Azeroth.$b$bBueno, siempre están aquellos que fingen que no les importan. Y aquellos que incluso están de su parte.$b$bTodos mienten.$b$bA decir verdad, a nadie le gustan las anguilas. Ni a las propias anguilas.$b$bAzeroth sería un lugar mejor si nadie tuviese que soportar más la visión de una anguila deslizándose desde las turbias profundidades, preparada para morder.$b$bAsí de claro.', '', 'Anguilas desagradables justificadamente asesinadas', '', '', '', '', '', '', '', '', 0),
(27733, 'esMX', 'El viejo cambiazo', 'Mata a Randolph Moloch.', 'Mira, me encantaría dar la orden y ver cómo mis hombres vuelan por los aires a los rebeldes, pero no puedo porque todas las Mazmorras están bajo la jurisdicción del celador Thelagua y él solo quiere contenerlos.$b$bEn lugar de desobedecer órdenes, ¡vamos a encargarnos del asunto de una forma ligeramente diferente! Nos hemos hecho amigos de Mortimer Moloch, quien resulta que no es otro que el gemelo de Randolph Moloch, el despiadado líder de los rebeldes. Mata a Randolph, ¡y lo sustituiremos por Mortimer para poner un fin pacífico a la rebelión!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Comandante de rifles Coe.', 0),
(27737, 'esMX', 'Purificación por fuego', 'Hazte con el núcleo ígneo de Lord Quemado.', 'Soy una experta en los primeros auxilios y en otros tipos de sanación, y con la ayuda de mi Pozo de Luz he sido capaz de devolver la salud a muchos de nuestros hombres. ¡El problema es que este lugar es tan frío y húmedo que los pierdo aun habiendo sanado sus heridas!$b$bEl terremoto ha enfurecido a los elementos que habitan en la prisión... Cuando salieron de la tierra mataron a la mitad de los prisioneros. Si acabas con su líder, Lord Quemado, y me traes su núcleo, ¡podré utilizarlo para calentar a nuestros hombres!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Enfermera Lillian.', 0),
(27738, 'esMX', 'El Foso de Escamas', 'Rescata a Tahet en El Foso de Escamas, en Uldum.', 'Un punto en el extremo sur del mapa estaba marcado con jeroglíficos de cocodrilos enfrentándose entre sí.$B$BDebe de ser el lugar en el que Caimas se hizo con Tahet.$B$BDirígete a El Foso de Escamas y encuentra la manera de rescatar al hijo del visir.', '', 'Tahet liberado', '', '', '', '', '', '', '', '', 0),
(27739, 'esMX', 'El rey de los gnolls', 'Vence a Hogger.', '$n, me temo que debo pedirte lo imposible.$b$bLlevo un parche en el ojo por voluntad suya. Miles y miles de personas han muerto ante su ira. Conseguimos encerrarlo aquí de puro milagro.$b$bFue un grave error. Resistimos todo lo que pudimos, pero entonces llegaron ellos. Desde las sombras y la oscuridad salieron gnolls, súbditos de Hogger, que descuartizaron a mis mejores hombres.$b$bDebes vencer al rey de los gnolls antes de que organice otro ataque y nos mate a todos con su ira fría y sedienta de sangre.', '', '', '', '', '', '', 'Hogger', '', '', 'Vuelve con: Celador Thelagua.', 0),
(27740, 'esMX', 'Baba Cebafango', 'Habla con la pequeña Daisy la Loca para viajar por cañón hasta Baba Cebafango.', 'Oye, ¡el barón ha venido mientras estabas fuera! ¡Me ha apaleado hasta que ha empezado a caer dinero!$b$bPero eso lo hace siempre. ¡Esta vez también me ha pedido que te cuente algo! Quiere que vayas al sur y ayudes a nuestra herborista, Baba Cebafango.$b$b¡Está al otro lado del agua, pero habla con mi amiga Daisy ahí fuera y te enviará al otro lado al estilo Larry el Demente!', '', '', '', '', '', '', '', '', '', '', 0),
(27742, 'esMX', 'Un sobresueldo', 'Recoge 6 fragmentos de elementium.', 'Que sepas que es nuestra obligación moral salvar todo este elementium de las arañas de esquisto. ¡Esos bichos se lo comen!$b$b¡Qué desperdicio!$b$bVenga, ¿qué me dices? ¿90/10, a mi favor?', '', '', '', '', '', '', '', '', '', 'Habla con: Iniciado Minaoro. Zona: Profundidades de Elementium, Tierras Altas Crepusculares.', 0),
(27743, 'esMX', 'Ya que estamos aquí', 'Mata a 12 cultores Crepusculares, ya sean sobrestantes de las profundidades o mineros Crepusculares, en las Profundidades de Elementium.', 'Sabes, ya que estamos aquí, podríamos ocuparnos de los intrusos del Martillo Crepuscular. ¡Antes este sitio era nuestro, después de todo!$B$BMe gustaría ayudar, pero con mis tótems y mis armas rotas, no resultaría muy útil.', '', 'Cultores de las Profundidades de Elementium asesinados', '', '', '', '', '', '', '', 'Habla con: Iniciado Minaoro. Zona: Dentro de las Profundidades de Elementium, Tierras Altas Crepusculares.', 0),
(27744, 'esMX', 'Arruinando runas', 'Destruye la runa de tierra Crepuscular, la runa de agua, la runa de aire y la runa de fuego.', 'Al examinar la runa de tierra Crepuscular, casi puedes sentir cómo se extiende su poder hacia las Profundidades de Elementium.$B$BProbablemente esté conectada con las otras runas. El iniciado Minaoro cree que deberías destruirlas todas.', '', 'Runa de tierra destruida', 'Runa de agua destruida', 'Runa de aire destruida', 'Runa de fuego destruida', '', '', '', '', 'Habla con: Iniciado Minaoro. Zona: Profundidades de Elementium, Tierras Altas Crepusculares.', 0),
(27745, 'esMX', 'Un encuentro fogoso', 'Consigue el controlador de portal de fuego y úsalo en el portal de fuego.', 'Es Dientemagma, mi antiguo elemental de fuego. $n, tienes que matarlo, ¡o me matará él a mí!$B$BTodo fue un gran malentendido. ¿Cómo podía yo saber que se pondría furioso conmigo por "tomar prestado" su corazón en Infralar? No puede morir... ¡al menos no de manera permanente!$B$BSeguro que lleva encima el controlador del portal. Tienes que conseguir el controlador y usarlo en el portal de fuego para llevarnos a todos de vuelta a la entrada.', '', 'Usa el controlador de portal de fuego', '', '', '', '', 'Dientemagma', '', '', 'Dale el controlador a: Iniciado Minaoro. Zona: Entrada de las Profundidades de Elementium, Tierras Altas Crepusculares.', 0),
(27746, 'esMX', 'Imperio de tierra', 'Preséntate ante la suma ejecutora Darthalia en el Bloqueo Austral, Laderas de Trabalomas.', 'Esta guerra ha provocado grandes pérdidas humanas. Hemos perdido mucho para garantizar nuestro lugar como legítimos soberanos de Lordaeron. Y aunque hemos ganado esta batalla, la guerra continúa en otras partes de los Reinos del Este.$B$BDebo regresar a Entrañas para recuperarme. Quiero que vayas a las Laderas de Trabalomas en mi lugar, $n. Eres $gel soldado:la soldado; en quien más confío, liderarás nuestras fuerzas para dominar de forma absoluta a nuestros enemigos en Trabalomas.$B$BPreséntate ante la suma ejecutora Darthalia en el Bloqueo Austral, al este.', '', '', '', '', '', '', '', '', '', '', 0),
(27747, 'esMX', 'Guerra total', 'Rompe 10 barriles de cerveza de Bramal en las Ruinas de Bramal.', 'Muchos de los Martillo Salvaje han huido de sus hogares. Ha llegado la hora de borrarlos del mapa.$B$BEn las montañas del norte encontrarás casas abandonas en las Ruinas de Bramal. Han dejado atrás barriles de la potente cerveza de Bramal.$B$BLa cerveza de Bramal tiene 220 grados; no sé cómo es posible.$B$BRompe los barriles y prende fuego al contenido. ¡Quémalos! ¡Que los enanos no tengan a donde volver!', '', 'Barriles Martillo Salvaje rotos', '', '', '', '', '', '', '', 'Vuelve con: Harkkan. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(27748, 'esMX', 'Fortuna y gloria', 'Mata al coloso obsidiana.', 'Tenemos que seguir avanzando, $n. Solo es cuestión de tiempo que esas tropas se organicen.$b$bEl arca debería estar más allá de esas ruinas.$b$bPermanece alerta; algo me dice que esto no ha terminado aún...', '', 'Coloso obsidiana derrotado', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Ascenso del Hacedor.', 0),
(27750, 'esMX', 'Forraje de guerra', 'Reúne 10 provisiones de comida Martillo Salvaje en las Ruinas de Bramal.', '<A Griff le rugen las tripas.>$B$BSiempre que los Faucedraco van a la guerra, todos dejan de cazar.$B$BLa comida que mejor sabe es aquella robada de la boca del enemigo. En el monte, al norte del río, hay un puñado de casas Martillo Salvaje en ruinas. Apuesto a que están llenas de comida.$B$BTrae algo de esa comida a mi boca.', '', '', '', '', '', '', '', '', '', 'Llévale la comida a: Griff. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(27751, 'esMX', 'Aplastando el Martillo Salvaje', 'Mata aceros de guerra Martillo Salvaje para recoger 8 insignias Martillo Salvaje. Los personajes con nombre propio de las Ruinas de Bramal también llevan insignias. ', 'Desde que mi gente reclamó las Tierras Altas por primera vez, los enanos Martillo Salvaje han sido nuestros enemigos. Luchamos contra ellos en Grim Batol, luchamos contra ellos en Los Humedales, e incluso ahora resuenan ecos de batalla en el norte, al otro lado del río, entre las Ruinas de Bramal.$B$BDemuéstrame tu valor. Busca y destruye aceros de guerra Martillo Salvaje. Los mejores de ellos llevan insignias, mis guerreros las recogen por docenas.$B$B¿Podrás tú?', '', '', '', '', '', '', '', '', '', 'Llévale las insignias Martillo Salvaje a: Narkrall Rasgarra. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(27752, 'esMX', 'Lucha como un Martillo Salvaje', 'Recoge 10 barriles de cerveza de Bramal de las Ruinas de Bramal. Ten cuidado, ¡es fuerte!', 'No es un alarde decir que los Bramal preparamos la mejor cerveza de los Reinos del Este. Tiene 110 grados. ¡Sí, has oído bien!$B$BCuando la gente huyó del sur hacia el centro de la ciudad, tuvieron que dejar atrás su cerveza.$B$B<Blundy hace una pausa para dejar patente la gravedad de la situación.>$B$B¡RECUPÉRALA! Esa bebida convertirá al guerrero más debilucho en un remolino rabioso rebosante de destrucción. ¡Consigue esos barriles! ¡Es nuestra única esperanza!', '', '', '', '', '', '', '', '', '', 'Llévale la cerveza al chamán inferior Blundy en Bramal, en las Tierras Altas Crepusculares.', 0),
(27753, 'esMX', 'Nunca te dejes la comida atrás', 'Reúne 10 provisiones de comida Martillo Salvaje en las Ruinas de Bramal.', 'Quedan pocas provisiones, $n. No dejan de llegar refugiados a Bramal desde las montañas: eso son muchas bocas que alimentar.$B$BQuedaron muchas reservas de comida atrás mientras la gente intentaba poner a salvo a sus familias. ¡Necesitamos esa comida!$B$BRegistra las ruinas que hay hacia el sur, el este y el sudoeste de aquí en busca de provisiones de comida.$B$B¡Cuidado, $c! La lucha es muy intensa en las inmediaciones de las ruinas.', '', '', '', '', '', '', '', '', '', 'Llévale la comida a: Fanny Bramal. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(27754, 'esMX', 'La caída de los Faucedraco', 'Mata a maleantes Faucedraco y recoge 8 insignias Faucedraco. Los personajes con nombre propio de las Ruinas de Bramal también llevarán insignias.', '¡Los Faucedraco!$B$B<Colin escupe.>$B$BMonstruos, todos ellos. Luchamos contra ellos por todas las Tierras Altas desde la última guerra. ¿Y ahora se unieron a la Horda?$B$BSi quieres convencernos a nosotros, los Martillo Salvaje, de que nos unamos bajo el estandarte de la Alianza, será mejor que demuestres tu valor frente a los Faucedraco. Dirígete a la batalla que se está librando en las Ruinas de Bramal, al sur y al suroeste. Mata a maleantes Faucedraco y recoge las insignias que llevan sus mejores guerreros. Entonces hablaremos. ', '', '', '', '', '', '', '', '', '', 'Llévale las insignias a: Colin Bramal, en Bramal, Tierras Altas Crepusculares. ', 0),
(27755, 'esMX', 'La maldición de las tumbas', 'Asesina a 6 cavadores enloquecidos y al mekigeniero Giromezcla.', 'Los Neferset no son la única amenaza para nuestras tumbas sagradas.$B$BHace unas semanas, una expedición gnoma se topó con nuestras tierras.$B$BHicieron caso omiso a nuestras advertencias y excavaron demasiado profundo en una cámara maldita.$B$BAhora la expedición al completo sufre una terrible maldición que les ha robado la cordura y ha tomado el control de sus mentes.$B$BAhora pretenden acceder a las cámaras más profundas de Uldum; lo que supone una grave amenaza. $B$BDirígete al Bancal Piedrasol y acaba con el sufrimiento de sus desdichadas almas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Profeta del Sol Tumet. Zona: Nahom, Uldum.', 0),
(27756, 'esMX', 'El Supervisor', 'Mata a Glubtok.', 'Si queremos averiguar qué está pasando allá abajo, ¡vamos a tener que abrirnos paso por todas las Minas de la Muerte! Glubtok el Supervisor será el primer oponente importante que te encontrarás; es un poderoso ogro mago. Ten cuidado, ¡sus malignos hechizos respaldan la fuerza bruta de su raza!$b$bLlévate este comunicador para que pueda mantenerme en contacto contigo mientras proseguimos con nuestra investigación. Ten cuidado ahí abajo.', '', '', '', '', '', '', 'Glubtok', 'La trama se complica.', 'Teniente Horatio Laine', 'Habla con: Teniente Horatio Laine. Zona: Minas de la Muerte.', 0),
(27757, 'esMX', 'Las profundidades más oscuras', 'Mata a Hr\'nglth el Perdido.', 'He visto a muchas criaturas marinas actuando de forma extraña por todo el pantano. Los múrlocs, claro, pero antes estaban los gilblins, los makrura... El otro día hasta vi a un naga deambulando por la orilla.$b$bAlgo los está atrayendo y encima los incita al frenesí. Muchas criaturas se han acercado a la Cueva Stagalbog, al oeste. Hay algo ahí abajo, y si se hace más fuerte pronto todos empezaremos a dirigirnos allí...$b$bDeberías ponerle fin antes de que suceda.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Baba Cebafango. Zona: Stagalbog, Pantano de las Penas.', 0),
(27758, 'esMX', 'El carpintero', 'Vence a Helix Rompengranajes.', '<Bzzzzzzzzzzzzt.>$b$bHola, ¿me oyes? ¡Excelente!$b$bParece que Helix se encarga de construir un mástil enorme. ¿No creerás que intentan terminar el Gigante Defias?$b$bMejor ve a investigar, $n, ¡y que no te dé miedo ensuciarte las manos! Tienes autorización para utilizar medios letales, si es necesario... y seamos sinceros, seguramente será necesario.', '', '', '', '', '', '', 'Helix Rompengranajes', 'La cosa empieza a aclararse.', 'Teniente Horatio Laine', 'Habla con: Teniente Horatio Laine. Zona: Minas de la Muerte.', 0),
(27760, 'esMX', 'Inteligencia artificial', 'Habla con el terminal A.I.D.A. en la Avanzada de Vigilantes, en Uldum.', '<Una voz femenina se dirige a ti desde el terminal portátil.>$B$BCódigo de emergencia: 55-729.$B$BLas funciones del córtex cerebral superior de los miembros de la expedición se han visto dañadas.$B$BPreséntate en el terminal más cercano, al sureste del Bancal Piedrasol, para un análisis más detallado.', '', '', '', '', '', '', '', '', '', '', 0),
(27761, 'esMX', 'Una distracción que desarma', 'Desarma la primera, la segunda y la tercera traca de bombas y desactiva 4 bombabots inestables en la Tumba del Rey del Sol.', 'La maldición ha destruido las funciones cerebrales superiores de los miembros de la expedición, pero mis cálculos indican que todavía se les puede estimular el subconsciente adolescente reprimido con la ayuda de imágenes realistas.$B$BUtiliza este proyector holográfico para distraerlos.$B$BAhora mismo se encuentran colocando explosivos en la tumba que se encuentra al este; tratan de acceder a los pasadizos secretos de Uldum.$B$BBuscan tecnología de recreación peligrosa en las profundidades de Uldum. Debemos detenerlos.', '', 'Primera traca de bombas desactivada', 'Segunda traca de bombas desactivada', 'Tercera traca de bombas desactivada', 'Bombabot inestable desactivado', '', '', '', '', 'Vuelve a: Terminal A.I.D.A.', 0),
(27762, 'esMX', '¡El Diodo a la vista!', 'Ve en El Inaplastable hasta las Tierras Inhóspitas, luego preséntate ante Eddie Flofizzle.', 'Eh, $r, presta atención. Tengo una oportunidad para un trabajo que no te vas a querer perder.$B$BNos han enviado aquí desde El Diodo, una nueva ciudad goblin en lo más profundo de las Tierras Inhóspitas. Un montón de dinero esperándote, sí $gseñor:señora;. Y ni siquiera hay tantos zombis... o tantos paladines estirados.$b$bDe eso nada, aquello es una selva virgen, y estamos buscando a alguien como tú que nos ayude a explorarla. En cuanto estés $glisto:lista;... te estaremos esperando.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Eddie Flotfizzle. Zona: El Diodo de Mar, Tierras Inhóspitas.', 0),
(27763, 'esMX', 'Al mismo El Diodo', 'Usa el teletransportador de la parte de atrás de El Diodo de Mar para subir a la montaña. Después informa a Dolph Explosionus en El Diodo, en las Tierras Inhóspitas.', 'Esto es el paraíso, $r. Siempre he deseado vivir en un tranquilo y agradable pueblo junto al mar para poder centrarme en mis explosiones sin distracciones.$b$bAunque la tranquilidad no es para todo el mundo... Especialmente para aquellos del estilo aventurero como tú.$b$bHemos instalado un teletransporte en la parte de atrás del pueblo que te llevará a la parte superior de los acantilados. Desde allí, puedes tomar el camino rápido hacia el oeste, hacia el mismo El Diodo, en el interior de las Tierras Inhóspitas.$b$bSeguramente allí arriba tendrás más cosas que hacer. Diles que te envía Flo.', '', '', '', '', '', '', '', '', '', '', 0),
(27764, 'esMX', 'Una extraña petición', 'Lleva el paquete de Dolph a Rhea al Barranco Lethlor en las Tierras Inhóspitas.', 'Hablando de otros asuntos. Tengo un paquete que necesito entregar.$b$bUna chica joven vino a nuestro pueblo no hace mucho. Buscaba pólvora comprimida, una carcasa para bomba de mitril templado y unas gafas de seguridad. Naturalmente, teníamos pólvora y carcasas de bombas suficientes para venderle, pero las gafas de seguridad fueron algo más difíciles de encontrar.$b$bEn resumen. Ahora tengo las gafas, pero ella ya ha vuelto a sus estudios en el Barranco Lethlor. ¿Podrías llevárselas?', '', '', '', '', '', '', '', '', '', 'Informa a: Rhea. Zona: Barranco Lethlor, Tierras Inhóspitas.', 0),
(27765, 'esMX', 'Primera muestra: huevos salvajes', 'Obtén 6 huevos de dragón Negro salvaje.', 'Estoy experimentando con dragones Negros. En concreto, me interesa su procreación.$b$bPara mis experimentos actuales necesito bastantes huevos de dragón Negro, motivo por el que estoy en el Barranco Lethlor. Recogería los huevos yo misma, pero creo que te beneficiarás al ayudarme.$b$bLos encontrarás en los bordes del barranco. Cuidado con los guardianes que vuelan en círculos arriba. No les gusta que roben los huevos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Rhea. Zona: Barranco Lethlor, Tierras Inhóspitas.', 0),
(27766, 'esMX', 'Segunda muestra: crías', 'Obtén 10 cadáveres de cría hirviente.', 'Necesito que me hagas otro favor. Tienes que obtener los cuerpos de las crías de dragón Negro que vuelan por aquí cerca. Mátalas y tráeme sus cadáveres.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Rhea. Zona: Barranco Lethlor, Tierras Inhóspitas.', 0),
(27768, 'esMX', 'Paso dos: el flebotomista', 'Mata a Gomora el Flebotomista en la Carnicería.', 'Estos trols perpetúan la caída de mis hermanos a la pesadilla. Infectan y corrompen a los dragones Verdes con la sangre de su dios infame, y luego cosechan el mal que crece en su interior. Los cultivan como si fueran ganado...$b$bEste salvajismo repugnante no puede continuar. Vuelve al lugar en el que saliste de la Sala de las Máscaras y enfila el otro pasillo, hasta la Carnicería. Allí Gomora el Flebotomista cosecha cadáveres para sus rituales malvados e impuros. Quítale la vida; ¡no se la merece!', '', '', '', '', '', '', 'Gomora el Flebotomista', 'La piedra de juramento nos vincula.', 'Lord Itharius', '', 0),
(27769, 'esMX', 'La auténtica Rhea', 'Descubre la verdadera identidad de Rhea.', 'Como te sugerí antes, no soy una goblin normal. Puede que ya hayas adivinado mi identidad real.$b$bDeja que te muestre mi auténtica forma. Como has demostrado ser $gdigno:digna; de confianza, también compartiré contigo los detalles de mi plan.', '', 'Descubre la identidad real de Rhea', '', '', '', '', '', '', '', 'Habla con: Rheastrasza. Zona: Barranco Lethlor en las Tierras Inhóspitas.', 0),
(27770, 'esMX', 'Levantando el velo', 'Sé testigo de la última parte de los estudios de Rhea.', 'El Vuelo Negro era noble, antiguamente. Eran los guardianes de la tierra, la protegían. Qué ironía que se hayan convertido en la peor amenaza que la tierra haya conocido jamás.$B$BCreo que queda un resquicio de esperanza, a pesar de todo, al igual que mi maestra. El Vuelo Negro sobrevivirá a la traición de Alamuerte, y planeará una vez más como el noble guardián de la tierra.$B$BQuiero enseñarte algo. Cierra los ojos, y te revelaré la parte final de mis estudios.', '', 'Sé testigo de la última parte de los estudios de Rhea', '', '', '', '', '', '', '', 'Habla con: Rhea. Zona: Barranco Lethlor, Tierras Inhóspitas.', 0),
(27771, 'esMX', 'Tercera muestra: huevos implantados', 'Consigue 3 huevos de Nyxondra.', 'Nyxondra está retenida contra su voluntad. Está oculta de su linaje en el mismo centro de sus zonas de cría. Pone huevos, que le son arrebatados antes de que pueda ver cómo se rompen.$B$B¿Cruel? Tal vez... pero no tan cruel como la forma en que su Vuelo trató a mi maestra.$B$BDemuéstrame que puedo confiar en ti, $n. Coge los huevos de Nyxondra y tráemelos aquí. Tendrás que pelear para someterla antes de poder cogerlos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Rhea. Zona: Barranco Lethlor, Tierras Inhóspitas.', 0),
(27772, 'esMX', 'El venerable doctor Blam', 'Llévale las muestras de dragón Negro al Dr. Hieronymus Blam en El Final de Agmond, en las Tierras Inhóspitas.', 'Tomé una difícil decisión al revelarte mi identidad, $n. Necesitaba que confiaras en mí, pero ya no puedo permanecer aquí, en el Barranco Lethlor, ya que mi tapadera ha sido claramente descubierta.$B$BSin embargo, puede que consigas escabullirte sin ser $gvisto:vista;. Ten, coge los resultados de nuestra investigación y llévalos al oeste. En El Final de Agmond encontrarás a un gnomo que sabrá qué hacer con estas muestras.$B$B¡Date prisa, $n! ¡No debes entretenerte aquí más de lo necesario!', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Dr. Hieronymus Blam. Zona: El Final de Agmond, Tierras Inhóspitas.', 0),
(27773, 'esMX', 'Paso uno: el profeta', 'Derrota a Jammal\'an el Profeta.', 'Lo único que se interpone entre el templo y yo es el profeta Jammal\'an. Es el líder de los trols Atal\'ai, un manipulador despreciable.$b$bTen en cuenta que no te enfrentas a un simple trol demente, $n, sino a un instrumento de fuerzas más allá de nuestra comprensión más oscura. Pero no estás $gsolo:sola;; mi fuerza y la voluntad del Vuelo Verde te acompañan.$b$bVe hasta el Cubil del Clamor, sigue a la izquierda por la Sala de los Rituales y baja a la Sala de los Huesos. En el fondo encontrarás a Jammal\'an.', '', 'Jammal\'an el Profeta derrotado', '', '', '', '', 'Jammal\'an el Profeta', 'La piedra de juramento nos vincula.', 'Lord Itharius', '', 0),
(27774, 'esMX', 'Persuadidos fácilmente', 'Mata a 9 ogros Rotapolvo en el Asentamiento Kosh.', 'La amenaza más inmediata para El Diodo es, sin duda, la colonia de ogros del noroeste.$B$BLa mayoría de nuestros vecinos ogros solían ser guerreros, pero, por lo visto, cada vez hay más practicando magia. No tendré un ejército de magi ogros a mis puertas.$B$BVe a exterminar a algunos de esos ogros Rotapolvo. Con suerte, captarán el mensaje y evitarán desafiar el poder de El Diodo.', '', 'Rotapolvo asesinado', '', '', '', '', '', '', '', 'Vuelve con: Dolph Explosionus. Zona: El Diodo, Tierras Inhóspitas.', 0),
(27775, 'esMX', 'Cuando las cosas se pongan difíciles, haz trampa', 'Consigue una vara de instructor de un magi ogro instructor en el asentamiento Kosh.', '¡No logro que mi invento funcione! ¡Ah!$B$BEso es, lo tengo decidido. Haré trampas y usaré la magia.$B$BLo que mi invento necesita de verdad es un pistón sólido lo suficientemente fino como para caber en un tubo de cobre estrecho, pero lo suficientemente fuerte como para encajar impactos de forma repetida sin romperse. Las varas mágicas que llevan esos magi ogros al norte deberían servirme perfectamente.$B$BPor lo que sé, solo los instructores llevan los bastones resistentes.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Garyanne Golpellave. Zona: El Diodo, Tierras Inhóspitas.', 0),
(27776, 'esMX', 'Es la hora de las cabras', 'Utiliza el golpeador de cabras de Garyanne con 12 machos cabríos en El Diodo.', 'Tenemos un pequeño problema con las cabras, aquí, en El Diodo, por si no te habías dado cuenta. Se comen todo lo que encuentran, y parece que le han cogido el gusto a los engranajes y las piezas que solemos dejar por ahí.$B$B¡La situación se está volviendo insoportable!$B$BEncontrarás a la mayoría de los machos cabríos deambulando por los límites del pueblo, cerca del borde del acantilado. Usa este dispositivo para darles un "empujoncito".', '', 'Machos cabríos empujados', '', '', '', '', '', '', '', 'Vuelve con: Garyanne Golpellave. Zona: El Diodo, Tierras Inhóspitas.', 0),
(27777, 'esMX', 'Códigos de acceso al núcleo', 'Consigue los códigos de acceso al núcleo de Tornaflujo el Demente.', 'La cantidad de expedicionarios es inmensa, usuario $n.$B$BSi tratas de encargarte de ellos por métodos convencionales, te llevará aproximadamente 2.700.136,5 horas.$B$BPodemos utilizar una poderosa fuente de energía que se encuentra en el interior del vehículo reptador de la expedición.$B$BNecesitaremos los códigos de acceso al núcleo de fusión para conseguirlo.$B$BEl mekigeniero Tornaflujo tiene esos códigos y podrás encontrarlos en la torre de observación estelar al sureste.$B$BHe cargado frecuencias de interferencia en un codificador. Úsalas para desactivar temporalmente las defensas de Tornaflujo.', '', '', '', '', '', '', '', '', '', 'Vuelve a: Terminal A.I.D.A.', 0),
(27778, 'esMX', 'Piratear el Wibson', 'Piratea la unidad central Wibson en lo alto del Otilius.', 'Es cierto. Han llegado nuevos miembros de la expedición por mar.$B$BMis escáneres detectan que ya les ha afectado el fenómeno de la maldición.$B$BTienes que darte prisa y montar en el Otilius. Los códigos de acceso nos proporcionarán el control sobre el núcleo de fusión, pero todavía queda una capa de seguridad que debemos rebasar.$B$BUsuario $n, tengo que pedirte que piratees la sofisticadísima unidad central conocida como "Wibson".$B$BNo te preocupes, te proporcionaré más instrucciones.', '', 'Unidad central Wibson pirateada', '', '', '', '', '', '', '', 'Ve al núcleo de fusión en lo alto del Otilius en Uldum.', 0),
(27779, 'esMX', 'Gnomeliminación', 'Elimina a 1000 gnomos enloquecidos.', 'He descargado mi programa al núcleo de fusión y tengo control total sobre él.$B$BHe creado una pequeña bolsa de aire en el interior para evitar evaporar al usuario $n.$B$BCederé el control de todas las funciones de movimiento para poder dedicar mis ciclos a mantener el núcleo estable.$B$BBaja la colina y neutraliza a todos los miembros de la expedición que puedas.$B$BMi análisis indica que podrías sentir... "culpabilidad" por causa del alto número de víctimas.$B$BUsuario $n, debes convencerte de que los miembros de la expedición carecen de esperanzas.', '', 'Gnomo enloquecido eliminado', '', '', '', '', '', '', '', '', 0),
(27781, 'esMX', 'La maquinación', 'Destruye el Siegaenemigos 5000.', '<Bzzzzzzzzzzzzt.>$b$b<Bzzzzzzzzzzzzt.>$b$b¿Ho... hola? $n, ¿estás ahí? ¿Sigues con vida? ¿Hola?$b$b¡Ah, bien! ¡Sigues ahí! En el nombre de Lordaeron, ¿qué están construyendo? ¡Es algún tipo de monstruosidad mecanizada! ¡Debes impedir que completen esa... ese... esa cosa!$b$bOlvídate de las reglas, ¡haz lo que sea para evitarlo!', '', '', '', '', '', '', 'Siegaenemigos 5000', '¡El sigilo es la mejor opción!', 'Teniente Horatio Laine', 'Habla con: Teniente Horatio Laine. Zona: Minas de la Muerte.', 0),
(27782, 'esMX', 'Mathias te necesita', 'Habla con Mathias Shaw en la Ciudadela Crepuscular, en las Tierras Altas Crepusculares.', 'Hemos tenido buenos momentos. Lamento de veras verte partir. Pero Mathias dice que te necesita.$B$B¡Dijo que es urgente!$B$BBueno, ¿querrás tomar un trago o algo después de lo que sea, $gchaval:señorita;?', '', '', '', '', '', '', '', '', '', '', 0),
(27783, 'esMX', 'Garona te necesita', 'Habla con Garona Semiorco en la Ciudadela Crepuscular, en las Tierras Altas Crepusculares.', 'Hemos tenido buenos momentos. Lamento de veras verte partir. Pero Garona dice que te necesita.$B$B¡Dijo que es urgente!$B$BBueno, ¿querrás tomar un trago o algo después de lo que sea, $gchaval:señorita;?', '', '', '', '', '', '', '', '', '', '', 0),
(27784, 'esMX', 'El Martillo del Crepúsculo', 'Consigue el Martillo del Crepúsculo.', 'Mientras estabas en la mina, he podido averiguar dónde guardan el Martillo del Crepúsculo. Lo crearon en el Altar del Crepúsculo, al sur.$B$BMás importante aún, los adeptos han cometido un error fatal: Cho\'gall está supervisando personalmente su construcción definitiva.$B$BMuchos IV:7 murieron para traernos esta información.', '', '', '', '', '', '', '', '', '', '', 0),
(27785, 'esMX', 'El almirante', 'Mata al almirante Rasgagruñido.', '<Bzzzzzzzzzzzzt.>$b$bNo me lo puedo creer... ¡Casi han terminado de reconstruirlo! No tenemos mucho tiempo, $n.$b$bEl almirante Rasgagruñido, la mano derecha de Vanessa, tiene que estar a bordo. Nunca llegaremos hasta ella si sigue vivo y puede evitarlo. Vas a tener que subir al Gigante en construcción, encontrar a Rasgagruñido y matarlo para poder entrar en los aposentos privados de Vanessa en la cubierta superior.$b$bTen cuidado, ¡el almirante padece la maldición de los huargen y estará encantado de clavarte las garras!', '', '', '', '', '', '', 'Almirante Rasgagruñido', 'Ya está.', 'Teniente Horatio Laine', 'Habla con: Teniente Horatio Laine. Zona: Minas de la Muerte.', 0),
(27786, 'esMX', 'El Martillo del Crepúsculo', 'Consigue el Martillo del Crepúsculo.', 'Mientras estabas en la mina, he podido averiguar dónde guardan el Martillo del Crepúsculo. Lo crearon en el Altar del Crepúsculo, al sur.$B$BMás importante aún, los adeptos han cometido un error fatal: Cho\'gall está supervisando personalmente su construcción definitiva.$B$B<Garona empieza a afilar sus espadas.>$B$BMuchos Kor\'kron murieron para traernos esta información.', '', '', '', '', '', '', '', '', '', '', 0),
(27787, 'esMX', 'Trituracráneos la Montaña', 'Sobrevive y luego mata a Trituracráneos la Montaña.', '¡Era una trampa! Cho\'gall te atrajo con el Martillo del Crepúsculo, para que su gronn acabara contigo.$B$B¡Sobrevive y mata a Trituracráneos la Montaña!', '', 'Sobrevive al revés de Trituracráneos', '', '', '', '', 'Trituracráneos', '', '', 'Habla con: Kurdran Martillo Salvaje. Zona: Paso del Invicto, Tierras Altas Crepusculares.', 0),
(27788, 'esMX', 'Trituracráneos la Montaña', 'Sobrevive y luego mata a Trituracráneos la Montaña.', '¡Era una trampa! Cho\'gall te atrajo con el Martillo del Crepúsculo, para que su gronn acabara contigo.$B$B¡Sobrevive y mata a Trituracráneos la Montaña!', '', 'Sobrevive al revés de Trituracráneos', '', '', '', '', 'Trituracráneos', '', '', 'Habla con: Señora de la guerra Zaela. Zona: Machacolpe, Tierras Altas Crepusculares.', 0),
(27789, 'esMX', 'Problemas trogg', 'Sube a una torreta de Blam, luego sobrevive a cuatro oleadas de ataques trogg.', 'Necesitaré algo de tiempo para analizar estas muestras y tomarme un descanso de mi turno de disparar troggs. Ocupa una de mis torretas y acaba con tantos troggs como puedas. Yo estaré aquí, estudiando.$b$bLas torretas tienen dos facultades: un disparo normal y una sobrecarga eléctrica, ¡para cuando se acercan demasiados enemigos! Je, je, buena suerte.$b$bAh, y ten cuidado con los troggs grandes y lentos. No es buena idea que se te acerquen.', '', 'Sobrevive a la primera oleada', 'Sobrevive a la segunda oleada', 'Sobrevive a la tercera oleada', 'Sobrevive a la última oleada', '', '', '', '', 'Vuelve con: Dr. Hieronymus Blam. Zona: El Final de Agmond, Tierras Inhóspitas.', 0),
(27790, 'esMX', 'Principal de los Defias', 'Mata a la principal de los Defias.', 'Hola, $n. He oído hablar de ti. Escucha con atención, solo tendrás una oportunidad.$b$bLa nueva principal de los Defias debe de estar dentro de la cabaña, organizando toda la operación. Quiero que entres y acabes con ella, por el bien de cientos de inocentes que la organización que fundó su padre ha matado y aterrorizado.$b$bMe sorprende que te haya dejado acercarte tanto a su posición sin huir y esperar a circunstancias más favorables, pero parece que tenemos suerte.', '', '', '', '', '', '', 'Maestro Mathias Shaw', '', '', 'Habla con: Teniente Horatio Laine. Zona: Minas de la Muerte.', 0),
(27791, 'esMX', 'Excavación Viento Seco', 'Habla con el prospector jefe Durdin en la Excavación Viento Seco, en las Tierras Inhóspitas.', 'Tengo una idea, pero es una posibilidad muy remota. Por suerte, las posibilidades remotas son mi especialidad.$B$BAl norte de aquí, la Liga de Expedicionarios ha descubierto nuevas ruinas titánicas bajo la arena. Si hay algo más viejo y más sabio que los dragones, son los titanes. Diablos, si he oído rumores de que los titanes CREARON a los dragones.$B$BHabla con el prospector jefe Durdin en el campamento del norte. Tendrá más información que yo sobre esos titanes.$B$B¿Qué te dije? Es una posibilidad muy remota.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Prospector jefe Durdin. Zona: Excavación Viento Seco, Tierras Inhóspitas.', 0),
(27792, 'esMX', 'Todo vale en el amor, la guerra y la arqueología', 'Consigue un cáliz roto, un jarrón polvoriento, un jeroglífico terráneo y una herramienta trogg.', 'Lo primero es lo primero. No voy a sentarme aquí sin más y contarte todo lo que hemos descubierto en esas ruinas. ¡Tenemos problemas de los que ocuparnos!$B$BEl más apremiante es el de esos gamberros de las reliquias, justo al otro lado de la tumba. ¡Se están llevando todo nuestro botín! ¿Acaso no saben que excavar es un trabajo para enanos?$B$BCaza a algunos de sus "excavadores", bandidos, en mi opinión, y tráeme de vuelta algunos de esos artefactos.$B$BENTONCES hablaremos de titanes.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Prospector jefe Durdin. Zona: Excavación Viento Seco, Tierras Inhóspitas.', 0),
(27793, 'esMX', 'Protectores ancestrales', 'Examina al Celador y al Centinela.', 'Oíste un buen barullo que provenía de la cámara central de la tumba. Esas dos estatuas grandes parecían tremendamente sospechosas.', '', 'Celador examinado exhaustivamente', 'Centinela examinado exhaustivamente', '', '', '', '', '', '', 'Inspecciona: El tesoro del titán. Zona: Dentro de la Tumba de los Vigías, Tierras Inhóspitas.', 0),
(27794, 'esMX', 'Devolver a Blam', 'Llévale el Ojo de los vigías al Dr. Hieronymus Blam a El Final de Agmond en las Tierras Inhóspitas.', 'Dentro del cofre, encuentras un dispositivo pequeño y circular encima de un cojín.$B$BSi hay algún artefacto de los titanes en esta tumba, es ese. Te comprometes a traérselo de vuelta al Dr. Blam.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Dr. Hieronymus Blam. Zona: El Final de Agmond, Tierras Inhóspitas.', 0),
(27795, 'esMX', 'Mareas oscuras', 'Mata a 6 ogros de Rocal.', 'La batalla se desarrolla justo como yo quería. Ahora que sus guerreros están prácticamente agotados, he enviado a nuestra caballería.$b$bLo que no me esperaba era a los ogros. Nuestros caballeros están bien equipados para enfrentarse a los toscos, pero van a necesitar ayuda.$b$bQuiero que vuelvas al campo de batalla de inmediato, $n. Pocas personas pueden acabar con un ogro a pie, pero creo que puedo contar contigo. No me decepciones.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Joanna Corazón Azul. Zona: Avanzada Marea Pantanosa, Pantano de las Penas.', 0),
(27796, 'esMX', 'El peón de celador', 'Averigua para qué sirve el peón de celador dentro de la Tumba de los Vigías, en las Tierras Inhóspitas.', 'En cuanto los estúpidos del Relicario llegaron aquí, nos entró el pánico y empezamos a saquear indiscriminadamente.$B$BEse día hubo mucha arqueología de la mala.$B$BPor suerte. Olga se topó con esta pequeña estatua de jade. Creímos que era una especie de llave, pero no logramos averiguar qué es lo que abre. Puede que tú tengas más suerte con ella.', '', '', '', '', '', '', '', '', '', '', 0),
(27797, 'esMX', 'El peón de centinela', 'Averigua para qué sirve el peón de centinela dentro de la Tumba de los Vigías, en las Tierras Inhóspitas.', 'Uno de los rufianes del Relicario del Paso de Mirasangre casi nos roba esta estatua. Conseguimos cogerle en el acto y hemos recuperado la estatua, pero no ha servido de mucho.$B$BParece que es una especie de llave, pero no encuentro la cerradura en ningún rincón de estas ruinas. ¿Quieres intentarlo?', '', '', '', '', '', '', '', '', '', '', 0),
(27798, 'esMX', 'Agua de vida', 'Usa el agua de vida para extraer información del cadáver del maestro de forja Finlay.', 'Toma mi agua de vida y hazla beber al cadáver del enano ahogado.$B$BEn vida fue un trabajador de los metales, y, aunque ahora su cuerpo nutra mi lago, el agua le permitirá decirte lo que quieres saber.$B$BConsigue la información que necesitas y desaparece de mis dominios.', '', 'Información sobre el artefacto conseguida', '', '', '', '', '', '', '', 'Habla con: Garona Semiorco. Zona: Ciudadela Crepuscular, Tierras Altas Crepusculares.', 0),
(27799, 'esMX', 'Dije las palabras...', 'Interrumpe los rituales de los cultores en la Calle Mayor, el Valle del Honor y en las inmediaciones de la Puerta Oeste de la ciudad leyendo de forma equivocada las palabras del libro de conjuros.', 'Ahora que te has familiarizado con el ritual, ya es hora de que lo realices en la ciudad. Docenas de nuestros hermanos se han abierto paso hasta los lugares del ritual.$B$BQuiero que visites los lugares del ritual del portal en el segundo nivel de la Calle Mayor, el Valle del Honor, cerca del Bastión de los Valientes y en las inmediaciones de la Puerta Oeste de Orgrimmar. Los equipos que hay allí ya habrán realizado la mayoría de los preparativos y lo único que tendrás que hacer es leer la última parte del conjuro del libro.$B$BMuy pronto, la ciudad será pasto de las llamas.', '', 'Interrumpe el ritual en la Calle Mayor', 'Interrumpe el ritual en el Valle del Honor', 'Interrumpe el ritual cerca de la Puerta Oeste', '', '', '', '', '', 'Vuelve con: Guardia de sangre Torek. Zona: Valle de la Fuerza, Orgrimmar.', 0),
(27800, 'esMX', 'A infiltrarse de nuevo', 'Ponte tu toga de recluta, ve a la Pocilga y obtén el libro de conjuros del sobrestante Jintak. Lee el libro cerca del altar de cultor para llevar a cabo el ritual.', 'A pesar de que hemos capturado a muchos de ellos, los cultores parecen seguros de su victoria. Hemos de descubrir más acerca del ritual que mencionó aquel al que interrogaste.$B$BParece que esos rituales son el núcleo del plan para atacar Orgrimmar.$B$BCoge una de las togas que les quitamos a los cultores arrestados. Ya no las van a necesitar. Póntela, vuelve a su avanzada en la Pocilga, en Durotar, y trata de averiguar cosas sobre esos rituales y el papel que juegan en los planes del culto.', '', 'Practica el ritual de los cultores', '', '', '', '', '', '', '', 'Vuelve con: Sobrestante Jintak. Zona: la Pocilga, en Durotar.', 0),
(27801, 'esMX', 'Papeles, por favor', 'Ve a las puertas principales de Orgrimmar, lee la proclamación del Jefe de Guerra y registra a 5 ciudadanos de Orgrimmar. Confisca cualquier cosa sospechosa que encuentres.', 'Mis hombres han descubierto recientemente a un grupo de cultores tratando de colarse en la ciudad. El tráfico de entrada a Orgrimmar se ha detenido. El Jefe de Guerra ha decretado que todos los visitantes sean registrados antes de que crucen las puertas. Toma una copia de su proclamación y léesela a la gente que está reunida ante las puertas principales. Después, ayuda a los guardias a registrar a todo el que quiera entrar.', '', 'Ciudadanos de Orgrimmar registrados', 'Lee la proclamación del Jefe de Guerra', '', '', '', '', '', '', 'Vuelve con: Guardia de sangre Torek. Zona: Valle de la Fuerza.', 0),
(27802, 'esMX', 'Arresta a los infiltrados', 'Utiliza las esposas pesadas para arrestar a 5 infiltrados cultores y llévaselos al celador Gartok Puñofuria en el Círculo del Valor, en el Valle del Honor de Orgrimmar. Cuando vuelvas con los prisioneros, interroga al cultor detenido.', 'La nota que encontraste solo puede significar una cosa. La proclamación del Jefe de Guerra llegó demasiado tarde. Ya tenían infiltrados trabajando en la ciudad.$B$BEsta nota contiene instrucciones y lugares de reunión de los cultores. Nuestros enemigos se han vuelto más inteligentes. Va a ser difícil darles caza a todos, pero hemos de capturar al mayor número posible de ellos. Usa estas esposas para detener a los infiltrados y entrégalos al celador Gartok Puñofuria en el Círculo del Valor, en el Valle del Honor.', '', 'Cultores arrestados y llevados al Círculo del Valor', 'Interroga al cultor detenido', '', '', '', '', '', '', 'Vuelve con: Guardia de sangre Torek. Zona: Valle de la Fuerza, Orgrimmar.', 0),
(27803, 'esMX', 'Un merecido descanso', 'Mata a 8 ignitores subyugados.', 'Tengo a mis chicos formando líneas de defensa en todos los lados de la ciudad, evitando que los elementales manen de la tierra removida. Son buenos chicos y se han mantenido firmes, pero hasta el enano más robusto acaba por cansarse.$B$BSe han organizado por turnos: una hora de descanso por cada hora en las defensas. No puedo hacer nada más con los hombres de que dispongo.$B$BSi quieres ayudar, únete a una línea de defensa y elige un turno. Dales a mis chicos el respiro que se merecen. Vuelve para informar cuando hayas matado a varios elementales.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Keegan Barbafuego. Zona: Patrulla de Barbafuego, Tierras Altas Crepusculares.', 0),
(27804, 'esMX', 'Los únicos hogares que tenemos', 'Extingue 50 fuegos en Patrulla de Barbafuego.', 'Ya nos han hecho retroceder mucho más de lo que esperaba, pero no pienso dejar nuestros hogares en manos de esos chuchos. Puede que los quemen, los saqueen y que escupan en los escombros, pero seguiremos luchando para recuperarlos.$B$BDicho esto, prefiero que no los quemen. He hecho que los chicos traigan cubos de agua del pozo para controlar las llamas. Si te unieras a ellos, podrían ayudarte dándote los cubos para que no tengas que dar viajes.', '', 'Fuegos del poblado extinguidos', '', '', '', '', '', '', '', 'Vuelve con: Keegan Barbafuego. Zona: Patrulla de Barbafuego, Tierras Altas Crepusculares.', 0),
(27805, 'esMX', 'Pequeños placeres', 'Encuentra las rosas secas de Meara, el martillo de marfil de Parlan y la muñeca de Aprika, y devuélvelos.', '¿Puedo suponer que eres la cara nueva que está ayudando a Keegan? Encantada de conocerte. Tal vez puedas hacerle un par de favores más a los desdichados Martillo Salvaje que se han refugiado aquí.$B$BTodos tuvimos que retirarnos rápidamente a este edificio, y algunos dejamos atrás cosas de gran valor, aquí cerca, en nuestros hogares destruidos. ¿Te importaría traérnoslas cuando vuelvas? Le darías una gran alegría a algunas almas apesadumbradas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Cailin Altozano. Zona: Patrulla de Barbafuego, Tierras Altas Crepusculares.', 0),
(27806, 'esMX', 'Una tarea honorable', 'Habla con Iain Barbafuego en el Cementerio Barbafuego.', 'Iain, mi segundo al mando, llevó el cuerpo de uno de nuestros héroes caídos a la catedral, al oeste. Es el hombre al que le encargué recomponer un pelotón de jinetes de grifos con los efectivos que pudiera encontrar. Me gustaría que lo ayudases.$B$BDebe quedarte claro lo urgente que es esta tarea. No podremos aguantar aquí eternamente; el Martillo Crepuscular o los orcos Faucedraco acabarán por superarnos. Reunir a un pelotón activo puede ser nuestra única esperanza para sobrevivir a estos conflictos.', '', '', '', '', '', '', '', '', '', '', 0),
(27807, 'esMX', 'El clan Mullan', 'Habla con Duglas Mullan en el Crisol de Matanza.', 'Si queremos formar todo un pelotón de grifos, nos tendremos que mover rápido para reunir a todos los supervivientes antes de que se vayan o de que los encuentren. He sabido de algunos grupos de jinetes que permanecieron juntos. Pronto iré a buscar a los jinetes Bramal y a los jinetes Moore.$B$BLos Mullan se dirigían al oeste, hacia el Crisol de Matanza, la última vez que los vi. Ve a ver si puedes convencer a Duglas Mullan para que se una a Keegan: le debe un favor... o tres.', '', '', '', '', '', '', '', '', '', '', 0),
(27808, 'esMX', 'Cabezota como un Doyle', 'Habla con Keeland Doyle en el Bosque de las Tierras Altas.', 'Los jinetes Doyle fueron vistos por última vez yendo hacia los árboles del sur, en la frontera del Bosque Obsidiana. Son unos cabezotas y costará convencerlos para que se unan a nosotros.$B$BLa mejor manera será que le digas a Keeland Doyle que Cailin Altozano se ha refugiado en la ciudad, con nosotros. Keeland siente algo por ella y puede que eso baste para convencerle para que traiga a todos sus chicos con él.', '', '', '', '', '', '', '', '', '', '', 0),
(27809, 'esMX', 'El bramido de Barbafuego', 'Habla con Mackay Barbafuego en el Campamento de Guerra Gorshak.', 'También necesito que busques a Mackay y a sus hombres al otro lado de la Brecha Devoradora, en el Campamento de Guerra Gorshak.$B$BLos Faucedraco no sobrevivieron al ataque inicial y Mackay está intentando rescatar lo que pueda de su campamento para aprovisionar a nuestras tropas. No debería costar mucho convencerlos, pero querrán que alguien les ayude a empaquetarlo todo antes de volver con Keegan.$B$BDale una patada en el trasero de parte del viejo Iain si es necesario.', '', '', '', '', '', '', '', '', '', '', 0),
(27810, 'esMX', 'El espíritu de la lucha', 'Desafía y derrota a uno de los jinetes de grifos Mullan.', 'Keegan quiere que los Mullan alcen el vuelo con él, ¿eh? Si hay un enano para el que volaría, es él. Sin embargo, no entiendo por qué envía a $gun extranjero:una extranjera; para reclutarme, a mí no me parece muy educado.$B$BApuesto a que no le duras ni 20 segundos a uno de mis chicos, en el bar o en el campo de batalla. Demuestra que me equivoco. Derrota a uno de ellos en una pelea y luego consideraré lo de volar con el viejo Keegan.', '', 'Jinete de grifos Mullan derrotado', '', '', '', '', '', '', '', 'Habla con: Duglas Mullan. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27811, 'esMX', 'El olor de la batalla', 'Encuentra 8 grifos Mullan y entrégaselos a sus jinetes de grifos.', 'No dejes que Duglas te engañe, los Mullan están deseando volver a emprender el vuelo, y si hay alguien por quien estaríamos dispuestos a hacerlo, ese es Barbafuego.$B$BDejamos nuestros grifos en el Bosque de las Tierras Altas, al sur, para que pudieran cazar y alejarse del ruido de la batalla durante un tiempo. Se merecían un descanso.$B$BSi nos quieres ver volar pronto, harías bien en ayudarnos a traer de vuelta a nuestros grifos.$B$BToma este pedazo de abedul de las Tierras Altas carbonizado. Lo usamos en los entrenamientos: en cuanto lo huelan, volverán directos hacia nosotros.', '', 'Grifos Mullan encontrados y entregados', '', '', '', '', '', '', '', 'Vuelve con: Edana Mullan. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27812, 'esMX', 'La lealtad del clan Mullan', 'Llévale las noticias del clan Mullan a Iain Barbafuego, en el Cementerio Barbafuego.', 'Nos has convencido. Keegan puede contar con nosotros. Nos reuniremos con ellos en la ciudad cuando estén todos listos.$B$BEres $gduro:dura; para no ser $gun:una; Martillo Salvaje. Supongo que también saben $gcriarlos:criarlas; allí de donde vienes.$B$BSin embargo, todavía no te he visto beber. Eso será una prueba de verdad.', '', '', '', '', '', '', '', '', '', '', 0),
(27813, 'esMX', 'Una muerte digna de un Faucedraco', 'Derrota a 6 rezagados Faucedraco.', 'Los Crepusculares saquearon esta ciudad, matando a la mayoría de los Faucedraco que vivían en ella. Aunque algunos sobrevivieron, y no les gusta mucho la idea de que nos tomemos libertades con sus suministros.$B$BNo es que eso importe mucho.$B$BBueno, a mí no me gusta mucho la idea de que ataquen a mis chicos. Mátalos, échalos, me da igual, solo hazlos desaparecer.', '', 'Rezagado Faucedraco derrotado', '', '', '', '', '', '', '', 'Vuelve con: Mackay Barbafuego. Zona: Campamento de Guerra de Gorshak, Tierras Altas Crepusculares.', 0),
(27814, 'esMX', 'Todo lo que podamos conseguir', 'Llévale 8 armas Faucedraco a Brom Forjamartillo en el Campamento de Guerra Gorshak.', '¿Quedarnos y forjar más armas? ¡Bah! ¡Un Forjamartillo nunca ha tenido miedo de la batalla! ¿Quién necesita la seguridad del hogar para forjar armas? Además, hay montones de materia prima ahí fuera. Esas armas Faucedraco no sirven para nada, pero se pueden fundir para hacer armas de verdad. Tráeme 8 armas Faucedraco para que mi hija y yo podamos forjar auténticas armas con ellas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Brom Forjamartillo.', 0),
(27815, 'esMX', 'Algo para los chicos', 'Llévale las armas de Forjamartillo a Iain Barbafuego al Cementerio Barbafuego.', '¿Limpiaste el campamento y le hiciste recados a Forjamartillo? No está mal para $gun:una; $c $gnovato:novata;. Llévale esto a Iain, al Cementerio Barbafuego, y te recompensará por un trabajo bien hecho.', '', '', '', '', '', '', '', '', '', '', 0),
(27816, 'esMX', 'Una petición personal', 'Habla con Keegan Barbafuego en Patrulla de Barbafuego.', 'Una lástima lo de los Doyle. Aunque es un milagro que tantos lográsemos salir con vida, así que no me sorprende.$B$BEsos patanes de Bramal son unos cobardes. Se niegan a salir de la ciudad incluso después de decirles que es Keegan quien se lo pide. Pero conseguí convencer a los Moore, esos valen por tres clanes por lo menos.$B$BKeegan quería hablar contigo personalmente cuando volvieras. Ve a verlo en la ciudad.', '', '', '', '', '', '', '', '', '', '', 0),
(27817, 'esMX', 'Dejar caer el martillo', 'Mata a 12 vinculadores de tormentas Crepusculares y a Servias Vienterror usando uno de los grifos de Patrulla de Barbafuego.', 'Gracias a ti y a Iain, tenemos suficientes jinetes como para poder contraatacar al Martillo Crepuscular.$B$BEstamos entrenados para luchar mientras montamos, pero llevar a un segundo jinete para que maneje el martillo de tormenta suele ser más eficiente. Pensé que disfrutarías con ese honor.$B$BCoge tu grifo y únete a la lucha. Pero date prisa, queremos eliminar hasta el último de esos Martillo Crepuscular de esas rocas flotantes antes de una hora.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Keegan Barbafuego. Zona: Patrulla de Barbafuego, Tierras Altas Crepusculares.', 0),
(27818, 'esMX', 'Señales serpenteantes', 'Reúne 5 corazones de serpiente de Stagalbog intactos.', 'Me asenté aquí antes de que fundaran Chapaleos, para elaborar mis pociones y vivir en paz y tranquilidad. Conozco este pantano como la palma de mi mano vieja y marchita.$b$bHace poco ha habido un cambio en la fauna. Las sierpes voladoras que quizás hayas visto en Stagalbog son serpientes aladas. Hacía siglos que no las veíamos por aquí.$b$bSi son del tipo que yo creo, son una fuente estupenda de ingredientes. Sé un sol y tráeme algunos de sus corazones, ¿quieres?', '', '', '', '', '', '', '', '', '', 'Vuelve con: Baba Cebafango. Zona: Stagalbog, Pantano de las Penas.', 0),
(27819, 'esMX', 'TEST - RVM', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27821, 'esMX', 'Orcos y humanos', 'Mata a 8 guerreros de Rocal.', 'Con una guerra que se extiende por todo el mundo, lo último que necesitamos es un asentamiento de la Horda en nuestro patio trasero. Crestagrana, Bosque del Ocaso, e incluso Elwynn están todos a un día de viaje de aquí.$b$bHemos realizado el primer ataque y no pienso dejar que la Horda recupere el aliento. Así que considérate $gdesplegado:desplegada;. Coge un arma, únete al resto de las tropas en Fango de Sangre y empieza a matar orcos.$b$bVuelve cuando hayas causado daños. Te quiero $gvivo:viva;... Es una orden. ¡Retírate!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Joanna Corazón Azul. Zona: Avanzada Marea Pantanosa, Pantano de las Penas.', 0),
(27822, 'esMX', 'Patanes inútiles', 'Mata a 5 peones de Rocal.', 'Quiero que la victoria esté totalmente asegurada. No me basta con tener más recursos; tenemos que asegurarnos de que al enemigo no le queda nada.$b$bLas tropas de Rocal dependen de la madera que recogen de los bosques colindantes. Los peones orcos que cortan los árboles no son guerreros, pero solo sienten odio por los humanos.$b$bNo tengas piedad. Quiero que mates a los peones y que el suministro de madera de Rocal cese por completo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Joanna Corazón Azul. Zona: Avanzada Marea Pantanosa, Pantano de las Penas.', 0),
(27823, 'esMX', 'Un enano tiene necesidades', 'Consigue 15 jarras de Cebasombras.', 'No me malinterpretes, puedo reconocer una buena excavación tan bien como cualquier enano. Es solo que... bueno, excavamos tanto, y bebemos tan poco, que a veces me pregunto si debería dejar mi pala y regresar a Forjaz.$B$BPero hoy no. Todavía puedo excavar.$B$BEsos enanos Hierro Negro de la excavación de Piemartillo, justo al norte de aquí, hacen una cerveza fuerte excelente, aquí: en medio del desierto. ¿Crees que podrías conseguir un poco para mí?', '', '', '', '', '', '', '', '', '', 'Vuelve con: Sigrun Extracero. Zona: Excavación Viento Seco, Tierras Inhóspitas.', 0),
(27824, 'esMX', 'Buena mercancía', 'Busca el tesoro en la planta baja de la Fortaleza de Angor.', 'Tengo una pequeña proposición para ti, si te interesa.$B$BLos enanos Hierro Negro estaban aquí mucho antes de nuestra llegada. Eso significa que, una vez que se abrieron estas ruinas titánicas, los Hierro Negro fueron los primeros en entrar, saqueando todo lo bueno. Apuesto a que todavía tienen esos tesoros guardados en la Fortaleza de Angor, al noroeste de aquí.$B$BTu facultad para darle una paliza a un enano está más que demostrada. Ve a esa fortaleza y ábrete camino a mamporros hasta el tesoro.$B$BIría contigo, pero estoy borracho.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Sigrun Extracero. Zona: Excavación Viento Seco, Tierras Inhóspitas.', 0),
(27825, 'esMX', 'El más gordo sobrevive', 'Consigue 6 trozos de carne Rotapolvo y 10 sábanas de seda Rotapolvo.', 'Andamos escasos de suministros, $gextranjero:extranjera;. Con los dragones Negros sembrando la destrucción en lo que serían nuestros terrenos de caza, no hay forma de conseguir comida.$B$BLo ogros del suroeste, sin embargo, tienen justo lo que necesitamos. En su gruta deberías encontrar un montón de carne y demás suministros.$B$BPuede que opongan resistencia. Estate alerta.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Victoria Dolen. Zona: Boca del Dragón, Tierras Inhóspitas.', 0),
(27826, 'esMX', 'En la boca del dragón', 'Llévale el huevo de dragón Negro purificado a Rhea a Boca del Dragón, en las Tierras Inhóspitas.', '<El Dr. Blam mira el huevo fijamente en silencio, maravillado, parpadea un par de veces y te mira.>$b$b¿Ha... has visto eso? ¡Increíble! ¡Mi idea de los titanes ha funcionado! Con tu ayuda, por supuesto.$B$BSerá mejor que le llevemos esto de vuelta a Rhea. Ya no está en el Barranco Lethlor; parece ser que arruinó su tapadera cuando tomó su verdadera forma delante de todas esas crías. Ahora está en el oeste, en un campamento de la Alianza llamado Boca del Dragón.$B$BEstará esperándoos a ti y a ese huevo.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Rhea. Zona: Boca del Dragón, Tierras Inhóspitas.', 0),
(27827, 'esMX', 'El veloz, el fiero y el robusto', 'Habla con Eric "El Veloz" en Boca del Dragón, en las Tierras Inhóspitas.', 'Con las prisas por escapar del Barranco Lethlor, olvidé atar un cabo suelto: Nyxondra. Es libre, y ha dado la alarma entre el Vuelo Negro. Medio Vuelo está aquí, en las Tierras Inhóspitas del oeste, buscando ese huevo.$B$BMe encargaré de esconder el huevo. Tú te ocuparás de algunos de los dragones más problemáticos. Y tendrás ayuda.$B$BHabla con Eric, allá, al otro lado del campamento. Él y sus hermanos se unirán a ti.', '', '', '', '', '', '', '', '', '', '', 0),
(27828, 'esMX', 'Eric, el enano mañoso', 'Usa la Carga de Eric y la poción de bolsillo de Eric.', 'Antes de que nos volvamos locos matando dragones, déjame explicarte cómo peleo.$B$B"El Veloz", así me llaman, y te diré por qué: me lanzaré contra tus enemigos, con el casco por delante, no te creas, y los aturdiré durante unos segundos. También suelo llevar algunas pociones conmigo para las emergencias.$B$B¿Por qué no practicamos luchando juntos? Dirígete al campo y pon a prueba mis facultades.', '', 'Usa la Carga de Eric', 'Usa la poción de bolsillo de Eric', '', '', '', '', '', '', 'Habla con: Eric "El Veloz". Zona: Tierras Inhóspitas.', 0),
(27829, 'esMX', 'La ira del Vuelo', 'Mata a Kalaran el Aniquilador y a 4 soldados Huida oscura.', 'Hola, $n. Parece que ustedes cuatro han tenido tiempo para conocerse bien.$B$BTengo mi primera tarea para ti. Kalaran, un anciano dragón negro de considerable poder, se ha unido a la caza del huevo que estamos protegiendo. Tenemos que detenerlo antes de que se acerque demasiado.$B$BLo encontrarás a él y a sus esbirros en Terraseca, al noreste de Boca del Dragón. Dale caza y derrótalo. Seguramente necesitarás la ayuda de tus nuevos aliados enanos.', '', '', '', '', '', '', 'Rheastrasza', 'Aún queda trabajo por hacer.', 'Rheastrasza', '', 0),
(27830, 'esMX', 'Su caza continúa', 'Derrota al general Jirakka, a Moldarr y a 6 dragauros de la Huida oscura.', 'El Vuelo Negro va en serio. Por lo visto se han hecho con gran parte de Nuevo Kargath, el gran asentamiento de la Horda al noroeste de Boca del Dragón. Sus tropas están bajo el mando del general Jirakka y de su campeón, Moldarr. Tenemos que detenerlos.$B$BNosotros los dragones no intervenimos en las riñas entre la Horda y la Alianza, pero entiendo el riesgo que corréis al entrar en Nuevo Kargath. Héroes... tened cuidado.', '', '', '', 'Dragauro de la Huida oscura asesinado', '', '', 'Rheastrasza', 'Nuestro mayor desafío nos espera...', 'Rheastrasza', '', 0),
(27831, 'esMX', 'La pena y la ira', 'Mata a Nyxondra y a 12 estirpes de Nyxondra.', 'Mi mayor pesar es la forma en que tratamos... no, en que traté a Nyxondra. La obligué a poner huevos y luego hice experimentos con ellos. Una vez, y otra, y otra.$B$BYo también soy madre: puedo imaginar su dolor.$B$BNo... No debo ser débil. Después de todo, nuestro trabajo beneficiará a las futuras generaciones de dragones Negros. Su sacrificio era necesario.$B$BDa vueltas alrededor de las ruinas de Kargath, al noroeste de Nuevo Kargath, loca de ira. Os lo ruego, héroes... poned fin a su sufrimiento.', '', '', '', '', '', '', 'Rheastrasza', 'Ya casi ha terminado.', 'Rheastrasza', '', 0),
(27832, 'esMX', 'La Guarida Oculta', 'Habla con Rhea en la Guarida Oculta, en las Tierras Inhóspitas.', 'Ahora que la mayoría de los dragones Negros están fuera de las Tierras Inhóspitas, es seguro trasladar el huevo. Me encontrarás en una pequeña meseta, al norte de Nuevo Kargath.$B$BVen a verme.', '', '', '', '', '', '', 'Rheastrasza', '', '', '', 0),
(27833, 'esMX', 'Resistentes de media tonelada', 'Mata a 12 combatientes Rotapolvo. Puedes matar a aplastadores Rotapolvo o a chamanes Rotapolvo.', 'Diría que tenemos un problema con los dragones, pero parece que están más interesados en Nuevo Kargath que en nuestro pequeño campamento. De todos modos, tengo hombres que se encargan de mantener a los dragones a raya.$B$BSin embargo, hay un problema que se nos ha pasado por alto: el campamento ogro al sudoeste de nuestra posición. Por lo visto ha emergido de él un pequeño ejército de combatientes.$B$BNo podemos quedarnos sentados esperando a que nos rodeen, soldado. Diezma sus filas antes de que diezmen las nuestras.', '', 'Combatiente Rotapolvo asesinado', '', '', '', '', '', '', '', 'Vuelve con: Terrance Tormenta. Zona: Boca del Dragón, Tierras Inhóspitas.', 0),
(27834, 'esMX', 'Baelog, el cañón de cristal', 'Usa el Disparo del Valhalla de Baelog y el Alarido de guerra de Baelog.', 'Antes de que empiece a soltar flechas contra esos dragones, será mejor que me presente.$B$BSoy Baelog, el alma de este grupo. Mi espada muerde como un crocolisco, y mis flechas cantan como Reinas alma en pena. Sin embargo, suelo cansarme rápido, y no tengo tanto aguante como mis dos hermanos.$B$BDa la orden, y atravesaré el corazón de tu objetivo con un disparo certero. También puedo animar a mis hermanos inyectándoles el frenesí de la batalla.$B$B¿Por qué no intentamos pelear juntos?', '', 'Usa el Disparo del Valhalla de Baelog', 'Usa el Alarido de guerra de Baelog', '', '', '', '', '', '', 'Hablo con: Baelog. Zona: Tierras Inhóspitas.', 0),
(27835, 'esMX', 'Olaf, el grande', 'Usa el Muro de escudo de Olaf y el Grito poderoso de Olaf.', 'Puede que no te hayas dado cuenta, pero soy muy grande, para ser un enano.$B$BMe aseguro de que mis dos hermanos no se metan en demasiados líos. Son pequeños y no tienen un escudo grande como el mío. Soy grande, ¡puedo aguantar los golpes de unos cuantos monstruos! Además, si me ando con cuidado, ¡puedo lograr que golpeen mi escudo en vez de a mí!$B$BA ti también puedo protegerte. Venga, practiquemos un poco. Me aseguraré de que los enemigos me ataquen a mí y no a ti.', '', 'Usa el Muro de escudo de Olaf', 'Usa el Grito poderoso de Olaf', '', '', '', '', '', '', 'Habla con: Olaf. Zona: Tierras Inhóspitas.', 0),
(27836, 'esMX', 'Deteniendo la propagación', 'Destruye 6 huevos de deslizador.', 'Acabar con las criaturas que asolan el río no será suficiente, $n.$B$BUna nueva generación de estas monstruosidades amenaza ya con surgir en nuestras aguas sagradas.$B$BBusca sus malditos huevos y destrúyelos.', '', 'Huevo de deslizador destruido', '', '', '', '', '', '', '', 'Vuelve con: Sumo sacerdote Amet. Zona: Presa Vir\'naal, Uldum.', 0),
(27837, 'esMX', 'Intrusos en el agua', 'Asesina a 8 deslizadores aguaserena.', 'Poco después de que las barreras protectoras de Uldum cayeran, el río Vir\'naal se vio afectado por una terrible corrupción.$B$BEl hecho de que llegara hasta aquí de forma premeditada o por accidente, no tiene relevancia.$B$BEl resultado es el mismo. A medida que el río se cubre de neblina, nuestra capacidad para ver el futuro también se distorsiona.$B$BMira fuera, $c. Estas terribles criaturas nunca debieron habitar las prístinas aguas de nuestro río.$B$BAsesínalas para que el río nos proporcione visiones de nuevo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Sumo sacerdote Amet. Zona: Interior de la Presa Vir\'naal, Uldum.', 0),
(27838, 'esMX', 'La raíz de la corrupción', 'Dirígete a la fuente nororiental del río Vir\'naal y asesina a Madrescama Hevna.', 'Es posible que te hayas enfrentado a los síntomas de nuestro problema, $n. Pero he estado estudiando a estas malditas bestias y no están poniendo los huevos aquí.$B$BLa fuerza de la corriente lleva los huevos hasta la presa, sea lo que sea lo que los pone, está corriente arriba.$B$BDirígete al noreste, hasta la fuente principal del río, y enfréntate a la raíz de la corrupción.', '', '', '', '', '', '', 'Madrescama Hevna', '', '', 'Vuelve con: Sumo sacerdote Amet. Zona: Interior de la Presa de Nilos, Uldum.', 19865);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Objectives`, `Details`, `EndText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `QuestGiverTextWindow`, `QuestGiverTargetName`, `QuestTurnTextWindow`, `QuestTurnTargetName`, `CompletedText`, `VerifiedBuild`) VALUES
(27839, 'esMX', 'Armas antiguas', 'Recupera las armas de Tol\'vir antiguas', 'A pesar de que no estamos formalmente en guerra todavía, los Neferset no dudan a la hora de encarcelar o matar a todo el que invada su territorio.$B$BEl rey Phaoris se niega a hacer lo mismo, incluso sabiendo que utilizan nuestras tierras para pasar de contrabando antiguas reliquias de las tumbas de nuestros ancestros.$B$BMis exploradores me han informado de que los Neferset están a punto de transportar un gran cargamento de armas saqueadas al sur de aquí.$B$BHe formado a los trabajadores que reclutaste para que te ayuden. Llámalos con este cuerno cuando encuentres a los contrabandistas y recupera las armas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Alto comandante Kamses. Zona: Avanzada de la Legión Ramkahen, Uldum.', 0),
(27840, 'esMX', 'Cristales draenetistas', 'Hazte con 5 cristales draenetistas en el Retiro Fangoso.', 'Los Perdidos que habitan en Retiro Fangoso son como nosotros en apariencia pero, en realidad, son monstruos que enloquecieron debido a los rigores sufridos durante nuestro viaje a Azeroth. En su día hermanos nuestros, viven ahora en Retiro Fangoso hacia el oeste, donde atrapan o matan a todo aquel que vague por la zona.$B$BAdemás, nos han robado algo sagrado para nosotros: los cristales draenetistas.$B$BCarecemos de la fuerza necesaria para aventurarnos en Retiro Fangoso y recuperar la draenetista que nos ha sido robada de entre sus cabañas y hogueras, pero sin ella... quizás perdamos nosotros también nuestro camino.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Holaaru. Zona: Avanzada Marea Pantanosa, Pantano de las Penas.|n', 0),
(27841, 'esMX', 'Los muertos agradecidos', 'Consigue pan de muerto y dáselo al espíritu de goblin alegre en el cementerio de Orgrimmar.$B$BUsa una flor de muerto naranja para ver al espíritu que sin ella sería invisible.', 'Es genial volver a visitar a la familia y a los amigos, pero puede que me haya pasado... ¡Ya me he comido todo lo que me han preparado!$B$B¿Puedes tomarte la molestia de conseguirme un poco más de ese delicioso pan de muerto? Estaría muy agradecido...$B$BCreo que Buhonero vende la receta allí.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Espíritu de goblin alegre. Zona: Durotar.', 0),
(27842, 'esMX', 'Solo el principio', 'Mata a Glubtok.', 'Echo de menos los días en los que legiones enteras de poderosos ogros marchaban hacia la batalla codo con codo con la Horda; la patética Alianza se aterrorizaba de su ferocidad. A lo mejor esos días volverán antes de que me reúna con los ancestros.$b$bSin embargo, ya no es el caso. Un ogro mago, Glubtok, se ha aliado con la despreciable Hermandad Defias y hace las veces de supervisor de sus operaciones mineras. ¡Necio patético! Arrebátale la vida en mi nombre, ¡y por el espíritu y la gloria de la Horda!', '', '', '', '', '', '', 'Glubtok', 'Aún no has terminado, joven.', 'Kagtha', 'Habla con: Kagtha. Zona: Minas de la Muerte.', 0),
(27843, 'esMX', 'Refuerzos denegados', 'Mata a 3 brujos de Rocal.', 'No bastará con matar ogros. Los están invocando al campo de batalla con demasiada rapidez.$b$bQuiero que atravieses las líneas enemigas y busques a sus invocadores. Los orcos están utilizando brujos para traer refuerzos.$b$bAcaba con los brujos y los portales deberían cerrarse. No hay muchos; un ataque rápido y preciso debería bastar para sabotear al enemigo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Joanna Corazón Azul. Zona: Avanzada Marea Pantanosa, Pantano de las Penas.', 0),
(27844, 'esMX', '¡¡¡Traidores!!!', 'Vence a Helix Rompengranajes.', '¡Los goblins que encontrarás trabajando con los Defias son oficialmente traidores del Cártel Pantoque, la Mano Destrozada y la Horda misma!$b$bAún no me han iniciado en la Mano Destrozada, así que mi lealtad pertenece completamente a mi gente. Al parecer Helix Rompengranajes no tiene tiempo para semejantes escrúpulos y está construyendo un mástil para el Gigante Defias. De parte de Miss Caos y mía, ¿nos harías el favor de "encargarte" de Helix?', '', '', '', '', '', '', 'Helix Rompengranajes', '', '', 'Vuelve con: Finta Navajazos. Zona: Interior de las Minas de la Muerte.', 0),
(27845, 'esMX', 'La marca de los caídos', 'Utiliza el Estandarte de los Caídos para marcar a 7 lacayos Marea Pantanosa.', 'Nos hemos llevado a más de los que hemos perdido, pero hemos perdido a demasiados. Demasiados valientes han dado su vida por la Alianza en este lugar. Quiero asegurarme de que se les honra como es debido, independientemente de lo encarnizada que se vuelva la batalla.$b$bLlévate estas banderas y coloca una en cada soldado caído que encuentres. Los resguardos protectores de las mismas no ofrecen mucha protección contra la profanación, pero es mejor que nada. Así podré calcular cuántos soldados hemos perdido desde aquí.', '', 'Lacayo marcado', '', '', '', '', '', '', '', 'Vuelve con: Joanna Corazón Azul. Zona: Avanzada Marea Pantanosa, Pantano de las Penas.', 0),
(27847, 'esMX', 'No del todo', 'Destruye el Siegaenemigos 5000.', '¡Estos prototipos revolucionarán la estrategia bélica de la Horda cuando los perfeccione! El problema es que sus fuentes de alimentación no son compatibles con las maniobras de combate complicadas o los armazones grandes, dos cualidades muy deseables cuando se trata de luchar contra la Alianza.$b$bLos Defias, con la ayuda de ciertos goblins traidores como Helix, casi han terminado el Siegaenemigos 5000, ¡un gólem enorme que funciona de verdad!$b$bNo podemos permitir que se haga público, ¿a que no? ¡Perdería clientes!', '', '', '', '', '', '', 'Siegaenemigos 5000', '', '', 'Vuelve con: Miss Caos. Zona: Interior de las Minas de la Muerte.', 0),
(27848, 'esMX', 'Buenas intenciones... Ejecución pobre', 'Mata al almirante Rasgagruñido.', 'Los Defias planean terminar el Gigante y utilizarlo para arrasar Ventormenta. Es una causa noble, ¡y cualquier auténtico guerrero orco la tomaría sin dudarlo ni un segundo!$b$bEl fallo de Vanessa radica en la ejecución de su plan. La construcción del barco es pobre, la tripulación apenas está entrenada ¡y lo peor de todo es que hay un huargen entre ellos!$b$bSe llama almirante Rasgagruñido y hay que matarlo sin piedad en nombre del Jefe de Guerra. ¡Lok\'tar ogar!', '', '', '', '', '', '', 'Almirante Rasgagruñido', 'Fue un adversario digno.', 'Kagtha', 'Habla con: Kagtha. Zona: Minas de la Muerte.', 0),
(27849, 'esMX', 'Asalto a Rocal', 'Mata a 6 defensores de Rocal.', 'Muy bien, $n. Hemos llegado al último asalto sobre Rocal.$b$bNo debería tener que recordarte esto, pero lo diré de todas formas: no somos orcos, y no vamos a convertirnos en ellos por venganza o por rencor. No incendiaremos Rocal para bailar sobre sus cenizas.$b$bNo, quiero hacerlo bien. Quiero que sea preciso. Mantén la cabeza alta y abate a todo orco que tome un arma.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Joanna Corazón Azul. Zona: Avanzada Marea Pantanosa.', 0),
(27850, 'esMX', 'Principal de los Defias', 'Mata a la principal de los Defias.', 'La Mano Destrozada lleva años en silencio.$b$b¡Se acabó!$b$bSerás el instrumento de nuestro renacimiento, $n. ¡Mata a la principal de los Defias y confisca su barco para la Horda! Lo convertiremos en una auténtica nave de guerra de la Horda y la utilizaremos para arrasar Ventormenta de una vez por todas.$b$bLos pocos supervivientes que queden harán correr la voz de nuestro poder imparable y todo el mundo temblará ante nuestro poder.$b$bAhora ve, $ghéroe:heroína;, la muerte de VanCleef será tu mayor triunfo hasta la fecha.', '', '', '', '', '', '', 'Kagtha', '', '', 'Habla con: Kagtha. Zona: Minas de la Muerte.', 0),
(27851, 'esMX', 'Cortar el suministro', 'Confisca 5 cajones de suministros de Rocal.', 'Es posible que no vayamos a reducir Rocal a cenizas, pero no quiero tener que entrar allí una segunda vez.$b$bQuiero que recojas todos los suministros que veas en el pueblo mientras estés allí. Sin comida, no tendrán guerreros más de un día.$b$bDebería haber cajas desperdigadas por todo el pueblo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Joanna Corazón Azul. Zona: Avanzada Marea Pantanosa, Pantano de las Penas.', 0),
(27852, 'esMX', 'Orcos y humanos', 'Mata a 10 lacayos Marea Pantanosa.', 'Se libra una guerra en el pantano, $n. Unos despiadados humanos se han asentado al norte de la ciudad y han traído un ejército a nuestro hogar.$b$bNo hay nada en este pantano que les haga falta. Solo han venido hasta aquí para atacarnos, sin provocación. ¡No les daremos el placer de la victoria!$b$bNos falta personal y necesito que todos los orcos capaces se dirijan al campo de batalla. Ve y mata a todos los humanos que puedas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Comandante de envíos Ruag. Zona: Rocal, Pantano de las Penas.', 0),
(27853, 'esMX', 'Patanes inútiles', 'Mata a 5 campesinos Marea Pantanosa.', 'La Alianza nos supera en número. Tienen tanto miedo que han enviado a todo un ejército para aplastar un solo asentamiento. ¡Pero no nos rendiremos!$b$bSin recursos, sus soldados estarán en desventaja. Los campesinos humanos trabajan en los bosques que hay en el exterior de la Avanzada Marea Pantanosa; reúnen madera para reconstruir sus muros medio derruidos.$b$bNiégales la madera... y sus vidas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Comandante de envíos Ruag. Zona: Rocal, Pantano de las Penas.', 0),
(27854, 'esMX', 'Mareas oscuras', 'Mata a 6 caballeros Marea Pantanosa.', 'Hemos sufrido demasiadas pérdidas, $n. El Bastión Machacamiedo ha enviado ogros de las Tierras Devastadas como refuerzos, pero no son infinitos; la Alianza también los ataca a ellos, incluso ahora mismo.$b$bLa Alianza ha respondido a nuestros ogros con caballeros montados, una estrategia que les dio fruto en la Segunda Guerra. ¡Nos harán falta nuestros guerreros más fuertes para cambiar las tornas de la batalla!$b$bVuelve a Fango de Sangre, $n, ¡y acaba con esos caballeros!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Comandante de envíos Ruag. Zona: Rocal, Pantano de las Penas.', 0),
(27855, 'esMX', 'Refuerzos denegados', 'Mata a 3 magos Marea Pantanosa.', 'La Alianza ha traído a sus magos para invocar más refuerzos directamente al campo de batalla, desde su fortaleza. ¡Debemos detenerlos!$b$bSon pocos, pero un solo portal puede cambiar las tornas de una batalla. ¡Ataca a los magos y cierra los portales!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Comandante de envíos Ruag. Zona: Rocal, Pantano de las Penas.', 0),
(27856, 'esMX', 'La marca de los caídos', 'Utiliza el Estandarte de los Caídos para marcar a 7 guerreros de Rocal caídos.', 'Muchos guerreros se han entregado a la muerte para concedernos la victoria, $n. Es el destino del orco auténtico.$b$bHe visto cómo la Alianza despoja los cadáveres de los caídos, cómo se llevan sus bienes como ratas. No profanarán a nuestros héroes caídos de semejante manera.$b$bLlévate estos resguardos a Fango de Sangre. Colócalos en los cadáveres de guerreros caídos. Estaré observando, para ver cuántos han caído y para honrar su sacrificio. Ojalá los espíritus nos ayuden a cambio de nuestro respeto.', '', 'Guerrero de Rocal caído marcado', '', '', '', '', '', '', '', 'Vuelve con: Comandante de envíos Ruag. Zona: Rocal, Pantano de las Penas.', 0),
(27857, 'esMX', '¡Nos atacan!', 'Mata a 12 invasores Marea Pantanosa.', '¡La Alianza se abalanza sobre nuestros muros!$b$bTus actos los han retrasado y han debilitado sus filas, $n, pero aun así nos superan en número. Es nuestro último combate. Victoria o muerte...$b$bLucha con honor, $n. Están atravesando los muros ahora mismo. ¡Echa a los perros humanos de Rocal, por la Horda!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Comandante de envíos Ruag. Zona: Rocal, Pantano de las Penas.', 0),
(27858, 'esMX', 'El regalo de Rheastrasza', 'Espera mientras Rhea recupera el huevo de la Guarida Oculta.', 'Espera aquí. Voy a recuperar el huevo.', '', 'Espera a que Rhea recupere el huevo', '', '', '', '', '', '', '', 'Lee: Note de Rhea. Zona: Guarida Oculta, Tierras Inhóspitas.', 0),
(27859, 'esMX', 'El huevo sobrevive', 'Espera mientras Rhea recupera el huevo de la Guarida Oculta.', '', '', '', '', '', '', '', '', '', '', '', 0),
(27860, 'esMX', 'Los Perdidos', 'Mata a 12 Perdidos en el Retiro Fangoso.', 'Cuando el Portal Oscuro se cerró, hace muchos años, el arrepentimiento y el miedo atenazó a muchos de los que vinimos a estas tierras. En su desesperación, maldijeron el nombre de la Luz y se rebajaron a la violencia y al odio.$b$bEstas almas caídas son ahora Los Perdidos, poco más que monstruos sin conciencia que atacan a todo el que se les acerca. Cada día se corrompen más, y a medida que sus miembros van muriendo han empezado a secuestrar a gente de El Puerto...$b$bNo se les puede ayudar, $n. Su sufrimiento debe terminar. ¿Quieres liberarlos de su miseria?', '', 'Perdido matado', '', '', '', '', '', '', '', 'Vuelve con: Holaaru. Zona: Avanzada Marea Pantanosa, Pantano de las Penas.', 0),
(27861, 'esMX', 'El Crisol de Matanza: ¡el truhán Ojosangre!', '¡Entra en la arena en el Crisol de Matanza y derrota a Hurp\'derp!', '¡Me preguntaba cuando aparecerías, $n! ¡Tener a $gun antiguo campeón:una antigua campeona; de El Círculo de Sangre aquí atraerá a mucha gente! ¡Vamos a ser ricos, colega! ¡RICOS!$B$BBueno, esto es un antiguo foso de lucha de los Faucedraco. No hicieron falta muchas modificaciones para adaptarlo a nuestras necesidades. He tanteado el terreno y he conseguido que algunos pesos pesados de todo Azeroth se unan a la matanza. ¡Ya es hora de sacar algo de oro!$B$BYa sabes de qué va, $n. Cuando estés $glisto:lista; dímelo ¡y pondremos este espectáculo en marcha!', 'Hurp\'derp derrotado', '', '', '', '', 'Hurp\'derp derrotado', '', '', '', 'Vuelve con: Wodin, el sirviente trol. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27862, 'esMX', 'El Crisol de Matanza: ¡el truhán Ojosangre!', '¡Entra en la arena en el Crisol de Matanza y derrota a Hurp\'derp!', '¡Vaya, vaya, pero si es $gel antiguo campeón:la antigua campeona; de angustia, $n! ¡Veo un futuro lleno de dinero ahora que estás aquí! ¡Vamos a ser ricos, colega! ¡Asquerosamente RICOS!$B$BBueno, esto es un antiguo foso de lucha de faucedracos. No hicieron falta muchas modificaciones para adaptarlo a nuestras necesidades. He tanteado el terreno y he conseguido que algunos pesos pesados de todo Azeroth se unan a la matanza. ¡Ya es hora de sacar algo de oro!$B$BYa sabes de qué va, $n. Cuando estés $glisto:lista; dímelo ¡y pondremos este espectáculo en marcha!', 'Hurp\'derp derrotado', '', '', '', '', 'Hurp\'derp derrotado', '', '', '', 'Vuelve con: Wodin, el sirviente trol. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27863, 'esMX', 'El Crisol de Matanza: ¡el truhán Ojosangre!', '¡Entra en la arena en el Crisol de Matanza y derrota a Hurp\'derp!', 'Te diré una cosa, colega, a este sitio le falta mucho para parecerse a las llanuras de Nagrand o al barreño de sangre de Zul\'Drak, pero oye, ¡yo voy donde está el dinero! Así que $gbienvenido:bienvenida; a las Altas, $gamigo:amiga;.$B$BEres $gnuevo:nueva; en este foso, así que deja que te explique. Yo soy el promotor de luchas y este alegre trol que está a mi lado es Wodin, mi guardaespaldas. Tú eres el entretenimiento. Cuando quieras luchar, avísame y te prepararé un combate.$B$BSi estás $glisto:lista; y te acompaña un grupo de amigos, ¡podemos empezar! ¿Qué me dices?', 'Hurp\'derp derrotado', '', '', '', '', 'Hurp\'derp derrotado', 'Hurp\'derp', 'La mano derecha de Gurg.', 'Wodin', 'Vuelve con: Wodin, el sirviente trol. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27864, 'esMX', 'El Crisol de Matanza: ¡el mortal Faucedraco!', '¡Entra en la arena en el Crisol de Matanza y derrota a Torg Cazadraco!', '¡Esto te va a encantar! Los Faucedraco han oído que estarás en la arena y están decididos a no dejar que salgas de ella.$B$B¡Es hora de que $gel bueno:la buena; y $gviejo:vieja; $r se eche encima de ese orco! ¡Avísame cuando estés $glisto:lista;!', 'Torg Cazadraco derrotado', '', '', '', '', 'Torg Cazadraco derrotado', 'Torg Cazadraco', 'No hay amor como el de los trols.', 'Wodin', 'Vuelve con: Wodin, el sirviente trol. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27865, 'esMX', 'El Crisol de Matanza: ¡el perverso Martillo Salvaje!', '¡Entra en la arena en el Crisol de Matanza y derrota a Sully Cortarrótulas!', '¡Esto te va a encantar! Los Martillo Salvaje han oído que estarás en la arena y están decididos a no dejar que salgas de ella.$B$B¡Es hora de que $gel bueno:la buena; y $gviejo:vieja; $r se eche encima de ese enano! ¡Avísame cuando estés $glisto:lista;!', 'Sully Cortarrótulas derrotado', '', '', '', '', 'Sully Cortarrótulas derrotado', 'Sully Cortarrótulas', 'No hay amor como el de los trols.', 'Wodin', 'Vuelve con: Wodin, el sirviente trol. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27866, 'esMX', 'El Crisol de Matanza: ¡la creación de Calder!', '¡Entra en la arena en el Crisol de Matanza y derrota al Collage de cadáver!', 'Lúgubre y sangriento, el próximo encuentro hará rugir a las masas de una forma u otra. Calder Gray ha estado reuniendo los trozos de los cuerpos de los luchadores derrotados para construir al campeón perfecto.$B$BEsta cosa es la unión definitiva de cadáveres de combatientes. Un revuelto magnífico de monstruosidades destrozadas. ¡¿$GListo:Lista; para ensuciarte las manos?! ¡Yo lo estoy! ¡Avísame cuando estés $gpreparado:preparada; para que podamos empezar!', 'Collage de cadáver derrotado', '', '', '', '', 'Collage de cadáver derrotado', 'Collage de cadáver', 'Wodin sabe lo mucho que te gusta.', 'Wodin', 'Vuelve con: Wodin, el sirviente trol. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27867, 'esMX', 'El Crisol de Matanza: ¡el duque del destripamiento!', '¡Entra en la arena en el Crisol de Matanza y derrota a Lord Geoffery Tulvan!', 'Con este vas a tener más de lo que esperabas, colega. ¡Tenemos a un señor guerrero experimentado! Viene de Gilneas, y está dispuesto a demostrar que es el mejor guerrero a este lado de Azeroth.$B$BAsí que átate las botas y agárrate los pantalones, porque la cosa se va a poner fea. Avísame cuando estés $glisto:lista; para el castigo.', 'Lord Geoffery Tulvan derrotado', '', '', '', '', 'Lord Geoffery Tulvan derrotado', 'Lord Geoffery Tulvan', 'Lleva cuatro años y todavía no se ha cambiado de ropa.', 'Wodin', 'Vuelve con: Wodin, el sirviente trol. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27868, 'esMX', 'El Crisol de Matanza: ¡el terror Crepuscular!', '¡Entra en la arena en el Crisol de Matanza y derrota a Brasaescara el Devorador!', 'Esta vez tenemos a alguien a quien no te costará odiar. Al principio no estaba seguro de si debería dejarlo entrar en el foso, pero ¡una pelea es una pelea! ¡¿Y quién soy yo para rechazar unas ganancias garantizadas?!$B$BEste tipo viene de la mismísima Ciudadela Crepuscular, y tiene un buen par de puños. ¡Será mejor que te muevas rápido y no bajes la guardia! Avísame cuando estés $glisto:lista; para algo de acción.', 'Brasaescara el Devorador derrotado', '', '', '', '', 'Brasaescara el Devorador derrotado', 'Brasaescara', 'Tarareando blues.', 'Wodin', 'Vuelve con: Wodin, el sirviente trol. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(27869, 'esMX', 'El dragón y el templo', 'Habla con Lord Itharius en lo alto de las escaleras exteriores del Templo de Atal\'Hakkar.', 'Esas serpientes deben de ser del Templo de Atal\'hakkar. Ya me habían dado una pista...$b$bHace unos días, un visitante vino y me pidió que me mantuviera alerta con esos bichos. Un elfo llamado Itharius. Estoy segura de que se pensó que no vería su verdadera forma... Era un dragón Verde disfrazado que sin duda había venido para ayudar a sus hermanos.$b$bBien podría tener razón. Itharius se fue hacia el templo. A lo mejor deberías ir a buscarlo. Se acerca una oscuridad...', '', '', '', '', '', '', '', '', '', '', 0),
(27870, 'esMX', 'A la Avanzada Marea Pantanosa', 'Habla con Joanna Corazón Azul en la Avanzada Marea Pantanosa.', 'Tanto si me ayudas en el templo como si no, tu gente debe saber lo que está sucediendo aquí.$b$bAl norte del templo, los humanos de tu Alianza mortal han construido lo que llaman la Avanzada de Marea Pantanosa. Luchan con la Horda en el pantano, en un conflicto furioso que preveo que solo irá a peor.$b$bNo es mi trabajo interferir en los asuntos mortales, $n. Solo te pido que avises a tu gente de lo que se oculta en el templo.', '', '', '', '', '', '', '', '', '', '', 0),
(27871, 'esMX', 'A Rocal', 'Habla con el comandante de envíos Ruag en Rocal, en el Pantano de las Penas.', 'Tanto si me ayudas en el templo como si no, tu gente debe saber lo que está sucediendo aquí.$b$bAl sureste del templo se encuentra Rocal, el pueblo de la Horda. Los orcos del lugar libran una guerra contra los humanos recién llegados al pantano, en un conflicto furioso que preveo que solo irá a peor.$b$bNo es mi trabajo interferir en los asuntos mortales, $n. Solo te pido que avises a tu gente de lo que se oculta en el templo.', '', '', '', '', '', '', '', '', '', '', 0),
(27872, 'esMX', 'Misiones de Tortolla completadas', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27873, 'esMX', 'Misiones de Aviana completadas', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27874, 'esMX', 'El legado de Aviana', 'Encuentra a Choluna en el Santuario de Aviana, en Monte Hyjal.', 'Requieren tu pericia en otro lugar, $n.$B$BJusto al suroeste del Árbol del Mundo se encuentra el Santuario de Aviana, hogar de los druidas de la Garfa. Aviana, la matrona de todas las criaturas aladas, dio su vida por este mundo hace diez mil años.$B$BPercibo que su santuario está bajo amenaza, al igual que los druidas que lo custodian. Busca a Choluna, una de las druidas aladas más sabias, en el interior del santuario. ', '', '', '', '', '', '', '', '', '', 'Encuentra a: Choluna. Zona: Santuario de Aviana, Monte Hyjal.', 0),
(27875, 'esMX', 'Flor de plegaria', 'Recoge 10 ramos de flor de plegaria del Lodo Traicionero.', 'Llevo años intentando curar la aflicción de los Tábidos. Las energías malignas que los corrompieron no solo deformaron sus cuerpos; les arrebató el alivio de la Luz. No pueden sentir su calor.$b$bNo puedo permitir que Magtoor perezca en la oscuridad, $n. Antes de que empeorara yo examinaba la flor de plegaria, una que crece en el Lodo Traicionero. Prospera hasta en la sombra más oscura. Te lo ruego, tráeme esas flores, por el bien de Magtoor.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Anacoreta Avuun. Zona: El Puerto, Pantano de las Penas.', 0),
(27876, 'esMX', 'Los secretos del lodo', 'Recoge 10 muestras de cieno vigorizado de pegotes de lodo traicionero.', 'El Lodo Traicionero le debe su nombre a un fenómeno único. De alguna forma, el cieno es tan fino que se agrupa y se mueve solo, desplazándose como si tuviera vida propia.$b$bAl principio me preocupaba que fuera una fuerza corruptora, pero mis estudios han demostrado lo contrario: cualquiera que sea la energía que potencia la tierra, es de naturaleza positiva. Quizás esta vida tan enérgica se pueda transmitir a los Tábidos para devolverlos a su antiguo estado.$b$bEs posible que al cieno no le guste que lo recojan, $n, pero ayúdame a obtenerlo, por favor.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Anacoreta Avuun. Zona: El Puerto, Pantano de las Penas.', 0),
(27877, 'esMX', 'La Liga de Cretinos', 'Consigue 15 cabezas de Hierro Negro.', 'Necesito tu ayuda para un pequeño proyecto en el que estoy trabajando, $n. Tiene que ver con un campo que me gusta llamar "arqueología defensiva".$B$BMe gusta enterrar objetos no mágicos, en lugares llamativos, para engañar a esos idiotas de la Alianza y que piensen que han encontrado algo de valor.$B$BMmm... los enanos Hierro Negro merodean por la Excavación de Piemartillo y por la Fortaleza de Angor, al norte. Tráeme sus cabezas. Sí, eso es, sus cabezas.$B$BUna vez que les hayamos arrancado la carne, podemos usar esas calaveras para entorpecer el trabajo de los enanos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lidia Brillo del Sol. Zona: Paso de Mirasangre, Tierras Inhóspitas.', 0),
(27878, 'esMX', 'Adquisición forzosa', 'Busca el tesoro en la planta baja de la Fortaleza de Angor.', 'Tengo una pequeña propuesta para ti, si te interesa.$B$BLos enanos Hierro Negro estaban aquí mucho antes de nuestra llegada. Eso significa que, una vez que se abrieron estas ruinas titánicas, los Hierro Negro fueron los primeros en entrar y saquearon los mejores objetos. Apuesto a que todavía tienen esos tesoros guardados en la Fortaleza de Angor, al noroeste de aquí.$B$BQuiero que encuentres ese tesoro... y lo robes.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Aoren Brillo del Sol. Zona: Paso de Mirasangre, Tierras Inhóspitas.', 0),
(27879, 'esMX', 'El más gordo sobrevive', 'Consigue 6 trozos de carne Rotapolvo y 10 sábanas de seda Rotapolvo.', 'Andamos escasos de suministros, $gextranjero:extranjera;. Con los dragones Negros sembrando la destrucción en nuestros terrenos de caza, no hay forma de conseguir comida.$B$BLo ogros del sur, sin embargo, tienen justo lo que necesitamos. En su gruta deberías encontrar un montón de carne y demás suministros.$B$BPuede que opongan resistencia. Estate alerta.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Aidan Estiviento. Zona: Nuevo Kargath, Tierras Inhóspitas.', 0),
(27880, 'esMX', 'Resistentes de media tonelada', 'Mata a 12 combatientes Rotapolvo. Puedes matar a aplastadores Rotapolvo o a chamanes Rotapolvo.', 'Mis brutos tienen el problema de los dragones bajo control. Además, no puedo dejar que $gun:una; $c $gpresuntuoso:presuntuosa; como tú irrumpa aquí y arruine nuestros planes.$B$B¿Quieres trabajo? Bien, te daré trabajo. Inspecciona el campamento ogro al sudoeste de nuestra posición. Por lo que he oído, ha emergido de él un pequeño ejército de combatientes.$B$BNo podemos quedarnos sentados esperando a que nos rodeen, soldado... sobre todo cuando todavía nos estamos ocupando de los dragones Negros. Diezma sus filas antes de que diezmen las nuestras.', '', 'Combatiente Rotapolvo asesinado', '', '', '', '', '', '', '', 'Vuelve con Gorn. Zona: Nuevo Kargath, Tierras Inhóspitas.', 0),
(27881, 'esMX', 'Paso de Mirasangre', 'Habla con el alto examinador Tae\'thelan Mirasangre en el Paso de Mirasangre, en las Tierras Inhóspitas.', 'Tengo una idea, pero es una posibilidad muy remota. Por suerte, las posibilidades remotas son mi especialidad.$B$BAl norte de aquí, el Relicario ha descubierto nuevas ruinas titánicas bajo la arena. Si hay algo más viejo y más sabio que los dragones, son los titanes. Diablos, si he oído rumores de que los titanes CREARON a los dragones.$B$BHabla con el alto examinador Tae\'thelan Mirasangre en su campamento del noroeste. Tendrá más información que yo sobre esos titanes.$B$B¿Qué te dije? Es una posibilidad muy remota.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Alto examinador Tae\'thelan Mirasangre. Zona: Paso de Mirasangre, Tierras Inhóspitas.', 0),
(27882, 'esMX', 'No se trata de historia, sino de poder', 'Consigue un cáliz roto, un jarrón polvoriento, un jeroglífico terráneo y una herramienta trogg.', 'Puede que la Liga de Expedicionarios tenga los conocimientos de un granjero sobre el acto de cavar en sí. Lo que les falta, sin embargo, es el sentido común para USAR los artefactos que desentierran. Almacenan sus tesoros en museos en vez de usar esos objetos de poder para su auténtico propósito.$B$BLos enanos son tontos. Afortunadamente, mueren con facilidad.$B$BLos encontrarás cavando en las paredes de cañón al norte de aquí. Quítales lo que puedas de sus manos rechonchas y tráemelo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Alto examinador Tae\'thelan Mirasangre. Zona: Paso de Mirasangre, Tierras Inhóspitas.', 0),
(27883, 'esMX', 'El peón de celador', 'Averigua para qué sirve el peón de celador dentro de la Tumba de los Vigías, en las Tierras Inhóspitas.', 'Uno de los pocos objetos de valor que conseguimos saquear de esas ruinas fue esta pequeña estatua de jade.$B$BCreemos que es algún tipo de llave, pero no conseguimos determinar lo que abre. A mí así no me sirve para nada.$B$BTal vez tú tengas más suerte con ella.', '', '', '', '', '', '', '', '', '', '', 0),
(27884, 'esMX', 'El peón de centinela', 'Averigua para qué sirve el peón de centinela dentro de la Tumba de los Vigías, en las Tierras Inhóspitas.', 'Encontramos una pequeña estatua roja en el cadáver de uno de esos arqueólogos de la Liga de Expedicionarios. Desgraciadamente, no lo matamos nosotros. La vida salvaje local ya se había encargado de ello.$B$BLa estatua está bien confeccionada, pero aparentemente carece de poder mágico alguno. Puedes usarla para cualquier fin que consideres necesario.', '', '', '', '', '', '', '', '', '', '', 0),
(27885, 'esMX', 'El juego del celador', 'Completa el juego del celador teletransportando a los peones del celador a posiciones en las que miren hacia dentro.', 'Contemplas como la estatua se divide en dos, luego en cuatro y, por último, en ocho estatuas idénticas en una formación cuadrada.$b$bOyes una voz, pero no proviene del exterior, sino de tu propia mente:$b$b   "Un auténtico celador no mira HACIA FUERA, en busca de señales de peligro.$b  Un auténtico celador mantiene la mirada HACIA DENTRO, siempre centrado en la protección de aquello que custodia."$b$b¿Será algún tipo de acertijo?', '', 'Juego del celador completado', '', '', '', '', '', '', '', '', 0),
(27886, 'esMX', 'El juego del centinela', 'Completa el juego del centinela conectando las dos estatuas rojas.', 'Al colocar la estatua en su lugar, aparecen varias estatuas de piedra adicionales en la sala. En un pequeño recinto en el extremo más lejano de la misma, también aparece otra estatua color rubí. Oyes una voz:$b$b  "El centinela vigila.$b  El centinela protege.$b   La visión del centinela no flaquea."$b$bEsa estatua roja del otro lado de la habitación parece importante. ¿Tal vez deberías conectar las dos estatuas rojas?', '', 'Juego del centinela completado', '', '', '', '', '', '', '', '', 0),
(27887, 'esMX', 'Protectores ancestrales', 'Examina al Celador y al Centinela.', 'Oíste un buen barullo que provenía de la cámara central de la tumba. Esas dos estatuas grandes parecían tremendamente sospechosas.', '', 'Celador examinado exhaustivamente', 'Centinela examinado exhaustivamente', '', '', '', '', '', '', 'Inspecciona: El tesoro del titán. Zona: Dentro de la Tumba de los Vigías, Tierras Inhóspitas.', 0),
(27888, 'esMX', 'Devolver a Blam', 'Llévale el Ojo de los vigías al Dr. Hieronymus Blam a El Final de Agmond en las Tierras Inhóspitas.', 'Dentro del cofre, encuentras un dispositivo pequeño y circular encima de un cojín.$B$BSi hay algún artefacto de los titanes en esta tumba, es ese. Te comprometes a traérselo de vuelta al Dr. Blam.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Dr. Hieronymus Blam. Zona: El Final de Agmond, Tierras Inhóspitas.', 0),
(27889, 'esMX', 'Nuevo Kargath', 'Llévale el huevo de dragón negro purificado a Rhea a Nuevo Kargath, en las Tierras Inhóspitas.', '<El Dr. Blam mira el huevo fijamente en silencio, maravillado, parpadea un par de veces y te mira.>$b$b¿Ha... has visto eso? ¡Increíble! ¡Mi idea de los titanes ha funcionado! Con tu ayuda, por supuesto.$B$BSerá mejor que le llevemos esto de vuelta a Rhea. Ya no está en el Barranco Lethlor; parece ser que arruinó su tapadera cuando tomó su verdadera forma delante de todas esas crías. Ahora está en el oeste, en un gran establecimiento de la Horda llamado "Nuevo Kargath".$B$BEstará esperándote a ti y a ese huevo.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Rhea. Zona: Nuevo Kargath, Tierras Inhóspitas.', 0),
(27890, 'esMX', 'Los perros malos', 'Habla con Amakkar en Nuevo Kargath, en las Tierras Inhóspitas.', 'Con las prisas por escapar del Barranco Lethlor, olvidé atar un cabo suelto: Nyxondra. Es libre, y ha dado la alarma entre el Vuelo Negro. Medio Vuelo está aquí, en las Tierras Inhóspitas del oeste, buscando ese huevo.$B$BMe encargaré de esconder el huevo. Tú te ocuparás de algunos de los dragones más problemáticos. Y tendrás ayuda.$B$BLe he pagado a un par de mercenarios para que te ayuden. Los encontrarás en esa posada.', '', '', '', '', '', '', '', '', '', '', 0),
(27891, 'esMX', 'Amakkar, el manitas', 'Utiliza el Golpe en los riñones de Amakkar y la poción de bolsillo de Amakkar.', 'Antes de que nos volvamos locos matando dragones, déjame contarte algo sobre cómo peleo.$B$BNo soy tremendamente fuerte o duro como esos otros dos, pero conozco unos cuantos trucos. Cuando lo ordenes, sorprenderé a tus enemigos haciendo que se queden paralizados. También me aseguro de tener algunas pociones cerca para las emergencias.$B$B¿Por qué no practicamos luchando juntos? Dirígete al campo y verás lo que es luchar con un orco de verdad.', '', 'Usa el Golpe en los riñones de Amakkar', 'Usa la poción de bolsillo de Amakkar', '', '', '', '', '', '', 'Habla con: Amakkar. Zona: Tierras Inhóspitas.', 0),
(27892, 'esMX', 'Jurrix el Ígneo', 'Usa la Explosión ígnea de Jurrix y la Distorsión temporal de Jurrix.', 'Oh, ¿con que quieres hablar? Vale.$B$BSoy Jurrix, el único condotiero con medio cerebro que hay por aquí. También soy el único cuyos ataques causen algún efecto. La única razón por la que sigo con estos escudos de carne alrededor mío es para evitar que me maten.$B$BEscucha, estás al mando de esta operación. Da la orden y atravesaré el corazón del objetivo con una bola de fuego. Si las cosas se descontrolan, puedo distorsionar el tiempo para que puedas lanzar un par de ataques más.$B$B¿Por qué no intentamos pelear juntos?', '', 'Usa la Explosión ígnea de Jurrix', 'Usa la Distorsión temporal de Jurrix', '', '', '', '', '', '', 'Habla con: Jurrix Melenablanca. Zona: Tierras Inhóspitas.', 0),
(27893, 'esMX', 'Gargal, el Behemoth', 'Usa el Muro de escudo de Gargal y el Grito poderoso de Gargal.', 'Puede que no te hayas dado cuenta, pero soy muy grande, para ser un orco.$B$BMe aseguro de que estos dos amigos míos no se metan en demasiados líos. Son pequeños y no tienen un escudo grande como el mío. Soy grande, ¡puedo aguantar los golpes de unos cuantos monstruos! Además, si me ando con cuidado, ¡puedo lograr que golpeen mi escudo en vez de a mí!$B$BA ti también puedo protegerte. Venga, practiquemos un poco. Me aseguraré de que los enemigos me ataquen a mí y no a ti.', '', 'Usa el Muro de escudo de Gargal', 'Usa el Grito poderoso de Gargal', '', '', '', '', '', '', 'Habla con: Gargal. Zona: Tierras Inhóspitas.', 0),
(27894, 'esMX', 'La ira del Vuelo', 'Mata a Kalaran el Aniquilador y a 4 soldados Huida oscura.', 'Hola, $n. Parece que ustedes cuatro han tenido tiempo para conocerse bien.$B$BTengo mi primera tarea para ti. Kalaran, un anciano dragón negro de considerable poder, se ha unido a la caza del huevo que estamos protegiendo. Tenemos que detenerlo antes de que se acerque demasiado.$B$BLo encontrarás a él y a sus esbirros en Terraseca, al este de Nuevo Kargath. Dale caza y derrótalo. Seguramente necesitarás la ayuda de tus nuevos aliados mercenarios.', '', '', '', '', '', '', 'Rheastrasza', 'Aún queda trabajo por hacer.', 'Rheastrasza', '', 0),
(27895, 'esMX', 'Su caza continúa', 'Derrota al general Jirakka, a Moldarr y a 6 dragauros de la Huida oscura.', 'El Vuelo Negro va en serio. Como ya habrás visto, se han hecho con gran parte de Nuevo Kargath. Esas tropas están bajo el mando del general Jirakka y de su campeón, Moldarr. Hay que detenerlos.', '', '', '', 'Dragauro de la Huida oscura asesinado', '', '', 'Rheastrasza', 'Nuestro mayor desafío nos espera...', 'Rheastrasza', '', 0),
(27896, 'esMX', 'La pena y la ira', 'Mata a Nyxondra y a 12 estirpes de Nyxondra.', 'Mi mayor pesar es la forma en que tratamos... no, en que traté a Nyxondra. La obligué a poner huevos y luego hice experimentos con ellos. Una vez, y otra, y otra.$B$BYo también soy madre: puedo imaginar su dolor.$B$BNo... No debo ser débil. Después de todo, nuestro trabajo beneficiará a las futuras generaciones de dragones Negros. Su sacrificio era necesario.$B$BDa vueltas alrededor de las ruinas de Kargath, al noroeste de Nuevo Kargath, loca de ira. Os lo ruego, héroes... poned fin a su sufrimiento.', '', '', '', '', '', '', 'Rheastrasza', 'Ya casi ha terminado.', 'Rheastrasza', '', 0),
(27897, 'esMX', 'La Guarida Oculta', 'Habla con Rhea en la Guarida Oculta, en las Tierras Inhóspitas.', 'Ahora que la mayoría de los dragones Negros están fuera de las Tierras Inhóspitas, es seguro trasladar el huevo. Me encontrarás en una pequeña meseta, al norte de Nuevo Kargath.$B$BVen a verme.', '', '', '', '', '', '', 'Rheastrasza', '', '', '', 0),
(27898, 'esMX', 'El regalo de Rheastrasza', 'Espera mientras Rhea recupera el huevo de la Guarida Oculta.', 'Espera aquí. Voy a recuperar el huevo.', '', 'Espera a que Rhea recupere el huevo', '', '', '', '', '', '', '', 'Lee: Note de Rhea. Zona: Guarida Oculta, Tierras Inhóspitas.', 0),
(27899, 'esMX', 'Ese brillo en sus ojos', 'Habla con: Harrison Jones. Zona: Obelisco del Sol.', 'Si buscas a Harrison, se te acaba de escapar.$b$bNo paraba de hablar de su último descubrimiento; y de que ahora todo comenzaba a cobrar sentido.$b$bPero... te aseguro que para mí nada de lo que decía tiene sentido.$b$bTraté de convencerle de que se quedase aquí para disfrutar de un par de puestas de sol en el desierto conmigo, pero no hay manera de hablar con él cuando tiene ese brillo en los ojos.$b$bTal vez quieras comprobar qué trama.$b$bSe dirigió hacia el gran monolito, al sur de aquí.', '', '', '', '', '', '', '', '', '', '', 0),
(27900, 'esMX', 'Yo me encargo de este tipo', 'Mata a 10 soldados de aire Schnottz.', 'Muy $goportuno:oportuna;, $n.$b$bParece que no soy el único interesado en estos obeliscos; y estos tipos no parecen estar dispuestos a compartir información...$b$bCreo que puedo ocuparme de este tipo.$b$bTal vez tú podrías ocuparte de algunos de sus amigos antes de que lleguen hasta allí.', '', 'Soldados de aire Schnottz asesinados', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Obelisco del Sol.', 0),
(27901, 'esMX', 'No saben lo que tienen aquí', 'Crea el dispositivo de activación titánico.', 'Escucha, $n. No tengo demasiado tiempo para hablar.$b$b¡Estos tipos están extrayendo reliquias de este yacimiento y se están llevando piezas de tecnología antigua que nos hace falta!$b$bNecesito que busques en sus cajones piezas de un dispositivo de activación antiguo. Los oficiales deberían tener los códigos que necesitarás para abrirlos.$b$b¡Rápido!$b$b¡No podemos permitir que carguen todas estas cosas en sus aviones!', '', '', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Obelisco del Sol.', 0),
(27902, 'esMX', 'El Manantial', 'Reúne 6 motas de Manantial de los elementales de Manantial.', 'Magtoor me ha hablado del chamanismo que practican los Tábidos. El gran Nobundo dijo una vez que el camino de los elementos podría ser, de alguna forma, otro camino hacia la Luz.$b$bEspero que haya algo de verdad en ello. Los elementales que se reúnen cerca de la Cueva de Manantial, al sur, son una fuente de agua verdaderamente prístina. Pueden ser caóticos y violentos, pero el agua pura que se recoge de ellos será el conducto perfecto para la bendición de la Luz.$b$bTráeme ese agua, $n, por favor.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Anacoreta Avuun. Zona: El Puerto, Pantano de las Penas.', 0),
(27903, 'esMX', 'La llave de contacto', 'Recupera la lente del Sol.', '¡No hay manera de acabar con este tipo!$b$bTú lo estás haciendo muy bien, $gchico:chica;. Solo queda una cosa por hacer.$b$bSegún mis investigaciones, debajo debería haber una estatua titánica. Usa el dispositivo para activarla, después rómpela.$b$bSi mi teoría es correcta, la clave para reactivar este obelisco se encuentra en esa estatua.', '', '', '', '', '', '', '', '', '', 'Coloca la lente del Sol en el estrado de la Cámara del Sol.', 0),
(27904, 'esMX', 'Un soplo de bruma', 'Reúne 5 cristales humeantes de los grells brumosos.', 'Los grells son espíritus del bosque que deambulan por el Valle Brumoso, al este. Aunque se parecen a los diablillos, no he encontrado ningún rastro demoníaco en los que he estudiado. Por lo que puedo ver, permanecen incorruptos.$b$bAquellos que viven en el valle se mueven al son del viento e invocan soplos de brisa a su antojo. Ese aire puro podría añadirse a mi remedio para el pobre Magtoor.$b$b$n, reúne los cristales humeantes que se encuentran en los cuerpos de los grells. Debo agotar hasta la última posible cura.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Anacoreta Avuun. Zona: El Puerto, Pantano de las Penas.', 0),
(27905, 'esMX', '¡Armacola!', 'Usa el armacola para defender al bombardero de Schnottz.', 'Vale, ya he suavizado a este tipo, ¿qué tal si me ayudas a acabar con él?$b$bTengo un plan de evasión, pero nos hará falta mucho valor y algo de suerte.$b$b¿Estás $gpreparado:preparada;, $n?$b$bTú sígueme...', '', 'Evasión del Obelisco del Sol', '', '', '', '', '', '', '', 'Defiende el bombardero de Schnottz hasta que Harrison pueda aterrizar.', 0),
(27906, 'esMX', 'Neeka Marca de Sangre', 'Habla con Neeka Marca de Sangre en el Cruce Lanzarrota.', 'Aún nos queda mucho por hacer para recuperarnos del asalto y prepararnos para el siguiente. Necesitaré que todos nuestros exploradores se coordinen.$b$bNeeka Marca de Sangre es nuestra mejor exploradora, se entrenó en las despiadadas Tierras Inhóspitas. La enviamos al oeste, al Cruce Lanzarrota, para vigilar las actividades de la Alianza.$b$bVe a ver a Neeka, $n. Cuéntale lo que ha pasado en Rocal. Ayúdala en todo lo que puedas.', '', '', '', '', '', '', '', '', '', '', 0),
(27907, 'esMX', 'Flor de plegaria', 'Recoge 10 ramos de flor de plegaria del Lodo Traicionero.', 'Estoy acabada, $c. He depositado mi fuerza en Helgrum y ahora sangra por sus heridas abiertas. Son heridas demasiado profundas, la carne se niega a curarse.$b$bMurmura atemorizado, lo consumen la fiebre y el dolor. No puedo dejarlo solo. Ahora no. Te ruego avergonzada que recojas unas hierbas para mí.$b$bLa flor de plegaria que crece en el pantano es un antiguo remedio de alivio. Con la cantidad suficiente podríamos detener el dolor.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Neeka Marca de Guerra. Zona: Cruce Lanzarrota, Pantano de las Penas.', 0),
(27908, 'esMX', 'Los secretos del lodo', 'Recoge 10 muestras de cieno vigorizado de pegotes de lodo traicionero.', 'Las heridas de Helgrum se infectan con el aire del pantano. Se hinchan y supuran, y llenan sus últimos momentos de sufrimiento. Debo cubrirlas con algo.$b$bLos espíritus atraviesan este lugar. Poseen el lodo mismo y lo mueven en bloques de tierra que adoptan vida propia.$b$bLos espíritus del lodo puro y fresco le ofrecerán cierto alivio. Reúnelo por mí, por favor, ya que no puedo dejarlo solo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Neeka Marca de Guerra. Zona: Cruce Lanzarrota, Pantano de las Penas.', 0),
(27909, 'esMX', 'El Manantial', 'Recoge 8 motas de Manantial de los elementales de Manantial.', 'La respiración de Helgrum se ralentiza. Se acerca su hora.$b$bNecesito agua. Los elementales vagan por los estanques de la Cueva de Manantial. El agua que fluye de ellos es la más pura de este pantano.$b$bAunque pudiera arriesgarme a abandonar a Helgrum, el hacha me temblaría en las manos. Debo rogarte que te apiades de mí una vez más, por la comodidad de Helgrum. Tráeme las motas de los elementales, para que su último trago sea puro y refrescante.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Neeka Marca de Guerra. Zona: Cruce Lanzarrota, Pantano de las Penas.', 0),
(27910, 'esMX', 'El último lamento', 'Obtén el pellejo de Fauceumbría.', 'Ya que me veo reducida a suplicar, pediré todo lo que pueda. Debo pedirte un último favor, una última tarea que te ruega una orca humillada.$b$bHelgrum tenía una gran presa: Fauceumbría, la comedora de ogros, la gran pantera de Valle Brumoso. Nunca se permitió el placer de darle caza. Aunque deseaba ardientemente entregarse a la cacería, nuestras misiones de exploración eran demasiado importantes.$b$bSi no puede darle caza a Fauceumbría en este mundo, entonces que le dé caza en el siguiente. Toma su relevo y tráeme el pellejo de Fauceumbría.', '', '', '', '', '', '', 'Fauceumbría', '', '', 'Vuelve con: Neeka Marca de Guerra. Zona: Cruce Lanzarrota, Pantano de las Penas.', 0),
(27911, 'esMX', 'Su último aliento', 'Presencia los últimos momentos de Helgrum.', 'Se mueve...$b$bNo te vayas, $n. Te lo ruego, honra a Helgrum conmigo. Has hecho tanto por él...', '', '', '', '', '', '', '', '', '', 'Habla con: Neeka Marca de Sangre.', 0),
(27912, 'esMX', 'El tesoro de los titanes', 'Inspecciona el tesoro de los Vigías.', 'Al caer al suelo el segundo defensor, aparece un cofre al fondo de la cámara. ¿Será esto lo que estaban protegiendo?', '', '', '', '', '', '', '', '', '', 'Inspecciona: Tesoro de los Vigías. Zona: Tumba de los Vigías, Tierras Inhóspitas.', 0),
(27913, 'esMX', 'El tesoro de los titanes', 'Inspecciona el tesoro de los Vigías.', 'Al caer al suelo el segundo defensor, aparece un cofre al fondo de la cámara. ¿Será esto lo que estaban protegiendo?', '', '', '', '', '', '', '', '', '', 'Inspecciona: Tesoro de los Vigías. Zona: Tumba de los Vigías, Tierras Inhóspitas.', 0),
(27914, 'esMX', 'La bendición del Vuelo Verde', 'Habla con Lord Itharius en lo alto del Templo de Atal\'Hakkar.', 'Has hecho bien, $n. Puede que Jammal\'an se nos haya escapado de entre las manos, pero su huida me permite entrar en el templo a mi antojo.$b$bQuédate donde estás y no te muevas. Para acelerar tu regreso, atraeré tu espíritu a través del Sueño Esmeralda.$b$bEsto puede producir una ligera somnolencia.', '', '', '', '', '', '', 'Lord Itharius', '', '', '', 0),
(27915, 'esMX', 'El corazón del templo', 'Habla con Lord Itharius de nuevo dentro del Templo de Atal\'Hakkar.', 'Admito que estoy personalmente involucrado en este asunto. Uno de los primeros dragones Verdes que corrompieron aquí fue mi hermano, Eranikus.$b$bPensaba que había perdido a Eranikus para siempre en las pesadillas más oscuras, pero he oído que su sombra ha aparecido dentro del templo. No sé si es realmente él, o si es un eco vacío y triste.$b$bSi deseas seguir ayudándome, vuelve a la Sala de las Máscaras y pasa por los arcos hasta llegar al verdadero sagrario del templo. Allí me reuniré contigo.', '', '', '', '', '', '', '', '', '', '', 0),
(27916, 'esMX', 'El informe de Ruag', 'Entrega el informe de Lanzarrota al comandante de envíos Ruag, en Rocal.', 'Aquí está el informe de Ruag, $n. Cuéntale que su explorador sigue aquí.$b$bNo menciones a Helgrum. No quiero distraer a nadie con la noticia de esta tragedia.$b$bDebo ser fuerte. Todos debemos ser fuertes.', '', '', '', '', '', '', '', '', '', 'Informa a: Comandante de envíos Ruag. Zona: Rocal, Pantano de las Penas.', 0),
(27917, 'esMX', 'Olisqueando', 'Mata al barón Ashbury.', 'Hace kilómetros que puedo oler a Godfrey y a sus compañeros. Han hecho un trabajo pésimo al cubrir el rastro de su huida. Será el último error que cometan.$b$bUno de ellos está cerca, y a pesar de que su olor ha cambiado ligeramente al convertirse en no-muerto estoy bastante seguro de que se trata de Ashbury. Entra y córtalo en rodajas; los Renegados no interferirán con nuestra misión.', '', '', '', '', '', '', 'Barón Ashbury', '', '', 'Vuelve con: Maestro de manada Ivar Colmillo de Sangre.', 0),
(27918, 'esMX', 'El Puerto', 'Entrega los cristales draenetistas al anacoreta Avuun.', 'El anacoreta Avuun es uno de nuestros hermanos incorruptos, lo que las demás razas conocen como un draenei. Vino a El Puerto para sanarnos y para intentar encontrar una cura. Él me envió a recoger estos cristales.$b$bAhora mismo vela por un amigo muy enfermo... A pesar de que ha enviado mensajes al mismo Exodar, aún no ha recibido ayuda. ¿Podrías llevarle estos cristales, $n? Puede que seas $gel único:la única; que puede ayudarle.', '', '', '', '', '', '', '', '', '', '', 0),
(27919, 'esMX', 'A las Tierras Devastadas', 'Viaja a las Tierras Devastadas y habla con Enohar Cebatruenos en el Castillo de Nethergarde.', 'Apreciamos tu ayuda en el pantano, $n. Me gustaría informarte de que he recibido una carta del Castillo de Nethergarde.$b$bEnohar Cebatruenos solicita ayuda para investigar los naufragios de Las Costas Rojas, pero nadie se ha ofrecido a realizar semejante viaje y yo no puedo abandonar El Puerto.$b$bEl Castillo de Nethergarde se encuentra en las Tierras Devastadas, al sur del Pantano de las Penas. No te acerques demasiado a Rocal en tu viaje.', '', '', '', '', '', '', '', '', '', '', 0),
(27920, 'esMX', 'Blindado hasta los dientes', 'Mata al barón Filargenta y al comandante Vallefont.', 'Hemos topado con un obstáculo inesperado en nuestro asalto al castillo, $n. Parece que los sirvientes que atendían al barón Filargenta y al comandante Vallefont en vida también les sirven en la muerte, y Godfrey los ha colocado justo entre nosotros y él.$b$bNo te preocupes, no permitiremos que sean nada más que un pequeño incordio. Elimina a Filargenta y a Vallefont y no solo sus guardias se quedarán sin maestros que los dirijan, sino que también nos acercará a nuestro objetivo final.', '', '', '', '', '', '', 'Comandante Vallefont', '', '', 'Vuelve con: Maestro de manada Ivar Colmillo de Sangre.', 0),
(27921, 'esMX', 'Con uñas y dientes', 'Mata a Lord Walden.', 'Parece que Lord Walden por fin se ha percatado de nuestra presencia y ha reforzado sus defensas. Es inútil... Nada puede detener a nuestra manada.$b$bEl camino que conduce hasta él está lleno de poderosos esbirros de la Plaga, pero confío en que seas capaz de despejar el camino para los que te sigamos. Cuando matemos a Walden, podremos proseguir directamente hasta el cobarde de su líder.', '', '', '', '', '', '', 'Lord Walden', '', '', 'Vuelve con: Maestro de manada Ivar Colmillo de Sangre.', 0),
(27922, 'esMX', '¡Traidores!', 'Escóndete tras la fronda Neferset y descubre el secreto Neferset.', 'Por favor, desconocido. Tienes que ayudarme.$B$BHe venido aquí para investigar la llegada de un poderoso aliado de los Neferset; y lo único que he conseguido es que mis mayores aliados me traicionen y me entreguen al enemigo.$B$BVe al bancal que se encuentra sobre nosotros, al este, y encuentra la información que yo no he podido descubrir. Tendrás que esconderte de los Neferset. Tal vez puedas ocultarte tras una de las grandes plantas que hay sobre la plataforma.$B$BHaz esto por mí y ayudaré a tus amigos a encontrar el camino hacia un lugar seguro.', '', 'Secreto Neferset descubierto', '', '', '', '', '', '', '', 'Vuelve con: Príncipe Nadun. Zona: Ciudad Perdida de los Tol\'vir, Uldum.', 0),
(27923, 'esMX', 'Humo en los ojos', 'Quema montones de heno en el interior de la Ciudad Perdida de los Tol\'vir, en Uldum.', 'No sé qué tipo de plan absurdo está maquinando tu amigo, pero vamos a necesitar una distracción si pretendemos tener alguna posibilidad de escapar.$B$BCoge la antorcha de ese blandón y provoca algunos incendios.$B$BTal vez si conseguimos distraer la atención de esa escoria de Neferset durante unos minutos, tendremos la oportunidad que necesitamos.', '', 'Fardo de heno quemado', '', '', '', '', '', '', '', 'Vuelve con: Príncipe Nadun. Zona: Ciudad Perdida de los Tol\'vir, Uldum.', 0),
(27924, 'esMX', 'El plan de Budd', 'Consigue 6 piezas de armadura Neferset.', '¡Tengo una idea! Confía en mí, ¡esta vez es buena!$B$BConsigue algunas de esas piezas de armadura brillante que usan los hombres-gato.$B$BEste plan no puede fallar. Confía en mí.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Budd. Zona: Ciudad Perdida de los Tol\'vir, Uldum.', 0),
(27926, 'esMX', 'Hospitalidad oriental', 'Belloc Hoja Brillante quiere que te mezcles con los invitados en el Embarcadero de Schnottz.', 'Me temo que el Comandante está bastante ocupado.$b$bUna operación como esta requiere de toda su atención estos días.$b$bMientras esperas para hablar con él, ¿por qué no te mezclas con algunos de nuestros invitados?$b$bHemos invitado a varios de los personajes más ilustres de Azeroth para que presencien el momento en que desvelemos los secretos de esta región.$b$bNo me cabe duda de que los encontrarás de lo más cautivadores.', '', 'Te has relacionado con el embajador Laurent', 'Te has relacionado con un caballero refinado', 'Te has relacionado con un artista en ciernes', 'Te has relacionado con una joven aspirante a estrella', '', '', '', '', 'Habla con: Belloc Hoja Brillante. Zona: Embarcadero de Schnottz.', 0),
(27927, 'esMX', 'A la cicatriz', 'Encuentra a Theldurin el Perdido en la Cicatriz del Rompemundos, en las Tierras Inhóspitas.', 'Las Tierras Inhóspitas son el hogar de algunas gentes peculiares, muchas de las cuales llevan aquí bastante tiempo.$B$BPor ejemplo, había aquí tres caballeros... no recuerdo sus nombres... creo que el enano se llamaba Theldurin. En fin, fueron al sur, hace unos días, con un cargamento de cerveza y no se ha sabido nada más de ellos. Creo que se dirigían a la gran cicatriz.$B$B¿Te importaría ir a ver cómo están? Quisiera asegurarme de que están bien.', '', '', '', '', '', '', '', '', '', '', 0),
(27928, 'esMX', 'Un favor para el camarada peletero', 'Reúne 5 pelambres de coyote de desierto.', 'El Comandante puede ser muy generoso con quien le demuestra lealtad; y yo sé lo que puedes hacer para ganarte su favor.$b$bAntes de aumentar su... eeh... mano de obra, se dedicaba al comercio de pieles de animales.$b$bSe le da bastante bien la peletería. El camarada peletero es capaz de hacer maravillas incluso con las pieles más deterioradas.$b$bSe dice que en el oasis seco del este habita una camada especial de coyotes.$b$bLas pieles de estos coyotes serán un regalo que apreciará mucho.', '', '', '', '', '', '', '', '', '', 'Habla con: Belloc Hoja Brillante. Zona: Embarcadero de Schnottz.', 0),
(27929, 'esMX', 'Hazlos caer', 'Usa el enganchacarnes con púas para desmontar y matar a 4 jinetes de grifos de Bramal.', 'Un simple draco Faucedraco vale por una docena de jinetes de grifos Martillo Salvaje. Si los tiras de sus piojosos pájaros no son nada.$B$BHasta tú los podrías matar fácilmente, $c de la Horda.$B$BCaza a los jinetes de grifos que hay volando sobre el río al norte de Garganta de Sangre. Coge este gancho y lánzaselo cuando pasen volando cerca de ti. Su ímpetu hará que salgan disparados de su silla y caigan a tus pies. ¡Remátalos! Mata a unos cuantos jinetes de grifos de Bramal y creeré que tu Horda es tan poderosa como dices.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Narkrall Rasgarra. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(27930, 'esMX', 'Devastación', 'Busca a Rheastrasza.', 'Vía libre. Si Rheastrasza o el huevo pudieron escapar milagrosamente a las llamas de Alamuerte, seguramente necesitarán tu ayuda cuanto antes.', '', '', '', '', '', '', '', '', '', 'Busca cualquier rastro de: Rheastrasza. Zona: Guarida Oculta, Tierras Inhóspitas.', 0),
(27931, 'esMX', 'Los Campos Convulsos', 'Habla con Pizarra Arenamovediza en Los Campos Convulsos en Infralar.', 'Antes de que nos puedas echar una mano aquí, tendrás que encargarte de las fuerzas de Therazane, la Madre Pétrea, en el sur. Los elementales y los gigantes que hay en Los Campos Convulsos se están reuniendo. $B$BEllos también van tras el fragmento central del Pilar del Mundo. Nos atacarán en mitad de nuestra guerra con los troggs de piedra y no podremos repelerlos.$B$BYa he enviado al archigeomántico. Ve a ver a Pizarra Arenamovediza y haz lo que te pida.', '', '', '', '', '', '', '', '', '', '', 0),
(27932, 'esMX', 'El hacha de hendimiento terrestre', 'Asesina a 5 colosos esmeralda hendidos.', 'Los colosos esmeralda son las criaturas más grandes de la Madre Pétrea. Tienen que ser los primeros en desaparecer del campo.$B$BTraje el hacha del Padre Pétreo Mantomena para este propósito. Úsala para hendir los gigantes.$B$BAsí los podrás reducir a un tamaño más manejable para poder finiquitarlos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Pizarra Arenamovediza. Zona: Los Campos Convulsos, Infralar.', 0),
(27933, 'esMX', 'Mena elemental', 'Recoge 6 menas elementales.', 'Vas a tener que enfrentarte con el líder de las fuerzas de Therazane. Sin embargo, para llegar hasta a él de forma rápida y segura, tendré que realizar un ritual.$B$BSal al campo y recoge minerales elementales de los furibundos. Si tengo suficientes, podré hacer que te fundas con el suelo para llevarte adonde tienes que ir.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Pizarra Arenamovediza. Zona: Los Campos Convulsos, Infralar.', 0),
(27934, 'esMX', 'Uno con el suelo', 'Completa el ritual Uno con el suelo.', 'El jefe de las fuerzas de la Madre Pétrea aquí es el gran señor elemental de la tierra, Avalanchion. Por suerte para nosotros, los cultores del Martillo Crepuscular han decidido invadir su guarida. Buscan someter a sus elementales a su voluntad.$B$BVamos a aprovechar el caos. El ritual que realizo te fundirá con la tierra. Te llevará cerca de Avalanchion sin que note tu presencia. $B$BDepende de ti acabar con él.', '', 'Ritual Uno con el suelo completado', '', '', '', '', '', 'Avalanchion está justo ahí delante. Ya sabes lo que tienes que hacer.', 'Pizarra Arenamovediza', '', 0),
(27935, 'esMX', 'Acaba con la avalancha', 'Asesina a Avalanchion.', 'Avalanchion se encuentra frente a ti. Mátalo para evitar que las fuerzas de Therazane ataquen el Hogar Pétreo.', '', '', '', '', '', '', 'Avalanchion', '', '', 'Preséntate ante Crag Aplastarrocas en el Hogar Pétreo en Infralar.', 0),
(27936, 'esMX', 'Acaba con la avalancha', 'Asesina a Avalanchion.', '¡Tienes que volver y matar a Avalanchion para evitar que las fuerzas de Therazane ataquen el Hogar Pétreo!', '', '', '', '', '', '', 'Avalanchion', '', '', 'Preséntate ante Crag Aplastarrocas en el Hogar Pétreo en Infralar.', 0),
(27937, 'esMX', 'El regreso del héroe', 'Preséntate ante el Padre Pétreo Mantomena en el Hogar Pétreo en Infralar.', 'El Padre Pétreo espera que regreses al sur, al Hogar Pétreo. $B$BPonte presentable. ¡Te has ganado una bienvenida de héroe!', '', '', '', '', '', '', '', '', '', '', 0),
(27938, 'esMX', 'El fragmento central', 'Recupera el fragmento central del Pilar del Mundo.', 'Te entrego la llave del Hogar Pétreo. Con ella puedes abrir la cámara que lleva a mi hogar y recuperar el fragmento central del Pilar del Mundo.$B$BMantén el fragmento a salvo, $n. ¡Llévalo al Templo de la Tierra en el centro de Infralar lo más rápido posible!$B$BSiempre serás $gbienvenido:bienvenida; aquí.', '', '', '', '', '', '', '', '', '', 'Entrega el fragmento central del Pilar del Mundo a la clamatierras Yevaa en el Templo de la Tierra en Infralar.', 0),
(27939, 'esMX', 'El zorro del desierto', 'Schnottz quiere que le lleves el zorro del desierto.', 'Hay mucho que hacerr en esta región, $r.$b$bA ambos nos apasionan las antiguas tecnologías que se encuentrran aquí, ¿ferrdad?$b$bTal vez podrríamos trrabajarr juntos.$b$bDejemos atrrás los malos entendidos del pasado, ¿de acuerrdo?$b$bHay una crriaturra al este de esta zona que prretendo cazarr sin éxito hace tiempo. Trráemela como muestrra de tu sincerridad, ¿mmm?$b$bEntonces tal vez te perrmita accederr a mi operración...', '', '', '', '', '', '', '', '', '', 'Habla con: Schnottz. Zona: Embarcadero de Schnottz.', 0),
(27940, 'esMX', 'Sucios pájaros', 'Tienes que asesinar a 8 buitres malsanos.', 'El cielo que corona el Oasis Árido está plagado de estos terribles buitres.$b$bSon como roedores infecciosos con alas, estas criaturas no sirven para gran cosa y causan un enorme daño.$b$bLibera a los cielos de esta molestia y deja la región mejor de lo que la encontraste.', '', 'Buitres malsanos asesinados', '', '', '', '', 'Buitre malsano', '', '', '', 0),
(27941, 'esMX', 'Moda uniforme', 'Belloc Hoja Brillante quiere que reúnas 10 uniformes de soldado.', 'Tenemos una política muy estricta en nuestras filas, una que nos tomamos muy en serio.$b$bNuestras tropas deben llevar el uniforme oficial en todo momento. Esto mejora la organización, evita el fuego amigo y ¡consigue que las tropas tengan un aspecto envidiable!$b$bLo llamamos: Moda uniforme.$b$bÚltimamente andamos escasos de uniformes. Te voy a pedir que recuperes los de los soldados que han caído en combate.$b$bEncontrarás a un montón de estos pobres muchachos al este de aquí, en las Ruinas de Ammon.', '', '', '', '', '', '', '', '', '', 'Habla con: Belloc Hoja Brillante. Zona: Embarcadero de Schnottz.', 0),
(27942, 'esMX', 'Idolatría', 'El comandante Schnottz quiere que reúnas 8 ídolos bien conservados.', 'Necesito que te ocupes de algo, $r.$b$bMi asesorr de mayorr confianza está bajo el efecto de una antigua maldición. Un hechizo que lo ha transforrmado en pavo, ¡nada más y nada menos!$b$bLlevo días estudiando el asunto en busca de un remedio; y porr fin estoy prreparrado parra realizarr el ritual.$b$bNecesitarré varrios ídolos de las ruinas cerrcanas. ¡Trráemelos ahorra mismo!$b$b¡Puedes retirrarrte!', '', '', '', '', '', '', '', '', '', 'Habla con: Comandante Schnottz. Zona: Embarcadero de Schnottz.', 0),
(27943, 'esMX', 'Espíritus iracundos', 'El comandante Schnottz quiere que uses el L.P.A.C. para reunir 5 esencias espectrales furiosas.', 'El doctorr Venkman erra uno de mis mejorres infestigadorres, hasta que tuvimos que acabarr con su miserria.$b$bPerro me dejó uno de sus mayorres logrros. Contra un adversario sobrrrenatural adecuadamente arrmonizado, esta arma consumirá la esencia de su objetivo.$b$bTiene una imporrtancia vital parra el ritual que foy a realizarr.$b$bTe prreguntarrás cuál es tu papel en todo esto. Es sencillo. Tendrrás el honor de reunirr los materriales.$b$bEl arrma está calibrrada parra funcionarr en los espectrros furriosos del templo del este.', '', '', '', '', '', '', '', '', '', 'Habla con: Comandante Schnottz. Zona: Embarcadero de Schnottz.', 0),
(27944, 'esMX', 'Reducir sus efectivos', 'Mata a 12 rondadores Leñoscuro en Leñoscuro. El bosque Leñoscuro se encuentra al oeste de aquí, al otro lado del puente de la isla central.', 'Llevamos semanas tratando de hacernos con Leñoscuro, pero ese bosque está plagado de arañas. Hazme un favor, intenta reducir su número lo suficiente como para que podamos intentar un ataque.$b$bTen cuidado ahí fuera, he recibido informes sobre la presencia de tropas de la Horda en la zona a principios de semana.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el coordinador de avanzada Brack en el Campamento de Baradin cuando termines.', 0),
(27945, 'esMX', 'Píntalo de negro', 'Consigue un corazón de diamante negro.', 'La tierra sangra, $c. La desgarran como si cortaran carne.$B$BEsos cultores disfrutan con sus secretos pero los mismos elementales que usan para sus fechorías pueden traicionarlos. Busca esclavos de piedra obsidiana al noroeste de aquí, entre la tierra arruinada que llamamos la Brecha Negra.$B$BDespedaza sus cuerpos y encuéntrame un corazón perfecto de diamante negro. Estudiaré ese corazón. Y desnudaré su alma.', '', '', '', '', '', '', '', '', '', 'Llévale el corazón a: Mallia. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(27947, 'esMX', 'Una visión crepuscular', 'Encuentra un Ojo del Crepúsculo en la Brecha Negra.', 'Cho\'gall les sigue el rastro a sus esbirros a través de poderosos orbes mágicos: "los Ojos del Crepúsculo".$b$bEn el Monte Hyjal, los guardianes de Hyjal lograron encontrar y manipular uno de ellos. Debemos hacer lo mismo. Quiero uno de esos orbes, y quiero usarlo para mirar en el interior del mismísimo corazón de la guarida de Cho\'gall.$B$BRegistra la Brecha Negra, al otro lado del río, al noreste y encuentra un Ojo del Crepúsculo. ¡Haz lo que sea necesario para traérmelo!', '', '', '', '', '', '', '', '', '', 'Encuentra: Ojo del Crepúsculo. Zona: Brecha Negra.', 0),
(27948, 'esMX', 'Una tarea pegajosa', 'Reúne 4 glándulas de seda pegajosas de las madres de linaje Leñoscuro en Leñoscuro. El bosque Leñoscuro está al oeste, al otro lado del puente en la isla central.', 'Decir que encontrar suministros en esta isla es difícil es decir poco.$b$bAfortunadamente, hemos encontrado una buena cantidad de seda en Leñoscuro, al oeste de aquí. La mala noticia es que la seda viene de las glándulas de las arañas madre de linaje. Quiero que reúnas 4 de ellas.$b$bDebería bastar para terminar esta tanda de camisas.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el coordinador de avanzada Brack en el Campamento de Baradin cuando termines.', 0),
(27949, 'esMX', 'Los olvidados', 'Libera los espíritus de 6 almas torturadas en la Colina del Olvido. Puedes canalizar las almas tocando las lápidas directamente con la mano. La Colina del Olvido está al oeste de aquí, más allá de Leñoscuro y del Frente Inquieto.', 'En esta isla han muerto muchos soldados, $n. Lo justo es que les presentemos nuestros respetos de la forma que podamos.$b$bNecesito que viajes hasta la Colina del Olvido, al oeste de aquí, y que liberes las almas torturadas de nuestros compañeros de batalla en ese lugar. Pero ten cuidado por ahí, tenemos informes sobre la presencia de no-muertos en la zona.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el teniente Farnsworth en el Campamento de Baradin cuando termines.', 0),
(27950, 'esMX', '¡Gluber!', 'Schnottz quiere que hables con él cuando estés $glisto:lista; para presenciar el ritual.', '¡Porr fin! ¡Ha llegado el momento de liberrarr a Gluber de esa terrible maldición!$b$bAhorra prresta atención, $r, y perrmanece alerrta. No puede haberr ninguna interrupción mientrras realice el ritual.$b$b¡Afísame cuando hayas asegurrado el perrímetrro!$b$b¡Vamos, muéfete!', '', 'Ritual de transformación de Gluber presenciado', '', '', '', '', '', '', '', '', 0),
(27951, 'esMX', 'Todos tenemos que sacrificarnos', 'Mata a 10 chamanes de lo Oscuro.', '<El ojo te habla, su \'voz\' resuena como si viniera de todas partes al mismo tiempo.>$b$b¿Buscas mi visión, $r? Mis poderes tienen un precio. Esos discípulos Crepusculares me han estado honrando con la sangre de los enanos Martillo Salvaje de las ruinas que hay cerca de aquí, pero aún estoy sediento. Tal vez puedas hacerlo mejor.$B$BMata a mis antiguos amos y mi visión será tuya. Hónrame con la muerte de los chamanes de lo Oscuro. La sangre es sangre, después todo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ojo del Crepúsculo. Zona: La Brecha Negra, Tierras Altas Crepusculares.', 0),
(27952, 'esMX', 'Los exploradores', 'Habla con la exploradora Mowi en el Templo de la Tierra en Infralar.', 'Tenemos un contingente de la Liga de Expedicionarios en la cámara que hay al noroeste dentro del templo. $B$BAndan farfullando algo de que el Martillo Crepuscular trama algo.$B$B$n, ¿me haces el favor de ir a ver qué necesitan?', '', '', '', '', '', '', '', '', '', '', 0),
(27953, 'esMX', 'El Relicario', 'Habla con el examinador Rowe en el Templo de la Tierra en Infralar.', 'Tenemos un contingente del Relicario en la cámara que hay al noreste dentro del templo. $B$BAndan farfullando algo de que el Martillo Crepuscular trama algo.$B$B$n, ¿me haces el favor de ir a ver qué necesitan?', '', '', '', '', '', '', '', '', '', '', 0),
(27954, 'esMX', 'El truco está en los ojos', 'Llévale el Ojo del Crepúsculo a Garona Semiorco en Garganta de Sangre, en las Tierras Altas Crepusculares.', 'Muy bien, $r. Has comprado mis servicios con sangre. Llévame de vuelta con Garona Semiorco.$B$BOh sí, ya sé a dónde me llevas. El inexorable deseo de venganza de Garona no es ningún secreto. Será un placer ver el resultado.', '', '', '', '', '', '', '', '', '', 'Lleva el Ojo del Crepúsculo a: Garona Semiorco. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(27955, 'esMX', 'Ojo espía', 'Mira por el Ojo del Crepúsculo para Garona.', 'Esa cosa me pone los pelos de punta. Cho\'gall los usa para controlar a sus esbirros; ha llegado el momento de usarlo contra él.$B$BDéjame ver... mmm, está todo nublado. Solo te puedo ver a ti. ¿Por qué te está mostrando a ti?$B$B<Garona coloca el ojo frente a ella.>$B$BMira por el ojo y dime lo que ves. ¡Espía la guarida de Cho\'gall! ¿Qué está haciendo? ¿Está bien vigilada? ¡Dime!', '', 'Has mirado por el ojo', '', '', '', '', '', '', '', 'Habla con: Garona Semiorco. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(27956, 'esMX', 'La tarea de Ñoño', 'Consigue 15 volantes templados de gólems de guerra templados.', 'Ñoño venir de Tierras Inhóspitas. Otros ogros querer que Ñoño luchar.$B$BÑoño odiar luchar. Ñoño querer aprender.$B$BÑoño ver máquinas al sur. Maquinas hechas con engranajes.$B$BQuizás, si tú pedir amablemente, ¿máquinas dar a ti algunos engranajes? Tal vez así Ñoño poder tener engranaje, y aprender cosas de máquinas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ñoño. Zona: Avance del Torio, Garganta de Fuego.', 0),
(27957, 'esMX', 'Ñoño no matar', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(27958, 'esMX', 'Un buen antídoto', 'Consigue 14 muestras de veneno de Cristalderma.', 'Lástima que Ñoño se haya ido. Empezaba a gustarme su compañía.$B$BBueno, ¡volvamos al trabajo!$B$BSoy lo más parecido a un oficial médico que tiene esta expedición, y me estoy quedando sin antídotos. Solemos necesitar muchos antídotos.$B$BLa clave para un buen antídoto es empezar SIEMPRE con el veneno en sí. Las arañas Cristalderma que hay por aquí cerca deberían ser un buen punto de partida. Si las matas, probablemente podrás extraer algo de veneno de las bolsas de sus fauces.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Prisanne Rapapolvo. Zona: Avance del Torio, Garganta de Fuego.', 0),
(27959, 'esMX', 'La aventura de Ñoño: el jinete de arañas', 'Debilita a 7 arañas Cristaderma para que Ñoño pueda montar en ellas.', 'Ñoño ver que a ti gustar matar cosas. Tú dejar que Ñoño enseñar otra forma.$B$BÑoño siempre haber querido montar a lomos de araña. Parecer divertido. Pero arañas moverse muy rápido. Siempre escapar.$B$BNosotros trabajar juntos. Tú luchar contra araña hasta que araña estar débil y cansada. Luego Ñoño subir a lomos de araña y cabalgar.$B$B¡Quizás Ñoño incluso conseguir veneno para ti! ¡Tú no tener que matar!', '', 'Arañas montadas', '', '', '', '', '', '', '', '', 0),
(27960, 'esMX', 'Cuantos menos, mejor', 'Mata a 10 geólogos Hierro Negro o veladores Hierro Negro.', 'No soy un luchador... soy más bien un enano minero. Lo mismo ocurre con Jack y Pris. Y con Ñoño... bueno, cualquiera diría que es un gran luchador, pero es el más débil de todos nosotros.$B$BLo que quiero decir es que me alegras que llegaras cuando lo hiciste.$B$BPor lo visto, hay muchas posibilidades de que los de la Hermandad del Torio pronto luchen con los enanos Hierro Negro. He pensado que deberíamos deshacernos de los mejores que ellos tengan antes de que la guerra empiece de verdad. Empieza con los geólogos y los veladores del sur.', '', 'Geólogo o velador Hierro Negro asesinado', '', '', '', '', '', '', '', 'Vuelve con: Burrian Partecarbón. Zona: Avance del Torio, Garganta de Fuego.', 0),
(27961, 'esMX', 'Fuera de lugar', 'Consigue 8 pollos de ceniza.', 'La garganta es un lugar despiadado.No hay demasiado vida salvaje deambulando alegremente por aquí.$B$BIntentamos traer animales salvajes que poder cazar, pero no les ha ido nada bien. Simplemente no tienen dónde encontrar comida. Pero las arañas que hay cerca - que ya eran bastante peligrosas - se están volviendo más grandes y gordas gracias a la carne de pollo.$B$BNunca nos desharemos de todas las arañas, pero podemos rescatar a los pocos pollos que nos quedan. No solo estarás alimentando a la Hermandad, sino que los estarás salvando de una muerte dolorosa por mordedura de araña.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Burrian Partecarbón. Zona: Avance del Torio, Garganta de Fuego.', 0),
(27962, 'esMX', 'Una torpe reliquia', 'Consigue el cuerno gigante de Margol.', 'Margol la Furibunda es una vieja truenagarta que anda por aquí. La leyenda dice que lleva en La Garganta desde antes de que fuera una garganta. La leyenda también dice que se comió a mi hermano Barnabas.$B$BNo me importa lo vieja que sea o qué clase de magia pueda echar por la nariz. Solo quiero verla muerta. Por Barnabas.$B$BLa verás deambulando por los acantilados que hay al sur.', '', '', '', '', '', '', 'Margol la Furibunda', '', '', 'Vuelve con: Burrian Partecarbón. Zona: Avance del Torio, Garganta de Fuego.', 0),
(27963, 'esMX', 'Un nuevo amo... ¿pero quién?', 'Consigue el memorando Hierro Negro de Gravius Limugre en la Excavación de Limugre.', 'Has llegado justo a tiempo.$B$BEsto es lo que hay: los enanos Hierro Negro de la garganta se han estado comportando de forma extraña y la Hermandad del Torio pretende descubrir por qué. Al sobrestante Puñaceite no le gustan las sorpresas.$B$BSospechamos que están a la órdenes de un nuevo líder. Tengo razones para pensar que Gravius Limugre, que está al sur de aquí, sabe quién es.$B$BIncluso aquí, en La Garganta de Fuego, hemos oído hablar de tus hazañas, $n. Limugre no debería ser un problema para ti.', '', '', '', '', '', '', 'Gravius Limugre', '', '', 'Vuelve con: Jack Patarroca. Zona: Avance del Torio, Garganta de Fuego.', 0),
(27964, 'esMX', 'Jefe de excavación Mostachobulla', 'Mata a excavadores y lacayos Hierro Negro en la Caldera hasta que el Jefe de excavación Mostachobulla aparezca. Luego mata al Jefe de excavación Mostachobulla y consigue su ascua oscura.', 'Limugre no estaba tan arriba en la cadena de mando como pensábamos. Tendremos que coger a su superior y ver qué sabe.$B$BSe llama Jefe de excavación Mostachobulla, y está al mando de las operaciones de excavación de los Hierro Negro dentro de la Caldera, justo al noroeste de aquí. Sus excavadores y trabajadores patrullan el lado este de la Caldera, excavando hacia abajo día y noche.$B$BNo suele dejarse ver en el campo muy a menudo, pero si matas a bastantes de sus hombres, se verá obligado a salir y vérselas contigo.', '', '', '', '', '', '', 'Mostachobulla', '', '', 'Vuelve con: Jack Patarroca. Zona: Avance del Torio, Garganta de Fuego.', 0),
(27965, 'esMX', 'Puesto del Torio: la sede de la Hermandad', 'Preséntate ante el sobrestante Puñaceite en el Puesto del Torio en la Garganta de Fuego.', '¿Has... has visto eso? ¡Es la pieza que estábamos buscando, la que faltaba! Tenemos que llevarle esta información a alguien del Puesto del Torio.$B$BSabíamos que los Hierro Negro habían tenido tratos con el Señor del Fuego en el pasado, pero su gente nunca se había adentrado tanto en La Garganta de Fuego.$B$BEl Puesto del Torio está al oeste y al norte de aquí. Lo encontrarás enclavado en los acantilados que hay sobre los Llanos de Pirox. Llévale esta información directamente al sobrestante Puñaceite.', '', '', '', '', '', '', '', '', '', '', 0),
(27966, 'esMX', 'Recuperando los restos', 'Tienes que recoger 9 fémures malditos de los necrófagos que habitan la Colina del Olvido. La Colina del Olvido está en la zona oeste de la isla, pasado el Frente del Olvido.', 'La Colina del Olvido está invadida de zombis y de necrófagos desde que nos hicimos con esta isla destartalada. Hemos tratado de librarnos de ellos muchas veces, pero siempre terminan volviendo.$b$bUno de nuestros tenientes nos ha recomendado que nos llevemos los huesos de los necrófagos después de matarlos, para evitar que resuciten al día siguiente. ¿Crees que podrías ayudarnos con eso?', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el teniente Farnsworth en el Campamento de Baradin cuando termines.', 0),
(27967, 'esMX', 'Teniente primero Connor', 'Encuentra y mata al teniente primero Connor en la Colina del Olvido. Encontrarás la Colina del Olvido en el extremo occidental de la isla.', 'La primera vez que oí hablar del teniente Connor, no era más que un joven recluta en las Mazmorras de Ventormenta. Ninguno de nosotros hubiera imaginado que acabaría aquí en Tol Barad. Por desgracia, todavía merodea por estas destartaladas islas, destrozando la moral de nuestras tropas.$b$bNecesito que acabes con su sufrimiento... y con el nuestro.', '', '', '', '', '', '', 'Connor', '', '', 'Preséntate de nuevo ante el teniente Farnsworth en el Campamento de Baradin cuando termines con Connor.', 0),
(27968, 'esMX', 'La furia de la manada', 'Mata a Lord Godfrey.', '¡Ah, la dulce fragancia de la victoria! Mis hombres deberían estar descuartizando a Godfrey en este mismo instante. Ve a su dominio y recoge tu parte del botín, ¡te lo has ganado!$b$bPensaba que sería más difícil de derrotar...', '', '', '', '', '', '', 'Lord Godfrey', '', '', 'Vuelve con: Maestro de manada Ivar Colmillo de Sangre.', 0),
(27969, 'esMX', 'Haz algo útil', 'El comandante Schnottz quiere que convenzas a 6 obreros gandules para que vuelvan al trabajo.', 'Echarremos de menos a Gluber perro la misión no defe reserntirrse porr esto.$b$bTal fez puedas hacerr algo parra redimirrte.$b$bCoge uno de los uniforrmes que has recuperrado. Si lo llevas puesto, mis trrabajadorres no se mostrrarrán tan... agrresifos.$b$bÚltimamente les falta un poco de morral. Algunos de los trrabajadorres se niegan a realizarr sus funciones.$b$b¡Menuda audacia!$b$bEncuentrra a esos estúpidos vagos y conféncelos parra que fuelfan al trrabajo. ¡Si no...!', '', 'Gandules motivados', '', '', '', '', '', '', '', 'Habla con: Comandante Schnottz. Zona: Embarcadero de Schnottz.', 0),
(27970, 'esMX', 'Capitán P. Harris', 'Te han encargado que mates al Capitán P. Harris en el Cabo de la Esperanza Perdida. El Cabo de la Esperanza Perdida se encuentra al noroeste de aquí, a lo largo de la costa. Busca los restos de naufragio.', 'El Cabo de la Esperanza Perdida es un punto delicado para nuestra facción desde hace semanas aquí en Tol Barad. La mitad de nuestros barcos de suministros acaban contra las rocas.$b$bY para empeorar las cosas, está plagado de marineros no-muertos. Hemos intentado reducir sus efectivos, pero parecen volver incesantemente. Nuestro último recurso es acabar con el capitán ante el que responden. Lo encontrarás en un barco, cerca de la costa.$b$bOh, y espero que no le tengas mucho miedo a los tiburones.', '', '', '', '', '', '', 'Capitán P. Harris', '', '', 'Preséntate de nuevo ante el coordinador de avanzada Brack en el Campamento de Baradin cuando termines.', 0),
(27971, 'esMX', 'Golpear las jaulas', 'El coordinador de avanzada Brack te ha pedido que mates a 8 marineros naufragados en el Cabo de la Esperanza Perdida. El cabo se encuentra al noroeste de aquí, en la playa.', 'Llevamos teniendo problemas con los no-muertos del Cabo de la Esperanza Perdida durante cierto tiempo. Cada vez que naufraga un barco, consiguen engrosar sus filas de no-muertos.$b$b¿Podrías hacernos un favor y reducir sus unidades ahí fuera? Sé que no podrás matarlos a todos, pero todo lo que hagas servirá de ayuda tal y como están las cosas.$b$bTen cuidado con la horda, hemos recibido informes de que llevan a cabo emboscadas en la playa últimamente.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el coordinador de avanzada Brack en el Campamento de Baradin cuando termines.', 0),
(27972, 'esMX', 'Elevar la moral', 'Te han pedido que recuperes 6 barricas de ron de los Mares del Sur de los barcos naufragados en el Cabo de la Esperanza Perdida. El cabo se encuentra al norte de aquí, a lo largo de la costa.', 'La moral está baja estos días, $n. Hacemos todo lo que podemos para que las tropas mantengan la moral alta pero se nos están acabando los suministros de nuestro principal elevador de moral... el ron.$b$bHe recibido informes de nuestra infantería en el sur de que los barcos naufragados en el Cabo de la Esperanza Perdida todavía conservan sus suministros de ron de los Mares del Sur en sus cascos. ¿Podrías ir a investigar?$b$bTrae todo el ron que encuentres.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el coordinador de avanzada Brack en el Campamento de Baradin cuando termines.', 0),
(27973, 'esMX', '¡Cuidado con las astillas!', 'El sargento Gray te ha pedido que recuperes 15 trozos de madera de astillero del Astillero de Wellson. La madera puede obtenerse de los fantasmas del astillero o tirada en las inmediaciones. El astillero se encuentra al noroeste de aquí, en la costa.', '¿Has estado ya en el Astillero de Wellson, $n? Lo mejor es no acercarse por allí a no ser que se tenga un buen motivo para hacerlo. Por desgracia, es justo lo que necesito que hagas.$b$bVerás, desde que retomamos la isla estamos bajos de suministros. Ese astillero plagado de fantasmas está lleno de madera, pero siempre que hemos enviado a alguien a recogerla, no ha conseguido volver.$b$b¿Puedes ayudarnos?', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el sargento Gray en el Campamento de Baradin cuando termines.', 0),
(27974, 'esMX', 'Esta tierra es nuestra tierra', 'Mata al barón Ashbury.', '¿Pensabas que un puñado de alimañas huargen podrían detenerme? ¡Ja!$b$bEl Castillo de Colmillo Oscuro fue parte del reino de Lordaeron en vida, así que es muy apropiado que pertenezca a los Renegados en la muerte. Godfrey y sus cómplices son como mucho obstáculos menores, aunque estaremos encantados de acabar con ellos por su traición contra la Dama Oscura.$b$bAshbury se ha destacado cerca de la parte frontal del castillo y está expuesto a los ataques. Empecemos con buen pie, ¿te parece?', '', '', '', '', '', '', 'Barón Ashbury', '', '', 'Vuelve con: Comandante Mortacechador Belmont.', 0),
(27975, 'esMX', 'SE BUSCA: Supervisor Wellson', 'Mata al supervisor Wellson en el Astillero de Wellson. El astillero se encuentra al noroeste, en la costa oeste.', 'El supervisor Wellson ha sido un incordio desde que llegamos. Su astillero contiene una gran cantidad de suministros que nos resultarían extremadamente útiles... si pudiéramos echarles el guante.$b$bControla a sus esbirros de cerca y nos cuesta mucho adentrarnos en el astillero. Quiero que acabes con Wellson de una vez por todas. Ten cuidado, $n, hemos recibido informes de que la Horda está presente por todas partes.', '', '', '', '', '', '', 'Supervisor Wellson', '', '', 'Preséntate de nuevo ante el sargento Gray en el Campamento de Baradin cuando termines.', 0),
(27976, 'esMX', '¡Malditos dedos gordos!', 'Mata a 12 gólems de guerra pesados.', 'Desgraciadamente, ya no puedo pegar como antes, por culpa de este problema de dedos gordos. Verás, el clima de aquí, combinado con la falta de presión atmosférica, hace que se me expandan los dedos. Son como morcillas gigantes de Thelsamar, son...$B$BTendrás que cumplir mis órdenes.$B$BLo primero de mi agenda: darles una paliza a los gólems de guerra pesados de La Garganta. Ponte a ello.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Hansel Manospesadas. Zona: Puesto del Torio, La Garganta de Fuego.', 0),
(27977, 'esMX', 'Recuperar lo esencial', 'Encuentra y devuelve la tobera de herrería y el catalejo.', 'Aquí solíamos tener más cosas. Creo que había un catalejo y una tobera de herrería.$B$BEstoy seguro de que lo han robado los enanos Hierro Negro. ¡Sí, ya sé que yo soy un enano Hierro Negro! Hablo de los malos que viven en esa garganta.$B$BSerá mejor que registres a los vapoherreros que trabajan al sur de aquí. Seguramente trabajarán con herramientas como estas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Capataz Scrange. Zona: Puesto del Torio, La Garganta de Fuego.', 0),
(27978, 'esMX', 'Cazafantasmas', 'Mata a 14 fantasmas de cualquier tipo en el Alto de Largo, justo al noreste del campamento.', '¿Ves esa colina más allá de nuestro campamento? Es el Alto de Largo y no es un lugar agradable para establecer cerca un campamento. Desde que establecimos el campamento aquí hemos estado enfrentándonos con esos espíritus y espectros.$b$b¿Te importaría ir hasta allá arriba y hacerles saber que no pensamos irnos en el futuro próximo? Unas cuantas muertes en sus filas los mantendrán a raya.$b$bGracias por ayudarnos en esto, $n.', '', 'Fantasmas del Alto de Largo asesinados', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el sargento Gray en el Campamento de Baradin cuando termines.', 0),
(27979, 'esMX', 'Ministerio oscuro', 'Consigue la esferilla de Kiyuubi, la esferilla de Letherio y la esferilla de Finister, luego combínalas en una tripeticina Crepuscular.', 'Tengo otra tarea para ti. Esta viene del propio sobrestante. Parece que se quedó bastante impresionado cuando se enteró del "archiduque" que descubriste. $b$bNos ha pedido que le echemos el guante a tres ministros Crepusculares que trabajan en la Cresta Vigía, al oeste. Se llaman Kiyuubi, Letherio y Finister, y cada uno carga con una especie de roca especial. Combina las tres y tráemelas.$b$bEscucha, cuando el sobrestante da una orden, no hagas preguntas, ejecútala.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Hansel Manospesadas. Zona: Puesto del Torio, La Garganta de Fuego.', 0),
(27980, 'esMX', 'Las arañas tienen que desaparecer', 'Mata a 9 arañas de lava en La Garganta de Fuego.', 'Con las arañas de tamaño normal no tengo problema.$b$bLas arañas Cristalderma gigantes me ponen nervioso, pero están lo suficientemente lejos como para que no me preocupe demasiado.$b$b¿Pero las arañas de lava? <Lolo se estremece.> Las arañas de lava DAN MIEDO. Son arañas enormes. Que viven en la LAVA.$b$bAcaban de pagarme mi última semana de trabajo y te pagaré bien si matas a esas cosas. Las encontrarás en La Garganta de Fuego.  ', '', 'Araña de lava asesinada', '', '', '', '', '', '', '', 'Vuelve con: Capitán de vigía Lolo Zancalarga. Zona: Puesto del Torio, La Garganta de Fuego.', 0),
(27981, 'esMX', 'Calor incesante', 'Consigue 10 petacas de horno llenas. Tienes que usar las petacas de horno con elementales vivos en Las Garganta de Fuego.', 'Herramos, fundimos, tostamos cualquier carne de araña que podamos encontrar. Pollos de matorral si hay suerte. A lo que voy: todo ese trabajo significa que necesitamos mucho fuego.$B$BLo bueno es que estamos justo en medio de fuego city.$B$BPor supuesto, el mejor fuego viene de los elementales. Los encontrarás en toda La Garganta de Fuego, pero siempre cerca de la lava. Ten, coge este frasco y úsalo con los elementales.$B$BOh, ¿he mencionado que los elementales tienen que estar vivos cuando cojas la muestra?', '', '', '', '', '', '', '', '', '', 'Vuelve con: Hansel Manospesadas. Zona: Puesto del Torio, La Garganta de Fuego.', 0),
(27982, 'esMX', 'Colleras Crepusculares', 'Consigue 20 colleras Crepusculares.', '¿Has visto los ridículos collares que llevan esos cultores del Martillo Crepuscular? ¡Las gemas de esas cosas son más grandes que el puño de Hansel!$B$BUn par de gemas del tamaño de hamburguesas como esas y Burninate podría llevar su negocio de herrero a otro nivel. Trae esas colleras y te recompensará.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Herrero maestro Burninate. Zona: Puesto del Torio, La Garganta de Fuego.', 0),
(27983, 'esMX', 'La aventura de Ñoño: pequeños enanos gruñones', 'Debilita a 7 vapoherreros Hierro Negro para que Ñoño pueda hacerlos dormir.', '¿Qué hacer tú? ¿Por qué tú matar?$B$B¿Tú necesitar cosas de los enanos? Ah, Ñoño entender. Ñoño tener mejor manera.$B$BTú escuchar: tú luchar con enano, ¡pero no matar! Solo luchar hasta que enano estar cansado. Luego Ñoño ayudar enano a dormir. Enanos seguramente gruñir porque no poder dormir.$B$B¡Venga! Confiar en Ñoño.', '', 'Vapoherrero Hierro Negro dormidos', '', '', '', '', '', '', '', '', 0),
(27984, 'esMX', 'La historia de Lunthistle', 'Escucha a Zamael.', '¿Quieres ayudarme, mortal? Escucha lo que tengo que decir.', 'La historia de Zamael', '', '', '', '', 'La historia de Zamael', '', '', '', 'Vuelve con: Zamael Cardolún. Zona: Cresta Vigía, La Garganta de Fuego.', 0),
(27985, 'esMX', 'El rezo a Elune', 'Encuentra y lee el rezo a Elune.', '¿Me ayudarás, mortal? ¿Buscarás el rezo a Elune?$B$BComo te dije, el rezo fue grabado en una tablilla dorada. Creo que la tienen en una de sus viles cestas, cerca de la entrada de su cueva, al fondo de la mina.$B$BSi recuperas mi rezo, no me lo traigas a mí. En vez de eso, tómate el tiempo de leerlo.$B$BPuede que la absolución sea demasiado pedir, teniendo en cuenta los pecados que he cometido. Pero eso no me hará perder la esperanza.', '', '', '', '', '', '', '', '', '', '', 0),
(27986, 'esMX', 'En el salón del señor de la montaña', 'Habla con el señor de la montaña en la Cima de Hierro, en La Garganta de Fuego.', 'La Hermandad del Torio no tienen una milicia, solo algunos guardias y yo, eso es todo. Si queremos atacar con éxito a los Hierro Negro de la garganta, vamos a necesitar ayuda.$B$BEl señor de la montaña Rendan está en lo alto de esa torre, al otro lado de la garganta, hacia el sur. No tiene tratos con los Crepusculares ni con los elementales de fuego, pero tampoco se ha unido a la hermandad. Tal vez sea hora de hacerle una visita. Con su ayuda, puede que tengamos una oportunidad.', '', '', '', '', '', '', '', '', '', '', 0),
(27987, 'esMX', '¡Bola de cañón!', 'Tienes que recuperar 4 montones de bolas de cañón en el Alto de Largo para el sargento Gray. Encontrarás el Alto de Largo al noreste del campamento.', 'Largo y sus esbirros han estado robando nuestros suministros desde que acampamos aquí. Resulta frustrante, por no decir otra cosa.$b$bTenemos informes que indican que está almacenando bolas de cañón en las torres que dominan estas aguas en su Alto. ¿Podrías ir ahí arriba y tratar de recuperar algunas para nosotros?$b$bY, $n, no te olvides de mantenerte alerta contra la Horda también.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el sargento Gray en el Campamento de Baradin cuando termines.', 0),
(27988, 'esMX', 'Peste... ¡Peste por todas partes!', 'Mata al barón Filargenta y al comandante Vallefont.', '¡Lo mejor esta peste es que incluso cuando ha desaparecido a la vista, el residuo restante es bastante potente! Sin embargo, aún tenemos un área muy grande por cubrir antes de terminar, y Godfrey tiene muchas defensas.$b$bParece que los espíritus que servían al barón Filargenta en vida lo protegen en la muerte, y Godfrey los utiliza para repelernos. ¡Enséñale la voluntad de hierro de los Renegados!', '', '', '', '', '', '', 'Comandante Vallefont', '', '', 'Vuelve con: Comandante Mortacechador Belmont.', 0),
(27989, 'esMX', 'Ruumbo quiere miel', 'Recoge 10 pegotes de miel Muertobosque de las colmenas de la Aldea Muertobosque usando el palo de miel de Ruumbo.', '¡Ruumbo tiene hambre!$B$B¡Los estúpidos Muertobosque le han robado toda la miel a la tribu Fauces de Madera! Vimos... eh, ¡Ruumbo los vio! ¡Ahora Ruumbo exige tener esa miel!$B$B¡Toma este... este palo! Toma este palo y úsalo para robar la miel de sus colmenas en la Aldea Muertobosque.$B$BRuumbo tiene que tener toda la miel posible. Esto es vital.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Tótem de Ruumbo. Zona: Aldea Muertobosque, Frondavil.', 0),
(27990, 'esMX', 'Zona de batalla', 'El comandante Schnottz quiere que accedas a una de las torretas de sus tanques de asedio y que la uses para derrotar a 7 vigías decrépitos; después preséntate ante él.', 'Parrece que ha surrgido una nuefa oporrtunidad parra redimirrte, $r.$b$bEsta pequeña emerrgencia me ha dejado sin algunos tirradorres de tanque.$b$b¿Tienes lo que hay que tenerr parra ocuparr el lugarr de uno de ellos?$b$bMis tanques se encuentrran al oeste del campamento. ¡Sal ahí fuerra y acaba con estas patochadas!', '', 'Vigías decrépitos asesinados', 'De vuelta con Schnottz', '', '', '', '', '', '', 'Habla con: Comandante Schnottz. Zona: Embarcadero de Schnottz.', 0),
(27991, 'esMX', 'Recuperar el Alto', 'El sargento Gray te ha pedido que mates al comandante Largo en el Alto de Largo. El Alto se encuentra al noreste del campamento.', 'Solo hay una forma de recuperar el Alto de Largo.$b$bCreo que ya sabes lo que tenemos que hacer, $n. Largo está bastante paranoico últimamente, así que lo encontrarás en lo alto de la torre, esperando a que llegue por fin su marina imaginaria.', '', '', '', '', '', '', 'Comandante Largo', '', '', 'Preséntate de nuevo ante el sargento Gray en el Campamento de Baradin cuando termines.', 0),
(27992, 'esMX', 'Imanes, ¿cómo funcionan?', 'Te han encargado que recuperes 7 piezas de chatarra de máquina de asedio. Usa el recolector de chatarra magnetizado en el Frente Inquieto para encontrar chatarra. El Frente Inquieto se encuentra al oeste, pasado el segundo puente.', 'Conseguir piezas útiles de maquinaria en la isla no ha sido tarea fácil, $n. Llevamos tiempo intentando reparar las máquinas de asedio estropeadas en el campamento, pero siempre nos quedamos sin las piezas necesarias.$b$bNuestro segundo regimiento nos ha informado de que hay máquinas de asedio destrozadas en un antiguo campo de batalla al oeste de aquí. Tal vez encontremos algunas piezas allí.$B$bTe costará encontrar algo en ese campo de batalla, así que llévate este recolector de chatarra magnetizado y dale buen uso.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el teniente Farnsworth en el Campamento de Baradin cuando termines.', 0),
(27993, 'esMX', '¡Dales su merecido!', 'Mack quiere que investigues la Tumba de Khartut.', 'Hemos tenido suerte de escapar, $c. No creo que me sienta bien si no nos ocupamos de esos emboscadores.$b$b¿Qué tal si vuelves a la Tumba de Khartut y les das a esos indeseables su merecido?$b$bEstá al noreste, justo al entrar a Uldum, si mal no recuerdo.$b$b¿Qué estás mirando? ¡Evidentemente yo no estoy en condiciones de hacerlo!', '', 'Tumba de Khartut investigada', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Tumba de Khartut.', 0),
(27994, 'esMX', 'Ruumbo pide justicia', 'Mata a 15 fúrbolgs Muertobosque de cualquier tipo.', '¡Tú! ¡$gVagabundo:Vagabunda;! ¡Inclínate ante el poderoso Ruumbo, gran dios de la tribu Fauces de Madera!$B$B¡Escucha mis deseos! ¡La maligna tribu Muertobosque vive en el poblado que hay detrás de mí! ¡Son unos tremendos estúpidos!$B$BEs decir, ellos... ¡ellos mancillan mi nombre con sus malvadas fechorías! ¡Cazan a los miembros de mi amada tribu Fauces de Madera y les hacen daño!$B$B¡Exijo que impongas mi justicia! Derrota a los Muertobosque y yo te... ¡te favoreceré! ¡Sí! ¡Tendrás el favor de RUUMBO!', '', 'Fúrbolg Muertobosque asesinado', '', '', '', '', '', '', '', 'Vuelve con: Tótem de Ruumbo. Zona: Aldea Muertobosque, Frondavil.', 0),
(27995, 'esMX', '¡Baila para Ruumbo!', 'Ejecuta un baile estúpido para Ruumbo.', '¡Lo has hecho bien, $r! Ruumbo está complacido por tu valentía y por la deliciosa miel que le has dado a Ruumbo.$B$BAhora debes... ¡debes bailar! ¡Sí!$B$B¡Baila para Ruumbo! ¡Baila!', '', 'Secreto de Ruumbo descubierto', '', '', '', '', '', '', '', 'Vuelve a contarle lo que ha pasado a: Grazle. Zona: Santuario Esmeralda, Frondavil.', 0),
(27996, 'esMX', 'Las órdenes son para los vivos', 'Mata a Lord Walden.', 'No es ninguna sorpresa, pero no vamos a hacer caso a las órdenes de Cromush sobre la peste. Sin embargo, su fuerza bruta nos vendrá bien para abrirles camino a mis hombres por los muchos enemigos nos separan de Godfrey. El más poderoso es su mano derecha, Lord Walden.$b$bMe reuniré contigo en la cámara de Walden cuando hayas acabado con él. Entonces, por fin, ¡podremos tomar todo el Castillo de Colmillo Oscuro para los Renegados!', '', '', '', '', '', '', 'Lord Walden', '', '', 'Vuelve con: Comandante Mortacechador Belmont.', 0),
(27997, 'esMX', 'La corrupción de los Fuego de Jade', 'Mata a 12 sátiros Fuego de Jade o Jurapenas Fuego de Jade en la Cañada Fuego de Jade.', 'La purificación de este bosque ha sido un proceso extenuante. Por cada éxito que hemos tenido, ha surgido un nuevo desafío.$B$BLos sátiros Fuego de Jade han sido una molestia constante. Quieren corromper el bosque tanto como nosotros queremos purificarlo. Bien, hemos tomado medidas para empezar a erradicarlos por completo de Frondavil.$B$BViaja a la Cañada Fuego de Jade, al oeste, y libra al bosque de su presencia. Encontrarás la entrada justo al norte de las murallas de la Aldea Muertobosque; busca sus horribles estandartes.', '', 'Sátiro Fuego de Jade asesinado', '', '', '', '', '', '', '', 'Vuelve con: Tenell Correhoja. Zona: Santuario Esmeralda, Frondavil.', 0),
(27998, 'esMX', 'Dulce, despiadada venganza', 'Mata a Lord Godfrey.', 'Si todo va bien, podrás entrar directamente en el dominio personal de Godfrey y tomar una recompensa digna de $gun:una; joven $c tan $gambicioso:ambiciosa;.$b$bPero Godfrey es un oponente astuto, así que lo mejor será que te dirijas allí rápidamente por si haces falta. ¡Pagará por lo que le hizo a la Dama Oscura!', '', '', '', '', '', '', 'Lord Godfrey', '', '', 'Vuelve con: Comandante Mortacechador Belmont.', 0),
(27999, 'esMX', 'El fin de los Doyle', 'Lleva las noticias del clan Doyle a Iain Barbafuego, en el Cementerio Barbafuego.', 'Parece que los Doyle ya han librado su última batalla. Iain querrá saber qué les ha ocurrido.', '', '', '', '', '', '', '', '', '', '', 0),
(28000, 'esMX', 'Endiabladamente difícil', 'Debilita a Diblis y usa el saco de diablillo encantado para capturarlo.', 'Los sátiros esconden su Poza de la Luna corrupta tras una impenetrable barrera de fuego demoníaco. Sus fuerzas deben de tener algún modo de cruzar.$B$BInterrogar a los sátiros no servirá de nada, pero los diablillos con los que tratan serán fácilmente persuadidos. Tengo en mente a uno en concreto y también...$B$BEn las laderas del este han visto a un diablillo solitario vagar alejado de los otros demonios. Debería ser fácil cogerlo. Debilítalo en combate y luego usa este saco encantado para capturarlo. Yo hablaré con él...', '', 'Diblis capturado', '', '', '', '', '', '', '', 'Vuelve con: Arcanista Delaris. Zona: Ruinas de Constellas, Frondavil.', 0),
(28001, 'esMX', 'El deber de un cobarde', 'Habla con Colin Bramal en Bramal.', 'Aquí estamos a salvo, pero hay muchos Martillo Salvaje que todavía necesitan ayuda. Nuestro pelotón puede ofrecérsela, pero tenemos que seguir incrementando nuestras fuerzas si queremos hacer desaparecer a los Crepusculares.$B$BVoy a tener unas palabras con Colin Bramal. Solo un cobarde desoye la llamada de su gente, sobre todo en un momento tan nefasto.$B$bVe a Bramal, encuentra a Colin y haz que te dé una explicación. No toleraré semejante cobardía en un líder Martillo Salvaje.', '', '', '', '', '', '', '', '', '', '', 0),
(28002, 'esMX', 'Gestión de crisis', 'Belloc Hoja Brillante quiere que calmes a los invitados del Embarcadero de Schnottz.', 'Tenemos una situación delicada para la que necesitamos la... discreción objetiva de alguien externo.$b$bVerás, un desgraciado incidente ha disgustado a algunos de nuestros invitados. No te quepa duda de que nuestros mejores hombres están investigando los detalles.$b$bMientras tanto, sería perfecto que fueras capaz de calmar a nuestros invitados más aprensivos.$b$b¡Si manejas esto bien, el camarada peletero será informado de ello!', '', 'Escritor prolífico interrogado', 'Famosilla privilegiada calmada', 'Hombre de negocios pretencioso escarmentado', 'Artista en ciernes aconsejado', '', '', '', '', 'Habla con: Belloc Hoja Brillante. Zona: Embarcadero de Schnottz.', 0),
(28028, 'esMX', '¡Asedio!', 'Mata a 9 tiradores Hierro Negro.', 'El sobrestante Puñaceite no podía haber elegido un momento peor para pedirme que me una a la lucha. ¡Mi cima ya está bajo asedio!$B$BNo es nada que mis guardias no puedan controlar; aun así, no me será nada fácil coger a algunos enanos y enviarlos a esa garganta infernal.$B$B¿Sabes qué te digo? ¡Elimina a sus tiradores, que son los que mantienen la fortaleza bajo asedio, y tendré tu oferta en consideración! Estarán escondiéndose en los llanos del este.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Señor de la montaña Rendan. Zona: Cima de Hierro, La Garganta de Fuego.', 0),
(28029, 'esMX', '¡Préndeles fuego!', 'Usa la antorcha de reprensión en las cuatro torres que hay alrededor la Caldera.', 'No sé si lo habrás notado, pero mi torre es mucho más alta que cualquiera de las otras torres de La Garganta. Algunos enanos se enorgullecen de lo profundo que pueden cavar, pero yo no. A veces creo que debería haber sido un Martillo Salvaje.$B$BAunque sigue sin gustarme ver esas otras torres. Alzándose así, haciéndole cosquillas a los pies de mi torre. Toma, coge esta antorcha y úsala para prender los blandones que hay en lo alto de esas otras torres. Lamentarán haberlas construido.', '', 'Torre oeste en llamas', 'Torre sudoeste en llamas', 'Torre sudeste en llamas', 'Torre este en llamas', '', '', '', '', 'Vuelve con: Señor de la montaña Rendan. Zona: Cima de Hierro, La Garganta de Fuego.', 0),
(28030, 'esMX', 'Construyen mejores balas', 'Consigue 200 balas Hierro Negro.', 'Esos enanos cavadores de la garganta hacen al menos una cosa bien: hacen unas balas de primera. Yo no he logrado reproducir sus resultados, así que me he dedicado a robar cualquier bala suya que encuentre.$B$B¿Quieres ayudarme? Consígueme unos cuantos cientos de balas de esos tiradores de ahí abajo.$B$BEstoy seguro de que estarán encantados de darte sus balas de una en una, pero puede que te resulte más fácil buscarlas en los cajones que están llenos de ellas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Señor de la montaña Rendan. Zona: Cima de Hierro, La Garganta de Fuego.', 0),
(28031, 'esMX', 'Envío especial para Bridatuer', 'Entrégale el Criocañón E-lado a Bridatuer en la Excavación Sumergida, en Las Mil Agujas.', 'Tengo un nuevo socio empresarial: mi mejor amigo, Bridatuer. ¡Ahora mismo está levantando la infraestructura de nuestro nuevo emporio de helados!$b$bSe llevó nuestro congelante, nuestro inventario y nuestros empleados al suroeste, a la Excavación Sumergida. Por desgracia, en estos momentos no tengo forma de entregarle una cosa... Una cosa muy importante: ¡nuestro supersecreto Criocañón E-lado!$b$b¿Te importa llevárselo, $n?', '', '', '', '', '', '', '', '', '', '', 0),
(28032, 'esMX', 'Los misterios de las mollejas de fuego', 'Consigue 6 mollejas de fuego.', 'Hay tantas cosas que ignoramos de los incendiosauros. ¿De dónde vinieron? ¿Cómo sobreviven aquí, en los llanos? ¿Y por qué saben tan mal?$B$BCreo que la clave para comprender a estas bestias prehistóricas está en las mollejas de fuego. Todos los incendiosauros tienen una. Me gustaría tener unas cuantas para estudiarlas.$B$BEncontrarás incendiosauros alrededor del pie de la Cima de Hierro, más bien al oeste.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Agnes Finesquisto. Zona: Cima de Hierro, La Garganta de Fuego.', 0),
(28033, 'esMX', 'Engaño', 'Encuentra la forma de convencer al señor de la montaña Rendan para que se una a la Hermandad del Torio.', '¿Qué? ¿Por qué sigues aquí? Oh, ¿prometí que los ayudaría a ti y a la Hermandad del Torio en su lucha?$B$BMentí.$B$BNo puedo prescindir de hombres ahora mismo. Sé que dije que los ayudaría, pero no podrás convencerme de ninguna manera para que deje la Cima de Hierro ahora. De ninguna manera.', '', '', '', '', '', '', '', '', '', 'Habla con: Ñoño. Zona: Cima de Hierro, La Garganta de Fuego.', 0),
(28034, 'esMX', 'La aventura de Ñoño: la debilidad de Rendan', 'Habla con tres guardias de Cima de Hierro y pídeles que se unan a tu baile.', 'Ñoño no ser listo, pero Ñoño darse cuenta de cosas. Hoy, Ñoño darse cuenta de que a enano de la montaña gustar ver gente bailar.$B$B¡A Ñoño gustar bailar! ¡A $n gustar bailar! ¡Tal vez!$B$BQuizás nosotros encontrar más enanos que gustar bailar. Después nosotros hablar con enano de la montaña y él escuchar a $n.', '', 'Haz un fila de conga con tres enanos', '', '', '', '', '', '', '', 'Preséntate ante: Señor de la montaña Rendan. Zona: Cima de Hierro, La Garganta de Fuego.', 0),
(28035, 'esMX', 'El apoyo del Señor de la montaña', 'Informa de tu éxito al sobrestante Puñaceite en el Puesto del Torio, en La Garganta de Fuego.', '¡Bien, bien! De haber sabido que bailabas así, te hubiera pedido antes que hicieras todo eso.$B$BDile al sobrestante Puñaceite que me uniré a ustedes. ¡Nos encontraremos en la Fosa de la Escoria, $gmuchacho:muchacha;! Con las fuerzas combinadas del Puesto del Torio y de la Cima de Hierro, ¡esos enanos de La Garganta no sabrán de dónde vienen los golpes!', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Sobrestante Puñaceite. Zona: Puesto del Torio, La Garganta de Fuego.', 0),
(28038, 'esMX', 'Sangre en las Tierras Altas', 'Habla con Wodin, el sirviente trol, en el Crisol de Matanza en las Tierras Altas Crepusculares.', 'Sabes luchar, $c. Puede que te vaya bien en el Crisol.$B$B¿¡Cómo!? ¿No has oído hablar del Crisol de Matanza? Gurgthock, ese goblin pelota y su compañero trol nos han estado empapelando con panfletos desde que montó su negocio aquí, en las Tierras Altas. Allí luchan a muerte campeones de todo Azeroth. Deberías reunir a algunos amigos y ver qué tal te va.$B$BEl Crisol está al sudoeste. Busca a Wodin, el sirviente trol, en alguna parte en medio del círculo de huesos.', '', '', '', '', '', '', '', '', '', 'Habla con: Wodin, el sirviente trol. Zona: Crisol de Matanza, Tierras Altas Crepusculares.', 0),
(28041, 'esMX', 'Atraer y atrapar', 'Consigue un cadáver de grifo fresco.', 'Sabes arreglártelas en el suelo, $n. Eso lo reconozco.$B$BPero los Faucedraco dominan tanto los cielos como la tierra. Tu Horda no significará nada para mí hasta que me demuestres que puedes manejar tan bien a un draco como a un Faucedraco.$B$BVeamos si puedes traer a uno hasta Garganta de Sangre.$B$BPrimero necesitarás un cebo. Sal por ahí y mata a uno de los grifos que hay en los bosques al oeste y al noreste de aquí. ¡Asegúrate de que no esté domado! Los dracos odian que su comida apeste a enano.$B$BCoge el cadáver del grifo y ya sabes qué hacer a continuación.', '', '', '', '', '', '', '', '', '', 'Consigue un cadáver de grifo fresco.', 0),
(28042, 'esMX', 'Envío especial para Bridatuer', 'Entrégale el Criocañón E-lado a Bridatuer en la Excavación Sumergida, en Las Mil Agujas.', 'Hace poco me encontré con algo que debe entregarse a un gnomo llamado Bridatuer. Es más bien Idiotuer, si quieres mi opinión.$b$bQuiero que se lo lleves al suroeste, a la Excavación Sumergida. Está tramando algo, y hay dinero de por medio... ¡Puedo olerlo!$b$bVigila lo que hace, $n, y mira a ver si puedes conseguir una tajada de sus beneficios. ¡Una buena tajada!', '', '', '', '', '', '', '', '', '', '', 0),
(28043, 'esMX', 'Cómo domar a tu dragón', 'Atrae a un draco negro cebado, atácalo hasta que esté débil, monta en él y vuelve a Garganta de Sangre. ', '<Te echas al hombro el cadáver lleno de sangre del grifo, su ala va arrastrando por el suelo.>$b$b<Justo al sudoeste del Crisol de Matanza anidan dracos negros de las Tierras Altas, a lo largo de un anillo de picos de montaña bajos.>$b$b<Si tiras allí el cadáver del grifo, seguro que un draco viene a comérselo. Cuando tenga guardia baja, deberías poder atacarlo hasta que esté lo suficientemente débil para que puedas montarte en él y volar.>', '', 'Draco negro cebado capturado', '', '', '', '', '', '', '', 'Habla con: Zaela. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(28044, 'esMX', 'Toca lo intocable', 'Usa la poción de sangre de fase en el sigilo de Tichondrius para poder entrar en el vacío y buscar la garra de Tichondrius.', 'Le he añadido una gota de mi propia esencia al moco. Busca un sigilo brillante en el oeste, al borde de la Cresta Acechumbra. Colócate encima, concéntrate y échate esto encima. Debería bastar para permitirte pasar al vacío y ver lo que hay ahí REALMENTE.$B$BNo estarás $gsolo:sola;... el tesoro de los sátiros está vigilado por el acechador del vacío más grande que pudieron invocar. Derrótalo y el tesoro será tuyo.$B$BY vuelve de una sola pieza ¡o esta vieja loca me freirá!', '', '', '', '', '', '', 'Vorlus', 'Ahora no te muevas.', 'Arcanista Delaris', 'Vuelve con: Arcanista Delaris. Zona: Ruinas de Constellas, Frondavil.', 0),
(28045, 'esMX', '¡El mejor sabor del mundo!', 'Recoge 8 bolas de baba de silítido.', 'Bajo nuestros pies hay una cueva. ¡Es enorme! Es el lugar perfecto para nuestra nueva cámara frigorífica. Es lo bastante grande como para albergar todo nuestro inventario y más.$b$bPor desgracia, cuando estábamos a punto de terminar con las tuberías, ¡unos bichos salieron de la nada y mataron a todos mis empleados!$b$b¿Cómo podía haberlo sabido?$b$bPero me ha dado una gran idea: helado con sabor a silítido. ¡Nos vamos a hacer de oro!$b$bSolo necesito los siguientes ingredientes...', '', '', '', '', '', '', '', '', '', 'Vuelve con: Bridatuer. Zona: Excavación Sumergida, Las Mil Agujas.', 0),
(28046, 'esMX', 'Termina el trabajo', 'Mata a 5 soldados de la infantería inquieta en El Frente Inquieto. Encontrarás el frente en la zona oeste de la isla, justo antes de la Colina del Olvido.', 'Llevamos toda la semana tratando de recoger chatarra útil en el frente. Cada vez que reunimos un lote para llevarlo al campamento, nos asalta la infantería inquieta de la zona. ¿Podrías dirigirte hasta allí y borrarla del mapa?', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el teniente Farnsworth en el Campamento de Baradin cuando termines.', 0),
(28047, 'esMX', 'Congelar las tuberías', 'Utiliza el Criocañón E-lado para congelar las cuatro tuberías del interior de la cueva.', '¡Es hora de estrenar el Criocañón E-lado!$b$bPlagiamos la tecnología de los cañones de escarcha de los barcos fluviales. Si hay algo que se nos da bien a los gnomos, ¡es miniaturizar cosas haciendo que todo lo demás sea mucho más grande!$b$bQuiero que bajes el cañón hasta la cueva y congeles las tuberías que hemos instalado en las paredes. Eso las pondrá en funcionamiento.', '', 'Primera tubería congelada', 'Segunda tubería congelada', 'Tercera tubería congelada', 'Cuarta tubería congelada', '', '', '', '', 'Vuelve con: Bridatuer. Zona: Excavación Sumergida, Las Mil Agujas.', 0),
(28048, 'esMX', 'Hay que acabar con el listo', 'Mata al controlador de colmena.', 'Hay algún tipo de bicho cerebro listo al fondo de la cueva. Está al mando de todos los silítidos que hay allá abajo.$b$b¡Se me está derritiendo el helado! ¿Cómo voy a lanzar mi emporio de helados y salvar mi inventario si esa cosa sigue ahí?', '', '', '', '', '', '', 'Controlador de colmena', '', '', 'Vuelve con: Bridatuer. Zona: Excavación Sumergida, Las Mil Agujas.', 0),
(28049, 'esMX', 'Ver lo invisible', 'Recoge 8 lotes de moco maldito de las Ruinas de Constellas.', 'Sí, sí, la estirada de tu amiga maga ha dado en el clavo. Los diablillos de la Cresta Acechumbra esconden la llave de la barrera de los sátiros en el vacío. Está justo ahí, pero no puedes verlo o tocarlo a menos que cambies de fase.$B$BPero me parece que la fortuna no te sonríe, ¡porque solo los diablillos pueden cambiar de fase! Así que deberías cerrar los ojos, darte la vuelta y dejarme ir...$B$B¡Es broma! ¡No me hagas daño! Necesitaré babosas de los mocos malditos que hay alrededor de estas ruinas. ¡Tráeme suficientes para cubrirte de pies a cabeza!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Diblis. Zona: Ruinas de Constellas, Frondavil.', 0),
(28050, 'esMX', 'Tiburón Tanque', 'Te han pedido que mates a Tanque, un gran tiburón que recorre las aguas del Cabo de la Esperanza Perdida. El cabo se encuentra al norte de aquí, a lo largo de la costa norte.', 'Odio los tiburones. Mis tropas odian los tiburones también. Y ahí es donde entras tú, $n.$b$bNecesito que te dirijas al Cabo de la Esperanza Perdida y que acabes con un tiburón enorme que se llama Tanque. Tanque es duro de pelar, así que si fuese tú, me llevaría a algunos amigos.', '', '', '', '', '', '', 'Tanque', '', '', 'Preséntate de nuevo ante el coordinador de avanzada Brack en el Campamento de Baradin cuando termines.', 0),
(28051, 'esMX', 'Todo el mundo se muere por un helado…', 'Engancha el cable del remolque a 10 empleados muertos.', 'No me malinterpretes... Estoy contento por fuera, pero por dentro estoy totalmente destrozado. Todos mis amigos y empleados están muertos.$b$b¿Me harías un favor? Bucea por ahí y engancha el cable del remolque a mis empleados muertos. Yo tiraré de ellos.', '', 'Empleados muertos enganchados', '', '', '', '', '', '', '', 'Vuelve con: Bridatuer. Zona: Excavación Sumergida, Las Mil Agujas.', 0),
(28052, 'esMX', 'Operación: remover la caldera', 'Habla con el maestro de vuelo del Puesto del Torio, luego usa las armas de fuego de la máquina voladora de la hermandad para matar a defensores de la caldera hasta que se pueda entrar en la zona de forma segura.', 'Te voy a meter en una máquina voladora, $n.$B$BSerás $gel:la; responsable de hacer que nuestro aterrizaje en la Fosa de la Escoria sea agradable. Habla con tu maestro de vuelo aquí, en el Puesto del Torio, luego vuela hasta la Garganta.$B$BCuando te acerques al punto de aterrizaje, seguramente te estarán esperando hordas de enanos Hierro Negro. Usa las armas de fuego de la máquina voladora para eliminar a todos los que puedas, luego aterriza en la entrada de la caverna. Rendan debería estar esperándote cuando llegues.', '', 'Es seguro entrar en la Fosa de la Escoria', '', '', '', '', '', '', '', 'Preséntate ante: Señor de la montaña Rendan. Zona: Entrada de la Fosa de la Escoria, La Garganta de Fuego.', 0),
(28053, 'esMX', 'A Ñoño gustar tu estilo', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28054, 'esMX', 'La esclavitud es mala', 'Mata a 10 capataces Hiero Negro o esclavistas Hierro Negro.', 'Al igual que el sobrestante Maltorius, soy un enano rico. Sin embargo, yo gané mis riquezas con trabajo duro y decisiones sabias, no con la esclavitud.$B$BSí, vale, con muy poquita esclavitud. Casi nada.$B$BComo sea, lo primero que veo en estas cavernas son explotadores y capataces. ¡No lo permitiré! Según avances por la caverna, mata a todos los que puedas. Informa de tus resultados a Evonis Fumollín, en las profundidades de la Fosa de la Escoria.', '', 'Capataz Hierro Negro o esclavista Hierro Negro asesinado', '', '', '', '', '', '', '', 'Informa a: Evonis Fumollín. Zona: Fosa de la Escoria, La Garganta de Fuego.', 0),
(28055, 'esMX', 'Dulce y horrible libertad', 'Libera a 12 trabajadores esclavos. Si se resisten, mátalos.', 'Por supuesto, querremos liberar a todos los esclavos que podamos mientras estemos aquí. La mayoría de ellos seguramente se unirá a nosotros, ansiosos por luchar contra sus captores.$B$BSin embargo, verás que algunas veces los esclavos se resisten a ser liberados. Es un fenómeno extraño, se lo suele llamar "el síndrome de Durnholde".$B$BDe cualquier forma, deberías intentar liberarlos. Si se resisten, trátalos como a enemigos. Informa de tus resultados a Evonis Fumollín, en las profundidades de la Fosa de la Escoria.', '', 'Trabajadores esclavos liberados o asesinados', '', '', '', '', '', '', '', 'Preséntate ante: Evonis Fumollín. Zona: La Fosa de la Escoria, La Garganta de Fuego.', 0),
(28056, 'esMX', 'Álzate, Obsidion', 'Usa el altar de Suntara, luego mata a Lathoric el Negro y a Obsidion.', 'El sobrestante Maltorius está al mando aquí, pero no es el único enano con poder en la Fosa de la Escoria. Lathoric el Negro y su terrorífico gólem, Obsidion, están justo al fondo de este pasillo.$B$BDeberías poder invocarlos a los dos utilizando el altar de Lathoric. Encuéntralo, luego invoca a Lathoric y mátalo. Preséntate ante Evonis Fumollín cuando hayas terminado.', '', '', '', '', '', '', '', '', '', 'Informa a: Evonis Fumollín. Zona: Fosa de la Escoria, La Garganta de Fuego.', 0),
(28057, 'esMX', 'Mátalos privándolos de sueño', 'Consigue 16 almohadas Hierro Negro.', 'Es un hecho poco conocido que los enanos, especialmente los Hierro Negro, ¡necesitan descanso! ¡Mucho descanso!$B$BY ahora te pregunto: ¿cómo pueden dormir sin almohadas? Exacto, $n, no pueden. Por eso debes robarles las almohadas.$B$BCuando hayas terminado tu robo de almohadas, habla con el capataz Scrange. Está un poco más adentro de la cueva, trabajando en un proyecto secreto con Hansel.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Capataz Scrange. Zona: Fosa de la Escoria, La Garganta de Fuego.', 0),
(28058, 'esMX', '¡Mira el tamaño de esto!', 'Lleva la almohada de la ayudante de cámara Pilaprieta a Evonis Fumollín a La Garganta de Fuego.', 'Vaya, vaya... La ayudante de cámara tenía una enorme almohada bordada y ahora es tuya. Seguro que Evonis Fumollín estará encantada; llévale la almohada, a ver si te recompensa con algo.', '', '', '', '', '', '', '', '', '', '', 0),
(28059, 'esMX', 'Reclamar la fortaleza', 'Te han pedido que mates al señor de la fortaleza Farson en la Fortaleza de Farson. La Fortaleza de Farson se encuentra en la zona norte de la isla.', '¿Has visto la fortaleza de la zona norte de la isla, $n? Desde ahí dirige el señor de la fortaleza Farson sus operaciones.$b$bFarson tiene un pequeño grupo de acérrimos seguidores que nos han estado dando problemas desde que llegamos. Enviamos a un grupo a investigar y nos informó de su posición exacta en el interior de la fortaleza.$b$b¿Podrías acabar con él por nosotros?', '', '', '', '', '', '', 'Farson', '', '', 'Preséntate de nuevo ante el comandante Marcus Johnson en el Campamento de Baradin cuando termines.', 0),
(28060, 'esMX', 'Retorcidos lazos Crepusculares', 'Habla con Hansel Manospesadas y ayúdale a atacar al sobrestante Maltorius y al señor Crepuscular Arkkus.', 'Hansel y yo hemos venido aquí con una misión secreta: matar al sobrestante Maltorius. Aunque nuestro objetivo principal sigue siendo el mismo: derrotar al archiduque Rescoldo, no pasa nada si aprovechamos para eliminar al infame sobrestante de la Fosa de la Escoria, ya que estamos aquí.$B$BEl problema es que Hansel solo estaba preparado para enfrentarse a un enano, pero parece que Maltorius tiene visita... ¡un emisario del Martillo Crepuscular!$B$BHabla con Hansel y ayúdale. Luego baja por este pasillo hasta salir al balcón y verás al sobrestante Puñaceite.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Sobrestante Puñaceite. Zona: La Fosa de la Escoria, La Garganta de Fuego.', 0),
(28061, 'esMX', 'Esbirros de Rescoldo', 'Mata a 6 espantos de llama abrasadores.', 'Es posible cavar demasiado hondo, $n. Aunque bajo la superficie se hallan las vetas más ricas en minerales, también se pueden encontrar las criaturas más malvadas.$B$BComo los elementales de fuego.$B$BLos esbirros de Rescoldo deambulan por la caverna que hay allí delante. Cada uno de ellos lleva en su interior un pedazo de la maldad de Rescoldo. Mata a todos los que puedas y no sientas remordimientos.', '', '', '', '', '', '', '', '', '', '', 0),
(28062, 'esMX', 'De donde vino', 'Debilita al archiduque Rescoldo, luego usa la tripeticina consagrada para desterrarlo.', 'El archiduque Rescoldo se retuerce en el fondo de esta caverna. Podríamos matarlo... pero eso no es lo que vamos a hacer.$B$BMatar a Rescoldo aquí no significaría nada. En vez de eso, lo vamos a desterrar.$B$BAntes te pedí que consiguieras una piedra preciosa del Martillo Crepuscular. Ahora la usarás contra Rescoldo. Pelea con él, debilítalo y luego usa este objeto con él. Será desterrado de este reino.$B$BBuena suerte, valiente $n.', '', 'Archiduque Rescoldo desterrado', '', '', '', '', 'Archiduque Rescoldo', '', '', '', 0),
(28063, 'esMX', 'Hasta la última arma', 'Recoge 12 rifles oxidados en la Fortaleza de Farson en la zona norte de la Península de Tol Barad.', 'Es difícil encontrar suministros de batalla en esta roca. Cada vez que nos enfrentamos a un ataque de la Horda, da la sensación de que estamos luchando con palos y piedras.$B$BNos han informado de que el señor de la fortaleza Farson, en la zona norte de la isla, tiene grandes reservas de rifles que podríamos usar. ¿Podrías dirigirte hacia allí y confirmarlo?$b$bTen cuidado, $n, los seguidores de Farson harán lo que sea con tal de protegerlo.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Marcus Johnson en el Campamento de Baradin cuando termines.', 0),
(28064, 'esMX', 'Bienvenidos a la hermandad', 'Preséntate ante el sobrestante Puñaceite en el Puesto del Torio en la Garganta de Fuego.', 'Deberías regresar al Puesto del Torio. El sobrestante Puñaceite y el resto de la Hermandad del Torio se estarán preguntando cómo te fue en la lucha contra Rescoldo.', '', '', '', '', '', '', '', '', '', '', 0),
(28065, 'esMX', 'Ponte en su pellejo durante un tiempo', 'Escolta al prisionero de la Fortaleza de Farson hasta lugar seguro. La fortaleza se encuentra en el extremo norte de la isla.', 'Hemos mandado al menos a 3 grupos de reconocimiento diferentes a la Fortaleza de Farson durante las últimas semanas. Por desgracia, ninguno ha vuelto con información.$B$BEn este momento, lo único que podemos esperar es que los tengan retenidos como prisioneros. Necesito que te infiltres en la fortaleza y que rescates a nuestros soldados. No será fácil, $n, pero si alguien puede ayudarnos $gese:esa; eres tú.', 'Prisionero de Farson escoltado', '', '', '', '', 'Prisionero de Farson escoltado', 'Prisionero de Farson', '', '', 'Preséntate de nuevo ante el comandante Marcus Johnson en el Campamento de Baradin cuando termines.', 0),
(28068, 'esMX', 'Se buscan aventureros: Profundidades de Roca Negra', 'Habla con Morgan.', 'El rey Varian Wrynn ha solicitado que todos los aventureros aptos se dirijan a las Profundidades de Roca Negra, al noroeste de la Vigilia de Morgan, ¡de inmediato!$b$b¡Los enanos Hierro Negro suponen una grave amenaza para los ciudadanos de Crestagrana! Si decides ayudar, dirígete a las Profundidades de Roca Negra y habla con Morgan, quien acaba de volver de su larga ausencia y desea ejecutar su venganza contra la nación Hierro Negro.', '', '', '', '', '', '', '', '', '', '', 0),
(28069, 'esMX', 'Se buscan aventureros: Profundidades de Roca Negra', 'Habla con el sumo verdugo Nuzrak.', 'El Jefe de Guerra ha solicitado que todos los aventureros aptos se dirijan a las Profundidades de Roca Negra, al oeste de Peñasco Llamarada, ¡de inmediato!$b$b¡Los enanos Hierro Negro ya han atacado Crestagrana, ocupada por la Alianza, y si no se les detiene pronto podrían ser una amenaza para las pocas ciudadelas de la Horda que hay en el sur de Azeroth! Si decides ayudar, dirígete a las Profundidades de Roca Negra y habla con el sumo verdugo Nuzrak, que está reconstituyendo la Fuerza Expedicionaria de Kargath para acabar con los Hierro Negro de una vez por todas.', '', '', '', '', '', '', '', '', '', '', 0),
(28084, 'esMX', 'El poder de Krom\'gar', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28085, 'esMX', 'Problemas en Nido Alto', 'Habla con Pao\'ka Monte Presto en Nido Alto, en Las Mil Agujas.', 'Gracias por tu ayuda, $n. Deberías hablar con Pao\'ka Monte Presto en Nido Alto, al suroeste.$b$bA lo mejor él conoce el paradero de la bruja anciana.', '', '', '', '', '', '', '', '', '', '', 0),
(28086, 'esMX', 'Libera a los lechigados', 'Libera 12 lechigados de Nido Alto.', 'Los tramperos están apresando a los jinetes del viento jóvenes. $n, ¿irías hasta allí para liberar a los lechigados?', '', 'Lechigados liberados', '', '', '', '', '', '', '', 'Vuelve con: Pao\'ka Monte Presto. Zona: Nido Alto, Las Mil Agujas.', 0),
(28087, 'esMX', '¡Muerte a todos los tramperos!', 'Reúne 8 redes de trampero.', 'Solo hay una respuesta para esos despreciables tramperos del Martillo Crepuscular: ¡la muerte!$b$bTráeme sus redes, $n.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Pao\'ka Monte Presto. Zona: Nido Alto, Las Mil Agujas.', 0),
(28088, 'esMX', 'Libera a Cuorevaja', 'Libera a Cuorevaja de todas sus ataduras.', 'El Martillo Crepuscular ha encadenado al líder de la manada de Nido Alto. ¡Debes subir por la rampa que hay al este y liberar a Cuorevaja antes de que la manada pierda a su patriarca!', '', 'Cuorevaja liberado', '', '', '', '', '', '', '', 'Vuelve con: Pao\'ka Monte Presto. Zona: Nido Alto, Las Mil Agujas.', 0),
(28089, 'esMX', '¡La orden del Jefe de Guerra: Laderas de Trabalomas!', 'Preséntate ante la suma ejecutora Darthalia en la Puerta Austral, en las Laderas de Trabalomas.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante la suma ejecutora Darthalia en la Puerta Austral, en las Laderas de Trabalomas. ¡La maquinaria de guerra Renegada marcha hacia el frente, para conquistar Lordaeron en nombre de la Horda!$b$bPara llegar a la Puerta Austral debes seguir el camino hacia el sur, a través del Bosque de Argénteos, y girar al este para entrar en las Laderas de Trabalomas.$b$b¡Adelante, $ghermano:hermana;! ¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28090, 'esMX', 'Bienes preciosos', 'Recupera la piedra de puerta de la caravana Crepuscular. Los guardalanzas deberían tener las llaves que abren los cofres que contienen la piedra de puerta.', 'Las puertas que hay cañón abajo están cerradas. Nuestros exploradores han descubierto que sus caravanas llevan, metida en cofres, una especie de piedra que usan para abrir la puerta.$B$BVe allí y busca la llave del cofre en los cuerpos de los guardias. Cuando la encuentres, úsala en los cofres que hay en los vagones de las caravanas y tráeme la piedra de puerta.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Parche. Zona: Paso Faucedraco, Tierras Altas Crepusculares.', 0),
(28091, 'esMX', 'Blancos fáciles', 'Mata a 8 depositarios de lanzas Crepusculares.', 'La emboscada ha ido bien. La mayoría de los guardias están muertos, pero aún quedan algunos junto a los vagones.$B$BPuedes verlos al oeste de nuestra posición, abajo, en el cañón. Ve ahí y acaba con ellos para que podamos seguir con el ataque.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Parche. Zona: Paso Faucedraco, Tierras Altas Crepusculares.', 0),
(28092, 'esMX', 'Si la llave encaja', 'Lleva al escuadrón goblin a la Puerta Faucedraco cerrada.$B$BSi pierdes el escuadrón goblin, vuelve con el señor de la guerra Krogg para que te asigne uno nuevo.', 'Los dragones ya han llevado la batalla a los cielos sobre Grim Batol. Ahora depende de nosotros llevar a nuestros hombres por tierra y asegurar las puertas.$B$BQuiero que sepas lo que está en juego aquí, $c. De Grim Batol salen los refuerzos del Martillo Crepuscular hacia todas las Tierras Altas. Si no les cerramos el paso aquí, no ganaremos las batallas que nos quedan.$B$BEnviaré al escuadrón goblin contigo. Ve a la puerta del sudeste y ábrela. Parche te dará las instrucciones que necesites a partir de ahora.', '', 'Puerta Faucedraco abierta', '', '', '', '', '', '', '', 'Habla con: Parche. Zona: Recodo de Vermis, Tierras Altas Crepusculares.$B$BSi ya no estás con Parche, habla con: Señor de la guerra Krogg. Zona: Recodo de Vermis, Tierras Altas Crepusculares.', 0),
(28093, 'esMX', 'Haciendo presión', 'Lleva al escuadrón goblin más allá de la puerta norte Faucedraco hasta la entrada de Grim Batol.$B$BSi te separas del escuadrón goblin, vuelve con el señor de la guerra Krogg, en el Recodo de Vermis, para recibir órdenes.', 'Hemos hecho un buen trabajo hasta ahora. Deberíamos encontrar la entrada de Grim Batol justo detrás de la próxima puerta.$B$BMe ordenaron que asegurara la entrada y que les cerrara el paso a los refuerzos mientras el resto de nuestros hombres siguen avanzando por la ruta que hemos despejado en el cañón. Se me ocurre que si llegamos pronto, a lo mejor puedo dejar que Tictac se divierta un poco más.$B$BSigamos avanzando por el cañón hacia el sudoeste, deberíamos encontrar la siguiente puerta bastante rápido.', '', 'Entrada de Grim Batol asegurada', '', '', '', '', '', '', '', 'Habla con: Calen. Zona: Entrada de Grim Batol, Tierras Altas Crepusculares.', 0),
(28094, 'esMX', 'Preparando el camino', 'Mata a 30 adeptos del Martillo Crepuscular en el Recodo de Vermis mientras te abres camino hacia la entrada de Grim Batol.', 'Mis órdenes son acompañarte al sur, a través de las Puertas Faucedraco, hacia la entrada de Grim Batol. Tenemos que despejar el camino para que el resto de los hombres pueda seguirnos y asegurar la entrada.$B$BTraducción: mata todo lo que se mueva, y que no te dé vergüenza si lo encuentras divertido.$B$BLos chicos se están impacientando. Adelante.', '', 'Cultores del Recodo de Vermis asesinados', '', '', '', '', '', '', '', 'Habla con: Parche. Zona: Recodo de Vermis, Tierras Altas Crepusculares.$B$BSi ya no estás con Parche, habla con: Señor de la guerra Krogg. Zona: Recodo de Vermis, Tierras Altas Crepusculares.', 0),
(28096, 'esMX', 'Bienvenidos a la máquina', 'Asigna 3 misiones.', 'Acércate, $gamigo:querida;, toma un puro. Vas a llegar muy lejos como oficial de los Renegados. ¡Ya lo creo, esta es la buena vida y tú la vas a vivir!$b$bQuiero que cojas estas órdenes y se las entregues a los simples medianías que vengan a buscar trabajo. A quién le des el qué lo dejo enteramente a tu discreción.$b$bCuando estés $glisto:lista;, monta en mi fiel corcel esquelético (para que te vean bien) ¡y vive la vida! Es decir, quédate $gquieto:quieta; y espera.', '', 'Primera misión asignada', 'Segunda misión asignada', 'Tercera misión asignada', '', '', '', '', '', 'Vuelve con: Suma ejecutora Darthalia. Zona: Puerta Austral, Laderas de Trabalomas.', 0),
(28097, 'esMX', 'Las puertas de Grim Batol', 'Habla con el señor de la guerra Krogg en el Recodo de Vermis.', 'Krogg ha iniciado el ataque para avanzar por el cañón. Está justo tras la puerta que tenemos al sudeste.$B$BVoy a reunir al pelotón para que se una al ataque. Nos reuniremos contigo ahí abajo.', '', '', '', '', '', '', '', '', '', '', 0),
(28098, 'esMX', 'El maestro de vuelo Crepuscular', 'Ve volando con Cuorevaja hasta el Nidal Crepuscular y encárgate del maestro de vuelo Crepuscular Richtofen.', 'El maestro de vuelo Crepuscular Richtofen se encuentra en el Nidal Crepuscular, arriba y al sureste. Independientemente de lo que hagamos aquí abajo, si no nos encargamos de él no habrá esperanza para Nido Alto.$B$BAunque Cuorevaja está demasiado herido como para ayudarte en la lucha, al menos puede llevarte hasta allí. El resto depende de ti, $n.$B$BBuena suerte. ', '', 'Ve volando con Cuorevaja', 'Maestro de vuelo Crepuscular Richtofen eliminado', '', '', '', 'Richtofen', '', '', 'Vuelve con: Pao\'ka Monte Presto. Zona: Nido Alto, Las Mil Agujas.', 0),
(28099, 'esMX', 'Rasha\'krak', 'Consigue los brazales de vínculo de Rasha\'krak.', 'Según los informes que traes, creo que uno de los esbirros de ese "archiduque" ya haya puesto los ojos en el Puesto del Torio.$B$BSu nombre es Rasha\'krak, y patrulla por los charcos de lava que tenemos al sur. Se parece a los elementales de fuego latentes que hay por aquí, salvo por un pequeño detalle: los brazales de vínculo que lleva en las muñecas.$B$BEncuéntralo y tráeme esos brazales, $n. Necesito pruebas de que estamos en peligro antes de empezar una guerra contra elementales.', '', '', '', '', '', '', 'Rasha\'krak', '', '', 'Vuelve con: Sobrestante Puñaceite. Zona: Puesto del Torio, La Garganta de Fuego.', 0),
(28100, 'esMX', 'Un tótem que habla', 'Habla con el tótem de Ruumbo cerca de la aldea Muertobosque.', 'El poblado fúrbolg, al sur, es el hogar de la tribu Muertobosque, los peores enemigos de los Fauces de Madera. Son corruptos y mezquinos, como tantos otros llevados hasta la locura por la corrupción de estos bosques.$B$BSin embargo, ha ocurrido algo inusual cerca del poblado. Unos viajeros que venían hacia aquí han dicho que el tótem que hay junto al camino les ha hablado.$B$BYo no he oído nada cuando me he acercado. Puede vez te hable a ti, $n. Tal vez puedas hacerme el favor de descubrir qué está ocurriendo.', '', '', '', '', '', '', '', '', '', '', 0),
(28101, 'esMX', 'La orden de Mathias', 'Habla con Mathias Shaw en el Paso Faucedraco.', 'Los acontecimientos recientes han dejado aún más claro que esconderse aquí y lanzar ataques esporádicos contra Grim Batol no basta para mantener a salvo a los nuestros, y mucho menos para recuperar Grim Batol. Tenemos que ser más agresivos, tenemos que apuntar al corazón.$B$BHe aceptado enviar dragones para ayudar a tus comandantes. Ya estaban elaborando un plan para atacar Grim Batol, así que deberías empezar por ahí.$B$BMathias Shaw debería estar en el Paso Faucedraco, en el cañón que hay debajo de nosotros, hacia el sur.', '', '', '', '', '', '', '', '', '', '', 0),
(28102, 'esMX', 'Enfréntate al poder', 'Mata a 8 pícaros Fuego de Jade o acechasombras Fuego de Jade en las Ruinas de Constellas.', '¡Ha llegado la hora de la última ofensiva contra los Fuego de Jade!$B$BSi estás $glisto:lista; para atravesar su asquerosa barrera y llevar la lucha hasta su líder, te pediré también que nos ayudes con los sátiros inferiores. Nuestros druidas luchan ferozmente, pero tu fuerza puede hacer que cambien las tornas.$B$B¡Demuestra a los Fuego de Jade que estas tierras ya no estarán sometidas a su poder!', '', 'Pícaro Fuego de Jade o acechasombras Fuego de Jade asesinado', '', '', '', '', '', '', '', 'Vuelve con: Eridan Vientoazul. Zona: Ruina de Constellas, Frondavil.', 0),
(28103, 'esMX', 'Blancos fáciles', 'Mata a 8 depositarios de lanzas Crepusculares.', 'La emboscada ha ido bien. La mayoría de los guardias están muertos, pero aún quedan algunos junto a los vagones.$B$BVe ahí y acaba con ellos para que podamos seguir avanzando por el cañón.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Maestro Mathias Shaw. Zona: Paso Faucedraco, Tierras Altas Crepusculares.', 0),
(28104, 'esMX', 'Bienes preciosos', 'Recupera la piedra de puerta de la caravana Crepuscular. Los guardalanzas deberían tener las llaves que abren los cofres que contienen la piedra de puerta.', 'Las puertas que hay cañón abajo están cerradas. Nuestros exploradores descubrieron que sus caravanas llevan, metida en cofres, una piedra que usaron para abrir la puerta.$B$BVe allí y busca la llave del cofre en los cuerpos de los guardias. Cuando la encuentres, úsala en los cofres que hay en los vagones de las caravanas y tráeme la piedra de puerta.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Maestro Mathias Shaw. Zona: Paso Faucedraco, Tierras Altas Crepusculares.', 0),
(28105, 'esMX', 'Kavem el Inconmovible', 'Consigue la llave Neferset de Kavem el Inconmovible.', 'Kavem ya era bastante cruel antes de que los Neferset se aliasen con Alamuerte. Ahora su placer por causar dolor roza lo macabro.$B$BÉl es el que tiene las llaves de nuestros grilletes.$B$BSe encuentra en el edificio que está a nuestro lado, a mi derecha.$B$BEncuéntralo y quítale la llave. No dudes ni le demuestres compasión. Él te cortará el cuello sin pensarlo siquiera.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Príncipe Nadun. Zona: Ciudad Perdida de los Tol\'vir, Uldum.', 0),
(28106, 'esMX', 'La puertas de Grim Batol', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28107, 'esMX', 'Preparando el camino', 'Mata a 30 adeptos del Martillo Crepuscular en el Recodo de Vermis mientras te abres camino hacia la entrada de Grim Batol.', 'Mis órdenes son acompañarte al sur, a través de las Puertas Faucedraco, hacia la entrada de Grim Batol. Tenemos que despejar el camino para que el resto de los hombres pueda seguirnos y asegurar la entrada.$B$BTraducción: mata todo lo que se mueva, y que no te dé vergüenza si lo encuentras divertido.$B$BLos chicos se están impacientando. Adelante.', '', 'Cultores del Recodo de Vermis asesinados', '', '', '', '', '', '', '', 'Habla con: Teniente de Bancalto. Zona: Recodo de Vermis, Tierras Altas Crepusculares.$B$BSi ya no estás con tu escuadrón, habla con el maestro Mathias Shaw en el Recodo de Vermis, Tierras Altas Crepusculares.', 0),
(28108, 'esMX', 'Si la llave encaja', 'Lleva al escuadrón de Bancalto a la Puerta Faucedraco cerrada.$B$BSi pierdes tu escuadrón, vuelve con el maestro Mathias Shaw para que te asigne uno nuevo.', 'Los dragones ya han llevado la batalla a los cielos sobre Grim Batol. Ahora depende de nosotros llevar a nuestros hombres por tierra y asegurar las puertas.$B$BQuiero que sepas lo que está en juego aquí, $c. De Grim Batol salen los refuerzos del Martillo Crepuscular hacia todas las Tierras Altas. Si no les cerramos el paso aquí, no ganaremos las batallas que nos quedan.$B$BEnviaré a un escuadrón de Bancalto contigo. Ve a la puerta del sudeste y ábrela. Tu teniente te dará las instrucciones que necesites a partir de ahora.', '', 'Puerta Faucedraco abierta', '', '', '', '', '', '', '', 'Habla con: Teniente de Bancalto. Zona: Recodo de Vermis, Tierras Altas Crepusculares.$B$BSi ya no estás con tu escuadrón, habla con: Maestro Mathias Shaw. Zona: Recodo de Vermis, Tierras Altas Crepusculares.', 0),
(28111, 'esMX', 'Problemas en Mina Azur', 'Preséntate ante el capitán Keyton en la Mina Azur, en las Laderas de Trabalomas.', 'La productividad de nuestra granja de arañas en la Mina Azur está bajo mínimos. El capitán Keyton ha solicitado que le enviemos ayuda inmediatamente. Keyton afirma que las arañas de la mina rechazan las órdenes y campan a sus anchas. Por si fuera poco, un grupo de múrlocs costeros están asaltando nuestros suministros. Quiero que bajes hasta allí y eches un vistazo. Ayuda a Keyton y a la cuidadora de arañas, $n.$b$bEncontrarás la Mina Azur al sureste, cerca de la costa.', '', '', '', '', '', '', '', '', '', '', 0),
(28112, 'esMX', 'Huida de la Ciudad Perdida', 'Libera al príncipe Nadun y habla con el rey Phaoris en Ramkahen, en Uldum.', '¡Todo está listo! Desencadéname y libera a tus amigos.$B$B¡Tenemos que ser rápidos y actuar antes de que la basura Neferset se dé cuenta de que tramamos algo!$B$BSi lo consigues, ve a ver a mi hermano, el rey Phaoris, para que te recompense.', '', '', '', '', '', '', '', '', '', '', 0),
(28113, 'esMX', 'Rompe lo irrompible', 'Mata a Xavathras.', 'Con la Garra, estamos listos para derribar las defensas de los Fuego de Jade.$B$BVe a las ruinas del noroeste. Más allá del frente de los sátiros encontrarás un paso estrecho que lleva a su Poza de la Luna corrupta. El camino está bloqueado por una muralla enorme de llamas demoníacas, pero la Zarpa de Tichondrius debería poder encargarse de ella.$B$BTras la barrera encontrarás al líder de las fuerzas, Xavathras, guardando la Poza de la Luna corrupta. ¡Mátalo una vez que hayas pasado!', '', '', '', '', '', '', 'Xavathras', '', '', 'Vuelve con: Arcanista Delaris. Zona: Ruinas de Constellas, Frondavil.', 0),
(28114, 'esMX', 'Cosecha gloriosa', 'Reúne 60 huevos de trepador.', 'Justo al sur de la Puerta Austral encontrarás nuestras operaciones de domesticación de arañas. Con los años hemos desarrollado cierta afinidad con las arañas de Trabalomas y hemos conseguido domesticar y criar a estos bichitos tan adorables. ¡Ahora las arañas nos sirven como mascotas domésticas normales y como bestias de batalla! ¡Qué criaturas tan versátiles!$b$bQuiero que entres en los campos que hay al sureste y recolectes los huevos que se han estado incubando en los osos. Entrégale la cosecha a Sarus, en la mina.', '', '', '', '', '', '', '', '', '', 'Entrégale los huevos de trepador a la cuidadora de arañas Sarus en Mina Azur, en las Laderas de Trabalomas.', 0),
(28115, 'esMX', 'Más de la cuenta', 'Mata 8 osos infestados.', 'Los osos son bestias desalmadas que existen para atormentarnos. ¡Solo gracias al ingenio Renegado hemos conseguido sacar provecho a los osos! Utilizamos osos en nuestras granjas de arañas como comederos de huevos vivientes. Nuestras arañas ponen sus huevos en el cuerpo de los osos y los huevos se alimentan de la carne y de la sangre de las bestias.$b$bCuando ya han cumplido su cometido, es necesario ejecutar a esos monstruos. Viaja al sureste y mata a los osos infectados que ya han vivido más de la cuenta.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Cuidadora de arañas Sarus. Zona: Mina Azur, Laderas de Trabalomas.', 0),
(28116, 'esMX', 'Violeta sollozante', 'Recoge 8 violetas sollozantes.', 'Debemos prepararnos cuidadosamente antes de atacar Jaedenar. La magia de los brujos y de los demonios de Jaedenar es fuerte, así que tendremos que tener listas nuestras propias defensas antes de entrar.$B$BSolo necesitamos un ingrediente más: violeta sollozante, que crece en las colinas cercanas a la fortaleza del enemigo, al noroeste.$B$BRecoge la violeta sollozante, y después reúnete con mi ayudante en el campo. Él sabrá qué hacer después.', '', '', '', '', '', '', '', '', '', 'Entrega la violeta sollozante a Andalar Vallesombrío en Jaedenar, en Frondavil.', 0),
(28117, 'esMX', 'Limpiando las profundidades', 'Te han pedido que mates a 9 fantasmas de cualquier tipo en las Profundidades Malditas, al este del Bastión de Baradin.', 'Me alegro de verte, $n. Ahora que nos hemos hecho con Tol Barad, la batalla acaba de comenzar.$B$BHemos descubierto un módulo al este de aquí que necesitamos que limpies. Por lo visto está plagado de fantasmas que llevan encerrados allí abajo ni se sabe el tiempo.$b$bLimpia la zona todo lo que puedas y preséntate de nuevo ante mí cuando termines.', '', 'Fantasmas asesinados', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Stevens en el Bastión de Baradin cuando termines.', 0),
(28118, 'esMX', 'El archimago prisionero', 'Tienes que matar al archimago Galus y volver con su báculo de las Profundidades Malditas, al este del Bastión de Baradin.', 'Desde que llegamos a Tol Barad hemos estado intentando limpiar los módulos de las Profundidades Malditas. Parece que cada vez que nos acercamos, aparece ese archimago y nos obliga a retroceder.$B$BAhora que nos hemos hecho con la isla, ha llegado el momento de intentarlo de nuevo. Dirígete hasta allí y tráeme su báculo como prueba de que has terminado el trabajo.', '', '', '', '', '', '', 'Archimago Galus', '', '', 'Preséntate de nuevo ante el comandante Stevens en el Bastión de Baradin cuando termines.', 0),
(28119, 'esMX', 'Pureza de la Corrupción', 'Llena la cantimplora vacía con agua de la Poza de la Luna corrupta, en el centro de Jaedenar.', 'Las flores que me trajiste eran el ingrediente esencial.$B$BLa Guarida Sombría está rodeada de barreras protectoras, proyectadas desde blandones demoníacos. Si queremos expulsar al Consejo de la Sombra de Frondavil, tenemos que extinguir esos blandones.$B$BEste vial ha sido imbuido de violeta sollozante y magia de la naturaleza. Llénalo en la Poza de la Luna corrupta, en el centro de Jaedenar y vuelve a verme.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Andalar Vallesombrío. Zona: Jaedenar, Frondavil.', 0),
(28120, 'esMX', 'Aprender del pasado', 'Te han pedido que recuperes cuatro diarios de prisión polvorientos de las Profundidades Malditas, al este del Bastión de Baradin.', 'Ahora que por fin dominamos esta isla destartalada, podremos investigar cómo acabó en este estado. Algunas de nuestras tropas han descubierto diarios alrededor de la entrada del módulo de las Profundidades Malditas, al este de aquí.$B$BEstos diarios son especialmente interesantes para nuestros ancianos escribas en el campamento. Necesito que recuperes cuatro de ellos y que me los traigas lo antes posible.$B$BTen cuidado ahí abajo, $n, ese lugar está plagado de no-muertos.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Stevens en el Bastión de Baradin cuando termines.', 0),
(28121, 'esMX', 'Las fuerzas de Jaedenar', 'Mata a 12 efectivos Jaedenar.', 'El Consejo de la Sombra sigue adelante con la corrupción de estas tierras. En Jaedenar, al noroeste, adoran a los demonios de la Legión Ardiente y trabajan para abrir el camino que traiga a sus amos de vuelta a este mundo.$B$BEl territorio lo patrullan canes, guardianes, adeptos y cultores Jaedenar; matones que actúan como vigías para las fuerzas aún más viles que tienen debajo. ¡Serán los primeros en morir para que estos bosques no sufran más!', '', 'Efectivos Jaedenar asesinados', '', '', '', '', '', '', '', 'Encuéntrate con Andalar Vallesombrío en Jaedenar, Frondavil.', 0),
(28122, 'esMX', 'Un problema enorme', 'Te han pedido que mates a Problim, un ettin gigante que merodea por los caminos de Tol Barad.', '¡Por fin nos hacemos con esa maldita roca y ahora descubrimos que hay un enorme ettin merodeando por ella y aniquilando a nuestras patrullas de centinelas!$B$B$n, necesito que reúnas a unos cuantos amigos y que acabes con ese ettin. No podemos permitir que una bestia como esa merodee a sus anchas causando el caos.$B$BPermanece alerta, los informes del frente indican que lleva un árbol enorme a modo de arma, y no dudará en utilizarlo.', '', '', '', '', '', '', 'Problim', '', '', 'Preséntate de nuevo ante el sargento Parker en el Bastión de Baradin cuando termines.', 0),
(28123, 'esMX', 'La cadena del Demonio', 'Consigue la cadena del Demonio.', 'Narkrall me ha revelado el secreto de su influencia sobre los dracos de esta zona. Creía que la cadena del Demonio era un mito, pero la ha tenido todo este tiempo.$B$B¡Y ahora el muy idiota está a punto de perderla!$B$BSu vida no significa nada para mí, pero los Faucedraco no pueden permitirse perder ese artefacto. Síguelo al norte, hasta Bramal. La ciudad estará sumida en el caos, así que tal vez puedas aterrizar sin que nadie se dé cuenta. Tráeme la cadena del Demonio, aunque tengas que cogerla del cadáver de Narkrall.$B$B¡Encuentra el artefacto, $n!', '', '', '', '', '', '', '', '', '', 'Lleva la cadena del Demonio a: Zaela. Zona: Garganta de Sangre, Tierras Altas Crepusculares.', 0),
(28124, 'esMX', 'Hacia El Baluarte', 'Habla con Lakota Son del Viento en el Baluarte Crepuscular, en Las Mil Agujas.', '$n, mientras tú y los lechigados se encargaban del maestro del cielo, vino Lakota Son del Viento. Me pidió que te pidiera reunirte con ella al este del Baluarte Crespucular.$b$bDebería estar allí donde retienen a Magatha Tótem Siniestro.', '', '', '', '', '', '', '', '', '', '', 0),
(28125, 'esMX', 'Algo que ponerse', 'Reúne 10 piezas de armadura del Martillo Crepuscular.', 'Se me ha ocurrido una idea para que te acerques a sus líderes sin que te maten. Pero antes vas a tener que buscarte algo que ponerte.$b$bTe sugiero que vayas y les quites su armadura.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lakota Son del Viento. Zona: Baluarte Crepuscular, Las Mil Agujas.', 0),
(28126, 'esMX', 'Sofocar las llamas de protección', 'Usa el agua de la Poza de la Luna purificada para extinguir los cuatro blandones de protección en la Guarida Sombría.', 'Hay blandones por toda la Guarida Sombría.$B$BEntra en el túnel que lleva a la Guarida Sombría y sigue los pasadizos subterráneos. Extingue las llamas de todos los blandones y las protecciones que ha colocado el Consejo caerán, al menos durante un corto periodo de tiempo.', '', 'Extingue el Blandón del Dolor', 'Extingue el Blandón de la Maldad', 'Extingue el Blandón del Sufrimiento', 'Extingue el Blandón del Odio', '', '', '', '', 'Vuelve con: Greta Pezuñamusgo. Zona: Alto de Corazón Salvaje, Frondavil.', 0),
(28127, 'esMX', 'Libéralos', 'Rescata a 5 prisioneros del Baluarte de los carceleros Crepusculares.', 'Magatha no es la única prisionera del Martillo Crepuscular.$b$bCuando vayas por el sur, aprovecha para liberar a tantos como puedas.', '', 'Prisioneros del Baluarte liberados', '', '', '', '', '', '', '', 'Vuelve con: Lakota Son del Viento. Zona: Baluarte Crepuscular, Las Mil Agujas.', 0),
(28128, 'esMX', 'El círculo interno', 'Mata a 12 defensores en el interior de la Guarida Sombría.', 'Ahora que ya no hay centinelas, los siguientes serán los miembros más importantes del Consejo de la Sombra.$B$BEn las profundidades de los túmulos encontrarás a poderosos brujos, cazadores, déspotas, tejeoscuros y legionarios Jaedenar.$B$B¡Deben ser derrotados si queremos salvar estas tierras!', '', 'Defensores de la Guarida Sombría asesinados', '', '', '', '', '', '', '', 'Vuelve con: Jessir Arcolunar. Zona: Alto de Corazón, Frondavil.', 0),
(28129, 'esMX', 'El príncipe demonio', 'Mata al príncipe Xavalis.', 'Los sátiros Fuego de Jade, que han ocupado tanto territorio en Frondavil, trabajan directamente con el Consejo de la Sombra.$B$BEsos sátiros están directamente bajo las órdenes del antiguo y poderoso príncipe Xavalis. Algunos dicen que es el hijo de Xavius, el primer sátiro, bendecido por el mismísimo Sargeras.$B$BSea cual sea su naturaleza, debe morir si queremos dispersar a los Fuego de Jade y reclamar nuestros túmulos. Adéntrate en la Guarida Sombría y mátalo. No tengas piedad; él no la tendrá.', '', '', '', '', '', '', 'Príncipe Xavalis', '¡La Legión será expulsada de las profundidades!', 'Andalar Vallesombrío', '', 0),
(28130, 'esMX', 'Un pueblo poco amistoso', 'El comandante Marcus Johnson te ha pedido que mates a 14 aldeanos en Aldea Monrojo. Aldea Monrojo se encuentra al norte del campamento, en la parte de la derecha.', '¿Has estado ya en la Aldea Monrojo, $n? Te recomiendo que lleves una hoja bien afilada si vas para allá.$b$bLos habitantes de la aldea parecen normales, pero algo sospechoso se cuece por allí. Hemos recibido informes de que acaban con nuestros soldados a diestro y siniestro. Ya lo hemos tolerado bastante tiempo, así que necesito que vayas para allá y que hagas un poco de limpieza.$B$BAcaba con todos los que puedas y preséntate ante mí cuando acabes.', '', 'Residentes de Aldea Monrojo', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Marcus en el Campamento de Baradin cuando termines.', 0),
(28131, 'esMX', 'Tentadoras gemelas', 'Mata a Moora y a Salia.', 'Moora y Salia son las sirvientes personales del Señor de las Sombras Fel\'dan. ¡No dejes que te engañen!$B$BEsos asquerosos súcubos usan sus tretas y su repugnante magia para atraer a los mortales a las profundidades de la Guarida Sombría. Los que caen entre sus garras sufren un lavado de cerebro o los sacrifica Fel\'dan a sus maestros demoníacos.$B$BLas dos luchan como una sola y nunca se separan, lo que las convierte en una amenaza considerable. Adéntrate en la Guarida Sombría y mátalas.', '', '', '', '', '', '', 'Moora y Salia', '¡Fel\'dan caerá!', 'Andalar Vallesombrío', '', 0),
(28132, 'esMX', 'Excavaciones fructíferas', 'Lleva \'Excavaciones fructíferas\' a Belloc Hoja Brillante en el Embarcadero de Schnottz.', 'Este manual describe teorías descabelladas sobre cómo gestionar de la forma más eficaz a grandes grupos de trabajadores en proyectos de excavación masivos.$b$bTras echar un rápido vistazo al material, te resulta evidente que el autor de este libro es el encargado de estos saqueadores tremendamente agresivos.$b$bUn mapa en la contraportada indica que el autor tiene un búnker en la parte suroeste de Uldum.$B$BTal vez deberías presentarte.', '', '', '', '', '', '', 'Schnottz', '', '', '', 0),
(28133, 'esMX', 'Furia desatada', 'Viaja a La Garganta y habla con Zaela. Mata a Torth.', 'El draco de Narkrall, Torth, sobrevivió al ataque fallido contra Bramal y ahora la criatura se ha liberado de su antiguo dueño.$B$BTorth quiere vengarse de los Faucedraco y ya arrasó Garganta de Sangre una vez. Seguirá volviendo hasta que lo destruyamos de una vez por todas. Ha llegado la hora de usar la cadena del Demonio.$B$BEl antiguo nido de Torth es una pequeña caverna en las colinas, al oeste, que hemos convertido en un pequeño campamento llamado "La Garganta."$B$BReúnete conmigo en La Garganta y acabaremos con Torth.', '', '', '', '', '', '', 'Torth el Voraz', '', '', 'Habla con Zaela, en La Garganta, Tierras Altas Crepusculares. ', 0),
(28134, 'esMX', 'Castigo inminente', 'Habla con el nomarca Teneth en las Tierras de Tahret, con el sacerdote del Sol Asaris en el Sello del Rey Sol y con Asaq en Mar\'at.', 'Ahora que has recibido una recompensa adecuada, espero poder hablar contigo sinceramente.$B$BHas hecho un gran favor a mi reino, pero también has desequilibrado un frágil proceso de paz.$B$BYo trataba de conseguir la liberación de mi hermano por medios estrictamente diplomáticos para evitar el derramamiento de sangre.$B$BAhora no cabe duda de que el enemigo buscará venganza.$B$BHabla con el nomarca Teneth en las Tierras de Tahret, al este de aquí; con el sacerdote del Sol Asaris en el Sello del Rey Sol, al norte de aquí; y con Asaq en Mar\'at, al oeste de aquí. Averigua dónde golpeará el enemigo.', '', 'Habla con el nomarca Teneth', 'Habla con el sacerdote del Sol Asaris', 'Habla con Asaq', '', '', '', '', '', 'Vuelve con: Rey Phaoris. Zona: Ramkahen, Uldum.', 0),
(28135, 'esMX', 'La venganza de Al\'Akir', 'Habla con el príncipe Nadun, en el Puesto Comercial de Arsad, en las afueras de Mar\'at, en Uldum.  ', 'Escucha, $n. Lo que asoló Orsis no fue una tormenta de arena natural. Fueron los esbirros de Al\'Akir.$B$BEl señor elemental del aire es un firme aliado de Alamuerte y era tan solo cuestión de tiempo que lanzase a sus súbditos contra mi pueblo.$B$BEl ataque de Orsis ha sido una advertencia para nosotros. Tenemos que movernos con rapidez para ofrecer a nuestros hermanos la ayuda que podamos proporcionarles.$B$BReúnete con Nadun en el Puesto Comercial de Arsad al exterior de Mar\'at. Yo comenzaré los preparativos para hacernos cargo de los desplazados y de los heridos.', '', '', '', '', '', '', '', '', '', '', 0),
(28136, 'esMX', '¡Detrás de ti!', 'Asesina al maestro de códigos Deethuk, al comandante Mechaveloz y al elementalista Starion.', 'Los tres líderes de El Baluarte son poderosos y no debes subestimarlos, $n. Afortunadamente para nosotros, ahora tienes un disfraz para hacerte pasar por uno de los cultores del Martillo Crepuscular.$b$bDeberías ponértelo y hablar a solas con el maestro de códigos Deethuk, el comandante Mechaveloz y el elementalista Starion. Arréglatelas para que te den la espalda, ¡y entonces ataca de inmediato!', '', 'Maestro de códigos Deethuk asesinado', 'Comandante Mechaveloz asesinado', 'Elementalista Starion asesinado', '', '', '', '', '', 'Vuelve con: Lakota Son del Viento. Zona: Baluarte Crepuscular, Las Mil Agujas.', 0),
(28137, 'esMX', 'Enseña a un hombre a pescar... o a robar', 'Tienes que robar 22 lubinas de Monrojo. Encontrarás los pescados en redes en el embarcadero, en la parte trasera de la aldea. La Aldea Monrojo se encuentra al norte del campamento, a la derecha.', 'Aldea Monrojo: ese lugar es una maldición y una bendición para nosotros, $n. No sé dónde aprenderían los bandidos a pescar tan bien como lo hacen, pero ahora no tengo tiempo de preocuparme de eso.$B$BNecesito que vayas hasta allí y que robes todas las reservas de pescado que puedas. Desde que recuperamos la isla estamos viviendo de las sobras; y esta es nuestra única opción de conseguir reservas de comida sólida.$B$BTen cuidado con los sigilosos de ahí arriba, tenemos informes de que siguen en el interior de las murallas de la aldea.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Marcus Johnson en el Campamento de Baradin cuando termines.', 0),
(28138, 'esMX', 'Infestación humana', 'Captura 8 humanos de Trabalomas.', 'Esta mina era el núcleo de las operaciones mineras de la Alianza en Trabalomas. Ahora hace las veces de criadero para nuestras leales arañas, aunque los humanos aún la habitan... Por decirlo de alguna forma.$b$b<Keyton sonríe.>$b$b¡Pero vamos al grano! El celador Aguaserena ha pedido más trabajadores para los Campos de Lodo. Quiero que entres en la mina con estos grilletes y captures a los humanos de Trabalomas para que realicen trabajos forzados en los campos.$b$bSácalos de la telaraña que los paraliza y somételos a golpes antes de utilizar los grilletes.', '', 'Humano de Trabalomas capturado', '', '', '', '', '', '', '', 'Vuelve con: Capitán Keyton. Zona: Mina Azur, Laderas de Trabalomas.', 0),
(28139, 'esMX', 'Código del maestro de códigos', 'Hazte con el código del maestro de códigos.', '$n, las ataduras que encadenan a Magatha tienen un código concreto. Solo podremos liberarla si obtenemos dicho código.$b$bHay un dispositivo cerca del maestro de códigos Deethuk en El Baluarte, al sureste, que contiene los códigos.$b$bConsíguelos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lakota Son del Viento. Zona: Baluarte Crepuscular, Las Mil Agujas.', 0),
(28140, 'esMX', 'La bruja anciana', 'Inutiliza el controlador de vínculos de Magatha.', 'Ya tienes el código. Ahora solo tienes que dirigirte al sector este de El Baluarte y liberar a la bruja anciana.$b$bBuena suerte, $n. Gracias por todo lo que has hecho.', '', 'Controlador inutilizado', '', '', '', '', '', '', '', '', 0),
(28141, 'esMX', 'Reliquias del Rey del Sol', 'Consigue 4 reliquias del Rey del Sol.', 'El Sello del Rey Sol es un mecanismo de defensa para Ramkahen.$B$BCuando la barrera que rodeaba Uldum cayó, comenzamos a avistar escoltas Vagayermos de Tanaris que se filtraban por nuestras fronteras.$B$BAtacaron este lugar sagrado de camino al oeste y lo robaron en busca de las reliquias que en otro tiempo les proporcionaron poder.$B$BRecupera las reliquias para nosotros. Sin ellas no podremos defendernos contra los ataques del desierto.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Sacerdote del Sol Asaris. Zona: Uldum.', 0),
(28142, 'esMX', 'Al Quebranto', 'Habla con Magatha Tótem Siniestro en el Quebranto Crepuscular, en Las Mil Agujas.', 'Según Magatha, te espera justo al borde del Quebranto Crepuscular, al este.', '', '', '', '', '', '', '', '', '', '', 0),
(28144, 'esMX', '¡Pequeños monstruos ladrones!', 'Recupera 6 "suministros" del campamento Renegado.', 'La gran longitud de costa que se extiende de oeste a este, directamente al sur de nuestra posición, se conoce como la Playa del Oeste. Allí encontrarás dos cosas: múrlocs y nuestros "suministros" robados.$b$b<Keyton levanta las manos y hace signos de comillas con los dedos.>$b$bEsos malditos múrlocs ladrones nos atacaron por la espalda y se llevaron nuestros "suministros".$b$bNi Sarus ni yo podemos abandonar nuestros puestos. ¡Necesitamos que vayas a la Playa del Oeste a recuperar los "suministros"!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Capitán Keyton. Zona: Mina Azur, Laderas de Trabalomas.', 0),
(28145, 'esMX', 'Antídoto Sangreveneno', 'Rellena el vial de antídoto con el veneno de 8 cadáveres de escórpidos Sangreveneno.', 'Iset trató de defender este territorio sagrado cuando los bandidos Vagayermos lo saquearon.$B$BParece que utilizaron la potente toxina presente en los escórpidos Sangreveneno.$B$BCoge este vial y recoge el veneno de los cadáveres para que pueda generar un antídoto. Temo que Iset no tenga demasiado tiempo.', '', 'Escórpido Sangreveneno drenado', '', '', '', '', '', '', '', 'Vuelve con: Sacerdote del Sol Asaris. Zona: Sello del Rey Sol, Uldum.', 0),
(28146, 'esMX', '¡Delicias costeras!', 'Alimenta al trepador de mina hambriento con 12 múrlocs de la Playa del Oeste.', '¡Mis arañas están hambrientas e inquietas! Hace días que no comen y están empezando a atracarse con nuestros prisioneros humanos. No podemos permitirlo. Esos humanos nos hacen falta para los Campos de Lodo.$b$bQuiero que te lleves a una de mis arañas de mina hambrientas y que la alimentes con múrlocs de la Playa del Oeste, al sur de aquí. ¡Lo que tú mates, ella se lo comerá! ¡Cuantos más mejor!', '', 'Múrlocs entregados al trepador de mina hambriento', '', '', '', '', '', '', '', 'Preséntate ante: Cuidadora de arañas Sarus. Zona: Mina Azur, Laderas de Trabalomas.', 0),
(28147, 'esMX', 'El púrpura es tu color', 'Reúne 8 jirones de prendas Crepusculares.', 'Por lo que yo sé, los ogros Tripal que hay frente a esta caverna no se han unido todavía al Martillo Crepuscular. Si somos listos, podemos volver a los dos grupos uno contra otro.$B$BProbemos un pequeño truco que aprendí en Silithus. Primero tendremos que conseguir un conjunto de togas de cultor para ti.$B$BDirígete al sur de aquí y mata a algunos urdevientos Crepusculares en la Brecha Crepuscular. Aparte de interrumpir lo que quiera que estén haciendo, te dará la oportunidad de conseguir jirones de prendas Crepusculares.', '', '', '', '', '', '', '', '', '', 'Llévale los jirones a: Putreceño. Zona: La Garganta, Tierras Altas Crepusculares.', 0),
(28148, 'esMX', 'Sacrificando a los corruptos', 'Consigue 10 pelambres corruptas de oso Zarpira o de lobo Zarpayel.', 'La enfermiza corrupción demoníaca se ha adueñado de este bosque. El suelo, los árboles, los animales... todo absorbe la magia vil.$B$BNosotros, el Círculo Esmeralda hemos jurado purificar este bosque, lo que requiere una lucha constante. Aunque hay vida que todavía puede ser sanada, los osos y los lobos que andan cerca han llegado a un punto sin retorno.$B$BDebemos poner fin a su sufrimiento y asegurarnos de que sus cuerpos no propaguen aún más la corrupción. Caza a los osos y a los lobos y tráeme sus pellejos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Taronn Plumarroja. Zona: Santuario Esmeralda, Frondavil.', 0),
(28149, 'esMX', 'Susurros en el viento', 'Consigue un talismán de hablavientos y 5 alientos de vórtice.', '¿Las oyes, $c? Las voces de la caveh\'na. Quieren hablar, pero no tienen aliento.$B$BBuh\'quemos la forma de eh\'cuchar. Los Mah\'tillo Salvaje, ellos hablan con el viento. Ve a la Brecha Crepuh\'cular, al sur de aquí, y coge el talismán de hablavientos del campamento. Estará encima de un pilar de piedra.$B$B¡También necesitaremos el aliento de los elementales! Mata a vóh\'tices de tormenta y coge lo que necesites.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Buunu. Zona: La Garganta, Tierras Altas Crepusculares.', 0),
(28150, 'esMX', 'Un aliado arcano', 'Habla con la arcanista Delaris en las Ruinas de Constellas.', 'El Círculo Esmeralda ha jurado aceptar la ayuda de todos los que quieran luchar contra los demonios de Frondavil. Aunque mi gente siempre ha despreciado lo arcano, aquí no podemos permitirnos prescindir de semejante ventaja.$B$BLa arcanista Delaris, una maga Altonata superviviente, nos ayuda a luchar contra el sátiro Fuego de Jade. Sigue el camino hacia el norte y la encontrarás en nuestro campamento, por encima de las Ruinas de Constellas.$B$BSi quieres ayudar a purificar Frondavil, sigue sus indicaciones como has seguido las mías.', '', '', '', '', '', '', '', '', '', '', 0),
(28151, 'esMX', 'Un disfraz para matar', 'Mata a 10 ogros Tripal. Tu disfraz de Martillo Crepuscular se aplicará automáticamente mientras estés dentro de Foso Tripal. ', 'Tu disfraz está listo, $n. Ahora cuando vayas al norte, a Foso Tripal, tu traje del Martillo Crepuscular engañará a los ogros.$B$BEl resto del plan es simple: matas a un puñado de ogros Tripal y ellos culpan al culto. ¿Estás $glisto:lista; para sembrar el caos en el campamento ogro? Eso pensaba.', '', 'Ogros Tripal asesinados', '', '', '', '', '', '', '', 'Vuelve con: Putreceño. Zona: La Garganta, Tierras Altas Crepusculares.', 0),
(28152, 'esMX', 'Jaedenar espera', 'Entrega las hierbas de arcanista a Greta Pezuñamusgo en Alto de Corazón Salvaje.', 'Los cultores que viste guardando la Zarpa eran miembros del Consejo de la Sombra, unos brujos desdeñables que están detrás de casi todos los intentos de traer demonios a Azeroth.$B$BAl norte está Jaedenar, llamada así en honor de Kil\'jaeden. En sus profundidades se encuentra la Guarida Sombría, un antiguo túmulo y la fortaleza del Consejo de la Sombra en Azeroth.$B$BLleva estas hierbas al norte, a Alto Corazón Salvaje, en el lado este del camino. Greta Pezuñamusgo las necesitará para su plan de purificar la Guarida Sombría de una buena vez.', '', '', '', '', '', '', '', '', '', '', 0),
(28153, 'esMX', 'Señor de las Sombras Fel\'dan', 'Mata al Señor de las Sombras Fel\'dan.', 'El Señor de las Sombras Fel\'dan espera en las profundidades, $n.$B$BSu ira no conocerá límites ahora que has matado a sus amadas mascotas. Incluso sin Moora y Salia, es una fuerza terrible a la que enfrentarse.$B$BTen cuidado con sus poderes oscuros; a estas alturas ya casi es más demonio que orco.', '', '', '', '', '', '', 'Fel\'dan', 'Ya casi ha concluido nuestra misión. Reclamaremos la Guarida Sombría.', 'Andalar Vallesombrío', '', 0),
(28154, 'esMX', 'La aleta de Branquimugre o algo así...', 'Entrégale la aleta de Branquimugre al capitán Keyton en Mina Azur, en las Laderas de Trabalomas.', 'Esto parece ser la aleta de Branquimugre o algo así... A lo mejor hay alguien a quien le importe que hayas matado a ese múrloc en el campamento de Mina Azur. Seguramente no, pero merece la pena probar.$b$bLlévale la cola de Branquimugre o lo que sea eso al capitán Keyton en Mina Azur, en la zona suroeste de Trabalomas.', '', '', '', '', '', '', '', '', '', '', 0),
(28155, 'esMX', 'Lord Pesadilla', 'Mata a Lord Pesadilla.', 'Ahora solo queda un último poder acechando en las profundidades de la Guarida Sombría: Lord Pesadilla.$B$BEl Consejo de la Sombra complace todos sus caprichos e incluso Fel\'dan era un mero instrumento que le permitía preparar esta tierra para otra invasión de la Legión Ardiente.$B$BProcede con cuidado, $n. Un Señor del Terror es un enemigo temible. ¡Mantente firme y triunfa!', '', '', '', '', '', '', 'Lord Pesadilla', '', '', 'Vuelve con: Farlus Corazón Salvaje. Zona: Alto de Corazón Salvaje, Frondavil.', 0),
(28156, 'esMX', 'Rescate en la mina', '¡Lleva a Dumass a un lugar seguro!', '<Oyes a Dumass a través de la telaraña.>$b$b¡HOLA! ¡ARAÑAS POR TODAS PARTES! ¡EL CAPITÁN ENVIARME PARA SALVAR EL MUNDO Y CAPTURAR HUMANOS! ¿QUÉ SER ESTE SITIO? ¡QUÉ CALOR! YO...$b$b<Dumass habla sobre su situación sin cesar.>$b$bA lo mejor deberías liberarlo y sacarlo a la superficie. También puedes dejarlo donde está, aunque sea culpa tuya que se haya quedado atrapado en esta mina.', '¡Lleva a Dumass a un lugar seguro!', '', '', '', '', '¡Lleva a Dumass a un lugar seguro!', '', '', '', 'Vuelve con: Capitán Keyton. Zona: Mina Azur, Laderas de Trabalomas.', 0),
(28157, 'esMX', 'Los cuatro elementos Crepusculares', 'Reúne los cuatro elementos Crepusculares: aire, tierra, fuego y agua.', 'El Martillo Crepuscular ha invocado una monstruosidad. Es una combinación de los cuatro elementos imbuida con el poder de su mena especial, el elementium.$b$bSi quieres salvar Las Mil Agujas de la destrucción total, vas a tener que destruirla. Pero antes debes hacer un par de cosas para atravesar su escudo protector.$b$bVe hacia el este, al Quebranto, y trae los cuatro elementos Crepusculares.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Magatha Tótem Siniestro. Zona: Quebranto Crepuscular, Las Mil Agujas.', 0),
(28158, 'esMX', 'Esclavizados', 'Libera a la furia esclava y al vórtice esclavo.', 'El Martillo Crepuscular tiene esclavizados a dos elementales muy poderosos. Están utilizando a la furia esclava y al vórtice esclavo para imbuir a Animus con una gran cantidad de energía.$b$bCuando Animus haya absorbido suficiente energía, explotará; el resto de Las Mil Agujas, y buena parte de las tierras colindantes, desaparecerán para siempre.', '', 'Furia esclava liberada', 'Vórtice esclavo liberado', '', '', '', '', '', '', 'Vuelve con: Magatha Tótem Siniestro. Zona: Quebranto Crepuscular, Las Mil Agujas.', 0),
(28159, 'esMX', 'La piedra de la Muerte', 'Hazte con la piedra de la Muerte.', 'En el núcleo de Animus hay un artefacto conocido como la piedra de la Muerte. Una de sus propiedades es la capacidad de absorber una gran cantidad de energía.$b$bEsa es la forma en la que los cultores planean desencadenar la explosión: sobrecargar la piedra y amplificar su energía a través del elemental.$b$bTráeme la piedra de la Muerte. Para protegerla, claro está.', '', '', '', '', '', '', 'Animus', '', '', 'Vuelve con: Magatha Tótem Siniestro. Zona: Quebranto Crepuscular, Las Mil Agujas.', 0),
(28160, 'esMX', 'Que corra la voz', 'Habla con Fizzle Pernolatón en el Barcódromo de Fizzle y Pozzik, en Las Mil Agujas.', 'Por prestarme tan fiel servicio, te regalo tu vida. Llévatela fuera de mi vista. Cuéntale a tu gente todo lo que ha sucedido.$b$b$n, una cosa más: si alguna vez nos volvemos a cruzar, morirás.', '', '', '', '', '', '', '', '', '', '', 0),
(28161, 'esMX', 'Que corra la voz', 'Habla con Pozzik en el Barcódromo de Fizzle y Pozzik, en Las Mil Agujas.', 'Por prestarme tan fiel servicio, te regalo tu vida. Llévatela fuera de mi vista. Cuéntale a tu gente todo lo que ha sucedido.$b$b$n, una cosa más: si alguna vez nos volvemos a cruzar, morirás.', '', '', '', '', '', '', '', '', '', '', 0),
(28162, 'esMX', 'Cebo de pantano', 'Te han encargado que recojas 8 pellejos de crocolisco de crocoliscos de Baradin en Tol Barad. Encontrarás los crocoliscos en el pantano, al oeste del Bastión de Baradin.', 'En un lugar como este, nunca es fácil encontrar suministros, $c. Hemos estado explorando desde que recuperamos la isla, pero la cosa no pinta bien.$B$BPor suerte, acabamos de recibir informes de nuestros exploradores de que hay un pantano lleno de crocoliscos al oeste de nuestro campamento. Los pellejos de esos crocoliscos les vendrán estupendamente a nuestros peleteros. Tráeme todos los que puedas.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el sargento Parker en el Bastión de Baradin cuando termines.', 0),
(28163, 'esMX', 'Los restos', 'Te han ordenado que mates a 12 soldados de infantería de la Horda en Tol Barad. Encontrarás sus grupos de resistencia en los Rescoldos, la Vigilia del Celador y el Cuartel del Acorazado, aquí en Tol Barad.', 'Hemos peleado mucho para hacernos con esta isla, $r. Nos hemos deshecho de la mayoría de la escoria de la Horda, pero todavía percibo su asqueroso olor en el aire.$b$bNecesito que investigues los Rescoldos, la Vigilia del Celador y el Cuartel del Acorazado. Mata a todos los miembros de la Horda que encuentres.$B$B¡Ya conoces el dicho: solo hay un miembro de la Horda bueno, y es el que está muerto!', '', 'Infantería de la Horda', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el sargento Parker en el Bastión de Baradin cuando termines.', 0),
(28164, 'esMX', 'Busca al hermano Sacraplata', 'Habla con el hermano Sacraplata en los Suburbios Goblin de Orgrimmar.', 'Me acaban de decir que te necesitan en Orgrimmar, $n. El hermano Sacraplata ha solicitado que vuelvas a la ciudad en cuanto te sea posible. Su mensaje no incluía más información y parecía tratarse de un asunto urgente.$b$bBusca al hermano Sacraplata en los Suburbios Goblin de Orgrimmar.', '', '', '', '', '', '', '', '', '', '', 0),
(28165, 'esMX', 'Bloque D', 'Te han pedido que mates a 10 demonios de cualquier tipo en el Bloque D, al noroeste del Bastión de Baradin.', '¿Ya has oído hablar del Bloque D, $n? Es uno de los viejos módulos en la isla. El problema es que está infestado de demonios. Hemos planeado utilizarlo para encerrar al resto de miembros de la Horda que quedan en la isla, pero en su estado actual no va a ser posible.$B$BNecesito que vayas hasta allí y que te encargues de eliminar a esos demonios. Preséntate de nuevo ante mí cuando termines.', '', 'Demonios asesinados', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el segundo teniente Wansworth en el Bastión de Baradin cuando termines.', 0),
(28166, 'esMX', 'La luz nocturna de Thog', 'Consigue la Luz de las almas del Foso Tripal.', 'Pa ver a los eh\'píritus necesitamos una luz eh\'pecial. Una luz que ilumine nueh\'tro interior. La Luz de las almas.$B$BEl Mah\'tillo Crepuh\'cular las usa pa descubrir traidores deh\'pués de lo que les hicimos en Hyjal. Acaban de dah\'le una a los ogros Tripal como regalo.$B$BEn el Foso Tripal, al norte, encontrarás al bruto foh\'tachón Thog. Tiene una Luz de las almas. O la tendrá hasta que tú se la quites.', '', '', '', '', '', '', '', '', '', 'Llévale la Luz de las almas a: Buunu. Zona: La Garganta, Tierras Altas Crepusculares.', 0),
(28167, 'esMX', 'Preséntate ante Carvo Cargarrayo', 'Preséntate ante Carvo Cargarrayos en Gnomeregan.', 'Voy a empezar a preparar a mis hombres para abandonar este lugar. No podemos resistir más tiempo. Quiero que avances hasta el centro de la gran sala que tenemos delante.$b$bAllí deberías encontrar a Carvo Cargarrayos. Te dará más instrucciones. Buena suerte, $n, te veré en la superficie.', '', '', '', '', '', '', '', '', '', 'Informa a: Carvo Cargarrayos. Zona: Gnomeregan.', 0),
(28168, 'esMX', 'Problemas en los Campos de Lodo', 'Preséntate ante el celador Aguaserena en los Campos de Lodo, en las Laderas de Trabalomas.', 'El celador Aguaserena, de los Campos de Lodo, al norte de aquí, ha enviado una señal de auxilio. La misiva no estaba muy clara, pero por lo que he podido entender ha habido un motín en los Campos de Lodo y la mayoría de los guardias han sido asesinados. El celador me ha advertido que los posibles héroes deben acercarse por la entrada trasera, en el lado oeste de los Campos de Lodo.$b$bTambién nos ha pedido discreción. No quiere que se extienda la noticia de este pequeño *ejem*...', '', '', '', '', '', '', '', '', '', '', 0),
(28169, 'esMX', '¡Retirada a la Zona de Carga!', 'Sigue a los operativos de S.E.G.U.R.O. hasta Gafe Muelletorcido en la Zona de Carga.', '¡Un trabajo excelente al reunir a los demás supervivientes! Ellos y tú son la razón por la que siguen bajando los equipos de S.E.G.U.R.O. Nevin no descansará hasta que hayamos rescatado hasta el último superviviente posible.$b$bVoy a enviar a mis hombres a la Zona de Carga para preparar la descontaminación. Síguelos y reúnete con Gafe Muelletorcido cuando llegues. Ella te enviará a la descontaminación y te pondrá de camino a la superficie.', '', '', '', '', '', '', '', '', '', 'Sigue a los operativos de S.E.G.U.R.O. hasta Gafe Muelletorcido en la Zona de Carga.', 0),
(28170, 'esMX', 'Terrores nocturnos', 'Habla con Uchek en La Garganta. Desde el reino de los espíritus, usa la Luz de las almas para mantenerte a salvo mientras visitas los tres santuarios dentro de la cueva.', 'Mi amigo Uchek ya eh\'tá en la cueva. Hemos construio tres santuarios en el interior. Lo único que tienes que hacer es limpiar el mal yuyu de cada uno de ellos, colega.$B$BEntra en la cueva y habla con Uchek. Él te hará entrar en trance, te llevará al reino de los eh\'píritus. ¡Ve con cuidado! Si ves una beh\'tia fantah\'mal, no te asuh\'tes. Haz brillar la Luz de las almas sobre los eh\'píritus durante un rato, y la luz hará que se vayan para siempre. La luz te mantendrá a salvo. ¡Ahora ve a limpiar los tres santuarios!', '', 'Primer santuario purificado', 'Segundo santuario purificado', 'Tercer santuario purificado', '', '', '', '', '', 'Habla con: Buunu. Zona: La Garganta, Tierras Altas Crepusculares.', 0),
(28171, 'esMX', 'Y el cielo se volvió rojo', 'Únete al ataque contra el Vuelo Negro.', 'Estando Alamuerte entretenido con otros asuntos, tenemos una ardua y nefasta tarea por delante, a las órdenes de la mismísima reina. Hay que exterminar al Vuelo Negro.$B$BMe gustaría contar con tu ayuda para esto, si me la ofreces. En cuanto estés $glisto:lista;, habla conmigo y te enviaré con el próximo vuelo que se una al ataque.', '', 'Te has unido al ataque del Vuelo Rojo', '', '', '', '', '', '', '', 'Habla con: Lirastrasza. Zona: Noroeste del Bosque Obsidiana, Tierras Altas Crepusculares.', 0),
(28172, 'esMX', 'No han hecho nada malo', 'Consigue un vástago rojo liberado, un vástago verde liberado, un vástago azul liberado, y un vástago bronce liberado.', 'Los orcos Roca Negra de las estepas sirven a un oscuro maestro: uno que lleva a cabo retorcidos experimentos con criaturas vivas para crear su propio elenco de abominaciones. Muchos de sus sujetos de estudio son tan corruptos como su maestro, pero algunos son completamente inocentes.$B$BEn Las Colinas de los Vástagos, hacia el sur, encadenan a bebés dragón al suelo, para someterlos a tales experimentos. No pienso tolerarlo. Rompe sus cadenas y tráelos aquí... a salvo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Vellón Llamaestrella. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28173, 'esMX', 'Caída', 'Mata a 8 piroalas obsidiana después de usar los anzuelos de cazavermis para alcanzarlos.', 'Los cazadores de dracos Crepusculares usaron unos instrumentos atroces para derribar a nuestros dracos. Unos anzuelos que se clavaban en sus escamas y mantenían a salvo a los Crepusculares mientras hacían caer al suelo a los nuestros.$B$BEstamos más allá del punto en el que podíamos hablar de paz. Más allá de toda esperanza para su redención. La única piedad que nos queda es la de ofrecerle al Vuelo Negro el olvido que busca tan apasionadamente.$B$BUsa esos anzuelos para matar a los piroalas obsidiana que hay al sur. Deberían permitirte mejor maniobrabilidad en el aire si los usas bien.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lirastrasza. Zona: Noroeste del Bosque Obsidiana, Tierras Altas Crepusculares.', 0),
(28174, 'esMX', 'Venganza ardiente', 'Mata a 5 cuidadores Roca Negra y a 5 estirpes de flamascama.', 'Los orcos Roca Negra no tienen fin. Están por todas las llanuras de la batalla, al este, preparados para atacar en cualquier momento.$B$BYa atacaron mi tierra natal una vez. Estoy aquí para asegurarme de que no vuelva a ocurrir.$b$bSi sientes algún aprecio por la humanidad, harás lo mismo. Demuestra de lo que eres capaz. Viaja al sur, a Las Colinas de los Vástagos, y mata a sus cuidadores y a la prole de los dragones Negros. Demuéstrame que estás $gpreparado:preparada; para esta guerra.', '', '', '', '', '', '', '', '', '', 'Vuelve con John J. Keeshan. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28175, 'esMX', 'Brillando en la oscuridad', 'Usa la lágrima de Alexstrasza dentro del hueco que hay bajo el árbol obsidiana.', 'El gran árbol petrificado que hay ante nosotros, en el sur, fue antaño una almenara rebosante de vida. Nuestra almenara. El Vuelo Negro nos arrebató este bosque, y desde entonces ha estado corrupto y petrificado. Casi sin salvación.$B$BPero aún hay esperanza. He traído una poderosa herramienta para empezar con el proceso de sanación. Todavía podemos salvar el árbol, con mucho tiempo y suerte, y quizás con un pequeño esfuerzo por tu parte.$B$BLleva esto, la lágrima de Alexstrasza, y úsala en el corazón hueco del árbol.', '', 'Lágrima de Alexstrasza plantada', '', '', '', '', '', '', '', 'Vuelve con: Velastrasza. Zona: Noroeste del Bosque Obsidiana, Tierras Altas Crepusculares.', 0),
(28176, 'esMX', 'Seguir a los pequeños a casa', 'Usa la llama materna con los huevos obsidiana para liberar a las crías. Sigue a esas proles a la guarida de su madre.', 'En la parte sudoeste del Bosque Obsidiana, encontrarás algunas de las nidadas de huevos negros. Muchos de los huevos pueden abrirse en cualquier momento utilizando la llama adecuada, y mientras rompen el cascarón, llamarán a su madre y acudirán a ella.$B$bNo te preocupes, si esta purga debe aplicarse a las crías, no te obligaré a llevar a cabo esa tarea. Solo quiero que los hagas salir y que los sigas a su hogar cuando vayan a buscar a su madre. Es con ella con quien debemos enfrentarnos.', '', 'Crías obsidiana eclosionadas', 'Guarida Obsidiana infiltrada', '', '', '', '', '', '', 'Habla con: Fardollama. Zona: Interior de la Guarida Obsidiana, Tierras Altas Crepusculares.', 0),
(28177, 'esMX', 'Abastecerse', 'Consigue 5 púas de escórpido afiladas.', 'Si vamos a enfrentarnos al clan Roca Negra, tendremos que prepararnos antes. Mi coronel ya ha elaborado el plan, ahora hay que llevarlo a cabo.$B$BNecesito aguijones de escórpido... los más afilados que puedas encontrar. Las estepas están llenas de escórpidos, pero encontrarás a la mayoría en la garganta, al oeste.$b$bNo te importa para qué son. Pronto lo descubrirás.', '', '', '', '', '', '', '', '', '', 'Vuelve con John J. Keeshan. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28178, 'esMX', 'Un futuro proyecto', 'Consigue 11 pellejos de huargo brasal.', 'Necesitaremos pellejos de huargo, un montón. No importa que estén desgarrados, quemados o ensangrentados, pero necesitamos muchos.$b$bDe hecho, puede que sea mejor si están algo hechos polvo.$b$bEncontrarás huargos tanto al oeste como al este de aquí.|n', '', '', '', '', '', '', '', '', '', 'Vuelve con John J. Keeshan. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28179, 'esMX', 'A la caza de barro', 'Consigue 9 pilas de barro con motas de obsidiana.', 'Espero que no te importe mancharte un poco. Aunque a juzgar por tu aspecto, no creo que sea un problema.$b$bHacia el norte, al borde de la lava, encontrarás pilas de barro oscuro. Lo necesito.$b$bSerá mejor que no hagas preguntas, y que concentres tus esfuerzos en cumplir las órdenes, $n.', '', '', '', '', '', '', '', '', '', 'Vuelve con John J. Keeshan. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28180, 'esMX', 'La arena, la sidra y el orbe', 'Habla con Gorzeeki Ojovago cerca del Altar de la Tempestad.', 'El Coronel Troteman nos está esperando al este de aquí. Pero antes de que nos vayamos, tenemos que reunir más suministros. Esta vez, los conseguirás de un brujo llamado Gorzeeki Ojovago.$b$bSeguramente lo encontrarás al noroeste, cerca del Altar de la Tempestad. Dile que nos va a ayudar. Necesitamos la arena, la sidra y el orbe.$b$bÉl sabrá lo que significa.', '', '', '', '', '', '', '', '', '', 'Preséntate ante Gorzeeki Ojovago en el Altar de la Tempestad en Las Estepas Ardientes.', 0),
(28181, 'esMX', 'Los brujos tienen las mejores cosas', 'Consigue un puñado de arena de sueño, una jarra de sidra hidra vil y un orbe de cristal transparente.', '¿Keeshan dice que necesita suministros? ¡Yo tengo un montón de suministros! El problema es que esos brujos me han echado a patadas de mi casa y no me dejan volver.$b$b<Gorzeeki observa tu tamaño.>$b$bPero seguramente tú serías capaz de entrar. Dirígete hacia el norte y consigue un poco de mi arena de sueño, de mi sidra hidra vil y un orbe de cristal transparente. Estoy casi seguro de que eso es lo que necesita.$b$bAh, y si por casualidad matas a algún orco por accidente mientras estás por allí, no te preocupes, no me voy a disgustar demasiado.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Gorzeeki Ojovago. Zona: Altar de la Tempestad, Las Estepas Ardientes.', 0),
(28182, 'esMX', 'Ataque umbrío', 'Asesina a Ner\'gosh el Umbrío.', 'Ner\'gosh el Umbrío es el líder de los brujos que se encuentran al norte. Es el estúpido que me sacó de mi casa cuando esos orcos Roca Negra hicieron su aparición. Bueno, son todos unos estúpidos, pero él es el más estúpido de todos.$b$bSi pretendo volver a mudarme cerca del Altar, Ner\'gosh tiene que largarse.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Gorzeeki Ojovago. Zona: Altar de la Tempestad, Las Estepas Ardientes.', 0),
(28183, 'esMX', 'Vuelve con Keeshan', 'Vuelve a llevarle los suministros de brujo a John J. Keeshan en el Puesto Llamaestrella en Las Estepas Ardientes.', 'Bueno, supongo que aquí ya he acabado contigo. Iré a espantar a esos otros brujos en cuanto reúna el valor suficiente.$b$bToma, no olvides los suministros.', '', '', '', '', '', '', '', '', '', 'Preséntate ante John J. Keeshan en el Puesto Llamaestrella en Las Estepas Ardientes.', 0),
(28184, 'esMX', 'Cincelada, el corazón de las estepas', 'Mata a 15 soldados de asalto Roca Negra cualesquiera de camino a Cincelada.', 'Nos dirigimos a Cincelada, en pleno corazón de las estepas. Allí nos encontraremos con la Hermandad de Torio, así como con Troteman.$b$b¿Conoces a la Hermandad? Esos enanos Hierro Negro me han ayudado más de una vez. Es posible que volvamos a necesitar su ayuda.$b$bPasaremos por el Cobertizo Diente Negro de camino allí. ¿Qué te parece si matamos a unos cuantos Roca Negra mientras viajamos? Me estoy impacientando un poco en este campamento.', '', 'Tropa Roca Negra asesinada', '', '', '', '', '', '', '', 'Preséntate ante Stebben Menudillo en Cincelada en Las Estepas Ardientes.', 0),
(28185, 'esMX', 'Svarnos', 'Debes matar a Svarnos en el Bloque D y volver con su collera maldita. Svarnos está en el Bloque D, al noroeste del Bastión de Baradin.', 'Un trabajo excelente al capturar la isla, $c. Ahora que es nuestra, tenemos que conseguir que los bloques de celdas sean aptos para albergar prisioneros. El Bloque D ha resultado ser especialmente difícil de despejar. Por desgracia, está lleno de demonios de todo tipo.$b$bHemos podido diezmar los demonios, pero un can del Núcleo enorme se ha escapado de su celda y está sembrando el caos ahí abajo. Quiero que lo mates y me traigas su collar.', '', '', '', '', '', '', 'Svarnos', '', '', 'Preséntate de nuevo ante el segundo teniente Wansworth en el Bastión de Baradin cuando termines.', 0),
(28186, 'esMX', 'Grilletes malditos', 'Te han pedido que recuperes 8 grilletes malditos en el Bloque D, al noroeste del Bastión de Baradin.', '¿Has estado ya en el Bloque D, $n? Cada vez que limpiamos ese módulo infestado, los demonios vuelven muy rápidamente. Hemos descubierto que se regeneran a partir de los grilletes malditos que están desperdigados por la zona. Y ahí es donde entras tú, $n.$B$BNecesito que recuperes todos los grilletes que puedas y que me los traigas. Los destruiremos inmediatamente.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el segundo teniente Wansworth en el Bastión de Baradin cuando termines.', 0),
(28187, 'esMX', '¡Porr los pelos!', 'Habla con el comandante Schnottz cuando estés $glisto:lista; para acompañarlo fuera del edificio en llamas.', '¡Vale, $r! ¡Esto se acaba de ponerr serrio!$b$bAlguien crree que se puede deshacerr de mí tan fácilmente, ¿mmm?$b$b¡Eso ya lo ferremos! ¡Nada podrrá detenerr este trrabajo! ¡Nada!$b$b<Schnottz mira a su alrededor, las llamas lo devoran todo.>$b$bTal fez deferríamos salirr de aquí.$b$b¡Date prrisa! ¡El tiempo se acaba!|n', '', 'Schnottz puesto a salvo', '', '', '', '', '', '', '', 'Habla con: Comandante Schnottz. Zona: Embarcadero de Schnottz.', 0),
(28188, 'esMX', 'Revuelta en la cárcel', 'Te han ordenado que mates a 10 prisioneros de cualquier tipo en El Agujero, al suroeste del Campamento de Baradin.', 'Tenemos la isla, y ahora tenemos que aprovechar los recursos de la zona. Hemos encontrado un módulo abandonado al suroeste de aquí y necesitamos que vayas a investigar, $n.$B$BHemos recibido informes de que está plagado de prisioneros que llevan allí encerrados durante años. Haz lo que tengas que hacer para limpiar ese lugar. Preséntate de nuevo ante mí cuando termines.', '', 'Prisioneros asesinados', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el alguacil Fallows en el Bastión de Baradin cuando termines.', 0),
(28189, 'esMX', 'Haz lo correcto', '"Salva" a 15 esquejes humanos.', 'Te encuentras con una escena horrible. Alguien o algo ha enterrado a todos los humanos hasta el cuello, como si los hubieran plantado. Los necrófagos, que parecen estar cuidando el campo de esquejes humanos, ¡saltan ocasionalmente hasta el humano más cercano y se comen su cabeza!$b$bPuedes acabar con esto aquí y ahora. Coge esta pala y "salva" a los humanos.$b$bHaz lo correcto.', '', 'Esqueje humano "salvado"', '', '', '', '', '', '', '', '', 0),
(28190, 'esMX', 'El moco corrupto', 'Mata a 8 mocos corruptos.', 'Todo esto empezó con Winna Riessgo. Era una Boticaria Renegada en el Puesto del Veneno, buscando formas de usar el moco demoníaco que hay aquí contra la Alianza.$B$BLe advertimos que estaba yendo demasiado lejos, pero ella no nos escuchó y nosotros no actuamos lo suficientemente rápido. Ahora ella y todos los del Puesto del Veneno no son más que criaturas babosas descerebradas...$B$BLos asquerosos mocos que usó para esto todavía están en las charcas que hay al este y al sur. Te lo ruego, $c, destrúyelos para que otros no puedan cometer semejante maldad.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Altsoba Tótem de Ira. Zona: Puesto del Veneno, Frondavil.', 0),
(28191, 'esMX', 'Un final apropiado', 'Mata a 10 vermintes obsidiana.', 'El paisaje del sur está salpicado de vermintes obsidiana. No están en posición de atacarnos, pero nunca se sabe qué nuevas amenazas puede despertar el flujo de la batalla.$b$bQuiero que lleves la batalla a los vermintes. Acaba con ellos para que podamos purgar esta tierra de la presencia contaminante del Vuelo Negro.', '', 'Vermintes obsidiana asesinados', '', '', '', '', '', '', '', 'Vuelve con: Lirastrasza. Zona: Noroeste del Bosque Obsidiana, Tierras Altas Crepusculares.', 0),
(28192, 'esMX', 'Nadie saldrá con vida', 'Analiza la situación en los Campos de Lodo.', '¡Esta granja está en cuarentena! ¡Nada entra y nada sale! Aún estamos analizando la situación para averiguar qué ha ocurrido exactamente, pero mi teoría es que los obreros se comieron las setas y de alguna forma se transformaron en horribles monstruos no-muertos. A ver, ¿qué otra cosa podría haber pasado? ¡Es una granja! ¡Cultivamos setas! ¡Y lodo! ¡Sí, lodo!$b$bMira a tu alrededor, $c, porque ahora que estás aquí ya no te puedes ir hasta que esto esté arreglado.$b$b¡Míralo tú $gmismo:misma;!', 'Analiza la situación en los Campos de Lodo.', '', '', '', '', 'Analiza la situación en los Campos de Lodo.', '', '', '', 'Habla con: Celador Aguaserena. Zona: Los Campos de Lodo, Laderas de Trabalomas.', 0),
(28193, 'esMX', '¡A cal y canto!', 'El comandante Schnottz quiere que observes a los invitados en el Embarcadero de Schnottz.', '¡Ese edificio no ha estallado solo!$b$b¡Alguien trrata de acabarr conmigo; y no descansarrás hasta averriguarr quién!$b$bEmpieza porr los infitados. Fisítalos, ofserfa su comporrtamiento; y después fuelfe parra inforrmarrme.$b$b¡Si saben algo, harré que los interroguen!$b$b¡Puedes retirrarrte!', '', 'Invitados de Schnottz visitados', '', '', '', '', '', '', '', 'Habla con: Comandante Schnottz. Zona: Embarcadero de Schnottz.', 0),
(28194, 'esMX', 'La Gran Evasión', 'El escritor prolífico de Embarcadero de Schnottz quiere que reúnas 6 uniformes de marineros de Schnottz.', '¡Por favor, $c! ¡Necesitamos tu ayuda!$b$bNos retienen en este edificio contra nuestra voluntad. ¡Y con el comandante tan iracundo, es imposible saber qué pretende hacer con nosotros!$b$bTal vez si pudieras conseguirnos unos uniformes, podríamos escaparnos.$b$bNo deberíamos haber venido. Ahora lo veo claro.$b$bSi nos ayudas a escapar, escribiré la VERDAD sobre lo que ha ocurrido aquí.$b$bEsos hombres de los barcos están vestidos con el atuendo que necesitamos.', '', '', '', '', '', '', '', '', '', 'Habla con: Escritor prolífico. Zona: Embarcadero de Schnottz.', 0),
(28195, 'esMX', 'Enviar un mensaje', 'El comandante Schnottz quiere que mates al capitán Margun, al capitán Cork y al capitán Kronkh.', 'Tengo ojos y orrejas en todos los recofecos de esta región, $r.$b$bHe oído los rumorres que se prropagan porr mis trropas. He sido de lo más tolerrante con este comporrtamiento tan patético. ¡Hasta ahorra!$b$bEnviarré un mensaje a cada uno de los soldados de mis filas: ¡no tolerrarré esa disensión!$b$bTienes que asesinarr a los capitanes que se encuentrran a borrdo de mis barrcos en los muelles. Son los que más firrulentos se han mostrrado.$b$bCuando hayas terrminado esta tarrea, monitorrizarré las comunicaciones y decidirré qué hacer después.$b$b¡Puedes retirrarte!', '', 'Capitán Margun asesinado', 'Capitán Cork asesinado', 'Capitán Kronkh asesinado', '', '', '', '', '', 'Preséntate ante el comandante Schnottz en Embarcadero de Schnottz.', 0),
(28196, 'esMX', 'La Batalla por Trabalomas', 'Entrega La Batalla por Trabalomas al celador Aguaserena en los Campos de Lodo, en las Laderas de Trabalomas.', 'Este diario narra los últimos 62 días de la vida del funcionario Horracio Corzalbal. En él constan acusaciones condenatorias sobre el celador Aguaserena y sus actividades en los Campos de Lodo.$b$bDeberías enseñárselo al celador. Sin duda tendrá alguna explicación para el contenido del diario.', '', '', '', '', '', '', '', '', '', '', 0),
(28197, 'esMX', 'La discreción es la clave', 'Mata al ciudadano Wilkes y al funcionario Horracio Corzalbal.', '¡Debemos destruir todas las pruebas, $n! ¿He dicho "pruebas"? ¡Quería decir "no-muertos dementes"! A lo que iba: la discreción es clave. No debemos dejar que esos no-muertos salgan de los Campos de Lodo y nadie fuera de esta institución debe descubrir lo que ha pasado aquí.$b$bJusto al sureste de aquí, en lo que antes era una vieja granja de champiñones, encontrarás a un monstruo resucitado llamado ciudadano Wilkes y su compañero, el funcionario Horracio Corzalbal. Les han estado causando un montón de problemas a mis guardias. ¡Encuéntralos y mátalos!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Celador Aguaserena. Zona: Los Campos de Lodo, Laderas de Trabalomas.', 0),
(28198, 'esMX', 'El eslabón más débil', 'Habla con Salhet en la Avanzada de la Legión Ramkahen, en Uldum.', 'Se dice que una cadena es tan fuerte como su eslabón más débil.$B$BEstoy de acuerdo con esa teoría e incluso la ampliaría.$B$BEn vez de eliminar el eslabón débil, uno debe... reforzarlo.$B$BEl resto de eslabones mejorarán su rendimiento por temor a convertirse en el eslabón más débil.$B$BEn el caso de mi ejército, el eslabón más débil tiene un nombre: Salhet.$B$BLo encontrarás cerca de la parte inferior de esas escaleras.$B$BComienza por algo sencillo. Tal vez las hienas de las colinas al oeste de aquí.', '', '', '', '', '', '', '', '', '', '', 0),
(28199, 'esMX', '¡Por la ciencia!', 'Recupera 6 muestras de carne.', 'Muestras... Sí... ¡Necesito muestras! Estos, eh, experimentos... Quiero decir, estos desgraciados obreros deben ser estudiados.$b$bViaja al sureste hasta la primera granja y mata a los necrófagos resucitados. Debes recuperar muestras de carne de sus cadáveres decrépitos. ¡Tráemelas!$b$b<Arnauld enlaza las manos y se ríe como un maníaco sin razón aparente.>$b$b¡Debo experimentar!', '', '', '', '', '', '', '', '', '', 'Entrega las muestras de carne al formador de carne Arnauld en los Campos de Lodo, en las Laderas de Trabalomas.', 0),
(28200, 'esMX', 'El elemento de los suministros', 'Reúne 20 pellejos de crocolisco endurecidos.', 'Te darás cuenta de que estamos poco preparados para la batalla.$B$BLas tribus tol\'vir no han sufrido enfrentamientos masivos durante miles de años.$B$BAunque todos los protocolos de combate que los titanes programaron en nuestros ancestros siguen ahí. Algunos forman parte de nuestros instintos y otros los aprendemos en nuestras tradiciones.$B$BPero nada de eso puede compensar la falta de suministros. Necesitamos armas. Necesitamos armaduras.$B$BLas mejores armaduras son las que tienen revestimiento de piel de crocolisco de lecho de río, de los que hay por aquí cerca. Ayúdanos a reunir algunos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Sargento Mehat. Zona: Avanzada de la Legión Ramkahen, Uldum.', 0),
(28201, 'esMX', 'Arados como espadas', 'Recluta a 8 obreros Ramkahen.', 'Tenemos un ejército bastante grande, pero me temo que para el próximo enfrentamiento con las hordas Neferset necesitaremos que todos los tol\'vir capaces de Ramkahen y Orsis se unan a la lucha.$B$BQuiero que te pongas a la cabeza de la tarea de reclutamiento.$B$BCruza el río, hasta los Campos de Akhenet, y recluta a los obreros que trabajan allí.', '', 'Obrero Ramkahen reclutado', '', '', '', '', '', '', '', 'Vuelve con: Alto comandante Kamses. Zona: Avanzada de la Legión Ramkahen.', 0),
(28202, 'esMX', 'Un disfraz perfecto', 'Lleva la cantidad apropiada de suministros de la mesa de sastre a Thelaron Malaguja en Cincelada.', 'A juzgar por tu peso, complexión y estatura, vamos a vestirte como un ogro. Su ejército está formado en su mayoría por orcos, así que encajarás perfectamente.$b$b¿Sabes algo de sastrería? Si no es así, considera esto como tu primera lección. Mi mesa de trabajo, que está ahí mismo, tiene todo lo necesario.$b$bVe, coge todo lo que creas necesario y tráelo aquí. Thelaron se encargará de todo.', '', 'Disfraz perfecto creado', '', '', '', '', '', '', '', 'Preséntate ante John J. Keeshan en Cincelada en Las Estepas Ardientes.', 0),
(28203, 'esMX', 'Un disfraz perfecto', 'Lleva la cantidad apropiada de suministros de la mesa de sastre a Thelaron Malaguja en Cincelada.', 'A juzgar por tu peso, complexión y estatura, vamos a vestirte como un ogro. Los ogros Pirontraña siempre han trabajado con los Roca Negra, así que encajarás perfectamente.$b$b¿Sabes algo de sastrería? Si no es así, considera esto como tu primera lección. Mi mesa de trabajo, que está ahí mismo, tiene todo lo necesario.$b$bVe, coge todo lo que creas necesario y tráelo aquí. Thelaron se encargará de todo.', '', 'Disfraz perfecto creado', '', '', '', '', '', '', '', 'Preséntate ante John J. Keeshan en Cincelada en Las Estepas Ardientes.', 0),
(28204, 'esMX', 'Un disfraz perfecto', 'Lleva la cantidad apropiada de suministros de la mesa de sastre a Thelaron Malaguja en Cincelada.', 'A juzgar por tu peso, complexión y estatura, vamos a vestirte como un goblin. Sabemos que los Roca Negra han estado contratando a mercenarios goblins para completar sus filas, así que encajarás perfectamente.$b$b¿Sabes algo de sastrería? Si no es así, considera esto como tu primera lección. Mi mesa de trabajo, que está ahí mismo, tiene todo lo necesario.$b$bVe, coge todo lo que creas necesario y tráelo aquí. Thelaron se encargará de todo.', '', 'Disfraz perfecto creado', '', '', '', '', '', '', '', 'Preséntate ante John J. Keeshan en Cincelada en Las Estepas Ardientes.', 0),
(28205, 'esMX', 'Un disfraz perfecto', 'Lleva la cantidad apropiada de suministros de la mesa de sastre a Thelaron Malaguja en Cincelada.', 'A juzgar por tu peso, complexión y estatura, vamos a vestirte como un trol. Los trols Espina Ahumada siempre han trabajado con los orcos Roca Negra, así que encajarás perfectamente.$b$b¿Sabes algo de sastrería? Si no es así, considera esto como tu primera lección. Mi mesa de trabajo, que está ahí mismo, tiene todo lo necesario.$b$bVe, coge todo lo que creas necesario y tráelo aquí. Thelaron se encargará de todo.', '', 'Disfraz perfecto creado', '', '', '', '', '', '', '', 'Preséntate ante John J. Keeshan en Cincelada en Las Estepas Ardientes.', 0),
(28206, 'esMX', 'Una chica perdida', 'Busca a Johnny Fenómeno ("Jenny") en los Campos de Lodo, en las Laderas de Trabalomas.', 'Solo hace un día que la envié a investigar la granja que hay justo al este, ¡pero parece que haya pasado una eternidad!$b$bSabía que era auténtico amor en cuanto la vi. Sus preciosos rizos dorados, la forma en la que enmarcaban su rostro de elfa de sangre... Derritió mi oscuro corazón. No quería mandarla fuera, ¡pero era tan exigente...! ¡Tuve que darle lo que me pedía! ¿Quién podría haberse negado a semejante ángel?$b$b¡Ay de mí, la Increíble Jenny no ha vuelto! Me temo lo peor, $n. ¡Encuéntrala!', '', '', '', '', '', '', '', '', '', '', 0),
(28207, 'esMX', 'Una situación viscosa', 'Recoge 7 champiñones brillantes esmeralda.', '¡Este pobre casi no logra salir del Puesto del Veneno con vida! Si queremos evitar que se convierta en una babosa como los demás, tenemos que tratar la infección.$B$BHay muchos champiñones cerca de las verdes y brillantes aguas que hay por aquí, como el estanque que hay al este, bajo las cataratas. La mayoría de ellos no son buenos... ¡necesito que cojas los que son verde brillante!$B$BCon esos, podré preparar algo sabroso para este pobre tauren. ¡No tardes mucho!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Kelnir Hojacanto. Zona: Puesto del Veneno, Frondavil.', 0),
(28208, 'esMX', 'El gatito de Winna', 'Coge la etiqueta de oreja de Minino del gatito de Winna.', 'El señor Tauren me ha contado muchas cosas sobre lo que pasó en el Puesto del Veneno. ¡Dice que Winna Riessgo todavía está allí!$B$BLa hemos perdido, pero lo que queda de ella está creando un montón de babosas nuevas. ¡Debemos parar esto!$B$BAfortunadamente, tengo un plan. El señor Tauren ha dicho que Winna tenía un gatito. Le dio de comer agua corrupta de babosas y se escapó hacia el bosque. He visto a algo merodeando por el sudoeste, justo tras la Torre del Veneno, ¡pero estoy segura de que era más grande que un gatito! Ve a ver si el gatito tiene una etiqueta...', '', '', '', '', '', '', 'Gatito de Winna', '', '', 'Vuelve con: Kelnir Hojacanto. Zona: Puesto del Veneno, Frondavil.', 0),
(28209, 'esMX', 'Libertad para Lydon', 'Recupera la llave de la jaula de Lydon.', '¡Este sitio no es una granja! Aguaserena ha estado experimentando con los humanos de Trabalomas. Esas monstruosidades son todas obra suya.$b$bEso no es lo peor, $c. Las aberraciones que tienen la llave de mi jaula antes eran Renegados. Los experimentos de Aguaserena tienen el efecto secundario de convertir a los Renegados en zombis sin voluntad. ¿Por qué crees que le da tanto miedo que todo esto se descubra? Sabe que semejante crimen se castiga con la muerte.$b$b¡Sácame de aquí! ¡Los guardias de lodo que hay fuera tienen la llave!', '', '', '', '', '', '', '', '', '', 'Habla con: Maestro boticario Lydon. Zona: Los Campos de Lodo, Laderas de Trabalomas.', 0),
(28210, 'esMX', 'Entrar en vereda', 'Ayuda a Salhet a matar a 8 hienas Gruñido Sangriento.', '¿El alto comandante Kamses tiene una misión para mí?$B$BEspera... no me lo digas. Hienas otra vez, ¿verdad?$B$BMuy bien, lo haré lo mejor que pueda.$B$BEncuéntrate conmigo en el Monte del Vigía del Sol.$B$BNo te decepcionaré.', '', 'Ayuda a Salhet a derrotar a hienas Gruñido Sangriento', '', '', '', '', '', '', '', 'Habla con: Salhet. Zona: Monte del Vigía del Sol, Uldum.', 0),
(28211, 'esMX', 'Templadas con llamas elementales', 'Recoge 8 lanzas templadas.', 'Lo primero es lo primero: vamos a necesitar munición. Munición lo suficientemente poderosa como para perforar el pellejo acorazado de un draco negro.$B$BAl oeste de Bramal, hay un pueblo Martillo Salvaje que ha sido invadido por elementales de fuego desatado. Cualquier arma que haya quedado en esa conflagración habrá sido templada con llamas elementales. ¡Más resistentes que cualquier cosa que yo pudiera crear en esta fragua!$B$BEncuéntrame lanzas en la Conflagración de Humboldt, $n. Cuanto más puntiagudas, mejor.', '', '', '', '', '', '', '', '', '', 'Llévale las lanzas a: Nivvet Acequial. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(28212, 'esMX', 'Algo caliente', 'Consigue 5 perdigones de Furia de arrabio.', 'Tengo un plan para cuadruplicar el par de torsión de un arpón normal de este tamaño, pero, según mis cálculos, la acción de disparar el arma destrozaría la carcasa. Y probablemente partiría el planeta en dos.$B$BPuedo soldar un chasis 100 veces más fuerte si consigo una buena fuente de llamas elementales puras para fundir.$B$BHay malignos de ámbar deambulando al oeste de aquí, en la Conflagración Humboldt. Matarlos debería convertirlos en perdigones de Furia de arrabio. ¡Tráeme algunos!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Nivvet Acequial. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(28213, 'esMX', 'Misión de riessgo', 'Usa la etiqueta de oreja de minino para llamar la atención de Winna Riessgo y luego mátala.', 'Winna está enganchada a la fuente de la baba, en el mismo fondo del Puesto del Veneno. Se asegura de que siga fluyendo ¡y la protege! Pero si pudieras llamar su atención... $b$bCoge la etiqueta de oreja y enséñasela. Si queda algo, por pequeño que sea, de su verdadero ser, puede que funcione. Tal vez el recuerdo de la pérdida de su pobre minino salga a la superficie y lo lamente una vez más, ¡lo suficiente como para salir de la baba!$B$BEntonces podrás matarla y detener la baba. ¡Sí!', '', '', '', '', '', '', 'Winna Riessgo', '', '', 'Vuelve con: Kelnir Hojacanto. Zona: Puesto del Veneno, Frondavil.', 0),
(28214, 'esMX', 'Limpieza en el Puesto del Veneno', 'Mata a 6 esclavos babosos de Puesto del Veneno.', 'Blurgh...$B$BPodrías... ugh... por favor, podrías... URGH!$B$BPerdón, aún estoy un poco... ugh, mi estómago. Si te diriges a Puesto del Veneno, al oeste, podrías HUUURGH...$B$BSolo... solo acaba con el sufrimiento de lo que quede de mis amigos. Ve, ¡AHORA! Por tu propio bien. Uuuuurghh...', '', '', '', '', '', '', '', '', '', 'Vuelve con: Altsoba Tótem de Ira. Zona: Puesto del Veneno, Frondavil.', 0),
(28215, 'esMX', 'Energía potencial', 'Reúne 10 aros de elementium retorcidos.', 'Como bien sabes, la cantidad de energía almacenada en un muelle convencional es igual a la mitad de su elasticidad multiplicada por el desplazamiento al cuadrado. A menos que estés usando un muelle de elementium. ¡Entonces las cifras se vuelven obscenas! ¡Matemáticamente grotescas!$B$BNecesito aros de elementium para mi arma secreta y da la casualidad de que los adeptos del Martillo Crepuscular usan aros como esos para atar a los elementales de tierra.$B$BPuedes quitárselos a los esclavos de piedra obsidiana que hay al este de aquí, en la terrible región conocida como la Brecha Negra.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Nivvet Acequial. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(28216, 'esMX', 'Señor del Magma Falthazar', 'Consigue la cabeza del señor del Magma Falthazar.', 'Acabo de enterarme de las terribles noticias del oeste: hemos perdido la finca de Humboldt. ¡Borrada de la faz del planeta con una bola de fuego!$B$BEs culpa del Martillo Crepuscular, y los supervivientes dicen que lo hizo el señor del Magma Falthazar. Es un ascendiente: así llaman a los adeptos del Martillo Crepuscular del más alto rango que se hacen uno con los elementos. Es una criatura de puro fuego.$B$B¡Y pronto será una criatura de pura muerte! ¡Ve, mata a Falthazar en la Conflagración de Humboldt y tráeme su cabeza!', '', '', '', '', '', '', 'Falthazar', '', '', 'Vuelve con: Colin Bramal. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(28217, 'esMX', 'Se busca: el cazademonios', 'Mata a Feronas Morapecado.', 'Desde que recuperamos el Camino Fuego de Jade de manos de los sátiros, el Círculo Esmeralda ha enviado a muchos druidas para que comiencen con la ardua tarea de purificar las ruinas. Anoche, muchos de ellos fueron asesinados... por un elfo de la noche.$B$BLos testigos dicen que fue un cazademonios, un discípulo loco de Illidan. Algo difícil de encontrar. Sin duda se ha vuelto loco de poder, igual que su maestro.$B$BPagaré una buena recompensa a quien me traiga la prueba de su muerte. Ha sido visto al otro lado del camino del norte, en un valle bajo el Camino de Fuego de Jade.', '', '', '', '', '', '', 'Feronas Morapecado', '', '', 'Habla con: Feronas Morapecado.', 0),
(28218, 'esMX', 'Destino de fuego y pesar', 'Revive la batalla entre Illidan y Arthas.', 'Siempre han odiado a mi gente por lo que hacemos... proscritos despreciados, acusados de corrupción más allá de toda redención.$B$BPero si no fuera por un cazademonios, los propios bosques serían la mayor fortaleza de la Legión Ardiente en Azeroth. Hablo de mi maestro: Illidan Tempestira, el "Traidor".$B$BCompruébalo tú $gmismo:misma; Mira lo que ocurrió aquí cuando Illidan fue liberado por primera vez y las fuerzas demoníacas del señor del terror Tichondrius gobernaban este bosque sin encontrar resistencia alguna...', 'Arthas derrotado', '', '', '', '', 'Arthas derrotado', 'Arthas', '', '', 'Vuelve con: Feronas Morapecado. Zona: Frondavil.', 0),
(28219, 'esMX', 'Bichos para el bebé', 'Mata a 10 zumbones maderaférrea para alimentar la vaina de esqueje.', '<El pequeño esqueje abre sus hojas, como un bebé que quiere ser alimentado. Habla con una voz muy débil:>$B$BHambre... quiero... bichos...<Puedes oír el zumbido de las avispas al sur. ¿Será eso lo que quiere comer el pequeño?>', '', '', '', '', '', '', '', '', '', '', 0),
(28220, 'esMX', 'Buscando terreno', 'Lleva a la vaina de esqueje a 7 áreas de terreno rico.', '<El diminuto rebrote se revuelca, haciendo gestos hacia el sur. Apenas puedes oír una voz débil.>$B$BTierra...$B$B<Parece que quiere un terreno fresco. A lo mejor deberías llevarlo a uno de los terrenos que parecen más ricos.>', '', 'Terreno rico', '', '', '', '', '', '', '', '', 0),
(28221, 'esMX', 'Las raíces se hicieron para aplastarlas', 'Mata a 10 vapuleadores Troncoferro.', 'Hay tantos espíritus que continúan atrapados en cuerpos que se están pudriendo...$B$B¿Lo ves? Los vapuleadores Troncoferro, en el norte. Los han enfermado cosas demoníacas y están cubiertos de moho. Los pobres espíritus que tienen dentro no pueden salir.$B$B¡Tú puedes ayudar! Córtalos, así los espíritus podrán liberarse. Haré que los espíritus entren en mí y así podremos ser todos felices cuando yo crezca. ¿Nos ayudarás? ¿Por favor?', '', '', '', '', '', '', '', '', '', '', 0),
(28222, 'esMX', 'Cantando bajo el sol', 'Lleva al árbol joven protector a 5 fragmentos de luz solar en el Bosque de Troncoferro.', 'Nos estamos haciendo tan grandes... ¡Ha llegado la hora de brillar! ¡La hora de extender nuestras hojas hacia el sol!$B$B¡Llévame hacia el sol! El sol está muy lejos, pero su luz llega hasta nosotros. La luz baja por las ramas grandes hasta las pequeñas como las nuestras.$B$B¡Allí! ¡El sol llega hasta nosotros en el norte! Llévanos contigo, ¡llévanos a bailar!', '', 'Rayos de sol disfrutados', '', '', '', '', '', '', '', '', 0),
(28223, 'esMX', 'El celador', 'Tienes que matar al celador Silva en El Agujero y volver con sus llaves. El Agujero está al suroeste del Bastión de Baradin.', 'Ya casi hemos terminado de eliminar a los prisioneros de la revuelta en El Agujero, pero nos queda un último problema: el celador.$b$bEl celador Silva es su señor y harán lo que sea por él. Si lo eliminamos a él, los eliminamos a todos. Acaba con él y tráeme sus llaves. Podemos usar las llaves para explorar más en profundidad el módulo y tal vez así consigamos acceder al suministro de agua en la isla.', '', '', '', '', '', '', 'Celador Silva', '', '', 'Preséntate de nuevo ante el alguacil Fallows en el Bastión de Baradin cuando termines.', 0),
(28224, 'esMX', 'El último protector', 'Derrota al protector marchito.', 'Ah... gracias, pequeño $r. Yo y otros hemos intentado tantas veces, sin éxito, crecer en este bosque.$B$BEl protector marchito que hay al norte es el único ancestro que ha crecido hasta alcanzar la madurez desde que el bosque fue contaminado, pero su cuerpo está enfermo y su mente loca. Así como reunimos a los espíritus de los antárboles, me gustaría salvar a los espíritus que viven en él antes que dejarlos atrás.$B$BDerrótale y deja que sus espíritus se unan a mí antes de que eche mis raíces.', '', '', '', '', '', '', 'El protector marchito', '', '', '', 0),
(28225, 'esMX', 'Demuestra tu lealtad', 'Mata a 10 enanos Hierro Negro en las Ruinas de Thaurissan.', 'Puedes quedarte en Cincelada durante un tiempo, pero antes necesito comprobar que eres $gamigo:amiga;. Así que tengo una tarea para ti.$b$bNosotros los de la Hermandad del Torio no somos los únicos Hierro Negro en las estepas. Ni mucho menos. Somos muy pocos comparados con la cantidad de Hierro Negro que hay en la Montaña Roca Negra. Aquí en Cincelada estamos bastante seguros, pero aun así, no dejan de molestarnos y se acercan incluso hasta las Ruinas de Thaurissan, al norte.$b$bDemuéstrame tu amistad, $r. Mátalos por mí.', '', 'Enano de Thaurissan asesinado', '', '', '', '', '', '', '', 'Vuelve con: Stebben Menudillo. Zona: Cincelada, Las Estepas Ardientes.', 0),
(28226, 'esMX', 'Gólems desguazados', 'Mata a atracadores de guerra en las Ruinas de Thaurissan, después recoge 3 pistones de obsidiana, 3 cribas con escape fundente, 3 charnelas de torio y 1 núcleo de poder pétreo de las piezas de atracador de guerra que suelten.', 'Aquí tenemos gólems para que nos hagan de guardianes. Los enanos del norte también tienen gólems, pero no sé para qué.$b$bSupongo que solo para matar.$b$bNo nos vendrían mal unas cuantas piezas para nuestros gólems, así que el plan es el siguiente: mata a los suyos y después busca las piezas útiles que hayan caído al suelo. Recupera lo que puedas. Es posible que no puedas recogerlo todo, así que selecciona con cuidado.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Stebben Menudillo. Zona: Cincelada, Las Estepas Ardientes.', 0),
(28227, 'esMX', 'Entrenamiento de gólem', 'Ayuda a 4 gólems cincelados con su insrtucción de combate.', 'Has demostrado ser de gran ayuda por aquí, $r. Estaba pensando que podrías ayudarnos con una cosa más.$b$bNuestros guardias son fuertes, pero no tanto como tú. Estaba pensando que si no te importa, tal vez podrías ayudar a alguno de ellos con su entrenamiento. Tú solo ve y habla con alguno de ellos y enfréntate a él unas cuantas veces. Esperemos que aprendan observando tus movimientos y así mejoren.', '', 'Gólems cincelados entrenados', '', '', '', '', '', '', '', 'Vuelve con: Stebben Menudillo. Zona: Cincelada, Las Estepas Ardientes.', 0),
(28228, 'esMX', 'Unirse al bosque', 'Trae al protector floreciente de vuelta a la colina, en el centro del Bosque de Troncoferro.', 'Ha llegado el momento de despedirnos. Me has visto crecer desde que era un esqueje, aunque ha sido poco tiempo, pero ahora debo unirme al bosque.$B$BLlévame de vuelta a la colina donde me encontraste. Allí echaré mis raíces y creceré a la sombra de los ancestros que hubo antes de mí.', 'Protector llevado a la colina', '', '', '', '', 'Protector llevado a la colina', '', '', '', '', 0),
(28229, 'esMX', 'Naturaleza y Nutrición', 'Llena el vial en la Poza de la Luna en la Arboleda Susurravientos y echa el agua en el suelo, entre los antiguos protectores muertos, en el Bosque de Troncoferro.', 'Los antiguos protectores del Bosque de Troncoferro en el norte llevan años muertos, sus cuerpos son un amargo símbolo del daño sufrido por estas tierras.$B$BEn cada estación, cogemos agua de esta Poza de la Luna y la echamos en el suelo, a sus pies, con la esperanza de que alimentará una nueva vida. Si quieres, puedes llevar el agua tú $gmismo:misma;.$B$BEs una oportunidad excelente para reflexionar. Coge este vial, llénalo en la Poza de la Luna y echa el agua en la cima de la pequeña colina que hay entre los tres protectores.', '', 'Colina de Troncoferro regada', '', '', '', '', '', '', '', '', 0),
(28230, 'esMX', 'Protocolo', 'Mata a la monstruosidad Ray-Getz-Kalaba.', 'Antes de que le demos al celador lo que se merece debemos lidiar con la epidemia. No podemos permitir que se contagie el resto del mundo.$b$bEn la residencia de los obreros, justo al norte de aquí, hay una monstruosidad que Aguaserena elaboró a partir de tres granjeros. Si queremos proteger los Campos de Lodo, debemos destruir a esa bestia. ¡Lo exige el protocolo!', '', '', '', '', '', '', '', '', '', 'Habla con: Maestro boticario Lydon. Zona: Los Campos de Lodo, Laderas de Trabalomas.', 0),
(28231, 'esMX', 'Hazlo por Centella', 'Mata al herrero Verringtan.', 'El celador Aguaserena me envió al campo para investigar la epidemia. Cuando llegué, a Centella y a mí nos atacó la monstruosidad llamada Verringtan. Me derribó de lomos de Centella y salí corriendo inmediatamente. Ella se quedó para luchar contra la bestia. Por desgracia, esta la derrotó y la plantaron en la tierra como si fuera una semilla de poni de estrellas.$b$bDio su vida por defenderme. ¡La venganza debe ser mía! ¡Al menos hazlo por Centella!', '', '', '', '', '', '', '', '', '', 'Habla con: Johnny Fenómeno. Zona: Los Campos de Lodo, Laderas de Trabalomas.', 0),
(28232, 'esMX', 'Comida desde abajo', 'Te han pedido que recuperes 12 raciones de módulo de El Agujero, justo al suroeste del Bastión de Baradin.', 'Estamos bajos de suministros en el campamento, $n. Acabamos de enterarnos de que en el módulo al suroeste de aquí quedan raciones de la época en que estaba en uso. Necesitamos que recojas todas las que puedas y que las traigas al campamento.$B$BUna cosa más: todo el módulo está plagado de prisioneros, así que ten cuidado.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el alguacil Fallows en el Bastión de Baradin cuando termines.', 0),
(28233, 'esMX', 'El hermano perdido', 'Encuentra a Bahrum Forjamartillo.', '¡Mi hermano Bahrum ha desaparecido!$B$BFue uno de los primeros exploradores de la zona. Todos los demás han vuelto a salvo, pero no hay señales de él. Dicen que se habrá retrasado en alguna parte, pero es mi único hermano, y le prometí a mi mamá que cuidaría de él. ¿Me ayudarás a encontrarlo?', '', '', '', '', '', '', '', '', '', 'Encuentra a: Bahrum Forjamartillo.', 0),
(28234, 'esMX', '¡Se han llevado mis pantalones!', 'Encuentra las musleras de Bahrum.', '¿Por qué estoy en el cajón de grano? Para resumir: había avispones y algunos Faucedraco que se presentaron en un mal momento. Conseguí ponerme a salvo, ¡pero los muy bastardos se fueron llevándose mis musleras!$B$BMe las hizo mi hermana, incluso bordó mi nombre en... me moriría de vergüenza si se enterara de que las he perdido.$B$BEncuéntralas, por favor, vi cómo el ladrón se las llevaba a aquella fortaleza. Yo me quedaré aquí a *ejem* cubierto.$B$B¡Y no quieras saber lo que lleva un Martillo Salvaje bajo su falda!', '', '', '', '', '', '', '', '', '', 'Llévale las musleras a: Barhrum. Zona: Campamento de Guerra Gorshak, Tierras Altas Crepusculares.', 0),
(28235, 'esMX', 'Ladoquemado debe caer', 'Mata al magistrado Ladoquemado.', 'Una vez el magistrado Ladoquemado fue el alcalde de esta región. En vida fue un adversario formidable en la batalla por Trabalomas. En la no-muerte sin duda será un desafío.$b$bLadoquemado canaliza una gran magia Arcana en la sección noroeste de los Campos de Lodo. Llévanos hasta allí y acabaremos con su mandato de una vez por todas.', '', '', '', '', '', '', '', '', '', 'Habla con: Maestro boticario Lydon. Zona: Los Campos de Lodo, Laderas de Trabalomas.', 0),
(28236, 'esMX', 'El hermano perdido', 'Encuentra a Bahrum Forjamartillo.', '¡Mi hermano Bahrum ha desaparecido!$B$BFue uno de los primeros exploradores de la zona. Todos los demás han vuelto a salvo, pero no hay señales de él. Dicen que se habrá retrasado en alguna parte, pero es mi único hermano, y le prometí a mi mamá que cuidaría de él. ¿Me ayudarás a encontrarlo?', '', '', '', '', '', '', '', '', '', '<completion text>', 0),
(28237, 'esMX', 'Una plaga para la tierra', 'Córtale la cabeza al celador Aguaserena.', 'Ahora que hemos contenido la epidemia de no-muertos, ha llegado la hora de que Aguaserena y sus seguidores paguen por sus crímenes. Aunque hemos evitado una tragedia de proporciones inauditas desde la invasión de la Plaga, debemos asegurarnos de que nunca pueda volver a pasar nada semejante. ¡Todos sufrirán la muerte verdadera!$b$b¡Ven, $n! ¡Quiero la cabeza de Aguaserena!', '', '', '', '', '', '', '', '', '', 'Dale la cabeza del celador Aguaserena al maestro boticario Lydon en los Campos de Lodo, en las Laderas de Trabalomas.', 0),
(28238, 'esMX', 'Orillas Crepusculares', 'Habla con Fargo Cierrasílex en el Puerto de Ventormenta.', 'Ha llegado la hora, $c. Ahora que Ventormenta es segura, llevaremos la lucha al enemigo. ¡A las Tierras Altas!$b$bGracias a tus actos, la mayoría de la marina ya ha zarpado, pero Fargo Cierrasílex ha preparado un hidroavión que puede realizar el mismo viaje en un santiamén.$b$bHabla con Cierrasílex en el puerto y cuéntale que le acompañarás hasta las Tierras Altas. Estará cerca del agua. Buen viaje, $n.', '', '', '', '', '', '', '', '', '', 'Habla con: Kurdran Martillo Salvaje. Zona: Bancalto, Tierras Altas Crepusculares.', 0),
(28239, 'esMX', 'En el Cobertizo Diente Negro', 'Habla con el intendente Kaoshin en el Cobertizo Diente Negro en Las Estepas Ardientes.', 'No es precisamente el disfraz más... convincente que he visto en mi vida, pero funcionará. De todos modos, el trabajo encubierto consiste en echarle cara. Tú solo actúa como si debieras estar ahí, y todo irá bien.$b$bTu contacto en el interior del Cobertizo Diente Negro será un orco llamado intendente Kaoshin. Él NO sabe que eres $gun:una; espía, así que trata de mantener la calma.$b$bHaz todo lo que Kaoshin te pida. El coronel Troteman estará en contacto a través de la gnomograbadora para darte cualquier instrucción especial.$b$bBuena suerte ahí fuera, soldado.', '', '', '', '', '', '', '', '', '', '', 0),
(28241, 'esMX', 'Una visión crepuscular', 'Encuentra un Ojo del Crepúsculo en la Brecha Negra.', 'Cho\'gall les sigue el rastro a sus esbirros a través de esas extrañas bolas mágicas: "los Ojos del Crepúsculo".$B$BSi pudiera hacerme con uno de esos, seguro que podría usarlo para espiar a Cho\'gall y ver a qué se dedican sus monstruos. ¡Consígueme uno!$B$BRegistra la Brecha Negra, al este de aquí y justo al norte del río. Encuéntrame un Ojo del Crepúsculo y haz lo que sea necesario para traérmelo.', '', '', '', '', '', '', '', '', '', 'Encuentra: Ojo del Crepúsculo. Zona: Brecha Negra.', 0),
(28242, 'esMX', 'Todos tenemos que sacrificarnos', 'Mata a 10 chamanes de lo Oscuro.', '<El ojo te habla, su \'voz\' resuena como si viniera de todas partes al mismo tiempo.>$b$b¿Buscas mi visión, $r? Mis poderes tienen un precio. Esos discípulos Crepusculares me han estado honrando con la sangre de los enanos Martillo Salvaje de las ruinas que hay cerca de aquí, pero aún estoy sediento. Tal vez puedas hacerlo mejor.$B$BMata a mis antiguos amos y mi visión será tuya. Hónrame con la muerte de los chamanes de lo Oscuro. La sangre es sangre, después todo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ojo del Crepúsculo. Zona: La Brecha Negra, Tierras Altas Crepusculares.', 0),
(28243, 'esMX', 'El truco está en los ojos', 'Llévale el Ojo del Crepúsculo al chamán inferior Blundy en Bramal, en las Tierras Altas Crepusculares.', 'Muy bien, $r. Has comprado mis servicios con sangre. Llévame de vuelta con el "chamán inferior" de Bramal.$B$BOh sí, ya sé a dónde me llevas. Blundy es necio, las facultades empapadas de cerveza son triviales. Pero tú... tú me fascinas, $r. Con mi visión y tus facultades, imagina el caos que podríamos desatar juntos en este patético mundo...', '', '', '', '', '', '', '', '', '', 'Lleva el Ojo del Crepúsculo a: Chamán inferior Blundy. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(28244, 'esMX', 'Ojo espía', 'Mira por el Ojo del Crepúsculo para el chamán inferior Blundy.', 'Seré sincero, $n. Esa cosa me pone los nervios de punta. Pero ya que te tomaste la molestia de traerla hasta aquí, supongo que deberíamos darle un buen uso.$B$BTú primero.$B$BMira el ojo fijamente y pídele que te deje ver el interior de El Bastión del Crepúsculo de Cho\'gall. Descubriremos lo que planea ese indeseable de dos cabezas y lo usaremos en su contra. ', '', 'Has mirado por el ojo', '', '', '', '', '', '', '', 'Habla con: Chamán inferior Blundy. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(28245, 'esMX', 'Trabajo de recluta', 'Sácale brillo a 7 pares de botas Roca Negra.', '¡Bah! Tienes suerte de que me falte gente hoy. Si no te convertiría en $gel chico:la chica; de los azotes de la semana.$b$bLos oficiales y los soldados de alto rango necesitan que le saquemos brillo a sus botas. Las han dejado fuera de sus cabañas.$b$b¡Quiero verme reflejado en esas botas, recluta! ¡Manos a la obra!', '', 'Pares de botas Roca Negra brillantes', '', '', '', '', '', '', '', 'Vuelve con: Intendente Kaoshin. Zona: Cobertizo Diente Negro, Las Estepas Ardientes.', 0),
(28246, 'esMX', 'Recortes estratégicos', 'Usa la púa de escórpido afilada con el vuduista Timan en lo alto de El Pilar de Ceniza, con la maestra de huargos Othana en los cubiles de los huargos y con Gorlop cuando esté cerca de los charcos de lava.', '<Sonido eléctrico> $n... $n, ¿me oyes? Te habla Troteman.$b$bEscucha, acabamos de recibir la última información de inteligencia concerniente a tu siguiente misión. Queremos que acabes con tres elementos importantes. El primero es el vuduista Timan, al que encontrarás en lo alto de El Pilar de Ceniza. La maestra de huargos Othana se encuentra en los cubiles huargos centrales. Y por último, Gorlop está cerca de los charcos de lava, al sur.$b$bEncontrarás las púas de escórpido que recogiste junto con tus pertenencias. Usa las púas en los objetivos en el momento adecuado.', '', '', '', '', '', '', 'Coronel Troteman', 'No se te dan mal los objetos punzantes, colega.', 'Coronel Troteman', '', 0),
(28247, 'esMX', 'La última de su especie', 'Mata a Obsidia.', 'Obsidia es una de las últimas dragonas maduras que pueden perpetuar el linaje del Vuelo Negro. Debe morir.$B$BSi consigues matarla, informa de inmediato a Lirastrasza de tu victoria. Lleva mucho tiempo luchando para conseguir esto.$B$BGracias por ser nuestro colmillo en estas batallas. Has resultado ser $gun aliado:una aliada; muy útil.', 'Obsidia derrotada', '', '', '', '', 'Obsidia derrotada', 'Obsidia', '', '', 'Habla con: Lirastrasza. Zona: Noroeste del Bosque Obsidiana, Tierras Altas Crepusculares.', 0),
(28248, 'esMX', 'Paso del Invicto', 'Habla con Kurdran Martillo Salvaje en el Paso del Invicto.', 'Tu empeño y tus facultades están más que demostrados. Con Grim Batol bloqueada y los dragones negros expulsados, el Martillo Crepuscular está acorralado en su ciudadela.$B$BVe con tus líderes. Los encontrarás al noroeste, en el Paso del Invicto. Hazles saber que cuando comience su ataque contra la Ciudadela Crepuscular, el Vuelo Rojo cubrirá el cielo. Puede que no puedas compensarnos por todos los pecados que han cometido tus aliados, pero, en esta batalla, estaremos de tu lado.$B$BEl Martillo Crepuscular caerá.', '', '', '', '', '', '', '', '', '', '', 0),
(28249, 'esMX', 'Machacolpe', 'Habla con la señora de la guerra Zaela en Machacolpe.', 'Tu empeño y tus facultades están más que demostrados. Con Grim Batol bloqueada y los dragones negros expulsados, el Martillo Crepuscular está acorralado en su ciudadela.$B$BVe con tus líderes. Los encontrarás al oeste, en Machacolpe. Hazles saber que cuando comience su ataque contra la Ciudadela Crepuscular, el Vuelo Rojo cubrirá el cielo. Puede que no puedas compensarnos por todos los pecados que han cometido tus aliados, pero, en esta batalla, estaremos de su lado.$B$BEl Martillo Crepuscular caerá.', '', '', '', '', '', '', '', '', '', '', 0),
(28250, 'esMX', 'Extirpadores ladrones', 'Acaba con 30 pigmeos de arena con la marra de la dinastía Tahret.', 'No tengo el trabajo más glamuroso del mundo.$B$BNo me preocupo demasiado de los asuntos bélicos ni de los profundos misterios de las cámaras de Uldum ni nada de eso.$B$BEstoy al cargo de estas tierras... y estas tierras producen dátiles.$B$BPero estos malandrines extirpadores de dátiles se han vuelto lo bastante audaces como para subirse unos sobre los hombros de otros para tratar de robarme mis valiosos frutos.$B$BNo lo permitiré.$B$BCoge esta marra creada por los titanes, bendita por los reyes del sol y no sé qué más, y ¡acaba con esos bichos!', '', 'Extirpadores ladrones asesinados', '', '', '', '', '', '', '', 'Vuelve con: Nomarca Teneth. Zona: Tierras de Tahret.', 0),
(28251, 'esMX', 'Problemas en Costasur', 'Habla con Serge Hinott en las Ruinas de Costasur, en las Laderas de Trabalomas.', 'Antes de que me capturaran y encerraran estaba destacado en Costasur. Mi trabajo principal en las ruinas era tomar muestras de baba y asegurarme de que el añublo que liberábamos se disipaba con seguridad. Habría sido fácil y sencillo si no fuera por los huargen que no dejaban de acosarnos.$b$bQuiero que vayas a Costasur y busques a mi aprendiz, Serge Hinott. Asegúrate de que está bien y dile que volveré en cuanto haya terminado de trabajar aquí.$b$bEncontrarás las Ruinas de Costasur al sureste, cerca de la costa.', '', '', '', '', '', '', '', '', '', '', 0),
(28252, 'esMX', 'El cuerno de clamakodo', 'Usa el cuerno de los clamadores para llamar a 7 kodos de guerra Roca Negra para que vuelvan al campamento. Si algún kodo se vuelve hostil, lucha con él hasta someterlo.', 'Vale, tengo un trabajo realmente legítimo e importante para ti. Tenemos que llamar a los kodos que se encuentran en los pastos del sur. El General Thorg\'izog dice que avanzaremos pronto hacia Crestagrana; y no pienso permitir que falten kodos en mis filas.$b$bUsa este cuerno cerca de un kodo. Y volverá al campamento en cuanto oiga la llamada.$b$bPero ten cuidado. A veces los kodos son un poco peleones, así que tendrás que golpearlos un poco para que te hagan caso.', '', 'Kodos de guerra Roca Negra convocados de vuelta al campamento', '', '', '', '', '', '', '', '', 0),
(28253, 'esMX', 'Quedarnos con el cuerno', 'Devuelve el cuerno de los clamadores al coronel Troteman en Cincelada, en Las Estepas Ardientes.', '$n, soy Troteman. Quiero que te quedes con ese cuerno. Estoy seguro de que podemos improvisar y sacarle provecho para nuestro plan.$b$bEstoy bastante preocupado por lo que dijo Kaoshin sobre atacar Crestagrana. Sabíamos que nos esperaba otro ataque inminente, pero nuestros calendarios diferían en varios días.$b$bVuelve conmigo y tráeme el cuerno. Volveremos a hablar aquí, en Cincelada. Y trata de no estropear el disfraz. Todavía no has acabado tu operación encubierta.', '', '', '', '', '', '', 'Coronel Troteman', '', '', 'Preséntate ante el coronel Troteman. Zona: Cincelada, Las Estepas Ardientes.', 0),
(28254, 'esMX', 'Una aguja en el infierno', 'Habla con Thelaron Malaguja en Cincelada en Las Estepas Ardientes.', 'Tú y yo no podemos con un ejército, $n. Nos aplastarían. Por eso tenemos que seguir el plan de Troteman.$b$bLa siguiente parte del plan va a requerir cierta sutileza... algo en lo que yo no destaco precisamente. Y ahí es donde entras tú.$b$bHabla con Thelaron Malaguja, el sastre de la ciudad. Ya le he dado los pellejos y el barro que hemos recogido. Tendrá que tomarte medidas.$b$bEso es, $n: será una misión encubierta.', '', '', '', '', '', '', '', '', '', '', 0),
(28256, 'esMX', 'La calavera de Gul\'dan', 'Revive la batalla de Illidan por conseguir la calavera de Gul\'dan.', 'Illidan fue en busca de la calavera de Gul\'dan. Luchó contra ejércitos de demonios para alcanzarla, matándolos con el poder que lo convirtió en un odiado paria.$B$BObsérvalo en la batalla, $c. Contempla al que luchó con más ahínco contra los corruptores de Frondavil y asestó un golpe en su mismísima fuente.', 'Calavera de Gul\'dan conseguida', '', '', '', '', 'Calavera de Gul\'dan conseguida', '', '', '', 'Vuelve con: Feronas Morapecado. Zona: Frondavil.', 0),
(28257, 'esMX', 'La caída de Tichondrius', 'Revive la batalla de Illidan con Tichondrius.', 'Sí, Illidan tomó el poder de la calavera de Gul\'dan para sí mismo.$B$BPero, ¿huyó con ella en la noche? ¿La usó para su propia gloria? No... ¡su primera acción fue usar su nuevo poder para atacar al Señor del Terror Tichondrius!$B$BContempla su triunfo, $C. Contempla cómo Illidan reclamó Frondavil a los demonios... y el agradecimiento que le dieron.', 'Tichondrius derrotado', '', '', '', '', 'Tichondrius derrotado', 'Tichondrius', '', '', 'Vuelve con: Feronas Morapecado. Zona: Frondavil.', 0),
(28258, 'esMX', 'Reunión con Ander Germaine', 'Habla con Ander Germaine en el Centro de Mando, al sur del Casco Antiguo de Ventormenta.', 'Ander Germaine te ha enviado un mensaje. Quiere que te reúnas con él en su base de operaciones, el Centro de Mando del Casco Antiguo de Ventormenta, en cuanto puedas. Parecía importante, $n.', '', '', '', '', '', '', '', '', '', 'Habla con Ander Germaine en el Centro de Mando, al sur del Casco Antiguo de Ventormenta.', 0),
(28259, 'esMX', 'Reunión con Demisette Cloyce', 'Habla con Demisette Cloyce en el sótano del Cordero Degollado, en el Barrio de los Magos de Ventormenta.', 'Acabo de recibir un pergamino de Demisette Cloyce, de Ventormenta. Quiere que le hagas una visita al Cordero Degollado en Ventormenta. No da más detalles, pero me da la impresión de que se trata de algo importante.', '', '', '', '', '', '', '', '', '', 'Habla con Demisette Cloyce en el sótano del Cordero Degollado, en el Barrio de los Magos de Ventormenta.', 0),
(28260, 'esMX', 'Reunión con Wulf Hansreim', 'Habla con Wulf Hansreim en el Centro de Mando, al sur del Casco Antiguo de Ventormenta.', 'Wulf Hansreim ha enviado un mensaje desde Ventormenta: quiere reunirse contigo de inmediato. Está en el Centro de Mando, justo al sur del Casco Antiguo de Ventormenta.', '', '', '', '', '', '', '', '', '', 'Habla con Wulf Hansreim en el Centro de Mando, al sur del Casco Antiguo de Ventormenta.', 0),
(28261, 'esMX', 'Impostores entre nosotros', 'Mata a 12 transfiguradores Fuego de Jade en el camino Fuego de Jade.', 'Ahora que has recibido una lección en cuanto a tener una mente abierta, puede que quieras saber POR QUÉ maté a esos druidas.$B$BLa respuesta es simple: no eran druidas en absoluto.$B$BAún hay demonios en las ruinas, ocultándose a plena vista bajo la apariencia de custodios amistosos. Velo tú $gmismo:misma;... Esta venda está empapada en sangre de demonio. Llévale al norte, por las colinas, al camino Fuego de Jade y póntela sobre los ojos. Le mostrará la verdadera naturaleza de cualquier demonio hasta al más tonto de remate.', '', '', '', '', '', '', '', 'No bebas demasiado la primera vez.', 'Feronas Morapecado', 'Vuelve con: Feronas Morapecado. Zona: Frondavil.', 0),
(28262, 'esMX', 'Reunión con Lord Tony Romano', 'Habla con Ander Germaine en el Centro de Mando, al sur del Casco Antiguo de Ventormenta.', 'Lord Tony Romano, uno de los principales instructores de pícaros del IV:7 de Ventormenta, ha enviado un mensaje diciendo que desea hablar contigo. Dirígete a Ventormenta en cuanto puedas y búscalo en el edificio del IV:7, justo al sur del Casco Antiguo.', '', '', '', '', '', '', '', '', '', 'Habla con Lord Tony Romano en la sede del IV:7, al sur del Casco Antiguo de Ventormenta.', 0),
(28263, 'esMX', 'Reunión con Maginor Dumas', 'Habla con Maginor Dumas en el Sagrario del Mago, en el Barrio de los Magos de Ventormenta.', 'Acabo de recibir un mensaje de Maginor Dumas, el instructor jefe de los magos de Ventormenta. Te pide que te reúnas con él en el Sagrario del Mago, en Ventormenta, en cuanto llegues a la ciudad.', '', '', '', '', '', '', '', '', '', 'Habla con Maginor Dumas en el Sagrario del Mago, en el Barrio de los Magos de Ventormenta.', 0),
(28264, 'esMX', 'La estrategia de Navarax', 'Mata al demonio que se hace pasar por el archidruida Navarax.', 'Llevo bastante tiempo observando a esos impostores demoníacos y por fin he descubierto el paradero de su líder. No es otro que el archidruida Navarax, el líder del Círculo Esmeralda.$B$BEse demonio se escuda en inocentes. Si fuera a cazarlo a la Arboleda Susurravientos, se me echarían encima protectores ignorantes... ¡pero tú, tú puedes cogerlo desprevenido!$B$BVuelve a la Arboleda Susurravientos. Escala la torre del druida y encontrarás a Navarax en lo alto, en su habitación entre las ramas.', '', '', '', '', '', '', 'Archidruida Navarax', '', '', 'Vuelve con: Cazadora Selura. Zona: Arboleda Susurravientos, Frondavil.', 0),
(28265, 'esMX', 'General Thorg\'izog', 'Habla con el General Thorg\'izog.', 'Kaoshin resultó ser más útil de lo que esperaba, pero ya hemos acabado con él. Ha llegado el momento de que hables con el general. Creo que estás $gpreparado:preparada;.$b$bEl General Thorg\'izog es uno de los "Tres Grandes" que lideran las fuerzas de tierra aquí en Las Estepas Ardientes. Las dirige desde el Bastión de Roca Negra al noroeste. Ponte tu disfraz y ve a hablar con él. Intenta ganarte su confianza. Troteman se mantendrá en contacto, en caso de que necesitemos algo más de ti.', '', '', '', '', '', '', '', '', '', 'Preséntate ante el General Thorg\'izog en el Bastión de Roca Negra en Las Estepas Ardientes.', 0),
(28266, 'esMX', 'Prueba de magma', 'Habla con Wyrtle Mercenacero y pídele que libere al Señor del Magma Kolob. Después derrota al Señor del Magma Kolob en una batalla.', 'Supongo que sacaré el mayor provecho a esta situación. Los mercenarios globlin trajeron a estos enormes elementales de fuego a mi fortaleza en señal de agradecimiento por haberlos contratado. ¿Qué voy a hacer con un elemental aquí en las estepas? Es como llevar arena a la playa.$b$bSi buscas trabajo, demuestra lo que vales. Habla con este goblin de aquí y desafía a su elemental para enfrentarte con él. El ganador conseguirá mi respeto y mi tiempo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: General Thorg\'izog. Zona: Bastión de Roca Negra, Las Estepas Ardientes.', 0),
(28267, 'esMX', 'Pelotón de ejecución', 'Habla con el comandante Schnottz.', 'Fuelfe fuerra conmigo, $r.$b$bQuierro fer una cosa.', '', 'Has \'fuelto fuerra\' con Schnottz', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Embarcadero de Schnottz.', 0),
(28268, 'esMX', 'Reunión con Lord Grisillo Quiebrasombras', 'Habla con Lord Grisillo Quiebrasombras en la Catedral de la Luz, en el Distrito de la Catedral de Ventormenta.', 'Lord Grisillo Quiebrasombras, de la Catedral de la Luz, ha enviado un mensaje preguntando por ti. Quiere hablar contigo la próxima vez que pases por la ciudad. Seguramente estará en el Distrito de la Catedral.', '', '', '', '', '', '', '', '', '', 'Habla con Lord Grisillo Quiebrasombras en la Catedral de la Luz, en el Distrito de la Catedral de Ventormenta.', 0),
(28269, 'esMX', 'Encuéntrate conmigo en Vir\'sar', 'Habla con Harrison Jones en el Oasis de Vir\'sar.', 'Escucha esto, $n.$b$bSabía que estos obeliscos estaban ligados al Arca de la promesa, pero aún hay más.$b$bParece haber algo muy importante respecto al arca: algo relacionado con un lugar que los Creadores llamaron las Cámaras de los Orígenes.$b$bAhora que sabemos que Schnottz y su cuadrilla están aliados con Alamuerte, es mucho más urgente que lleguemos allí antes que ellos.$b$bTe esperaré al norte de aquí, en el Oasis de Vir\'sar$b$b¡Date prisa! ¡Nos llevan ventaja!|n', '', '', '', '', '', '', '', '', '', '', 0),
(28271, 'esMX', 'Productividad reducida', 'Mata a 15 excavadores de Schnottz o sobrestantes de Schnottz.', 'Vale, $n, esto es lo que he descubierto.$b$bHay un pequeño dispositivo titánico en las profundidades de un lugar llamado las Cámaras de los Orígenes. Se trata de un interruptor de regeneración de toda la vida existente en Azeroth. ¡Si se activa, destruirá a todo ser viviente del mundo!$b$bSe supone que solo debe usarse en condiciones extremas, pero si Alamuerte consigue corromper a los vigías titánicos, podría utilizar el contenido del arca para activar el dispositivo.$b$bDirígete al Obelisco de la Luna, $n. ¡Frena su avance!', '', 'Empleados de Schnottz muertos en el Obelisco de la Luna', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Oasis de Vir\'sar.', 0),
(28272, 'esMX', 'Las piezas que faltan', 'Reúne 7 pergaminos de cobre antiguo.', 'Solo me faltan unas piezas del rompecabezas.$b$bUna vez que las consigamos, podremos activar el obelisco final. Entonces la cosa se convertirá en una carrera contra Schnottz y sus compinches para localizar el Arca de la promesa.$b$bEsos estúpidos están excavando este lugar a toda velocidad. ¡Corren más que saquean!$b$bVe al obelisco y busca entre su botín, $n.$b$bMira a ver si encuentras las piezas que nos faltan.', '', '', '', '', '', '', '', '', '', 'Habla con: Harrison. Zona: Oasis de Vir\'sar.', 0),
(28273, 'esMX', 'Un amigo de un amigo', 'Harrison quiere que hables con Sullah en el Oasis de Vir\'sar.', 'Tengo que deshacer la maleta y recorrer un poco la zona. Mientras tanto, quiero que conozcas a un viejo amigo.$b$bSullah y yo nos conocemos desde hace mucho tiempo. Es un tipo en quien se puede confiar; y eso no es nada habitual hoy en día.$b$b¿Por qué no vas y te presentas?', '', '', '', '', '', '', '', '', '', '', 0),
(28274, 'esMX', 'Dos tiendas', 'Acompaña a Sullah hasta el Puesto de Sullah.', 'Mírate, $gamigo mío:amiga mía;. ¡Esta gran aventura tuya te tiene $ghecho:hecha; polvo!$b$bTienes que relajarte un poco. Estás demasiado $gtenso:tensa; y así solo vas a conseguir cansarte.$b$bConfía en mí, ¡sé lo que es la relajación!$b$bY hablando de tiendas, veo que el pequeño Jones me trajo las que pedí.$b$bVen, $gamigo:amiga;. ¡Únete a mí!', '', 'Has acompañado a Sullah', '', '', '', '', '', '', '', 'Habla con: Sullah. Zona: Puesto de Sullah.', 0),
(28275, 'esMX', '¡Bombas fuera!', 'Destruye 10 barcos de suministros espantosos.', 'El astillero de Wellson está recibiendo suministros constantemente por mar y tenemos que acabar con eso. Han colocado cañones a lo largo del embarcadero para defenderse, pero si consigues llegar hasta ellos, podremos usarlos para destruir sus barcos de suministros.$B$BDirígete hasta allí y averigua lo que puedes hacer. Infórmame de tus avances.', '', 'Barcos de suministros de Wellson destruidos', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el sargento Gray en el Campamento de Baradin cuando termines.', 0),
(28276, 'esMX', 'El secreto de Salhet', 'Encuéntrate con Salhet en el extremo sur del Monte del Vigía, en Uldum.', 'Escucha, $n. Antes de que te des por $gvencido:vencida; conmigo, quiero enseñarte algo.$B$BVerás, no soy un gran luchador. No tengo muy buena coordinación.$B$BSoy más bien una mente táctica.$B$BEncuéntrate conmigo en el límite sur del monte y te lo enseñaré.', '', '', '', '', '', '', '', '', '', '', 0),
(28277, 'esMX', 'Salhet el estratega', 'Habla con Salhet y asesina a 30 carroñeros Gruñido sangriento.', 'Desde que era un cachorro, siempre he querido ser general.$B$BEstaba deseando alistarme en el ejército. Pero como has podido comprobar, mis habilidades de combate no son precisamente brillantes.$B$BEsta no es la primera vez que me mandan a cazar hienas. De hecho, me envían aquí tan a menudo, que me he hecho amigo de estos leones y los he entrenado para que hagan lo que yo les mando.$B$BSon mis soldados, y bajo mi mando matarán a legiones de hienas. ¡Observa!', '', 'Carroñero Gruñido Sangriento asesinado', '', '', '', '', '', '', '', 'Vuelve con: Salhet. Zona: Monte del Vigía del Sol, Uldum.', 0),
(28278, 'esMX', 'Yo soy la ley y yo soy el látigo', 'Usa la cayada de disciplina Roca Negra con 20 soldados de asalto en los Campos de Honor. Si uno de los soldados descubre tu disfraz, mátalo a golpes antes de que pueda desvelar tu identidad.', 'Llevo tiempo buscando a $gun buen:una buena; soldado fuerte como tú. Necesito a alguien que mantenga a raya a mis tropas.$b$bEn el exterior del bastión encontrarás orcos, ogros y trols que se preparan para atacar Crestagrana. Mis sargentos los mantienen a raya, pero me gustaría que los ayudases.$b$bCoge esta cayada y disciplina a algunos de mis soldados. Me da igual si se estaban comportando mal o si estaban perfectamente formados; quiero que los golpees. Quiero que se concentren, que se curtan en la batalla y que sean obedientes.$b$bY ahora, vete.', '', 'Esbirros Roca Negra golpeados', '', '', '', '', '', '', '', 'Vuelve con: General Thorg\'izog. Zona: Bastión de Roca Negra, Las Estepas Ardientes.', 0),
(28279, 'esMX', 'Abuso de poder', 'Mata a 5 sargentos Roca Negra con la cayada de disciplina Roca Negra. Derrótalos rápidamente; antes de que puedan desenmascararte.', '¿$n? Aquí Troteman.$b$bParece que te has ganado la confianza de Thorg\'izog; y que te ha asignado una tarea de disciplina. Eso está muy bien.$b$bNecesitamos que acabes con sus sargentos. Los encontrarás a lomos de sus lobos, en el exterior del Bastión de Roca Negra en los Campos de Honor. Usa la cayada con ellos, varias veces, hasta que mueran. Tendrás que actuar con rapidez porque si se dan cuenta de que no eres uno de ellos, podrían desenmascararte. Golpea rápida y ferozmente, $n.$b$bTroteman, corto y cierro.', '', 'Sargento Roca Negra asesinado', '', '', '', '', 'Coronel Troteman', '¡Ja, ja, ja! ¡Buen trabajo!', 'Coronel Troteman', '', 0),
(28280, 'esMX', 'Hazlos desaparecer del cielo', 'Usa el derribadracos cargado a hombros para matar a 8 dracos negros Faucedraco.', '¡Ah! ¡Ya están aquí, $n, ya están aquí!$B$BEsperaba poder equipar a todo un ejército con mi derribadracos cargado a hombros, pero solo tengo un prototipo sin probar extremadamente caro. Ten, ¡cógelo!$B$B¡Dispara a los dracos negros Faucedraco que están sobrevolando Bramal y hazlos caer del cielo!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Nivvet Acequial. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(28281, 'esMX', 'La última batalla de Bramal', 'Mata a 8 garras del cielo Faucedraco que vayan a pie.', 'Tengo que reconocerte el mérito a ti y a tus amigos de la Alianza. ¡Les han dado una paliza a los Faucedraco!$B$BMuchos de sus jinetes han sido derribados pero siguen viniendo contra nosotros, y, sin ayuda, mis defensores se verán superados.$B$B¡Mata a los garras del cielo Faucedraco que vayan a pie y Bramal estará eternamente en deuda contigo!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Colin Bramal. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(28282, 'esMX', 'Narkrall, el domador de dracos', 'Mata a Narkrall Rasgarra. Habla con Colin Bramal cuando estés $glisto:lista;.', 'Hay un Faucedraco en este grupo, aquel al que llaman "Narkrall: el domador de dracos." No sé de dónde saca el poder que tiene sobre esas bestias pero el terror negro que monta es una mala bestia como no se había visto nunca en los cielos que cubren las Tierras Altas.$B$B$n, Narkrall es el villano que le quitó la vida a mi padre y dejó Bramal en mis manos.$B$BNo puedo enfrentarme a él solo, pero he visto de lo que eres capaz, $c. Tal vez juntos podamos ponerle fin a esto.$B$BAvísame cuando estés $glisto:lista; ¡y lucharemos contra Narkrall juntos!', '', '', '', '', '', '', 'Narkrall Rasgarra', '', '', 'Habla con: Colin Bramal. Zona: Bramal, Tierras Altas Crepusculares.', 0),
(28283, 'esMX', '¿Qué es ese repiqueteo?', 'Inspecciona el sonajero de huesos en la Cumbre de la Nube Negra, en Las Mil Agujas.', '¿Has visto ese sonajero resplandeciente en el suelo, frente a la cabaña de Isha?', '', '', '', '', '', '', '', '', '', '', 0),
(28284, 'esMX', '¿Qué es ese repiqueteo?', 'Inspecciona el sonajero de huesos en la Cumbre de la Nube Negra, en Las Mil Agujas.', '¿Has visto ese sonajero resplandeciente en el suelo, frente a la cabaña de Isha?', '', '', '', '', '', '', '', '', '', '', 0),
(28285, 'esMX', 'Reunión con la suma sacerdotisa Laurena', 'Habla con la suma sacerdotisa Laurena en la Catedral de la Luz, en el Distrito de la Catedral de Ventormenta.', 'Acabo de recibir un pergamino de la Catedral de la Luz, $n. La suma sacerdotisa Laurena nos ha comunicado que desea hablar contigo. Deberías ir a verla lo antes posible.', '', '', '', '', '', '', '', '', '', 'Habla con la suma sacerdotisa Laurena en la Catedral de la Luz, en el Distrito de la Catedral de Ventormenta.', 0),
(28286, 'esMX', 'Suficiente daño para un día', 'Vuelve con el Coronel Troteman en Cincelada.', 'Ya no tenemos ninguna necesidad estratégica de Thorg\'izog ni de las tropas de tierra de Roca Negra. Debemos pasar a la siguiente fase del plan.$b$bCuando hayas acabado en el fuerte, regresa con nosotros aquí a Cincelada.', '', '', '', '', '', '', 'Coronel Troteman', '', '', 'Preséntate ante el Coronel Troteman en Cincelada en Las Estepas Ardientes.', 0),
(28287, 'esMX', 'Reunión con la clarividente Umbrua', 'Habla con la clarividente Umbrua en el Tonel Dorado, en el Distrito de los Enanos de Ventormenta.', 'Acabo de hablar con un mensajero de la clarividente Umbrua, $n. Hay un asunto importante que quiere discutir contigo y dice que te reúnas con ella en el Tonel Dorado, en el Distrito de los Enanos de Ventormenta, en cuanto puedas.', '', '', '', '', '', '', '', '', '', 'Habla con la clarividente Umbrua en el Tonel Dorado, en el Distrito de los Enanos de Ventormenta.', 0),
(28288, 'esMX', 'Abre sus ojos', 'Usa el prisma de Delaris para aterrorizar a 20 diablillos Fuego de Jade.', 'Antes de que te vayas...$B$BHe aprovechado mi "tiempo a solas" con Diblis para aprender más cosas sobre los diablillos. Concretamente, acabó diciéndome lo que más temen los diablillos. Algo que los aterroriza por completo.$B$BMe pareció útil a la vez que interesante, así que he hecho algunos conjuros básicos. Este prisma proyectará una imagen de... bueno, de lo que Diblis describió.$B$BLa Cresta Acechumbra aún está llena de diablillos. ¿Por qué no me haces el favor de ir a comprobar su reacción?', '', 'Diablillos aterrorizados', '', '', '', '', '', '', '', 'Vuelve con: Arcanista Delaris. Zona: Ruinas de Constellas, Frondavil.', 0),
(28289, 'esMX', 'La llamada del Claro de la Luna', 'Ve a Claro de la Luna y habla con Loganaar en Amparo de la Noche.', 'Acabo de saber que nuestros hermanos de Claro de la Luna han solicitado tu ayuda, $n. Deberías viajar hasta allí y hablar con Loganaar, en Amparo de la Noche. Él te dirá todo lo que debes saber.', '', '', '', '', '', '', '', '', '', 'Ve a Claro de la Luna y habla con Loganaar en Amparo de la Noche.', 0),
(28290, 'esMX', 'Reunión con Grezz Puñofuria', 'Habla con Grezz Puñofuria en el Valle del Honor de Orgrimmar.', 'Grezz Puñofuria ha enviado un mensaje urgente preguntando por ti, $n. Quiere que te reúnas con él inmediatamente en el Valle de los Héroes de Orgrimmar. Debe de tener una misión importante para ti.', '', '', '', '', '', '', '', '', '', 'Habla con Grezz Puñofuria en el Valle del Honor de Orgrimmar.', 0),
(28291, 'esMX', 'Volver al campamento', 'Vuelve con el alto comandante Kamses en la Avanzada de la Legión Ramkahen.', '¿Tú qué crees, $n? Tal vez el Alto comandante me asigne unos cuantos hombres a los que dirigir.$B$BTal vez podamos reunir un regimiento juntos. ¿Qué te parece?', '', '', '', '', '', '', '', '', '', '', 0),
(28292, 'esMX', '¡Eso no es una pirámide!', 'Habla con Harrison Jones en el Castillo de Ventormenta en la Ciudad de Ventormenta.', 'La pirámide del Bancal del Hacedor en Uldum no es nada corriente. Es una máquina gigante que se puede reconfigurar para multitud de usos. $b$b¡Alamuerte iba a ordenarle al Martillo Crepuscular que la convirtiera en un arma de destrucción masiva!$B$B$n, tienes que usar el portal para llevarle esta información a Harrison Jones en Ventormenta. Él sabrá lo que hay que hacer.', '', '', '', '', '', '', '', '', '', '', 0),
(28293, 'esMX', '¡Eso no es una pirámide!', 'Habla con Belloc Hoja Brillante en el Fuerte Grommash en Orgrimmar.', 'La pirámide del Bancal del Hacedor en Uldum no es nada corriente. Es una máquina gigante que se puede reconfigurar para multitud de usos. $b$b¡Alamuerte iba a ordenarle al Martillo Crepuscular que la convirtiera en un arma de destrucción masiva!$B$B$n, tienes que usar el portal para llevarle esta información a Belloc Hoja Brillante en el Fuerte Grommash, en Orgrimmar. Él sabrá lo que hay que hacer.', '', '', '', '', '', '', '', '', '', '', 0),
(28294, 'esMX', 'La cumbre de Kirthaven', 'Habla con Lachlan MacGraff en Kirthaven, en las Tierras Altas Crepusculares.', 'Después de la paliza que les hemos dado, los ataques de los Faucedraco contra Bramal deberían parar. Puede que sí que haya un sitio para los Martillo Salvaje en tu Alianza: desde luego los Bramal estamos en deuda contigo.$B$BArriba, en Kirthaven, nuestro gran chamán, Lachlan MacGraff ha estado intentando organizar una cumbre entre los líderes supervivientes de las familias Martillo Salvaje. Es mucho pedir que nos pongamos de acuerdo para trabajar juntos, pero al menos estoy dispuesto a intentarlo.$B$BVuela hasta Kirthaven, hacia el norte, y habla con Lachlan MacGraff. ¡Nos vemos allí!', '', '', '', '', '', '', '', '', '', 'Habla con: Lachlan MacGraff. Zona: Kirthaven, Tierras Altas Crepusculares.', 0),
(28295, 'esMX', 'Encuentro con la caravana', 'Habla con Adarrah en el Valle Cardizal en Tanaris.', 'La pirámide que hay dentro del Bancal del Hacedor en Uldum se puede usar como superarma para acabar con todo rastro de vida en Azeroth.$B$B< Harrison piensa un momento.>$B$BTienes que continuar la investigación que has comenzado. Dirígete al extremo sur de Kalimdor, al Desierto de Tanaris. Hay una caravana que está a punto de partir hacia Uldum.$B$BQuizás te puedas acoplar.', '', '', '', '', '', '', '', '', '', '', 0),
(28296, 'esMX', 'Encuentro con la caravana', 'Habla con Adarrah en el Valle Cardizal en Tanaris.', 'La pirámide que hay dentro del Bancal del Hacedor en Uldum se puede usar como superarma para acabar con todo rastro de vida en Azeroth.$B$B<Belloc piensa un momento.>$B$BDebes continuar la buena investigación que has comenzado. Dirígete al sur, al Desierto de Tanaris. Hay una caravana que está a punto de partir hacia Uldum.$B$BQuizás te puedas acoplar.', '', '', '', '', '', '', '', '', '', '', 0),
(28297, 'esMX', 'Reunión con Ormak Tirosiniestro', 'Habla con Ormak Tirosiniestro en el Valle del Honor de Orgrimmar.', 'He recibido un pergamino para ti de Ormak Tirosiniestro, de Orgrimmar. Quiere que te dirijas al Valle del Honor y hables con él en cuanto puedas. Suena urgente, $n.', '', '', '', '', '', '', '', '', '', 'Habla con Ormak Tirosiniestro en el Valle del Honor de Orgrimmar.', 0),
(28298, 'esMX', 'Reunión con Gordul', 'Habla con Gordul en el Circo de las Sombras en Orgrimmar.', 'Gordul, líder de los pícaros de la Mano Destrozada en Orgrimmar, desea reunirse contigo. Ve rápidamente a Orgrimmar, $n, y búscalo en el Circo de las Sombras. Debe de tener una misión importante para ti.', '', '', '', '', '', '', '', '', '', 'Habla con Gordul en el Circo de las Sombras en Orgrimmar.', 0),
(28299, 'esMX', 'Reúnete con Kranosh', 'Habla con Kranosh en el Circo de las Sombras de Orgrimmar.', 'Acabo de saber de Kranosh, el principal instructor de brujos de Orgrimmar. Quiere que vayas a Orgrimmar y hables con él en el Circo de las Sombras. Suena como si tuviera una misión importante para ti.', '', '', '', '', '', '', '', '', '', 'Habla con Kranosh en el Circo de las Sombras de Orgrimmar.', 0),
(28300, 'esMX', 'Reunión con Ureda', 'Habla con Ureda en el Circo de las Sombras de Orgrimmar.', 'Acabo de recibir un pergamino de Orgrimmar para ti, $n. Es de Ureda, una de las instructoras de magos de la ciudad. Quiere que te reúnas con ella en el Circo de las Sombras de Orgrimmar la próxima vez que pases por la ciudad.', '', '', '', '', '', '', '', '', '', 'Habla con Ureda en el Circo de las Sombras de Orgrimmar.', 0),
(28301, 'esMX', 'Reúnete con Terga Rompesuelos', 'Habla con Terga Rompesuelos en el Valle de la Sabiduría de Orgrimmar.', 'Acabo de recibir un mensaje urgente dirigido a ti, $n. Es de Terga Rompesuelos, una de las instructoras de chamanes de Orgrimmar. Solicita tu presencia tan pronto como sea posible.', '', '', '', '', '', '', '', '', '', 'Habla con Terga Rompesuelos en el Valle de la Sabiduría de Orgrimmar.', 0),
(28302, 'esMX', 'Reunión con el caminasol Atohmo', 'Habla con el caminasol Atohmo en el Valle de la Sabiduría de Orgrimmar.', 'Deberías dirigirte a Orgrimmar en cuanto puedas, $n. El caminasol Atohmo nos ha comunicado que desea hablar contigo sobre un asunto de gran importancia para la Horda. Búscalo en el Valle de la Sabiduría.', '', '', '', '', '', '', '', '', '', 'Habla con el caminasol Atohmo en el Valle de la Sabiduría de Orgrimmar.', 0),
(28303, 'esMX', 'Reunión con el maestro Pyreanor', 'Habla con el maestro Pyreanor en Fuerte Grommash, en Orgrimmar.', 'El maestro Pyreanor te ha enviado un mensaje urgente, $n. Te pide que te reúnas con él en Fuerte Grommash, en el Valle de la Fuerza de Orgrimmar, la próxima vez que pases por la ciudad. Sonaba como si tuviera una tarea importante para ti.', '', '', '', '', '', '', '', '', '', 'Habla con: Maestro Pyreanor. Zona: Fuerte Grommash, Orgrimmar.', 0),
(28304, 'esMX', 'Reunión con la clériga oscura Cecille', 'Habla con la clériga oscura Cecille en Fuerte Grommash, en el Valle de la Fuerza de Orgrimmar.', 'La clériga oscura Cecille, miembro de la delegación de la Reina alma en pena en Orgrimmar, ha pedido que te reúnas con ella la próxima vez que estés en la ciudad. La encontrarás en el interior de Fuerte Grommash, en el Valle de la Fuerza de Orgrimmar. Debe ser algo importante para que te convoque directamente, $n.', '', '', '', '', '', '', '', '', '', 'Habla con la clériga oscura Cecille en Fuerte Grommash, en el Valle de la Fuerza de Orgrimmar.', 0),
(28305, 'esMX', 'El destino del Puesto del Veneno', 'Habla con Kelnir Hojacanto en el Puesto del Veneno.', 'Mientras nos ocupábamos de Jaedenar, envié a una amiga mía al norte, al Puesto del Veneno. Solíamos tener alguna que otra visita de los tauren que hay allí, pero últimamente han dejado de venir del todo.$B$BMi amiga, Kelnir Hojacanto, aún no ha regresado. ¿Podrías viajar al norte para ver cómo está y cuál es la situación en el Puesto del Veneno?$B$BSi la encuentras, ten cuidado... las dríades como ella suelen parecerles extrañas a las otras razas.', '', '', '', '', '', '', '', '', '', '', 0),
(28306, 'esMX', 'Arboleda Susurravientos', 'Habla con Tender Bosquepuro en la Arboleda Susurravientos.', '¡Nos has ayudado tanto aquí!$B$BMe quedaré aquí un rato y cuidaré del pobre señor Tauren hasta que deje de vomitar tanto. ¿Por qué no te diriges al norte a la Arboleda Susurravientos? ¡Aquello es muy bonito y los druidas son muy amables!$B$BDeberías decirle a la señorita Bosquepuro que estoy bien; se preocupará si tardo mucho en volver. ¡También puede que te pida que la ayudes con sus flores! ¡Es tan divertido!', '', '', '', '', '', '', '', '', '', '', 0),
(28307, 'esMX', 'Reunión con Tyelis', 'Habla con Tyelis en Fuerte Grommash, en el Valle de la Fuerza de Orgrimmar.', 'Tyelis, miembro de la delegación de Lunargenta en Orgrimmar, ha solicitado que te reúnas con él la próxima vez que vayas a la ciudad. Lo encontrarás en el interior de Fuerte Grommash, en el Valle de la Fuerza de Orgrimmar. Debe de ser algo importante para que te convoque de forma tan directa, $n.', '', '', '', '', '', '', '', '', '', 'Habla con Tyelis en Fuerte Grommash, en el Valle de la Fuerza de Orgrimmar.', 0),
(28308, 'esMX', 'Reunión con la vidente Liwatha', 'Habla con la vidente Liwatha en el Valle de la Sabiduría de Orgrimmar.', 'La vidente Liwatha te envía recuerdos desde el Valle de la Sabiduría de Orgrimmar, $n. Me ha pedido que te traslade una invitación a visitarla la próxima vez que pases por la ciudad. Sonaba como si tuviera algo importante que discutir contigo.', '', '', '', '', '', '', '', '', '', 'Habla con la vidente Liwatha en el Valle de la Sabiduría de Orgrimmar.', 0),
(28309, 'esMX', 'Reunión con el caminasombras Zuru', 'Habla con el caminasombras Zuru, en el Valle de los Espíritus de Orgrimmar.', 'El caminasombras Zuru, un venerado instructor de sacerdotes, ha pedido que te reúnas con él en Orgrimmar. Puedes encontrarlo en el Valle de los Espíritus con el resto de instructores Lanza Negra. Debe ser algo importante para que te haya hecho llamar de forma tan directa, $n.', '', '', '', '', '', '', '', '', '', 'Habla con el caminasombras Zuru, en el Valle de los Espíritus de Orgrimmar.', 0),
(28310, 'esMX', 'Vigilia de Morgan', 'Preséntate ante Oralius en Vigilia de Morgan en Las Estepas Ardientes.', 'Nuestro trabajo aquí en Cincelada ha terminado, en gran medida gracias a ti. Ahora nos desplazaremos hacia el este, a Vigilia de Morgan.$b$bNuestra información indica que Vigilia de Morgan ha sido desalojada, ya que la mayor parte de sus habitantes se han mudado a Montaña Roca Negra para enfrentarse contra los Roca Negra. Debería servir como base de operaciones para las fases finales de nuestro plan.$b$bPor supuesto, Keeshan se reunirá contigo en el camino. Igual que yo.', '', '', '', '', '', '', '', '', '', '', 0),
(28311, 'esMX', 'Cenizas negras', 'Consigue 9 montones de cenizas de obsidiana.', 'Necesito que recojas unas cuantas cosas más antes de que podamos ir a por lo que queda del ejército Roca Negra. Si vamos a hacerlo, más vale que lo hagamos bien; y eso significa que debemos estar preparados.$b$bNecesito ceniza, $n. No una ceniza cualquiera... ceniza de los mayores elementales obsidiana que merodean las mesetas del noroeste. Es una ceniza completamente negra, que es justo lo que necesitamos para nuestro próximo disfraz.$b$bNo te preocupes, tú ya tienes disfraz. Este es para otra persona... bueno, para otra... COSA.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Coronel Troteman. Zona: Vigilia de Morgan, Las Estepas Ardientes.', 0),
(28312, 'esMX', 'Demonios latentes de la tierra', 'Consigue 18 flamantes caídos.', 'El lecho de lava cercano, al oeste de aquí, alberga a los flamantes, una especie de demonios de fuego que habitan estas estepas desde hace mucho tiempo. La situación en el ejército Roca Negra es tal que si lo hacemos con cuidado, podríamos infiltrar a unos cuantos de esos flamantes en sus filas para que causen el caos.$b$bTráeme los cadáveres de varios flamantes. Al ser demonios, son fáciles de resucitar; y después podremos usarlos para nuestros propios propósitos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Coronel Troteman. Zona: Vigilia de Morgan, Las Estepas Ardientes.', 0),
(28313, 'esMX', 'Un montón de deliciosos huargos', 'Usa la serrahuargos en los cuerpos de los huargos brasales gigantes asesinados para conseguir 40 chuletas de huargo.', 'Vamos a necesitar carne fresca, lo que significa que vas a tener que cazar huargos. Los huargos de esta parte de las estepas deben ser tu objetivo.$b$b<Troteman saca una gran espada y te hace entrega de ella.>$b$bCaza los huargos brasales gigantes. Una vez muertos, usa esta sierra para cercenar las mejores piezas de carne de sus cadáveres. Encontrarás huargos por todas partes en las estepas, pero la manada que domina la zona se encuentra la noreste.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Coronel Troteman. Zona: Vigilia de Morgan, Estepas Ardientes.', 0),
(28314, 'esMX', 'Recorrido sangriento', 'Mata a 25 dragauros negros o vermintes negros.', 'Mis piernas vuelven a pedir acción. ¿Te apetece dar una vuelta, $n?$b$bVamos a recorrer Roca Machacamiedo. Quiero investigar un poco el ejército de los Roca Negra antes de que avancemos; y ya que estamos por allí, supongo que será buena idea matar a algunos de camino.', '', '', '', '', '', '', '', '', '', '', 0),
(28315, 'esMX', 'Vanguardia dracónica', 'Asesina a Minyoth, a la domadora de crías Akumi, a Terromath el Chamuscado y a Tugnar Faucesangre.', 'Los orcos Roca Negra no vienen solos. Ya has visto que tienen a los ogros Pirontraña y a los trols Espina Ahumada de su lado. Por desgracia para nosotros también se han aliado con el Vuelo Negro.$b$bLos orcos y los dragones ya han enviado a algunos de sus campeones para que vigilen los puntos de reunión, que están marcados con la calavera de un dragón en lo alto de una pica. Tú y yo vamos a localizar esos puntos de reunión y vamos a acabar con su vanguardia antes de que comience la batalla.$b$b¿$gPreparado:Preparada;?', '', '', '', '', '', '', '', '', '', 'Habla con: John J. Keeshan.', 0),
(28316, 'esMX', 'Un trato con un dragón', 'Entrega las crías rescatadas a Acride en Roca Desliz en Las Estepas Ardientes.', 'Mientras rodeamos Roca Machacamiedo, tenemos que hacer una parada más.$b$b¿Recuerdas las crías que liberaste en Las Colinas de los Vástagos? Troteman se ha estado encargando de ellas, pero ahora vamos a entregárselas a alguien que puede cuidarlos mejor que nosotros. Se encuentra en Roca Desliz, al noreste de Roca Machacamiedo.$b$bSe llama Acride, y podría ser la clave para la victoria en la próxima batalla.', '', '', '', '', '', '', '', '', '', 'Habla con: Acride. Zona: Roca Desliz, Las Estepas Ardientes.', 0),
(28317, 'esMX', 'Una entrega para Thorg\'izog', 'Usa tu disfraz de Roca Negra y lleva las chuletas marinadas con sidra hidra al general Thorg\'izog en el Horno Pirontraña en Las Estepas Ardientes. Habla con el coronel Troteman si necesitas un nuevo disfraz de Roca Negra.', 'El General Thorg\'izog se encuentra entre los ogros en el Horno Pirontraña, una cueva en el extremo occidental de la Roca Machacamiedo. Quiero que le entregues esto a él y a los ogros.$b$bEn el interior del paquete encontrarás las chuletas de huargo que conseguiste marinadas en la sidra hidra vil que conseguimos en el Altar de la Tempestad.$b$bSi fuese tú, me abstendría de comérmelas.$b$bLlévaselo al General Thorg\'izog. Él se ocupará de que sus tropas reciban alimento y, con algo de suerte, incluso él comerá un poco.', '', '', '', '', '', '', '', '', '', 'Habla con: General Thorg\'izog. Zona: Interior del Horno Pirontraña, Las Estepas Ardientes.', 0),
(28318, 'esMX', 'Una entrega para Neeralak', 'Usa tu disfraz de Roca Negra, cuélate en El Laberinto de las Calaveras y convence al señor de los dragones Neeralak de que coja tu cajón de flamantes durmientes. Habla con el coronel Troteman si necesitas otro disfraz de Roca Negra.', 'Los brujos del clan Roca Negra practican con frecuencia su magia en El Laberinto de Calaveras, una cueva en la zona este de Roca Machacamiedo. Su líder, Xi\'lun, está ocupado en otro lugar, así que la cueva la mantiene ahora otro de los Tres Grandes: el señor de los dragones Neeralak. Y Neeralak es experto en dragones, no en nigromancia.$b$bHe usado la arena de sueño en esos flamantes que capturaste. Trata de convencer a Neeralak de que son diablillos de brujo, en vez de flamantes. Cuando se despierten no se alegrarán.', '', '', '', '', '', '', '', '', '', 'Habla con: Señor de los dragones Neeralak. Zona: El Laberinto de Calaveras, Las Estepas Ardientes.', 0),
(28319, 'esMX', 'Una entrega para Xi\'lun', 'Mientras usas el disfraz de Roca Negra, entrega el orbe de cristal transparente al Gran brujo Xi\'lun en lo alto de la Roca Machacamiedo en Las Estepas Ardientes.', 'Inteligencia nos informa de que el Gran brujo Xi\'lun, el último miembro de los Tres Grandes, está en el interior de la cueva en lo alto del Pico Machacamiedo, preparándose para su gran momento.$b$bEstá esperando una entrega: un orbe de dominación, con el que poder realizar un poderoso ritual de invocación. Quiero que le des esto:$b$b<Troteman te entrega un orbe de cristal.>$b$bEs el orbe de cristal transparente que liberaste del Altar de la Tempestad. No tiene poder. Dáselo a Xi\'lun, y cruza los dedos para que no se dé cuenta.', '', '', '', '', '', '', '', '', '', 'Preséntate ante el Gran brujo Xi\'lun en la Roca Machacamiedo en Las Estepas Ardientes.', 0),
(28320, 'esMX', 'Ataque a Roca Machacamiedo', 'Asesina a 200 invasores Roca Negra. Si pierdes tu vehículo, usa el cuerno de los clamadores para volver a invocarlo.', 'Ha llegado el momento de la verdad, $n. Ahora empieza lo bueno. Todas las piezas encajan.$b$bAgárrate y ven conmigo. Vamos a hablar con Acride para pedirle el favor que nos debe. Después detendremos esta invasión incluso antes de que empiece.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Coronel Troteman. Zona: Vigilia de Morgan, Las Estepas Ardientes.', 0),
(28321, 'esMX', 'Gloria entre el caos', 'Mata al General Thorg\'izog, al señor de los dragones Neeralak y al Gran brujo Xi\'lun.', 'Keeshan y tú volveréis a esa montaña. Tres orcos sobrevivieron el ataque; y no descansaremos hasta que estén muertos.$b$bSí, eso es, estoy hablando de los Tres Grandes.$b$bEl General Thorg\'izog se arrastró de vuelta hasta el Horno Pirontraña y el señor de los dragones Neeralak se esconde como un cobarde en la cueva de lo alto de la montaña. Xi\'lun está en la parte trasera de El Laberinto de Calaveras, conspirando con sus colegas los brujos.$b$bDeja tu señal, $n. Acaba con esos Roca Negra lloricas y ¡demuéstrales el poder de Crestagrana!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Coronel Troteman. Zona: Vigilia de Morgan, Las Estepas Ardientes.', 0),
(28322, 'esMX', 'Botín de guerra', 'Inspecciona el cajón de suministros abandonados en la Vigilia de Morgan en Las Estepas Ardientes.', 'Hoy hemos acabado con un gigante, $n. Y a pesar de que los orcos Roca Negra siguen poblando su aguja, dudo que tengan planeado acercarse a Crestagrana en mucho tiempo. Keeshan y tú os encargasteis de eso.$b$bCreo que hemos sido bastante ingeniosos aquí en Las Estepas Ardientes; esos suministros de brujo que recogimos nos vinieron de maravilla, al igual que las cenizas de obsidiana que utilizamos para ocultar a nuestro dragón.$b$bDe todos modos quedan todavía suministros abandonados. Coge tu pico antes de que te marches más allá de las estepas.', '', '', '', '', '', '', '', '', '', '', 0),
(28323, 'esMX', 'Reunión con el hermano Sacraplata', 'Habla con el hermano Sacraplata en los Suburbios Goblin de Orgrimmar.', 'El hermano Sacraplata me ha comunicado que desea hablar contigo. La próxima vez que pases por Orgrimmar, hazle una visita en los Suburbios Goblin. Parecía que tuviera algo importante en mente.', '', '', '', '', '', '', '', '', '', 'Habla con: Hermano Sacraplata. Zona: Suburbios Goblin, Orgrimmar.', 0),
(28324, 'esMX', 'Estudio en letalidad', 'Recupera 250 muestras de añublo.', 'Utilizamos una cepa bastante fuerte de añublo contra los humanos de Costasur. Como puedes ver, funcionó, pero el problema con el uso del añublo es que tiende a permanecer después de que haya cumplido su cometido.$b$bLo que necesito que hagas es que cojas este equipo de prueba y salgas al campo para obtener un recuento de letalidad de las babosas de añublo que hemos liberado en la zona. Utiliza el analizador de letalidad en las babosas de añublo que recorren los charcos. Vuelve a verme cuando tengas datos sólidos.', '', 'Muestra de añublo tomada', '', '', '', '', '', '', '', 'Vuelve con: Serge Hinott. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28325, 'esMX', 'Vida verde', 'Recupera 8 botes de añublo usados.', '¡Reciclaje! Es la última moda. La Reina alma en pena ha decretado que si queremos prosperar como pueblo debemos empezar a conservar. Todos debemos cumplir con nuestra parte, ¿verdad? Dicho eso, tú vas a cumplir con la nuestra.$b$bDebe de haber miles de trozos de botes de añublo usados por todo Costasur. Podemos reutilizarlos para elaborar más bombas de añublo. Entra en las ruinas y recoge todo lo que encuentres.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Serge Hinott. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28326, 'esMX', 'Situando a los peones', 'Vuelve con el Coronel Troteman en Vigilia de Morgan en Las Estepas Ardientes.', '$n. Parece que Keeshan y tú han acabado con sus tareas. Yo también he terminado las mías.$b$bVuelve a Vigilia de Morgan. He preparado unos cuantos paquetes para entregárselos a los Tres Grandes: Thorg\'izog, Neeralak y Xi\'lun. Ya has conocido al General Thorg\'izog. Esta será tu oportunidad de conocer a los otros dos.$b$bAntes de que los matemos, se sobreentiende.', '', '', '', '', '', '', 'Coronel Troteman', '', '', '', 0),
(28327, 'esMX', '¡Preparados!', 'Preséntate ante el Coronel Troteman en Vigilia de Morgan en Las Estepas Ardientes.', '$n, responde. ¿Me recibes?$b$bLa batalla está a punto de comenzar. Espero que hayas entregado todos los paquetes.$b$bTe necesito en Vigilia de Morgan, AHORA.', '', '', '', '', '', '', 'Coronel Troteman', '', '', '', 0),
(28328, 'esMX', 'Maquinaciones Crepusculares', 'Utiliza la antorcha resplandeciente para destruir 8 copias de El Credo Crepuscular en el Domicilio de las Profundidades de Roca Negra.', 'La influencia del Martillo Crepuscular se hace notar en todas partes. No dejan de buscar aliados en su guerra contra nosotros, y ahora reclutan a los enanos Hierro Negro de las Profundidades de Roca Negra para su causa.$b$bEl dominio que ejerce Moira sobre los Hierro Negro es delicado en el mejor de los casos, y cada día que pasa sus súbditos se alejan más de ella. Debemos sabotear estas operaciones de reclutamiento.$b$bQuiero que vayas al Domicilio de las Profundidades de Roca Negra y utilices esta antorcha para prenderles fuego a los libros que el Martillo Crepuscular distribuye por allí.', '', 'Copias de El Credo Crepuscular quemadas', '', '', '', '', '', '', '', 'Vuelve con la suma sacerdotisa Laurena en la Catedral de la Luz, en el Distrito de la Catedral de Ventormenta.', 0),
(28329, 'esMX', 'Burbujas enfadadas', 'Mata 5 babosas de añublo enfadadas.', 'Estas babosas de añublo parecen estar muy enfadadas. Hasta tienen una difusa cara humanoide con expresión de enfado en el ectoplasma. No crees que a Hinott le entusiasme que haya babosas rebeldes en las reservas de reproducción.$b$bMata todas las babosas de añublo enfadadas que veas e intenta localizar la reserva de reproducción.', '', '', '', '', '', '', 'Babosa enfadada', '', '', 'Habla con: Serge Hinott. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28330, 'esMX', 'Rastro de suciedad', 'Mata a Chet el Criador de babosas.', 'El rastro de suciedad y cólera conduce hasta el ayuntamiento en ruinas. Tiene que haber una reserva de reproducción de babosas dentro de la estructura. ¡Ábrete paso hasta el interior y acaba con cualquier criador de babosas que te encuentres!$b$bSi lo consigues, sin duda Serge Hinott, en las Ruinas de Costasur, querrá saber de ello.', '', '', '', '', '', '', 'Chet', '', '', 'Habla con: Serge Hinott. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28331, 'esMX', 'La vara de Helcular da...', 'Utiliza la vara de Helcular para potenciar 8 forestales oscuras.', 'Y pensar que yo, un maestro de la nigromancia instruido por el mismísimo Kel\'Thuzad, me vi reducido a ser un mísero cadáver en una tumba. Por fortuna mi astuto aprendiz, Thaivand, consiguió reunir a un grupo de héroes para que se hicieran con esto:$b$b<Helcular saca la vara.>$b$bRenací gracias a esta vara. ¡La vara da y la vara quita!$b$bTómala y utilízala para potenciar a nuestras forestales oscuras que luchan contra los huargen en el campo que hay al norte. Renueva su vigor con mi vara.', '', 'Forestal oscura potenciada', '', '', '', '', '', '', '', 'Vuelve con: Helcular. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28332, 'esMX', 'La orden de Helcular', 'Mata a 15 cazadores de Renegados Colmillo de Sangre.', 'Nuestras forestales oscuras peinan los campos en busca de terroristas huargen. Sus maestros oscuros los han enviado para darnos caza y matarnos. Aunque una forestal oscura es una oponente formidable, a menudo los huargen atacan en manadas que pueden ser demasiado hasta para las susodichas.$b$bRastrea los campos que hay alrededor de las ruinas de Costasur en busca de cazadores de Renegados Colmillo de Sangre. ¡Mata a todos los que veas! ¡Por los Renegados y por Lordaeron!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Helcular. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28333, 'esMX', 'Es la hora de engrasar', 'Usa el arpeo de Darla para coger latas de aceite de Troncoferro y úsalas para engrasar 7 trituradoras de Troncoferro.', 'Hay tres cosas en el Claro de Troncoferro: madera, aceite y trabajadores exhaustos. Las dos primeras son la causa de la segunda, pero me gusta hacer las cosas de forma eficiente.$B$BMis trituradoras están trabajando el triple de horas extras no remuneradas y no tengo tiempo para hacer que se ocupen de su mantenimiento.$B$BUsa este arpeo para coger algunas de las latas de aceite que hay por el campamento y úsalas para engrasar las trituradoras, ¿quieres?', '', 'Trituradora engrasada', '', '', '', '', '', '', '', 'Vuelve con: Darla Brocadozer. Zona: Claro de Troncoferro, Frondavil.', 0),
(28334, 'esMX', 'Batalla de bengalas', 'Usa la caja de mega bengalas de Darla para revelar a 8 merodeadores de Ramaespolón y mátalos.', 'Esta operación ha permanecido discreta hasta ahora, pero los huargen del Claro Ramaespolón van a por nosotros. Lo han intentado todo para dejarnos encerrados.$B$BAlgunos de los trabajadores me han dicho que han creído ver huargen alrededor del claro. Coge estas bengalas desmesuradas. Son los suficientemente brillantes como para iluminar cualquier cosa que se acerque a ellas.$B$BUsa las bengalas para buscar huargen merodeadores ¡y asegúrate de que no salgan de aquí con vida!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Darla Brocadozer. Zona: Claro de Troncoferro, Frondavil.', 0),
(28335, 'esMX', '¡Apágala! ¡Apágala!', 'Apaga la bomba de control maestro al fondo de la Caverna de Troncoferro.', '¡Fueron esos malditos huargen! Se colaron en la caverna sin que yo los viera.$B$B¡Tienen que haber manipulado la bomba de control maestro! Si se deja encendida mucho tiempo, todas las tuberías que hay debajo de nosotros van a explotar. ¿Las fugas que tenemos ahora te parecen malas? ¡Tú espera!$B$BEscucha, si puedes llegar hasta la bomba de control maestro, al fondo de la caverna, ¡podrías apagarla y salvarnos a todos!', '', '', '', '', '', '', '', '', '', '', 0),
(28336, 'esMX', 'Abofetear y tapar', 'Abofetea a 7 trabajadores aterrados para hacer que tapen los chorros de aceites.', '¡Oh por... otra vez no! Si has oído al alguacil gritando ahí fuera, ¡eso significa que que tenemos una fuga de aceite tremenda entre manos! ¡Son esos asquerosos huargen otra vez!$B$BPresta atención, eso va a ser un caos total: goblins privados de sueño corriendo por todas partes, gritando y sin saber qué hacer. Necesito que hagas entrar en razón a los trabajadores.$B$B¡Cruzarles la cara con un buen revés debería funcionar! Una vez que se hayan espabilado, ¡volverán al trabajo y taparán esos chorros!', '', 'Trabajador aterrado abofeteado', '', '', '', '', '', '', '', 'Vuelve con: Darla Brocadozer. Zona: Claro de Troncoferro, Frondavil.', 0),
(28337, 'esMX', 'Los machacadores de Troncoferro', 'Mata a 9 machacadores Troncoferro.', 'Asqueroso, ¿verdad? Míralos. Cositas patéticas que no pueden ni manejar sus propios cuerpos.$B$BTropiezan por ahí con sus enormes machacadores de metal, dejando el bosque hecho astillas. Apuesto a que piensan que ahí están a salvo, calentitos y cómodos.$B$BDemuéstrales que se equivocan. Ábrete camino hacia el norte, a través del campamento, y destruye a tantos machacadores como puedas. Cuando hayas derramado algo de sangre, haremos este lugar pedazos de una buena vez.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Alton Redding. Zona: Caverna de Troncoferro, Frondavil.', 0),
(28338, 'esMX', 'Los Muertobosque del Norte', 'Mata a 15 fúrbolg Muertobosque de cualquier tipo en el poblado Zarpavil.', 'Al suroeste hay un campamento de fúrbolgs Muertobosque. La corrupción impregna el campamento y yo quiero acabar con ella antes de que se convierta en un problema.$B$BLa tribu Muertobosque es malvada, pero solo por los efectos de la energía vil que contamina sus mentes. Su hostilidad no es en realidad una cualidad innata en ellos, y sin embargo, no podemos salvarlos. Me entristece que tengamos que combatir contra nuestros hermanos.$B$B$n... Debo pedirte que hagas lo que debe hacerse. Pero ahórrame los detalles. No podría soportarlos.', '', 'Fúrbolg Muertobosque asesinado', '', '', '', '', '', '', '', 'Vuelve con: Nafien. Zona: Bastión Fauces de Madera, Frondavil.', 0),
(28339, 'esMX', '¿Fluye tu aceite?', 'Recoge 10 bolas de alquitrán crudo de los fangos aceitosos.', 'La última vez que tuvimos una fuga de aceite semejante, ¡hasta el aceite intentó escaparse!$B$BNo sé cuál es la causa, tal vez sea por la viscosidades demoníacas que hay flotando por aquí, pero cuando tenemos una fuga de alquitrán lo suficientemente grande, se junta todo e intenta escapar.$B$B¡Eso son beneficios tratando de escapar! ¡Persigue a esos fangos de aceite y trae de vuelta su dulce y precioso aceite!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Darla Brocadozer. Zona: Claro de Troncoferro, Frondavil.', 0),
(28340, 'esMX', 'Un trato explosivo', 'Reúne 8 explosivos Troncoferro en la Caverna de Troncoferro.', '¡Todos mis trabajadores salieron de la caverna huyendo de esas cosas pantanosas! Darla me ha enviado aquí para arreglar el desaguisado, ¿pero has visto lo que hay ahí? ¡Yo no entro!$B$BHa quedado una tonelada de explosivos que no podemos dejar sueltos por ahí$B$BTe diré lo que podemos hacer: vas ahí y consigues reunir los explosivos mientras yo me quedo aquí procurando que las cosas pantanosas no me maten; si tú tampoco te vas al otro barrio, te pago. ¿Qué te parece?', '', '', '', '', '', '', '', '', '', 'Vuelve con: Supervisor Pikwik. Zona: Caverna de Troncoferro, Frondavil.', 0),
(28341, 'esMX', 'Recoger corrupción', 'Recoge 8 esencias entrópicas de los horrores entrópicos de la Cañada Gran Cicatriz.', 'Aunque los druidas desprecian los poderes demoníacos que infestan esta tierra, debemos hacerles frente.$B$BLa Cañada Gran Cicatriz, al sur, rebosa de corrupción. Las energías que hay allí son tan caóticas que se manifiestan como entidades violentas, magia vil en estado puro, hecha corpórea para atacar a toda forma de vida.$B$BHe estado vigilando de cerca a esas bestias caóticas y estudiando su fuerza. Tengo que asegurarme de que se siguen debilitando con el tiempo. Tráeme las esencias que sueltan para que pueda asegurarme de que están disminuyendo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Elessa Brisa Estelar. Zona: Arboleda Susurravientos, Frondavil.', 0),
(28342, 'esMX', 'Pedazos corruptos', 'Recoge 9 pedazos de escombros infernales de la Cañada Gran Cicatriz.', 'Los infernales que acechan en la Cañada Gran Cicatriz son formidables, pero no invencibles. Hemos progresado mucho diezmando su número.$B$BPero destruirlos solo es parte de la solución. He descubierto que la piedra de la que están hechos los infernales aún contiene grandes cantidades de magia vil, incluso después de su muerte.$B$BLos escombros de los infernales muertos están esparcidos por toda la Cañada Gran Cicatriz, vertiendo su corrupción de vuelta a la tierra. Si pudieras recogerlos y traérmelos te lo agradecería.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Elessa Brisa Estelar. Zona: Arboleda Susurravientos, Frondavil.', 0),
(28343, 'esMX', 'El Aliento de Cenarius', 'Recupera el Aliento de Cenarius del piromántico Fruto del Saber en las Profundidades de Roca Negra y utiliza el artefacto para cerrar 3 puertas elementales.', '$n, hemos descubierto que el artefacto Cenarion que faltaba ha aparecido en manos de un piromántico del Martillo Crepuscular. El piromántico Fruto del Saber se ha llevado el artefacto, el Aliento de Cenarius, a las Profundidades de Roca Negra y utiliza su poder para abrir puertas elementales.$b$bDebemos actuar para impedir que Fruto del Saber invoque elementales para reforzar las filas de sus aliados Hierro Negro. Recupera el artefacto y utiliza su poder para cerrar las puertas que ha estado utilizando Fruto del Saber.', '', 'Puerta elemental cerrada', '', '', '', '', '', '', '', 'Vuelve con: Loganaar. Zona: Amparo de la Noche, Claro de la Luna.', 0),
(28344, 'esMX', '¿Puedes oler lo que el lok\'tar se está cocinando?', 'Encuentra al matarreyes Orkus en las Ruinas de Costasur en las Laderas de Trabalomas.', 'Justo antes de que llegaras un orco vino volando sobre una vermis de escarcha y me exigió que le indicará por dónde suelen "andar los novatos". Como no estaba seguro de qué me estaba hablando, le dije que cumpliera con su deber como miembro de la Horda y que se ocupara de la amenaza huargen en esta zona. El tipo gruñó algo sobre "qué estaba cocinando el lok\'tar" y se dirigió hacia el sur, a los muelles.$B$BNormalmente no me importaría en absoluto que el orco se perdiera o no, pero la verdad es que tengo mucha curiosidad por saber qué está cocinando el lok\'tar. Descúbrelo.', '', '', '', '', '', '', '', '', '', '', 0),
(28345, 'esMX', '*Glu* ¡SOCORRO! *Glu*', 'Ayuda al matarreyes Orkus a salir del agua.', '*GLU*$b$b¡SOCORRO! *BUFIDO*$b$b¡ORKUS SE AHOGA! ¡AYÚDAME, $gASIGNADOR:ASIGNADORA; $n!$b$b*GLUGLÚ*$b$b¡Un enano ha tirado a Orkus al agua! ¡No quiere morir!$b$b*GLU*$b$bLa vergüenza sería insoportable.', 'Orkus sacado del agua sano y salvo', '', '', '', '', 'Orkus sacado del agua sano y salvo', '', '', '', 'Habla con: Matarreyes Orkus. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28346, 'esMX', 'El solterón', 'Habla de expectativas matrimoniales con Keegan Barbafuego en Kirthaven, en las Tierras Altas Crepusculares.', 'Tenemos que hacer que esto funcione, $n. ¡La respuesta está en la sangre! Los lazos familiares han mantenido apartados a estos clanes Martillo Salvaje. Serán los lazos familiares los que vuelvan a unirlos. Es un tiro a ciegas, ¡pero vamos a tener que hacer de casamenteros!$B$BBuscaré a Colin Bramal y hablaré con él. Tú tienes mucho tacto, deberías hablar con Keegan Barbafuego dentro. Es lo suficientemente listo como para comprender la necesidad de una boda política. ¡Ve y averigua si le gusta alguien!', '', '', '', '', '', '', '', '', '', '', 0),
(28347, 'esMX', 'Coffer of Promise TRACKING QUEST', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28348, 'esMX', 'Encuentro Pico Tormenta', 'Infórmate del encuentro Pico Tormenta de Orkus.', 'Encontré a Helcular, el nigromante decrépito, con la esperanza de informarme sobre el movimiento de la Alianza en Trabalomas.$b$bHelcular me encargó buscar y matar huargen. Normalmente no sería un problema para Orkus, pero acababa de comer varias raciones de las fabulosas chuletillas de quimerok de Dirge y las tripas me gritaban de angustia. Entonces se armó la gorda y acabé en el agua.$b$bEscucha a Orkus, $n.', 'Infórmate sobre el encuentro Pico Tormenta', '', '', '', '', 'Infórmate sobre el encuentro Pico Tormenta', '', '', '', 'Habla con: Matarreyes Orkus. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28349, 'esMX', 'Megs de marketing', 'Habla con Megs Trituramatic en la Central SCK, en Kezan.', '$gJefe:Jefa;, mientras estabas en las minas, Megs Trituramatic de marketing vino preguntando por ti. Decía algo sobre tu vehículo nuevo.$B$BEstá justo fuera del edificio a la izquierda.', '', '', '', '', '', '', '', '', '', '', 0),
(28350, 'esMX', 'Maestro trampero', 'Sullah quiere que reúnas 5 sobras de carne de los animales salvajes de Uldum.', 'Hay algo sobre mí que tal vez no sepas, $n...$b$bVengo de un amplio linaje de tramperos. Mi padre me enseñó, del mismo modo que el suyo le enseñó a él, el arte de atrapar criaturas de la forma más compasiva posible.$b$bCualquier maestro trampero te dirá que la parte más importante de una buena trampa es el cebo.$b$bAsí que empecemos por ahí.$b$bLlena este cubo de trozos de carne de todas las criaturas salvajes que encuentres en Uldum.', '', '', '', '', '', '', '', '', '', 'Habla con: Sullah. Zona: Puesto de Sullah.', 0),
(28351, 'esMX', 'Un potencial ilimitado', 'Usa la jaula reforzada para capturar a 5 pigmeos retozadores.', 'Algunos ven a los pigmeos de arena como una mera plaga, como a gusanos, o incluso algo peor, como a pequeños demonios.$b$b¡Yo digo que no los comprenden!$b$bCon el cuidado y el liderazgo adecuado, estos tipos podrían convertirse en un don de la naturaleza.$b$bQuiero que cojas estas jaulas y que las uses para capturar a unos pocos para que pueda trabajar con ellos.$b$bVas a tener que darles una buena paliza antes de meterlos en la jaula, pero será por su propio bien.$b$b¡Ya lo verás!$B$B¡Ve hacia el sur en busca de pigmeos!', '', 'Pigmeos de arena capturados', '', '', '', '', '', '', '', 'Habla con: Sullah. Zona: Puesto de Sullah, Uldum.', 0),
(28352, 'esMX', 'Doma de camellos', 'Usa el arnés de Sullah para domar a 3 camellos.', '¡Saludos, $gamigo:amiga;!$b$bSiempre eres $gbienvenido:bienvenida; en mi humilde tienda.$b$b¿Buscas algo que hacer? ¡Sullah tiene algo para ti!$b$bLos camellos nunca vienen mal, pero si encima tienes que montar una actuación como la de mi puesto, ¡entonces son completamente imprescindibles!$b$bCoge este arnés y utilízalo para someter a un camello que merodee por ahí.$b$bPuede que tengas que, eh, humillarlo un poco primero... No sé si sabes a lo que me refiero.$B$BEncontrarás un desierto lleno de camellos salvajes al sur.', '', 'Camellos salvajes capturados', '', '', '', '', '', '', '', 'Habla con: Sullah. Zona: Puesto de Sullah.', 0),
(28353, 'esMX', 'El pequeño Jones ha mandado a buscarte', 'Habla con Harrison Jones en el Oasis de Vir\'sar.', 'Escucha, $n, tal vez deberías volver con el pequeño Jones cuando tengas un momento.$b$bLo más probable es que, sea lo que sea que tiene que contarte, sea más urgente que ninguna tarea que yo pueda encomendarte.', '', '', '', '', '', '', '', '', '', '', 0),
(28354, 'esMX', 'Kasha volará de nuevo', 'Reúne 8 flores Morrobarro.', 'Kasha volará de nuevo, $n. ¡Debe hacerlo si queremos venganza! Por desgracia, Orkus debe quedarse aquí con Kasha. Debes ayudarnos. ¡Te lo ruego!$b$bEscucha atentamente, $gasignador:asignadora; de misiones. Cuando llegué aquí, me pasé días volando para aprenderme la distribución del terreno. Hay una granja al este de aquí que lleva tiempo abandonada y que ahora está ocupada por los gnolls. En esta granja crece un tipo de seta especial que se llama morrobarro. Ve a la granja y recoge morrobarro para Kasha. Vuelve cuando hayas llenado la mochila.', '', '', '', '', '', '', '', '', '', 'Habla con: Matarreyes Orkus. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28355, 'esMX', 'Pequeños monstruos', 'Mata 10 gnolls de cualquier tipo en la Granja Nethander.', '¡Gnolls! Esos pequeños monstruos son un castigo para cualquier tierra... Y ya es decir, teniendo en cuenta que Trabalomas es territorio Renegado. Mata todos los gnolls que puedas en la Granja Nethander. ¡Por el bien del mundo!', '', 'Gnoll o chamán Morrobarro muerto', '', '', '', '', '', '', '', '', 0),
(28356, 'esMX', 'Ataque preventivo', 'Mata a 15 nagas de cualquier tipo en la Playa del Este.', 'Estos planes detallan lo que parece ser un ataque inminente a Costasur. Los nagas de la Playa del Este pretenden invadir el pueblo ahora que hemos echado a la Alianza.$b$b¡No si puedes evitarlo!$b$bMata a todos los nagas de la Playa del Este y ve a ver a Helcular, en las Ruinas de Costasur, con los planes de ataque Espinadaga.', '', 'Naga Espinadaga muerto', '', '', '', '', '', '', '', 'Vuelve con: Helcular. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28357, 'esMX', 'Sorpréndelos entre los árboles', 'Mata a 8 defensores de Ramaespolón.', '¿Esos chuchos sarnosos creen que pueden fisgonear por aquí y salirse con la suya? Les daré una lección...$B$BY con eso quiero decir que TÚ les darás una lección. Tú y el pequeño ejército de goblins con hachas contratados que he enviado al Claro Ramaespolón.$B$BA estas alturas, el lugar estará lleno de huargen. Justo donde queremos que estén. Dirígete al sudoeste, únete al resto de nuestras fuerzas y despelléjalos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Darla Brocadozer. Zona: Claro de Troncoferro, Frondavil.', 0),
(28358, 'esMX', 'Cazando a los Malditos', 'Mata a 6 avizores infernales.', 'Los primeros demonios que pusieron un pie en este bosque fueron los infernales. Hace tiempo, esos poderosos seres de piedra y fuego demoníaco cayeron del cielo para conquistar esta tierra en nombre de la Legión Ardiente.$B$BLos cráteres carbonizados de la Cañada Gran Cicatriz, al sur, es donde aterrizaron esos infernales y aún quedan muchos por aquí. Son unos enemigos temibles y matarlos es tanto un desafío digno como una noble causa.$B$BOfrezco una recompensa a aquellos que se unan a la caza. Después, vuelve aquí.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Hurak Cuerno Salvaje. Zona: Arboleda Susurravientos, Frondavil.', 0),
(28359, 'esMX', 'El núcleo de Kroshius', 'Consigue el núcleo infernal de Kroshius.', 'El demonio más temible de la Cañada Gran Cicatriz se llama Kroshius. Aunque muchos le han dado caza a lo largo de los años, la destrucción solo lo ha hecho más fuerte.$B$BUna y otra vez, han venido brujos a este bosque y han reanimado a Kroshius. Ahora acecha en el sudeste, rodeado por fuego demoníaco, esperando a cualquiera que se atreva a venir para reclamar su poder.$B$B¡No permitiré que continúe este ciclo corrupto! Mata a Kroshius y tráeme su núcleo infernal.', '', '', '', '', '', '', 'Kroshius', '', '', 'Vuelve con: Hurak Cuerno Salvaje. Zona: Arboleda Susurravientos, Frondavil.', 0),
(28360, 'esMX', 'Un sacrificio necesario', 'Mata a 8 trotadores Putrevil.', 'Me encantaría salvar a todas las criaturas del bosque, pero, como probablemente habrás visto, algunas se han ido demasiado lejos.$B$BCuando fundamos la Arboleda Susurravientos, los bosques del sur estaban llenos de hermosos trotadores, unas criaturas majestuosas y gentiles. La corrupción que hay aquí no las ha vuelto violentas, pero se han consumido hasta quedar en casi nada.$B$BAunque fueran purificadas, solo conocerían dolor y sufrimiento. Por favor, $c, ayúdame y sacrifícalas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Tender Bosquepuro. Zona: Arboleda Susurravientos, Frondavil.', 0),
(28361, 'esMX', 'Purificar ardillas', 'Frota 6 ardillas corruptas.', 'A menudo, los animales más grandes están demasiado corruptos para poder salvarlos, pero te sorprenderá saber que los pequeños son más resistentes.$B$BMira las ardillas, por ejemplo. Después de bañarse en agua corrompida, pueden extender la enfermedad lejos de la fuente original, pero tarda mucho en afectar a las ardillas en sí. De hecho, ¡una simple limpieza resultará en una ardilla limpia y un bosque más seguro!$B$BToma esta botella de mezcla purificadora. Coge a cualquier ardilla que veas en el bosque, hacia el sur, y frótala... ¡te lo agradecerán!', '', 'Ardilla corrupta frotada', '', '', '', '', '', '', '', 'Vuelve con: Tender Bosquepuro. Zona: Arboleda Susurravientos, Frondavil.', 0),
(28362, 'esMX', '¡Estúpido Drizle!', 'Encuentra a Drizle en el poblado Zarpavil.', '¡Estúpido, estúpido Drizle! ¡Le dije que no fuera!$B$BDrizle quería robar más miel del poblado Zarpavil... ya sabes, el que está al oeste de aquí. Puedes verlo desde el acantilado...$B$BEn fin... Le dije que era una mala idea pero fue de todas formas y lo atrapó la tribu Muertobosque y... y...$B$BSniff...$B$B¡No sé qué le harán! ¡Por favor, encuéntralo, $gseñor:señora; $r! Aunque se un tonto, ¡no quiero que se lo coman!', '', '', '', '', '', '', '', '', '', '', 0),
(28363, 'esMX', 'Golpear el avispero', 'Habla con Sullah en el Puesto de Sullah.', '¡Guau!$b$bParece que has captado toda su atención, $n. No seremos capaces de entrar ahí mientras estén en alerta como ahora.$b$bTiene que haber alguna forma...$b$bEs solo cuestión de tiempo que los hombres de Schnottz activen el obelisco; y yo tengo que estudiar los pergaminos que encontraste. Necesito que te encargues de esto sin mí.$b$bSullah tiene contactos en esta zona. Tal vez él tenga la solución para que podamos entrar.', '', '', '', '', '', '', '', '', '', '', 0),
(28364, 'esMX', 'La llave del cabecilla', 'Quítale la llave de Drizle al cabecilla Sangrefauce.', '¡Sniff... lo siento! ¡No quería que me atraparan! ¡Me cogieron, me pusieron esta cadena y me dejaron aquí! ¡No puedo moverme y se me ha dormido la pierna y tengo hambre!$B$BEl jefe tiene la llave... El cabecilla Sangrefauce, según dijeron los otros. Está al norte del campamento.$B$B¡Pero date prisa! ¡Por favor! ¡No me dejes aquí solo!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Drizle. Zona: Poblado Zarpavil, Frondavil.', 0),
(28366, 'esMX', 'Desarmando a los osos', 'Consigue 7 armas de Muertobosque del poblado Zarpavil.', 'Me gustaría hacer todo lo posible para proteger a mi gente de la tribu Muertobosque sin tener que matar hasta el último de ellos. Hemos avanzado en este sentido en el pasado y, si quieres demostrar tu valía a la tribu Fauces de Madera, te pediría que hicieras lo mismo.$B$BBusca los montones de armas que hay en al poblado Zarpavil, al sudoeste. Coge tantas como puedas. Si desarmamos a la tribu Muertobosque, puede que logremos impedir un futuro derramamiento de sangre.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Nafien. Zona: Bastión Fauces de Madera, Frondavil.', 0),
(28367, 'esMX', 'Embozo de los creadores', 'Sabotea 7 toneles de pólvora de Schnottz.', '¡Tener amigos es bueno, $c! ¡Además del cariño, que en sí es ya una recompensa, la amistad también tiene ventajas tangibles!$b$bUnos amigos míos interceptaron hace poco un cargamento del saqueo de Schnottz y encontraron algo que te podrá servir.$b$bEs una pieza de tecnología titánica que hace que su usuario se vuelva casi invisible. Si la usas en el campamento enemigo, podrás reconectar sus explosivos y causar el caos en su operación.$b$bTodas las cargas tienen una duración limitada, ¡así que busca cobijo rápidamente!', '', 'Toneles de pólvora saboteados', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Oasis de Vir\'sar.', 0),
(28368, 'esMX', '¡Fuego en el agujero!', 'Mata a Grolvitar el Abrasador.', '¡Cielos, colega! Cerraste bien esas válvulas.$B$BDesgraciadamente, ¡ha habido una explosión crítica en el regulador central de combustión! La señora Darla ha enviado a todos los trabajadores de los que podía prescindir para apagar el fuego, ¡pero esas llamas tienen vida propia!$B$B¡Literalmente! ¡Saltan y agarran a todo el que se acerca! Así que Darla dice que si te decidieras a salir de esa caverna en la que estás y derrotar a ese elemental, ¡tendría una recompensa estupenda esperándote!', '', '', '', '', '', '', 'Grolvitar el Abrasador', '', '', 'Vuelve con: Darla Brocadozer. Zona: Claro de Troncoferro, Frondavil.', 0),
(28369, 'esMX', 'Mi hermana, Fanny', 'Habla con: Fanny Bramal en Bramal, en las Tierras Altas Crepusculares.', 'Antes de irte, pasa por la posada que hay justo detrás de mí. Mi hermana Fanny está dentro.$B$BEstán llegando a Bramal refugiados de todos los asentamientos Martillo Salvaje quemados de los alrededores y he puesto a Fanny a cargo de ellos. Es muy fuerte, pero puede que necesite tu ayuda.', '', '', '', '', '', '', '', '', '', '', 0),
(28370, 'esMX', 'A la caza de fuegos fatuos', 'Usa el imán de fuegos fatuos de Darla para coger 5 fuegos fatuos de Ramaespolón.', 'Esos huargen tienen fuegos fatuos, ¿te lo puedes creer? Los elfos de la noche les enseñaron toda esa basura druídica: ahora también tienen sus pequeños y queridos fuegos fatuos que les dan todo el material de construcción que quieren, sin tener que dañar ni uno de sus preciados árboles.$B$BSi tuviéramos esas cosas, podríamos sacar más madera de cada uno de nuestros árboles. ¡Recursos gratis, beneficios gratis! Por eso he estado trabajando en este dispositivo de contención.$B$BDirígete al Claro de Ramaespolón y úsalo para robar algunos fuegos fatuos. Solo tienes que apuntar y pulsar el botón.', '', 'Fuego fatuo de Ramaespolón capturado', '', '', '', '', '', '', '', 'Vuelve con: Darla Brocadozer. Zona: Claro de Troncoferro, Frondavil.', 0),
(28371, 'esMX', '[DND] ORKUS QUEST FLAG [DO NOT LOCALIZE]', 'Reúne 8 flores Morrobarro.', 'Kasha volará de nuevo, $n. ¡Debe hacerlo si queremos venganza! Por desgracia, Orkus debe quedarse aquí con Kasha. Debes ayudarnos. ¡Te lo ruego!$b$bEscucha atentamente, $gasignador:asignadora; de misiones. Cuando llegué aquí, me pasé días volando para aprenderme la distribución del terreno. Hay una granja al este de aquí que lleva tiempo abandonada y que ahora está ocupada por los gnolls. En esta granja crece un tipo de seta especial que se llama morrobarro. Ve a la granja y recoge morrobarro para Kasha. Vuelve cuando hayas llenado la mochila.', '', '', '', '', '', '', '', '', '', 'Habla con: Matarreyes Orkus. Zona: Ruinas de Costasur, Laderas de Trabalomas.', 0),
(28372, 'esMX', 'De vuelta al negocio', 'Vuela hasta el Claro de Troncoferro y habla con Darla Brocadozer.', 'Todo esto de los amigos felices está muy bien: la gente trabajando junta, curando el bosque... Pero qué pasará con el bosque cuando esté curado? ¿Se quedará ahí sin más?$B$BNecesitamos esta madera. La Horda la necesita. Tengo órdenes de mandar a tantos soldados leales de la Horda, y estoy seguro de que tú eres muy leal, al norte, al Claro de Troncoferro.$B$BYa lo he arreglado para que el maestro de hipogrifos te de un viaje gratis hasta allí. Habla con Darla Brocadozer cuando llegues.', '', '', '', '', '', '', '', '', '', '', 0),
(28373, 'esMX', 'Bastión Fauces de Madera', 'Habla con Nafien en el Bastión Fauces de Madera, en Frondavil. El Bastión Fauces de Madera está en el este, pasando el Poblado Zarpavil.', 'Vale, sé que hay pocas probabilidades, pero por preguntar no se pierde nada.$B$BMientras me encargo de la disputa de los ridículos sinsentidos que acaban de tener lugar, necesito que vayas a hablar con unos osos. Los fúrbolgs Fauces de Madera controlan los bosques del noreste, y no nos tienen demasiado aprecio.$B$BNecesito que alguien les dé a entender que la Horda no es tan mala. Dirígete al noreste, por el camino hacia el Bastión Fauces de Madera, no vayas a meterte en el Poblado Zarpavil, y pregúntale a los fúrbolgs que haya fuera si necesitan que les hagan algún favor.', '', '', '', '', '', '', '', '', '', '', 0),
(28374, 'esMX', 'Quitando las malas hierbas', 'Arranca 7 azotadores Susurravientos para comprobar su corrupción.', 'En un sitio como este, incluso algo tan simple como cultivar flores o quitar hierbajos puede requerir un esfuerzo heroico.$B$BLos azotadores orquídea que crecen en todas partes de la arboleda son un signo de sanación. Pero no son perfectos: algunos sucumben a la corrupción demoníaca de vez en cuando.$B$BHe descubierto que la mejor manera de comprobarlo es arrancarlos sin más. Si son normales, darán un par de vueltas por ahí y volverán a echar raíces. Si no lo son... bueno, ¡será mejor que te prepares para pelear!', '', 'Azotador Susurravientos comprobado', '', '', '', '', '', '', '', 'Vuelve con: Tender Bosquepuro. Zona: Arboleda Susurravientos, Frondavil.', 0),
(28375, 'esMX', 'El camino al Purgatorio', 'Acompaña al matarreyes Orkus a la Isla del Purgatorio.', 'Ha llegado la hora de la venganza, $n. Gracias a ti Kasha puede volver a volar. Nos llevará hasta la Isla del Purgatorio para que podamos enfrentarnos al general de los enanos Pico Tormenta, Vanndar Pico Tormenta, y a su capitana, Balinda Piedrahogar. LOS DOS pagarán por lo que han hecho.$b$b¿Estás $glisto:lista;? Orkus no puede hacerlo solo.', 'El camino al Purgatorio tomado', '', '', '', '', 'El camino al Purgatorio tomado', '', '', '', 'Habla con: Matarreyes Orkus. Zona: Isla del Purgatorio, Laderas de Trabalomas.', 0),
(28376, 'esMX', 'La cabeza de Myzerian', 'Lleva la cabeza de Myzerian a Sullah en el Puesto de Sullah.', 'La cabeza de uno de los dragones Negros más imponentes de Alamuerte está en tu poder.$b$bA pesar de que la mitad de Azeroth pagaría una buena cifra por ella, algo te dice que su lugar está en un museo para que todo el mundo pueda observarla y recordar.$b$bSeguro que Harrison Jones tiene los contactos adecuados.$b$bNo hay duda de que Sullah estará encantado de entregársela.', '', '', '', '', '', '', '', '', '', '', 0),
(28377, 'esMX', 'Rescate en el Foso Tripal', 'Encuentra a Colin Bramal en Foso Tripal, en las Tierras Altas Crepusculares.', 'Vaya, hablando del diablo con un traje azul. ¡A Fanny la han raptado unos ogros!$B$BNo confío en que los Bramal logren organizar un rescate por sí solos. Reuniré a mis jinetes de grifos y les daré apoyo aéreo.$B$BSeguro que les viene bien tener a un $c más ahí abajo, $n. Coge tu equipamiento y busca a Colin Bramal en el campamento ogro de Tripal. Está al sudoeste de aquí, bajo los acantilados. ¡Date prisa!', '', '', '', '', '', '', '', '', '', '', 0),
(28378, 'esMX', 'Encuentra a Fanny', 'Encuentra y rescata a Fanny Bramal.', 'Hemos empezado a remover este campamento, $n, pero no hay rastro de Fanny. Tal vez puedas encontrarla.$B$BNo hemos mirado en la cueva que hay justo detrás de mí, al noroeste. ¡Mira a ver si encuentras a Fanny en la cueva!', '', 'Fanny Bramal rescatada', '', '', '', '', '', '', '', 'Habla con: Colin Bramal. Zona: Foso Tripal, Tierras Altas Crepusculares.', 0),
(28379, 'esMX', 'Pulverizar ogros', 'Mata a 10 ogros Tripal (pueden ser aporreadores Tripal, arrojadores Tripal o partecaras Tripal).', '¡Ogros Tripal! Diría que son más tontos que un saco de martillos, pero siento más respeto por mis martillos.$B$BRepelimos sus ataques durante años, pero si son tan osados como para llevarse a uno de los nuestros, vamos a tener que darles una lección.$B$B¡Ayúdanos a darles una paliza a los ogros Tripal! Mata a sus aporreadores, a sus arrojadores o a sus partecaras, ya sea aquí o, mejor aún, dentro de la cueva. Así aprenderán. ', '', 'Ogro Tripal asesinado', '', '', '', '', '', '', '', 'Vuelve con: Colin Bramal. Zona: Foso Tripal, Tierras Altas Crepusculares.', 0),
(28380, 'esMX', 'Pikwik en peligro', 'Habla con el supervisor Pikwik en la Caverna de Troncoferro.', '¿Qué demonios está pasando aquí? El supervisor Pikwik ya debería haber cerrado las válvulas.$B$BPodemos pasarnos el día entero tapando fugas y, si la válvula central está cerrada, solo estamos retrasando una explosión enorme.$B$BEscucha, si valoras el dinero, tu vida, o cualquier combinación de ambos, será mejor que te dirijas al sur, a la Caverna de Troncoferro, y mires a ver si encuentras al supervisor Pikwik.', '', '', '', '', '', '', '', '', '', '', 0),
(28381, 'esMX', 'La madre del cubil', 'Coge un vuelo al Claro de Ramaespolón y habla con la madre del cubil Ulrica.', 'Apenas a un vuelo de cuervo hacia el norte, los goblins arrasan este bosque, talándolo para alimentar la máquina de guerra de la Horda y llenarse los bolsillos. La Horda usa suficientes palabras bonitas y mentiras veladas con los druidas para que hagan la vista gorda, con cuidado de no perturbar la frágil neutralidad que hay aquí.$B$BLos huargen de Ramaespolón están hartos. ¡Únete a nosotros! El maestro de hipogrifos puede llevarte directamente a nuestro hogar. La madre del cubil Ulrica le dará la bienvenida a cualquier $r que quiera luchar.', '', '', '', '', '', '', '', '', '', '', 0),
(28382, 'esMX', 'Enemigo a las raíces', 'Mata a 8 taladores Troncoferro.', '¡Ya tenemos encima a los goblins!$B$BHemos hecho todo lo posible para advertir a los goblins de que se vayan del Claro de Troncoferro antes de que recurramos a la violencia. Como no nos hicieron caso, atacamos y ahora, en vez de dejar el bosque tranquilo, arriesgan sus vidas por la codicia.$B$B¡Pronto conocerán el alcance de nuestra ira! La batalla ha estallado justo al otro lado de nuestra puerta norte. ¡Únete a la manada y mata a cualquier goblin que se atreva a seguirnos!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Madre del cubil Ulrica. Zona: Claro Ramaespolón, Frondavil.', 0),
(28383, 'esMX', 'Fuegos fatuos del bosque', 'Usa el bordón Vientopresto para coger 5 fuegos fatuos de Ramaespolón.', 'Llevo mucho tiempo trabajando aquí, junto a la madre del cubil, para impartir las enseñanzas de Cenarius y las artes de la vida salvaje. Me he ganado su confianza y, a cambio, me ha permitido hablarle a sus estudiantes de los espíritus del bosque. La compañía de fuegos fatuos es un gran honor, así como una bendición muy práctica.$B$BPero ahora llegan los goblins y quieren robar los fuegos fatuos para usarlos de forma nefasta. ¡Te ruego que impidas esa blasfemia!$B$BAtrae a los fuegos fatuos de vuelta aquí desde los bosques del oeste con esta rama bendita, y mantenlos a salvo.', '', 'Fuego fatuo de Ramaespolón capturado', '', '', '', '', '', '', '', 'Vuelve con: Lyros Vientoveloz. Zona: Claro de Troncoferro, Frondavil.', 0),
(28384, 'esMX', 'Hacia el claro', 'Habla con Alton Redding cerca de la Caverna de Troncoferro', 'El Claro de Troncoferro debe ser arrasado. No podemos permitirnos tener piedad con los goblins si queremos evitar que propaguen su destrucción por todo el bosque.$B$BAlton Redding, el protector en quien más confío, ya ha llevado a la mayor parte de la manada al otro lado de la línea enemiga, para atacar mientras estén distraídos aquí. Búscalo en el oeste, sobre la Caverna de Troncoferro.', '', '', '', '', '', '', '', '', '', '', 0),
(28385, 'esMX', 'Aceite e ironía', 'Sabotea la bomba de control maestro en el fondo de la Caverna de Troncoferro.', 'Pretendo usar la avaricia y la contaminación de los goblins en su contra. Cualquier daño adicional que podamos causarle a la tierra que ya han excavado valdrá la pena si así detenemos su propagación.$B$BEn las profundidades de la Caverna de Troncoferro, justo debajo de nosotros, hay muchas tuberías que bombean aceite a través de la tierra, por todo el claro. Esas tuberías están conectadas con la bomba de control maestro, en el fondo de la caverna.$B$BEntra en la caverna y sabotea la bomba. El caos que habrá a continuación nos dará la oportunidad de asestar nuestro golpe final.', '', '', '', '', '', '', '', '', '', '', 0),
(28386, 'esMX', 'Bombas prestadas', 'Reúne 8 explosivos Troncoferro en la Caverna de Troncoferro.', 'Los trabajadores de la Caverna de Troncoferro, bajo nosotros, ya han salido huyendo. Otra cosa se ha apoderado de la cueva.$B$BEso es bueno para nosotros. Vi cómo a algunos de ellos se les caían los explosivos mientras huían... explosivos que necesitaremos para la próxima etapa de nuestro plan.$B$BEntra en la cueva y recupera todas las bombas abandonadas que encuentres. Cuando hayas terminado con eso y con la bomba, empezará nuestro ataque final.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Alton Redding. Zona: Caverna de Troncoferro, Frondavil.', 0),
(28387, 'esMX', 'Incendio', 'Usa los explosivos Troncoferro robados para prender fuego a 7 géiseres de aceite en el Claro de Troncoferro.', 'Tu sabotaje de la bomba ha hecho que las tuberías se rompan en todo el campamento. Ha cundido el pánico entre los goblins a causa de los géiseres y la cosa se va a poner peor.$B$BCoge los explosivos que hemos reunido y úsalos para prender fuego a los géiseres. Haremos todo el daño que podamos en el campamento y evitaremos que ese aceite sirva de combustible a las trituradoras... o peor aún: a los barcos de guerra de la Horda.', '', 'Chorro de aceite prendido', '', '', '', '', '', '', '', 'Vuelve con: Alton Redding. Zona: Caverna de Troncoferro, Frondavil.', 0),
(28388, 'esMX', 'Malditos sueldos', 'Mata a 7 trabajadores aterrados.', 'Pequeños cobardes patéticos... ¡mira cómo huyen despavoridos!$B$BNo dejes que te engañen, $n. En cuanto recuperen el sentido, esos goblins dedicaran cada segundo a talar hasta el último árbol de este bosque y enviarle la madera a la campaña de la Horda.$B$BNo les des la oportunidad. Mata sin piedad a los trabajadores que haya en el Claro de Troncoferro... ¡demuéstrales que su codicia tiene un precio!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Alton Redding. Zona: Caverna de Troncoferro, Frondavil.', 0),
(28389, 'esMX', 'Preséntate ante la madre del cubil', 'Habla con la madre del cubil Ulrica en el Claro Ramaespolón.', 'Con los goblins dispersados y su equipo destruido, o bien captan el mensaje y se van, o serán presas fáciles si deciden quedarse. Hemos ganado.$B$BHas luchado con tanto ahínco como cualquier miembro de la manada, $n. Vuelve con la madre del cubil e infórmala de nuestro éxito. Yo seguiré vigilando.', '', '', '', '', '', '', '', '', '', '', 0),
(28390, 'esMX', 'Glop, hijo de Glop', 'Habla con la ensalmadora de la tierra Norsala y después mata al Fungimántico Glop.', 'Glop tuvo un hijo. Su enorme orgullo le hizo llamarlo Glop. Y así es como se perpetuó la línea de los fungimánticos.$B$BNecesito que mates a este nuevo fungimántico. Tu aliado chamán ya ha regresado y te espera en su cueva al suroeste del Alto Verlok.', '', '', '', '', '', '', 'Fungimántico Glop', '', '', 'Vuelve con: Ruberick. Zona: Trono de Therazane, Infralar.', 0),
(28391, 'esMX', 'El linaje impaciente', 'Derrota a Aeosera.', 'Aeosera es impaciente y testaruda. Se burla de nuestra dominación; y tenemos que ponerla en su sitio.$B$BTodavía tengo la marra que conseguiste para mí. Vuelve al extremo occidental de El Nidal Pálido y golpea el cristal resonador.$B$BYo me encontraré contigo allí y te ayudaré en lo que pueda. Ponla en su sitio, $c.', '', 'Cristal resonador pálido golpeado', 'Aeosera derrotada', '', '', '', 'Aeosera', '', '', 'Vuelve con: Terrath el Firme. Zona: Trono de Therazane, Infralar.', 0),
(28392, 'esMX', 'La tribu Fauces de Madera', 'Habla con Nafien en la entrada del Bastión Fauces de Madera.', 'Los fúrbolgs Fauces de Madera son la última tribu conocida de fúrbolgs no contaminados. Están apiñados en el límite de estas tierras, defendiendo ferozmente su hogar: el Bastión Fauces de Madera.$B$BAunque son criaturas orgullosas, necesitan mucha ayuda. Si quieres ayudar, sigue el camino hacia el norte desde aquí y búscalos en la entrada del Bastión Fauces de Madera.', '', '', '', '', '', '', '', '', '', '', 0),
(28393, 'esMX', 'Una alianza peligrosa', 'Mata 6 destructores guardia de fuego y recupera los planes de ataque del general Forjainquina en el Cuartel Oeste, en las Profundidades de Roca Negra.', 'Me preocupa el último informe del IV:7 sobre las actividades del Martillo Crepuscular y los Hierro Negro, $n. Hay pruebas de que están preparando un ataque conjunto desde el interior de la Montaña Roca Negra. No nos sería fácil rechazar semejante combinación de fuerzas, pero si actuamos antes de que estén listos para atacar podríamos debilitar la ofensiva.$b$bDebes entrar en las Profundidades de Roca Negra y obtener los planes de ataque del Martillo Crepuscular del general Forjainquina, en el Cuartel Oeste. No dudes en eliminar a los elementales que apoyan a sus tropas.', '', '', '', '', '', '', '', '', '', 'Vuelve con Ander Germaine en el Centro de Mano, al sur del Casco Antiguo de Ventormenta.', 0),
(28394, 'esMX', 'Las creaciones del señor gólem', 'Obtén 5 módulos elementales de los gólems del Taller de las Profundidades de Roca Negra y recupera los planos de gólem elemental.', 'Los últimos informes del IV:7 sobre las Profundidades de Roca Negra son preocupantes, $n. Parece que el Martillo Crepuscular colabora con el ingeniero Hierro Negro Argelmach para crear gólems de guerra con la energía de los elementales. Estos gólems podrían resultar ser armas devastadoras si las usan contra nosotros.$b$bDebes evitar que eso ocurra, $n. Ve al Taller de las Profundidades de Roca Negra, obtén los planos que van a utilizar para fabricar gólems y recupera los módulos elementales con los que les proporcionarán energía.', '', '', '', '', '', '', '', '', '', 'Vuelve con Wulf Hansreim en el Centro de Mando, al sur del Casco Antiguo de Ventormenta.', 0),
(28395, 'esMX', 'Plumas para Nafien', '', '', '', '', '', '', '', '', '', '', '', 'Vuelve con: Nafien. Zona: Frondavil.', 0),
(28396, 'esMX', 'Plumas para Grazle', '', '', '', '', '', '', '', '', '', '', '', 'Vuelve con: Grazle. Zona: Frondavil.', 0),
(28397, 'esMX', 'Nunca lo verán venir...', 'Mata a 8 enanos Pico Tormenta y 8 avizores Colmillo de Sangre en la Isla del Purgatorio.', 'Cometieron un error al no matarme cuando tuvieron la ocasión. Quizás se creyeron que Orkus se ahogaría. ¡JA! Ahora pagarán el precio de su descuido.$b$bTú y yo vamos a arrasar esta isla, $n. ¡Nunca lo verán venir! Cuando todos sus soldados estén muertos, nos enfrentaremos a sus líderes. Mantén los ojos abiertos por si encuentras planes de ataque. ¡Si nos hacemos con sus planes podremos detener toda la invasión!$b$b¡Vámonos, $n!', '', 'Enano Pico Tormenta muerto', '', '', '', '', '', '', '', 'Habla con: Matarreyes Orkus. Zona: Isla del Purgatorio, Laderas de Trabalomas.', 0),
(28398, 'esMX', 'El grimorio del piromántico', 'Mata 6 emisarios Crepusculares y quítale el grimorio de Fruto del Saber al piromántico Fruto del Saber en las Ruinas de Thaurissan, en las Profundidades de Roca Negra.', 'El poder de los Hierro Negro y de sus aliados del Martillo Crepuscular no deja de crecer en la Montaña Roca Negra. El piromántico Fruto del Saber, un mago famoso, desempeña un papel importante en el liderazgo de las tropas del Martillo Crepuscular en la región. Si pudiéramos hacernos con su grimorio, podría diseñar contrahechizos y demás formas de mitigar su magia elemental.$b$bDebes bajar a las Profundidades de Roca Negra, encontrar las Ruinas de Thaurissan y capturar el grimorio. No les muestres piedad a Fruto del Saber y a sus esbirros Crepusculares.', '', '', '', '', '', '', '', '', '', 'Vuelve con Maginor Dumas en el Sagrario del Mago, en el Barrio de los Magos de Ventormenta.', 0),
(28399, 'esMX', 'Piedras de Vínculo', 'Recupera 6 piedras vinculantes elementales de las Profundidades de Roca Negra. Encontrarás las piedras en la Ciudad Forjatiniebla, el Domicilio, las Ruinas de Thaurissan, el Cuartel Oeste y el Cuartel Este.', 'Sé de buena tinta que a IV:7 le preocupa la colaboración entre el Martillo Crepuscular y los enanos Hierro Negro de las Profundidades de Roca Negra. Podemos reaccionar a este dato, demostrar nuestra valía a la Alianza, y al mismo tiempo ganarnos una propina.$b$bEl informe menciona que los seguidores del Martillo Crepuscular han colocado unas cuantas piedras vinculantes elementales por la Ciudad Forjatiniebla, el Domicilio, las Ruinas de Thaurissan, el Cuartel Oeste y el Cuartel Este. ¡Busca y captura esas piedras!', '', '', '', '', '', '', '', '', '', 'Vuelve con Demisette Cloyce bajo El Cordero Degollado, en el Barrio de los Magos de Ventormenta.', 0),
(28400, 'esMX', '¡Héroes de la Horda!', 'Robad los planes de batalla de la Alianza y convertíos en héroes de la Horda.', '¡Ahora debemos encontrar sus planes de batalla y acabar con sus líderes! Si tenemos éxito, hay un gran señor de la guerra orco que sirvió en la guerra de Argénteos y que ahora está destacado en el Molino Tarren, en el corazón de Trabalomas. ¡Nos dará recomendaciones a los dos por esto! ¡Seremos héroes de la Horda, $n!$b$b¡Adelante! ¡Juntos derrotaremos a esa escoria de la Alianza!', 'Convertíos en héroes de la Horda', '', '', '', '', 'Convertíos en héroes de la Horda', '', '', '', 'Entrégale los planes de batalla de la Alianza al gran señor de la guerra Cromush en el Molino Tarren, en las Laderas de Trabalomas.', 0),
(28401, 'esMX', 'Los esclavos del Señor del Fuego', 'Utiliza el tótem de libertad para liberar las esencias de 6 guardias de fuego, destructores guardia de fuego o guardias de fuego llameantes en las Profundidades de Roca Negra.', 'El culto del Martillo Crepuscular y los enanos Hierro Negro agrupan sus tropas en las salas de las Profundidades de Roca Negra. Sus legiones cuentan con el apoyo de hordas y hordas de elementales de fuego sometidos al servicio del Señor del Fuego, Ragnaros.$b$bSi pudiéramos liberar a esos elementales de su vínculo podemos debilitar a nuestros enemigos y honrar a los elementos. Llévate este tótem y utilízalo con los guardias de fuego sometidos. Liberará sus espíritus de su vínculo y los devolverá a su estado natural.', '', 'Guardias de fuego liberados', '', '', '', '', '', '', '', 'Vuelve con: Clarividente Umbrua. Zona: Distrito de los Enanos, Ventormenta.', 0),
(28402, 'esMX', 'Schnottz tan rápido', 'Mata a 10 soldados de élite de Schnottz en la Cámara de la Luna.', 'Casi estoy listo, $n.$b$bTus pergaminos contenían suficiente información como para descifrar el método de encriptación. Ahora solo queda que traduzca los códigos.$b$bNecesito que explores la cámara que hay debajo del Obelisco de la Luna. Es posible que haya unos pocos soldados de Schnottz ahí abajo que se libraron de tu ataque.$b$bEncárgate de ellos; yo me encontraré contigo abajo cuando acabe.', '', 'Soldados de élite de Schnottz asesinados', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Cámara de la Luna.', 0),
(28403, 'esMX', 'Datos erróneos', 'Acompaña a Harrison Jones en la Cámara de la Luna.', 'Debería haber dos dispositivos de comunicación titánicos en esta cámara.$b$bSi mis traducciones son correctas: uno de ellos es una trampa mortal y el otro aceptará los códigos y activará el obelisco.$b$bEsperemos que no me haya equivocado.$b$bAvísame cuando estés $gpreparado:preparada;.', '', 'Datos de titán cargados', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Cámara de la Luna.', 0),
(28404, 'esMX', 'Lo haré a mano', 'Derrota al guardián titánico.', 'Sí, todo esto resulta bastante familiar.$b$bGracias a toda la información que has reunido para mí, estoy seguro de que podré activar el mecanismo. Solo necesitaré un poco de tiempo sin distracciones.$b$bTen por seguro que tan pronto como empiece, ese ensamblaje titánico tratará de detenerme.$b$bAhí es donde entras tú.$b$bNo necesito recordarte lo que nos jugamos aquí. ¡Acaba con ese guardián!', '', 'Guardián titánico derrotado', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Cámara de la Luna.', 0),
(28405, 'esMX', 'Armas de oscuridad', 'Captura 5 armas imbuidas de elementales de los enanos Yunque Colérico en las Profundidades de Roca Negra, y luego rómpelas en el Yunquenegro en Ciudad Forjatiniebla.', 'Hace mucho que las Profundidades de Roca Negra albergan a nuestros enemigos, pero IV:7 nos ha informado de que ahora los Hierro Negro y el Martillo Crepuscular están incrementando su colaboración. Gracias a los conocimientos de la secta, los enanos Hierro Negro imbuyen sus armas con poderes elementales. Han equipado a la legión Yunque Colérico con estas temibles armas nuevas.$b$bQuiero que vayas a las Profundidades de Roca Negra y reúnas las armas de los enanos Yunque Colérico que haya en el lugar. Rómpelas en el Yunquenegro, en el corazón de Ciudad Forjatiniebla.', '', 'Arma imbuida de elementales rota', '', '', '', '', '', '', '', 'Vuelve con Lord Grisillo Quiebrasombras en la Catedral de la Luz, en el Distrito de la Catedral de Ventormenta.', 0),
(28406, 'esMX', 'El ejército Hierro Negro', 'Utiliza el veneno de acción rápida para contaminar 6 raciones de grano en el Cuartel Oeste o en el Cuartel Este de las Profundidades de Roca Negra.', 'La cosa se está poniendo interesante en la Montaña Roca Negra, $n. Nuestras fuentes informan de que los enanos Hierro Negro están estrechando sus lazos con el Martillo Crepuscular y ambos se están preparando para una gran ofensiva.$b$bHe compartido el contenido del informe con figuras clave de Ventormenta y quiero que nos ayudes con la creciente amenaza Hierro Negro.$b$bLa mayoría de las raciones del ejército Hierro Negro se guardan en los cuarteles este y oeste de las Profundidades de Roca Negra. Toma este veneno y utilízalo con las reservas de grano.', '', 'Envenena las raciones de grano', '', '', '', '', '', '', '', 'Vuelve con Lord Tony Romano en el SI:7, al sur del Casco Antiguo de Ventormenta.', 0),
(28407, 'esMX', 'La solterona', 'Habla con Fanny en Kirthaven, en las Tierras Altas Crepusculares.', '¿Barbafuego? ¿¡Casarse con mi hermana!? ¡Juro que el mundo se ha vuelto loco, $n!$B$BSin embargo, puede que Kurdran tenga razón. Una bonita boda normal tranquilizaría a todo el mundo... y puede que aplaque un poco a Barbafuego. Fue fantástico luchar juntos aquí contra los ogros.$B$B¡De acuerdo! Depende de Fanny. Algo me dice que no querrá que la aten.$B$BVuela a Kirthaven y mira a ver si está dispuesta. Yo me ocuparé de los detalles desagradables con los ogros de aquí.', '', '', '', '', '', '', '', '', '', '', 0),
(28408, 'esMX', 'Algo llamativo', 'Recoge 12 plumas de búho prístinas.', 'Según la tradición, las novias Martillo Salvaje visten de blanco para mostrar su pureza. Además, llevan una corona de plumas negras, para mostrar su audacia.$B$BLas plumas de búho son las que mejor lo representan y Fanny no se merece menos. Los búhos leonados son oriundos de las Tierras Altas. Búscalos alrededor de los árboles que crecen a los largo de los acantilados y coge sus plumas.$B$BSeguramente será mejor que los mates antes.', '', '', '', '', '', '', '', '', '', 'Llévale las plumas a: Lachland MacGraff. Zona: Kirthaven, Tierras Altas Crepusculares.', 0),
(28409, 'esMX', 'Algo destilado', 'Habla con Hammelhand en el camino que hay al este de Kirthaven y escolta a una caravana de provisiones de vuelta a la ciudad.', 'Sería un insulto celebrar una boda de los Martillo Salvaje sin bebida. El propio Kurdran encargó que enviaran unos cuantos barriles de cerveza Cebatruenos desde Bancalto, pero la caravana no puede cruzar el paso.$B$BSigue el camino que hay al este, por el lado sur del Monte del Rayo, y alcanza la caravana. Busca a un tipo llamado Hammelhand, ¡y ayúdalo a traer la bebida por el paso!', '', 'Caravana de provisiones escoltada', '', '', '', '', '', '', '', 'Habla con: Lachlan MacGraff. Zona: Kirthaven, Tierras Altas Crepusculares.', 0),
(28410, 'esMX', 'Algo robado', 'Recoge una madeja de paño oscuro refinado.', 'Todo el mundo querrá ponerse sus mejores galas para esto, y el paño no abunda en las Tierras Altas.$B$BTengo entendido que esos desgraciados goblins, en la costa, usan la seda más fina para reparar sus zepelines. ¡Un desperdicio!$B$BEncuentra un zepelín que cubra la ruta entre el puerto Faucedraco y La Krazzería y rescata algo de seda del cargamento que llevan en la cubierta inferior.', '', '', '', '', '', '', '', '', '', 'Llévale el paño a: Lachlan MacGraff. Zona: Kirthaven, Tierras Altas Crepusculares.', 0),
(28411, 'esMX', 'Algo estofado', 'Reúne 8 trozos de carne de venado fresco y 5 costillas de huargo.', 'Finalmente, vamos a necesitar un festín. ¡Y nada de bocadillos diminutos! Esta muchedumbre quiere carne, y mucha.$B$BReúne venado de alce de las Tierras Altas y de ciervos. El huargo de las Tierras Altas también está bueno... trae unas costillas. Va a ser un festín como no se ha visto nunca en los Reinos del Este, $gamigo:amiga;.', '', '', '', '', '', '', '', '', '', 'Lleva la comida a: Lachlan MacGraff. Zona: Kirthaven, Tierras Altas Crepusculares.', 0),
(28413, 'esMX', 'Letra y música de...', 'Habla con Russell Brower y ayúdale a escribir una canción.', 'He escrito muchas canciones épicas en mi vida, $n, pero esta boda se merece una balada muy especial. ¡Y rápido!$B$B¿Debería escribir una canción de amor? ¿Una cancioncilla alegre? ¿Una ruda canción de borrachos?$B$BMe vendría bien algo de ayuda con la letra, si te apetece intentarlo.$B$B¡Habla conmigo y escribiremos una canción juntos!', '', 'Crea una canción', '', '', '', '', '', '', '', 'Habla con: Russell Brower. Zona: Kirthaven, Tierras Altas Crepusculares.', 0),
(28414, 'esMX', 'El tanto de la victoria', 'Entra en el Bucanero Pantoque y marca el tanto de la victoria chutando el bombalón entre las chimeneas de detrás de la meta contraria.', 'Todo depende de ti, $gchico:chica;. Has destrozado a los Tiburones Bonvapor y ahora lo único que queda es marcar el tanto de la victoria.$B$B<El entrenador se inclina hacia ti y te susurra al oído.>$B$BMira, entre nosotros, creo que tenemos que hacerlo a lo grande. No solo quiero que marques un tanto... ¡Quiero que lo mandes tan lejos que vuele entre las chimeneas de detrás de la meta!$B$BHe manipulado el bombalón para darte el empujoncito que te hará falta.$B$B¡Venga, sal ahí y haz que me sienta orgulloso!', '', 'Bombalón chutado entre las chimeneas', '', '', '', '', '', '', '', 'Vuelve con: Entrenador Paselargo. Zona: Campo Kajaro, Kezan.', 0),
(28415, 'esMX', '¡Tenemos refrescos!', 'Reúne 7 moscallamas.', 'Tenemos que actuar. Winky y Gor\'tesh se estaban peleando, así que he planeado esta ceremonia de amistad para ayudarlos a que se reconcilien. Todo iba bien hasta que...$b$bBueno, ya conoces el resto de la historia.$b$b¡Incluso he comprado bebidas!$b$bA Winky le encantan las moscallamas. Sale a buscarlas casi cada noche. Supongo que eso es lo que estará haciendo.$b$bEncontrarás moscallamas al oeste y al norte, dondequiera que haya lava. Tráeme siete, ¡y date prisa!$b$b¡Puede que Gor\'tesh se vaya también!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Oralius. Zona: Vigilia de Morgan, Las Estepas Ardientes.', 0),
(28416, 'esMX', 'Venganza ardiente', 'Mata a 5 cuidadores Roca Negra y a 5 estirpes de flamascama.', '$n... ¿eres tú? Pensé que estabas $gmuerto:muerta;; ¡igual que los demás!$b$bNo, siempre has sido fuerte, incluso entonces, incluso en Crestagrana.$b$bNuestra lucha no ha terminado, $n. Ya han atacado nuestras tierras una vez. Estoy aquí para asegurarme de que no vuelva a ocurrir.$b$bSi aún eres capaz de luchar como lo hiciste entonces, únete a mí. Puedes empezar por dirigirte hacia el sur, a Las Colinas de los Vástagos, y asesinar a sus cuidadores y a la prole de los dragones Negros.$b$bSerá como en los viejos tiempos.', '', '', '', '', '', '', '', '', '', 'Vuelve con John J. Keeshan. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28417, 'esMX', 'No han hecho nada malo', 'Consigue un vástago rojo liberado, un vástago verde liberado, un vástago azul liberado, y un vástago bronce liberado.', 'Los orcos Roca Negra de las estepas sirven a un oscuro maestro: uno que lleva a cabo retorcidos experimentos con criaturas vivas para crear su propio elenco de abominaciones. Muchos de sus sujetos de estudio son tan corruptos como su maestro, pero algunos son completamente inocentes.$B$BEn Las Colinas de los Vástagos, hacia el sur, encadenan a bebés dragón al suelo, para someterlos a tales experimentos. No pienso tolerarlo. Rompe sus cadenas y tráelos aquí... a salvo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Vellón Llamaestrella. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28418, 'esMX', 'Venganza ardiente', 'Mata a 5 cuidadores Roca Negra y a 5 estirpes de flamascama.', 'Soy un orco Roca Negra de nacimiento. He pasado gran parte de mi infancia en el interior de esa montaña.$b$b<Ariok se acerca a la Montaña Roca Negra, hacia el norte.>$b$bPero a pesar de llevar su misma sangre, no comparto sus puntos de vista. Y estoy buscando un aliado para que me ayude a detener su próximo ataque.$b$bDemuestra tu valía. Viaja hacia el sur, a Las Colinas de los Vástagos, y asesina a sus criadores y a la prole de los dragones Negros. Demuéstrame que estás $gpreparado:preparada; para esta guerra.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ariok. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28419, 'esMX', 'Abastecerse', 'Consigue 5 púas de escórpido afiladas.', 'Si vamos a enfrentarnos al clan Roca Negra, tendremos que prepararnos antes. Mi padre ya ha elaborado el plan, ahora hay que llevarlo a cabo.$B$BNecesito aguijones de escórpido... los más afilados que puedas encontrar. Las estepas están llenas de escórpidos, pero encontrarás a la mayoría en la garganta, al oeste.$b$bNo te importa para qué son. Pronto lo descubrirás.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ariok. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28420, 'esMX', 'Un futuro proyecto', 'Consigue 11 pellejos de huargo brasal.', 'Según mi padre, necesitaremos pellejos de huargo, y muchos además. No importa si están rasgados, quemados o ensangrentados, pero necesitaremos muchos.$b$bEn realidad, probablemente sea mejor que estén un poco destrozados.$b$bEncontrarás huargos tanto al oeste como al este de aquí.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ariok. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28421, 'esMX', 'A la caza de barro', 'Consigue 9 pilas de barro con motas de obsidiana.', 'Espero que no te importe mancharte un poco. Aunque a juzgar por tu aspecto, no creo que sea un problema.$b$bHacia el norte, al borde de la lava, encontrarás pilas de barro oscuro. Lo necesito.$b$bSerá mejor que no hagas preguntas, y que concentres tus esfuerzos en cumplir las órdenes, $n.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ariok. Zona: Puesto Llamaestrella, Las Estepas Ardientes.', 0),
(28422, 'esMX', 'La arena, la sidra y el orbe', 'Habla con Gorzeeki Ojovago cerca del Altar de la Tempestad.', 'Mi padre nos está esperando al este de aquí. Pero antes de que nos vayamos, tenemos que reunir más suministros. Esta vez, los conseguirás de un brujo llamado Gorzeeki Ojovago.$b$bSeguramente lo encontrarás al noroeste, cerca del Altar de la Tempestad. Dile que nos va a ayudar. Necesitamos la arena, la sidra y el orbe.$b$bÉl sabrá lo que significa.', '', '', '', '', '', '', '', '', '', 'Preséntate ante Gorzeeki Ojovago en el Altar de la Tempestad en Las Estepas Ardientes.', 0),
(28423, 'esMX', 'Los brujos tienen las mejores cosas', 'Consigue un puñado de arena de sueño, una jarra de sidra hidra vil y un orbe de cristal transparente.', '¿Ariok dice que necesita suministros? ¡Yo tengo un montón de suministros! El problema es que esos brujos me han echado a patadas de mi casa y no me dejan volver.$b$b<Gorzeeki observa tu tamaño.>$b$bPero seguramente tú serías capaz de entrar. Dirígete hacia el norte y consigue un poco de mi arena de sueño, de mi sidra hidra vil y un orbe de cristal transparente. Estoy casi seguro de que eso es lo que necesita.$b$bAh, y si por casualidad matas a algún orco por accidente mientras estás por allí, no te preocupes, no me voy a disgustar demasiado.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Gorzeeki Ojovago. Zona: Altar de la Tempestad, Las Estepas Ardientes.', 0),
(28424, 'esMX', 'Ataque umbrío', 'Asesina a Ner\'gosh el Umbrío.', 'Ner\'gosh el Umbrío es el líder de los brujos que se encuentran al norte. Es el estúpido que me sacó de mi casa cuando esos orcos Roca Negra hicieron su aparición. Bueno, son todos unos estúpidos, pero él es el más estúpido de todos.$b$bSi pretendo volver a mudarme cerca del Altar, Ner\'gosh tiene que largarse.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Gorzeeki Ojovago. Zona: Altar de la Tempestad, Las Estepas Ardientes.', 0),
(28425, 'esMX', 'Vuelve con Ariok', 'Vuelve a llevarle los suministros de brujo a Ariok en el Puesto Llamaestrella en Las Estepas Ardientes.', 'Bueno, supongo que aquí ya he acabado contigo. Iré a espantar a esos otros brujos en cuanto reúna el valor suficiente.$b$bToma, no olvides los suministros.', '', '', '', '', '', '', '', '', '', 'Preséntate ante Ariok en el Puesto Llamaestrella en Las Estepas Ardientes.', 0),
(28426, 'esMX', 'Cincelada, el corazón de las estepas', 'Mata a 15 soldados de asalto Roca Negra cualesquiera de camino a Cincelada.', 'Nos dirigimos a Cincelada, en pleno corazón de las estepas. Allí nos encontraremos con la Hermandad de Torio, así como con mi padre.$b$b¿Conoces a la Hermandad? Esos enanos Hierro Negro me han ayudado más de una vez. Es posible que volvamos a necesitar su ayuda.$b$bPasaremos por el Cobertizo Diente Negro de camino allí. ¿Qué te parece si matamos a unos cuantos Roca Negra mientras viajamos? Me estoy impacientando un poco en este campamento.', '', 'Tropa Roca Negra asesinada', '', '', '', '', '', '', '', 'Preséntate ante Stebben Menudillo en Cincelada en Las Estepas Ardientes.', 0),
(28427, 'esMX', 'Una aguja en el infierno', 'Habla con Thelaron Malaguja en Cincelada en Las Estepas Ardientes.', 'Lok\'tar, $c. Me llamo Eitrigg, de la Cruzada Argenta... anteriormente formaba parte de la guardia de honor del Jefe de Guerra. Y antes de eso formaba parte de los orcos Roca Negra.$b$bCreo que mi hijo te ha informado sobre nuestro plan. ¿No lo ha hecho? Bueno, casi mejor.$b$bLa siguiente parte del plan va a requerir cierta sutileza. Habla con Thelaron Malaguja, el sastre de la ciudad. Ya le he dado los pellejos y el barro que has recogido. Tendrá que tomarte medidas.$b$bEso es, $r: será una misión encubierta.', '', '', '', '', '', '', '', '', '', 'Habla con: Thelaron Malaguja. Zona: Cincelada, Las Estepas Ardientes.', 0),
(28428, 'esMX', 'Un disfraz perfecto', 'Lleva la cantidad apropiada de suministros de la mesa de sastre a Thelaron Malaguja en Cincelada.', 'A juzgar por tu peso, complexión y estatura, vamos a vestirte como un ogro. Su ejército está formado en su mayoría por orcos, así que encajarás perfectamente.$b$b¿Sabes algo de sastrería? Si no es así, considera esto como tu primera lección. Mi mesa de trabajo, que está ahí mismo, tiene todo lo necesario.$b$bVe, coge todo lo que creas necesario y tráelo aquí. Thelaron se encargará de todo.', '', 'Disfraz perfecto creado', '', '', '', '', '', '', '', 'Preséntate ante Eitrigg en Cincelada en Las Estepas Ardientes.', 0),
(28429, 'esMX', 'Un disfraz perfecto', 'Lleva la cantidad apropiada de suministros de la mesa de sastre a Thelaron Malaguja en Cincelada.', 'A juzgar por tu peso, complexión y estatura, vamos a vestirte como un ogro. Los ogros Pirontraña siempre han trabajado con los Roca Negra, así que encajarás perfectamente.$b$b¿Sabes algo de sastrería? Si no es así, considera esto como tu primera lección. Mi mesa de trabajo, que está ahí mismo, tiene todo lo necesario.$b$bVe, coge todo lo que creas necesario y tráelo aquí. Thelaron se encargará de todo.', '', 'Disfraz perfecto creado', '', '', '', '', '', '', '', 'Preséntate ante Eitrigg en Cincelada en Las Estepas Ardientes.', 0),
(28431, 'esMX', 'Un disfraz perfecto', 'Lleva la cantidad apropiada de suministros de la mesa de sastre a Thelaron Malaguja en Cincelada.', 'A juzgar por tu peso, complexión y estatura, vamos a vestirte como un trol. Los trols Espina Ahumada siempre han trabajado con los orcos Roca Negra, así que encajarás perfectamente.$b$b¿Sabes algo de sastrería? Si no es así, considera esto como tu primera lección. Mi mesa de trabajo, que está ahí mismo, tiene todo lo necesario.$b$bVe, coge todo lo que creas necesario y tráelo aquí. Thelaron se encargará de todo.', '', 'Disfraz perfecto creado', '', '', '', '', '', '', '', 'Preséntate ante Eitrigg en Cincelada en Las Estepas Ardientes.', 0),
(28432, 'esMX', 'En el Cobertizo Diente Negro', 'Habla con el intendente Kaoshin en el Cobertizo Diente Negro en Las Estepas Ardientes.', 'El trabajo encubierto consiste en echarle cara. Tú solo actúa como si debieras estar ahí, y todo irá bien.$b$bTu contacto en el interior del Cobertizo Diente Negro será un orco llamado intendente Kaoshin. Él NO sabe que eres $gun:una; espía, así que trata de mantener la calma. Haz todo lo que te pida.$b$b<Eitrigg te coloca un pequeño objeto mecánico en la mano.>$b$bPonte este dispositivo en el oído. Estaré en contacto para darte cualquier instrucción especial.$b$bBuena suerte ahí fuera, soldado.', '', '', '', '', '', '', '', '', '', 'Habla con: Intendente Kaoshin. Zona: Cobertizo Diente Negro, Las Estepas Ardientes.', 0),
(28433, 'esMX', 'Trabajo de recluta', 'Sácale brillo a 7 pares de botas Roca Negra.', '¡Bah! Tienes suerte de que me falte gente hoy. Si no te convertiría en $gel chico:la chica; de los azotes de la semana.$b$bLos oficiales y los soldados de alto rango necesitan que le saquemos brillo a sus botas. Las han dejado fuera de sus cabañas.$b$b¡Quiero verme reflejado en esas botas, recluta! ¡Manos a la obra!', '', 'Pares de botas Roca Negra brillantes', '', '', '', '', '', '', '', 'Vuelve con: Intendente Kaoshin. Zona: Cobertizo Diente Negro, Las Estepas Ardientes.', 0),
(28434, 'esMX', 'Recortes estratégicos', 'Usa la púa de escórpido afilada con el vuduista Timan en lo alto de El Pilar de Ceniza, con la maestra de huargos Othana en los cubiles de los huargos y con Gorlop cuando esté cerca de los charcos de lava.', '<Oyes un zumbido en el oído.>$b$b¿$n? Te habla Eitrigg.$b$bAcabamos de recibir la última información de inteligencia concerniente a tu siguiente misión. Queremos que acabes con tres elementos importantes. El primero es el vuduista Timan, al que encontrarás en lo alto de El Pilar de Ceniza. La maestra de huargos Othana se encuentra en los cubiles huargos centrales. Y por último, Gorlop está cerca de los charcos de lava, al sur.$b$bEncontrarás las púas de escórpido que recogiste junto con tus pertenencias. Usa las púas en los objetivos en el momento adecuado.', '', '', '', '', '', '', 'Eitrigg', 'Buen trabajo.', 'Eitrigg', '', 0),
(28435, 'esMX', 'El cuerno de clamakodo', 'Usa el cuerno de los clamadores para llamar a 7 kodos de guerra Roca Negra para que vuelvan al campamento. Si algún kodo se vuelve hostil, lucha con él hasta someterlo.', 'Vale, tengo un trabajo realmente legítimo e importante para ti. Tenemos que llamar a los kodos que se encuentran en los pastos del sur. El General Thorg\'izog dice que avanzaremos pronto hacia Crestagrana; y no pienso permitir que falten kodos en mis filas.$b$bUsa este cuerno cerca de un kodo. Y volverá al campamento en cuanto oiga la llamada.$b$bPero ten cuidado. A veces los kodos son un poco peleones, así que tendrás que golpearlos un poco para que te hagan caso.', '', 'Kodos de guerra Roca Negra convocados de vuelta al campamento', '', '', '', '', '', '', '', '', 0),
(28436, 'esMX', 'Quedarnos con el cuerno', 'Devuelve el cuerno de los clamadores a Eitrigg en Cincelada en Las Estepas Ardientes.', '$n, soy Eitrigg. Quiero que te quedes con ese cuerno. Estoy seguro de que podemos improvisar y sacarle provecho para nuestro plan.$b$bEstoy bastante preocupado por lo que dijo Kaoshin sobre atacar Crestagrana. Sabíamos que nos esperaba otro ataque inminente, pero no tan pronto.$b$bVuelve conmigo y tráeme el cuerno. Volveremos a hablar aquí, en Cincelada. Y trata de no estropear el disfraz. Todavía no has acabado tu operación encubierta.', '', '', '', '', '', '', 'Eitrigg', '', '', 'Preséntate ante Eitrigg en Cincelada en Las Estepas Ardientes.', 0),
(28437, 'esMX', 'General Thorg\'izog', 'Habla con el General Thorg\'izog.', 'Kaoshin resultó ser más útil de lo que esperaba, pero ya hemos acabado con él. Ha llegado el momento de que hables con el general. Creo que estás $gpreparado:preparada;.$b$bEl General Thorg\'izog es uno de los "Tres Grandes" que lideran las fuerzas de los Roca Negra aquí en Las Estepas Ardientes. Dirige sus tropas desde el Bastión de Roca Negra al noroeste. Ponte tu disfraz y ve a hablar con él. Intenta ganarte su confianza. Me mantendré en contacto, en caso de que necesite algo más de ti.', '', '', '', '', '', '', '', '', '', 'Preséntate ante el General Thorg\'izog en el Bastión de Roca Negra en Las Estepas Ardientes.', 0),
(28438, 'esMX', 'Prueba de magma', 'Habla con Wyrtle Mercenacero y pídele que libere al Señor del Magma Kolob. Después derrota al Señor del Magma Kolob en una batalla.', 'Supongo que sacaré el mayor provecho a esta situación. Los mercenarios globlin trajeron a estos enormes elementales de fuego a mi fortaleza en señal de agradecimiento por haberlos contratado. ¿Qué voy a hacer con un elemental aquí en las estepas? Es como llevar arena a la playa.$b$bSi buscas trabajo, demuestra lo que vales. Habla con este goblin de aquí y desafía a su elemental para enfrentarte con él. El ganador conseguirá mi respeto y mi tiempo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: General Thorg\'izog. Zona: Bastión de Roca Negra, Las Estepas Ardientes.', 0),
(28439, 'esMX', 'Yo soy la ley y yo soy el látigo', 'Usa la cayada de disciplina Roca Negra con 20 soldados de asalto en los Campos de Honor. Si uno de los soldados descubre tu disfraz, mátalo a golpes antes de que pueda desvelar tu identidad.', 'Llevo tiempo buscando a $gun buen:una buena; soldado fuerte como tú. Necesito a alguien que mantenga a raya a mis tropas.$b$bEn el exterior del bastión encontrarás orcos, ogros y trols que se preparan para atacar Crestagrana. Mis sargentos los mantienen a raya, pero me gustaría que los ayudases.$b$bCoge esta cayada y disciplina a algunos de mis soldados. Me da igual si se estaban comportando mal o si estaban perfectamente formados; quiero que los golpees. Quiero que se concentren, que se curtan en la batalla y que sean obedientes.$b$bY ahora, vete.', '', 'Esbirros Roca Negra golpeados', '', '', '', '', '', '', '', 'Vuelve con: General Thorg\'izog. Zona: Bastión de Roca Negra, Las Estepas Ardientes.', 0),
(28440, 'esMX', 'Abuso de poder', 'Mata a 5 sargentos Roca Negra con la cayada de disciplina Roca Negra. Derrótalos rápidamente; antes de que puedan desenmascararte.', '¿$n? Aquí Eitrigg.$b$bParece que te has ganado la confianza de Thorg\'izog; y que te ha asignado una tarea de disciplina. Eso está muy bien.$b$bNecesitamos que acabes con sus sargentos. Los encontrarás a lomos de sus lobos, en el exterior del Bastión de Roca Negra en los Campos de Honor. Usa la cayada con ellos, varias veces, hasta que mueran. Tendrás que actuar con rapidez porque si se dan cuenta de que no eres uno de ellos, podrían desenmascararte. Golpea rápida y ferozmente, $n.', '', 'Sargento Roca Negra asesinado', '', '', '', '', 'Eitrigg', 'Está hecho. Y bastante bien, por cierto.', 'Eitrigg', '', 0),
(28441, 'esMX', 'Suficiente daño para un día', 'Vuelve con Eitrigg a Cincelada.', 'Ya no tenemos ninguna necesidad estratégica de Thorg\'izog ni de las tropas de tierra de Roca Negra. Debemos pasar a la siguiente fase del plan.$b$bCuando hayas acabado en el fuerte, regresa con mi hijo y conmigo a Cincelada.', '', '', '', '', '', '', 'Eitrigg', '', '', 'Preséntate ante Eitrigg en Cincelada en Las Estepas Ardientes.', 0),
(28442, 'esMX', 'Peñasco Llamarada', 'Preséntate ante Kibler en el Peñasco Llamarada en Las Estepas Ardientes.', 'Nuestro trabajo aquí en Cincelada ha terminado, en gran medida gracias a ti. Ahora nos desplazaremos hacia el noreste, a Peñasco Llamarada.$b$bPeñasco Llamarada se encuentra en las montañas, más allá de las Ruinas de Thaurissan. Debería servir como base de operaciones para las fases finales de nuestro plan.$b$bPor supuesto, mi hijo Ariok se reunirá contigo en el camino. Igual que yo.', '', '', '', '', '', '', '', '', '', '', 0),
(28443, 'esMX', 'Cenizas negras', 'Consigue 9 montones de cenizas de obsidiana.', 'Necesito que recojas unas cuantas cosas más antes de que podamos ir a por lo que queda del ejército Roca Negra. Si vamos a hacerlo, más vale que lo hagamos bien; y eso significa que debemos estar preparados.$b$bNecesito ceniza, $n. No una ceniza cualquiera... ceniza de los mayores elementales obsidiana que merodean las mesetas del noroeste. Es una ceniza completamente negra, que es justo lo que necesitamos para nuestro próximo disfraz.$b$bNo te preocupes, tú ya tienes disfraz. Este es para otra persona... bueno, para otra... COSA.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Eitrigg. Zona: Peñasco Llamarada, Las Estepas Ardientes.', 0),
(28444, 'esMX', 'Demonios latentes de la tierra', 'Consigue 18 flamantes caídos.', 'El lecho de lava cercano, al sur de aquí, alberga a los flamantes, una especie de demonios de fuego que habitan estas estepas desde hace mucho tiempo. La situación en el ejército Roca Negra es tal que si lo hacemos con cuidado, podríamos infiltrar a unos cuantos de esos flamantes en sus filas para que causen el caos.$b$bTráeme los cadáveres de varios flamantes. Al ser demonios, son fáciles de resucitar; y después podremos usarlos para nuestros propios propósitos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Eitrigg. Zona: Peñasco Llamarada, Las Estepas Ardientes.', 0),
(28445, 'esMX', 'Un montón de deliciosos huargos', 'Usa la serrahuargos en los cuerpos de los huargos brasales gigantes asesinados para conseguir 40 chuletas de huargo.', 'Vamos a necesitar carne fresca, lo que significa que vas a tener que cazar huargos. Los huargos de esta parte de las estepas deben ser tu objetivo.$b$b<Eitrigg saca una gran espada y te hace entrega de ella.>$b$bCaza los huargos brasales gigantes. Una vez muertos, usa esta sierra para cercenar las mejores piezas de carne de sus cadáveres. Encontrarás huargos por todas partes en las estepas, pero la manada más cercana domina la zona del sureste.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Eitrigg. Zona: Peñasco Llamarada, Las Estepas Ardientes.', 0),
(28446, 'esMX', 'Recorrido sangriento', 'Mata a 25 dragauros negros o vermintes negros.', 'Mis piernas vuelven a pedir acción. ¿Te apetece dar una vuelta, $n?$b$bVamos a recorrer Roca Machacamiedo. Quiero investigar un poco el ejército de los Roca Negra antes de que avancemos; y ya que estamos por allí, supongo que será buena idea matar a algunos de camino.', '', '', '', '', '', '', '', '', '', 'Habla con: Ariok.', 0),
(28447, 'esMX', 'Vanguardia dracónica', 'Asesina a Minyoth, a la domadora de crías Akumi, a Terromath el Chamuscado y a Tugnar Faucesangre.', 'Los orcos Roca Negra no vienen solos. Ya has visto que tienen a los ogros Pirontraña y a los trols Espina Ahumada de su lado. Por desgracia para nosotros también se han aliado con el Vuelo Negro.$b$bLos orcos y los dragones ya han enviado a algunos de sus campeones para que vigilen los puntos de reunión, que están marcados con la calavera de un dragón en lo alto de una pica. Tú y yo vamos a localizar esos puntos de reunión y vamos a acabar con su vanguardia antes de que comience la batalla.$b$b¿$gPreparado:Preparada;?', '', '', '', '', '', '', '', '', '', 'Habla con: Ariok.', 0),
(28448, 'esMX', 'Un trato con un dragón', 'Entrega las crías rescatadas a Acride en Roca Desliz en Las Estepas Ardientes.', 'Mientras rodeamos Roca Machacamiedo, tenemos que hacer una parada más.$b$b¿Recuerdas las crías que liberaste en Las Colinas de los Vástagos? Me he estado encargando yo de ellas, pero ahora vamos a entregárselas a alguien que puede cuidarlos mejor que nosotros. Se encuentra en Roca Desliz, al noreste de Roca Machacamiedo.$b$bSe llama Acride, y podría ser la clave para la victoria en la próxima batalla.', '', '', '', '', '', '', '', '', '', 'Habla con: Acride. Zona: Roca Desliz, Las Estepas Ardientes.', 0),
(28449, 'esMX', 'Situando a los peones', 'Vuelve con Eitrigg en el Peñasco Llamarada en Las Estepas Ardientes.', '<Oyes un zumbido en el oído.>$b$b$n. Parece que Ariok y tú han terminado con sus tareas. Yo también he terminado las mías.$b$bVuelve al Peñasco Llamarada. He preparado unos paquetes para entregárselos a los Tres Grandes: Thorg\'izog, Neeralak y Xi\'lun. Ya conoces al General Thorg\'izog. Esta será tu oportunidad de conocer a los otros dos.$b$bAntes de matarlos, se sobreentiende.', '', '', '', '', '', '', 'Eitrigg', '', '', '', 0),
(28450, 'esMX', 'Una entrega para Thorg\'izog', 'Usa tu disfraz de Roca Negra y lleva las chuletas marinadas con sidra hidra al general Thorg\'izog en el Horno Pirontraña en Las Estepas Ardientes. Habla con Eitrigg si necesitas un nuevo disfraz de Roca Negra.', 'El General Thorg\'izog se encuentra entre los ogros en el Horno Pirontraña, una cueva en el extremo occidental de la Roca Machacamiedo. Quiero que le entregues esto a él y a los ogros.$b$bEn el interior del paquete encontrarás las chuletas de huargo que conseguiste marinadas en la sidra hidra vil que conseguimos en el Altar de la Tempestad.$b$bSi fuese tú, me abstendría de comérmelas.$b$bLlévaselo al General Thorg\'izog. Él se ocupará de que sus tropas reciban alimento y, con algo de suerte, incluso él comerá un poco.', '', '', '', '', '', '', '', '', '', 'Habla con: General Thorg\'izog. Zona: Interior del Horno Pirontraña, Las Estepas Ardientes.', 0),
(28451, 'esMX', 'Una entrega para Neeralak', 'Usa tu disfraz de Roca Negra, cuélate en El Laberinto de las Calaveras y convence al señor de los dragones Neeralak de que coja tu cajón de flamantes durmientes. Habla con Eitrigg si necesitas otro disfraz de Roca Negra.', 'Los brujos del clan Roca Negra practican con frecuencia su magia en El Laberinto de Calaveras, una cueva en la zona este de Roca Machacamiedo. Su líder, Xi\'lun, está ocupado en otro lugar, así que la cueva la mantiene ahora otro de los Tres Grandes: el señor de los dragones Neeralak. Y Neeralak es experto en dragones, no en nigromancia.$b$bHe usado la arena de sueño en esos flamantes que capturaste. Trata de convencer a Neeralak de que son diablillos de brujo, en vez de flamantes. Cuando se despierten no se alegrarán.', '', '', '', '', '', '', '', '', '', 'Habla con: Señor de los dragones Neeralak. Zona: El Laberinto de Calaveras, Las Estepas Ardientes.', 0),
(28452, 'esMX', 'Una entrega para Xi\'lun', 'Mientras usas el disfraz de Roca Negra, entrega el orbe de cristal transparente al Gran brujo Xi\'lun en lo alto de la Roca Machacamiedo en Las Estepas Ardientes. Habla con Eitrigg si necesitas un disfraz de Roca Negra nuevo.', 'Inteligencia nos informa de que el Gran brujo Xi\'lun, el último miembro de los Tres Grandes, está en el interior de la cueva en lo alto del Pico Machacamiedo, preparándose para su gran momento.$b$bEstá esperando una entrega: un orbe de dominación, con el que poder realizar un poderoso ritual de invocación. Quiero que le des esto:$b$b<Eitrigg te entrega un orbe de cristal.>$b$bEs el orbe de cristal transparente que liberaste del Altar de la Tempestad. No tiene poder. Dáselo a Xi\'lun, y cruza los dedos para que no se dé cuenta.', '', '', '', '', '', '', '', '', '', 'Preséntate ante el Gran brujo Xi\'lun en la Roca Machacamiedo en Las Estepas Ardientes.', 0),
(28453, 'esMX', '¡Preparados!', 'Preséntate ante Eitrigg en el Peñasco Llamarada en Las Estepas Ardientes.', '$n, responde. ¿Me recibes?$b$bLa batalla está a punto de comenzar. Espero que hayas entregado todos los paquetes.$b$bTe necesito en el Peñasco Llamarada, AHORA.', '', '', '', '', '', '', 'Eitrigg', '', '', '', 0),
(28454, 'esMX', 'Ataque a Roca Machacamiedo', 'Asesina a 200 invasores Roca Negra. Si pierdes tu vehículo, usa el cuerno de los clamadores para volver a invocarlo.', 'Ha llegado el momento de la verdad, $n. Es un día triste... Un día en el que los orcos Roca Negra aprenderán una lección importante. Hoy nuestro plan dará sus frutos.$b$bVen conmigo. Vamos a hablar con Acride para pedirle el favor que nos debe. Después detendremos esta invasión incluso antes de que empiece.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Eitrigg. Zona: Peñasco Llamarada, Las Estepas Ardientes.', 0),
(28455, 'esMX', 'Gloria entre el caos', 'Mata al General Thorg\'izog, al señor de los dragones Neeralak y al Gran brujo Xi\'lun.', 'Mi hijo y tú volveréis a esa montaña. Tres orcos sobrevivieron el ataque; y no descansaremos hasta que estén muertos.$b$bSí, eso es, estoy hablando de los Tres Grandes.$b$bEl General Thorg\'izog se arrastró de vuelta hasta el Horno Pirontraña y el señor de los dragones Neeralak se esconde como un cobarde en la cueva de lo alto de la montaña. Xi\'lun está en la parte trasera de El Laberinto de Calaveras, conspirando con sus colegas los brujos.$b$bDeja tu señal, $n. ¡Acaba con esos Roca Negra corruptos de una vez por todas!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Eitrigg. Zona: Peñasco Llamarada, Las Estepas Ardientes.', 0),
(28456, 'esMX', 'Botín de guerra', 'Inspecciona el cajón de suministros abandonados en el Peñasco Llamarada en Las Estepas Ardientes.', 'A pesar de que los orcos Roca Negra siguen poblando su aguja, dudo que tengan planeado acercarse a la gente inocente de Crestagrana en mucho tiempo. Ariok y tú os encargasteis de eso.$b$bCreo que hemos sido bastante ingeniosos aquí en Las Estepas Ardientes; esos suministros de brujo que recogimos nos vinieron de maravilla, al igual que las cenizas de obsidiana que utilizamos para ocultar a nuestro dragón.$b$bDe todos modos quedan todavía suministros abandonados. Coge tu pico antes de que te marches más allá de las estepas.', '', '', '', '', '', '', '', '', '', '', 0),
(28457, 'esMX', 'Una alianza peligrosa', 'Mata 6 destructores guardia de fuego y recupera los planes de ataque del general Forjainquina en el Cuartel Oeste, en las Profundidades de Roca Negra.', 'La Mano Destrozada cree que los enanos Hierro Negro y el Martillo Crepuscular trabajan juntos. Hay pruebas de que están preparando un ataque conjunto desde el interior de la Montaña Roca Negra. No podemos permitir que semejante ejército salga de la montaña.$b$bDebes entrar en las Profundidades de Roca Negra y obtener los planes de ataque del Martillo Crepuscular del general Forjainquina, en el Cuartel Oeste. Elimina a los elementales que el Martillo Crepuscular ha suministrado como apoyo de sus tropas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Grezz Puñofuria. Zona: Valle del Honor, Orgrimmar.', 0),
(28458, 'esMX', 'El grimorio del piromántico', 'Mata 6 emisarios Crepusculares y quítale el grimorio de Fruto del Saber al piromántico Fruto del Saber en las Ruinas de Thaurissan, en las Profundidades de Roca Negra.', 'El poder de los Hierro Negro y de sus aliados del Martillo Crepuscular no deja de crecer en la Montaña Roca Negra. El piromántico Fruto del Saber es un mago poderoso e influyente de la delegación del Martillo Crepuscular. Si pudiéramos hacernos con su grimorio, podría desarrollar medidas contra los hechizos y las maldiciones del Martillo Crepuscular.$b$bDebes bajar a las Profundidades de Roca Negra, encontrar las Ruinas de Thaurissan y capturar el grimorio. No les muestres piedad a Fruto del Saber y a sus esbirros Crepusculares.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ureda. Zona: Circo de las Sombras, Orgrimmar.', 0),
(28459, 'esMX', 'Piedras de Vínculo', 'Recupera 6 piedras vinculantes elementales de las Profundidades de Roca Negra. Encontrarás las piedras en la Ciudad Forjatiniebla, el Domicilio, las Ruinas de Thaurissan, el Cuartel Oeste y el Cuartel Este.', 'La Mano Destrozada ha descubierto un aumento de la colaboración entre el Martillo Crepuscular y los enanos Hierro Negro en las Profundidades de Roca Negra. Es nuestra oportunidad de atacar a nuestros enemigos y hacernos más fuertes, $n.$b$bLos seguidores del Martillo Crepuscular han colocado unas cuantas piedras vinculantes elementales por la Ciudad Forjatiniebla, el Domicilio, las Ruinas de Thaurissan, el Cuartel Oeste y el Cuartel Este. ¡Busca y captura esas piedras!', '', '', '', '', '', '', '', '', '', 'Vuelve con Kranosh en el Circo de las Sombras de Orgrimmar.', 0),
(28460, 'esMX', 'La amenaza de los Nevada', 'Mata a 15 fúrbolgs Nevada de cualquier tipo cerca de los Baños de Fuego de Escarcha.', 'Vine a Cuna del Invierno para investigar los Baños de Fuego de Escarcha. He observado que el agua parece tener... cualidades extrañas. Todavía no he podido descubrir la fuente y, para serte sincera, últimamente he tenido algunos problemas a causa de los fúrbolgs Nevada.$B$BParecen sentirse atraídos por las fuentes, igual que yo. Se han vuelto extremadamente protectores con el agua, no permiten que me acerque a los dos manantiales más grandes, al norte de aquí.$B$BMe gustaría seguir con mis estudios, ¿me ayudarás?', '', 'Fúrbolgs Nevada asesinados', '', '', '', '', '', '', '', 'Vuelve con: Donova Cubilnevado. Zona: Baños de Fuego de Escarcha, Cuna del Invierno.', 0),
(28461, 'esMX', 'Las creaciones del señor gólem', 'Obtén 5 módulos elementales de los gólems del Taller de las Profundidades de Roca Negra y recupera los planos de gólem elemental.', 'La Mano Destrozada ha descubierto datos preocupantes en las Profundidades de Roca Negra. Parece que el Martillo Crepuscular colabora con el ingeniero Hierro Negro Argelmach para crear gólems de guerra con la energía de los elementales. Estos gólems podrían resultar ser una ventaja decisiva para nuestros enemigos.$b$bVe al Taller de las Profundidades de Roca Negra, obtén los planos que van a utilizar para fabricar gólems y recupera los módulos elementales con los que les proporcionarán energía.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ormak Tirosiniestro. Zona: Valle del Honor, Orgrimmar.', 0),
(28463, 'esMX', 'El ejército Hierro Negro', 'Utiliza el veneno de acción rápida para contaminar 6 raciones de grano en el Cuartel Oeste o en el Cuartel Este de las Profundidades de Roca Negra.', 'Como miembro de la Mano Destrozada, sabes que nuestro trabajo es vigilar a los enemigos de la Horda. Hemos descubierto que los enanos Hierro Negro y sus nuevos aliados, el Martillo Crepuscular, se están preparando para el ataque.$b$bTe voy a enviar a lidiar con esta amenaza antes de que el ejército Hierro Negro se ponga en marcha. Coge este veneno y aplícalo a las raciones de grano de los soldados en las Profundidades de Roca Negra.$b$bLa mayoría de las raciones del ejército Hierro Negro se guardan en los cuarteles este y oeste de las Profundidades de Roca Negra.', '', 'Envenena las raciones de grano', '', '', '', '', '', '', '', 'Vuelve con: Gordul. Zona: Circo de las Sombras, Orgrimmar.', 0),
(28464, 'esMX', 'Sucumbir a la corrupción', 'Encuentra la caldera de Nevada en el campamento Nevada del norte.', 'La agresividad de los fúrbolgs Nevada tiene que tener un origen. Si es posible, ¡quiero llegar hasta el fondo del asunto!$b$bHe visto que los fúrbolgs de los campamentos del norte preparaban algo en una caldera. Parecían protegerla con mucho celo... Si lo que sea que se está cociendo allá está provocando esto, debo examinarlo en persona.$b$bEncuentra la caldera, si sigue allí, ¡y tráeme lo que hay dentro!', '', '', '', '', '', '', '', '', '', '', 0),
(28465, 'esMX', 'Los esclavos del Señor del Fuego', 'Utiliza el tótem de libertad para liberar las esencias de 6 guardias de fuego, destructores guardia de fuego o guardias de fuego llameantes en las Profundidades de Roca Negra.', 'El culto del Martillo Crepuscular y los enanos Hierro Negro agrupan sus tropas en las salas de las Profundidades de Roca Negra. Sus legiones cuentan con el apoyo de hordas y hordas de elementales de fuego sometidos al servicio del Señor del Fuego, Ragnaros.$b$bSi pudiéramos liberar a esos elementales de su vínculo podemos debilitar a nuestros enemigos y honrar a los elementos. Llévate este tótem y utilízalo con los guardias de fuego sometidos. Liberará sus espíritus de su vínculo y los devolverá a su estado natural.', '', 'Guardias de fuego liberados', '', '', '', '', '', '', '', 'Vuelve con: Terga Rompesuelos. Zona: Valle de la Sabiduría, Orgrimmar.', 0),
(28466, 'esMX', 'Armas de oscuridad', 'Captura 5 armas imbuidas de elementales de los enanos Yunque Colérico en las Profundidades de Roca Negra, y luego rómpelas en el Yunquenegro en Ciudad Forjatiniebla.', 'Hace mucho que las Profundidades de Roca Negra albergan a nuestros enemigos, pero la Mano Destrozada nos ha informado de que ahora los Hierro Negro y el Martillo Crepuscular están incrementando su colaboración. Gracias a los conocimientos de la secta, los enanos Hierro Negro imbuyen sus armas con poderes elementales. Han equipado a la legión Yunque Colérico con estas temibles armas nuevas.$b$bQuiero que vayas a las Profundidades de Roca Negra y reúnas las armas de los enanos Yunque Colérico que haya en el lugar. Rómpelas en el Yunquenegro, en el corazón de Ciudad Forjatiniebla.', '', 'Arma imbuida de elementales rota', '', '', '', '', '', '', '', 'Vuelve con: Caminasol Atohmo. Zona: Valle de la Sabiduría, Orgrimmar.', 0),
(28467, 'esMX', 'Baba misteriosa', 'Informa sobre tus descubrimientos a Donova Cubilnevado.', 'Dentro de la caldera hay una sustancia verdosa, pútrida y viscosa. Sea lo que sea, no puede ser bueno.$b$bLo mejor será informar a Donova de tus descubrimientos y llevar una muestra del líquido de la caldera.', '', '', '', '', '', '', '', '', '', '', 0),
(28468, 'esMX', '[DEPRECATED]Horrores tóxicos', 'Recoge 3 gotitas de horror tóxico para Donova Cubilnevado de Cuna del Invierno.', 'He estudiado la muestra que has traído contigo y aunque no estoy segura a ciencia cierta, creo que contiene restos de elementos tóxicos. Necesito hacer un estudio comparativo, y solo sé de una forma de hacerlo.$B$BCreo que los fúrbolgs Muertobosque están recogiendo estos elementos de otras criaturas corruptas de Frondavil, especialmente de los elementales que viven en el Bosque de Troncoferro, los llamados horrores tóxicos.$B$BReúne algunas muestras para que pueda compararlas, pero ten cuidado... ¡es un lugar muy peligroso!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Donova Cubilnevado. Zona: Cuna del Invierno.', 0),
(28469, 'esMX', 'Corredores Nevada', 'Encuentra y mata al corredor Nevada y quítale el cajón de Nevada.', 'Muy interesante, $n...$B$BSi se mezcla esta sustancia tóxica con el agua de las fuentes termales, pierde su toxicidad, y solo conserva la capacidad para alterar temporalmente al que la ingiere. Debe ser la razón por la que los Nevada protegen con tanto fervor las fuentes termales... las necesitan para purificar su aguardiente.$B$BTenemos que detenerlo... interrumpir el contacto entre los Nevada y los Muertobosque. Un grupo de corredores recorre el camino que separa su poblado y Frondavil. Encuéntralos, acaba con ellos y róbales su cargamento.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Donova Cubilnevado. Zona: Cuna del Invierno.', 0),
(28470, 'esMX', 'Gran Jefe Nevada', 'Mata al Gran Jefe Nevada.', 'Normalmente los fúrbolgs Nevada no son una tribu agresiva; este cambio en su comportamiento me induce a pensar que deben de estar recibiendo órdenes de su jefe. Es probable que ya no podamos deshacer el daño que han causado, pero si matamos a su líder podríamos evitar que empeore.$b$bVuelve a dirigirte al este, más allá de donde encontraste la caldera. El Gran Jefe Nevada estará allí, en la zona más al este del Puesto de los Fauces de Madera.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Donova Cubilnevado. Zona: Cuna del Invierno.', 0),
(28471, 'esMX', 'La pieza final', 'Lleva el diario mal escrito a Donova Cubilnevado de Cuna del Invierno.', 'El diario que llevaba consigo el gran jefe parece muy extenso, pero das un vistazo a un par de páginas y descubres que no puedes leer el texto. Los signos son tan toscos y están tan mal escritos que no estás $gseguro:segura; de que alguien pueda leerlos.$B$BPero quizás Donova pueda contarte lo que dice...', '', '', '', '', '', '', '', '', '', '', 0),
(28472, 'esMX', 'Las palabras del Gran Jefe', 'Lleva el registro escrito de forma rudimentaria a Kelek Guardacielo en el Lago Kel\'theril.', 'Los Nevada han dejado de ser una amenaza para mí, pero si todavía quieres descubrir qué les empujó a crear y consumir esta extraña aguardiente, creo que deberías buscar a Kelek Guardacielo.$B$BEs un druida que antes trabajaba con el Círculo Esmeralda purificando Frondavil y luego vino aquí para estudiar las ruinas.$b$bDeberías poder verlo al este, en el Lago Kel\'theril, donde pasa la mayor parte del tiempo.', '', '', '', '', '', '', '', '', '', '', 0),
(28473, 'esMX', 'Armas de oscuridad', 'Captura 5 armas imbuidas de elementales de los enanos Yunque Colérico en las Profundidades de Roca Negra, y luego rómpelas en el Yunquenegro en Ciudad Forjatiniebla.', 'Hace mucho que las Profundidades de Roca Negra albergan a nuestros enemigos, pero la Mano Destrozada nos ha informado de que ahora los Hierro Negro y el Martillo Crepuscular están incrementando su colaboración. Gracias a los conocimientos de la secta, los enanos Hierro Negro imbuyen sus armas con poderes elementales. Han equipado a la legión Yunque Colérico con estas temibles armas nuevas.$b$bQuiero que vayas a las Profundidades de Roca Negra y reúnas las armas de los enanos Yunque Colérico que haya en el lugar. Rómpelas en el Yunquenegro, en el corazón de Ciudad Forjatiniebla.', '', 'Arma imbuida de elementales rota', '', '', '', '', '', '', '', 'Vuelve con: Maestro Pyreanor. Zona: Fuerte Grommash, Orgrimmar.', 0),
(28474, 'esMX', 'Maquinaciones Crepusculares', 'Utiliza la antorcha resplandeciente para destruir 8 copias de El Credo Crepuscular en el Domicilio de las Profundidades de Roca Negra.', 'La influencia del Martillo Crepuscular en las Profundidades de Roca Negra no deja de crecer. Se han aliado con los enanos Hierro Negro y pretenden convencerlos para que ataquen fuera de la montaña.$b$bDebemos destruir los instrumentos de instigación del Martillo Crepuscular. Su influencia sobre los Hierro Negro debe menguar.$b$bQuiero que vayas al Domicilio de las Profundidades de Roca Negra y utilices esta antorcha para prenderles fuego a los libros que el Martillo Crepuscular distribuye por allí.', '', 'Copias de El Credo Crepuscular quemadas', '', '', '', '', '', '', '', 'Vuelve con: Clériga oscura Cecille. Zona: Fuerte Grommash, Orgrimmar.', 0),
(28475, 'esMX', 'Maquinaciones Crepusculares', 'Utiliza la antorcha resplandeciente para destruir 8 copias de El Credo Crepuscular en el Domicilio de las Profundidades de Roca Negra.', 'En las Profundidades de Roca Negra, el Martillo Crepuscular ha comenzado a persuadir a los Hierro Negro para reforzar su alianza y preparar sus ejércitos para una campaña fuera de la montaña.$b$bNo debemos permitir que esta manipulación resulte en una fuerza Hierro Negro-Martillo Crepuscular. Debemos destruir las herramientas de persuasión del culto.$b$bQuiero que vayas al Domicilio de las Profundidades de Roca Negra y utilices esta antorcha para prenderles fuego a los libros que el Martillo Crepuscular distribuye por allí.', '', 'Copias de El Credo Crepuscular quemadas', '', '', '', '', '', '', '', 'Vuelve con: Tyelis. Zona: Fuerte Grommash, Orgrimmar.', 0),
(28476, 'esMX', 'Maquinaciones Crepusculares', 'Utiliza la antorcha resplandeciente para destruir 8 copias de El Credo Crepuscular en el Domicilio de las Profundidades de Roca Negra.', 'En las Profundidades de Roca Negra, el Martillo Crepuscular ha comenzado a persuadir a los Hierro Negro para reforzar su alianza y preparar una campaña de conquista.$b$bDebemos actuar antes de que los cultores aviven la sed de sangre de los Hierro Negro y de sus líderes. Quizás la mejor manera de solucionar esto sea destruir el material que los cultores están distribuyendo entre los enanos.$b$bQuiero que vayas al Domicilio de las Profundidades de Roca Negra y utilices esta antorcha para prenderles fuego a los libros que el Martillo Crepuscular distribuye por allí.', '', 'Copias de El Credo Crepuscular quemadas', '', '', '', '', '', '', '', 'Vuelve con: Vidente Liwatha. Zona: Valle de la Sabiduría, Orgrimmar.', 0),
(28477, 'esMX', 'Maquinaciones Crepusculares', 'Utiliza la antorcha resplandeciente para destruir 8 copias de El Credo Crepuscular en el Domicilio de las Profundidades de Roca Negra.', 'Nueh\'tros enemigos maquinan contra nosotros en las salas de las Profundidades de Roca Negra. Los cultores del Mah\'tillo Crepuh\'cular predican a los Hierro Negro y les dan libros, diciendo que es hora de ir a la guerra. Con un ejéh\'cito Hierro Negro bajo su control, el Mah\'tillo Crepuh\'cular sería una fueh\'za foh\'midable. ¡Debemos acabáh con la agitación!$b$b¡Quiero que vayas al Domicilio de las Profundidades de Roca Negra y utilices eh\'ta antoh\'cha para quemáh los libros del Mah\'tillo Crepuh\'cular!', '', 'Copias de El Credo Crepuscular quemadas', '', '', '', '', '', '', '', 'Vuelve con: Caminasombras Zuru. Zona: Valle de los Espíritus, Orgrimmar.', 0),
(28478, 'esMX', 'Maquinaciones Crepusculares', 'Utiliza la antorcha resplandeciente para destruir 8 copias de El Credo Crepuscular en el Domicilio de las Profundidades de Roca Negra.', '¡No les bastaba con que su maestro destrozara el mundo, no! El Martillo Crepuscular se está esforzando al máximo para unir a nuestros enemigos en nuestra contra, especialmente en las Profundidades de Roca Negra. Tienen todo un equipo de emisarios destacado allí para distribuir propaganda con intención de comenzar una campaña conjunta.$b$bSiempre he oído que el medio es el mensaje; pues bien, ¡es hora de destruir el mensaje!$b$b¡Quiero que vayas al Domicilio de las Profundidades de Roca Negra y utilices esta antorcha para quemar esos libros del Martillo Crepuscular!', '', 'Copias de El Credo Crepuscular quemadas', '', '', '', '', '', '', '', 'Vuelve con: Hermano Sacraplata. Zona: Suburbios Goblin, Orgrimmar.', 0),
(28479, 'esMX', 'Las Ruinas de Kel\'Theril', 'Habla con el espíritu kaldorei en el lago Kel\'theril, en Cuna del Invierno.', 'En este lago, los Altonato robaron el Cristal de Zin-Malor. El cristal era un artefacto poderoso que manipulaba la magia Arcana de forma salvaje e impredecible... pero solo los dignos podían utilizarlo, a los demás, los condenaba.$B$BLos espíritus que vagan por aquí se remontan a varias generaciones, todos ellos quedaron atados aquí por Zin-Malor. Algunos querrán hablar y contar su historia.$B$BSi quieres conocer el fin de Zin-Malor, busca al espíritu que hay en el centro del lago...', '', '', '', '', '', '', '', '', '', '', 0),
(28480, 'esMX', 'Tenientes de la oscuridad', 'Asesina al señor escorpión Namkhare y al sumo sacerdote Sekhemet.', 'Los ejércitos de Ramkahen están siendo masacrados por los guardianes inmortales de Neferset.$B$BLa única forma de derrotarlos es asesinar al Faraón oscuro de Neferset.$B$BPero antes de encargarnos de él, vamos a tener que ocuparnos de sus tenientes.$B$BDirígete al otro lado de la línea de batalla y asesina al señor escorpión Namkhare y al sumo sacerdote Sekhemet. Solo entonces estaremos preparados para enfrentarnos al Faraón oscuro.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Rey Phaoris. Zona: Afueras de la Ciudad de Neferset, Uldum.', 0),
(28482, 'esMX', 'El regalo de Sullah', 'Habla con Harrison Jones en el Precipicio del Peregrino.', 'El pequeño Jones me ha dicho que ustedes dos tienen que subir a esa montaña.$b$bBueno, no van a llegar lejos con esos soldados merodeando por todas partes como hormigas en un cadáver.$b$bAlgunos de mis amigos confiscaron algunas de las herramientas del enemigo. Facilitará un poco su viaje.$b$bDirígete a la cresta de la montaña, al norte, las encontrarás allí.$b$b¡Buena suerte a los dos!', '', '', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Precipicio del Peregrino.', 0),
(28483, 'esMX', 'Haz sangrar al enemigo', 'Consigue 10 insignias Neferset.', 'No te voy a mentir, $n. Tenemos ante nosotros un desafío tremendo.$B$BCuando accedas a las líneas enemigas en la Ciudad de Neferset, quiero que me traigas la insignia de toda la escoria Neferset que derrotes.$B$BLa moral de nuestras tropas subirá como la espuma cuando sepan que has asestado un buen golpe al enemigo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Rey Phaoris. Zona: Afueras de la Ciudad de Neferset, Uldum.', 0),
(28484, 'esMX', 'El corazón de la cuestión', 'Reúne 12 corazones de yeti palpitantes.', 'El magus lleva demasiado tiempo ocioso, y un mago ocioso a menudo conduce a planes muy poco meditados. Esta vez debo ocuparme de recoger órganos de varias bestias con la intención de dar poder algún tipo de vara de control. Soy demasiado frágil para andar por ahí cazando bestias, ¡especialmente yetis!$B$B¿Quizás tú lo harías por mí si te ofreciera una recompensa de algún tipo? Todo lo que necesito es que te dirijas al oeste, a las cuevas de los yetis, y que mates yetis. Arráncales del pecho sus corazones palpitantes y tráemelos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Vigilante Bel\'varil. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28485, 'esMX', 'Señor de los yetis Yetimus', 'Adquiere el cuerno retorcido de Yetimus.', 'Durante años los yetis de montaña de esta región han campado a sus anchas. ¡Nuestra tolerancia al tratar con la amenaza yeti ha dado lugar a una aberración! Yetimus, señor de todos los yetis, ha adquirido un tamaño y una fuerza que nuestra guardia es sencillamente incapaz de manejar. Tememos que su apetito lo conduzca cerca del Molino Tarren y nos devore a todos.$b$bReúne un grupo adecuado de aventureros y despacha a la bestia. Merodea por el campo, al oeste.$b$bTráeme uno de sus cuernos y te recompensaré con generosidad.', '', '', '', '', '', '', 'Yetimus', '', '', 'Entrégale el cuerno retorcido de Yetimus al Guardia de la Muerte Samsa en el Molino Tarren, en las Laderas de Trabalomas.', 0),
(28486, 'esMX', 'La táctica de Salhet', 'Escolta al capitán forestal Ramkahen al territorio superior.', 'La Ciudad de Neferset está demasiado bien defendida. Sin embargo la montaña que está al lado no lo está.$B$BHe hablado con el capitán forestal y está dispuesto a dirigir a unos cuantos de sus hombres para asegurar la cima de la montaña.$B$BPero con una condición, $n. Solo acepta si encabezamos el ataque con ellos.$B$BTiene que ser un grupo pequeño, si no atraeremos la atención del enemigo demasiado pronto. Pero confía en mí... los forestales de Ramkahen son duros de pelar. Si estás con ellos, no hay duda de que lo conseguiremos.', '', 'Territorio superior asegurado', '', '', '', '', '', '', '', 'Vuelve con: Salhet. Zona: Afueras de la Ciudad de Neferset, Uldum.', 0),
(28487, 'esMX', 'Los problemas personales de Humbert', 'Recupera la espada de Humbert, el yelmo de Humbert y los pantalones de Humbert.', 'Qué vergüenza. ¿Por dónde empiezo?$b$bVerás, Melisara me envió a investigar la amenaza yeti en las cuevas que hay al oeste, cerca de aquí. Se estaba haciendo tarde y me estaba empezando a pesar la armadura. Me la quité y decidí darme un paseo. Sí, eh, me fui a darme un paseo. El caso es que cuando volví, ¡descubrí que me habían robado el equipo! Fueron los yetis. Estoy seguro. Se llevaron mis pantalones, mi espada y el yelmo, y se fueron a su cueva. Recupéralos y te recompensaré.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Guardia de la Muerte Humbert. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28488, 'esMX', 'Bajo la superficie', 'Recupera un racimo de cristal de rubí enorme.', 'Entre las otras gemas preciosas que hay ocultas en las profundidades fuera de nuestro alcance en las Profundidades Desmoronadas, hay unos racimos de cristales de rubí. Están imbuidos de energía terrible.$B$BNo será fácil obtenerlos, pues están bien protegidos. Pero tú eres $gterco:terca; y valiente. Creo que podrías hacerlo.$B$BEn las Profundidades Desmoronadas, busca donde los túneles acaban bruscamente en piedra. Los racimos a veces se encuentran en esos pasajes. Si encuentras uno, tráemelo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Felsen el Duradero. Zona: Trono de Therazane, Infralar.', 0),
(28489, 'esMX', 'Sándwiches de venado', 'Reúne 8 trozos de carne de venado.', '¿Alguna vez has comido un sándwich de venado? Yo tampoco, pero deben de estar deliciosos. No me dejo llevar por la comida, pero soy un hombre de negocios. Si mis clientes quieren sándwiches de venado, ¿quién soy yo para llevarles la contraria?$b$bSeguramente te estarás preguntando: "¿Y esto qué tiene que ver conmigo?". Yo te lo diré, $c: ¡necesito carne de venado! Tráeme carne de venado de los venados de Trabalomas y te pagaré. ¿A que suena bien?$b$b¡Ponte en marcha! Al oeste es donde hay más venados.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Derak Ocaso. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28490, 'esMX', 'Se busca héroe: ¡Costa Oscura!', 'Preséntate ante la sacerdotisa Dentaria en Lor\'danel en Costa Oscura.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante la sacerdotisa Dentaria en Lor\'danel en Costa Oscura.$B$BLa gente de Lor\'danel necesita tu ayuda para que te encargues del cuidado de los supervivientes de la destrucción de Auberdine y para que asegures su ciudad contra el Martillo Crepuscular. Habla con Vesprystus, el maestro de hipogrifos, en Aldea Rut\'theran, en el exterior de Darnassus y él te organizará un vuelo hasta la Costa Oscura.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28491, 'esMX', 'No son luciérnagas, son moscallamas', 'Reúne 7 moscallamas.', 'La mayor parte de mis compañeros residentes en el Peñasco Llamarada parecen haberlo abandonado en algún momento. Supongo que Las Estepas Ardientes no eran lo bastante INTERESANTES para ellos.$b$bNo es mi caso. Yo siempre encuentro motivos para quedarme, y el último resultan ser las moscallamas que han aparecido últimamente.$b$bAparecen cerca de la lava durante el día. Por la noche, se las encuentra casi por todas partes.$b$bSi no te importa reunir unas cuantas, te recompensaré por ello.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Kibler. Zona: Peñasco Llamarada, Las Estepas Ardientes.', 0),
(28492, 'esMX', 'Se busca héroe: ¡Vallefresno!', 'Preséntate ante la centinela Shyela en el Refugio de Orendil al noroeste de Vallefresno.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante la centinela Shyela en el Refugio de Orendil al noroeste de Vallefresno.$B$B¡No podemos permitir que continúe la agresión de la Horda en Vallefresno! Necesitamos tu ayuda para repeler a los invasores y restaurar el bosque sagrado. Ve al sur hacia la Vega Crepuscular en Costa Oscura para llegar al bosque de Vallefresno.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28493, 'esMX', '¡La orden del Jefe de Guerra: ¡Vallefresno!', 'Preséntate ante Kadrak en La Empalizada de Mor\'shan en la frontera entre Los Baldíos del Norte y Vallefresno.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Kadrak en La Empalizada de Mor\'shan en la frontera entre Los Baldíos del Norte y Vallefresno. Ayúdanos a llevar a los elfos de la noche fuera del bosque, y así podamos reclamar sus recursos para nuestro pueblo.$B$BPara llegar hasta La Empalizada de Mor\'shan, toma al norte el Camino del Oro desde El Cruce en Los Baldíos del Norte.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28494, 'esMX', '¡La orden del Jefe de Guerra: Los Baldíos del Norte!', 'Preséntate ante Kargal Marca de Guerra en la Avanzada del Puente en Los Baldíos del Norte.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Kargal Marca de Guerra en la Avanzada del Puente en Los Baldíos del Norte.$B$BNecesitamos tu ayuda para asegurar Los Baldíos del Norte contra los usurpadores jabaespines y centauros.$B$BPara llegar hasta la Avanzada del Puente, viaja hacia el oeste atravesando la Cuenca Furia del Sur en Durotar y cruza el puente que lleva a Los Baldíos del Norte.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28495, 'esMX', 'Una posibilidad de luchar', 'Salva 10 cervatos de la colina.', '¡Bendita sea la Luz! ¡Necesito tu ayuda!$b$bDe camino a Trabalomas me fijé en varias familias de ciervos adorables. Cuando me acerqué para acariciar a uno de los cervatos, un gato montés hambriento saltó y lo mató. Salí corriendo hasta el Molino Tarren y juré solucionar la situación de los cervatos de la colina. Ahora, tras días de experimentación, ¡he creado la salvación del cervato de la colina!$b$bLlévate mi varita a los campos que hay al oeste y utilízala para potenciar a los cervatos de la colina. Cuando estén potenciados, ¡podrán defenderse solos!', '', 'Cervato de la colina "salvado"', '', '', '', '', '', '', '', 'Vuelve con: Consejera Nochealba. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28496, 'esMX', 'Orden del Jefe de Guerra: ¡Azshara!', 'Preséntate ante el jefe de personal Grabbit en la Puerta Trasera de Orgrimmar, en Azshara.', 'Por la presente, se ordena a todos los miembros aptos de la Horda que se presenten ante Ag\'tor Puñosangre en la Puerta Trasera de Orgrimmar, en Azshara.$B$B¡Hay que ayudar a hacer retroceder a las fuerzas invasoras de la Alianza y asegurar Azshara por la gloria de la Horda!$B$BAbandona Orgrimmar por la puerta norte para llegar a la Puerta Trasera de Orgrimmar, en Azshara.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28497, 'esMX', 'Fuego desde el cielo', 'Mata a 100 soldados de Schnottz $gmontado:montada; en artillería confiscada.', 'Sullah no estaba de broma. ¡Esa colina está plagada de soldados!$b$bSube y hazte con nuestros objetivos.$b$b¡No desperdicies ni un solo tiro, $n! Tenemos que conseguir subir ahí arriba.', '', 'Soldados de infantería de Schnottz asesinados', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Precipicio del Peregrino.', 0),
(28498, 'esMX', 'El secreto de Nahom', 'Consigue 8 trozos de tablilla de Atulhet.', 'Existe una vieja historia sobre Nahom. Habla de cómo un poderoso profeta llamado Atulhet se quedaba con los tesoros de los enemigos canalizando el poder del sol a través de este templo.$B$BLa mayoría cree que no es más que una leyenda, pero ese poder... sin duda nos sería de mucha ayuda ahora.$B$BLos viles Neferset han saqueado la Tumba de Atulhet. Se han llevado todos los artefactos de poder y han roto las tablillas que codifican sus memorias.$B$BDirígete a las Tumbas de los Precursores, al este de aquí, y recupera todos los fragmentos que encuentres.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Salhet. Zona: Nahom, Uldum.', 0),
(28499, 'esMX', 'Castigar a los intrusos', 'Asesina a 10 intrusos Neferset cualesquiera en las Tumbas de los Precursores.', 'Nosotros, los sacerdotes de Nahom, somos los guardianes de las Tumbas de los Precursores.$B$BDesde que los Neferset siguen a sus nuevos amos, han cometido grandes herejías.$B$BRoban las tumbas sagradas en busca de artefactos poderosos y destruyen valiosas reliquias en el proceso.$B$BDirígete a las tumbas, al este de aquí, y castiga a los ladrones de tumbas por sus transgresiones; si no, se unirán a sus hermanos cuando los Neferset ataquen Nahom.', '', 'Intruso Neferset asesinado', '', '', '', '', '', '', '', 'Vuelve con: Profeta del Sol Tumet. Zona: Nahom, Uldum.', 0),
(28500, 'esMX', 'La clave de Keset', 'Consigue la clave de Keset.', '<Salhet pasa un rato observando las tablillas con los sacerdotes a su alrededor.>$B$BEstá todo aquí, $n. Atulhet construyó una potente arma en el interior de este templo y la única forma de acceder es con la clave adecuada.$B$BSe supone que está escondida en el Paso de Keset. Esperemos que los saqueadores Neferset no hayan llegado todavía hasta ella. En ese lugar es donde opera el asaltante Lord Havat; y él es el más despiadado de todos.$B$BPero sin refuerzos, es posible que esta sea nuestra única oportunidad de defender Nahom.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Salhet. Zona: Nahom, Uldum.', 0),
(28501, 'esMX', 'La defensa de Nahom', 'Habla con el sargento Ramkahen y defiende con éxito Nahom.', 'El enemigo se acerca... y son muchos.$B$BNo recibiremos más refuerzos. Esperemos ser capaces de detener el avance Neferset.$B$BSi Nahom cae, Ramkahen será la siguiente.$B$BSal fuera y habla con uno de mis sargentos cuando estés $glisto:lista;. Te ayudaré a liderar las fuerzas que tenemos lo mejor que pueda.', 'La defensa de Nahom', '', '', '', '', 'La defensa de Nahom', '', '', '', 'Vuelve con: Salhet. Zona: Nahom, Uldum.', 0),
(28502, 'esMX', 'El Señor de la guerra bandido', 'Asesina al señor de la guerra Ihsenn.', 'Nuestra ley exige que los que están tras estos ataques reciban su castigo.$B$BEl cabecilla de la banda de bandidos es un hombre conocido como señor de la guerra Ihsenn.$B$BLo encontrarás en el extremo occidental del desierto. Asegúrate de que su trasgresión no quede sin castigo.', '', '', '', '', '', '', 'Señor de la guerra Ihsenn', '', '', 'Vuelve con: Sacerdote del Sol Asaris. Zona: Sello del Rey Sol, Uldum.', 0),
(28503, 'esMX', 'Se busca héroe: ¡Las Mil Agujas!', 'Preséntate ante Caryssia Cazaluna en Nueva Thalanaar, en la frontera entre Feralas y Las Mil Agujas.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Caryssia Cazaluna en Nueva Thalanaar, en la frontera entre Feralas y Las Mil Agujas.$b$bLas centinelas necesitan tu ayuda para rechazar a los asaltantes Tótem Siniestro que controlan la zona. Para llegar a Nueva Thalanaar, viaja al este de Feralas, cerca del linde con Las Mil Agujas.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28504, 'esMX', '¡La orden del Jefe de Guerra: Las Mil Agujas!', 'Preséntate ante Nyse en Piñón de Barro, al sur del Marjal Revolcafango.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Nyse, en Piñón de Barro. Únete a las fuerzas de la Horda que luchan contra los Tótem Siniestro rebeldes que dominan la zona.$b$bNyse te proporcionará un transporte hasta el frente. Te espera en la posada de Piñón de Barro, al sur del Marjal Revolcafango.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28505, 'esMX', 'La batalla por Andorhal', 'Habla con Guthrum Tronapuño para volar a Andorhal, en las Tierras de la Peste del Oeste. Luego preséntate ante Thassarian en el interior de Andorhal.', 'Acabo de enterarme, $gchico:chica;. No suena nada bien.$B$BLa ciudad de Andorhal está en mitad de una guerra a tres bandas entre los Renegados, la Alianza y la Plaga. El rey Wrynn ha apostado por un caballero de la Muerte para liderar su ataque, pero no me cabe duda de que le vendrá bien recibir toda la ayuda posible.$B$BOdio verte marchar, pero han preguntado por ti en concreto, $n. Ve fuera y habla con Guthrum Tronapuño. Te enviará en el primer grifo que salga para Andorhal.', '', '', '', '', '', '', '', '', '', 'Preséntate ante Thassarian en el interior de Andorhal, en las Tierras de la Peste del Oeste.', 0),
(28506, 'esMX', 'La marcha de los Pico Tormenta', 'Presencia la marcha de los Pico Tormenta.', 'Estos planes que has recuperado cuentan una historia interesante, $n. Los Pico Tormenta han estado desplazando sus ejércitos desde el Valle de Alterac a los "cuatro dedos" de Trabalomas desde hace más de un mes. De algún modo han conseguido establecer sus instalaciones en secreto sin que se enteraran nuestras tropas. Si no hubiéramos recibido estos planes, dentro de una semana habrían marchado sobre nosotros y aniquilado todo a su paso.$b$bSin embargo, con estos planes podemos cambiar las tornas.$b$bEsto es lo que debemos hacer...', 'Presencia la marcha de los Pico Tormenta.', '', '', '', '', 'Presencia la marcha de los Pico Tormenta.', '', '', '', 'Habla con: Gran señor de la guerra Cromush. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28507, 'esMX', 'Se busca héroe: ¡Tanaris!', 'Preséntate ante Kelsey Chispacero en Gadgetzan en Tanaris.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Kelsey Chispacero en Gadgetzan.$B$BLa Alianza necesita tu ayuda para ganar las concesiones del barón local y acceder a los valiosos recursos de la zona. Puedes llegar a la Gadgetzan si viajas al sur desde El Piélago de Sal en Las Mil Agujas.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28508, 'esMX', 'La batalla por Andorhal', 'Habla con Kellen Kuhn para volar a Andorhal, en las Tierras de la Peste del Oeste. Luego preséntate ante Koltira Tejemuerte en el interior de Andorhal.', 'Acabo de recibir una misiva de lo más peculiar... Peculiar de verdad.$B$BLa ciudad de Andorhal está en mitad de una guerra a tres bandas entre los Renegados, la Alianza y la Plaga. Parece que Sylvanas se ha puesto en marcha, y, para poner las cosas más interesantes, ha puesto al mando a Koltira Tejemuerte, el caballero de la Muerte.$B$BHan preguntado por ti en concreto, $n. Habla con Kellen Kuhn, el cuidador de murciélagos. Te enviará en el primer murciélago que salga para Andorhal.', '', '', '', '', '', '', '', '', '', 'Preséntate ante Koltira Tejemuerte en el interior de Andorhal, en las Tierras de la Peste del Oeste.', 0),
(28509, 'esMX', 'La orden del Jefe de Guerra: ¡Tanaris!', 'Preséntate ante Megs Trituramatic en Gadgetzan en Tanaris.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Megs Trituramatic en Gadgetzan. Ayuda a la Horda y al Cártel Pantoque a establecer una presencia en Tanaris antes de que lo haga la Alianza.$B$BPara llegar a Gadgetzan, en Tanaris, dirígete hacia el sur desde el Barcódromo de Fizzle y Pozzik al sudeste de Las Mil Agujas.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28510, 'esMX', '¡La orden del Jefe de Guerra: Feralas!', 'Preséntate ante Konu Tótem de Runa en el Campamento Ataya, en Feralas.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Konu Tótem de Runa en el Campamento Ataya, en Feralas. Ayuda a la Horda a proteger el gran bosque de la Alianza y de los Tótem Siniestro.$b$bPara llegar al Campamento Ataya, viaja al sur desde Desolace y entra en Feralas.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28511, 'esMX', 'Se busca héroe: ¡Feralas!', 'Preséntate ante Telaron Vuelavento en el Reposo de la Soñadora, en Feralas.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Telaron Vuelavento en el Reposo de la Soñadora, en Feralas.$b$bLa Alianza necesita tu ayuda para superar a nuestros enemigos, la Horda y los Tótem Siniestro. Para llegar al Reposo de la Soñadora, viaja al sur desde Desolace y entra en Feralas.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28512, 'esMX', 'En ayuda de la Hermandad del Torio', 'Habla con Jack Patarroca en el Avance del Torio, en la Garganta de Fuego.', 'Es posible que los enanos Hierro Negro sean calculadores y maliciosos, pero no todos son enemigos. He hablado varias veces con los enanos de la Hermandad del Torio y siempre nos han ayudado.$b$bUn amigo mío, Jack Patarroca, vino hace poco preguntando si quería ir con él a un tipo de expedición. Parecía importante.$b$bYo tengo mucho trabajo, pero igual a ti no te importa ir. Vete al oeste, por el camino a la Garganta de Fuego. Te encontrarás con él al poco de abandonar las Tierras Inhóspitas.', '', '', '', '', '', '', '', '', '', '', 0),
(28513, 'esMX', 'El orgullo de los Altonato', 'Mata a 8 Altonato angustiados o sufridos.', 'Hace diez mil años...$b$bLos Altonato vivíamos aquí, en prosperidad. Nos considerábamos superiores a las clases comunes de los demás elfos de la noche. La riqueza y la magia satisfacían todas nuestras necesidades, así que llevábamos vidas de indulgencia y ocio. Y codicia...$b$bLos espíritus que ves por aquí están embargados por los remordimientos y el arrepentimiento. Su angustia los aprisiona. Si quieres saber más sobre Kel\'theril y Zin-Malor, libéralos de su agonía.', '', 'Espíritus Altonato liberados', '', '', '', '', '', '', '', 'Vuelve con: Espíritu kal\'dorei. Zona: Lago Kel\'theril, Cuna del Invierno.', 0),
(28514, 'esMX', 'Vellón Llamaestrella', 'Preséntate ante Vellón Llamaestrella en el Puesto Llamaestrella, en Las Estepas Ardientes.', 'Consigo pasar muy poco tiempo fuera de La Garganta de Fuego estos días. Hace meses que quiero visitar a un amigo en Las Estepas Ardientes, pero no he tenido la oportunidad.$B$BSu nombre es Vellón Llamaestrella. Aunque no es un miembro de la Hermandad, es un amigo de confianza.$B$B¿Lo saludarás de mi parte? Tendrás que viajar al sur, a través de la base de la Montaña Roca Negra. Tú sigue siempre hacia el sur... lo encontrarás.$B$BGracias.', '', '', '', '', '', '', '', '', '', '', 0),
(28515, 'esMX', 'Vellón Llamaestrella', 'Preséntate ante Vellón Llamaestrella en el Puesto Llamaestrella, en Las Estepas Ardientes.', 'Consigo pasar muy poco tiempo fuera de La Garganta de Fuego estos días. Hace meses que quiero visitar a un amigo en Las Estepas Ardientes, pero no he tenido la oportunidad.$B$BSu nombre es Vellón Llamaestrella. Aunque no es un miembro de la Hermandad, es un amigo de confianza.$B$B¿Lo saludarás de mi parte? Tendrás que viajar al sur, a través de la base de la Montaña Roca Negra. Tú sigue siempre hacia el sur... lo encontrarás.$B$BGracias.', '', '', '', '', '', '', '', '', '', '', 0),
(28517, 'esMX', 'El Roble Quejumbroso', 'Habla con Genn Cringris en el Roble Quejumbroso, en Darnassus.', 'Así que este es... nuestro nuevo hogar. No sé si volveré a sentir alguna vez que realmente tengo un hogar.$B$BPero no debemos menospreciar lo que los elfos de la noche nos han ofrecido. Su raza no es precisamente propensa a dar la bienvenida a cualquiera. Es un gran gesto de fe y generosidad el que han hecho al acogernos.$B$BGwen y Cringris están en la ciudad, en el Roble Quejumbroso. Deberías pasar por allí. Toma el portal que está bajo el árbol que queda al norte de aquí y después busca el Roble Quejumbroso en la zona norte de la ciudad.', '', '', '', '', '', '', '', '', '', '', 0),
(28518, 'esMX', 'El legado de los elfos nobles', 'Obtén la memoria de Zin-Malor del espíritu del archimago Maenius.', 'Hace cien años...$b$bUn grupo de elfos nobles, entre los que me encontraba yo, llegamos aquí desde nuestro hogar, Quel\'Thalas. Buscábamos los antiguos misterios de Kel\'theril, para averiguar por qué se destruyó.$b$bEncontramos restos en el hielo, fragmentos del cristal. El archimago al que acompañábamos no tardó en caer bajo su influjo. En nuestra ingenuidad, no nos dimos cuenta hasta que fue demasiado tarde.$b$bSu espíritu vaga por el sureste, entre aquellos a los que condujo a la locura, que aún se aferran al recuerdo de su preciado fragmento...', '', '', '', '', '', '', 'Archimago Maenius', '', '', 'Vuelve con el espíritu quel\'dorei en el centro del Lago Kel\'theril, en Cuna del Invierno.', 0),
(28519, 'esMX', 'El dolor de los elfos de sangre', 'Mata a 7 espíritus desdichados o espectros desdichados en el Lago Kel\'theril.', 'Hace un año...$b$bLa leyenda del Cristal de Zin-Malor llegó a Lunargenta, y conduje a un grupo de los mejores guerreros y eruditos posibles hasta esta tierra. Trajimos una buena cantidad de cristales de maná, para que ninguno de nosotros se sintiera tentado de probar el propio cristal.$b$bAl cristal no le hacía falta nuestra ansia para destruirnos. En cuanto cayó en nuestras manos, los corrompió a todos menos a mí hasta convertirlos en bestias terribles.$b$bEsas desgraciadas almas aún vagan en busca de más vidas que anclar a este lago. ¿Les mostrarás piedad... o huirás con la esperanza de morir en un lugar más seguro?', '', '', '', '', '', '', '', '', '', 'Vuelve con el espíritu sin\'dorei en el centro del Lago Kel\'theril, en Cuna del Invierno.', 0),
(28520, 'esMX', 'La caída de la Ciudad de Neferset', 'Asesina al faraón oscuro Tekahn en la Ciudad de Neferset, en Uldum.', 'Ahora estamos listos para atacar, $n.$B$BSi acabamos con el faraón oscuro Tekahn, los colosos inmortales caerán y nuestros ejércitos podrán marchar sobre la Ciudad de Neferset.$B$BBúscalo y enfréntate a él sin temor. Me aseguraré de que no estés $gsolo:sola; cuando llegue el momento de acabar con él.', '', '', '', '', '', '', 'Faraón oscuro Tekahn', '', '', 'Vuelve con: Rey Phaoris. Zona: Ramkahen, Uldum.', 0),
(28521, 'esMX', 'Habla con Salfa', 'Viaja por el Bastión Fauces de Madera y sal a Cuna del Invierno. Habla con Salfa, que está haciendo guardia en la entrada del Bastión Fauces de Madera.', 'La amenaza de la corrupción no proviene únicamente de los fúrbolgs Muertobosque del sur, también del este, de los fúrbolgs Invernales de Cuna del Invierno. Si quieres seguir ayudándonos, habla con Salfa. Está al otro lado del Bastión, en la entrada de Cuna del Invierno. Sigue el camino de la izquierda para llegar hasta allí.', '', '', '', '', '', '', '', '', '', '', 0),
(28522, 'esMX', 'Actividad de los Nevada', 'Reúne 10 cuentas de Espíritu Nevada de los fúrbolgs Nevada.', 'Los Fauces de Madera solemos ir a lo nuestro, $n. Aunque permitimos el paso a aquellos en quienes confiamos, intentamos evitar al resto de las tribus de fúrbolgs en la medida de lo posible.$b$bLa tribu Nevada cada vez es más hostil con nosotros. Parecen estar en un estado de rabia constante, totalmente consumidos por su propio miedo y odio hacia todo lo que no comprenden.$b$bLos Nevada llevan cuentas de espíritu, aunque salta a la vista que no han conseguido protegerlos de la corrupción. Tráeme 10 cuentas para demostrarme que has diezmado sus filas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Salfa. Zona: Cuna del Invierno.', 0),
(28523, 'esMX', 'Más cuentas para Salfa', '', '', '', '', '', '', '', '', '', '', '', 'Vuelve con: Salfa. Zona: Frondavil.', 0),
(28524, 'esMX', 'Una entrega para Donova', 'Entrégale la cesta de Salfa a Donova Cubilnevado en Cuna del Invierno.', 'Donova Cubilnevado es una enana amable que frecuenta los baños cercanos. Dice que está estudiando sus propiedades mágicas.$B$BEs una buena persona y mantiene buenas relaciones con nuestra tribu. Como los Nevada se han vuelto cada vez más agresivos, ha empezado a investigar la causa de su corrupción.$B$BYo tengo que seguir aquí, en mi puesto, pero he preparado una cesta de aperitivos para ella. Hazme el favor de llevársela y dile que esperamos su próxima visita.', '', '', '', '', '', '', '', '', '', '', 0),
(28525, 'esMX', 'Se busca héroe: ¡Cráter de Un\'Goro!', 'Preséntate ante Williden Marshal en el Alto de Marshal, en el Cráter de Un\'Goro.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Williden Marshal en el Alto de Marshal.$b$bLa Alianza reclama tu apoyo para Expediciones Marshal, los encargados de descubrir las bestias antiguas, las flores únicas y los cristales poderosos del Cráter de Un\'Goro. Para llegar al cráter, sal de Tanaris por el oeste y sigue el camino hasta el Alto de Marshal.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28526, 'esMX', '¡La orden del Jefe de Guerra: Cráter de Un\'Goro!', 'Preséntate ante Williden Marshal en el Alto de Marshal, en el Cráter de Un\'Goro.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Williden Marshal en el Alto de Marshal. Debes ayudar al personal de Expediciones Marshal mientras descubren los secretos del Cráter de Un\'Goro. Las bestias y cristales insólitos que pueblan el cráter podrían ser de utilidad para la Horda.$b$bPara llegar al Cráter de Un\'Goro, toma el camino desde el oeste de Tanaris hacia el cráter y prosigue hasta el Alto de Marshal.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28527, 'esMX', '¡La orden del Jefe de Guerra: Silithus!', 'Preséntate ante la clamavientos Cuerno Digno en Fuerte Cenarion, en Silithus.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el clamavientos Cuerno Digno en el Fuerte Cenarion. Vais a ayudar a nuestros aliados de Cenarion en su batalla para hacer retroceder al Martillo Crepuscular. ¡No podemos permitir que los esbirros de Cho\'Gall dominen Silithus!$B$BLlegaréis a Silithus por el camino noroeste que sale del Cráter de Un\'Goro.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28528, 'esMX', 'Se busca héroe: ¡Silithus!', 'Preséntate ante la clamavientos Cuerno Digno en Fuerte Cenarion, en Silithus.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante la clamavientos Cuerno Digno en Fuerte Cenarion.$b$bNuestros aliados del Círculo Cenarion necesitan tu ayuda para luchar contra el avance del Martillo Crepuscular. Para llegar a Silithus, toma el camino que sale del Cráter de Un\'Goro por el noroeste.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28529, 'esMX', 'Escrituras del vacío', 'Lleva las escrituras del heraldo oscuro a la forestal Glynda Nal\'Shea en Lor\'danel.', 'Los pergaminos son vagos y parecen ser la pieza de un rompecabezas mucho más grande, pero si no te equivocas, podrían revelar algunos de los pasos necesarios para convertirse en un cazademonios.$B$BLa mayoría de los elfos de la noche observan con recelo los juramentos oscuros y los rituales necesarios para convertirse en un cazademonios; de modo que esto es algo que están interesados en ocultar.$B$BLa forestal Glynda Nal\'Shea sabrá qué hacer con estos pergaminos.', '', '', '', '', '', '', '', '', '', '', 0),
(28530, 'esMX', 'Señales hirvientes', 'Reúne 7 unidades de fango verde sospechoso de las oleadas de manantial hirvientes o de las burbujas de manantial en ebullición.', 'Parecía que la caldera contenía material concentrado. Si los Nevada están diluyendo esa sustancia directamente en los manantiales, la contaminación se acumularía con el tiempo... Y diluirla sería cada vez menos efectivo.$b$bEl manantial que hay al noreste está plagado de elementales. Pensé que sería por el Cataclismo, pero su aparición podría ser una reacción a este problema.$b$b¿Podrías examinarlos en busca de corrupción? Caza unos cuantos y tráeme cualquier sustancia verde extraña que dejen atrás.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Donova Cubilnevado. Zona: Baños de Fuego de Escarcha, Cuna del Invierno.', 0),
(28531, 'esMX', 'Se busca héroe: ¡Desolace!', 'Preséntate ante la oficial Jankie en Tethris Aran en Desolace.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el oficial Jankie en el camino de Desolace, en Tethris Aran...$B$BLos valientes guerreros de Punta de Nijel están a la merced de demonios y de los ejércitos de la Horda y necesitan tu ayuda. Para llegar a Desolace, viaja hacia el sur por el camino que sale de La Vega Carbonizada, en Sierra Espolón.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28532, 'esMX', 'Orden del Jefe de Guerra: ¡Sierra Espolón!', 'Preséntate ante el guardia de sangre Aldo Llueverroca en Refugio de Brisa de Plata, en Vallefresno.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el guardia de sangre Aldo Llueverroca en Refugio de Brisa de Plata en Vallefresno. Las fuerzas de la Horda en Sierra Espolón necesitan tu ayuda para hacer retroceder a los invasores de la Alianza y proteger a nuestra gente. El guardia de sangre te llevará hasta la frontera de Sierra Espolón.$B$BPara llegar al Refugio de Brisa de Plata, viaja hasta el corazón de Vallefresno y únete a nuestras fuerzas junto al lago.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28533, 'esMX', 'La decisión del Alto Consejo', 'Habla con el rey Phaoris en Ramkahen, en Uldum.', 'El Alto Consejo está listo para decidir sobre la guerra con la tribu Neferset.', '', '', '', '', '', '', '', '', '', '', 0),
(28534, 'esMX', 'Descendientes de los Altonato', 'Habla con el espíritu quel\'dorei.', 'Poco después de mi muerte, la codicia de mi gente habría de conducirlos al exilio. En un continente distinto se convirtieron en los quel\'dorei, los elfos nobles. En Quel\'Thalas se maravillaron del poder de su Fuente del Sol y olvidaron su legado de deseo y avaricia.$b$bEstos descendientes distantes regresaron aquí, convocados por la mano del destino, condenados a repetir la historia. Escucha su historia, igual que la he escuchado yo...', '', '', '', '', '', '', '', '', '', '', 0),
(28535, 'esMX', 'Descendientes de los elfos nobles', 'Habla con el espíritu sin\'dorei.', 'Mucho después de mi muerte, mi gente habría de sufrir un error aún mayor. Los elfos nobles dependíamos de La Fuente del Sol y de su gloria. Nunca nos imaginamos un mundo sin ella, así que nunca nos preparamos para semejante destino.$b$bMás tarde, cuando La Fuente del Sol cayó ante el poder de los no-muertos, los supervivientes de mis descendientes quedaron perdidos y desamparados... y el camino que tomaron como respuesta los cambió para siempre.$b$bLos sin\'dorei, que ansiaban la redención, también acabarían regresando...', '', '', '', '', '', '', '', '', '', '', 0),
(28536, 'esMX', 'La maldición de Zin-Malor', 'Vuelve con Kelek Guardacielo en el Lago Kel\'theril, en Cuna del Invierno.', 'Has visto suficiente. Recuerda que el Cristal de Zin-Malor solo acarrea la ruina a todo lo que le rodea.$b$bAbandona este lugar si no quieres ser $guno:una; de nosotros.', '', '', '', '', '', '', '', '', '', '', 0),
(28537, 'esMX', 'En busca de sombras', 'Persigue y mata a la sombra del Hablaalmas para obtener alguna pista sobre su maestro.', '¿Dices que habló de un señor? ¿Alguien que posee Zin-Malor?$b$bEs una noticia muy grave. ¡Debes pasar a la acción, $c! Vi a la sombra volar hacia el sur. Toma el camino a las ruinas superiores y quizás puedas trepar por la cascada helada.$b$bNo bajes la guardia... Puede que te esté esperando.', '', '', '', '', '', '', 'Sombra del Hablaalmas', '', '', 'Vuelve con: Kelek Guardacielo. Zona: Lago Kel\'theril, Cuna del Invierno.', 0),
(28538, 'esMX', 'El grito del alma en pena', 'Usa el espejo de alma en pena para capturar 10 agentes del IV:7.', '¿Tú vas a ser $gnuestro salvador:nuestra salvadora;? Muy bien, me vincularé a ti. A través de este vínculo podré ver con tus ojos y comunicarme contigo en el campo de batalla.$b$bSegún los planes que nos has traído, los Pico Tormenta se han agenciado la ayuda del IV:7 en el Saliente de Sofera, al norte. El IV:7 está compuesto exclusivamente de humanos, humanos que podemos utilizar en nuestro beneficio.$b$bCoge mi espejo y viaja al norte. Entabla combate con los agentes del IV:7 hasta que estén cerca de la muerte. Cuando estén heridos, usa el espejo.', '', 'Agente del IV:7 capturado', '', '', '', '', '', 'Queda mucho trabajo por hacer. No te duermas en los laureles.', 'Melisara', 'Habla con: Melisara. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28539, 'esMX', 'Se busca héroe: ¡Sierra Espolón!', 'Preséntate ante la cazadora Jalin en la Torre del Polvo Estelar, en la frontera entre Vallefresno y Sierra Espolón.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante la cazadora Jalin en la Torre del Polvo Estelar en Vallefresno.$B$B¡Las fuerzas de la Horda se preparan para tomar Sierra Espolón y hay que detenerlas! Puedes llegar a la Torra del Polvo Estelar viajando hacia el sur del Bosque de Vallefresno, cerca de la frontera de Sierra Espolón.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28540, 'esMX', 'La magia E\'ko', 'Hazte con el corazón de Pelofrío.', 'Mau\'ari lleva años haciendo talih\'manes de los eh\'píritus salvajes de la zona. Mau\'ari les ARRANCA el E\'ko directamente a los animales y hace talih\'manes p\'a los críos y p\'a los aventureros.$b$bAl eh\'te hay una alta colina rodeada de osos Dentoeh\'quirla. En lo alto de la colina está Pelofrío, el oso más viejo del boh\'que.$b$bA Mau\'ari le hace falta el oso p\'a su magia. Tráme el gran corazón del oso.', '', '', '', '', '', '', '', '', '', 'Vuelve con la médica bruja Mau\'ari en la zona oeste de Cuna del Invierno.', 0),
(28542, 'esMX', '¡La orden del Jefe de Guerra: Frondavil!', 'Preséntate ante Tenell Correhoja en el Santuario Esmeralda, en Frondavil.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Tenell Correhoja en el Santuario Esmeralda, en Frondavil. ¡El Círculo Cenarion necesita tu ayuda para arrebatarle el control de Frondavil a los demonios y otras criaturas corruptas!$B$BPara llegar al Santuario Esmeralda, viaja al norte desde Vallefresno y sigue el camino hasta que llegues al santuario.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28543, 'esMX', 'Se busca héroe: ¡Frondavil!', 'Preséntate ante Tenell Correhoja en el Santuario Esmeralda, en Frondavil.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Tenell Correhoja en el Santuario Esmeralda.$B$B¡Sus órdenes son que ayudes a redimir Frondavil de las influencias demoníacas que gobiernan el bosque. Dirígete al norte desde Vallefresno y sigue el camino de Frondavil hasta que llegues al Santuario Esmeralda.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28544, 'esMX', 'Se busca héroe: ¡Cuna del Invierno!', 'Preséntate ante Donova Cubilnevado en los Baños de Fuego de Escarcha, en Cuna del Invierno.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Donova Cubilnevado en los Baños de Fuego de Escarcha.$B$BNecesita tu ayuda para afrontar la amenaza de los fúrbolgs Nevada. Para llegar a los Baños de Fuego de Escarcha en Cuna del Invierno, debes viajar hacia el este desde el norte de Frondavil y atravesar el Bastión Fauces de Madera.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28545, 'esMX', '¡La orden del Jefe de Guerra: Cuna del Invierno!', 'Preséntate ante Donova Cubilnevado en los Baños de Fuego de Escarcha, en Cuna del Invierno.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Donova Cubilnevado en los Baños de Fuego de Escarcha. Sus descubrimientos sobre los fúrbolgs Nevada podrían ser la llave para acabar con esta amenaza de una vez por todas.$B$BPara llegar a los Baños de Fuego de Escarcha en Cuna del Invierno, debes viajar hacia el este desde el norte de Frondavil y atravesar el Bastión Fauces de Madera.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28548, 'esMX', 'La orden del Jefe de Guerra: ¡Desolace!', 'Preséntate ante Furien en Tethris Aran, en Desolace.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Furien en Tethris Aran, en Desolace. Los valientes guerreros de la Horda de Desolace necesitan tu ayuda para rechazar a los ejércitos de la Alianza y a antiguos demonios$b$bPara llegar a Tethris Aran, viaja hacia el sur desde La Vega Carbonizada, en Sierra Espolón.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28549, 'esMX', '¡La orden del Jefe de Guerra: Los Baldíos del Sur!', 'Preséntate ante Nura Abrecaminos en La Carretera en Los Baldíos del Sur.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Nura Abrecaminos en La Carretera en Los Baldíos del Sur. Con las recientes victorias de la Alianza en Los Baldíos, nuestros enemigos amenazan con cortar nuestras líneas de suministros y poner a nuestros guerreros en un aprieto. ¡Debemos actuar!$B$BPara llegar a La Carretera, dirígete hacia el este desde la Sierra Espolón.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28550, 'esMX', 'Se busca héroe: ¡Los Baldíos del Sur!', 'Preséntate ante el comandante Walpole en el Paso del Espolón en la parte noroeste de Los Baldíos del Sur.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el comandante Walpole en el Paso del Espolón en Los Baldíos del Sur.$B$BNuestros valientes soldados han hecho grandes avances en Los Baldíos, ¡pero lo han pagado caro! Necesitamos tu ayuda para consolidar nuestros avances. Puedes llegar hasta Los Baldíos del Sur desde la Sierra Espolón si te diriges al sureste atravesando la Vega del Gran Bosque.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28551, 'esMX', 'Se busca héroe: ¡Los Baldíos del Sur!', 'Preséntate ante el maestro de embarcadero Lewis en el embarcadero en el exterior de Fuerte del Norte en Los Baldíos del Sur.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el maestro de embarcadero Lewis cerca del Fuerte del Norte.$B$BNuestros valientes soldados han hecho grandes avances en Los Baldíos, ¡pero lo han pagado caro! Necesitamos tu ayuda para consolidar nuestros avances. Puedes llegar hasta el embarcadero en el exterior del Fuerte del Norte tomando un barco desde Bahía del Botín a Trinquete y dirigiéndote hacia el sur por la costa.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28552, 'esMX', 'Se busca héroe: ¡Marjal Revolcafango!', 'Preséntate ante Calia Castilla en isla Theramore, en el Marjal Revolcafango.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Calia Castilla en Isla Theramore.$b$bDebes ayudar a Calia Castilla, del IV:7, a descubrir lo que amenaza a Theramore dentro de la ciudad o más allá de sus muros. Para llegar a Isla Theramore, toma el barco desde Menethil o atraviesa el marjal por Los Baldíos del Sur.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28553, 'esMX', 'Okrilla y las Tierras Devastadas', 'Preséntate ante Okrilla en el Bastión Machacamiedo, en las Tierras Devastadas.', 'Tengo un último encargo para ti, $n. Viene del Bastión Machacamiedo, al sur, en las Tierras Devastadas.$b$bLa matrona de guerra Okrilla libra una guerra contra las fuerzas de la Alianza provenientes del Castillo de Nethergarde, y necesita la ayuda de $gun robusto:una robusta; $c.$b$bVe al sur, hasta las Tierras Devastadas, y luego prosigue al oeste. Buena suerte, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(28554, 'esMX', '¡La orden del Jefe de Guerra: Marjal Revolcafango!', 'Preséntate ante Krog en el Poblado Murohelecho, en el Marjal Revolcafango.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Krog en el Poblado Murohelecho. El marjal está saturado de enemigos de todo tipo y las fuerzas de la Alianza en la zona son peligrosamente fuertes.$b$bPuedes viajar hasta el Marjal Revolcafango si sigues el camino que parte de la zona este de Los Baldíos del Sur, hacia el Poblado Murohelecho.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28556, 'esMX', 'Romper la mano', 'Coloca un arma nuclear de bolsillo goblin en el Saliente de Sofera, la Daga de Corrahn, La Punta y el Saliente de Gavin.', 'Debemos romper los dedos de los Pico Tormenta si queremos detener su incursión.$b$b<Cromush te entrega un pequeño paquete.>$b$bDentro de este paquete hay cuatro explosivos goblin de alta potencia. Debes infiltrarte en los cuatro dedos (el Saliente de Sofera, la Daga de Corrahn, La Punta y el Saliente de Gavin) y colocar un arma nuclear de bolsillo goblin en cada uno de ellos.$b$bCuando hayas acabado con eso y con lo que te pida Melisara, vuelve a verme.', '', 'Arma nuclear de bolsillo colocada en el Saliente de Sofera', 'Arma nuclear de bolsillo colocada en la Daga de Corrahn', 'Arma nuclear de bolsillo colocada en La Punta', 'Arma nuclear de bolsillo colocada en el Saliente de Gavin', '', '', '', '', 'Habla con: Gran señor de la guerra Cromush. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28557, 'esMX', 'Orden del Jefe de Guerra: ¡Uldum!', 'Habla con Adarrah en el Valle Cardizal en Tanaris occidental.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Adarrah en el Valle Cardizal en Tanaris.$B$BExisten textos antiguos que indican que Uldum alberga tesoros y riquezas incalculables. ¡Ve hasta allí y consíguelos en nombre de la Horda!$B$BPuedes llegar hasta la caravana de Adarrah viajando hacia la parte suroeste de Tanaris y buscando El Valle Cardizal.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28558, 'esMX', 'Se busca héroe: ¡Uldum!', 'Habla con Adarrah en el Valle Cardizal en Tanaris.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Adarrah en el Valle Cardizal en Tanaris.$B$B¡Sé uno de los primero en entrar en la gloriosa Uldum y en reclamar su tesoros por el honor de la Alianza!$B$BPuedes llegar a la caravana de Adarrah si te diriges al extremo oeste de Tanaris.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28559, 'esMX', 'Se busca héroe: ¡Isla Bruma de Sangre!', 'Preséntate ante Vorkhan el Pastor de elekks, en la Encrucijada de Kessel, en la Isla Bruma de Sangre.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Vorkhan el Pastor de elekks, en la Encrucijada de Kessel.$B$BLa gente de Bruma de Sangre necesita tu ayuda para lidiar con los traicioneros elfos de sangre y con las peligrosas criaturas que hay sueltas por la isla. Puedes llegar a la Encrucijada de Kessel, en la Isla Bruma de Sangre, cruzando el puente que hay al norte de la Isla Bruma Azur.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28560, 'esMX', '¡La orden del Jefe de Guerra: Tierras Fantasma!', 'Preséntate ante el arcanista Vandril en Tranquillien, en las Tierras Fantasma.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el arcanista Vandril en Tranquillien, en las Tierras Fantasma.$B$BSe necesita tu ayuda para hacer retroceder a los innumerables invasores de La Plaga y ayudar a los Renegados a luchar contra nuestro enemigo común.$B$BPara llegar a Tranquillien, sigue el camino del sur desde la plaza Brisa Pura hasta las Tierras Fantasma.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28561, 'esMX', 'Nahom debe resistir', 'Preséntate ante el regimiento en Nahom, en Uldum.', 'Tan pronto como avancemos hacia el oeste para atacar la Ciudad de Neferset, el enemigo nos atacará desde el este, donde seremos más débiles.$B$BNahom será la primera en caer, y si es así, Ramkahen le seguirá rápidamente.$B$BYa se encuentra allí un pequeño destacamento.$B$BQue te informen de la situación. Quiero que te asegures de que Nahom resistirá hasta que yo pueda enviar más tropas hasta allí.', '', '', '', '', '', '', '', '', '', '', 0),
(28562, 'esMX', 'Se busca héroe: ¡Páramos de Poniente!', 'Preséntate ante el teniente Horatio Laine en La Finca de Jansen en los Páramos de Poniente.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el teniente Horatio Laine, en la Finca de Jansen.$B$BLos Páramos de Poniente están invadidos de mendigos y vagabundos, lo que ha conducido a un aumento considerable de la actividad criminal. Es necesaria tu ayuda para restaurar el orden entre el populacho. Puedes llegar a la Finca de Jansen en los Páramos de Poniente si viajas al oeste desde el Bosque de Elwynn.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28563, 'esMX', 'Se busca héroe: ¡Montañas Crestagrana!', 'Preséntate ante el capitán de la Avanzada Parker en la Avanzada de la Torre en Montañas Crestagrana.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el capitán de la Avanzada Parker en la Avanzada de la Torre, en las Montañas Crestagrana.$b$bEl equipo del capitán Parker ha sufrido ataques de gnolls y orcos merodeadores. La gente de Villa del Lago peligra y es necesaria tu ayuda para protegerla. Viaja al este desde la frontera del Bosque de Elwynn y entra la zona de Tres Caminos, en Crestagrana, y ve a la Avanzada de la Torre.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28564, 'esMX', 'Se busca héroe: ¡Bosque del Ocaso!', 'Preséntate ante la comandante Althea Cerranegro en Villa Oscura en el Bosque del Ocaso.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante la comandante Althea Cerranegro en Villa Oscura.$b$bLos veladores de la comandante no dan abasto para defenderse de los lobos que merodean y las bandas de huargen salvajes. No aguantarán mucho sin tu ayuda. Puedes llegar hasta Villa Oscura en el Bosque del Ocaso si sigues el camino que hay al sur, en el margen entre el Bosque de Elwynn y las Montañas Crestagrana.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28565, 'esMX', 'Se busca héroe: ¡Los Humedales!', 'Preséntate ante el montaraz Rharen en Dun Algaz.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el montaraz Rharen, en Dun Algaz.$B$BTras la destrucción del Cataclismo, Los Humedales se vieron invadidos de bestias salvajes, asaltantes orcos y salvajes gnols. Para llegar a Los Humedales, debes viajar al norte de Loch Modan hacia el bastión de los enanos de Dun Algaz.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28566, 'esMX', 'Aniquilación', 'Mata al capitán Corazón Helado y a 12 soldados Pico Tormenta.', '<La imagen de Melisara se te aparece.>$b$bEl campamento de los Pico Tormenta está situado en lo alto de la Daga de Corrahn, al oeste del Saliente de Sofera. Debes entrar en el campamento y exterminar a todos los enanos que veas. Deben aprender lo que es el miedo, y no hay mejor lección que la aniquilación absoluta.$b$bNi un superviviente, $n. Hasta su capitán, especialmente su capitán, debe morir.$b$bEstaremos en contacto.', '', '', '', '', '', '', 'Melisara', 'La aniquilación conduce a la duda.', 'Melisara', 'Habla con: Melisara. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28567, 'esMX', 'Se busca héroe: ¡Loch Modan!', 'Preséntate ante el piloto Podomartillo en la Avanzada de Puerta Sur en Loch Modan.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el piloto Podomartillo en la Avanzada de la Puerta Sur.$B$BLa destrucción de la Presa de las Tres Cabezas y la reaparición de los kóbolds y los troggs tienen a los montaraces contra las cuerdas. ¡Necesitamos refuerzos desesperadamente! Viaja hacia el este, más allá del Paso de la Puerta Sur desde la zona oriental de Dun Morogh para llegar a la Avanzada de la Puerta Sur.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28568, 'esMX', '¡La orden del Jefe de Guerra: Bosque de Argénteos!', 'Preséntate ante el Gran Ejecutor Mortuus en el Alto Mando Renegado en el Bosque de Argénteos.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presente ante el Gran Ejecutor Mortuus en el Alto Mando Renegado en el Bosque de Argénteos.$B$B¡Ahora, más que nunca, necesitamos tu ayuda para expulsar a la plaga enemiga de esta región y conquistar el puerto de Gilneas!$B$BPara llegar al Alto Mando Renegado, debes viajar al sur, a través de los Claros de Tirisfal y entrar en el Bosque de Argénteos. Desde allí, sigue el camino hacia el sur hasta llegar al Alto Mando Renegado.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28569, 'esMX', 'La bala de Chapaleos', 'Habla con Sharon Pillabomba en el extremo más suroriental de Las Estepas Ardientes para llevar la bala de Chapaleos hasta el Pantano de las Penas. Después habla con el barón mercante Brochargento en Chapaleos.', 'He oído historias sobre un camino que lleva al Pantano de las Penas. ¡Relatos misteriosos sobre un camino sinuoso que atraviesa completamente Crestagrana y te lleva directamente a Chapaleos!$b$bSi no tienes nada más que hacer, supongo que tendrás que irte. Y todos nos pondremos tristes. Cuando te vayas, habla con Sharon Pillabomba en el extremo más suroriental de las estepas. Ella te llevará.$b$b<Oralius inclina la cabeza, como si estuviese escuchando algo.>$b$b¿Winky? ¡WINKY! ¡NO!', '', '', '', '', '', '', '', '', '', 'Informa a: Barón mercante Brochargento. Zona: Chapaleos, Pantano de las Penas.', 0),
(28570, 'esMX', 'La bala de Chapaleos', 'Habla con Sharon Pillabomba en el extremo más suroriental de Las Estepas Ardientes para llevar la bala de Chapaleos hasta el Pantano de las Penas. Después habla con el barón mercante Brochargento en Chapaleos.', 'Eres $gtodo un:toda una; $r, ¿verdad? Mírate... ya estás enorme. ¡Y nos acabamos de conocer!$b$bSé perfectamente lo que pasará... en breve te quedarás sin nada que hacer en Peñasco Llamarada. Me prometerás que volverás. Pero nunca lo harás.$b$bKibler ya ha vivido esto.$b$bCuando te vayas, habla con Sharon Pillabomba en el extremo sureste de Las Estepas. Te llevará en la bala.$b$b¿Qué? Oh, no es más que un cohete. Perfectamente seguro.', '', '', '', '', '', '', '', '', '', 'Informa a: Barón mercante Brochargento. Zona: Chapaleos, Pantano de las Penas.', 0),
(28571, 'esMX', '¡La orden del Jefe de Guerra: Laderas de Trabalomas!', 'Preséntate ante la suma ejecutora Darthalia en la Puerta Austral, en las Laderas de Trabalomas.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante la suma ejecutora Darthalia en la Puerta Austral, en las Laderas de Trabalomas. ¡La maquinaria de guerra Renegada marcha hacia el frente, para conquistar Lordaeron en nombre de la Horda!$b$bPara llegar a la Puerta Austral debes seguir el camino hacia el sur, a través del Bosque de Argénteos, y girar al este para entrar en las Laderas de Trabalomas.$b$b¡Adelante, $ghermano:hermana;! ¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28572, 'esMX', '¡La orden del Jefe de Guerra: Tierras Altas de Arathi!', 'Preséntate ante la forestal oscura Alina en Caída de Galen, en las Tierras Altas de Arathi.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante la forestal oscura Alina en Caída de Galen. Las fuerzas de la Dama Oscura necesitan tu ayuda para extender el dominio de la Horda y hacer retroceder a los intrusos de la Alianza.$B$BPara llegar a las Tierras Altas de Arathi, viaja hacia el este desde las Laderas de Trabalomas y sigue el camino cruzando la Muralla de Thoradin $B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28573, 'esMX', 'Se busca héroe: ¡Tierras Altas de Arathi!', 'Preséntate ante la capitana Nials en Refugio de la Zaga, en las Tierras Altas de Arathi.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante la capitana Nials en Refugio de la Zaga.$b$b¡El honor ancestral de Stromgarde debe ser redimido! Los ogros y los criminales llevan mucho tiempo mancillando sus calles. Viaja hacia el norte desde Los Humedales y cruza el Puente Thandol para llegar a Arathi. Sigue el camino hasta Refugio de la Zaga y preséntate ante la capitana.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28574, 'esMX', '¡La orden del Jefe de Guerra: Tierras del Interior!', 'Preséntate ante el anciano Colmillopartido en el Poblado Sañardiente en las Tierras del Interior.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el anciano Colmillopartido en el Poblado Sañardiente.$B$BAhora que los enanos Martillo Salvaje se han unido oficialmente a la alianza, se han convertido en nuestros enemigos. ¡Deben ser derrotados! $b$bPara llegar al Poblado Sañardiente, cruza hasta las Tierras del Interior desde el paso de la montaña en la zona oriental de las Laderas de Trabalomas y llega hasta la costa este.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28575, 'esMX', '¡La orden del Jefe de Guerra: Tierras de la Peste del Oeste!', 'Preséntate ante Koltira Tejemuerte en Andorhal, en las Tierras de la Peste del Oeste.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Koltira Tejemuerte en Andorhal.$B$BLas fuerzas de la Alianza se están adentrando en la ciudad en ruinas de Andorhal con la intención de reclamarlas para sí. ¡Debemos hacerles frente antes de que aseguren su posición aquí!$b$bCruza el Baluarte, en el extremo este de Claros de Tirisfal, sigue el camino del sudeste hacia Andorhal y reúnete allí con nuestras fuerzas.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28576, 'esMX', 'Se busca héroe: ¡Tierras de la Peste del Oeste!', 'Preséntate ante Thassarian en Andorhal, en las Tierras de la Peste del Oeste.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Thassarian en Andorhal.$B$BA la vista de nuestras anteriores victorias en Andorhal, los Renegados han decidido lanzar un contraataque. Se necesita tu ayuda para rechazar a la Plaga y a la Horda y reclamar la perdida Andorhal.$B$BPara llegar a Andorhal, viaja hacia el norte, a través de las Laderas de Trabalomas y sigue el camino más allá del Campamento del Orvallo.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28577, 'esMX', '¡La orden del Jefe de Guerra: Tierras de la Peste del Este!', 'Preséntate ante Fiona en la orilla este del río Thondroril en las Tierras de la Peste del Este.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Fiona en la orilla este del río Thondroril.$B$BLa Cruzada Argenta ha reforzado su presencia en las Tierras de la Peste y necesita tu ayuda para consolidar sus victorias.$B$BCruza el río Thondroril en la frontera este de las Tierras de la Peste del Oeste y busca a Fiona en la orilla opuesta.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28578, 'esMX', 'Se busca héroe: ¡Tierras de la Peste del Este!', 'Preséntate ante Fiona en la orilla este del río Thondroril en las Tierras de la Peste del Este.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Fiona en la orilla este del río Thondroril.$B$BLa Cruzada Argenta necesita tu ayuda para recuperar las Tierras de la Peste del Este de las manos de la Plaga.$B$BPara llegar a las Tierras de la Peste del Este, cruza el río Thondroril desde las Tierras de la Peste del Oeste y busca a Fiona en la orilla este.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28579, 'esMX', 'Se busca héroe: ¡Las Tierras Inhóspitas!', 'Preséntate ante Gek Bocatraca en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Gek Bocatraca en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.$b$bSe requiere tu ayuda para examinar el daño causado por Alamuerte y la disposición de las tropas de la Horda en las Tierras Inhóspitas.$b$bGek ha accedido a ofrecer transporte por cohete hasta las Tierras Inhóspitas a cambio de ayuda. Ve a verle a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28580, 'esMX', '¡La orden del Jefe de Guerra: las Tierras Inhóspitas!', 'Preséntate ante Gek Bocatraca en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Gek Bocatraca en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.$b$bLa Alianza está desesperada por establecerse en las Tierras Inhóspitas. Tu deber será mantenerla a raya e indagar sobre la destrucción que ha causado Alamuerte.$b$bGek ha accedido a ofrecer transporte por cohete hasta las Tierras Inhóspitas. Reúnete con él en la Capilla de la Esperanza de la Luz.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28581, 'esMX', '¡La orden del Jefe de Guerra: La Garganta de Fuego!', 'Preséntate ante Jack Patarroca en el Avance del Torio, en La Garganta de Fuego.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Jack Patarroca en el Avance del Torio.$B$BLa Mano Destrozada informa de que parece que los enanos Hierro Negro de La Garganta de Fuego se están preparando para algo. Tu deber es descubrir todo lo que puedas sobres sus planes y detenerlos.$B$BPuedes llegar hasta La Garganta de Fuego siguiendo el camino hacia el oeste desde las Tierras Inhóspitas.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28582, 'esMX', 'Se busca héroe: ¡La Garganta de Fuego!', 'Preséntate ante Jack Patarroca en el Avance del Torio, en La Garganta de Fuego.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Jack Patarroca en el Avance del Torio.$B$BIV:7 informa de que parece que los enanos Hierro Negro de La Garganta de Fuego se preparan para atacar. Tu deber es descubrir todo lo que puedas sobre sus planes y detenerlos.$B$BPuedes llegar hasta La Garganta de Fuego siguiendo el camino hacia el oeste desde las Tierras Inhóspitas.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28583, 'esMX', 'La Krazzería', 'Llévale la solicitud de patente al capitán Krazz a La Krazzería, en las Tierras Altas Crepusculares.', 'El diseño de esta nueva trituradora es lo más, $n. ¡Lo más! El próximo paso es proteger mi propiedad intelectual. Hay que procesar patentes, elegir comerciantes, ceses y abstenciones. Oh, ¡y sobornos!$B$BToma, llévale esta solicitud de patente al capitán Krazz, a La Krazzería. Sobrevivió a la destrucción de su zepelín, así que estará deseando adentrarse en nuevas oportunidades financieras.$B$BLa Krazzería está al norte de aquí, muy segura en la cima de una montaña. Adelante, $Gchico:chica;. ¡Andando!', '', '', '', '', '', '', '', '', '', 'Lleva la solicitud de patente a: Capitán Krazz. Zona: La Krazzería, Tierras Altas Crepusculares.', 0),
(28584, 'esMX', 'Construcción de calidad', 'Usa la cinta explosiva para sellar 10 válvulas defectuosas.', 'Mira esto, $gjefe:jefa; si no fuera por ese idiota tartamudo que tengo en frente, La Krazzería estaría en pie sin ningún problema.$B$BDesgraciadamente para todos los involucrados, ¡Rothman el "Finolis" decidió montar esto en la cima de una montaña! En serio, ¿a quién se le ocurre?$B$BAsí que empezó a haber fugas por todas partes por las válvulas defectuosas. ¿Crees que podrías coger esta cinta explosiva y hacerme el favor de sellarlas?', '', 'Válvulas defectuosas selladas', '', '', '', '', '', '', '', 'Vuelve con: Brett el Bombardero. Zona: La Krazzería, Tierras Altas Crepusculares.', 0),
(28586, 'esMX', 'Rescate en poni flotador', 'Usa los ponis flotadores para rescatar a 10 obreros de La Krazzería que se han caído al agua.', '¡El idiota que tengo enfrente está haciendo que maten a toda nuestra gente!$B$BBrett "el Plomazo" montó La Krazzería en el sitio equivocado y ahora es altamente inestable. Las explosiones por la inestabilidad están tirando a nuestros obreros de la plataforma al agua.$B$BNo te importa volar hasta ahí abajo y rescatarlos con algunos ponis flotadores, ¿verdad, $n?', '', 'Obreros de La Krazzería rescatados', '', '', '', '', '', '', '', 'Vuelve con: Granadillo Rothman. Zona: La Krazzería, Tierras Altas Crepusculares.', 0),
(28587, 'esMX', 'La ayuda de los Lobo Gélido', 'Habla con Voggah Agarre Letal en las Montañas de Alterac, en las Laderas de Trabalomas.', 'Estudiaré los planes de batalla Pico Tormenta y me prepararé para un asalto. Quiero que vayas al Valle de Alterac y solicites la ayuda del clan Lobo Gélido: es el clan de nuestro antiguo Jefe de Guerra, Thrall. ¡Nos ayudarán a luchar contra los enanos Pico Tormenta! ¡Juntos aplastaremos a los invasores y los expulsaremos de Lordaeron para siempre!$b$bAhora ve, $n. El Valle de Alterac está al noreste del Molino Tarren. Busca a Vogga Agarre Letal y cuéntale que la Horda requiere la ayuda de los Lobo Gélido.$b$b¡LOK\'TAR!', '', '', '', '', '', '', '', '', '', '', 0),
(28588, 'esMX', 'Infestación Martillo Salvaje', 'Mata a 10 asaltantes Martillo Salvaje.', '¡Mientras esos dos idiotas discuten sobre quién metió la pata a lo grande aquí, está teniendo lugar una invasión a gran escala de La Krazzería!$B$BEsos zopencos Martillo Salvaje están por todas partes. Ve ahí y limpia el lugar de esa plaga de apestosos come ajos.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Capitán Krazz. Zona: La Krazzería, Tierras Altas Crepusculares.', 0),
(28589, 'esMX', 'Todo menos el fregadero', 'Mata a 15 garfatormentas Martillo Salvaje.', 'Tienes que hacer algo con los garfatormentas Martillo Salvaje. ¡Están acabando con nosotros!$B$BEl problema es que no nos queda munición, así que tuvimos que improvisar. Cargamos mis cañones de Krazz con todo tipo de cosas: ponis flotadores, latas de Kaja\'Cola, envases de comida, pilas de combustible, llantas... ya te lo imaginas.$B$BBásicamente: todo menos el fregadero.$B$B¿Estás de humor para hacer prácticas de tiro?', '', 'Súbete a un cañón de Krazz', '', '', '', '', '', '', '', 'Vuelve con: Capitán Krazz. Zona: La Krazzería, Tierras Altas Crepusculares.', 0),
(28590, 'esMX', 'Represalias', 'Habla con Parche a bordo del Trituracielos que sobrevuela Bancalto.', 'Resulta que conozco a cierta escoria de la Alianza que está a punto de recibir algo. Y tienen algo que nos pertenece. He autorizado una ofensiva total contra Bancalto.$B$BSúbete al Trituracielos y únete al ataque. Parche te dará más detalles cuando llegues.', '', '', '', '', '', '', '', '', '', '', 0),
(28591, 'esMX', 'En la muralla', 'Mata a 80 tiradores de Bancalto, a 12 cañoneros de Bancalto y destruye 4 cañones de Bancalto con una torreta Trituracielos.', 'Tienes pinta de ser $gun chico al:una chica a la; que le gusta la acción. Súbete a una de esas torretas y arrasa sus defensas de la muralla.$B$BDate prisa, ¿quieres? Preferiría que lo hicieras antes de que salgamos todos volando en una gran bola de fuego.', '', '', '', '', '', '', '', '', '', 'Habla con: Parche. Zona: A bordo del Trituracielos que sobrevuela Bancalto, Tierras Altas Crepusculares.', 0),
(28592, 'esMX', 'Regalos de despedida', 'Coloca bombas en el barco, en la entrada de la fortaleza y en una de las torres norte.', 'Estoy seguro de que Parche tendrá algún plan genial en mente, pero esto no sería un ataque si no dejásemos algunos regalitos explosivos.$B$BBaja ahí y coloca algunos de estos explosivos en el barco, en la entrada de la fortaleza y en una de esas torres norte. Eso debería bastar para hacer que se tambaleen.$B$BNosotros también vamos bajo tierra. Reúnete con nosotros en la torre este cuando hayas terminado.', '', 'Bomba del barco de Bancalto colocada', 'Bomba de la fortaleza de Bancalto colocada', 'Bomba de la torre de Bancalto colocada', '', '', '', '', '', 'Reúnete con: Tictac. Zona: Cerca de la torre este de Bancalto, Tierras Altas Crepusculares.', 0),
(28593, 'esMX', 'De la máxima importancia', 'Recupera el churumbele de inducción.', 'Cuando cayó el zepelín de Garrosh, también lo hizo el churumbele de inducción que nos conseguiste en Azshara. La Alianza lo tiene en algún lugar de esa fortaleza, y Krazz quiere recuperarlo.$B$BYo apostaría por el sótano del castillo, así que empieza por ahí. Cuando esté entre tus manos, tráemelo, estaré junto a la torre este.', '', '', '', '', '', '', '', '', '', 'Reúnete con: Parche. Zona: Torre este de Bancalto, Tierras Altas Crepusculares.', 0),
(28594, 'esMX', 'Bancalto, mar de lágrimas', 'Mata a 10 defensores de Bancalto.', 'Ve ahí y aniquila a esa chusma de la Alianza. Cualquiera valdrá. Solo quiero que estén dispersados mientras vas a por el verdadero objetivo.$B$BReúnete con nosotros en la torre este cuando hayas terminado.', '', 'Defensores de Bancalto asesinados', '', '', '', '', '', '', '', 'Reúnete con: Parche. Zona: Torre este de Bancalto, Tierras Altas Crepusculares.', 0),
(28595, 'esMX', '¡La Krazzería!', 'Habla con Tritón para que te lleve a La Krazzería, luego dale el churumbele de inducción al capitán Krazz.', 'Eso es todo. Ya hemos empaquetado. Podemos irnos.$B$BTritón tiene unos girocópteros amarrados en lo alto de la torre. Ve a reunirte con ella para que te lleve rápidamente a La Krazzería. Nosotros limpiaremos esto.', '', '', '', '', '', '', '', '', '', '', 0),
(28596, 'esMX', 'La bienvenida de Bancalto', 'Mata a 10 agresores de la Horda en Bancalto.', '$gBienvenido:Bienvenida; a las Tierras Altas, soldado. Llegas justo a tiempo.$B$BLas tropas de la Horda han lanzado un ataque aéreo. Ponte en marcha y haz algo al respecto. ¡Elimínalos!', '', 'Agresores de la Horda asesinados', '', '', '', '', '', '', '', 'Vuelve con: Teniente Fawkes. Zona: Bancalto, Tierras Altas Crepusculares.', 0),
(28597, 'esMX', 'Ardiendo por los dos lados', 'Recoge 10 sacos llenos de pólvora de cañón.', '¡Ah! Vamos a entrar de lleno en acción, $n. Parece que Bancalto tiene lo que se podría llamar un problema de zepelines: esa nave está causando auténticos destrozos en los muros.$B$BEscucha, se me ha ocurrido una idea tan estúpida que es genial. Solo necesito un poco de pólvora de cañón.$B$B¡Recoge toda la que puedas encontrar en los alrededores de Bancalto y reúnete conmigo en la zona de comercio!', '', '', '', '', '', '', '', '', '', 'Reúnete con: Fargo Cierrasílex. Zona: Oeste de Bancalto, Tierras Altas Crepusculares.', 0),
(28598, 'esMX', 'Apuntando alto', 'Espera a que Fargo Cierrasílex te meta en el zepelín y pon los explosivos en la cámara de abajo.', 'Mira esto, $n. ¡He encontrado el arma más grande de Bancalto! Vamos a probar una técnica que heredé de mi padre, y este de su padre, y este del suyo, poco antes de que volara por los aires.$B$BSe llama "disparo de $c".$B$BTomas a $gun:una; $r $c, $glo:la; metes en un cañón gigante y luego... vamos, relájate. Normalmente funciona.$B$BToma esos explosivos y espera aquí, junto a mí. En cuanto se acerque ese zepelín, te dispararé a la cubierta. Pon los explosivos en su interior y... no sé, ya se te ocurrirá algo por el camino.', '', 'Espera a que te lancen del cañón de Cierrasílex', 'Destruye el Trituracielos', '', '', '', '', '', '', 'Vuelve con: Fargo Cierrasílex. Zona: Bancalto, Tierras Altas Crepusculares.', 0),
(28599, 'esMX', 'Kurdran está esperando', 'Habla con Kurdran Martillo Salvaje en la fortaleza de Bancalto, en las Tierras Altas Crepusculares.', 'Parece que el ataque ha cesado, $n. Y es una pena, porque nunca llegamos a usar el cohete-$c.$B$BEn fin, Kurdran Martillo Salvaje está en lo alto de la fortaleza y estoy seguro de que está esperando para darte el recibimiento de $Gun héroe:una heroína;. ¡Te lo has ganado! ¡Ve a hablar con él!$B$BYo me adelantaré y exploraré la playa.', '', '', '', '', '', '', '', '', '', '', 0),
(28600, 'esMX', 'Cuestión de lealtad', 'Habla con Drek\'Thar.', 'Yo no tengo autoridad sobre estas cuestiones. Debes hablar con nuestro líder, Drek\'Thar. Ya le he notificado tu llegada al Bastión Lobo Gélido. Drek\'Thar saldrá para hablar contigo personalmente.', 'Aprende las cuestiones de lealtad.', '', '', '', '', 'Aprende las cuestiones de lealtad.', '', '', '', 'Habla con: Gran señor de la guerra Cromush. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28602, 'esMX', 'Prepárate', 'Reúne 6 trozos de cuerda.', 'Todo aventurero que se precie sabe que no debe meterse jamás en una cueva, mazmorra, cripta o tumba sin un buen suministro de cuerda... ¿Verdad?$b$bPues bien, la mía estaba en ese vagón lleno de explosivos que acabas de detonar.$b$b¿Qué te parece si te das una vuelta por aquí y miras si puedes encontrar un poco?', '', '', '', '', '', '', '', '', '', 'Habla con: Harrison Jones. Zona: Cámara de las Estrellas.', 0),
(28603, 'esMX', 'Infiltración', 'Mata al instructor Rufus, al sargento de maniobras Magnus y al capitán Barbasucia.', 'Para la siguiente misión quiero que viajes al oeste, a La Punta, y te infiltres en los campos de entrenamiento Pico Tormenta. Aunque allí hay cientos de practicantes Pico Tormenta, una de mis almas en pena te disfrazará como uno de los humanos capturados, para que así puedas pasearte tranquilamente entre el enemigo.$b$bEntra en La Punta y busca a los instructores Pico Tormenta. Cuando los encuentres, ¡provócalos para que te ataquen! Cuando te ataquen, mátalos. Con los instructores muertos, ¡no podrán entrenar más soldados!', '', '', '', '', '', '', 'Melisara', 'La confusión conduce al caos.', 'Melisara', 'Habla con: Melisara. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28604, 'esMX', 'Engaños y trucos', 'Utiliza la barrica de agua para envenenar a 30 practicantes Pico Tormenta.', 'Mientras esté a tu lado, el enemigo pensará que eres de los suyos. Sin embargo, tu nueva humanidad no te permitirá arriesgarte. ¡Si llamas la atención, los enanos sospecharán y te atacarán!$b$bDicho eso, tengo un plan. Coge esta barrica de agua envenenada y úsala para saciar la sed de los practicantes Pico Tormenta. Cuando la beban contraerán una enfermedad letal y acabarán por sucumbir al veneno.', '', 'Practicante Pico Tormenta envenenado', '', '', '', '', '', '', '', 'Habla con: Lilith. Zona: Laderas de Trabalomas.', 0),
(28605, 'esMX', 'Dominación', 'Mata 10 ingenieros Pico Tormenta.', '<Los pensamientos de Melisara se entrecruzan con los tuyos.>$b$bLa última misión será un asalto contra los técnicos de asedio del Saliente de Gavin, situado al oeste de La Punta. Adéntrate en el último dedo y destruye a los enanos y gnomos ingenieros que construyen y refuerzan las máquinas de guerra de los Pico Tormenta. No te olvides de colocar las armas nucleares de bolsillo de Cromush.', '', '', '', '', '', '', 'Melisara', '', '', 'Vuelve con: Melisara. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28608, 'esMX', 'El Sepulcro Sombrío', 'Obtén el líquido de embalsamar espeso y el cordel para coser cadáveres en el Sepulcro Sombrío, en Camposanto.', 'Me alegro de ver que estás en pie y en marcha, $n. Te has conservado bien, ¡especialmente para alguien que lleva tanto tiempo $gmuerto:muerta;!$b$bNo todo el mundo tiene la misma suerte. Si no te importa, me gustaría que me trajeras el líquido de embalsamar y algo de cordel para coser estos cadáveres. Encontrarás las dos cosas en el Sepulcro Sombrío, el edificio que tengo justo detrás.$b$bDarnell te guiará, él conoce el camino.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Enterrador Mordo. Zona: Las Tumbas del Camposanto, Camposanto.', 0),
(28609, 'esMX', 'La hora del martillo', 'Habla con Deez Hurtarroca.', 'Los tres llevamos semanas discutiendo sobre qué armas son superiores.$b$bNo le tolero a nadie que me diga que mis mazas quedan en segundo lugar. Las hachas de Kilram y las espadas de Seril jamás estarán a la altura de la fuerza bruta de mis creaciones.$b$bYa me he cansado de discutir. Es hora de enseñarles que tengo razón mediante una demostración. Si quieres, cielo, ¡sal y dile a Deez Hurtarroca que necesito la roca más grande que encuentre!', '', '', '', '', '', '', '', '', '', '', 0),
(28610, 'esMX', 'Enrocado', 'Obtén 6 trozos de escombros primordiales de los estruendores Trocescarcha.', 'Si quieres una roca, ¡puedes utilizar mi propia y patentada roca de bolsillo! Normalmente te vendería una sin más, pero me he quedado sin materias primas.$b$bHan aparecido unos elementales de tierra en el pico que hay justo al sur de la ciudad. Son una buena fuente de escombros. Si me traes una buena cantidad, ¡te pagaré por los suministros y te daré una roca de bolsillo totalmente gratis!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Deez Hurtarroca. Zona: Vista Eterna, Cuna del Invierno.', 0),
(28611, 'esMX', 'El ritual de los Rapiñadores', 'Detén el ritual de Neferset en la Caverna Negrasombra.', 'Ah, ya puedo ver con más claridad, $n.$B$BTenemos motivos suficientes para ser cautelosos con los malvados Neferset. Ya percibo que están detrás de las fuerzas que contaminan el río.$B$BVuelve a sumergirte bajo el agua y encuentra la Caverna Negrasombra. Encontrarás a los Neferset realizando un terrible ritual de corrupción.$B$BDetenlos para que el río se purifique de nuevo.', '', 'Ritual de Neferset detenido', '', '', '', '', '', '', '', 'Vuelve con: Sumo sacerdote Amet. Zona: Presa Vir\'Naal, Uldum.', 0),
(28612, 'esMX', 'Harrison Jones y el Templo de Uldum', 'Recupera el Arca de la promesa.', 'Después de lo que hemos pasado, ¡parece que por fin las cosas empiezan a salir bien!$b$bEstamos a tan solo unos pasos del arca... He investigado los códigos para desvelarla... Schnottz cree que estamos muertos...$b$b¿Sabes?, ¡es posible que lo consigamos, después de todo!', '', 'Arca de la promesa descubierta', '', '', '', '', '', '', '', 'Habla con: Brann Barbabronce. Zona: Templo de Uldum.', 0),
(28613, 'esMX', '¡Nos vemos al otro lado!', 'Habla con Harrison Jones en lo alto del Ascenso del Hacedor, en Uldum.', 'Bien, $n. Hemos conseguido un poco de espacio de maniobra, pero no hay tiempo que perder.$b$b¡Sígueme!', '', '', '', '', '', '', '', '', '', '', 0),
(28614, 'esMX', 'Rabioso', 'Mata a Grolnar el Rabioso.', 'La ausencia del gran jefe Nevada no ha apaciguado la ira de los Nevada. En su ausencia, su mayor guerrero ha ascendido a una posición de terrible poder.$b$bGrolnar el Rabioso se esconde en una cueva en lo alto del Poblado Nevada, atiborrado con suficiente aguardiente corrupta como para matar a diez fúrbolgs menores.$b$b¡Se ha convertido en una bestia hinchada y horrible! Nuestros guerreros han sido incapaces de enfrentarse a él. ¿Tienes la fuerza necesaria para derrotarlo, $c?', '', '', '', '', '', '', 'Grolnar', '', '', 'Vuelve con Burndl cerca del Poblado Nevada, en la Cuna del Invierno.', 0),
(28615, 'esMX', 'Volver la tierra en su contra', 'Utiliza el tótem sobrecargado de Tanrir para sobrecargar 4 tótems de tierra Nevada.', 'A pesar de su corrupción y de su locura, los Nevada aún se aferran a sus poderes chamánicos. Me inquieta verlos usar los poderes de los elementos para dañar a mi tribu y a otros inocentes.$B$B¡Volveremos sus tótems en su contra! Lleva mi propio tótem contigo al poblado Nevada. Usa su poder, desde lejos, con los tótems de Nevada ¡y la furia de la tierra se desatará contra todos los que anden cerca!$B$BSobra decir... ¡que te mantengas a distancia!', '', 'Tótem de tierra Nevada sobrecargado', '', '', '', '', '', '', '', 'Vuelve con: Tanrir. Zona: Poblado Nevada, Cuna del Invierno.', 0),
(28616, 'esMX', 'Apocalipsis Pico Tormenta', 'Presencia el apocalipsis Pico Tormenta.', 'Antes de proseguir, guardemos un minuto de silencio por nuestro hermano caído, Orkus, ya que sin él el asalto Pico Tormenta nos habría aniquilado. ¡Esto va por ti, hermano!$b$b<Cromush se arrodilla.>$b$b¡$n, no te creas que me he olvidado de tu papel en todo esto! A ti te corresponde el honor de detonar las armas nucleares de bolsillo goblin.$b$b¿Estás $glisto:lista;? ¡POR LA HORDA!', 'Presencia el apocalipsis Pico Tormenta.', '', '', '', '', 'Presencia el apocalipsis Pico Tormenta.', '', '', '', 'Habla con: Gran señor de la guerra Cromush. Zona: Molino Tarren, Laderas de Trabalomas.', 0),
(28617, 'esMX', 'Flores al poder', 'Sobrevive a una gigantesca oleada de zombis.', 'Sabes cómo utilizar las escupidoras, pero ¿acaso sabes que si utilizas un girasol puedes hacer que las cosas crezcan más rápido? Plantaremos unos girasoles y después unas cuantas escupidoras para hacer retroceder a las monstruosidades del celador Aguaserena.$B$B¡Vamos!', '', 'Gigantesca oleada de zombis superada', '', '', '', '', '', '', '', 'Habla con: Brazie el Botánico. Zona: Granja de Brazie, Laderas de Trabalomas.', 0),
(28618, 'esMX', 'Entrega de rocas', 'Entrega la roca de bolsillo a Lilith la Ágil en Vista Eterna.', '¡Aquí tienes, como te prometí! Una roca de bolsillo.$b$bEs para Lilith, ¿verdad? ¡Es mi única cliente!', '', '', '', '', '', '', '', '', '', '', 0),
(28619, 'esMX', '¡La orden del Jefe de Guerra: Tierras Altas de Arathi!', 'Preséntate ante la forestal oscura Alina en Caída de Galen, en las Tierras Altas de Arathi.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante la forestal oscura Alina en Caída de Galen. Las fuerzas de la Dama Oscura necesitan tu ayuda para extender el dominio de la Horda y hacer retroceder a los intrusos de la Alianza.$B$BPara llegar a las Tierras Altas de Arathi, viaja hacia el este desde las Laderas de Trabalomas y sigue el camino cruzando la Muralla de Thoradin $B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28620, 'esMX', 'Torre Oriental', 'Habla con Nils Beerot en la Torre Oriental, en las Laderas de Trabalomas.', 'Nuestra avanzada del sureste está sufriendo algunos problemas. Los únicos detalles que tengo... Bueno, mejor te leo la última carta:$b$b"Los orcos se han vuelto arrogantes. Envía ayuda o los azotaré con juncos".$b$bEso es todo. Nos lo ha enviado nuestro psilósofo jefe, Nils Beerot. Ya, yo tampoco tengo ni idea de lo que significa eso. ¿Me harás el favor de dirigirte a la Torre Oriental y averiguar qué es lo que le hace falta? ¡No aguanto más cartas crípticas!$b$bVe al sur y sigue el camino al este.', '', '', '', '', '', '', '', '', '', '', 0),
(28621, 'esMX', '¡Pon esta monada en la cuna!', 'Habla con Harrison Jones en el Templo de Uldum.', '¡Ay!$b$b¡Junior y tú se lo han tomado con calma para venir, eh!$b$bApostaría a que han estado $gbebiendo cerveza:paseando de la mano; por los monumentos.$b$b¡No se rompán el brazo dándose palmaditas en la espalda, el verdadero trabajo acaba de empezar!$b$bEste artefacto es mucho más de lo que parece, pero para poder desvelar sus secretos tenemos que llevarlo a la Cuna de los Ancestros.$b$b¿Y cómo crees que vamos a hacer eso?$b$bTal vez junior tenga alguna idea genial, ¿no?', '', '', '', '', '', '', '', '', '', '', 0),
(28622, 'esMX', 'Por aire, tres', 'Usa las bengalas de señalización en el Templo de Uldum.', 'Había pensado en llevar el arca a mi laboratorio para estudiarla, pero parece que aquí Brann tiene otro plan.$b$bCree que sabe cómo detener los planes de Alamuerte aquí en Uldum.$b$bMi amigo Jock está ahí al lado con el transporte, esperando nuestra señal.$b$bCoge estas bengalas y colócalas en el perímetro para hacerle saber que ya estamos listos.', '', 'Bengala de señalización norte colocada', 'Bengala de señalización oeste colocada', 'Bengala de señalización sur colocada', '', '', '', '', '', 'Vuelve con: Brann Barbabronce. Zona: Cuna de los Ancestros.', 0),
(28623, 'esMX', 'El avance occidental', 'Preséntate ante el rey Phaoris en las Afueras de la Ciudad de Neferset, en Uldum.', 'Nuestro trabajo aquí ha terminado, $n. Contra todo pronóstico, hemos detenido el avance de Neferset en Nahom.$B$BUnámonos a las fuerzas que avanzan al oeste, si no se quedarán con toda la gloria para ellos solos.$B$BYa deben haber llegado a las Afueras de la Ciudad de Neferset.', '', '', '', '', '', '', '', '', '', '', 0),
(28624, 'esMX', 'La bravuconada de Kilram', 'Habla con Deez Hurtarroca.', '¡Bah! ¡Yo solo veo torpeza y tosquedad!$b$bLa fuerza sola no te basta. Mis hachas son igual de fuertes que las mazas de Lilith, ¡pero son tan afiladas que puedo cortar un árbol de un golpe!$B$BY te lo voy a demostrar, aquí, delante de todo el mundo. ¡Pregúntale a Deez a ver si puede traer un árbol!', '', '', '', '', '', '', '', '', '', '', 0),
(28625, 'esMX', 'Dar leña', 'Recoge 10 trozos de madera de escarcha recién cortada de los antárboles Hojaescarcha.', 'Comercio con leña a menudo, ¿pero árboles enteros? Esa es nueva. Como las rocas.$b$bA lo mejor me puedes hacer otro favor. Al oeste de la ciudad hay una arboleda con vistas al Lago Kel\'theril. No sé si es cosa de los fantasmas o de todos esos trastos mágicos élficos que hay por todas partes, pero últimamente hemos visto muchos antárboles y azotadores por allí.$b$bHacen que cortar leña en la zona sea una pesadilla, así que ¿por qué no talas unos cuantos? Tráeme la madera de los antárboles.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Deez Hurtarroca. Zona: Vista Eterna, Cuna del Invierno.', 0),
(28626, 'esMX', 'Entrega de árboles', 'Entrégale el árbol de súper crecimiento instantáneo a Kilram en la posada de Vista Eterna.', '¡Aquí tienes, un árbol de súper crecimiento instantáneo elaborado en un 80% con ingredientes naturales!$b$bSin raíces, sin musgo, sin problemas. Dáselo a Kilram y asegúrate de que se aleja bastante cuando lo use.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Kilram. Zona: Vista Eterna, Cuna del Invierno.', 0),
(28627, 'esMX', 'La bravuconada de Seril', 'Habla con Deez Hurtarroca.', 'Brutos y aficionados.$B$BNo importa lo afilada o pesada que sea tu arma si solo sirve para dar tajos como un ogro. Podría pasarme horas hablando sobre finura, velocidad, equilibrio y control... pero es más fácil ir un paso por delante de esos tontos.$B$BDile a Deez que tenemos una nueva orden para él. Necesito un bloque de hielo.', '', '', '', '', '', '', '', '', '', '', 0),
(28628, 'esMX', 'Una entrega helada', 'Entrégale el bloque de hielo instantáneo a Seril Finiquiplaga en Vista Eterna.', 'Muy bien, ¡un bloque de hielo instantáneo puro y de alta calidad!$b$bDurante un tiempo intenté vendérselos a la gente como protección, ¿sabes? Igual que hacen los magos. Pero nunca llegamos a descubrir cómo se hace para respirar.', '', '', '', '', '', '', '', '', '', '', 0),
(28629, 'esMX', 'Yeti... ¿ya hemos llegado?', 'Obtén 10 pelajes de yeti gruesos de yetis Cardo Nevado.', 'A mis amigos siempre se les ocurren ideas geniales. Nunca creí que pudiera igualarlos... ¡hasta hoy! ¡Acabo de terminar los diseños de algo grande! Si prometes no decírselo a nadie, te contaré el secreto...$b$b¡Voy a construir un yeti mecánico! Mis amigos no solo se asustarán cuando lo vean, ¡sino que cuando se les pase se quedarán impresionados!$b$bNecesitaré pelajes de yeti gruesos de los yetis Cardo Nevado. Hay un montón en las Colinas Cardo Nevado, al sureste.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Umi Risitas. Zona: Vista Eterna, Cuna del Invierno.', 0),
(28630, 'esMX', 'Eco Tres', 'Encuentra Eco Tres.', 'Han desaparecido muchos goblins en las Colinas Cardo Nevado. ¡Yo casi fui una de ellos!$b$bSe me ocurrió la idea de colocar un sensor para que nos alertase cuando los yetis se acercaran a Vista Eterna. Evidentemente, no funciona. Hay yetis por todas partes y no he tenido noticia del cacharro.$b$b¿Te importaría echarle un vistazo de mi parte? A lo mejor se puede arreglar. Eco Tres está al sureste, al borde de las Colinas Cardo Nevado. No preguntes qué pasó con Eco Uno y Eco Dos.', '', '', '', '', '', '', '', '', '', '', 0),
(28631, 'esMX', 'Los cuernos perfectos', 'Hazte con los cuernos prístinos de Golpescarcha.', '¡No puedo hacer un yeti sin cuernos!$b$bParece que llevo toda una vida buscando el par de cuernos perfecto... ¡Y ninguno de los que encuentro está a la altura! Pero justo el otro día vi a un yeti enorme en Cuna del Invierno.$b$bLo llamé Golpescarcha. ¡Sus cuernos son los que andaba buscando! Se esconde en el fondo de la cueva que hay en el lado este de las Colinas Cardo Nevado.$b$bTráeme sus cuernos... ¡Pero no te olvides de echarle un vistazo a Eco Tres por el camino!', '', '', '', '', '', '', 'Golpescarcha', '', '', 'Vuelve con: Umi Risitas. Zona: Vista Eterna, Cuna del Invierno.', 0),
(28632, 'esMX', 'Recién salido de las colinas', 'Reúne 7 trozos de hielo de glaciar puro de la caverna de las Colinas Cardo Nevado.', '¿Ahora toca hielo? Vaya. Tengo buenas noticias y malas noticias.$b$bLa buena noticia es que hay hielo puro y sólido en la caverna de las Colinas Cardo Nevado, todo recto al este de Vista Eterna. La mala noticia es que allí también hay un puñado de yetis sañosos.$b$bPero oye, si puedes encargarte de los yeti, ¡entonces está chupado! Acércate a los trozos más grandes y rómpelos con tu arma. Tráemelos y yo me encargo del resto.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Deez Hurtarroca. Zona: Vista Eterna, Cuna del Invierno.', 0),
(28633, 'esMX', 'El Arca de la promesa', 'Dale a Brann Barbabronce el contenido del Arca de la promesa.', 'No estoy seguro de qué nos espera, así que permanece alerta, ¿eh?$b$bEstos códigos deberían revelar el propósito real de esta arca; y deberían proporcionarnos las herramientas para acabar con los planes de Alamuerte en Uldum ¡para siempre!$b$b¡Apártate!', '', '', '', '', '', '', '', '', '', 'Habla con: Brann Barbabronce. Zona: Cuna de los Ancestros.', 0),
(28634, 'esMX', 'Extinción', 'Mata 12 lechubestias arrasadoras.', 'Lechubestias... Monstruos plumosos sin alma que han venido de las profundidades más oscuras del Vacío Abisal para alimentarse de los débiles.$b$b<Nils señala hacia el bosque que rodea la Torre Oriental.>$b$bNos rodean por todos lados y planean un ataque, lo percibo. Debes detenerlos antes de que puedan organizarse.$b$bQuiero que te adentres en el bosque y mates todas las lechubestias que encuentres. ¡QUE NO SOBREVIVA NI UNA!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Nils Beerot. Zona: Torre Oriental, Laderas de Trabalomas.', 0),
(28635, 'esMX', 'Casa encantada en Trabalomas', 'Registra Dun Garok en busca de pruebas de que esté encantada.', 'La batalla por Dun Garok fue una de las más sangrientas de todo Trabalomas. Los enanos, superados en número diez a uno, lucharon hasta el último segundo. Todos y cada uno de ellos murieron para defender ese pedazo de roca.$b$bAhora oigo rumores de que el sitio está encantado. ¡Nadie quiere acercarse a él! Por desgracia, tengo órdenes de preparar Dun Garok para hacerla habitable.$b$b¿Quieres hacerme un favor y buscar pruebas de si Dun Garok está encantada? Está lejos, al sureste.', 'Registra Dun Garok en busca de pruebas de que esté encantada.', '', '', '', '', 'Registra Dun Garok en busca de pruebas de que esté encantada.', '', '', '', 'Habla con: Fantasma del capitán Ferrocolina. Zona: Dun Garok, Laderas de Trabalomas.', 0),
(28636, 'esMX', 'El silencio de los enanos', 'Mata 10 espíritus de Dun Garok.', 'Ahora los espíritus de mis soldados vagan por este fuerte, $gchaval:chavala;. Sus almas han quedado vinculadas al lugar. Incluso en la muerte quieren seguir luchando por él. Es muy triste.$b$bAcaba con su sufrimiento y quizás puedas hacerte con el botín de la victoria de tu gente.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Capitán Jekyll. Zona: Torre Oriental, Laderas de Trabalomas.', 0),
(28637, 'esMX', 'Antojo de oso', 'Mata a 15 osos Dentoesquirla.', '¿Has tenido ya el privilegio de probar la carne de oso? Yo nunca pude probarla en Gilneas, pero los osos de aquí son simplemente exquisitos.$B$BLos osos Dentoesquirla que hay en el sur están bien protegidos del frío con su grasa. Los he estado cazando yo mismo y es bastante entretenido, ¡pero prefiero comerlos, con diferencia!$B$BTe recomiendo que intentes cazarlos. Limítate a los osos Dentoesquirla de pelaje blanco y el Capitán irá a traerme a cualquiera que mates.', '', '', '', '', '', '', '', 'Mmm... Oso...', 'Francis Morcott', 'Vuelve con: Francis Morcott. Zona: Foso de Humo de Buenazampa, Cuna del Invierno.', 0),
(28638, 'esMX', 'A por lechuzas', 'Mata 15 lechuzas de Cuna del Invierno.', 'Llevo toda la vida comiendo lechuza. Las lechuzas están muy ricas, y mi amigo Jez está de acuerdo. ¡Yo fui el primero en decirle que vendiera lechuza!$b$bEste huargen tan finolis dice que los osos saben mejor, pero no le hagas caso. Deberías cazarte una lechuza. Hay un montón justo al sur de aquí. Por ahora limítate a las grises, y cuando tengas unas cuantas llámame con el artilugio parlanchín que te ha dado Jez.', '', '', '', '', '', '', '', 'Este artilugio parlanchín no deja de confundirme.', 'Jeb Guthrie', '', 0),
(28639, 'esMX', 'Ursius', 'Mata a Ursius.', 'He oído decir que uno es lo que come. No sé si me lo creo, pero si es verdad entonces quiero comerme la criatura más fuerte que encuentre.$b$bUrsius es el oso más grande de Cuna del Invierno. Come el primero cuando su manada de Dentoesquirlas abate una quimera o un lechúcico. Habita en la cueva más cómoda de las tierras de los Dentoesquirla. Y cuenta con una... considerable influencia sobre las hembras Dentoesquirla.$b$bEs mi tipo de oso.$b$bQuiero comérmelo.$b$bSu cueva está cerca de los aplastadores. ¡Buena suerte!', '', '', '', '', '', '', 'Francis Morcott', '', '', 'Vuelve con: Francis Morcott. Zona: Foso de Humo de Buenazampa, Cuna del Invierno.', 0),
(28640, 'esMX', 'Sables de hielo frescos', 'Mata a 15 sables de hielo o acechadores sables de hielo.', '¿A que huele genial? Mis carnes ahumadas siempre triunfan y nadie más puede aportar los sabores exóticos que yo encuentro en las colinas. Y es eficiente; ¡tú cazas a cambio de una pequeña cantidad y mis otros amigos arrastran a las bestias hasta aquí para que sean desolladas y ahumadas!$B$BAhora tengo el monopolio de la carne de sable de hielo. Realmente deliciosa, se hacen unas salchichas estupendas. Ve y caza a esos gatos al oeste, ¡podemos empezar por ahí!', '', '', '', '', '', '', '', '¡Tú sigue cazando y yo seguiré ahumando!', 'Jez Buenazampa', '', 0),
(28641, 'esMX', 'El orgullo de la mesa de la cena', 'Mata a 15 cazadoras sable de hielo o vigías de la manada sable de hielo.', 'Muy bien, $Gchico:chica;, ¡ha llegado la hora de ir campo adentro!$B$BEste botín no está nada mal, pero más lejos, hacia el oeste, encontrarás unos gatitos aún más grandes. Los vigías de la manada y las cazadoras tienen mucho músculo y sirven para hacer unas raciones de hamburguesa INCREÍBLES. ¡Se veden de maravilla!$B$BDame un toque cuando hayas acabado y nos ocuparemos de que vayas a por el plato principal.', '', '', '', '', '', '', 'Jez Buenazampa', '¡Nos queda uno!', 'Jez Buenazampa', '', 0),
(28643, 'esMX', 'El desafío de Durnholde: Zephyrus', 'Mata a Zephyrus.', 'El Castillo de Durnholde siempre ha sido un lugar conflictivo. Durante años los humanos lo utilizaron como campo de internamiento y prisión para los orcos, luego lo tomó la Hermandad. ¿Y ahora? La Dama Oscura lo ha capturado y ha colocado poderosos elementales en los muros. Me ha encargado organizar "el desafío de Durnholde". ¡Todo aquel que derrote a todos los elementales se llevará el gran premio! Llévate esta guía y enfréntate a tu primer desafío: ¡Zephyrus!$b$bDurnholde se encuentra al noreste.', '', '', '', '', '', '', 'Zephyrus', '', '', 'Preséntate ante: Capitán Jekyll. Zona: Torre Oriental, Laderas de Trabalomas.', 0),
(28644, 'esMX', 'El desafío de Durnholde: Teracula', 'Mata a Teracula.', 'Según la guía, tu siguiente desafío es Teracula. Patrulla el camino que hay al exterior de la guarida de Zephyrus.', '', '', '', '', '', '', 'Teracula', '', '', 'Preséntate ante: Capitán Jekyll. Zona: Torre Oriental, Laderas de Trabalomas.', 0),
(28645, 'esMX', 'El desafío de Durnholde: Sangraveneno', 'Mata a Sangraveneno.', 'Según la guía, tu siguiente desafío es Sangraveneno. Este temible elemental se encuentra en el nivel inferior del Castillo de Durnholde, cerca de las prisiones occidentales.', '', '', '', '', '', '', 'Sangraveneno', '', '', 'Preséntate ante: Capitán Jekyll. Zona: Torre Oriental, Laderas de Trabalomas.', 0),
(28646, 'esMX', 'El desafío de Durnholde: Infernus', 'Mata a Infernus.', 'Según la guía, tu siguiente desafío es Infernus. Este ser, compuesto de lava y fuego ardiente, se encuentra en el nivel inferior del Castillo de Durnholde, cerca de las prisiones orientales.', '', '', '', '', '', '', 'Infernus', '', '', 'Preséntate ante: Capitán Jekyll. Zona: Torre Oriental, Laderas de Trabalomas.', 0),
(28647, 'esMX', 'El desafío de Durnholde: D-1000', 'Mata al D-1000.', 'En la antigua arena del Castillo de Durnholde hay un ser compuesto de mercurio puro. Los Renegados lo han llamado D-1000. ¡Mata al D-1000 y reclama tu premio!', '', '', '', '', '', '', 'D-1000', '', '', 'Preséntate ante: Capitán Jekyll. Zona: Torre Oriental, Laderas de Trabalomas.', 0),
(28649, 'esMX', 'Una sorpresa especial', 'El caballero Comandante Puño de Peste te ha ordenado que ejecutes a Lord Harford, un prisionero de El Alba Argenta dentro de la prisión de los alrededores.', 'Llegamos aquí, arrasamos el lugar y nos encaminamos hasta la casa de la prisión. No esperábamos encontrarnos con lo que vimos ahí, $n. Parece que la Cruzada ha estado verdaderamente ocupada. Todo aquello está lleno de prisioneros de El Alba Argenta. La mayoría de ellos ya estaban muertos cuando llegamos, pero algunos pocos aún respiraban.$b$bEstuve a punto de ir allí y acabar con el resto, pero creo que eres tú quien se merece este honor. Sobre todo hay un huargen muy valiente, cuya ejecución creo que disfrutarás de lo lindo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Caballero Comandante Puño de Peste. Zona: Capilla de la Llama Carmesí, Tierras de la Peste: El Enclave Escarlata.', 0),
(28650, 'esMX', 'Una sorpresa especial', 'El caballero Comandante Puño de Peste te ha ordenado que ejecutes a Gally Tiñebulto, un prisionero de El Alba Argenta dentro de la prisión de los alrededores.', 'Llegamos aquí, arrasamos el lugar y nos encaminamos hasta la casa de la prisión. No esperábamos encontrarnos con lo que vimos ahí, $n. Parece que la Cruzada ha estado verdaderamente ocupada. Todo aquello está lleno de prisioneros de El Alba Argenta. La mayoría de ellos ya estaban muertos cuando llegamos, pero algunos pocos aún respiraban.$b$bEstuve a punto de ir allí y acabar con el resto, pero creo que eres tú quien se merece este honor. Sobre todo hay un goblin muy valiente, cuya ejecución creo que disfrutarás de lo lindo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Caballero Comandante Puño de Peste. Zona: Capilla de la Llama Carmesí, Tierras de la Peste: El Enclave Escarlata.', 0),
(28651, 'esMX', 'La novicia Elreth', 'Habla con la novicia Elreth en Camposanto, en los Claros de Tirisfal.', 'Ahora que ya has terminado con la instrucción, ¿por qué no vas a hablar con Elreth? Trabaja para el sacerdote de las Sombras Sarvis y es probable que tenga tareas en las que puedas aplicar tus nuevas facultades.', '', '', '', '', '', '', '', '', '', 'Habla con: Novicia Elreth. Zona: Camposanto, Claros de Tirisfal.', 0),
(28652, 'esMX', 'Custodio Caice', 'Habla con el custodio Caice en las Tumbas del Camposanto, en los Claros de Tirisfal.', 'Yo ya he terminado contigo, pero hay a quien le vendría bien tu ayuda.$b$bEl custodio Caice, que está de pie en ese tocón que tengo detrás, seguramente podrá asignarte otra tarea. Deberías hablar con él.', '', '', '', '', '', '', '', '', '', '', 0),
(28653, 'esMX', 'Sacerdote de las Sombras Sarvis', 'Habla con el sacerdote de las Sombras Sarvis en Camposanto, en los Claros de Tirisfal.', '¿Sigues aquí, $n? Solo soy un guardia de la Muerte, ¿sabes? No tengo muchas tareas que asignar a los viandantes como tú.$b$bTe recomendaría que hablaras con el sacerdote de las Sombras Sarvis. Recuerdo que me ayudó a recuperarme cuando me sacaron de aquella tumba. Seguro que hará lo mismo por ti.$b$bLo verás en el interior de la capilla, en el lado oeste del pueblo.', '', '', '', '', '', '', '', '', '', '', 0),
(28654, 'esMX', 'El corazón de la cuestión', 'Brann Barbabronce quiere que te encuentres con él en las Cámaras de los Orígenes.', 'Bueno, $gcompañero:señorita;, a una parte de mí le gustaría poder quedarse y disfrutar de las vistas contigo.$b$bEn mis tiempos vi cosas realmente asombrosas, pero nada como esto de aquí.$b$bPor desgracia, tengo que investigar un poco sobre estos discos antes de poder acceder a las Cámaras de los Orígenes.$b$bParece que sabes lo que te haces, tal vez te gustaría venir conmigo y ver cómo trabaja un arqueólogo de VERDAD, ¿eh?', '', '', '', '', '', '', '', '', '', '', 0),
(28655, 'esMX', 'La boda Martillo Salvaje, salvaje, salvaje', 'Habla con Grundy MacGraff para que comience la ceremonia de la boda. ¡Mata a cualquiera del Martillo Crepuscular que intente detenerla!', '¡Estamos listos para empezar, $n!$B$BPero sé de buena tinta que puede que el Martillo Crepuscular intente perturbar la ceremonia, para desmoralizar a los Martillo Salvaje. ¡La cosa podría ponerse peligrosa!$B$BPor eso, yo mismo oficiaré la ceremonia, para tener cerca a los novios. ¿Te parece un buen plan? ¡Bien!$B$BComo su padre está muerto y su hermano es el padrino, Fanny ha pedido que seas tú quien la lleve al altar. ¡Menudo honor! Habla conmigo cuando estés $glisto:lista; para empezar.', '', 'Nupcias completadas', '', '', '', '', '', '', '', 'Habla con: Kurdran Martillo Salvaje. Zona: Kirthaven, Tierras Altas Crepusculares.', 0),
(28656, 'esMX', 'Fuerzas vitales extrañas', 'Habla con la médica bruja Mau\'ari en el Chalet Cubilnevado, en Cuna del Invierno.', 'Cuando esta criatura murió, su cuerpo despidió algún tipo de energía. La energía se trasladó hacia ti y ahora te sientes más fuerte.$b$bSegún los habitantes de Cuna del Invierno, la médica bruja Mau\'ari del Chalet Cubilnevado es una experta de la fauna local. A lo mejor sabe algo sobre esta misteriosa energía.', '', '', '', '', '', '', '', '', '', '', 0),
(28657, 'esMX', 'Un problema enorme', 'Te han pedido que mates a Problim, un ettin gigante que merodea por los caminos de Tol Barad.', '¡Por fin nos hacemos con esa maldita roca y ahora descubrimos que hay un enorme ettin merodeando por ella y aniquilando a nuestras patrullas de centinelas!$B$B$n, necesito que reúnas a unos cuantos amigos y que acabes con ese ettin. No podemos permitir que una bestia como esa merodee a sus anchas causando el caos.$B$BPermanece alerta, los informes del frente indican que lleva un árbol enorme a modo de arma, y no dudará en utilizarlo.', '', '', '', '', '', '', 'Problim', '', '', 'Preséntate de nuevo ante el comandante Zanoth en el Bastión de Baradin cuando termines.', 0),
(28658, 'esMX', 'Cebo de pantano', 'Te han encargado que recojas 8 pellejos de crocolisco de crocoliscos de Baradin en Tol Barad. Encontrarás los crocoliscos en el pantano, al oeste del Bastión de Baradin.', 'En un lugar como este, nunca es fácil encontrar suministros, $c. Hemos estado explorando desde que recuperamos la isla, pero la cosa no pinta bien.$B$BPor suerte, acabamos de recibir informes de nuestros exploradores de que hay un pantano lleno de crocoliscos al oeste de nuestro campamento. Los pellejos de esos crocoliscos les vendrán estupendamente a nuestros peleteros. Tráeme todos los que puedas.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Zanoth en el Bastión de Baradin cuando termines.', 0),
(28659, 'esMX', 'Los restos', 'Te han ordenado que mates a 12 soldados de infantería de la Alianza en Tol Barad. Encontrarás sus grupos de resistencia en los Rescoldos, la Vigilia del Celador y el Cuartel del Acorazado, aquí en Tol Barad.', 'Hemos peleado mucho para hacernos con esta isla, $r. Nos hemos deshecho de la mayoría de la escoria de la Alianza, pero todavía percibo su asqueroso olor en el aire.$b$bNecesito que investigues los Rescoldos, la Vigilia del Celador y el Cuartel del Acorazado. Mata a todos los miembros de la Alianza que encuentres.$B$B¡Ya conoces el dicho: solo hay un miembro de la Alianza bueno, y es el que está muerto!', '', 'Infantería de la Alianza', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Zanoth en el Bastión de Baradin cuando termines.', 0),
(28660, 'esMX', 'Limpiando las profundidades', 'Te han pedido que mates a 9 fantasmas de cualquier tipo en las Profundidades Malditas, al este del Bastión de Baradin.', 'Me alegro de verte, $n. Ahora que nos hemos hecho con Tol Barad, la batalla acaba de comenzar.$B$BHemos descubierto un módulo al este de aquí que necesitamos que limpies. Por lo visto está plagado de fantasmas que llevan encerrados allí abajo ni se sabe el tiempo.$b$bLimpia la zona todo lo que puedas y preséntate de nuevo ante mí cuando termines.', '', 'Fantasmas asesinados', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el soldado Garnoth en el Bastión de Baradin cuando termines.', 0),
(28661, 'esMX', 'El archimago prisionero', 'Tienes que matar al archimago Galus y volver con su báculo de las Profundidades Malditas, al este del Bastión de Baradin.', 'Desde que llegamos a Tol Barad hemos estado intentando limpiar los módulos de las Profundidades Malditas. Parece que cada vez que nos acercamos, aparece ese archimago y nos obliga a retroceder.$B$BAhora que nos hemos hecho con la isla, ha llegado el momento de intentarlo de nuevo. Dirígete hasta allí y tráeme su báculo como prueba de que has terminado el trabajo.', '', '', '', '', '', '', 'Archimago Galus', '', '', 'Preséntate de nuevo ante el soldado Garnoth en el Bastión de Baradin cuando termines.', 0),
(28662, 'esMX', 'Aprender del pasado', 'Te han pedido que recuperes cuatro diarios de prisión polvorientos de las Profundidades Malditas, al este del Bastión de Baradin.', 'Ahora que por fin dominamos esta isla destartalada, podremos investigar cómo acabó en este estado. Algunas de nuestras tropas han descubierto diarios alrededor de la entrada del módulo de las Profundidades Malditas, al este de aquí.$B$BEstos diarios son especialmente interesantes para nuestros ancianos escribas en el campamento. Necesito que recuperes cuatro de ellos y que me los traigas lo antes posible.$B$BTen cuidado ahí abajo, $n, ese lugar está plagado de no-muertos.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el soldado Garnoth en el Bastión de Baradin cuando termines.', 0),
(28663, 'esMX', 'Bloque D', 'Te han pedido que mates a 10 demonios de cualquier tipo en el Bloque D, al noroeste del Bastión de Baradin.', '¿Ya has oído hablar del Bloque D, $n? Es uno de los viejos módulos en la isla. El problema es que está infestado de demonios. Hemos planeado utilizarlo para encerrar al resto de miembros de la Alianza que quedan en la isla, pero en su estado actual no va a ser posible.$B$BNecesito que vayas hasta allí y que te encargues de eliminar a esos demonios. Preséntate de nuevo ante mí cuando termines.', '', 'Demonios asesinados', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el maestro de maniobras Razgoth en el Bastión de Baradin cuando termines.', 0),
(28664, 'esMX', 'Svarnos', 'Debes matar a Svarnos en el Bloque D y volver con su collera maldita. Svarnos está en el Bloque D, al noroeste del Bastión de Baradin.', 'Un trabajo excelente al capturar la isla, $c. Ahora que es nuestra, tenemos que conseguir que los bloques de celdas sean aptos para albergar prisioneros. El Bloque D ha resultado ser especialmente difícil de despejar. Por desgracia, está lleno de demonios de todo tipo.$b$bHemos podido diezmar los demonios, pero un can del Núcleo enorme se ha escapado de su celda y está sembrando el caos ahí abajo. Quiero que lo mates y me traigas su collar.', '', '', '', '', '', '', 'Svarnos', '', '', 'Preséntate de nuevo ante el maestro de maniobras Razgoth en el Bastión de Baradin cuando termines.', 0),
(28665, 'esMX', 'Grilletes malditos', 'Te han pedido que recuperes 8 grilletes malditos en el Bloque D, al noroeste del Bastión de Baradin.', '¿Has estado ya en el Bloque D, $n? Cada vez que limpiamos ese módulo infestado, los demonios vuelven muy rápidamente. Hemos descubierto que se regeneran a partir de los grilletes malditos que están desperdigados por la zona. Y ahí es donde entras tú, $n.$B$BNecesito que recuperes todos los grilletes que puedas y que me los traigas. Los destruiremos inmediatamente.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el maestro de maniobras Razgoth en el Bastión de Baradin cuando termines.', 0),
(28666, 'esMX', 'Se busca héroe: ¡Las Estepas Ardientes!', 'Preséntate ante John J. Keeshan en el Puesto Llamaestrella en Las Estepas Ardientes.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante John J. Keeshan en el Puesto Llamaestrella.$B$B¡Necesitamos tu ayuda urgentemente para detener la amenaza Roca Negra!$B$BPuedes llegar a Las Estepas Ardientes si viajas desde La Garganta de Fuego a través de la Montaña Roca Negra. Busca el Puesto Llamaestrella en la parte más alejada de la montaña.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28667, 'esMX', 'Orden del Jefe de Guerra: ¡Las Estepas Ardientes!', 'Preséntate ante Ariok en el Puesto Llamaestrella en Las Estepas Ardientes.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Ariok en el Puesto Llamaestrella.$B$BEl honorable hijo de Eitrigg, Ariok, necesita tu ayuda para detener el ciego ataque de los orcos Roca Negra antes de que invadan las tierras vecinas.$B$BPuedes llegar hasta Las Estepas Ardientes si te diriges hacia el sur desde La Garganta de Fuego, pasando por la Montaña Roca Negra. El Puesto Llamaestrella se encuentra al sur de la montaña.$B$B¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28668, 'esMX', 'Revuelta en la cárcel', 'Te han ordenado que mates a 10 prisioneros de cualquier tipo en El Agujero, al suroeste del Campamento de Baradin.', 'Tenemos la isla, y ahora tenemos que aprovechar los recursos de la zona. Hemos encontrado un módulo abandonado al suroeste de aquí y necesitamos que vayas a investigar, $n.$B$BHemos recibido informes de que está plagado de prisioneros que llevan allí encerrados durante años. Haz lo que tengas que hacer para limpiar ese lugar. Preséntate de nuevo ante mí cuando termines.', '', 'Prisioneros asesinados', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el sargento de segunda Lazgar en el Bastión de Baradin cuando termines.', 0),
(28669, 'esMX', 'El celador', 'Tienes que matar al celador Silva en El Agujero y volver con sus llaves. El Agujero está al suroeste del Bastión de Baradin.', 'Ya casi hemos terminado de eliminar a los prisioneros de la revuelta en El Agujero, pero nos queda un último problema: el celador.$b$bEl celador Silva es su señor y harán lo que sea por él. Si lo eliminamos a él, los eliminamos a todos. Acaba con él y tráeme sus llaves. Podemos usar las llaves para explorar más en profundidad el módulo y tal vez así consigamos acceder al suministro de agua en la isla.', '', '', '', '', '', '', 'Celador Silva', '', '', 'Preséntate de nuevo ante el sargento de segunda Lazgar en el Bastión de Baradin cuando termines.', 0),
(28670, 'esMX', 'Comida desde abajo', 'Te han pedido que recuperes 12 raciones de módulo de El Agujero, justo al suroeste del Bastión de Baradin.', 'Estamos bajos de suministros en el campamento, $n. Acabamos de enterarnos de que en el módulo al suroeste de aquí quedan raciones de la época en que estaba en uso. Necesitamos que recojas todas las que puedas y que las traigas al campamento.$B$BUna cosa más: todo el módulo está plagado de prisioneros, así que ten cuidado.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el sargento de segunda Lazgar en el Bastión de Baradin cuando termines.', 0),
(28671, 'esMX', '¡La orden del Jefe de Guerra: Las Tierras Devastadas!', 'Preséntate ante Okrilla en el Bastión Machacamiedo, en las Tierras Devastadas.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Okrilla en el Bastión Machacamiedo.$b$bOkrilla, comandante de las fuerzas de la Horda en el Bastión Machacamiedo, necesita tu ayuda para afianzar la avanzada contra los ogros rebeldes y las fuerzas de la Alianza.$b$bVe hasta el Bastión Machacamiedo por el camino que hay al sur del Pantano de las Penas.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28672, 'esMX', 'El ejecutor en el campo', 'Preséntate ante el ejecutor Arren.', 'Podría tenerte trabajando en el pueblo toda la semana, pero parece que te va más el combate.$b$b<Elreth te mira de arriba abajo y asiente.>$b$bSí, servirás. Quiero que vayas a hablar con el ejecutor Arren. Sigue el camino hacia el norte y sal de Camposanto. Lo encontrarás poco después de pasar las barricadas.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Ejecutor Arren. Zona: Camposanto, Claros de Tirisfal.', 0),
(28673, 'esMX', 'Se busca héroe: ¡Las Tierras Devastadas!', 'Preséntate ante el intendente Lungertz en el Castillo de Nethergarde.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el intendente Lungertz en el Castillo de Nethergarde.$b$b¡Las tropas de guarnición de Nethergarde necesitan tu ayuda urgentemente para contener el avance de la Horda en Las Tierras Devastadas! Ve al sur desde el Pantano de las Penas y sigue el camino hacia el este para llegar al Castillo de Nethergarde.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28674, 'esMX', 'Aldea Estrella Fugaz', 'Habla con Wynd Cazanoche en la Aldea Estrella Fugaz.', 'Te has mantenido bastante $gocupado:ocupada; por aquí. Si aún quieres hacer buenas acciones, o si solo buscas que te paguen, tengo algo que te puede interesar.$b$bLa Aldea Estrella Fugaz está justo al noroeste de Vista Eterna. Los elfos de la noche de la aldea están sufriendo una infestación de bichos bastante grave y piden toda la ayuda que puedan conseguir.$b$bUnos cuantos goblins ya fueron desde aquí para empezar a exterminar, pero seguro que hay sitio para más. Habla con Wynd Cazanoche, él te pondrá al día.', '', '', '', '', '', '', '', '', '', '', 0),
(28675, 'esMX', 'Se busca héroe: ¡El Pantano de las Penas!', 'Preséntate ante el barón mercante Brochargento en Chapaleos, en el Pantano de las Penas.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el barón mercante Brochargento en Chapaleos.$b$b¡Las fuerzas de la Alianza necesitan con urgencia las municiones que proporciona el barón! Debes hacer lo que haga falta para convencerlo para que siga vendiéndonos suministros a precios razonables.$b$bPara llegar al pantano, sigue el camino que sale por el sureste de las Estepas Ardientes, por las Montañas Crestagrana.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28676, 'esMX', 'Exterminadores al rescate', 'Habla con Rinno Flamacortina dentro del Túmulo de Ban\'Thallow.', 'Nuestro túmulo se infestó prácticamente de la noche a la mañana. Unas terribles criaturas que no habíamos visto antes en estas tierras llenaron los túneles sin que viéramos los huevos de los que eclosionaron.$b$bSiendo tan pocos, apenas pudimos evitar que se extendieran fuera del túmulo. Hemos tenido que contratar goblins de Vista eterna que aseguran ser expertos en la exterminación, pero todavía no han tenido éxito.$b$bSi deseas ayudarles, entra en el túmulo al oeste de este lugar y habla con Rinno Flamacortina.', '', '', '', '', '', '', '', '', '', '', 0),
(28677, 'esMX', '¡La orden del Jefe de Guerra: El Pantano de las Penas!', 'Preséntate ante el barón mercante Brochargento en Chapaleos, en el Pantano de las Penas.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el barón mercante Brochargento.$b$bPersuade al barón mercante para que siga suministrando a nuestros guerreros con las armas y municiones que necesite, ¡cueste lo que cueste!$b$bViaja hasta el Pantano de las Penas por el camino que sale por el sureste de las Estepas Ardientes, por las Montañas Crestagrana, y reúnete con el barón mercante en su complejo de vacaciones.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28678, 'esMX', 'Capitán P. Harris', 'Te han encargado que mates al Capitán P. Harris en el Cabo de la Esperanza Perdida. El Cabo de la Esperanza Perdida se encuentra al noroeste de aquí, a lo largo de la costa. Busca los restos de naufragio.', 'El Cabo de la Esperanza Perdida es un punto delicado para nuestra facción desde hace semanas aquí en Tol Barad. La mitad de nuestros barcos de suministros acaban contra las rocas.$b$bY para empeorar las cosas, está plagado de marineros no-muertos. Hemos intentado reducir sus efectivos, pero parecen volver incesantemente. Nuestro último recurso es acabar con el capitán ante el que responden. Lo encontrarás en un barco, cerca de la costa.$b$bOh, y espero que no le tengas mucho miedo a los tiburones.', '', '', '', '', '', '', 'Capitán P. Harris', '', '', 'Preséntate de nuevo ante el tercer oficial Kronkar en los Dominios Grito Infernal cuando termines.', 0),
(28679, 'esMX', 'Golpear las jaulas', 'El tercer oficial Kronkar te ha pedido que mates a 8 marineros naufragados en el Cabo de la Esperanza Perdida. El cabo se encuentra al noroeste de aquí, en la playa.', 'Llevamos teniendo problemas con los no-muertos del Cabo de la Esperanza Perdida durante cierto tiempo. Cada vez que naufraga un barco, consiguen engrosar sus filas de no-muertos.$b$b¿Podrías hacernos un favor y reducir sus unidades ahí fuera? Sé que no podrás matarlos a todos, pero todo lo que hagas servirá de ayuda tal y como están las cosas.$b$bTen cuidado con la alianza, hemos recibido informes de que llevan a cabo emboscadas en la playa últimamente.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el tercer oficial Kronkar en los Dominios Grito Infernal cuando termines.', 0),
(28680, 'esMX', 'Elevar la moral', 'Te han pedido que recuperes 6 barricas de ron de los Mares del Sur de los barcos naufragados en el Cabo de la Esperanza Perdida. El cabo se encuentra al norte de aquí, a lo largo de la costa.', 'La moral está baja estos días, $n. Hacemos todo lo que podemos para que las tropas mantengan la moral alta pero se nos están acabando los suministros de nuestro principal elevador de moral... el ron.$b$bHe recibido informes de nuestra infantería en el sur de que los barcos naufragados en el Cabo de la Esperanza Perdida todavía conservan sus suministros de ron de los Mares del Sur en sus cascos. ¿Podrías ir a investigar?$b$bTrae todo el ron que encuentres.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el tercer oficial Kronkar en los Dominios Grito Infernal cuando termines.', 0),
(28681, 'esMX', 'Tiburón Tanque', 'Te han pedido que mates a Tanque, un gran tiburón que recorre las aguas del Cabo de la Esperanza Perdida. El cabo se encuentra al norte de aquí, a lo largo de la costa norte.', 'Odio los tiburones. Mis tropas odian los tiburones también. Y ahí es donde entras tú, $n.$b$bNecesito que te dirijas al Cabo de la Esperanza Perdida y que acabes con un tiburón enorme que se llama Tanque. Tanque es duro de pelar, así que si fuese tú, me llevaría a algunos amigos.', '', '', '', '', '', '', 'Tanque', '', '', 'Preséntate de nuevo ante el tercer oficial Kronkar en los Dominios Grito Infernal cuando termines.', 0),
(28682, 'esMX', 'Reclamar la fortaleza', 'Te han pedido que mates al señor de la fortaleza Farson en la Fortaleza de Farson. La Fortaleza de Farson se encuentra en la zona norte de la isla.', '¿Has visto la fortaleza de la zona norte de la isla, $n? Desde ahí dirige el señor de la fortaleza Farson sus operaciones.$b$bFarson tiene un pequeño grupo de acérrimos seguidores que nos han estado dando problemas desde que llegamos. Enviamos a un grupo a investigar y nos informó de su posición exacta en el interior de la fortaleza.$b$b¿Podrías acabar con él por nosotros?', '', '', '', '', '', '', 'Farson', '', '', 'Preséntate de nuevo ante el comandante Larmash en los Dominios Grito Infernal cuando termines.', 0),
(28683, 'esMX', 'Reducir sus efectivos', 'Mata a 12 rondadores Leñoscuro en Leñoscuro. El bosque Leñoscuro se encuentra al norte de aquí, al otro lado del puente de la isla central.', 'Llevamos semanas tratando de hacernos con Leñoscuro, pero ese bosque está plagado de arañas. Hazme un favor, intenta reducir su número lo suficiente como para que podamos intentar un ataque.$b$bTen cuidado ahí fuera, he recibido informes sobre la presencia de tropas de la Alianza en la zona a principios de semana.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el tercer oficial Kronkar en los Dominios Grito Infernal cuando termines.', 0),
(28684, 'esMX', 'Una tarea pegajosa', 'Reúne 4 glándulas de seda pegajosas de las madres de linaje Leñoscuro en Leñoscuro. El bosque Leñoscuro está al oeste, al otro lado del puente en la isla central.', 'Decir que encontrar suministros en esta isla es difícil es decir poco.$b$bAfortunadamente, hemos encontrado una buena cantidad de seda en Leñoscuro, al norte de aquí. La mala noticia es que la seda viene de las glándulas de las arañas madre de linaje. Quiero que reúnas 4 de ellas.$b$bDebería bastar para terminar esta tanda de camisas.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el tercer oficial Kronkar en los Dominios Grito Infernal cuando termines.', 0),
(28685, 'esMX', 'Hasta la última arma', 'Recoge 12 rifles oxidados en la Fortaleza de Farson en la zona norte de la Península de Tol Barad.', 'Es difícil encontrar suministros de batalla en esta roca. Cada vez que nos enfrentamos a un ataque de la Alianza, da la sensación de que estamos luchando con palos y piedras.$B$BNos han informado de que el señor de la fortaleza Farson, en la zona norte de la isla, tiene grandes reservas de rifles que podríamos usar. ¿Podrías dirigirte hacia allí y confirmarlo?$b$bTen cuidado, $n, los seguidores de Farson harán lo que sea con tal de protegerlo.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Larmash en los Dominios Grito Infernal cuando termines.', 0),
(28686, 'esMX', 'Un pueblo poco amistoso', 'El comandante Larmash te ha pedido que mates a 14 aldeanos en Aldea Monrojo. Aldea Monrojo se encuentra al norte del campamento, en la parte de la derecha.', '¿Has estado ya en la Aldea Monrojo, $n? Te recomiendo que lleves una hoja bien afilada si vas para allá.$b$bLos habitantes de la aldea parecen normales, pero algo sospechoso se cuece por allí. Hemos recibido informes de que acaban con nuestros soldados a diestro y siniestro. Ya lo hemos tolerado bastante tiempo, así que necesito que vayas para allá y que hagas un poco de limpieza.$B$BAcaba con todos los que puedas y preséntate ante mí cuando acabes.', '', 'Residentes de Aldea Monrojo', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Larmash en los Dominios Grito Infernal cuando termines.', 0),
(28687, 'esMX', 'Enseña a un hombre a pescar... o a robar', 'Tienes que robar 22 lubinas de Monrojo. Encontrarás los pescados en redes en el embarcadero, en la parte trasera de la aldea. La Aldea Monrojo se encuentra al norte del campamento, a la derecha.', 'Aldea Monrojo: ese lugar es una maldición y una bendición para nosotros, $n. No sé dónde aprenderían los bandidos a pescar tan bien como lo hacen, pero ahora no tengo tiempo de preocuparme de eso.$B$BNecesito que vayas hasta allí y que robes todas las reservas de pescado que puedas. Desde que recuperamos la isla estamos viviendo de las sobras; y esta es nuestra única opción de conseguir reservas de comida sólida.$B$BTen cuidado con los sigilosos de ahí arriba, tenemos informes de que siguen en el interior de las murallas de la aldea.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el comandante Larmash en los Dominios Grito Infernal cuando termines.', 0),
(28688, 'esMX', 'Orden del Jefe de Guerra: ¡Norte de la Vega de Tuercespina!', 'Preséntate ante el comandante Aggro\'gosh en el Campamento Grom\'gol, en el Norte de la Vega de Tuercespina.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el comandante Aggro\'gosh en el Campamento Grom\'gol. El comandante necesita tu ayuda para mantener las rutas de suministros abiertas y libres de las interferencias de los habitantes locales y de la molesta Alianza.$b$bPara llegar a Grom\'gol, toma un zepelín desde la torre de zepelín este de Orgrimmar o desde la que hay cerca de Entrañas.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28689, 'esMX', 'Los olvidados', 'Libera los espíritus de 6 almas torturadas en la Colina del Olvido. Puedes canalizar las almas tocando las lápidas directamente con la mano. La Colina del Olvido está al oeste de aquí, más allá del Frente Inquieto.', 'En esta isla han muerto muchos soldados, $n. Lo justo es que les presentemos nuestros respetos de la forma que podamos.$b$bNecesito que viajes hasta la Colina del Olvido, al oeste de aquí, y que liberes las almas torturadas de nuestros compañeros de batalla en ese lugar. Pero ten cuidado por ahí, tenemos informes sobre la presencia de no-muertos en la zona.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el capitán Prug en los Dominios Grito Infernal cuando termines.', 0),
(28690, 'esMX', 'Recuperando los restos', 'Tienes que recoger 9 fémures malditos de los necrófagos que habitan la Colina del Olvido. La Colina del Olvido está en la zona oeste de la isla, pasado el Frente del Olvido.', 'La Colina del Olvido está invadida de zombis y de necrófagos desde que nos hicimos con esta isla destartalada. Hemos tratado de librarnos de ellos muchas veces, pero siempre terminan volviendo.$b$bUno de nuestros tenientes nos ha recomendado que nos llevemos los huesos de los necrófagos después de matarlos, para evitar que resuciten al día siguiente. ¿Crees que podrías ayudarnos con eso?', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el capitán Prug en los Dominios Grito Infernal cuando termines.', 0),
(28691, 'esMX', 'Teniente primero Connor', 'Encuentra y mata al teniente primero Connor en la Colina del Olvido. Encontrarás la Colina del Olvido en el extremo occidental de la isla.', 'La primera vez que oí hablar del teniente Connor, no era más que un joven recluta en la Sima Ígnea. Ninguno de nosotros hubiera imaginado que acabaría aquí en Tol Barad. Por desgracia, todavía merodea por estas destartaladas islas, destrozando la moral de nuestras tropas.$b$bNecesito que acabes con su sufrimiento... y con el nuestro.', '', '', '', '', '', '', 'Connor', '', '', 'Preséntate de nuevo ante el capitán Prug en los Dominios Grito Infernal cuando termines.', 0),
(28692, 'esMX', 'Imanes, ¿cómo funcionan?', 'Te han encargado que recuperes 7 piezas de chatarra de máquina de asedio. Usa el recolector de chatarra magnetizado en el Frente Inquieto para encontrar chatarra. El Frente Inquieto se encuentra al oeste, pasado el segundo puente.', 'Conseguir piezas útiles de maquinaria en la isla no ha sido tarea fácil, $n. Llevamos tiempo intentando reparar las máquinas de asedio estropeadas en el campamento, pero siempre nos quedamos sin las piezas necesarias.$b$bNuestro segundo regimiento nos ha informado de que hay máquinas de asedio destrozadas en un antiguo campo de batalla al oeste de aquí. Tal vez encontremos algunas piezas allí.$B$bTe costará encontrar algo en ese campo de batalla, así que llévate este recolector de chatarra magnetizado y dale buen uso.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el capitán Prug en los Dominios Grito Infernal cuando termines.', 0),
(28693, 'esMX', 'Termina el trabajo', 'Mata a 5 soldados inquietos en El Frente Inquieto. Encontrarás el frente en la zona oeste de la isla, justo antes de la Colina del Olvido.', 'Llevamos toda la semana tratando de recoger chatarra útil en el frente. Cada vez que reunimos un lote para llevarlo al campamento, nos asaltan los soldados inquietos de la zona. ¿Podrías dirigirte hasta allí y borrarlos del mapa?', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el capitán Prug en los Dominios Grito Infernal cuando termines.', 0),
(28694, 'esMX', '¡Cuidado con las astillas!', 'El soldado Sarlosk te ha pedido que recuperes 15 trozos de madera de astillero del Astillero de Wellson. La madera puede obtenerse de los fantasmas del astillero o tirada en las inmediaciones. El astillero se encuentra al noroeste de aquí, en la costa.', '¿Has estado ya en el Astillero de Wellson, $n? Lo mejor es no acercarse por allí a no ser que se tenga un buen motivo para hacerlo. Por desgracia, es justo lo que necesito que hagas.$b$bVerás, desde que retomamos la isla estamos bajos de suministros. Ese astillero plagado de fantasmas está lleno de madera, pero siempre que hemos enviado a alguien a recogerla, no ha conseguido volver.$b$b¿Puedes ayudarnos?', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el soldado Sarlosk en los Dominios Grito Infernal cuando termines.', 0),
(28695, 'esMX', 'SE BUSCA: Supervisor Wellson', 'Mata al supervisor Wellson en el Astillero de Wellson. El astillero se encuentra al norte, en la costa oeste.', 'El supervisor Wellson ha sido un incordio desde que llegamos. Su astillero contiene una gran cantidad de suministros que nos resultarían extremadamente útiles... si pudiéramos echarles el guante.$b$bControla a sus esbirros de cerca y nos cuesta mucho adentrarnos en el astillero. Quiero que acabes con Wellson de una vez por todas. Ten cuidado, $n, hemos recibido informes de que la Alianza está presente por todas partes.', '', '', '', '', '', '', 'Supervisor Wellson', '', '', 'Preséntate de nuevo ante el soldado Sarlosk en los Dominios Grito Infernal cuando termines.', 0),
(28696, 'esMX', '¡Bombas fuera!', 'Destruye 10 barcos de suministros espantosos.', 'El astillero de Wellson está recibiendo suministros constantemente por mar y tenemos que acabar con eso. Han colocado cañones a lo largo del embarcadero para defenderse, pero si consigues llegar hasta ellos, podremos usarlos para destruir sus barcos de suministros.$B$BDirígete hasta allí y averigua lo que puedes hacer. Infórmame de tus avances.', '', 'Barcos de suministros de Wellson destruidos', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el soldado Sarlosk en los Dominios Grito Infernal cuando termines.', 0),
(28697, 'esMX', 'Cazafantasmas', 'Mata a 14 fantasmas de cualquier tipo en el Alto de Largo, al noreste del campamento de la Horda.', '¿Ves esa colina con las torres hacia el nordeste? Es el Alto de Largo y no es un lugar agradable para establecer cerca un campamento. Desde que establecimos el campamento aquí hemos estado enfrentándonos con esos espíritus y espectros.$b$b¿Te importaría ir hasta allá arriba y hacerles saber que no pensamos irnos en un futuro próximo? Unas cuantas muertes en sus filas los mantendrán a raya.$b$bGracias por ayudarnos con esto, $n.', '', 'Fantasmas del Alto de Largo asesinados', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el soldado Sarlosk en los Dominios Grito Infernal cuando termines.', 0),
(28698, 'esMX', '¡Bola de cañón!', 'Tienes que recuperar 4 montones de bolas de cañón en el Alto de Largo para el soldado Sarlosk. Encontrarás el Alto de Largo al noreste del campamento.', 'Largo y sus esbirros han estado robando nuestros suministros desde que acampamos aquí. Resulta frustrante, por no decir otra cosa.$b$bTenemos informes que indican que está almacenando bolas de cañón en las torres que dominan estas aguas en su mirador. ¿Podrías ir ahí arriba y tratar de recuperar algunas para nosotros?$b$bY, $n, no te olvides de mantenerte alerta contra la Alianza también.', '', '', '', '', '', '', '', '', '', 'Preséntate de nuevo ante el soldado Sarlosk en los Dominios Grito Infernal cuando termines.', 0),
(28699, 'esMX', 'Se busca héroe: ¡Norte de la Vega de Tuercespina!', 'Preséntate ante el teniente Doren en el Asentamiento Rebelde, en el Norte de la Vega de Tuercespina.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el teniente Doren en el Asentamiento Rebelde.$b$bAños después de la traición del coronel Kurzen contra Ventormenta, la verdad sobre lo sucedido sigue siendo un misterio. Ayuda a los supervivientes a descubrir qué pasó con el coronel. Viaja al sur desde el Bosque del Ocaso y sigue el camino hacia el oeste después de haber entrado en la selva para llegar al Asentamiento Rebelde.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28700, 'esMX', 'Recuperar el Alto', 'El soldado Sarlosk te ha pedido que mates al comandante Largo en el Alto de Largo. El Alto se encuentra al noreste del campamento.', 'Solo hay una forma de recuperar el Alto de Largo.$b$bCreo que ya sabes lo que tenemos que hacer, $n. Largo está bastante paranoico últimamente, así que lo encontrarás en lo alto de la torre, esperando a que llegue por fin su marina imaginaria.', '', '', '', '', '', '', 'Comandante Largo', '', '', 'Preséntate de nuevo ante el soldado Sarlosk en los Dominios Grito Infernal cuando termines.', 0),
(28701, 'esMX', 'Fuera de peligro', 'Recupera 5 reliquias Estrella Fugaz del Túmulo de Ban\'Thallow.', 'Afortunadamente, cuando sucedió la infestación no había ningún druida durmiendo en el túmulo del oeste. Aun así, sigue siendo un lugar sagrado para nosotros y sus profundidades contienen reliquias benditas que llevan siglos sin tocarse.$b$bAunque confío relativamente en los exterminadores goblin, también estoy... al corriente de las costumbres de su raza. Por favor, recoge todas las reliquias que encuentres en el túmulo y tráemelas para que nadie las dañe. Están metidas en urnas colocadas en pequeños huecos por todo el túmulo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Wynd Cazanoche. Zona: Aldea Estrella Fugaz, Cuna del Invierno.', 0),
(28702, 'esMX', 'Se busca héroe: ¡El Cabo de Tuercespina!', 'Preséntate ante Bronwyn Labragolpe en la Excavación de la Liga de Expedicionarios, en El Cabo de Tuercespina.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante Bronwyn Labragolpe en la Excavación de la Liga de Expedicionarios.$b$bLa expedición de la Liga de Expedicionarios necesita tu ayuda para proteger su excavación y sus descubrimientos de los ogros que merodean por la zona. Viaja al sur desde el Norte de la Vega de Tuercespina y sigue el camino hasta la Excavación de la Liga de Expedicionarios.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28703, 'esMX', 'Entra en mi túmulo', 'Mata 10 trepadores Acechofrío y 5 perforadores Acechofrío.', 'Sigo sin tener ni idea de dónde han salido estos bichos. Mi teoría es que el Cataclismo habrá agitado algunos nidos subterráneos de los que no estábamos al corriente.$b$b¡Pero es inútil distraerse con eso cuando hay que matarlos!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Rinno Flamacortina. Zona: Túmulo de Ban\'Thallow, Cuna del Invierno.', 0),
(28704, 'esMX', '¡La orden del Jefe de Guerra: El Cabo de Tuercespina!', 'Preséntate ante Sassy Malallave en el Escondrijo Malallave, en El Cabo de Tuercespina.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Sassy Malallave en el Escondrijo Malallave. Necesita tu ayuda para lidiar con los piratas y los nagas que han invadido la selva.$b$bPara viajar al Escondrijo Malallave, dirígete al sur desde el Norte de la Vega de Tuercespina y busca el pueblo que hay al suroeste de la Arena Gurubashi.$b$b¡El destino aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28705, 'esMX', '¡La orden del Jefe de Guerra: Terrallende!', 'Preséntate ante el teniente general Orion en Los Peldaños del Destino, en la Península del Fuego Infernal.', 'Por la presente se les ordena a todos los miembros aptos de la Horda a que se presenten ante el teniente general Orion en los Peldaños del Destino.$B$BSe requieren sus habilidades para luchar contra la presencia de la Legión Ardiente en los restos destrozados de Terrallende.$B$BVayan al Circo de las Sombras de Orgrimmar y utilicen el portal que hay cerca de los instructores de magos para entrar en la Península del Fuego Infernal.$B$B¡El destino llama!', '', '', '', '', '', '', '', '', '', '', 0),
(28706, 'esMX', 'A todo gas', 'Llévale la caja de fumigadores matabichos a Remma Flamacortina dentro del Túmulo de Ban\'Thallow.', 'Mis hermanas ya se han adentrado por el túmulo para lidiar con los bichos, y están empezando a superarlas. Yo digo que es hora de gasear todo este sitio.$b$bCoge estos fumigadores. No los actives tú $gsolo:sola;, hace falta ser un profesional altamente cualificado y con sentido de la oportunidad. Tú busca a mis hermanas y dáselos.$b$bLa que está más cerca de la entrada debería ser Remma. Baja por el pasillo y sigue a la derecha al bajar por la rampa.', '', '', '', '', '', '', '', '', '', '', 0),
(28707, 'esMX', 'Rocíalos de nuevo', 'Llévale la caja de fumigadores matabichos a Marcy Flamacortina, dentro del Túmulo de Ban\'Thallow.', 'Voy a ir organizando esto.$b$bLa siguiente es Marcy, más adelante. Sigue por este pasillo y búscala en la siguiente cámara principal.', '', '', '', '', '', '', '', '', '', '', 0),
(28708, 'esMX', 'Se busca héroe: ¡Terrallende!', 'Preséntate ante el comandante Duron en los Peldaños del Destino, en la Península del Fuego Infernal.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el comandante Duron en la Península del Fuego Infernal.$B$B¡Las tropas de expedicionarios necesitan su ayuda para derrotar a los ejércitos demoníacos de la Legión Ardiente! Utilicen el portal que hay en el nivel medio de la torre del Barrio de los Magos para viajar a los Peldaños del Destino en Terrallende.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28709, 'esMX', 'Se busca héroe: ¡Rasganorte!', 'Preséntate ante el oficial de reclutamiento Blythe en la Fortaleza Denuedo, en la Tundra Boreal.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse ante el oficial de reclutamiento Blythe en la Fortaleza Denuedo, en la Tundra Boreal.$b$b¡La Expedición de Denuedo necesita tu ayuda para mantener las fuerzas de la Plaga bajo control y proteger las tierras civilizadas! Ve al muelle de Ventormenta y toma el barco que va al norte, a la Fortaleza Denuedo.$b$b¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28710, 'esMX', 'Rocíame otra vez', 'Llévale la caja de fumigadores matabichos a Sana Flamacortina en el Túmulo de Ban\'Thallow.', '¡Rinno ya podría haber enviado algo más que $gun:una; simple $r para echarnos una mano aquí abajo! Vaya cara...$b$bVoy a ir organizando esto. Sigue hacia el norte, desde esta sala, y busca a Sana. Lo más probable es que se haya perdido en la última cámara, así que busca los pasajes laterales cuando llegues.', '', '', '', '', '', '', '', '', '', '', 0),
(28711, 'esMX', '¡La orden del Jefe de Guerra: Rasganorte!', 'Preséntate ante el oficial de reclutamiento Grito de Guerra en el Bastión Grito de Guerra, en la Tundra Boreal.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el oficial de reclutamiento Grito de Guerra en el Bastión Grito de Guerra.$b$bLa Ofensiva Grito de Guerra necesita tu ayuda para superar la amenaza continua de la Plaga de no-muertos.$b$bMonta en un zepelín en la torre de zepelín este de Orgrimmar hasta el Bastión Grito de Guerra y preséntate ante el oficial de reclutamiento.$b$b¡El destino te aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28712, 'esMX', 'Llega la reina de dragones', 'Busca a Lirastrasza en el Círculo de la Vida en las Tierras Altas Crepusculares.', 'Hola, $r. Ojalá nos hubiéramos encontrado en mejores circunstancias. El mundo pende de un hilo, y todo lo que tejieron los titanes puede estar en peligro.$B$BMe causa gran pesar, pero mi sentencia es definitiva. Alamuerte, la horrible criatura que antaño fue Guardián de la Tierra y mi amigo, debe ser destruido.$B$BHe preparado un lugar en la cima de las Tierras Altas, al oeste del Reducto Bermellón, donde puedo procurar su caída. Busca el Círculo de la Vida y, dentro de él, habla con Lirastrasza. Me reuniré contigo allí.', '', '', '', '', '', '', '', '', '', '', 0),
(28713, 'esMX', 'El equilibrio de la naturaleza', 'Mata 6 sables de la noche jóvenes.', 'Saludos, $n. Me llamo Ilthalaine. Mi misión en Cañada Umbría es entrenar a $gtodo:toda; $c joven como tú para asegurar que se mantenga el equilibrio de la naturaleza.$b$bLas lluvias primaverales han sido especialmente duras este año y han provocado que algunas bestias del bosque medren y otras sufran. Por desgracia, la población de sables de la noche ha crecido demasiado y amenazan con devastar las demás especies si no reducimos su número.$b$bVe, joven $c, y reduce la población de sables para que la armonía de la naturaleza se conserve.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ilthalaine. Zona: Cañada Umbría.', 0),
(28714, 'esMX', 'Corrupción de musgovil', 'Recoge 6 puñados de musgovil de los grellines al oeste de Ilthalaine.', 'Das la impresión de saber lo que haces. A lo mejor puedo encargarte algo más importante.$b$bComo bien sabes, se suponía que la corrupción de Teldrassil se había eliminado, pero algo permanece. Las criaturas no se han calmado y todo tipo de problemas aún nos asolan.$b$bQuiero que te encargues de los grellines que se han reunido al oeste, y ya que estás regístralos en busca de musgovil. Me ayudará a averiguar de dónde proviene esta corrupción.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Ilthalaine. Zona: Cañada Umbría.', 0),
(28715, 'esMX', 'Ladrones demoníacos', 'Recupera las bolsas robadas de Melithar cerca de los grellines del oeste.', '¡Malditos grells! Han vuelto a robar de nuestras despensas.$b$bSi no te importa echarme una mano, seguro que tienen las bolsas que me han robado en sus campamentos al oeste. Te recompensaré si me lo traes de vuelta.', '', '', '', '', '', '', '', '', '', 'Vuelve con Melithar Corzocelada, en Aldrassil. ', 0),
(28716, 'esMX', 'Se busca héroe: ¡Tierras Altas Crepusculares!', 'Habla con el rey Varian Wrynn en el Castillo de Ventormenta en Ventormenta.', 'Por orden de su alteza real, el rey Varian Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse en la Sala del Trono, en el Castillo de Ventormenta.$B$BWrynn necesita un héroe digno de confianza y que haya demostrado su valía para una misión de la mayor importancia.$B$BEl Castillo de Ventormenta está situado en la zona este de la Ciudad de Ventormenta.$B$B¡Por la gloria y el honor de la Alianza!', '', '', '', '', '', '', '', '', '', '', 0),
(28717, 'esMX', '¡La orden del Jefe de Guerra: Tierras Altas Crepusculares!', 'Informa a Vol\'jin en el Fuerte Grommash en Orgrimmar.', 'Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante Vol\'jin en el Fuerte Grommash.$B$BEl Jefe de Guerra necesita su ayuda para preparar el glorioso ataque en las Tierras Altas Crepusculares contra nuestros dos enemigos: la Alianza y el Martillo Crepuscular.$B$BReúnanse con el Jefe de Guerra en el Fuerte Grommash en el centro del Valle de la Fuerza en Orgrimmar.$B$B¡El destino aguarda!', '', '', '', '', '', '', '', '', '', '', 0),
(28718, 'esMX', 'Donde hay humo, hay carne deliciosa', 'Busca a Jez Buenazampa en el Foso de Humo de Buenazampa en Cuna del Invierno.', 'Cuéntame, $c... ¿Te gusta la carne? Aún mejor, ¿te gusta el dinero?$b$bTengo un primo segundo que se está haciendo de oro en el negocio de la carne congelada. Se ha procurado un foso de humo al norte y busca ayuda para cazar todas esas alimañas peligrosas que siempre acaban estando tan ricas.$b$bLos carnívoros pagan bien, colega. Estoy demasiada involucrada en este túmulo (¿en qué estaba yo pensando?), así que lo mejor es que le pase la oportunidad a $gun buen:una buena; $r como tú.$b$bSe llama Jez. Ve al noreste, ¡y dirígete hacia el humo!', '', '', '', '', '', '', '', '', '', '', 0),
(28719, 'esMX', 'Un poco fuerte', 'Mata 15 aplastadores Dentoesquirla.', 'A muchas personas la carne de los osos Dentoesquirla les parece demasiado fuerte. Yo no estoy de acuerdo, aunque no soy quién para juzgar los gustos de los demás.$b$bEso sí, los aplastadores Dentoesquirla (sus primos de pelaje marrón, al sur) tienen una carne mucho más tierna, especialmente en las zarpas. Y he oído que el morro también se considera una delicia.$b$bProsigue con tu caza, $n. Veamos si puedes conseguir unos aplastadores para Francis.', '', '', '', '', '', '', 'Francis Morcott', 'No está nada mal este oso.', 'Francis Morcott', 'Vuelve con: Francis Morcott. Zona: Foso de Humo de Buenazampa, Cuna del Invierno.', 0),
(28721, 'esMX', 'Ponte en su pellejo durante un tiempo', 'Escolta al prisionero de la Fortaleza de Farson hasta lugar seguro. La fortaleza se encuentra en el extremo norte de la isla.', 'Hemos mandado al menos a 3 grupos de reconocimiento diferentes a la Fortaleza de Farson durante las últimas semanas. Por desgracia, ninguno ha vuelto con información.$B$BEn este momento, lo único que podemos esperar es que los tengan retenidos como prisioneros. Necesito que te infiltres en la fortaleza y que rescates a nuestros soldados. No será fácil, $n, pero si alguien puede ayudarnos $gese:esa; eres tú.', 'Prisionero de Farson escoltado', '', '', '', '', 'Prisionero de Farson escoltado', 'Prisionero de Farson', '', '', 'Preséntate de nuevo ante el comandante Larmash en los Dominios Grito Infernal cuando termines.', 0),
(28722, 'esMX', 'Yetifobia', 'Asusta a Legacki con el yeti mecánico de Umi.', '¡Ya está todo listo, $n!$b$bLe he dicho a mi amiga Legacki que tengo una sorpresa para ella. ¡Ahí entras tú!$b$bTe voy a dar mi yeti mecánico y tendrás el honor de usarlo para darle una sorpresa. Está al otro lado de Vista Eterna, cerca de la posada.$b$bAcércate a ella y enciende el yeti... ¡Yo estaré mirando desde aquí!', '', 'Asusta a Legacki', '', '', '', '', '', '', '', 'Vuelve con: Umi Risitas. Zona: Vista Eterna, Cuna del Invierno.', 0),
(28723, 'esMX', 'Sacerdotisa de la Luna', 'Habla con Dentaria Claro de Plata entre los dos estanques del centro de Cañada Umbría.', 'Ahora que has practicado tu nueva facultad, a lo mejor te apetece ayudarnos a investigar la corrupción que asola Cañada Umbría.$b$bDentaria Claro de Plata, sacerdotisa de la Luna, se ha ofrecido a ayudarnos. La encontrarás entre dos estanques justo al norte de nuestro gran árbol. Rodea el árbol para llegar hasta ella y ofrécele toda la ayuda que puedas, joven $c.', '', '', '', '', '', '', '', '', '', '', 0),
(28724, 'esMX', 'El antídoto de Iverron', 'Recoge 7 lirios alunados.', 'Nuestro amigo Iverron ha caído víctima del veneno de las arañas Tejemadera cercanas. Puedo tratarlo para evitar que su estado empeore, pero necesito que alguien recoja un ingrediente para preparar el antídoto.$b$bAlrededor de los estanques crecen lirios alunados. Son flores con fuertes propiedades curativas y puedo combinarlas con los ingredientes que ya tengo para devolverle la salud a Iverron.$b$b¿Me harías el favor de recogerlas? Deberías poder ver muchas cerca de la orilla del agua.', '', '', '', '', '', '', '', '', '', 'Vuelve con Dentaria Claro de Plata entre los dos estanques de la zona norte de Cañada Umbría.', 0),
(28725, 'esMX', 'La protectora de los bosques', 'Busca a la dríade Tarindrella en la Gruta Narácnida, en el extremo norte de Cañada Umbría.', 'Debo pedirte algo más peligroso. El susurro de los espíritus del bosque me ha traído extrañas nuevas.$B$BLa misteriosa protectora de los bosques, Tarindrella, ha regresado a Cañada Umbría. La presencia de la dríade en estos bosques no se conocía desde antes de la bendición de Teldrassil. Si ha viajado de nuevo hasta estas tierras, entonces sin duda algo va mal.$B$BBusca a Tarindrella en la Gruta Narácnida, al norte. Es peligroso, pero tendremos el antídoto preparado por si acaso.', '', '', '', '', '', '', '', '', '', '', 0),
(28726, 'esMX', 'Corrupción Tejemadera', 'Mata 12 arañas Tejemadera.', 'Esperaba no tener que volver a Teldrassil con una tarea tan nefasta. Esperaba que la corrupción se hubiera eliminado para siempre. Pero quedó algo maligno.$B$BEstas arañas padecen más la corrupción que otra fauna cercana. Se están convirtiendo en un peligro para tu gente y para el bosque. Debemos reducir su número, pero lo más importante es encontrar la fuente de la corrupción que las asola.$B$BIré contigo y te ayudaré. ', '', '', '', '', '', '', '', '', '', 'Habla con: Tarindrella. Zona: Gruta Narácnida, Cañada Umbría.', 0),
(28727, 'esMX', 'Toque vil', 'Mata a Githyiss la Vil en el extremo norte de la Gruta Narácnida.', 'Si estas arañas nacen con la corrupción en las venas, entonces su madre de linaje debe ser la raíz de este mal.$b$bVayamos al extremo norte de la gruta y busquemos a Githyiss la Vil. Ella posee las respuestas que buscamos.', '', '', '', '', '', '', 'Githyiss la Vil', '', '', 'Habla con: Tarindrella. Zona: Gruta Narácnida, Cañada Umbría.', 0),
(28728, 'esMX', 'Una señal de lo que está por venir', 'Vuelve con Dentaria Claro de Plata entre los dos estanques de la zona norte de Cañada Umbría.', 'Seguiré el rastro de los Tuercepinos y encontraré la fuente de la corrupción. Si te encuentras con Athridas Manto de Oso en Dolanaar, verás que conoce muy bien los problemas que atormentan a este bosque y te podrá enseñar cómo seguir ayudando.$b$bSin duda nos volveremos a encontrar algún día. Quizás puedas ayudarme a tratar con la fuente de la corrupción, cuando la encuentre. De momento, te envío de vuelta a Dentaria para que termines con tu instrucción. Gracias por todo, $n.', '', '', '', '', '', '', '', '', '', '', 0),
(28729, 'esMX', 'Teldrassil: La corona de Azeroth', 'Llena la ampolla de cristal en la poza de la luna del noreste de Cañada Umbría.', 'Como parte de un ritual para completar tu instrucción en Cañada Umbría, debes aprender nuestra historia reciente.$b$bHay una tarea que debes realizar. Ve a la poza de la luna al noreste y llena una ampolla con sus aguas. Cuando estés allí presenciarás una visión de nuestra magia y conocerás nuestro pasado.$b$bCuando termines, tráeme el agua y te daré más instrucciones.', '', '', '', '', '', '', '', '', '', 'Vuelve con Dentaria Claro de Plata entre los dos estanques de la zona norte de Cañada Umbría.', 0),
(28730, 'esMX', 'Aguas preciosas', 'Lleva la ampolla de cristal llena a Tenaron Tormentagarre en lo alto de Aldrassil, en Cañada Umbría.', 'Tenaron Tormentagarre supervisa todo lo que sucede en esta cañada. Se encuentra en lo alto de Aldrassil.$b$bSi miras al sur, verás la parte inferior de la rampa que conduce hasta él. Sube por ella para completar tu instrucción.$b$bHa sido maravilloso conocerte, $n. Me llena de orgullo saber que entre los elfos de la noche jóvenes hay algunos tan desinteresados y llenos de vida como tú. Harás grandes cosas por nuestra gente. Harás grandes cosas por este mundo.$b$bHasta que nos volvamos a ver.', '', '', '', '', '', '', '', '', '', '', 0),
(28731, 'esMX', 'Teldrassil: La transmisión del conocimiento', 'Lleva la vasija casi llena a Corithras Furia Lunar a Dolanaar.', 'Aunque podría contarte mucho más de las Pozas de la Luna y de Teldrassil, debo dejarte ir; Corithras Furia Lunar te está esperando. He puesto el agua que has traído en esta vasija; llévasela.$B$BEstará en la Poza de la Luna de Dolanaar. Coge el camino del sur de Aldrassil al salir de Cañada Umbría y sigue los adoquines cuando el camino gira al oeste.$B$BTen cuidado, $n. Últimamente hay criaturas muy peligrosas en el bosque.', '', '', '', '', '', '', '', '', '', '', 0),
(28732, 'esMX', 'Esto solo puede significar una cosa...', 'Ve en la máquina topo de Finkle hasta la Montaña Roca Negra.', 'A Raz y a mí nos reclutaron los Guardianes de Hyjal para investigar el resurgir de Ragnaros en nuestro mundo. ¡Te puedo confirmar desde ya que ha vuelto y que está enfadado! También tenemos pruebas de que esos cultores del Martillo Crepuscular están trasladando elementales desde aquí hasta las Cavernas Roca Negra, en los Reinos del Este.$b$bRaz y yo estábamos a punto de dirigirnos hacia allá para investigar. Hay sitio para uno más en la máquina topo, si te interesa. Reúnete con nosotros en el interior y comenzaremos el viaje.', 'Llega a las Cavernas Roca Negra.', '', '', '', '', 'Llega a las Cavernas Roca Negra.', '', '', '', 'Encuentra a: Finkle Einhorn. Zona: Cavernas Roca Negra, Montaña Roca Negra.', 0),
(28733, 'esMX', 'Botánica básica', 'Sobrevive a una gigantesca oleada de zombis.', '¡SOCORRO! ¡SOCORRO! ¡Unos no-muertos frenéticos están atacando mi granja! Seguro que ese celador demente de los Campos de Lodo es el responsable de este lío. ¡Ayúdame a rechazar a los zombis!', '', 'Gigantesca oleada de zombis superada', '', '', '', '', '', '', '', 'Habla con: Brazie el Botánico. Zona: Granja de Brazie, Laderas de Trabalomas.', 0),
(28734, 'esMX', 'Un favor para Melithar', 'Habla con Melithar Corzocelada en Cañada Umbría.', 'Deberías hablar con Melithar, creo que ya ha tenido problemas con los grells.$b$bSospecho que te ofrecerá algo para guardar más cosas si le ayudas.', '', '', '', '', '', '', '', '', '', '', 0),
(28735, 'esMX', '¡A la Cámara de Incineración!', 'Mata a Machacahuesos Rom\'ogg.', '¡Era una emboscada, $n! En cuanto entramos nos atacó un ogro gordísimo llamado Machacahuesos Rom\'ogg. Raz me defendió con valentía mientras huía para esconderme. Vi cómo lo dejaban inconsciente de un golpe y se lo llevaban a rastras a un lugar que el gordo llamó "Cámara de Incineración". Creo que está al fondo de la sala, al otro lado del puente.$B$BTengo demasiado miedo para ir más lejos. Llévate mi escafandra multiusos y busca a Raz. Me comunicaré contigo mediante el casco.$b$bSi encuentras al ogro, ¡mátalo!', '', '', '', '', '', '', 'Machacahuesos Rom\'ogg', '¡Sigue a Raz!', 'Finkle Einhorn', 'Habla con: Finkle Einhorn. Zona: Cavernas Roca Negra, Montaña Roca Negra.', 0),
(28736, 'esMX', 'Fuego desde el cielo', 'Sube a la artillería confiscada y úsala para matar a 100 soldados de infantería de Schnottz.', 'Los restos de la organización de Schnottz permanecen en Ascenso del Hacedor, y han convertido la región en una zona letal para todo el que se acerca a ella.$b$bHay un montón de munición, pero sin un buen avistador, estoy disparando a ciegas.$b$bSube y échame una mano. ¡Esos soldados no van a saber por dónde les viene!', '', 'Soldados de infantería asesinados', '', '', '', '', '', '', '', 'Habla con: Nómada curtido. Zona: Precipicio del Peregrino.', 0),
(28737, 'esMX', '¿Qué es este sitio?', 'Mata a Corla, Heraldo del Crepúsculo.', '<El casco de Finkle te da un pequeño calambrazo.>$b$b¿Qué es este sitio? Parece que le están haciendo algo terrible a ese dragón abisal. ¡Transfieren la energía del dragón a esa mujer! ¡Debemos detener este ritual!$b$b¡Mata a Corla para salir de esta sala!', '', '', '', '', '', '', 'Corla, Heraldo del Crepúsculo', '¡No hay tiempo que perder! ¡Raz necesita nuestra ayuda!', 'Finkle Einhorn', 'Habla con: Finkle Einhorn. Zona: Cavernas Roca Negra, Montaña Roca Negra.', 0),
(28738, 'esMX', 'La Forja Crepuscular', 'Mata a Karsh Doblacero.', '<El yelmo de Finkle crepita con energía.>$b$b¡Maldita sea! ¡Raz no se para! ¡Es como si lo embargara una sed insaciable de venganza contra todo lo Crepuscular! Parece que para atravesar esta sala y alcanzar a Raz vamos a tener que eliminar al armero Crepuscular, Karsh Doblacero. Mátalo rápidamente, $n.', '', '', '', '', '', '', 'Karsh Doblacero', 'Raz está cerca. ¡Puedo oírlo!', 'Finkle Einhorn', 'Habla con: Finkle Einhorn. Zona: Cavernas Roca Negra, Montaña Roca Negra.', 0),
(28739, 'esMX', 'Night Elf Class Skill Tracker Quest', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(28740, 'esMX', '¿Qué ven mis ojos?', 'Mata a Bella.', '<El yelmo de Finkle suelta un grito agudo propio de una niña.>$b$b¡NO PUEDE SER! Yo... yo me quedé atrapado dentro de una de esas bestias casi un mes entero. Sí, literalmente, atrapado dentro de su estómago. ¡Si no hubiera sido por mi traje y mi casco multiusos habría muerto abrasado! ¡Mira, tiene una camada de cachorros!$b$b¡T-tienes que pararle los pies a esa cosa, $n! No podemos dejar que ni ella ni sus cachorros salgan de aquí con vida.', '', '', '', '', '', '', 'Bella', 'Esto me ahorrará unos cuantos años de terapia.', 'Finkle Einhorn', 'Habla con: Finkle Einhorn. Zona: Cavernas Roca Negra, Montaña Roca Negra.', 0),
(28741, 'esMX', 'Señor ascendiente Obsidius', 'Mata al señor ascendiente Obsidius.', '<El yelmo de Finkle suena.>$B$B¡POR MIS TUERCAS! ¡Mira este sitio! ¡¿Eso... eso son marcas de las garras de Alamuerte, en el techo?! ¿Y qué es esa criatura en el centro de la cámara?$B$BNo veo a Raz por ningún lado. ¡Encarguémonos de ese monstruo y busquemos a Raz! ', '', '', '', '', '', '', 'Lord Obsidius', '', '', 'Habla con: Finkle Einhorn. Zona: Cavernas Roca Negra, Montaña Roca Negra.', 0),
(28742, 'esMX', 'Shi-Rotam', 'Mata a Shi-Rotam.', '¡Es hora de la gran presa, colega! Shi-Rotam acecha por el norte y es el sable de hielo más grande que existe.$b$bDeberías sentirte $ghalagado:halagada;: no hay presa más fiera contra la que se pueda medir un cazador, y si vieras el dinero que me ofrecen los gourmets que quieren probar al bicho este, ¡te quedarías con la boca abierta!$b$bCuando la tengas, vuelve al campamento. No quiero extinguir toda la población de sables de hielo en un día...', '', '', '', '', '', '', 'Shi-Rotam', '', '', 'Vuelve con: Jez Buenazampa. Zona: Foso de Humo de Buenazampa, Cuna del Invierno.', 0),
(28744, 'esMX', 'Los necrófagos me tienen hasta las semillas', 'Sobrevive a 2 gigantescas oleadas de zombis.', '¡Eres $gun:una; profesional, $n! ¡$gTodo un botánico:Toda una botánica;! Escucha, tengo una nueva semilla para que la pruebes: la rocanuez. Utilízala para bloquear el paso de los no-muertos. Colócala y se pararán en seco. ¡Los no-muertos son unos estúpidos!$b$b¡Vamos a probarla!', '', 'Gigantesca oleada de zombis superada', '', '', '', '', '', '', '', 'Habla con: Brazie el Botánico. Zona: Granja de Brazie, Laderas de Trabalomas.', 0),
(28745, 'esMX', 'Deliciosos estridadores', 'Mata 15 estridadores de Cuna del Invierno.', 'Las lechuzas pequeñas están riquísimas, pero Buenazampa dice que las hay aún mayores más al sur. La gente de por aquí dice que se llaman estridadores... ¡Hacen un montón de ruido cuando se alteran!$b$bPero Buenazampa dice que son las mejores lechuzas que jamás ha probado o vendido, y yo le creo. ¿Por qué no vas a hacerte con unas cuantas mientras yo sigo discutiendo con Francis?', '', '', '', '', '', '', 'Jeb Guthrie', 'Este artilugio parlanchín no deja de confundirme.', 'Jeb Guthrie', '', 0),
(28746, 'esMX', 'Penetrar en sus defensas', 'Consigue acceder a la sala de control titánica.', '¡Allá vamos, $n!$b$bAl otro lado de esa puerta se encuentra la sala de control.$b$bEntraré rápidamente, desactivaré el mecanismo de recreación y después nos iremos a casa. Pan comido.$b$bYa ves, $gchico:chica;, es este tipo de preparación la que distingue al verdadero arqueólogo del típico cazador de tesoros.$b$bNo hay por qué agitar a las bestias sin necesidad. Lo único que se consigue es complicar las cosas...', '', 'Sala de control titánica allanada', '', '', '', '', '', '', '', 'Habla con: Brann Barbabronce. Zona: El Arca de las Luces, Cámaras de los Orígenes.', 0),
(28747, 'esMX', 'Que alguien active la bomba de calabaza', 'Sobrevive a 2 gigantescas oleadas de zombis.', '¿Alguna vez has visto una de estas?$b$b<Brazie saca una calabaza.>$b$bNo es una calabaza cualquiera, $gamigo:amiga;. Verás, cuando plantas una de estas, espera hasta que se acerca un zombi y entonces ¡CATAPÚN! Tripas de zombi por todas partes. ¡Vamos allá!', '', 'Gigantesca oleada de zombis superada', '', '', '', '', '', '', '', 'Habla con: Brazie el Botánico. Zona: Granja de Brazie, Laderas de Trabalomas.', 0),
(28748, 'esMX', 'El jardín de los muertos', 'Derrota al celador Aguaserena.', '¡ES AGUASERENA! ¡YA CASI ESTÁ AQUÍ! ¡Nos hará falta todo nuestro esfuerzo para derrotarlo! ¡Vamos allá!', '', 'Celador Aguaserena derrotado', '', '', '', '', '', '', '', 'Habla con: Brazie el Botánico. Zona: Granja de Brazie, Laderas de Trabalomas.', 0),
(28749, 'esMX', 'La batalla por Andorhal', 'Habla con el mago de guerra Erallier para que te teletransporte a Andorhal, en las Tierras de la Peste del Oeste. Luego preséntate ante Thassarian en el interior de Andorhal.', 'Acaba de llegar un grifo de las Tierras de la Peste, y trae noticias. No suena nada bien.$B$BLa ciudad de Andorhal está en mitad de una guerra a tres bandas entre los Renegados, la Alianza y la Plaga. El rey Wrynn ha apostado por un caballero de la Muerte para liderar su ataque, pero no me cabe duda de que le vendrá bien recibir toda la ayuda posible.$B$BPidieron concretamente que un $c de la Alianza participara en algunas misiones especiales. Si aceptas el cargo, vuelve a hablar conmigo y prepararé un portal.', '', '', '', '', '', '', '', '', '', 'Preséntate ante Thassarian en el interior de Andorhal, en las Tierras de la Peste del Oeste.', 0),
(28750, 'esMX', 'La batalla por Andorhal', 'Habla con el arcanista Arman para que te teletransporte a Andorhal, en las Tierras de la Peste del Oeste. Luego preséntate ante Thassarian en el interior de Andorhal.', 'Acaba de llegar un jinete del viento de las Tierras de la Peste, y trae noticias. No suena nada bien.$B$BLa ciudad de Andorhal está en mitad de una guerra a tres bandas entre los Renegados, la Alianza y la Plaga. Parece que Sylvanas se ha puesto en marcha, y, para poner las cosas más interesantes, ha puesto al mando a Koltira Tejemuerte, el caballero de la Muerte.$B$BPidieron concretamente que un $c de la Horda participara en algunas misiones especiales. Si aceptas el cargo, vuelve a hablar conmigo y prepararé un portal.', '', '', '', '', '', '', '', '', '', 'Preséntate ante Koltira Tejemuerte en el interior de Andorhal, en las Tierras de la Peste del Oeste.', 0),
(28751, 'esMX', 'Cuidar el jardín', 'Sobrevive a 2 gigantescas oleadas de zombis.', 'Aunque hemos derrotado al celador Aguaserena, sus zombis siguen vagando por el campo. Mira, ¡se acerca otra oleada! ¡Ayúdame a expulsarlos, $gviejo amigo:vieja amiga;! ¡Adelante!', '', 'Gigantesca oleada de zombis superada', '', '', '', '', '', '', '', 'Habla con: Brazie el Botánico. Zona: Granja de Brazie, Laderas de Trabalomas.', 0),
(28753, 'esMX', 'A lo bestia', 'Brann Barbabronce quiere que mates a Isiset, Ammunae, Setesh y Rajh.', '¡Maldita sea!$b$b¡Alguien ha corrompido todo el sistema! Me va a ser imposible acceder al almacén principal desde esta consola.$b$bVamos a tener que hacerlo a lo bestia, $gchico:chica;. Espero que tú y tus amigos estén a la altura de la batalla.$b$bHabrá cuatro guardianes en el nivel superior de este lugar. Y yo no podré utilizar este disco hasta que estén... eh, fuera de línea, digamos.', '', 'Isiset asesinada', 'Ammunae asesinado', 'Rajh asesinado', 'Setesh asesinado', '', '', '', '', 'Habla con: Brann Barbabronce. Zona: Cámara superior de las Cámaras de los Orígenes.', 0),
(28755, 'esMX', 'Crónicas de la Mano de Plata', 'Recupera un volumen perdido de las Crónicas de la Mano de Plata en Stratholme.', '¿Sabes quiénes eran los caballeros de la Mano de Plata? Fueron los primeros paladines de la Luz, y de sus filas surgieron caballeros que acabarían por unirse a El Alba Argenta o a la Cruzada Escarlata. Aunque muchos se han descarriado, aún poseen valiosas reliquias de la Mano de Plata.$b$bEn lo más profundo de Stratholme, bajo la atenta mirada del instructor Galford, perduran varios volúmenes de las Crónicas de la Mano de Plata. Todo volumen que recuperes sería una contribución digna para la nueva Capilla de la Esperanza de la Luz.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lord Raymond George. Zona: Capilla de la Esperanza de la Luz.', 0),
(28756, 'esMX', 'Aberraciones de hueso', 'Mata a Traquesangre en el Osario de Scholomance.', 'En vida, mis hermanos y yo luchamos contra todas las fuerzas de la Plaga, pero a quien más despreciábamos era a los nigromantes. No les bastaba con resucitar a nuestros camaradas muertos y enviarlos contra nosotros; no, creaban viles gólems de hueso con guadañas en lugar de manos.$B$BEsas aberraciones mataron a muchos de mis hermanos, y sin embargo no pudimos destruirlas a todas. Te ruego, $n, que lleves a cabo la misión de los caídos. Aventúrate en el Osario de Scholomance y mata a las más grandes y peligrosas de esas abominables criaturas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Lord Raymond George. Zona: Capilla de la Esperanza de la Luz.', 0),
(28757, 'esMX', '¡Rechazar el ataque!', 'Mata a 6 huargos Roca Negra.', 'Así que eres $gel nuevo:la nueva; recluta de Ventormenta, ¿eh? Soy el alguacil McBride, comandante de este cuartel. Me alegra tenerte a bordo...$B$B<McBride mira unos papeles.>$b$b$n. Es $n, ¿verdad?$B$BLlegas justo a tiempo. Los orcos Roca Negra han conseguido colarse en Villanorte a través de una brecha en las montañas. Mis soldados están haciendo todo lo que pueden para rechazarlos, pero me temo que pronto se verán superados.$B$B¡Dirígete al noroeste, al bosque y mata a los atacantes huargos Roca Negra! ¡Ayuda a mis soldados!', '', '', '', '', '', '', 'Huarguerrero Roca Negra', '', '', 'Vuelve con: Alguacil McBride. Zona: Abadía de Villanorte, Bosque de Elwynn.', 0),
(28758, 'esMX', 'Una batalla a vida o muerte', 'Monta en un vanguardia Bermellón. Mata a 8 dracos de las Sombras Crepusculares.', '¡Alexstrasza y Alamuerte se han dirigido a los cielos sobre Grim Batol! Su plan sigue adelante, la reina de los dragones está junto al Círculo de la Vida que había preparado. Tendremos que apoyarla con todas nuestras fuerzas.$B$B¡Date prisa! Súbete a uno de los vanguardias Bermellón que hay detrás de mí.$B$BSi vemos a algún draco Crepuscular ayudando a Alamuerte, tendremos que matarlo. ¡Monta, rápido!', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Calen. Zona: Base de Grim Batol, Tierras Altas Crepusculares.', 0),
(28759, 'esMX', 'Leones por corderos', 'Mata a 8 espías Roca Negra.', 'Los orcos invasores no son tontos. Nos están estudiando, quieren asegurarse de que cuando ataquen tendrán la ventaja.$B$BEn el bosque, al noroeste, están los espías Roca Negra. Nos espían usando catalejos, observando cada uno de nuestros movimientos... esperando. ¡Quiero que lleves la lucha a su campo!$B$B¡Mata a los espías Roca Negra! ¡Debemos dejarles claro que sabemos que nos están observando y que estamos preparados!', '', '', '', '', '', '', 'Espía Roca Negra', '', '', 'Vuelve con: Alguacil McBride. Zona: Abadía de Villanorte, Bosque de Elwynn.', 0),
(28760, 'esMX', 'Venganza para Orsis', 'Mata a Asaad.', 'La gran ciudad de Orsis fue atacada por los ejércitos del aire.$b$bNos hicieron prisioneros, nosotros tuvimos suerte.$b$bLa mayoría murieron, atrapados bajo las asfixiantes arenas del desierto.$b$bAsaad, el califa de Al\'Akir, ordenó el ataque... Y deberá pagarlo con su vida.', '', '', '', '', '', '', 'Assad', '', '', 'Vuelve con: Itesh. Zona: La Cumbre del Vórtice.', 0),
(28761, 'esMX', 'Honrar la llama', '', '', '', '', '', '', '', '', '', '', '', '', 0),
