(29742, 'esMX', 'El ancestro Menkhaf', '', '', '', '', '', '', '', '', '', '', '', '', 0),
(29760, 'esMX', 'Luchador de fosa', 'Habla con Korgol Trituracráneos en la Feria de la Luna Negra.', 'Debe haber algo mejor para un maestro luchador de fosa que esto...$b$bQuizás tenga alguna idea Korgol Trituracráneos, encargado del combate a muerte de la Feria de la Luna Negra.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Korgol Trituracráneos. Zona: Combate a muerte de la Feria de la Luna Negra.', 0),
(29761, 'esMX', 'Maestro luchador de fosa', '', '', '', '', '', '', '', '', '', '', '', 'Vuelve con: Korgol Trituracráneos. Zona: Feria de la Luna Negra.', 0),
(29763, 'esMX', 'Robar su trueno', 'El defensor Mordun te ha pedido que consigas la cabeza de Ingvar el Desvalijador.', 'Los vrykuls son temibles en una pelea. Por lo visto ansían morir en combate. Con su número y su ferocidad, estamos condenados, simple y llanamente.$B$BSin embargo hay uno al que estiman, responde al nombre de Ingvar. Acaba con él y asestarás un duro golpe a su moral.', '', '', '', '', '', '', 'Ingvar el Desvalijador', '', '', 'Vuelve con: Defensor Mordun. Zona: Interior de la Fortaleza de Utgarde.', 0),
(29764, 'esMX', 'Desarme', 'El defensor Mordun quiere que robes 5 armas vrykul.', 'Hazme caso, $gchico:chica;, ¡las armas vrykul son muy desagradables! Aparentemente bien equilibradas, terriblemente afiladas... simplemente mortales.$B$B¡Necesito que robes algunas de sus armas antes de que carguen contra nosotros!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Defensor Mordun. Zona: Interior de la Fortaleza de Utgarde.', 0),
(29801, 'esMX', 'Demuestra lo que vales', 'Róbale un anillo descodificador de criptomántico a Hagara la Vinculatormentas en El Ojo de la Eternidad, en el interior del encuentro de banda Alma de Dragón. ', '¡Hola, $n! Te has ganado la reputación en el Vuelo por tener... digamos... "dedos ágiles".$b$bNecesitamos a alguien con tus habilidades para un asunto de lo más delicado. Antes de desvelarte nada más, necesito saber si eres la persona adecuada para este trabajo.$b$bCuando el curso de la batalla te lleve a El Ojo de la Eternidad, necesitaré que robes a Hagara la Vinculatormentas para recuperar un anillo descodificador de criptomántico. ¿Aceptas la misión?', '', '', '', '', '', '', '', '', '', 'Entrega el anillo a: Lord Afrasastrasz. Zona: Templo del Reposo del Dragón, interior del encuentro de banda Alma de Dragón.', 0),
(29802, 'esMX', 'Un mensaje escondido', 'Recarga tu anillo descodificador de criptomántico y úsalo para descodificar la clave chamuscada de Corastrasza.', 'Corastrasza, actualmente destinada al Reducto Bermellón, en las Tierras Altas Crepusculares, interceptó un mensaje cifrado de gran importancia. Es mejor que te explique ella la situación por completo, ¡pero necesitamos tu experiencia para descifrar el código!$B$BLlévale tu anillo descodificador a un taumaturgo etéreo de tu capital; él sabrá cómo recargarlo. Consigue la clave codificada de Corastrasza y usa el anillo para descodificársela. ¡Date prisa! El tiempo es oro...', '', 'Anillo descodificador recargado', 'Hazte con la clave chamuscada', '', '', '', '', '', '', 'Entrega la clave resuelta a: Corastrasza. Zona: Reducto Bermellón, Tierras Altas Crepusculares.', 0),
(29803, 'esMX', 'El informador del Rey Exánime', 'El defensor Mordun del interior de la fortaleza de Utgarde quiere que mates al príncipe Keleseth.', 'El príncipe Keleseth sirve de vista y oído a Arthas en el Fiordo.$b$b¡No me gusta ni un pelo!$b$bVe y enséñale lo que vale un peine. Le harás un favor al mundo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Defensor Mordun. Zona: Interior de la Fortaleza de Utgarde.', 0),
(29807, 'esMX', 'Muerte al rey traidor', 'El reivindicador A\'zak de Azjol-Nerub te ha asignado la misión de derrotar a Anub\'arak. Debes volver con A\'zak cuando consigas el caparazón de Anub\'arak roto.', 'Anub\'arak, el rey traidor, habita en el otrora orgulloso reino de Azjol-Nerub.$b$bHa tergiversado y pervertido nuestra tierra natal hasta convertirla en el pozo de mugre que es hoy en día. Dirige un ejército de nerubianos no-muertos que han jurado lealtad al Rey Exánime.$B$BAcaba con su reinado.', '', '', '', '', '', '', 'Anub\'Arak', '', '', 'Vuelve con: Reivindicador A\'zak. Zona: Azjol-Nerub.', 0),
(29808, 'esMX', '¡No olvides de los huevos!', 'El reivindicador A\'zak de Azjol-Nerub quiere que destruyas 6 huevos de la Plaga nerubianos.', 'Por todo Azjol-Nerub, los nerubianos plagados incuban cuidadosamente los huevos que pronto se abrirán y les proporcionarán aún más miembros que se alzarán y asesinarán.$b$bLos huevos se han contaminado con magia demoníaca. Nuestra única opción es eliminarlos.', '', 'Huevos de la Plaga nerubianos destruidos', '', '', '', '', '', '', '', 'Vuelve con: Reivindicador A\'zak. Zona: Azjol-Nerub.', 0),
(29810, 'esMX', 'Los ignotos', 'Kilix el Desenmarañador en El Foso de Narjun quiere que mates al heraldo Volazj y a los tres Olvidados que le acompañan en Ahn’’Kahet.', 'Mi pueblo iba cavando cada vez más hondo a medida que iban perdiendo terreno en su lucha contra los no-muertos. Con la desesperación cavaron demasiado hondo.$B$BSin avisar, la voluntad de los viejos dioses se nos presentó evidente con la llegada de unas criaturas conocidas como los ignotos.$B$BAl final, no podíamos luchar en dos frentes de enemigos tan poderosos. Nuestra desgracia nos costó la guerra contra los no-muertos y, al final, nuestro hogar.$B$BEntra en Ahn’’kahet, $c, y limpia nuestro antiguo hogar de estas atrocidades ignotas.', '', 'Los Olvidados aniquilados', 'Heraldo Volazj derrotado', '', '', '', '', '', '', 'Vuelve con: Kilix el Desenmarañador. Zona: El Foso de Narjun, Cementerio de Dragones.', 0),
(29811, 'esMX', 'El dije del Vigía de las puertas', 'El reivindicador A\'zak de Azjol-nerub quiere que recuperes el dije del Vigía de las puertas de Krik\'thir, el Vigía de las puertas.', 'Krik\'thir, guardián de las puertas de Azjol-Nerub, no era un traidor.$b$bCayó en la guerra de la Araña defendiendo nuestro hogar de la Plaga.$b$bPor su condición, poseía la llave del imperio escondido. Me gustaría que la recuperases para poder devolvérsela a su pueblo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Reivindicador A\'zak. Zona: Azjol-Nerub.', 0),
(29825, 'esMX', 'Adiós al maestro', 'El vidente Ixit de Ahn\'kahet te ha encomendado el asesinato del ancestro Nadox.', 'Una vez llamé maestro al ancestro Nadox.$b$bTodo eso cambió para siempre cuando me vi obligado a verlo asesinar sin piedad a mis amigos y a mi familia como un sirviente de los condenados.$b$bEncuéntralo en las profundidades y hazle pagar por sus crímenes, $r.', '', '', '', '', '', '', '', 'Bien hecho.', 'Vidente Ixit', 'Vuelve con: Vidente Ixit. Zona: Ahn\'kahet.', 0),
(29826, 'esMX', 'Reclamar Ahn\'kahet', 'El vidente Ixit, en Ahn\'Kahet, quiere que mates a 3 ojos de Taldaram, a un muelehuesos y al príncipe Taldaram.', 'Para mantenerse a salvo de los moradores de las heladas profundidades, el príncipe Taldaram y su ejército de la Plaga usan los mismos resguardos que usábamos nosotros para ocultar nuestro imperio.$B$BDesactiva los resguardos y acaba con los miembros de la Plaga que los protegen. Mis fuerzas ayudarán a los nativos a acabar con el resto.', '', '', '', '', '', '', 'Vidente Ixit', 'Tengo que pedirte un favor más.', 'Vidente Ixit', 'Vuelve con: Vidente Ixit. Zona: Ahn\'kahet.', 0),
(29828, 'esMX', 'El pavor de la Plaga', 'Kurzel, en la Fortaleza de Drak\'Tharon quiere que mates al rey Dred y le traigas su diente.', 'Uno de los trols Drakkari que escapó me habló de un gran rey raptor, Dred, que era inmune a la Plaga.$B$BSi encuentras al rey Dred y me traes uno de sus dientes, tal vez pueda convertirlo en un arma.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Kurzel. Zona: Fortaleza de Drak\'Tharon.', 0),
(29829, 'esMX', 'La discreción es la clave', 'Rhonin quiere que vayas al Bastión Violeta en Dalaran y que hables con la teniente Sinclari.', 'Escúchame, $r.$B$BAcaban de informarme sobre un incidente en el Bastión Violeta. ¡Parece ser que los azules están lanzando un ataque a gran escala para invadir Dalaran!$B$BNecesito que vayas a la prisión y hables con la teniente Sinclari ahora mismo. Ella te dará los detalles.$b$bEso no es todo. Necesito que lleves el tema con la máxima discreción. Si es posible, no hay que alarmar a los ciudadanos de Dalaran. ¿Está claro?$b$bMuy bien, ya puedes irte.', '', '', '', '', '', '', '', '', '', '', 0),
(29830, 'esMX', 'Contención', 'La teniente Sinclari de El Bastión Violeta quiere que pongas fin a las fuerzas invasivas del dragón Azul. Habla con ella de nuevo cuando Cianigosa esté muerta.', 'Mis fuerzas están para el arrastre y los siervos de Malygos no hacen más que atacar.$b$bMe temo que aún queda lo peor.$b$bDebes tomar partido hasta que llegue su líder, Cianigosa. Solo su muerte detendría la invasión y salvaría Dalaran.$b$bHabla conmigo cuando estés $glisto:lista;.', '', 'Cianigosa asesinada', '', '', '', '', '', '', '', 'Vuelve con: Teniente Sinclari. Zona: El Bastión Violeta.', 0),
(29833, 'esMX', 'Negocios inconclusos', 'Har\'koa quiere que hables con Tol\'mar en Gundrak.', 'Aunque es verdad que el profeta de Akali ya no es un problema para este mundo, aún queda trabajo por hacer.$B$BLa mayor parte de la sangre de Akali le ha dado poder a otro, y es él quien representa un auténtico peligro.$B$BRápido, $n, ve a Gundrak y habla con Tol\'mar. El podrá darte más indicaciones para esta causa.', '', '', '', '', '', '', '', '', '', '', 0),
(29834, 'esMX', 'Gal\'darah debe pagar', 'Tol\'mar quiere que mates a Slad\'ran, a Moorabi y a Gal\'darah en Gundrak.', 'Debe de ser lo más horrible que he vih\'to en mi vida. El gran Akali asesinado delante de mis ojos. Horrible...$B$BMi trabajo consih\'te solo en observar. ¡Pero no puedo aguantar eh\'to! ¡Gal\'darah y sus seguidores tienen que pagar!$B$BVenga la mueh\'te de Akali, colega. Es lo correcto.', '', '', '', '', '', '', 'Gal\'darah', '', '', 'Vuelve con: Tol\'mar. Zona: Gundrak.', 0),
(29835, 'esMX', 'Gal\'darah debe pagar', 'La cronista Bah\'Kini quiere que mates a Slad\'ran, a Moorabi y a Gal\'darah en Gundrak.', 'Han asesinao al gran Akali, $r.$B$BMi misión en la vida es tomar nota, no luchar. ¡Pero no puedo aguantar eh\'to! ¡Gal\'darah y sus seguidores tienen que pagar!$B$BVenga la mueh\'te de Akali, colega. Es lo correcto.', '', '', '', '', '', '', 'Gal\'darah', '', '', 'Vuelve con: Cronista Bah\'Kini. Zona: Gundrak.', 0),
(29836, 'esMX', 'Probando, probando', 'To\'kini quiere que hables con Bah\'kini en Gundrak.', 'Se han eh\'tado escuchando sonidos aterradores de Gundrak. Cada vez son más altos y más frecuentes.$B$BMi antigua estudiante eh\'tá grabando los eventos desde su pueh\'to en el interior de Gundrak. ¿Quizás tú tengas tiempo para ver cómo le va?', '', '', '', '', '', '', '', '', '', '', 0),
(29838, 'esMX', 'Único', 'La cronista Bah\'Kini quiere que recuperes una pieza del coloso Drakkari en Gundrak.', 'A primera vih\'ta, eh\'to parece la vieja hih\'toria: trols jugando con poderes prohibidos y deh\'truyendo a los mismos seres a los que deberían eh\'tar adorando.$B$BSi es cieh\'to lo que he oído, tienen un gólem eh\'pecial, ¡uno como no se ha creado nunca!$B$BTráeme una pieza de ese gólem pa\' eh\'tudiah\'la.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Cronista Bah\'Kini. Zona: Gundrak.', 0),
(29839, 'esMX', 'Único', 'Tol\'mar quiere que recuperes una pieza del coloso Drakkari en Gundrak.', 'Todo eh\'te lío se podría haber evitado si los Drakkari hubieran adorado a los dioses en vez de deh\'truih\'los.$B$BHe oído que tienen un gólem eh\'pecial, uno imbuido con poderes prohibidos.$B$BTráeme una pieza de ese gólem pa\' que podamos aprender de nueh\'tros hermanos y hermanas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Tol\'mar. Zona: Gundrak.', 0),
(29840, 'esMX', 'Para la posteridad', 'La cronista Bah\'Kini, en Gundrak, quiere que recojas 6 tablillas de historia Drakkari.', 'Gundrak eh\'tá condenado. Sabes que es verdad.$B$BSi tienes el valor suficiente, busca tablillas de historia pa\' averiguar qué llevó al imperio Drakkari a tan aciago deh\'tino.$B$BPuede que algún día podamos reh\'tituir su antigua gloria.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Cronista Bah\'Kini. Zona: Gundrak.', 0),
(29844, 'esMX', 'Para la posteridad', 'Tol\'mar, en Gundrak, quiere que recojas 6 tablillas de historia Drakkari.', 'La tierra de los trols de hielo no es más que la sombra de su antigua gloria.$B$BSi tienes el valor suficiente, busca tablillas de historia pa\' averiguar qué llevó al imperio Drakkari a tan aciago deh\'tino.$B$BPuede que algún día podamos entregah\'le eh\'ta tierra a una nueva generación de trols de hielo.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Tol\'mar. Zona: Gundrak.', 0),
(29847, 'esMX', 'Cazar al ladrón', 'Infíltrate en la Mansión Ravenholdt y localiza el huevo de dragón Negro perdido.', 'Justo detrás de esta cueva se erige la Mansión Ravenholdt. ¡Tienes que entrar sin que te vean!$b$b<Mostrasz te lanza un encantamiento.>$b$bEso es, así te tendré $gvigilado:vigilada; y podré comunicarme contigo cuando te adentres en el recinto. Cuélate en esa mansión, localiza el huevo y que no te pillen...', '', 'Huevo localizado', '', '', '', '', '', '', '', 'Sigue a Wrathion escaleras arriba y habla con él. Zona: Mansión Ravenholdt, Laderas de Trabalomas.', 0),
(29848, 'esMX', 'El vigía melancólico', 'Kaldir Temeferro de las Cámaras de Piedra te ha pedido que entierres a la Doncella de Pena y recojas una lágrima de cristal pesarosa.', 'Con mucho gusto daría mi vida por los Creadores o sus creaciones.$b$bSin embargo, desde la traición de Loken, parece que todo Ulduar se ha vuelto de espaldas al mundo. Alguien en especial, la Doncella de Pena, parece sufrir una gran agonía por las nuevas órdenes.$b$bTe ruego que la entierres y me traigas una de sus lágrimas.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Kaldir Temeferro. Zona: Cámaras de Piedra.', 0),
(29850, 'esMX', 'Ensamblajes corruptos', 'Kaldir Temeferro de las Cámaras de Piedra te ha pedido que mates a 3 gigantes Runa Oscura y a Krytallus.', 'Los enanos férreos están ocupados desenterrando enormes ensamblajes de piedra que, me temo, utilizarán como poderosas armas.$b$b¡Derrota a su sobrestante Krystallus y a sus gigantes Runa Oscura que ya merodean por las salas antes de que sea demasiado tarde!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Kaldir Temeferro. Zona: Cámaras de Piedra.', 0),
(29851, 'esMX', 'Campeón del torneo', 'El alto señor Tirion Vadín te ha encomendado que completes la Prueba del Campeón.', 'Con este torneo nos acercamos aún más a nuestro enfrentamiento final con el Rey Exánime.$B$B$n, lucha con valor y con honor. Todos los luchadores que hay aquí se han reunido por el bien común.$B$B¡Juntos, detendremos a Arthas!', '', '', '', '', '', '', 'Alto señor Tirion Vadín', 'Haces que tenga grandes esperanzas en el éxito de esta campaña.', 'Alto señor Tirion Vadín', '', 0),
(29860, 'esMX', 'Diametralmente opuesto', 'El heraldo de tormenta Eljrrin de las Cámaras de Relámpagos quiere que derrotes a Volkhan.', 'Voy a ser claro contigo, $gpequeño:pequeña; $r. Mi gente no ha vuelto a ser la misma desde que cortamos nuestro vínculo con Thorim.$b$bVolkhan no descansará hasta que él o nosotros deje de existir. Solo queremos paz, pero parece que no tenemos otro remedio que ir a la guerra.', '', 'Volkhan derrotado', '', '', '', '', '', '', '', 'Vuelve con: Heraldo de tormenta Eljrrin. Zona: Cámaras de Relámpagos.', 0),
(29861, 'esMX', '¡Lo que haga falta!', 'El heraldo de tormenta Eljrrin de las Cámaras de Relámpagos quiere que derrotes a Loken. Después, vuelve con el heraldo de tormenta Eljrrin y llévale la lengua de Loken.', 'De una forma u otra, Loken debe caer.$b$bEl honor y la gloria de su derrota te pertenecerán.$b$bVuelve aquí con su lengua viperina y gánate mi eterna gratitud.', '', '', '', '', '', '', '', '', '', 'Vuelve con: Heraldo de tormenta Eljrrin. Zona: Cámaras de Relámpagos.', 0),
(29862, 'esMX', 'Despejando el camino', 'El heraldo de tormenta Eljrrin de las Cámaras de Relámpagos quiere que mates a 3 ensalmadores Tronaforjado, 3 tácticos Tronaforjado y al general Bjarngrim.', 'Las fuerzas de Loken se preparan para la guerra. Para lo que no están preparados es para ser atacados.$b$bEs el momento de asestarles un buen golpe. Elimina al general Bjarngrim y a su ejército, ¡no vaya a ser que preparen una gran ofensiva contra toda vida en Azeroth!', '', '', '', '', '', '', '', '', '', 'Vuelve con: Heraldo de tormenta Eljrrin. Zona: Cámaras de Relámpagos.', 0),
(29863, 'esMX', 'El heraldo de tormenta Eljrrin', 'El rey Jokkum quiere que entres en las Cámaras de Relámpagos y que hables con el heraldo de tormenta Eljrrin.', 'He enviado a un emisario a las Cámaras de Relámpagos para llevar la batalla ante Loken.$b$bSin duda, necesitará apoyo dada la fuerza de los ejércitos de Loken. Préstale toda la ayuda que puedas para que podamos detener por fin al traidor.', '', '', '', '', '', '', '', '', '', '', 0),
(29864, 'esMX', 'La raíz del problema', 'La confesora Argenta Cabelloclaro quiere que mates a Svala Tumbapena.', 'Estamos trabajando duro para minimizar nuestras pérdidas frente a la máquina de guerra de la Plaga.$b$bLos vrykuls de aquí están arruinando la misión al unirse voluntariamente a las filas del Rey Exánime.$b$bTe lo ruego, valiente $gcampeón:campeona;, ¡derrota a su líder espiritual, Svala, antes de que suma a su pueblo en una sombra eterna!', '', '', '', '', '', '', 'Svala Tumbapena', '', '', 'Vuelve con: Imagen de confesora Argenta Cabelloclaro. Zona: Pináculo de Utgarde.', 0),
(29934, 'esMX', 'A Ravenholdt', 'Habla con Mostrasz en el Reducto Bermellón y vuela con él hasta la Mansión Ravenholdt. ', 'Si el huevo se encuentra en la Mansión Ravenholdt, no podemos arriesgarnos a quemarlo en un ataque devastador. Necesitaré a alguien escurridizo que se cuele allí y compruebe si tienen el huevo ahí dentro.$b$bMe refiero a ti, $n.$b$bMostrasz te ayudará a infiltrarte en el recinto. Habla con él afuera y volad juntos hasta Ravenholdt. ¡Buena suerte!', '', 'Habla con Mostrasz', '', '', '', '', '', '', '', 'Habla con: Mostrasz. Zona: Interior de la cueva, justo fuera de la Mansión Ravenholdt, Laderas de Trabalomas.', 0),
(30092, 'esMX', 'Nuestro hombre en Gilneas', 'Busca a Zazzo Dedocentella cerca de las Ruinas de la Ciudad de Gilneas, en Gilneas.', 'Si deseas unirte a mi causa y acabar con los dragones Negros que se ocultan, demuestra tu valor destruyendo a Hiram Creed. Está reuniendo un ejército en Gilneas.$B$BNo hemos podido eludir a sus defensores, pero tenemos a un hombre dentro que lo mantiene vigilado. Zazzo Dedocentella, un mago arcano muy hábil, está esperando que contactemos con él junto a la ruinas de la capital gilneana.$B$BReúnete con él y te conducirá hasta el objetivo.', '', '', '', '', '', '', '', '', '', 'Busca a: Zazzo Dedocentella. Zona: Cerca de las Ruinas de la Ciudad de Gilneas, Gilneas.', 0),
(30093, 'esMX', 'Asesinar a Creed', 'Cuélate en las Ruinas de la Ciudad de Gilneas y mata a Hiram Creed en el Distrito Militar.', 'La ciudad lleva días sumida en el caos. Hiram Creed, disfrazado de gilneano, ha infectado a la mayoría de esos perros con su propia sangre dracónica. Incluso los Renegados están teniendo problemas para deshacerse de él.$B$B¡Lo único que puede acabar con esto es un asesinato bien planeado!$B$BEl puente que tengo detrás está relativamente poco vigilado. Cuélate por la plaza de los mercaderes y dirígete al sur. Verás a Creed en el centro del Distrito Militar.$B$BTe estaré vigilando y te sacaré si hay algún problema.$B$B¡... Y los habrá, no te quepa duda!', '', '', '', '', '', '', '', '', '', 'Habla con: Zazzo Dedocentella. Zona: Noreste de la ciudad de Gilneas, ruinas de Gilneas.', 0),
(30094, 'esMX', 'El Fin de los Días', 'Habla con Nozdormu en el Fin de los Días.', 'Nozdormu, el Aspecto Bronce, ha solicitado ayuda a los campeones de la Horda. Tú eres $guno de los primeros:una de las primeras; en la lista. Puedo darte más detalles.$b$bEs poco habitual en mi maestro el solicitar la ayuda de los mortales, pero supongo que todo cambia con el tiempo... incluso el propio Aspecto del Tiempo.$b$bTe espera en el Fin de los Días, en el futuro lejano. Si así lo deseas, puedo ayudarte a viajar allí.', '', '', '', '', '', '', '', '', '', 'Habla con: Nozdormu. Zona: Fin de los Días.', 0),
(30095, 'esMX', 'El Fin de los Días', 'Habla con Nozdormu en el Fin de los Días.', 'Nozdormu, el Aspecto Bronce, ha solicitado ayuda a los campeones de la Alianza. Tú eres $guno de los primeros:una de las primeras; en la lista. Puedo darte más detalles.$b$bEs poco habitual en mi maestro el solicitar la ayuda de los mortales, pero supongo que todo cambia con el tiempo... incluso el propio Aspecto del Tiempo.$b$bTe espera en el Fin de los Días, en el futuro lejano. Si así lo deseas, puedo ayudarte a viajar allí.', '', '', '', '', '', '', '', '', '', 'Habla con: Nozdormu. Zona: Fin de los Días.', 0),
(30096, 'esMX', 'Murozond', 'Mata a Murozond.', 'Si queremos destruir a Alamuerte, necesitaremos el poder del Alma de dragón. Para obtener el Alma de dragón, tendré que llevarte de nuevo al Cataclismo, diez mil años atrás... Pero ese pasaje del tiempo está bloqueado para mí.$b$bLa criatura que nos bloquea su acceso se llama Murozond. Hay que matarlo aquí, en este futuro distorsionado, para que podamos continuar con nuestro plan de acabar con Alamuerte.$b$bPara eso estás aquí, $n.', '', '', '', '', '', '', '', '', '', 'Habla con: Nozdormu. Zona: Santuario de Dragones Bronce, el Fin de los Días.', 0),
(30097, 'esMX', 'Para que conste', 'Mata a dos de los Ecos en el Fin de los Días y deja que la vasija de Alurmi archive su información.', 'Por lo que tengo entendido, estás tratando de evitar este futuro. Si eso es verdad, debemos archivar datos de este ramal del tiempo antes de que lo perdamos definitivamente.$b$bCreemos que los elementos más valiosos e interesantes de este futuro son los poderosos "ecos" que vagan por los Santuarios de Dragones.$b$bLlévate este recipiente para silenciarlos. Una parte de sus energías quedará archivada en poder del Vuelo Bronce.', '', 'Eco archivado', '', '', '', '', '', '', '', 'Vuelve con: Alurmi. Zona: Fin de los Días.', 0),
(30098, 'esMX', 'El Pozo de la Eternidad', 'Habla con Nozdormu en el Pozo de la Eternidad.', 'Hemos de movernos con rapidez, antes de que intervenga cualquier Agente Infinito. El tiempo es precioso.$b$bAhora, te llevaré de tu futuro lejano a tu pasado lejano... la Guerra de los Ancestros. Nuestro objetivo es el Alma de dragón, un artefacto de inmenso poder... suficiente para doblegar a Alamuerte y acabar con su reinado sobre tu presente.', '', '', '', '', '', '', '', '', '', 'Habla con: Nozdormu. Zona: Pozo de la Eternidad.', 0),
(30099, 'esMX', 'En número interminable', 'Desactiva los tres portales demoníacos y, después, mata a Peroth\'arn.', 'Entre nosotros y el Alma de dragón hay una legión de demonios. Tenemos que acabar con ellos antes de proseguir.$b$bSi mis cálculos son correctos, que suelen serlo, un joven elfo de la noche llamado Illidan Tempestira debería cruzarse pronto en nuestro camino. Sin duda, será de gran ayuda a la hora de cazar demonios.$b$bAyuda a Illidan a inutilizar los portales de los demonios y, después, mata a su líder, Peroth\'arn.', '', 'Primer portal inutilizado', 'Segundo portal inutilizado', 'Tercer portal inutilizado', '', '', '', '', '', 'Habla con: Nozdormu. Zona: Cerca del Pozo de la Eternidad.', 0),
(30100, 'esMX', 'La vanagloriosa', 'Deshazte de la reina Azshara.', 'La reina Azshara y su guardia real están justo ahí delante. No podemos permitir que nuestro plan sufra ninguna interferencia, por lo que la atacaremos para impedir que tenga la posibilidad de inmiscuirse.$b$bEs altamente improbable que mates hoy a la reina Azshara; hay muy pocas líneas temporales coherentes en ese ramal. Considéralo una victoria si simplemente logras llamar su atención, aunque sea durante un tiempo.', '', 'Reina Azshara derrotada', '', '', '', '', '', '', '', 'Habla con: Nozdormu. Zona: Pozo de la Eternidad.', 0),
(30101, 'esMX', 'El camino al Alma de dragón', 'Mata a Mannoroth.', 'No puedo echar a volar y hacerme con el Alma de dragón tan fácilmente. Los dioses antiguos la protegen.$b$bPara empeorar las cosas, su escudo está reforzado por el torbellino formado por las energías Arcanas que emanan del Pozo de la Eternidad. Estas energías están gobernadas por el gran demonio Mannoroth.$b$bDistrae a Mannoroth y el vínculo entre el Alma de dragón y el pozo se romperá. Sin el poder del pozo, la defensa de los dioses antiguos se debilitará y el Alma de dragón será vulnerable.$b$bEntonces me haré con ella.', '', '', '', '', '', '', '', '', '', 'Habla con: Illidan. Zona: Pozo de la Eternidad.', 0),
(30102, 'esMX', 'La Hora del Crepúsculo', 'Habla con Thrall en la Hora del Crepúsculo.', 'No es necesario quedarse por aquí para siempre. ¿No te acuerdas? Podemos CONTROLAR EL TIEMPO. Especialmente desde que te libraste de ese tal Murozond, allá en el futuro.$b$b¿Y esa Alma de dragón que acabas de liberar? Thrall ya la tiene en tu tiempo presente. Y va a necesitar tu ayuda.$b$b¿$gListo:Lista; para partir?', '', '', '', '', '', '', '', '', '', 'Habla con: Thrall. Zona: Hora del Crepúsculo.', 0),
(30103, 'esMX', '¡Al Reposo del Dragón!', 'Escolta a Thrall para que llegue a salvo al Templo del Reposo del Dragón.', 'El Alma de dragón... Un arma con suficiente poder como para derrotar a Alamuerte. Gracias a ti, ahora se encuentra segura en nuestras manos.$b$b¡Ven! Los Aspectos nos esperan. Tenemos que llevar el Alma de dragón al Templo del Reposo del Dragón, en el centro del Cementerio de Dragones.', '', 'Acompaña a Thrall para que llegue a salvo al Reposo del Dragón', '', '', '', '', '', '', '', 'Habla con: Thrall. Zona: Hora del Crepúsculo.', 0),
(30104, 'esMX', 'Documentar los portales del tiempo', 'Mata a un demonio de la Legión, a una fámula real y al capitán Varo\'then. Luego deja que la vasija de Alurmi archive la información.', 'Tú... $n, ¿no? Nos ayudaste en la labor de archivo en el pasado. Bueno, técnicamente era el futuro, pero ya me entiendes. El tiempo es muy relativo.$b$bNecesito más información para nuestro archivo. Siempre que Nozdormu y tú no intenten sobrescribir esta franja temporal, como hicieron en el Fin de los Días, nos vendrán bien más datos.$b$bNecesito información del capitán Varo\'then, de una de las pequeñas y preciosas fámulas reales de Azshara y... mmm... Ah, ¿qué tal también de un guardia vil de esos grandes que hay al pie de aquellas escaleras?', '', 'Demonio de la Legión archivado', 'Fámula real archivada', 'Capitán Varo\'then archivado', '', '', '', '', '', 'Lleva la vasija de Alurmi a Alurmi cerca del Pozo de la Eternidad.', 0),
(30105, 'esMX', 'El profeta Crepuscular', 'Encuentra y desenmascara al profeta Crepuscular.', 'La carta dice lo siguiente:$b$b"La Hora del Crepúsculo está próxima. Thrall, el chamán del mundo, se aproxima al Reposo del Dragón con el Alma de dragón en mano, musitando una lastimera amenaza final de destrucción de nuestro glorioso maestro".$b$b"Detén a Thrall y ganaremos nuestra guerra. Te vigilaré de cerca".$b$b - El profeta Crepuscular', '', 'El profeta Crepuscular desenmascarado', '', '', '', '', '', '', '', 'Habla con: Thrall. Zona: Hora del Crepúsculo.', 0),
(30106, 'esMX', 'Ya está hecho', 'Informa de tu éxito al príncipe Wrathion en la Mansión Ravenholdt, en las Laderas de Trabalomas.', 'El príncipe Wrathion estará encantado de saber que tuviste éxito. Deberías presentarte ante él en la Mansión Ravenholdt.$B$BEl príncipe es conocido por ser extremadamente generoso con aquellos que lo ayudan. ', '', '', '', '', '', '', '', '', '', 'Informa de tu éxito a: Príncipe Wrathion. Zona: Mansión Ravenholdt, Laderas de Trabalomas.', 0),
(30107, 'esMX', 'Por un puñado de gemas', 'Obtén 333 gemas enigmáticas saqueando cúmulos de gemas de elementium de las criaturas del encuentro de banda Alma de Dragón. ', 'Las dagas que te he dado son vainas sin vida. Serán capaces de hacer grandes cosas cuando dispongan de un modo de contener el poder que tengo en mente.$B$BNecesito que me consigas gemas enigmáticas. Las facetas de estas raras piedras son como ventanas al infinito. Los secuaces del Martillo Crepuscular suelen usarlas para controlar a los elementales más poderosos.$B$BUna gran batalla arrecia alrededor del Templo del Reposo del Dragón. Consigue cúmulos de gemas de elementium de los secuaces de Alamuerte y tráeme las gemas.', '', '', '', '', '', '', '', '', '', 'Lleva las gemas enigmáticas a: príncipe Wrathion. Zona: Mansión Ravenholdt, Laderas de Trabalomas.', 0),
(30108, 'esMX', 'Nuestro hombre en Karazhan', 'Preséntate ante Zazzo Dedocentella en las ruinas justo al sureste de Karazhan.', 'Tu próximo objetivo es la dragona negra Nalice, que está enfrascada en una especie de depravación arcana bajo la torre en ruinas de Karazhan.$B$BTu misión principal consiste en acabar con ella, pero si puedes traerme un vial que contenga su sangre, podré utilizarla para aumentar el poder de las dagas que te he dado.$B$BZazzo, tu cómplice, ya se encuentra en la zona y te espera allí. Él te dará más detalles.', '', '', '', '', '', '', '', '', '', 'Preséntate ante: Zazzo Dedocentella. Zona: Ruinas justo al sureste de Karazhan.', 0),
(30109, 'esMX', 'La sangre de la traidora', 'Cuélate en el Sótano del Maestro, en las ruinas alrededor de Karazhan, derrota a Nalice y consigue un vial de sangre de dragón negra.', 'He localizado a Nalice en el Sótano del Maestro, un sótano extenso que encontrarás en las ruinas de ahí arriba.$B$BLos adoradores de la dragona están por todas partes y Nalice ha preparado unos extraños dispositivos de almacenamiento Arcano por toda la zona. Quizás podrías usarlos en tu beneficio.$B$BCuélate entre los adoradores, acaba con Nalice y consigue un vial de su sangre para Wrathion.$B$BTe estaré observando constantemente y te sacaré si te metes en algún problema. ¡Pero NO entraré contigo!', '', '', '', '', '', '', '', '', '', 'Lleva el vial a: Zazzo Dedocentella. Zona: Karazhan, Paso de la Muerte.', 0),
(30112, 'esMX', 'Ajuste de cuentas', 'La forestal oscura Marrah quiere que mates al príncipe Keleseth en la Fortaleza de Utgarde.', 'Las fuerzas de Utgarde se organizan bajo la tutela del príncipe Kelesath, un embajador San\'layn de la Plaga.$B$BNo podemos permitir que los vrykuls se beneficien por más tiempo de sus consejos. Siléncialo.', '', '', '', '', '', '', 'Keleseth', '', '', 'Vuelve con: Forestal oscura Marrah. Zona: Interior de la Fortaleza de Utgarde.', 0),
(30113, 'esMX', 'Victoria en las profundidades', 'Lleva el vial de sangre de dragón conservada, junto con tus dagas Miedo y Venganza, a Wrathion en la Mansión Ravenholdt en las Laderas de Trabalomas.', '<Zazzo realiza un encantamiento en el vial de sangre y, después, te lo devuelve con rapidez, como si pensase que pudiera ser tóxico.>$B$B¡Hecho! Será mejor que le lleves esto a Wrathion lo antes posible, junto con esas dos dagas tuyas.$B$BNo sé qué planea hacer con todo esto. Entre tú y yo, a veces ese niño dragón me da escalofríos. ¡Buena suerte!', '', '', '', '', '', '', '', '', '', 'Lleva el vial de sangre de dragón conservada y tus dagas Miedo y Venganza a: Wrathion. Zona: Mansión Ravenholdt, Laderas de Trabalomas.', 0),
(30116, 'esMX', 'Afílate los colmillos', 'Recoge 60 cúmulos de gemas de elementium de las criaturas del encuentro de banda Alma de Dragón.', '¿Entiendes por qué he hecho que asesines a los dragones, pero perdones a los mortales? No es su culpa. Deben buscar su propio destino, libres de la interferencia de mi raza.$B$BNos acercamos al final de nuestra misión y también es el momento de buscar nuestro propio destino. Puedo seguir mejorando tus armas, pero no bastará con recoger gemas enigmáticas. Para mi trabajo necesitaré cúmulos completos. Consíguelos de los secuaces de mi padre...', '', '', '', '', '', '', '', '', '', 'Lleva los cúmulos a: Wrathion. Zona: Mansión Ravenholdt, Laderas de Trabalomas.', 0),
(30118, 'esMX', 'Parricidio', 'Acaba con Alamuerte y hazte con un fragmento de su mandíbula. ', 'Tu próximo objetivo ha cobrado las vidas de todos mis otros asesinos. Necesito que mates a mi propio padre.$B$BDebes acabar con Alamuerte.$B$BNo tenemos tiempo. Su locura ya corrompió al resto de mi especie y su oscuridad consumirá el mundo si no lo detenemos.$B$BSi milagrosamente tienes éxito y puedes traerme una parte de su ser, tal vez un fragmento de la armadura que utiliza para enmascarar su verdadera naturaleza caótica, te daré una recompensa sin igual. ', '', '', '', '', '', '', '', '', '', 'Lleva el fragmento de la mandíbula de Alamuerte, junto con tus dagas, La Durmiente y La Soñadora, a: Wrathion. Zona: Mansión Ravenholdt, Laderas de Trabalomas.', 0),
(30120, 'esMX', 'Limpiar Drak\'Tharon', 'Drakuru quiere que uses el elixir de Drakuru en su pedestal dentro de Drak\'Tharon. Para usar el elixir de Drakuru ahí vas a necesitar 5 mojos de resistencia.', '¡Eh, colega, eh\'tás aquí! ¡Eh\'tá bien, colega!$b$bDrak\'Tharon pronto eh\'tará limpio de esos no mueh\'tos locos y volverá a su noble propósito. A cambio de tu ayuda, ¡los tesoros más valiosos de la foh\'taleza serán tuyos, colega!$b$bCuando llegues a lo alto, me tienes que invocar y ejecutaré el ritual.$b$bPor deh\'gracia, pa\' invocah\'me hay un precio a cambio. Tienes que recoger el mojo de los supervivientes.', '', '', '', '', '', '', '', '', '', '', 0),
(30173, 'esMX', '¡Cerdos de guerra!', '', '', '', '', '', '', '', '', '', '', '', 'test2 test2 test2 $o1a $o1o', 19865);
